void OPPROTO op_POWER_sllq (void)

{

    uint32_t msk = -1;



    msk = msk << (T1 & 0x1FUL);

    if (T1 & 0x20UL)

        msk = ~msk;

    T1 &= 0x1FUL;

    T0 = (T0 << T1) & msk;

    T0 |= env->spr[SPR_MQ] & ~msk;

    RETURN();

}

void OPPROTO op_POWER_sraq (void)

{

    env->spr[SPR_MQ] = rotl32(T0, 32 - (T1 & 0x1FUL));

    if (T1 & 0x20UL)

        T0 = -1L;

    else

        T0 = Ts0 >> T1;

    RETURN();

}

void OPPROTO op_POWER_slq (void)

{

    uint32_t msk = -1, tmp;



    msk = msk << (T1 & 0x1FUL);

    if (T1 & 0x20UL)

        msk = ~msk;

    T1 &= 0x1FUL;

    tmp = rotl32(T0, T1);

    T0 = tmp & msk;

    env->spr[SPR_MQ] = tmp;

    RETURN();

}

