static void rv30_loop_filter(RV34DecContext *r, int row)

{

    MpegEncContext *s = &r->s;

    int mb_pos, mb_x;

    int i, j, k;

    uint8_t *Y, *C;

    int loc_lim, cur_lim, left_lim = 0, top_lim = 0;



    mb_pos = row * s->mb_stride;

    for(mb_x = 0; mb_x < s->mb_width; mb_x++, mb_pos++){

        int mbtype = s->current_picture_ptr->mb_type[mb_pos];

        if(IS_INTRA(mbtype) || IS_SEPARATE_DC(mbtype))

            r->deblock_coefs[mb_pos] = 0xFFFF;

        if(IS_INTRA(mbtype))

            r->cbp_chroma[mb_pos] = 0xFF;

    }



    /* all vertical edges are filtered first

     * and horizontal edges are filtered on the next iteration

     */

    mb_pos = row * s->mb_stride;

    for(mb_x = 0; mb_x < s->mb_width; mb_x++, mb_pos++){

        cur_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos]];

        if(mb_x)

            left_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos - 1]];

        for(j = 0; j < 16; j += 4){

            Y = s->current_picture_ptr->f.data[0] + mb_x*16 + (row*16 + j) * s->linesize + 4 * !mb_x;

            for(i = !mb_x; i < 4; i++, Y += 4){

                int ij = i + j;

                loc_lim = 0;

                if(r->deblock_coefs[mb_pos] & (1 << ij))

                    loc_lim = cur_lim;

                else if(!i && r->deblock_coefs[mb_pos - 1] & (1 << (ij + 3)))

                    loc_lim = left_lim;

                else if( i && r->deblock_coefs[mb_pos]     & (1 << (ij - 1)))

                    loc_lim = cur_lim;

                if(loc_lim)

                    rv30_weak_loop_filter(Y, 1, s->linesize, loc_lim);

            }

        }

        for(k = 0; k < 2; k++){

            int cur_cbp, left_cbp = 0;

            cur_cbp = (r->cbp_chroma[mb_pos] >> (k*4)) & 0xF;

            if(mb_x)

                left_cbp = (r->cbp_chroma[mb_pos - 1] >> (k*4)) & 0xF;

            for(j = 0; j < 8; j += 4){

                C = s->current_picture_ptr->f.data[k + 1] + mb_x*8 + (row*8 + j) * s->uvlinesize + 4 * !mb_x;

                for(i = !mb_x; i < 2; i++, C += 4){

                    int ij = i + (j >> 1);

                    loc_lim = 0;

                    if (cur_cbp & (1 << ij))

                        loc_lim = cur_lim;

                    else if(!i && left_cbp & (1 << (ij + 1)))

                        loc_lim = left_lim;

                    else if( i && cur_cbp  & (1 << (ij - 1)))

                        loc_lim = cur_lim;

                    if(loc_lim)

                        rv30_weak_loop_filter(C, 1, s->uvlinesize, loc_lim);

                }

            }

        }

    }

    mb_pos = row * s->mb_stride;

    for(mb_x = 0; mb_x < s->mb_width; mb_x++, mb_pos++){

        cur_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos]];

        if(row)

            top_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos - s->mb_stride]];

        for(j = 4*!row; j < 16; j += 4){

            Y = s->current_picture_ptr->f.data[0] + mb_x*16 + (row*16 + j) * s->linesize;

            for(i = 0; i < 4; i++, Y += 4){

                int ij = i + j;

                loc_lim = 0;

                if(r->deblock_coefs[mb_pos] & (1 << ij))

                    loc_lim = cur_lim;

                else if(!j && r->deblock_coefs[mb_pos - s->mb_stride] & (1 << (ij + 12)))

                    loc_lim = top_lim;

                else if( j && r->deblock_coefs[mb_pos]                & (1 << (ij - 4)))

                    loc_lim = cur_lim;

                if(loc_lim)

                    rv30_weak_loop_filter(Y, s->linesize, 1, loc_lim);

            }

        }

        for(k = 0; k < 2; k++){

            int cur_cbp, top_cbp = 0;

            cur_cbp = (r->cbp_chroma[mb_pos] >> (k*4)) & 0xF;

            if(row)

                top_cbp = (r->cbp_chroma[mb_pos - s->mb_stride] >> (k*4)) & 0xF;

            for(j = 4*!row; j < 8; j += 4){

                C = s->current_picture_ptr->f.data[k+1] + mb_x*8 + (row*8 + j) * s->uvlinesize;

                for(i = 0; i < 2; i++, C += 4){

                    int ij = i + (j >> 1);

                    loc_lim = 0;

                    if (r->cbp_chroma[mb_pos] & (1 << ij))

                        loc_lim = cur_lim;

                    else if(!j && top_cbp & (1 << (ij + 2)))

                        loc_lim = top_lim;

                    else if( j && cur_cbp & (1 << (ij - 2)))

                        loc_lim = cur_lim;

                    if(loc_lim)

                        rv30_weak_loop_filter(C, s->uvlinesize, 1, loc_lim);

                }

            }

        }

    }

}

static int rv30_decode_mb_info(RV34DecContext *r)

{

    static const int rv30_p_types[6] = { RV34_MB_SKIP, RV34_MB_P_16x16, RV34_MB_P_8x8, -1, RV34_MB_TYPE_INTRA, RV34_MB_TYPE_INTRA16x16 };

    static const int rv30_b_types[6] = { RV34_MB_SKIP, RV34_MB_B_DIRECT, RV34_MB_B_FORWARD, RV34_MB_B_BACKWARD, RV34_MB_TYPE_INTRA, RV34_MB_TYPE_INTRA16x16 };

    MpegEncContext *s = &r->s;

    GetBitContext *gb = &s->gb;

    int code = svq3_get_ue_golomb(gb);



    if(code > 11){

        av_log(s->avctx, AV_LOG_ERROR, "Incorrect MB type code\n");

        return -1;

    }

    if(code > 5){

        av_log(s->avctx, AV_LOG_ERROR, "dquant needed\n");

        code -= 6;

    }

    if(s->pict_type != AV_PICTURE_TYPE_B)

        return rv30_p_types[code];

    else

        return rv30_b_types[code];

}

static int rv34_set_deblock_coef(RV34DecContext *r)

{

    MpegEncContext *s = &r->s;

    int mvmask = 0, i, j;

    int midx = s->mb_x * 2 + s->mb_y * 2 * s->b8_stride;

    int16_t (*motion_val)[2] = s->current_picture_ptr->motion_val[0][midx];

    if(s->pict_type == FF_I_TYPE)

        return 0;

    for(j = 0; j < 16; j += 8){

        for(i = 0; i < 2; i++){

            if(is_mv_diff_gt_3(motion_val + i, 1))

                mvmask |= 0x11 << (j + i*2);

            if(is_mv_diff_gt_3(motion_val + i, s->b8_stride))

                mvmask |= 0x03 << (j + i*2);

        }

        motion_val += s->b8_stride;

    }

    return mvmask;

}

static void vc1_mc_4mv_luma(VC1Context *v, int n, int dir)

{

    MpegEncContext *s = &v->s;

    DSPContext *dsp = &v->s.dsp;

    uint8_t *srcY;

    int dxy, mx, my, src_x, src_y;

    int off;

    int fieldmv = (v->fcm == ILACE_FRAME) ? v->blk_mv_type[s->block_index[n]] : 0;

    int v_edge_pos = s->v_edge_pos >> v->field_mode;



    if (!v->field_mode && !v->s.last_picture.f.data[0])

        return;



    mx = s->mv[dir][n][0];

    my = s->mv[dir][n][1];



    if (!dir) {

        if (v->field_mode) {

            if ((v->cur_field_type != v->ref_field_type[dir]) && v->cur_field_type)

                srcY = s->current_picture.f.data[0];

            else

                srcY = s->last_picture.f.data[0];

        } else

            srcY = s->last_picture.f.data[0];

    } else

        srcY = s->next_picture.f.data[0];



    if (v->field_mode) {

        if (v->cur_field_type != v->ref_field_type[dir])

            my = my - 2 + 4 * v->cur_field_type;

    }



    if (s->pict_type == AV_PICTURE_TYPE_P && n == 3 && v->field_mode) {

        int same_count = 0, opp_count = 0, k;

        int chosen_mv[2][4][2], f;

        int tx, ty;

        for (k = 0; k < 4; k++) {

            f = v->mv_f[0][s->block_index[k] + v->blocks_off];

            chosen_mv[f][f ? opp_count : same_count][0] = s->mv[0][k][0];

            chosen_mv[f][f ? opp_count : same_count][1] = s->mv[0][k][1];

            opp_count  += f;

            same_count += 1 - f;

        }

        f = opp_count > same_count;

        switch (f ? opp_count : same_count) {

        case 4:

            tx = median4(chosen_mv[f][0][0], chosen_mv[f][1][0],

                         chosen_mv[f][2][0], chosen_mv[f][3][0]);

            ty = median4(chosen_mv[f][0][1], chosen_mv[f][1][1],

                         chosen_mv[f][2][1], chosen_mv[f][3][1]);

            break;

        case 3:

            tx = mid_pred(chosen_mv[f][0][0], chosen_mv[f][1][0], chosen_mv[f][2][0]);

            ty = mid_pred(chosen_mv[f][0][1], chosen_mv[f][1][1], chosen_mv[f][2][1]);

            break;

        case 2:

            tx = (chosen_mv[f][0][0] + chosen_mv[f][1][0]) / 2;

            ty = (chosen_mv[f][0][1] + chosen_mv[f][1][1]) / 2;

            break;

        }

        s->current_picture.f.motion_val[1][s->block_index[0] + v->blocks_off][0] = tx;

        s->current_picture.f.motion_val[1][s->block_index[0] + v->blocks_off][1] = ty;

        for (k = 0; k < 4; k++)

            v->mv_f[1][s->block_index[k] + v->blocks_off] = f;

    }



    if (v->fcm == ILACE_FRAME) {  // not sure if needed for other types of picture

        int qx, qy;

        int width  = s->avctx->coded_width;

        int height = s->avctx->coded_height >> 1;

        qx = (s->mb_x * 16) + (mx >> 2);

        qy = (s->mb_y *  8) + (my >> 3);



        if (qx < -17)

            mx -= 4 * (qx + 17);

        else if (qx > width)

            mx -= 4 * (qx - width);

        if (qy < -18)

            my -= 8 * (qy + 18);

        else if (qy > height + 1)

            my -= 8 * (qy - height - 1);

    }



    if ((v->fcm == ILACE_FRAME) && fieldmv)

        off = ((n > 1) ? s->linesize : 0) + (n & 1) * 8;

    else

        off = s->linesize * 4 * (n & 2) + (n & 1) * 8;

    if (v->field_mode && v->cur_field_type)

        off += s->current_picture_ptr->f.linesize[0];



    src_x = s->mb_x * 16 + (n & 1) * 8 + (mx >> 2);

    if (!fieldmv)

        src_y = s->mb_y * 16 + (n & 2) * 4 + (my >> 2);

    else

        src_y = s->mb_y * 16 + ((n > 1) ? 1 : 0) + (my >> 2);



    if (v->profile != PROFILE_ADVANCED) {

        src_x = av_clip(src_x, -16, s->mb_width  * 16);

        src_y = av_clip(src_y, -16, s->mb_height * 16);

    } else {

        src_x = av_clip(src_x, -17, s->avctx->coded_width);

        if (v->fcm == ILACE_FRAME) {

            if (src_y & 1)

                src_y = av_clip(src_y, -17, s->avctx->coded_height + 1);

            else

                src_y = av_clip(src_y, -18, s->avctx->coded_height);

        } else {

            src_y = av_clip(src_y, -18, s->avctx->coded_height + 1);

        }

    }



    srcY += src_y * s->linesize + src_x;

    if (v->field_mode && v->ref_field_type[dir])

        srcY += s->current_picture_ptr->f.linesize[0];



    if (fieldmv && !(src_y & 1))

        v_edge_pos--;

    if (fieldmv && (src_y & 1) && src_y < 4)

        src_y--;

    if (v->rangeredfrm || (v->mv_mode == MV_PMODE_INTENSITY_COMP)

        || s->h_edge_pos < 13 || v_edge_pos < 23

        || (unsigned)(src_x - s->mspel) > s->h_edge_pos - (mx & 3) - 8 - s->mspel * 2

        || (unsigned)(src_y - (s->mspel << fieldmv)) > v_edge_pos - (my & 3) - ((8 + s->mspel * 2) << fieldmv)) {

        srcY -= s->mspel * (1 + (s->linesize << fieldmv));

        /* check emulate edge stride and offset */

        s->dsp.emulated_edge_mc(s->edge_emu_buffer, srcY, s->linesize,

                                9 + s->mspel * 2, (9 + s->mspel * 2) << fieldmv,

                                src_x - s->mspel, src_y - (s->mspel << fieldmv),

                                s->h_edge_pos, v_edge_pos);

        srcY = s->edge_emu_buffer;

        /* if we deal with range reduction we need to scale source blocks */

        if (v->rangeredfrm) {

            int i, j;

            uint8_t *src;



            src = srcY;

            for (j = 0; j < 9 + s->mspel * 2; j++) {

                for (i = 0; i < 9 + s->mspel * 2; i++)

                    src[i] = ((src[i] - 128) >> 1) + 128;

                src += s->linesize << fieldmv;

            }

        }

        /* if we deal with intensity compensation we need to scale source blocks */

        if (v->mv_mode == MV_PMODE_INTENSITY_COMP) {

            int i, j;

            uint8_t *src;



            src = srcY;

            for (j = 0; j < 9 + s->mspel * 2; j++) {

                for (i = 0; i < 9 + s->mspel * 2; i++)

                    src[i] = v->luty[src[i]];

                src += s->linesize << fieldmv;

            }

        }

        srcY += s->mspel * (1 + (s->linesize << fieldmv));

    }



    if (s->mspel) {

        dxy = ((my & 3) << 2) | (mx & 3);

        v->vc1dsp.put_vc1_mspel_pixels_tab[dxy](s->dest[0] + off, srcY, s->linesize << fieldmv, v->rnd);

    } else { // hpel mc - always used for luma

        dxy = (my & 2) | ((mx & 2) >> 1);

        if (!v->rnd)

            dsp->put_pixels_tab[1][dxy](s->dest[0] + off, srcY, s->linesize, 8);

        else

            dsp->put_no_rnd_pixels_tab[1][dxy](s->dest[0] + off, srcY, s->linesize, 8);

    }

}

