static int applehttp_open(URLContext *h, const char *uri, int flags)

{

    AppleHTTPContext *s;

    int ret, i;

    const char *nested_url;



    if (flags & AVIO_FLAG_WRITE)

        return AVERROR(ENOSYS);



    s = av_mallocz(sizeof(AppleHTTPContext));

    if (!s)

        return AVERROR(ENOMEM);

    h->priv_data = s;

    h->is_streamed = 1;



    if (av_strstart(uri, "applehttp+", &nested_url)) {

        av_strlcpy(s->playlisturl, nested_url, sizeof(s->playlisturl));

    } else if (av_strstart(uri, "applehttp://", &nested_url)) {

        av_strlcpy(s->playlisturl, "http://", sizeof(s->playlisturl));

        av_strlcat(s->playlisturl, nested_url, sizeof(s->playlisturl));

    } else {

        av_log(h, AV_LOG_ERROR, "Unsupported url %s\n", uri);

        ret = AVERROR(EINVAL);

        goto fail;

    }



    if ((ret = parse_playlist(h, s->playlisturl)) < 0)

        goto fail;



    if (s->n_segments == 0 && s->n_variants > 0) {

        int max_bandwidth = 0, maxvar = -1;

        for (i = 0; i < s->n_variants; i++) {

            if (s->variants[i]->bandwidth > max_bandwidth || i == 0) {

                max_bandwidth = s->variants[i]->bandwidth;

                maxvar = i;

            }

        }

        av_strlcpy(s->playlisturl, s->variants[maxvar]->url,

                   sizeof(s->playlisturl));

        if ((ret = parse_playlist(h, s->playlisturl)) < 0)

            goto fail;

    }



    if (s->n_segments == 0) {

        av_log(h, AV_LOG_WARNING, "Empty playlist\n");

        ret = AVERROR(EIO);

        goto fail;

    }

    s->cur_seq_no = s->start_seq_no;

    if (!s->finished && s->n_segments >= 3)

        s->cur_seq_no = s->start_seq_no + s->n_segments - 3;



    return 0;



fail:

    av_free(s);

    return ret;

}

static av_cold int peak_init_writer(AVFormatContext *s)

{

    WAVMuxContext *wav = s->priv_data;

    AVCodecContext *enc = s->streams[0]->codec;



    if (enc->codec_id != AV_CODEC_ID_PCM_S8 &&

        enc->codec_id != AV_CODEC_ID_PCM_S16LE &&

        enc->codec_id != AV_CODEC_ID_PCM_U8 &&

        enc->codec_id != AV_CODEC_ID_PCM_U16LE) {

        av_log(s, AV_LOG_ERROR, "%s codec not supported for Peak Chunk\n",

               s->streams[0]->codec->codec ? s->streams[0]->codec->codec->name : "NONE");

        return -1;

    }



    wav->peak_bps = av_get_bits_per_sample(enc->codec_id) / 8;



    if (wav->peak_bps == 1 && wav->peak_format == PEAK_FORMAT_UINT16) {

        av_log(s, AV_LOG_ERROR,

               "Writing 16 bit peak for 8 bit audio does not make sense\n");

        return AVERROR(EINVAL);

    }



    wav->peak_maxpos = av_mallocz(enc->channels * sizeof(*wav->peak_maxpos));

    if (!wav->peak_maxpos)

        goto nomem;

    wav->peak_maxneg = av_mallocz(enc->channels * sizeof(*wav->peak_maxneg));

    if (!wav->peak_maxneg)

        goto nomem;



    wav->peak_output = av_malloc(PEAK_BUFFER_SIZE);

    if (!wav->peak_output)

        goto nomem;



    wav->peak_outbuf_size = PEAK_BUFFER_SIZE;



    return 0;



nomem:

    av_log(s, AV_LOG_ERROR, "Out of memory\n");

    peak_free_buffers(s);

    return AVERROR(ENOMEM);

}

static av_cold int g726_decode_init(AVCodecContext *avctx)

{

    G726Context* c = avctx->priv_data;



    if (avctx->sample_rate <= 0) {

        av_log(avctx, AV_LOG_ERROR, "Samplerate is invalid\n");

        return -1;

    }



    if(avctx->channels != 1){

        av_log(avctx, AV_LOG_ERROR, "Only mono is supported\n");

        return -1;

    }



    c->code_size = avctx->bits_per_coded_sample;

    if (c->code_size < 2 || c->code_size > 5) {

        av_log(avctx, AV_LOG_ERROR, "Invalid number of bits %d\n", c->code_size);

        return AVERROR(EINVAL);

    }

    g726_reset(c, c->code_size - 2);



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;



    return 0;

}

static int ftp_open(URLContext *h, const char *url, int flags)

{

    char proto[10], path[MAX_URL_SIZE];

    int err;

    FTPContext *s = h->priv_data;



    av_dlog(h, "ftp protocol open\n");



    s->state = DISCONNECTED;

    s->filesize = -1;

    s->position = 0;



    av_url_split(proto, sizeof(proto),

                 s->credencials, sizeof(s->credencials),

                 s->hostname, sizeof(s->hostname),

                 &s->server_control_port,

                 path, sizeof(path),

                 url);



    if (s->server_control_port < 0 || s->server_control_port > 65535)

        s->server_control_port = 21;



    if ((err = ftp_connect_control_connection(h)) < 0)

        goto fail;



    if ((err = ftp_current_dir(s)) < 0)

        goto fail;

    av_strlcat(s->path, path, sizeof(s->path));



    if (ftp_restart(s, 0) < 0) {

        h->is_streamed = 1;

    } else {

        if (ftp_file_size(s) < 0 && flags & AVIO_FLAG_READ)

            h->is_streamed = 1;

        if (s->write_seekable != 1 && flags & AVIO_FLAG_WRITE)

            h->is_streamed = 1;

    }



    return 0;



  fail:

    av_log(h, AV_LOG_ERROR, "FTP open failed\n");

    ffurl_closep(&s->conn_control);

    ffurl_closep(&s->conn_data);

    return err;

}

int ff_frame_thread_init(AVCodecContext *avctx)

{

    int thread_count = avctx->thread_count;

    const AVCodec *codec = avctx->codec;

    AVCodecContext *src = avctx;

    FrameThreadContext *fctx;

    int i, err = 0;



#if HAVE_W32THREADS

    w32thread_init();

#endif



    if (!thread_count) {

        int nb_cpus = av_cpu_count();

        av_log(avctx, AV_LOG_DEBUG, "detected %d logical cores\n", nb_cpus);

        // use number of cores + 1 as thread count if there is more than one

        if (nb_cpus > 1)

            thread_count = avctx->thread_count = FFMIN(nb_cpus + 1, MAX_AUTO_THREADS);

        else

            thread_count = avctx->thread_count = 1;

    }



    if (thread_count <= 1) {

        avctx->active_thread_type = 0;

        return 0;

    }



    avctx->internal->thread_ctx = fctx = av_mallocz(sizeof(FrameThreadContext));



    fctx->threads = av_mallocz(sizeof(PerThreadContext) * thread_count);

    pthread_mutex_init(&fctx->buffer_mutex, NULL);

    fctx->delaying = 1;



    for (i = 0; i < thread_count; i++) {

        AVCodecContext *copy = av_malloc(sizeof(AVCodecContext));

        PerThreadContext *p  = &fctx->threads[i];



        pthread_mutex_init(&p->mutex, NULL);

        pthread_mutex_init(&p->progress_mutex, NULL);

        pthread_cond_init(&p->input_cond, NULL);

        pthread_cond_init(&p->progress_cond, NULL);

        pthread_cond_init(&p->output_cond, NULL);



        p->frame = av_frame_alloc();

        if (!p->frame) {


            err = AVERROR(ENOMEM);

            goto error;

        }



        p->parent = fctx;

        p->avctx  = copy;



        if (!copy) {

            err = AVERROR(ENOMEM);

            goto error;

        }



        *copy = *src;



        copy->internal = av_malloc(sizeof(AVCodecInternal));

        if (!copy->internal) {

            err = AVERROR(ENOMEM);

            goto error;

        }

        *copy->internal = *src->internal;

        copy->internal->thread_ctx = p;

        copy->internal->pkt = &p->avpkt;



        if (!i) {

            src = copy;



            if (codec->init)

                err = codec->init(copy);



            update_context_from_thread(avctx, copy, 1);

        } else {

            copy->priv_data = av_malloc(codec->priv_data_size);

            if (!copy->priv_data) {

                err = AVERROR(ENOMEM);

                goto error;

            }

            memcpy(copy->priv_data, src->priv_data, codec->priv_data_size);

            copy->internal->is_copy = 1;



            if (codec->init_thread_copy)

                err = codec->init_thread_copy(copy);

        }



        if (err) goto error;



        if (!pthread_create(&p->thread, NULL, frame_worker_thread, p))

            p->thread_init = 1;

    }



    return 0;



error:

    ff_frame_thread_free(avctx, i+1);



    return err;

}

int ff_slice_thread_init(AVCodecContext *avctx)

{

    int i;

    SliceThreadContext *c;

    int thread_count = avctx->thread_count;



#if HAVE_W32THREADS

    w32thread_init();

#endif



    // We cannot do this in the encoder init as the threads are created before

    if (av_codec_is_encoder(avctx->codec) &&

        avctx->codec_id == AV_CODEC_ID_MPEG1VIDEO &&

        avctx->height > 2800)

        thread_count = avctx->thread_count = 1;



    if (!thread_count) {

        int nb_cpus = av_cpu_count();

        if  (avctx->height)

            nb_cpus = FFMIN(nb_cpus, (avctx->height+15)/16);

        // use number of cores + 1 as thread count if there is more than one

        if (nb_cpus > 1)

            thread_count = avctx->thread_count = FFMIN(nb_cpus + 1, MAX_AUTO_THREADS);

        else

            thread_count = avctx->thread_count = 1;

    }



    if (thread_count <= 1) {

        avctx->active_thread_type = 0;

        return 0;

    }



    c = av_mallocz(sizeof(SliceThreadContext));

    if (!c)

        return -1;



    c->workers = av_mallocz_array(thread_count, sizeof(pthread_t));

    if (!c->workers) {

        av_free(c);

        return -1;

    }



    avctx->internal->thread_ctx = c;

    c->current_job = 0;

    c->job_count = 0;

    c->job_size = 0;

    c->done = 0;

    pthread_cond_init(&c->current_job_cond, NULL);

    pthread_cond_init(&c->last_job_cond, NULL);

    pthread_mutex_init(&c->current_job_lock, NULL);

    pthread_mutex_lock(&c->current_job_lock);

    for (i=0; i<thread_count; i++) {

        if(pthread_create(&c->workers[i], NULL, worker, avctx)) {

           avctx->thread_count = i;

           pthread_mutex_unlock(&c->current_job_lock);

           ff_thread_free(avctx);

           return -1;

        }

    }



    thread_park_workers(c, thread_count);



    avctx->execute = thread_execute;

    avctx->execute2 = thread_execute2;

    return 0;

}

static int frame_thread_init(AVCodecContext *avctx)

{

    int thread_count = avctx->thread_count;

    AVCodec *codec = avctx->codec;

    AVCodecContext *src = avctx;

    FrameThreadContext *fctx;

    int i, err = 0;



    if (!thread_count) {

        int nb_cpus = get_logical_cpus(avctx);

        // use number of cores + 1 as thread count if there is motre than one

        if (nb_cpus > 1)

            thread_count = avctx->thread_count = nb_cpus + 1;

    }



    if (thread_count <= 1) {

        avctx->active_thread_type = 0;

        return 0;

    }



    avctx->thread_opaque = fctx = av_mallocz(sizeof(FrameThreadContext));



    fctx->threads = av_mallocz(sizeof(PerThreadContext) * thread_count);

    pthread_mutex_init(&fctx->buffer_mutex, NULL);

    fctx->delaying = 1;



    for (i = 0; i < thread_count; i++) {

        AVCodecContext *copy = av_malloc(sizeof(AVCodecContext));

        PerThreadContext *p  = &fctx->threads[i];



        pthread_mutex_init(&p->mutex, NULL);

        pthread_mutex_init(&p->progress_mutex, NULL);

        pthread_cond_init(&p->input_cond, NULL);

        pthread_cond_init(&p->progress_cond, NULL);

        pthread_cond_init(&p->output_cond, NULL);



        p->parent = fctx;

        p->avctx  = copy;



        if (!copy) {

            err = AVERROR(ENOMEM);

            goto error;

        }



        *copy = *src;

        copy->thread_opaque = p;

        copy->pkt = &p->avpkt;



        if (!i) {

            src = copy;



            if (codec->init)

                err = codec->init(copy);



            update_context_from_thread(avctx, copy, 1);

        } else {

            copy->priv_data = av_malloc(codec->priv_data_size);

            if (!copy->priv_data) {

                err = AVERROR(ENOMEM);

                goto error;

            }

            memcpy(copy->priv_data, src->priv_data, codec->priv_data_size);

            copy->internal = av_malloc(sizeof(AVCodecInternal));

            if (!copy->internal) {

                err = AVERROR(ENOMEM);

                goto error;

            }

            *(copy->internal) = *(src->internal);

            copy->internal->is_copy = 1;



            if (codec->init_thread_copy)

                err = codec->init_thread_copy(copy);

        }



        if (err) goto error;



        if (!pthread_create(&p->thread, NULL, frame_worker_thread, p))

            p->thread_init = 1;

    }



    return 0;



error:

    frame_thread_free(avctx, i+1);



    return err;

}

int ffv1_init_slice_state(FFV1Context *f, FFV1Context *fs)

{

    int j;



    fs->plane_count  = f->plane_count;

    fs->transparency = f->transparency;

    for (j = 0; j < f->plane_count; j++) {

        PlaneContext *const p = &fs->plane[j];



        if (fs->ac) {

            if (!p->state)

                p->state = av_malloc(CONTEXT_SIZE * p->context_count *

                                     sizeof(uint8_t));

            if (!p->state)

                return AVERROR(ENOMEM);

        } else {

            if (!p->vlc_state)

                p->vlc_state = av_malloc(p->context_count * sizeof(VlcState));

            if (!p->vlc_state)

                return AVERROR(ENOMEM);

        }

    }



    if (fs->ac > 1) {

        //FIXME only redo if state_transition changed

        for (j = 1; j < 256; j++) {

            fs->c.one_state[j]        = f->state_transition[j];

            fs->c.zero_state[256 - j] = 256 - fs->c.one_state[j];

        }

    }



    return 0;

}

static int stdio_fclose(void *opaque)

{

    QEMUFileStdio *s = opaque;

    int ret = 0;



    if (qemu_file_is_writable(s->file)) {

        int fd = fileno(s->stdio_file);

        struct stat st;



        ret = fstat(fd, &st);

        if (ret == 0 && S_ISREG(st.st_mode)) {

            /*

             * If the file handle is a regular file make sure the

             * data is flushed to disk before signaling success.

             */

            ret = fsync(fd);

            if (ret != 0) {

                ret = -errno;

                return ret;

            }

        }

    }

    if (fclose(s->stdio_file) == EOF) {

        ret = -errno;

    }

    g_free(s);

    return ret;

}

int qemu_create_pidfile(const char *filename)

{

    char buffer[128];

    int len;

    int fd;



    fd = qemu_open(filename, O_RDWR | O_CREAT, 0600);

    if (fd == -1) {

        return -1;

    }

    if (lockf(fd, F_TLOCK, 0) == -1) {

        close(fd);

        return -1;

    }

    len = snprintf(buffer, sizeof(buffer), FMT_pid "\n", getpid());

    if (write(fd, buffer, len) != len) {

        close(fd);

        return -1;

    }



    close(fd);

    return 0;

}

static int floppy_probe_device(const char *filename)

{

    int fd, ret;

    int prio = 0;

    struct floppy_struct fdparam;

    struct stat st;



    if (strstart(filename, "/dev/fd", NULL))

        prio = 50;



    fd = open(filename, O_RDONLY | O_NONBLOCK);

    if (fd < 0) {

        goto out;

    }

    ret = fstat(fd, &st);

    if (ret == -1 || !S_ISBLK(st.st_mode)) {

        goto outc;

    }



    /* Attempt to detect via a floppy specific ioctl */

    ret = ioctl(fd, FDGETPRM, &fdparam);

    if (ret >= 0)

        prio = 100;



outc:

    close(fd);

out:

    return prio;

}

static int cdrom_probe_device(const char *filename)

{

    int fd, ret;

    int prio = 0;



    if (strstart(filename, "/dev/cd", NULL))

        prio = 50;



    fd = open(filename, O_RDONLY | O_NONBLOCK);

    if (fd < 0) {

        goto out;

    }



    /* Attempt to detect via a CDROM specific ioctl */

    ret = ioctl(fd, CDROM_DRIVE_STATUS, CDSL_CURRENT);

    if (ret >= 0)

        prio = 100;



    close(fd);

out:

    return prio;

}

static void sun4c_hw_init(const struct hwdef *hwdef, ram_addr_t RAM_size,

                          const char *boot_device,

                          DisplayState *ds, const char *kernel_filename,

                          const char *kernel_cmdline,

                          const char *initrd_filename, const char *cpu_model)

{

    CPUState *env;

    unsigned int i;

    void *iommu, *espdma, *ledma, *main_esp, *nvram;

    qemu_irq *cpu_irqs, *slavio_irq, *espdma_irq, *ledma_irq;

    qemu_irq *esp_reset, *le_reset;

    qemu_irq *fdc_tc;

    unsigned long prom_offset, kernel_size;

    int ret;

    char buf[1024];

    BlockDriverState *fd[MAX_FD];

    int drive_index;

    void *fw_cfg;



    /* init CPU */

    if (!cpu_model)

        cpu_model = hwdef->default_cpu_model;



    env = cpu_init(cpu_model);

    if (!env) {

        fprintf(stderr, "qemu: Unable to find Sparc CPU definition\n");

        exit(1);

    }



    cpu_sparc_set_id(env, 0);



    qemu_register_reset(main_cpu_reset, env);

    cpu_irqs = qemu_allocate_irqs(cpu_set_irq, env, MAX_PILS);

    env->prom_addr = hwdef->slavio_base;



    /* allocate RAM */

    if ((uint64_t)RAM_size > hwdef->max_mem) {

        fprintf(stderr,

                "qemu: Too much memory for this machine: %d, maximum %d\n",

                (unsigned int)(RAM_size / (1024 * 1024)),

                (unsigned int)(hwdef->max_mem / (1024 * 1024)));

        exit(1);

    }

    cpu_register_physical_memory(0, RAM_size, 0);



    /* load boot prom */

    prom_offset = RAM_size + hwdef->vram_size;

    cpu_register_physical_memory(hwdef->slavio_base,

                                 (PROM_SIZE_MAX + TARGET_PAGE_SIZE - 1) &

                                 TARGET_PAGE_MASK,

                                 prom_offset | IO_MEM_ROM);



    if (bios_name == NULL)

        bios_name = PROM_FILENAME;

    snprintf(buf, sizeof(buf), "%s/%s", bios_dir, bios_name);

    ret = load_elf(buf, hwdef->slavio_base - PROM_VADDR, NULL, NULL, NULL);

    if (ret < 0 || ret > PROM_SIZE_MAX)

        ret = load_image_targphys(buf, hwdef->slavio_base, PROM_SIZE_MAX);

    if (ret < 0 || ret > PROM_SIZE_MAX) {

        fprintf(stderr, "qemu: could not load prom '%s'\n",

                buf);

        exit(1);

    }

    prom_offset += (ret + TARGET_PAGE_SIZE - 1) & TARGET_PAGE_MASK;



    /* set up devices */

    slavio_intctl = sun4c_intctl_init(hwdef->sun4c_intctl_base,

                                      &slavio_irq, cpu_irqs);



    iommu = iommu_init(hwdef->iommu_base, hwdef->iommu_version,

                       slavio_irq[hwdef->me_irq]);



    espdma = sparc32_dma_init(hwdef->dma_base, slavio_irq[hwdef->esp_irq],

                              iommu, &espdma_irq, &esp_reset);



    ledma = sparc32_dma_init(hwdef->dma_base + 16ULL,

                             slavio_irq[hwdef->le_irq], iommu, &ledma_irq,

                             &le_reset);



    if (graphic_depth != 8 && graphic_depth != 24) {

        fprintf(stderr, "qemu: Unsupported depth: %d\n", graphic_depth);

        exit (1);

    }

    tcx_init(ds, hwdef->tcx_base, phys_ram_base + RAM_size, RAM_size,

             hwdef->vram_size, graphic_width, graphic_height, graphic_depth);



    if (nd_table[0].model == NULL

        || strcmp(nd_table[0].model, "lance") == 0) {

        lance_init(&nd_table[0], hwdef->le_base, ledma, *ledma_irq, le_reset);

    } else if (strcmp(nd_table[0].model, "?") == 0) {

        fprintf(stderr, "qemu: Supported NICs: lance\n");

        exit (1);

    } else {

        fprintf(stderr, "qemu: Unsupported NIC: %s\n", nd_table[0].model);

        exit (1);

    }



    nvram = m48t59_init(slavio_irq[0], hwdef->nvram_base, 0,

                        hwdef->nvram_size, 2);



    slavio_serial_ms_kbd_init(hwdef->ms_kb_base, slavio_irq[hwdef->ms_kb_irq],

                              nographic);

    // Slavio TTYA (base+4, Linux ttyS0) is the first Qemu serial device

    // Slavio TTYB (base+0, Linux ttyS1) is the second Qemu serial device

    slavio_serial_init(hwdef->serial_base, slavio_irq[hwdef->ser_irq],

                       serial_hds[1], serial_hds[0]);



    slavio_misc = slavio_misc_init(-1, hwdef->apc_base,

                                   hwdef->aux1_base, hwdef->aux2_base,

                                   slavio_irq[hwdef->me_irq], env, &fdc_tc);



    if (hwdef->fd_base != (target_phys_addr_t)-1) {

        /* there is zero or one floppy drive */

        fd[1] = fd[0] = NULL;

        drive_index = drive_get_index(IF_FLOPPY, 0, 0);

        if (drive_index != -1)

            fd[0] = drives_table[drive_index].bdrv;



        sun4m_fdctrl_init(slavio_irq[hwdef->fd_irq], hwdef->fd_base, fd,

                          fdc_tc);

    }



    if (drive_get_max_bus(IF_SCSI) > 0) {

        fprintf(stderr, "qemu: too many SCSI bus\n");

        exit(1);

    }



    main_esp = esp_init(hwdef->esp_base, 2,

                        espdma_memory_read, espdma_memory_write,

                        espdma, *espdma_irq, esp_reset);



    for (i = 0; i < ESP_MAX_DEVS; i++) {

        drive_index = drive_get_index(IF_SCSI, 0, i);

        if (drive_index == -1)

            continue;

        esp_scsi_attach(main_esp, drives_table[drive_index].bdrv, i);

    }



    kernel_size = sun4m_load_kernel(kernel_filename, initrd_filename,

                                    RAM_size);



    nvram_init(nvram, (uint8_t *)&nd_table[0].macaddr, kernel_cmdline,

               boot_device, RAM_size, kernel_size, graphic_width,

               graphic_height, graphic_depth, hwdef->nvram_machine_id,

               "Sun4c");



    fw_cfg = fw_cfg_init(0, 0, CFG_ADDR, CFG_ADDR + 2);

    fw_cfg_add_i32(fw_cfg, FW_CFG_ID, 1);

    fw_cfg_add_i64(fw_cfg, FW_CFG_RAM_SIZE, (uint64_t)ram_size);

    fw_cfg_add_i16(fw_cfg, FW_CFG_MACHINE_ID, hwdef->machine_id);

}

static void r2d_init(ram_addr_t ram_size,

              const char *boot_device,

	      const char *kernel_filename, const char *kernel_cmdline,

	      const char *initrd_filename, const char *cpu_model)

{

    CPUState *env;

    struct SH7750State *s;

    ram_addr_t sdram_addr;

    qemu_irq *irq;

    PCIBus *pci;

    DriveInfo *dinfo;

    int i;



    if (!cpu_model)

        cpu_model = "SH7751R";



    env = cpu_init(cpu_model);

    if (!env) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }



    /* Allocate memory space */

    sdram_addr = qemu_ram_alloc(SDRAM_SIZE);

    cpu_register_physical_memory(SDRAM_BASE, SDRAM_SIZE, sdram_addr);

    /* Register peripherals */

    s = sh7750_init(env);

    irq = r2d_fpga_init(0x04000000, sh7750_irl(s));

    pci = sh_pci_register_bus(r2d_pci_set_irq, r2d_pci_map_irq, irq, 0, 4);



    sm501_init(0x10000000, SM501_VRAM_SIZE, irq[SM501], serial_hds[2]);



    /* onboard CF (True IDE mode, Master only). */

    if ((dinfo = drive_get(IF_IDE, 0, 0)) != NULL)

	mmio_ide_init(0x14001000, 0x1400080c, irq[CF_IDE], 1,

		      dinfo, NULL);



    /* NIC: rtl8139 on-board, and 2 slots. */

    for (i = 0; i < nb_nics; i++)

        pci_nic_init(&nd_table[i], "rtl8139", i==0 ? "2" : NULL);



    /* Todo: register on board registers */

    if (kernel_filename) {

      int kernel_size;

      /* initialization which should be done by firmware */

      stl_phys(SH7750_BCR1, 1<<3); /* cs3 SDRAM */

      stw_phys(SH7750_BCR2, 3<<(3*2)); /* cs3 32bit */



      if (kernel_cmdline) {

          kernel_size = load_image_targphys(kernel_filename,

				   SDRAM_BASE + LINUX_LOAD_OFFSET,

				   SDRAM_SIZE - LINUX_LOAD_OFFSET);

          env->pc = (SDRAM_BASE + LINUX_LOAD_OFFSET) | 0xa0000000;

          pstrcpy_targphys(SDRAM_BASE + 0x10100, 256, kernel_cmdline);

      } else {

          kernel_size = load_image_targphys(kernel_filename, SDRAM_BASE, SDRAM_SIZE);

          env->pc = SDRAM_BASE | 0xa0000000; /* Start from P2 area */

      }



      if (kernel_size < 0) {

        fprintf(stderr, "qemu: could not load kernel '%s'\n", kernel_filename);

        exit(1);

      }

    }

}

