        mod = (modrm >> 6) & 3;

        gen_pop_T0(s);

        if (mod == 3) {

            /* NOTE: order is important for pop %sp */

            gen_pop_update(s);

            rm = (modrm & 7) | REX_B(s);

            gen_op_mov_reg_T0(ot, rm);

