static av_always_inline void decode_subband_internal(DiracContext *s, SubBand *b, int is_arith)

{

    int cb_x, cb_y, left, right, top, bottom;

    DiracArith c;

    GetBitContext gb;

    int cb_width  = s->codeblock[b->level + (b->orientation != subband_ll)].width;

    int cb_height = s->codeblock[b->level + (b->orientation != subband_ll)].height;

    int blockcnt_one = (cb_width + cb_height) == 2;



    if (!b->length)

        return;



    init_get_bits8(&gb, b->coeff_data, b->length);



    if (is_arith)

        ff_dirac_init_arith_decoder(&c, &gb, b->length);



    top = 0;

    for (cb_y = 0; cb_y < cb_height; cb_y++) {

        bottom = (b->height * (cb_y+1)) / cb_height;

        left = 0;

        for (cb_x = 0; cb_x < cb_width; cb_x++) {

            right = (b->width * (cb_x+1)) / cb_width;

            codeblock(s, b, &gb, &c, left, right, top, bottom, blockcnt_one, is_arith);

            left = right;

        }

        top = bottom;

    }



    if (b->orientation == subband_ll && s->num_refs == 0)

        intra_dc_prediction(b);

}

static inline int coeff_unpack_golomb(GetBitContext *gb, int qfactor, int qoffset)

{

    int coeff = dirac_get_se_golomb(gb);

    const int sign = FFSIGN(coeff);

    if (coeff)

        coeff = sign*((sign * coeff * qfactor + qoffset) >> 2);

    return coeff;

}

static inline void unpack_coeffs(SnowContext *s, SubBand *b, SubBand * parent, int orientation){

    const int w= b->width;

    const int h= b->height;

    int x,y;



    if(1){

        int run;

        x_and_coeff *xc= b->x_coeff;

        x_and_coeff *prev_xc= NULL;

        x_and_coeff *prev2_xc= xc;

        x_and_coeff *parent_xc= parent ? parent->x_coeff : NULL;

        x_and_coeff *prev_parent_xc= parent_xc;



        run= get_symbol2(&s->c, b->state[1], 3);

        for(y=0; y<h; y++){

            int v=0;

            int lt=0, t=0, rt=0;



            if(y && prev_xc->x == 0){

                rt= prev_xc->coeff;

            }

            for(x=0; x<w; x++){

                int p=0;

                const int l= v;



                lt= t; t= rt;



                if(y){

                    if(prev_xc->x <= x)

                        prev_xc++;

                    if(prev_xc->x == x + 1)

                        rt= prev_xc->coeff;

                    else

                        rt=0;

                }

                if(parent_xc){

                    if(x>>1 > parent_xc->x){

                        parent_xc++;

                    }

                    if(x>>1 == parent_xc->x){

                        p= parent_xc->coeff;

                    }

                }

                if(/*ll|*/l|lt|t|rt|p){

                    int context= av_log2(/*ABS(ll) + */3*(l>>1) + (lt>>1) + (t&~1) + (rt>>1) + (p>>1));



                    v=get_rac(&s->c, &b->state[0][context]);

                    if(v){

                        v= 2*(get_symbol2(&s->c, b->state[context + 2], context-4) + 1);

                        v+=get_rac(&s->c, &b->state[0][16 + 1 + 3 + quant3bA[l&0xFF] + 3*quant3bA[t&0xFF]]);



                        xc->x=x;

                        (xc++)->coeff= v;

                    }

                }else{

                    if(!run){

                        run= get_symbol2(&s->c, b->state[1], 3);

                        v= 2*(get_symbol2(&s->c, b->state[0 + 2], 0-4) + 1);

                        v+=get_rac(&s->c, &b->state[0][16 + 1 + 3]);



                        xc->x=x;

                        (xc++)->coeff= v;

                    }else{

                        int max_run;

                        run--;

                        v=0;



                        if(y) max_run= FFMIN(run, prev_xc->x - x - 2);

                        else  max_run= FFMIN(run, w-x-1);

                        if(parent_xc)

                            max_run= FFMIN(max_run, 2*parent_xc->x - x - 1);

                        x+= max_run;

                        run-= max_run;

                    }

                }

            }

            (xc++)->x= w+1; //end marker

            prev_xc= prev2_xc;

            prev2_xc= xc;



            if(parent_xc){

                if(y&1){

                    while(parent_xc->x != parent->width+1)

                        parent_xc++;

                    parent_xc++;

                    prev_parent_xc= parent_xc;

                }else{

                    parent_xc= prev_parent_xc;

                }

            }

        }



        (xc++)->x= w+1; //end marker

    }

}

static void decode_block_params(DiracContext *s, DiracArith arith[8], DiracBlock *block,

                                int stride, int x, int y)

{

    int i;



    block->ref  = pred_block_mode(block, stride, x, y, DIRAC_REF_MASK_REF1);

    block->ref ^= dirac_get_arith_bit(arith, CTX_PMODE_REF1);



    if (s->num_refs == 2) {

        block->ref |= pred_block_mode(block, stride, x, y, DIRAC_REF_MASK_REF2);

        block->ref ^= dirac_get_arith_bit(arith, CTX_PMODE_REF2) << 1;

    }



    if (!block->ref) {

        pred_block_dc(block, stride, x, y);

        for (i = 0; i < 3; i++)

            block->u.dc[i] += dirac_get_arith_int(arith+1+i, CTX_DC_F1, CTX_DC_DATA);

        return;

    }



    if (s->globalmc_flag) {

        block->ref |= pred_block_mode(block, stride, x, y, DIRAC_REF_MASK_GLOBAL);

        block->ref ^= dirac_get_arith_bit(arith, CTX_GLOBAL_BLOCK) << 2;

    }



    for (i = 0; i < s->num_refs; i++)

        if (block->ref & (i+1)) {

            if (block->ref & DIRAC_REF_MASK_GLOBAL) {

                global_mv(s, block, x, y, i);

            } else {

                pred_mv(block, stride, x, y, i);

                block->u.mv[i][0] += dirac_get_arith_int(arith + 4 + 2 * i, CTX_MV_F1, CTX_MV_DATA);

                block->u.mv[i][1] += dirac_get_arith_int(arith + 5 + 2 * i, CTX_MV_F1, CTX_MV_DATA);

            }

        }

}

static int encode_picture_lossless(AVCodecContext *avctx, unsigned char *buf, int buf_size, void *data){

    MpegEncContext * const s = avctx->priv_data;

    MJpegContext * const m = s->mjpeg_ctx;

    AVFrame *pict = data;

    const int width= s->width;

    const int height= s->height;

    AVFrame * const p= (AVFrame*)&s->current_picture;

    const int predictor= avctx->prediction_method+1;



    init_put_bits(&s->pb, buf, buf_size);



    *p = *pict;

    p->pict_type= FF_I_TYPE;

    p->key_frame= 1;



    mjpeg_picture_header(s);



    s->header_bits= put_bits_count(&s->pb);



    if(avctx->pix_fmt == PIX_FMT_RGBA32){

        int x, y, i;

        const int linesize= p->linesize[0];

        uint16_t buffer[2048][4];

        int left[3], top[3], topleft[3];



        for(i=0; i<3; i++){

            buffer[0][i]= 1 << (9 - 1);

        }



        for(y = 0; y < height; y++) {

            const int modified_predictor= y ? predictor : 1;

            uint8_t *ptr = p->data[0] + (linesize * y);



            for(i=0; i<3; i++){

                top[i]= left[i]= topleft[i]= buffer[0][i];

            }

            for(x = 0; x < width; x++) {

                buffer[x][1] = ptr[4*x+0] - ptr[4*x+1] + 0x100;

                buffer[x][2] = ptr[4*x+2] - ptr[4*x+1] + 0x100;

                buffer[x][0] = (ptr[4*x+0] + 2*ptr[4*x+1] + ptr[4*x+2])>>2;



                for(i=0;i<3;i++) {

                    int pred, diff;



                    PREDICT(pred, topleft[i], top[i], left[i], modified_predictor);



                    topleft[i]= top[i];

                    top[i]= buffer[x+1][i];



                    left[i]= buffer[x][i];



                    diff= ((left[i] - pred + 0x100)&0x1FF) - 0x100;



                    if(i==0)

                        mjpeg_encode_dc(s, diff, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly

                    else

                        mjpeg_encode_dc(s, diff, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);

                }

            }

        }

    }else{

        int mb_x, mb_y, i;

        const int mb_width  = (width  + s->mjpeg_hsample[0] - 1) / s->mjpeg_hsample[0];

        const int mb_height = (height + s->mjpeg_vsample[0] - 1) / s->mjpeg_vsample[0];



        for(mb_y = 0; mb_y < mb_height; mb_y++) {

            for(mb_x = 0; mb_x < mb_width; mb_x++) {

                if(mb_x==0 || mb_y==0){

                    for(i=0;i<3;i++) {

                        uint8_t *ptr;

                        int x, y, h, v, linesize;

                        h = s->mjpeg_hsample[i];

                        v = s->mjpeg_vsample[i];

                        linesize= p->linesize[i];



                        for(y=0; y<v; y++){

                            for(x=0; x<h; x++){

                                int pred;



                                ptr = p->data[i] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap

                                if(y==0 && mb_y==0){

                                    if(x==0 && mb_x==0){

                                        pred= 128;

                                    }else{

                                        pred= ptr[-1];

                                    }

                                }else{

                                    if(x==0 && mb_x==0){

                                        pred= ptr[-linesize];

                                    }else{

                                        PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);

                                    }

                                }



                                if(i==0)

                                    mjpeg_encode_dc(s, (int8_t)(*ptr - pred), m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly

                                else

                                    mjpeg_encode_dc(s, (int8_t)(*ptr - pred), m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);

                            }

                        }

                    }

                }else{

                    for(i=0;i<3;i++) {

                        uint8_t *ptr;

                        int x, y, h, v, linesize;

                        h = s->mjpeg_hsample[i];

                        v = s->mjpeg_vsample[i];

                        linesize= p->linesize[i];



                        for(y=0; y<v; y++){

                            for(x=0; x<h; x++){

                                int pred;



                                ptr = p->data[i] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap

//printf("%d %d %d %d %8X\n", mb_x, mb_y, x, y, ptr); 

                                PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);



                                if(i==0)

                                    mjpeg_encode_dc(s, (int8_t)(*ptr - pred), m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly

                                else

                                    mjpeg_encode_dc(s, (int8_t)(*ptr - pred), m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);

                            }

                        }

                    }

                }

            }

        }

    }



    emms_c();



    mjpeg_picture_trailer(s);

    s->picture_number++;



    flush_put_bits(&s->pb);

    return pbBufPtr(&s->pb) - s->pb.buf;

//    return (put_bits_count(&f->pb)+7)/8;

}

static int svq1_encode_frame(AVCodecContext *avctx, unsigned char *buf, 

    int buf_size, void *data)

{

    SVQ1Context * const s = avctx->priv_data;

    AVFrame *pict = data;

    AVFrame * const p= (AVFrame*)&s->picture;

    AVFrame temp;

    int i;



    if(avctx->pix_fmt != PIX_FMT_YUV410P){

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return -1;

    }



    if(!s->current_picture.data[0]){

        avctx->get_buffer(avctx, &s->current_picture);

        avctx->get_buffer(avctx, &s->last_picture);

    }



    temp= s->current_picture;

    s->current_picture= s->last_picture;

    s->last_picture= temp;



    init_put_bits(&s->pb, buf, buf_size);



    *p = *pict;

    p->pict_type = avctx->frame_number % avctx->gop_size ? P_TYPE : I_TYPE;

    p->key_frame = p->pict_type == I_TYPE;



    svq1_write_header(s, p->pict_type);

    for(i=0; i<3; i++){

        svq1_encode_plane(s, i,

            s->picture.data[i], s->last_picture.data[i], s->current_picture.data[i],

            s->frame_width / (i?4:1), s->frame_height / (i?4:1), 

            s->picture.linesize[i], s->current_picture.linesize[i]);

    }



//    align_put_bits(&s->pb);

    while(put_bits_count(&s->pb) & 31)

        put_bits(&s->pb, 1, 0);



    flush_put_bits(&s->pb);



    return (put_bits_count(&s->pb) / 8);

}

static int ffv1_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                        const AVFrame *pict, int *got_packet)

{

    FFV1Context *f      = avctx->priv_data;

    RangeCoder *const c = &f->slice_context[0]->c;

    int used_count      = 0;

    uint8_t keystate    = 128;

    uint8_t *buf_p;

    int i, ret;



    f->frame = pict;



    if ((ret = ff_alloc_packet(pkt, avctx->width * avctx->height *

                             ((8 * 2 + 1 + 1) * 4) / 8 +

                             AV_INPUT_BUFFER_MIN_SIZE)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    ff_init_range_encoder(c, pkt->data, pkt->size);

    ff_build_rac_states(c, 0.05 * (1LL << 32), 256 - 8);



    if (avctx->gop_size == 0 || f->picture_number % avctx->gop_size == 0) {

        put_rac(c, &keystate, 1);

        f->key_frame = 1;

        f->gob_count++;

        write_header(f);

    } else {

        put_rac(c, &keystate, 0);

        f->key_frame = 0;

    }



    if (f->ac > 1) {

        int i;

        for (i = 1; i < 256; i++) {

            c->one_state[i]        = f->state_transition[i];

            c->zero_state[256 - i] = 256 - c->one_state[i];

        }

    }



    for (i = 1; i < f->slice_count; i++) {

        FFV1Context *fs = f->slice_context[i];

        uint8_t *start  = pkt->data +

                          (pkt->size - used_count) * (int64_t)i / f->slice_count;

        int len = pkt->size / f->slice_count;

        ff_init_range_encoder(&fs->c, start, len);

    }

    avctx->execute(avctx, encode_slice, &f->slice_context[0], NULL,

                   f->slice_count, sizeof(void *));



    buf_p = pkt->data;

    for (i = 0; i < f->slice_count; i++) {

        FFV1Context *fs = f->slice_context[i];

        int bytes;



        if (fs->ac) {

            uint8_t state = 129;

            put_rac(&fs->c, &state, 0);

            bytes = ff_rac_terminate(&fs->c);

        } else {

            flush_put_bits(&fs->pb); // FIXME: nicer padding

            bytes = fs->ac_byte_count + (put_bits_count(&fs->pb) + 7) / 8;

        }

        if (i > 0 || f->version > 2) {

            av_assert0(bytes < pkt->size / f->slice_count);

            memmove(buf_p, fs->c.bytestream_start, bytes);

            av_assert0(bytes < (1 << 24));

            AV_WB24(buf_p + bytes, bytes);

            bytes += 3;

        }

        if (f->ec) {

            unsigned v;

            buf_p[bytes++] = 0;

            v = av_crc(av_crc_get_table(AV_CRC_32_IEEE), 0, buf_p, bytes);

            AV_WL32(buf_p + bytes, v);

            bytes += 4;

        }

        buf_p += bytes;

    }



    if ((avctx->flags & AV_CODEC_FLAG_PASS1) && (f->picture_number & 31) == 0) {

        int j, k, m;

        char *p   = avctx->stats_out;

        char *end = p + STATS_OUT_SIZE;



        memset(f->rc_stat, 0, sizeof(f->rc_stat));

        for (i = 0; i < f->quant_table_count; i++)

            memset(f->rc_stat2[i], 0, f->context_count[i] * sizeof(*f->rc_stat2[i]));



        for (j = 0; j < f->slice_count; j++) {

            FFV1Context *fs = f->slice_context[j];

            for (i = 0; i < 256; i++) {

                f->rc_stat[i][0] += fs->rc_stat[i][0];

                f->rc_stat[i][1] += fs->rc_stat[i][1];

            }

            for (i = 0; i < f->quant_table_count; i++) {

                for (k = 0; k < f->context_count[i]; k++)

                    for (m = 0; m < 32; m++) {

                        f->rc_stat2[i][k][m][0] += fs->rc_stat2[i][k][m][0];

                        f->rc_stat2[i][k][m][1] += fs->rc_stat2[i][k][m][1];

                    }

            }

        }



        for (j = 0; j < 256; j++) {

            snprintf(p, end - p, "%" PRIu64 " %" PRIu64 " ",

                     f->rc_stat[j][0], f->rc_stat[j][1]);

            p += strlen(p);

        }

        snprintf(p, end - p, "\n");



        for (i = 0; i < f->quant_table_count; i++) {

            for (j = 0; j < f->context_count[i]; j++)

                for (m = 0; m < 32; m++) {

                    snprintf(p, end - p, "%" PRIu64 " %" PRIu64 " ",

                             f->rc_stat2[i][j][m][0], f->rc_stat2[i][j][m][1]);

                    p += strlen(p);

                }

        }

        snprintf(p, end - p, "%d\n", f->gob_count);

    } else if (avctx->flags & AV_CODEC_FLAG_PASS1)

        avctx->stats_out[0] = '\0';



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->key_frame = f->key_frame;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    f->picture_number++;

    pkt->size   = buf_p - pkt->data;

    pkt->flags |= AV_PKT_FLAG_KEY * f->key_frame;

    *got_packet = 1;



    return 0;

}

static int svq1_encode_frame(AVCodecContext *avctx, unsigned char *buf,

    int buf_size, void *data)

{

    SVQ1Context * const s = avctx->priv_data;

    AVFrame *pict = data;

    AVFrame * const p= (AVFrame*)&s->picture;

    AVFrame temp;

    int i;



    if(avctx->pix_fmt != PIX_FMT_YUV410P){

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return -1;

    }



    if(!s->current_picture.data[0]){

        avctx->get_buffer(avctx, &s->current_picture);

        avctx->get_buffer(avctx, &s->last_picture);

        s->scratchbuf = av_malloc(s->current_picture.linesize[0] * 16);

    }



    temp= s->current_picture;

    s->current_picture= s->last_picture;

    s->last_picture= temp;



    init_put_bits(&s->pb, buf, buf_size);



    *p = *pict;

    p->pict_type = avctx->gop_size && avctx->frame_number % avctx->gop_size ? FF_P_TYPE : FF_I_TYPE;

    p->key_frame = p->pict_type == FF_I_TYPE;



    svq1_write_header(s, p->pict_type);

    for(i=0; i<3; i++){

        if(svq1_encode_plane(s, i,

            s->picture.data[i], s->last_picture.data[i], s->current_picture.data[i],

            s->frame_width / (i?4:1), s->frame_height / (i?4:1),

            s->picture.linesize[i], s->current_picture.linesize[i]) < 0)

                return -1;

    }



//    align_put_bits(&s->pb);

    while(put_bits_count(&s->pb) & 31)

        put_bits(&s->pb, 1, 0);



    flush_put_bits(&s->pb);



    return put_bits_count(&s->pb) / 8;

}

void OPPROTO op_divw (void)

{

    if (unlikely(((int32_t)T0 == INT32_MIN && (int32_t)T1 == -1) ||

                 (int32_t)T1 == 0)) {

        T0 = (int32_t)((-1) * ((uint32_t)T0 >> 31));

    } else {

        T0 = (int32_t)T0 / (int32_t)T1;

    }

    RETURN();

}

void do_srad (void)

{

    int64_t ret;



    if (likely(!(T1 & 0x40UL))) {

        if (likely((uint64_t)T1 != 0)) {

            ret = (int64_t)T0 >> (T1 & 0x3FUL);

            if (likely(ret >= 0 || ((int64_t)T0 & ((1 << T1) - 1)) == 0)) {

                xer_ca = 0;

            } else {

                xer_ca = 1;

            }

        } else {

            ret = T0;

            xer_ca = 0;

        }

    } else {

        ret = (-1) * ((uint64_t)T0 >> 63);

        if (likely(ret >= 0 || ((uint64_t)T0 & ~0x8000000000000000ULL) == 0)) {

            xer_ca = 0;

        } else {

            xer_ca = 1;

        }

    }

    T0 = ret;

}

void do_subfzeo_64 (void)

{

    T1 = T0;

    T0 = ~T0 + xer_ca;

    if (likely(!(((uint64_t)~T1 ^ UINT64_MAX) &

                 ((uint64_t)(~T1) ^ (uint64_t)T0) & (1ULL << 63)))) {

        xer_ov = 0;

    } else {

        xer_ov = 1;

        xer_so = 1;

    }

    if (likely((uint64_t)T0 >= (uint64_t)~T1)) {

        xer_ca = 0;

    } else {

        xer_ca = 1;

    }

}

