static int decode_frame(FLACContext *s)

{

    int i, ret;

    GetBitContext *gb = &s->gb;

    FLACFrameInfo fi;



    if ((ret = ff_flac_decode_frame_header(s->avctx, gb, &fi, 0)) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "invalid frame header\n");

        return ret;

    }



    if (s->channels && fi.channels != s->channels && s->got_streaminfo) {

        s->channels = s->avctx->channels = fi.channels;

        ff_flac_set_channel_layout(s->avctx);

        ret = allocate_buffers(s);

        if (ret < 0)

            return ret;

    }

    s->channels = s->avctx->channels = fi.channels;

    if (!s->avctx->channel_layout)

        ff_flac_set_channel_layout(s->avctx);

    s->ch_mode = fi.ch_mode;



    if (!s->bps && !fi.bps) {

        av_log(s->avctx, AV_LOG_ERROR, "bps not found in STREAMINFO or frame header\n");

        return AVERROR_INVALIDDATA;

    }

    if (!fi.bps) {

        fi.bps = s->bps;

    } else if (s->bps && fi.bps != s->bps) {

        av_log(s->avctx, AV_LOG_ERROR, "switching bps mid-stream is not "

                                       "supported\n");

        return AVERROR_INVALIDDATA;

    }



    if (!s->bps) {

        s->bps = s->avctx->bits_per_raw_sample = fi.bps;

        flac_set_bps(s);

    }



    if (!s->max_blocksize)

        s->max_blocksize = FLAC_MAX_BLOCKSIZE;

    if (fi.blocksize > s->max_blocksize) {

        av_log(s->avctx, AV_LOG_ERROR, "blocksize %d > %d\n", fi.blocksize,

               s->max_blocksize);

        return AVERROR_INVALIDDATA;

    }

    s->blocksize = fi.blocksize;



    if (!s->samplerate && !fi.samplerate) {

        av_log(s->avctx, AV_LOG_ERROR, "sample rate not found in STREAMINFO"

                                        " or frame header\n");

        return AVERROR_INVALIDDATA;

    }

    if (fi.samplerate == 0)

        fi.samplerate = s->samplerate;

    s->samplerate = s->avctx->sample_rate = fi.samplerate;



    if (!s->got_streaminfo) {

        ret = allocate_buffers(s);

        if (ret < 0)

            return ret;

        ff_flacdsp_init(&s->dsp, s->avctx->sample_fmt, s->channels, s->bps);

        s->got_streaminfo = 1;

        dump_headers(s->avctx, (FLACStreaminfo *)s);

    }



//    dump_headers(s->avctx, (FLACStreaminfo *)s);



    /* subframes */

    for (i = 0; i < s->channels; i++) {

        if ((ret = decode_subframe(s, i)) < 0)

            return ret;

    }



    align_get_bits(gb);



    /* frame footer */

    skip_bits(gb, 16); /* data crc */



    return 0;

}

static int read_restart_header(MLPDecodeContext *m, GetBitContext *gbp,

                               const uint8_t *buf, unsigned int substr)

{

    SubStream *s = &m->substream[substr];

    unsigned int ch;

    int sync_word, tmp;

    uint8_t checksum;

    uint8_t lossless_check;

    int start_count = get_bits_count(gbp);

    const int max_matrix_channel = m->avctx->codec_id == CODEC_ID_MLP

                                 ? MAX_MATRIX_CHANNEL_MLP

                                 : MAX_MATRIX_CHANNEL_TRUEHD;



    sync_word = get_bits(gbp, 13);



    if (sync_word != 0x31ea >> 1) {

        av_log(m->avctx, AV_LOG_ERROR,

               "restart header sync incorrect (got 0x%04x)\n", sync_word);

        return AVERROR_INVALIDDATA;

    }



    s->noise_type = get_bits1(gbp);



    if (m->avctx->codec_id == CODEC_ID_MLP && s->noise_type) {

        av_log(m->avctx, AV_LOG_ERROR, "MLP must have 0x31ea sync word.\n");

        return AVERROR_INVALIDDATA;

    }



    skip_bits(gbp, 16); /* Output timestamp */



    s->min_channel        = get_bits(gbp, 4);

    s->max_channel        = get_bits(gbp, 4);

    s->max_matrix_channel = get_bits(gbp, 4);



    if (s->max_matrix_channel > max_matrix_channel) {

        av_log(m->avctx, AV_LOG_ERROR,

               "Max matrix channel cannot be greater than %d.\n",

               max_matrix_channel);

        return AVERROR_INVALIDDATA;

    }



    if (s->max_channel != s->max_matrix_channel) {

        av_log(m->avctx, AV_LOG_ERROR,

               "Max channel must be equal max matrix channel.\n");

        return AVERROR_INVALIDDATA;

    }



    /* This should happen for TrueHD streams with >6 channels and MLP's noise

     * type. It is not yet known if this is allowed. */

    if (s->max_channel > MAX_MATRIX_CHANNEL_MLP && !s->noise_type) {

        av_log_ask_for_sample(m->avctx,

               "Number of channels %d is larger than the maximum supported "

               "by the decoder.\n", s->max_channel + 2);

        return AVERROR_PATCHWELCOME;

    }



    if (s->min_channel > s->max_channel) {

        av_log(m->avctx, AV_LOG_ERROR,

               "Substream min channel cannot be greater than max channel.\n");

        return AVERROR_INVALIDDATA;

    }



    if (m->avctx->request_channels > 0

        && s->max_channel + 1 >= m->avctx->request_channels

        && substr < m->max_decoded_substream) {

        av_log(m->avctx, AV_LOG_DEBUG,

               "Extracting %d channel downmix from substream %d. "

               "Further substreams will be skipped.\n",

               s->max_channel + 1, substr);

        m->max_decoded_substream = substr;

    }



    s->noise_shift   = get_bits(gbp,  4);

    s->noisegen_seed = get_bits(gbp, 23);



    skip_bits(gbp, 19);



    s->data_check_present = get_bits1(gbp);

    lossless_check = get_bits(gbp, 8);

    if (substr == m->max_decoded_substream

        && s->lossless_check_data != 0xffffffff) {

        tmp = xor_32_to_8(s->lossless_check_data);

        if (tmp != lossless_check)

            av_log(m->avctx, AV_LOG_WARNING,

                   "Lossless check failed - expected %02x, calculated %02x.\n",

                   lossless_check, tmp);

    }



    skip_bits(gbp, 16);



    memset(s->ch_assign, 0, sizeof(s->ch_assign));



    for (ch = 0; ch <= s->max_matrix_channel; ch++) {

        int ch_assign = get_bits(gbp, 6);

        if (ch_assign > s->max_matrix_channel) {

            av_log_ask_for_sample(m->avctx,

                   "Assignment of matrix channel %d to invalid output channel %d.\n",

                   ch, ch_assign);

            return AVERROR_PATCHWELCOME;

        }

        s->ch_assign[ch_assign] = ch;

    }



    if (m->avctx->codec_id == CODEC_ID_MLP && m->needs_reordering) {

        if (m->avctx->channel_layout == (AV_CH_LAYOUT_QUAD|AV_CH_LOW_FREQUENCY) ||

            m->avctx->channel_layout == AV_CH_LAYOUT_5POINT0_BACK) {

            int i = s->ch_assign[4];

            s->ch_assign[4] = s->ch_assign[3];

            s->ch_assign[3] = s->ch_assign[2];

            s->ch_assign[2] = i;

        } else if (m->avctx->channel_layout == AV_CH_LAYOUT_5POINT1_BACK) {

            FFSWAP(int, s->ch_assign[2], s->ch_assign[4]);

            FFSWAP(int, s->ch_assign[3], s->ch_assign[5]);

        }

    }

    if (m->avctx->codec_id == CODEC_ID_TRUEHD &&

        (m->avctx->channel_layout == AV_CH_LAYOUT_7POINT1 ||

        m->avctx->channel_layout == AV_CH_LAYOUT_7POINT1_WIDE)) {

        FFSWAP(int, s->ch_assign[4], s->ch_assign[6]);

        FFSWAP(int, s->ch_assign[5], s->ch_assign[7]);

    } else if (m->avctx->codec_id == CODEC_ID_TRUEHD &&

        (m->avctx->channel_layout == AV_CH_LAYOUT_6POINT1 ||

        m->avctx->channel_layout == (AV_CH_LAYOUT_6POINT1 | AV_CH_TOP_CENTER) ||

        m->avctx->channel_layout == (AV_CH_LAYOUT_6POINT1 | AV_CH_TOP_FRONT_CENTER))) {

        int i = s->ch_assign[6];

        s->ch_assign[6] = s->ch_assign[5];

        s->ch_assign[5] = s->ch_assign[4];

        s->ch_assign[4] = i;

    }



    checksum = ff_mlp_restart_checksum(buf, get_bits_count(gbp) - start_count);



    if (checksum != get_bits(gbp, 8))

        av_log(m->avctx, AV_LOG_ERROR, "restart header checksum error\n");



    /* Set default decoding parameters. */

    s->param_presence_flags   = 0xff;

    s->num_primitive_matrices = 0;

    s->blocksize              = 8;

    s->lossless_check_data    = 0;



    memset(s->output_shift   , 0, sizeof(s->output_shift   ));

    memset(s->quant_step_size, 0, sizeof(s->quant_step_size));



    for (ch = s->min_channel; ch <= s->max_channel; ch++) {

        ChannelParams *cp = &s->channel_params[ch];

        cp->filter_params[FIR].order = 0;

        cp->filter_params[IIR].order = 0;

        cp->filter_params[FIR].shift = 0;

        cp->filter_params[IIR].shift = 0;



        /* Default audio coding is 24-bit raw PCM. */

        cp->huff_offset      = 0;

        cp->sign_huff_offset = (-1) << 23;

        cp->codebook         = 0;

        cp->huff_lsbs        = 24;

    }



    if (substr == m->max_decoded_substream)

        m->avctx->channels = s->max_matrix_channel + 1;



    return 0;

}

static int v210_read_header(AVFormatContext *ctx)

{

    V210DemuxerContext *s = ctx->priv_data;

    AVStream *st;



    st = avformat_new_stream(ctx, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;



    st->codec->codec_id = ctx->iformat->raw_codec_id;



    avpriv_set_pts_info(st, 64, s->framerate.den, s->framerate.num);



    st->codec->width    = s->width;

    st->codec->height   = s->height;

    st->codec->pix_fmt  = ctx->iformat->raw_codec_id == AV_CODEC_ID_V210 ?

                          AV_PIX_FMT_YUV422P10 : AV_PIX_FMT_YUV422P16;

    st->codec->bit_rate = av_rescale_q(GET_PACKET_SIZE(s->width, s->height),

                                       (AVRational){8,1}, st->time_base);



    return 0;

}

static int video_read_header(AVFormatContext *s,

                             AVFormatParameters *ap)

{

    AVStream *st;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR_NOMEM;



    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = s->iformat->value;

    st->need_parsing = 1;



    /* for mjpeg, specify frame rate */

    /* for mpeg4 specify it too (most mpeg4 streams dont have the fixed_vop_rate set ...)*/

    if (ap && ap->time_base.num) {

        av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

    } else if ( st->codec->codec_id == CODEC_ID_MJPEG ||

                st->codec->codec_id == CODEC_ID_MPEG4 ||

                st->codec->codec_id == CODEC_ID_H264) {

        av_set_pts_info(st, 64, 1, 25);

    }



    return 0;

}

AVStream *avformat_new_stream(AVFormatContext *s, const AVCodec *c)

{

    AVStream *st;

    int i;



    if (av_reallocp_array(&s->streams, s->nb_streams + 1,

                          sizeof(*s->streams)) < 0) {

        s->nb_streams = 0;

        return NULL;

    }



    st = av_mallocz(sizeof(AVStream));

    if (!st)

        return NULL;

    if (!(st->info = av_mallocz(sizeof(*st->info)))) {

        av_free(st);

        return NULL;

    }



    st->codec = avcodec_alloc_context3(c);

    if (!st->codec) {

        av_free(st->info);

        av_free(st);

        return NULL;

    }

    if (s->iformat) {

        /* no default bitrate if decoding */

        st->codec->bit_rate = 0;



        /* default pts setting is MPEG-like */

        avpriv_set_pts_info(st, 33, 1, 90000);

    }



    st->index      = s->nb_streams;

    st->start_time = AV_NOPTS_VALUE;

    st->duration   = AV_NOPTS_VALUE;

    /* we set the current DTS to 0 so that formats without any timestamps

     * but durations get some timestamps, formats with some unknown

     * timestamps have their first few packets buffered and the

     * timestamps corrected before they are returned to the user */

    st->cur_dts       = 0;

    st->first_dts     = AV_NOPTS_VALUE;

    st->probe_packets = MAX_PROBE_PACKETS;



    st->last_IP_pts = AV_NOPTS_VALUE;

    for (i = 0; i < MAX_REORDER_DELAY + 1; i++)

        st->pts_buffer[i] = AV_NOPTS_VALUE;



    st->sample_aspect_ratio = (AVRational) { 0, 1 };



    st->info->fps_first_dts = AV_NOPTS_VALUE;

    st->info->fps_last_dts  = AV_NOPTS_VALUE;



    s->streams[s->nb_streams++] = st;

    return st;

}

static int wv_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    WVContext *wc = s->priv_data;

    AVStream *st;

    int ret;



    wc->block_parsed = 0;

    for (;;) {

        if ((ret = wv_read_block_header(s, pb, 0)) < 0)

            return ret;

        if (!AV_RN32(wc->extra))

            avio_skip(pb, wc->blksize - 24);

        else

            break;

    }



    /* now we are ready: build format streams */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->codec->codec_type            = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id              = AV_CODEC_ID_WAVPACK;

    st->codec->channels              = wc->chan;

    st->codec->channel_layout        = wc->chmask;

    st->codec->sample_rate           = wc->rate;

    st->codec->bits_per_coded_sample = wc->bpp;

    avpriv_set_pts_info(st, 64, 1, wc->rate);

    st->start_time = 0;

    st->duration   = wc->samples;



    if (s->pb->seekable) {

        int64_t cur = avio_tell(s->pb);

        wc->apetag_start = ff_ape_parse_tag(s);

        if (!av_dict_get(s->metadata, "", NULL, AV_DICT_IGNORE_SUFFIX))

            ff_id3v1_read(s);

        avio_seek(s->pb, cur, SEEK_SET);

    }



    return 0;

}

int qcow2_backing_read1(BlockDriverState *bs, QEMUIOVector *qiov,

                  int64_t sector_num, int nb_sectors)

{

    int n1;

    if ((sector_num + nb_sectors) <= bs->total_sectors)

        return nb_sectors;

    if (sector_num >= bs->total_sectors)

        n1 = 0;

    else

        n1 = bs->total_sectors - sector_num;



    qemu_iovec_memset(qiov, 0, 512 * (nb_sectors - n1));



    return n1;

}

static int coroutine_fn qcow2_co_is_allocated(BlockDriverState *bs,

        int64_t sector_num, int nb_sectors, int *pnum)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t cluster_offset;

    int ret;



    *pnum = nb_sectors;

    /* FIXME We can get errors here, but the bdrv_co_is_allocated interface

     * can't pass them on today */

    qemu_co_mutex_lock(&s->lock);

    ret = qcow2_get_cluster_offset(bs, sector_num << 9, pnum, &cluster_offset);

    qemu_co_mutex_unlock(&s->lock);

    if (ret < 0) {

        *pnum = 0;

    }



    return (cluster_offset != 0) || (ret == QCOW2_CLUSTER_ZERO);

}

static coroutine_fn int sd_co_writev(BlockDriverState *bs, int64_t sector_num,

                        int nb_sectors, QEMUIOVector *qiov)

{

    SheepdogAIOCB acb;

    int ret;

    int64_t offset = (sector_num + nb_sectors) * BDRV_SECTOR_SIZE;

    BDRVSheepdogState *s = bs->opaque;



    if (offset > s->inode.vdi_size) {

        ret = sd_truncate(bs, offset);

        if (ret < 0) {

            return ret;

        }

    }



    sd_aio_setup(&acb, s, qiov, sector_num, nb_sectors, AIOCB_WRITE_UDATA);



retry:

    if (check_overlapping_aiocb(s, &acb)) {

        qemu_co_queue_wait(&s->overlapping_queue);

        goto retry;

    }



    sd_co_rw_vector(&acb);

    sd_write_done(&acb);



    QLIST_REMOVE(&acb, aiocb_siblings);

    qemu_co_queue_restart_all(&s->overlapping_queue);

    return acb.ret;

}

static coroutine_fn int sd_co_discard(BlockDriverState *bs, int64_t sector_num,

                                      int nb_sectors)

{

    SheepdogAIOCB *acb;

    QEMUIOVector dummy;

    BDRVSheepdogState *s = bs->opaque;

    int ret;



    if (!s->discard_supported) {

            return 0;

    }



    acb = sd_aio_setup(bs, &dummy, sector_num, nb_sectors);

    acb->aiocb_type = AIOCB_DISCARD_OBJ;

    acb->aio_done_func = sd_finish_aiocb;



retry:

    if (check_overwrapping_aiocb(s, acb)) {

        qemu_co_queue_wait(&s->overwrapping_queue);

        goto retry;

    }



    ret = sd_co_rw_vector(acb);

    if (ret <= 0) {

        QLIST_REMOVE(acb, aiocb_siblings);

        qemu_co_queue_restart_all(&s->overwrapping_queue);

        qemu_aio_unref(acb);

        return ret;

    }



    qemu_coroutine_yield();



    QLIST_REMOVE(acb, aiocb_siblings);

    qemu_co_queue_restart_all(&s->overwrapping_queue);



    return acb->ret;

}

static void pointer_event(VncState *vs, int button_mask, int x, int y)

{

    static uint32_t bmap[INPUT_BUTTON__MAX] = {

        [INPUT_BUTTON_LEFT]       = 0x01,

        [INPUT_BUTTON_MIDDLE]     = 0x02,

        [INPUT_BUTTON_RIGHT]      = 0x04,

        [INPUT_BUTTON_WHEEL_UP]   = 0x08,

        [INPUT_BUTTON_WHEEL_DOWN] = 0x10,

    };

    QemuConsole *con = vs->vd->dcl.con;

    int width = pixman_image_get_width(vs->vd->server);

    int height = pixman_image_get_height(vs->vd->server);



    if (vs->last_bmask != button_mask) {

        qemu_input_update_buttons(con, bmap, vs->last_bmask, button_mask);

        vs->last_bmask = button_mask;

    }



    if (vs->absolute) {

        qemu_input_queue_abs(con, INPUT_AXIS_X, x, width);

        qemu_input_queue_abs(con, INPUT_AXIS_Y, y, height);

    } else if (vnc_has_feature(vs, VNC_FEATURE_POINTER_TYPE_CHANGE)) {

        qemu_input_queue_rel(con, INPUT_AXIS_X, x - 0x7FFF);

        qemu_input_queue_rel(con, INPUT_AXIS_Y, y - 0x7FFF);

    } else {

        if (vs->last_x != -1) {

            qemu_input_queue_rel(con, INPUT_AXIS_X, x - vs->last_x);

            qemu_input_queue_rel(con, INPUT_AXIS_Y, y - vs->last_y);

        }

        vs->last_x = x;

        vs->last_y = y;

    }

    qemu_input_event_sync();

}

static void hmp_mouse_move(Monitor *mon, const QDict *qdict)

{

    int dx, dy, dz, button;

    const char *dx_str = qdict_get_str(qdict, "dx_str");

    const char *dy_str = qdict_get_str(qdict, "dy_str");

    const char *dz_str = qdict_get_try_str(qdict, "dz_str");



    dx = strtol(dx_str, NULL, 0);

    dy = strtol(dy_str, NULL, 0);

    qemu_input_queue_rel(NULL, INPUT_AXIS_X, dx);

    qemu_input_queue_rel(NULL, INPUT_AXIS_Y, dy);



    if (dz_str) {

        dz = strtol(dz_str, NULL, 0);

        if (dz != 0) {

            button = (dz > 0) ? INPUT_BUTTON_WHEEL_UP : INPUT_BUTTON_WHEEL_DOWN;

            qemu_input_queue_btn(NULL, button, true);

            qemu_input_event_sync();

            qemu_input_queue_btn(NULL, button, false);

        }

    }

    qemu_input_event_sync();

}

static void sdl_mouse_warp(int x, int y, int on)

{

    if (on) {

        if (!guest_cursor)

            sdl_show_cursor();

        if (gui_grab || kbd_mouse_is_absolute() || absolute_enabled) {

            SDL_SetCursor(guest_sprite);

            SDL_WarpMouse(x, y);

        }

    } else if (gui_grab)

        sdl_hide_cursor();

    guest_cursor = on;

    guest_x = x, guest_y = y;

}

static void ps2_mouse_event(DeviceState *dev, QemuConsole *src,

                            InputEvent *evt)

{

    static const int bmap[INPUT_BUTTON__MAX] = {

        [INPUT_BUTTON_LEFT]   = MOUSE_EVENT_LBUTTON,

        [INPUT_BUTTON_MIDDLE] = MOUSE_EVENT_MBUTTON,

        [INPUT_BUTTON_RIGHT]  = MOUSE_EVENT_RBUTTON,

    };

    PS2MouseState *s = (PS2MouseState *)dev;

    InputMoveEvent *move;

    InputBtnEvent *btn;



    /* check if deltas are recorded when disabled */

    if (!(s->mouse_status & MOUSE_STATUS_ENABLED))

        return;



    switch (evt->type) {

    case INPUT_EVENT_KIND_REL:

        move = evt->u.rel;

        if (move->axis == INPUT_AXIS_X) {

            s->mouse_dx += move->value;

        } else if (move->axis == INPUT_AXIS_Y) {

            s->mouse_dy -= move->value;

        }

        break;



    case INPUT_EVENT_KIND_BTN:

        btn = evt->u.btn;

        if (btn->down) {

            s->mouse_buttons |= bmap[btn->button];

            if (btn->button == INPUT_BUTTON_WHEEL_UP) {

                s->mouse_dz--;

            } else if (btn->button == INPUT_BUTTON_WHEEL_DOWN) {

                s->mouse_dz++;

            }

        } else {

            s->mouse_buttons &= ~bmap[btn->button];

        }

        break;



    default:

        /* keep gcc happy */

        break;

    }

}

static void qdev_prop_set_globals_for_type(DeviceState *dev,

                                           const char *typename)

{

    GList *l;



    for (l = global_props; l; l = l->next) {

        GlobalProperty *prop = l->data;

        Error *err = NULL;



        if (strcmp(typename, prop->driver) != 0) {

            continue;

        }

        prop->used = true;

        object_property_parse(OBJECT(dev), prop->value, prop->property, &err);

        if (err != NULL) {

            error_prepend(&err, "can't apply global %s.%s=%s: ",

                          prop->driver, prop->property, prop->value);

            if (!dev->hotplugged && prop->errp) {

                error_propagate(prop->errp, err);

            } else {

                assert(prop->user_provided);

                warn_report_err(err);

            }

        }

    }

}

static void set_chr(Object *obj, Visitor *v, const char *name, void *opaque,

                    Error **errp)

{

    DeviceState *dev = DEVICE(obj);

    Error *local_err = NULL;

    Property *prop = opaque;

    CharBackend *be = qdev_get_prop_ptr(dev, prop);

    CharDriverState *s;

    char *str;



    if (dev->realized) {

        qdev_prop_set_after_realize(dev, name, errp);

        return;

    }



    visit_type_str(v, name, &str, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    if (!*str) {

        g_free(str);

        be->chr = NULL;

        return;

    }



    s = qemu_chr_find(str);

    g_free(str);

    if (s == NULL) {

        error_setg(errp, "Property '%s.%s' can't find value '%s'",

                   object_get_typename(obj), prop->name, str);

        return;

    }



    if (!qemu_chr_fe_init(be, s, errp)) {

        error_prepend(errp, "Property '%s.%s' can't take value '%s': ",

                      object_get_typename(obj), prop->name, str);

        return;

    }

}

static void set_bit(Object *obj, Visitor *v, void *opaque,

                    const char *name, Error **errp)

{

    DeviceState *dev = DEVICE(obj);

    Property *prop = opaque;

    Error *local_err = NULL;

    bool value;



    if (dev->realized) {

        qdev_prop_set_after_realize(dev, name, errp);

        return;

    }



    visit_type_bool(v, &value, name, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }

    bit_prop_set(dev, prop, value);

}

void qdev_property_add_static(DeviceState *dev, Property *prop,

                              Error **errp)

{

    Error *local_err = NULL;

    Object *obj = OBJECT(dev);



    /*

     * TODO qdev_prop_ptr does not have getters or setters.  It must

     * go now that it can be replaced with links.  The test should be

     * removed along with it: all static properties are read/write.

     */

    if (!prop->info->get && !prop->info->set) {

        return;

    }



    object_property_add(obj, prop->name, prop->info->name,

                        prop->info->get, prop->info->set,

                        prop->info->release,

                        prop, &local_err);



    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    object_property_set_description(obj, prop->name,

                                    prop->info->description,

                                    &error_abort);



    if (prop->info->set_default_value) {

        prop->info->set_default_value(obj, prop);

    }

}

static int scsi_write_data(SCSIRequest *req)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    uint32_t n;



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    n = r->iov.iov_len / 512;

    if (n) {

        qemu_iovec_init_external(&r->qiov, &r->iov, 1);

        r->req.aiocb = bdrv_aio_writev(s->bs, r->sector, &r->qiov, n,

                                   scsi_write_complete, r);

        if (r->req.aiocb == NULL) {

            scsi_write_complete(r, -EIO);

        }

    } else {

        /* Invoke completion routine to fetch data from host.  */

        scsi_write_complete(r, 0);

    }



    return 0;

}

static void scsi_write_request(SCSIDiskReq *r)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    uint32_t n;



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    n = r->iov.iov_len / 512;

    if (n) {

        qemu_iovec_init_external(&r->qiov, &r->iov, 1);

        r->req.aiocb = bdrv_aio_writev(s->bs, r->sector, &r->qiov, n,

                                   scsi_write_complete, r);

        if (r->req.aiocb == NULL) {

            scsi_write_complete(r, -EIO);

        }

    } else {

        /* Invoke completion routine to fetch data from host.  */

        scsi_write_complete(r, 0);

    }

}

static void scsi_write_data(SCSIRequest *req)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    SCSIDiskClass *sdc = (SCSIDiskClass *) object_get_class(OBJECT(s));



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    /* The request is used as the AIO opaque value, so add a ref.  */

    scsi_req_ref(&r->req);

    if (r->req.cmd.mode != SCSI_XFER_TO_DEV) {

        DPRINTF("Data transfer direction invalid\n");

        scsi_write_complete_noio(r, -EINVAL);

        return;

    }



    if (!r->req.sg && !r->qiov.size) {

        /* Called for the first time.  Ask the driver to send us more data.  */

        r->started = true;

        scsi_write_complete_noio(r, 0);

        return;

    }

    if (s->tray_open) {

        scsi_write_complete_noio(r, -ENOMEDIUM);

        return;

    }



    if (r->req.cmd.buf[0] == VERIFY_10 || r->req.cmd.buf[0] == VERIFY_12 ||

        r->req.cmd.buf[0] == VERIFY_16) {

        if (r->req.sg) {

            scsi_dma_complete_noio(r, 0);

        } else {

            scsi_write_complete_noio(r, 0);

        }

        return;

    }



    if (r->req.sg) {

        dma_acct_start(s->qdev.conf.blk, &r->acct, r->req.sg, BLOCK_ACCT_WRITE);

        r->req.resid -= r->req.sg->size;

        r->req.aiocb = dma_blk_io(blk_get_aio_context(s->qdev.conf.blk),

                                  r->req.sg, r->sector << BDRV_SECTOR_BITS,

                                  sdc->dma_writev, r, scsi_dma_complete, r,

                                  DMA_DIRECTION_TO_DEVICE);

    } else {

        block_acct_start(blk_get_stats(s->qdev.conf.blk), &r->acct,

                         r->qiov.size, BLOCK_ACCT_WRITE);

        r->req.aiocb = sdc->dma_writev(r->sector << BDRV_SECTOR_BITS, &r->qiov,

                                       scsi_write_complete, r, r);

    }

}

static void scsi_read_data(SCSIRequest *req)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    bool first;



    DPRINTF("Read sector_count=%d\n", r->sector_count);

    if (r->sector_count == 0) {

        /* This also clears the sense buffer for REQUEST SENSE.  */

        scsi_req_complete(&r->req, GOOD);

        return;

    }



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    /* The request is used as the AIO opaque value, so add a ref.  */

    scsi_req_ref(&r->req);

    if (r->req.cmd.mode == SCSI_XFER_TO_DEV) {

        DPRINTF("Data transfer direction invalid\n");

        scsi_read_complete(r, -EINVAL);

        return;

    }



    if (s->tray_open) {

        scsi_read_complete(r, -ENOMEDIUM);

        return;

    }



    first = !r->started;

    r->started = true;

    if (first && r->need_fua_emulation) {

        block_acct_start(blk_get_stats(s->qdev.conf.blk), &r->acct, 0,

                         BLOCK_ACCT_FLUSH);

        r->req.aiocb = blk_aio_flush(s->qdev.conf.blk, scsi_do_read_cb, r);

    } else {

        scsi_do_read(r, 0);

    }

}

