MigrationState *unix_start_outgoing_migration(Monitor *mon,

                                              const char *path,

					      int64_t bandwidth_limit,

					      int detach,

					      int blk,

					      int inc)

{

    FdMigrationState *s;

    struct sockaddr_un addr;

    int ret;



    addr.sun_family = AF_UNIX;

    snprintf(addr.sun_path, sizeof(addr.sun_path), "%s", path);



    s = qemu_mallocz(sizeof(*s));



    s->get_error = unix_errno;

    s->write = unix_write;

    s->close = unix_close;

    s->mig_state.cancel = migrate_fd_cancel;

    s->mig_state.get_status = migrate_fd_get_status;

    s->mig_state.release = migrate_fd_release;



    s->mig_state.blk = blk;

    s->mig_state.shared = inc;



    s->state = MIG_STATE_ACTIVE;

    s->mon = NULL;

    s->bandwidth_limit = bandwidth_limit;

    s->fd = socket(PF_UNIX, SOCK_STREAM, 0);

    if (s->fd < 0) {

        dprintf("Unable to open socket");

        goto err_after_alloc;

    }



    socket_set_nonblock(s->fd);



    if (!detach) {

        migrate_fd_monitor_suspend(s, mon);

    }



    do {

        ret = connect(s->fd, (struct sockaddr *)&addr, sizeof(addr));

        if (ret == -1)

	    ret = -(s->get_error(s));



        if (ret == -EINPROGRESS || ret == -EWOULDBLOCK)

	    qemu_set_fd_handler2(s->fd, NULL, NULL, unix_wait_for_connect, s);

    } while (ret == -EINTR);



    if (ret < 0 && ret != -EINPROGRESS && ret != -EWOULDBLOCK) {

        dprintf("connect failed\n");

        goto err_after_open;

    } else if (ret >= 0)

        migrate_fd_connect(s);



    return &s->mig_state;



err_after_open:

    close(s->fd);



err_after_alloc:

    qemu_free(s);

    return NULL;

}

int tcp_start_outgoing_migration(MigrationState *s, const char *host_port,

                                 Error **errp)

{

    s->get_error = socket_errno;

    s->write = socket_write;

    s->close = tcp_close;



    s->fd = inet_connect(host_port, false, NULL, errp);



    if (!error_is_set(errp)) {

        migrate_fd_connect(s);

    } else if (error_is_type(*errp, QERR_SOCKET_CONNECT_IN_PROGRESS)) {

        DPRINTF("connect in progress\n");

        qemu_set_fd_handler2(s->fd, NULL, NULL, tcp_wait_for_connect, s);

    } else if (error_is_type(*errp, QERR_SOCKET_CREATE_FAILED)) {

        DPRINTF("connect failed\n");

        return -1;

    } else if (error_is_type(*errp, QERR_SOCKET_CONNECT_FAILED)) {

        DPRINTF("connect failed\n");

        migrate_fd_error(s);

        return -1;

    } else {

        DPRINTF("unknown error\n");

        return -1;

    }



    return 0;

}

MigrationState *tcp_start_outgoing_migration(const char *host_port,

					     int64_t bandwidth_limit,

					     int async)

{

    struct sockaddr_in addr;

    FdMigrationState *s;

    int ret;



    if (parse_host_port(&addr, host_port) < 0)

        return NULL;



    s = qemu_mallocz(sizeof(*s));

    if (s == NULL)

        return NULL;



    s->mig_state.cancel = tcp_cancel;

    s->mig_state.get_status = tcp_get_status;

    s->mig_state.release = tcp_release;



    s->state = MIG_STATE_ACTIVE;

    s->detach = !async;

    s->bandwidth_limit = bandwidth_limit;

    s->fd = socket(PF_INET, SOCK_STREAM, 0);

    if (s->fd == -1) {

        qemu_free(s);

	return NULL;

    }



    fcntl(s->fd, F_SETFL, O_NONBLOCK);



    if (s->detach == 1) {

        dprintf("detaching from monitor\n");

        monitor_suspend();

	s->detach = 2;

    }



    do {

        ret = connect(s->fd, (struct sockaddr *)&addr, sizeof(addr));

        if (ret == -1)

            ret = -errno;



        if (ret == -EINPROGRESS)

            qemu_set_fd_handler2(s->fd, NULL, NULL, tcp_wait_for_connect, s);

    } while (ret == -EINTR);



    if (ret < 0 && ret != -EINPROGRESS) {

        dprintf("connect failed\n");

        close(s->fd);

        qemu_free(s);

	s = NULL;

    } else if (ret >= 0)

        tcp_connect_migrate(s);



    return &s->mig_state;

}

int tcp_start_outgoing_migration(MigrationState *s, const char *host_port,

                                 Error **errp)

{

    s->get_error = socket_errno;

    s->write = socket_write;

    s->close = tcp_close;



