static target_ulong h_put_tce(PowerPCCPU *cpu, sPAPREnvironment *spapr,

                              target_ulong opcode, target_ulong *args)

{

    target_ulong liobn = args[0];

    target_ulong ioba = args[1];

    target_ulong tce = args[2];

    sPAPRTCETable *tcet = spapr_tce_find_by_liobn(liobn);



    if (liobn & 0xFFFFFFFF00000000ULL) {

        hcall_dprintf("spapr_vio_put_tce on out-of-boundsw LIOBN "

                      TARGET_FMT_lx "\n", liobn);

        return H_PARAMETER;

    }



    ioba &= ~(SPAPR_TCE_PAGE_SIZE - 1);



    if (tcet) {

        return put_tce_emu(tcet, ioba, tce);

    }

#ifdef DEBUG_TCE

    fprintf(stderr, "%s on liobn=" TARGET_FMT_lx /*%s*/

            "  ioba 0x" TARGET_FMT_lx "  TCE 0x" TARGET_FMT_lx "\n",

            __func__, liobn, /*dev->qdev.id, */ioba, tce);

#endif



    return H_PARAMETER;

}

static target_ulong h_add_logical_lan_buffer(CPUPPCState *env,

                                             sPAPREnvironment *spapr,

                                             target_ulong opcode,

                                             target_ulong *args)

{

    target_ulong reg = args[0];

    target_ulong buf = args[1];

    VIOsPAPRDevice *sdev = spapr_vio_find_by_reg(spapr->vio_bus, reg);

    VIOsPAPRVLANDevice *dev = (VIOsPAPRVLANDevice *)sdev;

    vlan_bd_t bd;



    dprintf("H_ADD_LOGICAL_LAN_BUFFER(0x" TARGET_FMT_lx

            ", 0x" TARGET_FMT_lx ")\n", reg, buf);



    if (!sdev) {

        hcall_dprintf("Bad device\n");

        return H_PARAMETER;

    }



    if ((check_bd(dev, buf, 4) < 0)

        || (VLAN_BD_LEN(buf) < 16)) {

        hcall_dprintf("Bad buffer enqueued\n");

        return H_PARAMETER;

    }



    if (!dev->isopen || dev->rx_bufs >= VLAN_MAX_BUFS) {

        return H_RESOURCE;

    }



    do {

        dev->add_buf_ptr += 8;

        if (dev->add_buf_ptr >= SPAPR_VIO_TCE_PAGE_SIZE) {

            dev->add_buf_ptr = VLAN_RX_BDS_OFF;

        }



        bd = ldq_tce(sdev, dev->buf_list + dev->add_buf_ptr);

    } while (bd & VLAN_BD_VALID);



    stq_tce(sdev, dev->buf_list + dev->add_buf_ptr, buf);



    dev->rx_bufs++;



    dprintf("h_add_logical_lan_buffer():  Added buf  ptr=%d  rx_bufs=%d"

            " bd=0x%016llx\n", dev->add_buf_ptr, dev->rx_bufs,

            (unsigned long long)buf);



    return H_SUCCESS;

}

static target_ulong h_vio_signal(CPUState *env, sPAPREnvironment *spapr,

                                 target_ulong opcode,

                                 target_ulong *args)

{

    target_ulong reg = args[0];

    target_ulong mode = args[1];

    VIOsPAPRDevice *dev = spapr_vio_find_by_reg(spapr->vio_bus, reg);

    VIOsPAPRDeviceInfo *info;



    if (!dev) {

        return H_PARAMETER;

    }



    info = (VIOsPAPRDeviceInfo *)qdev_get_info(&dev->qdev);



    if (mode & ~info->signal_mask) {

        return H_PARAMETER;

    }



    dev->signal_state = mode;



    return H_SUCCESS;

}

static target_ulong h_add_logical_lan_buffer(PowerPCCPU *cpu,

                                             sPAPRMachineState *spapr,

                                             target_ulong opcode,

                                             target_ulong *args)

{

    target_ulong reg = args[0];

    target_ulong buf = args[1];

    VIOsPAPRDevice *sdev = spapr_vio_find_by_reg(spapr->vio_bus, reg);

    VIOsPAPRVLANDevice *dev = VIO_SPAPR_VLAN_DEVICE(sdev);

    target_long ret;



    DPRINTF("H_ADD_LOGICAL_LAN_BUFFER(0x" TARGET_FMT_lx

            ", 0x" TARGET_FMT_lx ")\n", reg, buf);



    if (!sdev) {

        hcall_dprintf("Bad device\n");

        return H_PARAMETER;

    }



    if ((check_bd(dev, buf, 4) < 0)

        || (VLAN_BD_LEN(buf) < 16)) {

        hcall_dprintf("Bad buffer enqueued\n");

        return H_PARAMETER;

    }



    if (!dev->isopen) {

        return H_RESOURCE;

    }



    ret = spapr_vlan_add_rxbuf_to_page(dev, buf);

    if (ret) {

        return ret;

    }



    dev->rx_bufs++;



    qemu_flush_queued_packets(qemu_get_queue(dev->nic));



    return H_SUCCESS;

}

