static void filter(SPPContext *p, uint8_t *dst, uint8_t *src,

                   int dst_linesize, int src_linesize, int width, int height,

                   const uint8_t *qp_table, int qp_stride, int is_luma, int sample_bytes)

{

    int x, y, i;

    const int count = 1 << p->log2_count;

    const int linesize = is_luma ? p->temp_linesize : FFALIGN(width+16, 16);

    DECLARE_ALIGNED(16, uint64_t, block_align)[32];

    int16_t *block  = (int16_t *)block_align;

    int16_t *block2 = (int16_t *)(block_align + 16);

    uint16_t *psrc16 = (uint16_t*)p->src;



    for (y = 0; y < height; y++) {

        int index = 8 + 8*linesize + y*linesize;

        memcpy(p->src + index*sample_bytes, src + y*src_linesize, width*sample_bytes);

        if (sample_bytes == 1) {

            for (x = 0; x < 8; x++) {

                p->src[index         - x - 1] = p->src[index +         x    ];

                p->src[index + width + x    ] = p->src[index + width - x - 1];

            }

        } else {

            for (x = 0; x < 8; x++) {

                psrc16[index         - x - 1] = psrc16[index +         x    ];

                psrc16[index + width + x    ] = psrc16[index + width - x - 1];

            }

        }

    }

    for (y = 0; y < 8; y++) {

        memcpy(p->src + (       7-y)*linesize * sample_bytes, p->src + (       y+8)*linesize * sample_bytes, linesize * sample_bytes);

        memcpy(p->src + (height+8+y)*linesize * sample_bytes, p->src + (height-y+7)*linesize * sample_bytes, linesize * sample_bytes);

    }



    for (y = 0; y < height + 8; y += 8) {

        memset(p->temp + (8 + y) * linesize, 0, 8 * linesize * sizeof(*p->temp));

        for (x = 0; x < width + 8; x += 8) {

            int qp;



            if (p->qp) {

                qp = p->qp;

            } else{

                const int qps = 3 + is_luma;

                qp = qp_table[(FFMIN(x, width - 1) >> qps) + (FFMIN(y, height - 1) >> qps) * qp_stride];

                qp = FFMAX(1, norm_qscale(qp, p->qscale_type));

            }

            for (i = 0; i < count; i++) {

                const int x1 = x + offset[i + count - 1][0];

                const int y1 = y + offset[i + count - 1][1];

                const int index = x1 + y1*linesize;

                p->dct->get_pixels(block, p->src + sample_bytes*index, sample_bytes*linesize);

                p->dct->fdct(block);

                p->requantize(block2, block, qp, p->dct->idct_permutation);

                p->dct->idct(block2);

                add_block(p->temp + index, linesize, block2);

            }

        }

        if (y) {

            if (sample_bytes == 1) {

                p->store_slice(dst + (y - 8) * dst_linesize, p->temp + 8 + y*linesize,

                               dst_linesize, linesize, width,

                               FFMIN(8, height + 8 - y), MAX_LEVEL - p->log2_count,

                               ldither);

            } else {

                store_slice16_c((uint16_t*)(dst + (y - 8) * dst_linesize), p->temp + 8 + y*linesize,

                                dst_linesize/2, linesize, width,

                                FFMIN(8, height + 8 - y), MAX_LEVEL - p->log2_count,

                                ldither);

            }

        }

    }

}

static void RENAME(decode_rgb_frame)(FFV1Context *s, uint8_t *src[3], int w, int h, int stride[3])

{

    int x, y, p;

    TYPE *sample[4][2];

    int lbd    = s->avctx->bits_per_raw_sample <= 8;

    int bits   = s->avctx->bits_per_raw_sample > 0 ? s->avctx->bits_per_raw_sample : 8;

    int offset = 1 << bits;



    for (x = 0; x < 4; x++) {

        sample[x][0] = RENAME(s->sample_buffer) +  x * 2      * (w + 6) + 3;

        sample[x][1] = RENAME(s->sample_buffer) + (x * 2 + 1) * (w + 6) + 3;

    }



    s->run_index = 0;



    memset(RENAME(s->sample_buffer), 0, 8 * (w + 6) * sizeof(*RENAME(s->sample_buffer)));



    for (y = 0; y < h; y++) {

        for (p = 0; p < 3 + s->transparency; p++) {

            TYPE *temp = sample[p][0]; // FIXME: try a normal buffer



            sample[p][0] = sample[p][1];

            sample[p][1] = temp;



            sample[p][1][-1]= sample[p][0][0  ];

            sample[p][0][ w]= sample[p][0][w-1];

            if (lbd && s->slice_coding_mode == 0)

                RENAME(decode_line)(s, w, sample[p], (p + 1)/2, 9);

            else

                RENAME(decode_line)(s, w, sample[p], (p + 1)/2, bits + (s->slice_coding_mode != 1));

        }

        for (x = 0; x < w; x++) {

            int g = sample[0][1][x];

            int b = sample[1][1][x];

            int r = sample[2][1][x];

            int a = sample[3][1][x];



            if (s->slice_coding_mode != 1) {

                b -= offset;

                r -= offset;

                g -= (b * s->slice_rct_by_coef + r * s->slice_rct_ry_coef) >> 2;

                b += g;

                r += g;

            }



            if (lbd)

                *((uint32_t*)(src[0] + x*4 + stride[0]*y)) = b + (g<<8) + (r<<16) + (a<<24);

            else if (sizeof(TYPE) == 4) {

                *((uint16_t*)(src[0] + x*2 + stride[0]*y)) = g;

                *((uint16_t*)(src[1] + x*2 + stride[1]*y)) = b;

                *((uint16_t*)(src[2] + x*2 + stride[2]*y)) = r;

            } else {

                *((uint16_t*)(src[0] + x*2 + stride[0]*y)) = b;

                *((uint16_t*)(src[1] + x*2 + stride[1]*y)) = g;

                *((uint16_t*)(src[2] + x*2 + stride[2]*y)) = r;

            }

        }

    }

}

static void apply_unsharp(      uint8_t *dst, int dst_stride,

                          const uint8_t *src, int src_stride,

                          int width, int height, FilterParam *fp)

{

    uint32_t **sc = fp->sc;

    uint32_t sr[MAX_MATRIX_SIZE - 1], tmp1, tmp2;



    int32_t res;

    int x, y, z;

    const uint8_t *src2 = NULL;  //silence a warning



    if (!fp->amount) {

        if (dst_stride == src_stride)

            memcpy(dst, src, src_stride * height);

        else

            for (y = 0; y < height; y++, dst += dst_stride, src += src_stride)

                memcpy(dst, src, width);

        return;

    }



    for (y = 0; y < 2 * fp->steps_y; y++)

        memset(sc[y], 0, sizeof(sc[y][0]) * (width + 2 * fp->steps_x));



    for (y = -fp->steps_y; y < height + fp->steps_y; y++) {

        if (y < height)

            src2 = src;



        memset(sr, 0, sizeof(sr[0]) * (2 * fp->steps_x - 1));

        for (x = -fp->steps_x; x < width + fp->steps_x; x++) {

            tmp1 = x <= 0 ? src2[0] : x >= width ? src2[width-1] : src2[x];

            for (z = 0; z < fp->steps_x * 2; z += 2) {

                tmp2 = sr[z + 0] + tmp1; sr[z + 0] = tmp1;

                tmp1 = sr[z + 1] + tmp2; sr[z + 1] = tmp2;

            }

            for (z = 0; z < fp->steps_y * 2; z += 2) {

                tmp2 = sc[z + 0][x + fp->steps_x] + tmp1; sc[z + 0][x + fp->steps_x] = tmp1;

                tmp1 = sc[z + 1][x + fp->steps_x] + tmp2; sc[z + 1][x + fp->steps_x] = tmp2;

            }

            if (x >= fp->steps_x && y >= fp->steps_y) {

                const uint8_t *srx = src - fp->steps_y * src_stride + x - fp->steps_x;

                uint8_t *dsx       = dst - fp->steps_y * dst_stride + x - fp->steps_x;



                res = (int32_t)*srx + ((((int32_t) * srx - (int32_t)((tmp1 + fp->halfscale) >> fp->scalebits)) * fp->amount) >> 16);

                *dsx = av_clip_uint8(res);

            }

        }

        if (y >= 0) {

            dst += dst_stride;

            src += src_stride;

        }

    }

}

static void encode_rgb_frame(FFV1Context *s, uint8_t *src[3], int w, int h, int stride[3])

{

    int x, y, p, i;

    const int ring_size = s->avctx->context_model ? 3 : 2;

    int16_t *sample[4][3];

    int lbd    = s->bits_per_raw_sample <= 8;

    int bits   = s->bits_per_raw_sample > 0 ? s->bits_per_raw_sample : 8;

    int offset = 1 << bits;



    s->run_index = 0;



    memset(s->sample_buffer, 0, ring_size * MAX_PLANES *

                                (w + 6) * sizeof(*s->sample_buffer));



    for (y = 0; y < h; y++) {

        for (i = 0; i < ring_size; i++)

            for (p = 0; p < MAX_PLANES; p++)

                sample[p][i]= s->sample_buffer + p*ring_size*(w+6) + ((h+i-y)%ring_size)*(w+6) + 3;



        for (x = 0; x < w; x++) {

            int b, g, r, av_uninit(a);

            if (lbd) {

                unsigned v = *((uint32_t*)(src[0] + x*4 + stride[0]*y));

                b =  v        & 0xFF;

                g = (v >>  8) & 0xFF;

                r = (v >> 16) & 0xFF;

                a =  v >> 24;

            } else {

                b = *((uint16_t*)(src[0] + x*2 + stride[0]*y));

                g = *((uint16_t*)(src[1] + x*2 + stride[1]*y));

                r = *((uint16_t*)(src[2] + x*2 + stride[2]*y));

            }



            b -= g;

            r -= g;

            g += (b + r) >> 2;

            b += offset;

            r += offset;



            sample[0][0][x] = g;

            sample[1][0][x] = b;

            sample[2][0][x] = r;

            sample[3][0][x] = a;

        }

        for (p = 0; p < 3 + s->transparency; p++) {

            sample[p][0][-1] = sample[p][1][0  ];

            sample[p][1][ w] = sample[p][1][w-1];

            if (lbd)

                encode_line(s, w, sample[p], (p + 1) / 2, 9);

            else

                encode_line(s, w, sample[p], (p + 1) / 2, bits + 1);

        }

    }

}

