static always_inline target_ulong MASK (uint32_t start, uint32_t end)

{

    target_ulong ret;



#if defined(TARGET_PPC64)

    if (likely(start == 0)) {

        ret = (uint64_t)(-1ULL) << (63 - end);

    } else if (likely(end == 63)) {

        ret = (uint64_t)(-1ULL) >> start;

    }

#else

    if (likely(start == 0)) {

        ret = (uint32_t)(-1ULL) << (31  - end);

    } else if (likely(end == 31)) {

        ret = (uint32_t)(-1ULL) >> start;

    }

#endif

    else {

        ret = (((target_ulong)(-1ULL)) >> (start)) ^

            (((target_ulong)(-1ULL) >> (end)) >> 1);

        if (unlikely(start > end))

            return ~ret;

    }



    return ret;

}

static void pollfds_poll(GArray *pollfds, int nfds, fd_set *rfds,

                         fd_set *wfds, fd_set *xfds)

{

    int i;



    for (i = 0; i < pollfds->len; i++) {

        GPollFD *pfd = &g_array_index(pollfds, GPollFD, i);

        int fd = pfd->fd;

        int revents = 0;



        if (FD_ISSET(fd, rfds)) {

            revents |= G_IO_IN | G_IO_HUP | G_IO_ERR;

        }

        if (FD_ISSET(fd, wfds)) {

            revents |= G_IO_OUT | G_IO_ERR;

        }

        if (FD_ISSET(fd, xfds)) {

            revents |= G_IO_PRI;

        }

        pfd->revents = revents & pfd->events;

    }

}

static int pollfds_fill(GArray *pollfds, fd_set *rfds, fd_set *wfds,

                        fd_set *xfds)

{

    int nfds = -1;

    int i;



    for (i = 0; i < pollfds->len; i++) {

        GPollFD *pfd = &g_array_index(pollfds, GPollFD, i);

        int fd = pfd->fd;

        int events = pfd->events;

        if (events & (G_IO_IN | G_IO_HUP | G_IO_ERR)) {

            FD_SET(fd, rfds);

            nfds = MAX(nfds, fd);

        }

        if (events & (G_IO_OUT | G_IO_ERR)) {

            FD_SET(fd, wfds);

            nfds = MAX(nfds, fd);

        }

        if (events & G_IO_PRI) {

            FD_SET(fd, xfds);

            nfds = MAX(nfds, fd);

        }

    }

    return nfds;

}

static void pollfds_poll(GArray *pollfds, int nfds, fd_set *rfds,

                         fd_set *wfds, fd_set *xfds)

{

    int i;



    for (i = 0; i < pollfds->len; i++) {

        GPollFD *pfd = &g_array_index(pollfds, GPollFD, i);

        int fd = pfd->fd;

        int revents = 0;



        if (FD_ISSET(fd, rfds)) {

            revents |= G_IO_IN;

        }

        if (FD_ISSET(fd, wfds)) {

            revents |= G_IO_OUT;

        }

        if (FD_ISSET(fd, xfds)) {

            revents |= G_IO_PRI;

        }

        pfd->revents = revents & pfd->events;

    }

}

static void glib_select_fill(int *max_fd, fd_set *rfds, fd_set *wfds,

                             fd_set *xfds, uint32_t *cur_timeout)

{

    GMainContext *context = g_main_context_default();

    int i;

    int timeout = 0;



    g_main_context_prepare(context, &max_priority);



    n_poll_fds = g_main_context_query(context, max_priority, &timeout,

                                      poll_fds, ARRAY_SIZE(poll_fds));

    g_assert(n_poll_fds <= ARRAY_SIZE(poll_fds));



    for (i = 0; i < n_poll_fds; i++) {

        GPollFD *p = &poll_fds[i];



        if ((p->events & G_IO_IN)) {

            FD_SET(p->fd, rfds);

            *max_fd = MAX(*max_fd, p->fd);

        }

        if ((p->events & G_IO_OUT)) {

            FD_SET(p->fd, wfds);

            *max_fd = MAX(*max_fd, p->fd);

        }

        if ((p->events & G_IO_ERR)) {

            FD_SET(p->fd, xfds);

            *max_fd = MAX(*max_fd, p->fd);

        }

    }



    if (timeout >= 0 && timeout < *cur_timeout) {

        *cur_timeout = timeout;

    }

}

static int decode_frame(AVCodecContext *avctx,

                        void *data, int *got_frame, AVPacket *avpkt)

{

    TiffContext *const s = avctx->priv_data;

    AVFrame *const p = data;

    ThreadFrame frame = { .f = data };

    unsigned off;

    int le, ret, plane, planes;

    int i, j, entries, stride;

    unsigned soff, ssize;

    uint8_t *dst;

    GetByteContext stripsizes;

    GetByteContext stripdata;



    bytestream2_init(&s->gb, avpkt->data, avpkt->size);



    // parse image header

    if ((ret = ff_tdecode_header(&s->gb, &le, &off))) {

        av_log(avctx, AV_LOG_ERROR, "Invalid TIFF header\n");

        return ret;

    } else if (off >= UINT_MAX - 14 || avpkt->size < off + 14) {

        av_log(avctx, AV_LOG_ERROR, "IFD offset is greater than image size\n");

        return AVERROR_INVALIDDATA;

    }

    s->le          = le;

    // TIFF_BPP is not a required tag and defaults to 1

    s->bppcount    = s->bpp = 1;

    s->photometric = TIFF_PHOTOMETRIC_NONE;

    s->compr       = TIFF_RAW;

    s->fill_order  = 0;

    free_geotags(s);



    // Reset these offsets so we can tell if they were set this frame

    s->stripsizesoff = s->strippos = 0;

    /* parse image file directory */

    bytestream2_seek(&s->gb, off, SEEK_SET);

    entries = ff_tget_short(&s->gb, le);

    if (bytestream2_get_bytes_left(&s->gb) < entries * 12)

        return AVERROR_INVALIDDATA;

    for (i = 0; i < entries; i++) {

        if ((ret = tiff_decode_tag(s, p)) < 0)

            return ret;

    }



    for (i = 0; i<s->geotag_count; i++) {

        const char *keyname = get_geokey_name(s->geotags[i].key);

        if (!keyname) {

            av_log(avctx, AV_LOG_WARNING, "Unknown or unsupported GeoTIFF key %d\n", s->geotags[i].key);

            continue;

        }

        if (get_geokey_type(s->geotags[i].key) != s->geotags[i].type) {

            av_log(avctx, AV_LOG_WARNING, "Type of GeoTIFF key %d is wrong\n", s->geotags[i].key);

            continue;

        }

        ret = av_dict_set(&p->metadata, keyname, s->geotags[i].val, 0);

        if (ret<0) {

            av_log(avctx, AV_LOG_ERROR, "Writing metadata with key '%s' failed\n", keyname);

            return ret;

        }

    }



    if (!s->strippos && !s->stripoff) {

        av_log(avctx, AV_LOG_ERROR, "Image data is missing\n");

        return AVERROR_INVALIDDATA;

    }

    /* now we have the data and may start decoding */

    if ((ret = init_image(s, &frame)) < 0)

        return ret;



    if (s->strips == 1 && !s->stripsize) {

        av_log(avctx, AV_LOG_WARNING, "Image data size missing\n");

        s->stripsize = avpkt->size - s->stripoff;

    }



    if (s->stripsizesoff) {

        if (s->stripsizesoff >= (unsigned)avpkt->size)

            return AVERROR_INVALIDDATA;

        bytestream2_init(&stripsizes, avpkt->data + s->stripsizesoff,

                         avpkt->size - s->stripsizesoff);

    }

    if (s->strippos) {

        if (s->strippos >= (unsigned)avpkt->size)

            return AVERROR_INVALIDDATA;

        bytestream2_init(&stripdata, avpkt->data + s->strippos,

                         avpkt->size - s->strippos);

    }



    if (s->rps <= 0 || s->rps % s->subsampling[1]) {

        av_log(avctx, AV_LOG_ERROR, "rps %d invalid\n", s->rps);

        return AVERROR_INVALIDDATA;

    }



    planes = s->planar ? s->bppcount : 1;

    for (plane = 0; plane < planes; plane++) {

        stride = p->linesize[plane];

        dst = p->data[plane];

        for (i = 0; i < s->height; i += s->rps) {

            if (s->stripsizesoff)

                ssize = ff_tget(&stripsizes, s->sstype, le);

            else

                ssize = s->stripsize;



            if (s->strippos)

                soff = ff_tget(&stripdata, s->sot, le);

            else

                soff = s->stripoff;



            if (soff > avpkt->size || ssize > avpkt->size - soff) {

                av_log(avctx, AV_LOG_ERROR, "Invalid strip size/offset\n");

                return AVERROR_INVALIDDATA;

            }

            if ((ret = tiff_unpack_strip(s, p, dst, stride, avpkt->data + soff, ssize, i,

                                         FFMIN(s->rps, s->height - i))) < 0) {

                if (avctx->err_recognition & AV_EF_EXPLODE)

                    return ret;

                break;

            }

            dst += s->rps * stride;

        }

        if (s->predictor == 2) {

            if (s->photometric == TIFF_PHOTOMETRIC_YCBCR) {

                av_log(s->avctx, AV_LOG_ERROR, "predictor == 2 with YUV is unsupported");

                return AVERROR_PATCHWELCOME;

            }

            dst   = p->data[plane];

            soff  = s->bpp >> 3;

            if (s->planar)

                soff  = FFMAX(soff / s->bppcount, 1);

            ssize = s->width * soff;

            if (s->avctx->pix_fmt == AV_PIX_FMT_RGB48LE ||

                s->avctx->pix_fmt == AV_PIX_FMT_RGBA64LE ||

                s->avctx->pix_fmt == AV_PIX_FMT_GRAY16LE ||

                s->avctx->pix_fmt == AV_PIX_FMT_YA16LE ||

                s->avctx->pix_fmt == AV_PIX_FMT_GBRP16LE ||

                s->avctx->pix_fmt == AV_PIX_FMT_GBRAP16LE) {

                for (i = 0; i < s->height; i++) {

                    for (j = soff; j < ssize; j += 2)

                        AV_WL16(dst + j, AV_RL16(dst + j) + AV_RL16(dst + j - soff));

                    dst += stride;

                }

            } else if (s->avctx->pix_fmt == AV_PIX_FMT_RGB48BE ||

                       s->avctx->pix_fmt == AV_PIX_FMT_RGBA64BE ||

                       s->avctx->pix_fmt == AV_PIX_FMT_GRAY16BE ||

                       s->avctx->pix_fmt == AV_PIX_FMT_YA16BE ||

                       s->avctx->pix_fmt == AV_PIX_FMT_GBRP16BE ||

                       s->avctx->pix_fmt == AV_PIX_FMT_GBRAP16BE) {

                for (i = 0; i < s->height; i++) {

                    for (j = soff; j < ssize; j += 2)

                        AV_WB16(dst + j, AV_RB16(dst + j) + AV_RB16(dst + j - soff));

                    dst += stride;

                }

            } else {

                for (i = 0; i < s->height; i++) {

                    for (j = soff; j < ssize; j++)

                        dst[j] += dst[j - soff];

                    dst += stride;

                }

            }

        }



        if (s->photometric == TIFF_PHOTOMETRIC_WHITE_IS_ZERO) {

            int c = (s->avctx->pix_fmt == AV_PIX_FMT_PAL8 ? (1<<s->bpp) - 1 : 255);

            dst = p->data[plane];

            for (i = 0; i < s->height; i++) {

                for (j = 0; j < stride; j++)

                    dst[j] = c - dst[j];

                dst += stride;

            }

        }

    }



    if (s->planar && s->bppcount > 2) {

        FFSWAP(uint8_t*, p->data[0],     p->data[2]);

        FFSWAP(int,      p->linesize[0], p->linesize[2]);

        FFSWAP(uint8_t*, p->data[0],     p->data[1]);

        FFSWAP(int,      p->linesize[0], p->linesize[1]);

    }



    *got_frame = 1;



    return avpkt->size;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    UtvideoContext *c = avctx->priv_data;

    int i, j;

    const uint8_t *plane_start[5];

    int plane_size, max_slice_size = 0, slice_start, slice_end, slice_size;

    int ret;

    GetByteContext gb;

    ThreadFrame frame = { .f = data };



    if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0)

        return ret;



    /* parse plane structure to get frame flags and validate slice offsets */

    bytestream2_init(&gb, buf, buf_size);

    for (i = 0; i < c->planes; i++) {

        plane_start[i] = gb.buffer;

        if (bytestream2_get_bytes_left(&gb) < 256 + 4 * c->slices) {

            av_log(avctx, AV_LOG_ERROR, "Insufficient data for a plane\n");

            return AVERROR_INVALIDDATA;

        }

        bytestream2_skipu(&gb, 256);

        slice_start = 0;

        slice_end   = 0;

        for (j = 0; j < c->slices; j++) {

            slice_end   = bytestream2_get_le32u(&gb);

            slice_size  = slice_end - slice_start;

            if (slice_end < 0 || slice_size < 0 ||

                bytestream2_get_bytes_left(&gb) < slice_end) {

                av_log(avctx, AV_LOG_ERROR, "Incorrect slice size\n");

                return AVERROR_INVALIDDATA;

            }

            slice_start = slice_end;

            max_slice_size = FFMAX(max_slice_size, slice_size);

        }

        plane_size = slice_end;

        bytestream2_skipu(&gb, plane_size);

    }

    plane_start[c->planes] = gb.buffer;

    if (bytestream2_get_bytes_left(&gb) < c->frame_info_size) {

        av_log(avctx, AV_LOG_ERROR, "Not enough data for frame information\n");

        return AVERROR_INVALIDDATA;

    }

    c->frame_info = bytestream2_get_le32u(&gb);

    av_log(avctx, AV_LOG_DEBUG, "frame information flags %"PRIX32"\n",

           c->frame_info);



    c->frame_pred = (c->frame_info >> 8) & 3;



    if (c->frame_pred == PRED_GRADIENT) {

        avpriv_request_sample(avctx, "Frame with gradient prediction");

        return AVERROR_PATCHWELCOME;

    }



    av_fast_malloc(&c->slice_bits, &c->slice_bits_size,

                   max_slice_size + AV_INPUT_BUFFER_PADDING_SIZE);



    if (!c->slice_bits) {

        av_log(avctx, AV_LOG_ERROR, "Cannot allocate temporary buffer\n");

        return AVERROR(ENOMEM);

    }



    switch (c->avctx->pix_fmt) {

    case AV_PIX_FMT_RGB24:

    case AV_PIX_FMT_RGBA:

        for (i = 0; i < c->planes; i++) {

            ret = decode_plane(c, i, frame.f->data[0] + ff_ut_rgb_order[i],

                               c->planes, frame.f->linesize[0], avctx->width,

                               avctx->height, plane_start[i],

                               c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[0] + ff_ut_rgb_order[i],

                                   c->planes, frame.f->linesize[0], avctx->width,

                                   avctx->height, c->slices, 0);

                } else {

                    restore_median_il(frame.f->data[0] + ff_ut_rgb_order[i],

                                      c->planes, frame.f->linesize[0],

                                      avctx->width, avctx->height, c->slices,

                                      0);

                }

            }

        }

        restore_rgb_planes(frame.f->data[0], c->planes, frame.f->linesize[0],

                           avctx->width, avctx->height);

        break;

    case AV_PIX_FMT_YUV420P:

        for (i = 0; i < 3; i++) {

            ret = decode_plane(c, i, frame.f->data[i], 1, frame.f->linesize[i],

                               avctx->width >> !!i, avctx->height >> !!i,

                               plane_start[i], c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[i], 1, frame.f->linesize[i],

                                   avctx->width >> !!i, avctx->height >> !!i,

                                   c->slices, !i);

                } else {

                    restore_median_il(frame.f->data[i], 1, frame.f->linesize[i],

                                      avctx->width  >> !!i,

                                      avctx->height >> !!i,

                                      c->slices, !i);

                }

            }

        }

        break;

    case AV_PIX_FMT_YUV422P:

        for (i = 0; i < 3; i++) {

            ret = decode_plane(c, i, frame.f->data[i], 1, frame.f->linesize[i],

                               avctx->width >> !!i, avctx->height,

                               plane_start[i], c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[i], 1, frame.f->linesize[i],

                                   avctx->width >> !!i, avctx->height,

                                   c->slices, 0);

                } else {

                    restore_median_il(frame.f->data[i], 1, frame.f->linesize[i],

                                      avctx->width >> !!i, avctx->height,

                                      c->slices, 0);

                }

            }

        }

        break;

    }



    frame.f->key_frame = 1;

    frame.f->pict_type = AV_PICTURE_TYPE_I;

    frame.f->interlaced_frame = !!c->interlaced;



    *got_frame = 1;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static int decode_frame(AVCodecContext *avctx,

                        void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    TiffContext *const s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame *const p = &s->picture;

    const uint8_t *orig_buf = buf, *end_buf = buf + buf_size;

    unsigned off;

    int id, le, ret;

    int i, j, entries;

    int stride;

    unsigned soff, ssize;

    uint8_t *dst;



    //parse image header

    if (end_buf - buf < 8)

        return AVERROR_INVALIDDATA;

    id = AV_RL16(buf);

    buf += 2;

    if (id == 0x4949)

        le = 1;

    else if (id == 0x4D4D)

        le = 0;

    else {

        av_log(avctx, AV_LOG_ERROR, "TIFF header not found\n");

        return -1;

    }

    s->le = le;

    s->invert = 0;

    s->compr = TIFF_RAW;

    s->fill_order = 0;

    free_geotags(s);

    /* free existing metadata */

    av_dict_free(&s->picture.metadata);



    // As TIFF 6.0 specification puts it "An arbitrary but carefully chosen number

    // that further identifies the file as a TIFF file"

    if (tget_short(&buf, le) != 42) {

        av_log(avctx, AV_LOG_ERROR,

               "The answer to life, universe and everything is not correct!\n");

        return -1;

    }

    // Reset these pointers so we can tell if they were set this frame

    s->stripsizes = s->stripdata = NULL;

    /* parse image file directory */

    off = tget_long(&buf, le);

    if (off >= UINT_MAX - 14 || end_buf - orig_buf < off + 14) {

        av_log(avctx, AV_LOG_ERROR, "IFD offset is greater than image size\n");

        return AVERROR_INVALIDDATA;

    }

    buf = orig_buf + off;

    entries = tget_short(&buf, le);

    for (i = 0; i < entries; i++) {

        if (tiff_decode_tag(s, orig_buf, buf, end_buf) < 0)

            return -1;

        buf += 12;

    }



    for (i = 0; i<s->geotag_count; i++) {

        const char *keyname = get_geokey_name(s->geotags[i].key);

        if (!keyname) {

            av_log(avctx, AV_LOG_WARNING, "Unknown or unsupported GeoTIFF key %d\n", s->geotags[i].key);

            continue;

        }

        if (get_geokey_type(s->geotags[i].key) != s->geotags[i].type) {

            av_log(avctx, AV_LOG_WARNING, "Type of GeoTIFF key %d is wrong\n", s->geotags[i].key);

            continue;

        }

        ret = av_dict_set(&s->picture.metadata, keyname, s->geotags[i].val, 0);

        if (ret<0) {

            av_log(avctx, AV_LOG_ERROR, "Writing metadata with key '%s' failed\n", keyname);

            return ret;

        }

    }



    if (!s->stripdata && !s->stripoff) {

        av_log(avctx, AV_LOG_ERROR, "Image data is missing\n");

        return -1;

    }

    /* now we have the data and may start decoding */

    if ((ret = init_image(s)) < 0)

        return ret;



    if (s->strips == 1 && !s->stripsize) {

        av_log(avctx, AV_LOG_WARNING, "Image data size missing\n");

        s->stripsize = buf_size - s->stripoff;

    }

    stride = p->linesize[0];

    dst = p->data[0];

    for (i = 0; i < s->height; i += s->rps) {

        if (s->stripsizes) {

            if (s->stripsizes >= end_buf)

                return AVERROR_INVALIDDATA;

            ssize = tget(&s->stripsizes, s->sstype, s->le);

        } else

            ssize = s->stripsize;



        if (s->stripdata) {

            if (s->stripdata >= end_buf)

                return AVERROR_INVALIDDATA;

            soff = tget(&s->stripdata, s->sot, s->le);

        } else

            soff = s->stripoff;



        if (soff > buf_size || ssize > buf_size - soff) {

            av_log(avctx, AV_LOG_ERROR, "Invalid strip size/offset\n");

            return -1;

        }

        if (tiff_unpack_strip(s, dst, stride, orig_buf + soff, ssize,

                              FFMIN(s->rps, s->height - i)) < 0)

            break;

        dst += s->rps * stride;

    }

    if (s->predictor == 2) {

        dst = p->data[0];

        soff = s->bpp >> 3;

        ssize = s->width * soff;

        if (s->avctx->pix_fmt == PIX_FMT_RGB48LE ||

            s->avctx->pix_fmt == PIX_FMT_RGBA64LE) {

            for (i = 0; i < s->height; i++) {

                for (j = soff; j < ssize; j += 2)

                    AV_WL16(dst + j, AV_RL16(dst + j) + AV_RL16(dst + j - soff));

                dst += stride;

            }

        } else if (s->avctx->pix_fmt == PIX_FMT_RGB48BE ||

                   s->avctx->pix_fmt == PIX_FMT_RGBA64BE) {

            for (i = 0; i < s->height; i++) {

                for (j = soff; j < ssize; j += 2)

                    AV_WB16(dst + j, AV_RB16(dst + j) + AV_RB16(dst + j - soff));

                dst += stride;

            }

        } else {

            for (i = 0; i < s->height; i++) {

                for (j = soff; j < ssize; j++)

                    dst[j] += dst[j - soff];

                dst += stride;

            }

        }

    }



    if (s->invert) {

        dst = s->picture.data[0];

        for (i = 0; i < s->height; i++) {

            for (j = 0; j < s->picture.linesize[0]; j++)

                dst[j] = (s->avctx->pix_fmt == PIX_FMT_PAL8 ? (1<<s->bpp) - 1 : 255) - dst[j];

            dst += s->picture.linesize[0];

        }

    }

    *picture   = s->picture;

    *data_size = sizeof(AVPicture);



    return buf_size;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame, AVPacket *avpkt)

{

    AVFrame *frame = data;

    DxaDecContext * const c = avctx->priv_data;

    uint8_t *outptr, *srcptr, *tmpptr;

    unsigned long dsize;

    int i, j, compr, ret;

    int stride;

    int pc = 0;

    GetByteContext gb;



    bytestream2_init(&gb, avpkt->data, avpkt->size);



    /* make the palette available on the way out */

    if (bytestream2_peek_le32(&gb) == MKTAG('C','M','A','P')) {

        bytestream2_skip(&gb, 4);

        for(i = 0; i < 256; i++){

            c->pal[i] = 0xFFU << 24 | bytestream2_get_be24(&gb);

        }

        pc = 1;

    }



    if ((ret = ff_get_buffer(avctx, frame, AV_GET_BUFFER_FLAG_REF)) < 0)

        return ret;

    memcpy(frame->data[1], c->pal, AVPALETTE_SIZE);

    frame->palette_has_changed = pc;



    outptr = frame->data[0];

    srcptr = c->decomp_buf;

    tmpptr = c->prev->data[0];

    stride = frame->linesize[0];



    if (bytestream2_get_le32(&gb) == MKTAG('N','U','L','L'))

        compr = -1;

    else

        compr = bytestream2_get_byte(&gb);



    dsize = c->dsize;

    if (compr != 4 && compr != -1) {

        bytestream2_skip(&gb, 4);

        if (uncompress(c->decomp_buf, &dsize, avpkt->data + bytestream2_tell(&gb),

                       bytestream2_get_bytes_left(&gb)) != Z_OK) {

            av_log(avctx, AV_LOG_ERROR, "Uncompress failed!\n");

            return AVERROR_UNKNOWN;

        }

        memset(c->decomp_buf + dsize, 0, DECOMP_BUF_PADDING);

    }



    if (avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(avctx, AV_LOG_DEBUG, "compr:%2d, dsize:%d\n", compr, (int)dsize);



    switch(compr){

    case -1:

        frame->key_frame = 0;

        frame->pict_type = AV_PICTURE_TYPE_P;

        if (c->prev->data[0])

            memcpy(frame->data[0], c->prev->data[0], frame->linesize[0] * avctx->height);

        else{ // Should happen only when first frame is 'NULL'

            memset(frame->data[0], 0, frame->linesize[0] * avctx->height);

            frame->key_frame = 1;

            frame->pict_type = AV_PICTURE_TYPE_I;

        }

        break;

    case 2:

    case 4:

        frame->key_frame = 1;

        frame->pict_type = AV_PICTURE_TYPE_I;

        for (j = 0; j < avctx->height; j++) {

                memcpy(outptr, srcptr, avctx->width);

            outptr += stride;

            srcptr += avctx->width;

        }

        break;

    case 3:

    case 5:

        if (!tmpptr) {

            av_log(avctx, AV_LOG_ERROR, "Missing reference frame.\n");

            if (!(avctx->flags2 & CODEC_FLAG2_SHOW_ALL))

                return AVERROR_INVALIDDATA;

        }

        frame->key_frame = 0;

        frame->pict_type = AV_PICTURE_TYPE_P;

        for (j = 0; j < avctx->height; j++) {

            if(tmpptr){

                for(i = 0; i < avctx->width; i++)

                    outptr[i] = srcptr[i] ^ tmpptr[i];

                tmpptr += stride;

            }else

                memcpy(outptr, srcptr, avctx->width);

            outptr += stride;

            srcptr += avctx->width;

        }

        break;

    case 12: // ScummVM coding

    case 13:

        frame->key_frame = 0;

        frame->pict_type = AV_PICTURE_TYPE_P;

        if (!c->prev->data[0]) {

            av_log(avctx, AV_LOG_ERROR, "Missing reference frame\n");

            return AVERROR_INVALIDDATA;

        }

        decode_13(avctx, c, frame->data[0], frame->linesize[0], srcptr, c->prev->data[0]);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown/unsupported compression type %d\n", compr);

        return AVERROR_INVALIDDATA;

    }



    av_frame_unref(c->prev);

    if ((ret = av_frame_ref(c->prev, frame)) < 0)

        return ret;



    *got_frame = 1;



    /* always report that the buffer was completely consumed */

    return avpkt->size;

}

int attribute_align_arg avcodec_decode_video2(AVCodecContext *avctx, AVFrame *picture,

                                              int *got_picture_ptr,

                                              AVPacket *avpkt)

{

    AVCodecInternal *avci = avctx->internal;

    int ret;



    *got_picture_ptr = 0;

    if ((avctx->coded_width || avctx->coded_height) && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        return -1;



    avctx->internal->pkt = avpkt;

    ret = apply_param_change(avctx, avpkt);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error applying parameter changes.\n");

        if (avctx->err_recognition & AV_EF_EXPLODE)

            return ret;

    }



    avcodec_get_frame_defaults(picture);



    if (!avctx->refcounted_frames)

        av_frame_unref(&avci->to_free);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type & FF_THREAD_FRAME)) {

        if (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME)

            ret = ff_thread_decode_frame(avctx, picture, got_picture_ptr,

                                         avpkt);

        else {

            ret = avctx->codec->decode(avctx, picture, got_picture_ptr,

                                       avpkt);

            picture->pkt_dts = avpkt->dts;

            /* get_buffer is supposed to set frame parameters */

            if (!(avctx->codec->capabilities & CODEC_CAP_DR1)) {

                picture->sample_aspect_ratio = avctx->sample_aspect_ratio;

                picture->width               = avctx->width;

                picture->height              = avctx->height;

                picture->format              = avctx->pix_fmt;

            }

        }



        emms_c(); //needed to avoid an emms_c() call before every return;



        if (ret < 0 && picture->buf[0])

            av_frame_unref(picture);



        if (*got_picture_ptr) {

            if (!avctx->refcounted_frames) {

                avci->to_free = *picture;

                avci->to_free.extended_data = avci->to_free.data;

                memset(picture->buf, 0, sizeof(picture->buf));

            }



            avctx->frame_number++;

        }

    } else

        ret = 0;



    return ret;

}

int attribute_align_arg avcodec_decode_video2(AVCodecContext *avctx, AVFrame *picture,

                         int *got_picture_ptr,

                         AVPacket *avpkt)

{

    int ret;



    *got_picture_ptr= 0;

    if((avctx->coded_width||avctx->coded_height) && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        return -1;



    if((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type&FF_THREAD_FRAME)){

        av_packet_split_side_data(avpkt);

        apply_param_change(avctx, avpkt);

        avctx->pkt = avpkt;

        if (HAVE_THREADS && avctx->active_thread_type&FF_THREAD_FRAME)

             ret = ff_thread_decode_frame(avctx, picture, got_picture_ptr,

                                          avpkt);

        else {

            ret = avctx->codec->decode(avctx, picture, got_picture_ptr,

                              avpkt);

            picture->pkt_dts= avpkt->dts;



            if(!avctx->has_b_frames){

            picture->pkt_pos= avpkt->pos;

            }

            //FIXME these should be under if(!avctx->has_b_frames)

            if (!picture->sample_aspect_ratio.num)

                picture->sample_aspect_ratio = avctx->sample_aspect_ratio;

            if (!picture->width)

                picture->width = avctx->width;

            if (!picture->height)

                picture->height = avctx->height;

            if (picture->format == PIX_FMT_NONE)

                picture->format = avctx->pix_fmt;

        }



        emms_c(); //needed to avoid an emms_c() call before every return;





        if (*got_picture_ptr){

            avctx->frame_number++;

            picture->best_effort_timestamp = guess_correct_pts(avctx,

                                                            picture->pkt_pts,

                                                            picture->pkt_dts);

        }

    }else

        ret= 0;



    return ret;

}

int attribute_align_arg avcodec_decode_video2(AVCodecContext *avctx, AVFrame *picture,

                         int *got_picture_ptr,

                         const AVPacket *avpkt)

{

    int ret;

    // copy to ensure we do not change avpkt

    AVPacket tmp = *avpkt;



    if (avctx->codec->type != AVMEDIA_TYPE_VIDEO) {

        av_log(avctx, AV_LOG_ERROR, "Invalid media type for video\n");

        return AVERROR(EINVAL);

    }



    *got_picture_ptr= 0;

    if((avctx->coded_width||avctx->coded_height) && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        return -1;



    if((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type&FF_THREAD_FRAME)){

        int did_split = av_packet_split_side_data(&tmp);

        apply_param_change(avctx, &tmp);

        avctx->pkt = &tmp;

        if (HAVE_THREADS && avctx->active_thread_type&FF_THREAD_FRAME)

             ret = ff_thread_decode_frame(avctx, picture, got_picture_ptr,

                                          &tmp);

        else {

            ret = avctx->codec->decode(avctx, picture, got_picture_ptr,

                              &tmp);

            picture->pkt_dts= avpkt->dts;



            if(!avctx->has_b_frames){

            picture->pkt_pos= avpkt->pos;

            }

            //FIXME these should be under if(!avctx->has_b_frames)

            if (!picture->sample_aspect_ratio.num)

                picture->sample_aspect_ratio = avctx->sample_aspect_ratio;

            if (!picture->width)

                picture->width = avctx->width;

            if (!picture->height)

                picture->height = avctx->height;

            if (picture->format == PIX_FMT_NONE)

                picture->format = avctx->pix_fmt;

        }



        emms_c(); //needed to avoid an emms_c() call before every return;



        avctx->pkt = NULL;

        if (did_split) {

            ff_packet_free_side_data(&tmp);

            if(ret == tmp.size)

                ret = avpkt->size;

        }



        if (*got_picture_ptr){

            avctx->frame_number++;

            picture->best_effort_timestamp = guess_correct_pts(avctx,

                                                            picture->pkt_pts,

                                                            picture->pkt_dts);

        }

    }else

        ret= 0;



    return ret;

}

int attribute_align_arg avcodec_encode_video2(AVCodecContext *avctx,

                                              AVPacket *avpkt,

                                              const AVFrame *frame,

                                              int *got_packet_ptr)

{

    int ret;

    int user_packet = !!avpkt->data;



    *got_packet_ptr = 0;



    if (!(avctx->codec->capabilities & CODEC_CAP_DELAY) && !frame) {

        av_free_packet(avpkt);

        av_init_packet(avpkt);

        avpkt->size     = 0;

        return 0;

    }



    if (av_image_check_size(avctx->width, avctx->height, 0, avctx))

        return AVERROR(EINVAL);



    av_assert0(avctx->codec->encode2);



    ret = avctx->codec->encode2(avctx, avpkt, frame, got_packet_ptr);

    if (!ret) {

        if (!*got_packet_ptr)

            avpkt->size = 0;

        else if (!(avctx->codec->capabilities & CODEC_CAP_DELAY))

            avpkt->pts = avpkt->dts = frame->pts;



        if (!user_packet && avpkt->data) {

            uint8_t *new_data = av_realloc(avpkt->data, avpkt->size);

            if (new_data)

                avpkt->data = new_data;

        }



        avctx->frame_number++;

    }



    if (ret < 0 || !*got_packet_ptr)

        av_free_packet(avpkt);



    emms_c();

    return ret;

}

static int megasas_ld_get_info_submit(SCSIDevice *sdev, int lun,

                                      MegasasCmd *cmd)

{

    struct mfi_ld_info *info = cmd->iov_buf;

    size_t dcmd_size = sizeof(struct mfi_ld_info);

    uint8_t cdb[6];

    SCSIRequest *req;

    ssize_t len, resid;

    uint16_t sdev_id = ((sdev->id & 0xFF) << 8) | (lun & 0xFF);

    uint64_t ld_size;



    if (!cmd->iov_buf) {

        cmd->iov_buf = g_malloc0(dcmd_size);

        info = cmd->iov_buf;

        megasas_setup_inquiry(cdb, 0x83, sizeof(info->vpd_page83));

        req = scsi_req_new(sdev, cmd->index, lun, cdb, cmd);

        if (!req) {

            trace_megasas_dcmd_req_alloc_failed(cmd->index,

                                                "LD get info vpd inquiry");

            g_free(cmd->iov_buf);

            cmd->iov_buf = NULL;

            return MFI_STAT_FLASH_ALLOC_FAIL;

        }

        trace_megasas_dcmd_internal_submit(cmd->index,

                                           "LD get info vpd inquiry", lun);

        len = scsi_req_enqueue(req);

        if (len > 0) {

            cmd->iov_size = len;

            scsi_req_continue(req);

        }

        return MFI_STAT_INVALID_STATUS;

    }



    info->ld_config.params.state = MFI_LD_STATE_OPTIMAL;

    info->ld_config.properties.ld.v.target_id = lun;

    info->ld_config.params.stripe_size = 3;

    info->ld_config.params.num_drives = 1;

    info->ld_config.params.is_consistent = 1;

    /* Logical device size is in blocks */

    blk_get_geometry(sdev->conf.blk, &ld_size);

    info->size = cpu_to_le64(ld_size);

    memset(info->ld_config.span, 0, sizeof(info->ld_config.span));

    info->ld_config.span[0].start_block = 0;

    info->ld_config.span[0].num_blocks = info->size;

    info->ld_config.span[0].array_ref = cpu_to_le16(sdev_id);



    resid = dma_buf_read(cmd->iov_buf, dcmd_size, &cmd->qsg);

    g_free(cmd->iov_buf);

    cmd->iov_size = dcmd_size - resid;

    cmd->iov_buf = NULL;

    return MFI_STAT_OK;

}

