static int parse_outputs(const char **buf, AVFilterInOut **curr_inputs,

                         AVFilterInOut **open_inputs,

                         AVFilterInOut **open_outputs, AVClass *log_ctx)

{

    int ret, pad = 0;



    while (**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        AVFilterInOut *input = *curr_inputs;







        *curr_inputs = (*curr_inputs)->next;



        if (!name)




        /* First check if the label is not in the open_inputs list */

        match = extract_inout(name, open_inputs);



        if (match) {

            if ((ret = link_filter(input->filter_ctx, input->pad_idx,

                                   match->filter_ctx, match->pad_idx, log_ctx)) < 0)

                return ret;

            av_free(match->name);

            av_free(name);

            av_free(match);

            av_free(input);

        } else {

            /* Not in the list, so add the first input as a open_output */

            input->name = name;

            insert_inout(open_outputs, input);


        *buf += strspn(*buf, WHITESPACES);

        pad++;




    return pad;

static int parse_inputs(const char **buf, AVFilterInOut **currInputs,

                        AVFilterInOut **openLinks, AVClass *log_ctx)

{

    int pad = 0;



    while(**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        if(!name)

            return -1;



        /* First check if the label is not in the openLinks list */

        match = extract_inout(name, openLinks);



        if(match) {

            /* A label of a open link. Make it one of the inputs of the next

               filter */

            if(match->type != LinkTypeOut) {

                av_log(log_ctx, AV_LOG_ERROR,

                       "Label \"%s\" appears twice as input!\n", match->name);

                return -1;

            }


        } else {

            /* Not in the list, so add it as an input */

            match = av_mallocz(sizeof(AVFilterInOut));

            match->name    = name;

            match->type    = LinkTypeIn;

            match->pad_idx = pad;

        }



        insert_inout(currInputs, match);



        *buf += consume_whitespace(*buf);

        pad++;

    }



    return pad;

}

int avfilter_parse_graph(AVFilterGraph *graph, const char *filters,

                         AVFilterInOut *open_inputs,

                         AVFilterInOut *open_outputs, AVClass *log_ctx)

{

    int index = 0;

    char chr = 0;



    AVFilterInOut *curr_inputs = NULL;



    do {

        AVFilterContext *filter;

        filters += consume_whitespace(filters);



        if(parse_inputs(&filters, &curr_inputs, &open_outputs, log_ctx) < 0)

            goto fail;



        filter = parse_filter(&filters, graph, index, log_ctx);



        if(!filter)

            goto fail;



        if(filter->input_count == 1 && !curr_inputs && !index) {

            /* First input can be omitted if it is "[in]" */

            const char *tmp = "[in]";

            if(parse_inputs(&tmp, &curr_inputs, &open_outputs, log_ctx) < 0)

                goto fail;

        }



        if(link_filter_inouts(filter, &curr_inputs, &open_inputs, log_ctx) < 0)

            goto fail;



        if(parse_outputs(&filters, &curr_inputs, &open_inputs, &open_outputs,

                         log_ctx) < 0)

            goto fail;



        filters += consume_whitespace(filters);

        chr = *filters++;



        if(chr == ';' && curr_inputs) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Could not find a output to link when parsing \"%s\"\n",

                   filters - 1);

            goto fail;

        }

        index++;

    } while(chr == ',' || chr == ';');



    if (*filters) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Unable to parse graph description substring: \"%s\"\n",

               filters - 1);

        goto fail;

    }



    if(open_inputs && !strcmp(open_inputs->name, "out") && curr_inputs) {

        /* Last output can be omitted if it is "[out]" */

        const char *tmp = "[out]";

        if(parse_outputs(&tmp, &curr_inputs, &open_inputs,

                         &open_outputs, log_ctx) < 0)

            goto fail;

    }



    return 0;



 fail:

    avfilter_destroy_graph(graph);

    free_inout(open_inputs);

    free_inout(open_outputs);

    free_inout(curr_inputs);

    return -1;

}

int avfilter_graph_parse(AVFilterGraph *graph, const char *filters,

                         AVFilterInOut **open_inputs_ptr, AVFilterInOut **open_outputs_ptr,

                         void *log_ctx)

{

    int index = 0, ret = 0;

    char chr = 0;



    AVFilterInOut *curr_inputs = NULL;

    AVFilterInOut *open_inputs  = open_inputs_ptr  ? *open_inputs_ptr  : NULL;

    AVFilterInOut *open_outputs = open_outputs_ptr ? *open_outputs_ptr : NULL;



    do {

        AVFilterContext *filter;

        const char *filterchain = filters;

        filters += strspn(filters, WHITESPACES);



        if ((ret = parse_inputs(&filters, &curr_inputs, &open_outputs, log_ctx)) < 0)

            goto end;



        if ((ret = parse_filter(&filter, &filters, graph, index, log_ctx)) < 0)

            goto end;



        if (filter->input_count == 1 && !curr_inputs && !index) {

            /* First input pad, assume it is "[in]" if not specified */

            const char *tmp = "[in]";

            if ((ret = parse_inputs(&tmp, &curr_inputs, &open_outputs, log_ctx)) < 0)

                goto end;

        }



        if ((ret = link_filter_inouts(filter, &curr_inputs, &open_inputs, log_ctx)) < 0)

            goto end;



        if ((ret = parse_outputs(&filters, &curr_inputs, &open_inputs, &open_outputs,

                                 log_ctx)) < 0)

            goto end;



        filters += strspn(filters, WHITESPACES);

        chr = *filters++;



        if (chr == ';' && curr_inputs) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Invalid filterchain containing an unlabelled output pad: \"%s\"\n",

                   filterchain);

            ret = AVERROR(EINVAL);

            goto end;

        }

        index++;

    } while (chr == ',' || chr == ';');



    if (chr) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Unable to parse graph description substring: \"%s\"\n",

               filters - 1);

        ret = AVERROR(EINVAL);

        goto end;

    }



    if (open_inputs && !strcmp(open_inputs->name, "out") && curr_inputs) {

        /* Last output pad, assume it is "[out]" if not specified */

        const char *tmp = "[out]";

        if ((ret = parse_outputs(&tmp, &curr_inputs, &open_inputs, &open_outputs,

                                 log_ctx)) < 0)

            goto end;

    }



end:

    /* clear open_in/outputs only if not passed as parameters */

    if (open_inputs_ptr) *open_inputs_ptr = open_inputs;

    else avfilter_inout_free(&open_inputs);

    if (open_outputs_ptr) *open_outputs_ptr = open_outputs;

    else avfilter_inout_free(&open_outputs);

    avfilter_inout_free(&curr_inputs);



    if (ret < 0) {

        for (; graph->filter_count > 0; graph->filter_count--)

            avfilter_free(graph->filters[graph->filter_count - 1]);

        av_freep(&graph->filters);

    }

    return ret;

}

static int virtio_net_device_exit(DeviceState *qdev)

{

    VirtIONet *n = VIRTIO_NET(qdev);

    VirtIODevice *vdev = VIRTIO_DEVICE(qdev);

    int i;



    /* This will stop vhost backend if appropriate. */

    virtio_net_set_status(vdev, 0);



    unregister_savevm(qdev, "virtio-net", n);



    if (n->netclient_name) {

        g_free(n->netclient_name);

        n->netclient_name = NULL;

    }

    if (n->netclient_type) {

        g_free(n->netclient_type);

        n->netclient_type = NULL;

    }



    g_free(n->mac_table.macs);

    g_free(n->vlans);



    for (i = 0; i < n->max_queues; i++) {

        VirtIONetQueue *q = &n->vqs[i];

        NetClientState *nc = qemu_get_subqueue(n->nic, i);



        qemu_purge_queued_packets(nc);



        if (q->tx_timer) {

            timer_del(q->tx_timer);

            timer_free(q->tx_timer);

        } else if (q->tx_bh) {

            qemu_bh_delete(q->tx_bh);

        }

    }



    g_free(n->vqs);

    qemu_del_nic(n->nic);

    virtio_cleanup(vdev);



    return 0;

}

static void virtio_net_set_status(struct VirtIODevice *vdev, uint8_t status)

{

    VirtIONet *n = VIRTIO_NET(vdev);

    VirtIONetQueue *q;

    int i;

    uint8_t queue_status;



    virtio_net_vnet_endian_status(n, status);

    virtio_net_vhost_status(n, status);



    for (i = 0; i < n->max_queues; i++) {

        NetClientState *ncs = qemu_get_subqueue(n->nic, i);

        bool queue_started;

        q = &n->vqs[i];



        if ((!n->multiqueue && i != 0) || i >= n->curr_queues) {

            queue_status = 0;

        } else {

            queue_status = status;

        }

        queue_started =

            virtio_net_started(n, queue_status) && !n->vhost_started;



        if (queue_started) {

            qemu_flush_queued_packets(ncs);

        }



        if (!q->tx_waiting) {

            continue;

        }



        if (queue_started) {

            if (q->tx_timer) {

                timer_mod(q->tx_timer,

                               qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL) + n->tx_timeout);

            } else {

                qemu_bh_schedule(q->tx_bh);

            }

        } else {

            if (q->tx_timer) {

                timer_del(q->tx_timer);

            } else {

                qemu_bh_cancel(q->tx_bh);

            }

            if ((n->status & VIRTIO_NET_S_LINK_UP) == 0 &&

                (queue_status & VIRTIO_CONFIG_S_DRIVER_OK)) {

                /* if tx is waiting we are likely have some packets in tx queue

                 * and disabled notification */

                q->tx_waiting = 0;

                virtio_queue_set_notification(q->tx_vq, 1);

                virtio_net_drop_tx_queue_data(vdev, q->tx_vq);

            }

        }

    }

}

static void virtio_net_set_features(VirtIODevice *vdev, uint64_t features)

{

    VirtIONet *n = VIRTIO_NET(vdev);

    int i;



    virtio_net_set_multiqueue(n,

                              __virtio_has_feature(features, VIRTIO_NET_F_MQ));



    virtio_net_set_mrg_rx_bufs(n,

                               __virtio_has_feature(features,

                                                    VIRTIO_NET_F_MRG_RXBUF),

                               __virtio_has_feature(features,

                                                    VIRTIO_F_VERSION_1));



    if (n->has_vnet_hdr) {

        n->curr_guest_offloads =

            virtio_net_guest_offloads_by_features(features);

        virtio_net_apply_guest_offloads(n);

    }



    for (i = 0;  i < n->max_queues; i++) {

        NetClientState *nc = qemu_get_subqueue(n->nic, i);



        if (!get_vhost_net(nc->peer)) {

            continue;

        }

        vhost_net_ack_features(get_vhost_net(nc->peer), features);

    }



    if (__virtio_has_feature(features, VIRTIO_NET_F_CTRL_VLAN)) {

        memset(n->vlans, 0, MAX_VLAN >> 3);

    } else {

        memset(n->vlans, 0xff, MAX_VLAN >> 3);

    }

}

static void virtio_net_set_multiqueue(VirtIONet *n, int multiqueue, int ctrl)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(n);

    int i, max = multiqueue ? n->max_queues : 1;



    n->multiqueue = multiqueue;



    for (i = 2; i <= n->max_queues * 2 + 1; i++) {

        virtio_del_queue(vdev, i);

    }



    for (i = 1; i < max; i++) {

        n->vqs[i].rx_vq = virtio_add_queue(vdev, 256, virtio_net_handle_rx);

        if (n->vqs[i].tx_timer) {

            n->vqs[i].tx_vq =

                virtio_add_queue(vdev, 256, virtio_net_handle_tx_timer);

            n->vqs[i].tx_timer = qemu_new_timer_ns(vm_clock,

                                                   virtio_net_tx_timer,

                                                   &n->vqs[i]);

        } else {

            n->vqs[i].tx_vq =

                virtio_add_queue(vdev, 256, virtio_net_handle_tx_bh);

            n->vqs[i].tx_bh = qemu_bh_new(virtio_net_tx_bh, &n->vqs[i]);

        }



        n->vqs[i].tx_waiting = 0;

        n->vqs[i].n = n;

    }



    if (ctrl) {

        n->ctrl_vq = virtio_add_queue(vdev, 64, virtio_net_handle_ctrl);

    }



    virtio_net_set_queues(n);

}

