static void omap_uwire_write(void *opaque, target_phys_addr_t addr,

                             uint64_t value, unsigned size)

{

    struct omap_uwire_s *s = (struct omap_uwire_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;



    if (size != 2) {

        return omap_badwidth_write16(opaque, addr, value);

    }



    switch (offset) {

    case 0x00:	/* TDR */

        s->txbuf = value;				/* TD */

        if ((s->setup[4] & (1 << 2)) &&			/* AUTO_TX_EN */

                        ((s->setup[4] & (1 << 3)) ||	/* CS_TOGGLE_TX_EN */

                         (s->control & (1 << 12)))) {	/* CS_CMD */

            s->control |= 1 << 14;			/* CSRB */

            omap_uwire_transfer_start(s);

        }

        break;



    case 0x04:	/* CSR */

        s->control = value & 0x1fff;

        if (value & (1 << 13))				/* START */

            omap_uwire_transfer_start(s);

        break;



    case 0x08:	/* SR1 */

        s->setup[0] = value & 0x003f;

        break;



    case 0x0c:	/* SR2 */

        s->setup[1] = value & 0x0fc0;

        break;



    case 0x10:	/* SR3 */

        s->setup[2] = value & 0x0003;

        break;



    case 0x14:	/* SR4 */

        s->setup[3] = value & 0x0001;

        break;



    case 0x18:	/* SR5 */

        s->setup[4] = value & 0x000f;

        break;



    default:

        OMAP_BAD_REG(addr);

        return;

    }

}

void ff_rtp_send_aac(AVFormatContext *s1, const uint8_t *buff, int size)

{

    RTPMuxContext *s = s1->priv_data;

    int len, max_packet_size;

    uint8_t *p;

    const int max_frames_per_packet = s->max_frames_per_packet ? s->max_frames_per_packet : 5;

    const int max_au_headers_size = 2 + 2 * max_frames_per_packet;



    /* skip ADTS header, if present */

    if ((s1->streams[0]->codec->extradata_size) == 0) {

        size -= 7;

        buff += 7;

    }

    max_packet_size = s->max_payload_size - max_au_headers_size;



    /* test if the packet must be sent */

    len = (s->buf_ptr - s->buf);

    if ((s->num_frames == max_frames_per_packet) || (len && (len + size) > s->max_payload_size)) {

        int au_size = s->num_frames * 2;



        p = s->buf + max_au_headers_size - au_size - 2;

        if (p != s->buf) {

            memmove(p + 2, s->buf + 2, au_size);

        }

        /* Write the AU header size */

        p[0] = ((au_size * 8) & 0xFF) >> 8;

        p[1] = (au_size * 8) & 0xFF;



        ff_rtp_send_data(s1, p, s->buf_ptr - p, 1);



        s->num_frames = 0;

    }

    if (s->num_frames == 0) {

        s->buf_ptr = s->buf + max_au_headers_size;

        s->timestamp = s->cur_timestamp;

    }



    if (size <= max_packet_size) {

        p = s->buf + s->num_frames++ * 2 + 2;

        *p++ = size >> 5;

        *p = (size & 0x1F) << 3;

        memcpy(s->buf_ptr, buff, size);

        s->buf_ptr += size;

    } else {

        int au_size = size;



        max_packet_size = s->max_payload_size - 4;

        p = s->buf;

        p[0] = 0;

        p[1] = 16;

        while (size > 0) {

            len = FFMIN(size, max_packet_size);

            p[2] = au_size >> 5;

            p[3] = (au_size & 0x1F) << 3;

            memcpy(p + 4, buff, len);

            ff_rtp_send_data(s1, p, len + 4, len == size);

            size -= len;

            buff += len;

        }

    }

}

static inline void s_zero(int cur_diff, struct G722Band *band)

{

    int s_zero = 0;



    #define ACCUM(k, x, d) do { \

            int tmp = x; \

            band->zero_mem[k] = ((band->zero_mem[k] * 255) >> 8) + \

               d*((band->diff_mem[k]^cur_diff) < 0 ? -128 : 128); \

            band->diff_mem[k] = tmp; \

            s_zero += (tmp * band->zero_mem[k]) >> 15; \

        } while (0)

    if (cur_diff) {

        ACCUM(5, band->diff_mem[4], 1);

        ACCUM(4, band->diff_mem[3], 1);

        ACCUM(3, band->diff_mem[2], 1);

        ACCUM(2, band->diff_mem[1], 1);

        ACCUM(1, band->diff_mem[0], 1);

        ACCUM(0, cur_diff << 1, 1);

    } else {

        ACCUM(5, band->diff_mem[4], 0);

        ACCUM(4, band->diff_mem[3], 0);

        ACCUM(3, band->diff_mem[2], 0);

        ACCUM(2, band->diff_mem[1], 0);

        ACCUM(1, band->diff_mem[0], 0);

        ACCUM(0, cur_diff << 1, 0);

    }

    #undef ACCUM

    band->s_zero = s_zero;

}

static void predictor_decode_stereo(APEContext *ctx, int count)

{

    APEPredictor *p = &ctx->predictor;

    int32_t *decoded0 = ctx->decoded[0];

    int32_t *decoded1 = ctx->decoded[1];



    while (count--) {

        /* Predictor Y */

        *decoded0 = predictor_update_filter(p, *decoded0, 0, YDELAYA, YDELAYB,

                                            YADAPTCOEFFSA, YADAPTCOEFFSB);

        decoded0++;

        *decoded1 = predictor_update_filter(p, *decoded1, 1, XDELAYA, XDELAYB,

                                            XADAPTCOEFFSA, XADAPTCOEFFSB);

        decoded1++;



        /* Combined */

        p->buf++;



        /* Have we filled the history buffer? */

        if (p->buf == p->historybuffer + HISTORY_SIZE) {

            memmove(p->historybuffer, p->buf,

                    PREDICTOR_SIZE * sizeof(*p->historybuffer));

            p->buf = p->historybuffer;

        }

    }

}

void kvm_arm_reset_vcpu(ARMCPU *cpu)

{

    /* Feed the kernel back its initial register state */

    memmove(cpu->cpreg_values, cpu->cpreg_reset_values,

            cpu->cpreg_array_len * sizeof(cpu->cpreg_values[0]));



    if (!write_list_to_kvmstate(cpu)) {

        abort();

    }

}

static void print_report(AVFormatContext **output_files,

                         AVOutputStream **ost_table, int nb_ostreams,

                         int is_last_report)

{

    char buf[1024];

    AVOutputStream *ost;

    AVFormatContext *oc, *os;

    int64_t total_size;

    AVCodecContext *enc;

    int frame_number, vid, i;

    double bitrate, ti1, pts;

    static int64_t last_time = -1;

    static int qp_histogram[52];



    if (!is_last_report) {

        int64_t cur_time;

        /* display the report every 0.5 seconds */

        cur_time = av_gettime();

        if (last_time == -1) {

            last_time = cur_time;

            return;

        }

        if ((cur_time - last_time) < 500000)

            return;

        last_time = cur_time;

    }





    oc = output_files[0];



    total_size = url_fsize(oc->pb);

    if(total_size<0) // FIXME improve url_fsize() so it works with non seekable output too

        total_size= url_ftell(oc->pb);



    buf[0] = '\0';

    ti1 = 1e10;

    vid = 0;

    for(i=0;i<nb_ostreams;i++) {

        ost = ost_table[i];

        os = output_files[ost->file_index];

        enc = ost->st->codec;

        if (vid && enc->codec_type == CODEC_TYPE_VIDEO) {

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "q=%2.1f ",

                    enc->coded_frame->quality/(float)FF_QP2LAMBDA);

        }

        if (!vid && enc->codec_type == CODEC_TYPE_VIDEO) {

            float t = (av_gettime()-timer_start) / 1000000.0;



            frame_number = ost->frame_number;

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "frame=%5d fps=%3d q=%3.1f ",

                     frame_number, (t>1)?(int)(frame_number/t+0.5) : 0,

                     enc->coded_frame ? enc->coded_frame->quality/(float)FF_QP2LAMBDA : -1);

            if(is_last_report)

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "L");

            if(qp_hist && enc->coded_frame){

                int j;

                int qp= lrintf(enc->coded_frame->quality/(float)FF_QP2LAMBDA);

                if(qp>=0 && qp<sizeof(qp_histogram)/sizeof(int))

                    qp_histogram[qp]++;

                for(j=0; j<32; j++)

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%X", (int)lrintf(log(qp_histogram[j]+1)/log(2)));

            }

            if (enc->flags&CODEC_FLAG_PSNR){

                int j;

                double error, error_sum=0;

                double scale, scale_sum=0;

                char type[3]= {'Y','U','V'};

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "PSNR=");

                for(j=0; j<3; j++){

                    if(is_last_report){

                        error= enc->error[j];

                        scale= enc->width*enc->height*255.0*255.0*frame_number;

                    }else{

                        error= enc->coded_frame->error[j];

                        scale= enc->width*enc->height*255.0*255.0;

                    }

                    if(j) scale/=4;

                    error_sum += error;

                    scale_sum += scale;

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%c:%2.2f ", type[j], psnr(error/scale));

                }

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "*:%2.2f ", psnr(error_sum/scale_sum));

            }

            vid = 1;

        }

        /* compute min output value */

        pts = (double)ost->st->pts.val * av_q2d(ost->st->time_base);

        if ((pts < ti1) && (pts > 0))

            ti1 = pts;

    }

    if (ti1 < 0.01)

        ti1 = 0.01;



    if (verbose || is_last_report) {

        bitrate = (double)(total_size * 8) / ti1 / 1000.0;



        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

            "size=%8.0fkB time=%0.1f bitrate=%6.1fkbits/s",

            (double)total_size / 1024, ti1, bitrate);



        if (verbose > 1)

          snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " dup=%d drop=%d",

                  nb_frames_dup, nb_frames_drop);



        if (verbose >= 0)

            fprintf(stderr, "%s    \r", buf);



        fflush(stderr);

    }



    if (is_last_report && verbose >= 0){

        int64_t raw= audio_size + video_size + extra_size;

        fprintf(stderr, "\n");

        fprintf(stderr, "video:%1.0fkB audio:%1.0fkB global headers:%1.0fkB muxing overhead %f%%\n",

                video_size/1024.0,

                audio_size/1024.0,

                extra_size/1024.0,

                100.0*(total_size - raw)/raw

        );

    }

}

static void print_report(int is_last_report, int64_t timer_start)

{

    char buf[1024];

    OutputStream *ost;

    AVFormatContext *oc;

    int64_t total_size;

    AVCodecContext *enc;

    int frame_number, vid, i;

    double bitrate, ti1, pts;

    static int64_t last_time = -1;

    static int qp_histogram[52];



    if (!print_stats && !is_last_report)

        return;



    if (!is_last_report) {

        int64_t cur_time;

        /* display the report every 0.5 seconds */

        cur_time = av_gettime();

        if (last_time == -1) {

            last_time = cur_time;

            return;

        }

        if ((cur_time - last_time) < 500000)

            return;

        last_time = cur_time;

    }





    oc = output_files[0]->ctx;



    total_size = avio_size(oc->pb);

    if (total_size <= 0) // FIXME improve avio_size() so it works with non seekable output too

        total_size = avio_tell(oc->pb);

    if (total_size < 0) {

        char errbuf[128];

        av_strerror(total_size, errbuf, sizeof(errbuf));

        av_log(NULL, AV_LOG_VERBOSE, "Bitrate not available, "

               "avio_tell() failed: %s\n", errbuf);

        total_size = 0;

    }



    buf[0] = '\0';

    ti1 = 1e10;

    vid = 0;

    for (i = 0; i < nb_output_streams; i++) {

        float q = -1;

        ost = output_streams[i];

        enc = ost->st->codec;

        if (!ost->stream_copy && enc->coded_frame)

            q = enc->coded_frame->quality / (float)FF_QP2LAMBDA;

        if (vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "q=%2.1f ", q);

        }

        if (!vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            float t = (av_gettime() - timer_start) / 1000000.0;



            frame_number = ost->frame_number;

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "frame=%5d fps=%3d q=%3.1f ",

                     frame_number, (t > 1) ? (int)(frame_number / t + 0.5) : 0, q);

            if (is_last_report)

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "L");

            if (qp_hist) {

                int j;

                int qp = lrintf(q);

                if (qp >= 0 && qp < FF_ARRAY_ELEMS(qp_histogram))

                    qp_histogram[qp]++;

                for (j = 0; j < 32; j++)

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%X", (int)lrintf(log2(qp_histogram[j] + 1)));

            }

            if (enc->flags&CODEC_FLAG_PSNR) {

                int j;

                double error, error_sum = 0;

                double scale, scale_sum = 0;

                char type[3] = { 'Y','U','V' };

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "PSNR=");

                for (j = 0; j < 3; j++) {

                    if (is_last_report) {

                        error = enc->error[j];

                        scale = enc->width * enc->height * 255.0 * 255.0 * frame_number;

                    } else {

                        error = enc->coded_frame->error[j];

                        scale = enc->width * enc->height * 255.0 * 255.0;

                    }

                    if (j)

                        scale /= 4;

                    error_sum += error;

                    scale_sum += scale;

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%c:%2.2f ", type[j], psnr(error / scale));

                }

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "*:%2.2f ", psnr(error_sum / scale_sum));

            }

            vid = 1;

        }

        /* compute min output value */

        pts = (double)ost->st->pts.val * av_q2d(ost->st->time_base);

        if ((pts < ti1) && (pts > 0))

            ti1 = pts;

    }

    if (ti1 < 0.01)

        ti1 = 0.01;



    bitrate = (double)(total_size * 8) / ti1 / 1000.0;



    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

            "size=%8.0fkB time=%0.2f bitrate=%6.1fkbits/s",

            (double)total_size / 1024, ti1, bitrate);



    if (nb_frames_dup || nb_frames_drop)

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " dup=%d drop=%d",

                nb_frames_dup, nb_frames_drop);



    av_log(NULL, AV_LOG_INFO, "%s    \r", buf);



    fflush(stderr);



    if (is_last_report) {

        int64_t raw= audio_size + video_size + extra_size;

        av_log(NULL, AV_LOG_INFO, "\n");

        av_log(NULL, AV_LOG_INFO, "video:%1.0fkB audio:%1.0fkB global headers:%1.0fkB muxing overhead %f%%\n",

               video_size / 1024.0,

               audio_size / 1024.0,

               extra_size / 1024.0,

               100.0 * (total_size - raw) / raw

        );

    }

}

