    double bitrate;

    int64_t pts = INT64_MIN;

    static int64_t last_time = -1;

    static int qp_histogram[52];

    int hours, mins, secs, us;



    if (!print_stats && !is_last_report && !progress_avio)

        return;



    if (!is_last_report) {

        if (last_time == -1) {

            last_time = cur_time;

            return;

        }

        if ((cur_time - last_time) < 500000)

            return;

        last_time = cur_time;

    }





    oc = output_files[0]->ctx;



    total_size = avio_size(oc->pb);

    if (total_size <= 0) // FIXME improve avio_size() so it works with non seekable output too

        total_size = avio_tell(oc->pb);



    buf[0] = '\0';

    vid = 0;

    av_bprint_init(&buf_script, 0, 1);

    for (i = 0; i < nb_output_streams; i++) {

        float q = -1;

        ost = output_streams[i];

        enc = ost->enc_ctx;

        if (!ost->stream_copy && enc->coded_frame)

            q = enc->coded_frame->quality / (float)FF_QP2LAMBDA;

        if (vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "q=%2.1f ", q);

            av_bprintf(&buf_script, "stream_%d_%d_q=%.1f\n",

                       ost->file_index, ost->index, q);

        }

        if (!vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            float fps, t = (cur_time-timer_start) / 1000000.0;



            frame_number = ost->frame_number;

            fps = t > 1 ? frame_number / t : 0;

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "frame=%5d fps=%3.*f q=%3.1f ",

                     frame_number, fps < 9.95, fps, q);

            av_bprintf(&buf_script, "frame=%d\n", frame_number);

            av_bprintf(&buf_script, "fps=%.1f\n", fps);

            av_bprintf(&buf_script, "stream_%d_%d_q=%.1f\n",

                       ost->file_index, ost->index, q);

            if (is_last_report)

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "L");

            if (qp_hist) {

                int j;

                int qp = lrintf(q);

                if (qp >= 0 && qp < FF_ARRAY_ELEMS(qp_histogram))

                    qp_histogram[qp]++;

                for (j = 0; j < 32; j++)

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%X", (int)lrintf(log2(qp_histogram[j] + 1)));

            }

            if ((enc->flags&CODEC_FLAG_PSNR) && (enc->coded_frame || is_last_report)) {

                int j;

                double error, error_sum = 0;

                double scale, scale_sum = 0;

                double p;

                char type[3] = { 'Y','U','V' };

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "PSNR=");

                for (j = 0; j < 3; j++) {

                    if (is_last_report) {

                        error = enc->error[j];

                        scale = enc->width * enc->height * 255.0 * 255.0 * frame_number;

                    } else {

                        error = enc->coded_frame->error[j];

                        scale = enc->width * enc->height * 255.0 * 255.0;

                    }

                    if (j)

                        scale /= 4;

                    error_sum += error;

                    scale_sum += scale;

                    p = psnr(error / scale);

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%c:%2.2f ", type[j], p);

                    av_bprintf(&buf_script, "stream_%d_%d_psnr_%c=%2.2f\n",

                               ost->file_index, ost->index, type[j] | 32, p);

                }

                p = psnr(error_sum / scale_sum);

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "*:%2.2f ", psnr(error_sum / scale_sum));

                av_bprintf(&buf_script, "stream_%d_%d_psnr_all=%2.2f\n",

                           ost->file_index, ost->index, p);

            }

            vid = 1;

        }

        /* compute min output value */

        if (av_stream_get_end_pts(ost->st) != AV_NOPTS_VALUE)

            pts = FFMAX(pts, av_rescale_q(av_stream_get_end_pts(ost->st),

                                          ost->st->time_base, AV_TIME_BASE_Q));

        if (is_last_report)

            nb_frames_drop += ost->last_droped;

    }



    secs = pts / AV_TIME_BASE;

    us = pts % AV_TIME_BASE;

    mins = secs / 60;

    secs %= 60;

    hours = mins / 60;

    mins %= 60;



    bitrate = pts && total_size >= 0 ? total_size * 8 / (pts / 1000.0) : -1;



    if (total_size < 0) snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

                                 "size=N/A time=");

    else                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

                                 "size=%8.0fkB time=", total_size / 1024.0);

    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

             "%02d:%02d:%02d.%02d ", hours, mins, secs,

             (100 * us) / AV_TIME_BASE);



    if (bitrate < 0) {

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),"bitrate=N/A");

        av_bprintf(&buf_script, "bitrate=N/A\n");

    }else{

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),"bitrate=%6.1fkbits/s", bitrate);

        av_bprintf(&buf_script, "bitrate=%6.1fkbits/s\n", bitrate);

    }



    if (total_size < 0) av_bprintf(&buf_script, "total_size=N/A\n");

    else                av_bprintf(&buf_script, "total_size=%"PRId64"\n", total_size);

    av_bprintf(&buf_script, "out_time_ms=%"PRId64"\n", pts);

    av_bprintf(&buf_script, "out_time=%02d:%02d:%02d.%06d\n",

               hours, mins, secs, us);



    if (nb_frames_dup || nb_frames_drop)

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " dup=%d drop=%d",

                nb_frames_dup, nb_frames_drop);

    av_bprintf(&buf_script, "dup_frames=%d\n", nb_frames_dup);

    av_bprintf(&buf_script, "drop_frames=%d\n", nb_frames_drop);



    if (print_stats || is_last_report) {

        const char end = is_last_report ? '\n' : '\r';

        if (print_stats==1 && AV_LOG_INFO > av_log_get_level()) {

            fprintf(stderr, "%s    %c", buf, end);

        } else

            av_log(NULL, AV_LOG_INFO, "%s    %c", buf, end);



    fflush(stderr);

    }



    if (progress_avio) {

        av_bprintf(&buf_script, "progress=%s\n",

                   is_last_report ? "end" : "continue");

        avio_write(progress_avio, buf_script.str,

                   FFMIN(buf_script.len, buf_script.size - 1));

        avio_flush(progress_avio);

        av_bprint_finalize(&buf_script, NULL);

        if (is_last_report) {

            avio_closep(&progress_avio);

        }

    }



    if (is_last_report)

        print_final_stats(total_size);

}

static av_always_inline void rv40_weak_loop_filter(uint8_t *src,

                                                   const int step,

                                                   const ptrdiff_t stride,

                                                   const int filter_p1,

                                                   const int filter_q1,

                                                   const int alpha,

                                                   const int beta,

                                                   const int lim_p0q0,

                                                   const int lim_q1,

                                                   const int lim_p1)

{

    const uint8_t *cm = ff_crop_tab + MAX_NEG_CROP;

    int i, t, u, diff;



    for (i = 0; i < 4; i++, src += stride) {

        int diff_p1p0 = src[-2*step] - src[-1*step];

        int diff_q1q0 = src[ 1*step] - src[ 0*step];

        int diff_p1p2 = src[-2*step] - src[-3*step];

        int diff_q1q2 = src[ 1*step] - src[ 2*step];



        t = src[0*step] - src[-1*step];

        if (!t)

            continue;



        u = (alpha * FFABS(t)) >> 7;

        if (u > 3 - (filter_p1 && filter_q1))

            continue;



        t <<= 2;

        if (filter_p1 && filter_q1)

            t += src[-2*step] - src[1*step];



        diff = CLIP_SYMM((t + 4) >> 3, lim_p0q0);

        src[-1*step] = cm[src[-1*step] + diff];

        src[ 0*step] = cm[src[ 0*step] - diff];



        if (filter_p1 && FFABS(diff_p1p2) <= beta) {

            t = (diff_p1p0 + diff_p1p2 - diff) >> 1;

            src[-2*step] = cm[src[-2*step] - CLIP_SYMM(t, lim_p1)];

        }



        if (filter_q1 && FFABS(diff_q1q2) <= beta) {

            t = (diff_q1q0 + diff_q1q2 + diff) >> 1;

            src[ 1*step] = cm[src[ 1*step] - CLIP_SYMM(t, lim_q1)];

        }

    }

}

static inline void h264_loop_filter_chroma_intra_c(uint8_t *pix, int xstride, int ystride, int alpha, int beta)

{

    int d;

    for( d = 0; d < 8; d++ ) {

        const int p0 = pix[-1*xstride];

        const int p1 = pix[-2*xstride];

        const int q0 = pix[0];

        const int q1 = pix[1*xstride];



        if( FFABS( p0 - q0 ) < alpha &&

            FFABS( p1 - p0 ) < beta &&

            FFABS( q1 - q0 ) < beta ) {



            pix[-xstride] = ( 2*p1 + p0 + q1 + 2 ) >> 2;   /* p0' */

            pix[0]        = ( 2*q1 + q0 + p1 + 2 ) >> 2;   /* q0' */

        }

        pix += ystride;

    }

}

static void vc1_loop_filter(uint8_t* src, int step, int stride, int len, int pq)

{

    int i;

    int filt3;



    for(i = 0; i < len; i += 4){

        filt3 = vc1_filter_line(src + 2*step, stride, pq);

        if(filt3){

            vc1_filter_line(src + 0*step, stride, pq);

            vc1_filter_line(src + 1*step, stride, pq);

            vc1_filter_line(src + 3*step, stride, pq);

        }

        src += step * 4;

    }

}

static av_always_inline av_flatten void h264_loop_filter_luma_intra_c(uint8_t *pix, int xstride, int ystride, int alpha, int beta)

{

    int d;

    for( d = 0; d < 16; d++ ) {

        const int p2 = pix[-3*xstride];

        const int p1 = pix[-2*xstride];

        const int p0 = pix[-1*xstride];



        const int q0 = pix[ 0*xstride];

        const int q1 = pix[ 1*xstride];

        const int q2 = pix[ 2*xstride];



        if( FFABS( p0 - q0 ) < alpha &&

            FFABS( p1 - p0 ) < beta &&

            FFABS( q1 - q0 ) < beta ) {



            if(FFABS( p0 - q0 ) < (( alpha >> 2 ) + 2 )){

                if( FFABS( p2 - p0 ) < beta)

                {

                    const int p3 = pix[-4*xstride];

                    /* p0', p1', p2' */

                    pix[-1*xstride] = ( p2 + 2*p1 + 2*p0 + 2*q0 + q1 + 4 ) >> 3;

                    pix[-2*xstride] = ( p2 + p1 + p0 + q0 + 2 ) >> 2;

                    pix[-3*xstride] = ( 2*p3 + 3*p2 + p1 + p0 + q0 + 4 ) >> 3;

                } else {

                    /* p0' */

                    pix[-1*xstride] = ( 2*p1 + p0 + q1 + 2 ) >> 2;

                }

                if( FFABS( q2 - q0 ) < beta)

                {

                    const int q3 = pix[3*xstride];

                    /* q0', q1', q2' */

                    pix[0*xstride] = ( p1 + 2*p0 + 2*q0 + 2*q1 + q2 + 4 ) >> 3;

                    pix[1*xstride] = ( p0 + q0 + q1 + q2 + 2 ) >> 2;

                    pix[2*xstride] = ( 2*q3 + 3*q2 + q1 + q0 + p0 + 4 ) >> 3;

                } else {

                    /* q0' */

                    pix[0*xstride] = ( 2*q1 + q0 + p1 + 2 ) >> 2;

                }

            }else{

                /* p0', q0' */

                pix[-1*xstride] = ( 2*p1 + p0 + q1 + 2 ) >> 2;

                pix[ 0*xstride] = ( 2*q1 + q0 + p1 + 2 ) >> 2;

            }

        }

        pix += ystride;

    }

}

DeviceState *qdev_try_create(BusState *bus, const char *type)

{

    DeviceState *dev;



    if (object_class_by_name(type) == NULL) {

        return NULL;

    }

    dev = DEVICE(object_new(type));

    if (!dev) {

        return NULL;

    }



    if (!bus) {







