}

SCSIDevice *scsi_bus_legacy_add_drive(SCSIBus *bus, BlockDriverState *bdrv,

                                      int unit, bool removable, int bootindex,

                                      const char *serial, Error **errp)

{

    const char *driver;

    DeviceState *dev;

    Error *err = NULL;



    driver = bdrv_is_sg(bdrv) ? "scsi-generic" : "scsi-disk";

    dev = qdev_create(&bus->qbus, driver);

    qdev_prop_set_uint32(dev, "scsi-id", unit);

    if (bootindex >= 0) {

        qdev_prop_set_int32(dev, "bootindex", bootindex);

    }

    if (object_property_find(OBJECT(dev), "removable", NULL)) {

        qdev_prop_set_bit(dev, "removable", removable);

    }

    if (serial) {

        qdev_prop_set_string(dev, "serial", serial);

    }

    if (qdev_prop_set_drive(dev, "drive", bdrv) < 0) {

        error_setg(errp, "Setting drive property failed");

        qdev_free(dev);

        return NULL;

    }

    object_property_set_bool(OBJECT(dev), true, "realized", &err);

    if (err != NULL) {

        error_propagate(errp, err);

        qdev_free(dev);

        return NULL;

    }

    return SCSI_DEVICE(dev);

}

DeviceState *qdev_device_add(QemuOpts *opts)

{

    DeviceClass *k;

    const char *driver, *path, *id;

    DeviceState *qdev;

    BusState *bus;



    driver = qemu_opt_get(opts, "driver");

    if (!driver) {

        qerror_report(QERR_MISSING_PARAMETER, "driver");

        return NULL;

    }



    /* find driver */

    k = DEVICE_CLASS(object_class_by_name(driver));



    /* find bus */

    path = qemu_opt_get(opts, "bus");

    if (path != NULL) {

        bus = qbus_find(path);

        if (!bus) {

            return NULL;

        }

        if (bus->info != k->bus_info) {

            qerror_report(QERR_BAD_BUS_FOR_DEVICE,

                           driver, bus->info->name);

            return NULL;

        }

    } else {

        bus = qbus_find_recursive(main_system_bus, NULL, k->bus_info);

        if (!bus) {

            qerror_report(QERR_NO_BUS_FOR_DEVICE,

                          driver, k->bus_info->name);

            return NULL;

        }

    }

    if (qdev_hotplug && !bus->allow_hotplug) {

        qerror_report(QERR_BUS_NO_HOTPLUG, bus->name);

        return NULL;

    }



    /* create device, set properties */

    qdev = qdev_create_from_info(bus, driver);

    id = qemu_opts_id(opts);

    if (id) {

        qdev->id = id;

        qdev_property_add_child(qdev_get_peripheral(), qdev->id, qdev, NULL);

    } else {

        static int anon_count;

        gchar *name = g_strdup_printf("device[%d]", anon_count++);

        qdev_property_add_child(qdev_get_peripheral_anon(), name,

                                qdev, NULL);

        g_free(name);

    }        

    if (qemu_opt_foreach(opts, set_property, qdev, 1) != 0) {

        qdev_free(qdev);

        return NULL;

    }

    if (qdev_init(qdev) < 0) {

        qerror_report(QERR_DEVICE_INIT_FAILED, driver);

        return NULL;

    }

    qdev->opts = opts;

    return qdev;

}

CharDriverState *qemu_chr_new_from_opts(QemuOpts *opts,

                                    void (*init)(struct CharDriverState *s),

                                    Error **errp)

{

    Error *local_err = NULL;

    CharDriver *cd;

    CharDriverState *chr;

    GSList *i;

    ChardevReturn *ret = NULL;

    ChardevBackend *backend;

    const char *id = qemu_opts_id(opts);

    char *bid = NULL;



    if (id == NULL) {

        error_setg(errp, "chardev: no id specified");

        goto err;

    }



    if (qemu_opt_get(opts, "backend") == NULL) {

        error_setg(errp, "chardev: \"%s\" missing backend",

                   qemu_opts_id(opts));

        goto err;

    }

    for (i = backends; i; i = i->next) {

        cd = i->data;



        if (strcmp(cd->name, qemu_opt_get(opts, "backend")) == 0) {

            break;

        }

    }

    if (i == NULL) {

        error_setg(errp, "chardev: backend \"%s\" not found",

                   qemu_opt_get(opts, "backend"));

        goto err;

    }



    backend = g_new0(ChardevBackend, 1);



    if (qemu_opt_get_bool(opts, "mux", 0)) {

        bid = g_strdup_printf("%s-base", id);

    }



    chr = NULL;

    backend->kind = cd->kind;

    if (cd->parse) {

        cd->parse(opts, backend, &local_err);

        if (local_err) {

            error_propagate(errp, local_err);

            goto qapi_out;

        }

    }

    ret = qmp_chardev_add(bid ? bid : id, backend, errp);

    if (!ret) {

        goto qapi_out;

    }



    if (bid) {

        qapi_free_ChardevBackend(backend);

        qapi_free_ChardevReturn(ret);

        backend = g_new0(ChardevBackend, 1);

        backend->mux = g_new0(ChardevMux, 1);

        backend->kind = CHARDEV_BACKEND_KIND_MUX;

        backend->mux->chardev = g_strdup(bid);

        ret = qmp_chardev_add(id, backend, errp);

        if (!ret) {

            chr = qemu_chr_find(bid);

            qemu_chr_delete(chr);

            chr = NULL;

            goto qapi_out;

        }

    }



    chr = qemu_chr_find(id);

    chr->opts = opts;



qapi_out:

    qapi_free_ChardevBackend(backend);

    qapi_free_ChardevReturn(ret);

    g_free(bid);

    return chr;



err:

    qemu_opts_del(opts);

    return NULL;

}

static int rv10_decode_packet(AVCodecContext *avctx,

                             const uint8_t *buf, int buf_size, int buf_size2)

{

    MpegEncContext *s = avctx->priv_data;

    int mb_count, mb_pos, left, start_mb_x;



    init_get_bits(&s->gb, buf, buf_size*8);

    if(s->codec_id ==CODEC_ID_RV10)

        mb_count = rv10_decode_picture_header(s);

    else

        mb_count = rv20_decode_picture_header(s);

    if (mb_count < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "HEADER ERROR\n");

        return -1;

    }



    if (s->mb_x >= s->mb_width ||

        s->mb_y >= s->mb_height) {

        av_log(s->avctx, AV_LOG_ERROR, "POS ERROR %d %d\n", s->mb_x, s->mb_y);

        return -1;

    }

    mb_pos = s->mb_y * s->mb_width + s->mb_x;

    left = s->mb_width * s->mb_height - mb_pos;

    if (mb_count > left) {

        av_log(s->avctx, AV_LOG_ERROR, "COUNT ERROR\n");

        return -1;

    }



    if ((s->mb_x == 0 && s->mb_y == 0) || s->current_picture_ptr==NULL) {

        if(s->current_picture_ptr){ //FIXME write parser so we always have complete frames?

            ff_er_frame_end(s);

            ff_MPV_frame_end(s);

            s->mb_x= s->mb_y = s->resync_mb_x = s->resync_mb_y= 0;

        }

        if(ff_MPV_frame_start(s, avctx) < 0)

            return -1;

        ff_er_frame_start(s);

    } else {

        if (s->current_picture_ptr->f.pict_type != s->pict_type) {

            av_log(s->avctx, AV_LOG_ERROR, "Slice type mismatch\n");

            return -1;

        }

    }



    av_dlog(avctx, "qscale=%d\n", s->qscale);



    /* default quantization values */

    if(s->codec_id== CODEC_ID_RV10){

        if(s->mb_y==0) s->first_slice_line=1;

    }else{

        s->first_slice_line=1;

        s->resync_mb_x= s->mb_x;

    }

    start_mb_x= s->mb_x;

    s->resync_mb_y= s->mb_y;

    if(s->h263_aic){

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_aic_dc_scale_table;

    }else{

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_mpeg1_dc_scale_table;

    }



    if(s->modified_quant)

        s->chroma_qscale_table= ff_h263_chroma_qscale_table;



    ff_set_qscale(s, s->qscale);



    s->rv10_first_dc_coded[0] = 0;

    s->rv10_first_dc_coded[1] = 0;

    s->rv10_first_dc_coded[2] = 0;

    s->block_wrap[0]=

    s->block_wrap[1]=

    s->block_wrap[2]=

    s->block_wrap[3]= s->b8_stride;

    s->block_wrap[4]=

    s->block_wrap[5]= s->mb_stride;

    ff_init_block_index(s);

    /* decode each macroblock */



    for(s->mb_num_left= mb_count; s->mb_num_left>0; s->mb_num_left--) {

        int ret;

        ff_update_block_index(s);

        av_dlog(avctx, "**mb x=%d y=%d\n", s->mb_x, s->mb_y);



        s->mv_dir = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16;

        ret=ff_h263_decode_mb(s, s->block);



        if (ret != SLICE_ERROR && s->gb.size_in_bits < get_bits_count(&s->gb) && 8*buf_size2 >= get_bits_count(&s->gb)){

            av_log(avctx, AV_LOG_DEBUG, "update size from %d to %d\n", s->gb.size_in_bits, 8*buf_size2);

            s->gb.size_in_bits= 8*buf_size2;

            ret= SLICE_OK;

        }



        if (ret == SLICE_ERROR || s->gb.size_in_bits < get_bits_count(&s->gb)) {

            av_log(s->avctx, AV_LOG_ERROR, "ERROR at MB %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        if(s->pict_type != AV_PICTURE_TYPE_B)

            ff_h263_update_motion_val(s);

        ff_MPV_decode_mb(s, s->block);

        if(s->loop_filter)

            ff_h263_loop_filter(s);



        if (++s->mb_x == s->mb_width) {

            s->mb_x = 0;

            s->mb_y++;

            ff_init_block_index(s);

        }

        if(s->mb_x == s->resync_mb_x)

            s->first_slice_line=0;

        if(ret == SLICE_END) break;

    }



    ff_er_add_slice(s, start_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, ER_MB_END);



    return s->gb.size_in_bits;

}

