static void gen_rdhwr(DisasContext *ctx, int rt, int rd, int sel)

{

    TCGv t0;



#if !defined(CONFIG_USER_ONLY)

    /* The Linux kernel will emulate rdhwr if it's not supported natively.

       Therefore only check the ISA in system mode.  */

    check_insn(ctx, ISA_MIPS32R2);

#endif

    t0 = tcg_temp_new();



    switch (rd) {

    case 0:

        gen_helper_rdhwr_cpunum(t0, cpu_env);

        gen_store_gpr(t0, rt);

        break;

    case 1:

        gen_helper_rdhwr_synci_step(t0, cpu_env);

        gen_store_gpr(t0, rt);

        break;

    case 2:

        if (ctx->tb->cflags & CF_USE_ICOUNT) {

            gen_io_start();

        }

        gen_helper_rdhwr_cc(t0, cpu_env);

        if (ctx->tb->cflags & CF_USE_ICOUNT) {

            gen_io_end();

        }

        gen_store_gpr(t0, rt);

        /* Break the TB to be able to take timer interrupts immediately

           after reading count. BS_STOP isn't sufficient, we need to ensure

           we break completely out of translated code.  */

        gen_save_pc(ctx->pc + 4);

        ctx->bstate = BS_EXCP;

        break;

    case 3:

        gen_helper_rdhwr_ccres(t0, cpu_env);

        gen_store_gpr(t0, rt);

        break;

    case 4:

        check_insn(ctx, ISA_MIPS32R6);

        if (sel != 0) {

            /* Performance counter registers are not implemented other than

             * control register 0.

             */

            generate_exception(ctx, EXCP_RI);

        }

        gen_helper_rdhwr_performance(t0, cpu_env);

        gen_store_gpr(t0, rt);

        break;

    case 5:

        check_insn(ctx, ISA_MIPS32R6);

        gen_helper_rdhwr_xnp(t0, cpu_env);

        gen_store_gpr(t0, rt);

        break;

    case 29:

#if defined(CONFIG_USER_ONLY)

        tcg_gen_ld_tl(t0, cpu_env,

                      offsetof(CPUMIPSState, active_tc.CP0_UserLocal));

        gen_store_gpr(t0, rt);

        break;

#else

        if ((ctx->hflags & MIPS_HFLAG_CP0) ||

            (ctx->hflags & MIPS_HFLAG_HWRENA_ULR)) {

            tcg_gen_ld_tl(t0, cpu_env,

                          offsetof(CPUMIPSState, active_tc.CP0_UserLocal));

            gen_store_gpr(t0, rt);

        } else {

            generate_exception_end(ctx, EXCP_RI);

        }

        break;

#endif

    default:            /* Invalid */

        MIPS_INVAL("rdhwr");

        generate_exception_end(ctx, EXCP_RI);

        break;

    }

    tcg_temp_free(t0);

}

static void gen_arith_imm(DisasContext *ctx, uint32_t opc,

                          int rt, int rs, int16_t imm)

{

    target_ulong uimm = (target_long)imm; /* Sign extend to 32/64 bits */

    const char *opn = "imm arith";



    if (rt == 0 && opc != OPC_ADDI && opc != OPC_DADDI) {

        /* If no destination, treat it as a NOP.

           For addi, we must generate the overflow exception when needed. */

        MIPS_DEBUG("NOP");

        return;

    }

    switch (opc) {

    case OPC_ADDI:

        {

            TCGv t0 = tcg_temp_local_new();

            TCGv t1 = tcg_temp_new();

            TCGv t2 = tcg_temp_new();

            int l1 = gen_new_label();



            gen_load_gpr(t1, rs);

            tcg_gen_addi_tl(t0, t1, uimm);

            tcg_gen_ext32s_tl(t0, t0);



            tcg_gen_xori_tl(t1, t1, ~uimm);

            tcg_gen_xori_tl(t2, t0, uimm);

            tcg_gen_and_tl(t1, t1, t2);

            tcg_temp_free(t2);

            tcg_gen_brcondi_tl(TCG_COND_GE, t1, 0, l1);

            tcg_temp_free(t1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

            tcg_gen_ext32s_tl(t0, t0);

            gen_store_gpr(t0, rt);

            tcg_temp_free(t0);

        }

        opn = "addi";

        break;

    case OPC_ADDIU:

        if (rs != 0) {

            tcg_gen_addi_tl(cpu_gpr[rt], cpu_gpr[rs], uimm);

            tcg_gen_ext32s_tl(cpu_gpr[rt], cpu_gpr[rt]);

        } else {

            tcg_gen_movi_tl(cpu_gpr[rt], uimm);

        }

        opn = "addiu";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DADDI:

        {

            TCGv t0 = tcg_temp_local_new();

            TCGv t1 = tcg_temp_new();

            TCGv t2 = tcg_temp_new();

            int l1 = gen_new_label();



            gen_load_gpr(t1, rs);

            tcg_gen_addi_tl(t0, t1, uimm);



            tcg_gen_xori_tl(t1, t1, ~uimm);

            tcg_gen_xori_tl(t2, t0, uimm);

            tcg_gen_and_tl(t1, t1, t2);

            tcg_temp_free(t2);

            tcg_gen_brcondi_tl(TCG_COND_GE, t1, 0, l1);

            tcg_temp_free(t1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

            gen_store_gpr(t0, rt);

            tcg_temp_free(t0);

        }

        opn = "daddi";

        break;

    case OPC_DADDIU:

        if (rs != 0) {

            tcg_gen_addi_tl(cpu_gpr[rt], cpu_gpr[rs], uimm);

        } else {

            tcg_gen_movi_tl(cpu_gpr[rt], uimm);

        }

        opn = "daddiu";

        break;

#endif

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s, %s, " TARGET_FMT_lx, opn, regnames[rt], regnames[rs], uimm);

}

static void disas_simd_3same_logic(DisasContext *s, uint32_t insn)

{

    int rd = extract32(insn, 0, 5);

    int rn = extract32(insn, 5, 5);

    int rm = extract32(insn, 16, 5);

    int size = extract32(insn, 22, 2);

    bool is_u = extract32(insn, 29, 1);

    bool is_q = extract32(insn, 30, 1);

    TCGv_i64 tcg_op1 = tcg_temp_new_i64();

    TCGv_i64 tcg_op2 = tcg_temp_new_i64();

    TCGv_i64 tcg_res[2];

    int pass;



    tcg_res[0] = tcg_temp_new_i64();

    tcg_res[1] = tcg_temp_new_i64();



    for (pass = 0; pass < (is_q ? 2 : 1); pass++) {

        read_vec_element(s, tcg_op1, rn, pass, MO_64);

        read_vec_element(s, tcg_op2, rm, pass, MO_64);



        if (!is_u) {

            switch (size) {

            case 0: /* AND */

                tcg_gen_and_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 1: /* BIC */

                tcg_gen_andc_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 2: /* ORR */

                tcg_gen_or_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 3: /* ORN */

                tcg_gen_orc_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            }

        } else {

            if (size != 0) {

                /* B* ops need res loaded to operate on */

                read_vec_element(s, tcg_res[pass], rd, pass, MO_64);

            }



            switch (size) {

            case 0: /* EOR */

                tcg_gen_xor_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 1: /* BSL bitwise select */

                tcg_gen_xor_i64(tcg_op1, tcg_op1, tcg_op2);

                tcg_gen_and_i64(tcg_op1, tcg_op1, tcg_res[pass]);

                tcg_gen_xor_i64(tcg_res[pass], tcg_op2, tcg_op1);

                break;

            case 2: /* BIT, bitwise insert if true */

                tcg_gen_xor_i64(tcg_op1, tcg_op1, tcg_res[pass]);

                tcg_gen_and_i64(tcg_op1, tcg_op1, tcg_op2);

                tcg_gen_xor_i64(tcg_res[pass], tcg_res[pass], tcg_op1);

                break;

            case 3: /* BIF, bitwise insert if false */

                tcg_gen_xor_i64(tcg_op1, tcg_op1, tcg_res[pass]);

                tcg_gen_andc_i64(tcg_op1, tcg_op1, tcg_op2);

                tcg_gen_xor_i64(tcg_res[pass], tcg_res[pass], tcg_op1);

                break;

            }

        }

    }



    write_vec_element(s, tcg_res[0], rd, 0, MO_64);

    if (!is_q) {

        tcg_gen_movi_i64(tcg_res[1], 0);

    }

    write_vec_element(s, tcg_res[1], rd, 1, MO_64);



    tcg_temp_free_i64(tcg_op1);

    tcg_temp_free_i64(tcg_op2);

    tcg_temp_free_i64(tcg_res[0]);

    tcg_temp_free_i64(tcg_res[1]);

}

static void gen_cp1 (DisasContext *ctx, uint32_t opc, int rt, int fs)

{

    const char *opn = "cp1 move";

    TCGv t0 = tcg_temp_new();



    switch (opc) {

    case OPC_MFC1:

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            gen_load_fpr32(fp0, fs);

            tcg_gen_ext_i32_tl(t0, fp0);

            tcg_temp_free_i32(fp0);

        }

        gen_store_gpr(t0, rt);

        opn = "mfc1";

        break;

    case OPC_MTC1:

        gen_load_gpr(t0, rt);

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            tcg_gen_trunc_tl_i32(fp0, t0);

            gen_store_fpr32(fp0, fs);

            tcg_temp_free_i32(fp0);

        }

        opn = "mtc1";

        break;

    case OPC_CFC1:

        gen_helper_1e0i(cfc1, t0, fs);

        gen_store_gpr(t0, rt);

        opn = "cfc1";

        break;

    case OPC_CTC1:

        gen_load_gpr(t0, rt);

        {

            TCGv_i32 fs_tmp = tcg_const_i32(fs);



            gen_helper_0e2i(ctc1, t0, fs_tmp, rt);

            tcg_temp_free_i32(fs_tmp);

        }

        opn = "ctc1";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DMFC1:

        gen_load_fpr64(ctx, t0, fs);

        gen_store_gpr(t0, rt);

        opn = "dmfc1";

        break;

    case OPC_DMTC1:

        gen_load_gpr(t0, rt);

        gen_store_fpr64(ctx, t0, fs);

        opn = "dmtc1";

        break;

#endif

    case OPC_MFHC1:

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            gen_load_fpr32h(fp0, fs);

            tcg_gen_ext_i32_tl(t0, fp0);

            tcg_temp_free_i32(fp0);

        }

        gen_store_gpr(t0, rt);

        opn = "mfhc1";

        break;

    case OPC_MTHC1:

        gen_load_gpr(t0, rt);

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            tcg_gen_trunc_tl_i32(fp0, t0);

            gen_store_fpr32h(fp0, fs);

            tcg_temp_free_i32(fp0);

        }

        opn = "mthc1";

        break;

    default:

        MIPS_INVAL(opn);

        generate_exception (ctx, EXCP_RI);

        goto out;

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s %s", opn, regnames[rt], fregnames[fs]);



 out:

    tcg_temp_free(t0);

}

static void v9fs_stat(void *opaque)

{

    int32_t fid;

    V9fsStat v9stat;

    ssize_t err = 0;

    size_t offset = 7;

    struct stat stbuf;

    V9fsFidState *fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "d", &fid);




    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    err = v9fs_co_lstat(pdu, &fidp->path, &stbuf);

    if (err < 0) {

        goto out;

    }

    err = stat_to_v9stat(pdu, &fidp->path, &stbuf, &v9stat);

    if (err < 0) {

        goto out;

    }

    offset += pdu_marshal(pdu, offset, "wS", 0, &v9stat);

    err = offset;

    v9fs_stat_free(&v9stat);

out:

    put_fid(pdu, fidp);

out_nofid:

    trace_v9fs_stat_return(pdu->tag, pdu->id, v9stat.mode,

                           v9stat.atime, v9stat.mtime, v9stat.length);



    complete_pdu(s, pdu, err);

}

static void v9fs_xattrcreate(void *opaque)

{

    int flags;

    int32_t fid;

    int64_t size;

    ssize_t err = 0;

    V9fsString name;

    size_t offset = 7;

    V9fsFidState *file_fidp;

    V9fsFidState *xattr_fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "dsqd",

                  &fid, &name, &size, &flags);




    file_fidp = get_fid(pdu, fid);

    if (file_fidp == NULL) {

        err = -EINVAL;

        goto out_nofid;

    }

    /* Make the file fid point to xattr */

    xattr_fidp = file_fidp;

    xattr_fidp->fid_type = P9_FID_XATTR;

    xattr_fidp->fs.xattr.copied_len = 0;

    xattr_fidp->fs.xattr.len = size;

    xattr_fidp->fs.xattr.flags = flags;

    v9fs_string_init(&xattr_fidp->fs.xattr.name);

    v9fs_string_copy(&xattr_fidp->fs.xattr.name, &name);

    if (size) {

        xattr_fidp->fs.xattr.value = g_malloc(size);

    } else {

        xattr_fidp->fs.xattr.value = NULL;

    }

    err = offset;

    put_fid(pdu, file_fidp);

out_nofid:

    complete_pdu(s, pdu, err);

    v9fs_string_free(&name);

}

static void v9fs_statfs(void *opaque)

{

    int32_t fid;

    ssize_t retval = 0;

    size_t offset = 7;

    V9fsFidState *fidp;

    struct statfs stbuf;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "d", &fid);

    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        retval = -ENOENT;

        goto out_nofid;

    }

    retval = v9fs_co_statfs(pdu, &fidp->path, &stbuf);

    if (retval < 0) {

        goto out;

    }

    retval = offset;

    retval += v9fs_fill_statfs(s, pdu, &stbuf);

out:

    put_fid(pdu, fidp);

out_nofid:

    complete_pdu(s, pdu, retval);

    return;

}

static void v9fs_fsync(void *opaque)

{

    int err;

    int32_t fid;

    int datasync;

    size_t offset = 7;

    V9fsFidState *fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "dd", &fid, &datasync);

    trace_v9fs_fsync(pdu->tag, pdu->id, fid, datasync);



    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    err = v9fs_co_fsync(pdu, fidp, datasync);

    if (!err) {

        err = offset;

    }

    put_fid(pdu, fidp);

out_nofid:

    complete_pdu(s, pdu, err);

}

uint64_t helper_addlv(CPUAlphaState *env, uint64_t op1, uint64_t op2)

{

    uint64_t tmp = op1;

    op1 = (uint32_t)(op1 + op2);

    if (unlikely((tmp ^ op2 ^ (-1UL)) & (tmp ^ op1) & (1UL << 31))) {

        arith_excp(env, GETPC(), EXC_M_IOV, 0);

    }

    return op1;

}

uint64_t helper_subqv (uint64_t op1, uint64_t op2)

{

    uint64_t res;

    res = op1 - op2;

    if (unlikely((op1 ^ op2) & (res ^ op1) & (1ULL << 63))) {

        arith_excp(env, GETPC(), EXC_M_IOV, 0);

    }

    return res;

}

uint64_t helper_addqv (uint64_t op1, uint64_t op2)

{

    uint64_t tmp = op1;

    op1 += op2;

    if (unlikely((tmp ^ op2 ^ (-1ULL)) & (tmp ^ op1) & (1ULL << 63))) {

        arith_excp(env, GETPC(), EXC_M_IOV, 0);

    }

    return op1;

}

uint64_t helper_addqv(CPUAlphaState *env, uint64_t op1, uint64_t op2)

{

    uint64_t tmp = op1;

    op1 += op2;

    if (unlikely((tmp ^ op2 ^ (-1ULL)) & (tmp ^ op1) & (1ULL << 63))) {

        arith_excp(env, GETPC(), EXC_M_IOV, 0);

    }

    return op1;

}

static void rocker_test_dma_ctrl(Rocker *r, uint32_t val)

{

    PCIDevice *dev = PCI_DEVICE(r);

    char *buf;

    int i;



    buf = g_malloc(r->test_dma_size);



    if (!buf) {

        DPRINTF("test dma buffer alloc failed");

        return;

    }



    switch (val) {

    case ROCKER_TEST_DMA_CTRL_CLEAR:

        memset(buf, 0, r->test_dma_size);

        break;

    case ROCKER_TEST_DMA_CTRL_FILL:

        memset(buf, 0x96, r->test_dma_size);

        break;

    case ROCKER_TEST_DMA_CTRL_INVERT:

        pci_dma_read(dev, r->test_dma_addr, buf, r->test_dma_size);

        for (i = 0; i < r->test_dma_size; i++) {

            buf[i] = ~buf[i];

        }

        break;

    default:

        DPRINTF("not test dma control val=0x%08x\n", val);

        goto err_out;

    }

    pci_dma_write(dev, r->test_dma_addr, buf, r->test_dma_size);



    rocker_msix_irq(r, ROCKER_MSIX_VEC_TEST);



err_out:

    g_free(buf);

}

virtio_crypto_sym_op_helper(VirtIODevice *vdev,

           struct virtio_crypto_cipher_para *cipher_para,

           struct virtio_crypto_alg_chain_data_para *alg_chain_para,

           struct iovec *iov, unsigned int out_num)

{

    VirtIOCrypto *vcrypto = VIRTIO_CRYPTO(vdev);

    CryptoDevBackendSymOpInfo *op_info;

    uint32_t src_len = 0, dst_len = 0;

    uint32_t iv_len = 0;

    uint32_t aad_len = 0, hash_result_len = 0;

    uint32_t hash_start_src_offset = 0, len_to_hash = 0;

    uint32_t cipher_start_src_offset = 0, len_to_cipher = 0;



    size_t max_len, curr_size = 0;

    size_t s;



    /* Plain cipher */

    if (cipher_para) {

        iv_len = ldl_le_p(&cipher_para->iv_len);

        src_len = ldl_le_p(&cipher_para->src_data_len);

        dst_len = ldl_le_p(&cipher_para->dst_data_len);

    } else if (alg_chain_para) { /* Algorithm chain */

        iv_len = ldl_le_p(&alg_chain_para->iv_len);

        src_len = ldl_le_p(&alg_chain_para->src_data_len);

        dst_len = ldl_le_p(&alg_chain_para->dst_data_len);



        aad_len = ldl_le_p(&alg_chain_para->aad_len);

        hash_result_len = ldl_le_p(&alg_chain_para->hash_result_len);

        hash_start_src_offset = ldl_le_p(

                         &alg_chain_para->hash_start_src_offset);

        cipher_start_src_offset = ldl_le_p(

                         &alg_chain_para->cipher_start_src_offset);

        len_to_cipher = ldl_le_p(&alg_chain_para->len_to_cipher);

        len_to_hash = ldl_le_p(&alg_chain_para->len_to_hash);

    } else {

        return NULL;

    }



    max_len = iv_len + aad_len + src_len + dst_len + hash_result_len;

    if (unlikely(max_len > vcrypto->conf.max_size)) {

        virtio_error(vdev, "virtio-crypto too big length");

        return NULL;

    }



    op_info = g_malloc0(sizeof(CryptoDevBackendSymOpInfo) + max_len);

    op_info->iv_len = iv_len;

    op_info->src_len = src_len;

    op_info->dst_len = dst_len;

    op_info->aad_len = aad_len;

    op_info->digest_result_len = hash_result_len;

    op_info->hash_start_src_offset = hash_start_src_offset;

    op_info->len_to_hash = len_to_hash;

    op_info->cipher_start_src_offset = cipher_start_src_offset;

    op_info->len_to_cipher = len_to_cipher;

    /* Handle the initilization vector */

    if (op_info->iv_len > 0) {

        DPRINTF("iv_len=%" PRIu32 "\n", op_info->iv_len);

        op_info->iv = op_info->data + curr_size;



        s = iov_to_buf(iov, out_num, 0, op_info->iv, op_info->iv_len);

        if (unlikely(s != op_info->iv_len)) {

            virtio_error(vdev, "virtio-crypto iv incorrect");

            goto err;

        }

        iov_discard_front(&iov, &out_num, op_info->iv_len);

        curr_size += op_info->iv_len;

    }



    /* Handle additional authentication data if exists */

    if (op_info->aad_len > 0) {

        DPRINTF("aad_len=%" PRIu32 "\n", op_info->aad_len);

        op_info->aad_data = op_info->data + curr_size;



        s = iov_to_buf(iov, out_num, 0, op_info->aad_data, op_info->aad_len);

        if (unlikely(s != op_info->aad_len)) {

            virtio_error(vdev, "virtio-crypto additional auth data incorrect");

            goto err;

        }

        iov_discard_front(&iov, &out_num, op_info->aad_len);



        curr_size += op_info->aad_len;

    }



    /* Handle the source data */

    if (op_info->src_len > 0) {

        DPRINTF("src_len=%" PRIu32 "\n", op_info->src_len);

        op_info->src = op_info->data + curr_size;



        s = iov_to_buf(iov, out_num, 0, op_info->src, op_info->src_len);

        if (unlikely(s != op_info->src_len)) {

            virtio_error(vdev, "virtio-crypto source data incorrect");

            goto err;

        }

        iov_discard_front(&iov, &out_num, op_info->src_len);



        curr_size += op_info->src_len;

    }



    /* Handle the destination data */

    op_info->dst = op_info->data + curr_size;

    curr_size += op_info->dst_len;



    DPRINTF("dst_len=%" PRIu32 "\n", op_info->dst_len);



    /* Handle the hash digest result */

    if (hash_result_len > 0) {

        DPRINTF("hash_result_len=%" PRIu32 "\n", hash_result_len);

        op_info->digest_result = op_info->data + curr_size;

    }



    return op_info;



err:

    g_free(op_info);

    return NULL;

}

static int xenfb_map_fb(struct XenFB *xenfb)

{

    struct xenfb_page *page = xenfb->c.page;

    char *protocol = xenfb->c.xendev.protocol;

    int n_fbdirs;

    unsigned long *pgmfns = NULL;

    unsigned long *fbmfns = NULL;

    void *map, *pd;

    int mode, ret = -1;



    /* default to native */

    pd = page->pd;

    mode = sizeof(unsigned long) * 8;



    if (!protocol) {

	/*

	 * Undefined protocol, some guesswork needed.

	 *

	 * Old frontends which don't set the protocol use

	 * one page directory only, thus pd[1] must be zero.

	 * pd[1] of the 32bit struct layout and the lower

	 * 32 bits of pd[0] of the 64bit struct layout have

	 * the same location, so we can check that ...

	 */

	uint32_t *ptr32 = NULL;

	uint32_t *ptr64 = NULL;

#if defined(__i386__)

	ptr32 = (void*)page->pd;

	ptr64 = ((void*)page->pd) + 4;

#elif defined(__x86_64__)

	ptr32 = ((void*)page->pd) - 4;

	ptr64 = (void*)page->pd;

#endif

	if (ptr32) {

	    if (ptr32[1] == 0) {

		mode = 32;

		pd   = ptr32;

	    } else {

		mode = 64;

		pd   = ptr64;

	    }

	}

#if defined(__x86_64__)

    } else if (strcmp(protocol, XEN_IO_PROTO_ABI_X86_32) == 0) {

	/* 64bit dom0, 32bit domU */

	mode = 32;

	pd   = ((void*)page->pd) - 4;

#elif defined(__i386__)

    } else if (strcmp(protocol, XEN_IO_PROTO_ABI_X86_64) == 0) {

	/* 32bit dom0, 64bit domU */

	mode = 64;

	pd   = ((void*)page->pd) + 4;

#endif

    }



    if (xenfb->pixels) {

        munmap(xenfb->pixels, xenfb->fbpages * XC_PAGE_SIZE);

        xenfb->pixels = NULL;

    }



    xenfb->fbpages = (xenfb->fb_len + (XC_PAGE_SIZE - 1)) / XC_PAGE_SIZE;

    n_fbdirs = xenfb->fbpages * mode / 8;

    n_fbdirs = (n_fbdirs + (XC_PAGE_SIZE - 1)) / XC_PAGE_SIZE;



    pgmfns = g_malloc0(sizeof(unsigned long) * n_fbdirs);

    fbmfns = g_malloc0(sizeof(unsigned long) * xenfb->fbpages);



    xenfb_copy_mfns(mode, n_fbdirs, pgmfns, pd);

    map = xc_map_foreign_pages(xen_xc, xenfb->c.xendev.dom,

			       PROT_READ, pgmfns, n_fbdirs);

    if (map == NULL)

	goto out;

    xenfb_copy_mfns(mode, xenfb->fbpages, fbmfns, map);

    munmap(map, n_fbdirs * XC_PAGE_SIZE);



    xenfb->pixels = xc_map_foreign_pages(xen_xc, xenfb->c.xendev.dom,

					 PROT_READ | PROT_WRITE, fbmfns, xenfb->fbpages);

    if (xenfb->pixels == NULL)

	goto out;



    ret = 0; /* all is fine */



out:

    g_free(pgmfns);

    g_free(fbmfns);

    return ret;

}

static char **breakline(char *input, int *count)

{

    int c = 0;

    char *p;

    char **rval = g_malloc0(sizeof(char *));

    char **tmp;



    while (rval && (p = qemu_strsep(&input, " ")) != NULL) {

        if (!*p) {

            continue;

        }

        c++;

        tmp = g_realloc(rval, sizeof(*rval) * (c + 1));

        if (!tmp) {

            g_free(rval);

            rval = NULL;

            c = 0;

            break;

        } else {

            rval = tmp;

        }

        rval[c - 1] = p;

        rval[c] = NULL;

    }

    *count = c;

    return rval;

}

static int add_metadata_from_side_data(AVCodecContext *avctx, AVFrame *frame)

{

    int size, ret = 0;

    const uint8_t *side_metadata;

    const uint8_t *end;



    side_metadata = av_packet_get_side_data(avctx->pkt,

                                            AV_PKT_DATA_STRINGS_METADATA, &size);

    if (!side_metadata)

        goto end;

    end = side_metadata + size;

    while (side_metadata < end) {

        const uint8_t *key = side_metadata;

        const uint8_t *val = side_metadata + strlen(key) + 1;

        int ret = av_dict_set(avpriv_frame_get_metadatap(frame), key, val, 0);

        if (ret < 0)

            break;

        side_metadata = val + strlen(val) + 1;

    }

end:

    return ret;

}

uint8_t *av_packet_pack_dictionary(AVDictionary *dict, int *size)

{

    AVDictionaryEntry *t = NULL;

    uint8_t *data = NULL;

    *size = 0;



    if (!dict)

        return NULL;



    while ((t = av_dict_get(dict, "", t, AV_DICT_IGNORE_SUFFIX))) {

        const int keylen = strlen(t->key);

        const int valuelen = strlen(t->value);

        const size_t new_size = *size + keylen + 1 + valuelen + 1;

        uint8_t *const new_data = av_realloc(data, new_size);



        if (!new_data)

            goto fail;

        data = new_data;



        memcpy(data + *size, t->key, keylen + 1);

        memcpy(data + *size + keylen + 1, t->value, valuelen + 1);



        *size = new_size;

    }



    return data;



fail:

    av_freep(&data);

    *size = 0;

    return NULL;

}

static int seek_test(const char *input_filename, const char *start, const char *end)

{

    AVCodec *codec = NULL;

    AVCodecContext *ctx= NULL;

    AVCodecParameters *origin_par = NULL;

    AVFrame *fr = NULL;

    AVFormatContext *fmt_ctx = NULL;

    int video_stream;

    int result;

    int i, j;

    long int start_ts, end_ts;



    size_of_array = 0;

    number_of_elements = 0;

    crc_array = pts_array = NULL;



    result = avformat_open_input(&fmt_ctx, input_filename, NULL, NULL);

    if (result < 0) {

        av_log(NULL, AV_LOG_ERROR, "Can't open file\n");

        return result;

    }



    result = avformat_find_stream_info(fmt_ctx, NULL);

    if (result < 0) {

        av_log(NULL, AV_LOG_ERROR, "Can't get stream info\n");

        return result;

    }



    start_ts = read_seek_range(start);

    end_ts = read_seek_range(end);

    if ((start_ts < 0) || (end_ts < 0))

        return -1;



    //TODO: add ability to work with audio format

    video_stream = av_find_best_stream(fmt_ctx, AVMEDIA_TYPE_VIDEO, -1, -1, NULL, 0);

    if (video_stream < 0) {

      av_log(NULL, AV_LOG_ERROR, "Can't find video stream in input file\n");

      return -1;

    }



    origin_par = fmt_ctx->streams[video_stream]->codecpar;



    codec = avcodec_find_decoder(origin_par->codec_id);

    if (!codec) {

        av_log(NULL, AV_LOG_ERROR, "Can't find decoder\n");

        return -1;

    }



    ctx = avcodec_alloc_context3(codec);

    if (!ctx) {

        av_log(NULL, AV_LOG_ERROR, "Can't allocate decoder context\n");

        return AVERROR(ENOMEM);

    }



    result = avcodec_parameters_to_context(ctx, origin_par);

    if (result) {

        av_log(NULL, AV_LOG_ERROR, "Can't copy decoder context\n");

        return result;

    }



    result = avcodec_open2(ctx, codec, NULL);

    if (result < 0) {

        av_log(ctx, AV_LOG_ERROR, "Can't open decoder\n");

        return result;

    }



    fr = av_frame_alloc();

    if (!fr) {

        av_log(NULL, AV_LOG_ERROR, "Can't allocate frame\n");

        return AVERROR(ENOMEM);

    }



    result = compute_crc_of_packets(fmt_ctx, video_stream, ctx, fr, 0, 0, 1);

    if (result != 0)

        return -1;



    for (i = start_ts; i < end_ts; i += 100) {

        for (j = i + 100; j < end_ts; j += 100)

        result = compute_crc_of_packets(fmt_ctx, video_stream, ctx, fr, i, j, 0);

        if (result != 0)

            return -1;

    }



    av_freep(&crc_array);

    av_freep(&pts_array);

    av_frame_free(&fr);

    avcodec_close(ctx);

    avformat_close_input(&fmt_ctx);

    avcodec_free_context(&ctx);

    return 0;

}

int av_interleave_packet_per_dts(AVFormatContext *s, AVPacket *out, AVPacket *pkt, int flush){

    AVPacketList *pktl, **next_point, *this_pktl;

    int stream_count=0;

    int streams[MAX_STREAMS];



    if(pkt){

        AVStream *st= s->streams[ pkt->stream_index];



//        assert(pkt->destruct != av_destruct_packet); //FIXME



        this_pktl = av_mallocz(sizeof(AVPacketList));

        this_pktl->pkt= *pkt;

        if(pkt->destruct == av_destruct_packet)

            pkt->destruct= NULL; // not shared -> must keep original from being freed

        else

            av_dup_packet(&this_pktl->pkt);  //shared -> must dup



        next_point = &s->packet_buffer;

        while(*next_point){

            AVStream *st2= s->streams[ (*next_point)->pkt.stream_index];

            int64_t left=  st2->time_base.num * (int64_t)st ->time_base.den;

            int64_t right= st ->time_base.num * (int64_t)st2->time_base.den;

            if((*next_point)->pkt.dts * left > pkt->dts * right) //FIXME this can overflow

                break;

            next_point= &(*next_point)->next;

        }

        this_pktl->next= *next_point;

        *next_point= this_pktl;

    }



    memset(streams, 0, sizeof(streams));

    pktl= s->packet_buffer;

    while(pktl){

//av_log(s, AV_LOG_DEBUG, "show st:%d dts:%"PRId64"\n", pktl->pkt.stream_index, pktl->pkt.dts);

        if(streams[ pktl->pkt.stream_index ] == 0)

            stream_count++;

        streams[ pktl->pkt.stream_index ]++;

        pktl= pktl->next;

    }



    if(s->nb_streams == stream_count || (flush && stream_count)){

        pktl= s->packet_buffer;

        *out= pktl->pkt;



        s->packet_buffer= pktl->next;

        av_freep(&pktl);

        return 1;

    }else{

        av_init_packet(out);

        return 0;

    }

}

void op_cp1_enabled(void)

{

    if (!(env->CP0_Status & (1 << CP0St_CU1))) {

        CALL_FROM_TB2(do_raise_exception_err, EXCP_CpU, 1);

    }

    RETURN();

}

void op_mtc0_status (void)

{

    uint32_t val, old;

    uint32_t mask = env->Status_rw_bitmask;



    /* No reverse endianness, no MDMX/DSP, no 64bit ops

       implemented. */

    val = T0 & mask;

    old = env->CP0_Status;

    if (!(val & (1 << CP0St_EXL)) &&

        !(val & (1 << CP0St_ERL)) &&

        !(env->hflags & MIPS_HFLAG_DM) &&

        (val & (1 << CP0St_UM)))

        env->hflags |= MIPS_HFLAG_UM;

#ifdef TARGET_MIPS64

    if ((env->hflags & MIPS_HFLAG_UM) &&

        !(val & (1 << CP0St_PX)) &&

        !(val & (1 << CP0St_UX)))

        env->hflags &= ~MIPS_HFLAG_64;

#endif

    env->CP0_Status = (env->CP0_Status & ~mask) | val;

    if (loglevel & CPU_LOG_EXEC)

        CALL_FROM_TB2(do_mtc0_status_debug, old, val);

    CALL_FROM_TB1(cpu_mips_update_irq, env);

    RETURN();

}

