int ff_mpeg1_find_frame_end(ParseContext *pc, const uint8_t *buf, int buf_size, AVCodecParserContext *s)

{

    int i;

    uint32_t state = pc->state;



    /* EOF considered as end of frame */

    if (buf_size == 0)

        return 0;



/*

 0  frame start         -> 1/4

 1  first_SEQEXT        -> 0/2

 2  first field start   -> 3/0

 3  second_SEQEXT       -> 2/0

 4  searching end

*/



    for (i = 0; i < buf_size; i++) {

        av_assert1(pc->frame_start_found >= 0 && pc->frame_start_found <= 4);

        if (pc->frame_start_found & 1) {

            if (state == EXT_START_CODE && (buf[i] & 0xF0) != 0x80)

                pc->frame_start_found--;

            else if (state == EXT_START_CODE + 2) {

                if ((buf[i] & 3) == 3)

                    pc->frame_start_found = 0;

                else

                    pc->frame_start_found = (pc->frame_start_found + 1) & 3;

            }

            state++;

        } else {

            i = avpriv_find_start_code(buf + i, buf + buf_size, &state) - buf - 1;

            if (pc->frame_start_found == 0 && state >= SLICE_MIN_START_CODE && state <= SLICE_MAX_START_CODE) {

                i++;

                pc->frame_start_found = 4;

            }

            if (state == SEQ_END_CODE) {

                pc->frame_start_found = 0;

                pc->state=-1;

                return i+1;

            }

            if (pc->frame_start_found == 2 && state == SEQ_START_CODE)

                pc->frame_start_found = 0;

            if (pc->frame_start_found  < 4 && state == EXT_START_CODE)

                pc->frame_start_found++;

            if (pc->frame_start_found == 4 && (state & 0xFFFFFF00) == 0x100) {

                if (state < SLICE_MIN_START_CODE || state > SLICE_MAX_START_CODE) {

                    pc->frame_start_found = 0;

                    pc->state             = -1;

                    return i - 3;

                }

            }

            if (pc->frame_start_found == 0 && s && state == PICTURE_START_CODE) {

                ff_fetch_timestamp(s, i - 3, 1);

            }

        }

    }

    pc->state = state;

    return END_NOT_FOUND;

}

void ff_mpeg_set_erpic(ERPicture *dst, Picture *src)

{

    int i;




    if (!src)

        return;



    dst->f = &src->f;

    dst->tf = &src->tf;



    for (i = 0; i < 2; i++) {

        dst->motion_val[i] = src->motion_val[i];

        dst->ref_index[i] = src->ref_index[i];

    }



    dst->mb_type = src->mb_type;

    dst->field_picture = src->field_picture;

}

void ff_fetch_timestamp(AVCodecParserContext *s, int off, int remove){

    int i;



    s->dts= s->pts= AV_NOPTS_VALUE;

    s->offset= 0;

    for(i = 0; i < AV_PARSER_PTS_NB; i++) {

        if (   s->next_frame_offset + off >= s->cur_frame_offset[i]

            &&(s->     frame_offset       <  s->cur_frame_offset[i] || !s->frame_offset)

            //check is disabled  becausue mpeg-ts doesnt send complete PES packets

            && /*s->next_frame_offset + off <*/  s->cur_frame_end[i]){

            s->dts= s->cur_frame_dts[i];

            s->pts= s->cur_frame_pts[i];

            s->offset = s->next_frame_offset - s->cur_frame_offset[i];

            if(remove)

                s->cur_frame_offset[i]= INT64_MAX;

        }

    }

}

void ff_xvmc_pack_pblocks(MpegEncContext *s, int cbp)

{

    int i, j = 0;

    const int mb_block_count = 4 + (1 << s->chroma_format);



    cbp <<= 12-mb_block_count;

    for (i = 0; i < mb_block_count; i++) {

        if (cbp & (1 << 11))

            s->pblocks[i] = &s->block[j++];

        else

            s->pblocks[i] = NULL;

        cbp += cbp;

    }

}

static void escaped_string(void)

{

    int i;

    struct {

        const char *encoded;

        const char *decoded;

        int skip;

    } test_cases[] = {

        { "\"\\b\"", "\b" },

        { "\"\\f\"", "\f" },

        { "\"\\n\"", "\n" },

        { "\"\\r\"", "\r" },

        { "\"\\t\"", "\t" },

        { "\"/\"", "/" },

        { "\"\\/\"", "/", .skip = 1 },

        { "\"\\\\\"", "\\" },

        { "\"\\\"\"", "\"" },

        { "\"hello world \\\"embedded string\\\"\"",

          "hello world \"embedded string\"" },

        { "\"hello world\\nwith new line\"", "hello world\nwith new line" },

        { "\"single byte utf-8 \\u0020\"", "single byte utf-8  ", .skip = 1 },

        { "\"double byte utf-8 \\u00A2\"", "double byte utf-8 \xc2\xa2" },

        { "\"triple byte utf-8 \\u20AC\"", "triple byte utf-8 \xe2\x82\xac" },

        { "'\\b'", "\b", .skip = 1 },

        { "'\\f'", "\f", .skip = 1 },

        { "'\\n'", "\n", .skip = 1 },

        { "'\\r'", "\r", .skip = 1 },

        { "'\\t'", "\t", .skip = 1 },

        { "'\\/'", "/", .skip = 1 },

        { "'\\\\'", "\\", .skip = 1 },

        {}

    };



    for (i = 0; test_cases[i].encoded; i++) {

        QObject *obj;

        QString *str;



        obj = qobject_from_json(test_cases[i].encoded, NULL);

        str = qobject_to_qstring(obj);

        g_assert(str);

        g_assert_cmpstr(qstring_get_str(str), ==, test_cases[i].decoded);



        if (test_cases[i].skip == 0) {

            str = qobject_to_json(obj);

            g_assert_cmpstr(qstring_get_str(str), ==, test_cases[i].encoded);

            qobject_decref(obj);

        }



        QDECREF(str);

    }

}

