static void gen_mullwo(DisasContext *ctx)

{

    TCGv_i32 t0 = tcg_temp_new_i32();

    TCGv_i32 t1 = tcg_temp_new_i32();



    tcg_gen_trunc_tl_i32(t0, cpu_gpr[rA(ctx->opcode)]);

    tcg_gen_trunc_tl_i32(t1, cpu_gpr[rB(ctx->opcode)]);

    tcg_gen_muls2_i32(t0, t1, t0, t1);

#if defined(TARGET_PPC64)

    tcg_gen_concat_i32_i64(cpu_gpr[rD(ctx->opcode)], t0, t1);

#else

    tcg_gen_mov_i32(cpu_gpr[rD(ctx->opcode)], t0);

#endif



    tcg_gen_sari_i32(t0, t0, 31);

    tcg_gen_setcond_i32(TCG_COND_NE, t0, t0, t1);

    tcg_gen_extu_i32_tl(cpu_ov, t0);




    tcg_gen_or_tl(cpu_so, cpu_so, cpu_ov);



    tcg_temp_free_i32(t0);

    tcg_temp_free_i32(t1);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rD(ctx->opcode)]);

static void gen_lswi(DisasContext *ctx)

{

    TCGv t0;

    TCGv_i32 t1, t2;

    int nb = NB(ctx->opcode);

    int start = rD(ctx->opcode);

    int ra = rA(ctx->opcode);

    int nr;



    if (nb == 0)

        nb = 32;

    nr = nb / 4;

    if (unlikely(((start + nr) > 32  &&

                  start <= ra && (start + nr - 32) > ra) ||

                 ((start + nr) <= 32 && start <= ra && (start + nr) > ra))) {

        gen_inval_exception(ctx, POWERPC_EXCP_INVAL_LSWX);

        return;

    }

    gen_set_access_type(ctx, ACCESS_INT);

    /* NIP cannot be restored if the memory exception comes from an helper */

    gen_update_nip(ctx, ctx->nip - 4);

    t0 = tcg_temp_new();

    gen_addr_register(ctx, t0);

    t1 = tcg_const_i32(nb);

    t2 = tcg_const_i32(start);

    gen_helper_lsw(cpu_env, t0, t1, t2);

    tcg_temp_free(t0);

    tcg_temp_free_i32(t1);

    tcg_temp_free_i32(t2);

}

static void gen_maskg(DisasContext *ctx)

{

    int l1 = gen_new_label();

    TCGv t0 = tcg_temp_new();

    TCGv t1 = tcg_temp_new();

    TCGv t2 = tcg_temp_new();

    TCGv t3 = tcg_temp_new();

    tcg_gen_movi_tl(t3, 0xFFFFFFFF);

    tcg_gen_andi_tl(t0, cpu_gpr[rB(ctx->opcode)], 0x1F);

    tcg_gen_andi_tl(t1, cpu_gpr[rS(ctx->opcode)], 0x1F);

    tcg_gen_addi_tl(t2, t0, 1);

    tcg_gen_shr_tl(t2, t3, t2);

    tcg_gen_shr_tl(t3, t3, t1);

    tcg_gen_xor_tl(cpu_gpr[rA(ctx->opcode)], t2, t3);

    tcg_gen_brcond_tl(TCG_COND_GE, t0, t1, l1);

    tcg_gen_neg_tl(cpu_gpr[rA(ctx->opcode)], cpu_gpr[rA(ctx->opcode)]);

    gen_set_label(l1);

    tcg_temp_free(t0);

    tcg_temp_free(t1);

    tcg_temp_free(t2);

    tcg_temp_free(t3);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rA(ctx->opcode)]);

}

static void read_tree(GetBitContext *gb, Tree *tree)

{

    uint8_t tmp1[16], tmp2[16], *in = tmp1, *out = tmp2;

    int i, t, len;



    tree->vlc_num = get_bits(gb, 4);

    if (!tree->vlc_num) {

        for (i = 0; i < 16; i++)

            tree->syms[i] = i;

        return;

    }

    if (get_bits1(gb)) {

        len = get_bits(gb, 3);

        memset(tmp1, 0, sizeof(tmp1));

        for (i = 0; i <= len; i++) {

            tree->syms[i] = get_bits(gb, 4);

            tmp1[tree->syms[i]] = 1;

        }

        for (i = 0; i < 16; i++)

            if (!tmp1[i])

                tree->syms[++len] = i;

    } else {

        len = get_bits(gb, 2);

        for (i = 0; i < 16; i++)

            in[i] = i;

        for (i = 0; i <= len; i++) {

            int size = 1 << i;

            for (t = 0; t < 16; t += size << 1)

                merge(gb, out + t, in + t, size);

            FFSWAP(uint8_t*, in, out);

        }

        memcpy(tree->syms, in, 16);

    }

}

static int decode_packet(AVCodecContext *avctx, void *data,

                         int *got_frame_ptr, AVPacket* avpkt)

{

    WMAProDecodeCtx *s = avctx->priv_data;

    GetBitContext* gb  = &s->pgb;

    const uint8_t* buf = avpkt->data;

    int buf_size       = avpkt->size;

    int num_bits_prev_frame;

    int packet_sequence_number;



    *got_frame_ptr = 0;



    if (s->packet_done || s->packet_loss) {

        s->packet_done = 0;



        /** sanity check for the buffer length */

        if (buf_size < avctx->block_align) {

            av_log(avctx, AV_LOG_ERROR, "Input packet too small (%d < %d)\n",

                   buf_size, avctx->block_align);

            return AVERROR_INVALIDDATA;

        }



        s->next_packet_start = buf_size - avctx->block_align;

        buf_size = avctx->block_align;

        s->buf_bit_size = buf_size << 3;



        /** parse packet header */

        init_get_bits(gb, buf, s->buf_bit_size);

        packet_sequence_number = get_bits(gb, 4);

        skip_bits(gb, 2);



        /** get number of bits that need to be added to the previous frame */

        num_bits_prev_frame = get_bits(gb, s->log2_frame_size);

        av_dlog(avctx, "packet[%d]: nbpf %x\n", avctx->frame_number,

                num_bits_prev_frame);



        /** check for packet loss */

        if (!s->packet_loss &&

            ((s->packet_sequence_number + 1) & 0xF) != packet_sequence_number) {

            s->packet_loss = 1;

            av_log(avctx, AV_LOG_ERROR, "Packet loss detected! seq %x vs %x\n",

                   s->packet_sequence_number, packet_sequence_number);

        }

        s->packet_sequence_number = packet_sequence_number;



        if (num_bits_prev_frame > 0) {

            int remaining_packet_bits = s->buf_bit_size - get_bits_count(gb);

            if (num_bits_prev_frame >= remaining_packet_bits) {

                num_bits_prev_frame = remaining_packet_bits;

                s->packet_done = 1;

            }



            /** append the previous frame data to the remaining data from the

                previous packet to create a full frame */

            save_bits(s, gb, num_bits_prev_frame, 1);

            av_dlog(avctx, "accumulated %x bits of frame data\n",

                    s->num_saved_bits - s->frame_offset);



            /** decode the cross packet frame if it is valid */

            if (!s->packet_loss)

                decode_frame(s, data, got_frame_ptr);

        } else if (s->num_saved_bits - s->frame_offset) {

            av_dlog(avctx, "ignoring %x previously saved bits\n",

                    s->num_saved_bits - s->frame_offset);

        }



        if (s->packet_loss) {

            /** reset number of saved bits so that the decoder

                does not start to decode incomplete frames in the

                s->len_prefix == 0 case */

            s->num_saved_bits = 0;

            s->packet_loss = 0;

        }



    } else {

        int frame_size;

        s->buf_bit_size = (avpkt->size - s->next_packet_start) << 3;

        init_get_bits(gb, avpkt->data, s->buf_bit_size);

        skip_bits(gb, s->packet_offset);

        if (s->len_prefix && remaining_bits(s, gb) > s->log2_frame_size &&

            (frame_size = show_bits(gb, s->log2_frame_size)) &&

            frame_size <= remaining_bits(s, gb)) {

            save_bits(s, gb, frame_size, 0);

            s->packet_done = !decode_frame(s, data, got_frame_ptr);

        } else if (!s->len_prefix

                   && s->num_saved_bits > get_bits_count(&s->gb)) {

            /** when the frames do not have a length prefix, we don't know

                the compressed length of the individual frames

                however, we know what part of a new packet belongs to the

                previous frame

                therefore we save the incoming packet first, then we append

                the "previous frame" data from the next packet so that

                we get a buffer that only contains full frames */

            s->packet_done = !decode_frame(s, data, got_frame_ptr);

        } else

            s->packet_done = 1;

    }



    if (s->packet_done && !s->packet_loss &&

        remaining_bits(s, gb) > 0) {

        /** save the rest of the data so that it can be decoded

            with the next packet */

        save_bits(s, gb, remaining_bits(s, gb), 0);

    }



    s->packet_offset = get_bits_count(gb) & 7;

    if (s->packet_loss)

        return AVERROR_INVALIDDATA;



    return get_bits_count(gb) >> 3;

}

static av_cold int atrac3_decode_init(AVCodecContext *avctx)

{

    int i, ret;

    int version, delay, samples_per_frame, frame_factor;

    const uint8_t *edata_ptr = avctx->extradata;

    ATRAC3Context *q = avctx->priv_data;



    if (avctx->channels <= 0 || avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Channel configuration error!\n");

        return AVERROR(EINVAL);

    }



    /* Take care of the codec-specific extradata. */

    if (avctx->extradata_size == 14) {

        /* Parse the extradata, WAV format */

        av_log(avctx, AV_LOG_DEBUG, "[0-1] %d\n",

               bytestream_get_le16(&edata_ptr));  // Unknown value always 1

        edata_ptr += 4;                             // samples per channel

        q->coding_mode = bytestream_get_le16(&edata_ptr);

        av_log(avctx, AV_LOG_DEBUG,"[8-9] %d\n",

               bytestream_get_le16(&edata_ptr));  //Dupe of coding mode

        frame_factor = bytestream_get_le16(&edata_ptr);  // Unknown always 1

        av_log(avctx, AV_LOG_DEBUG,"[12-13] %d\n",

               bytestream_get_le16(&edata_ptr));  // Unknown always 0



        /* setup */

        samples_per_frame    = SAMPLES_PER_FRAME * avctx->channels;

        version              = 4;

        delay                = 0x88E;

        q->coding_mode       = q->coding_mode ? JOINT_STEREO : STEREO;

        q->scrambled_stream  = 0;



        if (avctx->block_align !=  96 * avctx->channels * frame_factor &&

            avctx->block_align != 152 * avctx->channels * frame_factor &&

            avctx->block_align != 192 * avctx->channels * frame_factor) {

            av_log(avctx, AV_LOG_ERROR, "Unknown frame/channel/frame_factor "

                   "configuration %d/%d/%d\n", avctx->block_align,

                   avctx->channels, frame_factor);

            return AVERROR_INVALIDDATA;

        }

    } else if (avctx->extradata_size == 10) {

        /* Parse the extradata, RM format. */

        version                = bytestream_get_be32(&edata_ptr);

        samples_per_frame      = bytestream_get_be16(&edata_ptr);

        delay                  = bytestream_get_be16(&edata_ptr);

        q->coding_mode         = bytestream_get_be16(&edata_ptr);

        q->scrambled_stream    = 1;



    } else {

        av_log(NULL, AV_LOG_ERROR, "Unknown extradata size %d.\n",

               avctx->extradata_size);

        return AVERROR(EINVAL);

    }



    /* Check the extradata */



    if (version != 4) {

        av_log(avctx, AV_LOG_ERROR, "Version %d != 4.\n", version);

        return AVERROR_INVALIDDATA;

    }



    if (samples_per_frame != SAMPLES_PER_FRAME &&

        samples_per_frame != SAMPLES_PER_FRAME * 2) {

        av_log(avctx, AV_LOG_ERROR, "Unknown amount of samples per frame %d.\n",

               samples_per_frame);

        return AVERROR_INVALIDDATA;

    }



    if (delay != 0x88E) {

        av_log(avctx, AV_LOG_ERROR, "Unknown amount of delay %x != 0x88E.\n",

               delay);

        return AVERROR_INVALIDDATA;

    }



    if (q->coding_mode == STEREO)

        av_log(avctx, AV_LOG_DEBUG, "Normal stereo detected.\n");

    else if (q->coding_mode == JOINT_STEREO) {

        if (avctx->channels != 2)

            return AVERROR_INVALIDDATA;

        av_log(avctx, AV_LOG_DEBUG, "Joint stereo detected.\n");

    } else {

        av_log(avctx, AV_LOG_ERROR, "Unknown channel coding mode %x!\n",

               q->coding_mode);

        return AVERROR_INVALIDDATA;

    }



    if (avctx->block_align >= UINT_MAX / 2)

        return AVERROR(EINVAL);



    q->decoded_bytes_buffer = av_mallocz(FFALIGN(avctx->block_align, 4) +

                                         FF_INPUT_BUFFER_PADDING_SIZE);

    if (q->decoded_bytes_buffer == NULL)

        return AVERROR(ENOMEM);



    avctx->sample_fmt = AV_SAMPLE_FMT_FLTP;



    /* initialize the MDCT transform */

    if ((ret = ff_mdct_init(&q->mdct_ctx, 9, 1, 1.0 / 32768)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing MDCT\n");

        av_freep(&q->decoded_bytes_buffer);

        return ret;

    }



    /* init the joint-stereo decoding data */

    q->weighting_delay[0] = 0;

    q->weighting_delay[1] = 7;

    q->weighting_delay[2] = 0;

    q->weighting_delay[3] = 7;

    q->weighting_delay[4] = 0;

    q->weighting_delay[5] = 7;



    for (i = 0; i < 4; i++) {

        q->matrix_coeff_index_prev[i] = 3;

        q->matrix_coeff_index_now[i]  = 3;

        q->matrix_coeff_index_next[i] = 3;

    }



    ff_atrac_init_gain_compensation(&q->gainc_ctx, 4, 3);

    avpriv_float_dsp_init(&q->fdsp, avctx->flags & CODEC_FLAG_BITEXACT);

    ff_fmt_convert_init(&q->fmt_conv, avctx);



    q->units = av_mallocz(sizeof(*q->units) * avctx->channels);

    if (!q->units) {

        atrac3_decode_close(avctx);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static int decode_frame(AVCodecContext *avctx,

                        void *data, int *data_size,

                        AVPacket *avpkt)

{

    JvContext *s           = avctx->priv_data;

    const uint8_t *buf     = avpkt->data;

    const uint8_t *buf_end = buf + avpkt->size;

    int video_size, video_type, i, j;



    video_size = AV_RL32(buf);

    video_type = buf[4];

    buf += 5;



    if (video_size) {

        if (video_size < 0 || video_size > avpkt->size - 5) {

            av_log(avctx, AV_LOG_ERROR, "video size %d invalid\n", video_size);

            return AVERROR_INVALIDDATA;

        }

        if (avctx->reget_buffer(avctx, &s->frame) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        if (video_type == 0 || video_type == 1) {

            GetBitContext gb;

            init_get_bits(&gb, buf, 8 * video_size);



            for (j = 0; j < avctx->height; j += 8)

                for (i = 0; i < avctx->width; i += 8)

                    decode8x8(&gb, s->frame.data[0] + j*s->frame.linesize[0] + i,

                              s->frame.linesize[0], &s->dsp);



            buf += video_size;

        } else if (video_type == 2) {

            if (buf + 1 <= buf_end) {

                int v = *buf++;

                for (j = 0; j < avctx->height; j++)

                    memset(s->frame.data[0] + j*s->frame.linesize[0], v, avctx->width);

            }

        } else {

            av_log(avctx, AV_LOG_WARNING, "unsupported frame type %i\n", video_type);

            return AVERROR_INVALIDDATA;

        }

    }



    if (buf_end - buf >= AVPALETTE_COUNT * 3) {

        for (i = 0; i < AVPALETTE_COUNT; i++) {

            uint32_t pal = AV_RB24(buf);

            s->palette[i] = 0xFF << 24 | pal << 2 | ((pal >> 4) & 0x30303);

            buf += 3;

        }

        s->palette_has_changed = 1;

    }



    if (video_size) {

        s->frame.key_frame           = 1;

        s->frame.pict_type           = AV_PICTURE_TYPE_I;

        s->frame.palette_has_changed = s->palette_has_changed;

        s->palette_has_changed       = 0;

        memcpy(s->frame.data[1], s->palette, AVPALETTE_SIZE);



        *data_size      = sizeof(AVFrame);

        *(AVFrame*)data = s->frame;

    }



    return avpkt->size;

}

uint32_t HELPER(sar_cc)(CPUM68KState *env, uint32_t val, uint32_t shift)

{

    uint64_t temp;

    uint32_t result;



    shift &= 63;

    temp = (int64_t)val << 32 >> shift;

    result = temp >> 32;



    env->cc_c = (temp >> 31) & 1;

    env->cc_n = result;

    env->cc_z = result;

    env->cc_v = result ^ val;

    env->cc_x = shift ? env->cc_c : env->cc_x;



    return result;

}

uint32_t HELPER(shl_cc)(CPUM68KState *env, uint32_t val, uint32_t shift)

{

    uint64_t result;



    shift &= 63;

    result = (uint64_t)val << shift;



    env->cc_c = (result >> 32) & 1;

    env->cc_n = result;

    env->cc_z = result;

    env->cc_v = 0;

    env->cc_x = shift ? env->cc_c : env->cc_x;



    return result;

}

uint32_t HELPER(lpdbr)(CPUS390XState *env, uint32_t f1, uint32_t f2)

{

    float64 v1;

    float64 v2 = env->fregs[f2].d;



    v1 = float64_abs(v2);

    env->fregs[f1].d = v1;

    return set_cc_nz_f64(v1);

}

uint32_t HELPER(lpxbr)(CPUS390XState *env, uint32_t f1, uint32_t f2)

{

    CPU_QuadU v1;

    CPU_QuadU v2;



    v2.ll.upper = env->fregs[f2].ll;

    v2.ll.lower = env->fregs[f2 + 2].ll;

    v1.q = float128_abs(v2.q);

    env->fregs[f1].ll = v1.ll.upper;

    env->fregs[f1 + 2].ll = v1.ll.lower;

    return set_cc_nz_f128(v1.q);

}

static void term_up_char(void)

{

    int idx;



    if (term_hist_entry == 0)

	return;

    if (term_hist_entry == -1) {

	/* Find latest entry */

	for (idx = 0; idx < TERM_MAX_CMDS; idx++) {

	    if (term_history[idx] == NULL)

		break;

	}

	term_hist_entry = idx;

    }

    term_hist_entry--;

    if (term_hist_entry >= 0) {

	strcpy(term_cmd_buf, term_history[term_hist_entry]);

	term_printf("\n");

	term_print_cmdline(term_cmd_buf);

	term_cmd_buf_index = term_cmd_buf_size = strlen(term_cmd_buf);

    }

}

