static int decode_mime_header(AMRWBContext *ctx, const uint8_t *buf)

{

    /* Decode frame header (1st octet) */

    ctx->fr_cur_mode  = buf[0] >> 3 & 0x0F;

    ctx->fr_quality   = (buf[0] & 0x4) != 0x4;



    return 1;

}

static int decode_cabac_mb_cbp_chroma( H264Context *h) {

    int ctx;

    int cbp_a, cbp_b;



    cbp_a = (h->left_cbp>>4)&0x03;

    cbp_b = (h-> top_cbp>>4)&0x03;



    ctx = 0;

    if( cbp_a > 0 ) ctx++;

    if( cbp_b > 0 ) ctx += 2;

    if( get_cabac( &h->cabac, &h->cabac_state[77 + ctx] ) == 0 )

        return 0;



    ctx = 4;

    if( cbp_a == 2 ) ctx++;

    if( cbp_b == 2 ) ctx += 2;

    return 1 + get_cabac( &h->cabac, &h->cabac_state[77 + ctx] );

}

static int decode_cabac_mb_chroma_pre_mode( H264Context *h) {

    const int mba_xy = h->left_mb_xy[0];

    const int mbb_xy = h->top_mb_xy;



    int ctx = 0;



    /* No need to test for IS_INTRA4x4 and IS_INTRA16x16, as we set chroma_pred_mode_table to 0 */

    if( h->slice_table[mba_xy] == h->slice_num && h->chroma_pred_mode_table[mba_xy] != 0 )

        ctx++;



    if( h->slice_table[mbb_xy] == h->slice_num && h->chroma_pred_mode_table[mbb_xy] != 0 )

        ctx++;



    if( get_cabac( &h->cabac, &h->cabac_state[64+ctx] ) == 0 )

        return 0;



    if( get_cabac( &h->cabac, &h->cabac_state[64+3] ) == 0 )

        return 1;

    if( get_cabac( &h->cabac, &h->cabac_state[64+3] ) == 0 )

        return 2;

    else

        return 3;

}

static int check_mv(H264Context *h, long b_idx, long bn_idx, int mvy_limit){

    int v;



    v = h->ref_cache[0][b_idx] != h->ref_cache[0][bn_idx] |

        h->mv_cache[0][b_idx][0] - h->mv_cache[0][bn_idx][0] + 3 >= 7U |

        FFABS( h->mv_cache[0][b_idx][1] - h->mv_cache[0][bn_idx][1] ) >= mvy_limit;



    if(h->list_count==2){

        if(!v)

            v = h->ref_cache[1][b_idx] != h->ref_cache[1][bn_idx] |

                h->mv_cache[1][b_idx][0] - h->mv_cache[1][bn_idx][0] + 3 >= 7U |

                FFABS( h->mv_cache[1][b_idx][1] - h->mv_cache[1][bn_idx][1] ) >= mvy_limit;



        if(v){

            if(h->ref_cache[0][b_idx] != h->ref_cache[1][bn_idx] |

               h->ref_cache[1][b_idx] != h->ref_cache[0][bn_idx])

                return 1;

            return

                h->mv_cache[0][b_idx][0] - h->mv_cache[1][bn_idx][0] + 3 >= 7U |

                FFABS( h->mv_cache[0][b_idx][1] - h->mv_cache[1][bn_idx][1] ) >= mvy_limit |

                h->mv_cache[1][b_idx][0] - h->mv_cache[0][bn_idx][0] + 3 >= 7U |

                FFABS( h->mv_cache[1][b_idx][1] - h->mv_cache[0][bn_idx][1] ) >= mvy_limit;

        }

    }



    return v;

}

static void close_decoder(QSVContext *q)

{

    QSVFrame *cur;



    if (q->session)

        MFXVideoDECODE_Close(q->session);



    while (q->async_fifo && av_fifo_size(q->async_fifo)) {

        QSVFrame *out_frame;

        mfxSyncPoint *sync;



        av_fifo_generic_read(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

        av_fifo_generic_read(q->async_fifo, &sync,      sizeof(sync),      NULL);



        av_freep(&sync);

    }



    cur = q->work_frames;

    while (cur) {

        q->work_frames = cur->next;

        av_frame_free(&cur->frame);

        av_freep(&cur);

        cur = q->work_frames;

    }



    q->engine_ready   = 0;

    q->reinit_pending = 0;

}

static int do_qsv_decode(AVCodecContext *avctx, QSVContext *q,

                  AVFrame *frame, int *got_frame,

                  AVPacket *avpkt)

{

    QSVFrame *out_frame;

    mfxFrameSurface1 *insurf;

    mfxFrameSurface1 *outsurf;

    mfxSyncPoint *sync;

    mfxBitstream bs = { { { 0 } } };

    int ret;

    int n_out_frames;

    int buffered = 0;

    int flush    = !avpkt->size || q->reinit_pending;



    if (!q->engine_ready) {

        ret = qsv_decode_init(avctx, q, avpkt);

        if (ret)

            return ret;

    }



    if (!flush) {

        if (av_fifo_size(q->input_fifo)) {

            /* we have got rest of previous packet into buffer */

            if (av_fifo_space(q->input_fifo) < avpkt->size) {

                ret = av_fifo_grow(q->input_fifo, avpkt->size);

                if (ret < 0)

                    return ret;

            }

            av_fifo_generic_write(q->input_fifo, avpkt->data, avpkt->size, NULL);

            bs.Data       = q->input_fifo->rptr;

            bs.DataLength = av_fifo_size(q->input_fifo);

            buffered = 1;

        } else {

            bs.Data       = avpkt->data;

            bs.DataLength = avpkt->size;

        }

        bs.MaxLength  = bs.DataLength;

        bs.TimeStamp  = avpkt->pts;

    }



    sync = av_mallocz(sizeof(*sync));

    if (!sync) {

        av_freep(&sync);

        return AVERROR(ENOMEM);

    }



    while (1) {

        ret = get_surface(avctx, q, &insurf);

        if (ret < 0)

            return ret;

        do {

            ret = MFXVideoDECODE_DecodeFrameAsync(q->session, flush ? NULL : &bs,

                                                  insurf, &outsurf, sync);

            if (ret != MFX_WRN_DEVICE_BUSY)

                break;

            av_usleep(500);

        } while (1);



        if (MFX_WRN_VIDEO_PARAM_CHANGED==ret) {

            /* TODO: handle here minor sequence header changing */

        } else if (MFX_ERR_INCOMPATIBLE_VIDEO_PARAM==ret) {

            av_fifo_reset(q->input_fifo);

            flush = q->reinit_pending = 1;

            continue;

        }



        if (*sync) {

            QSVFrame *out_frame = find_frame(q, outsurf);



            if (!out_frame) {

                av_freep(&sync);

                av_log(avctx, AV_LOG_ERROR,

                       "The returned surface does not correspond to any frame\n");

                return AVERROR_BUG;

            }



            out_frame->queued = 1;

            av_fifo_generic_write(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

            av_fifo_generic_write(q->async_fifo, &sync,      sizeof(sync),      NULL);



            continue;

        } else {

            av_freep(&sync);

        }

        if (MFX_ERR_MORE_SURFACE != ret && ret < 0)

            break;

    }



    /* make sure we do not enter an infinite loop if the SDK

     * did not consume any data and did not return anything */

    if (!*sync && !bs.DataOffset && !flush) {

        av_log(avctx, AV_LOG_WARNING, "A decode call did not consume any data\n");

        bs.DataOffset = avpkt->size;

    }



    if (buffered) {

        qsv_fifo_relocate(q->input_fifo, bs.DataOffset);

    } else if (bs.DataOffset!=avpkt->size) {

        /* some data of packet was not consumed. store it to local buffer */

        av_fifo_generic_write(q->input_fifo, avpkt->data+bs.DataOffset,

                              avpkt->size - bs.DataOffset, NULL);

    }



    if (MFX_ERR_MORE_DATA!=ret && ret < 0) {

        av_freep(&sync);

        av_log(avctx, AV_LOG_ERROR, "Error %d during QSV decoding.\n", ret);

        return ff_qsv_error(ret);

    }

    n_out_frames = av_fifo_size(q->async_fifo) / (sizeof(out_frame)+sizeof(sync));



    if (n_out_frames > q->async_depth || (flush && n_out_frames) ) {

        AVFrame *src_frame;



        av_fifo_generic_read(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

        av_fifo_generic_read(q->async_fifo, &sync,      sizeof(sync),      NULL);

        out_frame->queued = 0;



        do {

            ret = MFXVideoCORE_SyncOperation(q->session, *sync, 1000);

        } while (ret == MFX_WRN_IN_EXECUTION);



        av_freep(&sync);



        src_frame = out_frame->frame;



        ret = av_frame_ref(frame, src_frame);

        if (ret < 0)

            return ret;



        outsurf = out_frame->surface;



        frame->pkt_pts = frame->pts = outsurf->Data.TimeStamp;



        frame->repeat_pict =

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FRAME_TRIPLING ? 4 :

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FRAME_DOUBLING ? 2 :

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FIELD_REPEATED ? 1 : 0;

        frame->top_field_first =

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FIELD_TFF;

        frame->interlaced_frame =

            !(outsurf->Info.PicStruct & MFX_PICSTRUCT_PROGRESSIVE);



        *got_frame = 1;

    }



    return avpkt->size;

}

int ff_qsv_enc_close(AVCodecContext *avctx, QSVEncContext *q)

{

    QSVFrame *cur;



    MFXVideoENCODE_Close(q->session);

    if (q->internal_session)

        MFXClose(q->internal_session);

    q->session          = NULL;

    q->internal_session = NULL;



    cur = q->work_frames;

    while (cur) {

        q->work_frames = cur->next;

        av_frame_free(&cur->frame);

        av_freep(&cur);

        cur = q->work_frames;

    }



    while (q->async_fifo && av_fifo_size(q->async_fifo)) {

        AVPacket pkt;

        mfxSyncPoint sync;

        mfxBitstream *bs;



        av_fifo_generic_read(q->async_fifo, &pkt,  sizeof(pkt),  NULL);

        av_fifo_generic_read(q->async_fifo, &sync, sizeof(sync), NULL);

        av_fifo_generic_read(q->async_fifo, &bs,   sizeof(bs),   NULL);



        av_freep(&bs);

        av_packet_unref(&pkt);

    }

    av_fifo_free(q->async_fifo);

    q->async_fifo = NULL;



    av_frame_free(&avctx->coded_frame);



    return 0;

}

static int qsv_decode(AVCodecContext *avctx, QSVContext *q,

                      AVFrame *frame, int *got_frame,

                      AVPacket *avpkt)

{

    QSVFrame *out_frame;

    mfxFrameSurface1 *insurf;

    mfxFrameSurface1 *outsurf;

    mfxSyncPoint *sync;

    mfxBitstream bs = { { { 0 } } };

    int ret;



    if (avpkt->size) {

        bs.Data       = avpkt->data;

        bs.DataLength = avpkt->size;

        bs.MaxLength  = bs.DataLength;

        bs.TimeStamp  = avpkt->pts;

    }



    sync = av_mallocz(sizeof(*sync));

    if (!sync) {

        av_freep(&sync);

        return AVERROR(ENOMEM);

    }



    do {

        ret = get_surface(avctx, q, &insurf);

        if (ret < 0)

            return ret;



        ret = MFXVideoDECODE_DecodeFrameAsync(q->session, avpkt->size ? &bs : NULL,

                                              insurf, &outsurf, sync);

        if (ret == MFX_WRN_DEVICE_BUSY)

            av_usleep(500);



    } while (ret == MFX_WRN_DEVICE_BUSY || ret == MFX_ERR_MORE_SURFACE);



    if (ret != MFX_ERR_NONE &&

        ret != MFX_ERR_MORE_DATA &&

        ret != MFX_WRN_VIDEO_PARAM_CHANGED &&

        ret != MFX_ERR_MORE_SURFACE) {

        av_log(avctx, AV_LOG_ERROR, "Error during QSV decoding.\n");

        av_freep(&sync);

        return ff_qsv_error(ret);

    }



    /* make sure we do not enter an infinite loop if the SDK

     * did not consume any data and did not return anything */

    if (!*sync && !bs.DataOffset) {

        av_log(avctx, AV_LOG_WARNING, "A decode call did not consume any data\n");

        bs.DataOffset = avpkt->size;

    }



    if (*sync) {

        QSVFrame *out_frame = find_frame(q, outsurf);



        if (!out_frame) {

            av_log(avctx, AV_LOG_ERROR,

                   "The returned surface does not correspond to any frame\n");

            av_freep(&sync);

            return AVERROR_BUG;

        }



        out_frame->queued = 1;

        av_fifo_generic_write(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

        av_fifo_generic_write(q->async_fifo, &sync,      sizeof(sync),      NULL);

    } else {

        av_freep(&sync);

    }



    if (!av_fifo_space(q->async_fifo) ||

        (!avpkt->size && av_fifo_size(q->async_fifo))) {

        AVFrame *src_frame;



        av_fifo_generic_read(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

        av_fifo_generic_read(q->async_fifo, &sync,      sizeof(sync),      NULL);

        out_frame->queued = 0;



        do {

            ret = MFXVideoCORE_SyncOperation(q->session, *sync, 1000);

        } while (ret == MFX_WRN_IN_EXECUTION);



        av_freep(&sync);



        src_frame = out_frame->frame;



        ret = av_frame_ref(frame, src_frame);

        if (ret < 0)

            return ret;



        outsurf = out_frame->surface;



#if FF_API_PKT_PTS

FF_DISABLE_DEPRECATION_WARNINGS

        frame->pkt_pts = outsurf->Data.TimeStamp;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

        frame->pts = outsurf->Data.TimeStamp;



        frame->repeat_pict =

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FRAME_TRIPLING ? 4 :

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FRAME_DOUBLING ? 2 :

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FIELD_REPEATED ? 1 : 0;

        frame->top_field_first =

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FIELD_TFF;

        frame->interlaced_frame =

            !(outsurf->Info.PicStruct & MFX_PICSTRUCT_PROGRESSIVE);



        *got_frame = 1;

    }



    return bs.DataOffset;

}

