static void vty_receive(void *opaque, const uint8_t *buf, int size)

{

    VIOsPAPRVTYDevice *dev = (VIOsPAPRVTYDevice *)opaque;

    int i;



    if ((dev->in == dev->out) && size) {

        /* toggle line to simulate edge interrupt */

        qemu_irq_pulse(dev->sdev.qirq);

    }

    for (i = 0; i < size; i++) {

        assert((dev->in - dev->out) < VTERM_BUFSIZE);

        dev->buf[dev->in++ % VTERM_BUFSIZE] = buf[i];

    }

}

static void store_slice_c(uint8_t *dst, const int16_t *src,

                          int dst_stride, int src_stride,

                          int width, int height, int log2_scale)

{

    int y, x;



#define STORE(pos) do {                                                     \

    temp = ((src[x + y * src_stride + pos] << log2_scale) + d[pos]) >> 8;   \

    if (temp & 0x100) temp = ~(temp >> 31);                                 \

    dst[x + y * dst_stride + pos] = temp;                                   \

} while (0)



    for (y = 0; y < height; y++) {

        const uint8_t *d = dither[y&7];

        for (x = 0; x < width; x += 8) {

            int temp;

            STORE(0);

            STORE(1);

            STORE(2);

            STORE(3);

            STORE(4);

            STORE(5);

            STORE(6);

            STORE(7);

        }

    }

}

static void decode_rowskip(uint8_t* plane, int width, int height, int stride, VC9Context *v){

    int x, y;

    GetBitContext *gb = &v->s.gb;



    for (y=0; y<height; y++){

        if (!get_bits(gb, 1)) //rowskip

            memset(plane, 0, width);

        else

            for (x=0; x<width; x++) 

                plane[x] = get_bits(gb, 1);

        plane += stride;

    }

}

static float ssim_end4(int sum0[5][4], int sum1[5][4], int width)

{

    float ssim = 0.0;

    int i;



    for (i = 0; i < width; i++)

        ssim += ssim_end1(sum0[i][0] + sum0[i + 1][0] + sum1[i][0] + sum1[i + 1][0],

                          sum0[i][1] + sum0[i + 1][1] + sum1[i][1] + sum1[i + 1][1],

                          sum0[i][2] + sum0[i + 1][2] + sum1[i][2] + sum1[i + 1][2],

                          sum0[i][3] + sum0[i + 1][3] + sum1[i][3] + sum1[i + 1][3]);

    return ssim;

}

static void draw_line(uint8_t *buf, int sx, int sy, int ex, int ey,

                      int w, int h, int stride, int color)

{

    int x, y, fr, f;



    sx = av_clip(sx, 0, w - 1);

    sy = av_clip(sy, 0, h - 1);

    ex = av_clip(ex, 0, w - 1);

    ey = av_clip(ey, 0, h - 1);



    buf[sy * stride + sx] += color;



    if (FFABS(ex - sx) > FFABS(ey - sy)) {

        if (sx > ex) {

            FFSWAP(int, sx, ex);

            FFSWAP(int, sy, ey);

        }

        buf += sx + sy * stride;

        ex  -= sx;

        f    = ((ey - sy) << 16) / ex;

        for (x = 0; x = ex; x++) {

            y  = (x * f) >> 16;

            fr = (x * f) & 0xFFFF;

            buf[y * stride + x]       += (color * (0x10000 - fr)) >> 16;

            buf[(y + 1) * stride + x] += (color *            fr ) >> 16;

        }

    } else {

        if (sy > ey) {

            FFSWAP(int, sx, ex);

            FFSWAP(int, sy, ey);

        }

        buf += sx + sy * stride;

        ey  -= sy;

        if (ey)

            f  = ((ex - sx) << 16) / ey;

        else

            f = 0;

        for (y = 0; y = ey; y++) {

            x  = (y * f) >> 16;

            fr = (y * f) & 0xFFFF;

            buf[y * stride + x]     += (color * (0x10000 - fr)) >> 16;

            buf[y * stride + x + 1] += (color *            fr ) >> 16;

        }

    }

}

