}

static int jpeg2000_decode_packet(Jpeg2000DecoderContext *s,

                                  Jpeg2000CodingStyle *codsty,

                                  Jpeg2000ResLevel *rlevel, int precno,

                                  int layno, uint8_t *expn, int numgbits)

{

    int bandno, cblkno, ret, nb_code_blocks;



    if (!(ret = get_bits(s, 1))) {

        jpeg2000_flush(s);

        return 0;

    } else if (ret < 0)

        return ret;



    for (bandno = 0; bandno < rlevel->nbands; bandno++) {

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;



        if (band->coord[0][0] == band->coord[0][1] ||

            band->coord[1][0] == band->coord[1][1])

            continue;



        nb_code_blocks =  prec->nb_codeblocks_height *

                          prec->nb_codeblocks_width;

        for (cblkno = 0; cblkno < nb_code_blocks; cblkno++) {

            Jpeg2000Cblk *cblk = prec->cblk + cblkno;

            int incl, newpasses, llen;



            if (cblk->npasses)

                incl = get_bits(s, 1);

            else

                incl = tag_tree_decode(s, prec->cblkincl + cblkno, layno + 1) == layno;

            if (!incl)

                continue;

            else if (incl < 0)

                return incl;



            if (!cblk->npasses)

                cblk->nonzerobits = expn[bandno] + numgbits - 1 -

                                    tag_tree_decode(s, prec->zerobits + cblkno,

                                                    100);

            if ((newpasses = getnpasses(s)) < 0)

                return newpasses;

            if ((llen = getlblockinc(s)) < 0)

                return llen;

            cblk->lblock += llen;

            if ((ret = get_bits(s, av_log2(newpasses) + cblk->lblock)) < 0)

                return ret;

            cblk->lengthinc = ret;

            cblk->npasses  += newpasses;

        }

    }

    jpeg2000_flush(s);



    if (codsty->csty & JPEG2000_CSTY_EPH) {

        if (bytestream2_peek_be16(&s->g) == JPEG2000_EPH)

            bytestream2_skip(&s->g, 2);

        else

            av_log(s->avctx, AV_LOG_ERROR, "EPH marker not found.\n");

    }



    for (bandno = 0; bandno < rlevel->nbands; bandno++) {

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;



        nb_code_blocks = prec->nb_codeblocks_height * prec->nb_codeblocks_width;

        for (cblkno = 0; cblkno < nb_code_blocks; cblkno++) {

            Jpeg2000Cblk *cblk = prec->cblk + cblkno;

            if (   bytestream2_get_bytes_left(&s->g) < cblk->lengthinc

                || sizeof(cblk->data) < cblk->lengthinc

            )

                return AVERROR(EINVAL);

            /* Code-block data can be empty. In that case initialize data

             * with 0xFFFF. */

            if (cblk->lengthinc > 0) {

                bytestream2_get_bufferu(&s->g, cblk->data, cblk->lengthinc);

            } else {

                cblk->data[0] = 0xFF;

                cblk->data[1] = 0xFF;

            }

            cblk->length   += cblk->lengthinc;

            cblk->lengthinc = 0;

        }

    }

    return 0;

}

static int jpeg2000_decode_packet(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile, int *tp_index,

                                  Jpeg2000CodingStyle *codsty,

                                  Jpeg2000ResLevel *rlevel, int precno,

                                  int layno, uint8_t *expn, int numgbits)

{

    int bandno, cblkno, ret, nb_code_blocks;

    int cwsno;



    if (bytestream2_get_bytes_left(&s->g) == 0 && s->bit_index == 8) {

        if (*tp_index < FF_ARRAY_ELEMS(tile->tile_part) - 1) {

            s->g = tile->tile_part[++(*tp_index)].tpg;

        }

    }



    if (bytestream2_peek_be32(&s->g) == 0xFF910004)

        bytestream2_skip(&s->g, 6);



    if (!(ret = get_bits(s, 1))) {

        jpeg2000_flush(s);

        return 0;

    } else if (ret < 0)

        return ret;



    for (bandno = 0; bandno < rlevel->nbands; bandno++) {

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;



        if (band->coord[0][0] == band->coord[0][1] ||

            band->coord[1][0] == band->coord[1][1])

            continue;

        nb_code_blocks =  prec->nb_codeblocks_height *

                          prec->nb_codeblocks_width;

        for (cblkno = 0; cblkno < nb_code_blocks; cblkno++) {

            Jpeg2000Cblk *cblk = prec->cblk + cblkno;

            int incl, newpasses, llen;



            if (cblk->npasses)

                incl = get_bits(s, 1);

            else

                incl = tag_tree_decode(s, prec->cblkincl + cblkno, layno + 1) == layno;

            if (!incl)

                continue;

            else if (incl < 0)

                return incl;



            if (!cblk->npasses) {

                int v = expn[bandno] + numgbits - 1 -

                        tag_tree_decode(s, prec->zerobits + cblkno, 100);

                if (v < 0) {

                    av_log(s->avctx, AV_LOG_ERROR,

                           "nonzerobits %d invalid\n", v);

                    return AVERROR_INVALIDDATA;

                }

                cblk->nonzerobits = v;

            }

            if ((newpasses = getnpasses(s)) < 0)

                return newpasses;

            av_assert2(newpasses > 0);

            if (cblk->npasses + newpasses >= JPEG2000_MAX_PASSES) {

                avpriv_request_sample(s->avctx, "Too many passes\n");

                return AVERROR_PATCHWELCOME;

            }

            if ((llen = getlblockinc(s)) < 0)

                return llen;

            if (cblk->lblock + llen + av_log2(newpasses) > 16) {

                avpriv_request_sample(s->avctx,

                                      "Block with length beyond 16 bits\n");

                return AVERROR_PATCHWELCOME;

            }



            cblk->lblock += llen;



            cblk->nb_lengthinc = 0;

            cblk->nb_terminationsinc = 0;

            do {

                int newpasses1 = 0;



                while (newpasses1 < newpasses) {

                    newpasses1 ++;

                    if (needs_termination(codsty->cblk_style, cblk->npasses + newpasses1 - 1)) {

                        cblk->nb_terminationsinc ++;

                        break;

                    }

                }



                if ((ret = get_bits(s, av_log2(newpasses1) + cblk->lblock)) < 0)

                    return ret;

                if (ret > sizeof(cblk->data)) {

                    avpriv_request_sample(s->avctx,

                                        "Block with lengthinc greater than %"SIZE_SPECIFIER"",

                                        sizeof(cblk->data));

                    return AVERROR_PATCHWELCOME;

                }

                cblk->lengthinc[cblk->nb_lengthinc++] = ret;

                cblk->npasses  += newpasses1;

                newpasses -= newpasses1;

            } while(newpasses);

        }

    }

    jpeg2000_flush(s);



    if (codsty->csty & JPEG2000_CSTY_EPH) {

        if (bytestream2_peek_be16(&s->g) == JPEG2000_EPH)

            bytestream2_skip(&s->g, 2);

        else

            av_log(s->avctx, AV_LOG_ERROR, "EPH marker not found.\n");

    }



    for (bandno = 0; bandno < rlevel->nbands; bandno++) {

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;



        nb_code_blocks = prec->nb_codeblocks_height * prec->nb_codeblocks_width;

        for (cblkno = 0; cblkno < nb_code_blocks; cblkno++) {

            Jpeg2000Cblk *cblk = prec->cblk + cblkno;

            for (cwsno = 0; cwsno < cblk->nb_lengthinc; cwsno ++) {

                if (   bytestream2_get_bytes_left(&s->g) < cblk->lengthinc[cwsno]

                    || sizeof(cblk->data) < cblk->length + cblk->lengthinc[cwsno] + 4

                ) {

                    av_log(s->avctx, AV_LOG_ERROR,

                        "Block length %"PRIu16" or lengthinc %d is too large, left %d\n",

                        cblk->length, cblk->lengthinc[cwsno], bytestream2_get_bytes_left(&s->g));

                    return AVERROR_INVALIDDATA;

                }



                bytestream2_get_bufferu(&s->g, cblk->data + cblk->length, cblk->lengthinc[cwsno]);

                cblk->length   += cblk->lengthinc[cwsno];

                cblk->lengthinc[cwsno] = 0;

                if (cblk->nb_terminationsinc) {

                    cblk->nb_terminationsinc--;

                    cblk->nb_terminations++;

                    cblk->data[cblk->length++] = 0xFF;

                    cblk->data[cblk->length++] = 0xFF;

                    cblk->data_start[cblk->nb_terminations] = cblk->length;

                }

            }

        }

    }

    return 0;

}

static int jpeg2000_decode_packet(Jpeg2000DecoderContext *s,

                                  Jpeg2000CodingStyle *codsty,

                                  Jpeg2000ResLevel *rlevel, int precno,

                                  int layno, uint8_t *expn, int numgbits)

{

    int bandno, cblkno, ret, nb_code_blocks;



    if (!(ret = get_bits(s, 1))) {

        jpeg2000_flush(s);

        return 0;

    } else if (ret < 0)

        return ret;



    for (bandno = 0; bandno < rlevel->nbands; bandno++) {

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;



        if (band->coord[0][0] == band->coord[0][1] ||

            band->coord[1][0] == band->coord[1][1])

            continue;

        prec->yi0 = 0;

        prec->xi0 = 0;

        nb_code_blocks =  prec->nb_codeblocks_height *

                          prec->nb_codeblocks_width;

        for (cblkno = 0; cblkno < nb_code_blocks; cblkno++) {

            Jpeg2000Cblk *cblk = prec->cblk + cblkno;

            int incl, newpasses, llen;



            if (cblk->npasses)

                incl = get_bits(s, 1);

            else

                incl = tag_tree_decode(s, prec->cblkincl + cblkno, layno + 1) == layno;

            if (!incl)

                continue;

            else if (incl < 0)

                return incl;



            if (!cblk->npasses)

                cblk->nonzerobits = expn[bandno] + numgbits - 1 -

                                    tag_tree_decode(s, prec->zerobits + cblkno,

                                                    100);

            if ((newpasses = getnpasses(s)) < 0)

                return newpasses;

            if ((llen = getlblockinc(s)) < 0)

                return llen;

            cblk->lblock += llen;

            if ((ret = get_bits(s, av_log2(newpasses) + cblk->lblock)) < 0)

                return ret;

            cblk->lengthinc = ret;

            cblk->npasses  += newpasses;

        }

    }

    jpeg2000_flush(s);



    if (codsty->csty & JPEG2000_CSTY_EPH) {

        if (bytestream2_peek_be16(&s->g) == JPEG2000_EPH)

            bytestream2_skip(&s->g, 2);

        else

            av_log(s->avctx, AV_LOG_ERROR, "EPH marker not found.\n");

    }



    for (bandno = 0; bandno < rlevel->nbands; bandno++) {

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;



        nb_code_blocks = prec->nb_codeblocks_height * prec->nb_codeblocks_width;

        for (cblkno = 0; cblkno < nb_code_blocks; cblkno++) {

            Jpeg2000Cblk *cblk = prec->cblk + cblkno;

            if (bytestream2_get_bytes_left(&s->g) < cblk->lengthinc)

                return AVERROR(EINVAL);

            /* Code-block data can be empty. In that case initialize data

             * with 0xFFFF. */

            if (cblk->lengthinc > 0) {

                bytestream2_get_bufferu(&s->g, cblk->data, cblk->lengthinc);

            } else {

                cblk->data[0] = 0xFF;

                cblk->data[1] = 0xFF;

            }

            cblk->length   += cblk->lengthinc;

            cblk->lengthinc = 0;

        }

    }

    return 0;

}

static int jpeg2000_read_main_headers(Jpeg2000DecoderContext *s)

{

    Jpeg2000CodingStyle *codsty = s->codsty;

    Jpeg2000QuantStyle *qntsty  = s->qntsty;

    uint8_t *properties         = s->properties;



    for (;;) {

        int len, ret = 0;

        uint16_t marker;

        int oldpos;



        if (bytestream2_get_bytes_left(&s->g) < 2) {

            av_log(s->avctx, AV_LOG_ERROR, "Missing EOC\n");

            break;

        }



        marker = bytestream2_get_be16u(&s->g);

        oldpos = bytestream2_tell(&s->g);



        if (marker == JPEG2000_SOD) {

            Jpeg2000Tile *tile = s->tile + s->curtileno;

            Jpeg2000TilePart *tp = tile->tile_part + tile->tp_idx;



            bytestream2_init(&tp->tpg, s->g.buffer, tp->tp_end - s->g.buffer);

            bytestream2_skip(&s->g, tp->tp_end - s->g.buffer);



            continue;

        }

        if (marker == JPEG2000_EOC)

            break;



        if (bytestream2_get_bytes_left(&s->g) < 2)

            return AVERROR(EINVAL);

        len = bytestream2_get_be16u(&s->g);

        switch (marker) {

        case JPEG2000_SIZ:

            ret = get_siz(s);

            if (!s->tile)

                s->numXtiles = s->numYtiles = 0;

            break;

        case JPEG2000_COC:

            ret = get_coc(s, codsty, properties);

            break;

        case JPEG2000_COD:

            ret = get_cod(s, codsty, properties);

            break;

        case JPEG2000_QCC:

            ret = get_qcc(s, len, qntsty, properties);

            break;

        case JPEG2000_QCD:

            ret = get_qcd(s, len, qntsty, properties);

            break;

        case JPEG2000_SOT:

            if (!(ret = get_sot(s, len))) {

                av_assert1(s->curtileno >= 0);

                codsty = s->tile[s->curtileno].codsty;

                qntsty = s->tile[s->curtileno].qntsty;

                properties = s->tile[s->curtileno].properties;

            }

            break;

        case JPEG2000_COM:

            // the comment is ignored

            bytestream2_skip(&s->g, len - 2);

            break;

        case JPEG2000_TLM:

            // Tile-part lengths

            ret = get_tlm(s, len);

            break;

        default:

            av_log(s->avctx, AV_LOG_ERROR,

                   "unsupported marker 0x%.4X at pos 0x%X\n",

                   marker, bytestream2_tell(&s->g) - 4);

            bytestream2_skip(&s->g, len - 2);

            break;

        }

        if (bytestream2_tell(&s->g) - oldpos != len || ret) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "error during processing marker segment %.4x\n", marker);

            return ret ? ret : -1;

        }

    }

    return 0;

}

static void adb_keyboard_event(DeviceState *dev, QemuConsole *src,

                               InputEvent *evt)

{

    KBDState *s = (KBDState *)dev;

    int qcode, keycode;



    qcode = qemu_input_key_value_to_qcode(evt->u.key.data->key);

    if (qcode >= ARRAY_SIZE(qcode_to_adb_keycode)) {

        return;

    }

    /* FIXME: take handler into account when translating qcode */

    keycode = qcode_to_adb_keycode[qcode];

    if (keycode == NO_KEY) {  /* We don't want to send this to the guest */

        ADB_DPRINTF("Ignoring NO_KEY\n");

        return;

    }

    if (evt->u.key.data->down == false) { /* if key release event */

        keycode = keycode | 0x80;   /* create keyboard break code */

    }



    adb_kbd_put_keycode(s, keycode);

}

static void *qemu_tcg_rr_cpu_thread_fn(void *arg)

{

    CPUState *cpu = arg;



    rcu_register_thread();




    qemu_thread_get_self(cpu->thread);



    CPU_FOREACH(cpu) {

        cpu->thread_id = qemu_get_thread_id();

        cpu->created = true;

        cpu->can_do_io = 1;

    }

    qemu_cond_signal(&qemu_cpu_cond);



    /* wait for initial kick-off after machine start */

    while (first_cpu->stopped) {

        qemu_cond_wait(first_cpu->halt_cond, &qemu_global_mutex);



        /* process any pending work */

        CPU_FOREACH(cpu) {

            current_cpu = cpu;

            qemu_wait_io_event_common(cpu);

        }

    }



    start_tcg_kick_timer();



    cpu = first_cpu;



    /* process any pending work */

    cpu->exit_request = 1;



    while (1) {

        /* Account partial waits to QEMU_CLOCK_VIRTUAL.  */

        qemu_account_warp_timer();



        if (!cpu) {

            cpu = first_cpu;

        }



        while (cpu && !cpu->queued_work_first && !cpu->exit_request) {



            atomic_mb_set(&tcg_current_rr_cpu, cpu);

            current_cpu = cpu;



            qemu_clock_enable(QEMU_CLOCK_VIRTUAL,

                              (cpu->singlestep_enabled & SSTEP_NOTIMER) == 0);



            if (cpu_can_run(cpu)) {

                int r;

                r = tcg_cpu_exec(cpu);

                if (r == EXCP_DEBUG) {

                    cpu_handle_guest_debug(cpu);







                }

            } else if (cpu->stop) {

                if (cpu->unplug) {

                    cpu = CPU_NEXT(cpu);

                }


            }



            cpu = CPU_NEXT(cpu);

        } /* while (cpu && !cpu->exit_request).. */



        /* Does not need atomic_mb_set because a spurious wakeup is okay.  */

        atomic_set(&tcg_current_rr_cpu, NULL);



        if (cpu && cpu->exit_request) {

            atomic_mb_set(&cpu->exit_request, 0);

        }



        handle_icount_deadline();



        qemu_tcg_wait_io_event(cpu ? cpu : QTAILQ_FIRST(&cpus));

        deal_with_unplugged_cpus();

    }



    return NULL;

}

static void curses_calc_pad(void)

{

    if (is_graphic_console()) {

        width = gwidth;

        height = gheight;

    } else {

        width = COLS;

        height = LINES;

    }



    if (screenpad)

        delwin(screenpad);



    clear();

    refresh();



    screenpad = newpad(height, width);



    if (width > COLS) {

        px = (width - COLS) / 2;

        sminx = 0;

        smaxx = COLS;

    } else {

        px = 0;

        sminx = (COLS - width) / 2;

        smaxx = sminx + width;

    }



    if (height > LINES) {

        py = (height - LINES) / 2;

        sminy = 0;

        smaxy = LINES;

    } else {

        py = 0;

        sminy = (LINES - height) / 2;

        smaxy = sminy + height;

    }

}

static void sdl_refresh(DisplayState *ds)

{

    SDL_Event ev1, *ev = &ev1;

    int mod_state;

    int buttonstate = SDL_GetMouseState(NULL, NULL);



    if (last_vm_running != vm_running) {

        last_vm_running = vm_running;

        sdl_update_caption();

    }



    vga_hw_update();

    SDL_EnableUNICODE(!is_graphic_console());



    while (SDL_PollEvent(ev)) {

        switch (ev->type) {

        case SDL_VIDEOEXPOSE:

            sdl_update(ds, 0, 0, screen->w, screen->h);

            break;

        case SDL_KEYDOWN:

        case SDL_KEYUP:

            if (ev->type == SDL_KEYDOWN) {

                if (!alt_grab) {

                    mod_state = (SDL_GetModState() & gui_grab_code) ==

                                gui_grab_code;

                } else {

                    mod_state = (SDL_GetModState() & (gui_grab_code | KMOD_LSHIFT)) ==

                                (gui_grab_code | KMOD_LSHIFT);

                }

                gui_key_modifier_pressed = mod_state;

                if (gui_key_modifier_pressed) {

                    int keycode;

                    keycode = sdl_keyevent_to_keycode(&ev->key);

                    switch(keycode) {

                    case 0x21: /* 'f' key on US keyboard */

                        toggle_full_screen(ds);

                        gui_keysym = 1;

                        break;

                    case 0x02 ... 0x0a: /* '1' to '9' keys */

                        /* Reset the modifiers sent to the current console */

                        reset_keys();

                        console_select(keycode - 0x02);

                        if (!is_graphic_console()) {

                            /* display grab if going to a text console */

                            if (gui_grab)

                                sdl_grab_end();

                        }

                        gui_keysym = 1;

                        break;

                    default:

                        break;

                    }

                } else if (!is_graphic_console()) {

                    int keysym;

                    keysym = 0;

                    if (ev->key.keysym.mod & (KMOD_LCTRL | KMOD_RCTRL)) {

                        switch(ev->key.keysym.sym) {

                        case SDLK_UP: keysym = QEMU_KEY_CTRL_UP; break;

                        case SDLK_DOWN: keysym = QEMU_KEY_CTRL_DOWN; break;

                        case SDLK_LEFT: keysym = QEMU_KEY_CTRL_LEFT; break;

                        case SDLK_RIGHT: keysym = QEMU_KEY_CTRL_RIGHT; break;

                        case SDLK_HOME: keysym = QEMU_KEY_CTRL_HOME; break;

                        case SDLK_END: keysym = QEMU_KEY_CTRL_END; break;

                        case SDLK_PAGEUP: keysym = QEMU_KEY_CTRL_PAGEUP; break;

                        case SDLK_PAGEDOWN: keysym = QEMU_KEY_CTRL_PAGEDOWN; break;

                        default: break;

                        }

                    } else {

                        switch(ev->key.keysym.sym) {

                        case SDLK_UP: keysym = QEMU_KEY_UP; break;

                        case SDLK_DOWN: keysym = QEMU_KEY_DOWN; break;

                        case SDLK_LEFT: keysym = QEMU_KEY_LEFT; break;

                        case SDLK_RIGHT: keysym = QEMU_KEY_RIGHT; break;

                        case SDLK_HOME: keysym = QEMU_KEY_HOME; break;

                        case SDLK_END: keysym = QEMU_KEY_END; break;

                        case SDLK_PAGEUP: keysym = QEMU_KEY_PAGEUP; break;

                        case SDLK_PAGEDOWN: keysym = QEMU_KEY_PAGEDOWN; break;

                        case SDLK_BACKSPACE: keysym = QEMU_KEY_BACKSPACE; break;

                        case SDLK_DELETE: keysym = QEMU_KEY_DELETE; break;

                        default: break;

                        }

                    }

                    if (keysym) {

                        kbd_put_keysym(keysym);

                    } else if (ev->key.keysym.unicode != 0) {

                        kbd_put_keysym(ev->key.keysym.unicode);

                    }

                }

            } else if (ev->type == SDL_KEYUP) {

                if (!alt_grab) {

                    mod_state = (ev->key.keysym.mod & gui_grab_code);

                } else {

                    mod_state = (ev->key.keysym.mod &

                                 (gui_grab_code | KMOD_LSHIFT));

                }

                if (!mod_state) {

                    if (gui_key_modifier_pressed) {

                        gui_key_modifier_pressed = 0;

                        if (gui_keysym == 0) {

                            /* exit/enter grab if pressing Ctrl-Alt */

                            if (!gui_grab) {

                                /* if the application is not active,

                                   do not try to enter grab state. It

                                   prevents

                                   'SDL_WM_GrabInput(SDL_GRAB_ON)'

                                   from blocking all the application

                                   (SDL bug). */

                                if (SDL_GetAppState() & SDL_APPACTIVE)

                                    sdl_grab_start();

                            } else {

                                sdl_grab_end();

                            }

                            /* SDL does not send back all the

                               modifiers key, so we must correct it */

                            reset_keys();

                            break;

                        }

                        gui_keysym = 0;

                    }

                }

            }

            if (is_graphic_console() && !gui_keysym)

                sdl_process_key(&ev->key);

            break;

        case SDL_QUIT:

            if (!no_quit) {

                qemu_system_shutdown_request();

                vm_start();	/* In case we're paused */

            }

            break;

        case SDL_MOUSEMOTION:

            if (gui_grab || kbd_mouse_is_absolute() ||

                absolute_enabled) {

                sdl_send_mouse_event(ev->motion.xrel, ev->motion.yrel, 0,

                       ev->motion.x, ev->motion.y, ev->motion.state);

            }

            break;

        case SDL_MOUSEBUTTONDOWN:

        case SDL_MOUSEBUTTONUP:

            {

                SDL_MouseButtonEvent *bev = &ev->button;

                if (!gui_grab && !kbd_mouse_is_absolute()) {

                    if (ev->type == SDL_MOUSEBUTTONDOWN &&

                        (bev->button == SDL_BUTTON_LEFT)) {

                        /* start grabbing all events */

                        sdl_grab_start();

                    }

                } else {

                    int dz;

                    dz = 0;

                    if (ev->type == SDL_MOUSEBUTTONDOWN) {

                        buttonstate |= SDL_BUTTON(bev->button);

                    } else {

                        buttonstate &= ~SDL_BUTTON(bev->button);

                    }

#ifdef SDL_BUTTON_WHEELUP

                    if (bev->button == SDL_BUTTON_WHEELUP && ev->type == SDL_MOUSEBUTTONDOWN) {

                        dz = -1;

                    } else if (bev->button == SDL_BUTTON_WHEELDOWN && ev->type == SDL_MOUSEBUTTONDOWN) {

                        dz = 1;

                    }

#endif

                    sdl_send_mouse_event(0, 0, dz, bev->x, bev->y, buttonstate);

                }

            }

            break;

        case SDL_ACTIVEEVENT:

            if (gui_grab && ev->active.state == SDL_APPINPUTFOCUS &&

                !ev->active.gain && !gui_fullscreen_initial_grab) {

                sdl_grab_end();

            }

            if (ev->active.state & SDL_APPACTIVE) {

                if (ev->active.gain) {

                    /* Back to default interval */

                    ds->gui_timer_interval = 0;

                } else {

                    /* Sleeping interval */

                    ds->gui_timer_interval = 500;

                }

            }

            break;

        default:

            break;

        }

    }

}

static int read_ts(const char *s, int64_t *start, int *duration)

{

    int64_t end;

    int hh1, mm1, ss1, ms1;

    int hh2, mm2, ss2, ms2;



    if (sscanf(s, "%u:%u:%u.%u,%u:%u:%u.%u",

               &hh1, &mm1, &ss1, &ms1, &hh2, &mm2, &ss2, &ms2) == 8) {

        end    = (hh2*3600 + mm2*60 + ss2) * 100 + ms2;

        *start = (hh1*3600 + mm1*60 + ss1) * 100 + ms1;

        *duration = end - *start;

        return 0;

    }

    return -1;

}

static int64_t get_pts(const char *buf, int *duration)

{

    int i, hour, min, sec, hsec;

    int he, me, se, mse;



    for (i=0; i<2; i++) {

        int64_t start, end;

        if (sscanf(buf, "%d:%2d:%2d%*1[,.]%3d --> %d:%2d:%2d%*1[,.]%3d",

                   &hour, &min, &sec, &hsec, &he, &me, &se, &mse) == 8) {

            min += 60*hour;

            sec += 60*min;

            start = sec*1000+hsec;

            me += 60*he;

            se += 60*me;

            end = se*1000+mse;

            *duration = end - start;

            return start;

        }

        buf += strcspn(buf, "\n") + 1;

    }

    return AV_NOPTS_VALUE;

}

static char *ts_value_string (char *buf, int buf_size, int64_t ts)

{

    if (ts == AV_NOPTS_VALUE) {

        snprintf(buf, buf_size, "N/A");

    } else {

        snprintf(buf, buf_size, "%"PRId64, ts);

    }



    return buf;

}

static int64_t get_pts(const char **buf, int *duration,

                       int32_t *x1, int32_t *y1, int32_t *x2, int32_t *y2)

{

    int i;



    for (i=0; i<2; i++) {

        int hh1, mm1, ss1, ms1;

        int hh2, mm2, ss2, ms2;

        if (sscanf(*buf, "%d:%2d:%2d%*1[,.]%3d --> %d:%2d:%2d%*1[,.]%3d"

                   "%*[ ]X1:%u X2:%u Y1:%u Y2:%u",

                   &hh1, &mm1, &ss1, &ms1,

                   &hh2, &mm2, &ss2, &ms2,

                   x1, x2, y1, y2) >= 8) {

            int64_t start = (hh1*3600LL + mm1*60LL + ss1) * 1000LL + ms1;

            int64_t end   = (hh2*3600LL + mm2*60LL + ss2) * 1000LL + ms2;

            *duration = end - start;

            *buf += strcspn(*buf, "\n") + 1;

            return start;

        }

        *buf += strcspn(*buf, "\n") + 1;

    }

    return AV_NOPTS_VALUE;

}

