static int au_write_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    AVCodecContext *enc = s->streams[0]->codec;



    if (!enc->codec_tag)

        return AVERROR(EINVAL);



    ffio_wfourcc(pb, ".snd");                   /* magic number */

    avio_wb32(pb, AU_HEADER_SIZE);              /* header size */

    avio_wb32(pb, AU_UNKNOWN_SIZE);             /* data size */

    avio_wb32(pb, enc->codec_tag);              /* codec ID */

    avio_wb32(pb, enc->sample_rate);

    avio_wb32(pb, enc->channels);

    avio_wb64(pb, 0); /* annotation field */

    avio_flush(pb);



    return 0;

}

static int mov_write_avid_tag(AVIOContext *pb, MOVTrack *track)

{

    int i;

    avio_wb32(pb, 24); /* size */

    ffio_wfourcc(pb, "ACLR");

    ffio_wfourcc(pb, "ACLR");

    ffio_wfourcc(pb, "0001");

    if (track->enc->color_range == AVCOL_RANGE_MPEG || /* Legal range (16-235) */

        track->enc->color_range == AVCOL_RANGE_UNSPECIFIED) {

        avio_wb32(pb, 1); /* Corresponds to 709 in official encoder */

    } else { /* Full range (0-255) */

        avio_wb32(pb, 2); /* Corresponds to RGB in official encoder */

    }

    avio_wb32(pb, 0); /* unknown */



    avio_wb32(pb, 24); /* size */

    ffio_wfourcc(pb, "APRG");

    ffio_wfourcc(pb, "APRG");

    ffio_wfourcc(pb, "0001");

    avio_wb32(pb, 1); /* unknown */

    avio_wb32(pb, 0); /* unknown */



    avio_wb32(pb, 120); /* size */

    ffio_wfourcc(pb, "ARES");

    ffio_wfourcc(pb, "ARES");

    ffio_wfourcc(pb, "0001");

    avio_wb32(pb, AV_RB32(track->vos_data + 0x28)); /* dnxhd cid, some id ? */

    avio_wb32(pb, track->enc->width);

    /* values below are based on samples created with quicktime and avid codecs */

    if (track->vos_data[5] & 2) { // interlaced

        avio_wb32(pb, track->enc->height / 2);

        avio_wb32(pb, 2); /* unknown */

        avio_wb32(pb, 0); /* unknown */

        avio_wb32(pb, 4); /* unknown */

    } else {

        avio_wb32(pb, track->enc->height);

        avio_wb32(pb, 1); /* unknown */

        avio_wb32(pb, 0); /* unknown */

        if (track->enc->height == 1080)

            avio_wb32(pb, 5); /* unknown */

        else

            avio_wb32(pb, 6); /* unknown */

    }

    /* padding */

    for (i = 0; i < 10; i++)

        avio_wb64(pb, 0);



    /* extra padding for stsd needed */

    avio_wb32(pb, 0);

    return 0;

}

static void mov_write_uuidprof_tag(AVIOContext *pb, AVFormatContext *s)

{

    AVStream       *video_st    = s->streams[0];

    AVCodecParameters *video_par = s->streams[0]->codecpar;

    AVCodecParameters *audio_par = s->streams[1]->codecpar;

    int audio_rate = audio_par->sample_rate;

    int64_t frame_rate = (video_st->avg_frame_rate.num * 0x10000LL) / video_st->avg_frame_rate.den;

    int audio_kbitrate = audio_par->bit_rate / 1000;

    int video_kbitrate = FFMIN(video_par->bit_rate / 1000, 800 - audio_kbitrate);



    avio_wb32(pb, 0x94); /* size */

    ffio_wfourcc(pb, "uuid");

    ffio_wfourcc(pb, "PROF");



    avio_wb32(pb, 0x21d24fce); /* 96 bit UUID */

    avio_wb32(pb, 0xbb88695c);

    avio_wb32(pb, 0xfac9c740);



    avio_wb32(pb, 0x0);  /* ? */

    avio_wb32(pb, 0x3);  /* 3 sections ? */



    avio_wb32(pb, 0x14); /* size */

    ffio_wfourcc(pb, "FPRF");

    avio_wb32(pb, 0x0);  /* ? */

    avio_wb32(pb, 0x0);  /* ? */

    avio_wb32(pb, 0x0);  /* ? */



    avio_wb32(pb, 0x2c);  /* size */

    ffio_wfourcc(pb, "APRF"); /* audio */

    avio_wb32(pb, 0x0);

    avio_wb32(pb, 0x2);   /* TrackID */

    ffio_wfourcc(pb, "mp4a");

    avio_wb32(pb, 0x20f);

    avio_wb32(pb, 0x0);

    avio_wb32(pb, audio_kbitrate);

    avio_wb32(pb, audio_kbitrate);

    avio_wb32(pb, audio_rate);

    avio_wb32(pb, audio_par->channels);



    avio_wb32(pb, 0x34);  /* size */

    ffio_wfourcc(pb, "VPRF");   /* video */

    avio_wb32(pb, 0x0);

    avio_wb32(pb, 0x1);    /* TrackID */

    if (video_par->codec_id == AV_CODEC_ID_H264) {

        ffio_wfourcc(pb, "avc1");

        avio_wb16(pb, 0x014D);

        avio_wb16(pb, 0x0015);

    } else {

        ffio_wfourcc(pb, "mp4v");

        avio_wb16(pb, 0x0000);

        avio_wb16(pb, 0x0103);

    }

    avio_wb32(pb, 0x0);

    avio_wb32(pb, video_kbitrate);

    avio_wb32(pb, video_kbitrate);

    avio_wb32(pb, frame_rate);

    avio_wb32(pb, frame_rate);

    avio_wb16(pb, video_par->width);

    avio_wb16(pb, video_par->height);

    avio_wb32(pb, 0x010001); /* ? */

}

static int mov_write_tapt_tag(AVIOContext *pb, MOVTrack *track)

{

    int32_t width = av_rescale(track->enc->sample_aspect_ratio.num, track->enc->width,

                               track->enc->sample_aspect_ratio.den);



    int64_t pos = avio_tell(pb);



    avio_wb32(pb, 0); /* size */

    ffio_wfourcc(pb, "tapt");



    avio_wb32(pb, 20);

    ffio_wfourcc(pb, "clef");

    avio_wb32(pb, 0);

    avio_wb32(pb, width << 16);

    avio_wb32(pb, track->enc->height << 16);



    avio_wb32(pb, 20);

    ffio_wfourcc(pb, "enof");

    avio_wb32(pb, 0);

    avio_wb32(pb, track->enc->width << 16);

    avio_wb32(pb, track->enc->height << 16);



    return updateSize(pb, pos);

};

static int local_remove(FsContext *ctx, const char *path)

{

    int err;

    struct stat stbuf;

    char *buffer;



    if (ctx->export_flags & V9FS_SM_MAPPED_FILE) {

        buffer = rpath(ctx, path);

        err =  lstat(buffer, &stbuf);

        g_free(buffer);

        if (err) {

            goto err_out;

        }

        /*

         * If directory remove .virtfs_metadata contained in the

         * directory

         */

        if (S_ISDIR(stbuf.st_mode)) {

            buffer = g_strdup_printf("%s/%s/%s", ctx->fs_root,

                                     path, VIRTFS_META_DIR);

            err = remove(buffer);

            g_free(buffer);

            if (err < 0 && errno != ENOENT) {

                /*

                 * We didn't had the .virtfs_metadata file. May be file created

                 * in non-mapped mode ?. Ignore ENOENT.

                 */

                goto err_out;

            }

        }

        /*

         * Now remove the name from parent directory

         * .virtfs_metadata directory

         */

        buffer = local_mapped_attr_path(ctx, path);

        err = remove(buffer);

        g_free(buffer);

        if (err < 0 && errno != ENOENT) {

            /*

             * We didn't had the .virtfs_metadata file. May be file created

             * in non-mapped mode ?. Ignore ENOENT.

             */

            goto err_out;

        }

    }



    buffer = rpath(ctx, path);

    err = remove(buffer);

    g_free(buffer);

err_out:

    return err;

}

