static void x86_cpuid_set_apic_id(Object *obj, Visitor *v, const char *name,

                                  void *opaque, Error **errp)

{

    X86CPU *cpu = X86_CPU(obj);

    DeviceState *dev = DEVICE(obj);

    const int64_t min = 0;

    const int64_t max = UINT32_MAX;

    Error *error = NULL;

    int64_t value;



    if (dev->realized) {

        error_setg(errp, "Attempt to set property '%s' on '%s' after "

                   "it was realized", name, object_get_typename(obj));

        return;

    }



    visit_type_int(v, name, &value, &error);

    if (error) {

        error_propagate(errp, error);

        return;

    }

    if (value < min || value > max) {

        error_setg(errp, "Property %s.%s doesn't take value %" PRId64

                   " (minimum: %" PRId64 ", maximum: %" PRId64 ")" ,

                   object_get_typename(obj), name, value, min, max);

        return;

    }



    if ((value != cpu->apic_id) && cpu_exists(value)) {

        error_setg(errp, "CPU with APIC ID %" PRIi64 " exists", value);

        return;

    }

    cpu->apic_id = value;

}

static void set_blocksize(Object *obj, Visitor *v, void *opaque,

                          const char *name, Error **errp)

{

    DeviceState *dev = DEVICE(obj);

    Property *prop = opaque;

    uint16_t value, *ptr = qdev_get_prop_ptr(dev, prop);

    Error *local_err = NULL;

    const int64_t min = 512;

    const int64_t max = 32768;



    if (dev->realized) {

        qdev_prop_set_after_realize(dev, name, errp);

        return;

    }



    visit_type_uint16(v, &value, name, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }

    if (value < min || value > max) {

        error_set(errp, QERR_PROPERTY_VALUE_OUT_OF_RANGE,

                  dev->id?:"", name, (int64_t)value, min, max);

        return;

    }



    /* We rely on power-of-2 blocksizes for bitmasks */

    if ((value & (value - 1)) != 0) {

        error_setg(errp,

                  "Property %s.%s doesn't take value '%" PRId64 "', it's not a power of 2",

                  dev->id ?: "", name, (int64_t)value);

        return;

    }



    *ptr = value;

}

static int vdi_create(const char *filename, QemuOpts *opts, Error **errp)

{

    int ret = 0;

    uint64_t bytes = 0;

    uint32_t blocks;

    size_t block_size = DEFAULT_CLUSTER_SIZE;

    uint32_t image_type = VDI_TYPE_DYNAMIC;

    VdiHeader header;

    size_t i;

    size_t bmap_size;

    int64_t offset = 0;

    Error *local_err = NULL;

    BlockDriverState *bs = NULL;

    uint32_t *bmap = NULL;



    logout("\n");



    /* Read out options. */

    bytes = qemu_opt_get_size_del(opts, BLOCK_OPT_SIZE, 0);

#if defined(CONFIG_VDI_BLOCK_SIZE)

    /* TODO: Additional checks (SECTOR_SIZE * 2^n, ...). */

    block_size = qemu_opt_get_size_del(opts,

                                       BLOCK_OPT_CLUSTER_SIZE,

                                       DEFAULT_CLUSTER_SIZE);

#endif

#if defined(CONFIG_VDI_STATIC_IMAGE)

    if (qemu_opt_get_bool_del(opts, BLOCK_OPT_STATIC, false)) {

        image_type = VDI_TYPE_STATIC;

    }

#endif



    if (bytes > VDI_DISK_SIZE_MAX) {

        ret = -ENOTSUP;

        error_setg(errp, "Unsupported VDI image size (size is 0x%" PRIx64

                          ", max supported is 0x%" PRIx64 ")",

                          bytes, VDI_DISK_SIZE_MAX);

        goto exit;

    }



    ret = bdrv_create_file(filename, opts, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }

    ret = bdrv_open(&bs, filename, NULL, NULL, BDRV_O_RDWR | BDRV_O_PROTOCOL,

                    NULL, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    /* We need enough blocks to store the given disk size,

       so always round up. */

    blocks = (bytes + block_size - 1) / block_size;



    bmap_size = blocks * sizeof(uint32_t);

    bmap_size = ((bmap_size + SECTOR_SIZE - 1) & ~(SECTOR_SIZE -1));



    memset(&header, 0, sizeof(header));

    pstrcpy(header.text, sizeof(header.text), VDI_TEXT);

    header.signature = VDI_SIGNATURE;

    header.version = VDI_VERSION_1_1;

    header.header_size = 0x180;

    header.image_type = image_type;

    header.offset_bmap = 0x200;

    header.offset_data = 0x200 + bmap_size;

    header.sector_size = SECTOR_SIZE;

    header.disk_size = bytes;

    header.block_size = block_size;

    header.blocks_in_image = blocks;

    if (image_type == VDI_TYPE_STATIC) {

        header.blocks_allocated = blocks;

    }

    uuid_generate(header.uuid_image);

    uuid_generate(header.uuid_last_snap);

    /* There is no need to set header.uuid_link or header.uuid_parent here. */

#if defined(CONFIG_VDI_DEBUG)

    vdi_header_print(&header);

#endif

    vdi_header_to_le(&header);

    ret = bdrv_pwrite_sync(bs, offset, &header, sizeof(header));

    if (ret < 0) {

        error_setg(errp, "Error writing header to %s", filename);

        goto exit;

    }

    offset += sizeof(header);



    if (bmap_size > 0) {

        bmap = g_malloc0(bmap_size);

        for (i = 0; i < blocks; i++) {

            if (image_type == VDI_TYPE_STATIC) {

                bmap[i] = i;

            } else {

                bmap[i] = VDI_UNALLOCATED;

            }

        }

        ret = bdrv_pwrite_sync(bs, offset, bmap, bmap_size);

        if (ret < 0) {

            error_setg(errp, "Error writing bmap to %s", filename);

            goto exit;

        }

        offset += bmap_size;

    }



    if (image_type == VDI_TYPE_STATIC) {

        ret = bdrv_truncate(bs, offset + blocks * block_size);

        if (ret < 0) {

            error_setg(errp, "Failed to statically allocate %s", filename);

            goto exit;

        }

    }



exit:

    bdrv_unref(bs);

    g_free(bmap);

    return ret;

}

static int vmdk_create_extent(const char *filename, int64_t filesize,

                              bool flat, bool compress, bool zeroed_grain,

                              Error **errp)

{

    int ret, i;

    BlockDriverState *bs = NULL;

    VMDK4Header header;

    Error *local_err;

    uint32_t tmp, magic, grains, gd_sectors, gt_size, gt_count;

    uint32_t *gd_buf = NULL;

    int gd_buf_size;



    ret = bdrv_create_file(filename, NULL, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    ret = bdrv_file_open(&bs, filename, NULL, NULL, BDRV_O_RDWR, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    if (flat) {

        ret = bdrv_truncate(bs, filesize);

        if (ret < 0) {

            error_setg(errp, "Could not truncate file");

        }

        goto exit;

    }

    magic = cpu_to_be32(VMDK4_MAGIC);

    memset(&header, 0, sizeof(header));

    header.version = zeroed_grain ? 2 : 1;

    header.flags = VMDK4_FLAG_RGD | VMDK4_FLAG_NL_DETECT

                   | (compress ? VMDK4_FLAG_COMPRESS | VMDK4_FLAG_MARKER : 0)

                   | (zeroed_grain ? VMDK4_FLAG_ZERO_GRAIN : 0);

    header.compressAlgorithm = compress ? VMDK4_COMPRESSION_DEFLATE : 0;

    header.capacity = filesize / BDRV_SECTOR_SIZE;

    header.granularity = 128;

    header.num_gtes_per_gt = BDRV_SECTOR_SIZE;



    grains = DIV_ROUND_UP(filesize / BDRV_SECTOR_SIZE, header.granularity);

    gt_size = DIV_ROUND_UP(header.num_gtes_per_gt * sizeof(uint32_t),

                           BDRV_SECTOR_SIZE);

    gt_count = DIV_ROUND_UP(grains, header.num_gtes_per_gt);

    gd_sectors = DIV_ROUND_UP(gt_count * sizeof(uint32_t), BDRV_SECTOR_SIZE);



    header.desc_offset = 1;

    header.desc_size = 20;

    header.rgd_offset = header.desc_offset + header.desc_size;

    header.gd_offset = header.rgd_offset + gd_sectors + (gt_size * gt_count);

    header.grain_offset =

        ROUND_UP(header.gd_offset + gd_sectors + (gt_size * gt_count),

                 header.granularity);

    /* swap endianness for all header fields */

    header.version = cpu_to_le32(header.version);

    header.flags = cpu_to_le32(header.flags);

    header.capacity = cpu_to_le64(header.capacity);

    header.granularity = cpu_to_le64(header.granularity);

    header.num_gtes_per_gt = cpu_to_le32(header.num_gtes_per_gt);

    header.desc_offset = cpu_to_le64(header.desc_offset);

    header.desc_size = cpu_to_le64(header.desc_size);

    header.rgd_offset = cpu_to_le64(header.rgd_offset);

    header.gd_offset = cpu_to_le64(header.gd_offset);

    header.grain_offset = cpu_to_le64(header.grain_offset);

    header.compressAlgorithm = cpu_to_le16(header.compressAlgorithm);



    header.check_bytes[0] = 0xa;

    header.check_bytes[1] = 0x20;

    header.check_bytes[2] = 0xd;

    header.check_bytes[3] = 0xa;



    /* write all the data */

    ret = bdrv_pwrite(bs, 0, &magic, sizeof(magic));

    if (ret < 0) {

        error_set(errp, QERR_IO_ERROR);

        goto exit;

    }

    ret = bdrv_pwrite(bs, sizeof(magic), &header, sizeof(header));

    if (ret < 0) {

        error_set(errp, QERR_IO_ERROR);

        goto exit;

    }



    ret = bdrv_truncate(bs, le64_to_cpu(header.grain_offset) << 9);

    if (ret < 0) {

        error_setg(errp, "Could not truncate file");

        goto exit;

    }



    /* write grain directory */

    gd_buf_size = gd_sectors * BDRV_SECTOR_SIZE;

    gd_buf = g_malloc0(gd_buf_size);

    for (i = 0, tmp = le64_to_cpu(header.rgd_offset) + gd_sectors;

         i < gt_count; i++, tmp += gt_size) {

        gd_buf[i] = cpu_to_le32(tmp);

    }

    ret = bdrv_pwrite(bs, le64_to_cpu(header.rgd_offset) * BDRV_SECTOR_SIZE,

                      gd_buf, gd_buf_size);

    if (ret < 0) {

        error_set(errp, QERR_IO_ERROR);

        goto exit;

    }



    /* write backup grain directory */

    for (i = 0, tmp = le64_to_cpu(header.gd_offset) + gd_sectors;

         i < gt_count; i++, tmp += gt_size) {

        gd_buf[i] = cpu_to_le32(tmp);

    }

    ret = bdrv_pwrite(bs, le64_to_cpu(header.gd_offset) * BDRV_SECTOR_SIZE,

                      gd_buf, gd_buf_size);

    if (ret < 0) {

        error_set(errp, QERR_IO_ERROR);

        goto exit;

    }



    ret = 0;

exit:

    if (bs) {

        bdrv_unref(bs);

    }

    g_free(gd_buf);

    return ret;

}

static int cow_create(const char *filename, QemuOpts *opts, Error **errp)

{

    struct cow_header_v2 cow_header;

    struct stat st;

    int64_t image_sectors = 0;

    char *image_filename = NULL;

    Error *local_err = NULL;

    int ret;

    BlockDriverState *cow_bs = NULL;



    /* Read out options */

    image_sectors = DIV_ROUND_UP(qemu_opt_get_size_del(opts, BLOCK_OPT_SIZE, 0),

                                 BDRV_SECTOR_SIZE);

    image_filename = qemu_opt_get_del(opts, BLOCK_OPT_BACKING_FILE);



    ret = bdrv_create_file(filename, opts, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    ret = bdrv_open(&cow_bs, filename, NULL, NULL,

                    BDRV_O_RDWR | BDRV_O_PROTOCOL, NULL, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    memset(&cow_header, 0, sizeof(cow_header));

    cow_header.magic = cpu_to_be32(COW_MAGIC);

    cow_header.version = cpu_to_be32(COW_VERSION);

    if (image_filename) {

        /* Note: if no file, we put a dummy mtime */

        cow_header.mtime = cpu_to_be32(0);



        if (stat(image_filename, &st) != 0) {

            goto mtime_fail;

        }

        cow_header.mtime = cpu_to_be32(st.st_mtime);

    mtime_fail:

        pstrcpy(cow_header.backing_file, sizeof(cow_header.backing_file),

                image_filename);

    }

    cow_header.sectorsize = cpu_to_be32(512);

    cow_header.size = cpu_to_be64(image_sectors * 512);

    ret = bdrv_pwrite(cow_bs, 0, &cow_header, sizeof(cow_header));

    if (ret < 0) {

        goto exit;

    }



    /* resize to include at least all the bitmap */

    ret = bdrv_truncate(cow_bs,

        sizeof(cow_header) + ((image_sectors + 7) >> 3));

    if (ret < 0) {

        goto exit;

    }



exit:

    g_free(image_filename);

    if (cow_bs) {

        bdrv_unref(cow_bs);

    }

    return ret;

}

static int cow_open(BlockDriverState *bs, QDict *options, int flags,

                    Error **errp)

{

    BDRVCowState *s = bs->opaque;

    struct cow_header_v2 cow_header;

    int bitmap_size;

    int64_t size;

    int ret;



    /* see if it is a cow image */

    ret = bdrv_pread(bs->file, 0, &cow_header, sizeof(cow_header));

    if (ret < 0) {

        goto fail;

    }



    if (be32_to_cpu(cow_header.magic) != COW_MAGIC) {

        error_setg(errp, "Image not in COW format");

        ret = -EINVAL;

        goto fail;

    }



    if (be32_to_cpu(cow_header.version) != COW_VERSION) {

        char version[64];

        snprintf(version, sizeof(version),

               "COW version %" PRIu32, cow_header.version);

        error_set(errp, QERR_UNKNOWN_BLOCK_FORMAT_FEATURE,

            bs->device_name, "cow", version);

        ret = -ENOTSUP;

        goto fail;

    }



    /* cow image found */

    size = be64_to_cpu(cow_header.size);

    bs->total_sectors = size / 512;



    pstrcpy(bs->backing_file, sizeof(bs->backing_file),

            cow_header.backing_file);



    bitmap_size = ((bs->total_sectors + 7) >> 3) + sizeof(cow_header);

    s->cow_sectors_offset = (bitmap_size + 511) & ~511;

    qemu_co_mutex_init(&s->lock);

    return 0;

 fail:

    return ret;

}

static av_cold int adpcm_decode_init(AVCodecContext * avctx)

{

    ADPCMDecodeContext *c = avctx->priv_data;

    unsigned int max_channels = 2;



    switch(avctx->codec->id) {

    case CODEC_ID_ADPCM_EA_R1:

    case CODEC_ID_ADPCM_EA_R2:

    case CODEC_ID_ADPCM_EA_R3:

    case CODEC_ID_ADPCM_EA_XAS:

        max_channels = 6;

        break;

    }

    if(avctx->channels > max_channels){

        return -1;

    }



    switch(avctx->codec->id) {

    case CODEC_ID_ADPCM_CT:

        c->status[0].step = c->status[1].step = 511;

        break;

    case CODEC_ID_ADPCM_IMA_WAV:

        if (avctx->bits_per_coded_sample != 4) {

            av_log(avctx, AV_LOG_ERROR, "Only 4-bit ADPCM IMA WAV files are supported\n");

            return -1;

        }

        break;

    case CODEC_ID_ADPCM_IMA_WS:

        if (avctx->extradata && avctx->extradata_size == 2 * 4) {

            c->status[0].predictor = AV_RL32(avctx->extradata);

            c->status[1].predictor = AV_RL32(avctx->extradata + 4);

        }

        break;

    default:

        break;

    }

    avctx->sample_fmt = AV_SAMPLE_FMT_S16;



    avcodec_get_frame_defaults(&c->frame);

    avctx->coded_frame = &c->frame;



    return 0;

}

static av_cold int nvenc_setup_device(AVCodecContext *avctx)

{

    NvencContext *ctx = avctx->priv_data;

    NvencDynLoadFunctions *dl_fn = &ctx->nvenc_dload_funcs;



    CUresult cu_res;

    CUcontext cu_context_curr;



    switch (avctx->codec->id) {

    case AV_CODEC_ID_H264:

        ctx->init_encode_params.encodeGUID = NV_ENC_CODEC_H264_GUID;

        break;

    case AV_CODEC_ID_HEVC:

        ctx->init_encode_params.encodeGUID = NV_ENC_CODEC_HEVC_GUID;

        break;

    default:

        return AVERROR_BUG;

    }



    ctx->data_pix_fmt = avctx->pix_fmt;



#if CONFIG_CUDA

    if (avctx->pix_fmt == AV_PIX_FMT_CUDA) {

        AVHWFramesContext *frames_ctx;

        AVCUDADeviceContext *device_hwctx;



        if (!avctx->hw_frames_ctx) {

            av_log(avctx, AV_LOG_ERROR, "hw_frames_ctx must be set when using GPU frames as input\n");

            return AVERROR(EINVAL);

        }



        frames_ctx = (AVHWFramesContext*)avctx->hw_frames_ctx->data;

        device_hwctx = frames_ctx->device_ctx->hwctx;

        ctx->cu_context = device_hwctx->cuda_ctx;

        ctx->data_pix_fmt = frames_ctx->sw_format;

        return 0;

    }

#endif



    if (ctx->gpu >= dl_fn->nvenc_device_count) {

        av_log(avctx, AV_LOG_FATAL, "Requested GPU %d, but only %d GPUs are available!\n", ctx->gpu, dl_fn->nvenc_device_count);

        return AVERROR(EINVAL);

    }



    ctx->cu_context = NULL;

    cu_res = dl_fn->cu_ctx_create(&ctx->cu_context_internal, 4, dl_fn->nvenc_devices[ctx->gpu]); // CU_CTX_SCHED_BLOCKING_SYNC=4, avoid CPU spins



    if (cu_res != CUDA_SUCCESS) {

        av_log(avctx, AV_LOG_FATAL, "Failed creating CUDA context for NVENC: 0x%x\n", (int)cu_res);

        return AVERROR_EXTERNAL;

    }



    cu_res = dl_fn->cu_ctx_pop_current(&cu_context_curr);



    if (cu_res != CUDA_SUCCESS) {

        av_log(avctx, AV_LOG_FATAL, "Failed popping CUDA context: 0x%x\n", (int)cu_res);

        return AVERROR_EXTERNAL;

    }



    ctx->cu_context = ctx->cu_context_internal;



    return 0;

}

static av_cold int eightsvx_decode_init(AVCodecContext *avctx)

{

    EightSvxContext *esc = avctx->priv_data;



    if (avctx->channels < 1 || avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "8SVX does not support more than 2 channels\n");

        return AVERROR_INVALIDDATA;

    }



    switch (avctx->codec->id) {

    case AV_CODEC_ID_8SVX_FIB: esc->table = fibonacci;    break;

    case AV_CODEC_ID_8SVX_EXP: esc->table = exponential;  break;

    case AV_CODEC_ID_PCM_S8_PLANAR:

    case AV_CODEC_ID_8SVX_RAW: esc->table = NULL;         break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Invalid codec id %d.\n", avctx->codec->id);

        return AVERROR_INVALIDDATA;

    }

    avctx->sample_fmt = AV_SAMPLE_FMT_U8P;



    avcodec_get_frame_defaults(&esc->frame);

    avctx->coded_frame = &esc->frame;



    return 0;

}

static av_cold int msrle_decode_init(AVCodecContext *avctx)

{

    MsrleContext *s = avctx->priv_data;



    s->avctx = avctx;



    switch (avctx->bits_per_coded_sample) {

    case 4:

    case 8:

        avctx->pix_fmt = AV_PIX_FMT_PAL8;

        break;

    case 24:

        avctx->pix_fmt = AV_PIX_FMT_BGR24;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "unsupported bits per sample\n");

        return AVERROR_INVALIDDATA;

    }



    s->frame.data[0] = NULL;



    return 0;

}

static unsigned int dec_addi_acr(DisasContext *dc)

{

	TCGv t0;

	DIS(fprintf (logfile, "addi.%c $r%u, $r%u, $acr\n",

		  memsize_char(memsize_zz(dc)), dc->op2, dc->op1));

	cris_cc_mask(dc, 0);

	t0 = tcg_temp_new(TCG_TYPE_TL);

	tcg_gen_shl_tl(t0, cpu_R[dc->op2], tcg_const_tl(dc->zzsize));

	tcg_gen_add_tl(cpu_R[R_ACR], cpu_R[dc->op1], t0);



	return 2;

}

static unsigned int dec_move_r(DisasContext *dc)

{

	int size = memsize_zz(dc);



	DIS(fprintf (logfile, "move.%c $r%u, $r%u\n",

		    memsize_char(size), dc->op1, dc->op2));



	cris_cc_mask(dc, CC_MASK_NZ);

	if (size == 4) {

		dec_prep_move_r(dc, dc->op1, dc->op2, size, 0, cpu_R[dc->op2]);

		cris_cc_mask(dc, CC_MASK_NZ);

		cris_update_cc_op(dc, CC_OP_MOVE, 4);

		cris_update_cc_x(dc);

		cris_update_result(dc, cpu_R[dc->op2]);

	}

	else {

		TCGv t0;



		t0 = tcg_temp_new(TCG_TYPE_TL);

		dec_prep_move_r(dc, dc->op1, dc->op2, size, 0, t0);

		cris_alu(dc, CC_OP_MOVE,

			 cpu_R[dc->op2],

			 cpu_R[dc->op2], t0, size);

		tcg_temp_free(t0);

	}

	return 2;

}

static unsigned int dec_bound_m(DisasContext *dc)

{

	TCGv l[2];

	int memsize = memsize_zz(dc);

	int insn_len;

	DIS(fprintf (logfile, "bound.%d [$r%u%s, $r%u\n",

		    memsize_char(memsize),

		    dc->op1, dc->postinc ? "+]" : "]",

		    dc->op2));



	l[0] = tcg_temp_local_new(TCG_TYPE_TL);

	l[1] = tcg_temp_local_new(TCG_TYPE_TL);

	insn_len = dec_prep_alu_m(dc, 0, memsize, l[0], l[1]);

	cris_cc_mask(dc, CC_MASK_NZ);

	cris_alu(dc, CC_OP_BOUND, cpu_R[dc->op2], l[0], l[1], 4);

	do_postinc(dc, memsize);

	tcg_temp_free(l[0]);

	tcg_temp_free(l[1]);

	return insn_len;

}

static unsigned int dec_swap_r(DisasContext *dc)

{

	TCGv t0;

#if DISAS_CRIS

	char modename[4];

#endif

	DIS(fprintf (logfile, "swap%s $r%u\n",

		     swapmode_name(dc->op2, modename), dc->op1));



	cris_cc_mask(dc, CC_MASK_NZ);

	t0 = tcg_temp_new(TCG_TYPE_TL);

	t_gen_mov_TN_reg(t0, dc->op1);

	if (dc->op2 & 8)

		tcg_gen_not_tl(t0, t0);

	if (dc->op2 & 4)

		t_gen_swapw(t0, t0);

	if (dc->op2 & 2)

		t_gen_swapb(t0, t0);

	if (dc->op2 & 1)

		t_gen_swapr(t0, t0);

	cris_alu(dc, CC_OP_MOVE,

		    cpu_R[dc->op1], cpu_R[dc->op1], t0, 4);

	tcg_temp_free(t0);

	return 2;

}

static void bmdma_map(PCIDevice *pci_dev, int region_num,

                    pcibus_t addr, pcibus_t size, int type)

{

    PCIIDEState *d = DO_UPCAST(PCIIDEState, dev, pci_dev);

    int i;



    for(i = 0;i < 2; i++) {

        BMDMAState *bm = &d->bmdma[i];

        d->bus[i].bmdma = bm;

        bm->bus = d->bus+i;


        qemu_add_vm_change_state_handler(ide_dma_restart_cb, bm);



        register_ioport_write(addr, 1, 1, bmdma_cmd_writeb, bm);



        register_ioport_write(addr + 1, 3, 1, bmdma_writeb, bm);

        register_ioport_read(addr, 4, 1, bmdma_readb, bm);



        register_ioport_write(addr + 4, 4, 1, bmdma_addr_writeb, bm);

        register_ioport_read(addr + 4, 4, 1, bmdma_addr_readb, bm);

        register_ioport_write(addr + 4, 4, 2, bmdma_addr_writew, bm);

        register_ioport_read(addr + 4, 4, 2, bmdma_addr_readw, bm);

        register_ioport_write(addr + 4, 4, 4, bmdma_addr_writel, bm);

        register_ioport_read(addr + 4, 4, 4, bmdma_addr_readl, bm);

        addr += 8;

    }

}

