    s->period = qemu_get_be32(f);

    rtc_coalesced_timer_update(s);

    return 0;

}

static int read_packet(AVFormatContext *s1, AVPacket *pkt)

{

    VideoDemuxData *s = s1->priv_data;

    char filename[1024];

    int i;

    int size[3]={0}, ret[3]={0};

    AVIOContext *f[3];

    AVCodecContext *codec= s1->streams[0]->codec;



    if (!s->is_pipe) {

        /* loop over input */

        if (s->loop && s->img_number > s->img_last) {

            s->img_number = s->img_first;

        }

        if (s->img_number > s->img_last)

            return AVERROR_EOF;

        if (av_get_frame_filename(filename, sizeof(filename),

                                  s->path, s->img_number)<0 && s->img_number > 1)

            return AVERROR(EIO);

        for(i=0; i<3; i++){

            if (avio_open2(&f[i], filename, AVIO_FLAG_READ,

                           &s1->interrupt_callback, NULL) < 0) {

                if(i==1)

                    break;

                av_log(s1, AV_LOG_ERROR, "Could not open file : %s\n",filename);

                return AVERROR(EIO);

            }

            size[i]= avio_size(f[i]);



            if(codec->codec_id != AV_CODEC_ID_RAWVIDEO)

                break;

            filename[ strlen(filename) - 1 ]= 'U' + i;

        }



        if(codec->codec_id == AV_CODEC_ID_RAWVIDEO && !codec->width)

            infer_size(&codec->width, &codec->height, size[0]);

    } else {

        f[0] = s1->pb;

        if (f[0]->eof_reached)

            return AVERROR(EIO);

        size[0]= 4096;

    }



    av_new_packet(pkt, size[0] + size[1] + size[2]);

    pkt->stream_index = 0;

    pkt->flags |= AV_PKT_FLAG_KEY;



    pkt->size= 0;

    for(i=0; i<3; i++){

        if(size[i]){

            ret[i]= avio_read(f[i], pkt->data + pkt->size, size[i]);

            if (!s->is_pipe)

                avio_close(f[i]);

            if(ret[i]>0)

                pkt->size += ret[i];

        }

    }



    if (ret[0] <= 0 || ret[1]<0 || ret[2]<0) {

        av_free_packet(pkt);

        return AVERROR(EIO); /* signal EOF */

    } else {

        s->img_count++;

        s->img_number++;

        return 0;

    }

}

static int read_packet(AVFormatContext *s, AVPacket *pkt)

{

    PAFDemuxContext *p = s->priv_data;

    AVIOContext     *pb = s->pb;

    uint32_t        count, offset;

    int             size, i;



    if (p->current_frame >= p->nb_frames)

        return AVERROR_EOF;



    if (url_feof(pb))

        return AVERROR_EOF;



    if (p->got_audio) {

        if (av_new_packet(pkt, p->audio_size) < 0)

            return AVERROR(ENOMEM);



        memcpy(pkt->data, p->temp_audio_frame, p->audio_size);

        pkt->duration     = PAF_SOUND_SAMPLES * (p->audio_size / PAF_SOUND_FRAME_SIZE);

        pkt->flags       |= AV_PKT_FLAG_KEY;

        pkt->stream_index = 1;

        p->got_audio      = 0;

        return pkt->size;

    }



    count = (p->current_frame == 0) ? p->preload_count : p->blocks_count_table[p->current_frame - 1];

    for (i = 0; i < count; i++) {

        if (p->current_frame_block >= p->frame_blks)

            return AVERROR_INVALIDDATA;



        offset = p->blocks_offset_table[p->current_frame_block] & ~(1U << 31);

        if (p->blocks_offset_table[p->current_frame_block] & (1U << 31)) {

            if (offset > p->audio_size - p->buffer_size)

                return AVERROR_INVALIDDATA;



            avio_read(pb, p->audio_frame + offset, p->buffer_size);

            if (offset == (p->max_audio_blks - 2) * p->buffer_size) {

                memcpy(p->temp_audio_frame, p->audio_frame, p->audio_size);

                p->got_audio = 1;

            }

        } else {

            if (offset > p->video_size - p->buffer_size)

                return AVERROR_INVALIDDATA;



            avio_read(pb, p->video_frame + offset, p->buffer_size);

        }

        p->current_frame_block++;

    }



    size = p->video_size - p->frames_offset_table[p->current_frame];

    if (size < 1)

        return AVERROR_INVALIDDATA;



    if (av_new_packet(pkt, size) < 0)

        return AVERROR(ENOMEM);



    pkt->stream_index = 0;

    pkt->duration     = 1;

    memcpy(pkt->data, p->video_frame + p->frames_offset_table[p->current_frame], size);

    if (pkt->data[0] & 0x20)

        pkt->flags   |= AV_PKT_FLAG_KEY;

    p->current_frame++;



    return pkt->size;

}

static int img_read_packet(AVFormatContext *s1, AVPacket *pkt)

{

    VideoData *s = s1->priv_data;

    char filename[1024];

    int ret;

    ByteIOContext f1, *f;



    if (!s->is_pipe) {

        if (get_frame_filename(filename, sizeof(filename),

                               s->path, s->img_number) < 0)

            return -EIO;

        f = &f1;

        if (url_fopen(f, filename, URL_RDONLY) < 0)

            return -EIO;

    } else {

        f = &s1->pb;

        if (url_feof(f))

            return -EIO;

    }



    av_new_packet(pkt, s->img_size);

    pkt->stream_index = 0;



    s->ptr = pkt->data;

    ret = av_read_image(f, filename, s->img_fmt, read_packet_alloc_cb, s);

    if (!s->is_pipe) {

        url_fclose(f);

    }



    if (ret < 0) {

        av_free_packet(pkt);

        return -EIO; /* signal EOF */

    } else {

        pkt->pts = av_rescale((int64_t)s->img_number * s1->streams[0]->codec.frame_rate_base, s1->pts_den, s1->streams[0]->codec.frame_rate) / s1->pts_num;

        s->img_number++;

        return 0;

    }

}

static int read_packet(AVFormatContext *s,

                          AVPacket *pkt)

{

    ByteIOContext *pb = s->pb;

    PutBitContext pbo;

    uint16_t buf[8 * MAX_FRAME_SIZE + 2];

    int packet_size;

    int sync;

    uint16_t* src=buf;

    int i, j, ret;



    if(url_feof(pb))

        return AVERROR_EOF;



    sync = get_le16(pb); // sync word

    packet_size = get_le16(pb) / 8;

    assert(packet_size < 8 * MAX_FRAME_SIZE);



    ret = get_buffer(pb, (uint8_t*)buf, (8 * packet_size) * sizeof(uint16_t));

    if(ret<0)

        return ret;

    if(ret != 8 * packet_size * sizeof(uint16_t))

        return AVERROR(EIO);



    av_new_packet(pkt, packet_size);



    init_put_bits(&pbo, pkt->data, packet_size);

    for(j=0; j < packet_size; j++)

        for(i=0; i<8;i++)

            put_bits(&pbo,1, AV_RL16(src++) == BIT_1 ? 1 : 0);



    flush_put_bits(&pbo);



    pkt->duration=1;

    return 0;

}

