static void tcg_out_dat_rIN(TCGContext *s, int cond, int opc, int opneg,

                            TCGArg dst, TCGArg lhs, TCGArg rhs,

                            bool rhs_is_const)

{

    /* Emit either the reg,imm or reg,reg form of a data-processing insn.

     * rhs must satisfy the "rIN" constraint.

     */

    if (rhs_is_const) {

        int rot = encode_imm(rhs);

        if (rot < 0) {

            rhs = -rhs;

            rot = encode_imm(rhs);

            assert(rot >= 0);

            opc = opneg;

        }

        tcg_out_dat_imm(s, cond, opc, dst, lhs, rotl(rhs, rot) | (rot << 7));

    } else {

        tcg_out_dat_reg(s, cond, opc, dst, lhs, rhs, SHIFT_IMM_LSL(0));

    }

}

static void tcg_out_ri64(TCGContext *s, int const_arg, TCGArg arg)

{

    if (const_arg) {

        assert(const_arg == 1);

        tcg_out8(s, TCG_CONST);

        tcg_out64(s, arg);

    } else {

        tcg_out_r(s, arg);

    }

}

static bool tcg_out_opc_jmp(TCGContext *s, MIPSInsn opc, void *target)

{

    uintptr_t dest = (uintptr_t)target;

    uintptr_t from = (uintptr_t)s->code_ptr + 4;

    int32_t inst;



    /* The pc-region branch happens within the 256MB region of

       the delay slot (thus the +4).  */

    if ((from ^ dest) & -(1 << 28)) {

        return false;

    }

    assert((dest & 3) == 0);



    inst = opc;

    inst |= (dest >> 2) & 0x3ffffff;

    tcg_out32(s, inst);

    return true;

}

static inline void gen_jcc1_noeob(DisasContext *s, int b, int l1)

{

    CCPrepare cc = gen_prepare_cc(s, b, cpu_T[0]);



    if (cc.mask != -1) {

        tcg_gen_andi_tl(cpu_T[0], cc.reg, cc.mask);

        cc.reg = cpu_T[0];

    }

    if (cc.use_reg2) {

        tcg_gen_brcond_tl(cc.cond, cc.reg, cc.reg2, l1);

    } else {

        tcg_gen_brcondi_tl(cc.cond, cc.reg, cc.imm, l1);

    }

}

