static int mov_create_chapter_track(AVFormatContext *s, int tracknum)

{

    MOVMuxContext *mov = s->priv_data;

    MOVTrack *track = &mov->tracks[tracknum];

    AVPacket pkt = { .stream_index = tracknum, .flags = AV_PKT_FLAG_KEY };

    int i, len;

    // These properties are required to make QT recognize the chapter track

    uint8_t chapter_properties[43] = { 0, 0, 0, 0, 0, 0, 0, 1, };



    track->mode = mov->mode;

    track->tag = MKTAG('t','e','x','t');

    track->timescale = MOV_TIMESCALE;

    track->enc = avcodec_alloc_context3(NULL);

    if (!track->enc)


    track->enc->codec_type = AVMEDIA_TYPE_SUBTITLE;

    track->enc->extradata = av_malloc(sizeof(chapter_properties));

    if (track->enc->extradata == NULL)


    track->enc->extradata_size = sizeof(chapter_properties);

    memcpy(track->enc->extradata, chapter_properties, sizeof(chapter_properties));



    for (i = 0; i < s->nb_chapters; i++) {

        AVChapter *c = s->chapters[i];

        AVDictionaryEntry *t;



        int64_t end = av_rescale_q(c->end, c->time_base, (AVRational){1,MOV_TIMESCALE});

        pkt.pts = pkt.dts = av_rescale_q(c->start, c->time_base, (AVRational){1,MOV_TIMESCALE});

        pkt.duration = end - pkt.dts;



        if ((t = av_dict_get(c->metadata, "title", NULL, 0))) {

            len      = strlen(t->value);

            pkt.size = len + 2;

            pkt.data = av_malloc(pkt.size);



            AV_WB16(pkt.data, len);

            memcpy(pkt.data + 2, t->value, len);

            ff_mov_write_packet(s, &pkt);

            av_freep(&pkt.data);

        }

    }



    return 0;

}

static int mpegts_write_packet_internal(AVFormatContext *s, AVPacket *pkt)

{

    AVStream *st = s->streams[pkt->stream_index];

    int size = pkt->size;

    uint8_t *buf = pkt->data;

    uint8_t *data = NULL;

    MpegTSWrite *ts = s->priv_data;

    MpegTSWriteStream *ts_st = st->priv_data;

    const int64_t delay = av_rescale(s->max_delay, 90000, AV_TIME_BASE) * 2;

    int64_t dts = pkt->dts, pts = pkt->pts;



    if (ts->reemit_pat_pmt) {

        av_log(s, AV_LOG_WARNING,

               "resend_headers option is deprecated, use -mpegts_flags resend_headers\n");

        ts->reemit_pat_pmt = 0;

        ts->flags         |= MPEGTS_FLAG_REEMIT_PAT_PMT;

    }



    if (ts->flags & MPEGTS_FLAG_REEMIT_PAT_PMT) {

        ts->pat_packet_count = ts->pat_packet_period - 1;

        ts->sdt_packet_count = ts->sdt_packet_period - 1;

        ts->flags           &= ~MPEGTS_FLAG_REEMIT_PAT_PMT;

    }



    if (ts->copyts < 1) {

        if (pts != AV_NOPTS_VALUE)

            pts += delay;

        if (dts != AV_NOPTS_VALUE)

            dts += delay;

    }



    if (ts_st->first_pts_check && pts == AV_NOPTS_VALUE) {

        av_log(s, AV_LOG_ERROR, "first pts value must be set\n");

        return AVERROR_INVALIDDATA;

    }

    ts_st->first_pts_check = 0;



    if (st->codec->codec_id == AV_CODEC_ID_H264) {

        const uint8_t *p = buf, *buf_end = p + size;

        uint32_t state = -1;

        int extradd = (pkt->flags & AV_PKT_FLAG_KEY) ? st->codec->extradata_size : 0;

        int ret = ff_check_h264_startcode(s, st, pkt);

        if (ret < 0)

            return ret;



        if (extradd && AV_RB24(st->codec->extradata) > 1)

            extradd = 0;



        do {

            p = avpriv_find_start_code(p, buf_end, &state);

            av_log(s, AV_LOG_TRACE, "nal %d\n", state & 0x1f);

            if ((state & 0x1f) == 7)

                extradd = 0;

        } while (p < buf_end && (state & 0x1f) != 9 &&

                 (state & 0x1f) != 5 && (state & 0x1f) != 1);



        if ((state & 0x1f) != 5)

            extradd = 0;

        if ((state & 0x1f) != 9) { // AUD NAL

            data = av_malloc(pkt->size + 6 + extradd);

            if (!data)

                return AVERROR(ENOMEM);

            memcpy(data + 6, st->codec->extradata, extradd);

            memcpy(data + 6 + extradd, pkt->data, pkt->size);

            AV_WB32(data, 0x00000001);

            data[4] = 0x09;

            data[5] = 0xf0; // any slice type (0xe) + rbsp stop one bit

            buf     = data;

            size    = pkt->size + 6 + extradd;

        }

    } else if (st->codec->codec_id == AV_CODEC_ID_AAC) {

        if (pkt->size < 2) {

            av_log(s, AV_LOG_ERROR, "AAC packet too short\n");

            return AVERROR_INVALIDDATA;

        }

        if ((AV_RB16(pkt->data) & 0xfff0) != 0xfff0) {

            int ret;

            AVPacket pkt2;



            if (!ts_st->amux) {

                av_log(s, AV_LOG_ERROR, "AAC bitstream not in ADTS format "

                                        "and extradata missing\n");

                return AVERROR_INVALIDDATA;

            }



            av_init_packet(&pkt2);

            pkt2.data = pkt->data;

            pkt2.size = pkt->size;

            av_assert0(pkt->dts != AV_NOPTS_VALUE);

            pkt2.dts = av_rescale_q(pkt->dts, st->time_base, ts_st->amux->streams[0]->time_base);



            ret = avio_open_dyn_buf(&ts_st->amux->pb);

            if (ret < 0)

                return AVERROR(ENOMEM);



            ret = av_write_frame(ts_st->amux, &pkt2);

            if (ret < 0) {

                ffio_free_dyn_buf(&ts_st->amux->pb);

                return ret;

            }

            size            = avio_close_dyn_buf(ts_st->amux->pb, &data);

            ts_st->amux->pb = NULL;

            buf             = data;

        }

    } else if (st->codec->codec_id == AV_CODEC_ID_HEVC) {

        int ret = check_hevc_startcode(s, st, pkt);

        if (ret < 0)

            return ret;

    }



    if (pkt->dts != AV_NOPTS_VALUE) {

        int i;

        for(i=0; i<s->nb_streams; i++) {

            AVStream *st2 = s->streams[i];

            MpegTSWriteStream *ts_st2 = st2->priv_data;

            if (   ts_st2->payload_size

               && (ts_st2->payload_dts == AV_NOPTS_VALUE || dts - ts_st2->payload_dts > delay/2)) {

                mpegts_write_pes(s, st2, ts_st2->payload, ts_st2->payload_size,

                                ts_st2->payload_pts, ts_st2->payload_dts,

                                ts_st2->payload_flags & AV_PKT_FLAG_KEY);

                ts_st2->payload_size = 0;

            }

        }

    }



    if (ts_st->payload_size && (ts_st->payload_size + size > ts->pes_payload_size ||

        (dts != AV_NOPTS_VALUE && ts_st->payload_dts != AV_NOPTS_VALUE &&

         av_compare_ts(dts - ts_st->payload_dts, st->time_base,

                       s->max_delay, AV_TIME_BASE_Q) >= 0))) {

        mpegts_write_pes(s, st, ts_st->payload, ts_st->payload_size,

                         ts_st->payload_pts, ts_st->payload_dts,

                         ts_st->payload_flags & AV_PKT_FLAG_KEY);

        ts_st->payload_size = 0;

    }



    if (st->codec->codec_type != AVMEDIA_TYPE_AUDIO || size > ts->pes_payload_size) {

        av_assert0(!ts_st->payload_size);

        // for video and subtitle, write a single pes packet

        mpegts_write_pes(s, st, buf, size, pts, dts,

                         pkt->flags & AV_PKT_FLAG_KEY);

        av_free(data);

        return 0;

    }



    if (!ts_st->payload_size) {

        ts_st->payload_pts   = pts;

        ts_st->payload_dts   = dts;

        ts_st->payload_flags = pkt->flags;

    }



    memcpy(ts_st->payload + ts_st->payload_size, buf, size);

    ts_st->payload_size += size;



    av_free(data);



    return 0;

}

static int mov_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    MOVContext *mov = s->priv_data;

    ByteIOContext *pb = s->pb;

    MOVTrack *trk = &mov->tracks[pkt->stream_index];

    AVCodecContext *enc = trk->enc;

    unsigned int samplesInChunk = 0;

    int size= pkt->size;



    if (url_is_streamed(s->pb)) return 0; /* Can't handle that */

    if (!size) return 0; /* Discard 0 sized packets */



    if (enc->codec_id == CODEC_ID_AMR_NB) {

        /* We must find out how many AMR blocks there are in one packet */

        static uint16_t packed_size[16] =

            {13, 14, 16, 18, 20, 21, 27, 32, 6, 0, 0, 0, 0, 0, 0, 0};

        int len = 0;



        while (len < size && samplesInChunk < 100) {

            len += packed_size[(pkt->data[len] >> 3) & 0x0F];

            samplesInChunk++;

        }

        if(samplesInChunk > 1){

            av_log(s, AV_LOG_ERROR, "fatal error, input is not a single packet, implement a AVParser for it\n");

            return -1;

        }

    } else if (trk->sampleSize)

        samplesInChunk = size/trk->sampleSize;

    else

        samplesInChunk = 1;



    /* copy extradata if it exists */

    if (trk->vosLen == 0 && enc->extradata_size > 0) {

        trk->vosLen = enc->extradata_size;

        trk->vosData = av_malloc(trk->vosLen);

        memcpy(trk->vosData, enc->extradata, trk->vosLen);

    }



    if (enc->codec_id == CODEC_ID_H264 && trk->vosLen > 0 && *(uint8_t *)trk->vosData != 1) {

        /* from x264 or from bytestream h264 */

        /* nal reformating needed */

        int ret = ff_avc_parse_nal_units(pkt->data, &pkt->data, &pkt->size);

        if (ret < 0)

            return ret;

        assert(pkt->size);

        size = pkt->size;

    } else if (enc->codec_id == CODEC_ID_DNXHD && !trk->vosLen) {

        /* copy frame header to create needed atoms */

        if (size < 640)

            return -1;

        trk->vosLen = 640;

        trk->vosData = av_malloc(trk->vosLen);

        memcpy(trk->vosData, pkt->data, 640);

    }



    if (!(trk->entry % MOV_INDEX_CLUSTER_SIZE)) {

        trk->cluster = av_realloc(trk->cluster, (trk->entry + MOV_INDEX_CLUSTER_SIZE) * sizeof(*trk->cluster));

        if (!trk->cluster)

            return -1;

    }



    trk->cluster[trk->entry].pos = url_ftell(pb);

    trk->cluster[trk->entry].samplesInChunk = samplesInChunk;

    trk->cluster[trk->entry].size = size;

    trk->cluster[trk->entry].entries = samplesInChunk;

    trk->cluster[trk->entry].dts = pkt->dts;

    trk->trackDuration = pkt->dts - trk->cluster[0].dts + pkt->duration;



    if(enc->codec_type == CODEC_TYPE_VIDEO) {

        if (pkt->dts != pkt->pts)

            trk->hasBframes = 1;

        trk->cluster[trk->entry].cts = pkt->pts - pkt->dts;

        trk->cluster[trk->entry].key_frame = !!(pkt->flags & PKT_FLAG_KEY);

        if(trk->cluster[trk->entry].key_frame)

            trk->hasKeyframes++;

    }

    trk->entry++;

    trk->sampleCount += samplesInChunk;

    mov->mdat_size += size;



    put_buffer(pb, pkt->data, size);



    put_flush_packet(pb);

    return 0;

}

static int mov_write_packet(AVFormatContext *s, int stream_index,

                            const uint8_t *buf, int size, int64_t pts)

{

    MOVContext *mov = s->priv_data;

    ByteIOContext *pb = &s->pb;

    AVCodecContext *enc = &s->streams[stream_index]->codec;

    MOVTrack* trk = &mov->tracks[stream_index];

    int cl, id;

    unsigned int samplesInChunk = 0;



    if (url_is_streamed(&s->pb)) return 0; /* Can't handle that */

    if (!size) return 0; /* Discard 0 sized packets */



    if (enc->codec_type == CODEC_TYPE_VIDEO ) {

        samplesInChunk = 1;

    }

    else if (enc->codec_type == CODEC_TYPE_AUDIO ) {

        if( enc->codec_id == CODEC_ID_AMR_NB) {

            /* We must find out how many AMR blocks there are in one packet */

            static uint16_t packed_size[16] =

                {13, 14, 16, 18, 20, 21, 27, 32, 6, 0, 0, 0, 0, 0, 0, 0};

            int len = 0;



            while (len < size && samplesInChunk < 100) {

                len += packed_size[(buf[len] >> 3) & 0x0F];

                samplesInChunk++;

            }

        }

        else if(enc->codec_id == CODEC_ID_PCM_ALAW) {

            samplesInChunk = size/enc->channels;

        }

        else {

            samplesInChunk = 1;

        }

    }



    if ((enc->codec_id == CODEC_ID_MPEG4 || enc->codec_id == CODEC_ID_AAC)

        && trk->vosLen == 0) {

        assert(enc->extradata_size);



        trk->vosLen = enc->extradata_size;

        trk->vosData = av_malloc(trk->vosLen);

        memcpy(trk->vosData, enc->extradata, trk->vosLen);

    }



    cl = trk->entry / MOV_INDEX_CLUSTER_SIZE;

    id = trk->entry % MOV_INDEX_CLUSTER_SIZE;



    if (trk->ents_allocated <= trk->entry) {

        trk->cluster = av_realloc(trk->cluster, (cl+1)*sizeof(void*)); 

        if (!trk->cluster)

            return -1;

        trk->cluster[cl] = av_malloc(MOV_INDEX_CLUSTER_SIZE*sizeof(MOVIentry));

        if (!trk->cluster[cl])

            return -1;

        trk->ents_allocated += MOV_INDEX_CLUSTER_SIZE;

    }

    if (mov->mdat_written == 0) {

        mov_write_mdat_tag(pb, mov);

        mov->mdat_written = 1;

        mov->time = Timestamp();

    }



    trk->cluster[cl][id].pos = url_ftell(pb) - mov->movi_list;

    trk->cluster[cl][id].samplesInChunk = samplesInChunk;

    trk->cluster[cl][id].size = size;

    trk->cluster[cl][id].entries = samplesInChunk;

    if(enc->codec_type == CODEC_TYPE_VIDEO) {

        trk->cluster[cl][id].key_frame = enc->coded_frame->key_frame;

        if(enc->coded_frame->pict_type == FF_I_TYPE)

            trk->hasKeyframes = 1;

    }

    trk->enc = enc;

    trk->entry++;

    trk->sampleCount += samplesInChunk;

    trk->mdat_size += size;



    put_buffer(pb, buf, size);



    put_flush_packet(pb);

    return 0;

}

static void gen_ld (CPUMIPSState *env, DisasContext *ctx, uint32_t opc,

                    int rt, int base, int16_t offset)

{

    const char *opn = "ld";

    TCGv t0, t1;



    if (rt == 0 && env->insn_flags & (INSN_LOONGSON2E | INSN_LOONGSON2F)) {

        /* Loongson CPU uses a load to zero register for prefetch.

           We emulate it as a NOP. On other CPU we must perform the

           actual memory access. */

        MIPS_DEBUG("NOP");

        return;

    }



    t0 = tcg_temp_new();

    gen_base_offset_addr(ctx, t0, base, offset);



    switch (opc) {

#if defined(TARGET_MIPS64)

    case OPC_LWU:

        tcg_gen_qemu_ld32u(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lwu";

        break;

    case OPC_LD:

        tcg_gen_qemu_ld64(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "ld";

        break;

    case OPC_LLD:

        save_cpu_state(ctx, 1);

        op_ld_lld(t0, t0, ctx);

        gen_store_gpr(t0, rt);

        opn = "lld";

        break;

    case OPC_LDL:

        save_cpu_state(ctx, 1);

        t1 = tcg_temp_new();

        gen_load_gpr(t1, rt);

        gen_helper_1e2i(ldl, t1, t1, t0, ctx->mem_idx);

        gen_store_gpr(t1, rt);

        tcg_temp_free(t1);

        opn = "ldl";

        break;

    case OPC_LDR:

        save_cpu_state(ctx, 1);

        t1 = tcg_temp_new();

        gen_load_gpr(t1, rt);

        gen_helper_1e2i(ldr, t1, t1, t0, ctx->mem_idx);

        gen_store_gpr(t1, rt);

        tcg_temp_free(t1);

        opn = "ldr";

        break;

    case OPC_LDPC:

        t1 = tcg_const_tl(pc_relative_pc(ctx));

        gen_op_addr_add(ctx, t0, t0, t1);

        tcg_temp_free(t1);

        tcg_gen_qemu_ld64(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "ldpc";

        break;

#endif

    case OPC_LWPC:

        t1 = tcg_const_tl(pc_relative_pc(ctx));

        gen_op_addr_add(ctx, t0, t0, t1);

        tcg_temp_free(t1);

        tcg_gen_qemu_ld32s(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lwpc";

        break;

    case OPC_LW:

        tcg_gen_qemu_ld32s(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lw";

        break;

    case OPC_LH:

        tcg_gen_qemu_ld16s(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lh";

        break;

    case OPC_LHU:

        tcg_gen_qemu_ld16u(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lhu";

        break;

    case OPC_LB:

        tcg_gen_qemu_ld8s(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lb";

        break;

    case OPC_LBU:

        tcg_gen_qemu_ld8u(t0, t0, ctx->mem_idx);

        gen_store_gpr(t0, rt);

        opn = "lbu";

        break;

    case OPC_LWL:

        save_cpu_state(ctx, 1);

        t1 = tcg_temp_new();

        gen_load_gpr(t1, rt);

        gen_helper_1e2i(lwl, t1, t1, t0, ctx->mem_idx);

        gen_store_gpr(t1, rt);

        tcg_temp_free(t1);

        opn = "lwl";

        break;

    case OPC_LWR:

        save_cpu_state(ctx, 1);

        t1 = tcg_temp_new();

        gen_load_gpr(t1, rt);

        gen_helper_1e2i(lwr, t1, t1, t0, ctx->mem_idx);

        gen_store_gpr(t1, rt);

        tcg_temp_free(t1);

        opn = "lwr";

        break;

    case OPC_LL:

        save_cpu_state(ctx, 1);

        op_ld_ll(t0, t0, ctx);

        gen_store_gpr(t0, rt);

        opn = "ll";

        break;

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s, %d(%s)", opn, regnames[rt], offset, regnames[base]);

    tcg_temp_free(t0);

}

static void gen_muldiv (DisasContext *ctx, uint32_t opc,

                        int rs, int rt)

{

    const char *opn = "mul/div";

    TCGv t0, t1;

    unsigned int acc;



    switch (opc) {

    case OPC_DIV:

    case OPC_DIVU:

#if defined(TARGET_MIPS64)

    case OPC_DDIV:

    case OPC_DDIVU:

#endif

        t0 = tcg_temp_local_new();

        t1 = tcg_temp_local_new();

        break;

    default:

        t0 = tcg_temp_new();

        t1 = tcg_temp_new();

        break;

    }



    gen_load_gpr(t0, rs);

    gen_load_gpr(t1, rt);

    switch (opc) {

    case OPC_DIV:

        {

            int l1 = gen_new_label();

            int l2 = gen_new_label();



            tcg_gen_ext32s_tl(t0, t0);

            tcg_gen_ext32s_tl(t1, t1);

            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_brcondi_tl(TCG_COND_NE, t0, INT_MIN, l2);

            tcg_gen_brcondi_tl(TCG_COND_NE, t1, -1, l2);



            tcg_gen_mov_tl(cpu_LO[0], t0);

            tcg_gen_movi_tl(cpu_HI[0], 0);

            tcg_gen_br(l1);

            gen_set_label(l2);

            tcg_gen_div_tl(cpu_LO[0], t0, t1);

            tcg_gen_rem_tl(cpu_HI[0], t0, t1);

            tcg_gen_ext32s_tl(cpu_LO[0], cpu_LO[0]);

            tcg_gen_ext32s_tl(cpu_HI[0], cpu_HI[0]);

            gen_set_label(l1);

        }

        opn = "div";

        break;

    case OPC_DIVU:

        {

            int l1 = gen_new_label();



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_divu_tl(cpu_LO[0], t0, t1);

            tcg_gen_remu_tl(cpu_HI[0], t0, t1);

            tcg_gen_ext32s_tl(cpu_LO[0], cpu_LO[0]);

            tcg_gen_ext32s_tl(cpu_HI[0], cpu_HI[0]);

            gen_set_label(l1);

        }

        opn = "divu";

        break;

    case OPC_MULT:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext_tl_i64(t2, t0);

            tcg_gen_ext_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "mult";

        break;

    case OPC_MULTU:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_extu_tl_i64(t2, t0);

            tcg_gen_extu_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "multu";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DDIV:

        {

            int l1 = gen_new_label();

            int l2 = gen_new_label();



            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_brcondi_tl(TCG_COND_NE, t0, -1LL << 63, l2);

            tcg_gen_brcondi_tl(TCG_COND_NE, t1, -1LL, l2);

            tcg_gen_mov_tl(cpu_LO[0], t0);

            tcg_gen_movi_tl(cpu_HI[0], 0);

            tcg_gen_br(l1);

            gen_set_label(l2);

            tcg_gen_div_i64(cpu_LO[0], t0, t1);

            tcg_gen_rem_i64(cpu_HI[0], t0, t1);

            gen_set_label(l1);

        }

        opn = "ddiv";

        break;

    case OPC_DDIVU:

        {

            int l1 = gen_new_label();



            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_divu_i64(cpu_LO[0], t0, t1);

            tcg_gen_remu_i64(cpu_HI[0], t0, t1);

            gen_set_label(l1);

        }

        opn = "ddivu";

        break;

    case OPC_DMULT:

        gen_helper_dmult(cpu_env, t0, t1);

        opn = "dmult";

        break;

    case OPC_DMULTU:

        gen_helper_dmultu(cpu_env, t0, t1);

        opn = "dmultu";

        break;

#endif

    case OPC_MADD:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext_tl_i64(t2, t0);

            tcg_gen_ext_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_add_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "madd";

        break;

    case OPC_MADDU:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_extu_tl_i64(t2, t0);

            tcg_gen_extu_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_add_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "maddu";

        break;

    case OPC_MSUB:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext_tl_i64(t2, t0);

            tcg_gen_ext_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_sub_i64(t2, t3, t2);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "msub";

        break;

    case OPC_MSUBU:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_extu_tl_i64(t2, t0);

            tcg_gen_extu_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_sub_i64(t2, t3, t2);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "msubu";

        break;

    default:

        MIPS_INVAL(opn);

        generate_exception(ctx, EXCP_RI);

        goto out;

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s %s", opn, regnames[rs], regnames[rt]);

 out:

    tcg_temp_free(t0);

    tcg_temp_free(t1);

}

static void gen_flt3_ldst (DisasContext *ctx, uint32_t opc,

                           int fd, int fs, int base, int index)

{

    const char *opn = "extended float load/store";

    int store = 0;

    TCGv t0 = tcg_temp_new();



    if (base == 0) {

        gen_load_gpr(t0, index);

    } else if (index == 0) {

        gen_load_gpr(t0, base);

    } else {

        gen_load_gpr(t0, index);

        gen_op_addr_add(ctx, t0, cpu_gpr[base]);

    }

    /* Don't do NOP if destination is zero: we must perform the actual

       memory access. */

    save_cpu_state(ctx, 0);

    switch (opc) {

    case OPC_LWXC1:

        check_cop1x(ctx);

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            tcg_gen_qemu_ld32s(t0, t0, ctx->mem_idx);

            tcg_gen_trunc_tl_i32(fp0, t0);

            gen_store_fpr32(fp0, fd);

            tcg_temp_free_i32(fp0);

        }

        opn = "lwxc1";

        break;

    case OPC_LDXC1:

        check_cop1x(ctx);

        check_cp1_registers(ctx, fd);

        {

            TCGv_i64 fp0 = tcg_temp_new_i64();



            tcg_gen_qemu_ld64(fp0, t0, ctx->mem_idx);

            gen_store_fpr64(ctx, fp0, fd);

            tcg_temp_free_i64(fp0);

        }

        opn = "ldxc1";

        break;

    case OPC_LUXC1:

        check_cp1_64bitmode(ctx);

        tcg_gen_andi_tl(t0, t0, ~0x7);

        {

            TCGv_i64 fp0 = tcg_temp_new_i64();



            tcg_gen_qemu_ld64(fp0, t0, ctx->mem_idx);

            gen_store_fpr64(ctx, fp0, fd);

            tcg_temp_free_i64(fp0);

        }

        opn = "luxc1";

        break;

    case OPC_SWXC1:

        check_cop1x(ctx);

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();

            TCGv t1 = tcg_temp_new();



            gen_load_fpr32(fp0, fs);

            tcg_gen_extu_i32_tl(t1, fp0);

            tcg_gen_qemu_st32(t1, t0, ctx->mem_idx);

            tcg_temp_free_i32(fp0);

            tcg_temp_free_i32(t1);

        }

        opn = "swxc1";

        store = 1;

        break;

    case OPC_SDXC1:

        check_cop1x(ctx);

        check_cp1_registers(ctx, fs);

        {

            TCGv_i64 fp0 = tcg_temp_new_i64();



            gen_load_fpr64(ctx, fp0, fs);

            tcg_gen_qemu_st64(fp0, t0, ctx->mem_idx);

            tcg_temp_free_i64(fp0);

        }

        opn = "sdxc1";

        store = 1;

        break;

    case OPC_SUXC1:

        check_cp1_64bitmode(ctx);

        tcg_gen_andi_tl(t0, t0, ~0x7);

        {

            TCGv_i64 fp0 = tcg_temp_new_i64();



            gen_load_fpr64(ctx, fp0, fs);

            tcg_gen_qemu_st64(fp0, t0, ctx->mem_idx);

            tcg_temp_free_i64(fp0);

        }

        opn = "suxc1";

        store = 1;

        break;

    }

    tcg_temp_free(t0);

    MIPS_DEBUG("%s %s, %s(%s)", opn, fregnames[store ? fs : fd],

               regnames[index], regnames[base]);

}

static void gen_arith (CPUState *env, DisasContext *ctx, uint32_t opc,

                       int rd, int rs, int rt)

{

    const char *opn = "arith";

    TCGv t0 = tcg_temp_local_new(TCG_TYPE_TL);

    TCGv t1 = tcg_temp_local_new(TCG_TYPE_TL);



    if (rd == 0 && opc != OPC_ADD && opc != OPC_SUB

       && opc != OPC_DADD && opc != OPC_DSUB) {

        /* If no destination, treat it as a NOP.

           For add & sub, we must generate the overflow exception when needed. */

        MIPS_DEBUG("NOP");

        goto out;

    }

    gen_load_gpr(t0, rs);

    /* Specialcase the conventional move operation. */

    if (rt == 0 && (opc == OPC_ADDU || opc == OPC_DADDU

                    || opc == OPC_SUBU || opc == OPC_DSUBU)) {

        gen_store_gpr(t0, rd);

        goto out;

    }

    gen_load_gpr(t1, rt);

    switch (opc) {

    case OPC_ADD:

        {

            TCGv r_tmp1 = tcg_temp_local_new(TCG_TYPE_TL);

            TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_TL);

            int l1 = gen_new_label();



            save_cpu_state(ctx, 1);

            tcg_gen_ext32s_tl(r_tmp1, t0);

            tcg_gen_ext32s_tl(r_tmp2, t1);

            tcg_gen_add_tl(t0, r_tmp1, r_tmp2);



            tcg_gen_xor_tl(r_tmp1, r_tmp1, t1);

            tcg_gen_xori_tl(r_tmp1, r_tmp1, -1);

            tcg_gen_xor_tl(r_tmp2, t0, t1);

            tcg_gen_and_tl(r_tmp1, r_tmp1, r_tmp2);

            tcg_temp_free(r_tmp2);

            tcg_gen_shri_tl(r_tmp1, r_tmp1, 31);

            tcg_gen_brcondi_tl(TCG_COND_EQ, r_tmp1, 0, l1);

            tcg_temp_free(r_tmp1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);



            tcg_gen_ext32s_tl(t0, t0);

        }

        opn = "add";

        break;

    case OPC_ADDU:

        tcg_gen_ext32s_tl(t0, t0);

        tcg_gen_ext32s_tl(t1, t1);

        tcg_gen_add_tl(t0, t0, t1);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "addu";

        break;

    case OPC_SUB:

        {

            TCGv r_tmp1 = tcg_temp_local_new(TCG_TYPE_TL);

            TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_TL);

            int l1 = gen_new_label();



            save_cpu_state(ctx, 1);

            tcg_gen_ext32s_tl(r_tmp1, t0);

            tcg_gen_ext32s_tl(r_tmp2, t1);

            tcg_gen_sub_tl(t0, r_tmp1, r_tmp2);



            tcg_gen_xor_tl(r_tmp2, r_tmp1, t1);

            tcg_gen_xor_tl(r_tmp1, r_tmp1, t0);

            tcg_gen_and_tl(r_tmp1, r_tmp1, r_tmp2);

            tcg_temp_free(r_tmp2);

            tcg_gen_shri_tl(r_tmp1, r_tmp1, 31);

            tcg_gen_brcondi_tl(TCG_COND_EQ, r_tmp1, 0, l1);

            tcg_temp_free(r_tmp1);

            /* operands of different sign, first operand and result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);



            tcg_gen_ext32s_tl(t0, t0);

        }

        opn = "sub";

        break;

    case OPC_SUBU:

        tcg_gen_ext32s_tl(t0, t0);

        tcg_gen_ext32s_tl(t1, t1);

        tcg_gen_sub_tl(t0, t0, t1);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "subu";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DADD:

        {

            TCGv r_tmp1 = tcg_temp_local_new(TCG_TYPE_TL);

            TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_TL);

            int l1 = gen_new_label();



            save_cpu_state(ctx, 1);

            tcg_gen_mov_tl(r_tmp1, t0);

            tcg_gen_add_tl(t0, t0, t1);



            tcg_gen_xor_tl(r_tmp1, r_tmp1, t1);

            tcg_gen_xori_tl(r_tmp1, r_tmp1, -1);

            tcg_gen_xor_tl(r_tmp2, t0, t1);

            tcg_gen_and_tl(r_tmp1, r_tmp1, r_tmp2);

            tcg_temp_free(r_tmp2);

            tcg_gen_shri_tl(r_tmp1, r_tmp1, 63);

            tcg_gen_brcondi_tl(TCG_COND_EQ, r_tmp1, 0, l1);

            tcg_temp_free(r_tmp1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

        }

        opn = "dadd";

        break;

    case OPC_DADDU:

        tcg_gen_add_tl(t0, t0, t1);

        opn = "daddu";

        break;

    case OPC_DSUB:

        {

            TCGv r_tmp1 = tcg_temp_local_new(TCG_TYPE_TL);

            TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_TL);

            int l1 = gen_new_label();



            save_cpu_state(ctx, 1);

            tcg_gen_mov_tl(r_tmp1, t0);

            tcg_gen_sub_tl(t0, t0, t1);



            tcg_gen_xor_tl(r_tmp2, r_tmp1, t1);

            tcg_gen_xor_tl(r_tmp1, r_tmp1, t0);

            tcg_gen_and_tl(r_tmp1, r_tmp1, r_tmp2);

            tcg_temp_free(r_tmp2);

            tcg_gen_shri_tl(r_tmp1, r_tmp1, 63);

            tcg_gen_brcondi_tl(TCG_COND_EQ, r_tmp1, 0, l1);

            tcg_temp_free(r_tmp1);

            /* operands of different sign, first operand and result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

        }

        opn = "dsub";

        break;

    case OPC_DSUBU:

        tcg_gen_sub_tl(t0, t0, t1);

        opn = "dsubu";

        break;

#endif

    case OPC_SLT:

        gen_op_lt(t0, t1);

        opn = "slt";

        break;

    case OPC_SLTU:

        gen_op_ltu(t0, t1);

        opn = "sltu";

        break;

    case OPC_AND:

        tcg_gen_and_tl(t0, t0, t1);

        opn = "and";

        break;

    case OPC_NOR:

        tcg_gen_or_tl(t0, t0, t1);

        tcg_gen_not_tl(t0, t0);

        opn = "nor";

        break;

    case OPC_OR:

        tcg_gen_or_tl(t0, t0, t1);

        opn = "or";

        break;

    case OPC_XOR:

        tcg_gen_xor_tl(t0, t0, t1);

        opn = "xor";

        break;

    case OPC_MUL:

        tcg_gen_ext32s_tl(t0, t0);

        tcg_gen_ext32s_tl(t1, t1);

        tcg_gen_mul_tl(t0, t0, t1);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "mul";

        break;

    case OPC_MOVN:

        {

            int l1 = gen_new_label();



            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            gen_store_gpr(t0, rd);

            gen_set_label(l1);

        }

        opn = "movn";

        goto print;

    case OPC_MOVZ:

        {

            int l1 = gen_new_label();



            tcg_gen_brcondi_tl(TCG_COND_NE, t1, 0, l1);

            gen_store_gpr(t0, rd);

            gen_set_label(l1);

        }

        opn = "movz";

        goto print;

    case OPC_SLLV:

        tcg_gen_ext32u_tl(t0, t0);

        tcg_gen_ext32u_tl(t1, t1);

        tcg_gen_andi_tl(t0, t0, 0x1f);

        tcg_gen_shl_tl(t0, t1, t0);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "sllv";

        break;

    case OPC_SRAV:

        tcg_gen_ext32s_tl(t1, t1);

        tcg_gen_andi_tl(t0, t0, 0x1f);

        tcg_gen_sar_tl(t0, t1, t0);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "srav";

        break;

    case OPC_SRLV:

        switch ((ctx->opcode >> 6) & 0x1f) {

        case 0:

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_andi_tl(t0, t0, 0x1f);

            tcg_gen_shr_tl(t0, t1, t0);

            tcg_gen_ext32s_tl(t0, t0);

            opn = "srlv";

            break;

        case 1:

            /* rotrv is decoded as srlv on non-R2 CPUs */

            if (env->insn_flags & ISA_MIPS32R2) {

                int l1 = gen_new_label();

                int l2 = gen_new_label();



                tcg_gen_andi_tl(t0, t0, 0x1f);

                tcg_gen_brcondi_tl(TCG_COND_EQ, t0, 0, l1);

                {

                    TCGv r_tmp1 = tcg_temp_new(TCG_TYPE_I32);

                    TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_I32);



                    tcg_gen_trunc_tl_i32(r_tmp1, t0);

                    tcg_gen_trunc_tl_i32(r_tmp2, t1);

                    tcg_gen_rotr_i32(r_tmp1, r_tmp1, r_tmp2);

                    tcg_temp_free(r_tmp1);

                    tcg_temp_free(r_tmp2);

                    tcg_gen_br(l2);

                }

                gen_set_label(l1);

                tcg_gen_mov_tl(t0, t1);

                gen_set_label(l2);

                opn = "rotrv";

            } else {

                tcg_gen_ext32u_tl(t1, t1);

                tcg_gen_andi_tl(t0, t0, 0x1f);

                tcg_gen_shr_tl(t0, t1, t0);

                tcg_gen_ext32s_tl(t0, t0);

                opn = "srlv";

            }

            break;

        default:

            MIPS_INVAL("invalid srlv flag");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

#if defined(TARGET_MIPS64)

    case OPC_DSLLV:

        tcg_gen_andi_tl(t0, t0, 0x3f);

        tcg_gen_shl_tl(t0, t1, t0);

        opn = "dsllv";

        break;

    case OPC_DSRAV:

        tcg_gen_andi_tl(t0, t0, 0x3f);

        tcg_gen_sar_tl(t0, t1, t0);

        opn = "dsrav";

        break;

    case OPC_DSRLV:

        switch ((ctx->opcode >> 6) & 0x1f) {

        case 0:

            tcg_gen_andi_tl(t0, t0, 0x3f);

            tcg_gen_shr_tl(t0, t1, t0);

            opn = "dsrlv";

            break;

        case 1:

            /* drotrv is decoded as dsrlv on non-R2 CPUs */

            if (env->insn_flags & ISA_MIPS32R2) {

                int l1 = gen_new_label();

                int l2 = gen_new_label();



                tcg_gen_andi_tl(t0, t0, 0x3f);

                tcg_gen_brcondi_tl(TCG_COND_EQ, t0, 0, l1);

                {

                    tcg_gen_rotr_tl(t0, t1, t0);

                    tcg_gen_br(l2);

                }

                gen_set_label(l1);

                tcg_gen_mov_tl(t0, t1);

                gen_set_label(l2);

                opn = "drotrv";

            } else {

                tcg_gen_andi_tl(t0, t0, 0x3f);

                tcg_gen_shr_tl(t0, t1, t0);

                opn = "dsrlv";

            }

            break;

        default:

            MIPS_INVAL("invalid dsrlv flag");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

#endif

    default:

        MIPS_INVAL(opn);

        generate_exception(ctx, EXCP_RI);

        goto out;

    }

    gen_store_gpr(t0, rd);

 print:

    MIPS_DEBUG("%s %s, %s, %s", opn, regnames[rd], regnames[rs], regnames[rt]);

 out:

    tcg_temp_free(t0);

    tcg_temp_free(t1);

}

static int32_t bmdma_prepare_buf(IDEDMA *dma, int32_t limit)

{

    BMDMAState *bm = DO_UPCAST(BMDMAState, dma, dma);

    IDEState *s = bmdma_active_if(bm);

    PCIDevice *pci_dev = PCI_DEVICE(bm->pci_dev);

    struct {

        uint32_t addr;

        uint32_t size;

    } prd;

    int l, len;



    pci_dma_sglist_init(&s->sg, pci_dev,

                        s->nsector / (BMDMA_PAGE_SIZE / 512) + 1);

    s->io_buffer_size = 0;

    for(;;) {

        if (bm->cur_prd_len == 0) {

            /* end of table (with a fail safe of one page) */

            if (bm->cur_prd_last ||

                (bm->cur_addr - bm->addr) >= BMDMA_PAGE_SIZE) {

                return s->sg.size;

            }

            pci_dma_read(pci_dev, bm->cur_addr, &prd, 8);

            bm->cur_addr += 8;

            prd.addr = le32_to_cpu(prd.addr);

            prd.size = le32_to_cpu(prd.size);

            len = prd.size & 0xfffe;

            if (len == 0)

                len = 0x10000;

            bm->cur_prd_len = len;

            bm->cur_prd_addr = prd.addr;

            bm->cur_prd_last = (prd.size & 0x80000000);

        }

        l = bm->cur_prd_len;

        if (l > 0) {

            uint64_t sg_len;



            /* Don't add extra bytes to the SGList; consume any remaining

             * PRDs from the guest, but ignore them. */

            sg_len = MIN(limit - s->sg.size, bm->cur_prd_len);

            if (sg_len) {

                qemu_sglist_add(&s->sg, bm->cur_prd_addr, sg_len);

            }



            /* Note: We limit the max transfer to be 2GiB.

             * This should accommodate the largest ATA transaction

             * for LBA48 (65,536 sectors) and 32K sector sizes. */

            if (s->sg.size > INT32_MAX) {

                error_report("IDE: sglist describes more than 2GiB.");

                break;

            }

            bm->cur_prd_addr += l;

            bm->cur_prd_len -= l;

            s->io_buffer_size += l;

        }

    }



    qemu_sglist_destroy(&s->sg);

    s->io_buffer_size = 0;

    return -1;

}

