static uint32_t parse_peak(const uint8_t *peak)

{

    int64_t val = 0;

    int64_t scale = 1;



    if (!peak)

        return 0;



    peak += strspn(peak, " \t");



    if (peak[0] == '1' && peak[1] == '.')

        return UINT32_MAX;

    else if (!(peak[0] == '0' && peak[1] == '.'))

        return 0;



    peak += 2;



    while (av_isdigit(*peak)) {

        int digit = *peak - '0';



        if (scale > INT64_MAX / 10)

            break;



        val    = 10 * val + digit;

        scale *= 10;



        peak++;

    }



    return av_rescale(val, UINT32_MAX, scale);

}

int match_ext(const char *filename, const char *extensions)

{

    const char *ext, *p;

    char ext1[32], *q;



    if(!filename)

        return 0;



    ext = strrchr(filename, '.');

    if (ext) {

        ext++;

        p = extensions;

        for(;;) {

            q = ext1;

            while (*p != '\0' && *p != ',') 

                *q++ = *p++;

            *q = '\0';

            if (!strcasecmp(ext1, ext)) 

                return 1;

            if (*p == '\0') 

                break;

            p++;

        }

    }

    return 0;

}

static int32_t parse_gain(const char *gain)

{

    char *fraction;

    int  scale = 10000;

    int32_t mb = 0;

    int db;



    if (!gain)

        return INT32_MIN;



    gain += strspn(gain, " \t");



    db = strtol(gain, &fraction, 0);

    if (*fraction++ == '.') {

        while (av_isdigit(*fraction) && scale) {

            mb += scale * (*fraction - '0');

            scale /= 10;

            fraction++;

        }

    }



    if (abs(db) > (INT32_MAX - mb) / 100000)

        return INT32_MIN;



    return db * 100000 + FFSIGN(db) * mb;

}

static int match_format(const char *name, const char *names)

{

    const char *p;

    int len, namelen;



    if (!name || !names)

        return 0;



    namelen = strlen(name);

    while ((p = strchr(names, ','))) {

        len = FFMAX(p - names, namelen);

        if (!av_strncasecmp(name, names, len))

            return 1;

        names = p + 1;

    }

    return !av_strcasecmp(name, names);

}

