static void handle_mousemotion(SDL_Event *ev)

{

    int max_x, max_y;

    struct sdl2_console *scon = get_scon_from_window(ev->key.windowID);



    if (qemu_input_is_absolute() || absolute_enabled) {

        int scr_w, scr_h;

        SDL_GetWindowSize(scon->real_window, &scr_w, &scr_h);

        max_x = scr_w - 1;

        max_y = scr_h - 1;

        if (gui_grab && (ev->motion.x == 0 || ev->motion.y == 0 ||

                         ev->motion.x == max_x || ev->motion.y == max_y)) {

            sdl_grab_end(scon);

        }

        if (!gui_grab &&

            (ev->motion.x > 0 && ev->motion.x < max_x &&

             ev->motion.y > 0 && ev->motion.y < max_y)) {

            sdl_grab_start(scon);

        }

    }

    if (gui_grab || qemu_input_is_absolute() || absolute_enabled) {

        sdl_send_mouse_event(scon, ev->motion.xrel, ev->motion.yrel,

                             ev->motion.x, ev->motion.y, ev->motion.state);

    }

}

static void hmp_mouse_move(Monitor *mon, const QDict *qdict)

{

    int dx, dy, dz, button;

    const char *dx_str = qdict_get_str(qdict, "dx_str");

    const char *dy_str = qdict_get_str(qdict, "dy_str");

    const char *dz_str = qdict_get_try_str(qdict, "dz_str");



    dx = strtol(dx_str, NULL, 0);

    dy = strtol(dy_str, NULL, 0);

    qemu_input_queue_rel(NULL, INPUT_AXIS_X, dx);

    qemu_input_queue_rel(NULL, INPUT_AXIS_Y, dy);



    if (dz_str) {

        dz = strtol(dz_str, NULL, 0);

        if (dz != 0) {

            button = (dz > 0) ? INPUT_BUTTON_WHEEL_UP : INPUT_BUTTON_WHEEL_DOWN;

            qemu_input_queue_btn(NULL, button, true);

            qemu_input_event_sync();

            qemu_input_queue_btn(NULL, button, false);

        }

    }

    qemu_input_event_sync();

}

static QVirtioPCIDevice *virtio_blk_pci_init(QPCIBus *bus, int slot)

{

    QVirtioPCIDevice *dev;



    dev = qvirtio_pci_device_find(bus, VIRTIO_ID_BLOCK);

    g_assert(dev != NULL);

    g_assert_cmphex(dev->vdev.device_type, ==, VIRTIO_ID_BLOCK);

    g_assert_cmphex(dev->pdev->devfn, ==, ((slot << 3) | PCI_FN));



    qvirtio_pci_device_enable(dev);

    qvirtio_reset(&dev->vdev);

    qvirtio_set_acknowledge(&dev->vdev);

    qvirtio_set_driver(&dev->vdev);



    return dev;

}

static void pci_indirect(void)

{

    QVirtioPCIDevice *dev;

    QPCIBus *bus;

    QVirtQueuePCI *vqpci;

    QGuestAllocator *alloc;

    QVirtioBlkReq req;

    QVRingIndirectDesc *indirect;

    void *addr;

    uint64_t req_addr;

    uint64_t capacity;

    uint32_t features;

    uint32_t free_head;

    uint8_t status;

    char *data;



    bus = test_start();



    dev = virtio_blk_init(bus);



    /* MSI-X is not enabled */

    addr = dev->addr + QVIRTIO_DEVICE_SPECIFIC_NO_MSIX;



    capacity = qvirtio_config_readq(&qvirtio_pci, &dev->vdev, addr);

    g_assert_cmpint(capacity, ==, TEST_IMAGE_SIZE / 512);



    features = qvirtio_get_features(&qvirtio_pci, &dev->vdev);

    g_assert_cmphex(features & QVIRTIO_F_RING_INDIRECT_DESC, !=, 0);

    features = features & ~(QVIRTIO_F_BAD_FEATURE | QVIRTIO_F_RING_EVENT_IDX |

                                                            QVIRTIO_BLK_F_SCSI);

    qvirtio_set_features(&qvirtio_pci, &dev->vdev, features);



    alloc = pc_alloc_init();

    vqpci = (QVirtQueuePCI *)qvirtqueue_setup(&qvirtio_pci, &dev->vdev,

                                                                    alloc, 0);

    qvirtio_set_driver_ok(&qvirtio_pci, &dev->vdev);



    /* Write request */

    req.type = QVIRTIO_BLK_T_OUT;

    req.ioprio = 1;

    req.sector = 0;

    req.data = g_malloc0(512);

    strcpy(req.data, "TEST");



    req_addr = virtio_blk_request(alloc, &req, 512);



    g_free(req.data);



    indirect = qvring_indirect_desc_setup(&dev->vdev, alloc, 2);

    qvring_indirect_desc_add(indirect, req_addr, 528, false);

    qvring_indirect_desc_add(indirect, req_addr + 528, 1, true);

    free_head = qvirtqueue_add_indirect(&vqpci->vq, indirect);

    qvirtqueue_kick(&qvirtio_pci, &dev->vdev, &vqpci->vq, free_head);



    g_assert(qvirtio_wait_queue_isr(&qvirtio_pci, &dev->vdev, &vqpci->vq,

                                                        QVIRTIO_BLK_TIMEOUT));

    status = readb(req_addr + 528);

    g_assert_cmpint(status, ==, 0);



    g_free(indirect);

    guest_free(alloc, req_addr);



    /* Read request */

    req.type = QVIRTIO_BLK_T_IN;

    req.ioprio = 1;

    req.sector = 0;

    req.data = g_malloc0(512);

    strcpy(req.data, "TEST");



    req_addr = virtio_blk_request(alloc, &req, 512);



    g_free(req.data);



    indirect = qvring_indirect_desc_setup(&dev->vdev, alloc, 2);

    qvring_indirect_desc_add(indirect, req_addr, 16, false);

    qvring_indirect_desc_add(indirect, req_addr + 16, 513, true);

    free_head = qvirtqueue_add_indirect(&vqpci->vq, indirect);

    qvirtqueue_kick(&qvirtio_pci, &dev->vdev, &vqpci->vq, free_head);



    g_assert(qvirtio_wait_queue_isr(&qvirtio_pci, &dev->vdev, &vqpci->vq,

                                                        QVIRTIO_BLK_TIMEOUT));

    status = readb(req_addr + 528);

    g_assert_cmpint(status, ==, 0);



    data = g_malloc0(512);

    memread(req_addr + 16, data, 512);

    g_assert_cmpstr(data, ==, "TEST");

    g_free(data);



    g_free(indirect);

    guest_free(alloc, req_addr);



    /* End test */

    guest_free(alloc, vqpci->vq.desc);

    qvirtio_pci_device_disable(dev);

    g_free(dev);

    test_end();

}

