int virtio_scsi_common_exit(VirtIOSCSICommon *vs)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(vs);



    g_free(vs->cmd_vqs);

    virtio_cleanup(vdev);

    return 0;

}

static void control_out(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtQueueElement elem;

    VirtIOSerial *vser;



    vser = DO_UPCAST(VirtIOSerial, vdev, vdev);



    while (virtqueue_pop(vq, &elem)) {

        handle_control_message(vser, elem.out_sg[0].iov_base);

        virtqueue_push(vq, &elem, elem.out_sg[0].iov_len);

    }

    virtio_notify(vdev, vq);

}

static void handle_output(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOSerial *vser;

    VirtIOSerialPort *port;

    VirtIOSerialPortInfo *info;



    vser = DO_UPCAST(VirtIOSerial, vdev, vdev);

    port = find_port_by_vq(vser, vq);

    info = port ? DO_UPCAST(VirtIOSerialPortInfo, qdev, port->dev.info) : NULL;



    if (!port || !port->host_connected || !info->have_data) {

        discard_vq_data(vq, vdev);

        return;

    }



    if (!port->throttled) {

        do_flush_queued_data(port, vq, vdev);

        return;

    }

}

static int virtio_rng_load(QEMUFile *f, void *opaque, int version_id)

{

    VirtIORNG *vrng = opaque;

    VirtIODevice *vdev = VIRTIO_DEVICE(vrng);



    if (version_id != 1) {

        return -EINVAL;

    }

    virtio_load(vdev, f, version_id);



    /* We may have an element ready but couldn't process it due to a quota

     * limit.  Make sure to try again after live migration when the quota may

     * have been reset.

     */

    virtio_rng_process(vrng);



    return 0;

}

static int poll_filters(void)

{

    AVFilterBufferRef *picref;

    AVFrame *filtered_frame = NULL;

    int i, ret, ret_all;

    unsigned nb_success, nb_eof;

    int64_t frame_pts;



    while (1) {

        /* Reap all buffers present in the buffer sinks */

        for (i = 0; i < nb_output_streams; i++) {

            OutputStream *ost = output_streams[i];

            OutputFile    *of = output_files[ost->file_index];

            int ret = 0;



            if (!ost->filter || ost->is_past_recording_time)

                continue;



            if (!ost->filtered_frame && !(ost->filtered_frame = avcodec_alloc_frame())) {

                return AVERROR(ENOMEM);

            } else

                avcodec_get_frame_defaults(ost->filtered_frame);

            filtered_frame = ost->filtered_frame;



            while (1) {

                AVRational ist_pts_tb = ost->filter->filter->inputs[0]->time_base;

                if (ost->enc->type == AVMEDIA_TYPE_AUDIO &&

                    !(ost->enc->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE))

                    ret = av_buffersink_read_samples(ost->filter->filter, &picref,

                                                    ost->st->codec->frame_size);

                else

#ifdef SINKA

                    ret = av_buffersink_read(ost->filter->filter, &picref);

#else

                    ret = av_buffersink_get_buffer_ref(ost->filter->filter, &picref,

                                                       AV_BUFFERSINK_FLAG_NO_REQUEST);

#endif

                if (ret < 0) {

                    if (ret != AVERROR(EAGAIN) && ret != AVERROR_EOF) {

                        char buf[256];

                        av_strerror(ret, buf, sizeof(buf));

                        av_log(NULL, AV_LOG_WARNING,

                               "Error in av_buffersink_get_buffer_ref(): %s\n", buf);

                    }

                    break;

                }


                if (ost->enc->type == AVMEDIA_TYPE_VIDEO)

                    filtered_frame->pts = frame_pts = av_rescale_q(picref->pts, ist_pts_tb, AV_TIME_BASE_Q);

                else if (picref->pts != AV_NOPTS_VALUE)

                    filtered_frame->pts = frame_pts = av_rescale_q(picref->pts,

                                                    ost->filter->filter->inputs[0]->time_base,

                                                    ost->st->codec->time_base) -

                                        av_rescale_q(of->start_time,

                                                    AV_TIME_BASE_Q,

                                                    ost->st->codec->time_base);

                //if (ost->source_index >= 0)

                //    *filtered_frame= *input_streams[ost->source_index]->decoded_frame; //for me_threshold



                if (of->start_time && filtered_frame->pts < of->start_time) {

                    avfilter_unref_buffer(picref);

                    continue;

                }



                switch (ost->filter->filter->inputs[0]->type) {

                case AVMEDIA_TYPE_VIDEO:

                    avfilter_fill_frame_from_video_buffer_ref(filtered_frame, picref);

                    filtered_frame->pts = frame_pts;

                    if (!ost->frame_aspect_ratio)

                        ost->st->codec->sample_aspect_ratio = picref->video->sample_aspect_ratio;



                    do_video_out(of->ctx, ost, filtered_frame,

                                 same_quant ? ost->last_quality :

                                              ost->st->codec->global_quality);

                    break;

                case AVMEDIA_TYPE_AUDIO:

                    avfilter_copy_buf_props(filtered_frame, picref);

                    filtered_frame->pts = frame_pts;

                    do_audio_out(of->ctx, ost, filtered_frame);

                    break;

                default:

                    // TODO support subtitle filters

                    av_assert0(0);

                }



                avfilter_unref_buffer(picref);

            }

        }

        /* Request frames through all the graphs */

        ret_all = nb_success = nb_eof = 0;

        for (i = 0; i < nb_filtergraphs; i++) {

            ret = avfilter_graph_request_oldest(filtergraphs[i]->graph);

            if (!ret) {

                nb_success++;

            } else if (ret == AVERROR_EOF) {

                nb_eof++;

            } else if (ret != AVERROR(EAGAIN)) {

                char buf[256];

                av_strerror(ret, buf, sizeof(buf));

                av_log(NULL, AV_LOG_WARNING,

                       "Error in request_frame(): %s\n", buf);

                ret_all = ret;

            }

        }

        if (!nb_success)

            break;

        /* Try again if anything succeeded */

    }

    return nb_eof == nb_filtergraphs ? AVERROR_EOF : ret_all;

}

static int init_output_stream_streamcopy(OutputStream *ost)

{

    OutputFile *of = output_files[ost->file_index];

    InputStream *ist = get_input_stream(ost);

    AVCodecParameters *par_dst = ost->st->codecpar;

    AVCodecParameters *par_src = ost->ref_par;

    AVRational sar;

    int i, ret;

    uint32_t codec_tag = par_dst->codec_tag;



    av_assert0(ist && !ost->filter);



    avcodec_parameters_to_context(ost->enc_ctx, ist->st->codecpar);

    ret = av_opt_set_dict(ost->enc_ctx, &ost->encoder_opts);

    if (ret < 0) {

        av_log(NULL, AV_LOG_FATAL,

               "Error setting up codec context options.\n");

        return ret;

    }

    avcodec_parameters_from_context(par_src, ost->enc_ctx);



    if (!codec_tag) {

        unsigned int codec_tag_tmp;

        if (!of->ctx->oformat->codec_tag ||

            av_codec_get_id (of->ctx->oformat->codec_tag, par_src->codec_tag) == par_src->codec_id ||

            !av_codec_get_tag2(of->ctx->oformat->codec_tag, par_src->codec_id, &codec_tag_tmp))

            codec_tag = par_src->codec_tag;

    }



    ret = avcodec_parameters_copy(par_dst, par_src);

    if (ret < 0)

        return ret;



    par_dst->codec_tag = codec_tag;



    if (!ost->frame_rate.num)

        ost->frame_rate = ist->framerate;

    ost->st->avg_frame_rate = ost->frame_rate;



    ret = avformat_transfer_internal_stream_timing_info(of->ctx->oformat, ost->st, ist->st, copy_tb);

    if (ret < 0)

        return ret;



    // copy timebase while removing common factors

    ost->st->time_base = av_add_q(av_stream_get_codec_timebase(ost->st), (AVRational){0, 1});



    // copy disposition

    ost->st->disposition = ist->st->disposition;



    if (ist->st->nb_side_data) {

        ost->st->side_data = av_realloc_array(NULL, ist->st->nb_side_data,

                                              sizeof(*ist->st->side_data));

        if (!ost->st->side_data)

            return AVERROR(ENOMEM);



        ost->st->nb_side_data = 0;

        for (i = 0; i < ist->st->nb_side_data; i++) {

            const AVPacketSideData *sd_src = &ist->st->side_data[i];

            AVPacketSideData *sd_dst = &ost->st->side_data[ost->st->nb_side_data];



            if (ost->rotate_overridden && sd_src->type == AV_PKT_DATA_DISPLAYMATRIX)

                continue;



            sd_dst->data = av_malloc(sd_src->size);

            if (!sd_dst->data)

                return AVERROR(ENOMEM);

            memcpy(sd_dst->data, sd_src->data, sd_src->size);

            sd_dst->size = sd_src->size;

            sd_dst->type = sd_src->type;

            ost->st->nb_side_data++;

        }

    }



    ost->parser = av_parser_init(par_dst->codec_id);

    ost->parser_avctx = avcodec_alloc_context3(NULL);

    if (!ost->parser_avctx)

        return AVERROR(ENOMEM);



    switch (par_dst->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        if (audio_volume != 256) {

            av_log(NULL, AV_LOG_FATAL, "-acodec copy and -vol are incompatible (frames are not decoded)\n");

            exit_program(1);

        }

        if((par_dst->block_align == 1 || par_dst->block_align == 1152 || par_dst->block_align == 576) && par_dst->codec_id == AV_CODEC_ID_MP3)

            par_dst->block_align= 0;

        if(par_dst->codec_id == AV_CODEC_ID_AC3)

            par_dst->block_align= 0;

        break;

    case AVMEDIA_TYPE_VIDEO:

        if (ost->frame_aspect_ratio.num) { // overridden by the -aspect cli option

            sar =

                av_mul_q(ost->frame_aspect_ratio,

                         (AVRational){ par_dst->height, par_dst->width });

            av_log(NULL, AV_LOG_WARNING, "Overriding aspect ratio "

                   "with stream copy may produce invalid files\n");

            }

        else if (ist->st->sample_aspect_ratio.num)

            sar = ist->st->sample_aspect_ratio;

        else

            sar = par_src->sample_aspect_ratio;

        ost->st->sample_aspect_ratio = par_dst->sample_aspect_ratio = sar;

        ost->st->avg_frame_rate = ist->st->avg_frame_rate;

        ost->st->r_frame_rate = ist->st->r_frame_rate;

        break;

    }



    return 0;

}

static int poll_filters(void)

{

    AVFilterBufferRef *picref;

    AVFrame *filtered_frame = NULL;

    int i, frame_size;



    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];

        OutputFile    *of = output_files[ost->file_index];

        int ret = 0;



        if (!ost->filter)

            continue;



        if (!ost->filtered_frame && !(ost->filtered_frame = avcodec_alloc_frame())) {

            return AVERROR(ENOMEM);

        } else

            avcodec_get_frame_defaults(ost->filtered_frame);

        filtered_frame = ost->filtered_frame;



        while (ret >= 0 && !ost->is_past_recording_time) {

            if (ost->enc->type == AVMEDIA_TYPE_AUDIO &&

                !(ost->enc->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE))

                ret = av_buffersink_read_samples(ost->filter->filter, &picref,

                                                 ost->st->codec->frame_size);

            else

                ret = av_buffersink_read(ost->filter->filter, &picref);



            if (ret < 0)

                break;



            avfilter_copy_buf_props(filtered_frame, picref);

            if (picref->pts != AV_NOPTS_VALUE)

                filtered_frame->pts = av_rescale_q(picref->pts,

                                                   ost->filter->filter->inputs[0]->time_base,

                                                   ost->st->codec->time_base) -

                                      av_rescale_q(of->start_time,

                                                   AV_TIME_BASE_Q,

                                                   ost->st->codec->time_base);



            if (of->start_time && filtered_frame->pts < of->start_time) {

                avfilter_unref_buffer(picref);

                continue;

            }



            switch (ost->filter->filter->inputs[0]->type) {

            case AVMEDIA_TYPE_VIDEO:

                if (!ost->frame_aspect_ratio)

                    ost->st->codec->sample_aspect_ratio = picref->video->pixel_aspect;



                do_video_out(of->ctx, ost, filtered_frame, &frame_size,

                             same_quant ? ost->last_quality :

                                          ost->st->codec->global_quality);

                if (vstats_filename && frame_size)

                    do_video_stats(of->ctx, ost, frame_size);

                break;

            case AVMEDIA_TYPE_AUDIO:

                do_audio_out(of->ctx, ost, filtered_frame);

                break;

            default:

                // TODO support subtitle filters

                av_assert0(0);

            }



            avfilter_unref_buffer(picref);

        }

    }

    return 0;

}

static void do_streamcopy(InputStream *ist, OutputStream *ost, const AVPacket *pkt)

{

    OutputFile *of = output_files[ost->file_index];

    int64_t ost_tb_start_time = av_rescale_q(of->start_time, AV_TIME_BASE_Q, ost->st->time_base);

    AVPacket opkt;



    av_init_packet(&opkt);



    if ((!ost->frame_number && !(pkt->flags & AV_PKT_FLAG_KEY)) &&

        !ost->copy_initial_nonkeyframes)

        return;



    if (of->recording_time != INT64_MAX &&

        ist->last_dts >= of->recording_time + of->start_time) {

        ost->is_past_recording_time = 1;

        return;

    }



    /* force the input stream PTS */

    if (ost->st->codec->codec_type == AVMEDIA_TYPE_AUDIO)

        audio_size += pkt->size;

    else if (ost->st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        video_size += pkt->size;

        ost->sync_opts++;

    }



    if (pkt->pts != AV_NOPTS_VALUE)

        opkt.pts = av_rescale_q(pkt->pts, ist->st->time_base, ost->st->time_base) - ost_tb_start_time;

    else

        opkt.pts = AV_NOPTS_VALUE;



    if (pkt->dts == AV_NOPTS_VALUE)

        opkt.dts = av_rescale_q(ist->last_dts, AV_TIME_BASE_Q, ost->st->time_base);

    else

        opkt.dts = av_rescale_q(pkt->dts, ist->st->time_base, ost->st->time_base);

    opkt.dts -= ost_tb_start_time;



    opkt.duration = av_rescale_q(pkt->duration, ist->st->time_base, ost->st->time_base);

    opkt.flags    = pkt->flags;



    // FIXME remove the following 2 lines they shall be replaced by the bitstream filters

    if (  ost->st->codec->codec_id != AV_CODEC_ID_H264

       && ost->st->codec->codec_id != AV_CODEC_ID_MPEG1VIDEO

       && ost->st->codec->codec_id != AV_CODEC_ID_MPEG2VIDEO

       && ost->st->codec->codec_id != AV_CODEC_ID_VC1

       ) {

        if (av_parser_change(ist->st->parser, ost->st->codec, &opkt.data, &opkt.size, pkt->data, pkt->size, pkt->flags & AV_PKT_FLAG_KEY))

            opkt.destruct = av_destruct_packet;

    } else {

        opkt.data = pkt->data;

        opkt.size = pkt->size;

    }



    write_frame(of->ctx, &opkt, ost);

    ost->st->codec->frame_number++;

    av_free_packet(&opkt);

}

