static uint64_t imx_serial_read(void *opaque, hwaddr offset,

                                unsigned size)

{

    IMXSerialState *s = (IMXSerialState *)opaque;

    uint32_t c;



    DPRINTF("read(offset=%x)\n", offset >> 2);

    switch (offset >> 2) {

    case 0x0: /* URXD */

        c = s->readbuff;

        if (!(s->uts1 & UTS1_RXEMPTY)) {

            /* Character is valid */

            c |= URXD_CHARRDY;

            s->usr1 &= ~USR1_RRDY;

            s->usr2 &= ~USR2_RDR;

            s->uts1 |= UTS1_RXEMPTY;

            imx_update(s);

            qemu_chr_accept_input(s->chr);

        }

        return c;



    case 0x20: /* UCR1 */

        return s->ucr1;



    case 0x21: /* UCR2 */

        return s->ucr2;



    case 0x25: /* USR1 */

        return s->usr1;



    case 0x26: /* USR2 */

        return s->usr2;



    case 0x2A: /* BRM Modulator */

        return s->ubmr;



    case 0x2B: /* Baud Rate Count */

        return s->ubrc;



    case 0x2d: /* Test register */

        return s->uts1;



    case 0x24: /* UFCR */

        return s->ufcr;



    case 0x2c:

        return s->onems;



    case 0x22: /* UCR3 */

        return s->ucr3;



    case 0x23: /* UCR4 */

    case 0x29: /* BRM Incremental */

        return 0x0; /* TODO */



    default:

        IPRINTF("%s: bad offset: 0x%x\n", __func__, (int)offset);

        return 0;

    }

}

static uint64_t strongarm_gpio_read(void *opaque, hwaddr offset,

                                    unsigned size)

{

    StrongARMGPIOInfo *s = opaque;



    switch (offset) {

    case GPDR:        /* GPIO Pin-Direction registers */

        return s->dir;



    case GPSR:        /* GPIO Pin-Output Set registers */

        DPRINTF("%s: Read from a write-only register 0x" TARGET_FMT_plx "\n",

                        __func__, offset);

        return s->gpsr;    /* Return last written value.  */



    case GPCR:        /* GPIO Pin-Output Clear registers */

        DPRINTF("%s: Read from a write-only register 0x" TARGET_FMT_plx "\n",

                        __func__, offset);

        return 31337;        /* Specified as unpredictable in the docs.  */



    case GRER:        /* GPIO Rising-Edge Detect Enable registers */

        return s->rising;



    case GFER:        /* GPIO Falling-Edge Detect Enable registers */

        return s->falling;



    case GAFR:        /* GPIO Alternate Function registers */

        return s->gafr;



    case GPLR:        /* GPIO Pin-Level registers */

        return (s->olevel & s->dir) |

               (s->ilevel & ~s->dir);



    case GEDR:        /* GPIO Edge Detect Status registers */

        return s->status;



    default:

        printf("%s: Bad offset 0x" TARGET_FMT_plx "\n", __func__, offset);

    }



    return 0;

}

static uint64_t imx_timerp_read(void *opaque, target_phys_addr_t offset,

                                unsigned size)

{

    IMXTimerPState *s = (IMXTimerPState *)opaque;



    DPRINTF("p-read(offset=%x)", offset >> 2);

    switch (offset >> 2) {

    case 0: /* Control Register */

        DPRINTF("cr %x\n", s->cr);

        return s->cr;



    case 1: /* Status Register */

        DPRINTF("int_level %x\n", s->int_level);

        return s->int_level;



    case 2: /* LR - ticks*/

        DPRINTF("lr %x\n", s->lr);

        return s->lr;



    case 3: /* CMP */

        DPRINTF("cmp %x\n", s->cmp);

        return s->cmp;



    case 4: /* CNT */

        return ptimer_get_count(s->timer);

    }

    IPRINTF("imx_timerp_read: Bad offset %x\n",

            (int)offset >> 2);

    return 0;

}

static uint64_t imx_ccm_read(void *opaque, target_phys_addr_t offset,

                                unsigned size)

{

    IMXCCMState *s = (IMXCCMState *)opaque;



    DPRINTF("read(offset=%x)", offset >> 2);

    switch (offset >> 2) {

    case 0: /* CCMR */

        DPRINTF(" ccmr = 0x%x\n", s->ccmr);

        return s->ccmr;

    case 1:

        DPRINTF(" pdr0 = 0x%x\n", s->pdr0);

        return s->pdr0;

    case 2:

        DPRINTF(" pdr1 = 0x%x\n", s->pdr1);

        return s->pdr1;

    case 4:

        DPRINTF(" mpctl = 0x%x\n", s->mpctl);

        return s->mpctl;

    case 6:

        DPRINTF(" spctl = 0x%x\n", s->spctl);

        return s->spctl;

    case 8:

        DPRINTF(" cgr0 = 0x%x\n", s->cgr[0]);

        return s->cgr[0];

    case 9:

        DPRINTF(" cgr1 = 0x%x\n", s->cgr[1]);

        return s->cgr[1];

    case 10:

        DPRINTF(" cgr2 = 0x%x\n", s->cgr[2]);

        return s->cgr[2];

    case 18: /* LTR1 */

        return 0x00004040;

    case 23:

        DPRINTF(" pcmr0 = 0x%x\n", s->pmcr0);

        return s->pmcr0;

    }

    DPRINTF(" return 0\n");

    return 0;

}

static int qemu_rbd_open(BlockDriverState *bs, QDict *options, int flags,

                         Error **errp)

{

    BDRVRBDState *s = bs->opaque;

    char pool[RBD_MAX_POOL_NAME_SIZE];

    char snap_buf[RBD_MAX_SNAP_NAME_SIZE];

    char conf[RBD_MAX_CONF_SIZE];

    char clientname_buf[RBD_MAX_CONF_SIZE];

    char *clientname;

    QemuOpts *opts;

    Error *local_err = NULL;

    const char *filename;

    int r;



    opts = qemu_opts_create(&runtime_opts, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        qemu_opts_del(opts);

        return -EINVAL;

    }



    filename = qemu_opt_get(opts, "filename");



    if (qemu_rbd_parsename(filename, pool, sizeof(pool),

                           snap_buf, sizeof(snap_buf),

                           s->name, sizeof(s->name),

                           conf, sizeof(conf), errp) < 0) {

        r = -EINVAL;

        goto failed_opts;

    }



    clientname = qemu_rbd_parse_clientname(conf, clientname_buf);

    r = rados_create(&s->cluster, clientname);

    if (r < 0) {

        error_setg(&local_err, "error initializing");

        goto failed_opts;

    }



    s->snap = NULL;

    if (snap_buf[0] != '\0') {

        s->snap = g_strdup(snap_buf);

    }



    /*

     * Fallback to more conservative semantics if setting cache

     * options fails. Ignore errors from setting rbd_cache because the

     * only possible error is that the option does not exist, and

     * librbd defaults to no caching. If write through caching cannot

     * be set up, fall back to no caching.

     */

    if (flags & BDRV_O_NOCACHE) {

        rados_conf_set(s->cluster, "rbd_cache", "false");

    } else {

        rados_conf_set(s->cluster, "rbd_cache", "true");

    }



    if (strstr(conf, "conf=") == NULL) {

        /* try default location, but ignore failure */

        rados_conf_read_file(s->cluster, NULL);

    }



    if (conf[0] != '\0') {

        r = qemu_rbd_set_conf(s->cluster, conf, errp);

        if (r < 0) {

            goto failed_shutdown;

        }

    }



    r = rados_connect(s->cluster);

    if (r < 0) {

        error_setg(&local_err, "error connecting");

        goto failed_shutdown;

    }



    r = rados_ioctx_create(s->cluster, pool, &s->io_ctx);

    if (r < 0) {

        error_setg(&local_err, "error opening pool %s", pool);

        goto failed_shutdown;

    }



    r = rbd_open(s->io_ctx, s->name, &s->image, s->snap);

    if (r < 0) {

        error_setg(&local_err, "error reading header from %s", s->name);

        goto failed_open;

    }



    bs->read_only = (s->snap != NULL);



    qemu_opts_del(opts);

    return 0;



failed_open:

    rados_ioctx_destroy(s->io_ctx);

failed_shutdown:

    rados_shutdown(s->cluster);

    g_free(s->snap);

failed_opts:

    qemu_opts_del(opts);

    return r;

}

static int quorum_open(BlockDriverState *bs, QDict *options, int flags,

                       Error **errp)

{

    BDRVQuorumState *s = bs->opaque;

    Error *local_err = NULL;

    QemuOpts *opts;

    bool *opened;

    QDict *sub = NULL;

    QList *list = NULL;

    const QListEntry *lentry;

    int i;

    int ret = 0;



    qdict_flatten(options);

    qdict_extract_subqdict(options, &sub, "children.");

    qdict_array_split(sub, &list);



    if (qdict_size(sub)) {

        error_setg(&local_err, "Invalid option children.%s",

                   qdict_first(sub)->key);

        ret = -EINVAL;

        goto exit;

    }



    /* count how many different children are present */

    s->num_children = qlist_size(list);

    if (s->num_children < 2) {

        error_setg(&local_err,

                   "Number of provided children must be greater than 1");

        ret = -EINVAL;

        goto exit;

    }



    opts = qemu_opts_create(&quorum_runtime_opts, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (local_err) {

        ret = -EINVAL;

        goto exit;

    }



    s->threshold = qemu_opt_get_number(opts, QUORUM_OPT_VOTE_THRESHOLD, 0);



    /* and validate it against s->num_children */

    ret = quorum_valid_threshold(s->threshold, s->num_children, &local_err);

    if (ret < 0) {

        goto exit;

    }



    /* is the driver in blkverify mode */

    if (qemu_opt_get_bool(opts, QUORUM_OPT_BLKVERIFY, false) &&

        s->num_children == 2 && s->threshold == 2) {

        s->is_blkverify = true;

    } else if (qemu_opt_get_bool(opts, QUORUM_OPT_BLKVERIFY, false)) {

        fprintf(stderr, "blkverify mode is set by setting blkverify=on "

                "and using two files with vote_threshold=2\n");

    }



    s->rewrite_corrupted = qemu_opt_get_bool(opts, QUORUM_OPT_REWRITE, false);

    if (s->rewrite_corrupted && s->is_blkverify) {

        error_setg(&local_err,

                   "rewrite-corrupted=on cannot be used with blkverify=on");

        ret = -EINVAL;

        goto exit;

    }



    /* allocate the children BlockDriverState array */

    s->bs = g_new0(BlockDriverState *, s->num_children);

    opened = g_new0(bool, s->num_children);



    for (i = 0, lentry = qlist_first(list); lentry;

         lentry = qlist_next(lentry), i++) {

        QDict *d;

        QString *string;



        switch (qobject_type(lentry->value))

        {

            /* List of options */

            case QTYPE_QDICT:

                d = qobject_to_qdict(lentry->value);

                QINCREF(d);

                ret = bdrv_open(&s->bs[i], NULL, NULL, d, flags, NULL,

                                &local_err);

                break;



            /* QMP reference */

            case QTYPE_QSTRING:

                string = qobject_to_qstring(lentry->value);

                ret = bdrv_open(&s->bs[i], NULL, qstring_get_str(string), NULL,

                                flags, NULL, &local_err);

                break;



            default:

                error_setg(&local_err, "Specification of child block device %i "

                           "is invalid", i);

                ret = -EINVAL;

        }



        if (ret < 0) {

            goto close_exit;

        }

        opened[i] = true;

    }



    g_free(opened);

    goto exit;



close_exit:

    /* cleanup on error */

    for (i = 0; i < s->num_children; i++) {

        if (!opened[i]) {

            continue;

        }

        bdrv_unref(s->bs[i]);

    }

    g_free(s->bs);

    g_free(opened);

exit:

    /* propagate error */

    if (local_err) {

        error_propagate(errp, local_err);

    }

    QDECREF(list);

    QDECREF(sub);

    return ret;

}

