    for (i = 0; avpriv_fmt_conversion_table[i].codec_id != AV_CODEC_ID_NONE; i++) {

        if (avpriv_fmt_conversion_table[i].v4l2_fmt == v4l2_fmt &&

            avpriv_fmt_conversion_table[i].codec_id == codec_id) {

            return avpriv_fmt_conversion_table[i].ff_fmt;

        }

    }



    return AV_PIX_FMT_NONE;

}

unsigned int codec_get_tag(const CodecTag *tags, int id)

{

    while (tags->id != 0) {

        if (tags->id == id)

            return tags->tag;

        tags++;

    }

    return 0;

}

static void RENAME(decode_rgb_frame)(FFV1Context *s, uint8_t *src[3], int w, int h, int stride[3])

{

    int x, y, p;

    TYPE *sample[4][2];

    int lbd    = s->avctx->bits_per_raw_sample <= 8;

    int bits   = s->avctx->bits_per_raw_sample > 0 ? s->avctx->bits_per_raw_sample : 8;

    int offset = 1 << bits;



    for (x = 0; x < 4; x++) {

        sample[x][0] = RENAME(s->sample_buffer) +  x * 2      * (w + 6) + 3;

        sample[x][1] = RENAME(s->sample_buffer) + (x * 2 + 1) * (w + 6) + 3;

    }



    s->run_index = 0;



    memset(RENAME(s->sample_buffer), 0, 8 * (w + 6) * sizeof(*RENAME(s->sample_buffer)));



    for (y = 0; y < h; y++) {

        for (p = 0; p < 3 + s->transparency; p++) {

            TYPE *temp = sample[p][0]; // FIXME: try a normal buffer



            sample[p][0] = sample[p][1];

            sample[p][1] = temp;



            sample[p][1][-1]= sample[p][0][0  ];

            sample[p][0][ w]= sample[p][0][w-1];

            if (lbd && s->slice_coding_mode == 0)

                RENAME(decode_line)(s, w, sample[p], (p + 1)/2, 9);

            else

                RENAME(decode_line)(s, w, sample[p], (p + 1)/2, bits + (s->slice_coding_mode != 1));

        }

        for (x = 0; x < w; x++) {

            int g = sample[0][1][x];

            int b = sample[1][1][x];

            int r = sample[2][1][x];

            int a = sample[3][1][x];



            if (s->slice_coding_mode != 1) {

                b -= offset;

                r -= offset;

                g -= (b * s->slice_rct_by_coef + r * s->slice_rct_ry_coef) >> 2;

                b += g;

                r += g;

            }



            if (lbd)

                *((uint32_t*)(src[0] + x*4 + stride[0]*y)) = b + (g<<8) + (r<<16) + (a<<24);

            else if (sizeof(TYPE) == 4) {

                *((uint16_t*)(src[0] + x*2 + stride[0]*y)) = g;

                *((uint16_t*)(src[1] + x*2 + stride[1]*y)) = b;

                *((uint16_t*)(src[2] + x*2 + stride[2]*y)) = r;

            } else {

                *((uint16_t*)(src[0] + x*2 + stride[0]*y)) = b;

                *((uint16_t*)(src[1] + x*2 + stride[1]*y)) = g;

                *((uint16_t*)(src[2] + x*2 + stride[2]*y)) = r;

            }

        }

    }

}

static void fill_picture_parameters(AVCodecContext *avctx,

                                    struct dxva_context *ctx,

                                    const struct MpegEncContext *s,

                                    DXVA_PictureParameters *pp)

{

    const Picture *current_picture = s->current_picture_ptr;

    int is_field = s->picture_structure != PICT_FRAME;



    memset(pp, 0, sizeof(*pp));

    pp->wDecodedPictureIndex         = ff_dxva2_get_surface_index(ctx, &current_picture->f);

    pp->wDeblockedPictureIndex       = 0;

    if (s->pict_type != AV_PICTURE_TYPE_I)

        pp->wForwardRefPictureIndex  = ff_dxva2_get_surface_index(ctx, &s->last_picture.f);

    else

        pp->wForwardRefPictureIndex  = 0xffff;

    if (s->pict_type == AV_PICTURE_TYPE_B)

        pp->wBackwardRefPictureIndex = ff_dxva2_get_surface_index(ctx, &s->next_picture.f);

    else

        pp->wBackwardRefPictureIndex = 0xffff;

    pp->wPicWidthInMBminus1          = s->mb_width  - 1;

    pp->wPicHeightInMBminus1         = (s->mb_height >> is_field) - 1;

    pp->bMacroblockWidthMinus1       = 15;

    pp->bMacroblockHeightMinus1      = 15;

    pp->bBlockWidthMinus1            = 7;

    pp->bBlockHeightMinus1           = 7;

    pp->bBPPminus1                   = 7;

    pp->bPicStructure                = s->picture_structure;

    pp->bSecondField                 = is_field && !s->first_field;

    pp->bPicIntra                    = s->pict_type == AV_PICTURE_TYPE_I;

    pp->bPicBackwardPrediction       = s->pict_type == AV_PICTURE_TYPE_B;

    pp->bBidirectionalAveragingMode  = 0;

    pp->bMVprecisionAndChromaRelation= 0; /* FIXME */

    pp->bChromaFormat                = s->chroma_format;

    pp->bPicScanFixed                = 1;

    pp->bPicScanMethod               = s->alternate_scan ? 1 : 0;

    pp->bPicReadbackRequests         = 0;

    pp->bRcontrol                    = 0;

    pp->bPicSpatialResid8            = 0;

    pp->bPicOverflowBlocks           = 0;

    pp->bPicExtrapolation            = 0;

    pp->bPicDeblocked                = 0;

    pp->bPicDeblockConfined          = 0;

    pp->bPic4MVallowed               = 0;

    pp->bPicOBMC                     = 0;

    pp->bPicBinPB                    = 0;

    pp->bMV_RPS                      = 0;

    pp->bReservedBits                = 0;

    pp->wBitstreamFcodes             = (s->mpeg_f_code[0][0] << 12) |

                                       (s->mpeg_f_code[0][1] <<  8) |

                                       (s->mpeg_f_code[1][0] <<  4) |

                                       (s->mpeg_f_code[1][1]      );

    pp->wBitstreamPCEelements        = (s->intra_dc_precision         << 14) |

                                       (s->picture_structure          << 12) |

                                       (s->top_field_first            << 11) |

                                       (s->frame_pred_frame_dct       << 10) |

                                       (s->concealment_motion_vectors <<  9) |

                                       (s->q_scale_type               <<  8) |

                                       (s->intra_vlc_format           <<  7) |

                                       (s->alternate_scan             <<  6) |

                                       (s->repeat_first_field         <<  5) |

                                       (s->chroma_420_type            <<  4) |

                                       (s->progressive_frame          <<  3);

    pp->bBitstreamConcealmentNeed    = 0;

    pp->bBitstreamConcealmentMethod  = 0;

}

