static unsigned tget_long(const uint8_t **p, int le)

{

    unsigned v = le ? AV_RL32(*p) : AV_RB32(*p);

    *p += 4;

    return v;

}

static double tget_double(const uint8_t **p, int le)

{

    av_alias64 i = { .u64 = le ? AV_RL64(*p) : AV_RB64(*p)};

    *p += 8;

    return i.f64;

}

static unsigned tget_short(GetByteContext *gb, int le)

{

    unsigned v = le ? bytestream2_get_le16u(gb) : bytestream2_get_be16u(gb);

    return v;

}

static int get_rice_un(GetBitContext *gb, int k)

{

    unsigned int v = get_unary(gb, 1, 128);

    return (v << k) | get_bits_long(gb, k);

}

