static int vqf_read_seek(AVFormatContext *s,

                         int stream_index, int64_t timestamp, int flags)

{

    VqfContext *c = s->priv_data;

    AVStream *st;

    int ret;

    int64_t pos;



    st = s->streams[stream_index];

    pos = av_rescale_rnd(timestamp * st->codec->bit_rate,

                         st->time_base.num,

                         st->time_base.den * (int64_t)c->frame_bit_len,

                         (flags & AVSEEK_FLAG_BACKWARD) ?

                                                   AV_ROUND_DOWN : AV_ROUND_UP);

    pos *= c->frame_bit_len;



    st->cur_dts = av_rescale(pos, st->time_base.den,

                             st->codec->bit_rate * (int64_t)st->time_base.num);



    if ((ret = avio_seek(s->pb, ((pos-7) >> 3) + s->internal->data_offset, SEEK_SET)) < 0)

        return ret;



    c->remaining_bits = -7 - ((pos-7)&7);

    return 0;

}

int pcm_read_seek(AVFormatContext *s,

                  int stream_index, int64_t timestamp, int flags)

{

    AVStream *st;

    int block_align, byte_rate;

    int64_t pos;



    st = s->streams[0];



    block_align = st->codec->block_align ? st->codec->block_align :

        (av_get_bits_per_sample(st->codec->codec_id) * st->codec->channels) >> 3;

    byte_rate = st->codec->bit_rate ? st->codec->bit_rate >> 3 :

        block_align * st->codec->sample_rate;



    if (block_align <= 0 || byte_rate <= 0)

        return -1;



    /* compute the position by aligning it to block_align */

    pos = av_rescale_rnd(timestamp * byte_rate,

                         st->time_base.num,

                         st->time_base.den * (int64_t)block_align,

                         (flags & AVSEEK_FLAG_BACKWARD) ? AV_ROUND_DOWN : AV_ROUND_UP);

    pos *= block_align;



    /* recompute exact position */

    st->cur_dts = av_rescale(pos, st->time_base.den, byte_rate * (int64_t)st->time_base.num);

    url_fseek(s->pb, pos + s->data_offset, SEEK_SET);

    return 0;

}

static int real_seek(AVFormatContext *avf, int stream,

                     int64_t min_ts, int64_t ts, int64_t max_ts, int flags)

{

    ConcatContext *cat = avf->priv_data;

    int ret, left, right;



    if (stream >= 0) {

        if (stream >= avf->nb_streams)

            return AVERROR(EINVAL);

        rescale_interval(avf->streams[stream]->time_base, AV_TIME_BASE_Q,

                         &min_ts, &ts, &max_ts);

    }



    left  = 0;

    right = cat->nb_files;

    while (right - left > 1) {

        int mid = (left + right) / 2;

        if (ts < cat->files[mid].start_time)

            right = mid;

        else

            left  = mid;

    }



    if ((ret = open_file(avf, left)) < 0)

        return ret;



    ret = try_seek(avf, stream, min_ts, ts, max_ts, flags);

    if (ret < 0 && !(flags & AVSEEK_FLAG_BACKWARD) &&

        left < cat->nb_files - 1 &&

        cat->files[left + 1].start_time < max_ts) {

        if ((ret = open_file(avf, left + 1)) < 0)

            return ret;

        ret = try_seek(avf, stream, min_ts, ts, max_ts, flags);

    }

    return ret;

}

static av_cold int aacPlus_encode_init(AVCodecContext *avctx)

{

    aacPlusAudioContext *s = avctx->priv_data;

    aacplusEncConfiguration *aacplus_cfg;



