        return -1;

    }



    s->aacplus_handle = aacplusEncOpen(avctx->sample_rate, avctx->channels,

                                       &s->samples_input, &s->max_output_bytes);

    if(!s->aacplus_handle) {

            av_log(avctx, AV_LOG_ERROR, "can't open encoder\n");

            return -1;

    }



    /* check aacplus version */

    aacplus_cfg = aacplusEncGetCurrentConfiguration(s->aacplus_handle);



    /* put the options in the configuration struct */

    if(avctx->profile != FF_PROFILE_AAC_LOW && avctx->profile != FF_PROFILE_UNKNOWN) {

            av_log(avctx, AV_LOG_ERROR, "invalid AAC profile: %d, only LC supported\n", avctx->profile);

            aacplusEncClose(s->aacplus_handle);

            return -1;

    }



    aacplus_cfg->bitRate = avctx->bit_rate;

    aacplus_cfg->bandWidth = avctx->cutoff;

    aacplus_cfg->outputFormat = !(avctx->flags & CODEC_FLAG_GLOBAL_HEADER);

    aacplus_cfg->inputFormat = avctx->sample_fmt == AV_SAMPLE_FMT_FLT ? AACPLUS_INPUT_FLOAT : AACPLUS_INPUT_16BIT;

    if (!aacplusEncSetConfiguration(s->aacplus_handle, aacplus_cfg)) {

        av_log(avctx, AV_LOG_ERROR, "libaacplus doesn't support this output format!\n");

        return -1;

    }



    avctx->frame_size = s->samples_input / avctx->channels;



    /* Set decoder specific info */

    avctx->extradata_size = 0;

    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER) {



        unsigned char *buffer = NULL;

        unsigned long decoder_specific_info_size;



        if (aacplusEncGetDecoderSpecificInfo(s->aacplus_handle, &buffer,

                                           &decoder_specific_info_size) == 1) {

            avctx->extradata = av_malloc(decoder_specific_info_size + FF_INPUT_BUFFER_PADDING_SIZE);

            avctx->extradata_size = decoder_specific_info_size;

            memcpy(avctx->extradata, buffer, avctx->extradata_size);

        }

        free(buffer);

    }

    return 0;

}

static av_cold int libx265_encode_init(AVCodecContext *avctx)

{

    libx265Context *ctx = avctx->priv_data;



    ctx->api = x265_api_get(av_pix_fmt_desc_get(avctx->pix_fmt)->comp[0].depth_minus1 + 1);

    if (!ctx->api)

        ctx->api = x265_api_get(0);



    if (avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL &&

        !av_pix_fmt_desc_get(avctx->pix_fmt)->log2_chroma_w) {

        av_log(avctx, AV_LOG_ERROR,

               "4:2:2 and 4:4:4 support is not fully defined for HEVC yet. "

               "Set -strict experimental to encode anyway.\n");

        return AVERROR(ENOSYS);

    }



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame) {

        av_log(avctx, AV_LOG_ERROR, "Could not allocate frame.\n");

        return AVERROR(ENOMEM);

    }



    ctx->params = ctx->api->param_alloc();

    if (!ctx->params) {

        av_log(avctx, AV_LOG_ERROR, "Could not allocate x265 param structure.\n");

        return AVERROR(ENOMEM);

    }



    if (ctx->api->param_default_preset(ctx->params, ctx->preset, ctx->tune) < 0) {

        int i;



        av_log(avctx, AV_LOG_ERROR, "Error setting preset/tune %s/%s.\n", ctx->preset, ctx->tune);

        av_log(avctx, AV_LOG_INFO, "Possible presets:");

        for (i = 0; x265_preset_names[i]; i++)

            av_log(avctx, AV_LOG_INFO, " %s", x265_preset_names[i]);



        av_log(avctx, AV_LOG_INFO, "\n");

        av_log(avctx, AV_LOG_INFO, "Possible tunes:");

        for (i = 0; x265_tune_names[i]; i++)

            av_log(avctx, AV_LOG_INFO, " %s", x265_tune_names[i]);



        av_log(avctx, AV_LOG_INFO, "\n");



        return AVERROR(EINVAL);

    }



    ctx->params->frameNumThreads = avctx->thread_count;

    ctx->params->fpsNum          = avctx->time_base.den;

    ctx->params->fpsDenom        = avctx->time_base.num * avctx->ticks_per_frame;

    ctx->params->sourceWidth     = avctx->width;

    ctx->params->sourceHeight    = avctx->height;

    ctx->params->bEnablePsnr     = !!(avctx->flags & CODEC_FLAG_PSNR);



    if ((avctx->color_primaries <= AVCOL_PRI_BT2020 &&

         avctx->color_primaries != AVCOL_PRI_UNSPECIFIED) ||

        (avctx->color_trc <= AVCOL_TRC_BT2020_12 &&

         avctx->color_trc != AVCOL_TRC_UNSPECIFIED) ||

        (avctx->colorspace <= AVCOL_SPC_BT2020_CL &&

         avctx->colorspace != AVCOL_SPC_UNSPECIFIED)) {



        ctx->params->vui.bEnableVideoSignalTypePresentFlag  = 1;

        ctx->params->vui.bEnableColorDescriptionPresentFlag = 1;



        // x265 validates the parameters internally

        ctx->params->vui.colorPrimaries          = avctx->color_primaries;

        ctx->params->vui.transferCharacteristics = avctx->color_trc;

        ctx->params->vui.matrixCoeffs            = avctx->colorspace;

    }



    if (avctx->sample_aspect_ratio.num > 0 && avctx->sample_aspect_ratio.den > 0) {

        char sar[12];

        int sar_num, sar_den;



        av_reduce(&sar_num, &sar_den,

                  avctx->sample_aspect_ratio.num,

                  avctx->sample_aspect_ratio.den, 65535);

        snprintf(sar, sizeof(sar), "%d:%d", sar_num, sar_den);

        if (ctx->api->param_parse(ctx->params, "sar", sar) == X265_PARAM_BAD_VALUE) {

            av_log(avctx, AV_LOG_ERROR, "Invalid SAR: %d:%d.\n", sar_num, sar_den);

            return AVERROR_INVALIDDATA;

        }

    }



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV420P10:

        ctx->params->internalCsp = X265_CSP_I420;

        break;

    case AV_PIX_FMT_YUV422P:

    case AV_PIX_FMT_YUV422P10:

        ctx->params->internalCsp = X265_CSP_I422;

        break;

    case AV_PIX_FMT_YUV444P:

    case AV_PIX_FMT_YUV444P10:

        ctx->params->internalCsp = X265_CSP_I444;

        break;

    }



    if (ctx->crf >= 0) {

        char crf[6];



        snprintf(crf, sizeof(crf), "%2.2f", ctx->crf);

        if (ctx->api->param_parse(ctx->params, "crf", crf) == X265_PARAM_BAD_VALUE) {

            av_log(avctx, AV_LOG_ERROR, "Invalid crf: %2.2f.\n", ctx->crf);

            return AVERROR(EINVAL);

        }

    } else if (avctx->bit_rate > 0) {

        ctx->params->rc.bitrate         = avctx->bit_rate / 1000;

        ctx->params->rc.rateControlMode = X265_RC_ABR;

    }



    if (!(avctx->flags & CODEC_FLAG_GLOBAL_HEADER))

        ctx->params->bRepeatHeaders = 1;



    if (ctx->x265_opts) {

        AVDictionary *dict    = NULL;

        AVDictionaryEntry *en = NULL;



        if (!av_dict_parse_string(&dict, ctx->x265_opts, "=", ":", 0)) {

            while ((en = av_dict_get(dict, "", en, AV_DICT_IGNORE_SUFFIX))) {

                int parse_ret = ctx->api->param_parse(ctx->params, en->key, en->value);



                switch (parse_ret) {

                case X265_PARAM_BAD_NAME:

                    av_log(avctx, AV_LOG_WARNING,

                          "Unknown option: %s.\n", en->key);

                    break;

                case X265_PARAM_BAD_VALUE:

                    av_log(avctx, AV_LOG_WARNING,

                          "Invalid value for %s: %s.\n", en->key, en->value);

                    break;

                default:

                    break;

                }

            }

            av_dict_free(&dict);

        }

    }



    ctx->encoder = ctx->api->encoder_open(ctx->params);

    if (!ctx->encoder) {

        av_log(avctx, AV_LOG_ERROR, "Cannot open libx265 encoder.\n");

        libx265_encode_close(avctx);

        return AVERROR_INVALIDDATA;

    }



    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER) {

        x265_nal *nal;

        int nnal;



        avctx->extradata_size = ctx->api->encoder_headers(ctx->encoder, &nal, &nnal);

        if (avctx->extradata_size <= 0) {

            av_log(avctx, AV_LOG_ERROR, "Cannot encode headers.\n");

            libx265_encode_close(avctx);

            return AVERROR_INVALIDDATA;

        }



        avctx->extradata = av_malloc(avctx->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!avctx->extradata) {

            av_log(avctx, AV_LOG_ERROR,

                   "Cannot allocate HEVC header of size %d.\n", avctx->extradata_size);

            libx265_encode_close(avctx);

            return AVERROR(ENOMEM);

        }



        memcpy(avctx->extradata, nal[0].payload, avctx->extradata_size);

    }



    return 0;

}

static uint_fast8_t vorbis_floor1_decode(vorbis_context *vc,

                                         vorbis_floor_data *vfu, float *vec)

{

    vorbis_floor1 *vf = &vfu->t1;

    GetBitContext *gb = &vc->gb;

    uint_fast16_t range_v[4] = { 256, 128, 86, 64 };

    uint_fast16_t range = range_v[vf->multiplier-1];

    uint_fast16_t floor1_Y[258];

    uint_fast16_t floor1_Y_final[258];

    int floor1_flag[258];

    uint_fast8_t class_;

    uint_fast8_t cdim;

    uint_fast8_t cbits;

    uint_fast8_t csub;

    uint_fast8_t cval;

    int_fast16_t book;

    uint_fast16_t offset;

    uint_fast16_t i,j;

    /*u*/int_fast16_t adx, ady, off, predicted; // WTF ? dy/adx =  (unsigned)dy/adx ?

    int_fast16_t dy, err;





    if (!get_bits1(gb)) // silence

        return 1;



// Read values (or differences) for the floor's points



    floor1_Y[0] = get_bits(gb, ilog(range - 1));

    floor1_Y[1] = get_bits(gb, ilog(range - 1));



    AV_DEBUG("floor 0 Y %d floor 1 Y %d \n", floor1_Y[0], floor1_Y[1]);



    offset = 2;

    for (i = 0; i < vf->partitions; ++i) {

        class_ = vf->partition_class[i];

        cdim   = vf->class_dimensions[class_];

        cbits  = vf->class_subclasses[class_];

        csub = (1 << cbits) - 1;

        cval = 0;



        AV_DEBUG("Cbits %d \n", cbits);



        if (cbits) // this reads all subclasses for this partition's class

            cval = get_vlc2(gb, vc->codebooks[vf->class_masterbook[class_]].vlc.table,

                            vc->codebooks[vf->class_masterbook[class_]].nb_bits, 3);



        for (j = 0; j < cdim; ++j) {

            book = vf->subclass_books[class_][cval & csub];



            AV_DEBUG("book %d Cbits %d cval %d  bits:%d \n", book, cbits, cval, get_bits_count(gb));



            cval = cval >> cbits;

            if (book > -1) {

                floor1_Y[offset+j] = get_vlc2(gb, vc->codebooks[book].vlc.table,

                vc->codebooks[book].nb_bits, 3);

            } else {

                floor1_Y[offset+j] = 0;

            }



            AV_DEBUG(" floor(%d) = %d \n", vf->list[offset+j].x, floor1_Y[offset+j]);

        }

        offset+=cdim;

    }



// Amplitude calculation from the differences



    floor1_flag[0] = 1;

    floor1_flag[1] = 1;

    floor1_Y_final[0] = floor1_Y[0];

    floor1_Y_final[1] = floor1_Y[1];



    for (i = 2; i < vf->x_list_dim; ++i) {

        uint_fast16_t val, highroom, lowroom, room;

        uint_fast16_t high_neigh_offs;

        uint_fast16_t low_neigh_offs;



        low_neigh_offs  = vf->list[i].low;

        high_neigh_offs = vf->list[i].high;

        dy  = floor1_Y_final[high_neigh_offs] - floor1_Y_final[low_neigh_offs];  // render_point begin

        adx = vf->list[high_neigh_offs].x - vf->list[low_neigh_offs].x;

        ady = FFABS(dy);

        err = ady * (vf->list[i].x - vf->list[low_neigh_offs].x);

        off = (int16_t)err / (int16_t)adx;

        if (dy < 0) {

            predicted = floor1_Y_final[low_neigh_offs] - off;

        } else {

            predicted = floor1_Y_final[low_neigh_offs] + off;

        } // render_point end



        val = floor1_Y[i];

        highroom = range-predicted;

        lowroom  = predicted;

        if (highroom < lowroom) {

            room = highroom * 2;

        } else {

            room = lowroom * 2;   // SPEC mispelling

        }

        if (val) {

            floor1_flag[low_neigh_offs]  = 1;

            floor1_flag[high_neigh_offs] = 1;

            floor1_flag[i]               = 1;

            if (val >= room) {

                if (highroom > lowroom) {

                    floor1_Y_final[i] = val - lowroom + predicted;

                } else {

                    floor1_Y_final[i] = predicted - val + highroom - 1;

                }

            } else {

                if (val & 1) {

                    floor1_Y_final[i] = predicted - (val + 1) / 2;

                } else {

                    floor1_Y_final[i] = predicted + val / 2;

                }

            }

        } else {

            floor1_flag[i]    = 0;

            floor1_Y_final[i] = predicted;

        }



        AV_DEBUG(" Decoded floor(%d) = %d / val %d \n", vf->list[i].x, floor1_Y_final[i], val);

    }



// Curve synth - connect the calculated dots and convert from dB scale FIXME optimize ?



    ff_vorbis_floor1_render_list(vf->list, vf->x_list_dim, floor1_Y_final, floor1_flag, vf->multiplier, vec, vf->list[1].x);



    AV_DEBUG(" Floor decoded\n");



    return 0;

}

static uint_fast8_t vorbis_floor0_decode(vorbis_context *vc,

                                         vorbis_floor_data *vfu, float *vec)

{

    vorbis_floor0 *vf = &vfu->t0;

    float *lsp = vf->lsp;

    uint_fast32_t amplitude;

    uint_fast32_t book_idx;

    uint_fast8_t blockflag = vc->modes[vc->mode_number].blockflag;



    amplitude = get_bits(&vc->gb, vf->amplitude_bits);

    if (amplitude > 0) {

        float last = 0;

        uint_fast16_t lsp_len = 0;

        uint_fast16_t idx;

        vorbis_codebook codebook;



        book_idx = get_bits(&vc->gb, ilog(vf->num_books));

        if (book_idx >= vf->num_books) {

            av_log(vc->avccontext, AV_LOG_ERROR,

                    "floor0 dec: booknumber too high!\n");

            book_idx =  0;

            //FIXME: look above

        }

        AV_DEBUG("floor0 dec: booknumber: %u\n", book_idx);

        codebook = vc->codebooks[vf->book_list[book_idx]];



        while (lsp_len<vf->order) {

            int vec_off;



            AV_DEBUG("floor0 dec: book dimension: %d\n", codebook.dimensions);

            AV_DEBUG("floor0 dec: maximum depth: %d\n", codebook.maxdepth);

            /* read temp vector */

            vec_off = get_vlc2(&vc->gb, codebook.vlc.table,

                               codebook.nb_bits, codebook.maxdepth)

                      * codebook.dimensions;

            AV_DEBUG("floor0 dec: vector offset: %d\n", vec_off);

            /* copy each vector component and add last to it */

            for (idx = 0; idx < codebook.dimensions; ++idx)

                lsp[lsp_len+idx] = codebook.codevectors[vec_off+idx] + last;

            last = lsp[lsp_len+idx-1]; /* set last to last vector component */



            lsp_len += codebook.dimensions;

        }

#ifdef V_DEBUG

        /* DEBUG: output lsp coeffs */

        {

            int idx;

            for (idx = 0; idx < lsp_len; ++idx)

                AV_DEBUG("floor0 dec: coeff at %d is %f\n", idx, lsp[idx]);

        }

#endif



        /* synthesize floor output vector */

        {

            int i;

            int order = vf->order;

            float wstep = M_PI / vf->bark_map_size;



            for (i = 0; i < order; i++)

                lsp[i] = 2.0f * cos(lsp[i]);



            AV_DEBUG("floor0 synth: map_size = %d; m = %d; wstep = %f\n",

                     vf->map_size, order, wstep);



            i = 0;

            while (i < vf->map_size[blockflag]) {

                int j, iter_cond = vf->map[blockflag][i];

                float p = 0.5f;

                float q = 0.5f;

                float two_cos_w = 2.0f * cos(wstep * iter_cond); // needed all times



                /* similar part for the q and p products */

                for (j = 0; j + 1 < order; j += 2) {

                    q *= lsp[j]     - two_cos_w;

                    p *= lsp[j + 1] - two_cos_w;

                }

                if (j == order) { // even order

                    p *= p * (2.0f - two_cos_w);

                    q *= q * (2.0f + two_cos_w);

                } else { // odd order

                    q *= two_cos_w-lsp[j]; // one more time for q



                    /* final step and square */

                    p *= p * (4.f - two_cos_w * two_cos_w);

                    q *= q;

                }



                /* calculate linear floor value */

                {

                    q = exp((((amplitude*vf->amplitude_offset) /

                              (((1 << vf->amplitude_bits) - 1) * sqrt(p + q)))

                             - vf->amplitude_offset) * .11512925f);

                }



                /* fill vector */

                do {

                    vec[i] = q; ++i;

                } while (vf->map[blockflag][i] == iter_cond);

            }

        }

    } else {

        /* this channel is unused */

        return 1;

    }



    AV_DEBUG(" Floor0 decoded\n");



    return 0;

}

static int vorbis_floor1_decode(vorbis_context *vc,

                                vorbis_floor_data *vfu, float *vec)

{

    vorbis_floor1 *vf = &vfu->t1;

    GetBitContext *gb = &vc->gb;

    uint16_t range_v[4] = { 256, 128, 86, 64 };

