static int vqf_read_seek(AVFormatContext *s,

                         int stream_index, int64_t timestamp, int flags)

{

    VqfContext *c = s->priv_data;

    AVStream *st;

    int ret;

    int64_t pos;



    st = s->streams[stream_index];

    pos = av_rescale_rnd(timestamp * st->codec->bit_rate,

                         st->time_base.num,

                         st->time_base.den * (int64_t)c->frame_bit_len,

                         (flags & AVSEEK_FLAG_BACKWARD) ?

                                                   AV_ROUND_DOWN : AV_ROUND_UP);

    pos *= c->frame_bit_len;



    st->cur_dts = av_rescale(pos, st->time_base.den,

                             st->codec->bit_rate * (int64_t)st->time_base.num);



    if ((ret = avio_seek(s->pb, ((pos-7) >> 3) + s->internal->data_offset, SEEK_SET)) < 0)

        return ret;



    c->remaining_bits = -7 - ((pos-7)&7);

    return 0;

}

static void mp3_parse_info_tag(AVFormatContext *s, AVStream *st,

                               MPADecodeHeader *c, uint32_t spf)

{

#define LAST_BITS(k, n) ((k) & ((1 << (n)) - 1))

#define MIDDLE_BITS(k, m, n) LAST_BITS((k) >> (m), ((n) - (m)))



    uint16_t crc;

    uint32_t v;



    char version[10];



    uint32_t peak   = 0;

    int32_t  r_gain = INT32_MIN, a_gain = INT32_MIN;



    MP3DecContext *mp3 = s->priv_data;

    static const int64_t xing_offtbl[2][2] = {{32, 17}, {17,9}};

    uint64_t fsize = avio_size(s->pb);



    /* Check for Xing / Info tag */

    avio_skip(s->pb, xing_offtbl[c->lsf == 1][c->nb_channels == 1]);

    v = avio_rb32(s->pb);

    mp3->is_cbr = v == MKBETAG('I', 'n', 'f', 'o');

    if (v != MKBETAG('X', 'i', 'n', 'g') && !mp3->is_cbr)

        return;



    v = avio_rb32(s->pb);

    if (v & XING_FLAG_FRAMES)

        mp3->frames = avio_rb32(s->pb);

    if (v & XING_FLAG_SIZE)

        mp3->header_filesize = avio_rb32(s->pb);

    if (fsize && mp3->header_filesize) {

        uint64_t min, delta;

        min = FFMIN(fsize, mp3->header_filesize);

        delta = FFMAX(fsize, mp3->header_filesize) - min;

        if (fsize > mp3->header_filesize && delta > min >> 4) {

            mp3->frames = 0;

        } else if (delta > min >> 4) {

            av_log(s, AV_LOG_WARNING,

                   "filesize and duration do not match (growing file?)\n");

        }

    }

    if (v & XING_FLAG_TOC)

        read_xing_toc(s, mp3->header_filesize, av_rescale_q(mp3->frames,

                                       (AVRational){spf, c->sample_rate},

                                       st->time_base));

    /* VBR quality */

    if(v & 8)

        avio_skip(s->pb, 4);



    /* Encoder short version string */

    memset(version, 0, sizeof(version));

    avio_read(s->pb, version, 9);



    /* Info Tag revision + VBR method */

    avio_r8(s->pb);



    /* Lowpass filter value */

    avio_r8(s->pb);



    /* ReplayGain peak */

    v    = avio_rb32(s->pb);

    peak = av_rescale(v, 100000, 1 << 23);



    /* Radio ReplayGain */

    v = avio_rb16(s->pb);



    if (MIDDLE_BITS(v, 13, 15) == 1) {

        r_gain = MIDDLE_BITS(v, 0, 8) * 10000;



        if (v & (1 << 9))

            r_gain *= -1;

    }



    /* Audiophile ReplayGain */

    v = avio_rb16(s->pb);



    if (MIDDLE_BITS(v, 13, 15) == 2) {

        a_gain = MIDDLE_BITS(v, 0, 8) * 10000;



        if (v & (1 << 9))

            a_gain *= -1;

    }



    /* Encoding flags + ATH Type */

    avio_r8(s->pb);



    /* if ABR {specified bitrate} else {minimal bitrate} */

    avio_r8(s->pb);



    /* Encoder delays */

    v= avio_rb24(s->pb);

    if(AV_RB32(version) == MKBETAG('L', 'A', 'M', 'E')

        || AV_RB32(version) == MKBETAG('L', 'a', 'v', 'f')) {



        mp3->start_pad = v>>12;

        mp3->  end_pad = v&4095;

        st->skip_samples = mp3->start_pad + 528 + 1;

        if (mp3->frames)

            st->end_discard_sample = -mp3->end_pad + 528 + 1 + mp3->frames * (int64_t)spf;

        if (!st->start_time)

            st->start_time = av_rescale_q(st->skip_samples,

                                            (AVRational){1, c->sample_rate},

                                            st->time_base);

        av_log(s, AV_LOG_DEBUG, "pad %d %d\n", mp3->start_pad, mp3->  end_pad);

    }



    /* Misc */

    avio_r8(s->pb);



    /* MP3 gain */

    avio_r8(s->pb);



    /* Preset and surround info */

    avio_rb16(s->pb);



    /* Music length */

    avio_rb32(s->pb);



    /* Music CRC */

    avio_rb16(s->pb);



    /* Info Tag CRC */

    crc = ffio_get_checksum(s->pb);

    v   = avio_rb16(s->pb);



    if (v == crc) {

        ff_replaygain_export_raw(st, r_gain, peak, a_gain, 0);

        av_dict_set(&st->metadata, "encoder", version, 0);

    }

}

int pcm_read_seek(AVFormatContext *s,

                  int stream_index, int64_t timestamp, int flags)

{

    AVStream *st;

    int block_align, byte_rate;

    int64_t pos;



    st = s->streams[0];



    block_align = st->codec->block_align ? st->codec->block_align :

        (av_get_bits_per_sample(st->codec->codec_id) * st->codec->channels) >> 3;

    byte_rate = st->codec->bit_rate ? st->codec->bit_rate >> 3 :

        block_align * st->codec->sample_rate;



    if (block_align <= 0 || byte_rate <= 0)

        return -1;



    /* compute the position by aligning it to block_align */

    pos = av_rescale_rnd(timestamp * byte_rate,

                         st->time_base.num,

                         st->time_base.den * (int64_t)block_align,

                         (flags & AVSEEK_FLAG_BACKWARD) ? AV_ROUND_DOWN : AV_ROUND_UP);

    pos *= block_align;



    /* recompute exact position */

    st->cur_dts = av_rescale(pos, st->time_base.den, byte_rate * (int64_t)st->time_base.num);

    url_fseek(s->pb, pos + s->data_offset, SEEK_SET);

    return 0;

}

static int mp3_read_header(AVFormatContext *s)

{

    MP3DecContext *mp3 = s->priv_data;

    AVStream *st;

    int64_t off;

    int ret;

    int i;



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id = AV_CODEC_ID_MP3;

    st->need_parsing = AVSTREAM_PARSE_FULL_RAW;

    st->start_time = 0;



    // lcm of all mp3 sample rates

    avpriv_set_pts_info(st, 64, 1, 14112000);



    s->pb->maxsize = -1;

    off = avio_tell(s->pb);



    if (!av_dict_get(s->metadata, "", NULL, AV_DICT_IGNORE_SUFFIX))

        ff_id3v1_read(s);



    if(s->pb->seekable)

        mp3->filesize = avio_size(s->pb);



    if (mp3_parse_vbr_tags(s, st, off) < 0)

        avio_seek(s->pb, off, SEEK_SET);



    ret = ff_replaygain_export(st, s->metadata);

    if (ret < 0)

        return ret;



    off = avio_tell(s->pb);

    for (i = 0; i < 64 * 1024; i++) {

        uint32_t header, header2;

        int frame_size;

        if (!(i&1023))

            ffio_ensure_seekback(s->pb, i + 1024 + 4);

        frame_size = check(s->pb, off + i, &header);

        if (frame_size > 0) {

            avio_seek(s->pb, off, SEEK_SET);

            ffio_ensure_seekback(s->pb, i + 1024 + frame_size + 4);

            if (check(s->pb, off + i + frame_size, &header2) >= 0 &&

                (header & SAME_HEADER_MASK) == (header2 & SAME_HEADER_MASK))

            {

                av_log(s, AV_LOG_INFO, "Skipping %d bytes of junk at %"PRId64".\n", i, off);

                avio_seek(s->pb, off + i, SEEK_SET);

                break;

            }

        }

        avio_seek(s->pb, off, SEEK_SET);

    }



    // the seek index is relative to the end of the xing vbr headers

    for (i = 0; i < st->nb_index_entries; i++)

        st->index_entries[i].pos += avio_tell(s->pb);



    /* the parameters will be extracted from the compressed bitstream */

    return 0;

}

