static int skip_check(MpegEncContext *s, Picture *p, Picture *ref)

{

    int x, y, plane;

    int score = 0;

    int64_t score64 = 0;



    for (plane = 0; plane < 3; plane++) {

        const int stride = p->f.linesize[plane];

        const int bw = plane ? 1 : 2;

        for (y = 0; y < s->mb_height * bw; y++) {

            for (x = 0; x < s->mb_width * bw; x++) {

                int off = p->shared ? 0 : 16;

                uint8_t *dptr = p->f.data[plane] + 8 * (x + y * stride) + off;

                uint8_t *rptr = ref->f.data[plane] + 8 * (x + y * stride);

                int v   = s->dsp.frame_skip_cmp[1](s, dptr, rptr, stride, 8);



                switch (s->avctx->frame_skip_exp) {

                case 0: score    =  FFMAX(score, v);          break;

                case 1: score   += FFABS(v);                  break;

                case 2: score   += v * v;                     break;

                case 3: score64 += FFABS(v * v * (int64_t)v); break;

                case 4: score64 += v * v * (int64_t)(v * v);  break;

                }

            }

        }

    }



    if (score)

        score64 = score;



    if (score64 < s->avctx->frame_skip_threshold)

        return 1;

    if (score64 < ((s->avctx->frame_skip_factor * (int64_t)s->lambda) >> 8))

        return 1;

    return 0;

}

static void channel_weighting(float *su1, float *su2, int *p3)

{

    int band, nsample;

    /* w[x][y] y=0 is left y=1 is right */

    float w[2][2];



    if (p3[1] != 7 || p3[3] != 7) {

        get_channel_weights(p3[1], p3[0], w[0]);

        get_channel_weights(p3[3], p3[2], w[1]);



        for (band = 1; band < 4; band++) {

            for (nsample = 0; nsample < 8; nsample++) {

                su1[band * 256 + nsample] *= INTERPOLATE(w[0][0], w[0][1], nsample);

                su2[band * 256 + nsample] *= INTERPOLATE(w[1][0], w[1][1], nsample);

            }

            for(; nsample < 256; nsample++) {

                su1[band * 256  + nsample] *= w[1][0];

                su2[band * 256  + nsample] *= w[1][1];

            }

        }

    }

}

static void floor_fit(venc_context_t * venc, floor_t * fc, float * coeffs, int * posts, int samples) {

    int range = 255 / fc->multiplier + 1;

    int i;

    for (i = 0; i < fc->values; i++) {

        int position = fc->list[fc->list[i].sort].x;

        int begin = fc->list[fc->list[FFMAX(i-1, 0)].sort].x;

        int end   = fc->list[fc->list[FFMIN(i+1, fc->values - 1)].sort].x;

        int j;

        float average = 0;

        begin = (position + begin) / 2;

        end   = (position + end  ) / 2;



        assert(end <= samples);

        for (j = begin; j < end; j++) average += fabs(coeffs[j]);

        average /= end - begin;

        average /= 32; // MAGIC!

        for (j = 0; j < range - 1; j++) if (floor1_inverse_db_table[j * fc->multiplier] > average) break;

        posts[fc->list[i].sort] = j;

    }

}

static void scsi_unrealize(SCSIDevice *dev, Error **errp)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, dev);



    scsi_device_purge_requests(&s->qdev, SENSE_CODE(NO_SENSE));

    blockdev_mark_auto_del(s->qdev.conf.blk);

}

static void scsi_hd_realize(SCSIDevice *dev, Error **errp)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, dev);

    blkconf_blocksizes(&s->qdev.conf);

    s->qdev.blocksize = s->qdev.conf.logical_block_size;

    s->qdev.type = TYPE_DISK;

    if (!s->product) {

        s->product = g_strdup("QEMU HARDDISK");

    }

    scsi_realize(&s->qdev, errp);

}

static void scsi_dma_complete(void *opaque, int ret)

{

    SCSIDiskReq *r = (SCSIDiskReq *)opaque;

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);



    bdrv_acct_done(s->qdev.conf.bs, &r->acct);



    if (ret) {

        if (scsi_handle_rw_error(r, -ret)) {

            goto done;

        }

    }



    r->sector += r->sector_count;

    r->sector_count = 0;

    scsi_req_complete(&r->req, GOOD);



done:

    if (!r->req.io_canceled) {

        scsi_req_unref(&r->req);

    }

}

static int scsi_cd_initfn(SCSIDevice *dev)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, dev);

    s->qdev.blocksize = 2048;

    s->qdev.type = TYPE_ROM;

    s->features |= 1 << SCSI_DISK_F_REMOVABLE;

    if (!s->product) {

        s->product = g_strdup("QEMU CD-ROM");

    }

    return scsi_initfn(&s->qdev);

}

static int ivr_read_header(AVFormatContext *s)

{

    unsigned tag, type, len, tlen, value;

    int i, j, n, count, nb_streams, ret;

    uint8_t key[256], val[256];

    AVIOContext *pb = s->pb;

    AVStream *st;

    int64_t pos, offset, temp;



    pos = avio_tell(pb);

    tag = avio_rl32(pb);

    if (tag == MKTAG('.','R','1','M')) {

        if (avio_rb16(pb) != 1)

            return AVERROR_INVALIDDATA;

        if (avio_r8(pb) != 1)

            return AVERROR_INVALIDDATA;

        len = avio_rb32(pb);

        avio_skip(pb, len);

        avio_skip(pb, 5);

        temp = avio_rb64(pb);

        while (!avio_feof(pb) && temp) {

            offset = temp;

            temp = avio_rb64(pb);

        }

        avio_skip(pb, offset - avio_tell(pb));

        if (avio_r8(pb) != 1)

            return AVERROR_INVALIDDATA;

        len = avio_rb32(pb);

        avio_skip(pb, len);

        if (avio_r8(pb) != 2)

            return AVERROR_INVALIDDATA;

        avio_skip(pb, 16);

        pos = avio_tell(pb);

        tag = avio_rl32(pb);

    }



    if (tag != MKTAG('.','R','E','C'))

        return AVERROR_INVALIDDATA;



    if (avio_r8(pb) != 0)

        return AVERROR_INVALIDDATA;

    count = avio_rb32(pb);

    for (i = 0; i < count; i++) {

        if (avio_feof(pb))

            return AVERROR_INVALIDDATA;



        type = avio_r8(pb);

        tlen = avio_rb32(pb);

        avio_get_str(pb, tlen, key, sizeof(key));

        len = avio_rb32(pb);

        if (type == 5) {

            avio_get_str(pb, len, val, sizeof(val));

            av_log(s, AV_LOG_DEBUG, "%s = '%s'\n", key, val);

        } else if (type == 4) {

            av_log(s, AV_LOG_DEBUG, "%s = '0x", key);

            for (j = 0; j < len; j++)

                av_log(s, AV_LOG_DEBUG, "%X", avio_r8(pb));

            av_log(s, AV_LOG_DEBUG, "'\n");

        } else if (len == 4 && type == 3 && !strncmp(key, "StreamCount", tlen)) {

            nb_streams = value = avio_rb32(pb);

        } else if (len == 4 && type == 3) {

            value = avio_rb32(pb);

            av_log(s, AV_LOG_DEBUG, "%s = %d\n", key, value);

        } else {

            av_log(s, AV_LOG_DEBUG, "Skipping unsupported key: %s\n", key);

            avio_skip(pb, len);

        }

    }



    for (n = 0; n < nb_streams; n++) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        st->priv_data = ff_rm_alloc_rmstream();

        if (!st->priv_data)

            return AVERROR(ENOMEM);



        if (avio_r8(pb) != 1)

            return AVERROR_INVALIDDATA;



        count = avio_rb32(pb);

        for (i = 0; i < count; i++) {

            if (avio_feof(pb))

                return AVERROR_INVALIDDATA;



            type = avio_r8(pb);

            tlen  = avio_rb32(pb);

            avio_get_str(pb, tlen, key, sizeof(key));

            len  = avio_rb32(pb);

            if (type == 5) {

                avio_get_str(pb, len, val, sizeof(val));

                av_log(s, AV_LOG_DEBUG, "%s = '%s'\n", key, val);

            } else if (type == 4 && !strncmp(key, "OpaqueData", tlen)) {

                ret = ffio_ensure_seekback(pb, 4);

                if (ret < 0)

                    return ret;

                if (avio_rb32(pb) == MKBETAG('M', 'L', 'T', 'I')) {

                    ret = rm_read_multi(s, pb, st, NULL);

                } else {

                    avio_seek(pb, -4, SEEK_CUR);

                    ret = ff_rm_read_mdpr_codecdata(s, pb, st, st->priv_data, len, NULL);

                }



                if (ret < 0)

                    return ret;

            } else if (type == 4) {

                int j;



                av_log(s, AV_LOG_DEBUG, "%s = '0x", key);

                for (j = 0; j < len; j++)

                    av_log(s, AV_LOG_DEBUG, "%X", avio_r8(pb));

                av_log(s, AV_LOG_DEBUG, "'\n");

            } else if (len == 4 && type == 3 && !strncmp(key, "Duration", tlen)) {

                st->duration = avio_rb32(pb);

            } else if (len == 4 && type == 3) {

                value = avio_rb32(pb);

                av_log(s, AV_LOG_DEBUG, "%s = %d\n", key, value);

            } else {

                av_log(s, AV_LOG_DEBUG, "Skipping unsupported key: %s\n", key);

                avio_skip(pb, len);

            }

        }

    }



    if (avio_r8(pb) != 6)

        return AVERROR_INVALIDDATA;

    avio_skip(pb, 12);

    avio_skip(pb, avio_rb64(pb) + pos - avio_tell(s->pb));

    if (avio_r8(pb) != 8)

        return AVERROR_INVALIDDATA;

    avio_skip(pb, 8);



    return 0;

}

static int pva_read_packet(AVFormatContext *s, AVPacket *pkt) {

    ByteIOContext *pb = s->pb;

    PVAContext *pvactx = s->priv_data;

    int ret, syncword, streamid, reserved, flags, length, pts_flag;

    int64_t pva_pts = AV_NOPTS_VALUE;



recover:

    syncword = get_be16(pb);

    streamid = get_byte(pb);

    get_byte(pb);               /* counter not used */

    reserved = get_byte(pb);

    flags    = get_byte(pb);

    length   = get_be16(pb);



    pts_flag = flags & 0x10;



    if (syncword != PVA_MAGIC) {

        av_log(s, AV_LOG_ERROR, "invalid syncword\n");

        return AVERROR(EIO);

    }

    if (streamid != PVA_VIDEO_PAYLOAD && streamid != PVA_AUDIO_PAYLOAD) {

        av_log(s, AV_LOG_ERROR, "invalid streamid\n");

        return AVERROR(EIO);

    }

    if (reserved != 0x55) {

        av_log(s, AV_LOG_WARNING, "expected reserved byte to be 0x55\n");

    }

    if (length > PVA_MAX_PAYLOAD_LENGTH) {

        av_log(s, AV_LOG_ERROR, "invalid payload length %u\n", length);

        return AVERROR(EIO);

    }



    if (streamid == PVA_VIDEO_PAYLOAD && pts_flag) {

        pva_pts = get_be32(pb);

        length -= 4;

    } else if (streamid == PVA_AUDIO_PAYLOAD) {

        /* PVA Audio Packets either start with a signaled PES packet or

         * are a continuation of the previous PES packet. New PES packets

         * always start at the beginning of a PVA Packet, never somewhere in

         * the middle. */

        if (!pvactx->continue_pes) {

            int pes_signal, pes_header_data_length, pes_packet_length,

                pes_flags;

            unsigned char pes_header_data[256];



            pes_signal             = get_be24(pb);

            get_byte(pb);

            pes_packet_length      = get_be16(pb);

            pes_flags              = get_be16(pb);

            pes_header_data_length = get_byte(pb);



            if (pes_signal != 1) {

                av_log(s, AV_LOG_WARNING, "expected signaled PES packet, "

                                          "trying to recover\n");

                url_fskip(pb, length - 9);

                goto recover;

            }



            get_buffer(pb, pes_header_data, pes_header_data_length);

            length -= 9 + pes_header_data_length;



            pes_packet_length -= 3 + pes_header_data_length;



            pvactx->continue_pes = pes_packet_length;



            if (pes_flags & 0x80 && (pes_header_data[0] & 0xf0) == 0x20)

                pva_pts = ff_parse_pes_pts(pes_header_data);

        }



        pvactx->continue_pes -= length;



        if (pvactx->continue_pes < 0) {

            av_log(s, AV_LOG_WARNING, "audio data corruption\n");

            pvactx->continue_pes = 0;

        }

    }



    if ((ret = av_get_packet(pb, pkt, length)) <= 0)

        return AVERROR(EIO);



    pkt->stream_index = streamid - 1;

    if (pva_pts != AV_NOPTS_VALUE)

        pkt->pts = pva_pts;



    return ret;

}

static int rm_read_index(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    unsigned int size, n_pkts, str_id, next_off, n, pos, pts;

    AVStream *st;



    do {

        if (avio_rl32(pb) != MKTAG('I','N','D','X'))

            return -1;

        size     = avio_rb32(pb);

        if (size < 20)

            return -1;

        avio_skip(pb, 2);

        n_pkts   = avio_rb32(pb);

        str_id   = avio_rb16(pb);

        next_off = avio_rb32(pb);

        for (n = 0; n < s->nb_streams; n++)

            if (s->streams[n]->id == str_id) {

                st = s->streams[n];

                break;

            }

        if (n == s->nb_streams)

            goto skip;



        for (n = 0; n < n_pkts; n++) {

            avio_skip(pb, 2);

            pts = avio_rb32(pb);

            pos = avio_rb32(pb);

            avio_skip(pb, 4); /* packet no. */



            av_add_index_entry(st, pos, pts, 0, 0, AVINDEX_KEYFRAME);

        }



skip:

        if (next_off && avio_tell(pb) != next_off &&

            avio_seek(pb, next_off, SEEK_SET) < 0)

            return -1;

    } while (next_off);



    return 0;

}

static int lmlm4_read_packet(AVFormatContext *s, AVPacket *pkt) {

    AVIOContext *pb = s->pb;

    int ret;

    unsigned int frame_type, packet_size, padding, frame_size;



    avio_rb16(pb);                       /* channel number */

    frame_type  = avio_rb16(pb);

    packet_size = avio_rb32(pb);

    padding     = -packet_size & 511;

    frame_size  = packet_size - 8;



    if (frame_type > LMLM4_MPEG1L2 || frame_type == LMLM4_INVALID) {

        av_log(s, AV_LOG_ERROR, "invalid or unsupported frame_type\n");

        return AVERROR(EIO);

    }

    if (packet_size > LMLM4_MAX_PACKET_SIZE) {

        av_log(s, AV_LOG_ERROR, "packet size exceeds maximum\n");

        return AVERROR(EIO);

    }



    if ((ret = av_get_packet(pb, pkt, frame_size)) <= 0)

        return AVERROR(EIO);



    avio_skip(pb, padding);



    switch (frame_type) {

        case LMLM4_I_FRAME:

            pkt->flags = AV_PKT_FLAG_KEY;

        case LMLM4_P_FRAME:

        case LMLM4_B_FRAME:

            pkt->stream_index = 0;

            break;

        case LMLM4_MPEG1L2:

            pkt->stream_index = 1;

            break;

    }



    return ret;

}

