int ff_read_packet(AVFormatContext *s, AVPacket *pkt)
{
    int ret, i, err;
    AVStream *st;
    for (;;) {
        AVPacketList *pktl = s->internal->raw_packet_buffer;
        if (pktl) {
            *pkt = pktl->pkt;
            st   = s->streams[pkt->stream_index];
            if (s->internal->raw_packet_buffer_remaining_size <= 0)
                if ((err = probe_codec(s, st, NULL)) < 0)
                    return err;
            if (st->request_probe <= 0) {
                s->internal->raw_packet_buffer                 = pktl->next;
                s->internal->raw_packet_buffer_remaining_size += pkt->size;
                av_free(pktl);
                return 0;
        pkt->data = NULL;
        pkt->size = 0;
        av_init_packet(pkt);
        ret = s->iformat->read_packet(s, pkt);
        if (ret < 0) {
            /* Some demuxers return FFERROR_REDO when they consume
               data and discard it (ignored streams, junk, extradata).
               We must re-call the demuxer to get the real packet. */
            if (ret == FFERROR_REDO)
                continue;
            if (!pktl || ret == AVERROR(EAGAIN))
                return ret;
            for (i = 0; i < s->nb_streams; i++) {
                st = s->streams[i];
                if (st->probe_packets || st->request_probe > 0)
                    if ((err = probe_codec(s, st, NULL)) < 0)
                        return err;
                av_assert0(st->request_probe <= 0);
            continue;
        if (!pkt->buf) {
            AVPacket tmp = { 0 };
            ret = av_packet_ref(&tmp, pkt);
            if (ret < 0)
                return ret;
            *pkt = tmp;
        if ((s->flags & AVFMT_FLAG_DISCARD_CORRUPT) &&
            (pkt->flags & AV_PKT_FLAG_CORRUPT)) {
            av_log(s, AV_LOG_WARNING,
                   "Dropped corrupted packet (stream = %d)\n",
                   pkt->stream_index);
            av_packet_unref(pkt);
            continue;
        if (pkt->stream_index >= (unsigned)s->nb_streams) {
            av_log(s, AV_LOG_ERROR, "Invalid stream index %d\n", pkt->stream_index);
            continue;
        st = s->streams[pkt->stream_index];
        if (update_wrap_reference(s, st, pkt->stream_index, pkt) && st->pts_wrap_behavior == AV_PTS_WRAP_SUB_OFFSET) {
            // correct first time stamps to negative values
            if (!is_relative(st->first_dts))
                st->first_dts = wrap_timestamp(st, st->first_dts);
            if (!is_relative(st->start_time))
                st->start_time = wrap_timestamp(st, st->start_time);
            if (!is_relative(st->cur_dts))
                st->cur_dts = wrap_timestamp(st, st->cur_dts);
        pkt->dts = wrap_timestamp(st, pkt->dts);
        pkt->pts = wrap_timestamp(st, pkt->pts);
        force_codec_ids(s, st);
        /* TODO: audio: time filter; video: frame reordering (pts != dts) */
        if (s->use_wallclock_as_timestamps)
            pkt->dts = pkt->pts = av_rescale_q(av_gettime(), AV_TIME_BASE_Q, st->time_base);
        if (!pktl && st->request_probe <= 0)
            return ret;
        err = add_to_pktbuf(&s->internal->raw_packet_buffer, pkt,
                            &s->internal->raw_packet_buffer_end, 0);
        if (err)
            return err;
        s->internal->raw_packet_buffer_remaining_size -= pkt->size;
        if ((err = probe_codec(s, st, pkt)) < 0)
            return err;

int av_read_frame(AVFormatContext *s, AVPacket *pkt)

{

    const int genpts = s->flags & AVFMT_FLAG_GENPTS;

    int          eof = 0;

    int ret;

    AVStream *st;



    if (!genpts) {

        ret = s->packet_buffer ?

            read_from_packet_buffer(&s->packet_buffer, &s->packet_buffer_end, pkt) :

            read_frame_internal(s, pkt);

        if (ret < 0)

            return ret;

        goto return_packet;

    }



    for (;;) {

        AVPacketList *pktl = s->packet_buffer;



        if (pktl) {

            AVPacket *next_pkt = &pktl->pkt;



            if (next_pkt->dts != AV_NOPTS_VALUE) {

                int wrap_bits = s->streams[next_pkt->stream_index]->pts_wrap_bits;

                // last dts seen for this stream. if any of packets following

                // current one had no dts, we will set this to AV_NOPTS_VALUE.

                int64_t last_dts = next_pkt->dts;

                while (pktl && next_pkt->pts == AV_NOPTS_VALUE) {

                    if (pktl->pkt.stream_index == next_pkt->stream_index &&

                        (av_compare_mod(next_pkt->dts, pktl->pkt.dts, 2LL << (wrap_bits - 1)) < 0)) {

                        if (av_compare_mod(pktl->pkt.pts, pktl->pkt.dts, 2LL << (wrap_bits - 1))) { //not b frame

                            next_pkt->pts = pktl->pkt.dts;

                        }

                        if (last_dts != AV_NOPTS_VALUE) {

                            // Once last dts was set to AV_NOPTS_VALUE, we don't change it.

                            last_dts = pktl->pkt.dts;

                        }

                    }

                    pktl = pktl->next;

                }

                if (eof && next_pkt->pts == AV_NOPTS_VALUE && last_dts != AV_NOPTS_VALUE) {

                    // Fixing the last reference frame had none pts issue (For MXF etc).

                    // We only do this when

                    // 1. eof.

                    // 2. we are not able to resolve a pts value for current packet.

                    // 3. the packets for this stream at the end of the files had valid dts.

                    next_pkt->pts = last_dts + next_pkt->duration;

                }

                pktl = s->packet_buffer;

            }



            /* read packet from packet buffer, if there is data */

            if (!(next_pkt->pts == AV_NOPTS_VALUE &&

                  next_pkt->dts != AV_NOPTS_VALUE && !eof)) {

                ret = read_from_packet_buffer(&s->packet_buffer,

                                               &s->packet_buffer_end, pkt);

                goto return_packet;

            }

        }



        ret = read_frame_internal(s, pkt);

        if (ret < 0) {

            if (pktl && ret != AVERROR(EAGAIN)) {

                eof = 1;

                continue;

            } else

                return ret;

        }



        if (av_dup_packet(add_to_pktbuf(&s->packet_buffer, pkt,

                          &s->packet_buffer_end)) < 0)

            return AVERROR(ENOMEM);

    }



return_packet:



    st = s->streams[pkt->stream_index];

    if (st->skip_samples) {

        uint8_t *p = av_packet_new_side_data(pkt, AV_PKT_DATA_SKIP_SAMPLES, 10);

        AV_WL32(p, st->skip_samples);

        av_log(s, AV_LOG_DEBUG, "demuxer injecting skip %d\n", st->skip_samples);

        st->skip_samples = 0;

    }



    if ((s->iformat->flags & AVFMT_GENERIC_INDEX) && pkt->flags & AV_PKT_FLAG_KEY) {

        ff_reduce_index(s, st->index);

        av_add_index_entry(st, pkt->pos, pkt->dts, 0, 0, AVINDEX_KEYFRAME);

    }



    if (is_relative(pkt->dts))

        pkt->dts -= RELATIVE_TS_BASE;

    if (is_relative(pkt->pts))

        pkt->pts -= RELATIVE_TS_BASE;



    return ret;

}

int av_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret, i;

    AVStream *st;



    for(;;){

        AVPacketList *pktl = s->raw_packet_buffer;



        if (pktl) {

            *pkt = pktl->pkt;

            if(s->streams[pkt->stream_index]->codec->codec_id != CODEC_ID_PROBE ||

               !s->streams[pkt->stream_index]->probe_packets){

                s->raw_packet_buffer = pktl->next;

                av_free(pktl);

                return 0;

            }

        }



        av_init_packet(pkt);

        ret= s->iformat->read_packet(s, pkt);

        if (ret < 0) {

            if (!pktl || ret == AVERROR(EAGAIN))

                return ret;

            for (i = 0; i < s->nb_streams; i++)

                s->streams[i]->probe_packets = 0;

            continue;

        }

        st= s->streams[pkt->stream_index];



        switch(st->codec->codec_type){

        case CODEC_TYPE_VIDEO:

            if(s->video_codec_id)   st->codec->codec_id= s->video_codec_id;

            break;

        case CODEC_TYPE_AUDIO:

            if(s->audio_codec_id)   st->codec->codec_id= s->audio_codec_id;

            break;

        case CODEC_TYPE_SUBTITLE:

            if(s->subtitle_codec_id)st->codec->codec_id= s->subtitle_codec_id;

            break;

        }



        if(!pktl && (st->codec->codec_id != CODEC_ID_PROBE ||

                     !st->probe_packets))

            return ret;



        add_to_pktbuf(&s->raw_packet_buffer, pkt, &s->raw_packet_buffer_end);



        if(st->codec->codec_id == CODEC_ID_PROBE){

            AVProbeData *pd = &st->probe_data;



            --st->probe_packets;



            pd->buf = av_realloc(pd->buf, pd->buf_size+pkt->size+AVPROBE_PADDING_SIZE);

            memcpy(pd->buf+pd->buf_size, pkt->data, pkt->size);

            pd->buf_size += pkt->size;

            memset(pd->buf+pd->buf_size, 0, AVPROBE_PADDING_SIZE);



            if(av_log2(pd->buf_size) != av_log2(pd->buf_size - pkt->size)){

                set_codec_from_probe_data(st, pd, 1);

                if(st->codec->codec_id != CODEC_ID_PROBE){

                    pd->buf_size=0;

                    av_freep(&pd->buf);

                }

            }

        }

    }

}

int ff_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret, i, err;

    AVStream *st;



    for (;;) {

        AVPacketList *pktl = s->internal->raw_packet_buffer;



        if (pktl) {

            *pkt = pktl->pkt;

            st   = s->streams[pkt->stream_index];

            if (s->internal->raw_packet_buffer_remaining_size <= 0)

                if ((err = probe_codec(s, st, NULL)) < 0)

                    return err;

            if (st->request_probe <= 0) {

                s->internal->raw_packet_buffer                 = pktl->next;

                s->internal->raw_packet_buffer_remaining_size += pkt->size;

                av_free(pktl);

                return 0;

            }

        }



        pkt->data = NULL;

        pkt->size = 0;

        av_init_packet(pkt);

        ret = s->iformat->read_packet(s, pkt);

        if (ret < 0) {

            /* Some demuxers return FFERROR_REDO when they consume

               data and discard it (ignored streams, junk, extradata).

               We must re-call the demuxer to get the real packet. */

            if (ret == FFERROR_REDO)

                continue;

            if (!pktl || ret == AVERROR(EAGAIN))

                return ret;

            for (i = 0; i < s->nb_streams; i++) {

                st = s->streams[i];

                if (st->probe_packets)

                    if ((err = probe_codec(s, st, NULL)) < 0)

                        return err;

                av_assert0(st->request_probe <= 0);

            }

            continue;

        }



        if (!pkt->buf) {

            AVPacket tmp = { 0 };

            ret = av_packet_ref(&tmp, pkt);

            if (ret < 0)

                return ret;

            *pkt = tmp;

        }



        if ((s->flags & AVFMT_FLAG_DISCARD_CORRUPT) &&

            (pkt->flags & AV_PKT_FLAG_CORRUPT)) {

            av_log(s, AV_LOG_WARNING,

                   "Dropped corrupted packet (stream = %d)\n",

                   pkt->stream_index);

            av_packet_unref(pkt);

            continue;

        }



        if (pkt->stream_index >= (unsigned)s->nb_streams) {

            av_log(s, AV_LOG_ERROR, "Invalid stream index %d\n", pkt->stream_index);

            continue;

        }



        st = s->streams[pkt->stream_index];



        if (update_wrap_reference(s, st, pkt->stream_index, pkt) && st->pts_wrap_behavior == AV_PTS_WRAP_SUB_OFFSET) {

            // correct first time stamps to negative values

            if (!is_relative(st->first_dts))

                st->first_dts = wrap_timestamp(st, st->first_dts);

            if (!is_relative(st->start_time))

                st->start_time = wrap_timestamp(st, st->start_time);

            if (!is_relative(st->cur_dts))

                st->cur_dts = wrap_timestamp(st, st->cur_dts);

        }



        pkt->dts = wrap_timestamp(st, pkt->dts);

        pkt->pts = wrap_timestamp(st, pkt->pts);



        force_codec_ids(s, st);



        /* TODO: audio: time filter; video: frame reordering (pts != dts) */

        if (s->use_wallclock_as_timestamps)

            pkt->dts = pkt->pts = av_rescale_q(av_gettime(), AV_TIME_BASE_Q, st->time_base);



        if (!pktl && st->request_probe <= 0)

            return ret;



        err = add_to_pktbuf(&s->internal->raw_packet_buffer, pkt,

                            &s->internal->raw_packet_buffer_end, 0);

        if (err)

            return err;

        s->internal->raw_packet_buffer_remaining_size -= pkt->size;



        if ((err = probe_codec(s, st, pkt)) < 0)

            return err;

    }

}

