static int webvtt_event_to_ass(AVBPrint *buf, const char *p)

{

    int i, again, skip = 0;



    while (*p) {



        for (i = 0; i < FF_ARRAY_ELEMS(webvtt_tag_replace); i++) {

            const char *from = webvtt_tag_replace[i].from;

            const size_t len = strlen(from);

            if (!strncmp(p, from, len)) {

                av_bprintf(buf, "%s", webvtt_tag_replace[i].to);

                p += len;

                again = 1;

                break;

            }

        }

        if (!*p)

            break;



        if (again) {

            again = 0;

            skip = 0;

            continue;

        }

        if (*p == '<')

            skip = 1;

        else if (*p == '>')

            skip = 0;

        else if (p[0] == '\n' && p[1])

            av_bprintf(buf, "\\N");

        else if (!skip && *p != '\r')

            av_bprint_chars(buf, *p, 1);

        p++;

    }

    return 0;

}

static void do_sendkey(const char *string)

{

    uint8_t keycodes[16];

    int nb_keycodes = 0;

    char keyname_buf[16];

    char *separator;

    int keyname_len, keycode, i;



    while (1) {

        separator = strchr(string, '-');

        keyname_len = separator ? separator - string : strlen(string);

        if (keyname_len > 0) {

            pstrcpy(keyname_buf, sizeof(keyname_buf), string);

            if (keyname_len > sizeof(keyname_buf) - 1) {

                term_printf("invalid key: '%s...'\n", keyname_buf);

                return;

            }

            if (nb_keycodes == sizeof(keycodes)) {

                term_printf("too many keys\n");

                return;

            }

            keyname_buf[keyname_len] = 0;

            keycode = get_keycode(keyname_buf);

            if (keycode < 0) {

                term_printf("unknown key: '%s'\n", keyname_buf);

                return;

            }

            keycodes[nb_keycodes++] = keycode;

        }

        if (!separator)

            break;

        string = separator + 1;

    }

    /* key down events */

    for(i = 0; i < nb_keycodes; i++) {

        keycode = keycodes[i];

        if (keycode & 0x80)

            kbd_put_keycode(0xe0);

        kbd_put_keycode(keycode & 0x7f);

    }

    /* key up events */

    for(i = nb_keycodes - 1; i >= 0; i--) {

        keycode = keycodes[i];

        if (keycode & 0x80)

            kbd_put_keycode(0xe0);

        kbd_put_keycode(keycode | 0x80);

    }

}

static void release_keys(void *opaque)

{

    int keycode;



    while (nb_pending_keycodes > 0) {

        nb_pending_keycodes--;

        keycode = keycodes[nb_pending_keycodes];

        if (keycode & 0x80)

            kbd_put_keycode(0xe0);

        kbd_put_keycode(keycode | 0x80);

    }

}

void do_migrate_set_speed(Monitor *mon, const QDict *qdict)

{

    double d;

    char *ptr;

    FdMigrationState *s;

    const char *value = qdict_get_str(qdict, "value");



    d = strtod(value, &ptr);

    switch (*ptr) {

    case 'G': case 'g':

        d *= 1024;

    case 'M': case 'm':

        d *= 1024;

    case 'K': case 'k':

        d *= 1024;

    default:

        break;

    }



    max_throttle = (uint32_t)d;



    s = migrate_to_fms(current_migration);

    if (s && s->file) {

        qemu_file_set_rate_limit(s->file, max_throttle);

    }

}

int do_migrate_set_speed(Monitor *mon, const QDict *qdict, QObject **ret_data)

{

    int64_t d;

    FdMigrationState *s;



    d = qdict_get_int(qdict, "value");

    d = MAX(0, MIN(UINT32_MAX, d));

    max_throttle = d;



    s = migrate_to_fms(current_migration);

    if (s && s->file) {

        qemu_file_set_rate_limit(s->file, max_throttle);

    }



    return 0;

}

void do_info_migrate(Monitor *mon, QObject **ret_data)

{

    QDict *qdict;

    MigrationState *s = current_migration;



    if (s) {

        switch (s->get_status(s)) {

        case MIG_STATE_ACTIVE:

            qdict = qdict_new();

            qdict_put(qdict, "status", qstring_from_str("active"));



            migrate_put_status(qdict, "ram", ram_bytes_transferred(),

                               ram_bytes_remaining(), ram_bytes_total());



            if (blk_mig_active()) {

                migrate_put_status(qdict, "disk", blk_mig_bytes_transferred(),

                                   blk_mig_bytes_remaining(),

                                   blk_mig_bytes_total());

            }



            *ret_data = QOBJECT(qdict);

            break;

        case MIG_STATE_COMPLETED:

            *ret_data = qobject_from_jsonf("{ 'status': 'completed' }");

            break;

        case MIG_STATE_ERROR:

            *ret_data = qobject_from_jsonf("{ 'status': 'failed' }");

            break;

        case MIG_STATE_CANCELLED:

            *ret_data = qobject_from_jsonf("{ 'status': 'cancelled' }");

            break;

        }

        assert(*ret_data != NULL);

    }

}

void do_migrate_set_downtime(Monitor *mon, const QDict *qdict)

{

    char *ptr;

    double d;

    const char *value = qdict_get_str(qdict, "value");



    d = strtod(value, &ptr);

    if (!strcmp(ptr,"ms")) {

        d *= 1000000;

    } else if (!strcmp(ptr,"us")) {

        d *= 1000;

    } else if (!strcmp(ptr,"ns")) {

    } else {

        /* all else considered to be seconds */

        d *= 1000000000;

    }



    max_downtime = (uint64_t)d;

}

