static void rtas_set_indicator(PowerPCCPU *cpu, sPAPRMachineState *spapr,

                               uint32_t token, uint32_t nargs,

                               target_ulong args, uint32_t nret,

                               target_ulong rets)

{

    uint32_t sensor_type;

    uint32_t sensor_index;

    uint32_t sensor_state;

    uint32_t ret = RTAS_OUT_SUCCESS;

    sPAPRDRConnector *drc;

    sPAPRDRConnectorClass *drck;



    if (nargs != 3 || nret != 1) {

        ret = RTAS_OUT_PARAM_ERROR;

        goto out;

    }



    sensor_type = rtas_ld(args, 0);

    sensor_index = rtas_ld(args, 1);

    sensor_state = rtas_ld(args, 2);



    if (!sensor_type_is_dr(sensor_type)) {

        goto out_unimplemented;

    }



    /* if this is a DR sensor we can assume sensor_index == drc_index */

    drc = spapr_drc_by_index(sensor_index);

    if (!drc) {

        trace_spapr_rtas_set_indicator_invalid(sensor_index);

        ret = RTAS_OUT_PARAM_ERROR;

        goto out;

    }

    drck = SPAPR_DR_CONNECTOR_GET_CLASS(drc);



    switch (sensor_type) {

    case RTAS_SENSOR_TYPE_ISOLATION_STATE:

        ret = drck->set_isolation_state(drc, sensor_state);

        break;

    case RTAS_SENSOR_TYPE_DR:

        ret = drck->set_indicator_state(drc, sensor_state);

        break;

    case RTAS_SENSOR_TYPE_ALLOCATION_STATE:

        ret = drck->set_allocation_state(drc, sensor_state);

        break;

    default:

        goto out_unimplemented;

    }



out:

    rtas_st(rets, 0, ret);

    return;



out_unimplemented:

    /* currently only DR-related sensors are implemented */

    trace_spapr_rtas_set_indicator_not_supported(sensor_index, sensor_type);

    rtas_st(rets, 0, RTAS_OUT_NOT_SUPPORTED);

}

static void tcg_out_setcond_i32(TCGContext *s, TCGCond cond, TCGReg ret,

                                TCGReg c1, int32_t c2, int c2const)

{

    /* For 32-bit comparisons, we can play games with ADDX/SUBX.  */

    switch (cond) {

    case TCG_COND_LTU:

    case TCG_COND_GEU:

        /* The result of the comparison is in the carry bit.  */

        break;



    case TCG_COND_EQ:

    case TCG_COND_NE:

        /* For equality, we can transform to inequality vs zero.  */

        if (c2 != 0) {

            tcg_out_arithc(s, ret, c1, c2, c2const, ARITH_XOR);

        }

        c1 = TCG_REG_G0, c2 = ret, c2const = 0;

        cond = (cond == TCG_COND_EQ ? TCG_COND_GEU : TCG_COND_LTU);

	break;



    case TCG_COND_GTU:

    case TCG_COND_LEU:

        /* If we don't need to load a constant into a register, we can

           swap the operands on GTU/LEU.  There's no benefit to loading

           the constant into a temporary register.  */

        if (!c2const || c2 == 0) {

            TCGReg t = c1;

            c1 = c2;

            c2 = t;

            c2const = 0;

            cond = tcg_swap_cond(cond);

            break;

        }

        /* FALLTHRU */



    default:

        tcg_out_cmp(s, c1, c2, c2const);

        tcg_out_movi_imm13(s, ret, 0);

        tcg_out_movcc(s, cond, MOVCC_ICC, ret, 1, 1);

        return;

    }



    tcg_out_cmp(s, c1, c2, c2const);

    if (cond == TCG_COND_LTU) {

        tcg_out_arithi(s, ret, TCG_REG_G0, 0, ARITH_ADDX);

    } else {

        tcg_out_arithi(s, ret, TCG_REG_G0, -1, ARITH_SUBX);

    }

}

static inline void tcg_out_qemu_st(TCGContext *s, int cond,

                const TCGArg *args, int opc)

{

    int addr_reg, data_reg, data_reg2;

#ifdef CONFIG_SOFTMMU

    int mem_index, s_bits;

# if TARGET_LONG_BITS == 64

    int addr_reg2;

# endif

    uint32_t *label_ptr;

#endif



    data_reg = *args++;

    if (opc == 3)

        data_reg2 = *args++;

    else

        data_reg2 = 0; /* surpress warning */

    addr_reg = *args++;

#if TARGET_LONG_BITS == 64

    addr_reg2 = *args++;

#endif

#ifdef CONFIG_SOFTMMU

    mem_index = *args;

    s_bits = opc & 3;



    /* Should generate something like the following:

     *  shr r8, addr_reg, #TARGET_PAGE_BITS

     *  and r0, r8, #(CPU_TLB_SIZE - 1)   @ Assumption: CPU_TLB_BITS <= 8

     *  add r0, env, r0 lsl #CPU_TLB_ENTRY_BITS

     */

    tcg_out_dat_reg(s, COND_AL, ARITH_MOV,

                    8, 0, addr_reg, SHIFT_IMM_LSR(TARGET_PAGE_BITS));

    tcg_out_dat_imm(s, COND_AL, ARITH_AND,

                    0, 8, CPU_TLB_SIZE - 1);

    tcg_out_dat_reg(s, COND_AL, ARITH_ADD,

                    0, TCG_AREG0, 0, SHIFT_IMM_LSL(CPU_TLB_ENTRY_BITS));

    /* In the

     *  ldr r1 [r0, #(offsetof(CPUState, tlb_table[mem_index][0].addr_write))]

     * below, the offset is likely to exceed 12 bits if mem_index != 0 and

     * not exceed otherwise, so use an

     *  add r0, r0, #(mem_index * sizeof *CPUState.tlb_table)

     * before.

     */

    if (mem_index)

        tcg_out_dat_imm(s, COND_AL, ARITH_ADD, 0, 0,

                        (mem_index << (TLB_SHIFT & 1)) |

                        ((16 - (TLB_SHIFT >> 1)) << 8));

    tcg_out_ld32_12(s, COND_AL, 1, 0,

                    offsetof(CPUState, tlb_table[0][0].addr_write));

    tcg_out_dat_reg(s, COND_AL, ARITH_CMP,

                    0, 1, 8, SHIFT_IMM_LSL(TARGET_PAGE_BITS));

    /* Check alignment.  */

    if (s_bits)

        tcg_out_dat_imm(s, COND_EQ, ARITH_TST,

                        0, addr_reg, (1 << s_bits) - 1);

#  if TARGET_LONG_BITS == 64

    /* XXX: possibly we could use a block data load or writeback in

     * the first access.  */

    tcg_out_ld32_12(s, COND_EQ, 1, 0,

                    offsetof(CPUState, tlb_table[0][0].addr_write)

                    + 4);

    tcg_out_dat_reg(s, COND_EQ, ARITH_CMP,

                    0, 1, addr_reg2, SHIFT_IMM_LSL(0));

#  endif

    tcg_out_ld32_12(s, COND_EQ, 1, 0,

                    offsetof(CPUState, tlb_table[0][0].addend));



    switch (opc) {

    case 0:

        tcg_out_st8_r(s, COND_EQ, data_reg, addr_reg, 1);

        break;

    case 0 | 4:

        tcg_out_st8s_r(s, COND_EQ, data_reg, addr_reg, 1);

        break;

    case 1:

        tcg_out_st16u_r(s, COND_EQ, data_reg, addr_reg, 1);

        break;

    case 1 | 4:

        tcg_out_st16s_r(s, COND_EQ, data_reg, addr_reg, 1);

        break;

    case 2:

    default:

        tcg_out_st32_r(s, COND_EQ, data_reg, addr_reg, 1);

        break;

    case 3:

        tcg_out_st32_rwb(s, COND_EQ, data_reg, 1, addr_reg);

        tcg_out_st32_12(s, COND_EQ, data_reg2, 1, 4);

        break;

    }



    label_ptr = (void *) s->code_ptr;

    tcg_out_b(s, COND_EQ, 8);



    /* TODO: move this code to where the constants pool will be */

    if (addr_reg)

        tcg_out_dat_reg(s, cond, ARITH_MOV,

                        0, 0, addr_reg, SHIFT_IMM_LSL(0));

# if TARGET_LONG_BITS == 32

    switch (opc) {

    case 0:

        tcg_out_dat_imm(s, cond, ARITH_AND, 1, data_reg, 0xff);

        tcg_out_dat_imm(s, cond, ARITH_MOV, 2, 0, mem_index);

        break;

    case 1:

        tcg_out_dat_reg(s, cond, ARITH_MOV,

                        1, 0, data_reg, SHIFT_IMM_LSL(16));

        tcg_out_dat_reg(s, cond, ARITH_MOV,

                        1, 0, 1, SHIFT_IMM_LSR(16));

        tcg_out_dat_imm(s, cond, ARITH_MOV, 2, 0, mem_index);

        break;

    case 2:

        if (data_reg != 1)

            tcg_out_dat_reg(s, cond, ARITH_MOV,

                            1, 0, data_reg, SHIFT_IMM_LSL(0));

        tcg_out_dat_imm(s, cond, ARITH_MOV, 2, 0, mem_index);

        break;

    case 3:

        if (data_reg != 1)

            tcg_out_dat_reg(s, cond, ARITH_MOV,

                            1, 0, data_reg, SHIFT_IMM_LSL(0));

        if (data_reg2 != 2)

            tcg_out_dat_reg(s, cond, ARITH_MOV,

                            2, 0, data_reg2, SHIFT_IMM_LSL(0));

        tcg_out_dat_imm(s, cond, ARITH_MOV, 3, 0, mem_index);

        break;

    }

# else

    if (addr_reg2 != 1)

        tcg_out_dat_reg(s, cond, ARITH_MOV,

                        1, 0, addr_reg2, SHIFT_IMM_LSL(0));

    switch (opc) {

    case 0:

        tcg_out_dat_imm(s, cond, ARITH_AND, 2, data_reg, 0xff);

        tcg_out_dat_imm(s, cond, ARITH_MOV, 3, 0, mem_index);

        break;

    case 1:

        tcg_out_dat_reg(s, cond, ARITH_MOV,

                        2, 0, data_reg, SHIFT_IMM_LSL(16));

        tcg_out_dat_reg(s, cond, ARITH_MOV,

                        2, 0, 2, SHIFT_IMM_LSR(16));

        tcg_out_dat_imm(s, cond, ARITH_MOV, 3, 0, mem_index);

        break;

    case 2:

        if (data_reg != 2)

            tcg_out_dat_reg(s, cond, ARITH_MOV,

                            2, 0, data_reg, SHIFT_IMM_LSL(0));

        tcg_out_dat_imm(s, cond, ARITH_MOV, 3, 0, mem_index);

        break;

    case 3:

        tcg_out_dat_imm(s, cond, ARITH_MOV, 8, 0, mem_index);

        tcg_out32(s, (cond << 28) | 0x052d8010); /* str r8, [sp, #-0x10]! */

        if (data_reg != 2)

            tcg_out_dat_reg(s, cond, ARITH_MOV,

                            2, 0, data_reg, SHIFT_IMM_LSL(0));

        if (data_reg2 != 3)

            tcg_out_dat_reg(s, cond, ARITH_MOV,

                            3, 0, data_reg2, SHIFT_IMM_LSL(0));

        break;

    }

# endif



# ifdef SAVE_LR

    tcg_out_dat_reg(s, cond, ARITH_MOV, 8, 0, 14, SHIFT_IMM_LSL(0));

# endif



    tcg_out_bl(s, cond, (tcg_target_long) qemu_st_helpers[s_bits] -

                    (tcg_target_long) s->code_ptr);



# if TARGET_LONG_BITS == 64

    if (opc == 3)

        tcg_out_dat_imm(s, cond, ARITH_ADD, 13, 13, 0x10);

# endif



# ifdef SAVE_LR

    tcg_out_dat_reg(s, cond, ARITH_MOV, 14, 0, 8, SHIFT_IMM_LSL(0));

# endif



    *label_ptr += ((void *) s->code_ptr - (void *) label_ptr - 8) >> 2;

#else

    switch (opc) {

    case 0:

        tcg_out_st8_12(s, COND_AL, data_reg, addr_reg, 0);

        break;

    case 0 | 4:

        tcg_out_st8s_8(s, COND_AL, data_reg, addr_reg, 0);

        break;

    case 1:

        tcg_out_st16u_8(s, COND_AL, data_reg, addr_reg, 0);

        break;

    case 1 | 4:

        tcg_out_st16s_8(s, COND_AL, data_reg, addr_reg, 0);

        break;

    case 2:

    default:

        tcg_out_st32_12(s, COND_AL, data_reg, addr_reg, 0);

        break;

    case 3:

        /* TODO: use block store -

         * check that data_reg2 > data_reg or the other way */

        tcg_out_st32_12(s, COND_AL, data_reg, addr_reg, 0);

        tcg_out_st32_12(s, COND_AL, data_reg2, addr_reg, 4);

        break;

    }

#endif

}

static void tcg_out_qemu_ld(TCGContext *s, TCGReg data, TCGReg addr,

                            TCGMemOpIdx oi, bool is_64)

{

    TCGMemOp memop = get_memop(oi);

#ifdef CONFIG_SOFTMMU

    unsigned memi = get_mmuidx(oi);

    TCGReg addrz, param;

    tcg_insn_unit *func;

    tcg_insn_unit *label_ptr;



    addrz = tcg_out_tlb_load(s, addr, memi, memop & MO_SIZE,

                             offsetof(CPUTLBEntry, addr_read));



    /* The fast path is exactly one insn.  Thus we can perform the

       entire TLB Hit in the (annulled) delay slot of the branch

       over the TLB Miss case.  */



    /* beq,a,pt %[xi]cc, label0 */

    label_ptr = s->code_ptr;

    tcg_out_bpcc0(s, COND_E, BPCC_A | BPCC_PT

                  | (TARGET_LONG_BITS == 64 ? BPCC_XCC : BPCC_ICC), 0);

    /* delay slot */

    tcg_out_ldst_rr(s, data, addrz, TCG_REG_O1,

                    qemu_ld_opc[memop & (MO_BSWAP | MO_SSIZE)]);



    /* TLB Miss.  */



    param = TCG_REG_O1;

    if (!SPARC64 && TARGET_LONG_BITS == 64) {

        /* Skip the high-part; we'll perform the extract in the trampoline.  */

        param++;

    }

    tcg_out_mov(s, TCG_TYPE_REG, param++, addr);



    /* We use the helpers to extend SB and SW data, leaving the case

       of SL needing explicit extending below.  */

    if ((memop & MO_SSIZE) == MO_SL) {

        func = qemu_ld_trampoline[memop & (MO_BSWAP | MO_SIZE)];

    } else {

        func = qemu_ld_trampoline[memop & (MO_BSWAP | MO_SSIZE)];

    }

    assert(func != NULL);

    tcg_out_call_nodelay(s, func);

    /* delay slot */

    tcg_out_movi(s, TCG_TYPE_I32, param, oi);



    /* Recall that all of the helpers return 64-bit results.

       Which complicates things for sparcv8plus.  */

    if (SPARC64) {

        /* We let the helper sign-extend SB and SW, but leave SL for here.  */

        if (is_64 && (memop & MO_SSIZE) == MO_SL) {

            tcg_out_arithi(s, data, TCG_REG_O0, 0, SHIFT_SRA);

        } else {

            tcg_out_mov(s, TCG_TYPE_REG, data, TCG_REG_O0);

        }

    } else {

        if ((memop & MO_SIZE) == MO_64) {

            tcg_out_arithi(s, TCG_REG_O0, TCG_REG_O0, 32, SHIFT_SLLX);

            tcg_out_arithi(s, TCG_REG_O1, TCG_REG_O1, 0, SHIFT_SRL);

            tcg_out_arith(s, data, TCG_REG_O0, TCG_REG_O1, ARITH_OR);

        } else if (is_64) {

            /* Re-extend from 32-bit rather than reassembling when we

               know the high register must be an extension.  */

            tcg_out_arithi(s, data, TCG_REG_O1, 0,

                           memop & MO_SIGN ? SHIFT_SRA : SHIFT_SRL);

        } else {

            tcg_out_mov(s, TCG_TYPE_I32, data, TCG_REG_O1);

        }

    }



    *label_ptr |= INSN_OFF19(tcg_ptr_byte_diff(s->code_ptr, label_ptr));

#else

    if (SPARC64 && TARGET_LONG_BITS == 32) {

        tcg_out_arithi(s, TCG_REG_T1, addr, 0, SHIFT_SRL);

        addr = TCG_REG_T1;

    }

    tcg_out_ldst_rr(s, data, addr,

                    (guest_base ? TCG_GUEST_BASE_REG : TCG_REG_G0),

                    qemu_ld_opc[memop & (MO_BSWAP | MO_SSIZE)]);

#endif /* CONFIG_SOFTMMU */

}

static void tcg_out_setcond2(TCGContext *s, const TCGArg *args,

                             const int *const_args)

{

    TCGArg new_args[6];

    int label_true, label_over;



    memcpy(new_args, args+1, 5*sizeof(TCGArg));



    if (args[0] == args[1] || args[0] == args[2]

        || (!const_args[3] && args[0] == args[3])

        || (!const_args[4] && args[0] == args[4])) {

        /* When the destination overlaps with one of the argument

           registers, don't do anything tricky.  */

        label_true = label_arg(gen_new_label());

        label_over = label_arg(gen_new_label());



        new_args[5] = label_true;

        tcg_out_brcond2(s, new_args, const_args+1, 1);



        tcg_out_movi(s, TCG_TYPE_I32, args[0], 0);

        tcg_out_jxx(s, JCC_JMP, label_over, 1);

        tcg_out_label(s, label_true, s->code_ptr);



        tcg_out_movi(s, TCG_TYPE_I32, args[0], 1);

        tcg_out_label(s, label_over, s->code_ptr);

    } else {

        /* When the destination does not overlap one of the arguments,

           clear the destination first, jump if cond false, and emit an

           increment in the true case.  This results in smaller code.  */



        tcg_out_movi(s, TCG_TYPE_I32, args[0], 0);



        label_over = label_arg(gen_new_label());

        new_args[4] = tcg_invert_cond(new_args[4]);

        new_args[5] = label_over;

        tcg_out_brcond2(s, new_args, const_args+1, 1);



        tgen_arithi(s, ARITH_ADD, args[0], 1, 0);

        tcg_out_label(s, label_over, s->code_ptr);

    }

}

