static void start_children(FFServerStream *feed)

{

    char *pathname;

    char *slash;

    int i;

    size_t cmd_length;



    if (no_launch)

        return;



    cmd_length = strlen(my_program_name);



   /**

    * FIXME: WIP Safeguard. Remove after clearing all harcoded

    * '1024' path lengths

    */

    if (cmd_length > PATH_LENGTH - 1) {

        http_log("Could not start children. Command line: '%s' exceeds "

                    "path length limit (%d)\n", my_program_name, PATH_LENGTH);

        return;

    }



    pathname = av_strdup (my_program_name);

    if (!pathname) {

        http_log("Could not allocate memory for children cmd line\n");

        return;

    }

   /* replace "ffserver" with "ffmpeg" in the path of current

    * program. Ignore user provided path */



    slash = strrchr(pathname, '/');

    if (!slash)

        slash = pathname;

    else

        slash++;

    strcpy(slash, "ffmpeg");



    for (; feed; feed = feed->next) {



        if (!feed->child_argv || feed->pid)

            continue;



        feed->pid_start = time(0);



        feed->pid = fork();

        if (feed->pid < 0) {

            http_log("Unable to create children: %s\n", strerror(errno));

            av_free (pathname);

            exit(EXIT_FAILURE);

        }



        if (feed->pid)

            continue;



        /* In child */



        http_log("Launch command line: ");

        http_log("%s ", pathname);



        for (i = 1; feed->child_argv[i] && feed->child_argv[i][0]; i++)

            http_log("%s ", feed->child_argv[i]);

        http_log("\n");



        for (i = 3; i < 256; i++)

            close(i);



        if (!config.debug) {

            if (!freopen("/dev/null", "r", stdin))

                http_log("failed to redirect STDIN to /dev/null\n;");

            if (!freopen("/dev/null", "w", stdout))

                http_log("failed to redirect STDOUT to /dev/null\n;");

            if (!freopen("/dev/null", "w", stderr))

                http_log("failed to redirect STDERR to /dev/null\n;");

        }



        signal(SIGPIPE, SIG_DFL);

        execvp(pathname, feed->child_argv);

        av_free (pathname);

        _exit(1);

    }

    av_free (pathname);

}

static void bios_supports_mode(const char *pmutils_bin, const char *pmutils_arg,

                               const char *sysfile_str, Error **err)

{

    pid_t pid;

    ssize_t ret;

    char *pmutils_path;

    int status, pipefds[2];



    if (pipe(pipefds) < 0) {

        error_set(err, QERR_UNDEFINED_ERROR);

        return;

    }



    pmutils_path = g_find_program_in_path(pmutils_bin);



    pid = fork();

    if (!pid) {

        struct sigaction act;



        memset(&act, 0, sizeof(act));

        act.sa_handler = SIG_DFL;

        sigaction(SIGCHLD, &act, NULL);



        setsid();

        close(pipefds[0]);

        reopen_fd_to_null(0);

        reopen_fd_to_null(1);

        reopen_fd_to_null(2);



        pid = fork();

        if (!pid) {

            int fd;

            char buf[32]; /* hopefully big enough */



            if (pmutils_path) {

                execle(pmutils_path, pmutils_bin, pmutils_arg, NULL, environ);

            }



            /*

             * If we get here either pm-utils is not installed or execle() has

             * failed. Let's try the manual method if the caller wants it.

             */



            if (!sysfile_str) {

                _exit(SUSPEND_NOT_SUPPORTED);

            }



            fd = open(LINUX_SYS_STATE_FILE, O_RDONLY);

            if (fd < 0) {

                _exit(SUSPEND_NOT_SUPPORTED);

            }



            ret = read(fd, buf, sizeof(buf)-1);

            if (ret <= 0) {

                _exit(SUSPEND_NOT_SUPPORTED);

            }

            buf[ret] = '\0';



            if (strstr(buf, sysfile_str)) {

                _exit(SUSPEND_SUPPORTED);

            }



            _exit(SUSPEND_NOT_SUPPORTED);

        }



        if (pid > 0) {

            wait(&status);

        } else {

            status = SUSPEND_NOT_SUPPORTED;

        }



        ret = write(pipefds[1], &status, sizeof(status));

        if (ret != sizeof(status)) {

            _exit(EXIT_FAILURE);

        }



        _exit(EXIT_SUCCESS);

    }



    close(pipefds[1]);

    g_free(pmutils_path);



    if (pid < 0) {

        error_set(err, QERR_UNDEFINED_ERROR);

        goto out;

    }



    ret = read(pipefds[0], &status, sizeof(status));

    if (ret == sizeof(status) && WIFEXITED(status) &&

        WEXITSTATUS(status) == SUSPEND_SUPPORTED) {

            goto out;

    }



    error_set(err, QERR_UNSUPPORTED);



out:

    close(pipefds[0]);

}

static rwpipe *rwpipe_open( int argc, char *argv[] )

{

    rwpipe *this = av_mallocz( sizeof( rwpipe ) );



    if ( this != NULL )

    {

        int input[ 2 ];

        int output[ 2 ];



        pipe( input );

        pipe( output );



        this->pid = fork();



        if ( this->pid == 0 )

        {

#define COMMAND_SIZE 10240

            char *command = av_mallocz( COMMAND_SIZE );

            int i;



            strcpy( command, "" );

            for ( i = 0; i < argc; i ++ )

            {

                av_strlcat( command, argv[ i ], COMMAND_SIZE );

                av_strlcat( command, " ", COMMAND_SIZE );

            }



            dup2( output[ 0 ], STDIN_FILENO );

            dup2( input[ 1 ], STDOUT_FILENO );



            close( input[ 0 ] );

            close( input[ 1 ] );

            close( output[ 0 ] );

            close( output[ 1 ] );



            execl("/bin/sh", "sh", "-c", command, (char*)NULL );

            _exit( 255 );

        }

        else

        {

            close( input[ 1 ] );

            close( output[ 0 ] );



            this->reader = fdopen( input[ 0 ], "r" );

            this->writer = fdopen( output[ 1 ], "w" );

        }

    }



    return this;

}

static int mov_open_dref(AVIOContext **pb, char *src, MOVDref *ref,

                         AVIOInterruptCB *int_cb)

{

    /* try relative path, we do not try the absolute because it can leak information about our

       system to an attacker */

    if (ref->nlvl_to > 0 && ref->nlvl_from > 0) {

        char filename[1024];

        char *src_path;

        int i, l;



        /* find a source dir */

        src_path = strrchr(src, '/');

        if (src_path)

            src_path++;

        else

            src_path = src;



        /* find a next level down to target */

        for (i = 0, l = strlen(ref->path) - 1; l >= 0; l--)

            if (ref->path[l] == '/') {

                if (i == ref->nlvl_to - 1)

                    break;

                else

                    i++;

            }



        /* compose filename if next level down to target was found */

        if (i == ref->nlvl_to - 1 && src_path - src  < sizeof(filename)) {

            memcpy(filename, src, src_path - src);

            filename[src_path - src] = 0;



            for (i = 1; i < ref->nlvl_from; i++)

                av_strlcat(filename, "../", 1024);



            av_strlcat(filename, ref->path + l + 1, 1024);



            if (!avio_open2(pb, filename, AVIO_FLAG_READ, int_cb, NULL))

                return 0;

        }

    }



    return AVERROR(ENOENT);

}

