void ff_wms_parse_sdp_a_line(AVFormatContext *s, const char *p)

{

    if (av_strstart(p, "pgmpu:data:application/vnd.ms.wms-hdr.asfv1;base64,", &p)) {

        ByteIOContext pb;

        RTSPState *rt = s->priv_data;

        int len = strlen(p) * 6 / 8;

        char *buf = av_mallocz(len);

        av_base64_decode(buf, p, len);



        if (rtp_asf_fix_header(buf, len) < 0)

            av_log(s, AV_LOG_ERROR,

                   "Failed to fix invalid RTSP-MS/ASF min_pktsize\n");

        init_packetizer(&pb, buf, len);

        if (rt->asf_ctx) {

            av_close_input_stream(rt->asf_ctx);

            rt->asf_ctx = NULL;

        }

        av_open_input_stream(&rt->asf_ctx, &pb, "", &asf_demuxer, NULL);

        rt->asf_pb_pos = url_ftell(&pb);

        av_free(buf);

        rt->asf_ctx->pb = NULL;

    }

}

static int read_ffserver_streams(OptionsContext *o, AVFormatContext *s, const char *filename)

{

    int i, err;

    AVFormatContext *ic = avformat_alloc_context();





    ic->interrupt_callback = int_cb;

    err = avformat_open_input(&ic, filename, NULL, NULL);

    if (err < 0)

        return err;

    /* copy stream format */

    for(i=0;i<ic->nb_streams;i++) {

        AVStream *st;

        OutputStream *ost;

        AVCodec *codec;

        const char *enc_config;



        codec = avcodec_find_encoder(ic->streams[i]->codecpar->codec_id);

        if (!codec) {

            av_log(s, AV_LOG_ERROR, "no encoder found for codec id %i\n", ic->streams[i]->codecpar->codec_id);

            return AVERROR(EINVAL);

        }

        if (codec->type == AVMEDIA_TYPE_AUDIO)

            opt_audio_codec(o, "c:a", codec->name);

        else if (codec->type == AVMEDIA_TYPE_VIDEO)

            opt_video_codec(o, "c:v", codec->name);

        ost   = new_output_stream(o, s, codec->type, -1);

        st    = ost->st;



        avcodec_get_context_defaults3(st->codec, codec);

        enc_config = av_stream_get_recommended_encoder_configuration(ic->streams[i]);

        if (enc_config) {

            AVDictionary *opts = NULL;

            av_dict_parse_string(&opts, enc_config, "=", ",", 0);

            av_opt_set_dict2(st->codec, &opts, AV_OPT_SEARCH_CHILDREN);

            av_dict_free(&opts);

        }



        if (st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO && !ost->stream_copy)

            choose_sample_fmt(st, codec);

        else if (st->codecpar->codec_type == AVMEDIA_TYPE_VIDEO && !ost->stream_copy)

            choose_pixel_fmt(st, st->codec, codec, st->codecpar->format);

        avcodec_copy_context(ost->enc_ctx, st->codec);

        if (enc_config)

            av_dict_parse_string(&ost->encoder_opts, enc_config, "=", ",", 0);

    }



    avformat_close_input(&ic);

    return err;

}

int ff_wms_parse_sdp_a_line(AVFormatContext *s, const char *p)

{

    int ret = 0;

    if (av_strstart(p, "pgmpu:data:application/vnd.ms.wms-hdr.asfv1;base64,", &p)) {

        AVIOContext pb;

        RTSPState *rt = s->priv_data;

        AVDictionary *opts = NULL;

        int len = strlen(p) * 6 / 8;

        char *buf = av_mallocz(len);

        av_base64_decode(buf, p, len);



        if (rtp_asf_fix_header(buf, len) < 0)

            av_log(s, AV_LOG_ERROR,

                   "Failed to fix invalid RTSP-MS/ASF min_pktsize\n");

        init_packetizer(&pb, buf, len);

        if (rt->asf_ctx) {

            avformat_close_input(&rt->asf_ctx);

        }

        if (!(rt->asf_ctx = avformat_alloc_context()))

            return AVERROR(ENOMEM);

        rt->asf_ctx->pb      = &pb;

        av_dict_set(&opts, "no_resync_search", "1", 0);

        ret = avformat_open_input(&rt->asf_ctx, "", &ff_asf_demuxer, &opts);

        av_dict_free(&opts);

        if (ret < 0)

            return ret;

        av_dict_copy(&s->metadata, rt->asf_ctx->metadata, 0);

        rt->asf_pb_pos = avio_tell(&pb);

        av_free(buf);

        rt->asf_ctx->pb = NULL;

    }

    return ret;

}

static int put_flac_codecpriv(AVFormatContext *s,

                              AVIOContext *pb, AVCodecContext *codec)

{

    int write_comment = (codec->channel_layout &&

                         !(codec->channel_layout & ~0x3ffffULL) &&

                         !ff_flac_is_native_layout(codec->channel_layout));

    int ret = ff_flac_write_header(pb, codec->extradata, codec->extradata_size,

                                   !write_comment);



    if (ret < 0)

        return ret;



    if (write_comment) {

        const char *vendor = (s->flags & AVFMT_FLAG_BITEXACT) ?

                             "Lavf" : LIBAVFORMAT_IDENT;

        AVDictionary *dict = NULL;

        uint8_t buf[32], *data, *p;

        int len;



        snprintf(buf, sizeof(buf), "0x%"PRIx64, codec->channel_layout);

        av_dict_set(&dict, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK", buf, 0);



        len = ff_vorbiscomment_length(dict, vendor);

        data = av_malloc(len + 4);

        if (!data) {

            av_dict_free(&dict);

            return AVERROR(ENOMEM);

        }



        data[0] = 0x84;

        AV_WB24(data + 1, len);



        p = data + 4;

        ff_vorbiscomment_write(&p, &dict, vendor);



        avio_write(pb, data, len + 4);



        av_freep(&data);

        av_dict_free(&dict);

    }



    return 0;

}

static int ra144_decode_frame(AVCodecContext * avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    static const uint8_t sizes[LPC_ORDER] = {6, 5, 5, 4, 4, 3, 3, 3, 3, 2};

    unsigned int refl_rms[NBLOCKS];           // RMS of the reflection coefficients

    int16_t block_coefs[NBLOCKS][LPC_ORDER];  // LPC coefficients of each sub-block

    unsigned int lpc_refl[LPC_ORDER];         // LPC reflection coefficients of the frame

    int i, j;

    int ret;

    int16_t *samples;

    unsigned int energy;



    RA144Context *ractx = avctx->priv_data;

    GetBitContext gb;



    if (buf_size < FRAME_SIZE) {

        av_log(avctx, AV_LOG_ERROR,

               "Frame too small (%d bytes). Truncated file?\n", buf_size);

        *got_frame_ptr = 0;

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    frame->nb_samples = NBLOCKS * BLOCKSIZE;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;

    samples = (int16_t *)frame->data[0];



    init_get_bits8(&gb, buf, FRAME_SIZE);



    for (i = 0; i < LPC_ORDER; i++)

        lpc_refl[i] = ff_lpc_refl_cb[i][get_bits(&gb, sizes[i])];



    ff_eval_coefs(ractx->lpc_coef[0], lpc_refl);

    ractx->lpc_refl_rms[0] = ff_rms(lpc_refl);



    energy = ff_energy_tab[get_bits(&gb, 5)];



    refl_rms[0] = ff_interp(ractx, block_coefs[0], 1, 1, ractx->old_energy);

    refl_rms[1] = ff_interp(ractx, block_coefs[1], 2,

                            energy <= ractx->old_energy,

                            ff_t_sqrt(energy*ractx->old_energy) >> 12);

    refl_rms[2] = ff_interp(ractx, block_coefs[2], 3, 0, energy);

    refl_rms[3] = ff_rescale_rms(ractx->lpc_refl_rms[0], energy);



    ff_int_to_int16(block_coefs[3], ractx->lpc_coef[0]);



    for (i=0; i < NBLOCKS; i++) {

        do_output_subblock(ractx, block_coefs[i], refl_rms[i], &gb);



        for (j=0; j < BLOCKSIZE; j++)

            *samples++ = av_clip_int16(ractx->curr_sblock[j + 10] << 2);

    }



    ractx->old_energy = energy;

    ractx->lpc_refl_rms[1] = ractx->lpc_refl_rms[0];



    FFSWAP(unsigned int *, ractx->lpc_coef[0], ractx->lpc_coef[1]);



    *got_frame_ptr = 1;



    return FRAME_SIZE;

}

static void ra144_encode_subblock(RA144Context *ractx,

                                  const int16_t *sblock_data,

                                  const int16_t *lpc_coefs, unsigned int rms,

                                  PutBitContext *pb)

{

    float data[BLOCKSIZE] = { 0 }, work[LPC_ORDER + BLOCKSIZE];

    float coefs[LPC_ORDER];

    float zero[BLOCKSIZE], cba[BLOCKSIZE], cb1[BLOCKSIZE], cb2[BLOCKSIZE];

    int16_t cba_vect[BLOCKSIZE];

    int cba_idx, cb1_idx, cb2_idx, gain;

    int i, n;

    unsigned m[3];

    float g[3];

    float error, best_error;



    for (i = 0; i < LPC_ORDER; i++) {

        work[i] = ractx->curr_sblock[BLOCKSIZE + i];

        coefs[i] = lpc_coefs[i] * (1/4096.0);

    }



    /**

     * Calculate the zero-input response of the LPC filter and subtract it from

     * input data.

     */

    ff_celp_lp_synthesis_filterf(work + LPC_ORDER, coefs, data, BLOCKSIZE,

                                 LPC_ORDER);

    for (i = 0; i < BLOCKSIZE; i++) {

        zero[i] = work[LPC_ORDER + i];

        data[i] = sblock_data[i] - zero[i];

    }



    /**

     * Codebook search is performed without taking into account the contribution

     * of the previous subblock, since it has been just subtracted from input

     * data.

     */

    memset(work, 0, LPC_ORDER * sizeof(*work));



    cba_idx = adaptive_cb_search(ractx->adapt_cb, work + LPC_ORDER, coefs,

                                 data);

    if (cba_idx) {

        /**

         * The filtered vector from the adaptive codebook can be retrieved from

         * work, see implementation of adaptive_cb_search().

         */

        memcpy(cba, work + LPC_ORDER, sizeof(cba));



        ff_copy_and_dup(cba_vect, ractx->adapt_cb, cba_idx + BLOCKSIZE / 2 - 1);

        m[0] = (ff_irms(cba_vect) * rms) >> 12;

    }

    fixed_cb_search(work + LPC_ORDER, coefs, data, cba_idx, &cb1_idx, &cb2_idx);

    for (i = 0; i < BLOCKSIZE; i++) {

        cb1[i] = ff_cb1_vects[cb1_idx][i];

        cb2[i] = ff_cb2_vects[cb2_idx][i];

    }

    ff_celp_lp_synthesis_filterf(work + LPC_ORDER, coefs, cb1, BLOCKSIZE,

                                 LPC_ORDER);

    memcpy(cb1, work + LPC_ORDER, sizeof(cb1));

    m[1] = (ff_cb1_base[cb1_idx] * rms) >> 8;

    ff_celp_lp_synthesis_filterf(work + LPC_ORDER, coefs, cb2, BLOCKSIZE,

                                 LPC_ORDER);

    memcpy(cb2, work + LPC_ORDER, sizeof(cb2));

    m[2] = (ff_cb2_base[cb2_idx] * rms) >> 8;

    best_error = FLT_MAX;

    gain = 0;

    for (n = 0; n < 256; n++) {

        g[1] = ((ff_gain_val_tab[n][1] * m[1]) >> ff_gain_exp_tab[n]) *

               (1/4096.0);

        g[2] = ((ff_gain_val_tab[n][2] * m[2]) >> ff_gain_exp_tab[n]) *

               (1/4096.0);

        error = 0;

        if (cba_idx) {

            g[0] = ((ff_gain_val_tab[n][0] * m[0]) >> ff_gain_exp_tab[n]) *

                   (1/4096.0);

            for (i = 0; i < BLOCKSIZE; i++) {

                data[i] = zero[i] + g[0] * cba[i] + g[1] * cb1[i] +

                          g[2] * cb2[i];

                error += (data[i] - sblock_data[i]) *

                         (data[i] - sblock_data[i]);

            }

        } else {

            for (i = 0; i < BLOCKSIZE; i++) {

                data[i] = zero[i] + g[1] * cb1[i] + g[2] * cb2[i];

                error += (data[i] - sblock_data[i]) *

                         (data[i] - sblock_data[i]);

            }

        }

        if (error < best_error) {

            best_error = error;

            gain = n;

        }

    }

    put_bits(pb, 7, cba_idx);

    put_bits(pb, 8, gain);

    put_bits(pb, 7, cb1_idx);

    put_bits(pb, 7, cb2_idx);

    ff_subblock_synthesis(ractx, lpc_coefs, cba_idx, cb1_idx, cb2_idx, rms,

                          gain);

}

static int ra144_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                              const AVFrame *frame, int *got_packet_ptr)

{

    static const uint8_t sizes[LPC_ORDER] = {64, 32, 32, 16, 16, 8, 8, 8, 8, 4};

    static const uint8_t bit_sizes[LPC_ORDER] = {6, 5, 5, 4, 4, 3, 3, 3, 3, 2};

    RA144Context *ractx = avctx->priv_data;

    PutBitContext pb;

    int32_t lpc_data[NBLOCKS * BLOCKSIZE];

    int32_t lpc_coefs[LPC_ORDER][MAX_LPC_ORDER];

    int shift[LPC_ORDER];

    int16_t block_coefs[NBLOCKS][LPC_ORDER];

    int lpc_refl[LPC_ORDER];    /**< reflection coefficients of the frame */

    unsigned int refl_rms[NBLOCKS]; /**< RMS of the reflection coefficients */

    const int16_t *samples = frame ? (const int16_t *)frame->data[0] : NULL;

    int energy = 0;

    int i, idx, ret;



    if (ractx->last_frame)

        return 0;



    if ((ret = ff_alloc_packet2(avctx, avpkt, FRAMESIZE)))

        return ret;



    /**

     * Since the LPC coefficients are calculated on a frame centered over the

     * fourth subframe, to encode a given frame, data from the next frame is

     * needed. In each call to this function, the previous frame (whose data are

     * saved in the encoder context) is encoded, and data from the current frame

     * are saved in the encoder context to be used in the next function call.

     */

    for (i = 0; i < (2 * BLOCKSIZE + BLOCKSIZE / 2); i++) {

        lpc_data[i] = ractx->curr_block[BLOCKSIZE + BLOCKSIZE / 2 + i];

        energy += (lpc_data[i] * lpc_data[i]) >> 4;

    }

    if (frame) {

        int j;

        for (j = 0; j < frame->nb_samples && i < NBLOCKS * BLOCKSIZE; i++, j++) {

            lpc_data[i] = samples[j] >> 2;

            energy += (lpc_data[i] * lpc_data[i]) >> 4;

        }

    }

    if (i < NBLOCKS * BLOCKSIZE)

        memset(&lpc_data[i], 0, (NBLOCKS * BLOCKSIZE - i) * sizeof(*lpc_data));

    energy = ff_energy_tab[quantize(ff_t_sqrt(energy >> 5) >> 10, ff_energy_tab,

                                    32)];



    ff_lpc_calc_coefs(&ractx->lpc_ctx, lpc_data, NBLOCKS * BLOCKSIZE, LPC_ORDER,

                      LPC_ORDER, 16, lpc_coefs, shift, FF_LPC_TYPE_LEVINSON,

                      0, ORDER_METHOD_EST, 12, 0);

    for (i = 0; i < LPC_ORDER; i++)

        block_coefs[NBLOCKS - 1][i] = -(lpc_coefs[LPC_ORDER - 1][i] <<

                                        (12 - shift[LPC_ORDER - 1]));



    /**

     * TODO: apply perceptual weighting of the input speech through bandwidth

     * expansion of the LPC filter.

     */



    if (ff_eval_refl(lpc_refl, block_coefs[NBLOCKS - 1], avctx)) {

        /**

         * The filter is unstable: use the coefficients of the previous frame.

         */

        ff_int_to_int16(block_coefs[NBLOCKS - 1], ractx->lpc_coef[1]);

        if (ff_eval_refl(lpc_refl, block_coefs[NBLOCKS - 1], avctx)) {

            /* the filter is still unstable. set reflection coeffs to zero. */

            memset(lpc_refl, 0, sizeof(lpc_refl));

        }

    }

    init_put_bits(&pb, avpkt->data, avpkt->size);

    for (i = 0; i < LPC_ORDER; i++) {

        idx = quantize(lpc_refl[i], ff_lpc_refl_cb[i], sizes[i]);

        put_bits(&pb, bit_sizes[i], idx);

        lpc_refl[i] = ff_lpc_refl_cb[i][idx];

    }

    ractx->lpc_refl_rms[0] = ff_rms(lpc_refl);

    ff_eval_coefs(ractx->lpc_coef[0], lpc_refl);

    refl_rms[0] = ff_interp(ractx, block_coefs[0], 1, 1, ractx->old_energy);

    refl_rms[1] = ff_interp(ractx, block_coefs[1], 2,

                            energy <= ractx->old_energy,

                            ff_t_sqrt(energy * ractx->old_energy) >> 12);

    refl_rms[2] = ff_interp(ractx, block_coefs[2], 3, 0, energy);

    refl_rms[3] = ff_rescale_rms(ractx->lpc_refl_rms[0], energy);

    ff_int_to_int16(block_coefs[NBLOCKS - 1], ractx->lpc_coef[0]);

    put_bits(&pb, 5, quantize(energy, ff_energy_tab, 32));

    for (i = 0; i < NBLOCKS; i++)

        ra144_encode_subblock(ractx, ractx->curr_block + i * BLOCKSIZE,

                              block_coefs[i], refl_rms[i], &pb);

    flush_put_bits(&pb);

    ractx->old_energy = energy;

    ractx->lpc_refl_rms[1] = ractx->lpc_refl_rms[0];

    FFSWAP(unsigned int *, ractx->lpc_coef[0], ractx->lpc_coef[1]);



    /* copy input samples to current block for processing in next call */

    i = 0;

    if (frame) {

        for (; i < frame->nb_samples; i++)

            ractx->curr_block[i] = samples[i] >> 2;



        if ((ret = ff_af_queue_add(&ractx->afq, frame)) < 0)

            return ret;

    } else

        ractx->last_frame = 1;

    memset(&ractx->curr_block[i], 0,

           (NBLOCKS * BLOCKSIZE - i) * sizeof(*ractx->curr_block));



    /* Get the next frame pts/duration */

    ff_af_queue_remove(&ractx->afq, avctx->frame_size, &avpkt->pts,

                       &avpkt->duration);



    avpkt->size = FRAMESIZE;

    *got_packet_ptr = 1;

    return 0;

}

static int ra144_decode_frame(AVCodecContext * avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    static const uint8_t sizes[LPC_ORDER] = {6, 5, 5, 4, 4, 3, 3, 3, 3, 2};

    unsigned int refl_rms[NBLOCKS];           // RMS of the reflection coefficients

    uint16_t block_coefs[NBLOCKS][LPC_ORDER]; // LPC coefficients of each sub-block

    unsigned int lpc_refl[LPC_ORDER];         // LPC reflection coefficients of the frame

    int i, j;

    int ret;

    int16_t *samples;

    unsigned int energy;



    RA144Context *ractx = avctx->priv_data;

    GetBitContext gb;



    /* get output buffer */

    frame->nb_samples = NBLOCKS * BLOCKSIZE;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = (int16_t *)frame->data[0];



    if(buf_size < FRAMESIZE) {

        av_log(avctx, AV_LOG_ERROR,

               "Frame too small (%d bytes). Truncated file?\n", buf_size);

        *got_frame_ptr = 0;

        return buf_size;

    }

    init_get_bits(&gb, buf, FRAMESIZE * 8);



    for (i = 0; i < LPC_ORDER; i++)

        lpc_refl[i] = ff_lpc_refl_cb[i][get_bits(&gb, sizes[i])];



    ff_eval_coefs(ractx->lpc_coef[0], lpc_refl);

    ractx->lpc_refl_rms[0] = ff_rms(lpc_refl);



    energy = ff_energy_tab[get_bits(&gb, 5)];



    refl_rms[0] = ff_interp(ractx, block_coefs[0], 1, 1, ractx->old_energy);

    refl_rms[1] = ff_interp(ractx, block_coefs[1], 2,

                            energy <= ractx->old_energy,

                            ff_t_sqrt(energy*ractx->old_energy) >> 12);

    refl_rms[2] = ff_interp(ractx, block_coefs[2], 3, 0, energy);

    refl_rms[3] = ff_rescale_rms(ractx->lpc_refl_rms[0], energy);



    ff_int_to_int16(block_coefs[3], ractx->lpc_coef[0]);



    for (i=0; i < NBLOCKS; i++) {

        do_output_subblock(ractx, block_coefs[i], refl_rms[i], &gb);



        for (j=0; j < BLOCKSIZE; j++)

            *samples++ = av_clip_int16(ractx->curr_sblock[j + 10] << 2);

    }



    ractx->old_energy = energy;

    ractx->lpc_refl_rms[1] = ractx->lpc_refl_rms[0];



    FFSWAP(unsigned int *, ractx->lpc_coef[0], ractx->lpc_coef[1]);



    *got_frame_ptr = 1;



    return FRAMESIZE;

}

static inline void range_dec_normalize(APEContext *ctx)

{

    while (ctx->rc.range <= BOTTOM_VALUE) {

        ctx->rc.buffer <<= 8;

        if(ctx->ptr < ctx->data_end)

            ctx->rc.buffer += *ctx->ptr;

        ctx->ptr++;

        ctx->rc.low    = (ctx->rc.low << 8)    | ((ctx->rc.buffer >> 1) & 0xFF);

        ctx->rc.range  <<= 8;

    }

}

static void cin_decode_rle(const unsigned char *src, int src_size, unsigned char *dst, int dst_size)

{

    int len, code;

    unsigned char *dst_end = dst + dst_size;

    const unsigned char *src_end = src + src_size;



    while (src < src_end && dst < dst_end) {

        code = *src++;

        if (code & 0x80) {

            len = code - 0x7F;

            memset(dst, *src++, FFMIN(len, dst_end - dst));

        } else {

            len = code + 1;

            memcpy(dst, src, FFMIN(len, dst_end - dst));

            src += len;

        }

        dst += len;

    }

}

static void decode(GetByteContext *gb, RangeCoder *rc, unsigned cumFreq, unsigned freq, unsigned total_freq)

{

    rc->code -= cumFreq * rc->range;

    rc->range *= freq;



    while (rc->range < TOP && bytestream2_get_bytes_left(gb) > 0) {

        unsigned byte = bytestream2_get_byte(gb);

        rc->code = (rc->code << 8) | byte;

        rc->range <<= 8;

    }

}

static inline void cow_set_bits(uint8_t *bitmap, int start, int64_t nb_sectors)

{

    int64_t bitnum = start, last = start + nb_sectors;

    while (bitnum < last) {

        if ((bitnum & 7) == 0 && bitnum + 8 <= last) {

            bitmap[bitnum / 8] = 0xFF;

            bitnum += 8;

            continue;

        }

        bitmap[bitnum/8] |= (1 << (bitnum % 8));

        bitnum++;

    }

}

static int dmg_open(BlockDriverState *bs, int flags)

{

    BDRVDMGState *s = bs->opaque;

    off_t info_begin,info_end,last_in_offset,last_out_offset;

    uint32_t count;

    uint32_t max_compressed_size=1,max_sectors_per_chunk=1,i;

    int64_t offset;



    bs->read_only = 1;

    s->n_chunks = 0;

    s->offsets = s->lengths = s->sectors = s->sectorcounts = NULL;



    /* read offset of info blocks */

    offset = bdrv_getlength(bs->file);

    if (offset < 0) {

        goto fail;

    }

    offset -= 0x1d8;



    info_begin = read_off(bs, offset);

    if (info_begin == 0) {

	goto fail;

    }



    if (read_uint32(bs, info_begin) != 0x100) {

        goto fail;

    }



    count = read_uint32(bs, info_begin + 4);

    if (count == 0) {

        goto fail;

    }

    info_end = info_begin + count;



    offset = info_begin + 0x100;



    /* read offsets */

    last_in_offset = last_out_offset = 0;

    while (offset < info_end) {

        uint32_t type;



	count = read_uint32(bs, offset);

	if(count==0)

	    goto fail;

        offset += 4;



	type = read_uint32(bs, offset);

	if (type == 0x6d697368 && count >= 244) {

	    int new_size, chunk_count;



            offset += 4;

            offset += 200;



	    chunk_count = (count-204)/40;

	    new_size = sizeof(uint64_t) * (s->n_chunks + chunk_count);

	    s->types = g_realloc(s->types, new_size/2);

	    s->offsets = g_realloc(s->offsets, new_size);

	    s->lengths = g_realloc(s->lengths, new_size);

	    s->sectors = g_realloc(s->sectors, new_size);

	    s->sectorcounts = g_realloc(s->sectorcounts, new_size);



	    for(i=s->n_chunks;i<s->n_chunks+chunk_count;i++) {

		s->types[i] = read_uint32(bs, offset);

		offset += 4;

		if(s->types[i]!=0x80000005 && s->types[i]!=1 && s->types[i]!=2) {

		    if(s->types[i]==0xffffffff) {

			last_in_offset = s->offsets[i-1]+s->lengths[i-1];

			last_out_offset = s->sectors[i-1]+s->sectorcounts[i-1];

		    }

		    chunk_count--;

		    i--;

		    offset += 36;

		    continue;

		}

		offset += 4;



		s->sectors[i] = last_out_offset+read_off(bs, offset);

		offset += 8;



		s->sectorcounts[i] = read_off(bs, offset);

		offset += 8;



		s->offsets[i] = last_in_offset+read_off(bs, offset);

		offset += 8;



		s->lengths[i] = read_off(bs, offset);

		offset += 8;



		if(s->lengths[i]>max_compressed_size)

		    max_compressed_size = s->lengths[i];

		if(s->sectorcounts[i]>max_sectors_per_chunk)

		    max_sectors_per_chunk = s->sectorcounts[i];

	    }

	    s->n_chunks+=chunk_count;

	}

    }



    /* initialize zlib engine */

    s->compressed_chunk = g_malloc(max_compressed_size+1);

    s->uncompressed_chunk = g_malloc(512*max_sectors_per_chunk);

    if(inflateInit(&s->zstream) != Z_OK)

	goto fail;



    s->current_chunk = s->n_chunks;



    qemu_co_mutex_init(&s->lock);

    return 0;

fail:

    return -1;

}

static int cloop_open(BlockDriverState *bs, int flags)

{

    BDRVCloopState *s = bs->opaque;

    uint32_t offsets_size, max_compressed_block_size = 1, i;



    bs->read_only = 1;



    /* read header */

    if (bdrv_pread(bs->file, 128, &s->block_size, 4) < 4) {

        goto cloop_close;

    }

    s->block_size = be32_to_cpu(s->block_size);



    if (bdrv_pread(bs->file, 128 + 4, &s->n_blocks, 4) < 4) {

        goto cloop_close;

    }

    s->n_blocks = be32_to_cpu(s->n_blocks);



    /* read offsets */

    offsets_size = s->n_blocks * sizeof(uint64_t);

    s->offsets = g_malloc(offsets_size);

    if (bdrv_pread(bs->file, 128 + 4 + 4, s->offsets, offsets_size) <

            offsets_size) {

        goto cloop_close;

    }

    for(i=0;i<s->n_blocks;i++) {

        s->offsets[i] = be64_to_cpu(s->offsets[i]);

        if (i > 0) {

            uint32_t size = s->offsets[i] - s->offsets[i - 1];

            if (size > max_compressed_block_size) {

                max_compressed_block_size = size;

            }

        }

    }



    /* initialize zlib engine */

    s->compressed_block = g_malloc(max_compressed_block_size + 1);

    s->uncompressed_block = g_malloc(s->block_size);

    if (inflateInit(&s->zstream) != Z_OK) {

        goto cloop_close;

    }

    s->current_block = s->n_blocks;



    s->sectors_per_block = s->block_size/512;

    bs->total_sectors = s->n_blocks * s->sectors_per_block;

    qemu_co_mutex_init(&s->lock);

    return 0;



cloop_close:

    return -1;

}

static int dmg_open(BlockDriverState *bs, QDict *options, int flags,

                    Error **errp)

{

    BDRVDMGState *s = bs->opaque;

    DmgHeaderState ds;

    uint64_t rsrc_fork_offset, rsrc_fork_length;

    uint64_t plist_xml_offset, plist_xml_length;

    int64_t offset;

    int ret;



    bs->file = bdrv_open_child(NULL, options, "file", bs, &child_file,

                               false, errp);

    if (!bs->file) {

        return -EINVAL;

    }



    block_module_load_one("dmg-bz2");

    bs->read_only = true;



    s->n_chunks = 0;

    s->offsets = s->lengths = s->sectors = s->sectorcounts = NULL;

    /* used by dmg_read_mish_block to keep track of the current I/O position */

    ds.data_fork_offset = 0;

    ds.max_compressed_size = 1;

    ds.max_sectors_per_chunk = 1;



    /* locate the UDIF trailer */

    offset = dmg_find_koly_offset(bs->file, errp);

    if (offset < 0) {

        ret = offset;

        goto fail;

    }



    /* offset of data fork (DataForkOffset) */

    ret = read_uint64(bs, offset + 0x18, &ds.data_fork_offset);

    if (ret < 0) {

        goto fail;

    } else if (ds.data_fork_offset > offset) {

        ret = -EINVAL;

        goto fail;

    }



    /* offset of resource fork (RsrcForkOffset) */

    ret = read_uint64(bs, offset + 0x28, &rsrc_fork_offset);

    if (ret < 0) {

        goto fail;

    }

    ret = read_uint64(bs, offset + 0x30, &rsrc_fork_length);

    if (ret < 0) {

        goto fail;

    }

    if (rsrc_fork_offset >= offset ||

        rsrc_fork_length > offset - rsrc_fork_offset) {

        ret = -EINVAL;

        goto fail;

    }

    /* offset of property list (XMLOffset) */

    ret = read_uint64(bs, offset + 0xd8, &plist_xml_offset);

    if (ret < 0) {

        goto fail;

    }

    ret = read_uint64(bs, offset + 0xe0, &plist_xml_length);

    if (ret < 0) {

        goto fail;

    }

    if (plist_xml_offset >= offset ||

        plist_xml_length > offset - plist_xml_offset) {

        ret = -EINVAL;

        goto fail;

    }

    ret = read_uint64(bs, offset + 0x1ec, (uint64_t *)&bs->total_sectors);

    if (ret < 0) {

        goto fail;

    }

    if (bs->total_sectors < 0) {

        ret = -EINVAL;

        goto fail;

    }

    if (rsrc_fork_length != 0) {

        ret = dmg_read_resource_fork(bs, &ds,

                                     rsrc_fork_offset, rsrc_fork_length);

        if (ret < 0) {

            goto fail;

        }

    } else if (plist_xml_length != 0) {

        ret = dmg_read_plist_xml(bs, &ds, plist_xml_offset, plist_xml_length);

        if (ret < 0) {

            goto fail;

        }

    } else {

        ret = -EINVAL;

        goto fail;

    }



    /* initialize zlib engine */

    s->compressed_chunk = qemu_try_blockalign(bs->file->bs,

                                              ds.max_compressed_size + 1);

    s->uncompressed_chunk = qemu_try_blockalign(bs->file->bs,

                                                512 * ds.max_sectors_per_chunk);

    if (s->compressed_chunk == NULL || s->uncompressed_chunk == NULL) {

        ret = -ENOMEM;

        goto fail;

    }



    if (inflateInit(&s->zstream) != Z_OK) {

        ret = -EINVAL;

        goto fail;

    }



    s->current_chunk = s->n_chunks;



    qemu_co_mutex_init(&s->lock);

    return 0;



fail:

    g_free(s->types);

    g_free(s->offsets);

    g_free(s->lengths);

    g_free(s->sectors);

    g_free(s->sectorcounts);

    qemu_vfree(s->compressed_chunk);

    qemu_vfree(s->uncompressed_chunk);

    return ret;

}

static int dmg_open(BlockDriverState *bs, QDict *options, int flags,
                    Error **errp)
{
    BDRVDMGState *s = bs->opaque;
    uint64_t info_begin, info_end, last_in_offset, last_out_offset;
    uint32_t count, tmp;
    uint32_t max_compressed_size = 1, max_sectors_per_chunk = 1, i;
    int64_t offset;
    int ret;
    bs->read_only = 1;
    s->n_chunks = 0;
    s->offsets = s->lengths = s->sectors = s->sectorcounts = NULL;
    /* read offset of info blocks */
    offset = bdrv_getlength(bs->file);
    if (offset < 0) {
        ret = offset;
    offset -= 0x1d8;
    ret = read_uint64(bs, offset, &info_begin);
    if (ret < 0) {
    } else if (info_begin == 0) {
    ret = read_uint32(bs, info_begin, &tmp);
    if (ret < 0) {
    } else if (tmp != 0x100) {
    ret = read_uint32(bs, info_begin + 4, &count);
    if (ret < 0) {
    } else if (count == 0) {
    info_end = info_begin + count;
    offset = info_begin + 0x100;
    /* read offsets */
    last_in_offset = last_out_offset = 0;
    while (offset < info_end) {
        uint32_t type;
        ret = read_uint32(bs, offset, &count);
        if (ret < 0) {
        } else if (count == 0) {
        offset += 4;
        ret = read_uint32(bs, offset, &type);
        if (ret < 0) {
        if (type == 0x6d697368 && count >= 244) {
            size_t new_size;
            uint32_t chunk_count;
            offset += 4;
            offset += 200;
            chunk_count = (count - 204) / 40;
            new_size = sizeof(uint64_t) * (s->n_chunks + chunk_count);
            s->types = g_realloc(s->types, new_size / 2);
            s->offsets = g_realloc(s->offsets, new_size);
            s->lengths = g_realloc(s->lengths, new_size);
            s->sectors = g_realloc(s->sectors, new_size);
            s->sectorcounts = g_realloc(s->sectorcounts, new_size);
            for (i = s->n_chunks; i < s->n_chunks + chunk_count; i++) {
                ret = read_uint32(bs, offset, &s->types[i]);
                if (ret < 0) {
                offset += 4;
                if (s->types[i] != 0x80000005 && s->types[i] != 1 &&
                    s->types[i] != 2) {
                    if (s->types[i] == 0xffffffff && i > 0) {
                        last_in_offset = s->offsets[i - 1] + s->lengths[i - 1];
                        last_out_offset = s->sectors[i - 1] +
                                          s->sectorcounts[i - 1];
                    chunk_count--;
                    i--;
                    offset += 36;
                    continue;
                offset += 4;
                ret = read_uint64(bs, offset, &s->sectors[i]);
                if (ret < 0) {
                s->sectors[i] += last_out_offset;
                offset += 8;
                ret = read_uint64(bs, offset, &s->sectorcounts[i]);
                if (ret < 0) {
                offset += 8;
                if (s->sectorcounts[i] > DMG_SECTORCOUNTS_MAX) {
                    error_report("sector count %" PRIu64 " for chunk %u is "
                                 "larger than max (%u)",
                                 s->sectorcounts[i], i, DMG_SECTORCOUNTS_MAX);
                ret = read_uint64(bs, offset, &s->offsets[i]);
                if (ret < 0) {
                s->offsets[i] += last_in_offset;
                offset += 8;
                ret = read_uint64(bs, offset, &s->lengths[i]);
                if (ret < 0) {
                offset += 8;
                if (s->lengths[i] > max_compressed_size) {
                    max_compressed_size = s->lengths[i];
                if (s->sectorcounts[i] > max_sectors_per_chunk) {
                    max_sectors_per_chunk = s->sectorcounts[i];
            s->n_chunks += chunk_count;
    /* initialize zlib engine */
    s->compressed_chunk = g_malloc(max_compressed_size + 1);
    s->uncompressed_chunk = g_malloc(512 * max_sectors_per_chunk);
    if (inflateInit(&s->zstream) != Z_OK) {
    s->current_chunk = s->n_chunks;
    qemu_co_mutex_init(&s->lock);
    return 0;
fail:
    g_free(s->types);
    g_free(s->offsets);
    g_free(s->lengths);
    g_free(s->sectors);
    g_free(s->sectorcounts);
    g_free(s->compressed_chunk);
    g_free(s->uncompressed_chunk);
    return ret;

