static av_cold int flashsv_encode_init(AVCodecContext *avctx)

{

    FlashSVContext *s = avctx->priv_data;



    s->avctx = avctx;



    if (avctx->width > 4095 || avctx->height > 4095) {

        av_log(avctx, AV_LOG_ERROR,

               "Input dimensions too large, input must be max 4096x4096 !\n");

        return AVERROR_INVALIDDATA;

    }



    // Needed if zlib unused or init aborted before deflateInit

    memset(&s->zstream, 0, sizeof(z_stream));



    s->last_key_frame = 0;



    s->image_width  = avctx->width;

    s->image_height = avctx->height;



    s->tmpblock  = av_mallocz(3 * 256 * 256);

    s->encbuffer = av_mallocz(s->image_width * s->image_height * 3);



    if (!s->tmpblock || !s->encbuffer) {

        av_log(avctx, AV_LOG_ERROR, "Memory allocation failed.\n");

        return AVERROR(ENOMEM);

    }



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame) {

        flashsv_encode_end(avctx);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static void flush_change(H264Context *h)

{

    h->outputed_poc = h->next_outputed_poc = INT_MIN;

    h->prev_interlaced_frame = 1;

    idr(h);

    h->prev_frame_num = -1;

    if (h->s.current_picture_ptr)

        h->s.current_picture_ptr->f.reference = 0;

    h->s.first_field = 0;

    memset(h->ref_list[0], 0, sizeof(h->ref_list[0]));

    memset(h->ref_list[1], 0, sizeof(h->ref_list[1]));

    memset(h->default_ref_list[0], 0, sizeof(h->default_ref_list[0]));

    memset(h->default_ref_list[1], 0, sizeof(h->default_ref_list[1]));

    ff_h264_reset_sei(h);

    h->recovery_frame= -1;

    h->sync= 0;

    h->list_count = 0;

    h->current_slice = 0;

}

void ff_h264_free_tables(H264Context *h, int free_rbsp)

{

    int i;



    av_freep(&h->intra4x4_pred_mode);

    av_freep(&h->chroma_pred_mode_table);

    av_freep(&h->cbp_table);

    av_freep(&h->mvd_table[0]);

    av_freep(&h->mvd_table[1]);

    av_freep(&h->direct_table);

    av_freep(&h->non_zero_count);

    av_freep(&h->slice_table_base);

    h->slice_table = NULL;

    av_freep(&h->list_counts);



    av_freep(&h->mb2b_xy);

    av_freep(&h->mb2br_xy);



    av_buffer_pool_uninit(&h->qscale_table_pool);

    av_buffer_pool_uninit(&h->mb_type_pool);

    av_buffer_pool_uninit(&h->motion_val_pool);

    av_buffer_pool_uninit(&h->ref_index_pool);



    if (free_rbsp && h->DPB) {

        for (i = 0; i < H264_MAX_PICTURE_COUNT; i++)

            ff_h264_unref_picture(h, &h->DPB[i]);

        av_freep(&h->DPB);

    }



    h->cur_pic_ptr = NULL;



    for (i = 0; i < h->nb_slice_ctx; i++) {

        H264SliceContext *sl = &h->slice_ctx[i];



        av_freep(&sl->dc_val_base);

        av_freep(&sl->er.mb_index2xy);

        av_freep(&sl->er.error_status_table);

        av_freep(&sl->er.er_temp_buffer);



        av_freep(&sl->bipred_scratchpad);

        av_freep(&sl->edge_emu_buffer);

        av_freep(&sl->top_borders[0]);

        av_freep(&sl->top_borders[1]);



        sl->bipred_scratchpad_allocated = 0;

        sl->edge_emu_buffer_allocated   = 0;

        sl->top_borders_allocated[0]    = 0;

        sl->top_borders_allocated[1]    = 0;



        if (free_rbsp) {

            av_freep(&sl->rbsp_buffer);

            sl->rbsp_buffer_size            = 0;

        }

    }

}

static void flush_dpb(AVCodecContext *avctx)

{

    H264Context *h = avctx->priv_data;

    int i;



    memset(h->delayed_pic, 0, sizeof(h->delayed_pic));



    ff_h264_flush_change(h);



    if (h->DPB)

        for (i = 0; i < H264_MAX_PICTURE_COUNT; i++)

            ff_h264_unref_picture(h, &h->DPB[i]);

    h->cur_pic_ptr = NULL;

    ff_h264_unref_picture(h, &h->cur_pic);



    h->mb_y = 0;



    ff_h264_free_tables(h);

    h->context_initialized = 0;

}

static int h264_init_context(AVCodecContext *avctx, H264Context *h)

{

    int i;



    h->avctx                 = avctx;



    h->picture_structure     = PICT_FRAME;

    h->slice_context_count   = 1;

    h->workaround_bugs       = avctx->workaround_bugs;

    h->flags                 = avctx->flags;

    h->prev_poc_msb          = 1 << 16;

    h->x264_build            = -1;

    h->recovery_frame        = -1;

    h->frame_recovered       = 0;



    h->next_outputed_poc = INT_MIN;

    for (i = 0; i < MAX_DELAYED_PIC_COUNT; i++)

        h->last_pocs[i] = INT_MIN;



    ff_h264_reset_sei(h);



    avctx->chroma_sample_location = AVCHROMA_LOC_LEFT;



    h->nb_slice_ctx = (avctx->active_thread_type & FF_THREAD_SLICE) ?  H264_MAX_THREADS : 1;

    h->slice_ctx = av_mallocz_array(h->nb_slice_ctx, sizeof(*h->slice_ctx));

    if (!h->slice_ctx) {

        h->nb_slice_ctx = 0;

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < H264_MAX_PICTURE_COUNT; i++) {

        h->DPB[i].f = av_frame_alloc();

        if (!h->DPB[i].f)

            return AVERROR(ENOMEM);

    }



    h->cur_pic.f = av_frame_alloc();

    if (!h->cur_pic.f)

        return AVERROR(ENOMEM);



    for (i = 0; i < h->nb_slice_ctx; i++)

        h->slice_ctx[i].h264 = h;



    return 0;

}

static const AVOption *av_set_number(void *obj, const char *name, double num, int den, int64_t intnum){

    const AVOption *o= av_find_opt(obj, name, NULL, 0, 0);

    void *dst;

    if(!o || o->offset<=0)

        return NULL;



    if(o->max*den < num*intnum || o->min*den > num*intnum) {

        av_log(NULL, AV_LOG_ERROR, "Value %lf for parameter '%s' out of range\n", num, name);

        return NULL;

    }



    dst= ((uint8_t*)obj) + o->offset;



    switch(o->type){

    case FF_OPT_TYPE_FLAGS:

    case FF_OPT_TYPE_INT:   *(int       *)dst= llrint(num/den)*intnum; break;

    case FF_OPT_TYPE_INT64: *(int64_t   *)dst= llrint(num/den)*intnum; break;

    case FF_OPT_TYPE_FLOAT: *(float     *)dst= num*intnum/den;         break;

    case FF_OPT_TYPE_DOUBLE:*(double    *)dst= num*intnum/den;         break;

    case FF_OPT_TYPE_RATIONAL:

        if((int)num == num) *(AVRational*)dst= (AVRational){num*intnum, den};

        else                *(AVRational*)dst= av_d2q(num*intnum/den, 1<<24);

        break;

    default:

        return NULL;

    }

    return o;

}

static int write_number(void *obj, const AVOption *o, void *dst, double num, int den, int64_t intnum)

{

    if (o->max*den < num*intnum || o->min*den > num*intnum) {

        av_log(obj, AV_LOG_ERROR, "Value %f for parameter '%s' out of range\n",

               num*intnum/den, o->name);

        return AVERROR(ERANGE);

    }



    switch (o->type) {

    case AV_OPT_TYPE_FLAGS:

    case AV_OPT_TYPE_INT:   *(int       *)dst= llrint(num/den)*intnum; break;

    case AV_OPT_TYPE_INT64: *(int64_t   *)dst= llrint(num/den)*intnum; break;

    case AV_OPT_TYPE_FLOAT: *(float     *)dst= num*intnum/den;         break;

    case AV_OPT_TYPE_DOUBLE:*(double    *)dst= num*intnum/den;         break;

    case AV_OPT_TYPE_RATIONAL:

        if ((int)num == num) *(AVRational*)dst= (AVRational){num*intnum, den};

        else                 *(AVRational*)dst= av_d2q(num*intnum/den, 1<<24);

        break;

    default:

        return AVERROR(EINVAL);

    }

    return 0;

}

