static uint64_t omap_wd_timer_read(void *opaque, target_phys_addr_t addr,

                                   unsigned size)

{

    struct omap_watchdog_timer_s *s = (struct omap_watchdog_timer_s *) opaque;



    if (size != 2) {

        return omap_badwidth_read16(opaque, addr);

    }



    switch (addr) {

    case 0x00:	/* CNTL_TIMER */

        return (s->timer.ptv << 9) | (s->timer.ar << 8) |

                (s->timer.st << 7) | (s->free << 1);



    case 0x04:	/* READ_TIMER */

        return omap_timer_read(&s->timer);



    case 0x08:	/* TIMER_MODE */

        return s->mode << 15;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static void FUNC(sao_band_filter)(uint8_t *_dst, uint8_t *_src,

                                  ptrdiff_t stride, SAOParams *sao,

                                  int *borders, int width, int height,

                                  int c_idx, int class)

{

    pixel *dst = (pixel *)_dst;

    pixel *src = (pixel *)_src;

    int offset_table[32] = { 0 };

    int k, y, x;

    int chroma = !!c_idx;

    int shift  = BIT_DEPTH - 5;

    int *sao_offset_val = sao->offset_val[c_idx];

    int sao_left_class  = sao->band_position[c_idx];

    int init_y = 0, init_x = 0;



    stride /= sizeof(pixel);



    switch (class) {

    case 0:

        if (!borders[2])

            width -= (8 >> chroma) + 2;

        if (!borders[3])

            height -= (4 >> chroma) + 2;

        break;

    case 1:

        init_y = -(4 >> chroma) - 2;

        if (!borders[2])

            width -= (8 >> chroma) + 2;

        height = (4 >> chroma) + 2;

        break;

    case 2:

        init_x = -(8 >> chroma) - 2;

        width  =  (8 >> chroma) + 2;

        if (!borders[3])

            height -= (4 >> chroma) + 2;

        break;

    case 3:

        init_y = -(4 >> chroma) - 2;

        init_x = -(8 >> chroma) - 2;

        width  =  (8 >> chroma) + 2;

        height =  (4 >> chroma) + 2;

        break;

    }



    dst = dst + (init_y * stride + init_x);

    src = src + (init_y * stride + init_x);

    for (k = 0; k < 4; k++)

        offset_table[(k + sao_left_class) & 31] = sao_offset_val[k + 1];

    for (y = 0; y < height; y++) {

        for (x = 0; x < width; x++)

            dst[x] = av_clip_pixel(src[x] + offset_table[av_clip_pixel(src[x] >> shift)]);

        dst += stride;

        src += stride;

    }

}

static void openpic_tmr_write(void *opaque, hwaddr addr, uint64_t val,

                                unsigned len)

{

    OpenPICState *opp = opaque;

    int idx;



    DPRINTF("%s: addr %08x <= %08x\n", __func__, addr, val);

    if (addr & 0xF)

        return;

    idx = (addr >> 6) & 0x3;

    addr = addr & 0x30;



    if (addr == 0x0) {

        /* TIFR (TFRR) */

        opp->tifr = val;

        return;

    }

    switch (addr & 0x30) {

    case 0x00: /* TICC (GTCCR) */

        break;

    case 0x10: /* TIBC (GTBCR) */

        if ((opp->timers[idx].ticc & TICC_TOG) != 0 &&

            (val & TIBC_CI) == 0 &&

            (opp->timers[idx].tibc & TIBC_CI) != 0) {

            opp->timers[idx].ticc &= ~TICC_TOG;

        }

        opp->timers[idx].tibc = val;

        break;

    case 0x20: /* TIVP (GTIVPR) */

        write_IRQreg_ipvp(opp, opp->irq_tim0 + idx, val);

        break;

    case 0x30: /* TIDE (GTIDR) */

        write_IRQreg_ide(opp, opp->irq_tim0 + idx, val);

        break;

    }

}

static uint64_t openpic_src_read(void *opaque, uint64_t addr, unsigned len)

{

    OpenPICState *opp = opaque;

    uint32_t retval;

    int idx;



    DPRINTF("%s: addr %08x\n", __func__, addr);

    retval = 0xFFFFFFFF;

    if (addr & 0xF) {

        return retval;

    }

    addr = addr & 0xFFF0;

    idx = addr >> 5;

    if (addr & 0x10) {

        /* EXDE / IFEDE / IEEDE */

        retval = read_IRQreg_ide(opp, idx);

    } else {

        /* EXVP / IFEVP / IEEVP */

        retval = read_IRQreg_ipvp(opp, idx);

    }

    DPRINTF("%s: => %08x\n", __func__, retval);



    return retval;

}

static uint64_t openpic_src_read(void *opaque, uint64_t addr, unsigned len)

{

    OpenPICState *opp = opaque;

    uint32_t retval;

    int idx;



    DPRINTF("%s: addr %#" HWADDR_PRIx "\n", __func__, addr);

    retval = 0xFFFFFFFF;

    if (addr & 0xF) {

        return retval;

    }

    addr = addr & 0xFFF0;

    idx = addr >> 5;

    if (addr & 0x10) {

        /* EXDE / IFEDE / IEEDE */

        retval = read_IRQreg_idr(opp, idx);

    } else {

        /* EXVP / IFEVP / IEEVP */

        retval = read_IRQreg_ivpr(opp, idx);

    }

    DPRINTF("%s: => 0x%08x\n", __func__, retval);



    return retval;

}

static uint64_t openpic_gbl_read(void *opaque, hwaddr addr, unsigned len)

{

    OpenPICState *opp = opaque;

    uint32_t retval;



    DPRINTF("%s: addr " TARGET_FMT_plx "\n", __func__, addr);

    retval = 0xFFFFFFFF;

    if (addr & 0xF)

        return retval;

    switch (addr) {

    case 0x1000: /* FREP */

        retval = opp->frep;

        break;

    case 0x1020: /* GLBC */

        retval = opp->glbc;

        break;

    case 0x1080: /* VENI */

        retval = opp->veni;

        break;

    case 0x1090: /* PINT */

        retval = 0x00000000;

        break;

    case 0x00: /* Block Revision Register1 (BRR1) */

        retval = opp->brr1;

        break;

    case 0x40:

    case 0x50:

    case 0x60:

    case 0x70:

    case 0x80:

    case 0x90:

    case 0xA0:

    case 0xB0:

        retval = openpic_cpu_read_internal(opp, addr, get_current_cpu());

        break;

    case 0x10A0: /* IPI_IPVP */

    case 0x10B0:

    case 0x10C0:

    case 0x10D0:

        {

            int idx;

            idx = (addr - 0x10A0) >> 4;

            retval = read_IRQreg_ipvp(opp, opp->irq_ipi0 + idx);

        }

        break;

    case 0x10E0: /* SPVE */

        retval = opp->spve;

        break;

    default:

        break;

    }

    DPRINTF("%s: => %08x\n", __func__, retval);



    return retval;

}

static void gen_rfe(DisasContext *s, TCGv pc, TCGv cpsr)

{

    gen_set_cpsr(cpsr, 0xffffffff);

    dead_tmp(cpsr);

    store_reg(s, 15, pc);

    s->is_jmp = DISAS_UPDATE;

}

static void gen_exception_insn(DisasContext *s, int offset, int excp,

                               int syn, uint32_t target_el)

{

    gen_set_condexec(s);

    gen_set_pc_im(s, s->pc - offset);

    gen_exception(excp, syn, target_el);

    s->is_jmp = DISAS_JUMP;

}

static void gen_exception(DisasContext *s, int trapno, target_ulong cur_eip)

{

    gen_update_cc_op(s);

    gen_jmp_im(cur_eip);

    gen_helper_raise_exception(cpu_env, tcg_const_i32(trapno));

    s->is_jmp = DISAS_TB_JUMP;

