static QDict *qmp_dispatch_check_obj(const QObject *request, Error **errp)

{

    const QDictEntry *ent;

    const char *arg_name;

    const QObject *arg_obj;

    bool has_exec_key = false;

    QDict *dict = NULL;



    dict = qobject_to_qdict(request);

    if (!dict) {

        error_setg(errp, QERR_QMP_BAD_INPUT_OBJECT,

                   "request is not a dictionary");

        return NULL;

    }



    for (ent = qdict_first(dict); ent;

         ent = qdict_next(dict, ent)) {

        arg_name = qdict_entry_key(ent);

        arg_obj = qdict_entry_value(ent);



        if (!strcmp(arg_name, "execute")) {

            if (qobject_type(arg_obj) != QTYPE_QSTRING) {

                error_setg(errp, QERR_QMP_BAD_INPUT_OBJECT_MEMBER, "execute",

                           "string");

                return NULL;

            }

            has_exec_key = true;

        } else if (!strcmp(arg_name, "arguments")) {

            if (qobject_type(arg_obj) != QTYPE_QDICT) {

                error_setg(errp, QERR_QMP_BAD_INPUT_OBJECT_MEMBER,

                           "arguments", "object");

                return NULL;

            }

        } else {

            error_setg(errp, QERR_QMP_EXTRA_MEMBER, arg_name);

            return NULL;

        }

    }



    if (!has_exec_key) {

        error_setg(errp, QERR_QMP_BAD_INPUT_OBJECT, "execute");

        return NULL;

    }



    return dict;

}

static QDict *qmp_check_input_obj(QObject *input_obj)

{

    const QDictEntry *ent;

    int has_exec_key = 0;

    QDict *input_dict;



    if (qobject_type(input_obj) != QTYPE_QDICT) {

        qerror_report(QERR_QMP_BAD_INPUT_OBJECT, "object");

        return NULL;

    }



    input_dict = qobject_to_qdict(input_obj);



    for (ent = qdict_first(input_dict); ent; ent = qdict_next(input_dict, ent)){

        const char *arg_name = qdict_entry_key(ent);

        const QObject *arg_obj = qdict_entry_value(ent);



        if (!strcmp(arg_name, "execute")) {

            if (qobject_type(arg_obj) != QTYPE_QSTRING) {

                qerror_report(QERR_QMP_BAD_INPUT_OBJECT_MEMBER, "execute",

                              "string");

                return NULL;

            }

            has_exec_key = 1;

        } else if (!strcmp(arg_name, "arguments")) {

            if (qobject_type(arg_obj) != QTYPE_QDICT) {

                qerror_report(QERR_QMP_BAD_INPUT_OBJECT_MEMBER, "arguments",

                              "object");

                return NULL;

            }

        } else if (!strcmp(arg_name, "id")) {

            /* FIXME: check duplicated IDs for async commands */

        } else {

            qerror_report(QERR_QMP_EXTRA_MEMBER, arg_name);

            return NULL;

        }

    }



    if (!has_exec_key) {

        qerror_report(QERR_QMP_BAD_INPUT_OBJECT, "execute");

        return NULL;

    }



    return input_dict;

}

static QDict *parse_json_filename(const char *filename, Error **errp)

{

    QObject *options_obj;

    QDict *options;

    int ret;



    ret = strstart(filename, "json:", &filename);

    assert(ret);



    options_obj = qobject_from_json(filename);

    if (!options_obj) {

        error_setg(errp, "Could not parse the JSON options");

        return NULL;

    }



    if (qobject_type(options_obj) != QTYPE_QDICT) {

        qobject_decref(options_obj);

        error_setg(errp, "Invalid JSON object given");

        return NULL;

    }



    options = qobject_to_qdict(options_obj);

    qdict_flatten(options);



    return options;

}

static QObject *qmp_input_get_object(QmpInputVisitor *qiv,

                                     const char *name,

                                     bool consume, Error **errp)

{

    StackObject *tos;

    QObject *qobj;

    QObject *ret;



    if (QSLIST_EMPTY(&qiv->stack)) {

        /* Starting at root, name is ignored. */

        assert(qiv->root);

        return qiv->root;

    }



    /* We are in a container; find the next element. */

    tos = QSLIST_FIRST(&qiv->stack);

    qobj = tos->obj;

    assert(qobj);



    if (qobject_type(qobj) == QTYPE_QDICT) {

        assert(name);

        ret = qdict_get(qobject_to_qdict(qobj), name);

        if (tos->h && consume && ret) {

            bool removed = g_hash_table_remove(tos->h, name);

            assert(removed);

        }

        if (!ret) {

            error_setg(errp, QERR_MISSING_PARAMETER, name);

        }

    } else {

        assert(qobject_type(qobj) == QTYPE_QLIST);

        assert(!name);

        ret = qlist_entry_obj(tos->entry);

        assert(ret);

        if (consume) {

            tos->entry = qlist_next(tos->entry);

        }

    }



    return ret;

}

void ff_svq3_add_idct_c(uint8_t *dst, DCTELEM *block, int stride, int qp,

                            int dc)

{

    const int qmul = svq3_dequant_coeff[qp];

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    if (dc) {

        dc = 13*13*((dc == 1) ? 1538*block[0] : ((qmul*(block[0] >> 3)) / 2));

        block[0] = 0;

    }



    for (i = 0; i < 4; i++) {

        const int z0 = 13*(block[0 + 4*i] +    block[2 + 4*i]);

        const int z1 = 13*(block[0 + 4*i] -    block[2 + 4*i]);

        const int z2 =  7* block[1 + 4*i] - 17*block[3 + 4*i];

        const int z3 = 17* block[1 + 4*i] +  7*block[3 + 4*i];



        block[0 + 4*i] = z0 + z3;

        block[1 + 4*i] = z1 + z2;

        block[2 + 4*i] = z1 - z2;

        block[3 + 4*i] = z0 - z3;

    }



    for (i = 0; i < 4; i++) {

        const int z0 = 13*(block[i + 4*0] +    block[i + 4*2]);

        const int z1 = 13*(block[i + 4*0] -    block[i + 4*2]);

        const int z2 =  7* block[i + 4*1] - 17*block[i + 4*3];

        const int z3 = 17* block[i + 4*1] +  7*block[i + 4*3];

        const int rr = (dc + 0x80000);



        dst[i + stride*0] = cm[ dst[i + stride*0] + (((z0 + z3)*qmul + rr) >> 20) ];

        dst[i + stride*1] = cm[ dst[i + stride*1] + (((z1 + z2)*qmul + rr) >> 20) ];

        dst[i + stride*2] = cm[ dst[i + stride*2] + (((z1 - z2)*qmul + rr) >> 20) ];

        dst[i + stride*3] = cm[ dst[i + stride*3] + (((z0 - z3)*qmul + rr) >> 20) ];

    }

}

static void sha256_transform(uint32_t *state, const uint8_t buffer[64])

{

    unsigned int i, a, b, c, d, e, f, g, h;

    uint32_t block[64];

    uint32_t T1;



    a = state[0];

    b = state[1];

    c = state[2];

    d = state[3];

    e = state[4];

    f = state[5];

    g = state[6];

    h = state[7];

#if CONFIG_SMALL

    for (i = 0; i < 64; i++) {

        uint32_t T2;

        if (i < 16)

            T1 = blk0(i);

        else

            T1 = blk(i);

        T1 += h + Sigma1_256(e) + Ch(e, f, g) + K256[i];

        T2 = Sigma0_256(a) + Maj(a, b, c);

        h = g;

        g = f;

        f = e;

        e = d + T1;

        d = c;

        c = b;

        b = a;

        a = T1 + T2;

    }

#else

    for (i = 0; i < 16;) {

        ROUND256_0_TO_15(a, b, c, d, e, f, g, h);

        ROUND256_0_TO_15(h, a, b, c, d, e, f, g);

        ROUND256_0_TO_15(g, h, a, b, c, d, e, f);

        ROUND256_0_TO_15(f, g, h, a, b, c, d, e);

        ROUND256_0_TO_15(e, f, g, h, a, b, c, d);

        ROUND256_0_TO_15(d, e, f, g, h, a, b, c);

        ROUND256_0_TO_15(c, d, e, f, g, h, a, b);

        ROUND256_0_TO_15(b, c, d, e, f, g, h, a);

    }



    for (; i < 64;) {

        ROUND256_16_TO_63(a, b, c, d, e, f, g, h);

        ROUND256_16_TO_63(h, a, b, c, d, e, f, g);

        ROUND256_16_TO_63(g, h, a, b, c, d, e, f);

        ROUND256_16_TO_63(f, g, h, a, b, c, d, e);

        ROUND256_16_TO_63(e, f, g, h, a, b, c, d);

        ROUND256_16_TO_63(d, e, f, g, h, a, b, c);

        ROUND256_16_TO_63(c, d, e, f, g, h, a, b);

        ROUND256_16_TO_63(b, c, d, e, f, g, h, a);

    }

#endif

    state[0] += a;

    state[1] += b;

    state[2] += c;

    state[3] += d;

    state[4] += e;

    state[5] += f;

    state[6] += g;

    state[7] += h;

}

static uint32_t get_generic_seed(void)

{

    uint8_t tmp[120];

    struct AVSHA *sha = (void*)tmp;

    clock_t last_t  = 0;

    static uint64_t i = 0;

    static uint32_t buffer[512] = { 0 };

    unsigned char digest[20];

    uint64_t last_i = i;



    av_assert0(sizeof(tmp) >= av_sha_size);



    if(TEST){

        memset(buffer, 0, sizeof(buffer));

        last_i = i = 0;

    }else{

#ifdef AV_READ_TIME

        buffer[13] ^= AV_READ_TIME();

        buffer[41] ^= AV_READ_TIME()>>32;

#endif

    }



    for (;;) {

        clock_t t = clock();



        if (last_t == t) {

            buffer[i & 511]++;

        } else {

            buffer[++i & 511] += (t - last_t) % 3294638521U;

            if (last_i && i - last_i > 4 || i - last_i > 64 || TEST && i - last_i > 8)

                break;

        }

        last_t = t;

    }



    if(TEST)

        buffer[0] = buffer[1] = 0;



    av_sha_init(sha, 160);

    av_sha_update(sha, (const uint8_t *)buffer, sizeof(buffer));

    av_sha_final(sha, digest);

    return AV_RB32(digest) + AV_RB32(digest + 16);

}

static void body(uint32_t ABCD[4], uint32_t X[16])

{

    int i av_unused;

    uint32_t t;

    uint32_t a = ABCD[3];

    uint32_t b = ABCD[2];

    uint32_t c = ABCD[1];

    uint32_t d = ABCD[0];



#if HAVE_BIGENDIAN

    for (i = 0; i < 16; i++)

        X[i] = av_bswap32(X[i]);

#endif



#if CONFIG_SMALL

    for (i = 0; i < 64; i++) {

        CORE(i, a, b, c, d);

        t = d;

        d = c;

        c = b;

        b = a;

        a = t;

    }

#else

#define CORE2(i)                                                        \

    CORE( i,   a,b,c,d); CORE((i+1),d,a,b,c);                           \

    CORE((i+2),c,d,a,b); CORE((i+3),b,c,d,a)

#define CORE4(i) CORE2(i); CORE2((i+4)); CORE2((i+8)); CORE2((i+12))

    CORE4(0); CORE4(16); CORE4(32); CORE4(48);

#endif



    ABCD[0] += d;

    ABCD[1] += c;

    ABCD[2] += b;

    ABCD[3] += a;

}

