PPC_OP(srw)

{

    if (T1 & 0x20) {

        T0 = 0;

    } else {

        T0 = T0 >> T1;

    }

    RETURN();

}

PPC_OP(cmp)

{

    if (Ts0 < Ts1) {

        T0 = 0x08;

    } else if (Ts0 > Ts1) {

        T0 = 0x04;

    } else {

        T0 = 0x02;

    }

    RETURN();

}

PPC_OP(addze)

{

    T1 = T0;

    T0 += xer_ca;

    if (T0 < T1) {

        xer_ca = 1;

    } else {

        xer_ca = 0;

    }

    RETURN();

}

PPC_OP(addc)

{

    T2 = T0;

    T0 += T1;

    if (T0 < T2) {

        xer_ca = 1;

    } else {

        xer_ca = 0;

    }

    RETURN();

}

static inline uint16_t mipsdsp_trunc16_sat16_round(int32_t a,

                                                   CPUMIPSState *env)

{

    int64_t temp;



    temp = (int32_t)a + 0x00008000;



    if (a > (int)0x7fff8000) {

        temp = 0x7FFFFFFF;

        set_DSPControl_overflow_flag(1, 22, env);

    }



    return (temp >> 16) & 0xFFFF;

}

