static void exynos4210_ltick_recalc_count(struct tick_timer *s)

{

    uint64_t to_count;



    if ((s->cnt_run && s->last_tcnto) || (s->int_run && s->last_icnto)) {

        /*

         * one or both timers run and not counted to the end;

         * distance is not passed, recalculate with last_tcnto * last_icnto

         */



        if (s->last_tcnto) {

            to_count = s->last_tcnto * s->last_icnto;

        } else {

            to_count = s->last_icnto;

        }

    } else {

        /* distance is passed, recalculate with tcnto * icnto */

        if (s->icntb) {

            s->distance = s->tcntb * s->icntb;

        } else {

            s->distance = s->tcntb;

        }



        to_count = s->distance;

        s->progress = 0;

    }



    if (to_count > MCT_LT_COUNTER_STEP) {

        /* count by step */

        s->count = MCT_LT_COUNTER_STEP;

    } else {

        s->count = to_count;

    }

}

static bool bdrv_exceed_iops_limits(BlockDriverState *bs, bool is_write,

                             double elapsed_time, uint64_t *wait)

{

    uint64_t iops_limit = 0;

    double   ios_limit, ios_base;

    double   slice_time, wait_time;



    if (bs->io_limits.iops[BLOCK_IO_LIMIT_TOTAL]) {

        iops_limit = bs->io_limits.iops[BLOCK_IO_LIMIT_TOTAL];

    } else if (bs->io_limits.iops[is_write]) {

        iops_limit = bs->io_limits.iops[is_write];

    } else {

        if (wait) {

            *wait = 0;

        }



        return false;

    }



    slice_time = bs->slice_end - bs->slice_start;

    slice_time /= (NANOSECONDS_PER_SECOND);

    ios_limit  = iops_limit * slice_time;

    ios_base   = bs->nr_ops[is_write] - bs->io_base.ios[is_write];

    if (bs->io_limits.iops[BLOCK_IO_LIMIT_TOTAL]) {

        ios_base += bs->nr_ops[!is_write] - bs->io_base.ios[!is_write];

    }



    if (ios_base + 1 <= ios_limit) {

        if (wait) {

            *wait = 0;

        }



        return false;

    }



    /* Calc approx time to dispatch */

    wait_time = (ios_base + 1) / iops_limit;

    if (wait_time > elapsed_time) {

        wait_time = wait_time - elapsed_time;

    } else {

        wait_time = 0;

    }



    bs->slice_time = wait_time * BLOCK_IO_SLICE_TIME * 10;

    bs->slice_end += bs->slice_time - 3 * BLOCK_IO_SLICE_TIME;

    if (wait) {

        *wait = wait_time * BLOCK_IO_SLICE_TIME * 10;

    }



    return true;

}

static void build_chunks(MOVTrack *trk)

{

    int i;

    MOVIentry *chunk= &trk->cluster[0];

    uint64_t chunkSize = chunk->size;

    chunk->chunkNum= 1;

    trk->chunkCount= 1;

    for(i=1; i<trk->entry; i++){

        if(chunk->pos + chunkSize == trk->cluster[i].pos){

            chunkSize             += trk->cluster[i].size;

            chunk->samplesInChunk += trk->cluster[i].entries;

        }else{

            trk->cluster[i].chunkNum = chunk->chunkNum+1;

            chunk=&trk->cluster[i];

            chunkSize = chunk->size;

            trk->chunkCount++;

        }

    }

}

void bdrv_detach_aio_context(BlockDriverState *bs)

{

    BdrvAioNotifier *baf;

    BdrvChild *child;



    if (!bs->drv) {

        return;

    }



    QLIST_FOREACH(baf, &bs->aio_notifiers, list) {

        baf->detach_aio_context(baf->opaque);

    }



    if (bs->drv->bdrv_detach_aio_context) {

        bs->drv->bdrv_detach_aio_context(bs);

    }

    QLIST_FOREACH(child, &bs->children, next) {

        bdrv_detach_aio_context(child->bs);

    }



    bs->aio_context = NULL;

}

