static int mov_read_elst(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    MOVStreamContext *sc;

    int i, edit_count, version;



    if (c->fc->nb_streams < 1 || c->ignore_editlist)

        return 0;

    sc = c->fc->streams[c->fc->nb_streams-1]->priv_data;



    version = avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */

    edit_count = avio_rb32(pb); /* entries */



    if (!edit_count)

        return 0;

    if (sc->elst_data)

        av_log(c->fc, AV_LOG_WARNING, "Duplicated ELST atom\n");

    av_free(sc->elst_data);

    sc->elst_count = 0;

    sc->elst_data = av_malloc_array(edit_count, sizeof(*sc->elst_data));

    if (!sc->elst_data)

        return AVERROR(ENOMEM);



    av_log(c->fc, AV_LOG_TRACE, "track[%u].edit_count = %i\n", c->fc->nb_streams - 1, edit_count);

    for (i = 0; i < edit_count && !pb->eof_reached; i++) {

        MOVElst *e = &sc->elst_data[i];



        if (version == 1) {

            e->duration = avio_rb64(pb);

            e->time     = avio_rb64(pb);

        } else {

            e->duration = avio_rb32(pb); /* segment duration */

            e->time     = (int32_t)avio_rb32(pb); /* media time */

        }

        e->rate = avio_rb32(pb) / 65536.0;

        av_log(c->fc, AV_LOG_TRACE, "duration=%"PRId64" time=%"PRId64" rate=%f\n",

               e->duration, e->time, e->rate);



        if (e->time < 0 && e->time != -1 &&

            c->fc->strict_std_compliance >= FF_COMPLIANCE_STRICT) {

            av_log(c->fc, AV_LOG_ERROR, "Track %d, edit %d: Invalid edit list media time=%"PRId64"\n",

                   c->fc->nb_streams-1, i, e->time);

            return AVERROR_INVALIDDATA;

        }

    }

    sc->elst_count = i;



    return 0;

}

static int sdp_parse_rtpmap(AVFormatContext *s,

                            AVStream *st, RTSPStream *rtsp_st,

                            int payload_type, const char *p)

{

    AVCodecContext *codec = st->codec;

    char buf[256];

    int i;

    AVCodec *c;

    const char *c_name;



    /* See if we can handle this kind of payload.

     * The space should normally not be there but some Real streams or

     * particular servers ("RealServer Version 6.1.3.970", see issue 1658)

     * have a trailing space. */

    get_word_sep(buf, sizeof(buf), "/ ", &p);

    if (payload_type < RTP_PT_PRIVATE) {

        /* We are in a standard case

         * (from http://www.iana.org/assignments/rtp-parameters). */

        codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    if (codec->codec_id == AV_CODEC_ID_NONE) {

        RTPDynamicProtocolHandler *handler =

            ff_rtp_handler_find_by_name(buf, codec->codec_type);

        init_rtp_handler(handler, rtsp_st, st);

        /* If no dynamic handler was found, check with the list of standard

         * allocated types, if such a stream for some reason happens to

         * use a private payload type. This isn't handled in rtpdec.c, since

         * the format name from the rtpmap line never is passed into rtpdec. */

        if (!rtsp_st->dynamic_handler)

            codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    c = avcodec_find_decoder(codec->codec_id);

    if (c && c->name)

        c_name = c->name;

    else

        c_name = "(null)";



    get_word_sep(buf, sizeof(buf), "/", &p);

    i = atoi(buf);

    switch (codec->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        av_log(s, AV_LOG_DEBUG, "audio codec set to: %s\n", c_name);

        codec->sample_rate = RTSP_DEFAULT_AUDIO_SAMPLERATE;

        codec->channels = RTSP_DEFAULT_NB_AUDIO_CHANNELS;

        if (i > 0) {

            codec->sample_rate = i;

            avpriv_set_pts_info(st, 32, 1, codec->sample_rate);

            get_word_sep(buf, sizeof(buf), "/", &p);

            i = atoi(buf);

            if (i > 0)

                codec->channels = i;

        }

        av_log(s, AV_LOG_DEBUG, "audio samplerate set to: %i\n",

               codec->sample_rate);

        av_log(s, AV_LOG_DEBUG, "audio channels set to: %i\n",

               codec->channels);

        break;

    case AVMEDIA_TYPE_VIDEO:

        av_log(s, AV_LOG_DEBUG, "video codec set to: %s\n", c_name);

        if (i > 0)

            avpriv_set_pts_info(st, 32, 1, i);

        break;

    default:

        break;

    }

    if (rtsp_st->dynamic_handler && rtsp_st->dynamic_handler->init)

        rtsp_st->dynamic_handler->init(s, st->index,

                                       rtsp_st->dynamic_protocol_context);

    return 0;

}

static char *sdp_write_media_attributes(char *buff, int size, AVCodecContext *c, int payload_type, AVFormatContext *fmt)

{

    char *config = NULL;



    switch (c->codec_id) {

        case AV_CODEC_ID_H264: {

            int mode = 1;

            if (fmt && fmt->oformat && fmt->oformat->priv_class &&

                av_opt_flag_is_set(fmt->priv_data, "rtpflags", "h264_mode0"))

                mode = 0;

            if (c->extradata_size) {

                config = extradata2psets(c);

            }

            av_strlcatf(buff, size, "a=rtpmap:%d H264/90000\r\n"

                                    "a=fmtp:%d packetization-mode=%d%s\r\n",

                                     payload_type,

                                     payload_type, mode, config ? config : "");

            break;

        }

        case AV_CODEC_ID_H263:

        case AV_CODEC_ID_H263P:

            /* a=framesize is required by 3GPP TS 26.234 (PSS). It

             * actually specifies the maximum video size, but we only know

             * the current size. This is required for playback on Android

             * stagefright and on Samsung bada. */

            if (!fmt || !fmt->oformat->priv_class ||

                !av_opt_flag_is_set(fmt->priv_data, "rtpflags", "rfc2190") ||

                c->codec_id == AV_CODEC_ID_H263P)

            av_strlcatf(buff, size, "a=rtpmap:%d H263-2000/90000\r\n"

                                    "a=framesize:%d %d-%d\r\n",

                                    payload_type,

                                    payload_type, c->width, c->height);

            break;

        case AV_CODEC_ID_HEVC:

            if (c->extradata_size)

                av_log(NULL, AV_LOG_WARNING, "HEVC extradata not currently "

                                             "passed properly through SDP\n");

            av_strlcatf(buff, size, "a=rtpmap:%d H265/90000\r\n", payload_type);

            break;

        case AV_CODEC_ID_MPEG4:

            if (c->extradata_size) {

                config = extradata2config(c);

            }

            av_strlcatf(buff, size, "a=rtpmap:%d MP4V-ES/90000\r\n"

                                    "a=fmtp:%d profile-level-id=1%s\r\n",

                                     payload_type,

                                     payload_type, config ? config : "");

            break;

        case AV_CODEC_ID_AAC:

            if (fmt && fmt->oformat->priv_class &&

                av_opt_flag_is_set(fmt->priv_data, "rtpflags", "latm")) {

                config = latm_context2config(c);

                if (!config)

                    return NULL;

                av_strlcatf(buff, size, "a=rtpmap:%d MP4A-LATM/%d/%d\r\n"

                                        "a=fmtp:%d profile-level-id=%d;cpresent=0;config=%s\r\n",

                                         payload_type, c->sample_rate, c->channels,

                                         payload_type, latm_context2profilelevel(c), config);

            } else {

                if (c->extradata_size) {

                    config = extradata2config(c);

                } else {

                    /* FIXME: maybe we can forge config information based on the

                     *        codec parameters...

                     */

                    av_log(c, AV_LOG_ERROR, "AAC with no global headers is currently not supported.\n");

                    return NULL;

                }

                if (!config) {

                    return NULL;

                }

                av_strlcatf(buff, size, "a=rtpmap:%d MPEG4-GENERIC/%d/%d\r\n"

                                        "a=fmtp:%d profile-level-id=1;"

                                        "mode=AAC-hbr;sizelength=13;indexlength=3;"

                                        "indexdeltalength=3%s\r\n",

                                         payload_type, c->sample_rate, c->channels,

                                         payload_type, config);

            }

            break;

        case AV_CODEC_ID_PCM_S16BE:

            if (payload_type >= RTP_PT_PRIVATE)

                av_strlcatf(buff, size, "a=rtpmap:%d L16/%d/%d\r\n",

                                         payload_type,

                                         c->sample_rate, c->channels);

            break;

        case AV_CODEC_ID_PCM_MULAW:

            if (payload_type >= RTP_PT_PRIVATE)

                av_strlcatf(buff, size, "a=rtpmap:%d PCMU/%d/%d\r\n",

                                         payload_type,

                                         c->sample_rate, c->channels);

            break;

        case AV_CODEC_ID_PCM_ALAW:

            if (payload_type >= RTP_PT_PRIVATE)

                av_strlcatf(buff, size, "a=rtpmap:%d PCMA/%d/%d\r\n",

                                         payload_type,

                                         c->sample_rate, c->channels);

            break;

        case AV_CODEC_ID_AMR_NB:

            av_strlcatf(buff, size, "a=rtpmap:%d AMR/%d/%d\r\n"

                                    "a=fmtp:%d octet-align=1\r\n",

                                     payload_type, c->sample_rate, c->channels,

                                     payload_type);

            break;

        case AV_CODEC_ID_AMR_WB:

            av_strlcatf(buff, size, "a=rtpmap:%d AMR-WB/%d/%d\r\n"

                                    "a=fmtp:%d octet-align=1\r\n",

                                     payload_type, c->sample_rate, c->channels,

                                     payload_type);

            break;

        case AV_CODEC_ID_VORBIS:

            if (c->extradata_size)

                config = xiph_extradata2config(c);

            else

                av_log(c, AV_LOG_ERROR, "Vorbis configuration info missing\n");

            if (!config)

                return NULL;



            av_strlcatf(buff, size, "a=rtpmap:%d vorbis/%d/%d\r\n"

                                    "a=fmtp:%d configuration=%s\r\n",

                                    payload_type, c->sample_rate, c->channels,

                                    payload_type, config);

            break;

        case AV_CODEC_ID_THEORA: {

            const char *pix_fmt;

            switch (c->pix_fmt) {

            case AV_PIX_FMT_YUV420P:

                pix_fmt = "YCbCr-4:2:0";

                break;

            case AV_PIX_FMT_YUV422P:

                pix_fmt = "YCbCr-4:2:2";

                break;

            case AV_PIX_FMT_YUV444P:

                pix_fmt = "YCbCr-4:4:4";

                break;

            default:

                av_log(c, AV_LOG_ERROR, "Unsupported pixel format.\n");

                return NULL;

            }



            if (c->extradata_size)

                config = xiph_extradata2config(c);

            else

                av_log(c, AV_LOG_ERROR, "Theora configuation info missing\n");

            if (!config)

                return NULL;



            av_strlcatf(buff, size, "a=rtpmap:%d theora/90000\r\n"

                                    "a=fmtp:%d delivery-method=inline; "

                                    "width=%d; height=%d; sampling=%s; "

                                    "configuration=%s\r\n",

                                    payload_type, payload_type,

                                    c->width, c->height, pix_fmt, config);

            break;

        }

        case AV_CODEC_ID_VP8:

            av_strlcatf(buff, size, "a=rtpmap:%d VP8/90000\r\n",

                                     payload_type);

            break;

        case AV_CODEC_ID_MJPEG:

            if (payload_type >= RTP_PT_PRIVATE)

                av_strlcatf(buff, size, "a=rtpmap:%d JPEG/90000\r\n",

                                         payload_type);

            break;

        case AV_CODEC_ID_ADPCM_G722:

            if (payload_type >= RTP_PT_PRIVATE)

                av_strlcatf(buff, size, "a=rtpmap:%d G722/%d/%d\r\n",

                                         payload_type,

                                         8000, c->channels);

            break;

        case AV_CODEC_ID_ADPCM_G726: {

            if (payload_type >= RTP_PT_PRIVATE)

                av_strlcatf(buff, size, "a=rtpmap:%d G726-%d/%d\r\n",

                                         payload_type,

                                         c->bits_per_coded_sample*8,

                                         c->sample_rate);

            break;

        }

        case AV_CODEC_ID_ILBC:

            av_strlcatf(buff, size, "a=rtpmap:%d iLBC/%d\r\n"

                                    "a=fmtp:%d mode=%d\r\n",

                                     payload_type, c->sample_rate,

                                     payload_type, c->block_align == 38 ? 20 : 30);

            break;

        case AV_CODEC_ID_SPEEX:

            av_strlcatf(buff, size, "a=rtpmap:%d speex/%d\r\n",

                                     payload_type, c->sample_rate);

            break;

        case AV_CODEC_ID_OPUS:

            /* The opus RTP draft says that all opus streams MUST be declared

               as stereo, to avoid negotiation failures. The actual number of

               channels can change on a packet-by-packet basis. The number of

               channels a receiver prefers to receive or a sender plans to send

               can be declared via fmtp parameters (both default to mono), but

               receivers MUST be able to receive and process stereo packets. */

            av_strlcatf(buff, size, "a=rtpmap:%d opus/48000/2\r\n",

                                     payload_type);

            if (c->channels == 2) {

                av_strlcatf(buff, size, "a=fmtp:%d sprop-stereo:1\r\n",

                                         payload_type);

            }

            break;

        default:

            /* Nothing special to do here... */

            break;

    }



    av_free(config);



    return buff;

}

static int sdp_parse_rtpmap(AVCodecContext *codec, RTSPStream *rtsp_st, int payload_type, const char *p)

{

    char buf[256];

    int i;

    AVCodec *c;

    const char *c_name;



    /* Loop into AVRtpDynamicPayloadTypes[] and AVRtpPayloadTypes[] and

       see if we can handle this kind of payload */

    get_word_sep(buf, sizeof(buf), "/", &p);

    if (payload_type >= RTP_PT_PRIVATE) {

        RTPDynamicProtocolHandler *handler= RTPFirstDynamicPayloadHandler;

        while(handler) {

            if (!strcasecmp(buf, handler->enc_name) && (codec->codec_type == handler->codec_type)) {

                codec->codec_id = handler->codec_id;

                rtsp_st->dynamic_handler= handler;

                if(handler->open) {

                    rtsp_st->dynamic_protocol_context= handler->open();

                }

                break;

            }

            handler= handler->next;

        }

    } else {

        /* We are in a standard case ( from http://www.iana.org/assignments/rtp-parameters) */

        /* search into AVRtpPayloadTypes[] */

        codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    c = avcodec_find_decoder(codec->codec_id);

    if (c && c->name)

        c_name = c->name;

    else

        c_name = (char *)NULL;



    if (c_name) {

        get_word_sep(buf, sizeof(buf), "/", &p);

        i = atoi(buf);

        switch (codec->codec_type) {

            case CODEC_TYPE_AUDIO:

                av_log(codec, AV_LOG_DEBUG, " audio codec set to : %s\n", c_name);

                codec->sample_rate = RTSP_DEFAULT_AUDIO_SAMPLERATE;

                codec->channels = RTSP_DEFAULT_NB_AUDIO_CHANNELS;

                if (i > 0) {

                    codec->sample_rate = i;

                    get_word_sep(buf, sizeof(buf), "/", &p);

                    i = atoi(buf);

                    if (i > 0)

                        codec->channels = i;

                    // TODO: there is a bug here; if it is a mono stream, and less than 22000Hz, faad upconverts to stereo and twice the

                    //  frequency.  No problem, but the sample rate is being set here by the sdp line.  Upcoming patch forthcoming. (rdm)

                }

                av_log(codec, AV_LOG_DEBUG, " audio samplerate set to : %i\n", codec->sample_rate);

                av_log(codec, AV_LOG_DEBUG, " audio channels set to : %i\n", codec->channels);

                break;

            case CODEC_TYPE_VIDEO:

                av_log(codec, AV_LOG_DEBUG, " video codec set to : %s\n", c_name);

                break;

            default:

                break;

        }

        return 0;

    }



    return -1;

}

static void sdp_parse_fmtp(AVStream *st, const char *p)

{

    char attr[256];

    /* Vorbis setup headers can be up to 12KB and are sent base64

     * encoded, giving a 12KB * (4/3) = 16KB FMTP line. */

    char value[16384];

    int i;



    RTSPStream *rtsp_st = st->priv_data;

    AVCodecContext *codec = st->codec;

    RTPPayloadData *rtp_payload_data = &rtsp_st->rtp_payload_data;



    /* loop on each attribute */

    while(rtsp_next_attr_and_value(&p, attr, sizeof(attr), value, sizeof(value)))

    {

        /* grab the codec extra_data from the config parameter of the fmtp line */

        sdp_parse_fmtp_config(codec, rtsp_st->dynamic_protocol_context,

                              attr, value);

        /* Looking for a known attribute */

        for (i = 0; attr_names[i].str; ++i) {

            if (!strcasecmp(attr, attr_names[i].str)) {

                if (attr_names[i].type == ATTR_NAME_TYPE_INT)

                    *(int *)((char *)rtp_payload_data + attr_names[i].offset) = atoi(value);

                else if (attr_names[i].type == ATTR_NAME_TYPE_STR)

                    *(char **)((char *)rtp_payload_data + attr_names[i].offset) = av_strdup(value);

            }

        }

    }

}

void ff_xvmc_init_block(MpegEncContext *s)

{

    struct xvmc_render_state *render = (struct xvmc_render_state*)s->current_picture.data[2];

    assert(render);

    if (!render || render->magic != AV_XVMC_RENDER_MAGIC) {

        assert(0);

        return; // make sure that this is a render packet

    }

    s->block = (DCTELEM *)(render->data_blocks + render->next_free_data_block_num * 64);

}

void ff_release_unused_pictures(MpegEncContext *s, int remove_current)

{

    int i;



    /* release non reference frames */

    for(i=0; i<s->picture_count; i++){

        if(s->picture[i].data[0] && !s->picture[i].reference

           && s->picture[i].owner2 == s

           && (remove_current || &s->picture[i] != s->current_picture_ptr)

           /*&& s->picture[i].type!=FF_BUFFER_TYPE_SHARED*/){

            free_frame_buffer(s, &s->picture[i]);

        }

    }

}

static int slice_end(AVCodecContext *avctx, AVFrame *pict)

{

    Mpeg1Context *s1  = avctx->priv_data;

    MpegEncContext *s = &s1->mpeg_enc_ctx;



    if (!s1->mpeg_enc_ctx_allocated || !s->current_picture_ptr)

        return 0;



    if (s->avctx->hwaccel) {

        if (s->avctx->hwaccel->end_frame(s->avctx) < 0)

            av_log(avctx, AV_LOG_ERROR,

                   "hardware accelerator failed to decode picture\n");

    }



#if FF_API_XVMC

FF_DISABLE_DEPRECATION_WARNINGS

    if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration)

        ff_xvmc_field_end(s);

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */



    /* end of slice reached */

    if (/* s->mb_y << field_pic == s->mb_height && */ !s->first_field) {

        /* end of image */



        ff_er_frame_end(&s->er);



        ff_mpv_frame_end(s);



        if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

            int ret = av_frame_ref(pict, s->current_picture_ptr->f);

            if (ret < 0)

                return ret;

            ff_print_debug_info(s, s->current_picture_ptr);

        } else {

            if (avctx->active_thread_type & FF_THREAD_FRAME)

                s->picture_number++;

            /* latency of 1 frame for I- and P-frames */

            /* XXX: use another variable than picture_number */

            if (s->last_picture_ptr != NULL) {

                int ret = av_frame_ref(pict, s->last_picture_ptr->f);

                if (ret < 0)

                    return ret;

                ff_print_debug_info(s, s->last_picture_ptr);

            }

        }



        return 1;

    } else {

        return 0;

    }

}

void ff_xvmc_field_end(MpegEncContext *s)

{

    struct xvmc_pix_fmt *render = (struct xvmc_pix_fmt*)s->current_picture.f->data[2];

    assert(render);



    if (render->filled_mv_blocks_num > 0)

        ff_mpeg_draw_horiz_band(s, 0, 0);

}

static int read_ffserver_streams(OptionsContext *o, AVFormatContext *s, const char *filename)

{

    int i, err;

    AVFormatContext *ic = avformat_alloc_context();





    ic->interrupt_callback = int_cb;

    err = avformat_open_input(&ic, filename, NULL, NULL);

    if (err < 0)

        return err;

    /* copy stream format */

    for(i=0;i<ic->nb_streams;i++) {

        AVStream *st;

        OutputStream *ost;

        AVCodec *codec;

        const char *enc_config;



        codec = avcodec_find_encoder(ic->streams[i]->codecpar->codec_id);

        if (!codec) {

            av_log(s, AV_LOG_ERROR, "no encoder found for codec id %i\n", ic->streams[i]->codecpar->codec_id);

            return AVERROR(EINVAL);

        }

        if (codec->type == AVMEDIA_TYPE_AUDIO)

            opt_audio_codec(o, "c:a", codec->name);

        else if (codec->type == AVMEDIA_TYPE_VIDEO)

            opt_video_codec(o, "c:v", codec->name);

        ost   = new_output_stream(o, s, codec->type, -1);

        st    = ost->st;



        avcodec_get_context_defaults3(st->codec, codec);

        enc_config = av_stream_get_recommended_encoder_configuration(ic->streams[i]);

        if (enc_config) {

            AVDictionary *opts = NULL;

            av_dict_parse_string(&opts, enc_config, "=", ",", 0);

            av_opt_set_dict2(st->codec, &opts, AV_OPT_SEARCH_CHILDREN);

            av_dict_free(&opts);

        }



        if (st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO && !ost->stream_copy)

            choose_sample_fmt(st, codec);

        else if (st->codecpar->codec_type == AVMEDIA_TYPE_VIDEO && !ost->stream_copy)

            choose_pixel_fmt(st, st->codec, codec, st->codecpar->format);

        avcodec_copy_context(ost->enc_ctx, st->codec);

        if (enc_config)

            av_dict_parse_string(&ost->encoder_opts, enc_config, "=", ",", 0);

    }



    avformat_close_input(&ic);

    return err;

}

static void new_video_stream(AVFormatContext *oc)

{

    AVStream *st;

    AVCodecContext *video_enc;

    enum CodecID codec_id;

    AVCodec *codec= NULL;



    st = av_new_stream(oc, oc->nb_streams < nb_streamid_map ? streamid_map[oc->nb_streams] : 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        ffmpeg_exit(1);

    }



    output_codecs = grow_array(output_codecs, sizeof(*output_codecs), &nb_output_codecs, nb_output_codecs + 1);

    if(!video_stream_copy){

        if (video_codec_name) {

            codec_id = find_codec_or_die(video_codec_name, AVMEDIA_TYPE_VIDEO, 1,

                                         avcodec_opts[AVMEDIA_TYPE_VIDEO]->strict_std_compliance);

            codec = avcodec_find_encoder_by_name(video_codec_name);

            output_codecs[nb_output_codecs-1] = codec;

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_VIDEO);

            codec = avcodec_find_encoder(codec_id);

        }

    }



    avcodec_get_context_defaults3(st->codec, codec);

    bitstream_filters[nb_output_files] =

        grow_array(bitstream_filters[nb_output_files],

                   sizeof(*bitstream_filters[nb_output_files]),

                   &nb_bitstream_filters[nb_output_files], oc->nb_streams);

    bitstream_filters[nb_output_files][oc->nb_streams - 1]= video_bitstream_filters;

    video_bitstream_filters= NULL;



    avcodec_thread_init(st->codec, thread_count);



    video_enc = st->codec;



    if(video_codec_tag)

        video_enc->codec_tag= video_codec_tag;



    if(   (video_global_header&1)

       || (video_global_header==0 && (oc->oformat->flags & AVFMT_GLOBALHEADER))){

        video_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_VIDEO]->flags|= CODEC_FLAG_GLOBAL_HEADER;

    }

    if(video_global_header&2){

        video_enc->flags2 |= CODEC_FLAG2_LOCAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_VIDEO]->flags2|= CODEC_FLAG2_LOCAL_HEADER;

    }



    if (video_stream_copy) {

        st->stream_copy = 1;

        video_enc->codec_type = AVMEDIA_TYPE_VIDEO;

        video_enc->sample_aspect_ratio =

        st->sample_aspect_ratio = av_d2q(frame_aspect_ratio*frame_height/frame_width, 255);

    } else {

        const char *p;

        int i;

        AVRational fps= frame_rate.num ? frame_rate : (AVRational){25,1};



        video_enc->codec_id = codec_id;

        set_context_opts(video_enc, avcodec_opts[AVMEDIA_TYPE_VIDEO], AV_OPT_FLAG_VIDEO_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);



        if (codec && codec->supported_framerates && !force_fps)

            fps = codec->supported_framerates[av_find_nearest_q_idx(fps, codec->supported_framerates)];

        video_enc->time_base.den = fps.num;

        video_enc->time_base.num = fps.den;



        video_enc->width = frame_width;

        video_enc->height = frame_height;

        video_enc->sample_aspect_ratio = av_d2q(frame_aspect_ratio*video_enc->height/video_enc->width, 255);

        video_enc->pix_fmt = frame_pix_fmt;

        st->sample_aspect_ratio = video_enc->sample_aspect_ratio;



        choose_pixel_fmt(st, codec);



        if (intra_only)

            video_enc->gop_size = 0;

        if (video_qscale || same_quality) {

            video_enc->flags |= CODEC_FLAG_QSCALE;

            video_enc->global_quality=

                st->quality = FF_QP2LAMBDA * video_qscale;

        }



        if(intra_matrix)

            video_enc->intra_matrix = intra_matrix;

        if(inter_matrix)

            video_enc->inter_matrix = inter_matrix;



        p= video_rc_override_string;

        for(i=0; p; i++){

            int start, end, q;

            int e=sscanf(p, "%d,%d,%d", &start, &end, &q);

            if(e!=3){

                fprintf(stderr, "error parsing rc_override\n");

                ffmpeg_exit(1);

            }

            video_enc->rc_override=

                av_realloc(video_enc->rc_override,

                           sizeof(RcOverride)*(i+1));

            video_enc->rc_override[i].start_frame= start;

            video_enc->rc_override[i].end_frame  = end;

            if(q>0){

                video_enc->rc_override[i].qscale= q;

                video_enc->rc_override[i].quality_factor= 1.0;

            }

            else{

                video_enc->rc_override[i].qscale= 0;

                video_enc->rc_override[i].quality_factor= -q/100.0;

            }

            p= strchr(p, '/');

            if(p) p++;

        }

        video_enc->rc_override_count=i;

        if (!video_enc->rc_initial_buffer_occupancy)

            video_enc->rc_initial_buffer_occupancy = video_enc->rc_buffer_size*3/4;

        video_enc->me_threshold= me_threshold;

        video_enc->intra_dc_precision= intra_dc_precision - 8;



        if (do_psnr)

            video_enc->flags|= CODEC_FLAG_PSNR;



        /* two pass mode */

        if (do_pass) {

            if (do_pass == 1) {

                video_enc->flags |= CODEC_FLAG_PASS1;

            } else {

                video_enc->flags |= CODEC_FLAG_PASS2;

            }

        }

    }

    if (video_language) {

        av_metadata_set2(&st->metadata, "language", video_language, 0);

        av_freep(&video_language);

    }



    /* reset some key parameters */

    video_disable = 0;

    av_freep(&video_codec_name);

    video_stream_copy = 0;

    frame_pix_fmt = PIX_FMT_NONE;

}

int read_ffserver_streams(AVFormatContext *s, const char *filename)

{

    int i;

    AVFormatContext *ic;



    ic = av_open_input_file(filename, FFM_PACKET_SIZE);

    if (!ic)

        return -EIO;

    /* copy stream format */

    s->nb_streams = ic->nb_streams;

    for(i=0;i<ic->nb_streams;i++) {

        AVStream *st;

        st = av_mallocz(sizeof(AVFormatContext));

        memcpy(st, ic->streams[i], sizeof(AVStream));

        s->streams[i] = st;

    }



    av_close_input_file(ic);

    return 0;

}

static void new_audio_stream(AVFormatContext *oc, int file_idx)

{

    AVStream *st;

    AVOutputStream *ost;

    AVCodec *codec= NULL;

    AVCodecContext *audio_enc;

    enum CodecID codec_id;



    st = av_new_stream(oc, oc->nb_streams < nb_streamid_map ? streamid_map[oc->nb_streams] : 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        ffmpeg_exit(1);

    }

    ost = new_output_stream(oc, file_idx);



    output_codecs = grow_array(output_codecs, sizeof(*output_codecs), &nb_output_codecs, nb_output_codecs + 1);

    if(!audio_stream_copy){

        if (audio_codec_name) {

            codec_id = find_codec_or_die(audio_codec_name, AVMEDIA_TYPE_AUDIO, 1,

                                         avcodec_opts[AVMEDIA_TYPE_AUDIO]->strict_std_compliance);

            codec = avcodec_find_encoder_by_name(audio_codec_name);

            output_codecs[nb_output_codecs-1] = codec;

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_AUDIO);

            codec = avcodec_find_encoder(codec_id);

        }

    }



    avcodec_get_context_defaults3(st->codec, codec);



    ost->bitstream_filters = audio_bitstream_filters;

    audio_bitstream_filters= NULL;



    avcodec_thread_init(st->codec, thread_count);



    audio_enc = st->codec;

    audio_enc->codec_type = AVMEDIA_TYPE_AUDIO;



    if(audio_codec_tag)

        audio_enc->codec_tag= audio_codec_tag;



    if (oc->oformat->flags & AVFMT_GLOBALHEADER) {

        audio_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_AUDIO]->flags|= CODEC_FLAG_GLOBAL_HEADER;

    }

    if (audio_stream_copy) {

        st->stream_copy = 1;

        audio_enc->channels = audio_channels;

        audio_enc->sample_rate = audio_sample_rate;

    } else {

        audio_enc->codec_id = codec_id;

        set_context_opts(audio_enc, avcodec_opts[AVMEDIA_TYPE_AUDIO], AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);



        if (audio_qscale > QSCALE_NONE) {

            audio_enc->flags |= CODEC_FLAG_QSCALE;

            audio_enc->global_quality = st->quality = FF_QP2LAMBDA * audio_qscale;

        }

        audio_enc->channels = audio_channels;

        audio_enc->sample_fmt = audio_sample_fmt;

        audio_enc->sample_rate = audio_sample_rate;

        audio_enc->channel_layout = channel_layout;

        if (av_get_channel_layout_nb_channels(channel_layout) != audio_channels)

            audio_enc->channel_layout = 0;

        choose_sample_fmt(st, codec);

        choose_sample_rate(st, codec);

    }

    audio_enc->time_base= (AVRational){1, audio_sample_rate};

    if (audio_language) {

        av_metadata_set2(&st->metadata, "language", audio_language, 0);

        av_freep(&audio_language);

    }



    /* reset some key parameters */

    audio_disable = 0;

    av_freep(&audio_codec_name);

    audio_stream_copy = 0;

}

