int vnc_tls_validate_certificate(VncState *vs)

{

    int ret;

    unsigned int status;

    const gnutls_datum_t *certs;

    unsigned int nCerts, i;

    time_t now;



    VNC_DEBUG("Validating client certificate\n");

    if ((ret = gnutls_certificate_verify_peers2 (vs->tls.session, &status)) < 0) {

        VNC_DEBUG("Verify failed %s\n", gnutls_strerror(ret));

        return -1;

    }



    if ((now = time(NULL)) == ((time_t)-1)) {

        return -1;

    }



    if (status != 0) {

        if (status & GNUTLS_CERT_INVALID)

            VNC_DEBUG("The certificate is not trusted.\n");



        if (status & GNUTLS_CERT_SIGNER_NOT_FOUND)

            VNC_DEBUG("The certificate hasn't got a known issuer.\n");



        if (status & GNUTLS_CERT_REVOKED)

            VNC_DEBUG("The certificate has been revoked.\n");



        if (status & GNUTLS_CERT_INSECURE_ALGORITHM)

            VNC_DEBUG("The certificate uses an insecure algorithm\n");



        return -1;

    } else {

        VNC_DEBUG("Certificate is valid!\n");

    }



    /* Only support x509 for now */

    if (gnutls_certificate_type_get(vs->tls.session) != GNUTLS_CRT_X509)

        return -1;



    if (!(certs = gnutls_certificate_get_peers(vs->tls.session, &nCerts)))

        return -1;



    for (i = 0 ; i < nCerts ; i++) {

        gnutls_x509_crt_t cert;

        VNC_DEBUG ("Checking certificate chain %d\n", i);

        if (gnutls_x509_crt_init (&cert) < 0)

            return -1;



        if (gnutls_x509_crt_import(cert, &certs[i], GNUTLS_X509_FMT_DER) < 0) {

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (gnutls_x509_crt_get_expiration_time (cert) < now) {

            VNC_DEBUG("The certificate has expired\n");

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (gnutls_x509_crt_get_activation_time (cert) > now) {

            VNC_DEBUG("The certificate is not yet activated\n");

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (gnutls_x509_crt_get_activation_time (cert) > now) {

            VNC_DEBUG("The certificate is not yet activated\n");

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (i == 0) {

            size_t dnameSize = 1024;

            vs->tls.dname = g_malloc(dnameSize);

        requery:

            if ((ret = gnutls_x509_crt_get_dn (cert, vs->tls.dname, &dnameSize)) != 0) {

                if (ret == GNUTLS_E_SHORT_MEMORY_BUFFER) {

                    vs->tls.dname = g_realloc(vs->tls.dname, dnameSize);

                    goto requery;

                }

                gnutls_x509_crt_deinit (cert);

                VNC_DEBUG("Cannot get client distinguished name: %s",

                          gnutls_strerror (ret));

                return -1;

            }



            if (vs->vd->tls.x509verify) {

                int allow;

                if (!vs->vd->tls.acl) {

                    VNC_DEBUG("no ACL activated, allowing access");

                    gnutls_x509_crt_deinit (cert);

                    continue;

                }



                allow = qemu_acl_party_is_allowed(vs->vd->tls.acl,

                                                  vs->tls.dname);



                VNC_DEBUG("TLS x509 ACL check for %s is %s\n",

                          vs->tls.dname, allow ? "allowed" : "denied");

                if (!allow) {

                    gnutls_x509_crt_deinit (cert);

                    return -1;

                }

            }

        }



        gnutls_x509_crt_deinit (cert);

    }



    return 0;

}

static int vncws_start_tls_handshake(VncState *vs)

{

    int ret = gnutls_handshake(vs->tls.session);



    if (ret < 0) {

        if (!gnutls_error_is_fatal(ret)) {

            VNC_DEBUG("Handshake interrupted (blocking)\n");

            if (!gnutls_record_get_direction(vs->tls.session)) {

                qemu_set_fd_handler(vs->csock, vncws_tls_handshake_io,

                                    NULL, vs);

            } else {

                qemu_set_fd_handler(vs->csock, NULL, vncws_tls_handshake_io,

                                    vs);

            }

            return 0;

        }

        VNC_DEBUG("Handshake failed %s\n", gnutls_strerror(ret));

        vnc_client_error(vs);

        return -1;

    }



    if (vs->vd->tls.x509verify) {

        if (vnc_tls_validate_certificate(vs) < 0) {

            VNC_DEBUG("Client verification failed\n");

            vnc_client_error(vs);

            return -1;

        } else {

            VNC_DEBUG("Client verification passed\n");

        }

    }



    VNC_DEBUG("Handshake done, switching to TLS data mode\n");

    qemu_set_fd_handler(vs->csock, vncws_handshake_read, NULL, vs);



    return 0;

}

static int vnc_auth_sasl_check_access(VncState *vs)

{

    const void *val;

    int err;



    err = sasl_getprop(vs->sasl.conn, SASL_USERNAME, &val);

    if (err != SASL_OK) {

	VNC_DEBUG("cannot query SASL username on connection %d (%s)\n",

		  err, sasl_errstring(err, NULL, NULL));

	return -1;

    }

    if (val == NULL) {

	VNC_DEBUG("no client username was found\n");

	return -1;

    }

    VNC_DEBUG("SASL client username %s\n", (const char *)val);



    vs->sasl.username = qemu_strdup((const char*)val);



    return 0;

}

static int protocol_client_auth(VncState *vs, char *data, size_t len)

{

    /* We only advertise 1 auth scheme at a time, so client

     * must pick the one we sent. Verify this */

    if (data[0] != vs->auth) { /* Reject auth */

       VNC_DEBUG("Reject auth %d\n", (int)data[0]);

       vnc_write_u32(vs, 1);

       if (vs->minor >= 8) {

           static const char err[] = "Authentication failed";

           vnc_write_u32(vs, sizeof(err));

           vnc_write(vs, err, sizeof(err));

       }

       vnc_client_error(vs);

    } else { /* Accept requested auth */

       VNC_DEBUG("Client requested auth %d\n", (int)data[0]);

       switch (vs->auth) {

       case VNC_AUTH_NONE:

           VNC_DEBUG("Accept auth none\n");

           vnc_write_u32(vs, 0); /* Accept auth completion */

           vnc_read_when(vs, protocol_client_init, 1);

           break;



       case VNC_AUTH_VNC:

           VNC_DEBUG("Start VNC auth\n");

           return start_auth_vnc(vs);



#if CONFIG_VNC_TLS

       case VNC_AUTH_VENCRYPT:

           VNC_DEBUG("Accept VeNCrypt auth\n");;

           return start_auth_vencrypt(vs);

#endif /* CONFIG_VNC_TLS */



       default: /* Should not be possible, but just in case */

           VNC_DEBUG("Reject auth %d\n", vs->auth);

           vnc_write_u8(vs, 1);

           if (vs->minor >= 8) {

               static const char err[] = "Authentication failed";

               vnc_write_u32(vs, sizeof(err));

               vnc_write(vs, err, sizeof(err));

           }

           vnc_client_error(vs);

       }

    }

    return 0;

}

int fw_cfg_add_callback(FWCfgState *s, uint16_t key, FWCfgCallback callback,

                        void *callback_opaque, uint8_t *data, size_t len)

{

    int arch = !!(key & FW_CFG_ARCH_LOCAL);



    if (!(key & FW_CFG_WRITE_CHANNEL))

        return 0;



    key &= FW_CFG_ENTRY_MASK;



    if (key >= FW_CFG_MAX_ENTRY || len > 65535)

        return 0;



    s->entries[arch][key].data = data;

    s->entries[arch][key].len = len;

    s->entries[arch][key].callback_opaque = callback_opaque;

    s->entries[arch][key].callback = callback;



    return 1;

}

static int fifo_put(SerialState *s, int fifo, uint8_t chr)

{

    SerialFIFO *f = (fifo) ? &s->recv_fifo : &s->xmit_fifo;



    f->data[f->head++] = chr;



    if (f->head == UART_FIFO_LENGTH)

        f->head = 0;

    f->count++;



    return 1;

}

static int avs_probe(AVProbeData * p)

{

    const uint8_t *d;



    if (p->buf_size < 2)

        return 0;

    d = p->buf;

    if (d[0] == 'w' && d[1] == 'W' && d[2] == 0x10 && d[3] == 0)

        return 50;



    return 0;

}

int fw_cfg_add_bytes(FWCfgState *s, uint16_t key, uint8_t *data, uint32_t len)

{

    int arch = !!(key & FW_CFG_ARCH_LOCAL);



    key &= FW_CFG_ENTRY_MASK;



    if (key >= FW_CFG_MAX_ENTRY)

        return 0;



    s->entries[arch][key].data = data;

    s->entries[arch][key].len = len;



    return 1;

}

static float get_band_cost_ZERO_mips(struct AACEncContext *s,

                                     PutBitContext *pb, const float *in,

                                     const float *scaled, int size, int scale_idx,

                                     int cb, const float lambda, const float uplim,

                                     int *bits)

{

    int i;

    float cost = 0;



    for (i = 0; i < size; i += 4) {

        cost += in[i  ] * in[i  ];

        cost += in[i+1] * in[i+1];

        cost += in[i+2] * in[i+2];

        cost += in[i+3] * in[i+3];

    }

    if (bits)

        *bits = 0;

    return cost * lambda;

}

static void add_pid_to_pmt(MpegTSContext *ts, unsigned int programid,

                           unsigned int pid)

{

    struct Program *p = get_program(ts, programid);

    int i;

    if (!p)

        return;



    if (p->nb_pids >= MAX_PIDS_PER_PROGRAM)

        return;



    for (i = 0; i < MAX_PIDS_PER_PROGRAM; i++)

        if (p->pids[i] == pid)

            return;



    p->pids[p->nb_pids++] = pid;

}

static void pre_calc_cosmod(DCAContext * s)

{

    int i, j, k;

    static int cosmod_inited = 0;



    if(cosmod_inited) return;

    for (j = 0, k = 0; k < 16; k++)

        for (i = 0; i < 16; i++)

            cos_mod[j++] = cos((2 * i + 1) * (2 * k + 1) * M_PI / 64);



    for (k = 0; k < 16; k++)

        for (i = 0; i < 16; i++)

            cos_mod[j++] = cos((i) * (2 * k + 1) * M_PI / 32);



    for (k = 0; k < 16; k++)

        cos_mod[j++] = 0.25 / (2 * cos((2 * k + 1) * M_PI / 128));



    for (k = 0; k < 16; k++)

        cos_mod[j++] = -0.25 / (2.0 * sin((2 * k + 1) * M_PI / 128));



    cosmod_inited = 1;

}

static void sr_1d97_float(float *p, int i0, int i1)

{

    int i;



    if (i1 <= i0 + 1) {

        if (i0 == 1)

            p[1] *= F_LFTG_K/2;

        else

            p[0] *= F_LFTG_X/2;

        return;

    }



    extend97_float(p, i0, i1);



    for (i = i0 / 2 - 1; i < i1 / 2 + 2; i++)

        p[2 * i]     -= F_LFTG_DELTA * (p[2 * i - 1] + p[2 * i + 1]);

    /* step 4 */

    for (i = i0 / 2 - 1; i < i1 / 2 + 1; i++)

        p[2 * i + 1] -= F_LFTG_GAMMA * (p[2 * i]     + p[2 * i + 2]);

    /*step 5*/

    for (i = i0 / 2; i < i1 / 2 + 1; i++)

        p[2 * i]     += F_LFTG_BETA  * (p[2 * i - 1] + p[2 * i + 1]);

    /* step 6 */

    for (i = i0 / 2; i < i1 / 2; i++)

        p[2 * i + 1] += F_LFTG_ALPHA * (p[2 * i]     + p[2 * i + 2]);

}

static int decode_thread(void *arg)

{

    VideoState *is = arg;

    AVFormatContext *ic;

    int err, i, ret;

    int st_index[AVMEDIA_TYPE_NB];

    AVPacket pkt1, *pkt = &pkt1;

    AVFormatParameters params, *ap = &params;

    int eof=0;

    int pkt_in_play_range = 0;



    ic = avformat_alloc_context();



    memset(st_index, -1, sizeof(st_index));

    is->video_stream = -1;

    is->audio_stream = -1;

    is->subtitle_stream = -1;



    global_video_state = is;

    url_set_interrupt_cb(decode_interrupt_cb);



    memset(ap, 0, sizeof(*ap));



    ap->prealloced_context = 1;

    ap->width = frame_width;

    ap->height= frame_height;

    ap->time_base= (AVRational){1, 25};

    ap->pix_fmt = frame_pix_fmt;



    set_context_opts(ic, avformat_opts, AV_OPT_FLAG_DECODING_PARAM, NULL);



    err = av_open_input_file(&ic, is->filename, is->iformat, 0, ap);

    if (err < 0) {

        print_error(is->filename, err);

        ret = -1;

        goto fail;

    }

    is->ic = ic;



    if(genpts)

        ic->flags |= AVFMT_FLAG_GENPTS;



    err = av_find_stream_info(ic);

    if (err < 0) {

        fprintf(stderr, "%s: could not find codec parameters\n", is->filename);

        ret = -1;

        goto fail;

    }

    if(ic->pb)

        ic->pb->eof_reached= 0; //FIXME hack, ffplay maybe should not use url_feof() to test for the end



    if(seek_by_bytes<0)

        seek_by_bytes= !!(ic->iformat->flags & AVFMT_TS_DISCONT);



    /* if seeking requested, we execute it */

    if (start_time != AV_NOPTS_VALUE) {

        int64_t timestamp;



        timestamp = start_time;

        /* add the stream start time */

        if (ic->start_time != AV_NOPTS_VALUE)

            timestamp += ic->start_time;

        ret = avformat_seek_file(ic, -1, INT64_MIN, timestamp, INT64_MAX, 0);

        if (ret < 0) {

            fprintf(stderr, "%s: could not seek to position %0.3f\n",

                    is->filename, (double)timestamp / AV_TIME_BASE);

        }

    }



    for (i = 0; i < ic->nb_streams; i++)

        ic->streams[i]->discard = AVDISCARD_ALL;

    if (!video_disable)

        st_index[AVMEDIA_TYPE_VIDEO] =

            av_find_best_stream(ic, AVMEDIA_TYPE_VIDEO,

                                wanted_stream[AVMEDIA_TYPE_VIDEO], -1, NULL, 0);

    if (!audio_disable)

        st_index[AVMEDIA_TYPE_AUDIO] =

            av_find_best_stream(ic, AVMEDIA_TYPE_AUDIO,

                                wanted_stream[AVMEDIA_TYPE_AUDIO],

                                st_index[AVMEDIA_TYPE_VIDEO],

                                NULL, 0);

    if (!video_disable)

        st_index[AVMEDIA_TYPE_SUBTITLE] =

            av_find_best_stream(ic, AVMEDIA_TYPE_SUBTITLE,

                                wanted_stream[AVMEDIA_TYPE_SUBTITLE],

                                (st_index[AVMEDIA_TYPE_AUDIO] >= 0 ?

                                 st_index[AVMEDIA_TYPE_AUDIO] :

                                 st_index[AVMEDIA_TYPE_VIDEO]),

                                NULL, 0);

    if (show_status) {

        av_dump_format(ic, 0, is->filename, 0);

    }



    /* open the streams */

    if (st_index[AVMEDIA_TYPE_AUDIO] >= 0) {

        stream_component_open(is, st_index[AVMEDIA_TYPE_AUDIO]);

    }



    ret=-1;

    if (st_index[AVMEDIA_TYPE_VIDEO] >= 0) {

        ret= stream_component_open(is, st_index[AVMEDIA_TYPE_VIDEO]);

    }

    is->refresh_tid = SDL_CreateThread(refresh_thread, is);

    if(ret<0) {

        if (!display_disable)

            is->show_audio = 2;

    }



    if (st_index[AVMEDIA_TYPE_SUBTITLE] >= 0) {

        stream_component_open(is, st_index[AVMEDIA_TYPE_SUBTITLE]);

    }



    if (is->video_stream < 0 && is->audio_stream < 0) {

        fprintf(stderr, "%s: could not open codecs\n", is->filename);

        ret = -1;

        goto fail;

    }



    for(;;) {

        if (is->abort_request)

            break;

        if (is->paused != is->last_paused) {

            is->last_paused = is->paused;

            if (is->paused)

                is->read_pause_return= av_read_pause(ic);

            else

                av_read_play(ic);

        }

#if CONFIG_RTSP_DEMUXER

        if (is->paused && !strcmp(ic->iformat->name, "rtsp")) {

            /* wait 10 ms to avoid trying to get another packet */

            /* XXX: horrible */

            SDL_Delay(10);

            continue;

        }

#endif

        if (is->seek_req) {

            int64_t seek_target= is->seek_pos;

            int64_t seek_min= is->seek_rel > 0 ? seek_target - is->seek_rel + 2: INT64_MIN;

            int64_t seek_max= is->seek_rel < 0 ? seek_target - is->seek_rel - 2: INT64_MAX;

//FIXME the +-2 is due to rounding being not done in the correct direction in generation

//      of the seek_pos/seek_rel variables



            ret = avformat_seek_file(is->ic, -1, seek_min, seek_target, seek_max, is->seek_flags);

            if (ret < 0) {

                fprintf(stderr, "%s: error while seeking\n", is->ic->filename);

            }else{

                if (is->audio_stream >= 0) {

                    packet_queue_flush(&is->audioq);

                    packet_queue_put(&is->audioq, &flush_pkt);

                }

                if (is->subtitle_stream >= 0) {

                    packet_queue_flush(&is->subtitleq);

                    packet_queue_put(&is->subtitleq, &flush_pkt);

                }

                if (is->video_stream >= 0) {

                    packet_queue_flush(&is->videoq);

                    packet_queue_put(&is->videoq, &flush_pkt);

                }

            }

            is->seek_req = 0;

            eof= 0;

        }



        /* if the queue are full, no need to read more */

        if (   is->audioq.size + is->videoq.size + is->subtitleq.size > MAX_QUEUE_SIZE

            || (   (is->audioq   .size  > MIN_AUDIOQ_SIZE || is->audio_stream<0)

                && (is->videoq   .nb_packets > MIN_FRAMES || is->video_stream<0)

                && (is->subtitleq.nb_packets > MIN_FRAMES || is->subtitle_stream<0))) {

            /* wait 10 ms */

            SDL_Delay(10);

            continue;

        }

        if(eof) {

            if(is->video_stream >= 0){

                av_init_packet(pkt);

                pkt->data=NULL;

                pkt->size=0;

                pkt->stream_index= is->video_stream;

                packet_queue_put(&is->videoq, pkt);

            }

            SDL_Delay(10);

            if(is->audioq.size + is->videoq.size + is->subtitleq.size ==0){

                if(loop!=1 && (!loop || --loop)){

                    stream_seek(cur_stream, start_time != AV_NOPTS_VALUE ? start_time : 0, 0, 0);

                }else if(autoexit){

                    ret=AVERROR_EOF;

                    goto fail;

                }

            }

            continue;

        }

        ret = av_read_frame(ic, pkt);

        if (ret < 0) {

            if (ret == AVERROR_EOF || ic->pb->eof_reached)

                eof=1;

            if (ic->pb->error)

                break;

            SDL_Delay(100); /* wait for user event */

            continue;

        }

        /* check if packet is in play range specified by user, then queue, otherwise discard */

        pkt_in_play_range = duration == AV_NOPTS_VALUE ||

                (pkt->pts - ic->streams[pkt->stream_index]->start_time) *

                av_q2d(ic->streams[pkt->stream_index]->time_base) -

                (double)(start_time != AV_NOPTS_VALUE ? start_time : 0)/1000000

                <= ((double)duration/1000000);

        if (pkt->stream_index == is->audio_stream && pkt_in_play_range) {

            packet_queue_put(&is->audioq, pkt);

        } else if (pkt->stream_index == is->video_stream && pkt_in_play_range) {

            packet_queue_put(&is->videoq, pkt);

        } else if (pkt->stream_index == is->subtitle_stream && pkt_in_play_range) {

            packet_queue_put(&is->subtitleq, pkt);

        } else {

            av_free_packet(pkt);

        }

    }

    /* wait until the end */

    while (!is->abort_request) {

        SDL_Delay(100);

    }



    ret = 0;

 fail:

    /* disable interrupting */

    global_video_state = NULL;



    /* close each stream */

    if (is->audio_stream >= 0)

        stream_component_close(is, is->audio_stream);

    if (is->video_stream >= 0)

        stream_component_close(is, is->video_stream);

    if (is->subtitle_stream >= 0)

        stream_component_close(is, is->subtitle_stream);

    if (is->ic) {

        av_close_input_file(is->ic);

        is->ic = NULL; /* safety */

    }

    url_set_interrupt_cb(NULL);



    if (ret != 0) {

        SDL_Event event;



        event.type = FF_QUIT_EVENT;

        event.user.data1 = is;

        SDL_PushEvent(&event);

    }

    return 0;

}

static int transcode(void)

{

    int ret, i;

    AVFormatContext *is, *os;

    OutputStream *ost;

    InputStream *ist;

    uint8_t *no_packet;

    int no_packet_count = 0;

    int64_t timer_start;



    if (!(no_packet = av_mallocz(nb_input_files)))

        exit_program(1);



    ret = transcode_init();

    if (ret < 0)

        goto fail;



    av_log(NULL, AV_LOG_INFO, "Press ctrl-c to stop encoding\n");

    term_init();



    timer_start = av_gettime();



    for (; received_sigterm == 0;) {

        int file_index, ist_index, past_recording_time = 1;

        AVPacket pkt;

        int64_t ipts_min;



        ipts_min = INT64_MAX;



        /* check if there's any stream where output is still needed */

        for (i = 0; i < nb_output_streams; i++) {

            OutputFile *of;

            ost = output_streams[i];

            of  = output_files[ost->file_index];

            os  = output_files[ost->file_index]->ctx;

            if (ost->is_past_recording_time ||

                (os->pb && avio_tell(os->pb) >= of->limit_filesize))

                continue;

            if (ost->frame_number > ost->max_frames) {

                int j;

                for (j = 0; j < of->ctx->nb_streams; j++)

                    output_streams[of->ost_index + j]->is_past_recording_time = 1;

                continue;

            }

            past_recording_time = 0;

        }

        if (past_recording_time)

            break;



        /* select the stream that we must read now by looking at the

           smallest output pts */

        file_index = -1;

        for (i = 0; i < nb_input_streams; i++) {

            int64_t ipts;

            ist = input_streams[i];

            ipts = ist->last_dts;

            if (ist->discard || no_packet[ist->file_index])

                continue;

            if (!input_files[ist->file_index]->eof_reached) {

                if (ipts < ipts_min) {

                    ipts_min = ipts;

                    file_index = ist->file_index;

                }

            }

        }

        /* if none, if is finished */

        if (file_index < 0) {

            if (no_packet_count) {

                no_packet_count = 0;

                memset(no_packet, 0, nb_input_files);

                usleep(10000);

                continue;

            }

            break;

        }



        /* read a frame from it and output it in the fifo */

        is  = input_files[file_index]->ctx;

        ret = av_read_frame(is, &pkt);

        if (ret == AVERROR(EAGAIN)) {

            no_packet[file_index] = 1;

            no_packet_count++;

            continue;

        }

        if (ret < 0) {

            input_files[file_index]->eof_reached = 1;



            for (i = 0; i < input_files[file_index]->nb_streams; i++) {

                ist = input_streams[input_files[file_index]->ist_index + i];

                if (ist->decoding_needed)

                    output_packet(ist, NULL);

            }



            if (opt_shortest)

                break;

            else

                continue;

        }



        no_packet_count = 0;

        memset(no_packet, 0, nb_input_files);



        if (do_pkt_dump) {

            av_pkt_dump_log2(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump,

                             is->streams[pkt.stream_index]);

        }

        /* the following test is needed in case new streams appear

           dynamically in stream : we ignore them */

        if (pkt.stream_index >= input_files[file_index]->nb_streams)

            goto discard_packet;

        ist_index = input_files[file_index]->ist_index + pkt.stream_index;

        ist = input_streams[ist_index];

        if (ist->discard)

            goto discard_packet;



        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);

        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);



        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts *= ist->ts_scale;

        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts *= ist->ts_scale;



        //fprintf(stderr, "next:%"PRId64" dts:%"PRId64" off:%"PRId64" %d\n",

        //        ist->next_dts,

        //        pkt.dts, input_files[ist->file_index].ts_offset,

        //        ist->st->codec->codec_type);

        if (pkt.dts != AV_NOPTS_VALUE && ist->next_dts != AV_NOPTS_VALUE

            && (is->iformat->flags & AVFMT_TS_DISCONT)) {

            int64_t pkt_dts = av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

            int64_t delta   = pkt_dts - ist->next_dts;

            if ((FFABS(delta) > 1LL * dts_delta_threshold * AV_TIME_BASE || pkt_dts + 1 < ist->last_dts) && !copy_ts) {

                input_files[ist->file_index]->ts_offset -= delta;

                av_log(NULL, AV_LOG_DEBUG,

                       "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n",

                       delta, input_files[ist->file_index]->ts_offset);

                pkt.dts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

                if (pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            }

        }



        // fprintf(stderr,"read #%d.%d size=%d\n", ist->file_index, ist->st->index, pkt.size);

        if (output_packet(ist, &pkt) < 0 || poll_filters() < 0) {

            av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d\n",

                   ist->file_index, ist->st->index);

            if (exit_on_error)

                exit_program(1);

            av_free_packet(&pkt);

            continue;

        }



    discard_packet:

        av_free_packet(&pkt);



        /* dump report by using the output first video and audio streams */

        print_report(0, timer_start);

    }



    /* at the end of stream, we must flush the decoder buffers */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (!input_files[ist->file_index]->eof_reached && ist->decoding_needed) {

            output_packet(ist, NULL);

        }

    }

    poll_filters();

    flush_encoders();



    term_exit();



    /* write the trailer if needed and close file */

    for (i = 0; i < nb_output_files; i++) {

        os = output_files[i]->ctx;

        av_write_trailer(os);

    }



    /* dump report by using the first video and audio streams */

    print_report(1, timer_start);



    /* close each encoder */

    for (i = 0; i < nb_output_streams; i++) {

        ost = output_streams[i];

        if (ost->encoding_needed) {

            av_freep(&ost->st->codec->stats_in);

            avcodec_close(ost->st->codec);

        }

    }



    /* close each decoder */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (ist->decoding_needed) {

            avcodec_close(ist->st->codec);

        }

    }



    /* finished ! */

    ret = 0;



 fail:

    av_freep(&no_packet);



    if (output_streams) {

        for (i = 0; i < nb_output_streams; i++) {

            ost = output_streams[i];

            if (ost) {

                if (ost->stream_copy)

                    av_freep(&ost->st->codec->extradata);

                if (ost->logfile) {

                    fclose(ost->logfile);

                    ost->logfile = NULL;

                }

                av_fifo_free(ost->fifo); /* works even if fifo is not

                                             initialized but set to zero */

                av_freep(&ost->st->codec->subtitle_header);

                av_free(ost->forced_kf_pts);

                if (ost->avr)

                    avresample_free(&ost->avr);

                av_dict_free(&ost->opts);

            }

        }

    }

    return ret;

}

static int transcode(void)

{

    int ret, i;

    AVFormatContext *is, *os;

    OutputStream *ost;

    InputStream *ist;

    uint8_t *no_packet;

    int no_packet_count = 0;

    int64_t timer_start;

    int key;



    if (!(no_packet = av_mallocz(nb_input_files)))

        exit_program(1);



    ret = transcode_init();

    if (ret < 0)

        goto fail;



    if (!using_stdin) {

        av_log(NULL, AV_LOG_INFO, "Press [q] to stop, [?] for help\n");

    }



    timer_start = av_gettime();



    for (; received_sigterm == 0;) {

        int file_index, ist_index;

        AVPacket pkt;

        int64_t cur_time= av_gettime();



        /* if 'q' pressed, exits */

        if (!using_stdin) {

            static int64_t last_time;

            if (received_nb_signals)

                break;

            /* read_key() returns 0 on EOF */

            if(cur_time - last_time >= 100000 && !run_as_daemon){

                key =  read_key();

                last_time = cur_time;

            }else

                key = -1;

            if (key == 'q')

                break;

            if (key == '+') av_log_set_level(av_log_get_level()+10);

            if (key == '-') av_log_set_level(av_log_get_level()-10);

            if (key == 's') qp_hist     ^= 1;

            if (key == 'h'){

                if (do_hex_dump){

                    do_hex_dump = do_pkt_dump = 0;

                } else if(do_pkt_dump){

                    do_hex_dump = 1;

                } else

                    do_pkt_dump = 1;

                av_log_set_level(AV_LOG_DEBUG);

            }

            if (key == 'c' || key == 'C'){

                char buf[4096], target[64], command[256], arg[256] = {0};

                double time;

                int k, n = 0;

                fprintf(stderr, "\nEnter command: <target> <time> <command>[ <argument>]\n");

                i = 0;

                while ((k = read_key()) != '\n' && k != '\r' && i < sizeof(buf)-1)

                    if (k > 0)

                        buf[i++] = k;

                buf[i] = 0;

                if (k > 0 &&

                    (n = sscanf(buf, "%63[^ ] %lf %255[^ ] %255[^\n]", target, &time, command, arg)) >= 3) {

                    av_log(NULL, AV_LOG_DEBUG, "Processing command target:%s time:%f command:%s arg:%s",

                           target, time, command, arg);

                    for (i = 0; i < nb_filtergraphs; i++) {

                        FilterGraph *fg = filtergraphs[i];

                        if (fg->graph) {

                            if (time < 0) {

                                ret = avfilter_graph_send_command(fg->graph, target, command, arg, buf, sizeof(buf),

                                                                  key == 'c' ? AVFILTER_CMD_FLAG_ONE : 0);

                                fprintf(stderr, "Command reply for stream %d: ret:%d res:%s\n", i, ret, buf);

                            } else {

                                ret = avfilter_graph_queue_command(fg->graph, target, command, arg, 0, time);

                            }

                        }

                    }

                } else {

                    av_log(NULL, AV_LOG_ERROR,

                           "Parse error, at least 3 arguments were expected, "

                           "only %d given in string '%s'\n", n, buf);

                }

            }

            if (key == 'd' || key == 'D'){

                int debug=0;

                if(key == 'D') {

                    debug = input_streams[0]->st->codec->debug<<1;

                    if(!debug) debug = 1;

                    while(debug & (FF_DEBUG_DCT_COEFF|FF_DEBUG_VIS_QP|FF_DEBUG_VIS_MB_TYPE)) //unsupported, would just crash

                        debug += debug;

                }else

                    if(scanf("%d", &debug)!=1)

                        fprintf(stderr,"error parsing debug value\n");

                for(i=0;i<nb_input_streams;i++) {

                    input_streams[i]->st->codec->debug = debug;

                }

                for(i=0;i<nb_output_streams;i++) {

                    ost = output_streams[i];

                    ost->st->codec->debug = debug;

                }

                if(debug) av_log_set_level(AV_LOG_DEBUG);

                fprintf(stderr,"debug=%d\n", debug);

            }

            if (key == '?'){

                fprintf(stderr, "key    function\n"

                                "?      show this help\n"

                                "+      increase verbosity\n"

                                "-      decrease verbosity\n"

                                "c      Send command to filtergraph\n"

                                "D      cycle through available debug modes\n"

                                "h      dump packets/hex press to cycle through the 3 states\n"

                                "q      quit\n"

                                "s      Show QP histogram\n"

                );

            }

        }



        /* check if there's any stream where output is still needed */

        if (!need_output()) {

            av_log(NULL, AV_LOG_VERBOSE, "No more output streams to write to, finishing.\n");

            break;

        }



        /* select the stream that we must read now */

        file_index = select_input_file(no_packet);

        /* if none, if is finished */

        if (file_index < 0) {

            if (no_packet_count) {

                no_packet_count = 0;

                memset(no_packet, 0, nb_input_files);

                usleep(10000);

                continue;

            }

            break;

        }



        /* read a frame from it and output it in the fifo */

        is  = input_files[file_index]->ctx;

        ret = av_read_frame(is, &pkt);

        if (ret == AVERROR(EAGAIN)) {

            no_packet[file_index] = 1;

            no_packet_count++;

            continue;

        }

        if (ret < 0) {

            input_files[file_index]->eof_reached = 1;



            for (i = 0; i < input_files[file_index]->nb_streams; i++) {

                ist = input_streams[input_files[file_index]->ist_index + i];

                if (ist->decoding_needed)

                    output_packet(ist, NULL);

            }



            if (opt_shortest)

                break;

            else

                continue;

        }



        no_packet_count = 0;

        memset(no_packet, 0, nb_input_files);



        if (do_pkt_dump) {

            av_pkt_dump_log2(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump,

                             is->streams[pkt.stream_index]);

        }

        /* the following test is needed in case new streams appear

           dynamically in stream : we ignore them */

        if (pkt.stream_index >= input_files[file_index]->nb_streams)

            goto discard_packet;

        ist_index = input_files[file_index]->ist_index + pkt.stream_index;

        ist = input_streams[ist_index];

        if (ist->discard)

            goto discard_packet;



        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);

        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);



        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts *= ist->ts_scale;

        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts *= ist->ts_scale;



        if (debug_ts) {

            av_log(NULL, AV_LOG_INFO, "demuxer -> ist_index:%d type:%s "

                    "next_dts:%s next_dts_time:%s next_pts:%s next_pts_time:%s  pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s off:%"PRId64"\n",

                    ist_index, av_get_media_type_string(ist->st->codec->codec_type),

                    av_ts2str(ist->next_dts), av_ts2timestr(ist->next_dts, &ist->st->time_base),

                    av_ts2str(ist->next_pts), av_ts2timestr(ist->next_pts, &ist->st->time_base),

                    av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &ist->st->time_base),

                    av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &ist->st->time_base),

                    input_files[ist->file_index]->ts_offset);

        }



        if (pkt.dts != AV_NOPTS_VALUE && ist->next_dts != AV_NOPTS_VALUE && !copy_ts) {

            int64_t pkt_dts = av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

            int64_t delta   = pkt_dts - ist->next_dts;

            if (is->iformat->flags & AVFMT_TS_DISCONT) {

            if(delta < -1LL*dts_delta_threshold*AV_TIME_BASE ||

                (delta > 1LL*dts_delta_threshold*AV_TIME_BASE &&

                 ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                pkt_dts+1<ist->pts){

                input_files[ist->file_index]->ts_offset -= delta;

                av_log(NULL, AV_LOG_DEBUG,

                       "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n",

                       delta, input_files[ist->file_index]->ts_offset);

                pkt.dts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

                if (pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            }

            } else {

                if ( delta < -1LL*dts_error_threshold*AV_TIME_BASE ||

                    (delta > 1LL*dts_error_threshold*AV_TIME_BASE && ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                     pkt_dts+1<ist->pts){

                    av_log(NULL, AV_LOG_WARNING, "DTS %"PRId64", next:%"PRId64" st:%d invalid dropping\n", pkt.dts, ist->next_dts, pkt.stream_index);

                    pkt.dts = AV_NOPTS_VALUE;

                }

                if (pkt.pts != AV_NOPTS_VALUE){

                    int64_t pkt_pts = av_rescale_q(pkt.pts, ist->st->time_base, AV_TIME_BASE_Q);

                    delta   = pkt_pts - ist->next_dts;

                    if ( delta < -1LL*dts_error_threshold*AV_TIME_BASE ||

                        (delta > 1LL*dts_error_threshold*AV_TIME_BASE && ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                        pkt_pts+1<ist->pts) {

                        av_log(NULL, AV_LOG_WARNING, "PTS %"PRId64", next:%"PRId64" invalid dropping st:%d\n", pkt.pts, ist->next_dts, pkt.stream_index);

                        pkt.pts = AV_NOPTS_VALUE;

                    }

                }

            }

        }



        // fprintf(stderr,"read #%d.%d size=%d\n", ist->file_index, ist->st->index, pkt.size);

        if ((ret = output_packet(ist, &pkt)) < 0 ||

            ((ret = poll_filters()) < 0 && ret != AVERROR_EOF)) {

            char buf[128];

            av_strerror(ret, buf, sizeof(buf));

            av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d: %s\n",

                   ist->file_index, ist->st->index, buf);

            if (exit_on_error)

                exit_program(1);

            av_free_packet(&pkt);

            continue;

        }



    discard_packet:

        av_free_packet(&pkt);



        /* dump report by using the output first video and audio streams */

        print_report(0, timer_start, cur_time);

    }



    /* at the end of stream, we must flush the decoder buffers */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (!input_files[ist->file_index]->eof_reached && ist->decoding_needed) {

            output_packet(ist, NULL);

        }

    }

    poll_filters();

    flush_encoders();



    term_exit();



    /* write the trailer if needed and close file */

    for (i = 0; i < nb_output_files; i++) {

        os = output_files[i]->ctx;

        av_write_trailer(os);

    }



    /* dump report by using the first video and audio streams */

    print_report(1, timer_start, av_gettime());



    /* close each encoder */

    for (i = 0; i < nb_output_streams; i++) {

        ost = output_streams[i];

        if (ost->encoding_needed) {

            av_freep(&ost->st->codec->stats_in);

            avcodec_close(ost->st->codec);

        }

    }



    /* close each decoder */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (ist->decoding_needed) {

            avcodec_close(ist->st->codec);

        }

    }



    /* finished ! */

    ret = 0;



 fail:

    av_freep(&no_packet);



    if (output_streams) {

        for (i = 0; i < nb_output_streams; i++) {

            ost = output_streams[i];

            if (ost) {

                if (ost->stream_copy)

                    av_freep(&ost->st->codec->extradata);

                if (ost->logfile) {

                    fclose(ost->logfile);

                    ost->logfile = NULL;

                }

                av_freep(&ost->st->codec->subtitle_header);

                av_free(ost->forced_kf_pts);

                av_dict_free(&ost->opts);

            }

        }

    }

    return ret;

}

static void stream_component_close(VideoState *is, int stream_index)

{

    AVFormatContext *ic = is->ic;

    AVCodecContext *avctx;



    if (stream_index < 0 || stream_index >= ic->nb_streams)

        return;

    avctx = ic->streams[stream_index]->codec;



    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        packet_queue_abort(&is->audioq);



        SDL_CloseAudio();



        packet_queue_flush(&is->audioq);

        av_free_packet(&is->audio_pkt);

        if (is->swr_ctx)

            swr_free(&is->swr_ctx);

        av_freep(&is->audio_buf1);

        is->audio_buf = NULL;

        av_freep(&is->frame);



        if (is->rdft) {

            av_rdft_end(is->rdft);

            av_freep(&is->rdft_data);

            is->rdft = NULL;

            is->rdft_bits = 0;

        }

        break;

    case AVMEDIA_TYPE_VIDEO:

        packet_queue_abort(&is->videoq);



        /* note: we also signal this mutex to make sure we deblock the

           video thread in all cases */

        SDL_LockMutex(is->pictq_mutex);

        SDL_CondSignal(is->pictq_cond);

        SDL_UnlockMutex(is->pictq_mutex);



        SDL_WaitThread(is->video_tid, NULL);



        packet_queue_flush(&is->videoq);

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        packet_queue_abort(&is->subtitleq);



        /* note: we also signal this mutex to make sure we deblock the

           video thread in all cases */

        SDL_LockMutex(is->subpq_mutex);

        is->subtitle_stream_changed = 1;



        SDL_CondSignal(is->subpq_cond);

        SDL_UnlockMutex(is->subpq_mutex);



        SDL_WaitThread(is->subtitle_tid, NULL);



        packet_queue_flush(&is->subtitleq);

        break;

    default:

        break;

    }



    ic->streams[stream_index]->discard = AVDISCARD_ALL;

    avcodec_close(avctx);

#if CONFIG_AVFILTER

    free_buffer_pool(&is->buffer_pool);

#endif

    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        is->audio_st = NULL;

        is->audio_stream = -1;

        break;

    case AVMEDIA_TYPE_VIDEO:

        is->video_st = NULL;

        is->video_stream = -1;

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        is->subtitle_st = NULL;

        is->subtitle_stream = -1;

        break;

    default:

        break;

    }

}

int ff_xvmc_field_start(MpegEncContext *s, AVCodecContext *avctx)

{

    struct xvmc_pix_fmt *last, *next, *render = (struct xvmc_pix_fmt*)s->current_picture.f.data[2];

    const int mb_block_count = 4 + (1 << s->chroma_format);



    assert(avctx);

    if (!render || render->xvmc_id != AV_XVMC_ID ||

        !render->data_blocks || !render->mv_blocks ||

        (unsigned int)render->allocated_mv_blocks   > INT_MAX/(64*6) ||

        (unsigned int)render->allocated_data_blocks > INT_MAX/64     ||

        !render->p_surface) {

        av_log(avctx, AV_LOG_ERROR,

               "Render token doesn't look as expected.\n");

        return -1; // make sure that this is a render packet

    }



    if (render->filled_mv_blocks_num) {

        av_log(avctx, AV_LOG_ERROR,

               "Rendering surface contains %i unprocessed blocks.\n",

               render->filled_mv_blocks_num);

        return -1;

    }

    if (render->allocated_mv_blocks   < 1 ||

        render->allocated_data_blocks <  render->allocated_mv_blocks*mb_block_count ||

        render->start_mv_blocks_num   >= render->allocated_mv_blocks                ||

        render->next_free_data_block_num >

                        render->allocated_data_blocks -

                        mb_block_count*(render->allocated_mv_blocks-render->start_mv_blocks_num)) {

        av_log(avctx, AV_LOG_ERROR,

               "Rendering surface doesn't provide enough block structures to work with.\n");

        return -1;

    }



    render->picture_structure = s->picture_structure;

    render->flags             = s->first_field ? 0 : XVMC_SECOND_FIELD;

    render->p_future_surface  = NULL;

    render->p_past_surface    = NULL;



    switch(s->pict_type) {

        case  AV_PICTURE_TYPE_I:

            return 0; // no prediction from other frames

        case  AV_PICTURE_TYPE_B:

            next = (struct xvmc_pix_fmt*)s->next_picture.f.data[2];

            if (!next)

                return -1;

            if (next->xvmc_id != AV_XVMC_ID)

                return -1;

            render->p_future_surface = next->p_surface;

            // no return here, going to set forward prediction

        case  AV_PICTURE_TYPE_P:

            last = (struct xvmc_pix_fmt*)s->last_picture.f.data[2];

            if (!last)

                last = render; // predict second field from the first

            if (last->xvmc_id != AV_XVMC_ID)

                return -1;

            render->p_past_surface = last->p_surface;

            return 0;

    }



return -1;

}

void ff_xvmc_init_block(MpegEncContext *s)

{

    struct xvmc_render_state *render = (struct xvmc_render_state*)s->current_picture.data[2];

    assert(render);

    if (!render || render->magic != AV_XVMC_RENDER_MAGIC) {

        assert(0);

        return; // make sure that this is a render packet

    }

    s->block = (DCTELEM *)(render->data_blocks + render->next_free_data_block_num * 64);

}

int ff_xvmc_field_start(MpegEncContext*s, AVCodecContext *avctx)

{

    struct xvmc_pixfmt_render *last, *next, *render = (struct xvmc_pixfmt_render*)s->current_picture.data[2];

    const int mb_block_count = 4 + (1 << s->chroma_format);



    assert(avctx);

    if (!render || render->magic_id != AV_XVMC_RENDER_MAGIC ||

        !render->data_blocks || !render->mv_blocks){

        av_log(avctx, AV_LOG_ERROR,

               "Render token doesn't look as expected.\n");

        return -1; // make sure that this is a render packet

    }



    render->picture_structure = s->picture_structure;

    render->flags             = s->first_field ? 0 : XVMC_SECOND_FIELD;



    if (render->filled_mv_blocks_num) {

        av_log(avctx, AV_LOG_ERROR,

               "Rendering surface contains %i unprocessed blocks.\n",

               render->filled_mv_blocks_num);

        return -1;

    }

    if (render->total_number_of_mv_blocks   < 1 ||

        render->total_number_of_data_blocks < mb_block_count) {

        av_log(avctx, AV_LOG_ERROR,

               "Rendering surface doesn't provide enough block structures to work with.\n");

        return -1;

    }

    if (render->total_number_of_mv_blocks   < 1 ||

        render->total_number_of_data_blocks < mb_block_count) {

        av_log(avctx, AV_LOG_ERROR,

               "Rendering surface doesn't provide enough block structures to work with.\n");

        return -1;

    }



    render->p_future_surface = NULL;

    render->p_past_surface   = NULL;



    switch(s->pict_type) {

        case  FF_I_TYPE:

            return 0; // no prediction from other frames

        case  FF_B_TYPE:

            next = (struct xvmc_pixfmt_render*)s->next_picture.data[2];

            if (!next)

                return -1;

            if (next->magic_id != AV_XVMC_RENDER_MAGIC)

                return -1;

            render->p_future_surface = next->p_surface;

            // no return here, going to set forward prediction

        case  FF_P_TYPE:

            last = (struct xvmc_pixfmt_render*)s->last_picture.data[2];

            if (!last)

                last = render; // predict second field from the first

            if (last->magic_id != AV_XVMC_RENDER_MAGIC)

                return -1;

            render->p_past_surface = last->p_surface;

            return 0;

    }



return -1;

}

void ff_xvmc_decode_mb(MpegEncContext *s)

{

    XvMCMacroBlock *mv_block;

    struct xvmc_pix_fmt *render;

    int i, cbp, blocks_per_mb;



    const int mb_xy = s->mb_y * s->mb_stride + s->mb_x;





    if (s->encoding) {

        av_log(s->avctx, AV_LOG_ERROR, "XVMC doesn't support encoding!!!\n");

        return;

    }



    // from ff_mpv_decode_mb(), update DC predictors for P macroblocks

    if (!s->mb_intra) {

        s->last_dc[0] =

        s->last_dc[1] =

        s->last_dc[2] =  128 << s->intra_dc_precision;

    }



    // MC doesn't skip blocks

    s->mb_skipped = 0;





    // Do I need to export quant when I could not perform postprocessing?

    // Anyway, it doesn't hurt.

    s->current_picture.qscale_table[mb_xy] = s->qscale;



    // start of XVMC-specific code

    render = (struct xvmc_pix_fmt*)s->current_picture.f->data[2];

    assert(render);

    assert(render->xvmc_id == AV_XVMC_ID);

    assert(render->mv_blocks);



    // take the next free macroblock

    mv_block = &render->mv_blocks[render->start_mv_blocks_num +

                                  render->filled_mv_blocks_num];



    mv_block->x        = s->mb_x;

    mv_block->y        = s->mb_y;

    mv_block->dct_type = s->interlaced_dct; // XVMC_DCT_TYPE_FRAME/FIELD;

    if (s->mb_intra) {

        mv_block->macroblock_type = XVMC_MB_TYPE_INTRA; // no MC, all done

    } else {

        mv_block->macroblock_type = XVMC_MB_TYPE_PATTERN;



        if (s->mv_dir & MV_DIR_FORWARD) {

            mv_block->macroblock_type |= XVMC_MB_TYPE_MOTION_FORWARD;

            // PMV[n][dir][xy] = mv[dir][n][xy]

            mv_block->PMV[0][0][0] = s->mv[0][0][0];

            mv_block->PMV[0][0][1] = s->mv[0][0][1];

            mv_block->PMV[1][0][0] = s->mv[0][1][0];

            mv_block->PMV[1][0][1] = s->mv[0][1][1];

        }

        if (s->mv_dir & MV_DIR_BACKWARD) {

            mv_block->macroblock_type |= XVMC_MB_TYPE_MOTION_BACKWARD;

            mv_block->PMV[0][1][0] = s->mv[1][0][0];

            mv_block->PMV[0][1][1] = s->mv[1][0][1];

            mv_block->PMV[1][1][0] = s->mv[1][1][0];

            mv_block->PMV[1][1][1] = s->mv[1][1][1];

        }



        switch(s->mv_type) {

            case  MV_TYPE_16X16:

                mv_block->motion_type = XVMC_PREDICTION_FRAME;

                break;

            case  MV_TYPE_16X8:

                mv_block->motion_type = XVMC_PREDICTION_16x8;

                break;

            case  MV_TYPE_FIELD:

                mv_block->motion_type = XVMC_PREDICTION_FIELD;

                if (s->picture_structure == PICT_FRAME) {

                    mv_block->PMV[0][0][1] <<= 1;

                    mv_block->PMV[1][0][1] <<= 1;

                    mv_block->PMV[0][1][1] <<= 1;

                    mv_block->PMV[1][1][1] <<= 1;

                }

                break;

            case  MV_TYPE_DMV:

                mv_block->motion_type = XVMC_PREDICTION_DUAL_PRIME;

                if (s->picture_structure == PICT_FRAME) {



                    mv_block->PMV[0][0][0] = s->mv[0][0][0];      // top from top

                    mv_block->PMV[0][0][1] = s->mv[0][0][1] << 1;



                    mv_block->PMV[0][1][0] = s->mv[0][0][0];      // bottom from bottom

                    mv_block->PMV[0][1][1] = s->mv[0][0][1] << 1;



                    mv_block->PMV[1][0][0] = s->mv[0][2][0];      // dmv00, top from bottom

                    mv_block->PMV[1][0][1] = s->mv[0][2][1] << 1; // dmv01



                    mv_block->PMV[1][1][0] = s->mv[0][3][0];      // dmv10, bottom from top

                    mv_block->PMV[1][1][1] = s->mv[0][3][1] << 1; // dmv11



                } else {

                    mv_block->PMV[0][1][0] = s->mv[0][2][0];      // dmv00

                    mv_block->PMV[0][1][1] = s->mv[0][2][1];      // dmv01

                }

                break;

            default:

                assert(0);

        }



        mv_block->motion_vertical_field_select = 0;



        // set correct field references

        if (s->mv_type == MV_TYPE_FIELD || s->mv_type == MV_TYPE_16X8) {

            mv_block->motion_vertical_field_select |= s->field_select[0][0];

            mv_block->motion_vertical_field_select |= s->field_select[1][0] << 1;

            mv_block->motion_vertical_field_select |= s->field_select[0][1] << 2;

            mv_block->motion_vertical_field_select |= s->field_select[1][1] << 3;

        }

    } // !intra

    // time to handle data blocks

    mv_block->index = render->next_free_data_block_num;



    blocks_per_mb = 6;

    if (s->chroma_format >= 2) {

        blocks_per_mb = 4 + (1 << s->chroma_format);

    }



    // calculate cbp

    cbp = 0;

    for (i = 0; i < blocks_per_mb; i++) {

        cbp += cbp;

        if (s->block_last_index[i] >= 0)

            cbp++;

    }



    if (s->avctx->flags & AV_CODEC_FLAG_GRAY) {

        if (s->mb_intra) {                                   // intra frames are always full chroma blocks

            for (i = 4; i < blocks_per_mb; i++) {

                memset(s->pblocks[i], 0, sizeof(*s->pblocks[i]));  // so we need to clear them

                if (!render->unsigned_intra)

                    *s->pblocks[i][0] = 1 << 10;

            }

        } else {

            cbp &= 0xf << (blocks_per_mb - 4);

            blocks_per_mb = 4;                               // luminance blocks only

        }

    }

    mv_block->coded_block_pattern = cbp;

    if (cbp == 0)

        mv_block->macroblock_type &= ~XVMC_MB_TYPE_PATTERN;



    for (i = 0; i < blocks_per_mb; i++) {

        if (s->block_last_index[i] >= 0) {

            // I do not have unsigned_intra MOCO to test, hope it is OK.

            if (s->mb_intra && (render->idct || !render->unsigned_intra))

                *s->pblocks[i][0] -= 1 << 10;

            if (!render->idct) {

                s->idsp.idct(*s->pblocks[i]);

                /* It is unclear if MC hardware requires pixel diff values to be

                 * in the range [-255;255]. TODO: Clipping if such hardware is

                 * ever found. As of now it would only be an unnecessary

                 * slowdown. */

            }

            // copy blocks only if the codec doesn't support pblocks reordering

            if (s->avctx->xvmc_acceleration == 1) {

                memcpy(&render->data_blocks[render->next_free_data_block_num*64],

                       s->pblocks[i], sizeof(*s->pblocks[i]));

            }

            render->next_free_data_block_num++;

        }

    }

    render->filled_mv_blocks_num++;



    assert(render->filled_mv_blocks_num     <= render->allocated_mv_blocks);

    assert(render->next_free_data_block_num <= render->allocated_data_blocks);

    /* The above conditions should not be able to fail as long as this function

     * is used and the following 'if ()' automatically calls a callback to free

     * blocks. */





    if (render->filled_mv_blocks_num == render->allocated_mv_blocks)

        ff_mpeg_draw_horiz_band(s, 0, 0);

}

static void av_estimate_timings_from_bit_rate(AVFormatContext *ic)

{

    int64_t filesize, duration;

    int bit_rate, i;

    AVStream *st;



    /* if bit_rate is already set, we believe it */

    if (ic->bit_rate == 0) {

        bit_rate = 0;

        for(i=0;i<ic->nb_streams;i++) {

            st = ic->streams[i];

            bit_rate += st->codec->bit_rate;

        }

        ic->bit_rate = bit_rate;

    }



    /* if duration is already set, we believe it */

    if (ic->duration == AV_NOPTS_VALUE &&

        ic->bit_rate != 0 &&

        ic->file_size != 0)  {

        filesize = ic->file_size;

        if (filesize > 0) {

            for(i = 0; i < ic->nb_streams; i++) {

                st = ic->streams[i];

                duration= av_rescale(8*filesize, st->time_base.den, ic->bit_rate*(int64_t)st->time_base.num);

                if (st->duration == AV_NOPTS_VALUE)

                    st->duration = duration;

            }

        }

    }

}

void ff_configure_buffers_for_index(AVFormatContext *s, int64_t time_tolerance)

{

    int ist1, ist2;

    int64_t pos_delta = 0;

    //We could use URLProtocol flags here but as many user applications do not use URLProtocols this would be unreliable

    const char *proto = avio_find_protocol_name(s->filename);



    if (!(strcmp(proto, "file") && strcmp(proto, "pipe") && strcmp(proto, "cache")))

        return;



    for (ist1 = 0; ist1 < s->nb_streams; ist1++) {

        AVStream *st1 = s->streams[ist1];

        for (ist2 = 0; ist2 < s->nb_streams; ist2++) {

            AVStream *st2 = s->streams[ist2];

            int i1, i2;



            if (ist1 == ist2)

                continue;



            for (i1 = i2 = 0; i1 < st1->nb_index_entries; i1++) {

                AVIndexEntry *e1 = &st1->index_entries[i1];

                int64_t e1_pts = av_rescale_q(e1->timestamp, st1->time_base, AV_TIME_BASE_Q);



                for (; i2 < st2->nb_index_entries; i2++) {

                    AVIndexEntry *e2 = &st2->index_entries[i2];

                    int64_t e2_pts = av_rescale_q(e2->timestamp, st2->time_base, AV_TIME_BASE_Q);

                    if (e2_pts - e1_pts < time_tolerance)

                        continue;

                    pos_delta = FFMAX(pos_delta, e1->pos - e2->pos);

                    break;

                }

            }

        }

    }



    pos_delta *= 2;

    /* XXX This could be adjusted depending on protocol*/

    if (s->pb->buffer_size < pos_delta && pos_delta < (1<<24)) {

        av_log(s, AV_LOG_VERBOSE, "Reconfiguring buffers to size %"PRId64"\n", pos_delta);

        ffio_set_buf_size(s->pb, pos_delta);

        s->pb->short_seek_threshold = FFMAX(s->pb->short_seek_threshold, pos_delta/2);

    }

}

static int guess_ni_flag(AVFormatContext *s)

{

    int i;

    int64_t last_start = 0;

    int64_t first_end  = INT64_MAX;

    int64_t oldpos     = avio_tell(s->pb);

    int *idx;

    int64_t min_pos, pos;



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        int n        = st->nb_index_entries;

        unsigned int size;



        if (n <= 0)

            continue;



        if (n >= 2) {

            int64_t pos = st->index_entries[0].pos;

            avio_seek(s->pb, pos + 4, SEEK_SET);

            size = avio_rl32(s->pb);

            if (pos + size > st->index_entries[1].pos)

                last_start = INT64_MAX;

        }



        if (st->index_entries[0].pos > last_start)

            last_start = st->index_entries[0].pos;

        if (st->index_entries[n - 1].pos < first_end)

            first_end = st->index_entries[n - 1].pos;

    }

    avio_seek(s->pb, oldpos, SEEK_SET);

    if (last_start > first_end)

        return 1;

    idx= av_calloc(s->nb_streams, sizeof(*idx));

    if (!idx)

        return 0;

    for (min_pos=pos=0; min_pos!=INT64_MAX; pos= min_pos+1LU) {

        int64_t max_dts = INT64_MIN/2, min_dts= INT64_MAX/2;

        min_pos = INT64_MAX;



        for (i=0; i<s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            AVIStream *ast = st->priv_data;

            int n= st->nb_index_entries;

            while (idx[i]<n && st->index_entries[idx[i]].pos < pos)

                idx[i]++;

            if (idx[i] < n) {

                min_dts = FFMIN(min_dts, av_rescale_q(st->index_entries[idx[i]].timestamp/FFMAX(ast->sample_size, 1), st->time_base, AV_TIME_BASE_Q));

                min_pos = FFMIN(min_pos, st->index_entries[idx[i]].pos);

            }

            if (idx[i])

                max_dts = FFMAX(max_dts, av_rescale_q(st->index_entries[idx[i]-1].timestamp/FFMAX(ast->sample_size, 1), st->time_base, AV_TIME_BASE_Q));

        }

        if (max_dts - min_dts > 2*AV_TIME_BASE) {

            av_free(idx);

            return 1;

        }

    }

    av_free(idx);

    return 0;

}

static void estimate_timings_from_bit_rate(AVFormatContext *ic)

{

    int64_t filesize, duration;

    int i;

    AVStream *st;



    /* if bit_rate is already set, we believe it */

    if (ic->bit_rate <= 0) {

        int bit_rate = 0;

        for(i=0;i<ic->nb_streams;i++) {

            st = ic->streams[i];

            if (st->codec->bit_rate > 0) {

                if (INT_MAX - st->codec->bit_rate > bit_rate) {

                    bit_rate = 0;

                    break;

                }

                bit_rate += st->codec->bit_rate;

            }

        }

        ic->bit_rate = bit_rate;

    }



    /* if duration is already set, we believe it */

    if (ic->duration == AV_NOPTS_VALUE &&

        ic->bit_rate != 0) {

        filesize = ic->pb ? avio_size(ic->pb) : 0;

        if (filesize > 0) {

            for(i = 0; i < ic->nb_streams; i++) {

                st = ic->streams[i];

                duration= av_rescale(8*filesize, st->time_base.den, ic->bit_rate*(int64_t)st->time_base.num);

                if (st->duration == AV_NOPTS_VALUE)

                    st->duration = duration;

            }

        }

    }

}

