int ff_eval_refl(int *refl, const int16_t *coefs, AVCodecContext *avctx)

{

    int b, i, j;

    int buffer1[LPC_ORDER];

    int buffer2[LPC_ORDER];

    int *bp1 = buffer1;

    int *bp2 = buffer2;



    for (i=0; i < LPC_ORDER; i++)

        buffer2[i] = coefs[i];



    refl[LPC_ORDER-1] = bp2[LPC_ORDER-1];



    if ((unsigned) bp2[LPC_ORDER-1] + 0x1000 > 0x1fff) {

        av_log(avctx, AV_LOG_ERROR, "Overflow. Broken sample?\n");

        return 1;

    }



    for (i = LPC_ORDER-2; i >= 0; i--) {

        b = 0x1000-((bp2[i+1] * bp2[i+1]) >> 12);



        if (!b)

            b = -2;



        b = 0x1000000 / b;

        for (j=0; j <= i; j++) {

#if CONFIG_FTRAPV

            int a = bp2[j] - ((refl[i+1] * bp2[i-j]) >> 12);

            if((int)(a*(unsigned)b) != a*(int64_t)b)

                return 1;

#endif

            bp1[j] = ((bp2[j] - ((refl[i+1] * bp2[i-j]) >> 12)) * b) >> 12;

        }



        if ((unsigned) bp1[i] + 0x1000 > 0x1fff)

            return 1;



        refl[i] = bp1[i];



        FFSWAP(int *, bp1, bp2);

    }

    return 0;

}

int av_aes_init(AVAES *a, const uint8_t *key, int key_bits, int decrypt) {

    int i, j, t, rconpointer = 0;

    uint8_t tk[8][4];

    int KC= key_bits>>5;

    int rounds= KC + 6;

    uint8_t  log8[256];

    uint8_t alog8[512];



    if(!enc_multbl[4][1023]){

        j=1;

        for(i=0; i<255; i++){

            alog8[i]=

            alog8[i+255]= j;

            log8[j]= i;

            j^= j+j;

            if(j>255) j^= 0x11B;

        }

        for(i=0; i<256; i++){

            j= i ? alog8[255-log8[i]] : 0;

            j ^= (j<<1) ^ (j<<2) ^ (j<<3) ^ (j<<4);

            j = (j ^ (j>>8) ^ 99) & 255;

            inv_sbox[j]= i;

            sbox    [i]= j;

        }

        init_multbl2(dec_multbl[0], (int[4]){0xe, 0x9, 0xd, 0xb}, log8, alog8, inv_sbox);

        init_multbl2(enc_multbl[0], (int[4]){0x2, 0x1, 0x1, 0x3}, log8, alog8, sbox);

    }



    if(key_bits!=128 && key_bits!=192 && key_bits!=256)

        return -1;



    a->rounds= rounds;



    memcpy(tk, key, KC*4);



    for(t= 0; t < (rounds+1)*16;) {

        memcpy(a->round_key[0][0]+t, tk, KC*4);

        t+= KC*4;



        for(i = 0; i < 4; i++)

            tk[0][i] ^= sbox[tk[KC-1][(i+1)&3]];

        tk[0][0] ^= rcon[rconpointer++];



        for(j = 1; j < KC; j++){

            if(KC != 8 || j != KC>>1)

                for(i = 0; i < 4; i++) tk[j][i] ^=      tk[j-1][i];

            else

                for(i = 0; i < 4; i++) tk[j][i] ^= sbox[tk[j-1][i]];

        }

    }



    if(decrypt){

        for(i=1; i<rounds; i++){

            uint8_t tmp[3][16];

            memcpy(tmp[2], a->round_key[i][0], 16);

            subshift(tmp[1], 0, sbox);

            mix(tmp, dec_multbl, 1, 3);

            memcpy(a->round_key[i][0], tmp[0], 16);

        }

    }else{

        for(i=0; i<(rounds+1)>>1; i++){

            for(j=0; j<16; j++)

                FFSWAP(int, a->round_key[i][0][j], a->round_key[rounds-i][0][j]);

        }

    }



    return 0;

}

AVAES *av_aes_init(uint8_t *key, int key_bits, int decrypt) {

    AVAES *a;

    int i, j, t, rconpointer = 0;

    uint8_t tk[8][4];

    int KC= key_bits>>5;

    int rounds= KC + 6;

    uint8_t  log8[256];

    uint8_t alog8[512];



    if(!sbox[255]){

        j=1;

        for(i=0; i<255; i++){

            alog8[i]=

            alog8[i+255]= j;

            log8[j]= i;

            j^= j+j;

            if(j>255) j^= 0x11B;

        }

        for(i=0; i<256; i++){

            j= i ? alog8[255-log8[i]] : 0;

            j ^= (j<<1) ^ (j<<2) ^ (j<<3) ^ (j<<4);

            j = (j ^ (j>>8) ^ 99) & 255;

            inv_sbox[j]= i;

            sbox    [i]= j;

        }

        init_multbl2(dec_multbl[0], (int[4]){0xe, 0x9, 0xd, 0xb}, log8, alog8, inv_sbox);

        init_multbl2(enc_multbl[0], (int[4]){0x2, 0x1, 0x1, 0x3}, log8, alog8, sbox);

    }



    if(key_bits!=128 && key_bits!=192 && key_bits!=256)

        return NULL;



    a= av_malloc(sizeof(AVAES));

    a->rounds= rounds;



    memcpy(tk, key, KC*4);



    for(t= 0; t < (rounds+1)*4;) {

        memcpy(a->round_key[0][t], tk, KC*4);

        t+= KC;



        for(i = 0; i < 4; i++)

            tk[0][i] ^= sbox[tk[KC-1][(i+1)&3]];

        tk[0][0] ^= rcon[rconpointer++];



        for(j = 1; j < KC; j++){

            if(KC != 8 || j != KC>>1)

                for(i = 0; i < 4; i++) tk[j][i] ^=      tk[j-1][i];

            else

                for(i = 0; i < 4; i++) tk[j][i] ^= sbox[tk[j-1][i]];

        }

    }



    if(decrypt){

        for(i=1; i<rounds; i++){

            for(j=0; j<16; j++)

                a->round_key[i][0][j]= sbox[a->round_key[i][0][j]];

            mix(a->round_key[i], dec_multbl);

        }

    }else{

        for(i=0; i<(rounds+1)>>1; i++){

            for(j=0; j<16; j++)

                FFSWAP(int, a->round_key[i][0][j], a->round_key[rounds-i][0][j]);

        }

    }



    return a;

}

void av_blowfish_crypt(AVBlowfish *ctx, uint8_t *dst, const uint8_t *src,

                       int count, uint8_t *iv, int decrypt)

{

    uint32_t v0, v1;

    int i;



    while (count > 0) {

        if (decrypt) {

            v0 = AV_RB32(src);

            v1 = AV_RB32(src + 4);



            av_blowfish_crypt_ecb(ctx, &v0, &v1, decrypt);



            AV_WB32(dst, v0);

            AV_WB32(dst + 4, v1);



            if (iv) {

                for (i = 0; i < 8; i++)

                    dst[i] = dst[i] ^ iv[i];

                memcpy(iv, src, 8);

            }

        } else {

            if (iv) {

                for (i = 0; i < 8; i++)

                    dst[i] = src[i] ^ iv[i];

                v0 = AV_RB32(dst);

                v1 = AV_RB32(dst + 4);

            } else {

                v0 = AV_RB32(src);

                v1 = AV_RB32(src + 4);

            }



            av_blowfish_crypt_ecb(ctx, &v0, &v1, decrypt);



            AV_WB32(dst, v0);

            AV_WB32(dst + 4, v1);



            if (iv)

                memcpy(iv, dst, 8);

        }



        src   += 8;

        dst   += 8;

        count -= 8;

    }

}

