static kbd_layout_t *parse_keyboard_layout(const name2keysym_t *table,

                                           const char *language,

                                           kbd_layout_t *k)

{

    FILE *f;

    char * filename;

    char line[1024];

    int len;



    filename = qemu_find_file(QEMU_FILE_TYPE_KEYMAP, language);

    f = filename ? fopen(filename, "r") : NULL;

    g_free(filename);

    if (!f) {

        fprintf(stderr, "Could not read keymap file: '%s'\n", language);

        return NULL;

    }



    if (!k) {

        k = g_malloc0(sizeof(kbd_layout_t));

    }



    for(;;) {

        if (fgets(line, 1024, f) == NULL) {

            break;

        }

        len = strlen(line);

        if (len > 0 && line[len - 1] == '\n') {

            line[len - 1] = '\0';

        }

        if (line[0] == '#') {

            continue;

        }

        if (!strncmp(line, "map ", 4)) {

            continue;

        }

        if (!strncmp(line, "include ", 8)) {

            parse_keyboard_layout(table, line + 8, k);

        } else {

            char *end_of_keysym = line;

            while (*end_of_keysym != 0 && *end_of_keysym != ' ') {

                end_of_keysym++;

            }

            if (*end_of_keysym) {

                int keysym;

                *end_of_keysym = 0;

                keysym = get_keysym(table, line);

                if (keysym == 0) {

                    /* fprintf(stderr, "Warning: unknown keysym %s\n", line);*/

                } else {

                    const char *rest = end_of_keysym + 1;

                    int keycode = strtol(rest, NULL, 0);



                    if (strstr(rest, "numlock")) {

                        add_to_key_range(&k->keypad_range, keycode);

                        add_to_key_range(&k->numlock_range, keysym);

                        /* fprintf(stderr, "keypad keysym %04x keycode %d\n",

                                   keysym, keycode); */

                    }



                    if (strstr(rest, "shift")) {

                        keycode |= SCANCODE_SHIFT;

                    }

                    if (strstr(rest, "altgr")) {

                        keycode |= SCANCODE_ALTGR;

                    }

                    if (strstr(rest, "ctrl")) {

                        keycode |= SCANCODE_CTRL;

                    }



                    add_keysym(line, keysym, keycode, k);



                    if (strstr(rest, "addupper")) {

                        char *c;

                        for (c = line; *c; c++) {

                            *c = qemu_toupper(*c);

                        }

                        keysym = get_keysym(table, line);

                        if (keysym) {

                            add_keysym(line, keysym,

                                       keycode | SCANCODE_SHIFT, k);

                        }

                    }

                }

            }

        }

    }

    fclose(f);

    return k;

}

static int asf_read_marker(AVFormatContext *s, int64_t size)

{

    AVIOContext *pb = s->pb;

    ASFContext *asf = s->priv_data;

    int i, count, name_len, ret;

    char name[1024];



    avio_rl64(pb);            // reserved 16 bytes

    avio_rl64(pb);            // ...

    count = avio_rl32(pb);    // markers count

    avio_rl16(pb);            // reserved 2 bytes

    name_len = avio_rl16(pb); // name length

    for (i = 0; i < name_len; i++)

        avio_r8(pb); // skip the name



    for (i = 0; i < count; i++) {

        int64_t pres_time;

        int name_len;



        avio_rl64(pb);             // offset, 8 bytes

        pres_time = avio_rl64(pb); // presentation time

        pres_time -= asf->hdr.preroll * 10000;

        avio_rl16(pb);             // entry length

        avio_rl32(pb);             // send time

        avio_rl32(pb);             // flags

        name_len = avio_rl32(pb);  // name length

        if ((ret = avio_get_str16le(pb, name_len * 2, name,

                                    sizeof(name))) < name_len)

            avio_skip(pb, name_len - ret);

        avpriv_new_chapter(s, i, (AVRational) { 1, 10000000 }, pres_time,

                           AV_NOPTS_VALUE, name);

    }



    return 0;

}

static int asf_read_generic_value(AVFormatContext *s, uint8_t *name, uint16_t name_len,

                                  int type, AVDictionary **met)

{

    AVIOContext *pb = s->pb;

    uint64_t value;

    char buf[32];



    switch (type) {

    case ASF_BOOL:

        value = avio_rl32(pb);

        break;

    case ASF_DWORD:

        value = avio_rl32(pb);

        break;

    case ASF_QWORD:

        value = avio_rl64(pb);

        break;

    case ASF_WORD:

        value = avio_rl16(pb);

        break;

    default:

        av_freep(&name);

        return AVERROR_INVALIDDATA;

    }

    snprintf(buf, sizeof(buf), "%"PRIu64, value);

    if (av_dict_set(met, name, buf, 0) < 0)

        av_log(s, AV_LOG_WARNING, "av_dict_set failed.\n");



    return 0;

}

static int asf_read_simple_index(AVFormatContext *s, const GUIDParseTable *g)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st    = NULL;

    uint64_t interval; // index entry time interval in 100 ns units, usually it's 1s

    uint32_t pkt_num, nb_entries;

    int32_t prev_pkt_num = -1;

    int i, ret;

    uint64_t size = avio_rl64(pb);



    // simple index objects should be ordered by stream number, this loop tries to find

    // the first not indexed video stream

    for (i = 0; i < asf->nb_streams; i++) {

        if ((asf->asf_st[i]->type == AVMEDIA_TYPE_VIDEO) && !asf->asf_st[i]->indexed) {

            asf->asf_st[i]->indexed = 1;

            st = s->streams[asf->asf_st[i]->index];

            break;

        }

    }

    if (!st) {

        avio_skip(pb, size - 24); // if there's no video stream, skip index object

        return 0;

    }

    avio_skip(pb, 16); // skip File ID

    interval = avio_rl64(pb);

    avio_skip(pb, 4);

    nb_entries = avio_rl32(pb);

    for (i = 0; i < nb_entries; i++) {

        pkt_num = avio_rl32(pb);

        ret = avio_skip(pb, 2);

        if (ret < 0) {

            av_log(s, AV_LOG_ERROR, "Skipping failed in asf_read_simple_index.\n");

            return ret;

        }

        if (prev_pkt_num != pkt_num) {

            av_add_index_entry(st, asf->first_packet_offset + asf->packet_size *

                               pkt_num, av_rescale(interval, i, 10000),

                               asf->packet_size, 0, AVINDEX_KEYFRAME);

            prev_pkt_num = pkt_num;

        }

    }

    asf->is_simple_index = 1;

    align_position(pb, asf->offset, size);



    return 0;

}

static int asf_read_stream_properties(AVFormatContext *s, const GUIDParseTable *g)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    uint64_t size;

    uint32_t err_data_len, ts_data_len; // type specific data length

    uint16_t flags;

    ff_asf_guid stream_type;

    enum AVMediaType type;

    int i, ret;

    uint8_t stream_index;

    AVStream *st;

    ASFStream *asf_st;



    // ASF file must not contain more than 128 streams according to the specification

    if (asf->nb_streams >= ASF_MAX_STREAMS)

        return AVERROR_INVALIDDATA;



    size = avio_rl64(pb);

    ff_get_guid(pb, &stream_type);

    if (!ff_guidcmp(&stream_type, &ff_asf_audio_stream))

        type = AVMEDIA_TYPE_AUDIO;

    else if (!ff_guidcmp(&stream_type, &ff_asf_video_stream))

        type = AVMEDIA_TYPE_VIDEO;

    else if (!ff_guidcmp(&stream_type, &ff_asf_jfif_media))

        type = AVMEDIA_TYPE_VIDEO;

    else if (!ff_guidcmp(&stream_type, &ff_asf_command_stream))

        type = AVMEDIA_TYPE_DATA;

    else if (!ff_guidcmp(&stream_type,

                         &ff_asf_ext_stream_embed_stream_header))

        type = AVMEDIA_TYPE_UNKNOWN;

    else

        return AVERROR_INVALIDDATA;



    ff_get_guid(pb, &stream_type); // error correction type

    avio_skip(pb, 8); // skip the time offset

    ts_data_len      = avio_rl32(pb);

    err_data_len     = avio_rl32(pb);

    flags            = avio_rl16(pb); // bit 15 - Encrypted Content



    stream_index = flags & ASF_STREAM_NUM;

    for (i = 0; i < asf->nb_streams; i++)

        if (stream_index == asf->asf_st[i]->stream_index) {

            av_log(s, AV_LOG_WARNING,

                   "Duplicate stream found, this stream will be ignored.\n");

            align_position(pb, asf->offset, size);

            return 0;

        }



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    avpriv_set_pts_info(st, 32, 1, 1000); // pts should be dword, in milliseconds

    st->codec->codec_type = type;

    asf->asf_st[asf->nb_streams] = av_mallocz(sizeof(*asf_st));

    if (!asf->asf_st[asf->nb_streams])

        return AVERROR(ENOMEM);

    asf_st                       = asf->asf_st[asf->nb_streams];

    asf_st->stream_index         = stream_index;

    asf_st->index                = st->index;

    asf_st->indexed              = 0;

    st->id                       = flags & ASF_STREAM_NUM;

    av_init_packet(&asf_st->pkt.avpkt);

    asf_st->pkt.data_size        = 0;

    avio_skip(pb, 4); // skip reserved field



    switch (type) {

    case AVMEDIA_TYPE_AUDIO:

        asf_st->type = AVMEDIA_TYPE_AUDIO;

        if ((ret = ff_get_wav_header(s, pb, st->codec, ts_data_len)) < 0)

            return ret;

        break;

    case AVMEDIA_TYPE_VIDEO:

        asf_st->type = AVMEDIA_TYPE_VIDEO;

        if ((ret = parse_video_info(pb, st)) < 0)

            return ret;

        break;

    default:

        avio_skip(pb, ts_data_len);

        break;

    }



    if (err_data_len) {

        if (type == AVMEDIA_TYPE_AUDIO) {

            uint8_t span = avio_r8(pb);

            if (span > 1) {

                asf_st->span              = span;

                asf_st->virtual_pkt_len   = avio_rl16(pb);

                asf_st->virtual_chunk_len = avio_rl16(pb);

                if (!asf_st->virtual_chunk_len || !asf_st->virtual_pkt_len)

                    return AVERROR_INVALIDDATA;

                avio_skip(pb, err_data_len - 5);

            } else

                avio_skip(pb, err_data_len - 1);

        } else

            avio_skip(pb, err_data_len);

    }



    asf->nb_streams++;

    align_position(pb, asf->offset, size);



    return 0;

}

static int vhdx_log_flush(BlockDriverState *bs, BDRVVHDXState *s,

                          VHDXLogSequence *logs)

{

    int ret = 0;

    int i;

    uint32_t cnt, sectors_read;

    uint64_t new_file_size;

    void *data = NULL;

    VHDXLogDescEntries *desc_entries = NULL;

    VHDXLogEntryHeader hdr_tmp = { 0 };



    cnt = logs->count;



    data = qemu_blockalign(bs, VHDX_LOG_SECTOR_SIZE);



    ret = vhdx_user_visible_write(bs, s);

    if (ret < 0) {

        goto exit;

    }



    /* each iteration represents one log sequence, which may span multiple

     * sectors */

    while (cnt--) {

        ret = vhdx_log_peek_hdr(bs, &logs->log, &hdr_tmp);

        if (ret < 0) {

            goto exit;

        }

        /* if the log shows a FlushedFileOffset larger than our current file

         * size, then that means the file has been truncated / corrupted, and

         * we must refused to open it / use it */

        if (hdr_tmp.flushed_file_offset > bdrv_getlength(bs->file->bs)) {

            ret = -EINVAL;

            goto exit;

        }



        ret = vhdx_log_read_desc(bs, s, &logs->log, &desc_entries, true);

        if (ret < 0) {

            goto exit;

        }



        for (i = 0; i < desc_entries->hdr.descriptor_count; i++) {

            if (desc_entries->desc[i].signature == VHDX_LOG_DESC_SIGNATURE) {

                /* data sector, so read a sector to flush */

                ret = vhdx_log_read_sectors(bs, &logs->log, &sectors_read,

                                            data, 1, false);

                if (ret < 0) {

                    goto exit;

                }

                if (sectors_read != 1) {

                    ret = -EINVAL;

                    goto exit;

                }

                vhdx_log_data_le_import(data);

            }



            ret = vhdx_log_flush_desc(bs, &desc_entries->desc[i], data);

            if (ret < 0) {

                goto exit;

            }

        }

        if (bdrv_getlength(bs->file->bs) < desc_entries->hdr.last_file_offset) {

            new_file_size = desc_entries->hdr.last_file_offset;

            if (new_file_size % (1024*1024)) {

                /* round up to nearest 1MB boundary */

                new_file_size = ((new_file_size >> 20) + 1) << 20;

                bdrv_truncate(bs->file, new_file_size, PREALLOC_MODE_OFF, NULL);

            }

        }

        qemu_vfree(desc_entries);

        desc_entries = NULL;

    }



    bdrv_flush(bs);

    /* once the log is fully flushed, indicate that we have an empty log

     * now.  This also sets the log guid to 0, to indicate an empty log */

    vhdx_log_reset(bs, s);



exit:

    qemu_vfree(data);

    qemu_vfree(desc_entries);

    return ret;

}

static int vhdx_create_new_region_table(BlockDriverState *bs,

                                        uint64_t image_size,

                                        uint32_t block_size,

                                        uint32_t sector_size,

                                        uint32_t log_size,

                                        bool use_zero_blocks,

                                        VHDXImageType type,

                                        uint64_t *metadata_offset)

{

    int ret = 0;

    uint32_t offset = 0;

    void *buffer = NULL;

    uint64_t bat_file_offset;

    uint32_t bat_length;

    BDRVVHDXState *s = NULL;

    VHDXRegionTableHeader *region_table;

    VHDXRegionTableEntry *rt_bat;

    VHDXRegionTableEntry *rt_metadata;



    assert(metadata_offset != NULL);



    /* Populate enough of the BDRVVHDXState to be able to use the

     * pre-existing BAT calculation, translation, and update functions */

    s = g_malloc0(sizeof(BDRVVHDXState));



    s->chunk_ratio = (VHDX_MAX_SECTORS_PER_BLOCK) *

                     (uint64_t) sector_size / (uint64_t) block_size;



    s->sectors_per_block = block_size / sector_size;

    s->virtual_disk_size = image_size;

    s->block_size = block_size;

    s->logical_sector_size = sector_size;



    vhdx_set_shift_bits(s);



    vhdx_calc_bat_entries(s);



    /* At this point the VHDX state is populated enough for creation */



    /* a single buffer is used so we can calculate the checksum over the

     * entire 64KB block */

    buffer = g_malloc0(VHDX_HEADER_BLOCK_SIZE);

    region_table = buffer;

    offset += sizeof(VHDXRegionTableHeader);

    rt_bat = buffer + offset;

    offset += sizeof(VHDXRegionTableEntry);

    rt_metadata  = buffer + offset;



    region_table->signature = VHDX_REGION_SIGNATURE;

    region_table->entry_count = 2;   /* BAT and Metadata */



    rt_bat->guid        = bat_guid;

    rt_bat->length      = ROUND_UP(s->bat_entries * sizeof(VHDXBatEntry), MiB);

    rt_bat->file_offset = ROUND_UP(VHDX_HEADER_SECTION_END + log_size, MiB);

    s->bat_offset = rt_bat->file_offset;



    rt_metadata->guid        = metadata_guid;

    rt_metadata->file_offset = ROUND_UP(rt_bat->file_offset + rt_bat->length,

                                        MiB);

    rt_metadata->length      = 1 * MiB; /* min size, and more than enough */

    *metadata_offset = rt_metadata->file_offset;



    bat_file_offset = rt_bat->file_offset;

    bat_length = rt_bat->length;



    vhdx_region_header_le_export(region_table);

    vhdx_region_entry_le_export(rt_bat);

    vhdx_region_entry_le_export(rt_metadata);



    vhdx_update_checksum(buffer, VHDX_HEADER_BLOCK_SIZE,

                         offsetof(VHDXRegionTableHeader, checksum));





    /* The region table gives us the data we need to create the BAT,

     * so do that now */

    ret = vhdx_create_bat(bs, s, image_size, type, use_zero_blocks,

                          bat_file_offset, bat_length);

    if (ret < 0) {

        goto exit;

    }



    /* Now write out the region headers to disk */

    ret = bdrv_pwrite(bs, VHDX_REGION_TABLE_OFFSET, buffer,

                      VHDX_HEADER_BLOCK_SIZE);

    if (ret < 0) {

        goto exit;

    }



    ret = bdrv_pwrite(bs, VHDX_REGION_TABLE2_OFFSET, buffer,

                      VHDX_HEADER_BLOCK_SIZE);

    if (ret < 0) {

        goto exit;

    }





exit:

    g_free(s);

    g_free(buffer);

    return ret;

}

static int vhdx_log_write(BlockDriverState *bs, BDRVVHDXState *s,

                          void *data, uint32_t length, uint64_t offset)

{

    int ret = 0;

    void *buffer = NULL;

    void *merged_sector = NULL;

    void *data_tmp, *sector_write;

    unsigned int i;

    int sector_offset;

    uint32_t desc_sectors, sectors, total_length;

    uint32_t sectors_written = 0;

    uint32_t aligned_length;

    uint32_t leading_length = 0;

    uint32_t trailing_length = 0;

    uint32_t partial_sectors = 0;

    uint32_t bytes_written = 0;

    uint64_t file_offset;

    VHDXHeader *header;

    VHDXLogEntryHeader new_hdr;

    VHDXLogDescriptor *new_desc = NULL;

    VHDXLogDataSector *data_sector = NULL;

    MSGUID new_guid = { 0 };



    header = s->headers[s->curr_header];



    /* need to have offset read data, and be on 4096 byte boundary */



    if (length > header->log_length) {

        /* no log present.  we could create a log here instead of failing */

        ret = -EINVAL;

        goto exit;

    }



    if (guid_eq(header->log_guid, zero_guid)) {

        vhdx_guid_generate(&new_guid);

        vhdx_update_headers(bs, s, false, &new_guid);

    } else {

        /* currently, we require that the log be flushed after

         * every write. */

        ret = -ENOTSUP;

        goto exit;

    }



    /* 0 is an invalid sequence number, but may also represent the first

     * log write (or a wrapped seq) */

    if (s->log.sequence == 0) {

        s->log.sequence = 1;

    }



    sector_offset = offset % VHDX_LOG_SECTOR_SIZE;

    file_offset = (offset / VHDX_LOG_SECTOR_SIZE) * VHDX_LOG_SECTOR_SIZE;



    aligned_length = length;



    /* add in the unaligned head and tail bytes */

    if (sector_offset) {

        leading_length = (VHDX_LOG_SECTOR_SIZE - sector_offset);

        leading_length = leading_length > length ? length : leading_length;

        aligned_length -= leading_length;

        partial_sectors++;

    }



    sectors = aligned_length / VHDX_LOG_SECTOR_SIZE;

    trailing_length = aligned_length - (sectors * VHDX_LOG_SECTOR_SIZE);

    if (trailing_length) {

        partial_sectors++;

    }



    sectors += partial_sectors;



    /* sectors is now how many sectors the data itself takes, not

     * including the header and descriptor metadata */



    new_hdr = (VHDXLogEntryHeader) {

                .signature           = VHDX_LOG_SIGNATURE,

                .tail                = s->log.tail,

                .sequence_number     = s->log.sequence,

                .descriptor_count    = sectors,

                .reserved            = 0,

                .flushed_file_offset = bdrv_getlength(bs->file),

                .last_file_offset    = bdrv_getlength(bs->file),

              };



    new_hdr.log_guid = header->log_guid;



    desc_sectors = vhdx_compute_desc_sectors(new_hdr.descriptor_count);



    total_length = (desc_sectors + sectors) * VHDX_LOG_SECTOR_SIZE;

    new_hdr.entry_length = total_length;



    vhdx_log_entry_hdr_le_export(&new_hdr);



    buffer = qemu_blockalign(bs, total_length);

    memcpy(buffer, &new_hdr, sizeof(new_hdr));



    new_desc = (VHDXLogDescriptor *) (buffer + sizeof(new_hdr));

    data_sector = buffer + (desc_sectors * VHDX_LOG_SECTOR_SIZE);

    data_tmp = data;



    /* All log sectors are 4KB, so for any partial sectors we must

     * merge the data with preexisting data from the final file

     * destination */

    merged_sector = qemu_blockalign(bs, VHDX_LOG_SECTOR_SIZE);



    for (i = 0; i < sectors; i++) {

        new_desc->signature       = VHDX_LOG_DESC_SIGNATURE;

        new_desc->sequence_number = s->log.sequence;

        new_desc->file_offset     = file_offset;



        if (i == 0 && leading_length) {

            /* partial sector at the front of the buffer */

            ret = bdrv_pread(bs->file, file_offset, merged_sector,

                             VHDX_LOG_SECTOR_SIZE);

            if (ret < 0) {

                goto exit;

            }

            memcpy(merged_sector + sector_offset, data_tmp, leading_length);

            bytes_written = leading_length;

            sector_write = merged_sector;

        } else if (i == sectors - 1 && trailing_length) {

            /* partial sector at the end of the buffer */

            ret = bdrv_pread(bs->file,

                            file_offset,

                            merged_sector + trailing_length,

                            VHDX_LOG_SECTOR_SIZE - trailing_length);

            if (ret < 0) {

                goto exit;

            }

            memcpy(merged_sector, data_tmp, trailing_length);

            bytes_written = trailing_length;

            sector_write = merged_sector;

        } else {

            bytes_written = VHDX_LOG_SECTOR_SIZE;

            sector_write = data_tmp;

        }



        /* populate the raw sector data into the proper structures,

         * as well as update the descriptor, and convert to proper

         * endianness */

        vhdx_log_raw_to_le_sector(new_desc, data_sector, sector_write,

                                  s->log.sequence);



        data_tmp += bytes_written;

        data_sector++;

        new_desc++;

        file_offset += VHDX_LOG_SECTOR_SIZE;

    }



    /* checksum covers entire entry, from the log header through the

     * last data sector */

    vhdx_update_checksum(buffer, total_length,

                         offsetof(VHDXLogEntryHeader, checksum));

    cpu_to_le32s((uint32_t *)(buffer + 4));



    /* now write to the log */

    vhdx_log_write_sectors(bs, &s->log, &sectors_written, buffer,

                           desc_sectors + sectors);

    if (ret < 0) {

        goto exit;

    }



    if (sectors_written != desc_sectors + sectors) {

        /* instead of failing, we could flush the log here */

        ret = -EINVAL;

        goto exit;

    }



    s->log.sequence++;

    /* write new tail */

    s->log.tail = s->log.write;



exit:

    qemu_vfree(buffer);

    qemu_vfree(merged_sector);

    return ret;

}

static int vhdx_create_new_region_table(BlockDriverState *bs,

                                        uint64_t image_size,

                                        uint32_t block_size,

                                        uint32_t sector_size,

                                        uint32_t log_size,

                                        bool use_zero_blocks,

                                        VHDXImageType type,

                                        uint64_t *metadata_offset)

{

    int ret = 0;

    uint32_t offset = 0;

    void *buffer = NULL;

    uint64_t bat_file_offset;

    uint32_t bat_length;

    BDRVVHDXState *s = NULL;

    VHDXRegionTableHeader *region_table;

    VHDXRegionTableEntry *rt_bat;

    VHDXRegionTableEntry *rt_metadata;



    assert(metadata_offset != NULL);



    /* Populate enough of the BDRVVHDXState to be able to use the

     * pre-existing BAT calculation, translation, and update functions */

    s = g_new0(BDRVVHDXState, 1);



    s->chunk_ratio = (VHDX_MAX_SECTORS_PER_BLOCK) *

                     (uint64_t) sector_size / (uint64_t) block_size;



    s->sectors_per_block = block_size / sector_size;

    s->virtual_disk_size = image_size;

    s->block_size = block_size;

    s->logical_sector_size = sector_size;



    vhdx_set_shift_bits(s);



    vhdx_calc_bat_entries(s);



    /* At this point the VHDX state is populated enough for creation */



    /* a single buffer is used so we can calculate the checksum over the

     * entire 64KB block */

    buffer = g_malloc0(VHDX_HEADER_BLOCK_SIZE);

    region_table = buffer;

    offset += sizeof(VHDXRegionTableHeader);

    rt_bat = buffer + offset;

    offset += sizeof(VHDXRegionTableEntry);

    rt_metadata  = buffer + offset;



    region_table->signature = VHDX_REGION_SIGNATURE;

    region_table->entry_count = 2;   /* BAT and Metadata */



    rt_bat->guid        = bat_guid;

    rt_bat->length      = ROUND_UP(s->bat_entries * sizeof(VHDXBatEntry), MiB);

    rt_bat->file_offset = ROUND_UP(VHDX_HEADER_SECTION_END + log_size, MiB);

    s->bat_offset = rt_bat->file_offset;



    rt_metadata->guid        = metadata_guid;

    rt_metadata->file_offset = ROUND_UP(rt_bat->file_offset + rt_bat->length,

                                        MiB);

    rt_metadata->length      = 1 * MiB; /* min size, and more than enough */

    *metadata_offset = rt_metadata->file_offset;



    bat_file_offset = rt_bat->file_offset;

    bat_length = rt_bat->length;



    vhdx_region_header_le_export(region_table);

    vhdx_region_entry_le_export(rt_bat);

    vhdx_region_entry_le_export(rt_metadata);



    vhdx_update_checksum(buffer, VHDX_HEADER_BLOCK_SIZE,

                         offsetof(VHDXRegionTableHeader, checksum));





    /* The region table gives us the data we need to create the BAT,

     * so do that now */

    ret = vhdx_create_bat(bs, s, image_size, type, use_zero_blocks,

                          bat_file_offset, bat_length);

    if (ret < 0) {

        goto exit;

    }



    /* Now write out the region headers to disk */

    ret = bdrv_pwrite(bs, VHDX_REGION_TABLE_OFFSET, buffer,

                      VHDX_HEADER_BLOCK_SIZE);

    if (ret < 0) {

        goto exit;

    }



    ret = bdrv_pwrite(bs, VHDX_REGION_TABLE2_OFFSET, buffer,

                      VHDX_HEADER_BLOCK_SIZE);

    if (ret < 0) {

        goto exit;

    }



exit:

    g_free(s);

    g_free(buffer);

    return ret;

}

