                               unsigned int max_num_sg, bool is_write,
                               hwaddr pa, size_t sz)
{
    unsigned num_sg = *p_num_sg;
    assert(num_sg <= max_num_sg);
    if (!sz) {
        error_report("virtio: zero sized buffers are not allowed");
    while (sz) {
        hwaddr len = sz;
        if (num_sg == max_num_sg) {
            error_report("virtio: too many write descriptors in indirect table");
        iov[num_sg].iov_base = cpu_physical_memory_map(pa, &len, is_write);
        iov[num_sg].iov_len = len;
        addr[num_sg] = pa;
        sz -= len;
        pa += len;
        num_sg++;
    *p_num_sg = num_sg;

size_t iov_to_buf(const struct iovec *iov, const unsigned int iov_cnt, size_t iov_off,

                  void *buf, size_t size)

{

    uint8_t *ptr;

    size_t iovec_off, buf_off;

    unsigned int i;



    ptr = buf;

    iovec_off = 0;

    buf_off = 0;

    for (i = 0; i < iov_cnt && size; i++) {

        if (iov_off < (iovec_off + iov[i].iov_len)) {

            size_t len = MIN((iovec_off + iov[i].iov_len) - iov_off , size);



            memcpy(ptr + buf_off, iov[i].iov_base + (iov_off - iovec_off), len);



            buf_off += len;

            iov_off += len;

            size -= len;

        }

        iovec_off += iov[i].iov_len;

    }

    return buf_off;

}

static size_t v9fs_packunpack(void *addr, struct iovec *sg, int sg_count,

                              size_t offset, size_t size, int pack)

{

    int i = 0;

    size_t copied = 0;



    for (i = 0; size && i < sg_count; i++) {

        size_t len;

        if (offset >= sg[i].iov_len) {

            /* skip this sg */

            offset -= sg[i].iov_len;

            continue;

        } else {

            len = MIN(sg[i].iov_len - offset, size);

            if (pack) {

                memcpy(sg[i].iov_base + offset, addr, len);

            } else {

                memcpy(addr, sg[i].iov_base + offset, len);

            }

            size -= len;

            copied += len;

            addr += len;

            if (size) {

                offset = 0;

                continue;

            }

        }

    }



    return copied;

}

static uint64_t lsi_ram_read(void *opaque, target_phys_addr_t addr,

                             unsigned size)

{

    LSIState *s = opaque;

    uint32_t val;

    uint32_t mask;



    val = s->script_ram[addr >> 2];

    mask = ((uint64_t)1 << (size * 8)) - 1;

    val >>= (addr & 3) * 8;

    return val & mask;

}

static void lsi_mmio_write(void *opaque, target_phys_addr_t addr,

                           uint64_t val, unsigned size)

