static int dxtory_decode_v1_rgb(AVCodecContext *avctx, AVFrame *pic,

                                const uint8_t *src, int src_size,

                                int id, int bpp)

{

    int h;

    uint8_t *dst;

    int ret;



    if (src_size < avctx->width * avctx->height * bpp) {

        av_log(avctx, AV_LOG_ERROR, "packet too small\n");

        return AVERROR_INVALIDDATA;

    }



    avctx->pix_fmt = id;

    if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)

        return ret;



    dst = pic->data[0];

    for (h = 0; h < avctx->height; h++) {

        memcpy(dst, src, avctx->width * bpp);

        src += avctx->width * bpp;

        dst += pic->linesize[0];

    }



    return 0;

}

static int set_palette(AVFrame * frame, const uint8_t * palette_buffer, int buf_size)

{

    uint32_t * palette = (uint32_t *)frame->data[1];

    int a;



    if (buf_size < 256*3)

        return AVERROR_INVALIDDATA;



    for(a = 0; a < 256; a++){

        palette[a] = AV_RB24(&palette_buffer[a * 3]) * 4;

    }

    frame->palette_has_changed = 1;

    return 256*3;

}

static int dxtory_decode_v1_420(AVCodecContext *avctx, AVFrame *pic,

                                const uint8_t *src, int src_size)

{

    int h, w;

    uint8_t *Y1, *Y2, *U, *V;

    int ret;



    if (src_size < avctx->width * avctx->height * 3LL / 2) {

        av_log(avctx, AV_LOG_ERROR, "packet too small\n");

        return AVERROR_INVALIDDATA;

    }



    avctx->pix_fmt = AV_PIX_FMT_YUV420P;

    if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)

        return ret;



    Y1 = pic->data[0];

    Y2 = pic->data[0] + pic->linesize[0];

    U  = pic->data[1];

    V  = pic->data[2];

    for (h = 0; h < avctx->height; h += 2) {

        for (w = 0; w < avctx->width; w += 2) {

            AV_COPY16(Y1 + w, src);

            AV_COPY16(Y2 + w, src + 2);

            U[w >> 1] = src[4] + 0x80;

            V[w >> 1] = src[5] + 0x80;

            src += 6;

        }

        Y1 += pic->linesize[0] << 1;

        Y2 += pic->linesize[0] << 1;

        U  += pic->linesize[1];

        V  += pic->linesize[2];

    }



    return 0;

}

static void cmv_decode_intra(CmvContext * s, const uint8_t *buf, const uint8_t *buf_end){

    unsigned char *dst = s->frame.data[0];

    int i;



    for (i=0; i < s->avctx->height && buf+s->avctx->width<=buf_end; i++) {

        memcpy(dst, buf, s->avctx->width);

        dst += s->frame.linesize[0];

        buf += s->avctx->width;

    }

}

static void avc_luma_vt_8w_msa(const uint8_t *src, int32_t src_stride,

                               uint8_t *dst, int32_t dst_stride,

                               int32_t height)

{

    int32_t loop_cnt;

    int16_t filt_const0 = 0xfb01;

    int16_t filt_const1 = 0x1414;

    int16_t filt_const2 = 0x1fb;

    v16i8 src0, src1, src2, src3, src4, src7, src8, src9, src10;

    v16i8 src10_r, src32_r, src76_r, src98_r;

    v16i8 src21_r, src43_r, src87_r, src109_r;

    v8i16 out0_r, out1_r, out2_r, out3_r;

    v16i8 filt0, filt1, filt2;

    v16u8 out0, out1;



    filt0 = (v16i8) __msa_fill_h(filt_const0);

    filt1 = (v16i8) __msa_fill_h(filt_const1);

    filt2 = (v16i8) __msa_fill_h(filt_const2);



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    src += (5 * src_stride);



    XORI_B5_128_SB(src0, src1, src2, src3, src4);

    ILVR_B4_SB(src1, src0, src2, src1, src3, src2, src4, src3,

               src10_r, src21_r, src32_r, src43_r);



    for (loop_cnt = (height >> 2); loop_cnt--;) {

        LD_SB4(src, src_stride, src7, src8, src9, src10);

        src += (4 * src_stride);



        XORI_B4_128_SB(src7, src8, src9, src10);

        ILVR_B4_SB(src7, src4, src8, src7, src9, src8, src10, src9,

                   src76_r, src87_r, src98_r, src109_r);

        out0_r = DPADD_SH3_SH(src10_r, src32_r, src76_r, filt0, filt1, filt2);

        out1_r = DPADD_SH3_SH(src21_r, src43_r, src87_r, filt0, filt1, filt2);

        out2_r = DPADD_SH3_SH(src32_r, src76_r, src98_r, filt0, filt1, filt2);

        out3_r = DPADD_SH3_SH(src43_r, src87_r, src109_r, filt0, filt1, filt2);

        SRARI_H4_SH(out0_r, out1_r, out2_r, out3_r, 5);

        SAT_SH4_SH(out0_r, out1_r, out2_r, out3_r, 7);

        out0 = PCKEV_XORI128_UB(out0_r, out1_r);

        out1 = PCKEV_XORI128_UB(out2_r, out3_r);

        ST8x4_UB(out0, out1, dst, dst_stride);

        dst += (4 * dst_stride);



        src10_r = src76_r;

        src32_r = src98_r;

        src21_r = src87_r;

        src43_r = src109_r;

        src4 = src10;

    }

}

static void avc_luma_vt_and_aver_dst_8x8_msa(const uint8_t *src,

                                             int32_t src_stride,

                                             uint8_t *dst, int32_t dst_stride)

{

    int32_t loop_cnt;

