static void ff_h264_idct_add_mmx(uint8_t *dst, int16_t *block, int stride)

{

    /* Load dct coeffs */

    __asm__ volatile(

        "movq   (%0), %%mm0 \n\t"

        "movq  8(%0), %%mm1 \n\t"

        "movq 16(%0), %%mm2 \n\t"

        "movq 24(%0), %%mm3 \n\t"

    :: "r"(block) );



    __asm__ volatile(

        /* mm1=s02+s13  mm2=s02-s13  mm4=d02+d13  mm0=d02-d13 */

        IDCT4_1D( %%mm2, %%mm1, %%mm0, %%mm3, %%mm4 )



        "movq      %0,    %%mm6 \n\t"

        /* in: 1,4,0,2  out: 1,2,3,0 */

        TRANSPOSE4( %%mm3, %%mm1, %%mm0, %%mm2, %%mm4 )



        "paddw     %%mm6, %%mm3 \n\t"



        /* mm2=s02+s13  mm3=s02-s13  mm4=d02+d13  mm1=d02-d13 */

        IDCT4_1D( %%mm4, %%mm2, %%mm3, %%mm0, %%mm1 )



        "pxor %%mm7, %%mm7    \n\t"

    :: "m"(ff_pw_32));



    __asm__ volatile(

    STORE_DIFF_4P( %%mm0, %%mm1, %%mm7)

        "add %1, %0             \n\t"

    STORE_DIFF_4P( %%mm2, %%mm1, %%mm7)

        "add %1, %0             \n\t"

    STORE_DIFF_4P( %%mm3, %%mm1, %%mm7)

        "add %1, %0             \n\t"

    STORE_DIFF_4P( %%mm4, %%mm1, %%mm7)

        : "+r"(dst)

        : "r" ((x86_reg)stride)

    );

}

static void generate_silence(uint8_t* buf, enum AVSampleFormat sample_fmt, size_t size)

{

    int fill_char = 0x00;

    if (sample_fmt == AV_SAMPLE_FMT_U8)

        fill_char = 0x80;

    memset(buf, fill_char, size);

}

static void generate_bootsect(target_phys_addr_t option_rom,

                              uint32_t gpr[8], uint16_t segs[6], uint16_t ip)

{

    uint8_t rom[512], *p, *reloc;

    uint8_t sum;

    int i;



    memset(rom, 0, sizeof(rom));



    p = rom;

    /* Make sure we have an option rom signature */

    *p++ = 0x55;

    *p++ = 0xaa;



    /* ROM size in sectors*/

    *p++ = 1;



    /* Hook int19 */



    *p++ = 0x50;		/* push ax */

    *p++ = 0x1e;		/* push ds */

    *p++ = 0x31; *p++ = 0xc0;	/* xor ax, ax */

    *p++ = 0x8e; *p++ = 0xd8;	/* mov ax, ds */



    *p++ = 0xc7; *p++ = 0x06;   /* movvw _start,0x64 */

    *p++ = 0x64; *p++ = 0x00;

    reloc = p;

    *p++ = 0x00; *p++ = 0x00;



    *p++ = 0x8c; *p++ = 0x0e;   /* mov cs,0x66 */

    *p++ = 0x66; *p++ = 0x00;



    *p++ = 0x1f;		/* pop ds */

    *p++ = 0x58;		/* pop ax */

    *p++ = 0xcb;		/* lret */



    /* Actual code */

    *reloc = (p - rom);



    *p++ = 0xfa;		/* CLI */

    *p++ = 0xfc;		/* CLD */



    for (i = 0; i < 6; i++) {

	if (i == 1)		/* Skip CS */

	    continue;



	*p++ = 0xb8;		/* MOV AX,imm16 */

	*p++ = segs[i];

	*p++ = segs[i] >> 8;

	*p++ = 0x8e;		/* MOV <seg>,AX */

	*p++ = 0xc0 + (i << 3);

    }



    for (i = 0; i < 8; i++) {

	*p++ = 0x66;		/* 32-bit operand size */

	*p++ = 0xb8 + i;	/* MOV <reg>,imm32 */

	*p++ = gpr[i];

	*p++ = gpr[i] >> 8;

	*p++ = gpr[i] >> 16;

	*p++ = gpr[i] >> 24;

    }



    *p++ = 0xea;		/* JMP FAR */

    *p++ = ip;			/* IP */

    *p++ = ip >> 8;

    *p++ = segs[1];		/* CS */

    *p++ = segs[1] >> 8;



    /* sign rom */

    sum = 0;

    for (i = 0; i < (sizeof(rom) - 1); i++)

        sum += rom[i];

    rom[sizeof(rom) - 1] = -sum;



    cpu_physical_memory_write_rom(option_rom, rom, sizeof(rom));

    option_rom_setup_reset(option_rom, sizeof (rom));

}

static int encode_apng(AVCodecContext *avctx, AVPacket *pkt,

                       const AVFrame *pict, int *got_packet)

{

    PNGEncContext *s = avctx->priv_data;

    int ret;

    int enc_row_size;

    size_t max_packet_size;

    APNGFctlChunk fctl_chunk;



    if (pict && avctx->codec_id == AV_CODEC_ID_APNG && s->color_type == PNG_COLOR_TYPE_PALETTE) {

        uint32_t checksum = ~av_crc(av_crc_get_table(AV_CRC_32_IEEE_LE), ~0U, pict->data[1], 256 * sizeof(uint32_t));



        if (avctx->frame_number == 0) {

            s->palette_checksum = checksum;

        } else if (checksum != s->palette_checksum) {

            av_log(avctx, AV_LOG_ERROR,

                   "Input contains more than one unique palette. APNG does not support multiple palettes.\n");

            return -1;

        }

    }



    enc_row_size    = deflateBound(&s->zstream, (avctx->width * s->bits_per_pixel + 7) >> 3);

    max_packet_size =

        AV_INPUT_BUFFER_MIN_SIZE + // headers

        avctx->height * (

            enc_row_size +

            (4 + 12) * (((int64_t)enc_row_size + IOBUF_SIZE - 1) / IOBUF_SIZE) // fdAT * ceil(enc_row_size / IOBUF_SIZE)

        );

    if (max_packet_size > INT_MAX)

        return AVERROR(ENOMEM);



    if (avctx->frame_number == 0) {

        s->bytestream = avctx->extradata = av_malloc(FF_MIN_BUFFER_SIZE);

        if (!avctx->extradata)

            return AVERROR(ENOMEM);



        ret = encode_headers(avctx, pict);

        if (ret < 0)

            return ret;



        avctx->extradata_size = s->bytestream - avctx->extradata;



        s->last_frame_packet = av_malloc(max_packet_size);

        if (!s->last_frame_packet)

            return AVERROR(ENOMEM);

    } else if (s->last_frame) {

        ret = ff_alloc_packet2(avctx, pkt, max_packet_size, 0);

        if (ret < 0)

            return ret;



        memcpy(pkt->data, s->last_frame_packet, s->last_frame_packet_size);

        pkt->size = s->last_frame_packet_size;

        pkt->pts = pkt->dts = s->last_frame->pts;

    }



    if (pict) {

        s->bytestream_start =

        s->bytestream       = s->last_frame_packet;

        s->bytestream_end   = s->bytestream + max_packet_size;



        // We're encoding the frame first, so we have to do a bit of shuffling around

        // to have the image data write to the correct place in the buffer

        fctl_chunk.sequence_number = s->sequence_number;

        ++s->sequence_number;

        s->bytestream += 26 + 12;



        ret = apng_encode_frame(avctx, pict, &fctl_chunk, &s->last_frame_fctl);

        if (ret < 0)

            return ret;



        fctl_chunk.delay_num = 0; // delay filled in during muxing

        fctl_chunk.delay_den = 0;

    } else {

        s->last_frame_fctl.dispose_op = APNG_DISPOSE_OP_NONE;

    }



    if (s->last_frame) {

        uint8_t* last_fctl_chunk_start = pkt->data;

        uint8_t buf[26];



        AV_WB32(buf + 0, s->last_frame_fctl.sequence_number);

        AV_WB32(buf + 4, s->last_frame_fctl.width);

        AV_WB32(buf + 8, s->last_frame_fctl.height);

        AV_WB32(buf + 12, s->last_frame_fctl.x_offset);

        AV_WB32(buf + 16, s->last_frame_fctl.y_offset);

        AV_WB16(buf + 20, s->last_frame_fctl.delay_num);

        AV_WB16(buf + 22, s->last_frame_fctl.delay_den);

        buf[24] = s->last_frame_fctl.dispose_op;

        buf[25] = s->last_frame_fctl.blend_op;

        png_write_chunk(&last_fctl_chunk_start, MKTAG('f', 'c', 'T', 'L'), buf, 26);



        *got_packet = 1;

    }



    if (pict) {

        if (!s->last_frame) {

            s->last_frame = av_frame_alloc();

            if (!s->last_frame)

                return AVERROR(ENOMEM);

        } else if (s->last_frame_fctl.dispose_op != APNG_DISPOSE_OP_PREVIOUS) {

            if (!s->prev_frame) {

                s->prev_frame = av_frame_alloc();

                if (!s->prev_frame)

                    return AVERROR(ENOMEM);



                s->prev_frame->format = pict->format;

                s->prev_frame->width = pict->width;

                s->prev_frame->height = pict->height;

                if ((ret = av_frame_get_buffer(s->prev_frame, 32)) < 0)

                    return ret;

            }



            // Do disposal, but not blending

            memcpy(s->prev_frame->data[0], s->last_frame->data[0],

                   s->last_frame->linesize[0] * s->last_frame->height);

            if (s->last_frame_fctl.dispose_op == APNG_DISPOSE_OP_BACKGROUND) {

                uint32_t y;

                uint8_t bpp = (s->bits_per_pixel + 7) >> 3;

                for (y = s->last_frame_fctl.y_offset; y < s->last_frame_fctl.y_offset + s->last_frame_fctl.height; ++y) {

                    size_t row_start = s->last_frame->linesize[0] * y + bpp * s->last_frame_fctl.x_offset;

                    memset(s->prev_frame->data[0] + row_start, 0, bpp * s->last_frame_fctl.width);

                }

            }

        }



        av_frame_unref(s->last_frame);

        ret = av_frame_ref(s->last_frame, (AVFrame*)pict);

        if (ret < 0)

            return ret;



        s->last_frame_fctl = fctl_chunk;

        s->last_frame_packet_size = s->bytestream - s->bytestream_start;

    } else {

        av_frame_free(&s->last_frame);

    }



    return 0;

}

static int xface_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                              const AVFrame *frame, int *got_packet)

{

    XFaceContext *xface = avctx->priv_data;

    ProbRangesQueue pq = {{ 0 }, 0};

    uint8_t bitmap_copy[XFACE_PIXELS];

    BigInt b = {0};

    int i, j, k, ret = 0;

    const uint8_t *buf;

    uint8_t *p;

    char intbuf[XFACE_MAX_DIGITS];



    if (avctx->width || avctx->height) {

        if (avctx->width != XFACE_WIDTH || avctx->height != XFACE_HEIGHT) {

            av_log(avctx, AV_LOG_ERROR,

                   "Size value %dx%d not supported, only accepts a size of %dx%d\n",

                   avctx->width, avctx->height, XFACE_WIDTH, XFACE_HEIGHT);

            return AVERROR(EINVAL);

        }

    }

    avctx->width  = XFACE_WIDTH;

    avctx->height = XFACE_HEIGHT;



    /* convert image from MONOWHITE to 1=black 0=white bitmap */

    buf = frame->data[0];

    i = j = 0;

    do {

        for (k = 0; k < 8; k++)

            xface->bitmap[i++] = (buf[j]>>(7-k))&1;

        if (++j == XFACE_WIDTH/8) {

            buf += frame->linesize[0];

            j = 0;

        }

    } while (i < XFACE_PIXELS);



    /* create a copy of bitmap */

    memcpy(bitmap_copy, xface->bitmap, XFACE_PIXELS);

    ff_xface_generate_face(xface->bitmap, bitmap_copy);



    encode_block(xface->bitmap,                         16, 16, 0, &pq);

    encode_block(xface->bitmap + 16,                    16, 16, 0, &pq);

    encode_block(xface->bitmap + 32,                    16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 16,      16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 16 + 16, 16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 16 + 32, 16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 32,      16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 32 + 16, 16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 32 + 32, 16, 16, 0, &pq);



    while (pq.prob_ranges_idx > 0)

        push_integer(&b, pq.prob_ranges[--pq.prob_ranges_idx]);



    /* write the inverted big integer in b to intbuf */

    i = 0;


    while (b.nb_words) {

        uint8_t r;

        ff_big_div(&b, XFACE_PRINTS, &r);


        intbuf[i++] = r + XFACE_FIRST_PRINT;

    }



    if ((ret = ff_alloc_packet2(avctx, pkt, i+2)) < 0)

        return ret;



    /* revert the number, and close the buffer */

    p = pkt->data;

    while (--i >= 0)

        *(p++) = intbuf[i];

    *(p++) = '\n';

    *(p++) = 0;



    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

static int apng_encode_frame(AVCodecContext *avctx, const AVFrame *pict,

                             APNGFctlChunk *best_fctl_chunk, APNGFctlChunk *best_last_fctl_chunk)

{

    PNGEncContext *s = avctx->priv_data;

    int ret;

    unsigned int y;

    AVFrame* diffFrame;

    uint8_t bpp = (s->bits_per_pixel + 7) >> 3;

    uint8_t *original_bytestream, *original_bytestream_end;

    uint8_t *temp_bytestream = 0, *temp_bytestream_end;

    uint32_t best_sequence_number;

    uint8_t *best_bytestream;

    size_t best_bytestream_size = SIZE_MAX;

    APNGFctlChunk last_fctl_chunk = *best_last_fctl_chunk;

    APNGFctlChunk fctl_chunk = *best_fctl_chunk;



    if (avctx->frame_number == 0) {

        best_fctl_chunk->width = pict->width;

        best_fctl_chunk->height = pict->height;

        best_fctl_chunk->x_offset = 0;

        best_fctl_chunk->y_offset = 0;

        best_fctl_chunk->blend_op = APNG_BLEND_OP_SOURCE;

        return encode_frame(avctx, pict);

    }



    diffFrame = av_frame_alloc();

    if (!diffFrame)

        return AVERROR(ENOMEM);



    diffFrame->format = pict->format;

    diffFrame->width = pict->width;

    diffFrame->height = pict->height;

    if ((ret = av_frame_get_buffer(diffFrame, 32)) < 0)

        goto fail;



    original_bytestream = s->bytestream;

    original_bytestream_end = s->bytestream_end;



    temp_bytestream = av_malloc(original_bytestream_end - original_bytestream);

    temp_bytestream_end = temp_bytestream + (original_bytestream_end - original_bytestream);

    if (!temp_bytestream) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    for (last_fctl_chunk.dispose_op = 0; last_fctl_chunk.dispose_op < 3; ++last_fctl_chunk.dispose_op) {

        // 0: APNG_DISPOSE_OP_NONE

        // 1: APNG_DISPOSE_OP_BACKGROUND

        // 2: APNG_DISPOSE_OP_PREVIOUS



        for (fctl_chunk.blend_op = 0; fctl_chunk.blend_op < 2; ++fctl_chunk.blend_op) {

            // 0: APNG_BLEND_OP_SOURCE

            // 1: APNG_BLEND_OP_OVER



            uint32_t original_sequence_number = s->sequence_number, sequence_number;

            uint8_t *bytestream_start = s->bytestream;

            size_t bytestream_size;



            // Do disposal

            if (last_fctl_chunk.dispose_op != APNG_DISPOSE_OP_PREVIOUS) {

                diffFrame->width = pict->width;

                diffFrame->height = pict->height;

                av_frame_copy(diffFrame, s->last_frame);



                if (last_fctl_chunk.dispose_op == APNG_DISPOSE_OP_BACKGROUND) {

                    for (y = last_fctl_chunk.y_offset; y < last_fctl_chunk.y_offset + last_fctl_chunk.height; ++y) {

                        size_t row_start = diffFrame->linesize[0] * y + bpp * last_fctl_chunk.x_offset;

                        memset(diffFrame->data[0] + row_start, 0, bpp * last_fctl_chunk.width);

                    }

                }

            } else {

                if (!s->prev_frame)

                    continue;



                diffFrame->width = pict->width;

                diffFrame->height = pict->height;

                av_frame_copy(diffFrame, s->prev_frame);

            }



            // Do inverse blending

            if (apng_do_inverse_blend(diffFrame, pict, &fctl_chunk, bpp) < 0)

                continue;



            // Do encoding

            ret = encode_frame(avctx, diffFrame);

            sequence_number = s->sequence_number;

            s->sequence_number = original_sequence_number;

            bytestream_size = s->bytestream - bytestream_start;

            s->bytestream = bytestream_start;

            if (ret < 0)

                goto fail;



            if (bytestream_size < best_bytestream_size) {

                *best_fctl_chunk = fctl_chunk;

                *best_last_fctl_chunk = last_fctl_chunk;



                best_sequence_number = sequence_number;

                best_bytestream = s->bytestream;

                best_bytestream_size = bytestream_size;



                if (best_bytestream == original_bytestream) {

                    s->bytestream = temp_bytestream;

                    s->bytestream_end = temp_bytestream_end;

                } else {

                    s->bytestream = original_bytestream;

                    s->bytestream_end = original_bytestream_end;

                }

            }

        }

    }



    s->sequence_number = best_sequence_number;

    s->bytestream = original_bytestream + best_bytestream_size;

    s->bytestream_end = original_bytestream_end;

    if (best_bytestream != original_bytestream)

        memcpy(original_bytestream, best_bytestream, best_bytestream_size);



    ret = 0;



fail:

    av_freep(&temp_bytestream);

    av_frame_free(&diffFrame);

    return ret;

}

static int decode_frame(AVCodecContext *avctx,

                        void *data, int *got_frame,

                        AVPacket *avpkt)

{

    PNGDecContext *const s = avctx->priv_data;

    const uint8_t *buf     = avpkt->data;

    int buf_size           = avpkt->size;

    AVFrame *p             = data;

    uint8_t *crow_buf_base = NULL;

    uint32_t tag, length;

    int ret;



    /* check signature */

    if (buf_size < 8 ||

        memcmp(buf, ff_pngsig, 8) != 0 &&

        memcmp(buf, ff_mngsig, 8) != 0)

        return -1;



    bytestream2_init(&s->gb, buf + 8, buf_size - 8);

    s->y = s->state = 0;



    /* init the zlib */

    s->zstream.zalloc = ff_png_zalloc;

    s->zstream.zfree  = ff_png_zfree;

    s->zstream.opaque = NULL;

    ret = inflateInit(&s->zstream);

    if (ret != Z_OK)

        return -1;

    for (;;) {

        if (bytestream2_get_bytes_left(&s->gb) <= 0)

            goto fail;

        length = bytestream2_get_be32(&s->gb);

        if (length > 0x7fffffff)

            goto fail;

        tag = bytestream2_get_le32(&s->gb);

        av_dlog(avctx, "png: tag=%c%c%c%c length=%u\n",

                (tag & 0xff),

                ((tag >> 8) & 0xff),

                ((tag >> 16) & 0xff),

                ((tag >> 24) & 0xff), length);

        switch (tag) {

        case MKTAG('I', 'H', 'D', 'R'):

            if (length != 13)

                goto fail;

            s->width  = bytestream2_get_be32(&s->gb);

            s->height = bytestream2_get_be32(&s->gb);

            if (av_image_check_size(s->width, s->height, 0, avctx)) {

                s->width = s->height = 0;

                goto fail;

            }

            s->bit_depth        = bytestream2_get_byte(&s->gb);

            s->color_type       = bytestream2_get_byte(&s->gb);

            s->compression_type = bytestream2_get_byte(&s->gb);

            s->filter_type      = bytestream2_get_byte(&s->gb);

            s->interlace_type   = bytestream2_get_byte(&s->gb);

            bytestream2_skip(&s->gb, 4); /* crc */

            s->state |= PNG_IHDR;

            av_dlog(avctx, "width=%d height=%d depth=%d color_type=%d "

                           "compression_type=%d filter_type=%d interlace_type=%d\n",

                    s->width, s->height, s->bit_depth, s->color_type,

                    s->compression_type, s->filter_type, s->interlace_type);

            break;

        case MKTAG('I', 'D', 'A', 'T'):

            if (!(s->state & PNG_IHDR))

                goto fail;

            if (!(s->state & PNG_IDAT)) {

                /* init image info */

                avctx->width  = s->width;

                avctx->height = s->height;



                s->channels       = ff_png_get_nb_channels(s->color_type);

                s->bits_per_pixel = s->bit_depth * s->channels;

                s->bpp            = (s->bits_per_pixel + 7) >> 3;

                s->row_size       = (avctx->width * s->bits_per_pixel + 7) >> 3;



                if (s->bit_depth == 8 &&

                    s->color_type == PNG_COLOR_TYPE_RGB) {

                    avctx->pix_fmt = AV_PIX_FMT_RGB24;

                } else if (s->bit_depth == 8 &&

                           s->color_type == PNG_COLOR_TYPE_RGB_ALPHA) {

                    avctx->pix_fmt = AV_PIX_FMT_RGB32;

                } else if (s->bit_depth == 8 &&

                           s->color_type == PNG_COLOR_TYPE_GRAY) {

                    avctx->pix_fmt = AV_PIX_FMT_GRAY8;

                } else if (s->bit_depth == 16 &&

                           s->color_type == PNG_COLOR_TYPE_GRAY) {

                    avctx->pix_fmt = AV_PIX_FMT_GRAY16BE;

                } else if (s->bit_depth == 16 &&

                           s->color_type == PNG_COLOR_TYPE_RGB) {

                    avctx->pix_fmt = AV_PIX_FMT_RGB48BE;

                } else if (s->bit_depth == 1 &&

                           s->color_type == PNG_COLOR_TYPE_GRAY) {

                    avctx->pix_fmt = AV_PIX_FMT_MONOBLACK;

                } else if (s->bit_depth == 8 &&

                           s->color_type == PNG_COLOR_TYPE_PALETTE) {

                    avctx->pix_fmt = AV_PIX_FMT_PAL8;

                } else if (s->bit_depth == 8 &&

                           s->color_type == PNG_COLOR_TYPE_GRAY_ALPHA) {

                    avctx->pix_fmt = AV_PIX_FMT_YA8;

                } else if (s->bit_depth == 16 &&

                           s->color_type == PNG_COLOR_TYPE_GRAY_ALPHA) {

                    avctx->pix_fmt = AV_PIX_FMT_YA16BE;

                } else {

                    goto fail;

                }



                if (ff_get_buffer(avctx, p, AV_GET_BUFFER_FLAG_REF) < 0) {

                    av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

                    goto fail;

                }

                p->pict_type        = AV_PICTURE_TYPE_I;

                p->key_frame        = 1;

                p->interlaced_frame = !!s->interlace_type;



                /* compute the compressed row size */

                if (!s->interlace_type) {

                    s->crow_size = s->row_size + 1;

                } else {

                    s->pass          = 0;

                    s->pass_row_size = ff_png_pass_row_size(s->pass,

                                                            s->bits_per_pixel,

                                                            s->width);

                    s->crow_size = s->pass_row_size + 1;

                }

                av_dlog(avctx, "row_size=%d crow_size =%d\n",

                        s->row_size, s->crow_size);

                s->image_buf      = p->data[0];

                s->image_linesize = p->linesize[0];

                /* copy the palette if needed */

                if (s->color_type == PNG_COLOR_TYPE_PALETTE)

                    memcpy(p->data[1], s->palette, 256 * sizeof(uint32_t));

                /* empty row is used if differencing to the first row */

                s->last_row = av_mallocz(s->row_size);

                if (!s->last_row)

                    goto fail;

                if (s->interlace_type ||

                    s->color_type == PNG_COLOR_TYPE_RGB_ALPHA) {

                    s->tmp_row = av_malloc(s->row_size);

                    if (!s->tmp_row)

                        goto fail;

                }

                /* compressed row */

                crow_buf_base = av_malloc(s->row_size + 16);

                if (!crow_buf_base)

                    goto fail;



                /* we want crow_buf+1 to be 16-byte aligned */

                s->crow_buf          = crow_buf_base + 15;

                s->zstream.avail_out = s->crow_size;

                s->zstream.next_out  = s->crow_buf;

            }

            s->state |= PNG_IDAT;

            if (png_decode_idat(s, length) < 0)

                goto fail;

            bytestream2_skip(&s->gb, 4); /* crc */

            break;

        case MKTAG('P', 'L', 'T', 'E'):

        {

            int n, i, r, g, b;



            if ((length % 3) != 0 || length > 256 * 3)

                goto skip_tag;

            /* read the palette */

            n = length / 3;

            for (i = 0; i < n; i++) {

                r = bytestream2_get_byte(&s->gb);

                g = bytestream2_get_byte(&s->gb);

                b = bytestream2_get_byte(&s->gb);

                s->palette[i] = (0xff << 24) | (r << 16) | (g << 8) | b;

            }

            for (; i < 256; i++)

                s->palette[i] = (0xff << 24);

            s->state |= PNG_PLTE;

            bytestream2_skip(&s->gb, 4);     /* crc */

        }

        break;

        case MKTAG('t', 'R', 'N', 'S'):

        {

            int v, i;



            /* read the transparency. XXX: Only palette mode supported */

            if (s->color_type != PNG_COLOR_TYPE_PALETTE ||

                length > 256 ||

                !(s->state & PNG_PLTE))

                goto skip_tag;

            for (i = 0; i < length; i++) {

                v = bytestream2_get_byte(&s->gb);

                s->palette[i] = (s->palette[i] & 0x00ffffff) | (v << 24);

            }

            bytestream2_skip(&s->gb, 4);     /* crc */

        }

        break;

        case MKTAG('I', 'E', 'N', 'D'):

            if (!(s->state & PNG_ALLIMAGE))

                goto fail;

            bytestream2_skip(&s->gb, 4); /* crc */

            goto exit_loop;

        default:

            /* skip tag */

skip_tag:

            bytestream2_skip(&s->gb, length + 4);

            break;

        }

    }

exit_loop:

    /* handle p-frames only if a predecessor frame is available */

    if (s->prev->data[0]) {

        if (!(avpkt->flags & AV_PKT_FLAG_KEY)) {

            int i, j;

            uint8_t *pd      = p->data[0];

            uint8_t *pd_last = s->prev->data[0];



            for (j = 0; j < s->height; j++) {

                for (i = 0; i < s->width * s->bpp; i++)

                    pd[i] += pd_last[i];

                pd      += s->image_linesize;

                pd_last += s->image_linesize;

            }

        }

    }



    av_frame_unref(s->prev);

    if ((ret = av_frame_ref(s->prev, p)) < 0)

        goto fail;



    *got_frame = 1;



    ret = bytestream2_tell(&s->gb);

the_end:

    inflateEnd(&s->zstream);

    av_free(crow_buf_base);

    s->crow_buf = NULL;

    av_freep(&s->last_row);

    av_freep(&s->tmp_row);

    return ret;

fail:

    ret = -1;

    goto the_end;

}

BlockDriverAIOCB *bdrv_aio_write(BlockDriverState *bs, int64_t sector_num,

                                 const uint8_t *buf, int nb_sectors,

                                 BlockDriverCompletionFunc *cb, void *opaque)

{

    BlockDriver *drv = bs->drv;

    BlockDriverAIOCB *ret;



    if (!drv)

        return NULL;

    if (bs->read_only)

        return NULL;

    if (bdrv_wr_badreq_sectors(bs, sector_num, nb_sectors))

        return NULL;

    if (sector_num == 0 && bs->boot_sector_enabled && nb_sectors > 0) {

        memcpy(bs->boot_sector_data, buf, 512);

    }



    ret = drv->bdrv_aio_write(bs, sector_num, buf, nb_sectors, cb, opaque);



    if (ret) {

	/* Update stats even though technically transfer has not happened. */

	bs->wr_bytes += (unsigned) nb_sectors * SECTOR_SIZE;

	bs->wr_ops ++;

    }



    return ret;

}

int bdrv_write(BlockDriverState *bs, int64_t sector_num,

               const uint8_t *buf, int nb_sectors)

{

    BlockDriver *drv = bs->drv;

    if (!bs->drv)

        return -ENOMEDIUM;

    if (bs->read_only)

        return -EACCES;

    if (bdrv_check_request(bs, sector_num, nb_sectors))

        return -EIO;



    return drv->bdrv_write(bs, sector_num, buf, nb_sectors);

}

BlockDriverAIOCB *bdrv_aio_read(BlockDriverState *bs, int64_t sector_num,

                                uint8_t *buf, int nb_sectors,

                                BlockDriverCompletionFunc *cb, void *opaque)

{

    BlockDriver *drv = bs->drv;

    BlockDriverAIOCB *ret;



    if (!drv)

        return NULL;



    /* XXX: we assume that nb_sectors == 0 is suppored by the async read */

    if (sector_num == 0 && bs->boot_sector_enabled && nb_sectors > 0) {

        memcpy(buf, bs->boot_sector_data, 512);

        sector_num++;

        nb_sectors--;

        buf += 512;

    }



    ret = drv->bdrv_aio_read(bs, sector_num, buf, nb_sectors, cb, opaque);



    if (ret) {

	/* Update stats even though technically transfer has not happened. */

	bs->rd_bytes += (unsigned) nb_sectors * SECTOR_SIZE;

	bs->rd_ops ++;

    }



    return ret;

}

static BlockDriverAIOCB *quorum_aio_readv(BlockDriverState *bs,

                                         int64_t sector_num,

                                         QEMUIOVector *qiov,

                                         int nb_sectors,

                                         BlockDriverCompletionFunc *cb,

                                         void *opaque)

{

    BDRVQuorumState *s = bs->opaque;

    QuorumAIOCB *acb = quorum_aio_get(s, bs, qiov, sector_num,

                                      nb_sectors, cb, opaque);

    int i;



    acb->is_read = true;



    for (i = 0; i < s->num_children; i++) {

        acb->qcrs[i].buf = qemu_blockalign(s->bs[i], qiov->size);

        qemu_iovec_init(&acb->qcrs[i].qiov, qiov->niov);

        qemu_iovec_clone(&acb->qcrs[i].qiov, qiov, acb->qcrs[i].buf);

    }



    for (i = 0; i < s->num_children; i++) {

        bdrv_aio_readv(s->bs[i], sector_num, &acb->qcrs[i].qiov, nb_sectors,

                       quorum_aio_cb, &acb->qcrs[i]);

    }



    return &acb->common;

}

static void test_machine(gconstpointer data)

{

    const char *machine = data;

    char *args;

    QDict *response;



    args = g_strdup_printf("-machine %s", machine);

    qtest_start(args);



    test_properties("/machine");



    response = qmp("{ 'execute': 'quit' }");

    g_assert(qdict_haskey(response, "return"));



    qtest_end();

    g_free(args);

}

static void migrate_check_parameter(QTestState *who, const char *parameter,

                                    const char *value)

{

    QDict *rsp, *rsp_return;

    const char *result;



    rsp = wait_command(who, "{ 'execute': 'query-migrate-parameters' }");

    rsp_return = qdict_get_qdict(rsp, "return");

    result = g_strdup_printf("%" PRId64,

                             qdict_get_try_int(rsp_return,  parameter, -1));

    g_assert_cmpstr(result, ==, value);

    QDECREF(rsp);

}

void qdev_property_add_child(DeviceState *dev, const char *name,

                             DeviceState *child, Error **errp)

{

    gchar *type;



    type = g_strdup_printf("child<%s>", child->info->name);



    qdev_property_add(dev, name, type, qdev_get_child_property,

                      NULL, NULL, child, errp);



    qdev_ref(child);

    g_assert(child->parent == NULL);

    child->parent = dev;



    g_free(type);

}

static void vmgenid_set_guid_test(void)

{

    QemuUUID expected, measured;

    gchar *cmd;



    g_assert(qemu_uuid_parse(VGID_GUID, &expected) == 0);



    cmd = g_strdup_printf("-machine accel=tcg -device vmgenid,id=testvgid,"

                          "guid=%s", VGID_GUID);

    qtest_start(cmd);



    /* Read the GUID from accessing guest memory */

    read_guid_from_memory(&measured);

    g_assert(memcmp(measured.data, expected.data, sizeof(measured.data)) == 0);



    qtest_quit(global_qtest);

    g_free(cmd);

}

uint32_t do_arm_semihosting(CPUARMState *env)

{

    target_ulong args;

    char * s;

    int nr;

    uint32_t ret;

    uint32_t len;

#ifdef CONFIG_USER_ONLY

    TaskState *ts = env->opaque;

#else

    CPUARMState *ts = env;

#endif



    nr = env->regs[0];

    args = env->regs[1];

    switch (nr) {

    case TARGET_SYS_OPEN:

        if (!(s = lock_user_string(ARG(0))))

            /* FIXME - should this error code be -TARGET_EFAULT ? */

            return (uint32_t)-1;

        if (ARG(1) >= 12)

            return (uint32_t)-1;

        if (strcmp(s, ":tt") == 0) {

            if (ARG(1) < 4)

                return STDIN_FILENO;

            else

                return STDOUT_FILENO;

        }

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "open,%s,%x,1a4", ARG(0),

			   (int)ARG(2)+1, gdb_open_modeflags[ARG(1)]);

            return env->regs[0];

        } else {

            ret = set_swi_errno(ts, open(s, open_modeflags[ARG(1)], 0644));

        }

        unlock_user(s, ARG(0), 0);

        return ret;

    case TARGET_SYS_CLOSE:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "close,%x", ARG(0));

            return env->regs[0];

        } else {

            return set_swi_errno(ts, close(ARG(0)));

        }

    case TARGET_SYS_WRITEC:

        {

          char c;



          if (get_user_u8(c, args))

              /* FIXME - should this error code be -TARGET_EFAULT ? */

              return (uint32_t)-1;

          /* Write to debug console.  stderr is near enough.  */

          if (use_gdb_syscalls()) {

                gdb_do_syscall(arm_semi_cb, "write,2,%x,1", args);

                return env->regs[0];

          } else {

                return write(STDERR_FILENO, &c, 1);

          }

        }

    case TARGET_SYS_WRITE0:

        if (!(s = lock_user_string(args)))

            /* FIXME - should this error code be -TARGET_EFAULT ? */

            return (uint32_t)-1;

        len = strlen(s);

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "write,2,%x,%x\n", args, len);

            ret = env->regs[0];

        } else {

            ret = write(STDERR_FILENO, s, len);

        }

        unlock_user(s, args, 0);

        return ret;

    case TARGET_SYS_WRITE:

        len = ARG(2);

        if (use_gdb_syscalls()) {

            arm_semi_syscall_len = len;

            gdb_do_syscall(arm_semi_cb, "write,%x,%x,%x", ARG(0), ARG(1), len);

            return env->regs[0];

        } else {

            if (!(s = lock_user(VERIFY_READ, ARG(1), len, 1)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ret = set_swi_errno(ts, write(ARG(0), s, len));

            unlock_user(s, ARG(1), 0);

            if (ret == (uint32_t)-1)

                return -1;

            return len - ret;

        }

    case TARGET_SYS_READ:

        len = ARG(2);

        if (use_gdb_syscalls()) {

            arm_semi_syscall_len = len;

            gdb_do_syscall(arm_semi_cb, "read,%x,%x,%x", ARG(0), ARG(1), len);

            return env->regs[0];

        } else {

            if (!(s = lock_user(VERIFY_WRITE, ARG(1), len, 0)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            do

              ret = set_swi_errno(ts, read(ARG(0), s, len));

            while (ret == -1 && errno == EINTR);

            unlock_user(s, ARG(1), len);

            if (ret == (uint32_t)-1)

                return -1;

            return len - ret;

        }

    case TARGET_SYS_READC:

       /* XXX: Read from debug console. Not implemented.  */

        return 0;

    case TARGET_SYS_ISTTY:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "isatty,%x", ARG(0));

            return env->regs[0];

        } else {

            return isatty(ARG(0));

        }

    case TARGET_SYS_SEEK:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "lseek,%x,%x,0", ARG(0), ARG(1));

            return env->regs[0];

        } else {

            ret = set_swi_errno(ts, lseek(ARG(0), ARG(1), SEEK_SET));

            if (ret == (uint32_t)-1)

              return -1;

            return 0;

        }

    case TARGET_SYS_FLEN:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_flen_cb, "fstat,%x,%x",

			   ARG(0), env->regs[13]-64);

            return env->regs[0];

        } else {

            struct stat buf;

            ret = set_swi_errno(ts, fstat(ARG(0), &buf));

            if (ret == (uint32_t)-1)

                return -1;

            return buf.st_size;

        }

    case TARGET_SYS_TMPNAM:

        /* XXX: Not implemented.  */

        return -1;

    case TARGET_SYS_REMOVE:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "unlink,%s", ARG(0), (int)ARG(1)+1);

            ret = env->regs[0];

        } else {

            if (!(s = lock_user_string(ARG(0))))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ret =  set_swi_errno(ts, remove(s));

            unlock_user(s, ARG(0), 0);

        }

        return ret;

    case TARGET_SYS_RENAME:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "rename,%s,%s",

                           ARG(0), (int)ARG(1)+1, ARG(2), (int)ARG(3)+1);

            return env->regs[0];

        } else {

            char *s2;

            s = lock_user_string(ARG(0));

            s2 = lock_user_string(ARG(2));

            if (!s || !s2)

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                ret = (uint32_t)-1;

            else

                ret = set_swi_errno(ts, rename(s, s2));

            if (s2)

                unlock_user(s2, ARG(2), 0);

            if (s)

                unlock_user(s, ARG(0), 0);

            return ret;

        }

    case TARGET_SYS_CLOCK:

        return clock() / (CLOCKS_PER_SEC / 100);

    case TARGET_SYS_TIME:

        return set_swi_errno(ts, time(NULL));

    case TARGET_SYS_SYSTEM:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "system,%s", ARG(0), (int)ARG(1)+1);

            return env->regs[0];

        } else {

            if (!(s = lock_user_string(ARG(0))))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ret = set_swi_errno(ts, system(s));

            unlock_user(s, ARG(0), 0);

            return ret;

        }

    case TARGET_SYS_ERRNO:

#ifdef CONFIG_USER_ONLY

        return ts->swi_errno;

#else

        return syscall_err;

#endif

    case TARGET_SYS_GET_CMDLINE:

        {

            /* Build a command-line from the original argv.

             *

             * The inputs are:

             *     * ARG(0), pointer to a buffer of at least the size

             *               specified in ARG(1).

             *     * ARG(1), size of the buffer pointed to by ARG(0) in

             *               bytes.

             *

             * The outputs are:

             *     * ARG(0), pointer to null-terminated string of the

             *               command line.

             *     * ARG(1), length of the string pointed to by ARG(0).

             */



            char *output_buffer;

            size_t input_size = ARG(1);

            size_t output_size;

            int status = 0;



            /* Compute the size of the output string.  */

#if !defined(CONFIG_USER_ONLY)

            output_size = strlen(ts->boot_info->kernel_filename)

                        + 1  /* Separating space.  */

                        + strlen(ts->boot_info->kernel_cmdline)

                        + 1; /* Terminating null byte.  */

#else

            unsigned int i;



            output_size = ts->info->arg_end - ts->info->arg_start;

            if (!output_size) {

                /* We special-case the "empty command line" case (argc==0).

                   Just provide the terminating 0. */

                output_size = 1;

            }

#endif



            if (output_size > input_size) {

                 /* Not enough space to store command-line arguments.  */

                return -1;

            }



            /* Adjust the command-line length.  */

            SET_ARG(1, output_size - 1);



            /* Lock the buffer on the ARM side.  */

            output_buffer = lock_user(VERIFY_WRITE, ARG(0), output_size, 0);

            if (!output_buffer) {

                return -1;

            }



            /* Copy the command-line arguments.  */

#if !defined(CONFIG_USER_ONLY)

            pstrcpy(output_buffer, output_size, ts->boot_info->kernel_filename);

            pstrcat(output_buffer, output_size, " ");

            pstrcat(output_buffer, output_size, ts->boot_info->kernel_cmdline);

#else

            if (output_size == 1) {

                /* Empty command-line.  */

                output_buffer[0] = '\0';

                goto out;

            }



            if (copy_from_user(output_buffer, ts->info->arg_start,

                               output_size)) {

                status = -1;

                goto out;

            }



            /* Separate arguments by white spaces.  */

            for (i = 0; i < output_size - 1; i++) {

                if (output_buffer[i] == 0) {

                    output_buffer[i] = ' ';

                }

            }

        out:

#endif

            /* Unlock the buffer on the ARM side.  */

            unlock_user(output_buffer, ARG(0), output_size);



            return status;

        }

    case TARGET_SYS_HEAPINFO:

        {

            uint32_t *ptr;

            uint32_t limit;



#ifdef CONFIG_USER_ONLY

            /* Some C libraries assume the heap immediately follows .bss, so

               allocate it using sbrk.  */

            if (!ts->heap_limit) {

                abi_ulong ret;



                ts->heap_base = do_brk(0);

                limit = ts->heap_base + ARM_ANGEL_HEAP_SIZE;

                /* Try a big heap, and reduce the size if that fails.  */

                for (;;) {

                    ret = do_brk(limit);

                    if (ret >= limit) {

                        break;

                    }

                    limit = (ts->heap_base >> 1) + (limit >> 1);

                }

                ts->heap_limit = limit;

            }



            if (!(ptr = lock_user(VERIFY_WRITE, ARG(0), 16, 0)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ptr[0] = tswap32(ts->heap_base);

            ptr[1] = tswap32(ts->heap_limit);

            ptr[2] = tswap32(ts->stack_base);

            ptr[3] = tswap32(0); /* Stack limit.  */

            unlock_user(ptr, ARG(0), 16);

#else

            limit = ram_size;

            if (!(ptr = lock_user(VERIFY_WRITE, ARG(0), 16, 0)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            /* TODO: Make this use the limit of the loaded application.  */

            ptr[0] = tswap32(limit / 2);

            ptr[1] = tswap32(limit);

            ptr[2] = tswap32(limit); /* Stack base */

            ptr[3] = tswap32(0); /* Stack limit.  */

            unlock_user(ptr, ARG(0), 16);

#endif

            return 0;

        }

    case TARGET_SYS_EXIT:

        gdb_exit(env, 0);

        exit(0);

    default:

        fprintf(stderr, "qemu: Unsupported SemiHosting SWI 0x%02x\n", nr);

        cpu_dump_state(env, stderr, fprintf, 0);

        abort();

    }

}

uint32_t do_arm_semihosting(CPUState *env)

{

    target_ulong args;

    char * s;

    int nr;

    uint32_t ret;

    uint32_t len;

#ifdef CONFIG_USER_ONLY

    TaskState *ts = env->opaque;

#else

    CPUState *ts = env;

#endif



    nr = env->regs[0];

    args = env->regs[1];

    switch (nr) {

    case SYS_OPEN:

        if (!(s = lock_user_string(ARG(0))))

            /* FIXME - should this error code be -TARGET_EFAULT ? */

            return (uint32_t)-1;

        if (ARG(1) >= 12)

            return (uint32_t)-1;

        if (strcmp(s, ":tt") == 0) {

            if (ARG(1) < 4)

                return STDIN_FILENO;

            else

                return STDOUT_FILENO;

        }

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "open,%s,%x,1a4", ARG(0),

			   (int)ARG(2)+1, gdb_open_modeflags[ARG(1)]);

            return env->regs[0];

        } else {

            ret = set_swi_errno(ts, open(s, open_modeflags[ARG(1)], 0644));

        }

        unlock_user(s, ARG(0), 0);

        return ret;

    case SYS_CLOSE:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "close,%x", ARG(0));

            return env->regs[0];

        } else {

            return set_swi_errno(ts, close(ARG(0)));

        }

    case SYS_WRITEC:

        {

          char c;



          if (get_user_u8(c, args))

              /* FIXME - should this error code be -TARGET_EFAULT ? */

              return (uint32_t)-1;

          /* Write to debug console.  stderr is near enough.  */

          if (use_gdb_syscalls()) {

                gdb_do_syscall(arm_semi_cb, "write,2,%x,1", args);

                return env->regs[0];

          } else {

                return write(STDERR_FILENO, &c, 1);

          }

        }

    case SYS_WRITE0:

        if (!(s = lock_user_string(args)))

            /* FIXME - should this error code be -TARGET_EFAULT ? */

            return (uint32_t)-1;

        len = strlen(s);

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "write,2,%x,%x\n", args, len);

            ret = env->regs[0];

        } else {

            ret = write(STDERR_FILENO, s, len);

        }

        unlock_user(s, args, 0);

        return ret;

    case SYS_WRITE:

        len = ARG(2);

        if (use_gdb_syscalls()) {

            arm_semi_syscall_len = len;

            gdb_do_syscall(arm_semi_cb, "write,%x,%x,%x", ARG(0), ARG(1), len);

            return env->regs[0];

        } else {

            if (!(s = lock_user(VERIFY_READ, ARG(1), len, 1)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ret = set_swi_errno(ts, write(ARG(0), s, len));

            unlock_user(s, ARG(1), 0);

            if (ret == (uint32_t)-1)

                return -1;

            return len - ret;

        }

    case SYS_READ:

        len = ARG(2);

        if (use_gdb_syscalls()) {

            arm_semi_syscall_len = len;

            gdb_do_syscall(arm_semi_cb, "read,%x,%x,%x", ARG(0), ARG(1), len);

            return env->regs[0];

        } else {

            if (!(s = lock_user(VERIFY_WRITE, ARG(1), len, 0)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            do

              ret = set_swi_errno(ts, read(ARG(0), s, len));

            while (ret == -1 && errno == EINTR);

            unlock_user(s, ARG(1), len);

            if (ret == (uint32_t)-1)

                return -1;

            return len - ret;

        }

    case SYS_READC:

       /* XXX: Read from debug cosole. Not implemented.  */

        return 0;

    case SYS_ISTTY:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "isatty,%x", ARG(0));

            return env->regs[0];

        } else {

            return isatty(ARG(0));

        }

    case SYS_SEEK:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "lseek,%x,%x,0", ARG(0), ARG(1));

            return env->regs[0];

        } else {

            ret = set_swi_errno(ts, lseek(ARG(0), ARG(1), SEEK_SET));

            if (ret == (uint32_t)-1)

              return -1;

            return 0;

        }

    case SYS_FLEN:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_flen_cb, "fstat,%x,%x",

			   ARG(0), env->regs[13]-64);

            return env->regs[0];

        } else {

            struct stat buf;

            ret = set_swi_errno(ts, fstat(ARG(0), &buf));

            if (ret == (uint32_t)-1)

                return -1;

            return buf.st_size;

        }

    case SYS_TMPNAM:

        /* XXX: Not implemented.  */

        return -1;

    case SYS_REMOVE:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "unlink,%s", ARG(0), (int)ARG(1)+1);

            ret = env->regs[0];

        } else {

            if (!(s = lock_user_string(ARG(0))))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ret =  set_swi_errno(ts, remove(s));

            unlock_user(s, ARG(0), 0);

        }

        return ret;

    case SYS_RENAME:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "rename,%s,%s",

                           ARG(0), (int)ARG(1)+1, ARG(2), (int)ARG(3)+1);

            return env->regs[0];

        } else {

            char *s2;

            s = lock_user_string(ARG(0));

            s2 = lock_user_string(ARG(2));

            if (!s || !s2)

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                ret = (uint32_t)-1;

            else

                ret = set_swi_errno(ts, rename(s, s2));

            if (s2)

                unlock_user(s2, ARG(2), 0);

            if (s)

                unlock_user(s, ARG(0), 0);

            return ret;

        }

    case SYS_CLOCK:

        return clock() / (CLOCKS_PER_SEC / 100);

    case SYS_TIME:

        return set_swi_errno(ts, time(NULL));

    case SYS_SYSTEM:

        if (use_gdb_syscalls()) {

            gdb_do_syscall(arm_semi_cb, "system,%s", ARG(0), (int)ARG(1)+1);

            return env->regs[0];

        } else {

            if (!(s = lock_user_string(ARG(0))))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ret = set_swi_errno(ts, system(s));

            unlock_user(s, ARG(0), 0);

            return ret;

        }

    case SYS_ERRNO:

#ifdef CONFIG_USER_ONLY

        return ts->swi_errno;

#else

        return syscall_err;

#endif

    case SYS_GET_CMDLINE:

#ifdef CONFIG_USER_ONLY

        /* Build a commandline from the original argv.  */

        {

            char *arm_cmdline_buffer;

            const char *host_cmdline_buffer;



            unsigned int i;

            unsigned int arm_cmdline_len = ARG(1);

            unsigned int host_cmdline_len =

                ts->info->arg_end-ts->info->arg_start;



            if (!arm_cmdline_len || host_cmdline_len > arm_cmdline_len) {

                return -1; /* not enough space to store command line */

            }



            if (!host_cmdline_len) {

                /* We special-case the "empty command line" case (argc==0).

                   Just provide the terminating 0. */

                arm_cmdline_buffer = lock_user(VERIFY_WRITE, ARG(0), 1, 0);

                arm_cmdline_buffer[0] = 0;

                unlock_user(arm_cmdline_buffer, ARG(0), 1);



                /* Adjust the commandline length argument. */

                SET_ARG(1, 0);

                return 0;

            }



            /* lock the buffers on the ARM side */

            arm_cmdline_buffer =

                lock_user(VERIFY_WRITE, ARG(0), host_cmdline_len, 0);

            host_cmdline_buffer =

                lock_user(VERIFY_READ, ts->info->arg_start,

                                       host_cmdline_len, 1);



            if (arm_cmdline_buffer && host_cmdline_buffer)

            {

                /* the last argument is zero-terminated;

                   no need for additional termination */

                memcpy(arm_cmdline_buffer, host_cmdline_buffer,

                       host_cmdline_len);



                /* separate arguments by white spaces */

                for (i = 0; i < host_cmdline_len-1; i++) {

                    if (arm_cmdline_buffer[i] == 0) {

                        arm_cmdline_buffer[i] = ' ';

                    }

                }



                /* Adjust the commandline length argument. */

                SET_ARG(1, host_cmdline_len-1);

            }



            /* Unlock the buffers on the ARM side.  */

            unlock_user(arm_cmdline_buffer, ARG(0), host_cmdline_len);

            unlock_user((void*)host_cmdline_buffer, ts->info->arg_start, 0);



            /* Return success if we could return a commandline.  */

            return (arm_cmdline_buffer && host_cmdline_buffer) ? 0 : -1;

        }

#else

        return -1;

#endif

    case SYS_HEAPINFO:

        {

            uint32_t *ptr;

            uint32_t limit;



#ifdef CONFIG_USER_ONLY

            /* Some C libraries assume the heap immediately follows .bss, so

               allocate it using sbrk.  */

            if (!ts->heap_limit) {

                long ret;



                ts->heap_base = do_brk(0);

                limit = ts->heap_base + ARM_ANGEL_HEAP_SIZE;

                /* Try a big heap, and reduce the size if that fails.  */

                for (;;) {

                    ret = do_brk(limit);

                    if (ret != -1)

                        break;

                    limit = (ts->heap_base >> 1) + (limit >> 1);

                }

                ts->heap_limit = limit;

            }



            if (!(ptr = lock_user(VERIFY_WRITE, ARG(0), 16, 0)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            ptr[0] = tswap32(ts->heap_base);

            ptr[1] = tswap32(ts->heap_limit);

            ptr[2] = tswap32(ts->stack_base);

            ptr[3] = tswap32(0); /* Stack limit.  */

            unlock_user(ptr, ARG(0), 16);

#else

            limit = ram_size;

            if (!(ptr = lock_user(VERIFY_WRITE, ARG(0), 16, 0)))

                /* FIXME - should this error code be -TARGET_EFAULT ? */

                return (uint32_t)-1;

            /* TODO: Make this use the limit of the loaded application.  */

            ptr[0] = tswap32(limit / 2);

            ptr[1] = tswap32(limit);

            ptr[2] = tswap32(limit); /* Stack base */

            ptr[3] = tswap32(0); /* Stack limit.  */

            unlock_user(ptr, ARG(0), 16);

#endif

            return 0;

        }

    case SYS_EXIT:

        gdb_exit(env, 0);

        exit(0);

    default:

        fprintf(stderr, "qemu: Unsupported SemiHosting SWI 0x%02x\n", nr);

        cpu_dump_state(env, stderr, fprintf, 0);

        abort();

    }

}

