void visit_type_uint64(Visitor *v, uint64_t *obj, const char *name, Error **errp)

{

    int64_t value;

    if (!error_is_set(errp)) {

        if (v->type_uint64) {

            v->type_uint64(v, obj, name, errp);

        } else {

            value = *obj;

            v->type_int(v, &value, name, errp);

            *obj = value;

        }

    }

}

