static int dump_ppc_insns (CPUPPCState *env)

{

    opc_handler_t **table, *handler;

    uint8_t opc1, opc2, opc3;



    printf("Instructions set:\n");

    /* opc1 is 6 bits long */

    for (opc1 = 0x00; opc1 < 0x40; opc1++) {

        table = env->opcodes;

        handler = table[opc1];

        if (is_indirect_opcode(handler)) {

            /* opc2 is 5 bits long */

            for (opc2 = 0; opc2 < 0x20; opc2++) {

                table = env->opcodes;

                handler = env->opcodes[opc1];

                table = ind_table(handler);

                handler = table[opc2];

                if (is_indirect_opcode(handler)) {

                    table = ind_table(handler);

                    /* opc3 is 5 bits long */

                    for (opc3 = 0; opc3 < 0x20; opc3++) {

                        handler = table[opc3];

                        if (handler->handler != &gen_invalid) {

                            printf("INSN: %02x %02x %02x (%02d %04d) : %s\n",

                                   opc1, opc2, opc3, opc1, (opc3 << 5) | opc2,

                                   handler->oname);

                        }

                    }

                } else {

                    if (handler->handler != &gen_invalid) {

                        printf("INSN: %02x %02x -- (%02d %04d) : %s\n",

                               opc1, opc2, opc1, opc2, handler->oname);

                    }

                }

            }

        } else {

            if (handler->handler != &gen_invalid) {

                printf("INSN: %02x -- -- (%02d ----) : %s\n",

                       opc1, opc1, handler->oname);

            }

        }

    }

}

static void ppc_cpu_unrealizefn(DeviceState *dev, Error **errp)

{

    PowerPCCPU *cpu = POWERPC_CPU(dev);

    CPUPPCState *env = &cpu->env;

    opc_handler_t **table;

    int i, j;



    cpu_exec_exit(CPU(dev));



    for (i = 0; i < PPC_CPU_OPCODES_LEN; i++) {

        if (env->opcodes[i] == &invalid_handler) {

            continue;

        }

        if (is_indirect_opcode(env->opcodes[i])) {

            table = ind_table(env->opcodes[i]);

            for (j = 0; j < PPC_CPU_INDIRECT_OPCODES_LEN; j++) {

                if (table[j] != &invalid_handler &&

                        is_indirect_opcode(table[j])) {

                    g_free((opc_handler_t *)((uintptr_t)table[j] &

                        ~PPC_INDIRECT));

                }

            }

            g_free((opc_handler_t *)((uintptr_t)env->opcodes[i] &

                ~PPC_INDIRECT));

        }

    }

}

void cpu_dump_statistics (CPUState *env, FILE*f,

                          int (*cpu_fprintf)(FILE *f, const char *fmt, ...),

                          int flags)

{

#if defined(DO_PPC_STATISTICS)

    opc_handler_t **t1, **t2, **t3, *handler;

    int op1, op2, op3;



    t1 = env->opcodes;

    for (op1 = 0; op1 < 64; op1++) {

        handler = t1[op1];

        if (is_indirect_opcode(handler)) {

            t2 = ind_table(handler);

            for (op2 = 0; op2 < 32; op2++) {

                handler = t2[op2];

                if (is_indirect_opcode(handler)) {

                    t3 = ind_table(handler);

                    for (op3 = 0; op3 < 32; op3++) {

                        handler = t3[op3];

                        if (handler->count == 0)

                            continue;

                        cpu_fprintf(f, "%02x %02x %02x (%02x %04d) %16s: "

                                    "%016" PRIx64 " %" PRId64 "\n",

                                    op1, op2, op3, op1, (op3 << 5) | op2,

                                    handler->oname,

                                    handler->count, handler->count);

                    }

                } else {

                    if (handler->count == 0)

                        continue;

                    cpu_fprintf(f, "%02x %02x    (%02x %04d) %16s: "

                                "%016" PRIx64 " %" PRId64 "\n",

                                op1, op2, op1, op2, handler->oname,

                                handler->count, handler->count);

                }

            }

        } else {

            if (handler->count == 0)

                continue;

            cpu_fprintf(f, "%02x       (%02x     ) %16s: %016" PRIx64

                        " %" PRId64 "\n",

                        op1, op1, handler->oname,

                        handler->count, handler->count);

        }

    }

#endif

}

static void usage(void)

{

    const struct qemu_argument *arginfo;

    int maxarglen;

    int maxenvlen;



    printf("usage: qemu-" TARGET_ARCH " [options] program [arguments...]\n"

           "Linux CPU emulator (compiled for " TARGET_ARCH " emulation)\n"

           "\n"

           "Options and associated environment variables:\n"

           "\n");



    maxarglen = maxenvlen = 0;



    for (arginfo = arg_table; arginfo->handle_opt != NULL; arginfo++) {

        if (strlen(arginfo->env) > maxenvlen) {

            maxenvlen = strlen(arginfo->env);

        }

        if (strlen(arginfo->argv) > maxarglen) {

            maxarglen = strlen(arginfo->argv);

        }

    }



    printf("%-*s%-*sDescription\n", maxarglen+3, "Argument",

            maxenvlen+1, "Env-variable");



    for (arginfo = arg_table; arginfo->handle_opt != NULL; arginfo++) {

        if (arginfo->has_arg) {

            printf("-%s %-*s %-*s %s\n", arginfo->argv,

                    (int)(maxarglen-strlen(arginfo->argv)), arginfo->example,

                    maxenvlen, arginfo->env, arginfo->help);

        } else {

            printf("-%-*s %-*s %s\n", maxarglen+1, arginfo->argv,

                    maxenvlen, arginfo->env,

                    arginfo->help);

        }

    }



    printf("\n"

           "Defaults:\n"

           "QEMU_LD_PREFIX  = %s\n"

           "QEMU_STACK_SIZE = %ld byte\n",

           interp_prefix,

           guest_stack_size);



    printf("\n"

           "You can use -E and -U options or the QEMU_SET_ENV and\n"

           "QEMU_UNSET_ENV environment variables to set and unset\n"

           "environment variables for the target process.\n"

           "It is possible to provide several variables by separating them\n"

           "by commas in getsubopt(3) style. Additionally it is possible to\n"

           "provide the -E and -U options multiple times.\n"

           "The following lines are equivalent:\n"

           "    -E var1=val2 -E var2=val2 -U LD_PRELOAD -U LD_DEBUG\n"

           "    -E var1=val2,var2=val2 -U LD_PRELOAD,LD_DEBUG\n"

           "    QEMU_SET_ENV=var1=val2,var2=val2 QEMU_UNSET_ENV=LD_PRELOAD,LD_DEBUG\n"

           "Note that if you provide several changes to a single variable\n"

           "the last change will stay in effect.\n");



    exit(1);

}

yuv2rgb_2_c_template(SwsContext *c, const int16_t *buf[2],
                     const int16_t *ubuf[2], const int16_t *vbuf[2],
                     const int16_t *abuf[2], uint8_t *dest, int dstW,
                     int yalpha, int uvalpha, int y,
                     enum PixelFormat target, int hasAlpha)
{
    const int16_t *buf0  = buf[0],  *buf1  = buf[1],
                  *ubuf0 = ubuf[0], *ubuf1 = ubuf[1],
                  *vbuf0 = vbuf[0], *vbuf1 = vbuf[1],
                  *abuf0 = hasAlpha ? abuf[0] : NULL,
                  *abuf1 = hasAlpha ? abuf[1] : NULL;
    int  yalpha1 = 4095 - yalpha;
    int uvalpha1 = 4095 - uvalpha;
    int i;
    for (i = 0; i < (dstW >> 1); i++) {
        int Y1 = (buf0[i * 2]     * yalpha1  + buf1[i * 2]     * yalpha)  >> 19;
        int Y2 = (buf0[i * 2 + 1] * yalpha1  + buf1[i * 2 + 1] * yalpha)  >> 19;
        int U  = (ubuf0[i]        * uvalpha1 + ubuf1[i]        * uvalpha) >> 19;
        int V  = (vbuf0[i]        * uvalpha1 + vbuf1[i]        * uvalpha) >> 19;
        int A1, A2;
        const void *r =  c->table_rV[V],
                   *g = (c->table_gU[U] + c->table_gV[V]),
                   *b =  c->table_bU[U];
        if (hasAlpha) {
            A1 = (abuf0[i * 2    ] * yalpha1 + abuf1[i * 2    ] * yalpha) >> 19;
            A2 = (abuf0[i * 2 + 1] * yalpha1 + abuf1[i * 2 + 1] * yalpha) >> 19;
        }
        yuv2rgb_write(dest, i, Y1, Y2, hasAlpha ? A1 : 0, hasAlpha ? A2 : 0,
                      r, g, b, y, target, hasAlpha);
    }
}

yuv2rgb_full_2_c_template(SwsContext *c, const int16_t *buf[2],

                     const int16_t *ubuf[2], const int16_t *vbuf[2],

                     const int16_t *abuf[2], uint8_t *dest, int dstW,

                     int yalpha, int uvalpha, int y,

                     enum AVPixelFormat target, int hasAlpha)

{

    const int16_t *buf0  = buf[0],  *buf1  = buf[1],

                  *ubuf0 = ubuf[0], *ubuf1 = ubuf[1],

                  *vbuf0 = vbuf[0], *vbuf1 = vbuf[1],

                  *abuf0 = hasAlpha ? abuf[0] : NULL,

                  *abuf1 = hasAlpha ? abuf[1] : NULL;

    int  yalpha1 = 4096 - yalpha;

    int uvalpha1 = 4096 - uvalpha;

    int i;

    int step = (target == AV_PIX_FMT_RGB24 || target == AV_PIX_FMT_BGR24) ? 3 : 4;

    int err[4] = {0};



    if(   target == AV_PIX_FMT_BGR4_BYTE || target == AV_PIX_FMT_RGB4_BYTE

       || target == AV_PIX_FMT_BGR8      || target == AV_PIX_FMT_RGB8)

        step = 1;



    for (i = 0; i < dstW; i++) {

        int Y = ( buf0[i] * yalpha1  +  buf1[i] * yalpha             ) >> 10; //FIXME rounding

        int U = (ubuf0[i] * uvalpha1 + ubuf1[i] * uvalpha-(128 << 19)) >> 10;

        int V = (vbuf0[i] * uvalpha1 + vbuf1[i] * uvalpha-(128 << 19)) >> 10;

        int A;



        if (hasAlpha) {

            A = (abuf0[i] * yalpha1 + abuf1[i] * yalpha + (1<<18)) >> 19;

            if (A & 0x100)

                A = av_clip_uint8(A);

        }



        yuv2rgb_write_full(c, dest, i, Y, A, U, V, y, target, hasAlpha, err);

        dest += step;

    }

    c->dither_error[0][i] = err[0];

    c->dither_error[1][i] = err[1];

    c->dither_error[2][i] = err[2];

}

