static int bink_decode_plane(BinkContext *c, GetBitContext *gb, int plane_idx,

                             int is_chroma)

{

    int blk;

    int i, j, bx, by;

    uint8_t *dst, *prev, *ref, *ref_start, *ref_end;

    int v, col[2];

    const uint8_t *scan;

    int xoff, yoff;

    LOCAL_ALIGNED_16(DCTELEM, block, [64]);

    LOCAL_ALIGNED_16(uint8_t, ublock, [64]);

    LOCAL_ALIGNED_16(int32_t, dctblock, [64]);

    int coordmap[64];



    const int stride = c->pic.linesize[plane_idx];

    int bw = is_chroma ? (c->avctx->width  + 15) >> 4 : (c->avctx->width  + 7) >> 3;

    int bh = is_chroma ? (c->avctx->height + 15) >> 4 : (c->avctx->height + 7) >> 3;

    int width = c->avctx->width >> is_chroma;



    init_lengths(c, FFMAX(width, 8), bw);

    for (i = 0; i < BINK_NB_SRC; i++)

        read_bundle(gb, c, i);



    ref_start = c->last.data[plane_idx];

    ref_end   = c->last.data[plane_idx]

                + (bw - 1 + c->last.linesize[plane_idx] * (bh - 1)) * 8;



    for (i = 0; i < 64; i++)

        coordmap[i] = (i & 7) + (i >> 3) * stride;



    for (by = 0; by < bh; by++) {

        if (read_block_types(c->avctx, gb, &c->bundle[BINK_SRC_BLOCK_TYPES]) < 0)

            return -1;

        if (read_block_types(c->avctx, gb, &c->bundle[BINK_SRC_SUB_BLOCK_TYPES]) < 0)

            return -1;

        if (read_colors(gb, &c->bundle[BINK_SRC_COLORS], c) < 0)

            return -1;

        if (read_patterns(c->avctx, gb, &c->bundle[BINK_SRC_PATTERN]) < 0)

            return -1;

        if (read_motion_values(c->avctx, gb, &c->bundle[BINK_SRC_X_OFF]) < 0)

            return -1;

        if (read_motion_values(c->avctx, gb, &c->bundle[BINK_SRC_Y_OFF]) < 0)

            return -1;

        if (read_dcs(c->avctx, gb, &c->bundle[BINK_SRC_INTRA_DC], DC_START_BITS, 0) < 0)

            return -1;

        if (read_dcs(c->avctx, gb, &c->bundle[BINK_SRC_INTER_DC], DC_START_BITS, 1) < 0)

            return -1;

        if (read_runs(c->avctx, gb, &c->bundle[BINK_SRC_RUN]) < 0)

            return -1;



        if (by == bh)

            break;

        dst  = c->pic.data[plane_idx]  + 8*by*stride;

        prev = c->last.data[plane_idx] + 8*by*stride;

        for (bx = 0; bx < bw; bx++, dst += 8, prev += 8) {

            blk = get_value(c, BINK_SRC_BLOCK_TYPES);

            // 16x16 block type on odd line means part of the already decoded block, so skip it

            if ((by & 1) && blk == SCALED_BLOCK) {

                bx++;

                dst  += 8;

                prev += 8;

                continue;

            }

            switch (blk) {

            case SKIP_BLOCK:

                c->dsp.put_pixels_tab[1][0](dst, prev, stride, 8);

                break;

            case SCALED_BLOCK:

                blk = get_value(c, BINK_SRC_SUB_BLOCK_TYPES);

                switch (blk) {

                case RUN_BLOCK:

                    scan = bink_patterns[get_bits(gb, 4)];

                    i = 0;

                    do {

                        int run = get_value(c, BINK_SRC_RUN) + 1;



                        i += run;

                        if (i > 64) {

                            av_log(c->avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                            return -1;

                        }

                        if (get_bits1(gb)) {

                            v = get_value(c, BINK_SRC_COLORS);

                            for (j = 0; j < run; j++)

                                ublock[*scan++] = v;

                        } else {

                            for (j = 0; j < run; j++)

                                ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                        }

                    } while (i < 63);

                    if (i == 63)

                        ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                    break;

                case INTRA_BLOCK:

                    memset(dctblock, 0, sizeof(*dctblock) * 64);

                    dctblock[0] = get_value(c, BINK_SRC_INTRA_DC);

                    read_dct_coeffs(gb, dctblock, bink_scan, bink_intra_quant, -1);

                    c->bdsp.idct_put(ublock, 8, dctblock);

                    break;

                case FILL_BLOCK:

                    v = get_value(c, BINK_SRC_COLORS);

                    c->dsp.fill_block_tab[0](dst, v, stride, 16);

                    break;

                case PATTERN_BLOCK:

                    for (i = 0; i < 2; i++)

                        col[i] = get_value(c, BINK_SRC_COLORS);

                    for (j = 0; j < 8; j++) {

                        v = get_value(c, BINK_SRC_PATTERN);

                        for (i = 0; i < 8; i++, v >>= 1)

                            ublock[i + j*8] = col[v & 1];

                    }

                    break;

                case RAW_BLOCK:

                    for (j = 0; j < 8; j++)

                        for (i = 0; i < 8; i++)

                            ublock[i + j*8] = get_value(c, BINK_SRC_COLORS);

                    break;

                default:

                    av_log(c->avctx, AV_LOG_ERROR, "Incorrect 16x16 block type %d\n", blk);

                    return -1;

                }

                if (blk != FILL_BLOCK)

                c->bdsp.scale_block(ublock, dst, stride);

                bx++;

                dst  += 8;

                prev += 8;

                break;

            case MOTION_BLOCK:

                xoff = get_value(c, BINK_SRC_X_OFF);

                yoff = get_value(c, BINK_SRC_Y_OFF);

                ref = prev + xoff + yoff * stride;

                if (ref < ref_start || ref > ref_end) {

                    av_log(c->avctx, AV_LOG_ERROR, "Copy out of bounds @%d, %d\n",

                           bx*8 + xoff, by*8 + yoff);

                    return -1;

                }

                c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                break;

            case RUN_BLOCK:

                scan = bink_patterns[get_bits(gb, 4)];

                i = 0;

                do {

                    int run = get_value(c, BINK_SRC_RUN) + 1;



                    i += run;

                    if (i > 64) {

                        av_log(c->avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                        return -1;

                    }

                    if (get_bits1(gb)) {

                        v = get_value(c, BINK_SRC_COLORS);

                        for (j = 0; j < run; j++)

                            dst[coordmap[*scan++]] = v;

                    } else {

                        for (j = 0; j < run; j++)

                            dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                    }

                } while (i < 63);

                if (i == 63)

                    dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                break;

            case RESIDUE_BLOCK:

                xoff = get_value(c, BINK_SRC_X_OFF);

                yoff = get_value(c, BINK_SRC_Y_OFF);

                ref = prev + xoff + yoff * stride;

                if (ref < ref_start || ref > ref_end) {

                    av_log(c->avctx, AV_LOG_ERROR, "Copy out of bounds @%d, %d\n",

                           bx*8 + xoff, by*8 + yoff);

                    return -1;

                }

                c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                c->dsp.clear_block(block);

                v = get_bits(gb, 7);

                read_residue(gb, block, v);

                c->dsp.add_pixels8(dst, block, stride);

                break;

            case INTRA_BLOCK:

                memset(dctblock, 0, sizeof(*dctblock) * 64);

                dctblock[0] = get_value(c, BINK_SRC_INTRA_DC);

                read_dct_coeffs(gb, dctblock, bink_scan, bink_intra_quant, -1);

                c->bdsp.idct_put(dst, stride, dctblock);

                break;

            case FILL_BLOCK:

                v = get_value(c, BINK_SRC_COLORS);

                c->dsp.fill_block_tab[1](dst, v, stride, 8);

                break;

            case INTER_BLOCK:

                xoff = get_value(c, BINK_SRC_X_OFF);

                yoff = get_value(c, BINK_SRC_Y_OFF);

                ref = prev + xoff + yoff * stride;

                c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                memset(dctblock, 0, sizeof(*dctblock) * 64);

                dctblock[0] = get_value(c, BINK_SRC_INTER_DC);

                read_dct_coeffs(gb, dctblock, bink_scan, bink_inter_quant, -1);

                c->bdsp.idct_add(dst, stride, dctblock);

                break;

            case PATTERN_BLOCK:

                for (i = 0; i < 2; i++)

                    col[i] = get_value(c, BINK_SRC_COLORS);

                for (i = 0; i < 8; i++) {

                    v = get_value(c, BINK_SRC_PATTERN);

                    for (j = 0; j < 8; j++, v >>= 1)

                        dst[i*stride + j] = col[v & 1];

                }

                break;

            case RAW_BLOCK:

                for (i = 0; i < 8; i++)

                    memcpy(dst + i*stride, c->bundle[BINK_SRC_COLORS].cur_ptr + i*8, 8);

                c->bundle[BINK_SRC_COLORS].cur_ptr += 64;

                break;

            default:

                av_log(c->avctx, AV_LOG_ERROR, "Unknown block type %d\n", blk);

                return -1;

            }

        }

    }

    if (get_bits_count(gb) & 0x1F) //next plane data starts at 32-bit boundary

        skip_bits_long(gb, 32 - (get_bits_count(gb) & 0x1F));



    return 0;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *data_size, AVPacket *pkt)

{

    BinkContext * const c = avctx->priv_data;

    GetBitContext gb;

    int blk;

    int i, j, plane, plane_idx, bx, by;

    uint8_t *dst, *prev, *ref, *ref_start, *ref_end;

    int v, col[2];

    const uint8_t *scan;

    int xoff, yoff;

    DECLARE_ALIGNED_16(DCTELEM, block[64]);

    DECLARE_ALIGNED_16(uint8_t, ublock[64]);

    int coordmap[64];



    if(c->pic.data[0])

        avctx->release_buffer(avctx, &c->pic);



    if(avctx->get_buffer(avctx, &c->pic) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    init_get_bits(&gb, pkt->data, pkt->size*8);

    if (c->version >= 'i')

        skip_bits_long(&gb, 32);



    for (plane = 0; plane < 3; plane++) {

        const int stride = c->pic.linesize[plane];

        int bw = plane ? (avctx->width  + 15) >> 4 : (avctx->width  + 7) >> 3;

        int bh = plane ? (avctx->height + 15) >> 4 : (avctx->height + 7) >> 3;

        int width = avctx->width >> !!plane;



        init_lengths(c, FFMAX(width, 8), bw);

        for (i = 0; i < BINK_NB_SRC; i++)

            read_bundle(&gb, c, i);



        plane_idx = (!plane || !c->swap_planes) ? plane : (plane ^ 3);

        ref_start = c->last.data[plane_idx];

        ref_end   = c->last.data[plane_idx]

                    + (bw - 1 + c->last.linesize[plane_idx] * (bh - 1)) * 8;



        for (i = 0; i < 64; i++)

            coordmap[i] = (i & 7) + (i >> 3) * stride;



        for (by = 0; by < bh; by++) {

            if (read_block_types(avctx, &gb, &c->bundle[BINK_SRC_BLOCK_TYPES]) < 0)

                return -1;

            if (read_block_types(avctx, &gb, &c->bundle[BINK_SRC_SUB_BLOCK_TYPES]) < 0)

                return -1;

            if (read_colors(&gb, &c->bundle[BINK_SRC_COLORS], c) < 0)

                return -1;

            if (read_patterns(avctx, &gb, &c->bundle[BINK_SRC_PATTERN]) < 0)

                return -1;

            if (read_motion_values(avctx, &gb, &c->bundle[BINK_SRC_X_OFF]) < 0)

                return -1;

            if (read_motion_values(avctx, &gb, &c->bundle[BINK_SRC_Y_OFF]) < 0)

                return -1;

            if (read_dcs(avctx, &gb, &c->bundle[BINK_SRC_INTRA_DC], DC_START_BITS, 0) < 0)

                return -1;

            if (read_dcs(avctx, &gb, &c->bundle[BINK_SRC_INTER_DC], DC_START_BITS, 1) < 0)

                return -1;

            if (read_runs(avctx, &gb, &c->bundle[BINK_SRC_RUN]) < 0)

                return -1;



            if (by == bh)

                break;

            dst  = c->pic.data[plane_idx]  + 8*by*stride;

            prev = c->last.data[plane_idx] + 8*by*stride;

            for (bx = 0; bx < bw; bx++, dst += 8, prev += 8) {

                blk = get_value(c, BINK_SRC_BLOCK_TYPES);

                // 16x16 block type on odd line means part of the already decoded block, so skip it

                if ((by & 1) && blk == SCALED_BLOCK) {

                    bx++;

                    dst  += 8;

                    prev += 8;

                    continue;

                }

                switch (blk) {

                case SKIP_BLOCK:

                    c->dsp.put_pixels_tab[1][0](dst, prev, stride, 8);

                    break;

                case SCALED_BLOCK:

                    blk = get_value(c, BINK_SRC_SUB_BLOCK_TYPES);

                    switch (blk) {

                    case RUN_BLOCK:

                        scan = bink_patterns[get_bits(&gb, 4)];

                        i = 0;

                        do {

                            int run = get_value(c, BINK_SRC_RUN) + 1;



                            i += run;

                            if (i > 64) {

                                av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                                return -1;

                            }

                            if (get_bits1(&gb)) {

                                v = get_value(c, BINK_SRC_COLORS);

                                for (j = 0; j < run; j++)

                                    ublock[*scan++] = v;

                            } else {

                                for (j = 0; j < run; j++)

                                    ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                            }

                        } while (i < 63);

                        if (i == 63)

                            ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                        break;

                    case INTRA_BLOCK:

                        c->dsp.clear_block(block);

                        block[0] = get_value(c, BINK_SRC_INTRA_DC);

                        read_dct_coeffs(&gb, block, c->scantable.permutated, 1);

                        c->dsp.idct(block);

                        c->dsp.put_pixels_nonclamped(block, ublock, 8);

                        break;

                    case FILL_BLOCK:

                        v = get_value(c, BINK_SRC_COLORS);

                        c->dsp.fill_block_tab[0](dst, v, stride, 16);

                        break;

                    case PATTERN_BLOCK:

                        for (i = 0; i < 2; i++)

                            col[i] = get_value(c, BINK_SRC_COLORS);

                        for (j = 0; j < 8; j++) {

                            v = get_value(c, BINK_SRC_PATTERN);

                            for (i = 0; i < 8; i++, v >>= 1)

                                ublock[i + j*8] = col[v & 1];

                        }

                        break;

                    case RAW_BLOCK:

                        for (j = 0; j < 8; j++)

                            for (i = 0; i < 8; i++)

                                ublock[i + j*8] = get_value(c, BINK_SRC_COLORS);

                        break;

                    default:

                        av_log(avctx, AV_LOG_ERROR, "Incorrect 16x16 block type %d\n", blk);

                        return -1;

                    }

                    if (blk != FILL_BLOCK)

                        c->dsp.scale_block(ublock, dst, stride);

                    bx++;

                    dst  += 8;

                    prev += 8;

                    break;

                case MOTION_BLOCK:

                    xoff = get_value(c, BINK_SRC_X_OFF);

                    yoff = get_value(c, BINK_SRC_Y_OFF);

                    ref = prev + xoff + yoff * stride;

                    if (ref < ref_start || ref > ref_end) {

                        av_log(avctx, AV_LOG_ERROR, "Copy out of bounds @%d, %d\n",

                               bx*8 + xoff, by*8 + yoff);

                        return -1;

                    }

                    c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                    break;

                case RUN_BLOCK:

                    scan = bink_patterns[get_bits(&gb, 4)];

                    i = 0;

                    do {

                        int run = get_value(c, BINK_SRC_RUN) + 1;



                        i += run;

                        if (i > 64) {

                            av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                            return -1;

                        }

                        if (get_bits1(&gb)) {

                            v = get_value(c, BINK_SRC_COLORS);

                            for (j = 0; j < run; j++)

                                dst[coordmap[*scan++]] = v;

                        } else {

                            for (j = 0; j < run; j++)

                                dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                        }

                    } while (i < 63);

                    if (i == 63)

                        dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                    break;

                case RESIDUE_BLOCK:

                    xoff = get_value(c, BINK_SRC_X_OFF);

                    yoff = get_value(c, BINK_SRC_Y_OFF);

                    ref = prev + xoff + yoff * stride;

                    if (ref < ref_start || ref > ref_end) {

                        av_log(avctx, AV_LOG_ERROR, "Copy out of bounds @%d, %d\n",

                               bx*8 + xoff, by*8 + yoff);

                        return -1;

                    }

                    c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                    c->dsp.clear_block(block);

                    v = get_bits(&gb, 7);

                    read_residue(&gb, block, v);

                    c->dsp.add_pixels8(dst, block, stride);

                    break;

                case INTRA_BLOCK:

                    c->dsp.clear_block(block);

                    block[0] = get_value(c, BINK_SRC_INTRA_DC);

                    read_dct_coeffs(&gb, block, c->scantable.permutated, 1);

                    c->dsp.idct_put(dst, stride, block);

                    break;

                case FILL_BLOCK:

                    v = get_value(c, BINK_SRC_COLORS);

                    c->dsp.fill_block_tab[1](dst, v, stride, 8);

                    break;

                case INTER_BLOCK:

                    xoff = get_value(c, BINK_SRC_X_OFF);

                    yoff = get_value(c, BINK_SRC_Y_OFF);

                    ref = prev + xoff + yoff * stride;

                    c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                    c->dsp.clear_block(block);

                    block[0] = get_value(c, BINK_SRC_INTER_DC);

                    read_dct_coeffs(&gb, block, c->scantable.permutated, 0);

                    c->dsp.idct_add(dst, stride, block);

                    break;

                case PATTERN_BLOCK:

                    for (i = 0; i < 2; i++)

                        col[i] = get_value(c, BINK_SRC_COLORS);

                    for (i = 0; i < 8; i++) {

                        v = get_value(c, BINK_SRC_PATTERN);

                        for (j = 0; j < 8; j++, v >>= 1)

                            dst[i*stride + j] = col[v & 1];

                    }

                    break;

                case RAW_BLOCK:

                    for (i = 0; i < 8; i++)

                        memcpy(dst + i*stride, c->bundle[BINK_SRC_COLORS].cur_ptr + i*8, 8);

                    c->bundle[BINK_SRC_COLORS].cur_ptr += 64;

                    break;

                default:

                    av_log(avctx, AV_LOG_ERROR, "Unknown block type %d\n", blk);

                    return -1;

                }

            }

        }

        if (get_bits_count(&gb) & 0x1F) //next plane data starts at 32-bit boundary

            skip_bits_long(&gb, 32 - (get_bits_count(&gb) & 0x1F));

    }

    emms_c();



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = c->pic;



    FFSWAP(AVFrame, c->pic, c->last);



    /* always report that the buffer was completely consumed */

    return pkt->size;

}

static int bink_decode_plane(BinkContext *c, AVFrame *frame, BitstreamContext *bc,

                             int plane_idx, int is_chroma)

{

    int blk, ret;

    int i, j, bx, by;

    uint8_t *dst, *prev, *ref_start, *ref_end;

    int v, col[2];

    const uint8_t *scan;

    LOCAL_ALIGNED_16(int16_t, block, [64]);

    LOCAL_ALIGNED_16(uint8_t, ublock, [64]);

    LOCAL_ALIGNED_16(int32_t, dctblock, [64]);

    int coordmap[64];



    const int stride = frame->linesize[plane_idx];

    int bw = is_chroma ? (c->avctx->width  + 15) >> 4 : (c->avctx->width  + 7) >> 3;

    int bh = is_chroma ? (c->avctx->height + 15) >> 4 : (c->avctx->height + 7) >> 3;

    int width = c->avctx->width >> is_chroma;



    init_lengths(c, FFMAX(width, 8), bw);

    for (i = 0; i < BINK_NB_SRC; i++)

        read_bundle(bc, c, i);



    ref_start = c->last->data[plane_idx] ? c->last->data[plane_idx]

                                         : frame->data[plane_idx];

    ref_end   = ref_start

                + (bw - 1 + c->last->linesize[plane_idx] * (bh - 1)) * 8;



    for (i = 0; i < 64; i++)

        coordmap[i] = (i & 7) + (i >> 3) * stride;



    for (by = 0; by < bh; by++) {

        if ((ret = read_block_types(c->avctx, bc, &c->bundle[BINK_SRC_BLOCK_TYPES])) < 0)

            return ret;

        if ((ret = read_block_types(c->avctx, bc, &c->bundle[BINK_SRC_SUB_BLOCK_TYPES])) < 0)

            return ret;

        if ((ret = read_colors(bc, &c->bundle[BINK_SRC_COLORS], c)) < 0)

            return ret;

        if ((ret = read_patterns(c->avctx, bc, &c->bundle[BINK_SRC_PATTERN])) < 0)

            return ret;

        if ((ret = read_motion_values(c->avctx, bc, &c->bundle[BINK_SRC_X_OFF])) < 0)

            return ret;

        if ((ret = read_motion_values(c->avctx, bc, &c->bundle[BINK_SRC_Y_OFF])) < 0)

            return ret;

        if ((ret = read_dcs(c->avctx, bc, &c->bundle[BINK_SRC_INTRA_DC], DC_START_BITS, 0)) < 0)

            return ret;

        if ((ret = read_dcs(c->avctx, bc, &c->bundle[BINK_SRC_INTER_DC], DC_START_BITS, 1)) < 0)

            return ret;

        if ((ret = read_runs(c->avctx, bc, &c->bundle[BINK_SRC_RUN])) < 0)

            return ret;



        if (by == bh)

            break;

        dst  = frame->data[plane_idx]  + 8*by*stride;

        prev = (c->last->data[plane_idx] ? c->last->data[plane_idx]

                                         : frame->data[plane_idx]) + 8*by*stride;

        for (bx = 0; bx < bw; bx++, dst += 8, prev += 8) {

            blk = get_value(c, BINK_SRC_BLOCK_TYPES);

            // 16x16 block type on odd line means part of the already decoded block, so skip it

            if ((by & 1) && blk == SCALED_BLOCK) {

                bx++;

                dst  += 8;

                prev += 8;

                continue;

            }

            switch (blk) {

            case SKIP_BLOCK:

                c->hdsp.put_pixels_tab[1][0](dst, prev, stride, 8);

                break;

            case SCALED_BLOCK:

                blk = get_value(c, BINK_SRC_SUB_BLOCK_TYPES);

                switch (blk) {

                case RUN_BLOCK:

                    scan = bink_patterns[bitstream_read(bc, 4)];

                    i = 0;

                    do {

                        int run = get_value(c, BINK_SRC_RUN) + 1;



                        i += run;

                        if (i > 64) {

                            av_log(c->avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                            return AVERROR_INVALIDDATA;

                        }

                        if (bitstream_read_bit(bc)) {

                            v = get_value(c, BINK_SRC_COLORS);

                            for (j = 0; j < run; j++)

                                ublock[*scan++] = v;

                        } else {

                            for (j = 0; j < run; j++)

                                ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                        }

                    } while (i < 63);

                    if (i == 63)

                        ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                    break;

                case INTRA_BLOCK:

                    memset(dctblock, 0, sizeof(*dctblock) * 64);

                    dctblock[0] = get_value(c, BINK_SRC_INTRA_DC);

                    read_dct_coeffs(bc, dctblock, bink_scan, bink_intra_quant, -1);

                    c->binkdsp.idct_put(ublock, 8, dctblock);

                    break;

                case FILL_BLOCK:

                    v = get_value(c, BINK_SRC_COLORS);

                    c->bdsp.fill_block_tab[0](dst, v, stride, 16);

                    break;

                case PATTERN_BLOCK:

                    for (i = 0; i < 2; i++)

                        col[i] = get_value(c, BINK_SRC_COLORS);

                    for (j = 0; j < 8; j++) {

                        v = get_value(c, BINK_SRC_PATTERN);

                        for (i = 0; i < 8; i++, v >>= 1)

                            ublock[i + j*8] = col[v & 1];

                    }

                    break;

                case RAW_BLOCK:

                    for (j = 0; j < 8; j++)

                        for (i = 0; i < 8; i++)

                            ublock[i + j*8] = get_value(c, BINK_SRC_COLORS);

                    break;

                default:

                    av_log(c->avctx, AV_LOG_ERROR, "Incorrect 16x16 block type %d\n", blk);

                    return AVERROR_INVALIDDATA;

                }

                if (blk != FILL_BLOCK)

                c->binkdsp.scale_block(ublock, dst, stride);

                bx++;

                dst  += 8;

                prev += 8;

                break;

            case MOTION_BLOCK:

                ret = bink_put_pixels(c, dst, prev, stride,

                                      ref_start, ref_end);

                if (ret < 0)

                    return ret;

                break;

            case RUN_BLOCK:

                scan = bink_patterns[bitstream_read(bc, 4)];

                i = 0;

                do {

                    int run = get_value(c, BINK_SRC_RUN) + 1;



                    i += run;

                    if (i > 64) {

                        av_log(c->avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                        return AVERROR_INVALIDDATA;

                    }

                    if (bitstream_read_bit(bc)) {

                        v = get_value(c, BINK_SRC_COLORS);

                        for (j = 0; j < run; j++)

                            dst[coordmap[*scan++]] = v;

                    } else {

                        for (j = 0; j < run; j++)

                            dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                    }

                } while (i < 63);

                if (i == 63)

                    dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                break;

            case RESIDUE_BLOCK:

                ret = bink_put_pixels(c, dst, prev, stride,

                                      ref_start, ref_end);

                if (ret < 0)

                    return ret;

                c->bdsp.clear_block(block);

                v = bitstream_read(bc, 7);

                read_residue(bc, block, v);

                c->binkdsp.add_pixels8(dst, block, stride);

                break;

            case INTRA_BLOCK:

                memset(dctblock, 0, sizeof(*dctblock) * 64);

                dctblock[0] = get_value(c, BINK_SRC_INTRA_DC);

                read_dct_coeffs(bc, dctblock, bink_scan, bink_intra_quant, -1);

                c->binkdsp.idct_put(dst, stride, dctblock);

                break;

            case FILL_BLOCK:

                v = get_value(c, BINK_SRC_COLORS);

                c->bdsp.fill_block_tab[1](dst, v, stride, 8);

                break;

            case INTER_BLOCK:

                ret = bink_put_pixels(c, dst, prev, stride,

                                      ref_start, ref_end);

                if (ret < 0)

                    return ret;

                memset(dctblock, 0, sizeof(*dctblock) * 64);

                dctblock[0] = get_value(c, BINK_SRC_INTER_DC);

                read_dct_coeffs(bc, dctblock, bink_scan, bink_inter_quant, -1);

                c->binkdsp.idct_add(dst, stride, dctblock);

                break;

            case PATTERN_BLOCK:

                for (i = 0; i < 2; i++)

                    col[i] = get_value(c, BINK_SRC_COLORS);

                for (i = 0; i < 8; i++) {

                    v = get_value(c, BINK_SRC_PATTERN);

                    for (j = 0; j < 8; j++, v >>= 1)

                        dst[i*stride + j] = col[v & 1];

                }

                break;

            case RAW_BLOCK:

                for (i = 0; i < 8; i++)

                    memcpy(dst + i*stride, c->bundle[BINK_SRC_COLORS].cur_ptr + i*8, 8);

                c->bundle[BINK_SRC_COLORS].cur_ptr += 64;

                break;

            default:

                av_log(c->avctx, AV_LOG_ERROR, "Unknown block type %d\n", blk);

                return AVERROR_INVALIDDATA;

            }

        }

    }

    if (bitstream_tell(bc) & 0x1F) // next plane data starts at 32-bit boundary

        bitstream_skip(bc, 32 - (bitstream_tell(bc) & 0x1F));



    return 0;

}

static int targa_decode_rle(AVCodecContext *avctx, TargaContext *s, const uint8_t *src, int src_size, uint8_t *dst, int w, int h, int stride, int bpp)

{

    int i, x, y;

    int depth = (bpp + 1) >> 3;

    int type, count;

    int diff;

    const uint8_t *src_end = src + src_size;



    diff = stride - w * depth;

    x = y = 0;

    while(y < h){

        CHECK_BUFFER_SIZE(src, src_end, 1, "image type");

        type = *src++;

        count = (type & 0x7F) + 1;

        type &= 0x80;

        if((x + count > w) && (x + count + 1 > (h - y) * w)){

            av_log(avctx, AV_LOG_ERROR, "Packet went out of bounds: position (%i,%i) size %i\n", x, y, count);

            return -1;

        }

        if(type){

            CHECK_BUFFER_SIZE(src, src_end, depth, "image data");

        }else{

            CHECK_BUFFER_SIZE(src, src_end, count * depth, "image data");

        }

        for(i = 0; i < count; i++){

            switch(depth){

            case 1:

                *dst = *src;

                break;

            case 2:

                AV_WN16A(dst, AV_RN16A(src));

                break;

            case 3:

                dst[0] = src[0];

                dst[1] = src[1];

                dst[2] = src[2];

                break;

            case 4:

                AV_WN32A(dst, AV_RN32A(src));

                break;

            }

            dst += depth;

            if(!type)

                src += depth;



            x++;

            if(x == w){

                x = 0;

                y++;

                dst += diff;

            }

        }

        if(type)

            src += depth;

    }

    return src_size;

}

static int get_int32_le(QEMUFile *f, void *pv, size_t size)

{

    int32_t *cur = pv;

    int32_t loaded;

    qemu_get_sbe32s(f, &loaded);



    if (loaded >= 0 && loaded <= *cur) {

        *cur = loaded;

        return 0;

    }

    return -EINVAL;

}

static int get_bitmap(QEMUFile *f, void *pv, size_t size)

{

    unsigned long *bmp = pv;

    int i, idx = 0;

    for (i = 0; i < BITS_TO_U64S(size); i++) {

        uint64_t w = qemu_get_be64(f);

        bmp[idx++] = w;

        if (sizeof(unsigned long) == 4 && idx < BITS_TO_LONGS(size)) {

            bmp[idx++] = w >> 32;

        }

    }

    return 0;

}

static int get_uint64_as_uint32(QEMUFile *f, void *pv, size_t size,

                                VMStateField *field)

{

    uint64_t *v = pv;

    *v = qemu_get_be32(f);

    return 0;

}

static int get_pci_irq_state(QEMUFile *f, void *pv, size_t size)

{

    PCIDevice *s = container_of(pv, PCIDevice, config);

    uint32_t irq_state[PCI_NUM_PINS];

    int i;

    for (i = 0; i < PCI_NUM_PINS; ++i) {

        irq_state[i] = qemu_get_be32(f);

        if (irq_state[i] != 0x1 && irq_state[i] != 0) {

            fprintf(stderr, "irq state %d: must be 0 or 1.\n",

                    irq_state[i]);

            return -EINVAL;

        }

    }



    for (i = 0; i < PCI_NUM_PINS; ++i) {

        pci_set_irq_state(s, i, irq_state[i]);

    }



    return 0;

}

static int get_phys_addr_mpu(CPUARMState *env, uint32_t address,

                             int access_type, int is_user,

                             hwaddr *phys_ptr, int *prot)

{

    int n;

    uint32_t mask;

    uint32_t base;



    *phys_ptr = address;

    for (n = 7; n >= 0; n--) {

	base = env->cp15.c6_region[n];

	if ((base & 1) == 0)

	    continue;

	mask = 1 << ((base >> 1) & 0x1f);

	/* Keep this shift separate from the above to avoid an

	   (undefined) << 32.  */

	mask = (mask << 1) - 1;

	if (((base ^ address) & ~mask) == 0)

	    break;

    }

    if (n < 0)

	return 2;



    if (access_type == 2) {

	mask = env->cp15.c5_insn;

    } else {

	mask = env->cp15.c5_data;

    }

    mask = (mask >> (n * 4)) & 0xf;

    switch (mask) {

    case 0:

	return 1;

    case 1:

	if (is_user)

	  return 1;

	*prot = PAGE_READ | PAGE_WRITE;

	break;

    case 2:

	*prot = PAGE_READ;

	if (!is_user)

	    *prot |= PAGE_WRITE;

	break;

    case 3:

	*prot = PAGE_READ | PAGE_WRITE;

	break;

    case 5:

	if (is_user)

	    return 1;

	*prot = PAGE_READ;

	break;

    case 6:

	*prot = PAGE_READ;

	break;

    default:

	/* Bad permission.  */

	return 1;

    }

    *prot |= PAGE_EXEC;

    return 0;

}

static int aiff_probe(AVProbeData *p)

{

    /* check file header */

    if (p->buf_size < 16)

        return 0;

    if (p->buf[0] == 'F' && p->buf[1] == 'O' &&

        p->buf[2] == 'R' && p->buf[3] == 'M' &&

        p->buf[8] == 'A' && p->buf[9] == 'I' &&

        p->buf[10] == 'F' && (p->buf[11] == 'F' || p->buf[11] == 'C'))

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static inline int check_ap(CPUARMState *env, int ap, int domain_prot,

                           int access_type, int is_user)

{

  int prot_ro;



  if (domain_prot == 3) {

    return PAGE_READ | PAGE_WRITE;

  }



  if (access_type == 1)

      prot_ro = 0;

  else

      prot_ro = PAGE_READ;



  switch (ap) {

  case 0:

      if (access_type == 1)

          return 0;

      switch ((env->cp15.c1_sys >> 8) & 3) {

      case 1:

          return is_user ? 0 : PAGE_READ;

      case 2:

          return PAGE_READ;

      default:

          return 0;

      }

  case 1:

      return is_user ? 0 : PAGE_READ | PAGE_WRITE;

  case 2:

      if (is_user)

          return prot_ro;

      else

          return PAGE_READ | PAGE_WRITE;

  case 3:

      return PAGE_READ | PAGE_WRITE;

  case 4: /* Reserved.  */

      return 0;

  case 5:

      return is_user ? 0 : prot_ro;

  case 6:

      return prot_ro;

  case 7:

      if (!arm_feature (env, ARM_FEATURE_V6K))

          return 0;

      return prot_ro;

  default:

      abort();

  }

}

static int mmf_probe(AVProbeData *p)

{

    /* check file header */

    if (p->buf_size <= 32)

        return 0;

    if (p->buf[0] == 'M' && p->buf[1] == 'M' &&

        p->buf[2] == 'M' && p->buf[3] == 'D' &&

        p->buf[8] == 'C' && p->buf[9] == 'N' &&

        p->buf[10] == 'T' && p->buf[11] == 'I')

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

struct omap_gpmc_s *omap_gpmc_init(target_phys_addr_t base, qemu_irq irq)

{

    struct omap_gpmc_s *s = (struct omap_gpmc_s *)

            g_malloc0(sizeof(struct omap_gpmc_s));



    memory_region_init_io(&s->iomem, &omap_gpmc_ops, s, "omap-gpmc", 0x1000);

    memory_region_add_subregion(get_system_memory(), base, &s->iomem);




    omap_gpmc_reset(s);



    return s;

}

struct omap_sdrc_s *omap_sdrc_init(MemoryRegion *sysmem,

                                   hwaddr base)

{

    struct omap_sdrc_s *s = (struct omap_sdrc_s *)

            g_malloc0(sizeof(struct omap_sdrc_s));



    omap_sdrc_reset(s);



    memory_region_init_io(&s->iomem, NULL, &omap_sdrc_ops, s, "omap.sdrc", 0x1000);

    memory_region_add_subregion(sysmem, base, &s->iomem);



    return s;

}

static struct omap_rtc_s *omap_rtc_init(target_phys_addr_t base,

                qemu_irq *irq, omap_clk clk)

{

    int iomemtype;

    struct omap_rtc_s *s = (struct omap_rtc_s *)

            qemu_mallocz(sizeof(struct omap_rtc_s));



    s->irq = irq[0];

    s->alarm = irq[1];

    s->clk = qemu_new_timer(rt_clock, omap_rtc_tick, s);



    omap_rtc_reset(s);



    iomemtype = cpu_register_io_memory(omap_rtc_readfn,

                    omap_rtc_writefn, s, DEVICE_NATIVE_ENDIAN);

    cpu_register_physical_memory(base, 0x800, iomemtype);



    return s;

}

static struct omap_uwire_s *omap_uwire_init(MemoryRegion *system_memory,

                                            target_phys_addr_t base,

                                            qemu_irq txirq, qemu_irq rxirq,

                                            qemu_irq dma,

                                            omap_clk clk)

{

    struct omap_uwire_s *s = (struct omap_uwire_s *)

            g_malloc0(sizeof(struct omap_uwire_s));



    s->txirq = txirq;

    s->rxirq = rxirq;

    s->txdrq = dma;

    omap_uwire_reset(s);



    memory_region_init_io(&s->iomem, &omap_uwire_ops, s, "omap-uwire", 0x800);

