static inline direntry_t* create_short_and_long_name(BDRVVVFATState* s,

	unsigned int directory_start, const char* filename, int is_dot)

{

    int i,j,long_index=s->directory.next;

    direntry_t* entry = NULL;

    direntry_t* entry_long = NULL;



    if(is_dot) {

	entry=array_get_next(&(s->directory));

	memset(entry->name,0x20,11);

	memcpy(entry->name,filename,strlen(filename));

	return entry;

    }



    entry_long=create_long_filename(s,filename);



    i = strlen(filename);

    for(j = i - 1; j>0  && filename[j]!='.';j--);

    if (j > 0)

	i = (j > 8 ? 8 : j);

    else if (i > 8)

	i = 8;



    entry=array_get_next(&(s->directory));

    memset(entry->name,0x20,11);

    memcpy(entry->name, filename, i);



    if(j > 0)

	for (i = 0; i < 3 && filename[j+1+i]; i++)

	    entry->extension[i] = filename[j+1+i];



    /* upcase & remove unwanted characters */

    for(i=10;i>=0;i--) {

	if(i==10 || i==7) for(;i>0 && entry->name[i]==' ';i--);

	if(entry->name[i]<=' ' || entry->name[i]>0x7f

		|| strchr(".*?<>|\":/\\[];,+='",entry->name[i]))

	    entry->name[i]='_';

        else if(entry->name[i]>='a' && entry->name[i]<='z')

            entry->name[i]+='A'-'a';

    }



    /* mangle duplicates */

    while(1) {

	direntry_t* entry1=array_get(&(s->directory),directory_start);

	int j;



	for(;entry1<entry;entry1++)

	    if(!is_long_name(entry1) && !memcmp(entry1->name,entry->name,11))

		break; /* found dupe */

	if(entry1==entry) /* no dupe found */

	    break;



	/* use all 8 characters of name */

	if(entry->name[7]==' ') {

	    int j;

	    for(j=6;j>0 && entry->name[j]==' ';j--)

		entry->name[j]='~';

	}



	/* increment number */

	for(j=7;j>0 && entry->name[j]=='9';j--)

	    entry->name[j]='0';

	if(j>0) {

	    if(entry->name[j]<'0' || entry->name[j]>'9')

	        entry->name[j]='0';

	    else

	        entry->name[j]++;

	}

    }



    /* calculate checksum; propagate to long name */

    if(entry_long) {

        uint8_t chksum=fat_chksum(entry);



	/* calculate anew, because realloc could have taken place */

	entry_long=array_get(&(s->directory),long_index);

	while(entry_long<entry && is_long_name(entry_long)) {

	    entry_long->reserved[1]=chksum;

	    entry_long++;

	}

    }



    return entry;

}

static int webvtt_event_to_ass(AVBPrint *buf, const char *p)

{

    int i, again, skip = 0;



    while (*p) {



        for (i = 0; i < FF_ARRAY_ELEMS(webvtt_tag_replace); i++) {

            const char *from = webvtt_tag_replace[i].from;

            const size_t len = strlen(from);

            if (!strncmp(p, from, len)) {

                av_bprintf(buf, "%s", webvtt_tag_replace[i].to);

                p += len;

                again = 1;

                break;

            }

        }

        if (!*p)

            break;



        if (again) {

            again = 0;

            skip = 0;

            continue;

        }

        if (*p == '<')

            skip = 1;

        else if (*p == '>')

            skip = 0;

        else if (p[0] == '\n' && p[1])

            av_bprintf(buf, "\\N");

        else if (!skip && *p != '\r')

            av_bprint_chars(buf, *p, 1);

        p++;

    }

    return 0;

}

int get_frame_filename(char *buf, int buf_size,

                       const char *path, int number)

{

    const char *p;

    char *q, buf1[20];

    int nd, len, c, percentd_found;



    q = buf;

    p = path;

    percentd_found = 0;

    for(;;) {

        c = *p++;

        if (c == '\0')

            break;

        if (c == '%') {

            do {

                nd = 0;

                while (isdigit(*p)) {

                    nd = nd * 10 + *p++ - '0';

                }

                c = *p++;

                if (c == '*' && nd > 0) {

                    // The nd field is actually the modulus

                    number = number % nd;

                    c = *p++;

                    nd = 0;

                }

            } while (isdigit(c));



            switch(c) {

            case '%':

                goto addchar;

            case 'd':

                if (percentd_found)

                    goto fail;

                percentd_found = 1;

                snprintf(buf1, sizeof(buf1), "%0*d", nd, number);

                len = strlen(buf1);

                if ((q - buf + len) > buf_size - 1)

                    goto fail;

                memcpy(q, buf1, len);

                q += len;

                break;

            default:

                goto fail;

            }

        } else {

        addchar:

            if ((q - buf) < buf_size - 1)

                *q++ = c;

        }

    }

    if (!percentd_found)

        goto fail;

    *q = '\0';

    return 0;

 fail:

    *q = '\0';

    return -1;

}

static void listflags(char *buf, int bufsize, uint32_t fbits,

    const char **featureset, uint32_t flags)

{

    const char **p = &featureset[31];

    char *q, *b, bit;

    int nc;



    b = 4 <= bufsize ? buf + (bufsize -= 3) - 1 : NULL;

    *buf = '\0';

    for (q = buf, bit = 31; fbits && bufsize; --p, fbits &= ~(1 << bit), --bit)

        if (fbits & 1 << bit && (*p || !flags)) {

            if (*p)

                nc = snprintf(q, bufsize, "%s%s", q == buf ? "" : " ", *p);

            else

                nc = snprintf(q, bufsize, "%s[%d]", q == buf ? "" : " ", bit);

            if (bufsize <= nc) {

                if (b)

                    sprintf(b, "...");

                return;

            }

            q += nc;

            bufsize -= nc;

        }

}

static int find_image_range(int *pfirst_index, int *plast_index,

                            const char *path, int start_index, int start_index_range)

{

    char buf[1024];

    int range, last_index, range1, first_index;



    /* find the first image */

    for (first_index = start_index; first_index < start_index + start_index_range; first_index++) {

        if (av_get_frame_filename(buf, sizeof(buf), path, first_index) < 0) {

            *pfirst_index =

            *plast_index  = 1;

            if (avio_check(buf, AVIO_FLAG_READ) > 0)

                return 0;

            return -1;

        }

        if (avio_check(buf, AVIO_FLAG_READ) > 0)

            break;

    }

    if (first_index == start_index + start_index_range)

        goto fail;



    /* find the last image */

    last_index = first_index;

    for (;;) {

        range = 0;

        for (;;) {

            if (!range)

                range1 = 1;

            else

                range1 = 2 * range;

            if (av_get_frame_filename(buf, sizeof(buf), path,

                                      last_index + range1) < 0)

                goto fail;

            if (avio_check(buf, AVIO_FLAG_READ) <= 0)

                break;

            range = range1;

            /* just in case... */

            if (range >= (1 << 30))

                goto fail;

        }

        /* we are sure than image last_index + range exists */

        if (!range)

            break;

        last_index += range;

    }

    *pfirst_index = first_index;

    *plast_index  = last_index;

    return 0;



fail:

    return -1;

}

static void an5206_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    M68kCPU *cpu;

    CPUM68KState *env;

    int kernel_size;

    uint64_t elf_entry;

    hwaddr entry;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    MemoryRegion *sram = g_new(MemoryRegion, 1);



    if (!cpu_model) {

        cpu_model = "m5206";

    }

    cpu = M68K_CPU(cpu_generic_init(TYPE_M68K_CPU, cpu_model));

    if (!cpu) {

        error_report("Unable to find m68k CPU definition");

        exit(1);

    }

    env = &cpu->env;



    /* Initialize CPU registers.  */

    env->vbr = 0;

    /* TODO: allow changing MBAR and RAMBAR.  */

    env->mbar = AN5206_MBAR_ADDR | 1;

    env->rambar0 = AN5206_RAMBAR_ADDR | 1;



    /* DRAM at address zero */

    memory_region_allocate_system_memory(ram, NULL, "an5206.ram", ram_size);

    memory_region_add_subregion(address_space_mem, 0, ram);



    /* Internal SRAM.  */

    memory_region_init_ram(sram, NULL, "an5206.sram", 512, &error_fatal);

    memory_region_add_subregion(address_space_mem, AN5206_RAMBAR_ADDR, sram);



    mcf5206_init(address_space_mem, AN5206_MBAR_ADDR, cpu);



    /* Load kernel.  */

    if (!kernel_filename) {

        if (qtest_enabled()) {

            return;

        }

        fprintf(stderr, "Kernel image must be specified\n");

        exit(1);

    }



    kernel_size = load_elf(kernel_filename, NULL, NULL, &elf_entry,

                           NULL, NULL, 1, EM_68K, 0, 0);

    entry = elf_entry;

    if (kernel_size < 0) {

        kernel_size = load_uimage(kernel_filename, &entry, NULL, NULL,

                                  NULL, NULL);

    }

    if (kernel_size < 0) {

        kernel_size = load_image_targphys(kernel_filename, KERNEL_LOAD_ADDR,

                                          ram_size - KERNEL_LOAD_ADDR);

        entry = KERNEL_LOAD_ADDR;

    }

    if (kernel_size < 0) {

        fprintf(stderr, "qemu: could not load kernel '%s'\n", kernel_filename);

        exit(1);

    }



    env->pc = entry;

}

static void create_cps(MaltaState *s, const char *cpu_model,

                       qemu_irq *cbus_irq, qemu_irq *i8259_irq)

{

    Error *err = NULL;

    s->cps = g_new0(MIPSCPSState, 1);



    object_initialize(s->cps, sizeof(MIPSCPSState), TYPE_MIPS_CPS);

    qdev_set_parent_bus(DEVICE(s->cps), sysbus_get_default());



    object_property_set_str(OBJECT(s->cps), cpu_model, "cpu-model", &err);

    object_property_set_int(OBJECT(s->cps), smp_cpus, "num-vp", &err);

    object_property_set_bool(OBJECT(s->cps), true, "realized", &err);

    if (err != NULL) {

        error_report("%s", error_get_pretty(err));

        exit(1);

    }



    sysbus_mmio_map_overlap(SYS_BUS_DEVICE(s->cps), 0, 0, 1);



    /* FIXME: When GIC is present then we should use GIC's IRQ 3.

       Until then CPS exposes CPU's IRQs thus use the default IRQ 2. */

    *i8259_irq = get_cps_irq(s->cps, 2);

    *cbus_irq = NULL;

}

