static void get_pixels_altivec(int16_t *restrict block, const uint8_t *pixels,

                               ptrdiff_t line_size)

{

    int i;

    vec_u8 perm = vec_lvsl(0, pixels);

    const vec_u8 zero = (const vec_u8)vec_splat_u8(0);



    for (i = 0; i < 8; i++) {

        /* Read potentially unaligned pixels.

         * We're reading 16 pixels, and actually only want 8,

         * but we simply ignore the extras. */

        vec_u8 pixl = vec_ld(0, pixels);

        vec_u8 pixr = vec_ld(7, pixels);

        vec_u8 bytes = vec_perm(pixl, pixr, perm);



        // Convert the bytes into shorts.

        vec_s16 shorts = (vec_s16)vec_mergeh(zero, bytes);



        // Save the data to the block, we assume the block is 16-byte aligned.

        vec_st(shorts, i * 16, (vec_s16 *)block);



        pixels += line_size;

    }

}

void put_no_rnd_h264_chroma_mc8_altivec(uint8_t * dst, uint8_t * src, int stride, int h, int x, int y) {

   DECLARE_ALIGNED_16(signed int, ABCD[4]) =

                        {((8 - x) * (8 - y)),

                             ((x) * (8 - y)),

                         ((8 - x) * (y)),

                             ((x) * (y))};

    register int i;

    vec_u8 fperm;

    const vec_s32 vABCD = vec_ld(0, ABCD);

    const vec_s16 vA = vec_splat((vec_s16)vABCD, 1);

    const vec_s16 vB = vec_splat((vec_s16)vABCD, 3);

    const vec_s16 vC = vec_splat((vec_s16)vABCD, 5);

    const vec_s16 vD = vec_splat((vec_s16)vABCD, 7);

    LOAD_ZERO;

    const vec_s16 v28ss = vec_sub(vec_sl(vec_splat_s16(1),vec_splat_u16(5)),vec_splat_s16(4));

    const vec_u16 v6us  = vec_splat_u16(6);

    register int loadSecond     = (((unsigned long)src) % 16) <= 7 ? 0 : 1;

    register int reallyBadAlign = (((unsigned long)src) % 16) == 15 ? 1 : 0;



    vec_u8 vsrcAuc, vsrcBuc, vsrcperm0, vsrcperm1;

    vec_u8 vsrc0uc, vsrc1uc;

    vec_s16 vsrc0ssH, vsrc1ssH;

    vec_u8 vsrcCuc, vsrc2uc, vsrc3uc;

    vec_s16 vsrc2ssH, vsrc3ssH, psum;

    vec_u8 vdst, ppsum, fsum;



    if (((unsigned long)dst) % 16 == 0) {

        fperm = (vec_u8){0x10, 0x11, 0x12, 0x13,

                           0x14, 0x15, 0x16, 0x17,

                           0x08, 0x09, 0x0A, 0x0B,

                           0x0C, 0x0D, 0x0E, 0x0F};

    } else {

        fperm = (vec_u8){0x00, 0x01, 0x02, 0x03,

                           0x04, 0x05, 0x06, 0x07,

                           0x18, 0x19, 0x1A, 0x1B,

                           0x1C, 0x1D, 0x1E, 0x1F};

    }



    vsrcAuc = vec_ld(0, src);



    if (loadSecond)

        vsrcBuc = vec_ld(16, src);

    vsrcperm0 = vec_lvsl(0, src);

    vsrcperm1 = vec_lvsl(1, src);



    vsrc0uc = vec_perm(vsrcAuc, vsrcBuc, vsrcperm0);

    if (reallyBadAlign)

        vsrc1uc = vsrcBuc;

    else

        vsrc1uc = vec_perm(vsrcAuc, vsrcBuc, vsrcperm1);



    vsrc0ssH = (vec_s16)vec_mergeh(zero_u8v, (vec_u8)vsrc0uc);

    vsrc1ssH = (vec_s16)vec_mergeh(zero_u8v, (vec_u8)vsrc1uc);



    if (!loadSecond) {// -> !reallyBadAlign

        for (i = 0 ; i < h ; i++) {





            vsrcCuc = vec_ld(stride + 0, src);



            vsrc2uc = vec_perm(vsrcCuc, vsrcCuc, vsrcperm0);

            vsrc3uc = vec_perm(vsrcCuc, vsrcCuc, vsrcperm1);



            vsrc2ssH = (vec_s16)vec_mergeh(zero_u8v, (vec_u8)vsrc2uc);

            vsrc3ssH = (vec_s16)vec_mergeh(zero_u8v, (vec_u8)vsrc3uc);



            psum = vec_mladd(vA, vsrc0ssH, vec_splat_s16(0));

            psum = vec_mladd(vB, vsrc1ssH, psum);

            psum = vec_mladd(vC, vsrc2ssH, psum);

            psum = vec_mladd(vD, vsrc3ssH, psum);

            psum = vec_add(v28ss, psum);

            psum = vec_sra(psum, v6us);



            vdst = vec_ld(0, dst);

            ppsum = (vec_u8)vec_packsu(psum, psum);

            fsum = vec_perm(vdst, ppsum, fperm);



            vec_st(fsum, 0, dst);



            vsrc0ssH = vsrc2ssH;

            vsrc1ssH = vsrc3ssH;



            dst += stride;

            src += stride;

        }

    } else {

        vec_u8 vsrcDuc;

        for (i = 0 ; i < h ; i++) {

            vsrcCuc = vec_ld(stride + 0, src);

            vsrcDuc = vec_ld(stride + 16, src);



            vsrc2uc = vec_perm(vsrcCuc, vsrcDuc, vsrcperm0);

            if (reallyBadAlign)

                vsrc3uc = vsrcDuc;

            else

                vsrc3uc = vec_perm(vsrcCuc, vsrcDuc, vsrcperm1);



            vsrc2ssH = (vec_s16)vec_mergeh(zero_u8v, (vec_u8)vsrc2uc);

            vsrc3ssH = (vec_s16)vec_mergeh(zero_u8v, (vec_u8)vsrc3uc);



            psum = vec_mladd(vA, vsrc0ssH, vec_splat_s16(0));

            psum = vec_mladd(vB, vsrc1ssH, psum);

            psum = vec_mladd(vC, vsrc2ssH, psum);

            psum = vec_mladd(vD, vsrc3ssH, psum);

            psum = vec_add(v28ss, psum);

            psum = vec_sr(psum, v6us);



            vdst = vec_ld(0, dst);

            ppsum = (vec_u8)vec_pack(psum, psum);

            fsum = vec_perm(vdst, ppsum, fperm);



            vec_st(fsum, 0, dst);



            vsrc0ssH = vsrc2ssH;

            vsrc1ssH = vsrc3ssH;



            dst += stride;

            src += stride;

        }

    }

}

static void get_pixels_altivec(int16_t *restrict block, const uint8_t *pixels, int line_size)

{

    int i;

    vector unsigned char perm = vec_lvsl(0, pixels);

    vector unsigned char bytes;

    const vector unsigned char zero = (const vector unsigned char)vec_splat_u8(0);

    vector signed short shorts;



    for (i = 0; i < 8; i++) {

        // Read potentially unaligned pixels.

        // We're reading 16 pixels, and actually only want 8,

        // but we simply ignore the extras.

        vector unsigned char pixl = vec_ld( 0, pixels);

        vector unsigned char pixr = vec_ld(15, pixels);

        bytes = vec_perm(pixl, pixr, perm);



        // convert the bytes into shorts

        shorts = (vector signed short)vec_mergeh(zero, bytes);



        // save the data to the block, we assume the block is 16-byte aligned

        vec_st(shorts, i*16, (vector signed short*)block);



        pixels += line_size;

    }

}

static int sad8_altivec(void *v, uint8_t *pix1, uint8_t *pix2, int line_size, int h)

{

    int i;

    int s;

    const vector unsigned int zero = (const vector unsigned int)vec_splat_u32(0);

    const vector unsigned char permclear = (vector unsigned char){255,255,255,255,255,255,255,255,0,0,0,0,0,0,0,0};

    vector unsigned char perm1 = vec_lvsl(0, pix1);

    vector unsigned char perm2 = vec_lvsl(0, pix2);

    vector unsigned char t1, t2, t3,t4, t5;

    vector unsigned int sad;

    vector signed int sumdiffs;



    sad = (vector unsigned int)vec_splat_u32(0);



    for (i = 0; i < h; i++) {

        /* Read potentially unaligned pixels into t1 and t2

           Since we're reading 16 pixels, and actually only want 8,

           mask out the last 8 pixels. The 0s don't change the sum. */

        vector unsigned char pix1l = vec_ld( 0, pix1);

        vector unsigned char pix1r = vec_ld(15, pix1);

        vector unsigned char pix2l = vec_ld( 0, pix2);

        vector unsigned char pix2r = vec_ld(15, pix2);

        t1 = vec_and(vec_perm(pix1l, pix1r, perm1), permclear);

        t2 = vec_and(vec_perm(pix2l, pix2r, perm2), permclear);



        /* Calculate a sum of abs differences vector */

        t3 = vec_max(t1, t2);

        t4 = vec_min(t1, t2);

        t5 = vec_sub(t3, t4);



        /* Add each 4 pixel group together and put 4 results into sad */

        sad = vec_sum4s(t5, sad);



        pix1 += line_size;

        pix2 += line_size;

    }



    /* Sum up the four partial sums, and put the result into s */

    sumdiffs = vec_sums((vector signed int) sad, (vector signed int) zero);

    sumdiffs = vec_splat(sumdiffs, 3);

    vec_ste(sumdiffs, 0, &s);



    return s;

}

static int thread_get_buffer_internal(AVCodecContext *avctx, ThreadFrame *f, int flags)

{

    PerThreadContext *p = avctx->internal->thread_ctx;

    int err;



    f->owner = avctx;



    ff_init_buffer_info(avctx, f->f);



    if (!(avctx->active_thread_type & FF_THREAD_FRAME))

        return ff_get_buffer(avctx, f->f, flags);



    if (atomic_load(&p->state) != STATE_SETTING_UP &&

        (avctx->codec->update_thread_context || !THREAD_SAFE_CALLBACKS(avctx))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() cannot be called after ff_thread_finish_setup()\n");

        return -1;

    }



    if (avctx->internal->allocate_progress) {

        atomic_int *progress;

        f->progress = av_buffer_alloc(2 * sizeof(*progress));

        if (!f->progress) {

            return AVERROR(ENOMEM);

        }

        progress = (atomic_int*)f->progress->data;



        atomic_init(&progress[0], -1);

        atomic_init(&progress[1], -1);

    }



    pthread_mutex_lock(&p->parent->buffer_mutex);

    if (avctx->thread_safe_callbacks ||

        avctx->get_buffer2 == avcodec_default_get_buffer2) {

        err = ff_get_buffer(avctx, f->f, flags);

    } else {

        pthread_mutex_lock(&p->progress_mutex);

        p->requested_frame = f->f;

        p->requested_flags = flags;

        atomic_store_explicit(&p->state, STATE_GET_BUFFER, memory_order_release);

        pthread_cond_broadcast(&p->progress_cond);



        while (atomic_load(&p->state) != STATE_SETTING_UP)

            pthread_cond_wait(&p->progress_cond, &p->progress_mutex);



        err = p->result;



        pthread_mutex_unlock(&p->progress_mutex);



    }

    if (!THREAD_SAFE_CALLBACKS(avctx) && !avctx->codec->update_thread_context)

        ff_thread_finish_setup(avctx);

    if (err)

        av_buffer_unref(&f->progress);



    pthread_mutex_unlock(&p->parent->buffer_mutex);



    return err;

}

void ff_frame_thread_free(AVCodecContext *avctx, int thread_count)

{

    FrameThreadContext *fctx = avctx->internal->thread_ctx;

    const AVCodec *codec = avctx->codec;

    int i;



    park_frame_worker_threads(fctx, thread_count);



    if (fctx->prev_thread && fctx->prev_thread != fctx->threads)

        if (update_context_from_thread(fctx->threads->avctx, fctx->prev_thread->avctx, 0) < 0) {

            av_log(avctx, AV_LOG_ERROR, "Final thread update failed\n");

            fctx->prev_thread->avctx->internal->is_copy = fctx->threads->avctx->internal->is_copy;

            fctx->threads->avctx->internal->is_copy = 1;

        }



    fctx->die = 1;



    for (i = 0; i < thread_count; i++) {

        PerThreadContext *p = &fctx->threads[i];



        pthread_mutex_lock(&p->mutex);

        pthread_cond_signal(&p->input_cond);

        pthread_mutex_unlock(&p->mutex);



        if (p->thread_init)

            pthread_join(p->thread, NULL);

        p->thread_init=0;



        if (codec->close)

            codec->close(p->avctx);



        release_delayed_buffers(p);

        av_frame_free(&p->frame);

    }



    for (i = 0; i < thread_count; i++) {

        PerThreadContext *p = &fctx->threads[i];



        pthread_mutex_destroy(&p->mutex);

        pthread_mutex_destroy(&p->progress_mutex);

        pthread_cond_destroy(&p->input_cond);

        pthread_cond_destroy(&p->progress_cond);

        pthread_cond_destroy(&p->output_cond);

        av_packet_unref(&p->avpkt);

        av_freep(&p->released_buffers);



        if (i) {

            av_freep(&p->avctx->priv_data);

            av_freep(&p->avctx->slice_offset);

        }



        av_freep(&p->avctx->internal);

        av_freep(&p->avctx);

    }



    av_freep(&fctx->threads);

    pthread_mutex_destroy(&fctx->buffer_mutex);

    av_freep(&avctx->internal->thread_ctx);



    if (avctx->priv_data && avctx->codec && avctx->codec->priv_class)

        av_opt_free(avctx->priv_data);

    avctx->codec = NULL;

}

static int thread_get_buffer_internal(AVCodecContext *avctx, ThreadFrame *f, int flags)

{

    PerThreadContext *p = avctx->thread_opaque;

    int err;



    f->owner = avctx;



    ff_init_buffer_info(avctx, f->f);



    if (!(avctx->active_thread_type & FF_THREAD_FRAME))

        return ff_get_buffer(avctx, f->f, flags);



    if (p->state != STATE_SETTING_UP &&

        (avctx->codec->update_thread_context || (!avctx->thread_safe_callbacks &&

                avctx->get_buffer != avcodec_default_get_buffer))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() cannot be called after ff_thread_finish_setup()\n");

        return -1;

    }



    if (avctx->internal->allocate_progress) {

        int *progress;

        f->progress = av_buffer_alloc(2 * sizeof(int));

        if (!f->progress) {

            return AVERROR(ENOMEM);

        }

        progress = (int*)f->progress->data;



        progress[0] = progress[1] = -1;

    }



    pthread_mutex_lock(&p->parent->buffer_mutex);



    if (avctx->thread_safe_callbacks || (

#if FF_API_GET_BUFFER

        !avctx->get_buffer &&

#endif

        avctx->get_buffer2 == avcodec_default_get_buffer2)) {

        err = ff_get_buffer(avctx, f->f, flags);

    } else {

        pthread_mutex_lock(&p->progress_mutex);

        p->requested_frame = f->f;

        p->requested_flags = flags;

        p->state = STATE_GET_BUFFER;

        pthread_cond_broadcast(&p->progress_cond);



        while (p->state != STATE_SETTING_UP)

            pthread_cond_wait(&p->progress_cond, &p->progress_mutex);



        err = p->result;



        pthread_mutex_unlock(&p->progress_mutex);



        if (!avctx->codec->update_thread_context)

            ff_thread_finish_setup(avctx);

    }



    if (err)

        av_buffer_unref(&f->progress);



    pthread_mutex_unlock(&p->parent->buffer_mutex);



    return err;

}

void ff_thread_release_buffer(AVCodecContext *avctx, ThreadFrame *f)

{

    PerThreadContext *p = avctx->internal->thread_ctx;

    FrameThreadContext *fctx;

    AVFrame *dst, *tmp;

FF_DISABLE_DEPRECATION_WARNINGS

    int can_direct_free = !(avctx->active_thread_type & FF_THREAD_FRAME) ||

                          avctx->thread_safe_callbacks                   ||

                          (

#if FF_API_GET_BUFFER

                           !avctx->get_buffer &&

#endif

                           avctx->get_buffer2 == avcodec_default_get_buffer2);

FF_ENABLE_DEPRECATION_WARNINGS



    if (!f->f->data[0])

        return;



    if (avctx->debug & FF_DEBUG_BUFFERS)

        av_log(avctx, AV_LOG_DEBUG, "thread_release_buffer called on pic %p\n", f);



    av_buffer_unref(&f->progress);

    f->owner    = NULL;



    if (can_direct_free) {

        av_frame_unref(f->f);

        return;

    }



    fctx = p->parent;

    pthread_mutex_lock(&fctx->buffer_mutex);



    if (p->num_released_buffers + 1 >= INT_MAX / sizeof(*p->released_buffers))

        goto fail;

    tmp = av_fast_realloc(p->released_buffers, &p->released_buffers_allocated,

                          (p->num_released_buffers + 1) *

                          sizeof(*p->released_buffers));

    if (!tmp)

        goto fail;

    p->released_buffers = tmp;



    dst = &p->released_buffers[p->num_released_buffers];

    av_frame_move_ref(dst, f->f);



    p->num_released_buffers++;



fail:

    pthread_mutex_unlock(&fctx->buffer_mutex);

}

