static int hds_flush(AVFormatContext *s, OutputStream *os, int final,

                     int64_t end_ts)

{

    HDSContext *c = s->priv_data;

    int i, ret = 0;

    char target_filename[1024];

    int index = s->streams[os->first_stream]->id;



    if (!os->packets_written)

        return 0;



    avio_flush(os->ctx->pb);

    os->packets_written = 0;

    close_file(os);



    snprintf(target_filename, sizeof(target_filename),

             "%s/stream%dSeg1-Frag%d", s->filename, index, os->fragment_index);

    ret = ff_rename(os->temp_filename, target_filename);

    if (ret < 0)

        return ret;

    add_fragment(os, target_filename, os->frag_start_ts, end_ts - os->frag_start_ts);



    if (!final) {

        ret = init_file(s, os, end_ts);

        if (ret < 0)

            return ret;

    }



    if (c->window_size || (final && c->remove_at_exit)) {

        int remove = os->nb_fragments - c->window_size - c->extra_window_size;

        if (final && c->remove_at_exit)

            remove = os->nb_fragments;

        if (remove > 0) {

            for (i = 0; i < remove; i++) {

                unlink(os->fragments[i]->file);

                av_free(os->fragments[i]);

            }

            os->nb_fragments -= remove;

            memmove(os->fragments, os->fragments + remove,

                    os->nb_fragments * sizeof(*os->fragments));

        }

    }



    if (ret >= 0)

        ret = write_abst(s, os, final);

    return ret;

}

yuv2422_2_c_template(SwsContext *c, const int16_t *buf[2],

                     const int16_t *ubuf[2], const int16_t *vbuf[2],

                     const int16_t *abuf[2], uint8_t *dest, int dstW,

                     int yalpha, int uvalpha, int y,

                     enum PixelFormat target)

{

    const int16_t *buf0  = buf[0],  *buf1  = buf[1],

                  *ubuf0 = ubuf[0], *ubuf1 = ubuf[1],

                  *vbuf0 = vbuf[0], *vbuf1 = vbuf[1];

    int  yalpha1 = 4095 - yalpha;

    int uvalpha1 = 4095 - uvalpha;

    int i;



    for (i = 0; i < ((dstW + 1) >> 1); i++) {

        int Y1 = (buf0[i * 2]     * yalpha1  + buf1[i * 2]     * yalpha)  >> 19;

        int Y2 = (buf0[i * 2 + 1] * yalpha1  + buf1[i * 2 + 1] * yalpha)  >> 19;

        int U  = (ubuf0[i]        * uvalpha1 + ubuf1[i]        * uvalpha) >> 19;

        int V  = (vbuf0[i]        * uvalpha1 + vbuf1[i]        * uvalpha) >> 19;



        Y1 = av_clip_uint8(Y1);

        Y2 = av_clip_uint8(Y2);

        U  = av_clip_uint8(U);

        V  = av_clip_uint8(V);



        output_pixels(i * 4, Y1, U, Y2, V);

    }

}

yuv2gray16_X_c_template(SwsContext *c, const int16_t *lumFilter,

                        const int32_t **lumSrc, int lumFilterSize,

                        const int16_t *chrFilter, const int32_t **chrUSrc,

                        const int32_t **chrVSrc, int chrFilterSize,

                        const int32_t **alpSrc, uint16_t *dest, int dstW,

                        int y, enum PixelFormat target)

{

    int i;



    for (i = 0; i < (dstW >> 1); i++) {

        int j;

        int Y1 = 1 << 14;

        int Y2 = 1 << 14;



        for (j = 0; j < lumFilterSize; j++) {

            Y1 += lumSrc[j][i * 2]     * lumFilter[j];

            Y2 += lumSrc[j][i * 2 + 1] * lumFilter[j];

        }

        Y1 >>= 15;

        Y2 >>= 15;

        if ((Y1 | Y2) & 0x10000) {

            Y1 = av_clip_uint16(Y1);

            Y2 = av_clip_uint16(Y2);

        }

        output_pixel(&dest[i * 2 + 0], Y1);

        output_pixel(&dest[i * 2 + 1], Y2);

    }

}

yuv2gray16_2_c_template(SwsContext *c, const uint16_t *buf0,

                        const uint16_t *buf1, const uint16_t *ubuf0,

                        const uint16_t *ubuf1, const uint16_t *vbuf0,

                        const uint16_t *vbuf1, const uint16_t *abuf0,

                        const uint16_t *abuf1, uint8_t *dest, int dstW,

                        int yalpha, int uvalpha, int y,

                        enum PixelFormat target)

{

    int  yalpha1 = 4095 - yalpha; \

    int i;



    for (i = 0; i < (dstW >> 1); i++) {

        const int i2 = 2 * i;

        int Y1 = (buf0[i2  ] * yalpha1 + buf1[i2  ] * yalpha) >> 11;

        int Y2 = (buf0[i2+1] * yalpha1 + buf1[i2+1] * yalpha) >> 11;



        output_pixel(&dest[2 * i2 + 0], Y1);

        output_pixel(&dest[2 * i2 + 2], Y2);

    }

}

yuv2422_1_c_template(SwsContext *c, const int16_t *buf0,
                     const int16_t *ubuf[2], const int16_t *vbuf[2],
                     const int16_t *abuf0, uint8_t *dest, int dstW,
                     int uvalpha, int y, enum PixelFormat target)
{
    const int16_t *ubuf0 = ubuf[0], *vbuf0 = vbuf[0];
    int i;
    if (uvalpha < 2048) {
        for (i = 0; i < (dstW >> 1); i++) {
            int Y1 = buf0[i * 2]     >> 7;
            int Y2 = buf0[i * 2 + 1] >> 7;
            int U  = ubuf0[i]        >> 7;
            int V  = vbuf0[i]        >> 7;
            output_pixels(i * 4, Y1, U, Y2, V);
        }
    } else {
        const int16_t *ubuf1 = ubuf[1], *vbuf1 = vbuf[1];
        for (i = 0; i < (dstW >> 1); i++) {
            int Y1 =  buf0[i * 2]          >> 7;
            int Y2 =  buf0[i * 2 + 1]      >> 7;
            int U  = (ubuf0[i] + ubuf1[i]) >> 8;
            int V  = (vbuf0[i] + vbuf1[i]) >> 8;
            output_pixels(i * 4, Y1, U, Y2, V);
        }
    }
}

