int kvm_arm_sync_mpstate_to_qemu(ARMCPU *cpu)

{

    if (cap_has_mp_state) {

        struct kvm_mp_state mp_state;

        int ret = kvm_vcpu_ioctl(CPU(cpu), KVM_GET_MP_STATE, &mp_state);

        if (ret) {

            fprintf(stderr, "%s: failed to get MP_STATE %d/%s\n",

                    __func__, ret, strerror(-ret));

            abort();

        }

        cpu->powered_off = (mp_state.mp_state == KVM_MP_STATE_STOPPED);

    }



    return 0;

}

static int tap_set_sndbuf(TAPState *s, const char *sndbuf_str)

{

    int sndbuf = TAP_DEFAULT_SNDBUF;



    if (sndbuf_str) {

        sndbuf = atoi(sndbuf_str);

    }



    if (!sndbuf) {

        sndbuf = INT_MAX;

    }



    if (ioctl(s->fd, TUNSETSNDBUF, &sndbuf) == -1 && sndbuf_str) {

        qemu_error("TUNSETSNDBUF ioctl failed: %s\n", strerror(errno));

        return -1;

    }

    return 0;

}

int nbd_client(int fd)

{

    int ret;

    int serrno;



    TRACE("Doing NBD loop");



    ret = ioctl(fd, NBD_DO_IT);

    if (ret == -1 && errno == EPIPE) {

        /* NBD_DO_IT normally returns EPIPE when someone has disconnected

         * the socket via NBD_DISCONNECT.  We do not want to return 1 in

         * that case.

         */

        ret = 0;

    }

    serrno = errno;



    TRACE("NBD loop returned %d: %s", ret, strerror(serrno));



    TRACE("Clearing NBD queue");

    ioctl(fd, NBD_CLEAR_QUE);



    TRACE("Clearing NBD socket");

    ioctl(fd, NBD_CLEAR_SOCK);



    errno = serrno;

    return ret;

}

void mpeg1_encode_init(MpegEncContext *s)

{

    static int done=0;

    if(!done){

        int f_code;

        int mv;



        done=1;

        for(f_code=1; f_code<=MAX_FCODE; f_code++){

            for(mv=-MAX_MV; mv<=MAX_MV; mv++){

                int len;



                if(mv==0) len= mbMotionVectorTable[0][1];

                else{

                    int val, bit_size, range, code;



                    bit_size = s->f_code - 1;

                    range = 1 << bit_size;



                    val=mv;

                    if (val < 0) 

                        val = -val;

                    val--;

                    code = (val >> bit_size) + 1;

                    if(code<17){

                        len= mbMotionVectorTable[code][1] + 1 + bit_size;

                    }else{

                        len= mbMotionVectorTable[16][1] + 2 + bit_size;

                    }

                }



                mv_penalty[f_code][mv+MAX_MV]= len;

            }

        }





        for(f_code=MAX_FCODE; f_code>0; f_code--){

            for(mv=-(8<<f_code); mv<(8<<f_code); mv++){

                fcode_tab[mv+MAX_MV]= f_code;

            }

        }

    }

    s->mv_penalty= mv_penalty;



    s->fcode_tab= fcode_tab;

}

