static av_cold int atrac1_decode_init(AVCodecContext *avctx)

{

    AT1Ctx *q = avctx->priv_data;



    avctx->sample_fmt = AV_SAMPLE_FMT_FLT;



    if (avctx->channels < 1 || avctx->channels > AT1_MAX_CHANNELS) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported number of channels: %d\n",

               avctx->channels);

        return AVERROR(EINVAL);

    }

    q->channels = avctx->channels;



    if (avctx->channels == 2) {

        q->out_samples[0] = av_malloc(2 * AT1_SU_SAMPLES * sizeof(*q->out_samples[0]));

        q->out_samples[1] = q->out_samples[0] + AT1_SU_SAMPLES;

        if (!q->out_samples[0]) {

            av_freep(&q->out_samples[0]);

            return AVERROR(ENOMEM);

        }

    }



    /* Init the mdct transforms */

    ff_mdct_init(&q->mdct_ctx[0], 6, 1, -1.0/ (1 << 15));

    ff_mdct_init(&q->mdct_ctx[1], 8, 1, -1.0/ (1 << 15));

    ff_mdct_init(&q->mdct_ctx[2], 9, 1, -1.0/ (1 << 15));



    ff_init_ff_sine_windows(5);



    atrac_generate_tables();



    dsputil_init(&q->dsp, avctx);

    ff_fmt_convert_init(&q->fmt_conv, avctx);



    q->bands[0] = q->low;

    q->bands[1] = q->mid;

    q->bands[2] = q->high;



    /* Prepare the mdct overlap buffers */

    q->SUs[0].spectrum[0] = q->SUs[0].spec1;

    q->SUs[0].spectrum[1] = q->SUs[0].spec2;

    q->SUs[1].spectrum[0] = q->SUs[1].spec1;

    q->SUs[1].spectrum[1] = q->SUs[1].spec2;



    return 0;

}

static av_cold int encode_init(AVCodecContext *avctx)

{

    NellyMoserEncodeContext *s = avctx->priv_data;

    int i, ret;



    if (avctx->channels != 1) {

        av_log(avctx, AV_LOG_ERROR, "Nellymoser supports only 1 channel\n");

        return AVERROR(EINVAL);

    }



    if (avctx->sample_rate != 8000 && avctx->sample_rate != 16000 &&

        avctx->sample_rate != 11025 &&

        avctx->sample_rate != 22050 && avctx->sample_rate != 44100 &&

        avctx->strict_std_compliance >= FF_COMPLIANCE_NORMAL) {

        av_log(avctx, AV_LOG_ERROR, "Nellymoser works only with 8000, 16000, 11025, 22050 and 44100 sample rate\n");

        return AVERROR(EINVAL);

    }



    avctx->frame_size = NELLY_SAMPLES;

    avctx->delay      = NELLY_BUF_LEN;

    ff_af_queue_init(avctx, &s->afq);

    s->avctx = avctx;

    if ((ret = ff_mdct_init(&s->mdct_ctx, 8, 0, 32768.0)) < 0)

        goto error;

    ff_dsputil_init(&s->dsp, avctx);



    /* Generate overlap window */

    ff_sine_window_init(ff_sine_128, 128);

    for (i = 0; i < POW_TABLE_SIZE; i++)

        pow_table[i] = -pow(2, -i / 2048.0 - 3.0 + POW_TABLE_OFFSET);



    if (s->avctx->trellis) {

        s->opt  = av_malloc(NELLY_BANDS * OPT_SIZE * sizeof(float  ));

        s->path = av_malloc(NELLY_BANDS * OPT_SIZE * sizeof(uint8_t));

        if (!s->opt || !s->path) {

            ret = AVERROR(ENOMEM);

            goto error;

        }

    }



#if FF_API_OLD_ENCODE_AUDIO

    avctx->coded_frame = avcodec_alloc_frame();

    if (!avctx->coded_frame) {

        ret = AVERROR(ENOMEM);

        goto error;

    }

#endif



    return 0;

error:

    encode_end(avctx);

    return ret;

}

