static uint64_t lan9118_readl(void *opaque, hwaddr offset,

                              unsigned size)

{

    lan9118_state *s = (lan9118_state *)opaque;



    //DPRINTF("Read reg 0x%02x\n", (int)offset);

    if (offset < 0x20) {

        /* RX FIFO */

        return rx_fifo_pop(s);

    }

    switch (offset) {

    case 0x40:

        return rx_status_fifo_pop(s);

    case 0x44:

        return s->rx_status_fifo[s->tx_status_fifo_head];

    case 0x48:

        return tx_status_fifo_pop(s);

    case 0x4c:

        return s->tx_status_fifo[s->tx_status_fifo_head];

    case CSR_ID_REV:

        return 0x01180001;

    case CSR_IRQ_CFG:

        return s->irq_cfg;

    case CSR_INT_STS:

        return s->int_sts;

    case CSR_INT_EN:

        return s->int_en;

    case CSR_BYTE_TEST:

        return 0x87654321;

    case CSR_FIFO_INT:

        return s->fifo_int;

    case CSR_RX_CFG:

        return s->rx_cfg;

    case CSR_TX_CFG:

        return s->tx_cfg;

    case CSR_HW_CFG:

        return s->hw_cfg;

    case CSR_RX_DP_CTRL:

        return 0;

    case CSR_RX_FIFO_INF:

        return (s->rx_status_fifo_used << 16) | (s->rx_fifo_used << 2);

    case CSR_TX_FIFO_INF:

        return (s->tx_status_fifo_used << 16)

               | (s->tx_fifo_size - s->txp->fifo_used);

    case CSR_PMT_CTRL:

        return s->pmt_ctrl;

    case CSR_GPIO_CFG:

        return s->gpio_cfg;

    case CSR_GPT_CFG:

        return s->gpt_cfg;

    case CSR_GPT_CNT:

        return ptimer_get_count(s->timer);

    case CSR_WORD_SWAP:

        return s->word_swap;

    case CSR_FREE_RUN:

        return (qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL) / 40) - s->free_timer_start;

    case CSR_RX_DROP:

        /* TODO: Implement dropped frames counter.  */

        return 0;

    case CSR_MAC_CSR_CMD:

        return s->mac_cmd;

    case CSR_MAC_CSR_DATA:

        return s->mac_data;

    case CSR_AFC_CFG:

        return s->afc_cfg;

    case CSR_E2P_CMD:

        return s->e2p_cmd;

    case CSR_E2P_DATA:

        return s->e2p_data;

    }

    hw_error("lan9118_read: Bad reg 0x%x\n", (int)offset);

    return 0;

}

static uint32_t arm_timer_read(void *opaque, target_phys_addr_t offset)

{

    arm_timer_state *s = (arm_timer_state *)opaque;



    switch (offset >> 2) {

    case 0: /* TimerLoad */

    case 6: /* TimerBGLoad */

        return s->limit;

    case 1: /* TimerValue */

        return ptimer_get_count(s->timer);

    case 2: /* TimerControl */

        return s->control;

    case 4: /* TimerRIS */

        return s->int_level;

    case 5: /* TimerMIS */

        if ((s->control & TIMER_CTRL_IE) == 0)

            return 0;

        return s->int_level;

    default:

        hw_error("%s: Bad offset %x\n", __func__, (int)offset);

        return 0;

    }

}

static uint64_t ahci_mem_read(void *opaque, target_phys_addr_t addr,

                              unsigned size)

{

    AHCIState *s = opaque;

    uint32_t val = 0;



    if (addr < AHCI_GENERIC_HOST_CONTROL_REGS_MAX_ADDR) {

        switch (addr) {

        case HOST_CAP:

            val = s->control_regs.cap;

            break;

        case HOST_CTL:

            val = s->control_regs.ghc;

            break;

        case HOST_IRQ_STAT:

            val = s->control_regs.irqstatus;

            break;

        case HOST_PORTS_IMPL:

            val = s->control_regs.impl;

            break;

        case HOST_VERSION:

            val = s->control_regs.version;

            break;

        }



        DPRINTF(-1, "(addr 0x%08X), val 0x%08X\n", (unsigned) addr, val);

    } else if ((addr >= AHCI_PORT_REGS_START_ADDR) &&

               (addr < (AHCI_PORT_REGS_START_ADDR +

                (s->ports * AHCI_PORT_ADDR_OFFSET_LEN)))) {

        val = ahci_port_read(s, (addr - AHCI_PORT_REGS_START_ADDR) >> 7,

                             addr & AHCI_PORT_ADDR_OFFSET_MASK);

    }



    return val;

}

static uint64_t pxa2xx_lcdc_read(void *opaque, hwaddr offset,

                                 unsigned size)

{

    PXA2xxLCDState *s = (PXA2xxLCDState *) opaque;

    int ch;



    switch (offset) {

    case LCCR0:

        return s->control[0];

    case LCCR1:

        return s->control[1];

    case LCCR2:

        return s->control[2];

    case LCCR3:

        return s->control[3];

    case LCCR4:

        return s->control[4];

    case LCCR5:

        return s->control[5];



    case OVL1C1:

        return s->ovl1c[0];

    case OVL1C2:

        return s->ovl1c[1];

    case OVL2C1:

        return s->ovl2c[0];

    case OVL2C2:

        return s->ovl2c[1];



    case CCR:

        return s->ccr;



    case CMDCR:

        return s->cmdcr;



    case TRGBR:

        return s->trgbr;

    case TCR:

        return s->tcr;



    case 0x200 ... 0x1000:	/* DMA per-channel registers */

        ch = (offset - 0x200) >> 4;

        if (!(ch >= 0 && ch < PXA_LCDDMA_CHANS))

            goto fail;



        switch (offset & 0xf) {

        case DMA_FDADR:

            return s->dma_ch[ch].descriptor;

        case DMA_FSADR:

            return s->dma_ch[ch].source;

        case DMA_FIDR:

            return s->dma_ch[ch].id;

        case DMA_LDCMD:

            return s->dma_ch[ch].command;

        default:

            goto fail;

        }



    case FBR0:

        return s->dma_ch[0].branch;

    case FBR1:

        return s->dma_ch[1].branch;

    case FBR2:

        return s->dma_ch[2].branch;

    case FBR3:

        return s->dma_ch[3].branch;

    case FBR4:

        return s->dma_ch[4].branch;

    case FBR5:

        return s->dma_ch[5].branch;

    case FBR6:

        return s->dma_ch[6].branch;



    case BSCNTR:

        return s->bscntr;



    case PRSR:

        return 0;



    case LCSR0:

        return s->status[0];

    case LCSR1:

        return s->status[1];

    case LIIDR:

        return s->liidr;



    default:

    fail:

        hw_error("%s: Bad offset " REG_FMT "\n", __FUNCTION__, offset);

    }



    return 0;

}

static int read_low_coeffs(AVCodecContext *avctx, int16_t *dst, int size, int width, ptrdiff_t stride)

{

    PixletContext *ctx = avctx->priv_data;

    GetBitContext *b = &ctx->gbit;

    unsigned cnt1, nbits, k, j = 0, i = 0;

    int64_t value, state = 3;

    int rlen, escape, flag = 0;



    while (i < size) {

        nbits = FFMIN(ff_clz((state >> 8) + 3) ^ 0x1F, 14);



        cnt1 = get_unary(b, 0, 8);

        if (cnt1 < 8) {

            value = show_bits(b, nbits);

            if (value <= 1) {

                skip_bits(b, nbits - 1);

                escape = ((1 << nbits) - 1) * cnt1;

            } else {

                skip_bits(b, nbits);

                escape = value + ((1 << nbits) - 1) * cnt1 - 1;

            }

        } else {

            escape = get_bits(b, 16);

        }



        value = -((escape + flag) & 1) | 1;

        dst[j++] = value * ((escape + flag + 1) >> 1);

        i++;

        if (j == width) {

            j = 0;

            dst += stride;

        }

        state = 120 * (escape + flag) + state - (120 * state >> 8);

        flag = 0;



        if (state * 4 > 0xFF || i >= size)

            continue;



        nbits = ((state + 8) >> 5) + (state ? ff_clz(state) : 32) - 24;

        escape = av_mod_uintp2(16383, nbits);

        cnt1 = get_unary(b, 0, 8);

        if (cnt1 > 7) {

            rlen = get_bits(b, 16);

        } else {

            value = show_bits(b, nbits);

            if (value > 1) {

                skip_bits(b, nbits);

                rlen = value + escape * cnt1 - 1;

            } else {

                skip_bits(b, nbits - 1);

                rlen = escape * cnt1;

            }

        }



        if (rlen > size - i)

            return AVERROR_INVALIDDATA;

        i += rlen;



        for (k = 0; k < rlen; k++) {

            dst[j++] = 0;

            if (j == width) {

                j = 0;

                dst += stride;

            }

        }



        state = 0;

        flag = rlen < 0xFFFF ? 1 : 0;

    }



    align_get_bits(b);

    return get_bits_count(b) >> 3;

}

static int read_high_coeffs(AVCodecContext *avctx, uint8_t *src, int16_t *dst, int size,

                            int c, int a, int d,

                            int width, ptrdiff_t stride)

{

    PixletContext *ctx = avctx->priv_data;

    GetBitContext *b = &ctx->gbit;

    unsigned cnt1, shbits, rlen, nbits, length, i = 0, j = 0, k;

    int ret, escape, pfx, value, yflag, xflag, flag = 0;

    int64_t state = 3, tmp;



    if ((ret = init_get_bits8(b, src, bytestream2_get_bytes_left(&ctx->gb))) < 0)

      return ret;



    if ((a >= 0) + (a ^ (a >> 31)) - (a >> 31) != 1) {

        nbits = 33 - ff_clz((a >= 0) + (a ^ (a >> 31)) - (a >> 31) - 1);

        if (nbits > 16)

            return AVERROR_INVALIDDATA;

    } else {

        nbits = 1;

    }



    length = 25 - nbits;



    while (i < size) {

        if (state >> 8 != -3) {

            value = ff_clz((state >> 8) + 3) ^ 0x1F;

        } else {

            value = -1;

        }



        cnt1 = get_unary(b, 0, length);



        if (cnt1 >= length) {

            cnt1 = get_bits(b, nbits);

        } else {

            pfx = 14 + ((((uint64_t)(value - 14)) >> 32) & (value - 14));

            cnt1 *= (1 << pfx) - 1;

            shbits = show_bits(b, pfx);

            if (shbits <= 1) {

                skip_bits(b, pfx - 1);

            } else {

                skip_bits(b, pfx);

                cnt1 += shbits - 1;

            }

        }



        xflag = flag + cnt1;

        yflag = xflag;



        if (flag + cnt1 == 0) {

            value = 0;

        } else {

            xflag &= 1u;

            tmp = c * ((yflag + 1) >> 1) + (c >> 1);

            value = xflag + (tmp ^ -xflag);

        }



        i++;

        dst[j++] = value;

        if (j == width) {

            j = 0;

            dst += stride;

        }

        state += d * yflag - (d * state >> 8);



        flag = 0;



        if (state * 4 > 0xFF || i >= size)

            continue;



        pfx = ((state + 8) >> 5) + (state ? ff_clz(state): 32) - 24;

        escape = av_mod_uintp2(16383, pfx);

        cnt1 = get_unary(b, 0, 8);

        if (cnt1 < 8) {

            if (pfx < 1 || pfx > 25)

                return AVERROR_INVALIDDATA;

            value = show_bits(b, pfx);

            if (value > 1) {

                skip_bits(b, pfx);

                rlen = value + escape * cnt1 - 1;

            } else {

                skip_bits(b, pfx - 1);

                rlen = escape * cnt1;

            }

        } else {

            if (get_bits1(b))

                value = get_bits(b, 16);

            else

                value = get_bits(b, 8);



            rlen = value + 8 * escape;

        }



        if (rlen > 0xFFFF || i + rlen > size)

            return AVERROR_INVALIDDATA;

        i += rlen;



        for (k = 0; k < rlen; k++) {

            dst[j++] = 0;

            if (j == width) {

                j = 0;

                dst += stride;

            }

        }



        state = 0;

        flag = rlen < 0xFFFF ? 1 : 0;

    }



    align_get_bits(b);

    return get_bits_count(b) >> 3;

}

static int theora_decode_tables(AVCodecContext *avctx, GetBitContext gb)

{

    Vp3DecodeContext *s = avctx->priv_data;

    int i, n, matrices;



    if (s->theora >= 0x030200) {

        n = get_bits(&gb, 3);

        /* loop filter limit values table */

        for (i = 0; i < 64; i++)

            s->filter_limit_values[i] = get_bits(&gb, n);

    }



    if (s->theora >= 0x030200)

        n = get_bits(&gb, 4) + 1;

    else

        n = 16;

    /* quality threshold table */

    for (i = 0; i < 64; i++)

        s->coded_ac_scale_factor[i] = get_bits(&gb, n);



    if (s->theora >= 0x030200)

        n = get_bits(&gb, 4) + 1;

    else

        n = 16;

    /* dc scale factor table */

    for (i = 0; i < 64; i++)

        s->coded_dc_scale_factor[i] = get_bits(&gb, n);



    if (s->theora >= 0x030200)

        matrices = get_bits(&gb, 9) + 1;

    else

        matrices = 3;

    if (matrices != 3) {

        av_log(avctx,AV_LOG_ERROR, "unsupported matrices: %d\n", matrices);

//        return -1;

    }

    /* y coeffs */

    for (i = 0; i < 64; i++)

        s->coded_intra_y_dequant[i] = get_bits(&gb, 8);



    /* uv coeffs */

    for (i = 0; i < 64; i++)

        s->coded_intra_c_dequant[i] = get_bits(&gb, 8);



    /* inter coeffs */

    for (i = 0; i < 64; i++)

        s->coded_inter_dequant[i] = get_bits(&gb, 8);



    /* skip unknown matrices */

    n = matrices - 3;

    while(n--)

        for (i = 0; i < 64; i++)

            skip_bits(&gb, 8);



    for (i = 0; i <= 1; i++) {

        for (n = 0; n <= 2; n++) {

            int newqr;

            if (i > 0 || n > 0)

                newqr = get_bits(&gb, 1);

            else

                newqr = 1;

            if (!newqr) {

                if (i > 0)

                    get_bits(&gb, 1);

            }

            else {

                int qi = 0;

                skip_bits(&gb, av_log2(matrices-1)+1);

                while (qi < 63) {

                    qi += get_bits(&gb, av_log2(63-qi)+1) + 1;

                    skip_bits(&gb, av_log2(matrices-1)+1);

                }

                if (qi > 63) {

                    av_log(avctx, AV_LOG_ERROR, "invalid qi %d > 63\n", qi);

                    return -1;

                }

            }

        }

    }



    /* Huffman tables */

    for (s->hti = 0; s->hti < 80; s->hti++) {

        s->entries = 0;

        s->huff_code_size = 1;

        if (!get_bits(&gb, 1)) {

            s->hbits = 0;

            read_huffman_tree(avctx, &gb);

            s->hbits = 1;

            read_huffman_tree(avctx, &gb);

        }

    }



    s->theora_tables = 1;



    return 0;

}

static int decode_segment(TAKDecContext *s, int8_t mode, int32_t *decoded, int len)

{

    struct CParam code;

    GetBitContext *gb = &s->gb;

    int i;



    if (!mode) {

        memset(decoded, 0, len * sizeof(*decoded));

        return 0;

    }



    if (mode > FF_ARRAY_ELEMS(xcodes))

        return AVERROR_INVALIDDATA;

    code = xcodes[mode - 1];



    for (i = 0; i < len; i++) {

        int x = get_bits_long(gb, code.init);

        if (x >= code.escape && get_bits1(gb)) {

            x |= 1 << code.init;

            if (x >= code.aescape) {

                int scale = get_unary(gb, 1, 9);

                if (scale == 9) {

                    int scale_bits = get_bits(gb, 3);

                    if (scale_bits > 0) {

                        if (scale_bits == 7) {

                            scale_bits += get_bits(gb, 5);

                            if (scale_bits > 29)

                                return AVERROR_INVALIDDATA;

                        }

                        scale = get_bits_long(gb, scale_bits) + 1;

                        x    += code.scale * scale;

                    }

                    x += code.bias;

                } else

                    x += code.scale * scale - code.escape;

            } else

                x -= code.escape;

        }

        decoded[i] = (x >> 1) ^ -(x & 1);

    }



    return 0;

}

static void nbd_co_receive_reply(NBDClientSession *s,

                                 NBDRequest *request,

                                 NBDReply *reply,

                                 QEMUIOVector *qiov)

{

    int ret;



    /* Wait until we're woken up by nbd_read_reply_entry.  */

    qemu_coroutine_yield();

    *reply = s->reply;

    if (reply->handle != request->handle ||

        !s->ioc) {

        reply->error = EIO;

    } else {

        if (qiov && reply->error == 0) {

            ret = nbd_rwv(s->ioc, qiov->iov, qiov->niov, request->len, true,

                          NULL);

            if (ret != request->len) {

                reply->error = EIO;

            }

        }



        /* Tell the read handler to read another header.  */

        s->reply.handle = 0;

    }

}

static int nbd_co_discard(BlockDriverState *bs, int64_t sector_num,

                          int nb_sectors)

{

    BDRVNBDState *s = bs->opaque;

    struct nbd_request request;

    struct nbd_reply reply;



    if (!(s->nbdflags & NBD_FLAG_SEND_TRIM)) {

        return 0;

    }

    request.type = NBD_CMD_TRIM;

    request.from = sector_num * 512;;

    request.len = nb_sectors * 512;



    nbd_coroutine_start(s, &request);

    if (nbd_co_send_request(s, &request, NULL, 0) == -1) {

        reply.error = errno;

    } else {

        nbd_co_receive_reply(s, &request, &reply, NULL, 0);

    }

    nbd_coroutine_end(s, &request);

    return -reply.error;

}

static int nbd_co_readv_1(NbdClientSession *client, int64_t sector_num,

                          int nb_sectors, QEMUIOVector *qiov,

                          int offset)

{

    struct nbd_request request = { .type = NBD_CMD_READ };

    struct nbd_reply reply;

    ssize_t ret;



    request.from = sector_num * 512;

    request.len = nb_sectors * 512;



    nbd_coroutine_start(client, &request);

    ret = nbd_co_send_request(client, &request, NULL, 0);

    if (ret < 0) {

        reply.error = -ret;

    } else {

        nbd_co_receive_reply(client, &request, &reply, qiov, offset);

    }

    nbd_coroutine_end(client, &request);

    return -reply.error;



}

static int vmdk_is_allocated(BlockDriverState *bs, int64_t sector_num,

                             int nb_sectors, int *pnum)

{

    BDRVVmdkState *s = bs->opaque;

    int64_t index_in_cluster, n, ret;

    uint64_t offset;

    VmdkExtent *extent;



    extent = find_extent(s, sector_num, NULL);

    if (!extent) {

        return 0;

    }

    ret = get_cluster_offset(bs, extent, NULL,

                            sector_num * 512, 0, &offset);

    /* get_cluster_offset returning 0 means success */

    ret = !ret;



    index_in_cluster = sector_num % extent->cluster_sectors;

    n = extent->cluster_sectors - index_in_cluster;

    if (n > nb_sectors) {

        n = nb_sectors;

    }

    *pnum = n;

    return ret;

}

static int filter_frame(AVFilterLink *inlink, AVFilterBufferRef *buf)

{

    AVFilterContext *ctx = inlink->dst;

    AlphaMergeContext *merge = ctx->priv;



    int is_alpha = (inlink == ctx->inputs[1]);

    struct FFBufQueue *queue =

        (is_alpha ? &merge->queue_alpha : &merge->queue_main);

    ff_bufqueue_add(ctx, queue, buf);



    while (1) {

        AVFilterBufferRef *main_buf, *alpha_buf;



        if (!ff_bufqueue_peek(&merge->queue_main, 0) ||

            !ff_bufqueue_peek(&merge->queue_alpha, 0)) break;



        main_buf = ff_bufqueue_get(&merge->queue_main);

        alpha_buf = ff_bufqueue_get(&merge->queue_alpha);



        merge->frame_requested = 0;

        draw_frame(ctx, main_buf, alpha_buf);

        ff_filter_frame(ctx->outputs[0], avfilter_ref_buffer(main_buf, ~0));

        avfilter_unref_buffer(alpha_buf);

    }

    return 0;

}

static int config_output(AVFilterLink *outlink)

{

    AVFilterContext *ctx = outlink->src;

    LIBVMAFContext *s = ctx->priv;

    AVFilterLink *mainlink = ctx->inputs[0];

    int ret;



    outlink->w = mainlink->w;

    outlink->h = mainlink->h;

    outlink->time_base = mainlink->time_base;

    outlink->sample_aspect_ratio = mainlink->sample_aspect_ratio;

    outlink->frame_rate = mainlink->frame_rate;

    if ((ret = ff_dualinput_init(ctx, &s->dinput)) < 0)

        return ret;



    return 0;

}

static int request_frame(AVFilterLink *outlink)

{

    AVFilterContext *ctx = outlink->src;

    TrimContext       *s = ctx->priv;

    int ret;



    s->got_output = 0;

    while (!s->got_output) {

        if (s->eof)

            return AVERROR_EOF;



        ret = ff_request_frame(ctx->inputs[0]);

        if (ret < 0)

            return ret;

    }



    return 0;

}

int ff_request_frame(AVFilterLink *link)

{

    int ret = -1;

    FF_TPRINTF_START(NULL, request_frame); ff_tlog_link(NULL, link, 1);



    if (link->closed)

        return AVERROR_EOF;

    av_assert0(!link->frame_requested);

    link->frame_requested = 1;

    while (link->frame_requested) {

        if (link->srcpad->request_frame)

            ret = link->srcpad->request_frame(link);

        else if (link->src->inputs[0])

            ret = ff_request_frame(link->src->inputs[0]);

        if (ret == AVERROR_EOF && link->partial_buf) {

            AVFrame *pbuf = link->partial_buf;

            link->partial_buf = NULL;

            ret = ff_filter_frame_framed(link, pbuf);

        }

        if (ret < 0) {

            link->frame_requested = 0;

            if (ret == AVERROR_EOF)

                link->closed = 1;

        } else {

            av_assert0(!link->frame_requested ||

                       link->flags & FF_LINK_FLAG_REQUEST_LOOP);

        }

    }

    return ret;

}

static int dpcm_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             uint8_t *buf, int buf_size)

{

    DPCMContext *s = avctx->priv_data;

    int in, out = 0;

    int predictor[2];

    int channel_number = 0;

    short *output_samples = data;

    int shift[2];

    unsigned char byte;

    short diff;



    if (!buf_size)

        return 0;



    // almost every DPCM variant expands one byte of data into two

    if(*data_size/2 < buf_size)




    switch(avctx->codec->id) {



    case CODEC_ID_ROQ_DPCM:

        if (s->channels == 1)

            predictor[0] = AV_RL16(&buf[6]);

        else {

            predictor[0] = buf[7] << 8;

            predictor[1] = buf[6] << 8;

        }

        SE_16BIT(predictor[0]);

        SE_16BIT(predictor[1]);



        /* decode the samples */

        for (in = 8, out = 0; in < buf_size; in++, out++) {

            predictor[channel_number] += s->roq_square_array[buf[in]];

            predictor[channel_number] = av_clip_int16(predictor[channel_number]);

            output_samples[out] = predictor[channel_number];



            /* toggle channel */

            channel_number ^= s->channels - 1;

        }

        break;



    case CODEC_ID_INTERPLAY_DPCM:

        in = 6;  /* skip over the stream mask and stream length */

        predictor[0] = AV_RL16(&buf[in]);

        in += 2;

        SE_16BIT(predictor[0])

        output_samples[out++] = predictor[0];

        if (s->channels == 2) {

            predictor[1] = AV_RL16(&buf[in]);

            in += 2;

            SE_16BIT(predictor[1])

            output_samples[out++] = predictor[1];

        }



        while (in < buf_size) {

            predictor[channel_number] += interplay_delta_table[buf[in++]];

            predictor[channel_number] = av_clip_int16(predictor[channel_number]);

            output_samples[out++] = predictor[channel_number];



            /* toggle channel */

            channel_number ^= s->channels - 1;

        }



        break;



    case CODEC_ID_XAN_DPCM:

        in = 0;

        shift[0] = shift[1] = 4;

        predictor[0] = AV_RL16(&buf[in]);

        in += 2;

        SE_16BIT(predictor[0]);

        if (s->channels == 2) {

            predictor[1] = AV_RL16(&buf[in]);

            in += 2;

            SE_16BIT(predictor[1]);

        }



        while (in < buf_size) {

            byte = buf[in++];

            diff = (byte & 0xFC) << 8;

            if ((byte & 0x03) == 3)

                shift[channel_number]++;

            else

                shift[channel_number] -= (2 * (byte & 3));

            /* saturate the shifter to a lower limit of 0 */

            if (shift[channel_number] < 0)

                shift[channel_number] = 0;



            diff >>= shift[channel_number];

            predictor[channel_number] += diff;



            predictor[channel_number] = av_clip_int16(predictor[channel_number]);

            output_samples[out++] = predictor[channel_number];



            /* toggle channel */

            channel_number ^= s->channels - 1;

        }

        break;

    case CODEC_ID_SOL_DPCM:

        in = 0;

        if (avctx->codec_tag != 3) {



            while (in < buf_size) {

                int n1, n2;

                n1 = (buf[in] >> 4) & 0xF;

                n2 = buf[in++] & 0xF;

                s->sample[0] += s->sol_table[n1];

                 if (s->sample[0] < 0) s->sample[0] = 0;

                if (s->sample[0] > 255) s->sample[0] = 255;

                output_samples[out++] = (s->sample[0] - 128) << 8;

                s->sample[s->channels - 1] += s->sol_table[n2];

                if (s->sample[s->channels - 1] < 0) s->sample[s->channels - 1] = 0;

                if (s->sample[s->channels - 1] > 255) s->sample[s->channels - 1] = 255;

                output_samples[out++] = (s->sample[s->channels - 1] - 128) << 8;

            }

        } else {

            while (in < buf_size) {

                int n;

                n = buf[in++];

                if (n & 0x80) s->sample[channel_number] -= s->sol_table[n & 0x7F];

                else s->sample[channel_number] += s->sol_table[n & 0x7F];

                s->sample[channel_number] = av_clip_int16(s->sample[channel_number]);

                output_samples[out++] = s->sample[channel_number];

                /* toggle channel */

                channel_number ^= s->channels - 1;

            }

        }

        break;

    }



    *data_size = out * sizeof(short);

    return buf_size;

}

static int dpcm_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_end = buf + buf_size;

    DPCMContext *s = avctx->priv_data;

    int out = 0, ret;

    int predictor[2];

    int ch = 0;

    int stereo = s->channels - 1;

    int16_t *output_samples;



    /* calculate output size */

    switch(avctx->codec->id) {

    case CODEC_ID_ROQ_DPCM:

        out = buf_size - 8;

        break;

    case CODEC_ID_INTERPLAY_DPCM:

        out = buf_size - 6 - s->channels;

        break;

    case CODEC_ID_XAN_DPCM:

        out = buf_size - 2 * s->channels;

        break;

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3)

            out = buf_size * 2;

        else

            out = buf_size;

        break;

    }

    if (out <= 0) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    s->frame.nb_samples = out / s->channels;

    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    output_samples = (int16_t *)s->frame.data[0];



    switch(avctx->codec->id) {



    case CODEC_ID_ROQ_DPCM:

        buf += 6;



        if (stereo) {

            predictor[1] = (int16_t)(bytestream_get_byte(&buf) << 8);

            predictor[0] = (int16_t)(bytestream_get_byte(&buf) << 8);

        } else {

            predictor[0] = (int16_t)bytestream_get_le16(&buf);

        }



        /* decode the samples */

        while (buf < buf_end) {

            predictor[ch] += s->roq_square_array[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_INTERPLAY_DPCM:

        buf += 6;  /* skip over the stream mask and stream length */



        for (ch = 0; ch < s->channels; ch++) {

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);

            *output_samples++ = predictor[ch];

        }



        ch = 0;

        while (buf < buf_end) {

            predictor[ch] += interplay_delta_table[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_XAN_DPCM:

    {

        int shift[2] = { 4, 4 };



        for (ch = 0; ch < s->channels; ch++)

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);



        ch = 0;

        while (buf < buf_end) {

            uint8_t n = *buf++;

            int16_t diff = (n & 0xFC) << 8;

            if ((n & 0x03) == 3)

                shift[ch]++;

            else

                shift[ch] -= (2 * (n & 3));

            /* saturate the shifter to a lower limit of 0 */

            if (shift[ch] < 0)

                shift[ch] = 0;



            diff >>= shift[ch];

            predictor[ch] += diff;



            predictor[ch] = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;

    }

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3) {

            uint8_t *output_samples_u8 = data;

            while (buf < buf_end) {

                uint8_t n = *buf++;



                s->sample[0] += s->sol_table[n >> 4];

                s->sample[0]  = av_clip_uint8(s->sample[0]);

                *output_samples_u8++ = s->sample[0];



                s->sample[stereo] += s->sol_table[n & 0x0F];

                s->sample[stereo]  = av_clip_uint8(s->sample[stereo]);

                *output_samples_u8++ = s->sample[stereo];

            }

        } else {

            while (buf < buf_end) {

                uint8_t n = *buf++;

                if (n & 0x80) s->sample[ch] -= sol_table_16[n & 0x7F];

                else          s->sample[ch] += sol_table_16[n & 0x7F];

                s->sample[ch] = av_clip_int16(s->sample[ch]);

                *output_samples++ = s->sample[ch];

                /* toggle channel */

                ch ^= stereo;

            }

        }

        break;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

}

static int dpcm_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_end = buf + buf_size;

    DPCMContext *s = avctx->priv_data;

    int out = 0;

    int predictor[2];

    int ch = 0;

    int stereo = s->channels - 1;

    int16_t *output_samples = data;



    if (!buf_size)

        return 0;



    /* calculate output size */

    switch(avctx->codec->id) {

    case CODEC_ID_ROQ_DPCM:

        out = buf_size - 8;

        break;

    case CODEC_ID_INTERPLAY_DPCM:

        out = buf_size - 6 - s->channels;

        break;

    case CODEC_ID_XAN_DPCM:

        out = buf_size - 2 * s->channels;

        break;

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3)

            out = buf_size * 2;

        else

            out = buf_size;

        break;

    }

    out *= av_get_bytes_per_sample(avctx->sample_fmt);

    if (out < 0) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR(EINVAL);

    }

    if (*data_size < out) {

        av_log(avctx, AV_LOG_ERROR, "output buffer is too small\n");

        return AVERROR(EINVAL);

    }



    switch(avctx->codec->id) {



    case CODEC_ID_ROQ_DPCM:

        buf += 6;



        if (stereo) {

            predictor[1] = (int16_t)(bytestream_get_byte(&buf) << 8);

            predictor[0] = (int16_t)(bytestream_get_byte(&buf) << 8);

        } else {

            predictor[0] = (int16_t)bytestream_get_le16(&buf);

        }



        /* decode the samples */

        while (buf < buf_end) {

            predictor[ch] += s->roq_square_array[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_INTERPLAY_DPCM:

        buf += 6;  /* skip over the stream mask and stream length */



        for (ch = 0; ch < s->channels; ch++) {

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);

            *output_samples++ = predictor[ch];

        }



        ch = 0;

        while (buf < buf_end) {

            predictor[ch] += interplay_delta_table[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_XAN_DPCM:

    {

        int shift[2] = { 4, 4 };



        for (ch = 0; ch < s->channels; ch++)

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);



        ch = 0;

        while (buf < buf_end) {

            uint8_t n = *buf++;

            int16_t diff = (n & 0xFC) << 8;

            if ((n & 0x03) == 3)

                shift[ch]++;

            else

                shift[ch] -= (2 * (n & 3));

            /* saturate the shifter to a lower limit of 0 */

            if (shift[ch] < 0)

                shift[ch] = 0;



            diff >>= shift[ch];

            predictor[ch] += diff;



            predictor[ch] = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;

    }

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3) {

            uint8_t *output_samples_u8 = data;

            while (buf < buf_end) {

                uint8_t n = *buf++;



                s->sample[0] += s->sol_table[n >> 4];

                s->sample[0]  = av_clip_uint8(s->sample[0]);

                *output_samples_u8++ = s->sample[0];



                s->sample[stereo] += s->sol_table[n & 0x0F];

                s->sample[stereo]  = av_clip_uint8(s->sample[stereo]);

                *output_samples_u8++ = s->sample[stereo];

            }

        } else {

            while (buf < buf_end) {

                uint8_t n = *buf++;

                if (n & 0x80) s->sample[ch] -= sol_table_16[n & 0x7F];

                else          s->sample[ch] += sol_table_16[n & 0x7F];

                s->sample[ch] = av_clip_int16(s->sample[ch]);

                *output_samples++ = s->sample[ch];

                /* toggle channel */

                ch ^= stereo;

            }

        }

        break;

    }



    *data_size = out;

    return buf_size;

}

static int pcm_decode_frame(AVCodecContext *avctx,
			    void *data, int *data_size,
			    uint8_t *buf, int buf_size)
{
    PCMDecode *s = avctx->priv_data;
    int n;
    short *samples;
    uint8_t *src;
    samples = data;
    src = buf;
    switch(avctx->codec->id) {
    case CODEC_ID_PCM_S16LE:
        n = buf_size >> 1;
        for(;n>0;n--) {
            *samples++ = src[0] | (src[1] << 8);
            src += 2;
        }
        break;
    case CODEC_ID_PCM_S16BE:
        n = buf_size >> 1;
        for(;n>0;n--) {
            *samples++ = (src[0] << 8) | src[1];
            src += 2;
        }
        break;
    case CODEC_ID_PCM_U16LE:
        n = buf_size >> 1;
        for(;n>0;n--) {
            *samples++ = (src[0] | (src[1] << 8)) - 0x8000;
            src += 2;
        }
        break;
    case CODEC_ID_PCM_U16BE:
        n = buf_size >> 1;
        for(;n>0;n--) {
            *samples++ = ((src[0] << 8) | src[1]) - 0x8000;
            src += 2;
        }
        break;
    case CODEC_ID_PCM_S8:
        n = buf_size;
        for(;n>0;n--) {
            *samples++ = src[0] << 8;
            src++;
        }
        break;
    case CODEC_ID_PCM_U8:
        n = buf_size;
        for(;n>0;n--) {
            *samples++ = ((int)src[0] - 128) << 8;
            src++;
        }
        break;
    case CODEC_ID_PCM_ALAW:
    case CODEC_ID_PCM_MULAW:
        n = buf_size;
        for(;n>0;n--) {
            *samples++ = s->table[src[0]];
            src++;
        }
        break;
    default:
        return -1;
    }
    *data_size = (uint8_t *)samples - (uint8_t *)data;
    return src - buf;
}

static int parse_dsd_prop(AVFormatContext *s, AVStream *st, uint64_t eof)

{

    AVIOContext *pb = s->pb;

    char abss[24];

    int hour, min, sec, i, ret, config;

    int dsd_layout[6];

    ID3v2ExtraMeta *id3v2_extra_meta;



    while (avio_tell(pb) + 12 <= eof) {

        uint32_t tag      = avio_rl32(pb);

        uint64_t size     = avio_rb64(pb);

        uint64_t orig_pos = avio_tell(pb);



        switch(tag) {

        case MKTAG('A','B','S','S'):

            if (size < 8)

                return AVERROR_INVALIDDATA;

            hour = avio_rb16(pb);

            min  = avio_r8(pb);

            sec  = avio_r8(pb);

            snprintf(abss, sizeof(abss), "%02dh:%02dm:%02ds:%d", hour, min, sec, avio_rb32(pb));

            av_dict_set(&st->metadata, "absolute_start_time", abss, 0);

            break;



        case MKTAG('C','H','N','L'):

            if (size < 2)

                return AVERROR_INVALIDDATA;

            st->codecpar->channels       = avio_rb16(pb);

            if (size < 2 + st->codecpar->channels * 4)

                return AVERROR_INVALIDDATA;

            st->codecpar->channel_layout = 0;

            if (st->codecpar->channels > FF_ARRAY_ELEMS(dsd_layout)) {

                avpriv_request_sample(s, "channel layout");

                break;

            }

            for (i = 0; i < st->codecpar->channels; i++)

                dsd_layout[i] = avio_rl32(pb);

            for (i = 0; i < FF_ARRAY_ELEMS(dsd_channel_layout); i++) {

                const DSDLayoutDesc * d = &dsd_channel_layout[i];

                if (av_get_channel_layout_nb_channels(d->layout) == st->codecpar->channels &&

                    !memcmp(d->dsd_layout, dsd_layout, st->codecpar->channels * sizeof(uint32_t))) {

                    st->codecpar->channel_layout = d->layout;

                    break;

                }

            }

            break;



        case MKTAG('C','M','P','R'):

            if (size < 4)

                return AVERROR_INVALIDDATA;

            tag = avio_rl32(pb);

            st->codecpar->codec_id = ff_codec_get_id(dsd_codec_tags, tag);

            if (!st->codecpar->codec_id) {

                av_log(s, AV_LOG_ERROR, "'%c%c%c%c' compression is not supported\n",

                    tag&0xFF, (tag>>8)&0xFF, (tag>>16)&0xFF, (tag>>24)&0xFF);

                return AVERROR_PATCHWELCOME;

            }

            break;



        case MKTAG('F','S',' ',' '):

            if (size < 4)

                return AVERROR_INVALIDDATA;

            st->codecpar->sample_rate = avio_rb32(pb) / 8;

            break;



        case MKTAG('I','D','3',' '):

            id3v2_extra_meta = NULL;

            ff_id3v2_read(s, ID3v2_DEFAULT_MAGIC, &id3v2_extra_meta, size);

            if (id3v2_extra_meta) {

                if ((ret = ff_id3v2_parse_apic(s, &id3v2_extra_meta)) < 0) {

                    ff_id3v2_free_extra_meta(&id3v2_extra_meta);

                    return ret;

                }

                ff_id3v2_free_extra_meta(&id3v2_extra_meta);

            }



            if (size < avio_tell(pb) - orig_pos) {

                av_log(s, AV_LOG_ERROR, "id3 exceeds chunk size\n");

                return AVERROR_INVALIDDATA;

            }

            break;



        case MKTAG('L','S','C','O'):

            if (size < 2)

                return AVERROR_INVALIDDATA;

            config = avio_rb16(pb);

            if (config != 0xFFFF) {

                if (config < FF_ARRAY_ELEMS(dsd_loudspeaker_config))

                    st->codecpar->channel_layout = dsd_loudspeaker_config[config];

                if (!st->codecpar->channel_layout)

                    avpriv_request_sample(s, "loudspeaker configuration %d", config);

            }

            break;

        }



        avio_skip(pb, size - (avio_tell(pb) - orig_pos) + (size & 1));

    }



    return 0;

}

int ff_mov_read_stsd_entries(MOVContext *c, AVIOContext *pb, int entries)

{

    AVStream *st;

    MOVStreamContext *sc;

    int j, pseudo_stream_id;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    for (pseudo_stream_id=0; pseudo_stream_id<entries; pseudo_stream_id++) {

        //Parsing Sample description table

        enum CodecID id;

        int dref_id = 1;

        MOVAtom a = { AV_RL32("stsd") };

        int64_t start_pos = avio_tell(pb);

        int size = avio_rb32(pb); /* size */

        uint32_t format = avio_rl32(pb); /* data format */



        if (size >= 16) {

            avio_rb32(pb); /* reserved */

            avio_rb16(pb); /* reserved */

            dref_id = avio_rb16(pb);




        }



        if (st->codec->codec_tag &&

            st->codec->codec_tag != format &&

            (c->fc->video_codec_id ? ff_codec_get_id(codec_movvideo_tags, format) != c->fc->video_codec_id

                                   : st->codec->codec_tag != MKTAG('j','p','e','g'))

           ){

            /* Multiple fourcc, we skip JPEG. This is not correct, we should

             * export it as a separate AVStream but this needs a few changes

             * in the MOV demuxer, patch welcome. */

        multiple_stsd:

            av_log(c->fc, AV_LOG_WARNING, "multiple fourcc not supported\n");

            avio_skip(pb, size - (avio_tell(pb) - start_pos));

            continue;

        }

        /* we cannot demux concatenated h264 streams because of different extradata */

        if (st->codec->codec_tag && st->codec->codec_tag == AV_RL32("avc1"))

            goto multiple_stsd;

        sc->pseudo_stream_id = st->codec->codec_tag ? -1 : pseudo_stream_id;

        sc->dref_id= dref_id;



        st->codec->codec_tag = format;

        id = ff_codec_get_id(codec_movaudio_tags, format);

        if (id<=0 && ((format&0xFFFF) == 'm'+('s'<<8) || (format&0xFFFF) == 'T'+('S'<<8)))

            id = ff_codec_get_id(ff_codec_wav_tags, av_bswap32(format)&0xFFFF);



        if (st->codec->codec_type != AVMEDIA_TYPE_VIDEO && id > 0) {

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        } else if (st->codec->codec_type != AVMEDIA_TYPE_AUDIO && /* do not overwrite codec type */

                   format && format != MKTAG('m','p','4','s')) { /* skip old asf mpeg4 tag */

            id = ff_codec_get_id(codec_movvideo_tags, format);

            if (id <= 0)

                id = ff_codec_get_id(ff_codec_bmp_tags, format);

            if (id > 0)

                st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

            else if (st->codec->codec_type == AVMEDIA_TYPE_DATA){

                id = ff_codec_get_id(ff_codec_movsubtitle_tags, format);

                if (id > 0)

                    st->codec->codec_type = AVMEDIA_TYPE_SUBTITLE;

            }

        }



        av_dlog(c->fc, "size=%d 4CC= %c%c%c%c codec_type=%d\n", size,

                (format >> 0) & 0xff, (format >> 8) & 0xff, (format >> 16) & 0xff,

                (format >> 24) & 0xff, st->codec->codec_type);



        if (st->codec->codec_type==AVMEDIA_TYPE_VIDEO) {

            unsigned int color_depth, len;

            int color_greyscale;



            st->codec->codec_id = id;

            avio_rb16(pb); /* version */

            avio_rb16(pb); /* revision level */

            avio_rb32(pb); /* vendor */

            avio_rb32(pb); /* temporal quality */

            avio_rb32(pb); /* spatial quality */



            st->codec->width = avio_rb16(pb); /* width */

            st->codec->height = avio_rb16(pb); /* height */



            avio_rb32(pb); /* horiz resolution */

            avio_rb32(pb); /* vert resolution */

            avio_rb32(pb); /* data size, always 0 */

            avio_rb16(pb); /* frames per samples */



            len = avio_r8(pb); /* codec name, pascal string */

            if (len > 31)

                len = 31;

            mov_read_mac_string(c, pb, len, st->codec->codec_name, 32);

            if (len < 31)

                avio_skip(pb, 31 - len);

            /* codec_tag YV12 triggers an UV swap in rawdec.c */

            if (!memcmp(st->codec->codec_name, "Planar Y'CbCr 8-bit 4:2:0", 25))

                st->codec->codec_tag=MKTAG('I', '4', '2', '0');



            st->codec->bits_per_coded_sample = avio_rb16(pb); /* depth */

            st->codec->color_table_id = avio_rb16(pb); /* colortable id */

            av_dlog(c->fc, "depth %d, ctab id %d\n",

                   st->codec->bits_per_coded_sample, st->codec->color_table_id);

            /* figure out the palette situation */

            color_depth = st->codec->bits_per_coded_sample & 0x1F;

            color_greyscale = st->codec->bits_per_coded_sample & 0x20;



            /* if the depth is 2, 4, or 8 bpp, file is palettized */

            if ((color_depth == 2) || (color_depth == 4) ||

                (color_depth == 8)) {

                /* for palette traversal */

                unsigned int color_start, color_count, color_end;

                unsigned char r, g, b;



                if (color_greyscale) {

                    int color_index, color_dec;

                    /* compute the greyscale palette */

                    st->codec->bits_per_coded_sample = color_depth;

                    color_count = 1 << color_depth;

                    color_index = 255;

                    color_dec = 256 / (color_count - 1);

                    for (j = 0; j < color_count; j++) {

                        if (id == CODEC_ID_CINEPAK){

                            r = g = b = color_count - 1 - color_index;

                        }else

                        r = g = b = color_index;

                        sc->palette[j] =

                            (r << 16) | (g << 8) | (b);

                        color_index -= color_dec;

                        if (color_index < 0)

                            color_index = 0;

                    }

                } else if (st->codec->color_table_id) {

                    const uint8_t *color_table;

                    /* if flag bit 3 is set, use the default palette */

                    color_count = 1 << color_depth;

                    if (color_depth == 2)

                        color_table = ff_qt_default_palette_4;

                    else if (color_depth == 4)

                        color_table = ff_qt_default_palette_16;

                    else

                        color_table = ff_qt_default_palette_256;



                    for (j = 0; j < color_count; j++) {

                        r = color_table[j * 3 + 0];

                        g = color_table[j * 3 + 1];

                        b = color_table[j * 3 + 2];

                        sc->palette[j] =

                            (r << 16) | (g << 8) | (b);

                    }

                } else {

                    /* load the palette from the file */

                    color_start = avio_rb32(pb);

                    color_count = avio_rb16(pb);

                    color_end = avio_rb16(pb);

                    if ((color_start <= 255) &&

                        (color_end <= 255)) {

                        for (j = color_start; j <= color_end; j++) {

                            /* each R, G, or B component is 16 bits;

                             * only use the top 8 bits; skip alpha bytes

                             * up front */

                            avio_r8(pb);

                            avio_r8(pb);

                            r = avio_r8(pb);

                            avio_r8(pb);

                            g = avio_r8(pb);

                            avio_r8(pb);

                            b = avio_r8(pb);

                            avio_r8(pb);

                            sc->palette[j] =

                                (r << 16) | (g << 8) | (b);

                        }

                    }

                }

                sc->has_palette = 1;

            }

        } else if (st->codec->codec_type==AVMEDIA_TYPE_AUDIO) {

            int bits_per_sample, flags;

            uint16_t version = avio_rb16(pb);



            st->codec->codec_id = id;

            avio_rb16(pb); /* revision level */

            avio_rb32(pb); /* vendor */



            st->codec->channels = avio_rb16(pb);             /* channel count */

            av_dlog(c->fc, "audio channels %d\n", st->codec->channels);

            st->codec->bits_per_coded_sample = avio_rb16(pb);      /* sample size */



            sc->audio_cid = avio_rb16(pb);

            avio_rb16(pb); /* packet size = 0 */



            st->codec->sample_rate = ((avio_rb32(pb) >> 16));



            //Read QT version 1 fields. In version 0 these do not exist.

            av_dlog(c->fc, "version =%d, isom =%d\n",version,c->isom);

            if (!c->isom) {

                if (version==1) {

                    sc->samples_per_frame = avio_rb32(pb);

                    avio_rb32(pb); /* bytes per packet */

                    sc->bytes_per_frame = avio_rb32(pb);

                    avio_rb32(pb); /* bytes per sample */

                } else if (version==2) {

                    avio_rb32(pb); /* sizeof struct only */

                    st->codec->sample_rate = av_int2double(avio_rb64(pb)); /* float 64 */

                    st->codec->channels = avio_rb32(pb);

                    avio_rb32(pb); /* always 0x7F000000 */

                    st->codec->bits_per_coded_sample = avio_rb32(pb); /* bits per channel if sound is uncompressed */

                    flags = avio_rb32(pb); /* lpcm format specific flag */

                    sc->bytes_per_frame = avio_rb32(pb); /* bytes per audio packet if constant */

                    sc->samples_per_frame = avio_rb32(pb); /* lpcm frames per audio packet if constant */

                    if (format == MKTAG('l','p','c','m'))

                        st->codec->codec_id = ff_mov_get_lpcm_codec_id(st->codec->bits_per_coded_sample, flags);

                }

            }



            switch (st->codec->codec_id) {

            case CODEC_ID_PCM_S8:

            case CODEC_ID_PCM_U8:

                if (st->codec->bits_per_coded_sample == 16)

                    st->codec->codec_id = CODEC_ID_PCM_S16BE;

                break;

            case CODEC_ID_PCM_S16LE:

            case CODEC_ID_PCM_S16BE:

                if (st->codec->bits_per_coded_sample == 8)

                    st->codec->codec_id = CODEC_ID_PCM_S8;

                else if (st->codec->bits_per_coded_sample == 24)

                    st->codec->codec_id =

                        st->codec->codec_id == CODEC_ID_PCM_S16BE ?

                        CODEC_ID_PCM_S24BE : CODEC_ID_PCM_S24LE;

                break;

            /* set values for old format before stsd version 1 appeared */

            case CODEC_ID_MACE3:

                sc->samples_per_frame = 6;

                sc->bytes_per_frame = 2*st->codec->channels;

                break;

            case CODEC_ID_MACE6:

                sc->samples_per_frame = 6;

                sc->bytes_per_frame = 1*st->codec->channels;

                break;

            case CODEC_ID_ADPCM_IMA_QT:

                sc->samples_per_frame = 64;

                sc->bytes_per_frame = 34*st->codec->channels;

                break;

            case CODEC_ID_GSM:

                sc->samples_per_frame = 160;

                sc->bytes_per_frame = 33;

                break;

            default:

                break;

            }



            bits_per_sample = av_get_bits_per_sample(st->codec->codec_id);

            if (bits_per_sample) {

                st->codec->bits_per_coded_sample = bits_per_sample;

                sc->sample_size = (bits_per_sample >> 3) * st->codec->channels;

            }

        } else if (st->codec->codec_type==AVMEDIA_TYPE_SUBTITLE){

            // ttxt stsd contains display flags, justification, background

            // color, fonts, and default styles, so fake an atom to read it

            MOVAtom fake_atom = { .size = size - (avio_tell(pb) - start_pos) };

            if (format != AV_RL32("mp4s")) // mp4s contains a regular esds atom

                mov_read_glbl(c, pb, fake_atom);

            st->codec->codec_id= id;

            st->codec->width = sc->width;

            st->codec->height = sc->height;

        } else {

            if (st->codec->codec_tag == MKTAG('t','m','c','d')) {

                int val;

                avio_rb32(pb);       /* reserved */

                val = avio_rb32(pb); /* flags */

                if (val & 1)

                    st->codec->flags2 |= CODEC_FLAG2_DROP_FRAME_TIMECODE;

                avio_rb32(pb);

                avio_rb32(pb);

                st->codec->time_base.den = avio_r8(pb);

                st->codec->time_base.num = 1;

            }

            /* other codec type, just skip (rtp, mp4s, ...) */

            avio_skip(pb, size - (avio_tell(pb) - start_pos));

        }

        /* this will read extra atoms at the end (wave, alac, damr, avcC, SMI ...) */

        a.size = size - (avio_tell(pb) - start_pos);

        if (a.size > 8) {

            if (mov_read_default(c, pb, a) < 0)


        } else if (a.size > 0)

            avio_skip(pb, a.size);

    }



    if (st->codec->codec_type==AVMEDIA_TYPE_AUDIO && st->codec->sample_rate==0 && sc->time_scale>1)

        st->codec->sample_rate= sc->time_scale;



    /* special codec parameters handling */

    switch (st->codec->codec_id) {

#if CONFIG_DV_DEMUXER

    case CODEC_ID_DVAUDIO:

        c->dv_fctx = avformat_alloc_context();

        c->dv_demux = avpriv_dv_init_demux(c->dv_fctx);

        if (!c->dv_demux) {

            av_log(c->fc, AV_LOG_ERROR, "dv demux context init error\n");


        }

        sc->dv_audio_container = 1;

        st->codec->codec_id = CODEC_ID_PCM_S16LE;

        break;

#endif

    /* no ifdef since parameters are always those */

    case CODEC_ID_QCELP:

        // force sample rate for qcelp when not stored in mov

        if (st->codec->codec_tag != MKTAG('Q','c','l','p'))

            st->codec->sample_rate = 8000;

        st->codec->frame_size= 160;

        st->codec->channels= 1; /* really needed */

        break;

    case CODEC_ID_AMR_NB:

        st->codec->channels= 1; /* really needed */

        /* force sample rate for amr, stsd in 3gp does not store sample rate */

        st->codec->sample_rate = 8000;

        /* force frame_size, too, samples_per_frame isn't always set properly */

        st->codec->frame_size  = 160;

        break;

    case CODEC_ID_AMR_WB:

        st->codec->channels    = 1;

        st->codec->sample_rate = 16000;

        st->codec->frame_size  = 320;

        break;

    case CODEC_ID_MP2:

    case CODEC_ID_MP3:

        st->codec->codec_type = AVMEDIA_TYPE_AUDIO; /* force type after stsd for m1a hdlr */

        st->need_parsing = AVSTREAM_PARSE_FULL;

        break;

    case CODEC_ID_GSM:

    case CODEC_ID_ADPCM_MS:

    case CODEC_ID_ADPCM_IMA_WAV:

        st->codec->frame_size = sc->samples_per_frame;

        st->codec->block_align = sc->bytes_per_frame;

        break;

    case CODEC_ID_ALAC:

        if (st->codec->extradata_size == 36) {

            st->codec->frame_size = AV_RB32(st->codec->extradata+12);

            st->codec->channels   = AV_RB8 (st->codec->extradata+21);

            st->codec->sample_rate = AV_RB32(st->codec->extradata+32);

        }

        break;

    case CODEC_ID_AC3:

        st->need_parsing = AVSTREAM_PARSE_FULL;

        break;

    case CODEC_ID_MPEG1VIDEO:

        st->need_parsing = AVSTREAM_PARSE_FULL;

        break;

    default:

        break;

    }



    return 0;

}

static int rm_read_index(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    unsigned int size, n_pkts, str_id, next_off, n, pos, pts;

    AVStream *st;



    do {

        if (avio_rl32(pb) != MKTAG('I','N','D','X'))

            return -1;

        size     = avio_rb32(pb);

        if (size < 20)

            return -1;

        avio_skip(pb, 2);

        n_pkts   = avio_rb32(pb);

        str_id   = avio_rb16(pb);

        next_off = avio_rb32(pb);

        for (n = 0; n < s->nb_streams; n++)

            if (s->streams[n]->id == str_id) {

                st = s->streams[n];

                break;

            }

        if (n == s->nb_streams)

            goto skip;



        for (n = 0; n < n_pkts; n++) {

            avio_skip(pb, 2);

            pts = avio_rb32(pb);

            pos = avio_rb32(pb);

            avio_skip(pb, 4); /* packet no. */



            av_add_index_entry(st, pos, pts, 0, 0, AVINDEX_KEYFRAME);

        }



skip:

        if (next_off && avio_tell(pb) != next_off &&

            avio_seek(pb, next_off, SEEK_SET) < 0)

            return -1;

    } while (next_off);



    return 0;

}

static int flv_data_packet(AVFormatContext *s, AVPacket *pkt,

                           int64_t dts, int64_t next)

{

    AVIOContext *pb = s->pb;

    AVStream *st    = NULL;

    char buf[20];

    int ret = AVERROR_INVALIDDATA;

    int i, length = -1;



    switch (avio_r8(pb)) {

    case AMF_DATA_TYPE_MIXEDARRAY:

        avio_seek(pb, 4, SEEK_CUR);

    case AMF_DATA_TYPE_OBJECT:

        break;

    default:

        goto skip;

    }



    while ((ret = amf_get_string(pb, buf, sizeof(buf))) > 0) {

        AMFDataType type = avio_r8(pb);

        if (type == AMF_DATA_TYPE_STRING && !strcmp(buf, "text")) {

            length = avio_rb16(pb);

            ret    = av_get_packet(pb, pkt, length);

            if (ret < 0)

                goto skip;

            else

                break;

        } else {

            if ((ret = amf_skip_tag(pb, type)) < 0)

                goto skip;

        }

    }



    if (length < 0) {

        ret = AVERROR_INVALIDDATA;

        goto skip;

    }



    for (i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_DATA)

            break;

    }



    if (i == s->nb_streams) {

        st = create_stream(s, AVMEDIA_TYPE_DATA);

        if (!st)

            return AVERROR_INVALIDDATA;

        st->codec->codec_id = AV_CODEC_ID_TEXT;

    }



    pkt->dts  = dts;

    pkt->pts  = dts;

    pkt->size = ret;



    pkt->stream_index = st->index;

    pkt->flags       |= AV_PKT_FLAG_KEY;



skip:

    avio_seek(s->pb, next + 4, SEEK_SET);



    return ret;

}

static sd_rsp_type_t sd_app_command(SDState *sd,

                                    SDRequest req)

{

    DPRINTF("ACMD%d 0x%08x\n", req.cmd, req.arg);

    switch (req.cmd) {

    case 6:	/* ACMD6:  SET_BUS_WIDTH */

        switch (sd->state) {

        case sd_transfer_state:

            sd->sd_status[0] &= 0x3f;

            sd->sd_status[0] |= (req.arg & 0x03) << 6;

            return sd_r1;



        default:

            break;

        }

        break;



    case 13:	/* ACMD13: SD_STATUS */

        switch (sd->state) {

        case sd_transfer_state:

            sd->state = sd_sendingdata_state;

            sd->data_start = 0;

            sd->data_offset = 0;

            return sd_r1;



        default:

            break;

        }

        break;



    case 22:	/* ACMD22: SEND_NUM_WR_BLOCKS */

        switch (sd->state) {

        case sd_transfer_state:

            *(uint32_t *) sd->data = sd->blk_written;



            sd->state = sd_sendingdata_state;

            sd->data_start = 0;

            sd->data_offset = 0;

            return sd_r1;



        default:

            break;

        }

        break;



    case 23:	/* ACMD23: SET_WR_BLK_ERASE_COUNT */

        switch (sd->state) {

        case sd_transfer_state:

            return sd_r1;



        default:

            break;

        }

        break;



    case 41:	/* ACMD41: SD_APP_OP_COND */

        if (sd->spi) {

            /* SEND_OP_CMD */

            sd->state = sd_transfer_state;

            return sd_r1;

        }

        switch (sd->state) {

        case sd_idle_state:

            /* We accept any voltage.  10000 V is nothing.  */

            if (req.arg)

                sd->state = sd_ready_state;



            return sd_r3;



        default:

            break;

        }

        break;



    case 42:	/* ACMD42: SET_CLR_CARD_DETECT */

        switch (sd->state) {

        case sd_transfer_state:

            /* Bringing in the 50KOhm pull-up resistor... Done.  */

            return sd_r1;



        default:

            break;

        }

        break;



    case 51:	/* ACMD51: SEND_SCR */

        switch (sd->state) {

        case sd_transfer_state:

            sd->state = sd_sendingdata_state;

            sd->data_start = 0;

            sd->data_offset = 0;

            return sd_r1;



        default:

            break;

        }

        break;



    default:

        /* Fall back to standard commands.  */

        sd->card_status &= ~APP_CMD;

        return sd_normal_command(sd, req);

    }



    fprintf(stderr, "SD: ACMD%i in a wrong state\n", req.cmd);

    return sd_illegal;

}

static sd_rsp_type_t sd_normal_command(SDState *sd,
                                       SDRequest req)
{
    uint32_t rca = 0x0000;
    uint64_t addr = (sd->ocr & (1 << 30)) ? (uint64_t) req.arg << 9 : req.arg;
    if (sd_cmd_type[req.cmd] == sd_ac || sd_cmd_type[req.cmd] == sd_adtc)
        rca = req.arg >> 16;
    DPRINTF("CMD%d 0x%08x state %d\n", req.cmd, req.arg, sd->state);
    switch (req.cmd) {
    /* Basic commands (Class 0 and Class 1) */
    case 0:	/* CMD0:   GO_IDLE_STATE */
        switch (sd->state) {
        case sd_inactive_state:
            return sd->spi ? sd_r1 : sd_r0;
        default:
            sd->state = sd_idle_state;
            sd_reset(sd, sd->bdrv);
            return sd->spi ? sd_r1 : sd_r0;
        }
        break;
    case 1:	/* CMD1:   SEND_OP_CMD */
        if (!sd->spi)
            goto bad_cmd;
        sd->state = sd_transfer_state;
        return sd_r1;
    case 2:	/* CMD2:   ALL_SEND_CID */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->state) {
        case sd_ready_state:
            sd->state = sd_identification_state;
            return sd_r2_i;
        default:
            break;
        }
        break;
    case 3:	/* CMD3:   SEND_RELATIVE_ADDR */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->state) {
        case sd_identification_state:
        case sd_standby_state:
            sd->state = sd_standby_state;
            sd_set_rca(sd);
            return sd_r6;
        default:
            break;
        }
        break;
    case 4:	/* CMD4:   SEND_DSR */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->state) {
        case sd_standby_state:
            break;
        default:
            break;
        }
        break;
    case 5: /* CMD5: reserved for SDIO cards */
    case 6:	/* CMD6:   SWITCH_FUNCTION */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->mode) {
        case sd_data_transfer_mode:
            sd_function_switch(sd, req.arg);
            sd->state = sd_sendingdata_state;
            sd->data_start = 0;
            sd->data_offset = 0;
            return sd_r1;
        default:
            break;
        }
        break;
    case 7:	/* CMD7:   SELECT/DESELECT_CARD */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->state) {
        case sd_standby_state:
            if (sd->rca != rca)
            sd->state = sd_transfer_state;
            return sd_r1b;
        case sd_transfer_state:
        case sd_sendingdata_state:
            if (sd->rca == rca)
                break;
            sd->state = sd_standby_state;
            return sd_r1b;
        case sd_disconnect_state:
            if (sd->rca != rca)
            sd->state = sd_programming_state;
            return sd_r1b;
        case sd_programming_state:
            if (sd->rca == rca)
                break;
            sd->state = sd_disconnect_state;
            return sd_r1b;
        default:
            break;
        }
        break;
    case 8:	/* CMD8:   SEND_IF_COND */
        /* Physical Layer Specification Version 2.00 command */
        switch (sd->state) {
        case sd_idle_state:
            sd->vhs = 0;
            /* No response if not exactly one VHS bit is set.  */
            if (!(req.arg >> 8) || (req.arg >> ffs(req.arg & ~0xff)))
                return sd->spi ? sd_r7 : sd_r0;
            /* Accept.  */
            sd->vhs = req.arg;
            return sd_r7;
        default:
            break;
        }
        break;
    case 9:	/* CMD9:   SEND_CSD */
        switch (sd->state) {
        case sd_standby_state:
            if (sd->rca != rca)
            return sd_r2_s;
        case sd_transfer_state:
            if (!sd->spi)
                break;
            sd->state = sd_sendingdata_state;
            memcpy(sd->data, sd->csd, 16);
            sd->data_start = addr;
            sd->data_offset = 0;
            return sd_r1;
        default:
            break;
        }
        break;
    case 10:	/* CMD10:  SEND_CID */
        switch (sd->state) {
        case sd_standby_state:
            if (sd->rca != rca)
            return sd_r2_i;
        case sd_transfer_state:
            if (!sd->spi)
                break;
            sd->state = sd_sendingdata_state;
            memcpy(sd->data, sd->cid, 16);
            sd->data_start = addr;
            sd->data_offset = 0;
            return sd_r1;
        default:
            break;
        }
        break;
    case 11:	/* CMD11:  READ_DAT_UNTIL_STOP */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_sendingdata_state;
            sd->data_start = req.arg;
            sd->data_offset = 0;
            if (sd->data_start + sd->blk_len > sd->size)
                sd->card_status |= ADDRESS_ERROR;
        default:
            break;
        }
        break;
    case 12:	/* CMD12:  STOP_TRANSMISSION */
        switch (sd->state) {
        case sd_sendingdata_state:
            sd->state = sd_transfer_state;
            return sd_r1b;
        case sd_receivingdata_state:
            sd->state = sd_programming_state;
            /* Bzzzzzzztt .... Operation complete.  */
            sd->state = sd_transfer_state;
            return sd_r1b;
        default:
            break;
        }
        break;
    case 13:	/* CMD13:  SEND_STATUS */
        switch (sd->mode) {
        case sd_data_transfer_mode:
            if (sd->rca != rca)
            return sd_r1;
        default:
            break;
        }
        break;
    case 15:	/* CMD15:  GO_INACTIVE_STATE */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->mode) {
        case sd_data_transfer_mode:
            if (sd->rca != rca)
            sd->state = sd_inactive_state;
        default:
            break;
        }
        break;
    /* Block read commands (Classs 2) */
    case 16:	/* CMD16:  SET_BLOCKLEN */
        switch (sd->state) {
        case sd_transfer_state:
            if (req.arg > (1 << HWBLOCK_SHIFT))
                sd->card_status |= BLOCK_LEN_ERROR;
            else
                sd->blk_len = req.arg;
            return sd_r1;
        default:
            break;
        }
        break;
    case 17:	/* CMD17:  READ_SINGLE_BLOCK */
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_sendingdata_state;
            sd->data_start = addr;
            sd->data_offset = 0;
            if (sd->data_start + sd->blk_len > sd->size)
                sd->card_status |= ADDRESS_ERROR;
            return sd_r1;
        default:
            break;
        }
        break;
    case 18:	/* CMD18:  READ_MULTIPLE_BLOCK */
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_sendingdata_state;
            sd->data_start = addr;
            sd->data_offset = 0;
            if (sd->data_start + sd->blk_len > sd->size)
                sd->card_status |= ADDRESS_ERROR;
            return sd_r1;
        default:
            break;
        }
        break;
    /* Block write commands (Class 4) */
    case 24:	/* CMD24:  WRITE_SINGLE_BLOCK */
        if (sd->spi)
            goto unimplemented_cmd;
        switch (sd->state) {
        case sd_transfer_state:
            /* Writing in SPI mode not implemented.  */
            if (sd->spi)
                break;
            sd->state = sd_receivingdata_state;
            sd->data_start = addr;
            sd->data_offset = 0;
            sd->blk_written = 0;
            if (sd->data_start + sd->blk_len > sd->size)
                sd->card_status |= ADDRESS_ERROR;
            if (sd_wp_addr(sd, sd->data_start))
                sd->card_status |= WP_VIOLATION;
            if (sd->csd[14] & 0x30)
                sd->card_status |= WP_VIOLATION;
            return sd_r1;
        default:
            break;
        }
        break;
    case 25:	/* CMD25:  WRITE_MULTIPLE_BLOCK */
        if (sd->spi)
            goto unimplemented_cmd;
        switch (sd->state) {
        case sd_transfer_state:
            /* Writing in SPI mode not implemented.  */
            if (sd->spi)
                break;
            sd->state = sd_receivingdata_state;
            sd->data_start = addr;
            sd->data_offset = 0;
            sd->blk_written = 0;
            if (sd->data_start + sd->blk_len > sd->size)
                sd->card_status |= ADDRESS_ERROR;
            if (sd_wp_addr(sd, sd->data_start))
                sd->card_status |= WP_VIOLATION;
            if (sd->csd[14] & 0x30)
                sd->card_status |= WP_VIOLATION;
            return sd_r1;
        default:
            break;
        }
        break;
    case 26:	/* CMD26:  PROGRAM_CID */
        if (sd->spi)
            goto bad_cmd;
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_receivingdata_state;
            sd->data_start = 0;
            sd->data_offset = 0;
            return sd_r1;
        default:
            break;
        }
        break;
    case 27:	/* CMD27:  PROGRAM_CSD */
        if (sd->spi)
            goto unimplemented_cmd;
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_receivingdata_state;
            sd->data_start = 0;
            sd->data_offset = 0;
            return sd_r1;
        default:
            break;
        }
        break;
    /* Write protection (Class 6) */
    case 28:	/* CMD28:  SET_WRITE_PROT */
        switch (sd->state) {
        case sd_transfer_state:
            if (addr >= sd->size) {
                sd->card_status = ADDRESS_ERROR;
                return sd_r1b;
            }
            sd->state = sd_programming_state;
            sd->wp_groups[addr >> (HWBLOCK_SHIFT +
                            SECTOR_SHIFT + WPGROUP_SHIFT)] = 1;
            /* Bzzzzzzztt .... Operation complete.  */
            sd->state = sd_transfer_state;
            return sd_r1b;
        default:
            break;
        }
        break;
    case 29:	/* CMD29:  CLR_WRITE_PROT */
        switch (sd->state) {
        case sd_transfer_state:
            if (addr >= sd->size) {
                sd->card_status = ADDRESS_ERROR;
                return sd_r1b;
            }
            sd->state = sd_programming_state;
            sd->wp_groups[addr >> (HWBLOCK_SHIFT +
                            SECTOR_SHIFT + WPGROUP_SHIFT)] = 0;
            /* Bzzzzzzztt .... Operation complete.  */
            sd->state = sd_transfer_state;
            return sd_r1b;
        default:
            break;
        }
        break;
    case 30:	/* CMD30:  SEND_WRITE_PROT */
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_sendingdata_state;
            *(uint32_t *) sd->data = sd_wpbits(sd, req.arg);
            sd->data_start = addr;
            sd->data_offset = 0;
            return sd_r1b;
        default:
            break;
        }
        break;
    /* Erase commands (Class 5) */
    case 32:	/* CMD32:  ERASE_WR_BLK_START */
        switch (sd->state) {
        case sd_transfer_state:
            sd->erase_start = req.arg;
            return sd_r1;
        default:
            break;
        }
        break;
    case 33:	/* CMD33:  ERASE_WR_BLK_END */
        switch (sd->state) {
        case sd_transfer_state:
            sd->erase_end = req.arg;
            return sd_r1;
        default:
            break;
        }
        break;
    case 38:	/* CMD38:  ERASE */
        switch (sd->state) {
        case sd_transfer_state:
            if (sd->csd[14] & 0x30) {
                sd->card_status |= WP_VIOLATION;
                return sd_r1b;
            }
            sd->state = sd_programming_state;
            sd_erase(sd);
            /* Bzzzzzzztt .... Operation complete.  */
            sd->state = sd_transfer_state;
            return sd_r1b;
        default:
            break;
        }
        break;
    /* Lock card commands (Class 7) */
    case 42:	/* CMD42:  LOCK_UNLOCK */
        if (sd->spi)
            goto unimplemented_cmd;
        switch (sd->state) {
        case sd_transfer_state:
            sd->state = sd_receivingdata_state;
            sd->data_start = 0;
            sd->data_offset = 0;
            return sd_r1;
        default:
            break;
        }
        break;
    /* Application specific commands (Class 8) */
    case 55:	/* CMD55:  APP_CMD */
        if (sd->rca != rca)
        sd->card_status |= APP_CMD;
        return sd_r1;
    case 56:	/* CMD56:  GEN_CMD */
        fprintf(stderr, "SD: GEN_CMD 0x%08x\n", req.arg);
        switch (sd->state) {
        case sd_transfer_state:
            sd->data_offset = 0;
            if (req.arg & 1)
                sd->state = sd_sendingdata_state;
            else
                sd->state = sd_receivingdata_state;
            return sd_r1;
        default:
            break;
        }
        break;
    default:
    bad_cmd:
        fprintf(stderr, "SD: Unknown CMD%i\n", req.cmd);
    unimplemented_cmd:
        /* Commands that are recognised but not yet implemented in SPI mode.  */
        fprintf(stderr, "SD: CMD%i not implemented in SPI mode\n", req.cmd);
    }
    fprintf(stderr, "SD: CMD%i in a wrong state\n", req.cmd);
}

static sd_rsp_type_t sd_app_command(SDState *sd,

                                    SDRequest req)

{

    DPRINTF("ACMD%d 0x%08x\n", req.cmd, req.arg);

    sd->card_status |= APP_CMD;

    switch (req.cmd) {

    case 6:	/* ACMD6:  SET_BUS_WIDTH */

        switch (sd->state) {

        case sd_transfer_state:

            sd->sd_status[0] &= 0x3f;

            sd->sd_status[0] |= (req.arg & 0x03) << 6;

            return sd_r1;



        default:

            break;

        }

        break;



    case 13:	/* ACMD13: SD_STATUS */

        switch (sd->state) {

        case sd_transfer_state:

            sd->state = sd_sendingdata_state;

            sd->data_start = 0;

            sd->data_offset = 0;

            return sd_r1;



        default:

            break;

        }

        break;



    case 22:	/* ACMD22: SEND_NUM_WR_BLOCKS */

        switch (sd->state) {

        case sd_transfer_state:

            *(uint32_t *) sd->data = sd->blk_written;



            sd->state = sd_sendingdata_state;

            sd->data_start = 0;

            sd->data_offset = 0;

            return sd_r1;



        default:

            break;

        }

        break;



    case 23:	/* ACMD23: SET_WR_BLK_ERASE_COUNT */

        switch (sd->state) {

        case sd_transfer_state:

            return sd_r1;



        default:

            break;

        }

        break;



    case 41:	/* ACMD41: SD_APP_OP_COND */

        if (sd->spi) {

            /* SEND_OP_CMD */

            sd->state = sd_transfer_state;

            return sd_r1;

        }

        switch (sd->state) {

        case sd_idle_state:

            /* We accept any voltage.  10000 V is nothing.

             *

             * We don't model init delay so just advance straight to ready state

             * unless it's an enquiry ACMD41 (bits 23:0 == 0).

             */

            if (req.arg & ACMD41_ENQUIRY_MASK) {

                sd->state = sd_ready_state;

            }



            return sd_r3;



        default:

            break;

        }

        break;



    case 42:	/* ACMD42: SET_CLR_CARD_DETECT */

        switch (sd->state) {

        case sd_transfer_state:

            /* Bringing in the 50KOhm pull-up resistor... Done.  */

            return sd_r1;



        default:

            break;

        }

        break;



    case 51:	/* ACMD51: SEND_SCR */

        switch (sd->state) {

        case sd_transfer_state:

            sd->state = sd_sendingdata_state;

            sd->data_start = 0;

            sd->data_offset = 0;

            return sd_r1;



        default:

            break;

        }

        break;



    default:

        /* Fall back to standard commands.  */

        return sd_normal_command(sd, req);

    }



    fprintf(stderr, "SD: ACMD%i in a wrong state\n", req.cmd);

    return sd_illegal;

}

void sd_write_data(SDState *sd, uint8_t value)

{

    int i;



    if (!sd->bdrv || !bdrv_is_inserted(sd->bdrv) || !sd->enable)

        return;



    if (sd->state != sd_receivingdata_state) {

        fprintf(stderr, "sd_write_data: not in Receiving-Data state\n");

        return;

    }



    if (sd->card_status & (ADDRESS_ERROR | WP_VIOLATION))

        return;



    switch (sd->current_cmd) {

    case 24:	/* CMD24:  WRITE_SINGLE_BLOCK */

        sd->data[sd->data_offset ++] = value;

        if (sd->data_offset >= sd->blk_len) {

            /* TODO: Check CRC before committing */

            sd->state = sd_programming_state;

            BLK_WRITE_BLOCK(sd->data_start, sd->data_offset);

            sd->blk_written ++;

            sd->csd[14] |= 0x40;

            /* Bzzzzzzztt .... Operation complete.  */

            sd->state = sd_transfer_state;

        }

        break;



    case 25:	/* CMD25:  WRITE_MULTIPLE_BLOCK */

        if (sd->data_offset == 0) {

            /* Start of the block - let's check the address is valid */

            if (sd->data_start + sd->blk_len > sd->size) {

                sd->card_status |= ADDRESS_ERROR;

                break;

            }

            if (sd_wp_addr(sd, sd->data_start)) {

                sd->card_status |= WP_VIOLATION;

                break;

            }

        }

        sd->data[sd->data_offset++] = value;

        if (sd->data_offset >= sd->blk_len) {

            /* TODO: Check CRC before committing */

            sd->state = sd_programming_state;

            BLK_WRITE_BLOCK(sd->data_start, sd->data_offset);

            sd->blk_written++;

            sd->data_start += sd->blk_len;

            sd->data_offset = 0;

            sd->csd[14] |= 0x40;



            /* Bzzzzzzztt .... Operation complete.  */

            sd->state = sd_receivingdata_state;

        }

        break;



    case 26:	/* CMD26:  PROGRAM_CID */

        sd->data[sd->data_offset ++] = value;

        if (sd->data_offset >= sizeof(sd->cid)) {

            /* TODO: Check CRC before committing */

            sd->state = sd_programming_state;

            for (i = 0; i < sizeof(sd->cid); i ++)

                if ((sd->cid[i] | 0x00) != sd->data[i])

                    sd->card_status |= CID_CSD_OVERWRITE;



            if (!(sd->card_status & CID_CSD_OVERWRITE))

                for (i = 0; i < sizeof(sd->cid); i ++) {

                    sd->cid[i] |= 0x00;

                    sd->cid[i] &= sd->data[i];

                }

            /* Bzzzzzzztt .... Operation complete.  */

            sd->state = sd_transfer_state;

        }

        break;



    case 27:	/* CMD27:  PROGRAM_CSD */

        sd->data[sd->data_offset ++] = value;

        if (sd->data_offset >= sizeof(sd->csd)) {

            /* TODO: Check CRC before committing */

            sd->state = sd_programming_state;

            for (i = 0; i < sizeof(sd->csd); i ++)

                if ((sd->csd[i] | sd_csd_rw_mask[i]) !=

                    (sd->data[i] | sd_csd_rw_mask[i]))

                    sd->card_status |= CID_CSD_OVERWRITE;



            /* Copy flag (OTP) & Permanent write protect */

            if (sd->csd[14] & ~sd->data[14] & 0x60)

                sd->card_status |= CID_CSD_OVERWRITE;



            if (!(sd->card_status & CID_CSD_OVERWRITE))

                for (i = 0; i < sizeof(sd->csd); i ++) {

                    sd->csd[i] |= sd_csd_rw_mask[i];

                    sd->csd[i] &= sd->data[i];

                }

            /* Bzzzzzzztt .... Operation complete.  */

            sd->state = sd_transfer_state;

        }

        break;



    case 42:	/* CMD42:  LOCK_UNLOCK */

        sd->data[sd->data_offset ++] = value;

        if (sd->data_offset >= sd->blk_len) {

            /* TODO: Check CRC before committing */

            sd->state = sd_programming_state;

            sd_lock_command(sd);

            /* Bzzzzzzztt .... Operation complete.  */

            sd->state = sd_transfer_state;

        }

        break;



    case 56:	/* CMD56:  GEN_CMD */

        sd->data[sd->data_offset ++] = value;

        if (sd->data_offset >= sd->blk_len) {

            APP_WRITE_BLOCK(sd->data_start, sd->data_offset);

            sd->state = sd_transfer_state;

        }

        break;



    default:

        fprintf(stderr, "sd_write_data: unknown command\n");

        break;

    }

}

static int dpcm_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             uint8_t *buf, int buf_size)

{

    DPCMContext *s = avctx->priv_data;

    int in, out = 0;

    int predictor[2];

    int channel_number = 0;

    short *output_samples = data;

    int shift[2];

    unsigned char byte;

    short diff;



    if (!buf_size)

        return 0;



    // almost every DPCM variant expands one byte of data into two

    if(*data_size/2 < buf_size)




    switch(avctx->codec->id) {



    case CODEC_ID_ROQ_DPCM:

        if (s->channels == 1)

            predictor[0] = AV_RL16(&buf[6]);

        else {

            predictor[0] = buf[7] << 8;

            predictor[1] = buf[6] << 8;

        }

        SE_16BIT(predictor[0]);

        SE_16BIT(predictor[1]);



        /* decode the samples */

        for (in = 8, out = 0; in < buf_size; in++, out++) {

            predictor[channel_number] += s->roq_square_array[buf[in]];

            predictor[channel_number] = av_clip_int16(predictor[channel_number]);

            output_samples[out] = predictor[channel_number];



            /* toggle channel */

            channel_number ^= s->channels - 1;

        }

        break;



    case CODEC_ID_INTERPLAY_DPCM:

        in = 6;  /* skip over the stream mask and stream length */

        predictor[0] = AV_RL16(&buf[in]);

        in += 2;

        SE_16BIT(predictor[0])

        output_samples[out++] = predictor[0];

        if (s->channels == 2) {

            predictor[1] = AV_RL16(&buf[in]);

            in += 2;

            SE_16BIT(predictor[1])

            output_samples[out++] = predictor[1];

        }



        while (in < buf_size) {

            predictor[channel_number] += interplay_delta_table[buf[in++]];

            predictor[channel_number] = av_clip_int16(predictor[channel_number]);

            output_samples[out++] = predictor[channel_number];



            /* toggle channel */

            channel_number ^= s->channels - 1;

        }



        break;



    case CODEC_ID_XAN_DPCM:

        in = 0;

        shift[0] = shift[1] = 4;

        predictor[0] = AV_RL16(&buf[in]);

        in += 2;

        SE_16BIT(predictor[0]);

        if (s->channels == 2) {

            predictor[1] = AV_RL16(&buf[in]);

            in += 2;

            SE_16BIT(predictor[1]);

        }



        while (in < buf_size) {

            byte = buf[in++];

            diff = (byte & 0xFC) << 8;

            if ((byte & 0x03) == 3)

                shift[channel_number]++;

            else

                shift[channel_number] -= (2 * (byte & 3));

            /* saturate the shifter to a lower limit of 0 */

            if (shift[channel_number] < 0)

                shift[channel_number] = 0;



            diff >>= shift[channel_number];

            predictor[channel_number] += diff;



            predictor[channel_number] = av_clip_int16(predictor[channel_number]);

            output_samples[out++] = predictor[channel_number];



            /* toggle channel */

            channel_number ^= s->channels - 1;

        }

        break;

    case CODEC_ID_SOL_DPCM:

        in = 0;

        if (avctx->codec_tag != 3) {



            while (in < buf_size) {

                int n1, n2;

                n1 = (buf[in] >> 4) & 0xF;

                n2 = buf[in++] & 0xF;

                s->sample[0] += s->sol_table[n1];

                 if (s->sample[0] < 0) s->sample[0] = 0;

                if (s->sample[0] > 255) s->sample[0] = 255;

                output_samples[out++] = (s->sample[0] - 128) << 8;

                s->sample[s->channels - 1] += s->sol_table[n2];

                if (s->sample[s->channels - 1] < 0) s->sample[s->channels - 1] = 0;

                if (s->sample[s->channels - 1] > 255) s->sample[s->channels - 1] = 255;

                output_samples[out++] = (s->sample[s->channels - 1] - 128) << 8;

            }

        } else {

            while (in < buf_size) {

                int n;

                n = buf[in++];

                if (n & 0x80) s->sample[channel_number] -= s->sol_table[n & 0x7F];

                else s->sample[channel_number] += s->sol_table[n & 0x7F];

                s->sample[channel_number] = av_clip_int16(s->sample[channel_number]);

                output_samples[out++] = s->sample[channel_number];

                /* toggle channel */

                channel_number ^= s->channels - 1;

            }

        }

        break;

    }



    *data_size = out * sizeof(short);

    return buf_size;

}

static int dpcm_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_end = buf + buf_size;

    DPCMContext *s = avctx->priv_data;

    int out = 0, ret;

    int predictor[2];

    int ch = 0;

    int stereo = s->channels - 1;

    int16_t *output_samples;



    /* calculate output size */

    switch(avctx->codec->id) {

    case CODEC_ID_ROQ_DPCM:

        out = buf_size - 8;

        break;

    case CODEC_ID_INTERPLAY_DPCM:

        out = buf_size - 6 - s->channels;

        break;

    case CODEC_ID_XAN_DPCM:

        out = buf_size - 2 * s->channels;

        break;

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3)

            out = buf_size * 2;

        else

            out = buf_size;

        break;

    }

    if (out <= 0) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    s->frame.nb_samples = out / s->channels;

    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    output_samples = (int16_t *)s->frame.data[0];



    switch(avctx->codec->id) {



    case CODEC_ID_ROQ_DPCM:

        buf += 6;



        if (stereo) {

            predictor[1] = (int16_t)(bytestream_get_byte(&buf) << 8);

            predictor[0] = (int16_t)(bytestream_get_byte(&buf) << 8);

        } else {

            predictor[0] = (int16_t)bytestream_get_le16(&buf);

        }



        /* decode the samples */

        while (buf < buf_end) {

            predictor[ch] += s->roq_square_array[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_INTERPLAY_DPCM:

        buf += 6;  /* skip over the stream mask and stream length */



        for (ch = 0; ch < s->channels; ch++) {

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);

            *output_samples++ = predictor[ch];

        }



        ch = 0;

        while (buf < buf_end) {

            predictor[ch] += interplay_delta_table[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_XAN_DPCM:

    {

        int shift[2] = { 4, 4 };



        for (ch = 0; ch < s->channels; ch++)

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);



        ch = 0;

        while (buf < buf_end) {

            uint8_t n = *buf++;

            int16_t diff = (n & 0xFC) << 8;

            if ((n & 0x03) == 3)

                shift[ch]++;

            else

                shift[ch] -= (2 * (n & 3));

            /* saturate the shifter to a lower limit of 0 */

            if (shift[ch] < 0)

                shift[ch] = 0;



            diff >>= shift[ch];

            predictor[ch] += diff;



            predictor[ch] = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;

    }

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3) {

            uint8_t *output_samples_u8 = data;

            while (buf < buf_end) {

                uint8_t n = *buf++;



                s->sample[0] += s->sol_table[n >> 4];

                s->sample[0]  = av_clip_uint8(s->sample[0]);

                *output_samples_u8++ = s->sample[0];



                s->sample[stereo] += s->sol_table[n & 0x0F];

                s->sample[stereo]  = av_clip_uint8(s->sample[stereo]);

                *output_samples_u8++ = s->sample[stereo];

            }

        } else {

            while (buf < buf_end) {

                uint8_t n = *buf++;

                if (n & 0x80) s->sample[ch] -= sol_table_16[n & 0x7F];

                else          s->sample[ch] += sol_table_16[n & 0x7F];

                s->sample[ch] = av_clip_int16(s->sample[ch]);

                *output_samples++ = s->sample[ch];

                /* toggle channel */

                ch ^= stereo;

            }

        }

        break;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

}

