                /* toggle channel */

                ch ^= stereo;

            }

        }

        break;

    }



    *data_size = out;

    return buf_size;

}

static int pnm_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf   = avpkt->data;

    int buf_size         = avpkt->size;

    PNMContext * const s = avctx->priv_data;

    AVFrame * const p    = data;

    int i, j, n, linesize, h, upgrade = 0, is_mono = 0;

    unsigned char *ptr;

    int components, sample_len, ret;

    unsigned int maskval = 0;



    s->bytestream_start =

    s->bytestream       = (uint8_t *)buf;

    s->bytestream_end   = (uint8_t *)buf + buf_size;



    if ((ret = ff_pnm_decode_header(avctx, s)) < 0)

        return ret;



    if ((ret = ff_get_buffer(avctx, p, 0)) < 0)

        return ret;

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;



    switch (avctx->pix_fmt) {

    default:

        return AVERROR(EINVAL);

    case AV_PIX_FMT_RGBA64BE:

        n = avctx->width * 8;

        components=4;

        sample_len=16;

        goto do_read;

    case AV_PIX_FMT_RGB48BE:

        n = avctx->width * 6;

        components=3;

        sample_len=16;

        goto do_read;

    case AV_PIX_FMT_RGBA:

        n = avctx->width * 4;

        components=4;

        sample_len=8;

        goto do_read;

    case AV_PIX_FMT_RGB24:

        n = avctx->width * 3;

        components=3;

        sample_len=8;

        goto do_read;

    case AV_PIX_FMT_GRAY8:

        n = avctx->width;

        components=1;

        sample_len=8;

        if (s->maxval < 255) {

            upgrade = 1;

            maskval = (2 << av_log2(s->maxval)) - 1;

        }

        goto do_read;

    case AV_PIX_FMT_GRAY8A:

        n = avctx->width * 2;

        components=2;

        sample_len=8;

        goto do_read;

    case AV_PIX_FMT_GRAY16BE:

    case AV_PIX_FMT_GRAY16LE:

        n = avctx->width * 2;

        components=1;

        sample_len=16;

        if (s->maxval < 65535) {

            upgrade = 2;

            maskval = (2 << av_log2(s->maxval)) - 1;

        }

        goto do_read;

    case AV_PIX_FMT_MONOWHITE:

    case AV_PIX_FMT_MONOBLACK:

        n = (avctx->width + 7) >> 3;

        components=1;

        sample_len=1;

        is_mono = 1;

    do_read:

        ptr      = p->data[0];

        linesize = p->linesize[0];

        if (s->bytestream + n * avctx->height > s->bytestream_end)

            return AVERROR_INVALIDDATA;

        if(s->type < 4 || (is_mono && s->type==7)){

            for (i=0; i<avctx->height; i++) {

                PutBitContext pb;

                init_put_bits(&pb, ptr, linesize);

                for(j=0; j<avctx->width * components; j++){

                    unsigned int c=0;

                    int v=0;

                    if(s->type < 4)

                    while(s->bytestream < s->bytestream_end && (*s->bytestream < '0' || *s->bytestream > '9' ))

                        s->bytestream++;

                    if(s->bytestream >= s->bytestream_end)

                        return AVERROR_INVALIDDATA;

                    if (is_mono) {

                        /* read a single digit */

                        v = (*s->bytestream++)&1;

                    } else {

                        /* read a sequence of digits */

                        do {

                            v = 10*v + c;

                            c = (*s->bytestream++) - '0';

                        } while (c <= 9);

                    }

                    put_bits(&pb, sample_len, (((1<<sample_len)-1)*v + (s->maxval>>1))/s->maxval);

                }

                flush_put_bits(&pb);

                ptr+= linesize;

            }

        }else{

        for (i = 0; i < avctx->height; i++) {

            if (!upgrade)

                memcpy(ptr, s->bytestream, n);

            else if (upgrade == 1) {

                unsigned int j, f = (255 * 128 + s->maxval / 2) / s->maxval;

                for (j = 0; j < n; j++)

                    ptr[j] = ((s->bytestream[j] & maskval) * f + 64) >> 7;

            } else if (upgrade == 2) {

                unsigned int j, v, f = (65535 * 32768 + s->maxval / 2) / s->maxval;

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]) & maskval;

                    ((uint16_t *)ptr)[j] = (v * f + 16384) >> 15;

                }

            }

            s->bytestream += n;

            ptr           += linesize;

        }

        }

        break;

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV420P9BE:

    case AV_PIX_FMT_YUV420P10BE:

        {

            unsigned char *ptr1, *ptr2;



            n        = avctx->width;

            ptr      = p->data[0];

            linesize = p->linesize[0];

            if (s->maxval >= 256)

                n *= 2;

            if (s->bytestream + n * avctx->height * 3 / 2 > s->bytestream_end)

                return AVERROR_INVALIDDATA;

            for (i = 0; i < avctx->height; i++) {

                memcpy(ptr, s->bytestream, n);

                s->bytestream += n;

                ptr           += linesize;

            }

            ptr1 = p->data[1];

            ptr2 = p->data[2];

            n >>= 1;

            h = avctx->height >> 1;

            for (i = 0; i < h; i++) {

                memcpy(ptr1, s->bytestream, n);

                s->bytestream += n;

                memcpy(ptr2, s->bytestream, n);

                s->bytestream += n;

                ptr1 += p->linesize[1];

                ptr2 += p->linesize[2];

            }

        }

        break;

    case AV_PIX_FMT_YUV420P16:

        {

            uint16_t *ptr1, *ptr2;

            const int f = (65535 * 32768 + s->maxval / 2) / s->maxval;

            unsigned int j, v;



            n        = avctx->width * 2;

            ptr      = p->data[0];

            linesize = p->linesize[0];

            if (s->bytestream + n * avctx->height * 3 / 2 > s->bytestream_end)

                return AVERROR_INVALIDDATA;

            for (i = 0; i < avctx->height; i++) {

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ((uint16_t *)ptr)[j] = (v * f + 16384) >> 15;

                }

                s->bytestream += n;

                ptr           += linesize;

            }

            ptr1 = (uint16_t*)p->data[1];

            ptr2 = (uint16_t*)p->data[2];

            n >>= 1;

            h = avctx->height >> 1;

            for (i = 0; i < h; i++) {

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ptr1[j] = (v * f + 16384) >> 15;

                }

                s->bytestream += n;



                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ptr2[j] = (v * f + 16384) >> 15;

                }

                s->bytestream += n;



                ptr1 += p->linesize[1] / 2;

                ptr2 += p->linesize[2] / 2;

            }

        }

        break;

    }

    *got_frame = 1;



    return s->bytestream - s->bytestream_start;

}

static void mm_decode_inter(MmContext * s, int half_horiz, int half_vert, const uint8_t *buf, int buf_size)
{
    const int data_ptr = 2 + AV_RL16(&buf[0]);
    int d, r, y;
    d = data_ptr; r = 2; y = 0;
    while(r < data_ptr) {
        int i, j;
        int length = buf[r] & 0x7f;
        int x = buf[r+1] + ((buf[r] & 0x80) << 1);
        r += 2;
        if (length==0) {
            y += x;
            continue;
        }
        for(i=0; i<length; i++) {
            for(j=0; j<8; j++) {
                int replace = (buf[r+i] >> (7-j)) & 1;
                if (replace) {
                    int color = buf[d];
                    s->frame.data[0][y*s->frame.linesize[0] + x] = color;
                    if (half_horiz)
                        s->frame.data[0][y*s->frame.linesize[0] + x + 1] = color;
                    if (half_vert) {
                        s->frame.data[0][(y+1)*s->frame.linesize[0] + x] = color;
                        if (half_horiz)
                            s->frame.data[0][(y+1)*s->frame.linesize[0] + x + 1] = color;
                    }
                    d++;
                }
                x += 1 + half_horiz;
            }
        }
        r += length;
        y += 1 + half_vert;
    }
}

static void FUNC(dequant)(int16_t *coeffs, int16_t log2_size)

{

    int shift  = 15 - BIT_DEPTH - log2_size;

    int x, y;

    int size = 1 << log2_size;



    if (shift > 0) {

        int offset = 1 << (shift - 1);

        for (y = 0; y < size; y++) {

            for (x = 0; x < size; x++) {

                *coeffs = (*coeffs + offset) >> shift;

                coeffs++;

            }

        }

    } else {

        for (y = 0; y < size; y++) {

            for (x = 0; x < size; x++) {

                *coeffs = *coeffs << -shift;

                coeffs++;

            }

        }

    }

}

static void mm_decode_inter(MmContext * s, int half_horiz, int half_vert, const uint8_t *buf, int buf_size)

{

    const int data_ptr = 2 + AV_RL16(&buf[0]);

    int d, r, y;

    d = data_ptr; r = 2; y = 0;



    while(r < data_ptr) {

        int i, j;

        int length = buf[r] & 0x7f;

        int x = buf[r+1] + ((buf[r] & 0x80) << 1);

        r += 2;



        if (length==0) {

            y += x;

            continue;

        }



        for(i=0; i<length; i++) {

            for(j=0; j<8; j++) {

                int replace = (buf[r+i] >> (7-j)) & 1;

                if (replace) {

                    int color = buf[d];

                    s->frame.data[0][y*s->frame.linesize[0] + x] = color;

                    if (half_horiz)

                        s->frame.data[0][y*s->frame.linesize[0] + x + 1] = color;

                    if (half_vert) {

                        s->frame.data[0][(y+1)*s->frame.linesize[0] + x] = color;

                        if (half_horiz)

                            s->frame.data[0][(y+1)*s->frame.linesize[0] + x + 1] = color;

                    }

                    d++;

                }

                x += half_horiz ? 2 : 1;

            }

        }



        r += length;

        y += half_vert ? 2 : 1;

    }

}

static void blur(CoverContext *cover, AVFrame *in, int offx, int offy)

{

    int x, y, p;



    for (p=0; p<3; p++) {

        int ox = offx>>!!p;

        int oy = offy>>!!p;

        int stride = in->linesize[p];

        uint8_t *data = in->data[p] + ox + oy * stride;

        int w = FF_CEIL_RSHIFT(cover->width , !!p);

        int h = FF_CEIL_RSHIFT(cover->height, !!p);

        int iw = FF_CEIL_RSHIFT(in->width , !!p);

        int ih = FF_CEIL_RSHIFT(in->height, !!p);

        for (y = 0; y < h; y++) {

            for (x = 0; x < w; x++) {

                int c = 0;

                int s = 0;

                if (ox) {

                    int scale = 65536 / (x + 1);

                    s += data[-1 + y*stride] * scale;

                    c += scale;

                }

                if (oy) {

                    int scale = 65536 / (y + 1);

                    s += data[x - stride] * scale;

                    c += scale;

                }

                if (ox + w < iw) {

                    int scale = 65536 / (w - x);

                    s += data[w + y*stride] * scale;

                    c += scale;

                }

                if (oy + h < ih) {

                    int scale = 65536 / (h - y);

                    s += data[x + h*stride] * scale;

                    c += scale;

                }

                data[x + y*stride] = (s + (c>>1)) / c;

            }

        }

    }

}

static int decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             uint8_t *buf, int buf_size)

{

    H264Context *h = avctx->priv_data;

    MpegEncContext *s = &h->s;

    AVFrame *pict = data;

    int buf_index;



    s->flags= avctx->flags;

    s->flags2= avctx->flags2;



   /* no supplementary picture */

    if (buf_size == 0) {

        return 0;

    }



    if(s->flags&CODEC_FLAG_TRUNCATED){

        int next= find_frame_end(h, buf, buf_size);



        if( ff_combine_frame(&s->parse_context, next, &buf, &buf_size) < 0 )

            return buf_size;

//printf("next:%d buf_size:%d last_index:%d\n", next, buf_size, s->parse_context.last_index);

    }



    if(h->is_avc && !h->got_avcC) {

        int i, cnt, nalsize;

        unsigned char *p = avctx->extradata;

        if(avctx->extradata_size < 7) {

            av_log(avctx, AV_LOG_ERROR, "avcC too short\n");

            return -1;

        }

        if(*p != 1) {

            av_log(avctx, AV_LOG_ERROR, "Unknown avcC version %d\n", *p);

            return -1;

        }

        /* sps and pps in the avcC always have length coded with 2 bytes,

           so put a fake nal_length_size = 2 while parsing them */

        h->nal_length_size = 2;

        // Decode sps from avcC

        cnt = *(p+5) & 0x1f; // Number of sps

        p += 6;

        for (i = 0; i < cnt; i++) {

            nalsize = BE_16(p) + 2;

            if(decode_nal_units(h, p, nalsize) < 0) {

                av_log(avctx, AV_LOG_ERROR, "Decoding sps %d from avcC failed\n", i);

                return -1;

            }

            p += nalsize;

        }

        // Decode pps from avcC

        cnt = *(p++); // Number of pps

        for (i = 0; i < cnt; i++) {

            nalsize = BE_16(p) + 2;

            if(decode_nal_units(h, p, nalsize)  != nalsize) {

                av_log(avctx, AV_LOG_ERROR, "Decoding pps %d from avcC failed\n", i);

                return -1;

            }

            p += nalsize;

        }

        // Now store right nal length size, that will be use to parse all other nals

        h->nal_length_size = ((*(((char*)(avctx->extradata))+4))&0x03)+1;

        // Do not reparse avcC

        h->got_avcC = 1;

    }



    if(!h->is_avc && s->avctx->extradata_size && s->picture_number==0){

        if(decode_nal_units(h, s->avctx->extradata, s->avctx->extradata_size) < 0)

            return -1;

    }



    buf_index=decode_nal_units(h, buf, buf_size);

    if(buf_index < 0)

        return -1;



    //FIXME do something with unavailable reference frames



//    if(ret==FRAME_SKIPPED) return get_consumed_bytes(s, buf_index, buf_size);

    if(!s->current_picture_ptr){

        av_log(h->s.avctx, AV_LOG_DEBUG, "error, NO frame\n");

        return -1;

    }



    {

        Picture *out = s->current_picture_ptr;

#if 0 //decode order

        *data_size = sizeof(AVFrame);

#else

        /* Sort B-frames into display order */

        Picture *cur = s->current_picture_ptr;

        Picture *prev = h->delayed_output_pic;

        int out_idx = 0;

        int pics = 0;

        int out_of_order;

        int cross_idr = 0;

        int dropped_frame = 0;

        int i;



        if(h->sps.bitstream_restriction_flag

           && s->avctx->has_b_frames < h->sps.num_reorder_frames){

            s->avctx->has_b_frames = h->sps.num_reorder_frames;

            s->low_delay = 0;

        }



        while(h->delayed_pic[pics]) pics++;

        h->delayed_pic[pics++] = cur;

        if(cur->reference == 0)

            cur->reference = 1;



        for(i=0; h->delayed_pic[i]; i++)

            if(h->delayed_pic[i]->key_frame || h->delayed_pic[i]->poc==0)

                cross_idr = 1;



        out = h->delayed_pic[0];

        for(i=1; h->delayed_pic[i] && !h->delayed_pic[i]->key_frame; i++)

            if(h->delayed_pic[i]->poc < out->poc){

                out = h->delayed_pic[i];

                out_idx = i;

            }



        out_of_order = !cross_idr && prev && out->poc < prev->poc;

        if(prev && pics <= s->avctx->has_b_frames)

            out = prev;

        else if((out_of_order && pics-1 == s->avctx->has_b_frames && pics < 15)

           || (s->low_delay &&

            ((!cross_idr && prev && out->poc > prev->poc + 2)

             || cur->pict_type == B_TYPE)))

        {

            s->low_delay = 0;

            s->avctx->has_b_frames++;

            out = prev;

        }

        else if(out_of_order)

            out = prev;



        if(out_of_order || pics > s->avctx->has_b_frames){

            dropped_frame = (out != h->delayed_pic[out_idx]);

            for(i=out_idx; h->delayed_pic[i]; i++)

                h->delayed_pic[i] = h->delayed_pic[i+1];

        }



        if(prev == out && !dropped_frame)

            *data_size = 0;

        else

            *data_size = sizeof(AVFrame);

        if(prev && prev != out && prev->reference == 1)

            prev->reference = 0;

        h->delayed_output_pic = out;

#endif



        if(out)

            *pict= *(AVFrame*)out;

        else

            av_log(avctx, AV_LOG_DEBUG, "no picture\n");

    }



    assert(pict->data[0] || !*data_size);

    ff_print_debug_info(s, pict);

//printf("out %d\n", (int)pict->data[0]);

#if 0 //?



    /* Return the Picture timestamp as the frame number */

    /* we substract 1 because it is added on utils.c    */

    avctx->frame_number = s->picture_number - 1;

#endif

    return get_consumed_bytes(s, buf_index, buf_size);

}

int ff_jpegls_decode_picture(MJpegDecodeContext *s, int near,
                             int point_transform, int ilv)
{
    int i, t = 0;
    uint8_t *zero, *last, *cur;
    JLSState *state;
    int off = 0, stride = 1, width, shift, ret = 0;
    zero = av_mallocz(s->picture_ptr->linesize[0]);
    if (!zero)
        return AVERROR(ENOMEM);
    last = zero;
    cur  = s->picture_ptr->data[0];
    state = av_mallocz(sizeof(JLSState));
    if (!state) {
        av_free(zero);
        return AVERROR(ENOMEM);
    /* initialize JPEG-LS state from JPEG parameters */
    state->near   = near;
    state->bpp    = (s->bits < 2) ? 2 : s->bits;
    state->maxval = s->maxval;
    state->T1     = s->t1;
    state->T2     = s->t2;
    state->T3     = s->t3;
    state->reset  = s->reset;
    ff_jpegls_reset_coding_parameters(state, 0);
    ff_jpegls_init_state(state);
    if (s->bits <= 8)
        shift = point_transform + (8 - s->bits);
    else
        shift = point_transform + (16 - s->bits);
    if (s->avctx->debug & FF_DEBUG_PICT_INFO) {
        av_log(s->avctx, AV_LOG_DEBUG,
               "JPEG-LS params: %ix%i NEAR=%i MV=%i T(%i,%i,%i) "
               "RESET=%i, LIMIT=%i, qbpp=%i, RANGE=%i\n",
                s->width, s->height, state->near, state->maxval,
                state->T1, state->T2, state->T3,
                state->reset, state->limit, state->qbpp, state->range);
        av_log(s->avctx, AV_LOG_DEBUG, "JPEG params: ILV=%i Pt=%i BPP=%i, scan = %i\n",
                ilv, point_transform, s->bits, s->cur_scan);
    if (ilv == 0) { /* separate planes */
        if (s->cur_scan > s->nb_components) {
        stride = (s->nb_components > 1) ? 3 : 1;
        off    = av_clip(s->cur_scan - 1, 0, stride - 1);
        width  = s->width * stride;
        cur   += off;
        for (i = 0; i < s->height; i++) {
            if (s->bits <= 8) {
                ls_decode_line(state, s, last, cur, t, width, stride, off, 8);
                t = last[0];
            } else {
                ls_decode_line(state, s, last, cur, t, width, stride, off, 16);
                t = *((uint16_t *)last);
            last = cur;
            cur += s->picture_ptr->linesize[0];
            if (s->restart_interval && !--s->restart_count) {
                align_get_bits(&s->gb);
                skip_bits(&s->gb, 16); /* skip RSTn */
    } else if (ilv == 1) { /* line interleaving */
        int j;
        int Rc[3] = { 0, 0, 0 };
        stride = (s->nb_components > 1) ? 3 : 1;
        memset(cur, 0, s->picture_ptr->linesize[0]);
        width = s->width * stride;
        for (i = 0; i < s->height; i++) {
            for (j = 0; j < stride; j++) {
                ls_decode_line(state, s, last + j, cur + j,
                               Rc[j], width, stride, j, 8);
                Rc[j] = last[j];
                if (s->restart_interval && !--s->restart_count) {
                    align_get_bits(&s->gb);
                    skip_bits(&s->gb, 16); /* skip RSTn */
            last = cur;
            cur += s->picture_ptr->linesize[0];
    } else if (ilv == 2) { /* sample interleaving */
        avpriv_report_missing_feature(s->avctx, "Sample interleaved images");
        ret = AVERROR_PATCHWELCOME;
    if (s->xfrm && s->nb_components == 3) {
        int x, w;
        w = s->width * s->nb_components;
        if (s->bits <= 8) {
            uint8_t *src = s->picture_ptr->data[0];
            for (i = 0; i < s->height; i++) {
                switch(s->xfrm) {
                case 1:
                    for (x = off; x < w; x += 3) {
                        src[x  ] += src[x+1] + 128;
                        src[x+2] += src[x+1] + 128;
                    break;
                case 2:
                    for (x = off; x < w; x += 3) {
                        src[x  ] += src[x+1] + 128;
                        src[x+2] += ((src[x  ] + src[x+1])>>1) + 128;
                    break;
                case 3:
                    for (x = off; x < w; x += 3) {
                        int g = src[x+0] - ((src[x+2]+src[x+1])>>2) + 64;
                        src[x+0] = src[x+2] + g + 128;
                        src[x+2] = src[x+1] + g + 128;
                        src[x+1] = g;
                    break;
                case 4:
                    for (x = off; x < w; x += 3) {
                        int r    = src[x+0] - ((                       359 * (src[x+2]-128) + 490) >> 8);
                        int g    = src[x+0] - (( 88 * (src[x+1]-128) - 183 * (src[x+2]-128) +  30) >> 8);
                        int b    = src[x+0] + ((454 * (src[x+1]-128)                        + 574) >> 8);
                        src[x+0] = av_clip_uint8(r);
                        src[x+1] = av_clip_uint8(g);
                        src[x+2] = av_clip_uint8(b);
                    break;
                src += s->picture_ptr->linesize[0];
        }else
            avpriv_report_missing_feature(s->avctx, "16bit xfrm");
    if (shift) { /* we need to do point transform or normalize samples */
        int x, w;
        w = s->width * s->nb_components;
        if (s->bits <= 8) {
