static int encode_frame(AVCodecContext* avc_context, uint8_t *outbuf,

                        int buf_size, void *data)

{

    th_ycbcr_buffer t_yuv_buffer;

    TheoraContext *h = avc_context->priv_data;

    AVFrame *frame = data;

    ogg_packet o_packet;

    int result, i;



    // EOS, finish and get 1st pass stats if applicable

    if (!frame) {

        th_encode_packetout(h->t_state, 1, &o_packet);

        if (avc_context->flags & CODEC_FLAG_PASS1)

            if (get_stats(avc_context, 1))

                return -1;

        return 0;

    }



    /* Copy planes to the theora yuv_buffer */

    for (i = 0; i < 3; i++) {

        t_yuv_buffer[i].width  = FFALIGN(avc_context->width,  16) >> (i && h->uv_hshift);

        t_yuv_buffer[i].height = FFALIGN(avc_context->height, 16) >> (i && h->uv_vshift);

        t_yuv_buffer[i].stride = frame->linesize[i];

        t_yuv_buffer[i].data   = frame->data[i];

    }



    if (avc_context->flags & CODEC_FLAG_PASS2)

        if (submit_stats(avc_context))

            return -1;



    /* Now call into theora_encode_YUVin */

    result = th_encode_ycbcr_in(h->t_state, t_yuv_buffer);

    if (result) {

        const char* message;

        switch (result) {

        case -1:

            message = "differing frame sizes";

            break;

        case TH_EINVAL:

            message = "encoder is not ready or is finished";

            break;

        default:

            message = "unknown reason";

            break;

        }

        av_log(avc_context, AV_LOG_ERROR, "theora_encode_YUVin failed (%s) [%d]\n", message, result);

        return -1;

    }



    if (avc_context->flags & CODEC_FLAG_PASS1)

        if (get_stats(avc_context, 0))

            return -1;



    /* Pick up returned ogg_packet */

    result = th_encode_packetout(h->t_state, 0, &o_packet);

    switch (result) {

    case 0:

        /* No packet is ready */

        return 0;

    case 1:

        /* Success, we have a packet */

        break;

    default:

        av_log(avc_context, AV_LOG_ERROR, "theora_encode_packetout failed [%d]\n", result);

        return -1;

    }



    /* Copy ogg_packet content out to buffer */

    if (buf_size < o_packet.bytes) {

        av_log(avc_context, AV_LOG_ERROR, "encoded frame too large\n");

        return -1;

    }

    memcpy(outbuf, o_packet.packet, o_packet.bytes);



    // HACK: does not take codec delay into account (neither does the decoder though)

    avc_context->coded_frame->pts = frame->pts;

    avc_context->coded_frame->key_frame = !(o_packet.granulepos & h->keyframe_mask);



    return o_packet.bytes;

}

static int read_sl_header(PESContext *pes, SLConfigDescr *sl,

                          const uint8_t *buf, int buf_size)

{

    GetBitContext gb;

    int au_start_flag = 0, au_end_flag = 0, ocr_flag = 0, idle_flag = 0;

    int padding_flag = 0, padding_bits = 0, inst_bitrate_flag = 0;

    int dts_flag = -1, cts_flag = -1;

    int64_t dts = AV_NOPTS_VALUE, cts = AV_NOPTS_VALUE;



    init_get_bits(&gb, buf, buf_size * 8);



    if (sl->use_au_start)

        au_start_flag = get_bits1(&gb);

    if (sl->use_au_end)

        au_end_flag = get_bits1(&gb);

    if (!sl->use_au_start && !sl->use_au_end)

        au_start_flag = au_end_flag = 1;

    if (sl->ocr_len > 0)

        ocr_flag = get_bits1(&gb);

    if (sl->use_idle)

        idle_flag = get_bits1(&gb);

    if (sl->use_padding)

        padding_flag = get_bits1(&gb);

    if (padding_flag)

        padding_bits = get_bits(&gb, 3);



    if (!idle_flag && (!padding_flag || padding_bits != 0)) {

        if (sl->packet_seq_num_len)

            skip_bits_long(&gb, sl->packet_seq_num_len);

        if (sl->degr_prior_len)

            if (get_bits1(&gb))

                skip_bits(&gb, sl->degr_prior_len);

        if (ocr_flag)

            skip_bits_long(&gb, sl->ocr_len);

        if (au_start_flag) {

            if (sl->use_rand_acc_pt)

                get_bits1(&gb);

            if (sl->au_seq_num_len > 0)

                skip_bits_long(&gb, sl->au_seq_num_len);

            if (sl->use_timestamps) {

                dts_flag = get_bits1(&gb);

                cts_flag = get_bits1(&gb);

            }

        }

        if (sl->inst_bitrate_len)

            inst_bitrate_flag = get_bits1(&gb);

        if (dts_flag == 1)

            dts = get_ts64(&gb, sl->timestamp_len);

        if (cts_flag == 1)

            cts = get_ts64(&gb, sl->timestamp_len);

        if (sl->au_len > 0)

            skip_bits_long(&gb, sl->au_len);

        if (inst_bitrate_flag)

            skip_bits_long(&gb, sl->inst_bitrate_len);

    }



    if (dts != AV_NOPTS_VALUE)

        pes->dts = dts;

    if (cts != AV_NOPTS_VALUE)

        pes->pts = cts;



    if (sl->timestamp_len && sl->timestamp_res)

        avpriv_set_pts_info(pes->st, sl->timestamp_len, 1, sl->timestamp_res);



    return (get_bits_count(&gb) + 7) >> 3;

}

static int r3d_read_red1(AVFormatContext *s)

{

    AVStream *st = avformat_new_stream(s, NULL);

    char filename[258];

    int tmp;

    int av_unused tmp2;

    AVRational framerate;



    if (!st)

        return AVERROR(ENOMEM);

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_JPEG2000;



    tmp  = avio_r8(s->pb); // major version

    tmp2 = avio_r8(s->pb); // minor version

    av_dlog(s, "version %d.%d\n", tmp, tmp2);



    tmp = avio_rb16(s->pb); // unknown

    av_dlog(s, "unknown1 %d\n", tmp);



    tmp = avio_rb32(s->pb);

    avpriv_set_pts_info(st, 32, 1, tmp);



    tmp = avio_rb32(s->pb); // filenum

    av_dlog(s, "filenum %d\n", tmp);



    avio_skip(s->pb, 32); // unknown



    st->codec->width  = avio_rb32(s->pb);

    st->codec->height = avio_rb32(s->pb);



    tmp = avio_rb16(s->pb); // unknown

    av_dlog(s, "unknown2 %d\n", tmp);



    framerate.num = avio_rb16(s->pb);

    framerate.den = avio_rb16(s->pb);

    if (framerate.num && framerate.den)

        st->r_frame_rate = st->avg_frame_rate = framerate;



    tmp = avio_r8(s->pb); // audio channels

    av_dlog(s, "audio channels %d\n", tmp);

    if (tmp > 0) {

        AVStream *ast = avformat_new_stream(s, NULL);

        if (!ast)

            return AVERROR(ENOMEM);

        ast->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        ast->codec->codec_id = CODEC_ID_PCM_S32BE;

        ast->codec->channels = tmp;

        avpriv_set_pts_info(ast, 32, 1, st->time_base.den);

    }



    avio_read(s->pb, filename, 257);

    filename[sizeof(filename)-1] = 0;

    av_dict_set(&st->metadata, "filename", filename, 0);



    av_dlog(s, "filename %s\n", filename);

    av_dlog(s, "resolution %dx%d\n", st->codec->width, st->codec->height);

    av_dlog(s, "timescale %d\n", st->time_base.den);

    av_dlog(s, "frame rate %d/%d\n",

            framerate.num, framerate.den);



    return 0;

}

static int decode_fctl_chunk(AVFormatContext *s, APNGDemuxContext *ctx, AVPacket *pkt)

{

    uint32_t sequence_number, width, height, x_offset, y_offset;

    uint16_t delay_num, delay_den;

    uint8_t dispose_op, blend_op;



    sequence_number = avio_rb32(s->pb);

    width           = avio_rb32(s->pb);

    height          = avio_rb32(s->pb);

    x_offset        = avio_rb32(s->pb);

    y_offset        = avio_rb32(s->pb);

    delay_num       = avio_rb16(s->pb);

    delay_den       = avio_rb16(s->pb);

    dispose_op      = avio_r8(s->pb);

    blend_op        = avio_r8(s->pb);

    avio_skip(s->pb, 4); /* crc */



    /* default is hundredths of seconds */

    if (!delay_den)

        delay_den = 100;

    if (!delay_num || delay_den / delay_num > ctx->max_fps) {

        delay_num = 1;

        delay_den = ctx->default_fps;

    }

    ctx->pkt_duration = av_rescale_q(delay_num,

                                     (AVRational){ 1, delay_den },

                                     s->streams[0]->time_base);



    av_log(s, AV_LOG_DEBUG, "%s: "

            "sequence_number: %"PRId32", "

            "width: %"PRIu32", "

            "height: %"PRIu32", "

            "x_offset: %"PRIu32", "

            "y_offset: %"PRIu32", "

            "delay_num: %"PRIu16", "

            "delay_den: %"PRIu16", "

            "dispose_op: %d, "

            "blend_op: %d\n",

            __FUNCTION__,

            sequence_number,

            width,

            height,

            x_offset,

            y_offset,

            delay_num,

            delay_den,

            dispose_op,

            blend_op);



    if (width != s->streams[0]->codecpar->width ||

        height != s->streams[0]->codecpar->height ||

        x_offset != 0 ||

        y_offset != 0) {

        if (sequence_number == 0 ||

            x_offset >= s->streams[0]->codecpar->width ||

            width > s->streams[0]->codecpar->width - x_offset ||

            y_offset >= s->streams[0]->codecpar->height ||

            height > s->streams[0]->codecpar->height - y_offset)

            return AVERROR_INVALIDDATA;

        ctx->is_key_frame = 0;

    } else {

        if (sequence_number == 0 && dispose_op == APNG_DISPOSE_OP_PREVIOUS)

            dispose_op = APNG_DISPOSE_OP_BACKGROUND;

        ctx->is_key_frame = dispose_op == APNG_DISPOSE_OP_BACKGROUND ||

                            blend_op   == APNG_BLEND_OP_SOURCE;

    }



    return 0;

}

