            av_log(avctx, AV_LOG_ERROR, "PCM DVD unsupported sample depth\n");

            return AVERROR(EINVAL);

        }

        /* 2 samples are interleaved per block in PCM_DVD */

        samples_per_block = 2;

        sample_size       = avctx->bits_per_coded_sample * 2 / 8;

    } else if (avctx->codec_id == AV_CODEC_ID_PCM_LXF) {

        /* we process 40-bit blocks per channel for LXF */

        samples_per_block = 2;

        sample_size       = 5;

    }



    if (sample_size == 0) {

        av_log(avctx, AV_LOG_ERROR, "Invalid sample_size\n");

        return AVERROR(EINVAL);

    }



    n = avctx->channels * sample_size;



    if (n && buf_size % n) {

        if (buf_size < n) {

            av_log(avctx, AV_LOG_ERROR, "invalid PCM packet\n");

            return -1;

        } else

            buf_size -= buf_size % n;

    }



    n = buf_size / sample_size;



    /* get output buffer */

    s->frame.nb_samples = n * samples_per_block / avctx->channels;

    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = s->frame.data[0];



    switch (avctx->codec->id) {

    case AV_CODEC_ID_PCM_U32LE:

        DECODE(32, le32, src, samples, n, 0, 0x80000000)

        break;

    case AV_CODEC_ID_PCM_U32BE:

        DECODE(32, be32, src, samples, n, 0, 0x80000000)

        break;

    case AV_CODEC_ID_PCM_S24LE:

        DECODE(32, le24, src, samples, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_S24BE:

        DECODE(32, be24, src, samples, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_U24LE:

        DECODE(32, le24, src, samples, n, 8, 0x800000)

        break;

    case AV_CODEC_ID_PCM_U24BE:

        DECODE(32, be24, src, samples, n, 8, 0x800000)

        break;

    case AV_CODEC_ID_PCM_S24DAUD:

        for (; n > 0; n--) {

            uint32_t v = bytestream_get_be24(&src);

            v >>= 4; // sync flags are here

            AV_WN16A(samples, ff_reverse[(v >> 8) & 0xff] +

                             (ff_reverse[v        & 0xff] << 8));

            samples += 2;

        }

        break;

    case AV_CODEC_ID_PCM_S16LE_PLANAR:

    {

        n /= avctx->channels;

        for (c = 0; c < avctx->channels; c++) {

            samples = s->frame.extended_data[c];

#if HAVE_BIGENDIAN

            DECODE(16, le16, src, samples, n, 0, 0)

#else

            memcpy(samples, src, n * 2);

#endif

            src += n * 2;

        }

        break;

    }

    case AV_CODEC_ID_PCM_U16LE:

        DECODE(16, le16, src, samples, n, 0, 0x8000)

        break;

    case AV_CODEC_ID_PCM_U16BE:

        DECODE(16, be16, src, samples, n, 0, 0x8000)

        break;

    case AV_CODEC_ID_PCM_S8:

        for (; n > 0; n--)

            *samples++ = *src++ + 128;

        break;

#if HAVE_BIGENDIAN

    case AV_CODEC_ID_PCM_F64LE:

        DECODE(64, le64, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S32LE:

    case AV_CODEC_ID_PCM_F32LE:

        DECODE(32, le32, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16LE:

        DECODE(16, le16, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F64BE:

    case AV_CODEC_ID_PCM_F32BE:

    case AV_CODEC_ID_PCM_S32BE:

    case AV_CODEC_ID_PCM_S16BE:

#else

    case AV_CODEC_ID_PCM_F64BE:

        DECODE(64, be64, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F32BE:

    case AV_CODEC_ID_PCM_S32BE:

        DECODE(32, be32, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16BE:

        DECODE(16, be16, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F64LE:

    case AV_CODEC_ID_PCM_F32LE:

    case AV_CODEC_ID_PCM_S32LE:

    case AV_CODEC_ID_PCM_S16LE:

#endif /* HAVE_BIGENDIAN */

    case AV_CODEC_ID_PCM_U8:

        memcpy(samples, src, n * sample_size);

        break;

    case AV_CODEC_ID_PCM_ZORK:

        for (; n > 0; n--) {

            int v = *src++;

            if (v < 128)

                v = 128 - v;

            *samples++ = v;

        }

        break;

    case AV_CODEC_ID_PCM_ALAW:

    case AV_CODEC_ID_PCM_MULAW:

        for (; n > 0; n--) {

            AV_WN16A(samples, s->table[*src++]);

            samples += 2;

        }

        break;

    case AV_CODEC_ID_PCM_DVD:

    {

        const uint8_t *src8;

        dst_int32_t = (int32_t *)s->frame.data[0];

        n /= avctx->channels;

        switch (avctx->bits_per_coded_sample) {

        case 20:

            while (n--) {

                c    = avctx->channels;

                src8 = src + 4 * c;

                while (c--) {

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8   & 0xf0) <<  8);

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++ & 0x0f) << 12);

                }

                src = src8;

            }

            break;

        case 24:

            while (n--) {

                c    = avctx->channels;

                src8 = src + 4 * c;

                while (c--) {

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++) << 8);

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++) << 8);

                }

                src = src8;

            }

            break;

        }

        break;

    }

    case AV_CODEC_ID_PCM_LXF:

    {

        int i;

        n /= avctx->channels;

        for (c = 0; c < avctx->channels; c++) {

            dst_int32_t = (int32_t *)s->frame.extended_data[c];

            for (i = 0; i < n; i++) {

                // extract low 20 bits and expand to 32 bits

                *dst_int32_t++ =  (src[2]         << 28) |

                                  (src[1]         << 20) |

                                  (src[0]         << 12) |

                                 ((src[2] & 0x0F) <<  8) |

                                   src[1];

                // extract high 20 bits and expand to 32 bits

                *dst_int32_t++ =  (src[4]         << 24) |

                                  (src[3]         << 16) |

                                 ((src[2] & 0xF0) <<  8) |

                                  (src[4]         <<  4) |

                                  (src[3]         >>  4);

                src += 5;

            }

        }

        break;

    }

    default:

        return -1;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

}

static int parse_presentation_segment(AVCodecContext *avctx,

                                      const uint8_t *buf, int buf_size,

                                      int64_t pts)

{

    PGSSubContext *ctx = avctx->priv_data;

    int i, state, ret;




    // Video descriptor

    int w = bytestream_get_be16(&buf);

    int h = bytestream_get_be16(&buf);



    uint16_t object_index;



    ctx->presentation.pts = pts;



    av_dlog(avctx, "Video Dimensions %dx%d\n",

            w, h);

    ret = ff_set_dimensions(avctx, w, h);

    if (ret < 0)

        return ret;



    /* Skip 1 bytes of unknown, frame rate */

    buf++;



    // Composition descriptor

    ctx->presentation.id_number = bytestream_get_be16(&buf);

    /*

     * state is a 2 bit field that defines pgs epoch boundaries

     * 00 - Normal, previously defined objects and palettes are still valid

     * 01 - Acquisition point, previous objects and palettes can be released

     * 10 - Epoch start, previous objects and palettes can be released

     * 11 - Epoch continue, previous objects and palettes can be released

     *

     * reserved 6 bits discarded

     */

    state = bytestream_get_byte(&buf) >> 6;

    if (state != 0) {

        flush_cache(avctx);

    }



    /*

     * skip palette_update_flag (0x80),

     */

    buf += 1;

    ctx->presentation.palette_id = bytestream_get_byte(&buf);

    ctx->presentation.object_count = bytestream_get_byte(&buf);

    if (ctx->presentation.object_count > MAX_OBJECT_REFS) {

        av_log(avctx, AV_LOG_ERROR,

               "Invalid number of presentation objects %d\n",

               ctx->presentation.object_count);

        ctx->presentation.object_count = 2;

        if (avctx->err_recognition & AV_EF_EXPLODE) {

            return AVERROR_INVALIDDATA;

        }

    }





    for (i = 0; i < ctx->presentation.object_count; i++)

    {



        if (buf_end - buf < 8) {

            av_log(avctx, AV_LOG_ERROR, "Insufficent space for object\n");

            ctx->presentation.object_count = i;

            return AVERROR_INVALIDDATA;

        }



        ctx->presentation.objects[i].id = bytestream_get_be16(&buf);

        ctx->presentation.objects[i].window_id = bytestream_get_byte(&buf);

        ctx->presentation.objects[i].composition_flag = bytestream_get_byte(&buf);



        ctx->presentation.objects[i].x = bytestream_get_be16(&buf);

        ctx->presentation.objects[i].y = bytestream_get_be16(&buf);



        // If cropping

        if (ctx->presentation.objects[i].composition_flag & 0x80) {

            ctx->presentation.objects[i].crop_x = bytestream_get_be16(&buf);

            ctx->presentation.objects[i].crop_y = bytestream_get_be16(&buf);

            ctx->presentation.objects[i].crop_w = bytestream_get_be16(&buf);

            ctx->presentation.objects[i].crop_h = bytestream_get_be16(&buf);

        }



        av_dlog(avctx, "Subtitle Placement x=%d, y=%d\n",

                ctx->presentation.objects[i].x, ctx->presentation.objects[i].y);



        if (ctx->presentation.objects[i].x > avctx->width ||

            ctx->presentation.objects[i].y > avctx->height) {

            av_log(avctx, AV_LOG_ERROR, "Subtitle out of video bounds. x = %d, y = %d, video width = %d, video height = %d.\n",

                   ctx->presentation.objects[i].x,

                   ctx->presentation.objects[i].y,

                    avctx->width, avctx->height);

            ctx->presentation.objects[i].x = 0;

            ctx->presentation.objects[i].y = 0;

            if (avctx->err_recognition & AV_EF_EXPLODE) {

                return AVERROR_INVALIDDATA;

            }

        }

    }



    return 0;

}

static int dxtory_decode_v1_420(AVCodecContext *avctx, AVFrame *pic,

                                const uint8_t *src, int src_size)

{

    int h, w;

    uint8_t *Y1, *Y2, *U, *V;

    int ret;



    if (src_size < avctx->width * avctx->height * 3 / 2) {

        av_log(avctx, AV_LOG_ERROR, "packet too small\n");

        return AVERROR_INVALIDDATA;

    }



    avctx->pix_fmt = AV_PIX_FMT_YUV420P;

    if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)

        return ret;



    Y1 = pic->data[0];

    Y2 = pic->data[0] + pic->linesize[0];

    U  = pic->data[1];

    V  = pic->data[2];

    for (h = 0; h < avctx->height; h += 2) {

        for (w = 0; w < avctx->width; w += 2) {

            AV_COPY16(Y1 + w, src);

            AV_COPY16(Y2 + w, src + 2);

            U[w >> 1] = src[4] + 0x80;

            V[w >> 1] = src[5] + 0x80;

            src += 6;

        }

        Y1 += pic->linesize[0] << 1;

        Y2 += pic->linesize[0] << 1;

        U  += pic->linesize[1];

        V  += pic->linesize[2];

    }



    return 0;

}

static void parse_presentation_segment(AVCodecContext *avctx,

                                       const uint8_t *buf, int buf_size)

{

    PGSSubContext *ctx = avctx->priv_data;



    int x, y;



    int w = bytestream_get_be16(&buf);

    int h = bytestream_get_be16(&buf);



    av_dlog(avctx, "Video Dimensions %dx%d\n",

            w, h);

    if (av_image_check_size(w, h, 0, avctx) >= 0)

        avcodec_set_dimensions(avctx, w, h);



    /* Skip 1 bytes of unknown, frame rate? */

    buf++;



    ctx->presentation.id_number = bytestream_get_be16(&buf);



    /*

     * Skip 3 bytes of unknown:

     *     state

     *     palette_update_flag (0x80),

     *     palette_id_to_use,

     */

    buf += 3;



    ctx->presentation.object_number = bytestream_get_byte(&buf);

    if (!ctx->presentation.object_number)

        return;



    /*

     * Skip 4 bytes of unknown:

     *     object_id_ref (2 bytes),

     *     window_id_ref,

     *     composition_flag (0x80 - object cropped, 0x40 - object forced)

     */

    buf += 4;



    x = bytestream_get_be16(&buf);

    y = bytestream_get_be16(&buf);



    /* TODO If cropping, cropping_x, cropping_y, cropping_width, cropping_height (all 2 bytes).*/



    av_dlog(avctx, "Subtitle Placement x=%d, y=%d\n", x, y);



    if (x > avctx->width || y > avctx->height) {

        av_log(avctx, AV_LOG_ERROR, "Subtitle out of video bounds. x = %d, y = %d, video width = %d, video height = %d.\n",

               x, y, avctx->width, avctx->height);

        x = 0; y = 0;

    }



    /* Fill in dimensions */

    ctx->presentation.x = x;

    ctx->presentation.y = y;

}

