                                          ram_size - initrd_base);



        if (initrd_size < 0) {

            fprintf(stderr, "qemu: could not load initial ram disk '%s'\n",

                    params->initrd_filename);

            exit(1);

        }

    }



    /* If we're loading a kernel directly, we must load the device tree too. */

    if (params->kernel_filename) {

        struct boot_info *boot_info;

        int dt_size;



        dt_base = (loadaddr + kernel_size + DTC_LOAD_PAD) & ~DTC_PAD_MASK;

        dt_size = ppce500_load_device_tree(env, params, dt_base, initrd_base,

                                           initrd_size);

        if (dt_size < 0) {

            fprintf(stderr, "couldn't load device tree\n");

            exit(1);

        }



        boot_info = env->load_info;

        boot_info->entry = entry;

        boot_info->dt_base = dt_base;

        boot_info->dt_size = dt_size;

    }



    if (kvm_enabled()) {

        kvmppc_init();

    }

}

static av_always_inline int mvd_decode(HEVCContext *s)

{

    int ret = 2;

    int k = 1;



    while (k < CABAC_MAX_BIN && get_cabac_bypass(&s->HEVClc->cc)) {

        ret += 1 << k;

        k++;

    }

    if (k == CABAC_MAX_BIN)

        av_log(s->avctx, AV_LOG_ERROR, "CABAC_MAX_BIN : %d\n", k);

    while (k--)

        ret += get_cabac_bypass(&s->HEVClc->cc) << k;

    return get_cabac_bypass_sign(&s->HEVClc->cc, -ret);

}

static inline int read_line(AVFormatContext *s, char *rbuf, const int rbufsize,

                            int *rbuflen)

{

    RTSPState *rt = s->priv_data;

    int idx       = 0;

    int ret       = 0;

    *rbuflen      = 0;



    do {

        ret = ffurl_read_complete(rt->rtsp_hd, rbuf + idx, 1);

        if (ret < 0)

            return ret;

        if (rbuf[idx] == '\r') {

            /* Ignore */

        } else if (rbuf[idx] == '\n') {

            rbuf[idx] = '\0';

            *rbuflen  = idx;

            return 0;

        } else

            idx++;

    } while (idx < rbufsize);

    av_log(s, AV_LOG_ERROR, "Message too long\n");

    return AVERROR(EIO);

}

static av_always_inline int coeff_abs_level_remaining_decode(HEVCContext *s, int rc_rice_param)

{

    int prefix = 0;

    int suffix = 0;

    int last_coeff_abs_level_remaining;

    int i;



    while (prefix < CABAC_MAX_BIN && get_cabac_bypass(&s->HEVClc->cc))

        prefix++;

    if (prefix == CABAC_MAX_BIN) {

        av_log(s->avctx, AV_LOG_ERROR, "CABAC_MAX_BIN : %d\n", prefix);

        return 0;

    }

    if (prefix < 3) {

        for (i = 0; i < rc_rice_param; i++)

            suffix = (suffix << 1) | get_cabac_bypass(&s->HEVClc->cc);

        last_coeff_abs_level_remaining = (prefix << rc_rice_param) + suffix;

    } else {

        int prefix_minus3 = prefix - 3;

        for (i = 0; i < prefix_minus3 + rc_rice_param; i++)

            suffix = (suffix << 1) | get_cabac_bypass(&s->HEVClc->cc);

        last_coeff_abs_level_remaining = (((1 << prefix_minus3) + 3 - 1)

                                              << rc_rice_param) + suffix;

    }

    return last_coeff_abs_level_remaining;

}

static int decode_residuals(FLACContext *s, int channel, int pred_order)

{

    int i, tmp, partition, method_type, rice_order;

    int sample = 0, samples;



    method_type = get_bits(&s->gb, 2);

    if (method_type > 1) {

        av_log(s->avctx, AV_LOG_ERROR, "illegal residual coding method %d\n",

               method_type);

        return -1;

    }



    rice_order = get_bits(&s->gb, 4);



    samples= s->blocksize >> rice_order;

    if (pred_order > samples) {

        av_log(s->avctx, AV_LOG_ERROR, "invalid predictor order: %i > %i\n",

               pred_order, samples);

        return -1;

    }



    sample=

    i= pred_order;

    for (partition = 0; partition < (1 << rice_order); partition++) {

        tmp = get_bits(&s->gb, method_type == 0 ? 4 : 5);

        if (tmp == (method_type == 0 ? 15 : 31)) {

            tmp = get_bits(&s->gb, 5);

            for (; i < samples; i++, sample++)

                s->decoded[channel][sample] = get_sbits_long(&s->gb, tmp);

        } else {

            for (; i < samples; i++, sample++) {

                s->decoded[channel][sample] = get_sr_golomb_flac(&s->gb, tmp, INT_MAX, 0);

            }

        }

        i= 0;

    }



    return 0;

}

static int hls_window(AVFormatContext *s, int last)

{

    HLSContext *hls = s->priv_data;

    ListEntry *en;

    int64_t target_duration = 0;

    int ret = 0;

    AVIOContext *out = NULL;

    char temp_filename[1024];

    int64_t sequence = FFMAX(hls->start_sequence, hls->sequence - hls->size);



    snprintf(temp_filename, sizeof(temp_filename), "%s.tmp", s->filename);

    if ((ret = avio_open2(&out, temp_filename, AVIO_FLAG_WRITE,

                          &s->interrupt_callback, NULL)) < 0)

        goto fail;



    for (en = hls->list; en; en = en->next) {

        if (target_duration < en->duration)

            target_duration = en->duration;

    }



    avio_printf(out, "#EXTM3U\n");

    avio_printf(out, "#EXT-X-VERSION:%d\n", hls->version);

    if (hls->allowcache == 0 || hls->allowcache == 1) {

        avio_printf(out, "#EXT-X-ALLOW-CACHE:%s\n", hls->allowcache == 0 ? "NO" : "YES");

    }

    avio_printf(out, "#EXT-X-TARGETDURATION:%"PRId64"\n",

                av_rescale_rnd(target_duration, 1, AV_TIME_BASE,

                               AV_ROUND_UP));

    avio_printf(out, "#EXT-X-MEDIA-SEQUENCE:%"PRId64"\n", sequence);



    av_log(s, AV_LOG_VERBOSE, "EXT-X-MEDIA-SEQUENCE:%"PRId64"\n",

           sequence);



    for (en = hls->list; en; en = en->next) {

        if (hls->version > 2)

            avio_printf(out, "#EXTINF:%f\n",

                        (double)en->duration / AV_TIME_BASE);

        else

            avio_printf(out, "#EXTINF:%"PRId64",\n",

                        av_rescale(en->duration, 1, AV_TIME_BASE));

        if (hls->baseurl)

            avio_printf(out, "%s", hls->baseurl);

        avio_printf(out, "%s\n", en->name);

    }



    if (last)

        avio_printf(out, "#EXT-X-ENDLIST\n");



fail:

    avio_closep(&out);

    if (ret >= 0)

        ff_rename(temp_filename, s->filename);

    return ret;

}

static int seg_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    AVStream *st = s->streams[pkt->stream_index];

    int64_t end_pts = seg->recording_time * seg->number;

    int ret, can_split = 1;



    if (!oc)

        return AVERROR(EINVAL);



    if (seg->has_video) {

        can_split = st->codec->codec_type == AVMEDIA_TYPE_VIDEO &&

                    pkt->flags & AV_PKT_FLAG_KEY;

    }



    if (can_split && av_compare_ts(pkt->pts, st->time_base, end_pts,

                                   AV_TIME_BASE_Q) >= 0) {

        av_log(s, AV_LOG_DEBUG, "Next segment starts at %d %"PRId64"\n",

               pkt->stream_index, pkt->pts);



        ret = segment_end(oc, seg->individual_header_trailer);



        if (!ret)

            ret = segment_start(s, seg->individual_header_trailer);



        if (ret)

            goto fail;



        oc = seg->avf;



        if (seg->list) {

            if (seg->list_type == LIST_HLS) {

                if ((ret = segment_hls_window(s, 0)) < 0)

                    goto fail;

            } else {

                avio_printf(seg->pb, "%s\n", oc->filename);

                avio_flush(seg->pb);

                if (seg->size && !(seg->number % seg->size)) {

                    avio_closep(&seg->pb);

                    if ((ret = avio_open2(&seg->pb, seg->list, AVIO_FLAG_WRITE,

                                          &s->interrupt_callback, NULL)) < 0)

                        goto fail;

                }

            }

        }

    }



    ret = ff_write_chained(oc, pkt->stream_index, pkt, s);



fail:

    if (ret < 0)

        seg_free_context(seg);



    return ret;

}

static int hls_start(AVFormatContext *s)

{

    HLSContext *c = s->priv_data;

    AVFormatContext *oc = c->avf;

    int err = 0;



    if (c->wrap)

        c->number %= c->wrap;



    if (av_get_frame_filename(oc->filename, sizeof(oc->filename),

                              c->basename, c->number++) < 0)

        return AVERROR(EINVAL);



    if ((err = avio_open2(&oc->pb, oc->filename, AVIO_FLAG_WRITE,

                          &s->interrupt_callback, NULL)) < 0)

        return err;



    if (oc->oformat->priv_class && oc->priv_data)

        av_opt_set(oc->priv_data, "mpegts_flags", "resend_headers", 0);



    return 0;

}

static int segment_end(AVFormatContext *s, int write_trailer, int is_last)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    int ret = 0;



    av_write_frame(oc, NULL); /* Flush any buffered data (fragmented mp4) */

    if (write_trailer)

        ret = av_write_trailer(oc);



    if (ret < 0)

        av_log(s, AV_LOG_ERROR, "Failure occurred when ending segment '%s'\n",

               oc->filename);



    if (seg->list) {

        if (seg->list_size || seg->list_type == LIST_TYPE_M3U8) {

            SegmentListEntry *entry = av_mallocz(sizeof(*entry));

            if (!entry) {

                ret = AVERROR(ENOMEM);

                goto end;

            }



            /* append new element */

            memcpy(entry, &seg->cur_entry, sizeof(*entry));

            if (!seg->segment_list_entries)

                seg->segment_list_entries = seg->segment_list_entries_end = entry;

            else

                seg->segment_list_entries_end->next = entry;

            seg->segment_list_entries_end = entry;



            /* drop first item */

            if (seg->list_size && seg->segment_count > seg->list_size) {

                entry = seg->segment_list_entries;

                seg->segment_list_entries = seg->segment_list_entries->next;

                av_free(entry->filename);

                av_freep(&entry);

            }



            avio_close(seg->list_pb);

            if ((ret = segment_list_open(s)) < 0)

                goto end;

            for (entry = seg->segment_list_entries; entry; entry = entry->next)

                segment_list_print_entry(seg->list_pb, seg->list_type, entry, s);

            if (seg->list_type == LIST_TYPE_M3U8 && is_last)

                avio_printf(seg->list_pb, "#EXT-X-ENDLIST\n");

        } else {

            segment_list_print_entry(seg->list_pb, seg->list_type, &seg->cur_entry, s);

        }

        avio_flush(seg->list_pb);

    }



    av_log(s, AV_LOG_VERBOSE, "segment:'%s' count:%d ended\n",

           seg->avf->filename, seg->segment_count);

    seg->segment_count++;



end:

    avio_close(oc->pb);



    return ret;

}

static inline int cris_addc(int a, const int b)

{

