static int dfa_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    DfaContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    const uint8_t *buf_end = avpkt->data + avpkt->size;

    const uint8_t *tmp_buf;

    uint32_t chunk_type, chunk_size;

    uint8_t *dst;

    int ret;

    int i, pal_elems;



    if (s->pic.data[0])

        avctx->release_buffer(avctx, &s->pic);



    if ((ret = avctx->get_buffer(avctx, &s->pic))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    while (buf < buf_end) {

        chunk_size = AV_RL32(buf + 4);

        chunk_type = AV_RL32(buf + 8);

        buf += 12;

        if (buf_end - buf < chunk_size) {

            av_log(avctx, AV_LOG_ERROR, "Chunk size is too big (%d bytes)\n", chunk_size);

            return -1;

        }

        if (!chunk_type)

            break;

        if (chunk_type == 1) {

            pal_elems = FFMIN(chunk_size / 3, 256);

            tmp_buf = buf;

            for (i = 0; i < pal_elems; i++) {

                s->pal[i] = bytestream_get_be24(&tmp_buf) << 2;

                s->pal[i] |= (s->pal[i] >> 6) & 0x333;

            }

            s->pic.palette_has_changed = 1;

        } else if (chunk_type <= 9) {

            if (decoder[chunk_type - 2](s->frame_buf, avctx->width, avctx->height,

                                        buf, buf + chunk_size)) {

                av_log(avctx, AV_LOG_ERROR, "Error decoding %s chunk\n",

                       chunk_name[chunk_type - 2]);

                return -1;

            }

        } else {

            av_log(avctx, AV_LOG_WARNING, "Ignoring unknown chunk type %d\n",

                   chunk_type);

        }

        buf += chunk_size;

    }



    buf = s->frame_buf;

    dst = s->pic.data[0];

    for (i = 0; i < avctx->height; i++) {

        memcpy(dst, buf, avctx->width);

        dst += s->pic.linesize[0];

        buf += avctx->width;

    }

    memcpy(s->pic.data[1], s->pal, sizeof(s->pal));



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->pic;



    return avpkt->size;

}

static int bfi_decode_frame(AVCodecContext * avctx, void *data,

                            int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    BFIContext *bfi = avctx->priv_data;

    uint8_t *dst = bfi->dst;

    uint8_t *src, *dst_offset, colour1, colour2;

    uint8_t *frame_end = bfi->dst + avctx->width * avctx->height;

    uint32_t *pal;

    int i, j, height = avctx->height;



    if (bfi->frame.data[0])

        avctx->release_buffer(avctx, &bfi->frame);



    bfi->frame.reference = 1;



    if (avctx->get_buffer(avctx, &bfi->frame) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    /* Set frame parameters and palette, if necessary */

    if (!avctx->frame_number) {

        bfi->frame.pict_type = FF_I_TYPE;

        bfi->frame.key_frame = 1;

        /* Setting the palette */

        if(avctx->extradata_size>768) {

            av_log(NULL, AV_LOG_ERROR, "Palette is too large.\n");

            return -1;

        }

        pal = (uint32_t *) bfi->frame.data[1];

        for (i = 0; i < avctx->extradata_size / 3; i++) {

            int shift = 16;

            *pal = 0;

            for (j = 0; j < 3; j++, shift -= 8)

                *pal +=

                    ((avctx->extradata[i * 3 + j] << 2) |

                    (avctx->extradata[i * 3 + j] >> 4)) << shift;

            pal++;

        }

        bfi->frame.palette_has_changed = 1;

    } else {

        bfi->frame.pict_type = FF_P_TYPE;

        bfi->frame.key_frame = 0;

    }



    buf += 4; //Unpacked size, not required.



    while (dst != frame_end) {

        static const uint8_t lentab[4]={0,2,0,1};

        unsigned int byte = *buf++, av_uninit(offset);

        unsigned int code = byte >> 6;

        unsigned int length = byte & ~0xC0;



        /* Get length and offset(if required) */

        if (length == 0) {

            if (code == 1) {

                length = bytestream_get_byte(&buf);

                offset = bytestream_get_le16(&buf);

            } else {

                length = bytestream_get_le16(&buf);

                if (code == 2 && length == 0)

                    break;

            }

        } else {

            if (code == 1)

                offset = bytestream_get_byte(&buf);

        }



        /* Do boundary check */

        if (dst + (length<<lentab[code]) > frame_end)

            break;



        switch (code) {



        case 0:                //Normal Chain

            bytestream_get_buffer(&buf, dst, length);

            dst += length;

            break;



        case 1:                //Back Chain

            dst_offset = dst - offset;

            length *= 4;        //Convert dwords to bytes.

            if (dst_offset < bfi->dst)

                break;

            while (length--)

                *dst++ = *dst_offset++;

            break;



        case 2:                //Skip Chain

            dst += length;

            break;



        case 3:                //Fill Chain

            colour1 = bytestream_get_byte(&buf);

            colour2 = bytestream_get_byte(&buf);

            while (length--) {

                *dst++ = colour1;

                *dst++ = colour2;

            }

            break;



        }

    }



    src = bfi->dst;

    dst = bfi->frame.data[0];

    while (height--) {

        memcpy(dst, src, avctx->width);

        src += avctx->width;

        dst += bfi->frame.linesize[0];

    }

    *data_size = sizeof(AVFrame);

    *(AVFrame *) data = bfi->frame;

    return buf_size;

}

static int decode_frame_byterun1(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    IffContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    unsigned buf_size = avpkt->size;

    const uint8_t *buf_end = buf+buf_size;

    unsigned y, plane, x;



    if (avctx->reget_buffer(avctx, &s->frame) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    for(y = 0; y < avctx->height ; y++ ) {

        uint8_t *row = &s->frame.data[0][ y*s->frame.linesize[0] ];

        if (avctx->codec_tag == MKTAG('I','L','B','M')) { //interleaved

            memset(row, 0, avctx->pix_fmt == PIX_FMT_PAL8 ? avctx->width : (avctx->width * 4));

            for (plane = 0; plane < avctx->bits_per_coded_sample; plane++) {

                for(x = 0; x < s->planesize && buf < buf_end; ) {

                    int8_t value = *buf++;

                    unsigned length;

                    if (value >= 0) {

                        length = value + 1;

                        memcpy(s->planebuf + x, buf, FFMIN3(length, s->planesize - x, buf_end - buf));

                        buf += length;

                    } else if (value > -128) {

                        length = -value + 1;

                        memset(s->planebuf + x, *buf++, FFMIN(length, s->planesize - x));

                    } else { //noop

                        continue;

                    }

                    x += length;

                }

                if (avctx->pix_fmt == PIX_FMT_PAL8) {

                    decodeplane8(row, s->planebuf, s->planesize, avctx->bits_per_coded_sample, plane);

                } else { //PIX_FMT_BGR32

                    decodeplane32((uint32_t *) row, s->planebuf, s->planesize, avctx->bits_per_coded_sample, plane);

                }

            }

        } else {

            for(x = 0; x < avctx->width && buf < buf_end; ) {

                int8_t value = *buf++;

                unsigned length;

                if (value >= 0) {

                    length = value + 1;

                    memcpy(row + x, buf, FFMIN3(length, buf_end - buf, avctx->width - x));

                    buf += length;

                } else if (value > -128) {

                    length = -value + 1;

                    memset(row + x, *buf++, FFMIN(length, avctx->width - x));

                } else { //noop

                    continue;

                }

                x += length;

            }

        }

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->frame;

    return buf_size;

}

static int raw_decode(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    int linesize_align = 4;

    RawVideoContext *context = avctx->priv_data;



    AVFrame   *frame   = data;

    AVPicture *picture = data;



    frame->pict_type        = avctx->coded_frame->pict_type;

    frame->interlaced_frame = avctx->coded_frame->interlaced_frame;

    frame->top_field_first = avctx->coded_frame->top_field_first;

    frame->reordered_opaque = avctx->reordered_opaque;

    frame->pkt_pts          = avctx->pkt->pts;

    frame->pkt_pos          = avctx->pkt->pos;



    if(context->tff>=0){

        frame->interlaced_frame = 1;

        frame->top_field_first  = context->tff;

    }



    if(buf_size < context->length - (avctx->pix_fmt==PIX_FMT_PAL8 ? 256*4 : 0))

        return -1;



    if (avctx->width <= 0 || avctx->height <= 0) {

        av_log(avctx, AV_LOG_ERROR, "w/h is invalid\n");

        return AVERROR(EINVAL);

    }



    //2bpp and 4bpp raw in avi and mov (yes this is ugly ...)

    if (context->buffer) {

        int i;

        uint8_t *dst = context->buffer;

        buf_size = context->length - 256*4;

        if (avctx->bits_per_coded_sample == 4){

            for(i=0; 2*i+1 < buf_size && i<avpkt->size; i++){

                dst[2*i+0]= buf[i]>>4;

                dst[2*i+1]= buf[i]&15;

            }

            linesize_align = 8;

        } else {

            for(i=0; 4*i+3 < buf_size && i<avpkt->size; i++){

                dst[4*i+0]= buf[i]>>6;

                dst[4*i+1]= buf[i]>>4&3;

                dst[4*i+2]= buf[i]>>2&3;

                dst[4*i+3]= buf[i]   &3;

            }

            linesize_align = 16;

        }

        buf= dst;

    }



    if(avctx->codec_tag == MKTAG('A', 'V', '1', 'x') ||

       avctx->codec_tag == MKTAG('A', 'V', 'u', 'p'))

        buf += buf_size - context->length;



    avpicture_fill(picture, buf, avctx->pix_fmt, avctx->width, avctx->height);

    if((avctx->pix_fmt==PIX_FMT_PAL8 && buf_size < context->length) ||

       (av_pix_fmt_descriptors[avctx->pix_fmt].flags & PIX_FMT_PSEUDOPAL)) {

        frame->data[1]= context->palette;

    }

    if (avctx->pix_fmt == PIX_FMT_PAL8) {

        const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



        if (pal) {

            memcpy(frame->data[1], pal, AVPALETTE_SIZE);

            frame->palette_has_changed = 1;

        }

    }

    if((avctx->pix_fmt==PIX_FMT_BGR24    ||

        avctx->pix_fmt==PIX_FMT_GRAY8    ||

        avctx->pix_fmt==PIX_FMT_RGB555LE ||

        avctx->pix_fmt==PIX_FMT_RGB555BE ||

        avctx->pix_fmt==PIX_FMT_RGB565LE ||

        avctx->pix_fmt==PIX_FMT_MONOWHITE ||

        avctx->pix_fmt==PIX_FMT_PAL8) &&

        FFALIGN(frame->linesize[0], linesize_align)*avctx->height <= buf_size)

        frame->linesize[0] = FFALIGN(frame->linesize[0], linesize_align);



    if(context->flip)

        flip(avctx, picture);



    if (   avctx->codec_tag == MKTAG('Y', 'V', '1', '2')

        || avctx->codec_tag == MKTAG('Y', 'V', '1', '6')

        || avctx->codec_tag == MKTAG('Y', 'V', '2', '4')

        || avctx->codec_tag == MKTAG('Y', 'V', 'U', '9'))

        FFSWAP(uint8_t *, picture->data[1], picture->data[2]);



    if(avctx->codec_tag == AV_RL32("yuv2") &&

       avctx->pix_fmt   == PIX_FMT_YUYV422) {

        int x, y;

        uint8_t *line = picture->data[0];

        for(y = 0; y < avctx->height; y++) {

            for(x = 0; x < avctx->width; x++)

                line[2*x + 1] ^= 0x80;

            line += picture->linesize[0];

        }

    }



    *data_size = sizeof(AVPicture);

    return buf_size;

}

int ff_alloc_picture(MpegEncContext *s, Picture *pic, int shared){

    const int big_mb_num= s->mb_stride*(s->mb_height+1) + 1; //the +1 is needed so memset(,,stride*height) does not sig11

    const int mb_array_size= s->mb_stride*s->mb_height;

    const int b8_array_size= s->b8_stride*s->mb_height*2;

    const int b4_array_size= s->b4_stride*s->mb_height*4;

    int i;

    int r= -1;



    if(shared){

        assert(pic->data[0]);

        assert(pic->type == 0 || pic->type == FF_BUFFER_TYPE_SHARED);

        pic->type= FF_BUFFER_TYPE_SHARED;

    }else{

        assert(!pic->data[0]);



        if (alloc_frame_buffer(s, pic) < 0)

            return -1;



        s->linesize  = pic->linesize[0];

        s->uvlinesize= pic->linesize[1];

    }



    if(pic->qscale_table==NULL){

        if (s->encoding) {

            FF_ALLOCZ_OR_GOTO(s->avctx, pic->mb_var   , mb_array_size * sizeof(int16_t)  , fail)

            FF_ALLOCZ_OR_GOTO(s->avctx, pic->mc_mb_var, mb_array_size * sizeof(int16_t)  , fail)

            FF_ALLOCZ_OR_GOTO(s->avctx, pic->mb_mean  , mb_array_size * sizeof(int8_t )  , fail)

        }



        FF_ALLOCZ_OR_GOTO(s->avctx, pic->mbskip_table , mb_array_size * sizeof(uint8_t)+2, fail) //the +2 is for the slice end check

        FF_ALLOCZ_OR_GOTO(s->avctx, pic->qscale_table , mb_array_size * sizeof(uint8_t)  , fail)

        FF_ALLOCZ_OR_GOTO(s->avctx, pic->mb_type_base , (big_mb_num + s->mb_stride) * sizeof(uint32_t), fail)

        pic->mb_type= pic->mb_type_base + 2*s->mb_stride+1;

        if(s->out_format == FMT_H264){

            for(i=0; i<2; i++){

                FF_ALLOCZ_OR_GOTO(s->avctx, pic->motion_val_base[i], 2 * (b4_array_size+4)  * sizeof(int16_t), fail)

                pic->motion_val[i]= pic->motion_val_base[i]+4;

                FF_ALLOCZ_OR_GOTO(s->avctx, pic->ref_index[i], 4*mb_array_size * sizeof(uint8_t), fail)

            }

            pic->motion_subsample_log2= 2;

        }else if(s->out_format == FMT_H263 || s->encoding || (s->avctx->debug&FF_DEBUG_MV) || (s->avctx->debug_mv)){

            for(i=0; i<2; i++){

                FF_ALLOCZ_OR_GOTO(s->avctx, pic->motion_val_base[i], 2 * (b8_array_size+4) * sizeof(int16_t), fail)

                pic->motion_val[i]= pic->motion_val_base[i]+4;

                FF_ALLOCZ_OR_GOTO(s->avctx, pic->ref_index[i], 4*mb_array_size * sizeof(uint8_t), fail)

            }

            pic->motion_subsample_log2= 3;

        }

        if(s->avctx->debug&FF_DEBUG_DCT_COEFF) {

            FF_ALLOCZ_OR_GOTO(s->avctx, pic->dct_coeff, 64 * mb_array_size * sizeof(DCTELEM)*6, fail)

        }

        pic->qstride= s->mb_stride;

        FF_ALLOCZ_OR_GOTO(s->avctx, pic->pan_scan , 1 * sizeof(AVPanScan), fail)

    }



    /* It might be nicer if the application would keep track of these

     * but it would require an API change. */

    memmove(s->prev_pict_types+1, s->prev_pict_types, PREV_PICT_TYPES_BUFFER_SIZE-1);

    s->prev_pict_types[0]= s->dropable ? AV_PICTURE_TYPE_B : s->pict_type;

    if(pic->age < PREV_PICT_TYPES_BUFFER_SIZE && s->prev_pict_types[pic->age] == AV_PICTURE_TYPE_B)

        pic->age= INT_MAX; // Skipped MBs in B-frames are quite rare in MPEG-1/2 and it is a bit tricky to skip them anyway.

    pic->owner2 = NULL;



    return 0;

fail: //for the FF_ALLOCZ_OR_GOTO macro

    if(r>=0)

        free_frame_buffer(s, pic);

    return -1;

}

static int alloc_frame_buffer(MpegEncContext *s, Picture *pic)

{

    int r;



    if (s->avctx->hwaccel) {

        assert(!pic->f.hwaccel_picture_private);

        if (s->avctx->hwaccel->priv_data_size) {

            pic->f.hwaccel_picture_private = av_mallocz(s->avctx->hwaccel->priv_data_size);

            if (!pic->f.hwaccel_picture_private) {

                av_log(s->avctx, AV_LOG_ERROR, "alloc_frame_buffer() failed (hwaccel private data allocation)\n");

                return -1;

            }

        }

    }



    if (s->codec_id != AV_CODEC_ID_WMV3IMAGE &&

        s->codec_id != AV_CODEC_ID_VC1IMAGE  &&

        s->codec_id != AV_CODEC_ID_MSS2)

        r = ff_thread_get_buffer(s->avctx, &pic->f);

    else

        r = avcodec_default_get_buffer(s->avctx, &pic->f);



    if (r < 0 || !pic->f.type || !pic->f.data[0]) {

        av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed (%d %d %p)\n",

               r, pic->f.type, pic->f.data[0]);

        av_freep(&pic->f.hwaccel_picture_private);

        return -1;

    }



    if (s->linesize && (s->linesize   != pic->f.linesize[0] ||

                        s->uvlinesize != pic->f.linesize[1])) {

        av_log(s->avctx, AV_LOG_ERROR,

               "get_buffer() failed (stride changed)\n");

        free_frame_buffer(s, pic);

        return -1;

    }



    if (pic->f.linesize[1] != pic->f.linesize[2]) {

        av_log(s->avctx, AV_LOG_ERROR,

               "get_buffer() failed (uv stride mismatch)\n");

        free_frame_buffer(s, pic);

        return -1;

    }



    return 0;

}

int ff_alloc_picture(MpegEncContext *s, Picture *pic, int shared)

{

    int i, ret;



    if (shared) {

        assert(pic->f.data[0]);

        pic->shared = 1;

    } else {

        assert(!pic->f.data[0]);



        if (alloc_frame_buffer(s, pic) < 0)

            return -1;



        s->linesize   = pic->f.linesize[0];

        s->uvlinesize = pic->f.linesize[1];

    }



    if (!pic->qscale_table_buf)

        ret = alloc_picture_tables(s, pic);

    else

        ret = make_tables_writable(pic);

    if (ret < 0)

        goto fail;



    if (s->encoding) {

        pic->mb_var    = (uint16_t*)pic->mb_var_buf->data;

        pic->mc_mb_var = (uint16_t*)pic->mc_mb_var_buf->data;

        pic->mb_mean   = pic->mb_mean_buf->data;

    }



    pic->mbskip_table = pic->mbskip_table_buf->data;

    pic->qscale_table = pic->qscale_table_buf->data + 2 * s->mb_stride + 1;

    pic->mb_type      = (uint32_t*)pic->mb_type_buf->data + 2 * s->mb_stride + 1;



    if (pic->motion_val_buf[0]) {

        for (i = 0; i < 2; i++) {

            pic->motion_val[i] = (int16_t (*)[2])pic->motion_val_buf[i]->data + 4;

            pic->ref_index[i]  = pic->ref_index_buf[i]->data;

        }

    }



    return 0;

fail:

    av_log(s->avctx, AV_LOG_ERROR, "Error allocating a picture.\n");

    ff_mpeg_unref_picture(s, pic);

    free_picture_tables(pic);

    return AVERROR(ENOMEM);

}

int MPV_common_init(MpegEncContext *s)

{

    int y_size, c_size, yc_size, i, mb_array_size, mv_table_size, x, y, threads;



    s->mb_height = (s->height + 15) / 16;



    if(s->avctx->thread_count > MAX_THREADS || (s->avctx->thread_count > s->mb_height && s->mb_height)){

        av_log(s->avctx, AV_LOG_ERROR, "too many threads\n");

        return -1;

    }



    if((s->width || s->height) && avcodec_check_dimensions(s->avctx, s->width, s->height))

        return -1;



    dsputil_init(&s->dsp, s->avctx);

    ff_dct_common_init(s);



    s->flags= s->avctx->flags;

    s->flags2= s->avctx->flags2;



    s->mb_width  = (s->width  + 15) / 16;

    s->mb_stride = s->mb_width + 1;

    s->b8_stride = s->mb_width*2 + 1;

    s->b4_stride = s->mb_width*4 + 1;

    mb_array_size= s->mb_height * s->mb_stride;

    mv_table_size= (s->mb_height+2) * s->mb_stride + 1;



    /* set chroma shifts */

    avcodec_get_chroma_sub_sample(s->avctx->pix_fmt,&(s->chroma_x_shift),

                                                    &(s->chroma_y_shift) );



    /* set default edge pos, will be overriden in decode_header if needed */

    s->h_edge_pos= s->mb_width*16;

    s->v_edge_pos= s->mb_height*16;



    s->mb_num = s->mb_width * s->mb_height;



    s->block_wrap[0]=

    s->block_wrap[1]=

    s->block_wrap[2]=

    s->block_wrap[3]= s->b8_stride;

    s->block_wrap[4]=

    s->block_wrap[5]= s->mb_stride;



    y_size = s->b8_stride * (2 * s->mb_height + 1);

    c_size = s->mb_stride * (s->mb_height + 1);

    yc_size = y_size + 2 * c_size;



    /* convert fourcc to upper case */

    s->codec_tag=          toupper( s->avctx->codec_tag     &0xFF)

                        + (toupper((s->avctx->codec_tag>>8 )&0xFF)<<8 )

                        + (toupper((s->avctx->codec_tag>>16)&0xFF)<<16)

                        + (toupper((s->avctx->codec_tag>>24)&0xFF)<<24);



    s->stream_codec_tag=          toupper( s->avctx->stream_codec_tag     &0xFF)

                               + (toupper((s->avctx->stream_codec_tag>>8 )&0xFF)<<8 )

                               + (toupper((s->avctx->stream_codec_tag>>16)&0xFF)<<16)

                               + (toupper((s->avctx->stream_codec_tag>>24)&0xFF)<<24);



    s->avctx->coded_frame= (AVFrame*)&s->current_picture;



    CHECKED_ALLOCZ(s->mb_index2xy, (s->mb_num+1)*sizeof(int)) //error ressilience code looks cleaner with this

    for(y=0; y<s->mb_height; y++){

        for(x=0; x<s->mb_width; x++){

            s->mb_index2xy[ x + y*s->mb_width ] = x + y*s->mb_stride;

        }

    }

    s->mb_index2xy[ s->mb_height*s->mb_width ] = (s->mb_height-1)*s->mb_stride + s->mb_width; //FIXME really needed?



    if (s->encoding) {

        /* Allocate MV tables */

        CHECKED_ALLOCZ(s->p_mv_table_base            , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_forw_mv_table_base       , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_back_mv_table_base       , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_bidir_forw_mv_table_base , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_bidir_back_mv_table_base , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_direct_mv_table_base     , mv_table_size * 2 * sizeof(int16_t))

        s->p_mv_table           = s->p_mv_table_base            + s->mb_stride + 1;

        s->b_forw_mv_table      = s->b_forw_mv_table_base       + s->mb_stride + 1;

        s->b_back_mv_table      = s->b_back_mv_table_base       + s->mb_stride + 1;

        s->b_bidir_forw_mv_table= s->b_bidir_forw_mv_table_base + s->mb_stride + 1;

        s->b_bidir_back_mv_table= s->b_bidir_back_mv_table_base + s->mb_stride + 1;

        s->b_direct_mv_table    = s->b_direct_mv_table_base     + s->mb_stride + 1;



        if(s->msmpeg4_version){

            CHECKED_ALLOCZ(s->ac_stats, 2*2*(MAX_LEVEL+1)*(MAX_RUN+1)*2*sizeof(int));

        }

        CHECKED_ALLOCZ(s->avctx->stats_out, 256);



        /* Allocate MB type table */

        CHECKED_ALLOCZ(s->mb_type  , mb_array_size * sizeof(uint16_t)) //needed for encoding



        CHECKED_ALLOCZ(s->lambda_table, mb_array_size * sizeof(int))



        CHECKED_ALLOCZ(s->q_intra_matrix, 64*32 * sizeof(int))

        CHECKED_ALLOCZ(s->q_inter_matrix, 64*32 * sizeof(int))

        CHECKED_ALLOCZ(s->q_intra_matrix16, 64*32*2 * sizeof(uint16_t))

        CHECKED_ALLOCZ(s->q_inter_matrix16, 64*32*2 * sizeof(uint16_t))

        CHECKED_ALLOCZ(s->input_picture, MAX_PICTURE_COUNT * sizeof(Picture*))

        CHECKED_ALLOCZ(s->reordered_input_picture, MAX_PICTURE_COUNT * sizeof(Picture*))



        if(s->avctx->noise_reduction){

            CHECKED_ALLOCZ(s->dct_offset, 2 * 64 * sizeof(uint16_t))

        }

    }

    CHECKED_ALLOCZ(s->picture, MAX_PICTURE_COUNT * sizeof(Picture))



    CHECKED_ALLOCZ(s->error_status_table, mb_array_size*sizeof(uint8_t))



    if(s->codec_id==CODEC_ID_MPEG4 || (s->flags & CODEC_FLAG_INTERLACED_ME)){

        /* interlaced direct mode decoding tables */

            for(i=0; i<2; i++){

                int j, k;

                for(j=0; j<2; j++){

                    for(k=0; k<2; k++){

                        CHECKED_ALLOCZ(s->b_field_mv_table_base[i][j][k]     , mv_table_size * 2 * sizeof(int16_t))

                        s->b_field_mv_table[i][j][k]    = s->b_field_mv_table_base[i][j][k]     + s->mb_stride + 1;

                    }

                    CHECKED_ALLOCZ(s->b_field_select_table[i][j]     , mb_array_size * 2 * sizeof(uint8_t))

                    CHECKED_ALLOCZ(s->p_field_mv_table_base[i][j]     , mv_table_size * 2 * sizeof(int16_t))

                    s->p_field_mv_table[i][j]    = s->p_field_mv_table_base[i][j]     + s->mb_stride + 1;

                }

                CHECKED_ALLOCZ(s->p_field_select_table[i]      , mb_array_size * 2 * sizeof(uint8_t))

            }

    }

    if (s->out_format == FMT_H263) {

        /* ac values */

        CHECKED_ALLOCZ(s->ac_val_base, yc_size * sizeof(int16_t) * 16);

        s->ac_val[0] = s->ac_val_base + s->b8_stride + 1;

        s->ac_val[1] = s->ac_val_base + y_size + s->mb_stride + 1;

        s->ac_val[2] = s->ac_val[1] + c_size;



        /* cbp values */

        CHECKED_ALLOCZ(s->coded_block_base, y_size);

        s->coded_block= s->coded_block_base + s->b8_stride + 1;



        /* cbp, ac_pred, pred_dir */

        CHECKED_ALLOCZ(s->cbp_table  , mb_array_size * sizeof(uint8_t))

        CHECKED_ALLOCZ(s->pred_dir_table, mb_array_size * sizeof(uint8_t))

    }



    if (s->h263_pred || s->h263_plus || !s->encoding) {

        /* dc values */

        //MN: we need these for error resilience of intra-frames

        CHECKED_ALLOCZ(s->dc_val_base, yc_size * sizeof(int16_t));

        s->dc_val[0] = s->dc_val_base + s->b8_stride + 1;

        s->dc_val[1] = s->dc_val_base + y_size + s->mb_stride + 1;

        s->dc_val[2] = s->dc_val[1] + c_size;

        for(i=0;i<yc_size;i++)

            s->dc_val_base[i] = 1024;

    }



    /* which mb is a intra block */

    CHECKED_ALLOCZ(s->mbintra_table, mb_array_size);

    memset(s->mbintra_table, 1, mb_array_size);



    /* init macroblock skip table */

    CHECKED_ALLOCZ(s->mbskip_table, mb_array_size+2);

    //Note the +1 is for a quicker mpeg4 slice_end detection

    CHECKED_ALLOCZ(s->prev_pict_types, PREV_PICT_TYPES_BUFFER_SIZE);



    s->parse_context.state= -1;

    if((s->avctx->debug&(FF_DEBUG_VIS_QP|FF_DEBUG_VIS_MB_TYPE)) || (s->avctx->debug_mv)){

       s->visualization_buffer[0] = av_malloc((s->mb_width*16 + 2*EDGE_WIDTH) * s->mb_height*16 + 2*EDGE_WIDTH);

       s->visualization_buffer[1] = av_malloc((s->mb_width*8 + EDGE_WIDTH) * s->mb_height*8 + EDGE_WIDTH);

       s->visualization_buffer[2] = av_malloc((s->mb_width*8 + EDGE_WIDTH) * s->mb_height*8 + EDGE_WIDTH);

    }



    s->context_initialized = 1;



    s->thread_context[0]= s;

    /* h264 does thread context setup itself, but it needs context[0]

     * to be fully initialized for the error resilience code */

    threads = s->codec_id == CODEC_ID_H264 ? 1 : s->avctx->thread_count;



    for(i=1; i<threads; i++){

        s->thread_context[i]= av_malloc(sizeof(MpegEncContext));

        memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

    }



    for(i=0; i<threads; i++){

        if(init_duplicate_context(s->thread_context[i], s) < 0)

           goto fail;

        s->thread_context[i]->start_mb_y= (s->mb_height*(i  ) + s->avctx->thread_count/2) / s->avctx->thread_count;

        s->thread_context[i]->end_mb_y  = (s->mb_height*(i+1) + s->avctx->thread_count/2) / s->avctx->thread_count;

    }



    return 0;

 fail:

    MPV_common_end(s);

    return -1;

}

static int decode_band_hdr(IVI4DecContext *ctx, IVIBandDesc *band,

                           AVCodecContext *avctx)

{

    int plane, band_num, indx, transform_id, scan_indx;

    int i;

    int quant_mat;



    plane    = get_bits(&ctx->gb, 2);

    band_num = get_bits(&ctx->gb, 4);

    if (band->plane != plane || band->band_num != band_num) {

        av_log(avctx, AV_LOG_ERROR, "Invalid band header sequence!\n");

        return AVERROR_INVALIDDATA;

    }



    band->is_empty = get_bits1(&ctx->gb);

    if (!band->is_empty) {

        /* skip header size

         * If header size is not given, header size is 4 bytes. */

        if (get_bits1(&ctx->gb))

            skip_bits(&ctx->gb, 16);



        band->is_halfpel = get_bits(&ctx->gb, 2);

        if (band->is_halfpel >= 2) {

            av_log(avctx, AV_LOG_ERROR, "Invalid/unsupported mv resolution: %d!\n",

                   band->is_halfpel);

            return AVERROR_INVALIDDATA;

        }

#if IVI4_STREAM_ANALYSER

        if (!band->is_halfpel)

            ctx->uses_fullpel = 1;

#endif



        band->checksum_present = get_bits1(&ctx->gb);

        if (band->checksum_present)

            band->checksum = get_bits(&ctx->gb, 16);



        indx = get_bits(&ctx->gb, 2);

        if (indx == 3) {

            av_log(avctx, AV_LOG_ERROR, "Invalid block size!\n");

            return AVERROR_INVALIDDATA;

        }

        band->mb_size  = 16 >> indx;

        band->blk_size = 8 >> (indx >> 1);



        band->inherit_mv     = get_bits1(&ctx->gb);

        band->inherit_qdelta = get_bits1(&ctx->gb);



        band->glob_quant = get_bits(&ctx->gb, 5);



        if (!get_bits1(&ctx->gb) || ctx->frame_type == FRAMETYPE_INTRA) {

            transform_id = get_bits(&ctx->gb, 5);

            if (transform_id >= FF_ARRAY_ELEMS(transforms) ||

                !transforms[transform_id].inv_trans) {

                av_log_ask_for_sample(avctx, "Unimplemented transform: %d!\n", transform_id);

                return AVERROR_PATCHWELCOME;

            }

            if ((transform_id >= 7 && transform_id <= 9) ||

                 transform_id == 17) {

                av_log_ask_for_sample(avctx, "DCT transform not supported yet!\n");

                return AVERROR_PATCHWELCOME;

            }



            if (transform_id < 10 && band->blk_size < 8) {

                av_log(avctx, AV_LOG_ERROR, "wrong transform size!\n");

                return AVERROR_INVALIDDATA;

            }

#if IVI4_STREAM_ANALYSER

            if ((transform_id >= 0 && transform_id <= 2) || transform_id == 10)

                ctx->uses_haar = 1;

#endif



            band->inv_transform = transforms[transform_id].inv_trans;

            band->dc_transform  = transforms[transform_id].dc_trans;

            band->is_2d_trans   = transforms[transform_id].is_2d_trans;

            band->transform_size= (transform_id < 10) ? 8 : 4;



            scan_indx = get_bits(&ctx->gb, 4);

            if ((scan_indx>4 && scan_indx<10) != (band->blk_size==4)) {

                av_log(avctx, AV_LOG_ERROR, "mismatching scan table!\n");

                return AVERROR_INVALIDDATA;

            }

            if (scan_indx == 15) {

                av_log(avctx, AV_LOG_ERROR, "Custom scan pattern encountered!\n");

                return AVERROR_INVALIDDATA;

            }

            band->scan = scan_index_to_tab[scan_indx];



            quant_mat = get_bits(&ctx->gb, 5);

            if (quant_mat == 31) {

                av_log(avctx, AV_LOG_ERROR, "Custom quant matrix encountered!\n");

                return AVERROR_INVALIDDATA;

            }

            if (quant_mat > 21) {

                av_log(avctx, AV_LOG_ERROR, "Invalid quant matrix encountered!\n");

                return AVERROR_INVALIDDATA;

            }

            band->quant_mat = quant_mat;

        }



        /* decode block huffman codebook */

        if (ff_ivi_dec_huff_desc(&ctx->gb, get_bits1(&ctx->gb), IVI_BLK_HUFF,

                                 &band->blk_vlc, avctx))

            return AVERROR_INVALIDDATA;



        /* select appropriate rvmap table for this band */

        band->rvmap_sel = get_bits1(&ctx->gb) ? get_bits(&ctx->gb, 3) : 8;



        /* decode rvmap probability corrections if any */

        band->num_corr = 0; /* there is no corrections */

        if (get_bits1(&ctx->gb)) {

            band->num_corr = get_bits(&ctx->gb, 8); /* get number of correction pairs */

            if (band->num_corr > 61) {

                av_log(avctx, AV_LOG_ERROR, "Too many corrections: %d\n",

                       band->num_corr);

                return AVERROR_INVALIDDATA;

            }



            /* read correction pairs */

            for (i = 0; i < band->num_corr * 2; i++)

                band->corr[i] = get_bits(&ctx->gb, 8);

        }

    }



    if (band->blk_size == 8) {

        band->intra_base = &ivi4_quant_8x8_intra[quant_index_to_tab[band->quant_mat]][0];

        band->inter_base = &ivi4_quant_8x8_inter[quant_index_to_tab[band->quant_mat]][0];

    } else {

        band->intra_base = &ivi4_quant_4x4_intra[quant_index_to_tab[band->quant_mat]][0];

        band->inter_base = &ivi4_quant_4x4_inter[quant_index_to_tab[band->quant_mat]][0];

    }



    /* Indeo 4 doesn't use scale tables */

    band->intra_scale = NULL;

    band->inter_scale = NULL;



    align_get_bits(&ctx->gb);



    if (!band->scan) {

        av_log(avctx, AV_LOG_ERROR, "band->scan not set\n");

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static int decode_pic_hdr(IVI45DecContext *ctx, AVCodecContext *avctx)

{

    int             pic_size_indx, i, p;

    IVIPicConfig    pic_conf;



    if (get_bits(&ctx->gb, 18) != 0x3FFF8) {

        av_log(avctx, AV_LOG_ERROR, "Invalid picture start code!\n");

        return AVERROR_INVALIDDATA;

    }



    ctx->prev_frame_type = ctx->frame_type;

    ctx->frame_type      = get_bits(&ctx->gb, 3);

    if (ctx->frame_type == 7) {

        av_log(avctx, AV_LOG_ERROR, "Invalid frame type: %d\n", ctx->frame_type);

        return AVERROR_INVALIDDATA;

    }



#if IVI4_STREAM_ANALYSER

    if (ctx->frame_type == FRAMETYPE_BIDIR)

        ctx->has_b_frames = 1;

#endif



    ctx->transp_status = get_bits1(&ctx->gb);

#if IVI4_STREAM_ANALYSER

    if (ctx->transp_status) {

        ctx->has_transp = 1;

    }

#endif



    /* unknown bit: Mac decoder ignores this bit, XANIM returns error */

    if (get_bits1(&ctx->gb)) {

        av_log(avctx, AV_LOG_ERROR, "Sync bit is set!\n");

        return AVERROR_INVALIDDATA;

    }



    ctx->data_size = get_bits1(&ctx->gb) ? get_bits(&ctx->gb, 24) : 0;



    /* null frames don't contain anything else so we just return */

    if (ctx->frame_type >= FRAMETYPE_NULL_FIRST) {

        av_dlog(avctx, "Null frame encountered!\n");

        return 0;

    }



    /* Check key lock status. If enabled - ignore lock word.         */

    /* Usually we have to prompt the user for the password, but      */

    /* we don't do that because Indeo 4 videos can be decoded anyway */

    if (get_bits1(&ctx->gb)) {

        skip_bits_long(&ctx->gb, 32);

        av_dlog(avctx, "Password-protected clip!\n");

    }



    pic_size_indx = get_bits(&ctx->gb, 3);

    if (pic_size_indx == IVI4_PIC_SIZE_ESC) {

        pic_conf.pic_height = get_bits(&ctx->gb, 16);

        pic_conf.pic_width  = get_bits(&ctx->gb, 16);

    } else {

        pic_conf.pic_height = ivi4_common_pic_sizes[pic_size_indx * 2 + 1];

        pic_conf.pic_width  = ivi4_common_pic_sizes[pic_size_indx * 2    ];

    }



    /* Decode tile dimensions. */

    if (get_bits1(&ctx->gb)) {

        pic_conf.tile_height = scale_tile_size(pic_conf.pic_height, get_bits(&ctx->gb, 4));

        pic_conf.tile_width  = scale_tile_size(pic_conf.pic_width,  get_bits(&ctx->gb, 4));

#if IVI4_STREAM_ANALYSER

        ctx->uses_tiling = 1;

#endif

    } else {

        pic_conf.tile_height = pic_conf.pic_height;

        pic_conf.tile_width  = pic_conf.pic_width;

    }



    /* Decode chroma subsampling. We support only 4:4 aka YVU9. */

    if (get_bits(&ctx->gb, 2)) {

        av_log(avctx, AV_LOG_ERROR, "Only YVU9 picture format is supported!\n");

        return AVERROR_INVALIDDATA;

    }

    pic_conf.chroma_height = (pic_conf.pic_height + 3) >> 2;

    pic_conf.chroma_width  = (pic_conf.pic_width  + 3) >> 2;



    /* decode subdivision of the planes */

    pic_conf.luma_bands = decode_plane_subdivision(&ctx->gb);


    if (pic_conf.luma_bands)

        pic_conf.chroma_bands = decode_plane_subdivision(&ctx->gb);

    ctx->is_scalable = pic_conf.luma_bands != 1 || pic_conf.chroma_bands != 1;

    if (ctx->is_scalable && (pic_conf.luma_bands != 4 || pic_conf.chroma_bands != 1)) {

        av_log(avctx, AV_LOG_ERROR, "Scalability: unsupported subdivision! Luma bands: %d, chroma bands: %d\n",

               pic_conf.luma_bands, pic_conf.chroma_bands);

        return AVERROR_INVALIDDATA;

    }



    /* check if picture layout was changed and reallocate buffers */

    if (ivi_pic_config_cmp(&pic_conf, &ctx->pic_conf)) {

        if (ff_ivi_init_planes(ctx->planes, &pic_conf)) {

            av_log(avctx, AV_LOG_ERROR, "Couldn't reallocate color planes!\n");

            return AVERROR(ENOMEM);

        }



        ctx->pic_conf = pic_conf;



        /* set default macroblock/block dimensions */

        for (p = 0; p <= 2; p++) {

            for (i = 0; i < (!p ? pic_conf.luma_bands : pic_conf.chroma_bands); i++) {

                ctx->planes[p].bands[i].mb_size  = !p ? (!ctx->is_scalable ? 16 : 8) : 4;

                ctx->planes[p].bands[i].blk_size = !p ? 8 : 4;

            }

        }



        if (ff_ivi_init_tiles(ctx->planes, ctx->pic_conf.tile_width,

                              ctx->pic_conf.tile_height)) {

            av_log(avctx, AV_LOG_ERROR,

                   "Couldn't reallocate internal structures!\n");

            return AVERROR(ENOMEM);

        }

    }



    ctx->frame_num = get_bits1(&ctx->gb) ? get_bits(&ctx->gb, 20) : 0;



    /* skip decTimeEst field if present */

    if (get_bits1(&ctx->gb))

        skip_bits(&ctx->gb, 8);



    /* decode macroblock and block huffman codebooks */

    if (ff_ivi_dec_huff_desc(&ctx->gb, get_bits1(&ctx->gb), IVI_MB_HUFF,  &ctx->mb_vlc,  avctx) ||

        ff_ivi_dec_huff_desc(&ctx->gb, get_bits1(&ctx->gb), IVI_BLK_HUFF, &ctx->blk_vlc, avctx))

        return AVERROR_INVALIDDATA;



    ctx->rvmap_sel = get_bits1(&ctx->gb) ? get_bits(&ctx->gb, 3) : 8;



    ctx->in_imf = get_bits1(&ctx->gb);

    ctx->in_q   = get_bits1(&ctx->gb);



    ctx->pic_glob_quant = get_bits(&ctx->gb, 5);



    /* TODO: ignore this parameter if unused */

    ctx->unknown1 = get_bits1(&ctx->gb) ? get_bits(&ctx->gb, 3) : 0;



    ctx->checksum = get_bits1(&ctx->gb) ? get_bits(&ctx->gb, 16) : 0;



    /* skip picture header extension if any */

    while (get_bits1(&ctx->gb)) {

        av_dlog(avctx, "Pic hdr extension encountered!\n");

        skip_bits(&ctx->gb, 8);

    }



    if (get_bits1(&ctx->gb)) {

        av_log(avctx, AV_LOG_ERROR, "Bad blocks bits encountered!\n");

    }



    align_get_bits(&ctx->gb);



    return 0;

}

