static int sunrast_decode_frame(AVCodecContext *avctx, void *data,

                                int *data_size, AVPacket *avpkt) {

    const uint8_t *buf = avpkt->data;

    const uint8_t *buf_end = avpkt->data + avpkt->size;

    SUNRASTContext * const s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame * const p = &s->picture;

    unsigned int w, h, depth, type, maptype, maplength, stride, x, y, len, alen;

    uint8_t *ptr;

    const uint8_t *bufstart = buf;



    if (avpkt->size < 32)

        return AVERROR_INVALIDDATA;



    if (AV_RB32(buf) != 0x59a66a95) {

        av_log(avctx, AV_LOG_ERROR, "this is not sunras encoded data\n");

        return -1;

    }



    w         = AV_RB32(buf+4);

    h         = AV_RB32(buf+8);

    depth     = AV_RB32(buf+12);

    type      = AV_RB32(buf+20);

    maptype   = AV_RB32(buf+24);

    maplength = AV_RB32(buf+28);

    buf      += 32;



    if (type == RT_FORMAT_TIFF || type == RT_FORMAT_IFF) {

        av_log(avctx, AV_LOG_ERROR, "unsupported (compression) type\n");

        return -1;

    }

    if (type < RT_OLD || type > RT_FORMAT_IFF) {

        av_log(avctx, AV_LOG_ERROR, "invalid (compression) type\n");

        return -1;

    }

    if (av_image_check_size(w, h, 0, avctx)) {

        av_log(avctx, AV_LOG_ERROR, "invalid image size\n");

        return -1;

    }

    if (maptype & ~1) {

        av_log(avctx, AV_LOG_ERROR, "invalid colormap type\n");

        return -1;

    }





    switch (depth) {

        case 1:

            avctx->pix_fmt = PIX_FMT_MONOWHITE;

            break;

        case 8:

            avctx->pix_fmt = PIX_FMT_PAL8;

            break;

        case 24:

            avctx->pix_fmt = (type == RT_FORMAT_RGB) ? PIX_FMT_RGB24 : PIX_FMT_BGR24;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "invalid depth\n");

            return -1;

    }



    if (p->data[0])

        avctx->release_buffer(avctx, p);



    if (w != avctx->width || h != avctx->height)

        avcodec_set_dimensions(avctx, w, h);

    if (avctx->get_buffer(avctx, p) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    p->pict_type = AV_PICTURE_TYPE_I;



    if (buf_end - buf < maplength)

        return AVERROR_INVALIDDATA;



    if (depth != 8 && maplength) {

        av_log(avctx, AV_LOG_WARNING, "useless colormap found or file is corrupted, trying to recover\n");



    } else if (depth == 8) {

        unsigned int len = maplength / 3;



        if (!maplength) {

            av_log(avctx, AV_LOG_ERROR, "colormap expected\n");

            return -1;

        }

        if (maplength % 3 || maplength > 768) {

            av_log(avctx, AV_LOG_WARNING, "invalid colormap length\n");

            return -1;

        }



        ptr = p->data[1];

        for (x=0; x<len; x++, ptr+=4)

            *(uint32_t *)ptr = (buf[x]<<16) + (buf[len+x]<<8) + buf[len+len+x];

    }



    buf += maplength;



    ptr    = p->data[0];

    stride = p->linesize[0];



    /* scanlines are aligned on 16 bit boundaries */

    len  = (depth * w + 7) >> 3;

    alen = len + (len&1);



    if (type == RT_BYTE_ENCODED) {

        int value, run;

        uint8_t *end = ptr + h*stride;



        x = 0;

        while (ptr != end && buf < buf_end) {

            run = 1;

            if (buf_end - buf < 1)

                return AVERROR_INVALIDDATA;



            if ((value = *buf++) == 0x80) {

                run = *buf++ + 1;

                if (run != 1)

                    value = *buf++;

            }

            while (run--) {

                if (x < len)

                    ptr[x] = value;

                if (++x >= alen) {

                    x = 0;

                    ptr += stride;

                    if (ptr == end)

                        break;

                }

            }

        }

    } else {

        for (y=0; y<h; y++) {

            if (buf_end - buf < len)

                break;

            memcpy(ptr, buf, len);

            ptr += stride;

            buf += alen;

        }

    }



    *picture = s->picture;

    *data_size = sizeof(AVFrame);



    return buf - bufstart;

}

static int decode_frame(AVCodecContext *avctx,

                        void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    TiffContext *const s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame *const p = &s->picture;

    const uint8_t *orig_buf = buf, *end_buf = buf + buf_size;

    unsigned off;

    int id, le, ret;

    int i, j, entries;

    int stride;

    unsigned soff, ssize;

    uint8_t *dst;



    //parse image header

    if (end_buf - buf < 8)

        return AVERROR_INVALIDDATA;

    id = AV_RL16(buf);

    buf += 2;

    if (id == 0x4949)

        le = 1;

    else if (id == 0x4D4D)

        le = 0;

    else {

        av_log(avctx, AV_LOG_ERROR, "TIFF header not found\n");

        return -1;

    }

    s->le = le;

    s->invert = 0;

    s->compr = TIFF_RAW;

    s->fill_order = 0;

    free_geotags(s);

    /* free existing metadata */

    av_dict_free(&s->picture.metadata);



    // As TIFF 6.0 specification puts it "An arbitrary but carefully chosen number

    // that further identifies the file as a TIFF file"

    if (tget_short(&buf, le) != 42) {

        av_log(avctx, AV_LOG_ERROR,

               "The answer to life, universe and everything is not correct!\n");

        return -1;

    }

    // Reset these pointers so we can tell if they were set this frame

    s->stripsizes = s->stripdata = NULL;

    /* parse image file directory */

    off = tget_long(&buf, le);

    if (off >= UINT_MAX - 14 || end_buf - orig_buf < off + 14) {

        av_log(avctx, AV_LOG_ERROR, "IFD offset is greater than image size\n");

        return AVERROR_INVALIDDATA;

    }

    buf = orig_buf + off;

    entries = tget_short(&buf, le);

    for (i = 0; i < entries; i++) {

        if (tiff_decode_tag(s, orig_buf, buf, end_buf) < 0)

            return -1;

        buf += 12;

    }



    for (i = 0; i<s->geotag_count; i++) {

        const char *keyname = get_geokey_name(s->geotags[i].key);

        if (!keyname) {

            av_log(avctx, AV_LOG_WARNING, "Unknown or unsupported GeoTIFF key %d\n", s->geotags[i].key);

            continue;

        }

        if (get_geokey_type(s->geotags[i].key) != s->geotags[i].type) {

            av_log(avctx, AV_LOG_WARNING, "Type of GeoTIFF key %d is wrong\n", s->geotags[i].key);

            continue;

        }

        ret = av_dict_set(&s->picture.metadata, keyname, s->geotags[i].val, 0);

        if (ret<0) {

            av_log(avctx, AV_LOG_ERROR, "Writing metadata with key '%s' failed\n", keyname);

            return ret;

        }

    }



    if (!s->stripdata && !s->stripoff) {

        av_log(avctx, AV_LOG_ERROR, "Image data is missing\n");

        return -1;

    }

    /* now we have the data and may start decoding */

    if ((ret = init_image(s)) < 0)

        return ret;



    if (s->strips == 1 && !s->stripsize) {

        av_log(avctx, AV_LOG_WARNING, "Image data size missing\n");

        s->stripsize = buf_size - s->stripoff;

    }

    stride = p->linesize[0];

    dst = p->data[0];

    for (i = 0; i < s->height; i += s->rps) {

        if (s->stripsizes) {

            if (s->stripsizes >= end_buf)

                return AVERROR_INVALIDDATA;

            ssize = tget(&s->stripsizes, s->sstype, s->le);

        } else

            ssize = s->stripsize;



        if (s->stripdata) {

            if (s->stripdata >= end_buf)

                return AVERROR_INVALIDDATA;

            soff = tget(&s->stripdata, s->sot, s->le);

        } else

            soff = s->stripoff;



        if (soff > buf_size || ssize > buf_size - soff) {

            av_log(avctx, AV_LOG_ERROR, "Invalid strip size/offset\n");

            return -1;

        }

        if (tiff_unpack_strip(s, dst, stride, orig_buf + soff, ssize,

                              FFMIN(s->rps, s->height - i)) < 0)

            break;

        dst += s->rps * stride;

    }

    if (s->predictor == 2) {

        dst = p->data[0];

        soff = s->bpp >> 3;

        ssize = s->width * soff;

        if (s->avctx->pix_fmt == PIX_FMT_RGB48LE ||

            s->avctx->pix_fmt == PIX_FMT_RGBA64LE) {

            for (i = 0; i < s->height; i++) {

                for (j = soff; j < ssize; j += 2)

                    AV_WL16(dst + j, AV_RL16(dst + j) + AV_RL16(dst + j - soff));

                dst += stride;

            }

        } else if (s->avctx->pix_fmt == PIX_FMT_RGB48BE ||

                   s->avctx->pix_fmt == PIX_FMT_RGBA64BE) {

            for (i = 0; i < s->height; i++) {

                for (j = soff; j < ssize; j += 2)

                    AV_WB16(dst + j, AV_RB16(dst + j) + AV_RB16(dst + j - soff));

                dst += stride;

            }

        } else {

            for (i = 0; i < s->height; i++) {

                for (j = soff; j < ssize; j++)

                    dst[j] += dst[j - soff];

                dst += stride;

            }

        }

    }



    if (s->invert) {

        dst = s->picture.data[0];

        for (i = 0; i < s->height; i++) {

            for (j = 0; j < s->picture.linesize[0]; j++)

                dst[j] = (s->avctx->pix_fmt == PIX_FMT_PAL8 ? (1<<s->bpp) - 1 : 255) - dst[j];

            dst += s->picture.linesize[0];

        }

    }

    *picture   = s->picture;

    *data_size = sizeof(AVPicture);



    return buf_size;

}

static void spapr_tce_reset(DeviceState *dev)

{

    sPAPRTCETable *tcet = SPAPR_TCE_TABLE(dev);

    size_t table_size = tcet->nb_table * sizeof(uint64_t);



    memset(tcet->table, 0, table_size);

}

static void ioreq_release(struct ioreq *ioreq, bool finish)

{

    struct XenBlkDev *blkdev = ioreq->blkdev;



    QLIST_REMOVE(ioreq, list);

    memset(ioreq, 0, sizeof(*ioreq));

    ioreq->blkdev = blkdev;

    QLIST_INSERT_HEAD(&blkdev->freelist, ioreq, list);

    if (finish) {

        blkdev->requests_finished--;

    } else {

        blkdev->requests_inflight--;

    }

}

