    s->mb_qmin= 2;

    s->mb_qmax= 31;

    s->rc_eq= "tex^qComp";

    s->qcompress= 0.5;

    s->max_qdiff= 3;

    s->b_quant_factor=1.25;

    s->b_quant_offset=1.25;

    s->i_quant_factor=-0.8;

    s->i_quant_offset=0.0;

    s->error_concealment= 3;

    s->error_resilience= 1;

    s->workaround_bugs= FF_BUG_AUTODETECT;

    s->frame_rate_base= 1;

    s->frame_rate = 25;

    s->gop_size= 50;

