static void tcp_wait_for_connect(int fd, Error *err, void *opaque)

{

    MigrationState *s = opaque;



    if (fd < 0) {

        DPRINTF("migrate connect error: %s\n", error_get_pretty(err));

        s->to_dst_file = NULL;

        migrate_fd_error(s);

    } else {

        DPRINTF("migrate connect success\n");

        s->to_dst_file = qemu_fopen_socket(fd, "wb");

        migrate_fd_connect(s);

    }

}

void fd_start_outgoing_migration(MigrationState *s, const char *fdname, Error **errp)

{

    int fd = monitor_get_fd(cur_mon, fdname, errp);

    if (fd == -1) {

        return;

    }

    s->file = qemu_fdopen(fd, "wb");



    migrate_fd_connect(s);

}

static void migrate_fd_put_notify(void *opaque)

{

    MigrationState *s = opaque;



    qemu_set_fd_handler2(s->fd, NULL, NULL, NULL, NULL);

    qemu_file_put_notify(s->file);

    if (qemu_file_get_error(s->file)) {

        migrate_fd_error(s);

    }

}

static void tcp_wait_for_connect(void *opaque)

{

    MigrationState *s = opaque;

    int val, ret;

    socklen_t valsize = sizeof(val);



    DPRINTF("connect completed\n");

    do {

        ret = getsockopt(s->fd, SOL_SOCKET, SO_ERROR, (void *) &val, &valsize);

    } while (ret == -1 && (socket_error()) == EINTR);



    if (ret < 0) {

        migrate_fd_error(s);

        return;

    }



    qemu_set_fd_handler2(s->fd, NULL, NULL, NULL, NULL);



    if (val == 0)

        migrate_fd_connect(s);

    else {

        DPRINTF("error connecting %d\n", val);

        migrate_fd_error(s);

    }

}

static int encode_picture_lossless(AVCodecContext *avctx, AVPacket *pkt,
                                   const AVFrame *pict, int *got_packet)
{
    MpegEncContext * const s = avctx->priv_data;
    MJpegContext * const m = s->mjpeg_ctx;
    const int width= s->width;
    const int height= s->height;
    AVFrame * const p = &s->current_picture.f;
    const int predictor= avctx->prediction_method+1;
    const int mb_width  = (width  + s->mjpeg_hsample[0] - 1) / s->mjpeg_hsample[0];
    const int mb_height = (height + s->mjpeg_vsample[0] - 1) / s->mjpeg_vsample[0];
    int ret, max_pkt_size = FF_MIN_BUFFER_SIZE;
    if (avctx->pix_fmt == AV_PIX_FMT_BGRA)
        max_pkt_size += width * height * 3 * 4;
    else {
        max_pkt_size += mb_width * mb_height * 3 * 4
                        * s->mjpeg_hsample[0] * s->mjpeg_vsample[0];
    if ((ret = ff_alloc_packet2(avctx, pkt, max_pkt_size)) < 0)
    init_put_bits(&s->pb, pkt->data, pkt->size);
    *p = *pict;
    p->pict_type= AV_PICTURE_TYPE_I;
    p->key_frame= 1;
    ff_mjpeg_encode_picture_header(s);
    s->header_bits= put_bits_count(&s->pb);
    if(avctx->pix_fmt == AV_PIX_FMT_BGR0
        || avctx->pix_fmt == AV_PIX_FMT_BGRA
        || avctx->pix_fmt == AV_PIX_FMT_BGR24){
        int x, y, i;
        const int linesize= p->linesize[0];
        uint16_t (*buffer)[4]= (void *) s->rd_scratchpad;
        int left[3], top[3], topleft[3];
        for(i=0; i<3; i++){
            buffer[0][i]= 1 << (9 - 1);
        for(y = 0; y < height; y++) {
            const int modified_predictor= y ? predictor : 1;
            uint8_t *ptr = p->data[0] + (linesize * y);
            if(s->pb.buf_end - s->pb.buf - (put_bits_count(&s->pb)>>3) < width*3*4){
                av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");
                return -1;
            for(i=0; i<3; i++){
                top[i]= left[i]= topleft[i]= buffer[0][i];
            for(x = 0; x < width; x++) {
                if(avctx->pix_fmt == AV_PIX_FMT_BGR24){
                    buffer[x][1] = ptr[3*x+0] - ptr[3*x+1] + 0x100;
                    buffer[x][2] = ptr[3*x+2] - ptr[3*x+1] + 0x100;
                    buffer[x][0] = (ptr[3*x+0] + 2*ptr[3*x+1] + ptr[3*x+2])>>2;
                }else{
                buffer[x][1] = ptr[4*x+0] - ptr[4*x+1] + 0x100;
                buffer[x][2] = ptr[4*x+2] - ptr[4*x+1] + 0x100;
                buffer[x][0] = (ptr[4*x+0] + 2*ptr[4*x+1] + ptr[4*x+2])>>2;
                for(i=0;i<3;i++) {
                    int pred, diff;
                    PREDICT(pred, topleft[i], top[i], left[i], modified_predictor);
                    topleft[i]= top[i];
                    top[i]= buffer[x+1][i];
                    left[i]= buffer[x][i];
                    diff= ((left[i] - pred + 0x100)&0x1FF) - 0x100;
                    if(i==0)
                        ff_mjpeg_encode_dc(s, diff, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly
                    else
                        ff_mjpeg_encode_dc(s, diff, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);
    }else{
        int mb_x, mb_y, i;
        for(mb_y = 0; mb_y < mb_height; mb_y++) {
            if(s->pb.buf_end - s->pb.buf - (put_bits_count(&s->pb)>>3) < mb_width * 4 * 3 * s->mjpeg_hsample[0] * s->mjpeg_vsample[0]){
                av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");
                return -1;
            for(mb_x = 0; mb_x < mb_width; mb_x++) {
                if(mb_x==0 || mb_y==0){
                    for(i=0;i<3;i++) {
                        uint8_t *ptr;
                        int x, y, h, v, linesize;
                        h = s->mjpeg_hsample[i];
                        v = s->mjpeg_vsample[i];
                        linesize= p->linesize[i];
                        for(y=0; y<v; y++){
                            for(x=0; x<h; x++){
                                int pred;
                                ptr = p->data[i] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap
                                if(y==0 && mb_y==0){
                                    if(x==0 && mb_x==0){
                                        pred= 128;
                                    }else{
                                        pred= ptr[-1];
                                }else{
                                    if(x==0 && mb_x==0){
                                        pred= ptr[-linesize];
                                    }else{
                                        PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);
                                if(i==0)
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly
                                else
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);
                }else{
                    for(i=0;i<3;i++) {
                        uint8_t *ptr;
                        int x, y, h, v, linesize;
                        h = s->mjpeg_hsample[i];
                        v = s->mjpeg_vsample[i];
                        linesize= p->linesize[i];
                        for(y=0; y<v; y++){
                            for(x=0; x<h; x++){
                                int pred;
                                ptr = p->data[i] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap
                                PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);
                                if(i==0)
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly
                                else
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);
    emms_c();
    av_assert0(s->esc_pos == s->header_bits >> 3);
    ff_mjpeg_encode_stuffing(s);
    ff_mjpeg_encode_picture_trailer(s);
    s->picture_number++;
    flush_put_bits(&s->pb);
    pkt->size   = put_bits_ptr(&s->pb) - s->pb.buf;
    pkt->flags |= AV_PKT_FLAG_KEY;
    *got_packet = 1;
    return 0;
//    return (put_bits_count(&f->pb)+7)/8;

static int encode_picture_ls(AVCodecContext *avctx, AVPacket *pkt,

                             const AVFrame *pict, int *got_packet)

{

    const AVFrame *const p = pict;

    const int near         = avctx->prediction_method;

    PutBitContext pb, pb2;

    GetBitContext gb;

    uint8_t *buf2, *zero, *cur, *last;

    JLSState *state;

    int i, size, ret;

    int comps;



    if (avctx->pix_fmt == AV_PIX_FMT_GRAY8 ||

        avctx->pix_fmt == AV_PIX_FMT_GRAY16)

        comps = 1;

    else

        comps = 3;



    if ((ret = ff_alloc_packet(pkt, avctx->width * avctx->height * comps * 4 +

                               FF_MIN_BUFFER_SIZE)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    buf2 = av_malloc(pkt->size);



    init_put_bits(&pb, pkt->data, pkt->size);

    init_put_bits(&pb2, buf2, pkt->size);



    /* write our own JPEG header, can't use mjpeg_picture_header */

    put_marker(&pb, SOI);

    put_marker(&pb, SOF48);

    put_bits(&pb, 16, 8 + comps * 3); // header size depends on components

    put_bits(&pb, 8, (avctx->pix_fmt == AV_PIX_FMT_GRAY16) ? 16 : 8);  // bpp

    put_bits(&pb, 16, avctx->height);

    put_bits(&pb, 16, avctx->width);

    put_bits(&pb, 8, comps);          // components

    for (i = 1; i <= comps; i++) {

        put_bits(&pb, 8, i);     // component ID

        put_bits(&pb, 8, 0x11);  // subsampling: none

        put_bits(&pb, 8, 0);     // Tiq, used by JPEG-LS ext

    }



    put_marker(&pb, SOS);

    put_bits(&pb, 16, 6 + comps * 2);

    put_bits(&pb, 8, comps);

    for (i = 1; i <= comps; i++) {

        put_bits(&pb, 8, i);   // component ID

        put_bits(&pb, 8, 0);   // mapping index: none

    }

    put_bits(&pb, 8, near);

    put_bits(&pb, 8, (comps > 1) ? 1 : 0);  // interleaving: 0 - plane, 1 - line

    put_bits(&pb, 8, 0);  // point transform: none



    state = av_mallocz(sizeof(JLSState));

    /* initialize JPEG-LS state from JPEG parameters */

    state->near = near;

    state->bpp  = (avctx->pix_fmt == AV_PIX_FMT_GRAY16) ? 16 : 8;

    ff_jpegls_reset_coding_parameters(state, 0);

    ff_jpegls_init_state(state);



    ls_store_lse(state, &pb);



    zero = av_mallocz(p->linesize[0]);

    last = zero;

    cur  = p->data[0];

    if (avctx->pix_fmt == AV_PIX_FMT_GRAY8) {

        int t = 0;



        for (i = 0; i < avctx->height; i++) {

            ls_encode_line(state, &pb2, last, cur, t, avctx->width, 1, 0, 8);

            t    = last[0];

            last = cur;

            cur += p->linesize[0];

        }

    } else if (avctx->pix_fmt == AV_PIX_FMT_GRAY16) {

        int t = 0;



        for (i = 0; i < avctx->height; i++) {

            ls_encode_line(state, &pb2, last, cur, t, avctx->width, 1, 0, 16);

            t    = *((uint16_t *)last);

            last = cur;

            cur += p->linesize[0];

        }

    } else if (avctx->pix_fmt == AV_PIX_FMT_RGB24) {

        int j, width;

        int Rc[3] = { 0, 0, 0 };



        width = avctx->width * 3;

        for (i = 0; i < avctx->height; i++) {

            for (j = 0; j < 3; j++) {

                ls_encode_line(state, &pb2, last + j, cur + j, Rc[j],

                               width, 3, j, 8);

                Rc[j] = last[j];

            }

            last = cur;

            cur += p->linesize[0];

        }

    } else if (avctx->pix_fmt == AV_PIX_FMT_BGR24) {

        int j, width;

        int Rc[3] = { 0, 0, 0 };



        width = avctx->width * 3;

        for (i = 0; i < avctx->height; i++) {

            for (j = 2; j >= 0; j--) {

                ls_encode_line(state, &pb2, last + j, cur + j, Rc[j],

                               width, 3, j, 8);

                Rc[j] = last[j];

            }

            last = cur;

            cur += p->linesize[0];

        }

    }



    av_free(zero);

    av_free(state);



    /* the specification says that after doing 0xff escaping unused bits in

     * the last byte must be set to 0, so just append 7 "optional" zero-bits

     * to avoid special-casing. */

    put_bits(&pb2, 7, 0);

    size = put_bits_count(&pb2);

    flush_put_bits(&pb2);

    /* do escape coding */

    init_get_bits(&gb, buf2, size);

    size -= 7;

    while (get_bits_count(&gb) < size) {

        int v;

        v = get_bits(&gb, 8);

        put_bits(&pb, 8, v);

        if (v == 0xFF) {

            v = get_bits(&gb, 7);

            put_bits(&pb, 8, v);

        }

    }

    avpriv_align_put_bits(&pb);

    av_free(buf2);



    /* End of image */

    put_marker(&pb, EOI);

    flush_put_bits(&pb);



    emms_c();



    pkt->size   = put_bits_count(&pb) >> 3;

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;

    return 0;

}

static int ljpeg_encode_bgr(AVCodecContext *avctx, PutBitContext *pb,

                            const AVFrame *frame)

{

    LJpegEncContext *s    = avctx->priv_data;

    const int width       = frame->width;

    const int height      = frame->height;

    const int linesize    = frame->linesize[0];

    uint16_t (*buffer)[4] = s->scratch;

    const int predictor   = avctx->prediction_method+1;

    int left[3], top[3], topleft[3];

    int x, y, i;



    for (i = 0; i < 3; i++)

        buffer[0][i] = 1 << (9 - 1);



    for (y = 0; y < height; y++) {

        const int modified_predictor = y ? predictor : 1;

        uint8_t *ptr = frame->data[0] + (linesize * y);



        if (pb->buf_end - pb->buf - (put_bits_count(pb) >> 3) < width * 3 * 3) {

            av_log(avctx, AV_LOG_ERROR, "encoded frame too large\n");

            return -1;

        }



        for (i = 0; i < 3; i++)

            top[i]= left[i]= topleft[i]= buffer[0][i];



        for (x = 0; x < width; x++) {

            buffer[x][1] =  ptr[3 * x + 0] -     ptr[3 * x + 1] + 0x100;

            buffer[x][2] =  ptr[3 * x + 2] -     ptr[3 * x + 1] + 0x100;

            buffer[x][0] = (ptr[3 * x + 0] + 2 * ptr[3 * x + 1] + ptr[3 * x + 2]) >> 2;



            for (i = 0; i < 3; i++) {

                int pred, diff;



                PREDICT(pred, topleft[i], top[i], left[i], modified_predictor);



                topleft[i] = top[i];

                top[i]     = buffer[x+1][i];



                left[i]    = buffer[x][i];



                diff       = ((left[i] - pred + 0x100) & 0x1FF) - 0x100;



                if (i == 0)

                    ff_mjpeg_encode_dc(pb, diff, s->huff_size_dc_luminance, s->huff_code_dc_luminance); //FIXME ugly

                else

                    ff_mjpeg_encode_dc(pb, diff, s->huff_size_dc_chrominance, s->huff_code_dc_chrominance);

            }

        }

    }



    return 0;

}

static int encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                        const AVFrame *pic, int *got_packet)

{

    ProresContext *ctx = avctx->priv_data;

    uint8_t *orig_buf, *buf, *slice_hdr, *slice_sizes, *tmp;

    uint8_t *picture_size_pos;

    PutBitContext pb;

    int x, y, i, mb, q = 0;

    int sizes[4] = { 0 };

    int slice_hdr_size = 2 + 2 * (ctx->num_planes - 1);

    int frame_size, picture_size, slice_size;

    int mbs_per_slice = ctx->mbs_per_slice;

    int pkt_size, ret;



    *avctx->coded_frame           = *pic;

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

    avctx->coded_frame->key_frame = 1;



    pkt_size = ctx->mb_width * ctx->mb_height * 64 * 3 * 12

               + ctx->num_slices * 2 + 200 + FF_MIN_BUFFER_SIZE;



    if ((ret = ff_alloc_packet(pkt, pkt_size)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    orig_buf = pkt->data;



    // frame atom

    orig_buf += 4;                              // frame size

    bytestream_put_be32  (&orig_buf, FRAME_ID); // frame container ID

    buf = orig_buf;



    // frame header

    tmp = buf;

    buf += 2;                                   // frame header size will be stored here

    bytestream_put_be16  (&buf, 0);             // version 1

    bytestream_put_buffer(&buf, "Lavc", 4);     // creator

    bytestream_put_be16  (&buf, avctx->width);

    bytestream_put_be16  (&buf, avctx->height);

    bytestream_put_byte  (&buf, ctx->chroma_factor << 6); // frame flags

    bytestream_put_byte  (&buf, 0);             // reserved

    bytestream_put_byte  (&buf, 0);             // primaries

    bytestream_put_byte  (&buf, 0);             // transfer function

    bytestream_put_byte  (&buf, 6);             // colour matrix - ITU-R BT.601-4

    bytestream_put_byte  (&buf, 0x40);          // source format and alpha information

    bytestream_put_byte  (&buf, 0);             // reserved

    bytestream_put_byte  (&buf, 0x03);          // matrix flags - both matrices are present

    // luma quantisation matrix

    for (i = 0; i < 64; i++)

        bytestream_put_byte(&buf, ctx->profile_info->quant[i]);

    // chroma quantisation matrix

    for (i = 0; i < 64; i++)

        bytestream_put_byte(&buf, ctx->profile_info->quant[i]);

    bytestream_put_be16  (&tmp, buf - orig_buf); // write back frame header size



    // picture header

    picture_size_pos = buf + 1;

    bytestream_put_byte  (&buf, 0x40);          // picture header size (in bits)

    buf += 4;                                   // picture data size will be stored here

    bytestream_put_be16  (&buf, ctx->num_slices); // total number of slices

    bytestream_put_byte  (&buf, av_log2(ctx->mbs_per_slice) << 4); // slice width and height in MBs



    // seek table - will be filled during slice encoding

    slice_sizes = buf;

    buf += ctx->num_slices * 2;



    // slices

    for (y = 0; y < ctx->mb_height; y++) {

        mbs_per_slice = ctx->mbs_per_slice;

        for (x = mb = 0; x < ctx->mb_width; x += mbs_per_slice, mb++) {

            while (ctx->mb_width - x < mbs_per_slice)

                mbs_per_slice >>= 1;

            q = find_slice_quant(avctx, pic, (mb + 1) * TRELLIS_WIDTH, x, y,

                                 mbs_per_slice);

        }



        for (x = ctx->slices_width - 1; x >= 0; x--) {

            ctx->slice_q[x] = ctx->nodes[q].quant;

            q = ctx->nodes[q].prev_node;

        }



        mbs_per_slice = ctx->mbs_per_slice;

        for (x = mb = 0; x < ctx->mb_width; x += mbs_per_slice, mb++) {

            q = ctx->slice_q[mb];



            while (ctx->mb_width - x < mbs_per_slice)

                mbs_per_slice >>= 1;



            bytestream_put_byte(&buf, slice_hdr_size << 3);

            slice_hdr = buf;

            buf += slice_hdr_size - 1;

            init_put_bits(&pb, buf, (pkt_size - (buf - orig_buf)) * 8);

            encode_slice(avctx, pic, &pb, sizes, x, y, q, mbs_per_slice);



            bytestream_put_byte(&slice_hdr, q);

            slice_size = slice_hdr_size + sizes[ctx->num_planes - 1];

            for (i = 0; i < ctx->num_planes - 1; i++) {

                bytestream_put_be16(&slice_hdr, sizes[i]);

                slice_size += sizes[i];

            }

            bytestream_put_be16(&slice_sizes, slice_size);

            buf += slice_size - slice_hdr_size;

        }

    }



    orig_buf -= 8;

    frame_size = buf - orig_buf;

    picture_size = buf - picture_size_pos - 6;

    bytestream_put_be32(&orig_buf, frame_size);

    bytestream_put_be32(&picture_size_pos, picture_size);



    pkt->size   = frame_size;

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

int av_vsrc_buffer_add_frame2(AVFilterContext *buffer_filter, AVFrame *frame,

                              int64_t pts, AVRational pixel_aspect, int width,

                              int height, enum PixelFormat  pix_fmt,

                              const char *sws_param)

{

    BufferSourceContext *c = buffer_filter->priv;

    int ret;



    if (c->has_frame) {

        av_log(buffer_filter, AV_LOG_ERROR,

               "Buffering several frames is not supported. "

               "Please consume all available frames before adding a new one.\n"

            );

        //return -1;

    }



    if(width != c->w || height != c->h || pix_fmt != c->pix_fmt){

        AVFilterContext *scale= buffer_filter->outputs[0]->dst;

        AVFilterLink *link;



        av_log(buffer_filter, AV_LOG_INFO, "Changing filter graph input to accept %dx%d %d (%d %d)\n",

               width,height,pix_fmt, c->pix_fmt, scale->outputs[0]->format);



        if(!scale || strcmp(scale->filter->name,"scale")){

            AVFilter *f= avfilter_get_by_name("scale");



            av_log(buffer_filter, AV_LOG_INFO, "Inserting scaler filter\n");

            if(avfilter_open(&scale, f, "Input equalizer") < 0)

                return -1;



            if((ret=avfilter_init_filter(scale, sws_param, NULL))<0){

                avfilter_free(scale);

                return ret;

            }



            if((ret=avfilter_insert_filter(buffer_filter->outputs[0], scale, 0, 0))<0){

                avfilter_free(scale);

                return ret;

            }



            scale->outputs[0]->format= c->pix_fmt;

        }



        c->pix_fmt= scale->inputs[0]->format= pix_fmt;

        c->w= scale->inputs[0]->w= width;

        c->h= scale->inputs[0]->h= height;



        link= scale->outputs[0];

        if ((ret =  link->srcpad->config_props(link)) < 0)

            return ret;

    }



    memcpy(c->frame.data    , frame->data    , sizeof(frame->data));

    memcpy(c->frame.linesize, frame->linesize, sizeof(frame->linesize));

    c->frame.interlaced_frame= frame->interlaced_frame;

    c->frame.top_field_first = frame->top_field_first;

    c->frame.key_frame = frame->key_frame;

    c->frame.pict_type = frame->pict_type;

    c->pts = pts;

    c->pixel_aspect = pixel_aspect;

    c->has_frame = 1;



    return 0;

}

int av_buffersrc_add_ref(AVFilterContext *buffer_filter,

                         AVFilterBufferRef *picref, int flags)

{

    BufferSourceContext *c = buffer_filter->priv;

    AVFilterLink *outlink = buffer_filter->outputs[0];

    AVFilterBufferRef *buf;

    int ret;



    if (!picref) {

        c->eof = 1;

        return 0;

    } else if (c->eof)

        return AVERROR(EINVAL);



    if (!av_fifo_space(c->fifo) &&

        (ret = av_fifo_realloc2(c->fifo, av_fifo_size(c->fifo) +

                                         sizeof(buf))) < 0)

        return ret;



    if (!(flags & AV_BUFFERSRC_FLAG_NO_CHECK_FORMAT)) {

        /* TODO reindent */

    if (picref->video->w != c->w || picref->video->h != c->h || picref->format != c->pix_fmt) {

        AVFilterContext *scale = buffer_filter->outputs[0]->dst;

        AVFilterLink *link;

        char scale_param[1024];



        av_log(buffer_filter, AV_LOG_INFO,

               "Buffer video input changed from size:%dx%d fmt:%s to size:%dx%d fmt:%s\n",

               c->w, c->h, av_pix_fmt_descriptors[c->pix_fmt].name,

               picref->video->w, picref->video->h, av_pix_fmt_descriptors[picref->format].name);



        if (!scale || strcmp(scale->filter->name, "scale")) {

            AVFilter *f = avfilter_get_by_name("scale");



            av_log(buffer_filter, AV_LOG_INFO, "Inserting scaler filter\n");

            if ((ret = avfilter_open(&scale, f, "Input equalizer")) < 0)

                return ret;



            c->scale = scale;



            snprintf(scale_param, sizeof(scale_param)-1, "%d:%d:%s", c->w, c->h, c->sws_param);

            if ((ret = avfilter_init_filter(scale, scale_param, NULL)) < 0) {

                return ret;

            }



            if ((ret = avfilter_insert_filter(buffer_filter->outputs[0], scale, 0, 0)) < 0) {

                return ret;

            }

            scale->outputs[0]->time_base = scale->inputs[0]->time_base;



            scale->outputs[0]->format= c->pix_fmt;

        } else if (!strcmp(scale->filter->name, "scale")) {

            snprintf(scale_param, sizeof(scale_param)-1, "%d:%d:%s",

                     scale->outputs[0]->w, scale->outputs[0]->h, c->sws_param);

            scale->filter->init(scale, scale_param, NULL);

        }



        c->pix_fmt = scale->inputs[0]->format = picref->format;

        c->w       = scale->inputs[0]->w      = picref->video->w;

        c->h       = scale->inputs[0]->h      = picref->video->h;



        link = scale->outputs[0];

        if ((ret =  link->srcpad->config_props(link)) < 0)

            return ret;

    }

    }



    if (flags & AV_BUFFERSRC_FLAG_NO_COPY) {

        buf = picref;

    } else {

    buf = avfilter_get_video_buffer(outlink, AV_PERM_WRITE,

                                    picref->video->w, picref->video->h);

    av_image_copy(buf->data, buf->linesize,

                  (void*)picref->data, picref->linesize,

                  picref->format, picref->video->w, picref->video->h);

    avfilter_copy_buffer_ref_props(buf, picref);



    }



    if ((ret = av_fifo_generic_write(c->fifo, &buf, sizeof(buf), NULL)) < 0) {

        if (buf != picref)

            avfilter_unref_buffer(buf);

        return ret;

    }

    c->nb_failed_requests = 0;



    return 0;

}

int avfilter_config_links(AVFilterContext *filter)

{

    int (*config_link)(AVFilterLink *);

    unsigned i;

    int ret;



    for (i = 0; i < filter->nb_inputs; i ++) {

        AVFilterLink *link = filter->inputs[i];

        AVFilterLink *inlink = link->src->nb_inputs ?

            link->src->inputs[0] : NULL;



        if (!link) continue;



        link->current_pts = AV_NOPTS_VALUE;



        switch (link->init_state) {

        case AVLINK_INIT:

            continue;

        case AVLINK_STARTINIT:

            av_log(filter, AV_LOG_INFO, "circular filter chain detected\n");

            return 0;

        case AVLINK_UNINIT:

            link->init_state = AVLINK_STARTINIT;



            if ((ret = avfilter_config_links(link->src)) < 0)

                return ret;



            if (!(config_link = link->srcpad->config_props)) {

                if (link->src->nb_inputs != 1) {

                    av_log(link->src, AV_LOG_ERROR, "Source filters and filters "

                                                    "with more than one input "

                                                    "must set config_props() "

                                                    "callbacks on all outputs\n");

                    return AVERROR(EINVAL);

                }

            } else if ((ret = config_link(link)) < 0) {

                av_log(link->src, AV_LOG_ERROR,

                       "Failed to configure output pad on %s\n",

                       link->src->name);

                return ret;

            }



            switch (link->type) {

            case AVMEDIA_TYPE_VIDEO:

                if (!link->time_base.num && !link->time_base.den)

                    link->time_base = inlink ? inlink->time_base : AV_TIME_BASE_Q;



                if (!link->sample_aspect_ratio.num && !link->sample_aspect_ratio.den)

                    link->sample_aspect_ratio = inlink ?

                        inlink->sample_aspect_ratio : (AVRational){1,1};



                if (inlink && !link->frame_rate.num && !link->frame_rate.den)

                    link->frame_rate = inlink->frame_rate;



                if (inlink) {

                    if (!link->w)

                        link->w = inlink->w;

                    if (!link->h)

                        link->h = inlink->h;

                } else if (!link->w || !link->h) {

                    av_log(link->src, AV_LOG_ERROR,

                           "Video source filters must set their output link's "

                           "width and height\n");

                    return AVERROR(EINVAL);

                }

                break;



            case AVMEDIA_TYPE_AUDIO:

                if (inlink) {

                    if (!link->sample_rate)

                        link->sample_rate = inlink->sample_rate;

                    if (!link->time_base.num && !link->time_base.den)

                        link->time_base = inlink->time_base;

                    if (!link->channel_layout)

                        link->channel_layout = inlink->channel_layout;

                } else if (!link->sample_rate) {

                    av_log(link->src, AV_LOG_ERROR,

                           "Audio source filters must set their output link's "

                           "sample_rate\n");

                    return AVERROR(EINVAL);

                }



                if (!link->time_base.num && !link->time_base.den)

                    link->time_base = (AVRational) {1, link->sample_rate};

            }



            if ((config_link = link->dstpad->config_props))

                if ((ret = config_link(link)) < 0) {

                    av_log(link->src, AV_LOG_ERROR,

                           "Failed to configure input pad on %s\n",

                           link->dst->name);

                    return ret;

                }



            link->init_state = AVLINK_INIT;

        }

    }



    return 0;

}

int avfilter_link(AVFilterContext *src, unsigned srcpad,

                  AVFilterContext *dst, unsigned dstpad)

{

    AVFilterLink *link;



    if (src->nb_outputs <= srcpad || dst->nb_inputs <= dstpad ||

        src->outputs[srcpad]      || dst->inputs[dstpad])

        return -1;



    if (src->output_pads[srcpad].type != dst->input_pads[dstpad].type) {

        av_log(src, AV_LOG_ERROR,

               "Media type mismatch between the '%s' filter output pad %d and the '%s' filter input pad %d\n",

               src->name, srcpad, dst->name, dstpad);

        return AVERROR(EINVAL);

    }



    src->outputs[srcpad] =

    dst-> inputs[dstpad] = link = av_mallocz(sizeof(AVFilterLink));



    link->src     = src;

    link->dst     = dst;

    link->srcpad  = &src->output_pads[srcpad];

    link->dstpad  = &dst->input_pads[dstpad];

    link->type    = src->output_pads[srcpad].type;

    assert(AV_PIX_FMT_NONE == -1 && AV_SAMPLE_FMT_NONE == -1);

    link->format  = -1;



    return 0;

}

int ff_h264_decode_picture_parameter_set(GetBitContext *gb, AVCodecContext *avctx,

