static void render_fragments(Vp3DecodeContext *s,

                             int first_fragment,

                             int fragment_width,

                             int fragment_height,

                             int plane /* 0 = Y, 1 = U, 2 = V */) 

{

    int x, y;

    int m, n;

    int i = first_fragment;

    int j;

    int16_t *dequantizer;

    DCTELEM dequant_block[64];

    unsigned char *output_plane;

    unsigned char *last_plane;

    unsigned char *golden_plane;

    int stride;



    debug_vp3("  vp3: rendering final fragments for %s\n",

        (plane == 0) ? "Y plane" : (plane == 1) ? "U plane" : "V plane");



    /* set up plane-specific parameters */

    if (plane == 0) {

        dequantizer = s->intra_y_dequant;

        output_plane = s->current_frame.data[0];

        last_plane = s->current_frame.data[0];

        golden_plane = s->current_frame.data[0];

        stride = -s->current_frame.linesize[0];

    } else if (plane == 1) {

        dequantizer = s->intra_c_dequant;

        output_plane = s->current_frame.data[1];

        last_plane = s->current_frame.data[1];

        golden_plane = s->current_frame.data[1];

        stride = -s->current_frame.linesize[1];

    } else {

        dequantizer = s->intra_c_dequant;

        output_plane = s->current_frame.data[2];

        last_plane = s->current_frame.data[2];

        golden_plane = s->current_frame.data[2];

        stride = -s->current_frame.linesize[2];

    }



    /* for each fragment row... */

    for (y = 0; y < fragment_height; y++) {



        /* for each fragment in a row... */

        for (x = 0; x < fragment_width; x++, i++) {



            /* transform if this block was coded */

            if (s->all_fragments[i].coding_method == MODE_INTRA) {

                /* dequantize the DCT coefficients */

                for (j = 0; j < 64; j++)

                    dequant_block[dequant_index[j]] =

                        s->all_fragments[i].coeffs[j] *

                        dequantizer[j];

                dequant_block[0] += 1024;



                debug_idct("fragment %d:\n", i);

                debug_idct("dequantized block:\n");

                for (m = 0; m < 8; m++) {

                    for (n = 0; n < 8; n++) {

                        debug_idct(" %5d", dequant_block[m * 8 + n]);

                    }

                    debug_idct("\n");

                }

                debug_idct("\n");



                /* invert DCT and place in final output */

                s->dsp.idct_put(

                    output_plane + s->all_fragments[i].first_pixel,

                    stride, dequant_block);



/*

                debug_idct("idct block:\n");

                for (m = 0; m < 8; m++) {

                    for (n = 0; n < 8; n++) {

                        debug_idct(" %3d", pixels[m * 8 + n]);

                    }

                    debug_idct("\n");

                }

                debug_idct("\n");

*/

            } else if (s->all_fragments[i].coding_method == MODE_COPY) {



                /* copy directly from the previous frame */

                for (m = 0; m < 8; m++)

                    memcpy(

                        output_plane + s->all_fragments[i].first_pixel + stride * m,

                        last_plane + s->all_fragments[i].first_pixel + stride * m,

                        8);



            } else {



                /* carry out the motion compensation */



            }

        }

    }



    emms_c();



}

static void draw_digit(int digit, uint8_t *dst, unsigned dst_linesize,

                       unsigned segment_width)

{

#define TOP_HBAR        1

#define MID_HBAR        2

#define BOT_HBAR        4

#define LEFT_TOP_VBAR   8

#define LEFT_BOT_VBAR  16

#define RIGHT_TOP_VBAR 32

#define RIGHT_BOT_VBAR 64

    struct {

        int x, y, w, h;

    } segments[] = {

        { 1,  0, 5, 1 }, /* TOP_HBAR */

        { 1,  6, 5, 1 }, /* MID_HBAR */

        { 1, 12, 5, 1 }, /* BOT_HBAR */

        { 0,  1, 1, 5 }, /* LEFT_TOP_VBAR */

        { 0,  7, 1, 5 }, /* LEFT_BOT_VBAR */

        { 6,  1, 1, 5 }, /* RIGHT_TOP_VBAR */

        { 6,  7, 1, 5 }  /* RIGHT_BOT_VBAR */

    };

    static const unsigned char masks[10] = {

        /* 0 */ TOP_HBAR         |BOT_HBAR|LEFT_TOP_VBAR|LEFT_BOT_VBAR|RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

        /* 1 */                                                        RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

        /* 2 */ TOP_HBAR|MID_HBAR|BOT_HBAR|LEFT_BOT_VBAR                             |RIGHT_TOP_VBAR,

        /* 3 */ TOP_HBAR|MID_HBAR|BOT_HBAR                            |RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

        /* 4 */          MID_HBAR         |LEFT_TOP_VBAR              |RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

        /* 5 */ TOP_HBAR|BOT_HBAR|MID_HBAR|LEFT_TOP_VBAR                             |RIGHT_BOT_VBAR,

        /* 6 */ TOP_HBAR|BOT_HBAR|MID_HBAR|LEFT_TOP_VBAR|LEFT_BOT_VBAR               |RIGHT_BOT_VBAR,

        /* 7 */ TOP_HBAR                                              |RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

        /* 8 */ TOP_HBAR|BOT_HBAR|MID_HBAR|LEFT_TOP_VBAR|LEFT_BOT_VBAR|RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

        /* 9 */ TOP_HBAR|BOT_HBAR|MID_HBAR|LEFT_TOP_VBAR              |RIGHT_TOP_VBAR|RIGHT_BOT_VBAR,

    };

    unsigned mask = masks[digit];

    int i;



    draw_rectangle(0, dst, dst_linesize, segment_width, 0, 0, 8, 13);

    for (i = 0; i < FF_ARRAY_ELEMS(segments); i++)

        if (mask & (1<<i))

            draw_rectangle(255, dst, dst_linesize, segment_width,

                           segments[i].x, segments[i].y, segments[i].w, segments[i].h);

}

static void render_fragments(Vp3DecodeContext *s,

                             int first_fragment,

                             int width,

                             int height,

                             int plane /* 0 = Y, 1 = U, 2 = V */) 

{

    int x, y;

    int m, n;

    int i = first_fragment;

    int j;

    int16_t *dequantizer;

    DCTELEM dequant_block[64];

    unsigned char *output_plane;

    unsigned char *last_plane;

    unsigned char *golden_plane;

    int stride;

    int motion_x, motion_y;

    int motion_x_limit, motion_y_limit;

    int motion_halfpel_index;

    unsigned int motion_source;



    debug_vp3("  vp3: rendering final fragments for %s\n",

        (plane == 0) ? "Y plane" : (plane == 1) ? "U plane" : "V plane");



    /* set up plane-specific parameters */

    if (plane == 0) {

        dequantizer = s->intra_y_dequant;

        output_plane = s->current_frame.data[0];

        last_plane = s->last_frame.data[0];

        golden_plane = s->golden_frame.data[0];

        stride = -s->current_frame.linesize[0];

    } else if (plane == 1) {

        dequantizer = s->intra_c_dequant;

        output_plane = s->current_frame.data[1];

        last_plane = s->last_frame.data[1];

        golden_plane = s->golden_frame.data[1];

        stride = -s->current_frame.linesize[1];

    } else {

        dequantizer = s->intra_c_dequant;

        output_plane = s->current_frame.data[2];

        last_plane = s->last_frame.data[2];

        golden_plane = s->golden_frame.data[2];

        stride = -s->current_frame.linesize[2];

    }



    motion_x_limit = width - 8;

    motion_y_limit = height - 8;



    /* for each fragment row... */

    for (y = 0; y < height; y += 8) {



        /* for each fragment in a row... */

        for (x = 0; x < width; x += 8, i++) {



            /* transform if this block was coded */

            if (s->all_fragments[i].coding_method != MODE_COPY) {



                /* sort out the motion vector */

                motion_x = s->all_fragments[i].motion_x;

                motion_y = s->all_fragments[i].motion_y;

                motion_halfpel_index = s->all_fragments[i].motion_halfpel_index;

/*



                if (motion_x < 0)

                    motion_x = 0;

                if (motion_y < 0)

                    motion_y = 0;

                if (motion_x > motion_x_limit)

                    motion_x = motion_x_limit;

                if (motion_y > motion_y_limit)

                    motion_y = motion_y_limit;

*/

                motion_source = s->all_fragments[i].first_pixel;

                motion_source += motion_x;

                motion_source += (motion_y * stride);



                /* first, take care of copying a block from either the

                 * previous or the golden frame */

                if ((s->all_fragments[i].coding_method == MODE_USING_GOLDEN) ||

                    (s->all_fragments[i].coding_method == MODE_GOLDEN_MV)) {



                    s->dsp.put_pixels_tab[1][motion_halfpel_index](

                        output_plane + s->all_fragments[i].first_pixel,

                        golden_plane + motion_source,

                        stride, 8);



                } else 

                if (s->all_fragments[i].coding_method != MODE_INTRA) {



                    s->dsp.put_pixels_tab[1][motion_halfpel_index](

                        output_plane + s->all_fragments[i].first_pixel,

                        last_plane + motion_source,

                        stride, 8);

                }



                /* dequantize the DCT coefficients */

                debug_idct("fragment %d, coding mode %d, DC = %d, dequant = %d:\n", 

                    i, s->all_fragments[i].coding_method, 

                    s->all_fragments[i].coeffs[0], dequantizer[0]);

                for (j = 0; j < 64; j++)

                    dequant_block[dequant_index[j]] =

                        s->all_fragments[i].coeffs[j] *

                        dequantizer[j];



                debug_idct("dequantized block:\n");

                for (m = 0; m < 8; m++) {

                    for (n = 0; n < 8; n++) {

                        debug_idct(" %5d", dequant_block[m * 8 + n]);

                    }

                    debug_idct("\n");

                }

                debug_idct("\n");



                /* invert DCT and place (or add) in final output */



                if (s->all_fragments[i].coding_method == MODE_INTRA) {

                    dequant_block[0] += 1024;

                    s->dsp.idct_put(

                        output_plane + s->all_fragments[i].first_pixel,

                        stride, dequant_block);

                } else {

                    s->dsp.idct_add(

                        output_plane + s->all_fragments[i].first_pixel,

                        stride, dequant_block);

                }



                debug_idct("block after idct_%s():\n",

                    (s->all_fragments[i].coding_method == MODE_INTRA)?

                    "put" : "add");

                for (m = 0; m < 8; m++) {

                    for (n = 0; n < 8; n++) {

                        debug_idct(" %3d", *(output_plane + 

                            s->all_fragments[i].first_pixel + (m * stride + n)));

                    }

                    debug_idct("\n");

                }

                debug_idct("\n");



            } else {



                /* copy directly from the previous frame */

                s->dsp.put_pixels_tab[1][0](

                    output_plane + s->all_fragments[i].first_pixel,

                    last_plane + s->all_fragments[i].first_pixel,

                    stride, 8);



            }

        }

    }



    emms_c();



}

