}

GuestFileWrite *qmp_guest_file_write(int64_t handle, const char *buf_b64,

                                     bool has_count, int64_t count,

                                     Error **errp)

{

    GuestFileWrite *write_data = NULL;

    guchar *buf;

    gsize buf_len;

    int write_count;

    GuestFileHandle *gfh = guest_file_handle_find(handle, errp);

    FILE *fh;



    if (!gfh) {

        return NULL;

    }



    fh = gfh->fh;

    buf = g_base64_decode(buf_b64, &buf_len);



    if (!has_count) {

        count = buf_len;

    } else if (count < 0 || count > buf_len) {

        error_setg(errp, "value '%" PRId64 "' is invalid for argument count",

                   count);

        g_free(buf);

        return NULL;

    }



    write_count = fwrite(buf, 1, count, fh);

    if (ferror(fh)) {

        error_setg_errno(errp, errno, "failed to write to file");

        slog("guest-file-write failed, handle: %" PRId64, handle);

    } else {

        write_data = g_malloc0(sizeof(GuestFileWrite));

        write_data->count = write_count;

        write_data->eof = feof(fh);

    }

    g_free(buf);

    clearerr(fh);



    return write_data;

}

void qmp_guest_file_close(int64_t handle, Error **err)

{

    GuestFileHandle *gfh = guest_file_handle_find(handle, err);

    int ret;



    slog("guest-file-close called, handle: %ld", handle);

    if (!gfh) {

        return;

    }



    ret = fclose(gfh->fh);

    if (ret == -1) {

        error_set(err, QERR_QGA_COMMAND_FAILED, "fclose() failed");

        return;

    }



    QTAILQ_REMOVE(&guest_file_state.filehandles, gfh, next);

    g_free(gfh);

}

struct GuestFileSeek *qmp_guest_file_seek(int64_t handle, int64_t offset,

                                          int64_t whence, Error **errp)

{

    GuestFileHandle *gfh = guest_file_handle_find(handle, errp);

    GuestFileSeek *seek_data = NULL;

    FILE *fh;

    int ret;



    if (!gfh) {

        return NULL;

    }



    fh = gfh->fh;

    ret = fseek(fh, offset, whence);

    if (ret == -1) {

        error_setg_errno(errp, errno, "failed to seek file");

        if (errno == ESPIPE) {

            /* file is non-seekable, stdio shouldn't be buffering anyways */

            gfh->state = RW_STATE_NEW;

        }

    } else {

        seek_data = g_new0(GuestFileSeek, 1);

        seek_data->position = ftell(fh);

        seek_data->eof = feof(fh);

        gfh->state = RW_STATE_NEW;

    }

    clearerr(fh);



    return seek_data;

}

GuestFileWrite *qmp_guest_file_write(int64_t handle, const char *buf_b64,

                                     bool has_count, int64_t count,

                                     Error **errp)

{

    GuestFileWrite *write_data = NULL;

    guchar *buf;

    gsize buf_len;

    bool is_ok;

    DWORD write_count;

    GuestFileHandle *gfh = guest_file_handle_find(handle, errp);

    HANDLE fh;



    if (!gfh) {

        return NULL;

    }

    fh = gfh->fh;

    buf = g_base64_decode(buf_b64, &buf_len);



    if (!has_count) {

        count = buf_len;

    } else if (count < 0 || count > buf_len) {

        error_setg(errp, "value '%" PRId64

                   "' is invalid for argument count", count);

        goto done;

    }



    is_ok = WriteFile(fh, buf, count, &write_count, NULL);

    if (!is_ok) {

        error_setg_win32(errp, GetLastError(), "failed to write to file");

        slog("guest-file-write-failed, handle: %" PRId64, handle);

    } else {

        write_data = g_new0(GuestFileWrite, 1);

        write_data->count = (size_t) write_count;

    }



done:

    g_free(buf);

    return write_data;

}

void ff_h264_direct_ref_list_init(H264Context * const h){

    MpegEncContext * const s = &h->s;

    Picture * const ref1 = &h->ref_list[1][0];

    Picture * const cur = s->current_picture_ptr;

    int list, j, field;

    int sidx= (s->picture_structure&1)^1;

    int ref1sidx = (ref1->f.reference&1)^1;



    for(list=0; list<2; list++){

        cur->ref_count[sidx][list] = h->ref_count[list];

        for(j=0; j<h->ref_count[list]; j++)

            cur->ref_poc[sidx][list][j] = 4 * h->ref_list[list][j].frame_num + (h->ref_list[list][j].f.reference & 3);

    }



    if(s->picture_structure == PICT_FRAME){

        memcpy(cur->ref_count[1], cur->ref_count[0], sizeof(cur->ref_count[0]));

        memcpy(cur->ref_poc  [1], cur->ref_poc  [0], sizeof(cur->ref_poc  [0]));

    }



    cur->mbaff= FRAME_MBAFF;



    h->col_fieldoff= 0;

    if(s->picture_structure == PICT_FRAME){

        int cur_poc = s->current_picture_ptr->poc;

        int *col_poc = h->ref_list[1]->field_poc;

        h->col_parity= (FFABS(col_poc[0] - cur_poc) >= FFABS(col_poc[1] - cur_poc));

        ref1sidx=sidx= h->col_parity;

    } else if (!(s->picture_structure & h->ref_list[1][0].f.reference) && !h->ref_list[1][0].mbaff) { // FL -> FL & differ parity

        h->col_fieldoff = 2 * h->ref_list[1][0].f.reference - 3;

    }



    if (cur->f.pict_type != AV_PICTURE_TYPE_B || h->direct_spatial_mv_pred)

        return;



    for(list=0; list<2; list++){

        fill_colmap(h, h->map_col_to_list0, list, sidx, ref1sidx, 0);

        if(FRAME_MBAFF)

        for(field=0; field<2; field++)

            fill_colmap(h, h->map_col_to_list0_field[field], list, field, field, 1);

    }

}

static int fill_default_ref_list(H264Context *h){

    MpegEncContext * const s = &h->s;

    int i;

    int smallest_poc_greater_than_current = -1;

    Picture sorted_short_ref[32];



    if(h->slice_type==B_TYPE){

        int out_i;

        int limit= -1;



        /* sort frame according to poc in B slice */

        for(out_i=0; out_i<h->short_ref_count; out_i++){

            int best_i=-1;

            int best_poc=INT_MAX;



            for(i=0; i<h->short_ref_count; i++){

                const int poc= h->short_ref[i]->poc;

                if(poc > limit && poc < best_poc){

                    best_poc= poc;

                    best_i= i;

                }

            }



            assert(best_i != -1);



            limit= best_poc;

            sorted_short_ref[out_i]= *h->short_ref[best_i];

            tprintf("sorted poc: %d->%d poc:%d fn:%d\n", best_i, out_i, sorted_short_ref[out_i].poc, sorted_short_ref[out_i].frame_num);

            if (-1 == smallest_poc_greater_than_current) {

                if (h->short_ref[best_i]->poc >= s->current_picture_ptr->poc) {

                    smallest_poc_greater_than_current = out_i;

                }

            }

        }

    }



    if(s->picture_structure == PICT_FRAME){

        if(h->slice_type==B_TYPE){

            int list;

            tprintf("current poc: %d, smallest_poc_greater_than_current: %d\n", s->current_picture_ptr->poc, smallest_poc_greater_than_current);



            // find the largest poc

            for(list=0; list<2; list++){

                int index = 0;

                int j= -99;

                int step= list ? -1 : 1;



                for(i=0; i<h->short_ref_count && index < h->ref_count[list]; i++, j+=step) {

                    while(j<0 || j>= h->short_ref_count){

                        if(j != -99 && step == (list ? -1 : 1))

                            return -1;

                        step = -step;

                        j= smallest_poc_greater_than_current + (step>>1);

                    }

                    if(sorted_short_ref[j].reference != 3) continue;

                    h->default_ref_list[list][index  ]= sorted_short_ref[j];

                    h->default_ref_list[list][index++].pic_id= sorted_short_ref[j].frame_num;

                }



                for(i = 0; i < 16 && index < h->ref_count[ list ]; i++){

                    if(h->long_ref[i] == NULL) continue;

                    if(h->long_ref[i]->reference != 3) continue;



                    h->default_ref_list[ list ][index  ]= *h->long_ref[i];

                    h->default_ref_list[ list ][index++].pic_id= i;;

                }



                if(list && (smallest_poc_greater_than_current<=0 || smallest_poc_greater_than_current>=h->short_ref_count) && (1 < index)){

                    // swap the two first elements of L1 when

                    // L0 and L1 are identical

                    Picture temp= h->default_ref_list[1][0];

                    h->default_ref_list[1][0] = h->default_ref_list[1][1];

                    h->default_ref_list[1][1] = temp;

                }



                if(index < h->ref_count[ list ])

                    memset(&h->default_ref_list[list][index], 0, sizeof(Picture)*(h->ref_count[ list ] - index));

            }

        }else{

            int index=0;

            for(i=0; i<h->short_ref_count; i++){

                if(h->short_ref[i]->reference != 3) continue; //FIXME refernce field shit

                h->default_ref_list[0][index  ]= *h->short_ref[i];

                h->default_ref_list[0][index++].pic_id= h->short_ref[i]->frame_num;

            }

            for(i = 0; i < 16; i++){

                if(h->long_ref[i] == NULL) continue;

                if(h->long_ref[i]->reference != 3) continue;

                h->default_ref_list[0][index  ]= *h->long_ref[i];

                h->default_ref_list[0][index++].pic_id= i;;

            }

            if(index < h->ref_count[0])

                memset(&h->default_ref_list[0][index], 0, sizeof(Picture)*(h->ref_count[0] - index));

        }

    }else{ //FIELD

        if(h->slice_type==B_TYPE){

        }else{

            //FIXME second field balh

        }

    }

#ifdef TRACE

    for (i=0; i<h->ref_count[0]; i++) {

        tprintf("List0: %s fn:%d 0x%p\n", (h->default_ref_list[0][i].long_ref ? "LT" : "ST"), h->default_ref_list[0][i].pic_id, h->default_ref_list[0][i].data[0]);

    }

    if(h->slice_type==B_TYPE){

        for (i=0; i<h->ref_count[1]; i++) {

            tprintf("List1: %s fn:%d 0x%p\n", (h->default_ref_list[1][i].long_ref ? "LT" : "ST"), h->default_ref_list[1][i].pic_id, h->default_ref_list[0][i].data[0]);

        }

    }

#endif

    return 0;

}

static inline void direct_ref_list_init(H264Context * const h){

    MpegEncContext * const s = &h->s;

    Picture * const ref1 = &h->ref_list[1][0];

    Picture * const cur = s->current_picture_ptr;

    int list, i, j;

    int sidx= s->picture_structure&1;

    int ref1sidx= ref1->reference&1;

    for(list=0; list<2; list++){

        cur->ref_count[sidx][list] = h->ref_count[list];

        for(j=0; j<h->ref_count[list]; j++)

            cur->ref_poc[sidx][list][j] = h->ref_list[list][j].poc;

    }

    if(s->picture_structure == PICT_FRAME){

        memcpy(cur->ref_count[0], cur->ref_count[1], sizeof(cur->ref_count[0]));

        memcpy(cur->ref_poc  [0], cur->ref_poc  [1], sizeof(cur->ref_poc  [0]));

    }

    if(cur->pict_type != FF_B_TYPE || h->direct_spatial_mv_pred)

        return;

    for(list=0; list<2; list++){

        for(i=0; i<ref1->ref_count[ref1sidx][list]; i++){

            const int poc = ref1->ref_poc[ref1sidx][list][i];

            h->map_col_to_list0[list][i] = 0; /* bogus; fills in for missing frames */

            for(j=0; j<h->ref_count[list]; j++)

                if(h->ref_list[list][j].poc == poc){

                    h->map_col_to_list0[list][i] = j;

                    break;

                }

        }

    }

    if(FRAME_MBAFF){

        for(list=0; list<2; list++){

            for(i=0; i<ref1->ref_count[ref1sidx][list]; i++){

                j = h->map_col_to_list0[list][i];

                h->map_col_to_list0_field[list][2*i] = 2*j;

                h->map_col_to_list0_field[list][2*i+1] = 2*j+1;

            }

        }

    }

}

static void encode_plane(FFV1Context *s, uint8_t *src, int w, int h,

                         int stride, int plane_index)

{

    int x, y, i;

    const int ring_size = s->avctx->context_model ? 3 : 2;

    int16_t *sample[3];

    s->run_index = 0;



    memset(s->sample_buffer, 0, ring_size * (w + 6) * sizeof(*s->sample_buffer));



    for (y = 0; y < h; y++) {

        for (i = 0; i < ring_size; i++)

            sample[i] = s->sample_buffer + (w + 6) * ((h + i - y) % ring_size) + 3;



        sample[0][-1]= sample[1][0  ];

        sample[1][ w]= sample[1][w-1];

// { START_TIMER

        if (s->bits_per_raw_sample <= 8) {

            for (x = 0; x < w; x++)

                sample[0][x] = src[x + stride * y];

            encode_line(s, w, sample, plane_index, 8);

        } else {

            if (s->packed_at_lsb) {

                for (x = 0; x < w; x++) {

                    sample[0][x] = ((uint16_t*)(src + stride*y))[x];

                }

            } else {

                for (x = 0; x < w; x++) {

                    sample[0][x] = ((uint16_t*)(src + stride*y))[x] >> (16 - s->bits_per_raw_sample);

                }

            }

            encode_line(s, w, sample, plane_index, s->bits_per_raw_sample);

        }

// STOP_TIMER("encode line") }

    }

}

static void compute_frame_duration(int *pnum, int *pden, AVStream *st, 

                                   AVCodecParserContext *pc, AVPacket *pkt)

{

    int frame_size;



    *pnum = 0;

    *pden = 0;

    switch(st->codec.codec_type) {

    case CODEC_TYPE_VIDEO:

        if(st->time_base.num*1000 > st->time_base.den){

            *pnum = st->time_base.num;

            *pden = st->time_base.den;

        }else if(st->codec.time_base.num*1000 > st->codec.time_base.den){

            *pnum = st->codec.time_base.num;

            *pden = st->codec.time_base.den;

            if (pc && pc->repeat_pict) {

                *pden *= 2;

                *pnum = (*pnum) * (2 + pc->repeat_pict);

            }

        }

        break;

    case CODEC_TYPE_AUDIO:

        frame_size = get_audio_frame_size(&st->codec, pkt->size);

        if (frame_size < 0)

            break;

        *pnum = frame_size;

        *pden = st->codec.sample_rate;

        break;

    default:

        break;

    }

}

void add_codec(FFStream *stream, AVCodecContext *av)

{

    AVStream *st;



    /* compute default parameters */

    switch(av->codec_type) {

    case CODEC_TYPE_AUDIO:

        if (av->bit_rate == 0)

            av->bit_rate = 64000;

        if (av->sample_rate == 0)

            av->sample_rate = 22050;

        if (av->channels == 0)

            av->channels = 1;

        break;

    case CODEC_TYPE_VIDEO:

        if (av->bit_rate == 0)

            av->bit_rate = 64000;

        if (av->frame_rate == 0)

            av->frame_rate = 5 * FRAME_RATE_BASE;

        if (av->width == 0 || av->height == 0) {

            av->width = 160;

            av->height = 128;

        }

        /* Bitrate tolerance is less for streaming */

        if (av->bit_rate_tolerance == 0)

            av->bit_rate_tolerance = av->bit_rate / 4;

        if (av->qmin == 0)

            av->qmin = 3;

        if (av->qmax == 0)

            av->qmax = 31;

        if (av->max_qdiff == 0)

            av->max_qdiff = 3;

        av->qcompress = 0.5;

        av->qblur = 0.5;



        break;

    default:

        abort();

    }



    st = av_mallocz(sizeof(AVStream));

    if (!st)

        return;

    stream->streams[stream->nb_streams++] = st;

    memcpy(&st->codec, av, sizeof(AVCodecContext));

}

static int gsm_parse(AVCodecParserContext *s1, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    GSMParseContext *s = s1->priv_data;

    ParseContext *pc = &s->pc;

    int next;



    if (!s->block_size) {

        switch (avctx->codec_id) {

        case AV_CODEC_ID_GSM:

            s->block_size = GSM_BLOCK_SIZE;

            s->duration   = GSM_FRAME_SIZE;

            break;

        case AV_CODEC_ID_GSM_MS:

            s->block_size = GSM_MS_BLOCK_SIZE;

            s->duration   = GSM_FRAME_SIZE * 2;

            break;

        default:

            return AVERROR(EINVAL);

        }

    }



    if (!s->remaining)

        s->remaining = s->block_size;

    if (s->remaining <= buf_size) {

        next = s->remaining;

        s->remaining = 0;

    } else {

        next = END_NOT_FOUND;

        s->remaining -= buf_size;

    }



    if (ff_combine_frame(pc, next, &buf, &buf_size) < 0 || !buf_size) {

        *poutbuf      = NULL;

        *poutbuf_size = 0;

        return buf_size;

    }



    s1->duration = s->duration;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

void ff_compute_frame_duration(int *pnum, int *pden, AVStream *st,

                               AVCodecParserContext *pc, AVPacket *pkt)

{

    int frame_size;



    *pnum = 0;

    *pden = 0;

    switch(st->codec->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        if (st->avg_frame_rate.num) {

            *pnum = st->avg_frame_rate.den;

            *pden = st->avg_frame_rate.num;

        } else if(st->time_base.num*1000LL > st->time_base.den) {

            *pnum = st->time_base.num;

            *pden = st->time_base.den;

        }else if(st->codec->time_base.num*1000LL > st->codec->time_base.den){

            *pnum = st->codec->time_base.num;

            *pden = st->codec->time_base.den;

            if (pc && pc->repeat_pict) {

                *pnum = (*pnum) * (1 + pc->repeat_pict);

            }

            //If this codec can be interlaced or progressive then we need a parser to compute duration of a packet

            //Thus if we have no parser in such case leave duration undefined.

            if(st->codec->ticks_per_frame>1 && !pc){

                *pnum = *pden = 0;

            }

        }

        break;

    case AVMEDIA_TYPE_AUDIO:

        frame_size = ff_get_audio_frame_size(st->codec, pkt->size, 0);

        if (frame_size <= 0 || st->codec->sample_rate <= 0)

            break;

        *pnum = frame_size;

        *pden = st->codec->sample_rate;

        break;

    default:

        break;

    }

}

static int os_host_main_loop_wait(uint32_t timeout)

{

    GMainContext *context = g_main_context_default();

    int select_ret, g_poll_ret, ret, i;

    PollingEntry *pe;

    WaitObjects *w = &wait_objects;

    gint poll_timeout;

    static struct timeval tv0;



    /* XXX: need to suppress polling by better using win32 events */

    ret = 0;

    for (pe = first_polling_entry; pe != NULL; pe = pe->next) {

        ret |= pe->func(pe->opaque);

    }

    if (ret != 0) {

        return ret;

    }



    g_main_context_prepare(context, &max_priority);

    n_poll_fds = g_main_context_query(context, max_priority, &poll_timeout,

                                      poll_fds, ARRAY_SIZE(poll_fds));

    g_assert(n_poll_fds <= ARRAY_SIZE(poll_fds));



    for (i = 0; i < w->num; i++) {

        poll_fds[n_poll_fds + i].fd = (DWORD_PTR)w->events[i];

        poll_fds[n_poll_fds + i].events = G_IO_IN;

    }



    if (poll_timeout < 0 || timeout < poll_timeout) {

        poll_timeout = timeout;

    }



    qemu_mutex_unlock_iothread();

    g_poll_ret = g_poll(poll_fds, n_poll_fds + w->num, poll_timeout);

    qemu_mutex_lock_iothread();

    if (g_poll_ret > 0) {

        for (i = 0; i < w->num; i++) {

            w->revents[i] = poll_fds[n_poll_fds + i].revents;

        }

        for (i = 0; i < w->num; i++) {

            if (w->revents[i] && w->func[i]) {

                w->func[i](w->opaque[i]);

            }

        }

    }



    if (g_main_context_check(context, max_priority, poll_fds, n_poll_fds)) {

        g_main_context_dispatch(context);

    }



    /* Call select after g_poll to avoid a useless iteration and therefore

     * improve socket latency.

     */



    if (nfds >= 0) {

        select_ret = select(nfds + 1, &rfds, &wfds, &xfds, &tv0);

        if (select_ret != 0) {

            timeout = 0;

        }

    }



    return select_ret || g_poll_ret;

}

static int os_host_main_loop_wait(int timeout)

{

    int ret, i;

    PollingEntry *pe;

    WaitObjects *w = &wait_objects;

    static struct timeval tv0;



    /* XXX: need to suppress polling by better using win32 events */

    ret = 0;

    for (pe = first_polling_entry; pe != NULL; pe = pe->next) {

        ret |= pe->func(pe->opaque);

    }

    if (ret != 0) {

        return ret;

    }



    if (nfds >= 0) {

        ret = select(nfds + 1, &rfds, &wfds, &xfds, &tv0);

        if (ret != 0) {

            timeout = 0;

        }

    }



    for (i = 0; i < w->num; i++) {

        poll_fds[i].fd = (DWORD) w->events[i];

        poll_fds[i].events = G_IO_IN;

    }



    qemu_mutex_unlock_iothread();

    ret = g_poll(poll_fds, w->num, timeout);

    qemu_mutex_lock_iothread();

    if (ret > 0) {

        for (i = 0; i < w->num; i++) {

            w->revents[i] = poll_fds[i].revents;

        }

        for (i = 0; i < w->num; i++) {

            if (w->revents[i] && w->func[i]) {

                w->func[i](w->opaque[i]);

            }

        }

    }



    /* If an edge-triggered socket event occurred, select will return a

     * positive result on the next iteration.  We do not need to do anything

     * here.

     */



    return ret;

}

void os_host_main_loop_wait(int *timeout)

{

    int ret, ret2, i;

    PollingEntry *pe;



    /* XXX: need to suppress polling by better using win32 events */

    ret = 0;

    for(pe = first_polling_entry; pe != NULL; pe = pe->next) {

        ret |= pe->func(pe->opaque);

    }

    if (ret == 0) {

        int err;

        WaitObjects *w = &wait_objects;



        qemu_mutex_unlock_iothread();

        ret = WaitForMultipleObjects(w->num, w->events, FALSE, *timeout);

        qemu_mutex_lock_iothread();

        if (WAIT_OBJECT_0 + 0 <= ret && ret <= WAIT_OBJECT_0 + w->num - 1) {

            if (w->func[ret - WAIT_OBJECT_0])

                w->func[ret - WAIT_OBJECT_0](w->opaque[ret - WAIT_OBJECT_0]);



            /* Check for additional signaled events */

            for(i = (ret - WAIT_OBJECT_0 + 1); i < w->num; i++) {



                /* Check if event is signaled */

                ret2 = WaitForSingleObject(w->events[i], 0);

                if(ret2 == WAIT_OBJECT_0) {

                    if (w->func[i])

                        w->func[i](w->opaque[i]);

                } else if (ret2 == WAIT_TIMEOUT) {

                } else {

                    err = GetLastError();

                    fprintf(stderr, "WaitForSingleObject error %d %d\n", i, err);

                }

            }

        } else if (ret == WAIT_TIMEOUT) {

        } else {

            err = GetLastError();

            fprintf(stderr, "WaitForMultipleObjects error %d %d\n", ret, err);

        }

    }



    *timeout = 0;

}

static int os_host_main_loop_wait(uint32_t timeout)

{

    int ret;



    glib_select_fill(&nfds, &rfds, &wfds, &xfds, &timeout);



    if (timeout > 0) {

        qemu_mutex_unlock_iothread();

    }



    /* We'll eventually drop fd_set completely.  But for now we still have

     * *_fill() and *_poll() functions that use rfds/wfds/xfds.

     */

    gpollfds_from_select();



    ret = g_poll((GPollFD *)gpollfds->data, gpollfds->len, timeout);



    gpollfds_to_select(ret);



    if (timeout > 0) {

        qemu_mutex_lock_iothread();

    }



    glib_select_poll(&rfds, &wfds, &xfds, (ret < 0));

    return ret;

}

