    c->ach    = 0;

    c->frames = 0;

    c->abytes = 0;



    c->vst->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    c->vst->codec->codec_id   = CODEC_ID_DVVIDEO;

    c->vst->codec->bit_rate   = 25000000;

    c->vst->start_time        = 0;



