    s->irq = timerirq;

    s->alarm = alarmirq;

    s->clk = timer_new_ms(rtc_clock, omap_rtc_tick, s);



    omap_rtc_reset(s);



    memory_region_init_io(&s->iomem, NULL, &omap_rtc_ops, s,

