int xbzrle_decode_buffer(uint8_t *src, int slen, uint8_t *dst, int dlen)

{

    int i = 0, d = 0;

    int ret;

    uint32_t count = 0;



    while (i < slen) {



        /* zrun */

        if ((slen - i) < 2) {

            return -1;

        }



        ret = uleb128_decode_small(src + i, &count);

        if (ret < 0 || (i && !count)) {

            return -1;

        }

        i += ret;

        d += count;



        /* overflow */

        if (d > dlen) {

            return -1;

        }



        /* nzrun */

        if ((slen - i) < 2) {

            return -1;

        }



        ret = uleb128_decode_small(src + i, &count);

        if (ret < 0 || !count) {

            return -1;

        }

        i += ret;



        /* overflow */

        if (d + count > dlen || i + count > slen) {

            return -1;

        }



        memcpy(dst + d, src + i, count);

        d += count;

        i += count;

    }



    return d;

}

static int rtp_asf_fix_header(uint8_t *buf, int len)

{

    uint8_t *p = buf, *end = buf + len;



    if (len < sizeof(ff_asf_guid) * 2 + 22 ||

        memcmp(p, ff_asf_header, sizeof(ff_asf_guid))) {

        return -1;

    }

    p += sizeof(ff_asf_guid) + 14;

    do {

        uint64_t chunksize = AV_RL64(p + sizeof(ff_asf_guid));

        if (memcmp(p, ff_asf_file_header, sizeof(ff_asf_guid))) {

            if (chunksize > end - p)

                return -1;

            p += chunksize;

            continue;

        }



        /* skip most of the file header, to min_pktsize */

        p += 6 * 8 + 3 * 4 + sizeof(ff_asf_guid) * 2;

        if (p + 8 <= end && AV_RL32(p) == AV_RL32(p + 4)) {

            /* and set that to zero */

            AV_WL32(p, 0);

            return 0;

        }

        break;

    } while (end - p >= sizeof(ff_asf_guid) + 8);



    return -1;

}

static int raw_pread(BlockDriverState *bs, int64_t offset,

                     uint8_t *buf, int count)

{

    BDRVRawState *s = bs->opaque;

    int size, ret, shift, sum;



    sum = 0;



    if (s->aligned_buf != NULL)  {



        if (offset & 0x1ff) {

            /* align offset on a 512 bytes boundary */



            shift = offset & 0x1ff;

            size = (shift + count + 0x1ff) & ~0x1ff;

            if (size > ALIGNED_BUFFER_SIZE)

                size = ALIGNED_BUFFER_SIZE;

            ret = raw_pread_aligned(bs, offset - shift, s->aligned_buf, size);

            if (ret < 0)

                return ret;



            size = 512 - shift;

            if (size > count)

                size = count;

            memcpy(buf, s->aligned_buf + shift, size);



            buf += size;

            offset += size;

            count -= size;

            sum += size;



            if (count == 0)

                return sum;

        }

        if (count & 0x1ff || (uintptr_t) buf & 0x1ff) {



            /* read on aligned buffer */



            while (count) {



                size = (count + 0x1ff) & ~0x1ff;

                if (size > ALIGNED_BUFFER_SIZE)

                    size = ALIGNED_BUFFER_SIZE;



                ret = raw_pread_aligned(bs, offset, s->aligned_buf, size);

                if (ret < 0)

                    return ret;



                size = ret;

                if (size > count)

                    size = count;



                memcpy(buf, s->aligned_buf, size);



                buf += size;

                offset += size;

                count -= size;

                sum += size;

            }



            return sum;

        }

    }



    return raw_pread_aligned(bs, offset, buf, count) + sum;

}

static int lag_decode_zero_run_line(LagarithContext *l, uint8_t *dst,

                                    const uint8_t *src, int width,

                                    int esc_count)

{

    int i = 0;

    int count;

    uint8_t zero_run = 0;

    const uint8_t *start = src;

    uint8_t mask1 = -(esc_count < 2);

    uint8_t mask2 = -(esc_count < 3);

    uint8_t *end = dst + (width - 2);



output_zeros:

    if (l->zeros_rem) {

        count = FFMIN(l->zeros_rem, width - i);

        memset(dst, 0, count);

        l->zeros_rem -= count;

        dst += count;

    }



    while (dst < end) {

        i = 0;

        while (!zero_run && dst + i < end) {

            i++;

            zero_run =

                !(src[i] | (src[i + 1] & mask1) | (src[i + 2] & mask2));

        }

        if (zero_run) {

            zero_run = 0;

            i += esc_count;

            memcpy(dst, src, i);

            dst += i;

            l->zeros_rem = lag_calc_zero_run(src[i]);



            src += i + 1;

            goto output_zeros;

        } else {

            memcpy(dst, src, i);

            src += i;

        }

    }

    return start - src;

}

static float get_band_cost_ZERO_mips(struct AACEncContext *s,

                                     PutBitContext *pb, const float *in,

                                     const float *scaled, int size, int scale_idx,

                                     int cb, const float lambda, const float uplim,

                                     int *bits)

{

    int i;

    float cost = 0;



    for (i = 0; i < size; i += 4) {

        cost += in[i  ] * in[i  ];

        cost += in[i+1] * in[i+1];

        cost += in[i+2] * in[i+2];

        cost += in[i+3] * in[i+3];

    }

    if (bits)

        *bits = 0;

    return cost * lambda;

}

static void celt_search_for_intensity(OpusPsyContext *s, CeltFrame *f)
{
    int i, best_band = CELT_MAX_BANDS - 1;
    float dist, best_dist = FLT_MAX;
    /* TODO: fix, make some heuristic up here using the lambda value */
    float end_band = 0;
    for (i = f->end_band; i >= end_band; i--) {
        f->intensity_stereo = i;
        bands_dist(s, f, &dist);
        if (best_dist > dist) {
            best_dist = dist;
            best_band = i;
        }
    }
    f->intensity_stereo = best_band;
    s->avg_is_band = (s->avg_is_band + f->intensity_stereo)/2.0f;
}

static void pre_calc_cosmod(DCAContext * s)

{

    int i, j, k;

    static int cosmod_inited = 0;



    if(cosmod_inited) return;

    for (j = 0, k = 0; k < 16; k++)

        for (i = 0; i < 16; i++)

            cos_mod[j++] = cos((2 * i + 1) * (2 * k + 1) * M_PI / 64);



    for (k = 0; k < 16; k++)

        for (i = 0; i < 16; i++)

            cos_mod[j++] = cos((i) * (2 * k + 1) * M_PI / 32);



    for (k = 0; k < 16; k++)

        cos_mod[j++] = 0.25 / (2 * cos((2 * k + 1) * M_PI / 128));



    for (k = 0; k < 16; k++)

        cos_mod[j++] = -0.25 / (2.0 * sin((2 * k + 1) * M_PI / 128));



    cosmod_inited = 1;

}

static void gd_update(DisplayChangeListener *dcl,

                      DisplayState *ds, int x, int y, int w, int h)

{

    GtkDisplayState *s = ds->opaque;

    int x1, x2, y1, y2;

    int mx, my;

    int fbw, fbh;

    int ww, wh;



    DPRINTF("update(x=%d, y=%d, w=%d, h=%d)\n", x, y, w, h);



    x1 = floor(x * s->scale_x);

    y1 = floor(y * s->scale_y);



    x2 = ceil(x * s->scale_x + w * s->scale_x);

    y2 = ceil(y * s->scale_y + h * s->scale_y);



    fbw = ds_get_width(s->ds) * s->scale_x;

    fbh = ds_get_height(s->ds) * s->scale_y;



    gdk_drawable_get_size(gtk_widget_get_window(s->drawing_area), &ww, &wh);



    mx = my = 0;

    if (ww > fbw) {

        mx = (ww - fbw) / 2;

    }

    if (wh > fbh) {

        my = (wh - fbh) / 2;

    }



    gtk_widget_queue_draw_area(s->drawing_area, mx + x1, my + y1, (x2 - x1), (y2 - y1));

}

static void gd_update_geometry_hints(VirtualConsole *vc)

{

    GtkDisplayState *s = vc->s;

    GdkWindowHints mask = 0;

    GdkGeometry geo = {};

    GtkWidget *geo_widget = NULL;

    GtkWindow *geo_window;



    if (vc->type == GD_VC_GFX) {

        if (!vc->gfx.ds) {

            return;

        }

        if (s->free_scale) {

            geo.min_width  = surface_width(vc->gfx.ds) * VC_SCALE_MIN;

            geo.min_height = surface_height(vc->gfx.ds) * VC_SCALE_MIN;

            mask |= GDK_HINT_MIN_SIZE;

        } else {

            geo.min_width  = surface_width(vc->gfx.ds) * vc->gfx.scale_x;

            geo.min_height = surface_height(vc->gfx.ds) * vc->gfx.scale_y;

            mask |= GDK_HINT_MIN_SIZE;

        }

        geo_widget = vc->gfx.drawing_area;

        gtk_widget_set_size_request(geo_widget, geo.min_width, geo.min_height);



#if defined(CONFIG_VTE)

    } else if (vc->type == GD_VC_VTE) {

        VteTerminal *term = VTE_TERMINAL(vc->vte.terminal);

        GtkBorder *ib;



        geo.width_inc  = vte_terminal_get_char_width(term);

        geo.height_inc = vte_terminal_get_char_height(term);

        mask |= GDK_HINT_RESIZE_INC;

        geo.base_width  = geo.width_inc;

        geo.base_height = geo.height_inc;

        mask |= GDK_HINT_BASE_SIZE;

        geo.min_width  = geo.width_inc * VC_TERM_X_MIN;

        geo.min_height = geo.height_inc * VC_TERM_Y_MIN;

        mask |= GDK_HINT_MIN_SIZE;

        gtk_widget_style_get(vc->vte.terminal, "inner-border", &ib, NULL);

        geo.base_width  += ib->left + ib->right;

        geo.base_height += ib->top + ib->bottom;

        geo.min_width   += ib->left + ib->right;

        geo.min_height  += ib->top + ib->bottom;

        geo_widget = vc->vte.terminal;

#endif

    }



    geo_window = GTK_WINDOW(vc->window ? vc->window : s->window);

    gtk_window_set_geometry_hints(geo_window, geo_widget, &geo, mask);

}

static gboolean gd_motion_event(GtkWidget *widget, GdkEventMotion *motion,

                                void *opaque)

{

    GtkDisplayState *s = opaque;

    int dx, dy;

    int x, y;



    x = motion->x / s->scale_x;

    y = motion->y / s->scale_y;



    if (kbd_mouse_is_absolute()) {

        dx = x * 0x7FFF / (ds_get_width(s->ds) - 1);

        dy = y * 0x7FFF / (ds_get_height(s->ds) - 1);

    } else if (s->last_x == -1 || s->last_y == -1) {

        dx = 0;

        dy = 0;

    } else {

        dx = x - s->last_x;

        dy = y - s->last_y;

    }



    s->last_x = x;

    s->last_y = y;



    if (kbd_mouse_is_absolute()) {

        kbd_mouse_event(dx, dy, 0, s->button_mask);

    }



    return TRUE;

}

