FF_ENABLE_DEPRECATION_WARNINGS

#endif



#if FF_API_CODER_TYPE

FF_DISABLE_DEPRECATION_WARNINGS

    if (avctx->coder_type == FF_CODER_TYPE_RAW)

        s->rle = 0;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    width  = avctx->width;

    height = avctx->height;

    bytes_per_channel = 1;

    pixmax = 0xFF;

    put_be = HAVE_BIGENDIAN;



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_GRAY8:

        dimension = SGI_SINGLE_CHAN;

        depth     = SGI_GRAYSCALE;

        break;

    case AV_PIX_FMT_RGB24:

        dimension = SGI_MULTI_CHAN;

        depth     = SGI_RGB;

        break;

    case AV_PIX_FMT_RGBA:

        dimension = SGI_MULTI_CHAN;

        depth     = SGI_RGBA;

        break;

    case AV_PIX_FMT_GRAY16LE:

        put_be = !HAVE_BIGENDIAN;

    case AV_PIX_FMT_GRAY16BE:

        bytes_per_channel = 2;

        pixmax = 0xFFFF;

        dimension = SGI_SINGLE_CHAN;

        depth     = SGI_GRAYSCALE;

        break;

    case AV_PIX_FMT_RGB48LE:

        put_be = !HAVE_BIGENDIAN;

    case AV_PIX_FMT_RGB48BE:

        bytes_per_channel = 2;

        pixmax = 0xFFFF;

        dimension = SGI_MULTI_CHAN;

        depth     = SGI_RGB;

        break;

    case AV_PIX_FMT_RGBA64LE:

        put_be = !HAVE_BIGENDIAN;

    case AV_PIX_FMT_RGBA64BE:

        bytes_per_channel = 2;

        pixmax = 0xFFFF;

        dimension = SGI_MULTI_CHAN;

        depth     = SGI_RGBA;

        break;

    default:

        return AVERROR_INVALIDDATA;

    }



    tablesize = depth * height * 4;

    length = SGI_HEADER_SIZE;

    if (!s->rle)

        length += depth * height * width;

    else // assume sgi_rle_encode() produces at most 2x size of input

        length += tablesize * 2 + depth * height * (2 * width + 1);



    if ((ret = ff_alloc_packet(pkt, bytes_per_channel * length)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet of size %d.\n", length);

        return ret;

    }



    bytestream2_init_writer(&pbc, pkt->data, pkt->size);



    /* Encode header. */

    bytestream2_put_be16(&pbc, SGI_MAGIC);

    bytestream2_put_byte(&pbc, s->rle); /* RLE 1 - VERBATIM 0 */

    bytestream2_put_byte(&pbc, bytes_per_channel);

    bytestream2_put_be16(&pbc, dimension);

    bytestream2_put_be16(&pbc, width);

    bytestream2_put_be16(&pbc, height);

    bytestream2_put_be16(&pbc, depth);



    bytestream2_put_be32(&pbc, 0L); /* pixmin */

    bytestream2_put_be32(&pbc, pixmax);

    bytestream2_put_be32(&pbc, 0L); /* dummy */



    /* name */

    bytestream2_skip_p(&pbc, 80);



    /* colormap */

    bytestream2_put_be32(&pbc, 0L);



    /* The rest of the 512 byte header is unused. */

    bytestream2_skip_p(&pbc, 404);



    if (s->rle) {

        PutByteContext taboff_pcb, tablen_pcb;



        /* Skip RLE offset table. */

        bytestream2_init_writer(&taboff_pcb, pbc.buffer, tablesize);

        bytestream2_skip_p(&pbc, tablesize);



        /* Skip RLE length table. */

        bytestream2_init_writer(&tablen_pcb, pbc.buffer, tablesize);

        bytestream2_skip_p(&pbc, tablesize);



        /* Make an intermediate consecutive buffer. */

        if (!(encode_buf = av_malloc(width * bytes_per_channel)))

            return AVERROR(ENOMEM);



        for (z = 0; z < depth; z++) {

            in_buf = p->data[0] + p->linesize[0] * (height - 1) + z * bytes_per_channel;



            for (y = 0; y < height; y++) {

                bytestream2_put_be32(&taboff_pcb, bytestream2_tell_p(&pbc));



                for (x = 0; x < width * bytes_per_channel; x += bytes_per_channel)

                    encode_buf[x] = in_buf[depth * x];



                length = sgi_rle_encode(&pbc, encode_buf, width,

                                        bytes_per_channel);

                if (length < 1) {

                    av_free(encode_buf);

                    return AVERROR_INVALIDDATA;

                }



                bytestream2_put_be32(&tablen_pcb, length);

                in_buf -= p->linesize[0];

            }

        }



        av_free(encode_buf);

    } else {

        for (z = 0; z < depth; z++) {

            in_buf = p->data[0] + p->linesize[0] * (height - 1) + z * bytes_per_channel;



            for (y = 0; y < height; y++) {

                for (x = 0; x < width * depth; x += depth)

                    if (bytes_per_channel == 1)

                        bytestream2_put_byte(&pbc, in_buf[x]);

                    else

                        if (put_be)

                            bytestream2_put_be16(&pbc, ((uint16_t *)in_buf)[x]);

                        else

                            bytestream2_put_le16(&pbc, ((uint16_t *)in_buf)[x]);



                in_buf -= p->linesize[0];

            }

        }

    }



    /* total length */

    pkt->size   = bytestream2_tell_p(&pbc);

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

static int encode_picture_lossless(AVCodecContext *avctx, AVPacket *pkt,
                                   const AVFrame *pict, int *got_packet)
{
    MpegEncContext * const s = avctx->priv_data;
    MJpegContext * const m = s->mjpeg_ctx;
    const int width= s->width;
    const int height= s->height;
    AVFrame * const p = &s->current_picture.f;
    const int predictor= avctx->prediction_method+1;
    const int mb_width  = (width  + s->mjpeg_hsample[0] - 1) / s->mjpeg_hsample[0];
    const int mb_height = (height + s->mjpeg_vsample[0] - 1) / s->mjpeg_vsample[0];
    int ret, max_pkt_size = FF_MIN_BUFFER_SIZE;
    if (avctx->pix_fmt == AV_PIX_FMT_BGRA)
        max_pkt_size += width * height * 3 * 4;
    else {
        max_pkt_size += mb_width * mb_height * 3 * 4
                        * s->mjpeg_hsample[0] * s->mjpeg_vsample[0];
    if ((ret = ff_alloc_packet2(avctx, pkt, max_pkt_size)) < 0)
    init_put_bits(&s->pb, pkt->data, pkt->size);
    *p = *pict;
    p->pict_type= AV_PICTURE_TYPE_I;
    p->key_frame= 1;
    ff_mjpeg_encode_picture_header(s);
    s->header_bits= put_bits_count(&s->pb);
    if(avctx->pix_fmt == AV_PIX_FMT_BGR0
        || avctx->pix_fmt == AV_PIX_FMT_BGRA
        || avctx->pix_fmt == AV_PIX_FMT_BGR24){
        int x, y, i;
        const int linesize= p->linesize[0];
        uint16_t (*buffer)[4]= (void *) s->rd_scratchpad;
        int left[3], top[3], topleft[3];
        for(i=0; i<3; i++){
            buffer[0][i]= 1 << (9 - 1);
        for(y = 0; y < height; y++) {
            const int modified_predictor= y ? predictor : 1;
            uint8_t *ptr = p->data[0] + (linesize * y);
            if(s->pb.buf_end - s->pb.buf - (put_bits_count(&s->pb)>>3) < width*3*4){
                av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");
                return -1;
            for(i=0; i<3; i++){
                top[i]= left[i]= topleft[i]= buffer[0][i];
            for(x = 0; x < width; x++) {
                if(avctx->pix_fmt == AV_PIX_FMT_BGR24){
                    buffer[x][1] = ptr[3*x+0] - ptr[3*x+1] + 0x100;
                    buffer[x][2] = ptr[3*x+2] - ptr[3*x+1] + 0x100;
                    buffer[x][0] = (ptr[3*x+0] + 2*ptr[3*x+1] + ptr[3*x+2])>>2;
                }else{
                buffer[x][1] = ptr[4*x+0] - ptr[4*x+1] + 0x100;
                buffer[x][2] = ptr[4*x+2] - ptr[4*x+1] + 0x100;
                buffer[x][0] = (ptr[4*x+0] + 2*ptr[4*x+1] + ptr[4*x+2])>>2;
                for(i=0;i<3;i++) {
                    int pred, diff;
                    PREDICT(pred, topleft[i], top[i], left[i], modified_predictor);
                    topleft[i]= top[i];
                    top[i]= buffer[x+1][i];
                    left[i]= buffer[x][i];
                    diff= ((left[i] - pred + 0x100)&0x1FF) - 0x100;
                    if(i==0)
                        ff_mjpeg_encode_dc(s, diff, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly
                    else
                        ff_mjpeg_encode_dc(s, diff, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);
    }else{
        int mb_x, mb_y, i;
        for(mb_y = 0; mb_y < mb_height; mb_y++) {
            if(s->pb.buf_end - s->pb.buf - (put_bits_count(&s->pb)>>3) < mb_width * 4 * 3 * s->mjpeg_hsample[0] * s->mjpeg_vsample[0]){
                av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");
                return -1;
            for(mb_x = 0; mb_x < mb_width; mb_x++) {
                if(mb_x==0 || mb_y==0){
                    for(i=0;i<3;i++) {
                        uint8_t *ptr;
                        int x, y, h, v, linesize;
                        h = s->mjpeg_hsample[i];
                        v = s->mjpeg_vsample[i];
                        linesize= p->linesize[i];
                        for(y=0; y<v; y++){
                            for(x=0; x<h; x++){
                                int pred;
                                ptr = p->data[i] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap
                                if(y==0 && mb_y==0){
                                    if(x==0 && mb_x==0){
                                        pred= 128;
                                    }else{
                                        pred= ptr[-1];
                                }else{
                                    if(x==0 && mb_x==0){
                                        pred= ptr[-linesize];
                                    }else{
                                        PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);
                                if(i==0)
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly
                                else
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);
                }else{
                    for(i=0;i<3;i++) {
                        uint8_t *ptr;
                        int x, y, h, v, linesize;
                        h = s->mjpeg_hsample[i];
                        v = s->mjpeg_vsample[i];
                        linesize= p->linesize[i];
                        for(y=0; y<v; y++){
                            for(x=0; x<h; x++){
                                int pred;
                                ptr = p->data[i] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap
                                PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);
                                if(i==0)
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_luminance, m->huff_code_dc_luminance); //FIXME ugly
                                else
                                    ff_mjpeg_encode_dc(s, *ptr - pred, m->huff_size_dc_chrominance, m->huff_code_dc_chrominance);
    emms_c();
    av_assert0(s->esc_pos == s->header_bits >> 3);
    ff_mjpeg_encode_stuffing(s);
    ff_mjpeg_encode_picture_trailer(s);
    s->picture_number++;
    flush_put_bits(&s->pb);
    pkt->size   = put_bits_ptr(&s->pb) - s->pb.buf;
    pkt->flags |= AV_PKT_FLAG_KEY;
    *got_packet = 1;
    return 0;
//    return (put_bits_count(&f->pb)+7)/8;

static av_always_inline void get_mvdata_interlaced(VC1Context *v, int *dmv_x,

                                                   int *dmv_y, int *pred_flag)

{

    int index, index1;

    int extend_x = 0, extend_y = 0;

    GetBitContext *gb = &v->s.gb;

    int bits, esc;

    int val, sign;

    const int* offs_tab;



    if (v->numref) {

        bits = VC1_2REF_MVDATA_VLC_BITS;

        esc  = 125;

    } else {

        bits = VC1_1REF_MVDATA_VLC_BITS;

        esc  = 71;

    }

    switch (v->dmvrange) {

    case 1:

        extend_x = 1;

        break;

    case 2:

        extend_y = 1;

        break;

    case 3:

        extend_x = extend_y = 1;

        break;

    }

    index = get_vlc2(gb, v->imv_vlc->table, bits, 3);

    if (index == esc) {

        *dmv_x = get_bits(gb, v->k_x);

        *dmv_y = get_bits(gb, v->k_y);

        if (v->numref) {

            *pred_flag = *dmv_y & 1;

            *dmv_y     = (*dmv_y + *pred_flag) >> 1;

        }

    }

    else {

        if (extend_x)

            offs_tab = offset_table2;

        else

            offs_tab = offset_table1;

        index1 = (index + 1) % 9;

        if (index1 != 0) {

            val    = get_bits(gb, index1 + extend_x);

            sign   = 0 -(val & 1);

            *dmv_x = (sign ^ ((val >> 1) + offs_tab[index1])) - sign;

        } else

            *dmv_x = 0;

        if (extend_y)

            offs_tab = offset_table2;

        else

            offs_tab = offset_table1;

        index1 = (index + 1) / 9;

        if (index1 > v->numref) {

            val    = get_bits(gb, (index1 + (extend_y << v->numref)) >> v->numref);

            sign   = 0 - (val & 1);

            *dmv_y = (sign ^ ((val >> 1) + offs_tab[index1 >> v->numref])) - sign;

        } else

            *dmv_y = 0;

        if (v->numref)

            *pred_flag = index1 & 1;

    }

}

static void vc1_decode_p_blocks(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    int apply_loop_filter;



    /* select codingmode used for VLC tables selection */

    switch (v->c_ac_table_index) {

    case 0:

        v->codingset = (v->pqindex <= 8) ? CS_HIGH_RATE_INTRA : CS_LOW_MOT_INTRA;

        break;

    case 1:

        v->codingset = CS_HIGH_MOT_INTRA;

        break;

    case 2:

        v->codingset = CS_MID_RATE_INTRA;

        break;

    }



    switch (v->c_ac_table_index) {

    case 0:

        v->codingset2 = (v->pqindex <= 8) ? CS_HIGH_RATE_INTER : CS_LOW_MOT_INTER;

        break;

    case 1:

        v->codingset2 = CS_HIGH_MOT_INTER;

        break;

    case 2:

        v->codingset2 = CS_MID_RATE_INTER;

        break;

    }



    apply_loop_filter   = s->loop_filter && !(s->avctx->skip_loop_filter >= AVDISCARD_NONKEY);

    s->first_slice_line = 1;

    memset(v->cbp_base, 0, sizeof(v->cbp_base[0])*2*s->mb_stride);

    for (s->mb_y = s->start_mb_y; s->mb_y < s->end_mb_y; s->mb_y++) {

        s->mb_x = 0;

        ff_init_block_index(s);

        for (; s->mb_x < s->mb_width; s->mb_x++) {

            ff_update_block_index(s);



            if (v->fcm == ILACE_FIELD)

                vc1_decode_p_mb_intfi(v);

            else if (v->fcm == ILACE_FRAME)

                vc1_decode_p_mb_intfr(v);

            else vc1_decode_p_mb(v);

            if (s->mb_y != s->start_mb_y && apply_loop_filter && v->fcm == PROGRESSIVE)

                vc1_apply_p_loop_filter(v);

            if (get_bits_count(&s->gb) > v->bits || get_bits_count(&s->gb) < 0) {

                // TODO: may need modification to handle slice coding

                ff_er_add_slice(s, 0, s->start_mb_y, s->mb_x, s->mb_y, ER_MB_ERROR);

                av_log(s->avctx, AV_LOG_ERROR, "Bits overconsumption: %i > %i at %ix%i\n",

                       get_bits_count(&s->gb), v->bits, s->mb_x, s->mb_y);

                return;

            }

        }

        memmove(v->cbp_base,      v->cbp,      sizeof(v->cbp_base[0])      * s->mb_stride);

        memmove(v->ttblk_base,    v->ttblk,    sizeof(v->ttblk_base[0])    * s->mb_stride);

        memmove(v->is_intra_base, v->is_intra, sizeof(v->is_intra_base[0]) * s->mb_stride);

        memmove(v->luma_mv_base,  v->luma_mv,  sizeof(v->luma_mv_base[0])  * s->mb_stride);

        if (s->mb_y != s->start_mb_y) ff_draw_horiz_band(s, (s->mb_y - 1) * 16, 16);

        s->first_slice_line = 0;

    }

    if (apply_loop_filter) {

        s->mb_x = 0;

        ff_init_block_index(s);

        for (; s->mb_x < s->mb_width; s->mb_x++) {

            ff_update_block_index(s);

            vc1_apply_p_loop_filter(v);

        }

    }

    if (s->end_mb_y >= s->start_mb_y)

        ff_draw_horiz_band(s, (s->end_mb_y - 1) * 16, 16);

    ff_er_add_slice(s, 0, s->start_mb_y << v->field_mode, s->mb_width - 1,

                    (s->end_mb_y << v->field_mode) - 1, ER_MB_END);

}

static void vc1_decode_skip_blocks(VC1Context *v)

{

    MpegEncContext *s = &v->s;



    ff_er_add_slice(s, 0, s->start_mb_y, s->mb_width - 1, s->end_mb_y - 1, ER_MB_END);

    s->first_slice_line = 1;

    for (s->mb_y = s->start_mb_y; s->mb_y < s->end_mb_y; s->mb_y++) {

        s->mb_x = 0;

        ff_init_block_index(s);

        ff_update_block_index(s);

        if (s->last_picture.f.data[0]) {

            memcpy(s->dest[0], s->last_picture.f.data[0] + s->mb_y * 16 * s->linesize,   s->linesize   * 16);

            memcpy(s->dest[1], s->last_picture.f.data[1] + s->mb_y *  8 * s->uvlinesize, s->uvlinesize *  8);

            memcpy(s->dest[2], s->last_picture.f.data[2] + s->mb_y *  8 * s->uvlinesize, s->uvlinesize *  8);

        }

        ff_draw_horiz_band(s, s->mb_y * 16, 16);

        s->first_slice_line = 0;

    }

    s->pict_type = AV_PICTURE_TYPE_P;

}

static void vc1_decode_b_blocks(VC1Context *v)

{

    MpegEncContext *s = &v->s;



    /* select codingmode used for VLC tables selection */

    switch(v->c_ac_table_index){

    case 0:

        v->codingset = (v->pqindex <= 8) ? CS_HIGH_RATE_INTRA : CS_LOW_MOT_INTRA;

        break;

    case 1:

        v->codingset = CS_HIGH_MOT_INTRA;

        break;

    case 2:

        v->codingset = CS_MID_RATE_INTRA;

        break;

    }



    switch(v->c_ac_table_index){

    case 0:

        v->codingset2 = (v->pqindex <= 8) ? CS_HIGH_RATE_INTER : CS_LOW_MOT_INTER;

        break;

    case 1:

        v->codingset2 = CS_HIGH_MOT_INTER;

        break;

    case 2:

        v->codingset2 = CS_MID_RATE_INTER;

        break;

    }



    s->first_slice_line = 1;

    for(s->mb_y = 0; s->mb_y < s->mb_height; s->mb_y++) {

        for(s->mb_x = 0; s->mb_x < s->mb_width; s->mb_x++) {

            ff_init_block_index(s);

            ff_update_block_index(s);

            s->dsp.clear_blocks(s->block[0]);



            vc1_decode_b_mb(v);

            if(get_bits_count(&s->gb) > v->bits || get_bits_count(&s->gb) < 0) {

                ff_er_add_slice(s, 0, 0, s->mb_x, s->mb_y, (AC_END|DC_END|MV_END));

                av_log(s->avctx, AV_LOG_ERROR, "Bits overconsumption: %i > %i at %ix%i\n", get_bits_count(&s->gb), v->bits,s->mb_x,s->mb_y);

                return;

            }

            if(v->s.loop_filter) vc1_loop_filter_iblk(s, s->current_picture.qscale_table[s->mb_x + s->mb_y *s->mb_stride]);

        }

        ff_draw_horiz_band(s, s->mb_y * 16, 16);

        s->first_slice_line = 0;

    }

    ff_er_add_slice(s, 0, 0, s->mb_width - 1, s->mb_height - 1, (AC_END|DC_END|MV_END));

}

paint_mouse_pointer(XImage *image, struct x11grab *s)

{

    int x_off = s->x_off;

    int y_off = s->y_off;

    int width = s->width;

    int height = s->height;

    Display *dpy = s->dpy;

    XFixesCursorImage *xcim;

    int x, y;

    int line, column;

    int to_line, to_column;

    int pixstride = image->bits_per_pixel >> 3;

    /* Warning: in its insanity, xlib provides unsigned image data through a

     * char* pointer, so we have to make it uint8_t to make things not break.

     * Anyone who performs further investigation of the xlib API likely risks

     * permanent brain damage. */

    uint8_t *pix = image->data;

    Cursor c;

    Window w;

    XSetWindowAttributes attr;



    /* Code doesn't currently support 16-bit or PAL8 */

    if (image->bits_per_pixel != 24 && image->bits_per_pixel != 32)

        return;



    c = XCreateFontCursor(dpy, XC_left_ptr);

    w = DefaultRootWindow(dpy);

    attr.cursor = c;

    XChangeWindowAttributes(dpy, w, CWCursor, &attr);



    xcim = XFixesGetCursorImage(dpy);



    x = xcim->x - xcim->xhot;

    y = xcim->y - xcim->yhot;



    to_line = FFMIN((y + xcim->height), (height + y_off));

    to_column = FFMIN((x + xcim->width), (width + x_off));



    for (line = FFMAX(y, y_off); line < to_line; line++) {

        for (column = FFMAX(x, x_off); column < to_column; column++) {

            int  xcim_addr = (line - y) * xcim->width + column - x;

            int image_addr = ((line - y_off) * width + column - x_off) * pixstride;

            int r = (uint8_t)(xcim->pixels[xcim_addr] >>  0);

            int g = (uint8_t)(xcim->pixels[xcim_addr] >>  8);

            int b = (uint8_t)(xcim->pixels[xcim_addr] >> 16);

            int a = (uint8_t)(xcim->pixels[xcim_addr] >> 24);



            if (a == 255) {

                pix[image_addr+0] = r;

                pix[image_addr+1] = g;

                pix[image_addr+2] = b;

            } else if (a) {

                /* pixel values from XFixesGetCursorImage come premultiplied by alpha */

                pix[image_addr+0] = r + (pix[image_addr+0]*(255-a) + 255/2) / 255;

                pix[image_addr+1] = g + (pix[image_addr+1]*(255-a) + 255/2) / 255;

                pix[image_addr+2] = b + (pix[image_addr+2]*(255-a) + 255/2) / 255;

            }

        }

    }



    XFree(xcim);

    xcim = NULL;

}

static void to_meta_with_crop(AVCodecContext *avctx, AVFrame *p, int *dest)

{

    int blockx, blocky, x, y;

    int luma = 0;

    int height = FFMIN(avctx->height, C64YRES);

    int width  = FFMIN(avctx->width , C64XRES);

    uint8_t *src = p->data[0];



    for (blocky = 0; blocky < C64YRES; blocky += 8) {

        for (blockx = 0; blockx < C64XRES; blockx += 8) {

            for (y = blocky; y < blocky + 8 && y < C64YRES; y++) {

                for (x = blockx; x < blockx + 8 && x < C64XRES; x += 2) {

                    if(x < width && y < height) {

                        /* build average over 2 pixels */

                        luma = (src[(x + 0 + y * p->linesize[0])] +

                                src[(x + 1 + y * p->linesize[0])]) / 2;

                        /* write blocks as linear data now so they are suitable for elbg */

                        dest[0] = luma;

                    }

                    dest++;

                }

            }

        }

    }

}

