}

envlist_setenv(envlist_t *envlist, const char *env)

{

	struct envlist_entry *entry = NULL;

	const char *eq_sign;

	size_t envname_len;



	if ((envlist == NULL) || (env == NULL))

		return (EINVAL);



	/* find out first equals sign in given env */

	if ((eq_sign = strchr(env, '=')) == NULL)

		return (EINVAL);

	envname_len = eq_sign - env + 1;



	/*

	 * If there already exists variable with given name

	 * we remove and release it before allocating a whole

	 * new entry.

	 */

	for (entry = envlist->el_entries.lh_first; entry != NULL;

	    entry = entry->ev_link.le_next) {

		if (strncmp(entry->ev_var, env, envname_len) == 0)

			break;

	}



	if (entry != NULL) {

		LIST_REMOVE(entry, ev_link);

		free((char *)entry->ev_var);

		free(entry);

	} else {

		envlist->el_count++;

	}



	if ((entry = malloc(sizeof (*entry))) == NULL)

		return (errno);

	if ((entry->ev_var = strdup(env)) == NULL) {

		free(entry);

		return (errno);

	}

	LIST_INSERT_HEAD(&envlist->el_entries, entry, ev_link);



	return (0);

}

static int yop_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    YopDecContext *yop = s->priv_data;

    AVIOContext *pb  = s->pb;



    int ret;

    int actual_video_data_size = yop->frame_size -

                                 yop->audio_block_length - yop->palette_size;



    yop->video_packet.stream_index = 1;



    if (yop->video_packet.data) {

        *pkt                   =  yop->video_packet;

        yop->video_packet.data =  NULL;

        yop->video_packet.size =  0;

        pkt->data[0]           =  yop->odd_frame;

        pkt->flags             |= AV_PKT_FLAG_KEY;

        yop->odd_frame         ^= 1;

        return pkt->size;

    }

    ret = av_new_packet(&yop->video_packet,

                        yop->frame_size - yop->audio_block_length);

    if (ret < 0)

        return ret;



    yop->video_packet.pos = avio_tell(pb);



    ret = avio_read(pb, yop->video_packet.data, yop->palette_size);

    if (ret < 0) {

        goto err_out;

    }else if (ret < yop->palette_size) {

        ret = AVERROR_EOF;

        goto err_out;

    }



    ret = av_get_packet(pb, pkt, 920);

    if (ret < 0)

        goto err_out;



    // Set position to the start of the frame

    pkt->pos = yop->video_packet.pos;



    avio_skip(pb, yop->audio_block_length - ret);



    ret = avio_read(pb, yop->video_packet.data + yop->palette_size,

                     actual_video_data_size);

    if (ret < 0)

        goto err_out;

    else if (ret < actual_video_data_size)

        av_shrink_packet(&yop->video_packet, yop->palette_size + ret);



    // Arbitrarily return the audio data first

    return yop->audio_block_length;



err_out:

    av_free_packet(&yop->video_packet);

    return ret;

}

static int iff_read_packet(AVFormatContext *s,

                           AVPacket *pkt)

{

    IffDemuxContext *iff = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st = s->streams[0];

    int ret;

    int64_t pos = avio_tell(pb);



    if (pos >= iff->body_end)

        return AVERROR_EOF;



    if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

        if (st->codec->codec_tag == ID_MAUD) {

            ret = av_get_packet(pb, pkt, FFMIN(iff->body_end - pos, 1024 * st->codec->block_align));

        } else {

            ret = av_get_packet(pb, pkt, iff->body_size);

        }

    } else if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        uint8_t *buf;



        if (av_new_packet(pkt, iff->body_size + 2) < 0) {

            return AVERROR(ENOMEM);

        }



        buf = pkt->data;

        bytestream_put_be16(&buf, 2);

        ret = avio_read(pb, buf, iff->body_size);



    } else {

        av_assert0(0);

    }



    if (pos == iff->body_pos)

        pkt->flags |= AV_PKT_FLAG_KEY;

    if (ret < 0)

        return ret;

    pkt->stream_index = 0;

    return ret;

}

static int avi_write_idx1(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    AVIContext *avi = s->priv_data;

    int64_t idx_chunk;

    int i;

    char tag[5];



    if (pb->seekable) {

        AVIStream *avist;

        AVIIentry *ie = 0, *tie;

        int empty, stream_id = -1;



        idx_chunk = ff_start_tag(pb, "idx1");

        for (i = 0; i < s->nb_streams; i++) {

            avist        = s->streams[i]->priv_data;

            avist->entry = 0;

        }



        do {

            empty = 1;

            for (i = 0; i < s->nb_streams; i++) {

                avist = s->streams[i]->priv_data;

                if (avist->indexes.entry <= avist->entry)

                    continue;



                tie = avi_get_ientry(&avist->indexes, avist->entry);

                if (empty || tie->pos < ie->pos) {

                    ie        = tie;

                    stream_id = i;

                }

                empty = 0;

            }

            if (!empty) {

                avist = s->streams[stream_id]->priv_data;

                avi_stream2fourcc(tag, stream_id,

                                  s->streams[stream_id]->codecpar->codec_type);

                ffio_wfourcc(pb, tag);

                avio_wl32(pb, ie->flags);

                avio_wl32(pb, ie->pos);

                avio_wl32(pb, ie->len);

                avist->entry++;

            }

        } while (!empty);

        ff_end_tag(pb, idx_chunk);



        avi_write_counters(s, avi->riff_id);

    }

    return 0;

}

static int write_skip_frames(AVFormatContext *s, int stream_index, int64_t dts)

{

    AVIStream *avist    = s->streams[stream_index]->priv_data;

    AVCodecContext *enc = s->streams[stream_index]->codec;



    av_dlog(s, "dts:%s packet_count:%d stream_index:%d\n", av_ts2str(dts), avist->packet_count, stream_index);

    while (enc->block_align == 0 && dts != AV_NOPTS_VALUE &&

           dts > avist->packet_count && enc->codec_id != AV_CODEC_ID_XSUB && avist->packet_count) {

        AVPacket empty_packet;



        if (dts - avist->packet_count > 60000) {

            av_log(s, AV_LOG_ERROR, "Too large number of skipped frames %"PRId64" > 60000\n", dts - avist->packet_count);

            return AVERROR(EINVAL);

        }



        av_init_packet(&empty_packet);

        empty_packet.size         = 0;

        empty_packet.data         = NULL;

        empty_packet.stream_index = stream_index;

        avi_write_packet(s, &empty_packet);

        av_dlog(s, "dup dts:%s packet_count:%d\n", av_ts2str(dts), avist->packet_count);

    }



    return 0;

}

static int decode_dc_progressive(MJpegDecodeContext *s, int16_t *block,

                                 int component, int dc_index,

                                 int16_t *quant_matrix, int Al)

{

    int val;

    s->bdsp.clear_block(block);

    val = mjpeg_decode_dc(s, dc_index);

    if (val == 0xfffff) {

        av_log(s->avctx, AV_LOG_ERROR, "error dc\n");

        return AVERROR_INVALIDDATA;

    }

    val = (val * (quant_matrix[0] << Al)) + s->last_dc[component];

    s->last_dc[component] = val;

    block[0] = val;

    return 0;

}

static inline int GET_TOK(TM2Context *ctx,int type) {

    if(ctx->tok_ptrs[type] >= ctx->tok_lens[type]) {

        av_log(ctx->avctx, AV_LOG_ERROR, "Read token from stream %i out of bounds (%i>=%i)\n", type, ctx->tok_ptrs[type], ctx->tok_lens[type]);

        return 0;

    }

    if(type <= TM2_MOT)

        return ctx->deltas[type][ctx->tokens[type][ctx->tok_ptrs[type]++]];

    return ctx->tokens[type][ctx->tok_ptrs[type]++];

}

