bool address_space_access_valid(AddressSpace *as, hwaddr addr, int len, bool is_write)

{

    MemoryRegion *mr;

    hwaddr l, xlat;



    rcu_read_lock();

    while (len > 0) {

        l = len;

        mr = address_space_translate(as, addr, &xlat, &l, is_write);

        if (!memory_access_is_direct(mr, is_write)) {

            l = memory_access_size(mr, l, addr);

            if (!memory_region_access_valid(mr, xlat, l, is_write)) {


                return false;

            }

        }



        len -= l;

        addr += l;

    }


    return true;

}

static inline int get_ue_code(GetBitContext *gb, int order)

{

    if (order) {

        int ret = get_ue_golomb(gb) << order;

        return ret + get_bits(gb, order);

    }

    return get_ue_golomb(gb);

}

static inline int memory_access_size(MemoryRegion *mr, int l, hwaddr addr)

{

    if (l >= 4 && (((addr & 3) == 0 || mr->ops->impl.unaligned))) {

        return 4;

    }

    if (l >= 2 && (((addr & 1) == 0) || mr->ops->impl.unaligned)) {

        return 2;

    }

    return 1;

}

static inline bool fp_access_check(DisasContext *s)

{

    assert(!s->fp_access_checked);

    s->fp_access_checked = true;



    if (s->cpacr_fpen) {

        return true;

    }



    gen_exception_insn(s, 4, EXCP_UDEF, syn_fp_access_trap(1, 0xe, false),

                       default_exception_el(s));

    return false;

}

static int virtio_blk_device_init(VirtIODevice *vdev)

{

    DeviceState *qdev = DEVICE(vdev);

    VirtIOBlock *s = VIRTIO_BLK(vdev);

    VirtIOBlkConf *blk = &(s->blk);

    static int virtio_blk_id;



    if (!blk->conf.bs) {

        error_report("drive property not set");

        return -1;

    }

    if (!bdrv_is_inserted(blk->conf.bs)) {

        error_report("Device needs media, but drive is empty");

        return -1;

    }



    blkconf_serial(&blk->conf, &blk->serial);

    if (blkconf_geometry(&blk->conf, NULL, 65535, 255, 255) < 0) {

        return -1;

    }



    virtio_init(vdev, "virtio-blk", VIRTIO_ID_BLOCK,

                sizeof(struct virtio_blk_config));



    vdev->get_config = virtio_blk_update_config;

    vdev->set_config = virtio_blk_set_config;

    vdev->get_features = virtio_blk_get_features;

    vdev->set_status = virtio_blk_set_status;

    vdev->reset = virtio_blk_reset;

    s->bs = blk->conf.bs;

    s->conf = &blk->conf;

    memcpy(&(s->blk), blk, sizeof(struct VirtIOBlkConf));

    s->rq = NULL;

    s->sector_mask = (s->conf->logical_block_size / BDRV_SECTOR_SIZE) - 1;



    s->vq = virtio_add_queue(vdev, 128, virtio_blk_handle_output);

#ifdef CONFIG_VIRTIO_BLK_DATA_PLANE

    if (!virtio_blk_data_plane_create(vdev, blk, &s->dataplane)) {

        virtio_cleanup(vdev);

        return -1;

    }

#endif



    s->change = qemu_add_vm_change_state_handler(virtio_blk_dma_restart_cb, s);

    register_savevm(qdev, "virtio-blk", virtio_blk_id++, 2,

                    virtio_blk_save, virtio_blk_load, s);

    bdrv_set_dev_ops(s->bs, &virtio_block_ops, s);

    bdrv_set_buffer_alignment(s->bs, s->conf->logical_block_size);



    bdrv_iostatus_enable(s->bs);



    add_boot_device_path(s->conf->bootindex, qdev, "/disk@0,0");

    return 0;

}

