static void copy_frame(J2kEncoderContext *s)

{

    int tileno, compno, i, y, x;

    uint8_t *line;

    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++){

        J2kTile *tile = s->tile + tileno;

        if (s->planar){

            for (compno = 0; compno < s->ncomponents; compno++){

                J2kComponent *comp = tile->comp + compno;

                int *dst = comp->data;

                line = s->picture->data[compno]

                       + comp->coord[1][0] * s->picture->linesize[compno]

                       + comp->coord[0][0];

                for (y = comp->coord[1][0]; y < comp->coord[1][1]; y++){

                    uint8_t *ptr = line;

                    for (x = comp->coord[0][0]; x < comp->coord[0][1]; x++)

                        *dst++ = *ptr++ - (1 << 7);

                    line += s->picture->linesize[compno];

                }

            }

        } else{

            line = s->picture->data[0] + tile->comp[0].coord[1][0] * s->picture->linesize[0]

                   + tile->comp[0].coord[0][0] * s->ncomponents;



            i = 0;

            for (y = tile->comp[0].coord[1][0]; y < tile->comp[0].coord[1][1]; y++){

                uint8_t *ptr = line;

                for (x = tile->comp[0].coord[0][0]; x < tile->comp[0].coord[0][1]; x++, i++){

                    for (compno = 0; compno < s->ncomponents; compno++){

                        tile->comp[compno].data[i] = *ptr++  - (1 << 7);

                    }

                }

                line += s->picture->linesize[0];

            }

        }

    }

}

static void jpeg2000_dec_cleanup(Jpeg2000DecoderContext *s)

{

    int tileno, compno;

    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++) {

        if (s->tile[tileno].comp) {

            for (compno = 0; compno < s->ncomponents; compno++) {

                Jpeg2000Component *comp     = s->tile[tileno].comp   + compno;

                Jpeg2000CodingStyle *codsty = s->tile[tileno].codsty + compno;



                ff_jpeg2000_cleanup(comp, codsty);

            }

            av_freep(&s->tile[tileno].comp);

        }

    }

    av_freep(&s->tile);



    s->numXtiles = s->numYtiles = 0;

}

static void update_sono_yuv(AVFrame *sono, const ColorFloat *c, int idx)

{

    int x, fmt = sono->format, w = sono->width;

    uint8_t *lpy = sono->data[0] + idx * sono->linesize[0];

    uint8_t *lpu = sono->data[1] + idx * sono->linesize[1];

    uint8_t *lpv = sono->data[2] + idx * sono->linesize[2];



    for (x = 0; x < w; x += 2) {

        *lpy++ = c[x].yuv.y + 0.5f;

        *lpu++ = c[x].yuv.u + 0.5f;

        *lpv++ = c[x].yuv.v + 0.5f;

        *lpy++ = c[x+1].yuv.y + 0.5f;

        if (fmt == AV_PIX_FMT_YUV444P) {

            *lpu++ = c[x+1].yuv.u + 0.5f;

            *lpv++ = c[x+1].yuv.v + 0.5f;

        }

    }

}

static int jpeg2000_read_bitstream_packets(Jpeg2000DecoderContext *s)

{

    int ret = 0;

    int tileno;



    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++) {

        Jpeg2000Tile *tile = s->tile + tileno;



        if (ret = init_tile(s, tileno))

            return ret;



        s->g = tile->tile_part[0].tpg;

        if (ret = jpeg2000_decode_packets(s, tile))

            return ret;

    }



    return 0;

}

