static int mov_read_ctts(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */

    entries = avio_rb32(pb);



    av_log(c->fc, AV_LOG_TRACE, "track[%i].ctts.entries = %i\n", c->fc->nb_streams-1, entries);



    if (!entries)

        return 0;

    if (entries >= UINT_MAX / sizeof(*sc->ctts_data))

        return AVERROR_INVALIDDATA;

    av_freep(&sc->ctts_data);

    sc->ctts_data = av_realloc(NULL, entries * sizeof(*sc->ctts_data));

    if (!sc->ctts_data)

        return AVERROR(ENOMEM);



    for (i = 0; i < entries && !pb->eof_reached; i++) {

        int count    =avio_rb32(pb);

        int duration =avio_rb32(pb);



        sc->ctts_data[i].count   = count;

        sc->ctts_data[i].duration= duration;



        av_log(c->fc, AV_LOG_TRACE, "count=%d, duration=%d\n",

                count, duration);



        if (FFABS(duration) > (1<<28) && i+2<entries) {

            av_log(c->fc, AV_LOG_WARNING, "CTTS invalid\n");

            av_freep(&sc->ctts_data);

            sc->ctts_count = 0;

            return 0;

        }



        if (i+2<entries)

            mov_update_dts_shift(sc, duration);

    }



    sc->ctts_count = i;



    if (pb->eof_reached)

        return AVERROR_EOF;



    av_log(c->fc, AV_LOG_TRACE, "dts shift %d\n", sc->dts_shift);



    return 0;

}

static void qpci_pc_config_writel(QPCIBus *bus, int devfn, uint8_t offset, uint32_t value)

{

    outl(0xcf8, (1 << 31) | (devfn << 8) | offset);

    outl(0xcfc, value);

}

static uint16_t qpci_pc_config_readw(QPCIBus *bus, int devfn, uint8_t offset)

{

    outl(0xcf8, (1 << 31) | (devfn << 8) | offset);

    return inw(0xcfc);

}

static void gic_dist_writew(void *opaque, target_phys_addr_t offset,

                            uint32_t value)

{

    gic_dist_writeb(opaque, offset, value & 0xff);

    gic_dist_writeb(opaque, offset + 1, value >> 8);

}

static int pci_apb_map_irq(PCIDevice *pci_dev, int irq_num)

{

    return ((pci_dev->devfn & 0x18) >> 1) + irq_num;

}

static int decode_stream_header(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    StreamContext *stc;

    int class, nom, denom, stream_id;

    uint64_t tmp, end;

    AVStream *st;



    end= get_packetheader(nut, bc, 1);

    end += url_ftell(bc) - 4;



    GET_V(stream_id, tmp < s->nb_streams && !nut->stream[tmp].time_base.num);

    stc= &nut->stream[stream_id];



    st = s->streams[stream_id];

    if (!st)

        return AVERROR_NOMEM;



    class = get_v(bc);

    tmp = get_fourcc(bc);

    st->codec->codec_tag= tmp;

    switch(class)

    {

        case 0:

            st->codec->codec_type = CODEC_TYPE_VIDEO;

            st->codec->codec_id = codec_get_bmp_id(tmp);

            if (st->codec->codec_id == CODEC_ID_NONE)

                av_log(s, AV_LOG_ERROR, "Unknown codec?!\n");

            break;

        case 1:

            st->codec->codec_type = CODEC_TYPE_AUDIO;

            st->codec->codec_id = codec_get_wav_id(tmp);

            if (st->codec->codec_id == CODEC_ID_NONE)

                av_log(s, AV_LOG_ERROR, "Unknown codec?!\n");

            break;

        case 2:

//            st->codec->codec_type = CODEC_TYPE_TEXT;

//            break;

        case 3:

            st->codec->codec_type = CODEC_TYPE_DATA;

            break;

        default:

            av_log(s, AV_LOG_ERROR, "Unknown stream class (%d)\n", class);

            return -1;

    }

    GET_V(stc->time_base_id    , tmp < nut->time_base_count);

    GET_V(stc->msb_pts_shift   , tmp < 16);

    stc->max_pts_distance= get_v(bc);

    GET_V(stc->decode_delay    , tmp < 1000); //sanity limit, raise this if moors law is true

    st->codec->has_b_frames= stc->decode_delay;

    get_v(bc); //stream flags



    GET_V(st->codec->extradata_size, tmp < (1<<30));

    if(st->codec->extradata_size){

        st->codec->extradata= av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

        get_buffer(bc, st->codec->extradata, st->codec->extradata_size);

    }



    if (st->codec->codec_type == CODEC_TYPE_VIDEO){

        GET_V(st->codec->width , tmp > 0)

        GET_V(st->codec->height, tmp > 0)

        st->codec->sample_aspect_ratio.num= get_v(bc);

        st->codec->sample_aspect_ratio.den= get_v(bc);

        if((!st->codec->sample_aspect_ratio.num) != (!st->codec->sample_aspect_ratio.den)){

            av_log(s, AV_LOG_ERROR, "invalid aspect ratio\n");

            return -1;

        }

        get_v(bc); /* csp type */

    }else if (st->codec->codec_type == CODEC_TYPE_AUDIO){

        GET_V(st->codec->sample_rate , tmp > 0)

        tmp= get_v(bc); // samplerate_den

        if(tmp > st->codec->sample_rate){

            av_log(s, AV_LOG_ERROR, "bleh, libnut muxed this ;)\n");

            st->codec->sample_rate= tmp;

        }

        GET_V(st->codec->channels, tmp > 0)

    }

    if(skip_reserved(bc, end) || check_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "Stream header %d checksum mismatch\n", stream_id);

        return -1;

    }

    stc->time_base= nut->time_base[stc->time_base_id];

    av_set_pts_info(s->streams[stream_id], 63, stc->time_base.num, stc->time_base.den);

    return 0;

}

static int decode_main_header(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    uint64_t tmp, end;

    unsigned int stream_count;

    int i, j, tmp_stream, tmp_mul, tmp_pts, tmp_size, count, tmp_res;



    end= get_packetheader(nut, bc, 1);

    end += url_ftell(bc) - 4;



    GET_V(tmp              , tmp >=2 && tmp <= 3)

    GET_V(stream_count     , tmp > 0 && tmp <=MAX_STREAMS)



    nut->max_distance = get_v(bc);

    if(nut->max_distance > 65536){

        av_log(s, AV_LOG_DEBUG, "max_distance %d\n", nut->max_distance);

        nut->max_distance= 65536;

    }



    GET_V(nut->time_base_count, tmp>0 && tmp<INT_MAX / sizeof(AVRational))

    nut->time_base= av_malloc(nut->time_base_count * sizeof(AVRational));



    for(i=0; i<nut->time_base_count; i++){

        GET_V(nut->time_base[i].num, tmp>0 && tmp<(1ULL<<31))

        GET_V(nut->time_base[i].den, tmp>0 && tmp<(1ULL<<31))

        if(ff_gcd(nut->time_base[i].num, nut->time_base[i].den) != 1){

            av_log(s, AV_LOG_ERROR, "time base invalid\n");

            return -1;

        }

    }

    tmp_pts=0;

    tmp_mul=1;

    tmp_stream=0;

    for(i=0; i<256;){

        int tmp_flags = get_v(bc);

        int tmp_fields= get_v(bc);

        if(tmp_fields>0) tmp_pts   = get_s(bc);

        if(tmp_fields>1) tmp_mul   = get_v(bc);

        if(tmp_fields>2) tmp_stream= get_v(bc);

        if(tmp_fields>3) tmp_size  = get_v(bc);

        else             tmp_size  = 0;

        if(tmp_fields>4) tmp_res   = get_v(bc);

        else             tmp_res   = 0;

        if(tmp_fields>5) count     = get_v(bc);

        else             count     = tmp_mul - tmp_size;



        while(tmp_fields-- > 6)

           get_v(bc);



        if(count == 0 || i+count > 256){

            av_log(s, AV_LOG_ERROR, "illegal count %d at %d\n", count, i);

            return -1;

        }

        if(tmp_stream >= stream_count){

            av_log(s, AV_LOG_ERROR, "illegal stream number\n");

            return -1;

        }



        for(j=0; j<count; j++,i++){

            if (i == 'N') {

                nut->frame_code[i].flags= FLAG_INVALID;

                j--;

                continue;

            }

            nut->frame_code[i].flags           = tmp_flags ;

            nut->frame_code[i].pts_delta       = tmp_pts   ;

            nut->frame_code[i].stream_id       = tmp_stream;

            nut->frame_code[i].size_mul        = tmp_mul   ;

            nut->frame_code[i].size_lsb        = tmp_size+j;

            nut->frame_code[i].reserved_count  = tmp_res   ;

        }

    }

    assert(nut->frame_code['N'].flags == FLAG_INVALID);



    if(skip_reserved(bc, end) || check_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "Main header checksum mismatch\n");

        return -1;

    }



    nut->stream = av_mallocz(sizeof(StreamContext)*stream_count);

    for(i=0; i<stream_count; i++){

        av_new_stream(s, i);

    }



    return 0;

}

static int decode_syncpoint(NUTContext *nut, int64_t *ts, int64_t *back_ptr){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    int64_t end, tmp;

    AVRational time_base;



    nut->last_syncpoint_pos= url_ftell(bc)-8;



    end= get_packetheader(nut, bc, 1);

    end += url_ftell(bc);



    tmp= get_v(bc);

    *back_ptr= nut->last_syncpoint_pos - 16*get_v(bc);

    if(*back_ptr < 0)

        return -1;



    ff_nut_reset_ts(nut, nut->time_base[tmp % nut->time_base_count], tmp);



    if(skip_reserved(bc, end) || get_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "sync point checksum mismatch\n");

        return -1;

    }



    *ts= tmp / s->nb_streams * av_q2d(nut->time_base[tmp % s->nb_streams])*AV_TIME_BASE;

    add_sp(nut, nut->last_syncpoint_pos, *back_ptr, *ts);



    return 0;

}

static int raw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVStream *st;

    int id;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR_NOMEM;

    if (ap) {

        id = s->iformat->value;

        if (id == CODEC_ID_RAWVIDEO) {

            st->codec->codec_type = CODEC_TYPE_VIDEO;

        } else {

            st->codec->codec_type = CODEC_TYPE_AUDIO;

        }

        st->codec->codec_id = id;



        switch(st->codec->codec_type) {

        case CODEC_TYPE_AUDIO:

            st->codec->sample_rate = ap->sample_rate;

            st->codec->channels = ap->channels;

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

            break;

        case CODEC_TYPE_VIDEO:

            av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

            st->codec->width = ap->width;

            st->codec->height = ap->height;

            st->codec->pix_fmt = ap->pix_fmt;

            if(st->codec->pix_fmt == PIX_FMT_NONE)

                st->codec->pix_fmt= PIX_FMT_YUV420P;

            break;

        default:

            return -1;

        }

    } else {

        return -1;

    }

    return 0;

}

static unsigned int mszh_decomp(unsigned char * srcptr, int srclen, unsigned char * destptr, unsigned int destsize)

{

    unsigned char *destptr_bak = destptr;

    unsigned char *destptr_end = destptr + destsize;

    unsigned char mask = 0;

    unsigned char maskbit = 0;

    unsigned int ofs, cnt;



    while (srclen > 0 && destptr < destptr_end) {

        if (maskbit == 0) {

            mask = *srcptr++;

            maskbit = 8;

            srclen--;

            continue;

        }

        if ((mask & (1 << (--maskbit))) == 0) {

            if (destptr + 4 > destptr_end)

                break;

            memcpy(destptr, srcptr, 4);

            srclen -= 4;

            destptr += 4;

            srcptr += 4;

        } else {

            ofs = *srcptr++;

            cnt = *srcptr++;

            ofs += cnt * 256;

            cnt = ((cnt >> 3) & 0x1f) + 1;

            ofs &= 0x7ff;

            srclen -= 2;

            cnt *= 4;

            if (destptr + cnt > destptr_end) {

                cnt =  destptr_end - destptr;

            }

            for (; cnt > 0; cnt--) {

                *destptr = *(destptr - ofs);

                destptr++;

            }

        }

    }



    return destptr - destptr_bak;

}

static int mszh_decomp(unsigned char * srcptr, int srclen, unsigned char * destptr)

{

    unsigned char *destptr_bak = destptr;

    unsigned char mask = 0;

    unsigned char maskbit = 0;

    unsigned int ofs, cnt;



    while (srclen > 0) {

        if (maskbit == 0) {

            mask = *(srcptr++);

            maskbit = 8;

            srclen--;

            continue;

        }

        if ((mask & (1 << (--maskbit))) == 0) {

            *(int*)destptr = *(int*)srcptr;

            srclen -= 4;

            destptr += 4;

            srcptr += 4;

        } else {

            ofs = *(srcptr++);

            cnt = *(srcptr++);

            ofs += cnt * 256;;

            cnt = ((cnt >> 3) & 0x1f) + 1;

            ofs &= 0x7ff;

            srclen -= 2;

            cnt *= 4;

            for (; cnt > 0; cnt--) {

                *(destptr) = *(destptr - ofs);

                destptr++;

            }

        }

    }



    return (destptr - destptr_bak);

}

static void lz_unpack(unsigned char *src, unsigned char *dest)

{

    unsigned char *s;

    unsigned char *d;

    unsigned char queue[QUEUE_SIZE];

    unsigned int qpos;

    unsigned int dataleft;

    unsigned int chainofs;

    unsigned int chainlen;

    unsigned int speclen;

    unsigned char tag;

    unsigned int i, j;



    s = src;

    d = dest;

    dataleft = LE_32(s);

    s += 4;

    memset(queue, QUEUE_SIZE, 0x20);

    if (LE_32(s) == 0x56781234) {

        s += 4;

        qpos = 0x111;

        speclen = 0xF + 3;

    } else {

        qpos = 0xFEE;

        speclen = 100;  /* no speclen */

    }



    while (dataleft > 0) {

        tag = *s++;

        if ((tag == 0xFF) && (dataleft > 8)) {

            for (i = 0; i < 8; i++) {

                queue[qpos++] = *d++ = *s++;

                qpos &= QUEUE_MASK;

            }

            dataleft -= 8;

        } else {

            for (i = 0; i < 8; i++) {

                if (dataleft == 0)

                    break;

                if (tag & 0x01) {

                    queue[qpos++] = *d++ = *s++;

                    qpos &= QUEUE_MASK;

                    dataleft--;

                } else {

                    chainofs = *s++;

                    chainofs |= ((*s & 0xF0) << 4);

                    chainlen = (*s++ & 0x0F) + 3;

                    if (chainlen == speclen)

                        chainlen = *s++ + 0xF + 3;

                    for (j = 0; j < chainlen; j++) {

                        *d = queue[chainofs++ & QUEUE_MASK];

                        queue[qpos++] = *d++;

                        qpos &= QUEUE_MASK;

                    }

                    dataleft -= chainlen;

                }

                tag >>= 1;

            }

        }

    }

}

static int rle_unpack(unsigned char *src, unsigned char *dest, int len)

{

    unsigned char *ps;

    unsigned char *pd;

    int i, l;



    ps = src;

    pd = dest;

    if (len & 1)

        *pd++ = *ps++;



    len >>= 1;

    i = 0;

    do {

        l = *ps++;

        if (l & 0x80) {

            l = (l & 0x7F) * 2;

            memcpy(pd, ps, l);

            ps += l;

            pd += l;

        } else {

            for (i = 0; i < l; i++) {

                *pd++ = ps[0];

                *pd++ = ps[1];

            }

            ps += 2;

        }

        i += l;

    } while (i < len);



    return (ps - src);

}

