int qemu_egl_rendernode_open(void)

{

    DIR *dir;

    struct dirent *e;

    int r, fd;

    char *p;



    dir = opendir("/dev/dri");

    if (!dir) {

        return -1;

    }



    fd = -1;

    while ((e = readdir(dir))) {

        if (e->d_type != DT_CHR) {

            continue;

        }



        if (strncmp(e->d_name, "renderD", 7)) {

            continue;

        }



        r = asprintf(&p, "/dev/dri/%s", e->d_name);

        if (r < 0) {

            return -1;

        }



        r = open(p, O_RDWR | O_CLOEXEC | O_NOCTTY | O_NONBLOCK);

        if (r < 0) {

            free(p);

            continue;

        }

        fd = r;

        free(p);

        break;

    }



    closedir(dir);

    if (fd < 0) {

        return -1;

    }

    return fd;

}

void init_paths(const char *prefix)

{

    char pref_buf[PATH_MAX];



    if (prefix[0] == '\0' ||

        !strcmp(prefix, "/"))

        return;



    if (prefix[0] != '/') {

        char *cwd = getcwd(NULL, 0);

        size_t pref_buf_len = sizeof(pref_buf);



        if (!cwd)

            abort();

        pstrcpy(pref_buf, sizeof(pref_buf), cwd);

        pstrcat(pref_buf, pref_buf_len, "/");

        pstrcat(pref_buf, pref_buf_len, prefix);

        free(cwd);

    } else

        pstrcpy(pref_buf, sizeof(pref_buf), prefix + 1);



    base = new_entry("", NULL, pref_buf);

    base = add_dir_maybe(base);

    if (base->num_entries == 0) {

        g_free(base->pathname);

        free(base->name);

        free(base);

        base = NULL;

    } else {

        set_parents(base, base);

    }

}

static BlockDriver *find_protocol(const char *filename)

{

    BlockDriver *drv1;

    char protocol[128];

    int len;

    const char *p;



#ifdef _WIN32

    if (is_windows_drive(filename) ||

        is_windows_drive_prefix(filename))

        return bdrv_find_format("raw");

#endif

    p = strchr(filename, ':');

    if (!p)

        return bdrv_find_format("raw");

    len = p - filename;

    if (len > sizeof(protocol) - 1)

        len = sizeof(protocol) - 1;

    memcpy(protocol, filename, len);

    protocol[len] = '\0';

    QLIST_FOREACH(drv1, &bdrv_drivers, list) {

        if (drv1->protocol_name &&

            !strcmp(drv1->protocol_name, protocol)) {

            return drv1;

        }

    }

    return NULL;

}

static void v9fs_wstat_post_chown(V9fsState *s, V9fsWstatState *vs, int err)

{

    V9fsFidState *fidp;

    if (err < 0) {

        goto out;

    }



    if (vs->v9stat.name.size != 0) {

        char *old_name, *new_name;

        char *end;



        old_name = vs->fidp->path.data;

        end = strrchr(old_name, '/');

        if (end) {

            end++;

        } else {

            end = old_name;

        }



        new_name = qemu_mallocz(end - old_name + vs->v9stat.name.size + 1);



        memcpy(new_name, old_name, end - old_name);

        memcpy(new_name + (end - old_name), vs->v9stat.name.data,

                vs->v9stat.name.size);

        vs->nname.data = new_name;

        vs->nname.size = strlen(new_name);



        if (strcmp(new_name, vs->fidp->path.data) != 0) {

            if (v9fs_do_rename(s, &vs->fidp->path, &vs->nname)) {

                err = -errno;

            } else {

                /*

                 * Fixup fid's pointing to the old name to

                 * start pointing to the new name

                 */

                for (fidp = s->fid_list; fidp; fidp = fidp->next) {



                    if (vs->fidp == fidp) {

                        /*

                         * we replace name of this fid towards the end

                         * so that our below strcmp will work

                         */

                        continue;

                    }

                    if (!strncmp(vs->fidp->path.data, fidp->path.data,

                                 strlen(vs->fidp->path.data))) {

                        /* replace the name */

                        v9fs_fix_path(&fidp->path, &vs->nname,

                                      strlen(vs->fidp->path.data));

                    }

                }

                v9fs_string_copy(&vs->fidp->path, &vs->nname);

            }

        }

    }

    v9fs_wstat_post_rename(s, vs, err);

    return;



out:

    v9fs_stat_free(&vs->v9stat);

    complete_pdu(s, vs->pdu, err);

    qemu_free(vs);

}

static void set_int32(Object *obj, Visitor *v, void *opaque,

                      const char *name, Error **errp)

{

    DeviceState *dev = DEVICE(obj);

    Property *prop = opaque;

    int32_t *ptr = qdev_get_prop_ptr(dev, prop);

    Error *local_err = NULL;

    int64_t value;



    if (dev->state != DEV_STATE_CREATED) {

        error_set(errp, QERR_PERMISSION_DENIED);

        return;

    }



    visit_type_int(v, &value, name, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }

    if (value > prop->info->min && value <= prop->info->max) {

        *ptr = value;

    } else {

        error_set(errp, QERR_PROPERTY_VALUE_OUT_OF_RANGE,

                  dev->id?:"", name, value, prop->info->min,

                  prop->info->max);

    }

}

