static int read_matrix_params(MLPDecodeContext *m, SubStream *s, GetBitContext *gbp)

{

    unsigned int mat, ch;



    s->num_primitive_matrices = get_bits(gbp, 4);

    m->matrix_changed++;



    for (mat = 0; mat < s->num_primitive_matrices; mat++) {

        int frac_bits, max_chan;

        s->matrix_out_ch[mat] = get_bits(gbp, 4);

        frac_bits             = get_bits(gbp, 4);

        s->lsb_bypass   [mat] = get_bits1(gbp);



        if (s->matrix_out_ch[mat] > s->max_matrix_channel) {

            av_log(m->avctx, AV_LOG_ERROR,

                    "Invalid channel %d specified as output from matrix.\n",

                    s->matrix_out_ch[mat]);

            return -1;

        }

        if (frac_bits > 14) {

            av_log(m->avctx, AV_LOG_ERROR,

                    "Too many fractional bits specified.\n");

            return -1;

        }



        max_chan = s->max_matrix_channel;

        if (!s->noise_type)

            max_chan+=2;



        for (ch = 0; ch <= max_chan; ch++) {

            int coeff_val = 0;

            if (get_bits1(gbp))

                coeff_val = get_sbits(gbp, frac_bits + 2);



            s->matrix_coeff[mat][ch] = coeff_val << (14 - frac_bits);

        }



        if (s->noise_type)

            s->matrix_noise_shift[mat] = get_bits(gbp, 4);

        else

            s->matrix_noise_shift[mat] = 0;

    }



    return 0;

}

static int metadata_parse(FLACContext *s)

{

    int i, metadata_last, metadata_type, metadata_size;

    int initial_pos= get_bits_count(&s->gb);



    if (show_bits_long(&s->gb, 32) == MKBETAG('f','L','a','C')) {

        skip_bits_long(&s->gb, 32);



        do {

            metadata_last = get_bits1(&s->gb);

            metadata_type = get_bits(&s->gb, 7);

            metadata_size = get_bits_long(&s->gb, 24);



            if (get_bits_count(&s->gb) + 8*metadata_size > s->gb.size_in_bits) {

                skip_bits_long(&s->gb, initial_pos - get_bits_count(&s->gb));

                break;

            }



            if (metadata_size) {

                switch (metadata_type) {

                case FLAC_METADATA_TYPE_STREAMINFO:

                    if (!s->got_streaminfo) {

                        ff_flac_parse_streaminfo(s->avctx, (FLACStreaminfo *)s,

                                                 s->gb.buffer+get_bits_count(&s->gb)/8);

                        allocate_buffers(s);

                        s->got_streaminfo = 1;

                    }

                default:

                    for (i = 0; i < metadata_size; i++)

                        skip_bits(&s->gb, 8);

                }

            }

        } while (!metadata_last);



        return 1;

    }

    return 0;

}

static int wavpack_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    WavpackContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    int frame_size;

    int samplecount = 0;



    s->block = 0;

    s->samples_left = 0;

    s->ch_offset = 0;



    if(s->mkv_mode){

        s->samples = AV_RL32(buf); buf += 4;

    }

    while(buf_size > 0){

        if(!s->multichannel){

            frame_size = buf_size;

        }else{

            if(!s->mkv_mode){

                frame_size = AV_RL32(buf) - 12; buf += 4; buf_size -= 4;

            }else{

                if(buf_size < 12) //MKV files can have zero flags after last block

                    break;

                frame_size = AV_RL32(buf + 8) + 12;

            }

        }

        if(frame_size < 0 || frame_size > buf_size){

            av_log(avctx, AV_LOG_ERROR, "Block %d has invalid size (size %d vs. %d bytes left)\n",

                   s->block, frame_size, buf_size);

            return -1;

        }

        if((samplecount = wavpack_decode_block(avctx, s->block, data,

                                               data_size, buf, frame_size)) < 0)

            return -1;

        s->block++;

        buf += frame_size; buf_size -= frame_size;

    }

    *data_size = samplecount * avctx->channels;



    return s->samples_left > 0 ? 0 : avpkt->size;

}

static int ws_snd_decode_frame(AVCodecContext *avctx,

                void *data, int *data_size,

                AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

//    WSSNDContext *c = avctx->priv_data;



    int in_size, out_size;

    int sample = 128;

    int i;

    uint8_t *samples = data;



    if (!buf_size)

        return 0;



    out_size = AV_RL16(&buf[0]);

    in_size = AV_RL16(&buf[2]);

    buf += 4;



    if (out_size > *data_size) {

        av_log(avctx, AV_LOG_ERROR, "Frame is too large to fit in buffer\n");

        return -1;

    }

    if (in_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "Frame data is larger than input buffer\n");

        return -1;

    }



    *data_size = out_size;



    if (in_size == out_size) {

        for (i = 0; i < out_size; i++)

            *samples++ = *buf++;

        return buf_size;

    }



    while (out_size > 0) {

        int code;

        uint8_t count;

        code = (*buf) >> 6;

        count = (*buf) & 0x3F;

        buf++;

        switch(code) {

        case 0: /* ADPCM 2-bit */

            for (count++; count > 0; count--) {

                code = *buf++;

                sample += ws_adpcm_2bit[code & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_2bit[(code >> 2) & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_2bit[(code >> 4) & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_2bit[(code >> 6) & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                out_size -= 4;

            }

            break;

        case 1: /* ADPCM 4-bit */

            for (count++; count > 0; count--) {

                code = *buf++;

                sample += ws_adpcm_4bit[code & 0xF];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_4bit[code >> 4];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                out_size -= 2;

            }

            break;

        case 2: /* no compression */

            if (count & 0x20) { /* big delta */

                int8_t t;

                t = count;

                t <<= 3;

                sample += t >> 3;

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                out_size--;

            } else { /* copy */

                for (count++; count > 0; count--) {

                    *samples++ = *buf++;

                    out_size--;

                }

                sample = buf[-1];

            }

            break;

        default: /* run */

            for(count++; count > 0; count--) {

                *samples++ = sample;

                out_size--;

            }

        }

    }



    return buf_size;

}

static int g726_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    G726Context *c = avctx->priv_data;

    int16_t *samples = data;

    GetBitContext gb;



    init_get_bits(&gb, buf, buf_size * 8);



    while (get_bits_count(&gb) + c->code_size <= buf_size*8)

        *samples++ = g726_decode(c, get_bits(&gb, c->code_size));



    if(buf_size*8 != get_bits_count(&gb))

        av_log(avctx, AV_LOG_ERROR, "Frame invalidly split, missing parser?\n");



    *data_size = (uint8_t*)samples - (uint8_t*)data;

    return buf_size;

}

static int adx_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf0 = avpkt->data;

    int buf_size        = avpkt->size;

    ADXContext *c       = avctx->priv_data;

    int16_t *samples    = data;

    const uint8_t *buf  = buf0;

    int rest            = buf_size;



    if (!c->header_parsed) {

        int hdrsize = adx_decode_header(avctx, buf, rest);

        if (!hdrsize)

            return -1;

        c->header_parsed = 1;

        buf  += hdrsize;

        rest -= hdrsize;

    }



    /* 18 bytes of data are expanded into 32*2 bytes of audio,

       so guard against buffer overflows */

    if (rest / 18 > *data_size / 64)

        rest = (*data_size / 64) * 18;



    if (c->in_temp) {

        int copysize = 18 * avctx->channels - c->in_temp;

        memcpy(c->dec_temp + c->in_temp, buf, copysize);

        rest -= copysize;

        buf  += copysize;

        if (avctx->channels == 1) {

            adx_decode(samples, c->dec_temp, c->prev);

            samples += 32;

        } else {

            adx_decode_stereo(samples, c->dec_temp, c->prev);

            samples += 32*2;

        }

    }



    if (avctx->channels == 1) {

        while (rest >= 18) {

            adx_decode(samples, buf, c->prev);

            rest    -= 18;

            buf     += 18;

            samples += 32;

        }

    } else {

        while (rest >= 18 * 2) {

            adx_decode_stereo(samples, buf, c->prev);

            rest    -= 18 * 2;

            buf     += 18 * 2;

            samples += 32 * 2;

        }

    }



    c->in_temp = rest;

    if (rest) {

        memcpy(c->dec_temp, buf, rest);

        buf += rest;

    }

    *data_size = (uint8_t*)samples - (uint8_t*)data;

    return buf - buf0;

}

static void decode_v4_vector(CinepakEncContext *s, AVPicture *sub_pict, int *v4_vector, strip_info *info)

{

    int i, x, y, entry_size = s->pix_fmt == AV_PIX_FMT_YUV420P ? 6 : 4;



    for(i = y = 0; y < 4; y += 2) {

        for(x = 0; x < 4; x += 2, i++) {

            sub_pict->data[0][x   +     y*sub_pict->linesize[0]] = info->v4_codebook[v4_vector[i]*entry_size];

            sub_pict->data[0][x+1 +     y*sub_pict->linesize[0]] = info->v4_codebook[v4_vector[i]*entry_size+1];

            sub_pict->data[0][x   + (y+1)*sub_pict->linesize[0]] = info->v4_codebook[v4_vector[i]*entry_size+2];

            sub_pict->data[0][x+1 + (y+1)*sub_pict->linesize[0]] = info->v4_codebook[v4_vector[i]*entry_size+3];



            if(s->pix_fmt == AV_PIX_FMT_YUV420P) {

                sub_pict->data[1][(x>>1) + (y>>1)*sub_pict->linesize[1]] = info->v4_codebook[v4_vector[i]*entry_size+4];

                sub_pict->data[2][(x>>1) + (y>>1)*sub_pict->linesize[2]] = info->v4_codebook[v4_vector[i]*entry_size+5];

            }

        }

    }

}

static void rv30_loop_filter(RV34DecContext *r, int row)

{

    MpegEncContext *s = &r->s;

    int mb_pos, mb_x;

    int i, j, k;

    uint8_t *Y, *C;

    int loc_lim, cur_lim, left_lim = 0, top_lim = 0;



