static int vaapi_encode_issue(AVCodecContext *avctx,

                              VAAPIEncodePicture *pic)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    VAAPIEncodeSlice *slice;

    VAStatus vas;

    int err, i;

    char data[MAX_PARAM_BUFFER_SIZE];

    size_t bit_len;



    av_log(avctx, AV_LOG_DEBUG, "Issuing encode for pic %"PRId64"/%"PRId64" "

           "as type %s.\n", pic->display_order, pic->encode_order,

           picture_type_name[pic->type]);

    if (pic->nb_refs == 0) {

        av_log(avctx, AV_LOG_DEBUG, "No reference pictures.\n");

    } else {

        av_log(avctx, AV_LOG_DEBUG, "Refers to:");

        for (i = 0; i < pic->nb_refs; i++) {

            av_log(avctx, AV_LOG_DEBUG, " %"PRId64"/%"PRId64,

                   pic->refs[i]->display_order, pic->refs[i]->encode_order);

        }

        av_log(avctx, AV_LOG_DEBUG, ".\n");

    }



    av_assert0(pic->input_available && !pic->encode_issued);

    for (i = 0; i < pic->nb_refs; i++) {

        av_assert0(pic->refs[i]);

        // If we are serialised then the references must have already

        // completed.  If not, they must have been issued but need not

        // have completed yet.

        if (ctx->issue_mode == ISSUE_MODE_SERIALISE_EVERYTHING)

            av_assert0(pic->refs[i]->encode_complete);

        else

            av_assert0(pic->refs[i]->encode_issued);

    }



    av_log(avctx, AV_LOG_DEBUG, "Input surface is %#x.\n", pic->input_surface);



    pic->recon_image = av_frame_alloc();

    if (!pic->recon_image) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    err = av_hwframe_get_buffer(ctx->recon_frames_ref, pic->recon_image, 0);

    if (err < 0) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    pic->recon_surface = (VASurfaceID)(uintptr_t)pic->recon_image->data[3];

    av_log(avctx, AV_LOG_DEBUG, "Recon surface is %#x.\n", pic->recon_surface);



    pic->output_buffer_ref = av_buffer_pool_get(ctx->output_buffer_pool);

    if (!pic->output_buffer_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    pic->output_buffer = (VABufferID)(uintptr_t)pic->output_buffer_ref->data;

    av_log(avctx, AV_LOG_DEBUG, "Output buffer is %#x.\n",

           pic->output_buffer);



    if (ctx->codec->picture_params_size > 0) {

        pic->codec_picture_params = av_malloc(ctx->codec->picture_params_size);

        if (!pic->codec_picture_params)

            goto fail;

        memcpy(pic->codec_picture_params, ctx->codec_picture_params,

               ctx->codec->picture_params_size);

    } else {

        av_assert0(!ctx->codec_picture_params);

    }



    pic->nb_param_buffers = 0;



    if (pic->encode_order == 0) {

        // Global parameter buffers are set on the first picture only.



        for (i = 0; i < ctx->nb_global_params; i++) {

            err = vaapi_encode_make_param_buffer(avctx, pic,

                                                 VAEncMiscParameterBufferType,

                                                 (char*)ctx->global_params[i],

                                                 ctx->global_params_size[i]);

            if (err < 0)

                goto fail;

        }

    }



    if (pic->type == PICTURE_TYPE_IDR && ctx->codec->init_sequence_params) {

        err = vaapi_encode_make_param_buffer(avctx, pic,

                                             VAEncSequenceParameterBufferType,

                                             ctx->codec_sequence_params,

                                             ctx->codec->sequence_params_size);

        if (err < 0)

            goto fail;

    }



    if (ctx->codec->init_picture_params) {

        err = ctx->codec->init_picture_params(avctx, pic);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Failed to initialise picture "

                   "parameters: %d.\n", err);

            goto fail;

        }

        err = vaapi_encode_make_param_buffer(avctx, pic,

                                             VAEncPictureParameterBufferType,

                                             pic->codec_picture_params,

                                             ctx->codec->picture_params_size);

        if (err < 0)

            goto fail;

    }



    if (pic->type == PICTURE_TYPE_IDR) {

        if (ctx->va_packed_headers & VA_ENC_PACKED_HEADER_SEQUENCE &&

            ctx->codec->write_sequence_header) {

            bit_len = 8 * sizeof(data);

            err = ctx->codec->write_sequence_header(avctx, data, &bit_len);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to write per-sequence "

                       "header: %d.\n", err);

                goto fail;

            }

            err = vaapi_encode_make_packed_header(avctx, pic,

                                                  ctx->codec->sequence_header_type,

                                                  data, bit_len);

            if (err < 0)

                goto fail;

        }

    }



    if (ctx->va_packed_headers & VA_ENC_PACKED_HEADER_PICTURE &&

        ctx->codec->write_picture_header) {

        bit_len = 8 * sizeof(data);

        err = ctx->codec->write_picture_header(avctx, pic, data, &bit_len);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Failed to write per-picture "

                   "header: %d.\n", err);

            goto fail;

        }

        err = vaapi_encode_make_packed_header(avctx, pic,

                                              ctx->codec->picture_header_type,

                                              data, bit_len);

        if (err < 0)

            goto fail;

    }



    if (ctx->codec->write_extra_buffer) {

        for (i = 0;; i++) {

            size_t len = sizeof(data);

            int type;

            err = ctx->codec->write_extra_buffer(avctx, pic, i, &type,

                                                 data, &len);

            if (err == AVERROR_EOF)

                break;

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to write extra "

                       "buffer %d: %d.\n", i, err);

                goto fail;

            }



            err = vaapi_encode_make_param_buffer(avctx, pic, type,

                                                 data, len);

            if (err < 0)

                goto fail;

        }

    }



    if (ctx->va_packed_headers & VA_ENC_PACKED_HEADER_MISC &&

        ctx->codec->write_extra_header) {

        for (i = 0;; i++) {

            int type;

            bit_len = 8 * sizeof(data);

            err = ctx->codec->write_extra_header(avctx, pic, i, &type,

                                                 data, &bit_len);

            if (err == AVERROR_EOF)

                break;

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to write extra "

                       "header %d: %d.\n", i, err);

                goto fail;

            }



            err = vaapi_encode_make_packed_header(avctx, pic, type,

                                                  data, bit_len);

            if (err < 0)

                goto fail;

        }

    }



    av_assert0(pic->nb_slices <= MAX_PICTURE_SLICES);

    for (i = 0; i < pic->nb_slices; i++) {

        slice = av_mallocz(sizeof(*slice));

        if (!slice) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        slice->index = i;

        pic->slices[i] = slice;



        if (ctx->codec->slice_params_size > 0) {

            slice->codec_slice_params = av_mallocz(ctx->codec->slice_params_size);

            if (!slice->codec_slice_params) {

                err = AVERROR(ENOMEM);

                goto fail;

            }

        }



        if (ctx->codec->init_slice_params) {

            err = ctx->codec->init_slice_params(avctx, pic, slice);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to initalise slice "

                       "parameters: %d.\n", err);

                goto fail;

            }

        }



        if (ctx->va_packed_headers & VA_ENC_PACKED_HEADER_SLICE &&

            ctx->codec->write_slice_header) {

            bit_len = 8 * sizeof(data);

            err = ctx->codec->write_slice_header(avctx, pic, slice,

                                                 data, &bit_len);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to write per-slice "

                       "header: %d.\n", err);

                goto fail;

            }

            err = vaapi_encode_make_packed_header(avctx, pic,

                                                  ctx->codec->slice_header_type,

                                                  data, bit_len);

            if (err < 0)

                goto fail;

        }



        if (ctx->codec->init_slice_params) {

            err = vaapi_encode_make_param_buffer(avctx, pic,

                                                 VAEncSliceParameterBufferType,

                                                 slice->codec_slice_params,

                                                 ctx->codec->slice_params_size);

            if (err < 0)

                goto fail;

        }

    }



    vas = vaBeginPicture(ctx->hwctx->display, ctx->va_context,

                         pic->input_surface);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to begin picture encode issue: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail_with_picture;

    }



    vas = vaRenderPicture(ctx->hwctx->display, ctx->va_context,

                          pic->param_buffers, pic->nb_param_buffers);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to upload encode parameters: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail_with_picture;

    }



    vas = vaEndPicture(ctx->hwctx->display, ctx->va_context);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to end picture encode issue: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        // vaRenderPicture() has been called here, so we should not destroy

        // the parameter buffers unless separate destruction is required.

        if (ctx->hwctx->driver_quirks &

            AV_VAAPI_DRIVER_QUIRK_RENDER_PARAM_BUFFERS)

            goto fail;

        else

            goto fail_at_end;

    }



    if (ctx->hwctx->driver_quirks &

        AV_VAAPI_DRIVER_QUIRK_RENDER_PARAM_BUFFERS) {

        for (i = 0; i < pic->nb_param_buffers; i++) {

            vas = vaDestroyBuffer(ctx->hwctx->display,

                                  pic->param_buffers[i]);

            if (vas != VA_STATUS_SUCCESS) {

                av_log(avctx, AV_LOG_ERROR, "Failed to destroy "

                       "param buffer %#x: %d (%s).\n",

                       pic->param_buffers[i], vas, vaErrorStr(vas));

                // And ignore.

            }

        }

    }



    pic->encode_issued = 1;



    if (ctx->issue_mode == ISSUE_MODE_SERIALISE_EVERYTHING)

        return vaapi_encode_wait(avctx, pic);

    else

        return 0;



fail_with_picture:

    vaEndPicture(ctx->hwctx->display, ctx->va_context);

fail:

    for(i = 0; i < pic->nb_param_buffers; i++)

        vaDestroyBuffer(ctx->hwctx->display, pic->param_buffers[i]);

fail_at_end:

    av_freep(&pic->codec_picture_params);

    av_frame_free(&pic->recon_image);



    return err;

}

static int sdl_write_header(AVFormatContext *s)

{

    SDLContext *sdl = s->priv_data;

    AVStream *st = s->streams[0];

    AVCodecContext *encctx = st->codec;

    AVRational sar, dar; /* sample and display aspect ratios */

    int i, ret;

    int flags = SDL_SWSURFACE | sdl->window_fullscreen ? SDL_FULLSCREEN : 0;



    if (!sdl->window_title)

        sdl->window_title = av_strdup(s->filename);

    if (!sdl->icon_title)

        sdl->icon_title = av_strdup(sdl->window_title);



    if (SDL_WasInit(SDL_INIT_VIDEO)) {

        av_log(s, AV_LOG_ERROR,

               "SDL video subsystem was already inited, aborting\n");

        sdl->sdl_was_already_inited = 1;

        ret = AVERROR(EINVAL);

        goto fail;

    }



    if (SDL_Init(SDL_INIT_VIDEO) != 0) {

        av_log(s, AV_LOG_ERROR, "Unable to initialize SDL: %s\n", SDL_GetError());

        ret = AVERROR(EINVAL);

        goto fail;

    }



    if (   s->nb_streams > 1

        || encctx->codec_type != AVMEDIA_TYPE_VIDEO

        || encctx->codec_id   != AV_CODEC_ID_RAWVIDEO) {

        av_log(s, AV_LOG_ERROR, "Only supports one rawvideo stream\n");

        ret = AVERROR(EINVAL);

        goto fail;

    }



    for (i = 0; sdl_overlay_pix_fmt_map[i].pix_fmt != AV_PIX_FMT_NONE; i++) {

        if (sdl_overlay_pix_fmt_map[i].pix_fmt == encctx->pix_fmt) {

            sdl->overlay_fmt = sdl_overlay_pix_fmt_map[i].overlay_fmt;

            break;

        }

    }



    if (!sdl->overlay_fmt) {

        av_log(s, AV_LOG_ERROR,

               "Unsupported pixel format '%s', choose one of yuv420p, yuyv422, or uyvy422\n",

               av_get_pix_fmt_name(encctx->pix_fmt));

        ret = AVERROR(EINVAL);

        goto fail;

    }



    /* compute overlay width and height from the codec context information */

    sar = st->sample_aspect_ratio.num ? st->sample_aspect_ratio : (AVRational){ 1, 1 };

    dar = av_mul_q(sar, (AVRational){ encctx->width, encctx->height });



    /* we suppose the screen has a 1/1 sample aspect ratio */

    if (sdl->window_width && sdl->window_height) {

        /* fit in the window */

        if (av_cmp_q(dar, (AVRational){ sdl->window_width, sdl->window_height }) > 0) {

            /* fit in width */

            sdl->overlay_width  = sdl->window_width;

            sdl->overlay_height = av_rescale(sdl->overlay_width, dar.den, dar.num);

        } else {

            /* fit in height */

            sdl->overlay_height = sdl->window_height;

            sdl->overlay_width  = av_rescale(sdl->overlay_height, dar.num, dar.den);

        }

    } else {

        if (sar.num > sar.den) {

            sdl->overlay_width  = encctx->width;

            sdl->overlay_height = av_rescale(sdl->overlay_width, dar.den, dar.num);

        } else {

            sdl->overlay_height = encctx->height;

            sdl->overlay_width  = av_rescale(sdl->overlay_height, dar.num, dar.den);

        }

        sdl->window_width  = sdl->overlay_width;

        sdl->window_height = sdl->overlay_height;

    }

    sdl->overlay_x = (sdl->window_width  - sdl->overlay_width ) / 2;

    sdl->overlay_y = (sdl->window_height - sdl->overlay_height) / 2;



    SDL_WM_SetCaption(sdl->window_title, sdl->icon_title);

    sdl->surface = SDL_SetVideoMode(sdl->window_width, sdl->window_height,

                                    24, flags);

    if (!sdl->surface) {

        av_log(s, AV_LOG_ERROR, "Unable to set video mode: %s\n", SDL_GetError());

        ret = AVERROR(EINVAL);

        goto fail;

    }



    sdl->overlay = SDL_CreateYUVOverlay(encctx->width, encctx->height,

                                        sdl->overlay_fmt, sdl->surface);

    if (!sdl->overlay || sdl->overlay->pitches[0] < encctx->width) {

        av_log(s, AV_LOG_ERROR,

               "SDL does not support an overlay with size of %dx%d pixels\n",

               encctx->width, encctx->height);

        ret = AVERROR(EINVAL);

        goto fail;

    }



    av_log(s, AV_LOG_VERBOSE, "w:%d h:%d fmt:%s sar:%d/%d -> w:%d h:%d\n",

           encctx->width, encctx->height, av_get_pix_fmt_name(encctx->pix_fmt), sar.num, sar.den,

           sdl->overlay_width, sdl->overlay_height);

    return 0;



fail:

    sdl_write_trailer(s);

    return ret;

}

static int vaapi_decode_make_config(AVCodecContext *avctx)

{

    VAAPIDecodeContext *ctx = avctx->internal->hwaccel_priv_data;



    AVVAAPIHWConfig       *hwconfig    = NULL;

    AVHWFramesConstraints *constraints = NULL;

    VAStatus vas;

    int err, i, j;

    const AVCodecDescriptor *codec_desc;

    VAProfile profile, *profile_list = NULL;

    int profile_count, exact_match, alt_profile;

    const AVPixFmtDescriptor *sw_desc, *desc;



    codec_desc = avcodec_descriptor_get(avctx->codec_id);

    if (!codec_desc) {

        err = AVERROR(EINVAL);

        goto fail;

    }



    profile_count = vaMaxNumProfiles(ctx->hwctx->display);

    profile_list  = av_malloc_array(profile_count,

                                    sizeof(VAProfile));

    if (!profile_list) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    vas = vaQueryConfigProfiles(ctx->hwctx->display,

                                profile_list, &profile_count);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to query profiles: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(ENOSYS);

        goto fail;

    }



    profile = VAProfileNone;

    exact_match = 0;



    for (i = 0; i < FF_ARRAY_ELEMS(vaapi_profile_map); i++) {

        int profile_match = 0;

        if (avctx->codec_id != vaapi_profile_map[i].codec_id)

            continue;

        if (avctx->profile == vaapi_profile_map[i].codec_profile ||

            vaapi_profile_map[i].codec_profile == FF_PROFILE_UNKNOWN)

            profile_match = 1;

        profile = vaapi_profile_map[i].va_profile;

        for (j = 0; j < profile_count; j++) {

            if (profile == profile_list[j]) {

                exact_match = profile_match;

                break;

            }

        }

        if (j < profile_count) {

            if (exact_match)

                break;

            alt_profile = vaapi_profile_map[i].codec_profile;

        }

    }

    av_freep(&profile_list);



    if (profile == VAProfileNone) {

        av_log(avctx, AV_LOG_ERROR, "No support for codec %s "

               "profile %d.\n", codec_desc->name, avctx->profile);

        err = AVERROR(ENOSYS);

        goto fail;

    }

    if (!exact_match) {

        if (avctx->hwaccel_flags &

            AV_HWACCEL_FLAG_ALLOW_PROFILE_MISMATCH) {

            av_log(avctx, AV_LOG_VERBOSE, "Codec %s profile %d not "

                   "supported for hardware decode.\n",

                   codec_desc->name, avctx->profile);

            av_log(avctx, AV_LOG_WARNING, "Using possibly-"

                   "incompatible profile %d instead.\n",

                   alt_profile);

        } else {

            av_log(avctx, AV_LOG_VERBOSE, "Codec %s profile %d not "

                   "supported for hardware decode.\n",

                   codec_desc->name, avctx->profile);

            err = AVERROR(EINVAL);

            goto fail;

        }

    }



    ctx->va_profile    = profile;

    ctx->va_entrypoint = VAEntrypointVLD;



    vas = vaCreateConfig(ctx->hwctx->display, ctx->va_profile,

                         ctx->va_entrypoint, NULL, 0,

                         &ctx->va_config);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create decode "

               "configuration: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    hwconfig = av_hwdevice_hwconfig_alloc(avctx->hw_device_ctx ?

                                          avctx->hw_device_ctx :

                                          ctx->frames->device_ref);

    if (!hwconfig) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    hwconfig->config_id = ctx->va_config;



    constraints =

        av_hwdevice_get_hwframe_constraints(avctx->hw_device_ctx ?

                                            avctx->hw_device_ctx :

                                            ctx->frames->device_ref,

                                            hwconfig);

    if (!constraints) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    if (avctx->coded_width  < constraints->min_width  ||

        avctx->coded_height < constraints->min_height ||

        avctx->coded_width  > constraints->max_width  ||

        avctx->coded_height > constraints->max_height) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not support image "

               "size %dx%d (constraints: width %d-%d height %d-%d).\n",

               avctx->coded_width, avctx->coded_height,

               constraints->min_width,  constraints->max_width,

               constraints->min_height, constraints->max_height);

        err = AVERROR(EINVAL);

        goto fail;

    }

    if (!constraints->valid_sw_formats ||

        constraints->valid_sw_formats[0] == AV_PIX_FMT_NONE) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not offer any "

               "usable surface formats.\n");

        err = AVERROR(EINVAL);

        goto fail;

    }



    // Find the first format in the list which matches the expected

    // bit depth and subsampling.  If none are found (this can happen

    // when 10-bit streams are decoded to 8-bit surfaces, for example)

    // then just take the first format on the list.

    ctx->surface_format = constraints->valid_sw_formats[0];

    sw_desc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);

    for (i = 0; constraints->valid_sw_formats[i] != AV_PIX_FMT_NONE; i++) {

        desc = av_pix_fmt_desc_get(constraints->valid_sw_formats[i]);

        if (desc->nb_components != sw_desc->nb_components ||

            desc->log2_chroma_w != sw_desc->log2_chroma_w ||

            desc->log2_chroma_h != sw_desc->log2_chroma_h)

            continue;

        for (j = 0; j < desc->nb_components; j++) {

            if (desc->comp[j].depth != sw_desc->comp[j].depth)

                break;

        }

        if (j < desc->nb_components)

            continue;

        ctx->surface_format = constraints->valid_sw_formats[i];

        break;

    }



    // Start with at least four surfaces.

    ctx->surface_count = 4;

    // Add per-codec number of surfaces used for storing reference frames.

    switch (avctx->codec_id) {

    case AV_CODEC_ID_H264:

    case AV_CODEC_ID_HEVC:

        ctx->surface_count += 16;

        break;

    case AV_CODEC_ID_VP9:

        ctx->surface_count += 8;

        break;

    case AV_CODEC_ID_VP8:

        ctx->surface_count += 3;

        break;

    default:

        ctx->surface_count += 2;

    }

    // Add an additional surface per thread is frame threading is enabled.

    if (avctx->active_thread_type & FF_THREAD_FRAME)

        ctx->surface_count += avctx->thread_count;



    av_hwframe_constraints_free(&constraints);

    av_freep(&hwconfig);



    return 0;



fail:

    av_hwframe_constraints_free(&constraints);

    av_freep(&hwconfig);

    if (ctx->va_config != VA_INVALID_ID) {

        vaDestroyConfig(ctx->hwctx->display, ctx->va_config);

        ctx->va_config = VA_INVALID_ID;

    }

    av_freep(&profile_list);

    return err;

}

av_cold int ff_vaapi_encode_init(AVCodecContext *avctx,

                                 const VAAPIEncodeType *type)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    AVVAAPIFramesContext *recon_hwctx = NULL;

    AVVAAPIHWConfig *hwconfig = NULL;

    AVHWFramesConstraints *constraints = NULL;

    enum AVPixelFormat recon_format;

    VAStatus vas;

    int err, i;



    if (!avctx->hw_frames_ctx) {

        av_log(avctx, AV_LOG_ERROR, "A hardware frames reference is "

               "required to associate the encoding device.\n");

        return AVERROR(EINVAL);

    }



    ctx->codec = type;

    ctx->codec_options = ctx->codec_options_data;



    ctx->va_config  = VA_INVALID_ID;

    ctx->va_context = VA_INVALID_ID;



    ctx->priv_data = av_mallocz(type->priv_data_size);

    if (!ctx->priv_data) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    ctx->input_frames_ref = av_buffer_ref(avctx->hw_frames_ctx);

    if (!ctx->input_frames_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->input_frames = (AVHWFramesContext*)ctx->input_frames_ref->data;



    ctx->device_ref = av_buffer_ref(ctx->input_frames->device_ref);

    if (!ctx->device_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->device = (AVHWDeviceContext*)ctx->device_ref->data;

    ctx->hwctx = ctx->device->hwctx;



    err = ctx->codec->init(avctx);

    if (err < 0)

        goto fail;



    err = vaapi_encode_check_config(avctx);

    if (err < 0)

        goto fail;



    vas = vaCreateConfig(ctx->hwctx->display,

                         ctx->va_profile, ctx->va_entrypoint,

                         ctx->config_attributes, ctx->nb_config_attributes,

                         &ctx->va_config);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create encode pipeline "

               "configuration: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    hwconfig = av_hwdevice_hwconfig_alloc(ctx->device_ref);

    if (!hwconfig) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    hwconfig->config_id = ctx->va_config;



    constraints = av_hwdevice_get_hwframe_constraints(ctx->device_ref,

                                                      hwconfig);

    if (!constraints) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    // Probably we can use the input surface format as the surface format

    // of the reconstructed frames.  If not, we just pick the first (only?)

    // format in the valid list and hope that it all works.

    recon_format = AV_PIX_FMT_NONE;

    if (constraints->valid_sw_formats) {

        for (i = 0; constraints->valid_sw_formats[i] != AV_PIX_FMT_NONE; i++) {

            if (ctx->input_frames->sw_format ==

                constraints->valid_sw_formats[i]) {

                recon_format = ctx->input_frames->sw_format;

                break;

            }

        }

        if (recon_format == AV_PIX_FMT_NONE) {

            // No match.  Just use the first in the supported list and

            // hope for the best.

            recon_format = constraints->valid_sw_formats[0];

        }

    } else {

        // No idea what to use; copy input format.

        recon_format = ctx->input_frames->sw_format;

    }

    av_log(avctx, AV_LOG_DEBUG, "Using %s as format of "

           "reconstructed frames.\n", av_get_pix_fmt_name(recon_format));



    if (ctx->aligned_width  < constraints->min_width  ||

        ctx->aligned_height < constraints->min_height ||

        ctx->aligned_width  > constraints->max_width ||

        ctx->aligned_height > constraints->max_height) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not support encoding at "

               "size %dx%d (constraints: width %d-%d height %d-%d).\n",

               ctx->aligned_width, ctx->aligned_height,

               constraints->min_width,  constraints->max_width,

               constraints->min_height, constraints->max_height);

        err = AVERROR(EINVAL);

        goto fail;

    }



    av_freep(&hwconfig);

    av_hwframe_constraints_free(&constraints);



    ctx->recon_frames_ref = av_hwframe_ctx_alloc(ctx->device_ref);

    if (!ctx->recon_frames_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->recon_frames = (AVHWFramesContext*)ctx->recon_frames_ref->data;



    ctx->recon_frames->format    = AV_PIX_FMT_VAAPI;

    ctx->recon_frames->sw_format = recon_format;

    ctx->recon_frames->width     = ctx->aligned_width;

    ctx->recon_frames->height    = ctx->aligned_height;

    ctx->recon_frames->initial_pool_size = ctx->nb_recon_frames;



    err = av_hwframe_ctx_init(ctx->recon_frames_ref);

    if (err < 0) {

        av_log(avctx, AV_LOG_ERROR, "Failed to initialise reconstructed "

               "frame context: %d.\n", err);

        goto fail;

    }

    recon_hwctx = ctx->recon_frames->hwctx;



    vas = vaCreateContext(ctx->hwctx->display, ctx->va_config,

                          ctx->aligned_width, ctx->aligned_height,

                          VA_PROGRESSIVE,

                          recon_hwctx->surface_ids,

                          recon_hwctx->nb_surfaces,

                          &ctx->va_context);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create encode pipeline "

               "context: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    ctx->input_order  = 0;

    ctx->output_delay = avctx->max_b_frames;

    ctx->decode_delay = 1;

    ctx->output_order = - ctx->output_delay - 1;



    if (ctx->codec->sequence_params_size > 0) {

        ctx->codec_sequence_params =

            av_mallocz(ctx->codec->sequence_params_size);

        if (!ctx->codec_sequence_params) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }

    if (ctx->codec->picture_params_size > 0) {

        ctx->codec_picture_params =

            av_mallocz(ctx->codec->picture_params_size);

        if (!ctx->codec_picture_params) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }



    if (ctx->codec->init_sequence_params) {

        err = ctx->codec->init_sequence_params(avctx);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Codec sequence initialisation "

                   "failed: %d.\n", err);

            goto fail;

        }

    }



    ctx->output_buffer_pool =

        av_buffer_pool_init2(sizeof(VABufferID), avctx,

                             &vaapi_encode_alloc_output_buffer, NULL);

    if (!ctx->output_buffer_pool) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    // All I are IDR for now.

    ctx->i_per_idr = 0;

    ctx->p_per_i = ((avctx->gop_size + avctx->max_b_frames) /

                    (avctx->max_b_frames + 1));

    ctx->b_per_p = avctx->max_b_frames;



    // This should be configurable somehow.  (Needs testing on a machine

    // where it actually overlaps properly, though.)

    ctx->issue_mode = ISSUE_MODE_MAXIMISE_THROUGHPUT;



    return 0;



fail:

    av_freep(&hwconfig);

    av_hwframe_constraints_free(&constraints);

    ff_vaapi_encode_close(avctx);

    return err;

}

static int parse(AVCodecParserContext *ctx,

                 AVCodecContext *avctx,

                 const uint8_t **out_data, int *out_size,

                 const uint8_t *data, int size)

{

    VP9ParseContext *s = ctx->priv_data;

    int full_size = size;

    int marker;



    if (size <= 0) {

        *out_size = 0;

        *out_data = data;



        return 0;

    }



    if (s->n_frames > 0) {

        *out_data = data;

        *out_size = s->size[--s->n_frames];

        parse_frame(ctx, *out_data, *out_size);



        return s->n_frames > 0 ? *out_size : size /* i.e. include idx tail */;

    }



    marker = data[size - 1];

    if ((marker & 0xe0) == 0xc0) {

        int nbytes = 1 + ((marker >> 3) & 0x3);

        int n_frames = 1 + (marker & 0x7), idx_sz = 2 + n_frames * nbytes;



        if (size >= idx_sz && data[size - idx_sz] == marker) {

            const uint8_t *idx = data + size + 1 - idx_sz;

            int first = 1;



            switch (nbytes) {

#define case_n(a, rd) \

            case a: \

                while (n_frames--) { \

                    unsigned sz = rd; \

                    idx += a; \

                    if (sz > size) { \

                        s->n_frames = 0; \

                        *out_size = size; \

                        *out_data = data; \

                        av_log(avctx, AV_LOG_ERROR, \

                               "Superframe packet size too big: %u > %d\n", \

                               sz, size); \

                        return full_size; \

                    } \

                    if (first) { \

                        first = 0; \

                        *out_data = data; \

                        *out_size = sz; \

                        s->n_frames = n_frames; \

                    } else { \

                        s->size[n_frames] = sz; \

                    } \

                    data += sz; \

                    size -= sz; \

                } \

                parse_frame(ctx, *out_data, *out_size); \

                return *out_size



                case_n(1, *idx);

                case_n(2, AV_RL16(idx));

                case_n(3, AV_RL24(idx));

                case_n(4, AV_RL32(idx));

            }

        }

    }



    *out_data = data;

    *out_size = size;

    parse_frame(ctx, data, size);



    return size;

}

static int ws_snd_decode_frame(AVCodecContext *avctx,

                void *data, int *data_size,

                AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

//    WSSNDContext *c = avctx->priv_data;



    int in_size, out_size;

    int sample = 128;

    int i;

    uint8_t *samples = data;



    if (!buf_size)

        return 0;



    out_size = AV_RL16(&buf[0]);

    in_size = AV_RL16(&buf[2]);

    buf += 4;



    if (out_size > *data_size) {

        av_log(avctx, AV_LOG_ERROR, "Frame is too large to fit in buffer\n");

        return -1;

    }

    if (in_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "Frame data is larger than input buffer\n");

        return -1;

    }



    *data_size = out_size;



    if (in_size == out_size) {

        for (i = 0; i < out_size; i++)

            *samples++ = *buf++;

        return buf_size;

    }



    while (out_size > 0) {

        int code;

        uint8_t count;

        code = (*buf) >> 6;

        count = (*buf) & 0x3F;

        buf++;

        switch(code) {

        case 0: /* ADPCM 2-bit */

            for (count++; count > 0; count--) {

                code = *buf++;

                sample += ws_adpcm_2bit[code & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_2bit[(code >> 2) & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_2bit[(code >> 4) & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_2bit[(code >> 6) & 0x3];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                out_size -= 4;

            }

            break;

        case 1: /* ADPCM 4-bit */

            for (count++; count > 0; count--) {

                code = *buf++;

                sample += ws_adpcm_4bit[code & 0xF];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                sample += ws_adpcm_4bit[code >> 4];

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                out_size -= 2;

            }

            break;

        case 2: /* no compression */

            if (count & 0x20) { /* big delta */

                int8_t t;

                t = count;

                t <<= 3;

                sample += t >> 3;

                sample = av_clip_uint8(sample);

                *samples++ = sample;

                out_size--;

            } else { /* copy */

                for (count++; count > 0; count--) {

                    *samples++ = *buf++;

                    out_size--;

                }

                sample = buf[-1];

            }

            break;

        default: /* run */

            for(count++; count > 0; count--) {

                *samples++ = sample;

                out_size--;

            }

        }

    }



    return buf_size;

}

static int vp9_superframe_filter(AVBSFContext *ctx, AVPacket *out)

{

    BitstreamContext bc;

    VP9BSFContext *s = ctx->priv_data;

    AVPacket *in;

    int res, invisible, profile, marker, uses_superframe_syntax = 0, n;



    res = ff_bsf_get_packet(ctx, &in);

    if (res < 0)

        return res;



    marker = in->data[in->size - 1];

    if ((marker & 0xe0) == 0xc0) {

        int nbytes = 1 + ((marker >> 3) & 0x3);

        int n_frames = 1 + (marker & 0x7), idx_sz = 2 + n_frames * nbytes;



        uses_superframe_syntax = in->size >= idx_sz && in->data[in->size - idx_sz] == marker;

    }



    res = bitstream_init8(&bc, in->data, in->size);

    if (res < 0)

        goto done;



    bitstream_read(&bc, 2); // frame marker

    profile  = bitstream_read(&bc, 1);

    profile |= bitstream_read(&bc, 1) << 1;

    if (profile == 3)

        profile += bitstream_read(&bc, 1);



    if (bitstream_read(&bc, 1)) {

        invisible = 0;

    } else {

        bitstream_read(&bc, 1); // keyframe

        invisible = !bitstream_read(&bc, 1);

    }



    if (uses_superframe_syntax && s->n_cache > 0) {

        av_log(ctx, AV_LOG_ERROR,

               "Mixing of superframe syntax and naked VP9 frames not supported");

        res = AVERROR(ENOSYS);

        goto done;

    } else if ((!invisible || uses_superframe_syntax) && !s->n_cache) {

        // passthrough

        av_packet_move_ref(out, in);

        goto done;

    } else if (s->n_cache + 1 >= MAX_CACHE) {

        av_log(ctx, AV_LOG_ERROR,

               "Too many invisible frames");

        res = AVERROR_INVALIDDATA;

        goto done;

    }



    s->cache[s->n_cache++] = in;

    in                     = NULL;

    if (invisible) {

        res = AVERROR(EAGAIN);

        goto done;

    }

    av_assert0(s->n_cache > 0);



    // build superframe

    if ((res = merge_superframe(s->cache, s->n_cache, out)) < 0)

        goto done;



    res = av_packet_copy_props(out, s->cache[s->n_cache - 1]);

    if (res < 0)

        goto done;



    for (n = 0; n < s->n_cache; n++)

        av_packet_free(&s->cache[n]);

    s->n_cache = 0;



done:

    if (res < 0)

        av_packet_unref(out);

    av_packet_free(&in);

    return res;

}

static inline int read_line(AVFormatContext *s, char *rbuf, const int rbufsize,

                            int *rbuflen)

{

    RTSPState *rt = s->priv_data;

    int idx       = 0;

    int ret       = 0;

    *rbuflen      = 0;



    do {

        ret = ffurl_read_complete(rt->rtsp_hd, rbuf + idx, 1);

        if (ret < 0)

            return ret;

        if (rbuf[idx] == '\r') {

            /* Ignore */

        } else if (rbuf[idx] == '\n') {

            rbuf[idx] = '\0';

            *rbuflen  = idx;

            return 0;

        } else

            idx++;

    } while (idx < rbufsize);

    av_log(s, AV_LOG_ERROR, "Message too long\n");

    return AVERROR(EIO);

}

