bool bdrv_all_can_snapshot(BlockDriverState **first_bad_bs)

{

    bool ok = true;

    BlockDriverState *bs;

    BdrvNextIterator it;



    for (bs = bdrv_first(&it); bs; bs = bdrv_next(&it)) {

        AioContext *ctx = bdrv_get_aio_context(bs);



        aio_context_acquire(ctx);

        if (bdrv_is_inserted(bs) && !bdrv_is_read_only(bs)) {

            ok = bdrv_can_snapshot(bs);

        }

        aio_context_release(ctx);

        if (!ok) {


            goto fail;

        }

    }



fail:

    *first_bad_bs = bs;

    return ok;

}

bool vfio_blacklist_opt_rom(VFIOPCIDevice *vdev)

{

    PCIDevice *pdev = &vdev->pdev;

    uint16_t vendor_id, device_id;

    int count = 0;



    vendor_id = pci_get_word(pdev->config + PCI_VENDOR_ID);

    device_id = pci_get_word(pdev->config + PCI_DEVICE_ID);



    while (count < ARRAY_SIZE(romblacklist)) {

        if (romblacklist[count].vendor_id == vendor_id &&

            romblacklist[count].device_id == device_id) {

                return true;

        }

        count++;

    }



    return false;

}

int bdrv_flush_all(void)

{

    BlockDriverState *bs = NULL;

    int result = 0;



    while ((bs = bdrv_next(bs))) {

        AioContext *aio_context = bdrv_get_aio_context(bs);

        int ret;



        aio_context_acquire(aio_context);

        ret = bdrv_flush(bs);

        if (ret < 0 && !result) {

            result = ret;

        }

        aio_context_release(aio_context);

    }



    return result;

}

bool iommu_dma_memory_valid(DMAContext *dma, dma_addr_t addr, dma_addr_t len,

                            DMADirection dir)

{

    target_phys_addr_t paddr, plen;



#ifdef DEBUG_IOMMU

    fprintf(stderr, "dma_memory_check context=%p addr=0x" DMA_ADDR_FMT

            " len=0x" DMA_ADDR_FMT " dir=%d\n", dma, addr, len, dir);

#endif



    while (len) {

        if (dma->translate(dma, addr, &paddr, &plen, dir) != 0) {

            return false;

        }



        /* The translation might be valid for larger regions. */

        if (plen > len) {

            plen = len;

        }



        len -= plen;

        addr += plen;

    }



    return true;

}

static int vhost_user_call(struct vhost_dev *dev, unsigned long int request,

        void *arg)

{

    VhostUserMsg msg;

    VhostUserRequest msg_request;

    struct vhost_vring_file *file = 0;

    int need_reply = 0;

    int fds[VHOST_MEMORY_MAX_NREGIONS];

    int i, fd;

    size_t fd_num = 0;



    assert(dev->vhost_ops->backend_type == VHOST_BACKEND_TYPE_USER);



    msg_request = vhost_user_request_translate(request);

    msg.request = msg_request;

    msg.flags = VHOST_USER_VERSION;

    msg.size = 0;



    switch (request) {

    case VHOST_GET_FEATURES:

        need_reply = 1;

        break;



    case VHOST_SET_FEATURES:

    case VHOST_SET_LOG_BASE:

        msg.u64 = *((__u64 *) arg);

        msg.size = sizeof(m.u64);

        break;



    case VHOST_SET_OWNER:

    case VHOST_RESET_OWNER:

        break;



    case VHOST_SET_MEM_TABLE:

        for (i = 0; i < dev->mem->nregions; ++i) {

            struct vhost_memory_region *reg = dev->mem->regions + i;

            ram_addr_t ram_addr;

            qemu_ram_addr_from_host((void *)reg->userspace_addr, &ram_addr);

            fd = qemu_get_ram_fd(ram_addr);

            if (fd > 0) {

                msg.memory.regions[fd_num].userspace_addr = reg->userspace_addr;

                msg.memory.regions[fd_num].memory_size  = reg->memory_size;

                msg.memory.regions[fd_num].guest_phys_addr = reg->guest_phys_addr;

                msg.memory.regions[fd_num].mmap_offset = reg->userspace_addr -

                    (uintptr_t) qemu_get_ram_block_host_ptr(reg->guest_phys_addr);

                assert(fd_num < VHOST_MEMORY_MAX_NREGIONS);

                fds[fd_num++] = fd;

            }

        }



        msg.memory.nregions = fd_num;



        if (!fd_num) {

            error_report("Failed initializing vhost-user memory map\n"

                    "consider using -object memory-backend-file share=on\n");

            return -1;

        }



        msg.size = sizeof(m.memory.nregions);

        msg.size += sizeof(m.memory.padding);

        msg.size += fd_num * sizeof(VhostUserMemoryRegion);



        break;



    case VHOST_SET_LOG_FD:

        fds[fd_num++] = *((int *) arg);

        break;



    case VHOST_SET_VRING_NUM:

    case VHOST_SET_VRING_BASE:

        memcpy(&msg.state, arg, sizeof(struct vhost_vring_state));

        msg.size = sizeof(m.state);

        break;



    case VHOST_GET_VRING_BASE:

        memcpy(&msg.state, arg, sizeof(struct vhost_vring_state));

        msg.size = sizeof(m.state);

        need_reply = 1;

        break;



    case VHOST_SET_VRING_ADDR:

        memcpy(&msg.addr, arg, sizeof(struct vhost_vring_addr));

        msg.size = sizeof(m.addr);

        break;



    case VHOST_SET_VRING_KICK:

    case VHOST_SET_VRING_CALL:

    case VHOST_SET_VRING_ERR:

        file = arg;

        msg.u64 = file->index & VHOST_USER_VRING_IDX_MASK;

        msg.size = sizeof(m.u64);

        if (ioeventfd_enabled() && file->fd > 0) {

            fds[fd_num++] = file->fd;

        } else {

            msg.u64 |= VHOST_USER_VRING_NOFD_MASK;

        }

        break;

    default:

        error_report("vhost-user trying to send unhandled ioctl\n");

        return -1;

        break;

    }



    if (vhost_user_write(dev, &msg, fds, fd_num) < 0) {

        return 0;

    }



    if (need_reply) {

        if (vhost_user_read(dev, &msg) < 0) {

            return 0;

        }



        if (msg_request != msg.request) {

            error_report("Received unexpected msg type."

                    " Expected %d received %d\n", msg_request, msg.request);

            return -1;

        }



        switch (msg_request) {

        case VHOST_USER_GET_FEATURES:

            if (msg.size != sizeof(m.u64)) {

                error_report("Received bad msg size.\n");

                return -1;

            }

            *((__u64 *) arg) = msg.u64;

            break;

        case VHOST_USER_GET_VRING_BASE:

            if (msg.size != sizeof(m.state)) {

                error_report("Received bad msg size.\n");

                return -1;

            }

            memcpy(arg, &msg.state, sizeof(struct vhost_vring_state));

            break;

        default:

            error_report("Received unexpected msg type.\n");

            return -1;

            break;

        }

    }



    return 0;

}

static int vhost_sync_dirty_bitmap(struct vhost_dev *dev,

                                   MemoryRegionSection *section,

                                   hwaddr start_addr,

                                   hwaddr end_addr)

{

    int i;



    if (!dev->log_enabled || !dev->started) {

        return 0;

    }

    for (i = 0; i < dev->mem->nregions; ++i) {

        struct vhost_memory_region *reg = dev->mem->regions + i;

        vhost_dev_sync_region(dev, section, start_addr, end_addr,

                              reg->guest_phys_addr,

                              range_get_last(reg->guest_phys_addr,

                                             reg->memory_size));

    }

    for (i = 0; i < dev->nvqs; ++i) {

        struct vhost_virtqueue *vq = dev->vqs + i;

        vhost_dev_sync_region(dev, section, start_addr, end_addr, vq->used_phys,

                              range_get_last(vq->used_phys, vq->used_size));

    }

    return 0;

}

static int vhost_set_vring_file(struct vhost_dev *dev,

                                VhostUserRequest request,

                                struct vhost_vring_file *file)

{

    int fds[VHOST_MEMORY_MAX_NREGIONS];

    size_t fd_num = 0;

    VhostUserMsg msg = {

        .request = request,

        .flags = VHOST_USER_VERSION,

        .payload.u64 = file->index & VHOST_USER_VRING_IDX_MASK,

        .size = sizeof(msg.payload.u64),

    };



    if (ioeventfd_enabled() && file->fd > 0) {

        fds[fd_num++] = file->fd;

    } else {

        msg.payload.u64 |= VHOST_USER_VRING_NOFD_MASK;

    }



    vhost_user_write(dev, &msg, fds, fd_num);



    return 0;

}

static int vhost_user_get_vring_base(struct vhost_dev *dev,

                                     struct vhost_vring_state *ring)

{

    VhostUserMsg msg = {

        .request = VHOST_USER_GET_VRING_BASE,

        .flags = VHOST_USER_VERSION,

        .state = *ring,

        .size = sizeof(*ring),

    };



    vhost_user_write(dev, &msg, NULL, 0);



    if (vhost_user_read(dev, &msg) < 0) {

        return 0;

    }



    if (msg.request != VHOST_USER_GET_VRING_BASE) {

        error_report("Received unexpected msg type. Expected %d received %d",

                     VHOST_USER_GET_VRING_BASE, msg.request);

