static int ogg_build_flac_headers(AVCodecContext *avctx,

                                  OGGStreamContext *oggstream, int bitexact)

{

    const char *vendor = bitexact ? "ffmpeg" : LIBAVFORMAT_IDENT;

    enum FLACExtradataFormat format;

    uint8_t *streaminfo;

    uint8_t *p;

    if (!ff_flac_is_extradata_valid(avctx, &format, &streaminfo))

        return -1;

    oggstream->header_len[0] = 51;

    oggstream->header[0] = av_mallocz(51); // per ogg flac specs

    p = oggstream->header[0];



    bytestream_put_byte(&p, 0x7F);

    bytestream_put_buffer(&p, "FLAC", 4);

    bytestream_put_byte(&p, 1); // major version

    bytestream_put_byte(&p, 0); // minor version

    bytestream_put_be16(&p, 1); // headers packets without this one

    bytestream_put_buffer(&p, "fLaC", 4);

    bytestream_put_byte(&p, 0x00); // streaminfo

    bytestream_put_be24(&p, 34);

    bytestream_put_buffer(&p, streaminfo, FLAC_STREAMINFO_SIZE);

    oggstream->header_len[1] = 1+3+4+strlen(vendor)+4;

    oggstream->header[1] = av_mallocz(oggstream->header_len[1]);

    p = oggstream->header[1];



    bytestream_put_byte(&p, 0x84); // last metadata block and vorbis comment

    bytestream_put_be24(&p, oggstream->header_len[1] - 4);

    bytestream_put_le32(&p, strlen(vendor));

    bytestream_put_buffer(&p, vendor, strlen(vendor));

    bytestream_put_le32(&p, 0); // user comment list length

    return 0;

}

static int inject_fake_duration_metadata(RTMPContext *rt)

{

    // We need to insert the metdata packet directly after the FLV

    // header, i.e. we need to move all other already read data by the

    // size of our fake metadata packet.



    uint8_t* p;

    // Keep old flv_data pointer

    uint8_t* old_flv_data = rt->flv_data;

    // Allocate a new flv_data pointer with enough space for the additional package

    if (!(rt->flv_data = av_malloc(rt->flv_size + 55))) {

        rt->flv_data = old_flv_data;

        return AVERROR(ENOMEM);

    }



    // Copy FLV header

    memcpy(rt->flv_data, old_flv_data, 13);

    // Copy remaining packets

    memcpy(rt->flv_data + 13 + 55, old_flv_data + 13, rt->flv_size - 13);

    // Increase the size by the injected packet

    rt->flv_size += 55;

    // Delete the old FLV data

    av_free(old_flv_data);



    p = rt->flv_data + 13;

    bytestream_put_byte(&p, FLV_TAG_TYPE_META);

    bytestream_put_be24(&p, 40); // size of data part (sum of all parts below)

    bytestream_put_be24(&p, 0);  // timestamp

    bytestream_put_be32(&p, 0);  // reserved



    // first event name as a string

    bytestream_put_byte(&p, AMF_DATA_TYPE_STRING);

    // "onMetaData" as AMF string

    bytestream_put_be16(&p, 10);

    bytestream_put_buffer(&p, "onMetaData", 10);



    // mixed array (hash) with size and string/type/data tuples

    bytestream_put_byte(&p, AMF_DATA_TYPE_MIXEDARRAY);

    bytestream_put_be32(&p, 1); // metadata_count



    // "duration" as AMF string

    bytestream_put_be16(&p, 8);

    bytestream_put_buffer(&p, "duration", 8);

    bytestream_put_byte(&p, AMF_DATA_TYPE_NUMBER);

    bytestream_put_be64(&p, av_double2int(rt->duration));



    // Finalise object

    bytestream_put_be16(&p, 0); // Empty string

    bytestream_put_byte(&p, AMF_END_OF_OBJECT);

    bytestream_put_be32(&p, 40); // size of data part (sum of all parts below)



    return 0;

}

int ff_vorbiscomment_write(uint8_t **p, AVDictionary **m,

                           const char *vendor_string)

{

    bytestream_put_le32(p, strlen(vendor_string));

    bytestream_put_buffer(p, vendor_string, strlen(vendor_string));

    if (*m) {

        int count = av_dict_count(*m);

        AVDictionaryEntry *tag = NULL;

        bytestream_put_le32(p, count);

        while ((tag = av_dict_get(*m, "", tag, AV_DICT_IGNORE_SUFFIX))) {

            unsigned int len1 = strlen(tag->key);

            unsigned int len2 = strlen(tag->value);

            bytestream_put_le32(p, len1+1+len2);

            bytestream_put_buffer(p, tag->key, len1);

            bytestream_put_byte(p, '=');

            bytestream_put_buffer(p, tag->value, len2);

        }

    } else

        bytestream_put_le32(p, 0);

    return 0;

}

static int gif_image_write_header(uint8_t **bytestream,

                                  int width, int height, int loop_count,

                                  uint32_t *palette)

{

    int i;

    unsigned int v;



    bytestream_put_buffer(bytestream, "GIF", 3);

    bytestream_put_buffer(bytestream, "89a", 3);

    bytestream_put_le16(bytestream, width);

    bytestream_put_le16(bytestream, height);



    bytestream_put_byte(bytestream, 0xf7); /* flags: global clut, 256 entries */

    bytestream_put_byte(bytestream, 0x1f); /* background color index */

    bytestream_put_byte(bytestream, 0); /* aspect ratio */



    /* the global palette */

    if (!palette) {

        bytestream_put_buffer(bytestream, (const unsigned char *)gif_clut, 216*3);

        for(i=0;i<((256-216)*3);i++)

            bytestream_put_byte(bytestream, 0);

    } else {

        for(i=0;i<256;i++) {

            v = palette[i];

            bytestream_put_be24(bytestream, v);

        }

    }



        /*        update: this is the 'NETSCAPE EXTENSION' that allows for looped animated gif

                see http://members.aol.com/royalef/gifabout.htm#net-extension



                byte   1       : 33 (hex 0x21) GIF Extension code

                byte   2       : 255 (hex 0xFF) Application Extension Label

                byte   3       : 11 (hex (0x0B) Length of Application Block

                                         (eleven bytes of data to follow)

                bytes  4 to 11 : "NETSCAPE"

                bytes 12 to 14 : "2.0"

                byte  15       : 3 (hex 0x03) Length of Data Sub-Block

                                         (three bytes of data to follow)

                byte  16       : 1 (hex 0x01)

                bytes 17 to 18 : 0 to 65535, an unsigned integer in

                                         lo-hi byte format. This indicate the

                                         number of iterations the loop should

                                         be executed.

                bytes 19       : 0 (hex 0x00) a Data Sub-block Terminator

        */



    /* application extension header */

#ifdef GIF_ADD_APP_HEADER

    if (loop_count >= 0 && loop_count <= 65535) {

        bytestream_put_byte(bytestream, 0x21);

        bytestream_put_byte(bytestream, 0xff);

        bytestream_put_byte(bytestream, 0x0b);

        bytestream_put_buffer(bytestream, "NETSCAPE2.0", 11);  // bytes 4 to 14

        bytestream_put_byte(bytestream, 0x03); // byte 15

        bytestream_put_byte(bytestream, 0x01); // byte 16

        bytestream_put_le16(bytestream, (uint16_t)loop_count);

        bytestream_put_byte(bytestream, 0x00); // byte 19

    }

#endif

    return 0;

}

static void output_audio_block(AC3EncodeContext *s, int blk)

{

    int ch, i, baie, bnd, got_cpl, ch0;

    AC3Block *block = &s->blocks[blk];



    /* block switching */

    if (!s->eac3) {

        for (ch = 0; ch < s->fbw_channels; ch++)

            put_bits(&s->pb, 1, 0);

    }



    /* dither flags */

    if (!s->eac3) {

        for (ch = 0; ch < s->fbw_channels; ch++)

            put_bits(&s->pb, 1, 1);

    }



    /* dynamic range codes */

    put_bits(&s->pb, 1, 0);



    /* spectral extension */

    if (s->eac3)

        put_bits(&s->pb, 1, 0);



    /* channel coupling */

    if (!s->eac3)

        put_bits(&s->pb, 1, block->new_cpl_strategy);

    if (block->new_cpl_strategy) {

        if (!s->eac3)

            put_bits(&s->pb, 1, block->cpl_in_use);

        if (block->cpl_in_use) {

            int start_sub, end_sub;

            if (s->eac3)

                put_bits(&s->pb, 1, 0); /* enhanced coupling */

            if (!s->eac3 || s->channel_mode != AC3_CHMODE_STEREO) {

                for (ch = 1; ch <= s->fbw_channels; ch++)

                    put_bits(&s->pb, 1, block->channel_in_cpl[ch]);

            }

            if (s->channel_mode == AC3_CHMODE_STEREO)

                put_bits(&s->pb, 1, 0); /* phase flags in use */

            start_sub = (s->start_freq[CPL_CH] - 37) / 12;

            end_sub   = (s->cpl_end_freq       - 37) / 12;

            put_bits(&s->pb, 4, start_sub);

            put_bits(&s->pb, 4, end_sub - 3);

            /* coupling band structure */

            if (s->eac3) {

                put_bits(&s->pb, 1, 0); /* use default */

            } else {

                for (bnd = start_sub+1; bnd < end_sub; bnd++)

                    put_bits(&s->pb, 1, ff_eac3_default_cpl_band_struct[bnd]);

            }

        }

    }



    /* coupling coordinates */

    if (block->cpl_in_use) {

        for (ch = 1; ch <= s->fbw_channels; ch++) {

            if (block->channel_in_cpl[ch]) {

                if (!s->eac3 || block->new_cpl_coords[ch] != 2)

                    put_bits(&s->pb, 1, block->new_cpl_coords[ch]);

                if (block->new_cpl_coords[ch]) {

                    put_bits(&s->pb, 2, block->cpl_master_exp[ch]);

                    for (bnd = 0; bnd < s->num_cpl_bands; bnd++) {

                        put_bits(&s->pb, 4, block->cpl_coord_exp [ch][bnd]);

                        put_bits(&s->pb, 4, block->cpl_coord_mant[ch][bnd]);

                    }

                }

            }

        }

    }



    /* stereo rematrixing */

    if (s->channel_mode == AC3_CHMODE_STEREO) {

        if (!s->eac3 || blk > 0)

            put_bits(&s->pb, 1, block->new_rematrixing_strategy);

        if (block->new_rematrixing_strategy) {

            /* rematrixing flags */

            for (bnd = 0; bnd < block->num_rematrixing_bands; bnd++)

                put_bits(&s->pb, 1, block->rematrixing_flags[bnd]);

        }

    }



    /* exponent strategy */

    if (!s->eac3) {

        for (ch = !block->cpl_in_use; ch <= s->fbw_channels; ch++)

            put_bits(&s->pb, 2, s->exp_strategy[ch][blk]);

        if (s->lfe_on)

            put_bits(&s->pb, 1, s->exp_strategy[s->lfe_channel][blk]);

    }



    /* bandwidth */

    for (ch = 1; ch <= s->fbw_channels; ch++) {

        if (s->exp_strategy[ch][blk] != EXP_REUSE && !block->channel_in_cpl[ch])

            put_bits(&s->pb, 6, s->bandwidth_code);

    }



    /* exponents */

    for (ch = !block->cpl_in_use; ch <= s->channels; ch++) {

        int nb_groups;

        int cpl = (ch == CPL_CH);



        if (s->exp_strategy[ch][blk] == EXP_REUSE)

            continue;



        /* DC exponent */

        put_bits(&s->pb, 4, block->grouped_exp[ch][0] >> cpl);



        /* exponent groups */

        nb_groups = exponent_group_tab[cpl][s->exp_strategy[ch][blk]-1][block->end_freq[ch]-s->start_freq[ch]];

        for (i = 1; i <= nb_groups; i++)

            put_bits(&s->pb, 7, block->grouped_exp[ch][i]);



        /* gain range info */

        if (ch != s->lfe_channel && !cpl)

            put_bits(&s->pb, 2, 0);

    }



    /* bit allocation info */

    if (!s->eac3) {

        baie = (blk == 0);

        put_bits(&s->pb, 1, baie);

        if (baie) {

            put_bits(&s->pb, 2, s->slow_decay_code);

            put_bits(&s->pb, 2, s->fast_decay_code);

            put_bits(&s->pb, 2, s->slow_gain_code);

            put_bits(&s->pb, 2, s->db_per_bit_code);

            put_bits(&s->pb, 3, s->floor_code);

        }

    }



    /* snr offset */

    if (!s->eac3) {

        put_bits(&s->pb, 1, block->new_snr_offsets);

        if (block->new_snr_offsets) {

            put_bits(&s->pb, 6, s->coarse_snr_offset);

            for (ch = !block->cpl_in_use; ch <= s->channels; ch++) {

                put_bits(&s->pb, 4, s->fine_snr_offset[ch]);

                put_bits(&s->pb, 3, s->fast_gain_code[ch]);

            }

        }

    } else {

        put_bits(&s->pb, 1, 0); /* no converter snr offset */

    }



    /* coupling leak */

    if (block->cpl_in_use) {

        if (!s->eac3 || block->new_cpl_leak != 2)

            put_bits(&s->pb, 1, block->new_cpl_leak);

        if (block->new_cpl_leak) {

            put_bits(&s->pb, 3, s->bit_alloc.cpl_fast_leak);

            put_bits(&s->pb, 3, s->bit_alloc.cpl_slow_leak);

        }

    }



    if (!s->eac3) {

        put_bits(&s->pb, 1, 0); /* no delta bit allocation */

        put_bits(&s->pb, 1, 0); /* no data to skip */

    }



    /* mantissas */

    got_cpl = !block->cpl_in_use;

    for (ch = 1; ch <= s->channels; ch++) {

        int b, q;



        if (!got_cpl && ch > 1 && block->channel_in_cpl[ch-1]) {

            ch0     = ch - 1;

            ch      = CPL_CH;

            got_cpl = 1;

        }

        for (i = s->start_freq[ch]; i < block->end_freq[ch]; i++) {

            q = block->qmant[ch][i];

            b = s->ref_bap[ch][blk][i];

            switch (b) {

            case 0:                                          break;

            case 1: if (q != 128) put_bits (&s->pb,   5, q); break;

            case 2: if (q != 128) put_bits (&s->pb,   7, q); break;

            case 3:               put_sbits(&s->pb,   3, q); break;

            case 4: if (q != 128) put_bits (&s->pb,   7, q); break;

            case 14:              put_sbits(&s->pb,  14, q); break;

            case 15:              put_sbits(&s->pb,  16, q); break;

            default:              put_sbits(&s->pb, b-1, q); break;

            }

        }

        if (ch == CPL_CH)

            ch = ch0;

    }

}

static void encode_frame(MpegAudioContext *s,

                         unsigned char bit_alloc[MPA_MAX_CHANNELS][SBLIMIT],

                         int padding)

{

    int i, j, k, l, bit_alloc_bits, b, ch;

    unsigned char *sf;

    int q[3];

    PutBitContext *p = &s->pb;



    /* header */



    put_bits(p, 12, 0xfff);

    put_bits(p, 1, 1 - s->lsf); /* 1 = mpeg1 ID, 0 = mpeg2 lsf ID */

    put_bits(p, 2, 4-2);  /* layer 2 */

    put_bits(p, 1, 1); /* no error protection */

    put_bits(p, 4, s->bitrate_index);

    put_bits(p, 2, s->freq_index);

    put_bits(p, 1, s->do_padding); /* use padding */

    put_bits(p, 1, 0);             /* private_bit */

    put_bits(p, 2, s->nb_channels == 2 ? MPA_STEREO : MPA_MONO);

    put_bits(p, 2, 0); /* mode_ext */

    put_bits(p, 1, 0); /* no copyright */

    put_bits(p, 1, 1); /* original */

    put_bits(p, 2, 0); /* no emphasis */



    /* bit allocation */

    j = 0;

    for(i=0;i<s->sblimit;i++) {

        bit_alloc_bits = s->alloc_table[j];

        for(ch=0;ch<s->nb_channels;ch++) {

            put_bits(p, bit_alloc_bits, bit_alloc[ch][i]);

        }

        j += 1 << bit_alloc_bits;

    }



    /* scale codes */

    for(i=0;i<s->sblimit;i++) {

        for(ch=0;ch<s->nb_channels;ch++) {

            if (bit_alloc[ch][i])

                put_bits(p, 2, s->scale_code[ch][i]);

        }

    }



    /* scale factors */

    for(i=0;i<s->sblimit;i++) {

        for(ch=0;ch<s->nb_channels;ch++) {

            if (bit_alloc[ch][i]) {

                sf = &s->scale_factors[ch][i][0];

                switch(s->scale_code[ch][i]) {

                case 0:

                    put_bits(p, 6, sf[0]);

                    put_bits(p, 6, sf[1]);

                    put_bits(p, 6, sf[2]);

                    break;

                case 3:

                case 1:

                    put_bits(p, 6, sf[0]);

                    put_bits(p, 6, sf[2]);

                    break;

                case 2:

                    put_bits(p, 6, sf[0]);

                    break;

                }

            }

        }

    }



    /* quantization & write sub band samples */



    for(k=0;k<3;k++) {

        for(l=0;l<12;l+=3) {

            j = 0;

            for(i=0;i<s->sblimit;i++) {

                bit_alloc_bits = s->alloc_table[j];

                for(ch=0;ch<s->nb_channels;ch++) {

                    b = bit_alloc[ch][i];

                    if (b) {

                        int qindex, steps, m, sample, bits;

                        /* we encode 3 sub band samples of the same sub band at a time */

                        qindex = s->alloc_table[j+b];

                        steps = ff_mpa_quant_steps[qindex];

                        for(m=0;m<3;m++) {

                            sample = s->sb_samples[ch][k][l + m][i];

                            /* divide by scale factor */

#if USE_FLOATS

                            {

                                float a;

                                a = (float)sample * s->scale_factor_inv_table[s->scale_factors[ch][i][k]];

                                q[m] = (int)((a + 1.0) * steps * 0.5);

                            }

#else

                            {

                                int q1, e, shift, mult;

                                e = s->scale_factors[ch][i][k];

                                shift = s->scale_factor_shift[e];

                                mult = s->scale_factor_mult[e];



                                /* normalize to P bits */

                                if (shift < 0)

                                    q1 = sample << (-shift);

                                else

                                    q1 = sample >> shift;

                                q1 = (q1 * mult) >> P;

                                q1 += 1 << P;

                                if (q1 < 0)

                                    q1 = 0;

                                q[m] = (unsigned)(q1 * steps) >> (P + 1);

                            }

#endif

                            if (q[m] >= steps)

                                q[m] = steps - 1;

                            av_assert2(q[m] >= 0 && q[m] < steps);

                        }

                        bits = ff_mpa_quant_bits[qindex];

                        if (bits < 0) {

                            /* group the 3 values to save bits */

                            put_bits(p, -bits,

                                     q[0] + steps * (q[1] + steps * q[2]));

                        } else {

                            put_bits(p, bits, q[0]);

                            put_bits(p, bits, q[1]);

                            put_bits(p, bits, q[2]);

                        }

                    }

                }

                /* next subband in alloc table */

                j += 1 << bit_alloc_bits;

            }

        }

    }



    /* padding */

    for(i=0;i<padding;i++)

        put_bits(p, 1, 0);



    /* flush */

    flush_put_bits(p);

}

static void quantize_all(DCAEncContext *c)

{

    int sample, band, ch;



    for (sample = 0; sample < SUBBAND_SAMPLES; sample++)

        for (band = 0; band < 32; band++)

            for (ch = 0; ch < c->fullband_channels; ch++)

                c->quantized[sample][band][ch] = quantize_value(c->subband[sample][band][ch], c->quant[band][ch]);

}

void ff_eac3_output_frame_header(AC3EncodeContext *s)

{

    int blk, ch;

    AC3EncOptions *opt = &s->options;



    put_bits(&s->pb, 16, 0x0b77);                   /* sync word */



    /* BSI header */

    put_bits(&s->pb,  2, 0);                        /* stream type = independent */

    put_bits(&s->pb,  3, 0);                        /* substream id = 0 */

    put_bits(&s->pb, 11, (s->frame_size / 2) - 1);  /* frame size */

    if (s->bit_alloc.sr_shift) {

        put_bits(&s->pb, 2, 0x3);                   /* fscod2 */

        put_bits(&s->pb, 2, s->bit_alloc.sr_code);  /* sample rate code */

    } else {

        put_bits(&s->pb, 2, s->bit_alloc.sr_code);  /* sample rate code */

        put_bits(&s->pb, 2, 0x3);                   /* number of blocks = 6 */

    }

    put_bits(&s->pb, 3, s->channel_mode);           /* audio coding mode */

    put_bits(&s->pb, 1, s->lfe_on);                 /* LFE channel indicator */

    put_bits(&s->pb, 5, s->bitstream_id);           /* bitstream id (EAC3=16) */

    put_bits(&s->pb, 5, -opt->dialogue_level);      /* dialogue normalization level */

    put_bits(&s->pb, 1, 0);                         /* no compression gain */

    put_bits(&s->pb, 1, 0);                         /* no mixing metadata */

    /* TODO: mixing metadata */

    put_bits(&s->pb, 1, 0);                         /* no info metadata */

    /* TODO: info metadata */

    put_bits(&s->pb, 1, 0);                         /* no additional bit stream info */



    /* frame header */

    put_bits(&s->pb, 1, 1);                         /* exponent strategy syntax = each block */

    put_bits(&s->pb, 1, 0);                         /* aht enabled = no */

    put_bits(&s->pb, 2, 0);                         /* snr offset strategy = 1 */

    put_bits(&s->pb, 1, 0);                         /* transient pre-noise processing enabled = no */

    put_bits(&s->pb, 1, 0);                         /* block switch syntax enabled = no */

    put_bits(&s->pb, 1, 0);                         /* dither flag syntax enabled = no */

    put_bits(&s->pb, 1, 0);                         /* bit allocation model syntax enabled = no */

    put_bits(&s->pb, 1, 0);                         /* fast gain codes enabled = no */

    put_bits(&s->pb, 1, 0);                         /* dba syntax enabled = no */

    put_bits(&s->pb, 1, 0);                         /* skip field syntax enabled = no */

    put_bits(&s->pb, 1, 0);                         /* spx enabled = no */

    /* coupling strategy use flags */

    if (s->channel_mode > AC3_CHMODE_MONO) {

        put_bits(&s->pb, 1, s->blocks[0].cpl_in_use);

        for (blk = 1; blk < AC3_MAX_BLOCKS; blk++) {

            AC3Block *block = &s->blocks[blk];

            put_bits(&s->pb, 1, block->new_cpl_strategy);

            if (block->new_cpl_strategy)

                put_bits(&s->pb, 1, block->cpl_in_use);

        }

    }

    /* exponent strategy */

    for (blk = 0; blk < AC3_MAX_BLOCKS; blk++)

        for (ch = !s->blocks[blk].cpl_in_use; ch <= s->fbw_channels; ch++)

            put_bits(&s->pb, 2, s->exp_strategy[ch][blk]);

    if (s->lfe_on) {

        for (blk = 0; blk < AC3_MAX_BLOCKS; blk++)

            put_bits(&s->pb, 1, s->exp_strategy[s->lfe_channel][blk]);

    }

    /* E-AC-3 to AC-3 converter exponent strategy (unfortunately not optional...) */

    for (ch = 1; ch <= s->fbw_channels; ch++)

        put_bits(&s->pb, 5, 0);

    /* snr offsets */

    put_bits(&s->pb, 6, s->coarse_snr_offset);

    put_bits(&s->pb, 4, s->fine_snr_offset[1]);

    /* block start info */

    put_bits(&s->pb, 1, 0);

}

static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }




    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static void decode_plane_bitstream(HYuvContext *s, int count, int plane)

{

    int i;



    count /= 2;



    if (s->bps <= 8) {

        OPEN_READER(re, &s->gb);

        if (count >= (get_bits_left(&s->gb)) / (32 * 2)) {

            for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

                READ_2PIX_PLANE(s->temp[0][2 * i], s->temp[0][2 * i + 1], plane, OP8bits);

            }

        } else {

            for(i=0; i<count; i++){

                READ_2PIX_PLANE(s->temp[0][2 * i], s->temp[0][2 * i + 1], plane, OP8bits);

            }

        }

        CLOSE_READER(re, &s->gb);

    } else if (s->bps <= 14) {

        OPEN_READER(re, &s->gb);

        if (count >= (get_bits_left(&s->gb)) / (32 * 2)) {

            for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

                READ_2PIX_PLANE(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane, OP14bits);

            }

        } else {

            for(i=0; i<count; i++){

                READ_2PIX_PLANE(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane, OP14bits);

            }

        }

        CLOSE_READER(re, &s->gb);

    } else {

        if (count >= (get_bits_left(&s->gb)) / (32 * 2)) {

            for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

                READ_2PIX_PLANE16(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane);

            }

        } else {

            for(i=0; i<count; i++){

                READ_2PIX_PLANE16(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane);

            }

        }

    }

}

static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

        for (; i < count; i++)

            s->temp[0][2 * i    ] = s->temp[1][i] =

            s->temp[0][2 * i + 1] = s->temp[2][i] = 128;

    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static void encode_422_bitstream(HYuvContext *s, int count){

    int i;



    count/=2;

    if(s->flags&CODEC_FLAG_PASS1){

        for(i=0; i<count; i++){

            s->stats[0][ s->temp[0][2*i  ] ]++;

            s->stats[1][ s->temp[1][  i  ] ]++;

            s->stats[0][ s->temp[0][2*i+1] ]++;

            s->stats[2][ s->temp[2][  i  ] ]++;

        }

    }else if(s->context){

        for(i=0; i<count; i++){

            s->stats[0][ s->temp[0][2*i  ] ]++;

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i  ] ], s->bits[0][ s->temp[0][2*i  ] ]);

            s->stats[1][ s->temp[1][  i  ] ]++;

            put_bits(&s->pb, s->len[1][ s->temp[1][  i  ] ], s->bits[1][ s->temp[1][  i  ] ]);

            s->stats[0][ s->temp[0][2*i+1] ]++;

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i+1] ], s->bits[0][ s->temp[0][2*i+1] ]);

            s->stats[2][ s->temp[2][  i  ] ]++;

            put_bits(&s->pb, s->len[2][ s->temp[2][  i  ] ], s->bits[2][ s->temp[2][  i  ] ]);

        }

    }else{

        for(i=0; i<count; i++){

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i  ] ], s->bits[0][ s->temp[0][2*i  ] ]);

            put_bits(&s->pb, s->len[1][ s->temp[1][  i  ] ], s->bits[1][ s->temp[1][  i  ] ]);

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i+1] ], s->bits[0][ s->temp[0][2*i+1] ]);

            put_bits(&s->pb, s->len[2][ s->temp[2][  i  ] ], s->bits[2][ s->temp[2][  i  ] ]);

        }

    }

}

static void start_auth_vencrypt_subauth(VncState *vs)

{

    switch (vs->subauth) {

    case VNC_AUTH_VENCRYPT_TLSNONE:

    case VNC_AUTH_VENCRYPT_X509NONE:

       VNC_DEBUG("Accept TLS auth none\n");

       vnc_write_u32(vs, 0); /* Accept auth completion */

       start_client_init(vs);

       break;



    case VNC_AUTH_VENCRYPT_TLSVNC:

    case VNC_AUTH_VENCRYPT_X509VNC:

       VNC_DEBUG("Start TLS auth VNC\n");

       start_auth_vnc(vs);

       break;



#ifdef CONFIG_VNC_SASL

    case VNC_AUTH_VENCRYPT_TLSSASL:

    case VNC_AUTH_VENCRYPT_X509SASL:

      VNC_DEBUG("Start TLS auth SASL\n");

      start_auth_sasl(vs);

      break;

#endif /* CONFIG_VNC_SASL */



    default: /* Should not be possible, but just in case */

       VNC_DEBUG("Reject subauth %d server bug\n", vs->auth);

       vnc_write_u8(vs, 1);

       if (vs->minor >= 8) {

           static const char err[] = "Unsupported authentication type";

           vnc_write_u32(vs, sizeof(err));

           vnc_write(vs, err, sizeof(err));

       }

       vnc_client_error(vs);

    }

}

static int protocol_client_vencrypt_init(VncState *vs, uint8_t *data, size_t len)

{

    if (data[0] != 0 ||

        data[1] != 2) {

        VNC_DEBUG("Unsupported VeNCrypt protocol %d.%d\n", (int)data[0], (int)data[1]);

        vnc_write_u8(vs, 1); /* Reject version */

        vnc_flush(vs);

        vnc_client_error(vs);

    } else {

        VNC_DEBUG("Sending allowed auth %d\n", vs->subauth);

        vnc_write_u8(vs, 0); /* Accept version */

        vnc_write_u8(vs, 1); /* Number of sub-auths */

        vnc_write_u32(vs, vs->subauth); /* The supported auth */

        vnc_flush(vs);

        vnc_read_when(vs, protocol_client_vencrypt_auth, 4);

    }

    return 0;

}

static void start_auth_vencrypt_subauth(VncState *vs)

{

    switch (vs->vd->subauth) {

    case VNC_AUTH_VENCRYPT_TLSNONE:

    case VNC_AUTH_VENCRYPT_X509NONE:

       VNC_DEBUG("Accept TLS auth none\n");

       vnc_write_u32(vs, 0); /* Accept auth completion */

       start_client_init(vs);

       break;



    case VNC_AUTH_VENCRYPT_TLSVNC:

    case VNC_AUTH_VENCRYPT_X509VNC:

       VNC_DEBUG("Start TLS auth VNC\n");

       start_auth_vnc(vs);

       break;



#ifdef CONFIG_VNC_SASL

    case VNC_AUTH_VENCRYPT_TLSSASL:

    case VNC_AUTH_VENCRYPT_X509SASL:

      VNC_DEBUG("Start TLS auth SASL\n");

      return start_auth_sasl(vs);

#endif /* CONFIG_VNC_SASL */



    default: /* Should not be possible, but just in case */

       VNC_DEBUG("Reject subauth %d server bug\n", vs->vd->auth);

       vnc_write_u8(vs, 1);

       if (vs->minor >= 8) {

           static const char err[] = "Unsupported authentication type";

           vnc_write_u32(vs, sizeof(err));

           vnc_write(vs, err, sizeof(err));

       }

       vnc_client_error(vs);

    }

}

