    }

    MIPS_DEBUG("%s: cond %02x target " TARGET_FMT_lx, opn,

               ctx->hflags, btarget);

    ctx->btarget = btarget;



 out:

    tcg_temp_free(t0);

    tcg_temp_free(t1);

}

static void gen_compute_branch (DisasContext *ctx, uint32_t opc,

                                int insn_bytes,

                                int rs, int rt, int32_t offset)

{

    target_ulong btgt = -1;

    int blink = 0;

    int bcond_compute = 0;

    TCGv t0 = tcg_temp_new();

    TCGv t1 = tcg_temp_new();



    if (ctx->hflags & MIPS_HFLAG_BMASK) {

#ifdef MIPS_DEBUG_DISAS

        LOG_DISAS("Branch in delay slot at PC 0x" TARGET_FMT_lx "\n", ctx->pc);

#endif

        generate_exception(ctx, EXCP_RI);

        goto out;

    }



    /* Load needed operands */

    switch (opc) {

    case OPC_BEQ:

    case OPC_BEQL:

    case OPC_BNE:

    case OPC_BNEL:

        /* Compare two registers */

        if (rs != rt) {

            gen_load_gpr(t0, rs);

            gen_load_gpr(t1, rt);

            bcond_compute = 1;

        }

        btgt = ctx->pc + insn_bytes + offset;

        break;

    case OPC_BGEZ:

    case OPC_BGEZAL:

    case OPC_BGEZALL:

    case OPC_BGEZL:

    case OPC_BGTZ:

    case OPC_BGTZL:

    case OPC_BLEZ:

    case OPC_BLEZL:

    case OPC_BLTZ:

    case OPC_BLTZAL:

    case OPC_BLTZALL:

    case OPC_BLTZL:

        /* Compare to zero */

        if (rs != 0) {

            gen_load_gpr(t0, rs);

            bcond_compute = 1;

        }

        btgt = ctx->pc + insn_bytes + offset;

        break;

    case OPC_J:

    case OPC_JAL:

    case OPC_JALX:

        /* Jump to immediate */

        btgt = ((ctx->pc + insn_bytes) & (int32_t)0xF0000000) | (uint32_t)offset;

        break;

    case OPC_JR:

    case OPC_JALR:

    case OPC_JALRC:

        /* Jump to register */

        if (offset != 0 && offset != 16) {

            /* Hint = 0 is JR/JALR, hint 16 is JR.HB/JALR.HB, the

               others are reserved. */

            MIPS_INVAL("jump hint");

            generate_exception(ctx, EXCP_RI);

            goto out;

        }

        gen_load_gpr(btarget, rs);

        break;

    default:

        MIPS_INVAL("branch/jump");

        generate_exception(ctx, EXCP_RI);

        goto out;

    }

    if (bcond_compute == 0) {

        /* No condition to be computed */

        switch (opc) {

        case OPC_BEQ:     /* rx == rx        */

        case OPC_BEQL:    /* rx == rx likely */

        case OPC_BGEZ:    /* 0 >= 0          */

        case OPC_BGEZL:   /* 0 >= 0 likely   */

        case OPC_BLEZ:    /* 0 <= 0          */

        case OPC_BLEZL:   /* 0 <= 0 likely   */

            /* Always take */

            ctx->hflags |= MIPS_HFLAG_B;

            MIPS_DEBUG("balways");

            break;

        case OPC_BGEZAL:  /* 0 >= 0          */

        case OPC_BGEZALL: /* 0 >= 0 likely   */

            /* Always take and link */

            blink = 31;

            ctx->hflags |= MIPS_HFLAG_B;

            MIPS_DEBUG("balways and link");

            break;

        case OPC_BNE:     /* rx != rx        */

        case OPC_BGTZ:    /* 0 > 0           */

        case OPC_BLTZ:    /* 0 < 0           */

            /* Treat as NOP. */

            MIPS_DEBUG("bnever (NOP)");

            goto out;

        case OPC_BLTZAL:  /* 0 < 0           */

            tcg_gen_movi_tl(cpu_gpr[31], ctx->pc + 8);

            MIPS_DEBUG("bnever and link");

            goto out;

        case OPC_BLTZALL: /* 0 < 0 likely */

            tcg_gen_movi_tl(cpu_gpr[31], ctx->pc + 8);

            /* Skip the instruction in the delay slot */

            MIPS_DEBUG("bnever, link and skip");

            ctx->pc += 4;

            goto out;

        case OPC_BNEL:    /* rx != rx likely */

        case OPC_BGTZL:   /* 0 > 0 likely */

        case OPC_BLTZL:   /* 0 < 0 likely */

            /* Skip the instruction in the delay slot */

            MIPS_DEBUG("bnever and skip");

            ctx->pc += 4;

            goto out;

        case OPC_J:

            ctx->hflags |= MIPS_HFLAG_B;

            MIPS_DEBUG("j " TARGET_FMT_lx, btgt);

            break;

        case OPC_JALX:

            ctx->hflags |= MIPS_HFLAG_BX;

            /* Fallthrough */

        case OPC_JAL:

            blink = 31;

            ctx->hflags |= MIPS_HFLAG_B;

            ctx->hflags |= (ctx->hflags & MIPS_HFLAG_M16

                            ? MIPS_HFLAG_BDS16

                            : MIPS_HFLAG_BDS32);

            MIPS_DEBUG("jal " TARGET_FMT_lx, btgt);

            break;

        case OPC_JR:

            ctx->hflags |= MIPS_HFLAG_BR;

            if (ctx->hflags & MIPS_HFLAG_M16)

                ctx->hflags |= MIPS_HFLAG_BDS16;

            MIPS_DEBUG("jr %s", regnames[rs]);

            break;

        case OPC_JALR:

        case OPC_JALRC:

            blink = rt;

            ctx->hflags |= MIPS_HFLAG_BR;

            if (ctx->hflags & MIPS_HFLAG_M16)

                ctx->hflags |= MIPS_HFLAG_BDS16;

            MIPS_DEBUG("jalr %s, %s", regnames[rt], regnames[rs]);

            break;

        default:

            MIPS_INVAL("branch/jump");

            generate_exception(ctx, EXCP_RI);

            goto out;

        }

    } else {

        switch (opc) {

        case OPC_BEQ:

            tcg_gen_setcond_tl(TCG_COND_EQ, bcond, t0, t1);

            MIPS_DEBUG("beq %s, %s, " TARGET_FMT_lx,

                       regnames[rs], regnames[rt], btgt);

            goto not_likely;

        case OPC_BEQL:

            tcg_gen_setcond_tl(TCG_COND_EQ, bcond, t0, t1);

            MIPS_DEBUG("beql %s, %s, " TARGET_FMT_lx,

                       regnames[rs], regnames[rt], btgt);

            goto likely;

        case OPC_BNE:

            tcg_gen_setcond_tl(TCG_COND_NE, bcond, t0, t1);

            MIPS_DEBUG("bne %s, %s, " TARGET_FMT_lx,

                       regnames[rs], regnames[rt], btgt);

            goto not_likely;

        case OPC_BNEL:

            tcg_gen_setcond_tl(TCG_COND_NE, bcond, t0, t1);

            MIPS_DEBUG("bnel %s, %s, " TARGET_FMT_lx,

                       regnames[rs], regnames[rt], btgt);

            goto likely;

        case OPC_BGEZ:

            tcg_gen_setcondi_tl(TCG_COND_GE, bcond, t0, 0);

            MIPS_DEBUG("bgez %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto not_likely;

        case OPC_BGEZL:

            tcg_gen_setcondi_tl(TCG_COND_GE, bcond, t0, 0);

            MIPS_DEBUG("bgezl %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto likely;

        case OPC_BGEZAL:

            tcg_gen_setcondi_tl(TCG_COND_GE, bcond, t0, 0);

            MIPS_DEBUG("bgezal %s, " TARGET_FMT_lx, regnames[rs], btgt);

            blink = 31;

            goto not_likely;

        case OPC_BGEZALL:

            tcg_gen_setcondi_tl(TCG_COND_GE, bcond, t0, 0);

            blink = 31;

            MIPS_DEBUG("bgezall %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto likely;

        case OPC_BGTZ:

            tcg_gen_setcondi_tl(TCG_COND_GT, bcond, t0, 0);

            MIPS_DEBUG("bgtz %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto not_likely;

        case OPC_BGTZL:

            tcg_gen_setcondi_tl(TCG_COND_GT, bcond, t0, 0);

            MIPS_DEBUG("bgtzl %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto likely;

        case OPC_BLEZ:

            tcg_gen_setcondi_tl(TCG_COND_LE, bcond, t0, 0);

            MIPS_DEBUG("blez %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto not_likely;

        case OPC_BLEZL:

            tcg_gen_setcondi_tl(TCG_COND_LE, bcond, t0, 0);

            MIPS_DEBUG("blezl %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto likely;

        case OPC_BLTZ:

            tcg_gen_setcondi_tl(TCG_COND_LT, bcond, t0, 0);

            MIPS_DEBUG("bltz %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto not_likely;

        case OPC_BLTZL:

            tcg_gen_setcondi_tl(TCG_COND_LT, bcond, t0, 0);

            MIPS_DEBUG("bltzl %s, " TARGET_FMT_lx, regnames[rs], btgt);

            goto likely;

        case OPC_BLTZAL:

            tcg_gen_setcondi_tl(TCG_COND_LT, bcond, t0, 0);

            blink = 31;

            MIPS_DEBUG("bltzal %s, " TARGET_FMT_lx, regnames[rs], btgt);

        not_likely:

            ctx->hflags |= MIPS_HFLAG_BC;

            break;

        case OPC_BLTZALL:

            tcg_gen_setcondi_tl(TCG_COND_LT, bcond, t0, 0);

            blink = 31;

            MIPS_DEBUG("bltzall %s, " TARGET_FMT_lx, regnames[rs], btgt);

        likely:

            ctx->hflags |= MIPS_HFLAG_BL;

            break;

        default:

            MIPS_INVAL("conditional branch/jump");

            generate_exception(ctx, EXCP_RI);

            goto out;

        }

    }

    MIPS_DEBUG("enter ds: link %d cond %02x target " TARGET_FMT_lx,

               blink, ctx->hflags, btgt);



    ctx->btarget = btgt;

    if (blink > 0) {

        int post_delay = insn_bytes;

        int lowbit = !!(ctx->hflags & MIPS_HFLAG_M16);



        if (opc != OPC_JALRC)

            post_delay += ((ctx->hflags & MIPS_HFLAG_BDS16) ? 2 : 4);



        tcg_gen_movi_tl(cpu_gpr[blink], ctx->pc + post_delay + lowbit);

    }



 out:

    if (insn_bytes == 2)

        ctx->hflags |= MIPS_HFLAG_B16;

    tcg_temp_free(t0);

    tcg_temp_free(t1);

}

static QObject *parse_literal(JSONParserContext *ctxt, QList **tokens)

{

    QObject *token, *obj;

    QList *working = qlist_copy(*tokens);



    token = qlist_pop(working);

    if (token == NULL) {

        goto out;

    }



    switch (token_get_type(token)) {

    case JSON_STRING:

        obj = QOBJECT(qstring_from_escaped_str(ctxt, token));

        break;

    case JSON_INTEGER:

        obj = QOBJECT(qint_from_int(strtoll(token_get_value(token), NULL, 10)));

        break;

    case JSON_FLOAT:

        /* FIXME dependent on locale */

        obj = QOBJECT(qfloat_from_double(strtod(token_get_value(token), NULL)));

        break;

    default:

        goto out;

    }



    qobject_decref(token);

    QDECREF(*tokens);

    *tokens = working;



    return obj;



out:

    qobject_decref(token);

    QDECREF(working);



    return NULL;

}

static QObject *parse_object(JSONParserContext *ctxt, QList **tokens, va_list *ap)

{

    QDict *dict = NULL;

    QObject *token, *peek;

    QList *working = qlist_copy(*tokens);



    token = qlist_pop(working);

    if (token == NULL) {

        goto out;

    }



    if (!token_is_operator(token, '{')) {

        goto out;

    }

    qobject_decref(token);

    token = NULL;



    dict = qdict_new();



    peek = qlist_peek(working);

    if (peek == NULL) {

        parse_error(ctxt, NULL, "premature EOI");

        goto out;

    }



    if (!token_is_operator(peek, '}')) {

        if (parse_pair(ctxt, dict, &working, ap) == -1) {

            goto out;

        }



        token = qlist_pop(working);

        if (token == NULL) {

            parse_error(ctxt, NULL, "premature EOI");

            goto out;

        }



        while (!token_is_operator(token, '}')) {

            if (!token_is_operator(token, ',')) {

                parse_error(ctxt, token, "expected separator in dict");

                goto out;

            }

            qobject_decref(token);

            token = NULL;



            if (parse_pair(ctxt, dict, &working, ap) == -1) {

                goto out;

            }



            token = qlist_pop(working);

            if (token == NULL) {

                parse_error(ctxt, NULL, "premature EOI");

                goto out;

            }

        }

        qobject_decref(token);

        token = NULL;

    } else {

        token = qlist_pop(working);

        qobject_decref(token);

        token = NULL;

    }



    QDECREF(*tokens);

    *tokens = working;



    return QOBJECT(dict);



out:

    qobject_decref(token);

    QDECREF(working);

    QDECREF(dict);

    return NULL;

}

static QObject *parse_escape(JSONParserContext *ctxt, QList **tokens, va_list *ap)

{

    QObject *token = NULL, *obj;

    QList *working = qlist_copy(*tokens);



    if (ap == NULL) {

        goto out;

    }



    token = qlist_pop(working);

    if (token == NULL) {

        goto out;

    }



    if (token_is_escape(token, "%p")) {

        obj = va_arg(*ap, QObject *);

    } else if (token_is_escape(token, "%i")) {

        obj = QOBJECT(qbool_from_int(va_arg(*ap, int)));

    } else if (token_is_escape(token, "%d")) {

        obj = QOBJECT(qint_from_int(va_arg(*ap, int)));

    } else if (token_is_escape(token, "%ld")) {

        obj = QOBJECT(qint_from_int(va_arg(*ap, long)));

    } else if (token_is_escape(token, "%lld") ||

               token_is_escape(token, "%I64d")) {

        obj = QOBJECT(qint_from_int(va_arg(*ap, long long)));

    } else if (token_is_escape(token, "%s")) {

        obj = QOBJECT(qstring_from_str(va_arg(*ap, const char *)));

    } else if (token_is_escape(token, "%f")) {

        obj = QOBJECT(qfloat_from_double(va_arg(*ap, double)));

    } else {

        goto out;

    }



    qobject_decref(token);

    QDECREF(*tokens);

    *tokens = working;



    return obj;



out:

    qobject_decref(token);

    QDECREF(working);



    return NULL;

}

static int parse_pair(JSONParserContext *ctxt, QDict *dict, QList **tokens, va_list *ap)

{

    QObject *key = NULL, *token = NULL, *value, *peek;

    QList *working = qlist_copy(*tokens);



    peek = qlist_peek(working);

    if (peek == NULL) {

        parse_error(ctxt, NULL, "premature EOI");

        goto out;

    }



    key = parse_value(ctxt, &working, ap);

    if (!key || qobject_type(key) != QTYPE_QSTRING) {

        parse_error(ctxt, peek, "key is not a string in object");

        goto out;

    }



    token = qlist_pop(working);

    if (token == NULL) {

        parse_error(ctxt, NULL, "premature EOI");

        goto out;

    }



    if (!token_is_operator(token, ':')) {

        parse_error(ctxt, token, "missing : in object pair");

        goto out;

    }



    value = parse_value(ctxt, &working, ap);

    if (value == NULL) {

        parse_error(ctxt, token, "Missing value in dict");

        goto out;

    }



    qdict_put_obj(dict, qstring_get_str(qobject_to_qstring(key)), value);



    qobject_decref(token);

    qobject_decref(key);

    QDECREF(*tokens);

    *tokens = working;



    return 0;



out:

    qobject_decref(token);

    qobject_decref(key);

    QDECREF(working);



    return -1;

}

static av_cold int vaapi_encode_check_config(AVCodecContext *avctx)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    VAStatus vas;

    int i, n, err;

    VAProfile    *profiles    = NULL;

    VAEntrypoint *entrypoints = NULL;

    VAConfigAttrib attr[] = {

        { VAConfigAttribRateControl     },

        { VAConfigAttribEncMaxRefFrames },

    };



    n = vaMaxNumProfiles(ctx->hwctx->display);

    profiles = av_malloc_array(n, sizeof(VAProfile));

    if (!profiles) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    vas = vaQueryConfigProfiles(ctx->hwctx->display, profiles, &n);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(ctx, AV_LOG_ERROR, "Failed to query profiles: %d (%s).\n",

               vas, vaErrorStr(vas));

        err = AVERROR(ENOSYS);

        goto fail;

    }

    for (i = 0; i < n; i++) {

        if (profiles[i] == ctx->va_profile)

            break;

    }

    if (i >= n) {

        av_log(ctx, AV_LOG_ERROR, "Encoding profile not found (%d).\n",

               ctx->va_profile);

        err = AVERROR(ENOSYS);

        goto fail;

    }



    n = vaMaxNumEntrypoints(ctx->hwctx->display);

    entrypoints = av_malloc_array(n, sizeof(VAEntrypoint));

    if (!entrypoints) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    vas = vaQueryConfigEntrypoints(ctx->hwctx->display, ctx->va_profile,

                                   entrypoints, &n);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(ctx, AV_LOG_ERROR, "Failed to query entrypoints for "

               "profile %u: %d (%s).\n", ctx->va_profile,

               vas, vaErrorStr(vas));

        err = AVERROR(ENOSYS);

        goto fail;

    }

    for (i = 0; i < n; i++) {

        if (entrypoints[i] == ctx->va_entrypoint)

            break;

    }

    if (i >= n) {

        av_log(ctx, AV_LOG_ERROR, "Encoding entrypoint not found "

               "(%d / %d).\n", ctx->va_profile, ctx->va_entrypoint);

        err = AVERROR(ENOSYS);

        goto fail;

    }



    vas = vaGetConfigAttributes(ctx->hwctx->display,

                                ctx->va_profile, ctx->va_entrypoint,

                                attr, FF_ARRAY_ELEMS(attr));

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to fetch config "

               "attributes: %d (%s).\n", vas, vaErrorStr(vas));

        return AVERROR(EINVAL);

    }



    for (i = 0; i < FF_ARRAY_ELEMS(attr); i++) {

        if (attr[i].value == VA_ATTRIB_NOT_SUPPORTED) {

            // Unfortunately we have to treat this as "don't know" and hope

            // for the best, because the Intel MJPEG encoder returns this

            // for all the interesting attributes.

            continue;

        }

        switch (attr[i].type) {

        case VAConfigAttribRateControl:

            if (!(ctx->va_rc_mode & attr[i].value)) {

                av_log(avctx, AV_LOG_ERROR, "Rate control mode is not "

                       "supported: %x\n", attr[i].value);

                err = AVERROR(EINVAL);

                goto fail;

            }

            break;

        case VAConfigAttribEncMaxRefFrames:

        {

            unsigned int ref_l0 = attr[i].value & 0xffff;

            unsigned int ref_l1 = (attr[i].value >> 16) & 0xffff;



            if (avctx->gop_size > 1 && ref_l0 < 1) {

                av_log(avctx, AV_LOG_ERROR, "P frames are not "

                       "supported (%x).\n", attr[i].value);

                err = AVERROR(EINVAL);

                goto fail;

            }

            if (avctx->max_b_frames > 0 && ref_l1 < 1) {

                av_log(avctx, AV_LOG_ERROR, "B frames are not "

                       "supported (%x).\n", attr[i].value);

                err = AVERROR(EINVAL);

                goto fail;

            }

        }

        break;

        }

    }



    err = 0;

fail:

    av_freep(&profiles);

    av_freep(&entrypoints);

    return err;

}

static int vaapi_decode_make_config(AVCodecContext *avctx)

{

    VAAPIDecodeContext *ctx = avctx->internal->hwaccel_priv_data;



    AVVAAPIHWConfig       *hwconfig    = NULL;

    AVHWFramesConstraints *constraints = NULL;

    VAStatus vas;

    int err, i, j;

    const AVCodecDescriptor *codec_desc;

    VAProfile profile, *profile_list = NULL;

    int profile_count, exact_match, alt_profile;

    const AVPixFmtDescriptor *sw_desc, *desc;



    codec_desc = avcodec_descriptor_get(avctx->codec_id);

    if (!codec_desc) {

        err = AVERROR(EINVAL);

        goto fail;

    }



    profile_count = vaMaxNumProfiles(ctx->hwctx->display);

    profile_list  = av_malloc_array(profile_count,

                                    sizeof(VAProfile));

    if (!profile_list) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    vas = vaQueryConfigProfiles(ctx->hwctx->display,

                                profile_list, &profile_count);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to query profiles: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(ENOSYS);

        goto fail;

    }



    profile = VAProfileNone;

    exact_match = 0;



    for (i = 0; i < FF_ARRAY_ELEMS(vaapi_profile_map); i++) {

        int profile_match = 0;

        if (avctx->codec_id != vaapi_profile_map[i].codec_id)

            continue;

        if (avctx->profile == vaapi_profile_map[i].codec_profile ||

            vaapi_profile_map[i].codec_profile == FF_PROFILE_UNKNOWN)

            profile_match = 1;

        profile = vaapi_profile_map[i].va_profile;

        for (j = 0; j < profile_count; j++) {

            if (profile == profile_list[j]) {

                exact_match = profile_match;

                break;

            }

        }

        if (j < profile_count) {

            if (exact_match)

                break;

            alt_profile = vaapi_profile_map[i].codec_profile;

        }

    }

    av_freep(&profile_list);



    if (profile == VAProfileNone) {

        av_log(avctx, AV_LOG_ERROR, "No support for codec %s "

               "profile %d.\n", codec_desc->name, avctx->profile);

        err = AVERROR(ENOSYS);

        goto fail;

    }

    if (!exact_match) {

        if (avctx->hwaccel_flags &

            AV_HWACCEL_FLAG_ALLOW_PROFILE_MISMATCH) {

            av_log(avctx, AV_LOG_VERBOSE, "Codec %s profile %d not "

                   "supported for hardware decode.\n",

                   codec_desc->name, avctx->profile);

            av_log(avctx, AV_LOG_WARNING, "Using possibly-"

                   "incompatible profile %d instead.\n",

                   alt_profile);

        } else {

            av_log(avctx, AV_LOG_VERBOSE, "Codec %s profile %d not "

                   "supported for hardware decode.\n",

                   codec_desc->name, avctx->profile);

            err = AVERROR(EINVAL);

            goto fail;

        }

    }



    ctx->va_profile    = profile;

    ctx->va_entrypoint = VAEntrypointVLD;



    vas = vaCreateConfig(ctx->hwctx->display, ctx->va_profile,

                         ctx->va_entrypoint, NULL, 0,

                         &ctx->va_config);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create decode "

               "configuration: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    hwconfig = av_hwdevice_hwconfig_alloc(avctx->hw_device_ctx ?

                                          avctx->hw_device_ctx :

                                          ctx->frames->device_ref);

    if (!hwconfig) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    hwconfig->config_id = ctx->va_config;



    constraints =

        av_hwdevice_get_hwframe_constraints(avctx->hw_device_ctx ?

                                            avctx->hw_device_ctx :

                                            ctx->frames->device_ref,

                                            hwconfig);

    if (!constraints) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    if (avctx->coded_width  < constraints->min_width  ||

        avctx->coded_height < constraints->min_height ||

        avctx->coded_width  > constraints->max_width  ||

        avctx->coded_height > constraints->max_height) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not support image "

               "size %dx%d (constraints: width %d-%d height %d-%d).\n",

               avctx->coded_width, avctx->coded_height,

               constraints->min_width,  constraints->max_width,

               constraints->min_height, constraints->max_height);

        err = AVERROR(EINVAL);

        goto fail;

    }

    if (!constraints->valid_sw_formats ||

        constraints->valid_sw_formats[0] == AV_PIX_FMT_NONE) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not offer any "

               "usable surface formats.\n");

        err = AVERROR(EINVAL);

        goto fail;

    }



    // Find the first format in the list which matches the expected

    // bit depth and subsampling.  If none are found (this can happen

    // when 10-bit streams are decoded to 8-bit surfaces, for example)

    // then just take the first format on the list.

    ctx->surface_format = constraints->valid_sw_formats[0];

    sw_desc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);

    for (i = 0; constraints->valid_sw_formats[i] != AV_PIX_FMT_NONE; i++) {

        desc = av_pix_fmt_desc_get(constraints->valid_sw_formats[i]);

        if (desc->nb_components != sw_desc->nb_components ||

            desc->log2_chroma_w != sw_desc->log2_chroma_w ||

            desc->log2_chroma_h != sw_desc->log2_chroma_h)

            continue;

        for (j = 0; j < desc->nb_components; j++) {

            if (desc->comp[j].depth != sw_desc->comp[j].depth)

                break;

        }

        if (j < desc->nb_components)

            continue;

        ctx->surface_format = constraints->valid_sw_formats[i];

        break;

    }



    // Start with at least four surfaces.

    ctx->surface_count = 4;

    // Add per-codec number of surfaces used for storing reference frames.

    switch (avctx->codec_id) {

    case AV_CODEC_ID_H264:

    case AV_CODEC_ID_HEVC:

        ctx->surface_count += 16;

        break;

    case AV_CODEC_ID_VP9:

        ctx->surface_count += 8;

        break;

    case AV_CODEC_ID_VP8:

        ctx->surface_count += 3;

        break;

    default:

        ctx->surface_count += 2;

    }

    // Add an additional surface per thread is frame threading is enabled.

    if (avctx->active_thread_type & FF_THREAD_FRAME)

        ctx->surface_count += avctx->thread_count;



    av_hwframe_constraints_free(&constraints);

    av_freep(&hwconfig);



    return 0;



fail:

    av_hwframe_constraints_free(&constraints);

    av_freep(&hwconfig);

    if (ctx->va_config != VA_INVALID_ID) {

        vaDestroyConfig(ctx->hwctx->display, ctx->va_config);

        ctx->va_config = VA_INVALID_ID;

    }

    av_freep(&profile_list);

    return err;

}

static av_cold int vaapi_encode_h265_init_internal(AVCodecContext *avctx)

{

    static const VAConfigAttrib default_config_attributes[] = {

        { .type  = VAConfigAttribRTFormat,

          .value = VA_RT_FORMAT_YUV420 },

        { .type  = VAConfigAttribEncPackedHeaders,

          .value = (VA_ENC_PACKED_HEADER_SEQUENCE |

                    VA_ENC_PACKED_HEADER_SLICE) },

    };



    VAAPIEncodeContext      *ctx = avctx->priv_data;

    VAAPIEncodeH265Context *priv = ctx->priv_data;

    int i, err;



    switch (avctx->profile) {

    case FF_PROFILE_HEVC_MAIN:

    case FF_PROFILE_UNKNOWN:

        ctx->va_profile = VAProfileHEVCMain;

        break;

    case FF_PROFILE_HEVC_MAIN_10:

        av_log(avctx, AV_LOG_ERROR, "H.265 main 10-bit profile "

               "is not supported.\n");

        return AVERROR_PATCHWELCOME;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown H.265 profile %d.\n",

               avctx->profile);

        return AVERROR(EINVAL);

    }

    ctx->va_entrypoint = VAEntrypointEncSlice;



    ctx->input_width    = avctx->width;

    ctx->input_height   = avctx->height;

    ctx->aligned_width  = FFALIGN(ctx->input_width,  16);

    ctx->aligned_height = FFALIGN(ctx->input_height, 16);

    priv->ctu_width     = FFALIGN(ctx->aligned_width,  32) / 32;

    priv->ctu_height    = FFALIGN(ctx->aligned_height, 32) / 32;



    av_log(avctx, AV_LOG_VERBOSE, "Input %ux%u -> Aligned %ux%u -> CTU %ux%u.\n",

           ctx->input_width, ctx->input_height, ctx->aligned_width,

           ctx->aligned_height, priv->ctu_width, priv->ctu_height);



    for (i = 0; i < FF_ARRAY_ELEMS(default_config_attributes); i++) {

        ctx->config_attributes[ctx->nb_config_attributes++] =

            default_config_attributes[i];

    }



    if (avctx->bit_rate > 0) {

        ctx->va_rc_mode = VA_RC_CBR;

        err = vaapi_encode_h265_init_constant_bitrate(avctx);

    } else {

        ctx->va_rc_mode = VA_RC_CQP;

        err = vaapi_encode_h265_init_fixed_qp(avctx);

    }

    if (err < 0)

        return err;



    ctx->config_attributes[ctx->nb_config_attributes++] = (VAConfigAttrib) {

        .type  = VAConfigAttribRateControl,

        .value = ctx->va_rc_mode,

    };



    ctx->nb_recon_frames = 20;



    return 0;

}

av_cold int ff_vaapi_encode_init(AVCodecContext *avctx,

                                 const VAAPIEncodeType *type)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    AVVAAPIFramesContext *recon_hwctx = NULL;

    AVVAAPIHWConfig *hwconfig = NULL;

    AVHWFramesConstraints *constraints = NULL;

    enum AVPixelFormat recon_format;

    VAStatus vas;

    int err, i;



    if (!avctx->hw_frames_ctx) {

        av_log(avctx, AV_LOG_ERROR, "A hardware frames reference is "

               "required to associate the encoding device.\n");

        return AVERROR(EINVAL);

    }



    ctx->codec = type;

    ctx->codec_options = ctx->codec_options_data;



    ctx->va_config  = VA_INVALID_ID;

    ctx->va_context = VA_INVALID_ID;



    ctx->priv_data = av_mallocz(type->priv_data_size);

    if (!ctx->priv_data) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    ctx->input_frames_ref = av_buffer_ref(avctx->hw_frames_ctx);

    if (!ctx->input_frames_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->input_frames = (AVHWFramesContext*)ctx->input_frames_ref->data;



    ctx->device_ref = av_buffer_ref(ctx->input_frames->device_ref);

    if (!ctx->device_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->device = (AVHWDeviceContext*)ctx->device_ref->data;

    ctx->hwctx = ctx->device->hwctx;



    err = ctx->codec->init(avctx);

    if (err < 0)

        goto fail;



    err = vaapi_encode_check_config(avctx);

    if (err < 0)

        goto fail;



    vas = vaCreateConfig(ctx->hwctx->display,

                         ctx->va_profile, ctx->va_entrypoint,

                         ctx->config_attributes, ctx->nb_config_attributes,

                         &ctx->va_config);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create encode pipeline "

               "configuration: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    hwconfig = av_hwdevice_hwconfig_alloc(ctx->device_ref);

    if (!hwconfig) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    hwconfig->config_id = ctx->va_config;



    constraints = av_hwdevice_get_hwframe_constraints(ctx->device_ref,

                                                      hwconfig);

    if (!constraints) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    // Probably we can use the input surface format as the surface format

    // of the reconstructed frames.  If not, we just pick the first (only?)

    // format in the valid list and hope that it all works.

    recon_format = AV_PIX_FMT_NONE;

    if (constraints->valid_sw_formats) {

        for (i = 0; constraints->valid_sw_formats[i] != AV_PIX_FMT_NONE; i++) {

            if (ctx->input_frames->sw_format ==

                constraints->valid_sw_formats[i]) {

                recon_format = ctx->input_frames->sw_format;

                break;

            }

        }

        if (recon_format == AV_PIX_FMT_NONE) {

            // No match.  Just use the first in the supported list and

            // hope for the best.

            recon_format = constraints->valid_sw_formats[0];

        }

    } else {

        // No idea what to use; copy input format.

        recon_format = ctx->input_frames->sw_format;

    }

    av_log(avctx, AV_LOG_DEBUG, "Using %s as format of "

           "reconstructed frames.\n", av_get_pix_fmt_name(recon_format));



    if (ctx->aligned_width  < constraints->min_width  ||

        ctx->aligned_height < constraints->min_height ||

        ctx->aligned_width  > constraints->max_width ||

        ctx->aligned_height > constraints->max_height) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not support encoding at "

               "size %dx%d (constraints: width %d-%d height %d-%d).\n",

               ctx->aligned_width, ctx->aligned_height,

               constraints->min_width,  constraints->max_width,

               constraints->min_height, constraints->max_height);

        err = AVERROR(EINVAL);

        goto fail;

    }



    av_freep(&hwconfig);

    av_hwframe_constraints_free(&constraints);



    ctx->recon_frames_ref = av_hwframe_ctx_alloc(ctx->device_ref);

    if (!ctx->recon_frames_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->recon_frames = (AVHWFramesContext*)ctx->recon_frames_ref->data;



    ctx->recon_frames->format    = AV_PIX_FMT_VAAPI;

    ctx->recon_frames->sw_format = recon_format;

    ctx->recon_frames->width     = ctx->aligned_width;

    ctx->recon_frames->height    = ctx->aligned_height;

    ctx->recon_frames->initial_pool_size = ctx->nb_recon_frames;



    err = av_hwframe_ctx_init(ctx->recon_frames_ref);

    if (err < 0) {

        av_log(avctx, AV_LOG_ERROR, "Failed to initialise reconstructed "

               "frame context: %d.\n", err);

        goto fail;

    }

    recon_hwctx = ctx->recon_frames->hwctx;



    vas = vaCreateContext(ctx->hwctx->display, ctx->va_config,

                          ctx->aligned_width, ctx->aligned_height,

                          VA_PROGRESSIVE,

                          recon_hwctx->surface_ids,

                          recon_hwctx->nb_surfaces,

                          &ctx->va_context);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create encode pipeline "

               "context: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    ctx->input_order  = 0;

    ctx->output_delay = avctx->max_b_frames;

    ctx->decode_delay = 1;

    ctx->output_order = - ctx->output_delay - 1;



    if (ctx->codec->sequence_params_size > 0) {

        ctx->codec_sequence_params =

            av_mallocz(ctx->codec->sequence_params_size);

        if (!ctx->codec_sequence_params) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }

    if (ctx->codec->picture_params_size > 0) {

        ctx->codec_picture_params =

            av_mallocz(ctx->codec->picture_params_size);

        if (!ctx->codec_picture_params) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }



    if (ctx->codec->init_sequence_params) {

        err = ctx->codec->init_sequence_params(avctx);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Codec sequence initialisation "

                   "failed: %d.\n", err);

            goto fail;

        }

    }



    ctx->output_buffer_pool =

        av_buffer_pool_init2(sizeof(VABufferID), avctx,

                             &vaapi_encode_alloc_output_buffer, NULL);

    if (!ctx->output_buffer_pool) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    // All I are IDR for now.

    ctx->i_per_idr = 0;

    ctx->p_per_i = ((avctx->gop_size + avctx->max_b_frames) /

                    (avctx->max_b_frames + 1));

    ctx->b_per_p = avctx->max_b_frames;



    // This should be configurable somehow.  (Needs testing on a machine

    // where it actually overlaps properly, though.)

    ctx->issue_mode = ISSUE_MODE_MAXIMISE_THROUGHPUT;



    return 0;



fail:

    av_freep(&hwconfig);

    av_hwframe_constraints_free(&constraints);

    ff_vaapi_encode_close(avctx);

    return err;

}

static int targa_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                              const AVFrame *p, int *got_packet)

{

    TargaContext *s = avctx->priv_data;

    int bpp, picsize, datasize = -1, ret;

    uint8_t *out;



    if(avctx->width > 0xffff || avctx->height > 0xffff) {

        av_log(avctx, AV_LOG_ERROR, "image dimensions too large\n");

        return AVERROR(EINVAL);

    }

    picsize = av_image_get_buffer_size(avctx->pix_fmt,

                                       avctx->width, avctx->height, 1);

    if ((ret = ff_alloc_packet(pkt, picsize + 45)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "encoded frame too large\n");

        return ret;

    }



    /* zero out the header and only set applicable fields */

    memset(pkt->data, 0, 12);

    AV_WL16(pkt->data+12, avctx->width);

    AV_WL16(pkt->data+14, avctx->height);

    /* image descriptor byte: origin is always top-left, bits 0-3 specify alpha */

    pkt->data[17] = 0x20 | (avctx->pix_fmt == AV_PIX_FMT_BGRA ? 8 : 0);



    switch(avctx->pix_fmt) {

    case AV_PIX_FMT_GRAY8:

        pkt->data[2]  = TGA_BW;     /* uncompressed grayscale image */

        pkt->data[16] = 8;          /* bpp */

        break;

    case AV_PIX_FMT_RGB555LE:

        pkt->data[2]  = TGA_RGB;    /* uncompresses true-color image */

        pkt->data[16] = 16;         /* bpp */

        break;

    case AV_PIX_FMT_BGR24:

        pkt->data[2]  = TGA_RGB;    /* uncompressed true-color image */

        pkt->data[16] = 24;         /* bpp */

        break;

    case AV_PIX_FMT_BGRA:

        pkt->data[2]  = TGA_RGB;    /* uncompressed true-color image */

        pkt->data[16] = 32;         /* bpp */

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Pixel format '%s' not supported.\n",

               av_get_pix_fmt_name(avctx->pix_fmt));

        return AVERROR(EINVAL);

    }

    bpp = pkt->data[16] >> 3;



    out = pkt->data + 18;  /* skip past the header we just output */



#if FF_API_CODER_TYPE

FF_DISABLE_DEPRECATION_WARNINGS

    if (avctx->coder_type == FF_CODER_TYPE_RAW)

        s->rle = 0;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    /* try RLE compression */

    if (s->rle)

        datasize = targa_encode_rle(out, picsize, p, bpp, avctx->width, avctx->height);



    /* if that worked well, mark the picture as RLE compressed */

    if(datasize >= 0)

        pkt->data[2] |= 8;



    /* if RLE didn't make it smaller, go back to no compression */

    else datasize = targa_encode_normal(out, p, bpp, avctx->width, avctx->height);



    out += datasize;



    /* The standard recommends including this section, even if we don't use

     * any of the features it affords. TODO: take advantage of the pixel

     * aspect ratio and encoder ID fields available? */

    memcpy(out, "\0\0\0\0\0\0\0\0TRUEVISION-XFILE.", 26);



    pkt->size   = out + 26 - pkt->data;

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

static int decode_frame(AVCodecContext * avctx, void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    KmvcContext *const ctx = avctx->priv_data;

    uint8_t *out, *src;

    int i;

    int header;

    int blocksize;

    const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



    if (ctx->pic.data[0])

        avctx->release_buffer(avctx, &ctx->pic);



    ctx->pic.reference = 1;

    ctx->pic.buffer_hints = FF_BUFFER_HINTS_VALID;

    if (avctx->get_buffer(avctx, &ctx->pic) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    header = *buf++;



    /* blocksize 127 is really palette change event */

    if (buf[0] == 127) {

        buf += 3;

        for (i = 0; i < 127; i++) {

            ctx->pal[i + (header & 0x81)] = AV_RB24(buf);

            buf += 4;

        }

        buf -= 127 * 4 + 3;

    }



    if (header & KMVC_KEYFRAME) {

        ctx->pic.key_frame = 1;

        ctx->pic.pict_type = AV_PICTURE_TYPE_I;

    } else {

        ctx->pic.key_frame = 0;

        ctx->pic.pict_type = AV_PICTURE_TYPE_P;

    }



    if (header & KMVC_PALETTE) {

        ctx->pic.palette_has_changed = 1;

        // palette starts from index 1 and has 127 entries

        for (i = 1; i <= ctx->palsize; i++) {

            ctx->pal[i] = bytestream_get_be24(&buf);

        }

    }



    if (pal) {

        ctx->pic.palette_has_changed = 1;

        memcpy(ctx->pal, pal, AVPALETTE_SIZE);

    }



    if (ctx->setpal) {

        ctx->setpal = 0;

        ctx->pic.palette_has_changed = 1;

    }



    /* make the palette available on the way out */

    memcpy(ctx->pic.data[1], ctx->pal, 1024);



    blocksize = *buf++;



    if (blocksize != 8 && blocksize != 127) {

        av_log(avctx, AV_LOG_ERROR, "Block size = %i\n", blocksize);

        return -1;

    }

    memset(ctx->cur, 0, 320 * 200);

    switch (header & KMVC_METHOD) {

    case 0:

    case 1: // used in palette changed event

        memcpy(ctx->cur, ctx->prev, 320 * 200);

        break;

    case 3:

        kmvc_decode_intra_8x8(ctx, buf, buf_size, avctx->width, avctx->height);

        break;

    case 4:

        kmvc_decode_inter_8x8(ctx, buf, buf_size, avctx->width, avctx->height);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown compression method %i\n", header & KMVC_METHOD);

        return -1;

    }



    out = ctx->pic.data[0];

    src = ctx->cur;

    for (i = 0; i < avctx->height; i++) {

        memcpy(out, src, avctx->width);

        src += 320;

        out += ctx->pic.linesize[0];

    }



    /* flip buffers */

    if (ctx->cur == ctx->frm0) {

        ctx->cur = ctx->frm1;

        ctx->prev = ctx->frm0;

    } else {

        ctx->cur = ctx->frm0;

        ctx->prev = ctx->frm1;

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame *) data = ctx->pic;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static int targa_encode_frame(AVCodecContext *avctx,

                              unsigned char *outbuf,

                              int buf_size, void *data){

    AVFrame *p = data;

    int bpp, picsize, datasize;

    uint8_t *out;



    if(avctx->width > 0xffff || avctx->height > 0xffff) {

        av_log(avctx, AV_LOG_ERROR, "image dimensions too large\n");

        return -1;

    }

    picsize = avpicture_get_size(avctx->pix_fmt, avctx->width, avctx->height);

    if(buf_size < picsize + 45) {

        av_log(avctx, AV_LOG_ERROR, "encoded frame too large\n");

        return -1;

    }



    p->pict_type= FF_I_TYPE;

    p->key_frame= 1;



    /* zero out the header and only set applicable fields */

    memset(outbuf, 0, 11);

    AV_WL16(outbuf+12, avctx->width);

    AV_WL16(outbuf+14, avctx->height);

    outbuf[17] = 0x20;           /* origin is top-left. no alpha */



    /* TODO: support alpha channel */

    switch(avctx->pix_fmt) {

    case PIX_FMT_GRAY8:

        outbuf[2] = 3;           /* uncompressed grayscale image */

        outbuf[16] = 8;          /* bpp */

        break;

    case PIX_FMT_RGB555:

        outbuf[2] = 2;           /* uncompresses true-color image */

        outbuf[16] = 16;         /* bpp */

        break;

    case PIX_FMT_BGR24:

        outbuf[2] = 2;           /* uncompressed true-color image */

        outbuf[16] = 24;         /* bpp */

        break;

    default:

        return -1;

    }

    bpp = outbuf[16] >> 3;



    out = outbuf + 18;  /* skip past the header we just output */



    /* try RLE compression */

    datasize = targa_encode_rle(out, picsize, p, bpp, avctx->width, avctx->height);



    /* if that worked well, mark the picture as RLE compressed */

    if(datasize >= 0)

        outbuf[2] |= 8;



    /* if RLE didn't make it smaller, go back to no compression */

    else datasize = targa_encode_normal(out, p, bpp, avctx->width, avctx->height);



    out += datasize;



    /* The standard recommends including this section, even if we don't use

     * any of the features it affords. TODO: take advantage of the pixel

     * aspect ratio and encoder ID fields available? */

    memcpy(out, "\0\0\0\0\0\0\0\0TRUEVISION-XFILE.", 26);



    return out + 26 - outbuf;

}

static int yuv4_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    AVStream *st = s->streams[pkt->stream_index];

    AVIOContext *pb = s->pb;

    AVFrame *frame;

    int* first_pkt = s->priv_data;

    int width, height, h_chroma_shift, v_chroma_shift;

    int i;

    char buf2[Y4M_LINE_MAX + 1];

    uint8_t *ptr, *ptr1, *ptr2;



    frame = (AVFrame *)pkt->data;



    /* for the first packet we have to output the header as well */

    if (*first_pkt) {

        *first_pkt = 0;

        if (yuv4_generate_header(s, buf2) < 0) {

            av_log(s, AV_LOG_ERROR,

                   "Error. YUV4MPEG stream header write failed.\n");

            return AVERROR(EIO);

        } else {

            avio_write(pb, buf2, strlen(buf2));

        }

    }



    /* construct frame header */



    avio_printf(s->pb, "%s\n", Y4M_FRAME_MAGIC);



    width  = st->codecpar->width;

    height = st->codecpar->height;



    ptr = frame->data[0];



    switch (st->codecpar->format) {

    case AV_PIX_FMT_GRAY8:

    case AV_PIX_FMT_YUV411P:

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV422P:

    case AV_PIX_FMT_YUV444P:

        break;

    case AV_PIX_FMT_GRAY16:

    case AV_PIX_FMT_YUV420P9:

    case AV_PIX_FMT_YUV422P9:

    case AV_PIX_FMT_YUV444P9:

    case AV_PIX_FMT_YUV420P10:

    case AV_PIX_FMT_YUV422P10:

    case AV_PIX_FMT_YUV444P10:

    case AV_PIX_FMT_YUV420P12:

    case AV_PIX_FMT_YUV422P12:

    case AV_PIX_FMT_YUV444P12:

    case AV_PIX_FMT_YUV420P14:

    case AV_PIX_FMT_YUV422P14:

    case AV_PIX_FMT_YUV444P14:

    case AV_PIX_FMT_YUV420P16:

    case AV_PIX_FMT_YUV422P16:

    case AV_PIX_FMT_YUV444P16:

        width *= 2;

        break;

    default:

        av_log(s, AV_LOG_ERROR, "The pixel format '%s' is not supported.\n",

               av_get_pix_fmt_name(st->codecpar->format));

        return AVERROR(EINVAL);

    }



    for (i = 0; i < height; i++) {

        avio_write(pb, ptr, width);

        ptr += frame->linesize[0];

    }



    if (st->codecpar->format != AV_PIX_FMT_GRAY8 &&

        st->codecpar->format != AV_PIX_FMT_GRAY16) {

        // Adjust for smaller Cb and Cr planes

        av_pix_fmt_get_chroma_sub_sample(st->codecpar->format, &h_chroma_shift,

                                         &v_chroma_shift);

        // Shift right, rounding up

        width  = AV_CEIL_RSHIFT(width,  h_chroma_shift);

        height = AV_CEIL_RSHIFT(height, v_chroma_shift);



        ptr1 = frame->data[1];

        ptr2 = frame->data[2];

        for (i = 0; i < height; i++) {     /* Cb */

            avio_write(pb, ptr1, width);

            ptr1 += frame->linesize[1];

        }

        for (i = 0; i < height; i++) {     /* Cr */

            avio_write(pb, ptr2, width);

            ptr2 += frame->linesize[2];

        }

    }



    return 0;

}

static int scsi_req_length(SCSICommand *cmd, SCSIDevice *dev, uint8_t *buf)

{

    switch (buf[0] >> 5) {

    case 0:

        cmd->xfer = buf[4];

        cmd->len = 6;

        break;

    case 1:

    case 2:

        cmd->xfer = lduw_be_p(&buf[7]);

        cmd->len = 10;

        break;

    case 4:

        cmd->xfer = ldl_be_p(&buf[10]) & 0xffffffffULL;

        cmd->len = 16;

        break;

    case 5:

        cmd->xfer = ldl_be_p(&buf[6]) & 0xffffffffULL;

        cmd->len = 12;

        break;

    default:

        return -1;

    }



    switch (buf[0]) {

    case TEST_UNIT_READY:

    case REWIND:

    case START_STOP:

    case SET_CAPACITY:

    case WRITE_FILEMARKS:

    case WRITE_FILEMARKS_16:

    case SPACE:

    case RESERVE:

    case RELEASE:

    case ERASE:

    case ALLOW_MEDIUM_REMOVAL:

    case VERIFY_10:

    case SEEK_10:

    case SYNCHRONIZE_CACHE:

    case SYNCHRONIZE_CACHE_16:

    case LOCATE_16:

    case LOCK_UNLOCK_CACHE:

    case SET_CD_SPEED:

    case SET_LIMITS:

    case WRITE_LONG_10:

    case MOVE_MEDIUM:

    case UPDATE_BLOCK:

    case RESERVE_TRACK:

    case SET_READ_AHEAD:

    case PRE_FETCH:

    case PRE_FETCH_16:

    case ALLOW_OVERWRITE:

        cmd->xfer = 0;

        break;

    case MODE_SENSE:

        break;

    case WRITE_SAME_10:

    case WRITE_SAME_16:

        cmd->xfer = dev->blocksize;

        break;

    case READ_CAPACITY_10:

        cmd->xfer = 8;

        break;

    case READ_BLOCK_LIMITS:

        cmd->xfer = 6;

        break;

    case SEND_VOLUME_TAG:

        /* GPCMD_SET_STREAMING from multimedia commands.  */

        if (dev->type == TYPE_ROM) {

            cmd->xfer = buf[10] | (buf[9] << 8);

        } else {

            cmd->xfer = buf[9] | (buf[8] << 8);

        }

        break;

    case WRITE_6:

        /* length 0 means 256 blocks */

        if (cmd->xfer == 0) {

            cmd->xfer = 256;

        }

    case WRITE_10:

    case WRITE_VERIFY_10:

    case WRITE_12:

    case WRITE_VERIFY_12:

    case WRITE_16:

    case WRITE_VERIFY_16:

        cmd->xfer *= dev->blocksize;

        break;

    case READ_6:

    case READ_REVERSE:

        /* length 0 means 256 blocks */

        if (cmd->xfer == 0) {

            cmd->xfer = 256;

        }

    case READ_10:

    case RECOVER_BUFFERED_DATA:

    case READ_12:

    case READ_16:

        cmd->xfer *= dev->blocksize;

        break;

    case FORMAT_UNIT:

        /* MMC mandates the parameter list to be 12-bytes long.  Parameters

         * for block devices are restricted to the header right now.  */

        if (dev->type == TYPE_ROM && (buf[1] & 16)) {

            cmd->xfer = 12;

        } else {

            cmd->xfer = (buf[1] & 16) == 0 ? 0 : (buf[1] & 32 ? 8 : 4);

        }

        break;

    case INQUIRY:

    case RECEIVE_DIAGNOSTIC:

    case SEND_DIAGNOSTIC:

        cmd->xfer = buf[4] | (buf[3] << 8);

        break;

    case READ_CD:

    case READ_BUFFER:

    case WRITE_BUFFER:

    case SEND_CUE_SHEET:

        cmd->xfer = buf[8] | (buf[7] << 8) | (buf[6] << 16);

        break;

    case PERSISTENT_RESERVE_OUT:

        cmd->xfer = ldl_be_p(&buf[5]) & 0xffffffffULL;

        break;

    case ERASE_12:

        if (dev->type == TYPE_ROM) {

            /* MMC command GET PERFORMANCE.  */

            cmd->xfer = scsi_get_performance_length(buf[9] | (buf[8] << 8),

                                                    buf[10], buf[1] & 0x1f);

        }

        break;

    case MECHANISM_STATUS:

    case READ_DVD_STRUCTURE:

    case SEND_DVD_STRUCTURE:

    case MAINTENANCE_OUT:

    case MAINTENANCE_IN:

        if (dev->type == TYPE_ROM) {

            /* GPCMD_REPORT_KEY and GPCMD_SEND_KEY from multi media commands */

            cmd->xfer = buf[9] | (buf[8] << 8);

        }

        break;

    }

    return 0;

}

