static int qsv_decode_init(AVCodecContext *avctx, QSVContext *q)

{

    const AVPixFmtDescriptor *desc;

    mfxSession session = NULL;

    int iopattern = 0;

    mfxVideoParam param = { { 0 } };

    int frame_width  = avctx->coded_width;

    int frame_height = avctx->coded_height;

    int ret;



    desc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);

    if (!desc)

        return AVERROR_BUG;



    if (!q->async_fifo) {

        q->async_fifo = av_fifo_alloc((1 + q->async_depth) *

                                      (sizeof(mfxSyncPoint*) + sizeof(QSVFrame*)));

        if (!q->async_fifo)

            return AVERROR(ENOMEM);

    }



    if (avctx->pix_fmt == AV_PIX_FMT_QSV && avctx->hwaccel_context) {

        AVQSVContext *user_ctx = avctx->hwaccel_context;

        session           = user_ctx->session;

        iopattern         = user_ctx->iopattern;

        q->ext_buffers    = user_ctx->ext_buffers;

        q->nb_ext_buffers = user_ctx->nb_ext_buffers;

    }



    if (avctx->hw_frames_ctx) {

        AVHWFramesContext    *frames_ctx = (AVHWFramesContext*)avctx->hw_frames_ctx->data;

        AVQSVFramesContext *frames_hwctx = frames_ctx->hwctx;



        if (!iopattern) {

            if (frames_hwctx->frame_type & MFX_MEMTYPE_OPAQUE_FRAME)

                iopattern = MFX_IOPATTERN_OUT_OPAQUE_MEMORY;

            else if (frames_hwctx->frame_type & MFX_MEMTYPE_VIDEO_MEMORY_DECODER_TARGET)

                iopattern = MFX_IOPATTERN_OUT_VIDEO_MEMORY;

        }



        frame_width  = frames_hwctx->surfaces[0].Info.Width;

        frame_height = frames_hwctx->surfaces[0].Info.Height;

    }



    if (!iopattern)

        iopattern = MFX_IOPATTERN_OUT_SYSTEM_MEMORY;

    q->iopattern = iopattern;



    ret = qsv_init_session(avctx, q, session, avctx->hw_frames_ctx);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing an MFX session\n");

        return ret;

    }



    ret = ff_qsv_codec_id_to_mfx(avctx->codec_id);

    if (ret < 0)

        return ret;



    param.mfx.CodecId      = ret;

    param.mfx.CodecProfile = ff_qsv_profile_to_mfx(avctx->codec_id, avctx->profile);

    param.mfx.CodecLevel   = avctx->level == FF_LEVEL_UNKNOWN ? MFX_LEVEL_UNKNOWN : avctx->level;



    param.mfx.FrameInfo.BitDepthLuma   = desc->comp[0].depth;

    param.mfx.FrameInfo.BitDepthChroma = desc->comp[0].depth;

    param.mfx.FrameInfo.Shift          = desc->comp[0].depth > 8;

    param.mfx.FrameInfo.FourCC         = q->fourcc;

    param.mfx.FrameInfo.Width          = frame_width;

    param.mfx.FrameInfo.Height         = frame_height;

    param.mfx.FrameInfo.ChromaFormat   = MFX_CHROMAFORMAT_YUV420;



    switch (avctx->field_order) {

    case AV_FIELD_PROGRESSIVE:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_PROGRESSIVE;

        break;

    case AV_FIELD_TT:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_FIELD_TFF;

        break;

    case AV_FIELD_BB:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_FIELD_BFF;

        break;

    default:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_UNKNOWN;

        break;

    }



    param.IOPattern   = q->iopattern;

    param.AsyncDepth  = q->async_depth;

    param.ExtParam    = q->ext_buffers;

    param.NumExtParam = q->nb_ext_buffers;



    ret = MFXVideoDECODE_Init(q->session, &param);

    if (ret < 0)

        return ff_qsv_print_error(avctx, ret,

                                  "Error initializing the MFX video decoder");



    q->frame_info = param.mfx.FrameInfo;



    return 0;

}

int ff_nvdec_decode_init(AVCodecContext *avctx)

{

    NVDECContext *ctx = avctx->internal->hwaccel_priv_data;



    NVDECFramePool      *pool;

    AVHWFramesContext   *frames_ctx;

    const AVPixFmtDescriptor *sw_desc;



    CUVIDDECODECREATEINFO params = { 0 };



    int cuvid_codec_type, cuvid_chroma_format;

    int ret = 0;



    sw_desc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);

    if (!sw_desc)

        return AVERROR_BUG;



    cuvid_codec_type = map_avcodec_id(avctx->codec_id);

    if (cuvid_codec_type < 0) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported codec ID\n");

        return AVERROR_BUG;

    }



    cuvid_chroma_format = map_chroma_format(avctx->sw_pix_fmt);

    if (cuvid_chroma_format < 0) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported chroma format\n");

        return AVERROR(ENOSYS);

    }



    if (!avctx->hw_frames_ctx) {

        ret = ff_decode_get_hw_frames_ctx(avctx, AV_HWDEVICE_TYPE_CUDA);

        if (ret < 0)

            return ret;

    }



    frames_ctx = (AVHWFramesContext*)avctx->hw_frames_ctx->data;



    params.ulWidth             = avctx->coded_width;

    params.ulHeight            = avctx->coded_height;

    params.ulTargetWidth       = avctx->coded_width;

    params.ulTargetHeight      = avctx->coded_height;

    params.bitDepthMinus8      = sw_desc->comp[0].depth - 8;

    params.OutputFormat        = params.bitDepthMinus8 ?

                                 cudaVideoSurfaceFormat_P016 : cudaVideoSurfaceFormat_NV12;

    params.CodecType           = cuvid_codec_type;

    params.ChromaFormat        = cuvid_chroma_format;

    params.ulNumDecodeSurfaces = frames_ctx->initial_pool_size;

    params.ulNumOutputSurfaces = 1;



    ret = nvdec_decoder_create(&ctx->decoder_ref, frames_ctx->device_ref, &params, avctx);

    if (ret < 0)

        return ret;



    pool = av_mallocz(sizeof(*pool));

    if (!pool) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }

    pool->dpb_size = frames_ctx->initial_pool_size;



    ctx->decoder_pool = av_buffer_pool_init2(sizeof(int), pool,

                                             nvdec_decoder_frame_alloc, av_free);

    if (!ctx->decoder_pool) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    return 0;

fail:

    ff_nvdec_decode_uninit(avctx);

    return ret;

}

int ff_nvdec_frame_params(AVCodecContext *avctx,

                          AVBufferRef *hw_frames_ctx,

                          int dpb_size)

{

    AVHWFramesContext *frames_ctx = (AVHWFramesContext*)hw_frames_ctx->data;

    const AVPixFmtDescriptor *sw_desc;

    int cuvid_codec_type, cuvid_chroma_format;



    sw_desc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);

    if (!sw_desc)

        return AVERROR_BUG;



    cuvid_codec_type = map_avcodec_id(avctx->codec_id);

    if (cuvid_codec_type < 0) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported codec ID\n");

        return AVERROR_BUG;

    }



    cuvid_chroma_format = map_chroma_format(avctx->sw_pix_fmt);

    if (cuvid_chroma_format < 0) {

        av_log(avctx, AV_LOG_VERBOSE, "Unsupported chroma format\n");

        return AVERROR(EINVAL);

    }



    if (avctx->thread_type & FF_THREAD_FRAME)

        dpb_size += avctx->thread_count;



    frames_ctx->format            = AV_PIX_FMT_CUDA;

    frames_ctx->width             = avctx->coded_width;

    frames_ctx->height            = avctx->coded_height;

    frames_ctx->sw_format         = sw_desc->comp[0].depth > 8 ?

                                    AV_PIX_FMT_P010 : AV_PIX_FMT_NV12;

    frames_ctx->initial_pool_size = dpb_size;



    return 0;

}

int ff_dxva2_decode_init(AVCodecContext *avctx)

{

    FFDXVASharedContext *sctx = DXVA_SHARED_CONTEXT(avctx);

    AVHWFramesContext *frames_ctx = NULL;

    int ret = 0;



    // Old API.

    if (avctx->hwaccel_context)

        return 0;



    // (avctx->pix_fmt is not updated yet at this point)

    sctx->pix_fmt = avctx->hwaccel->pix_fmt;



    if (avctx->codec_id == AV_CODEC_ID_H264 &&

        (avctx->profile & ~FF_PROFILE_H264_CONSTRAINED) > FF_PROFILE_H264_HIGH) {

        av_log(avctx, AV_LOG_VERBOSE, "Unsupported H.264 profile for DXVA HWAccel: %d\n",avctx->profile);

        return AVERROR(ENOTSUP);

    }



    if (avctx->codec_id == AV_CODEC_ID_HEVC &&

        avctx->profile != FF_PROFILE_HEVC_MAIN && avctx->profile != FF_PROFILE_HEVC_MAIN_10) {

        av_log(avctx, AV_LOG_VERBOSE, "Unsupported HEVC profile for DXVA HWAccel: %d\n", avctx->profile);

        return AVERROR(ENOTSUP);

    }



    if (!avctx->hw_frames_ctx && !avctx->hw_device_ctx) {

        av_log(avctx, AV_LOG_ERROR, "Either a hw_frames_ctx or a hw_device_ctx needs to be set for hardware decoding.\n");

        return AVERROR(EINVAL);

    }



    if (avctx->hw_frames_ctx) {

        frames_ctx = (AVHWFramesContext*)avctx->hw_frames_ctx->data;

    } else {

        avctx->hw_frames_ctx = av_hwframe_ctx_alloc(avctx->hw_device_ctx);

        if (!avctx->hw_frames_ctx)

            return AVERROR(ENOMEM);



        frames_ctx = (AVHWFramesContext*)avctx->hw_frames_ctx->data;



        dxva_adjust_hwframes(avctx, frames_ctx);



        ret = av_hwframe_ctx_init(avctx->hw_frames_ctx);

        if (ret < 0)

            goto fail;

    }



    sctx->device_ctx = frames_ctx->device_ctx;



    if (frames_ctx->format != sctx->pix_fmt ||

        !((sctx->pix_fmt == AV_PIX_FMT_D3D11 && CONFIG_D3D11VA) ||

          (sctx->pix_fmt == AV_PIX_FMT_DXVA2_VLD && CONFIG_DXVA2))) {

        av_log(avctx, AV_LOG_ERROR, "Invalid pixfmt for hwaccel!\n");

        ret = AVERROR(EINVAL);

        goto fail;

    }



#if CONFIG_D3D11VA

    if (sctx->pix_fmt == AV_PIX_FMT_D3D11) {

        AVD3D11VADeviceContext *device_hwctx = frames_ctx->device_ctx->hwctx;

        AVD3D11VAContext *d3d11_ctx = &sctx->ctx.d3d11va;

        HRESULT hr;



        ff_dxva2_lock(avctx);

        ret = d3d11va_create_decoder(avctx);

        ff_dxva2_unlock(avctx);

        if (ret < 0)

            goto fail;



        d3d11_ctx->decoder       = sctx->d3d11_decoder;

        d3d11_ctx->video_context = device_hwctx->video_context;

        d3d11_ctx->cfg           = &sctx->d3d11_config;

        d3d11_ctx->surface_count = sctx->nb_d3d11_views;

        d3d11_ctx->surface       = sctx->d3d11_views;

        d3d11_ctx->workaround    = sctx->workaround;

        d3d11_ctx->context_mutex = INVALID_HANDLE_VALUE;

    }

#endif



#if CONFIG_DXVA2

    if (sctx->pix_fmt == AV_PIX_FMT_DXVA2_VLD) {

        AVDXVA2FramesContext *frames_hwctx = frames_ctx->hwctx;

        struct dxva_context *dxva_ctx = &sctx->ctx.dxva2;



        ff_dxva2_lock(avctx);

        ret = dxva2_create_decoder(avctx);

        ff_dxva2_unlock(avctx);

        if (ret < 0)

            goto fail;



        dxva_ctx->decoder       = sctx->dxva2_decoder;

        dxva_ctx->cfg           = &sctx->dxva2_config;

        dxva_ctx->surface       = frames_hwctx->surfaces;

        dxva_ctx->surface_count = frames_hwctx->nb_surfaces;

        dxva_ctx->workaround    = sctx->workaround;

    }

#endif



    return 0;



fail:

    ff_dxva2_decode_uninit(avctx);

    return ret;

}

void do_info_snapshots(Monitor *mon)

{

    DriveInfo *dinfo;

    BlockDriverState *bs, *bs1;

    QEMUSnapshotInfo *sn_tab, *sn;

    int nb_sns, i;

    char buf[256];



    bs = get_bs_snapshots();

    if (!bs) {

        monitor_printf(mon, "No available block device supports snapshots\n");

        return;

    }

    monitor_printf(mon, "Snapshot devices:");

    QTAILQ_FOREACH(dinfo, &drives, next) {

        bs1 = dinfo->bdrv;

        if (bdrv_has_snapshot(bs1)) {

            if (bs == bs1)

                monitor_printf(mon, " %s", bdrv_get_device_name(bs1));

        }

    }

    monitor_printf(mon, "\n");



    nb_sns = bdrv_snapshot_list(bs, &sn_tab);

    if (nb_sns < 0) {

        monitor_printf(mon, "bdrv_snapshot_list: error %d\n", nb_sns);

        return;

    }

    monitor_printf(mon, "Snapshot list (from %s):\n",

                   bdrv_get_device_name(bs));

    monitor_printf(mon, "%s\n", bdrv_snapshot_dump(buf, sizeof(buf), NULL));

    for(i = 0; i < nb_sns; i++) {

        sn = &sn_tab[i];

        monitor_printf(mon, "%s\n", bdrv_snapshot_dump(buf, sizeof(buf), sn));

    }

    qemu_free(sn_tab);

}

void do_delvm(Monitor *mon, const QDict *qdict)

{

    DriveInfo *dinfo;

    BlockDriverState *bs, *bs1;

    int ret;

    const char *name = qdict_get_str(qdict, "name");



    bs = get_bs_snapshots();

    if (!bs) {

        monitor_printf(mon, "No block device supports snapshots\n");

        return;

    }



    QTAILQ_FOREACH(dinfo, &drives, next) {

        bs1 = dinfo->bdrv;

        if (bdrv_has_snapshot(bs1)) {

            ret = bdrv_snapshot_delete(bs1, name);

            if (ret < 0) {

                if (ret == -ENOTSUP)

                    monitor_printf(mon,

                                   "Snapshots not supported on device '%s'\n",

                                   bdrv_get_device_name(bs1));

                else

                    monitor_printf(mon, "Error %d while deleting snapshot on "

                                   "'%s'\n", ret, bdrv_get_device_name(bs1));

            }

        }

    }

}

void hmp_info_snapshots(Monitor *mon, const QDict *qdict)

{

    BlockDriverState *bs, *bs1;

    QEMUSnapshotInfo *sn_tab, *sn, s, *sn_info = &s;

    int nb_sns, i, ret, available;

    int total;

    int *available_snapshots;



    bs = find_vmstate_bs();

    if (!bs) {

        monitor_printf(mon, "No available block device supports snapshots\n");

        return;

    }



    nb_sns = bdrv_snapshot_list(bs, &sn_tab);

    if (nb_sns < 0) {

        monitor_printf(mon, "bdrv_snapshot_list: error %d\n", nb_sns);

        return;

    }



    if (nb_sns == 0) {

        monitor_printf(mon, "There is no snapshot available.\n");

        return;

    }



    available_snapshots = g_new0(int, nb_sns);

    total = 0;

    for (i = 0; i < nb_sns; i++) {

        sn = &sn_tab[i];

        available = 1;

        bs1 = NULL;



        while ((bs1 = bdrv_next(bs1))) {

            if (bdrv_can_snapshot(bs1) && bs1 != bs) {

                ret = bdrv_snapshot_find(bs1, sn_info, sn->id_str);

                if (ret < 0) {

                    available = 0;

                    break;

                }

            }

        }



        if (available) {

            available_snapshots[total] = i;

            total++;

        }

    }



    if (total > 0) {

        bdrv_snapshot_dump((fprintf_function)monitor_printf, mon, NULL);

        monitor_printf(mon, "\n");

        for (i = 0; i < total; i++) {

            sn = &sn_tab[available_snapshots[i]];

            bdrv_snapshot_dump((fprintf_function)monitor_printf, mon, sn);

            monitor_printf(mon, "\n");

        }

    } else {

        monitor_printf(mon, "There is no suitable snapshot available\n");

    }



    g_free(sn_tab);

    g_free(available_snapshots);



}

void hmp_sendkey(Monitor *mon, const QDict *qdict)

{

    const char *keys = qdict_get_str(qdict, "keys");

    KeyValueList *keylist, *head = NULL, *tmp = NULL;

    int has_hold_time = qdict_haskey(qdict, "hold-time");

    int hold_time = qdict_get_try_int(qdict, "hold-time", -1);

    Error *err = NULL;

    char *separator;

    int keyname_len;



    while (1) {

        separator = strchr(keys, '-');

        keyname_len = separator ? separator - keys : strlen(keys);



        /* Be compatible with old interface, convert user inputted "<" */

        if (keys[0] == '<' && keyname_len == 1) {

            keys = "less";

            keyname_len = 4;

        }



        keylist = g_malloc0(sizeof(*keylist));

        keylist->value = g_malloc0(sizeof(*keylist->value));



        if (!head) {

            head = keylist;

        }

        if (tmp) {

            tmp->next = keylist;

        }

        tmp = keylist;



        if (strstart(keys, "0x", NULL)) {

            char *endp;

            int value = strtoul(keys, &endp, 0);

            assert(endp <= keys + keyname_len);

            if (endp != keys + keyname_len) {

                goto err_out;

            }

            keylist->value->type = KEY_VALUE_KIND_NUMBER;

            keylist->value->u.number = value;

        } else {

            int idx = index_from_key(keys, keyname_len);

            if (idx == Q_KEY_CODE__MAX) {

                goto err_out;

            }

            keylist->value->type = KEY_VALUE_KIND_QCODE;

            keylist->value->u.qcode = idx;

        }



        if (!separator) {

            break;

        }

        keys = separator + 1;

    }



    qmp_send_key(head, has_hold_time, hold_time, &err);

    hmp_handle_error(mon, &err);



out:

    qapi_free_KeyValueList(head);

    return;



err_out:

    monitor_printf(mon, "invalid parameter: %.*s\n", keyname_len, keys);

    goto out;

}

static int decode_block_coeffs_internal(VP56RangeCoder *r, int16_t block[16],

                                        uint8_t probs[16][3][NUM_DCT_TOKENS - 1],

                                        int i, uint8_t *token_prob,

                                        int16_t qmul[2])

{

    VP56RangeCoder c = *r;

    goto skip_eob;

    do {

        int coeff;

        if (!vp56_rac_get_prob_branchy(&c, token_prob[0]))   // DCT_EOB

            break;



skip_eob:

        if (!vp56_rac_get_prob_branchy(&c, token_prob[1])) { // DCT_0

            if (++i == 16)

                break; // invalid input; blocks should end with EOB

            token_prob = probs[i][0];

            goto skip_eob;

        }



        if (!vp56_rac_get_prob_branchy(&c, token_prob[2])) { // DCT_1

            coeff = 1;

            token_prob = probs[i + 1][1];

        } else {

            if (!vp56_rac_get_prob_branchy(&c, token_prob[3])) { // DCT 2,3,4

                coeff = vp56_rac_get_prob_branchy(&c, token_prob[4]);

                if (coeff)

                    coeff += vp56_rac_get_prob(&c, token_prob[5]);

                coeff += 2;

            } else {

                // DCT_CAT*

                if (!vp56_rac_get_prob_branchy(&c, token_prob[6])) {

                    if (!vp56_rac_get_prob_branchy(&c, token_prob[7])) { // DCT_CAT1

                        coeff = 5 + vp56_rac_get_prob(&c, vp8_dct_cat1_prob[0]);

                    } else {                                    // DCT_CAT2

                        coeff  = 7;

                        coeff += vp56_rac_get_prob(&c, vp8_dct_cat2_prob[0]) << 1;

                        coeff += vp56_rac_get_prob(&c, vp8_dct_cat2_prob[1]);

                    }

                } else {    // DCT_CAT3 and up

                    int a   = vp56_rac_get_prob(&c, token_prob[8]);

                    int b   = vp56_rac_get_prob(&c, token_prob[9 + a]);

                    int cat = (a << 1) + b;

                    coeff  = 3 + (8 << cat);

                    coeff += vp8_rac_get_coeff(&c, ff_vp8_dct_cat_prob[cat]);

                }

            }

            token_prob = probs[i + 1][2];

        }

        block[zigzag_scan[i]] = (vp8_rac_get(&c) ? -coeff : coeff) * qmul[!!i];

    } while (++i < 16);



    *r = c;

    return i;

}

static int bgr24ToYv12Wrapper(SwsContext *c, const uint8_t *src[],

                              int srcStride[], int srcSliceY, int srcSliceH,

                              uint8_t *dst[], int dstStride[])

{

    rgb24toyv12(

        src[0],

        dst[0] +  srcSliceY       * dstStride[0],

        dst[1] + (srcSliceY >> 1) * dstStride[1],

        dst[2] + (srcSliceY >> 1) * dstStride[2],

        c->srcW, srcSliceH,

        dstStride[0], dstStride[1], srcStride[0]);

    if (dst[3])

        fillPlane(dst[3], dstStride[3], c->srcW, srcSliceH, srcSliceY, 255);

    return srcSliceH;

}

