static void FUNC(sao_band_filter)(uint8_t *_dst, uint8_t *_src,

                                  ptrdiff_t stride, SAOParams *sao,

                                  int *borders, int width, int height,

                                  int c_idx, int class)

{

    pixel *dst = (pixel *)_dst;

    pixel *src = (pixel *)_src;

    int offset_table[32] = { 0 };

    int k, y, x;

    int chroma = !!c_idx;

    int shift  = BIT_DEPTH - 5;

    int *sao_offset_val = sao->offset_val[c_idx];

    int sao_left_class  = sao->band_position[c_idx];

    int init_y = 0, init_x = 0;



    stride /= sizeof(pixel);



    switch (class) {

    case 0:

        if (!borders[2])

            width -= (8 >> chroma) + 2;

        if (!borders[3])

            height -= (4 >> chroma) + 2;

        break;

    case 1:

        init_y = -(4 >> chroma) - 2;

        if (!borders[2])

            width -= (8 >> chroma) + 2;

        height = (4 >> chroma) + 2;

        break;

    case 2:

        init_x = -(8 >> chroma) - 2;

        width  =  (8 >> chroma) + 2;

        if (!borders[3])

            height -= (4 >> chroma) + 2;

        break;

    case 3:

        init_y = -(4 >> chroma) - 2;

        init_x = -(8 >> chroma) - 2;

        width  =  (8 >> chroma) + 2;

        height =  (4 >> chroma) + 2;

        break;

    }



    dst = dst + (init_y * stride + init_x);

    src = src + (init_y * stride + init_x);

    for (k = 0; k < 4; k++)

        offset_table[(k + sao_left_class) & 31] = sao_offset_val[k + 1];

    for (y = 0; y < height; y++) {

        for (x = 0; x < width; x++)

            dst[x] = av_clip_pixel(src[x] + offset_table[av_clip_pixel(src[x] >> shift)]);

        dst += stride;

        src += stride;

    }

}

static void spapr_cpu_core_realize(DeviceState *dev, Error **errp)

{

    /* We don't use SPAPR_MACHINE() in order to exit gracefully if the user

     * tries to add a sPAPR CPU core to a non-pseries machine.

     */

    sPAPRMachineState *spapr =

        (sPAPRMachineState *) object_dynamic_cast(qdev_get_machine(),

                                                  TYPE_SPAPR_MACHINE);

    sPAPRCPUCore *sc = SPAPR_CPU_CORE(OBJECT(dev));

    sPAPRCPUCoreClass *scc = SPAPR_CPU_CORE_GET_CLASS(OBJECT(dev));

    CPUCore *cc = CPU_CORE(OBJECT(dev));

    size_t size;

    Error *local_err = NULL;

    void *obj;

    int i, j;



    if (!spapr) {

        error_setg(errp, TYPE_SPAPR_CPU_CORE " needs a pseries machine");

        return;

    }



    size = object_type_get_instance_size(scc->cpu_type);

    sc->threads = g_malloc0(size * cc->nr_threads);

    for (i = 0; i < cc->nr_threads; i++) {

        char id[32];

        CPUState *cs;

        PowerPCCPU *cpu;



        obj = sc->threads + i * size;



        object_initialize(obj, size, scc->cpu_type);

        cs = CPU(obj);

        cpu = POWERPC_CPU(cs);

        cs->cpu_index = cc->core_id + i;

        cpu->vcpu_id = (cc->core_id * spapr->vsmt / smp_threads) + i;

        if (kvm_enabled() && !kvm_vcpu_id_is_valid(cpu->vcpu_id)) {

            error_setg(&local_err, "Can't create CPU with id %d in KVM",

                       cpu->vcpu_id);

            error_append_hint(&local_err, "Adjust the number of cpus to %d "

                              "or try to raise the number of threads per core\n",

                              cpu->vcpu_id * smp_threads / spapr->vsmt);

            goto err;

        }





        /* Set NUMA node for the threads belonged to core  */

        cpu->node_id = sc->node_id;



        snprintf(id, sizeof(id), "thread[%d]", i);

        object_property_add_child(OBJECT(sc), id, obj, &local_err);

        if (local_err) {

            goto err;

        }

        object_unref(obj);

    }



    for (j = 0; j < cc->nr_threads; j++) {

        obj = sc->threads + j * size;



        spapr_cpu_core_realize_child(obj, spapr, &local_err);

        if (local_err) {

            goto err;

        }

    }

    return;



err:

    while (--i >= 0) {

        obj = sc->threads + i * size;

        object_unparent(obj);

    }

    g_free(sc->threads);

    error_propagate(errp, local_err);

}

static int usb_hub_handle_data(USBDevice *dev, USBPacket *p)

{

    USBHubState *s = (USBHubState *)dev;

    int ret;



    switch(p->pid) {

    case USB_TOKEN_IN:

        if (p->devep == 1) {

            USBHubPort *port;

            unsigned int status;

            int i, n;

            n = (NUM_PORTS + 1 + 7) / 8;

            if (p->len == 1) { /* FreeBSD workaround */

                n = 1;

            } else if (n > p->len) {

                return USB_RET_BABBLE;

            }

            status = 0;

            for(i = 0; i < NUM_PORTS; i++) {

                port = &s->ports[i];

                if (port->wPortChange)

                    status |= (1 << (i + 1));

            }

            if (status != 0) {

                for(i = 0; i < n; i++) {

                    p->data[i] = status >> (8 * i);

                }

                ret = n;

            } else {

                ret = USB_RET_NAK; /* usb11 11.13.1 */

            }

        } else {

            goto fail;

        }

        break;

    case USB_TOKEN_OUT:

    default:

    fail:

        ret = USB_RET_STALL;

        break;

    }

    return ret;

}

static int uhci_broadcast_packet(UHCIState *s, USBPacket *p)

{

    int i, ret;



    DPRINTF("uhci: packet enter. pid %s addr 0x%02x ep %d len %d\n",

           pid2str(p->pid), p->devaddr, p->devep, p->len);

    if (p->pid == USB_TOKEN_OUT || p->pid == USB_TOKEN_SETUP)

        dump_data(p->data, p->len);



    ret = USB_RET_NODEV;

    for (i = 0; i < NB_PORTS && ret == USB_RET_NODEV; i++) {

        UHCIPort *port = &s->ports[i];

        USBDevice *dev = port->port.dev;



        if (dev && (port->ctrl & UHCI_PORT_EN))

            ret = usb_handle_packet(dev, p);

    }



    DPRINTF("uhci: packet exit. ret %d len %d\n", ret, p->len);

    if (p->pid == USB_TOKEN_IN && ret > 0)

        dump_data(p->data, ret);



    return ret;

}

static int usb_hub_initfn(USBDevice *dev)

{

    USBHubState *s = DO_UPCAST(USBHubState, dev, dev);

    USBHubPort *port;

    int i;



    s->dev.speed = USB_SPEED_FULL;

    for (i = 0; i < NUM_PORTS; i++) {

        port = &s->ports[i];

        usb_register_port(usb_bus_from_device(dev),

                          &port->port, s, i, &s->dev, usb_hub_attach);

        port->wPortStatus = PORT_STAT_POWER;

        port->wPortChange = 0;

    }

    return 0;

}

static int uhci_broadcast_packet(UHCIState *s, USBPacket *p)

{

    UHCIPort *port;

    USBDevice *dev;

    int i, ret;



#ifdef DEBUG_PACKET

    {

        const char *pidstr;

        switch(p->pid) {

        case USB_TOKEN_SETUP: pidstr = "SETUP"; break;

        case USB_TOKEN_IN: pidstr = "IN"; break;

        case USB_TOKEN_OUT: pidstr = "OUT"; break;

        default: pidstr = "?"; break;

        }

        printf("frame %d: pid=%s addr=0x%02x ep=%d len=%d\n",

               s->frnum, pidstr, p->devaddr, p->devep, p->len);

        if (p->pid != USB_TOKEN_IN) {

            printf("     data_out=");

            for(i = 0; i < p->len; i++) {

                printf(" %02x", p->data[i]);

            }

            printf("\n");

        }

    }

#endif

    for(i = 0; i < NB_PORTS; i++) {

        port = &s->ports[i];

        dev = port->port.dev;

        if (dev && (port->ctrl & UHCI_PORT_EN)) {

            ret = dev->handle_packet(dev, p);

            if (ret != USB_RET_NODEV) {

#ifdef DEBUG_PACKET

                if (ret == USB_RET_ASYNC) {

                    printf("usb-uhci: Async packet\n");

                } else {

                    printf("     ret=%d ", ret);

                    if (p->pid == USB_TOKEN_IN && ret > 0) {

                        printf("data_in=");

                        for(i = 0; i < ret; i++) {

                            printf(" %02x", p->data[i]);

                        }

                    }

                    printf("\n");

                }

#endif

                return ret;

            }

        }

    }

    return USB_RET_NODEV;

}

BlockDriverAIOCB *bdrv_aio_write(BlockDriverState *bs, int64_t sector_num,

                                 const uint8_t *buf, int nb_sectors,

                                 BlockDriverCompletionFunc *cb, void *opaque)

{

    BlockDriver *drv = bs->drv;

    BlockDriverAIOCB *ret;



    if (!drv)

        return NULL;

    if (bs->read_only)

        return NULL;

    if (bdrv_wr_badreq_sectors(bs, sector_num, nb_sectors))

        return NULL;

    if (sector_num == 0 && bs->boot_sector_enabled && nb_sectors > 0) {

        memcpy(bs->boot_sector_data, buf, 512);

    }



    ret = drv->bdrv_aio_write(bs, sector_num, buf, nb_sectors, cb, opaque);



    if (ret) {

	/* Update stats even though technically transfer has not happened. */

	bs->wr_bytes += (unsigned) nb_sectors * SECTOR_SIZE;

	bs->wr_ops ++;

    }



    return ret;

}

int bdrv_write_compressed(BlockDriverState *bs, int64_t sector_num,

                          const uint8_t *buf, int nb_sectors)

{

    BlockDriver *drv = bs->drv;

    if (!drv)

        return -ENOMEDIUM;

    if (!drv->bdrv_write_compressed)

        return -ENOTSUP;

    if (bdrv_check_request(bs, sector_num, nb_sectors))

        return -EIO;



    if (bs->dirty_tracking) {

        set_dirty_bitmap(bs, sector_num, nb_sectors, 1);

    }



    return drv->bdrv_write_compressed(bs, sector_num, buf, nb_sectors);

}

BlockDriverAIOCB *bdrv_aio_read(BlockDriverState *bs, int64_t sector_num,

                                uint8_t *buf, int nb_sectors,

                                BlockDriverCompletionFunc *cb, void *opaque)

{

    BlockDriver *drv = bs->drv;

    BlockDriverAIOCB *ret;



    if (!drv)

        return NULL;



    /* XXX: we assume that nb_sectors == 0 is suppored by the async read */

    if (sector_num == 0 && bs->boot_sector_enabled && nb_sectors > 0) {

        memcpy(buf, bs->boot_sector_data, 512);

        sector_num++;

        nb_sectors--;

        buf += 512;

    }



    ret = drv->bdrv_aio_read(bs, sector_num, buf, nb_sectors, cb, opaque);



    if (ret) {

	/* Update stats even though technically transfer has not happened. */

	bs->rd_bytes += (unsigned) nb_sectors * SECTOR_SIZE;

	bs->rd_ops ++;

    }



    return ret;

}

int bdrv_write(BlockDriverState *bs, int64_t sector_num,

               const uint8_t *buf, int nb_sectors)

{

    BlockDriver *drv = bs->drv;

    if (!bs->drv)

        return -ENOMEDIUM;

    if (bs->read_only)

        return -EACCES;

    if (bdrv_check_request(bs, sector_num, nb_sectors))

        return -EIO;



    return drv->bdrv_write(bs, sector_num, buf, nb_sectors);

}

av_cold void ff_init_lls_x86(LLSModel *m)

{

    int cpu_flags = av_get_cpu_flags();

    if (EXTERNAL_SSE2(cpu_flags)) {

        m->update_lls = ff_update_lls_sse2;

        if (m->indep_count >= 4)

            m->evaluate_lls = ff_evaluate_lls_sse2;

    }

    if (EXTERNAL_AVX(cpu_flags)) {

        m->update_lls = ff_update_lls_avx;

    }

}

av_cold void ff_dcadsp_init_x86(DCADSPContext *s)

{

    int cpu_flags = av_get_cpu_flags();



    if (EXTERNAL_SSE(cpu_flags)) {

#if ARCH_X86_32

        s->int8x8_fmul_int32 = ff_int8x8_fmul_int32_sse;

#endif

        s->lfe_fir[0]        = ff_dca_lfe_fir0_sse;

        s->lfe_fir[1]        = ff_dca_lfe_fir1_sse;

    }



    if (EXTERNAL_SSE2(cpu_flags)) {

        s->int8x8_fmul_int32 = ff_int8x8_fmul_int32_sse2;

    }



    if (EXTERNAL_SSE4(cpu_flags)) {

        s->int8x8_fmul_int32 = ff_int8x8_fmul_int32_sse4;

    }

}

av_cold void ff_dither_init_x86(DitherDSPContext *ddsp,

                                enum AVResampleDitherMethod method)

{

    int cpu_flags = av_get_cpu_flags();



    if (EXTERNAL_SSE2(cpu_flags)) {

        ddsp->quantize      = ff_quantize_sse2;

        ddsp->ptr_align     = 16;

        ddsp->samples_align = 8;

    }



    if (method == AV_RESAMPLE_DITHER_RECTANGULAR) {

        if (EXTERNAL_SSE2(cpu_flags)) {

            ddsp->dither_int_to_float = ff_dither_int_to_float_rectangular_sse2;

        }

        if (EXTERNAL_AVX(cpu_flags)) {

            ddsp->dither_int_to_float = ff_dither_int_to_float_rectangular_avx;

        }

    } else {

        if (EXTERNAL_SSE2(cpu_flags)) {

            ddsp->dither_int_to_float = ff_dither_int_to_float_triangular_sse2;

        }

        if (EXTERNAL_AVX(cpu_flags)) {

            ddsp->dither_int_to_float = ff_dither_int_to_float_triangular_avx;

        }

    }

}

av_cold void ff_vp8dsp_init_arm(VP8DSPContext *dsp)

{

    int cpu_flags = av_get_cpu_flags();



    if (have_armv6(cpu_flags))

        ff_vp8dsp_init_armv6(dsp);

    if (have_neon(cpu_flags))

        ff_vp8dsp_init_neon(dsp);

}

static int msrle_decode_pal4(AVCodecContext *avctx, AVPicture *pic,

                              const uint8_t *data, int data_size)

{

    int stream_ptr = 0;

    unsigned char rle_code;

    unsigned char extra_byte, odd_pixel;

    unsigned char stream_byte;

    int pixel_ptr = 0;

    int row_dec = pic->linesize[0];

    int row_ptr = (avctx->height - 1) * row_dec;

    int frame_size = row_dec * avctx->height;

    int i;



    while (row_ptr >= 0) {

        FETCH_NEXT_STREAM_BYTE();

        rle_code = stream_byte;

        if (rle_code == 0) {

            /* fetch the next byte to see how to handle escape code */

            FETCH_NEXT_STREAM_BYTE();

            if (stream_byte == 0) {

                /* line is done, goto the next one */

                row_ptr -= row_dec;

                pixel_ptr = 0;

            } else if (stream_byte == 1) {

                /* decode is done */

                return 0;

            } else if (stream_byte == 2) {

                /* reposition frame decode coordinates */

                FETCH_NEXT_STREAM_BYTE();

                pixel_ptr += stream_byte;

                FETCH_NEXT_STREAM_BYTE();

                row_ptr -= stream_byte * row_dec;

            } else {

                // copy pixels from encoded stream

                odd_pixel =  stream_byte & 1;

                rle_code = (stream_byte + 1) / 2;

                extra_byte = rle_code & 0x01;

                if (row_ptr + pixel_ptr + stream_byte > frame_size) {

                    av_log(avctx, AV_LOG_ERROR, " MS RLE: frame ptr just went out of bounds (1)\n");

                    return -1;

                }



                for (i = 0; i < rle_code; i++) {

                    if (pixel_ptr >= avctx->width)

                        break;

                    FETCH_NEXT_STREAM_BYTE();

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte >> 4;

                    pixel_ptr++;

                    if (i + 1 == rle_code && odd_pixel)

                        break;

                    if (pixel_ptr >= avctx->width)

                        break;

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte & 0x0F;

                    pixel_ptr++;

                }



                // if the RLE code is odd, skip a byte in the stream

                if (extra_byte)

                    stream_ptr++;

            }

        } else {

            // decode a run of data

            if (row_ptr + pixel_ptr + stream_byte > frame_size) {

                av_log(avctx, AV_LOG_ERROR, " MS RLE: frame ptr just went out of bounds (1)\n");

                return -1;

            }

            FETCH_NEXT_STREAM_BYTE();

            for (i = 0; i < rle_code; i++) {

                if (pixel_ptr >= avctx->width)

                    break;

                if ((i & 1) == 0)

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte >> 4;

                else

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte & 0x0F;

                pixel_ptr++;

            }

        }

    }



    /* one last sanity check on the way out */

    if (stream_ptr < data_size) {

        av_log(avctx, AV_LOG_ERROR, " MS RLE: ended frame decode with bytes left over (%d < %d)\n",

            stream_ptr, data_size);

        return -1;

    }



    return 0;

}

static int msrle_decode_8_16_24_32(AVCodecContext *avctx, AVPicture *pic,

                                   int depth, GetByteContext *gb)

{

    uint8_t *output, *output_end;

    int p1, p2, line=avctx->height - 1, pos=0, i;

    uint16_t pix16;

    uint32_t pix32;

    unsigned int width= FFABS(pic->linesize[0]) / (depth >> 3);



    output     = pic->data[0] + (avctx->height - 1) * pic->linesize[0];

    output_end = pic->data[0] +  avctx->height      * pic->linesize[0];

    while (bytestream2_get_bytes_left(gb) > 0) {

        p1 = bytestream2_get_byteu(gb);

        if(p1 == 0) { //Escape code

            p2 = bytestream2_get_byte(gb);

            if(p2 == 0) { //End-of-line

                output = pic->data[0] + (--line) * pic->linesize[0];

                if (line < 0) {

                    if (bytestream2_get_be16(gb) == 1) { // end-of-picture

                        return 0;

                    } else {

                        av_log(avctx, AV_LOG_ERROR,

                               "Next line is beyond picture bounds (%d bytes left)\n",

                               bytestream2_get_bytes_left(gb));

                        return AVERROR_INVALIDDATA;

                    }

                }

                pos = 0;

                continue;

            } else if(p2 == 1) { //End-of-picture

                return 0;

            } else if(p2 == 2) { //Skip

                p1 = bytestream2_get_byte(gb);

                p2 = bytestream2_get_byte(gb);

                line -= p2;

                pos += p1;

                if (line < 0 || pos >= width){

                    av_log(avctx, AV_LOG_ERROR, "Skip beyond picture bounds\n");

                    return -1;

                }

                output = pic->data[0] + line * pic->linesize[0] + pos * (depth >> 3);

                continue;

            }

            // Copy data

            if ((pic->linesize[0] > 0 && output + p2 * (depth >> 3) > output_end) ||

                (pic->linesize[0] < 0 && output + p2 * (depth >> 3) < output_end)) {

                bytestream2_skip(gb, 2 * (depth >> 3));

                continue;

            } else if (bytestream2_get_bytes_left(gb) < p2 * (depth >> 3)) {

                av_log(avctx, AV_LOG_ERROR, "bytestream overrun\n");

                return AVERROR_INVALIDDATA;

            }



            if ((depth == 8) || (depth == 24)) {

                for(i = 0; i < p2 * (depth >> 3); i++) {

                    *output++ = bytestream2_get_byteu(gb);

                }

                // RLE8 copy is actually padded - and runs are not!

                if(depth == 8 && (p2 & 1)) {

                    bytestream2_skip(gb, 1);

                }

            } else if (depth == 16) {

                for(i = 0; i < p2; i++) {

                    *(uint16_t*)output = bytestream2_get_le16u(gb);

                    output += 2;

                }

            } else if (depth == 32) {

                for(i = 0; i < p2; i++) {

                    *(uint32_t*)output = bytestream2_get_le32u(gb);

                    output += 4;

                }

            }

            pos += p2;

        } else { //run of pixels

            uint8_t pix[3]; //original pixel

            if ((pic->linesize[0] > 0 && output + p1 * (depth >> 3) > output_end) ||

                (pic->linesize[0] < 0 && output + p1 * (depth >> 3) < output_end))

                continue;

            switch(depth){

            case  8: pix[0] = bytestream2_get_byte(gb);

                     break;

            case 16: pix16  = bytestream2_get_le16(gb);

                     break;

            case 24: pix[0] = bytestream2_get_byte(gb);

                     pix[1] = bytestream2_get_byte(gb);

                     pix[2] = bytestream2_get_byte(gb);

                     break;

            case 32: pix32  = bytestream2_get_le32(gb);

                     break;

            }

            switch(depth){

            case  8:

                for(i = 0; i < p1; i++)

                        *output++ = pix[0];

                break;

            case 16:

                for(i = 0; i < p1; i++) {

                        *(uint16_t*)output = pix16;

                        output += 2;

                }

                break;

            case 24:

                for(i = 0; i < p1; i++) {

                        *output++ = pix[0];

                        *output++ = pix[1];

                        *output++ = pix[2];

                }

                break;

            case 32:

                for(i = 0; i < p1; i++) {

                        *(uint32_t*)output = pix32;

                        output += 4;

                }

                break;

            }

            pos += p1;

        }

    }



    av_log(avctx, AV_LOG_WARNING, "MS RLE warning: no end-of-picture code\n");

    return 0;

}

static int msrle_decode_pal4(AVCodecContext *avctx, AVFrame *pic,

                             GetByteContext *gb)

{

    unsigned char rle_code;

    unsigned char extra_byte, odd_pixel;

    unsigned char stream_byte;

    int pixel_ptr = 0;

    int line = avctx->height - 1;

    int i;



    while (line >= 0 && pixel_ptr <= avctx->width) {

        if (bytestream2_get_bytes_left(gb) <= 0) {

            av_log(avctx, AV_LOG_ERROR,

                   "MS RLE: bytestream overrun, %dx%d left\n",

                   avctx->width - pixel_ptr, line);

            return AVERROR_INVALIDDATA;

        }

        rle_code = stream_byte = bytestream2_get_byteu(gb);

        if (rle_code == 0) {

            /* fetch the next byte to see how to handle escape code */

            stream_byte = bytestream2_get_byte(gb);

            if (stream_byte == 0) {

                /* line is done, goto the next one */

                line--;

                pixel_ptr = 0;

            } else if (stream_byte == 1) {

                /* decode is done */

                return 0;

            } else if (stream_byte == 2) {

                /* reposition frame decode coordinates */

                stream_byte = bytestream2_get_byte(gb);

                pixel_ptr += stream_byte;

                stream_byte = bytestream2_get_byte(gb);

                avpriv_request_sample(avctx, "Unused stream byte %X", stream_byte);

            } else {

                // copy pixels from encoded stream

                odd_pixel =  stream_byte & 1;

                rle_code = (stream_byte + 1) / 2;

                extra_byte = rle_code & 0x01;

                if (pixel_ptr + 2*rle_code - odd_pixel > avctx->width ||

                    bytestream2_get_bytes_left(gb) < rle_code) {

                    av_log(avctx, AV_LOG_ERROR,

                           "MS RLE: frame/stream ptr just went out of bounds (copy)\n");

                    return AVERROR_INVALIDDATA;

                }



                for (i = 0; i < rle_code; i++) {

                    if (pixel_ptr >= avctx->width)

                        break;

                    stream_byte = bytestream2_get_byteu(gb);

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte >> 4;

                    pixel_ptr++;

                    if (i + 1 == rle_code && odd_pixel)

                        break;

                    if (pixel_ptr >= avctx->width)

                        break;

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte & 0x0F;

                    pixel_ptr++;

                }



                // if the RLE code is odd, skip a byte in the stream

                if (extra_byte)

                    bytestream2_skip(gb, 1);

            }

        } else {

            // decode a run of data

            if (pixel_ptr + rle_code > avctx->width + 1) {

                av_log(avctx, AV_LOG_ERROR,

                       "MS RLE: frame ptr just went out of bounds (run) %d %d %d\n", pixel_ptr, rle_code, avctx->width);

                return AVERROR_INVALIDDATA;

            }

            stream_byte = bytestream2_get_byte(gb);

            for (i = 0; i < rle_code; i++) {

                if (pixel_ptr >= avctx->width)

                    break;

                if ((i & 1) == 0)

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte >> 4;

                else

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte & 0x0F;

                pixel_ptr++;

            }

        }

    }



    /* one last sanity check on the way out */

    if (bytestream2_get_bytes_left(gb)) {

        av_log(avctx, AV_LOG_ERROR,

               "MS RLE: ended frame decode with %d bytes left over\n",

               bytestream2_get_bytes_left(gb));

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static void msrle_decode_pal8(MsrleContext *s)

{

    int stream_ptr = 0;

    unsigned char rle_code;

    unsigned char extra_byte;

    unsigned char stream_byte;

    int pixel_ptr = 0;

    int row_dec = s->frame.linesize[0];

    int row_ptr = (s->avctx->height - 1) * row_dec;

    int frame_size = row_dec * s->avctx->height;



    while (row_ptr >= 0) {

        FETCH_NEXT_STREAM_BYTE();

        rle_code = stream_byte;

        if (rle_code == 0) {

            /* fetch the next byte to see how to handle escape code */

            FETCH_NEXT_STREAM_BYTE();

            if (stream_byte == 0) {

                /* line is done, goto the next one */

                row_ptr -= row_dec;

                pixel_ptr = 0;

            } else if (stream_byte == 1) {

                /* decode is done */

                return;

            } else if (stream_byte == 2) {

                /* reposition frame decode coordinates */

                FETCH_NEXT_STREAM_BYTE();

                pixel_ptr += stream_byte;

                FETCH_NEXT_STREAM_BYTE();

                row_ptr -= stream_byte * row_dec;

            } else {

                /* copy pixels from encoded stream */

                if ((row_ptr + pixel_ptr + stream_byte > frame_size) ||

                    (row_ptr < 0)) {

                    printf(" MS RLE: frame ptr just went out of bounds (1)\n");

                    return;

                }



                rle_code = stream_byte;

                extra_byte = stream_byte & 0x01;

                if (stream_ptr + rle_code + extra_byte > s->size) {

                    printf(" MS RLE: stream ptr just went out of bounds (2)\n");

                    return;

                }



                while (rle_code--) {

                    FETCH_NEXT_STREAM_BYTE();

                    s->frame.data[0][row_ptr + pixel_ptr] = stream_byte;

                    pixel_ptr++;

                }



                /* if the RLE code is odd, skip a byte in the stream */

                if (extra_byte)

                    stream_ptr++;

            }

        } else {

            /* decode a run of data */

            if ((row_ptr + pixel_ptr + stream_byte > frame_size) ||

                (row_ptr < 0)) {

                printf(" MS RLE: frame ptr just went out of bounds (2)\n");

                return;

            }



            FETCH_NEXT_STREAM_BYTE();



            while(rle_code--) {

                s->frame.data[0][row_ptr + pixel_ptr] = stream_byte;

                pixel_ptr++;

            }

        }

    }



    /* make the palette available */

    memcpy(s->frame.data[1], s->palette, 256 * 4);



    /* one last sanity check on the way out */

    if (stream_ptr < s->size)

        printf(" MS RLE: ended frame decode with bytes left over (%d < %d)\n",

            stream_ptr, s->size);

}

uint32_t HELPER(xc)(CPUS390XState *env, uint32_t l, uint64_t dest,

                    uint64_t src)

{

    int i;

    unsigned char x;

    uint32_t cc = 0;



    HELPER_LOG("%s l %d dest %" PRIx64 " src %" PRIx64 "\n",

               __func__, l, dest, src);



#ifndef CONFIG_USER_ONLY

    /* xor with itself is the same as memset(0) */

    if ((l > 32) && (src == dest) &&

        (src & TARGET_PAGE_MASK) == ((src + l) & TARGET_PAGE_MASK)) {

        mvc_fast_memset(env, l + 1, dest, 0);

        return 0;

    }

#else

    if (src == dest) {

        memset(g2h(dest), 0, l + 1);

        return 0;

    }

#endif



    for (i = 0; i <= l; i++) {

        x = cpu_ldub_data(env, dest + i) ^ cpu_ldub_data(env, src + i);

        if (x) {

            cc = 1;

        }

        cpu_stb_data(env, dest + i, x);

    }

    return cc;

}

void HELPER(mvpg)(CPUS390XState *env, uint64_t r0, uint64_t r1, uint64_t r2)

{

    /* XXX missing r0 handling */

    env->cc_op = 0;

#ifdef CONFIG_USER_ONLY

    memmove(g2h(r1), g2h(r2), TARGET_PAGE_SIZE);

#else

    mvc_fast_memmove(env, TARGET_PAGE_SIZE, r1, r2);

#endif

}

uint32_t HELPER(mvcl)(CPUS390XState *env, uint32_t r1, uint32_t r2)

{

    uintptr_t ra = GETPC();

    uint64_t destlen = env->regs[r1 + 1] & 0xffffff;

    uint64_t dest = get_address(env, r1);

    uint64_t srclen = env->regs[r2 + 1] & 0xffffff;

    uint64_t src = get_address(env, r2);

    uint8_t pad = env->regs[r2 + 1] >> 24;

    uint8_t v;

    uint32_t cc;



    if (destlen == srclen) {

        cc = 0;

    } else if (destlen < srclen) {

        cc = 1;

    } else {

        cc = 2;

    }



    if (srclen > destlen) {

        srclen = destlen;

    }



    for (; destlen && srclen; src++, dest++, destlen--, srclen--) {

        v = cpu_ldub_data_ra(env, src, ra);

        cpu_stb_data_ra(env, dest, v, ra);

    }



    for (; destlen; dest++, destlen--) {

        cpu_stb_data_ra(env, dest, pad, ra);

    }



    env->regs[r1 + 1] = destlen;

    /* can't use srclen here, we trunc'ed it */

    env->regs[r2 + 1] -= src - env->regs[r2];

    set_address(env, r1, dest);

    set_address(env, r2, src);



    return cc;

}

void HELPER(pka)(CPUS390XState *env, uint64_t dest, uint64_t src,

                 uint32_t srclen)

{

    uintptr_t ra = GETPC();

    int i;

    /* The destination operand is always 16 bytes long.  */

    const int destlen = 16;



    /* The operands are processed from right to left.  */

    src += srclen - 1;

    dest += destlen - 1;



    for (i = 0; i < destlen; i++) {

        uint8_t b = 0;



        /* Start with a positive sign */

        if (i == 0) {

            b = 0xc;

        } else if (srclen > 1) {

            b = cpu_ldub_data_ra(env, src, ra) & 0x0f;

            src--;

            srclen--;

        }



        if (srclen > 1) {

            b |= cpu_ldub_data_ra(env, src, ra) << 4;

            src--;

            srclen--;

        }



        cpu_stb_data_ra(env, dest, b, ra);

        dest--;

    }

}

static void test_properties(const char *path)

{

    char *child_path;

    QDict *response, *tuple;

    QList *list;

    QListEntry *entry;



    g_test_message("Obtaining properties of %s", path);

    response = qmp("{ 'execute': 'qom-list',"

                   "  'arguments': { 'path': '%s' } }", path);

    g_assert(response);



    g_assert(qdict_haskey(response, "return"));

    list = qobject_to_qlist(qdict_get(response, "return"));

    QLIST_FOREACH_ENTRY(list, entry) {

        tuple = qobject_to_qdict(qlist_entry_obj(entry));

        if (strstart(qdict_get_str(tuple, "type"), "child<", NULL)) {

            child_path = g_strdup_printf("%s/%s",

                                         path, qdict_get_str(tuple, "name"));

            test_properties(child_path);

            g_free(child_path);

        } else {

            const char *prop = qdict_get_str(tuple, "name");

            g_test_message("Testing property %s.%s", path, prop);

            response = qmp("{ 'execute': 'qom-get',"

                           "  'arguments': { 'path': '%s',"

                           "                 'property': '%s' } }",

                           path, prop);

            /* qom-get may fail but should not, e.g., segfault. */

            g_assert(response);

        }

    }

}

static void event_test_emit(test_QAPIEvent event, QDict *d, Error **errp)

{

    QObject *obj;

    QDict *t;

    int64_t s, ms;



    /* Verify that we have timestamp, then remove it to compare other fields */

    obj = qdict_get(d, "timestamp");

    g_assert(obj);

    t = qobject_to_qdict(obj);

    g_assert(t);

    obj = qdict_get(t, "seconds");

    g_assert(obj && qobject_type(obj) == QTYPE_QINT);

    s = qint_get_int(qobject_to_qint(obj));

    obj = qdict_get(t, "microseconds");

    g_assert(obj && qobject_type(obj) == QTYPE_QINT);

    ms = qint_get_int(qobject_to_qint(obj));

    if (s == -1) {

        g_assert(ms == -1);

    } else {

        g_assert(ms >= 0 && ms <= 999999);

    }

    g_assert(qdict_size(t) == 2);



    qdict_del(d, "timestamp");



    g_assert(qdict_cmp_simple(d, test_event_data->expect));



}

void qpci_plug_device_test(const char *driver, const char *id,

                           uint8_t slot, const char *opts)

{

