static int qemu_rdma_register_and_get_keys(RDMAContext *rdma,

        RDMALocalBlock *block, uint8_t *host_addr,

        uint32_t *lkey, uint32_t *rkey, int chunk,

        uint8_t *chunk_start, uint8_t *chunk_end)

{

    if (block->mr) {

        if (lkey) {

            *lkey = block->mr->lkey;

        }

        if (rkey) {

            *rkey = block->mr->rkey;

        }

        return 0;

    }



    /* allocate memory to store chunk MRs */

    if (!block->pmr) {

        block->pmr = g_malloc0(block->nb_chunks * sizeof(struct ibv_mr *));

        if (!block->pmr) {

            return -1;

        }

    }



    /*

     * If 'rkey', then we're the destination, so grant access to the source.

     *

     * If 'lkey', then we're the source VM, so grant access only to ourselves.

     */

    if (!block->pmr[chunk]) {

        uint64_t len = chunk_end - chunk_start;



        DDPRINTF("Registering %" PRIu64 " bytes @ %p\n",

                 len, chunk_start);



        block->pmr[chunk] = ibv_reg_mr(rdma->pd,

                chunk_start, len,

                (rkey ? (IBV_ACCESS_LOCAL_WRITE |

                        IBV_ACCESS_REMOTE_WRITE) : 0));



        if (!block->pmr[chunk]) {

            perror("Failed to register chunk!");

            fprintf(stderr, "Chunk details: block: %d chunk index %d"

                            " start %" PRIu64 " end %" PRIu64 " host %" PRIu64

                            " local %" PRIu64 " registrations: %d\n",

                            block->index, chunk, (uint64_t) chunk_start,

                            (uint64_t) chunk_end, (uint64_t) host_addr,

                            (uint64_t) block->local_host_addr,

                            rdma->total_registrations);

            return -1;

        }

        rdma->total_registrations++;

    }



    if (lkey) {

        *lkey = block->pmr[chunk]->lkey;

    }

    if (rkey) {

        *rkey = block->pmr[chunk]->rkey;

    }

    return 0;

}

start_xmit(E1000State *s)

{

    PCIDevice *d = PCI_DEVICE(s);

    dma_addr_t base;

    struct e1000_tx_desc desc;

    uint32_t tdh_start = s->mac_reg[TDH], cause = E1000_ICS_TXQE;



    if (!(s->mac_reg[TCTL] & E1000_TCTL_EN)) {

        DBGOUT(TX, "tx disabled\n");

        return;

    }



    while (s->mac_reg[TDH] != s->mac_reg[TDT]) {

        base = tx_desc_base(s) +

               sizeof(struct e1000_tx_desc) * s->mac_reg[TDH];

        pci_dma_read(d, base, &desc, sizeof(desc));



        DBGOUT(TX, "index %d: %p : %x %x\n", s->mac_reg[TDH],

               (void *)(intptr_t)desc.buffer_addr, desc.lower.data,

               desc.upper.data);



        process_tx_desc(s, &desc);

        cause |= txdesc_writeback(s, base, &desc);



        if (++s->mac_reg[TDH] * sizeof(desc) >= s->mac_reg[TDLEN])

            s->mac_reg[TDH] = 0;

        /*

         * the following could happen only if guest sw assigns

         * bogus values to TDT/TDLEN.

         * there's nothing too intelligent we could do about this.

         */

        if (s->mac_reg[TDH] == tdh_start) {

            DBGOUT(TXERR, "TDH wraparound @%x, TDT %x, TDLEN %x\n",

                   tdh_start, s->mac_reg[TDT], s->mac_reg[TDLEN]);

            break;

        }

    }

    set_ics(s, 0, cause);

}

static uint16_t nvme_map_prp(QEMUSGList *qsg, QEMUIOVector *iov, uint64_t prp1,

                             uint64_t prp2, uint32_t len, NvmeCtrl *n)

{

    hwaddr trans_len = n->page_size - (prp1 % n->page_size);

    trans_len = MIN(len, trans_len);

    int num_prps = (len >> n->page_bits) + 1;



    if (!prp1) {

        return NVME_INVALID_FIELD | NVME_DNR;

    } else if (n->cmbsz && prp1 >= n->ctrl_mem.addr &&

               prp1 < n->ctrl_mem.addr + int128_get64(n->ctrl_mem.size)) {

        qsg->nsg = 0;

        qemu_iovec_init(iov, num_prps);

        qemu_iovec_add(iov, (void *)&n->cmbuf[prp1 - n->ctrl_mem.addr], trans_len);

    } else {

        pci_dma_sglist_init(qsg, &n->parent_obj, num_prps);

        qemu_sglist_add(qsg, prp1, trans_len);

    }

    len -= trans_len;

    if (len) {

        if (!prp2) {

            goto unmap;

        }

        if (len > n->page_size) {

            uint64_t prp_list[n->max_prp_ents];

            uint32_t nents, prp_trans;

            int i = 0;



            nents = (len + n->page_size - 1) >> n->page_bits;

            prp_trans = MIN(n->max_prp_ents, nents) * sizeof(uint64_t);

            nvme_addr_read(n, prp2, (void *)prp_list, prp_trans);

            while (len != 0) {

                uint64_t prp_ent = le64_to_cpu(prp_list[i]);



                if (i == n->max_prp_ents - 1 && len > n->page_size) {

                    if (!prp_ent || prp_ent & (n->page_size - 1)) {

                        goto unmap;

                    }



                    i = 0;

                    nents = (len + n->page_size - 1) >> n->page_bits;

                    prp_trans = MIN(n->max_prp_ents, nents) * sizeof(uint64_t);

                    nvme_addr_read(n, prp_ent, (void *)prp_list,

                        prp_trans);

                    prp_ent = le64_to_cpu(prp_list[i]);

                }



                if (!prp_ent || prp_ent & (n->page_size - 1)) {

                    goto unmap;

                }



                trans_len = MIN(len, n->page_size);

                if (qsg->nsg){

                    qemu_sglist_add(qsg, prp_ent, trans_len);

                } else {

                    qemu_iovec_add(iov, (void *)&n->cmbuf[prp_ent - n->ctrl_mem.addr], trans_len);

                }

                len -= trans_len;

                i++;

            }

        } else {

            if (prp2 & (n->page_size - 1)) {

                goto unmap;

            }

            if (qsg->nsg) {

                qemu_sglist_add(qsg, prp2, len);

            } else {

                qemu_iovec_add(iov, (void *)&n->cmbuf[prp2 - n->ctrl_mem.addr], trans_len);

            }

        }

    }

    return NVME_SUCCESS;



 unmap:

    qemu_sglist_destroy(qsg);

    return NVME_INVALID_FIELD | NVME_DNR;

}

process_tx_desc(E1000State *s, struct e1000_tx_desc *dp)

{

    PCIDevice *d = PCI_DEVICE(s);

    uint32_t txd_lower = le32_to_cpu(dp->lower.data);

    uint32_t dtype = txd_lower & (E1000_TXD_CMD_DEXT | E1000_TXD_DTYP_D);

    unsigned int split_size = txd_lower & 0xffff, bytes, sz;

    unsigned int msh = 0xfffff;

    uint64_t addr;

    struct e1000_context_desc *xp = (struct e1000_context_desc *)dp;

    struct e1000_tx *tp = &s->tx;



    s->mit_ide |= (txd_lower & E1000_TXD_CMD_IDE);

    if (dtype == E1000_TXD_CMD_DEXT) {    /* context descriptor */

        e1000x_read_tx_ctx_descr(xp, &tp->props);

        tp->tso_frames = 0;

        if (tp->props.tucso == 0) {    /* this is probably wrong */

            DBGOUT(TXSUM, "TCP/UDP: cso 0!\n");

            tp->props.tucso = tp->props.tucss + (tp->props.tcp ? 16 : 6);

        }

        return;

    } else if (dtype == (E1000_TXD_CMD_DEXT | E1000_TXD_DTYP_D)) {

        // data descriptor

        if (tp->size == 0) {

            tp->props.sum_needed = le32_to_cpu(dp->upper.data) >> 8;

        }

        tp->props.cptse = (txd_lower & E1000_TXD_CMD_TSE) ? 1 : 0;

    } else {

        // legacy descriptor

        tp->props.cptse = 0;

    }



    if (e1000x_vlan_enabled(s->mac_reg) &&

        e1000x_is_vlan_txd(txd_lower) &&

        (tp->props.cptse || txd_lower & E1000_TXD_CMD_EOP)) {

        tp->vlan_needed = 1;

        stw_be_p(tp->vlan_header,

                      le16_to_cpu(s->mac_reg[VET]));

        stw_be_p(tp->vlan_header + 2,

                      le16_to_cpu(dp->upper.fields.special));

    }



    addr = le64_to_cpu(dp->buffer_addr);

    if (tp->props.tse && tp->props.cptse) {

        msh = tp->props.hdr_len + tp->props.mss;

        do {

            bytes = split_size;

            if (tp->size + bytes > msh)

                bytes = msh - tp->size;



            bytes = MIN(sizeof(tp->data) - tp->size, bytes);

            pci_dma_read(d, addr, tp->data + tp->size, bytes);

            sz = tp->size + bytes;

            if (sz >= tp->props.hdr_len && tp->size < tp->props.hdr_len) {

                memmove(tp->header, tp->data, tp->props.hdr_len);

            }

            tp->size = sz;

            addr += bytes;

            if (sz == msh) {

                xmit_seg(s);

                memmove(tp->data, tp->header, tp->props.hdr_len);

                tp->size = tp->props.hdr_len;

            }

            split_size -= bytes;

        } while (bytes && split_size);

    } else if (!tp->props.tse && tp->props.cptse) {

        // context descriptor TSE is not set, while data descriptor TSE is set

        DBGOUT(TXERR, "TCP segmentation error\n");

    } else {

        split_size = MIN(sizeof(tp->data) - tp->size, split_size);

        pci_dma_read(d, addr, tp->data + tp->size, split_size);

        tp->size += split_size;

    }



    if (!(txd_lower & E1000_TXD_CMD_EOP))

        return;

    if (!(tp->props.tse && tp->props.cptse && tp->size < tp->props.hdr_len)) {

        xmit_seg(s);

    }

    tp->tso_frames = 0;

    tp->props.sum_needed = 0;

    tp->vlan_needed = 0;

    tp->size = 0;

    tp->props.cptse = 0;

}

e1000e_process_tx_desc(E1000ECore *core,

                       struct e1000e_tx *tx,

                       struct e1000_tx_desc *dp,

                       int queue_index)

{

    uint32_t txd_lower = le32_to_cpu(dp->lower.data);

    uint32_t dtype = txd_lower & (E1000_TXD_CMD_DEXT | E1000_TXD_DTYP_D);

    unsigned int split_size = txd_lower & 0xffff;

    uint64_t addr;

    struct e1000_context_desc *xp = (struct e1000_context_desc *)dp;

    bool eop = txd_lower & E1000_TXD_CMD_EOP;



    if (dtype == E1000_TXD_CMD_DEXT) { /* context descriptor */

        e1000x_read_tx_ctx_descr(xp, &tx->props);

        e1000e_process_snap_option(core, le32_to_cpu(xp->cmd_and_length));

        return;

    } else if (dtype == (E1000_TXD_CMD_DEXT | E1000_TXD_DTYP_D)) {

        /* data descriptor */

        tx->props.sum_needed = le32_to_cpu(dp->upper.data) >> 8;

        tx->props.cptse = (txd_lower & E1000_TXD_CMD_TSE) ? 1 : 0;

        e1000e_process_ts_option(core, dp);

    } else {

        /* legacy descriptor */

        e1000e_process_ts_option(core, dp);

        tx->props.cptse = 0;

    }



    addr = le64_to_cpu(dp->buffer_addr);



    if (!tx->skip_cp) {

        if (!net_tx_pkt_add_raw_fragment(tx->tx_pkt, addr, split_size)) {

            tx->skip_cp = true;

        }

    }



    if (eop) {

        if (!tx->skip_cp && net_tx_pkt_parse(tx->tx_pkt)) {

            if (e1000x_vlan_enabled(core->mac) &&

                e1000x_is_vlan_txd(txd_lower)) {

                net_tx_pkt_setup_vlan_header_ex(tx->tx_pkt,

                    le16_to_cpu(dp->upper.fields.special), core->vet);

            }

            if (e1000e_tx_pkt_send(core, tx, queue_index)) {

                e1000e_on_tx_done_update_stats(core, tx->tx_pkt);

            }

        }



        tx->skip_cp = false;

        net_tx_pkt_reset(tx->tx_pkt);



        tx->props.sum_needed = 0;

        tx->props.cptse = 0;

    }

}

static int create_shared_memory_BAR(IVShmemState *s, int fd, uint8_t attr,

                                    Error **errp)

{

    void * ptr;



    ptr = mmap(0, s->ivshmem_size, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);

    if (ptr == MAP_FAILED) {

        error_setg_errno(errp, errno, "Failed to mmap shared memory");

        return -1;

    }



    s->shm_fd = fd;



    memory_region_init_ram_ptr(&s->ivshmem, OBJECT(s), "ivshmem.bar2",

                               s->ivshmem_size, ptr);

    vmstate_register_ram(&s->ivshmem, DEVICE(s));

    memory_region_add_subregion(&s->bar, 0, &s->ivshmem);



    /* region for shared memory */

    pci_register_bar(PCI_DEVICE(s), 2, attr, &s->bar);



    return 0;

}

static void virtio_vga_realize(VirtIOPCIProxy *vpci_dev, Error **errp)

{

    VirtIOVGA *vvga = VIRTIO_VGA(vpci_dev);

    VirtIOGPU *g = &vvga->vdev;

    VGACommonState *vga = &vvga->vga;

    Error *err = NULL;

    uint32_t offset;

    int i;



    /* init vga compat bits */

    vga->vram_size_mb = 8;

    vga_common_init(vga, OBJECT(vpci_dev), false);

    vga_init(vga, OBJECT(vpci_dev), pci_address_space(&vpci_dev->pci_dev),

             pci_address_space_io(&vpci_dev->pci_dev), true);

    pci_register_bar(&vpci_dev->pci_dev, 0,

                     PCI_BASE_ADDRESS_MEM_PREFETCH, &vga->vram);



    /*

     * Configure virtio bar and regions

     *

     * We use bar #2 for the mmio regions, to be compatible with stdvga.

     * virtio regions are moved to the end of bar #2, to make room for

     * the stdvga mmio registers at the start of bar #2.

     */

    vpci_dev->modern_mem_bar = 2;

    vpci_dev->msix_bar = 4;

    offset = memory_region_size(&vpci_dev->modern_bar);

    offset -= vpci_dev->notify.size;

    vpci_dev->notify.offset = offset;

    offset -= vpci_dev->device.size;

    vpci_dev->device.offset = offset;

    offset -= vpci_dev->isr.size;

    vpci_dev->isr.offset = offset;

    offset -= vpci_dev->common.size;

    vpci_dev->common.offset = offset;



    /* init virtio bits */

    qdev_set_parent_bus(DEVICE(g), BUS(&vpci_dev->bus));

    /* force virtio-1.0 */

    vpci_dev->flags &= ~VIRTIO_PCI_FLAG_DISABLE_MODERN;

    vpci_dev->flags |= VIRTIO_PCI_FLAG_DISABLE_LEGACY;

    object_property_set_bool(OBJECT(g), true, "realized", &err);

    if (err) {

        error_propagate(errp, err);

        return;

    }



    /* add stdvga mmio regions */

    pci_std_vga_mmio_region_init(vga, &vpci_dev->modern_bar,

                                 vvga->vga_mrs, true);



    vga->con = g->scanout[0].con;

    graphic_console_set_hwops(vga->con, &virtio_vga_ops, vvga);



    for (i = 0; i < g->conf.max_outputs; i++) {

        object_property_set_link(OBJECT(g->scanout[i].con),

                                 OBJECT(vpci_dev),

                                 "device", errp);

    }

}

