int32_t ff_mlp_pack_output(int32_t lossless_check_data,

                           uint16_t blockpos,

                           int32_t (*sample_buffer)[MAX_CHANNELS],

                           void *data,

                           uint8_t *ch_assign,

                           int8_t *output_shift,

                           uint8_t max_matrix_channel,

                           int is32)

{

    unsigned int i, out_ch = 0;

    int32_t *data_32 = data;

    int16_t *data_16 = data;



    for (i = 0; i < blockpos; i++) {

        for (out_ch = 0; out_ch <= max_matrix_channel; out_ch++) {

            int mat_ch = ch_assign[out_ch];

            int32_t sample = sample_buffer[i][mat_ch]

                          << output_shift[mat_ch];

            lossless_check_data ^= (sample & 0xffffff) << mat_ch;

            if (is32)

                *data_32++ = sample << 8;

            else

                *data_16++ = sample >> 8;

        }

    }

    return lossless_check_data;

}

static int hevc_find_frame_end(AVCodecParserContext *s, const uint8_t *buf,

                               int buf_size)

{

    HEVCParserContext *ctx = s->priv_data;

    ParseContext       *pc = &ctx->pc;

    int i;



    for (i = 0; i < buf_size; i++) {

        int nut;



        pc->state64 = (pc->state64 << 8) | buf[i];



        if (((pc->state64 >> 3 * 8) & 0xFFFFFF) != START_CODE)

            continue;



        nut = (pc->state64 >> 2 * 8 + 1) & 0x3F;

        // Beginning of access unit

        if ((nut >= HEVC_NAL_VPS && nut <= HEVC_NAL_AUD) || nut == HEVC_NAL_SEI_PREFIX ||

            (nut >= 41 && nut <= 44) || (nut >= 48 && nut <= 55)) {

            if (pc->frame_start_found) {

                pc->frame_start_found = 0;

                return i - 5;

            }

        } else if (nut <= HEVC_NAL_RASL_R ||

                   (nut >= HEVC_NAL_BLA_W_LP && nut <= HEVC_NAL_CRA_NUT)) {

            int first_slice_segment_in_pic_flag = buf[i] >> 7;

            if (first_slice_segment_in_pic_flag) {

                if (!pc->frame_start_found) {

                    pc->frame_start_found = 1;

                } else { // First slice of next frame found

                    pc->frame_start_found = 0;

                    return i - 5;

                }

            }

        }

    }



    return END_NOT_FOUND;

}

static void exponents_from_scale_factors(MPADecodeContext *s,

                                         GranuleDef *g,

                                         int16_t *exponents)

{

    const uint8_t *bstab, *pretab;

    int len, i, j, k, l, v0, shift, gain, gains[3];

    int16_t *exp_ptr;



    exp_ptr = exponents;

    gain = g->global_gain - 210;

    shift = g->scalefac_scale + 1;



    bstab = band_size_long[s->sample_rate_index];

    pretab = mpa_pretab[g->preflag];

    for(i=0;i<g->long_end;i++) {

        v0 = gain - ((g->scale_factors[i] + pretab[i]) << shift);

        len = bstab[i];

        for(j=len;j>0;j--)

            *exp_ptr++ = v0;

    }



    if (g->short_start < 13) {

        bstab = band_size_short[s->sample_rate_index];

        gains[0] = gain - (g->subblock_gain[0] << 3);

        gains[1] = gain - (g->subblock_gain[1] << 3);

        gains[2] = gain - (g->subblock_gain[2] << 3);

        k = g->long_end;

        for(i=g->short_start;i<13;i++) {

            len = bstab[i];

            for(l=0;l<3;l++) {

                v0 = gains[l] - (g->scale_factors[k++] << shift);

                for(j=len;j>0;j--)

                *exp_ptr++ = v0;

            }

        }

    }

}

static AVFilterBufferRef *get_video_buffer(AVFilterLink *link, int perms,

                                        int w, int h)

{

    FlipContext *flip = link->dst->priv;

    int i;



    AVFilterBufferRef *picref = avfilter_get_video_buffer(link->dst->outputs[0],

                                                       perms, w, h);



    for (i = 0; i < 4; i ++) {

        int vsub = i == 1 || i == 2 ? flip->vsub : 0;



        if (picref->data[i]) {

            picref->data[i] += ((h >> vsub)-1) * picref->linesize[i];

            picref->linesize[i] = -picref->linesize[i];

        }

    }



    return picref;

}

