    } else if (mvn == 2) { /* duplicate motion data for 2-Field MV block */

        s->current_picture.motion_val[dir][xy + 1][0] = s->current_picture.motion_val[dir][xy][0];

        s->current_picture.motion_val[dir][xy + 1][1] = s->current_picture.motion_val[dir][xy][1];

        s->mv[dir][n + 1][0] = s->mv[dir][n][0];

        s->mv[dir][n + 1][1] = s->mv[dir][n][1];

    }

}

static int unix_get_buffer(void *opaque, uint8_t *buf, int64_t pos, int size)

{

    QEMUFileSocket *s = opaque;

    ssize_t len;



    for (;;) {

        len = read(s->fd, buf, size);

        if (len != -1) {

            break;

        }

        if (errno == EAGAIN) {

            yield_until_fd_readable(s->fd);

        } else if (errno != EINTR) {

            break;

        }

    }



    if (len == -1) {

        len = -errno;

    }

    return len;

}

static int read_packet(ByteIOContext *pb, uint8_t *buf, int raw_packet_size)

{

    int skip, len;



    for(;;) {

        len = get_buffer(pb, buf, TS_PACKET_SIZE);

        if (len != TS_PACKET_SIZE)

            return AVERROR(EIO);

        /* check paquet sync byte */

        if (buf[0] != 0x47) {

            /* find a new packet start */

            url_fseek(pb, -TS_PACKET_SIZE, SEEK_CUR);

            if (mpegts_resync(pb) < 0)

                return AVERROR_INVALIDDATA;

            else

                continue;

        } else {

            skip = raw_packet_size - TS_PACKET_SIZE;

            if (skip > 0)

                url_fskip(pb, skip);

            break;

        }

    }

    return 0;

}

static int udp_write(URLContext *h, const uint8_t *buf, int size)

{

    UDPContext *s = h->priv_data;

    int ret;



    for(;;) {

        if (!s->is_connected) {

            ret = sendto (s->udp_fd, buf, size, 0,

                          (struct sockaddr *) &s->dest_addr,

                          s->dest_addr_len);

        } else

            ret = send(s->udp_fd, buf, size, 0);

        if (ret < 0) {

            if (ff_neterrno() != AVERROR(EINTR) &&

                ff_neterrno() != AVERROR(EAGAIN))

                return ff_neterrno();

        } else {

            break;

        }

    }

    return size;

}

static int check(AVIOContext *pb, int64_t pos, int64_t *out_pos)

{

    MPADecodeHeader mh = { 0 };

    int i;

    uint32_t header;

    int64_t off = 0;





    for (i = 0; i < SEEK_PACKETS; i++) {

        off = avio_seek(pb, pos + mh.frame_size, SEEK_SET);

        if (off < 0)

            break;



        header = avio_rb32(pb);



        if (ff_mpa_check_header(header) < 0 ||

            avpriv_mpegaudio_decode_header(&mh, header))

            break;

        out_pos[i] = off;

    }



    return i;

}

int64_t parse_time_or_die(const char *context, const char *timestr,

                          int is_duration)

{

    int64_t us;

    if (av_parse_time(&us, timestr, is_duration) < 0) {

        av_log(NULL, AV_LOG_FATAL, "Invalid %s specification for %s: %s\n",

               is_duration ? "duration" : "date", context, timestr);

        exit(1);

    }

    return us;

}

int ff_parse_packing_format(int *ret, const char *arg, void *log_ctx)

{

    char *tail;

    int planar = strtol(arg, &tail, 10);

    if (*tail) {

        planar = (strcmp(arg, "packed") != 0);

    } else if (planar != 0 && planar != 1) {

        av_log(log_ctx, AV_LOG_ERROR, "Invalid packing format '%s'\n", arg);

        return AVERROR(EINVAL);

    }

    *ret = planar;

    return 0;

}

int av_image_check_size(unsigned int w, unsigned int h, int log_offset, void *log_ctx)

{

    ImgUtils imgutils = { &imgutils_class, log_offset, log_ctx };



    if ((int)w>0 && (int)h>0 && (w+128)*(uint64_t)(h+128) < INT_MAX/8)

        return 0;



    av_log(&imgutils, AV_LOG_ERROR, "Picture size %ux%u is invalid\n", w, h);

    return AVERROR(EINVAL);

}

static int set_expr(AVExpr **pexpr, const char *expr, void *log_ctx)

{

    int ret;

    AVExpr *old = NULL;



    if (*pexpr)

        old = *pexpr;

    ret = av_expr_parse(pexpr, expr, var_names,

                        NULL, NULL, NULL, NULL, 0, log_ctx);

    if (ret < 0) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Error when evaluating the expression '%s'\n", expr);

        *pexpr = old;

        return ret;

    }



    av_expr_free(old);

    return 0;

}

static void decode_src_opc(CPUTriCoreState *env, DisasContext *ctx, int op1)

{

    int r1;

    int32_t const4;

    TCGv temp, temp2;



    r1 = MASK_OP_SRC_S1D(ctx->opcode);

    const4 = MASK_OP_SRC_CONST4_SEXT(ctx->opcode);



    switch (op1) {

    case OPC1_16_SRC_ADD:

        gen_addi_d(cpu_gpr_d[r1], cpu_gpr_d[r1], const4);

        break;

    case OPC1_16_SRC_ADD_A15:

        gen_addi_d(cpu_gpr_d[r1], cpu_gpr_d[15], const4);

        break;

    case OPC1_16_SRC_ADD_15A:

        gen_addi_d(cpu_gpr_d[15], cpu_gpr_d[r1], const4);

        break;

    case OPC1_16_SRC_ADD_A:

        tcg_gen_addi_tl(cpu_gpr_a[r1], cpu_gpr_a[r1], const4);

        break;

    case OPC1_16_SRC_CADD:

        gen_condi_add(TCG_COND_NE, cpu_gpr_d[r1], const4, cpu_gpr_d[r1],

                      cpu_gpr_d[15]);

        break;

    case OPC1_16_SRC_CADDN:

        gen_condi_add(TCG_COND_EQ, cpu_gpr_d[r1], const4, cpu_gpr_d[r1],

                      cpu_gpr_d[15]);

        break;

    case OPC1_16_SRC_CMOV:

        temp = tcg_const_tl(0);

        temp2 = tcg_const_tl(const4);

        tcg_gen_movcond_tl(TCG_COND_NE, cpu_gpr_d[r1], cpu_gpr_d[15], temp,

                           temp2, cpu_gpr_d[r1]);

        tcg_temp_free(temp);

        tcg_temp_free(temp2);

        break;

    case OPC1_16_SRC_CMOVN:

        temp = tcg_const_tl(0);

        temp2 = tcg_const_tl(const4);

        tcg_gen_movcond_tl(TCG_COND_EQ, cpu_gpr_d[r1], cpu_gpr_d[15], temp,

                           temp2, cpu_gpr_d[r1]);

        tcg_temp_free(temp);

        tcg_temp_free(temp2);

        break;

    case OPC1_16_SRC_EQ:

        tcg_gen_setcondi_tl(TCG_COND_EQ, cpu_gpr_d[15], cpu_gpr_d[r1],

                            const4);

        break;

    case OPC1_16_SRC_LT:

        tcg_gen_setcondi_tl(TCG_COND_LT, cpu_gpr_d[15], cpu_gpr_d[r1],

                            const4);

        break;

    case OPC1_16_SRC_MOV:

        tcg_gen_movi_tl(cpu_gpr_d[r1], const4);

        break;

    case OPC1_16_SRC_MOV_A:

        const4 = MASK_OP_SRC_CONST4(ctx->opcode);

        tcg_gen_movi_tl(cpu_gpr_a[r1], const4);

        break;

    case OPC1_16_SRC_MOV_E:

        if (tricore_feature(env, TRICORE_FEATURE_16)) {

            tcg_gen_movi_tl(cpu_gpr_d[r1], const4);

            tcg_gen_sari_tl(cpu_gpr_d[r1+1], cpu_gpr_d[r1], 31);

        } /* TODO: else raise illegal opcode trap */

        break;

    case OPC1_16_SRC_SH:

        gen_shi(cpu_gpr_d[r1], cpu_gpr_d[r1], const4);

        break;

    case OPC1_16_SRC_SHA:

        gen_shaci(cpu_gpr_d[r1], cpu_gpr_d[r1], const4);

        break;

    }

}

static void decode_rr_divide(CPUTriCoreState *env, DisasContext *ctx)

{

    uint32_t op2;

    int r1, r2, r3;



    TCGv temp, temp2;



    op2 = MASK_OP_RR_OP2(ctx->opcode);

    r3 = MASK_OP_RR_D(ctx->opcode);

    r2 = MASK_OP_RR_S2(ctx->opcode);

    r1 = MASK_OP_RR_S1(ctx->opcode);



    switch (op2) {

    case OPC2_32_RR_BMERGE:

        gen_helper_bmerge(cpu_gpr_d[r3], cpu_gpr_d[r1], cpu_gpr_d[r2]);

        break;

    case OPC2_32_RR_BSPLIT:

        gen_bsplit(cpu_gpr_d[r3], cpu_gpr_d[r3+1], cpu_gpr_d[r1]);

        break;

    case OPC2_32_RR_DVINIT_B:

        gen_dvinit_b(env, cpu_gpr_d[r3], cpu_gpr_d[r3+1], cpu_gpr_d[r1],

                     cpu_gpr_d[r2]);

        break;

    case OPC2_32_RR_DVINIT_BU:

        temp = tcg_temp_new();

        temp2 = tcg_temp_new();

        /* reset av */

        tcg_gen_movi_tl(cpu_PSW_AV, 0);

        if (!tricore_feature(env, TRICORE_FEATURE_131)) {

            /* overflow = (abs(D[r3+1]) >= abs(D[r2])) */

            tcg_gen_neg_tl(temp, cpu_gpr_d[r3+1]);

            /* use cpu_PSW_AV to compare against 0 */

            tcg_gen_movcond_tl(TCG_COND_LT, temp, cpu_gpr_d[r3+1], cpu_PSW_AV,

                               temp, cpu_gpr_d[r3+1]);

            tcg_gen_neg_tl(temp2, cpu_gpr_d[r2]);

            tcg_gen_movcond_tl(TCG_COND_LT, temp2, cpu_gpr_d[r2], cpu_PSW_AV,

                               temp2, cpu_gpr_d[r2]);

            tcg_gen_setcond_tl(TCG_COND_GE, cpu_PSW_V, temp, temp2);

        } else {

            /* overflow = (D[b] == 0) */

            tcg_gen_setcondi_tl(TCG_COND_EQ, cpu_PSW_V, cpu_gpr_d[r2], 0);

        }

        tcg_gen_shli_tl(cpu_PSW_V, cpu_PSW_V, 31);

        /* sv */

        tcg_gen_or_tl(cpu_PSW_SV, cpu_PSW_SV, cpu_PSW_V);

        /* write result */

        tcg_gen_shri_tl(temp, cpu_gpr_d[r1], 8);

        tcg_gen_shli_tl(cpu_gpr_d[r3], cpu_gpr_d[r1], 24);

        tcg_gen_mov_tl(cpu_gpr_d[r3+1], temp);



        tcg_temp_free(temp);

        tcg_temp_free(temp2);

        break;

    case OPC2_32_RR_DVINIT_H:

        gen_dvinit_h(env, cpu_gpr_d[r3], cpu_gpr_d[r3+1], cpu_gpr_d[r1],

                     cpu_gpr_d[r2]);

        break;

    case OPC2_32_RR_DVINIT_HU:

        temp = tcg_temp_new();

        temp2 = tcg_temp_new();

        /* reset av */

        tcg_gen_movi_tl(cpu_PSW_AV, 0);

        if (!tricore_feature(env, TRICORE_FEATURE_131)) {

            /* overflow = (abs(D[r3+1]) >= abs(D[r2])) */

            tcg_gen_neg_tl(temp, cpu_gpr_d[r3+1]);

            /* use cpu_PSW_AV to compare against 0 */

            tcg_gen_movcond_tl(TCG_COND_LT, temp, cpu_gpr_d[r3+1], cpu_PSW_AV,

                               temp, cpu_gpr_d[r3+1]);

            tcg_gen_neg_tl(temp2, cpu_gpr_d[r2]);

            tcg_gen_movcond_tl(TCG_COND_LT, temp2, cpu_gpr_d[r2], cpu_PSW_AV,

                               temp2, cpu_gpr_d[r2]);

            tcg_gen_setcond_tl(TCG_COND_GE, cpu_PSW_V, temp, temp2);

        } else {

            /* overflow = (D[b] == 0) */

            tcg_gen_setcondi_tl(TCG_COND_EQ, cpu_PSW_V, cpu_gpr_d[r2], 0);

        }

        tcg_gen_shli_tl(cpu_PSW_V, cpu_PSW_V, 31);

        /* sv */

        tcg_gen_or_tl(cpu_PSW_SV, cpu_PSW_SV, cpu_PSW_V);

        /* write result */

        tcg_gen_mov_tl(temp, cpu_gpr_d[r1]);

        tcg_gen_shri_tl(cpu_gpr_d[r3+1], temp, 16);

        tcg_gen_shli_tl(cpu_gpr_d[r3], temp, 16);

        tcg_temp_free(temp);

        tcg_temp_free(temp2);

        break;

    case OPC2_32_RR_DVINIT:

        temp = tcg_temp_new();

        temp2 = tcg_temp_new();

        /* overflow = ((D[b] == 0) ||

                      ((D[b] == 0xFFFFFFFF) && (D[a] == 0x80000000))) */

        tcg_gen_setcondi_tl(TCG_COND_EQ, temp, cpu_gpr_d[r2], 0xffffffff);

        tcg_gen_setcondi_tl(TCG_COND_EQ, temp2, cpu_gpr_d[r1], 0x80000000);

        tcg_gen_and_tl(temp, temp, temp2);

        tcg_gen_setcondi_tl(TCG_COND_EQ, temp2, cpu_gpr_d[r2], 0);

        tcg_gen_or_tl(cpu_PSW_V, temp, temp2);

        tcg_gen_shli_tl(cpu_PSW_V, cpu_PSW_V, 31);

        /* sv */

        tcg_gen_or_tl(cpu_PSW_SV, cpu_PSW_SV, cpu_PSW_V);

        /* reset av */

       tcg_gen_movi_tl(cpu_PSW_AV, 0);

        /* write result */

        tcg_gen_mov_tl(cpu_gpr_d[r3], cpu_gpr_d[r1]);

        /* sign extend to high reg */

        tcg_gen_sari_tl(cpu_gpr_d[r3+1], cpu_gpr_d[r1], 31);

        tcg_temp_free(temp);

        tcg_temp_free(temp2);

        break;

    case OPC2_32_RR_DVINIT_U:

        /* overflow = (D[b] == 0) */

        tcg_gen_setcondi_tl(TCG_COND_EQ, cpu_PSW_V, cpu_gpr_d[r2], 0);

        tcg_gen_shli_tl(cpu_PSW_V, cpu_PSW_V, 31);

        /* sv */

        tcg_gen_or_tl(cpu_PSW_SV, cpu_PSW_SV, cpu_PSW_V);

        /* reset av */

        tcg_gen_movi_tl(cpu_PSW_AV, 0);

        /* write result */

        tcg_gen_mov_tl(cpu_gpr_d[r3], cpu_gpr_d[r1]);

        /* zero extend to high reg*/

        tcg_gen_movi_tl(cpu_gpr_d[r3+1], 0);

        break;

    case OPC2_32_RR_PARITY:

        gen_helper_parity(cpu_gpr_d[r3], cpu_gpr_d[r1]);

        break;

    case OPC2_32_RR_UNPACK:

        gen_unpack(cpu_gpr_d[r3], cpu_gpr_d[r3+1], cpu_gpr_d[r1]);

        break;

    }

}

static void gen_srs(DisasContext *s,

                    uint32_t mode, uint32_t amode, bool writeback)

{

    int32_t offset;

    TCGv_i32 addr = tcg_temp_new_i32();

    TCGv_i32 tmp = tcg_const_i32(mode);

    gen_helper_get_r13_banked(addr, cpu_env, tmp);

    tcg_temp_free_i32(tmp);

    switch (amode) {

    case 0: /* DA */

        offset = -4;

        break;

    case 1: /* IA */

        offset = 0;

        break;

    case 2: /* DB */

        offset = -8;

        break;

    case 3: /* IB */

        offset = 4;

        break;

    default:

        abort();

    }

    tcg_gen_addi_i32(addr, addr, offset);

    tmp = load_reg(s, 14);

    gen_aa32_st32(tmp, addr, get_mem_index(s));

    tcg_temp_free_i32(tmp);

    tmp = load_cpu_field(spsr);

    tcg_gen_addi_i32(addr, addr, 4);

    gen_aa32_st32(tmp, addr, get_mem_index(s));

    tcg_temp_free_i32(tmp);

    if (writeback) {

        switch (amode) {

        case 0:

            offset = -8;

            break;

        case 1:

            offset = 4;

            break;

        case 2:

            offset = -4;

            break;

        case 3:

            offset = 0;

            break;

        default:

            abort();

        }

        tcg_gen_addi_i32(addr, addr, offset);

        tmp = tcg_const_i32(mode);

        gen_helper_set_r13_banked(cpu_env, tmp, addr);

        tcg_temp_free_i32(tmp);

    }

    tcg_temp_free_i32(addr);

}

static void gen_cp1 (DisasContext *ctx, uint32_t opc, int rt, int fs)

{

    const char *opn = "cp1 move";

    TCGv t0 = tcg_temp_new();



    switch (opc) {

    case OPC_MFC1:

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            gen_load_fpr32(fp0, fs);

            tcg_gen_ext_i32_tl(t0, fp0);

            tcg_temp_free_i32(fp0);

        }

        gen_store_gpr(t0, rt);

        opn = "mfc1";

        break;

    case OPC_MTC1:

        gen_load_gpr(t0, rt);

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            tcg_gen_trunc_tl_i32(fp0, t0);

            gen_store_fpr32(fp0, fs);

            tcg_temp_free_i32(fp0);

        }

        opn = "mtc1";

        break;

    case OPC_CFC1:

        gen_helper_1e0i(cfc1, t0, fs);

        gen_store_gpr(t0, rt);

        opn = "cfc1";

        break;

    case OPC_CTC1:

        gen_load_gpr(t0, rt);

        {

            TCGv_i32 fs_tmp = tcg_const_i32(fs);



            gen_helper_0e2i(ctc1, t0, fs_tmp, rt);

            tcg_temp_free_i32(fs_tmp);

        }

        opn = "ctc1";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DMFC1:

        gen_load_fpr64(ctx, t0, fs);

        gen_store_gpr(t0, rt);

        opn = "dmfc1";

        break;

    case OPC_DMTC1:

        gen_load_gpr(t0, rt);

        gen_store_fpr64(ctx, t0, fs);

        opn = "dmtc1";

        break;

#endif

    case OPC_MFHC1:

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            gen_load_fpr32h(fp0, fs);

            tcg_gen_ext_i32_tl(t0, fp0);

            tcg_temp_free_i32(fp0);

        }

        gen_store_gpr(t0, rt);

        opn = "mfhc1";

        break;

    case OPC_MTHC1:

        gen_load_gpr(t0, rt);

        {

            TCGv_i32 fp0 = tcg_temp_new_i32();



            tcg_gen_trunc_tl_i32(fp0, t0);

            gen_store_fpr32h(fp0, fs);

            tcg_temp_free_i32(fp0);

        }

        opn = "mthc1";

        break;

    default:

        MIPS_INVAL(opn);

        generate_exception (ctx, EXCP_RI);

        goto out;

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s %s", opn, regnames[rt], fregnames[fs]);



 out:

    tcg_temp_free(t0);

}

static void v9fs_readlink(void *opaque)

{

    V9fsPDU *pdu = opaque;

    size_t offset = 7;

    V9fsString target;

    int32_t fid;

    int err = 0;

    V9fsFidState *fidp;



    pdu_unmarshal(pdu, offset, "d", &fid);


    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }



    v9fs_string_init(&target);

    err = v9fs_co_readlink(pdu, &fidp->path, &target);

    if (err < 0) {

        goto out;

    }

    offset += pdu_marshal(pdu, offset, "s", &target);

    err = offset;

    v9fs_string_free(&target);

out:

    put_fid(pdu, fidp);

out_nofid:

    trace_v9fs_readlink_return(pdu->tag, pdu->id, target.data);

    complete_pdu(pdu->s, pdu, err);

}

static void v9fs_statfs(void *opaque)

{

    int32_t fid;

    ssize_t retval = 0;

    size_t offset = 7;

    V9fsFidState *fidp;

    struct statfs stbuf;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "d", &fid);

    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        retval = -ENOENT;

        goto out_nofid;

    }

    retval = v9fs_co_statfs(pdu, &fidp->path, &stbuf);

    if (retval < 0) {

        goto out;

    }

    retval = offset;

    retval += v9fs_fill_statfs(s, pdu, &stbuf);

out:

    put_fid(pdu, fidp);

out_nofid:

    complete_pdu(s, pdu, retval);

    return;

}

static void v9fs_lock(void *opaque)

{

    int8_t status;

    V9fsFlock *flock;

    size_t offset = 7;

    struct stat stbuf;

    V9fsFidState *fidp;

    int32_t fid, err = 0;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    flock = g_malloc(sizeof(*flock));

    pdu_unmarshal(pdu, offset, "dbdqqds", &fid, &flock->type,

                  &flock->flags, &flock->start, &flock->length,

                  &flock->proc_id, &flock->client_id);



    trace_v9fs_lock(pdu->tag, pdu->id, fid,

                    flock->type, flock->start, flock->length);



    status = P9_LOCK_ERROR;



    /* We support only block flag now (that too ignored currently) */

    if (flock->flags & ~P9_LOCK_FLAGS_BLOCK) {

        err = -EINVAL;

        goto out_nofid;

    }

    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    err = v9fs_co_fstat(pdu, fidp, &stbuf);

    if (err < 0) {

        goto out;

    }

    status = P9_LOCK_SUCCESS;

out:

    put_fid(pdu, fidp);

out_nofid:

    err = offset;

    err += pdu_marshal(pdu, offset, "b", status);

    trace_v9fs_lock_return(pdu->tag, pdu->id, status);

    complete_pdu(s, pdu, err);

    v9fs_string_free(&flock->client_id);

    g_free(flock);

}

static void v9fs_lcreate(void *opaque)

{

    int32_t dfid, flags, mode;

    gid_t gid;

    ssize_t err = 0;

    ssize_t offset = 7;

    V9fsString name;

    V9fsFidState *fidp;

    struct stat stbuf;

    V9fsQID qid;

    int32_t iounit;

    V9fsPDU *pdu = opaque;



    pdu_unmarshal(pdu, offset, "dsddd", &dfid, &name, &flags,

                  &mode, &gid);

    trace_v9fs_lcreate(pdu->tag, pdu->id, dfid, flags, mode, gid);



    fidp = get_fid(pdu, dfid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }



    flags = get_dotl_openflags(pdu->s, flags);

    err = v9fs_co_open2(pdu, fidp, &name, gid,

                        flags | O_CREAT, mode, &stbuf);

    if (err < 0) {

        goto out;

    }

    fidp->fid_type = P9_FID_FILE;

    fidp->open_flags = flags;

    if (flags & O_EXCL) {

        /*

         * We let the host file system do O_EXCL check

         * We should not reclaim such fd

         */

        fidp->flags |= FID_NON_RECLAIMABLE;

    }

    iounit =  get_iounit(pdu, &fidp->path);

    stat_to_qid(&stbuf, &qid);

    offset += pdu_marshal(pdu, offset, "Qd", &qid, iounit);

    err = offset;

    trace_v9fs_lcreate_return(pdu->tag, pdu->id,

                              qid.type, qid.version, qid.path, iounit);

out:

    put_fid(pdu, fidp);

out_nofid:

    complete_pdu(pdu->s, pdu, err);

    v9fs_string_free(&name);

}

static uint32_t mvc_asc(CPUS390XState *env, int64_t l, uint64_t a1,

                        uint64_t mode1, uint64_t a2, uint64_t mode2)

{

    CPUState *cs = CPU(s390_env_get_cpu(env));

    target_ulong src, dest;

    int flags, cc = 0, i;



    if (!l) {

        return 0;

    } else if (l > 256) {

        /* max 256 */

        l = 256;

        cc = 3;

    }



    if (mmu_translate(env, a1, 1, mode1, &dest, &flags, true)) {

        cpu_loop_exit(CPU(s390_env_get_cpu(env)));

    }

    dest |= a1 & ~TARGET_PAGE_MASK;



    if (mmu_translate(env, a2, 0, mode2, &src, &flags, true)) {

        cpu_loop_exit(CPU(s390_env_get_cpu(env)));

    }

    src |= a2 & ~TARGET_PAGE_MASK;



    /* XXX replace w/ memcpy */

    for (i = 0; i < l; i++) {

        /* XXX be more clever */

        if ((((dest + i) & TARGET_PAGE_MASK) != (dest & TARGET_PAGE_MASK)) ||

            (((src + i) & TARGET_PAGE_MASK) != (src & TARGET_PAGE_MASK))) {

            mvc_asc(env, l - i, a1 + i, mode1, a2 + i, mode2);

            break;

        }

        stb_phys(cs->as, dest + i, ldub_phys(cs->as, src + i));

    }



    return cc;

}

uint32_t HELPER(testblock)(CPUS390XState *env, uint64_t real_addr)

{

    uintptr_t ra = GETPC();

    CPUState *cs = CPU(s390_env_get_cpu(env));

    int i;



    real_addr = wrap_address(env, real_addr) & TARGET_PAGE_MASK;



    /* Check low-address protection */

    if ((env->cregs[0] & CR0_LOWPROT) && real_addr < 0x2000) {

        cpu_restore_state(cs, ra);

        program_interrupt(env, PGM_PROTECTION, 4);

        return 1;

    }



    for (i = 0; i < TARGET_PAGE_SIZE; i += 8) {

        cpu_stq_real_ra(env, real_addr + i, 0, ra);

    }



    return 0;

}

uint64_t HELPER(diag)(CPUS390XState *env, uint32_t num, uint64_t mem,

                      uint64_t code)

{

    uint64_t r;



    switch (num) {

    case 0x500:

        /* KVM hypercall */

        r = s390_virtio_hypercall(env);

        break;

    case 0x44:

        /* yield */

        r = 0;

        break;

    case 0x308:

        /* ipl */

        r = 0;

        break;

    default:

        r = -1;

        break;

    }



    if (r) {

        program_interrupt(env, PGM_OPERATION, ILEN_LATER_INC);

    }



    return r;

}

uint32_t HELPER(msa)(CPUS390XState *env, uint32_t r1, uint32_t r2, uint32_t r3,

                     uint32_t type)

{

    const uintptr_t ra = GETPC();

    const uint8_t mod = env->regs[0] & 0x80ULL;

    const uint8_t fc = env->regs[0] & 0x7fULL;

    CPUState *cs = CPU(s390_env_get_cpu(env));

    uint8_t subfunc[16] = { 0 };

    uint64_t param_addr;

    int i;



    switch (type) {

    case S390_FEAT_TYPE_KMAC:

    case S390_FEAT_TYPE_KIMD:

    case S390_FEAT_TYPE_KLMD:

    case S390_FEAT_TYPE_PCKMO:

    case S390_FEAT_TYPE_PCC:

        if (mod) {

            cpu_restore_state(cs, ra);

            program_interrupt(env, PGM_SPECIFICATION, 4);

            return 0;

        }

        break;

    }



    s390_get_feat_block(type, subfunc);

    if (!test_be_bit(fc, subfunc)) {

        cpu_restore_state(cs, ra);

        program_interrupt(env, PGM_SPECIFICATION, 4);

        return 0;

    }



    switch (fc) {

    case 0: /* query subfunction */

        for (i = 0; i < 16; i++) {

            param_addr = wrap_address(env, env->regs[1] + i);

            cpu_stb_data_ra(env, param_addr, subfunc[i], ra);

        }

        break;

    default:

        /* we don't implement any other subfunction yet */

        g_assert_not_reached();

    }



    return 0;

}

static int bdrv_inactivate_recurse(BlockDriverState *bs,

                                   bool setting_flag)

{

    BdrvChild *child, *parent;

    int ret;



    if (!setting_flag && bs->drv->bdrv_inactivate) {

        ret = bs->drv->bdrv_inactivate(bs);

        if (ret < 0) {

            return ret;

        }

    }



    if (setting_flag) {

        uint64_t perm, shared_perm;



        bs->open_flags |= BDRV_O_INACTIVE;



        QLIST_FOREACH(parent, &bs->parents, next_parent) {

            if (parent->role->inactivate) {

                ret = parent->role->inactivate(parent);

                if (ret < 0) {

                    bs->open_flags &= ~BDRV_O_INACTIVE;

                    return ret;

                }

            }

        }



        /* Update permissions, they may differ for inactive nodes */

        bdrv_get_cumulative_perm(bs, &perm, &shared_perm);

        bdrv_check_perm(bs, perm, shared_perm, NULL, &error_abort);

        bdrv_set_perm(bs, perm, shared_perm);

    }



    QLIST_FOREACH(child, &bs->children, next) {

        ret = bdrv_inactivate_recurse(child->bs, setting_flag);

        if (ret < 0) {

            return ret;

        }

    }



    /* At this point persistent bitmaps should be already stored by the format

     * driver */

    bdrv_release_persistent_dirty_bitmaps(bs);



    return 0;

}

static int bdrv_check_perm(BlockDriverState *bs, uint64_t cumulative_perms,

                           uint64_t cumulative_shared_perms, Error **errp)

{

    BlockDriver *drv = bs->drv;

    BdrvChild *c;

    int ret;



    /* Write permissions never work with read-only images */

    if ((cumulative_perms & (BLK_PERM_WRITE | BLK_PERM_WRITE_UNCHANGED)) &&

        bdrv_is_read_only(bs))

    {

        error_setg(errp, "Block node is read-only");

        return -EPERM;

    }



    /* Check this node */

    if (!drv) {

        return 0;

    }



    if (drv->bdrv_check_perm) {

        return drv->bdrv_check_perm(bs, cumulative_perms,

                                    cumulative_shared_perms, errp);

    }



    /* Drivers that never have children can omit .bdrv_child_perm() */

    if (!drv->bdrv_child_perm) {

        assert(QLIST_EMPTY(&bs->children));

        return 0;

    }



    /* Check all children */

    QLIST_FOREACH(c, &bs->children, next) {

        uint64_t cur_perm, cur_shared;

        drv->bdrv_child_perm(bs, c, c->role,

                             cumulative_perms, cumulative_shared_perms,

                             &cur_perm, &cur_shared);

        ret = bdrv_child_check_perm(c, cur_perm, cur_shared, errp);

        if (ret < 0) {

            return ret;

        }

    }



    return 0;

}

static const char *bdrv_get_parent_name(const BlockDriverState *bs)

{

    BdrvChild *c;

    const char *name;



    /* If multiple parents have a name, just pick the first one. */

    QLIST_FOREACH(c, &bs->parents, next_parent) {

        if (c->role->get_name) {

            name = c->role->get_name(c);

            if (name && *name) {

                return name;

            }

        }

    }



    return NULL;

}

static int qemu_rbd_parsename(const char *filename,

                              char *pool, int pool_len,

                              char *snap, int snap_len,

                              char *name, int name_len,

                              char *conf, int conf_len,

                              Error **errp)

{

    const char *start;

    char *p, *buf;

    int ret = 0;

    char *found_str;

    Error *local_err = NULL;



    if (!strstart(filename, "rbd:", &start)) {

        error_setg(errp, "File name must start with 'rbd:'");

        return -EINVAL;

    }



    buf = g_strdup(start);

    p = buf;

    *snap = '\0';

    *conf = '\0';



    found_str = qemu_rbd_next_tok(pool_len, p,

                                  '/', "pool name", &p, &local_err);

    if (local_err) {

        goto done;

    }

    if (!p) {

        ret = -EINVAL;

        error_setg(errp, "Pool name is required");

        goto done;

    }

    qemu_rbd_unescape(found_str);

    g_strlcpy(pool, found_str, pool_len);



    if (strchr(p, '@')) {

        found_str = qemu_rbd_next_tok(name_len, p,

                                      '@', "object name", &p, &local_err);

        if (local_err) {

            goto done;

        }

        qemu_rbd_unescape(found_str);

        g_strlcpy(name, found_str, name_len);



        found_str = qemu_rbd_next_tok(snap_len, p,

                                      ':', "snap name", &p, &local_err);

        if (local_err) {

            goto done;

        }

        qemu_rbd_unescape(found_str);

        g_strlcpy(snap, found_str, snap_len);

    } else {

        found_str = qemu_rbd_next_tok(name_len, p,

                                      ':', "object name", &p, &local_err);

        if (local_err) {

            goto done;

        }

        qemu_rbd_unescape(found_str);

        g_strlcpy(name, found_str, name_len);

    }

    if (!p) {

        goto done;

    }



    found_str = qemu_rbd_next_tok(conf_len, p,

                                  '\0', "configuration", &p, &local_err);

    if (local_err) {

        goto done;

    }

    g_strlcpy(conf, found_str, conf_len);



done:

    if (local_err) {

        ret = -EINVAL;

        error_propagate(errp, local_err);

    }

    g_free(buf);

    return ret;

}

static void process_event(JSONMessageParser *parser, QList *tokens)

{

    GAState *s = container_of(parser, GAState, parser);

    QObject *obj;

    QDict *qdict;

    Error *err = NULL;

    int ret;



    g_assert(s && parser);



    g_debug("process_event: called");

    obj = json_parser_parse_err(tokens, NULL, &err);

    if (err || !obj || qobject_type(obj) != QTYPE_QDICT) {

        qobject_decref(obj);

        qdict = qdict_new();

        if (!err) {

            g_warning("failed to parse event: unknown error");

            error_setg(&err, QERR_JSON_PARSING);

        } else {

            g_warning("failed to parse event: %s", error_get_pretty(err));

        }

        qdict_put_obj(qdict, "error", qmp_build_error_object(err));

        error_free(err);

    } else {

        qdict = qobject_to_qdict(obj);

    }



    g_assert(qdict);



    /* handle host->guest commands */

    if (qdict_haskey(qdict, "execute")) {

        process_command(s, qdict);

    } else {

        if (!qdict_haskey(qdict, "error")) {

            QDECREF(qdict);

            qdict = qdict_new();

            g_warning("unrecognized payload format");

            error_setg(&err, QERR_UNSUPPORTED);

            qdict_put_obj(qdict, "error", qmp_build_error_object(err));

            error_free(err);

        }

        ret = send_response(s, QOBJECT(qdict));

        if (ret < 0) {

            g_warning("error sending error response: %s", strerror(-ret));

        }

    }



    QDECREF(qdict);

}

static void monitor_protocol_emitter(Monitor *mon, QObject *data,

                                     QError *err)

{

    QDict *qmp;



    trace_monitor_protocol_emitter(mon);



    if (!err) {

        /* success response */

        qmp = qdict_new();

        if (data) {

            qobject_incref(data);

            qdict_put_obj(qmp, "return", data);

        } else {

            /* return an empty QDict by default */

            qdict_put(qmp, "return", qdict_new());

        }

    } else {

        /* error response */

        qmp = build_qmp_error_dict(err);

    }



    if (mon->mc->id) {

        qdict_put_obj(qmp, "id", mon->mc->id);

        mon->mc->id = NULL;

    }



    monitor_json_emitter(mon, QOBJECT(qmp));

    QDECREF(qmp);

}

static void handle_qmp_command(JSONMessageParser *parser, QList *tokens)

{

    Error *local_err = NULL;

    QObject *obj, *data;

    QDict *input, *args;

    const mon_cmd_t *cmd;

    const char *cmd_name;

    Monitor *mon = cur_mon;



    args = input = NULL;

    data = NULL;



    obj = json_parser_parse(tokens, NULL);

    if (!obj) {

        // FIXME: should be triggered in json_parser_parse()

        qerror_report(QERR_JSON_PARSING);

        goto err_out;

    }



    input = qmp_check_input_obj(obj, &local_err);

    if (!input) {

        qerror_report_err(local_err);

        qobject_decref(obj);

        goto err_out;

    }



    mon->mc->id = qdict_get(input, "id");

    qobject_incref(mon->mc->id);



    cmd_name = qdict_get_str(input, "execute");

    trace_handle_qmp_command(mon, cmd_name);

    cmd = qmp_find_cmd(cmd_name);

    if (!cmd) {

        qerror_report(ERROR_CLASS_COMMAND_NOT_FOUND,

                      "The command %s has not been found", cmd_name);

        goto err_out;

    }

    if (invalid_qmp_mode(mon, cmd)) {

        goto err_out;

    }



    obj = qdict_get(input, "arguments");

    if (!obj) {

        args = qdict_new();

    } else {

        args = qobject_to_qdict(obj);

        QINCREF(args);

    }



    qmp_check_client_args(cmd, args, &local_err);

    if (local_err) {

        qerror_report_err(local_err);

        goto err_out;

    }



    if (cmd->mhandler.cmd_new(mon, args, &data)) {

        /* Command failed... */

        if (!monitor_has_error(mon)) {

            /* ... without setting an error, so make one up */

            qerror_report(QERR_UNDEFINED_ERROR);

        }

    }



err_out:

    monitor_protocol_emitter(mon, data);

    qobject_decref(data);

    QDECREF(input);

    QDECREF(args);

}

static void qmp_output_add_obj(QmpOutputVisitor *qov, const char *name,

                               QObject *value)

{

    QStackEntry *e = QTAILQ_FIRST(&qov->stack);

    QObject *cur = e ? e->value : NULL;



    if (!cur) {

        /* FIXME we should require the user to reset the visitor, rather

         * than throwing away the previous root */

        qobject_decref(qov->root);

        qov->root = value;

    } else {

        switch (qobject_type(cur)) {

        case QTYPE_QDICT:

            assert(name);

            qdict_put_obj(qobject_to_qdict(cur), name, value);

            break;

        case QTYPE_QLIST:

            qlist_append_obj(qobject_to_qlist(cur), value);

            break;

        default:

            g_assert_not_reached();

        }

    }

}

static inline int decode_vui_parameters(H264Context *h, SPS *sps){

    MpegEncContext * const s = &h->s;

    int aspect_ratio_info_present_flag;

    unsigned int aspect_ratio_idc;



    aspect_ratio_info_present_flag= get_bits1(&s->gb);



    if( aspect_ratio_info_present_flag ) {

        aspect_ratio_idc= get_bits(&s->gb, 8);

        if( aspect_ratio_idc == EXTENDED_SAR ) {

            sps->sar.num= get_bits(&s->gb, 16);

            sps->sar.den= get_bits(&s->gb, 16);

        }else if(aspect_ratio_idc < FF_ARRAY_ELEMS(pixel_aspect)){

            sps->sar=  pixel_aspect[aspect_ratio_idc];

        }else{

            av_log(h->s.avctx, AV_LOG_ERROR, "illegal aspect ratio\n");

            return -1;

        }

    }else{

        sps->sar.num=

        sps->sar.den= 0;

    }

//            s->avctx->aspect_ratio= sar_width*s->width / (float)(s->height*sar_height);



    if(get_bits1(&s->gb)){      /* overscan_info_present_flag */

        get_bits1(&s->gb);      /* overscan_appropriate_flag */

    }



    sps->video_signal_type_present_flag = get_bits1(&s->gb);

    if(sps->video_signal_type_present_flag){

        get_bits(&s->gb, 3);    /* video_format */

        sps->full_range = get_bits1(&s->gb); /* video_full_range_flag */



        sps->colour_description_present_flag = get_bits1(&s->gb);

        if(sps->colour_description_present_flag){

            sps->color_primaries = get_bits(&s->gb, 8); /* colour_primaries */

            sps->color_trc       = get_bits(&s->gb, 8); /* transfer_characteristics */

            sps->colorspace      = get_bits(&s->gb, 8); /* matrix_coefficients */

            if (sps->color_primaries >= AVCOL_PRI_NB)

                sps->color_primaries  = AVCOL_PRI_UNSPECIFIED;

            if (sps->color_trc >= AVCOL_TRC_NB)

                sps->color_trc  = AVCOL_TRC_UNSPECIFIED;

            if (sps->colorspace >= AVCOL_SPC_NB)

                sps->colorspace  = AVCOL_SPC_UNSPECIFIED;

        }

    }



    if(get_bits1(&s->gb)){      /* chroma_location_info_present_flag */

        s->avctx->chroma_sample_location = get_ue_golomb(&s->gb)+1;  /* chroma_sample_location_type_top_field */

        get_ue_golomb(&s->gb);  /* chroma_sample_location_type_bottom_field */

    }



    sps->timing_info_present_flag = get_bits1(&s->gb);

    if(sps->timing_info_present_flag){

        sps->num_units_in_tick = get_bits_long(&s->gb, 32);

        sps->time_scale = get_bits_long(&s->gb, 32);

        if(!sps->num_units_in_tick || !sps->time_scale){

            av_log(h->s.avctx, AV_LOG_ERROR, "time_scale/num_units_in_tick invalid or unsupported (%d/%d)\n", sps->time_scale, sps->num_units_in_tick);

            return -1;

        }

        sps->fixed_frame_rate_flag = get_bits1(&s->gb);

    }



    sps->nal_hrd_parameters_present_flag = get_bits1(&s->gb);

    if(sps->nal_hrd_parameters_present_flag)

        if(decode_hrd_parameters(h, sps) < 0)

            return -1;

    sps->vcl_hrd_parameters_present_flag = get_bits1(&s->gb);

    if(sps->vcl_hrd_parameters_present_flag)

        if(decode_hrd_parameters(h, sps) < 0)

            return -1;

    if(sps->nal_hrd_parameters_present_flag || sps->vcl_hrd_parameters_present_flag)

        get_bits1(&s->gb);     /* low_delay_hrd_flag */

    sps->pic_struct_present_flag = get_bits1(&s->gb);



    sps->bitstream_restriction_flag = get_bits1(&s->gb);

    if(sps->bitstream_restriction_flag){

        get_bits1(&s->gb);     /* motion_vectors_over_pic_boundaries_flag */

        get_ue_golomb(&s->gb); /* max_bytes_per_pic_denom */

        get_ue_golomb(&s->gb); /* max_bits_per_mb_denom */

        get_ue_golomb(&s->gb); /* log2_max_mv_length_horizontal */

        get_ue_golomb(&s->gb); /* log2_max_mv_length_vertical */

        sps->num_reorder_frames= get_ue_golomb(&s->gb);

        get_ue_golomb(&s->gb); /*max_dec_frame_buffering*/



        if (get_bits_left(&s->gb) < 0) {

            av_log(h->s.avctx, AV_LOG_ERROR, "Overread VUI by %d bits\n", -get_bits_left(&s->gb));

            sps->num_reorder_frames=0;

            sps->bitstream_restriction_flag= 0;

        }



        if(sps->num_reorder_frames > 16U /*max_dec_frame_buffering || max_dec_frame_buffering > 16*/){

            av_log(h->s.avctx, AV_LOG_ERROR, "illegal num_reorder_frames %d\n", sps->num_reorder_frames);

            return -1;

        }

    }



    return 0;

}

static void decode_vui(HEVCContext *s, HEVCSPS *sps)

{

    VUI *vui          = &sps->vui;

    GetBitContext *gb = &s->HEVClc->gb;

    int sar_present;



    av_log(s->avctx, AV_LOG_DEBUG, "Decoding VUI\n");



    sar_present = get_bits1(gb);

    if (sar_present) {

        uint8_t sar_idx = get_bits(gb, 8);

        if (sar_idx < FF_ARRAY_ELEMS(vui_sar))

            vui->sar = vui_sar[sar_idx];

        else if (sar_idx == 255) {

            vui->sar.num = get_bits(gb, 16);

            vui->sar.den = get_bits(gb, 16);

        } else

            av_log(s->avctx, AV_LOG_WARNING,

                   "Unknown SAR index: %u.\n", sar_idx);

    }



    vui->overscan_info_present_flag = get_bits1(gb);

    if (vui->overscan_info_present_flag)

        vui->overscan_appropriate_flag = get_bits1(gb);



    vui->video_signal_type_present_flag = get_bits1(gb);

    if (vui->video_signal_type_present_flag) {

        vui->video_format                    = get_bits(gb, 3);

        vui->video_full_range_flag           = get_bits1(gb);

        vui->colour_description_present_flag = get_bits1(gb);

        if (vui->video_full_range_flag && sps->pix_fmt == AV_PIX_FMT_YUV420P)

            sps->pix_fmt = AV_PIX_FMT_YUVJ420P;

        if (vui->colour_description_present_flag) {

            vui->colour_primaries        = get_bits(gb, 8);

            vui->transfer_characteristic = get_bits(gb, 8);

            vui->matrix_coeffs           = get_bits(gb, 8);



            // Set invalid values to "unspecified"

            if (vui->colour_primaries >= AVCOL_PRI_NB)

                vui->colour_primaries = AVCOL_PRI_UNSPECIFIED;

            if (vui->transfer_characteristic >= AVCOL_TRC_NB)

                vui->transfer_characteristic = AVCOL_TRC_UNSPECIFIED;

            if (vui->matrix_coeffs >= AVCOL_SPC_NB)

                vui->matrix_coeffs = AVCOL_SPC_UNSPECIFIED;

        }

    }



    vui->chroma_loc_info_present_flag = get_bits1(gb);

    if (vui->chroma_loc_info_present_flag) {

        vui->chroma_sample_loc_type_top_field    = get_ue_golomb_long(gb);

        vui->chroma_sample_loc_type_bottom_field = get_ue_golomb_long(gb);

    }



    vui->neutra_chroma_indication_flag = get_bits1(gb);

    vui->field_seq_flag                = get_bits1(gb);

    vui->frame_field_info_present_flag = get_bits1(gb);



    vui->default_display_window_flag = get_bits1(gb);

    if (vui->default_display_window_flag) {

        //TODO: * 2 is only valid for 420

        vui->def_disp_win.left_offset   = get_ue_golomb_long(gb) * 2;

        vui->def_disp_win.right_offset  = get_ue_golomb_long(gb) * 2;

        vui->def_disp_win.top_offset    = get_ue_golomb_long(gb) * 2;

        vui->def_disp_win.bottom_offset = get_ue_golomb_long(gb) * 2;



        if (s->apply_defdispwin &&

            s->avctx->flags2 & CODEC_FLAG2_IGNORE_CROP) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "discarding vui default display window, "

                   "original values are l:%u r:%u t:%u b:%u\n",

                   vui->def_disp_win.left_offset,

                   vui->def_disp_win.right_offset,

                   vui->def_disp_win.top_offset,

                   vui->def_disp_win.bottom_offset);



            vui->def_disp_win.left_offset   =

            vui->def_disp_win.right_offset  =

            vui->def_disp_win.top_offset    =

            vui->def_disp_win.bottom_offset = 0;

        }

    }



    vui->vui_timing_info_present_flag = get_bits1(gb);



    if (vui->vui_timing_info_present_flag) {

        vui->vui_num_units_in_tick               = get_bits(gb, 32);

        vui->vui_time_scale                      = get_bits(gb, 32);

        vui->vui_poc_proportional_to_timing_flag = get_bits1(gb);

        if (vui->vui_poc_proportional_to_timing_flag)

            vui->vui_num_ticks_poc_diff_one_minus1 = get_ue_golomb_long(gb);

        vui->vui_hrd_parameters_present_flag = get_bits1(gb);

        if (vui->vui_hrd_parameters_present_flag)

            decode_hrd(s, 1, sps->max_sub_layers);

    }



    vui->bitstream_restriction_flag = get_bits1(gb);

    if (vui->bitstream_restriction_flag) {

        vui->tiles_fixed_structure_flag              = get_bits1(gb);

        vui->motion_vectors_over_pic_boundaries_flag = get_bits1(gb);

        vui->restricted_ref_pic_lists_flag           = get_bits1(gb);

        vui->min_spatial_segmentation_idc            = get_ue_golomb_long(gb);

        vui->max_bytes_per_pic_denom                 = get_ue_golomb_long(gb);

        vui->max_bits_per_min_cu_denom               = get_ue_golomb_long(gb);

        vui->log2_max_mv_length_horizontal           = get_ue_golomb_long(gb);

        vui->log2_max_mv_length_vertical             = get_ue_golomb_long(gb);

    }

}

static inline int decode_vui_parameters(GetBitContext *gb, AVCodecContext *avctx,

                                        SPS *sps)

{

    int aspect_ratio_info_present_flag;

    unsigned int aspect_ratio_idc;



    aspect_ratio_info_present_flag = get_bits1(gb);



    if (aspect_ratio_info_present_flag) {

        aspect_ratio_idc = get_bits(gb, 8);

        if (aspect_ratio_idc == EXTENDED_SAR) {

            sps->sar.num = get_bits(gb, 16);

            sps->sar.den = get_bits(gb, 16);

        } else if (aspect_ratio_idc < FF_ARRAY_ELEMS(pixel_aspect)) {

            sps->sar = pixel_aspect[aspect_ratio_idc];

        } else {

            av_log(avctx, AV_LOG_ERROR, "illegal aspect ratio\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        sps->sar.num =

        sps->sar.den = 0;

    }



    if (get_bits1(gb))      /* overscan_info_present_flag */

        get_bits1(gb);      /* overscan_appropriate_flag */



    sps->video_signal_type_present_flag = get_bits1(gb);

    if (sps->video_signal_type_present_flag) {

        get_bits(gb, 3);                 /* video_format */

        sps->full_range = get_bits1(gb); /* video_full_range_flag */



        sps->colour_description_present_flag = get_bits1(gb);

        if (sps->colour_description_present_flag) {

            sps->color_primaries = get_bits(gb, 8); /* colour_primaries */

            sps->color_trc       = get_bits(gb, 8); /* transfer_characteristics */

            sps->colorspace      = get_bits(gb, 8); /* matrix_coefficients */

            if (sps->color_primaries >= AVCOL_PRI_NB)

                sps->color_primaries = AVCOL_PRI_UNSPECIFIED;

            if (sps->color_trc >= AVCOL_TRC_NB)

                sps->color_trc = AVCOL_TRC_UNSPECIFIED;

            if (sps->colorspace >= AVCOL_SPC_NB)

                sps->colorspace = AVCOL_SPC_UNSPECIFIED;

        }

    }



    /* chroma_location_info_present_flag */

    if (get_bits1(gb)) {

        /* chroma_sample_location_type_top_field */

        avctx->chroma_sample_location = get_ue_golomb(gb) + 1;

        get_ue_golomb(gb);  /* chroma_sample_location_type_bottom_field */

    }



    sps->timing_info_present_flag = get_bits1(gb);

    if (sps->timing_info_present_flag) {

        sps->num_units_in_tick = get_bits_long(gb, 32);

        sps->time_scale        = get_bits_long(gb, 32);

        if (!sps->num_units_in_tick || !sps->time_scale) {

            av_log(avctx, AV_LOG_ERROR,

                   "time_scale/num_units_in_tick invalid or unsupported (%"PRIu32"/%"PRIu32")\n",

                   sps->time_scale, sps->num_units_in_tick);

            return AVERROR_INVALIDDATA;

        }

        sps->fixed_frame_rate_flag = get_bits1(gb);

    }



    sps->nal_hrd_parameters_present_flag = get_bits1(gb);

    if (sps->nal_hrd_parameters_present_flag)

        if (decode_hrd_parameters(gb, avctx, sps) < 0)

            return AVERROR_INVALIDDATA;

    sps->vcl_hrd_parameters_present_flag = get_bits1(gb);

    if (sps->vcl_hrd_parameters_present_flag)

        if (decode_hrd_parameters(gb, avctx, sps) < 0)

            return AVERROR_INVALIDDATA;

    if (sps->nal_hrd_parameters_present_flag ||

        sps->vcl_hrd_parameters_present_flag)

        get_bits1(gb);     /* low_delay_hrd_flag */

    sps->pic_struct_present_flag = get_bits1(gb);



    sps->bitstream_restriction_flag = get_bits1(gb);

    if (sps->bitstream_restriction_flag) {

        get_bits1(gb);     /* motion_vectors_over_pic_boundaries_flag */

        get_ue_golomb(gb); /* max_bytes_per_pic_denom */

        get_ue_golomb(gb); /* max_bits_per_mb_denom */

        get_ue_golomb(gb); /* log2_max_mv_length_horizontal */

        get_ue_golomb(gb); /* log2_max_mv_length_vertical */

        sps->num_reorder_frames = get_ue_golomb(gb);

        get_ue_golomb(gb); /*max_dec_frame_buffering*/



        if (get_bits_left(gb) < 0) {

            sps->num_reorder_frames         = 0;

            sps->bitstream_restriction_flag = 0;

        }



        if (sps->num_reorder_frames > 16U

            /* max_dec_frame_buffering || max_dec_frame_buffering > 16 */) {

            av_log(avctx, AV_LOG_ERROR,

                   "Clipping illegal num_reorder_frames %d\n",

                   sps->num_reorder_frames);

            sps->num_reorder_frames = 16;

            return AVERROR_INVALIDDATA;

        }

    }

    if (get_bits_left(gb) < 0) {

        av_log(avctx, AV_LOG_ERROR,

               "Overread VUI by %d bits\n", -get_bits_left(gb));

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static inline int decode_hrd_parameters(H264Context *h, SPS *sps)

{

    int cpb_count, i;

    cpb_count = get_ue_golomb_31(&h->gb) + 1;



    if (cpb_count > 32U) {

        av_log(h->avctx, AV_LOG_ERROR, "cpb_count %d invalid\n", cpb_count);

        return AVERROR_INVALIDDATA;

    }



    get_bits(&h->gb, 4); /* bit_rate_scale */

    get_bits(&h->gb, 4); /* cpb_size_scale */

    for (i = 0; i < cpb_count; i++) {

        get_ue_golomb_long(&h->gb); /* bit_rate_value_minus1 */

        get_ue_golomb_long(&h->gb); /* cpb_size_value_minus1 */

        get_bits1(&h->gb);          /* cbr_flag */

    }

    sps->initial_cpb_removal_delay_length = get_bits(&h->gb, 5) + 1;

    sps->cpb_removal_delay_length         = get_bits(&h->gb, 5) + 1;

    sps->dpb_output_delay_length          = get_bits(&h->gb, 5) + 1;

    sps->time_offset_length               = get_bits(&h->gb, 5);

    sps->cpb_cnt                          = cpb_count;

    return 0;

}

int bdrv_write_compressed(BlockDriverState *bs, int64_t sector_num,

                          const uint8_t *buf, int nb_sectors)

{

    BlockDriver *drv = bs->drv;

    if (!drv)

        return -ENOMEDIUM;

    if (!drv->bdrv_write_compressed)

        return -ENOTSUP;

    if (bdrv_check_request(bs, sector_num, nb_sectors))

        return -EIO;



    if (bs->dirty_tracking) {

        set_dirty_bitmap(bs, sector_num, nb_sectors, 1);

    }



    return drv->bdrv_write_compressed(bs, sector_num, buf, nb_sectors);

}

int bdrv_truncate(BlockDriverState *bs, int64_t offset)

{

    BlockDriver *drv = bs->drv;

    int ret;

    if (!drv)

        return -ENOMEDIUM;

    if (!drv->bdrv_truncate)

        return -ENOTSUP;

    if (bs->read_only)

        return -EACCES;



    ret = drv->bdrv_truncate(bs, offset);

    if (ret == 0) {

        ret = refresh_total_sectors(bs, offset >> BDRV_SECTOR_BITS);

        bdrv_dirty_bitmap_truncate(bs);

        bdrv_parent_cb_resize(bs);


    }

    return ret;

}

int bdrv_read(BlockDriverState *bs, int64_t sector_num,

              uint8_t *buf, int nb_sectors)

{

    BlockDriver *drv = bs->drv;



    if (!drv)

        return -ENOMEDIUM;



    if (sector_num == 0 && bs->boot_sector_enabled && nb_sectors > 0) {

            memcpy(buf, bs->boot_sector_data, 512);

        sector_num++;

        nb_sectors--;

        buf += 512;

        if (nb_sectors == 0)

            return 0;

    }

    if (drv->bdrv_pread) {

        int ret, len;

        len = nb_sectors * 512;

        ret = drv->bdrv_pread(bs, sector_num * 512, buf, len);

        if (ret < 0)

            return ret;

        else if (ret != len)

            return -EINVAL;

        else {

	    bs->rd_bytes += (unsigned) len;

	    bs->rd_ops ++;

            return 0;

	}

    } else {

        return drv->bdrv_read(bs, sector_num, buf, nb_sectors);

    }

}

int bdrv_truncate(BlockDriverState *bs, int64_t offset)

{

    BlockDriver *drv = bs->drv;

    int ret;

    if (!drv)

        return -ENOMEDIUM;

    if (!drv->bdrv_truncate)

        return -ENOTSUP;

    if (bs->read_only)

        return -EACCES;



    ret = drv->bdrv_truncate(bs, offset);

    if (ret == 0) {

        ret = refresh_total_sectors(bs, offset >> BDRV_SECTOR_BITS);

        bdrv_dirty_bitmap_truncate(bs);

        if (bs->blk) {

            blk_dev_resize_cb(bs->blk);

        }

    }

    return ret;

}

static int usb_host_handle_control(USBHostDevice *s, USBPacket *p)

{

    struct usbdevfs_urb *urb;

    AsyncURB *aurb;

    int ret, value, index;



    /* 

     * Process certain standard device requests.

     * These are infrequent and are processed synchronously.

     */

    value = le16_to_cpu(s->ctrl.req.wValue);

    index = le16_to_cpu(s->ctrl.req.wIndex);



    dprintf("husb: ctrl type 0x%x req 0x%x val 0x%x index %u len %u\n",

        s->ctrl.req.bRequestType, s->ctrl.req.bRequest, value, index, 

        s->ctrl.len);



    if (s->ctrl.req.bRequestType == 0) {

        switch (s->ctrl.req.bRequest) {

        case USB_REQ_SET_ADDRESS:

            return usb_host_set_address(s, value);



        case USB_REQ_SET_CONFIGURATION:

            return usb_host_set_config(s, value & 0xff);

        }

    }



    if (s->ctrl.req.bRequestType == 1 &&

                  s->ctrl.req.bRequest == USB_REQ_SET_INTERFACE)

        return usb_host_set_interface(s, index, value);



    /* The rest are asynchronous */



    aurb = async_alloc();

    aurb->hdev   = s;

    aurb->packet = p;



    /* 

     * Setup ctrl transfer.

     *

     * s->ctrl is layed out such that data buffer immediately follows

     * 'req' struct which is exactly what usbdevfs expects.

     */ 

    urb = &aurb->urb;



    urb->type     = USBDEVFS_URB_TYPE_CONTROL;

    urb->endpoint = p->devep;



    urb->buffer        = &s->ctrl.req;

    urb->buffer_length = 8 + s->ctrl.len;



    urb->usercontext = s;



    ret = ioctl(s->fd, USBDEVFS_SUBMITURB, urb);



    dprintf("husb: submit ctrl. len %u aurb %p\n", urb->buffer_length, aurb);



    if (ret < 0) {

        dprintf("husb: submit failed. errno %d\n", errno);

        async_free(aurb);



        switch(errno) {

        case ETIMEDOUT:

            return USB_RET_NAK;

        case EPIPE:

        default:

            return USB_RET_STALL;

        }

    }



    usb_defer_packet(p, async_cancel, aurb);

    return USB_RET_ASYNC;

}

static int qemu_rdma_exchange_recv(RDMAContext *rdma, RDMAControlHeader *head,

                                int expecting)

{

    RDMAControlHeader ready = {

                                .len = 0,

                                .type = RDMA_CONTROL_READY,

                                .repeat = 1,

                              };

    int ret;



    /*

     * Inform the source that we're ready to receive a message.

     */

    ret = qemu_rdma_post_send_control(rdma, NULL, &ready);



    if (ret < 0) {

        fprintf(stderr, "Failed to send control buffer!\n");

        return ret;

    }



    /*

     * Block and wait for the message.

     */

    ret = qemu_rdma_exchange_get_response(rdma, head,

                                          expecting, RDMA_WRID_READY);



    if (ret < 0) {

        return ret;

    }



    qemu_rdma_move_header(rdma, RDMA_WRID_READY, head);



    /*

     * Post a new RECV work request to replace the one we just consumed.

     */

    ret = qemu_rdma_post_recv_control(rdma, RDMA_WRID_READY);

    if (ret) {

        fprintf(stderr, "rdma migration: error posting second control recv!");

        return ret;

    }



    return 0;

}

static int usbredir_handle_control(USBDevice *udev, USBPacket *p,

        int request, int value, int index, int length, uint8_t *data)

{

    USBRedirDevice *dev = DO_UPCAST(USBRedirDevice, dev, udev);

    struct usb_redir_control_packet_header control_packet;

    AsyncURB *aurb;



    /* Special cases for certain standard device requests */

    switch (request) {

    case DeviceOutRequest | USB_REQ_SET_ADDRESS:

        DPRINTF("set address %d\n", value);

        dev->dev.addr = value;

        return 0;

    case DeviceOutRequest | USB_REQ_SET_CONFIGURATION:

        return usbredir_set_config(dev, p, value & 0xff);

    case DeviceRequest | USB_REQ_GET_CONFIGURATION:

        return usbredir_get_config(dev, p);

    case InterfaceOutRequest | USB_REQ_SET_INTERFACE:

        return usbredir_set_interface(dev, p, index, value);

    case InterfaceRequest | USB_REQ_GET_INTERFACE:

        return usbredir_get_interface(dev, p, index);

    }



    /* "Normal" ctrl requests */

    aurb = async_alloc(dev, p);



    /* Note request is (bRequestType << 8) | bRequest */

    DPRINTF("ctrl-out type 0x%x req 0x%x val 0x%x index %d len %d id %u\n",

            request >> 8, request & 0xff, value, index, length,

            aurb->packet_id);



    control_packet.request     = request & 0xFF;

    control_packet.requesttype = request >> 8;

    control_packet.endpoint    = control_packet.requesttype & USB_DIR_IN;

    control_packet.value       = value;

    control_packet.index       = index;

    control_packet.length      = length;

    aurb->control_packet       = control_packet;



    if (control_packet.requesttype & USB_DIR_IN) {

        usbredirparser_send_control_packet(dev->parser, aurb->packet_id,

                                           &control_packet, NULL, 0);

    } else {

        usbredir_log_data(dev, "ctrl data out:", data, length);

        usbredirparser_send_control_packet(dev->parser, aurb->packet_id,

                                           &control_packet, data, length);

    }

    usbredirparser_do_write(dev->parser);

    return USB_RET_ASYNC;

}

static void usb_host_handle_control(USBDevice *udev, USBPacket *p,

                                    int request, int value, int index,

                                    int length, uint8_t *data)

{

    USBHostDevice *s = USB_HOST_DEVICE(udev);

    USBHostRequest *r;

    int rc;



    trace_usb_host_req_control(s->bus_num, s->addr, p, request, value, index);



    if (s->dh == NULL) {

        p->status = USB_RET_NODEV;

        trace_usb_host_req_emulated(s->bus_num, s->addr, p, p->status);

        return;

    }



    switch (request) {

    case DeviceOutRequest | USB_REQ_SET_ADDRESS:

        usb_host_set_address(s, value);

        trace_usb_host_req_emulated(s->bus_num, s->addr, p, p->status);

        return;



    case DeviceOutRequest | USB_REQ_SET_CONFIGURATION:

        usb_host_set_config(s, value & 0xff, p);

        trace_usb_host_req_emulated(s->bus_num, s->addr, p, p->status);

        return;



    case InterfaceOutRequest | USB_REQ_SET_INTERFACE:

        usb_host_set_interface(s, index, value, p);

        trace_usb_host_req_emulated(s->bus_num, s->addr, p, p->status);

        return;



    case EndpointOutRequest | USB_REQ_CLEAR_FEATURE:

        if (value == 0) { /* clear halt */

            int pid = (index & USB_DIR_IN) ? USB_TOKEN_IN : USB_TOKEN_OUT;

            libusb_clear_halt(s->dh, index);

            usb_ep_set_halted(udev, pid, index & 0x0f, 0);

            trace_usb_host_req_emulated(s->bus_num, s->addr, p, p->status);

            return;

        }

    }



    r = usb_host_req_alloc(s, p, (request >> 8) & USB_DIR_IN, length + 8);

    r->cbuf = data;

    r->clen = length;

    memcpy(r->buffer, udev->setup_buf, 8);

    if (!r->in) {

        memcpy(r->buffer + 8, r->cbuf, r->clen);

    }



    /* Fix up USB-3 ep0 maxpacket size to allow superspeed connected devices

     * to work redirected to a not superspeed capable hcd */

    if (udev->speed == USB_SPEED_SUPER &&

        !(udev->port->speedmask & USB_SPEED_MASK_SUPER) &&

        request == 0x8006 && value == 0x100 && index == 0) {

        r->usb3ep0quirk = true;

    }



    libusb_fill_control_transfer(r->xfer, s->dh, r->buffer,

                                 usb_host_req_complete_ctrl, r,

                                 CONTROL_TIMEOUT);

    rc = libusb_submit_transfer(r->xfer);

    if (rc != 0) {

        p->status = USB_RET_NODEV;

        trace_usb_host_req_complete(s->bus_num, s->addr, p,

                                    p->status, p->actual_length);

        if (rc == LIBUSB_ERROR_NO_DEVICE) {

            usb_host_nodev(s);

        }

        return;

    }



    p->status = USB_RET_ASYNC;

}

dshow_cycle_devices(AVFormatContext *avctx, ICreateDevEnum *devenum,

                    enum dshowDeviceType devtype, IBaseFilter **pfilter)

{

    struct dshow_ctx *ctx = avctx->priv_data;

    IBaseFilter *device_filter = NULL;

    IEnumMoniker *classenum = NULL;

    IMoniker *m = NULL;

    const char *device_name = ctx->device_name[devtype];

    int r;



    const GUID *device_guid[2] = { &CLSID_VideoInputDeviceCategory,

                                   &CLSID_AudioInputDeviceCategory };

    const char *devtypename = (devtype == VideoDevice) ? "video" : "audio";



    r = ICreateDevEnum_CreateClassEnumerator(devenum, device_guid[devtype],

                                             (IEnumMoniker **) &classenum, 0);

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not enumerate %s devices.\n",

               devtypename);

        return AVERROR(EIO);

    }



    while (IEnumMoniker_Next(classenum, 1, &m, NULL) == S_OK && !device_filter) {

        IPropertyBag *bag = NULL;

        char *buf = NULL;

        VARIANT var;



        r = IMoniker_BindToStorage(m, 0, 0, &IID_IPropertyBag, (void *) &bag);

        if (r != S_OK)

            goto fail1;



        var.vt = VT_BSTR;

        r = IPropertyBag_Read(bag, L"FriendlyName", &var, NULL);

        if (r != S_OK)

            goto fail1;



        buf = dup_wchar_to_utf8(var.bstrVal);



        if (pfilter) {

            if (strcmp(device_name, buf))

                goto fail1;



            IMoniker_BindToObject(m, 0, 0, &IID_IBaseFilter, (void *) &device_filter);

        } else {

            av_log(avctx, AV_LOG_INFO, " \"%s\"\n", buf);

        }



fail1:

        if (buf)

            av_free(buf);

        if (bag)

            IPropertyBag_Release(bag);

        IMoniker_Release(m);

    }



    IEnumMoniker_Release(classenum);



    if (pfilter) {

        if (!device_filter) {

            av_log(avctx, AV_LOG_ERROR, "Could not find %s device.\n",

                   devtypename);

            return AVERROR(EIO);

        }

        *pfilter = device_filter;

    }



    return 0;

}

dshow_cycle_pins(AVFormatContext *avctx, enum dshowDeviceType devtype,

                 IBaseFilter *device_filter, IPin **ppin)

{

    struct dshow_ctx *ctx = avctx->priv_data;

    IEnumPins *pins = 0;

    IPin *device_pin = NULL;

    IPin *pin;

    int r;



    const GUID *mediatype[2] = { &MEDIATYPE_Video, &MEDIATYPE_Audio };

    const char *devtypename = (devtype == VideoDevice) ? "video" : "audio";



    int set_format = (devtype == VideoDevice && (ctx->video_size || ctx->framerate))

                  || (devtype == AudioDevice && (ctx->channels || ctx->sample_rate));

    int format_set = 0;



    r = IBaseFilter_EnumPins(device_filter, &pins);

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not enumerate pins.\n");

        return AVERROR(EIO);

    }



    if (!ppin) {

        av_log(avctx, AV_LOG_INFO, "DirectShow %s device options\n",

               devtypename);

    }

    while (IEnumPins_Next(pins, 1, &pin, NULL) == S_OK && !device_pin) {

        IKsPropertySet *p = NULL;

        IEnumMediaTypes *types = NULL;

        PIN_INFO info = {0};

        AM_MEDIA_TYPE *type;

        GUID category;

        DWORD r2;



        IPin_QueryPinInfo(pin, &info);

        IBaseFilter_Release(info.pFilter);



        if (info.dir != PINDIR_OUTPUT)

            goto next;

        if (IPin_QueryInterface(pin, &IID_IKsPropertySet, (void **) &p) != S_OK)

            goto next;

        if (IKsPropertySet_Get(p, &AMPROPSETID_Pin, AMPROPERTY_PIN_CATEGORY,

                               NULL, 0, &category, sizeof(GUID), &r2) != S_OK)

            goto next;

        if (!IsEqualGUID(&category, &PIN_CATEGORY_CAPTURE))

            goto next;



        if (!ppin) {

            char *buf = dup_wchar_to_utf8(info.achName);

            av_log(avctx, AV_LOG_INFO, " Pin \"%s\"\n", buf);

            av_free(buf);

            dshow_cycle_formats(avctx, devtype, pin, NULL);

            goto next;

        }

        if (set_format) {

            dshow_cycle_formats(avctx, devtype, pin, &format_set);

            if (!format_set) {

                goto next;

            }

        }



        if (IPin_EnumMediaTypes(pin, &types) != S_OK)

            goto next;



        IEnumMediaTypes_Reset(types);

        while (IEnumMediaTypes_Next(types, 1, &type, NULL) == S_OK && !device_pin) {

            if (IsEqualGUID(&type->majortype, mediatype[devtype])) {

                device_pin = pin;

                goto next;

            }

            CoTaskMemFree(type);

        }



next:

        if (types)

            IEnumMediaTypes_Release(types);

        if (p)

            IKsPropertySet_Release(p);

        if (device_pin != pin)

            IPin_Release(pin);

    }



    IEnumPins_Release(pins);



    if (ppin) {

        if (set_format && !format_set) {

            av_log(avctx, AV_LOG_ERROR, "Could not set %s options\n", devtypename);

            return AVERROR(EIO);

        }

        if (!device_pin) {

            av_log(avctx, AV_LOG_ERROR,

                "Could not find output pin from %s capture device.\n", devtypename);

            return AVERROR(EIO);

        }

        *ppin = device_pin;

    }



    return 0;

}

static int dshow_read_header(AVFormatContext *avctx)

{

    struct dshow_ctx *ctx = avctx->priv_data;

    IGraphBuilder *graph = NULL;

    ICreateDevEnum *devenum = NULL;

    IMediaControl *control = NULL;

    int ret = AVERROR(EIO);

    int r;



    if (!ctx->list_devices && !parse_device_name(avctx)) {

        av_log(avctx, AV_LOG_ERROR, "Malformed dshow input string.\n");

        goto error;

    }



    ctx->video_codec_id = avctx->video_codec_id ? avctx->video_codec_id

                                                : AV_CODEC_ID_RAWVIDEO;

    if (ctx->pixel_format != AV_PIX_FMT_NONE) {

        if (ctx->video_codec_id != AV_CODEC_ID_RAWVIDEO) {

            av_log(avctx, AV_LOG_ERROR, "Pixel format may only be set when "

                              "video codec is not set or set to rawvideo\n");

            ret = AVERROR(EINVAL);

            goto error;

        }

    }

    if (ctx->framerate) {

        r = av_parse_video_rate(&ctx->requested_framerate, ctx->framerate);

        if (r < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not parse framerate '%s'.\n", ctx->framerate);

            goto error;

        }

    }



    CoInitialize(0);



    r = CoCreateInstance(&CLSID_FilterGraph, NULL, CLSCTX_INPROC_SERVER,

                         &IID_IGraphBuilder, (void **) &graph);

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not create capture graph.\n");

        goto error;

    }

    ctx->graph = graph;



    r = CoCreateInstance(&CLSID_SystemDeviceEnum, NULL, CLSCTX_INPROC_SERVER,

                         &IID_ICreateDevEnum, (void **) &devenum);

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not enumerate system devices.\n");

        goto error;

    }



    if (ctx->list_devices) {

        av_log(avctx, AV_LOG_INFO, "DirectShow video devices\n");

        dshow_cycle_devices(avctx, devenum, VideoDevice, NULL);

        av_log(avctx, AV_LOG_INFO, "DirectShow audio devices\n");

        dshow_cycle_devices(avctx, devenum, AudioDevice, NULL);

        ret = AVERROR_EXIT;

        goto error;

    }

    if (ctx->list_options) {

        if (ctx->device_name[VideoDevice])

            dshow_list_device_options(avctx, devenum, VideoDevice);

        if (ctx->device_name[AudioDevice])

            dshow_list_device_options(avctx, devenum, AudioDevice);

        ret = AVERROR_EXIT;

        goto error;

    }



    if (ctx->device_name[VideoDevice]) {

        if ((r = dshow_open_device(avctx, devenum, VideoDevice)) < 0 ||

            (r = dshow_add_device(avctx, VideoDevice)) < 0) {

            ret = r;

            goto error;

        }

    }

    if (ctx->device_name[AudioDevice]) {

        if ((r = dshow_open_device(avctx, devenum, AudioDevice)) < 0 ||

            (r = dshow_add_device(avctx, AudioDevice)) < 0) {

            ret = r;

            goto error;

        }

    }



    ctx->mutex = CreateMutex(NULL, 0, NULL);

    if (!ctx->mutex) {

        av_log(avctx, AV_LOG_ERROR, "Could not create Mutex\n");

        goto error;

    }

    ctx->event = CreateEvent(NULL, 1, 0, NULL);

    if (!ctx->event) {

        av_log(avctx, AV_LOG_ERROR, "Could not create Event\n");

        goto error;

    }



    r = IGraphBuilder_QueryInterface(graph, &IID_IMediaControl, (void **) &control);

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not get media control.\n");

        goto error;

    }

    ctx->control = control;



    r = IMediaControl_Run(control);

    if (r == S_FALSE) {

        OAFilterState pfs;

        r = IMediaControl_GetState(control, 0, &pfs);

    }

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not run filter\n");

        goto error;

    }



    ret = 0;



error:



    if (ret < 0)

        dshow_read_close(avctx);



    if (devenum)

        ICreateDevEnum_Release(devenum);



    return ret;

}

static int vfw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    struct vfw_ctx *ctx = s->priv_data;

    AVCodecContext *codec;

    AVStream *st;

    int devnum;

    int bisize;

    BITMAPINFO *bi;

    CAPTUREPARMS cparms;

    DWORD biCompression;

    WORD biBitCount;

    int width;

    int height;

    int ret;



    if(!ap->time_base.den) {

        av_log(s, AV_LOG_ERROR, "A time base must be specified.\n");

        return AVERROR_IO;

    }



    ctx->s = s;



    ctx->hwnd = capCreateCaptureWindow(NULL, 0, 0, 0, 0, 0, HWND_MESSAGE, 0);

    if(!ctx->hwnd) {

        av_log(s, AV_LOG_ERROR, "Could not create capture window.\n");

        return AVERROR_IO;

    }



    /* If atoi fails, devnum==0 and the default device is used */

    devnum = atoi(s->filename);



    ret = SendMessage(ctx->hwnd, WM_CAP_DRIVER_CONNECT, devnum, 0);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not connect to device.\n");

        DestroyWindow(ctx->hwnd);

        return AVERROR(ENODEV);

    }



    SendMessage(ctx->hwnd, WM_CAP_SET_OVERLAY, 0, 0);

    SendMessage(ctx->hwnd, WM_CAP_SET_PREVIEW, 0, 0);



    ret = SendMessage(ctx->hwnd, WM_CAP_SET_CALLBACK_VIDEOSTREAM, 0,

                      (LPARAM) videostream_cb);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not set video stream callback.\n");

        goto fail_io;

    }



    SetWindowLongPtr(ctx->hwnd, GWLP_USERDATA, (LONG_PTR) ctx);



    st = av_new_stream(s, 0);

    if(!st) {

        vfw_read_close(s);

        return AVERROR_NOMEM;

    }



    /* Set video format */

    bisize = SendMessage(ctx->hwnd, WM_CAP_GET_VIDEOFORMAT, 0, 0);

    if(!bisize)

        goto fail_io;

    bi = av_malloc(bisize);

    if(!bi) {

        vfw_read_close(s);

        return AVERROR_NOMEM;

    }

    ret = SendMessage(ctx->hwnd, WM_CAP_GET_VIDEOFORMAT, bisize, (LPARAM) bi);

    if(!ret)

        goto fail_bi;



    dump_bih(s, &bi->bmiHeader);



    width  = ap->width  ? ap->width  : bi->bmiHeader.biWidth ;

    height = ap->height ? ap->height : bi->bmiHeader.biHeight;

    bi->bmiHeader.biWidth  = width ;

    bi->bmiHeader.biHeight = height;



#if 0

    /* For testing yet unsupported compressions

     * Copy these values from user-supplied verbose information */

    bi->bmiHeader.biWidth       = 320;

    bi->bmiHeader.biHeight      = 240;

    bi->bmiHeader.biPlanes      = 1;

    bi->bmiHeader.biBitCount    = 12;

    bi->bmiHeader.biCompression = MKTAG('I','4','2','0');

    bi->bmiHeader.biSizeImage   = 115200;

    dump_bih(s, &bi->bmiHeader);

#endif



    ret = SendMessage(ctx->hwnd, WM_CAP_SET_VIDEOFORMAT, bisize, (LPARAM) bi);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not set Video Format.\n");

        goto fail_bi;

    }



    biCompression = bi->bmiHeader.biCompression;

    biBitCount = bi->bmiHeader.biBitCount;



    av_free(bi);



    /* Set sequence setup */

    ret = SendMessage(ctx->hwnd, WM_CAP_GET_SEQUENCE_SETUP, sizeof(cparms),

                      (LPARAM) &cparms);

    if(!ret)

        goto fail_io;



    dump_captureparms(s, &cparms);



    cparms.fYield = 1; // Spawn a background thread

    cparms.dwRequestMicroSecPerFrame =

                               (ap->time_base.num*1000000) / ap->time_base.den;

    cparms.fAbortLeftMouse = 0;

    cparms.fAbortRightMouse = 0;

    cparms.fCaptureAudio = 0;

    cparms.vKeyAbort = 0;



    ret = SendMessage(ctx->hwnd, WM_CAP_SET_SEQUENCE_SETUP, sizeof(cparms),

                      (LPARAM) &cparms);

    if(!ret)

        goto fail_io;



    codec = st->codec;

    codec->time_base = ap->time_base;

    codec->codec_type = CODEC_TYPE_VIDEO;

    codec->width = width;

    codec->height = height;

    codec->pix_fmt = vfw_pixfmt(biCompression, biBitCount);

    if(codec->pix_fmt == PIX_FMT_NONE) {

        codec->codec_id = vfw_codecid(biCompression);

        if(codec->codec_id == CODEC_ID_NONE) {

            av_log(s, AV_LOG_ERROR, "Unknown compression type. "

                             "Please report verbose (-v 9) debug information.\n");

            vfw_read_close(s);

            return AVERROR_PATCHWELCOME;

        }

        codec->bits_per_coded_sample = biBitCount;

    } else {

        codec->codec_id = CODEC_ID_RAWVIDEO;

        if(biCompression == BI_RGB)

            codec->bits_per_coded_sample = biBitCount;

    }



    av_set_pts_info(st, 32, 1, 1000);



    ctx->mutex = CreateMutex(NULL, 0, NULL);

    if(!ctx->mutex) {

        av_log(s, AV_LOG_ERROR, "Could not create Mutex.\n" );

        goto fail_io;

    }

    ctx->event = CreateEvent(NULL, 1, 0, NULL);

    if(!ctx->event) {

        av_log(s, AV_LOG_ERROR, "Could not create Event.\n" );

        goto fail_io;

    }



    ret = SendMessage(ctx->hwnd, WM_CAP_SEQUENCE_NOFILE, 0, 0);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not start capture sequence.\n" );

        goto fail_io;

    }



    return 0;



fail_bi:

    av_free(bi);



fail_io:

    vfw_read_close(s);

    return AVERROR_IO;

}

