static int unix_get_buffer(void *opaque, uint8_t *buf, int64_t pos, int size)

{

    QEMUFileSocket *s = opaque;

    ssize_t len;



    for (;;) {

        len = read(s->fd, buf, size);

        if (len != -1) {

            break;

        }

        if (errno == EAGAIN) {

            yield_until_fd_readable(s->fd);

        } else if (errno != EINTR) {

            break;

        }

    }



    if (len == -1) {

        len = -errno;

    }

    return len;

}

static int buf_get_buffer(void *opaque, uint8_t *buf, int64_t pos, int size)

{

    QEMUBuffer *s = opaque;

    ssize_t len = qsb_get_length(s->qsb) - pos;



    if (len <= 0) {

        return 0;

    }



    if (len > size) {

        len = size;

    }

    return qsb_get_buffer(s->qsb, pos, len, buf);

}

static void fd_put_buffer(void *opaque, const uint8_t *buf,

                          int64_t pos, int size)

{

    QEMUFileFD *s = opaque;

    ssize_t len;



    do {

        len = write(s->fd, buf, size);

    } while (len == -1 && errno == EINTR);



    if (len == -1)

        len = -errno;



    /* When the fd becomes writable again, register a callback to do

     * a put notify */

    if (len == -EAGAIN)

        qemu_set_fd_handler2(s->fd, NULL, NULL, fd_put_notify, s);

}

ssize_t migrate_fd_put_buffer(void *opaque, const void *data, size_t size)

{

    FdMigrationState *s = opaque;

    ssize_t ret;



    do {

        ret = s->write(s, data, size);

    } while (ret == -1 && ((s->get_error(s)) == EINTR || (s->get_error(s)) == EWOULDBLOCK));



    if (ret == -1)

        ret = -(s->get_error(s));



    if (ret == -EAGAIN)

        qemu_set_fd_handler2(s->fd, NULL, NULL, migrate_fd_put_notify, s);



    return ret;

}

