static int parse_bsfs(void *log_ctx, const char *bsfs_spec,

                      AVBitStreamFilterContext **bsfs)

{

    char *bsf_name, *buf, *saveptr;

    int ret = 0;



    if (!(buf = av_strdup(bsfs_spec)))

        return AVERROR(ENOMEM);



    while (bsf_name = av_strtok(buf, ",", &saveptr)) {

        AVBitStreamFilterContext *bsf = av_bitstream_filter_init(bsf_name);



        if (!bsf) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Cannot initialize bitstream filter with name '%s', "

                   "unknown filter or internal error happened\n",

                   bsf_name);

            ret = AVERROR_UNKNOWN;

            goto end;

        }



        /* append bsf context to the list of bsf contexts */

        *bsfs = bsf;

        bsfs = &bsf->next;



        buf = NULL;

    }



end:

    av_free(buf);

    return ret;

}

uint8_t* ff_AMediaCodec_getOutputBuffer(FFAMediaCodec* codec, size_t idx, size_t *out_size)

{

    uint8_t *ret = NULL;

    JNIEnv *env = NULL;



    jobject buffer = NULL;



    JNI_GET_ENV_OR_RETURN(env, codec, NULL);



    if (codec->has_get_i_o_buffer) {

        buffer = (*env)->CallObjectMethod(env, codec->object, codec->jfields.get_output_buffer_id, idx);

        if (ff_jni_exception_check(env, 1, codec) < 0) {

            goto fail;

        }

    } else {

        if (!codec->output_buffers) {

            codec->output_buffers = (*env)->CallObjectMethod(env, codec->object, codec->jfields.get_output_buffers_id);

            if (ff_jni_exception_check(env, 1, codec) < 0) {

                goto fail;

            }



            codec->output_buffers = (*env)->NewGlobalRef(env, codec->output_buffers);

            if (ff_jni_exception_check(env, 1, codec) < 0) {

                goto fail;

            }

        }



        buffer = (*env)->GetObjectArrayElement(env, codec->output_buffers, idx);

        if (ff_jni_exception_check(env, 1, codec) < 0) {

            goto fail;

        }

    }



    ret = (*env)->GetDirectBufferAddress(env, buffer);

    *out_size = (*env)->GetDirectBufferCapacity(env, buffer);

fail:

    if (buffer) {

        (*env)->DeleteLocalRef(env, buffer);

    }



    return ret;

}

char *ff_AMediaCodecList_getCodecNameByType(const char *mime, int width, int height, void *log_ctx)

{

    int ret;

    char *name = NULL;

    char *supported_type = NULL;



    int attached = 0;

    JNIEnv *env = NULL;

    struct JNIAMediaCodecListFields jfields = { 0 };



    jobject format = NULL;

    jobject codec = NULL;

    jstring tmp = NULL;



    jobject info = NULL;

    jobject type = NULL;

    jobjectArray types = NULL;



    JNI_ATTACH_ENV_OR_RETURN(env, &attached, log_ctx, NULL);



    if ((ret = ff_jni_init_jfields(env, &jfields, jni_amediacodeclist_mapping, 0, log_ctx)) < 0) {

        goto done;

    }



    if (jfields.init_id && jfields.find_decoder_for_format_id) {

        tmp = ff_jni_utf_chars_to_jstring(env, mime, log_ctx);

        if (!tmp) {

            goto done;

        }



        format = (*env)->CallStaticObjectMethod(env, jfields.mediaformat_class, jfields.create_video_format_id, tmp, width, height);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }

        (*env)->DeleteLocalRef(env, tmp);

        tmp = NULL;



        codec = (*env)->NewObject(env, jfields.mediacodec_list_class, jfields.init_id, 0);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }



        tmp = (*env)->CallObjectMethod(env, codec, jfields.find_decoder_for_format_id, format);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }

        if (!tmp) {

            av_log(NULL, AV_LOG_ERROR, "Could not find decoder in media codec list "

                                       "for format { mime=%s width=%d height=%d }\n", mime, width, height);

            goto done;

        }



        name = ff_jni_jstring_to_utf_chars(env, tmp, log_ctx);

        if (!name) {

            goto done;

        }



    } else {

        int i;

        int codec_count;



        codec_count = (*env)->CallStaticIntMethod(env, jfields.mediacodec_list_class, jfields.get_codec_count_id);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }



        for(i = 0; i < codec_count; i++) {

            int j;

            int type_count;

            int is_encoder;



            info = (*env)->CallStaticObjectMethod(env, jfields.mediacodec_list_class, jfields.get_codec_info_at_id, i);

            if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                goto done;

            }



            types = (*env)->CallObjectMethod(env, info, jfields.get_supported_types_id);

            if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                goto done;

            }



            is_encoder = (*env)->CallBooleanMethod(env, info, jfields.is_encoder_id);

            if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                goto done;

            }



            if (is_encoder) {

                continue;

            }



            type_count = (*env)->GetArrayLength(env, types);

            for (j = 0; j < type_count; j++) {



                type = (*env)->GetObjectArrayElement(env, types, j);

                if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                    goto done;

                }



                supported_type = ff_jni_jstring_to_utf_chars(env, type, log_ctx);

                if (!supported_type) {

                    goto done;

                }



                if (!av_strcasecmp(supported_type, mime)) {

                    jobject codec_name;



                    codec_name = (*env)->CallObjectMethod(env, info, jfields.get_name_id);

                    if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                        goto done;

                    }



                    name = ff_jni_jstring_to_utf_chars(env, codec_name, log_ctx);

                    if (!name) {

                        goto done;

                    }



                    if (strstr(name, "OMX.google")) {

                        av_freep(&name);

                        continue;

                    }

                }



                av_freep(&supported_type);

            }



            (*env)->DeleteLocalRef(env, info);

            info = NULL;



            (*env)->DeleteLocalRef(env, types);

            types = NULL;



            if (name)

                break;

        }

    }



done:

    if (format) {

        (*env)->DeleteLocalRef(env, format);

    }



    if (codec) {

        (*env)->DeleteLocalRef(env, codec);

    }



    if (tmp) {

        (*env)->DeleteLocalRef(env, tmp);

    }



    if (info) {

        (*env)->DeleteLocalRef(env, info);

    }



    if (type) {

        (*env)->DeleteLocalRef(env, type);

    }



    if (types) {

        (*env)->DeleteLocalRef(env, types);

    }



    av_freep(&supported_type);



    ff_jni_reset_jfields(env, &jfields, jni_amediacodeclist_mapping, 0, log_ctx);



    JNI_DETACH_ENV(attached, log_ctx);



    return name;

}

static int check_jni_invocation(void *log_ctx)

{

    int ret = AVERROR_EXTERNAL;

    void *handle = NULL;

    void **jni_invocation = NULL;



    handle = dlopen(NULL, RTLD_LOCAL);

    if (!handle) {

        goto done;

    }



    jni_invocation = (void **)dlsym(handle, "_ZN13JniInvocation15jni_invocation_E");

    if (!jni_invocation) {

        av_log(log_ctx, AV_LOG_ERROR, "Could not find JniInvocation::jni_invocation_ symbol\n");

        goto done;

    }



    ret = !(jni_invocation != NULL && *jni_invocation != NULL);



done:

    if (handle) {

        dlclose(handle);

    }



    return ret;

}

static void vscsi_send_request_sense(VSCSIState *s, vscsi_req *req)

{

    SCSIDevice *sdev = req->sdev;

    uint8_t *cdb = req->iu.srp.cmd.cdb;

    int n;



    cdb[0] = 3;

    cdb[1] = 0;

    cdb[2] = 0;

    cdb[3] = 0;

    cdb[4] = 96;

    cdb[5] = 0;

    req->sensing = 1;

    n = sdev->info->send_command(sdev, req->qtag, cdb, req->lun);

    dprintf("VSCSI: Queued request sense tag 0x%x\n", req->qtag);

    if (n < 0) {

        fprintf(stderr, "VSCSI: REQUEST_SENSE wants write data !?!?!?\n");

        sdev->info->cancel_io(sdev, req->qtag);

        vscsi_makeup_sense(s, req, HARDWARE_ERROR, 0, 0);

        vscsi_send_rsp(s, req, CHECK_CONDITION, 0, 0);

        vscsi_put_req(s, req);

        return;

    } else if (n == 0) {

        return;

    }

    sdev->info->read_data(sdev, req->qtag);

}

static void vscsi_command_complete(SCSIRequest *sreq, uint32_t status)

{

    VSCSIState *s = DO_UPCAST(VSCSIState, vdev.qdev, sreq->bus->qbus.parent);

    vscsi_req *req = sreq->hba_private;

    int32_t res_in = 0, res_out = 0;



    dprintf("VSCSI: SCSI cmd complete, r=0x%x tag=0x%x status=0x%x, req=%p\n",

            reason, sreq->tag, status, req);

    if (req == NULL) {

        fprintf(stderr, "VSCSI: Can't find request for tag 0x%x\n", sreq->tag);

        return;

    }



    if (status == CHECK_CONDITION) {

        req->senselen = scsi_req_get_sense(req->sreq, req->sense,

                                           sizeof(req->sense));

        status = 0;

        dprintf("VSCSI: Sense data, %d bytes:\n", len);

        dprintf("       %02x  %02x  %02x  %02x  %02x  %02x  %02x  %02x\n",

                req->sense[0], req->sense[1], req->sense[2], req->sense[3],

                req->sense[4], req->sense[5], req->sense[6], req->sense[7]);

        dprintf("       %02x  %02x  %02x  %02x  %02x  %02x  %02x  %02x\n",

                req->sense[8], req->sense[9], req->sense[10], req->sense[11],

                req->sense[12], req->sense[13], req->sense[14], req->sense[15]);

    }



    dprintf("VSCSI: Command complete err=%d\n", status);

    if (status == 0) {

        /* We handle overflows, not underflows for normal commands,

         * but hopefully nobody cares

         */

        if (req->writing) {

            res_out = req->data_len;

        } else {

            res_in = req->data_len;

        }

    }

    vscsi_send_rsp(s, req, status, res_in, res_out);

    vscsi_put_req(req);

}

static void vscsi_inquiry_no_target(VSCSIState *s, vscsi_req *req)

{

    uint8_t *cdb = req->iu.srp.cmd.cdb;

    uint8_t resp_data[36];

    int rc, len, alen;



    /* We dont do EVPD. Also check that page_code is 0 */

    if ((cdb[1] & 0x01) || (cdb[1] & 0x01) || cdb[2] != 0) {

        /* Send INVALID FIELD IN CDB */

        vscsi_makeup_sense(s, req, ILLEGAL_REQUEST, 0x24, 0);

        vscsi_send_rsp(s, req, CHECK_CONDITION, 0, 0);

        return;

    }

    alen = cdb[3];

    alen = (alen << 8) | cdb[4];

    len = MIN(alen, 36);



    /* Fake up inquiry using PQ=3 */

    memset(resp_data, 0, 36);

    resp_data[0] = 0x7f;   /* Not capable of supporting a device here */

    resp_data[2] = 0x06;   /* SPS-4 */

    resp_data[3] = 0x02;   /* Resp data format */

    resp_data[4] = 36 - 5; /* Additional length */

    resp_data[7] = 0x10;   /* Sync transfers */

    memcpy(&resp_data[16], "QEMU EMPTY      ", 16);

    memcpy(&resp_data[8], "QEMU    ", 8);



    req->writing = 0;

    vscsi_preprocess_desc(req);

    rc = vscsi_srp_transfer_data(s, req, 0, resp_data, len);

    if (rc < 0) {

        vscsi_makeup_sense(s, req, HARDWARE_ERROR, 0, 0);

        vscsi_send_rsp(s, req, CHECK_CONDITION, 0, 0);

    } else {

        vscsi_send_rsp(s, req, 0, 36 - rc, 0);

    }

}

static void generate_eeprom_spd(uint8_t *eeprom, ram_addr_t ram_size)

{

    enum { SDR = 0x4, DDR2 = 0x8 } type;

    uint8_t *spd = spd_eeprom.contents;

    uint8_t nbanks = 0;

    uint16_t density = 0;

    int i;



    /* work in terms of MB */

    ram_size >>= 20;



    while ((ram_size >= 4) && (nbanks <= 2)) {

        int sz_log2 = MIN(31 - clz32(ram_size), 14);

        nbanks++;

        density |= 1 << (sz_log2 - 2);

        ram_size -= 1 << sz_log2;

    }



    /* split to 2 banks if possible */

    if ((nbanks == 1) && (density > 1)) {

        nbanks++;

        density >>= 1;

    }



    if (density & 0xff00) {

        density = (density & 0xe0) | ((density >> 8) & 0x1f);

        type = DDR2;

    } else if (!(density & 0x1f)) {

        type = DDR2;

    } else {

        type = SDR;

    }



    if (ram_size) {

        fprintf(stderr, "Warning: SPD cannot represent final %dMB"

                " of SDRAM\n", (int)ram_size);

    }



    /* fill in SPD memory information */

    spd[2] = type;

    spd[5] = nbanks;

    spd[31] = density;



    /* checksum */

    spd[63] = 0;

    for (i = 0; i < 63; i++) {

        spd[63] += spd[i];

    }



    /* copy for SMBUS */

    memcpy(eeprom, spd, sizeof(spd_eeprom.contents));

}

