sPAPRTCETable *spapr_tce_new_table(DeviceState *owner, uint32_t liobn, size_t window_size)

{

    sPAPRTCETable *tcet;



    if (spapr_tce_find_by_liobn(liobn)) {

        fprintf(stderr, "Attempted to create TCE table with duplicate"

                " LIOBN 0x%x\n", liobn);

        return NULL;

    }



    if (!window_size) {

        return NULL;

    }



    tcet = g_malloc0(sizeof(*tcet));

    tcet->liobn = liobn;

    tcet->window_size = window_size;



    if (kvm_enabled()) {

        tcet->table = kvmppc_create_spapr_tce(liobn,

                                              window_size,

                                              &tcet->fd);

    }



    if (!tcet->table) {

        size_t table_size = (window_size >> SPAPR_TCE_PAGE_SHIFT)

            * sizeof(sPAPRTCE);

        tcet->table = g_malloc0(table_size);

    }



#ifdef DEBUG_TCE

    fprintf(stderr, "spapr_iommu: New TCE table @ %p, liobn=0x%x, "

            "table @ %p, fd=%d\n", tcet, liobn, tcet->table, tcet->fd);

#endif



    memory_region_init_iommu(&tcet->iommu, OBJECT(owner), &spapr_iommu_ops,

                             "iommu-spapr", UINT64_MAX);



    QLIST_INSERT_HEAD(&spapr_tce_tables, tcet, list);



    return tcet;

}

sPAPRDRConnector *spapr_dr_connector_new(Object *owner, const char *type,

                                         uint32_t id)

{

    sPAPRDRConnector *drc = SPAPR_DR_CONNECTOR(object_new(type));

    char *prop_name;



    drc->id = id;

    drc->owner = owner;

    prop_name = g_strdup_printf("dr-connector[%"PRIu32"]",

                                spapr_drc_index(drc));

    object_property_add_child(owner, prop_name, OBJECT(drc), NULL);

    object_property_set_bool(OBJECT(drc), true, "realized", NULL);

    g_free(prop_name);



    /* PCI slot always start in a USABLE state, and stay there */

    if (spapr_drc_type(drc) == SPAPR_DR_CONNECTOR_TYPE_PCI) {

        drc->allocation_state = SPAPR_DR_ALLOCATION_STATE_USABLE;

    }



    return drc;

}

void spapr_tce_table_enable(sPAPRTCETable *tcet,

                            uint32_t page_shift, uint64_t bus_offset,

                            uint32_t nb_table)

{

    if (tcet->nb_table) {

        error_report("Warning: trying to enable already enabled TCE table");

        return;

    }



    tcet->bus_offset = bus_offset;

    tcet->page_shift = page_shift;

    tcet->nb_table = nb_table;

    tcet->table = spapr_tce_alloc_table(tcet->liobn,

                                        tcet->page_shift,

                                        tcet->bus_offset,

                                        tcet->nb_table,

                                        &tcet->fd,

                                        tcet->need_vfio);



    memory_region_set_size(&tcet->iommu,

                           (uint64_t)tcet->nb_table << tcet->page_shift);

    memory_region_add_subregion(&tcet->root, tcet->bus_offset, &tcet->iommu);

}

static int usb_net_handle_statusin(USBNetState *s, USBPacket *p)

{

    int ret = 8;



    if (p->len < 8)

        return USB_RET_STALL;



    ((le32 *) p->data)[0] = cpu_to_le32(1);

    ((le32 *) p->data)[1] = cpu_to_le32(0);

    if (!s->rndis_resp.tqh_first)

        ret = USB_RET_NAK;



#ifdef TRAFFIC_DEBUG

    fprintf(stderr, "usbnet: interrupt poll len %u return %d", p->len, ret);

    {

        int i;

        fprintf(stderr, ":");

        for (i = 0; i < ret; i++) {

            if (!(i & 15))

                fprintf(stderr, "\n%04x:", i);

            fprintf(stderr, " %02x", p->data[i]);

        }

        fprintf(stderr, "\n\n");

    }

#endif



    return ret;

}

static void print_track_chunks(FILE *out, struct Tracks *tracks, int main,

                               const char *type)

{

    int i, j;

    struct Track *track = tracks->tracks[main];

    for (i = 0; i < track->chunks; i++) {

        for (j = main + 1; j < tracks->nb_tracks; j++) {

            if (tracks->tracks[j]->is_audio == track->is_audio &&

                track->offsets[i].duration != tracks->tracks[j]->offsets[i].duration)

                fprintf(stderr, "Mismatched duration of %s chunk %d in %s and %s\n",

                        type, i, track->name, tracks->tracks[j]->name);

        }

        fprintf(out, "\t\t<c n=\"%d\" d=\"%d\" />\n",

                i, track->offsets[i].duration);

    }

}

