        AVDictionaryEntry *en = NULL;



        if (!av_dict_parse_string(&dict, x4->x264_params, "=", ":", 0)) {

            while ((en = av_dict_get(dict, "", en, AV_DICT_IGNORE_SUFFIX))) {

                if (x264_param_parse(&x4->params, en->key, en->value) < 0)

                    av_log(avctx, AV_LOG_WARNING,

                           "Error parsing option '%s = %s'.\n",

                            en->key, en->value);

            }



            av_dict_free(&dict);

        }

    }



    // update AVCodecContext with x264 parameters

    avctx->has_b_frames = x4->params.i_bframe ?

        x4->params.i_bframe_pyramid ? 2 : 1 : 0;

    if (avctx->max_b_frames < 0)

        avctx->max_b_frames = 0;



    avctx->bit_rate = x4->params.rc.i_bitrate*1000;



    x4->enc = x264_encoder_open(&x4->params);

    if (!x4->enc)

        return AVERROR_UNKNOWN;



    if (avctx->flags & AV_CODEC_FLAG_GLOBAL_HEADER) {

        x264_nal_t *nal;

        uint8_t *p;

        int nnal, s, i;



        s = x264_encoder_headers(x4->enc, &nal, &nnal);

        avctx->extradata = p = av_mallocz(s + AV_INPUT_BUFFER_PADDING_SIZE);

        if (!p)

            return AVERROR(ENOMEM);



        for (i = 0; i < nnal; i++) {

            /* Don't put the SEI in extradata. */

            if (nal[i].i_type == NAL_SEI) {

                av_log(avctx, AV_LOG_INFO, "%s\n", nal[i].p_payload+25);

                x4->sei_size = nal[i].i_payload;

                x4->sei      = av_malloc(x4->sei_size);

                if (!x4->sei)

                    return AVERROR(ENOMEM);

                memcpy(x4->sei, nal[i].p_payload, nal[i].i_payload);

                continue;

            }

            memcpy(p, nal[i].p_payload, nal[i].i_payload);

            p += nal[i].i_payload;

        }

        avctx->extradata_size = p - avctx->extradata;

    }



    cpb_props = ff_add_cpb_side_data(avctx);

    if (!cpb_props)

        return AVERROR(ENOMEM);

    cpb_props->buffer_size = x4->params.rc.i_vbv_buffer_size * 1000;

    cpb_props->max_bitrate = x4->params.rc.i_vbv_max_bitrate * 1000;

    cpb_props->avg_bitrate = x4->params.rc.i_bitrate         * 1000;



    return 0;

}

static av_cold int decoder_init(AVCodecContext * avctx)

{

    G729Context* ctx = avctx->priv_data;

    int i,k;



    if (avctx->channels != 1) {

        av_log(avctx, AV_LOG_ERROR, "Only mono sound is supported (requested channels: %d).\n", avctx->channels);

        return AVERROR(EINVAL);

    }

    avctx->sample_fmt = AV_SAMPLE_FMT_S16;



    /* Both 8kbit/s and 6.4kbit/s modes uses two subframes per frame. */

    avctx->frame_size = SUBFRAME_SIZE << 1;



    ctx->gain_coeff = 16384; // 1.0 in (1.14)



    for (k = 0; k < MA_NP + 1; k++) {

        ctx->past_quantizer_outputs[k] = ctx->past_quantizer_output_buf[k];

        for (i = 1; i < 11; i++)

            ctx->past_quantizer_outputs[k][i - 1] = (18717 * i) >> 3;

    }



    ctx->lsp[0] = ctx->lsp_buf[0];

    ctx->lsp[1] = ctx->lsp_buf[1];

    memcpy(ctx->lsp[0], lsp_init, 10 * sizeof(int16_t));



    ctx->exc = &ctx->exc_base[PITCH_DELAY_MAX+INTERPOL_LEN];



    /* random seed initialization */

    ctx->rand_value = 21845;



    /* quantized prediction error */

    for(i=0; i<4; i++)

        ctx->quant_energy[i] = -14336; // -14 in (5.10)



    avctx->dsp_mask= ~AV_CPU_FLAG_FORCE;

    dsputil_init(&ctx->dsp, avctx);



    return 0;

}

static av_cold int omx_encode_init(AVCodecContext *avctx)

{

    OMXCodecContext *s = avctx->priv_data;

    int ret = AVERROR_ENCODER_NOT_FOUND;

    const char *role;

    OMX_BUFFERHEADERTYPE *buffer;

    OMX_ERRORTYPE err;



#if CONFIG_OMX_RPI

    s->input_zerocopy = 1;

#endif



    s->omx_context = omx_init(avctx, s->libname, s->libprefix);

    if (!s->omx_context)

        return AVERROR_ENCODER_NOT_FOUND;



    pthread_mutex_init(&s->state_mutex, NULL);

    pthread_cond_init(&s->state_cond, NULL);

    pthread_mutex_init(&s->input_mutex, NULL);

    pthread_cond_init(&s->input_cond, NULL);

    pthread_mutex_init(&s->output_mutex, NULL);

    pthread_cond_init(&s->output_cond, NULL);

    s->mutex_cond_inited = 1;

    s->avctx = avctx;

    s->state = OMX_StateLoaded;

    s->error = OMX_ErrorNone;



    switch (avctx->codec->id) {

    case AV_CODEC_ID_MPEG4:

        role = "video_encoder.mpeg4";

        break;

    case AV_CODEC_ID_H264:

        role = "video_encoder.avc";

        break;

    default:

        return AVERROR(ENOSYS);

    }



    if ((ret = find_component(s->omx_context, avctx, role, s->component_name, sizeof(s->component_name))) < 0)

        goto fail;



    av_log(avctx, AV_LOG_INFO, "Using %s\n", s->component_name);



    if ((ret = omx_component_init(avctx, role)) < 0)

        goto fail;



    if (avctx->flags & AV_CODEC_FLAG_GLOBAL_HEADER) {

        while (1) {

            buffer = get_buffer(&s->output_mutex, &s->output_cond,

                                &s->num_done_out_buffers, s->done_out_buffers, 1);

            if (buffer->nFlags & OMX_BUFFERFLAG_CODECCONFIG) {

                if ((ret = av_reallocp(&avctx->extradata, avctx->extradata_size + buffer->nFilledLen + AV_INPUT_BUFFER_PADDING_SIZE)) < 0) {

                    avctx->extradata_size = 0;

                    goto fail;

                }

                memcpy(avctx->extradata + avctx->extradata_size, buffer->pBuffer + buffer->nOffset, buffer->nFilledLen);

                avctx->extradata_size += buffer->nFilledLen;

                memset(avctx->extradata + avctx->extradata_size, 0, AV_INPUT_BUFFER_PADDING_SIZE);

            }

            err = OMX_FillThisBuffer(s->handle, buffer);

            if (err != OMX_ErrorNone) {

                append_buffer(&s->output_mutex, &s->output_cond,

                              &s->num_done_out_buffers, s->done_out_buffers, buffer);

                av_log(avctx, AV_LOG_ERROR, "OMX_FillThisBuffer failed: %x\n", err);

                ret = AVERROR_UNKNOWN;

                goto fail;

            }

            if (avctx->codec->id == AV_CODEC_ID_H264) {

                // For H.264, the extradata can be returned in two separate buffers

                // (the videocore encoder on raspberry pi does this);

                // therefore check that we have got both SPS and PPS before continuing.

                int nals[32] = { 0 };

                int i;

                for (i = 0; i + 4 < avctx->extradata_size; i++) {

                     if (!avctx->extradata[i + 0] &&

                         !avctx->extradata[i + 1] &&

                         !avctx->extradata[i + 2] &&

                         avctx->extradata[i + 3] == 1) {

                         nals[avctx->extradata[i + 4] & 0x1f]++;

                     }

                }

                if (nals[NAL_SPS] && nals[NAL_PPS])

                    break;

            } else {

                if (avctx->extradata_size > 0)

                    break;

            }

        }

    }



    return 0;

fail:

    return ret;

}

static void watch_mem_write(void *opaque, hwaddr addr,

                            uint64_t val, unsigned size)

{

    check_watchpoint(addr & ~TARGET_PAGE_MASK, size, BP_MEM_WRITE);

    switch (size) {

    case 1:

        stb_phys(&address_space_memory, addr, val);

        break;

    case 2:

        stw_phys(&address_space_memory, addr, val);

        break;

    case 4:

        stl_phys(&address_space_memory, addr, val);

        break;

    default: abort();

    }

}

static void pxa2xx_pm_write(void *opaque, hwaddr addr,

                            uint64_t value, unsigned size)

{

    PXA2xxState *s = (PXA2xxState *) opaque;



    switch (addr) {

    case PMCR:

        /* Clear the write-one-to-clear bits... */

        s->pm_regs[addr >> 2] &= ~(value & 0x2a);

        /* ...and set the plain r/w bits */

        s->pm_regs[addr >> 2] &= ~0x15;

        s->pm_regs[addr >> 2] |= value & 0x15;

        break;



    case PSSR:	/* Read-clean registers */

    case RCSR:

    case PKSR:

        s->pm_regs[addr >> 2] &= ~value;

        break;



    default:	/* Read-write registers */

        if (!(addr & 3)) {

            s->pm_regs[addr >> 2] = value;

            break;

        }



        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

}

static uint64_t pxa2xx_rtc_read(void *opaque, hwaddr addr,

                                unsigned size)

{

    PXA2xxRTCState *s = (PXA2xxRTCState *) opaque;



    switch (addr) {

    case RTTR:

        return s->rttr;

    case RTSR:

        return s->rtsr;

    case RTAR:

        return s->rtar;

    case RDAR1:

        return s->rdar1;

    case RDAR2:

        return s->rdar2;

    case RYAR1:

        return s->ryar1;

    case RYAR2:

        return s->ryar2;

    case SWAR1:

        return s->swar1;

    case SWAR2:

        return s->swar2;

    case PIAR:

        return s->piar;

    case RCNR:

        return s->last_rcnr +

            ((qemu_clock_get_ms(rtc_clock) - s->last_hz) << 15) /

            (1000 * ((s->rttr & 0xffff) + 1));

    case RDCR:

        return s->last_rdcr +

            ((qemu_clock_get_ms(rtc_clock) - s->last_hz) << 15) /

            (1000 * ((s->rttr & 0xffff) + 1));

    case RYCR:

        return s->last_rycr;

    case SWCR:

        if (s->rtsr & (1 << 12))

            return s->last_swcr +

                (qemu_clock_get_ms(rtc_clock) - s->last_sw) / 10;

        else

            return s->last_swcr;

    default:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

    return 0;

}

static void pxa2xx_pic_mem_write(void *opaque, hwaddr offset,

                                 uint64_t value, unsigned size)

{

    PXA2xxPICState *s = (PXA2xxPICState *) opaque;



    switch (offset) {

    case ICMR:	/* Mask register */

        s->int_enabled[0] = value;

        break;

    case ICMR2:	/* Mask register 2 */

        s->int_enabled[1] = value;

        break;

    case ICLR:	/* Level register */

        s->is_fiq[0] = value;

        break;

    case ICLR2:	/* Level register 2 */

        s->is_fiq[1] = value;

        break;

    case ICCR:	/* Idle mask */

        s->int_idle = (value & 1) ? 0 : ~0;

        break;

    case IPR0  ... IPR31:

        s->priority[0  + ((offset - IPR0 ) >> 2)] = value & 0x8000003f;

        break;

    case IPR32 ... IPR39:

        s->priority[32 + ((offset - IPR32) >> 2)] = value & 0x8000003f;

        break;

    default:

        printf("%s: Bad register offset " REG_FMT "\n", __FUNCTION__, offset);

        return;

    }

    pxa2xx_pic_update(opaque);

}

