            return;

        }



        uint32_t rx_space = rxdw0 & CP_RX_BUFFER_SIZE_MASK;



        /* TODO: scatter the packet over available receive ring descriptors space */



        if (size+4 > rx_space)

        {

            DEBUG_PRINT(("RTL8139: C+ Rx mode : descriptor %d size %d received %d + 4\n",

                   descriptor, rx_space, size));



            s->IntrStatus |= RxOverflow;

            ++s->RxMissed;



            /* update tally counter */

            ++s->tally_counters.RxERR;

            ++s->tally_counters.MissPkt;



            rtl8139_update_irq(s);

            return;

        }



        target_phys_addr_t rx_addr = rtl8139_addr64(rxbufLO, rxbufHI);



        /* receive/copy to target memory */

        cpu_physical_memory_write( rx_addr, buf, size );



        if (s->CpCmd & CPlusRxChkSum)

        {

            /* do some packet checksumming */

        }



        /* write checksum */

#if defined (RTL8139_CALCULATE_RXCRC)

        val = cpu_to_le32(crc32(~0, buf, size));

#else

        val = 0;

#endif

        cpu_physical_memory_write( rx_addr+size, (uint8_t *)&val, 4);



/* first segment of received packet flag */

#define CP_RX_STATUS_FS (1<<29)

/* last segment of received packet flag */

#define CP_RX_STATUS_LS (1<<28)

/* multicast packet flag */

#define CP_RX_STATUS_MAR (1<<26)

/* physical-matching packet flag */

#define CP_RX_STATUS_PAM (1<<25)

/* broadcast packet flag */

#define CP_RX_STATUS_BAR (1<<24)

/* runt packet flag */

#define CP_RX_STATUS_RUNT (1<<19)

/* crc error flag */

#define CP_RX_STATUS_CRC (1<<18)

/* IP checksum error flag */

#define CP_RX_STATUS_IPF (1<<15)

/* UDP checksum error flag */

#define CP_RX_STATUS_UDPF (1<<14)

/* TCP checksum error flag */

#define CP_RX_STATUS_TCPF (1<<13)



        /* transfer ownership to target */

        rxdw0 &= ~CP_RX_OWN;



        /* set first segment bit */

        rxdw0 |= CP_RX_STATUS_FS;



        /* set last segment bit */

        rxdw0 |= CP_RX_STATUS_LS;



        /* set received packet type flags */

        if (packet_header & RxBroadcast)

            rxdw0 |= CP_RX_STATUS_BAR;

        if (packet_header & RxMulticast)

            rxdw0 |= CP_RX_STATUS_MAR;

        if (packet_header & RxPhysical)

            rxdw0 |= CP_RX_STATUS_PAM;



        /* set received size */

        rxdw0 &= ~CP_RX_BUFFER_SIZE_MASK;

        rxdw0 |= (size+4);



        /* reset VLAN tag flag */

        rxdw1 &= ~CP_RX_TAVA;



        /* update ring data */

        val = cpu_to_le32(rxdw0);

        cpu_physical_memory_write(cplus_rx_ring_desc,    (uint8_t *)&val, 4);

        val = cpu_to_le32(rxdw1);

        cpu_physical_memory_write(cplus_rx_ring_desc+4,  (uint8_t *)&val, 4);



        /* update tally counter */

        ++s->tally_counters.RxOk;



        /* seek to next Rx descriptor */

        if (rxdw0 & CP_RX_EOR)

        {

            s->currCPlusRxDesc = 0;

        }

        else

        {

            ++s->currCPlusRxDesc;

        }



        DEBUG_PRINT(("RTL8139: done C+ Rx mode ----------------\n"));



    }

    else

    {

        DEBUG_PRINT(("RTL8139: in ring Rx mode ================\n"));



        /* begin ring receiver mode */

        int avail = MOD2(s->RxBufferSize + s->RxBufPtr - s->RxBufAddr, s->RxBufferSize);



        /* if receiver buffer is empty then avail == 0 */



        if (avail != 0 && size + 8 >= avail)

        {

            DEBUG_PRINT(("rx overflow: rx buffer length %d head 0x%04x read 0x%04x === available 0x%04x need 0x%04x\n",

                   s->RxBufferSize, s->RxBufAddr, s->RxBufPtr, avail, size + 8));



            s->IntrStatus |= RxOverflow;

            ++s->RxMissed;

            rtl8139_update_irq(s);

            return;

        }



        packet_header |= RxStatusOK;



        packet_header |= (((size+4) << 16) & 0xffff0000);



        /* write header */

        uint32_t val = cpu_to_le32(packet_header);



        rtl8139_write_buffer(s, (uint8_t *)&val, 4);



        rtl8139_write_buffer(s, buf, size);



        /* write checksum */

#if defined (RTL8139_CALCULATE_RXCRC)

        val = cpu_to_le32(crc32(~0, buf, size));

#else

        val = 0;

#endif



        rtl8139_write_buffer(s, (uint8_t *)&val, 4);



        /* correct buffer write pointer */

        s->RxBufAddr = MOD2((s->RxBufAddr + 3) & ~0x3, s->RxBufferSize);



        /* now we can signal we have received something */



        DEBUG_PRINT(("   received: rx buffer length %d head 0x%04x read 0x%04x\n",

               s->RxBufferSize, s->RxBufAddr, s->RxBufPtr));

    }



    s->IntrStatus |= RxOK;



    if (do_interrupt)

    {

        rtl8139_update_irq(s);

    }

}

static void smc91c111_receive(void *opaque, const uint8_t *buf, size_t size)

{

    smc91c111_state *s = (smc91c111_state *)opaque;

    int status;

    int packetsize;

    uint32_t crc;

    int packetnum;

    uint8_t *p;



    if ((s->rcr & RCR_RXEN) == 0 || (s->rcr & RCR_SOFT_RST))

        return;

    /* Short packets are padded with zeros.  Receiving a packet

       < 64 bytes long is considered an error condition.  */

    if (size < 64)

        packetsize = 64;

    else

        packetsize = (size & ~1);

    packetsize += 6;

    crc = (s->rcr & RCR_STRIP_CRC) == 0;

    if (crc)

        packetsize += 4;

    /* TODO: Flag overrun and receive errors.  */

    if (packetsize > 2048)

        return;

    packetnum = smc91c111_allocate_packet(s);

    if (packetnum == 0x80)

        return;

    s->rx_fifo[s->rx_fifo_len++] = packetnum;



    p = &s->data[packetnum][0];

    /* ??? Multicast packets?  */

    status = 0;

    if (size > 1518)

        status |= RS_TOOLONG;

    if (size & 1)

        status |= RS_ODDFRAME;

    *(p++) = status & 0xff;

    *(p++) = status >> 8;

    *(p++) = packetsize & 0xff;

    *(p++) = packetsize >> 8;

    memcpy(p, buf, size & ~1);

    p += (size & ~1);

    /* Pad short packets.  */

    if (size < 64) {

        int pad;



        if (size & 1)

            *(p++) = buf[size - 1];

        pad = 64 - size;

        memset(p, 0, pad);

        p += pad;

        size = 64;

    }

    /* It's not clear if the CRC should go before or after the last byte in

       odd sized packets.  Linux disables the CRC, so that's no help.

       The pictures in the documentation show the CRC aligned on a 16-bit

       boundary before the last odd byte, so that's what we do.  */

    if (crc) {

        crc = crc32(~0, buf, size);

        *(p++) = crc & 0xff; crc >>= 8;

        *(p++) = crc & 0xff; crc >>= 8;

        *(p++) = crc & 0xff; crc >>= 8;

        *(p++) = crc & 0xff; crc >>= 8;

    }

    if (size & 1) {

        *(p++) = buf[size - 1];

        *(p++) = 0x60;

    } else {

        *(p++) = 0;

        *(p++) = 0x40;

    }

    /* TODO: Raise early RX interrupt?  */

    s->int_level |= INT_RCV;

    smc91c111_update(s);

}

static void residual_interp(int16_t *buf, int16_t *out, int lag,

                            int gain, int *rseed)

{

    int i;

    if (lag) { /* Voiced */

        int16_t *vector_ptr = buf + PITCH_MAX;

        /* Attenuate */

        for (i = 0; i < lag; i++)

            out[i] = vector_ptr[i - lag] * 3 >> 2;

        av_memcpy_backptr((uint8_t*)(out + lag), lag * sizeof(*out),

                          (FRAME_LEN - lag) * sizeof(*out));

    } else {  /* Unvoiced */

        for (i = 0; i < FRAME_LEN; i++) {

            *rseed = *rseed * 521 + 259;

            out[i] = gain * *rseed >> 15;

        }

        memset(buf, 0, (FRAME_LEN + PITCH_MAX) * sizeof(*buf));

    }

}

void ff_mqc_init_contexts(MqcState *mqc)

{

    int i;

    memset(mqc->cx_states, 0, sizeof(mqc->cx_states));

    mqc->cx_states[MQC_CX_UNI] = 2 * 46;

    mqc->cx_states[MQC_CX_RL]  = 2 * 3;

    mqc->cx_states[0]          = 2 * 4;



    for (i = 0; i < 47; i++) {

        ff_mqc_qe[2 * i]     =

        ff_mqc_qe[2 * i + 1] = cx_states[i].qe;



        ff_mqc_nlps[2 * i]     = 2 * cx_states[i].nlps + cx_states[i].sw;

        ff_mqc_nlps[2 * i + 1] = 2 * cx_states[i].nlps + 1 - cx_states[i].sw;

        ff_mqc_nmps[2 * i]     = 2 * cx_states[i].nmps;

        ff_mqc_nmps[2 * i + 1] = 2 * cx_states[i].nmps + 1;

    }

}

static inline void mix_3f_to_mono(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++)

        output[1][i] += (output[2][i] + output[3][i]);

    memset(output[2], 0, sizeof(output[2]));

    memset(output[3], 0, sizeof(output[3]));

}

static inline void mix_3f_2r_to_mono(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++)

        output[1][i] += (output[2][i] + output[3][i] + output[4][i] + output[5][i]);

    memset(output[2], 0, sizeof(output[2]));

    memset(output[3], 0, sizeof(output[3]));

    memset(output[4], 0, sizeof(output[4]));

    memset(output[5], 0, sizeof(output[5]));

}

static void scsi_generic_purge_requests(SCSIGenericState *s)

{

    SCSIGenericReq *r;



    while (!QTAILQ_EMPTY(&s->qdev.requests)) {

        r = DO_UPCAST(SCSIGenericReq, req, QTAILQ_FIRST(&s->qdev.requests));

        if (r->req.aiocb) {

            bdrv_aio_cancel(r->req.aiocb);

        }

        scsi_remove_request(r);

    }

}

static void dma_aio_cancel(BlockDriverAIOCB *acb)

{

    DMAAIOCB *dbs = container_of(acb, DMAAIOCB, common);



    if (dbs->acb) {

        bdrv_aio_cancel(dbs->acb);

    }

}

static void scsi_destroy(SCSIDevice *d)

{

    SCSIGenericState *s = DO_UPCAST(SCSIGenericState, qdev, d);

    SCSIGenericReq *r;



    while (!QTAILQ_EMPTY(&s->qdev.requests)) {

        r = DO_UPCAST(SCSIGenericReq, req, QTAILQ_FIRST(&s->qdev.requests));

        scsi_remove_request(r);

    }

    blockdev_mark_auto_del(s->qdev.conf.dinfo->bdrv);

}

static void scsi_write_do_fua(SCSIDiskReq *r)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);



    if (r->req.io_canceled) {

        scsi_req_cancel_complete(&r->req);

        goto done;

    }



    if (scsi_is_cmd_fua(&r->req.cmd)) {

        block_acct_start(bdrv_get_stats(s->qdev.conf.bs), &r->acct, 0,

                         BLOCK_ACCT_FLUSH);

        r->req.aiocb = bdrv_aio_flush(s->qdev.conf.bs, scsi_aio_complete, r);

        return;

    }



    scsi_req_complete(&r->req, GOOD);



done:

    scsi_req_unref(&r->req);

}

