int ff_pnm_decode_header(AVCodecContext *avctx, PNMContext * const s)

{

    char buf1[32], tuple_type[32];

    int h, w, depth, maxval;



    pnm_get(s, buf1, sizeof(buf1));

    s->type= buf1[1]-'0';

    if(buf1[0] != 'P')

        return -1;



    if (s->type==1 || s->type==4) {

        avctx->pix_fmt = PIX_FMT_MONOWHITE;

    } else if (s->type==2 || s->type==5) {

        if (avctx->codec_id == CODEC_ID_PGMYUV)

            avctx->pix_fmt = PIX_FMT_YUV420P;

        else

            avctx->pix_fmt = PIX_FMT_GRAY8;

    } else if (s->type==3 || s->type==6) {

        avctx->pix_fmt = PIX_FMT_RGB24;

    } else if (s->type==7) {

        w      = -1;

        h      = -1;

        maxval = -1;

        depth  = -1;

        tuple_type[0] = '\0';

        for (;;) {

            pnm_get(s, buf1, sizeof(buf1));

            if (!strcmp(buf1, "WIDTH")) {

                pnm_get(s, buf1, sizeof(buf1));

                w = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "HEIGHT")) {

                pnm_get(s, buf1, sizeof(buf1));

                h = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "DEPTH")) {

                pnm_get(s, buf1, sizeof(buf1));

                depth = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "MAXVAL")) {

                pnm_get(s, buf1, sizeof(buf1));

                maxval = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "TUPLTYPE") ||

            // FFmpeg used to write invalid files

                       !strcmp(buf1, "TUPLETYPE")) {

                pnm_get(s, tuple_type, sizeof(tuple_type));

            } else if (!strcmp(buf1, "ENDHDR")) {

                break;

            } else {

                return -1;

            }

        }

        /* check that all tags are present */

        if (w <= 0 || h <= 0 || maxval <= 0 || depth <= 0 || tuple_type[0] == '\0' || av_image_check_size(w, h, 0, avctx))

            return -1;



        avctx->width  = w;

        avctx->height = h;


        if (depth == 1) {

            if (maxval == 1)

                avctx->pix_fmt = PIX_FMT_MONOWHITE;

            else

                avctx->pix_fmt = PIX_FMT_GRAY8;

        } else if (depth == 3) {

            if (maxval < 256) {

            avctx->pix_fmt = PIX_FMT_RGB24;

            } else {

                av_log(avctx, AV_LOG_ERROR, "16-bit components are only supported for grayscale\n");

                avctx->pix_fmt = PIX_FMT_NONE;

                return -1;

            }

        } else if (depth == 4) {

            avctx->pix_fmt = PIX_FMT_RGB32;

        } else {

            return -1;

        }

        return 0;

    } else {

        return -1;

    }

    pnm_get(s, buf1, sizeof(buf1));

    avctx->width = atoi(buf1);

    if (avctx->width <= 0)

        return -1;

    pnm_get(s, buf1, sizeof(buf1));

    avctx->height = atoi(buf1);

    if(avctx->height <= 0 || av_image_check_size(avctx->width, avctx->height, 0, avctx))

        return -1;

    if (avctx->pix_fmt != PIX_FMT_MONOWHITE) {

        pnm_get(s, buf1, sizeof(buf1));

        s->maxval = atoi(buf1);

        if (s->maxval <= 0) {

            av_log(avctx, AV_LOG_ERROR, "Invalid maxval: %d\n", s->maxval);

            s->maxval = 255;

        }

        if (s->maxval >= 256) {

            if (avctx->pix_fmt == PIX_FMT_GRAY8) {

                avctx->pix_fmt = PIX_FMT_GRAY16BE;

                if (s->maxval != 65535)

                    avctx->pix_fmt = PIX_FMT_GRAY16;

            } else if (avctx->pix_fmt == PIX_FMT_RGB24) {

                if (s->maxval > 255)

                    avctx->pix_fmt = PIX_FMT_RGB48BE;

            } else {

                av_log(avctx, AV_LOG_ERROR, "Unsupported pixel format\n");

                avctx->pix_fmt = PIX_FMT_NONE;

                return -1;

            }

        }

    }else

        s->maxval=1;

    /* more check if YUV420 */

    if (avctx->pix_fmt == PIX_FMT_YUV420P) {

        if ((avctx->width & 1) != 0)

            return -1;

        h = (avctx->height * 2);

        if ((h % 3) != 0)

            return -1;

        h /= 3;

        avctx->height = h;

    }

    return 0;

}

int av_image_fill_pointers(uint8_t *data[4], enum PixelFormat pix_fmt, int height,

                           uint8_t *ptr, const int linesizes[4])

{

    int i, total_size, size[4], has_plane[4];



    const AVPixFmtDescriptor *desc = &av_pix_fmt_descriptors[pix_fmt];

    memset(data     , 0, sizeof(data[0])*4);

    memset(size     , 0, sizeof(size));

    memset(has_plane, 0, sizeof(has_plane));



    if ((unsigned)pix_fmt >= PIX_FMT_NB || desc->flags & PIX_FMT_HWACCEL)

        return AVERROR(EINVAL);



    data[0] = ptr;

    if (linesizes[0] > (INT_MAX - 1024) / height)

        return AVERROR(EINVAL);

    size[0] = linesizes[0] * height;



    if (desc->flags & PIX_FMT_PAL) {

        size[0] = (size[0] + 3) & ~3;

        data[1] = ptr + size[0]; /* palette is stored here as 256 32 bits words */

        return size[0] + 256 * 4;

    }



    for (i = 0; i < 4; i++)

        has_plane[desc->comp[i].plane] = 1;



    total_size = size[0];

    for (i = 1; i < 4 && has_plane[i]; i++) {

        int h, s = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

        data[i] = data[i-1] + size[i-1];

        h = (height + (1 << s) - 1) >> s;

        if (linesizes[i] > INT_MAX / h)

            return AVERROR(EINVAL);

        size[i] = h * linesizes[i];

        if (total_size > INT_MAX - size[i])

            return AVERROR(EINVAL);

        total_size += size[i];

    }



    return total_size;

}

int ff_pnm_decode_header(AVCodecContext *avctx, PNMContext * const s)

{

    char buf1[32], tuple_type[32];

    int h, w, depth, maxval;



    pnm_get(s, buf1, sizeof(buf1));

    s->type= buf1[1]-'0';

    if(buf1[0] != 'P')

        return AVERROR_INVALIDDATA;



    if (s->type==1 || s->type==4) {

        avctx->pix_fmt = AV_PIX_FMT_MONOWHITE;

    } else if (s->type==2 || s->type==5) {

        if (avctx->codec_id == AV_CODEC_ID_PGMYUV)

            avctx->pix_fmt = AV_PIX_FMT_YUV420P;

        else

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

    } else if (s->type==3 || s->type==6) {

        avctx->pix_fmt = AV_PIX_FMT_RGB24;

    } else if (s->type==7) {

        w      = -1;

        h      = -1;

        maxval = -1;

        depth  = -1;

        tuple_type[0] = '\0';

        for (;;) {

            pnm_get(s, buf1, sizeof(buf1));

            if (!strcmp(buf1, "WIDTH")) {

                pnm_get(s, buf1, sizeof(buf1));

                w = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "HEIGHT")) {

                pnm_get(s, buf1, sizeof(buf1));

                h = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "DEPTH")) {

                pnm_get(s, buf1, sizeof(buf1));

                depth = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "MAXVAL")) {

                pnm_get(s, buf1, sizeof(buf1));

                maxval = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "TUPLTYPE") ||

                       /* libavcodec used to write invalid files */

                       !strcmp(buf1, "TUPLETYPE")) {

                pnm_get(s, tuple_type, sizeof(tuple_type));

            } else if (!strcmp(buf1, "ENDHDR")) {

                break;

            } else {

                return AVERROR_INVALIDDATA;

            }

        }

        /* check that all tags are present */

        if (w <= 0 || h <= 0 || maxval <= 0 || depth <= 0 || tuple_type[0] == '\0' || av_image_check_size(w, h, 0, avctx) || s->bytestream >= s->bytestream_end)

            return AVERROR_INVALIDDATA;



        avctx->width  = w;

        avctx->height = h;

        s->maxval     = maxval;

        if (depth == 1) {

            if (maxval == 1) {

                avctx->pix_fmt = AV_PIX_FMT_MONOBLACK;

            } else if (maxval < 256) {

                avctx->pix_fmt = AV_PIX_FMT_GRAY8;

            } else {

                avctx->pix_fmt = AV_PIX_FMT_GRAY16;

            }

        } else if (depth == 2) {

            if (maxval == 255)

                avctx->pix_fmt = AV_PIX_FMT_GRAY8A;

        } else if (depth == 3) {

            if (maxval < 256) {

                avctx->pix_fmt = AV_PIX_FMT_RGB24;

            } else {

                avctx->pix_fmt = AV_PIX_FMT_RGB48;

            }

        } else if (depth == 4) {

            if (maxval < 256) {

                avctx->pix_fmt = AV_PIX_FMT_RGBA;

            } else {

                avctx->pix_fmt = AV_PIX_FMT_RGBA64;

            }

        } else {

            return AVERROR_INVALIDDATA;

        }

        return 0;

    } else {

        return AVERROR_INVALIDDATA;

    }

    pnm_get(s, buf1, sizeof(buf1));

    w = atoi(buf1);

    pnm_get(s, buf1, sizeof(buf1));

    h = atoi(buf1);

    if(w <= 0 || h <= 0 || av_image_check_size(w, h, 0, avctx) || s->bytestream >= s->bytestream_end)

        return AVERROR_INVALIDDATA;



    avctx->width  = w;

    avctx->height = h;



    if (avctx->pix_fmt != AV_PIX_FMT_MONOWHITE && avctx->pix_fmt != AV_PIX_FMT_MONOBLACK) {

        pnm_get(s, buf1, sizeof(buf1));

        s->maxval = atoi(buf1);

        if (s->maxval <= 0) {

            av_log(avctx, AV_LOG_ERROR, "Invalid maxval: %d\n", s->maxval);

            s->maxval = 255;

        }

        if (s->maxval >= 256) {

            if (avctx->pix_fmt == AV_PIX_FMT_GRAY8) {

                avctx->pix_fmt = AV_PIX_FMT_GRAY16;

            } else if (avctx->pix_fmt == AV_PIX_FMT_RGB24) {

                avctx->pix_fmt = AV_PIX_FMT_RGB48;

            } else if (avctx->pix_fmt == AV_PIX_FMT_YUV420P && s->maxval < 65536) {

                if (s->maxval < 512)

                    avctx->pix_fmt = AV_PIX_FMT_YUV420P9;

                else if (s->maxval < 1024)

                    avctx->pix_fmt = AV_PIX_FMT_YUV420P10;

                else

                    avctx->pix_fmt = AV_PIX_FMT_YUV420P16;

            } else {

                av_log(avctx, AV_LOG_ERROR, "Unsupported pixel format\n");

                avctx->pix_fmt = AV_PIX_FMT_NONE;

                return AVERROR_INVALIDDATA;

            }

        }

    }else

        s->maxval=1;

    /* more check if YUV420 */

    if (av_pix_fmt_desc_get(avctx->pix_fmt)->flags & AV_PIX_FMT_FLAG_PLANAR) {

        if ((avctx->width & 1) != 0)

            return AVERROR_INVALIDDATA;

        h = (avctx->height * 2);

        if ((h % 3) != 0)

            return AVERROR_INVALIDDATA;

        h /= 3;

        avctx->height = h;

    }

    return 0;

}

static int slirp_hostfwd(SlirpState *s, const char *redir_str,

                         int legacy_format, Error **errp)

{

    struct in_addr host_addr = { .s_addr = INADDR_ANY };

    struct in_addr guest_addr = { .s_addr = 0 };

    int host_port, guest_port;

    const char *p;

    char buf[256];

    int is_udp;

    char *end;



    p = redir_str;

    if (!p || get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

        goto fail_syntax;

    }

    if (!strcmp(buf, "tcp") || buf[0] == '\0') {

        is_udp = 0;

    } else if (!strcmp(buf, "udp")) {

        is_udp = 1;

    } else {

        goto fail_syntax;

    }



    if (!legacy_format) {

        if (get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

            goto fail_syntax;

        }

        if (buf[0] != '\0' && !inet_aton(buf, &host_addr)) {

            goto fail_syntax;

        }

    }



    if (get_str_sep(buf, sizeof(buf), &p, legacy_format ? ':' : '-') < 0) {

        goto fail_syntax;

    }

    host_port = strtol(buf, &end, 0);

    if (*end != '\0' || host_port < 0 || host_port > 65535) {

        goto fail_syntax;

    }



    if (get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

        goto fail_syntax;

    }

    if (buf[0] != '\0' && !inet_aton(buf, &guest_addr)) {

        goto fail_syntax;

    }



    guest_port = strtol(p, &end, 0);

    if (*end != '\0' || guest_port < 1 || guest_port > 65535) {

        goto fail_syntax;

    }



    if (slirp_add_hostfwd(s->slirp, is_udp, host_addr, host_port, guest_addr,

                          guest_port) < 0) {

        error_setg(errp, "Could not set up host forwarding rule '%s'",

                   redir_str);

        return -1;

    }

    return 0;



 fail_syntax:

    error_setg(errp, "Invalid host forwarding rule '%s'", redir_str);

    return -1;

}

