}

static int dvvideo_init(AVCodecContext *avctx)

{

    DVVideoContext *s = avctx->priv_data;

    DSPContext dsp;

    static int done=0;

    int i, j;



    if (!done) {

        VLC dv_vlc;

        uint16_t new_dv_vlc_bits[NB_DV_VLC*2];

        uint8_t new_dv_vlc_len[NB_DV_VLC*2];

        uint8_t new_dv_vlc_run[NB_DV_VLC*2];

        int16_t new_dv_vlc_level[NB_DV_VLC*2];



        done = 1;



        dv_vlc_map = av_mallocz(DV_VLC_MAP_LEV_SIZE*DV_VLC_MAP_RUN_SIZE*sizeof(struct dv_vlc_pair));

	if (!dv_vlc_map)

	    return -ENOMEM;



	/* dv_anchor lets each thread know its Id */

	dv_anchor = av_malloc(12*27*sizeof(void*));

	if (!dv_anchor) {

	    av_free(dv_vlc_map);

	    return -ENOMEM;

	}

	for (i=0; i<12*27; i++)

	    dv_anchor[i] = (void*)(size_t)i;



	/* it's faster to include sign bit in a generic VLC parsing scheme */

	for (i=0, j=0; i<NB_DV_VLC; i++, j++) {

	    new_dv_vlc_bits[j] = dv_vlc_bits[i];

	    new_dv_vlc_len[j] = dv_vlc_len[i];

	    new_dv_vlc_run[j] = dv_vlc_run[i];

	    new_dv_vlc_level[j] = dv_vlc_level[i];



	    if (dv_vlc_level[i]) {

	        new_dv_vlc_bits[j] <<= 1;

		new_dv_vlc_len[j]++;



		j++;

		new_dv_vlc_bits[j] = (dv_vlc_bits[i] << 1) | 1;

		new_dv_vlc_len[j] = dv_vlc_len[i] + 1;

		new_dv_vlc_run[j] = dv_vlc_run[i];

		new_dv_vlc_level[j] = -dv_vlc_level[i];

	    }

	}



        /* NOTE: as a trick, we use the fact the no codes are unused

           to accelerate the parsing of partial codes */

        init_vlc(&dv_vlc, TEX_VLC_BITS, j, 

                 new_dv_vlc_len, 1, 1, new_dv_vlc_bits, 2, 2);



        dv_rl_vlc = av_malloc(dv_vlc.table_size * sizeof(RL_VLC_ELEM));

	if (!dv_rl_vlc) {

	    av_free(dv_anchor);

	    av_free(dv_vlc_map);

	    return -ENOMEM;

	}

        for(i = 0; i < dv_vlc.table_size; i++){

            int code= dv_vlc.table[i][0];

            int len = dv_vlc.table[i][1];

            int level, run;



            if(len<0){ //more bits needed

                run= 0;

                level= code;

            } else {

                run=   new_dv_vlc_run[code] + 1;

                level= new_dv_vlc_level[code];

            }

            dv_rl_vlc[i].len = len;

            dv_rl_vlc[i].level = level;

            dv_rl_vlc[i].run = run;

        }

	free_vlc(&dv_vlc);



	for (i = 0; i < NB_DV_VLC - 1; i++) {

           if (dv_vlc_run[i] >= DV_VLC_MAP_RUN_SIZE || dv_vlc_level[i] >= DV_VLC_MAP_LEV_SIZE)

	       continue;



	   if (dv_vlc_map[dv_vlc_run[i]][dv_vlc_level[i]].size != 0)

	       continue;



	   dv_vlc_map[dv_vlc_run[i]][dv_vlc_level[i]].vlc = dv_vlc_bits[i] << 

	                                                    (!!dv_vlc_level[i]);

	   dv_vlc_map[dv_vlc_run[i]][dv_vlc_level[i]].size = dv_vlc_len[i] + 

	                                                     (!!dv_vlc_level[i]);

	}

	for (i = 0; i < DV_VLC_MAP_RUN_SIZE; i++) {

#ifdef DV_CODEC_TINY_TARGET

	   for (j = 1; j < DV_VLC_MAP_LEV_SIZE; j++) {

	      if (dv_vlc_map[i][j].size == 0) {

	          dv_vlc_map[i][j].vlc = dv_vlc_map[0][j].vlc |

		            (dv_vlc_map[i-1][0].vlc << (dv_vlc_map[0][j].size));

	          dv_vlc_map[i][j].size = dv_vlc_map[i-1][0].size + 

		                          dv_vlc_map[0][j].size;

	      }

	   }

#else

	   for (j = 1; j < DV_VLC_MAP_LEV_SIZE/2; j++) {

	      if (dv_vlc_map[i][j].size == 0) {

	          dv_vlc_map[i][j].vlc = dv_vlc_map[0][j].vlc |

		            (dv_vlc_map[i-1][0].vlc << (dv_vlc_map[0][j].size));

	          dv_vlc_map[i][j].size = dv_vlc_map[i-1][0].size + 

		                          dv_vlc_map[0][j].size;

	      }

	      dv_vlc_map[i][((uint16_t)(-j))&0x1ff].vlc = 

	                                    dv_vlc_map[i][j].vlc | 1;

	      dv_vlc_map[i][((uint16_t)(-j))&0x1ff].size = 

	                                    dv_vlc_map[i][j].size;

	   }

#endif

	}

    }



    /* Generic DSP setup */

    dsputil_init(&dsp, avctx);

    s->get_pixels = dsp.get_pixels;



    /* 88DCT setup */

    s->fdct[0] = dsp.fdct;

    s->idct_put[0] = dsp.idct_put;

    for (i=0; i<64; i++)

       s->dv_zigzag[0][i] = dsp.idct_permutation[ff_zigzag_direct[i]];



    /* 248DCT setup */

    s->fdct[1] = dsp.fdct248;

    s->idct_put[1] = simple_idct248_put;  // FIXME: need to add it to DSP

    memcpy(s->dv_zigzag[1], ff_zigzag248_direct, 64);



    /* XXX: do it only for constant case */

    dv_build_unquantize_tables(s, dsp.idct_permutation);



    /* FIXME: I really don't think this should be here */

    if (dv_codec_profile(avctx))

	avctx->pix_fmt = dv_codec_profile(avctx)->pix_fmt; 

    avctx->coded_frame = &s->picture;



    return 0;

}

static int build_vlc(AVCodecContext *avctx, VLC *vlc, const uint32_t *table)

{

    Node nodes[512];

    uint32_t bits[256];

    int16_t lens[256];

    uint8_t xlat[256];

    int cur_node, i, j, pos = 0;



    ff_free_vlc(vlc);



    for (i = 0; i < 256; i++) {

        nodes[i].count = table[i];

        nodes[i].sym   = i;

        nodes[i].n0    = -2;

        nodes[i].l     = i;

        nodes[i].r     = i;

    }



    cur_node = 256;

    j = 0;

    do {

        for (i = 0; ; i++) {

            int new_node = j;

            int first_node = cur_node;

            int second_node = cur_node;

            int nd, st;



            nodes[cur_node].count = -1;



            do {

                int val = nodes[new_node].count;

                if (val && (val < nodes[first_node].count)) {

                    if (val >= nodes[second_node].count) {

                        first_node = new_node;

                    } else {

                        first_node = second_node;

                        second_node = new_node;

                    }

                }

                new_node += 1;

            } while (new_node != cur_node);



            if (first_node == cur_node)

                break;



            nd = nodes[second_node].count;

            st = nodes[first_node].count;

            nodes[second_node].count = 0;

            nodes[first_node].count  = 0;

            nodes[cur_node].count = nd + st;

            nodes[cur_node].sym = -1;

            nodes[cur_node].n0 = cur_node;

            nodes[cur_node].l = first_node;

            nodes[cur_node].r = second_node;

            cur_node++;

        }

        j++;

    } while (cur_node - 256 == j);



    get_tree_codes(bits, lens, xlat, nodes, cur_node - 1, 0, 0, &pos);



    return ff_init_vlc_sparse(vlc, 10, pos, lens, 2, 2, bits, 4, 4, xlat, 1, 1, 0);

}

static int sap_read_header(AVFormatContext *s)

{

    struct SAPState *sap = s->priv_data;

    char host[1024], path[1024], url[1024];

    uint8_t recvbuf[RTP_MAX_PACKET_LENGTH];

    int port;

    int ret, i;

    AVInputFormat* infmt;



    if (!ff_network_init())

        return AVERROR(EIO);



    av_url_split(NULL, 0, NULL, 0, host, sizeof(host), &port,

                 path, sizeof(path), s->filename);

    if (port < 0)

        port = 9875;



    if (!host[0]) {

        /* Listen for announcements on sap.mcast.net if no host was specified */

        av_strlcpy(host, "224.2.127.254", sizeof(host));

    }



    ff_url_join(url, sizeof(url), "udp", NULL, host, port, "?localport=%d",

                port);

    ret = ffurl_open(&sap->ann_fd, url, AVIO_FLAG_READ,

                     &s->interrupt_callback, NULL);

    if (ret)

        goto fail;



    while (1) {

        int addr_type, auth_len;

        int pos;



        ret = ffurl_read(sap->ann_fd, recvbuf, sizeof(recvbuf) - 1);

        if (ret == AVERROR(EAGAIN))

            continue;

        if (ret < 0)

            goto fail;

        recvbuf[ret] = '\0'; /* Null terminate for easier parsing */

        if (ret < 8) {

            av_log(s, AV_LOG_WARNING, "Received too short packet\n");

            continue;

        }



        if ((recvbuf[0] & 0xe0) != 0x20) {

            av_log(s, AV_LOG_WARNING, "Unsupported SAP version packet "

                                      "received\n");

            continue;

        }



        if (recvbuf[0] & 0x04) {

            av_log(s, AV_LOG_WARNING, "Received stream deletion "

                                      "announcement\n");

            continue;

        }

        addr_type = recvbuf[0] & 0x10;

        auth_len  = recvbuf[1];

        sap->hash = AV_RB16(&recvbuf[2]);

        pos = 4;

        if (addr_type)

            pos += 16; /* IPv6 */

        else

            pos += 4; /* IPv4 */

        pos += auth_len * 4;

        if (pos + 4 >= ret) {

            av_log(s, AV_LOG_WARNING, "Received too short packet\n");

            continue;

        }

#define MIME "application/sdp"

        if (strcmp(&recvbuf[pos], MIME) == 0) {

            pos += strlen(MIME) + 1;

        } else if (strncmp(&recvbuf[pos], "v=0\r\n", 5) == 0) {

            // Direct SDP without a mime type

        } else {

            av_log(s, AV_LOG_WARNING, "Unsupported mime type %s\n",

                                      &recvbuf[pos]);

            continue;

        }



        sap->sdp = av_strdup(&recvbuf[pos]);

        break;

    }



    av_log(s, AV_LOG_VERBOSE, "SDP:\n%s\n", sap->sdp);

    ffio_init_context(&sap->sdp_pb, sap->sdp, strlen(sap->sdp), 0, NULL, NULL,

                  NULL, NULL);



    infmt = av_find_input_format("sdp");

    if (!infmt)

        goto fail;

    sap->sdp_ctx = avformat_alloc_context();

    if (!sap->sdp_ctx) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }

    sap->sdp_ctx->max_delay = s->max_delay;

    sap->sdp_ctx->pb        = &sap->sdp_pb;

    sap->sdp_ctx->interrupt_callback = s->interrupt_callback;



    av_assert0(!sap->sdp_ctx->codec_whitelist && !sap->sdp_ctx->format_whitelist);

    sap->sdp_ctx-> codec_whitelist = av_strdup(s->codec_whitelist);

    sap->sdp_ctx->format_whitelist = av_strdup(s->format_whitelist);



    ret = avformat_open_input(&sap->sdp_ctx, "temp.sdp", infmt, NULL);

    if (ret < 0)

        goto fail;

    if (sap->sdp_ctx->ctx_flags & AVFMTCTX_NOHEADER)

        s->ctx_flags |= AVFMTCTX_NOHEADER;

    for (i = 0; i < sap->sdp_ctx->nb_streams; i++) {

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        st->id = i;

        avcodec_copy_context(st->codec, sap->sdp_ctx->streams[i]->codec);

        st->time_base = sap->sdp_ctx->streams[i]->time_base;

    }



    return 0;



fail:

    sap_read_close(s);

    return ret;

}

static int pcm_read_header(AVFormatContext *s)

{

    PCMAudioDemuxerContext *s1 = s->priv_data;

    AVStream *st;

    uint8_t *mime_type = NULL;



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);





    st->codecpar->codec_type  = AVMEDIA_TYPE_AUDIO;

    st->codecpar->codec_id    = s->iformat->raw_codec_id;

    st->codecpar->sample_rate = s1->sample_rate;

    st->codecpar->channels    = s1->channels;



    av_opt_get(s->pb, "mime_type", AV_OPT_SEARCH_CHILDREN, &mime_type);

    if (mime_type && s->iformat->mime_type) {

        int rate = 0, channels = 0;

        size_t len = strlen(s->iformat->mime_type);

        if (!strncmp(s->iformat->mime_type, mime_type, len)) {

            uint8_t *options = mime_type + len;

            len = strlen(mime_type);

            while (options < mime_type + len) {

                options = strstr(options, ";");

                if (!options++)

                    break;

                if (!rate)

                    sscanf(options, " rate=%d",     &rate);

                if (!channels)

                    sscanf(options, " channels=%d", &channels);

            }

            if (rate <= 0) {

                av_log(s, AV_LOG_ERROR,

                       "Invalid sample_rate found in mime_type \"%s\"\n",

                       mime_type);


                return AVERROR_INVALIDDATA;

            }

            st->codecpar->sample_rate = rate;

            if (channels > 0)

                st->codecpar->channels = channels;

        }

    }




    st->codecpar->bits_per_coded_sample =

        av_get_bits_per_sample(st->codecpar->codec_id);



    av_assert0(st->codecpar->bits_per_coded_sample > 0);



    st->codecpar->block_align =

        st->codecpar->bits_per_coded_sample * st->codecpar->channels / 8;



    avpriv_set_pts_info(st, 64, 1, st->codecpar->sample_rate);

    return 0;

}

static int hls_mux_init(AVFormatContext *s)

{

    HLSContext *hls = s->priv_data;

    AVFormatContext *oc;

    AVFormatContext *vtt_oc;

    int i, ret;



    ret = avformat_alloc_output_context2(&hls->avf, hls->oformat, NULL, NULL);

    if (ret < 0)

        return ret;

    oc = hls->avf;



    oc->oformat            = hls->oformat;

    oc->interrupt_callback = s->interrupt_callback;

    oc->max_delay          = s->max_delay;

    av_dict_copy(&oc->metadata, s->metadata, 0);



    if(hls->vtt_oformat) {

        ret = avformat_alloc_output_context2(&hls->vtt_avf, hls->vtt_oformat, NULL, NULL);

        if (ret < 0)

            return ret;

        vtt_oc          = hls->vtt_avf;

        vtt_oc->oformat = hls->vtt_oformat;

        av_dict_copy(&vtt_oc->metadata, s->metadata, 0);

    }



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st;

        AVFormatContext *loc;

        if (s->streams[i]->codec->codec_type == AVMEDIA_TYPE_SUBTITLE)

            loc = vtt_oc;

        else

            loc = oc;



        if (!(st = avformat_new_stream(loc, NULL)))

            return AVERROR(ENOMEM);

        avcodec_copy_context(st->codec, s->streams[i]->codec);

        st->sample_aspect_ratio = s->streams[i]->sample_aspect_ratio;

        st->time_base = s->streams[i]->time_base;

    }

    hls->start_pos = 0;



    return 0;

}

static int ism_write_header(AVFormatContext *s)

{

    SmoothStreamingContext *c = s->priv_data;

    int ret = 0, i;

    AVOutputFormat *oformat;



    mkdir(s->filename, 0777);



    oformat = av_guess_format("ismv", NULL, NULL);

    if (!oformat) {

        ret = AVERROR_MUXER_NOT_FOUND;

        goto fail;

    }



    c->streams = av_mallocz(sizeof(*c->streams) * s->nb_streams);

    if (!c->streams) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    for (i = 0; i < s->nb_streams; i++) {

        OutputStream *os = &c->streams[i];

        AVFormatContext *ctx;

        AVStream *st;

        AVDictionary *opts = NULL;

        char buf[10];



        if (!s->streams[i]->codec->bit_rate) {

            av_log(s, AV_LOG_ERROR, "No bit rate set for stream %d\n", i);

            ret = AVERROR(EINVAL);

            goto fail;

        }

        snprintf(os->dirname, sizeof(os->dirname), "%s/QualityLevels(%d)", s->filename, s->streams[i]->codec->bit_rate);

        mkdir(os->dirname, 0777);



        ctx = avformat_alloc_context();

        if (!ctx) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        os->ctx = ctx;

        ctx->oformat = oformat;

        ctx->interrupt_callback = s->interrupt_callback;



        if (!(st = avformat_new_stream(ctx, NULL))) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        avcodec_copy_context(st->codec, s->streams[i]->codec);

        st->sample_aspect_ratio = s->streams[i]->sample_aspect_ratio;



        ctx->pb = avio_alloc_context(os->iobuf, sizeof(os->iobuf), AVIO_FLAG_WRITE, os, NULL, ism_write, ism_seek);

        if (!ctx->pb) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        snprintf(buf, sizeof(buf), "%d", c->lookahead_count);

        av_dict_set(&opts, "ism_lookahead", buf, 0);

        av_dict_set(&opts, "movflags", "frag_custom", 0);

        if ((ret = avformat_write_header(ctx, &opts)) < 0) {

             goto fail;

        }

        os->ctx_inited = 1;

        avio_flush(ctx->pb);

        av_dict_free(&opts);

        s->streams[i]->time_base = st->time_base;

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            c->has_video = 1;

            os->stream_type_tag = "video";

            if (st->codec->codec_id == AV_CODEC_ID_H264) {

                os->fourcc = "H264";

            } else if (st->codec->codec_id == AV_CODEC_ID_VC1) {

                os->fourcc = "WVC1";

            } else {

                av_log(s, AV_LOG_ERROR, "Unsupported video codec\n");

                ret = AVERROR(EINVAL);

                goto fail;

            }

        } else {

            c->has_audio = 1;

            os->stream_type_tag = "audio";

            if (st->codec->codec_id == AV_CODEC_ID_AAC) {

                os->fourcc = "AACL";

                os->audio_tag = 0xff;

            } else if (st->codec->codec_id == AV_CODEC_ID_WMAPRO) {

                os->fourcc = "WMAP";

                os->audio_tag = 0x0162;

            } else {

                av_log(s, AV_LOG_ERROR, "Unsupported audio codec\n");

                ret = AVERROR(EINVAL);

                goto fail;

            }

            os->packet_size = st->codec->block_align ? st->codec->block_align : 4;

        }

        get_private_data(os);

    }



    if (!c->has_video && c->min_frag_duration <= 0) {

        av_log(s, AV_LOG_WARNING, "no video stream and no min frag duration set\n");

        ret = AVERROR(EINVAL);

    }

    ret = write_manifest(s, 0);



fail:

    if (ret)

        ism_free(s);

    return ret;

}

