void qemu_send_packet(VLANClientState *vc, const uint8_t *buf, int size)

{

    VLANState *vlan = vc->vlan;

    VLANPacket *packet;



    if (vc->link_down)

        return;



#ifdef DEBUG_NET

    printf("vlan %d send:\n", vlan->id);

    hex_dump(stdout, buf, size);

#endif

    if (vlan->delivering) {

        packet = qemu_malloc(sizeof(VLANPacket) + size);

        packet->next = vlan->send_queue;

        packet->sender = vc;

        packet->size = size;

        memcpy(packet->data, buf, size);

        vlan->send_queue = packet;

    } else {

        vlan->delivering = 1;

        qemu_deliver_packet(vc, buf, size);

        while ((packet = vlan->send_queue) != NULL) {

            qemu_deliver_packet(packet->sender, packet->data, packet->size);

            vlan->send_queue = packet->next;

            qemu_free(packet);

        }

        vlan->delivering = 0;

    }

}

bool qemu_net_queue_flush(NetQueue *queue)

{

    while (!QTAILQ_EMPTY(&queue->packets)) {

        NetPacket *packet;

        int ret;



        packet = QTAILQ_FIRST(&queue->packets);

        QTAILQ_REMOVE(&queue->packets, packet, entry);




        ret = qemu_net_queue_deliver(queue,

                                     packet->sender,

                                     packet->flags,

                                     packet->data,

                                     packet->size);

        if (ret == 0) {

            queue->nq_count++;

            QTAILQ_INSERT_HEAD(&queue->packets, packet, entry);

            return false;

        }



        if (packet->sent_cb) {

            packet->sent_cb(packet->sender, ret);

        }



        g_free(packet);

    }

    return true;

}

void qemu_purge_queued_packets(VLANClientState *vc)

{

    VLANPacket *packet, *next;



    TAILQ_FOREACH_SAFE(packet, &vc->vlan->send_queue, entry, next) {

        if (packet->sender == vc) {

            TAILQ_REMOVE(&vc->vlan->send_queue, packet, entry);

            qemu_free(packet);

        }

    }

}

void qemu_unregister_reset(QEMUResetHandler *func, void *opaque)

{

    QEMUResetEntry *re;



    TAILQ_FOREACH(re, &reset_handlers, entry) {

        if (re->func == func && re->opaque == opaque) {

            TAILQ_REMOVE(&reset_handlers, re, entry);

            qemu_free(re);

            return;

        }

    }

}

