static int advanced_decode_picture_secondary_header(VC9Context *v)

{

    GetBitContext *gb = &v->s.gb;

    int index, status = 0;



    switch(v->s.pict_type)

    {

    case P_TYPE: status = decode_p_picture_secondary_header(v); break;

    case B_TYPE: status = decode_b_picture_secondary_header(v); break;

    case BI_TYPE:

    case I_TYPE: status = decode_i_picture_secondary_header(v); break; 

    }

    if (status<0) return FRAME_SKIPED;



    /* AC Syntax */

    v->ac_table_level = decode012(gb);

    if (v->s.pict_type == I_TYPE || v->s.pict_type == BI_TYPE)

    {

        v->ac2_table_level = decode012(gb);

    }

    /* DC Syntax */

    index = decode012(gb);

    v->luma_dc_vlc = &ff_msmp4_dc_luma_vlc[index];

    v->chroma_dc_vlc = &ff_msmp4_dc_chroma_vlc[index];



    return 0;

}

static int usb_hub_handle_data(USBDevice *dev, USBPacket *p)

{

    USBHubState *s = (USBHubState *)dev;

    int ret;



    switch(p->pid) {

    case USB_TOKEN_IN:

        if (p->devep == 1) {

            USBHubPort *port;

            unsigned int status;

            int i, n;

            n = (NUM_PORTS + 1 + 7) / 8;

            if (p->len == 1) { /* FreeBSD workaround */

                n = 1;

            } else if (n > p->len) {

                return USB_RET_BABBLE;

            }

            status = 0;

            for(i = 0; i < NUM_PORTS; i++) {

                port = &s->ports[i];

                if (port->wPortChange)

                    status |= (1 << (i + 1));

            }

            if (status != 0) {

                for(i = 0; i < n; i++) {

                    p->data[i] = status >> (8 * i);

                }

                ret = n;

            } else {

                ret = USB_RET_NAK; /* usb11 11.13.1 */

            }

        } else {

            goto fail;

        }

        break;

    case USB_TOKEN_OUT:

    default:

    fail:

        ret = USB_RET_STALL;

        break;

    }

    return ret;

}

static int advanced_decode_picture_header(VC9Context *v)

{

    static const int type_table[4] = { P_TYPE, B_TYPE, I_TYPE, BI_TYPE };

    int type, i, ret;



    if (v->interlace)

    {

        v->fcm = get_bits(&v->gb, 1);

        if (v->fcm) v->fcm = 2+get_bits(&v->gb, 1);

    }



    type = get_prefix(&v->gb, 0, 4);

    if (type > 4 || type < 0) return FRAME_SKIPED;

    v->pict_type = type_table[type];

    av_log(v->avctx, AV_LOG_INFO, "AP Frame Type: %i\n", v->pict_type);



    if (v->tfcntrflag) v->tfcntr = get_bits(&v->gb, 8);

    if (v->broadcast)

    {

        if (!v->interlace) v->rptfrm = get_bits(&v->gb, 2);

        else

        {

            v->tff = get_bits(&v->gb, 1);

            v->rff = get_bits(&v->gb, 1);

        }

    }



    if (v->panscanflag)

    {

#if 0

        for (i=0; i<v->numpanscanwin; i++)

        {

            v->topleftx[i] = get_bits(&v->gb, 16);

            v->toplefty[i] = get_bits(&v->gb, 16);

            v->bottomrightx[i] = get_bits(&v->gb, 16);

            v->bottomrighty[i] = get_bits(&v->gb, 16);

        }

#else

        skip_bits(&v->gb, 16*4*v->numpanscanwin);

#endif

    }

    v->rndctrl = get_bits(&v->gb, 1);

    v->uvsamp = get_bits(&v->gb, 1);

    if (v->finterpflag == 1) v->interpfrm = get_bits(&v->gb, 1);



    switch(v->pict_type)

    {

    case I_TYPE: if (decode_i_picture_header(v) < 0) return -1;

    case P_TYPE: if (decode_p_picture_header(v) < 0) return -1;

    case BI_TYPE:

    case B_TYPE: if (decode_b_picture_header(v) < 0) return FRAME_SKIPED;

    default: break;

    }



    /* AC/DC Syntax */

    v->transacfrm = get_bits(&v->gb, 1);

    if (v->transacfrm) v->transacfrm += get_bits(&v->gb, 1);

    if (v->pict_type == I_TYPE || v->pict_type == BI_TYPE)

    {

        v->transacfrm2 = get_bits(&v->gb, 1);

        if (v->transacfrm2) v->transacfrm2 += get_bits(&v->gb, 1);

    }

    v->transacdctab = get_bits(&v->gb, 1);

    if (v->pict_type == I_TYPE) vop_dquant_decoding(v);



    return 0;

}

static int rv20_decode_picture_header(MpegEncContext *s)

{

    int seq, mb_pos, i;



    i= get_bits(&s->gb, 2);

    switch(i){

    case 0: s->pict_type= I_TYPE; break;

    case 1: s->pict_type= I_TYPE; break; //hmm ...

    case 2: s->pict_type= P_TYPE; break;

    case 3: s->pict_type= B_TYPE; break;

    default: 

        av_log(s->avctx, AV_LOG_ERROR, "unknown frame type\n");

        return -1;

    }



    if (get_bits(&s->gb, 1)){

        av_log(s->avctx, AV_LOG_ERROR, "unknown bit set\n");

        return -1;

    }



    s->qscale = get_bits(&s->gb, 5);

    if(s->qscale==0){

        av_log(s->avctx, AV_LOG_ERROR, "error, qscale:0\n");

        return -1;

    }



    if(s->avctx->sub_id == 0x20200002)

        seq= get_bits(&s->gb, 16);

    else

        seq= get_bits(&s->gb, 8);



    for(i=0; i<6; i++){

        if(s->mb_width*s->mb_height < ff_mba_max[i]) break;

    }

    mb_pos= get_bits(&s->gb, ff_mba_length[i]);

    s->mb_x= mb_pos % s->mb_width;

    s->mb_y= mb_pos / s->mb_width;

    s->no_rounding= get_bits1(&s->gb);



    s->f_code = 1;

    s->unrestricted_mv = 1;

    s->h263_aic= s->pict_type == I_TYPE;

//    s->alt_inter_vlc=1;

//    s->obmc=1;

//    s->umvplus=1;

//    s->modified_quant=1;



    if(s->avctx->debug & FF_DEBUG_PICT_INFO){

            av_log(s->avctx, AV_LOG_INFO, "num:%5d x:%2d y:%2d type:%d qscale:%2d rnd:%d\n", 

                   seq, s->mb_x, s->mb_y, s->pict_type, s->qscale, s->no_rounding);

    }



    if (s->pict_type == B_TYPE){

        av_log(s->avctx, AV_LOG_ERROR, "b frame not supported\n");

        return -1;

    }



    return s->mb_width*s->mb_height - mb_pos;

}

