    char *kernel_str;

    const char *buf = args;

    int ret;



    dilate->nb_iterations = 1;



    if (args)

        kernel_str = av_get_token(&buf, "|");

    if ((ret = parse_iplconvkernel(&dilate->kernel,

                                   *kernel_str ? kernel_str : default_kernel_str,

                                   ctx)) < 0)

