static int encode_frame(AVCodecContext *avctx, AVPacket *avpkt,
                        const AVFrame *frame, int *got_packet_ptr)
{
    DCAEncContext *c = avctx->priv_data;
    const int32_t *samples;
    int ret, i;
    if ((ret = ff_alloc_packet2(avctx, avpkt, c->frame_size , 0)) < 0)
        return ret;
    samples = (const int32_t *)frame->data[0];
    subband_transform(c, samples);
    if (c->lfe_channel)
        lfe_downsample(c, samples);
    calc_masking(c, samples);
    find_peaks(c);
    assign_bits(c);
    calc_scales(c);
    quantize_all(c);
    shift_history(c, samples);
    init_put_bits(&c->pb, avpkt->data, avpkt->size);
    put_frame_header(c);
    put_primary_audio_header(c);
    for (i = 0; i < SUBFRAMES; i++)
        put_subframe(c, i);
    flush_put_bits(&c->pb);
    avpkt->pts      = frame->pts;
    avpkt->duration = ff_samples_to_time_base(avctx, frame->nb_samples);
    avpkt->size     = c->frame_size + 1;
    *got_packet_ptr = 1;
    return 0;
}

static int amr_wb_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                               const AVFrame *frame, int *got_packet_ptr)

{

    AMRWBContext *s = avctx->priv_data;

    const int16_t *samples = (const int16_t *)frame->data[0];

    int size, ret;



    if ((ret = ff_alloc_packet2(avctx, avpkt, MAX_PACKET_SIZE)))

        return ret;



    if (s->last_bitrate != avctx->bit_rate) {

        s->mode         = get_wb_bitrate_mode(avctx->bit_rate, avctx);

        s->last_bitrate = avctx->bit_rate;

    }

    size = E_IF_encode(s->state, s->mode, samples, avpkt->data, s->allow_dtx);

    if (size <= 0 || size > MAX_PACKET_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "Error encoding frame\n");

        return AVERROR(EINVAL);

    }



    if (frame->pts != AV_NOPTS_VALUE)

        avpkt->pts = frame->pts - ff_samples_to_time_base(avctx, avctx->delay);



    avpkt->size = size;

    *got_packet_ptr = 1;

    return 0;

}

static int g726_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    G726Context *c = avctx->priv_data;

    const int16_t *samples = (const int16_t *)frame->data[0];

    PutBitContext pb;

    int i, ret, out_size;



    out_size = (frame->nb_samples * c->code_size + 7) / 8;

    if ((ret = ff_alloc_packet2(avctx, avpkt, out_size)))

        return ret;

    init_put_bits(&pb, avpkt->data, avpkt->size);



    for (i = 0; i < frame->nb_samples; i++)

        put_bits(&pb, c->code_size, g726_encode(c, *samples++));



    flush_put_bits(&pb);



    avpkt->size = out_size;

    *got_packet_ptr = 1;

    return 0;

}

static int alac_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    AlacEncodeContext *s = avctx->priv_data;

    int out_bytes, max_frame_size, ret;



    s->frame_size = frame->nb_samples;



    if (frame->nb_samples < DEFAULT_FRAME_SIZE)

        max_frame_size = get_max_frame_size(s->frame_size, avctx->channels,

                                            avctx->bits_per_raw_sample);

    else

        max_frame_size = s->max_coded_frame_size;



    if ((ret = ff_alloc_packet2(avctx, avpkt, 2 * max_frame_size)))

        return ret;



    /* use verbatim mode for compression_level 0 */

    if (s->compression_level) {

        s->verbatim   = 0;

        s->extra_bits = avctx->bits_per_raw_sample - 16;

    } else {

        s->verbatim   = 1;

        s->extra_bits = 0;

    }



    out_bytes = write_frame(s, avpkt, frame->extended_data);



    if (out_bytes > max_frame_size) {

        /* frame too large. use verbatim mode */

        s->verbatim = 1;

        s->extra_bits = 0;

        out_bytes = write_frame(s, avpkt, frame->extended_data);

    }



    avpkt->size = out_bytes;

    *got_packet_ptr = 1;

    return 0;

}

static int vcr1_decode_frame(AVCodecContext *avctx, void *data,
                             int *got_frame, AVPacket *avpkt)
{
    const uint8_t *buf        = avpkt->data;
    int buf_size              = avpkt->size;
    VCR1Context *const a      = avctx->priv_data;
    AVFrame *const p          = data;
    const uint8_t *bytestream = buf;
    int i, x, y, ret;
    if ((ret = ff_get_buffer(avctx, p, 0)) < 0) {
        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");
        return ret;
    }
    p->pict_type = AV_PICTURE_TYPE_I;
    p->key_frame = 1;
    if (buf_size < 32)
    for (i = 0; i < 16; i++) {
        a->delta[i] = *bytestream++;
        bytestream++;
        buf_size--;
    }
    for (y = 0; y < avctx->height; y++) {
        int offset;
        uint8_t *luma = &p->data[0][y * p->linesize[0]];
        if ((y & 3) == 0) {
            uint8_t *cb = &p->data[1][(y >> 2) * p->linesize[1]];
            uint8_t *cr = &p->data[2][(y >> 2) * p->linesize[2]];
            for (i = 0; i < 4; i++)
                a->offset[i] = *bytestream++;
            offset = a->offset[0] - a->delta[bytestream[2] & 0xF];
            for (x = 0; x < avctx->width; x += 4) {
                luma[0]     = offset += a->delta[bytestream[2] & 0xF];
                luma[1]     = offset += a->delta[bytestream[2] >>  4];
                luma[2]     = offset += a->delta[bytestream[0] & 0xF];
                luma[3]     = offset += a->delta[bytestream[0] >>  4];
                luma       += 4;
                *cb++       = bytestream[3];
                *cr++       = bytestream[1];
                bytestream += 4;
                buf_size   -= 4;
            }
        } else {
            if (buf_size < avctx->width / 2)
            offset = a->offset[y & 3] - a->delta[bytestream[2] & 0xF];
            for (x = 0; x < avctx->width; x += 8) {
                luma[0]     = offset += a->delta[bytestream[2] & 0xF];
                luma[1]     = offset += a->delta[bytestream[2] >>  4];
                luma[2]     = offset += a->delta[bytestream[3] & 0xF];
                luma[3]     = offset += a->delta[bytestream[3] >>  4];
                luma[4]     = offset += a->delta[bytestream[0] & 0xF];
                luma[5]     = offset += a->delta[bytestream[0] >>  4];
                luma[6]     = offset += a->delta[bytestream[1] & 0xF];
                luma[7]     = offset += a->delta[bytestream[1] >>  4];
                luma       += 8;
                bytestream += 4;
                buf_size   -= 4;
            }
        }
    }
    *got_frame = 1;
    return buf_size;
packet_small:
    av_log(avctx, AV_LOG_ERROR, "Input packet too small.\n");
    return AVERROR_INVALIDDATA;
}

