    case PIX_FMT_UYVY422  : c->lumToYV12 = uyvyToY_c;    break;

    case PIX_FMT_BGR24    : c->lumToYV12 = bgr24ToY_c;   break;

    case PIX_FMT_BGR565LE : c->lumToYV12 = bgr16leToY_c; break;

