        case PIX_FMT_PAL8 : c->alpToYV12 = palToA_c; break;

        }

    }

}

void updateMMXDitherTables(SwsContext *c, int dstY, int lumBufIndex, int chrBufIndex,

                           int lastInLumBuf, int lastInChrBuf)

{

    const int dstH= c->dstH;

    const int flags= c->flags;

    int16_t **lumPixBuf= c->lumPixBuf;

    int16_t **chrUPixBuf= c->chrUPixBuf;

    int16_t **alpPixBuf= c->alpPixBuf;

    const int vLumBufSize= c->vLumBufSize;

    const int vChrBufSize= c->vChrBufSize;

    int32_t *vLumFilterPos= c->vLumFilterPos;

    int32_t *vChrFilterPos= c->vChrFilterPos;

    int16_t *vLumFilter= c->vLumFilter;

    int16_t *vChrFilter= c->vChrFilter;

    int32_t *lumMmxFilter= c->lumMmxFilter;

    int32_t *chrMmxFilter= c->chrMmxFilter;

    int32_t av_unused *alpMmxFilter= c->alpMmxFilter;

    const int vLumFilterSize= c->vLumFilterSize;

    const int vChrFilterSize= c->vChrFilterSize;

    const int chrDstY= dstY>>c->chrDstVSubSample;

    const int firstLumSrcY= vLumFilterPos[dstY]; //First line needed as input

    const int firstChrSrcY= vChrFilterPos[chrDstY]; //First line needed as input



    c->blueDither= ff_dither8[dstY&1];

    if (c->dstFormat == PIX_FMT_RGB555 || c->dstFormat == PIX_FMT_BGR555)

        c->greenDither= ff_dither8[dstY&1];

    else

        c->greenDither= ff_dither4[dstY&1];

    c->redDither= ff_dither8[(dstY+1)&1];

    if (dstY < dstH - 2) {

        const int16_t **lumSrcPtr= (const int16_t **)(void*) lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

        const int16_t **chrUSrcPtr= (const int16_t **)(void*) chrUPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

        const int16_t **alpSrcPtr= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? (const int16_t **)(void*) alpPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize : NULL;

        int i;



        if (firstLumSrcY < 0 || firstLumSrcY + vLumFilterSize > c->srcH) {

            const int16_t **tmpY = (const int16_t **) lumPixBuf + 2 * vLumBufSize;

            int neg = -firstLumSrcY, i, end = FFMIN(c->srcH - firstLumSrcY, vLumFilterSize);

            for (i = 0; i < neg;            i++)

                tmpY[i] = lumSrcPtr[neg];

            for (     ; i < end;            i++)

                tmpY[i] = lumSrcPtr[i];

            for (     ; i < vLumFilterSize; i++)

                tmpY[i] = tmpY[i-1];

            lumSrcPtr = tmpY;



            if (alpSrcPtr) {

                const int16_t **tmpA = (const int16_t **) alpPixBuf + 2 * vLumBufSize;

                for (i = 0; i < neg;            i++)

                    tmpA[i] = alpSrcPtr[neg];

                for (     ; i < end;            i++)

                    tmpA[i] = alpSrcPtr[i];

                for (     ; i < vLumFilterSize; i++)

                    tmpA[i] = tmpA[i - 1];

                alpSrcPtr = tmpA;

            }

        }

        if (firstChrSrcY < 0 || firstChrSrcY + vChrFilterSize > c->chrSrcH) {

            const int16_t **tmpU = (const int16_t **) chrUPixBuf + 2 * vChrBufSize;

            int neg = -firstChrSrcY, i, end = FFMIN(c->chrSrcH - firstChrSrcY, vChrFilterSize);

            for (i = 0; i < neg;            i++) {

                tmpU[i] = chrUSrcPtr[neg];

            }

            for (     ; i < end;            i++) {

                tmpU[i] = chrUSrcPtr[i];

            }

            for (     ; i < vChrFilterSize; i++) {

                tmpU[i] = tmpU[i - 1];

            }

            chrUSrcPtr = tmpU;

        }



        if (flags & SWS_ACCURATE_RND) {

            int s= APCK_SIZE / 8;

            for (i=0; i<vLumFilterSize; i+=2) {

                *(const void**)&lumMmxFilter[s*i              ]= lumSrcPtr[i  ];

                *(const void**)&lumMmxFilter[s*i+APCK_PTR2/4  ]= lumSrcPtr[i+(vLumFilterSize>1)];

                lumMmxFilter[s*i+APCK_COEF/4  ]=

                lumMmxFilter[s*i+APCK_COEF/4+1]= vLumFilter[dstY*vLumFilterSize + i    ]

                + (vLumFilterSize>1 ? vLumFilter[dstY*vLumFilterSize + i + 1]<<16 : 0);

                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {

                    *(const void**)&alpMmxFilter[s*i              ]= alpSrcPtr[i  ];

                    *(const void**)&alpMmxFilter[s*i+APCK_PTR2/4  ]= alpSrcPtr[i+(vLumFilterSize>1)];

                    alpMmxFilter[s*i+APCK_COEF/4  ]=

                    alpMmxFilter[s*i+APCK_COEF/4+1]= lumMmxFilter[s*i+APCK_COEF/4  ];

                }

            }

            for (i=0; i<vChrFilterSize; i+=2) {

                *(const void**)&chrMmxFilter[s*i              ]= chrUSrcPtr[i  ];

                *(const void**)&chrMmxFilter[s*i+APCK_PTR2/4  ]= chrUSrcPtr[i+(vChrFilterSize>1)];

                chrMmxFilter[s*i+APCK_COEF/4  ]=

                chrMmxFilter[s*i+APCK_COEF/4+1]= vChrFilter[chrDstY*vChrFilterSize + i    ]

                + (vChrFilterSize>1 ? vChrFilter[chrDstY*vChrFilterSize + i + 1]<<16 : 0);

            }

        } else {

            for (i=0; i<vLumFilterSize; i++) {

                *(const void**)&lumMmxFilter[4*i+0]= lumSrcPtr[i];

                lumMmxFilter[4*i+2]=

                lumMmxFilter[4*i+3]=

                ((uint16_t)vLumFilter[dstY*vLumFilterSize + i])*0x10001;

                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {

                    *(const void**)&alpMmxFilter[4*i+0]= alpSrcPtr[i];

                    alpMmxFilter[4*i+2]=

                    alpMmxFilter[4*i+3]= lumMmxFilter[4*i+2];

                }

            }

            for (i=0; i<vChrFilterSize; i++) {

                *(const void**)&chrMmxFilter[4*i+0]= chrUSrcPtr[i];

                chrMmxFilter[4*i+2]=

                chrMmxFilter[4*i+3]=

                ((uint16_t)vChrFilter[chrDstY*vChrFilterSize + i])*0x10001;

            }

        }

    }

}

void ff_get_unscaled_swscale(SwsContext *c)

{

    const enum PixelFormat srcFormat = c->srcFormat;

    const enum PixelFormat dstFormat = c->dstFormat;

    const int flags = c->flags;

    const int dstH = c->dstH;

    int needsDither;



    needsDither= isAnyRGB(dstFormat)

        &&  c->dstFormatBpp < 24

        && (c->dstFormatBpp < c->srcFormatBpp || (!isAnyRGB(srcFormat)));



    /* yv12_to_nv12 */

    if ((srcFormat == PIX_FMT_YUV420P || srcFormat == PIX_FMT_YUVA420P) && (dstFormat == PIX_FMT_NV12 || dstFormat == PIX_FMT_NV21)) {

        c->swScale= planarToNv12Wrapper;

    }

    /* yuv2bgr */

    if ((srcFormat==PIX_FMT_YUV420P || srcFormat==PIX_FMT_YUV422P || srcFormat==PIX_FMT_YUVA420P) && isAnyRGB(dstFormat)

        && !(flags & SWS_ACCURATE_RND) && !(dstH&1)) {

        c->swScale= ff_yuv2rgb_get_func_ptr(c);

    }



    if (srcFormat==PIX_FMT_YUV410P && (dstFormat==PIX_FMT_YUV420P || dstFormat==PIX_FMT_YUVA420P) && !(flags & SWS_BITEXACT)) {

        c->swScale= yvu9ToYv12Wrapper;

    }



    /* bgr24toYV12 */

    if (srcFormat==PIX_FMT_BGR24 && (dstFormat==PIX_FMT_YUV420P || dstFormat==PIX_FMT_YUVA420P) && !(flags & SWS_ACCURATE_RND))

        c->swScale= bgr24ToYv12Wrapper;



    /* RGB/BGR -> RGB/BGR (no dither needed forms) */

    if (   isAnyRGB(srcFormat)

        && isAnyRGB(dstFormat)

        && srcFormat != PIX_FMT_BGR8      && dstFormat != PIX_FMT_BGR8

        && srcFormat != PIX_FMT_RGB8      && dstFormat != PIX_FMT_RGB8

        && srcFormat != PIX_FMT_BGR4      && dstFormat != PIX_FMT_BGR4

        && srcFormat != PIX_FMT_RGB4      && dstFormat != PIX_FMT_RGB4

        && srcFormat != PIX_FMT_BGR4_BYTE && dstFormat != PIX_FMT_BGR4_BYTE

        && srcFormat != PIX_FMT_RGB4_BYTE && dstFormat != PIX_FMT_RGB4_BYTE

        && srcFormat != PIX_FMT_MONOBLACK && dstFormat != PIX_FMT_MONOBLACK

        && srcFormat != PIX_FMT_MONOWHITE && dstFormat != PIX_FMT_MONOWHITE

        && srcFormat != PIX_FMT_RGB48LE   && dstFormat != PIX_FMT_RGB48LE

        && srcFormat != PIX_FMT_RGB48BE   && dstFormat != PIX_FMT_RGB48BE

        && srcFormat != PIX_FMT_BGR48LE   && dstFormat != PIX_FMT_BGR48LE

        && srcFormat != PIX_FMT_BGR48BE   && dstFormat != PIX_FMT_BGR48BE

        && (!needsDither || (c->flags&(SWS_FAST_BILINEAR|SWS_POINT))))

        c->swScale= rgbToRgbWrapper;



#define isByteRGB(f) (\

        f == PIX_FMT_RGB32   ||\

        f == PIX_FMT_RGB32_1 ||\

        f == PIX_FMT_RGB24   ||\

        f == PIX_FMT_BGR32   ||\

        f == PIX_FMT_BGR32_1 ||\

        f == PIX_FMT_BGR24)



    if (isAnyRGB(srcFormat) && isPlanar(srcFormat) && isByteRGB(dstFormat))

        c->swScale= planarRgbToRgbWrapper;



    if ((usePal(srcFormat) && (

        dstFormat == PIX_FMT_RGB32   ||

        dstFormat == PIX_FMT_RGB32_1 ||

        dstFormat == PIX_FMT_RGB24   ||

        dstFormat == PIX_FMT_BGR32   ||

        dstFormat == PIX_FMT_BGR32_1 ||

        dstFormat == PIX_FMT_BGR24)))

        c->swScale= palToRgbWrapper;



    if (srcFormat == PIX_FMT_YUV422P) {

        if (dstFormat == PIX_FMT_YUYV422)

            c->swScale= yuv422pToYuy2Wrapper;

        else if (dstFormat == PIX_FMT_UYVY422)

            c->swScale= yuv422pToUyvyWrapper;

    }



    /* LQ converters if -sws 0 or -sws 4*/

    if (c->flags&(SWS_FAST_BILINEAR|SWS_POINT)) {

        /* yv12_to_yuy2 */

        if (srcFormat == PIX_FMT_YUV420P || srcFormat == PIX_FMT_YUVA420P) {

            if (dstFormat == PIX_FMT_YUYV422)

                c->swScale= planarToYuy2Wrapper;

            else if (dstFormat == PIX_FMT_UYVY422)

                c->swScale= planarToUyvyWrapper;

        }

    }

    if(srcFormat == PIX_FMT_YUYV422 && (dstFormat == PIX_FMT_YUV420P || dstFormat == PIX_FMT_YUVA420P))

        c->swScale= yuyvToYuv420Wrapper;

    if(srcFormat == PIX_FMT_UYVY422 && (dstFormat == PIX_FMT_YUV420P || dstFormat == PIX_FMT_YUVA420P))

        c->swScale= uyvyToYuv420Wrapper;

    if(srcFormat == PIX_FMT_YUYV422 && dstFormat == PIX_FMT_YUV422P)

        c->swScale= yuyvToYuv422Wrapper;

    if(srcFormat == PIX_FMT_UYVY422 && dstFormat == PIX_FMT_YUV422P)

        c->swScale= uyvyToYuv422Wrapper;



    /* simple copy */

    if (  srcFormat == dstFormat

        || (srcFormat == PIX_FMT_YUVA420P && dstFormat == PIX_FMT_YUV420P)

        || (srcFormat == PIX_FMT_YUV420P && dstFormat == PIX_FMT_YUVA420P)

        || (isPlanarYUV(srcFormat) && isGray(dstFormat))

        || (isPlanarYUV(dstFormat) && isGray(srcFormat))

        || (isGray(dstFormat) && isGray(srcFormat))

        || (isPlanarYUV(srcFormat) && isPlanarYUV(dstFormat)

            && c->chrDstHSubSample == c->chrSrcHSubSample

            && c->chrDstVSubSample == c->chrSrcVSubSample

            && dstFormat != PIX_FMT_NV12 && dstFormat != PIX_FMT_NV21

            && srcFormat != PIX_FMT_NV12 && srcFormat != PIX_FMT_NV21))

    {

        if (isPacked(c->srcFormat))

            c->swScale= packedCopyWrapper;

        else /* Planar YUV or gray */

            c->swScale= planarCopyWrapper;

    }



    if (ARCH_BFIN)

        ff_bfin_get_unscaled_swscale(c);

    if (HAVE_ALTIVEC)

        ff_swscale_get_unscaled_altivec(c);

}

void avcodec_align_dimensions2(AVCodecContext *s, int *width, int *height,

                               int linesize_align[AV_NUM_DATA_POINTERS])

{

    int i;

    int w_align= 1;

    int h_align= 1;



    switch(s->pix_fmt){

    case PIX_FMT_YUV420P:

    case PIX_FMT_YUYV422:

    case PIX_FMT_UYVY422:

    case PIX_FMT_YUV422P:

    case PIX_FMT_YUV440P:

    case PIX_FMT_YUV444P:

    case PIX_FMT_GBRP:

    case PIX_FMT_GRAY8:

    case PIX_FMT_GRAY16BE:

    case PIX_FMT_GRAY16LE:

    case PIX_FMT_YUVJ420P:

    case PIX_FMT_YUVJ422P:

    case PIX_FMT_YUVJ440P:

    case PIX_FMT_YUVJ444P:

    case PIX_FMT_YUVA420P:

    case PIX_FMT_YUVA444P:

    case PIX_FMT_YUV420P9LE:

    case PIX_FMT_YUV420P9BE:

    case PIX_FMT_YUV420P10LE:

    case PIX_FMT_YUV420P10BE:

    case PIX_FMT_YUV422P9LE:

    case PIX_FMT_YUV422P9BE:

    case PIX_FMT_YUV422P10LE:

    case PIX_FMT_YUV422P10BE:

    case PIX_FMT_YUV444P9LE:

    case PIX_FMT_YUV444P9BE:

    case PIX_FMT_YUV444P10LE:

    case PIX_FMT_YUV444P10BE:

    case PIX_FMT_GBRP9LE:

    case PIX_FMT_GBRP9BE:

    case PIX_FMT_GBRP10LE:

    case PIX_FMT_GBRP10BE:

        w_align = 16; //FIXME assume 16 pixel per macroblock

        h_align = 16 * 2; // interlaced needs 2 macroblocks height

        break;

    case PIX_FMT_YUV411P:

    case PIX_FMT_UYYVYY411:

        w_align=32;

        h_align=8;

        break;

    case PIX_FMT_YUV410P:

        if(s->codec_id == CODEC_ID_SVQ1){

            w_align=64;

            h_align=64;

        }

    case PIX_FMT_RGB555:

        if(s->codec_id == CODEC_ID_RPZA){

            w_align=4;

            h_align=4;

        }

    case PIX_FMT_PAL8:

    case PIX_FMT_BGR8:

    case PIX_FMT_RGB8:

        if(s->codec_id == CODEC_ID_SMC){

            w_align=4;

            h_align=4;

        }

        break;

    case PIX_FMT_BGR24:

        if((s->codec_id == CODEC_ID_MSZH) || (s->codec_id == CODEC_ID_ZLIB)){

            w_align=4;

            h_align=4;

        }

        break;

    default:

        w_align= 1;

        h_align= 1;

        break;

    }



    if(s->codec_id == CODEC_ID_IFF_ILBM || s->codec_id == CODEC_ID_IFF_BYTERUN1){

        w_align= FFMAX(w_align, 8);

    }



    *width = FFALIGN(*width , w_align);

    *height= FFALIGN(*height, h_align);

    if (s->codec_id == CODEC_ID_H264)

        *height+=2; // some of the optimized chroma MC reads one line too much



    for (i = 0; i < 4; i++)

        linesize_align[i] = STRIDE_ALIGN;

}

static void pci_bridge_region_init(PCIBridge *br)

{

    PCIBus *parent = br->dev.bus;

    uint16_t cmd = pci_get_word(br->dev.config + PCI_COMMAND);



    pci_bridge_init_alias(br, &br->alias_pref_mem,

                          PCI_BASE_ADDRESS_MEM_PREFETCH,

                          "pci_bridge_pref_mem",

                          &br->address_space_mem,

                          parent->address_space_mem,

                          cmd & PCI_COMMAND_MEMORY);

    pci_bridge_init_alias(br, &br->alias_mem,

                          PCI_BASE_ADDRESS_SPACE_MEMORY,

                          "pci_bridge_mem",

                          &br->address_space_mem,

                          parent->address_space_mem,

                          cmd & PCI_COMMAND_MEMORY);

    pci_bridge_init_alias(br, &br->alias_io,

                          PCI_BASE_ADDRESS_SPACE_IO,

                          "pci_bridge_io",

                          &br->address_space_io,

                          parent->address_space_io,

                          cmd & PCI_COMMAND_IO);

   /* TODO: optinal VGA and VGA palette snooping support. */

}

int pci_bridge_initfn(PCIDevice *dev)

{

    PCIBus *parent = dev->bus;

    PCIBridge *br = DO_UPCAST(PCIBridge, dev, dev);

    PCIBus *sec_bus = &br->sec_bus;



    pci_word_test_and_set_mask(dev->config + PCI_STATUS,

                               PCI_STATUS_66MHZ | PCI_STATUS_FAST_BACK);

    pci_config_set_class(dev->config, PCI_CLASS_BRIDGE_PCI);

    dev->config[PCI_HEADER_TYPE] =

        (dev->config[PCI_HEADER_TYPE] & PCI_HEADER_TYPE_MULTI_FUNCTION) |

        PCI_HEADER_TYPE_BRIDGE;

    pci_set_word(dev->config + PCI_SEC_STATUS,

                 PCI_STATUS_66MHZ | PCI_STATUS_FAST_BACK);



    /*

     * If we don't specify the name, the bus will be addressed as <id>.0, where

     * id is the device id.

     * Since PCI Bridge devices have a single bus each, we don't need the index:

     * let users address the bus using the device name.

     */

    if (!br->bus_name && dev->qdev.id && *dev->qdev.id) {

	    br->bus_name = dev->qdev.id;

    }



    qbus_create_inplace(&sec_bus->qbus, TYPE_PCI_BUS, &dev->qdev,

                        br->bus_name);

    sec_bus->parent_dev = dev;

    sec_bus->map_irq = br->map_irq;

    sec_bus->address_space_mem = &br->address_space_mem;

    memory_region_init(&br->address_space_mem, "pci_bridge_pci", INT64_MAX);

    sec_bus->address_space_io = &br->address_space_io;

    memory_region_init(&br->address_space_io, "pci_bridge_io", 65536);

    pci_bridge_region_init(br);

    QLIST_INIT(&sec_bus->child);

    QLIST_INSERT_HEAD(&parent->child, sec_bus, sibling);

    return 0;

}

static void pci_bridge_region_del(PCIBridge *br, PCIBridgeWindows *w)

{

    PCIDevice *pd = PCI_DEVICE(br);

    PCIBus *parent = pd->bus;



    memory_region_del_subregion(parent->address_space_io, &w->alias_io);

    memory_region_del_subregion(parent->address_space_mem, &w->alias_mem);

    memory_region_del_subregion(parent->address_space_mem, &w->alias_pref_mem);

    pci_unregister_vga(pd);

}

static pcibus_t pci_bar_address(PCIDevice *d,

				int reg, uint8_t type, pcibus_t size)

{

    pcibus_t new_addr, last_addr;

    int bar = pci_bar(d, reg);

    uint16_t cmd = pci_get_word(d->config + PCI_COMMAND);



    if (type & PCI_BASE_ADDRESS_SPACE_IO) {

        if (!(cmd & PCI_COMMAND_IO)) {

            return PCI_BAR_UNMAPPED;

        }

        new_addr = pci_get_long(d->config + bar) & ~(size - 1);

        last_addr = new_addr + size - 1;

        /* Check if 32 bit BAR wraps around explicitly.

         * TODO: make priorities correct and remove this work around.

         */

        if (last_addr <= new_addr || new_addr == 0 || last_addr >= UINT32_MAX) {

            return PCI_BAR_UNMAPPED;

        }

        return new_addr;

    }



    if (!(cmd & PCI_COMMAND_MEMORY)) {

        return PCI_BAR_UNMAPPED;

    }

    if (type & PCI_BASE_ADDRESS_MEM_TYPE_64) {

        new_addr = pci_get_quad(d->config + bar);

    } else {

        new_addr = pci_get_long(d->config + bar);

    }

    /* the ROM slot has a specific enable bit */

    if (reg == PCI_ROM_SLOT && !(new_addr & PCI_ROM_ADDRESS_ENABLE)) {

        return PCI_BAR_UNMAPPED;

    }

    new_addr &= ~(size - 1);

    last_addr = new_addr + size - 1;

    /* NOTE: we do not support wrapping */

    /* XXX: as we cannot support really dynamic

       mappings, we handle specific values as invalid

       mappings. */

    if (last_addr <= new_addr || new_addr == 0 ||

        last_addr == PCI_BAR_UNMAPPED) {

        return PCI_BAR_UNMAPPED;

    }



    /* Now pcibus_t is 64bit.

     * Check if 32 bit BAR wraps around explicitly.

     * Without this, PC ide doesn't work well.

     * TODO: remove this work around.

     */

    if  (!(type & PCI_BASE_ADDRESS_MEM_TYPE_64) && last_addr >= UINT32_MAX) {

        return PCI_BAR_UNMAPPED;

    }



    /*

     * OS is allowed to set BAR beyond its addressable

     * bits. For example, 32 bit OS can set 64bit bar

     * to >4G. Check it. TODO: we might need to support

     * it in the future for e.g. PAE.

     */

    if (last_addr >= HWADDR_MAX) {

        return PCI_BAR_UNMAPPED;

    }



    return new_addr;

}

void ff_hevc_set_qPy(HEVCContext *s, int xC, int yC,

                     int xBase, int yBase, int log2_cb_size)

{

    int qp_y = get_qPy_pred(s, xC, yC, xBase, yBase, log2_cb_size);



    if (s->HEVClc->tu.cu_qp_delta != 0) {

        int off = s->sps->qp_bd_offset;

        s->HEVClc->qp_y = ((qp_y + s->HEVClc->tu.cu_qp_delta + 52 + 2 * off) %

                          (52 + off)) - off;

    } else

        s->HEVClc->qp_y = qp_y;

}

void ff_hevc_deblocking_boundary_strengths(HEVCContext *s, int x0, int y0,

                                           int log2_trafo_size,

                                           int slice_or_tiles_up_boundary,

                                           int slice_or_tiles_left_boundary)

{

    MvField *tab_mvf     = s->ref->tab_mvf;

    int log2_min_pu_size = s->sps->log2_min_pu_size;

    int log2_min_tu_size = s->sps->log2_min_tb_size;

    int min_pu_width     = s->sps->min_pu_width;

    int min_tu_width     = s->sps->min_tb_width;

    int is_intra = tab_mvf[(y0 >> log2_min_pu_size) * min_pu_width +

                           (x0 >> log2_min_pu_size)].is_intra;

    int i, j, bs;



    if (y0 > 0 && (y0 & 7) == 0) {

        int yp_pu = (y0 - 1) >> log2_min_pu_size;

        int yq_pu =  y0      >> log2_min_pu_size;

        int yp_tu = (y0 - 1) >> log2_min_tu_size;

        int yq_tu =  y0      >> log2_min_tu_size;



        for (i = 0; i < (1 << log2_trafo_size); i += 4) {

            int x_pu = (x0 + i) >> log2_min_pu_size;

            int x_tu = (x0 + i) >> log2_min_tu_size;

            MvField *top  = &tab_mvf[yp_pu * min_pu_width + x_pu];

            MvField *curr = &tab_mvf[yq_pu * min_pu_width + x_pu];

            uint8_t top_cbf_luma  = s->cbf_luma[yp_tu * min_tu_width + x_tu];

            uint8_t curr_cbf_luma = s->cbf_luma[yq_tu * min_tu_width + x_tu];

            RefPicList *top_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                              x0 + i, y0 - 1);



            bs = boundary_strength(s, curr, curr_cbf_luma,

                                   top, top_cbf_luma, top_refPicList, 1);

            if (!s->sh.slice_loop_filter_across_slices_enabled_flag &&

                (slice_or_tiles_up_boundary & 1) &&

                (y0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            else if (!s->pps->loop_filter_across_tiles_enabled_flag &&

                     (slice_or_tiles_up_boundary & 2) &&

                     (y0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            if (y0 == 0 || s->sh.disable_deblocking_filter_flag == 1)

                bs = 0;

            if (bs)

                s->horizontal_bs[((x0 + i) + y0 * s->bs_width) >> 2] = bs;

        }

    }



    // bs for TU internal horizontal PU boundaries

    if (log2_trafo_size > s->sps->log2_min_pu_size && !is_intra)

        for (j = 8; j < (1 << log2_trafo_size); j += 8) {

            int yp_pu = (y0 + j - 1) >> log2_min_pu_size;

            int yq_pu = (y0 + j)     >> log2_min_pu_size;

            int yp_tu = (y0 + j - 1) >> log2_min_tu_size;

            int yq_tu = (y0 + j)     >> log2_min_tu_size;



            for (i = 0; i < (1 << log2_trafo_size); i += 4) {

                int x_pu = (x0 + i) >> log2_min_pu_size;

                int x_tu = (x0 + i) >> log2_min_tu_size;

                MvField *top  = &tab_mvf[yp_pu * min_pu_width + x_pu];

                MvField *curr = &tab_mvf[yq_pu * min_pu_width + x_pu];

                uint8_t top_cbf_luma  = s->cbf_luma[yp_tu * min_tu_width + x_tu];

                uint8_t curr_cbf_luma = s->cbf_luma[yq_tu * min_tu_width + x_tu];

                RefPicList *top_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                                  x0 + i,

                                                                  y0 + j - 1);



                bs = boundary_strength(s, curr, curr_cbf_luma,

                                       top, top_cbf_luma, top_refPicList, 0);

                if (s->sh.disable_deblocking_filter_flag == 1)

                    bs = 0;

                if (bs)

                    s->horizontal_bs[((x0 + i) + (y0 + j) * s->bs_width) >> 2] = bs;

            }

        }



    // bs for vertical TU boundaries

    if (x0 > 0 && (x0 & 7) == 0) {

        int xp_pu = (x0 - 1) >> log2_min_pu_size;

        int xq_pu =  x0      >> log2_min_pu_size;

        int xp_tu = (x0 - 1) >> log2_min_tu_size;

        int xq_tu =  x0      >> log2_min_tu_size;



        for (i = 0; i < (1 << log2_trafo_size); i += 4) {

            int y_pu      = (y0 + i) >> log2_min_pu_size;

            int y_tu      = (y0 + i) >> log2_min_tu_size;

            MvField *left = &tab_mvf[y_pu * min_pu_width + xp_pu];

            MvField *curr = &tab_mvf[y_pu * min_pu_width + xq_pu];



            uint8_t left_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xp_tu];

            uint8_t curr_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xq_tu];

            RefPicList *left_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                               x0 - 1, y0 + i);



            bs = boundary_strength(s, curr, curr_cbf_luma,

                                   left, left_cbf_luma, left_refPicList, 1);

            if (!s->sh.slice_loop_filter_across_slices_enabled_flag &&

                (slice_or_tiles_left_boundary & 1) &&

                (x0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            else if (!s->pps->loop_filter_across_tiles_enabled_flag &&

                     (slice_or_tiles_left_boundary & 2) &&

                     (x0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            if (x0 == 0 || s->sh.disable_deblocking_filter_flag == 1)

                bs = 0;

            if (bs)

                s->vertical_bs[(x0 >> 3) + ((y0 + i) >> 2) * s->bs_width] = bs;

        }

    }



    // bs for TU internal vertical PU boundaries

    if (log2_trafo_size > log2_min_pu_size && !is_intra)

        for (j = 0; j < (1 << log2_trafo_size); j += 4) {

            int y_pu = (y0 + j) >> log2_min_pu_size;

            int y_tu = (y0 + j) >> log2_min_tu_size;



            for (i = 8; i < (1 << log2_trafo_size); i += 8) {

                int xp_pu = (x0 + i - 1) >> log2_min_pu_size;

                int xq_pu = (x0 + i)     >> log2_min_pu_size;

                int xp_tu = (x0 + i - 1) >> log2_min_tu_size;

                int xq_tu = (x0 + i)     >> log2_min_tu_size;

                MvField *left = &tab_mvf[y_pu * min_pu_width + xp_pu];

                MvField *curr = &tab_mvf[y_pu * min_pu_width + xq_pu];

                uint8_t left_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xp_tu];

                uint8_t curr_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xq_tu];

                RefPicList *left_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                                   x0 + i - 1,

                                                                   y0 + j);



                bs = boundary_strength(s, curr, curr_cbf_luma,

                                       left, left_cbf_luma, left_refPicList, 0);

                if (s->sh.disable_deblocking_filter_flag == 1)

                    bs = 0;

                if (bs)

                    s->vertical_bs[((x0 + i) >> 3) + ((y0 + j) >> 2) * s->bs_width] = bs;

            }

        }

}

static void hls_transform_unit(HEVCContext *s, int x0, int y0,

                               int xBase, int yBase, int cb_xBase, int cb_yBase,

                               int log2_cb_size, int log2_trafo_size,

                               int trafo_depth, int blk_idx)

{

    HEVCLocalContext *lc = &s->HEVClc;



    if (lc->cu.pred_mode == MODE_INTRA) {

        int trafo_size = 1 << log2_trafo_size;

        ff_hevc_set_neighbour_available(s, x0, y0, trafo_size, trafo_size);



        s->hpc.intra_pred(s, x0, y0, log2_trafo_size, 0);

        if (log2_trafo_size > 2) {

            trafo_size = trafo_size << (s->sps->hshift[1] - 1);

            ff_hevc_set_neighbour_available(s, x0, y0, trafo_size, trafo_size);

            s->hpc.intra_pred(s, x0, y0, log2_trafo_size - 1, 1);

            s->hpc.intra_pred(s, x0, y0, log2_trafo_size - 1, 2);

        } else if (blk_idx == 3) {

            trafo_size = trafo_size << s->sps->hshift[1];

            ff_hevc_set_neighbour_available(s, xBase, yBase,

                                            trafo_size, trafo_size);

            s->hpc.intra_pred(s, xBase, yBase, log2_trafo_size, 1);

            s->hpc.intra_pred(s, xBase, yBase, log2_trafo_size, 2);

        }

    }



    if (lc->tt.cbf_luma ||

        SAMPLE_CBF(lc->tt.cbf_cb[trafo_depth], x0, y0) ||

        SAMPLE_CBF(lc->tt.cbf_cr[trafo_depth], x0, y0)) {

        int scan_idx   = SCAN_DIAG;

        int scan_idx_c = SCAN_DIAG;



        if (s->pps->cu_qp_delta_enabled_flag && !lc->tu.is_cu_qp_delta_coded) {

            lc->tu.cu_qp_delta = ff_hevc_cu_qp_delta_abs(s);

            if (lc->tu.cu_qp_delta != 0)

                if (ff_hevc_cu_qp_delta_sign_flag(s) == 1)

                    lc->tu.cu_qp_delta = -lc->tu.cu_qp_delta;

            lc->tu.is_cu_qp_delta_coded = 1;

            ff_hevc_set_qPy(s, x0, y0, cb_xBase, cb_yBase, log2_cb_size);

        }



        if (lc->cu.pred_mode == MODE_INTRA && log2_trafo_size < 4) {

            if (lc->tu.cur_intra_pred_mode >= 6 &&

                lc->tu.cur_intra_pred_mode <= 14) {

                scan_idx = SCAN_VERT;

            } else if (lc->tu.cur_intra_pred_mode >= 22 &&

                       lc->tu.cur_intra_pred_mode <= 30) {

                scan_idx = SCAN_HORIZ;

            }



            if (lc->pu.intra_pred_mode_c >=  6 &&

                lc->pu.intra_pred_mode_c <= 14) {

                scan_idx_c = SCAN_VERT;

            } else if (lc->pu.intra_pred_mode_c >= 22 &&

                       lc->pu.intra_pred_mode_c <= 30) {

                scan_idx_c = SCAN_HORIZ;

            }

        }



        if (lc->tt.cbf_luma)

            hls_residual_coding(s, x0, y0, log2_trafo_size, scan_idx, 0);

        if (log2_trafo_size > 2) {

            if (SAMPLE_CBF(lc->tt.cbf_cb[trafo_depth], x0, y0))

                hls_residual_coding(s, x0, y0, log2_trafo_size - 1, scan_idx_c, 1);

            if (SAMPLE_CBF(lc->tt.cbf_cr[trafo_depth], x0, y0))

                hls_residual_coding(s, x0, y0, log2_trafo_size - 1, scan_idx_c, 2);

        } else if (blk_idx == 3) {

            if (SAMPLE_CBF(lc->tt.cbf_cb[trafo_depth], xBase, yBase))

                hls_residual_coding(s, xBase, yBase, log2_trafo_size, scan_idx_c, 1);

            if (SAMPLE_CBF(lc->tt.cbf_cr[trafo_depth], xBase, yBase))

                hls_residual_coding(s, xBase, yBase, log2_trafo_size, scan_idx_c, 2);

        }

    }

}

static int hls_transform_unit(HEVCContext *s, int x0, int y0,

                              int xBase, int yBase, int cb_xBase, int cb_yBase,

                              int log2_cb_size, int log2_trafo_size,

                              int trafo_depth, int blk_idx,

                              int cbf_luma, int *cbf_cb, int *cbf_cr)

{

    HEVCLocalContext *lc = s->HEVClc;

    const int log2_trafo_size_c = log2_trafo_size - s->sps->hshift[1];

    int i;



    if (lc->cu.pred_mode == MODE_INTRA) {

        int trafo_size = 1 << log2_trafo_size;

        ff_hevc_set_neighbour_available(s, x0, y0, trafo_size, trafo_size);



        s->hpc.intra_pred[log2_trafo_size - 2](s, x0, y0, 0);

    }



    if (cbf_luma || cbf_cb[0] || cbf_cr[0] ||

        (s->sps->chroma_format_idc == 2 && (cbf_cb[1] || cbf_cr[1]))) {

        int scan_idx   = SCAN_DIAG;

        int scan_idx_c = SCAN_DIAG;

        int cbf_chroma = cbf_cb[0] || cbf_cr[0] ||

                         (s->sps->chroma_format_idc == 2 &&

                         (cbf_cb[1] || cbf_cr[1]));



        if (s->pps->cu_qp_delta_enabled_flag && !lc->tu.is_cu_qp_delta_coded) {

            lc->tu.cu_qp_delta = ff_hevc_cu_qp_delta_abs(s);

            if (lc->tu.cu_qp_delta != 0)

                if (ff_hevc_cu_qp_delta_sign_flag(s) == 1)

                    lc->tu.cu_qp_delta = -lc->tu.cu_qp_delta;

            lc->tu.is_cu_qp_delta_coded = 1;



            if (lc->tu.cu_qp_delta < -(26 + s->sps->qp_bd_offset / 2) ||

                lc->tu.cu_qp_delta >  (25 + s->sps->qp_bd_offset / 2)) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "The cu_qp_delta %d is outside the valid range "

                       "[%d, %d].\n",

                       lc->tu.cu_qp_delta,

                       -(26 + s->sps->qp_bd_offset / 2),

                        (25 + s->sps->qp_bd_offset / 2));

                return AVERROR_INVALIDDATA;

            }



            ff_hevc_set_qPy(s, cb_xBase, cb_yBase, log2_cb_size);

        }



        if (s->sh.cu_chroma_qp_offset_enabled_flag && cbf_chroma &&

            !lc->cu.cu_transquant_bypass_flag  &&  !lc->tu.is_cu_chroma_qp_offset_coded) {

            int cu_chroma_qp_offset_flag = ff_hevc_cu_chroma_qp_offset_flag(s);

            if (cu_chroma_qp_offset_flag) {

                int cu_chroma_qp_offset_idx  = 0;

                if (s->pps->chroma_qp_offset_list_len_minus1 > 0) {

                    cu_chroma_qp_offset_idx = ff_hevc_cu_chroma_qp_offset_idx(s);

                    av_log(s->avctx, AV_LOG_ERROR,

                        "cu_chroma_qp_offset_idx not yet tested.\n");

                }

                lc->tu.cu_qp_offset_cb = s->pps->cb_qp_offset_list[cu_chroma_qp_offset_idx];

                lc->tu.cu_qp_offset_cr = s->pps->cr_qp_offset_list[cu_chroma_qp_offset_idx];

            } else {

                lc->tu.cu_qp_offset_cb = 0;

                lc->tu.cu_qp_offset_cr = 0;

            }

            lc->tu.is_cu_chroma_qp_offset_coded = 1;

        }



        if (lc->cu.pred_mode == MODE_INTRA && log2_trafo_size < 4) {

            if (lc->tu.intra_pred_mode >= 6 &&

                lc->tu.intra_pred_mode <= 14) {

                scan_idx = SCAN_VERT;

            } else if (lc->tu.intra_pred_mode >= 22 &&

                       lc->tu.intra_pred_mode <= 30) {

                scan_idx = SCAN_HORIZ;

            }



            if (lc->tu.intra_pred_mode_c >=  6 &&

                lc->tu.intra_pred_mode_c <= 14) {

                scan_idx_c = SCAN_VERT;

            } else if (lc->tu.intra_pred_mode_c >= 22 &&

                       lc->tu.intra_pred_mode_c <= 30) {

                scan_idx_c = SCAN_HORIZ;

            }

        }



        lc->tu.cross_pf = 0;



        if (cbf_luma)

            ff_hevc_hls_residual_coding(s, x0, y0, log2_trafo_size, scan_idx, 0);

        if (log2_trafo_size > 2 || s->sps->chroma_format_idc == 3) {

            int trafo_size_h = 1 << (log2_trafo_size_c + s->sps->hshift[1]);

            int trafo_size_v = 1 << (log2_trafo_size_c + s->sps->vshift[1]);

            lc->tu.cross_pf  = (s->pps->cross_component_prediction_enabled_flag && cbf_luma &&

                                (lc->cu.pred_mode == MODE_INTER ||

                                 (lc->tu.chroma_mode_c ==  4)));



            if (lc->tu.cross_pf) {

                hls_cross_component_pred(s, 0);

            }

            for (i = 0; i < (s->sps->chroma_format_idc == 2 ? 2 : 1); i++) {

                if (lc->cu.pred_mode == MODE_INTRA) {

                    ff_hevc_set_neighbour_available(s, x0, y0 + (i << log2_trafo_size_c), trafo_size_h, trafo_size_v);

                    s->hpc.intra_pred[log2_trafo_size_c - 2](s, x0, y0 + (i << log2_trafo_size_c), 1);

                }

                if (cbf_cb[i])

                    ff_hevc_hls_residual_coding(s, x0, y0 + (i << log2_trafo_size_c),

                                                log2_trafo_size_c, scan_idx_c, 1);

                else

                    if (lc->tu.cross_pf) {

                        ptrdiff_t stride = s->frame->linesize[1];

                        int hshift = s->sps->hshift[1];

                        int vshift = s->sps->vshift[1];

                        int16_t *coeffs_y = lc->tu.coeffs[0];

                        int16_t *coeffs =   lc->tu.coeffs[1];

                        int size = 1 << log2_trafo_size_c;



                        uint8_t *dst = &s->frame->data[1][(y0 >> vshift) * stride +

                                                              ((x0 >> hshift) << s->sps->pixel_shift)];

                        for (i = 0; i < (size * size); i++) {

                            coeffs[i] = ((lc->tu.res_scale_val * coeffs_y[i]) >> 3);

                        }

                        s->hevcdsp.transform_add[log2_trafo_size-2](dst, coeffs, stride);

                    }

            }



            if (lc->tu.cross_pf) {

                hls_cross_component_pred(s, 1);

            }

            for (i = 0; i < (s->sps->chroma_format_idc == 2 ? 2 : 1); i++) {

                if (lc->cu.pred_mode == MODE_INTRA) {

                    ff_hevc_set_neighbour_available(s, x0, y0 + (i << log2_trafo_size_c), trafo_size_h, trafo_size_v);

                    s->hpc.intra_pred[log2_trafo_size_c - 2](s, x0, y0 + (i << log2_trafo_size_c), 2);

                }

                if (cbf_cr[i])

                    ff_hevc_hls_residual_coding(s, x0, y0 + (i << log2_trafo_size_c),

                                                log2_trafo_size_c, scan_idx_c, 2);

                else

                    if (lc->tu.cross_pf) {

                        ptrdiff_t stride = s->frame->linesize[2];

                        int hshift = s->sps->hshift[2];

                        int vshift = s->sps->vshift[2];

                        int16_t *coeffs_y = lc->tu.coeffs[0];

                        int16_t *coeffs =   lc->tu.coeffs[1];

                        int size = 1 << log2_trafo_size_c;



                        uint8_t *dst = &s->frame->data[2][(y0 >> vshift) * stride +

                                                          ((x0 >> hshift) << s->sps->pixel_shift)];

                        for (i = 0; i < (size * size); i++) {

                            coeffs[i] = ((lc->tu.res_scale_val * coeffs_y[i]) >> 3);

                        }

                        s->hevcdsp.transform_add[log2_trafo_size-2](dst, coeffs, stride);

                    }

            }

        } else if (blk_idx == 3) {

            int trafo_size_h = 1 << (log2_trafo_size + 1);

            int trafo_size_v = 1 << (log2_trafo_size + s->sps->vshift[1]);

            for (i = 0; i < (s->sps->chroma_format_idc == 2 ? 2 : 1); i++) {

                if (lc->cu.pred_mode == MODE_INTRA) {

                    ff_hevc_set_neighbour_available(s, xBase, yBase + (i << log2_trafo_size),

                                                    trafo_size_h, trafo_size_v);

                    s->hpc.intra_pred[log2_trafo_size - 2](s, xBase, yBase + (i << log2_trafo_size), 1);

                }

                if (cbf_cb[i])

                    ff_hevc_hls_residual_coding(s, xBase, yBase + (i << log2_trafo_size),

                                                log2_trafo_size, scan_idx_c, 1);

            }

            for (i = 0; i < (s->sps->chroma_format_idc == 2 ? 2 : 1); i++) {

                if (lc->cu.pred_mode == MODE_INTRA) {

                    ff_hevc_set_neighbour_available(s, xBase, yBase + (i << log2_trafo_size),

                                                trafo_size_h, trafo_size_v);

                    s->hpc.intra_pred[log2_trafo_size - 2](s, xBase, yBase + (i << log2_trafo_size), 2);

                }

                if (cbf_cr[i])

                    ff_hevc_hls_residual_coding(s, xBase, yBase + (i << log2_trafo_size),

                                                log2_trafo_size, scan_idx_c, 2);

            }

        }

    } else if (lc->cu.pred_mode == MODE_INTRA) {

        if (log2_trafo_size > 2 || s->sps->chroma_format_idc == 3) {

            int trafo_size_h = 1 << (log2_trafo_size_c + s->sps->hshift[1]);

            int trafo_size_v = 1 << (log2_trafo_size_c + s->sps->vshift[1]);

            ff_hevc_set_neighbour_available(s, x0, y0, trafo_size_h, trafo_size_v);

            s->hpc.intra_pred[log2_trafo_size_c - 2](s, x0, y0, 1);

            s->hpc.intra_pred[log2_trafo_size_c - 2](s, x0, y0, 2);

            if (s->sps->chroma_format_idc == 2) {

                ff_hevc_set_neighbour_available(s, x0, y0 + (1 << log2_trafo_size_c),

                                                trafo_size_h, trafo_size_v);

                s->hpc.intra_pred[log2_trafo_size_c - 2](s, x0, y0 + (1 << log2_trafo_size_c), 1);

                s->hpc.intra_pred[log2_trafo_size_c - 2](s, x0, y0 + (1 << log2_trafo_size_c), 2);

            }

        } else if (blk_idx == 3) {

            int trafo_size_h = 1 << (log2_trafo_size + 1);

            int trafo_size_v = 1 << (log2_trafo_size + s->sps->vshift[1]);

            ff_hevc_set_neighbour_available(s, xBase, yBase,

                                            trafo_size_h, trafo_size_v);

            s->hpc.intra_pred[log2_trafo_size - 2](s, xBase, yBase, 1);

            s->hpc.intra_pred[log2_trafo_size - 2](s, xBase, yBase, 2);

            if (s->sps->chroma_format_idc == 2) {

                ff_hevc_set_neighbour_available(s, xBase, yBase + (1 << (log2_trafo_size)),

                                                trafo_size_h, trafo_size_v);

                s->hpc.intra_pred[log2_trafo_size - 2](s, xBase, yBase + (1 << (log2_trafo_size)), 1);

                s->hpc.intra_pred[log2_trafo_size - 2](s, xBase, yBase + (1 << (log2_trafo_size)), 2);

            }

        }

    }



    return 0;

}

static void synth_block_fcb_acb(WMAVoiceContext *s, GetBitContext *gb,

                                int block_idx, int size,

                                int block_pitch_sh2,

                                const struct frame_type_desc *frame_desc,

                                float *excitation)

{

    static const float gain_coeff[6] = {

        0.8169, -0.06545, 0.1726, 0.0185, -0.0359, 0.0458

    };

    float pulses[MAX_FRAMESIZE / 2], pred_err, acb_gain, fcb_gain;

    int n, idx, gain_weight;

    AMRFixed fcb;



    assert(size <= MAX_FRAMESIZE / 2);

    memset(pulses, 0, sizeof(*pulses) * size);



    fcb.pitch_lag      = block_pitch_sh2 >> 2;

    fcb.pitch_fac      = 1.0;

    fcb.no_repeat_mask = 0;

    fcb.n              = 0;



    /* For the other frame types, this is where we apply the innovation

     * (fixed) codebook pulses of the speech signal. */

    if (frame_desc->fcb_type == FCB_TYPE_AW_PULSES) {

        aw_pulse_set1(s, gb, block_idx, &fcb);

        aw_pulse_set2(s, gb, block_idx, &fcb);

    } else /* FCB_TYPE_EXC_PULSES */ {

        int offset_nbits = 5 - frame_desc->log_n_blocks;



        fcb.no_repeat_mask = -1;

        /* similar to ff_decode_10_pulses_35bits(), but with single pulses

         * (instead of double) for a subset of pulses */

        for (n = 0; n < 5; n++) {

            float sign;

            int pos1, pos2;



            sign           = get_bits1(gb) ? 1.0 : -1.0;

            pos1           = get_bits(gb, offset_nbits);

            fcb.x[fcb.n]   = n + 5 * pos1;

            fcb.y[fcb.n++] = sign;

            if (n < frame_desc->dbl_pulses) {

                pos2           = get_bits(gb, offset_nbits);

                fcb.x[fcb.n]   = n + 5 * pos2;

                fcb.y[fcb.n++] = (pos1 < pos2) ? -sign : sign;

            }

        }

    }

    ff_set_fixed_vector(pulses, &fcb, 1.0, size);



    /* Calculate gain for adaptive & fixed codebook signal.

     * see ff_amr_set_fixed_gain(). */

    idx = get_bits(gb, 7);

    fcb_gain = expf(avpriv_scalarproduct_float_c(s->gain_pred_err,

                                                 gain_coeff, 6) -

                    5.2409161640 + wmavoice_gain_codebook_fcb[idx]);

    acb_gain = wmavoice_gain_codebook_acb[idx];

    pred_err = av_clipf(wmavoice_gain_codebook_fcb[idx],

                        -2.9957322736 /* log(0.05) */,

                         1.6094379124 /* log(5.0)  */);



    gain_weight = 8 >> frame_desc->log_n_blocks;

    memmove(&s->gain_pred_err[gain_weight], s->gain_pred_err,

            sizeof(*s->gain_pred_err) * (6 - gain_weight));

    for (n = 0; n < gain_weight; n++)

        s->gain_pred_err[n] = pred_err;



    /* Calculation of adaptive codebook */

    if (frame_desc->acb_type == ACB_TYPE_ASYMMETRIC) {

        int len;

        for (n = 0; n < size; n += len) {

            int next_idx_sh16;

            int abs_idx    = block_idx * size + n;

            int pitch_sh16 = (s->last_pitch_val << 16) +

                             s->pitch_diff_sh16 * abs_idx;

            int pitch      = (pitch_sh16 + 0x6FFF) >> 16;

            int idx_sh16   = ((pitch << 16) - pitch_sh16) * 8 + 0x58000;

            idx            = idx_sh16 >> 16;

            if (s->pitch_diff_sh16) {

                if (s->pitch_diff_sh16 > 0) {

                    next_idx_sh16 = (idx_sh16) &~ 0xFFFF;

                } else

                    next_idx_sh16 = (idx_sh16 + 0x10000) &~ 0xFFFF;

                len = av_clip((idx_sh16 - next_idx_sh16) / s->pitch_diff_sh16 / 8,

                              1, size - n);

            } else

                len = size;



            ff_acelp_interpolatef(&excitation[n], &excitation[n - pitch],

                                  wmavoice_ipol1_coeffs, 17,

                                  idx, 9, len);

        }

    } else /* ACB_TYPE_HAMMING */ {

        int block_pitch = block_pitch_sh2 >> 2;

        idx             = block_pitch_sh2 & 3;

        if (idx) {

            ff_acelp_interpolatef(excitation, &excitation[-block_pitch],

                                  wmavoice_ipol2_coeffs, 4,

                                  idx, 8, size);

        } else

            av_memcpy_backptr((uint8_t *) excitation, sizeof(float) * block_pitch,

                              sizeof(float) * size);

    }



    /* Interpolate ACB/FCB and use as excitation signal */

    ff_weighted_vector_sumf(excitation, excitation, pulses,

                            acb_gain, fcb_gain, size);

}

static inline int get_block(GetBitContext *gb, DCTELEM *block, const uint8_t *scan,
                            const uint32_t *quant) {
    int coeff, i, n;
    int8_t ac;
    uint8_t dc = get_bits(gb, 8);
    // block not coded
    if (dc == 255)
    // number of non-zero coefficients
    coeff = get_bits(gb, 6);
    // normally we would only need to clear the (63 - coeff) last values,
    // but since we do not know where they are we just clear the whole block
    memset(block, 0, 64 * sizeof(DCTELEM));
    // 2 bits per coefficient
    while (coeff) {
        ac = get_sbits(gb, 2);
        if (ac == -2)
            break; // continue with more bits
        PUT_COEFF(ac);
    }
    // 4 bits per coefficient
    ALIGN(4);
    if (get_bits_count(gb) + (coeff << 2) >= gb->size_in_bits)
    while (coeff) {
        ac = get_sbits(gb, 4);
        if (ac == -8)
            break; // continue with more bits
        PUT_COEFF(ac);
    }
    // 8 bits per coefficient
    ALIGN(8);
    if (get_bits_count(gb) + (coeff << 3) >= gb->size_in_bits)
    while (coeff) {
        ac = get_sbits(gb, 8);
        PUT_COEFF(ac);
    }
    PUT_COEFF(dc);
    return 1;
}

static void unpack_superblocks(Vp3DecodeContext *s, GetBitContext *gb)

{

    int bit = 0;

    int current_superblock = 0;

    int current_run = 0;

    int decode_fully_flags = 0;

    int decode_partial_blocks = 0;



    int i, j;

    int current_fragment;



    debug_vp3("  vp3: unpacking superblock coding\n");



    if (s->keyframe) {



        debug_vp3("    keyframe-- all superblocks are fully coded\n");

        memset(s->superblock_coding, SB_FULLY_CODED, s->superblock_count);



    } else {



        /* unpack the list of partially-coded superblocks */

        bit = get_bits(gb, 1);

        /* toggle the bit because as soon as the first run length is 

         * fetched the bit will be toggled again */

        bit ^= 1;

        while (current_superblock < s->superblock_count) {

            if (current_run == 0) {

                bit ^= 1;

                current_run = get_superblock_run_length(gb);

                debug_block_coding("      setting superblocks %d..%d to %s\n",

                    current_superblock,

                    current_superblock + current_run - 1,

                    (bit) ? "partially coded" : "not coded");



                /* if any of the superblocks are not partially coded, flag

                 * a boolean to decode the list of fully-coded superblocks */

                if (bit == 0)

                    decode_fully_flags = 1;

            } else {



                /* make a note of the fact that there are partially coded

                 * superblocks */

                decode_partial_blocks = 1;



            }

            s->superblock_coding[current_superblock++] = 

                (bit) ? SB_PARTIALLY_CODED : SB_NOT_CODED;

            current_run--;

        }



        /* unpack the list of fully coded superblocks if any of the blocks were

         * not marked as partially coded in the previous step */

        if (decode_fully_flags) {



            current_superblock = 0;

            current_run = 0;

            bit = get_bits(gb, 1);

            /* toggle the bit because as soon as the first run length is 

             * fetched the bit will be toggled again */

            bit ^= 1;

            while (current_superblock < s->superblock_count) {



                /* skip any superblocks already marked as partially coded */

                if (s->superblock_coding[current_superblock] == SB_NOT_CODED) {



                    if (current_run == 0) {

                        bit ^= 1;

                        current_run = get_superblock_run_length(gb);

                    }



                    debug_block_coding("      setting superblock %d to %s\n",

                        current_superblock,

                        (bit) ? "fully coded" : "not coded");

                    s->superblock_coding[current_superblock] = 

                        (bit) ? SB_FULLY_CODED : SB_NOT_CODED;

                    current_run--;

                }

                current_superblock++;

            }

        }



        /* if there were partial blocks, initialize bitstream for

         * unpacking fragment codings */

        if (decode_partial_blocks) {



            current_run = 0;

            bit = get_bits(gb, 1);

            /* toggle the bit because as soon as the first run length is 

             * fetched the bit will be toggled again */

            bit ^= 1;

        }

    }



    /* figure out which fragments are coded; iterate through each

     * superblock (all planes) */

    s->coded_fragment_list_index = 0;

    s->first_coded_y_fragment = s->first_coded_c_fragment = 0;

    s->last_coded_y_fragment = s->last_coded_c_fragment = -1;

    memset(s->macroblock_coded, 0, s->macroblock_count);

    for (i = 0; i < s->superblock_count; i++) {



        /* iterate through all 16 fragments in a superblock */

        for (j = 0; j < 16; j++) {



            /* if the fragment is in bounds, check its coding status */

            current_fragment = s->superblock_fragments[i * 16 + j];

            if (current_fragment != -1) {

                if (s->superblock_coding[i] == SB_NOT_CODED) {



                    /* copy all the fragments from the prior frame */

                    s->all_fragments[current_fragment].coding_method = 

                        MODE_COPY;



                } else if (s->superblock_coding[i] == SB_PARTIALLY_CODED) {



                    /* fragment may or may not be coded; this is the case

                     * that cares about the fragment coding runs */

                    if (current_run == 0) {

                        bit ^= 1;

                        current_run = get_fragment_run_length(gb);

                    }



                    if (bit) {

                        /* mode will be decoded in the next phase */

                        s->all_fragments[current_fragment].coding_method = 

                            MODE_INTER_NO_MV;

                        s->coded_fragment_list[s->coded_fragment_list_index] = 

                            current_fragment;

                        if ((current_fragment >= s->u_fragment_start) &&

                            (s->last_coded_y_fragment == -1)) {

                            s->first_coded_c_fragment = s->coded_fragment_list_index;

                            s->last_coded_y_fragment = s->first_coded_c_fragment - 1;

                        }

                        s->coded_fragment_list_index++;

                        s->macroblock_coded[s->all_fragments[current_fragment].macroblock] = 1;

                        debug_block_coding("      superblock %d is partially coded, fragment %d is coded\n",

                            i, current_fragment);

                    } else {

                        /* not coded; copy this fragment from the prior frame */

                        s->all_fragments[current_fragment].coding_method =

                            MODE_COPY;

                        debug_block_coding("      superblock %d is partially coded, fragment %d is not coded\n",

                            i, current_fragment);

                    }



                    current_run--;



                } else {



                    /* fragments are fully coded in this superblock; actual

                     * coding will be determined in next step */

                    s->all_fragments[current_fragment].coding_method = 

                        MODE_INTER_NO_MV;

                    s->coded_fragment_list[s->coded_fragment_list_index] = 

                        current_fragment;

                    if ((current_fragment >= s->u_fragment_start) &&

                        (s->last_coded_y_fragment == -1)) {

                        s->first_coded_c_fragment = s->coded_fragment_list_index;

                        s->last_coded_y_fragment = s->first_coded_c_fragment - 1;

                    }

                    s->coded_fragment_list_index++;

                    s->macroblock_coded[s->all_fragments[current_fragment].macroblock] = 1;

                    debug_block_coding("      superblock %d is fully coded, fragment %d is coded\n",

                        i, current_fragment);

                }

            }

        }

    }



    if (s->first_coded_c_fragment == 0)

        /* no C fragments coded */

        s->last_coded_y_fragment = s->coded_fragment_list_index - 1;

    else

        s->last_coded_c_fragment = s->coded_fragment_list_index - 1;

    debug_block_coding("    %d total coded fragments, y: %d -> %d, c: %d -> %d\n",

        s->coded_fragment_list_index,

        s->first_coded_y_fragment,

        s->last_coded_y_fragment,

        s->first_coded_c_fragment,

        s->last_coded_c_fragment);

}

static int asf_build_simple_index(AVFormatContext *s, int stream_index)
{
    ff_asf_guid g;
    ASFContext *asf     = s->priv_data;
    int64_t current_pos = avio_tell(s->pb);
    int64_t ret;
    if((ret = avio_seek(s->pb, asf->data_object_offset + asf->data_object_size, SEEK_SET)) < 0) {
        return ret;
    if ((ret = ff_get_guid(s->pb, &g)) < 0)
    /* the data object can be followed by other top-level objects,
     * skip them until the simple index object is reached */
    while (ff_guidcmp(&g, &ff_asf_simple_index_header)) {
        int64_t gsize = avio_rl64(s->pb);
        if (gsize < 24 || avio_feof(s->pb)) {
        avio_skip(s->pb, gsize - 24);
        if ((ret = ff_get_guid(s->pb, &g)) < 0)
    {
        int64_t itime, last_pos = -1;
        int pct, ict;
        int i;
        int64_t av_unused gsize = avio_rl64(s->pb);
        if ((ret = ff_get_guid(s->pb, &g)) < 0)
        itime = avio_rl64(s->pb);
        pct   = avio_rl32(s->pb);
        ict   = avio_rl32(s->pb);
        av_log(s, AV_LOG_DEBUG,
               "itime:0x%"PRIx64", pct:%d, ict:%d\n", itime, pct, ict);
        for (i = 0; i < ict; i++) {
            int pktnum        = avio_rl32(s->pb);
            int pktct         = avio_rl16(s->pb);
            int64_t pos       = s->internal->data_offset + s->packet_size * (int64_t)pktnum;
            int64_t index_pts = FFMAX(av_rescale(itime, i, 10000) - asf->hdr.preroll, 0);
            if (pos != last_pos) {
                av_log(s, AV_LOG_DEBUG, "pktnum:%d, pktct:%d  pts: %"PRId64"\n",
                       pktnum, pktct, index_pts);
                av_add_index_entry(s->streams[stream_index], pos, index_pts,
                                   s->packet_size, 0, AVINDEX_KEYFRAME);
                last_pos = pos;
        asf->index_read = ict > 1;
end:
//     if (avio_feof(s->pb)) {
//         ret = 0;
//     }
    avio_seek(s->pb, current_pos, SEEK_SET);
    return ret;

static int asf_read_simple_index(AVFormatContext *s, const GUIDParseTable *g)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st    = NULL;

    uint64_t interval; // index entry time interval in 100 ns units, usually it's 1s

    uint32_t pkt_num, nb_entries;

    int32_t prev_pkt_num = -1;

    int i, ret;

    uint64_t size = avio_rl64(pb);



    // simple index objects should be ordered by stream number, this loop tries to find

    // the first not indexed video stream

    for (i = 0; i < asf->nb_streams; i++) {

        if ((asf->asf_st[i]->type == AVMEDIA_TYPE_VIDEO) && !asf->asf_st[i]->indexed) {

            asf->asf_st[i]->indexed = 1;

            st = s->streams[asf->asf_st[i]->index];

            break;

        }

    }

    if (!st) {

        avio_skip(pb, size - 24); // if there's no video stream, skip index object

        return 0;

    }

    avio_skip(pb, 16); // skip File ID

    interval = avio_rl64(pb);

    avio_skip(pb, 4);

    nb_entries = avio_rl32(pb);

    for (i = 0; i < nb_entries; i++) {

        pkt_num = avio_rl32(pb);

        ret = avio_skip(pb, 2);

        if (ret < 0) {

            av_log(s, AV_LOG_ERROR, "Skipping failed in asf_read_simple_index.\n");

            return ret;

        }

        if (prev_pkt_num != pkt_num) {

            av_add_index_entry(st, asf->first_packet_offset + asf->packet_size *

                               pkt_num, av_rescale(interval, i, 10000),

                               asf->packet_size, 0, AVINDEX_KEYFRAME);

            prev_pkt_num = pkt_num;

        }

    }

    asf->is_simple_index = 1;

    align_position(pb, asf->offset, size);



    return 0;

}

static void asf_build_simple_index(AVFormatContext *s, int stream_index)

{

    ff_asf_guid g;

    ASFContext *asf = s->priv_data;

    int64_t current_pos= avio_tell(s->pb);

    int i;



    avio_seek(s->pb, asf->data_object_offset + asf->data_object_size, SEEK_SET);

    ff_get_guid(s->pb, &g);



    /* the data object can be followed by other top-level objects,

       skip them until the simple index object is reached */

    while (ff_guidcmp(&g, &index_guid)) {

        int64_t gsize= avio_rl64(s->pb);

        if (gsize < 24 || url_feof(s->pb)) {

            avio_seek(s->pb, current_pos, SEEK_SET);

            return;

        }

        avio_skip(s->pb, gsize-24);

        ff_get_guid(s->pb, &g);

    }



    {

        int64_t itime, last_pos=-1;

        int pct, ict;

        int64_t av_unused gsize= avio_rl64(s->pb);

        ff_get_guid(s->pb, &g);

        itime=avio_rl64(s->pb);

        pct=avio_rl32(s->pb);

        ict=avio_rl32(s->pb);

        av_log(s, AV_LOG_DEBUG, "itime:0x%"PRIx64", pct:%d, ict:%d\n",itime,pct,ict);



        for (i=0;i<ict;i++){

            int pktnum=avio_rl32(s->pb);

            int pktct =avio_rl16(s->pb);

            int64_t pos      = s->data_offset + s->packet_size*(int64_t)pktnum;

            int64_t index_pts= FFMAX(av_rescale(itime, i, 10000) - asf->hdr.preroll, 0);



            if(pos != last_pos){

            av_log(s, AV_LOG_DEBUG, "pktnum:%d, pktct:%d  pts: %"PRId64"\n", pktnum, pktct, index_pts);

            av_add_index_entry(s->streams[stream_index], pos, index_pts, s->packet_size, 0, AVINDEX_KEYFRAME);

            last_pos=pos;

            }

        }

        asf->index_read= 1;

    }

    avio_seek(s->pb, current_pos, SEEK_SET);

}

static int ape_read_header(AVFormatContext * s)

{

    AVIOContext *pb = s->pb;

    APEContext *ape = s->priv_data;

    AVStream *st;

    uint32_t tag;

    int i;

    int total_blocks, final_size = 0;

    int64_t pts, file_size;



    /* Skip any leading junk such as id3v2 tags */

    ape->junklength = avio_tell(pb);



    tag = avio_rl32(pb);

    if (tag != MKTAG('M', 'A', 'C', ' '))

        return -1;



    ape->fileversion = avio_rl16(pb);



    if (ape->fileversion < APE_MIN_VERSION || ape->fileversion > APE_MAX_VERSION) {

        av_log(s, AV_LOG_ERROR, "Unsupported file version - %d.%02d\n",

               ape->fileversion / 1000, (ape->fileversion % 1000) / 10);

        return -1;

    }



    if (ape->fileversion >= 3980) {

        ape->padding1             = avio_rl16(pb);

        ape->descriptorlength     = avio_rl32(pb);

        ape->headerlength         = avio_rl32(pb);

        ape->seektablelength      = avio_rl32(pb);

        ape->wavheaderlength      = avio_rl32(pb);

        ape->audiodatalength      = avio_rl32(pb);

        ape->audiodatalength_high = avio_rl32(pb);

        ape->wavtaillength        = avio_rl32(pb);

        avio_read(pb, ape->md5, 16);



        /* Skip any unknown bytes at the end of the descriptor.

           This is for future compatibility */

        if (ape->descriptorlength > 52)

            avio_skip(pb, ape->descriptorlength - 52);



        /* Read header data */

        ape->compressiontype      = avio_rl16(pb);

        ape->formatflags          = avio_rl16(pb);

        ape->blocksperframe       = avio_rl32(pb);

        ape->finalframeblocks     = avio_rl32(pb);

        ape->totalframes          = avio_rl32(pb);

        ape->bps                  = avio_rl16(pb);

        ape->channels             = avio_rl16(pb);

        ape->samplerate           = avio_rl32(pb);

    } else {

        ape->descriptorlength = 0;

        ape->headerlength = 32;



        ape->compressiontype      = avio_rl16(pb);

        ape->formatflags          = avio_rl16(pb);

        ape->channels             = avio_rl16(pb);

        ape->samplerate           = avio_rl32(pb);

        ape->wavheaderlength      = avio_rl32(pb);

        ape->wavtaillength        = avio_rl32(pb);

        ape->totalframes          = avio_rl32(pb);

        ape->finalframeblocks     = avio_rl32(pb);



        if (ape->formatflags & MAC_FORMAT_FLAG_HAS_PEAK_LEVEL) {

            avio_skip(pb, 4); /* Skip the peak level */

            ape->headerlength += 4;

        }



        if (ape->formatflags & MAC_FORMAT_FLAG_HAS_SEEK_ELEMENTS) {

            ape->seektablelength = avio_rl32(pb);

            ape->headerlength += 4;

            ape->seektablelength *= sizeof(int32_t);

        } else

            ape->seektablelength = ape->totalframes * sizeof(int32_t);



        if (ape->formatflags & MAC_FORMAT_FLAG_8_BIT)

            ape->bps = 8;

        else if (ape->formatflags & MAC_FORMAT_FLAG_24_BIT)

            ape->bps = 24;

        else

            ape->bps = 16;



        if (ape->fileversion >= 3950)

            ape->blocksperframe = 73728 * 4;

        else if (ape->fileversion >= 3900 || (ape->fileversion >= 3800  && ape->compressiontype >= 4000))

            ape->blocksperframe = 73728;

        else

            ape->blocksperframe = 9216;



        /* Skip any stored wav header */

        if (!(ape->formatflags & MAC_FORMAT_FLAG_CREATE_WAV_HEADER))

            avio_skip(pb, ape->wavheaderlength);

    }



    if(!ape->totalframes){

        av_log(s, AV_LOG_ERROR, "No frames in the file!\n");

        return AVERROR(EINVAL);

    }

    if(ape->totalframes > UINT_MAX / sizeof(APEFrame)){

        av_log(s, AV_LOG_ERROR, "Too many frames: %"PRIu32"\n",

               ape->totalframes);

        return -1;

    }

    if (ape->seektablelength / sizeof(*ape->seektable) < ape->totalframes) {

        av_log(s, AV_LOG_ERROR,

               "Number of seek entries is less than number of frames: %zu vs. %"PRIu32"\n",

               ape->seektablelength / sizeof(*ape->seektable), ape->totalframes);

        return AVERROR_INVALIDDATA;

    }

    ape->frames       = av_malloc(ape->totalframes * sizeof(APEFrame));

    if(!ape->frames)

        return AVERROR(ENOMEM);

    ape->firstframe   = ape->junklength + ape->descriptorlength + ape->headerlength + ape->seektablelength + ape->wavheaderlength;

    if (ape->fileversion < 3810)

        ape->firstframe += ape->totalframes;

    ape->currentframe = 0;





    ape->totalsamples = ape->finalframeblocks;

    if (ape->totalframes > 1)

        ape->totalsamples += ape->blocksperframe * (ape->totalframes - 1);



    if (ape->seektablelength > 0) {

        ape->seektable = av_malloc(ape->seektablelength);

        if (!ape->seektable)

            return AVERROR(ENOMEM);

        for (i = 0; i < ape->seektablelength / sizeof(uint32_t) && !pb->eof_reached; i++)

            ape->seektable[i] = avio_rl32(pb);

        if (ape->fileversion < 3810) {

            ape->bittable = av_malloc(ape->totalframes);

            if (!ape->bittable)

                return AVERROR(ENOMEM);

            for (i = 0; i < ape->totalframes && !pb->eof_reached; i++)

                ape->bittable[i] = avio_r8(pb);

        }

    }



    ape->frames[0].pos     = ape->firstframe;

    ape->frames[0].nblocks = ape->blocksperframe;

    ape->frames[0].skip    = 0;

    for (i = 1; i < ape->totalframes; i++) {

        ape->frames[i].pos      = ape->seektable[i] + ape->junklength;

        ape->frames[i].nblocks  = ape->blocksperframe;

        ape->frames[i - 1].size = ape->frames[i].pos - ape->frames[i - 1].pos;

        ape->frames[i].skip     = (ape->frames[i].pos - ape->frames[0].pos) & 3;

    }

    ape->frames[ape->totalframes - 1].nblocks = ape->finalframeblocks;

    /* calculate final packet size from total file size, if available */

    file_size = avio_size(pb);

    if (file_size > 0) {

        final_size = file_size - ape->frames[ape->totalframes - 1].pos -

                     ape->wavtaillength;

        final_size -= final_size & 3;

    }

    if (file_size <= 0 || final_size <= 0)

        final_size = ape->finalframeblocks * 8;

    ape->frames[ape->totalframes - 1].size = final_size;



    for (i = 0; i < ape->totalframes; i++) {

        if(ape->frames[i].skip){

            ape->frames[i].pos  -= ape->frames[i].skip;

            ape->frames[i].size += ape->frames[i].skip;

        }

        ape->frames[i].size = (ape->frames[i].size + 3) & ~3;

    }

    if (ape->fileversion < 3810) {

        for (i = 0; i < ape->totalframes; i++) {

            if (i < ape->totalframes - 1 && ape->bittable[i + 1])

                ape->frames[i].size += 4;

            ape->frames[i].skip <<= 3;

            ape->frames[i].skip  += ape->bittable[i];

        }

    }



    ape_dumpinfo(s, ape);



    av_log(s, AV_LOG_DEBUG, "Decoding file - v%d.%02d, compression level %"PRIu16"\n",

           ape->fileversion / 1000, (ape->fileversion % 1000) / 10,

           ape->compressiontype);



    /* now we are ready: build format streams */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return -1;



    total_blocks = (ape->totalframes == 0) ? 0 : ((ape->totalframes - 1) * ape->blocksperframe) + ape->finalframeblocks;



    st->codecpar->codec_type      = AVMEDIA_TYPE_AUDIO;

    st->codecpar->codec_id        = AV_CODEC_ID_APE;

    st->codecpar->codec_tag       = MKTAG('A', 'P', 'E', ' ');

    st->codecpar->channels        = ape->channels;

    st->codecpar->sample_rate     = ape->samplerate;

    st->codecpar->bits_per_coded_sample = ape->bps;



    st->nb_frames = ape->totalframes;

    st->start_time = 0;

    st->duration  = total_blocks / MAC_SUBFRAME_SIZE;

    avpriv_set_pts_info(st, 64, MAC_SUBFRAME_SIZE, ape->samplerate);



    st->codecpar->extradata = av_malloc(APE_EXTRADATA_SIZE);

    st->codecpar->extradata_size = APE_EXTRADATA_SIZE;

    AV_WL16(st->codecpar->extradata + 0, ape->fileversion);

    AV_WL16(st->codecpar->extradata + 2, ape->compressiontype);

    AV_WL16(st->codecpar->extradata + 4, ape->formatflags);



    pts = 0;

    for (i = 0; i < ape->totalframes; i++) {

        ape->frames[i].pts = pts;

        av_add_index_entry(st, ape->frames[i].pos, ape->frames[i].pts, 0, 0, AVINDEX_KEYFRAME);

        pts += ape->blocksperframe / MAC_SUBFRAME_SIZE;

    }



    /* try to read APE tags */

    if (pb->seekable) {

        ff_ape_parse_tag(s);

        avio_seek(pb, 0, SEEK_SET);

    }



    return 0;

}

void bdrv_set_aio_context(BlockDriverState *bs, AioContext *new_context)
{
    bdrv_drain(bs); /* ensure there are no in-flight requests */
    bdrv_detach_aio_context(bs);
    /* This function executes in the old AioContext so acquire the new one in
     * case it runs in a different thread.
     */
    aio_context_acquire(new_context);
    bdrv_attach_aio_context(bs, new_context);
    aio_context_release(new_context);

static void virtio_blk_handle_flush(BlockRequest *blkreq, int *num_writes,

    VirtIOBlockReq *req)

{

    BlockDriverAIOCB *acb;



    /*

     * Make sure all outstanding writes are posted to the backing device.

     */

    if (*num_writes > 0) {

        do_multiwrite(req->dev->bs, blkreq, *num_writes);

    }

    *num_writes = 0;



    acb = bdrv_aio_flush(req->dev->bs, virtio_blk_flush_complete, req);

    if (!acb) {

        virtio_blk_req_complete(req, VIRTIO_BLK_S_IOERR);

    }

}

