                                             st->codec->flags & CODEC_FLAG_BITEXACT,

                                             &s->metadata);

            if (err) {

                av_log(s, AV_LOG_ERROR, "Error writing Opus headers\n");

                av_freep(&st->priv_data);

                return err;

            }

        } else {

            uint8_t *p;

            const char *cstr = st->codec->codec_id == AV_CODEC_ID_VORBIS ? "vorbis" : "theora";

            int header_type = st->codec->codec_id == AV_CODEC_ID_VORBIS ? 3 : 0x81;

            int framing_bit = st->codec->codec_id == AV_CODEC_ID_VORBIS ? 1 : 0;



            if (avpriv_split_xiph_headers(st->codec->extradata, st->codec->extradata_size,

                                      st->codec->codec_id == AV_CODEC_ID_VORBIS ? 30 : 42,

                                      oggstream->header, oggstream->header_len) < 0) {

                av_log(s, AV_LOG_ERROR, "Extradata corrupted\n");

                av_freep(&st->priv_data);

                return -1;

            }



            p = ogg_write_vorbiscomment(7, st->codec->flags & CODEC_FLAG_BITEXACT,

                                        &oggstream->header_len[1], &s->metadata,

                                        framing_bit);

            oggstream->header[1] = p;

            if (!p)

                return AVERROR(ENOMEM);



            bytestream_put_byte(&p, header_type);

            bytestream_put_buffer(&p, cstr, 6);



            if (st->codec->codec_id == AV_CODEC_ID_THEORA) {

                /** KFGSHIFT is the width of the less significant section of the granule position

                    The less significant section is the frame count since the last keyframe */

                oggstream->kfgshift = ((oggstream->header[0][40]&3)<<3)|(oggstream->header[0][41]>>5);

                oggstream->vrev = oggstream->header[0][9];

                av_log(s, AV_LOG_DEBUG, "theora kfgshift %d, vrev %d\n",

                       oggstream->kfgshift, oggstream->vrev);

            }

        }

    }



    for (j = 0; j < s->nb_streams; j++) {

        OGGStreamContext *oggstream = s->streams[j]->priv_data;

        ogg_buffer_data(s, s->streams[j], oggstream->header[0],

                        oggstream->header_len[0], 0, 1);

        oggstream->page.flags |= 2; // bos

        ogg_buffer_page(s, oggstream);

    }

    for (j = 0; j < s->nb_streams; j++) {

        AVStream *st = s->streams[j];

        OGGStreamContext *oggstream = st->priv_data;

        for (i = 1; i < 3; i++) {

            if (oggstream && oggstream->header_len[i])

                ogg_buffer_data(s, st, oggstream->header[i],

                                oggstream->header_len[i], 0, 1);

        }

        ogg_buffer_page(s, oggstream);

    }

    return 0;

}

int av_find_best_stream(AVFormatContext *ic, enum AVMediaType type,

                        int wanted_stream_nb, int related_stream,

                        AVCodec **decoder_ret, int flags)

{

    int i, nb_streams = ic->nb_streams;

    int ret = AVERROR_STREAM_NOT_FOUND, best_count = -1, best_bitrate = -1, best_multiframe = -1, count, bitrate, multiframe;

    unsigned *program = NULL;

    const AVCodec *decoder = NULL, *best_decoder = NULL;



    if (related_stream >= 0 && wanted_stream_nb < 0) {

        AVProgram *p = av_find_program_from_stream(ic, NULL, related_stream);

        if (p) {

            program    = p->stream_index;

            nb_streams = p->nb_stream_indexes;

        }

    }

    for (i = 0; i < nb_streams; i++) {

        int real_stream_index = program ? program[i] : i;

        AVStream *st          = ic->streams[real_stream_index];

        AVCodecContext *avctx = st->codec;

        if (avctx->codec_type != type)

            continue;

        if (wanted_stream_nb >= 0 && real_stream_index != wanted_stream_nb)

            continue;

        if (wanted_stream_nb != real_stream_index &&

            st->disposition & (AV_DISPOSITION_HEARING_IMPAIRED |

                               AV_DISPOSITION_VISUAL_IMPAIRED))

            continue;

        if (type == AVMEDIA_TYPE_AUDIO && !avctx->channels)

            continue;

        if (decoder_ret) {

            decoder = find_decoder(ic, st, st->codec->codec_id);

            if (!decoder) {

                if (ret < 0)

                    ret = AVERROR_DECODER_NOT_FOUND;

                continue;

            }

        }

        count = st->codec_info_nb_frames;

        bitrate = avctx->bit_rate;

        if (!bitrate)

            bitrate = avctx->rc_max_rate;

        multiframe = FFMIN(5, count);

        if ((best_multiframe >  multiframe) ||

            (best_multiframe == multiframe && best_bitrate >  bitrate) ||

            (best_multiframe == multiframe && best_bitrate == bitrate && best_count >= count))

            continue;

        best_count   = count;

        best_bitrate = bitrate;

        best_multiframe = multiframe;

        ret          = real_stream_index;

        best_decoder = decoder;

        if (program && i == nb_streams - 1 && ret < 0) {

            program    = NULL;

            nb_streams = ic->nb_streams;

            /* no related stream found, try again with everything */

            i = 0;

        }

    }

    if (decoder_ret)

        *decoder_ret = (AVCodec*)best_decoder;

    return ret;

}

void ff_mpeg4_encode_picture_header(MpegEncContext *s, int picture_number)

{

    int time_incr;

    int time_div, time_mod;



    if (s->pict_type == AV_PICTURE_TYPE_I) {

        if (!(s->avctx->flags & AV_CODEC_FLAG_GLOBAL_HEADER)) {

            if (s->strict_std_compliance < FF_COMPLIANCE_VERY_STRICT)  // HACK, the reference sw is buggy

                mpeg4_encode_visual_object_header(s);

            if (s->strict_std_compliance < FF_COMPLIANCE_VERY_STRICT || picture_number == 0)  // HACK, the reference sw is buggy

                mpeg4_encode_vol_header(s, 0, 0);

        }

        if (!(s->workaround_bugs & FF_BUG_MS))

            mpeg4_encode_gop_header(s);

    }



    s->partitioned_frame = s->data_partitioning && s->pict_type != AV_PICTURE_TYPE_B;



    put_bits(&s->pb, 16, 0);                /* vop header */

    put_bits(&s->pb, 16, VOP_STARTCODE);    /* vop header */

    put_bits(&s->pb, 2, s->pict_type - 1);  /* pict type: I = 0 , P = 1 */



    time_div  = FFUDIV(s->time, s->avctx->time_base.den);

    time_mod  = FFUMOD(s->time, s->avctx->time_base.den);

    time_incr = time_div - s->last_time_base;

    av_assert0(time_incr >= 0);

    while (time_incr--)

        put_bits(&s->pb, 1, 1);



    put_bits(&s->pb, 1, 0);



    put_bits(&s->pb, 1, 1);                             /* marker */

    put_bits(&s->pb, s->time_increment_bits, time_mod); /* time increment */

    put_bits(&s->pb, 1, 1);                             /* marker */

    put_bits(&s->pb, 1, 1);                             /* vop coded */

    if (s->pict_type == AV_PICTURE_TYPE_P) {

        put_bits(&s->pb, 1, s->no_rounding);    /* rounding type */

    }

    put_bits(&s->pb, 3, 0);     /* intra dc VLC threshold */

    if (!s->progressive_sequence) {

        put_bits(&s->pb, 1, s->current_picture_ptr->f->top_field_first);

        put_bits(&s->pb, 1, s->alternate_scan);

    }

    // FIXME sprite stuff



    put_bits(&s->pb, 5, s->qscale);



    if (s->pict_type != AV_PICTURE_TYPE_I)

        put_bits(&s->pb, 3, s->f_code);  /* fcode_for */

    if (s->pict_type == AV_PICTURE_TYPE_B)

        put_bits(&s->pb, 3, s->b_code);  /* fcode_back */

}

static void mpeg4_encode_vol_header(MpegEncContext * s, int vo_number, int vol_number)

{

    int vo_ver_id;



    if(s->max_b_frames || s->quarter_sample){

        vo_ver_id= 5;

        s->vo_type= ADV_SIMPLE_VO_TYPE;

    }else{

        vo_ver_id= 1;

        s->vo_type= SIMPLE_VO_TYPE;

    }



    put_bits(&s->pb, 16, 0);

    put_bits(&s->pb, 16, 0x100 + vo_number);        /* video obj */

    put_bits(&s->pb, 16, 0);

    put_bits(&s->pb, 16, 0x120 + vol_number);       /* video obj layer */



    put_bits(&s->pb, 1, 0);		/* random access vol */

    put_bits(&s->pb, 8, s->vo_type);	/* video obj type indication */

    put_bits(&s->pb, 1, 1);		/* is obj layer id= yes */

      put_bits(&s->pb, 4, vo_ver_id);	/* is obj layer ver id */

      put_bits(&s->pb, 3, 1);		/* is obj layer priority */



    aspect_to_info(s, s->avctx->sample_aspect_ratio);



    put_bits(&s->pb, 4, s->aspect_ratio_info);/* aspect ratio info */

    if (s->aspect_ratio_info == FF_ASPECT_EXTENDED){

        put_bits(&s->pb, 8, s->avctx->sample_aspect_ratio.num);

        put_bits(&s->pb, 8, s->avctx->sample_aspect_ratio.den);

    }



    if(s->low_delay){

        put_bits(&s->pb, 1, 1);		/* vol control parameters= yes */

        put_bits(&s->pb, 2, 1);		/* chroma format YUV 420/YV12 */

        put_bits(&s->pb, 1, s->low_delay);

        put_bits(&s->pb, 1, 0);		/* vbv parameters= no */

    }else{

        put_bits(&s->pb, 1, 0);		/* vol control parameters= no */

    }



    put_bits(&s->pb, 2, RECT_SHAPE);	/* vol shape= rectangle */

    put_bits(&s->pb, 1, 1);		/* marker bit */



    put_bits(&s->pb, 16, s->time_increment_resolution);

    if (s->time_increment_bits < 1)

        s->time_increment_bits = 1;

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 1, 0);		/* fixed vop rate=no */

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 13, s->width);	/* vol width */

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 13, s->height);	/* vol height */

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 1, s->progressive_sequence ? 0 : 1);

    put_bits(&s->pb, 1, 1);		/* obmc disable */

    if (vo_ver_id == 1) {

        put_bits(&s->pb, 1, s->vol_sprite_usage=0);		/* sprite enable */

    }else{

        put_bits(&s->pb, 2, s->vol_sprite_usage=0);		/* sprite enable */

    }



    s->quant_precision=5;

    put_bits(&s->pb, 1, 0);		/* not 8 bit == false */

    put_bits(&s->pb, 1, s->mpeg_quant);	/* quant type= (0=h263 style)*/



    if(s->mpeg_quant){

        ff_write_quant_matrix(&s->pb, s->avctx->intra_matrix);

        ff_write_quant_matrix(&s->pb, s->avctx->inter_matrix);

    }



    if (vo_ver_id != 1)

        put_bits(&s->pb, 1, s->quarter_sample);

    put_bits(&s->pb, 1, 1);		/* complexity estimation disable */

    s->resync_marker= s->rtp_mode;

    put_bits(&s->pb, 1, s->resync_marker ? 0 : 1);/* resync marker disable */

    put_bits(&s->pb, 1, s->data_partitioning ? 1 : 0);

    if(s->data_partitioning){

        put_bits(&s->pb, 1, 0);		/* no rvlc */

    }



    if (vo_ver_id != 1){

        put_bits(&s->pb, 1, 0);		/* newpred */

        put_bits(&s->pb, 1, 0);		/* reduced res vop */

    }

    put_bits(&s->pb, 1, 0);		/* scalability */



    ff_mpeg4_stuffing(&s->pb);



    /* user data */

    if(!(s->flags & CODEC_FLAG_BITEXACT)){

        put_bits(&s->pb, 16, 0);

        put_bits(&s->pb, 16, 0x1B2);	/* user_data */

	put_string(&s->pb, LIBAVCODEC_IDENT);

        ff_mpeg4_stuffing(&s->pb);

    }

}

void ff_rv10_encode_picture_header(MpegEncContext *s, int picture_number)

{

    int full_frame= 0;



    avpriv_align_put_bits(&s->pb);



    put_bits(&s->pb, 1, 1);     /* marker */



    put_bits(&s->pb, 1, (s->pict_type == AV_PICTURE_TYPE_P));



    put_bits(&s->pb, 1, 0);     /* not PB frame */



    put_bits(&s->pb, 5, s->qscale);



    if (s->pict_type == AV_PICTURE_TYPE_I) {

        /* specific MPEG like DC coding not used */

    }

    /* if multiple packets per frame are sent, the position at which

       to display the macroblocks is coded here */

    if(!full_frame){

        put_bits(&s->pb, 6, 0); /* mb_x */

        put_bits(&s->pb, 6, 0); /* mb_y */

        put_bits(&s->pb, 12, s->mb_width * s->mb_height);

    }



    put_bits(&s->pb, 3, 0);     /* ignored */

}

void mpeg1_encode_picture_header(MpegEncContext *s, int picture_number)

{

    mpeg1_encode_sequence_header(s);



    /* mpeg1 picture header */

    put_header(s, PICTURE_START_CODE);

    /* temporal reference */



    // RAL: s->picture_number instead of s->fake_picture_number

    put_bits(&s->pb, 10, (s->picture_number - 

                          s->gop_picture_number) & 0x3ff); 

    s->fake_picture_number++;



    put_bits(&s->pb, 3, s->pict_type);



    s->vbv_delay_ptr= s->pb.buf + get_bit_count(&s->pb)/8;

    put_bits(&s->pb, 16, 0xFFFF); /* vbv_delay */



    // RAL: Forward f_code also needed for B frames

    if (s->pict_type == P_TYPE || s->pict_type == B_TYPE) {

        put_bits(&s->pb, 1, 0); /* half pel coordinates */

        if(s->codec_id == CODEC_ID_MPEG1VIDEO)

            put_bits(&s->pb, 3, s->f_code); /* forward_f_code */

        else

            put_bits(&s->pb, 3, 7); /* forward_f_code */

    }



    // RAL: Backward f_code necessary for B frames

    if (s->pict_type == B_TYPE) {

        put_bits(&s->pb, 1, 0); /* half pel coordinates */

        if(s->codec_id == CODEC_ID_MPEG1VIDEO)

            put_bits(&s->pb, 3, s->b_code); /* backward_f_code */

        else

            put_bits(&s->pb, 3, 7); /* backward_f_code */

    }



    put_bits(&s->pb, 1, 0); /* extra bit picture */



    s->frame_pred_frame_dct = 1;

    if(s->codec_id == CODEC_ID_MPEG2VIDEO){

        put_header(s, EXT_START_CODE);

        put_bits(&s->pb, 4, 8); //pic ext

        if (s->pict_type == P_TYPE || s->pict_type == B_TYPE) {

            put_bits(&s->pb, 4, s->f_code);

            put_bits(&s->pb, 4, s->f_code);

        }else{

            put_bits(&s->pb, 8, 255);

        }

        if (s->pict_type == B_TYPE) {

            put_bits(&s->pb, 4, s->b_code);

            put_bits(&s->pb, 4, s->b_code);

        }else{

            put_bits(&s->pb, 8, 255);

        }

        put_bits(&s->pb, 2, s->intra_dc_precision);

        put_bits(&s->pb, 2, s->picture_structure= PICT_FRAME);

        if (s->progressive_sequence) {

            put_bits(&s->pb, 1, 0); /* no repeat */

        } else {

            put_bits(&s->pb, 1, s->current_picture_ptr->top_field_first);

        }

        /* XXX: optimize the generation of this flag with entropy

           measures */

        s->frame_pred_frame_dct = s->progressive_sequence;



        put_bits(&s->pb, 1, s->frame_pred_frame_dct);

        put_bits(&s->pb, 1, s->concealment_motion_vectors);

        put_bits(&s->pb, 1, s->q_scale_type);

        put_bits(&s->pb, 1, s->intra_vlc_format);

        put_bits(&s->pb, 1, s->alternate_scan);

        put_bits(&s->pb, 1, s->repeat_first_field);

        put_bits(&s->pb, 1, s->chroma_420_type=1);

        s->progressive_frame = s->progressive_sequence;

        put_bits(&s->pb, 1, s->progressive_frame);

        put_bits(&s->pb, 1, 0); //composite_display_flag

    }

    if(s->flags & CODEC_FLAG_SVCD_SCAN_OFFSET){

        int i;



        put_header(s, USER_START_CODE);

        for(i=0; i<sizeof(svcd_scan_offset_placeholder); i++){

            put_bits(&s->pb, 8, svcd_scan_offset_placeholder[i]);

        }

    }



    s->mb_y=0;

    ff_mpeg1_encode_slice_header(s);

}

