static void rv34_idct_add_c(uint8_t *dst, ptrdiff_t stride, DCTELEM *block){

    int      temp[16];

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;

    int      i;



    rv34_row_transform(temp, block);

    memset(block, 0, 16*sizeof(DCTELEM));



    for(i = 0; i < 4; i++){

        const int z0 = 13*(temp[4*0+i] +    temp[4*2+i]) + 0x200;

        const int z1 = 13*(temp[4*0+i] -    temp[4*2+i]) + 0x200;

        const int z2 =  7* temp[4*1+i] - 17*temp[4*3+i];

        const int z3 = 17* temp[4*1+i] +  7*temp[4*3+i];



        dst[0] = cm[ dst[0] + ( (z0 + z3) >> 10 ) ];

        dst[1] = cm[ dst[1] + ( (z1 + z2) >> 10 ) ];

        dst[2] = cm[ dst[2] + ( (z1 - z2) >> 10 ) ];

        dst[3] = cm[ dst[3] + ( (z0 - z3) >> 10 ) ];



        dst  += stride;

    }

}

static void init_coef_vlc(VLC *vlc, 

                          uint16_t **prun_table, uint16_t **plevel_table,

                          const CoefVLCTable *vlc_table)

{

    int n = vlc_table->n;

    const uint8_t *table_bits = vlc_table->huffbits;

    const uint32_t *table_codes = vlc_table->huffcodes;

    const uint16_t *levels_table = vlc_table->levels;

    uint16_t *run_table, *level_table;

    const uint16_t *p;

    int i, l, j, level;



    init_vlc(vlc, 9, n, table_bits, 1, 1, table_codes, 4, 4);



    run_table = av_malloc(n * sizeof(uint16_t));

    level_table = av_malloc(n * sizeof(uint16_t));

    p = levels_table;

    i = 2;

    level = 1;

    while (i < n) {

        l = *p++;

        for(j=0;j<l;j++) {

            run_table[i] = j;

            level_table[i] = level;

            i++;

        }

        level++;

    }

    *prun_table = run_table;

    *plevel_table = level_table;

}

static void thread_pool_cancel(BlockDriverAIOCB *acb)

{

    ThreadPoolElement *elem = (ThreadPoolElement *)acb;

    ThreadPool *pool = elem->pool;



    trace_thread_pool_cancel(elem, elem->common.opaque);



    qemu_mutex_lock(&pool->lock);

    if (elem->state == THREAD_QUEUED &&

        /* No thread has yet started working on elem. we can try to "steal"

         * the item from the worker if we can get a signal from the

         * semaphore.  Because this is non-blocking, we can do it with

         * the lock taken and ensure that elem will remain THREAD_QUEUED.

         */

        qemu_sem_timedwait(&pool->sem, 0) == 0) {

        QTAILQ_REMOVE(&pool->request_list, elem, reqs);

        elem->state = THREAD_CANCELED;

        event_notifier_set(&pool->notifier);

    } else {

        pool->pending_cancellations++;

        while (elem->state != THREAD_CANCELED && elem->state != THREAD_DONE) {

            qemu_cond_wait(&pool->check_cancel, &pool->lock);

        }

        pool->pending_cancellations--;

    }

    qemu_mutex_unlock(&pool->lock);


}

static void coroutine_delete(Coroutine *co)

{

    if (CONFIG_COROUTINE_POOL) {

        qemu_mutex_lock(&pool_lock);

        if (pool_size < pool_max_size) {

            QSLIST_INSERT_HEAD(&pool, co, pool_next);

            co->caller = NULL;

            pool_size++;

            qemu_mutex_unlock(&pool_lock);

            return;

        }

        qemu_mutex_unlock(&pool_lock);

    }



    qemu_coroutine_delete(co);

}

