        ret = 1;

    }



    return ret;

}

static void spatial_compose53i_dy(dwt_compose_t *cs, DWTELEM *buffer, int width, int height, int stride){

    int y= cs->y;

    DWTELEM *b0= cs->b0;

    DWTELEM *b1= cs->b1;

    DWTELEM *b2= buffer + mirror(y+1, height-1)*stride;

    DWTELEM *b3= buffer + mirror(y+2, height-1)*stride;



{START_TIMER

        if(b1 <= b3) vertical_compose53iL0(b1, b2, b3, width);

        if(b0 <= b2) vertical_compose53iH0(b0, b1, b2, width);

STOP_TIMER("vertical_compose53i*")}



{START_TIMER

        if(y-1 >= 0) horizontal_compose53i(b0, width);

        if(b0 <= b2) horizontal_compose53i(b1, width);

STOP_TIMER("horizontal_compose53i")}



    cs->b0 = b2;

    cs->b1 = b3;

    cs->y += 2;

}

static void spatial_decompose97i(DWTELEM *buffer, int width, int height, int stride){

    int y;

    DWTELEM *b0= buffer + mirror(-4-1, height-1)*stride;

    DWTELEM *b1= buffer + mirror(-4  , height-1)*stride;

    DWTELEM *b2= buffer + mirror(-4+1, height-1)*stride;

    DWTELEM *b3= buffer + mirror(-4+2, height-1)*stride;



    for(y=-4; y<height; y+=2){

        DWTELEM *b4= buffer + mirror(y+3, height-1)*stride;

        DWTELEM *b5= buffer + mirror(y+4, height-1)*stride;



{START_TIMER

        if(b3 <= b5)     horizontal_decompose97i(b4, width);

        if(y+4 < height) horizontal_decompose97i(b5, width);

if(width>400){

STOP_TIMER("horizontal_decompose97i")

}}



{START_TIMER

        if(b3 <= b5) vertical_decompose97iH0(b3, b4, b5, width);

        if(b2 <= b4) vertical_decompose97iL0(b2, b3, b4, width);

        if(b1 <= b3) vertical_decompose97iH1(b1, b2, b3, width);

        if(b0 <= b2) vertical_decompose97iL1(b0, b1, b2, width);



if(width>400){

STOP_TIMER("vertical_decompose97i")

}}



        b0=b2;

        b1=b3;

        b2=b4;

        b3=b5;

    }

}

static void spatial_compose97i_dy(dwt_compose_t *cs, DWTELEM *buffer, int width, int height, int stride){

    int y = cs->y;

    DWTELEM *b0= cs->b0;

    DWTELEM *b1= cs->b1;

    DWTELEM *b2= cs->b2;

    DWTELEM *b3= cs->b3;

    DWTELEM *b4= buffer + mirror(y+3, height-1)*stride;

    DWTELEM *b5= buffer + mirror(y+4, height-1)*stride;



        if(stride == width && y+4 < height && 0){

            int x;

            for(x=0; x<width/2; x++)

                b5[x] += 64*2;

            for(; x<width; x++)

                b5[x] += 169*2;

        }



{START_TIMER

        if(b3 <= b5) vertical_compose97iL1(b3, b4, b5, width);

        if(b2 <= b4) vertical_compose97iH1(b2, b3, b4, width);

        if(b1 <= b3) vertical_compose97iL0(b1, b2, b3, width);

        if(b0 <= b2) vertical_compose97iH0(b0, b1, b2, width);

if(width>400){

STOP_TIMER("vertical_compose97i")}}



{START_TIMER

        if(y-1>=  0) horizontal_compose97i(b0, width);

        if(b0 <= b2) horizontal_compose97i(b1, width);

if(width>400 && b0 <= b2){

STOP_TIMER("horizontal_compose97i")}}



    cs->b0=b2;

    cs->b1=b3;

    cs->b2=b4;

    cs->b3=b5;

    cs->y += 2;

}

static void spatial_compose53i_dy_buffered(dwt_compose_t *cs, slice_buffer * sb, int width, int height, int stride_line){

    int y= cs->y;

    int mirror0 = mirror(y-1, height-1);

    int mirror1 = mirror(y  , height-1);

    int mirror2 = mirror(y+1, height-1);

    int mirror3 = mirror(y+2, height-1);



    DWTELEM *b0= cs->b0;

    DWTELEM *b1= cs->b1;

    DWTELEM *b2= slice_buffer_get_line(sb, mirror2 * stride_line);

    DWTELEM *b3= slice_buffer_get_line(sb, mirror3 * stride_line);



{START_TIMER

        if(mirror1 <= mirror3) vertical_compose53iL0(b1, b2, b3, width);

        if(mirror0 <= mirror2) vertical_compose53iH0(b0, b1, b2, width);

STOP_TIMER("vertical_compose53i*")}



{START_TIMER

        if(y-1 >= 0) horizontal_compose53i(b0, width);

        if(mirror0 <= mirror2) horizontal_compose53i(b1, width);

STOP_TIMER("horizontal_compose53i")}



    cs->b0 = b2;

    cs->b1 = b3;

    cs->y += 2;

}

static int sd_snapshot_create(BlockDriverState *bs, QEMUSnapshotInfo *sn_info)

{

    Error *local_err = NULL;

    BDRVSheepdogState *s = bs->opaque;

    int ret, fd;

    uint32_t new_vid;

    SheepdogInode *inode;

    unsigned int datalen;



    DPRINTF("sn_info: name %s id_str %s s: name %s vm_state_size %" PRId64 " "

            "is_snapshot %d\n", sn_info->name, sn_info->id_str,

            s->name, sn_info->vm_state_size, s->is_snapshot);



    if (s->is_snapshot) {

        error_report("You can't create a snapshot of a snapshot VDI, "

                     "%s (%" PRIu32 ").", s->name, s->inode.vdi_id);



        return -EINVAL;

    }



    DPRINTF("%s %s\n", sn_info->name, sn_info->id_str);



    s->inode.vm_state_size = sn_info->vm_state_size;

    s->inode.vm_clock_nsec = sn_info->vm_clock_nsec;

    /* It appears that inode.tag does not require a NUL terminator,

     * which means this use of strncpy is ok.

     */

    strncpy(s->inode.tag, sn_info->name, sizeof(s->inode.tag));

    /* we don't need to update entire object */

    datalen = SD_INODE_SIZE - sizeof(s->inode.data_vdi_id);



    /* refresh inode. */

    fd = connect_to_sdog(s, &local_err);

    if (fd < 0) {

        error_report("%s", error_get_pretty(local_err));;

        error_free(local_err);

        ret = fd;

        goto cleanup;

    }



    ret = write_object(fd, (char *)&s->inode, vid_to_vdi_oid(s->inode.vdi_id),

                       s->inode.nr_copies, datalen, 0, false, s->cache_flags);

    if (ret < 0) {

        error_report("failed to write snapshot's inode.");

        goto cleanup;

    }



    ret = do_sd_create(s, &new_vid, 1, &local_err);

    if (ret < 0) {

        error_report("%s", error_get_pretty(local_err));;

        error_free(local_err);

        error_report("failed to create inode for snapshot. %s",

                     strerror(errno));

        goto cleanup;

    }



    inode = (SheepdogInode *)g_malloc(datalen);



    ret = read_object(fd, (char *)inode, vid_to_vdi_oid(new_vid),

                      s->inode.nr_copies, datalen, 0, s->cache_flags);



    if (ret < 0) {

        error_report("failed to read new inode info. %s", strerror(errno));

        goto cleanup;

    }



    memcpy(&s->inode, inode, datalen);

    DPRINTF("s->inode: name %s snap_id %x oid %x\n",

            s->inode.name, s->inode.snap_id, s->inode.vdi_id);



cleanup:

    closesocket(fd);

    return ret;

}

static bool remove_objects(BDRVSheepdogState *s)

{

    int fd, i = 0, nr_objs = 0;

    Error *local_err = NULL;

    int ret = 0;

    bool result = true;

    SheepdogInode *inode = &s->inode;



    fd = connect_to_sdog(s, &local_err);

    if (fd < 0) {

        error_report_err(local_err);

        return false;

    }



    nr_objs = count_data_objs(inode);

    while (i < nr_objs) {

        int start_idx, nr_filled_idx;



        while (i < nr_objs && !inode->data_vdi_id[i]) {

            i++;

        }

        start_idx = i;



        nr_filled_idx = 0;

        while (i < nr_objs && nr_filled_idx < NR_BATCHED_DISCARD) {

            if (inode->data_vdi_id[i]) {

                inode->data_vdi_id[i] = 0;

                nr_filled_idx++;

            }



            i++;

        }



        ret = write_object(fd, s->bs,

                           (char *)&inode->data_vdi_id[start_idx],

                           vid_to_vdi_oid(s->inode.vdi_id), inode->nr_copies,

                           (i - start_idx) * sizeof(uint32_t),

                           offsetof(struct SheepdogInode,

                                    data_vdi_id[start_idx]),

                           false, s->cache_flags);

        if (ret < 0) {

            error_report("failed to discard snapshot inode.");

            result = false;

            goto out;

        }

    }



out:

    closesocket(fd);

    return result;

}

static int sd_snapshot_goto(BlockDriverState *bs, const char *snapshot_id)

{

    BDRVSheepdogState *s = bs->opaque;

    BDRVSheepdogState *old_s;

    char vdi[SD_MAX_VDI_LEN], tag[SD_MAX_VDI_TAG_LEN];

    char *buf = NULL;

    uint32_t vid;

    uint32_t snapid = 0;

    int ret = 0, fd;



    old_s = g_malloc(sizeof(BDRVSheepdogState));



    memcpy(old_s, s, sizeof(BDRVSheepdogState));



    pstrcpy(vdi, sizeof(vdi), s->name);



    snapid = strtoul(snapshot_id, NULL, 10);

    if (snapid) {

        tag[0] = 0;

    } else {

        pstrcpy(tag, sizeof(tag), s->name);

    }



    ret = find_vdi_name(s, vdi, snapid, tag, &vid, 1);

    if (ret) {

        error_report("Failed to find_vdi_name");

        goto out;

    }



    fd = connect_to_sdog(s->addr, s->port);

    if (fd < 0) {

        error_report("failed to connect");

        ret = fd;

        goto out;

    }



    buf = g_malloc(SD_INODE_SIZE);

    ret = read_object(fd, buf, vid_to_vdi_oid(vid), s->inode.nr_copies,

                      SD_INODE_SIZE, 0, s->cache_enabled);



    closesocket(fd);



    if (ret) {

        goto out;

    }



    memcpy(&s->inode, buf, sizeof(s->inode));



    if (!s->inode.vm_state_size) {

        error_report("Invalid snapshot");

        ret = -ENOENT;

        goto out;

    }



    s->is_snapshot = true;



    g_free(buf);

    g_free(old_s);



    return 0;

out:

    /* recover bdrv_sd_state */

    memcpy(s, old_s, sizeof(BDRVSheepdogState));

    g_free(buf);

    g_free(old_s);



    error_report("failed to open. recover old bdrv_sd_state.");



    return ret;

}

static int qcow2_truncate(BlockDriverState *bs, int64_t offset)

{

    BDRVQcowState *s = bs->opaque;

    int ret, new_l1_size;



    if (offset & 511) {

        return -EINVAL;

    }



    /* cannot proceed if image has snapshots */

    if (s->nb_snapshots) {

        return -ENOTSUP;

    }



    /* shrinking is currently not supported */

    if (offset < bs->total_sectors * 512) {

        return -ENOTSUP;

    }



    new_l1_size = size_to_l1(s, offset);

    ret = qcow2_grow_l1_table(bs, new_l1_size);

    if (ret < 0) {

        return ret;

    }



    /* write updated header.size */

    offset = cpu_to_be64(offset);

    ret = bdrv_pwrite(bs->file, offsetof(QCowHeader, size),

                      &offset, sizeof(uint64_t));

    if (ret < 0) {

        return ret;

    }



    s->l1_vm_state_index = new_l1_size;

    return 0;

}

static int rndis_query_response(USBNetState *s,

                rndis_query_msg_type *buf, unsigned int length)

{

    rndis_query_cmplt_type *resp;

    /* oid_supported_list is the largest data reply */

    uint8_t infobuf[sizeof(oid_supported_list)];

    uint32_t bufoffs, buflen;

    int infobuflen;

    unsigned int resplen;



    bufoffs = le32_to_cpu(buf->InformationBufferOffset) + 8;

    buflen = le32_to_cpu(buf->InformationBufferLength);

    if (bufoffs + buflen > length)

        return USB_RET_STALL;



    infobuflen = ndis_query(s, le32_to_cpu(buf->OID),

                            bufoffs + (uint8_t *) buf, buflen, infobuf,

                            sizeof(infobuf));

    resplen = sizeof(rndis_query_cmplt_type) +

            ((infobuflen < 0) ? 0 : infobuflen);

    resp = rndis_queue_response(s, resplen);

    if (!resp)

        return USB_RET_STALL;



    resp->MessageType = cpu_to_le32(RNDIS_QUERY_CMPLT);

    resp->RequestID = buf->RequestID; /* Still LE in msg buffer */

    resp->MessageLength = cpu_to_le32(resplen);



    if (infobuflen < 0) {

        /* OID not supported */

        resp->Status = cpu_to_le32(RNDIS_STATUS_NOT_SUPPORTED);

        resp->InformationBufferLength = cpu_to_le32(0);

        resp->InformationBufferOffset = cpu_to_le32(0);

        return 0;

    }



    resp->Status = cpu_to_le32(RNDIS_STATUS_SUCCESS);

    resp->InformationBufferOffset =

            cpu_to_le32(infobuflen ? sizeof(rndis_query_cmplt_type) - 8 : 0);

    resp->InformationBufferLength = cpu_to_le32(infobuflen);

    memcpy(resp + 1, infobuf, infobuflen);



    return 0;

}

static int usb_wacom_handle_data(USBDevice *dev, USBPacket *p)

{

    USBWacomState *s = (USBWacomState *) dev;

    int ret = 0;



    switch (p->pid) {

    case USB_TOKEN_IN:

        if (p->devep == 1) {

            if (!(s->changed || s->idle))

                return USB_RET_NAK;

            s->changed = 0;

            if (s->mode == WACOM_MODE_HID)

                ret = usb_mouse_poll(s, p->data, p->len);

            else if (s->mode == WACOM_MODE_WACOM)

                ret = usb_wacom_poll(s, p->data, p->len);

            break;

        }

        /* Fall through.  */

    case USB_TOKEN_OUT:

    default:

        ret = USB_RET_STALL;

        break;

    }

    return ret;

}

static int usb_msd_handle_control(USBDevice *dev, int request, int value,

                                  int index, int length, uint8_t *data)

{

    MSDState *s = (MSDState *)dev;

    int ret;



    ret = usb_desc_handle_control(dev, request, value, index, length, data);

    if (ret >= 0) {

        return ret;

    }



    ret = 0;

    switch (request) {

    case DeviceRequest | USB_REQ_GET_STATUS:

        data[0] = (1 << USB_DEVICE_SELF_POWERED) |

            (dev->remote_wakeup << USB_DEVICE_REMOTE_WAKEUP);

        data[1] = 0x00;

        ret = 2;

        break;

    case DeviceOutRequest | USB_REQ_CLEAR_FEATURE:

        if (value == USB_DEVICE_REMOTE_WAKEUP) {

            dev->remote_wakeup = 0;

        } else {

            goto fail;

        }

        ret = 0;

        break;

    case DeviceOutRequest | USB_REQ_SET_FEATURE:

        if (value == USB_DEVICE_REMOTE_WAKEUP) {

            dev->remote_wakeup = 1;

        } else {

            goto fail;

        }

        ret = 0;

        break;

    case DeviceRequest | USB_REQ_GET_CONFIGURATION:

        data[0] = 1;

        ret = 1;

        break;

    case DeviceOutRequest | USB_REQ_SET_CONFIGURATION:

        ret = 0;

        break;

    case DeviceRequest | USB_REQ_GET_INTERFACE:

        data[0] = 0;

        ret = 1;

        break;

    case DeviceOutRequest | USB_REQ_SET_INTERFACE:

        ret = 0;

        break;

    case EndpointOutRequest | USB_REQ_CLEAR_FEATURE:

        ret = 0;

        break;

    case InterfaceOutRequest | USB_REQ_SET_INTERFACE:

        ret = 0;

        break;

        /* Class specific requests.  */

    case ClassInterfaceOutRequest | MassStorageReset:

        /* Reset state ready for the next CBW.  */

        s->mode = USB_MSDM_CBW;

        ret = 0;

        break;

    case ClassInterfaceRequest | GetMaxLun:

        data[0] = 0;

        ret = 1;

        break;

    default:

    fail:

        ret = USB_RET_STALL;

        break;

    }

    return ret;

}

static int do_token_out(USBDevice *s, USBPacket *p)

{

    if (p->devep != 0)

        return s->info->handle_data(s, p);



    switch(s->setup_state) {

    case SETUP_STATE_ACK:

        if (s->setup_buf[0] & USB_DIR_IN) {

            s->setup_state = SETUP_STATE_IDLE;

            /* transfer OK */

        } else {

            /* ignore additional output */

        }

        return 0;



    case SETUP_STATE_DATA:

        if (!(s->setup_buf[0] & USB_DIR_IN)) {

            int len = s->setup_len - s->setup_index;

            if (len > p->len)

                len = p->len;

            memcpy(s->data_buf + s->setup_index, p->data, len);

            s->setup_index += len;

            if (s->setup_index >= s->setup_len)

                s->setup_state = SETUP_STATE_ACK;

            return len;

        }



        s->setup_state = SETUP_STATE_IDLE;

        return USB_RET_STALL;



    default:

        return USB_RET_STALL;

    }

}

static int sap_read_header(AVFormatContext *s)

{

    struct SAPState *sap = s->priv_data;

    char host[1024], path[1024], url[1024];

    uint8_t recvbuf[RTP_MAX_PACKET_LENGTH];

    int port;

    int ret, i;

    AVInputFormat* infmt;



    if (!ff_network_init())

        return AVERROR(EIO);



    av_url_split(NULL, 0, NULL, 0, host, sizeof(host), &port,

                 path, sizeof(path), s->filename);

    if (port < 0)

        port = 9875;



    if (!host[0]) {

        /* Listen for announcements on sap.mcast.net if no host was specified */

        av_strlcpy(host, "224.2.127.254", sizeof(host));

    }



    ff_url_join(url, sizeof(url), "udp", NULL, host, port, "?localport=%d",

                port);

    ret = ffurl_open(&sap->ann_fd, url, AVIO_FLAG_READ,

                     &s->interrupt_callback, NULL);

    if (ret)

        goto fail;



    while (1) {

        int addr_type, auth_len;

        int pos;



        ret = ffurl_read(sap->ann_fd, recvbuf, sizeof(recvbuf) - 1);

        if (ret == AVERROR(EAGAIN))

            continue;

        if (ret < 0)

            goto fail;

        recvbuf[ret] = '\0'; /* Null terminate for easier parsing */

        if (ret < 8) {

            av_log(s, AV_LOG_WARNING, "Received too short packet\n");

            continue;

        }



        if ((recvbuf[0] & 0xe0) != 0x20) {

            av_log(s, AV_LOG_WARNING, "Unsupported SAP version packet "

                                      "received\n");

            continue;

        }



        if (recvbuf[0] & 0x04) {

            av_log(s, AV_LOG_WARNING, "Received stream deletion "

                                      "announcement\n");

            continue;

        }

        addr_type = recvbuf[0] & 0x10;

        auth_len  = recvbuf[1];

        sap->hash = AV_RB16(&recvbuf[2]);

        pos = 4;

        if (addr_type)

            pos += 16; /* IPv6 */

        else

            pos += 4; /* IPv4 */

        pos += auth_len * 4;

        if (pos + 4 >= ret) {

            av_log(s, AV_LOG_WARNING, "Received too short packet\n");

            continue;

        }

#define MIME "application/sdp"

        if (strcmp(&recvbuf[pos], MIME) == 0) {

            pos += strlen(MIME) + 1;

        } else if (strncmp(&recvbuf[pos], "v=0\r\n", 5) == 0) {

            // Direct SDP without a mime type

        } else {

            av_log(s, AV_LOG_WARNING, "Unsupported mime type %s\n",

                                      &recvbuf[pos]);

            continue;

        }



        sap->sdp = av_strdup(&recvbuf[pos]);

        break;

    }



    av_log(s, AV_LOG_VERBOSE, "SDP:\n%s\n", sap->sdp);

    ffio_init_context(&sap->sdp_pb, sap->sdp, strlen(sap->sdp), 0, NULL, NULL,

                  NULL, NULL);



    infmt = av_find_input_format("sdp");

    if (!infmt)

        goto fail;

    sap->sdp_ctx = avformat_alloc_context();

    if (!sap->sdp_ctx) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }

    sap->sdp_ctx->max_delay = s->max_delay;

    sap->sdp_ctx->pb        = &sap->sdp_pb;

    sap->sdp_ctx->interrupt_callback = s->interrupt_callback;



    av_assert0(!sap->sdp_ctx->codec_whitelist && !sap->sdp_ctx->format_whitelist);

    sap->sdp_ctx-> codec_whitelist = av_strdup(s->codec_whitelist);

    sap->sdp_ctx->format_whitelist = av_strdup(s->format_whitelist);



    ret = avformat_open_input(&sap->sdp_ctx, "temp.sdp", infmt, NULL);

    if (ret < 0)

        goto fail;

    if (sap->sdp_ctx->ctx_flags & AVFMTCTX_NOHEADER)

        s->ctx_flags |= AVFMTCTX_NOHEADER;

    for (i = 0; i < sap->sdp_ctx->nb_streams; i++) {

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        st->id = i;

        avcodec_copy_context(st->codec, sap->sdp_ctx->streams[i]->codec);

        st->time_base = sap->sdp_ctx->streams[i]->time_base;

    }



    return 0;



fail:

    sap_read_close(s);

    return ret;

}

int ff_rtsp_connect(AVFormatContext *s)

{

    RTSPState *rt = s->priv_data;

    char host[1024], path[1024], tcpname[1024], cmd[2048], auth[128];

    char *option_list, *option, *filename;

    URLContext *rtsp_hd, *rtsp_hd_out;

    int port, err, tcp_fd;

    RTSPMessageHeader reply1 = {}, *reply = &reply1;

    int lower_transport_mask = 0;

    char real_challenge[64];

    struct sockaddr_storage peer;

    socklen_t peer_len = sizeof(peer);



    if (!ff_network_init())

        return AVERROR(EIO);

redirect:

    rt->control_transport = RTSP_MODE_PLAIN;

    /* extract hostname and port */

    ff_url_split(NULL, 0, auth, sizeof(auth),

                 host, sizeof(host), &port, path, sizeof(path), s->filename);

    if (*auth) {

        av_strlcpy(rt->auth, auth, sizeof(rt->auth));

    }

    if (port < 0)

        port = RTSP_DEFAULT_PORT;



    /* search for options */

    option_list = strrchr(path, '?');

    if (option_list) {

        /* Strip out the RTSP specific options, write out the rest of

         * the options back into the same string. */

        filename = option_list;

        while (option_list) {

            /* move the option pointer */

            option = ++option_list;

            option_list = strchr(option_list, '&');

            if (option_list)

                *option_list = 0;



            /* handle the options */

            if (!strcmp(option, "udp")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_UDP);

            } else if (!strcmp(option, "multicast")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_UDP_MULTICAST);

            } else if (!strcmp(option, "tcp")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_TCP);

            } else if(!strcmp(option, "http")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_TCP);

                rt->control_transport = RTSP_MODE_TUNNEL;

            } else {

                /* Write options back into the buffer, using memmove instead

                 * of strcpy since the strings may overlap. */

                int len = strlen(option);

                memmove(++filename, option, len);

                filename += len;

                if (option_list) *filename = '&';

            }

        }

        *filename = 0;

    }



    if (!lower_transport_mask)

        lower_transport_mask = (1 << RTSP_LOWER_TRANSPORT_NB) - 1;



    if (s->oformat) {

        /* Only UDP or TCP - UDP multicast isn't supported. */

        lower_transport_mask &= (1 << RTSP_LOWER_TRANSPORT_UDP) |

                                (1 << RTSP_LOWER_TRANSPORT_TCP);

        if (!lower_transport_mask || rt->control_transport == RTSP_MODE_TUNNEL) {

            av_log(s, AV_LOG_ERROR, "Unsupported lower transport method, "

                                    "only UDP and TCP are supported for output.\n");

            err = AVERROR(EINVAL);

            goto fail;

        }

    }



    /* Construct the URI used in request; this is similar to s->filename,

     * but with authentication credentials removed and RTSP specific options

     * stripped out. */

    ff_url_join(rt->control_uri, sizeof(rt->control_uri), "rtsp", NULL,

                host, port, "%s", path);



    if (rt->control_transport == RTSP_MODE_TUNNEL) {

        /* set up initial handshake for tunneling */

        char httpname[1024];

        char sessioncookie[17];

        char headers[1024];



        ff_url_join(httpname, sizeof(httpname), "http", NULL, host, port, "%s", path);

        snprintf(sessioncookie, sizeof(sessioncookie), "%08x%08x",

                 av_get_random_seed(), av_get_random_seed());



        /* GET requests */

        if (url_open(&rtsp_hd, httpname, URL_RDONLY) < 0) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* generate GET headers */

        snprintf(headers, sizeof(headers),

                 "x-sessioncookie: %s\r\n"

                 "Accept: application/x-rtsp-tunnelled\r\n"

                 "Pragma: no-cache\r\n"

                 "Cache-Control: no-cache\r\n",

                 sessioncookie);

        ff_http_set_headers(rtsp_hd, headers);



        /* complete the connection */

        if (url_read(rtsp_hd, NULL, 0)) {


            err = AVERROR(EIO);

            goto fail;

        }



        /* POST requests */

        if (url_open(&rtsp_hd_out, httpname, URL_WRONLY) < 0 ) {


            err = AVERROR(EIO);

            goto fail;

        }



        /* generate POST headers */

        snprintf(headers, sizeof(headers),

                 "x-sessioncookie: %s\r\n"

                 "Content-Type: application/x-rtsp-tunnelled\r\n"

                 "Pragma: no-cache\r\n"

                 "Cache-Control: no-cache\r\n"

                 "Content-Length: 32767\r\n"

                 "Expires: Sun, 9 Jan 1972 00:00:00 GMT\r\n",

                 sessioncookie);

        ff_http_set_headers(rtsp_hd_out, headers);

        ff_http_set_chunked_transfer_encoding(rtsp_hd_out, 0);



    } else {

        /* open the tcp connection */

        ff_url_join(tcpname, sizeof(tcpname), "tcp", NULL, host, port, NULL);

        if (url_open(&rtsp_hd, tcpname, URL_RDWR) < 0) {

            err = AVERROR(EIO);

            goto fail;

        }

        rtsp_hd_out = rtsp_hd;

    }

    rt->rtsp_hd = rtsp_hd;

    rt->rtsp_hd_out = rtsp_hd_out;

    rt->seq = 0;



    tcp_fd = url_get_file_handle(rtsp_hd);

    if (!getpeername(tcp_fd, (struct sockaddr*) &peer, &peer_len)) {

        getnameinfo((struct sockaddr*) &peer, peer_len, host, sizeof(host),

                    NULL, 0, NI_NUMERICHOST);

    }



    /* request options supported by the server; this also detects server

     * type */

    for (rt->server_type = RTSP_SERVER_RTP;;) {

        cmd[0] = 0;

        if (rt->server_type == RTSP_SERVER_REAL)

            av_strlcat(cmd,

                       /**

                        * The following entries are required for proper

                        * streaming from a Realmedia server. They are

                        * interdependent in some way although we currently

                        * don't quite understand how. Values were copied

                        * from mplayer SVN r23589.

                        * @param CompanyID is a 16-byte ID in base64

                        * @param ClientChallenge is a 16-byte ID in hex

                        */

                       "ClientChallenge: 9e26d33f2984236010ef6253fb1887f7\r\n"

                       "PlayerStarttime: [28/03/2003:22:50:23 00:00]\r\n"

                       "CompanyID: KnKV4M4I/B2FjJ1TToLycw==\r\n"

                       "GUID: 00000000-0000-0000-0000-000000000000\r\n",

                       sizeof(cmd));

        ff_rtsp_send_cmd(s, "OPTIONS", rt->control_uri, cmd, reply, NULL);

        if (reply->status_code != RTSP_STATUS_OK) {

            err = AVERROR_INVALIDDATA;

            goto fail;

        }



        /* detect server type if not standard-compliant RTP */

        if (rt->server_type != RTSP_SERVER_REAL && reply->real_challenge[0]) {

            rt->server_type = RTSP_SERVER_REAL;

            continue;

        } else if (!strncasecmp(reply->server, "WMServer/", 9)) {

            rt->server_type = RTSP_SERVER_WMS;

        } else if (rt->server_type == RTSP_SERVER_REAL)

            strcpy(real_challenge, reply->real_challenge);

        break;

    }



    if (s->iformat)

        err = rtsp_setup_input_streams(s, reply);

    else

        err = rtsp_setup_output_streams(s, host);

    if (err)

        goto fail;



    do {

        int lower_transport = ff_log2_tab[lower_transport_mask &

                                  ~(lower_transport_mask - 1)];



        err = make_setup_request(s, host, port, lower_transport,

                                 rt->server_type == RTSP_SERVER_REAL ?

                                     real_challenge : NULL);

        if (err < 0)

            goto fail;

        lower_transport_mask &= ~(1 << lower_transport);

        if (lower_transport_mask == 0 && err == 1) {

            err = FF_NETERROR(EPROTONOSUPPORT);

            goto fail;

        }

    } while (err);



    rt->state = RTSP_STATE_IDLE;

    rt->seek_timestamp = 0; /* default is to start stream at position zero */

    return 0;

 fail:

    ff_rtsp_close_streams(s);

    ff_rtsp_close_connections(s);

    if (reply->status_code >=300 && reply->status_code < 400 && s->iformat) {

        av_strlcpy(s->filename, reply->location, sizeof(s->filename));

        av_log(s, AV_LOG_INFO, "Status %d: Redirecting to %s\n",

               reply->status_code,

               s->filename);

        goto redirect;

    }

    ff_network_close();

    return err;

}

static int rtmp_open(URLContext *s, const char *uri, int flags)

{

    RTMPContext *rt = s->priv_data;

    char proto[8], hostname[256], path[1024], auth[100], *fname;

    char *old_app;

    uint8_t buf[2048];

    int port;

    AVDictionary *opts = NULL;

    int ret;



    if (rt->listen_timeout > 0)

        rt->listen = 1;



    rt->is_input = !(flags & AVIO_FLAG_WRITE);



    av_url_split(proto, sizeof(proto), auth, sizeof(auth),

                 hostname, sizeof(hostname), &port,

                 path, sizeof(path), s->filename);



    if (auth[0]) {

        char *ptr = strchr(auth, ':');

        if (ptr) {

            *ptr = '\0';

            av_strlcpy(rt->username, auth, sizeof(rt->username));

            av_strlcpy(rt->password, ptr + 1, sizeof(rt->password));

        }

    }



    if (rt->listen && strcmp(proto, "rtmp")) {

        av_log(s, AV_LOG_ERROR, "rtmp_listen not available for %s\n",

               proto);

        return AVERROR(EINVAL);

    }

    if (!strcmp(proto, "rtmpt") || !strcmp(proto, "rtmpts")) {

        if (!strcmp(proto, "rtmpts"))

            av_dict_set(&opts, "ffrtmphttp_tls", "1", 1);



        /* open the http tunneling connection */

        ff_url_join(buf, sizeof(buf), "ffrtmphttp", NULL, hostname, port, NULL);

    } else if (!strcmp(proto, "rtmps")) {

        /* open the tls connection */

        if (port < 0)

            port = RTMPS_DEFAULT_PORT;

        ff_url_join(buf, sizeof(buf), "tls", NULL, hostname, port, NULL);

    } else if (!strcmp(proto, "rtmpe") || (!strcmp(proto, "rtmpte"))) {

        if (!strcmp(proto, "rtmpte"))

            av_dict_set(&opts, "ffrtmpcrypt_tunneling", "1", 1);



        /* open the encrypted connection */

        ff_url_join(buf, sizeof(buf), "ffrtmpcrypt", NULL, hostname, port, NULL);

        rt->encrypted = 1;

    } else {

        /* open the tcp connection */

        if (port < 0)

            port = RTMP_DEFAULT_PORT;

        if (rt->listen)

            ff_url_join(buf, sizeof(buf), "tcp", NULL, hostname, port,

                        "?listen&listen_timeout=%d",

                        rt->listen_timeout * 1000);

        else

            ff_url_join(buf, sizeof(buf), "tcp", NULL, hostname, port, NULL);

    }



reconnect:

    if ((ret = ffurl_open(&rt->stream, buf, AVIO_FLAG_READ_WRITE,

                          &s->interrupt_callback, &opts)) < 0) {

        av_log(s , AV_LOG_ERROR, "Cannot open connection %s\n", buf);

        goto fail;

    }



    if (rt->swfverify) {

        if ((ret = rtmp_calc_swfhash(s)) < 0)

            goto fail;

    }



    rt->state = STATE_START;

    if (!rt->listen && (ret = rtmp_handshake(s, rt)) < 0)

        goto fail;

    if (rt->listen && (ret = rtmp_server_handshake(s, rt)) < 0)

        goto fail;



    rt->out_chunk_size = 128;

    rt->in_chunk_size  = 128; // Probably overwritten later

    rt->state = STATE_HANDSHAKED;



    // Keep the application name when it has been defined by the user.

    old_app = rt->app;



    rt->app = av_malloc(APP_MAX_LENGTH);

    if (!rt->app) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    //extract "app" part from path

    if (!strncmp(path, "/ondemand/", 10)) {

        fname = path + 10;

        memcpy(rt->app, "ondemand", 9);

    } else {

        char *next = *path ? path + 1 : path;

        char *p = strchr(next, '/');

        if (!p) {

            fname = next;

            rt->app[0] = '\0';

        } else {

            // make sure we do not mismatch a playpath for an application instance

            char *c = strchr(p + 1, ':');

            fname = strchr(p + 1, '/');

            if (!fname || (c && c < fname)) {

                fname = p + 1;

                av_strlcpy(rt->app, path + 1, p - path);

            } else {

                fname++;

                av_strlcpy(rt->app, path + 1, fname - path - 1);

            }

        }

    }



    if (old_app) {

        // The name of application has been defined by the user, override it.

        av_free(rt->app);

        rt->app = old_app;

    }



    if (!rt->playpath) {

        int len = strlen(fname);



        rt->playpath = av_malloc(PLAYPATH_MAX_LENGTH);

        if (!rt->playpath) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        if (!strchr(fname, ':') && len >= 4 &&

            (!strcmp(fname + len - 4, ".f4v") ||

             !strcmp(fname + len - 4, ".mp4"))) {

            memcpy(rt->playpath, "mp4:", 5);

        } else if (len >= 4 && !strcmp(fname + len - 4, ".flv")) {

            fname[len - 4] = '\0';

        } else {

            rt->playpath[0] = 0;

        }

        av_strlcat(rt->playpath, fname, PLAYPATH_MAX_LENGTH);

    }



    if (!rt->tcurl) {

        rt->tcurl = av_malloc(TCURL_MAX_LENGTH);

        if (!rt->tcurl) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        ff_url_join(rt->tcurl, TCURL_MAX_LENGTH, proto, NULL, hostname,

                    port, "/%s", rt->app);

    }



    if (!rt->flashver) {

        rt->flashver = av_malloc(FLASHVER_MAX_LENGTH);

        if (!rt->flashver) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        if (rt->is_input) {

            snprintf(rt->flashver, FLASHVER_MAX_LENGTH, "%s %d,%d,%d,%d",

                    RTMP_CLIENT_PLATFORM, RTMP_CLIENT_VER1, RTMP_CLIENT_VER2,

                    RTMP_CLIENT_VER3, RTMP_CLIENT_VER4);

        } else {

            snprintf(rt->flashver, FLASHVER_MAX_LENGTH,

                    "FMLE/3.0 (compatible; %s)", LIBAVFORMAT_IDENT);

        }

    }



    rt->client_report_size = 1048576;

    rt->bytes_read = 0;

    rt->last_bytes_read = 0;

    rt->server_bw = 2500000;



    av_log(s, AV_LOG_DEBUG, "Proto = %s, path = %s, app = %s, fname = %s\n",

           proto, path, rt->app, rt->playpath);

    if (!rt->listen) {

        if ((ret = gen_connect(s, rt)) < 0)

            goto fail;

    } else {

        if (read_connect(s, s->priv_data) < 0)

            goto fail;

        rt->is_input = 1;

    }



    do {

        ret = get_packet(s, 1);

    } while (ret == EAGAIN);

    if (ret < 0)

        goto fail;



    if (rt->do_reconnect) {

        ffurl_close(rt->stream);

        rt->stream       = NULL;

        rt->do_reconnect = 0;

        rt->nb_invokes   = 0;

        memset(rt->prev_pkt, 0, sizeof(rt->prev_pkt));

        free_tracked_methods(rt);

        goto reconnect;

    }



    if (rt->is_input) {

        // generate FLV header for demuxer

        rt->flv_size = 13;

        rt->flv_data = av_realloc(rt->flv_data, rt->flv_size);

        rt->flv_off  = 0;

        memcpy(rt->flv_data, "FLV\1\5\0\0\0\011\0\0\0\0", rt->flv_size);

    } else {

        rt->flv_size = 0;

        rt->flv_data = NULL;

        rt->flv_off  = 0;

        rt->skip_bytes = 13;

    }



    s->max_packet_size = rt->stream->max_packet_size;

    s->is_streamed     = 1;

    return 0;



fail:

    av_dict_free(&opts);

    rtmp_close(s);

    return ret;

}

