            } else {

                /* Write options back into the buffer, using memmove instead

                 * of strcpy since the strings may overlap. */

                int len = strlen(option);

                memmove(++filename, option, len);

                filename += len;

                if (option_list) *filename = '&';

            }

        }

        *filename = 0;

    }



    if (!lower_transport_mask)

        lower_transport_mask = (1 << RTSP_LOWER_TRANSPORT_NB) - 1;



    if (s->oformat) {

        /* Only UDP or TCP - UDP multicast isn't supported. */

        lower_transport_mask &= (1 << RTSP_LOWER_TRANSPORT_UDP) |

                                (1 << RTSP_LOWER_TRANSPORT_TCP);

        if (!lower_transport_mask || rt->control_transport == RTSP_MODE_TUNNEL) {

            av_log(s, AV_LOG_ERROR, "Unsupported lower transport method, "

                                    "only UDP and TCP are supported for output.\n");

            err = AVERROR(EINVAL);

            goto fail;

        }

    }



    /* Construct the URI used in request; this is similar to s->filename,

     * but with authentication credentials removed and RTSP specific options

     * stripped out. */

    ff_url_join(rt->control_uri, sizeof(rt->control_uri), "rtsp", NULL,

                host, port, "%s", path);



    if (rt->control_transport == RTSP_MODE_TUNNEL) {

        /* set up initial handshake for tunneling */

        char httpname[1024];

        char sessioncookie[17];

        char headers[1024];



        ff_url_join(httpname, sizeof(httpname), "http", auth, host, port, "%s", path);

        snprintf(sessioncookie, sizeof(sessioncookie), "%08x%08x",

                 av_get_random_seed(), av_get_random_seed());



        /* GET requests */

        if (url_alloc(&rt->rtsp_hd, httpname, URL_RDONLY) < 0) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* generate GET headers */

        snprintf(headers, sizeof(headers),

                 "x-sessioncookie: %s\r\n"

                 "Accept: application/x-rtsp-tunnelled\r\n"

                 "Pragma: no-cache\r\n"

                 "Cache-Control: no-cache\r\n",

                 sessioncookie);

        ff_http_set_headers(rt->rtsp_hd, headers);



        /* complete the connection */

        if (url_connect(rt->rtsp_hd)) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* POST requests */

        if (url_alloc(&rt->rtsp_hd_out, httpname, URL_WRONLY) < 0 ) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* generate POST headers */

        snprintf(headers, sizeof(headers),

                 "x-sessioncookie: %s\r\n"

                 "Content-Type: application/x-rtsp-tunnelled\r\n"

                 "Pragma: no-cache\r\n"

                 "Cache-Control: no-cache\r\n"

                 "Content-Length: 32767\r\n"

                 "Expires: Sun, 9 Jan 1972 00:00:00 GMT\r\n",

                 sessioncookie);

        ff_http_set_headers(rt->rtsp_hd_out, headers);

        ff_http_set_chunked_transfer_encoding(rt->rtsp_hd_out, 0);



        /* Initialize the authentication state for the POST session. The HTTP

         * protocol implementation doesn't properly handle multi-pass

         * authentication for POST requests, since it would require one of

         * the following:

         * - implementing Expect: 100-continue, which many HTTP servers

         *   don't support anyway, even less the RTSP servers that do HTTP

         *   tunneling

         * - sending the whole POST data until getting a 401 reply specifying

         *   what authentication method to use, then resending all that data

         * - waiting for potential 401 replies directly after sending the

         *   POST header (waiting for some unspecified time)

         * Therefore, we copy the full auth state, which works for both basic

         * and digest. (For digest, we would have to synchronize the nonce

         * count variable between the two sessions, if we'd do more requests

         * with the original session, though.)

         */

        ff_http_init_auth_state(rt->rtsp_hd_out, rt->rtsp_hd);



        /* complete the connection */

        if (url_connect(rt->rtsp_hd_out)) {

            err = AVERROR(EIO);

            goto fail;

        }

    } else {

        /* open the tcp connection */

        ff_url_join(tcpname, sizeof(tcpname), "tcp", NULL, host, port, NULL);

        if (url_open(&rt->rtsp_hd, tcpname, URL_RDWR) < 0) {

            err = AVERROR(EIO);

            goto fail;

        }

        rt->rtsp_hd_out = rt->rtsp_hd;

    }

    rt->seq = 0;



    tcp_fd = url_get_file_handle(rt->rtsp_hd);

    if (!getpeername(tcp_fd, (struct sockaddr*) &peer, &peer_len)) {

        getnameinfo((struct sockaddr*) &peer, peer_len, host, sizeof(host),

                    NULL, 0, NI_NUMERICHOST);

    }



    /* request options supported by the server; this also detects server

     * type */

    for (rt->server_type = RTSP_SERVER_RTP;;) {

        cmd[0] = 0;

        if (rt->server_type == RTSP_SERVER_REAL)

            av_strlcat(cmd,

                       /**

                        * The following entries are required for proper

                        * streaming from a Realmedia server. They are

                        * interdependent in some way although we currently

                        * don't quite understand how. Values were copied

                        * from mplayer SVN r23589.

                        * @param CompanyID is a 16-byte ID in base64

                        * @param ClientChallenge is a 16-byte ID in hex

                        */

                       "ClientChallenge: 9e26d33f2984236010ef6253fb1887f7\r\n"

                       "PlayerStarttime: [28/03/2003:22:50:23 00:00]\r\n"

                       "CompanyID: KnKV4M4I/B2FjJ1TToLycw==\r\n"

                       "GUID: 00000000-0000-0000-0000-000000000000\r\n",

                       sizeof(cmd));

        ff_rtsp_send_cmd(s, "OPTIONS", rt->control_uri, cmd, reply, NULL);

        if (reply->status_code != RTSP_STATUS_OK) {

            err = AVERROR_INVALIDDATA;

            goto fail;

        }



        /* detect server type if not standard-compliant RTP */

        if (rt->server_type != RTSP_SERVER_REAL && reply->real_challenge[0]) {

            rt->server_type = RTSP_SERVER_REAL;

            continue;

        } else if (!strncasecmp(reply->server, "WMServer/", 9)) {

            rt->server_type = RTSP_SERVER_WMS;

        } else if (rt->server_type == RTSP_SERVER_REAL)

            strcpy(real_challenge, reply->real_challenge);

        break;

    }



    if (s->iformat)

        err = rtsp_setup_input_streams(s, reply);

    else

        err = rtsp_setup_output_streams(s, host);

    if (err)

        goto fail;



    do {

        int lower_transport = ff_log2_tab[lower_transport_mask &

                                  ~(lower_transport_mask - 1)];



        err = make_setup_request(s, host, port, lower_transport,

                                 rt->server_type == RTSP_SERVER_REAL ?

                                     real_challenge : NULL);

        if (err < 0)

            goto fail;

        lower_transport_mask &= ~(1 << lower_transport);

        if (lower_transport_mask == 0 && err == 1) {

            err = FF_NETERROR(EPROTONOSUPPORT);

            goto fail;

        }

    } while (err);



    rt->state = RTSP_STATE_IDLE;

    rt->seek_timestamp = 0; /* default is to start stream at position zero */

    return 0;

 fail:

    ff_rtsp_close_streams(s);

    ff_rtsp_close_connections(s);

    if (reply->status_code >=300 && reply->status_code < 400 && s->iformat) {

        av_strlcpy(s->filename, reply->location, sizeof(s->filename));

        av_log(s, AV_LOG_INFO, "Status %d: Redirecting to %s\n",

               reply->status_code,

               s->filename);

        goto redirect;

    }

    ff_network_close();

    return err;

}

static void FUNC(intra_pred)(HEVCContext *s, int x0, int y0, int log2_size, int c_idx)

{

#define PU(x) \

    ((x) >> s->sps->log2_min_pu_size)

#define MVF(x, y) \

    (s->ref->tab_mvf[(x) + (y) * pic_width_in_min_pu])

#define MVF_PU(x, y) \

    MVF(PU(x0 + ((x) << hshift)), PU(y0 + ((y) << vshift)))

#define IS_INTRA(x, y) \

    MVF_PU(x, y).is_intra

#define MIN_TB_ADDR_ZS(x, y) \

    s->pps->min_tb_addr_zs[(y) * s->sps->min_tb_width + (x)]

#define EXTEND_LEFT(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            ptr[i - 1] = ptr[i]

#define EXTEND_RIGHT(ptr, start, length) \

        for (i = (start); i < (start) + (length); i++) \

            ptr[i] = ptr[i - 1]

#define EXTEND_UP(ptr, start, length)   EXTEND_LEFT(ptr, start, length)

#define EXTEND_DOWN(ptr, start, length) EXTEND_RIGHT(ptr, start, length)

#define EXTEND_LEFT_CIP(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            if (!IS_INTRA(i - 1, -1)) \

                ptr[i - 1] = ptr[i]

#define EXTEND_RIGHT_CIP(ptr, start, length) \

        for (i = (start); i < (start) + (length); i++) \

            if (!IS_INTRA(i, -1)) \

                ptr[i] = ptr[i - 1]

#define EXTEND_UP_CIP(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            if (!IS_INTRA(-1, i - 1)) \

                ptr[i - 1] = ptr[i]

#define EXTEND_UP_CIP_0(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            ptr[i - 1] = ptr[i]

#define EXTEND_DOWN_CIP(ptr, start, length) \

        for (i = (start); i < (start) + (length); i++) \

            if (!IS_INTRA(-1, i)) \

                ptr[i] = ptr[i - 1]

    HEVCLocalContext *lc = s->HEVClc;

    int i;

    int hshift = s->sps->hshift[c_idx];

    int vshift = s->sps->vshift[c_idx];

    int size = (1 << log2_size);

    int size_in_luma = size << hshift;

    int size_in_tbs = size_in_luma >> s->sps->log2_min_transform_block_size;

    int x = x0 >> hshift;

    int y = y0 >> vshift;

    int x_tb = x0 >> s->sps->log2_min_transform_block_size;

    int y_tb = y0 >> s->sps->log2_min_transform_block_size;

    int cur_tb_addr = MIN_TB_ADDR_ZS(x_tb, y_tb);



    ptrdiff_t stride = s->frame->linesize[c_idx] / sizeof(pixel);

    pixel *src = (pixel*)s->frame->data[c_idx] + x + y * stride;



    int pic_width_in_min_pu = PU(s->sps->width);



    enum IntraPredMode mode = c_idx ? lc->pu.intra_pred_mode_c :

                              lc->tu.cur_intra_pred_mode;



    pixel left_array[2 * MAX_TB_SIZE + 1];

    pixel filtered_left_array[2 * MAX_TB_SIZE + 1];

    pixel top_array[2 * MAX_TB_SIZE + 1];

    pixel filtered_top_array[2 * MAX_TB_SIZE + 1];



    pixel *left          = left_array + 1;

    pixel *top           = top_array + 1;

    pixel *filtered_left = filtered_left_array + 1;

    pixel *filtered_top  = filtered_top_array + 1;



    int cand_bottom_left = lc->na.cand_bottom_left && cur_tb_addr > MIN_TB_ADDR_ZS(x_tb - 1, y_tb + size_in_tbs);

    int cand_left        = lc->na.cand_left;

    int cand_up_left     = lc->na.cand_up_left;

    int cand_up          = lc->na.cand_up;

    int cand_up_right    = lc->na.cand_up_right && cur_tb_addr > MIN_TB_ADDR_ZS(x_tb + size_in_tbs, y_tb - 1);



    int bottom_left_size = (FFMIN(y0 + 2 * size_in_luma, s->sps->height) -

                            (y0 + size_in_luma)) >> vshift;

    int top_right_size   = (FFMIN(x0 + 2 * size_in_luma, s->sps->width) -

                            (x0 + size_in_luma)) >> hshift;



    if (s->pps->constrained_intra_pred_flag == 1) {

        int size_in_luma_pu = PU(size_in_luma);

        int on_pu_edge_x = !(x0 & ((1 << s->sps->log2_min_pu_size) - 1));

        int on_pu_edge_y = !(y0 & ((1 << s->sps->log2_min_pu_size) - 1));

        if(!size_in_luma_pu)

            size_in_luma_pu++;

        if (cand_bottom_left == 1 && on_pu_edge_x) {

            int x_left_pu   = PU(x0 - 1);

            int y_bottom_pu = PU(y0 + size_in_luma);

            cand_bottom_left = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_bottom_left |= MVF(x_left_pu, y_bottom_pu + i).is_intra;

        }

        if (cand_left == 1 && on_pu_edge_x) {

            int x_left_pu   = PU(x0 - 1);

            int y_left_pu   = PU(y0);

            cand_left = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_left |= MVF(x_left_pu, y_left_pu + i).is_intra;

        }

        if (cand_up_left == 1) {

            int x_left_pu   = PU(x0 - 1);

            int y_top_pu    = PU(y0 - 1);

            cand_up_left = MVF(x_left_pu, y_top_pu).is_intra;

        }

        if (cand_up == 1 && on_pu_edge_y) {

            int x_top_pu    = PU(x0);

            int y_top_pu    = PU(y0 - 1);

            cand_up = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_up |= MVF(x_top_pu + i, y_top_pu).is_intra;

        }

        if (cand_up_right == 1 && on_pu_edge_y) {

            int y_top_pu    = PU(y0 - 1);

            int x_right_pu  = PU(x0 + size_in_luma);

            cand_up_right = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_up_right |= MVF(x_right_pu + i, y_top_pu).is_intra;

        }

        for (i = 0; i < 2 * MAX_TB_SIZE; i++) {

            left[i] = 128;

            top[i]  = 128;

        }

    }

    if (cand_bottom_left) {

        for (i = size + bottom_left_size; i < (size << 1); i++)

            if (IS_INTRA(-1, size + bottom_left_size - 1) || !s->pps->constrained_intra_pred_flag)

                left[i] = POS(-1, size + bottom_left_size - 1);

        for (i = size + bottom_left_size - 1; i >= size; i--)

            if (IS_INTRA(-1, i) || !s->pps->constrained_intra_pred_flag)

                left[i] = POS(-1, i);

    }

    if (cand_left)

        for (i = size - 1; i >= 0; i--)

            if (IS_INTRA(-1, i) || !s->pps->constrained_intra_pred_flag)

                left[i] = POS(-1, i);

    if (cand_up_left)

        if (IS_INTRA(-1, -1) || !s->pps->constrained_intra_pred_flag) {

            left[-1] = POS(-1, -1);

            top[-1]  = left[-1];

        }

    if (cand_up)

        for (i = size - 1; i >= 0; i--)

            if (IS_INTRA(i, -1) || !s->pps->constrained_intra_pred_flag)

                top[i] = POS(i, -1);

    if (cand_up_right) {

        for (i = size + top_right_size; i < (size << 1); i++)

            if (IS_INTRA(size + top_right_size - 1, -1) || !s->pps->constrained_intra_pred_flag)

                top[i] = POS(size + top_right_size - 1, -1);

        for (i = size + top_right_size - 1; i >= size; i--)

            if (IS_INTRA(i, -1) || !s->pps->constrained_intra_pred_flag)

                top[i] = POS(i, -1);

    }



    if (s->pps->constrained_intra_pred_flag == 1) {

        if (cand_bottom_left || cand_left || cand_up_left || cand_up || cand_up_right) {

            int size_max_x = x0 + ((2 * size) << hshift) < s->sps->width ?

                                    2 * size : (s->sps->width - x0) >> hshift;

            int size_max_y = y0 + ((2 * size) << vshift) < s->sps->height ?

                                    2 * size : (s->sps->height - y0) >> vshift;

            int j = size + (cand_bottom_left? bottom_left_size: 0) -1;

            if (!cand_up_right) {

                size_max_x = x0 + ((size) << hshift) < s->sps->width ?

                                                    size : (s->sps->width - x0) >> hshift;

            }

            if (!cand_bottom_left) {

                size_max_y = y0 + (( size) << vshift) < s->sps->height ?

                                                     size : (s->sps->height - y0) >> vshift;

            }

            if (cand_bottom_left || cand_left || cand_up_left) {

                while (j>-1 && !IS_INTRA(-1, j)) j--;

                if (!IS_INTRA(-1, j)) {

                    j = 0;

                    while(j < size_max_x && !IS_INTRA(j, -1)) j++;

                    EXTEND_LEFT_CIP(top, j, j+1);

                    left[-1] = top[-1];

                    j = 0;

                }

            } else {

                j = 0;

                while (j < size_max_x && !IS_INTRA(j, -1)) j++;

                if (j > 0)

                    if (x0 > 0) {

                        EXTEND_LEFT_CIP(top, j, j+1);

                    } else {

                        EXTEND_LEFT_CIP(top, j, j);

                        top[-1] = top[0];

                    }

                left[-1] = top[-1];

                j = 0;

            }

            if (cand_bottom_left || cand_left) {

                EXTEND_DOWN_CIP(left, j, size_max_y-j);

            }

            if (!cand_left) {

                EXTEND_DOWN(left, 0, size);

            }

            if (!cand_bottom_left) {

                EXTEND_DOWN(left, size, size);

            }

            if (x0 != 0 && y0 != 0) {

                EXTEND_UP_CIP(left, size_max_y - 1, size_max_y);

            } else if( x0 == 0) {

                EXTEND_UP_CIP_0(left, size_max_y - 1, size_max_y);

            } else{

                EXTEND_UP_CIP(left, size_max_y - 1, size_max_y-1);

            }

            top[-1] = left[-1];

            if (y0 != 0) {

                EXTEND_RIGHT_CIP(top, 0, size_max_x);

            }

        }

    }

    // Infer the unavailable samples

    if (!cand_bottom_left) {

        if (cand_left) {

            EXTEND_DOWN(left, size, size);

        } else if (cand_up_left) {

            EXTEND_DOWN(left, 0, 2 * size);

            cand_left = 1;

        } else if (cand_up) {

            left[-1] = top[0];

            EXTEND_DOWN(left, 0, 2 * size);

            cand_up_left = 1;

            cand_left = 1;

        } else if (cand_up_right) {

            EXTEND_LEFT(top, size, size);

            left[-1] = top[0];

            EXTEND_DOWN(left ,0 , 2 * size);

            cand_up = 1;

            cand_up_left = 1;

            cand_left = 1;

        } else { // No samples available

            top[0] = left[-1] = (1 << (BIT_DEPTH - 1));

            EXTEND_RIGHT(top, 1, 2 * size - 1);

            EXTEND_DOWN(left, 0, 2 * size);

        }

    }



    if (!cand_left) {

        EXTEND_UP(left, size, size);

    }

    if (!cand_up_left) {

        left[-1] = left[0];

    }

    if (!cand_up) {

        top[0] = left[-1];

        EXTEND_RIGHT(top, 1, size-1);

    }

    if (!cand_up_right) {

        EXTEND_RIGHT(top, size, size);

    }



    top[-1] = left[-1];



#undef EXTEND_LEFT_CIP

#undef EXTEND_RIGHT_CIP

#undef EXTEND_UP_CIP

#undef EXTEND_DOWN_CIP

#undef IS_INTRA

#undef MVF_PU

#undef MVF

#undef PU

#undef EXTEND_LEFT

#undef EXTEND_RIGHT

#undef EXTEND_UP

#undef EXTEND_DOWN

#undef MIN_TB_ADDR_ZS



    // Filtering process

    if (c_idx == 0 && mode != INTRA_DC && size != 4) {

        int intra_hor_ver_dist_thresh[] = { 7, 1, 0 };

        int min_dist_vert_hor           = FFMIN(FFABS((int)mode - 26),

                                                FFABS((int)mode - 10));

        if (min_dist_vert_hor > intra_hor_ver_dist_thresh[log2_size - 3]) {

            int threshold = 1 << (BIT_DEPTH - 5);

            if (s->sps->sps_strong_intra_smoothing_enable_flag &&

                log2_size == 5 &&

                FFABS(top[-1] + top[63] - 2 * top[31]) < threshold &&

                FFABS(left[-1] + left[63] - 2 * left[31]) < threshold) {

                // We can't just overwrite values in top because it could be

                // a pointer into src

                filtered_top[-1] = top[-1];

                filtered_top[63] = top[63];

                for (i = 0; i < 63; i++)

                    filtered_top[i] = ((64 - (i + 1)) * top[-1] +

                                             (i + 1)  * top[63] + 32) >> 6;

                for (i = 0; i < 63; i++)

                    left[i] = ((64 - (i + 1)) * left[-1] +

                                     (i + 1)  * left[63] + 32) >> 6;

                top = filtered_top;

            } else {

                filtered_left[2 * size - 1] = left[2 * size - 1];

                filtered_top[2 * size - 1]  = top[2 * size - 1];

                for (i = 2 * size - 2; i >= 0; i--)

                    filtered_left[i] = (left[i + 1] + 2 * left[i] +

                                        left[i - 1] + 2) >> 2;

                filtered_top[-1] =

                filtered_left[-1] = (left[0] + 2 * left[-1] +

                                     top[0]  + 2) >> 2;

                for (i = 2 * size - 2; i >= 0; i--)

                    filtered_top[i] = (top[i + 1] + 2 * top[i] +

                                       top[i - 1] + 2) >> 2;

                left = filtered_left;

                top  = filtered_top;

            }

        }

    }



    switch (mode) {

    case INTRA_PLANAR:

        s->hpc.pred_planar[log2_size - 2]((uint8_t*)src, (uint8_t*)top,

                                          (uint8_t*)left, stride);

        break;

    case INTRA_DC:

        s->hpc.pred_dc((uint8_t*)src, (uint8_t*)top,

                       (uint8_t*)left, stride, log2_size, c_idx);

        break;

    default:

        s->hpc.pred_angular[log2_size - 2]((uint8_t*)src, (uint8_t*)top,

                                           (uint8_t*)left, stride, c_idx, mode);

        break;

    }

}

void ff_hevc_luma_mv_mvp_mode(HEVCContext *s, int x0, int y0, int nPbW,

                              int nPbH, int log2_cb_size, int part_idx,

                              int merge_idx, MvField *mv,

                              int mvp_lx_flag, int LX)

{

    HEVCLocalContext *lc = s->HEVClc;

    MvField *tab_mvf = s->ref->tab_mvf;

    int isScaledFlag_L0 = 0;

    int availableFlagLXA0 = 1;

    int availableFlagLXB0 = 1;

    int numMVPCandLX = 0;

    int min_pu_width = s->sps->min_pu_width;



    int xA0, yA0;

    int is_available_a0;

    int xA1, yA1;

    int is_available_a1;

    int xB0, yB0;

    int is_available_b0;

    int xB1, yB1;

    int is_available_b1;

    int xB2, yB2;

    int is_available_b2;



    Mv mvpcand_list[2] = { { 0 } };

    Mv mxA;

    Mv mxB;

    int ref_idx_curr = 0;

    int ref_idx = 0;

    int pred_flag_index_l0;

    int pred_flag_index_l1;



    const int cand_bottom_left = lc->na.cand_bottom_left;

    const int cand_left        = lc->na.cand_left;

    const int cand_up_left     = lc->na.cand_up_left;

    const int cand_up          = lc->na.cand_up;

    const int cand_up_right    = lc->na.cand_up_right_sap;

    ref_idx_curr       = LX;

    ref_idx            = mv->ref_idx[LX];

    pred_flag_index_l0 = LX;

    pred_flag_index_l1 = !LX;



    // left bottom spatial candidate

    xA0 = x0 - 1;

    yA0 = y0 + nPbH;



    is_available_a0 = AVAILABLE(cand_bottom_left, A0) &&

                      yA0 < s->sps->height &&

                      PRED_BLOCK_AVAILABLE(A0);



    //left spatial merge candidate

    xA1    = x0 - 1;

    yA1    = y0 + nPbH - 1;



    is_available_a1 = AVAILABLE(cand_left, A1);

    if (is_available_a0 || is_available_a1)

        isScaledFlag_L0 = 1;



    if (is_available_a0) {

        if (MP_MX(A0, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX(A0, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }



    if (is_available_a1) {

        if (MP_MX(A1, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX(A1, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }



    if (is_available_a0) {

        if (MP_MX_LT(A0, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX_LT(A0, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }



    if (is_available_a1) {

        if (MP_MX_LT(A1, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX_LT(A1, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }

    availableFlagLXA0 = 0;



b_candidates:

    // B candidates

    // above right spatial merge candidate

    xB0    = x0 + nPbW;

    yB0    = y0 - 1;



    is_available_b0 =  AVAILABLE(cand_up_right, B0) &&

                       xB0 < s->sps->width &&

                       PRED_BLOCK_AVAILABLE(B0);



    if (is_available_b0) {

        if (MP_MX(B0, pred_flag_index_l0, mxB)) {

            goto scalef;

        }

        if (MP_MX(B0, pred_flag_index_l1, mxB)) {

            goto scalef;

        }

    }



    // above spatial merge candidate

    xB1    = x0 + nPbW - 1;

    yB1    = y0 - 1;



    is_available_b1 = AVAILABLE(cand_up, B1);



    if (is_available_b1) {

        if (MP_MX(B1, pred_flag_index_l0, mxB)) {

            goto scalef;

        }

        if (MP_MX(B1, pred_flag_index_l1, mxB)) {

            goto scalef;

        }

    }



    // above left spatial merge candidate

    xB2 = x0 - 1;

    yB2 = y0 - 1;

    is_available_b2 = AVAILABLE(cand_up_left, B2);



    if (is_available_b2) {

        if (MP_MX(B2, pred_flag_index_l0, mxB)) {

            goto scalef;

        }

        if (MP_MX(B2, pred_flag_index_l1, mxB)) {

            goto scalef;

        }

    }

    availableFlagLXB0 = 0;



scalef:

    if (!isScaledFlag_L0) {

        if (availableFlagLXB0) {

            availableFlagLXA0 = 1;

            mxA = mxB;

        }

        availableFlagLXB0 = 0;



        // XB0 and L1

        if (is_available_b0) {

            availableFlagLXB0 = MP_MX_LT(B0, pred_flag_index_l0, mxB);

            if (!availableFlagLXB0)

                availableFlagLXB0 = MP_MX_LT(B0, pred_flag_index_l1, mxB);

        }



        if (is_available_b1 && !availableFlagLXB0) {

            availableFlagLXB0 = MP_MX_LT(B1, pred_flag_index_l0, mxB);

            if (!availableFlagLXB0)

                availableFlagLXB0 = MP_MX_LT(B1, pred_flag_index_l1, mxB);

        }



        if (is_available_b2 && !availableFlagLXB0) {

            availableFlagLXB0 = MP_MX_LT(B2, pred_flag_index_l0, mxB);

            if (!availableFlagLXB0)

                availableFlagLXB0 = MP_MX_LT(B2, pred_flag_index_l1, mxB);

        }

    }



    if (availableFlagLXA0)

        mvpcand_list[numMVPCandLX++] = mxA;



    if (availableFlagLXB0 && (!availableFlagLXA0 || mxA.x != mxB.x || mxA.y != mxB.y))

        mvpcand_list[numMVPCandLX++] = mxB;



    //temporal motion vector prediction candidate

    if (numMVPCandLX < 2 && s->sh.slice_temporal_mvp_enabled_flag &&

        mvp_lx_flag == numMVPCandLX) {

        Mv mv_col;

        int available_col = temporal_luma_motion_vector(s, x0, y0, nPbW,

                                                        nPbH, ref_idx,

                                                        &mv_col, LX);

        if (available_col)

            mvpcand_list[numMVPCandLX++] = mv_col;

    }



    mv->mv[LX] = mvpcand_list[mvp_lx_flag];

}

static void hls_prediction_unit(HEVCContext *s, int x0, int y0,

                                int nPbW, int nPbH,

                                int log2_cb_size, int partIdx)

{

#define POS(c_idx, x, y)                                                              \

    &s->frame->data[c_idx][((y) >> s->sps->vshift[c_idx]) * s->frame->linesize[c_idx] + \

                           (((x) >> s->sps->hshift[c_idx]) << s->sps->pixel_shift)]

    HEVCLocalContext *lc = &s->HEVClc;

    int merge_idx = 0;

    struct MvField current_mv = {{{ 0 }}};



    int min_pu_width = s->sps->min_pu_width;



    MvField *tab_mvf = s->ref->tab_mvf;

    RefPicList  *refPicList = s->ref->refPicList;

    HEVCFrame *ref0, *ref1;



    int tmpstride = MAX_PB_SIZE;



    uint8_t *dst0 = POS(0, x0, y0);

    uint8_t *dst1 = POS(1, x0, y0);

    uint8_t *dst2 = POS(2, x0, y0);

    int log2_min_cb_size = s->sps->log2_min_cb_size;

    int min_cb_width     = s->sps->min_cb_width;

    int x_cb             = x0 >> log2_min_cb_size;

    int y_cb             = y0 >> log2_min_cb_size;

    int x_pu, y_pu;

    int i, j;



    int skip_flag = SAMPLE_CTB(s->skip_flag, x_cb, y_cb);



    if (!skip_flag)

        lc->pu.merge_flag = ff_hevc_merge_flag_decode(s);



    if (skip_flag || lc->pu.merge_flag) {

        if (s->sh.max_num_merge_cand > 1)

            merge_idx = ff_hevc_merge_idx_decode(s);

        else

            merge_idx = 0;



        ff_hevc_luma_mv_merge_mode(s, x0, y0, nPbW, nPbH, log2_cb_size,

                                   partIdx, merge_idx, &current_mv);

    } else {

        enum InterPredIdc inter_pred_idc = PRED_L0;

        int mvp_flag;



        ff_hevc_set_neighbour_available(s, x0, y0, nPbW, nPbH);

        if (s->sh.slice_type == B_SLICE)

            inter_pred_idc = ff_hevc_inter_pred_idc_decode(s, nPbW, nPbH);



        if (inter_pred_idc != PRED_L1) {

            if (s->sh.nb_refs[L0]) {

                current_mv.ref_idx[0]= ff_hevc_ref_idx_lx_decode(s, s->sh.nb_refs[L0]);

            }

            current_mv.pred_flag[0] = 1;

            hls_mvd_coding(s, x0, y0, 0);

            mvp_flag = ff_hevc_mvp_lx_flag_decode(s);

            ff_hevc_luma_mv_mvp_mode(s, x0, y0, nPbW, nPbH, log2_cb_size,

                                     partIdx, merge_idx, &current_mv,

                                     mvp_flag, 0);

            current_mv.mv[0].x += lc->pu.mvd.x;

            current_mv.mv[0].y += lc->pu.mvd.y;

        }



        if (inter_pred_idc != PRED_L0) {

            if (s->sh.nb_refs[L1]) {

                current_mv.ref_idx[1]= ff_hevc_ref_idx_lx_decode(s, s->sh.nb_refs[L1]);

            }



            if (s->sh.mvd_l1_zero_flag == 1 && inter_pred_idc == PRED_BI) {

                AV_ZERO32(&lc->pu.mvd);

            } else {

                hls_mvd_coding(s, x0, y0, 1);

            }



            current_mv.pred_flag[1] = 1;

            mvp_flag = ff_hevc_mvp_lx_flag_decode(s);

            ff_hevc_luma_mv_mvp_mode(s, x0, y0, nPbW, nPbH, log2_cb_size,

                                     partIdx, merge_idx, &current_mv,

                                     mvp_flag, 1);

            current_mv.mv[1].x += lc->pu.mvd.x;

            current_mv.mv[1].y += lc->pu.mvd.y;

        }

    }



    x_pu = x0 >> s->sps->log2_min_pu_size;

    y_pu = y0 >> s->sps->log2_min_pu_size;



    for (j = 0; j < nPbH >> s->sps->log2_min_pu_size; j++)

        for (i = 0; i < nPbW >> s->sps->log2_min_pu_size; i++)

            tab_mvf[(y_pu + j) * min_pu_width + x_pu + i] = current_mv;



    if (current_mv.pred_flag[0]) {

        ref0 = refPicList[0].ref[current_mv.ref_idx[0]];

        if (!ref0)

            return;

        hevc_await_progress(s, ref0, &current_mv.mv[0], y0, nPbH);

    }

    if (current_mv.pred_flag[1]) {

        ref1 = refPicList[1].ref[current_mv.ref_idx[1]];

        if (!ref1)

            return;

        hevc_await_progress(s, ref1, &current_mv.mv[1], y0, nPbH);

    }



    if (current_mv.pred_flag[0] && !current_mv.pred_flag[1]) {

        DECLARE_ALIGNED(16, int16_t,  tmp[MAX_PB_SIZE * MAX_PB_SIZE]);

        DECLARE_ALIGNED(16, int16_t, tmp2[MAX_PB_SIZE * MAX_PB_SIZE]);



        luma_mc(s, tmp, tmpstride, ref0->frame,

                &current_mv.mv[0], x0, y0, nPbW, nPbH);



        if ((s->sh.slice_type == P_SLICE && s->pps->weighted_pred_flag) ||

            (s->sh.slice_type == B_SLICE && s->pps->weighted_bipred_flag)) {

            s->hevcdsp.weighted_pred(s->sh.luma_log2_weight_denom,

                                     s->sh.luma_weight_l0[current_mv.ref_idx[0]],

                                     s->sh.luma_offset_l0[current_mv.ref_idx[0]],

                                     dst0, s->frame->linesize[0], tmp,

                                     tmpstride, nPbW, nPbH);

        } else {

            s->hevcdsp.put_unweighted_pred(dst0, s->frame->linesize[0], tmp, tmpstride, nPbW, nPbH);

        }

        chroma_mc(s, tmp, tmp2, tmpstride, ref0->frame,

                  &current_mv.mv[0], x0 / 2, y0 / 2, nPbW / 2, nPbH / 2);



        if ((s->sh.slice_type == P_SLICE && s->pps->weighted_pred_flag) ||

            (s->sh.slice_type == B_SLICE && s->pps->weighted_bipred_flag)) {

            s->hevcdsp.weighted_pred(s->sh.chroma_log2_weight_denom,

                                     s->sh.chroma_weight_l0[current_mv.ref_idx[0]][0],

                                     s->sh.chroma_offset_l0[current_mv.ref_idx[0]][0],

                                     dst1, s->frame->linesize[1], tmp, tmpstride,

                                     nPbW / 2, nPbH / 2);

            s->hevcdsp.weighted_pred(s->sh.chroma_log2_weight_denom,

                                     s->sh.chroma_weight_l0[current_mv.ref_idx[0]][1],

                                     s->sh.chroma_offset_l0[current_mv.ref_idx[0]][1],

                                     dst2, s->frame->linesize[2], tmp2, tmpstride,

                                     nPbW / 2, nPbH / 2);

        } else {

            s->hevcdsp.put_unweighted_pred(dst1, s->frame->linesize[1], tmp, tmpstride, nPbW/2, nPbH/2);

            s->hevcdsp.put_unweighted_pred(dst2, s->frame->linesize[2], tmp2, tmpstride, nPbW/2, nPbH/2);

        }

    } else if (!current_mv.pred_flag[0] && current_mv.pred_flag[1]) {

        DECLARE_ALIGNED(16, int16_t, tmp [MAX_PB_SIZE * MAX_PB_SIZE]);

        DECLARE_ALIGNED(16, int16_t, tmp2[MAX_PB_SIZE * MAX_PB_SIZE]);



        if (!ref1)

            return;



        luma_mc(s, tmp, tmpstride, ref1->frame,

                &current_mv.mv[1], x0, y0, nPbW, nPbH);



        if ((s->sh.slice_type == P_SLICE && s->pps->weighted_pred_flag) ||

            (s->sh.slice_type == B_SLICE && s->pps->weighted_bipred_flag)) {

            s->hevcdsp.weighted_pred(s->sh.luma_log2_weight_denom,

                                      s->sh.luma_weight_l1[current_mv.ref_idx[1]],

                                      s->sh.luma_offset_l1[current_mv.ref_idx[1]],

                                      dst0, s->frame->linesize[0], tmp, tmpstride,

                                      nPbW, nPbH);

        } else {

            s->hevcdsp.put_unweighted_pred(dst0, s->frame->linesize[0], tmp, tmpstride, nPbW, nPbH);

        }



        chroma_mc(s, tmp, tmp2, tmpstride, ref1->frame,

                  &current_mv.mv[1], x0/2, y0/2, nPbW/2, nPbH/2);



        if ((s->sh.slice_type == P_SLICE && s->pps->weighted_pred_flag) ||

            (s->sh.slice_type == B_SLICE && s->pps->weighted_bipred_flag)) {

            s->hevcdsp.weighted_pred(s->sh.chroma_log2_weight_denom,

                                     s->sh.chroma_weight_l1[current_mv.ref_idx[1]][0],

                                     s->sh.chroma_offset_l1[current_mv.ref_idx[1]][0],

                                     dst1, s->frame->linesize[1], tmp, tmpstride, nPbW/2, nPbH/2);

            s->hevcdsp.weighted_pred(s->sh.chroma_log2_weight_denom,

                                     s->sh.chroma_weight_l1[current_mv.ref_idx[1]][1],

                                     s->sh.chroma_offset_l1[current_mv.ref_idx[1]][1],

                                     dst2, s->frame->linesize[2], tmp2, tmpstride, nPbW/2, nPbH/2);

        } else {

            s->hevcdsp.put_unweighted_pred(dst1, s->frame->linesize[1], tmp, tmpstride, nPbW/2, nPbH/2);

            s->hevcdsp.put_unweighted_pred(dst2, s->frame->linesize[2], tmp2, tmpstride, nPbW/2, nPbH/2);

        }

    } else if (current_mv.pred_flag[0] && current_mv.pred_flag[1]) {

        DECLARE_ALIGNED(16, int16_t, tmp [MAX_PB_SIZE * MAX_PB_SIZE]);

        DECLARE_ALIGNED(16, int16_t, tmp2[MAX_PB_SIZE * MAX_PB_SIZE]);

        DECLARE_ALIGNED(16, int16_t, tmp3[MAX_PB_SIZE * MAX_PB_SIZE]);

        DECLARE_ALIGNED(16, int16_t, tmp4[MAX_PB_SIZE * MAX_PB_SIZE]);

        HEVCFrame *ref0 = refPicList[0].ref[current_mv.ref_idx[0]];

        HEVCFrame *ref1 = refPicList[1].ref[current_mv.ref_idx[1]];



        if (!ref0 || !ref1)

            return;



        luma_mc(s, tmp, tmpstride, ref0->frame,

                &current_mv.mv[0], x0, y0, nPbW, nPbH);

        luma_mc(s, tmp2, tmpstride, ref1->frame,

                &current_mv.mv[1], x0, y0, nPbW, nPbH);



        if ((s->sh.slice_type == P_SLICE && s->pps->weighted_pred_flag) ||

            (s->sh.slice_type == B_SLICE && s->pps->weighted_bipred_flag)) {

            s->hevcdsp.weighted_pred_avg(s->sh.luma_log2_weight_denom,

                                         s->sh.luma_weight_l0[current_mv.ref_idx[0]],

                                         s->sh.luma_weight_l1[current_mv.ref_idx[1]],

                                         s->sh.luma_offset_l0[current_mv.ref_idx[0]],

                                         s->sh.luma_offset_l1[current_mv.ref_idx[1]],

                                         dst0, s->frame->linesize[0],

                                         tmp, tmp2, tmpstride, nPbW, nPbH);

        } else {

            s->hevcdsp.put_weighted_pred_avg(dst0, s->frame->linesize[0],

                                             tmp, tmp2, tmpstride, nPbW, nPbH);

        }



        chroma_mc(s, tmp, tmp2, tmpstride, ref0->frame,

                  &current_mv.mv[0], x0 / 2, y0 / 2, nPbW / 2, nPbH / 2);

        chroma_mc(s, tmp3, tmp4, tmpstride, ref1->frame,

                  &current_mv.mv[1], x0 / 2, y0 / 2, nPbW / 2, nPbH / 2);



        if ((s->sh.slice_type == P_SLICE && s->pps->weighted_pred_flag) ||

            (s->sh.slice_type == B_SLICE && s->pps->weighted_bipred_flag)) {

            s->hevcdsp.weighted_pred_avg(s->sh.chroma_log2_weight_denom,

                                         s->sh.chroma_weight_l0[current_mv.ref_idx[0]][0],

                                         s->sh.chroma_weight_l1[current_mv.ref_idx[1]][0],

                                         s->sh.chroma_offset_l0[current_mv.ref_idx[0]][0],

                                         s->sh.chroma_offset_l1[current_mv.ref_idx[1]][0],

                                         dst1, s->frame->linesize[1], tmp, tmp3,

                                         tmpstride, nPbW / 2, nPbH / 2);

            s->hevcdsp.weighted_pred_avg(s->sh.chroma_log2_weight_denom,

                                         s->sh.chroma_weight_l0[current_mv.ref_idx[0]][1],

                                         s->sh.chroma_weight_l1[current_mv.ref_idx[1]][1],

                                         s->sh.chroma_offset_l0[current_mv.ref_idx[0]][1],

                                         s->sh.chroma_offset_l1[current_mv.ref_idx[1]][1],

                                         dst2, s->frame->linesize[2], tmp2, tmp4,

                                         tmpstride, nPbW / 2, nPbH / 2);

        } else {

            s->hevcdsp.put_weighted_pred_avg(dst1, s->frame->linesize[1], tmp, tmp3, tmpstride, nPbW/2, nPbH/2);

            s->hevcdsp.put_weighted_pred_avg(dst2, s->frame->linesize[2], tmp2, tmp4, tmpstride, nPbW/2, nPbH/2);

        }

    }

}

static void luma_mc(HEVCContext *s, int16_t *dst, ptrdiff_t dststride,

                    AVFrame *ref, const Mv *mv, int x_off, int y_off,

                    int block_w, int block_h)

{

    HEVCLocalContext *lc = &s->HEVClc;

    uint8_t *src         = ref->data[0];

    ptrdiff_t srcstride  = ref->linesize[0];

    int pic_width        = s->ps.sps->width;

    int pic_height       = s->ps.sps->height;



    int mx         = mv->x & 3;

    int my         = mv->y & 3;

    int extra_left = ff_hevc_qpel_extra_before[mx];

    int extra_top  = ff_hevc_qpel_extra_before[my];



    x_off += mv->x >> 2;

    y_off += mv->y >> 2;

    src   += y_off * srcstride + (x_off << s->ps.sps->pixel_shift);



    if (x_off < extra_left || y_off < extra_top ||

        x_off >= pic_width - block_w - ff_hevc_qpel_extra_after[mx] ||

        y_off >= pic_height - block_h - ff_hevc_qpel_extra_after[my]) {

        const int edge_emu_stride = EDGE_EMU_BUFFER_STRIDE << s->ps.sps->pixel_shift;

        int offset = extra_top * srcstride + (extra_left << s->ps.sps->pixel_shift);

        int buf_offset = extra_top *

                         edge_emu_stride + (extra_left << s->ps.sps->pixel_shift);



        s->vdsp.emulated_edge_mc(lc->edge_emu_buffer, src - offset,

                                 edge_emu_stride, srcstride,

                                 block_w + ff_hevc_qpel_extra[mx],

                                 block_h + ff_hevc_qpel_extra[my],

                                 x_off - extra_left, y_off - extra_top,

                                 pic_width, pic_height);

        src = lc->edge_emu_buffer + buf_offset;

        srcstride = edge_emu_stride;

    }

    s->hevcdsp.put_hevc_qpel[my][mx](dst, dststride, src, srcstride, block_w,

                                     block_h, lc->mc_buffer);

}

static void virtio_scsi_handle_cmd(VirtIODevice *vdev, VirtQueue *vq)

{

    /* use non-QOM casts in the data path */

    VirtIOSCSI *s = (VirtIOSCSI *)vdev;

    VirtIOSCSIReq *req, *next;

    QTAILQ_HEAD(, VirtIOSCSIReq) reqs = QTAILQ_HEAD_INITIALIZER(reqs);



    if (s->ctx && !s->dataplane_started) {

        virtio_scsi_dataplane_start(s);

        return;

    }

    while ((req = virtio_scsi_pop_req(s, vq))) {

        if (virtio_scsi_handle_cmd_req_prepare(s, req)) {

            QTAILQ_INSERT_TAIL(&reqs, req, next);

        }

    }



    QTAILQ_FOREACH_SAFE(req, &reqs, next, next) {

        virtio_scsi_handle_cmd_req_submit(s, req);

    }

}

static void virtio_blk_dma_restart_bh(void *opaque)

{

    VirtIOBlock *s = opaque;

    VirtIOBlockReq *req = s->rq;

    MultiReqBuffer mrb = {

        .num_writes = 0,

    };



    qemu_bh_delete(s->bh);

    s->bh = NULL;



    s->rq = NULL;



    while (req) {

        virtio_blk_handle_request(req, &mrb);

        req = req->next;

    }



    if (mrb.num_writes > 0) {

        do_multiwrite(s->bs, mrb.blkreq, mrb.num_writes);

    }

}

static void virtio_blk_reset(VirtIODevice *vdev)

{

    VirtIOBlock *s = VIRTIO_BLK(vdev);

    AioContext *ctx;

    VirtIOBlockReq *req;



    ctx = blk_get_aio_context(s->blk);

    aio_context_acquire(ctx);

    blk_drain(s->blk);



    /* We drop queued requests after blk_drain() because blk_drain() itself can

     * produce them. */

    while (s->rq) {

        req = s->rq;

        s->rq = req->next;

        virtqueue_detach_element(req->vq, &req->elem, 0);

        virtio_blk_free_request(req);

    }



    if (s->dataplane) {

        virtio_blk_data_plane_stop(s->dataplane);

    }

    aio_context_release(ctx);



    blk_set_enable_write_cache(s->blk, s->original_wce);

}

static void virtio_gpu_handle_ctrl(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOGPU *g = VIRTIO_GPU(vdev);

    struct virtio_gpu_ctrl_command *cmd;



    if (!virtio_queue_ready(vq)) {

        return;

    }



#ifdef CONFIG_VIRGL

    if (!g->renderer_inited && g->use_virgl_renderer) {

        virtio_gpu_virgl_init(g);

        g->renderer_inited = true;

    }

#endif



    cmd = g_new(struct virtio_gpu_ctrl_command, 1);

    while (virtqueue_pop(vq, &cmd->elem)) {

        cmd->vq = vq;

        cmd->error = 0;

        cmd->finished = false;

        cmd->waiting = false;

        QTAILQ_INSERT_TAIL(&g->cmdq, cmd, next);

        cmd = g_new(struct virtio_gpu_ctrl_command, 1);

    }

    g_free(cmd);



    virtio_gpu_process_cmdq(g);



#ifdef CONFIG_VIRGL

    if (g->use_virgl_renderer) {

        virtio_gpu_virgl_fence_poll(g);

    }

#endif

}

static void av_always_inline filter_mb_edgeh( uint8_t *pix, int stride, const int16_t bS[4], unsigned int qp, H264Context *h ) {

    const int qp_bd_offset = 6 * (h->sps.bit_depth_luma - 8);

    const unsigned int index_a = qp - qp_bd_offset + h->slice_alpha_c0_offset;

    const int alpha = alpha_table[index_a];

    const int beta  = beta_table[qp - qp_bd_offset + h->slice_beta_offset];

    if (alpha ==0 || beta == 0) return;



    if( bS[0] < 4 ) {

        int8_t tc[4];

        tc[0] = tc0_table[index_a][bS[0]];

        tc[1] = tc0_table[index_a][bS[1]];

        tc[2] = tc0_table[index_a][bS[2]];

        tc[3] = tc0_table[index_a][bS[3]];

        h->h264dsp.h264_v_loop_filter_luma(pix, stride, alpha, beta, tc);

    } else {

        h->h264dsp.h264_v_loop_filter_luma_intra(pix, stride, alpha, beta);

    }

}

