int ff_flac_parse_picture(AVFormatContext *s, uint8_t *buf, int buf_size)

{

    const CodecMime *mime = ff_id3v2_mime_tags;

    enum AVCodecID id = AV_CODEC_ID_NONE;

    AVBufferRef *data = NULL;

    uint8_t mimetype[64], *desc = NULL;

    AVIOContext *pb = NULL;

    AVStream *st;

    int type, width, height;

    int len, ret = 0;



    pb = avio_alloc_context(buf, buf_size, 0, NULL, NULL, NULL, NULL);

    if (!pb)

        return AVERROR(ENOMEM);



    /* read the picture type */

    type = avio_rb32(pb);

    if (type >= FF_ARRAY_ELEMS(ff_id3v2_picture_types) || type < 0) {

        av_log(s, AV_LOG_ERROR, "Invalid picture type: %d.\n", type);

        if (s->error_recognition & AV_EF_EXPLODE) {

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }

        type = 0;

    }



    /* picture mimetype */

    len = avio_rb32(pb);

    if (len <= 0 ||

        avio_read(pb, mimetype, FFMIN(len, sizeof(mimetype) - 1)) != len) {

        av_log(s, AV_LOG_ERROR, "Could not read mimetype from an attached "

               "picture.\n");

        if (s->error_recognition & AV_EF_EXPLODE)

            ret = AVERROR_INVALIDDATA;

        goto fail;

    }

    mimetype[len] = 0;



    while (mime->id != AV_CODEC_ID_NONE) {

        if (!strncmp(mime->str, mimetype, sizeof(mimetype))) {

            id = mime->id;

            break;

        }

        mime++;

    }

    if (id == AV_CODEC_ID_NONE) {

        av_log(s, AV_LOG_ERROR, "Unknown attached picture mimetype: %s.\n",

               mimetype);

        if (s->error_recognition & AV_EF_EXPLODE)

            ret = AVERROR_INVALIDDATA;

        goto fail;

    }



    /* picture description */

    len = avio_rb32(pb);

    if (len > 0) {

        if (!(desc = av_malloc(len + 1))) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        if (avio_read(pb, desc, len) != len) {

            av_log(s, AV_LOG_ERROR, "Error reading attached picture description.\n");

            if (s->error_recognition & AV_EF_EXPLODE)

                ret = AVERROR(EIO);

            goto fail;

        }

        desc[len] = 0;

    }



    /* picture metadata */

    width  = avio_rb32(pb);

    height = avio_rb32(pb);

    avio_skip(pb, 8);



    /* picture data */

    len = avio_rb32(pb);

    if (len <= 0) {

        av_log(s, AV_LOG_ERROR, "Invalid attached picture size: %d.\n", len);

        if (s->error_recognition & AV_EF_EXPLODE)

            ret = AVERROR_INVALIDDATA;

        goto fail;

    }

    if (!(data = av_buffer_alloc(len))) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }

    if (avio_read(pb, data->data, len) != len) {

        av_log(s, AV_LOG_ERROR, "Error reading attached picture data.\n");

        if (s->error_recognition & AV_EF_EXPLODE)

            ret = AVERROR(EIO);

        goto fail;

    }



    st = avformat_new_stream(s, NULL);

    if (!st) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    av_init_packet(&st->attached_pic);

    st->attached_pic.buf          = data;

    st->attached_pic.data         = data->data;

    st->attached_pic.size         = len;

    st->attached_pic.stream_index = st->index;

    st->attached_pic.flags       |= AV_PKT_FLAG_KEY;



    st->disposition      |= AV_DISPOSITION_ATTACHED_PIC;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id   = id;

    st->codec->width      = width;

    st->codec->height     = height;

    av_dict_set(&st->metadata, "comment", ff_id3v2_picture_types[type], 0);

    if (desc)

        av_dict_set(&st->metadata, "title", desc, AV_DICT_DONT_STRDUP_VAL);



    av_freep(&pb);



    return 0;



fail:

    av_buffer_unref(&data);

    av_freep(&desc);

    av_freep(&pb);



    return ret;

}

static void read_apic(AVFormatContext *s, AVIOContext *pb, int taglen, char *tag, ID3v2ExtraMeta **extra_meta)

{

    int enc, pic_type;

    char             mimetype[64];

    const CodecMime     *mime = ff_id3v2_mime_tags;

    enum AVCodecID           id = AV_CODEC_ID_NONE;

    ID3v2ExtraMetaAPIC  *apic = NULL;

    ID3v2ExtraMeta *new_extra = NULL;

    int64_t               end = avio_tell(pb) + taglen;



    if (taglen <= 4)

        goto fail;



    new_extra = av_mallocz(sizeof(*new_extra));

    apic      = av_mallocz(sizeof(*apic));

    if (!new_extra || !apic)

        goto fail;



    enc = avio_r8(pb);

    taglen--;



    /* mimetype */

    taglen -= avio_get_str(pb, taglen, mimetype, sizeof(mimetype));

    while (mime->id != AV_CODEC_ID_NONE) {

        if (!av_strncasecmp(mime->str, mimetype, sizeof(mimetype))) {

            id = mime->id;

            break;

        }

        mime++;

    }

    if (id == AV_CODEC_ID_NONE) {

        av_log(s, AV_LOG_WARNING, "Unknown attached picture mimetype: %s, skipping.\n", mimetype);

        goto fail;

    }

    apic->id = id;



    /* picture type */

    pic_type = avio_r8(pb);

    taglen--;

    if (pic_type < 0 || pic_type >= FF_ARRAY_ELEMS(ff_id3v2_picture_types)) {

        av_log(s, AV_LOG_WARNING, "Unknown attached picture type %d.\n", pic_type);

        pic_type = 0;

    }

    apic->type = ff_id3v2_picture_types[pic_type];



    /* description and picture data */

    if (decode_str(s, pb, enc, &apic->description, &taglen) < 0) {

        av_log(s, AV_LOG_ERROR, "Error decoding attached picture description.\n");

        goto fail;

    }



    apic->buf = av_buffer_alloc(taglen);

    if (!apic->buf || !taglen || avio_read(pb, apic->buf->data, taglen) != taglen)

        goto fail;



    new_extra->tag    = "APIC";

    new_extra->data   = apic;

    new_extra->next   = *extra_meta;

    *extra_meta       = new_extra;



    return;



fail:

    if (apic)

        free_apic(apic);

    av_freep(&new_extra);

    avio_seek(pb, end, SEEK_SET);

}

static int ape_tag_read_field(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    uint8_t key[1024], *value;

    uint32_t size, flags;

    int i, c;



    size = avio_rl32(pb);  /* field size */

    flags = avio_rl32(pb); /* field flags */

    for (i = 0; i < sizeof(key) - 1; i++) {

        c = avio_r8(pb);

        if (c < 0x20 || c > 0x7E)

            break;

        else

            key[i] = c;

    }

    key[i] = 0;

    if (c != 0) {

        av_log(s, AV_LOG_WARNING, "Invalid APE tag key '%s'.\n", key);

        return -1;

    }

    if (size > INT32_MAX - FF_INPUT_BUFFER_PADDING_SIZE) {

        av_log(s, AV_LOG_ERROR, "APE tag size too large.\n");

        return AVERROR_INVALIDDATA;

    }

    if (flags & APE_TAG_FLAG_IS_BINARY) {

        uint8_t filename[1024];

        enum AVCodecID id;

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);



        size -= avio_get_str(pb, size, filename, sizeof(filename));

        if (size <= 0) {

            av_log(s, AV_LOG_WARNING, "Skipping binary tag '%s'.\n", key);

            return 0;

        }



        av_dict_set(&st->metadata, key, filename, 0);



        if ((id = ff_guess_image2_codec(filename)) != AV_CODEC_ID_NONE) {

            AVPacket pkt;

            int ret;



            ret = av_get_packet(s->pb, &pkt, size);

            if (ret < 0) {

                av_log(s, AV_LOG_ERROR, "Error reading cover art.\n");

                return ret;

            }



            st->disposition      |= AV_DISPOSITION_ATTACHED_PIC;

            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

            st->codec->codec_id   = id;



            st->attached_pic              = pkt;

            st->attached_pic.stream_index = st->index;

            st->attached_pic.flags       |= AV_PKT_FLAG_KEY;

        } else {

            if (ff_get_extradata(st->codec, s->pb, size) < 0)

                return AVERROR(ENOMEM);

            st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

        }

    } else {

        value = av_malloc(size+1);

        if (!value)

            return AVERROR(ENOMEM);

        c = avio_read(pb, value, size);

        if (c < 0) {

            av_free(value);

            return c;

        }

        value[c] = 0;

        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }

    return 0;

}

static int idcin_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    IdcinDemuxContext *idcin = s->priv_data;

    AVStream *st;

    unsigned int width, height;

    unsigned int sample_rate, bytes_per_sample, channels;

    int ret;



    /* get the 5 header parameters */

    width = avio_rl32(pb);

    height = avio_rl32(pb);

    sample_rate = avio_rl32(pb);

    bytes_per_sample = avio_rl32(pb);

    channels = avio_rl32(pb);



    if (s->pb->eof_reached) {

        av_log(s, AV_LOG_ERROR, "incomplete header\n");

        return s->pb->error ? s->pb->error : AVERROR_EOF;

    }



    if (av_image_check_size(width, height, 0, s) < 0)

        return AVERROR_INVALIDDATA;

    if (sample_rate > 0) {

        if (sample_rate < 14 || sample_rate > INT_MAX) {

            av_log(s, AV_LOG_ERROR, "invalid sample rate: %u\n", sample_rate);

            return AVERROR_INVALIDDATA;

        }

        if (bytes_per_sample < 1 || bytes_per_sample > 2) {

            av_log(s, AV_LOG_ERROR, "invalid bytes per sample: %u\n",

                   bytes_per_sample);

            return AVERROR_INVALIDDATA;

        }

        if (channels < 1 || channels > 2) {

            av_log(s, AV_LOG_ERROR, "invalid channels: %u\n", channels);

            return AVERROR_INVALIDDATA;

        }

        idcin->audio_present = 1;

    } else {

        /* if sample rate is 0, assume no audio */

        idcin->audio_present = 0;

    }



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    avpriv_set_pts_info(st, 33, 1, IDCIN_FPS);

    st->start_time = 0;

    idcin->video_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_IDCIN;

    st->codec->codec_tag = 0;  /* no fourcc */

    st->codec->width = width;

    st->codec->height = height;



    /* load up the Huffman tables into extradata */

    st->codec->extradata_size = HUFFMAN_TABLE_SIZE;

    st->codec->extradata = av_malloc(HUFFMAN_TABLE_SIZE);

    ret = avio_read(pb, st->codec->extradata, HUFFMAN_TABLE_SIZE);

    if (ret < 0) {

        return ret;

    } else if (ret != HUFFMAN_TABLE_SIZE) {

        av_log(s, AV_LOG_ERROR, "incomplete header\n");

        return AVERROR(EIO);

    }



    if (idcin->audio_present) {

        idcin->audio_present = 1;

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        avpriv_set_pts_info(st, 63, 1, sample_rate);

        st->start_time = 0;

        idcin->audio_stream_index = st->index;

        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_tag = 1;

        st->codec->channels = channels;

        st->codec->channel_layout = channels > 1 ? AV_CH_LAYOUT_STEREO :

                                                   AV_CH_LAYOUT_MONO;

        st->codec->sample_rate = sample_rate;

        st->codec->bits_per_coded_sample = bytes_per_sample * 8;

        st->codec->bit_rate = sample_rate * bytes_per_sample * 8 * channels;

        st->codec->block_align = idcin->block_align = bytes_per_sample * channels;

        if (bytes_per_sample == 1)

            st->codec->codec_id = AV_CODEC_ID_PCM_U8;

        else

            st->codec->codec_id = AV_CODEC_ID_PCM_S16LE;



        if (sample_rate % 14 != 0) {

            idcin->audio_chunk_size1 = (sample_rate / 14) *

            bytes_per_sample * channels;

            idcin->audio_chunk_size2 = (sample_rate / 14 + 1) *

                bytes_per_sample * channels;

        } else {

            idcin->audio_chunk_size1 = idcin->audio_chunk_size2 =

                (sample_rate / 14) * bytes_per_sample * channels;

        }

        idcin->current_audio_chunk = 0;

    }



    idcin->next_chunk_is_video = 1;

    idcin->first_pkt_pos = avio_tell(s->pb);



    return 0;

}

void HELPER(access_check_cp_reg)(CPUARMState *env, void *rip)

{

    const ARMCPRegInfo *ri = rip;

    switch (ri->accessfn(env, ri)) {

    case CP_ACCESS_OK:

        return;

    case CP_ACCESS_TRAP:

    case CP_ACCESS_TRAP_UNCATEGORIZED:

        /* These cases will eventually need to generate different

         * syndrome information.

         */

        break;

    default:

        g_assert_not_reached();

    }

    raise_exception(env, EXCP_UDEF);

}

void HELPER(set_cp_reg)(CPUARMState *env, void *rip, uint32_t value)

{

    const ARMCPRegInfo *ri = rip;



    ri->writefn(env, ri, value);

}

void HELPER(access_check_cp_reg)(CPUARMState *env, void *rip, uint32_t syndrome)

{

    const ARMCPRegInfo *ri = rip;

    int target_el;



    if (arm_feature(env, ARM_FEATURE_XSCALE) && ri->cp < 14

        && extract32(env->cp15.c15_cpar, ri->cp, 1) == 0) {

        raise_exception(env, EXCP_UDEF, syndrome, exception_target_el(env));

    }



    if (!ri->accessfn) {

        return;

    }



    switch (ri->accessfn(env, ri)) {

    case CP_ACCESS_OK:

        return;

    case CP_ACCESS_TRAP:

        target_el = exception_target_el(env);

        break;

    case CP_ACCESS_TRAP_EL2:

        /* Requesting a trap to EL2 when we're in EL3 or S-EL0/1 is

         * a bug in the access function.

         */

        assert(!arm_is_secure(env) && !arm_current_el(env) == 3);

        target_el = 2;

        break;

    case CP_ACCESS_TRAP_EL3:

        target_el = 3;

        break;

    case CP_ACCESS_TRAP_UNCATEGORIZED:

        target_el = exception_target_el(env);

        syndrome = syn_uncategorized();

        break;

    default:

        g_assert_not_reached();

    }



    raise_exception(env, EXCP_UDEF, syndrome, target_el);

}

void HELPER(diag)(CPUS390XState *env, uint32_t r1, uint32_t r3, uint32_t num)

{

    uint64_t r;



    switch (num) {

    case 0x500:

        /* KVM hypercall */

        qemu_mutex_lock_iothread();

        r = s390_virtio_hypercall(env);

        qemu_mutex_unlock_iothread();

        break;

    case 0x44:

        /* yield */

        r = 0;

        break;

    case 0x308:

        /* ipl */

        handle_diag_308(env, r1, r3);

        r = 0;

        break;

    default:

        r = -1;

        break;

    }



    if (r) {

        program_interrupt(env, PGM_OPERATION, ILEN_LATER_INC);

    }

}

