static char *pxb_host_ofw_unit_address(const SysBusDevice *dev)

{

    const PCIHostState *pxb_host;

    const PCIBus *pxb_bus;

    const PXBDev *pxb_dev;

    int position;

    const DeviceState *pxb_dev_base;

    const PCIHostState *main_host;

    const SysBusDevice *main_host_sbd;



    pxb_host = PCI_HOST_BRIDGE(dev);

    pxb_bus = pxb_host->bus;

    pxb_dev = PXB_DEV(pxb_bus->parent_dev);

    position = g_list_index(pxb_dev_list, pxb_dev);

    assert(position >= 0);



    pxb_dev_base = DEVICE(pxb_dev);

    main_host = PCI_HOST_BRIDGE(pxb_dev_base->parent_bus->parent);

    main_host_sbd = SYS_BUS_DEVICE(main_host);



    if (main_host_sbd->num_mmio > 0) {

        return g_strdup_printf(TARGET_FMT_plx ",%x",

                               main_host_sbd->mmio[0].addr, position + 1);

    }

    if (main_host_sbd->num_pio > 0) {

        return g_strdup_printf("i%04x,%x",

                               main_host_sbd->pio[0], position + 1);

    }

    return NULL;

}

static char *usb_get_fw_dev_path(DeviceState *qdev)

{

    USBDevice *dev = DO_UPCAST(USBDevice, qdev, qdev);

    char *fw_path, *in;

    int pos = 0;

    long nr;



    fw_path = qemu_malloc(32 + strlen(dev->port->path) * 6);

    in = dev->port->path;

    while (true) {

        nr = strtol(in, &in, 10);

        if (in[0] == '.') {

            /* some hub between root port and device */

            pos += sprintf(fw_path + pos, "hub@%ld/", nr);

            in++;

        } else {

            /* the device itself */

            pos += sprintf(fw_path + pos, "%s@%ld", qdev_fw_name(qdev), nr);

            break;

        }

    }

    return fw_path;

}

static void quantize_bands(int (*out)[2], const float *in, const float *scaled,

                           int size, float Q34, int is_signed, int maxval)

{

    int i;

    double qc;

    for (i = 0; i < size; i++) {

        qc = scaled[i] * Q34;

        out[i][0] = (int)FFMIN((int)qc,            maxval);

        out[i][1] = (int)FFMIN((int)(qc + 0.4054), maxval);

        if (is_signed && in[i] < 0.0f) {

            out[i][0] = -out[i][0];

            out[i][1] = -out[i][1];

        }

    }

}

static int pred(float *in, float *tgt, int n)

{

    int x, y;

    float *p1, *p2;

    double f0, f1, f2;

    float temp;



    if (in[n] == 0)

        return 0;



    if ((f0 = *in) <= 0)

        return 0;



    for (x=1 ; ; x++) {

        if (n < x)

            return 1;



        p1 = in + x;

        p2 = tgt;

        f1 = *(p1--);

        for (y=x; --y; f1 += (*(p1--))*(*(p2++)));



        p1 = tgt + x - 1;

        p2 = tgt;

        *(p1--) = f2 = -f1/f0;

        for (y=x >> 1; y--;) {

            temp = *p2 + *p1 * f2;

            *(p1--) += *p2 * f2;

            *(p2++) = temp;

        }

        if ((f0 += f1*f2) < 0)

            return 0;

    }

}

static int compare_doubles(const double *a, const double *b, int len,

                           double max_diff)

{

    int i;



    for (i = 0; i < len; i++) {

        if (fabs(a[i] - b[i]) > max_diff) {

            av_log(NULL, AV_LOG_ERROR, "%d: %- .12f - %- .12f = % .12g\n",

                   i, a[i], b[i], a[i] - b[i]);

            return -1;

        }

    }

    return 0;

}

av_cold int swr_init(struct SwrContext *s){

    int ret;

    char l1[1024], l2[1024];



    clear_context(s);



    if(s-> in_sample_fmt >= AV_SAMPLE_FMT_NB){

        av_log(s, AV_LOG_ERROR, "Requested input sample format %d is invalid\n", s->in_sample_fmt);

        return AVERROR(EINVAL);

    }

    if(s->out_sample_fmt >= AV_SAMPLE_FMT_NB){

        av_log(s, AV_LOG_ERROR, "Requested output sample format %d is invalid\n", s->out_sample_fmt);

        return AVERROR(EINVAL);

    }



    s->out.ch_count  = s-> user_out_ch_count;

    s-> in.ch_count  = s->  user_in_ch_count;

    s->used_ch_count = s->user_used_ch_count;



    s-> in_ch_layout = s-> user_in_ch_layout;

    s->out_ch_layout = s->user_out_ch_layout;



    if(av_get_channel_layout_nb_channels(s-> in_ch_layout) > SWR_CH_MAX) {

        av_log(s, AV_LOG_WARNING, "Input channel layout 0x%"PRIx64" is invalid or unsupported.\n", s-> in_ch_layout);

        s->in_ch_layout = 0;

    }



    if(av_get_channel_layout_nb_channels(s->out_ch_layout) > SWR_CH_MAX) {

        av_log(s, AV_LOG_WARNING, "Output channel layout 0x%"PRIx64" is invalid or unsupported.\n", s->out_ch_layout);

        s->out_ch_layout = 0;

    }



    switch(s->engine){

#if CONFIG_LIBSOXR

        case SWR_ENGINE_SOXR: s->resampler = &swri_soxr_resampler; break;

#endif

        case SWR_ENGINE_SWR : s->resampler = &swri_resampler; break;

        default:

            av_log(s, AV_LOG_ERROR, "Requested resampling engine is unavailable\n");

            return AVERROR(EINVAL);

    }



    if(!s->used_ch_count)

        s->used_ch_count= s->in.ch_count;



    if(s->used_ch_count && s-> in_ch_layout && s->used_ch_count != av_get_channel_layout_nb_channels(s-> in_ch_layout)){

        av_log(s, AV_LOG_WARNING, "Input channel layout has a different number of channels than the number of used channels, ignoring layout\n");

        s-> in_ch_layout= 0;

    }



    if(!s-> in_ch_layout)

        s-> in_ch_layout= av_get_default_channel_layout(s->used_ch_count);

    if(!s->out_ch_layout)

        s->out_ch_layout= av_get_default_channel_layout(s->out.ch_count);



    s->rematrix= s->out_ch_layout  !=s->in_ch_layout || s->rematrix_volume!=1.0 ||

                 s->rematrix_custom;



    if(s->int_sample_fmt == AV_SAMPLE_FMT_NONE){

        if(av_get_planar_sample_fmt(s->in_sample_fmt) <= AV_SAMPLE_FMT_S16P){

            s->int_sample_fmt= AV_SAMPLE_FMT_S16P;

        }else if(   av_get_planar_sample_fmt(s-> in_sample_fmt) == AV_SAMPLE_FMT_S32P

                 && av_get_planar_sample_fmt(s->out_sample_fmt) == AV_SAMPLE_FMT_S32P

                 && !s->rematrix

                 && s->engine != SWR_ENGINE_SOXR){

            s->int_sample_fmt= AV_SAMPLE_FMT_S32P;

        }else if(av_get_planar_sample_fmt(s->in_sample_fmt) <= AV_SAMPLE_FMT_FLTP){

            s->int_sample_fmt= AV_SAMPLE_FMT_FLTP;

        }else{

            av_log(s, AV_LOG_DEBUG, "Using double precision mode\n");

            s->int_sample_fmt= AV_SAMPLE_FMT_DBLP;

        }

    }



    if(   s->int_sample_fmt != AV_SAMPLE_FMT_S16P

        &&s->int_sample_fmt != AV_SAMPLE_FMT_S32P

        &&s->int_sample_fmt != AV_SAMPLE_FMT_FLTP

        &&s->int_sample_fmt != AV_SAMPLE_FMT_DBLP){

        av_log(s, AV_LOG_ERROR, "Requested sample format %s is not supported internally, S16/S32/FLT/DBL is supported\n", av_get_sample_fmt_name(s->int_sample_fmt));

        return AVERROR(EINVAL);

    }



    set_audiodata_fmt(&s-> in, s-> in_sample_fmt);

    set_audiodata_fmt(&s->out, s->out_sample_fmt);



    if (s->firstpts_in_samples != AV_NOPTS_VALUE) {

        if (!s->async && s->min_compensation >= FLT_MAX/2)

            s->async = 1;

        s->firstpts =

        s->outpts   = s->firstpts_in_samples * s->out_sample_rate;

    } else

        s->firstpts = AV_NOPTS_VALUE;



    if (s->async) {

        if (s->min_compensation >= FLT_MAX/2)

            s->min_compensation = 0.001;

        if (s->async > 1.0001) {

            s->max_soft_compensation = s->async / (double) s->in_sample_rate;

        }

    }



    if (s->out_sample_rate!=s->in_sample_rate || (s->flags & SWR_FLAG_RESAMPLE)){

        s->resample = s->resampler->init(s->resample, s->out_sample_rate, s->in_sample_rate, s->filter_size, s->phase_shift, s->linear_interp, s->cutoff, s->int_sample_fmt, s->filter_type, s->kaiser_beta, s->precision, s->cheby);

        if (!s->resample) {

            av_log(s, AV_LOG_ERROR, "Failed to initilaize resampler\n");

            return AVERROR(ENOMEM);

        }

    }else

        s->resampler->free(&s->resample);

    if(    s->int_sample_fmt != AV_SAMPLE_FMT_S16P

        && s->int_sample_fmt != AV_SAMPLE_FMT_S32P

        && s->int_sample_fmt != AV_SAMPLE_FMT_FLTP

        && s->int_sample_fmt != AV_SAMPLE_FMT_DBLP

        && s->resample){

        av_log(s, AV_LOG_ERROR, "Resampling only supported with internal s16/s32/flt/dbl\n");

        return -1;

    }



#define RSC 1 //FIXME finetune

    if(!s-> in.ch_count)

        s-> in.ch_count= av_get_channel_layout_nb_channels(s-> in_ch_layout);

    if(!s->used_ch_count)

        s->used_ch_count= s->in.ch_count;

    if(!s->out.ch_count)

        s->out.ch_count= av_get_channel_layout_nb_channels(s->out_ch_layout);



    if(!s-> in.ch_count){

        av_assert0(!s->in_ch_layout);

        av_log(s, AV_LOG_ERROR, "Input channel count and layout are unset\n");

        return -1;

    }



    av_get_channel_layout_string(l1, sizeof(l1), s-> in.ch_count, s-> in_ch_layout);

    av_get_channel_layout_string(l2, sizeof(l2), s->out.ch_count, s->out_ch_layout);

    if (s->out_ch_layout && s->out.ch_count != av_get_channel_layout_nb_channels(s->out_ch_layout)) {

        av_log(s, AV_LOG_ERROR, "Output channel layout %s mismatches specified channel count %d\n", l2, s->out.ch_count);

        return AVERROR(EINVAL);

    }

    if (s->in_ch_layout && s->used_ch_count != av_get_channel_layout_nb_channels(s->in_ch_layout)) {

        av_log(s, AV_LOG_ERROR, "Input channel layout %s mismatches specified channel count %d\n", l1, s->used_ch_count);

        return AVERROR(EINVAL);

    }



    if ((!s->out_ch_layout || !s->in_ch_layout) && s->used_ch_count != s->out.ch_count && !s->rematrix_custom) {

        av_log(s, AV_LOG_ERROR, "Rematrix is needed between %s and %s "

               "but there is not enough information to do it\n", l1, l2);

        return -1;

    }



av_assert0(s->used_ch_count);

av_assert0(s->out.ch_count);

    s->resample_first= RSC*s->out.ch_count/s->in.ch_count - RSC < s->out_sample_rate/(float)s-> in_sample_rate - 1.0;



    s->in_buffer= s->in;

    s->silence  = s->in;

    s->drop_temp= s->out;



    if(!s->resample && !s->rematrix && !s->channel_map && !s->dither.method){

        s->full_convert = swri_audio_convert_alloc(s->out_sample_fmt,

                                                   s-> in_sample_fmt, s-> in.ch_count, NULL, 0);

        return 0;

    }



    s->in_convert = swri_audio_convert_alloc(s->int_sample_fmt,

                                             s-> in_sample_fmt, s->used_ch_count, s->channel_map, 0);

    s->out_convert= swri_audio_convert_alloc(s->out_sample_fmt,

                                             s->int_sample_fmt, s->out.ch_count, NULL, 0);



    if (!s->in_convert || !s->out_convert)

        return AVERROR(ENOMEM);



    s->postin= s->in;

    s->preout= s->out;

    s->midbuf= s->in;



    if(s->channel_map){

        s->postin.ch_count=

        s->midbuf.ch_count= s->used_ch_count;

        if(s->resample)

            s->in_buffer.ch_count= s->used_ch_count;

    }

    if(!s->resample_first){

        s->midbuf.ch_count= s->out.ch_count;

        if(s->resample)

            s->in_buffer.ch_count = s->out.ch_count;

    }



    set_audiodata_fmt(&s->postin, s->int_sample_fmt);

    set_audiodata_fmt(&s->midbuf, s->int_sample_fmt);

    set_audiodata_fmt(&s->preout, s->int_sample_fmt);



    if(s->resample){

        set_audiodata_fmt(&s->in_buffer, s->int_sample_fmt);

    }



    if ((ret = swri_dither_init(s, s->out_sample_fmt, s->int_sample_fmt)) < 0)

        return ret;



    if(s->rematrix || s->dither.method)

        return swri_rematrix_init(s);



    return 0;

}

int swr_convert(struct SwrContext *s, uint8_t *out_arg[SWR_CH_MAX], int out_count,

                                const uint8_t *in_arg [SWR_CH_MAX], int  in_count){

    AudioData * in= &s->in;

    AudioData *out= &s->out;



    if (!swr_is_initialized(s)) {

        av_log(s, AV_LOG_ERROR, "Context has not been initialized\n");

        return AVERROR(EINVAL);

    }



    while(s->drop_output > 0){

        int ret;

        uint8_t *tmp_arg[SWR_CH_MAX];

#define MAX_DROP_STEP 16384

        if((ret=swri_realloc_audio(&s->drop_temp, FFMIN(s->drop_output, MAX_DROP_STEP)))<0)

            return ret;



        reversefill_audiodata(&s->drop_temp, tmp_arg);

        s->drop_output *= -1; //FIXME find a less hackish solution

        ret = swr_convert(s, tmp_arg, FFMIN(-s->drop_output, MAX_DROP_STEP), in_arg, in_count); //FIXME optimize but this is as good as never called so maybe it doesn't matter

        s->drop_output *= -1;

        in_count = 0;

        if(ret>0) {

            s->drop_output -= ret;

            if (!s->drop_output && !out_arg)

                return 0;

            continue;

        }



        av_assert0(s->drop_output);

        return 0;

    }



    if(!in_arg){

        if(s->resample){

            if (!s->flushed)

                s->resampler->flush(s);

            s->resample_in_constraint = 0;

            s->flushed = 1;

        }else if(!s->in_buffer_count){

            return 0;

        }

    }else

        fill_audiodata(in ,  (void*)in_arg);



    fill_audiodata(out, out_arg);



    if(s->resample){

        int ret = swr_convert_internal(s, out, out_count, in, in_count);

        if(ret>0 && !s->drop_output)

            s->outpts += ret * (int64_t)s->in_sample_rate;

        return ret;

    }else{

        AudioData tmp= *in;

        int ret2=0;

        int ret, size;

        size = FFMIN(out_count, s->in_buffer_count);

        if(size){

            buf_set(&tmp, &s->in_buffer, s->in_buffer_index);

            ret= swr_convert_internal(s, out, size, &tmp, size);

            if(ret<0)

                return ret;

            ret2= ret;

            s->in_buffer_count -= ret;

            s->in_buffer_index += ret;

            buf_set(out, out, ret);

            out_count -= ret;

            if(!s->in_buffer_count)

                s->in_buffer_index = 0;

        }



        if(in_count){

            size= s->in_buffer_index + s->in_buffer_count + in_count - out_count;



            if(in_count > out_count) { //FIXME move after swr_convert_internal

                if(   size > s->in_buffer.count

                && s->in_buffer_count + in_count - out_count <= s->in_buffer_index){

                    buf_set(&tmp, &s->in_buffer, s->in_buffer_index);

                    copy(&s->in_buffer, &tmp, s->in_buffer_count);

                    s->in_buffer_index=0;

                }else

                    if((ret=swri_realloc_audio(&s->in_buffer, size)) < 0)

                        return ret;

            }



            if(out_count){

                size = FFMIN(in_count, out_count);

                ret= swr_convert_internal(s, out, size, in, size);

                if(ret<0)

                    return ret;

                buf_set(in, in, ret);

                in_count -= ret;

                ret2 += ret;

            }

            if(in_count){

                buf_set(&tmp, &s->in_buffer, s->in_buffer_index + s->in_buffer_count);

                copy(&tmp, in, in_count);

                s->in_buffer_count += in_count;

            }

        }

        if(ret2>0 && !s->drop_output)

            s->outpts += ret2 * (int64_t)s->in_sample_rate;

        return ret2;

    }

}

int swr_init(SwrContext *s){

    s->in_buffer_index= 0;

    s->in_buffer_count= 0;

    s->resample_in_constraint= 0;

    free_temp(&s->postin);

    free_temp(&s->midbuf);

    free_temp(&s->preout);

    free_temp(&s->in_buffer);

    swr_audio_convert_free(&s-> in_convert);

    swr_audio_convert_free(&s->out_convert);



    s-> in.planar= s-> in_sample_fmt >= 0x100;

    s->out.planar= s->out_sample_fmt >= 0x100;

    s-> in_sample_fmt &= 0xFF;

    s->out_sample_fmt &= 0xFF;



    //We assume AVOptions checked the various values and the defaults where allowed

    if(   s->int_sample_fmt != AV_SAMPLE_FMT_S16

        &&s->int_sample_fmt != AV_SAMPLE_FMT_FLT){

        av_log(s, AV_LOG_ERROR, "Requested sample format %s is not supported internally, only float & S16 is supported\n", av_get_sample_fmt_name(s->int_sample_fmt));

        return AVERROR(EINVAL);

    }



    //FIXME should we allow/support using FLT on material that doesnt need it ?

    if(s->in_sample_fmt <= AV_SAMPLE_FMT_S16 || s->int_sample_fmt==AV_SAMPLE_FMT_S16){

        s->int_sample_fmt= AV_SAMPLE_FMT_S16;

    }else

        s->int_sample_fmt= AV_SAMPLE_FMT_FLT;





    if (s->out_sample_rate!=s->in_sample_rate || (s->flags & SWR_FLAG_RESAMPLE)){

        s->resample = swr_resample_init(s->resample, s->out_sample_rate, s->in_sample_rate, 16, 10, 0, 0.8);

    }else

        swr_resample_free(&s->resample);

    if(s->int_sample_fmt != AV_SAMPLE_FMT_S16 && s->resample){

        av_log(s, AV_LOG_ERROR, "Resampling only supported with internal s16 currently\n"); //FIXME

        return -1;

    }



    if(!s-> in_ch_layout)

        s-> in_ch_layout= guess_layout(s->in.ch_count);

    if(!s->out_ch_layout)

        s->out_ch_layout= guess_layout(s->out.ch_count);



    s->rematrix= s->out_ch_layout  !=s->in_ch_layout;



#define RSC 1 //FIXME finetune

    if(!s-> in.ch_count)

        s-> in.ch_count= av_get_channel_layout_nb_channels(s-> in_ch_layout);

    if(!s->out.ch_count)

        s->out.ch_count= av_get_channel_layout_nb_channels(s->out_ch_layout);



av_assert0(s-> in.ch_count);

av_assert0(s->out.ch_count);

    s->resample_first= RSC*s->out.ch_count/s->in.ch_count - RSC < s->out_sample_rate/(float)s-> in_sample_rate - 1.0;



    s-> in.bps= av_get_bits_per_sample_fmt(s-> in_sample_fmt)/8;

    s->int_bps= av_get_bits_per_sample_fmt(s->int_sample_fmt)/8;

    s->out.bps= av_get_bits_per_sample_fmt(s->out_sample_fmt)/8;



    s->in_convert = swr_audio_convert_alloc(s->int_sample_fmt,

                                            s-> in_sample_fmt, s-> in.ch_count, 0);

    s->out_convert= swr_audio_convert_alloc(s->out_sample_fmt,

                                            s->int_sample_fmt, s->out.ch_count, 0);





    s->postin= s->in;

    s->preout= s->out;

    s->midbuf= s->in;

    s->in_buffer= s->in;

    if(!s->resample_first){

        s->midbuf.ch_count= s->out.ch_count;

        s->in_buffer.ch_count = s->out.ch_count;

    }



    s->in_buffer.bps = s->postin.bps = s->midbuf.bps = s->preout.bps =  s->int_bps;

    s->in_buffer.planar = s->postin.planar = s->midbuf.planar = s->preout.planar =  1;





    if(s->rematrix && swr_rematrix_init(s)<0)

        return -1;



    return 0;

}

int avresample_open(AVAudioResampleContext *avr)

{

    int ret;



    /* set channel mixing parameters */

    avr->in_channels = av_get_channel_layout_nb_channels(avr->in_channel_layout);

    if (avr->in_channels <= 0 || avr->in_channels > AVRESAMPLE_MAX_CHANNELS) {

        av_log(avr, AV_LOG_ERROR, "Invalid input channel layout: %"PRIu64"\n",

               avr->in_channel_layout);

        return AVERROR(EINVAL);

    }

    avr->out_channels = av_get_channel_layout_nb_channels(avr->out_channel_layout);

    if (avr->out_channels <= 0 || avr->out_channels > AVRESAMPLE_MAX_CHANNELS) {

        av_log(avr, AV_LOG_ERROR, "Invalid output channel layout: %"PRIu64"\n",

               avr->out_channel_layout);

        return AVERROR(EINVAL);

    }

    avr->resample_channels = FFMIN(avr->in_channels, avr->out_channels);

    avr->downmix_needed    = avr->in_channels  > avr->out_channels;

    avr->upmix_needed      = avr->out_channels > avr->in_channels ||

                             avr->am->matrix                      ||

                             (avr->out_channels == avr->in_channels &&

                              avr->in_channel_layout != avr->out_channel_layout);

    avr->mixing_needed     = avr->downmix_needed || avr->upmix_needed;



    /* set resampling parameters */

    avr->resample_needed   = avr->in_sample_rate != avr->out_sample_rate ||

                             avr->force_resampling;



    /* select internal sample format if not specified by the user */

    if (avr->internal_sample_fmt == AV_SAMPLE_FMT_NONE &&

        (avr->mixing_needed || avr->resample_needed)) {

        enum AVSampleFormat  in_fmt = av_get_planar_sample_fmt(avr->in_sample_fmt);

        enum AVSampleFormat out_fmt = av_get_planar_sample_fmt(avr->out_sample_fmt);

        int max_bps = FFMAX(av_get_bytes_per_sample(in_fmt),

                            av_get_bytes_per_sample(out_fmt));

        if (max_bps <= 2) {

            avr->internal_sample_fmt = AV_SAMPLE_FMT_S16P;

        } else if (avr->mixing_needed) {

            avr->internal_sample_fmt = AV_SAMPLE_FMT_FLTP;

        } else {

            if (max_bps <= 4) {

                if (in_fmt  == AV_SAMPLE_FMT_S32P ||

                    out_fmt == AV_SAMPLE_FMT_S32P) {

                    if (in_fmt  == AV_SAMPLE_FMT_FLTP ||

                        out_fmt == AV_SAMPLE_FMT_FLTP) {

                        /* if one is s32 and the other is flt, use dbl */

                        avr->internal_sample_fmt = AV_SAMPLE_FMT_DBLP;

                    } else {

                        /* if one is s32 and the other is s32, s16, or u8, use s32 */

                        avr->internal_sample_fmt = AV_SAMPLE_FMT_S32P;

                    }

                } else {

                    /* if one is flt and the other is flt, s16 or u8, use flt */

                    avr->internal_sample_fmt = AV_SAMPLE_FMT_FLTP;

                }

            } else {

                /* if either is dbl, use dbl */

                avr->internal_sample_fmt = AV_SAMPLE_FMT_DBLP;

            }

        }

        av_log(avr, AV_LOG_DEBUG, "Using %s as internal sample format\n",

               av_get_sample_fmt_name(avr->internal_sample_fmt));

    }



    /* set sample format conversion parameters */

    if (avr->in_channels == 1)

        avr->in_sample_fmt = av_get_planar_sample_fmt(avr->in_sample_fmt);

    if (avr->out_channels == 1)

        avr->out_sample_fmt = av_get_planar_sample_fmt(avr->out_sample_fmt);

    avr->in_convert_needed = (avr->resample_needed || avr->mixing_needed) &&

                              avr->in_sample_fmt != avr->internal_sample_fmt;

    if (avr->resample_needed || avr->mixing_needed)

        avr->out_convert_needed = avr->internal_sample_fmt != avr->out_sample_fmt;

    else

        avr->out_convert_needed = avr->in_sample_fmt != avr->out_sample_fmt;



    /* allocate buffers */

    if (avr->mixing_needed || avr->in_convert_needed) {

        avr->in_buffer = ff_audio_data_alloc(FFMAX(avr->in_channels, avr->out_channels),

                                             0, avr->internal_sample_fmt,

                                             "in_buffer");

        if (!avr->in_buffer) {

            ret = AVERROR(EINVAL);

            goto error;

        }

    }

    if (avr->resample_needed) {

        avr->resample_out_buffer = ff_audio_data_alloc(avr->out_channels,

                                                       0, avr->internal_sample_fmt,

                                                       "resample_out_buffer");

        if (!avr->resample_out_buffer) {

            ret = AVERROR(EINVAL);

            goto error;

        }

    }

    if (avr->out_convert_needed) {

        avr->out_buffer = ff_audio_data_alloc(avr->out_channels, 0,

                                              avr->out_sample_fmt, "out_buffer");

        if (!avr->out_buffer) {

            ret = AVERROR(EINVAL);

            goto error;

        }

    }

    avr->out_fifo = av_audio_fifo_alloc(avr->out_sample_fmt, avr->out_channels,

                                        1024);

    if (!avr->out_fifo) {

        ret = AVERROR(ENOMEM);

        goto error;

    }



    /* setup contexts */

    if (avr->in_convert_needed) {

        avr->ac_in = ff_audio_convert_alloc(avr, avr->internal_sample_fmt,

                                            avr->in_sample_fmt, avr->in_channels);

        if (!avr->ac_in) {

            ret = AVERROR(ENOMEM);

            goto error;

        }

    }

    if (avr->out_convert_needed) {

        enum AVSampleFormat src_fmt;

        if (avr->in_convert_needed)

            src_fmt = avr->internal_sample_fmt;

        else

            src_fmt = avr->in_sample_fmt;

        avr->ac_out = ff_audio_convert_alloc(avr, avr->out_sample_fmt, src_fmt,

                                             avr->out_channels);

        if (!avr->ac_out) {

            ret = AVERROR(ENOMEM);

            goto error;

        }

    }

    if (avr->resample_needed) {

        avr->resample = ff_audio_resample_init(avr);

        if (!avr->resample) {

            ret = AVERROR(ENOMEM);

            goto error;

        }

    }

    if (avr->mixing_needed) {

        ret = ff_audio_mix_init(avr);

        if (ret < 0)

            goto error;

    }



    return 0;



error:

    avresample_close(avr);

    return ret;

}

void pc_hot_add_cpu(const int64_t id, Error **errp)

{

    X86CPU *cpu;

    ObjectClass *oc;

    PCMachineState *pcms = PC_MACHINE(qdev_get_machine());

    int64_t apic_id = x86_cpu_apic_id_from_index(id);

    Error *local_err = NULL;



    if (id < 0) {

        error_setg(errp, "Invalid CPU id: %" PRIi64, id);

        return;

    }



    if (cpu_exists(apic_id)) {

        error_setg(errp, "Unable to add CPU: %" PRIi64

                   ", it already exists", id);

        return;

    }



    if (id >= max_cpus) {

        error_setg(errp, "Unable to add CPU: %" PRIi64

                   ", max allowed: %d", id, max_cpus - 1);

        return;

    }



    if (apic_id >= ACPI_CPU_HOTPLUG_ID_LIMIT) {

        error_setg(errp, "Unable to add CPU: %" PRIi64

                   ", resulting APIC ID (%" PRIi64 ") is too large",

                   id, apic_id);

        return;

    }



    assert(pcms->possible_cpus->cpus[0].cpu); /* BSP is always present */

    oc = OBJECT_CLASS(CPU_GET_CLASS(pcms->possible_cpus->cpus[0].cpu));

    cpu = pc_new_cpu(object_class_get_name(oc), apic_id, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }

    object_unref(OBJECT(cpu));

}

static void x86_cpuid_set_apic_id(Object *obj, Visitor *v, const char *name,

                                  void *opaque, Error **errp)

{

    X86CPU *cpu = X86_CPU(obj);

    DeviceState *dev = DEVICE(obj);

    const int64_t min = 0;

    const int64_t max = UINT32_MAX;

    Error *error = NULL;

    int64_t value;



    if (dev->realized) {

        error_setg(errp, "Attempt to set property '%s' on '%s' after "

                   "it was realized", name, object_get_typename(obj));

        return;

    }



    visit_type_int(v, name, &value, &error);

    if (error) {

        error_propagate(errp, error);

        return;

    }

    if (value < min || value > max) {

        error_setg(errp, "Property %s.%s doesn't take value %" PRId64

                   " (minimum: %" PRId64 ", maximum: %" PRId64 ")" ,

                   object_get_typename(obj), name, value, min, max);

        return;

    }



    if ((value != cpu->apic_id) && cpu_exists(value)) {

        error_setg(errp, "CPU with APIC ID %" PRIi64 " exists", value);

        return;

    }

    cpu->apic_id = value;

}

static X86CPU *pc_new_cpu(const char *cpu_model, int64_t apic_id,

                          DeviceState *icc_bridge, Error **errp)

{

    X86CPU *cpu = NULL;

    Error *local_err = NULL;



    if (icc_bridge == NULL) {

        error_setg(&local_err, "Invalid icc-bridge value");

        goto out;

    }



    cpu = cpu_x86_create(cpu_model, &local_err);

    if (local_err != NULL) {

        goto out;

    }



    qdev_set_parent_bus(DEVICE(cpu), qdev_get_child_bus(icc_bridge, "icc"));



    object_property_set_int(OBJECT(cpu), apic_id, "apic-id", &local_err);

    object_property_set_bool(OBJECT(cpu), true, "realized", &local_err);



out:

    if (local_err) {

        error_propagate(errp, local_err);

        object_unref(OBJECT(cpu));

        cpu = NULL;

    }

    return cpu;

}

void pc_cpus_init(const char *cpu_model, DeviceState *icc_bridge)

{

    int i;

    X86CPU *cpu = NULL;

    Error *error = NULL;

    unsigned long apic_id_limit;



    /* init CPUs */

    if (cpu_model == NULL) {

#ifdef TARGET_X86_64

        cpu_model = "qemu64";

#else

        cpu_model = "qemu32";

#endif

    }

    current_cpu_model = cpu_model;



    apic_id_limit = pc_apic_id_limit(max_cpus);

    if (apic_id_limit > ACPI_CPU_HOTPLUG_ID_LIMIT) {

        error_report("max_cpus is too large. APIC ID of last CPU is %lu",

                     apic_id_limit - 1);

        exit(1);

    }



    for (i = 0; i < smp_cpus; i++) {

        cpu = pc_new_cpu(cpu_model, x86_cpu_apic_id_from_index(i),

                         icc_bridge, &error);

        if (error) {

            error_report_err(error);

            exit(1);

        }

        object_unref(OBJECT(cpu));

    }



    /* tell smbios about cpuid version and features */

    smbios_set_cpuid(cpu->env.cpuid_version, cpu->env.features[FEAT_1_EDX]);

}

static void openrisc_sim_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    OpenRISCCPU *cpu = NULL;

    MemoryRegion *ram;

    int n;



    if (!cpu_model) {

        cpu_model = "or1200";

    }



    for (n = 0; n < smp_cpus; n++) {

        cpu = OPENRISC_CPU(cpu_generic_init(TYPE_OPENRISC_CPU, cpu_model));

        if (cpu == NULL) {

            fprintf(stderr, "Unable to find CPU definition!\n");

            exit(1);

        }

        qemu_register_reset(main_cpu_reset, cpu);

        main_cpu_reset(cpu);

    }



    ram = g_malloc(sizeof(*ram));

    memory_region_init_ram(ram, NULL, "openrisc.ram", ram_size, &error_fatal);

    memory_region_add_subregion(get_system_memory(), 0, ram);



    cpu_openrisc_pic_init(cpu);

    cpu_openrisc_clock_init(cpu);



    serial_mm_init(get_system_memory(), 0x90000000, 0, cpu->env.irq[2],

                   115200, serial_hds[0], DEVICE_NATIVE_ENDIAN);



    if (nd_table[0].used) {

        openrisc_sim_net_init(get_system_memory(), 0x92000000,

                              0x92000400, cpu->env.irq[4], nd_table);

    }



    cpu_openrisc_load_kernel(ram_size, kernel_filename, cpu);

}

static void xlnx_ep108_init(MachineState *machine)

{

    XlnxEP108 *s = g_new0(XlnxEP108, 1);

    int i;

    uint64_t ram_size = machine->ram_size;



    /* Create the memory region to pass to the SoC */

    if (ram_size > XLNX_ZYNQMP_MAX_RAM_SIZE) {

        error_report("ERROR: RAM size 0x%" PRIx64 " above max supported of "

                     "0x%llx", ram_size,

                     XLNX_ZYNQMP_MAX_RAM_SIZE);

        exit(1);

    }



    if (ram_size < 0x08000000) {

        qemu_log("WARNING: RAM size 0x%" PRIx64 " is small for EP108",

                 ram_size);

    }



    memory_region_allocate_system_memory(&s->ddr_ram, NULL, "ddr-ram",

                                         ram_size);



    object_initialize(&s->soc, sizeof(s->soc), TYPE_XLNX_ZYNQMP);

    object_property_add_child(OBJECT(machine), "soc", OBJECT(&s->soc),

                              &error_abort);



    object_property_set_link(OBJECT(&s->soc), OBJECT(&s->ddr_ram),

                         "ddr-ram", &error_abort);



    object_property_set_bool(OBJECT(&s->soc), true, "realized", &error_fatal);



    /* Create and plug in the SD cards */

    for (i = 0; i < XLNX_ZYNQMP_NUM_SDHCI; i++) {

        BusState *bus;

        DriveInfo *di = drive_get_next(IF_SD);

        BlockBackend *blk = di ? blk_by_legacy_dinfo(di) : NULL;

        DeviceState *carddev;

        char *bus_name;



        bus_name = g_strdup_printf("sd-bus%d", i);

        bus = qdev_get_child_bus(DEVICE(&s->soc), bus_name);

        g_free(bus_name);

        if (!bus) {

            error_report("No SD bus found for SD card %d", i);

            exit(1);

        }

        carddev = qdev_create(bus, TYPE_SD_CARD);

        qdev_prop_set_drive(carddev, "drive", blk, &error_fatal);

        object_property_set_bool(OBJECT(carddev), true, "realized",

                                 &error_fatal);

    }



    for (i = 0; i < XLNX_ZYNQMP_NUM_SPIS; i++) {

        SSIBus *spi_bus;

        DeviceState *flash_dev;

        qemu_irq cs_line;

        DriveInfo *dinfo = drive_get_next(IF_MTD);

        gchar *bus_name = g_strdup_printf("spi%d", i);



        spi_bus = (SSIBus *)qdev_get_child_bus(DEVICE(&s->soc), bus_name);

        g_free(bus_name);



        flash_dev = ssi_create_slave_no_init(spi_bus, "sst25wf080");

        if (dinfo) {

            qdev_prop_set_drive(flash_dev, "drive", blk_by_legacy_dinfo(dinfo),

                                &error_fatal);

        }

        qdev_init_nofail(flash_dev);



        cs_line = qdev_get_gpio_in_named(flash_dev, SSI_GPIO_CS, 0);



        sysbus_connect_irq(SYS_BUS_DEVICE(&s->soc.spi[i]), 1, cs_line);

    }



    /* TODO create and connect IDE devices for ide_drive_get() */



    xlnx_ep108_binfo.ram_size = ram_size;

    xlnx_ep108_binfo.kernel_filename = machine->kernel_filename;

    xlnx_ep108_binfo.kernel_cmdline = machine->kernel_cmdline;

    xlnx_ep108_binfo.initrd_filename = machine->initrd_filename;

    xlnx_ep108_binfo.loader_start = 0;

    arm_load_kernel(s->soc.boot_cpu_ptr, &xlnx_ep108_binfo);

}

static void kzm_init(MachineState *machine)

{

    IMX31KZM *s = g_new0(IMX31KZM, 1);

    unsigned int ram_size;

    unsigned int alias_offset;

    unsigned int i;



    object_initialize(&s->soc, sizeof(s->soc), TYPE_FSL_IMX31);

    object_property_add_child(OBJECT(machine), "soc", OBJECT(&s->soc),

                              &error_abort);



    object_property_set_bool(OBJECT(&s->soc), true, "realized", &error_fatal);



    /* Check the amount of memory is compatible with the SOC */

    if (machine->ram_size > (FSL_IMX31_SDRAM0_SIZE + FSL_IMX31_SDRAM1_SIZE)) {

        error_report("WARNING: RAM size " RAM_ADDR_FMT " above max supported, "

                     "reduced to %x", machine->ram_size,

                     FSL_IMX31_SDRAM0_SIZE + FSL_IMX31_SDRAM1_SIZE);

        machine->ram_size = FSL_IMX31_SDRAM0_SIZE + FSL_IMX31_SDRAM1_SIZE;

    }



    memory_region_allocate_system_memory(&s->ram, NULL, "kzm.ram",

                                         machine->ram_size);

    memory_region_add_subregion(get_system_memory(), FSL_IMX31_SDRAM0_ADDR,

                                &s->ram);



    /* initialize the alias memory if any */

    for (i = 0, ram_size = machine->ram_size, alias_offset = 0;

         (i < 2) && ram_size; i++) {

        unsigned int size;

        static const struct {

            hwaddr addr;

            unsigned int size;

        } ram[2] = {

            { FSL_IMX31_SDRAM0_ADDR, FSL_IMX31_SDRAM0_SIZE },

            { FSL_IMX31_SDRAM1_ADDR, FSL_IMX31_SDRAM1_SIZE },

        };



        size = MIN(ram_size, ram[i].size);



        ram_size -= size;



        if (size < ram[i].size) {

            memory_region_init_alias(&s->ram_alias, NULL, "ram.alias",

                                     &s->ram, alias_offset, ram[i].size - size);

            memory_region_add_subregion(get_system_memory(),

                                        ram[i].addr + size, &s->ram_alias);

        }



        alias_offset += ram[i].size;

    }



    if (nd_table[0].used) {

        lan9118_init(&nd_table[0], KZM_LAN9118_ADDR,

                     qdev_get_gpio_in(DEVICE(&s->soc.avic), 52));

    }



    if (serial_hds[2]) { /* touchscreen */

        serial_mm_init(get_system_memory(), KZM_FPGA_ADDR+0x10, 0,

                       qdev_get_gpio_in(DEVICE(&s->soc.avic), 52),

                       14745600, serial_hds[2], DEVICE_NATIVE_ENDIAN);

    }



    kzm_binfo.ram_size = machine->ram_size;

    kzm_binfo.kernel_filename = machine->kernel_filename;

    kzm_binfo.kernel_cmdline = machine->kernel_cmdline;

    kzm_binfo.initrd_filename = machine->initrd_filename;

    kzm_binfo.nb_cpus = 1;



    if (!qtest_enabled()) {

        arm_load_kernel(&s->soc.cpu, &kzm_binfo);

    }

}

static void ppc_powernv_init(MachineState *machine)

{

    PnvMachineState *pnv = POWERNV_MACHINE(machine);

    MemoryRegion *ram;

    char *fw_filename;

    long fw_size;

    int i;

    char *chip_typename;



    /* allocate RAM */

    if (machine->ram_size < (1 * G_BYTE)) {

        error_report("Warning: skiboot may not work with < 1GB of RAM");

    }



    ram = g_new(MemoryRegion, 1);

    memory_region_allocate_system_memory(ram, NULL, "ppc_powernv.ram",

                                         machine->ram_size);

    memory_region_add_subregion(get_system_memory(), 0, ram);



    /* load skiboot firmware  */

    if (bios_name == NULL) {

        bios_name = FW_FILE_NAME;

    }



    fw_filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);



    fw_size = load_image_targphys(fw_filename, FW_LOAD_ADDR, FW_MAX_SIZE);

    if (fw_size < 0) {

        error_report("Could not load OPAL '%s'", fw_filename);

        exit(1);

    }

    g_free(fw_filename);



    /* load kernel */

    if (machine->kernel_filename) {

        long kernel_size;



        kernel_size = load_image_targphys(machine->kernel_filename,

                                          KERNEL_LOAD_ADDR, 0x2000000);

        if (kernel_size < 0) {

            error_report("Could not load kernel '%s'",

                         machine->kernel_filename);

            exit(1);

        }

    }



    /* load initrd */

    if (machine->initrd_filename) {

        pnv->initrd_base = INITRD_LOAD_ADDR;

        pnv->initrd_size = load_image_targphys(machine->initrd_filename,

                                  pnv->initrd_base, 0x10000000); /* 128MB max */

        if (pnv->initrd_size < 0) {

            error_report("Could not load initial ram disk '%s'",

                         machine->initrd_filename);

            exit(1);

        }

    }



    /* We need some cpu model to instantiate the PnvChip class */

    if (machine->cpu_model == NULL) {

        machine->cpu_model = "POWER8";

    }



    /* Create the processor chips */

    chip_typename = g_strdup_printf(TYPE_PNV_CHIP "-%s", machine->cpu_model);

    if (!object_class_by_name(chip_typename)) {

        error_report("invalid CPU model '%s' for %s machine",

                     machine->cpu_model, MACHINE_GET_CLASS(machine)->name);

        exit(1);

    }



    pnv->chips = g_new0(PnvChip *, pnv->num_chips);

    for (i = 0; i < pnv->num_chips; i++) {

        char chip_name[32];

        Object *chip = object_new(chip_typename);



        pnv->chips[i] = PNV_CHIP(chip);



        /* TODO: put all the memory in one node on chip 0 until we find a

         * way to specify different ranges for each chip

         */

        if (i == 0) {

            object_property_set_int(chip, machine->ram_size, "ram-size",

                                    &error_fatal);

        }



        snprintf(chip_name, sizeof(chip_name), "chip[%d]", PNV_CHIP_HWID(i));

        object_property_add_child(OBJECT(pnv), chip_name, chip, &error_fatal);

        object_property_set_int(chip, PNV_CHIP_HWID(i), "chip-id",

                                &error_fatal);

        object_property_set_int(chip, smp_cores, "nr-cores", &error_fatal);

        object_property_set_bool(chip, true, "realized", &error_fatal);

    }

    g_free(chip_typename);



    /* Instantiate ISA bus on chip 0 */

    pnv->isa_bus = pnv_isa_create(pnv->chips[0]);



    /* Create serial port */

    serial_hds_isa_init(pnv->isa_bus, 0, MAX_SERIAL_PORTS);



    /* Create an RTC ISA device too */

    rtc_init(pnv->isa_bus, 2000, NULL);



    /* OpenPOWER systems use a IPMI SEL Event message to notify the

     * host to powerdown */

    pnv->powerdown_notifier.notify = pnv_powerdown_notify;

    qemu_register_powerdown_notifier(&pnv->powerdown_notifier);

}

static int parse_outputs(const char **buf, AVFilterInOut **curr_inputs,

                         AVFilterInOut **open_inputs,

                         AVFilterInOut **open_outputs, AVClass *log_ctx)

{

    int ret, pad = 0;



    while (**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        AVFilterInOut *input = *curr_inputs;







        *curr_inputs = (*curr_inputs)->next;



        if (!name)




        /* First check if the label is not in the open_inputs list */

        match = extract_inout(name, open_inputs);



        if (match) {

            if ((ret = link_filter(input->filter_ctx, input->pad_idx,

                                   match->filter_ctx, match->pad_idx, log_ctx)) < 0)

                return ret;

            av_free(match->name);

            av_free(name);

            av_free(match);

            av_free(input);

        } else {

            /* Not in the list, so add the first input as a open_output */

            input->name = name;

            insert_inout(open_outputs, input);


        *buf += strspn(*buf, WHITESPACES);

        pad++;




    return pad;

static int parse_inputs(const char **buf, AVFilterInOut **currInputs,

                        AVFilterInOut **openLinks, AVClass *log_ctx)

{

    int pad = 0;



    while(**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        if(!name)

            return -1;



        /* First check if the label is not in the openLinks list */

        match = extract_inout(name, openLinks);



        if(match) {

            /* A label of a open link. Make it one of the inputs of the next

               filter */

            if(match->type != LinkTypeOut) {

                av_log(log_ctx, AV_LOG_ERROR,

                       "Label \"%s\" appears twice as input!\n", match->name);

                return -1;

            }


        } else {

            /* Not in the list, so add it as an input */

            match = av_mallocz(sizeof(AVFilterInOut));

            match->name    = name;

            match->type    = LinkTypeIn;

            match->pad_idx = pad;

        }



        insert_inout(currInputs, match);



        *buf += consume_whitespace(*buf);

        pad++;

    }



    return pad;

}

static int parse_inputs(const char **buf, AVFilterInOut **curr_inputs,

                        AVFilterInOut **open_outputs, AVClass *log_ctx)

{

    int pad = 0;



    while (**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        if (!name)

            return -1;



        /* First check if the label is not in the open_outputs list */

        match = extract_inout(name, open_outputs);



        if (match) {

            av_free(name);

        } else {

            /* Not in the list, so add it as an input */

            match = av_mallocz(sizeof(AVFilterInOut));

            match->name    = name;

            match->pad_idx = pad;

        }



        insert_inout(curr_inputs, match);



        *buf += strspn(*buf, WHITESPACES);

        pad++;

    }



    return pad;

}

int avfilter_parse_graph(AVFilterGraph *graph, const char *filters,

                         AVFilterInOut *open_inputs,

                         AVFilterInOut *open_outputs, AVClass *log_ctx)

{

    int index = 0;

    char chr = 0;



    AVFilterInOut *curr_inputs = NULL;



    do {

        AVFilterContext *filter;

        filters += consume_whitespace(filters);



        if(parse_inputs(&filters, &curr_inputs, &open_outputs, log_ctx) < 0)

            goto fail;



        filter = parse_filter(&filters, graph, index, log_ctx);



        if(!filter)

            goto fail;



        if(filter->input_count == 1 && !curr_inputs && !index) {

            /* First input can be omitted if it is "[in]" */

            const char *tmp = "[in]";

            if(parse_inputs(&tmp, &curr_inputs, &open_outputs, log_ctx) < 0)

                goto fail;

        }



        if(link_filter_inouts(filter, &curr_inputs, &open_inputs, log_ctx) < 0)

            goto fail;



        if(parse_outputs(&filters, &curr_inputs, &open_inputs, &open_outputs,

                         log_ctx) < 0)

            goto fail;



        filters += consume_whitespace(filters);

        chr = *filters++;



        if(chr == ';' && curr_inputs) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Could not find a output to link when parsing \"%s\"\n",

                   filters - 1);

            goto fail;

        }

        index++;

    } while(chr == ',' || chr == ';');



    if (*filters) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Unable to parse graph description substring: \"%s\"\n",

               filters - 1);

        goto fail;

    }



    if(open_inputs && !strcmp(open_inputs->name, "out") && curr_inputs) {

        /* Last output can be omitted if it is "[out]" */

        const char *tmp = "[out]";

        if(parse_outputs(&tmp, &curr_inputs, &open_inputs,

                         &open_outputs, log_ctx) < 0)

            goto fail;

    }



    return 0;



 fail:

    avfilter_destroy_graph(graph);

    free_inout(open_inputs);

    free_inout(open_outputs);

    free_inout(curr_inputs);

    return -1;

}

void vp8_mc_luma(VP8Context *s, VP8ThreadData *td, uint8_t *dst,

                 ThreadFrame *ref, const VP56mv *mv,

                 int x_off, int y_off, int block_w, int block_h,

                 int width, int height, int linesize,

                 vp8_mc_func mc_func[3][3])

{

    uint8_t *src = ref->f->data[0];



    if (AV_RN32A(mv)) {



        int mx = (mv->x << 1)&7, mx_idx = subpel_idx[0][mx];

        int my = (mv->y << 1)&7, my_idx = subpel_idx[0][my];



        x_off += mv->x >> 2;

        y_off += mv->y >> 2;



        // edge emulation

        ff_thread_await_progress(ref, (3 + y_off + block_h + subpel_idx[2][my]) >> 4, 0);

        src += y_off * linesize + x_off;

        if (x_off < mx_idx || x_off >= width  - block_w - subpel_idx[2][mx] ||

            y_off < my_idx || y_off >= height - block_h - subpel_idx[2][my]) {

            s->vdsp.emulated_edge_mc(td->edge_emu_buffer, src - my_idx * linesize - mx_idx, linesize,

                                     block_w + subpel_idx[1][mx], block_h + subpel_idx[1][my],

                                     x_off - mx_idx, y_off - my_idx, width, height);

            src = td->edge_emu_buffer + mx_idx + linesize * my_idx;

        }

        mc_func[my_idx][mx_idx](dst, linesize, src, linesize, block_h, mx, my);

    } else {

        ff_thread_await_progress(ref, (3 + y_off + block_h) >> 4, 0);

        mc_func[0][0](dst, linesize, src + y_off * linesize + x_off, linesize, block_h, 0, 0);

    }

}

static av_always_inline void mc_chroma_unscaled(VP9Context *s, vp9_mc_func (*mc)[2],

                                                uint8_t *dst_u, uint8_t *dst_v,

                                                ptrdiff_t dst_stride,

                                                const uint8_t *ref_u, ptrdiff_t src_stride_u,

                                                const uint8_t *ref_v, ptrdiff_t src_stride_v,

                                                ThreadFrame *ref_frame,

                                                ptrdiff_t y, ptrdiff_t x, const VP56mv *mv,

                                                int bw, int bh, int w, int h, int bytesperpixel)

{

    int mx = mv->x * (1 << !s->ss_h), my = mv->y * (1 << !s->ss_v), th;



    y += my >> 4;

    x += mx >> 4;

    ref_u += y * src_stride_u + x * bytesperpixel;

    ref_v += y * src_stride_v + x * bytesperpixel;

    mx &= 15;

    my &= 15;

    // FIXME bilinear filter only needs 0/1 pixels, not 3/4

    // we use +7 because the last 7 pixels of each sbrow can be changed in

    // the longest loopfilter of the next sbrow

    th = (y + bh + 4 * !!my + 7) >> (6 - s->ss_v);

    ff_thread_await_progress(ref_frame, FFMAX(th, 0), 0);

    if (x < !!mx * 3 || y < !!my * 3 ||

        x + !!mx * 4 > w - bw || y + !!my * 4 > h - bh) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_u - !!my * 3 * src_stride_u - !!mx * 3 * bytesperpixel,

                                 160, src_stride_u,

                                 bw + !!mx * 7, bh + !!my * 7,

                                 x - !!mx * 3, y - !!my * 3, w, h);

        ref_u = s->edge_emu_buffer + !!my * 3 * 160 + !!mx * 3 * bytesperpixel;

        mc[!!mx][!!my](dst_u, dst_stride, ref_u, 160, bh, mx, my);



        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_v - !!my * 3 * src_stride_v - !!mx * 3 * bytesperpixel,

                                 160, src_stride_v,

                                 bw + !!mx * 7, bh + !!my * 7,

                                 x - !!mx * 3, y - !!my * 3, w, h);

        ref_v = s->edge_emu_buffer + !!my * 3 * 160 + !!mx * 3 * bytesperpixel;

        mc[!!mx][!!my](dst_v, dst_stride, ref_v, 160, bh, mx, my);

    } else {

        mc[!!mx][!!my](dst_u, dst_stride, ref_u, src_stride_u, bh, mx, my);

        mc[!!mx][!!my](dst_v, dst_stride, ref_v, src_stride_v, bh, mx, my);

    }

}

static inline void chroma_4mv_motion_lowres(MpegEncContext *s,

                                            uint8_t *dest_cb, uint8_t *dest_cr,

                                            uint8_t **ref_picture,

                                            h264_chroma_mc_func * pix_op,

                                            int mx, int my)

{

    const int lowres     = s->avctx->lowres;

    const int op_index   = FFMIN(lowres, 2);

    const int block_s    = 8 >> lowres;

    const int s_mask     = (2 << lowres) - 1;

    const int h_edge_pos = s->h_edge_pos >> lowres + 1;

    const int v_edge_pos = s->v_edge_pos >> lowres + 1;

    int emu = 0, src_x, src_y, offset, sx, sy;

    uint8_t *ptr;



    if (s->quarter_sample) {

        mx /= 2;

        my /= 2;

    }



    /* In case of 8X8, we construct a single chroma motion vector

       with a special rounding */

    mx = ff_h263_round_chroma(mx);

    my = ff_h263_round_chroma(my);



    sx = mx & s_mask;

    sy = my & s_mask;

    src_x = s->mb_x * block_s + (mx >> lowres + 1);

    src_y = s->mb_y * block_s + (my >> lowres + 1);



    offset = src_y * s->uvlinesize + src_x;

    ptr = ref_picture[1] + offset;

    if (s->flags & CODEC_FLAG_EMU_EDGE) {

        if ((unsigned) src_x > FFMAX(h_edge_pos - (!!sx) - block_s, 0) ||

            (unsigned) src_y > FFMAX(v_edge_pos - (!!sy) - block_s, 0)) {

            s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, s->uvlinesize,

                                    9, 9, src_x, src_y, h_edge_pos, v_edge_pos);

            ptr = s->edge_emu_buffer;

            emu = 1;

        }

    }

    sx = (sx << 2) >> lowres;

    sy = (sy << 2) >> lowres;

    pix_op[op_index](dest_cb, ptr, s->uvlinesize, block_s, sx, sy);



    ptr = ref_picture[2] + offset;

    if (emu) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, s->uvlinesize, 9, 9,

                                src_x, src_y, h_edge_pos, v_edge_pos);

        ptr = s->edge_emu_buffer;

    }

    pix_op[op_index](dest_cr, ptr, s->uvlinesize, block_s, sx, sy);

}

static av_always_inline void mc_chroma_scaled(VP9Context *s, vp9_scaled_mc_func smc,

                                              vp9_mc_func (*mc)[2],

                                              uint8_t *dst_u, uint8_t *dst_v,

                                              ptrdiff_t dst_stride,

                                              const uint8_t *ref_u, ptrdiff_t src_stride_u,

                                              const uint8_t *ref_v, ptrdiff_t src_stride_v,

                                              ThreadFrame *ref_frame,

                                              ptrdiff_t y, ptrdiff_t x, const VP56mv *in_mv,

                                              int px, int py, int pw, int ph,

                                              int bw, int bh, int w, int h, int bytesperpixel,

                                              const uint16_t *scale, const uint8_t *step)

{

    if (s->s.frames[CUR_FRAME].tf.f->width == ref_frame->f->width &&

        s->s.frames[CUR_FRAME].tf.f->height == ref_frame->f->height) {

        mc_chroma_unscaled(s, mc, dst_u, dst_v, dst_stride, ref_u, src_stride_u,

                           ref_v, src_stride_v, ref_frame,

                           y, x, in_mv, bw, bh, w, h, bytesperpixel);

    } else {

    int mx, my;

    int refbw_m1, refbh_m1;

    int th;

    VP56mv mv;



    if (s->ss_h) {

        // BUG https://code.google.com/p/webm/issues/detail?id=820

        mv.x = av_clip(in_mv->x, -(x + pw - px + 4) * 16, (s->cols * 4 - x + px + 3) * 16);

        mx = scale_mv(mv.x, 0) + (scale_mv(x * 16, 0) & ~15) + (scale_mv(x * 32, 0) & 15);

    } else {

        mv.x = av_clip(in_mv->x, -(x + pw - px + 4) * 8, (s->cols * 8 - x + px + 3) * 8);

        mx = scale_mv(mv.x * 2, 0) + scale_mv(x * 16, 0);

    }

    if (s->ss_v) {

        // BUG https://code.google.com/p/webm/issues/detail?id=820

        mv.y = av_clip(in_mv->y, -(y + ph - py + 4) * 16, (s->rows * 4 - y + py + 3) * 16);

        my = scale_mv(mv.y, 1) + (scale_mv(y * 16, 1) & ~15) + (scale_mv(y * 32, 1) & 15);

    } else {

        mv.y = av_clip(in_mv->y, -(y + ph - py + 4) * 8, (s->rows * 8 - y + py + 3) * 8);

        my = scale_mv(mv.y * 2, 1) + scale_mv(y * 16, 1);

    }

#undef scale_mv

    y = my >> 4;

    x = mx >> 4;

    ref_u += y * src_stride_u + x * bytesperpixel;

    ref_v += y * src_stride_v + x * bytesperpixel;

    mx &= 15;

    my &= 15;

    refbw_m1 = ((bw - 1) * step[0] + mx) >> 4;

    refbh_m1 = ((bh - 1) * step[1] + my) >> 4;

    // FIXME bilinear filter only needs 0/1 pixels, not 3/4

    // we use +7 because the last 7 pixels of each sbrow can be changed in

    // the longest loopfilter of the next sbrow

    th = (y + refbh_m1 + 4 + 7) >> (6 - s->ss_v);

    ff_thread_await_progress(ref_frame, FFMAX(th, 0), 0);

    if (x < 3 || y < 3 || x + 4 >= w - refbw_m1 || y + 4 >= h - refbh_m1) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_u - 3 * src_stride_u - 3 * bytesperpixel,

                                 288, src_stride_u,

                                 refbw_m1 + 8, refbh_m1 + 8,

                                 x - 3, y - 3, w, h);

        ref_u = s->edge_emu_buffer + 3 * 288 + 3 * bytesperpixel;

        smc(dst_u, dst_stride, ref_u, 288, bh, mx, my, step[0], step[1]);



        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_v - 3 * src_stride_v - 3 * bytesperpixel,

                                 288, src_stride_v,

                                 refbw_m1 + 8, refbh_m1 + 8,

                                 x - 3, y - 3, w, h);

        ref_v = s->edge_emu_buffer + 3 * 288 + 3 * bytesperpixel;

        smc(dst_v, dst_stride, ref_v, 288, bh, mx, my, step[0], step[1]);

    } else {

        smc(dst_u, dst_stride, ref_u, src_stride_u, bh, mx, my, step[0], step[1]);

        smc(dst_v, dst_stride, ref_v, src_stride_v, bh, mx, my, step[0], step[1]);

    }

    }

}

static void conv411(uint8_t *dst, int dst_wrap, 
                    uint8_t *src, int src_wrap,
                    int width, int height)
{
    int w, c;
    uint8_t *s1, *s2, *d;
    for(;height > 0; height--) {
        s1 = src;
        s2 = src + src_wrap;
        d = dst;
        for(w = width;w > 0; w--) {
            c = (s1[0] + s2[0]) >> 1;
            d[0] = c;
            d[1] = c;
            s1++;
            s2++;
            d += 2;
        }
        src += src_wrap * 2;
        dst += dst_wrap;
    }
}

static void rgb24_to_yuvj444p(AVPicture *dst, AVPicture *src,

                              int width, int height)

{

    int src_wrap, x, y;

    int r, g, b;

    uint8_t *lum, *cb, *cr;

    const uint8_t *p;



    lum = dst->data[0];

    cb = dst->data[1];

    cr = dst->data[2];



    src_wrap = src->linesize[0] - width * BPP;

    p = src->data[0];

    for(y=0;y<height;y++) {

        for(x=0;x<width;x++) {

            RGB_IN(r, g, b, p);

            lum[0] = RGB_TO_Y(r, g, b);

            cb[0] = RGB_TO_U(r, g, b, 0);

            cr[0] = RGB_TO_V(r, g, b, 0);

            cb++;

            cr++;

            lum++;

        }

        p += src_wrap;

        lum += dst->linesize[0] - width;

        cb += dst->linesize[1] - width;

        cr += dst->linesize[2] - width;

    }

}

static void rgb24_to_rgb555(AVPicture *dst, AVPicture *src,

                            int width, int height)

{

    const unsigned char *p;

    unsigned char *q;

    int r, g, b, dst_wrap, src_wrap;

    int x, y;



    p = src->data[0];

    src_wrap = src->linesize[0] - 3 * width;



    q = dst->data[0];

    dst_wrap = dst->linesize[0] - 2 * width;



    for(y=0;y<height;y++) {

        for(x=0;x<width;x++) {

            r = p[0];

            g = p[1];

            b = p[2];



            ((unsigned short *)q)[0] = 

                ((r >> 3) << 10) | ((g >> 3) << 5) | (b >> 3) | 0x8000;

            q += 2;

            p += 3;

        }

        p += src_wrap;

        q += dst_wrap;

    }

}

static void rgba32_to_rgb24(AVPicture *dst, AVPicture *src,

                            int width, int height)

{

    const uint8_t *s;

    uint8_t *d;

    int src_wrap, dst_wrap, j, y;

    unsigned int v;



    s = src->data[0];

    src_wrap = src->linesize[0] - width * 4;



    d = dst->data[0];

    dst_wrap = dst->linesize[0] - width * 3;



    for(y=0;y<height;y++) {

        for(j = 0;j < width; j++) {

            v = *(uint32_t *)s;

            s += 4;

            d[0] = v >> 16;

            d[1] = v >> 8;

            d[2] = v;

            d += 3;

        }

        s += src_wrap;

        d += dst_wrap;

    }

}

static void pciej_write(void *opaque, uint32_t addr, uint32_t val)

{

    BusState *bus = opaque;

    DeviceState *qdev, *next;

    PCIDevice *dev;

    int slot = ffs(val) - 1;



    QLIST_FOREACH_SAFE(qdev, &bus->children, sibling, next) {

        dev = DO_UPCAST(PCIDevice, qdev, qdev);

        if (PCI_SLOT(dev->devfn) == slot) {

            qdev_free(qdev);

        }

    }





    PIIX4_DPRINTF("pciej write %x <== %d\n", addr, val);

}

static char *isabus_get_fw_dev_path(DeviceState *dev)

{

    ISADevice *d = (ISADevice*)dev;

    char path[40];

    int off;



    off = snprintf(path, sizeof(path), "%s", qdev_fw_name(dev));

    if (d->ioport_id) {

        snprintf(path + off, sizeof(path) - off, "@%04x", d->ioport_id);

    }



    return strdup(path);

}

static void pci_get_node_name(char *nodename, int len, PCIDevice *dev)

{

    int slot = PCI_SLOT(dev->devfn);

    int func = PCI_FUNC(dev->devfn);

    uint32_t ccode = pci_default_read_config(dev, PCI_CLASS_PROG, 3);

    const char *name;



    name = pci_find_device_name((ccode >> 16) & 0xff, (ccode >> 8) & 0xff,

                                ccode & 0xff);



    if (func != 0) {

        snprintf(nodename, len, "%s@%x,%x", name, slot, func);

    } else {

        snprintf(nodename, len, "%s@%x", name, slot);

    }

}

static void qbus_list_dev(BusState *bus, char *dest, int len)

{

    DeviceState *dev;

    const char *sep = " ";

    int pos = 0;



    pos += snprintf(dest+pos, len-pos, "devices at \"%s\":",

                    bus->name);

    LIST_FOREACH(dev, &bus->children, sibling) {

        pos += snprintf(dest+pos, len-pos, "%s\"%s\"",

                        sep, dev->info->name);

        if (dev->id)

            pos += snprintf(dest+pos, len-pos, "/\"%s\"", dev->id);

        sep = ", ";

    }

}

static void qio_channel_websock_handshake_send_res_ok(QIOChannelWebsock *ioc,

                                                      const char *key,

                                                      Error **errp)

{

    char combined_key[QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

                      QIO_CHANNEL_WEBSOCK_GUID_LEN + 1];

    char *accept = NULL;

    char *date = qio_channel_websock_date_str();



    g_strlcpy(combined_key, key, QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN + 1);

    g_strlcat(combined_key, QIO_CHANNEL_WEBSOCK_GUID,

              QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

              QIO_CHANNEL_WEBSOCK_GUID_LEN + 1);



    /* hash and encode it */

    if (qcrypto_hash_base64(QCRYPTO_HASH_ALG_SHA1,

                            combined_key,

                            QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

                            QIO_CHANNEL_WEBSOCK_GUID_LEN,

                            &accept,

                            errp) < 0) {

        qio_channel_websock_handshake_send_res_err(

            ioc, QIO_CHANNEL_WEBSOCK_HANDSHAKE_RES_SERVER_ERR);

        return;

    }



    qio_channel_websock_handshake_send_res(

        ioc, QIO_CHANNEL_WEBSOCK_HANDSHAKE_RES_OK, date, accept);



    g_free(date);

    g_free(accept);

}

static int qio_channel_websock_handshake_read(QIOChannelWebsock *ioc,

                                              Error **errp)

{

    char *handshake_end;

    ssize_t ret;

    /* Typical HTTP headers from novnc are 512 bytes, so limiting

     * total header size to 4096 is easily enough. */

    size_t want = 4096 - ioc->encinput.offset;

    buffer_reserve(&ioc->encinput, want);

    ret = qio_channel_read(ioc->master,

                           (char *)buffer_end(&ioc->encinput), want, errp);

    if (ret < 0) {

        return -1;

    }

    ioc->encinput.offset += ret;



    handshake_end = g_strstr_len((char *)ioc->encinput.buffer,

                                 ioc->encinput.offset,

                                 QIO_CHANNEL_WEBSOCK_HANDSHAKE_END);

    if (!handshake_end) {

        if (ioc->encinput.offset >= 4096) {

            error_setg(errp,

                       "End of headers not found in first 4096 bytes");

            return -1;

        } else {

            return 0;

        }

    }

    *handshake_end = '\0';



    if (qio_channel_websock_handshake_process(ioc,

                                              (char *)ioc->encinput.buffer,

                                              errp) < 0) {

        return -1;

    }



    buffer_advance(&ioc->encinput,

                   handshake_end - (char *)ioc->encinput.buffer +

                   strlen(QIO_CHANNEL_WEBSOCK_HANDSHAKE_END));

    return 1;

}

static void test_hash_base64(void)

{

    size_t i;



    g_assert(qcrypto_init(NULL) == 0);



    for (i = 0; i < G_N_ELEMENTS(expected_outputs) ; i++) {

        int ret;

        char *digest;



        ret = qcrypto_hash_base64(i,

                                  INPUT_TEXT,

                                  strlen(INPUT_TEXT),

                                  &digest,

                                  NULL);

        g_assert(ret == 0);

        g_assert(g_str_equal(digest, expected_outputs_b64[i]));

        g_free(digest);

    }

}

static char *shorts2str(int *sp, int count, const char *sep)

{

    int i;

    char *ap, *ap0;

    if (!sep) sep = ", ";

    ap = av_malloc((5 + strlen(sep)) * count);

    if (!ap)

        return NULL;

    ap0   = ap;

    ap[0] = '\0';

    for (i = 0; i < count; i++) {

        int l = snprintf(ap, 5 + strlen(sep), "%d%s", sp[i], sep);

        ap += l;

    }

    ap0[strlen(ap0) - strlen(sep)] = '\0';

    return ap0;

}

void dpy_gfx_replace_surface(QemuConsole *con,
                             DisplaySurface *surface)
{
    DisplayState *s = con->ds;
    DisplaySurface *old_surface = con->surface;
    DisplayChangeListener *dcl;
    con->surface = surface;
    QLIST_FOREACH(dcl, &s->listeners, next) {
        if (con != (dcl->con ? dcl->con : active_console)) {
            continue;
        }
        if (dcl->ops->dpy_gfx_switch) {
            dcl->ops->dpy_gfx_switch(dcl, surface);
        }
    }
    qemu_free_displaysurface(old_surface);
}

