static int dca_parse(AVCodecParserContext *s, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    DCAParseContext *pc1 = s->priv_data;

    ParseContext *pc = &pc1->pc;

    int next, duration, sample_rate;



    if (s->flags & PARSER_FLAG_COMPLETE_FRAMES) {

        next = buf_size;

    } else {

        next = dca_find_frame_end(pc1, buf, buf_size);



        if (ff_combine_frame(pc, next, &buf, &buf_size) < 0) {

            *poutbuf      = NULL;

            *poutbuf_size = 0;

            return buf_size;

        }

    }



    /* read the duration and sample rate from the frame header */

    if (!dca_parse_params(buf, buf_size, &duration, &sample_rate, &pc1->framesize)) {

        s->duration        = duration;

        avctx->sample_rate = sample_rate;

    } else

        s->duration = 0;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static int noise(AVBitStreamFilterContext *bsfc, AVCodecContext *avctx, const char *args,
                     uint8_t **poutbuf, int *poutbuf_size,
                     const uint8_t *buf, int buf_size, int keyframe){
    unsigned int *state= bsfc->priv_data;
    int amount= args ? atoi(args) : (*state % 10001+1);
    int i;
    *poutbuf= av_malloc(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);
    memcpy(*poutbuf, buf, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);
    for(i=0; i<buf_size; i++){
        (*state) += (*poutbuf)[i] + 1;
        if(*state % amount == 0)
            (*poutbuf)[i] = *state;
    }
    return 1;
}

static int dvdsub_parse(AVCodecParserContext *s,

                        AVCodecContext *avctx,

                        const uint8_t **poutbuf, int *poutbuf_size,

                        const uint8_t *buf, int buf_size)

{

    DVDSubParseContext *pc = s->priv_data;



    if (pc->packet_index == 0) {

        if (buf_size < 2)

            return buf_size;

        pc->packet_len = AV_RB16(buf);

        if (pc->packet_len == 0) /* HD-DVD subpicture packet */

            pc->packet_len = AV_RB32(buf+2);

        av_freep(&pc->packet);

        pc->packet = av_malloc(pc->packet_len);

    }

    if (pc->packet) {

        if (pc->packet_index + buf_size <= pc->packet_len) {

            memcpy(pc->packet + pc->packet_index, buf, buf_size);

            pc->packet_index += buf_size;

            if (pc->packet_index >= pc->packet_len) {

                *poutbuf = pc->packet;

                *poutbuf_size = pc->packet_len;

                pc->packet_index = 0;

                return buf_size;

            }

        } else {

            /* erroneous size */

            pc->packet_index = 0;

        }

    }

    *poutbuf = NULL;

    *poutbuf_size = 0;

    return buf_size;

}

static int adx_parse(AVCodecParserContext *s1,

                           AVCodecContext *avctx,

                           const uint8_t **poutbuf, int *poutbuf_size,

                           const uint8_t *buf, int buf_size)

{

    ADXParseContext *s = s1->priv_data;

    ParseContext *pc = &s->pc;

    int next = END_NOT_FOUND;



    if (!avctx->extradata_size) {

        int ret;



        ff_combine_frame(pc, END_NOT_FOUND, &buf, &buf_size);



        if (!s->header_size && pc->index >= MIN_HEADER_SIZE) {

            if (ret = avpriv_adx_decode_header(avctx, pc->buffer, pc->index,

                                               &s->header_size, NULL))

                return AVERROR_INVALIDDATA;

            s->block_size = BLOCK_SIZE * avctx->channels;

        }

        if (s->header_size && s->header_size <= pc->index) {

            avctx->extradata = av_mallocz(s->header_size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!avctx->extradata)

                return AVERROR(ENOMEM);

            avctx->extradata_size = s->header_size;

            memcpy(avctx->extradata, pc->buffer, s->header_size);

            memmove(pc->buffer, pc->buffer + s->header_size, s->header_size);

            pc->index -= s->header_size;

        }

        *poutbuf      = NULL;

        *poutbuf_size = 0;

        return buf_size;

    }



    if (pc->index - s->buf_pos >= s->block_size) {

        *poutbuf      = &pc->buffer[s->buf_pos];

        *poutbuf_size = s->block_size;

        s->buf_pos   += s->block_size;

        return 0;

    }

    if (pc->index && s->buf_pos) {

        memmove(pc->buffer, &pc->buffer[s->buf_pos], pc->index - s->buf_pos);

        pc->index -= s->buf_pos;

        s->buf_pos = 0;

    }

    if (buf_size + pc->index >= s->block_size)

        next = s->block_size - pc->index;



    if (ff_combine_frame(pc, next, &buf, &buf_size) < 0 || !buf_size) {

        *poutbuf      = NULL;

        *poutbuf_size = 0;

        return buf_size;

    }

    *poutbuf = buf;

    *poutbuf_size = buf_size;

    return next;

}

void add_codec(FFStream *stream, AVCodecContext *av)

{

    AVStream *st;



    /* compute default parameters */

    switch(av->codec_type) {

    case CODEC_TYPE_AUDIO:

        if (av->bit_rate == 0)

            av->bit_rate = 64000;

        if (av->sample_rate == 0)

            av->sample_rate = 22050;

        if (av->channels == 0)

            av->channels = 1;

        break;

    case CODEC_TYPE_VIDEO:

        if (av->bit_rate == 0)

            av->bit_rate = 64000;

        if (av->frame_rate == 0)

            av->frame_rate = 5 * FRAME_RATE_BASE;

        if (av->width == 0 || av->height == 0) {

            av->width = 160;

            av->height = 128;

        }

        /* Bitrate tolerance is less for streaming */

        if (av->bit_rate_tolerance == 0)

            av->bit_rate_tolerance = av->bit_rate / 4;

        if (av->qmin == 0)

            av->qmin = 3;

        if (av->qmax == 0)

            av->qmax = 31;

        if (av->max_qdiff == 0)

            av->max_qdiff = 3;

        av->qcompress = 0.5;

        av->qblur = 0.5;



        break;

    default:

        abort();

    }



    st = av_mallocz(sizeof(AVStream));

    if (!st)

        return;

    stream->streams[stream->nb_streams++] = st;

    memcpy(&st->codec, av, sizeof(AVCodecContext));

}

int avformat_write_header(AVFormatContext *s, AVDictionary **options)

{

    int ret = 0, i;

    AVStream *st;

    AVDictionary *tmp = NULL;

    AVCodecContext *codec = NULL;

    AVOutputFormat *of = s->oformat;



    if (options)

        av_dict_copy(&tmp, *options, 0);



    if ((ret = av_opt_set_dict(s, &tmp)) < 0)

        goto fail;



    // some sanity checks

    if (s->nb_streams == 0 && !(of->flags & AVFMT_NOSTREAMS)) {

        av_log(s, AV_LOG_ERROR, "no streams\n");

        ret = AVERROR(EINVAL);

        goto fail;

    }



    for (i = 0; i < s->nb_streams; i++) {

        st    = s->streams[i];

        codec = st->codec;



        switch (codec->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            if (codec->sample_rate <= 0) {

                av_log(s, AV_LOG_ERROR, "sample rate not set\n");

                ret = AVERROR(EINVAL);

                goto fail;

            }

            if (!codec->block_align)

                codec->block_align = codec->channels *

                                     av_get_bits_per_sample(codec->codec_id) >> 3;

            break;

        case AVMEDIA_TYPE_VIDEO:

            if (codec->time_base.num <= 0 ||

                codec->time_base.den <= 0) { //FIXME audio too?

                av_log(s, AV_LOG_ERROR, "time base not set\n");

                ret = AVERROR(EINVAL);

                goto fail;

            }



            if ((codec->width <= 0 || codec->height <= 0) &&

                !(of->flags & AVFMT_NODIMENSIONS)) {

                av_log(s, AV_LOG_ERROR, "dimensions not set\n");

                ret = AVERROR(EINVAL);

                goto fail;

            }



            if (av_cmp_q(st->sample_aspect_ratio,

                         codec->sample_aspect_ratio)) {

                av_log(s, AV_LOG_ERROR, "Aspect ratio mismatch between muxer "

                                        "(%d/%d) and encoder layer (%d/%d)\n",

                       st->sample_aspect_ratio.num, st->sample_aspect_ratio.den,

                       codec->sample_aspect_ratio.num,

                       codec->sample_aspect_ratio.den);

                ret = AVERROR(EINVAL);

                goto fail;

            }

            break;

        }



        if (of->codec_tag) {

            if (codec->codec_tag &&

                codec->codec_id == AV_CODEC_ID_RAWVIDEO &&

                !av_codec_get_tag(of->codec_tag, codec->codec_id) &&

                !validate_codec_tag(s, st)) {

                // the current rawvideo encoding system ends up setting

                // the wrong codec_tag for avi, we override it here

                codec->codec_tag = 0;

            }

            if (codec->codec_tag) {

                if (!validate_codec_tag(s, st)) {

                    char tagbuf[32];

                    av_get_codec_tag_string(tagbuf, sizeof(tagbuf), codec->codec_tag);

                    av_log(s, AV_LOG_ERROR,

                           "Tag %s/0x%08x incompatible with output codec id '%d'\n",

                           tagbuf, codec->codec_tag, codec->codec_id);

                    ret = AVERROR_INVALIDDATA;

                    goto fail;

                }

            } else

                codec->codec_tag = av_codec_get_tag(of->codec_tag, codec->codec_id);

        }



        if (of->flags & AVFMT_GLOBALHEADER &&

            !(codec->flags & CODEC_FLAG_GLOBAL_HEADER))

            av_log(s, AV_LOG_WARNING,

                   "Codec for stream %d does not use global headers "

                   "but container format requires global headers\n", i);

    }



    if (!s->priv_data && of->priv_data_size > 0) {

        s->priv_data = av_mallocz(of->priv_data_size);

        if (!s->priv_data) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        if (of->priv_class) {

            *(const AVClass **)s->priv_data = of->priv_class;

            av_opt_set_defaults(s->priv_data);

            if ((ret = av_opt_set_dict(s->priv_data, &tmp)) < 0)

                goto fail;

        }

    }



    /* set muxer identification string */

    if (s->nb_streams && !(s->streams[0]->codec->flags & CODEC_FLAG_BITEXACT)) {

        av_dict_set(&s->metadata, "encoder", LIBAVFORMAT_IDENT, 0);

    }



    if (s->oformat->write_header) {

        ret = s->oformat->write_header(s);

        if (ret < 0)

            goto fail;

    }



    /* init PTS generation */

    for (i = 0; i < s->nb_streams; i++) {

        int64_t den = AV_NOPTS_VALUE;

        st = s->streams[i];



        switch (st->codec->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            den = (int64_t)st->time_base.num * st->codec->sample_rate;

            break;

        case AVMEDIA_TYPE_VIDEO:

            den = (int64_t)st->time_base.num * st->codec->time_base.den;

            break;

        default:

            break;

        }

        if (den != AV_NOPTS_VALUE) {

            if (den <= 0) {

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            frac_init(&st->pts, 0, 0, den);

        }

    }



    if (options) {

        av_dict_free(options);

        *options = tmp;

    }

    return 0;

fail:

    av_dict_free(&tmp);

    return ret;

}

static void add_codec(FFServerStream *stream, AVCodecContext *av)

{

    AVStream *st;



    if(stream->nb_streams >= FF_ARRAY_ELEMS(stream->streams))

        return;



    /* compute default parameters */

    switch(av->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        if (av->bit_rate == 0)

            av->bit_rate = 64000;

        if (av->sample_rate == 0)

            av->sample_rate = 22050;

        if (av->channels == 0)

            av->channels = 1;

        break;

    case AVMEDIA_TYPE_VIDEO:

        if (av->bit_rate == 0)

            av->bit_rate = 64000;

        if (av->time_base.num == 0){

            av->time_base.den = 5;

            av->time_base.num = 1;

        }

        if (av->width == 0 || av->height == 0) {

            av->width = 160;

            av->height = 128;

        }

        /* Bitrate tolerance is less for streaming */

        if (av->bit_rate_tolerance == 0)

            av->bit_rate_tolerance = FFMAX(av->bit_rate / 4,

                      (int64_t)av->bit_rate*av->time_base.num/av->time_base.den);

        if (av->qmin == 0)

            av->qmin = 3;

        if (av->qmax == 0)

            av->qmax = 31;

        if (av->max_qdiff == 0)

            av->max_qdiff = 3;

        av->qcompress = 0.5;

        av->qblur = 0.5;



        if (!av->nsse_weight)

            av->nsse_weight = 8;



        av->frame_skip_cmp = FF_CMP_DCTMAX;

        if (!av->me_method)

            av->me_method = ME_EPZS;

        av->rc_buffer_aggressivity = 1.0;



        if (!av->rc_eq)

            av->rc_eq = av_strdup("tex^qComp");

        if (!av->i_quant_factor)

            av->i_quant_factor = -0.8;

        if (!av->b_quant_factor)

            av->b_quant_factor = 1.25;

        if (!av->b_quant_offset)

            av->b_quant_offset = 1.25;

        if (!av->rc_max_rate)

            av->rc_max_rate = av->bit_rate * 2;



        if (av->rc_max_rate && !av->rc_buffer_size) {

            av->rc_buffer_size = av->rc_max_rate;

        }





        break;

    default:

        abort();

    }



    st = av_mallocz(sizeof(AVStream));

    if (!st)

        return;

    st->codec = avcodec_alloc_context3(NULL);

    stream->streams[stream->nb_streams++] = st;

    memcpy(st->codec, av, sizeof(AVCodecContext));

}

