static void decode_delta_j(uint8_t *dst,

                           const uint8_t *buf, const uint8_t *buf_end,

                           int w, int h, int bpp, int dst_size)

{

    int32_t pitch;

    uint8_t *end = dst + dst_size, *ptr;

    uint32_t type, flag, cols, groups, rows, bytes;

    uint32_t offset;

    int planepitch_byte = (w + 7) / 8;

    int planepitch = ((w + 15) / 16) * 2;

    int kludge_j, b, g, r, d;

    GetByteContext gb;



    pitch = planepitch * bpp;

    kludge_j = w < 320 ? (320 - w) / 8 / 2 : 0;



    bytestream2_init(&gb, buf, buf_end - buf);



    while (bytestream2_get_bytes_left(&gb) >= 2) {

        type = bytestream2_get_be16(&gb);



        switch (type) {

        case 0:

            return;

        case 1:

            flag   = bytestream2_get_be16(&gb);

            cols   = bytestream2_get_be16(&gb);

            groups = bytestream2_get_be16(&gb);



            for (g = 0; g < groups; g++) {

                offset = bytestream2_get_be16(&gb);



                if (kludge_j)

                    offset = ((offset / (320 / 8)) * pitch) + (offset % (320 / 8)) - kludge_j;

                else

                    offset = ((offset / planepitch_byte) * pitch) + (offset % planepitch_byte);



                ptr = dst + offset;

                if (ptr >= end)

                    return;



                for (b = 0; b < cols; b++) {

                    for (d = 0; d < bpp; d++) {

                        uint8_t value = bytestream2_get_byte(&gb);



                        if (flag)

                            ptr[0] ^= value;

                        else

                            ptr[0]  = value;



                        ptr += planepitch;

                        if (ptr >= end)

                            return;

                    }

                }

                if ((cols * bpp) & 1)

                    bytestream2_skip(&gb, 1);

            }

            break;

        case 2:

            flag   = bytestream2_get_be16(&gb);

            rows   = bytestream2_get_be16(&gb);

            bytes  = bytestream2_get_be16(&gb);

            groups = bytestream2_get_be16(&gb);



            for (g = 0; g < groups; g++) {

                offset = bytestream2_get_be16(&gb);



                if (kludge_j)

                    offset = ((offset / (320 / 8)) * pitch) + (offset % (320/ 8)) - kludge_j;

                else

                    offset = ((offset / planepitch_byte) * pitch) + (offset % planepitch_byte);



                for (r = 0; r < rows; r++) {

                    for (d = 0; d < bpp; d++) {

                        ptr = dst + offset + (r * pitch) + d * planepitch;

                        if (ptr >= end)

                            return;



                        for (b = 0; b < bytes; b++) {

                            uint8_t value = bytestream2_get_byte(&gb);



                            if (flag)

                                ptr[0] ^= value;

                            else

                                ptr[0]  = value;



                            ptr++;

                            if (ptr >= end)

                                return;

                        }

                    }

                }

                if ((rows * bytes * bpp) & 1)

                    bytestream2_skip(&gb, 1);

            }

            break;

        default:

            return;

        }

    }

}

static int decode_wdlt(uint8_t *frame, int width, int height,

                       const uint8_t *src, const uint8_t *src_end)

{

    const uint8_t *frame_end   = frame + width * height;

    uint8_t *line_ptr;

    int count, i, v, lines, segments;



    lines = bytestream_get_le16(&src);

    if (lines > height || src >= src_end)

        return -1;



    while (lines--) {

        segments = bytestream_get_le16(&src);

        while ((segments & 0xC000) == 0xC000) {

            unsigned delta = -((int16_t)segments * width);

            if (frame_end - frame <= delta)

                return -1;

            frame    += delta;

            segments = bytestream_get_le16(&src);

        }

        if (segments & 0x8000) {

            frame[width - 1] = segments & 0xFF;

            segments = bytestream_get_le16(&src);

        }

        line_ptr = frame;

        frame += width;

        while (segments--) {

            if (src_end - src < 2)

                return -1;

            if (frame - line_ptr <= *src)

                return -1;

            line_ptr += *src++;

            count = (int8_t)*src++;

            if (count >= 0) {

                if (frame - line_ptr < count*2 || src_end - src < count*2)

                    return -1;

                bytestream_get_buffer(&src, line_ptr, count*2);

                line_ptr += count * 2;

            } else {

                count = -count;

                if (frame - line_ptr < count*2 || src_end - src < 2)

                    return -1;

                v = bytestream_get_le16(&src);

                for (i = 0; i < count; i++)

                    bytestream_put_le16(&line_ptr, v);

            }

        }

    }



    return 0;

}

static void decode_delta_e(uint8_t *dst,

                           const uint8_t *buf, const uint8_t *buf_end,

                           int w, int flag, int bpp, int dst_size)

{

    int planepitch = FFALIGN(w, 16) >> 3;

    int pitch = planepitch * bpp;

    int planepitch_byte = (w + 7) / 8;

    unsigned entries, ofssrc;

    GetByteContext gb, ptrs;

    PutByteContext pb;

    int k;



    if (buf_end - buf <= 4 * bpp)

        return;



    bytestream2_init_writer(&pb, dst, dst_size);

    bytestream2_init(&ptrs, buf, bpp * 4);



    for (k = 0; k < bpp; k++) {

        ofssrc = bytestream2_get_be32(&ptrs);



        if (!ofssrc)

            continue;



        if (ofssrc >= buf_end - buf)

            continue;



        bytestream2_init(&gb, buf + ofssrc, buf_end - (buf + ofssrc));



        entries = bytestream2_get_be16(&gb);

        while (entries) {

            int16_t opcode  = bytestream2_get_be16(&gb);

            unsigned offset = bytestream2_get_be32(&gb);



            bytestream2_seek_p(&pb, (offset / planepitch_byte) * pitch + (offset % planepitch_byte) + k * planepitch, SEEK_SET);

            if (opcode >= 0) {

                uint16_t x = bytestream2_get_be16(&gb);

                while (opcode && bytestream2_get_bytes_left_p(&pb) > 0) {

                    bytestream2_put_be16(&pb, x);

                    bytestream2_skip_p(&pb, pitch - 2);

                    opcode--;

                }

            } else {

                opcode = -opcode;

                while (opcode && bytestream2_get_bytes_left(&gb) > 0) {

                    bytestream2_put_be16(&pb, bytestream2_get_be16(&gb));

                    bytestream2_skip_p(&pb, pitch - 2);

                    opcode--;

                }

            }

            entries--;

        }

    }

}

static void decode_delta_j(uint8_t *dst,

                           const uint8_t *buf, const uint8_t *buf_end,

                           int w, int h, int bpp, int dst_size)

{

    int32_t pitch;

    uint8_t *ptr;

    uint32_t type, flag, cols, groups, rows, bytes;

    uint32_t offset;

    int planepitch_byte = (w + 7) / 8;

    int planepitch = ((w + 15) / 16) * 2;

    int kludge_j, b, g, r, d;

    GetByteContext gb;



    pitch = planepitch * bpp;

    kludge_j = w < 320 ? (320 - w) / 8 / 2 : 0;



    bytestream2_init(&gb, buf, buf_end - buf);



    while (bytestream2_get_bytes_left(&gb) >= 2) {

        type = bytestream2_get_be16(&gb);



        switch (type) {

        case 0:

            return;

        case 1:

            flag   = bytestream2_get_be16(&gb);

            cols   = bytestream2_get_be16(&gb);

            groups = bytestream2_get_be16(&gb);



            for (g = 0; g < groups; g++) {

                offset = bytestream2_get_be16(&gb);



                if (bytestream2_get_bytes_left(&gb) < 1)

                    return;



                if (kludge_j)

                    offset = ((offset / (320 / 8)) * pitch) + (offset % (320 / 8)) - kludge_j;

                else

                    offset = ((offset / planepitch_byte) * pitch) + (offset % planepitch_byte);



                for (b = 0; b < cols; b++) {

                    for (d = 0; d < bpp; d++) {

                        uint8_t value = bytestream2_get_byte(&gb);



                        if (offset >= dst_size)

                            return;

                        ptr = dst + offset;



                        if (flag)

                            ptr[0] ^= value;

                        else

                            ptr[0]  = value;



                        offset += planepitch;

                    }

                }

                if ((cols * bpp) & 1)

                    bytestream2_skip(&gb, 1);

            }

            break;

        case 2:

            flag   = bytestream2_get_be16(&gb);

            rows   = bytestream2_get_be16(&gb);

            bytes  = bytestream2_get_be16(&gb);

            groups = bytestream2_get_be16(&gb);



            for (g = 0; g < groups; g++) {

                offset = bytestream2_get_be16(&gb);



                if (kludge_j)

                    offset = ((offset / (320 / 8)) * pitch) + (offset % (320/ 8)) - kludge_j;

                else

                    offset = ((offset / planepitch_byte) * pitch) + (offset % planepitch_byte);



                for (r = 0; r < rows; r++) {

                    for (d = 0; d < bpp; d++) {

                        unsigned noffset = offset + (r * pitch) + d * planepitch;



                        if (bytestream2_get_bytes_left(&gb) < 1)

                            return;



                        for (b = 0; b < bytes; b++) {

                            uint8_t value = bytestream2_get_byte(&gb);



                            if (noffset >= dst_size)

                                return;

                            ptr = dst + noffset;



                            if (flag)

                                ptr[0] ^= value;

                            else

                                ptr[0]  = value;



                            noffset++;

                        }

                    }

                }

                if ((rows * bytes * bpp) & 1)

                    bytestream2_skip(&gb, 1);

            }

            break;

        default:

            return;

        }

    }

}

