                                &s->mem_config);

    /* Normal config area.  */

    memory_region_add_subregion(get_system_memory(), base + 0x02000000,

                                &s->mem_config2);



    if (s->realview) {

        /* IO memory area.  */

        memory_region_add_subregion(get_system_memory(), base + 0x03000000,

                                    &s->isa);

    }

}

