static void rtas_ibm_get_config_addr_info2(PowerPCCPU *cpu,

                                           sPAPREnvironment *spapr,

                                           uint32_t token, uint32_t nargs,

                                           target_ulong args, uint32_t nret,

                                           target_ulong rets)

{

    sPAPRPHBState *sphb;

    sPAPRPHBClass *spc;

    PCIDevice *pdev;

    uint32_t addr, option;

    uint64_t buid;



    if ((nargs != 4) || (nret != 2)) {

        goto param_error_exit;

    }



    buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    sphb = find_phb(spapr, buid);

    if (!sphb) {

        goto param_error_exit;

    }



    spc = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(sphb);

    if (!spc->eeh_set_option) {

        goto param_error_exit;

    }



    /*

     * We always have PE address of form "00BB0001". "BB"

     * represents the bus number of PE's primary bus.

     */

    option = rtas_ld(args, 3);

    switch (option) {

    case RTAS_GET_PE_ADDR:

        addr = rtas_ld(args, 0);

        pdev = find_dev(spapr, buid, addr);

        if (!pdev) {

            goto param_error_exit;

        }



        rtas_st(rets, 1, (pci_bus_num(pdev->bus) << 16) + 1);

        break;

    case RTAS_GET_PE_MODE:

        rtas_st(rets, 1, RTAS_PE_MODE_SHARED);

        break;

    default:

        goto param_error_exit;

    }



    rtas_st(rets, 0, RTAS_OUT_SUCCESS);

    return;



param_error_exit:

    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

}

static void rtas_ibm_slot_error_detail(PowerPCCPU *cpu,

                                       sPAPREnvironment *spapr,

                                       uint32_t token, uint32_t nargs,

                                       target_ulong args, uint32_t nret,

                                       target_ulong rets)

{

    sPAPRPHBState *sphb;

    sPAPRPHBClass *spc;

    int option;

    uint64_t buid;



    if ((nargs != 8) || (nret != 1)) {

        goto param_error_exit;

    }



    buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    sphb = find_phb(spapr, buid);

    if (!sphb) {

        goto param_error_exit;

    }



    spc = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(sphb);

    if (!spc->eeh_set_option) {

        goto param_error_exit;

    }



    option = rtas_ld(args, 7);

    switch (option) {

    case RTAS_SLOT_TEMP_ERR_LOG:

    case RTAS_SLOT_PERM_ERR_LOG:

        break;

    default:

        goto param_error_exit;

    }



    /* We don't have error log yet */

    rtas_st(rets, 0, RTAS_OUT_NO_ERRORS_FOUND);

    return;



param_error_exit:

    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

}

static void rtas_set_indicator(PowerPCCPU *cpu, sPAPRMachineState *spapr,

                               uint32_t token, uint32_t nargs,

                               target_ulong args, uint32_t nret,

                               target_ulong rets)

{

    uint32_t sensor_type;

    uint32_t sensor_index;

    uint32_t sensor_state;

    uint32_t ret = RTAS_OUT_SUCCESS;

    sPAPRDRConnector *drc;

    sPAPRDRConnectorClass *drck;



    if (nargs != 3 || nret != 1) {

        ret = RTAS_OUT_PARAM_ERROR;

        goto out;

    }



    sensor_type = rtas_ld(args, 0);

    sensor_index = rtas_ld(args, 1);

    sensor_state = rtas_ld(args, 2);



    if (!sensor_type_is_dr(sensor_type)) {

        goto out_unimplemented;

    }



    /* if this is a DR sensor we can assume sensor_index == drc_index */

    drc = spapr_drc_by_index(sensor_index);

    if (!drc) {

        trace_spapr_rtas_set_indicator_invalid(sensor_index);

        ret = RTAS_OUT_PARAM_ERROR;

        goto out;

    }

    drck = SPAPR_DR_CONNECTOR_GET_CLASS(drc);



    switch (sensor_type) {

    case RTAS_SENSOR_TYPE_ISOLATION_STATE:

        ret = drck->set_isolation_state(drc, sensor_state);

        break;

    case RTAS_SENSOR_TYPE_DR:

        ret = drck->set_indicator_state(drc, sensor_state);

        break;

    case RTAS_SENSOR_TYPE_ALLOCATION_STATE:

        ret = drck->set_allocation_state(drc, sensor_state);

        break;

    default:

        goto out_unimplemented;

    }



out:

    rtas_st(rets, 0, ret);

    return;



out_unimplemented:

    /* currently only DR-related sensors are implemented */

    trace_spapr_rtas_set_indicator_not_supported(sensor_index, sensor_type);

    rtas_st(rets, 0, RTAS_OUT_NOT_SUPPORTED);

}

static void rtas_ibm_set_slot_reset(PowerPCCPU *cpu,

                                    sPAPREnvironment *spapr,

                                    uint32_t token, uint32_t nargs,

                                    target_ulong args, uint32_t nret,

                                    target_ulong rets)

{

    sPAPRPHBState *sphb;

    sPAPRPHBClass *spc;

    uint32_t option;

    uint64_t buid;

    int ret;



    if ((nargs != 4) || (nret != 1)) {

        goto param_error_exit;

    }



    buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    option = rtas_ld(args, 3);

    sphb = find_phb(spapr, buid);

    if (!sphb) {

        goto param_error_exit;

    }



    spc = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(sphb);

    if (!spc->eeh_reset) {

        goto param_error_exit;

    }



    ret = spc->eeh_reset(sphb, option);

    rtas_st(rets, 0, ret);

    return;



param_error_exit:

    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

}

