static const char *local_mapped_attr_path(FsContext *ctx,

                                          const char *path, char *buffer)

{

    char *dir_name;

    char *tmp_path = g_strdup(path);

    char *base_name = basename(tmp_path);



    /* NULL terminate the directory */

    dir_name = tmp_path;

    *(base_name - 1) = '\0';



    snprintf(buffer, PATH_MAX, "%s/%s/%s/%s",

             ctx->fs_root, dir_name, VIRTFS_META_DIR, base_name);

    g_free(tmp_path);

    return buffer;

}

int qemu_uuid_parse(const char *str, QemuUUID *uuid)

{

    unsigned char *uu = &uuid->data[0];

    int ret;



    if (strlen(str) != 36) {

        return -1;

    }



    ret = sscanf(str, UUID_FMT, &uu[0], &uu[1], &uu[2], &uu[3],

                 &uu[4], &uu[5], &uu[6], &uu[7], &uu[8], &uu[9],

                 &uu[10], &uu[11], &uu[12], &uu[13], &uu[14],

                 &uu[15]);



    if (ret != 16) {

        return -1;

    }

    return 0;

}

void av_log_format_line(void *ptr, int level, const char *fmt, va_list vl,

                        char *line, int line_size, int *print_prefix)

{

    char part[3][512];

    format_line(ptr, level, fmt, vl, part, sizeof(part[0]), print_prefix, NULL);

    snprintf(line, line_size, "%s%s%s", part[0], part[1], part[2]);

}

void av_log_format_line(void *ptr, int level, const char *fmt, va_list vl,

                        char *line, int line_size, int *print_prefix)

{

    AVBPrint part[4];

    format_line(ptr, level, fmt, vl, part, print_prefix, NULL);

    snprintf(line, line_size, "%s%s%s%s", part[0].str, part[1].str, part[2].str, part[3].str);

    av_bprint_finalize(part+3, NULL);

}

