static void dp8393x_writew(void *opaque, target_phys_addr_t addr, uint32_t val)

{

    dp8393xState *s = opaque;

    int reg;



    if ((addr & ((1 << s->it_shift) - 1)) != 0) {

        return;

    }



    reg = addr >> s->it_shift;



    write_register(s, reg, (uint16_t)val);

}

void ff_xvmc_init_block(MpegEncContext *s)

{

    struct xvmc_render_state *render = (struct xvmc_render_state*)s->current_picture.data[2];

    assert(render);

    if (!render || render->magic != AV_XVMC_RENDER_MAGIC) {

