void usb_packet_unmap(USBPacket *p)

{

    int is_write = (p->pid == USB_TOKEN_IN);

    int i;



    for (i = 0; i < p->iov.niov; i++) {

        cpu_physical_memory_unmap(p->iov.iov[i].iov_base,

                                  p->iov.iov[i].iov_len, is_write,

                                  p->iov.iov[i].iov_len);

    }

}

void virtqueue_map_sg(struct iovec *sg, hwaddr *addr,

    size_t num_sg, int is_write)

{

    unsigned int i;

    hwaddr len;



    if (num_sg > VIRTQUEUE_MAX_SIZE) {

        error_report("virtio: map attempt out of bounds: %zd > %d",

                     num_sg, VIRTQUEUE_MAX_SIZE);

        exit(1);

    }



    for (i = 0; i < num_sg; i++) {

        len = sg[i].iov_len;

        sg[i].iov_base = cpu_physical_memory_map(addr[i], &len, is_write);

        if (sg[i].iov_base == NULL || len != sg[i].iov_len) {

            error_report("virtio: error trying to map MMIO memory");

            exit(1);

        }

    }

}

void qemu_iovec_concat(QEMUIOVector *dst,

                       QEMUIOVector *src, size_t soffset, size_t sbytes)

{

    int i;

    size_t done;

    struct iovec *siov = src->iov;

    assert(dst->nalloc != -1);

    assert(src->size >= soffset);

    for (i = 0, done = 0; done < sbytes && i < src->niov; i++) {

        if (soffset < siov[i].iov_len) {

            size_t len = MIN(siov[i].iov_len - soffset, sbytes - done);

            qemu_iovec_add(dst, siov[i].iov_base + soffset, len);

            done += len;

            soffset = 0;

        } else {

            soffset -= siov[i].iov_len;

        }

    }

    /* return done; */

}

int init_timer_alarm(void)

{

    struct qemu_alarm_timer *t = NULL;

    int i, err = -1;



    for (i = 0; alarm_timers[i].name; i++) {

        t = &alarm_timers[i];



        err = t->start(t);

        if (!err)

            break;

    }



    if (err) {

        err = -ENOENT;

        goto fail;

    }



    /* first event is at time 0 */

    atexit(quit_timers);

    t->pending = true;

    alarm_timer = t;



    return 0;



fail:

    return err;

}

static void get_sensor_reading(IPMIBmcSim *ibs,

                               uint8_t *cmd, unsigned int cmd_len,

                               uint8_t *rsp, unsigned int *rsp_len,

                               unsigned int max_rsp_len)

{

    IPMISensor *sens;



    IPMI_CHECK_CMD_LEN(3);

    if ((cmd[2] > MAX_SENSORS) ||

            !IPMI_SENSOR_GET_PRESENT(ibs->sensors + cmd[2])) {

        rsp[2] = IPMI_CC_REQ_ENTRY_NOT_PRESENT;

        return;

    }

    sens = ibs->sensors + cmd[2];

    IPMI_ADD_RSP_DATA(sens->reading);

    IPMI_ADD_RSP_DATA(IPMI_SENSOR_GET_RET_STATUS(sens));

    IPMI_ADD_RSP_DATA(sens->states & 0xff);

    if (IPMI_SENSOR_IS_DISCRETE(sens)) {

        IPMI_ADD_RSP_DATA((sens->states >> 8) & 0xff);

    }

}

static void get_sensor_type(IPMIBmcSim *ibs,

                               uint8_t *cmd, unsigned int cmd_len,

                               uint8_t *rsp, unsigned int *rsp_len,

                               unsigned int max_rsp_len)

{

    IPMISensor *sens;





    IPMI_CHECK_CMD_LEN(3);

    if ((cmd[2] > MAX_SENSORS) ||

            !IPMI_SENSOR_GET_PRESENT(ibs->sensors + cmd[2])) {

        rsp[2] = IPMI_CC_REQ_ENTRY_NOT_PRESENT;

        return;

    }

    sens = ibs->sensors + cmd[2];

    IPMI_ADD_RSP_DATA(sens->sensor_type);

    IPMI_ADD_RSP_DATA(sens->evt_reading_type_code);

}

static void set_sensor_type(IPMIBmcSim *ibs,

                               uint8_t *cmd, unsigned int cmd_len,

                               uint8_t *rsp, unsigned int *rsp_len,

                               unsigned int max_rsp_len)

{

    IPMISensor *sens;





    IPMI_CHECK_CMD_LEN(5);

    if ((cmd[2] > MAX_SENSORS) ||

            !IPMI_SENSOR_GET_PRESENT(ibs->sensors + cmd[2])) {

        rsp[2] = IPMI_CC_REQ_ENTRY_NOT_PRESENT;

        return;

    }

    sens = ibs->sensors + cmd[2];

    sens->sensor_type = cmd[3];

    sens->evt_reading_type_code = cmd[4] & 0x7f;

}

static void rearm_sensor_evts(IPMIBmcSim *ibs,

                              uint8_t *cmd, unsigned int cmd_len,

                              uint8_t *rsp, unsigned int *rsp_len,

                              unsigned int max_rsp_len)

{

    IPMISensor *sens;



    IPMI_CHECK_CMD_LEN(4);

    if ((cmd[2] >= MAX_SENSORS) ||

        !IPMI_SENSOR_GET_PRESENT(ibs->sensors + cmd[2])) {

        rsp[2] = IPMI_CC_REQ_ENTRY_NOT_PRESENT;

        return;

    }

    sens = ibs->sensors + cmd[2];



    if ((cmd[3] & 0x80) == 0) {

        /* Just clear everything */

        sens->states = 0;

        return;

    }

}

void ff_add_pixels_clamped_c(const DCTELEM *block, uint8_t *restrict pixels,

                             int line_size)

{

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    /* read the pixels */

    for(i=0;i<8;i++) {

        pixels[0] = cm[pixels[0] + block[0]];

        pixels[1] = cm[pixels[1] + block[1]];

        pixels[2] = cm[pixels[2] + block[2]];

        pixels[3] = cm[pixels[3] + block[3]];

        pixels[4] = cm[pixels[4] + block[4]];

        pixels[5] = cm[pixels[5] + block[5]];

        pixels[6] = cm[pixels[6] + block[6]];

        pixels[7] = cm[pixels[7] + block[7]];

        pixels += line_size;

        block += 8;

    }

}

static void vc1_loop_filter_iblk(MpegEncContext *s, int pq)

{

    int i, j;

    if(!s->first_slice_line)

        s->dsp.vc1_loop_filter(s->dest[0], 1, s->linesize, 16, pq);

    s->dsp.vc1_loop_filter(s->dest[0] + 8*s->linesize, 1, s->linesize, 16, pq);

    for(i = !s->mb_x*8; i < 16; i += 8)

        s->dsp.vc1_loop_filter(s->dest[0] + i, s->linesize, 1, 16, pq);

    for(j = 0; j < 2; j++){

        if(!s->first_slice_line)

            s->dsp.vc1_loop_filter(s->dest[j+1], 1, s->uvlinesize, 8, pq);

        if(s->mb_x)

            s->dsp.vc1_loop_filter(s->dest[j+1], s->uvlinesize, 1, 8, pq);

    }

}

void ff_fix_long_p_mvs(MpegEncContext * s)

{

    const int f_code= s->f_code;

    int y;

    UINT8 * fcode_tab= s->fcode_tab;



    /* clip / convert to intra 16x16 type MVs */

    for(y=0; y<s->mb_height; y++){

        int x;

        int xy= (y+1)* (s->mb_width+2)+1;

        int i= y*s->mb_width;

        for(x=0; x<s->mb_width; x++){

            if(s->mb_type[i]&MB_TYPE_INTER){

                if(   fcode_tab[s->p_mv_table[xy][0] + MAX_MV] > f_code

                   || fcode_tab[s->p_mv_table[xy][0] + MAX_MV] == 0

                   || fcode_tab[s->p_mv_table[xy][1] + MAX_MV] > f_code

                   || fcode_tab[s->p_mv_table[xy][1] + MAX_MV] == 0 ){

                    s->mb_type[i] &= ~MB_TYPE_INTER;

                    s->mb_type[i] |= MB_TYPE_INTRA;

                    s->p_mv_table[xy][0] = 0;

                    s->p_mv_table[xy][1] = 0;

                }

            }

            xy++;

            i++;

        }

    }



    if(s->flags&CODEC_FLAG_4MV){

        const int wrap= 2+ s->mb_width*2;



        /* clip / convert to intra 8x8 type MVs */

        for(y=0; y<s->mb_height; y++){

            int xy= (y*2 + 1)*wrap + 1;

            int i= y*s->mb_width;

            int x;



            for(x=0; x<s->mb_width; x++){

                if(s->mb_type[i]&MB_TYPE_INTER4V){

                    int block;

                    for(block=0; block<4; block++){

                        int off= (block& 1) + (block>>1)*wrap;

                        int mx= s->motion_val[ xy + off ][0];

                        int my= s->motion_val[ xy + off ][1];



                        if(   fcode_tab[mx + MAX_MV] > f_code

                           || fcode_tab[mx + MAX_MV] == 0

                           || fcode_tab[my + MAX_MV] > f_code

                           || fcode_tab[my + MAX_MV] == 0 ){

                            s->mb_type[i] &= ~MB_TYPE_INTER4V;

                            s->mb_type[i] |= MB_TYPE_INTRA;

                        }

                    }

                    xy+=2;

                    i++;

                }

            }

        }

    }

}

