static void gen_arith_imm(DisasContext *ctx, uint32_t opc,

                          int rt, int rs, int16_t imm)

{

    target_ulong uimm = (target_long)imm; /* Sign extend to 32/64 bits */

    const char *opn = "imm arith";



    if (rt == 0 && opc != OPC_ADDI && opc != OPC_DADDI) {

        /* If no destination, treat it as a NOP.

           For addi, we must generate the overflow exception when needed. */

        MIPS_DEBUG("NOP");

        return;

    }

    switch (opc) {

    case OPC_ADDI:

        {

            TCGv t0 = tcg_temp_local_new();

            TCGv t1 = tcg_temp_new();

            TCGv t2 = tcg_temp_new();

            int l1 = gen_new_label();



            gen_load_gpr(t1, rs);

            tcg_gen_addi_tl(t0, t1, uimm);

            tcg_gen_ext32s_tl(t0, t0);



            tcg_gen_xori_tl(t1, t1, ~uimm);

            tcg_gen_xori_tl(t2, t0, uimm);

            tcg_gen_and_tl(t1, t1, t2);

            tcg_temp_free(t2);

            tcg_gen_brcondi_tl(TCG_COND_GE, t1, 0, l1);

            tcg_temp_free(t1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

            tcg_gen_ext32s_tl(t0, t0);

            gen_store_gpr(t0, rt);

            tcg_temp_free(t0);

        }

        opn = "addi";

        break;

    case OPC_ADDIU:

        if (rs != 0) {

            tcg_gen_addi_tl(cpu_gpr[rt], cpu_gpr[rs], uimm);

            tcg_gen_ext32s_tl(cpu_gpr[rt], cpu_gpr[rt]);

        } else {

            tcg_gen_movi_tl(cpu_gpr[rt], uimm);

        }

        opn = "addiu";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DADDI:

        {

            TCGv t0 = tcg_temp_local_new();

            TCGv t1 = tcg_temp_new();

            TCGv t2 = tcg_temp_new();

            int l1 = gen_new_label();



            gen_load_gpr(t1, rs);

            tcg_gen_addi_tl(t0, t1, uimm);



            tcg_gen_xori_tl(t1, t1, ~uimm);

            tcg_gen_xori_tl(t2, t0, uimm);

            tcg_gen_and_tl(t1, t1, t2);

            tcg_temp_free(t2);

            tcg_gen_brcondi_tl(TCG_COND_GE, t1, 0, l1);

            tcg_temp_free(t1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

            gen_store_gpr(t0, rt);

            tcg_temp_free(t0);

        }

        opn = "daddi";

        break;

    case OPC_DADDIU:

        if (rs != 0) {

            tcg_gen_addi_tl(cpu_gpr[rt], cpu_gpr[rs], uimm);

        } else {

            tcg_gen_movi_tl(cpu_gpr[rt], uimm);

        }

        opn = "daddiu";

        break;

#endif

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s, %s, " TARGET_FMT_lx, opn, regnames[rt], regnames[rs], uimm);

}

static void disas_test_b_imm(DisasContext *s, uint32_t insn)

{

    unsigned int bit_pos, op, rt;

    uint64_t addr;

    int label_match;

    TCGv_i64 tcg_cmp;



    bit_pos = (extract32(insn, 31, 1) << 5) | extract32(insn, 19, 5);

    op = extract32(insn, 24, 1); /* 0: TBZ; 1: TBNZ */

    addr = s->pc + sextract32(insn, 5, 14) * 4 - 4;

    rt = extract32(insn, 0, 5);



    tcg_cmp = tcg_temp_new_i64();

    tcg_gen_andi_i64(tcg_cmp, cpu_reg(s, rt), (1ULL << bit_pos));

    label_match = gen_new_label();

    tcg_gen_brcondi_i64(op ? TCG_COND_NE : TCG_COND_EQ,

                        tcg_cmp, 0, label_match);

    tcg_temp_free_i64(tcg_cmp);

    gen_goto_tb(s, 0, s->pc);

    gen_set_label(label_match);

    gen_goto_tb(s, 1, addr);

}

static void gen_movci (DisasContext *ctx, int rd, int rs, int cc, int tf)

{

    int l1 = gen_new_label();

    uint32_t ccbit;

    TCGCond cond;

    TCGv t0 = tcg_temp_local_new(TCG_TYPE_TL);

    TCGv t1 = tcg_temp_local_new(TCG_TYPE_TL);

    TCGv r_tmp = tcg_temp_local_new(TCG_TYPE_I32);



    if (cc)

        ccbit = 1 << (24 + cc);

    else

        ccbit = 1 << 23;

    if (tf)

        cond = TCG_COND_EQ;

    else

        cond = TCG_COND_NE;



    gen_load_gpr(t0, rd);

    gen_load_gpr(t1, rs);

    tcg_gen_andi_i32(r_tmp, fpu_fcr31, ccbit);

    tcg_gen_brcondi_i32(cond, r_tmp, 0, l1);

    tcg_temp_free(r_tmp);



    tcg_gen_mov_tl(t0, t1);

    tcg_temp_free(t1);



    gen_set_label(l1);

    gen_store_gpr(t0, rd);

    tcg_temp_free(t0);

}

static int64_t qemu_icount_delta(void)

{

    if (!use_icount) {

        return 5000 * (int64_t) 1000000;

    } else if (use_icount == 1) {

        /* When not using an adaptive execution frequency

           we tend to get badly out of sync with real time,

           so just delay for a reasonable amount of time.  */

        return 0;

    } else {

        return cpu_get_icount() - cpu_get_clock();

    }

}

static int update_offset(RTMPContext *rt, int size)

{

    int old_flv_size;



    // generate packet header and put data into buffer for FLV demuxer

    if (rt->flv_off < rt->flv_size) {

        // There is old unread data in the buffer, thus append at the end

        old_flv_size  = rt->flv_size;

        rt->flv_size += size + 15;

    } else {

        // All data has been read, write the new data at the start of the buffer

        old_flv_size = 0;

        rt->flv_size = size + 15;

        rt->flv_off  = 0;

    }



    return old_flv_size;

}

static int qemu_calculate_timeout(void)

{

#ifndef CONFIG_IOTHREAD

    int timeout;



    if (!vm_running)

        timeout = 5000;

    else if (tcg_has_work())

        timeout = 0;

    else {

     /* XXX: use timeout computed from timers */

        int64_t add;

        int64_t delta;

        /* Advance virtual time to the next event.  */

	delta = qemu_icount_delta();

        if (delta > 0) {

            /* If virtual time is ahead of real time then just

               wait for IO.  */

            timeout = (delta + 999999) / 1000000;

        } else {

            /* Wait for either IO to occur or the next

               timer event.  */

            add = qemu_next_deadline();

            /* We advance the timer before checking for IO.

               Limit the amount we advance so that early IO

               activity won't get the guest too far ahead.  */

            if (add > 10000000)

                add = 10000000;

            delta += add;

            qemu_icount += qemu_icount_round (add);

            timeout = delta / 1000000;

            if (timeout < 0)

                timeout = 0;

        }

    }



    return timeout;

#else /* CONFIG_IOTHREAD */

    return 1000;

#endif

}

void ptimer_set_limit(ptimer_state *s, uint64_t limit, int reload)

{

    /*

     * Artificially limit timeout rate to something

     * achievable under QEMU.  Otherwise, QEMU spends all

     * its time generating timer interrupts, and there

     * is no forward progress.

     * About ten microseconds is the fastest that really works

     * on the current generation of host machines.

     */



    if (!use_icount && limit * s->period < 10000 && s->period) {

        limit = 10000 / s->period;

    }



    s->limit = limit;

    if (reload)

        s->delta = limit;

    if (s->enabled && reload) {

        s->next_event = qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL);

        ptimer_reload(s);

    }

}

static int ftp_open(URLContext *h, const char *url, int flags)

{

    char proto[10], path[MAX_URL_SIZE];

    int err;

    FTPContext *s = h->priv_data;



    av_dlog(h, "ftp protocol open\n");



    s->state = DISCONNECTED;

    s->filesize = -1;

    s->position = 0;



    av_url_split(proto, sizeof(proto),

                 s->credencials, sizeof(s->credencials),

                 s->hostname, sizeof(s->hostname),

                 &s->server_control_port,

                 path, sizeof(path),

                 url);



    if (s->server_control_port < 0 || s->server_control_port > 65535)

        s->server_control_port = 21;



    if ((err = ftp_connect_control_connection(h)) < 0)

        goto fail;



    if ((err = ftp_current_dir(s)) < 0)

        goto fail;

    av_strlcat(s->path, path, sizeof(s->path));



    if (ftp_restart(s, 0) < 0) {

        h->is_streamed = 1;

    } else {

        if (ftp_file_size(s) < 0 && flags & AVIO_FLAG_READ)

            h->is_streamed = 1;

        if (s->write_seekable != 1 && flags & AVIO_FLAG_WRITE)

            h->is_streamed = 1;

    }



    return 0;



  fail:

    av_log(h, AV_LOG_ERROR, "FTP open failed\n");

    ffurl_closep(&s->conn_control);

    ffurl_closep(&s->conn_data);

    return err;

}

static int ftp_auth(FTPContext *s, char *auth)

{

    const char *user = NULL, *pass = NULL;

    char *end = NULL, buf[CONTROL_BUFFER_SIZE];

    int err;

    av_assert2(auth);



    user = av_strtok(auth, ":", &end);

    pass = av_strtok(end, ":", &end);



    if (user) {

        snprintf(buf, sizeof(buf), "USER %s\r\n", user);

        if ((err = ffurl_write(s->conn_control, buf, strlen(buf))) < 0)

            return err;

        ftp_status(s, &err, NULL, NULL, NULL, -1);

        if (err == 3) {

            if (pass) {

                snprintf(buf, sizeof(buf), "PASS %s\r\n", pass);

                if ((err = ffurl_write(s->conn_control, buf, strlen(buf))) < 0)

                    return err;

                ftp_status(s, &err, NULL, NULL, NULL, -1);

            } else

                return AVERROR(EACCES);

        }

        if (err != 2) {

            return AVERROR(EACCES);

        }

    } else {

        const char* command = "USER anonymous\r\n";

        if ((err = ffurl_write(s->conn_control, command, strlen(command))) < 0)

            return err;

        ftp_status(s, &err, NULL, NULL, NULL, -1);

        if (err == 3) {

            if (s->anonymous_password) {

                snprintf(buf, sizeof(buf), "PASS %s\r\n", s->anonymous_password);

            } else

                snprintf(buf, sizeof(buf), "PASS nopassword\r\n");

            if ((err = ffurl_write(s->conn_control, buf, strlen(buf))) < 0)

                return err;

            ftp_status(s, &err, NULL, NULL, NULL, -1);

        }

        if (err != 2) {

            return AVERROR(EACCES);

        }

    }



    return 0;

}

static int config_output(AVFilterLink *outlink) {

    static const char hdcd_baduse[] =

        "The HDCD filter is unlikely to produce a desirable result in this context.";

    AVFilterContext *ctx = outlink->src;

    HDCDContext *s = ctx->priv;

    AVFilterLink *lk = outlink;

    while(lk != NULL) {

        AVFilterContext *nextf = lk->dst;

        if (lk->type == AVMEDIA_TYPE_AUDIO) {

            if (lk->format == AV_SAMPLE_FMT_S16 || lk->format == AV_SAMPLE_FMT_U8) {

                av_log(ctx, AV_LOG_WARNING, "s24 output is being truncated to %s at %s.\n",

                    av_get_sample_fmt_name(lk->format),

                    (nextf->name) ? nextf->name : "<unknown>"

                    );

                s->bad_config = 1;

                break;

            }

        }

        lk = (nextf->outputs) ? nextf->outputs[0] : NULL;

    }

    if (s->bad_config)

        av_log(ctx, AV_LOG_WARNING, "%s\n", hdcd_baduse);

    return 0;

}

static int ftp_connect_data_connection(URLContext *h)

{

    int err;

    char buf[CONTROL_BUFFER_SIZE], opts_format[20];

    AVDictionary *opts = NULL;

    FTPContext *s = h->priv_data;



    if (!s->conn_data) {

        /* Enter passive mode */

        if ((err = ftp_passive_mode(s)) < 0) {

            av_dlog(h, "Set passive mode failed\n");

            return err;

        }

        /* Open data connection */

        ff_url_join(buf, sizeof(buf), "tcp", NULL, s->hostname, s->server_data_port, NULL);

        if (s->rw_timeout != -1) {

            snprintf(opts_format, sizeof(opts_format), "%d", s->rw_timeout);

            av_dict_set(&opts, "timeout", opts_format, 0);

        } /* if option is not given, don't pass it and let tcp use its own default */

        err = ffurl_open(&s->conn_data, buf, AVIO_FLAG_READ_WRITE,

                         &h->interrupt_callback, &opts);

        av_dict_free(&opts);

        if (err < 0)

            return err;



        if (s->position)

            if ((err = ftp_restart(s, s->position)) < 0)

                return err;

    }

    s->state = READY;

    return 0;

}

static int rtmp_packet_read_one_chunk(URLContext *h, RTMPPacket *p,

                                      int chunk_size, RTMPPacket **prev_pkt_ptr,

                                      int *nb_prev_pkt, uint8_t hdr)

{



    uint8_t buf[16];

    int channel_id, timestamp, size;

    uint32_t ts_field; // non-extended timestamp or delta field

    uint32_t extra = 0;

    enum RTMPPacketType type;

    int written = 0;

    int ret, toread;

    RTMPPacket *prev_pkt;



    written++;

    channel_id = hdr & 0x3F;



    if (channel_id < 2) { //special case for channel number >= 64

        buf[1] = 0;

        if (ffurl_read_complete(h, buf, channel_id + 1) != channel_id + 1)

            return AVERROR(EIO);

        written += channel_id + 1;

        channel_id = AV_RL16(buf) + 64;

    }

    if ((ret = ff_rtmp_check_alloc_array(prev_pkt_ptr, nb_prev_pkt,

                                         channel_id)) < 0)

        return ret;

    prev_pkt = *prev_pkt_ptr;

    size  = prev_pkt[channel_id].size;

    type  = prev_pkt[channel_id].type;

    extra = prev_pkt[channel_id].extra;



    hdr >>= 6; // header size indicator

    if (hdr == RTMP_PS_ONEBYTE) {

        ts_field = prev_pkt[channel_id].ts_field;

    } else {

        if (ffurl_read_complete(h, buf, 3) != 3)

            return AVERROR(EIO);

        written += 3;

        ts_field = AV_RB24(buf);

        if (hdr != RTMP_PS_FOURBYTES) {

            if (ffurl_read_complete(h, buf, 3) != 3)

                return AVERROR(EIO);

            written += 3;

            size = AV_RB24(buf);

            if (ffurl_read_complete(h, buf, 1) != 1)

                return AVERROR(EIO);

            written++;

            type = buf[0];

            if (hdr == RTMP_PS_TWELVEBYTES) {

                if (ffurl_read_complete(h, buf, 4) != 4)

                    return AVERROR(EIO);

                written += 4;

                extra = AV_RL32(buf);

            }

        }

    }

    if (ts_field == 0xFFFFFF) {

        if (ffurl_read_complete(h, buf, 4) != 4)

            return AVERROR(EIO);

        timestamp = AV_RB32(buf);

    } else {

        timestamp = ts_field;

    }

    if (hdr != RTMP_PS_TWELVEBYTES)

        timestamp += prev_pkt[channel_id].timestamp;



    if (!prev_pkt[channel_id].read) {

        if ((ret = ff_rtmp_packet_create(p, channel_id, type, timestamp,

                                         size)) < 0)

            return ret;

        p->read = written;

        p->offset = 0;

        prev_pkt[channel_id].ts_field   = ts_field;

        prev_pkt[channel_id].timestamp  = timestamp;

    } else {

        // previous packet in this channel hasn't completed reading

        RTMPPacket *prev = &prev_pkt[channel_id];

        p->data          = prev->data;

        p->size          = prev->size;

        p->channel_id    = prev->channel_id;

        p->type          = prev->type;

        p->ts_field      = prev->ts_field;

        p->extra         = prev->extra;

        p->offset        = prev->offset;

        p->read          = prev->read + written;

        p->timestamp     = prev->timestamp;

        prev->data       = NULL;

    }

    p->extra = extra;

    // save history

    prev_pkt[channel_id].channel_id = channel_id;

    prev_pkt[channel_id].type       = type;

    prev_pkt[channel_id].size       = size;

    prev_pkt[channel_id].extra      = extra;

    size = size - p->offset;



    toread = FFMIN(size, chunk_size);

    if (ffurl_read_complete(h, p->data + p->offset, toread) != toread) {

        ff_rtmp_packet_destroy(p);

        return AVERROR(EIO);

    }

    size      -= toread;

    p->read   += toread;

    p->offset += toread;



    if (size > 0) {

       RTMPPacket *prev = &prev_pkt[channel_id];

       prev->data = p->data;

       prev->read = p->read;

       prev->offset = p->offset;


       return AVERROR(EAGAIN);

    }



    prev_pkt[channel_id].read = 0; // read complete; reset if needed

    return p->read;

}

static int wsaud_read_packet(AVFormatContext *s,
                             AVPacket *pkt)
{
    AVIOContext *pb = s->pb;
    unsigned char preamble[AUD_CHUNK_PREAMBLE_SIZE];
    unsigned int chunk_size;
    int ret = 0;
    AVStream *st = s->streams[0];
    if (avio_read(pb, preamble, AUD_CHUNK_PREAMBLE_SIZE) !=
        AUD_CHUNK_PREAMBLE_SIZE)
        return AVERROR(EIO);
    /* validate the chunk */
    if (AV_RL32(&preamble[4]) != AUD_CHUNK_SIGNATURE)
    chunk_size = AV_RL16(&preamble[0]);
    if (st->codecpar->codec_id == AV_CODEC_ID_WESTWOOD_SND1) {
        /* For Westwood SND1 audio we need to add the output size and input
           size to the start of the packet to match what is in VQA.
           Specifically, this is needed to signal when a packet should be
           decoding as raw 8-bit pcm or variable-size ADPCM. */
        int out_size = AV_RL16(&preamble[2]);
        if ((ret = av_new_packet(pkt, chunk_size + 4)) < 0)
            return ret;
        if ((ret = avio_read(pb, &pkt->data[4], chunk_size)) != chunk_size)
            return ret < 0 ? ret : AVERROR(EIO);
        AV_WL16(&pkt->data[0], out_size);
        AV_WL16(&pkt->data[2], chunk_size);
        pkt->duration = out_size;
    } else {
        ret = av_get_packet(pb, pkt, chunk_size);
        if (ret != chunk_size)
            return AVERROR(EIO);
        /* 2 samples/byte, 1 or 2 samples per frame depending on stereo */
        pkt->duration = (chunk_size * 2) / st->codecpar->channels;
    pkt->stream_index = st->index;
    return ret;

static int get_packet(URLContext *s, int for_header)

{

    RTMPContext *rt = s->priv_data;

    int ret;

    uint8_t *p;

    const uint8_t *next;

    uint32_t data_size;

    uint32_t ts, cts, pts=0;



    if (rt->state == STATE_STOPPED)

        return AVERROR_EOF;



    for (;;) {

        RTMPPacket rpkt = { 0 };

        if ((ret = ff_rtmp_packet_read(rt->stream, &rpkt,

                                       rt->chunk_size, rt->prev_pkt[0])) <= 0) {

            if (ret == 0) {

                return AVERROR(EAGAIN);

            } else {

                return AVERROR(EIO);

            }

        }

        rt->bytes_read += ret;

        if (rt->bytes_read > rt->last_bytes_read + rt->client_report_size) {

            av_log(s, AV_LOG_DEBUG, "Sending bytes read report\n");

            gen_bytes_read(s, rt, rpkt.timestamp + 1);

            rt->last_bytes_read = rt->bytes_read;

        }



        ret = rtmp_parse_result(s, rt, &rpkt);

        if (ret < 0) {//serious error in current packet

            ff_rtmp_packet_destroy(&rpkt);

            return -1;

        }

        if (rt->state == STATE_STOPPED) {

            ff_rtmp_packet_destroy(&rpkt);

            return AVERROR_EOF;

        }

        if (for_header && (rt->state == STATE_PLAYING || rt->state == STATE_PUBLISHING)) {

            ff_rtmp_packet_destroy(&rpkt);

            return 0;

        }

        if (!rpkt.data_size || !rt->is_input) {

            ff_rtmp_packet_destroy(&rpkt);

            continue;

        }

        if (rpkt.type == RTMP_PT_VIDEO || rpkt.type == RTMP_PT_AUDIO ||

           (rpkt.type == RTMP_PT_NOTIFY && !memcmp("\002\000\012onMetaData", rpkt.data, 13))) {

            ts = rpkt.timestamp;



            // generate packet header and put data into buffer for FLV demuxer

            rt->flv_off  = 0;

            rt->flv_size = rpkt.data_size + 15;

            rt->flv_data = p = av_realloc(rt->flv_data, rt->flv_size);

            bytestream_put_byte(&p, rpkt.type);

            bytestream_put_be24(&p, rpkt.data_size);

            bytestream_put_be24(&p, ts);

            bytestream_put_byte(&p, ts >> 24);

            bytestream_put_be24(&p, 0);

            bytestream_put_buffer(&p, rpkt.data, rpkt.data_size);

            bytestream_put_be32(&p, 0);

            ff_rtmp_packet_destroy(&rpkt);

            return 0;

        } else if (rpkt.type == RTMP_PT_METADATA) {

            // we got raw FLV data, make it available for FLV demuxer

            rt->flv_off  = 0;

            rt->flv_size = rpkt.data_size;

            rt->flv_data = av_realloc(rt->flv_data, rt->flv_size);

            /* rewrite timestamps */

            next = rpkt.data;

            ts = rpkt.timestamp;

            while (next - rpkt.data < rpkt.data_size - 11) {

                next++;

                data_size = bytestream_get_be24(&next);

                p=next;

                cts = bytestream_get_be24(&next);

                cts |= bytestream_get_byte(&next) << 24;

                if (pts==0)

                    pts=cts;

                ts += cts - pts;

                pts = cts;

                bytestream_put_be24(&p, ts);

                bytestream_put_byte(&p, ts >> 24);

                next += data_size + 3 + 4;

            }

            memcpy(rt->flv_data, rpkt.data, rpkt.data_size);

            ff_rtmp_packet_destroy(&rpkt);

            return 0;

        }

        ff_rtmp_packet_destroy(&rpkt);

    }

    return 0;

}

static int rtmp_write(URLContext *s, const uint8_t *buf, int size)
{
    RTMPContext *rt = s->priv_data;
    int size_temp = size;
    int pktsize, pkttype;
    uint32_t ts;
    const uint8_t *buf_temp = buf;
    uint8_t c;
    int ret;
    do {
        if (rt->skip_bytes) {
            int skip = FFMIN(rt->skip_bytes, size_temp);
            buf_temp       += skip;
            size_temp      -= skip;
            rt->skip_bytes -= skip;
            continue;
        if (rt->flv_header_bytes < 11) {
            const uint8_t *header = rt->flv_header;
            int copy = FFMIN(11 - rt->flv_header_bytes, size_temp);
            bytestream_get_buffer(&buf_temp, rt->flv_header + rt->flv_header_bytes, copy);
            rt->flv_header_bytes += copy;
            size_temp            -= copy;
            if (rt->flv_header_bytes < 11)
                break;
            pkttype = bytestream_get_byte(&header);
            pktsize = bytestream_get_be24(&header);
            ts = bytestream_get_be24(&header);
            ts |= bytestream_get_byte(&header) << 24;
            bytestream_get_be24(&header);
            rt->flv_size = pktsize;
            //force 12bytes header
            if (((pkttype == RTMP_PT_VIDEO || pkttype == RTMP_PT_AUDIO) && ts == 0) ||
                pkttype == RTMP_PT_NOTIFY) {
                if (pkttype == RTMP_PT_NOTIFY)
                    pktsize += 16;
                rt->prev_pkt[1][RTMP_SOURCE_CHANNEL].channel_id = 0;
            //this can be a big packet, it's better to send it right here
            if ((ret = ff_rtmp_packet_create(&rt->out_pkt, RTMP_SOURCE_CHANNEL,
                                             pkttype, ts, pktsize)) < 0)
            rt->out_pkt.extra = rt->main_channel_id;
            rt->flv_data = rt->out_pkt.data;
            if (pkttype == RTMP_PT_NOTIFY)
                ff_amf_write_string(&rt->flv_data, "@setDataFrame");
        if (rt->flv_size - rt->flv_off > size_temp) {
            bytestream_get_buffer(&buf_temp, rt->flv_data + rt->flv_off, size_temp);
            rt->flv_off += size_temp;
            size_temp = 0;
        } else {
            bytestream_get_buffer(&buf_temp, rt->flv_data + rt->flv_off, rt->flv_size - rt->flv_off);
            size_temp   -= rt->flv_size - rt->flv_off;
            rt->flv_off += rt->flv_size - rt->flv_off;
        if (rt->flv_off == rt->flv_size) {
            rt->skip_bytes = 4;
            if ((ret = ff_rtmp_packet_write(rt->stream, &rt->out_pkt,
                                            rt->chunk_size, rt->prev_pkt[1])) < 0)
            ff_rtmp_packet_destroy(&rt->out_pkt);
            rt->flv_size = 0;
            rt->flv_off = 0;
            rt->flv_header_bytes = 0;
    } while (buf_temp - buf < size);

static int mpegvideo_probe(AVProbeData *p)

{

    uint32_t code= -1;

    int pic=0, seq=0, slice=0, pspack=0, vpes=0, apes=0, res=0, sicle=0;

    int i;

    uint32_t last = 0;



    for(i=0; i<p->buf_size; i++){

        code = (code<<8) + p->buf[i];

        if ((code & 0xffffff00) == 0x100) {

            switch(code){

            case     SEQ_START_CODE:   seq++; break;

            case PICTURE_START_CODE:   pic++; break;

            case    PACK_START_CODE: pspack++; break;

            case              0x1b6:

                                        res++; break;

            }

            if (code >= SLICE_START_CODE && code <= 0x1af) {

                if (last >= SLICE_START_CODE && last <= 0x1af) {

                    if (code >= last) slice++;

                    else              sicle++;

                }else{

                    if (code == SLICE_START_CODE) slice++;

                    else                          sicle++;

                }

            }

            if     ((code & 0x1f0) == VIDEO_ID)   vpes++;

            else if((code & 0x1e0) == AUDIO_ID)   apes++;

            last = code;

        }

    }

    if(seq && seq*9<=pic*10 && pic*9<=slice*10 && !pspack && !apes && !res && slice > sicle) {

        if(vpes) return AVPROBE_SCORE_EXTENSION / 4;

        else     return pic>1 ? AVPROBE_SCORE_EXTENSION + 1 : AVPROBE_SCORE_EXTENSION / 2; // +1 for .mpg

    }

    return 0;

}

static void eeprom24c0x_write(int scl, int sda)

{

    if (eeprom.scl && scl && (eeprom.sda != sda)) {

        logout("%u: scl = %u->%u, sda = %u->%u i2c %s\n",

                eeprom.tick, eeprom.scl, scl, eeprom.sda, sda, sda ? "stop" : "start");

        if (!sda) {

            eeprom.tick = 1;

            eeprom.command = 0;

        }

    } else if (eeprom.tick == 0 && !eeprom.ack) {

        /* Waiting for start. */

        logout("%u: scl = %u->%u, sda = %u->%u wait for i2c start\n",

                eeprom.tick, eeprom.scl, scl, eeprom.sda, sda);

    } else if (!eeprom.scl && scl) {

        logout("%u: scl = %u->%u, sda = %u->%u trigger bit\n",

                eeprom.tick, eeprom.scl, scl, eeprom.sda, sda);

        if (eeprom.ack) {

            logout("\ti2c ack bit = 0\n");

            sda = 0;

            eeprom.ack = 0;

        } else if (eeprom.sda == sda) {

            uint8_t bit = (sda != 0);

            logout("\ti2c bit = %d\n", bit);

            if (eeprom.tick < 9) {

                eeprom.command <<= 1;

                eeprom.command += bit;

                eeprom.tick++;

                if (eeprom.tick == 9) {

                    logout("\tcommand 0x%04x, %s\n", eeprom.command, bit ? "read" : "write");

                    eeprom.ack = 1;

                }

            } else if (eeprom.tick < 17) {

                if (eeprom.command & 1) {

                    sda = ((eeprom.data & 0x80) != 0);

                }

                eeprom.address <<= 1;

                eeprom.address += bit;

                eeprom.tick++;

                eeprom.data <<= 1;

                if (eeprom.tick == 17) {

                    eeprom.data = eeprom.contents[eeprom.address];

                    logout("\taddress 0x%04x, data 0x%02x\n", eeprom.address, eeprom.data);

                    eeprom.ack = 1;

                    eeprom.tick = 0;

                }

            } else if (eeprom.tick >= 17) {

                sda = 0;

            }

        } else {

            logout("\tsda changed with raising scl\n");

        }

    } else {

        logout("%u: scl = %u->%u, sda = %u->%u\n", eeprom.tick, eeprom.scl, scl, eeprom.sda, sda);

    }

    eeprom.scl = scl;

    eeprom.sda = sda;

}

eeprom_t *eeprom93xx_new(DeviceState *dev, uint16_t nwords)

{

    /* Add a new EEPROM (with 16, 64 or 256 words). */

    eeprom_t *eeprom;

    uint8_t addrbits;



    switch (nwords) {

        case 16:

        case 64:

            addrbits = 6;

            break;

        case 128:

        case 256:

            addrbits = 8;

            break;

        default:

            assert(!"Unsupported EEPROM size, fallback to 64 words!");

            nwords = 64;

            addrbits = 6;

    }



    eeprom = (eeprom_t *)g_malloc0(sizeof(*eeprom) + nwords * 2);

    eeprom->size = nwords;

    eeprom->addrbits = addrbits;

    /* Output DO is tristate, read results in 1. */

    eeprom->eedo = 1;

    logout("eeprom = 0x%p, nwords = %u\n", eeprom, nwords);

    vmstate_register(dev, 0, &vmstate_eeprom, eeprom);

    return eeprom;

}

void pci_default_write_config(PCIDevice *d,

                              uint32_t address, uint32_t val, int len)

{

    int can_write, i;

    uint32_t end, addr;



    if (len == 4 && ((address >= 0x10 && address < 0x10 + 4 * 6) ||

                     (address >= 0x30 && address < 0x34))) {

        PCIIORegion *r;

        int reg;



        if ( address >= 0x30 ) {

            reg = PCI_ROM_SLOT;

        }else{

            reg = (address - 0x10) >> 2;

        }

        r = &d->io_regions[reg];

        if (r->size == 0)

            goto default_config;

        /* compute the stored value */

        if (reg == PCI_ROM_SLOT) {

            /* keep ROM enable bit */

            val &= (~(r->size - 1)) | 1;

        } else {

            val &= ~(r->size - 1);

            val |= r->type;

        }

        *(uint32_t *)(d->config + address) = cpu_to_le32(val);

        pci_update_mappings(d);

        return;

    }

 default_config:

    /* not efficient, but simple */

    addr = address;

    for(i = 0; i < len; i++) {

        /* default read/write accesses */

        switch(d->config[0x0e]) {

        case 0x00:

        case 0x80:

            switch(addr) {

            case 0x00:

            case 0x01:

            case 0x02:

            case 0x03:

            case 0x06:

            case 0x07:

            case 0x08:

            case 0x09:

            case 0x0a:

            case 0x0b:

            case 0x0e:

            case 0x10 ... 0x27: /* base */

            case 0x2c ... 0x2f: /* read-only subsystem ID & vendor ID */

            case 0x30 ... 0x33: /* rom */

            case 0x3d:

                can_write = 0;

                break;

            default:

                can_write = 1;

                break;

            }

            break;

        default:

        case 0x01:

            switch(addr) {

            case 0x00:

            case 0x01:

            case 0x02:

            case 0x03:

            case 0x06:

            case 0x07:

            case 0x08:

            case 0x09:

            case 0x0a:

            case 0x0b:

            case 0x0e:

            case 0x2c ... 0x2f: /* read-only subsystem ID & vendor ID */

            case 0x38 ... 0x3b: /* rom */

            case 0x3d:

                can_write = 0;

                break;

            default:

                can_write = 1;

                break;

            }

            break;

        }

        if (can_write) {

            /* Mask out writes to reserved bits in registers */

            switch (addr) {

	    case 0x05:

                val &= ~PCI_COMMAND_RESERVED_MASK_HI;

                break;

            case 0x06:

                val &= ~PCI_STATUS_RESERVED_MASK_LO;

                break;

            case 0x07:

                val &= ~PCI_STATUS_RESERVED_MASK_HI;

                break;

            }

            d->config[addr] = val;

        }

        if (++addr > 0xff)

        	break;

        val >>= 8;

    }



    end = address + len;

    if (end > PCI_COMMAND && address < (PCI_COMMAND + 2)) {

        /* if the command register is modified, we must modify the mappings */

        pci_update_mappings(d);

    }

}

static void *iothread_run(void *opaque)

{

    IOThread *iothread = opaque;



    rcu_register_thread();



    my_iothread = iothread;

    qemu_mutex_lock(&iothread->init_done_lock);

    iothread->thread_id = qemu_get_thread_id();

    qemu_cond_signal(&iothread->init_done_cond);

    qemu_mutex_unlock(&iothread->init_done_lock);



    while (!atomic_read(&iothread->stopping)) {

        aio_poll(iothread->ctx, true);



        if (atomic_read(&iothread->worker_context)) {

            GMainLoop *loop;



            g_main_context_push_thread_default(iothread->worker_context);

            iothread->main_loop =

                g_main_loop_new(iothread->worker_context, TRUE);

            loop = iothread->main_loop;



            g_main_loop_run(iothread->main_loop);

            iothread->main_loop = NULL;

            g_main_loop_unref(loop);



            g_main_context_pop_thread_default(iothread->worker_context);

        }

    }



    rcu_unregister_thread();

    return NULL;

}

static void iothread_complete(UserCreatable *obj, Error **errp)

{

    IOThread *iothread = IOTHREAD(obj);



    iothread->stopping = false;

    iothread->ctx = aio_context_new();

    iothread->thread_id = -1;



    qemu_mutex_init(&iothread->init_done_lock);

    qemu_cond_init(&iothread->init_done_cond);



    /* This assumes we are called from a thread with useful CPU affinity for us

     * to inherit.

     */

    qemu_thread_create(&iothread->thread, "iothread", iothread_run,

                       iothread, QEMU_THREAD_JOINABLE);



    /* Wait for initialization to complete */

    qemu_mutex_lock(&iothread->init_done_lock);

    while (iothread->thread_id == -1) {

        qemu_cond_wait(&iothread->init_done_cond,

                       &iothread->init_done_lock);

    }

    qemu_mutex_unlock(&iothread->init_done_lock);

}

static void *qemu_tcg_cpu_thread_fn(void *arg)

{

    CPUState *cpu = arg;



    qemu_tcg_init_cpu_signals();

    qemu_thread_get_self(cpu->thread);



    qemu_mutex_lock(&qemu_global_mutex);

    CPU_FOREACH(cpu) {

        cpu->thread_id = qemu_get_thread_id();

        cpu->created = true;

        cpu->exception_index = -1;

        cpu->can_do_io = 1;

    }

    qemu_cond_signal(&qemu_cpu_cond);



    /* wait for initial kick-off after machine start */

    while (QTAILQ_FIRST(&cpus)->stopped) {

        qemu_cond_wait(tcg_halt_cond, &qemu_global_mutex);



        /* process any pending work */

        CPU_FOREACH(cpu) {

            qemu_wait_io_event_common(cpu);

        }

    }



    while (1) {

        tcg_exec_all();



        if (use_icount) {

            int64_t deadline = qemu_clock_deadline_ns_all(QEMU_CLOCK_VIRTUAL);



            if (deadline == 0) {

                qemu_clock_notify(QEMU_CLOCK_VIRTUAL);

            }

        }

        qemu_tcg_wait_io_event();

    }



    return NULL;

}

static void *tcg_cpu_thread_fn(void *arg)

{

    CPUState *env = arg;



    qemu_tcg_init_cpu_signals();

    qemu_thread_self(env->thread);



    /* signal CPU creation */

    qemu_mutex_lock(&qemu_global_mutex);

    for (env = first_cpu; env != NULL; env = env->next_cpu)

        env->created = 1;

    qemu_cond_signal(&qemu_cpu_cond);



    /* and wait for machine initialization */

    while (!qemu_system_ready)

        qemu_cond_timedwait(&qemu_system_cond, &qemu_global_mutex, 100);



    while (1) {

        cpu_exec_all();

        qemu_tcg_wait_io_event();

    }



    return NULL;

}

