static const uint8_t *read_huffman_tables(FourXContext *f, const uint8_t * const buf){

    int frequency[512];

    uint8_t flag[512];

    int up[512];

    uint8_t len_tab[257];

    int bits_tab[257];

    int start, end;

    const uint8_t *ptr= buf;

    int j;



    memset(frequency, 0, sizeof(frequency));

    memset(up, -1, sizeof(up));



    start= *ptr++;

    end= *ptr++;

    for(;;){

        int i;



        for(i=start; i<=end; i++){

            frequency[i]= *ptr++;

        }

        start= *ptr++;

        if(start==0) break;



        end= *ptr++;

    }

    frequency[256]=1;



    while((ptr - buf)&3) ptr++; // 4byte align



    for(j=257; j<512; j++){

        int min_freq[2]= {256*256, 256*256};

        int smallest[2]= {0, 0};

        int i;

        for(i=0; i<j; i++){

            if(frequency[i] == 0) continue;

            if(frequency[i] < min_freq[1]){

                if(frequency[i] < min_freq[0]){

                    min_freq[1]= min_freq[0]; smallest[1]= smallest[0];

                    min_freq[0]= frequency[i];smallest[0]= i;

                }else{

                    min_freq[1]= frequency[i];smallest[1]= i;

                }

            }

        }

        if(min_freq[1] == 256*256) break;



        frequency[j]= min_freq[0] + min_freq[1];

        flag[ smallest[0] ]= 0;

        flag[ smallest[1] ]= 1;

        up[ smallest[0] ]=

        up[ smallest[1] ]= j;

        frequency[ smallest[0] ]= frequency[ smallest[1] ]= 0;

    }



    for(j=0; j<257; j++){

        int node;

        int len=0;

        int bits=0;



        for(node= j; up[node] != -1; node= up[node]){

            bits += flag[node]<<len;

            len++;

            if(len > 31) av_log(f->avctx, AV_LOG_ERROR, "vlc length overflow\n"); //can this happen at all ?

        }



        bits_tab[j]= bits;

        len_tab[j]= len;

    }



    init_vlc(&f->pre_vlc, ACDC_VLC_BITS, 257,

             len_tab , 1, 1,

             bits_tab, 4, 4, 0);



    return ptr;

}

static char *make_digest_auth(HTTPAuthState *state, const char *username,

                              const char *password, const char *uri,

                              const char *method)

{

    DigestParams *digest = &state->digest_params;

    int len;

    uint32_t cnonce_buf[2];

    char cnonce[17];

    char nc[9];

    int i;

    char A1hash[33], A2hash[33], response[33];

    struct AVMD5 *md5ctx;

    uint8_t hash[16];

    char *authstr;



    digest->nc++;

    snprintf(nc, sizeof(nc), "%08x", digest->nc);



    /* Generate a client nonce. */

    for (i = 0; i < 2; i++)

        cnonce_buf[i] = av_get_random_seed();

    ff_data_to_hex(cnonce, (const uint8_t*) cnonce_buf, sizeof(cnonce_buf), 1);

    cnonce[2*sizeof(cnonce_buf)] = 0;



    md5ctx = av_md5_alloc();

    if (!md5ctx)

        return NULL;



    av_md5_init(md5ctx);

    update_md5_strings(md5ctx, username, ":", state->realm, ":", password, NULL);

    av_md5_final(md5ctx, hash);

    ff_data_to_hex(A1hash, hash, 16, 1);

    A1hash[32] = 0;



    if (!strcmp(digest->algorithm, "") || !strcmp(digest->algorithm, "MD5")) {

    } else if (!strcmp(digest->algorithm, "MD5-sess")) {

        av_md5_init(md5ctx);

        update_md5_strings(md5ctx, A1hash, ":", digest->nonce, ":", cnonce, NULL);

        av_md5_final(md5ctx, hash);

        ff_data_to_hex(A1hash, hash, 16, 1);

        A1hash[32] = 0;

    } else {

        /* Unsupported algorithm */

        av_free(md5ctx);

        return NULL;

    }



    av_md5_init(md5ctx);

    update_md5_strings(md5ctx, method, ":", uri, NULL);

    av_md5_final(md5ctx, hash);

    ff_data_to_hex(A2hash, hash, 16, 1);

    A2hash[32] = 0;



    av_md5_init(md5ctx);

    update_md5_strings(md5ctx, A1hash, ":", digest->nonce, NULL);

    if (!strcmp(digest->qop, "auth") || !strcmp(digest->qop, "auth-int")) {

        update_md5_strings(md5ctx, ":", nc, ":", cnonce, ":", digest->qop, NULL);

    }

    update_md5_strings(md5ctx, ":", A2hash, NULL);

    av_md5_final(md5ctx, hash);

    ff_data_to_hex(response, hash, 16, 1);

    response[32] = 0;



    av_free(md5ctx);



    if (!strcmp(digest->qop, "") || !strcmp(digest->qop, "auth")) {

    } else if (!strcmp(digest->qop, "auth-int")) {

        /* qop=auth-int not supported */

        return NULL;

    } else {

        /* Unsupported qop value. */

        return NULL;

    }



    len = strlen(username) + strlen(state->realm) + strlen(digest->nonce) +

              strlen(uri) + strlen(response) + strlen(digest->algorithm) +

              strlen(digest->opaque) + strlen(digest->qop) + strlen(cnonce) +

              strlen(nc) + 150;



    authstr = av_malloc(len);

    if (!authstr)

        return NULL;

    snprintf(authstr, len, "Authorization: Digest ");



    /* TODO: Escape the quoted strings properly. */

    av_strlcatf(authstr, len, "username=\"%s\"",   username);

    av_strlcatf(authstr, len, ",realm=\"%s\"",     state->realm);

    av_strlcatf(authstr, len, ",nonce=\"%s\"",     digest->nonce);

    av_strlcatf(authstr, len, ",uri=\"%s\"",       uri);

    av_strlcatf(authstr, len, ",response=\"%s\"",  response);

    if (digest->algorithm[0])

        av_strlcatf(authstr, len, ",algorithm=%s",  digest->algorithm);

    if (digest->opaque[0])

        av_strlcatf(authstr, len, ",opaque=\"%s\"", digest->opaque);

    if (digest->qop[0]) {

        av_strlcatf(authstr, len, ",qop=\"%s\"",    digest->qop);

        av_strlcatf(authstr, len, ",cnonce=\"%s\"", cnonce);

        av_strlcatf(authstr, len, ",nc=%s",         nc);

    }



    av_strlcatf(authstr, len, "\r\n");



    return authstr;

}

rtsp_read_reply (AVFormatContext *s, RTSPMessageHeader *reply,

                 unsigned char **content_ptr, int return_on_interleaved_data)

{

    RTSPState *rt = s->priv_data;

    char buf[4096], buf1[1024], *q;

    unsigned char ch;

    const char *p;

    int ret, content_length, line_count = 0;

    unsigned char *content = NULL;



    memset(reply, 0, sizeof(*reply));



    /* parse reply (XXX: use buffers) */

    rt->last_reply[0] = '\0';

    for(;;) {

        q = buf;

        for(;;) {

            ret = url_read_complete(rt->rtsp_hd, &ch, 1);

#ifdef DEBUG_RTP_TCP

            dprintf(s, "ret=%d c=%02x [%c]\n", ret, ch, ch);

#endif

            if (ret != 1)

                return -1;

            if (ch == '\n')

                break;

            if (ch == '$') {

                /* XXX: only parse it if first char on line ? */

                if (return_on_interleaved_data) {

                    return 1;

                } else

                rtsp_skip_packet(s);

            } else if (ch != '\r') {

                if ((q - buf) < sizeof(buf) - 1)

                    *q++ = ch;

            }

        }

        *q = '\0';



        dprintf(s, "line='%s'\n", buf);



        /* test if last line */

        if (buf[0] == '\0')

            break;

        p = buf;

        if (line_count == 0) {

            /* get reply code */

            get_word(buf1, sizeof(buf1), &p);

            get_word(buf1, sizeof(buf1), &p);

            reply->status_code = atoi(buf1);

        } else {

            rtsp_parse_line(reply, p);

            av_strlcat(rt->last_reply, p,    sizeof(rt->last_reply));

            av_strlcat(rt->last_reply, "\n", sizeof(rt->last_reply));

        }

        line_count++;

    }



    if (rt->session_id[0] == '\0' && reply->session_id[0] != '\0')

        av_strlcpy(rt->session_id, reply->session_id, sizeof(rt->session_id));



    content_length = reply->content_length;

    if (content_length > 0) {

        /* leave some room for a trailing '\0' (useful for simple parsing) */

        content = av_malloc(content_length + 1);

        (void)url_read_complete(rt->rtsp_hd, content, content_length);

        content[content_length] = '\0';

    }

    if (content_ptr)

        *content_ptr = content;

    else

        av_free(content);



    /* EOS */

    if (reply->notice == 2101 /* End-of-Stream Reached */      ||

        reply->notice == 2104 /* Start-of-Stream Reached */    ||

        reply->notice == 2306 /* Continuous Feed Terminated */)

        rt->state = RTSP_STATE_IDLE;

    else if (reply->notice >= 4400 && reply->notice < 5500)

        return AVERROR(EIO); /* data or server error */

    else if (reply->notice == 2401 /* Ticket Expired */ ||

             (reply->notice >= 5500 && reply->notice < 5600) /* end of term */ )

        return AVERROR(EPERM);



    return 0;

}

static int write_reftable_entry(BlockDriverState *bs, int rt_index)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t buf[RT_ENTRIES_PER_SECTOR];

    int rt_start_index;

    int i, ret;



    rt_start_index = rt_index & ~(RT_ENTRIES_PER_SECTOR - 1);

    for (i = 0; i < RT_ENTRIES_PER_SECTOR; i++) {

        buf[i] = cpu_to_be64(s->refcount_table[rt_start_index + i]);

    }



    ret = qcow2_pre_write_overlap_check(bs,

            QCOW2_OL_DEFAULT & ~QCOW2_OL_REFCOUNT_TABLE,

            s->refcount_table_offset + rt_start_index * sizeof(uint64_t),

            sizeof(buf));

    if (ret < 0) {

        return ret;

    }



    BLKDBG_EVENT(bs->file, BLKDBG_REFTABLE_UPDATE);

    ret = bdrv_pwrite_sync(bs->file, s->refcount_table_offset +

            rt_start_index * sizeof(uint64_t), buf, sizeof(buf));

    if (ret < 0) {

        return ret;

    }



    return 0;

}

int qcow2_snapshot_goto(BlockDriverState *bs, const char *snapshot_id)

{

    BDRVQcowState *s = bs->opaque;

    QCowSnapshot *sn;

    int i, snapshot_index, l1_size2;



    snapshot_index = find_snapshot_by_id_or_name(bs, snapshot_id);

    if (snapshot_index < 0)

        return -ENOENT;

    sn = &s->snapshots[snapshot_index];



    if (qcow2_update_snapshot_refcount(bs, s->l1_table_offset, s->l1_size, -1) < 0)

        goto fail;



    if (qcow2_grow_l1_table(bs, sn->l1_size) < 0)

        goto fail;



    s->l1_size = sn->l1_size;

    l1_size2 = s->l1_size * sizeof(uint64_t);

    /* copy the snapshot l1 table to the current l1 table */

    if (bdrv_pread(bs->file, sn->l1_table_offset,

                   s->l1_table, l1_size2) != l1_size2)

        goto fail;

    if (bdrv_pwrite(bs->file, s->l1_table_offset,

                    s->l1_table, l1_size2) != l1_size2)

        goto fail;

    for(i = 0;i < s->l1_size; i++) {

        be64_to_cpus(&s->l1_table[i]);

    }



    if (qcow2_update_snapshot_refcount(bs, s->l1_table_offset, s->l1_size, 1) < 0)

        goto fail;



#ifdef DEBUG_ALLOC

    qcow2_check_refcounts(bs);

#endif

    return 0;

 fail:

    return -EIO;

}

static int write_l1_entry(BlockDriverState *bs, int l1_index)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t buf[L1_ENTRIES_PER_SECTOR];

    int l1_start_index;

    int i, ret;



    l1_start_index = l1_index & ~(L1_ENTRIES_PER_SECTOR - 1);

    for (i = 0; i < L1_ENTRIES_PER_SECTOR; i++) {

        buf[i] = cpu_to_be64(s->l1_table[l1_start_index + i]);

    }



    ret = qcow2_pre_write_overlap_check(bs,

            QCOW2_OL_DEFAULT & ~QCOW2_OL_ACTIVE_L1,

            s->l1_table_offset + 8 * l1_start_index, sizeof(buf));

    if (ret < 0) {

        return ret;

    }



    BLKDBG_EVENT(bs->file, BLKDBG_L1_UPDATE);

    ret = bdrv_pwrite_sync(bs->file, s->l1_table_offset + 8 * l1_start_index,

        buf, sizeof(buf));

    if (ret < 0) {

        return ret;

    }



    return 0;

}

static int qcow2_mark_dirty(BlockDriverState *bs)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t val;

    int ret;



    assert(s->qcow_version >= 3);



    if (s->incompatible_features & QCOW2_INCOMPAT_DIRTY) {

        return 0; /* already dirty */

    }



    val = cpu_to_be64(s->incompatible_features | QCOW2_INCOMPAT_DIRTY);

    ret = bdrv_pwrite(bs->file, offsetof(QCowHeader, incompatible_features),

                      &val, sizeof(val));

    if (ret < 0) {

        return ret;

    }

    ret = bdrv_flush(bs->file);

    if (ret < 0) {

        return ret;

    }



    /* Only treat image as dirty if the header was updated successfully */

    s->incompatible_features |= QCOW2_INCOMPAT_DIRTY;

    return 0;

}

static void fill_yuv_image(AVFrame *pict, int frame_index,

                           int width, int height)

{

    int x, y, i, ret;



    /* when we pass a frame to the encoder, it may keep a reference to it

     * internally;

     * make sure we do not overwrite it here

     */

    ret = av_frame_make_writable(pict);

    if (ret < 0)

        exit(1);



    i = frame_index;



    /* Y */

    for (y = 0; y < height; y++)

        for (x = 0; x < width; x++)

            pict->data[0][y * pict->linesize[0] + x] = x + y + i * 3;



    /* Cb and Cr */

    for (y = 0; y < height / 2; y++) {

        for (x = 0; x < width / 2; x++) {

            pict->data[1][y * pict->linesize[1] + x] = 128 + y + i * 2;

            pict->data[2][y * pict->linesize[2] + x] = 64 + x + i * 5;

        }

    }

}

void *qemu_ram_mmap(int fd, size_t size, size_t align, bool shared)

{

    /*

     * Note: this always allocates at least one extra page of virtual address

     * space, even if size is already aligned.

     */

    size_t total = size + align;

#if defined(__powerpc64__) && defined(__linux__)

    /* On ppc64 mappings in the same segment (aka slice) must share the same

     * page size. Since we will be re-allocating part of this segment

     * from the supplied fd, we should make sure to use the same page size,

     * unless we are using the system page size, in which case anonymous memory

     * is OK. Use align as a hint for the page size.

     * In this case, set MAP_NORESERVE to avoid allocating backing store memory.

     */

    int anonfd = fd == -1 || qemu_fd_getpagesize(fd) == getpagesize() ? -1 : fd;

    int flags = anonfd == -1 ? MAP_ANONYMOUS : MAP_NORESERVE;

    void *ptr = mmap(0, total, PROT_NONE, flags | MAP_PRIVATE, anonfd, 0);

#else

    void *ptr = mmap(0, total, PROT_NONE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);

#endif

    size_t offset = QEMU_ALIGN_UP((uintptr_t)ptr, align) - (uintptr_t)ptr;

    void *ptr1;



    if (ptr == MAP_FAILED) {

        return MAP_FAILED;

    }



    /* Make sure align is a power of 2 */

    assert(!(align & (align - 1)));

    /* Always align to host page size */

    assert(align >= getpagesize());



    ptr1 = mmap(ptr + offset, size, PROT_READ | PROT_WRITE,

                MAP_FIXED |

                (fd == -1 ? MAP_ANONYMOUS : 0) |

                (shared ? MAP_SHARED : MAP_PRIVATE),

                fd, 0);

    if (ptr1 == MAP_FAILED) {

        munmap(ptr, total);

        return MAP_FAILED;

    }



    ptr += offset;

    total -= offset;



    if (offset > 0) {

        munmap(ptr - offset, offset);

    }



    /*

     * Leave a single PROT_NONE page allocated after the RAM block, to serve as

     * a guard page guarding against potential buffer overflows.

     */

    if (total > size + getpagesize()) {

        munmap(ptr + size + getpagesize(), total - size - getpagesize());

    }



    return ptr;

}

static void code_gen_alloc(unsigned long tb_size)

{

#ifdef USE_STATIC_CODE_GEN_BUFFER

    code_gen_buffer = static_code_gen_buffer;

    code_gen_buffer_size = DEFAULT_CODE_GEN_BUFFER_SIZE;

    map_exec(code_gen_buffer, code_gen_buffer_size);

#else

    code_gen_buffer_size = tb_size;

    if (code_gen_buffer_size == 0) {

#if defined(CONFIG_USER_ONLY)

        /* in user mode, phys_ram_size is not meaningful */

        code_gen_buffer_size = DEFAULT_CODE_GEN_BUFFER_SIZE;

#else

        /* XXX: needs adjustments */

        code_gen_buffer_size = (unsigned long)(ram_size / 4);

#endif

    }

    if (code_gen_buffer_size < MIN_CODE_GEN_BUFFER_SIZE)

        code_gen_buffer_size = MIN_CODE_GEN_BUFFER_SIZE;

    /* The code gen buffer location may have constraints depending on

       the host cpu and OS */

#if defined(__linux__) 

    {

        int flags;

        void *start = NULL;



        flags = MAP_PRIVATE | MAP_ANONYMOUS;

#if defined(__x86_64__)

        flags |= MAP_32BIT;

        /* Cannot map more than that */

        if (code_gen_buffer_size > (800 * 1024 * 1024))

            code_gen_buffer_size = (800 * 1024 * 1024);

#elif defined(__sparc_v9__)

        // Map the buffer below 2G, so we can use direct calls and branches

        flags |= MAP_FIXED;

        start = (void *) 0x60000000UL;

        if (code_gen_buffer_size > (512 * 1024 * 1024))

            code_gen_buffer_size = (512 * 1024 * 1024);

#elif defined(__arm__)

        /* Map the buffer below 32M, so we can use direct calls and branches */

        flags |= MAP_FIXED;

        start = (void *) 0x01000000UL;

        if (code_gen_buffer_size > 16 * 1024 * 1024)

            code_gen_buffer_size = 16 * 1024 * 1024;

#elif defined(__s390x__)

        /* Map the buffer so that we can use direct calls and branches.  */

        /* We have a +- 4GB range on the branches; leave some slop.  */

        if (code_gen_buffer_size > (3ul * 1024 * 1024 * 1024)) {

            code_gen_buffer_size = 3ul * 1024 * 1024 * 1024;

        }

        start = (void *)0x90000000UL;

#endif

        code_gen_buffer = mmap(start, code_gen_buffer_size,

                               PROT_WRITE | PROT_READ | PROT_EXEC,

                               flags, -1, 0);

        if (code_gen_buffer == MAP_FAILED) {

            fprintf(stderr, "Could not allocate dynamic translator buffer\n");

            exit(1);

        }

    }

#elif defined(__FreeBSD__) || defined(__FreeBSD_kernel__) \

    || defined(__DragonFly__) || defined(__OpenBSD__)

    {

        int flags;

        void *addr = NULL;

        flags = MAP_PRIVATE | MAP_ANONYMOUS;

#if defined(__x86_64__)

        /* FreeBSD doesn't have MAP_32BIT, use MAP_FIXED and assume

         * 0x40000000 is free */

        flags |= MAP_FIXED;

        addr = (void *)0x40000000;

        /* Cannot map more than that */

        if (code_gen_buffer_size > (800 * 1024 * 1024))

            code_gen_buffer_size = (800 * 1024 * 1024);

#elif defined(__sparc_v9__)

        // Map the buffer below 2G, so we can use direct calls and branches

        flags |= MAP_FIXED;

        addr = (void *) 0x60000000UL;

        if (code_gen_buffer_size > (512 * 1024 * 1024)) {

            code_gen_buffer_size = (512 * 1024 * 1024);

        }

#endif

        code_gen_buffer = mmap(addr, code_gen_buffer_size,

                               PROT_WRITE | PROT_READ | PROT_EXEC, 

                               flags, -1, 0);

        if (code_gen_buffer == MAP_FAILED) {

            fprintf(stderr, "Could not allocate dynamic translator buffer\n");

            exit(1);

        }

    }

#else

    code_gen_buffer = qemu_malloc(code_gen_buffer_size);

    map_exec(code_gen_buffer, code_gen_buffer_size);

#endif

#endif /* !USE_STATIC_CODE_GEN_BUFFER */

    map_exec(code_gen_prologue, sizeof(code_gen_prologue));

    code_gen_buffer_max_size = code_gen_buffer_size - 

        (TCG_MAX_OP_SIZE * OPC_MAX_SIZE);

    code_gen_max_blocks = code_gen_buffer_size / CODE_GEN_AVG_BLOCK_SIZE;

    tbs = qemu_malloc(code_gen_max_blocks * sizeof(TranslationBlock));

}

static void virtqueue_map_iovec(VirtIODevice *vdev, struct iovec *sg,

                                hwaddr *addr, unsigned int *num_sg,

                                unsigned int max_size, int is_write)

{

    unsigned int i;

    hwaddr len;



    /* Note: this function MUST validate input, some callers

     * are passing in num_sg values received over the network.

     */

    /* TODO: teach all callers that this can fail, and return failure instead

     * of asserting here.

     * When we do, we might be able to re-enable NDEBUG below.

     */

#ifdef NDEBUG

#error building with NDEBUG is not supported

#endif

    assert(*num_sg <= max_size);



    for (i = 0; i < *num_sg; i++) {

        len = sg[i].iov_len;

        sg[i].iov_base = dma_memory_map(vdev->dma_as,

                                        addr[i], &len, is_write ?

                                        DMA_DIRECTION_FROM_DEVICE :

                                        DMA_DIRECTION_TO_DEVICE);

        if (!sg[i].iov_base) {

            error_report("virtio: error trying to map MMIO memory");

            exit(1);

        }

        if (len != sg[i].iov_len) {

            error_report("virtio: unexpected memory split");

            exit(1);

        }

    }

}

static void avc_biwgt_16width_msa(uint8_t *src, int32_t src_stride,

                                  uint8_t *dst, int32_t dst_stride,

                                  int32_t height, int32_t log2_denom,

                                  int32_t src_weight, int32_t dst_weight,

                                  int32_t offset_in)

{

    uint8_t cnt;

    v16i8 src_wgt, dst_wgt, wgt;

    v16i8 src0, src1, src2, src3;

    v16i8 dst0, dst1, dst2, dst3;

    v16i8 vec0, vec1, vec2, vec3, vec4, vec5, vec6, vec7;

    v8i16 temp0, temp1, temp2, temp3, temp4, temp5, temp6, temp7;

    v8i16 denom, offset, add_val;

    int32_t val = 128 * (src_weight + dst_weight);



    offset_in = ((offset_in + 1) | 1) << log2_denom;



    src_wgt = __msa_fill_b(src_weight);

    dst_wgt = __msa_fill_b(dst_weight);

    offset = __msa_fill_h(offset_in);

    denom = __msa_fill_h(log2_denom + 1);

    add_val = __msa_fill_h(val);

    offset += add_val;



    wgt = __msa_ilvev_b(dst_wgt, src_wgt);



    for (cnt = height / 4; cnt--;) {

        LOAD_4VECS_SB(src, src_stride, src0, src1, src2, src3);

        src += (4 * src_stride);



        LOAD_4VECS_SB(dst, dst_stride, dst0, dst1, dst2, dst3);



        XORI_B_4VECS_SB(src0, src1, src2, src3, src0, src1, src2, src3, 128);



        XORI_B_4VECS_SB(dst0, dst1, dst2, dst3, dst0, dst1, dst2, dst3, 128);



        ILV_B_LRLR_SB(src0, dst0, src1, dst1, vec1, vec0, vec3, vec2);

        ILV_B_LRLR_SB(src2, dst2, src3, dst3, vec5, vec4, vec7, vec6);



        temp0 = __msa_dpadd_s_h(offset, wgt, vec0);

        temp1 = __msa_dpadd_s_h(offset, wgt, vec1);

        temp2 = __msa_dpadd_s_h(offset, wgt, vec2);

        temp3 = __msa_dpadd_s_h(offset, wgt, vec3);

        temp4 = __msa_dpadd_s_h(offset, wgt, vec4);

        temp5 = __msa_dpadd_s_h(offset, wgt, vec5);

        temp6 = __msa_dpadd_s_h(offset, wgt, vec6);

        temp7 = __msa_dpadd_s_h(offset, wgt, vec7);



        SRA_4VECS(temp0, temp1, temp2, temp3,

                  temp0, temp1, temp2, temp3, denom);

        SRA_4VECS(temp4, temp5, temp6, temp7,

                  temp4, temp5, temp6, temp7, denom);



        temp0 = CLIP_UNSIGNED_CHAR_H(temp0);

        temp1 = CLIP_UNSIGNED_CHAR_H(temp1);

        temp2 = CLIP_UNSIGNED_CHAR_H(temp2);

        temp3 = CLIP_UNSIGNED_CHAR_H(temp3);

        temp4 = CLIP_UNSIGNED_CHAR_H(temp4);

        temp5 = CLIP_UNSIGNED_CHAR_H(temp5);

        temp6 = CLIP_UNSIGNED_CHAR_H(temp6);

        temp7 = CLIP_UNSIGNED_CHAR_H(temp7);



        PCKEV_B_4VECS_SB(temp1, temp3, temp5, temp7, temp0, temp2, temp4, temp6,

                         dst0, dst1, dst2, dst3);



        STORE_4VECS_SB(dst, dst_stride, dst0, dst1, dst2, dst3);

        dst += 4 * dst_stride;

    }

}

static void avc_biwgt_4x2_msa(uint8_t *src,

                              int32_t src_stride,

                              uint8_t *dst,

                              int32_t dst_stride,

                              int32_t log2_denom,

                              int32_t src_weight,

                              int32_t dst_weight,

                              int32_t offset_in)

{

    uint32_t load0, load1, out0, out1;

    v16i8 src_wgt, dst_wgt, wgt;

    v16i8 src0, src1, dst0, dst1;

    v8i16 temp0, temp1, denom, offset, add_val;

    int32_t val = 128 * (src_weight + dst_weight);



    offset_in = ((offset_in + 1) | 1) << log2_denom;



    src_wgt = __msa_fill_b(src_weight);

    dst_wgt = __msa_fill_b(dst_weight);

    offset = __msa_fill_h(offset_in);

    denom = __msa_fill_h(log2_denom + 1);

    add_val = __msa_fill_h(val);

    offset += add_val;



    wgt = __msa_ilvev_b(dst_wgt, src_wgt);



    load0 = LOAD_WORD(src);

    src += src_stride;

    load1 = LOAD_WORD(src);



    src0 = (v16i8) __msa_fill_w(load0);

    src1 = (v16i8) __msa_fill_w(load1);



    load0 = LOAD_WORD(dst);

    load1 = LOAD_WORD(dst + dst_stride);



    dst0 = (v16i8) __msa_fill_w(load0);

    dst1 = (v16i8) __msa_fill_w(load1);



    XORI_B_4VECS_SB(src0, src1, dst0, dst1, src0, src1, dst0, dst1, 128);



    ILVR_B_2VECS_SH(src0, src1, dst0, dst1, temp0, temp1);



    temp0 = __msa_dpadd_s_h(offset, wgt, (v16i8) temp0);

    temp1 = __msa_dpadd_s_h(offset, wgt, (v16i8) temp1);



    temp0 >>= denom;

    temp1 >>= denom;



    temp0 = CLIP_UNSIGNED_CHAR_H(temp0);

    temp1 = CLIP_UNSIGNED_CHAR_H(temp1);



    dst0 = __msa_pckev_b((v16i8) temp0, (v16i8) temp0);

    dst1 = __msa_pckev_b((v16i8) temp1, (v16i8) temp1);



    out0 = __msa_copy_u_w((v4i32) dst0, 0);

    out1 = __msa_copy_u_w((v4i32) dst1, 0);



    STORE_WORD(dst, out0);

    dst += dst_stride;

    STORE_WORD(dst, out1);

}

static void avc_wgt_4x4multiple_msa(uint8_t *data,

                                    int32_t stride,

                                    int32_t height,

                                    int32_t log2_denom,

                                    int32_t src_weight,

                                    int32_t offset_in)

{

    uint8_t cnt;

    uint32_t data0, data1, data2, data3;

    v16u8 zero = { 0 };

    v16u8 src0, src1, src2, src3;

    v8u16 temp0, temp1, temp2, temp3;

    v8i16 wgt, denom, offset;



    offset_in <<= (log2_denom);



    if (log2_denom) {

        offset_in += (1 << (log2_denom - 1));

    }



    wgt = __msa_fill_h(src_weight);

    offset = __msa_fill_h(offset_in);

    denom = __msa_fill_h(log2_denom);



    for (cnt = height / 4; cnt--;) {

        LOAD_4WORDS_WITH_STRIDE(data, stride, data0, data1, data2, data3);



        src0 = (v16u8) __msa_fill_w(data0);

        src1 = (v16u8) __msa_fill_w(data1);

        src2 = (v16u8) __msa_fill_w(data2);

        src3 = (v16u8) __msa_fill_w(data3);



        ILVR_B_4VECS_UH(src0, src1, src2, src3, zero, zero, zero, zero,

                        temp0, temp1, temp2, temp3);



        temp0 *= wgt;

        temp1 *= wgt;

        temp2 *= wgt;

        temp3 *= wgt;



        ADDS_S_H_4VECS_UH(temp0, offset, temp1, offset,

                          temp2, offset, temp3, offset,

                          temp0, temp1, temp2, temp3);



        MAXI_S_H_4VECS_UH(temp0, temp1, temp2, temp3, 0);



        SRL_H_4VECS_UH(temp0, temp1, temp2, temp3,

                       temp0, temp1, temp2, temp3, denom);



        SAT_U_H_4VECS_UH(temp0, temp1, temp2, temp3, 7);



        PCKEV_B_STORE_4_BYTES_4(temp0, temp1, temp2, temp3, data, stride);

        data += (4 * stride);

    }

}

static void avc_wgt_16width_msa(uint8_t *data,

                                int32_t stride,

                                int32_t height,

                                int32_t log2_denom,

                                int32_t src_weight,

                                int32_t offset_in)

{

    uint8_t cnt;

    v16u8 zero = { 0 };

    v16u8 src0, src1, src2, src3;

    v16u8 dst0, dst1, dst2, dst3;

    v8u16 src0_l, src1_l, src2_l, src3_l;

    v8u16 src0_r, src1_r, src2_r, src3_r;

    v8u16 temp0, temp1, temp2, temp3, temp4, temp5, temp6, temp7;

    v8u16 wgt, denom, offset;



    offset_in <<= (log2_denom);



    if (log2_denom) {

        offset_in += (1 << (log2_denom - 1));

    }



    wgt = (v8u16) __msa_fill_h(src_weight);

    offset = (v8u16) __msa_fill_h(offset_in);

    denom = (v8u16) __msa_fill_h(log2_denom);



    for (cnt = height / 4; cnt--;) {

        LOAD_4VECS_UB(data, stride, src0, src1, src2, src3);



        ILV_B_LRLR_UH(src0, zero, src1, zero, src0_l, src0_r, src1_l, src1_r);

        ILV_B_LRLR_UH(src2, zero, src3, zero, src2_l, src2_r, src3_l, src3_r);



        temp0 = wgt * src0_r;

        temp1 = wgt * src0_l;

        temp2 = wgt * src1_r;

        temp3 = wgt * src1_l;

        temp4 = wgt * src2_r;

        temp5 = wgt * src2_l;

        temp6 = wgt * src3_r;

        temp7 = wgt * src3_l;



        ADDS_S_H_4VECS_UH(temp0, offset, temp1, offset,

                          temp2, offset, temp3, offset,

                          temp0, temp1, temp2, temp3);



        ADDS_S_H_4VECS_UH(temp4, offset, temp5, offset,

                          temp6, offset, temp7, offset,

                          temp4, temp5, temp6, temp7);



        MAXI_S_H_4VECS_UH(temp0, temp1, temp2, temp3, 0);

        MAXI_S_H_4VECS_UH(temp4, temp5, temp6, temp7, 0);



        SRL_H_4VECS_UH(temp0, temp1, temp2, temp3,

                       temp0, temp1, temp2, temp3, denom);



        SRL_H_4VECS_UH(temp4, temp5, temp6, temp7,

                       temp4, temp5, temp6, temp7, denom);



        SAT_U_H_4VECS_UH(temp0, temp1, temp2, temp3, 7);

        SAT_U_H_4VECS_UH(temp4, temp5, temp6, temp7, 7);



        PCKEV_B_4VECS_UB(temp1, temp3, temp5, temp7, temp0, temp2, temp4, temp6,

                         dst0, dst1, dst2, dst3);



        STORE_4VECS_UB(data, stride, dst0, dst1, dst2, dst3);

        data += 4 * stride;

    }

}

static void tcg_out_st (TCGContext *s, TCGType type, int arg, int arg1,

                        tcg_target_long arg2)

{

    if (type == TCG_TYPE_I32)

        tcg_out_ldst (s, arg, arg1, arg2, STW, STWX);

    else

        tcg_out_ldst (s, arg, arg1, arg2, STD, STDX);

}

static inline void tcg_out_st(TCGContext *s, TCGType type, TCGReg arg,

                              TCGReg arg1, intptr_t arg2)

{

    int opi, opx;



    assert(TCG_TARGET_REG_BITS == 64 || type == TCG_TYPE_I32);

    if (type == TCG_TYPE_I32) {

        opi = STW, opx = STWX;

    } else {

        opi = STD, opx = STDX;

    }

    tcg_out_mem_long(s, opi, opx, arg, arg1, arg2);

}

static void tcg_out_ri64(TCGContext *s, int const_arg, TCGArg arg)

{

    if (const_arg) {

        assert(const_arg == 1);

        tcg_out8(s, TCG_CONST);

        tcg_out64(s, arg);

    } else {

        tcg_out_r(s, arg);

    }

}

static void tcg_out_movi(TCGContext *s, TCGType type,

                         TCGReg t0, tcg_target_long arg)

{

    uint8_t *old_code_ptr = s->code_ptr;

    uint32_t arg32 = arg;

    if (type == TCG_TYPE_I32 || arg == arg32) {

        tcg_out_op_t(s, INDEX_op_movi_i32);

        tcg_out_r(s, t0);

        tcg_out32(s, arg32);

    } else {

        assert(type == TCG_TYPE_I64);

#if TCG_TARGET_REG_BITS == 64

        tcg_out_op_t(s, INDEX_op_movi_i64);

        tcg_out_r(s, t0);

        tcg_out64(s, arg);

#else

        TODO();

#endif

    }

    old_code_ptr[1] = s->code_ptr - old_code_ptr;

}

void do_delvm(Monitor *mon, const QDict *qdict)

{

    DriveInfo *dinfo;

    BlockDriverState *bs, *bs1;

    int ret;

    const char *name = qdict_get_str(qdict, "name");



    bs = get_bs_snapshots();

    if (!bs) {

        monitor_printf(mon, "No block device supports snapshots\n");

        return;

    }



    QTAILQ_FOREACH(dinfo, &drives, next) {

        bs1 = dinfo->bdrv;

        if (bdrv_has_snapshot(bs1)) {

            ret = bdrv_snapshot_delete(bs1, name);

            if (ret < 0) {

                if (ret == -ENOTSUP)

                    monitor_printf(mon,

                                   "Snapshots not supported on device '%s'\n",

                                   bdrv_get_device_name(bs1));

                else

                    monitor_printf(mon, "Error %d while deleting snapshot on "

                                   "'%s'\n", ret, bdrv_get_device_name(bs1));

            }

        }

    }

}

static int del_existing_snapshots(Monitor *mon, const char *name)

{

    BlockDriverState *bs;

    QEMUSnapshotInfo sn1, *snapshot = &sn1;

    int ret;



    bs = NULL;

    while ((bs = bdrv_next(bs))) {

        if (bdrv_can_snapshot(bs) &&

            bdrv_snapshot_find(bs, snapshot, name) >= 0)

        {

            ret = bdrv_snapshot_delete(bs, name);

            if (ret < 0) {

                monitor_printf(mon,

                               "Error while deleting snapshot on '%s'\n",

                               bdrv_get_device_name(bs));

                return -1;

            }

        }

    }



    return 0;

}

void hmp_delvm(Monitor *mon, const QDict *qdict)

{

    BlockDriverState *bs;

    Error *err;

    const char *name = qdict_get_str(qdict, "name");



    if (!find_vmstate_bs()) {

        monitor_printf(mon, "No block device supports snapshots\n");

        return;

    }



    if (bdrv_all_delete_snapshot(name, &bs, &err) < 0) {

        monitor_printf(mon,

                       "Error while deleting snapshot on device '%s': %s\n",

                       bdrv_get_device_name(bs), error_get_pretty(err));

        error_free(err);

    }

}

void do_commit(Monitor *mon, const QDict *qdict)

{

    const char *device = qdict_get_str(qdict, "device");

    BlockDriverState *bs;



    if (!strcmp(device, "all")) {

        bdrv_commit_all();

    } else {

        bs = bdrv_find(device);

        if (!bs) {

            qerror_report(QERR_DEVICE_NOT_FOUND, device);

            return;

        }

        bdrv_commit(bs);

    }

}

void qmp_getfd(const char *fdname, Error **errp)

{

    mon_fd_t *monfd;

    int fd;



    fd = qemu_chr_fe_get_msgfd(cur_mon->chr);

    if (fd == -1) {

        error_set(errp, QERR_FD_NOT_SUPPLIED);

        return;

    }



    if (qemu_isdigit(fdname[0])) {


        error_set(errp, QERR_INVALID_PARAMETER_VALUE, "fdname",

                  "a name not starting with a digit");

        return;

    }



    QLIST_FOREACH(monfd, &cur_mon->fds, next) {

        if (strcmp(monfd->name, fdname) != 0) {

            continue;

        }



        close(monfd->fd);

        monfd->fd = fd;

        return;

    }



    monfd = g_malloc0(sizeof(mon_fd_t));

    monfd->name = g_strdup(fdname);

    monfd->fd = fd;



    QLIST_INSERT_HEAD(&cur_mon->fds, monfd, next);

}

void object_property_add_link(Object *obj, const char *name,

                              const char *type, Object **child,

                              void (*check)(Object *, const char *,

                                            Object *, Error **),

                              ObjectPropertyLinkFlags flags,

                              Error **errp)

{

    Error *local_err = NULL;

    LinkProperty *prop = g_malloc(sizeof(*prop));

    gchar *full_type;

    ObjectProperty *op;



    prop->child = child;

    prop->check = check;

    prop->flags = flags;



    full_type = g_strdup_printf("link<%s>", type);



    op = object_property_add(obj, name, full_type,

                             object_get_link_property,

                             check ? object_set_link_property : NULL,

                             object_release_link_property,

                             prop,

                             &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        g_free(prop);

        goto out;

    }



    op->resolve = object_resolve_link_property;



out:

    g_free(full_type);

}

void object_property_add_child(Object *obj, const char *name,

                               Object *child, Error **errp)

{

    Error *local_err = NULL;

    gchar *type;



    type = g_strdup_printf("child<%s>", object_get_typename(OBJECT(child)));



    object_property_add(obj, name, type, object_get_child_property, NULL,

                        object_finalize_child_property, child, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        goto out;

    }

    object_ref(child);

    g_assert(child->parent == NULL);

    child->parent = obj;



out:

    g_free(type);

}

static DevicePropertyInfo *make_device_property_info(ObjectClass *klass,

                                                     const char *name,

                                                     const char *default_type,

                                                     const char *description)

{

    DevicePropertyInfo *info;

    Property *prop;



    do {

        for (prop = DEVICE_CLASS(klass)->props; prop && prop->name; prop++) {

            if (strcmp(name, prop->name) != 0) {

                continue;

            }



            /*

             * TODO Properties without a parser are just for dirty hacks.

             * qdev_prop_ptr is the only such PropertyInfo.  It's marked

             * for removal.  This conditional should be removed along with

             * it.

             */

            if (!prop->info->set) {

                return NULL;           /* no way to set it, don't show */

            }



            info = g_malloc0(sizeof(*info));

            info->name = g_strdup(prop->name);

            info->type = g_strdup(prop->info->name);

            info->has_description = !!prop->info->description;

            info->description = g_strdup(prop->info->description);

            return info;

        }

        klass = object_class_get_parent(klass);

    } while (klass != object_class_by_name(TYPE_DEVICE));



    /* Not a qdev property, use the default type */

    info = g_malloc0(sizeof(*info));

    info->name = g_strdup(name);

    info->type = g_strdup(default_type);

    info->has_description = !!description;

    info->description = g_strdup(description);



    return info;

}

static void z2_init(MachineState *machine)

{

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    const char *initrd_filename = machine->initrd_filename;

    MemoryRegion *address_space_mem = get_system_memory();

    uint32_t sector_len = 0x10000;

    PXA2xxState *mpu;

    DriveInfo *dinfo;

    int be;

    void *z2_lcd;

    I2CBus *bus;

    DeviceState *wm;



    if (!cpu_model) {

        cpu_model = "pxa270-c5";

    }



    /* Setup CPU & memory */

    mpu = pxa270_init(address_space_mem, z2_binfo.ram_size, cpu_model);



#ifdef TARGET_WORDS_BIGENDIAN

    be = 1;

#else

    be = 0;

#endif

    dinfo = drive_get(IF_PFLASH, 0, 0);

    if (!dinfo && !qtest_enabled()) {

        fprintf(stderr, "Flash image must be given with the "

                "'pflash' parameter\n");

        exit(1);

    }



    if (!pflash_cfi01_register(Z2_FLASH_BASE,

                               NULL, "z2.flash0", Z2_FLASH_SIZE,

                               dinfo ? dinfo->bdrv : NULL, sector_len,

                               Z2_FLASH_SIZE / sector_len, 4, 0, 0, 0, 0,

                               be)) {

        fprintf(stderr, "qemu: Error registering flash memory.\n");

        exit(1);

    }



    /* setup keypad */

    pxa27x_register_keypad(mpu->kp, map, 0x100);



    /* MMC/SD host */

    pxa2xx_mmci_handlers(mpu->mmc,

        NULL,

        qdev_get_gpio_in(mpu->gpio, Z2_GPIO_SD_DETECT));



    type_register_static(&zipit_lcd_info);

    type_register_static(&aer915_info);

    z2_lcd = ssi_create_slave(mpu->ssp[1], "zipit-lcd");

    bus = pxa2xx_i2c_bus(mpu->i2c[0]);

    i2c_create_slave(bus, TYPE_AER915, 0x55);

    wm = i2c_create_slave(bus, "wm8750", 0x1b);

    mpu->i2s->opaque = wm;

    mpu->i2s->codec_out = wm8750_dac_dat;

    mpu->i2s->codec_in = wm8750_adc_dat;

    wm8750_data_req_set(wm, mpu->i2s->data_req, mpu->i2s);



    qdev_connect_gpio_out(mpu->gpio, Z2_GPIO_LCD_CS,

        qemu_allocate_irqs(z2_lcd_cs, z2_lcd, 1)[0]);



    z2_binfo.kernel_filename = kernel_filename;

    z2_binfo.kernel_cmdline = kernel_cmdline;

    z2_binfo.initrd_filename = initrd_filename;

    z2_binfo.board_id = 0x6dd;

    arm_load_kernel(mpu->cpu, &z2_binfo);

}

static void an5206_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    M68kCPU *cpu;

    CPUM68KState *env;

    int kernel_size;

    uint64_t elf_entry;

    hwaddr entry;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    MemoryRegion *sram = g_new(MemoryRegion, 1);



    if (!cpu_model) {

        cpu_model = "m5206";

    }

    cpu = M68K_CPU(cpu_generic_init(TYPE_M68K_CPU, cpu_model));

    if (!cpu) {

        error_report("Unable to find m68k CPU definition");

        exit(1);

    }

    env = &cpu->env;



    /* Initialize CPU registers.  */

    env->vbr = 0;

    /* TODO: allow changing MBAR and RAMBAR.  */

    env->mbar = AN5206_MBAR_ADDR | 1;

    env->rambar0 = AN5206_RAMBAR_ADDR | 1;



    /* DRAM at address zero */

    memory_region_allocate_system_memory(ram, NULL, "an5206.ram", ram_size);

    memory_region_add_subregion(address_space_mem, 0, ram);



    /* Internal SRAM.  */

    memory_region_init_ram(sram, NULL, "an5206.sram", 512, &error_fatal);

    memory_region_add_subregion(address_space_mem, AN5206_RAMBAR_ADDR, sram);



    mcf5206_init(address_space_mem, AN5206_MBAR_ADDR, cpu);



    /* Load kernel.  */

    if (!kernel_filename) {

        if (qtest_enabled()) {

            return;

        }

        fprintf(stderr, "Kernel image must be specified\n");

        exit(1);

    }



    kernel_size = load_elf(kernel_filename, NULL, NULL, &elf_entry,

                           NULL, NULL, 1, EM_68K, 0, 0);

    entry = elf_entry;

    if (kernel_size < 0) {

        kernel_size = load_uimage(kernel_filename, &entry, NULL, NULL,

                                  NULL, NULL);

    }

    if (kernel_size < 0) {

        kernel_size = load_image_targphys(kernel_filename, KERNEL_LOAD_ADDR,

                                          ram_size - KERNEL_LOAD_ADDR);

        entry = KERNEL_LOAD_ADDR;

    }

    if (kernel_size < 0) {

        fprintf(stderr, "qemu: could not load kernel '%s'\n", kernel_filename);

        exit(1);

    }



    env->pc = entry;

}

