    return buf - bufstart;

}

static int decode_0(AVCodecContext *avctx, uint8_t code, uint8_t *pkt)

{

    PAFVideoDecContext *c = avctx->priv_data;

    uint32_t opcode_size, offset;

    uint8_t *dst, *dend, mask = 0, color = 0, a, b, p;

    const uint8_t *src, *send, *opcodes;

    int  i, j, x = 0;



    i = bytestream2_get_byte(&c->gb);

    if (i) {

        if (code & 0x10) {

            int align;



            align = bytestream2_tell(&c->gb) & 3;

            if (align)

                bytestream2_skip(&c->gb, 4 - align);

        }

        do {

            a      = bytestream2_get_byte(&c->gb);

            b      = bytestream2_get_byte(&c->gb);

            p      = (a & 0xC0) >> 6;

            dst    = c->frame[p] + get_video_page_offset(avctx, a, b);

            dend   = c->frame[p] + c->frame_size;

            offset = (b & 0x7F) * 2;

            j      = bytestream2_get_le16(&c->gb) + offset;



            do {

                offset++;

                if (dst + 3 * avctx->width + 4 > dend)

                    return AVERROR_INVALIDDATA;

                copy4h(avctx, dst);

                if ((offset & 0x3F) == 0)

                    dst += avctx->width * 3;

                dst += 4;

            } while (offset < j);

        } while (--i);

    }



    dst = c->frame[c->current_frame];

    do {

        a    = bytestream2_get_byte(&c->gb);

        b    = bytestream2_get_byte(&c->gb);

        p    = (a & 0xC0) >> 6;

        src  = c->frame[p] + get_video_page_offset(avctx, a, b);

        send = c->frame[p] + c->frame_size;

        if (src + 3 * avctx->width + 4 > send)

            return AVERROR_INVALIDDATA;

        copy_block4(dst, src, avctx->width, avctx->width, 4);

        i++;

        if ((i & 0x3F) == 0)

            dst += avctx->width * 3;

        dst += 4;

    } while (i < c->video_size / 16);



    opcode_size = bytestream2_get_le16(&c->gb);

    bytestream2_skip(&c->gb, 2);



    if (bytestream2_get_bytes_left(&c->gb) < opcode_size)

        return AVERROR_INVALIDDATA;



    opcodes = pkt + bytestream2_tell(&c->gb);

    bytestream2_skipu(&c->gb, opcode_size);



    dst = c->frame[c->current_frame];



    for (i = 0; i < avctx->height; i += 4, dst += avctx->width * 3) {

        for (j = 0; j < avctx->width; j += 4, dst += 4) {

            int opcode, k = 0;



            if (x > opcode_size)

                return AVERROR_INVALIDDATA;

            if (j & 4) {

                opcode = opcodes[x] & 15;

                x++;

            } else {

                opcode = opcodes[x] >> 4;

            }



            while (block_sequences[opcode][k]) {



                offset = avctx->width * 2;

                code   = block_sequences[opcode][k++];



                switch (code) {

                case 2:

                    offset = 0;

                case 3:

                    color  = bytestream2_get_byte(&c->gb);

                case 4:

                    mask   = bytestream2_get_byte(&c->gb);

                    copy_color_mask(avctx, mask, dst + offset, color);

                    break;

                case 5:

                    offset = 0;

                case 6:

                    a    = bytestream2_get_byte(&c->gb);

                    b    = bytestream2_get_byte(&c->gb);

                    p    = (a & 0xC0) >> 6;

                    src  = c->frame[p] + get_video_page_offset(avctx, a, b);

                    send = c->frame[p] + c->frame_size;

                case 7:

                    if (src + offset + avctx->width + 4 > send)

                        return AVERROR_INVALIDDATA;

                    mask = bytestream2_get_byte(&c->gb);

                    copy_src_mask(avctx, mask, dst + offset, src + offset);

                    break;

                }

            }

        }

    }



    return 0;

}

static int old_codec47(SANMVideoContext *ctx, int top,
                       int left, int width, int height)
{
    int i, j, seq, compr, new_rot, tbl_pos, skip;
    int stride     = ctx->pitch;
    uint8_t *dst   = ((uint8_t*)ctx->frm0) + left + top * stride;
    uint8_t *prev1 = (uint8_t*)ctx->frm1;
    uint8_t *prev2 = (uint8_t*)ctx->frm2;
    uint32_t decoded_size;
    tbl_pos = bytestream2_tell(&ctx->gb);
    seq     = bytestream2_get_le16(&ctx->gb);
    compr   = bytestream2_get_byte(&ctx->gb);
    new_rot = bytestream2_get_byte(&ctx->gb);
    skip    = bytestream2_get_byte(&ctx->gb);
    bytestream2_skip(&ctx->gb, 9);
    decoded_size = bytestream2_get_le32(&ctx->gb);
    bytestream2_skip(&ctx->gb, 8);
    if (skip & 1)
        bytestream2_skip(&ctx->gb, 0x8080);
    if (!seq) {
        ctx->prev_seq = -1;
        memset(prev1, 0, ctx->height * stride);
        memset(prev2, 0, ctx->height * stride);
    av_dlog(ctx->avctx, "compression %d\n", compr);
    switch (compr) {
    case 0:
        if (bytestream2_get_bytes_left(&ctx->gb) < width * height)
            return AVERROR_INVALIDDATA;
        for (j = 0; j < height; j++) {
            bytestream2_get_bufferu(&ctx->gb, dst, width);
            dst += stride;
        break;
    case 1:
        if (bytestream2_get_bytes_left(&ctx->gb) < ((width + 1) >> 1) * ((height + 1) >> 1))
            return AVERROR_INVALIDDATA;
        for (j = 0; j < height; j += 2) {
            for (i = 0; i < width; i += 2) {
                dst[i] = dst[i + 1] =
                dst[stride + i] = dst[stride + i + 1] = bytestream2_get_byteu(&ctx->gb);
            dst += stride * 2;
        break;
    case 2:
        if (seq == ctx->prev_seq + 1) {
            for (j = 0; j < height; j += 8) {
                for (i = 0; i < width; i += 8) {
                    if (process_block(ctx, dst + i, prev1 + i, prev2 + i, stride,
                                      tbl_pos + 8, 8))
                        return AVERROR_INVALIDDATA;
                dst   += stride * 8;
                prev1 += stride * 8;
                prev2 += stride * 8;
        break;
    case 3:
        memcpy(ctx->frm0, ctx->frm2, ctx->pitch * ctx->height);
        break;
    case 4:
        memcpy(ctx->frm0, ctx->frm1, ctx->pitch * ctx->height);
        break;
    case 5:
        if (rle_decode(ctx, dst, decoded_size))
            return AVERROR_INVALIDDATA;
        break;
    default:
        av_log(ctx->avctx, AV_LOG_ERROR,
               "subcodec 47 compression %d not implemented\n", compr);
        return AVERROR_PATCHWELCOME;
    if (seq == ctx->prev_seq + 1)
        ctx->rotate_code = new_rot;
    else
        ctx->rotate_code = 0;
    ctx->prev_seq = seq;
    return 0;

static void decode_interframe_v4a(AVCodecContext *avctx, uint8_t *src,

                                  uint32_t size)

{

    Hnm4VideoContext *hnm = avctx->priv_data;

    GetByteContext gb;

    uint32_t writeoffset = 0, offset;

    uint8_t tag, count, previous, delta;



    bytestream2_init(&gb, src, size);



    while (bytestream2_tell(&gb) < size) {

        count = bytestream2_peek_byte(&gb) & 0x3F;

        if (count == 0) {

            tag = bytestream2_get_byte(&gb) & 0xC0;

            tag = tag >> 6;

            if (tag == 0) {

                writeoffset += bytestream2_get_byte(&gb);

            } else if (tag == 1) {

                if (writeoffset + hnm->width >= hnm->width * hnm->height) {

                    av_log(avctx, AV_LOG_ERROR, "writeoffset out of bounds\n");

                    break;

                }

                hnm->current[writeoffset]              = bytestream2_get_byte(&gb);

                hnm->current[writeoffset + hnm->width] = bytestream2_get_byte(&gb);

                writeoffset++;

            } else if (tag == 2) {

                writeoffset += hnm->width;

            } else if (tag == 3) {

                break;

            }

            if (writeoffset > hnm->width * hnm->height) {

                av_log(avctx, AV_LOG_ERROR, "writeoffset out of bounds\n");

                break;

            }

        } else {

            delta    = bytestream2_peek_byte(&gb) & 0x80;

            previous = bytestream2_peek_byte(&gb) & 0x40;

            bytestream2_skip(&gb, 1);



            offset  = writeoffset;

            offset += bytestream2_get_le16(&gb);



            if (delta)

                offset -= 0x10000;



            if (offset + hnm->width + count >= hnm->width * hnm->height) {

                av_log(avctx, AV_LOG_ERROR, "Attempting to read out of bounds\n");

                break;

            } else if (writeoffset + hnm->width + count >= hnm->width * hnm->height) {

                av_log(avctx, AV_LOG_ERROR, "Attempting to write out of bounds\n");

                break;

            }



            if (previous) {

                while (count > 0) {

                    hnm->current[writeoffset]              = hnm->previous[offset];

                    hnm->current[writeoffset + hnm->width] = hnm->previous[offset + hnm->width];

                    writeoffset++;

                    offset++;

                    count--;

                }

            } else {

                while (count > 0) {

                    hnm->current[writeoffset]              = hnm->current[offset];

                    hnm->current[writeoffset + hnm->width] = hnm->current[offset + hnm->width];

                    writeoffset++;

                    offset++;

                    count--;

                }

            }

        }

    }

}

static int decode_type1(GetByteContext *gb, PutByteContext *pb)

{

    unsigned opcode, len;

    int high = 0;

    int i, pos;



    while (bytestream2_get_bytes_left(gb) > 0) {

        GetByteContext gbc;



        while (bytestream2_get_bytes_left(gb) > 0) {

            while (bytestream2_get_bytes_left(gb) > 0) {

                opcode = bytestream2_get_byte(gb);

                high = opcode >= 0x20;

                if (high)

                    break;

                if (opcode)

                    break;

                opcode = bytestream2_get_byte(gb);

                if (opcode < 0xF8) {

                    opcode = opcode + 32;

                    break;

                }

                i = opcode - 0xF8;

                if (i) {

                    len = 256;

                    do {

                        len *= 2;

                        --i;

                    } while (i);

                } else {

                    len = 280;

                }

                do {

                    bytestream2_put_le32(pb, bytestream2_get_le32(gb));

                    bytestream2_put_le32(pb, bytestream2_get_le32(gb));

                    len -= 8;

                } while (len && bytestream2_get_bytes_left(gb) > 0);

            }



            if (!high) {

                do {

                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                    --opcode;

                } while (opcode && bytestream2_get_bytes_left(gb) > 0);



                while (bytestream2_get_bytes_left(gb) > 0) {

                    GetByteContext gbc;



                    opcode = bytestream2_get_byte(gb);

                    if (opcode >= 0x20)

                        break;

                    bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);



                    pos = -(opcode | 32 * bytestream2_get_byte(gb)) - 1;

                    bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                }

            }

            high = 0;

            if (opcode < 0x40)

                break;

            bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

            pos = (-((opcode & 0x1F) | 32 * bytestream2_get_byte(gb)) - 1);

            bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            len = (opcode >> 5) - 1;

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                --len;

            } while (len && bytestream2_get_bytes_left(&gbc) > 0);

        }

        len = opcode & 0x1F;

        if (!len) {

            if (!bytestream2_peek_byte(gb)) {

                do {

                    bytestream2_skip(gb, 1);

                    len += 255;

                } while (!bytestream2_peek_byte(gb) && bytestream2_get_bytes_left(gb) > 0);

            }

            len += bytestream2_get_byte(gb) + 31;

        }

        pos = -bytestream2_get_byte(gb);

        bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

        bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos - (bytestream2_get_byte(gb) << 8), SEEK_SET);

        if (bytestream2_tell_p(pb) == bytestream2_tell(&gbc))

            break;

        if (len < 5 || bytestream2_tell_p(pb) - bytestream2_tell(&gbc) < 4) {

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                --len;

            } while (len && bytestream2_get_bytes_left(&gbc) > 0);

        } else {

            bytestream2_put_le32(pb, bytestream2_get_le32(&gbc));

            len--;

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                len--;

            } while (len && bytestream2_get_bytes_left(&gbc) > 0);

        }

    }



    return 0;

}

static void cpu_pre_save(void *opaque)

{

    CPUState *env = opaque;

    int i;



    cpu_synchronize_state(env);



    /* FPU */

    env->fpus_vmstate = (env->fpus & ~0x3800) | (env->fpstt & 0x7) << 11;

    env->fptag_vmstate = 0;

    for(i = 0; i < 8; i++) {

        env->fptag_vmstate |= ((!env->fptags[i]) << i);

    }



#ifdef USE_X86LDOUBLE

    env->fpregs_format_vmstate = 0;

#else

    env->fpregs_format_vmstate = 1;

#endif

}

static void save_native_fp_fxsave(CPUState *env)

{

    struct fpxstate *fp = &fpx1;

    int fptag, i, j;

    uint16_t fpuc;



    asm volatile ("fxsave %0" : : "m" (*fp));

    env->fpuc = fp->fpuc;

    env->fpstt = (fp->fpus >> 11) & 7;

    env->fpus = fp->fpus & ~0x3800;

    fptag = fp->fptag ^ 0xff;

    for(i = 0;i < 8; i++) {

        env->fptags[i] = (fptag >> i) & 1;

    }

    j = env->fpstt;

    for(i = 0;i < 8; i++) {

        memcpy(&env->fpregs[j].d, &fp->fpregs1[i * 16], 10);

        j = (j + 1) & 7;

    }

    if (env->cpuid_features & CPUID_SSE) {

        env->mxcsr = fp->mxcsr;

        memcpy(env->xmm_regs, fp->xmm_regs, CPU_NB_REGS * 16);

    }



    /* we must restore the default rounding state */

    asm volatile ("fninit");

    fpuc = 0x037f | (env->fpuc & (3 << 10));

    asm volatile("fldcw %0" : : "m" (fpuc));

}

static void restore_native_fp_frstor(CPUState *env)

{

    int fptag, i, j;

    struct fpstate fp1, *fp = &fp1;



    fp->fpuc = env->fpuc;

    fp->fpus = (env->fpus & ~0x3800) | (env->fpstt & 0x7) << 11;

    fptag = 0;

    for (i=7; i>=0; i--) {

	fptag <<= 2;

	if (env->fptags[i]) {

            fptag |= 3;

        } else {

            /* the FPU automatically computes it */

        }

    }

    fp->fptag = fptag;

    j = env->fpstt;

    for(i = 0;i < 8; i++) {

        memcpy(&fp->fpregs1[i * 10], &env->fpregs[j].d, 10);

        j = (j + 1) & 7;

    }

    asm volatile ("frstor %0" : "=m" (*fp));

}

static void restore_native_fp_fxrstor(CPUState *env)

{

    struct fpxstate *fp = &fpx1;

    int i, j, fptag;



    fp->fpuc = env->fpuc;

    fp->fpus = (env->fpus & ~0x3800) | (env->fpstt & 0x7) << 11;

    fptag = 0;

    for(i = 0; i < 8; i++)

        fptag |= (env->fptags[i] << i);

    fp->fptag = fptag ^ 0xff;



    j = env->fpstt;

    for(i = 0;i < 8; i++) {

        memcpy(&fp->fpregs1[i * 16], &env->fpregs[j].d, 10);

        j = (j + 1) & 7;

    }

    if (env->cpuid_features & CPUID_SSE) {

        fp->mxcsr = env->mxcsr;

        /* XXX: check if DAZ is not available */

        fp->mxcsr_mask = 0xffff;

        memcpy(fp->xmm_regs, env->xmm_regs, CPU_NB_REGS * 16);

    }

    asm volatile ("fxrstor %0" : "=m" (*fp));

}

static int decode_thread(void *arg)

{

    VideoState *is = arg;

    AVFormatContext *ic;

    int err, i, ret;

    int st_index[AVMEDIA_TYPE_NB];

    AVPacket pkt1, *pkt = &pkt1;

    AVFormatParameters params, *ap = &params;

    int eof=0;

    int pkt_in_play_range = 0;



    ic = avformat_alloc_context();



    memset(st_index, -1, sizeof(st_index));

    is->video_stream = -1;

    is->audio_stream = -1;

    is->subtitle_stream = -1;



    global_video_state = is;

    url_set_interrupt_cb(decode_interrupt_cb);



    memset(ap, 0, sizeof(*ap));



    ap->prealloced_context = 1;

    ap->width = frame_width;

    ap->height= frame_height;

    ap->time_base= (AVRational){1, 25};

    ap->pix_fmt = frame_pix_fmt;



    set_context_opts(ic, avformat_opts, AV_OPT_FLAG_DECODING_PARAM, NULL);



    err = av_open_input_file(&ic, is->filename, is->iformat, 0, ap);

    if (err < 0) {

        print_error(is->filename, err);

        ret = -1;

        goto fail;

    }

    is->ic = ic;



    if(genpts)

        ic->flags |= AVFMT_FLAG_GENPTS;



    err = av_find_stream_info(ic);

    if (err < 0) {

        fprintf(stderr, "%s: could not find codec parameters\n", is->filename);

        ret = -1;

        goto fail;

    }

    if(ic->pb)

        ic->pb->eof_reached= 0; //FIXME hack, ffplay maybe should not use url_feof() to test for the end



    if(seek_by_bytes<0)

        seek_by_bytes= !!(ic->iformat->flags & AVFMT_TS_DISCONT);



    /* if seeking requested, we execute it */

    if (start_time != AV_NOPTS_VALUE) {

        int64_t timestamp;



        timestamp = start_time;

        /* add the stream start time */

        if (ic->start_time != AV_NOPTS_VALUE)

            timestamp += ic->start_time;

        ret = avformat_seek_file(ic, -1, INT64_MIN, timestamp, INT64_MAX, 0);

        if (ret < 0) {

            fprintf(stderr, "%s: could not seek to position %0.3f\n",

                    is->filename, (double)timestamp / AV_TIME_BASE);

        }

    }



    for (i = 0; i < ic->nb_streams; i++)

        ic->streams[i]->discard = AVDISCARD_ALL;

    if (!video_disable)

        st_index[AVMEDIA_TYPE_VIDEO] =

            av_find_best_stream(ic, AVMEDIA_TYPE_VIDEO,

                                wanted_stream[AVMEDIA_TYPE_VIDEO], -1, NULL, 0);

    if (!audio_disable)

        st_index[AVMEDIA_TYPE_AUDIO] =

            av_find_best_stream(ic, AVMEDIA_TYPE_AUDIO,

                                wanted_stream[AVMEDIA_TYPE_AUDIO],

                                st_index[AVMEDIA_TYPE_VIDEO],

                                NULL, 0);

    if (!video_disable)

        st_index[AVMEDIA_TYPE_SUBTITLE] =

            av_find_best_stream(ic, AVMEDIA_TYPE_SUBTITLE,

                                wanted_stream[AVMEDIA_TYPE_SUBTITLE],

                                (st_index[AVMEDIA_TYPE_AUDIO] >= 0 ?

                                 st_index[AVMEDIA_TYPE_AUDIO] :

                                 st_index[AVMEDIA_TYPE_VIDEO]),

                                NULL, 0);

    if (show_status) {

        av_dump_format(ic, 0, is->filename, 0);

    }



    /* open the streams */

    if (st_index[AVMEDIA_TYPE_AUDIO] >= 0) {

        stream_component_open(is, st_index[AVMEDIA_TYPE_AUDIO]);

    }



    ret=-1;

    if (st_index[AVMEDIA_TYPE_VIDEO] >= 0) {

        ret= stream_component_open(is, st_index[AVMEDIA_TYPE_VIDEO]);

    }

    is->refresh_tid = SDL_CreateThread(refresh_thread, is);

    if(ret<0) {

        if (!display_disable)

            is->show_audio = 2;

    }



    if (st_index[AVMEDIA_TYPE_SUBTITLE] >= 0) {

        stream_component_open(is, st_index[AVMEDIA_TYPE_SUBTITLE]);

    }



    if (is->video_stream < 0 && is->audio_stream < 0) {

        fprintf(stderr, "%s: could not open codecs\n", is->filename);

        ret = -1;

        goto fail;

    }



    for(;;) {

        if (is->abort_request)

            break;

        if (is->paused != is->last_paused) {

            is->last_paused = is->paused;

            if (is->paused)

                is->read_pause_return= av_read_pause(ic);

            else

                av_read_play(ic);

        }

#if CONFIG_RTSP_DEMUXER

        if (is->paused && !strcmp(ic->iformat->name, "rtsp")) {

            /* wait 10 ms to avoid trying to get another packet */

            /* XXX: horrible */

            SDL_Delay(10);

            continue;

        }

#endif

        if (is->seek_req) {

            int64_t seek_target= is->seek_pos;

            int64_t seek_min= is->seek_rel > 0 ? seek_target - is->seek_rel + 2: INT64_MIN;

            int64_t seek_max= is->seek_rel < 0 ? seek_target - is->seek_rel - 2: INT64_MAX;

//FIXME the +-2 is due to rounding being not done in the correct direction in generation

//      of the seek_pos/seek_rel variables



            ret = avformat_seek_file(is->ic, -1, seek_min, seek_target, seek_max, is->seek_flags);

            if (ret < 0) {

                fprintf(stderr, "%s: error while seeking\n", is->ic->filename);

            }else{

                if (is->audio_stream >= 0) {

                    packet_queue_flush(&is->audioq);

                    packet_queue_put(&is->audioq, &flush_pkt);

                }

                if (is->subtitle_stream >= 0) {

                    packet_queue_flush(&is->subtitleq);

                    packet_queue_put(&is->subtitleq, &flush_pkt);

                }

                if (is->video_stream >= 0) {

                    packet_queue_flush(&is->videoq);

                    packet_queue_put(&is->videoq, &flush_pkt);

                }

            }

            is->seek_req = 0;

            eof= 0;

        }



        /* if the queue are full, no need to read more */

        if (   is->audioq.size + is->videoq.size + is->subtitleq.size > MAX_QUEUE_SIZE

            || (   (is->audioq   .size  > MIN_AUDIOQ_SIZE || is->audio_stream<0)

                && (is->videoq   .nb_packets > MIN_FRAMES || is->video_stream<0)

                && (is->subtitleq.nb_packets > MIN_FRAMES || is->subtitle_stream<0))) {

            /* wait 10 ms */

            SDL_Delay(10);

            continue;

        }

        if(eof) {

            if(is->video_stream >= 0){

                av_init_packet(pkt);

                pkt->data=NULL;

                pkt->size=0;

                pkt->stream_index= is->video_stream;

                packet_queue_put(&is->videoq, pkt);

            }

            SDL_Delay(10);

            if(is->audioq.size + is->videoq.size + is->subtitleq.size ==0){

                if(loop!=1 && (!loop || --loop)){

                    stream_seek(cur_stream, start_time != AV_NOPTS_VALUE ? start_time : 0, 0, 0);

                }else if(autoexit){

                    ret=AVERROR_EOF;

                    goto fail;

                }

            }

            continue;

        }

        ret = av_read_frame(ic, pkt);

        if (ret < 0) {

            if (ret == AVERROR_EOF || ic->pb->eof_reached)

                eof=1;

            if (ic->pb->error)

                break;

            SDL_Delay(100); /* wait for user event */

            continue;

        }

        /* check if packet is in play range specified by user, then queue, otherwise discard */

        pkt_in_play_range = duration == AV_NOPTS_VALUE ||

                (pkt->pts - ic->streams[pkt->stream_index]->start_time) *

                av_q2d(ic->streams[pkt->stream_index]->time_base) -

                (double)(start_time != AV_NOPTS_VALUE ? start_time : 0)/1000000

                <= ((double)duration/1000000);

        if (pkt->stream_index == is->audio_stream && pkt_in_play_range) {

            packet_queue_put(&is->audioq, pkt);

        } else if (pkt->stream_index == is->video_stream && pkt_in_play_range) {

            packet_queue_put(&is->videoq, pkt);

        } else if (pkt->stream_index == is->subtitle_stream && pkt_in_play_range) {

            packet_queue_put(&is->subtitleq, pkt);

        } else {

            av_free_packet(pkt);

        }

    }

    /* wait until the end */

    while (!is->abort_request) {

        SDL_Delay(100);

    }



    ret = 0;

 fail:

    /* disable interrupting */

    global_video_state = NULL;



    /* close each stream */

    if (is->audio_stream >= 0)

        stream_component_close(is, is->audio_stream);

    if (is->video_stream >= 0)

        stream_component_close(is, is->video_stream);

    if (is->subtitle_stream >= 0)

        stream_component_close(is, is->subtitle_stream);

    if (is->ic) {

        av_close_input_file(is->ic);

        is->ic = NULL; /* safety */

    }

    url_set_interrupt_cb(NULL);



    if (ret != 0) {

        SDL_Event event;



        event.type = FF_QUIT_EVENT;

        event.user.data1 = is;

        SDL_PushEvent(&event);

    }

    return 0;

}

static int process_input(void)

{

    InputFile *ifile;

    AVFormatContext *is;

    InputStream *ist;

    AVPacket pkt;

    int ret, i, j;



    /* select the stream that we must read now */

    ifile = select_input_file();

    /* if none, if is finished */

    if (!ifile) {

        if (got_eagain()) {

            reset_eagain();

            av_usleep(10000);

            return AVERROR(EAGAIN);

        }

        av_log(NULL, AV_LOG_VERBOSE, "No more inputs to read from.\n");

        return AVERROR_EOF;

    }



    is  = ifile->ctx;

    ret = get_input_packet(ifile, &pkt);



    if (ret == AVERROR(EAGAIN)) {

        ifile->eagain = 1;

        return ret;

    }

    if (ret < 0) {

        if (ret != AVERROR_EOF) {

            print_error(is->filename, ret);

            if (exit_on_error)

                exit(1);

        }

        ifile->eof_reached = 1;



        for (i = 0; i < ifile->nb_streams; i++) {

            ist = input_streams[ifile->ist_index + i];

            if (ist->decoding_needed)

                output_packet(ist, NULL);



            /* mark all outputs that don't go through lavfi as finished */

            for (j = 0; j < nb_output_streams; j++) {

                OutputStream *ost = output_streams[j];



                if (ost->source_index == ifile->ist_index + i &&

                    (ost->stream_copy || ost->enc->type == AVMEDIA_TYPE_SUBTITLE))

                    ost->finished= 1;

            }

        }



        return AVERROR(EAGAIN);

    }



    reset_eagain();



    if (do_pkt_dump) {

        av_pkt_dump_log2(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump,

                         is->streams[pkt.stream_index]);

    }

    /* the following test is needed in case new streams appear

       dynamically in stream : we ignore them */

    if (pkt.stream_index >= ifile->nb_streams)

        goto discard_packet;



    ist = input_streams[ifile->ist_index + pkt.stream_index];

    if (ist->discard)

        goto discard_packet;



    if (pkt.dts != AV_NOPTS_VALUE)

        pkt.dts += av_rescale_q(ifile->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);

    if (pkt.pts != AV_NOPTS_VALUE)

        pkt.pts += av_rescale_q(ifile->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);



    if (pkt.pts != AV_NOPTS_VALUE)

        pkt.pts *= ist->ts_scale;

    if (pkt.dts != AV_NOPTS_VALUE)

        pkt.dts *= ist->ts_scale;



    if (pkt.dts != AV_NOPTS_VALUE && ist->next_dts != AV_NOPTS_VALUE &&

        (is->iformat->flags & AVFMT_TS_DISCONT)) {

        int64_t pkt_dts = av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

        int64_t delta   = pkt_dts - ist->next_dts;



        if ((FFABS(delta) > 1LL * dts_delta_threshold * AV_TIME_BASE || pkt_dts + 1 < ist->last_dts) && !copy_ts) {

            ifile->ts_offset -= delta;

            av_log(NULL, AV_LOG_DEBUG,

                   "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n",

                   delta, ifile->ts_offset);

            pkt.dts -= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            if (pkt.pts != AV_NOPTS_VALUE)

                pkt.pts -= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

        }

    }



    ret = output_packet(ist, &pkt);

    if (ret < 0) {

        av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d\n",

               ist->file_index, ist->st->index);

        if (exit_on_error)

            exit(1);

    }



discard_packet:

    av_free_packet(&pkt);



    return 0;

}

void opt_input_file(const char *filename)

{

    AVFormatContext *ic;

    AVFormatParameters params, *ap = &params;

    int err, i, ret, rfps;



    /* get default parameters from command line */

    memset(ap, 0, sizeof(*ap));

    ap->sample_rate = audio_sample_rate;

    ap->channels = audio_channels;

    ap->frame_rate = frame_rate;

    ap->width = frame_width;

    ap->height = frame_height;



    /* open the input file with generic libav function */

    err = av_open_input_file(&ic, filename, file_iformat, 0, ap);

    if (err < 0) {

        print_error(filename, err);

        exit(1);

    }



    /* If not enough info to get the stream parameters, we decode the

       first frames to get it. (used in mpeg case for example) */

    ret = av_find_stream_info(ic);

    if (ret < 0) {

        fprintf(stderr, "%s: could not find codec parameters\n", filename);

        exit(1);

    }



    /* update the current parameters so that they match the one of the input stream */

    for(i=0;i<ic->nb_streams;i++) {

        AVCodecContext *enc = &ic->streams[i]->codec;

        switch(enc->codec_type) {

        case CODEC_TYPE_AUDIO:

            //fprintf(stderr, "\nInput Audio channels: %d", enc->channels);

            audio_channels = enc->channels;

            audio_sample_rate = enc->sample_rate;

            break;

        case CODEC_TYPE_VIDEO:

            frame_height = enc->height;

            frame_width = enc->width;

            rfps = ic->streams[i]->r_frame_rate;

            if (enc->frame_rate != rfps) {

                fprintf(stderr,"\nSeems that stream %d comes from film source: %2.2f->%2.2f\n",

                    i, (float)enc->frame_rate / FRAME_RATE_BASE,

                    (float)rfps / FRAME_RATE_BASE);

            }

            /* update the current frame rate to match the stream frame rate */

            frame_rate = rfps;

            break;

        default:

            abort();

        }

    }



    input_files[nb_input_files] = ic;

    /* dump the file content */

    dump_format(ic, nb_input_files, filename, 0);

    nb_input_files++;

    file_iformat = NULL;

    file_oformat = NULL;

}

static int opt_output_file(const char *opt, const char *filename)

{

    AVFormatContext *oc;

    int i, err;

    AVOutputFormat *file_oformat;

    OutputStream *ost;

    InputStream  *ist;



    if (!strcmp(filename, "-"))

        filename = "pipe:";



    err = avformat_alloc_output_context2(&oc, NULL, last_asked_format, filename);

    last_asked_format = NULL;

    if (!oc) {

        print_error(filename, err);

        exit_program(1);

    }

    file_oformat= oc->oformat;



    if (!strcmp(file_oformat->name, "ffm") &&

        av_strstart(filename, "http:", NULL)) {

        /* special case for files sent to ffserver: we get the stream

           parameters from ffserver */

        int err = read_ffserver_streams(oc, filename);

        if (err < 0) {

            print_error(filename, err);

            exit_program(1);

        }

    } else if (!nb_stream_maps) {

        /* pick the "best" stream of each type */

#define NEW_STREAM(type, index)\

        if (index >= 0) {\

            ost = new_ ## type ## _stream(oc);\

            ost->source_index = index;\

            ost->sync_ist     = &input_streams[index];\

            input_streams[index].discard = 0;\

        }



        /* video: highest resolution */

        if (!video_disable && oc->oformat->video_codec != CODEC_ID_NONE) {

            int area = 0, idx = -1;

            for (i = 0; i < nb_input_streams; i++) {

                ist = &input_streams[i];

                if (ist->st->codec->codec_type == AVMEDIA_TYPE_VIDEO &&

                    ist->st->codec->width * ist->st->codec->height > area) {

                    area = ist->st->codec->width * ist->st->codec->height;

                    idx = i;

                }

            }

            NEW_STREAM(video, idx);

        }



        /* audio: most channels */

        if (!audio_disable && oc->oformat->audio_codec != CODEC_ID_NONE) {

            int channels = 0, idx = -1;

            for (i = 0; i < nb_input_streams; i++) {

                ist = &input_streams[i];

                if (ist->st->codec->codec_type == AVMEDIA_TYPE_AUDIO &&

                    ist->st->codec->channels > channels) {

                    channels = ist->st->codec->channels;

                    idx = i;

                }

            }

            NEW_STREAM(audio, idx);

        }



        /* subtitles: pick first */

        if (!subtitle_disable && oc->oformat->subtitle_codec != CODEC_ID_NONE) {

            for (i = 0; i < nb_input_streams; i++)

                if (input_streams[i].st->codec->codec_type == AVMEDIA_TYPE_SUBTITLE) {

                    NEW_STREAM(subtitle, i);

                    break;

                }

        }

        /* do something with data? */

    } else {

        for (i = 0; i < nb_stream_maps; i++) {

            StreamMap *map = &stream_maps[i];



            if (map->disabled)

                continue;



            ist = &input_streams[input_files[map->file_index].ist_index + map->stream_index];

            switch (ist->st->codec->codec_type) {

            case AVMEDIA_TYPE_VIDEO:    ost = new_video_stream(oc);    break;

            case AVMEDIA_TYPE_AUDIO:    ost = new_audio_stream(oc);    break;

            case AVMEDIA_TYPE_SUBTITLE: ost = new_subtitle_stream(oc); break;

            case AVMEDIA_TYPE_DATA:     ost = new_data_stream(oc);     break;

            default:

                av_log(NULL, AV_LOG_ERROR, "Cannot map stream #%d.%d - unsupported type.\n",

                       map->file_index, map->stream_index);

                exit_program(1);

            }



            ost->source_index = input_files[map->file_index].ist_index + map->stream_index;

            ost->sync_ist = &input_streams[input_files[map->sync_file_index].ist_index +

                                           map->sync_stream_index];

            ist->discard = 0;

        }

    }



    av_dict_copy(&oc->metadata, metadata, 0);

    av_dict_free(&metadata);





    if (nb_output_files == MAX_FILES)

        exit_program(1);                /* a temporary hack until all the other MAX_FILES-sized arrays are removed */

    output_files = grow_array(output_files, sizeof(*output_files), &nb_output_files, nb_output_files + 1);

    output_files[nb_output_files - 1].ctx       = oc;

    output_files[nb_output_files - 1].ost_index = nb_output_streams - oc->nb_streams;

    av_dict_copy(&output_files[nb_output_files - 1].opts, format_opts, 0);



    /* check filename in case of an image number is expected */

    if (oc->oformat->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(oc->filename)) {

            print_error(oc->filename, AVERROR(EINVAL));

            exit_program(1);

        }

    }



    if (!(oc->oformat->flags & AVFMT_NOFILE)) {

        /* test if it already exists to avoid loosing precious files */

        if (!file_overwrite &&

            (strchr(filename, ':') == NULL ||

             filename[1] == ':' ||

             av_strstart(filename, "file:", NULL))) {

            if (avio_check(filename, 0) == 0) {

                if (!using_stdin) {

                    fprintf(stderr,"File '%s' already exists. Overwrite ? [y/N] ", filename);

                    fflush(stderr);

                    if (!read_yesno()) {

                        fprintf(stderr, "Not overwriting - exiting\n");

                        exit_program(1);

                    }

                }

                else {

                    fprintf(stderr,"File '%s' already exists. Exiting.\n", filename);

                    exit_program(1);

                }

            }

        }



        /* open the file */

        if ((err = avio_open(&oc->pb, filename, AVIO_FLAG_WRITE)) < 0) {

            print_error(filename, err);

            exit_program(1);

        }

    }



    oc->preload= (int)(mux_preload*AV_TIME_BASE);

    oc->max_delay= (int)(mux_max_delay*AV_TIME_BASE);



    if (loop_output >= 0) {

        av_log(NULL, AV_LOG_WARNING, "-loop_output is deprecated, use -loop\n");

        oc->loop_output = loop_output;

    }



    /* copy chapters */

    if (chapters_input_file >= nb_input_files) {

        if (chapters_input_file == INT_MAX) {

            /* copy chapters from the first input file that has them*/

            chapters_input_file = -1;

            for (i = 0; i < nb_input_files; i++)

                if (input_files[i].ctx->nb_chapters) {

                    chapters_input_file = i;

                    break;

                }

        } else {

            av_log(NULL, AV_LOG_ERROR, "Invalid input file index %d in chapter mapping.\n",

                   chapters_input_file);

            exit_program(1);

        }

    }

    if (chapters_input_file >= 0)

        copy_chapters(chapters_input_file, nb_output_files - 1);



    /* copy metadata */

    for (i = 0; i < nb_meta_data_maps; i++) {

        AVFormatContext *files[2];

        AVDictionary    **meta[2];

        int j;



#define METADATA_CHECK_INDEX(index, nb_elems, desc)\

        if ((index) < 0 || (index) >= (nb_elems)) {\

            av_log(NULL, AV_LOG_ERROR, "Invalid %s index %d while processing metadata maps\n",\

                     (desc), (index));\

            exit_program(1);\

        }



        int in_file_index = meta_data_maps[i][1].file;

        if (in_file_index < 0)

            continue;

        METADATA_CHECK_INDEX(in_file_index, nb_input_files, "input file")



        files[0] = oc;

        files[1] = input_files[in_file_index].ctx;



        for (j = 0; j < 2; j++) {

            MetadataMap *map = &meta_data_maps[i][j];



            switch (map->type) {

            case 'g':

                meta[j] = &files[j]->metadata;

                break;

            case 's':

                METADATA_CHECK_INDEX(map->index, files[j]->nb_streams, "stream")

                meta[j] = &files[j]->streams[map->index]->metadata;

                break;

            case 'c':

                METADATA_CHECK_INDEX(map->index, files[j]->nb_chapters, "chapter")

                meta[j] = &files[j]->chapters[map->index]->metadata;

                break;

            case 'p':

                METADATA_CHECK_INDEX(map->index, files[j]->nb_programs, "program")

                meta[j] = &files[j]->programs[map->index]->metadata;

                break;

            }

        }



        av_dict_copy(meta[0], *meta[1], AV_DICT_DONT_OVERWRITE);

    }



    /* copy global metadata by default */

    if (metadata_global_autocopy && nb_input_files)

        av_dict_copy(&oc->metadata, input_files[0].ctx->metadata,

                     AV_DICT_DONT_OVERWRITE);

    if (metadata_streams_autocopy)

        for (i = output_files[nb_output_files - 1].ost_index; i < nb_output_streams; i++) {

            InputStream *ist = &input_streams[output_streams[i].source_index];

            av_dict_copy(&output_streams[i].st->metadata, ist->st->metadata, AV_DICT_DONT_OVERWRITE);

        }



    frame_rate    = (AVRational){0, 0};

    frame_width   = 0;

    frame_height  = 0;

    audio_sample_rate = 0;

    audio_channels    = 0;

    audio_sample_fmt  = AV_SAMPLE_FMT_NONE;

    chapters_input_file = INT_MAX;



    av_freep(&meta_data_maps);

    nb_meta_data_maps = 0;

    metadata_global_autocopy   = 1;

    metadata_streams_autocopy  = 1;

    metadata_chapters_autocopy = 1;

    av_freep(&stream_maps);

    nb_stream_maps = 0;



    av_dict_free(&codec_names);



    av_freep(&forced_key_frames);

    uninit_opts();

    init_opts();

    return 0;

}

static int adpcm_decode_frame(AVCodecContext *avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    ADPCMDecodeContext *c = avctx->priv_data;

    ADPCMChannelStatus *cs;

    int n, m, channel, i;

    short *samples;

    const uint8_t *src;

    int st; /* stereo */

    int count1, count2;

    int nb_samples, coded_samples, ret;



    nb_samples = get_nb_samples(avctx, buf, buf_size, &coded_samples);

    if (nb_samples <= 0) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of samples in packet\n");

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    c->frame.nb_samples = nb_samples;

    if ((ret = avctx->get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = (short *)c->frame.data[0];



    /* use coded_samples when applicable */

    /* it is always <= nb_samples, so the output buffer will be large enough */

    if (coded_samples) {

        if (coded_samples != nb_samples)

            av_log(avctx, AV_LOG_WARNING, "mismatch in coded sample count\n");

        c->frame.nb_samples = nb_samples = coded_samples;

    }



    src = buf;



    st = avctx->channels == 2 ? 1 : 0;



    switch(avctx->codec->id) {

    case CODEC_ID_ADPCM_IMA_QT:

        /* In QuickTime, IMA is encoded by chunks of 34 bytes (=64 samples).

           Channel data is interleaved per-chunk. */

        for (channel = 0; channel < avctx->channels; channel++) {

            int16_t predictor;

            int step_index;

            cs = &(c->status[channel]);

            /* (pppppp) (piiiiiii) */



            /* Bits 15-7 are the _top_ 9 bits of the 16-bit initial predictor value */

            predictor = AV_RB16(src);

            step_index = predictor & 0x7F;

            predictor &= 0xFF80;



            src += 2;



            if (cs->step_index == step_index) {

                int diff = (int)predictor - cs->predictor;

                if (diff < 0)

                    diff = - diff;

                if (diff > 0x7f)

                    goto update;

            } else {

            update:

                cs->step_index = step_index;

                cs->predictor = predictor;

            }



            if (cs->step_index > 88){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i\n", cs->step_index);

                cs->step_index = 88;

            }



            samples = (short *)c->frame.data[0] + channel;



            for (m = 0; m < 32; m++) {

                *samples = adpcm_ima_qt_expand_nibble(cs, src[0] & 0x0F, 3);

                samples += avctx->channels;

                *samples = adpcm_ima_qt_expand_nibble(cs, src[0] >> 4  , 3);

                samples += avctx->channels;

                src ++;

            }

        }

        break;

    case CODEC_ID_ADPCM_IMA_WAV:

        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        for(i=0; i<avctx->channels; i++){

            cs = &(c->status[i]);

            cs->predictor = *samples++ = (int16_t)bytestream_get_le16(&src);



            cs->step_index = *src++;

            if (cs->step_index > 88){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i\n", cs->step_index);

                cs->step_index = 88;

            }

            if (*src++) av_log(avctx, AV_LOG_ERROR, "unused byte should be null but is %d!!\n", src[-1]); /* unused */

        }



        for (n = (nb_samples - 1) / 8; n > 0; n--) {

            for (i = 0; i < avctx->channels; i++) {

                cs = &c->status[i];

                for (m = 0; m < 4; m++) {

                    uint8_t v = *src++;

                    *samples = adpcm_ima_expand_nibble(cs, v & 0x0F, 3);

                    samples += avctx->channels;

                    *samples = adpcm_ima_expand_nibble(cs, v >> 4  , 3);

                    samples += avctx->channels;

                }

                samples -= 8 * avctx->channels - 1;

            }

            samples += 7 * avctx->channels;

        }

        break;

    case CODEC_ID_ADPCM_4XM:

        for (i = 0; i < avctx->channels; i++)

            c->status[i].predictor= (int16_t)bytestream_get_le16(&src);



        for (i = 0; i < avctx->channels; i++) {

            c->status[i].step_index= (int16_t)bytestream_get_le16(&src);

            c->status[i].step_index = av_clip(c->status[i].step_index, 0, 88);

        }



        for (i = 0; i < avctx->channels; i++) {

            samples = (short *)c->frame.data[0] + i;

            cs = &c->status[i];

            for (n = nb_samples >> 1; n > 0; n--, src++) {

                uint8_t v = *src;

                *samples = adpcm_ima_expand_nibble(cs, v & 0x0F, 4);

                samples += avctx->channels;

                *samples = adpcm_ima_expand_nibble(cs, v >> 4  , 4);

                samples += avctx->channels;

            }

        }

        break;

    case CODEC_ID_ADPCM_MS:

    {

        int block_predictor;



        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        block_predictor = av_clip(*src++, 0, 6);

        c->status[0].coeff1 = ff_adpcm_AdaptCoeff1[block_predictor];

        c->status[0].coeff2 = ff_adpcm_AdaptCoeff2[block_predictor];

        if (st) {

            block_predictor = av_clip(*src++, 0, 6);

            c->status[1].coeff1 = ff_adpcm_AdaptCoeff1[block_predictor];

            c->status[1].coeff2 = ff_adpcm_AdaptCoeff2[block_predictor];

        }

        c->status[0].idelta = (int16_t)bytestream_get_le16(&src);

        if (st){

            c->status[1].idelta = (int16_t)bytestream_get_le16(&src);

        }



        c->status[0].sample1 = bytestream_get_le16(&src);

        if (st) c->status[1].sample1 = bytestream_get_le16(&src);

        c->status[0].sample2 = bytestream_get_le16(&src);

        if (st) c->status[1].sample2 = bytestream_get_le16(&src);



        *samples++ = c->status[0].sample2;

        if (st) *samples++ = c->status[1].sample2;

        *samples++ = c->status[0].sample1;

        if (st) *samples++ = c->status[1].sample1;

        for(n = (nb_samples - 2) >> (1 - st); n > 0; n--, src++) {

            *samples++ = adpcm_ms_expand_nibble(&c->status[0 ], src[0] >> 4  );

            *samples++ = adpcm_ms_expand_nibble(&c->status[st], src[0] & 0x0F);

        }

        break;

    }

    case CODEC_ID_ADPCM_IMA_DK4:

        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        for (channel = 0; channel < avctx->channels; channel++) {

            cs = &c->status[channel];

            cs->predictor  = (int16_t)bytestream_get_le16(&src);

            cs->step_index = av_clip(*src++, 0, 88);

            src++;

            *samples++ = cs->predictor;

        }

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v = *src;

            *samples++ = adpcm_ima_expand_nibble(&c->status[0 ], v >> 4  , 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v & 0x0F, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_DK3:

    {

        unsigned char last_byte = 0;

        unsigned char nibble;

        int decode_top_nibble_next = 0;

        int end_of_packet = 0;

        int diff_channel;



        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        c->status[0].predictor  = (int16_t)AV_RL16(src + 10);

        c->status[1].predictor  = (int16_t)AV_RL16(src + 12);

        c->status[0].step_index = av_clip(src[14], 0, 88);

        c->status[1].step_index = av_clip(src[15], 0, 88);

        /* sign extend the predictors */

        src += 16;

        diff_channel = c->status[1].predictor;



        /* the DK3_GET_NEXT_NIBBLE macro issues the break statement when

         * the buffer is consumed */

        while (1) {



            /* for this algorithm, c->status[0] is the sum channel and

             * c->status[1] is the diff channel */



            /* process the first predictor of the sum channel */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[0], nibble, 3);



            /* process the diff channel predictor */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[1], nibble, 3);



            /* process the first pair of stereo PCM samples */

            diff_channel = (diff_channel + c->status[1].predictor) / 2;

            *samples++ = c->status[0].predictor + c->status[1].predictor;

            *samples++ = c->status[0].predictor - c->status[1].predictor;



            /* process the second predictor of the sum channel */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[0], nibble, 3);



            /* process the second pair of stereo PCM samples */

            diff_channel = (diff_channel + c->status[1].predictor) / 2;

            *samples++ = c->status[0].predictor + c->status[1].predictor;

            *samples++ = c->status[0].predictor - c->status[1].predictor;

        }

        break;

    }

    case CODEC_ID_ADPCM_IMA_ISS:

        for (channel = 0; channel < avctx->channels; channel++) {

            cs = &c->status[channel];

            cs->predictor  = (int16_t)bytestream_get_le16(&src);

            cs->step_index = av_clip(*src++, 0, 88);

            src++;

        }



        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v1, v2;

            uint8_t v = *src;

            /* nibbles are swapped for mono */

            if (st) {

                v1 = v >> 4;

                v2 = v & 0x0F;

            } else {

                v2 = v >> 4;

                v1 = v & 0x0F;

            }

            *samples++ = adpcm_ima_expand_nibble(&c->status[0 ], v1, 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v2, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_APC:

        while (src < buf + buf_size) {

            uint8_t v = *src++;

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  v >> 4  , 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v & 0x0F, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_WS:

        for (channel = 0; channel < avctx->channels; channel++) {

            const uint8_t *src0;

            int src_stride;

            int16_t *smp = samples + channel;



            if (c->vqa_version == 3) {

                src0 = src + channel * buf_size / 2;

                src_stride = 1;

            } else {

                src0 = src + channel;

                src_stride = avctx->channels;

            }

            for (n = nb_samples / 2; n > 0; n--) {

                uint8_t v = *src0;

                src0 += src_stride;

                *smp = adpcm_ima_expand_nibble(&c->status[channel], v >> 4  , 3);

                smp += avctx->channels;

                *smp = adpcm_ima_expand_nibble(&c->status[channel], v & 0x0F, 3);

                smp += avctx->channels;

            }

        }

        src = buf + buf_size;

        break;

    case CODEC_ID_ADPCM_XA:

        while (buf_size >= 128) {

            xa_decode(samples, src, &c->status[0], &c->status[1],

                avctx->channels);

            src += 128;

            samples += 28 * 8;

            buf_size -= 128;

        }

        break;

    case CODEC_ID_ADPCM_IMA_EA_EACS:

        src += 4; // skip sample count (already read)



        for (i=0; i<=st; i++)

            c->status[i].step_index = av_clip(bytestream_get_le32(&src), 0, 88);

        for (i=0; i<=st; i++)

            c->status[i].predictor  = bytestream_get_le32(&src);



        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  *src>>4,   3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], *src&0x0F, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_EA_SEAD:

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            *samples++ = adpcm_ima_expand_nibble(&c->status[0], src[0] >> 4, 6);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st],src[0]&0x0F, 6);

        }

        break;

    case CODEC_ID_ADPCM_EA:

    {

        int32_t previous_left_sample, previous_right_sample;

        int32_t current_left_sample, current_right_sample;

        int32_t next_left_sample, next_right_sample;

        int32_t coeff1l, coeff2l, coeff1r, coeff2r;

        uint8_t shift_left, shift_right;



        /* Each EA ADPCM frame has a 12-byte header followed by 30-byte pieces,

           each coding 28 stereo samples. */



        src += 4; // skip sample count (already read)



        current_left_sample   = (int16_t)bytestream_get_le16(&src);

        previous_left_sample  = (int16_t)bytestream_get_le16(&src);

        current_right_sample  = (int16_t)bytestream_get_le16(&src);

        previous_right_sample = (int16_t)bytestream_get_le16(&src);



        for (count1 = 0; count1 < nb_samples / 28; count1++) {

            coeff1l = ea_adpcm_table[ *src >> 4       ];

            coeff2l = ea_adpcm_table[(*src >> 4  ) + 4];

            coeff1r = ea_adpcm_table[*src & 0x0F];

            coeff2r = ea_adpcm_table[(*src & 0x0F) + 4];

            src++;



            shift_left  = 20 - (*src >> 4);

            shift_right = 20 - (*src & 0x0F);

            src++;



            for (count2 = 0; count2 < 28; count2++) {

                next_left_sample  = sign_extend(*src >> 4, 4) << shift_left;

                next_right_sample = sign_extend(*src,      4) << shift_right;

                src++;



                next_left_sample = (next_left_sample +

                    (current_left_sample * coeff1l) +

                    (previous_left_sample * coeff2l) + 0x80) >> 8;

                next_right_sample = (next_right_sample +

                    (current_right_sample * coeff1r) +

                    (previous_right_sample * coeff2r) + 0x80) >> 8;



                previous_left_sample = current_left_sample;

                current_left_sample = av_clip_int16(next_left_sample);

                previous_right_sample = current_right_sample;

                current_right_sample = av_clip_int16(next_right_sample);

                *samples++ = (unsigned short)current_left_sample;

                *samples++ = (unsigned short)current_right_sample;

            }

        }



        if (src - buf == buf_size - 2)

            src += 2; // Skip terminating 0x0000



        break;

    }

    case CODEC_ID_ADPCM_EA_MAXIS_XA:

    {

        int coeff[2][2], shift[2];



        for(channel = 0; channel < avctx->channels; channel++) {

            for (i=0; i<2; i++)

                coeff[channel][i] = ea_adpcm_table[(*src >> 4) + 4*i];

            shift[channel] = 20 - (*src & 0x0F);

            src++;

        }

        for (count1 = 0; count1 < nb_samples / 2; count1++) {

            for(i = 4; i >= 0; i-=4) { /* Pairwise samples LL RR (st) or LL LL (mono) */

                for(channel = 0; channel < avctx->channels; channel++) {

                    int32_t sample = sign_extend(src[channel] >> i, 4) << shift[channel];

                    sample = (sample +

                             c->status[channel].sample1 * coeff[channel][0] +

                             c->status[channel].sample2 * coeff[channel][1] + 0x80) >> 8;

                    c->status[channel].sample2 = c->status[channel].sample1;

                    c->status[channel].sample1 = av_clip_int16(sample);

                    *samples++ = c->status[channel].sample1;

                }

            }

            src+=avctx->channels;

        }

        /* consume whole packet */

        src = buf + buf_size;

        break;

    }

    case CODEC_ID_ADPCM_EA_R1:

    case CODEC_ID_ADPCM_EA_R2:

    case CODEC_ID_ADPCM_EA_R3: {

        /* channel numbering

           2chan: 0=fl, 1=fr

           4chan: 0=fl, 1=rl, 2=fr, 3=rr

           6chan: 0=fl, 1=c,  2=fr, 3=rl,  4=rr, 5=sub */

        const int big_endian = avctx->codec->id == CODEC_ID_ADPCM_EA_R3;

        int32_t previous_sample, current_sample, next_sample;

        int32_t coeff1, coeff2;

        uint8_t shift;

        unsigned int channel;

        uint16_t *samplesC;

        const uint8_t *srcC;

        const uint8_t *src_end = buf + buf_size;

        int count = 0;



        src += 4; // skip sample count (already read)



        for (channel=0; channel<avctx->channels; channel++) {

            int32_t offset = (big_endian ? bytestream_get_be32(&src)

                                         : bytestream_get_le32(&src))

                           + (avctx->channels-channel-1) * 4;



            if ((offset < 0) || (offset >= src_end - src - 4)) break;

            srcC  = src + offset;

            samplesC = samples + channel;



            if (avctx->codec->id == CODEC_ID_ADPCM_EA_R1) {

                current_sample  = (int16_t)bytestream_get_le16(&srcC);

                previous_sample = (int16_t)bytestream_get_le16(&srcC);

            } else {

                current_sample  = c->status[channel].predictor;

                previous_sample = c->status[channel].prev_sample;

            }



            for (count1 = 0; count1 < nb_samples / 28; count1++) {

                if (*srcC == 0xEE) {  /* only seen in R2 and R3 */

                    srcC++;

                    if (srcC > src_end - 30*2) break;

                    current_sample  = (int16_t)bytestream_get_be16(&srcC);

                    previous_sample = (int16_t)bytestream_get_be16(&srcC);



                    for (count2=0; count2<28; count2++) {

                        *samplesC = (int16_t)bytestream_get_be16(&srcC);

                        samplesC += avctx->channels;

                    }

                } else {

                    coeff1 = ea_adpcm_table[ *srcC>>4     ];

                    coeff2 = ea_adpcm_table[(*srcC>>4) + 4];

                    shift = 20 - (*srcC++ & 0x0F);



                    if (srcC > src_end - 14) break;

                    for (count2=0; count2<28; count2++) {

                        if (count2 & 1)

                            next_sample = sign_extend(*srcC++,    4) << shift;

                        else

                            next_sample = sign_extend(*srcC >> 4, 4) << shift;



                        next_sample += (current_sample  * coeff1) +

                                       (previous_sample * coeff2);

                        next_sample = av_clip_int16(next_sample >> 8);



                        previous_sample = current_sample;

                        current_sample  = next_sample;

                        *samplesC = current_sample;

                        samplesC += avctx->channels;

                    }

                }

            }

            if (!count) {

                count = count1;

            } else if (count != count1) {

                av_log(avctx, AV_LOG_WARNING, "per-channel sample count mismatch\n");

                count = FFMAX(count, count1);

            }



            if (avctx->codec->id != CODEC_ID_ADPCM_EA_R1) {

                c->status[channel].predictor   = current_sample;

                c->status[channel].prev_sample = previous_sample;

            }

        }



        c->frame.nb_samples = count * 28;

        src = src_end;

        break;

    }

    case CODEC_ID_ADPCM_EA_XAS:

        for (channel=0; channel<avctx->channels; channel++) {

            int coeff[2][4], shift[4];

            short *s2, *s = &samples[channel];

            for (n=0; n<4; n++, s+=32*avctx->channels) {

                for (i=0; i<2; i++)

                    coeff[i][n] = ea_adpcm_table[(src[0]&0x0F)+4*i];

                shift[n] = 20 - (src[2] & 0x0F);

                for (s2=s, i=0; i<2; i++, src+=2, s2+=avctx->channels)

                    s2[0] = (src[0]&0xF0) + (src[1]<<8);

            }



            for (m=2; m<32; m+=2) {

                s = &samples[m*avctx->channels + channel];

                for (n=0; n<4; n++, src++, s+=32*avctx->channels) {

                    for (s2=s, i=0; i<8; i+=4, s2+=avctx->channels) {

                        int level = sign_extend(*src >> (4 - i), 4) << shift[n];

                        int pred  = s2[-1*avctx->channels] * coeff[0][n]

                                  + s2[-2*avctx->channels] * coeff[1][n];

                        s2[0] = av_clip_int16((level + pred + 0x80) >> 8);

                    }

                }

            }

        }

        break;

    case CODEC_ID_ADPCM_IMA_AMV:

    case CODEC_ID_ADPCM_IMA_SMJPEG:

        if (avctx->codec->id == CODEC_ID_ADPCM_IMA_AMV) {

            c->status[0].predictor = sign_extend(bytestream_get_le16(&src), 16);

            c->status[0].step_index = av_clip(bytestream_get_le16(&src), 0, 88);

            src += 4;

        } else {

            c->status[0].predictor = sign_extend(bytestream_get_be16(&src), 16);

            c->status[0].step_index = av_clip(bytestream_get_byte(&src), 0, 88);

            src += 1;

        }



        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            char hi, lo;

            lo = *src & 0x0F;

            hi = *src >> 4;



            if (avctx->codec->id == CODEC_ID_ADPCM_IMA_AMV)

                FFSWAP(char, hi, lo);



            *samples++ = adpcm_ima_expand_nibble(&c->status[0],

                lo, 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],

                hi, 3);

        }

        break;

    case CODEC_ID_ADPCM_CT:

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v = *src;

            *samples++ = adpcm_ct_expand_nibble(&c->status[0 ], v >> 4  );

            *samples++ = adpcm_ct_expand_nibble(&c->status[st], v & 0x0F);

        }

        break;

    case CODEC_ID_ADPCM_SBPRO_4:

    case CODEC_ID_ADPCM_SBPRO_3:

    case CODEC_ID_ADPCM_SBPRO_2:

        if (!c->status[0].step_index) {

            /* the first byte is a raw sample */

            *samples++ = 128 * (*src++ - 0x80);

            if (st)

              *samples++ = 128 * (*src++ - 0x80);

            c->status[0].step_index = 1;

            nb_samples--;

        }

        if (avctx->codec->id == CODEC_ID_ADPCM_SBPRO_4) {

            for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    src[0] >> 4, 4, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                    src[0] & 0x0F, 4, 0);

            }

        } else if (avctx->codec->id == CODEC_ID_ADPCM_SBPRO_3) {

            for (n = nb_samples / 3; n > 0; n--, src++) {

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                     src[0] >> 5        , 3, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    (src[0] >> 2) & 0x07, 3, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    src[0] & 0x03, 2, 0);

            }

        } else {

            for (n = nb_samples >> (2 - st); n > 0; n--, src++) {

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                     src[0] >> 6        , 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                    (src[0] >> 4) & 0x03, 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    (src[0] >> 2) & 0x03, 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                    src[0] & 0x03, 2, 2);

            }

        }

        break;

    case CODEC_ID_ADPCM_SWF:

    {

        GetBitContext gb;

        const int *table;

        int k0, signmask, nb_bits, count;

        int size = buf_size*8;



        init_get_bits(&gb, buf, size);



        //read bits & initial values

        nb_bits = get_bits(&gb, 2)+2;

        //av_log(NULL,AV_LOG_INFO,"nb_bits: %d\n", nb_bits);

        table = swf_index_tables[nb_bits-2];

        k0 = 1 << (nb_bits-2);

        signmask = 1 << (nb_bits-1);



        while (get_bits_count(&gb) <= size - 22*avctx->channels) {

            for (i = 0; i < avctx->channels; i++) {

                *samples++ = c->status[i].predictor = get_sbits(&gb, 16);

                c->status[i].step_index = get_bits(&gb, 6);

            }



            for (count = 0; get_bits_count(&gb) <= size - nb_bits*avctx->channels && count < 4095; count++) {

                int i;



                for (i = 0; i < avctx->channels; i++) {

                    // similar to IMA adpcm

                    int delta = get_bits(&gb, nb_bits);

                    int step = ff_adpcm_step_table[c->status[i].step_index];

                    long vpdiff = 0; // vpdiff = (delta+0.5)*step/4

                    int k = k0;



                    do {

                        if (delta & k)

                            vpdiff += step;

                        step >>= 1;

                        k >>= 1;

                    } while(k);

                    vpdiff += step;



                    if (delta & signmask)

                        c->status[i].predictor -= vpdiff;

                    else

                        c->status[i].predictor += vpdiff;



                    c->status[i].step_index += table[delta & (~signmask)];



                    c->status[i].step_index = av_clip(c->status[i].step_index, 0, 88);

                    c->status[i].predictor = av_clip_int16(c->status[i].predictor);



                    *samples++ = c->status[i].predictor;

                }

            }

        }

        src += buf_size;

        break;

    }

    case CODEC_ID_ADPCM_YAMAHA:

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v = *src;

            *samples++ = adpcm_yamaha_expand_nibble(&c->status[0 ], v & 0x0F);

            *samples++ = adpcm_yamaha_expand_nibble(&c->status[st], v >> 4  );

        }

        break;

    case CODEC_ID_ADPCM_THP:

    {

        int table[2][16];

        int prev[2][2];

        int ch;



        src += 4; // skip channel size

        src += 4; // skip number of samples (already read)



        for (i = 0; i < 32; i++)

            table[0][i] = (int16_t)bytestream_get_be16(&src);



        /* Initialize the previous sample.  */

        for (i = 0; i < 4; i++)

            prev[0][i] = (int16_t)bytestream_get_be16(&src);



        for (ch = 0; ch <= st; ch++) {

            samples = (short *)c->frame.data[0] + ch;



            /* Read in every sample for this channel.  */

            for (i = 0; i < nb_samples / 14; i++) {

                int index = (*src >> 4) & 7;

                unsigned int exp = *src++ & 15;

                int factor1 = table[ch][index * 2];

                int factor2 = table[ch][index * 2 + 1];



                /* Decode 14 samples.  */

                for (n = 0; n < 14; n++) {

                    int32_t sampledat;

                    if(n&1) sampledat = sign_extend(*src++, 4);

                    else    sampledat = sign_extend(*src >> 4, 4);



                    sampledat = ((prev[ch][0]*factor1

                                + prev[ch][1]*factor2) >> 11) + (sampledat << exp);

                    *samples = av_clip_int16(sampledat);

                    prev[ch][1] = prev[ch][0];

                    prev[ch][0] = *samples++;



                    /* In case of stereo, skip one sample, this sample

                       is for the other channel.  */

                    samples += st;

                }

            }

        }

        break;

    }



    default:

        return -1;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return src - buf;

}

static int pcm_decode_frame(AVCodecContext *avctx, void *data,
                            int *got_frame_ptr, AVPacket *avpkt)
{
    const uint8_t *src = avpkt->data;
    int buf_size       = avpkt->size;
    PCMDecode *s       = avctx->priv_data;
    int sample_size, c, n, ret, samples_per_block;
    uint8_t *samples;
    int32_t *dst_int32_t;
    sample_size = av_get_bits_per_sample(avctx->codec_id) / 8;
    /* av_get_bits_per_sample returns 0 for AV_CODEC_ID_PCM_DVD */
    samples_per_block = 1;
    if (AV_CODEC_ID_PCM_DVD == avctx->codec_id) {
        if (avctx->bits_per_coded_sample != 20 &&
            avctx->bits_per_coded_sample != 24) {
            av_log(avctx, AV_LOG_ERROR,
                   "PCM DVD unsupported sample depth %i\n",
                   avctx->bits_per_coded_sample);
        /* 2 samples are interleaved per block in PCM_DVD */
        samples_per_block = 2;
        sample_size       = avctx->bits_per_coded_sample * 2 / 8;
    } else if (avctx->codec_id == AV_CODEC_ID_PCM_LXF) {
        /* we process 40-bit blocks per channel for LXF */
        samples_per_block = 2;
        sample_size       = 5;
    if (sample_size == 0) {
        av_log(avctx, AV_LOG_ERROR, "Invalid sample_size\n");
    n = avctx->channels * sample_size;
    if (n && buf_size % n) {
        if (buf_size < n) {
            av_log(avctx, AV_LOG_ERROR,
                   "Invalid PCM packet, data has size %d but at least a size of %d was expected\n",
                   buf_size, n);
            return AVERROR_INVALIDDATA;
        } else
            buf_size -= buf_size % n;
    n = buf_size / sample_size;
    /* get output buffer */
    s->frame.nb_samples = n * samples_per_block / avctx->channels;
    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {
        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");
        return ret;
    samples = s->frame.data[0];
    switch (avctx->codec->id) {
    case AV_CODEC_ID_PCM_U32LE:
        DECODE(32, le32, src, samples, n, 0, 0x80000000)
        break;
    case AV_CODEC_ID_PCM_U32BE:
        DECODE(32, be32, src, samples, n, 0, 0x80000000)
        break;
    case AV_CODEC_ID_PCM_S24LE:
        DECODE(32, le24, src, samples, n, 8, 0)
        break;
    case AV_CODEC_ID_PCM_S24BE:
        DECODE(32, be24, src, samples, n, 8, 0)
        break;
    case AV_CODEC_ID_PCM_U24LE:
        DECODE(32, le24, src, samples, n, 8, 0x800000)
        break;
    case AV_CODEC_ID_PCM_U24BE:
        DECODE(32, be24, src, samples, n, 8, 0x800000)
        break;
    case AV_CODEC_ID_PCM_S24DAUD:
        for (; n > 0; n--) {
            uint32_t v = bytestream_get_be24(&src);
            v >>= 4; // sync flags are here
            AV_WN16A(samples, ff_reverse[(v >> 8) & 0xff] +
                             (ff_reverse[v        & 0xff] << 8));
            samples += 2;
        break;
    case AV_CODEC_ID_PCM_S16LE_PLANAR:
    {
        int i;
        n /= avctx->channels;
        for (c = 0; c < avctx->channels; c++) {
            samples = s->frame.extended_data[c];
            for (i = n; i > 0; i--) {
                AV_WN16A(samples, bytestream_get_le16(&src));
                samples += 2;
        break;
    case AV_CODEC_ID_PCM_U16LE:
        DECODE(16, le16, src, samples, n, 0, 0x8000)
        break;
    case AV_CODEC_ID_PCM_U16BE:
        DECODE(16, be16, src, samples, n, 0, 0x8000)
        break;
    case AV_CODEC_ID_PCM_S8:
        for (; n > 0; n--)
            *samples++ = *src++ + 128;
        break;
#if HAVE_BIGENDIAN
    case AV_CODEC_ID_PCM_F64LE:
        DECODE(64, le64, src, samples, n, 0, 0)
        break;
    case AV_CODEC_ID_PCM_S32LE:
    case AV_CODEC_ID_PCM_F32LE:
        DECODE(32, le32, src, samples, n, 0, 0)
        break;
    case AV_CODEC_ID_PCM_S16LE:
        DECODE(16, le16, src, samples, n, 0, 0)
        break;
    case AV_CODEC_ID_PCM_F64BE:
    case AV_CODEC_ID_PCM_F32BE:
    case AV_CODEC_ID_PCM_S32BE:
    case AV_CODEC_ID_PCM_S16BE:
#else
    case AV_CODEC_ID_PCM_F64BE:
        DECODE(64, be64, src, samples, n, 0, 0)
        break;
    case AV_CODEC_ID_PCM_F32BE:
    case AV_CODEC_ID_PCM_S32BE:
        DECODE(32, be32, src, samples, n, 0, 0)
        break;
    case AV_CODEC_ID_PCM_S16BE:
        DECODE(16, be16, src, samples, n, 0, 0)
        break;
    case AV_CODEC_ID_PCM_F64LE:
    case AV_CODEC_ID_PCM_F32LE:
    case AV_CODEC_ID_PCM_S32LE:
    case AV_CODEC_ID_PCM_S16LE:
#endif /* HAVE_BIGENDIAN */
    case AV_CODEC_ID_PCM_U8:
        memcpy(samples, src, n * sample_size);
        break;
    case AV_CODEC_ID_PCM_ZORK:
        for (; n > 0; n--) {
            int v = *src++;
            if (v < 128)
                v = 128 - v;
            *samples++ = v;
        break;
    case AV_CODEC_ID_PCM_ALAW:
    case AV_CODEC_ID_PCM_MULAW:
        for (; n > 0; n--) {
            AV_WN16A(samples, s->table[*src++]);
            samples += 2;
        break;
    case AV_CODEC_ID_PCM_DVD:
    {
        const uint8_t *src8;
        dst_int32_t = (int32_t *)s->frame.data[0];
        n /= avctx->channels;
        switch (avctx->bits_per_coded_sample) {
        case 20:
            while (n--) {
                c    = avctx->channels;
                src8 = src + 4 * c;
                while (c--) {
                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8   & 0xf0) <<  8);
                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++ & 0x0f) << 12);
                src = src8;
            break;
        case 24:
            while (n--) {
                c    = avctx->channels;
                src8 = src + 4 * c;
                while (c--) {
                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++) << 8);
                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++) << 8);
                src = src8;
            break;
        break;
    case AV_CODEC_ID_PCM_LXF:
    {
        int i;
        n /= avctx->channels;
        for (c = 0; c < avctx->channels; c++) {
            dst_int32_t = (int32_t *)s->frame.extended_data[c];
            for (i = 0; i < n; i++) {
                // extract low 20 bits and expand to 32 bits
                *dst_int32_t++ =  (src[2]         << 28) |
                                  (src[1]         << 20) |
                                  (src[0]         << 12) |
                                 ((src[2] & 0x0F) <<  8) |
                                   src[1];
                // extract high 20 bits and expand to 32 bits
                *dst_int32_t++ =  (src[4]         << 24) |
                                  (src[3]         << 16) |
                                 ((src[2] & 0xF0) <<  8) |
                                  (src[4]         <<  4) |
                                  (src[3]         >>  4);
                src += 5;
        break;
    default:
        return -1;
    *got_frame_ptr   = 1;
    *(AVFrame *)data = s->frame;
    return buf_size;

static int adpcm_decode_frame(AVCodecContext *avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    ADPCMDecodeContext *c = avctx->priv_data;

    ADPCMChannelStatus *cs;

    int n, m, channel, i;

    short *samples;

    int16_t **samples_p;

    int st; /* stereo */

    int count1, count2;

    int nb_samples, coded_samples, ret;

    GetByteContext gb;



    bytestream2_init(&gb, buf, buf_size);

    nb_samples = get_nb_samples(avctx, &gb, buf_size, &coded_samples);

    if (nb_samples <= 0) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of samples in packet\n");

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    c->frame.nb_samples = nb_samples;

    if ((ret = ff_get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = (short *)c->frame.data[0];

    samples_p = (int16_t **)c->frame.extended_data;



    /* use coded_samples when applicable */

    /* it is always <= nb_samples, so the output buffer will be large enough */

    if (coded_samples) {

        if (coded_samples != nb_samples)

            av_log(avctx, AV_LOG_WARNING, "mismatch in coded sample count\n");

        c->frame.nb_samples = nb_samples = coded_samples;

    }



    st = avctx->channels == 2 ? 1 : 0;



    switch(avctx->codec->id) {

    case AV_CODEC_ID_ADPCM_IMA_QT:

        /* In QuickTime, IMA is encoded by chunks of 34 bytes (=64 samples).

           Channel data is interleaved per-chunk. */

        for (channel = 0; channel < avctx->channels; channel++) {

            int predictor;

            int step_index;

            cs = &(c->status[channel]);

            /* (pppppp) (piiiiiii) */



            /* Bits 15-7 are the _top_ 9 bits of the 16-bit initial predictor value */

            predictor = sign_extend(bytestream2_get_be16u(&gb), 16);

            step_index = predictor & 0x7F;

            predictor &= ~0x7F;



            if (cs->step_index == step_index) {

                int diff = predictor - cs->predictor;

                if (diff < 0)

                    diff = - diff;

                if (diff > 0x7f)

                    goto update;

            } else {

            update:

                cs->step_index = step_index;

                cs->predictor = predictor;

            }



            if (cs->step_index > 88u){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index[%d] = %i\n",

                       channel, cs->step_index);

                return AVERROR_INVALIDDATA;

            }



            samples = samples_p[channel];



            for (m = 0; m < 64; m += 2) {

                int byte = bytestream2_get_byteu(&gb);

                samples[m    ] = adpcm_ima_qt_expand_nibble(cs, byte & 0x0F, 3);

                samples[m + 1] = adpcm_ima_qt_expand_nibble(cs, byte >> 4  , 3);

            }

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_WAV:

        for(i=0; i<avctx->channels; i++){

            cs = &(c->status[i]);

            cs->predictor = samples_p[i][0] = sign_extend(bytestream2_get_le16u(&gb), 16);



            cs->step_index = sign_extend(bytestream2_get_le16u(&gb), 16);

            if (cs->step_index > 88u){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index[%d] = %i\n",

                       i, cs->step_index);

                return AVERROR_INVALIDDATA;

            }

        }



        for (n = 0; n < (nb_samples - 1) / 8; n++) {

            for (i = 0; i < avctx->channels; i++) {

                cs = &c->status[i];

                samples = &samples_p[i][1 + n * 8];

                for (m = 0; m < 8; m += 2) {

                    int v = bytestream2_get_byteu(&gb);

                    samples[m    ] = adpcm_ima_expand_nibble(cs, v & 0x0F, 3);

                    samples[m + 1] = adpcm_ima_expand_nibble(cs, v >> 4  , 3);

                }

            }

        }

        break;

    case AV_CODEC_ID_ADPCM_4XM:

        for (i = 0; i < avctx->channels; i++)

            c->status[i].predictor = sign_extend(bytestream2_get_le16u(&gb), 16);



        for (i = 0; i < avctx->channels; i++) {

            c->status[i].step_index = sign_extend(bytestream2_get_le16u(&gb), 16);

            if (c->status[i].step_index > 88u) {

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index[%d] = %i\n",

                       i, c->status[i].step_index);

                return AVERROR_INVALIDDATA;

            }

        }



        for (i = 0; i < avctx->channels; i++) {

            samples = (int16_t *)c->frame.data[i];

            cs = &c->status[i];

            for (n = nb_samples >> 1; n > 0; n--) {

                int v = bytestream2_get_byteu(&gb);

                *samples++ = adpcm_ima_expand_nibble(cs, v & 0x0F, 4);

                *samples++ = adpcm_ima_expand_nibble(cs, v >> 4  , 4);

            }

        }

        break;

    case AV_CODEC_ID_ADPCM_MS:

    {

        int block_predictor;



        block_predictor = bytestream2_get_byteu(&gb);

        if (block_predictor > 6) {

            av_log(avctx, AV_LOG_ERROR, "ERROR: block_predictor[0] = %d\n",

                   block_predictor);

            return AVERROR_INVALIDDATA;

        }

        c->status[0].coeff1 = ff_adpcm_AdaptCoeff1[block_predictor];

        c->status[0].coeff2 = ff_adpcm_AdaptCoeff2[block_predictor];

        if (st) {

            block_predictor = bytestream2_get_byteu(&gb);

            if (block_predictor > 6) {

                av_log(avctx, AV_LOG_ERROR, "ERROR: block_predictor[1] = %d\n",

                       block_predictor);

                return AVERROR_INVALIDDATA;

            }

            c->status[1].coeff1 = ff_adpcm_AdaptCoeff1[block_predictor];

            c->status[1].coeff2 = ff_adpcm_AdaptCoeff2[block_predictor];

        }

        c->status[0].idelta = sign_extend(bytestream2_get_le16u(&gb), 16);

        if (st){

            c->status[1].idelta = sign_extend(bytestream2_get_le16u(&gb), 16);

        }



        c->status[0].sample1 = sign_extend(bytestream2_get_le16u(&gb), 16);

        if (st) c->status[1].sample1 = sign_extend(bytestream2_get_le16u(&gb), 16);

        c->status[0].sample2 = sign_extend(bytestream2_get_le16u(&gb), 16);

        if (st) c->status[1].sample2 = sign_extend(bytestream2_get_le16u(&gb), 16);



        *samples++ = c->status[0].sample2;

        if (st) *samples++ = c->status[1].sample2;

        *samples++ = c->status[0].sample1;

        if (st) *samples++ = c->status[1].sample1;

        for(n = (nb_samples - 2) >> (1 - st); n > 0; n--) {

            int byte = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ms_expand_nibble(&c->status[0 ], byte >> 4  );

            *samples++ = adpcm_ms_expand_nibble(&c->status[st], byte & 0x0F);

        }

        break;

    }

    case AV_CODEC_ID_ADPCM_IMA_DK4:

        for (channel = 0; channel < avctx->channels; channel++) {

            cs = &c->status[channel];

            cs->predictor  = *samples++ = sign_extend(bytestream2_get_le16u(&gb), 16);

            cs->step_index = sign_extend(bytestream2_get_le16u(&gb), 16);

            if (cs->step_index > 88u){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index[%d] = %i\n",

                       channel, cs->step_index);

                return AVERROR_INVALIDDATA;

            }

        }

        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int v = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0 ], v >> 4  , 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v & 0x0F, 3);

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_DK3:

    {

        int last_byte = 0;

        int nibble;

        int decode_top_nibble_next = 0;

        int diff_channel;

        const int16_t *samples_end = samples + avctx->channels * nb_samples;



        bytestream2_skipu(&gb, 10);

        c->status[0].predictor  = sign_extend(bytestream2_get_le16u(&gb), 16);

        c->status[1].predictor  = sign_extend(bytestream2_get_le16u(&gb), 16);

        c->status[0].step_index = bytestream2_get_byteu(&gb);

        c->status[1].step_index = bytestream2_get_byteu(&gb);

        if (c->status[0].step_index > 88u || c->status[1].step_index > 88u){

            av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i/%i\n",

                   c->status[0].step_index, c->status[1].step_index);

            return AVERROR_INVALIDDATA;

        }

        /* sign extend the predictors */

        diff_channel = c->status[1].predictor;



        /* DK3 ADPCM support macro */

#define DK3_GET_NEXT_NIBBLE() \

    if (decode_top_nibble_next) { \

        nibble = last_byte >> 4; \

        decode_top_nibble_next = 0; \

    } else { \

        last_byte = bytestream2_get_byteu(&gb); \

        nibble = last_byte & 0x0F; \

        decode_top_nibble_next = 1; \

    }



        while (samples < samples_end) {



            /* for this algorithm, c->status[0] is the sum channel and

             * c->status[1] is the diff channel */



            /* process the first predictor of the sum channel */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[0], nibble, 3);



            /* process the diff channel predictor */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[1], nibble, 3);



            /* process the first pair of stereo PCM samples */

            diff_channel = (diff_channel + c->status[1].predictor) / 2;

            *samples++ = c->status[0].predictor + c->status[1].predictor;

            *samples++ = c->status[0].predictor - c->status[1].predictor;



            /* process the second predictor of the sum channel */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[0], nibble, 3);



            /* process the second pair of stereo PCM samples */

            diff_channel = (diff_channel + c->status[1].predictor) / 2;

            *samples++ = c->status[0].predictor + c->status[1].predictor;

            *samples++ = c->status[0].predictor - c->status[1].predictor;

        }

        break;

    }

    case AV_CODEC_ID_ADPCM_IMA_ISS:

        for (channel = 0; channel < avctx->channels; channel++) {

            cs = &c->status[channel];

            cs->predictor  = sign_extend(bytestream2_get_le16u(&gb), 16);

            cs->step_index = sign_extend(bytestream2_get_le16u(&gb), 16);

            if (cs->step_index > 88u){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index[%d] = %i\n",

                       channel, cs->step_index);

                return AVERROR_INVALIDDATA;

            }

        }



        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int v1, v2;

            int v = bytestream2_get_byteu(&gb);

            /* nibbles are swapped for mono */

            if (st) {

                v1 = v >> 4;

                v2 = v & 0x0F;

            } else {

                v2 = v >> 4;

                v1 = v & 0x0F;

            }

            *samples++ = adpcm_ima_expand_nibble(&c->status[0 ], v1, 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v2, 3);

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_APC:

        while (bytestream2_get_bytes_left(&gb) > 0) {

            int v = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  v >> 4  , 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v & 0x0F, 3);

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_OKI:

        while (bytestream2_get_bytes_left(&gb) > 0) {

            int v = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ima_oki_expand_nibble(&c->status[0],  v >> 4  );

            *samples++ = adpcm_ima_oki_expand_nibble(&c->status[st], v & 0x0F);

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_WS:

        if (c->vqa_version == 3) {

            for (channel = 0; channel < avctx->channels; channel++) {

                int16_t *smp = samples_p[channel];



                for (n = nb_samples / 2; n > 0; n--) {

                    int v = bytestream2_get_byteu(&gb);

                    *smp++ = adpcm_ima_expand_nibble(&c->status[channel], v >> 4  , 3);

                    *smp++ = adpcm_ima_expand_nibble(&c->status[channel], v & 0x0F, 3);

                }

            }

        } else {

            for (n = nb_samples / 2; n > 0; n--) {

                for (channel = 0; channel < avctx->channels; channel++) {

                    int v = bytestream2_get_byteu(&gb);

                    *samples++  = adpcm_ima_expand_nibble(&c->status[channel], v >> 4  , 3);

                    samples[st] = adpcm_ima_expand_nibble(&c->status[channel], v & 0x0F, 3);

                }

                samples += avctx->channels;

            }

        }

        bytestream2_seek(&gb, 0, SEEK_END);

        break;

    case AV_CODEC_ID_ADPCM_XA:

    {

        int16_t *out0 = samples_p[0];

        int16_t *out1 = samples_p[1];

        int samples_per_block = 28 * (3 - avctx->channels) * 4;

        int sample_offset = 0;

        while (bytestream2_get_bytes_left(&gb) >= 128) {

            if ((ret = xa_decode(avctx, out0, out1, buf + bytestream2_tell(&gb),

                                 &c->status[0], &c->status[1],

                                 avctx->channels, sample_offset)) < 0)

                return ret;

            bytestream2_skipu(&gb, 128);

            sample_offset += samples_per_block;

        }

        break;

    }

    case AV_CODEC_ID_ADPCM_IMA_EA_EACS:

        for (i=0; i<=st; i++) {

            c->status[i].step_index = bytestream2_get_le32u(&gb);

            if (c->status[i].step_index > 88u) {

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index[%d] = %i\n",

                       i, c->status[i].step_index);

                return AVERROR_INVALIDDATA;

            }

        }

        for (i=0; i<=st; i++)

            c->status[i].predictor  = bytestream2_get_le32u(&gb);



        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int byte   = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  byte >> 4,   3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], byte & 0x0F, 3);

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_EA_SEAD:

        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int byte = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  byte >> 4,   6);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], byte & 0x0F, 6);

        }

        break;

    case AV_CODEC_ID_ADPCM_EA:

    {

        int previous_left_sample, previous_right_sample;

        int current_left_sample, current_right_sample;

        int next_left_sample, next_right_sample;

        int coeff1l, coeff2l, coeff1r, coeff2r;

        int shift_left, shift_right;



        /* Each EA ADPCM frame has a 12-byte header followed by 30-byte pieces,

           each coding 28 stereo samples. */



        if(avctx->channels != 2)

            return AVERROR_INVALIDDATA;



        current_left_sample   = sign_extend(bytestream2_get_le16u(&gb), 16);

        previous_left_sample  = sign_extend(bytestream2_get_le16u(&gb), 16);

        current_right_sample  = sign_extend(bytestream2_get_le16u(&gb), 16);

        previous_right_sample = sign_extend(bytestream2_get_le16u(&gb), 16);



        for (count1 = 0; count1 < nb_samples / 28; count1++) {

            int byte = bytestream2_get_byteu(&gb);

            coeff1l = ea_adpcm_table[ byte >> 4       ];

            coeff2l = ea_adpcm_table[(byte >> 4  ) + 4];

            coeff1r = ea_adpcm_table[ byte & 0x0F];

            coeff2r = ea_adpcm_table[(byte & 0x0F) + 4];



            byte = bytestream2_get_byteu(&gb);

            shift_left  = 20 - (byte >> 4);

            shift_right = 20 - (byte & 0x0F);



            for (count2 = 0; count2 < 28; count2++) {

                byte = bytestream2_get_byteu(&gb);

                next_left_sample  = sign_extend(byte >> 4, 4) << shift_left;

                next_right_sample = sign_extend(byte,      4) << shift_right;



                next_left_sample = (next_left_sample +

                    (current_left_sample * coeff1l) +

                    (previous_left_sample * coeff2l) + 0x80) >> 8;

                next_right_sample = (next_right_sample +

                    (current_right_sample * coeff1r) +

                    (previous_right_sample * coeff2r) + 0x80) >> 8;



                previous_left_sample = current_left_sample;

                current_left_sample = av_clip_int16(next_left_sample);

                previous_right_sample = current_right_sample;

                current_right_sample = av_clip_int16(next_right_sample);

                *samples++ = current_left_sample;

                *samples++ = current_right_sample;

            }

        }



        bytestream2_skip(&gb, 2); // Skip terminating 0x0000



        break;

    }

    case AV_CODEC_ID_ADPCM_EA_MAXIS_XA:

    {

        int coeff[2][2], shift[2];



        for(channel = 0; channel < avctx->channels; channel++) {

            int byte = bytestream2_get_byteu(&gb);

            for (i=0; i<2; i++)

                coeff[channel][i] = ea_adpcm_table[(byte >> 4) + 4*i];

            shift[channel] = 20 - (byte & 0x0F);

        }

        for (count1 = 0; count1 < nb_samples / 2; count1++) {

            int byte[2];



            byte[0] = bytestream2_get_byteu(&gb);

            if (st) byte[1] = bytestream2_get_byteu(&gb);

            for(i = 4; i >= 0; i-=4) { /* Pairwise samples LL RR (st) or LL LL (mono) */

                for(channel = 0; channel < avctx->channels; channel++) {

                    int sample = sign_extend(byte[channel] >> i, 4) << shift[channel];

                    sample = (sample +

                             c->status[channel].sample1 * coeff[channel][0] +

                             c->status[channel].sample2 * coeff[channel][1] + 0x80) >> 8;

                    c->status[channel].sample2 = c->status[channel].sample1;

                    c->status[channel].sample1 = av_clip_int16(sample);

                    *samples++ = c->status[channel].sample1;

                }

            }

        }

        bytestream2_seek(&gb, 0, SEEK_END);

        break;

    }

    case AV_CODEC_ID_ADPCM_EA_R1:

    case AV_CODEC_ID_ADPCM_EA_R2:

    case AV_CODEC_ID_ADPCM_EA_R3: {

        /* channel numbering

           2chan: 0=fl, 1=fr

           4chan: 0=fl, 1=rl, 2=fr, 3=rr

           6chan: 0=fl, 1=c,  2=fr, 3=rl,  4=rr, 5=sub */

        const int big_endian = avctx->codec->id == AV_CODEC_ID_ADPCM_EA_R3;

        int previous_sample, current_sample, next_sample;

        int coeff1, coeff2;

        int shift;

        unsigned int channel;

        uint16_t *samplesC;

        int count = 0;

        int offsets[6];



        for (channel=0; channel<avctx->channels; channel++)

            offsets[channel] = (big_endian ? bytestream2_get_be32(&gb) :

                                             bytestream2_get_le32(&gb)) +

                               (avctx->channels + 1) * 4;



        for (channel=0; channel<avctx->channels; channel++) {

            bytestream2_seek(&gb, offsets[channel], SEEK_SET);

            samplesC = samples_p[channel];



            if (avctx->codec->id == AV_CODEC_ID_ADPCM_EA_R1) {

                current_sample  = sign_extend(bytestream2_get_le16(&gb), 16);

                previous_sample = sign_extend(bytestream2_get_le16(&gb), 16);

            } else {

                current_sample  = c->status[channel].predictor;

                previous_sample = c->status[channel].prev_sample;

            }



            for (count1 = 0; count1 < nb_samples / 28; count1++) {

                int byte = bytestream2_get_byte(&gb);

                if (byte == 0xEE) {  /* only seen in R2 and R3 */

                    current_sample  = sign_extend(bytestream2_get_be16(&gb), 16);

                    previous_sample = sign_extend(bytestream2_get_be16(&gb), 16);



                    for (count2=0; count2<28; count2++)

                        *samplesC++ = sign_extend(bytestream2_get_be16(&gb), 16);

                } else {

                    coeff1 = ea_adpcm_table[ byte >> 4     ];

                    coeff2 = ea_adpcm_table[(byte >> 4) + 4];

                    shift = 20 - (byte & 0x0F);



                    for (count2=0; count2<28; count2++) {

                        if (count2 & 1)

                            next_sample = sign_extend(byte,    4) << shift;

                        else {

                            byte = bytestream2_get_byte(&gb);

                            next_sample = sign_extend(byte >> 4, 4) << shift;

                        }



                        next_sample += (current_sample  * coeff1) +

                                       (previous_sample * coeff2);

                        next_sample = av_clip_int16(next_sample >> 8);



                        previous_sample = current_sample;

                        current_sample  = next_sample;

                        *samplesC++ = current_sample;

                    }

                }

            }

            if (!count) {

                count = count1;

            } else if (count != count1) {

                av_log(avctx, AV_LOG_WARNING, "per-channel sample count mismatch\n");

                count = FFMAX(count, count1);

            }



            if (avctx->codec->id != AV_CODEC_ID_ADPCM_EA_R1) {

                c->status[channel].predictor   = current_sample;

                c->status[channel].prev_sample = previous_sample;

            }

        }



        c->frame.nb_samples = count * 28;

        bytestream2_seek(&gb, 0, SEEK_END);

        break;

    }

    case AV_CODEC_ID_ADPCM_EA_XAS:

        for (channel=0; channel<avctx->channels; channel++) {

            int coeff[2][4], shift[4];

            int16_t *s = samples_p[channel];

            for (n = 0; n < 4; n++, s += 32) {

                int val = sign_extend(bytestream2_get_le16u(&gb), 16);

                for (i=0; i<2; i++)

                    coeff[i][n] = ea_adpcm_table[(val&0x0F)+4*i];

                s[0] = val & ~0x0F;



                val = sign_extend(bytestream2_get_le16u(&gb), 16);

                shift[n] = 20 - (val & 0x0F);

                s[1] = val & ~0x0F;

            }



            for (m=2; m<32; m+=2) {

                s = &samples_p[channel][m];

                for (n = 0; n < 4; n++, s += 32) {

                    int level, pred;

                    int byte = bytestream2_get_byteu(&gb);



                    level = sign_extend(byte >> 4, 4) << shift[n];

                    pred  = s[-1] * coeff[0][n] + s[-2] * coeff[1][n];

                    s[0]  = av_clip_int16((level + pred + 0x80) >> 8);



                    level = sign_extend(byte, 4) << shift[n];

                    pred  = s[0] * coeff[0][n] + s[-1] * coeff[1][n];

                    s[1]  = av_clip_int16((level + pred + 0x80) >> 8);

                }

            }

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_AMV:

        c->status[0].predictor = sign_extend(bytestream2_get_le16u(&gb), 16);

        c->status[0].step_index = bytestream2_get_le16u(&gb);

        bytestream2_skipu(&gb, 4);

        if (c->status[0].step_index > 88u) {

            av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i\n",

                   c->status[0].step_index);

            return AVERROR_INVALIDDATA;

        }



        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int v = bytestream2_get_byteu(&gb);



            *samples++ = adpcm_ima_expand_nibble(&c->status[0], v >> 4, 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0], v & 0xf, 3);

        }

        break;

    case AV_CODEC_ID_ADPCM_IMA_SMJPEG:

        for (i = 0; i < avctx->channels; i++) {

            c->status[i].predictor = sign_extend(bytestream2_get_be16u(&gb), 16);

            c->status[i].step_index = bytestream2_get_byteu(&gb);

            bytestream2_skipu(&gb, 1);

            if (c->status[i].step_index > 88u) {

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i\n",

                       c->status[i].step_index);

                return AVERROR_INVALIDDATA;

            }

        }



        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int v = bytestream2_get_byteu(&gb);



            *samples++ = adpcm_ima_qt_expand_nibble(&c->status[0 ], v >> 4, 3);

            *samples++ = adpcm_ima_qt_expand_nibble(&c->status[st], v & 0xf, 3);

        }

        break;

    case AV_CODEC_ID_ADPCM_CT:

        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int v = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_ct_expand_nibble(&c->status[0 ], v >> 4  );

            *samples++ = adpcm_ct_expand_nibble(&c->status[st], v & 0x0F);

        }

        break;

    case AV_CODEC_ID_ADPCM_SBPRO_4:

    case AV_CODEC_ID_ADPCM_SBPRO_3:

    case AV_CODEC_ID_ADPCM_SBPRO_2:

        if (!c->status[0].step_index) {

            /* the first byte is a raw sample */

            *samples++ = 128 * (bytestream2_get_byteu(&gb) - 0x80);

            if (st)

                *samples++ = 128 * (bytestream2_get_byteu(&gb) - 0x80);

            c->status[0].step_index = 1;

            nb_samples--;

        }

        if (avctx->codec->id == AV_CODEC_ID_ADPCM_SBPRO_4) {

            for (n = nb_samples >> (1 - st); n > 0; n--) {

                int byte = bytestream2_get_byteu(&gb);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                                                       byte >> 4,   4, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                                                       byte & 0x0F, 4, 0);

            }

        } else if (avctx->codec->id == AV_CODEC_ID_ADPCM_SBPRO_3) {

            for (n = nb_samples / 3; n > 0; n--) {

                int byte = bytestream2_get_byteu(&gb);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                                                        byte >> 5        , 3, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                                                       (byte >> 2) & 0x07, 3, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                                                        byte & 0x03,       2, 0);

            }

        } else {

            for (n = nb_samples >> (2 - st); n > 0; n--) {

                int byte = bytestream2_get_byteu(&gb);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                                                        byte >> 6        , 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                                                       (byte >> 4) & 0x03, 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                                                       (byte >> 2) & 0x03, 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                                                        byte & 0x03,       2, 2);

            }

        }

        break;

    case AV_CODEC_ID_ADPCM_SWF:

        adpcm_swf_decode(avctx, buf, buf_size, samples);

        bytestream2_seek(&gb, 0, SEEK_END);

        break;

    case AV_CODEC_ID_ADPCM_YAMAHA:

        for (n = nb_samples >> (1 - st); n > 0; n--) {

            int v = bytestream2_get_byteu(&gb);

            *samples++ = adpcm_yamaha_expand_nibble(&c->status[0 ], v & 0x0F);

            *samples++ = adpcm_yamaha_expand_nibble(&c->status[st], v >> 4  );

        }

        break;

    case AV_CODEC_ID_ADPCM_AFC:

    {

        int samples_per_block;

        int blocks;



        if (avctx->extradata && avctx->extradata_size == 1 && avctx->extradata[0]) {

            samples_per_block = avctx->extradata[0] / 16;

            blocks = nb_samples / avctx->extradata[0];

        } else {

            samples_per_block = nb_samples / 16;

            blocks = 1;

        }



        for (m = 0; m < blocks; m++) {

        for (channel = 0; channel < avctx->channels; channel++) {

            int prev1 = c->status[channel].sample1;

            int prev2 = c->status[channel].sample2;



            samples = samples_p[channel] + m * 16;

            /* Read in every sample for this channel.  */

            for (i = 0; i < samples_per_block; i++) {

                int byte = bytestream2_get_byteu(&gb);

                int scale = 1 << (byte >> 4);

                int index = byte & 0xf;

                int factor1 = ff_adpcm_afc_coeffs[0][index];

                int factor2 = ff_adpcm_afc_coeffs[1][index];



                /* Decode 16 samples.  */

                for (n = 0; n < 16; n++) {

                    int32_t sampledat;



                    if (n & 1) {

                        sampledat = sign_extend(byte, 4);

                    } else {

                        byte = bytestream2_get_byteu(&gb);

                        sampledat = sign_extend(byte >> 4, 4);

                    }



                    sampledat = ((prev1 * factor1 + prev2 * factor2) +

                                 ((sampledat * scale) << 11)) >> 11;

                    *samples = av_clip_int16(sampledat);

                    prev2 = prev1;

                    prev1 = *samples++;

                }

            }



            c->status[channel].sample1 = prev1;

            c->status[channel].sample2 = prev2;

        }

        }

        bytestream2_seek(&gb, 0, SEEK_END);

        break;

    }

    case AV_CODEC_ID_ADPCM_THP:

    {

        int table[6][16];

        int ch;



        for (i = 0; i < avctx->channels; i++)

            for (n = 0; n < 16; n++)

                table[i][n] = sign_extend(bytestream2_get_be16u(&gb), 16);



        /* Initialize the previous sample.  */

        for (i = 0; i < avctx->channels; i++) {

            c->status[i].sample1 = sign_extend(bytestream2_get_be16u(&gb), 16);

            c->status[i].sample2 = sign_extend(bytestream2_get_be16u(&gb), 16);

        }



        for (ch = 0; ch < avctx->channels; ch++) {

            samples = samples_p[ch];



            /* Read in every sample for this channel.  */

            for (i = 0; i < nb_samples / 14; i++) {

                int byte = bytestream2_get_byteu(&gb);

                int index = (byte >> 4) & 7;

                unsigned int exp = byte & 0x0F;

                int factor1 = table[ch][index * 2];

                int factor2 = table[ch][index * 2 + 1];



                /* Decode 14 samples.  */

                for (n = 0; n < 14; n++) {

                    int32_t sampledat;



                    if (n & 1) {

                        sampledat = sign_extend(byte, 4);

                    } else {

                        byte = bytestream2_get_byteu(&gb);

                        sampledat = sign_extend(byte >> 4, 4);

                    }



                    sampledat = ((c->status[ch].sample1 * factor1

                                + c->status[ch].sample2 * factor2) >> 11) + (sampledat << exp);

                    *samples = av_clip_int16(sampledat);

                    c->status[ch].sample2 = c->status[ch].sample1;

                    c->status[ch].sample1 = *samples++;

                }

            }

        }

        break;

    }



    default:

        return -1;

    }



    if (avpkt->size && bytestream2_tell(&gb) == 0) {

        av_log(avctx, AV_LOG_ERROR, "Nothing consumed\n");

        return AVERROR_INVALIDDATA;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return bytestream2_tell(&gb);

}

static int tta_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    TTAContext *s = avctx->priv_data;

    int i, ret;

    int cur_chan = 0, framelen = s->frame_length;

    int32_t *p;



    if (avctx->err_recognition & AV_EF_CRCCHECK) {

        if (buf_size < 4 || tta_check_crc(s, buf, buf_size - 4))

            return AVERROR_INVALIDDATA;

    }



    init_get_bits(&s->gb, buf, buf_size*8);



    // FIXME: seeking

    s->total_frames--;

    if (!s->total_frames && s->last_frame_length)

        framelen = s->last_frame_length;



    /* get output buffer */

    s->frame.nb_samples = framelen;

    if ((ret = ff_get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    // decode directly to output buffer for 24-bit sample format

    if (s->bps == 3)

        s->decode_buffer = (int32_t *)s->frame.data[0];



    // init per channel states

    for (i = 0; i < s->channels; i++) {

        s->ch_ctx[i].predictor = 0;

        ttafilter_init(&s->ch_ctx[i].filter, ttafilter_configs[s->bps-1]);

        rice_init(&s->ch_ctx[i].rice, 10, 10);

    }



    for (p = s->decode_buffer; p < s->decode_buffer + (framelen * s->channels); p++) {

        int32_t *predictor = &s->ch_ctx[cur_chan].predictor;

        TTAFilter *filter = &s->ch_ctx[cur_chan].filter;

        TTARice *rice = &s->ch_ctx[cur_chan].rice;

        uint32_t unary, depth, k;

        int32_t value;



        unary = tta_get_unary(&s->gb);



        if (unary == 0) {

            depth = 0;

            k = rice->k0;

        } else {

            depth = 1;

            k = rice->k1;

            unary--;

        }



        if (get_bits_left(&s->gb) < k) {

            ret = AVERROR_INVALIDDATA;

            goto error;

        }



        if (k) {

            if (k > MIN_CACHE_BITS) {

                ret = AVERROR_INVALIDDATA;

                goto error;

            }

            value = (unary << k) + get_bits(&s->gb, k);

        } else

            value = unary;



        // FIXME: copy paste from original

        switch (depth) {

        case 1:

            rice->sum1 += value - (rice->sum1 >> 4);

            if (rice->k1 > 0 && rice->sum1 < shift_16[rice->k1])

                rice->k1--;

            else if(rice->sum1 > shift_16[rice->k1 + 1])

                rice->k1++;

            value += shift_1[rice->k0];

        default:

            rice->sum0 += value - (rice->sum0 >> 4);

            if (rice->k0 > 0 && rice->sum0 < shift_16[rice->k0])

                rice->k0--;

            else if(rice->sum0 > shift_16[rice->k0 + 1])

                rice->k0++;

        }



        // extract coded value

        *p = 1 + ((value >> 1) ^ ((value & 1) - 1));



        // run hybrid filter

        ttafilter_process(filter, p);



        // fixed order prediction

#define PRED(x, k) (int32_t)((((uint64_t)x << k) - x) >> k)

        switch (s->bps) {

        case 1: *p += PRED(*predictor, 4); break;

        case 2:

        case 3: *p += PRED(*predictor, 5); break;

        case 4: *p +=      *predictor;     break;

        }

        *predictor = *p;



        // flip channels

        if (cur_chan < (s->channels-1))

            cur_chan++;

        else {

            // decorrelate in case of multiple channels

            if (s->channels > 1) {

                int32_t *r = p - 1;

                for (*p += *r / 2; r > p - s->channels; r--)

                    *r = *(r + 1) - *r;

            }

            cur_chan = 0;

        }

    }



    if (get_bits_left(&s->gb) < 32) {

        ret = AVERROR_INVALIDDATA;

        goto error;

    }

    skip_bits_long(&s->gb, 32); // frame crc



    // convert to output buffer

    if (s->bps == 2) {

        int16_t *samples = (int16_t *)s->frame.data[0];

        for (p = s->decode_buffer; p < s->decode_buffer + (framelen * s->channels); p++)

            *samples++ = *p;

    } else {

        // shift samples for 24-bit sample format

        int32_t *samples = (int32_t *)s->frame.data[0];

        for (i = 0; i < framelen * s->channels; i++)

            *samples++ <<= 8;

        // reset decode buffer

        s->decode_buffer = NULL;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

error:

    // reset decode buffer

    if (s->bps == 3)

        s->decode_buffer = NULL;

    return ret;

}

static void cpu_ioreq_move(ioreq_t *req)

{

    int i, sign;



    sign = req->df ? -1 : 1;



    if (!req->data_is_ptr) {

        if (req->dir == IOREQ_READ) {

            for (i = 0; i < req->count; i++) {

                cpu_physical_memory_read(

                        req->addr + (sign * i * (int64_t)req->size),

                        (uint8_t *) &req->data, req->size);

            }

        } else if (req->dir == IOREQ_WRITE) {

            for (i = 0; i < req->count; i++) {

                cpu_physical_memory_write(

                        req->addr + (sign * i * (int64_t)req->size),

                        (uint8_t *) &req->data, req->size);

            }

        }

    } else {

        uint64_t tmp;



        if (req->dir == IOREQ_READ) {

            for (i = 0; i < req->count; i++) {

                cpu_physical_memory_read(

                        req->addr + (sign * i * (int64_t)req->size),

                        (uint8_t*) &tmp, req->size);

                cpu_physical_memory_write(

                        req->data + (sign * i * (int64_t)req->size),

                        (uint8_t*) &tmp, req->size);

            }

        } else if (req->dir == IOREQ_WRITE) {

            for (i = 0; i < req->count; i++) {

                cpu_physical_memory_read(

                        req->data + (sign * i * (int64_t)req->size),

                        (uint8_t*) &tmp, req->size);

                cpu_physical_memory_write(

                        req->addr + (sign * i * (int64_t)req->size),

                        (uint8_t*) &tmp, req->size);

            }

        }

    }

}

static void vnc_write_pixels_generic(VncState *vs, void *pixels1, int size)

{

    uint8_t buf[4];



    if (vs->depth == 4) {

        uint32_t *pixels = pixels1;

        int n, i;

        n = size >> 2;

        for(i = 0; i < n; i++) {

            vnc_convert_pixel(vs, buf, pixels[i]);

            vnc_write(vs, buf, vs->pix_bpp);

        }

    } else if (vs->depth == 2) {

        uint16_t *pixels = pixels1;

        int n, i;

        n = size >> 1;

        for(i = 0; i < n; i++) {

            vnc_convert_pixel(vs, buf, pixels[i]);

            vnc_write(vs, buf, vs->pix_bpp);

        }

    } else if (vs->depth == 1) {

        uint8_t *pixels = pixels1;

        int n, i;

        n = size;

        for(i = 0; i < n; i++) {

            vnc_convert_pixel(vs, buf, pixels[i]);

            vnc_write(vs, buf, vs->pix_bpp);

        }

    } else {

        fprintf(stderr, "vnc_write_pixels_generic: VncState color depth not supported\n");

    }

}

static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

        for (; i < count; i++)

            s->temp[0][2 * i    ] = s->temp[1][i] =

            s->temp[0][2 * i + 1] = s->temp[2][i] = 128;

    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static void mem_info_32(Monitor *mon, CPUState *env)

{

    int l1, l2, prot, last_prot;

    uint32_t pgd, pde, pte;

    target_phys_addr_t start, end;



    pgd = env->cr[3] & ~0xfff;

    last_prot = 0;

    start = -1;

    for(l1 = 0; l1 < 1024; l1++) {

        cpu_physical_memory_read(pgd + l1 * 4, &pde, 4);

        pde = le32_to_cpu(pde);

        end = l1 << 22;

        if (pde & PG_PRESENT_MASK) {

            if ((pde & PG_PSE_MASK) && (env->cr[4] & CR4_PSE_MASK)) {

                prot = pde & (PG_USER_MASK | PG_RW_MASK | PG_PRESENT_MASK);

                mem_print(mon, &start, &last_prot, end, prot);

            } else {

                for(l2 = 0; l2 < 1024; l2++) {

                    cpu_physical_memory_read((pde & ~0xfff) + l2 * 4, &pte, 4);

                    pte = le32_to_cpu(pte);

                    end = (l1 << 22) + (l2 << 12);

                    if (pte & PG_PRESENT_MASK) {

                        prot = pte & (PG_USER_MASK | PG_RW_MASK | PG_PRESENT_MASK);

                    } else {

                        prot = 0;

                    }

                    mem_print(mon, &start, &last_prot, end, prot);

                }

            }

        } else {

            prot = 0;

            mem_print(mon, &start, &last_prot, end, prot);

        }

    }

}

static char *choose_pix_fmts(OutputStream *ost)

{

     if (ost->keep_pix_fmt) {

        if (ost->filter)

            avfilter_graph_set_auto_convert(ost->filter->graph->graph,

                                            AVFILTER_AUTO_CONVERT_NONE);

        if (ost->st->codec->pix_fmt == PIX_FMT_NONE)

            return NULL;

        return av_strdup(av_get_pix_fmt_name(ost->st->codec->pix_fmt));

    }

    if (ost->st->codec->pix_fmt != PIX_FMT_NONE) {

        return av_strdup(av_get_pix_fmt_name(choose_pixel_fmt(ost->st, ost->enc, ost->st->codec->pix_fmt)));

    } else if (ost->enc->pix_fmts) {

        const enum PixelFormat *p;

        AVIOContext *s = NULL;

        uint8_t *ret;

        int len;



        if (avio_open_dyn_buf(&s) < 0)

            exit_program(1);



        p = ost->enc->pix_fmts;

        if (ost->st->codec->strict_std_compliance <= FF_COMPLIANCE_UNOFFICIAL) {

            if (ost->st->codec->codec_id == CODEC_ID_MJPEG) {

                p = (const enum PixelFormat[]) { PIX_FMT_YUVJ420P, PIX_FMT_YUVJ422P, PIX_FMT_YUV420P, PIX_FMT_YUV422P, PIX_FMT_NONE };

            } else if (ost->st->codec->codec_id == CODEC_ID_LJPEG) {

                p = (const enum PixelFormat[]) { PIX_FMT_YUVJ420P, PIX_FMT_YUVJ422P, PIX_FMT_YUVJ444P, PIX_FMT_YUV420P,

                                                    PIX_FMT_YUV422P, PIX_FMT_YUV444P, PIX_FMT_BGRA, PIX_FMT_NONE };

            }

        }



        for (; *p != PIX_FMT_NONE; p++) {

            const char *name = av_get_pix_fmt_name(*p);

            avio_printf(s, "%s:", name);

        }

        len = avio_close_dyn_buf(s, &ret);

        ret[len - 1] = 0;

        return ret;

    } else

        return NULL;

}

static int configure_video_filters(FilterGraph *fg)

{

    InputStream  *ist = fg->inputs[0]->ist;

    OutputStream *ost = fg->outputs[0]->ost;

    AVFilterContext *in_filter, *out_filter, *filter;

    AVCodecContext *codec = ost->st->codec;

    AVBufferSinkParams *buffersink_params = av_buffersink_params_alloc();

    char *pix_fmts;

    AVRational sample_aspect_ratio;

    char args[255];

    int ret;



    avfilter_graph_free(&fg->graph);

    fg->graph = avfilter_graph_alloc();

    if (!fg->graph)

        return AVERROR(ENOMEM);



    if (ist->st->sample_aspect_ratio.num) {

        sample_aspect_ratio = ist->st->sample_aspect_ratio;

    } else

        sample_aspect_ratio = ist->st->codec->sample_aspect_ratio;



    snprintf(args, 255, "%d:%d:%d:%d:%d:%d:%d:flags=%d", ist->st->codec->width,

             ist->st->codec->height, ist->st->codec->pix_fmt, 1, AV_TIME_BASE,

             sample_aspect_ratio.num, sample_aspect_ratio.den, SWS_BILINEAR + ((ist->st->codec->flags&CODEC_FLAG_BITEXACT) ? SWS_BITEXACT:0));



    ret = avfilter_graph_create_filter(&fg->inputs[0]->filter,

                                       avfilter_get_by_name("buffer"),

                                       "src", args, NULL, fg->graph);

    if (ret < 0)

        return ret;



#if FF_API_OLD_VSINK_API

    ret = avfilter_graph_create_filter(&fg->outputs[0]->filter,

                                       avfilter_get_by_name("buffersink"),

                                       "out", NULL, NULL, fg->graph);

#else

    ret = avfilter_graph_create_filter(&fg->outputs[0]->filter,

                                       avfilter_get_by_name("buffersink"),

                                       "out", NULL, buffersink_params, fg->graph);

#endif

    av_freep(&buffersink_params);



    if (ret < 0)

        return ret;

    in_filter  = fg->inputs[0]->filter;

    out_filter = fg->outputs[0]->filter;



    if (codec->width || codec->height) {

        snprintf(args, 255, "%d:%d:flags=0x%X",

                 codec->width,

                 codec->height,

                 (unsigned)ost->sws_flags);

        if ((ret = avfilter_graph_create_filter(&filter, avfilter_get_by_name("scale"),

                                                NULL, args, NULL, fg->graph)) < 0)

            return ret;

        if ((ret = avfilter_link(in_filter, 0, filter, 0)) < 0)

            return ret;

        in_filter = filter;

    }



    if ((pix_fmts = choose_pixel_fmts(ost))) {

        if ((ret = avfilter_graph_create_filter(&filter,

                                                avfilter_get_by_name("format"),

                                                "format", pix_fmts, NULL,

                                                fg->graph)) < 0)

            return ret;

        if ((ret = avfilter_link(filter, 0, out_filter, 0)) < 0)

            return ret;



        out_filter = filter;

        av_freep(&pix_fmts);

    }



    snprintf(args, sizeof(args), "flags=0x%X", (unsigned)ost->sws_flags);

    fg->graph->scale_sws_opts = av_strdup(args);



    if (ost->avfilter) {

        AVFilterInOut *outputs = avfilter_inout_alloc();

        AVFilterInOut *inputs  = avfilter_inout_alloc();



        outputs->name    = av_strdup("in");

        outputs->filter_ctx = in_filter;

        outputs->pad_idx = 0;

        outputs->next    = NULL;



        inputs->name    = av_strdup("out");

        inputs->filter_ctx = out_filter;

        inputs->pad_idx = 0;

        inputs->next    = NULL;



        if ((ret = avfilter_graph_parse(fg->graph, ost->avfilter, &inputs, &outputs, NULL)) < 0)

            return ret;

        av_freep(&ost->avfilter);

    } else {

        if ((ret = avfilter_link(in_filter, 0, out_filter, 0)) < 0)

            return ret;

    }



    if (ost->keep_pix_fmt)

        avfilter_graph_set_auto_convert(fg->graph,

                                        AVFILTER_AUTO_CONVERT_NONE);



    if ((ret = avfilter_graph_config(fg->graph, NULL)) < 0)

        return ret;



    ost->filter = fg->outputs[0];



    return 0;

}

static int is_allocated_sectors(const uint8_t *buf, int n, int *pnum)

{

    int v, i;



    if (n <= 0) {

        *pnum = 0;

        return 0;

    }

    v = is_not_zero(buf, 512);

    for(i = 1; i < n; i++) {

        buf += 512;

        if (v != is_not_zero(buf, 512))

            break;

    }

    *pnum = i;

    return v;

}

static void choose_pixel_fmt(AVStream *st, AVCodec *codec)

{

    if(codec && codec->pix_fmts){

        const enum PixelFormat *p= codec->pix_fmts;

        if(st->codec->strict_std_compliance <= FF_COMPLIANCE_UNOFFICIAL){

            if(st->codec->codec_id==CODEC_ID_MJPEG){

                p= (const enum PixelFormat[]){PIX_FMT_YUVJ420P, PIX_FMT_YUVJ422P, PIX_FMT_YUV420P, PIX_FMT_YUV422P, PIX_FMT_NONE};

            }else if(st->codec->codec_id==CODEC_ID_LJPEG){

                p= (const enum PixelFormat[]){PIX_FMT_YUVJ420P, PIX_FMT_YUVJ422P, PIX_FMT_YUVJ444P, PIX_FMT_YUV420P, PIX_FMT_YUV422P, PIX_FMT_YUV444P, PIX_FMT_BGRA, PIX_FMT_NONE};

            }

        }

        for(; *p!=-1; p++){

            if(*p == st->codec->pix_fmt)

                break;

        }

        if (*p == -1) {


            av_log(NULL, AV_LOG_WARNING,

                   "Incompatible pixel format '%s' for codec '%s', auto-selecting format '%s'\n",

                   av_pix_fmt_descriptors[st->codec->pix_fmt].name,

                   codec->name,

                   av_pix_fmt_descriptors[codec->pix_fmts[0]].name);

            st->codec->pix_fmt = codec->pix_fmts[0];

        }

    }

}

static void mov_metadata_creation_time(AVDictionary **metadata, int64_t time)
{
    if (time) {
        if(time >= 2082844800)
            time -= 2082844800;  /* seconds between 1904-01-01 and Epoch */
        avpriv_dict_set_timestamp(metadata, "creation_time", time * 1000000);

static void oledate_to_iso8601(char *buf, int buf_size, int64_t value)

{

    time_t t = 631112400LL + 86400*av_int2dbl(value);

    strftime(buf, buf_size, "%Y-%m-%d %H:%M:%S", gmtime(&t));

}

static int opt_recording_timestamp(void *optctx, const char *opt, const char *arg)

{

    OptionsContext *o = optctx;

    char buf[128];

    int64_t recording_timestamp = parse_time_or_die(opt, arg, 0) / 1E6;

    struct tm time = *gmtime((time_t*)&recording_timestamp);

    strftime(buf, sizeof(buf), "creation_time=%FT%T%z", &time);

    parse_option(o, "metadata", buf, options);



    av_log(NULL, AV_LOG_WARNING, "%s is deprecated, set the 'creation_time' metadata "

                                 "tag instead.\n", opt);

    return 0;

}

