static void qpeg_decode_intra(const uint8_t *src, uint8_t *dst, int size,

                            int stride, int width, int height)

{

    int i;

    int code;

    int c0, c1;

    int run, copy;

    int filled = 0;

    int rows_to_go;



    rows_to_go = height;

    height--;

    dst = dst + height * stride;



    while((size > 0) && (rows_to_go > 0)) {

        code = *src++;

        size--;

        run = copy = 0;

        if(code == 0xFC) /* end-of-picture code */

            break;

        if(code >= 0xF8) { /* very long run */

            c0 = *src++;

            c1 = *src++;

            size -= 2;

            run = ((code & 0x7) << 16) + (c0 << 8) + c1 + 2;

        } else if (code >= 0xF0) { /* long run */

            c0 = *src++;

            size--;

            run = ((code & 0xF) << 8) + c0 + 2;

        } else if (code >= 0xE0) { /* short run */

            run = (code & 0x1F) + 2;

        } else if (code >= 0xC0) { /* very long copy */

            c0 = *src++;

            c1 = *src++;

            size -= 2;

            copy = ((code & 0x3F) << 16) + (c0 << 8) + c1 + 1;

        } else if (code >= 0x80) { /* long copy */

            c0 = *src++;

            size--;

            copy = ((code & 0x7F) << 8) + c0 + 1;

        } else { /* short copy */

            copy = code + 1;

        }



        /* perform actual run or copy */

        if(run) {

            int p;



            p = *src++;

            size--;

            for(i = 0; i < run; i++) {

                dst[filled++] = p;

                if (filled >= width) {

                    filled = 0;

                    dst -= stride;

                    rows_to_go--;

                    if(rows_to_go <= 0)

                        break;

                }

            }

        } else {

            size -= copy;

            for(i = 0; i < copy; i++) {

                dst[filled++] = *src++;

                if (filled >= width) {

                    filled = 0;

                    dst -= stride;

                    rows_to_go--;

                    if(rows_to_go <= 0)

                        break;

                }

            }

        }

    }

}

static void mpeg1_encode_sequence_header(MpegEncContext *s)

{

        unsigned int vbv_buffer_size;

        unsigned int fps, v;

        int i;

        uint64_t time_code;

        float best_aspect_error= 1E10;

        float aspect_ratio= av_q2d(s->avctx->sample_aspect_ratio);

        int constraint_parameter_flag;



        if(aspect_ratio==0.0) aspect_ratio= 1.0; //pixel aspect 1:1 (VGA)



        if (s->current_picture.key_frame) {

            AVRational framerate= frame_rate_tab[s->frame_rate_index];



            /* mpeg1 header repeated every gop */

            put_header(s, SEQ_START_CODE);



            put_bits(&s->pb, 12, s->width);

            put_bits(&s->pb, 12, s->height);



            for(i=1; i<15; i++){

                float error= aspect_ratio;

                if(s->codec_id == CODEC_ID_MPEG1VIDEO || i <=1)

                    error-= 1.0/mpeg1_aspect[i];

                else

                    error-= av_q2d(mpeg2_aspect[i])*s->height/s->width;



                error= ABS(error);



                if(error < best_aspect_error){

                    best_aspect_error= error;

                    s->aspect_ratio_info= i;

                }

            }



            put_bits(&s->pb, 4, s->aspect_ratio_info);

            put_bits(&s->pb, 4, s->frame_rate_index);



            if(s->avctx->rc_max_rate){

                v = (s->avctx->rc_max_rate + 399) / 400;

                if (v > 0x3ffff && s->codec_id == CODEC_ID_MPEG1VIDEO)

                    v = 0x3ffff;

            }else{

                v= 0x3FFFF;

            }



            if(s->avctx->rc_buffer_size)

                vbv_buffer_size = s->avctx->rc_buffer_size;

            else

                /* VBV calculation: Scaled so that a VCD has the proper VBV size of 40 kilobytes */

                vbv_buffer_size = (( 20 * s->bit_rate) / (1151929 / 2)) * 8 * 1024;

            vbv_buffer_size= (vbv_buffer_size + 16383) / 16384;



            put_bits(&s->pb, 18, v & 0x3FFFF);

            put_bits(&s->pb, 1, 1); /* marker */

            put_bits(&s->pb, 10, vbv_buffer_size & 0x3FF);



            constraint_parameter_flag= 

                s->width <= 768 && s->height <= 576 && 

                s->mb_width * s->mb_height <= 396 &&

                s->mb_width * s->mb_height * framerate.num <= framerate.den*396*25 &&

                framerate.num <= framerate.den*30 &&

                vbv_buffer_size <= 20 &&

                v <= 1856000/400 &&

                s->codec_id == CODEC_ID_MPEG1VIDEO;



            put_bits(&s->pb, 1, constraint_parameter_flag);



            ff_write_quant_matrix(&s->pb, s->avctx->intra_matrix);

            ff_write_quant_matrix(&s->pb, s->avctx->inter_matrix);



            if(s->codec_id == CODEC_ID_MPEG2VIDEO){

                put_header(s, EXT_START_CODE);

                put_bits(&s->pb, 4, 1); //seq ext

                put_bits(&s->pb, 1, 0); //esc

                put_bits(&s->pb, 3, 4); //profile

                put_bits(&s->pb, 4, 8); //level

                put_bits(&s->pb, 1, s->progressive_sequence);

                put_bits(&s->pb, 2, 1); //chroma format 4:2:0

                put_bits(&s->pb, 2, 0); //horizontal size ext

                put_bits(&s->pb, 2, 0); //vertical size ext

                put_bits(&s->pb, 12, v>>18); //bitrate ext

                put_bits(&s->pb, 1, 1); //marker

                put_bits(&s->pb, 8, vbv_buffer_size >>10); //vbv buffer ext

                put_bits(&s->pb, 1, s->low_delay);

                put_bits(&s->pb, 2, 0); // frame_rate_ext_n

                put_bits(&s->pb, 5, 0); // frame_rate_ext_d

            }



            put_header(s, GOP_START_CODE);

            put_bits(&s->pb, 1, 0); /* do drop frame */

            /* time code : we must convert from the real frame rate to a

               fake mpeg frame rate in case of low frame rate */

            fps = (framerate.num + framerate.den/2)/ framerate.den;

            time_code = s->current_picture_ptr->coded_picture_number;



            s->gop_picture_number = time_code;

            put_bits(&s->pb, 5, (uint32_t)((time_code / (fps * 3600)) % 24));

            put_bits(&s->pb, 6, (uint32_t)((time_code / (fps * 60)) % 60));

            put_bits(&s->pb, 1, 1);

            put_bits(&s->pb, 6, (uint32_t)((time_code / fps) % 60));

            put_bits(&s->pb, 6, (uint32_t)((time_code % fps)));

            put_bits(&s->pb, 1, !!(s->flags & CODEC_FLAG_CLOSED_GOP));

            put_bits(&s->pb, 1, 0); /* broken link */

        }

}

void mpeg1_encode_picture_header(MpegEncContext *s, int picture_number)

{

    mpeg1_encode_sequence_header(s);



    /* mpeg1 picture header */

    put_header(s, PICTURE_START_CODE);

    /* temporal reference */



    // RAL: s->picture_number instead of s->fake_picture_number

    put_bits(&s->pb, 10, (s->picture_number - 

                          s->gop_picture_number) & 0x3ff); 

    s->fake_picture_number++;



    put_bits(&s->pb, 3, s->pict_type);



    s->vbv_delay_ptr= s->pb.buf + get_bit_count(&s->pb)/8;

    put_bits(&s->pb, 16, 0xFFFF); /* vbv_delay */



    // RAL: Forward f_code also needed for B frames

    if (s->pict_type == P_TYPE || s->pict_type == B_TYPE) {

        put_bits(&s->pb, 1, 0); /* half pel coordinates */

        if(s->codec_id == CODEC_ID_MPEG1VIDEO)

            put_bits(&s->pb, 3, s->f_code); /* forward_f_code */

        else

            put_bits(&s->pb, 3, 7); /* forward_f_code */

    }



    // RAL: Backward f_code necessary for B frames

    if (s->pict_type == B_TYPE) {

        put_bits(&s->pb, 1, 0); /* half pel coordinates */

        if(s->codec_id == CODEC_ID_MPEG1VIDEO)

            put_bits(&s->pb, 3, s->b_code); /* backward_f_code */

        else

            put_bits(&s->pb, 3, 7); /* backward_f_code */

    }



    put_bits(&s->pb, 1, 0); /* extra bit picture */



    s->frame_pred_frame_dct = 1;

    if(s->codec_id == CODEC_ID_MPEG2VIDEO){

        put_header(s, EXT_START_CODE);

        put_bits(&s->pb, 4, 8); //pic ext

        if (s->pict_type == P_TYPE || s->pict_type == B_TYPE) {

            put_bits(&s->pb, 4, s->f_code);

            put_bits(&s->pb, 4, s->f_code);

        }else{

            put_bits(&s->pb, 8, 255);

        }

        if (s->pict_type == B_TYPE) {

            put_bits(&s->pb, 4, s->b_code);

            put_bits(&s->pb, 4, s->b_code);

        }else{

            put_bits(&s->pb, 8, 255);

        }

        put_bits(&s->pb, 2, s->intra_dc_precision);

        put_bits(&s->pb, 2, s->picture_structure= PICT_FRAME);

        if (s->progressive_sequence) {

            put_bits(&s->pb, 1, 0); /* no repeat */

        } else {

            put_bits(&s->pb, 1, s->current_picture_ptr->top_field_first);

        }

        /* XXX: optimize the generation of this flag with entropy

           measures */

        s->frame_pred_frame_dct = s->progressive_sequence;



        put_bits(&s->pb, 1, s->frame_pred_frame_dct);

        put_bits(&s->pb, 1, s->concealment_motion_vectors);

        put_bits(&s->pb, 1, s->q_scale_type);

        put_bits(&s->pb, 1, s->intra_vlc_format);

        put_bits(&s->pb, 1, s->alternate_scan);

        put_bits(&s->pb, 1, s->repeat_first_field);

        put_bits(&s->pb, 1, s->chroma_420_type=1);

        s->progressive_frame = s->progressive_sequence;

        put_bits(&s->pb, 1, s->progressive_frame);

        put_bits(&s->pb, 1, 0); //composite_display_flag

    }

    if(s->flags & CODEC_FLAG_SVCD_SCAN_OFFSET){

        int i;



        put_header(s, USER_START_CODE);

        for(i=0; i<sizeof(svcd_scan_offset_placeholder); i++){

            put_bits(&s->pb, 8, svcd_scan_offset_placeholder[i]);

        }

    }



    s->mb_y=0;

    ff_mpeg1_encode_slice_header(s);

}

