static int xwma_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    int64_t size, av_uninit(data_size);

    uint32_t dpds_table_size = 0;

    uint32_t *dpds_table = 0;

    unsigned int tag;

    AVIOContext *pb = s->pb;

    AVStream *st;

    XWMAContext *xwma = s->priv_data;

    int i;



    /* The following code is mostly copied from wav.c, with some

     * minor alterations.

     */



    /* check RIFF header */

    tag = avio_rl32(pb);

    if (tag != MKTAG('R', 'I', 'F', 'F'))

        return -1;

    avio_rl32(pb); /* file size */

    tag = avio_rl32(pb);

    if (tag != MKTAG('X', 'W', 'M', 'A'))

        return -1;



    /* parse fmt header */

    tag = avio_rl32(pb);

    if (tag != MKTAG('f', 'm', 't', ' '))

        return -1;

    size = avio_rl32(pb);

    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    ff_get_wav_header(pb, st->codec, size);

    st->need_parsing = AVSTREAM_PARSE_NONE;



    /* All xWMA files I have seen contained WMAv2 data. If there are files

     * using WMA Pro or some other codec, then we need to figure out the right

     * extradata for that. Thus, ask the user for feedback, but try to go on

     * anyway.

     */

    if (st->codec->codec_id != CODEC_ID_WMAV2) {

        av_log(s, AV_LOG_WARNING, "unexpected codec (tag 0x04%x; id %d)\n",

                              st->codec->codec_tag, st->codec->codec_id);

        av_log_ask_for_sample(s, NULL);

    } else {

        /* In all xWMA files I have seen, there is no extradata. But the WMA

         * codecs require extradata, so we provide our own fake extradata.

         *

         * First, check that there really was no extradata in the header. If

         * there was, then try to use, after asking the the user to provide a

         * sample of this unusual file.

         */

        if (st->codec->extradata_size != 0) {

            /* Surprise, surprise: We *did* get some extradata. No idea

             * if it will work, but just go on and try it, after asking

             * the user for a sample.

             */

            av_log(s, AV_LOG_WARNING, "unexpected extradata (%d bytes)\n",

                                  st->codec->extradata_size);

            av_log_ask_for_sample(s, NULL);

        } else {

            st->codec->extradata_size = 6;

            st->codec->extradata      = av_mallocz(6 + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!st->codec->extradata)

                return AVERROR(ENOMEM);



            /* setup extradata with our experimentally obtained value */

            st->codec->extradata[4] = 31;

        }

    }



    /* set the sample rate */

    av_set_pts_info(st, 64, 1, st->codec->sample_rate);



    /* parse the remaining RIFF chunks */

    for (;;) {

        if (pb->eof_reached)

            return -1;

        /* read next chunk tag */

        tag = avio_rl32(pb);

        size = avio_rl32(pb);

        if (tag == MKTAG('d', 'a', 't', 'a')) {

            /* We assume that the data chunk comes last. */

            break;

        } else if (tag == MKTAG('d','p','d','s')) {

            /* Quoting the MSDN xWMA docs on the dpds chunk: "Contains the

             * decoded packet cumulative data size array, each element is the

             * number of bytes accumulated after the corresponding xWMA packet

             * is decoded in order"

             *

             * Each packet has size equal to st->codec->block_align, which in

             * all cases I saw so far was always 2230. Thus, we can use the

             * dpds data to compute a seeking index.

             */



            /* Error out if there is more than one dpds chunk. */

            if (dpds_table) {

                av_log(s, AV_LOG_ERROR, "two dpds chunks present\n");

                return -1;

            }



            /* Compute the number of entries in the dpds chunk. */

            if (size & 3) {  /* Size should be divisible by four */

                av_log(s, AV_LOG_WARNING, "dpds chunk size "PRId64" not divisible by 4\n", size);

            }

            dpds_table_size = size / 4;

            if (dpds_table_size == 0 || dpds_table_size >= INT_MAX / 4) {

                av_log(s, AV_LOG_ERROR, "dpds chunk size "PRId64" invalid\n", size);

                return -1;

            }



            /* Allocate some temporary storage to keep the dpds data around.

             * for processing later on.

             */

            dpds_table = av_malloc(dpds_table_size * sizeof(uint32_t));

            if (!dpds_table) {

                return AVERROR(ENOMEM);

            }



            for (i = 0; i < dpds_table_size; ++i) {

                dpds_table[i] = avio_rl32(pb);

                size -= 4;

            }

        }

        avio_skip(pb, size);

    }



    /* Determine overall data length */

    if (size < 0)

        return -1;

    if (!size) {

        xwma->data_end = INT64_MAX;

    } else

        xwma->data_end = avio_tell(pb) + size;





    if (dpds_table && dpds_table_size) {

        int64_t cur_pos;

        const uint32_t bytes_per_sample

                = (st->codec->channels * st->codec->bits_per_coded_sample) >> 3;



        /* Estimate the duration from the total number of output bytes. */

        const uint64_t total_decoded_bytes = dpds_table[dpds_table_size - 1];

        st->duration = total_decoded_bytes / bytes_per_sample;



        /* Use the dpds data to build a seek table.  We can only do this after

         * we know the offset to the data chunk, as we need that to determine

         * the actual offset to each input block.

         * Note: If we allowed ourselves to assume that the data chunk always

         * follows immediately after the dpds block, we could of course guess

         * the data block's start offset already while reading the dpds chunk.

         * I decided against that, just in case other chunks ever are

         * discovered.

         */

        cur_pos = avio_tell(pb);

        for (i = 0; i < dpds_table_size; ++i) {

            /* From the number of output bytes that would accumulate in the

             * output buffer after decoding the first (i+1) packets, we compute

             * an offset / timestamp pair.

             */

            av_add_index_entry(st,

                               cur_pos + (i+1) * st->codec->block_align, /* pos */

                               dpds_table[i] / bytes_per_sample,         /* timestamp */

                               st->codec->block_align,                   /* size */

                               0,                                        /* duration */

                               AVINDEX_KEYFRAME);

        }

    } else if (st->codec->bit_rate) {

        /* No dpds chunk was present (or only an empty one), so estimate

         * the total duration using the average bits per sample and the

         * total data length.

         */

        st->duration = (size<<3) * st->codec->sample_rate / st->codec->bit_rate;

    }



    av_free(dpds_table);



    return 0;

}

static int theora_header(AVFormatContext *s, int idx)
{
    struct ogg *ogg       = s->priv_data;
    struct ogg_stream *os = ogg->streams + idx;
    AVStream *st          = s->streams[idx];
    TheoraParams *thp     = os->private;
    int cds               = st->codec->extradata_size + os->psize + 2;
    int err;
    uint8_t *cdp;
    if (!(os->buf[os->pstart] & 0x80))
        return 0;
    if (!thp) {
        thp = av_mallocz(sizeof(*thp));
        if (!thp)
            return AVERROR(ENOMEM);
        os->private = thp;
    }
    switch (os->buf[os->pstart]) {
    case 0x80: {
        GetBitContext gb;
        AVRational timebase;
        init_get_bits(&gb, os->buf + os->pstart, os->psize * 8);
        /* 0x80"theora" */
        skip_bits_long(&gb, 7 * 8);
        thp->version = get_bits_long(&gb, 24);
        if (thp->version < 0x030100) {
            av_log(s, AV_LOG_ERROR,
                   "Too old or unsupported Theora (%x)\n", thp->version);
            return AVERROR(ENOSYS);
        }
        st->codec->width  = get_bits(&gb, 16) << 4;
        st->codec->height = get_bits(&gb, 16) << 4;
        if (thp->version >= 0x030400)
            skip_bits(&gb, 100);
        if (thp->version >= 0x030200) {
            int width  = get_bits_long(&gb, 24);
            int height = get_bits_long(&gb, 24);
            if (width  <= st->codec->width  && width  > st->codec->width  - 16 &&
                height <= st->codec->height && height > st->codec->height - 16) {
                st->codec->width  = width;
                st->codec->height = height;
            }
            skip_bits(&gb, 16);
        }
        timebase.den = get_bits_long(&gb, 32);
        timebase.num = get_bits_long(&gb, 32);
        if (!(timebase.num > 0 && timebase.den > 0)) {
            av_log(s, AV_LOG_WARNING, "Invalid time base in theora stream, assuming 25 FPS\n");
            timebase.num = 1;
            timebase.den = 25;
        }
        avpriv_set_pts_info(st, 64, timebase.num, timebase.den);
        st->sample_aspect_ratio.num = get_bits_long(&gb, 24);
        st->sample_aspect_ratio.den = get_bits_long(&gb, 24);
        if (thp->version >= 0x030200)
            skip_bits_long(&gb, 38);
        if (thp->version >= 0x304000)
            skip_bits(&gb, 2);
        thp->gpshift = get_bits(&gb, 5);
        thp->gpmask  = (1 << thp->gpshift) - 1;
        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;
        st->codec->codec_id   = AV_CODEC_ID_THEORA;
        st->need_parsing      = AVSTREAM_PARSE_HEADERS;
    }
    break;
    case 0x81:
        ff_vorbis_comment(s, &st->metadata, os->buf + os->pstart + 7, os->psize - 7);
    case 0x82:
        if (!thp->version)
            return AVERROR_INVALIDDATA;
        break;
    default:
        av_log(s, AV_LOG_ERROR, "Unknown header type %X\n", os->buf[os->pstart]);
        return AVERROR_INVALIDDATA;
    }
    if ((err = av_reallocp(&st->codec->extradata,
                           cds + FF_INPUT_BUFFER_PADDING_SIZE)) < 0) {
        st->codec->extradata_size = 0;
        return err;
    }
    cdp    = st->codec->extradata + st->codec->extradata_size;
    *cdp++ = os->psize >> 8;
    *cdp++ = os->psize & 0xff;
    memcpy(cdp, os->buf + os->pstart, os->psize);
    st->codec->extradata_size = cds;
    return 1;
}

static int mpeg_mux_init(AVFormatContext *ctx)

{

    MpegMuxContext *s = ctx->priv_data;

    int bitrate, i, mpa_id, mpv_id, mps_id, ac3_id, dts_id, lpcm_id, j;

    AVStream *st;

    StreamInfo *stream;

    int audio_bitrate;

    int video_bitrate;



    s->packet_number = 0;

    s->is_vcd =    (CONFIG_MPEG1VCD_MUXER  && ctx->oformat == &mpeg1vcd_muxer);

    s->is_svcd =   (CONFIG_MPEG2SVCD_MUXER && ctx->oformat == &mpeg2svcd_muxer);

    s->is_mpeg2 = ((CONFIG_MPEG2VOB_MUXER  && ctx->oformat == &mpeg2vob_muxer) ||

                   (CONFIG_MPEG2DVD_MUXER  && ctx->oformat == &mpeg2dvd_muxer) ||

                   (CONFIG_MPEG2SVCD_MUXER && ctx->oformat == &mpeg2svcd_muxer));

    s->is_dvd =    (CONFIG_MPEG2DVD_MUXER  && ctx->oformat == &mpeg2dvd_muxer);



    if(ctx->packet_size)

        s->packet_size = ctx->packet_size;

    else

        s->packet_size = 2048;



    s->vcd_padding_bytes_written = 0;

    s->vcd_padding_bitrate=0;



    s->audio_bound = 0;

    s->video_bound = 0;

    mpa_id = AUDIO_ID;

    ac3_id = AC3_ID;

    dts_id = DTS_ID;

    mpv_id = VIDEO_ID;

    mps_id = SUB_ID;

    lpcm_id = LPCM_ID;

    for(i=0;i<ctx->nb_streams;i++) {

        st = ctx->streams[i];

        stream = av_mallocz(sizeof(StreamInfo));

        if (!stream)

            goto fail;

        st->priv_data = stream;



        av_set_pts_info(st, 64, 1, 90000);



        switch(st->codec->codec_type) {

        case CODEC_TYPE_AUDIO:

            if        (st->codec->codec_id == CODEC_ID_AC3) {

                stream->id = ac3_id++;

            } else if (st->codec->codec_id == CODEC_ID_DTS) {

                stream->id = dts_id++;

            } else if (st->codec->codec_id == CODEC_ID_PCM_S16BE) {

                stream->id = lpcm_id++;

                for(j = 0; j < 4; j++) {

                    if (lpcm_freq_tab[j] == st->codec->sample_rate)

                        break;

                }

                if (j == 4)

                    goto fail;

                if (st->codec->channels > 8)

                    return -1;

                stream->lpcm_header[0] = 0x0c;

                stream->lpcm_header[1] = (st->codec->channels - 1) | (j << 4);

                stream->lpcm_header[2] = 0x80;

                stream->lpcm_align = st->codec->channels * 2;

            } else {

                stream->id = mpa_id++;

            }



            /* This value HAS to be used for VCD (see VCD standard, p. IV-7).

               Right now it is also used for everything else.*/

            stream->max_buffer_size = 4 * 1024;

            s->audio_bound++;

            break;

        case CODEC_TYPE_VIDEO:

            stream->id = mpv_id++;

            if (st->codec->rc_buffer_size)

                stream->max_buffer_size = 6*1024 + st->codec->rc_buffer_size/8;

            else

                stream->max_buffer_size = 230*1024; //FIXME this is probably too small as default

#if 0

                /* see VCD standard, p. IV-7*/

                stream->max_buffer_size = 46 * 1024;

            else

                /* This value HAS to be used for SVCD (see SVCD standard, p. 26 V.2.3.2).

                   Right now it is also used for everything else.*/

                stream->max_buffer_size = 230 * 1024;

#endif

            s->video_bound++;

            break;

        case CODEC_TYPE_SUBTITLE:

            stream->id = mps_id++;

            stream->max_buffer_size = 16 * 1024;

            break;

        default:

            return -1;

        }

        stream->fifo= av_fifo_alloc(16);

    }

    bitrate = 0;

    audio_bitrate = 0;

    video_bitrate = 0;

    for(i=0;i<ctx->nb_streams;i++) {

        int codec_rate;

        st = ctx->streams[i];

        stream = (StreamInfo*) st->priv_data;



        if(st->codec->rc_max_rate || stream->id==VIDEO_ID)

            codec_rate= st->codec->rc_max_rate;

        else

            codec_rate= st->codec->bit_rate;



        if(!codec_rate)

            codec_rate= (1<<21)*8*50/ctx->nb_streams;



        bitrate += codec_rate;



        if (stream->id==AUDIO_ID)

            audio_bitrate += codec_rate;

        else if (stream->id==VIDEO_ID)

            video_bitrate += codec_rate;

    }



    if(ctx->mux_rate){

        s->mux_rate= (ctx->mux_rate + (8 * 50) - 1) / (8 * 50);

    } else {

        /* we increase slightly the bitrate to take into account the

           headers. XXX: compute it exactly */

        bitrate += bitrate*5/100;

        bitrate += 10000;

        s->mux_rate = (bitrate + (8 * 50) - 1) / (8 * 50);

    }



    if (s->is_vcd) {

        double overhead_rate;



        /* The VCD standard mandates that the mux_rate field is 3528

           (see standard p. IV-6).

           The value is actually "wrong", i.e. if you calculate

           it using the normal formula and the 75 sectors per second transfer

           rate you get a different value because the real pack size is 2324,

           not 2352. But the standard explicitly specifies that the mux_rate

           field in the header must have this value.*/

//        s->mux_rate=2352 * 75 / 50;    /* = 3528*/



        /* The VCD standard states that the muxed stream must be

           exactly 75 packs / second (the data rate of a single speed cdrom).

           Since the video bitrate (probably 1150000 bits/sec) will be below

           the theoretical maximum we have to add some padding packets

           to make up for the lower data rate.

           (cf. VCD standard p. IV-6 )*/



        /* Add the header overhead to the data rate.

           2279 data bytes per audio pack, 2294 data bytes per video pack*/

        overhead_rate  = ((audio_bitrate / 8.0) / 2279) * (2324 - 2279);

        overhead_rate += ((video_bitrate / 8.0) / 2294) * (2324 - 2294);

        overhead_rate *= 8;



        /* Add padding so that the full bitrate is 2324*75 bytes/sec */

        s->vcd_padding_bitrate = 2324 * 75 * 8 - (bitrate + overhead_rate);

    }



    if (s->is_vcd || s->is_mpeg2)

        /* every packet */

        s->pack_header_freq = 1;

    else

        /* every 2 seconds */

        s->pack_header_freq = 2 * bitrate / s->packet_size / 8;



    /* the above seems to make pack_header_freq zero sometimes */

    if (s->pack_header_freq == 0)

       s->pack_header_freq = 1;



    if (s->is_mpeg2)

        /* every 200 packets. Need to look at the spec.  */

        s->system_header_freq = s->pack_header_freq * 40;

    else if (s->is_vcd)

        /* the standard mandates that there are only two system headers

           in the whole file: one in the first packet of each stream.

           (see standard p. IV-7 and IV-8) */

        s->system_header_freq = 0x7fffffff;

    else

        s->system_header_freq = s->pack_header_freq * 5;



    for(i=0;i<ctx->nb_streams;i++) {

        stream = ctx->streams[i]->priv_data;

        stream->packet_number = 0;

    }

    s->system_header_size = get_system_header_size(ctx);

    s->last_scr = 0;

    return 0;

 fail:

    for(i=0;i<ctx->nb_streams;i++) {

        av_free(ctx->streams[i]->priv_data);

    }

    return AVERROR(ENOMEM);

}

static int decode_picture_header(AVCodecContext *avctx, const uint8_t *buf, const int buf_size)

{

    ProresContext *ctx = avctx->priv_data;

    int i, hdr_size, slice_count;

    unsigned pic_data_size;

    int log2_slice_mb_width, log2_slice_mb_height;

    int slice_mb_count, mb_x, mb_y;

    const uint8_t *data_ptr, *index_ptr;



    hdr_size = buf[0] >> 3;

    if (hdr_size < 8 || hdr_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "error, wrong picture header size\n");

        return -1;

    }



    pic_data_size = AV_RB32(buf + 1);

    if (pic_data_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "error, wrong picture data size\n");

        return -1;

    }



    log2_slice_mb_width  = buf[7] >> 4;

    log2_slice_mb_height = buf[7] & 0xF;

    if (log2_slice_mb_width > 3 || log2_slice_mb_height) {

        av_log(avctx, AV_LOG_ERROR, "unsupported slice resolution: %dx%d\n",

               1 << log2_slice_mb_width, 1 << log2_slice_mb_height);

        return -1;

    }



    ctx->mb_width  = (avctx->width  + 15) >> 4;

    ctx->mb_height = (avctx->height + 15) >> 4;



    slice_count = AV_RB16(buf + 5);



    if (ctx->slice_count != slice_count || !ctx->slices) {

        av_freep(&ctx->slices);

        ctx->slices = av_mallocz(slice_count * sizeof(*ctx->slices));

        if (!ctx->slices)

            return AVERROR(ENOMEM);

        ctx->slice_count = slice_count;

    }



    if (!slice_count)

        return AVERROR(EINVAL);



    if (hdr_size + slice_count*2 > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "error, wrong slice count\n");

        return -1;

    }



    // parse slice information

    index_ptr = buf + hdr_size;

    data_ptr  = index_ptr + slice_count*2;



    slice_mb_count = 1 << log2_slice_mb_width;

    mb_x = 0;

    mb_y = 0;



    for (i = 0; i < slice_count; i++) {

        SliceContext *slice = &ctx->slices[i];



        slice->data = data_ptr;

        data_ptr += AV_RB16(index_ptr + i*2);



        while (ctx->mb_width - mb_x < slice_mb_count)

            slice_mb_count >>= 1;



        slice->mb_x = mb_x;

        slice->mb_y = mb_y;

        slice->mb_count = slice_mb_count;

        slice->data_size = data_ptr - slice->data;



        if (slice->data_size < 6) {

            av_log(avctx, AV_LOG_ERROR, "error, wrong slice data size\n");

            return -1;

        }



        mb_x += slice_mb_count;

        if (mb_x == ctx->mb_width) {

            slice_mb_count = 1 << log2_slice_mb_width;

            mb_x = 0;

            mb_y++;

        }

        if (data_ptr > buf + buf_size) {

            av_log(avctx, AV_LOG_ERROR, "error, slice out of bounds\n");

            return -1;

        }

    }



    return pic_data_size;

}

