        return actual_len;

    case usb_redir_stall:

        return USB_RET_STALL;

    case usb_redir_cancelled:

        WARNING("returning cancelled packet to HC?\n");

        return USB_RET_NAK;

    case usb_redir_inval:

        WARNING("got invalid param error from usb-host?\n");

        return USB_RET_NAK;

    case usb_redir_babble:

        return USB_RET_BABBLE;

    case usb_redir_ioerror:

    case usb_redir_timeout:

    default:

        return USB_RET_IOERROR;

    }

}

static av_cold void set_bandwidth(AC3EncodeContext *s)

{

    int blk, ch, cpl_start;



    if (s->cutoff) {

        /* calculate bandwidth based on user-specified cutoff frequency */

        int fbw_coeffs;

        fbw_coeffs     = s->cutoff * 2 * AC3_MAX_COEFS / s->sample_rate;

        s->bandwidth_code = av_clip((fbw_coeffs - 73) / 3, 0, 60);

    } else {

        /* use default bandwidth setting */

        s->bandwidth_code = ac3_bandwidth_tab[s->fbw_channels-1][s->bit_alloc.sr_code][s->frame_size_code/2];

    }



    /* set number of coefficients for each channel */

    for (ch = 1; ch <= s->fbw_channels; ch++) {

        s->start_freq[ch] = 0;

        for (blk = 0; blk < s->num_blocks; blk++)

            s->blocks[blk].end_freq[ch] = s->bandwidth_code * 3 + 73;

    }

    /* LFE channel always has 7 coefs */

    if (s->lfe_on) {

        s->start_freq[s->lfe_channel] = 0;

        for (blk = 0; blk < s->num_blocks; blk++)

            s->blocks[blk].end_freq[ch] = 7;

    }



    /* initialize coupling strategy */

    if (s->cpl_enabled) {

        if (s->options.cpl_start != AC3ENC_OPT_AUTO) {

            cpl_start = s->options.cpl_start;

        } else {

            cpl_start = ac3_coupling_start_tab[s->channel_mode-2][s->bit_alloc.sr_code][s->frame_size_code/2];

            if (cpl_start < 0) {

                if (s->options.channel_coupling == AC3ENC_OPT_AUTO)

                    s->cpl_enabled = 0;

                else

                    cpl_start = 15;

            }

        }

    }

    if (s->cpl_enabled) {

        int i, cpl_start_band, cpl_end_band;

        uint8_t *cpl_band_sizes = s->cpl_band_sizes;



        cpl_end_band   = s->bandwidth_code / 4 + 3;

        cpl_start_band = av_clip(cpl_start, 0, FFMIN(cpl_end_band-1, 15));



        s->num_cpl_subbands = cpl_end_band - cpl_start_band;



        s->num_cpl_bands = 1;

        *cpl_band_sizes  = 12;

        for (i = cpl_start_band + 1; i < cpl_end_band; i++) {

            if (ff_eac3_default_cpl_band_struct[i]) {

                *cpl_band_sizes += 12;

            } else {

                s->num_cpl_bands++;

                cpl_band_sizes++;

                *cpl_band_sizes = 12;

            }

        }



        s->start_freq[CPL_CH] = cpl_start_band * 12 + 37;

        s->cpl_end_freq       = cpl_end_band   * 12 + 37;

        for (blk = 0; blk < s->num_blocks; blk++)

            s->blocks[blk].end_freq[CPL_CH] = s->cpl_end_freq;

    }

}

static void FUNC(dequant)(int16_t *coeffs, int16_t log2_size)

{

    int shift  = 15 - BIT_DEPTH - log2_size;

    int x, y;

    int size = 1 << log2_size;



    if (shift > 0) {

        int offset = 1 << (shift - 1);

        for (y = 0; y < size; y++) {

            for (x = 0; x < size; x++) {

                *coeffs = (*coeffs + offset) >> shift;

                coeffs++;

            }

        }

    } else {

        for (y = 0; y < size; y++) {

            for (x = 0; x < size; x++) {

                *coeffs = *coeffs << -shift;

                coeffs++;

            }

        }

    }

}

static void calc_transform_coeffs_cpl(AC3DecodeContext *s)

{

    int bin, band, ch, band_end;



    bin = s->start_freq[CPL_CH];

    for (band = 0; band < s->num_cpl_bands; band++) {

        band_end = bin + s->cpl_band_sizes[band];

        for (; bin < band_end; bin++) {

            for (ch = 1; ch <= s->fbw_channels; ch++) {

                if (s->channel_in_cpl[ch]) {

                    s->fixed_coeffs[ch][bin] = ((int64_t)s->fixed_coeffs[CPL_CH][bin] *

                                                (int64_t)s->cpl_coords[ch][band]) >> 23;

                    if (ch == 2 && s->phase_flags[band])

                        s->fixed_coeffs[ch][bin] = -s->fixed_coeffs[ch][bin];

                }

            }

        }

    }

}

static void use_high_update_speed(WmallDecodeCtx *s, int ich)

{

    int ilms, recent, icoef;

    s->update_speed[ich] = 16;

    for (ilms = s->cdlms_ttl[ich]; ilms >= 0; ilms--) {

        recent = s->cdlms[ich][ilms].recent;

        if (s->bV3RTM) {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef + recent] *= 2;

        } else {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef] *= 2;

        }

    }

}

static inline void RENAME(yuy2ToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, int width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(

        "movq "MANGLE(bm01010101)", %%mm4           \n\t"

        "mov                    %0, %%"REG_a"       \n\t"

        "1:                                         \n\t"

        "movq    (%1, %%"REG_a",4), %%mm0           \n\t"

        "movq   8(%1, %%"REG_a",4), %%mm1           \n\t"

        "psrlw                  $8, %%mm0           \n\t"

        "psrlw                  $8, %%mm1           \n\t"

        "packuswb            %%mm1, %%mm0           \n\t"

        "movq                %%mm0, %%mm1           \n\t"

        "psrlw                  $8, %%mm0           \n\t"

        "pand                %%mm4, %%mm1           \n\t"

        "packuswb            %%mm0, %%mm0           \n\t"

        "packuswb            %%mm1, %%mm1           \n\t"

        "movd                %%mm0, (%3, %%"REG_a") \n\t"

        "movd                %%mm1, (%2, %%"REG_a") \n\t"

        "add                    $4, %%"REG_a"       \n\t"

        " js                    1b                  \n\t"

        : : "g" ((x86_reg)-width), "r" (src1+width*4), "r" (dstU+width), "r" (dstV+width)

        : "%"REG_a

    );

#else

    int i;

    for (i=0; i<width; i++) {

        dstU[i]= src1[4*i + 1];

        dstV[i]= src1[4*i + 3];

    }

#endif

    assert(src1 == src2);

}

