static void draw_rectangle(unsigned val, uint8_t *dst, int dst_linesize, unsigned segment_width,

                           unsigned x, unsigned y, unsigned w, unsigned h)

{

    int i;

    int step = 3;



    dst += segment_width * (step * x + y * dst_linesize);

    w *= segment_width * step;

    h *= segment_width;

    for (i = 0; i < h; i++) {

        memset(dst, val, w);

        dst += dst_linesize;

    }

}

static inline TCGOp *tcg_emit_op(TCGOpcode opc)

{

    TCGContext *ctx = tcg_ctx;

    int oi = ctx->gen_next_op_idx;

    int ni = oi + 1;

    int pi = oi - 1;

    TCGOp *op = &ctx->gen_op_buf[oi];



    tcg_debug_assert(oi < OPC_BUF_SIZE);

    ctx->gen_op_buf[0].prev = oi;

    ctx->gen_next_op_idx = ni;



    memset(op, 0, offsetof(TCGOp, args));

    op->opc = opc;

    op->prev = pi;

    op->next = ni;



    return op;

}

static int xenfb_send_position(struct XenInput *xenfb,

			       int abs_x, int abs_y, int z)

{

    union xenkbd_in_event event;



    memset(&event, 0, XENKBD_IN_EVENT_SIZE);

    event.type = XENKBD_TYPE_POS;

    event.pos.abs_x = abs_x;

    event.pos.abs_y = abs_y;

#if __XEN_LATEST_INTERFACE_VERSION__ == 0x00030207

    event.pos.abs_z = z;

#endif

#if __XEN_LATEST_INTERFACE_VERSION__ >= 0x00030208

    event.pos.rel_z = z;

#endif



    return xenfb_kbd_event(xenfb, &event);

}

static int kvm_put_fpu(CPUState *env)

{

    struct kvm_fpu fpu;

    int i;



    memset(&fpu, 0, sizeof fpu);

    fpu.fsw = env->fpus & ~(7 << 11);

    fpu.fsw |= (env->fpstt & 7) << 11;

    fpu.fcw = env->fpuc;

    for (i = 0; i < 8; ++i)

	fpu.ftwx |= (!env->fptags[i]) << i;

    memcpy(fpu.fpr, env->fpregs, sizeof env->fpregs);

    memcpy(fpu.xmm, env->xmm_regs, sizeof env->xmm_regs);

    fpu.mxcsr = env->mxcsr;



    return kvm_vcpu_ioctl(env, KVM_SET_FPU, &fpu);

}

static int pmp_header(AVFormatContext *s)

{

    PMPContext *pmp = s->priv_data;

    AVIOContext *pb = s->pb;

    int tb_num, tb_den;

    uint32_t index_cnt;

    int audio_codec_id = AV_CODEC_ID_NONE;

    int srate, channels;

    int i;

    uint64_t pos;

    int64_t fsize = avio_size(pb);



    AVStream *vst = avformat_new_stream(s, NULL);

    if (!vst)

        return AVERROR(ENOMEM);

    vst->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    avio_skip(pb, 8);

    switch (avio_rl32(pb)) {

    case 0:

        vst->codec->codec_id = AV_CODEC_ID_MPEG4;

        break;

    case 1:

        vst->codec->codec_id = AV_CODEC_ID_H264;

        break;

    default:

        av_log(s, AV_LOG_ERROR, "Unsupported video format\n");

        break;

    }

    index_cnt = avio_rl32(pb);

    vst->codec->width  = avio_rl32(pb);

    vst->codec->height = avio_rl32(pb);



    tb_num = avio_rl32(pb);

    tb_den = avio_rl32(pb);

    avpriv_set_pts_info(vst, 32, tb_num, tb_den);

    vst->nb_frames = index_cnt;

    vst->duration = index_cnt;



    switch (avio_rl32(pb)) {

    case 0:

        audio_codec_id = AV_CODEC_ID_MP3;

        break;

    case 1:

        av_log(s, AV_LOG_ERROR, "AAC not yet correctly supported\n");

        audio_codec_id = AV_CODEC_ID_AAC;

        break;

    default:

        av_log(s, AV_LOG_ERROR, "Unsupported audio format\n");

        break;

    }

    pmp->num_streams = avio_rl16(pb) + 1;

    avio_skip(pb, 10);

    srate = avio_rl32(pb);

    channels = avio_rl32(pb) + 1;

    pos = avio_tell(pb) + 4*index_cnt;

    for (i = 0; i < index_cnt; i++) {

        uint32_t size = avio_rl32(pb);

        int flags = size & 1 ? AVINDEX_KEYFRAME : 0;

        if (url_feof(pb)) {

            av_log(s, AV_LOG_FATAL, "Encountered EOF while reading index.\n");

            return AVERROR_INVALIDDATA;

        }

        size >>= 1;

        if (size < 9 + 4*pmp->num_streams) {

            av_log(s, AV_LOG_ERROR, "Packet too small\n");

            return AVERROR_INVALIDDATA;

        }

        av_add_index_entry(vst, pos, i, size, 0, flags);

        pos += size;

        if (fsize > 0 && i == 0 && pos > fsize) {

            av_log(s, AV_LOG_ERROR, "File ends before first packet\n");

            return AVERROR_INVALIDDATA;

        }

    }

    for (i = 1; i < pmp->num_streams; i++) {

        AVStream *ast = avformat_new_stream(s, NULL);

        if (!ast)

            return AVERROR(ENOMEM);

        ast->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        ast->codec->codec_id = audio_codec_id;

        ast->codec->channels = channels;

        ast->codec->sample_rate = srate;

        avpriv_set_pts_info(ast, 32, 1, srate);

    }

    return 0;

}

static int bfi_read_header(AVFormatContext * s)

{

    BFIContext *bfi = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *vstream;

    AVStream *astream;

    int fps, chunk_header;



    /* Initialize the video codec... */

    vstream = avformat_new_stream(s, NULL);

    if (!vstream)

        return AVERROR(ENOMEM);



    /* Initialize the audio codec... */

    astream = avformat_new_stream(s, NULL);

    if (!astream)

        return AVERROR(ENOMEM);



    /* Set the total number of frames. */

    avio_skip(pb, 8);

    chunk_header           = avio_rl32(pb);

    bfi->nframes           = avio_rl32(pb);

    avio_rl32(pb);

    avio_rl32(pb);

    avio_rl32(pb);

    fps                    = avio_rl32(pb);

    avio_skip(pb, 12);

    vstream->codecpar->width  = avio_rl32(pb);

    vstream->codecpar->height = avio_rl32(pb);



    /*Load the palette to extradata */

    avio_skip(pb, 8);

    vstream->codecpar->extradata      = av_malloc(768);

    if (!vstream->codecpar->extradata)

        return AVERROR(ENOMEM);

    vstream->codecpar->extradata_size = 768;

    avio_read(pb, vstream->codecpar->extradata,

               vstream->codecpar->extradata_size);



    astream->codecpar->sample_rate = avio_rl32(pb);

    if (astream->codecpar->sample_rate <= 0) {

        av_log(s, AV_LOG_ERROR, "Invalid sample rate %d\n", astream->codecpar->sample_rate);

        return AVERROR_INVALIDDATA;

    }



    /* Set up the video codec... */

    avpriv_set_pts_info(vstream, 32, 1, fps);

    vstream->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;

    vstream->codecpar->codec_id   = AV_CODEC_ID_BFI;

    vstream->codecpar->format     = AV_PIX_FMT_PAL8;

    vstream->nb_frames            =

    vstream->duration             = bfi->nframes;



    /* Set up the audio codec now... */

    astream->codecpar->codec_type      = AVMEDIA_TYPE_AUDIO;

    astream->codecpar->codec_id        = AV_CODEC_ID_PCM_U8;

    astream->codecpar->channels        = 1;

    astream->codecpar->channel_layout  = AV_CH_LAYOUT_MONO;

    astream->codecpar->bits_per_coded_sample = 8;

    astream->codecpar->bit_rate        =

        astream->codecpar->sample_rate * astream->codecpar->bits_per_coded_sample;

    avio_seek(pb, chunk_header - 3, SEEK_SET);

    avpriv_set_pts_info(astream, 64, 1, astream->codecpar->sample_rate);

    return 0;

}

static int aea_read_header(AVFormatContext *s)

{

    AVStream *st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    /* Parse the amount of channels and skip to pos 2048(0x800) */

    avio_skip(s->pb, 264);

    st->codec->channels = avio_r8(s->pb);

    avio_skip(s->pb, 1783);





    st->codec->codec_type     = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id       = AV_CODEC_ID_ATRAC1;

    st->codec->sample_rate    = 44100;

    st->codec->bit_rate       = 292000;



    if (st->codec->channels != 1 && st->codec->channels != 2) {

        av_log(s,AV_LOG_ERROR,"Channels %d not supported!\n",st->codec->channels);

        return -1;

    }



    st->codec->channel_layout = (st->codec->channels == 1) ? AV_CH_LAYOUT_MONO : AV_CH_LAYOUT_STEREO;



    st->codec->block_align = AT1_SU_SIZE * st->codec->channels;

    return 0;

}

static int init_filter_param(AVFilterContext *ctx, FilterParam *fp, const char *effect_type, int width)

{

    int z;

    const char *effect = fp->amount == 0 ? "none" : fp->amount < 0 ? "blur" : "sharpen";



    if  (!(fp->msize_x & fp->msize_y & 1)) {

        av_log(ctx, AV_LOG_ERROR,

               "Invalid even size for %s matrix size %dx%d\n",

               effect_type, fp->msize_x, fp->msize_y);

        return AVERROR(EINVAL);

    }



    av_log(ctx, AV_LOG_VERBOSE, "effect:%s type:%s msize_x:%d msize_y:%d amount:%0.2f\n",

           effect, effect_type, fp->msize_x, fp->msize_y, fp->amount / 65535.0);



    for (z = 0; z < 2 * fp->steps_y; z++)

        fp->sc[z] = av_malloc(sizeof(*(fp->sc[z])) * (width + 2 * fp->steps_x));



    return 0;

}

static int upload_texture(SDL_Texture *tex, AVFrame *frame, struct SwsContext **img_convert_ctx) {

    int ret = 0;

    switch (frame->format) {

        case AV_PIX_FMT_YUV420P:

            ret = SDL_UpdateYUVTexture(tex, NULL, frame->data[0], frame->linesize[0],

                                                  frame->data[1], frame->linesize[1],

                                                  frame->data[2], frame->linesize[2]);

            break;

        case AV_PIX_FMT_BGRA:

            ret = SDL_UpdateTexture(tex, NULL, frame->data[0], frame->linesize[0]);

            break;

        default:

            /* This should only happen if we are not using avfilter... */

            *img_convert_ctx = sws_getCachedContext(*img_convert_ctx,

                frame->width, frame->height, frame->format, frame->width, frame->height,

                AV_PIX_FMT_BGRA, sws_flags, NULL, NULL, NULL);

            if (*img_convert_ctx != NULL) {

                uint8_t *pixels;

                int pitch;

                if (!SDL_LockTexture(tex, NULL, (void **)&pixels, &pitch)) {

                    sws_scale(*img_convert_ctx, (const uint8_t * const *)frame->data, frame->linesize,

                              0, frame->height, &pixels, &pitch);

                    SDL_UnlockTexture(tex);

                }

            } else {

                av_log(NULL, AV_LOG_FATAL, "Cannot initialize the conversion context\n");

                ret = -1;

            }

            break;

    }

    return ret;

}

static ChannelElement *get_che(AACContext *ac, int type, int elem_id)
{
    // For PCE based channel configurations map the channels solely based on tags.
    if (!ac->oc[1].m4ac.chan_config) {
        return ac->tag_che_map[type][elem_id];
    }
    // Allow single CPE stereo files to be signalled with mono configuration.
    if (!ac->tags_mapped && type == TYPE_CPE && ac->oc[1].m4ac.chan_config == 1) {
        uint8_t layout_map[MAX_ELEM_ID*4][3];
        int layout_map_tags;
        push_output_configuration(ac);
        if (set_default_channel_config(ac->avctx, layout_map, &layout_map_tags,
                                       2) < 0)
            return NULL;
        if (output_configure(ac, layout_map, layout_map_tags,
                             2, OC_TRIAL_FRAME) < 0)
            return NULL;
        ac->oc[1].m4ac.chan_config = 2;
    }
    // And vice-versa
    if (!ac->tags_mapped && type == TYPE_SCE && ac->oc[1].m4ac.chan_config == 2 && 0) {
        uint8_t layout_map[MAX_ELEM_ID*4][3];
        int layout_map_tags;
        push_output_configuration(ac);
        av_log(ac->avctx, AV_LOG_DEBUG, "stereo with SCE\n");
        if (set_default_channel_config(ac->avctx, layout_map, &layout_map_tags,
                                       1) < 0)
            return NULL;
        if (output_configure(ac, layout_map, layout_map_tags,
                             1, OC_TRIAL_FRAME) < 0)
            return NULL;
        ac->oc[1].m4ac.chan_config = 1;
    }
    // For indexed channel configurations map the channels solely based on position.
    switch (ac->oc[1].m4ac.chan_config) {
    case 7:
        if (ac->tags_mapped == 3 && type == TYPE_CPE) {
            ac->tags_mapped++;
            return ac->tag_che_map[TYPE_CPE][elem_id] = ac->che[TYPE_CPE][2];
        }
    case 6:
        /* Some streams incorrectly code 5.1 audio as SCE[0] CPE[0] CPE[1] SCE[1]
           instead of SCE[0] CPE[0] CPE[1] LFE[0]. If we seem to have
           encountered such a stream, transfer the LFE[0] element to the SCE[1]'s mapping */
        if (ac->tags_mapped == tags_per_config[ac->oc[1].m4ac.chan_config] - 1 && (type == TYPE_LFE || type == TYPE_SCE)) {
            ac->tags_mapped++;
            return ac->tag_che_map[type][elem_id] = ac->che[TYPE_LFE][0];
        }
    case 5:
        if (ac->tags_mapped == 2 && type == TYPE_CPE) {
            ac->tags_mapped++;
            return ac->tag_che_map[TYPE_CPE][elem_id] = ac->che[TYPE_CPE][1];
        }
    case 4:
        if (ac->tags_mapped == 2 && ac->oc[1].m4ac.chan_config == 4 && type == TYPE_SCE) {
            ac->tags_mapped++;
            return ac->tag_che_map[TYPE_SCE][elem_id] = ac->che[TYPE_SCE][1];
        }
    case 3:
    case 2:
        if (ac->tags_mapped == (ac->oc[1].m4ac.chan_config != 2) && type == TYPE_CPE) {
            ac->tags_mapped++;
            return ac->tag_che_map[TYPE_CPE][elem_id] = ac->che[TYPE_CPE][0];
        } else if (ac->oc[1].m4ac.chan_config == 2) {
            return NULL;
        }
    case 1:
        if (!ac->tags_mapped && type == TYPE_SCE) {
            ac->tags_mapped++;
            return ac->tag_che_map[TYPE_SCE][elem_id] = ac->che[TYPE_SCE][0];
        }
    default:
        return NULL;
    }
}

static void mov_write_uuidprof_tag(AVIOContext *pb, AVFormatContext *s)

{

    AVStream       *video_st    = s->streams[0];

    AVCodecParameters *video_par = s->streams[0]->codecpar;

    AVCodecParameters *audio_par = s->streams[1]->codecpar;

    int audio_rate = audio_par->sample_rate;

    int64_t frame_rate = (video_st->avg_frame_rate.num * 0x10000LL) / video_st->avg_frame_rate.den;

    int audio_kbitrate = audio_par->bit_rate / 1000;

    int video_kbitrate = FFMIN(video_par->bit_rate / 1000, 800 - audio_kbitrate);



    avio_wb32(pb, 0x94); /* size */

    ffio_wfourcc(pb, "uuid");

    ffio_wfourcc(pb, "PROF");



    avio_wb32(pb, 0x21d24fce); /* 96 bit UUID */

    avio_wb32(pb, 0xbb88695c);

    avio_wb32(pb, 0xfac9c740);



    avio_wb32(pb, 0x0);  /* ? */

    avio_wb32(pb, 0x3);  /* 3 sections ? */



    avio_wb32(pb, 0x14); /* size */

    ffio_wfourcc(pb, "FPRF");

    avio_wb32(pb, 0x0);  /* ? */

    avio_wb32(pb, 0x0);  /* ? */

    avio_wb32(pb, 0x0);  /* ? */



    avio_wb32(pb, 0x2c);  /* size */

    ffio_wfourcc(pb, "APRF"); /* audio */

    avio_wb32(pb, 0x0);

    avio_wb32(pb, 0x2);   /* TrackID */

    ffio_wfourcc(pb, "mp4a");

    avio_wb32(pb, 0x20f);

    avio_wb32(pb, 0x0);

    avio_wb32(pb, audio_kbitrate);

    avio_wb32(pb, audio_kbitrate);

    avio_wb32(pb, audio_rate);

    avio_wb32(pb, audio_par->channels);



    avio_wb32(pb, 0x34);  /* size */

    ffio_wfourcc(pb, "VPRF");   /* video */

    avio_wb32(pb, 0x0);

    avio_wb32(pb, 0x1);    /* TrackID */

    if (video_par->codec_id == AV_CODEC_ID_H264) {

        ffio_wfourcc(pb, "avc1");

        avio_wb16(pb, 0x014D);

        avio_wb16(pb, 0x0015);

    } else {

        ffio_wfourcc(pb, "mp4v");

        avio_wb16(pb, 0x0000);

        avio_wb16(pb, 0x0103);

    }

    avio_wb32(pb, 0x0);

    avio_wb32(pb, video_kbitrate);

    avio_wb32(pb, video_kbitrate);

    avio_wb32(pb, frame_rate);

    avio_wb32(pb, frame_rate);

    avio_wb16(pb, video_par->width);

    avio_wb16(pb, video_par->height);

    avio_wb32(pb, 0x010001); /* ? */

}

static int set_pix_fmt(AVCodecContext *avctx, vpx_codec_caps_t codec_caps,

                       struct vpx_codec_enc_cfg *enccfg, vpx_codec_flags_t *flags,

                       vpx_img_fmt_t *img_fmt)

{

    VPxContext av_unused *ctx = avctx->priv_data;

#ifdef VPX_IMG_FMT_HIGHBITDEPTH

    enccfg->g_bit_depth = enccfg->g_input_bit_depth = 8;

#endif

    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUVA420P:

        enccfg->g_profile = 0;

        *img_fmt = VPX_IMG_FMT_I420;

        return 0;

    case AV_PIX_FMT_YUV422P:

        enccfg->g_profile = 1;

        *img_fmt = VPX_IMG_FMT_I422;

        return 0;

#if VPX_IMAGE_ABI_VERSION >= 3

    case AV_PIX_FMT_YUV440P:

        enccfg->g_profile = 1;

        *img_fmt = VPX_IMG_FMT_I440;

        return 0;

    case AV_PIX_FMT_GBRP:

        ctx->vpx_cs = VPX_CS_SRGB;

#endif

    case AV_PIX_FMT_YUV444P:

        enccfg->g_profile = 1;

        *img_fmt = VPX_IMG_FMT_I444;

        return 0;

#ifdef VPX_IMG_FMT_HIGHBITDEPTH

    case AV_PIX_FMT_YUV420P10:

    case AV_PIX_FMT_YUV420P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV420P10 ? 10 : 12;

            enccfg->g_profile = 2;

            *img_fmt = VPX_IMG_FMT_I42016;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

    case AV_PIX_FMT_YUV422P10:

    case AV_PIX_FMT_YUV422P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV422P10 ? 10 : 12;

            enccfg->g_profile = 3;

            *img_fmt = VPX_IMG_FMT_I42216;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

#if VPX_IMAGE_ABI_VERSION >= 3

    case AV_PIX_FMT_YUV440P10:

    case AV_PIX_FMT_YUV440P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV440P10 ? 10 : 12;

            enccfg->g_profile = 3;

            *img_fmt = VPX_IMG_FMT_I44016;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

    case AV_PIX_FMT_GBRP10:

    case AV_PIX_FMT_GBRP12:

        ctx->vpx_cs = VPX_CS_SRGB;

#endif

    case AV_PIX_FMT_YUV444P10:

    case AV_PIX_FMT_YUV444P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV444P10 ||

                avctx->pix_fmt == AV_PIX_FMT_GBRP10 ? 10 : 12;

            enccfg->g_profile = 3;

            *img_fmt = VPX_IMG_FMT_I44416;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

#endif

    default:

        break;

    }

    av_log(avctx, AV_LOG_ERROR, "Unsupported pixel format.\n");

    return AVERROR_INVALIDDATA;

}

static int load_xbzrle(QEMUFile *f, ram_addr_t addr, void *host)

{

    int ret, rc = 0;

    unsigned int xh_len;

    int xh_flags;



    if (!XBZRLE.decoded_buf) {

        XBZRLE.decoded_buf = g_malloc(TARGET_PAGE_SIZE);

    }



    /* extract RLE header */

    xh_flags = qemu_get_byte(f);

    xh_len = qemu_get_be16(f);



    if (xh_flags != ENCODING_FLAG_XBZRLE) {

        fprintf(stderr, "Failed to load XBZRLE page - wrong compression!\n");

        return -1;

    }



    if (xh_len > TARGET_PAGE_SIZE) {

        fprintf(stderr, "Failed to load XBZRLE page - len overflow!\n");

        return -1;

    }

    /* load data and decode */

    qemu_get_buffer(f, XBZRLE.decoded_buf, xh_len);



    /* decode RLE */

    ret = xbzrle_decode_buffer(XBZRLE.decoded_buf, xh_len, host,

                               TARGET_PAGE_SIZE);

    if (ret == -1) {

        fprintf(stderr, "Failed to load XBZRLE page - decode error!\n");

        rc = -1;

    } else  if (ret > TARGET_PAGE_SIZE) {

        fprintf(stderr, "Failed to load XBZRLE page - size %d exceeds %d!\n",

                ret, TARGET_PAGE_SIZE);

        abort();

    }



    return rc;

}

static uint32_t rtl8139_TxStatus_read(RTL8139State *s, uint8_t addr, int size)

{

    uint32_t reg = (addr - TxStatus0) / 4;

    uint32_t offset = addr & 0x3;

    uint32_t ret = 0;



    if (addr & (size - 1)) {

        DPRINTF("not implemented read for TxStatus addr=0x%x size=0x%x\n", addr,

                size);

        return ret;

    }



    switch (size) {

    case 1: /* fall through */

    case 2: /* fall through */

    case 4:

        ret = (s->TxStatus[reg] >> offset * 8) & ((1 << (size * 8)) - 1);

        DPRINTF("TxStatus[%d] read addr=0x%x size=0x%x val=0x%08x\n", reg, addr,

                size, ret);

        break;

    default:

        DPRINTF("unsupported size 0x%x of TxStatus reading\n", size);

        break;

    }



    return ret;

}

static int slirp_state_load(QEMUFile *f, void *opaque, int version_id)

{

    Slirp *slirp = opaque;

    struct ex_list *ex_ptr;



    while (qemu_get_byte(f)) {

        int ret;

        struct socket *so = socreate(slirp);



        if (!so)

            return -ENOMEM;



        ret = vmstate_load_state(f, &vmstate_slirp_socket, so, version_id);



        if (ret < 0)

            return ret;



        if ((so->so_faddr.s_addr & slirp->vnetwork_mask.s_addr) !=

            slirp->vnetwork_addr.s_addr) {

            return -EINVAL;

        }

        for (ex_ptr = slirp->exec_list; ex_ptr; ex_ptr = ex_ptr->ex_next) {

            if (ex_ptr->ex_pty == 3 &&

                so->so_faddr.s_addr == ex_ptr->ex_addr.s_addr &&

                so->so_fport == ex_ptr->ex_fport) {

                break;

            }

        }

        if (!ex_ptr)

            return -EINVAL;



        so->extra = (void *)ex_ptr->ex_exec;

    }



    if (version_id >= 2) {

        slirp->ip_id = qemu_get_be16(f);

    }



    if (version_id >= 3) {

        slirp_bootp_load(f, slirp);

    }



    return 0;

}

static void vgafb_write(void *opaque, target_phys_addr_t addr, uint64_t value,

                        unsigned size)

{

    MilkymistVgafbState *s = opaque;



    trace_milkymist_vgafb_memory_write(addr, value);



    addr >>= 2;

    switch (addr) {

    case R_CTRL:

        s->regs[addr] = value;

        vgafb_resize(s);

        break;

    case R_HSYNC_START:

    case R_HSYNC_END:

    case R_HSCAN:

    case R_VSYNC_START:

    case R_VSYNC_END:

    case R_VSCAN:

    case R_BURST_COUNT:

    case R_DDC:

    case R_SOURCE_CLOCK:

        s->regs[addr] = value;

        break;

    case R_BASEADDRESS:

        if (value & 0x1f) {

            error_report("milkymist_vgafb: framebuffer base address have to "

                     "be 32 byte aligned");

            break;

        }

        s->regs[addr] = value & s->fb_mask;

        s->invalidate = 1;

        break;

    case R_HRES:

    case R_VRES:

        s->regs[addr] = value;

        vgafb_resize(s);

        break;

    case R_BASEADDRESS_ACT:

        error_report("milkymist_vgafb: write to read-only register 0x"

                TARGET_FMT_plx, addr << 2);

        break;



    default:

        error_report("milkymist_vgafb: write access to unknown register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    }

}

static char *sysbus_get_fw_dev_path(DeviceState *dev)

{

    SysBusDevice *s = SYS_BUS_DEVICE(dev);

    char path[40];

    int off;



    off = snprintf(path, sizeof(path), "%s", qdev_fw_name(dev));



    if (s->num_mmio) {

        snprintf(path + off, sizeof(path) - off, "@"TARGET_FMT_plx,

                 s->mmio[0].addr);

    } else if (s->num_pio) {

        snprintf(path + off, sizeof(path) - off, "@i%04x", s->pio[0]);

    }



    return g_strdup(path);

}

static void qbus_list_dev(BusState *bus, char *dest, int len)

{

    DeviceState *dev;

    const char *sep = " ";

    int pos = 0;



    pos += snprintf(dest+pos, len-pos, "devices at \"%s\":",

                    bus->name);

    LIST_FOREACH(dev, &bus->children, sibling) {

        pos += snprintf(dest+pos, len-pos, "%s\"%s\"",

                        sep, dev->info->name);

        if (dev->id)

            pos += snprintf(dest+pos, len-pos, "/\"%s\"", dev->id);

        sep = ", ";

    }

}

static void listflags(char *buf, int bufsize, uint32_t fbits,

    const char **featureset, uint32_t flags)

{

    const char **p = &featureset[31];

    char *q, *b, bit;

    int nc;



    b = 4 <= bufsize ? buf + (bufsize -= 3) - 1 : NULL;

    *buf = '\0';

    for (q = buf, bit = 31; fbits && bufsize; --p, fbits &= ~(1 << bit), --bit)

        if (fbits & 1 << bit && (*p || !flags)) {

            if (*p)

                nc = snprintf(q, bufsize, "%s%s", q == buf ? "" : " ", *p);

            else

                nc = snprintf(q, bufsize, "%s[%d]", q == buf ? "" : " ", bit);

            if (bufsize <= nc) {

                if (b)

                    sprintf(b, "...");

                return;

            }

            q += nc;

            bufsize -= nc;

        }

}

