        //Tossing a video packet at the video decoder.

        ret = av_get_packet(pb, pkt, bfi->video_size);

        if (ret < 0)

            return ret;



        pkt->pts          = bfi->video_frame;

        bfi->video_frame += ret / bfi->video_size;



        /* One less frame to read. A cursory decrement. */

        bfi->nframes--;

    } else {

        /* Empty video packet */

        ret = AVERROR(EAGAIN);




    bfi->avflag       = !bfi->avflag;

    pkt->stream_index = bfi->avflag;

    return ret;

static int asf_read_stream_properties(AVFormatContext *s, int64_t size)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    ASFStream *asf_st;

    ff_asf_guid g;

    enum AVMediaType type;

    int type_specific_size, sizeX;

    unsigned int tag1;

    int64_t pos1, pos2, start_time;

    int test_for_ext_stream_audio, is_dvr_ms_audio=0;



    if (s->nb_streams == ASF_MAX_STREAMS) {

        av_log(s, AV_LOG_ERROR, "too many streams\n");

        return AVERROR(EINVAL);

    }



    pos1 = avio_tell(pb);



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    avpriv_set_pts_info(st, 32, 1, 1000); /* 32 bit pts in ms */

    asf_st = av_mallocz(sizeof(ASFStream));

    if (!asf_st)

        return AVERROR(ENOMEM);

    st->priv_data = asf_st;

    start_time = asf->hdr.preroll;



    asf_st->stream_language_index = 128; // invalid stream index means no language info



    if(!(asf->hdr.flags & 0x01)) { // if we aren't streaming...

        int64_t fsize = avio_size(pb);

        if (fsize <= 0 || (int64_t)asf->hdr.file_size <= 0 || FFABS(fsize - (int64_t)asf->hdr.file_size) < 10000)

            st->duration = asf->hdr.play_time /

                (10000000 / 1000) - start_time;

    }

    ff_get_guid(pb, &g);



    test_for_ext_stream_audio = 0;

    if (!ff_guidcmp(&g, &ff_asf_audio_stream)) {

        type = AVMEDIA_TYPE_AUDIO;

    } else if (!ff_guidcmp(&g, &ff_asf_video_stream)) {

        type = AVMEDIA_TYPE_VIDEO;

    } else if (!ff_guidcmp(&g, &ff_asf_jfif_media)) {

        type = AVMEDIA_TYPE_VIDEO;

        st->codec->codec_id = AV_CODEC_ID_MJPEG;

    } else if (!ff_guidcmp(&g, &ff_asf_command_stream)) {

        type = AVMEDIA_TYPE_DATA;

    } else if (!ff_guidcmp(&g, &ff_asf_ext_stream_embed_stream_header)) {

        test_for_ext_stream_audio = 1;

        type = AVMEDIA_TYPE_UNKNOWN;

    } else {

        return -1;

    }

    ff_get_guid(pb, &g);

    avio_skip(pb, 8); /* total_size */

    type_specific_size = avio_rl32(pb);

    avio_rl32(pb);

    st->id = avio_rl16(pb) & 0x7f; /* stream id */

    // mapping of asf ID to AV stream ID;

    asf->asfid2avid[st->id] = s->nb_streams - 1;



    avio_rl32(pb);



    if (test_for_ext_stream_audio) {

        ff_get_guid(pb, &g);

        if (!ff_guidcmp(&g, &ff_asf_ext_stream_audio_stream)) {

            type = AVMEDIA_TYPE_AUDIO;

            is_dvr_ms_audio=1;

            ff_get_guid(pb, &g);

            avio_rl32(pb);

            avio_rl32(pb);

            avio_rl32(pb);

            ff_get_guid(pb, &g);

            avio_rl32(pb);

        }

    }



    st->codec->codec_type = type;

    if (type == AVMEDIA_TYPE_AUDIO) {

        int ret = ff_get_wav_header(pb, st->codec, type_specific_size);

        if (ret < 0)

            return ret;

        if (is_dvr_ms_audio) {

            // codec_id and codec_tag are unreliable in dvr_ms

            // files. Set them later by probing stream.

            st->request_probe= 1;

            st->codec->codec_tag = 0;

        }

        if (st->codec->codec_id == AV_CODEC_ID_AAC) {

            st->need_parsing = AVSTREAM_PARSE_NONE;

        } else {

            st->need_parsing = AVSTREAM_PARSE_FULL;

        }

        /* We have to init the frame size at some point .... */

        pos2 = avio_tell(pb);

        if (size >= (pos2 + 8 - pos1 + 24)) {

            asf_st->ds_span = avio_r8(pb);

            asf_st->ds_packet_size = avio_rl16(pb);

            asf_st->ds_chunk_size = avio_rl16(pb);

            avio_rl16(pb); //ds_data_size

            avio_r8(pb);   //ds_silence_data

        }

        if (asf_st->ds_span > 1) {

            if (!asf_st->ds_chunk_size

                    || (asf_st->ds_packet_size/asf_st->ds_chunk_size <= 1)

                    || asf_st->ds_packet_size % asf_st->ds_chunk_size)

                asf_st->ds_span = 0; // disable descrambling

        }

    } else if (type == AVMEDIA_TYPE_VIDEO &&

            size - (avio_tell(pb) - pos1 + 24) >= 51) {

        avio_rl32(pb);

        avio_rl32(pb);

        avio_r8(pb);

        avio_rl16(pb);        /* size */

        sizeX= avio_rl32(pb); /* size */

        st->codec->width = avio_rl32(pb);

        st->codec->height = avio_rl32(pb);

        /* not available for asf */

        avio_rl16(pb); /* panes */

        st->codec->bits_per_coded_sample = avio_rl16(pb); /* depth */

        tag1 = avio_rl32(pb);

        avio_skip(pb, 20);

        if (sizeX > 40) {

            st->codec->extradata_size = sizeX - 40;

            st->codec->extradata = av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

            avio_read(pb, st->codec->extradata, st->codec->extradata_size);

        }



        /* Extract palette from extradata if bpp <= 8 */

        /* This code assumes that extradata contains only palette */

        /* This is true for all paletted codecs implemented in libavcodec */

        if (st->codec->extradata_size && (st->codec->bits_per_coded_sample <= 8)) {

#if HAVE_BIGENDIAN

            int i;

            for (i = 0; i < FFMIN(st->codec->extradata_size, AVPALETTE_SIZE)/4; i++)

                asf_st->palette[i] = av_bswap32(((uint32_t*)st->codec->extradata)[i]);

#else

            memcpy(asf_st->palette, st->codec->extradata,

                   FFMIN(st->codec->extradata_size, AVPALETTE_SIZE));

#endif

            asf_st->palette_changed = 1;

        }



        st->codec->codec_tag = tag1;

        st->codec->codec_id = ff_codec_get_id(ff_codec_bmp_tags, tag1);

        if(tag1 == MKTAG('D', 'V', 'R', ' ')){

            st->need_parsing = AVSTREAM_PARSE_FULL;

            // issue658 containse wrong w/h and MS even puts a fake seq header with wrong w/h in extradata while a correct one is in te stream. maximum lameness

            st->codec->width  =

                st->codec->height = 0;

            av_freep(&st->codec->extradata);

            st->codec->extradata_size=0;

        }

        if(st->codec->codec_id == AV_CODEC_ID_H264)

            st->need_parsing = AVSTREAM_PARSE_FULL_ONCE;

    }

    pos2 = avio_tell(pb);

    avio_skip(pb, size - (pos2 - pos1 + 24));



    return 0;

}

static int wav_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    int64_t size, av_uninit(data_size);

    int64_t sample_count=0;

    int rf64;

    unsigned int tag;

    AVIOContext *pb = s->pb;

    AVStream *st;

    WAVContext *wav = s->priv_data;

    int ret, got_fmt = 0;

    int64_t next_tag_ofs, data_ofs = -1;



    /* check RIFF header */

    tag = avio_rl32(pb);



    rf64 = tag == MKTAG('R', 'F', '6', '4');

    if (!rf64 && tag != MKTAG('R', 'I', 'F', 'F'))

        return -1;

    avio_rl32(pb); /* file size */

    tag = avio_rl32(pb);

    if (tag != MKTAG('W', 'A', 'V', 'E'))

        return -1;



    if (rf64) {

        if (avio_rl32(pb) != MKTAG('d', 's', '6', '4'))

            return -1;

        size = avio_rl32(pb);

        if (size < 16)

            return -1;

        avio_rl64(pb); /* RIFF size */

        data_size = avio_rl64(pb);

        sample_count = avio_rl64(pb);

        if (data_size < 0 || sample_count < 0) {

            av_log(s, AV_LOG_ERROR, "negative data_size and/or sample_count in "

                   "ds64: data_size = %"PRId64", sample_count = %"PRId64"\n",

                   data_size, sample_count);

            return AVERROR_INVALIDDATA;

        }

        avio_skip(pb, size - 24); /* skip rest of ds64 chunk */

    }



    for (;;) {

        size = next_tag(pb, &tag);

        next_tag_ofs = avio_tell(pb) + size;



        if (url_feof(pb))

            break;



        switch (tag) {

        case MKTAG('f', 'm', 't', ' '):

            /* only parse the first 'fmt ' tag found */

            if (!got_fmt && (ret = wav_parse_fmt_tag(s, size, &st) < 0)) {

                return ret;

            } else if (got_fmt)

                av_log(s, AV_LOG_WARNING, "found more than one 'fmt ' tag\n");



            got_fmt = 1;

            break;

        case MKTAG('d', 'a', 't', 'a'):

            if (!got_fmt) {

                av_log(s, AV_LOG_ERROR, "found no 'fmt ' tag before the 'data' tag\n");

                return AVERROR_INVALIDDATA;

            }



            if (rf64) {

                next_tag_ofs = wav->data_end = avio_tell(pb) + data_size;

            } else {

                data_size = size;

                next_tag_ofs = wav->data_end = size ? next_tag_ofs : INT64_MAX;

            }



            data_ofs = avio_tell(pb);



            /* don't look for footer metadata if we can't seek or if we don't

             * know where the data tag ends

             */

            if (!pb->seekable || (!rf64 && !size))

                goto break_loop;

            break;

        case MKTAG('f','a','c','t'):

            if(!sample_count)

                sample_count = avio_rl32(pb);

            break;

        case MKTAG('b','e','x','t'):

            if ((ret = wav_parse_bext_tag(s, size)) < 0)

                return ret;

            break;

        }



        /* seek to next tag unless we know that we'll run into EOF */

        if ((avio_size(pb) > 0 && next_tag_ofs >= avio_size(pb)) ||

            avio_seek(pb, next_tag_ofs, SEEK_SET) < 0) {

            break;

        }

    }

break_loop:

    if (data_ofs < 0) {

        av_log(s, AV_LOG_ERROR, "no 'data' tag found\n");

        return AVERROR_INVALIDDATA;

    }



    avio_seek(pb, data_ofs, SEEK_SET);



    if (!sample_count && st->codec->channels && av_get_bits_per_sample(st->codec->codec_id))

        sample_count = (data_size<<3) / (st->codec->channels * (uint64_t)av_get_bits_per_sample(st->codec->codec_id));

    if (sample_count)

        st->duration = sample_count;



    ff_metadata_conv_ctx(s, NULL, wav_metadata_conv);



    return 0;

}

static int flush_blks(QEMUFile *f)

{

    BlkMigBlock *blk;

    int ret = 0;



    DPRINTF("%s Enter submitted %d read_done %d transferred %d\n",

            __FUNCTION__, block_mig_state.submitted, block_mig_state.read_done,

            block_mig_state.transferred);



    blk_mig_lock();

    while ((blk = QSIMPLEQ_FIRST(&block_mig_state.blk_list)) != NULL) {

        if (qemu_file_rate_limit(f)) {

            break;

        }

        if (blk->ret < 0) {

            ret = blk->ret;

            break;

        }



        QSIMPLEQ_REMOVE_HEAD(&block_mig_state.blk_list, entry);

        blk_mig_unlock();

        blk_send(f, blk);

        blk_mig_lock();



        g_free(blk->buf);

        g_free(blk);



        block_mig_state.read_done--;

        block_mig_state.transferred++;

        assert(block_mig_state.read_done >= 0);

    }

    blk_mig_unlock();



    DPRINTF("%s Exit submitted %d read_done %d transferred %d\n", __FUNCTION__,

            block_mig_state.submitted, block_mig_state.read_done,

            block_mig_state.transferred);

    return ret;

}

static int block_save_setup(QEMUFile *f, void *opaque)

{

    int ret;



    DPRINTF("Enter save live setup submitted %d transferred %d\n",

            block_mig_state.submitted, block_mig_state.transferred);



    qemu_mutex_lock_iothread();

    init_blk_migration(f);



    /* start track dirty blocks */

    set_dirty_tracking();

    qemu_mutex_unlock_iothread();



    ret = flush_blks(f);

    blk_mig_reset_dirty_cursor();

    qemu_put_be64(f, BLK_MIG_FLAG_EOS);



    return ret;

}

static int block_save_complete(QEMUFile *f, void *opaque)

{

    int ret;



    DPRINTF("Enter save live complete submitted %d transferred %d\n",

            block_mig_state.submitted, block_mig_state.transferred);



    ret = flush_blks(f);

    if (ret) {

        blk_mig_cleanup();

        return ret;

    }



    blk_mig_reset_dirty_cursor();



    /* we know for sure that save bulk is completed and

       all async read completed */

    assert(block_mig_state.submitted == 0);



    do {

        ret = blk_mig_save_dirty_block(f, 0);

    } while (ret == 0);



    blk_mig_cleanup();

    if (ret) {

        return ret;

    }

    /* report completion */

    qemu_put_be64(f, (100 << BDRV_SECTOR_BITS) | BLK_MIG_FLAG_PROGRESS);



    DPRINTF("Block migration completed\n");



    qemu_put_be64(f, BLK_MIG_FLAG_EOS);



    return 0;

}

static int block_save_iterate(QEMUFile *f, void *opaque)

{

    int ret;



    DPRINTF("Enter save live iterate submitted %d transferred %d\n",

            block_mig_state.submitted, block_mig_state.transferred);



    ret = flush_blks(f);

    if (ret) {

        blk_mig_cleanup();

        return ret;

    }



    blk_mig_reset_dirty_cursor();



    /* control the rate of transfer */

    while ((block_mig_state.submitted +

            block_mig_state.read_done) * BLOCK_SIZE <

           qemu_file_get_rate_limit(f)) {

        if (block_mig_state.bulk_completed == 0) {

            /* first finish the bulk phase */

            if (blk_mig_save_bulked_block(f) == 0) {

                /* finished saving bulk on all devices */

                block_mig_state.bulk_completed = 1;

            }

        } else {

            ret = blk_mig_save_dirty_block(f, 1);

            if (ret != 0) {

                /* no more dirty blocks */

                break;

            }

        }

    }

    if (ret < 0) {

        blk_mig_cleanup();

        return ret;

    }



    ret = flush_blks(f);

    if (ret) {

        blk_mig_cleanup();

        return ret;

    }



    qemu_put_be64(f, BLK_MIG_FLAG_EOS);



    return 0;

}

static int matroska_parse_block(MatroskaDemuxContext *matroska, uint8_t *data,
                                int size, int64_t pos, uint64_t cluster_time,
                                uint64_t duration, int is_keyframe,
                                int64_t cluster_pos)
{
    uint64_t timecode = AV_NOPTS_VALUE;
    MatroskaTrack *track;
    int res = 0;
    AVStream *st;
    AVPacket *pkt;
    int16_t block_time;
    uint32_t *lace_size = NULL;
    int n, flags, laces = 0;
    uint64_t num;
