}

static void guess_mv(ERContext *s)

{

    uint8_t *fixed = s->er_temp_buffer;

#define MV_FROZEN    3

#define MV_CHANGED   2

#define MV_UNCHANGED 1

    const int mb_stride = s->mb_stride;

    const int mb_width  = s->mb_width;

    const int mb_height = s->mb_height;

    int i, depth, num_avail;

    int mb_x, mb_y, mot_step, mot_stride;



    set_mv_strides(s, &mot_step, &mot_stride);



    num_avail = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int f = 0;

        int error = s->error_status_table[mb_xy];



        if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

            f = MV_FROZEN; // intra // FIXME check

        if (!(error & ER_MV_ERROR))

            f = MV_FROZEN; // inter with undamaged MV



        fixed[mb_xy] = f;

        if (f == MV_FROZEN)

            num_avail++;

    }



    if ((!(s->avctx->error_concealment&FF_EC_GUESS_MVS)) ||

        num_avail <= mb_width / 2) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                const int mb_xy = mb_x + mb_y * s->mb_stride;

                int mv_dir = (s->last_pic.f && s->last_pic.f->data[0]) ? MV_DIR_FORWARD : MV_DIR_BACKWARD;



                if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

                    continue;

                if (!(s->error_status_table[mb_xy] & ER_MV_ERROR))

                    continue;



                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->decode_mb(s->opaque, 0, mv_dir, MV_TYPE_16X16, &s->mv,

                             mb_x, mb_y, 0, 0);

            }

        }

        return;

    }



    for (depth = 0; ; depth++) {

        int changed, pass, none_left;



        none_left = 1;

        changed   = 1;

        for (pass = 0; (changed || pass < 2) && pass < 10; pass++) {

            int mb_x, mb_y;

            int score_sum = 0;



            changed = 0;

            for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

                for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                    const int mb_xy        = mb_x + mb_y * s->mb_stride;

                    int mv_predictor[8][2] = { { 0 } };

                    int ref[8]             = { 0 };

                    int pred_count         = 0;

                    int j;

                    int best_score         = 256 * 256 * 256 * 64;

                    int best_pred          = 0;

                    const int mot_index    = (mb_x + mb_y * mot_stride) * mot_step;

                    int prev_x, prev_y, prev_ref;



                    if ((mb_x ^ mb_y ^ pass) & 1)

                        continue;



                    if (fixed[mb_xy] == MV_FROZEN)

                        continue;

                    assert(!IS_INTRA(s->cur_pic.mb_type[mb_xy]));

                    assert(s->last_pic && s->last_pic.f->data[0]);



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_FROZEN)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_FROZEN)

                        j = 1;

                    if (j == 0)

                        continue;



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_CHANGED)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_CHANGED)

                        j = 1;

                    if (j == 0 && pass > 1)

                        continue;



                    none_left = 0;



                    if (mb_x > 0 && fixed[mb_xy - 1]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index - mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index - mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy - 1)];

                        pred_count++;

                    }

                    if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index + mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index + mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy + 1)];

                        pred_count++;

                    }

                    if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index - mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index - mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy - s->mb_stride)];

                        pred_count++;

                    }

                    if (mb_y + 1<mb_height && fixed[mb_xy + mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index + mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index + mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy + s->mb_stride)];

                        pred_count++;

                    }

                    if (pred_count == 0)

                        continue;



                    if (pred_count > 1) {

                        int sum_x = 0, sum_y = 0, sum_r = 0;

                        int max_x, max_y, min_x, min_y, max_r, min_r;



                        for (j = 0; j < pred_count; j++) {

                            sum_x += mv_predictor[j][0];

                            sum_y += mv_predictor[j][1];

                            sum_r += ref[j];

                            if (j && ref[j] != ref[j - 1])

                                goto skip_mean_and_median;

                        }



                        /* mean */

                        mv_predictor[pred_count][0] = sum_x / j;

                        mv_predictor[pred_count][1] = sum_y / j;

                                 ref[pred_count]    = sum_r / j;



                        /* median */

                        if (pred_count >= 3) {

                            min_y = min_x = min_r =  99999;

                            max_y = max_x = max_r = -99999;

                        } else {

                            min_x = min_y = max_x = max_y = min_r = max_r = 0;

                        }

                        for (j = 0; j < pred_count; j++) {

                            max_x = FFMAX(max_x, mv_predictor[j][0]);

                            max_y = FFMAX(max_y, mv_predictor[j][1]);

                            max_r = FFMAX(max_r, ref[j]);

                            min_x = FFMIN(min_x, mv_predictor[j][0]);

                            min_y = FFMIN(min_y, mv_predictor[j][1]);

                            min_r = FFMIN(min_r, ref[j]);

                        }

                        mv_predictor[pred_count + 1][0] = sum_x - max_x - min_x;

                        mv_predictor[pred_count + 1][1] = sum_y - max_y - min_y;

                                 ref[pred_count + 1]    = sum_r - max_r - min_r;



                        if (pred_count == 4) {

                            mv_predictor[pred_count + 1][0] /= 2;

                            mv_predictor[pred_count + 1][1] /= 2;

                                     ref[pred_count + 1]    /= 2;

                        }

                        pred_count += 2;

                    }



skip_mean_and_median:

                    /* zero MV */

                    pred_count++;



                    if (!fixed[mb_xy]) {

                        if (s->avctx->codec_id == AV_CODEC_ID_H264) {

                            // FIXME

                        } else {

                            ff_thread_await_progress(s->last_pic.tf,

                                                     mb_y, 0);

                        }

                        if (!s->last_pic.motion_val[0] ||

                            !s->last_pic.ref_index[0])

                            goto skip_last_mv;

                        prev_x   = s->last_pic.motion_val[0][mot_index][0];

                        prev_y   = s->last_pic.motion_val[0][mot_index][1];

                        prev_ref = s->last_pic.ref_index[0][4 * mb_xy];

                    } else {

                        prev_x   = s->cur_pic.motion_val[0][mot_index][0];

                        prev_y   = s->cur_pic.motion_val[0][mot_index][1];

                        prev_ref = s->cur_pic.ref_index[0][4 * mb_xy];

                    }



                    /* last MV */

                    mv_predictor[pred_count][0] = prev_x;

                    mv_predictor[pred_count][1] = prev_y;

                             ref[pred_count]    = prev_ref;

                    pred_count++;



skip_last_mv:



                    for (j = 0; j < pred_count; j++) {

                        int *linesize = s->cur_pic.f->linesize;

                        int score = 0;

                        uint8_t *src = s->cur_pic.f->data[0] +

                                       mb_x * 16 + mb_y * 16 * linesize[0];



                        s->cur_pic.motion_val[0][mot_index][0] =

                            s->mv[0][0][0] = mv_predictor[j][0];

                        s->cur_pic.motion_val[0][mot_index][1] =

                            s->mv[0][0][1] = mv_predictor[j][1];



                        // predictor intra or otherwise not available

                        if (ref[j] < 0)

                            continue;



                        s->decode_mb(s->opaque, ref[j], MV_DIR_FORWARD,

                                     MV_TYPE_16X16, &s->mv, mb_x, mb_y, 0, 0);



                        if (mb_x > 0 && fixed[mb_xy - 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * linesize[0] - 1] -

                                               src[k * linesize[0]]);

                        }

                        if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * linesize[0] + 15] -

                                               src[k * linesize[0] + 16]);

                        }

                        if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k - linesize[0]] - src[k]);

                        }

                        if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k + linesize[0] * 15] -

                                               src[k + linesize[0] * 16]);

                        }



                        if (score <= best_score) { // <= will favor the last MV

                            best_score = score;

                            best_pred  = j;

                        }

                    }

                    score_sum += best_score;

                    s->mv[0][0][0] = mv_predictor[best_pred][0];

                    s->mv[0][0][1] = mv_predictor[best_pred][1];



                    for (i = 0; i < mot_step; i++)

                        for (j = 0; j < mot_step; j++) {

                            s->cur_pic.motion_val[0][mot_index + i + j * mot_stride][0] = s->mv[0][0][0];

                            s->cur_pic.motion_val[0][mot_index + i + j * mot_stride][1] = s->mv[0][0][1];

                        }



                    s->decode_mb(s->opaque, ref[best_pred], MV_DIR_FORWARD,

                                 MV_TYPE_16X16, &s->mv, mb_x, mb_y, 0, 0);





                    if (s->mv[0][0][0] != prev_x || s->mv[0][0][1] != prev_y) {

                        fixed[mb_xy] = MV_CHANGED;

                        changed++;

                    } else

                        fixed[mb_xy] = MV_UNCHANGED;

                }

            }

        }



        if (none_left)

            return;



        for (i = 0; i < s->mb_num; i++) {

            int mb_xy = s->mb_index2xy[i];

            if (fixed[mb_xy])

                fixed[mb_xy] = MV_FROZEN;

        }

    }

}

static void adjust_frame_information(ChannelElement *cpe, int chans)

{

    int i, w, w2, g, ch;

    int start, maxsfb, cmaxsfb;



    for (ch = 0; ch < chans; ch++) {

        IndividualChannelStream *ics = &cpe->ch[ch].ics;

        start = 0;

        maxsfb = 0;

        cpe->ch[ch].pulse.num_pulse = 0;

        for (w = 0; w < ics->num_windows*16; w += 16) {

            for (g = 0; g < ics->num_swb; g++) {

                //apply M/S

                if (cpe->common_window && !ch && cpe->ms_mask[w + g]) {

                    for (i = 0; i < ics->swb_sizes[g]; i++) {

                        cpe->ch[0].coeffs[start+i] = (cpe->ch[0].coeffs[start+i] + cpe->ch[1].coeffs[start+i]) / 2.0;

                        cpe->ch[1].coeffs[start+i] =  cpe->ch[0].coeffs[start+i] - cpe->ch[1].coeffs[start+i];

                    }

                }

                start += ics->swb_sizes[g];

            }

            for (cmaxsfb = ics->num_swb; cmaxsfb > 0 && cpe->ch[ch].zeroes[w+cmaxsfb-1]; cmaxsfb--)

                ;

            maxsfb = FFMAX(maxsfb, cmaxsfb);

        }

        ics->max_sfb = maxsfb;



        //adjust zero bands for window groups

        for (w = 0; w < ics->num_windows; w += ics->group_len[w]) {

            for (g = 0; g < ics->max_sfb; g++) {

                i = 1;

                for (w2 = w; w2 < w + ics->group_len[w]; w2++) {

                    if (!cpe->ch[ch].zeroes[w2*16 + g]) {

                        i = 0;

                        break;

                    }

                }

                cpe->ch[ch].zeroes[w*16 + g] = i;

            }

        }

    }



    if (chans > 1 && cpe->common_window) {

        IndividualChannelStream *ics0 = &cpe->ch[0].ics;

        IndividualChannelStream *ics1 = &cpe->ch[1].ics;

        int msc = 0;

        ics0->max_sfb = FFMAX(ics0->max_sfb, ics1->max_sfb);

        ics1->max_sfb = ics0->max_sfb;

        for (w = 0; w < ics0->num_windows*16; w += 16)

            for (i = 0; i < ics0->max_sfb; i++)

                if (cpe->ms_mask[w+i])

                    msc++;

        if (msc == 0 || ics0->max_sfb == 0)

            cpe->ms_mode = 0;

        else

            cpe->ms_mode = msc < ics0->max_sfb * ics0->num_windows ? 1 : 2;

    }

}

static int is_intra_more_likely(MpegEncContext *s){

    int is_intra_likely, i, j, undamaged_count, skip_amount, mb_x, mb_y;



    if (!s->last_picture_ptr || !s->last_picture_ptr->f.data[0]) return 1; //no previous frame available -> use spatial prediction



    undamaged_count=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        const int error= s->error_status_table[mb_xy];

        if(!((error&DC_ERROR) && (error&MV_ERROR)))

            undamaged_count++;

    }



    if(s->codec_id == CODEC_ID_H264){

        H264Context *h= (void*)s;

        if (h->ref_count[0] <= 0 || !h->ref_list[0][0].f.data[0])

            return 1;

    }



    if(undamaged_count < 5) return 0; //almost all MBs damaged -> use temporal prediction



    //prevent dsp.sad() check, that requires access to the image

    if(CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration && s->pict_type == AV_PICTURE_TYPE_I)

        return 1;



    skip_amount= FFMAX(undamaged_count/50, 1); //check only upto 50 MBs

    is_intra_likely=0;



    j=0;

    for(mb_y= 0; mb_y<s->mb_height-1; mb_y++){

        for(mb_x= 0; mb_x<s->mb_width; mb_x++){

            int error;

            const int mb_xy= mb_x + mb_y*s->mb_stride;



            error= s->error_status_table[mb_xy];

            if((error&DC_ERROR) && (error&MV_ERROR))

                continue; //skip damaged



            j++;

            if((j%skip_amount) != 0) continue; //skip a few to speed things up



            if(s->pict_type==AV_PICTURE_TYPE_I){

                uint8_t *mb_ptr     = s->current_picture.f.data[0] + mb_x*16 + mb_y*16*s->linesize;

                uint8_t *last_mb_ptr= s->last_picture.f.data   [0] + mb_x*16 + mb_y*16*s->linesize;



                if (s->avctx->codec_id == CODEC_ID_H264) {

                    // FIXME

                } else {

                    ff_thread_await_progress((AVFrame *) s->last_picture_ptr,

                                             mb_y, 0);

                }

                is_intra_likely += s->dsp.sad[0](NULL, last_mb_ptr, mb_ptr                    , s->linesize, 16);

                // FIXME need await_progress() here

                is_intra_likely -= s->dsp.sad[0](NULL, last_mb_ptr, last_mb_ptr+s->linesize*16, s->linesize, 16);

            }else{

                if (IS_INTRA(s->current_picture.f.mb_type[mb_xy]))

                   is_intra_likely++;

                else

                   is_intra_likely--;

            }

        }

    }

//printf("is_intra_likely: %d type:%d\n", is_intra_likely, s->pict_type);

    return is_intra_likely > 0;

}

static void guess_mv(MpegEncContext *s)

{

    uint8_t *fixed = av_malloc(s->mb_stride * s->mb_height);

#define MV_FROZEN    3

#define MV_CHANGED   2

#define MV_UNCHANGED 1

    const int mb_stride = s->mb_stride;

    const int mb_width  = s->mb_width;

    const int mb_height = s->mb_height;

    int i, depth, num_avail;

    int mb_x, mb_y, mot_step, mot_stride;



    set_mv_strides(s, &mot_step, &mot_stride);



    num_avail = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int f = 0;

        int error = s->error_status_table[mb_xy];



        if (IS_INTRA(s->current_picture.f.mb_type[mb_xy]))

            f = MV_FROZEN; // intra // FIXME check

        if (!(error & ER_MV_ERROR))

            f = MV_FROZEN; // inter with undamaged MV



        fixed[mb_xy] = f;

        if (f == MV_FROZEN)

            num_avail++;

        else if(s->last_picture.f.data[0] && s->last_picture.f.motion_val[0]){

            const int mb_y= mb_xy / s->mb_stride;

            const int mb_x= mb_xy % s->mb_stride;

            const int mot_index= (mb_x + mb_y*mot_stride) * mot_step;

            s->current_picture.f.motion_val[0][mot_index][0]= s->last_picture.f.motion_val[0][mot_index][0];

            s->current_picture.f.motion_val[0][mot_index][1]= s->last_picture.f.motion_val[0][mot_index][1];

            s->current_picture.f.ref_index[0][4*mb_xy]      = s->last_picture.f.ref_index[0][4*mb_xy];

        }

    }



    if ((!(s->avctx->error_concealment&FF_EC_GUESS_MVS)) ||

        num_avail <= mb_width / 2) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            s->mb_x = 0;

            s->mb_y = mb_y;

            ff_init_block_index(s);

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                const int mb_xy = mb_x + mb_y * s->mb_stride;



                ff_update_block_index(s);



                if (IS_INTRA(s->current_picture.f.mb_type[mb_xy]))

                    continue;

                if (!(s->error_status_table[mb_xy] & ER_MV_ERROR))

                    continue;



                s->mv_dir     = s->last_picture.f.data[0] ? MV_DIR_FORWARD

                                                          : MV_DIR_BACKWARD;

                s->mb_intra   = 0;

                s->mv_type    = MV_TYPE_16X16;

                s->mb_skipped = 0;



                s->dsp.clear_blocks(s->block[0]);



                s->mb_x        = mb_x;

                s->mb_y        = mb_y;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                decode_mb(s, 0);

            }

        }

        goto end;

    }



    for (depth = 0; ; depth++) {

        int changed, pass, none_left;



        none_left = 1;

        changed   = 1;

        for (pass = 0; (changed || pass < 2) && pass < 10; pass++) {

            int mb_x, mb_y;

            int score_sum = 0;



            changed = 0;

            for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

                s->mb_x = 0;

                s->mb_y = mb_y;

                ff_init_block_index(s);

                for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                    const int mb_xy        = mb_x + mb_y * s->mb_stride;

                    int mv_predictor[8][2] = { { 0 } };

                    int ref[8]             = { 0 };

                    int pred_count         = 0;

                    int j;

                    int best_score         = 256 * 256 * 256 * 64;

                    int best_pred          = 0;

                    const int mot_index    = (mb_x + mb_y * mot_stride) * mot_step;

                    int prev_x, prev_y, prev_ref;



                    ff_update_block_index(s);



                    if ((mb_x ^ mb_y ^ pass) & 1)

                        continue;



                    if (fixed[mb_xy] == MV_FROZEN)

                        continue;

                    assert(!IS_INTRA(s->current_picture.f.mb_type[mb_xy]));

                    assert(s->last_picture_ptr && s->last_picture_ptr->f.data[0]);



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_FROZEN)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_FROZEN)

                        j = 1;

                    if (j == 0)

                        continue;



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_CHANGED)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_CHANGED)

                        j = 1;

                    if (j == 0 && pass > 1)

                        continue;



                    none_left = 0;



                    if (mb_x > 0 && fixed[mb_xy - 1]) {

                        mv_predictor[pred_count][0] =

                            s->current_picture.f.motion_val[0][mot_index - mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->current_picture.f.motion_val[0][mot_index - mot_step][1];

                        ref[pred_count] =

                            s->current_picture.f.ref_index[0][4 * (mb_xy - 1)];

                        pred_count++;

                    }

                    if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                        mv_predictor[pred_count][0] =

                            s->current_picture.f.motion_val[0][mot_index + mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->current_picture.f.motion_val[0][mot_index + mot_step][1];

                        ref[pred_count] =

                            s->current_picture.f.ref_index[0][4 * (mb_xy + 1)];

                        pred_count++;

                    }

                    if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->current_picture.f.motion_val[0][mot_index - mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->current_picture.f.motion_val[0][mot_index - mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->current_picture.f.ref_index[0][4 * (mb_xy - s->mb_stride)];

                        pred_count++;

                    }

                    if (mb_y + 1<mb_height && fixed[mb_xy + mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->current_picture.f.motion_val[0][mot_index + mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->current_picture.f.motion_val[0][mot_index + mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->current_picture.f.ref_index[0][4 * (mb_xy + s->mb_stride)];

                        pred_count++;

                    }

                    if (pred_count == 0)

                        continue;



                    if (pred_count > 1) {

                        int sum_x = 0, sum_y = 0, sum_r = 0;

                        int max_x, max_y, min_x, min_y, max_r, min_r;



                        for (j = 0; j < pred_count; j++) {

                            sum_x += mv_predictor[j][0];

                            sum_y += mv_predictor[j][1];

                            sum_r += ref[j];

                            if (j && ref[j] != ref[j - 1])

                                goto skip_mean_and_median;

                        }



                        /* mean */

                        mv_predictor[pred_count][0] = sum_x / j;

                        mv_predictor[pred_count][1] = sum_y / j;

                                 ref[pred_count]    = sum_r / j;



                        /* median */

                        if (pred_count >= 3) {

                            min_y = min_x = min_r =  99999;

                            max_y = max_x = max_r = -99999;

                        } else {

                            min_x = min_y = max_x = max_y = min_r = max_r = 0;

                        }

                        for (j = 0; j < pred_count; j++) {

                            max_x = FFMAX(max_x, mv_predictor[j][0]);

                            max_y = FFMAX(max_y, mv_predictor[j][1]);

                            max_r = FFMAX(max_r, ref[j]);

                            min_x = FFMIN(min_x, mv_predictor[j][0]);

                            min_y = FFMIN(min_y, mv_predictor[j][1]);

                            min_r = FFMIN(min_r, ref[j]);

                        }

                        mv_predictor[pred_count + 1][0] = sum_x - max_x - min_x;

                        mv_predictor[pred_count + 1][1] = sum_y - max_y - min_y;

                                 ref[pred_count + 1]    = sum_r - max_r - min_r;



                        if (pred_count == 4) {

                            mv_predictor[pred_count + 1][0] /= 2;

                            mv_predictor[pred_count + 1][1] /= 2;

                                     ref[pred_count + 1]    /= 2;

                        }

                        pred_count += 2;

                    }



skip_mean_and_median:

                    /* zero MV */

                    pred_count++;



                    if (!fixed[mb_xy] && 0) {

                        if (s->avctx->codec_id == CODEC_ID_H264) {

                            // FIXME

                        } else {

                            ff_thread_await_progress(&s->last_picture_ptr->f,

                                                     mb_y, 0);

                        }

                        if (!s->last_picture.f.motion_val[0] ||

                            !s->last_picture.f.ref_index[0])

                            goto skip_last_mv;

                        prev_x   = s->last_picture.f.motion_val[0][mot_index][0];

                        prev_y   = s->last_picture.f.motion_val[0][mot_index][1];

                        prev_ref = s->last_picture.f.ref_index[0][4 * mb_xy];

                    } else {

                        prev_x   = s->current_picture.f.motion_val[0][mot_index][0];

                        prev_y   = s->current_picture.f.motion_val[0][mot_index][1];

                        prev_ref = s->current_picture.f.ref_index[0][4 * mb_xy];

                    }



                    /* last MV */

                    mv_predictor[pred_count][0] = prev_x;

                    mv_predictor[pred_count][1] = prev_y;

                             ref[pred_count]    = prev_ref;

                    pred_count++;



skip_last_mv:

                    s->mv_dir     = MV_DIR_FORWARD;

                    s->mb_intra   = 0;

                    s->mv_type    = MV_TYPE_16X16;

                    s->mb_skipped = 0;



                    s->dsp.clear_blocks(s->block[0]);



                    s->mb_x = mb_x;

                    s->mb_y = mb_y;



                    for (j = 0; j < pred_count; j++) {

                        int score = 0;

                        uint8_t *src = s->current_picture.f.data[0] +

                                       mb_x * 16 + mb_y * 16 * s->linesize;



                        s->current_picture.f.motion_val[0][mot_index][0] =

                            s->mv[0][0][0] = mv_predictor[j][0];

                        s->current_picture.f.motion_val[0][mot_index][1] =

                            s->mv[0][0][1] = mv_predictor[j][1];



                        // predictor intra or otherwise not available

                        if (ref[j] < 0)

                            continue;



                        decode_mb(s, ref[j]);



                        if (mb_x > 0 && fixed[mb_xy - 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * s->linesize - 1] -

                                               src[k * s->linesize]);

                        }

                        if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * s->linesize + 15] -

                                               src[k * s->linesize + 16]);

                        }

                        if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k - s->linesize] - src[k]);

                        }

                        if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k + s->linesize * 15] -

                                               src[k + s->linesize * 16]);

                        }



                        if (score <= best_score) { // <= will favor the last MV

                            best_score = score;

                            best_pred  = j;

                        }

                    }

                    score_sum += best_score;

                    s->mv[0][0][0] = mv_predictor[best_pred][0];

                    s->mv[0][0][1] = mv_predictor[best_pred][1];



                    for (i = 0; i < mot_step; i++)

                        for (j = 0; j < mot_step; j++) {

                            s->current_picture.f.motion_val[0][mot_index + i + j * mot_stride][0] = s->mv[0][0][0];

                            s->current_picture.f.motion_val[0][mot_index + i + j * mot_stride][1] = s->mv[0][0][1];

                        }



                    decode_mb(s, ref[best_pred]);





                    if (s->mv[0][0][0] != prev_x || s->mv[0][0][1] != prev_y) {

                        fixed[mb_xy] = MV_CHANGED;

                        changed++;

                    } else

                        fixed[mb_xy] = MV_UNCHANGED;

                }

            }



            // printf(".%d/%d", changed, score_sum); fflush(stdout);

        }



        if (none_left)

            goto end;



        for (i = 0; i < s->mb_num; i++) {

            int mb_xy = s->mb_index2xy[i];

            if (fixed[mb_xy])

                fixed[mb_xy] = MV_FROZEN;

        }

        // printf(":"); fflush(stdout);

    }

end:

    av_free(fixed);

}

void av_parser_close(AVCodecParserContext *s)

{

    if(s){

        if (s->parser->parser_close) {

            ff_lock_avcodec(NULL);

            s->parser->parser_close(s);

            ff_unlock_avcodec();

        }

        av_free(s->priv_data);

        av_free(s);

    }

}

static void dash_free(AVFormatContext *s)
{
    DASHContext *c = s->priv_data;
    int i, j;
    if (c->as) {
        for (i = 0; i < c->nb_as; i++)
            av_dict_free(&c->as[i].metadata);
        av_freep(&c->as);
        c->nb_as = 0;
    }
    if (!c->streams)
        return;
    for (i = 0; i < s->nb_streams; i++) {
        OutputStream *os = &c->streams[i];
        if (os->ctx && os->ctx_inited)
            av_write_trailer(os->ctx);
        if (os->ctx && os->ctx->pb)
            ffio_free_dyn_buf(&os->ctx->pb);
        ff_format_io_close(s, &os->out);
        if (os->ctx)
            avformat_free_context(os->ctx);
        for (j = 0; j < os->nb_segments; j++)
            av_free(os->segments[j]);
        av_free(os->segments);
    }
    av_freep(&c->streams);
}

