static int device_open(AVFormatContext *ctx)

{

    struct v4l2_capability cap;

    int fd;

#if CONFIG_LIBV4L2

    int fd_libv4l;

#endif

    int res, err;

    int flags = O_RDWR;



    if (ctx->flags & AVFMT_FLAG_NONBLOCK) {

        flags |= O_NONBLOCK;

    }



    fd = v4l2_open(ctx->filename, flags, 0);

    if (fd < 0) {

        err = errno;



        av_log(ctx, AV_LOG_ERROR, "Cannot open video device %s : %s\n",

               ctx->filename, strerror(err));



        return AVERROR(err);

    }

#if CONFIG_LIBV4L2

    fd_libv4l = v4l2_fd_open(fd, 0);

    if (fd < 0) {

        err = AVERROR(errno);

        av_log(ctx, AV_LOG_ERROR, "Cannot open video device with libv4l neither %s : %s\n",

               ctx->filename, strerror(errno));

        return err;

    }

    fd = fd_libv4l;

#endif



    res = v4l2_ioctl(fd, VIDIOC_QUERYCAP, &cap);

    if (res < 0) {

        err = errno;

        av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_QUERYCAP): %s\n",

               strerror(err));



        goto fail;

    }



    av_log(ctx, AV_LOG_VERBOSE, "[%d]Capabilities: %x\n",

           fd, cap.capabilities);



    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {

        av_log(ctx, AV_LOG_ERROR, "Not a video capture device.\n");

        err = ENODEV;



        goto fail;

    }



    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {

        av_log(ctx, AV_LOG_ERROR,

               "The device does not support the streaming I/O method.\n");

        err = ENOSYS;



        goto fail;

    }



    return fd;



fail:

    v4l2_close(fd);

    return AVERROR(err);

}

static int mmap_init(AVFormatContext *ctx)

{

    int i, res;

    struct video_data *s = ctx->priv_data;

    struct v4l2_requestbuffers req = {

        .type   = V4L2_BUF_TYPE_VIDEO_CAPTURE,

        .count  = desired_video_buffers,

        .memory = V4L2_MEMORY_MMAP

    };



    res = ioctl(s->fd, VIDIOC_REQBUFS, &req);

    if (res < 0) {

        if (errno == EINVAL) {

            av_log(ctx, AV_LOG_ERROR, "Device does not support mmap\n");

        } else {

            av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_REQBUFS)\n");

        }



        return AVERROR(errno);

    }



    if (req.count < 2) {

        av_log(ctx, AV_LOG_ERROR, "Insufficient buffer memory\n");



        return AVERROR(ENOMEM);

    }

    s->buffers = req.count;

    s->buf_start = av_malloc(sizeof(void *) * s->buffers);

    if (s->buf_start == NULL) {

        av_log(ctx, AV_LOG_ERROR, "Cannot allocate buffer pointers\n");



        return AVERROR(ENOMEM);

    }

    s->buf_len = av_malloc(sizeof(unsigned int) * s->buffers);

    if (s->buf_len == NULL) {

        av_log(ctx, AV_LOG_ERROR, "Cannot allocate buffer sizes\n");

        av_free(s->buf_start);



        return AVERROR(ENOMEM);

    }



    for (i = 0; i < req.count; i++) {

        struct v4l2_buffer buf = {

            .type   = V4L2_BUF_TYPE_VIDEO_CAPTURE,

            .index  = i,

            .memory = V4L2_MEMORY_MMAP

        };



        res = ioctl(s->fd, VIDIOC_QUERYBUF, &buf);

        if (res < 0) {

            av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_QUERYBUF)\n");



            return AVERROR(errno);

        }



        s->buf_len[i] = buf.length;

        if (s->frame_size > 0 && s->buf_len[i] < s->frame_size) {

            av_log(ctx, AV_LOG_ERROR,

                   "Buffer len [%d] = %d != %d\n",

                   i, s->buf_len[i], s->frame_size);



            return -1;

        }

        s->buf_start[i] = mmap(NULL, buf.length,

                               PROT_READ | PROT_WRITE, MAP_SHARED,

                               s->fd, buf.m.offset);



        if (s->buf_start[i] == MAP_FAILED) {

            av_log(ctx, AV_LOG_ERROR, "mmap: %s\n", strerror(errno));



            return AVERROR(errno);

        }

    }



    return 0;

}

static int device_init(AVFormatContext *ctx, int *width, int *height,

                       uint32_t pix_fmt)

{

    struct video_data *s = ctx->priv_data;

    int fd = s->fd;

    struct v4l2_format fmt;

    struct v4l2_pix_format *pix = &fmt.fmt.pix;



    int res;



    memset(&fmt, 0, sizeof(struct v4l2_format));



    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    pix->width = *width;

    pix->height = *height;

    pix->pixelformat = pix_fmt;

    pix->field = V4L2_FIELD_ANY;



    res = ioctl(fd, VIDIOC_S_FMT, &fmt);



    if ((*width != fmt.fmt.pix.width) || (*height != fmt.fmt.pix.height)) {

        av_log(ctx, AV_LOG_INFO,

               "The V4L2 driver changed the video from %dx%d to %dx%d\n",

               *width, *height, fmt.fmt.pix.width, fmt.fmt.pix.height);

        *width = fmt.fmt.pix.width;

        *height = fmt.fmt.pix.height;

    }



    if (pix_fmt != fmt.fmt.pix.pixelformat) {

        av_log(ctx, AV_LOG_DEBUG,

               "The V4L2 driver changed the pixel format "

               "from 0x%08X to 0x%08X\n",

               pix_fmt, fmt.fmt.pix.pixelformat);

        res = -1;

    }



    if (fmt.fmt.pix.field == V4L2_FIELD_INTERLACED) {

        av_log(ctx, AV_LOG_DEBUG, "The V4L2 driver using the interlaced mode");

        s->interlaced = 1;

    }



    return res;

}

