static void sdhci_sdma_transfer_single_block(SDHCIState *s)

{

    int n;

    uint32_t datacnt = s->blksize & 0x0fff;



    if (s->trnmod & SDHC_TRNS_READ) {

        for (n = 0; n < datacnt; n++) {

            s->fifo_buffer[n] = sdbus_read_data(&s->sdbus);

        }

        dma_memory_write(&address_space_memory, s->sdmasysad, s->fifo_buffer,

                         datacnt);

    } else {

        dma_memory_read(&address_space_memory, s->sdmasysad, s->fifo_buffer,

                        datacnt);

        for (n = 0; n < datacnt; n++) {

            sdbus_write_data(&s->sdbus, s->fifo_buffer[n]);

        }

    }



    if (s->trnmod & SDHC_TRNS_BLK_CNT_EN) {

        s->blkcnt--;

    }



    sdhci_end_transfer(s);

}

static uint64_t omap_clkm_read(void *opaque, target_phys_addr_t addr,

                               unsigned size)

{

    struct omap_mpu_state_s *s = (struct omap_mpu_state_s *) opaque;



    if (size != 2) {

        return omap_badwidth_read16(opaque, addr);

    }



    switch (addr) {

    case 0x00:	/* ARM_CKCTL */

        return s->clkm.arm_ckctl;



    case 0x04:	/* ARM_IDLECT1 */

        return s->clkm.arm_idlect1;



    case 0x08:	/* ARM_IDLECT2 */

        return s->clkm.arm_idlect2;



    case 0x0c:	/* ARM_EWUPCT */

        return s->clkm.arm_ewupct;



    case 0x10:	/* ARM_RSTCT1 */

        return s->clkm.arm_rstct1;



    case 0x14:	/* ARM_RSTCT2 */

        return s->clkm.arm_rstct2;



    case 0x18:	/* ARM_SYSST */

        return (s->clkm.clocking_scheme << 11) | s->clkm.cold_start;



    case 0x1c:	/* ARM_CKOUT1 */

        return s->clkm.arm_ckout1;



    case 0x20:	/* ARM_CKOUT2 */

        break;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static uint64_t omap_mpuio_read(void *opaque, target_phys_addr_t addr,

                                unsigned size)

{

    struct omap_mpuio_s *s = (struct omap_mpuio_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;

    uint16_t ret;



    if (size != 2) {

        return omap_badwidth_read16(opaque, addr);

    }



    switch (offset) {

    case 0x00:	/* INPUT_LATCH */

        return s->inputs;



    case 0x04:	/* OUTPUT_REG */

        return s->outputs;



    case 0x08:	/* IO_CNTL */

        return s->dir;



    case 0x10:	/* KBR_LATCH */

        return s->row_latch;



    case 0x14:	/* KBC_REG */

        return s->cols;



    case 0x18:	/* GPIO_EVENT_MODE_REG */

        return s->event;



    case 0x1c:	/* GPIO_INT_EDGE_REG */

        return s->edge;



    case 0x20:	/* KBD_INT */

        return (~s->row_latch & 0x1f) && !s->kbd_mask;



    case 0x24:	/* GPIO_INT */

        ret = s->ints;

        s->ints &= s->mask;

        if (ret)

            qemu_irq_lower(s->irq);

        return ret;



    case 0x28:	/* KBD_MASKIT */

        return s->kbd_mask;



    case 0x2c:	/* GPIO_MASKIT */

        return s->mask;



    case 0x30:	/* GPIO_DEBOUNCING_REG */

        return s->debounce;



    case 0x34:	/* GPIO_LATCH_REG */

        return s->latch;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static uint64_t omap_tcmi_read(void *opaque, target_phys_addr_t addr,

                               unsigned size)

{

    struct omap_mpu_state_s *s = (struct omap_mpu_state_s *) opaque;

    uint32_t ret;



    if (size != 4) {

        return omap_badwidth_read32(opaque, addr);

    }



    switch (addr) {

    case 0x00:	/* IMIF_PRIO */

    case 0x04:	/* EMIFS_PRIO */

    case 0x08:	/* EMIFF_PRIO */

    case 0x0c:	/* EMIFS_CONFIG */

    case 0x10:	/* EMIFS_CS0_CONFIG */

    case 0x14:	/* EMIFS_CS1_CONFIG */

    case 0x18:	/* EMIFS_CS2_CONFIG */

    case 0x1c:	/* EMIFS_CS3_CONFIG */

    case 0x24:	/* EMIFF_MRS */

    case 0x28:	/* TIMEOUT1 */

    case 0x2c:	/* TIMEOUT2 */

    case 0x30:	/* TIMEOUT3 */

    case 0x3c:	/* EMIFF_SDRAM_CONFIG_2 */

    case 0x40:	/* EMIFS_CFG_DYN_WAIT */

        return s->tcmi_regs[addr >> 2];



    case 0x20:	/* EMIFF_SDRAM_CONFIG */

        ret = s->tcmi_regs[addr >> 2];

        s->tcmi_regs[addr >> 2] &= ~1; /* XXX: Clear SLRF on SDRAM access */

        /* XXX: We can try using the VGA_DIRTY flag for this */

        return ret;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static void omap_pin_cfg_write(void *opaque, target_phys_addr_t addr,

                               uint64_t value, unsigned size)

{

    struct omap_mpu_state_s *s = (struct omap_mpu_state_s *) opaque;

    uint32_t diff;



    if (size != 4) {

        return omap_badwidth_write32(opaque, addr, value);

    }



    switch (addr) {

    case 0x00:	/* FUNC_MUX_CTRL_0 */

        diff = s->func_mux_ctrl[addr >> 2] ^ value;

        s->func_mux_ctrl[addr >> 2] = value;

        omap_pin_funcmux0_update(s, diff, value);

        return;



    case 0x04:	/* FUNC_MUX_CTRL_1 */

        diff = s->func_mux_ctrl[addr >> 2] ^ value;

        s->func_mux_ctrl[addr >> 2] = value;

        omap_pin_funcmux1_update(s, diff, value);

        return;



    case 0x08:	/* FUNC_MUX_CTRL_2 */

        s->func_mux_ctrl[addr >> 2] = value;

        return;



    case 0x0c:	/* COMP_MODE_CTRL_0 */

        s->comp_mode_ctrl[0] = value;

        s->compat1509 = (value != 0x0000eaef);

        omap_pin_funcmux0_update(s, ~0, s->func_mux_ctrl[0]);

        omap_pin_funcmux1_update(s, ~0, s->func_mux_ctrl[1]);

        return;



    case 0x10:	/* FUNC_MUX_CTRL_3 */

    case 0x14:	/* FUNC_MUX_CTRL_4 */

    case 0x18:	/* FUNC_MUX_CTRL_5 */

    case 0x1c:	/* FUNC_MUX_CTRL_6 */

    case 0x20:	/* FUNC_MUX_CTRL_7 */

    case 0x24:	/* FUNC_MUX_CTRL_8 */

    case 0x28:	/* FUNC_MUX_CTRL_9 */

    case 0x2c:	/* FUNC_MUX_CTRL_A */

    case 0x30:	/* FUNC_MUX_CTRL_B */

    case 0x34:	/* FUNC_MUX_CTRL_C */

    case 0x38:	/* FUNC_MUX_CTRL_D */

        s->func_mux_ctrl[(addr >> 2) - 1] = value;

        return;



    case 0x40:	/* PULL_DWN_CTRL_0 */

    case 0x44:	/* PULL_DWN_CTRL_1 */

    case 0x48:	/* PULL_DWN_CTRL_2 */

    case 0x4c:	/* PULL_DWN_CTRL_3 */

        s->pull_dwn_ctrl[(addr & 0xf) >> 2] = value;

        return;



    case 0x50:	/* GATE_INH_CTRL_0 */

        s->gate_inh_ctrl[0] = value;

        return;



    case 0x60:	/* VOLTAGE_CTRL_0 */

        s->voltage_ctrl[0] = value;

        return;



    case 0x70:	/* TEST_DBG_CTRL_0 */

        s->test_dbg_ctrl[0] = value;

        return;



    case 0x80:	/* MOD_CONF_CTRL_0 */

        diff = s->mod_conf_ctrl[0] ^ value;

        s->mod_conf_ctrl[0] = value;

        omap_pin_modconf1_update(s, diff, value);

        return;



    default:

        OMAP_BAD_REG(addr);

    }

}

