static int find_tag(ByteIOContext *pb, uint32_t tag1)

{

    unsigned int tag;

    int size;



    for(;;) {

        if (url_feof(pb))

            return -1;

        tag = get_le32(pb);

        size = get_le32(pb);

        if (tag == tag1)

            break;

        url_fseek(pb, size, SEEK_CUR);

    }

    if (size < 0)

        size = 0x7fffffff;

    return size;

}

static int avi_load_index(AVFormatContext *s)

{

    AVIContext *avi = s->priv_data;

    ByteIOContext *pb = s->pb;

    uint32_t tag, size;

    int64_t pos= url_ftell(pb);



    url_fseek(pb, avi->movi_end, SEEK_SET);

#ifdef DEBUG_SEEK

    printf("movi_end=0x%"PRIx64"\n", avi->movi_end);

#endif

    for(;;) {

        if (url_feof(pb))

            break;

        tag = get_le32(pb);

        size = get_le32(pb);

#ifdef DEBUG_SEEK

        printf("tag=%c%c%c%c size=0x%x\n",

               tag & 0xff,

               (tag >> 8) & 0xff,

               (tag >> 16) & 0xff,

               (tag >> 24) & 0xff,

               size);

#endif

        switch(tag) {

        case MKTAG('i', 'd', 'x', '1'):

            if (avi_read_idx1(s, size) < 0)

                goto skip;

            else

                goto the_end;

            break;

        default:

        skip:

            size += (size & 1);

            url_fskip(pb, size);

            break;

        }

    }

 the_end:

    url_fseek(pb, pos, SEEK_SET);

    return 0;

}

static int read_line(AVIOContext * pb, char* line, int bufsize)

{

    int i;

    for (i = 0; i < bufsize - 1; i++) {

        int b = avio_r8(pb);

        if (b == 0)

            break;

        if (b == '\n') {

            line[i] = '\0';

            return 0;

        }

        line[i] = b;

    }

    line[i] = '\0';

    return -1;

}

static int check(AVIOContext *pb, int64_t pos, int64_t *out_pos)

{

    MPADecodeHeader mh = { 0 };

    int i;

    uint32_t header;

    int64_t off = 0;





    for (i = 0; i < SEEK_PACKETS; i++) {

        off = avio_seek(pb, pos + mh.frame_size, SEEK_SET);

        if (off < 0)

            break;



        header = avio_rb32(pb);



        if (ff_mpa_check_header(header) < 0 ||

            avpriv_mpegaudio_decode_header(&mh, header))

            break;

        out_pos[i] = off;

    }



    return i;

}

av_cold void ff_ac3dsp_init_x86(AC3DSPContext *c, int bit_exact)

{

    int mm_flags = av_get_cpu_flags();



    if (EXTERNAL_MMX(mm_flags)) {

        c->ac3_exponent_min = ff_ac3_exponent_min_mmx;

        c->ac3_max_msb_abs_int16 = ff_ac3_max_msb_abs_int16_mmx;

        c->ac3_lshift_int16 = ff_ac3_lshift_int16_mmx;

        c->ac3_rshift_int32 = ff_ac3_rshift_int32_mmx;

    }

    if (EXTERNAL_AMD3DNOW(mm_flags)) {

        c->extract_exponents = ff_ac3_extract_exponents_3dnow;

        if (!bit_exact) {

            c->float_to_fixed24 = ff_float_to_fixed24_3dnow;

        }

    }

    if (EXTERNAL_MMXEXT(mm_flags)) {

        c->ac3_exponent_min = ff_ac3_exponent_min_mmxext;

        c->ac3_max_msb_abs_int16 = ff_ac3_max_msb_abs_int16_mmxext;

    }

    if (EXTERNAL_SSE(mm_flags)) {

        c->float_to_fixed24 = ff_float_to_fixed24_sse;

    }

    if (EXTERNAL_SSE2(mm_flags)) {

        c->ac3_exponent_min = ff_ac3_exponent_min_sse2;

        c->ac3_max_msb_abs_int16 = ff_ac3_max_msb_abs_int16_sse2;

        c->float_to_fixed24 = ff_float_to_fixed24_sse2;

        c->compute_mantissa_size = ff_ac3_compute_mantissa_size_sse2;

        c->extract_exponents = ff_ac3_extract_exponents_sse2;

        if (!(mm_flags & AV_CPU_FLAG_SSE2SLOW)) {

            c->ac3_lshift_int16 = ff_ac3_lshift_int16_sse2;

            c->ac3_rshift_int32 = ff_ac3_rshift_int32_sse2;

        }

    }

    if (EXTERNAL_SSSE3(mm_flags)) {

        c->ac3_max_msb_abs_int16 = ff_ac3_max_msb_abs_int16_ssse3;

        if (!(mm_flags & AV_CPU_FLAG_ATOM)) {

            c->extract_exponents = ff_ac3_extract_exponents_ssse3;

        }

    }



#if HAVE_SSE_INLINE && HAVE_7REGS

    if (INLINE_SSE(mm_flags)) {

        c->downmix = ac3_downmix_sse;

    }

#endif

}

