static uint64_t omap2_inth_read(void *opaque, target_phys_addr_t addr,

                                unsigned size)

{

    struct omap_intr_handler_s *s = (struct omap_intr_handler_s *) opaque;

    int offset = addr;

    int bank_no, line_no;

    struct omap_intr_handler_bank_s *bank = NULL;



    if ((offset & 0xf80) == 0x80) {

        bank_no = (offset & 0x60) >> 5;

        if (bank_no < s->nbanks) {

            offset &= ~0x60;

            bank = &s->bank[bank_no];

        }

    }



    switch (offset) {

    case 0x00:	/* INTC_REVISION */

        return 0x21;



    case 0x10:	/* INTC_SYSCONFIG */

        return (s->autoidle >> 2) & 1;



    case 0x14:	/* INTC_SYSSTATUS */

        return 1;						/* RESETDONE */



    case 0x40:	/* INTC_SIR_IRQ */

        return s->sir_intr[0];



    case 0x44:	/* INTC_SIR_FIQ */

        return s->sir_intr[1];



    case 0x48:	/* INTC_CONTROL */

        return (!s->mask) << 2;					/* GLOBALMASK */



    case 0x4c:	/* INTC_PROTECTION */

        return 0;



    case 0x50:	/* INTC_IDLE */

        return s->autoidle & 3;



    /* Per-bank registers */

    case 0x80:	/* INTC_ITR */

        return bank->inputs;



    case 0x84:	/* INTC_MIR */

        return bank->mask;



    case 0x88:	/* INTC_MIR_CLEAR */

    case 0x8c:	/* INTC_MIR_SET */

        return 0;



    case 0x90:	/* INTC_ISR_SET */

        return bank->swi;



    case 0x94:	/* INTC_ISR_CLEAR */

        return 0;



    case 0x98:	/* INTC_PENDING_IRQ */

        return bank->irqs & ~bank->mask & ~bank->fiq;



    case 0x9c:	/* INTC_PENDING_FIQ */

        return bank->irqs & ~bank->mask & bank->fiq;



    /* Per-line registers */

    case 0x100 ... 0x300:	/* INTC_ILR */

        bank_no = (offset - 0x100) >> 7;

        if (bank_no > s->nbanks)

            break;

        bank = &s->bank[bank_no];

        line_no = (offset & 0x7f) >> 2;

        return (bank->priority[line_no] << 2) |

                ((bank->fiq >> line_no) & 1);

    }

    OMAP_BAD_REG(addr);

    return 0;

}

static uint64_t omap_rtc_read(void *opaque, target_phys_addr_t addr,

                              unsigned size)

{

    struct omap_rtc_s *s = (struct omap_rtc_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;

    uint8_t i;



    if (size != 1) {

        return omap_badwidth_read8(opaque, addr);

    }



    switch (offset) {

    case 0x00:	/* SECONDS_REG */

        return to_bcd(s->current_tm.tm_sec);



    case 0x04:	/* MINUTES_REG */

        return to_bcd(s->current_tm.tm_min);



    case 0x08:	/* HOURS_REG */

        if (s->pm_am)

            return ((s->current_tm.tm_hour > 11) << 7) |

                    to_bcd(((s->current_tm.tm_hour - 1) % 12) + 1);

        else

            return to_bcd(s->current_tm.tm_hour);



    case 0x0c:	/* DAYS_REG */

        return to_bcd(s->current_tm.tm_mday);



    case 0x10:	/* MONTHS_REG */

        return to_bcd(s->current_tm.tm_mon + 1);



    case 0x14:	/* YEARS_REG */

        return to_bcd(s->current_tm.tm_year % 100);



    case 0x18:	/* WEEK_REG */

        return s->current_tm.tm_wday;



    case 0x20:	/* ALARM_SECONDS_REG */

        return to_bcd(s->alarm_tm.tm_sec);



    case 0x24:	/* ALARM_MINUTES_REG */

        return to_bcd(s->alarm_tm.tm_min);



    case 0x28:	/* ALARM_HOURS_REG */

        if (s->pm_am)

            return ((s->alarm_tm.tm_hour > 11) << 7) |

                    to_bcd(((s->alarm_tm.tm_hour - 1) % 12) + 1);

        else

            return to_bcd(s->alarm_tm.tm_hour);



    case 0x2c:	/* ALARM_DAYS_REG */

        return to_bcd(s->alarm_tm.tm_mday);



    case 0x30:	/* ALARM_MONTHS_REG */

        return to_bcd(s->alarm_tm.tm_mon + 1);



    case 0x34:	/* ALARM_YEARS_REG */

        return to_bcd(s->alarm_tm.tm_year % 100);



    case 0x40:	/* RTC_CTRL_REG */

        return (s->pm_am << 3) | (s->auto_comp << 2) |

                (s->round << 1) | s->running;



    case 0x44:	/* RTC_STATUS_REG */

        i = s->status;

        s->status &= ~0x3d;

        return i;



    case 0x48:	/* RTC_INTERRUPTS_REG */

        return s->interrupts;



    case 0x4c:	/* RTC_COMP_LSB_REG */

        return ((uint16_t) s->comp_reg) & 0xff;



    case 0x50:	/* RTC_COMP_MSB_REG */

        return ((uint16_t) s->comp_reg) >> 8;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static uint64_t omap_pwl_read(void *opaque, target_phys_addr_t addr,

                              unsigned size)

{

    struct omap_pwl_s *s = (struct omap_pwl_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;



    if (size != 1) {

        return omap_badwidth_read8(opaque, addr);

    }



    switch (offset) {

    case 0x00:	/* PWL_LEVEL */

        return s->level;

    case 0x04:	/* PWL_CTRL */

        return s->enable;

    }

    OMAP_BAD_REG(addr);

    return 0;

}

static uint64_t omap_mpuio_read(void *opaque, target_phys_addr_t addr,

                                unsigned size)

{

    struct omap_mpuio_s *s = (struct omap_mpuio_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;

    uint16_t ret;



    if (size != 2) {

        return omap_badwidth_read16(opaque, addr);

    }



    switch (offset) {

    case 0x00:	/* INPUT_LATCH */

        return s->inputs;



    case 0x04:	/* OUTPUT_REG */

        return s->outputs;



    case 0x08:	/* IO_CNTL */

        return s->dir;



    case 0x10:	/* KBR_LATCH */

        return s->row_latch;



    case 0x14:	/* KBC_REG */

        return s->cols;



    case 0x18:	/* GPIO_EVENT_MODE_REG */

        return s->event;



    case 0x1c:	/* GPIO_INT_EDGE_REG */

        return s->edge;



    case 0x20:	/* KBD_INT */

        return (~s->row_latch & 0x1f) && !s->kbd_mask;



    case 0x24:	/* GPIO_INT */

        ret = s->ints;

        s->ints &= s->mask;

        if (ret)

            qemu_irq_lower(s->irq);

        return ret;



    case 0x28:	/* KBD_MASKIT */

        return s->kbd_mask;



    case 0x2c:	/* GPIO_MASKIT */

        return s->mask;



    case 0x30:	/* GPIO_DEBOUNCING_REG */

        return s->debounce;



    case 0x34:	/* GPIO_LATCH_REG */

        return s->latch;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

