static inline int halfpel_motion_search(MpegEncContext * s,

				  int *mx_ptr, int *my_ptr, int dmin,

				  int xmin, int ymin, int xmax, int ymax,

                                  int pred_x, int pred_y, uint8_t *ref_picture)

{

    UINT16 *mv_penalty= s->mv_penalty[s->f_code] + MAX_MV; // f_code of the prev frame

    const int quant= s->qscale;

    int pen_x, pen_y;

    int mx, my, mx1, my1, d, xx, yy, dminh;

    UINT8 *pix, *ptr;



    mx = *mx_ptr;

    my = *my_ptr;

    ptr = ref_picture + (my * s->linesize) + mx;



    xx = 16 * s->mb_x;

    yy = 16 * s->mb_y;

    pix =  s->new_picture[0] + (yy * s->linesize) + xx;



    dminh = dmin;



    if (mx > xmin && mx < xmax && 

        my > ymin && my < ymax) {



        mx= mx1= 2*(mx - xx);

        my= my1= 2*(my - yy);

        if(dmin < Z_THRESHOLD && mx==0 && my==0){

            *mx_ptr = 0;

            *my_ptr = 0;

            return dmin;

        }



        pen_x= pred_x + mx;

        pen_y= pred_y + my;



        ptr-= s->linesize;

        CHECK_HALF_MV(xy2, -1, -1)

        CHECK_HALF_MV(y2 ,  0, -1)

        CHECK_HALF_MV(xy2, +1, -1)



        ptr+= s->linesize;

        CHECK_HALF_MV(x2 , -1,  0)

        CHECK_HALF_MV(x2 , +1,  0)

        CHECK_HALF_MV(xy2, -1, +1)

        CHECK_HALF_MV(y2 ,  0, +1)

        CHECK_HALF_MV(xy2, +1, +1)



    }else{

        mx= 2*(mx - xx);

        my= 2*(my - yy);

    }



    *mx_ptr = mx;

    *my_ptr = my;

    return dminh;

}

static int v4l2_set_parameters(AVFormatContext *s1)

{

    struct video_data *s = s1->priv_data;

    struct v4l2_standard standard = { 0 };

    struct v4l2_streamparm streamparm = { 0 };

    struct v4l2_fract *tpf;

    AVRational framerate_q = { 0 };

    int i, ret;



    if (s->framerate &&

        (ret = av_parse_video_rate(&framerate_q, s->framerate)) < 0) {

        av_log(s1, AV_LOG_ERROR, "Could not parse framerate '%s'.\n",

               s->framerate);

        return ret;

    }



    if (s->standard) {

        if (s->std_id) {

            ret = 0;

            av_log(s1, AV_LOG_DEBUG, "Setting standard: %s\n", s->standard);

            /* set tv standard */

            for (i = 0; ; i++) {

                standard.index = i;

                if (v4l2_ioctl(s->fd, VIDIOC_ENUMSTD, &standard) < 0) {

                    ret = AVERROR(errno);

                    break;

                }

                if (!av_strcasecmp(standard.name, s->standard))

                    break;

            }

            if (ret < 0) {

                av_log(s1, AV_LOG_ERROR, "Unknown or unsupported standard '%s'\n", s->standard);

                return ret;

            }



            if (v4l2_ioctl(s->fd, VIDIOC_S_STD, &standard.id) < 0) {

                ret = AVERROR(errno);

                av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_S_STD): %s\n", av_err2str(ret));

                return ret;

            }

        } else {

            av_log(s1, AV_LOG_WARNING,

                   "This device does not support any standard\n");

        }

    }



    /* get standard */

    if (v4l2_ioctl(s->fd, VIDIOC_G_STD, &s->std_id) == 0) {

        tpf = &standard.frameperiod;

        for (i = 0; ; i++) {

            standard.index = i;

            if (v4l2_ioctl(s->fd, VIDIOC_ENUMSTD, &standard) < 0) {

                ret = AVERROR(errno);

                if (ret == AVERROR(EINVAL)) {

                    tpf = &streamparm.parm.capture.timeperframe;

                    break;

                }

                av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_ENUMSTD): %s\n", av_err2str(ret));

                return ret;

            }

            if (standard.id == s->std_id) {

                av_log(s1, AV_LOG_DEBUG,

                       "Current standard: %s, id: %"PRIx64", frameperiod: %d/%d\n",

                       standard.name, (uint64_t)standard.id, tpf->numerator, tpf->denominator);

                break;

            }

        }

    } else {

        tpf = &streamparm.parm.capture.timeperframe;

    }



    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (v4l2_ioctl(s->fd, VIDIOC_G_PARM, &streamparm) < 0) {

        ret = AVERROR(errno);

        av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_G_PARM): %s\n", av_err2str(ret));

        return ret;

    }



    if (framerate_q.num && framerate_q.den) {

        if (streamparm.parm.capture.capability & V4L2_CAP_TIMEPERFRAME) {

            tpf = &streamparm.parm.capture.timeperframe;



            av_log(s1, AV_LOG_DEBUG, "Setting time per frame to %d/%d\n",

                   framerate_q.den, framerate_q.num);

            tpf->numerator   = framerate_q.den;

            tpf->denominator = framerate_q.num;



            if (v4l2_ioctl(s->fd, VIDIOC_S_PARM, &streamparm) < 0) {

                ret = AVERROR(errno);

                av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_S_PARM): %s\n", av_err2str(ret));

                return ret;

            }



            if (framerate_q.num != tpf->denominator ||

                framerate_q.den != tpf->numerator) {

                av_log(s1, AV_LOG_INFO,

                       "The driver changed the time per frame from "

                       "%d/%d to %d/%d\n",

                       framerate_q.den, framerate_q.num,

                       tpf->numerator, tpf->denominator);

            }

        } else {

            av_log(s1, AV_LOG_WARNING,

                   "The driver does not allow to change time per frame\n");

        }

    }

    if (tpf->denominator > 0 && tpf->numerator > 0) {

        s1->streams[0]->avg_frame_rate.num = tpf->denominator;

        s1->streams[0]->avg_frame_rate.den = tpf->numerator;

        s1->streams[0]->r_frame_rate = s1->streams[0]->avg_frame_rate;

    } else

        av_log(s1, AV_LOG_WARNING, "Time per frame unknown\n");



    return 0;

}

enum AVPixelFormat avpriv_fmt_v4l2ff(uint32_t v4l2_fmt, enum AVCodecID codec_id)

{

    int i;



    for (i = 0; avpriv_fmt_conversion_table[i].codec_id != AV_CODEC_ID_NONE; i++) {

        if (avpriv_fmt_conversion_table[i].v4l2_fmt == v4l2_fmt &&

            avpriv_fmt_conversion_table[i].codec_id == codec_id) {

            return avpriv_fmt_conversion_table[i].ff_fmt;

        }

    }



    return AV_PIX_FMT_NONE;

}

static int device_init(AVFormatContext *ctx, int *width, int *height,

                       uint32_t pix_fmt)

{

    struct video_data *s = ctx->priv_data;

    int fd = s->fd;

    struct v4l2_format fmt;

    struct v4l2_pix_format *pix = &fmt.fmt.pix;



    int res;



    memset(&fmt, 0, sizeof(struct v4l2_format));



    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    pix->width = *width;

    pix->height = *height;

    pix->pixelformat = pix_fmt;

    pix->field = V4L2_FIELD_ANY;



    res = ioctl(fd, VIDIOC_S_FMT, &fmt);



    if ((*width != fmt.fmt.pix.width) || (*height != fmt.fmt.pix.height)) {

        av_log(ctx, AV_LOG_INFO,

               "The V4L2 driver changed the video from %dx%d to %dx%d\n",

               *width, *height, fmt.fmt.pix.width, fmt.fmt.pix.height);

        *width = fmt.fmt.pix.width;

        *height = fmt.fmt.pix.height;

    }



    if (pix_fmt != fmt.fmt.pix.pixelformat) {

        av_log(ctx, AV_LOG_DEBUG,

               "The V4L2 driver changed the pixel format "

               "from 0x%08X to 0x%08X\n",

               pix_fmt, fmt.fmt.pix.pixelformat);

        res = -1;

    }



    if (fmt.fmt.pix.field == V4L2_FIELD_INTERLACED) {

        av_log(ctx, AV_LOG_DEBUG, "The V4L2 driver using the interlaced mode");

        s->interlaced = 1;

    }



    return res;

}

static int dnxhd_decode_frame(AVCodecContext *avctx, void *data,

                              int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    DNXHDContext *ctx = avctx->priv_data;

    ThreadFrame frame = { .f = data };

    AVFrame *picture = data;

    int first_field = 1;

    int ret, i;



    ff_dlog(avctx, "frame size %d\n", buf_size);



decode_coding_unit:

    if ((ret = dnxhd_decode_header(ctx, picture, buf, buf_size, first_field)) < 0)

        return ret;



    if ((avctx->width || avctx->height) &&

        (ctx->width != avctx->width || ctx->height != avctx->height)) {

        av_log(avctx, AV_LOG_WARNING, "frame size changed: %dx%d -> %dx%d\n",

               avctx->width, avctx->height, ctx->width, ctx->height);

        first_field = 1;

    }

    if (avctx->pix_fmt != AV_PIX_FMT_NONE && avctx->pix_fmt != ctx->pix_fmt) {

        av_log(avctx, AV_LOG_WARNING, "pix_fmt changed: %s -> %s\n",

               av_get_pix_fmt_name(avctx->pix_fmt), av_get_pix_fmt_name(ctx->pix_fmt));

        first_field = 1;

    }



    avctx->pix_fmt = ctx->pix_fmt;

    ret = ff_set_dimensions(avctx, ctx->width, ctx->height);

    if (ret < 0)

        return ret;



    if (first_field) {

        if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0)

            return ret;

        picture->pict_type = AV_PICTURE_TYPE_I;

        picture->key_frame = 1;

    }



    ctx->buf_size = buf_size - 0x280;

    ctx->buf = buf + 0x280;

    avctx->execute2(avctx, dnxhd_decode_row, picture, NULL, ctx->mb_height);



    if (first_field && picture->interlaced_frame) {

        buf      += ctx->cid_table->coding_unit_size;

        buf_size -= ctx->cid_table->coding_unit_size;

        first_field = 0;

        goto decode_coding_unit;

    }



    ret = 0;

    for (i = 0; i < avctx->thread_count; i++) {

        ret += ctx->rows[i].errors;

        ctx->rows[i].errors = 0;

    }



    if (ret) {

        av_log(ctx->avctx, AV_LOG_ERROR, "%d lines with errors\n", ret);

        return AVERROR_INVALIDDATA;

    }



    *got_frame = 1;

    return avpkt->size;

}

static void lsi_reg_writeb(LSIState *s, int offset, uint8_t val)

{

#define CASE_SET_REG24(name, addr) \

    case addr    : s->name &= 0xffffff00; s->name |= val;       break; \

    case addr + 1: s->name &= 0xffff00ff; s->name |= val << 8;  break; \

    case addr + 2: s->name &= 0xff00ffff; s->name |= val << 16; break;



#define CASE_SET_REG32(name, addr) \

    case addr    : s->name &= 0xffffff00; s->name |= val;       break; \

    case addr + 1: s->name &= 0xffff00ff; s->name |= val << 8;  break; \

    case addr + 2: s->name &= 0xff00ffff; s->name |= val << 16; break; \

    case addr + 3: s->name &= 0x00ffffff; s->name |= val << 24; break;



#ifdef DEBUG_LSI_REG

    DPRINTF("Write reg %x = %02x\n", offset, val);

#endif

    switch (offset) {

    case 0x00: /* SCNTL0 */

        s->scntl0 = val;

        if (val & LSI_SCNTL0_START) {

            BADF("Start sequence not implemented\n");

        }

        break;

    case 0x01: /* SCNTL1 */

        s->scntl1 = val & ~LSI_SCNTL1_SST;

        if (val & LSI_SCNTL1_IARB) {

            BADF("Immediate Arbritration not implemented\n");

        }

        if (val & LSI_SCNTL1_RST) {

            if (!(s->sstat0 & LSI_SSTAT0_RST)) {

                BusChild *kid;



                QTAILQ_FOREACH(kid, &s->bus.qbus.children, sibling) {

                    DeviceState *dev = kid->child;

                    device_reset(dev);

                }

                s->sstat0 |= LSI_SSTAT0_RST;

                lsi_script_scsi_interrupt(s, LSI_SIST0_RST, 0);

            }

        } else {

            s->sstat0 &= ~LSI_SSTAT0_RST;

        }

        break;

    case 0x02: /* SCNTL2 */

        val &= ~(LSI_SCNTL2_WSR | LSI_SCNTL2_WSS);

        s->scntl2 = val;

        break;

    case 0x03: /* SCNTL3 */

        s->scntl3 = val;

        break;

    case 0x04: /* SCID */

        s->scid = val;

        break;

    case 0x05: /* SXFER */

        s->sxfer = val;

        break;

    case 0x06: /* SDID */

        if ((val & 0xf) != (s->ssid & 0xf))

            BADF("Destination ID does not match SSID\n");

        s->sdid = val & 0xf;

        break;

    case 0x07: /* GPREG0 */

        break;

    case 0x08: /* SFBR */

        /* The CPU is not allowed to write to this register.  However the

           SCRIPTS register move instructions are.  */

        s->sfbr = val;

        break;

    case 0x0a: case 0x0b:

        /* Openserver writes to these readonly registers on startup */

	return;

    case 0x0c: case 0x0d: case 0x0e: case 0x0f:

        /* Linux writes to these readonly registers on startup.  */

        return;

    CASE_SET_REG32(dsa, 0x10)

    case 0x14: /* ISTAT0 */

        s->istat0 = (s->istat0 & 0x0f) | (val & 0xf0);

        if (val & LSI_ISTAT0_ABRT) {

            lsi_script_dma_interrupt(s, LSI_DSTAT_ABRT);

        }

        if (val & LSI_ISTAT0_INTF) {

            s->istat0 &= ~LSI_ISTAT0_INTF;

            lsi_update_irq(s);

        }

        if (s->waiting == 1 && val & LSI_ISTAT0_SIGP) {

            DPRINTF("Woken by SIGP\n");

            s->waiting = 0;

            s->dsp = s->dnad;

            lsi_execute_script(s);

        }

        if (val & LSI_ISTAT0_SRST) {

            lsi_soft_reset(s);

        }

        break;

    case 0x16: /* MBOX0 */

        s->mbox0 = val;

        break;

    case 0x17: /* MBOX1 */

        s->mbox1 = val;

        break;

    case 0x1a: /* CTEST2 */

	s->ctest2 = val & LSI_CTEST2_PCICIE;

	break;

    case 0x1b: /* CTEST3 */

        s->ctest3 = val & 0x0f;

        break;

    CASE_SET_REG32(temp, 0x1c)

    case 0x21: /* CTEST4 */

        if (val & 7) {

           BADF("Unimplemented CTEST4-FBL 0x%x\n", val);

        }

        s->ctest4 = val;

        break;

    case 0x22: /* CTEST5 */

        if (val & (LSI_CTEST5_ADCK | LSI_CTEST5_BBCK)) {

            BADF("CTEST5 DMA increment not implemented\n");

        }

        s->ctest5 = val;

        break;

    CASE_SET_REG24(dbc, 0x24)

    CASE_SET_REG32(dnad, 0x28)

    case 0x2c: /* DSP[0:7] */

        s->dsp &= 0xffffff00;

        s->dsp |= val;

        break;

    case 0x2d: /* DSP[8:15] */

        s->dsp &= 0xffff00ff;

        s->dsp |= val << 8;

        break;

    case 0x2e: /* DSP[16:23] */

        s->dsp &= 0xff00ffff;

        s->dsp |= val << 16;

        break;

    case 0x2f: /* DSP[24:31] */

        s->dsp &= 0x00ffffff;

        s->dsp |= val << 24;

        if ((s->dmode & LSI_DMODE_MAN) == 0

            && (s->istat1 & LSI_ISTAT1_SRUN) == 0)

            lsi_execute_script(s);

        break;

    CASE_SET_REG32(dsps, 0x30)

    CASE_SET_REG32(scratch[0], 0x34)

    case 0x38: /* DMODE */

        if (val & (LSI_DMODE_SIOM | LSI_DMODE_DIOM)) {

            BADF("IO mappings not implemented\n");

        }

        s->dmode = val;

        break;

    case 0x39: /* DIEN */

        s->dien = val;

        lsi_update_irq(s);

        break;

    case 0x3a: /* SBR */

        s->sbr = val;

        break;

    case 0x3b: /* DCNTL */

        s->dcntl = val & ~(LSI_DCNTL_PFF | LSI_DCNTL_STD);

        if ((val & LSI_DCNTL_STD) && (s->istat1 & LSI_ISTAT1_SRUN) == 0)

            lsi_execute_script(s);

        break;

    case 0x40: /* SIEN0 */

        s->sien0 = val;

        lsi_update_irq(s);

        break;

    case 0x41: /* SIEN1 */

        s->sien1 = val;

        lsi_update_irq(s);

        break;

    case 0x47: /* GPCNTL0 */

        break;

    case 0x48: /* STIME0 */

        s->stime0 = val;

        break;

    case 0x49: /* STIME1 */

        if (val & 0xf) {

            DPRINTF("General purpose timer not implemented\n");

            /* ??? Raising the interrupt immediately seems to be sufficient

               to keep the FreeBSD driver happy.  */

            lsi_script_scsi_interrupt(s, 0, LSI_SIST1_GEN);

        }

        break;

    case 0x4a: /* RESPID0 */

        s->respid0 = val;

        break;

    case 0x4b: /* RESPID1 */

        s->respid1 = val;

        break;

    case 0x4d: /* STEST1 */

        s->stest1 = val;

        break;

    case 0x4e: /* STEST2 */

        if (val & 1) {

            BADF("Low level mode not implemented\n");

        }

        s->stest2 = val;

        break;

    case 0x4f: /* STEST3 */

        if (val & 0x41) {

            BADF("SCSI FIFO test mode not implemented\n");

        }

        s->stest3 = val;

        break;

    case 0x56: /* CCNTL0 */

        s->ccntl0 = val;

        break;

    case 0x57: /* CCNTL1 */

        s->ccntl1 = val;

        break;

    CASE_SET_REG32(mmrs, 0xa0)

    CASE_SET_REG32(mmws, 0xa4)

    CASE_SET_REG32(sfs, 0xa8)

    CASE_SET_REG32(drs, 0xac)

    CASE_SET_REG32(sbms, 0xb0)

    CASE_SET_REG32(dbms, 0xb4)

    CASE_SET_REG32(dnad64, 0xb8)

    CASE_SET_REG32(pmjad1, 0xc0)

    CASE_SET_REG32(pmjad2, 0xc4)

    CASE_SET_REG32(rbc, 0xc8)

    CASE_SET_REG32(ua, 0xcc)

    CASE_SET_REG32(ia, 0xd4)

    CASE_SET_REG32(sbc, 0xd8)

    CASE_SET_REG32(csbc, 0xdc)

    default:

        if (offset >= 0x5c && offset < 0xa0) {

            int n;

            int shift;

            n = (offset - 0x58) >> 2;

            shift = (offset & 3) * 8;

            s->scratch[n] &= ~(0xff << shift);

            s->scratch[n] |= (val & 0xff) << shift;

        } else {

            BADF("Unhandled writeb 0x%x = 0x%x\n", offset, val);

        }

    }

#undef CASE_SET_REG24

#undef CASE_SET_REG32

}

static void scsi_generic_purge_requests(SCSIGenericState *s)

{

    SCSIGenericReq *r;



    while (!QTAILQ_EMPTY(&s->qdev.requests)) {

        r = DO_UPCAST(SCSIGenericReq, req, QTAILQ_FIRST(&s->qdev.requests));

        if (r->req.aiocb) {

            bdrv_aio_cancel(r->req.aiocb);

        }

        scsi_remove_request(r);

    }

}

void net_tx_pkt_reset(struct NetTxPkt *pkt)

{

    int i;



    /* no assert, as reset can be called before tx_pkt_init */

    if (!pkt) {

        return;

    }



    memset(&pkt->virt_hdr, 0, sizeof(pkt->virt_hdr));



    g_free(pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_base);

    pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_base = NULL;



    assert(pkt->vec);

    for (i = NET_TX_PKT_L2HDR_FRAG;

         i < pkt->payload_frags + NET_TX_PKT_PL_START_FRAG; i++) {

        pkt->vec[i].iov_len = 0;

    }

    pkt->payload_len = 0;

    pkt->payload_frags = 0;



    assert(pkt->raw);

    for (i = 0; i < pkt->raw_frags; i++) {

        assert(pkt->raw[i].iov_base);

        cpu_physical_memory_unmap(pkt->raw[i].iov_base, pkt->raw[i].iov_len,

                                  false, pkt->raw[i].iov_len);

        pkt->raw[i].iov_len = 0;

    }

    pkt->raw_frags = 0;



    pkt->hdr_len = 0;

    pkt->packet_type = 0;

    pkt->l4proto = 0;

}

static void lsi_do_msgout(LSIState *s)

{

    uint8_t msg;

    int len;

    uint32_t current_tag;

    SCSIDevice *current_dev;

    lsi_request *p, *p_next;

    int id;



    if (s->current) {

        current_tag = s->current->tag;

    } else {

        current_tag = s->select_tag;

    }

    id = (current_tag >> 8) & 0xf;

    current_dev = s->bus.devs[id];



    DPRINTF("MSG out len=%d\n", s->dbc);

    while (s->dbc) {

        msg = lsi_get_msgbyte(s);

        s->sfbr = msg;



        switch (msg) {

        case 0x04:

            DPRINTF("MSG: Disconnect\n");

            lsi_disconnect(s);

            break;

        case 0x08:

            DPRINTF("MSG: No Operation\n");

            lsi_set_phase(s, PHASE_CMD);

            break;

        case 0x01:

            len = lsi_get_msgbyte(s);

            msg = lsi_get_msgbyte(s);

            (void)len; /* avoid a warning about unused variable*/

            DPRINTF("Extended message 0x%x (len %d)\n", msg, len);

            switch (msg) {

            case 1:

                DPRINTF("SDTR (ignored)\n");

                lsi_skip_msgbytes(s, 2);

                break;

            case 3:

                DPRINTF("WDTR (ignored)\n");

                lsi_skip_msgbytes(s, 1);

                break;

            default:

                goto bad;

            }

            break;

        case 0x20: /* SIMPLE queue */

            s->select_tag |= lsi_get_msgbyte(s) | LSI_TAG_VALID;

            DPRINTF("SIMPLE queue tag=0x%x\n", s->select_tag & 0xff);

            break;

        case 0x21: /* HEAD of queue */

            BADF("HEAD queue not implemented\n");

            s->select_tag |= lsi_get_msgbyte(s) | LSI_TAG_VALID;

            break;

        case 0x22: /* ORDERED queue */

            BADF("ORDERED queue not implemented\n");

            s->select_tag |= lsi_get_msgbyte(s) | LSI_TAG_VALID;

            break;

        case 0x0d:

            /* The ABORT TAG message clears the current I/O process only. */

            DPRINTF("MSG: ABORT TAG tag=0x%x\n", current_tag);

            current_dev->info->cancel_io(current_dev, current_tag);

            lsi_disconnect(s);

            break;

        case 0x06:

        case 0x0e:

        case 0x0c:

            /* The ABORT message clears all I/O processes for the selecting

               initiator on the specified logical unit of the target. */

            if (msg == 0x06) {

                DPRINTF("MSG: ABORT tag=0x%x\n", current_tag);

            }

            /* The CLEAR QUEUE message clears all I/O processes for all

               initiators on the specified logical unit of the target. */

            if (msg == 0x0e) {

                DPRINTF("MSG: CLEAR QUEUE tag=0x%x\n", current_tag);

            }

            /* The BUS DEVICE RESET message clears all I/O processes for all

               initiators on all logical units of the target. */

            if (msg == 0x0c) {

                DPRINTF("MSG: BUS DEVICE RESET tag=0x%x\n", current_tag);

            }



            /* clear the current I/O process */

            current_dev->info->cancel_io(current_dev, current_tag);



            /* As the current implemented devices scsi_disk and scsi_generic

               only support one LUN, we don't need to keep track of LUNs.

               Clearing I/O processes for other initiators could be possible

               for scsi_generic by sending a SG_SCSI_RESET to the /dev/sgX

               device, but this is currently not implemented (and seems not

               to be really necessary). So let's simply clear all queued

               commands for the current device: */

            id = current_tag & 0x0000ff00;

            QTAILQ_FOREACH_SAFE(p, &s->queue, next, p_next) {

                if ((p->tag & 0x0000ff00) == id) {

                    current_dev->info->cancel_io(current_dev, p->tag);

                    QTAILQ_REMOVE(&s->queue, p, next);

                }

            }



            lsi_disconnect(s);

            break;

        default:

            if ((msg & 0x80) == 0) {

                goto bad;

            }

            s->current_lun = msg & 7;

            DPRINTF("Select LUN %d\n", s->current_lun);

            lsi_set_phase(s, PHASE_CMD);

            break;

        }

    }

    return;

bad:

    BADF("Unimplemented message 0x%02x\n", msg);

    lsi_set_phase(s, PHASE_MI);

    lsi_add_msg_byte(s, 7); /* MESSAGE REJECT */

    s->msg_action = 0;

}

static void use_high_update_speed(WmallDecodeCtx *s, int ich)

{

    int ilms, recent, icoef;

    s->update_speed[ich] = 16;

    for (ilms = s->cdlms_ttl[ich]; ilms >= 0; ilms--) {

        recent = s->cdlms[ich][ilms].recent;

        if (s->bV3RTM) {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef + recent] *= 2;

        } else {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef] *= 2;

        }

    }

}

static void revert_cdlms(WmallDecodeCtx *s, int tile_size)

{

    int icoef, ich;

    int32_t pred, channel_coeff;

    int ilms, num_lms;



    for (ich = 0; ich < s->num_channels; ich++) {

        if (!s->is_channel_coded[ich])

            continue;

        for (icoef = 0; icoef < tile_size; icoef++) {

            num_lms = s->cdlms_ttl[ich];

            channel_coeff = s->channel_residues[ich][icoef];

            if (icoef == s->transient_pos[ich]) {

                s->transient[ich] = 1;

                use_high_update_speed(s, ich);

            }

            for (ilms = num_lms; ilms >= 0; ilms--) {

                pred = lms_predict(s, ich, ilms);

                channel_coeff += pred;

                lms_update(s, ich, ilms, channel_coeff, pred);

            }

            if (s->transient[ich]) {

                --s->channel[ich].transient_counter;

                if(!s->channel[ich].transient_counter)

                    use_normal_update_speed(s, ich);

            }

            s->channel_coeffs[ich][icoef] = channel_coeff;

        }

    }

}

static void ac3_downmix(AC3DecodeContext *s)

{

    int i, j;

    float v0, v1;



    for(i=0; i<256; i++) {

        v0 = v1 = 0.0f;

        for(j=0; j<s->fbw_channels; j++) {

            v0 += s->output[j][i] * s->downmix_coeffs[j][0];

            v1 += s->output[j][i] * s->downmix_coeffs[j][1];

        }

        v0 /= s->downmix_coeff_sum[0];

        v1 /= s->downmix_coeff_sum[1];

        if(s->output_mode == AC3_CHMODE_MONO) {

            s->output[0][i] = (v0 + v1) * LEVEL_MINUS_3DB;

        } else if(s->output_mode == AC3_CHMODE_STEREO) {

            s->output[0][i] = v0;

            s->output[1][i] = v1;

        }

    }

}

static void calc_transform_coeffs_cpl(AC3DecodeContext *s)

{

    int bin, band, ch, band_end;



    bin = s->start_freq[CPL_CH];

    for (band = 0; band < s->num_cpl_bands; band++) {

        band_end = bin + s->cpl_band_sizes[band];

        for (; bin < band_end; bin++) {

            for (ch = 1; ch <= s->fbw_channels; ch++) {

                if (s->channel_in_cpl[ch]) {

                    s->fixed_coeffs[ch][bin] = ((int64_t)s->fixed_coeffs[CPL_CH][bin] *

                                                (int64_t)s->cpl_coords[ch][band]) >> 23;

                    if (ch == 2 && s->phase_flags[band])

                        s->fixed_coeffs[ch][bin] = -s->fixed_coeffs[ch][bin];

                }

            }

        }

    }

}

static void vnc_dpy_copy(DisplayChangeListener *dcl,

                         DisplayState *ds,

                         int src_x, int src_y,

                         int dst_x, int dst_y, int w, int h)

{

    VncDisplay *vd = ds->opaque;

    VncState *vs, *vn;

    uint8_t *src_row;

    uint8_t *dst_row;

    int i, x, y, pitch, inc, w_lim, s;

    int cmp_bytes;



    vnc_refresh_server_surface(vd);

    QTAILQ_FOREACH_SAFE(vs, &vd->clients, next, vn) {

        if (vnc_has_feature(vs, VNC_FEATURE_COPYRECT)) {

            vs->force_update = 1;

            vnc_update_client_sync(vs, 1);

            /* vs might be free()ed here */

        }

    }



    /* do bitblit op on the local surface too */

    pitch = vnc_server_fb_stride(vd);

    src_row = vnc_server_fb_ptr(vd, src_x, src_y);

    dst_row = vnc_server_fb_ptr(vd, dst_x, dst_y);

    y = dst_y;

    inc = 1;

    if (dst_y > src_y) {

        /* copy backwards */

        src_row += pitch * (h-1);

        dst_row += pitch * (h-1);

        pitch = -pitch;

        y = dst_y + h - 1;

        inc = -1;

    }

    w_lim = w - (16 - (dst_x % 16));

    if (w_lim < 0)

        w_lim = w;

    else

        w_lim = w - (w_lim % 16);

    for (i = 0; i < h; i++) {

        for (x = 0; x <= w_lim;

                x += s, src_row += cmp_bytes, dst_row += cmp_bytes) {

            if (x == w_lim) {

                if ((s = w - w_lim) == 0)

                    break;

            } else if (!x) {

                s = (16 - (dst_x % 16));

                s = MIN(s, w_lim);

            } else {

                s = 16;

            }

            cmp_bytes = s * VNC_SERVER_FB_BYTES;

            if (memcmp(src_row, dst_row, cmp_bytes) == 0)

                continue;

            memmove(dst_row, src_row, cmp_bytes);

            QTAILQ_FOREACH(vs, &vd->clients, next) {

                if (!vnc_has_feature(vs, VNC_FEATURE_COPYRECT)) {

                    set_bit(((x + dst_x) / 16), vs->dirty[y]);

                }

            }

        }

        src_row += pitch - w * VNC_SERVER_FB_BYTES;

        dst_row += pitch - w * VNC_SERVER_FB_BYTES;

        y += inc;

    }



    QTAILQ_FOREACH(vs, &vd->clients, next) {

        if (vnc_has_feature(vs, VNC_FEATURE_COPYRECT)) {

            vnc_copy(vs, src_x, src_y, dst_x, dst_y, w, h);

        }

    }

}

