int ff_ps_read_data(AVCodecContext *avctx, GetBitContext *gb_host, PSContext *ps, int bits_left)

{

    int e;

    int bit_count_start = get_bits_count(gb_host);

    int header;

    int bits_consumed;

    GetBitContext gbc = *gb_host, *gb = &gbc;



    header = get_bits1(gb);

    if (header) {     //enable_ps_header

        ps->enable_iid = get_bits1(gb);

        if (ps->enable_iid) {

            int iid_mode = get_bits(gb, 3);

            if (iid_mode > 5) {

                av_log(avctx, AV_LOG_ERROR, "iid_mode %d is reserved.\n",

                       iid_mode);

                goto err;

            }

            ps->nr_iid_par    = nr_iidicc_par_tab[iid_mode];

            ps->iid_quant     = iid_mode > 2;

            ps->nr_ipdopd_par = nr_iidopd_par_tab[iid_mode];

        }

        ps->enable_icc = get_bits1(gb);

        if (ps->enable_icc) {

            ps->icc_mode = get_bits(gb, 3);

            if (ps->icc_mode > 5) {

                av_log(avctx, AV_LOG_ERROR, "icc_mode %d is reserved.\n",

                       ps->icc_mode);

                goto err;

            }

            ps->nr_icc_par = nr_iidicc_par_tab[ps->icc_mode];

        }

        ps->enable_ext = get_bits1(gb);

    }



    ps->frame_class = get_bits1(gb);

    ps->num_env_old = ps->num_env;

    ps->num_env     = num_env_tab[ps->frame_class][get_bits(gb, 2)];



    ps->border_position[0] = -1;

    if (ps->frame_class) {

        for (e = 1; e <= ps->num_env; e++)

            ps->border_position[e] = get_bits(gb, 5);

    } else

        for (e = 1; e <= ps->num_env; e++)

            ps->border_position[e] = (e * numQMFSlots >> ff_log2_tab[ps->num_env]) - 1;



    if (ps->enable_iid) {

        for (e = 0; e < ps->num_env; e++) {

            int dt = get_bits1(gb);

            if (read_iid_data(avctx, gb, ps, ps->iid_par, huff_iid[2*dt+ps->iid_quant], e, dt))

                goto err;

        }

    } else




    if (ps->enable_icc)

        for (e = 0; e < ps->num_env; e++) {

            int dt = get_bits1(gb);

            if (read_icc_data(avctx, gb, ps, ps->icc_par, dt ? huff_icc_dt : huff_icc_df, e, dt))

                goto err;

        }

    else




    if (ps->enable_ext) {

        int cnt = get_bits(gb, 4);

        if (cnt == 15) {

            cnt += get_bits(gb, 8);

        }

        cnt *= 8;

        while (cnt > 7) {

            int ps_extension_id = get_bits(gb, 2);

            cnt -= 2 + ps_read_extension_data(gb, ps, ps_extension_id);

        }

        if (cnt < 0) {

            av_log(avctx, AV_LOG_ERROR, "ps extension overflow %d\n", cnt);

            goto err;

        }

        skip_bits(gb, cnt);

    }



    ps->enable_ipdopd &= !PS_BASELINE;



    //Fix up envelopes

    if (!ps->num_env || ps->border_position[ps->num_env] < numQMFSlots - 1) {

        //Create a fake envelope

        int source = ps->num_env ? ps->num_env - 1 : ps->num_env_old - 1;

        if (source >= 0 && source != ps->num_env) {

            if (ps->enable_iid) {

                memcpy(ps->iid_par+ps->num_env, ps->iid_par+source, sizeof(ps->iid_par[0]));

            }

            if (ps->enable_icc) {

                memcpy(ps->icc_par+ps->num_env, ps->icc_par+source, sizeof(ps->icc_par[0]));

            }

            if (ps->enable_ipdopd) {

                memcpy(ps->ipd_par+ps->num_env, ps->ipd_par+source, sizeof(ps->ipd_par[0]));

                memcpy(ps->opd_par+ps->num_env, ps->opd_par+source, sizeof(ps->opd_par[0]));

            }

        }

        ps->num_env++;

        ps->border_position[ps->num_env] = numQMFSlots - 1;

    }





    ps->is34bands_old = ps->is34bands;

    if (!PS_BASELINE && (ps->enable_iid || ps->enable_icc))

        ps->is34bands = (ps->enable_iid && ps->nr_iid_par == 34) ||

                        (ps->enable_icc && ps->nr_icc_par == 34);



    //Baseline

    if (!ps->enable_ipdopd) {



    }



    if (header)

        ps->start = 1;



    bits_consumed = get_bits_count(gb) - bit_count_start;

    if (bits_consumed <= bits_left) {

        skip_bits_long(gb_host, bits_consumed);

        return bits_consumed;

    }

    av_log(avctx, AV_LOG_ERROR, "Expected to read %d PS bits actually read %d.\n", bits_left, bits_consumed);

err:

    ps->start = 0;

    skip_bits_long(gb_host, bits_left);





    return bits_left;

}

static unsigned int read_sbr_data(AACContext *ac, SpectralBandReplication *sbr,

                                  GetBitContext *gb, int id_aac)

{

    unsigned int cnt = get_bits_count(gb);



    if (id_aac == TYPE_SCE || id_aac == TYPE_CCE) {

        read_sbr_single_channel_element(ac, sbr, gb);

    } else if (id_aac == TYPE_CPE) {

        read_sbr_channel_pair_element(ac, sbr, gb);

    } else {

        av_log(ac->avccontext, AV_LOG_ERROR,

            "Invalid bitstream - cannot apply SBR to element type %d\n", id_aac);

        sbr->start = 0;

        return get_bits_count(gb) - cnt;

    }

    if (get_bits1(gb)) { // bs_extended_data

        int num_bits_left = get_bits(gb, 4); // bs_extension_size

        if (num_bits_left == 15)

            num_bits_left += get_bits(gb, 8); // bs_esc_count



        num_bits_left <<= 3;

        while (num_bits_left > 7) {

            num_bits_left -= 2;

            read_sbr_extension(ac, sbr, gb, get_bits(gb, 2), &num_bits_left); // bs_extension_id

        }

    }



    return get_bits_count(gb) - cnt;

}

static int dvbsub_read_2bit_string(uint8_t *destbuf, int dbuf_len,

                                   const uint8_t **srcbuf, int buf_size,

                                   int non_mod, uint8_t *map_table)

{

    GetBitContext gb;



    int bits;

    int run_length;

    int pixels_read = 0;



    init_get_bits(&gb, *srcbuf, buf_size << 3);



    while (get_bits_count(&gb) < buf_size << 3 && pixels_read < dbuf_len) {

        bits = get_bits(&gb, 2);



        if (bits) {

            if (non_mod != 1 || bits != 1) {

                if (map_table)

                    *destbuf++ = map_table[bits];

                else

                    *destbuf++ = bits;

            }

            pixels_read++;

        } else {

            bits = get_bits1(&gb);

            if (bits == 1) {

                run_length = get_bits(&gb, 3) + 3;

                bits = get_bits(&gb, 2);



                if (non_mod == 1 && bits == 1)

                    pixels_read += run_length;

                else {

                    if (map_table)

                        bits = map_table[bits];

                    while (run_length-- > 0 && pixels_read < dbuf_len) {

                        *destbuf++ = bits;

                        pixels_read++;

                    }

                }

            } else {

                bits = get_bits1(&gb);

                if (bits == 0) {

                    bits = get_bits(&gb, 2);

                    if (bits == 2) {

                        run_length = get_bits(&gb, 4) + 12;

                        bits = get_bits(&gb, 2);



                        if (non_mod == 1 && bits == 1)

                            pixels_read += run_length;

                        else {

                            if (map_table)

                                bits = map_table[bits];

                            while (run_length-- > 0 && pixels_read < dbuf_len) {

                                *destbuf++ = bits;

                                pixels_read++;

                            }

                        }

                    } else if (bits == 3) {

                        run_length = get_bits(&gb, 8) + 29;

                        bits = get_bits(&gb, 2);



                        if (non_mod == 1 && bits == 1)

                            pixels_read += run_length;

                        else {

                            if (map_table)

                                bits = map_table[bits];

                            while (run_length-- > 0 && pixels_read < dbuf_len) {

                                *destbuf++ = bits;

                                pixels_read++;

                            }

                        }

                    } else if (bits == 1) {

                        pixels_read += 2;

                        if (map_table)

                            bits = map_table[0];

                        else

                            bits = 0;

                        if (pixels_read <= dbuf_len) {

                            *destbuf++ = bits;

                            *destbuf++ = bits;

                        }

                    } else {

                        (*srcbuf) += (get_bits_count(&gb) + 7) >> 3;

                        return pixels_read;

                    }

                } else {

                    if (map_table)

                        bits = map_table[0];

                    else

                        bits = 0;

                    *destbuf++ = bits;

                    pixels_read++;

                }

            }

        }

    }



    if (get_bits(&gb, 6))

        av_log(0, AV_LOG_ERROR, "DVBSub error: line overflow\n");



    (*srcbuf) += (get_bits_count(&gb) + 7) >> 3;



    return pixels_read;

}

static av_cold int sonic_decode_init(AVCodecContext *avctx)

{

    SonicContext *s = avctx->priv_data;

    GetBitContext gb;

    int i;



    s->channels = avctx->channels;

    s->samplerate = avctx->sample_rate;



    if (!avctx->extradata)

    {

        av_log(avctx, AV_LOG_ERROR, "No mandatory headers present\n");

        return AVERROR_INVALIDDATA;

    }



    init_get_bits8(&gb, avctx->extradata, avctx->extradata_size);



    s->version = get_bits(&gb, 2);

    if (s->version >= 2) {

        s->version       = get_bits(&gb, 8);

        s->minor_version = get_bits(&gb, 8);

    }

    if (s->version != 2)

    {

        av_log(avctx, AV_LOG_ERROR, "Unsupported Sonic version, please report\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->version >= 1)

    {

        s->channels = get_bits(&gb, 2);

        s->samplerate = samplerate_table[get_bits(&gb, 4)];

        av_log(avctx, AV_LOG_INFO, "Sonicv2 chans: %d samprate: %d\n",

            s->channels, s->samplerate);

    }



    if (s->channels > MAX_CHANNELS)

    {

        av_log(avctx, AV_LOG_ERROR, "Only mono and stereo streams are supported by now\n");

        return AVERROR_INVALIDDATA;

    }



    s->lossless = get_bits1(&gb);

    if (!s->lossless)

        skip_bits(&gb, 3); // XXX FIXME

    s->decorrelation = get_bits(&gb, 2);

    if (s->decorrelation != 3 && s->channels != 2) {

        av_log(avctx, AV_LOG_ERROR, "invalid decorrelation %d\n", s->decorrelation);

        return AVERROR_INVALIDDATA;

    }



    s->downsampling = get_bits(&gb, 2);

    if (!s->downsampling) {

        av_log(avctx, AV_LOG_ERROR, "invalid downsampling value\n");

        return AVERROR_INVALIDDATA;

    }



    s->num_taps = (get_bits(&gb, 5)+1)<<5;

    if (get_bits1(&gb)) // XXX FIXME

        av_log(avctx, AV_LOG_INFO, "Custom quant table\n");



    s->block_align = 2048LL*s->samplerate/(44100*s->downsampling);

    s->frame_size = s->channels*s->block_align*s->downsampling;

//    avctx->frame_size = s->block_align;



    av_log(avctx, AV_LOG_INFO, "Sonic: ver: %d.%d ls: %d dr: %d taps: %d block: %d frame: %d downsamp: %d\n",

        s->version, s->minor_version, s->lossless, s->decorrelation, s->num_taps, s->block_align, s->frame_size, s->downsampling);



    // generate taps

    s->tap_quant = av_calloc(s->num_taps, sizeof(*s->tap_quant));

    if (!s->tap_quant)

        return AVERROR(ENOMEM);



    for (i = 0; i < s->num_taps; i++)

        s->tap_quant[i] = ff_sqrt(i+1);



    s->predictor_k = av_calloc(s->num_taps, sizeof(*s->predictor_k));



    for (i = 0; i < s->channels; i++)

    {

        s->predictor_state[i] = av_calloc(s->num_taps, sizeof(**s->predictor_state));

        if (!s->predictor_state[i])

            return AVERROR(ENOMEM);

    }



    for (i = 0; i < s->channels; i++)

    {

        s->coded_samples[i] = av_calloc(s->block_align, sizeof(**s->coded_samples));

        if (!s->coded_samples[i])

            return AVERROR(ENOMEM);

    }

    s->int_samples = av_calloc(s->frame_size, sizeof(*s->int_samples));

    if (!s->int_samples)

        return AVERROR(ENOMEM);



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    return 0;

}

static int ape_tag_read_field(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    uint8_t key[1024], *value;

    uint32_t size, flags;

    int i, c;



    size = avio_rl32(pb);  /* field size */

    flags = avio_rl32(pb); /* field flags */

    for (i = 0; i < sizeof(key) - 1; i++) {

        c = avio_r8(pb);

        if (c < 0x20 || c > 0x7E)

            break;

        else

            key[i] = c;

    }

    key[i] = 0;

    if (c != 0) {

        av_log(s, AV_LOG_WARNING, "Invalid APE tag key '%s'.\n", key);

        return -1;

    }

    if (size >= UINT_MAX)

        return -1;

    if (flags & APE_TAG_FLAG_IS_BINARY) {

        uint8_t filename[1024];

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        avio_get_str(pb, INT_MAX, filename, sizeof(filename));

        st->codec->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!st->codec->extradata)

            return AVERROR(ENOMEM);

        if (avio_read(pb, st->codec->extradata, size) != size) {

            av_freep(&st->codec->extradata);

            return AVERROR(EIO);

        }

        st->codec->extradata_size = size;

        av_dict_set(&st->metadata, key, filename, 0);

        st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

    } else {

        value = av_malloc(size+1);

        if (!value)

            return AVERROR(ENOMEM);

        c = avio_read(pb, value, size);

        if (c < 0)

            return c;

        value[c] = 0;

        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }

    return 0;

}

static int opus_header(AVFormatContext *avf, int idx)

{

    struct ogg *ogg              = avf->priv_data;

    struct ogg_stream *os        = &ogg->streams[idx];

    AVStream *st                 = avf->streams[idx];

    struct oggopus_private *priv = os->private;

    uint8_t *packet              = os->buf + os->pstart;



    if (!priv) {

        priv = os->private = av_mallocz(sizeof(*priv));

        if (!priv)

            return AVERROR(ENOMEM);

    }



    if (os->flags & OGG_FLAG_BOS) {

        if (os->psize < OPUS_HEAD_SIZE || (AV_RL8(packet + 8) & 0xF0) != 0)

            return AVERROR_INVALIDDATA;

        st->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codecpar->codec_id   = AV_CODEC_ID_OPUS;

        st->codecpar->channels   = AV_RL8(packet + 9);



        priv->pre_skip        = AV_RL16(packet + 10);

        st->codecpar->initial_padding = priv->pre_skip;

        /*orig_sample_rate    = AV_RL32(packet + 12);*/

        /*gain                = AV_RL16(packet + 16);*/

        /*channel_map         = AV_RL8 (packet + 18);*/




        if (ff_alloc_extradata(st->codecpar, os->psize))

            return AVERROR(ENOMEM);



        memcpy(st->codecpar->extradata, packet, os->psize);



        st->codecpar->sample_rate = 48000;

        st->codecpar->seek_preroll = av_rescale(OPUS_SEEK_PREROLL_MS,

                                                st->codecpar->sample_rate, 1000);

        avpriv_set_pts_info(st, 64, 1, 48000);

        priv->need_comments = 1;

        return 1;

    }



    if (priv->need_comments) {

        if (os->psize < 8 || memcmp(packet, "OpusTags", 8))

            return AVERROR_INVALIDDATA;

        ff_vorbis_stream_comment(avf, st, packet + 8, os->psize - 8);

        priv->need_comments--;

        return 1;

    }



    return 0;

}

static int put_flac_codecpriv(AVFormatContext *s,

                              AVIOContext *pb, AVCodecContext *codec)

{

    int write_comment = (codec->channel_layout &&

                         !(codec->channel_layout & ~0x3ffffULL) &&

                         !ff_flac_is_native_layout(codec->channel_layout));

    int ret = ff_flac_write_header(pb, codec->extradata, codec->extradata_size,

                                   !write_comment);



    if (ret < 0)

        return ret;



    if (write_comment) {

        const char *vendor = (s->flags & AVFMT_FLAG_BITEXACT) ?

                             "Lavf" : LIBAVFORMAT_IDENT;

        AVDictionary *dict = NULL;

        uint8_t buf[32], *data, *p;

        int len;



        snprintf(buf, sizeof(buf), "0x%"PRIx64, codec->channel_layout);

        av_dict_set(&dict, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK", buf, 0);



        len = ff_vorbiscomment_length(dict, vendor);

        data = av_malloc(len + 4);

        if (!data) {

            av_dict_free(&dict);

            return AVERROR(ENOMEM);

        }



        data[0] = 0x84;

        AV_WB24(data + 1, len);



        p = data + 4;

        ff_vorbiscomment_write(&p, &dict, vendor);



        avio_write(pb, data, len + 4);



        av_freep(&data);

        av_dict_free(&dict);

    }



    return 0;

}

static void avi_read_nikon(AVFormatContext *s, uint64_t end)

{

    while (avio_tell(s->pb) < end) {

        uint32_t tag  = avio_rl32(s->pb);

        uint32_t size = avio_rl32(s->pb);

        switch (tag) {

        case MKTAG('n', 'c', 't', 'g'):  /* Nikon Tags */

        {

            uint64_t tag_end = avio_tell(s->pb) + size;

            while (avio_tell(s->pb) < tag_end) {

                uint16_t tag     = avio_rl16(s->pb);

                uint16_t size    = avio_rl16(s->pb);

                const char *name = NULL;

                char buffer[64]  = { 0 };

                if (avio_tell(s->pb) + size > tag_end)

                    size = tag_end - avio_tell(s->pb);

                size -= avio_read(s->pb, buffer,

                                  FFMIN(size, sizeof(buffer) - 1));

                switch (tag) {

                case 0x03:

                    name = "maker";

                    break;

                case 0x04:

                    name = "model";

                    break;

                case 0x13:

                    name = "creation_time";

                    if (buffer[4] == ':' && buffer[7] == ':')

                        buffer[4] = buffer[7] = '-';

                    break;

                }

                if (name)

                    av_dict_set(&s->metadata, name, buffer, 0);

                avio_skip(s->pb, size);

            }

            break;

        }

        default:

            avio_skip(s->pb, size);

            break;

        }

    }

}

