static void put_pixels_clamped_c(const int16_t *block, uint8_t *av_restrict pixels,

                                 ptrdiff_t line_size)

{

    int i;



    /* read the pixels */

    for (i = 0; i < 8; i++) {

        pixels[0] = av_clip_uint8(block[0]);

        pixels[1] = av_clip_uint8(block[1]);

        pixels[2] = av_clip_uint8(block[2]);

        pixels[3] = av_clip_uint8(block[3]);

        pixels[4] = av_clip_uint8(block[4]);

        pixels[5] = av_clip_uint8(block[5]);

        pixels[6] = av_clip_uint8(block[6]);

        pixels[7] = av_clip_uint8(block[7]);



        pixels += line_size;

        block  += 8;

    }

}

static void FUNCC(pred4x4_vertical_add)(uint8_t *_pix, const int16_t *_block,

                                        ptrdiff_t stride)

{

    int i;

    pixel *pix = (pixel*)_pix;

    const dctcoef *block = (const dctcoef*)_block;

    stride >>= sizeof(pixel)-1;

    pix -= stride;

    for(i=0; i<4; i++){

        pixel v = pix[0];

        pix[1*stride]= v += block[0];

        pix[2*stride]= v += block[4];

        pix[3*stride]= v += block[8];

        pix[4*stride]= v +  block[12];

        pix++;

        block++;

    }

}

static void FUNCC(pred8x8l_horizontal_add)(uint8_t *_pix, const int16_t *_block,

                                           ptrdiff_t stride)

{

    int i;

    pixel *pix = (pixel*)_pix;

    const dctcoef *block = (const dctcoef*)_block;

    stride >>= sizeof(pixel)-1;

    for(i=0; i<8; i++){

        pixel v = pix[-1];

        pix[0]= v += block[0];

        pix[1]= v += block[1];

        pix[2]= v += block[2];

        pix[3]= v += block[3];

        pix[4]= v += block[4];

        pix[5]= v += block[5];

        pix[6]= v += block[6];

        pix[7]= v +  block[7];

        pix+= stride;

        block+= 8;

    }

}

static void FUNC(transquant_bypass16x16)(uint8_t *_dst, int16_t *coeffs,

                                         ptrdiff_t stride)

{

    int x, y;

    pixel *dst = (pixel *)_dst;



    stride /= sizeof(pixel);



    for (y = 0; y < 16; y++) {

        for (x = 0; x < 16; x++) {

            dst[x] += *coeffs;

            coeffs++;

        }

        dst += stride;

    }

}

void os_set_proc_name(const char *s)

{

#if defined(PR_SET_NAME)

    char name[16];

    if (!s)

        return;

    name[sizeof(name) - 1] = 0;

    strncpy(name, s, sizeof(name));

    /* Could rewrite argv[0] too, but that's a bit more complicated.

       This simple way is enough for `top'. */

    if (prctl(PR_SET_NAME, name)) {

        perror("unable to change process name");

        exit(1);

    }

#else

    fprintf(stderr, "Change of process name not supported by your OS\n");

    exit(1);

#endif

}

