int av_opencl_buffer_write(cl_mem dst_cl_buf, uint8_t *src_buf, size_t buf_size)

{

    cl_int status;

    void *mapped = clEnqueueMapBuffer(gpu_env.command_queue, dst_cl_buf,

                                      CL_TRUE,CL_MAP_WRITE, 0, sizeof(uint8_t) * buf_size,

                                      0, NULL, NULL, &status);



    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not map OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    memcpy(mapped, src_buf, buf_size);



    status = clEnqueueUnmapMemObject(gpu_env.command_queue, dst_cl_buf, mapped, 0, NULL, NULL);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not unmap OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    return 0;

}

int av_opencl_buffer_read_image(uint8_t **dst_data, int *plane_size, int plane_num,

                                       cl_mem src_cl_buf, size_t cl_buffer_size)

{

    int i,buffer_size = 0,ret = 0;

    uint8_t *temp;

    void *mapped;

    cl_int status;

    if ((unsigned int)plane_num > 8) {

        return AVERROR(EINVAL);

    }

    for (i = 0;i < plane_num;i++) {

        buffer_size += plane_size[i];

    }

    if (buffer_size > cl_buffer_size) {

        av_log(&openclutils, AV_LOG_ERROR, "Cannot write image to CPU buffer: OpenCL buffer too small\n");

        return AVERROR(EINVAL);

    }

    mapped = clEnqueueMapBuffer(gpu_env.command_queue, src_cl_buf,

                                      CL_TRUE,CL_MAP_READ, 0, buffer_size,

                                      0, NULL, NULL, &status);



    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not map OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    temp = mapped;

    if (ret >= 0) {

        for (i = 0;i < plane_num;i++) {

            memcpy(dst_data[i], temp, plane_size[i]);

            temp += plane_size[i];

        }

    }

    status = clEnqueueUnmapMemObject(gpu_env.command_queue, src_cl_buf, mapped, 0, NULL, NULL);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not unmap OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    return 0;

}

static int compile_kernel_file(GPUEnv *gpu_env, const char *build_options)

{

    cl_int status;

    char *temp, *source_str = NULL;

    size_t source_str_len = 0;

    int i, ret = 0;



    for (i = 0; i < gpu_env->kernel_code_count; i++) {

        if (!gpu_env->kernel_code[i].is_compiled)

            source_str_len += strlen(gpu_env->kernel_code[i].kernel_string);

    }

    if (!source_str_len) {

        return 0;

    }

    source_str = av_mallocz(source_str_len + 1);

    if (!source_str) {

        return AVERROR(ENOMEM);

    }

    temp = source_str;

    for (i = 0; i < gpu_env->kernel_code_count; i++) {

        if (!gpu_env->kernel_code[i].is_compiled) {

            memcpy(temp, gpu_env->kernel_code[i].kernel_string,

                        strlen(gpu_env->kernel_code[i].kernel_string));

            gpu_env->kernel_code[i].is_compiled = 1;

            temp += strlen(gpu_env->kernel_code[i].kernel_string);

        }

    }

    /* create a CL program using the kernel source */

    gpu_env->programs[gpu_env->program_count] = clCreateProgramWithSource(gpu_env->context,

                                                           1, (const char **)(&source_str),

                                                                   &source_str_len, &status);

    if(status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not create OpenCL program with source code: %s\n",

               opencl_errstr(status));

        ret = AVERROR_EXTERNAL;

        goto end;

    }

    if (!gpu_env->programs[gpu_env->program_count]) {

        av_log(&openclutils, AV_LOG_ERROR, "Created program is NULL\n");

        ret = AVERROR_EXTERNAL;

        goto end;

    }

    i = 0;

    if (gpu_env->usr_spec_dev_info.dev_idx >= 0)

        i = gpu_env->usr_spec_dev_info.dev_idx;

    /* create a cl program executable for all the devices specified */

    if (!gpu_env->is_user_created)

        status = clBuildProgram(gpu_env->programs[gpu_env->program_count], 1, &gpu_env->device_ids[i],

                                build_options, NULL, NULL);

    else

        status = clBuildProgram(gpu_env->programs[gpu_env->program_count], 1, &(gpu_env->device_id),

                                 build_options, NULL, NULL);



    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not compile OpenCL kernel: %s\n", opencl_errstr(status));

        ret = AVERROR_EXTERNAL;

        goto end;

    }

    gpu_env->program_count++;

end:

    av_free(source_str);

    return ret;

}

void av_opencl_uninit(void)

{

    cl_int status;

    int i;

    LOCK_OPENCL

    gpu_env.init_count--;

    if (gpu_env.is_user_created)

        goto end;

    if ((gpu_env.init_count > 0) || (gpu_env.kernel_count > 0))

        goto end;

    for (i = 0; i < gpu_env.program_count; i++) {

        if (gpu_env.programs[i]) {

            status = clReleaseProgram(gpu_env.programs[i]);

            if (status != CL_SUCCESS) {

                av_log(&openclutils, AV_LOG_ERROR, "Could not release OpenCL program: %s\n", opencl_errstr(status));

            }

            gpu_env.programs[i] = NULL;

        }

    }

    if (gpu_env.command_queue) {

        status = clReleaseCommandQueue(gpu_env.command_queue);

        if (status != CL_SUCCESS) {

            av_log(&openclutils, AV_LOG_ERROR, "Could not release OpenCL command queue: %s\n", opencl_errstr(status));

        }

        gpu_env.command_queue = NULL;

    }

    if (gpu_env.context) {

        status = clReleaseContext(gpu_env.context);

        if (status != CL_SUCCESS) {

            av_log(&openclutils, AV_LOG_ERROR, "Could not release OpenCL context: %s\n", opencl_errstr(status));

        }

        gpu_env.context = NULL;

    }

    av_freep(&(gpu_env.device_ids));

end:

    UNLOCK_OPENCL

}

static int mov_read_ctts(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */

    entries = avio_rb32(pb);



    av_log(c->fc, AV_LOG_TRACE, "track[%i].ctts.entries = %i\n", c->fc->nb_streams-1, entries);



    if (!entries)

        return 0;

    if (entries >= UINT_MAX / sizeof(*sc->ctts_data))

        return AVERROR_INVALIDDATA;

    av_freep(&sc->ctts_data);

    sc->ctts_data = av_realloc(NULL, entries * sizeof(*sc->ctts_data));

    if (!sc->ctts_data)

        return AVERROR(ENOMEM);



    for (i = 0; i < entries && !pb->eof_reached; i++) {

        int count    =avio_rb32(pb);

        int duration =avio_rb32(pb);



        sc->ctts_data[i].count   = count;

        sc->ctts_data[i].duration= duration;



        av_log(c->fc, AV_LOG_TRACE, "count=%d, duration=%d\n",

                count, duration);



        if (FFABS(duration) > (1<<28) && i+2<entries) {

            av_log(c->fc, AV_LOG_WARNING, "CTTS invalid\n");

            av_freep(&sc->ctts_data);

            sc->ctts_count = 0;

            return 0;

        }



        if (i+2<entries)

            mov_update_dts_shift(sc, duration);

    }



    sc->ctts_count = i;



    if (pb->eof_reached)

        return AVERROR_EOF;



    av_log(c->fc, AV_LOG_TRACE, "dts shift %d\n", sc->dts_shift);



    return 0;

}

static int mov_read_stts(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries;

    int64_t duration=0;

    int64_t total_sample_count=0;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */

    entries = avio_rb32(pb);



    av_dlog(c->fc, "track[%i].stts.entries = %i\n",

            c->fc->nb_streams-1, entries);



    if (entries >= UINT_MAX / sizeof(*sc->stts_data))

        return -1;



    sc->stts_data = av_malloc(entries * sizeof(*sc->stts_data));

    if (!sc->stts_data)

        return AVERROR(ENOMEM);



    sc->stts_count = entries;



    for (i=0; i<entries; i++) {

        int sample_duration;

        int sample_count;



        sample_count=avio_rb32(pb);

        sample_duration = avio_rb32(pb);

        sc->stts_data[i].count= sample_count;

        sc->stts_data[i].duration= sample_duration;



        av_dlog(c->fc, "sample_count=%d, sample_duration=%d\n",

                sample_count, sample_duration);



        duration+=(int64_t)sample_duration*sample_count;

        total_sample_count+=sample_count;

    }



    st->nb_frames= total_sample_count;

    if (duration)

        st->duration= duration;

    return 0;

}

static int mov_read_stss(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */



    entries = avio_rb32(pb);



    av_dlog(c->fc, "keyframe_count = %d\n", entries);



    if (!entries)

    {

        sc->keyframe_absent = 1;

        if (!st->need_parsing)

            st->need_parsing = AVSTREAM_PARSE_HEADERS;

        return 0;

    }

    if (entries >= UINT_MAX / sizeof(int))

        return AVERROR_INVALIDDATA;

    sc->keyframes = av_malloc(entries * sizeof(int));

    if (!sc->keyframes)

        return AVERROR(ENOMEM);



    for (i = 0; i < entries && !pb->eof_reached; i++) {

        sc->keyframes[i] = avio_rb32(pb);

        //av_dlog(c->fc, "keyframes[]=%d\n", sc->keyframes[i]);

    }



    sc->keyframe_count = i;



    if (pb->eof_reached)

        return AVERROR_EOF;



    return 0;

}

static int mov_read_stsc(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    MOVStreamContext *sc = st->priv_data;

    unsigned int i, entries;



    get_byte(pb); /* version */

    get_be24(pb); /* flags */



    entries = get_be32(pb);



    dprintf(c->fc, "track[%i].stsc.entries = %i\n", c->fc->nb_streams-1, entries);



    if(entries >= UINT_MAX / sizeof(*sc->stsc_data))

        return -1;

    sc->stsc_data = av_malloc(entries * sizeof(*sc->stsc_data));

    if (!sc->stsc_data)

        return AVERROR(ENOMEM);

    sc->stsc_count = entries;



    for(i=0; i<entries; i++) {

        sc->stsc_data[i].first = get_be32(pb);

        sc->stsc_data[i].count = get_be32(pb);

        sc->stsc_data[i].id = get_be32(pb);

    }

    return 0;

}

static int get_metadata(AVFormatContext *s,

                        const char *const tag,

                        const unsigned data_size)

{

    uint8_t *buf = ((data_size + 1) == 0) ? NULL : av_malloc(data_size + 1);



    if (!buf)

        return AVERROR(ENOMEM);



    if (avio_read(s->pb, buf, data_size) < 0) {

        av_free(buf);

        return AVERROR(EIO);

    }

    buf[data_size] = 0;

    av_dict_set(&s->metadata, tag, buf, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

static int ape_tag_read_field(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    uint8_t key[1024], *value;

    uint32_t size, flags;

    int i, c;



    size = avio_rl32(pb);  /* field size */

    flags = avio_rl32(pb); /* field flags */

    for (i = 0; i < sizeof(key) - 1; i++) {

        c = avio_r8(pb);

        if (c < 0x20 || c > 0x7E)

            break;

        else

            key[i] = c;

    }

    key[i] = 0;

    if (c != 0) {

        av_log(s, AV_LOG_WARNING, "Invalid APE tag key '%s'.\n", key);

        return -1;

    }

    if (size >= UINT_MAX)

        return -1;

    if (flags & APE_TAG_FLAG_IS_BINARY) {

        uint8_t filename[1024];

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        avio_get_str(pb, INT_MAX, filename, sizeof(filename));

        st->codec->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!st->codec->extradata)

            return AVERROR(ENOMEM);

        if (avio_read(pb, st->codec->extradata, size) != size) {

            av_freep(&st->codec->extradata);

            return AVERROR(EIO);

        }

        st->codec->extradata_size = size;

        av_dict_set(&st->metadata, key, filename, 0);

        st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

    } else {

        value = av_malloc(size+1);

        if (!value)

            return AVERROR(ENOMEM);

        c = avio_read(pb, value, size);

        if (c < 0)

            return c;

        value[c] = 0;

        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }

    return 0;

}

static int avi_read_tag(AVFormatContext *s, AVStream *st, uint32_t tag, uint32_t size)

{

    AVIOContext *pb = s->pb;

    char key[5] = {0}, *value;



    size += (size & 1);



    if (size == UINT_MAX)

        return -1;

    value = av_malloc(size+1);

    if (!value)

        return -1;

    avio_read(pb, value, size);

    value[size]=0;



    AV_WL32(key, tag);



    return av_dict_set(st ? &st->metadata : &s->metadata, key, value,

                            AV_DICT_DONT_STRDUP_VAL);

}

static int add_string_metadata(int count, const char *name,

                               TiffContext *s)

{

    char *value;



    if (bytestream2_get_bytes_left(&s->gb) < count)

        return AVERROR_INVALIDDATA;



    value = av_malloc(count + 1);

    if (!value)

        return AVERROR(ENOMEM);



    bytestream2_get_bufferu(&s->gb, value, count);

    value[count] = 0;



    av_dict_set(&s->picture.metadata, name, value, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

static void hybrid6_cx(float (*in)[2], float (*out)[32][2], const float (*filter)[7][2], int len)

{

    int i, j, ssb;

    int N = 8;

    float temp[8][2];



    for (i = 0; i < len; i++, in++) {

        for (ssb = 0; ssb < N; ssb++) {

            float sum_re = filter[ssb][6][0] * in[6][0], sum_im = filter[ssb][6][0] * in[6][1];

            for (j = 0; j < 6; j++) {

                float in0_re = in[j][0];

                float in0_im = in[j][1];

                float in1_re = in[12-j][0];

                float in1_im = in[12-j][1];

                sum_re += filter[ssb][j][0] * (in0_re + in1_re) - filter[ssb][j][1] * (in0_im - in1_im);

                sum_im += filter[ssb][j][0] * (in0_im + in1_im) + filter[ssb][j][1] * (in0_re - in1_re);

            }

            temp[ssb][0] = sum_re;

            temp[ssb][1] = sum_im;

        }

        out[0][i][0] = temp[6][0];

        out[0][i][1] = temp[6][1];

        out[1][i][0] = temp[7][0];

        out[1][i][1] = temp[7][1];

        out[2][i][0] = temp[0][0];

        out[2][i][1] = temp[0][1];

        out[3][i][0] = temp[1][0];

        out[3][i][1] = temp[1][1];

        out[4][i][0] = temp[2][0] + temp[5][0];

        out[4][i][1] = temp[2][1] + temp[5][1];

        out[5][i][0] = temp[3][0] + temp[4][0];

        out[5][i][1] = temp[3][1] + temp[4][1];

    }

}

static void sbr_hf_assemble(float Y[2][38][64][2], const float X_high[64][40][2],

                            SpectralBandReplication *sbr, SBRData *ch_data,

                            const int e_a[2])

{

    int e, i, j, m;

    const int h_SL = 4 * !sbr->bs_smoothing_mode;

    const int kx = sbr->kx[1];

    const int m_max = sbr->m[1];

    static const float h_smooth[5] = {

        0.33333333333333,

        0.30150283239582,

        0.21816949906249,

        0.11516383427084,

        0.03183050093751,

    };

    static const int8_t phi[2][4] = {

        {  1,  0, -1,  0}, // real

        {  0,  1,  0, -1}, // imaginary

    };

    float (*g_temp)[48] = ch_data->g_temp, (*q_temp)[48] = ch_data->q_temp;

    int indexnoise = ch_data->f_indexnoise;

    int indexsine  = ch_data->f_indexsine;

    memcpy(Y[0], Y[1], sizeof(Y[0]));



    if (sbr->reset) {

        for (i = 0; i < h_SL; i++) {

            memcpy(g_temp[i + 2*ch_data->t_env[0]], sbr->gain[0], m_max * sizeof(sbr->gain[0][0]));

            memcpy(q_temp[i + 2*ch_data->t_env[0]], sbr->q_m[0],  m_max * sizeof(sbr->q_m[0][0]));

        }

    } else if (h_SL) {

        memcpy(g_temp[2*ch_data->t_env[0]], g_temp[2*ch_data->t_env_num_env_old], 4*sizeof(g_temp[0]));

        memcpy(q_temp[2*ch_data->t_env[0]], q_temp[2*ch_data->t_env_num_env_old], 4*sizeof(q_temp[0]));

    }



    for (e = 0; e < ch_data->bs_num_env; e++) {

        for (i = 2 * ch_data->t_env[e]; i < 2 * ch_data->t_env[e + 1]; i++) {

            memcpy(g_temp[h_SL + i], sbr->gain[e], m_max * sizeof(sbr->gain[0][0]));

            memcpy(q_temp[h_SL + i], sbr->q_m[e],  m_max * sizeof(sbr->q_m[0][0]));

        }

    }



    for (e = 0; e < ch_data->bs_num_env; e++) {

        for (i = 2 * ch_data->t_env[e]; i < 2 * ch_data->t_env[e + 1]; i++) {

            int phi_sign = (1 - 2*(kx & 1));



            if (h_SL && e != e_a[0] && e != e_a[1]) {

                for (m = 0; m < m_max; m++) {

                    const int idx1 = i + h_SL;

                    float g_filt = 0.0f;

                    for (j = 0; j <= h_SL; j++)

                        g_filt += g_temp[idx1 - j][m] * h_smooth[j];

                    Y[1][i][m + kx][0] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][0] * g_filt;

                    Y[1][i][m + kx][1] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][1] * g_filt;

                }

            } else {

                for (m = 0; m < m_max; m++) {

                    const float g_filt = g_temp[i + h_SL][m];

                    Y[1][i][m + kx][0] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][0] * g_filt;

                    Y[1][i][m + kx][1] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][1] * g_filt;

                }

            }



            if (e != e_a[0] && e != e_a[1]) {

                for (m = 0; m < m_max; m++) {

                    indexnoise = (indexnoise + 1) & 0x1ff;

                    if (sbr->s_m[e][m]) {

                        Y[1][i][m + kx][0] +=

                            sbr->s_m[e][m] * phi[0][indexsine];

                        Y[1][i][m + kx][1] +=

                            sbr->s_m[e][m] * (phi[1][indexsine] * phi_sign);

                    } else {

                        float q_filt;

                        if (h_SL) {

                            const int idx1 = i + h_SL;

                            q_filt = 0.0f;

                            for (j = 0; j <= h_SL; j++)

                                q_filt += q_temp[idx1 - j][m] * h_smooth[j];

                        } else {

                            q_filt = q_temp[i][m];

                        }

                        Y[1][i][m + kx][0] +=

                            q_filt * sbr_noise_table[indexnoise][0];

                        Y[1][i][m + kx][1] +=

                            q_filt * sbr_noise_table[indexnoise][1];

                    }

                    phi_sign = -phi_sign;

                }

            } else {

                indexnoise = (indexnoise + m_max) & 0x1ff;

                for (m = 0; m < m_max; m++) {

                    Y[1][i][m + kx][0] +=

                        sbr->s_m[e][m] * phi[0][indexsine];

                    Y[1][i][m + kx][1] +=

                        sbr->s_m[e][m] * (phi[1][indexsine] * phi_sign);

                    phi_sign = -phi_sign;

                }

            }

            indexsine = (indexsine + 1) & 3;

        }

    }

    ch_data->f_indexnoise = indexnoise;

    ch_data->f_indexsine  = indexsine;

}

static void extrapolate_isf(float out[LP_ORDER_16k], float isf[LP_ORDER])

{

    float diff_isf[LP_ORDER - 2], diff_mean;

    float *diff_hi = diff_isf - LP_ORDER + 1; // diff array for extrapolated indexes

    float corr_lag[3];

    float est, scale;

    int i, i_max_corr;



    memcpy(out, isf, (LP_ORDER - 1) * sizeof(float));

    out[LP_ORDER_16k - 1] = isf[LP_ORDER - 1];



    /* Calculate the difference vector */

    for (i = 0; i < LP_ORDER - 2; i++)

        diff_isf[i] = isf[i + 1] - isf[i];



    diff_mean = 0.0;

    for (i = 2; i < LP_ORDER - 2; i++)

        diff_mean += diff_isf[i] * (1.0f / (LP_ORDER - 4));



    /* Find which is the maximum autocorrelation */

    i_max_corr = 0;

    for (i = 0; i < 3; i++) {

        corr_lag[i] = auto_correlation(diff_isf, diff_mean, i + 2);



        if (corr_lag[i] > corr_lag[i_max_corr])

            i_max_corr = i;

    }

    i_max_corr++;



    for (i = LP_ORDER - 1; i < LP_ORDER_16k - 1; i++)

        out[i] = isf[i - 1] + isf[i - 1 - i_max_corr]

                            - isf[i - 2 - i_max_corr];



    /* Calculate an estimate for ISF(18) and scale ISF based on the error */

    est   = 7965 + (out[2] - out[3] - out[4]) / 6.0;

    scale = 0.5 * (FFMIN(est, 7600) - out[LP_ORDER - 2]) /

            (out[LP_ORDER_16k - 2] - out[LP_ORDER - 2]);



    for (i = LP_ORDER - 1; i < LP_ORDER_16k - 1; i++)

        diff_hi[i] = scale * (out[i] - out[i - 1]);



    /* Stability insurance */

    for (i = LP_ORDER; i < LP_ORDER_16k - 1; i++)

        if (diff_hi[i] + diff_hi[i - 1] < 5.0) {

            if (diff_hi[i] > diff_hi[i - 1]) {

                diff_hi[i - 1] = 5.0 - diff_hi[i];

            } else

                diff_hi[i] = 5.0 - diff_hi[i - 1];

        }



    for (i = LP_ORDER - 1; i < LP_ORDER_16k - 1; i++)

        out[i] = out[i - 1] + diff_hi[i] * (1.0f / (1 << 15));



    /* Scale the ISF vector for 16000 Hz */

    for (i = 0; i < LP_ORDER_16k - 1; i++)

        out[i] *= 0.8;

}

