int kvmppc_put_books_sregs(PowerPCCPU *cpu)

{

    CPUPPCState *env = &cpu->env;

    struct kvm_sregs sregs;

    int i;



    sregs.pvr = env->spr[SPR_PVR];



    sregs.u.s.sdr1 = env->spr[SPR_SDR1];



    /* Sync SLB */

#ifdef TARGET_PPC64

    for (i = 0; i < ARRAY_SIZE(env->slb); i++) {

        sregs.u.s.ppc64.slb[i].slbe = env->slb[i].esid;

        if (env->slb[i].esid & SLB_ESID_V) {

            sregs.u.s.ppc64.slb[i].slbe |= i;

        }

        sregs.u.s.ppc64.slb[i].slbv = env->slb[i].vsid;

    }

#endif



    /* Sync SRs */

    for (i = 0; i < 16; i++) {

        sregs.u.s.ppc32.sr[i] = env->sr[i];

    }



    /* Sync BATs */

    for (i = 0; i < 8; i++) {

        /* Beware. We have to swap upper and lower bits here */

        sregs.u.s.ppc32.dbat[i] = ((uint64_t)env->DBAT[0][i] << 32)

            | env->DBAT[1][i];

        sregs.u.s.ppc32.ibat[i] = ((uint64_t)env->IBAT[0][i] << 32)

            | env->IBAT[1][i];

    }



    return kvm_vcpu_ioctl(CPU(cpu), KVM_SET_SREGS, &sregs);

}

static int kvm_get_fpu(CPUState *env)

{

    struct kvm_fpu fpu;

    int i, ret;



    ret = kvm_vcpu_ioctl(env, KVM_GET_FPU, &fpu);

    if (ret < 0)

        return ret;



    env->fpstt = (fpu.fsw >> 11) & 7;

    env->fpus = fpu.fsw;

    env->fpuc = fpu.fcw;

    for (i = 0; i < 8; ++i)

	env->fptags[i] = !((fpu.ftwx >> i) & 1);

    memcpy(env->fpregs, fpu.fpr, sizeof env->fpregs);

    memcpy(env->xmm_regs, fpu.xmm, sizeof env->xmm_regs);

    env->mxcsr = fpu.mxcsr;



    return 0;

}

static int kvm_get_msrs(CPUState *env)

{

    struct {

        struct kvm_msrs info;

        struct kvm_msr_entry entries[100];

    } msr_data;

    struct kvm_msr_entry *msrs = msr_data.entries;

    int ret, i, n;



    n = 0;

    msrs[n++].index = MSR_IA32_SYSENTER_CS;

    msrs[n++].index = MSR_IA32_SYSENTER_ESP;

    msrs[n++].index = MSR_IA32_SYSENTER_EIP;

    if (kvm_has_msr_star(env)) {

        msrs[n++].index = MSR_STAR;

    }

    if (kvm_has_msr_hsave_pa(env)) {

        msrs[n++].index = MSR_VM_HSAVE_PA;

    }

    msrs[n++].index = MSR_IA32_TSC;

#ifdef TARGET_X86_64

    if (lm_capable_kernel) {

        msrs[n++].index = MSR_CSTAR;

        msrs[n++].index = MSR_KERNELGSBASE;

        msrs[n++].index = MSR_FMASK;

        msrs[n++].index = MSR_LSTAR;

    }

#endif

    msrs[n++].index = MSR_KVM_SYSTEM_TIME;

    msrs[n++].index = MSR_KVM_WALL_CLOCK;

#ifdef KVM_CAP_ASYNC_PF

    msrs[n++].index = MSR_KVM_ASYNC_PF_EN;

#endif



#ifdef KVM_CAP_MCE

    if (env->mcg_cap) {

        msrs[n++].index = MSR_MCG_STATUS;

        msrs[n++].index = MSR_MCG_CTL;

        for (i = 0; i < (env->mcg_cap & 0xff) * 4; i++) {

            msrs[n++].index = MSR_MC0_CTL + i;

        }

    }

#endif



    msr_data.info.nmsrs = n;

    ret = kvm_vcpu_ioctl(env, KVM_GET_MSRS, &msr_data);

    if (ret < 0) {

        return ret;

    }



    for (i = 0; i < ret; i++) {

        switch (msrs[i].index) {

        case MSR_IA32_SYSENTER_CS:

            env->sysenter_cs = msrs[i].data;

            break;

        case MSR_IA32_SYSENTER_ESP:

            env->sysenter_esp = msrs[i].data;

            break;

        case MSR_IA32_SYSENTER_EIP:

            env->sysenter_eip = msrs[i].data;

            break;

        case MSR_STAR:

            env->star = msrs[i].data;

            break;

#ifdef TARGET_X86_64

        case MSR_CSTAR:

            env->cstar = msrs[i].data;

            break;

        case MSR_KERNELGSBASE:

            env->kernelgsbase = msrs[i].data;

            break;

        case MSR_FMASK:

            env->fmask = msrs[i].data;

            break;

        case MSR_LSTAR:

            env->lstar = msrs[i].data;

            break;

#endif

        case MSR_IA32_TSC:

            env->tsc = msrs[i].data;

            break;

        case MSR_VM_HSAVE_PA:

            env->vm_hsave = msrs[i].data;

            break;

        case MSR_KVM_SYSTEM_TIME:

            env->system_time_msr = msrs[i].data;

            break;

        case MSR_KVM_WALL_CLOCK:

            env->wall_clock_msr = msrs[i].data;

            break;

#ifdef KVM_CAP_MCE

        case MSR_MCG_STATUS:

            env->mcg_status = msrs[i].data;

            break;

        case MSR_MCG_CTL:

            env->mcg_ctl = msrs[i].data;

            break;

#endif

        default:

#ifdef KVM_CAP_MCE

            if (msrs[i].index >= MSR_MC0_CTL &&

                msrs[i].index < MSR_MC0_CTL + (env->mcg_cap & 0xff) * 4) {

                env->mce_banks[msrs[i].index - MSR_MC0_CTL] = msrs[i].data;

            }

#endif

            break;

#ifdef KVM_CAP_ASYNC_PF

        case MSR_KVM_ASYNC_PF_EN:

            env->async_pf_en_msr = msrs[i].data;

            break;

#endif

        }

    }



    return 0;

}

static int kvm_get_xcrs(X86CPU *cpu)

{

    CPUX86State *env = &cpu->env;

    int i, ret;

    struct kvm_xcrs xcrs;



    if (!kvm_has_xcrs()) {

        return 0;

    }



    ret = kvm_vcpu_ioctl(CPU(cpu), KVM_GET_XCRS, &xcrs);

    if (ret < 0) {

        return ret;

    }



    for (i = 0; i < xcrs.nr_xcrs; i++) {

        /* Only support xcr0 now */

        if (xcrs.xcrs[i].xcr == 0) {

            env->xcr0 = xcrs.xcrs[i].value;

            break;

        }

    }

    return 0;

}

static int balloon_parse(const char *arg)

{

    QemuOpts *opts;



    if (strcmp(arg, "none") == 0) {

        return 0;

    }



    if (!strncmp(arg, "virtio", 6)) {

        if (arg[6] == ',') {

            /* have params -> parse them */

            opts = qemu_opts_parse(qemu_find_opts("device"), arg+7, 0);

            if (!opts)

                return  -1;

        } else {

            /* create empty opts */

            opts = qemu_opts_create(qemu_find_opts("device"), NULL, 0);

        }

        qemu_opt_set(opts, "driver", "virtio-balloon");

        return 0;

    }



    return -1;

}

static void monitor_parse(const char *optarg, const char *mode)

{

    static int monitor_device_index = 0;

    QemuOpts *opts;

    const char *p;

    char label[32];

    int def = 0;



    if (strstart(optarg, "chardev:", &p)) {

        snprintf(label, sizeof(label), "%s", p);

    } else {

        snprintf(label, sizeof(label), "compat_monitor%d",

                 monitor_device_index);

        if (monitor_device_index == 0) {

            def = 1;

        }

        opts = qemu_chr_parse_compat(label, optarg);

        if (!opts) {

            fprintf(stderr, "parse error: %s\n", optarg);

            exit(1);

        }

    }



    opts = qemu_opts_create(qemu_find_opts("mon"), label, 1);

    if (!opts) {

        fprintf(stderr, "duplicate chardev: %s\n", label);

        exit(1);

    }

    qemu_opt_set(opts, "mode", mode);

    qemu_opt_set(opts, "chardev", label);

    if (def)

        qemu_opt_set(opts, "default", "on");

    monitor_device_index++;

}

int qemu_global_option(const char *str)

{

    char driver[64], property[64];

    QemuOpts *opts;

    int rc, offset;



    rc = sscanf(str, "%63[^.].%63[^=]%n", driver, property, &offset);

    if (rc < 2 || str[offset] != '=') {

        error_report("can't parse: \"%s\"", str);

        return -1;

    }



    opts = qemu_opts_create(&qemu_global_opts, NULL, 0, &error_abort);

    qemu_opt_set(opts, "driver", driver, &error_abort);

    qemu_opt_set(opts, "property", property, &error_abort);

    qemu_opt_set(opts, "value", str + offset + 1, &error_abort);

    return 0;

}

static void monitor_parse(const char *optarg, const char *mode, bool pretty)

{

    static int monitor_device_index = 0;

    Error *local_err = NULL;

    QemuOpts *opts;

    const char *p;

    char label[32];

    int def = 0;



    if (strstart(optarg, "chardev:", &p)) {

        snprintf(label, sizeof(label), "%s", p);

    } else {

        snprintf(label, sizeof(label), "compat_monitor%d",

                 monitor_device_index);

        if (monitor_device_index == 0) {

            def = 1;

        }

        opts = qemu_chr_parse_compat(label, optarg);

        if (!opts) {

            fprintf(stderr, "parse error: %s\n", optarg);

            exit(1);

        }

    }



    opts = qemu_opts_create(qemu_find_opts("mon"), label, 1, &local_err);

    if (!opts) {

        error_report_err(local_err);

        exit(1);

    }

    qemu_opt_set(opts, "mode", mode, &error_abort);

    qemu_opt_set(opts, "chardev", label, &error_abort);

    qemu_opt_set_bool(opts, "pretty", pretty, &error_abort);

    if (def)

        qemu_opt_set(opts, "default", "on", &error_abort);

    monitor_device_index++;

}

static void virtio_balloon_receive_stats(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOBalloon *s = VIRTIO_BALLOON(vdev);

    VirtQueueElement *elem;

    VirtIOBalloonStat stat;

    size_t offset = 0;

    qemu_timeval tv;



    s->stats_vq_elem = elem = virtqueue_pop(vq, sizeof(VirtQueueElement));

    if (!elem) {

        goto out;

    }



    /* Initialize the stats to get rid of any stale values.  This is only

     * needed to handle the case where a guest supports fewer stats than it

     * used to (ie. it has booted into an old kernel).

     */

    reset_stats(s);



    while (iov_to_buf(elem->out_sg, elem->out_num, offset, &stat, sizeof(stat))

           == sizeof(stat)) {

        uint16_t tag = virtio_tswap16(vdev, stat.tag);

        uint64_t val = virtio_tswap64(vdev, stat.val);



        offset += sizeof(stat);

        if (tag < VIRTIO_BALLOON_S_NR)

            s->stats[tag] = val;

    }

    s->stats_vq_offset = offset;



    if (qemu_gettimeofday(&tv) < 0) {

        fprintf(stderr, "warning: %s: failed to get time of day\n", __func__);

        goto out;

    }



    s->stats_last_update = tv.tv_sec;



out:

    if (balloon_stats_enabled(s)) {

        balloon_stats_change_timer(s, s->stats_poll_interval);

    }

}

static void virtio_input_handle_sts(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOInputClass *vic = VIRTIO_INPUT_GET_CLASS(vdev);

    VirtIOInput *vinput = VIRTIO_INPUT(vdev);

    virtio_input_event event;

    VirtQueueElement elem;

    int len;



    while (virtqueue_pop(vinput->sts, &elem)) {

        memset(&event, 0, sizeof(event));

        len = iov_to_buf(elem.out_sg, elem.out_num,

                         0, &event, sizeof(event));

        if (vic->handle_status) {

            vic->handle_status(vinput, &event);

        }

        virtqueue_push(vinput->sts, &elem, len);

    }

    virtio_notify(vdev, vinput->sts);

}

static void virtio_balloon_receive_stats(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOBalloon *s = VIRTIO_BALLOON(vdev);

    VirtQueueElement *elem = &s->stats_vq_elem;

    VirtIOBalloonStat stat;

    size_t offset = 0;

    qemu_timeval tv;



    if (!virtqueue_pop(vq, elem)) {

        goto out;

    }



    /* Initialize the stats to get rid of any stale values.  This is only

     * needed to handle the case where a guest supports fewer stats than it

     * used to (ie. it has booted into an old kernel).

     */

    reset_stats(s);



    while (iov_to_buf(elem->out_sg, elem->out_num, offset, &stat, sizeof(stat))

           == sizeof(stat)) {

        uint16_t tag = virtio_tswap16(vdev, stat.tag);

        uint64_t val = virtio_tswap64(vdev, stat.val);



        offset += sizeof(stat);

        if (tag < VIRTIO_BALLOON_S_NR)

            s->stats[tag] = val;

    }

    s->stats_vq_offset = offset;



    if (qemu_gettimeofday(&tv) < 0) {

        fprintf(stderr, "warning: %s: failed to get time of day\n", __func__);

        goto out;

    }



    s->stats_last_update = tv.tv_sec;



out:

    if (balloon_stats_enabled(s)) {

        balloon_stats_change_timer(s, s->stats_poll_interval);

    }

}

static void do_flush_queued_data(VirtIOSerialPort *port, VirtQueue *vq,

                                 VirtIODevice *vdev)

{

    VirtIOSerialPortClass *vsc;



    assert(port);

    assert(virtio_queue_ready(vq));



    vsc = VIRTIO_SERIAL_PORT_GET_CLASS(port);



    while (!port->throttled) {

        unsigned int i;



        /* Pop an elem only if we haven't left off a previous one mid-way */

        if (!port->elem.out_num) {

            if (!virtqueue_pop(vq, &port->elem)) {

                break;

            }

            port->iov_idx = 0;

            port->iov_offset = 0;

        }



        for (i = port->iov_idx; i < port->elem.out_num; i++) {

            size_t buf_size;

            ssize_t ret;



            buf_size = port->elem.out_sg[i].iov_len - port->iov_offset;

            ret = vsc->have_data(port,

                                  port->elem.out_sg[i].iov_base

                                  + port->iov_offset,

                                  buf_size);

            if (port->throttled) {

                port->iov_idx = i;

                if (ret > 0) {

                    port->iov_offset += ret;

                }

                break;

            }

            port->iov_offset = 0;

        }

        if (port->throttled) {

            break;

        }

        virtqueue_push(vq, &port->elem, 0);

        port->elem.out_num = 0;

    }

    virtio_notify(vdev, vq);

}

static av_cold int theora_decode_init(AVCodecContext *avctx)

{

    Vp3DecodeContext *s = avctx->priv_data;

    GetBitContext gb;

    int ptype;

    const uint8_t *header_start[3];

    int header_len[3];

    int i;



    avctx->pix_fmt = AV_PIX_FMT_YUV420P;



    s->theora = 1;



    if (!avctx->extradata_size) {

        av_log(avctx, AV_LOG_ERROR, "Missing extradata!\n");

        return -1;

    }



    if (avpriv_split_xiph_headers(avctx->extradata, avctx->extradata_size,

                                  42, header_start, header_len) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Corrupt extradata\n");

        return -1;

    }



    for (i = 0; i < 3; i++) {

        if (header_len[i] <= 0)

            continue;

        init_get_bits8(&gb, header_start[i], header_len[i]);



        ptype = get_bits(&gb, 8);



        if (!(ptype & 0x80)) {

            av_log(avctx, AV_LOG_ERROR, "Invalid extradata!\n");

//          return -1;

        }



        // FIXME: Check for this as well.

        skip_bits_long(&gb, 6 * 8); /* "theora" */



        switch (ptype) {

        case 0x80:

            if (theora_decode_header(avctx, &gb) < 0)

                return -1;

            break;

        case 0x81:

// FIXME: is this needed? it breaks sometimes

//            theora_decode_comments(avctx, gb);

            break;

        case 0x82:

            if (theora_decode_tables(avctx, &gb))

                return -1;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR,

                   "Unknown Theora config packet: %d\n", ptype & ~0x80);

            break;

        }

        if (ptype != 0x81 && 8 * header_len[i] != get_bits_count(&gb))

            av_log(avctx, AV_LOG_WARNING,

                   "%d bits left in packet %X\n",

                   8 * header_len[i] - get_bits_count(&gb), ptype);

        if (s->theora < 0x030200)

            break;

    }



    return vp3_decode_init(avctx);

}

static av_cold int vorbis_encode_init(AVCodecContext *avccontext)

{

    vorbis_enc_context *venc = avccontext->priv_data;



    if (avccontext->channels != 2) {

        av_log(avccontext, AV_LOG_ERROR, "Current Libav Vorbis encoder only supports 2 channels.\n");

        return -1;

    }



    create_vorbis_context(venc, avccontext);



    if (avccontext->flags & CODEC_FLAG_QSCALE)

        venc->quality = avccontext->global_quality / (float)FF_QP2LAMBDA / 10.;

    else

        venc->quality = 0.03;

    venc->quality *= venc->quality;



    avccontext->extradata_size = put_main_header(venc, (uint8_t**)&avccontext->extradata);



    avccontext->frame_size     = 1 << (venc->log2_blocksize[0] - 1);



    avccontext->coded_frame            = avcodec_alloc_frame();

    avccontext->coded_frame->key_frame = 1;



    return 0;

}

static av_cold int alac_decode_init(AVCodecContext * avctx)

{

    int ret;

    int req_packed;

    ALACContext *alac = avctx->priv_data;

    alac->avctx = avctx;



    /* initialize from the extradata */

    if (alac->avctx->extradata_size != ALAC_EXTRADATA_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "expected %d extradata bytes\n",

            ALAC_EXTRADATA_SIZE);

        return -1;

    }

    if (alac_set_info(alac)) {

        av_log(avctx, AV_LOG_ERROR, "set_info failed\n");

        return -1;

    }



    req_packed = LIBAVCODEC_VERSION_MAJOR < 55 && !av_sample_fmt_is_planar(avctx->request_sample_fmt);

    switch (alac->sample_size) {

    case 16: avctx->sample_fmt = req_packed ? AV_SAMPLE_FMT_S16 : AV_SAMPLE_FMT_S16P;

             break;

    case 24:

    case 32: avctx->sample_fmt = req_packed ? AV_SAMPLE_FMT_S32 : AV_SAMPLE_FMT_S32P;

             break;

    default: av_log_ask_for_sample(avctx, "Sample depth %d is not supported.\n",

                                   alac->sample_size);

             return AVERROR_PATCHWELCOME;

    }

    avctx->bits_per_raw_sample = alac->sample_size;



    if (alac->channels < 1) {

        av_log(avctx, AV_LOG_WARNING, "Invalid channel count\n");

        alac->channels = avctx->channels;

    } else {

        if (alac->channels > MAX_CHANNELS)

            alac->channels = avctx->channels;

        else

            avctx->channels = alac->channels;

    }

    if (avctx->channels > MAX_CHANNELS) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported channel count: %d\n",

               avctx->channels);

        return AVERROR_PATCHWELCOME;

    }

    avctx->channel_layout = alac_channel_layouts[alac->channels - 1];



    if ((ret = allocate_buffers(alac)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating buffers\n");

        return ret;

    }



    avcodec_get_frame_defaults(&alac->frame);

    avctx->coded_frame = &alac->frame;



    return 0;

}

static av_cold int libspeex_decode_init(AVCodecContext *avctx)

{

    LibSpeexContext *s = avctx->priv_data;

    const SpeexMode *mode;



    // defaults in the case of a missing header

    if (avctx->sample_rate <= 8000)

        mode = &speex_nb_mode;

    else if (avctx->sample_rate <= 16000)

        mode = &speex_wb_mode;

    else

        mode = &speex_uwb_mode;



    if (avctx->extradata_size >= 80)

        s->header = speex_packet_to_header(avctx->extradata, avctx->extradata_size);



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    if (s->header) {

        avctx->sample_rate = s->header->rate;

        avctx->channels    = s->header->nb_channels;

        s->frame_size      = s->header->frame_size;



        mode = speex_lib_get_mode(s->header->mode);

        if (!mode) {

            av_log(avctx, AV_LOG_ERROR, "Unknown Speex mode %d", s->header->mode);

            return AVERROR_INVALIDDATA;

        }

    } else

        av_log(avctx, AV_LOG_INFO, "Missing Speex header, assuming defaults.\n");



    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Only stereo and mono are supported.\n");

        return AVERROR(EINVAL);

    }



    speex_bits_init(&s->bits);

    s->dec_state = speex_decoder_init(mode);

    if (!s->dec_state) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing libspeex decoder.\n");

        return -1;

    }



    if (!s->header) {

        speex_decoder_ctl(s->dec_state, SPEEX_GET_FRAME_SIZE, &s->frame_size);

    }



    if (avctx->channels == 2) {

        SpeexCallback callback;

        callback.callback_id = SPEEX_INBAND_STEREO;

        callback.func = speex_std_stereo_request_handler;

        callback.data = &s->stereo;

        s->stereo = (SpeexStereoState)SPEEX_STEREO_STATE_INIT;

        speex_decoder_ctl(s->dec_state, SPEEX_SET_HANDLER, &callback);

    }



    avcodec_get_frame_defaults(&s->frame);

    avctx->coded_frame = &s->frame;



    return 0;

}

static size_t save_page_header(RAMState *rs, RAMBlock *block, ram_addr_t offset)

{

    size_t size, len;



    if (block == rs->last_sent_block) {

        offset |= RAM_SAVE_FLAG_CONTINUE;

    }

    qemu_put_be64(rs->f, offset);

    size = 8;



    if (!(offset & RAM_SAVE_FLAG_CONTINUE)) {

        len = strlen(block->idstr);

        qemu_put_byte(rs->f, len);

        qemu_put_buffer(rs->f, (uint8_t *)block->idstr, len);

        size += 1 + len;

        rs->last_sent_block = block;

    }

    return size;

}

static int qcow2_update_ext_header(BlockDriverState *bs,

    const char *backing_file, const char *backing_fmt)

{

    size_t backing_file_len = 0;

    size_t backing_fmt_len = 0;

    BDRVQcowState *s = bs->opaque;

    QCowExtension ext_backing_fmt = {0, 0};

    int ret;



    /* Backing file format doesn't make sense without a backing file */

    if (backing_fmt && !backing_file) {

        return -EINVAL;

    }



    /* Prepare the backing file format extension if needed */

    if (backing_fmt) {

        ext_backing_fmt.len = cpu_to_be32(strlen(backing_fmt));

        ext_backing_fmt.magic = cpu_to_be32(QCOW_EXT_MAGIC_BACKING_FORMAT);

        backing_fmt_len = ((sizeof(ext_backing_fmt)

            + strlen(backing_fmt) + 7) & ~7);

    }



    /* Check if we can fit the new header into the first cluster */

    if (backing_file) {

        backing_file_len = strlen(backing_file);

    }



    size_t header_size = sizeof(QCowHeader) + backing_file_len

        + backing_fmt_len;



    if (header_size > s->cluster_size) {

        return -ENOSPC;

    }



    /* Rewrite backing file name and qcow2 extensions */

    size_t ext_size = header_size - sizeof(QCowHeader);

    uint8_t buf[ext_size];

    size_t offset = 0;

    size_t backing_file_offset = 0;



    if (backing_file) {

        if (backing_fmt) {

            int padding = backing_fmt_len -

                (sizeof(ext_backing_fmt) + strlen(backing_fmt));



            memcpy(buf + offset, &ext_backing_fmt, sizeof(ext_backing_fmt));

            offset += sizeof(ext_backing_fmt);



            memcpy(buf + offset, backing_fmt, strlen(backing_fmt));

            offset += strlen(backing_fmt);



            memset(buf + offset, 0, padding);

            offset += padding;

        }



        memcpy(buf + offset, backing_file, backing_file_len);

        backing_file_offset = sizeof(QCowHeader) + offset;

    }



    ret = bdrv_pwrite(bs->file, sizeof(QCowHeader), buf, ext_size);

    if (ret < 0) {

        goto fail;

    }



    /* Update header fields */

    uint64_t be_backing_file_offset = cpu_to_be64(backing_file_offset);

    uint32_t be_backing_file_size = cpu_to_be32(backing_file_len);



    ret = bdrv_pwrite(bs->file, offsetof(QCowHeader, backing_file_offset),

        &be_backing_file_offset, sizeof(uint64_t));

    if (ret < 0) {

        goto fail;

    }



    ret = bdrv_pwrite(bs->file, offsetof(QCowHeader, backing_file_size),

        &be_backing_file_size, sizeof(uint32_t));

    if (ret < 0) {

        goto fail;

    }



    ret = 0;

fail:

    return ret;

}

void qemu_put_buffer(QEMUFile *f, const uint8_t *buf, int size)

{

    int l;

    while (size > 0) {

        l = IO_BUF_SIZE - f->buf_index;

        if (l > size)

            l = size;

        memcpy(f->buf + f->buf_index, buf, l);

        f->buf_index += l;

        buf += l;

        size -= l;

        if (f->buf_index >= IO_BUF_SIZE)

            qemu_fflush(f);

    }

}

int qemu_savevm_state_begin(QEMUFile *f)

{

    SaveStateEntry *se;



    qemu_put_be32(f, QEMU_VM_FILE_MAGIC);

    qemu_put_be32(f, QEMU_VM_FILE_VERSION);



    TAILQ_FOREACH(se, &savevm_handlers, entry) {

        int len;



        if (se->save_live_state == NULL)

            continue;



        /* Section type */

        qemu_put_byte(f, QEMU_VM_SECTION_START);

        qemu_put_be32(f, se->section_id);



        /* ID string */

        len = strlen(se->idstr);

        qemu_put_byte(f, len);

        qemu_put_buffer(f, (uint8_t *)se->idstr, len);



        qemu_put_be32(f, se->instance_id);

        qemu_put_be32(f, se->version_id);



        se->save_live_state(f, QEMU_VM_SECTION_START, se->opaque);

    }



    if (qemu_file_has_error(f))

        return -EIO;



    return 0;

}

void qmp_guest_fstrim(bool has_minimum, int64_t minimum, Error **errp)

{

    int ret = 0;

    FsMountList mounts;

    struct FsMount *mount;

    int fd;

    Error *local_err = NULL;

    struct fstrim_range r = {

        .start = 0,

        .len = -1,

        .minlen = has_minimum ? minimum : 0,

    };



    slog("guest-fstrim called");



    QTAILQ_INIT(&mounts);

    build_fs_mount_list(&mounts, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    QTAILQ_FOREACH(mount, &mounts, next) {

        fd = qemu_open(mount->dirname, O_RDONLY);

        if (fd == -1) {

            error_setg_errno(errp, errno, "failed to open %s", mount->dirname);

            goto error;

        }



        /* We try to cull filesytems we know won't work in advance, but other

         * filesytems may not implement fstrim for less obvious reasons.  These

         * will report EOPNOTSUPP; we simply ignore these errors.  Any other

         * error means an unexpected error, so return it in those cases.  In

         * some other cases ENOTTY will be reported (e.g. CD-ROMs).

         */

        ret = ioctl(fd, FITRIM, &r);

        if (ret == -1) {

            if (errno != ENOTTY && errno != EOPNOTSUPP) {

                error_setg_errno(errp, errno, "failed to trim %s",

                                 mount->dirname);

                close(fd);

                goto error;

            }

        }

        close(fd);

    }



error:

    free_fs_mount_list(&mounts);

}

int64_t qmp_guest_file_open(const char *path, bool has_mode, const char *mode, Error **err)

{

    FILE *fh;

    int fd;

    int64_t ret = -1, handle;



    if (!has_mode) {

        mode = "r";

    }

    slog("guest-file-open called, filepath: %s, mode: %s", path, mode);

    fh = fopen(path, mode);

    if (!fh) {

        error_setg_errno(err, errno, "failed to open file '%s' (mode: '%s')",

                         path, mode);

        return -1;

    }



    /* set fd non-blocking to avoid common use cases (like reading from a

     * named pipe) from hanging the agent

     */

    fd = fileno(fh);

    ret = fcntl(fd, F_GETFL);

    ret = fcntl(fd, F_SETFL, ret | O_NONBLOCK);

    if (ret == -1) {

        error_setg_errno(err, errno, "failed to make file '%s' non-blocking",

                         path);

        fclose(fh);

        return -1;

    }



    handle = guest_file_handle_add(fh, err);

    if (error_is_set(err)) {

        fclose(fh);

        return -1;

    }



    slog("guest-file-open, handle: %d", handle);

    return handle;

}

int64_t qmp_guest_fsfreeze_thaw(Error **err)

{

    int ret;

    GuestFsfreezeMountList mounts;

    GuestFsfreezeMount *mount;

    int fd, i = 0, logged;



    QTAILQ_INIT(&mounts);

    ret = guest_fsfreeze_build_mount_list(&mounts);

    if (ret) {

        error_set(err, QERR_QGA_COMMAND_FAILED,

                  "failed to enumerate filesystems");

        return 0;

    }



    QTAILQ_FOREACH(mount, &mounts, next) {

        logged = false;

        fd = qemu_open(mount->dirname, O_RDONLY);

        if (fd == -1) {

            continue;

        }

        /* we have no way of knowing whether a filesystem was actually unfrozen

         * as a result of a successful call to FITHAW, only that if an error

         * was returned the filesystem was *not* unfrozen by that particular

         * call.

         *

         * since multiple preceeding FIFREEZEs require multiple calls to FITHAW

         * to unfreeze, continuing issuing FITHAW until an error is returned,

         * in which case either the filesystem is in an unfreezable state, or,

         * more likely, it was thawed previously (and remains so afterward).

         *

         * also, since the most recent successful call is the one that did

         * the actual unfreeze, we can use this to provide an accurate count

         * of the number of filesystems unfrozen by guest-fsfreeze-thaw, which

         * may * be useful for determining whether a filesystem was unfrozen

         * during the freeze/thaw phase by a process other than qemu-ga.

         */

        do {

            ret = ioctl(fd, FITHAW);

            if (ret == 0 && !logged) {

                i++;

                logged = true;

            }

        } while (ret == 0);

        close(fd);

    }



    guest_fsfreeze_state.status = GUEST_FSFREEZE_STATUS_THAWED;

    enable_logging();

    guest_fsfreeze_free_mount_list(&mounts);

    return i;

}

void qmp_guest_file_close(int64_t handle, Error **err)

{

    GuestFileHandle *gfh = guest_file_handle_find(handle, err);

