        block[0x2F] = temp_block[0x2F]; block[0x37] = temp_block[0x37];

        block[0x3B] = temp_block[0x3E]; block[0x3F] = temp_block[0x3F];

    }else{

        if(last_non_zero_p1 <= 1) goto end;

        block[0x01] = temp_block[0x01];

        block[0x08] = temp_block[0x08]; block[0x10] = temp_block[0x10];

        if(last_non_zero_p1 <= 4) goto end;

        block[0x09] = temp_block[0x09]; block[0x02] = temp_block[0x02];

        block[0x03] = temp_block[0x03];

        if(last_non_zero_p1 <= 7) goto end;

        block[0x0A] = temp_block[0x0A]; block[0x11] = temp_block[0x11];

        block[0x18] = temp_block[0x18]; block[0x20] = temp_block[0x20];

        if(last_non_zero_p1 <= 11) goto end;

        block[0x19] = temp_block[0x19];

        block[0x12] = temp_block[0x12]; block[0x0B] = temp_block[0x0B];

        block[0x04] = temp_block[0x04]; block[0x05] = temp_block[0x05];

        if(last_non_zero_p1 <= 16) goto end;

        block[0x0C] = temp_block[0x0C]; block[0x13] = temp_block[0x13];

        block[0x1A] = temp_block[0x1A]; block[0x21] = temp_block[0x21];

        block[0x28] = temp_block[0x28]; block[0x30] = temp_block[0x30];

        block[0x29] = temp_block[0x29]; block[0x22] = temp_block[0x22];

        if(last_non_zero_p1 <= 24) goto end;

        block[0x1B] = temp_block[0x1B]; block[0x14] = temp_block[0x14];

        block[0x0D] = temp_block[0x0D]; block[0x06] = temp_block[0x06];

        block[0x07] = temp_block[0x07]; block[0x0E] = temp_block[0x0E];

        block[0x15] = temp_block[0x15]; block[0x1C] = temp_block[0x1C];

        if(last_non_zero_p1 <= 32) goto end;

        block[0x23] = temp_block[0x23]; block[0x2A] = temp_block[0x2A];

        block[0x31] = temp_block[0x31]; block[0x38] = temp_block[0x38];

        block[0x39] = temp_block[0x39]; block[0x32] = temp_block[0x32];

        block[0x2B] = temp_block[0x2B]; block[0x24] = temp_block[0x24];

        if(last_non_zero_p1 <= 40) goto end;

        block[0x1D] = temp_block[0x1D]; block[0x16] = temp_block[0x16];

        block[0x0F] = temp_block[0x0F]; block[0x17] = temp_block[0x17];

        block[0x1E] = temp_block[0x1E]; block[0x25] = temp_block[0x25];

        block[0x2C] = temp_block[0x2C]; block[0x33] = temp_block[0x33];

        if(last_non_zero_p1 <= 48) goto end;

        block[0x3A] = temp_block[0x3A]; block[0x3B] = temp_block[0x3B];

        block[0x34] = temp_block[0x34]; block[0x2D] = temp_block[0x2D];

        block[0x26] = temp_block[0x26]; block[0x1F] = temp_block[0x1F];

        block[0x27] = temp_block[0x27]; block[0x2E] = temp_block[0x2E];

        if(last_non_zero_p1 <= 56) goto end;

        block[0x35] = temp_block[0x35]; block[0x3C] = temp_block[0x3C];

        block[0x3D] = temp_block[0x3D]; block[0x36] = temp_block[0x36];

        block[0x2F] = temp_block[0x2F]; block[0x37] = temp_block[0x37];

        block[0x3E] = temp_block[0x3E]; block[0x3F] = temp_block[0x3F];

    }

    end:

    return last_non_zero_p1 - 1;

}

static int RENAME(dct_quantize)(MpegEncContext *s,

                            DCTELEM *block, int n,

                            int qscale)

{

    int i, level, last_non_zero_p1, q;

    const UINT16 *qmat;

    static __align8 INT16 temp_block[64];

    int minLevel, maxLevel;



    if(s->avctx!=NULL && s->avctx->codec->id==CODEC_ID_MPEG4){

	/* mpeg4 */

        minLevel= -2048;

	maxLevel= 2047;

    }else if(s->out_format==FMT_MPEG1){

	/* mpeg1 */

        minLevel= -255;

	maxLevel= 255;

    }else if(s->out_format==FMT_MJPEG){

	/* (m)jpeg */

        minLevel= -1023;

	maxLevel= 1023;

    }else{

	/* h263 / msmpeg4 */

        minLevel= -128;

	maxLevel= 127;

    }



    av_fdct (block);



    if (s->mb_intra) {

        int dummy;

        if (n < 4)

            q = s->y_dc_scale;

        else

            q = s->c_dc_scale;



        /* note: block[0] is assumed to be positive */

#if 1

	asm volatile (

		"xorl %%edx, %%edx	\n\t"

		"mul %%ecx		\n\t"

		: "=d" (temp_block[0]), "=a"(dummy)

		: "a" (block[0] + (q >> 1)), "c" (inverse[q])

	);

#else

	asm volatile (

		"xorl %%edx, %%edx	\n\t"

		"divw %%cx		\n\t"

		"movzwl %%ax, %%eax	\n\t"

		: "=a" (temp_block[0])

		: "a" (block[0] + (q >> 1)), "c" (q)

		: "%edx"

	);

#endif

//        temp_block[0] = (block[0] + (q >> 1)) / q;

        i = 1;

        last_non_zero_p1 = 1;

        if (s->out_format == FMT_H263) {

            qmat = s->q_non_intra_matrix16;

        } else {

            qmat = s->q_intra_matrix16;

        }

        for(i=1;i<4;i++) {

            level = block[i] * qmat[i];

            level = level / (1 << (QMAT_SHIFT_MMX - 3));

            /* XXX: currently, this code is not optimal. the range should be:

               mpeg1: -255..255

               mpeg2: -2048..2047

               h263:  -128..127

               mpeg4: -2048..2047

            */

            if (level > maxLevel)

                level = maxLevel;

            else if (level < minLevel)

                level = minLevel;

            temp_block[i] = level;



	    if(level) 

	        if(last_non_zero_p1 < inv_zigzag_direct16[i]) last_non_zero_p1= inv_zigzag_direct16[i];

	    block[i]=0;

        }

    } else {

        i = 0;

        last_non_zero_p1 = 0;

        qmat = s->q_non_intra_matrix16;

    }



    asm volatile( /* XXX: small rounding bug, but it shouldnt matter */

	"movd %3, %%mm3			\n\t"

	SPREADW(%%mm3)

	"movd %4, %%mm4			\n\t"

	SPREADW(%%mm4)

#ifndef HAVE_MMX2	

	"movd %5, %%mm5			\n\t"

	SPREADW(%%mm5)

#endif

	"pxor %%mm7, %%mm7		\n\t"

	"movd %%eax, %%mm2		\n\t"

	SPREADW(%%mm2)

	"movl %6, %%eax			\n\t"

	".balign 16			\n\t"

	"1:				\n\t"

	"movq (%1, %%eax), %%mm0	\n\t"

	"movq (%2, %%eax), %%mm1	\n\t"

	"movq %%mm0, %%mm6		\n\t"

	"psraw $15, %%mm6		\n\t"

	"pmulhw %%mm0, %%mm1		\n\t"

	"psubsw %%mm6, %%mm1		\n\t"

#ifdef HAVE_MMX2

	"pminsw %%mm3, %%mm1		\n\t"

	"pmaxsw %%mm4, %%mm1		\n\t"

#else

	"paddsw %%mm3, %%mm1		\n\t"

	"psubusw %%mm4, %%mm1		\n\t"

	"paddsw %%mm5, %%mm1		\n\t"

#endif

	"movq %%mm1, (%8, %%eax)	\n\t"

	"pcmpeqw %%mm7, %%mm1		\n\t"

	"movq (%7, %%eax), %%mm0	\n\t"

	"movq %%mm7, (%1, %%eax)	\n\t"

	"pandn %%mm0, %%mm1		\n\t"

	PMAXW(%%mm1, %%mm2)

	"addl $8, %%eax			\n\t"

	" js 1b				\n\t"

	"movq %%mm2, %%mm0		\n\t"

	"psrlq $32, %%mm2		\n\t"

	PMAXW(%%mm0, %%mm2)

	"movq %%mm2, %%mm0		\n\t"

	"psrlq $16, %%mm2		\n\t"

	PMAXW(%%mm0, %%mm2)

	"movd %%mm2, %%eax		\n\t"

	"movzbl %%al, %%eax		\n\t"

	: "+a" (last_non_zero_p1)

	: "r" (block+64), "r" (qmat+64), 

#ifdef HAVE_MMX2

	  "m" (maxLevel),          "m" (minLevel),                    "m" (minLevel /* dummy */), "g" (2*i - 128),

#else

	  "m" (0x7FFF - maxLevel), "m" (0x7FFF -maxLevel + minLevel), "m" (minLevel),             "g" (2*i - 128),

#endif

	  "r" (inv_zigzag_direct16+64), "r" (temp_block+64)

    );

// last_non_zero_p1=64;       

    /* permute for IDCT */

    asm volatile(

	"movl %0, %%eax			\n\t"

	"pushl %%ebp			\n\t"

	"movl %%esp, " MANGLE(esp_temp) "\n\t"

	"1:				\n\t"

	"movzbl (%1, %%eax), %%ebx	\n\t"

	"movzbl 1(%1, %%eax), %%ebp	\n\t"

	"movw (%2, %%ebx, 2), %%cx	\n\t"

	"movw (%2, %%ebp, 2), %%sp	\n\t"

	"movzbl " MANGLE(permutation) "(%%ebx), %%ebx\n\t"

	"movzbl " MANGLE(permutation) "(%%ebp), %%ebp\n\t"

	"movw %%cx, (%3, %%ebx, 2)	\n\t"

	"movw %%sp, (%3, %%ebp, 2)	\n\t"

	"addl $2, %%eax			\n\t"

	" js 1b				\n\t"

	"movl " MANGLE(esp_temp) ", %%esp\n\t"

	"popl %%ebp			\n\t"

	: 

	: "g" (-last_non_zero_p1), "d" (zigzag_direct_noperm+last_non_zero_p1), "S" (temp_block), "D" (block)

	: "%eax", "%ebx", "%ecx"

	);

/*

    for(i=0; i<last_non_zero_p1; i++)

    {

       int j= zigzag_direct_noperm[i];

       block[block_permute_op(j)]= temp_block[j];

    }

*/

//block_permute(block);

    return last_non_zero_p1 - 1;

}

static int RENAME(dct_quantize)(MpegEncContext *s,

                            DCTELEM *block, int n,

                            int qscale, int *overflow)

{

    int level=0, last_non_zero_p1, q; //=0 is cuz gcc says uninitalized ...

    const uint16_t *qmat, *bias;

    static __align8 int16_t temp_block[64];



    //s->fdct (block);

    ff_fdct_mmx (block); //cant be anything else ...



    if (s->mb_intra) {

        int dummy;

        if (n < 4)

            q = s->y_dc_scale;

        else

            q = s->c_dc_scale;

        /* note: block[0] is assumed to be positive */

        if (!s->h263_aic) {

#if 1

        asm volatile (

        	"imul %%ecx		\n\t"

        	: "=d" (level), "=a"(dummy)

        	: "a" ((block[0]>>2) + q), "c" (inverse[q<<1])

        );

#else

        asm volatile (

        	"xorl %%edx, %%edx	\n\t"

        	"divw %%cx		\n\t"

        	"movzwl %%ax, %%eax	\n\t"

        	: "=a" (level)

        	: "a" ((block[0]>>2) + q), "c" (q<<1)

        	: "%edx"

        );

#endif

        } else

            /* For AIC we skip quant/dequant of INTRADC */

            level = (block[0] + 4)>>3;



        block[0]=0; //avoid fake overflow

//        temp_block[0] = (block[0] + (q >> 1)) / q;

        last_non_zero_p1 = 1;

        bias = s->q_intra_matrix16_bias[qscale];

        qmat = s->q_intra_matrix16[qscale];

    } else {

        last_non_zero_p1 = 0;

        bias = s->q_inter_matrix16_bias[qscale];

        qmat = s->q_inter_matrix16[qscale];

    }



    if(s->out_format == FMT_H263 && s->mpeg_quant==0){

	  /* PROLOGUE */

        asm volatile(

            "movd %%eax, %%mm3			\n\t" // last_non_zero_p1

            SPREADW(%%mm3)

            "pxor %%mm7, %%mm7			\n\t" // 0

            "pxor %%mm4, %%mm4			\n\t" // 0

            "movq (%1), %%mm5			\n\t" // qmat[0]

            "pxor %%mm6, %%mm6			\n\t"

            "psubw (%2), %%mm6			\n\t" // -bias[0]

            "movl $-128, %%eax			\n\t"

            : "+a" (last_non_zero_p1)

            : "r" (qmat), "r" (bias)

            );

	  /* CORE */

	  asm volatile(

            ".balign 16				\n\t"

            "1:					\n\t"

            "pxor %%mm1, %%mm1			\n\t" // 0

            "movq (%1, %%eax), %%mm0		\n\t" // block[i]

            "pcmpgtw %%mm0, %%mm1		\n\t" // block[i] <= 0 ? 0xFF : 0x00

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // ABS(block[i])

            "psubusw %%mm6, %%mm0		\n\t" // ABS(block[i]) + bias[0]

            "pmulhw %%mm5, %%mm0		\n\t" // (ABS(block[i])*qmat[0] - bias[0]*qmat[0])>>16

            "por %%mm0, %%mm4			\n\t" 

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // out=((ABS(block[i])*qmat[0] - bias[0]*qmat[0])>>16)*sign(block[i])

            "movq %%mm0, (%3, %%eax)		\n\t"

            "pcmpeqw %%mm7, %%mm0		\n\t" // out==0 ? 0xFF : 0x00

            "movq (%2, %%eax), %%mm1		\n\t" 

            "movq %%mm7, (%1, %%eax)		\n\t" // 0

            "pandn %%mm1, %%mm0			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "addl $8, %%eax			\n\t"

            " js 1b				\n\t"

            : "+a" (last_non_zero_p1)

            : "r" (block+64), "r" (inv_zigzag_direct16+64), "r" (temp_block+64)

            );

	  /* EPILOGUE */

	  asm volatile(

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $32, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $16, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movd %%mm3, %%eax			\n\t"

            "movzbl %%al, %%eax			\n\t" // last_non_zero_p1

            "movd %2, %%mm1			\n\t" // max_qcoeff

	    SPREADW(%%mm1)

            "psubusw %%mm1, %%mm4		\n\t" 

            "packuswb %%mm4, %%mm4		\n\t"

            "movd %%mm4, %1			\n\t" // *overflow

            : "+a" (last_non_zero_p1), "=r" (*overflow)

            : "r" (s->max_qcoeff)

            );

    }else{ // FMT_H263

        asm volatile(

            "pushl %%ebp				\n\t"

            "pushl %%ebx				\n\t"

            "movl %0, %%ebp				\n\t"

            "movl (%%ebp), %%ebx		\n\t"

            "movd %%ebx, %%mm3			\n\t" // last_non_zero_p1

            SPREADW(%%mm3)

            "pxor %%mm7, %%mm7			\n\t" // 0

            "pxor %%mm4, %%mm4			\n\t" // 0

            "movl $-128, %%ebx			\n\t"

            ".balign 16				\n\t"

            "1:					\n\t"

            "pxor %%mm1, %%mm1			\n\t" // 0

            "movq (%1, %%ebx), %%mm0		\n\t" // block[i]

            "pcmpgtw %%mm0, %%mm1		\n\t" // block[i] <= 0 ? 0xFF : 0x00

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // ABS(block[i])

            "movq (%3, %%ebx), %%mm6		\n\t" // bias[0]

            "paddusw %%mm6, %%mm0		\n\t" // ABS(block[i]) + bias[0]

            "movq (%2, %%ebx), %%mm5		\n\t" // qmat[i]

            "pmulhw %%mm5, %%mm0		\n\t" // (ABS(block[i])*qmat[0] + bias[0]*qmat[0])>>16

            "por %%mm0, %%mm4			\n\t" 

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // out=((ABS(block[i])*qmat[0] - bias[0]*qmat[0])>>16)*sign(block[i])

            "movq %%mm0, (%5, %%ebx)		\n\t"

            "pcmpeqw %%mm7, %%mm0		\n\t" // out==0 ? 0xFF : 0x00

            "movq (%4, %%ebx), %%mm1		\n\t" 

            "movq %%mm7, (%1, %%ebx)		\n\t" // 0

            "pandn %%mm1, %%mm0			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "addl $8, %%ebx			\n\t"

            " js 1b				\n\t"

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $32, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $16, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movd %%mm3, %%ebx			\n\t"

            "movzbl %%bl, %%ebx			\n\t" // last_non_zero_p1

            "movl %%ebx, (%%ebp)		\n\t"

            "popl %%ebx					\n\t"

            "popl %%ebp					\n\t"

            :

			: "m" (last_non_zero_p1),

              "r" (block+64), "r" (qmat+64), "r" (bias+64),

              "r" (inv_zigzag_direct16+64), "r" (temp_block+64)

        );

        // note the asm is split cuz gcc doesnt like that many operands ...

        asm volatile(

            "movd %1, %%mm1			\n\t" // max_qcoeff

	    SPREADW(%%mm1)

            "psubusw %%mm1, %%mm4		\n\t" 

            "packuswb %%mm4, %%mm4		\n\t"

            "movd %%mm4, %0			\n\t" // *overflow

        : "=r" (*overflow)

        : "r" (s->max_qcoeff)

        );

    }



    if(s->mb_intra) block[0]= level;

    else            block[0]= temp_block[0];



    if(s->dsp.idct_permutation_type == FF_SIMPLE_IDCT_PERM){

        if(last_non_zero_p1 <= 1) goto end;

        block[0x08] = temp_block[0x01]; block[0x10] = temp_block[0x08]; 

        block[0x20] = temp_block[0x10]; 

        if(last_non_zero_p1 <= 4) goto end;

        block[0x18] = temp_block[0x09]; block[0x04] = temp_block[0x02]; 

        block[0x09] = temp_block[0x03]; 

        if(last_non_zero_p1 <= 7) goto end;

        block[0x14] = temp_block[0x0A]; block[0x28] = temp_block[0x11]; 

        block[0x12] = temp_block[0x18]; block[0x02] = temp_block[0x20]; 

        if(last_non_zero_p1 <= 11) goto end;

        block[0x1A] = temp_block[0x19]; block[0x24] = temp_block[0x12]; 

        block[0x19] = temp_block[0x0B]; block[0x01] = temp_block[0x04]; 

        block[0x0C] = temp_block[0x05]; 

        if(last_non_zero_p1 <= 16) goto end;

        block[0x11] = temp_block[0x0C]; block[0x29] = temp_block[0x13]; 

        block[0x16] = temp_block[0x1A]; block[0x0A] = temp_block[0x21]; 

        block[0x30] = temp_block[0x28]; block[0x22] = temp_block[0x30]; 

        block[0x38] = temp_block[0x29]; block[0x06] = temp_block[0x22]; 

        if(last_non_zero_p1 <= 24) goto end;

        block[0x1B] = temp_block[0x1B]; block[0x21] = temp_block[0x14]; 

        block[0x1C] = temp_block[0x0D]; block[0x05] = temp_block[0x06]; 

        block[0x0D] = temp_block[0x07]; block[0x15] = temp_block[0x0E]; 

        block[0x2C] = temp_block[0x15]; block[0x13] = temp_block[0x1C]; 

        if(last_non_zero_p1 <= 32) goto end;

        block[0x0B] = temp_block[0x23]; block[0x34] = temp_block[0x2A]; 

        block[0x2A] = temp_block[0x31]; block[0x32] = temp_block[0x38]; 

        block[0x3A] = temp_block[0x39]; block[0x26] = temp_block[0x32]; 

        block[0x39] = temp_block[0x2B]; block[0x03] = temp_block[0x24]; 

        if(last_non_zero_p1 <= 40) goto end;

        block[0x1E] = temp_block[0x1D]; block[0x25] = temp_block[0x16]; 

        block[0x1D] = temp_block[0x0F]; block[0x2D] = temp_block[0x17]; 

        block[0x17] = temp_block[0x1E]; block[0x0E] = temp_block[0x25]; 

        block[0x31] = temp_block[0x2C]; block[0x2B] = temp_block[0x33]; 

        if(last_non_zero_p1 <= 48) goto end;

        block[0x36] = temp_block[0x3A]; block[0x3B] = temp_block[0x3B]; 

        block[0x23] = temp_block[0x34]; block[0x3C] = temp_block[0x2D]; 

        block[0x07] = temp_block[0x26]; block[0x1F] = temp_block[0x1F]; 

        block[0x0F] = temp_block[0x27]; block[0x35] = temp_block[0x2E]; 

        if(last_non_zero_p1 <= 56) goto end;

        block[0x2E] = temp_block[0x35]; block[0x33] = temp_block[0x3C]; 

        block[0x3E] = temp_block[0x3D]; block[0x27] = temp_block[0x36]; 

        block[0x3D] = temp_block[0x2F]; block[0x2F] = temp_block[0x37]; 

        block[0x37] = temp_block[0x3E]; block[0x3F] = temp_block[0x3F];

    }else if(s->dsp.idct_permutation_type == FF_LIBMPEG2_IDCT_PERM){

        if(last_non_zero_p1 <= 1) goto end;

        block[0x04] = temp_block[0x01]; 

        block[0x08] = temp_block[0x08]; block[0x10] = temp_block[0x10]; 

        if(last_non_zero_p1 <= 4) goto end;

        block[0x0C] = temp_block[0x09]; block[0x01] = temp_block[0x02]; 

        block[0x05] = temp_block[0x03]; 

        if(last_non_zero_p1 <= 7) goto end;

        block[0x09] = temp_block[0x0A]; block[0x14] = temp_block[0x11]; 

        block[0x18] = temp_block[0x18]; block[0x20] = temp_block[0x20]; 

        if(last_non_zero_p1 <= 11) goto end;

        block[0x1C] = temp_block[0x19]; 

        block[0x11] = temp_block[0x12]; block[0x0D] = temp_block[0x0B]; 

        block[0x02] = temp_block[0x04]; block[0x06] = temp_block[0x05]; 

        if(last_non_zero_p1 <= 16) goto end;

        block[0x0A] = temp_block[0x0C]; block[0x15] = temp_block[0x13]; 

        block[0x19] = temp_block[0x1A]; block[0x24] = temp_block[0x21]; 

        block[0x28] = temp_block[0x28]; block[0x30] = temp_block[0x30]; 

        block[0x2C] = temp_block[0x29]; block[0x21] = temp_block[0x22]; 

        if(last_non_zero_p1 <= 24) goto end;

        block[0x1D] = temp_block[0x1B]; block[0x12] = temp_block[0x14]; 

        block[0x0E] = temp_block[0x0D]; block[0x03] = temp_block[0x06]; 

        block[0x07] = temp_block[0x07]; block[0x0B] = temp_block[0x0E]; 

        block[0x16] = temp_block[0x15]; block[0x1A] = temp_block[0x1C]; 

        if(last_non_zero_p1 <= 32) goto end;

        block[0x25] = temp_block[0x23]; block[0x29] = temp_block[0x2A]; 

        block[0x34] = temp_block[0x31]; block[0x38] = temp_block[0x38]; 

        block[0x3C] = temp_block[0x39]; block[0x31] = temp_block[0x32]; 

        block[0x2D] = temp_block[0x2B]; block[0x22] = temp_block[0x24]; 

        if(last_non_zero_p1 <= 40) goto end;

        block[0x1E] = temp_block[0x1D]; block[0x13] = temp_block[0x16]; 

        block[0x0F] = temp_block[0x0F]; block[0x17] = temp_block[0x17]; 

        block[0x1B] = temp_block[0x1E]; block[0x26] = temp_block[0x25]; 

        block[0x2A] = temp_block[0x2C]; block[0x35] = temp_block[0x33]; 

        if(last_non_zero_p1 <= 48) goto end;

        block[0x39] = temp_block[0x3A]; block[0x3D] = temp_block[0x3B]; 

        block[0x32] = temp_block[0x34]; block[0x2E] = temp_block[0x2D]; 

            block[0x23] = temp_block[0x26]; block[0x1F] = temp_block[0x1F]; 

        block[0x27] = temp_block[0x27]; block[0x2B] = temp_block[0x2E]; 

        if(last_non_zero_p1 <= 56) goto end;

        block[0x36] = temp_block[0x35]; block[0x3A] = temp_block[0x3C]; 

        block[0x3E] = temp_block[0x3D]; block[0x33] = temp_block[0x36]; 

        block[0x2F] = temp_block[0x2F]; block[0x37] = temp_block[0x37]; 

        block[0x3B] = temp_block[0x3E]; block[0x3F] = temp_block[0x3F];

    }else{

        if(last_non_zero_p1 <= 1) goto end;

        block[0x01] = temp_block[0x01]; 

        block[0x08] = temp_block[0x08]; block[0x10] = temp_block[0x10]; 

        if(last_non_zero_p1 <= 4) goto end;

        block[0x09] = temp_block[0x09]; block[0x02] = temp_block[0x02]; 

        block[0x03] = temp_block[0x03]; 

        if(last_non_zero_p1 <= 7) goto end;

        block[0x0A] = temp_block[0x0A]; block[0x11] = temp_block[0x11]; 

        block[0x18] = temp_block[0x18]; block[0x20] = temp_block[0x20]; 

        if(last_non_zero_p1 <= 11) goto end;

        block[0x19] = temp_block[0x19]; 

        block[0x12] = temp_block[0x12]; block[0x0B] = temp_block[0x0B]; 

        block[0x04] = temp_block[0x04]; block[0x05] = temp_block[0x05]; 

        if(last_non_zero_p1 <= 16) goto end;

        block[0x0C] = temp_block[0x0C]; block[0x13] = temp_block[0x13]; 

        block[0x1A] = temp_block[0x1A]; block[0x21] = temp_block[0x21]; 

        block[0x28] = temp_block[0x28]; block[0x30] = temp_block[0x30]; 

        block[0x29] = temp_block[0x29]; block[0x22] = temp_block[0x22]; 

        if(last_non_zero_p1 <= 24) goto end;

        block[0x1B] = temp_block[0x1B]; block[0x14] = temp_block[0x14]; 

        block[0x0D] = temp_block[0x0D]; block[0x06] = temp_block[0x06]; 

        block[0x07] = temp_block[0x07]; block[0x0E] = temp_block[0x0E]; 

        block[0x15] = temp_block[0x15]; block[0x1C] = temp_block[0x1C]; 

        if(last_non_zero_p1 <= 32) goto end;

        block[0x23] = temp_block[0x23]; block[0x2A] = temp_block[0x2A]; 

        block[0x31] = temp_block[0x31]; block[0x38] = temp_block[0x38]; 

        block[0x39] = temp_block[0x39]; block[0x32] = temp_block[0x32]; 

        block[0x2B] = temp_block[0x2B]; block[0x24] = temp_block[0x24]; 

        if(last_non_zero_p1 <= 40) goto end;

        block[0x1D] = temp_block[0x1D]; block[0x16] = temp_block[0x16]; 

        block[0x0F] = temp_block[0x0F]; block[0x17] = temp_block[0x17]; 

        block[0x1E] = temp_block[0x1E]; block[0x25] = temp_block[0x25]; 

        block[0x2C] = temp_block[0x2C]; block[0x33] = temp_block[0x33]; 

        if(last_non_zero_p1 <= 48) goto end;

        block[0x3A] = temp_block[0x3A]; block[0x3B] = temp_block[0x3B]; 

        block[0x34] = temp_block[0x34]; block[0x2D] = temp_block[0x2D]; 

        block[0x26] = temp_block[0x26]; block[0x1F] = temp_block[0x1F]; 

        block[0x27] = temp_block[0x27]; block[0x2E] = temp_block[0x2E]; 

        if(last_non_zero_p1 <= 56) goto end;

        block[0x35] = temp_block[0x35]; block[0x3C] = temp_block[0x3C]; 

        block[0x3D] = temp_block[0x3D]; block[0x36] = temp_block[0x36]; 

        block[0x2F] = temp_block[0x2F]; block[0x37] = temp_block[0x37]; 

        block[0x3E] = temp_block[0x3E]; block[0x3F] = temp_block[0x3F];

    }

    end:

/*

    for(i=0; i<last_non_zero_p1; i++)

    {

       int j= zigzag_direct_noperm[i];

       block[block_permute_op(j)]= temp_block[j];

    }

*/



    return last_non_zero_p1 - 1;

}

static int dct_quantize_c(MpegEncContext *s, 

                        DCTELEM *block, int n,

                        int qscale, int *overflow)

{

    int i, j, level, last_non_zero, q;

    const int *qmat;

    int bias;

    int max=0;

    unsigned int threshold1, threshold2;



    av_fdct (block);



    /* we need this permutation so that we correct the IDCT

       permutation. will be moved into DCT code */

    block_permute(block);



    if (s->mb_intra) {

        if (!s->h263_aic) {

            if (n < 4)

                q = s->y_dc_scale;

            else

                q = s->c_dc_scale;

            q = q << 3;

        } else

            /* For AIC we skip quant/dequant of INTRADC */

            q = 1 << 3;



        /* note: block[0] is assumed to be positive */

        block[0] = (block[0] + (q >> 1)) / q;

        i = 1;

        last_non_zero = 0;

        qmat = s->q_intra_matrix[qscale];

        bias= s->intra_quant_bias<<(QMAT_SHIFT - 3 - QUANT_BIAS_SHIFT);

    } else {

        i = 0;

        last_non_zero = -1;

        qmat = s->q_inter_matrix[qscale];

        bias= s->inter_quant_bias<<(QMAT_SHIFT - 3 - QUANT_BIAS_SHIFT);

    }

    threshold1= (1<<(QMAT_SHIFT - 3)) - bias - 1;

    threshold2= threshold1<<1;



    for(;i<64;i++) {

        j = zigzag_direct[i];

        level = block[j];

        level = level * qmat[j];



//        if(   bias+level >= (1<<(QMAT_SHIFT - 3))

//           || bias-level >= (1<<(QMAT_SHIFT - 3))){

        if(((unsigned)(level+threshold1))>threshold2){

            if(level>0){

                level= (bias + level)>>(QMAT_SHIFT - 3);

                block[j]= level;

            }else{

                level= (bias - level)>>(QMAT_SHIFT - 3);

                block[j]= -level;

            }

            max |=level;

            last_non_zero = i;

        }else{

            block[j]=0;

        }

    }

    *overflow= s->max_qcoeff < max; //overflow might have happend



    return last_non_zero;

}

static void synthfilt_build_sb_samples (QDM2Context *q, GetBitContext *gb, int length, int sb_min, int sb_max)

{

    int sb, j, k, n, ch, run, channels;

    int joined_stereo, zero_encoding, chs;

    int type34_first;

    float type34_div = 0;

    float type34_predictor;

    float samples[10], sign_bits[16];



    if (length == 0) {

        // If no data use noise

        for (sb=sb_min; sb < sb_max; sb++)

            build_sb_samples_from_noise (q, sb);



        return;

    }



    for (sb = sb_min; sb < sb_max; sb++) {

        FIX_NOISE_IDX(q->noise_idx);



        channels = q->nb_channels;



        if (q->nb_channels <= 1 || sb < 12)

            joined_stereo = 0;

        else if (sb >= 24)

            joined_stereo = 1;

        else

            joined_stereo = (get_bits_left(gb) >= 1) ? get_bits1 (gb) : 0;



        if (joined_stereo) {

            if (get_bits_left(gb) >= 16)

                for (j = 0; j < 16; j++)

                    sign_bits[j] = get_bits1 (gb);



            for (j = 0; j < 64; j++)

                if (q->coding_method[1][sb][j] > q->coding_method[0][sb][j])

                    q->coding_method[0][sb][j] = q->coding_method[1][sb][j];



            fix_coding_method_array(sb, q->nb_channels, q->coding_method);

            channels = 1;

        }



        for (ch = 0; ch < channels; ch++) {

            zero_encoding = (get_bits_left(gb) >= 1) ? get_bits1(gb) : 0;

            type34_predictor = 0.0;

            type34_first = 1;



            for (j = 0; j < 128; ) {

                switch (q->coding_method[ch][sb][j / 2]) {

                    case 8:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + 2 * k) >= 128)

                                        break;

                                    samples[2 * k] = get_bits1(gb) ? dequant_1bit[joined_stereo][2 * get_bits1(gb)] : 0;

                                }

                            } else {

                                n = get_bits(gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[2 * k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                            for (k = 0; k < 5; k++)

                                samples[2 * k + 1] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else {

                            for (k = 0; k < 10; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 10;

                        break;



                    case 10:

                        if (get_bits_left(gb) >= 1) {

                            float f = 0.81;



                            if (get_bits1(gb))

                                f = -f;

                            f -= noise_samples[((sb + 1) * (j +5 * ch + 1)) & 127] * 9.0 / 40.0;

                            samples[0] = f;

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    case 16:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + k) >= 128)

                                        break;

                                    samples[k] = (get_bits1(gb) == 0) ? 0 : dequant_1bit[joined_stereo][2 * get_bits1(gb)];

                                }

                            } else {

                                n = get_bits (gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                        } else {

                            for (k = 0; k < 5; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 5;

                        break;



                    case 24:

                        if (get_bits_left(gb) >= 7) {

                            n = get_bits(gb, 7);

                            for (k = 0; k < 3; k++)

                                samples[k] = (random_dequant_type24[n][k] - 2.0) * 0.5;

                        } else {

                            for (k = 0; k < 3; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 3;

                        break;



                    case 30:

                        if (get_bits_left(gb) >= 4)

                            samples[0] = type30_dequant[qdm2_get_vlc(gb, &vlc_tab_type30, 0, 1)];

                        else

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);



                        run = 1;

                        break;



                    case 34:

                        if (get_bits_left(gb) >= 7) {

                            if (type34_first) {

                                type34_div = (float)(1 << get_bits(gb, 2));

                                samples[0] = ((float)get_bits(gb, 5) - 16.0) / 15.0;

                                type34_predictor = samples[0];

                                type34_first = 0;

                            } else {

                                samples[0] = type34_delta[qdm2_get_vlc(gb, &vlc_tab_type34, 0, 1)] / type34_div + type34_predictor;

                                type34_predictor = samples[0];

                            }

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    default:

                        samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        run = 1;

                        break;

                }



                if (joined_stereo) {

                    float tmp[10][MPA_MAX_CHANNELS];



                    for (k = 0; k < run; k++) {

                        tmp[k][0] = samples[k];

                        tmp[k][1] = (sign_bits[(j + k) / 8]) ? -samples[k] : samples[k];

                    }

                    for (chs = 0; chs < q->nb_channels; chs++)

                        for (k = 0; k < run; k++)

                            if ((j + k) < 128)

                                q->sb_samples[chs][j + k][sb] = q->tone_level[chs][sb][((j + k)/2)] * tmp[k][chs];

                } else {

                    for (k = 0; k < run; k++)

                        if ((j + k) < 128)

                            q->sb_samples[ch][j + k][sb] = q->tone_level[ch][sb][(j + k)/2] * samples[k];

                }



                j += run;

            } // j loop

        } // channel loop

    } // subband loop

}

static void qdm2_fft_decode_tones (QDM2Context *q, int duration, GetBitContext *gb, int b)

{

    int channel, stereo, phase, exp;

    int local_int_4,  local_int_8,  stereo_phase,  local_int_10;

    int local_int_14, stereo_exp, local_int_20, local_int_28;

    int n, offset;



    local_int_4 = 0;

    local_int_28 = 0;

    local_int_20 = 2;

    local_int_8 = (4 - duration);

    local_int_10 = 1 << (q->group_order - duration - 1);

    offset = 1;



    while (1) {

        if (q->superblocktype_2_3) {

            while ((n = qdm2_get_vlc(gb, &vlc_tab_fft_tone_offset[local_int_8], 1, 2)) < 2) {

                offset = 1;

                if (n == 0) {

                    local_int_4 += local_int_10;

                    local_int_28 += (1 << local_int_8);

                } else {

                    local_int_4 += 8*local_int_10;

                    local_int_28 += (8 << local_int_8);

                }

            }

            offset += (n - 2);

        } else {

            offset += qdm2_get_vlc(gb, &vlc_tab_fft_tone_offset[local_int_8], 1, 2);

            while (offset >= (local_int_10 - 1)) {

                offset += (1 - (local_int_10 - 1));

                local_int_4  += local_int_10;

                local_int_28 += (1 << local_int_8);

            }

        }



        if (local_int_4 >= q->group_size)

            return;



        local_int_14 = (offset >> local_int_8);

        if (local_int_14 >= FF_ARRAY_ELEMS(fft_level_index_table))

            return;



        if (q->nb_channels > 1) {

            channel = get_bits1(gb);

            stereo = get_bits1(gb);

        } else {

            channel = 0;

            stereo = 0;

        }



        exp = qdm2_get_vlc(gb, (b ? &fft_level_exp_vlc : &fft_level_exp_alt_vlc), 0, 2);

        exp += q->fft_level_exp[fft_level_index_table[local_int_14]];

        exp = (exp < 0) ? 0 : exp;



        phase = get_bits(gb, 3);

        stereo_exp = 0;

        stereo_phase = 0;



        if (stereo) {

            stereo_exp = (exp - qdm2_get_vlc(gb, &fft_stereo_exp_vlc, 0, 1));

            stereo_phase = (phase - qdm2_get_vlc(gb, &fft_stereo_phase_vlc, 0, 1));

            if (stereo_phase < 0)

                stereo_phase += 8;

        }



        if (q->frequency_range > (local_int_14 + 1)) {

            int sub_packet = (local_int_20 + local_int_28);



            qdm2_fft_init_coefficient(q, sub_packet, offset, duration, channel, exp, phase);

            if (stereo)

                qdm2_fft_init_coefficient(q, sub_packet, offset, duration, (1 - channel), stereo_exp, stereo_phase);

        }



        offset++;

    }

}

static int qdm2_get_vlc (GetBitContext *gb, VLC *vlc, int flag, int depth)

{

    int value;



    value = get_vlc2(gb, vlc->table, vlc->bits, depth);



    /* stage-2, 3 bits exponent escape sequence */

    if (value-- == 0)

        value = get_bits (gb, get_bits (gb, 3) + 1);



    /* stage-3, optional */

    if (flag) {

        int tmp = vlc_stage3_values[value];



        if ((value & ~3) > 0)

            tmp += get_bits (gb, (value >> 2));

        value = tmp;

    }



    return value;

}

static void qdm2_decode_fft_packets (QDM2Context *q)

{

    int i, j, min, max, value, type, unknown_flag;

    GetBitContext gb;



    if (q->sub_packet_list_B[0].packet == NULL)

        return;



    /* reset minimum indices for FFT coefficients */

    q->fft_coefs_index = 0;

    for (i=0; i < 5; i++)

        q->fft_coefs_min_index[i] = -1;



    /* process subpackets ordered by type, largest type first */

    for (i = 0, max = 256; i < q->sub_packets_B; i++) {

        QDM2SubPacket *packet;



        /* find subpacket with largest type less than max */

        for (j = 0, min = 0, packet = NULL; j < q->sub_packets_B; j++) {

            value = q->sub_packet_list_B[j].packet->type;

            if (value > min && value < max) {

                min = value;

                packet = q->sub_packet_list_B[j].packet;

            }

        }



        max = min;



        /* check for errors (?) */

        if (i == 0 && (packet->type < 16 || packet->type >= 48 || fft_subpackets[packet->type - 16]))

            return;



        /* decode FFT tones */

        init_get_bits (&gb, packet->data, packet->size*8);



        if (packet->type >= 32 && packet->type < 48 && !fft_subpackets[packet->type - 16])

            unknown_flag = 1;

        else

            unknown_flag = 0;



        type = packet->type;



        if ((type >= 17 && type < 24) || (type >= 33 && type < 40)) {

            int duration = q->sub_sampling + 5 - (type & 15);



            if (duration >= 0 && duration < 4)

                qdm2_fft_decode_tones(q, duration, &gb, unknown_flag);

        } else if (type == 31) {

            for (i=0; i < 4; i++)

                qdm2_fft_decode_tones(q, i, &gb, unknown_flag);

        } else if (type == 46) {

            for (i=0; i < 6; i++)

                q->fft_level_exp[i] = get_bits(&gb, 6);

            for (i=0; i < 4; i++)

            qdm2_fft_decode_tones(q, i, &gb, unknown_flag);

        }

    } // Loop on B packets



    /* calculate maximum indices for FFT coefficients */

    for (i = 0, j = -1; i < 5; i++)

        if (q->fft_coefs_min_index[i] >= 0) {

            if (j >= 0)

                q->fft_coefs_max_index[j] = q->fft_coefs_min_index[i];

            j = i;

        }

    if (j >= 0)

        q->fft_coefs_max_index[j] = q->fft_coefs_index;

}

static void cpu_4xx_wdt_cb (void *opaque)

{

    PowerPCCPU *cpu;

    CPUPPCState *env;

    ppc_tb_t *tb_env;

    ppc40x_timer_t *ppc40x_timer;

    uint64_t now, next;



    env = opaque;

    cpu = ppc_env_get_cpu(env);

    tb_env = env->tb_env;

    ppc40x_timer = tb_env->opaque;

    now = qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL);

    switch ((env->spr[SPR_40x_TCR] >> 30) & 0x3) {

    case 0:

        next = 1 << 17;

        break;

    case 1:

        next = 1 << 21;

        break;

    case 2:

        next = 1 << 25;

        break;

    case 3:

        next = 1 << 29;

        break;

    default:

        /* Cannot occur, but makes gcc happy */

        return;

    }

    next = now + muldiv64(next, get_ticks_per_sec(), tb_env->decr_freq);

    if (next == now)

        next++;

    LOG_TB("%s: TCR " TARGET_FMT_lx " TSR " TARGET_FMT_lx "\n", __func__,

           env->spr[SPR_40x_TCR], env->spr[SPR_40x_TSR]);

    switch ((env->spr[SPR_40x_TSR] >> 30) & 0x3) {

    case 0x0:

    case 0x1:

        timer_mod(ppc40x_timer->wdt_timer, next);

        ppc40x_timer->wdt_next = next;

        env->spr[SPR_40x_TSR] |= 1 << 31;

        break;

    case 0x2:

        timer_mod(ppc40x_timer->wdt_timer, next);

        ppc40x_timer->wdt_next = next;

        env->spr[SPR_40x_TSR] |= 1 << 30;

        if ((env->spr[SPR_40x_TCR] >> 27) & 0x1) {

            ppc_set_irq(cpu, PPC_INTERRUPT_WDT, 1);

        }

        break;

    case 0x3:

        env->spr[SPR_40x_TSR] &= ~0x30000000;

        env->spr[SPR_40x_TSR] |= env->spr[SPR_40x_TCR] & 0x30000000;

        switch ((env->spr[SPR_40x_TCR] >> 28) & 0x3) {

        case 0x0:

            /* No reset */

            break;

        case 0x1: /* Core reset */

            ppc40x_core_reset(cpu);

            break;

        case 0x2: /* Chip reset */

            ppc40x_chip_reset(cpu);

            break;

        case 0x3: /* System reset */

            ppc40x_system_reset(cpu);

            break;

        }

    }

}

static int get_phys_addr_mpu(CPUARMState *env, uint32_t address,

                             int access_type, int is_user,

                             hwaddr *phys_ptr, int *prot)

{

    int n;

    uint32_t mask;

    uint32_t base;



    *phys_ptr = address;

    for (n = 7; n >= 0; n--) {

	base = env->cp15.c6_region[n];

	if ((base & 1) == 0)

	    continue;

	mask = 1 << ((base >> 1) & 0x1f);

	/* Keep this shift separate from the above to avoid an

	   (undefined) << 32.  */

	mask = (mask << 1) - 1;

	if (((base ^ address) & ~mask) == 0)

	    break;

    }

    if (n < 0)

	return 2;



    if (access_type == 2) {

	mask = env->cp15.c5_insn;

    } else {

	mask = env->cp15.c5_data;

    }

    mask = (mask >> (n * 4)) & 0xf;

    switch (mask) {

    case 0:

	return 1;

    case 1:

	if (is_user)

	  return 1;

	*prot = PAGE_READ | PAGE_WRITE;

	break;

    case 2:

	*prot = PAGE_READ;

	if (!is_user)

	    *prot |= PAGE_WRITE;

	break;

    case 3:

	*prot = PAGE_READ | PAGE_WRITE;

	break;

    case 5:

	if (is_user)

	    return 1;

	*prot = PAGE_READ;

	break;

    case 6:

	*prot = PAGE_READ;

	break;

    default:

	/* Bad permission.  */

	return 1;

    }

    *prot |= PAGE_EXEC;

    return 0;

}

static void cuda_receive_packet(CUDAState *s,

                                const uint8_t *data, int len)

{

    uint8_t obuf[16];

    int ti, autopoll;



    switch(data[0]) {

    case CUDA_AUTOPOLL:

        autopoll = (data[1] != 0);

        if (autopoll != s->autopoll) {

            s->autopoll = autopoll;

            if (autopoll) {

                qemu_mod_timer(s->adb_poll_timer,

                               qemu_get_clock(vm_clock) +

                               (ticks_per_sec / CUDA_ADB_POLL_FREQ));

            } else {

                qemu_del_timer(s->adb_poll_timer);

            }

        }

        obuf[0] = CUDA_PACKET;

        obuf[1] = data[1];

        cuda_send_packet_to_host(s, obuf, 2);

        break;

    case CUDA_GET_TIME:

    case CUDA_SET_TIME:

        /* XXX: add time support ? */

        ti = time(NULL) + RTC_OFFSET;

        obuf[0] = CUDA_PACKET;

        obuf[1] = 0;

        obuf[2] = 0;

        obuf[3] = ti >> 24;

        obuf[4] = ti >> 16;

        obuf[5] = ti >> 8;

        obuf[6] = ti;

        cuda_send_packet_to_host(s, obuf, 7);

        break;

    case CUDA_FILE_SERVER_FLAG:

    case CUDA_SET_DEVICE_LIST:

    case CUDA_SET_AUTO_RATE:

    case CUDA_SET_POWER_MESSAGES:

        obuf[0] = CUDA_PACKET;

        obuf[1] = 0;

        cuda_send_packet_to_host(s, obuf, 2);

        break;

    case CUDA_POWERDOWN:

        obuf[0] = CUDA_PACKET;

        obuf[1] = 0;

        cuda_send_packet_to_host(s, obuf, 2);

	qemu_system_shutdown_request();

	break;

    case CUDA_RESET_SYSTEM:

        obuf[0] = CUDA_PACKET;

        obuf[1] = 0;

        cuda_send_packet_to_host(s, obuf, 2);

        qemu_system_reset_request();

        break;

    default:

        break;

    }

}

static uint32_t cuda_readb(void *opaque, target_phys_addr_t addr)

{

    CUDAState *s = opaque;

    uint32_t val;



    addr = (addr >> 9) & 0xf;

    switch(addr) {

    case 0:

        val = s->b;

        break;

    case 1:

        val = s->a;

        break;

    case 2:

        val = s->dirb;

        break;

    case 3:

        val = s->dira;

        break;

    case 4:

        val = get_counter(&s->timers[0]) & 0xff;

        s->ifr &= ~T1_INT;

        cuda_update_irq(s);

        break;

    case 5:

        val = get_counter(&s->timers[0]) >> 8;

        cuda_update_irq(s);

        break;

    case 6:

        val = s->timers[0].latch & 0xff;

        break;

    case 7:

        /* XXX: check this */

        val = (s->timers[0].latch >> 8) & 0xff;

        break;

    case 8:

        val = get_counter(&s->timers[1]) & 0xff;

        s->ifr &= ~T2_INT;

        break;

    case 9:

        val = get_counter(&s->timers[1]) >> 8;

        break;

    case 10:

        val = s->sr;

        s->ifr &= ~SR_INT;

        cuda_update_irq(s);

        break;

    case 11:

        val = s->acr;

        break;

    case 12:

        val = s->pcr;

        break;

    case 13:

        val = s->ifr;

        if (s->ifr & s->ier)

            val |= 0x80;

        break;

    case 14:

        val = s->ier | 0x80;

        break;

    default:

    case 15:

        val = s->anh;

        break;

    }

    if (addr != 13 || val != 0) {

        CUDA_DPRINTF("read: reg=0x%x val=%02x\n", (int)addr, val);

    }



    return val;

}

