static int ftp_auth(FTPContext *s)

{

    const char *user = NULL, *pass = NULL;

    char *end = NULL, buf[CONTROL_BUFFER_SIZE], credencials[CREDENTIALS_BUFFER_SIZE];

    int err;

    const int user_codes[] = {331, 230, 0};

    const int pass_codes[] = {230, 0};



    /* Authentication may be repeated, original string has to be saved */

    av_strlcpy(credencials, s->credencials, sizeof(credencials));



    user = av_strtok(credencials, ":", &end);

    pass = av_strtok(end, ":", &end);



    if (!user) {

        user = "anonymous";

        pass = s->anonymous_password ? s->anonymous_password : "nopassword";

    }



    snprintf(buf, sizeof(buf), "USER %s\r\n", user);

    err = ftp_send_command(s, buf, user_codes, NULL);

    if (err == 331) {

        if (pass) {

            snprintf(buf, sizeof(buf), "PASS %s\r\n", pass);

            err = ftp_send_command(s, buf, pass_codes, NULL);

        } else

            return AVERROR(EACCES);

    }

    if (!err)

        return AVERROR(EACCES);



    return 0;

}

void qemu_send_packet(VLANClientState *vc, const uint8_t *buf, int size)

{

    VLANState *vlan = vc->vlan;

    VLANPacket *packet;



    if (vc->link_down)

        return;



#ifdef DEBUG_NET

    printf("vlan %d send:\n", vlan->id);

    hex_dump(stdout, buf, size);

#endif

    if (vlan->delivering) {

        packet = qemu_malloc(sizeof(VLANPacket) + size);

        packet->next = vlan->send_queue;

        packet->sender = vc;

        packet->size = size;

        memcpy(packet->data, buf, size);

        vlan->send_queue = packet;

    } else {

        vlan->delivering = 1;

        qemu_deliver_packet(vc, buf, size);

        while ((packet = vlan->send_queue) != NULL) {

            qemu_deliver_packet(packet->sender, packet->data, packet->size);

            vlan->send_queue = packet->next;

            qemu_free(packet);

        }

        vlan->delivering = 0;

    }

}

static void qemu_net_queue_append_iov(NetQueue *queue,

                                      NetClientState *sender,

                                      unsigned flags,

                                      const struct iovec *iov,

                                      int iovcnt,

                                      NetPacketSent *sent_cb)

{

    NetPacket *packet;

    size_t max_len = 0;

    int i;



    if (queue->nq_count >= queue->nq_maxlen && !sent_cb) {

        return; /* drop if queue full and no callback */

    }

    for (i = 0; i < iovcnt; i++) {

        max_len += iov[i].iov_len;

    }



    packet = g_malloc(sizeof(NetPacket) + max_len);

    packet->sender = sender;

    packet->sent_cb = sent_cb;

    packet->flags = flags;

    packet->size = 0;



    for (i = 0; i < iovcnt; i++) {

        size_t len = iov[i].iov_len;



        memcpy(packet->data + packet->size, iov[i].iov_base, len);

        packet->size += len;

    }




    QTAILQ_INSERT_TAIL(&queue->packets, packet, entry);

}

static ssize_t qemu_enqueue_packet_iov(VLANClientState *sender,

                                       const struct iovec *iov, int iovcnt,

                                       NetPacketSent *sent_cb)

{

    VLANPacket *packet;

    size_t max_len = 0;

    int i;



    max_len = calc_iov_length(iov, iovcnt);



    packet = qemu_malloc(sizeof(VLANPacket) + max_len);

    packet->sender = sender;

    packet->sent_cb = sent_cb;

    packet->size = 0;



    for (i = 0; i < iovcnt; i++) {

        size_t len = iov[i].iov_len;



        memcpy(packet->data + packet->size, iov[i].iov_base, len);

        packet->size += len;

    }



    TAILQ_INSERT_TAIL(&sender->vlan->send_queue, packet, entry);



    return packet->size;

}

