static inline void h264_loop_filter_luma_c(uint8_t *pix, int xstride, int ystride, int alpha, int beta, int8_t *tc0)

{

    int i, d;

    for( i = 0; i < 4; i++ ) {

        if( tc0[i] < 0 ) {

            pix += 4*ystride;

            continue;

        }

        for( d = 0; d < 4; d++ ) {

            const int p0 = pix[-1*xstride];

            const int p1 = pix[-2*xstride];

            const int p2 = pix[-3*xstride];

            const int q0 = pix[0];

            const int q1 = pix[1*xstride];

            const int q2 = pix[2*xstride];



            if( FFABS( p0 - q0 ) < alpha &&

                FFABS( p1 - p0 ) < beta &&

                FFABS( q1 - q0 ) < beta ) {



                int tc = tc0[i];

                int i_delta;



                if( FFABS( p2 - p0 ) < beta ) {

                    if(tc0[i])

                    pix[-2*xstride] = p1 + av_clip( (( p2 + ( ( p0 + q0 + 1 ) >> 1 ) ) >> 1) - p1, -tc0[i], tc0[i] );

                    tc++;

                }

                if( FFABS( q2 - q0 ) < beta ) {

                    if(tc0[i])

                    pix[   xstride] = q1 + av_clip( (( q2 + ( ( p0 + q0 + 1 ) >> 1 ) ) >> 1) - q1, -tc0[i], tc0[i] );

                    tc++;

                }



                i_delta = av_clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );

                pix[-xstride] = av_clip_uint8( p0 + i_delta );    /* p0' */

                pix[0]        = av_clip_uint8( q0 - i_delta );    /* q0' */

            }

            pix += ystride;

        }

    }

}

static unsigned int mszh_decomp(unsigned char * srcptr, int srclen, unsigned char * destptr, unsigned int destsize)

{

    unsigned char *destptr_bak = destptr;

    unsigned char *destptr_end = destptr + destsize;

    unsigned char mask = 0;

    unsigned char maskbit = 0;

    unsigned int ofs, cnt;



    while (srclen > 0 && destptr < destptr_end) {

        if (maskbit == 0) {

            mask = *srcptr++;

            maskbit = 8;

            srclen--;

            continue;

        }

        if ((mask & (1 << (--maskbit))) == 0) {

            if (destptr + 4 > destptr_end)

                break;

            memcpy(destptr, srcptr, 4);

            srclen -= 4;

            destptr += 4;

            srcptr += 4;

        } else {

            ofs = *srcptr++;

            cnt = *srcptr++;

            ofs += cnt * 256;

            cnt = ((cnt >> 3) & 0x1f) + 1;

            ofs &= 0x7ff;

            srclen -= 2;

            cnt *= 4;

            if (destptr + cnt > destptr_end) {

                cnt =  destptr_end - destptr;

            }

            for (; cnt > 0; cnt--) {

                *destptr = *(destptr - ofs);

                destptr++;

            }

        }

    }



    return destptr - destptr_bak;

}

static void xan_unpack(unsigned char *dest, const unsigned char *src, int dest_len)

{

    unsigned char opcode;

    int size;

    unsigned char *dest_end = dest + dest_len;



    while (dest < dest_end) {

        opcode = *src++;



        if (opcode < 0xe0) {

            int size2, back;

            if ( (opcode & 0x80) == 0 ) {



                size = opcode & 3;



                back  = ((opcode & 0x60) << 3) + *src++ + 1;

                size2 = ((opcode & 0x1c) >> 2) + 3;



            } else if ( (opcode & 0x40) == 0 ) {



                size = *src >> 6;



                back  = (bytestream_get_be16(&src) & 0x3fff) + 1;

                size2 = (opcode & 0x3f) + 4;



            } else {



                size = opcode & 3;



                back  = ((opcode & 0x10) << 12) + bytestream_get_be16(&src) + 1;

                size2 = ((opcode & 0x0c) <<  6) + *src++ + 5;

                if (size + size2 > dest_end - dest)

                    return;

            }

            memcpy(dest, src, size);  dest += size;  src += size;

            av_memcpy_backptr(dest, back, size2);

            dest += size2;

        } else {

            int finish = opcode >= 0xfc;

            size = finish ? opcode & 3 : ((opcode & 0x1f) << 2) + 4;



            memcpy(dest, src, size);  dest += size;  src += size;

            if (finish)

                return;

        }

    }

}

static int rle_unpack(unsigned char *src, unsigned char *dest, int len)

{

    unsigned char *ps;

    unsigned char *pd;

    int i, l;



    ps = src;

    pd = dest;

    if (len & 1)

        *pd++ = *ps++;



    len >>= 1;

    i = 0;

    do {

        l = *ps++;

        if (l & 0x80) {

            l = (l & 0x7F) * 2;

            memcpy(pd, ps, l);

            ps += l;

            pd += l;

        } else {

            for (i = 0; i < l; i++) {

                *pd++ = ps[0];

                *pd++ = ps[1];

            }

            ps += 2;

        }

        i += l;

    } while (i < len);



    return (ps - src);

}

static int decode_type1(GetByteContext *gb, PutByteContext *pb)

{

    unsigned opcode, len;

    int high = 0;

    int i, pos;



    while (bytestream2_get_bytes_left(gb) > 0) {

        GetByteContext gbc;



        while (bytestream2_get_bytes_left(gb) > 0) {

            while (bytestream2_get_bytes_left(gb) > 0) {

                opcode = bytestream2_get_byte(gb);

                high = opcode >= 0x20;

                if (high)

                    break;

                if (opcode)

                    break;

                opcode = bytestream2_get_byte(gb);

                if (opcode < 0xF8) {

                    opcode = opcode + 32;

                    break;

                }

                i = opcode - 0xF8;

                if (i) {

                    len = 256;

                    do {

                        len *= 2;

                        --i;

                    } while (i);

                } else {

                    len = 280;

                }

                do {

                    bytestream2_put_le32(pb, bytestream2_get_le32(gb));

                    bytestream2_put_le32(pb, bytestream2_get_le32(gb));

                    len -= 8;

                } while (len && bytestream2_get_bytes_left(gb) > 0);

            }



            if (!high) {

                do {

                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                    --opcode;

                } while (opcode && bytestream2_get_bytes_left(gb) > 0);



                while (bytestream2_get_bytes_left(gb) > 0) {

                    GetByteContext gbc;



                    opcode = bytestream2_get_byte(gb);

                    if (opcode >= 0x20)

                        break;

                    bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);



                    pos = -(opcode | 32 * bytestream2_get_byte(gb)) - 1;

                    bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                }

            }

            high = 0;

            if (opcode < 0x40)

                break;

            bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

            pos = (-((opcode & 0x1F) | 32 * bytestream2_get_byte(gb)) - 1);

            bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            len = (opcode >> 5) - 1;

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                --len;

            } while (len && bytestream2_get_bytes_left(&gbc) > 0);

        }

        len = opcode & 0x1F;

        if (!len) {

            if (!bytestream2_peek_byte(gb)) {

                do {

                    bytestream2_skip(gb, 1);

                    len += 255;

                } while (!bytestream2_peek_byte(gb) && bytestream2_get_bytes_left(gb) > 0);

            }

            len += bytestream2_get_byte(gb) + 31;

        }

        pos = -bytestream2_get_byte(gb);

        bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

        bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos - (bytestream2_get_byte(gb) << 8), SEEK_SET);

        if (bytestream2_tell_p(pb) == bytestream2_tell(&gbc))

            break;

        if (len < 5 || bytestream2_tell_p(pb) - bytestream2_tell(&gbc) < 4) {

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                --len;

            } while (len && bytestream2_get_bytes_left(&gbc) > 0);

        } else {

            bytestream2_put_le32(pb, bytestream2_get_le32(&gbc));

            len--;

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                len--;

            } while (len && bytestream2_get_bytes_left(&gbc) > 0);

        }

    }



    return 0;

}

static int remove_decoded_packets(AVFormatContext *ctx, int64_t scr){

//    MpegMuxContext *s = ctx->priv_data;

    int i;



    for(i=0; i<ctx->nb_streams; i++){

        AVStream *st = ctx->streams[i];

        StreamInfo *stream = st->priv_data;

        PacketDesc *pkt_desc;



        while((pkt_desc= stream->predecode_packet)

              && scr > pkt_desc->dts){ //FIXME > vs >=

            if(stream->buffer_index < pkt_desc->size ||

               stream->predecode_packet == stream->premux_packet){

                av_log(ctx, AV_LOG_ERROR,

                       "buffer underflow i=%d bufi=%d size=%d\n",

                       i, stream->buffer_index, pkt_desc->size);

                break;

