AVStream *add_video_stream(AVFormatContext *oc, int codec_id)

{

    AVCodec *codec;

    AVCodecContext *c;

    AVStream *st;

    uint8_t *picture_buf;

    int size;



    st = av_new_stream(oc, 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        exit(1);

    }



    /* find the mpeg1 video encoder */

    codec = avcodec_find_encoder(codec_id);

    if (!codec) {

        fprintf(stderr, "codec not found\n");

        exit(1);

    }



    c = &st->codec;

    c->codec_type = CODEC_TYPE_VIDEO;



    /* put sample parameters */

    c->bit_rate = 400000;

    /* resolution must be a multiple of two */

    c->width = 352;  

    c->height = 288;

    /* frames per second */

    c->frame_rate = 25;  

    c->frame_rate_base= 1;

    c->gop_size = 12; /* emit one intra frame every twelve frames */



    /* open it */

    if (avcodec_open(c, codec) < 0) {

        fprintf(stderr, "could not open codec\n");

        exit(1);

    }



    /* alloc various buffers */

    picture= avcodec_alloc_frame();

    video_outbuf_size = 100000;

    video_outbuf = malloc(video_outbuf_size);



    size = c->width * c->height;

    picture_buf = malloc((size * 3) / 2); /* size for YUV 420 */



    picture->data[0] = picture_buf;

    picture->data[1] = picture->data[0] + size;

    picture->data[2] = picture->data[1] + size / 4;

    picture->linesize[0] = c->width;

    picture->linesize[1] = c->width / 2;

    picture->linesize[2] = c->width / 2;



    return st;

}

void audio_encode_example(const char *filename)

{

    AVCodec *codec;

    AVCodecContext *c= NULL;

    int frame_size, i, j, out_size, outbuf_size;

    FILE *f;

    short *samples;

    float t, tincr;

    uint8_t *outbuf;



    printf("Audio encoding\n");



    /* find the MP2 encoder */

    codec = avcodec_find_encoder(CODEC_ID_MP2);

    if (!codec) {

        fprintf(stderr, "codec not found\n");

        exit(1);

    }



    c= avcodec_alloc_context();



    /* put sample parameters */

    c->bit_rate = 64000;

    c->sample_rate = 44100;

    c->channels = 2;



    /* open it */

    if (avcodec_open(c, codec) < 0) {

        fprintf(stderr, "could not open codec\n");

        exit(1);

    }



    /* the codec gives us the frame size, in samples */

    frame_size = c->frame_size;

    samples = malloc(frame_size * 2 * c->channels);

    outbuf_size = 10000;

    outbuf = malloc(outbuf_size);



    f = fopen(filename, "w");

    if (!f) {

        fprintf(stderr, "could not open %s\n", filename);

        exit(1);

    }



    /* encode a single tone sound */

    t = 0;

    tincr = 2 * M_PI * 440.0 / c->sample_rate;

    for(i=0;i<200;i++) {

        for(j=0;j<frame_size;j++) {

            samples[2*j] = (int)(sin(t) * 10000);

            samples[2*j+1] = samples[2*j];

            t += tincr;

        }

        /* encode the samples */

        out_size = avcodec_encode_audio(c, outbuf, outbuf_size, samples);

        fwrite(outbuf, 1, out_size, f);

    }

    fclose(f);

    free(outbuf);

    free(samples);



    avcodec_close(c);

    free(c);

}

void video_encode_example(const char *filename)

{

    AVCodec *codec;

    AVCodecContext *c= NULL;

    int i, out_size, size, x, y, outbuf_size;

    FILE *f;

    AVFrame *picture;

    uint8_t *outbuf, *picture_buf;



    printf("Video encoding\n");



    /* find the mpeg1 video encoder */

    codec = avcodec_find_encoder(CODEC_ID_MPEG1VIDEO);

    if (!codec) {

        fprintf(stderr, "codec not found\n");

        exit(1);

    }



    c= avcodec_alloc_context();

    picture= avcodec_alloc_frame();



    /* put sample parameters */

    c->bit_rate = 400000;

    /* resolution must be a multiple of two */

    c->width = 352;  

    c->height = 288;

    /* frames per second */

    c->frame_rate = 25;  

    c->frame_rate_base= 1;

    c->gop_size = 10; /* emit one intra frame every ten frames */

    c->max_b_frames=1;



    /* open it */

    if (avcodec_open(c, codec) < 0) {

        fprintf(stderr, "could not open codec\n");

        exit(1);

    }



    /* the codec gives us the frame size, in samples */



    f = fopen(filename, "w");

    if (!f) {

        fprintf(stderr, "could not open %s\n", filename);

        exit(1);

    }



    /* alloc image and output buffer */

    outbuf_size = 100000;

    outbuf = malloc(outbuf_size);

    size = c->width * c->height;

    picture_buf = malloc((size * 3) / 2); /* size for YUV 420 */



    picture->data[0] = picture_buf;

    picture->data[1] = picture->data[0] + size;

    picture->data[2] = picture->data[1] + size / 4;

    picture->linesize[0] = c->width;

    picture->linesize[1] = c->width / 2;

    picture->linesize[2] = c->width / 2;



    /* encode 1 second of video */

    for(i=0;i<25;i++) {

        fflush(stdout);

        /* prepare a dummy image */

        /* Y */

        for(y=0;y<c->height;y++) {

            for(x=0;x<c->width;x++) {

                picture->data[0][y * picture->linesize[0] + x] = x + y + i * 3;

            }

        }



        /* Cb and Cr */

        for(y=0;y<c->height/2;y++) {

            for(x=0;x<c->width/2;x++) {

                picture->data[1][y * picture->linesize[1] + x] = 128 + y + i * 2;

                picture->data[2][y * picture->linesize[2] + x] = 64 + x + i * 5;

            }

        }



        /* encode the image */

        out_size = avcodec_encode_video(c, outbuf, outbuf_size, picture);

        printf("encoding frame %3d (size=%5d)\n", i, out_size);

        fwrite(outbuf, 1, out_size, f);

    }



    /* get the delayed frames */

    for(; out_size; i++) {

        fflush(stdout);



        out_size = avcodec_encode_video(c, outbuf, outbuf_size, NULL);

        printf("write frame %3d (size=%5d)\n", i, out_size);

        fwrite(outbuf, 1, out_size, f);

    }



    /* add sequence end code to have a real mpeg file */

    outbuf[0] = 0x00;

    outbuf[1] = 0x00;

    outbuf[2] = 0x01;

    outbuf[3] = 0xb7;

    fwrite(outbuf, 1, 4, f);

    fclose(f);

    free(picture_buf);

    free(outbuf);



    avcodec_close(c);

    free(c);

    free(picture);

    printf("\n");

}

static void new_audio_stream(AVFormatContext *oc, int file_idx)

{

    AVStream *st;

    AVOutputStream *ost;

    AVCodec *codec= NULL;

    AVCodecContext *audio_enc;

    enum CodecID codec_id;



    st = av_new_stream(oc, oc->nb_streams < nb_streamid_map ? streamid_map[oc->nb_streams] : 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        ffmpeg_exit(1);

    }

    ost = new_output_stream(oc, file_idx);



    output_codecs = grow_array(output_codecs, sizeof(*output_codecs), &nb_output_codecs, nb_output_codecs + 1);

    if(!audio_stream_copy){

        if (audio_codec_name) {

            codec_id = find_codec_or_die(audio_codec_name, AVMEDIA_TYPE_AUDIO, 1,

                                         avcodec_opts[AVMEDIA_TYPE_AUDIO]->strict_std_compliance);

            codec = avcodec_find_encoder_by_name(audio_codec_name);

            output_codecs[nb_output_codecs-1] = codec;

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_AUDIO);

            codec = avcodec_find_encoder(codec_id);

        }

    }



    avcodec_get_context_defaults3(st->codec, codec);



    ost->bitstream_filters = audio_bitstream_filters;

    audio_bitstream_filters= NULL;



    avcodec_thread_init(st->codec, thread_count);



    audio_enc = st->codec;

    audio_enc->codec_type = AVMEDIA_TYPE_AUDIO;



    if(audio_codec_tag)

        audio_enc->codec_tag= audio_codec_tag;



    if (oc->oformat->flags & AVFMT_GLOBALHEADER) {

        audio_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_AUDIO]->flags|= CODEC_FLAG_GLOBAL_HEADER;

    }

    if (audio_stream_copy) {

        st->stream_copy = 1;

        audio_enc->channels = audio_channels;

        audio_enc->sample_rate = audio_sample_rate;

    } else {

        audio_enc->codec_id = codec_id;

        set_context_opts(audio_enc, avcodec_opts[AVMEDIA_TYPE_AUDIO], AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);



        if (audio_qscale > QSCALE_NONE) {

            audio_enc->flags |= CODEC_FLAG_QSCALE;

            audio_enc->global_quality = st->quality = FF_QP2LAMBDA * audio_qscale;

        }

        audio_enc->channels = audio_channels;

        audio_enc->sample_fmt = audio_sample_fmt;

        audio_enc->sample_rate = audio_sample_rate;

        audio_enc->channel_layout = channel_layout;

        if (av_get_channel_layout_nb_channels(channel_layout) != audio_channels)

            audio_enc->channel_layout = 0;

        choose_sample_fmt(st, codec);

        choose_sample_rate(st, codec);

    }

    audio_enc->time_base= (AVRational){1, audio_sample_rate};

    if (audio_language) {

        av_metadata_set2(&st->metadata, "language", audio_language, 0);

        av_freep(&audio_language);

    }



    /* reset some key parameters */

    audio_disable = 0;

    av_freep(&audio_codec_name);

    audio_stream_copy = 0;

}

static av_cold int ljpeg_encode_init(AVCodecContext *avctx)

{

    LJpegEncContext *s = avctx->priv_data;



    if ((avctx->pix_fmt == AV_PIX_FMT_YUV420P ||

         avctx->pix_fmt == AV_PIX_FMT_YUV422P ||

         avctx->pix_fmt == AV_PIX_FMT_YUV444P ||

         avctx->color_range == AVCOL_RANGE_MPEG) &&

        avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL) {

        av_log(avctx, AV_LOG_ERROR,

               "Limited range YUV is non-standard, set strict_std_compliance to "

               "at least unofficial to use it.\n");

        return AVERROR(EINVAL);

    }



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame)




    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

    avctx->coded_frame->key_frame = 1;



    s->scratch = av_malloc_array(avctx->width + 1, sizeof(*s->scratch));

    if (!s->scratch)

        goto fail;



    ff_idctdsp_init(&s->idsp, avctx);

    ff_init_scantable(s->idsp.idct_permutation, &s->scantable,

                      ff_zigzag_direct);



    ff_mjpeg_init_hvsample(avctx, s->hsample, s->vsample);



    ff_mjpeg_build_huffman_codes(s->huff_size_dc_luminance,

                                 s->huff_code_dc_luminance,

                                 avpriv_mjpeg_bits_dc_luminance,

                                 avpriv_mjpeg_val_dc);

    ff_mjpeg_build_huffman_codes(s->huff_size_dc_chrominance,

                                 s->huff_code_dc_chrominance,

                                 avpriv_mjpeg_bits_dc_chrominance,

                                 avpriv_mjpeg_val_dc);



    return 0;




}

static av_cold int libopenjpeg_encode_close(AVCodecContext *avctx)

{

    LibOpenJPEGContext *ctx = avctx->priv_data;



    opj_cio_close(ctx->stream);

    ctx->stream = NULL;

    opj_destroy_compress(ctx->compress);

