static inline int hpel_motion_lowres(MpegEncContext *s,

                                     uint8_t *dest, uint8_t *src,

                                     int field_based, int field_select,

                                     int src_x, int src_y,

                                     int width, int height, int stride,

                                     int h_edge_pos, int v_edge_pos,

                                     int w, int h, h264_chroma_mc_func *pix_op,

                                     int motion_x, int motion_y)

{

    const int lowres   = s->avctx->lowres;

    const int op_index = FFMIN(lowres, 3);

    const int s_mask   = (2 << lowres) - 1;

    int emu = 0;

    int sx, sy;



    if (s->quarter_sample) {

        motion_x /= 2;

        motion_y /= 2;

    }



    sx = motion_x & s_mask;

    sy = motion_y & s_mask;

    src_x += motion_x >> lowres + 1;

    src_y += motion_y >> lowres + 1;



    src   += src_y * stride + src_x;



    if ((unsigned)src_x > FFMAX( h_edge_pos - (!!sx) - w,                 0) ||

        (unsigned)src_y > FFMAX((v_edge_pos >> field_based) - (!!sy) - h, 0)) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, src, s->linesize, w + 1,

                                (h + 1) << field_based, src_x,

                                src_y   << field_based,

                                h_edge_pos,

                                v_edge_pos);

        src = s->edge_emu_buffer;

        emu = 1;

    }



    sx = (sx << 2) >> lowres;

    sy = (sy << 2) >> lowres;

    if (field_select)

        src += s->linesize;

    pix_op[op_index](dest, src, stride, h, sx, sy);

    return emu;

}

static inline void comp_block(MadContext *t, int mb_x, int mb_y,

                              int j, int mv_x, int mv_y, int add)

{

    MpegEncContext *s = &t->s;

    if (j < 4) {

        comp(t->frame.data[0] + (mb_y*16 + ((j&2)<<2))*t->frame.linesize[0] + mb_x*16 + ((j&1)<<3),

             t->frame.linesize[0],

             t->last_frame.data[0] + (mb_y*16 + ((j&2)<<2) + mv_y)*t->last_frame.linesize[0] + mb_x*16 + ((j&1)<<3) + mv_x,

             t->last_frame.linesize[0], add);

    } else if (!(s->avctx->flags & CODEC_FLAG_GRAY)) {

        int index = j - 3;

        comp(t->frame.data[index] + (mb_y*8)*t->frame.linesize[index] + mb_x * 8,

             t->frame.linesize[index],

             t->last_frame.data[index] + (mb_y * 8 + (mv_y/2))*t->last_frame.linesize[index] + mb_x * 8 + (mv_x/2),

             t->last_frame.linesize[index], add);

    }

}

static inline void rv34_mc(RV34DecContext *r, const int block_type,

                          const int xoff, const int yoff, int mv_off,

                          const int width, const int height, int dir,

                          const int thirdpel, int weighted,

                          qpel_mc_func (*qpel_mc)[16],

                          h264_chroma_mc_func (*chroma_mc))

{

    MpegEncContext *s = &r->s;

    uint8_t *Y, *U, *V, *srcY, *srcU, *srcV;

    int dxy, mx, my, umx, umy, lx, ly, uvmx, uvmy, src_x, src_y, uvsrc_x, uvsrc_y;

    int mv_pos = s->mb_x * 2 + s->mb_y * 2 * s->b8_stride + mv_off;

    int is16x16 = 1;



    if(thirdpel){

        int chroma_mx, chroma_my;

        mx = (s->current_picture_ptr->f.motion_val[dir][mv_pos][0] + (3 << 24)) / 3 - (1 << 24);

        my = (s->current_picture_ptr->f.motion_val[dir][mv_pos][1] + (3 << 24)) / 3 - (1 << 24);

        lx = (s->current_picture_ptr->f.motion_val[dir][mv_pos][0] + (3 << 24)) % 3;

        ly = (s->current_picture_ptr->f.motion_val[dir][mv_pos][1] + (3 << 24)) % 3;

        chroma_mx = s->current_picture_ptr->f.motion_val[dir][mv_pos][0] / 2;

        chroma_my = s->current_picture_ptr->f.motion_val[dir][mv_pos][1] / 2;

        umx = (chroma_mx + (3 << 24)) / 3 - (1 << 24);

        umy = (chroma_my + (3 << 24)) / 3 - (1 << 24);

        uvmx = chroma_coeffs[(chroma_mx + (3 << 24)) % 3];

        uvmy = chroma_coeffs[(chroma_my + (3 << 24)) % 3];

    }else{

        int cx, cy;

        mx = s->current_picture_ptr->f.motion_val[dir][mv_pos][0] >> 2;

        my = s->current_picture_ptr->f.motion_val[dir][mv_pos][1] >> 2;

        lx = s->current_picture_ptr->f.motion_val[dir][mv_pos][0] & 3;

        ly = s->current_picture_ptr->f.motion_val[dir][mv_pos][1] & 3;

        cx = s->current_picture_ptr->f.motion_val[dir][mv_pos][0] / 2;

        cy = s->current_picture_ptr->f.motion_val[dir][mv_pos][1] / 2;

        umx = cx >> 2;

        umy = cy >> 2;

        uvmx = (cx & 3) << 1;

        uvmy = (cy & 3) << 1;

        //due to some flaw RV40 uses the same MC compensation routine for H2V2 and H3V3

        if(uvmx == 6 && uvmy == 6)

            uvmx = uvmy = 4;

    }



    if (HAVE_THREADS && (s->avctx->active_thread_type & FF_THREAD_FRAME)) {

        /* wait for the referenced mb row to be finished */

        int mb_row = FFMIN(s->mb_height - 1, s->mb_y + ((yoff + my + 21) >> 4));

        AVFrame *f = dir ? &s->next_picture_ptr->f : &s->last_picture_ptr->f;

        ff_thread_await_progress(f, mb_row, 0);

    }



    dxy = ly*4 + lx;

    srcY = dir ? s->next_picture_ptr->f.data[0] : s->last_picture_ptr->f.data[0];

    srcU = dir ? s->next_picture_ptr->f.data[1] : s->last_picture_ptr->f.data[1];

    srcV = dir ? s->next_picture_ptr->f.data[2] : s->last_picture_ptr->f.data[2];

    src_x = s->mb_x * 16 + xoff + mx;

    src_y = s->mb_y * 16 + yoff + my;

    uvsrc_x = s->mb_x * 8 + (xoff >> 1) + umx;

    uvsrc_y = s->mb_y * 8 + (yoff >> 1) + umy;

    srcY += src_y * s->linesize + src_x;

    srcU += uvsrc_y * s->uvlinesize + uvsrc_x;

    srcV += uvsrc_y * s->uvlinesize + uvsrc_x;

    if(s->h_edge_pos - (width << 3) < 6 || s->v_edge_pos - (height << 3) < 6 ||

       (unsigned)(src_x - !!lx*2) > s->h_edge_pos - !!lx*2 - (width <<3) - 4 ||

       (unsigned)(src_y - !!ly*2) > s->v_edge_pos - !!ly*2 - (height<<3) - 4) {

        uint8_t *uvbuf = s->edge_emu_buffer + 22 * s->linesize;



        srcY -= 2 + 2*s->linesize;

        s->dsp.emulated_edge_mc(s->edge_emu_buffer, srcY, s->linesize, (width<<3)+6, (height<<3)+6,

                            src_x - 2, src_y - 2, s->h_edge_pos, s->v_edge_pos);

        srcY = s->edge_emu_buffer + 2 + 2*s->linesize;

        s->dsp.emulated_edge_mc(uvbuf     , srcU, s->uvlinesize, (width<<2)+1, (height<<2)+1,

                            uvsrc_x, uvsrc_y, s->h_edge_pos >> 1, s->v_edge_pos >> 1);

        s->dsp.emulated_edge_mc(uvbuf + 16, srcV, s->uvlinesize, (width<<2)+1, (height<<2)+1,

                            uvsrc_x, uvsrc_y, s->h_edge_pos >> 1, s->v_edge_pos >> 1);

        srcU = uvbuf;

        srcV = uvbuf + 16;

    }

    if(!weighted){

        Y = s->dest[0] + xoff      + yoff     *s->linesize;

        U = s->dest[1] + (xoff>>1) + (yoff>>1)*s->uvlinesize;

        V = s->dest[2] + (xoff>>1) + (yoff>>1)*s->uvlinesize;

    }else{

        Y = r->tmp_b_block_y [dir]     +  xoff     +  yoff    *s->linesize;

        U = r->tmp_b_block_uv[dir*2]   + (xoff>>1) + (yoff>>1)*s->uvlinesize;

        V = r->tmp_b_block_uv[dir*2+1] + (xoff>>1) + (yoff>>1)*s->uvlinesize;

    }



    if(block_type == RV34_MB_P_16x8){

        qpel_mc[1][dxy](Y, srcY, s->linesize);

        Y    += 8;

        srcY += 8;

    }else if(block_type == RV34_MB_P_8x16){

        qpel_mc[1][dxy](Y, srcY, s->linesize);

        Y    += 8 * s->linesize;

        srcY += 8 * s->linesize;

    }

    is16x16 = (block_type != RV34_MB_P_8x8) && (block_type != RV34_MB_P_16x8) && (block_type != RV34_MB_P_8x16);

    qpel_mc[!is16x16][dxy](Y, srcY, s->linesize);

    chroma_mc[2-width]   (U, srcU, s->uvlinesize, height*4, uvmx, uvmy);

    chroma_mc[2-width]   (V, srcV, s->uvlinesize, height*4, uvmx, uvmy);

}

static void luma_mc(HEVCContext *s, int16_t *dst, ptrdiff_t dststride,

                    AVFrame *ref, const Mv *mv, int x_off, int y_off,

                    int block_w, int block_h)

{

    HEVCLocalContext *lc = &s->HEVClc;

    uint8_t *src         = ref->data[0];

    ptrdiff_t srcstride  = ref->linesize[0];

    int pic_width        = s->ps.sps->width;

    int pic_height       = s->ps.sps->height;



    int mx         = mv->x & 3;

    int my         = mv->y & 3;

    int extra_left = ff_hevc_qpel_extra_before[mx];

    int extra_top  = ff_hevc_qpel_extra_before[my];



    x_off += mv->x >> 2;

    y_off += mv->y >> 2;

    src   += y_off * srcstride + (x_off << s->ps.sps->pixel_shift);



    if (x_off < extra_left || y_off < extra_top ||

        x_off >= pic_width - block_w - ff_hevc_qpel_extra_after[mx] ||

        y_off >= pic_height - block_h - ff_hevc_qpel_extra_after[my]) {

        const int edge_emu_stride = EDGE_EMU_BUFFER_STRIDE << s->ps.sps->pixel_shift;

        int offset = extra_top * srcstride + (extra_left << s->ps.sps->pixel_shift);

        int buf_offset = extra_top *

                         edge_emu_stride + (extra_left << s->ps.sps->pixel_shift);



        s->vdsp.emulated_edge_mc(lc->edge_emu_buffer, src - offset,

                                 edge_emu_stride, srcstride,

                                 block_w + ff_hevc_qpel_extra[mx],

                                 block_h + ff_hevc_qpel_extra[my],

                                 x_off - extra_left, y_off - extra_top,

                                 pic_width, pic_height);

        src = lc->edge_emu_buffer + buf_offset;

        srcstride = edge_emu_stride;

    }

    s->hevcdsp.put_hevc_qpel[my][mx](dst, dststride, src, srcstride, block_w,

                                     block_h, lc->mc_buffer);

}

void migrate_fd_error(MigrationState *s)

{

    trace_migrate_fd_error();

    assert(s->to_dst_file == NULL);

    migrate_set_state(&s->state, MIGRATION_STATUS_SETUP,

                      MIGRATION_STATUS_FAILED);

    notifier_list_notify(&migration_state_notifiers, s);

}

void migrate_fd_connect(MigrationState *s)

{

    s->state = MIG_STATE_ACTIVE;

    trace_migrate_set_state(MIG_STATE_ACTIVE);



    s->bytes_xfer = 0;

    /* This is a best 1st approximation. ns to ms */

    s->expected_downtime = max_downtime/1000000;



    s->cleanup_bh = qemu_bh_new(migrate_fd_cleanup, s);

    s->file = qemu_fopen_ops(s, &migration_file_ops);



    qemu_file_set_rate_limit(s->file,

                             s->bandwidth_limit / XFER_LIMIT_RATIO);



    qemu_thread_create(&s->thread, migration_thread, s,

                       QEMU_THREAD_JOINABLE);

    notifier_list_notify(&migration_state_notifiers, s);

}

void migrate_fd_error(MigrationState *s)

{

    DPRINTF("setting error state\n");

    s->state = MIG_STATE_ERROR;

    notifier_list_notify(&migration_state_notifiers, s);

    migrate_fd_cleanup(s);

}

void migrate_fd_error(MigrationState *s, const Error *error)

{

    trace_migrate_fd_error(error ? error_get_pretty(error) : "");

    assert(s->to_dst_file == NULL);

    migrate_set_state(&s->state, MIGRATION_STATUS_SETUP,

                      MIGRATION_STATUS_FAILED);

    if (!s->error) {

        s->error = error_copy(error);

    }

    notifier_list_notify(&migration_state_notifiers, s);

}

static void vga_get_text_resolution(VGACommonState *s, int *pwidth, int *pheight,

                                    int *pcwidth, int *pcheight)

{

    int width, cwidth, height, cheight;



    /* total width & height */

    cheight = (s->cr[VGA_CRTC_MAX_SCAN] & 0x1f) + 1;

    cwidth = 8;

    if (!(s->sr[VGA_SEQ_CLOCK_MODE] & VGA_SR01_CHAR_CLK_8DOTS)) {

        cwidth = 9;

    }

    if (s->sr[VGA_SEQ_CLOCK_MODE] & 0x08) {

        cwidth = 16; /* NOTE: no 18 pixel wide */

    }

    width = (s->cr[VGA_CRTC_H_DISP] + 1);

    if (s->cr[VGA_CRTC_V_TOTAL] == 100) {

        /* ugly hack for CGA 160x100x16 - explain me the logic */

        height = 100;

    } else {

        height = s->cr[VGA_CRTC_V_DISP_END] |

            ((s->cr[VGA_CRTC_OVERFLOW] & 0x02) << 7) |

            ((s->cr[VGA_CRTC_OVERFLOW] & 0x40) << 3);

        height = (height + 1) / cheight;

    }



    *pwidth = width;

    *pheight = height;

    *pcwidth = cwidth;

    *pcheight = cheight;

}

static void get_sub_picture(CinepakEncContext *s, int x, int y, AVPicture *in, AVPicture *out)

{

    out->data[0] = in->data[0] + x + y * in->linesize[0];

    out->linesize[0] = in->linesize[0];



    if(s->pix_fmt == AV_PIX_FMT_YUV420P) {

        out->data[1] = in->data[1] + (x >> 1) + (y >> 1) * in->linesize[1];

        out->linesize[1] = in->linesize[1];



        out->data[2] = in->data[2] + (x >> 1) + (y >> 1) * in->linesize[2];

        out->linesize[2] = in->linesize[2];

    }

}

static void validate_thread_parameters(AVCodecContext *avctx)

{

    int frame_threading_supported = (avctx->codec->capabilities & CODEC_CAP_FRAME_THREADS)

                                && !(avctx->flags & CODEC_FLAG_TRUNCATED)

                                && !(avctx->flags & CODEC_FLAG_LOW_DELAY)

                                && !(avctx->flags2 & CODEC_FLAG2_CHUNKS);

    if (avctx->thread_count == 1) {

        avctx->active_thread_type = 0;

    } else if (frame_threading_supported && (avctx->thread_type & FF_THREAD_FRAME)) {

        avctx->active_thread_type = FF_THREAD_FRAME;

    } else {

        avctx->active_thread_type = FF_THREAD_SLICE;

    }

}

