static uint32_t hpet_ram_readl(void *opaque, target_phys_addr_t addr)

{

    HPETState *s = opaque;

    uint64_t cur_tick, index;



    DPRINTF("qemu: Enter hpet_ram_readl at %" PRIx64 "\n", addr);

    index = addr;

    /*address range of all TN regs*/

    if (index >= 0x100 && index <= 0x3ff) {

        uint8_t timer_id = (addr - 0x100) / 0x20;

        HPETTimer *timer = &s->timer[timer_id];



        if (timer_id > s->num_timers) {

            DPRINTF("qemu: timer id out of range\n");

            return 0;

        }



        switch ((addr - 0x100) % 0x20) {

        case HPET_TN_CFG:

            return timer->config;

        case HPET_TN_CFG + 4: // Interrupt capabilities

            return timer->config >> 32;

        case HPET_TN_CMP: // comparator register

            return timer->cmp;

        case HPET_TN_CMP + 4:

            return timer->cmp >> 32;

        case HPET_TN_ROUTE:

            return timer->fsb;

        case HPET_TN_ROUTE + 4:

            return timer->fsb >> 32;

        default:

            DPRINTF("qemu: invalid hpet_ram_readl\n");

            break;

        }

    } else {

        switch (index) {

        case HPET_ID:

            return s->capability;

        case HPET_PERIOD:

            return s->capability >> 32;

        case HPET_CFG:

            return s->config;

        case HPET_CFG + 4:

            DPRINTF("qemu: invalid HPET_CFG + 4 hpet_ram_readl \n");

            return 0;

        case HPET_COUNTER:

            if (hpet_enabled(s)) {

                cur_tick = hpet_get_ticks(s);

            } else {

                cur_tick = s->hpet_counter;

            }

            DPRINTF("qemu: reading counter  = %" PRIx64 "\n", cur_tick);

            return cur_tick;

        case HPET_COUNTER + 4:

            if (hpet_enabled(s)) {

                cur_tick = hpet_get_ticks(s);

            } else {

                cur_tick = s->hpet_counter;

            }

            DPRINTF("qemu: reading counter + 4  = %" PRIx64 "\n", cur_tick);

            return cur_tick >> 32;

        case HPET_STATUS:

            return s->isr;

        default:

            DPRINTF("qemu: invalid hpet_ram_readl\n");

            break;

        }

    }

    return 0;

}

void cpu_dump_state(CPUXtensaState *env, FILE *f, fprintf_function cpu_fprintf,

        int flags)

{

    int i, j;



    cpu_fprintf(f, "PC=%08x\n\n", env->pc);



    for (i = j = 0; i < 256; ++i) {

        if (sregnames[i]) {

            cpu_fprintf(f, "%s=%08x%c", sregnames[i], env->sregs[i],

                    (j++ % 4) == 3 ? '\n' : ' ');

        }

    }



    cpu_fprintf(f, (j % 4) == 0 ? "\n" : "\n\n");



    for (i = j = 0; i < 256; ++i) {

        if (uregnames[i]) {

            cpu_fprintf(f, "%s=%08x%c", uregnames[i], env->uregs[i],

                    (j++ % 4) == 3 ? '\n' : ' ');

        }

    }



    cpu_fprintf(f, (j % 4) == 0 ? "\n" : "\n\n");



    for (i = 0; i < 16; ++i) {

        cpu_fprintf(f, "A%02d=%08x%c", i, env->regs[i],

                (i % 4) == 3 ? '\n' : ' ');

    }



    cpu_fprintf(f, "\n");



    for (i = 0; i < env->config->nareg; ++i) {

        cpu_fprintf(f, "AR%02d=%08x%c", i, env->phys_regs[i],

                (i % 4) == 3 ? '\n' : ' ');

    }



    if (xtensa_option_enabled(env->config, XTENSA_OPTION_FP_COPROCESSOR)) {

        cpu_fprintf(f, "\n");



        for (i = 0; i < 16; ++i) {

            cpu_fprintf(f, "F%02d=%08x (%+10.8e)%c", i,

                    float32_val(env->fregs[i]),

                    *(float *)&env->fregs[i], (i % 2) == 1 ? '\n' : ' ');

        }

    }

}

void cpu_dump_state (CPUCRISState *env, FILE *f, fprintf_function cpu_fprintf,

                     int flags)

{

	int i;

	uint32_t srs;



	if (!env || !f)

		return;



	cpu_fprintf(f, "PC=%x CCS=%x btaken=%d btarget=%x\n"

		    "cc_op=%d cc_src=%d cc_dest=%d cc_result=%x cc_mask=%x\n",

		    env->pc, env->pregs[PR_CCS], env->btaken, env->btarget,

		    env->cc_op,

		    env->cc_src, env->cc_dest, env->cc_result, env->cc_mask);





	for (i = 0; i < 16; i++) {

		cpu_fprintf(f, "%s=%8.8x ",regnames[i], env->regs[i]);

		if ((i + 1) % 4 == 0)

			cpu_fprintf(f, "\n");

	}

	cpu_fprintf(f, "\nspecial regs:\n");

	for (i = 0; i < 16; i++) {

		cpu_fprintf(f, "%s=%8.8x ", pregnames[i], env->pregs[i]);

		if ((i + 1) % 4 == 0)

			cpu_fprintf(f, "\n");

	}

	srs = env->pregs[PR_SRS];

	cpu_fprintf(f, "\nsupport function regs bank %x:\n", srs);

	if (srs < 256) {

		for (i = 0; i < 16; i++) {

			cpu_fprintf(f, "s%2.2d=%8.8x ",

				    i, env->sregs[srs][i]);

			if ((i + 1) % 4 == 0)

				cpu_fprintf(f, "\n");

		}

	}

	cpu_fprintf(f, "\n\n");



}

