static int wma_decode_superframe(AVCodecContext *avctx, void *data,

                                 int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    WMACodecContext *s = avctx->priv_data;

    int nb_frames, bit_offset, i, pos, len, ret;

    uint8_t *q;

    int16_t *samples;



    tprintf(avctx, "***decode_superframe:\n");



    if(buf_size==0){

        s->last_superframe_len = 0;

        return 0;

    }

    if (buf_size < s->block_align)

        return 0;

    buf_size = s->block_align;



    init_get_bits(&s->gb, buf, buf_size*8);



    if (s->use_bit_reservoir) {

        /* read super frame header */

        skip_bits(&s->gb, 4); /* super frame index */

        nb_frames = get_bits(&s->gb, 4) - (s->last_superframe_len <= 0);

    } else {

        nb_frames = 1;

    }



    /* get output buffer */

    s->frame.nb_samples = nb_frames * s->frame_len;

    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = (int16_t *)s->frame.data[0];



    if (s->use_bit_reservoir) {

        bit_offset = get_bits(&s->gb, s->byte_offset_bits + 3);



        if (s->last_superframe_len > 0) {

            //        printf("skip=%d\n", s->last_bitoffset);

            /* add bit_offset bits to last frame */

            if ((s->last_superframe_len + ((bit_offset + 7) >> 3)) >

                MAX_CODED_SUPERFRAME_SIZE)

                goto fail;

            q = s->last_superframe + s->last_superframe_len;

            len = bit_offset;

            while (len > 7) {

                *q++ = (get_bits)(&s->gb, 8);

                len -= 8;

            }

            if (len > 0) {

                *q++ = (get_bits)(&s->gb, len) << (8 - len);

            }



            /* XXX: bit_offset bits into last frame */

            init_get_bits(&s->gb, s->last_superframe, MAX_CODED_SUPERFRAME_SIZE*8);

            /* skip unused bits */

            if (s->last_bitoffset > 0)

                skip_bits(&s->gb, s->last_bitoffset);

            /* this frame is stored in the last superframe and in the

               current one */

            if (wma_decode_frame(s, samples) < 0)

                goto fail;

            samples += s->nb_channels * s->frame_len;

            nb_frames--;

        }



        /* read each frame starting from bit_offset */

        pos = bit_offset + 4 + 4 + s->byte_offset_bits + 3;



        init_get_bits(&s->gb, buf + (pos >> 3), (MAX_CODED_SUPERFRAME_SIZE - (pos >> 3))*8);

        len = pos & 7;

        if (len > 0)

            skip_bits(&s->gb, len);



        s->reset_block_lengths = 1;

        for(i=0;i<nb_frames;i++) {

            if (wma_decode_frame(s, samples) < 0)

                goto fail;

            samples += s->nb_channels * s->frame_len;

        }



        /* we copy the end of the frame in the last frame buffer */

        pos = get_bits_count(&s->gb) + ((bit_offset + 4 + 4 + s->byte_offset_bits + 3) & ~7);

        s->last_bitoffset = pos & 7;

        pos >>= 3;

        len = buf_size - pos;

        if (len > MAX_CODED_SUPERFRAME_SIZE || len < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "len %d invalid\n", len);

            goto fail;

        }

        s->last_superframe_len = len;

        memcpy(s->last_superframe, buf + pos, len);

    } else {

        /* single frame decode */

        if (wma_decode_frame(s, samples) < 0)

            goto fail;

        samples += s->nb_channels * s->frame_len;

    }



//av_log(NULL, AV_LOG_ERROR, "%d %d %d %d outbytes:%d eaten:%d\n", s->frame_len_bits, s->block_len_bits, s->frame_len, s->block_len,        (int8_t *)samples - (int8_t *)data, s->block_align);



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return s->block_align;

 fail:

    /* when error, we reset the bit reservoir */

    s->last_superframe_len = 0;

    return -1;

}

static int mp_decode_layer3(MPADecodeContext *s)

{

    int nb_granules, main_data_begin;

    int gr, ch, blocksplit_flag, i, j, k, n, bits_pos;

    GranuleDef *g;

    int16_t exponents[576]; //FIXME try INTFLOAT



    /* read side info */

    if (s->lsf) {

        main_data_begin = get_bits(&s->gb, 8);

        skip_bits(&s->gb, s->nb_channels);

        nb_granules = 1;

    } else {

        main_data_begin = get_bits(&s->gb, 9);

        if (s->nb_channels == 2)

            skip_bits(&s->gb, 3);

        else

            skip_bits(&s->gb, 5);

        nb_granules = 2;

        for (ch = 0; ch < s->nb_channels; ch++) {

            s->granules[ch][0].scfsi = 0;/* all scale factors are transmitted */

            s->granules[ch][1].scfsi = get_bits(&s->gb, 4);

        }

    }



    for (gr = 0; gr < nb_granules; gr++) {

        for (ch = 0; ch < s->nb_channels; ch++) {

            av_dlog(s->avctx, "gr=%d ch=%d: side_info\n", gr, ch);

            g = &s->granules[ch][gr];

            g->part2_3_length = get_bits(&s->gb, 12);

            g->big_values     = get_bits(&s->gb,  9);

            if (g->big_values > 288) {

                av_log(s->avctx, AV_LOG_ERROR, "big_values too big\n");

                return AVERROR_INVALIDDATA;

            }



            g->global_gain = get_bits(&s->gb, 8);

            /* if MS stereo only is selected, we precompute the

               1/sqrt(2) renormalization factor */

            if ((s->mode_ext & (MODE_EXT_MS_STEREO | MODE_EXT_I_STEREO)) ==

                MODE_EXT_MS_STEREO)

                g->global_gain -= 2;

            if (s->lsf)

                g->scalefac_compress = get_bits(&s->gb, 9);

            else

                g->scalefac_compress = get_bits(&s->gb, 4);

            blocksplit_flag = get_bits1(&s->gb);

            if (blocksplit_flag) {

                g->block_type = get_bits(&s->gb, 2);

                if (g->block_type == 0) {

                    av_log(s->avctx, AV_LOG_ERROR, "invalid block type\n");

                    return AVERROR_INVALIDDATA;

                }

                g->switch_point = get_bits1(&s->gb);

                for (i = 0; i < 2; i++)

                    g->table_select[i] = get_bits(&s->gb, 5);

                for (i = 0; i < 3; i++)

                    g->subblock_gain[i] = get_bits(&s->gb, 3);

                ff_init_short_region(s, g);

            } else {

                int region_address1, region_address2;

                g->block_type = 0;

                g->switch_point = 0;

                for (i = 0; i < 3; i++)

                    g->table_select[i] = get_bits(&s->gb, 5);

                /* compute huffman coded region sizes */

                region_address1 = get_bits(&s->gb, 4);

                region_address2 = get_bits(&s->gb, 3);

                av_dlog(s->avctx, "region1=%d region2=%d\n",

                        region_address1, region_address2);

                ff_init_long_region(s, g, region_address1, region_address2);

            }

            ff_region_offset2size(g);

            ff_compute_band_indexes(s, g);



            g->preflag = 0;

            if (!s->lsf)

                g->preflag = get_bits1(&s->gb);

            g->scalefac_scale     = get_bits1(&s->gb);

            g->count1table_select = get_bits1(&s->gb);

            av_dlog(s->avctx, "block_type=%d switch_point=%d\n",

                    g->block_type, g->switch_point);

        }

    }



    if (!s->adu_mode) {

        const uint8_t *ptr = s->gb.buffer + (get_bits_count(&s->gb)>>3);

        assert((get_bits_count(&s->gb) & 7) == 0);

        /* now we get bits from the main_data_begin offset */

        av_dlog(s->avctx, "seekback: %d\n", main_data_begin);

    //av_log(NULL, AV_LOG_ERROR, "backstep:%d, lastbuf:%d\n", main_data_begin, s->last_buf_size);



        memcpy(s->last_buf + s->last_buf_size, ptr, EXTRABYTES);

        s->in_gb = s->gb;

        init_get_bits(&s->gb, s->last_buf, s->last_buf_size*8);

#if !UNCHECKED_BITSTREAM_READER

        s->gb.size_in_bits_plus8 += EXTRABYTES * 8;

#endif

        s->last_buf_size <<= 3;

        for (gr = 0, ch = 0; gr < nb_granules && (s->last_buf_size >> 3) < main_data_begin; gr++, ch = 0) {

            for (; ch < s->nb_channels && (s->last_buf_size >> 3) < main_data_begin; ch++) {

                g = &s->granules[ch][gr];

                s->last_buf_size += g->part2_3_length;

                memset(g->sb_hybrid, 0, sizeof(g->sb_hybrid));

            }

        }

        skip_bits_long(&s->gb, s->last_buf_size - 8 * main_data_begin);

        if (get_bits_count(&s->gb) >= s->gb.size_in_bits && s->in_gb.buffer) {

            skip_bits_long(&s->in_gb, get_bits_count(&s->gb) - s->gb.size_in_bits);

            s->gb           = s->in_gb;

            s->in_gb.buffer = NULL;

        }

    } else {

        gr = ch = 0;

    }



    for (; gr < nb_granules; gr++, ch = 0) {

        for (; ch < s->nb_channels; ch++) {

            g = &s->granules[ch][gr];

            bits_pos = get_bits_count(&s->gb);



            if (!s->lsf) {

                uint8_t *sc;

                int slen, slen1, slen2;



                /* MPEG1 scale factors */

                slen1 = slen_table[0][g->scalefac_compress];

                slen2 = slen_table[1][g->scalefac_compress];

                av_dlog(s->avctx, "slen1=%d slen2=%d\n", slen1, slen2);

                if (g->block_type == 2) {

                    n = g->switch_point ? 17 : 18;

                    j = 0;

                    if (slen1) {

                        for (i = 0; i < n; i++)

                            g->scale_factors[j++] = get_bits(&s->gb, slen1);

                    } else {

                        for (i = 0; i < n; i++)

                            g->scale_factors[j++] = 0;

                    }

                    if (slen2) {

                        for (i = 0; i < 18; i++)

                            g->scale_factors[j++] = get_bits(&s->gb, slen2);

                        for (i = 0; i < 3; i++)

                            g->scale_factors[j++] = 0;

                    } else {

                        for (i = 0; i < 21; i++)

                            g->scale_factors[j++] = 0;

                    }

                } else {

                    sc = s->granules[ch][0].scale_factors;

                    j = 0;

                    for (k = 0; k < 4; k++) {

                        n = k == 0 ? 6 : 5;

                        if ((g->scfsi & (0x8 >> k)) == 0) {

                            slen = (k < 2) ? slen1 : slen2;

                            if (slen) {

                                for (i = 0; i < n; i++)

                                    g->scale_factors[j++] = get_bits(&s->gb, slen);

                            } else {

                                for (i = 0; i < n; i++)

                                    g->scale_factors[j++] = 0;

                            }

                        } else {

                            /* simply copy from last granule */

                            for (i = 0; i < n; i++) {

                                g->scale_factors[j] = sc[j];

                                j++;

                            }

                        }

                    }

                    g->scale_factors[j++] = 0;

                }

            } else {

                int tindex, tindex2, slen[4], sl, sf;



                /* LSF scale factors */

                if (g->block_type == 2)

                    tindex = g->switch_point ? 2 : 1;

                else

                    tindex = 0;



                sf = g->scalefac_compress;

                if ((s->mode_ext & MODE_EXT_I_STEREO) && ch == 1) {

                    /* intensity stereo case */

                    sf >>= 1;

                    if (sf < 180) {

                        lsf_sf_expand(slen, sf, 6, 6, 0);

                        tindex2 = 3;

                    } else if (sf < 244) {

                        lsf_sf_expand(slen, sf - 180, 4, 4, 0);

                        tindex2 = 4;

                    } else {

                        lsf_sf_expand(slen, sf - 244, 3, 0, 0);

                        tindex2 = 5;

                    }

                } else {

                    /* normal case */

                    if (sf < 400) {

                        lsf_sf_expand(slen, sf, 5, 4, 4);

                        tindex2 = 0;

                    } else if (sf < 500) {

                        lsf_sf_expand(slen, sf - 400, 5, 4, 0);

                        tindex2 = 1;

                    } else {

                        lsf_sf_expand(slen, sf - 500, 3, 0, 0);

                        tindex2 = 2;

                        g->preflag = 1;

                    }

                }



                j = 0;

                for (k = 0; k < 4; k++) {

                    n  = lsf_nsf_table[tindex2][tindex][k];

                    sl = slen[k];

                    if (sl) {

                        for (i = 0; i < n; i++)

                            g->scale_factors[j++] = get_bits(&s->gb, sl);

                    } else {

                        for (i = 0; i < n; i++)

                            g->scale_factors[j++] = 0;

                    }

                }

                /* XXX: should compute exact size */

                for (; j < 40; j++)

                    g->scale_factors[j] = 0;

            }



            exponents_from_scale_factors(s, g, exponents);



            /* read Huffman coded residue */

            huffman_decode(s, g, exponents, bits_pos + g->part2_3_length);

        } /* ch */



        if (s->nb_channels == 2)

            compute_stereo(s, &s->granules[0][gr], &s->granules[1][gr]);



        for (ch = 0; ch < s->nb_channels; ch++) {

            g = &s->granules[ch][gr];



            reorder_block(s, g);

            compute_antialias(s, g);

            compute_imdct(s, g, &s->sb_samples[ch][18 * gr][0], s->mdct_buf[ch]);

        }

    } /* gr */

    if (get_bits_count(&s->gb) < 0)

        skip_bits_long(&s->gb, -get_bits_count(&s->gb));

    return nb_granules * 18;

}

static int mp_decode_frame(MPADecodeContext *s,

                           OUT_INT *samples, const uint8_t *buf, int buf_size)

{

    int i, nb_frames, ch;

    OUT_INT *samples_ptr;



    init_get_bits(&s->gb, buf + HEADER_SIZE, (buf_size - HEADER_SIZE)*8);



    /* skip error protection field */

    if (s->error_protection)

        skip_bits(&s->gb, 16);



    dprintf(s->avctx, "frame %d:\n", s->frame_count);

    switch(s->layer) {

    case 1:

        s->avctx->frame_size = 384;

        nb_frames = mp_decode_layer1(s);

        break;

    case 2:

        s->avctx->frame_size = 1152;

        nb_frames = mp_decode_layer2(s);

        break;

    case 3:

        s->avctx->frame_size = s->lsf ? 576 : 1152;

    default:

        nb_frames = mp_decode_layer3(s);



        s->last_buf_size=0;

        if(s->in_gb.buffer){

            align_get_bits(&s->gb);

            i= (s->gb.size_in_bits - get_bits_count(&s->gb))>>3;

            if(i >= 0 && i <= BACKSTEP_SIZE){

                memmove(s->last_buf, s->gb.buffer + (get_bits_count(&s->gb)>>3), i);

                s->last_buf_size=i;

            }else

                av_log(s->avctx, AV_LOG_ERROR, "invalid old backstep %d\n", i);

            s->gb= s->in_gb;

            s->in_gb.buffer= NULL;

        }



        align_get_bits(&s->gb);

        assert((get_bits_count(&s->gb) & 7) == 0);

        i= (s->gb.size_in_bits - get_bits_count(&s->gb))>>3;



        if(i<0 || i > BACKSTEP_SIZE || nb_frames<0){

            av_log(s->avctx, AV_LOG_WARNING, "invalid new backstep %d\n", i);

            i= FFMIN(BACKSTEP_SIZE, buf_size - HEADER_SIZE);

        }

        assert(i <= buf_size - HEADER_SIZE && i>= 0);

        memcpy(s->last_buf + s->last_buf_size, s->gb.buffer + buf_size - HEADER_SIZE - i, i);

        s->last_buf_size += i;



        break;

    }



    /* apply the synthesis filter */

    for(ch=0;ch<s->nb_channels;ch++) {

        samples_ptr = samples + ch;

        for(i=0;i<nb_frames;i++) {

            ff_mpa_synth_filter(s->synth_buf[ch], &(s->synth_buf_offset[ch]),

                         window, &s->dither_state,

                         samples_ptr, s->nb_channels,

                         s->sb_samples[ch][i]);

            samples_ptr += 32 * s->nb_channels;

        }

    }



    return nb_frames * 32 * sizeof(OUT_INT) * s->nb_channels;

}

static int flac_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            const uint8_t *buf, int buf_size)

{

    FLACContext *s = avctx->priv_data;

    int tmp = 0, i, j = 0, input_buf_size = 0;

    int16_t *samples_16 = data;

    int32_t *samples_32 = data;

    int alloc_data_size= *data_size;



    *data_size=0;



    if (s->max_framesize == 0) {

        s->max_framesize= FFMAX(4, buf_size); // should hopefully be enough for the first header

        s->bitstream= av_fast_realloc(s->bitstream, &s->allocated_bitstream_size, s->max_framesize);

    }



    if (1 && s->max_framesize) { //FIXME truncated

        if (s->bitstream_size < 4 || AV_RL32(s->bitstream) != MKTAG('f','L','a','C'))

            buf_size= FFMIN(buf_size, s->max_framesize - FFMIN(s->bitstream_size, s->max_framesize));

        input_buf_size= buf_size;



        if (s->bitstream_size + buf_size < buf_size || s->bitstream_index + s->bitstream_size + buf_size < s->bitstream_index)

            return -1;



        if (s->allocated_bitstream_size < s->bitstream_size + buf_size)

            s->bitstream= av_fast_realloc(s->bitstream, &s->allocated_bitstream_size, s->bitstream_size + buf_size);



        if (s->bitstream_index + s->bitstream_size + buf_size > s->allocated_bitstream_size) {

            memmove(s->bitstream, &s->bitstream[s->bitstream_index],

                    s->bitstream_size);

            s->bitstream_index=0;

        }

        memcpy(&s->bitstream[s->bitstream_index + s->bitstream_size],

               buf, buf_size);

        buf= &s->bitstream[s->bitstream_index];

        buf_size += s->bitstream_size;

        s->bitstream_size= buf_size;



        if (buf_size < s->max_framesize && input_buf_size) {

            return input_buf_size;

        }

    }



    init_get_bits(&s->gb, buf, buf_size*8);



    if (metadata_parse(s))

        goto end;



    tmp = show_bits(&s->gb, 16);

    if ((tmp & 0xFFFE) != 0xFFF8) {

        av_log(s->avctx, AV_LOG_ERROR, "FRAME HEADER not here\n");

        while (get_bits_count(&s->gb)/8+2 < buf_size && (show_bits(&s->gb, 16) & 0xFFFE) != 0xFFF8)

            skip_bits(&s->gb, 8);

        goto end; // we may not have enough bits left to decode a frame, so try next time

    }

    skip_bits(&s->gb, 16);

    if (decode_frame(s, alloc_data_size) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "decode_frame() failed\n");

        s->bitstream_size=0;

        s->bitstream_index=0;

        return -1;

    }



#define DECORRELATE(left, right)\

            assert(s->channels == 2);\

            for (i = 0; i < s->blocksize; i++) {\

                int a= s->decoded[0][i];\

                int b= s->decoded[1][i];\

                if (s->is32) {\

                    *samples_32++ = (left)  << s->sample_shift;\

                    *samples_32++ = (right) << s->sample_shift;\

                } else {\

                    *samples_16++ = (left)  << s->sample_shift;\

                    *samples_16++ = (right) << s->sample_shift;\

                }\

            }\

            break;



    switch (s->decorrelation) {

    case INDEPENDENT:

        for (j = 0; j < s->blocksize; j++) {

            for (i = 0; i < s->channels; i++) {

                if (s->is32)

                    *samples_32++ = s->decoded[i][j] << s->sample_shift;

                else

                    *samples_16++ = s->decoded[i][j] << s->sample_shift;

            }

        }

        break;

    case LEFT_SIDE:

        DECORRELATE(a,a-b)

    case RIGHT_SIDE:

        DECORRELATE(a+b,b)

    case MID_SIDE:

        DECORRELATE( (a-=b>>1) + b, a)

    }



    *data_size = s->blocksize * s->channels * (s->is32 ? 4 : 2);



end:

    i= (get_bits_count(&s->gb)+7)/8;

    if (i > buf_size) {

        av_log(s->avctx, AV_LOG_ERROR, "overread: %d\n", i - buf_size);

        s->bitstream_size=0;

        s->bitstream_index=0;

        return -1;

    }



    if (s->bitstream_size) {

        s->bitstream_index += i;

        s->bitstream_size  -= i;

        return input_buf_size;

    } else

        return i;

}

static SocketAddress *nbd_config(BDRVNBDState *s, QDict *options, Error **errp)

{

    SocketAddress *saddr = NULL;

    QDict *addr = NULL;

    QObject *crumpled_addr = NULL;

    Visitor *iv = NULL;

    Error *local_err = NULL;



    qdict_extract_subqdict(options, &addr, "server.");

    if (!qdict_size(addr)) {

        error_setg(errp, "NBD server address missing");

        goto done;

    }



    crumpled_addr = qdict_crumple(addr, errp);

    if (!crumpled_addr) {

        goto done;

    }











    iv = qobject_input_visitor_new(crumpled_addr);

    visit_type_SocketAddress(iv, NULL, &saddr, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        goto done;

    }



done:

    QDECREF(addr);

    qobject_decref(crumpled_addr);

    visit_free(iv);

    return saddr;

}

