static int gif_video_probe(AVProbeData * pd)

{

    const uint8_t *p, *p_end;

    int bits_per_pixel, has_global_palette, ext_code, ext_len;

    int gce_flags, gce_disposal;



    if (pd->buf_size < 24 ||

        memcmp(pd->buf, gif89a_sig, 6) != 0)

        return 0;

    p_end = pd->buf + pd->buf_size;

    p = pd->buf + 6;

    bits_per_pixel = (p[4] & 0x07) + 1;

    has_global_palette = (p[4] & 0x80);

    p += 7;

    if (has_global_palette)

        p += (1 << bits_per_pixel) * 3;

    for(;;) {

        if (p >= p_end)

            return 0;

        if (*p != '!')

            break;

        p++;

        if (p >= p_end)

            return 0;

        ext_code = *p++;

        if (p >= p_end)

            return 0;

        ext_len = *p++;

        if (ext_code == 0xf9) {

            if (p >= p_end)

                return 0;

            /* if GCE extension found with gce_disposal != 0: it is

               likely to be an animation */

            gce_flags = *p++;

            gce_disposal = (gce_flags >> 2) & 0x7;

            if (gce_disposal != 0)

                return AVPROBE_SCORE_MAX;

            else

                return 0;

        }

        for(;;) {

            if (ext_len == 0)

                break;

            p += ext_len;

            if (p >= p_end)

                return 0;

            ext_len = *p++;

        }

    }

    return 0;

}

static int parse_header(OutputStream *os, const uint8_t *buf, int buf_size)

{

    if (buf_size < 13)

        return AVERROR_INVALIDDATA;

    if (memcmp(buf, "FLV", 3))

        return AVERROR_INVALIDDATA;

    buf      += 13;

    buf_size -= 13;

    while (buf_size >= 11 + 4) {

        int type = buf[0];

        int size = AV_RB24(&buf[1]) + 11 + 4;

        if (size > buf_size)

            return AVERROR_INVALIDDATA;

        if (type == 8 || type == 9) {

            if (os->nb_extra_packets > FF_ARRAY_ELEMS(os->extra_packets))

                return AVERROR_INVALIDDATA;

            os->extra_packet_sizes[os->nb_extra_packets] = size;

            os->extra_packets[os->nb_extra_packets] = av_malloc(size);

            if (!os->extra_packets[os->nb_extra_packets])

                return AVERROR(ENOMEM);

            memcpy(os->extra_packets[os->nb_extra_packets], buf, size);

            os->nb_extra_packets++;

        } else if (type == 0x12) {

            if (os->metadata)

                return AVERROR_INVALIDDATA;

            os->metadata_size = size - 11 - 4;

            os->metadata      = av_malloc(os->metadata_size);

            if (!os->metadata)

                return AVERROR(ENOMEM);

            memcpy(os->metadata, buf + 11, os->metadata_size);

        }

        buf      += size;

        buf_size -= size;

    }

    if (!os->metadata)

        return AVERROR_INVALIDDATA;

    return 0;

}

static void dhcp_decode(const struct bootp_t *bp, int *pmsg_type,

                        const struct in_addr **preq_addr)

{

    const uint8_t *p, *p_end;

    int len, tag;



    *pmsg_type = 0;

    *preq_addr = NULL;



    p = bp->bp_vend;

    p_end = p + DHCP_OPT_LEN;

    if (memcmp(p, rfc1533_cookie, 4) != 0)

        return;

    p += 4;

    while (p < p_end) {

        tag = p[0];

        if (tag == RFC1533_PAD) {

            p++;

        } else if (tag == RFC1533_END) {

            break;

        } else {

            p++;

            if (p >= p_end)

                break;

            len = *p++;

            DPRINTF("dhcp: tag=%d len=%d\n", tag, len);



            switch(tag) {

            case RFC2132_MSG_TYPE:

                if (len >= 1)

                    *pmsg_type = p[0];

                break;

            case RFC2132_REQ_ADDR:

                if (len >= 4)

                    *preq_addr = (struct in_addr *)p;

                break;

            default:

                break;

            }

            p += len;

        }

    }

    if (*pmsg_type == DHCPREQUEST && !*preq_addr && bp->bp_ciaddr.s_addr) {

        *preq_addr = &bp->bp_ciaddr;

    }

}

static uint64_t pic_read(void *opaque, target_phys_addr_t addr,

                         unsigned size)

{

    HeathrowPICS *s = opaque;

    HeathrowPIC *pic;

    unsigned int n;

    uint32_t value;



    n = ((addr & 0xfff) - 0x10) >> 4;

    if (n >= 2) {

        value = 0;

    } else {

        pic = &s->pics[n];

        switch(addr & 0xf) {

        case 0x0:

            value = pic->events;

            break;

        case 0x4:

            value = pic->mask;

            break;

        case 0xc:

            value = pic->levels;

            break;

        default:

            value = 0;

            break;

        }

    }

    PIC_DPRINTF("readl: " TARGET_FMT_plx " %u: %08x\n", addr, n, value);

    return value;

}

static int xhci_fire_ctl_transfer(XHCIState *xhci, XHCITransfer *xfer)

{

    XHCITRB *trb_setup, *trb_status;

    uint8_t bmRequestType, bRequest;

    uint16_t wValue, wLength, wIndex;

    XHCIPort *port;

    USBDevice *dev;

    int ret;



    DPRINTF("xhci_fire_ctl_transfer(slot=%d)\n", xfer->slotid);



    trb_setup = &xfer->trbs[0];

    trb_status = &xfer->trbs[xfer->trb_count-1];



    /* at most one Event Data TRB allowed after STATUS */

    if (TRB_TYPE(*trb_status) == TR_EVDATA && xfer->trb_count > 2) {

        trb_status--;

    }



    /* do some sanity checks */

    if (TRB_TYPE(*trb_setup) != TR_SETUP) {

        fprintf(stderr, "xhci: ep0 first TD not SETUP: %d\n",

                TRB_TYPE(*trb_setup));

        return -1;

    }

    if (TRB_TYPE(*trb_status) != TR_STATUS) {

        fprintf(stderr, "xhci: ep0 last TD not STATUS: %d\n",

                TRB_TYPE(*trb_status));

        return -1;

    }

    if (!(trb_setup->control & TRB_TR_IDT)) {

        fprintf(stderr, "xhci: Setup TRB doesn't have IDT set\n");

        return -1;

    }

    if ((trb_setup->status & 0x1ffff) != 8) {

        fprintf(stderr, "xhci: Setup TRB has bad length (%d)\n",

                (trb_setup->status & 0x1ffff));

        return -1;

    }



    bmRequestType = trb_setup->parameter;

    bRequest = trb_setup->parameter >> 8;

    wValue = trb_setup->parameter >> 16;

    wIndex = trb_setup->parameter >> 32;

    wLength = trb_setup->parameter >> 48;



    if (xfer->data && xfer->data_alloced < wLength) {

        xfer->data_alloced = 0;

        g_free(xfer->data);

        xfer->data = NULL;

    }

    if (!xfer->data) {

        DPRINTF("xhci: alloc %d bytes data\n", wLength);

        xfer->data = g_malloc(wLength+1);

        xfer->data_alloced = wLength;

    }

    xfer->data_length = wLength;



    port = &xhci->ports[xhci->slots[xfer->slotid-1].port-1];

    dev = xhci_find_device(port, xhci->slots[xfer->slotid-1].devaddr);

    if (!dev) {

        fprintf(stderr, "xhci: slot %d port %d has no device\n", xfer->slotid,

                xhci->slots[xfer->slotid-1].port);

        return -1;

    }



    xfer->in_xfer = bmRequestType & USB_DIR_IN;

    xfer->iso_xfer = false;



    xhci_setup_packet(xfer, dev);

    if (!xfer->in_xfer) {

        xhci_xfer_data(xfer, xfer->data, wLength, 0, 1, 0);

    }

    ret = usb_device_handle_control(dev, &xfer->packet,

                                    (bmRequestType << 8) | bRequest,

                                    wValue, wIndex, wLength, xfer->data);



    xhci_complete_packet(xfer, ret);

    if (!xfer->running_async && !xfer->running_retry) {

        xhci_kick_ep(xhci, xfer->slotid, xfer->epid);

    }

    return 0;

}

static int xhci_submit(XHCIState *xhci, XHCITransfer *xfer, XHCIEPContext *epctx)

{

    uint64_t mfindex;



    DPRINTF("xhci_submit(slotid=%d,epid=%d)\n", xfer->slotid, xfer->epid);



    xfer->in_xfer = epctx->type>>2;



    switch(epctx->type) {

    case ET_INTR_OUT:

    case ET_INTR_IN:

    case ET_BULK_OUT:

    case ET_BULK_IN:

        xfer->pkts = 0;

        xfer->iso_xfer = false;

        break;

    case ET_ISO_OUT:

    case ET_ISO_IN:

        xfer->pkts = 1;

        xfer->iso_xfer = true;

        mfindex = xhci_mfindex_get(xhci);

        xhci_calc_iso_kick(xhci, xfer, epctx, mfindex);

        xhci_check_iso_kick(xhci, xfer, epctx, mfindex);

        if (xfer->running_retry) {

            return -1;

        }

        break;

    default:

        fprintf(stderr, "xhci: unknown or unhandled EP "

                "(type %d, in %d, ep %02x)\n",

                epctx->type, xfer->in_xfer, xfer->epid);

        return -1;

    }



    if (xhci_setup_packet(xfer) < 0) {

        return -1;

    }

    usb_handle_packet(xfer->packet.ep->dev, &xfer->packet);



    xhci_complete_packet(xfer);

    if (!xfer->running_async && !xfer->running_retry) {

        xhci_kick_ep(xhci, xfer->slotid, xfer->epid, xfer->streamid);

    }

    return 0;

}

static int xhci_submit(XHCIState *xhci, XHCITransfer *xfer, XHCIEPContext *epctx)

{

    uint64_t mfindex;



    DPRINTF("xhci_submit(slotid=%d,epid=%d)\n", xfer->slotid, xfer->epid);



    xfer->in_xfer = epctx->type>>2;



    switch(epctx->type) {

    case ET_INTR_OUT:

    case ET_INTR_IN:

        xfer->pkts = 0;

        xfer->iso_xfer = false;

        xfer->timed_xfer = true;

        mfindex = xhci_mfindex_get(xhci);

        xhci_calc_intr_kick(xhci, xfer, epctx, mfindex);

        xhci_check_intr_iso_kick(xhci, xfer, epctx, mfindex);

        if (xfer->running_retry) {

            return -1;

        }

        break;

    case ET_BULK_OUT:

    case ET_BULK_IN:

        xfer->pkts = 0;

        xfer->iso_xfer = false;

        xfer->timed_xfer = false;

        break;

    case ET_ISO_OUT:

    case ET_ISO_IN:

        xfer->pkts = 1;

        xfer->iso_xfer = true;

        xfer->timed_xfer = true;

        mfindex = xhci_mfindex_get(xhci);

        xhci_calc_iso_kick(xhci, xfer, epctx, mfindex);

        xhci_check_intr_iso_kick(xhci, xfer, epctx, mfindex);

        if (xfer->running_retry) {

            return -1;

        }

        break;

    default:

        trace_usb_xhci_unimplemented("endpoint type", epctx->type);

        return -1;

    }



    if (xhci_setup_packet(xfer) < 0) {

        return -1;

    }

    usb_handle_packet(xfer->packet.ep->dev, &xfer->packet);



    xhci_try_complete_packet(xfer);

    if (!xfer->running_async && !xfer->running_retry) {

        xhci_kick_epctx(xfer->epctx, xfer->streamid);

    }

    return 0;

}

static int xhci_ep_nuke_xfers(XHCIState *xhci, unsigned int slotid,

                               unsigned int epid, TRBCCode report)

{

    XHCISlot *slot;

    XHCIEPContext *epctx;

    int i, xferi, killed = 0;

    USBEndpoint *ep = NULL;

    assert(slotid >= 1 && slotid <= xhci->numslots);

    assert(epid >= 1 && epid <= 31);



    DPRINTF("xhci_ep_nuke_xfers(%d, %d)\n", slotid, epid);



    slot = &xhci->slots[slotid-1];



    if (!slot->eps[epid-1]) {

        return 0;

    }



    epctx = slot->eps[epid-1];



    xferi = epctx->next_xfer;

    for (i = 0; i < TD_QUEUE; i++) {

        killed += xhci_ep_nuke_one_xfer(&epctx->transfers[xferi], report);

        if (killed) {

            report = 0; /* Only report once */

        }

        epctx->transfers[xferi].packet.ep = NULL;

        xferi = (xferi + 1) % TD_QUEUE;

    }



    ep = xhci_epid_to_usbep(xhci, slotid, epid);

    if (ep) {

        usb_device_ep_stopped(ep->dev, ep);

    }

    return killed;

}

