static int vt82c686b_pm_initfn(PCIDevice *dev)

{

    VT686PMState *s = DO_UPCAST(VT686PMState, dev, dev);

    uint8_t *pci_conf;



    pci_conf = s->dev.config;

    pci_config_set_vendor_id(pci_conf, PCI_VENDOR_ID_VIA);

    pci_config_set_device_id(pci_conf, PCI_DEVICE_ID_VIA_ACPI);

    pci_config_set_class(pci_conf, PCI_CLASS_BRIDGE_OTHER);

    pci_config_set_revision(pci_conf, 0x40);



    pci_set_word(pci_conf + PCI_COMMAND, 0);

    pci_set_word(pci_conf + PCI_STATUS, PCI_STATUS_FAST_BACK |

                 PCI_STATUS_DEVSEL_MEDIUM);



    /* 0x48-0x4B is Power Management I/O Base */

    pci_set_long(pci_conf + 0x48, 0x00000001);



    /* SMB ports:0xeee0~0xeeef */

    s->smb_io_base =((s->smb_io_base & 0xfff0) + 0x0);

    pci_conf[0x90] = s->smb_io_base | 1;

    pci_conf[0x91] = s->smb_io_base >> 8;

    pci_conf[0xd2] = 0x90;

    register_ioport_write(s->smb_io_base, 0xf, 1, smb_ioport_writeb, &s->smb);

    register_ioport_read(s->smb_io_base, 0xf, 1, smb_ioport_readb, &s->smb);



    apm_init(&s->apm, NULL, s);



    acpi_pm_tmr_init(&s->tmr, pm_tmr_timer);

    acpi_pm1_cnt_init(&s->pm1_cnt, NULL);



    pm_smbus_init(&s->dev.qdev, &s->smb);



    return 0;

}

static inline int gen_iwmmxt_address(DisasContext *s, uint32_t insn, TCGv dest)

{

    int rd;

    uint32_t offset;

    TCGv tmp;



    rd = (insn >> 16) & 0xf;

    tmp = load_reg(s, rd);



    offset = (insn & 0xff) << ((insn >> 7) & 2);

    if (insn & (1 << 24)) {

        /* Pre indexed */

        if (insn & (1 << 23))

            tcg_gen_addi_i32(tmp, tmp, offset);

        else

            tcg_gen_addi_i32(tmp, tmp, -offset);

        tcg_gen_mov_i32(dest, tmp);

        if (insn & (1 << 21))

            store_reg(s, rd, tmp);

        else

            dead_tmp(tmp);

    } else if (insn & (1 << 21)) {

        /* Post indexed */

        tcg_gen_mov_i32(dest, tmp);

        if (insn & (1 << 23))

            tcg_gen_addi_i32(tmp, tmp, offset);

        else

            tcg_gen_addi_i32(tmp, tmp, -offset);

        store_reg(s, rd, tmp);

    } else if (!(insn & (1 << 23)))

        return 1;

    return 0;

}

static void shifter_out_im(TCGv var, int shift)

{

    TCGv tmp = new_tmp();

    if (shift == 0) {

        tcg_gen_andi_i32(tmp, var, 1);

    } else {

        tcg_gen_shri_i32(tmp, var, shift);

        if (shift != 31)

            tcg_gen_andi_i32(tmp, tmp, 1);

    }

    gen_set_CF(tmp);

    dead_tmp(tmp);

}

static int disas_cp_insn(CPUState *env, DisasContext *s, uint32_t insn)

{

    TCGv tmp, tmp2;

    uint32_t rd = (insn >> 12) & 0xf;

    uint32_t cp = (insn >> 8) & 0xf;

    if (IS_USER(s)) {

        return 1;

    }



    if (insn & ARM_CP_RW_BIT) {

        if (!env->cp[cp].cp_read)

            return 1;

        gen_set_pc_im(s->pc);

        tmp = new_tmp();

        tmp2 = tcg_const_i32(insn);

        gen_helper_get_cp(tmp, cpu_env, tmp2);

        tcg_temp_free(tmp2);

        store_reg(s, rd, tmp);

    } else {

        if (!env->cp[cp].cp_write)

            return 1;

        gen_set_pc_im(s->pc);

        tmp = load_reg(s, rd);

        tmp2 = tcg_const_i32(insn);

        gen_helper_set_cp(cpu_env, tmp2, tmp);

        tcg_temp_free(tmp2);

        dead_tmp(tmp);

    }

    return 0;

}

static void gen_neon_dup_u8(TCGv var, int shift)

{

    TCGv tmp = new_tmp();

    if (shift)

        tcg_gen_shri_i32(var, var, shift);

    tcg_gen_ext8u_i32(var, var);

    tcg_gen_shli_i32(tmp, var, 8);

    tcg_gen_or_i32(var, var, tmp);

    tcg_gen_shli_i32(tmp, var, 16);

    tcg_gen_or_i32(var, var, tmp);

    dead_tmp(tmp);

}

