    g_assert(!eof);

    QDECREF(ret);

    g_free(cmd);



    /* partial read */

    cmd = g_strdup_printf("{'execute': 'guest-file-read',"

                          " 'arguments': { 'handle': %" PRId64 "} }",

                          id);

    ret = qmp_fd(fixture->fd, cmd);

    val = qdict_get_qdict(ret, "return");

    count = qdict_get_int(val, "count");

    eof = qdict_get_bool(val, "eof");

    b64 = qdict_get_str(val, "buf-b64");

    g_assert_cmpint(count, ==, sizeof(helloworld) - 6);

    g_assert(eof);

    dec = g_base64_decode(b64, &count);

    g_assert_cmpint(count, ==, sizeof(helloworld) - 6);

    g_assert_cmpmem(dec, count, helloworld + 6, sizeof(helloworld) - 6);

    g_free(dec);



    QDECREF(ret);

    g_free(cmd);



    /* close */

    cmd = g_strdup_printf("{'execute': 'guest-file-close',"

                          " 'arguments': {'handle': %" PRId64 "} }",

                          id);

    ret = qmp_fd(fixture->fd, cmd);

    QDECREF(ret);

    g_free(cmd);

}

static void test_qga_guest_exec(gconstpointer fix)

{

    const TestFixture *fixture = fix;

    QDict *ret, *val;

    const gchar *out;

    guchar *decoded;

    int64_t pid, now, exitcode;

    gsize len;

    bool exited;



    /* exec 'echo foo bar' */

    ret = qmp_fd(fixture->fd, "{'execute': 'guest-exec', 'arguments': {"

                 " 'path': '/bin/echo', 'arg': [ '-n', '\" test_str \"' ],"

                 " 'capture-output': true } }");

    g_assert_nonnull(ret);

    qmp_assert_no_error(ret);

    val = qdict_get_qdict(ret, "return");

    pid = qdict_get_int(val, "pid");

    g_assert_cmpint(pid, >, 0);

    QDECREF(ret);



    /* wait for completion */

    now = g_get_monotonic_time();

    do {

        ret = qmp_fd(fixture->fd, "{'execute': 'guest-exec-status',"

                     " 'arguments': { 'pid': %" PRId64 "  } }", pid);

        g_assert_nonnull(ret);

        val = qdict_get_qdict(ret, "return");

        exited = qdict_get_bool(val, "exited");

        if (!exited) {

            QDECREF(ret);

        }

    } while (!exited &&

             g_get_monotonic_time() < now + 5 * G_TIME_SPAN_SECOND);

    g_assert(exited);



    /* check stdout */

    exitcode = qdict_get_int(val, "exitcode");

    g_assert_cmpint(exitcode, ==, 0);

    out = qdict_get_str(val, "out-data");

    decoded = g_base64_decode(out, &len);

    g_assert_cmpint(len, ==, 12);

    g_assert_cmpstr((char *)decoded, ==, "\" test_str \"");

    g_free(decoded);

    QDECREF(ret);

}

