static inline int get_ue_code(GetBitContext *gb, int order)

{

    if (order) {

        int ret = get_ue_golomb(gb) << order;

        return ret + get_bits(gb, order);

    }

    return get_ue_golomb(gb);

}

static unsigned int codec_get_asf_tag(const CodecTag *tags, unsigned int id)

{

    while (tags->id != 0) {

        if (!tags->invalid_asf && tags->id == id)

            return tags->tag;

        tags++;

    }

    return 0;

}

static inline int memory_access_size(MemoryRegion *mr, int l, hwaddr addr)

{

    if (l >= 4 && (((addr & 3) == 0 || mr->ops->impl.unaligned))) {

        return 4;

    }

    if (l >= 2 && (((addr & 1) == 0) || mr->ops->impl.unaligned)) {

        return 2;

    }

    return 1;

}

static void apply_independent_coupling_fixed(AACContext *ac,

                                       SingleChannelElement *target,

                                       ChannelElement *cce, int index)

{

    int i, c, shift, round, tmp;

    const int gain = cce->coup.gain[index][0];

    const int *src = cce->ch[0].ret;

    int *dest = target->ret;

    const int len = 1024 << (ac->oc[1].m4ac.sbr == 1);



    c = cce_scale_fixed[gain & 7];

    shift = (gain-1024) >> 3;

    if (shift < 0) {

        shift = -shift;

        round = 1 << (shift - 1);



        for (i = 0; i < len; i++) {

            tmp = (int)(((int64_t)src[i] * c + (int64_t)0x1000000000) >> 37);

            dest[i] += (tmp + round) >> shift;

        }

    }

    else {

      for (i = 0; i < len; i++) {

          tmp = (int)(((int64_t)src[i] * c + (int64_t)0x1000000000) >> 37);

          dest[i] += tmp << shift;

      }

    }

}

static inline void yuv2rgbXinC(int16_t *lumFilter, int16_t **lumSrc, int lumFilterSize,

				    int16_t *chrFilter, int16_t **chrSrc, int chrFilterSize,

				    uint8_t *dest, int dstW, int dstbpp)

{

	if(dstbpp==32)

	{

		int i;

		for(i=0; i<(dstW>>1); i++){

			int j;

			int Y1=0;

			int Y2=0;

			int U=0;

			int V=0;

			int Cb, Cr, Cg;

			for(j=0; j<lumFilterSize; j++)

			{

				Y1 += lumSrc[j][2*i] * lumFilter[j];

				Y2 += lumSrc[j][2*i+1] * lumFilter[j];

			}

			for(j=0; j<chrFilterSize; j++)

			{

				U += chrSrc[j][i] * chrFilter[j];

				V += chrSrc[j][i+2048] * chrFilter[j];

			}

			Y1= clip_yuvtab_2568[ (Y1>>19) + 256 ];

			Y2= clip_yuvtab_2568[ (Y2>>19) + 256 ];

			U >>= 19;

			V >>= 19;



			Cb= clip_yuvtab_40cf[U+ 256];

			Cg= clip_yuvtab_1a1e[V+ 256] + yuvtab_0c92[U+ 256];

			Cr= clip_yuvtab_3343[V+ 256];



			dest[8*i+0]=clip_table[((Y1 + Cb) >>13)];

			dest[8*i+1]=clip_table[((Y1 + Cg) >>13)];

			dest[8*i+2]=clip_table[((Y1 + Cr) >>13)];



			dest[8*i+4]=clip_table[((Y2 + Cb) >>13)];

			dest[8*i+5]=clip_table[((Y2 + Cg) >>13)];

			dest[8*i+6]=clip_table[((Y2 + Cr) >>13)];

		}

	}

	else if(dstbpp==24)

	{

		int i;

		for(i=0; i<(dstW>>1); i++){

			int j;

			int Y1=0;

			int Y2=0;

			int U=0;

			int V=0;

			int Cb, Cr, Cg;

			for(j=0; j<lumFilterSize; j++)

			{

				Y1 += lumSrc[j][2*i] * lumFilter[j];

				Y2 += lumSrc[j][2*i+1] * lumFilter[j];

			}

			for(j=0; j<chrFilterSize; j++)

			{

				U += chrSrc[j][i] * chrFilter[j];

				V += chrSrc[j][i+2048] * chrFilter[j];

			}

			Y1= clip_yuvtab_2568[ (Y1>>19) + 256 ];

			Y2= clip_yuvtab_2568[ (Y2>>19) + 256 ];

			U >>= 19;

			V >>= 19;



			Cb= clip_yuvtab_40cf[U+ 256];

			Cg= clip_yuvtab_1a1e[V+ 256] + yuvtab_0c92[U+ 256];

			Cr= clip_yuvtab_3343[V+ 256];



			dest[0]=clip_table[((Y1 + Cb) >>13)];

			dest[1]=clip_table[((Y1 + Cg) >>13)];

			dest[2]=clip_table[((Y1 + Cr) >>13)];



			dest[3]=clip_table[((Y2 + Cb) >>13)];

			dest[4]=clip_table[((Y2 + Cg) >>13)];

			dest[5]=clip_table[((Y2 + Cr) >>13)];

			dest+=6;

		}

	}

	else if(dstbpp==16)

	{

		int i;

		for(i=0; i<(dstW>>1); i++){

			int j;

			int Y1=0;

			int Y2=0;

			int U=0;

			int V=0;

			int Cb, Cr, Cg;

			for(j=0; j<lumFilterSize; j++)

			{

				Y1 += lumSrc[j][2*i] * lumFilter[j];

				Y2 += lumSrc[j][2*i+1] * lumFilter[j];

			}

			for(j=0; j<chrFilterSize; j++)

			{

				U += chrSrc[j][i] * chrFilter[j];

				V += chrSrc[j][i+2048] * chrFilter[j];

			}

			Y1= clip_yuvtab_2568[ (Y1>>19) + 256 ];

			Y2= clip_yuvtab_2568[ (Y2>>19) + 256 ];

			U >>= 19;

			V >>= 19;



			Cb= clip_yuvtab_40cf[U+ 256];

			Cg= clip_yuvtab_1a1e[V+ 256] + yuvtab_0c92[U+ 256];

			Cr= clip_yuvtab_3343[V+ 256];



			((uint16_t*)dest)[2*i] =

				clip_table16b[(Y1 + Cb) >>13] |

				clip_table16g[(Y1 + Cg) >>13] |

				clip_table16r[(Y1 + Cr) >>13];



			((uint16_t*)dest)[2*i+1] =

				clip_table16b[(Y2 + Cb) >>13] |

				clip_table16g[(Y2 + Cg) >>13] |

				clip_table16r[(Y2 + Cr) >>13];

		}

	}

	else if(dstbpp==15)

	{

		int i;

		for(i=0; i<(dstW>>1); i++){

			int j;

			int Y1=0;

			int Y2=0;

			int U=0;

			int V=0;

			int Cb, Cr, Cg;

			for(j=0; j<lumFilterSize; j++)

			{

				Y1 += lumSrc[j][2*i] * lumFilter[j];

				Y2 += lumSrc[j][2*i+1] * lumFilter[j];

			}

			for(j=0; j<chrFilterSize; j++)

			{

				U += chrSrc[j][i] * chrFilter[j];

				V += chrSrc[j][i+2048] * chrFilter[j];

			}

			Y1= clip_yuvtab_2568[ (Y1>>19) + 256 ];

			Y2= clip_yuvtab_2568[ (Y2>>19) + 256 ];

			U >>= 19;

			V >>= 19;



			Cb= clip_yuvtab_40cf[U+ 256];

			Cg= clip_yuvtab_1a1e[V+ 256] + yuvtab_0c92[U+ 256];

			Cr= clip_yuvtab_3343[V+ 256];



			((uint16_t*)dest)[2*i] =

				clip_table15b[(Y1 + Cb) >>13] |

				clip_table15g[(Y1 + Cg) >>13] |

				clip_table15r[(Y1 + Cr) >>13];



			((uint16_t*)dest)[2*i+1] =

				clip_table15b[(Y2 + Cb) >>13] |

				clip_table15g[(Y2 + Cg) >>13] |

				clip_table15r[(Y2 + Cr) >>13];

		}

	}

}

static void xan_unpack(unsigned char *dest, unsigned char *src)

{

    unsigned char opcode;

    int size;

    int offset;

    int byte1, byte2, byte3;



    for (;;) {

        opcode = *src++;



        if ( (opcode & 0x80) == 0 ) {



            offset = *src++;



            size = opcode & 3;

            bytecopy(dest, src, size);  dest += size;  src += size;



            size = ((opcode & 0x1c) >> 2) + 3;

            bytecopy (dest, dest - (((opcode & 0x60) << 3) + offset + 1), size);

            dest += size;



        } else if ( (opcode & 0x40) == 0 ) {



            byte1 = *src++;

            byte2 = *src++;



            size = byte1 >> 6;

            bytecopy (dest, src, size);  dest += size;  src += size;



            size = (opcode & 0x3f) + 4;

            bytecopy (dest, dest - (((byte1 & 0x3f) << 8) + byte2 + 1), size);

            dest += size;



        } else if ( (opcode & 0x20) == 0 ) {



            byte1 = *src++;

            byte2 = *src++;

            byte3 = *src++;



            size = opcode & 3;

            bytecopy (dest, src, size);  dest += size;  src += size;



            size = byte3 + 5 + ((opcode & 0xc) << 6);

            bytecopy (dest,

                dest - ((((opcode & 0x10) >> 4) << 0x10) + 1 + (byte1 << 8) + byte2),

                size);

            dest += size;

        } else {

            size = ((opcode & 0x1f) << 2) + 4;



            if (size > 0x70)

                break;



            bytecopy (dest, src, size);  dest += size;  src += size;

        }

    }



    size = opcode & 3;

    bytecopy(dest, src, size);  dest += size;  src += size;

}

void ff_svq3_add_idct_c(uint8_t *dst, DCTELEM *block, int stride, int qp,

                            int dc)

{

    const int qmul = svq3_dequant_coeff[qp];

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    if (dc) {

        dc = 13*13*((dc == 1) ? 1538*block[0] : ((qmul*(block[0] >> 3)) / 2));

        block[0] = 0;

    }



    for (i = 0; i < 4; i++) {

        const int z0 = 13*(block[0 + 4*i] +    block[2 + 4*i]);

        const int z1 = 13*(block[0 + 4*i] -    block[2 + 4*i]);

        const int z2 =  7* block[1 + 4*i] - 17*block[3 + 4*i];

        const int z3 = 17* block[1 + 4*i] +  7*block[3 + 4*i];



        block[0 + 4*i] = z0 + z3;

        block[1 + 4*i] = z1 + z2;

        block[2 + 4*i] = z1 - z2;

        block[3 + 4*i] = z0 - z3;

    }



    for (i = 0; i < 4; i++) {

        const int z0 = 13*(block[i + 4*0] +    block[i + 4*2]);

        const int z1 = 13*(block[i + 4*0] -    block[i + 4*2]);

        const int z2 =  7* block[i + 4*1] - 17*block[i + 4*3];

        const int z3 = 17* block[i + 4*1] +  7*block[i + 4*3];

        const int rr = (dc + 0x80000);



        dst[i + stride*0] = cm[ dst[i + stride*0] + (((z0 + z3)*qmul + rr) >> 20) ];

        dst[i + stride*1] = cm[ dst[i + stride*1] + (((z1 + z2)*qmul + rr) >> 20) ];

        dst[i + stride*2] = cm[ dst[i + stride*2] + (((z1 - z2)*qmul + rr) >> 20) ];

        dst[i + stride*3] = cm[ dst[i + stride*3] + (((z0 - z3)*qmul + rr) >> 20) ];

    }

}

