static int svq3_decode_slice_header(AVCodecContext *avctx)

{

    SVQ3Context *svq3 = avctx->priv_data;

    H264Context *h    = &svq3->h;

    MpegEncContext *s = &h->s;

    const int mb_xy   = h->mb_xy;

    int i, header;



    header = get_bits(&s->gb, 8);



    if (((header & 0x9F) != 1 && (header & 0x9F) != 2) || (header & 0x60) == 0) {

        /* TODO: what? */

        av_log(avctx, AV_LOG_ERROR, "unsupported slice header (%02X)\n", header);

        return -1;

    } else {

        int length = header >> 5 & 3;



        svq3->next_slice_index = get_bits_count(&s->gb) +

                                 8 * show_bits(&s->gb, 8 * length) +

                                 8 * length;



        if (svq3->next_slice_index > s->gb.size_in_bits) {

            av_log(avctx, AV_LOG_ERROR, "slice after bitstream end\n");

            return -1;

        }



        s->gb.size_in_bits = svq3->next_slice_index - 8 * (length - 1);

        skip_bits(&s->gb, 8);



        if (svq3->watermark_key) {

            uint32_t header = AV_RL32(&s->gb.buffer[(get_bits_count(&s->gb) >> 3) + 1]);

            AV_WL32(&s->gb.buffer[(get_bits_count(&s->gb) >> 3) + 1],

                    header ^ svq3->watermark_key);

        }

        if (length > 0) {

            memcpy((uint8_t *) &s->gb.buffer[get_bits_count(&s->gb) >> 3],

                   &s->gb.buffer[s->gb.size_in_bits >> 3], length - 1);

        }

        skip_bits_long(&s->gb, 0);

    }



    if ((i = svq3_get_ue_golomb(&s->gb)) == INVALID_VLC || i >= 3) {

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal slice type %d \n", i);

        return -1;

    }



    h->slice_type = golomb_to_pict_type[i];



    if ((header & 0x9F) == 2) {

        i              = (s->mb_num < 64) ? 6 : (1 + av_log2(s->mb_num - 1));

        s->mb_skip_run = get_bits(&s->gb, i) -

                         (s->mb_y * s->mb_width + s->mb_x);

    } else {

        skip_bits1(&s->gb);

        s->mb_skip_run = 0;

    }



    h->slice_num      = get_bits(&s->gb, 8);

    s->qscale         = get_bits(&s->gb, 5);

    s->adaptive_quant = get_bits1(&s->gb);



    /* unknown fields */

    skip_bits1(&s->gb);



    if (svq3->unknown_flag)

        skip_bits1(&s->gb);



    skip_bits1(&s->gb);

    skip_bits(&s->gb, 2);



    while (get_bits1(&s->gb))

        skip_bits(&s->gb, 8);



    /* reset intra predictors and invalidate motion vector references */

    if (s->mb_x > 0) {

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy - 1] + 3,

               -1, 4 * sizeof(int8_t));

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy - s->mb_x],

               -1, 8 * sizeof(int8_t) * s->mb_x);

    }

    if (s->mb_y > 0) {

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy - s->mb_stride],

               -1, 8 * sizeof(int8_t) * (s->mb_width - s->mb_x));



        if (s->mb_x > 0)

            h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - s->mb_stride - 1] + 3] = -1;

    }



    return 0;

}

static int svq1_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

  const uint8_t *buf = avpkt->data;

  int buf_size = avpkt->size;

  MpegEncContext *s=avctx->priv_data;

  uint8_t        *current, *previous;

  int             result, i, x, y, width, height;

  AVFrame *pict = data;

  svq1_pmv *pmv;



  /* initialize bit buffer */

  init_get_bits(&s->gb,buf,buf_size*8);



  /* decode frame header */

  s->f_code = get_bits (&s->gb, 22);



  if ((s->f_code & ~0x70) || !(s->f_code & 0x60))

    return -1;



  /* swap some header bytes (why?) */

  if (s->f_code != 0x20) {

    uint32_t *src = (uint32_t *) (buf + 4);



    for (i=0; i < 4; i++) {

      src[i] = ((src[i] << 16) | (src[i] >> 16)) ^ src[7 - i];

    }

  }



  result = svq1_decode_frame_header (&s->gb, s);



  if (result != 0)

  {

    av_dlog(s->avctx, "Error in svq1_decode_frame_header %i\n",result);

    return result;

  }




  //FIXME this avoids some confusion for "B frames" without 2 references

  //this should be removed after libavcodec can handle more flexible picture types & ordering

  if(s->pict_type==AV_PICTURE_TYPE_B && s->last_picture_ptr==NULL) return buf_size;



  if(  (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type==AV_PICTURE_TYPE_B)

     ||(avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type!=AV_PICTURE_TYPE_I)

     || avctx->skip_frame >= AVDISCARD_ALL)

      return buf_size;



  if(MPV_frame_start(s, avctx) < 0)

      return -1;



  pmv = av_malloc((FFALIGN(s->width, 16)/8 + 3) * sizeof(*pmv));

  if (!pmv)

      return -1;



  /* decode y, u and v components */

  for (i=0; i < 3; i++) {

    int linesize;

    if (i == 0) {

      width  = FFALIGN(s->width, 16);

      height = FFALIGN(s->height, 16);

      linesize= s->linesize;

    } else {

      if(s->flags&CODEC_FLAG_GRAY) break;

      width  = FFALIGN(s->width/4, 16);

      height = FFALIGN(s->height/4, 16);

      linesize= s->uvlinesize;

    }



    current = s->current_picture.f.data[i];



    if(s->pict_type==AV_PICTURE_TYPE_B){

        previous = s->next_picture.f.data[i];

    }else{

        previous = s->last_picture.f.data[i];

    }



    if (s->pict_type == AV_PICTURE_TYPE_I) {

      /* keyframe */

      for (y=0; y < height; y+=16) {

        for (x=0; x < width; x+=16) {

          result = svq1_decode_block_intra (&s->gb, &current[x], linesize);

          if (result != 0)

          {

            av_log(s->avctx, AV_LOG_INFO, "Error in svq1_decode_block %i (keyframe)\n",result);

            goto err;

          }

        }

        current += 16*linesize;

      }

    } else {

      /* delta frame */

      memset (pmv, 0, ((width / 8) + 3) * sizeof(svq1_pmv));



      for (y=0; y < height; y+=16) {

        for (x=0; x < width; x+=16) {

          result = svq1_decode_delta_block (s, &s->gb, &current[x], previous,

                                            linesize, pmv, x, y);

          if (result != 0)

          {

            av_dlog(s->avctx, "Error in svq1_decode_delta_block %i\n",result);

            goto err;

          }

        }



        pmv[0].x =

        pmv[0].y = 0;



        current += 16*linesize;

      }

    }

  }



  *pict = *(AVFrame*)&s->current_picture;





  MPV_frame_end(s);



  *data_size=sizeof(AVFrame);

  result = buf_size;

err:

  av_free(pmv);

  return result;

}

static int decode_frame_header (bit_buffer_t *bitbuf,MpegEncContext *s) {

  int frame_size_code;



  /* unknown field */

  get_bits (bitbuf, 8);



  /* frame type */

  s->pict_type = get_bits (bitbuf, 2);



  if (s->pict_type == 3)

    return -1;



  if (s->pict_type == SVQ1_FRAME_INTRA) {



    /* unknown fields */

    if (s->f_code == 0x50 || s->f_code == 0x60) {

      get_bits (bitbuf, 16);

    }



    if ((s->f_code ^ 0x10) >= 0x50) {

      skip_bits(bitbuf,8*get_bits (bitbuf, 8));

    }



    get_bits (bitbuf, 2);

    get_bits (bitbuf, 2);

    get_bits (bitbuf, 1);



    /* load frame size */

    frame_size_code = get_bits (bitbuf, 3);



    if (frame_size_code == 7) {

      /* load width, height (12 bits each) */

      s->width = get_bits (bitbuf, 12);

      s->height = get_bits (bitbuf, 12);



      if (!s->width || !s->height)

        return -1;

    } else {

      /* get width, height from table */

      s->width = frame_size_table[frame_size_code].width;

      s->height = frame_size_table[frame_size_code].height;

    }

  }



  /* unknown fields */

  if (get_bits (bitbuf, 1) == 1) {

    get_bits (bitbuf, 1);

    get_bits (bitbuf, 1);



    if (get_bits (bitbuf, 2) != 0)

      return -1;

  }



  if (get_bits (bitbuf, 1) == 1) {

    get_bits (bitbuf, 1);

    get_bits (bitbuf, 4);

    get_bits (bitbuf, 1);

    get_bits (bitbuf, 2);



    while (get_bits (bitbuf, 1) == 1) {

      get_bits (bitbuf, 8);

    }

  }



  return 0;

}

static int svq3_decode_slice_header(AVCodecContext *avctx)

{

    SVQ3Context *svq3 = avctx->priv_data;

    H264Context *h = &svq3->h;

    MpegEncContext *s = &h->s;

    const int mb_xy = h->mb_xy;

    int i, header;



    header = get_bits(&s->gb, 8);



    if (((header & 0x9F) != 1 && (header & 0x9F) != 2) || (header & 0x60) == 0) {

        /* TODO: what? */

        av_log(avctx, AV_LOG_ERROR, "unsupported slice header (%02X)\n", header);

        return -1;

    } else {

        int length = (header >> 5) & 3;



        svq3->next_slice_index = get_bits_count(&s->gb) + 8*show_bits(&s->gb, 8*length) + 8*length;



        if (svq3->next_slice_index > s->gb.size_in_bits) {

            av_log(avctx, AV_LOG_ERROR, "slice after bitstream end\n");

            return -1;

    }



        s->gb.size_in_bits = svq3->next_slice_index - 8*(length - 1);

        skip_bits(&s->gb, 8);



        if (svq3->watermark_key) {

            uint32_t header = AV_RL32(&s->gb.buffer[(get_bits_count(&s->gb)>>3)+1]);

            AV_WL32(&s->gb.buffer[(get_bits_count(&s->gb)>>3)+1], header ^ svq3->watermark_key);

        }

        if (length > 0) {

            memcpy((uint8_t *) &s->gb.buffer[get_bits_count(&s->gb) >> 3],

                   &s->gb.buffer[s->gb.size_in_bits >> 3], (length - 1));

        }

        skip_bits_long(&s->gb, 0);

    }



    if ((i = svq3_get_ue_golomb(&s->gb)) == INVALID_VLC || i >= 3){

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal slice type %d \n", i);

        return -1;

    }



    h->slice_type = golomb_to_pict_type[i];



    if ((header & 0x9F) == 2) {

        i = (s->mb_num < 64) ? 6 : (1 + av_log2 (s->mb_num - 1));

        s->mb_skip_run = get_bits(&s->gb, i) - (s->mb_x + (s->mb_y * s->mb_width));

    } else {

        skip_bits1(&s->gb);

        s->mb_skip_run = 0;

    }



    h->slice_num = get_bits(&s->gb, 8);

    s->qscale = get_bits(&s->gb, 5);

    s->adaptive_quant = get_bits1(&s->gb);



    /* unknown fields */

    skip_bits1(&s->gb);



    if (svq3->unknown_flag) {

        skip_bits1(&s->gb);

    }



    skip_bits1(&s->gb);

    skip_bits(&s->gb, 2);



    while (get_bits1(&s->gb)) {

        skip_bits(&s->gb, 8);

    }



    /* reset intra predictors and invalidate motion vector references */

    if (s->mb_x > 0) {

        memset(h->intra4x4_pred_mode+h->mb2br_xy[mb_xy - 1      ]+3, -1, 4*sizeof(int8_t));

        memset(h->intra4x4_pred_mode+h->mb2br_xy[mb_xy - s->mb_x]  , -1, 8*sizeof(int8_t)*s->mb_x);

    }

    if (s->mb_y > 0) {

        memset(h->intra4x4_pred_mode+h->mb2br_xy[mb_xy - s->mb_stride], -1, 8*sizeof(int8_t)*(s->mb_width - s->mb_x));



        if (s->mb_x > 0) {

            h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - s->mb_stride - 1]+3] = -1;

        }

    }



    return 0;

}

