            }



            if (context_count == h->max_contexts) {

                execute_decode_slices(h, context_count);

                context_count = 0;

            }



            if (err < 0)

                av_log(h->s.avctx, AV_LOG_ERROR, "decode_slice_header error\n");

            else if (err == 1) {

                /* Slice could not be decoded in parallel mode, copy down

                 * NAL unit stuff to context 0 and restart. Note that

                 * rbsp_buffer is not transferred, but since we no longer

                 * run in parallel mode this should not be an issue. */

                h->nal_unit_type = hx->nal_unit_type;

                h->nal_ref_idc   = hx->nal_ref_idc;

                hx               = h;

                goto again;

            }

        }

    }

    if (context_count)

        execute_decode_slices(h, context_count);



end:

    /* clean up */

    if (s->current_picture_ptr && s->current_picture_ptr->owner2 == s &&

        !s->droppable) {

        ff_thread_report_progress(&s->current_picture_ptr->f, INT_MAX,

                                  s->picture_structure == PICT_BOTTOM_FIELD);

    }



    return buf_index;

}

static int decode_nal_units(H264Context *h, uint8_t *buf, int buf_size){

    MpegEncContext * const s = &h->s;

    AVCodecContext * const avctx= s->avctx;

    int buf_index=0;

#if 0

    int i;

    for(i=0; i<50; i++){

        av_log(NULL, AV_LOG_ERROR,"%02X ", buf[i]);

    }

#endif

    h->slice_num = 0;

    s->current_picture_ptr= NULL;

    for(;;){

        int consumed;

        int dst_length;

        int bit_length;

        uint8_t *ptr;

        int i, nalsize = 0;



      if(h->is_avc) {

        if(buf_index >= buf_size) break;

        nalsize = 0;

        for(i = 0; i < h->nal_length_size; i++)

            nalsize = (nalsize << 8) | buf[buf_index++];

        if(nalsize <= 1){

            if(nalsize == 1){

                buf_index++;

                continue;

            }else{

                av_log(h->s.avctx, AV_LOG_ERROR, "AVC: nal size %d\n", nalsize);

                break;

            }

        }

      } else {

        // start code prefix search

        for(; buf_index + 3 < buf_size; buf_index++){

            // this should allways succeed in the first iteration

            if(buf[buf_index] == 0 && buf[buf_index+1] == 0 && buf[buf_index+2] == 1)

                break;

        }



        if(buf_index+3 >= buf_size) break;



        buf_index+=3;

      }



        ptr= decode_nal(h, buf + buf_index, &dst_length, &consumed, h->is_avc ? nalsize : buf_size - buf_index);

        while(ptr[dst_length - 1] == 0 && dst_length > 1)

            dst_length--;

        bit_length= 8*dst_length - decode_rbsp_trailing(ptr + dst_length - 1);



        if(s->avctx->debug&FF_DEBUG_STARTCODE){

            av_log(h->s.avctx, AV_LOG_DEBUG, "NAL %d at %d/%d length %d\n", h->nal_unit_type, buf_index, buf_size, dst_length);

        }



        if (h->is_avc && (nalsize != consumed))

            av_log(h->s.avctx, AV_LOG_ERROR, "AVC: Consumed only %d bytes instead of %d\n", consumed, nalsize);



        buf_index += consumed;



        if(  (s->hurry_up == 1 && h->nal_ref_idc  == 0) //FIXME dont discard SEI id

           ||(avctx->skip_frame >= AVDISCARD_NONREF && h->nal_ref_idc  == 0))

            continue;



        switch(h->nal_unit_type){

        case NAL_IDR_SLICE:

            idr(h); //FIXME ensure we don't loose some frames if there is reordering

        case NAL_SLICE:

            init_get_bits(&s->gb, ptr, bit_length);

            h->intra_gb_ptr=

            h->inter_gb_ptr= &s->gb;

            s->data_partitioning = 0;



            if(decode_slice_header(h) < 0){

                av_log(h->s.avctx, AV_LOG_ERROR, "decode_slice_header error\n");

                break;

            }

            s->current_picture_ptr->key_frame= (h->nal_unit_type == NAL_IDR_SLICE);

            if(h->redundant_pic_count==0 && s->hurry_up < 5

               && (avctx->skip_frame < AVDISCARD_NONREF || h->nal_ref_idc)

               && (avctx->skip_frame < AVDISCARD_BIDIR  || h->slice_type!=B_TYPE)

               && (avctx->skip_frame < AVDISCARD_NONKEY || h->slice_type==I_TYPE)

               && avctx->skip_frame < AVDISCARD_ALL)

                decode_slice(h);

            break;

        case NAL_DPA:

            init_get_bits(&s->gb, ptr, bit_length);

            h->intra_gb_ptr=

            h->inter_gb_ptr= NULL;

            s->data_partitioning = 1;



            if(decode_slice_header(h) < 0){

                av_log(h->s.avctx, AV_LOG_ERROR, "decode_slice_header error\n");

            }

            break;

        case NAL_DPB:

            init_get_bits(&h->intra_gb, ptr, bit_length);

            h->intra_gb_ptr= &h->intra_gb;

            break;

        case NAL_DPC:

            init_get_bits(&h->inter_gb, ptr, bit_length);

            h->inter_gb_ptr= &h->inter_gb;



            if(h->redundant_pic_count==0 && h->intra_gb_ptr && s->data_partitioning

               && s->context_initialized

               && s->hurry_up < 5

               && (avctx->skip_frame < AVDISCARD_NONREF || h->nal_ref_idc)

               && (avctx->skip_frame < AVDISCARD_BIDIR  || h->slice_type!=B_TYPE)

               && (avctx->skip_frame < AVDISCARD_NONKEY || h->slice_type==I_TYPE)

               && avctx->skip_frame < AVDISCARD_ALL)

                decode_slice(h);

            break;

        case NAL_SEI:

            init_get_bits(&s->gb, ptr, bit_length);

            decode_sei(h);

            break;

        case NAL_SPS:

            init_get_bits(&s->gb, ptr, bit_length);

            decode_seq_parameter_set(h);



            if(s->flags& CODEC_FLAG_LOW_DELAY)

                s->low_delay=1;



            if(avctx->has_b_frames < 2)

                avctx->has_b_frames= !s->low_delay;

            break;

        case NAL_PPS:

            init_get_bits(&s->gb, ptr, bit_length);



            decode_picture_parameter_set(h, bit_length);



            break;

        case NAL_AUD:

        case NAL_END_SEQUENCE:

        case NAL_END_STREAM:

        case NAL_FILLER_DATA:

        case NAL_SPS_EXT:

        case NAL_AUXILIARY_SLICE:

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unknown NAL code: %d\n", h->nal_unit_type);

        }

    }



    if(!s->current_picture_ptr) return buf_index; //no frame



    s->current_picture_ptr->qscale_type= FF_QSCALE_TYPE_H264;

    s->current_picture_ptr->pict_type= s->pict_type;



    h->prev_frame_num_offset= h->frame_num_offset;

    h->prev_frame_num= h->frame_num;

    if(s->current_picture_ptr->reference){

        h->prev_poc_msb= h->poc_msb;

        h->prev_poc_lsb= h->poc_lsb;

    }

    if(s->current_picture_ptr->reference)

        execute_ref_pic_marking(h, h->mmco, h->mmco_index);



    ff_er_frame_end(s);



    MPV_frame_end(s);



    return buf_index;

}

static int dca_find_frame_end(DCAParseContext * pc1, const uint8_t * buf,

                              int buf_size)

{

    int start_found, i;

    uint32_t state;

    ParseContext *pc = &pc1->pc;



    start_found = pc->frame_start_found;

    state = pc->state;



    i = 0;

    if (!start_found) {

        for (i = 0; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (IS_MARKER(state, i, buf, buf_size)) {

                if (!pc1->lastmarker || state == pc1->lastmarker || pc1->lastmarker == DCA_HD_MARKER) {

                    start_found = 1;

                    pc1->lastmarker = state;

                    break;

                }

            }

        }

    }

    if (start_found) {

        for (; i < buf_size; i++) {

            pc1->size++;

            state = (state << 8) | buf[i];

            if (state == DCA_HD_MARKER && !pc1->hd_pos)

                pc1->hd_pos = pc1->size;

            if (IS_MARKER(state, i, buf, buf_size) && (state == pc1->lastmarker || pc1->lastmarker == DCA_HD_MARKER)) {

                if(pc1->framesize > pc1->size)

                    continue;

                if(!pc1->framesize){

                    pc1->framesize = pc1->hd_pos ? pc1->hd_pos : pc1->size;

                }

                pc->frame_start_found = 0;

                pc->state = -1;

                pc1->size = 0;

                return i - 3;

            }

        }

    }

    pc->frame_start_found = start_found;

    pc->state = state;

    return END_NOT_FOUND;

}

static int hevc_find_frame_end(AVCodecParserContext *s, const uint8_t *buf,

                               int buf_size)

{

    HEVCParserContext *ctx = s->priv_data;

    ParseContext       *pc = &ctx->pc;

    int i;



    for (i = 0; i < buf_size; i++) {

        int nut;



        pc->state64 = (pc->state64 << 8) | buf[i];



        if (((pc->state64 >> 3 * 8) & 0xFFFFFF) != START_CODE)

            continue;



        nut = (pc->state64 >> 2 * 8 + 1) & 0x3F;

        // Beginning of access unit

        if ((nut >= HEVC_NAL_VPS && nut <= HEVC_NAL_AUD) || nut == HEVC_NAL_SEI_PREFIX ||

            (nut >= 41 && nut <= 44) || (nut >= 48 && nut <= 55)) {

            if (pc->frame_start_found) {

                pc->frame_start_found = 0;

                return i - 5;

            }

        } else if (nut <= HEVC_NAL_RASL_R ||

                   (nut >= HEVC_NAL_BLA_W_LP && nut <= HEVC_NAL_CRA_NUT)) {

            int first_slice_segment_in_pic_flag = buf[i] >> 7;

            if (first_slice_segment_in_pic_flag) {

                if (!pc->frame_start_found) {

                    pc->frame_start_found = 1;

                } else { // First slice of next frame found

                    pc->frame_start_found = 0;

                    return i - 5;

                }

            }

        }

    }



    return END_NOT_FOUND;

}

static int dca_find_frame_end(DCAParseContext *pc1, const uint8_t *buf,

                              int buf_size)

{

    int start_found, i;

    uint32_t state;

    ParseContext *pc = &pc1->pc;



    start_found = pc->frame_start_found;

    state       = pc->state;



    i = 0;

    if (!start_found) {

        for (i = 0; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (IS_MARKER(state, i, buf, buf_size)) {

                if (!pc1->lastmarker || state == pc1->lastmarker || pc1->lastmarker == DCA_SYNCWORD_SUBSTREAM) {

                    start_found     = 1;

                    pc1->lastmarker = state;

                    i++;

                    break;

                }

            }

        }

    }

    if (start_found) {

        for (; i < buf_size; i++) {

            pc1->size++;

            state = (state << 8) | buf[i];

            if (state == DCA_SYNCWORD_SUBSTREAM && !pc1->hd_pos)

                pc1->hd_pos = pc1->size;

            if (IS_MARKER(state, i, buf, buf_size) && (state == pc1->lastmarker || pc1->lastmarker == DCA_SYNCWORD_SUBSTREAM)) {

                if (pc1->framesize > pc1->size)

                    continue;

                pc->frame_start_found = 0;

                pc->state             = -1;

                pc1->size             = 0;

                return i - 3;

            }

        }

    }

    pc->frame_start_found = start_found;

    pc->state             = state;

    return END_NOT_FOUND;

}

static int bmp_parse(AVCodecParserContext *s, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    BMPParseContext *bpc = s->priv_data;

    uint64_t state = bpc->pc.state64;

    int next = END_NOT_FOUND;

    int i = 0;



    *poutbuf_size = 0;



restart:

    if (bpc->pc.frame_start_found <= 2+4+4) {

        for (; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (bpc->pc.frame_start_found == 0) {

                if ((state >> 48) == (('B' << 8) | 'M')) {

                    bpc->fsize = av_bswap32(state >> 16);

                    bpc->pc.frame_start_found = 1;

                }

            } else if (bpc->pc.frame_start_found == 2+4+4) {

//                 unsigned hsize = av_bswap32(state>>32);

                unsigned ihsize = av_bswap32(state);

                if (ihsize < 12 || ihsize > 200) {

                    bpc->pc.frame_start_found = 0;

                    continue;

                }

                bpc->pc.frame_start_found++;

                bpc->remaining_size = bpc->fsize + i - 17;



                if (bpc->pc.index + i > 17) {

                    next = i - 17;

                    state = 0;

                    break;

                } else {

                    bpc->pc.state64 = 0;

                    goto restart;

                }

            } else if (bpc->pc.frame_start_found)

                bpc->pc.frame_start_found++;

        }

        bpc->pc.state64 = state;

    } else {

        if (bpc->remaining_size) {

            i = FFMIN(bpc->remaining_size, buf_size);

            bpc->remaining_size -= i;

            if (bpc->remaining_size)

                goto flush;



            bpc->pc.frame_start_found = 0;

            goto restart;

        }

    }



flush:

    if (ff_combine_frame(&bpc->pc, next, &buf, &buf_size) < 0)

        return buf_size;



    if (next != END_NOT_FOUND && next < 0)

        bpc->pc.frame_start_found = FFMAX(bpc->pc.frame_start_found - i - 1, 0);

    else

        bpc->pc.frame_start_found = 0;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static av_cold int vaapi_encode_h265_init_constant_bitrate(AVCodecContext *avctx)

{

    VAAPIEncodeContext      *ctx = avctx->priv_data;

    VAAPIEncodeH265Context *priv = ctx->priv_data;

    int hrd_buffer_size;

    int hrd_initial_buffer_fullness;



    if (avctx->bit_rate > INT32_MAX) {

        av_log(avctx, AV_LOG_ERROR, "Target bitrate of 2^31 bps or "

               "higher is not supported.\n");

        return AVERROR(EINVAL);

    }



    if (avctx->rc_buffer_size)

        hrd_buffer_size = avctx->rc_buffer_size;

    else

        hrd_buffer_size = avctx->bit_rate;

    if (avctx->rc_initial_buffer_occupancy)

        hrd_initial_buffer_fullness = avctx->rc_initial_buffer_occupancy;

    else

        hrd_initial_buffer_fullness = hrd_buffer_size * 3 / 4;



    priv->rc_params.misc.type = VAEncMiscParameterTypeRateControl;

    priv->rc_params.rc = (VAEncMiscParameterRateControl) {

        .bits_per_second   = avctx->bit_rate,

        .target_percentage = 66,

        .window_size       = 1000,

        .initial_qp        = (avctx->qmax >= 0 ? avctx->qmax : 40),

        .min_qp            = (avctx->qmin >= 0 ? avctx->qmin : 20),

        .basic_unit_size   = 0,

    };

    ctx->global_params[ctx->nb_global_params] =

        &priv->rc_params.misc;

    ctx->global_params_size[ctx->nb_global_params++] =

        sizeof(priv->rc_params);



    priv->hrd_params.misc.type = VAEncMiscParameterTypeHRD;

    priv->hrd_params.hrd = (VAEncMiscParameterHRD) {

        .initial_buffer_fullness = hrd_initial_buffer_fullness,

        .buffer_size             = hrd_buffer_size,

    };

    ctx->global_params[ctx->nb_global_params] =

        &priv->hrd_params.misc;

    ctx->global_params_size[ctx->nb_global_params++] =

        sizeof(priv->hrd_params);



    // These still need to be  set for pic_init_qp/slice_qp_delta.

    priv->fixed_qp_idr = 30;

    priv->fixed_qp_p   = 30;

    priv->fixed_qp_b   = 30;



    av_log(avctx, AV_LOG_DEBUG, "Using constant-bitrate = %"PRId64" bps.\n",

           avctx->bit_rate);

    return 0;

}

