static int huff_build(VLC *vlc, uint8_t *len)

{

    HuffEntry he[256];

    uint32_t codes[256];

    uint8_t bits[256];

    uint8_t syms[256];

    uint32_t code;

    int i;



    for (i = 0; i < 256; i++) {

        he[i].sym = 255 - i;

        he[i].len = len[i];

        if (len[i] == 0)

            return AVERROR_INVALIDDATA;

    }

    AV_QSORT(he, 256, HuffEntry, huff_cmp_len);



    code = 1;

    for (i = 255; i >= 0; i--) {

        codes[i] = code >> (32 - he[i].len);

        bits[i]  = he[i].len;

        syms[i]  = he[i].sym;

        code += 0x80000000u >> (he[i].len - 1);

    }



    ff_free_vlc(vlc);

    return ff_init_vlc_sparse(vlc, FFMIN(he[255].len, 12), 256,

                              bits,  sizeof(*bits),  sizeof(*bits),

                              codes, sizeof(*codes), sizeof(*codes),

                              syms,  sizeof(*syms),  sizeof(*syms), 0);

}

static int huff_build12(VLC *vlc, uint8_t *len)

{

    HuffEntry he[4096];

    uint32_t codes[4096];

    uint8_t bits[4096];

    uint16_t syms[4096];

    uint32_t code;

    int i;



    for (i = 0; i < 4096; i++) {

        he[i].sym = 4095 - i;

        he[i].len = len[i];

        if (len[i] == 0)

            return AVERROR_INVALIDDATA;

    }

    AV_QSORT(he, 4096, HuffEntry, huff_cmp_len12);



    code = 1;

    for (i = 4095; i >= 0; i--) {

        codes[i] = code >> (32 - he[i].len);

        bits[i]  = he[i].len;

        syms[i]  = he[i].sym;

        code += 0x80000000u >> (he[i].len - 1);

    }



    ff_free_vlc(vlc);

    return ff_init_vlc_sparse(vlc, FFMIN(he[4095].len, 14), 4096,

                              bits,  sizeof(*bits),  sizeof(*bits),

                              codes, sizeof(*codes), sizeof(*codes),

                              syms,  sizeof(*syms),  sizeof(*syms), 0);

}

static int build_huff(const uint8_t *src, VLC *vlc)

{

    int i;

    HuffEntry he[256];

    int last;

    uint32_t codes[256];

    uint8_t bits[256];

    uint8_t syms[256];

    uint32_t code;



    for (i = 0; i < 256; i++) {

        he[i].sym = i;

        he[i].len = *src++;

    }

    qsort(he, 256, sizeof(*he), huff_cmp);



    if (!he[0].len || he[0].len > 32)

        return -1;



    last = 255;

    while (he[last].len == 255 && last)

        last--;



    code = 1;

    for (i = last; i >= 0; i--) {

        codes[i] = code >> (32 - he[i].len);

        bits[i]  = he[i].len;

        syms[i]  = he[i].sym;

        code += 0x80000000u >> (he[i].len - 1);

    }



    return init_vlc_sparse(vlc, FFMIN(he[last].len, 9), last + 1,

                           bits,  sizeof(*bits),  sizeof(*bits),

                           codes, sizeof(*codes), sizeof(*codes),

                           syms,  sizeof(*syms),  sizeof(*syms), 0);

}

static int init_ralf_vlc(VLC *vlc, const uint8_t *data, int elems)

{

    uint8_t  lens[MAX_ELEMS];

    uint16_t codes[MAX_ELEMS];

    int counts[17], prefixes[18];

    int i, cur_len;

    int max_bits = 0;

    GetBitContext gb;



    init_get_bits(&gb, data, elems * 4);



    for (i = 0; i <= 16; i++)

        counts[i] = 0;

    for (i = 0; i < elems; i++) {

        cur_len  = get_bits(&gb, 4) + 1;

        counts[cur_len]++;

        max_bits = FFMAX(max_bits, cur_len);

        lens[i]  = cur_len;

    }

    prefixes[1] = 0;

    for (i = 1; i <= 16; i++)

        prefixes[i + 1] = (prefixes[i] + counts[i]) << 1;



    for (i = 0; i < elems; i++)

        codes[i] = prefixes[lens[i]]++;



    return ff_init_vlc_sparse(vlc, FFMIN(max_bits, 9), elems,

                              lens, 1, 1, codes, 2, 2, NULL, 0, 0, 0);

}

static void test_wait_event_notifier(void)

{

    EventNotifierTestData data = { .n = 0, .active = 1 };

    event_notifier_init(&data.e, false);

    aio_set_event_notifier(ctx, &data.e, event_ready_cb, event_active_cb);

    g_assert(aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 0);

    g_assert_cmpint(data.active, ==, 1);



    event_notifier_set(&data.e);

    g_assert(aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);

    g_assert_cmpint(data.active, ==, 0);



    g_assert(!aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);

    g_assert_cmpint(data.active, ==, 0);



    aio_set_event_notifier(ctx, &data.e, NULL, NULL);

    g_assert(!aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);



    event_notifier_cleanup(&data.e);

}

