                                 const void *unused)

{

    data->qov = qmp_output_visitor_new();

    g_assert(data->qov != NULL);



    data->ov = qmp_output_get_visitor(data->qov);

    g_assert(data->ov != NULL);

}

static int nut_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    NUTContext *nut = s->priv_data;

    ByteIOContext *bc = &s->pb;

    int64_t pos;

    int inited_stream_count;



    nut->avf= s;



    /* main header */

    pos=0;

    for(;;){

        pos= find_startcode(bc, MAIN_STARTCODE, pos)+1;

        if (pos<0){

            av_log(s, AV_LOG_ERROR, "no main startcode found\n");

            return -1;

        }

        if(decode_main_header(nut) >= 0)

            break;

    }





    s->bit_rate = 0;



    nut->stream = av_malloc(sizeof(StreamContext)*nut->stream_count);



    /* stream headers */

    pos=0;

    for(inited_stream_count=0; inited_stream_count < nut->stream_count;){

        pos= find_startcode(bc, STREAM_STARTCODE, pos)+1;

        if (pos<0){

            av_log(s, AV_LOG_ERROR, "not all stream headers found\n");

            return -1;

        }

        if(decode_stream_header(nut) >= 0)

            inited_stream_count++;

    }



    /* info headers */

    pos=0;

    for(;;){

        uint64_t startcode= find_any_startcode(bc, pos);

        pos= url_ftell(bc);



        if(startcode==0){

            av_log(s, AV_LOG_ERROR, "EOF before video frames\n");

            return -1;

        }else if(startcode == KEYFRAME_STARTCODE){

            nut->next_startcode= startcode;

            break;

        }else if(startcode != INFO_STARTCODE){

            continue;

        }



        decode_info_header(nut);

    }



    return 0;

}

static int mov_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    MOVContext *mov = (MOVContext *) s->priv_data;

    ByteIOContext *pb = &s->pb;

    int i, err;

    MOV_atom_t atom = { 0, 0, 0 };



    mov->fc = s;

    mov->parse_table = mov_default_parse_table;



    if(!url_is_streamed(pb)) /* .mov and .mp4 aren't streamable anyway (only progressive download if moov is before mdat) */

        atom.size = url_fsize(pb);

    else

        atom.size = 0x7FFFFFFFFFFFFFFFLL;



    /* check MOV header */

    err = mov_read_default(mov, pb, atom);

    if (err<0 || (!mov->found_moov && !mov->found_mdat)) {

        av_log(s, AV_LOG_ERROR, "mov: header not found !!! (err:%d, moov:%d, mdat:%d) pos:%"PRId64"\n",

                err, mov->found_moov, mov->found_mdat, url_ftell(pb));

        return -1;

    }

    dprintf("on_parse_exit_offset=%d\n", (int) url_ftell(pb));



    /* some cleanup : make sure we are on the mdat atom */

    if(!url_is_streamed(pb) && (url_ftell(pb) != mov->mdat_offset))

        url_fseek(pb, mov->mdat_offset, SEEK_SET);



    mov->total_streams = s->nb_streams;



    for(i=0; i<mov->total_streams; i++) {

        MOVStreamContext *sc = mov->streams[i];



        if(!sc->time_rate)

            sc->time_rate=1;

        if(!sc->time_scale)

            sc->time_scale= mov->time_scale;

        av_set_pts_info(s->streams[i], 64, sc->time_rate, sc->time_scale);



        if(s->streams[i]->duration != AV_NOPTS_VALUE){

            assert(s->streams[i]->duration % sc->time_rate == 0);

            s->streams[i]->duration /= sc->time_rate;

        }

        sc->ffindex = i;

        mov_build_index(mov, s->streams[i]);

    }



    for(i=0; i<mov->total_streams; i++) {

        /* dont need those anymore */

        av_freep(&mov->streams[i]->chunk_offsets);

        av_freep(&mov->streams[i]->sample_to_chunk);

        av_freep(&mov->streams[i]->sample_sizes);

        av_freep(&mov->streams[i]->keyframes);

        av_freep(&mov->streams[i]->stts_data);

    }

    av_freep(&mov->mdat_list);

    return 0;

}

static int find_and_decode_index(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = s->pb;

    uint64_t tmp, end;

    int i, j, syncpoint_count;

    int64_t filesize= url_fsize(bc);

    int64_t *syncpoints;

    int8_t *has_keyframe;



    url_fseek(bc, filesize-12, SEEK_SET);

    url_fseek(bc, filesize-get_be64(bc), SEEK_SET);

    if(get_be64(bc) != INDEX_STARTCODE){

        av_log(s, AV_LOG_ERROR, "no index at the end\n");

        return -1;

    }



    end= get_packetheader(nut, bc, 1, INDEX_STARTCODE);

    end += url_ftell(bc);



    ff_get_v(bc); //max_pts

    GET_V(syncpoint_count, tmp < INT_MAX/8 && tmp > 0)

    syncpoints= av_malloc(sizeof(int64_t)*syncpoint_count);

    has_keyframe= av_malloc(sizeof(int8_t)*(syncpoint_count+1));

    for(i=0; i<syncpoint_count; i++){

        GET_V(syncpoints[i], tmp>0)

        if(i)

            syncpoints[i] += syncpoints[i-1];

    }



    for(i=0; i<s->nb_streams; i++){

        int64_t last_pts= -1;

        for(j=0; j<syncpoint_count;){

            uint64_t x= ff_get_v(bc);

            int type= x&1;

            int n= j;

            x>>=1;

            if(type){

                int flag= x&1;

                x>>=1;

                if(n+x >= syncpoint_count + 1){

                    av_log(s, AV_LOG_ERROR, "index overflow A\n");

                    return -1;

                }

                while(x--)

                    has_keyframe[n++]= flag;

                has_keyframe[n++]= !flag;

            }else{

                while(x != 1){

                    if(n>=syncpoint_count + 1){

                        av_log(s, AV_LOG_ERROR, "index overflow B\n");

                        return -1;

                    }

                    has_keyframe[n++]= x&1;

                    x>>=1;

                }

            }

            if(has_keyframe[0]){

                av_log(s, AV_LOG_ERROR, "keyframe before first syncpoint in index\n");

                return -1;

            }

            assert(n<=syncpoint_count+1);

            for(; j<n; j++){

                if(has_keyframe[j]){

                    uint64_t B, A= ff_get_v(bc);

                    if(!A){

                        A= ff_get_v(bc);

                        B= ff_get_v(bc);

                        //eor_pts[j][i] = last_pts + A + B

                    }else

                        B= 0;

                    av_add_index_entry(

                        s->streams[i],

                        16*syncpoints[j-1],

                        last_pts + A,

                        0,

                        0,

                        AVINDEX_KEYFRAME);

                    last_pts += A + B;

                }

            }

        }

    }



    if(skip_reserved(bc, end) || get_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "index checksum mismatch\n");

        return -1;

    }

    return 0;

}

static int get_packetheader(NUTContext *nut, ByteIOContext *bc, int prefix_length)

{

    int64_t start, size, last_size;

    start= url_ftell(bc) - prefix_length;



    if(start != nut->packet_start + nut->written_packet_size){

        av_log(nut->avf, AV_LOG_ERROR, "get_packetheader called at weird position\n");

        return -1;

    }



    size= get_v(bc);

    last_size= get_v(bc);

    if(nut->written_packet_size != last_size){

        av_log(nut->avf, AV_LOG_ERROR, "packet size missmatch %d != %lld at %lld\n", nut->written_packet_size, last_size, start);

        return -1;

    }



    nut->last_packet_start = nut->packet_start;

    nut->packet_start = start;

    nut->written_packet_size= size;



    return size;

}

int ff_v4l2_m2m_codec_end(AVCodecContext *avctx)

{

    V4L2m2mContext* s = avctx->priv_data;

    int ret;



    ret = ff_v4l2_context_set_status(&s->output, VIDIOC_STREAMOFF);

    if (ret)

            av_log(avctx, AV_LOG_ERROR, "VIDIOC_STREAMOFF %s\n", s->output.name);



    ret = ff_v4l2_context_set_status(&s->capture, VIDIOC_STREAMOFF);

    if (ret)

        av_log(avctx, AV_LOG_ERROR, "VIDIOC_STREAMOFF %s\n", s->capture.name);



    ff_v4l2_context_release(&s->output);



    if (atomic_load(&s->refcount))

        av_log(avctx, AV_LOG_ERROR, "ff_v4l2m2m_codec_end leaving pending buffers\n");



    ff_v4l2_context_release(&s->capture);

    sem_destroy(&s->refsync);



    /* release the hardware */

    if (close(s->fd) < 0 )

        av_log(avctx, AV_LOG_ERROR, "failure closing %s (%s)\n", s->devname, av_err2str(AVERROR(errno)));



    s->fd = -1;



    return 0;

}

int ff_v4l2_m2m_codec_full_reinit(V4L2m2mContext *s)

{

    void *log_ctx = s->avctx;

    int ret;



    av_log(log_ctx, AV_LOG_DEBUG, "%s full reinit\n", s->devname);



    /* wait for pending buffer references */

    if (atomic_load(&s->refcount))

        while(sem_wait(&s->refsync) == -1 && errno == EINTR);



    /* close the driver */

    ff_v4l2_m2m_codec_end(s->avctx);



    /* start again now that we know the stream dimensions */

    s->draining = 0;

    s->reinit = 0;



    s->fd = open(s->devname, O_RDWR | O_NONBLOCK, 0);

    if (s->fd < 0)

        return AVERROR(errno);



    ret = v4l2_prepare_contexts(s);

    if (ret < 0)

        goto error;



    /* if a full re-init was requested - probe didn't run - we need to populate

     * the format for each context

     */

    ret = ff_v4l2_context_get_format(&s->output);

    if (ret) {

        av_log(log_ctx, AV_LOG_DEBUG, "v4l2 output format not supported\n");

        goto error;

    }



    ret = ff_v4l2_context_get_format(&s->capture);

    if (ret) {

        av_log(log_ctx, AV_LOG_DEBUG, "v4l2 capture format not supported\n");

        goto error;

    }



    ret = ff_v4l2_context_set_format(&s->output);

    if (ret) {

        av_log(log_ctx, AV_LOG_ERROR, "can't set v4l2 output format\n");

        goto error;

    }



    ret = ff_v4l2_context_set_format(&s->capture);

    if (ret) {

        av_log(log_ctx, AV_LOG_ERROR, "can't to set v4l2 capture format\n");

        goto error;

    }



    ret = ff_v4l2_context_init(&s->output);

    if (ret) {

        av_log(log_ctx, AV_LOG_ERROR, "no v4l2 output context's buffers\n");

        goto error;

    }



    /* decoder's buffers need to be updated at a later stage */

    if (!av_codec_is_decoder(s->avctx->codec)) {

        ret = ff_v4l2_context_init(&s->capture);

        if (ret) {

            av_log(log_ctx, AV_LOG_ERROR, "no v4l2 capture context's buffers\n");

            goto error;

        }

    }



    return 0;



error:

    if (close(s->fd) < 0) {

        ret = AVERROR(errno);

        av_log(log_ctx, AV_LOG_ERROR, "error closing %s (%s)\n",

            s->devname, av_err2str(AVERROR(errno)));

    }

    s->fd = -1;



    return ret;

}

static int v4l2_receive_packet(AVCodecContext *avctx, AVPacket *avpkt)

{

    V4L2m2mContext *s = avctx->priv_data;

    V4L2Context *const capture = &s->capture;

    V4L2Context *const output = &s->output;

    int ret;



    if (s->draining)

        goto dequeue;



    if (!output->streamon) {

        ret = ff_v4l2_context_set_status(output, VIDIOC_STREAMON);

        if (ret) {

            av_log(avctx, AV_LOG_ERROR, "VIDIOC_STREAMOFF failed on output context\n");

            return ret;

        }

    }



    if (!capture->streamon) {

        ret = ff_v4l2_context_set_status(capture, VIDIOC_STREAMON);

        if (ret) {

            av_log(avctx, AV_LOG_ERROR, "VIDIOC_STREAMON failed on capture context\n");

            return ret;

        }

    }



dequeue:

    return ff_v4l2_context_dequeue_packet(capture, avpkt);

}

static av_cold int v4l2_decode_init(AVCodecContext *avctx)

{

    V4L2m2mContext *s = avctx->priv_data;

    V4L2Context *capture = &s->capture;

    V4L2Context *output = &s->output;

    int ret;



    /* if these dimensions are invalid (ie, 0 or too small) an event will be raised

     * by the v4l2 driver; this event will trigger a full pipeline reconfig and

     * the proper values will be retrieved from the kernel driver.

     */

    output->height = capture->height = avctx->coded_height;

    output->width = capture->width = avctx->coded_width;



    output->av_codec_id = avctx->codec_id;

    output->av_pix_fmt  = AV_PIX_FMT_NONE;



    capture->av_codec_id = AV_CODEC_ID_RAWVIDEO;

    capture->av_pix_fmt = avctx->pix_fmt;



    ret = ff_v4l2_m2m_codec_init(avctx);

    if (ret) {

        av_log(avctx, AV_LOG_ERROR, "can't configure decoder\n");

        return ret;

    }



    return v4l2_prepare_decoder(s);

}

static int film_read_header(AVFormatContext *s)

{

    FilmDemuxContext *film = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    unsigned char scratch[256];

    int i;

    unsigned int data_offset;

    unsigned int audio_frame_counter;



    film->sample_table = NULL;

    film->stereo_buffer = NULL;

    film->stereo_buffer_size = 0;



    /* load the main FILM header */

    if (avio_read(pb, scratch, 16) != 16)

        return AVERROR(EIO);

    data_offset = AV_RB32(&scratch[4]);

    film->version = AV_RB32(&scratch[8]);



    /* load the FDSC chunk */

    if (film->version == 0) {

        /* special case for Lemmings .film files; 20-byte header */

        if (avio_read(pb, scratch, 20) != 20)

            return AVERROR(EIO);

        /* make some assumptions about the audio parameters */

        film->audio_type = AV_CODEC_ID_PCM_S8;

        film->audio_samplerate = 22050;

        film->audio_channels = 1;

        film->audio_bits = 8;

    } else {

        /* normal Saturn .cpk files; 32-byte header */

        if (avio_read(pb, scratch, 32) != 32)

            return AVERROR(EIO);

        film->audio_samplerate = AV_RB16(&scratch[24]);

        film->audio_channels = scratch[21];

        if (!film->audio_channels || film->audio_channels > 2) {

            av_log(s, AV_LOG_ERROR,

                   "Invalid number of channels: %d\n", film->audio_channels);

            return AVERROR_INVALIDDATA;

        }

        film->audio_bits = scratch[22];

        if (scratch[23] == 2)

            film->audio_type = AV_CODEC_ID_ADPCM_ADX;

        else if (film->audio_channels > 0) {

            if (film->audio_bits == 8)

                film->audio_type = AV_CODEC_ID_PCM_S8;

            else if (film->audio_bits == 16)

                film->audio_type = AV_CODEC_ID_PCM_S16BE;

            else

                film->audio_type = AV_CODEC_ID_NONE;

        } else

            film->audio_type = AV_CODEC_ID_NONE;

    }



    if (AV_RB32(&scratch[0]) != FDSC_TAG)

        return AVERROR_INVALIDDATA;



    if (AV_RB32(&scratch[8]) == CVID_TAG) {

        film->video_type = AV_CODEC_ID_CINEPAK;

    } else if (AV_RB32(&scratch[8]) == RAW_TAG) {

        film->video_type = AV_CODEC_ID_RAWVIDEO;

    } else {

        film->video_type = AV_CODEC_ID_NONE;

    }



    /* initialize the decoder streams */

    if (film->video_type) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        film->video_stream_index = st->index;

        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        st->codec->codec_id = film->video_type;

        st->codec->codec_tag = 0;  /* no fourcc */

        st->codec->width = AV_RB32(&scratch[16]);

        st->codec->height = AV_RB32(&scratch[12]);



        if (film->video_type == AV_CODEC_ID_RAWVIDEO) {

            if (scratch[20] == 24) {

                st->codec->pix_fmt = AV_PIX_FMT_RGB24;

            } else {

                av_log(s, AV_LOG_ERROR, "raw video is using unhandled %dbpp\n", scratch[20]);

                return -1;

            }

        }

    }



    if (film->audio_type) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        film->audio_stream_index = st->index;

        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_id = film->audio_type;

        st->codec->codec_tag = 1;

        st->codec->channels = film->audio_channels;

        st->codec->sample_rate = film->audio_samplerate;



        if (film->audio_type == AV_CODEC_ID_ADPCM_ADX) {

            st->codec->bits_per_coded_sample = 18 * 8 / 32;

            st->codec->block_align = st->codec->channels * 18;

            st->need_parsing = AVSTREAM_PARSE_FULL;

        } else {

            st->codec->bits_per_coded_sample = film->audio_bits;

            st->codec->block_align = st->codec->channels *

                st->codec->bits_per_coded_sample / 8;

        }



        st->codec->bit_rate = st->codec->channels * st->codec->sample_rate *

            st->codec->bits_per_coded_sample;

    }



    /* load the sample table */

    if (avio_read(pb, scratch, 16) != 16)

        return AVERROR(EIO);

    if (AV_RB32(&scratch[0]) != STAB_TAG)

        return AVERROR_INVALIDDATA;

    film->base_clock = AV_RB32(&scratch[8]);

    film->sample_count = AV_RB32(&scratch[12]);

    if(film->sample_count >= UINT_MAX / sizeof(film_sample))

        return -1;

    film->sample_table = av_malloc(film->sample_count * sizeof(film_sample));

    if (!film->sample_table)

        return AVERROR(ENOMEM);



    for (i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

            avpriv_set_pts_info(st, 33, 1, film->base_clock);

        else

            avpriv_set_pts_info(st, 64, 1, film->audio_samplerate);

    }



    audio_frame_counter = 0;

    for (i = 0; i < film->sample_count; i++) {

        /* load the next sample record and transfer it to an internal struct */

        if (avio_read(pb, scratch, 16) != 16) {

            av_free(film->sample_table);

            return AVERROR(EIO);

        }

        film->sample_table[i].sample_offset =

            data_offset + AV_RB32(&scratch[0]);

        film->sample_table[i].sample_size = AV_RB32(&scratch[4]);

        if (film->sample_table[i].sample_size > INT_MAX / 4)

            return AVERROR_INVALIDDATA;

        if (AV_RB32(&scratch[8]) == 0xFFFFFFFF) {

            film->sample_table[i].stream = film->audio_stream_index;

            film->sample_table[i].pts = audio_frame_counter;



            if (film->audio_type == AV_CODEC_ID_ADPCM_ADX)

                audio_frame_counter += (film->sample_table[i].sample_size * 32 /

                    (18 * film->audio_channels));

            else if (film->audio_type != AV_CODEC_ID_NONE)

                audio_frame_counter += (film->sample_table[i].sample_size /

                    (film->audio_channels * film->audio_bits / 8));

        } else {

            film->sample_table[i].stream = film->video_stream_index;

            film->sample_table[i].pts = AV_RB32(&scratch[8]) & 0x7FFFFFFF;

            film->sample_table[i].keyframe = (scratch[8] & 0x80) ? 0 : 1;

        }

    }



    film->current_sample = 0;



    return 0;

}

static int flic_read_header(AVFormatContext *s)

{

    FlicDemuxContext *flic = s->priv_data;

    AVIOContext *pb = s->pb;

    unsigned char header[FLIC_HEADER_SIZE];

    AVStream *st, *ast;

    int speed;

    int magic_number;

    unsigned char preamble[FLIC_PREAMBLE_SIZE];



    flic->frame_number = 0;



    /* load the whole header and pull out the width and height */

    if (avio_read(pb, header, FLIC_HEADER_SIZE) != FLIC_HEADER_SIZE)

        return AVERROR(EIO);



    magic_number = AV_RL16(&header[4]);

    speed = AV_RL32(&header[0x10]);

    if (speed == 0)

        speed = FLIC_DEFAULT_SPEED;



    /* initialize the decoder streams */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    flic->video_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_FLIC;

    st->codec->codec_tag = 0;  /* no fourcc */

    st->codec->width = AV_RL16(&header[0x08]);

    st->codec->height = AV_RL16(&header[0x0A]);



    if (!st->codec->width || !st->codec->height) {

        /* Ugly hack needed for the following sample: */

        /* http://samples.mplayerhq.hu/fli-flc/fli-bugs/specular.flc */

        av_log(s, AV_LOG_WARNING,

               "File with no specified width/height. Trying 640x480.\n");

        st->codec->width  = 640;

        st->codec->height = 480;

    }



    /* send over the whole 128-byte FLIC header */

    st->codec->extradata_size = FLIC_HEADER_SIZE;

    st->codec->extradata = av_malloc(FLIC_HEADER_SIZE);

    memcpy(st->codec->extradata, header, FLIC_HEADER_SIZE);



    /* peek at the preamble to detect TFTD videos - they seem to always start with an audio chunk */

    if (avio_read(pb, preamble, FLIC_PREAMBLE_SIZE) != FLIC_PREAMBLE_SIZE) {

        av_log(s, AV_LOG_ERROR, "Failed to peek at preamble\n");

        return AVERROR(EIO);

    }



    avio_seek(pb, -FLIC_PREAMBLE_SIZE, SEEK_CUR);



    /* Time to figure out the framerate:

     * If the first preamble's magic number is 0xAAAA then this file is from

     * X-COM: Terror from the Deep. If on the other hand there is a FLIC chunk

     * magic number at offset 0x10 assume this file is from Magic Carpet instead.

     * If neither of the above is true then this is a normal FLIC file.

     */

    if (AV_RL16(&preamble[4]) == FLIC_TFTD_CHUNK_AUDIO) {

        /* TFTD videos have an extra 22050 Hz 8-bit mono audio stream */

        ast = avformat_new_stream(s, NULL);

        if (!ast)

            return AVERROR(ENOMEM);



        flic->audio_stream_index = ast->index;



        /* all audio frames are the same size, so use the size of the first chunk for block_align */

        ast->codec->block_align = AV_RL32(&preamble[0]);

        ast->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        ast->codec->codec_id = AV_CODEC_ID_PCM_U8;

        ast->codec->codec_tag = 0;

        ast->codec->sample_rate = FLIC_TFTD_SAMPLE_RATE;

        ast->codec->channels = 1;

        ast->codec->bit_rate = st->codec->sample_rate * 8;

        ast->codec->bits_per_coded_sample = 8;

        ast->codec->channel_layout = AV_CH_LAYOUT_MONO;

        ast->codec->extradata_size = 0;



        /* Since the header information is incorrect we have to figure out the

         * framerate using block_align and the fact that the audio is 22050 Hz.

         * We usually have two cases: 2205 -> 10 fps and 1470 -> 15 fps */

        avpriv_set_pts_info(st, 64, ast->codec->block_align, FLIC_TFTD_SAMPLE_RATE);

        avpriv_set_pts_info(ast, 64, 1, FLIC_TFTD_SAMPLE_RATE);

    } else if (AV_RL16(&header[0x10]) == FLIC_CHUNK_MAGIC_1) {

        avpriv_set_pts_info(st, 64, FLIC_MC_SPEED, 70);



        /* rewind the stream since the first chunk is at offset 12 */

        avio_seek(pb, 12, SEEK_SET);



        /* send over abbreviated FLIC header chunk */

        av_free(st->codec->extradata);

        st->codec->extradata_size = 12;

        st->codec->extradata = av_malloc(12);

        memcpy(st->codec->extradata, header, 12);



    } else if (magic_number == FLIC_FILE_MAGIC_1) {

        avpriv_set_pts_info(st, 64, speed, 70);

    } else if ((magic_number == FLIC_FILE_MAGIC_2) ||

               (magic_number == FLIC_FILE_MAGIC_3)) {

        avpriv_set_pts_info(st, 64, speed, 1000);

    } else {

        av_log(s, AV_LOG_ERROR, "Invalid or unsupported magic chunk in file\n");

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static int wsvqa_read_header(AVFormatContext *s)

{

    WsVqaDemuxContext *wsvqa = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    unsigned char *header;

    unsigned char scratch[VQA_PREAMBLE_SIZE];

    unsigned int chunk_tag;

    unsigned int chunk_size;

    int fps;



    /* initialize the video decoder stream */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->start_time = 0;

    wsvqa->video_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_WS_VQA;

    st->codec->codec_tag = 0;  /* no fourcc */



    /* skip to the start of the VQA header */

    avio_seek(pb, 20, SEEK_SET);



    /* the VQA header needs to go to the decoder */

    st->codec->extradata_size = VQA_HEADER_SIZE;

    st->codec->extradata = av_mallocz(VQA_HEADER_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

    header = (unsigned char *)st->codec->extradata;

    if (avio_read(pb, st->codec->extradata, VQA_HEADER_SIZE) !=

        VQA_HEADER_SIZE) {

        av_free(st->codec->extradata);

        return AVERROR(EIO);

    }

    st->codec->width = AV_RL16(&header[6]);

    st->codec->height = AV_RL16(&header[8]);

    fps = header[12];

    st->nb_frames =

    st->duration  = AV_RL16(&header[4]);

    if (fps < 1 || fps > 30) {

        av_log(s, AV_LOG_ERROR, "invalid fps: %d\n", fps);

        return AVERROR_INVALIDDATA;

    }

    avpriv_set_pts_info(st, 64, 1, fps);



    wsvqa->version      = AV_RL16(&header[ 0]);

    wsvqa->sample_rate  = AV_RL16(&header[24]);

    wsvqa->channels     = header[26];

    wsvqa->bps          = header[27];

    wsvqa->audio_stream_index = -1;



    s->ctx_flags |= AVFMTCTX_NOHEADER;



    /* there are 0 or more chunks before the FINF chunk; iterate until

     * FINF has been skipped and the file will be ready to be demuxed */

    do {

        if (avio_read(pb, scratch, VQA_PREAMBLE_SIZE) != VQA_PREAMBLE_SIZE)

            return AVERROR(EIO);

        chunk_tag = AV_RB32(&scratch[0]);

        chunk_size = AV_RB32(&scratch[4]);



        /* catch any unknown header tags, for curiousity */

        switch (chunk_tag) {

        case CINF_TAG:

        case CINH_TAG:

        case CIND_TAG:

        case PINF_TAG:

        case PINH_TAG:

        case PIND_TAG:

        case FINF_TAG:

        case CMDS_TAG:

            break;



        default:

            av_log (s, AV_LOG_ERROR, " note: unknown chunk seen (%c%c%c%c)\n",

                scratch[0], scratch[1],

                scratch[2], scratch[3]);

            break;

        }



        avio_skip(pb, chunk_size);

    } while (chunk_tag != FINF_TAG);



    return 0;

}

static int flic_read_header(AVFormatContext *s,

                            AVFormatParameters *ap)

{

    FlicDemuxContext *flic = s->priv_data;

    ByteIOContext *pb = &s->pb;

    unsigned char header[FLIC_HEADER_SIZE];

    AVStream *st;

    int speed;

    int magic_number;



    flic->pts = 0;



    /* load the whole header and pull out the width and height */

    if (get_buffer(pb, header, FLIC_HEADER_SIZE) != FLIC_HEADER_SIZE)

        return AVERROR(EIO);



    magic_number = AV_RL16(&header[4]);

    speed = AV_RL32(&header[0x10]);



    /* initialize the decoder streams */

    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);

    flic->video_stream_index = st->index;

    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_FLIC;

    st->codec->codec_tag = 0;  /* no fourcc */

    st->codec->width = AV_RL16(&header[0x08]);

    st->codec->height = AV_RL16(&header[0x0A]);



    if (!st->codec->width || !st->codec->height)

        return AVERROR_INVALIDDATA;



    /* send over the whole 128-byte FLIC header */

    st->codec->extradata_size = FLIC_HEADER_SIZE;

    st->codec->extradata = av_malloc(FLIC_HEADER_SIZE);

    memcpy(st->codec->extradata, header, FLIC_HEADER_SIZE);



    av_set_pts_info(st, 33, 1, 90000);



    /* Time to figure out the framerate: If there is a FLIC chunk magic

     * number at offset 0x10, assume this is from the Bullfrog game,

     * Magic Carpet. */

    if (AV_RL16(&header[0x10]) == FLIC_CHUNK_MAGIC_1) {



        flic->frame_pts_inc = FLIC_MC_PTS_INC;



        /* rewind the stream since the first chunk is at offset 12 */

        url_fseek(pb, 12, SEEK_SET);



        /* send over abbreviated FLIC header chunk */

        av_free(st->codec->extradata);

        st->codec->extradata_size = 12;

        st->codec->extradata = av_malloc(12);

        memcpy(st->codec->extradata, header, 12);



    } else if (magic_number == FLIC_FILE_MAGIC_1) {

        /*

         * in this case, the speed (n) is number of 1/70s ticks between frames:

         *

         *    pts        n * frame #

         *  --------  =  -----------  => pts = n * (90000/70) * frame #

         *   90000           70

         *

         *  therefore, the frame pts increment = n * 1285.7

         */

        flic->frame_pts_inc = speed * 1285.7;

    } else if ((magic_number == FLIC_FILE_MAGIC_2) ||

               (magic_number == FLIC_FILE_MAGIC_3)) {

        /*

         * in this case, the speed (n) is number of milliseconds between frames:

         *

         *    pts        n * frame #

         *  --------  =  -----------  => pts = n * 90 * frame #

         *   90000          1000

         *

         *  therefore, the frame pts increment = n * 90

         */

        flic->frame_pts_inc = speed * 90;

    } else {

        av_log(s, AV_LOG_INFO, "Invalid or unsupported magic chunk in file\n");

        return AVERROR_INVALIDDATA;

    }



    if (flic->frame_pts_inc == 0)

        flic->frame_pts_inc = FLIC_DEFAULT_PTS_INC;



    return 0;

}

int ff_wma_init(AVCodecContext * avctx, int flags2)
{
    WMACodecContext *s = avctx->priv_data;
    int i;
    float *window;
    float bps1, high_freq;
    volatile float bps;
    int sample_rate1;
    int coef_vlc_table;
    s->sample_rate = avctx->sample_rate;
    s->nb_channels = avctx->channels;
    s->bit_rate = avctx->bit_rate;
    s->block_align = avctx->block_align;
    dsputil_init(&s->dsp, avctx);
    if (avctx->codec->id == CODEC_ID_WMAV1) {
        s->version = 1;
    } else {
        s->version = 2;
    }
    /* compute MDCT block size */
    if (s->sample_rate <= 16000) {
        s->frame_len_bits = 9;
    } else if (s->sample_rate <= 22050 ||
               (s->sample_rate <= 32000 && s->version == 1)) {
        s->frame_len_bits = 10;
    } else {
        s->frame_len_bits = 11;
    }
    s->frame_len = 1 << s->frame_len_bits;
    if (s->use_variable_block_len) {
        int nb_max, nb;
        nb = ((flags2 >> 3) & 3) + 1;
        if ((s->bit_rate / s->nb_channels) >= 32000)
            nb += 2;
        nb_max = s->frame_len_bits - BLOCK_MIN_BITS;
        if (nb > nb_max)
            nb = nb_max;
        s->nb_block_sizes = nb + 1;
    } else {
        s->nb_block_sizes = 1;
    }
    /* init rate dependent parameters */
    s->use_noise_coding = 1;
    high_freq = s->sample_rate * 0.5;
    /* if version 2, then the rates are normalized */
    sample_rate1 = s->sample_rate;
    if (s->version == 2) {
        if (sample_rate1 >= 44100)
            sample_rate1 = 44100;
        else if (sample_rate1 >= 22050)
            sample_rate1 = 22050;
        else if (sample_rate1 >= 16000)
            sample_rate1 = 16000;
        else if (sample_rate1 >= 11025)
            sample_rate1 = 11025;
        else if (sample_rate1 >= 8000)
            sample_rate1 = 8000;
    }
    bps = (float)s->bit_rate / (float)(s->nb_channels * s->sample_rate);
    s->byte_offset_bits = av_log2((int)(bps * s->frame_len / 8.0 + 0.5)) + 2;
    /* compute high frequency value and choose if noise coding should
       be activated */
    bps1 = bps;
    if (s->nb_channels == 2)
        bps1 = bps * 1.6;
    if (sample_rate1 == 44100) {
        if (bps1 >= 0.61)
            s->use_noise_coding = 0;
        else
            high_freq = high_freq * 0.4;
    } else if (sample_rate1 == 22050) {
        if (bps1 >= 1.16)
            s->use_noise_coding = 0;
        else if (bps1 >= 0.72)
            high_freq = high_freq * 0.7;
        else
            high_freq = high_freq * 0.6;
    } else if (sample_rate1 == 16000) {
        if (bps > 0.5)
            high_freq = high_freq * 0.5;
        else
            high_freq = high_freq * 0.3;
    } else if (sample_rate1 == 11025) {
        high_freq = high_freq * 0.7;
    } else if (sample_rate1 == 8000) {
        if (bps <= 0.625) {
            high_freq = high_freq * 0.5;
        } else if (bps > 0.75) {
            s->use_noise_coding = 0;
        } else {
            high_freq = high_freq * 0.65;
        }
    } else {
        if (bps >= 0.8) {
            high_freq = high_freq * 0.75;
        } else if (bps >= 0.6) {
            high_freq = high_freq * 0.6;
        } else {
            high_freq = high_freq * 0.5;
        }
    }
    dprintf(s->avctx, "flags2=0x%x\n", flags2);
    dprintf(s->avctx, "version=%d channels=%d sample_rate=%d bitrate=%d block_align=%d\n",
           s->version, s->nb_channels, s->sample_rate, s->bit_rate,
           s->block_align);
    dprintf(s->avctx, "bps=%f bps1=%f high_freq=%f bitoffset=%d\n",
           bps, bps1, high_freq, s->byte_offset_bits);
    dprintf(s->avctx, "use_noise_coding=%d use_exp_vlc=%d nb_block_sizes=%d\n",
           s->use_noise_coding, s->use_exp_vlc, s->nb_block_sizes);
    /* compute the scale factor band sizes for each MDCT block size */
    {
        int a, b, pos, lpos, k, block_len, i, j, n;
        const uint8_t *table;
        if (s->version == 1) {
            s->coefs_start = 3;
        } else {
            s->coefs_start = 0;
        }
        for(k = 0; k < s->nb_block_sizes; k++) {
            block_len = s->frame_len >> k;
            if (s->version == 1) {
                lpos = 0;
                for(i=0;i<25;i++) {
                    a = wma_critical_freqs[i];
                    b = s->sample_rate;
                    pos = ((block_len * 2 * a)  + (b >> 1)) / b;
                    if (pos > block_len)
                        pos = block_len;
                    s->exponent_bands[0][i] = pos - lpos;
                    if (pos >= block_len) {
                        i++;
                        break;
                    }
                    lpos = pos;
                }
                s->exponent_sizes[0] = i;
            } else {
                /* hardcoded tables */
                table = NULL;
                a = s->frame_len_bits - BLOCK_MIN_BITS - k;
                if (a < 3) {
                    if (s->sample_rate >= 44100)
                        table = exponent_band_44100[a];
                    else if (s->sample_rate >= 32000)
                        table = exponent_band_32000[a];
                    else if (s->sample_rate >= 22050)
                        table = exponent_band_22050[a];
                }
                if (table) {
                    n = *table++;
                    for(i=0;i<n;i++)
                        s->exponent_bands[k][i] = table[i];
                    s->exponent_sizes[k] = n;
                } else {
                    j = 0;
                    lpos = 0;
                    for(i=0;i<25;i++) {
                        a = wma_critical_freqs[i];
                        b = s->sample_rate;
                        pos = ((block_len * 2 * a)  + (b << 1)) / (4 * b);
                        pos <<= 2;
                        if (pos > block_len)
                            pos = block_len;
                        if (pos > lpos)
                            s->exponent_bands[k][j++] = pos - lpos;
                        if (pos >= block_len)
                            break;
                        lpos = pos;
                    }
                    s->exponent_sizes[k] = j;
                }
            }
            /* max number of coefs */
            s->coefs_end[k] = (s->frame_len - ((s->frame_len * 9) / 100)) >> k;
            /* high freq computation */
            s->high_band_start[k] = (int)((block_len * 2 * high_freq) /
                                          s->sample_rate + 0.5);
            n = s->exponent_sizes[k];
            j = 0;
            pos = 0;
            for(i=0;i<n;i++) {
                int start, end;
                start = pos;
                pos += s->exponent_bands[k][i];
                end = pos;
                if (start < s->high_band_start[k])
                    start = s->high_band_start[k];
                if (end > s->coefs_end[k])
                    end = s->coefs_end[k];
                if (end > start)
                    s->exponent_high_bands[k][j++] = end - start;
            }
            s->exponent_high_sizes[k] = j;
#if 0
            tprintf(s->avctx, "%5d: coefs_end=%d high_band_start=%d nb_high_bands=%d: ",
                  s->frame_len >> k,
                  s->coefs_end[k],
                  s->high_band_start[k],
                  s->exponent_high_sizes[k]);
            for(j=0;j<s->exponent_high_sizes[k];j++)
                tprintf(s->avctx, " %d", s->exponent_high_bands[k][j]);
            tprintf(s->avctx, "\n");
#endif
        }
    }
#ifdef TRACE
    {
        int i, j;
        for(i = 0; i < s->nb_block_sizes; i++) {
            tprintf(s->avctx, "%5d: n=%2d:",
                   s->frame_len >> i,
                   s->exponent_sizes[i]);
            for(j=0;j<s->exponent_sizes[i];j++)
                tprintf(s->avctx, " %d", s->exponent_bands[i][j]);
            tprintf(s->avctx, "\n");
        }
    }
#endif
    /* init MDCT windows : simple sinus window */
    for(i = 0; i < s->nb_block_sizes; i++) {
        int n, j;
        float alpha;
        n = 1 << (s->frame_len_bits - i);
        window = av_malloc(sizeof(float) * n);
        alpha = M_PI / (2.0 * n);
        for(j=0;j<n;j++) {
            window[j] = sin((j + 0.5) * alpha);
        }
        s->windows[i] = window;
    }
    s->reset_block_lengths = 1;
    if (s->use_noise_coding) {
        /* init the noise generator */
        if (s->use_exp_vlc)
            s->noise_mult = 0.02;
        else
            s->noise_mult = 0.04;
#ifdef TRACE
        for(i=0;i<NOISE_TAB_SIZE;i++)
            s->noise_table[i] = 1.0 * s->noise_mult;
#else
        {
            unsigned int seed;
            float norm;
            seed = 1;
            norm = (1.0 / (float)(1LL << 31)) * sqrt(3) * s->noise_mult;
            for(i=0;i<NOISE_TAB_SIZE;i++) {
                seed = seed * 314159 + 1;
                s->noise_table[i] = (float)((int)seed) * norm;
            }
        }
#endif
    }
    /* choose the VLC tables for the coefficients */
    coef_vlc_table = 2;
    if (s->sample_rate >= 32000) {
        if (bps1 < 0.72)
            coef_vlc_table = 0;
        else if (bps1 < 1.16)
            coef_vlc_table = 1;
    }
    s->coef_vlcs[0]= &coef_vlcs[coef_vlc_table * 2    ];
    s->coef_vlcs[1]= &coef_vlcs[coef_vlc_table * 2 + 1];
    init_coef_vlc(&s->coef_vlc[0], &s->run_table[0], &s->level_table[0], &s->int_table[0],
                  s->coef_vlcs[0]);
    init_coef_vlc(&s->coef_vlc[1], &s->run_table[1], &s->level_table[1], &s->int_table[1],
                  s->coef_vlcs[1]);
    return 0;
}

static int wma_decode_init(AVCodecContext * avctx)

{

