static void flush_packet(AVFormatContext *ctx, int stream_index, 

                         int64_t pts, int64_t dts, int64_t scr)

{

    MpegMuxContext *s = ctx->priv_data;

    StreamInfo *stream = ctx->streams[stream_index]->priv_data;

    uint8_t *buf_ptr;

    int size, payload_size, startcode, id, len, stuffing_size, i, header_len;

    uint8_t buffer[128];



    id = stream->id;



#if 0

    printf("packet ID=%2x PTS=%0.3f\n", 

           id, pts / 90000.0);

#endif



    buf_ptr = buffer;

    if (((s->packet_number % s->pack_header_freq) == 0)) {

        /* output pack and systems header if needed */

        size = put_pack_header(ctx, buf_ptr, scr);

        buf_ptr += size;

        if ((s->packet_number % s->system_header_freq) == 0) {

            size = put_system_header(ctx, buf_ptr);

            buf_ptr += size;

        }

    }

    size = buf_ptr - buffer;

    put_buffer(&ctx->pb, buffer, size);



    /* packet header */

    if (s->is_mpeg2) {

        header_len = 3;

    } else {

        header_len = 0;

    }

    if (pts != AV_NOPTS_VALUE) {

        if (dts != AV_NOPTS_VALUE)

            header_len += 5 + 5;

        else

            header_len += 5;

    } else {

        if (!s->is_mpeg2)

            header_len++;

    }



    payload_size = s->packet_size - (size + 6 + header_len);

    if (id < 0xc0) {

        startcode = PRIVATE_STREAM_1;

        payload_size -= 4;

    } else {

        startcode = 0x100 + id;

    }

    stuffing_size = payload_size - stream->buffer_ptr;

    if (stuffing_size < 0)

        stuffing_size = 0;



    put_be32(&ctx->pb, startcode);



    put_be16(&ctx->pb, payload_size + header_len);

    /* stuffing */

    for(i=0;i<stuffing_size;i++)

        put_byte(&ctx->pb, 0xff);



    if (s->is_mpeg2) {

        put_byte(&ctx->pb, 0x80); /* mpeg2 id */



        if (pts != AV_NOPTS_VALUE) {

            if (dts != AV_NOPTS_VALUE) {

                put_byte(&ctx->pb, 0xc0); /* flags */

                put_byte(&ctx->pb, header_len - 3);

                put_timestamp(&ctx->pb, 0x03, pts);

                put_timestamp(&ctx->pb, 0x01, dts);

            } else {

                put_byte(&ctx->pb, 0x80); /* flags */

                put_byte(&ctx->pb, header_len - 3);

                put_timestamp(&ctx->pb, 0x02, pts);

            }

        } else {

            put_byte(&ctx->pb, 0x00); /* flags */

            put_byte(&ctx->pb, header_len - 3);

        }

    } else {

        if (pts != AV_NOPTS_VALUE) {

            if (dts != AV_NOPTS_VALUE) {

                put_timestamp(&ctx->pb, 0x03, pts);

                put_timestamp(&ctx->pb, 0x01, dts);

            } else {

                put_timestamp(&ctx->pb, 0x02, pts);

            }

        } else {

            put_byte(&ctx->pb, 0x0f);

        }

    }



    if (startcode == PRIVATE_STREAM_1) {

        put_byte(&ctx->pb, id);

        if (id >= 0x80 && id <= 0xbf) {

            /* XXX: need to check AC3 spec */

            put_byte(&ctx->pb, 1);

            put_byte(&ctx->pb, 0);

            put_byte(&ctx->pb, 2);

        }

    }



    /* output data */

    put_buffer(&ctx->pb, stream->buffer, payload_size - stuffing_size);

    put_flush_packet(&ctx->pb);



    /* preserve remaining data */

    len = stream->buffer_ptr - payload_size;

    if (len < 0) 

        len = 0;

    memmove(stream->buffer, stream->buffer + stream->buffer_ptr - len, len);

    stream->buffer_ptr = len;



    s->packet_number++;

    stream->packet_number++;

}

static int mpeg_mux_write_packet(AVFormatContext *ctx, AVPacket *pkt)

{

    int stream_index = pkt->stream_index;

    int size         = pkt->size;

    uint8_t *buf     = pkt->data;

    MpegMuxContext *s = ctx->priv_data;

    AVStream *st      = ctx->streams[stream_index];

    StreamInfo *stream = st->priv_data;

    int64_t pts, dts;

    PacketDesc *pkt_desc;

    int preload;

    const int is_iframe = st->codecpar->codec_type == AVMEDIA_TYPE_VIDEO &&

                          (pkt->flags & AV_PKT_FLAG_KEY);



    preload = av_rescale(s->preload, 90000, AV_TIME_BASE);



    pts = pkt->pts;

    dts = pkt->dts;



    if (s->last_scr == AV_NOPTS_VALUE) {

        if (dts == AV_NOPTS_VALUE || (dts < preload && ctx->avoid_negative_ts) || s->is_dvd) {

            if (dts != AV_NOPTS_VALUE)

                s->preload += av_rescale(-dts, AV_TIME_BASE, 90000);

            s->last_scr = 0;

        } else {

            s->last_scr = dts - preload;

            s->preload = 0;

        }

        preload = av_rescale(s->preload, 90000, AV_TIME_BASE);

        av_log(ctx, AV_LOG_DEBUG, "First SCR: %"PRId64" First DTS: %"PRId64"\n", s->last_scr, dts + preload);

    }



    if (dts != AV_NOPTS_VALUE) dts += preload;

    if (pts != AV_NOPTS_VALUE) pts += preload;



    av_log(ctx, AV_LOG_TRACE, "dts:%f pts:%f flags:%d stream:%d nopts:%d\n",

            dts / 90000.0, pts / 90000.0, pkt->flags,

            pkt->stream_index, pts != AV_NOPTS_VALUE);

    if (!stream->premux_packet)

        stream->next_packet = &stream->premux_packet;

    *stream->next_packet     =

    pkt_desc                 = av_mallocz(sizeof(PacketDesc));



    pkt_desc->pts            = pts;

    pkt_desc->dts            = dts;

    pkt_desc->unwritten_size =

    pkt_desc->size           = size;

    if (!stream->predecode_packet)

        stream->predecode_packet = pkt_desc;

    stream->next_packet = &pkt_desc->next;



    if (av_fifo_realloc2(stream->fifo, av_fifo_size(stream->fifo) + size) < 0)

        return -1;



    if (s->is_dvd) {

        // min VOBU length 0.4 seconds (mpucoder)

        if (is_iframe &&

            (s->packet_number == 0 ||

             (pts - stream->vobu_start_pts >= 36000))) {

            stream->bytes_to_iframe = av_fifo_size(stream->fifo);

            stream->align_iframe    = 1;

            stream->vobu_start_pts  = pts;

        }

    }



    av_fifo_generic_write(stream->fifo, buf, size, NULL);



    for (;;) {

        int ret = output_packet(ctx, 0);

        if (ret <= 0)

            return ret;

    }

}

static int mpeg_mux_write_packet(AVFormatContext *ctx, int stream_index,

                                 const uint8_t *buf, int size, int64_t pts)

{

    MpegMuxContext *s = ctx->priv_data;

    AVStream *st = ctx->streams[stream_index];

    StreamInfo *stream = st->priv_data;

    int len;



    while (size > 0) {

        /* set pts */

        if (stream->start_pts == -1) {

            stream->start_pts = pts;

        }

        len = s->packet_data_max_size - stream->buffer_ptr;

        if (len > size)

            len = size;

        memcpy(stream->buffer + stream->buffer_ptr, buf, len);

        stream->buffer_ptr += len;

        buf += len;

        size -= len;

        while (stream->buffer_ptr >= s->packet_data_max_size) {

            /* output the packet */

            if (stream->start_pts == -1)

                stream->start_pts = pts;

            flush_packet(ctx, stream_index, 0);

        }

    }

    return 0;

}

static int mpeg_mux_write_packet(AVFormatContext *ctx, AVPacket *pkt)

{

    MpegMuxContext *s = ctx->priv_data;

    int stream_index= pkt->stream_index;

    int size= pkt->size;

    uint8_t *buf= pkt->data;

    AVStream *st = ctx->streams[stream_index];

    StreamInfo *stream = st->priv_data;

    int64_t pts, dts, new_start_pts, new_start_dts;

    int len, avail_size;



    //XXX/FIXME this is and always was broken

//    compute_pts_dts(st, &pts, &dts, pkt->pts);



    pts= pkt->pts;

    dts= pkt->dts;



    if(s->is_svcd) {

        /* offset pts and dts slightly into the future to be able

           to do the compatibility fix below.*/

        pts = (pts + 2) & ((1LL << 33) - 1);

        dts = (dts + 2) & ((1LL << 33) - 1);



        if (stream->packet_number == 0 && dts == pts)

            /* For the very first packet we want to force the DTS to be included.

               This increases compatibility with lots of DVD players.

               Since the MPEG-2 standard mandates that DTS is only written when

               it is different from PTS we have to move it slightly into the past.*/

            dts = (dts - 2) & ((1LL << 33) - 1);

    }

    if(s->is_vcd) {

        /* We have to offset the PTS, so that it is consistent with the SCR.

           SCR starts at 36000, but the first two packs contain only padding

           and the first pack from the other stream, respectively, may also have

           been written before.

           So the real data starts at SCR 36000+3*1200. */

        pts = (pts + 36000 + 3600) & ((1LL << 33) - 1);

        dts = (dts + 36000 + 3600) & ((1LL << 33) - 1);

    }



#if 0

    update_scr(ctx,stream_index,pts);



    printf("%d: pts=%0.3f dts=%0.3f scr=%0.3f\n", 

           stream_index, 

           pts / 90000.0, 

           dts / 90000.0, 

           s->last_scr / 90000.0);

#endif



    /* we assume here that pts != AV_NOPTS_VALUE */

    new_start_pts = stream->start_pts;

    new_start_dts = stream->start_dts;



    if (stream->start_pts == AV_NOPTS_VALUE) {

        new_start_pts = pts;

        new_start_dts = dts;

    }

    avail_size = get_packet_payload_size(ctx, stream_index,

                                         new_start_pts, 

                                         new_start_dts);

    if (stream->buffer_ptr >= avail_size) {



        update_scr(ctx,stream_index,stream->start_pts);



        /* unlikely case: outputing the pts or dts increase the packet

           size so that we cannot write the start of the next

           packet. In this case, we must flush the current packet with

           padding.

           Note: this always happens for the first audio and video packet

           in a VCD file, since they do not carry any data.*/

        flush_packet(ctx, stream_index,

                     stream->start_pts, stream->start_dts, s->last_scr);

        stream->buffer_ptr = 0;

    }

    stream->start_pts = new_start_pts;

    stream->start_dts = new_start_dts;

    stream->nb_frames++;

    if (stream->frame_start_offset == 0)

        stream->frame_start_offset = stream->buffer_ptr;

    while (size > 0) {

        avail_size = get_packet_payload_size(ctx, stream_index,

                                             stream->start_pts, 

                                             stream->start_dts);

        len = avail_size - stream->buffer_ptr;

        if (len > size)

            len = size;

        memcpy(stream->buffer + stream->buffer_ptr, buf, len);

        stream->buffer_ptr += len;

        buf += len;

        size -= len;

        if (stream->buffer_ptr >= avail_size) {



            update_scr(ctx,stream_index,stream->start_pts);



            /* if packet full, we send it now */

            flush_packet(ctx, stream_index,

                         stream->start_pts, stream->start_dts, s->last_scr);

            stream->buffer_ptr = 0;



            if (s->is_vcd) {

                /* Write one or more padding sectors, if necessary, to reach

                   the constant overall bitrate.*/

                int vcd_pad_bytes;



                while((vcd_pad_bytes = get_vcd_padding_size(ctx,stream->start_pts) ) >= s->packet_size)

                    put_vcd_padding_sector(ctx);

            }



            /* Make sure only the FIRST pes packet for this frame has

               a timestamp */

            stream->start_pts = AV_NOPTS_VALUE;

            stream->start_dts = AV_NOPTS_VALUE;

        }

    }



    return 0;

}

SPARCCPU *sparc64_cpu_devinit(const char *cpu_model,

                              const char *default_cpu_model, uint64_t prom_addr)

{

    SPARCCPU *cpu;

    CPUSPARCState *env;

    ResetData *reset_info;



    uint32_t   tick_frequency = 100 * 1000000;

    uint32_t  stick_frequency = 100 * 1000000;

    uint32_t hstick_frequency = 100 * 1000000;



    if (cpu_model == NULL) {

        cpu_model = default_cpu_model;

    }

    cpu = SPARC_CPU(cpu_generic_init(TYPE_SPARC_CPU, cpu_model));

    if (cpu == NULL) {

        fprintf(stderr, "Unable to find Sparc CPU definition\n");

        exit(1);

    }

    env = &cpu->env;



    env->tick = cpu_timer_create("tick", cpu, tick_irq,

                                  tick_frequency, TICK_INT_DIS,

                                  TICK_NPT_MASK);



    env->stick = cpu_timer_create("stick", cpu, stick_irq,

                                   stick_frequency, TICK_INT_DIS,

                                   TICK_NPT_MASK);



    env->hstick = cpu_timer_create("hstick", cpu, hstick_irq,

                                    hstick_frequency, TICK_INT_DIS,

                                    TICK_NPT_MASK);



    reset_info = g_malloc0(sizeof(ResetData));

    reset_info->cpu = cpu;

    reset_info->prom_addr = prom_addr;

    qemu_register_reset(main_cpu_reset, reset_info);



    return cpu;

}

