static int read_mv_component(VP56RangeCoder *c, const uint8_t *p)

{

    int bit, x = 0;



    if (vp56_rac_get_prob_branchy(c, p[0])) {

        int i;



        for (i = 0; i < 3; i++)

            x += vp56_rac_get_prob(c, p[9 + i]) << i;

        for (i = 9; i > 3; i--)

            x += vp56_rac_get_prob(c, p[9 + i]) << i;

        if (!(x & 0xFFF0) || vp56_rac_get_prob(c, p[12]))

            x += 8;

    } else {

        // small_mvtree

        const uint8_t *ps = p + 2;

        bit = vp56_rac_get_prob(c, *ps);

        ps += 1 + 3 * bit;

        x  += 4 * bit;

        bit = vp56_rac_get_prob(c, *ps);

        ps += 1 + bit;

        x  += 2 * bit;

        x  += vp56_rac_get_prob(c, *ps);

    }



    return (x && vp56_rac_get_prob(c, p[1])) ? -x : x;

}

static void machine_set_loadparm(Object *obj, const char *val, Error **errp)

{

    S390CcwMachineState *ms = S390_CCW_MACHINE(obj);

    int i;



    for (i = 0; i < sizeof(ms->loadparm) && val[i]; i++) {

        uint8_t c = toupper(val[i]); /* mimic HMC */



        if (('A' <= c && c <= 'Z') || ('0' <= c && c <= '9') || (c == '.') ||

            (c == ' ')) {

            ms->loadparm[i] = c;

        } else {

            error_setg(errp, "LOADPARM: invalid character '%c' (ASCII 0x%02x)",

                       c, c);

            return;

        }

    }



    for (; i < sizeof(ms->loadparm); i++) {

        ms->loadparm[i] = ' '; /* pad right with spaces */

    }

}

static int compare_sectors(const uint8_t *buf1, const uint8_t *buf2, int n,

    int *pnum)

{

    bool res;

    int i;



    if (n <= 0) {

        *pnum = 0;

        return 0;

    }



    res = !!memcmp(buf1, buf2, 512);

    for(i = 1; i < n; i++) {

        buf1 += 512;

        buf2 += 512;



        if (!!memcmp(buf1, buf2, 512) != res) {

            break;

        }

    }



    *pnum = i;

    return res;

}

static int is_allocated_sectors(const uint8_t *buf, int n, int *pnum)

{

    int v, i;



    if (n <= 0) {

        *pnum = 0;

        return 0;

    }

    v = is_not_zero(buf, 512);

    for(i = 1; i < n; i++) {

        buf += 512;

        if (v != is_not_zero(buf, 512))

            break;

    }

    *pnum = i;

    return v;

}

static int decode_p_picture_primary_header(VC9Context *v)

{

    /* INTERFRM, FRMCNT, RANGEREDFRM read in caller */

    GetBitContext *gb = &v->s.gb;

    int lowquant, pqindex, status = 0;



    pqindex = get_bits(gb, 5);

    if (v->quantizer_mode == QUANT_FRAME_IMPLICIT)

        v->pq = pquant_table[0][pqindex];

    else

    {

        v->pq = pquant_table[v->quantizer_mode-1][pqindex];

    }

    if (pqindex < 9) v->halfpq = get_bits(gb, 1);

    if (v->quantizer_mode == QUANT_FRAME_EXPLICIT)

        v->pquantizer = get_bits(gb, 1);

    av_log(v->s.avctx, AV_LOG_DEBUG, "P Frame: QP=%i (+%i/2)\n",

           v->pq, v->halfpq);

    if (v->extended_mv == 1) v->mvrange = get_prefix(gb, 0, 3);

#if HAS_ADVANCED_PROFILE

    if (v->profile > PROFILE_MAIN)

    {

        if (v->postprocflag) v->postproc = get_bits(gb, 1);

    }

    else

#endif

        if (v->multires) v->respic = get_bits(gb, 2);

    lowquant = (v->pquantizer>12) ? 0 : 1;

    v->mv_mode = mv_pmode_table[lowquant][get_prefix(gb, 1, 4)];

    if (v->mv_mode == MV_PMODE_INTENSITY_COMP)

    {

        v->mv_mode2 = mv_pmode_table[lowquant][get_prefix(gb, 1, 3)];

        v->lumscale = get_bits(gb, 6);

        v->lumshift = get_bits(gb, 6);

    }

    return 0;

}

static int decode_b_picture_primary_header(VC9Context *v)

{

    GetBitContext *gb = &v->s.gb;

    int pqindex;



    /* Prolog common to all frametypes should be done in caller */

    if (v->profile == PROFILE_SIMPLE)

    {

        av_log(v->s.avctx, AV_LOG_ERROR, "Found a B frame while in Simple Profile!\n");

        return FRAME_SKIPED;

    }

    v->bfraction = vc9_bfraction_lut[get_vlc2(gb, vc9_bfraction_vlc.table,

                                              VC9_BFRACTION_VLC_BITS, 2)];

    if (v->bfraction < -1)

    {

        av_log(v->s.avctx, AV_LOG_ERROR, "Invalid BFRaction\n");

        return FRAME_SKIPED;

    }

    else if (!v->bfraction)

    {

        /* We actually have a BI frame */

        v->s.pict_type = BI_TYPE;

        v->buffer_fullness = get_bits(gb, 7);

    }



    /* Read the quantization stuff */

    pqindex = get_bits(gb, 5);

    if (v->quantizer_mode == QUANT_FRAME_IMPLICIT)

        v->pq = pquant_table[0][pqindex];

    else

    {

        v->pq = pquant_table[v->quantizer_mode-1][pqindex];

    }

    if (pqindex < 9) v->halfpq = get_bits(gb, 1);

    if (v->quantizer_mode == QUANT_FRAME_EXPLICIT)

        v->pquantizer = get_bits(gb, 1);



    if (v->profile > PROFILE_MAIN)

    {

        if (v->postprocflag) v->postproc = get_bits(gb, 2);

        if (v->extended_mv == 1 && v->s.pict_type != BI_TYPE)

            v->mvrange = get_prefix(gb, 0, 3);

    }

    else

    {

        if (v->extended_mv == 1)

            v->mvrange = get_prefix(gb, 0, 3);

    }

    /* Read the MV mode */

    if (v->s.pict_type != BI_TYPE)

    {

        v->mv_mode = get_bits(gb, 1);

        if (v->pq < 13)

        {

            if (!v->mv_mode)

            {

                v->mv_mode = get_bits(gb, 2);

                if (v->mv_mode)

                av_log(v->s.avctx, AV_LOG_ERROR,

                       "mv_mode for lowquant B frame was %i\n", v->mv_mode);

            }

        }

        else

        {

            if (!v->mv_mode)

            {

                if (get_bits(gb, 1))

                     av_log(v->s.avctx, AV_LOG_ERROR,

                            "mv_mode for highquant B frame was %i\n", v->mv_mode);

            }

            v->mv_mode = 1-v->mv_mode; //To match (pq < 13) mapping

        }

    }



    return 0;

}

static int decode_p_picture_header(VC9Context *v)

{

    /* INTERFRM, FRMCNT, RANGEREDFRM read in caller */

    int lowquant, pqindex;



    pqindex = get_bits(&v->gb, 5);

    if (v->quantizer_mode == QUANT_FRAME_IMPLICIT)

        v->pq = pquant_table[0][pqindex];

    else

    {

        v->pq = pquant_table[v->quantizer_mode-1][pqindex];

    }

    if (pqindex < 9) v->halfpq = get_bits(&v->gb, 1);

    if (v->quantizer_mode == QUANT_FRAME_EXPLICIT)

        v->pquantizer = get_bits(&v->gb, 1);

    av_log(v->avctx, AV_LOG_DEBUG, "P Frame: QP=%i (+%i/2)\n",

           v->pq, v->halfpq);

    if (v->extended_mv == 1) v->mvrange = get_prefix(&v->gb, 0, 3);

#if HAS_ADVANCED_PROFILE

    if (v->profile > PROFILE_MAIN)

    {

        if (v->postprocflag) v->postproc = get_bits(&v->gb, 1);

    }

    else

#endif

        if (v->multires) v->respic = get_bits(&v->gb, 2);

    lowquant = (v->pquantizer>12) ? 0 : 1;

    v->mv_mode = mv_pmode_table[lowquant][get_prefix(&v->gb, 1, 4)];

    if (v->mv_mode == MV_PMODE_INTENSITY_COMP)

    {

        v->mv_mode2 = mv_pmode_table[lowquant][get_prefix(&v->gb, 1, 3)];

        v->lumscale = get_bits(&v->gb, 6);

        v->lumshift = get_bits(&v->gb, 6);

    }



    if ((v->mv_mode == MV_PMODE_INTENSITY_COMP &&

         v->mv_mode2 == MV_PMODE_MIXED_MV)

        || v->mv_mode == MV_PMODE_MIXED_MV)

    {

        if (bitplane_decoding(v->mv_type_mb_plane, v->width_mb,

                                  v->height_mb, v) < 0)

            return -1;

    }



    if (bitplane_decoding(v->skip_mb_plane, v->width_mb,

                              v->height_mb, v) < 0)

        return -1;



    /* Hopefully this is correct for P frames */

    v->mv_diff_vlc = &vc9_mv_diff_vlc[get_bits(&v->gb, 2)];

    v->cbpcy_vlc = &vc9_cbpcy_p_vlc[get_bits(&v->gb, 2)];



    if (v->dquant)

    {

        av_log(v->avctx, AV_LOG_INFO, "VOP DQuant info\n");

        vop_dquant_decoding(v);

    }



    if (v->vstransform)

    {

        v->ttmbf = get_bits(&v->gb, 1);

        if (v->ttmbf)

        {

            v->ttfrm = get_bits(&v->gb, 2);

            av_log(v->avctx, AV_LOG_INFO, "Transform used: %ix%i\n",

                   (v->ttfrm & 2) ? 4 : 8, (v->ttfrm & 1) ? 4 : 8);

        }

    }

    /* Epilog should be done in caller */

    return 0;

}

static int decode_sequence_header(AVCodecContext *avctx, GetBitContext *gb)

{

    VC9Context *v = avctx->priv_data;



    v->profile = get_bits(gb, 2);

    av_log(avctx, AV_LOG_DEBUG, "Profile: %i\n", v->profile);



#if HAS_ADVANCED_PROFILE

    if (v->profile > PROFILE_MAIN)

    {

        v->level = get_bits(gb, 3);

        v->chromaformat = get_bits(gb, 2);

        if (v->chromaformat != 1)

        {

            av_log(avctx, AV_LOG_ERROR,

                   "Only 4:2:0 chroma format supported\n");

            return -1;

        }

    }

    else

#endif

    {

        v->res_sm = get_bits(gb, 2); //reserved

        if (v->res_sm)

        {

            av_log(avctx, AV_LOG_ERROR,

                   "Reserved RES_SM=%i is forbidden\n", v->res_sm);

            //return -1;

        }

    }



    // (fps-2)/4 (->30)

    v->frmrtq_postproc = get_bits(gb, 3); //common

    // (bitrate-32kbps)/64kbps

    v->bitrtq_postproc = get_bits(gb, 5); //common

    v->loopfilter = get_bits(gb, 1); //common



#if HAS_ADVANCED_PROFILE

    if (v->profile <= PROFILE_MAIN)

#endif

    {

        v->res_x8 = get_bits(gb, 1); //reserved

        if (v->res_x8)

        {

            av_log(avctx, AV_LOG_ERROR,

                   "1 for reserved RES_X8 is forbidden\n");

            return -1;

        }

        v->multires = get_bits(gb, 1);

        v->res_fasttx = get_bits(gb, 1);

        if (!v->res_fasttx)

        {

            av_log(avctx, AV_LOG_ERROR,

                   "0 for reserved RES_FASTTX is forbidden\n");

            //return -1;

        }

    }



    v->fastuvmc =  get_bits(gb, 1); //common

    if (!v->profile && !v->fastuvmc)

    {

        av_log(avctx, AV_LOG_ERROR,

               "FASTUVMC unavailable in Simple Profile\n");

        return -1;

    }

    v->extended_mv =  get_bits(gb, 1); //common

    if (!v->profile && v->extended_mv)

    {

        av_log(avctx, AV_LOG_ERROR,

               "Extended MVs unavailable in Simple Profile\n");

        return -1;

    }

    v->dquant =  get_bits(gb, 2); //common

    v->vstransform =  get_bits(gb, 1); //common



#if HAS_ADVANCED_PROFILE

    if (v->profile <= PROFILE_MAIN)

#endif

    {

        v->res_transtab = get_bits(gb, 1);

        if (v->res_transtab)

        {

            av_log(avctx, AV_LOG_ERROR,

                   "1 for reserved RES_TRANSTAB is forbidden\n");

            return -1;

        }

    }



    v->overlap = get_bits(gb, 1); //common



#if HAS_ADVANCED_PROFILE

    if (v->profile <= PROFILE_MAIN)

#endif

    {

        v->syncmarker = get_bits(gb, 1);

        v->rangered = get_bits(gb, 1);

    }



    avctx->max_b_frames = get_bits(gb, 3); //common

    v->quantizer_mode = get_bits(gb, 2); //common



#if HAS_ADVANCED_PROFILE

    if (v->profile <= PROFILE_MAIN)

#endif

    {

        v->finterpflag = get_bits(gb, 1); //common

        v->res_rtm_flag = get_bits(gb, 1); //reserved

        if (!v->res_rtm_flag)

        {

            av_log(avctx, AV_LOG_ERROR,

                   "0 for reserved RES_RTM_FLAG is forbidden\n");

            //return -1;

        }

#if TRACE

        av_log(avctx, AV_LOG_INFO,

               "Profile %i:\nfrmrtq_postproc=%i, bitrtq_postproc=%i\n"

               "LoopFilter=%i, MultiRes=%i, FastUVMV=%i, Extended MV=%i\n"

               "Rangered=%i, VSTransform=%i, Overlap=%i, SyncMarker=%i\n"

               "DQuant=%i, Quantizer mode=%i, Max B frames=%i\n",

               v->profile, v->frmrtq_postproc, v->bitrtq_postproc,

               v->loopfilter, v->multires, v->fastuvmc, v->extended_mv,

               v->rangered, v->vstransform, v->overlap, v->syncmarker,

               v->dquant, v->quantizer_mode, avctx->max_b_frames

               );

#endif

    }

#if HAS_ADVANCED_PROFILE

    else decode_advanced_sequence_header(avctx, gb);

#endif

}

static void show_stream(AVFormatContext *fmt_ctx, int stream_idx)

{

    AVStream *stream = fmt_ctx->streams[stream_idx];

    AVCodecContext *dec_ctx;

    AVCodec *dec;

    const char *profile;

    char val_str[128];

    AVRational display_aspect_ratio;



    probe_object_header("stream");



    probe_int("index", stream->index);



    if ((dec_ctx = stream->codec)) {

        if ((dec = dec_ctx->codec)) {

            probe_str("codec_name", dec->name);

            probe_str("codec_long_name", dec->long_name);

        } else {

            probe_str("codec_name", "unknown");

        }



        probe_str("codec_type", media_type_string(dec_ctx->codec_type));

        probe_str("codec_time_base",

                  rational_string(val_str, sizeof(val_str),

                                  "/", &dec_ctx->time_base));



        /* print AVI/FourCC tag */

        av_get_codec_tag_string(val_str, sizeof(val_str), dec_ctx->codec_tag);

        probe_str("codec_tag_string", val_str);

        probe_str("codec_tag", tag_string(val_str, sizeof(val_str),

                                          dec_ctx->codec_tag));



        /* print profile, if there is one */

        if (dec && (profile = av_get_profile_name(dec, dec_ctx->profile)))

            probe_str("profile", profile);



        switch (dec_ctx->codec_type) {

        case AVMEDIA_TYPE_VIDEO:

            probe_int("width", dec_ctx->width);

            probe_int("height", dec_ctx->height);

            probe_int("has_b_frames", dec_ctx->has_b_frames);

            if (dec_ctx->sample_aspect_ratio.num) {

                probe_str("sample_aspect_ratio",

                          rational_string(val_str, sizeof(val_str), ":",

                          &dec_ctx->sample_aspect_ratio));

                av_reduce(&display_aspect_ratio.num, &display_aspect_ratio.den,

                          dec_ctx->width  * dec_ctx->sample_aspect_ratio.num,

