        error_report("scsi-disk: drive property not set");
    s->bs = s->qdev.conf.bs;
    is_cd = bdrv_get_type_hint(s->bs) == BDRV_TYPE_CDROM;
    if (bdrv_get_on_error(s->bs, 1) != BLOCK_ERR_REPORT) {
        error_report("Device doesn't support drive option rerror");
    if (!s->serial) {
        /* try to fall back to value set with legacy -drive serial=... */
        dinfo = drive_get_by_blockdev(s->bs);
        s->serial = qemu_strdup(*dinfo->serial ? dinfo->serial : "0");
    if (!s->version) {
        s->version = qemu_strdup(QEMU_VERSION);
    if (bdrv_is_sg(s->bs)) {
        error_report("scsi-disk: unwanted /dev/sg*");
    if (is_cd) {
        s->qdev.blocksize = 2048;
    } else {
        s->qdev.blocksize = s->qdev.conf.logical_block_size;
    s->cluster_size = s->qdev.blocksize / 512;
    s->qdev.type = TYPE_DISK;
    qemu_add_vm_change_state_handler(scsi_dma_restart_cb, s);
    bdrv_set_removable(s->bs, is_cd);
    return 0;

static void scsi_realize(SCSIDevice *dev, Error **errp)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, dev);

    Error *err = NULL;



    if (!s->qdev.conf.bs) {

        error_setg(errp, "drive property not set");

        return;

    }



    if (!(s->features & (1 << SCSI_DISK_F_REMOVABLE)) &&

        !bdrv_is_inserted(s->qdev.conf.bs)) {

        error_setg(errp, "Device needs media, but drive is empty");

        return;

    }



    blkconf_serial(&s->qdev.conf, &s->serial);

    if (dev->type == TYPE_DISK) {

        blkconf_geometry(&dev->conf, NULL, 65535, 255, 255, &err);

        if (err) {

            error_propagate(errp, err);

            return;

        }

    }



    if (s->qdev.conf.discard_granularity == -1) {

        s->qdev.conf.discard_granularity =

            MAX(s->qdev.conf.logical_block_size, DEFAULT_DISCARD_GRANULARITY);

    }



    if (!s->version) {

        s->version = g_strdup(qemu_get_version());

    }

    if (!s->vendor) {

        s->vendor = g_strdup("QEMU");

    }



    if (bdrv_is_sg(s->qdev.conf.bs)) {

        error_setg(errp, "unwanted /dev/sg*");

        return;

    }



    if ((s->features & (1 << SCSI_DISK_F_REMOVABLE)) &&

            !(s->features & (1 << SCSI_DISK_F_NO_REMOVABLE_DEVOPS))) {

        bdrv_set_dev_ops(s->qdev.conf.bs, &scsi_disk_removable_block_ops, s);

    } else {

        bdrv_set_dev_ops(s->qdev.conf.bs, &scsi_disk_block_ops, s);

    }

    bdrv_set_guest_block_size(s->qdev.conf.bs, s->qdev.blocksize);



    bdrv_iostatus_enable(s->qdev.conf.bs);

}

static int scsi_cd_initfn(SCSIDevice *dev)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, dev);

    s->qdev.blocksize = 2048;

    s->qdev.type = TYPE_ROM;

    s->features |= 1 << SCSI_DISK_F_REMOVABLE;

    if (!s->product) {

        s->product = g_strdup("QEMU CD-ROM");

    }

    return scsi_initfn(&s->qdev);

}

static int scsi_generic_initfn(SCSIDevice *s)

{

    int rc;

    int sg_version;

    struct sg_scsi_id scsiid;



    if (!s->conf.bs) {

        error_report("drive property not set");

        return -1;

    }



    if (bdrv_get_on_error(s->conf.bs, 0) != BLOCKDEV_ON_ERROR_ENOSPC) {

        error_report("Device doesn't support drive option werror");

        return -1;

    }

    if (bdrv_get_on_error(s->conf.bs, 1) != BLOCKDEV_ON_ERROR_REPORT) {

        error_report("Device doesn't support drive option rerror");

        return -1;

    }



    /* check we are using a driver managing SG_IO (version 3 and after */

    rc = bdrv_ioctl(s->conf.bs, SG_GET_VERSION_NUM, &sg_version);

    if (rc < 0) {

        error_report("cannot get SG_IO version number: %s.  "

                     "Is this a SCSI device?",

                     strerror(-rc));

        return -1;

    }

    if (sg_version < 30000) {

        error_report("scsi generic interface too old");

        return -1;

    }



    /* get LUN of the /dev/sg? */

    if (bdrv_ioctl(s->conf.bs, SG_GET_SCSI_ID, &scsiid)) {

        error_report("SG_GET_SCSI_ID ioctl failed");

        return -1;

    }



    /* define device state */

    s->type = scsiid.scsi_type;

    DPRINTF("device type %d\n", s->type);

    if (s->type == TYPE_DISK || s->type == TYPE_ROM) {

        add_boot_device_path(s->conf.bootindex, &s->qdev, NULL);

    }



    switch (s->type) {

    case TYPE_TAPE:

        s->blocksize = get_stream_blocksize(s->conf.bs);

        if (s->blocksize == -1) {

            s->blocksize = 0;

        }

        break;



        /* Make a guess for block devices, we'll fix it when the guest sends.

         * READ CAPACITY.  If they don't, they likely would assume these sizes

         * anyway. (TODO: they could also send MODE SENSE).

         */

    case TYPE_ROM:

    case TYPE_WORM:

        s->blocksize = 2048;

        break;

    default:

        s->blocksize = 512;

        break;

    }



    DPRINTF("block size %d\n", s->blocksize);

    return 0;

}

static void ehci_update_frindex(EHCIState *ehci, int uframes)

{

    int i;



    if (!ehci_enabled(ehci) && ehci->pstate == EST_INACTIVE) {

        return;

    }



    for (i = 0; i < uframes; i++) {

        ehci->frindex++;



        if (ehci->frindex == 0x00002000) {

            ehci_raise_irq(ehci, USBSTS_FLR);

        }



        if (ehci->frindex == 0x00004000) {

            ehci_raise_irq(ehci, USBSTS_FLR);

            ehci->frindex = 0;

            if (ehci->usbsts_frindex >= 0x00004000) {

                ehci->usbsts_frindex -= 0x00004000;

            } else {

                ehci->usbsts_frindex = 0;

            }

        }

    }

}

static void use_normal_update_speed(WmallDecodeCtx *s, int ich)

{

    int ilms, recent, icoef;

    s->update_speed[ich] = 8;

    for (ilms = s->cdlms_ttl[ich]; ilms >= 0; ilms--) {

        recent = s->cdlms[ich][ilms].recent;

        if (s->bV3RTM) {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef + recent] /= 2;

        } else {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef] /= 2;

        }

    }

}

static void raw_close_fd_pool(BDRVRawState *s)

{

    int i;



    for (i = 0; i < RAW_FD_POOL_SIZE; i++) {

        if (s->fd_pool[i] != -1) {

            close(s->fd_pool[i]);

            s->fd_pool[i] = -1;

        }

    }

}

static void release_unused_pictures(H264Context *h, int remove_current)

{

    int i;



    /* release non reference frames */

    for (i = 0; i < MAX_PICTURE_COUNT; i++) {

        if (h->DPB[i].f.data[0] && !h->DPB[i].reference &&

            (remove_current || &h->DPB[i] != h->cur_pic_ptr)) {

            unref_picture(h, &h->DPB[i]);

        }

    }

}

static const MXFCodecUL *mxf_get_essence_container_ul(enum CodecID type)

{

    const MXFCodecUL *uls = ff_mxf_essence_container_uls;

    while (uls->id != CODEC_ID_NONE) {

        if (uls->id == type)

            break;

