static int decode_pce(AACContext *ac, enum ChannelPosition new_che_pos[4][MAX_ELEM_ID],

                      GetBitContext *gb)

{

    int num_front, num_side, num_back, num_lfe, num_assoc_data, num_cc, sampling_index;



    skip_bits(gb, 2);  // object_type



    sampling_index = get_bits(gb, 4);

    if (ac->m4ac.sampling_index != sampling_index)

        av_log(ac->avccontext, AV_LOG_WARNING, "Sample rate index in program config element does not match the sample rate index configured by the container.\n");



    num_front       = get_bits(gb, 4);

    num_side        = get_bits(gb, 4);

    num_back        = get_bits(gb, 4);

    num_lfe         = get_bits(gb, 2);

    num_assoc_data  = get_bits(gb, 3);

    num_cc          = get_bits(gb, 4);



    if (get_bits1(gb))

        skip_bits(gb, 4); // mono_mixdown_tag

    if (get_bits1(gb))

        skip_bits(gb, 4); // stereo_mixdown_tag



    if (get_bits1(gb))

        skip_bits(gb, 3); // mixdown_coeff_index and pseudo_surround



    decode_channel_map(new_che_pos[TYPE_CPE], new_che_pos[TYPE_SCE], AAC_CHANNEL_FRONT, gb, num_front);

    decode_channel_map(new_che_pos[TYPE_CPE], new_che_pos[TYPE_SCE], AAC_CHANNEL_SIDE,  gb, num_side );

    decode_channel_map(new_che_pos[TYPE_CPE], new_che_pos[TYPE_SCE], AAC_CHANNEL_BACK,  gb, num_back );

    decode_channel_map(NULL,                  new_che_pos[TYPE_LFE], AAC_CHANNEL_LFE,   gb, num_lfe  );



    skip_bits_long(gb, 4 * num_assoc_data);



    decode_channel_map(new_che_pos[TYPE_CCE], new_che_pos[TYPE_CCE], AAC_CHANNEL_CC,    gb, num_cc   );



    align_get_bits(gb);



    /* comment field, first byte is length */

    skip_bits_long(gb, 8 * get_bits(gb, 8));

    return 0;

}

static int decode_cce(AACContext *ac, GetBitContext *gb, ChannelElement *che)

{

    int num_gain = 0;

    int c, g, sfb, ret;

    int sign;

    INTFLOAT scale;

    SingleChannelElement *sce = &che->ch[0];

    ChannelCoupling     *coup = &che->coup;



    coup->coupling_point = 2 * get_bits1(gb);

    coup->num_coupled = get_bits(gb, 3);

    for (c = 0; c <= coup->num_coupled; c++) {

        num_gain++;

        coup->type[c] = get_bits1(gb) ? TYPE_CPE : TYPE_SCE;

        coup->id_select[c] = get_bits(gb, 4);

        if (coup->type[c] == TYPE_CPE) {

            coup->ch_select[c] = get_bits(gb, 2);

            if (coup->ch_select[c] == 3)

                num_gain++;

        } else

            coup->ch_select[c] = 2;

    }

    coup->coupling_point += get_bits1(gb) || (coup->coupling_point >> 1);



    sign  = get_bits(gb, 1);

    scale = AAC_RENAME(cce_scale)[get_bits(gb, 2)];



    if ((ret = decode_ics(ac, sce, gb, 0, 0)))

        return ret;



    for (c = 0; c < num_gain; c++) {

        int idx  = 0;

        int cge  = 1;

        int gain = 0;

        INTFLOAT gain_cache = FIXR10(1.);

        if (c) {

            cge = coup->coupling_point == AFTER_IMDCT ? 1 : get_bits1(gb);

            gain = cge ? get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60: 0;

            gain_cache = GET_GAIN(scale, gain);

        }

        if (coup->coupling_point == AFTER_IMDCT) {

            coup->gain[c][0] = gain_cache;

        } else {

            for (g = 0; g < sce->ics.num_window_groups; g++) {

                for (sfb = 0; sfb < sce->ics.max_sfb; sfb++, idx++) {

                    if (sce->band_type[idx] != ZERO_BT) {

                        if (!cge) {

                            int t = get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60;

                            if (t) {

                                int s = 1;

                                t = gain += t;

                                if (sign) {

                                    s  -= 2 * (t & 0x1);

                                    t >>= 1;

                                }

                                gain_cache = GET_GAIN(scale, t) * s;

                            }

                        }

                        coup->gain[c][idx] = gain_cache;

                    }

                }

            }

        }

    }

    return 0;

}

static int decode_cce(AACContext * ac, GetBitContext * gb, ChannelElement * che) {

    int num_gain = 0;

    int c, g, sfb, ret, idx = 0;

    int sign;

    float scale;

    SingleChannelElement * sce = &che->ch[0];

    ChannelCoupling * coup     = &che->coup;



    coup->coupling_point = 2*get_bits1(gb);

    coup->num_coupled = get_bits(gb, 3);

    for (c = 0; c <= coup->num_coupled; c++) {

        num_gain++;

        coup->type[c] = get_bits1(gb) ? TYPE_CPE : TYPE_SCE;

        coup->id_select[c] = get_bits(gb, 4);

        if (coup->type[c] == TYPE_CPE) {

            coup->ch_select[c] = get_bits(gb, 2);

            if (coup->ch_select[c] == 3)

                num_gain++;

        } else

            coup->ch_select[c] = 1;

    }

    coup->coupling_point += get_bits1(gb);



    if (coup->coupling_point == 2) {

        av_log(ac->avccontext, AV_LOG_ERROR,

            "Independently switched CCE with 'invalid' domain signalled.\n");

        memset(coup, 0, sizeof(ChannelCoupling));

        return -1;

    }



    sign = get_bits(gb, 1);

    scale = pow(2., pow(2., (int)get_bits(gb, 2) - 3));



    if ((ret = decode_ics(ac, sce, gb, 0, 0)))

        return ret;



    for (c = 0; c < num_gain; c++) {

        int cge = 1;

        int gain = 0;

        float gain_cache = 1.;

        if (c) {

            cge = coup->coupling_point == AFTER_IMDCT ? 1 : get_bits1(gb);

            gain = cge ? get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60: 0;

            gain_cache = pow(scale, gain);

        }

        for (g = 0; g < sce->ics.num_window_groups; g++) {

            for (sfb = 0; sfb < sce->ics.max_sfb; sfb++, idx++) {

                if (sce->band_type[idx] != ZERO_BT) {

                    if (!cge) {

                        int t = get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60;

                        if (t) {

                            int s = 1;

                            if (sign) {

                                s  -= 2 * (t & 0x1);

                                t >>= 1;

                            }

                            gain += t;

                            gain_cache = pow(scale, gain) * s;

                        }

                    }

                    coup->gain[c][idx] = gain_cache;

                }

            }

        }

    }

    return 0;

}

static void apply_dependent_coupling(AACContext * ac, SingleChannelElement * target, ChannelElement * cce, int index) {

    IndividualChannelStream * ics = &cce->ch[0].ics;

    const uint16_t * offsets = ics->swb_offset;

    float * dest = target->coeffs;

    const float * src = cce->ch[0].coeffs;

    int g, i, group, k, idx = 0;

    if(ac->m4ac.object_type == AOT_AAC_LTP) {

        av_log(ac->avccontext, AV_LOG_ERROR,

               "Dependent coupling is not supported together with LTP\n");

        return;

    }

    for (g = 0; g < ics->num_window_groups; g++) {

        for (i = 0; i < ics->max_sfb; i++, idx++) {

            if (cce->ch[0].band_type[idx] != ZERO_BT) {

                for (group = 0; group < ics->group_len[g]; group++) {

                    for (k = offsets[i]; k < offsets[i+1]; k++) {

                        // XXX dsputil-ize

                        dest[group*128+k] += cce->coup.gain[index][idx] * src[group*128+k];

                    }

                }

            }

        }

        dest += ics->group_len[g]*128;

        src  += ics->group_len[g]*128;

    }

}

static void tcp_wait_for_connect(void *opaque)

{

    MigrationState *s = opaque;

    int val, ret;

    socklen_t valsize = sizeof(val);



    DPRINTF("connect completed\n");

    do {

        ret = getsockopt(s->fd, SOL_SOCKET, SO_ERROR, (void *) &val, &valsize);

    } while (ret == -1 && (socket_error()) == EINTR);



    if (ret < 0) {

        migrate_fd_error(s);

        return;

    }



    qemu_set_fd_handler2(s->fd, NULL, NULL, NULL, NULL);



    if (val == 0)

        migrate_fd_connect(s);

    else {

        DPRINTF("error connecting %d\n", val);

        migrate_fd_error(s);

    }

}

static void buffered_flush(QEMUFileBuffered *s)

{

    size_t offset = 0;

    int error;



    error = qemu_file_get_error(s->file);

    if (error != 0) {

        DPRINTF("flush when error, bailing: %s\n", strerror(-error));

        return;

    }



    DPRINTF("flushing %zu byte(s) of data\n", s->buffer_size);



    while (s->bytes_xfer < s->xfer_limit && offset < s->buffer_size) {

        ssize_t ret;



        ret = migrate_fd_put_buffer(s->migration_state, s->buffer + offset,

                                    s->buffer_size - offset);

        if (ret == -EAGAIN) {

            DPRINTF("backend not ready, freezing\n");

            s->freeze_output = 1;

            break;

        }



        if (ret <= 0) {

            DPRINTF("error flushing data, %zd\n", ret);

            qemu_file_set_error(s->file, ret);

            break;

        } else {

            DPRINTF("flushed %zd byte(s)\n", ret);

            offset += ret;

            s->bytes_xfer += ret;

        }

    }



    DPRINTF("flushed %zu of %zu byte(s)\n", offset, s->buffer_size);

    memmove(s->buffer, s->buffer + offset, s->buffer_size - offset);

    s->buffer_size -= offset;

}

static ssize_t drop_sync(int fd, size_t size)

{

    ssize_t ret, dropped = size;

    uint8_t *buffer = g_malloc(MIN(65536, size));



    while (size > 0) {

        ret = read_sync(fd, buffer, MIN(65536, size));

        if (ret < 0) {

            g_free(buffer);

            return ret;

        }



        assert(ret <= size);

        size -= ret;

    }



    g_free(buffer);

    return dropped;

}

static int buffered_put_buffer(void *opaque, const uint8_t *buf, int64_t pos, int size)

{

    QEMUFileBuffered *s = opaque;

    ssize_t error;



    DPRINTF("putting %d bytes at %" PRId64 "\n", size, pos);



    error = qemu_file_get_error(s->file);

    if (error) {

        DPRINTF("flush when error, bailing: %s\n", strerror(-error));

        return error;

    }



    if (size <= 0) {

        return size;

    }



    if (size > (s->buffer_capacity - s->buffer_size)) {

        DPRINTF("increasing buffer capacity from %zu by %zu\n",

                s->buffer_capacity, size + 1024);



        s->buffer_capacity += size + 1024;



        s->buffer = g_realloc(s->buffer, s->buffer_capacity);

    }



    memcpy(s->buffer + s->buffer_size, buf, size);

    s->buffer_size += size;



    return size;

}

