static void vtd_iommu_replay(MemoryRegion *mr, IOMMUNotifier *n)

{

    VTDAddressSpace *vtd_as = container_of(mr, VTDAddressSpace, iommu);

    IntelIOMMUState *s = vtd_as->iommu_state;

    uint8_t bus_n = pci_bus_num(vtd_as->bus);

    VTDContextEntry ce;



    if (vtd_dev_to_context_entry(s, bus_n, vtd_as->devfn, &ce) == 0) {

        /*

         * Scanned a valid context entry, walk over the pages and

         * notify when needed.

         */

        trace_vtd_replay_ce_valid(bus_n, PCI_SLOT(vtd_as->devfn),

                                  PCI_FUNC(vtd_as->devfn),

                                  VTD_CONTEXT_ENTRY_DID(ce.hi),

                                  ce.hi, ce.lo);

        vtd_page_walk(&ce, 0, ~0ULL, vtd_replay_hook, (void *)n);

    } else {

        trace_vtd_replay_ce_invalid(bus_n, PCI_SLOT(vtd_as->devfn),

                                    PCI_FUNC(vtd_as->devfn));

    }



    return;

}

static void vtd_do_iommu_translate(VTDAddressSpace *vtd_as, PCIBus *bus,

                                   uint8_t devfn, hwaddr addr, bool is_write,

                                   IOMMUTLBEntry *entry)

{

    IntelIOMMUState *s = vtd_as->iommu_state;

    VTDContextEntry ce;

    uint8_t bus_num = pci_bus_num(bus);

    VTDContextCacheEntry *cc_entry = &vtd_as->context_cache_entry;

    uint64_t slpte;

    uint32_t level;

    uint16_t source_id = vtd_make_source_id(bus_num, devfn);

    int ret_fr;

    bool is_fpd_set = false;

    bool reads = true;

    bool writes = true;

    VTDIOTLBEntry *iotlb_entry;



    /* Check if the request is in interrupt address range */

    if (vtd_is_interrupt_addr(addr)) {

        if (is_write) {

            /* FIXME: since we don't know the length of the access here, we

             * treat Non-DWORD length write requests without PASID as

             * interrupt requests, too. Withoud interrupt remapping support,

             * we just use 1:1 mapping.

             */

            VTD_DPRINTF(MMU, "write request to interrupt address "

                        "gpa 0x%"PRIx64, addr);

            entry->iova = addr & VTD_PAGE_MASK_4K;

            entry->translated_addr = addr & VTD_PAGE_MASK_4K;

            entry->addr_mask = ~VTD_PAGE_MASK_4K;

            entry->perm = IOMMU_WO;

            return;

        } else {

            VTD_DPRINTF(GENERAL, "error: read request from interrupt address "

                        "gpa 0x%"PRIx64, addr);

            vtd_report_dmar_fault(s, source_id, addr, VTD_FR_READ, is_write);

            return;

        }

    }

    /* Try to fetch slpte form IOTLB */

    iotlb_entry = vtd_lookup_iotlb(s, source_id, addr);

    if (iotlb_entry) {

        VTD_DPRINTF(CACHE, "hit iotlb sid 0x%"PRIx16 " gpa 0x%"PRIx64

                    " slpte 0x%"PRIx64 " did 0x%"PRIx16, source_id, addr,

                    iotlb_entry->slpte, iotlb_entry->domain_id);

        slpte = iotlb_entry->slpte;

        reads = iotlb_entry->read_flags;

        writes = iotlb_entry->write_flags;

        goto out;

    }

    /* Try to fetch context-entry from cache first */

    if (cc_entry->context_cache_gen == s->context_cache_gen) {

        VTD_DPRINTF(CACHE, "hit context-cache bus %d devfn %d "

                    "(hi %"PRIx64 " lo %"PRIx64 " gen %"PRIu32 ")",

                    bus_num, devfn, cc_entry->context_entry.hi,

                    cc_entry->context_entry.lo, cc_entry->context_cache_gen);

        ce = cc_entry->context_entry;

        is_fpd_set = ce.lo & VTD_CONTEXT_ENTRY_FPD;

    } else {

        ret_fr = vtd_dev_to_context_entry(s, bus_num, devfn, &ce);

        is_fpd_set = ce.lo & VTD_CONTEXT_ENTRY_FPD;

        if (ret_fr) {

            ret_fr = -ret_fr;

            if (is_fpd_set && vtd_is_qualified_fault(ret_fr)) {

                VTD_DPRINTF(FLOG, "fault processing is disabled for DMA "

                            "requests through this context-entry "

                            "(with FPD Set)");

            } else {

                vtd_report_dmar_fault(s, source_id, addr, ret_fr, is_write);

            }

            return;

        }

        /* Update context-cache */

        VTD_DPRINTF(CACHE, "update context-cache bus %d devfn %d "

                    "(hi %"PRIx64 " lo %"PRIx64 " gen %"PRIu32 "->%"PRIu32 ")",

                    bus_num, devfn, ce.hi, ce.lo,

                    cc_entry->context_cache_gen, s->context_cache_gen);

        cc_entry->context_entry = ce;

        cc_entry->context_cache_gen = s->context_cache_gen;

    }



    ret_fr = vtd_gpa_to_slpte(&ce, addr, is_write, &slpte, &level,

                              &reads, &writes);

    if (ret_fr) {

        ret_fr = -ret_fr;

        if (is_fpd_set && vtd_is_qualified_fault(ret_fr)) {

            VTD_DPRINTF(FLOG, "fault processing is disabled for DMA requests "

                        "through this context-entry (with FPD Set)");

        } else {

            vtd_report_dmar_fault(s, source_id, addr, ret_fr, is_write);

        }

        return;

    }



    vtd_update_iotlb(s, source_id, VTD_CONTEXT_ENTRY_DID(ce.hi), addr, slpte,

                     reads, writes);

out:

    entry->iova = addr & VTD_PAGE_MASK_4K;

    entry->translated_addr = vtd_get_slpte_addr(slpte) & VTD_PAGE_MASK_4K;

    entry->addr_mask = ~VTD_PAGE_MASK_4K;

    entry->perm = (writes ? 2 : 0) + (reads ? 1 : 0);

}

static int vfio_pci_hot_reset(VFIOPCIDevice *vdev, bool single)

{

    VFIOGroup *group;

    struct vfio_pci_hot_reset_info *info;

    struct vfio_pci_dependent_device *devices;

    struct vfio_pci_hot_reset *reset;

    int32_t *fds;

    int ret, i, count;

    bool multi = false;



    trace_vfio_pci_hot_reset(vdev->vbasedev.name, single ? "one" : "multi");



    vfio_pci_pre_reset(vdev);

    vdev->vbasedev.needs_reset = false;



    info = g_malloc0(sizeof(*info));

    info->argsz = sizeof(*info);



    ret = ioctl(vdev->vbasedev.fd, VFIO_DEVICE_GET_PCI_HOT_RESET_INFO, info);

    if (ret && errno != ENOSPC) {

        ret = -errno;

        if (!vdev->has_pm_reset) {

            error_report("vfio: Cannot reset device %04x:%02x:%02x.%x, "

                         "no available reset mechanism.", vdev->host.domain,

                         vdev->host.bus, vdev->host.slot, vdev->host.function);

        }

        goto out_single;

    }



    count = info->count;

    info = g_realloc(info, sizeof(*info) + (count * sizeof(*devices)));

    info->argsz = sizeof(*info) + (count * sizeof(*devices));

    devices = &info->devices[0];



    ret = ioctl(vdev->vbasedev.fd, VFIO_DEVICE_GET_PCI_HOT_RESET_INFO, info);

    if (ret) {

        ret = -errno;

        error_report("vfio: hot reset info failed: %m");

        goto out_single;

    }



    trace_vfio_pci_hot_reset_has_dep_devices(vdev->vbasedev.name);



    /* Verify that we have all the groups required */

    for (i = 0; i < info->count; i++) {

        PCIHostDeviceAddress host;

        VFIOPCIDevice *tmp;

        VFIODevice *vbasedev_iter;



        host.domain = devices[i].segment;

        host.bus = devices[i].bus;

        host.slot = PCI_SLOT(devices[i].devfn);

        host.function = PCI_FUNC(devices[i].devfn);



        trace_vfio_pci_hot_reset_dep_devices(host.domain,

                host.bus, host.slot, host.function, devices[i].group_id);



        if (vfio_pci_host_match(&host, &vdev->host)) {

            continue;

        }



        QLIST_FOREACH(group, &vfio_group_list, next) {

            if (group->groupid == devices[i].group_id) {

                break;

            }

        }



        if (!group) {

            if (!vdev->has_pm_reset) {

                error_report("vfio: Cannot reset device %s, "

                             "depends on group %d which is not owned.",

                             vdev->vbasedev.name, devices[i].group_id);

            }

            ret = -EPERM;

            goto out;

        }



        /* Prep dependent devices for reset and clear our marker. */

        QLIST_FOREACH(vbasedev_iter, &group->device_list, next) {

            if (vbasedev_iter->type != VFIO_DEVICE_TYPE_PCI) {

                continue;

            }

            tmp = container_of(vbasedev_iter, VFIOPCIDevice, vbasedev);

            if (vfio_pci_host_match(&host, &tmp->host)) {

                if (single) {

                    ret = -EINVAL;

                    goto out_single;

                }

                vfio_pci_pre_reset(tmp);

                tmp->vbasedev.needs_reset = false;

                multi = true;

                break;

            }

        }

    }



    if (!single && !multi) {

        ret = -EINVAL;

        goto out_single;

    }



    /* Determine how many group fds need to be passed */

    count = 0;

    QLIST_FOREACH(group, &vfio_group_list, next) {

        for (i = 0; i < info->count; i++) {

            if (group->groupid == devices[i].group_id) {

                count++;

                break;

            }

        }

    }



    reset = g_malloc0(sizeof(*reset) + (count * sizeof(*fds)));

    reset->argsz = sizeof(*reset) + (count * sizeof(*fds));

    fds = &reset->group_fds[0];



    /* Fill in group fds */

    QLIST_FOREACH(group, &vfio_group_list, next) {

        for (i = 0; i < info->count; i++) {

            if (group->groupid == devices[i].group_id) {

                fds[reset->count++] = group->fd;

                break;

            }

        }

    }



    /* Bus reset! */

    ret = ioctl(vdev->vbasedev.fd, VFIO_DEVICE_PCI_HOT_RESET, reset);

    g_free(reset);



    trace_vfio_pci_hot_reset_result(vdev->vbasedev.name,

                                    ret ? "%m" : "Success");



out:

    /* Re-enable INTx on affected devices */

    for (i = 0; i < info->count; i++) {

        PCIHostDeviceAddress host;

        VFIOPCIDevice *tmp;

        VFIODevice *vbasedev_iter;



        host.domain = devices[i].segment;

        host.bus = devices[i].bus;

        host.slot = PCI_SLOT(devices[i].devfn);

        host.function = PCI_FUNC(devices[i].devfn);



        if (vfio_pci_host_match(&host, &vdev->host)) {

            continue;

        }



        QLIST_FOREACH(group, &vfio_group_list, next) {

            if (group->groupid == devices[i].group_id) {

                break;

            }

        }



        if (!group) {

            break;

        }



        QLIST_FOREACH(vbasedev_iter, &group->device_list, next) {

            if (vbasedev_iter->type != VFIO_DEVICE_TYPE_PCI) {

                continue;

            }

            tmp = container_of(vbasedev_iter, VFIOPCIDevice, vbasedev);

            if (vfio_pci_host_match(&host, &tmp->host)) {

                vfio_pci_post_reset(tmp);

                break;

            }

        }

    }

out_single:

    vfio_pci_post_reset(vdev);

    g_free(info);



    return ret;

}

static char *pcibus_get_dev_path(DeviceState *dev)

{

    PCIDevice *d = container_of(dev, PCIDevice, qdev);

    PCIDevice *t;

    int slot_depth;

    /* Path format: Domain:00:Slot.Function:Slot.Function....:Slot.Function.

     * 00 is added here to make this format compatible with

     * domain:Bus:Slot.Func for systems without nested PCI bridges.

     * Slot.Function list specifies the slot and function numbers for all

     * devices on the path from root to the specific device. */

    int domain_len = strlen("DDDD:00");

    int slot_len = strlen(":SS.F");

    int path_len;

    char *path, *p;



    /* Calculate # of slots on path between device and root. */;

    slot_depth = 0;

    for (t = d; t; t = t->bus->parent_dev) {

        ++slot_depth;

    }



    path_len = domain_len + slot_len * slot_depth;



    /* Allocate memory, fill in the terminating null byte. */

    path = malloc(path_len + 1 /* For '\0' */);

    path[path_len] = '\0';



    /* First field is the domain. */

    snprintf(path, domain_len, "%04x:00", pci_find_domain(d->bus));



    /* Fill in slot numbers. We walk up from device to root, so need to print

     * them in the reverse order, last to first. */

    p = path + path_len;

    for (t = d; t; t = t->bus->parent_dev) {

        p -= slot_len;

        snprintf(p, slot_len, ":%02x.%x", PCI_SLOT(t->devfn), PCI_FUNC(d->devfn));

    }



    return path;

}

