                av_log(s->avctx, AV_LOG_DEBUG, "Video Object Start");

            else if (startcode <= 0x12F)

                av_log(s->avctx, AV_LOG_DEBUG, "Video Object Layer Start");

            else if (startcode <= 0x13F)

                av_log(s->avctx, AV_LOG_DEBUG, "Reserved");

            else if (startcode <= 0x15F)

                av_log(s->avctx, AV_LOG_DEBUG, "FGS bp start");

            else if (startcode <= 0x1AF)

                av_log(s->avctx, AV_LOG_DEBUG, "Reserved");

            else if (startcode == 0x1B0)

                av_log(s->avctx, AV_LOG_DEBUG, "Visual Object Seq Start");

            else if (startcode == 0x1B1)

                av_log(s->avctx, AV_LOG_DEBUG, "Visual Object Seq End");

            else if (startcode == 0x1B2)

                av_log(s->avctx, AV_LOG_DEBUG, "User Data");

            else if (startcode == 0x1B3)

                av_log(s->avctx, AV_LOG_DEBUG, "Group of VOP start");

            else if (startcode == 0x1B4)

                av_log(s->avctx, AV_LOG_DEBUG, "Video Session Error");

            else if (startcode == 0x1B5)

                av_log(s->avctx, AV_LOG_DEBUG, "Visual Object Start");

            else if (startcode == 0x1B6)

                av_log(s->avctx, AV_LOG_DEBUG, "Video Object Plane start");

            else if (startcode == 0x1B7)

                av_log(s->avctx, AV_LOG_DEBUG, "slice start");

            else if (startcode == 0x1B8)

                av_log(s->avctx, AV_LOG_DEBUG, "extension start");

            else if (startcode == 0x1B9)

                av_log(s->avctx, AV_LOG_DEBUG, "fgs start");

            else if (startcode == 0x1BA)

                av_log(s->avctx, AV_LOG_DEBUG, "FBA Object start");

            else if (startcode == 0x1BB)

                av_log(s->avctx, AV_LOG_DEBUG, "FBA Object Plane start");

            else if (startcode == 0x1BC)

                av_log(s->avctx, AV_LOG_DEBUG, "Mesh Object start");

            else if (startcode == 0x1BD)

                av_log(s->avctx, AV_LOG_DEBUG, "Mesh Object Plane start");

            else if (startcode == 0x1BE)

                av_log(s->avctx, AV_LOG_DEBUG, "Still Texture Object start");

            else if (startcode == 0x1BF)

                av_log(s->avctx, AV_LOG_DEBUG, "Texture Spatial Layer start");

            else if (startcode == 0x1C0)

                av_log(s->avctx, AV_LOG_DEBUG, "Texture SNR Layer start");

            else if (startcode == 0x1C1)

                av_log(s->avctx, AV_LOG_DEBUG, "Texture Tile start");

            else if (startcode == 0x1C2)

                av_log(s->avctx, AV_LOG_DEBUG, "Texture Shape Layer start");

            else if (startcode == 0x1C3)

                av_log(s->avctx, AV_LOG_DEBUG, "stuffing start");

            else if (startcode <= 0x1C5)

                av_log(s->avctx, AV_LOG_DEBUG, "reserved");

            else if (startcode <= 0x1FF)

                av_log(s->avctx, AV_LOG_DEBUG, "System start");

            av_log(s->avctx, AV_LOG_DEBUG, " at %d\n", get_bits_count(gb));




        if (startcode >= 0x120 && startcode <= 0x12F) {






            if ((ret = decode_vol_header(ctx, gb)) < 0)

                return ret;

        } else if (startcode == USER_DATA_STARTCODE) {

            decode_user_data(ctx, gb);

        } else if (startcode == GOP_STARTCODE) {

            mpeg4_decode_gop_header(s, gb);

        } else if (startcode == VOS_STARTCODE) {

            mpeg4_decode_profile_level(s, gb);

        } else if (startcode == VOP_STARTCODE) {

            break;




        align_get_bits(gb);

        startcode = 0xff;




end:

    if (s->avctx->flags & AV_CODEC_FLAG_LOW_DELAY)

        s->low_delay = 1;

    s->avctx->has_b_frames = !s->low_delay;



    return decode_vop_header(ctx, gb);

static void mpegvideo_extract_headers(AVCodecParserContext *s,
                                      AVCodecContext *avctx,
                                      const uint8_t *buf, int buf_size)
{
    ParseContext1 *pc = s->priv_data;
    const uint8_t *buf_end;
    const uint8_t *buf_start= buf;
    uint32_t start_code;
    int frame_rate_index, ext_type, bytes_left;
    int frame_rate_ext_n, frame_rate_ext_d;
    int picture_structure, top_field_first, repeat_first_field, progressive_frame;
    int horiz_size_ext, vert_size_ext, bit_rate_ext;
//FIXME replace the crap with get_bits()
    s->repeat_pict = 0;
    buf_end = buf + buf_size;
    while (buf < buf_end) {
        start_code= -1;
        buf= ff_find_start_code(buf, buf_end, &start_code);
        bytes_left = buf_end - buf;
        switch(start_code) {
        case PICTURE_START_CODE:
            if (bytes_left >= 2) {
                s->pict_type = (buf[1] >> 3) & 7;
            }
            break;
        case SEQ_START_CODE:
            if (bytes_left >= 7) {
                pc->width  = (buf[0] << 4) | (buf[1] >> 4);
                pc->height = ((buf[1] & 0x0f) << 8) | buf[2];
                avcodec_set_dimensions(avctx, pc->width, pc->height);
                frame_rate_index = buf[3] & 0xf;
                pc->frame_rate.den = avctx->time_base.den = ff_frame_rate_tab[frame_rate_index].num;
                pc->frame_rate.num = avctx->time_base.num = ff_frame_rate_tab[frame_rate_index].den;
                avctx->bit_rate = ((buf[4]<<10) | (buf[5]<<2) | (buf[6]>>6))*400;
                avctx->codec_id = CODEC_ID_MPEG1VIDEO;
                avctx->sub_id = 1;
            }
            break;
        case EXT_START_CODE:
            if (bytes_left >= 1) {
                ext_type = (buf[0] >> 4);
                switch(ext_type) {
                case 0x1: /* sequence extension */
                    if (bytes_left >= 6) {
                        horiz_size_ext = ((buf[1] & 1) << 1) | (buf[2] >> 7);
                        vert_size_ext = (buf[2] >> 5) & 3;
                        bit_rate_ext = ((buf[2] & 0x1F)<<7) | (buf[3]>>1);
                        frame_rate_ext_n = (buf[5] >> 5) & 3;
                        frame_rate_ext_d = (buf[5] & 0x1f);
                        pc->progressive_sequence = buf[1] & (1 << 3);
                        avctx->has_b_frames= !(buf[5] >> 7);
                        pc->width  |=(horiz_size_ext << 12);
                        pc->height |=( vert_size_ext << 12);
                        avctx->bit_rate += (bit_rate_ext << 18) * 400;
                        avcodec_set_dimensions(avctx, pc->width, pc->height);
                        avctx->time_base.den = pc->frame_rate.den * (frame_rate_ext_n + 1);
                        avctx->time_base.num = pc->frame_rate.num * (frame_rate_ext_d + 1);
                        avctx->codec_id = CODEC_ID_MPEG2VIDEO;
                        avctx->sub_id = 2; /* forces MPEG2 */
                    }
                    break;
                case 0x8: /* picture coding extension */
                    if (bytes_left >= 5) {
                        picture_structure = buf[2]&3;
                        top_field_first = buf[3] & (1 << 7);
                        repeat_first_field = buf[3] & (1 << 1);
                        progressive_frame = buf[4] & (1 << 7);
                        /* check if we must repeat the frame */
                        if (repeat_first_field) {
                            if (pc->progressive_sequence) {
                                if (top_field_first)
                                    s->repeat_pict = 4;
                                else
                                    s->repeat_pict = 2;
                            } else if (progressive_frame) {
                                s->repeat_pict = 1;
                            }
                        }
                    }
                    break;
                }
            }
            break;
        case -1:
            goto the_end;
        default:
            /* we stop parsing when we encounter a slice. It ensures
               that this function takes a negligible amount of time */
            if (start_code >= SLICE_MIN_START_CODE &&
                start_code <= SLICE_MAX_START_CODE)
                goto the_end;
            break;
        }
    }
 the_end: ;
}

static inline int parse_nal_units(AVCodecParserContext *s,

                                  AVCodecContext *avctx,

                                  const uint8_t *buf, int buf_size)

{

    H264Context *h = s->priv_data;

    const uint8_t *buf_end = buf + buf_size;

    unsigned int pps_id;

    unsigned int slice_type;

    int state;

    const uint8_t *ptr;



    /* set some sane default values */

    s->pict_type = FF_I_TYPE;

    s->key_frame = 0;



    h->s.avctx= avctx;

    h->sei_recovery_frame_cnt = -1;

    h->sei_dpb_output_delay         =  0;

    h->sei_cpb_removal_delay        = -1;

    h->sei_buffering_period_present =  0;



    for(;;) {

        int src_length, dst_length, consumed;

        buf = ff_find_start_code(buf, buf_end, &state);

        if(buf >= buf_end)

            break;

        --buf;

        src_length = buf_end - buf;

        switch (state & 0x1f) {

        case NAL_SLICE:

        case NAL_IDR_SLICE:

            // Do not walk the whole buffer just to decode slice header

            if (src_length > 20)

                src_length = 20;

            break;

        }

        ptr= ff_h264_decode_nal(h, buf, &dst_length, &consumed, src_length);

        if (ptr==NULL || dst_length < 0)

            break;



        init_get_bits(&h->s.gb, ptr, 8*dst_length);

        switch(h->nal_unit_type) {

        case NAL_SPS:

            ff_h264_decode_seq_parameter_set(h);

            break;

        case NAL_PPS:

            ff_h264_decode_picture_parameter_set(h, h->s.gb.size_in_bits);

            break;

        case NAL_SEI:

            ff_h264_decode_sei(h);

            break;

        case NAL_IDR_SLICE:

            s->key_frame = 1;

            /* fall through */

        case NAL_SLICE:

            get_ue_golomb(&h->s.gb);  // skip first_mb_in_slice

            slice_type = get_ue_golomb_31(&h->s.gb);

            s->pict_type = golomb_to_pict_type[slice_type % 5];

            if (h->sei_recovery_frame_cnt >= 0) {

                /* key frame, since recovery_frame_cnt is set */

                s->key_frame = 1;

            }

            pps_id= get_ue_golomb(&h->s.gb);

            if(pps_id>=MAX_PPS_COUNT) {

                av_log(h->s.avctx, AV_LOG_ERROR, "pps_id out of range\n");

                return -1;

            }

            if(!h->pps_buffers[pps_id]) {

                av_log(h->s.avctx, AV_LOG_ERROR, "non-existing PPS referenced\n");

                return -1;

            }

            h->pps= *h->pps_buffers[pps_id];

            if(!h->sps_buffers[h->pps.sps_id]) {

                av_log(h->s.avctx, AV_LOG_ERROR, "non-existing SPS referenced\n");

                return -1;

            }

            h->sps = *h->sps_buffers[h->pps.sps_id];

            h->frame_num = get_bits(&h->s.gb, h->sps.log2_max_frame_num);



            if(h->sps.frame_mbs_only_flag){

                h->s.picture_structure= PICT_FRAME;

            }else{

                if(get_bits1(&h->s.gb)) { //field_pic_flag

                    h->s.picture_structure= PICT_TOP_FIELD + get_bits1(&h->s.gb); //bottom_field_flag

                } else {

                    h->s.picture_structure= PICT_FRAME;

                }

            }



            if(h->sps.pic_struct_present_flag) {

                switch (h->sei_pic_struct) {

                    case SEI_PIC_STRUCT_TOP_FIELD:

                    case SEI_PIC_STRUCT_BOTTOM_FIELD:

                        s->repeat_pict = 0;

                        break;

                    case SEI_PIC_STRUCT_FRAME:

                    case SEI_PIC_STRUCT_TOP_BOTTOM:

                    case SEI_PIC_STRUCT_BOTTOM_TOP:

                        s->repeat_pict = 1;

                        break;

                    case SEI_PIC_STRUCT_TOP_BOTTOM_TOP:

                    case SEI_PIC_STRUCT_BOTTOM_TOP_BOTTOM:

                        s->repeat_pict = 2;

                        break;

                    case SEI_PIC_STRUCT_FRAME_DOUBLING:

                        s->repeat_pict = 3;

                        break;

                    case SEI_PIC_STRUCT_FRAME_TRIPLING:

                        s->repeat_pict = 5;

                        break;

                    default:

                        s->repeat_pict = h->s.picture_structure == PICT_FRAME ? 1 : 0;

                        break;

                }

            } else {

                s->repeat_pict = h->s.picture_structure == PICT_FRAME ? 1 : 0;

            }



            return 0; /* no need to evaluate the rest */

        }

        buf += consumed;

    }

    /* didn't find a picture! */

    av_log(h->s.avctx, AV_LOG_ERROR, "missing picture in access unit\n");

    return -1;

}

static int mpegvideo_parse(AVCodecParserContext *s,

                           AVCodecContext *avctx,

                           const uint8_t **poutbuf, int *poutbuf_size,

                           const uint8_t *buf, int buf_size)

{

    ParseContext1 *pc1 = s->priv_data;

    ParseContext *pc= &pc1->pc;

    int next;



    if(s->flags & PARSER_FLAG_COMPLETE_FRAMES){

        next= buf_size;

    }else{

        next= ff_mpeg1_find_frame_end(pc, buf, buf_size);



        if (ff_combine_frame(pc, next, &buf, &buf_size) < 0) {

            *poutbuf = NULL;

            *poutbuf_size = 0;

            return buf_size;

        }



    }

    /* we have a full frame : we just parse the first few MPEG headers

       to have the full timing information. The time take by this

       function should be negligible for uncorrupted streams */

    mpegvideo_extract_headers(s, avctx, buf, buf_size);

#if 0

    printf("pict_type=%d frame_rate=%0.3f repeat_pict=%d\n",

           s->pict_type, (double)avctx->time_base.den / avctx->time_base.num, s->repeat_pict);

#endif



    *poutbuf = buf;

    *poutbuf_size = buf_size;

    return next;

}

static int get_bits(Jpeg2000DecoderContext *s, int n)

{

    int res = 0;

    if (s->buf_end - s->buf < ((n - s->bit_index) >> 8))

        return AVERROR(EINVAL);

    while (--n >= 0) {

        res <<= 1;

        if (s->bit_index == 0) {

            s->bit_index = 7 + (*s->buf != 0xff);

            s->buf++;

        }

        s->bit_index--;

        res |= (*s->buf >> s->bit_index) & 1;

    }

    return res;

}

static enum AVPixelFormat get_chroma_format(SchroChromaFormat schro_pix_fmt)

{

    int num_formats = sizeof(schro_pixel_format_map) /

                      sizeof(schro_pixel_format_map[0]);

    int idx;



    for (idx = 0; idx < num_formats; ++idx)

        if (schro_pixel_format_map[idx].schro_pix_fmt == schro_pix_fmt)

            return schro_pixel_format_map[idx].ff_pix_fmt;

    return AV_PIX_FMT_NONE;

}

static void libschroedinger_handle_first_access_unit(AVCodecContext *avctx)

{

    SchroDecoderParams *p_schro_params = avctx->priv_data;

    SchroDecoder *decoder = p_schro_params->decoder;



    p_schro_params->format = schro_decoder_get_video_format(decoder);



    /* Tell FFmpeg about sequence details. */

    if (av_image_check_size(p_schro_params->format->width,

                            p_schro_params->format->height, 0, avctx) < 0) {

        av_log(avctx, AV_LOG_ERROR, "invalid dimensions (%dx%d)\n",

               p_schro_params->format->width, p_schro_params->format->height);

        avctx->height = avctx->width = 0;

        return;

    }

    avctx->height  = p_schro_params->format->height;

    avctx->width   = p_schro_params->format->width;

    avctx->pix_fmt = get_chroma_format(p_schro_params->format->chroma_format);



    if (ff_get_schro_frame_format(p_schro_params->format->chroma_format,

                                  &p_schro_params->frame_format) == -1) {

        av_log(avctx, AV_LOG_ERROR,

               "This codec currently only supports planar YUV 4:2:0, 4:2:2 "

               "and 4:4:4 formats.\n");

        return;

    }



    avctx->framerate.num = p_schro_params->format->frame_rate_numerator;

    avctx->framerate.den = p_schro_params->format->frame_rate_denominator;

}

static int sbr_hf_gen(AACContext *ac, SpectralBandReplication *sbr,

                      float X_high[64][40][2], const float X_low[32][40][2],

                      const float (*alpha0)[2], const float (*alpha1)[2],

                      const float bw_array[5], const uint8_t *t_env,

                      int bs_num_env)

{

    int i, j, x;

    int g = 0;

    int k = sbr->kx[1];

    for (j = 0; j < sbr->num_patches; j++) {

        for (x = 0; x < sbr->patch_num_subbands[j]; x++, k++) {

            float alpha[4];

            const int p = sbr->patch_start_subband[j] + x;

            while (g <= sbr->n_q && k >= sbr->f_tablenoise[g])

                g++;

            g--;



            if (g < 0) {

                av_log(ac->avctx, AV_LOG_ERROR,

                       "ERROR : no subband found for frequency %d\n", k);

                return -1;

            }



            alpha[0] = alpha1[p][0] * bw_array[g] * bw_array[g];

            alpha[1] = alpha1[p][1] * bw_array[g] * bw_array[g];

            alpha[2] = alpha0[p][0] * bw_array[g];

            alpha[3] = alpha0[p][1] * bw_array[g];



            for (i = 2 * t_env[0]; i < 2 * t_env[bs_num_env]; i++) {

                const int idx = i + ENVELOPE_ADJUSTMENT_OFFSET;

                X_high[k][idx][0] =

                    X_low[p][idx - 2][0] * alpha[0] -

                    X_low[p][idx - 2][1] * alpha[1] +

                    X_low[p][idx - 1][0] * alpha[2] -

                    X_low[p][idx - 1][1] * alpha[3] +

                    X_low[p][idx][0];

                X_high[k][idx][1] =

                    X_low[p][idx - 2][1] * alpha[0] +

                    X_low[p][idx - 2][0] * alpha[1] +

                    X_low[p][idx - 1][1] * alpha[2] +

                    X_low[p][idx - 1][0] * alpha[3] +

                    X_low[p][idx][1];

            }

        }

    }

    if (k < sbr->m[1] + sbr->kx[1])

        memset(X_high + k, 0, (sbr->m[1] + sbr->kx[1] - k) * sizeof(*X_high));



    return 0;

}

int ff_get_schro_frame_format (SchroChromaFormat schro_pix_fmt,

                               SchroFrameFormat  *schro_frame_fmt)

{

    unsigned int num_formats = sizeof(schro_pixel_format_map) /

                               sizeof(schro_pixel_format_map[0]);



    int idx;



    for (idx = 0; idx < num_formats; ++idx) {

        if (schro_pixel_format_map[idx].schro_pix_fmt == schro_pix_fmt) {

            *schro_frame_fmt = schro_pixel_format_map[idx].schro_frame_fmt;

            return 0;

        }

    }

    return -1;

}

static void gen_or(DisasContext *ctx)

{

    int rs, ra, rb;



    rs = rS(ctx->opcode);

    ra = rA(ctx->opcode);

    rb = rB(ctx->opcode);

    /* Optimisation for mr. ri case */

    if (rs != ra || rs != rb) {

        if (rs != rb)

            tcg_gen_or_tl(cpu_gpr[ra], cpu_gpr[rs], cpu_gpr[rb]);

        else

            tcg_gen_mov_tl(cpu_gpr[ra], cpu_gpr[rs]);

        if (unlikely(Rc(ctx->opcode) != 0))

            gen_set_Rc0(ctx, cpu_gpr[ra]);

    } else if (unlikely(Rc(ctx->opcode) != 0)) {

        gen_set_Rc0(ctx, cpu_gpr[rs]);

#if defined(TARGET_PPC64)

    } else {

        int prio = 0;



        switch (rs) {

        case 1:

            /* Set process priority to low */

            prio = 2;

            break;

        case 6:

            /* Set process priority to medium-low */

            prio = 3;

            break;

        case 2:

            /* Set process priority to normal */

            prio = 4;

            break;

#if !defined(CONFIG_USER_ONLY)

        case 31:

            if (!ctx->pr) {

                /* Set process priority to very low */

                prio = 1;

            }

            break;

        case 5:

            if (!ctx->pr) {

                /* Set process priority to medium-hight */

                prio = 5;

            }

            break;

        case 3:

            if (!ctx->pr) {

                /* Set process priority to high */

                prio = 6;

            }

            break;

        case 7:

            if (ctx->hv) {

                /* Set process priority to very high */

                prio = 7;

            }

            break;

#endif

        default:

            /* nop */

            break;

        }

        if (prio) {

            TCGv t0 = tcg_temp_new();

            gen_load_spr(t0, SPR_PPR);

            tcg_gen_andi_tl(t0, t0, ~0x001C000000000000ULL);

            tcg_gen_ori_tl(t0, t0, ((uint64_t)prio) << 50);

            gen_store_spr(SPR_PPR, t0);

            tcg_temp_free(t0);

        }

#endif

    }

}

static int ppc_hash64_pte_prot(PowerPCCPU *cpu,

                               ppc_slb_t *slb, ppc_hash_pte64_t pte)

{

    CPUPPCState *env = &cpu->env;

    unsigned pp, key;

    /* Some pp bit combinations have undefined behaviour, so default

     * to no access in those cases */

    int prot = 0;



    key = !!(msr_pr ? (slb->vsid & SLB_VSID_KP)

             : (slb->vsid & SLB_VSID_KS));

    pp = (pte.pte1 & HPTE64_R_PP) | ((pte.pte1 & HPTE64_R_PP0) >> 61);



    if (key == 0) {

        switch (pp) {

        case 0x0:

        case 0x1:

        case 0x2:

            prot = PAGE_READ | PAGE_WRITE | PAGE_EXEC;

            break;



        case 0x3:

        case 0x6:

            prot = PAGE_READ | PAGE_EXEC;

            break;

        }

    } else {

        switch (pp) {

        case 0x0:

        case 0x6:

            break;



        case 0x1:

        case 0x3:

            prot = PAGE_READ | PAGE_EXEC;

            break;



        case 0x2:

            prot = PAGE_READ | PAGE_WRITE | PAGE_EXEC;

            break;

        }

    }



    /* No execute if either noexec or guarded bits set */

    if (!(pte.pte1 & HPTE64_R_N) || (pte.pte1 & HPTE64_R_G)

        || (slb->vsid & SLB_VSID_N)) {

        prot |= PAGE_EXEC;

    }



    return prot;

}

static void vga_update_display(void *opaque)

{

    VGACommonState *s = opaque;

    int full_update, graphic_mode;



    qemu_flush_coalesced_mmio_buffer();



    if (ds_get_bits_per_pixel(s->ds) == 0) {

        /* nothing to do */

    } else {

        full_update = 0;

        if (!(s->ar_index & 0x20) &&

            /* extra CGA compatibility hacks (not in standard VGA */

            (!(vga_cga_hacks & VGA_CGA_HACK_PALETTE_BLANKING) ||

             (s->ar_index != 0 && s->ar_flip_flop))) {

            graphic_mode = GMODE_BLANK;

        } else {

            graphic_mode = s->gr[VGA_GFX_MISC] & VGA_GR06_GRAPHICS_MODE;

        }

        if (graphic_mode != s->graphic_mode) {

            s->graphic_mode = graphic_mode;

            s->cursor_blink_time = qemu_get_clock_ms(vm_clock);

            full_update = 1;

        }

        switch(graphic_mode) {

        case GMODE_TEXT:

            vga_draw_text(s, full_update);

            break;

        case GMODE_GRAPH:

            vga_draw_graphic(s, full_update);

            break;

