static int dca_find_frame_end(DCAParseContext * pc1, const uint8_t * buf,

                              int buf_size)

{

    int start_found, i;

    uint32_t state;

    ParseContext *pc = &pc1->pc;



    start_found = pc->frame_start_found;

    state = pc->state;



    i = 0;

    if (!start_found) {

        for (i = 0; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (IS_MARKER(state, i, buf, buf_size)) {

                if (!pc1->lastmarker || state == pc1->lastmarker || pc1->lastmarker == DCA_HD_MARKER) {

                    start_found = 1;

                    pc1->lastmarker = state;

                    break;

                }

            }

        }

    }

    if (start_found) {

        for (; i < buf_size; i++) {

            pc1->size++;

            state = (state << 8) | buf[i];

            if (state == DCA_HD_MARKER && !pc1->hd_pos)

                pc1->hd_pos = pc1->size;

            if (IS_MARKER(state, i, buf, buf_size) && (state == pc1->lastmarker || pc1->lastmarker == DCA_HD_MARKER)) {

                if(pc1->framesize > pc1->size)

                    continue;

                if(!pc1->framesize){

                    pc1->framesize = pc1->hd_pos ? pc1->hd_pos : pc1->size;

                }

                pc->frame_start_found = 0;

                pc->state = -1;

                pc1->size = 0;

                return i - 3;

            }

        }

    }

    pc->frame_start_found = start_found;

    pc->state = state;

    return END_NOT_FOUND;

}

static int hevc_find_frame_end(AVCodecParserContext *s, const uint8_t *buf,

                               int buf_size)

{

    HEVCParserContext *ctx = s->priv_data;

    ParseContext       *pc = &ctx->pc;

    int i;



    for (i = 0; i < buf_size; i++) {

        int nut;



        pc->state64 = (pc->state64 << 8) | buf[i];



        if (((pc->state64 >> 3 * 8) & 0xFFFFFF) != START_CODE)

            continue;



        nut = (pc->state64 >> 2 * 8 + 1) & 0x3F;

        // Beginning of access unit

        if ((nut >= HEVC_NAL_VPS && nut <= HEVC_NAL_AUD) || nut == HEVC_NAL_SEI_PREFIX ||

            (nut >= 41 && nut <= 44) || (nut >= 48 && nut <= 55)) {

            if (pc->frame_start_found) {

                pc->frame_start_found = 0;

                return i - 5;

            }

        } else if (nut <= HEVC_NAL_RASL_R ||

                   (nut >= HEVC_NAL_BLA_W_LP && nut <= HEVC_NAL_CRA_NUT)) {

            int first_slice_segment_in_pic_flag = buf[i] >> 7;

            if (first_slice_segment_in_pic_flag) {

                if (!pc->frame_start_found) {

                    pc->frame_start_found = 1;

                } else { // First slice of next frame found

                    pc->frame_start_found = 0;

                    return i - 5;

                }

            }

        }

    }



    return END_NOT_FOUND;

}

static int mpeg1_find_frame_end(MpegEncContext *s, uint8_t *buf, int buf_size){

    ParseContext *pc= &s->parse_context;

    int i;

    uint32_t state;



    state= pc->state;



    i=0;

    if(!pc->frame_start_found){

        for(i=0; i<buf_size; i++){

            state= (state<<8) | buf[i];

            if(state >= SLICE_MIN_START_CODE && state <= SLICE_MAX_START_CODE){

                i++;

                pc->frame_start_found=1;

                break;

            }

        }

    }



    if(pc->frame_start_found){

        for(; i<buf_size; i++){

            state= (state<<8) | buf[i];

            if((state&0xFFFFFF00) == 0x100){

                if(state < SLICE_MIN_START_CODE || state > SLICE_MAX_START_CODE){

                    pc->frame_start_found=0;

                    pc->state=-1; 

                    return i-3;

                }

            }

        }

    }        

    pc->state= state;

    return -1;

}

static int h264_find_frame_end(H264ParseContext *p, const uint8_t *buf,

                               int buf_size)

{

    int i;

    uint32_t state;

    ParseContext *pc = &p->pc;

//    mb_addr= pc->mb_addr - 1;

    state = pc->state;

    if (state > 13)

        state = 7;



    for (i = 0; i < buf_size; i++) {

        if (state == 7) {

            i += p->h264dsp.startcode_find_candidate(buf + i, buf_size - i);

            if (i < buf_size)

                state = 2;

        } else if (state <= 2) {

            if (buf[i] == 1)

                state ^= 5;            // 2->7, 1->4, 0->5

            else if (buf[i])

                state = 7;

            else

                state >>= 1;           // 2->1, 1->0, 0->0

        } else if (state <= 5) {

            int nalu_type = buf[i] & 0x1F;

            if (nalu_type == NAL_SEI || nalu_type == NAL_SPS ||

                nalu_type == NAL_PPS || nalu_type == NAL_AUD) {

                if (pc->frame_start_found) {

                    i++;

                    goto found;

                }

            } else if (nalu_type == NAL_SLICE || nalu_type == NAL_DPA ||

                       nalu_type == NAL_IDR_SLICE) {

                if (pc->frame_start_found) {

                    state += 8;

                    continue;

                } else

                    pc->frame_start_found = 1;

            }

            state = 7;

        } else {

            // first_mb_in_slice is 0, probably the first nal of a new slice

            if (buf[i] & 0x80)

                goto found;

            state = 7;

        }

    }

    pc->state = state;

    return END_NOT_FOUND;



found:

    pc->state             = 7;

    pc->frame_start_found = 0;

    return i - (state & 5);

}

