static int xan_huffman_decode(unsigned char *dest, const unsigned char *src,

    int dest_len)

{

    unsigned char byte = *src++;

    unsigned char ival = byte + 0x16;

    const unsigned char * ptr = src + byte*2;

    unsigned char val = ival;

    unsigned char *dest_end = dest + dest_len;

    GetBitContext gb;



    init_get_bits(&gb, ptr, 0); // FIXME: no src size available



    while ( val != 0x16 ) {

        val = src[val - 0x17 + get_bits1(&gb) * byte];



        if ( val < 0x16 ) {

            if (dest + 1 > dest_end)

                return 0;

            *dest++ = val;

            val = ival;

        }

    }



    return 0;

}

static int mszh_decomp(unsigned char * srcptr, int srclen, unsigned char * destptr)

{

    unsigned char *destptr_bak = destptr;

    unsigned char mask = 0;

    unsigned char maskbit = 0;

    unsigned int ofs, cnt;



    while (srclen > 0) {

        if (maskbit == 0) {

            mask = *(srcptr++);

            maskbit = 8;

            srclen--;

            continue;

        }

        if ((mask & (1 << (--maskbit))) == 0) {

            *(int*)destptr = *(int*)srcptr;

            srclen -= 4;

            destptr += 4;

            srcptr += 4;

        } else {

            ofs = *(srcptr++);

            cnt = *(srcptr++);

            ofs += cnt * 256;;

            cnt = ((cnt >> 3) & 0x1f) + 1;

            ofs &= 0x7ff;

            srclen -= 2;

            cnt *= 4;

            for (; cnt > 0; cnt--) {

                *(destptr) = *(destptr - ofs);

                destptr++;

            }

        }

    }



    return (destptr - destptr_bak);

}

static int xan_huffman_decode(unsigned char *dest, int dest_len,

                              const unsigned char *src, int src_len)

{

    unsigned char byte = *src++;

    unsigned char ival = byte + 0x16;

    const unsigned char * ptr = src + byte*2;

    int ptr_len = src_len - 1 - byte*2;

    unsigned char val = ival;

    unsigned char *dest_end = dest + dest_len;

    GetBitContext gb;



    if (ptr_len < 0)

        return AVERROR_INVALIDDATA;



    init_get_bits(&gb, ptr, ptr_len * 8);



    while ( val != 0x16 ) {

        val = src[val - 0x17 + get_bits1(&gb) * byte];



        if ( val < 0x16 ) {

            if (dest >= dest_end)

                return 0;

            *dest++ = val;

            val = ival;

        }

    }



    return 0;

}

static int xan_huffman_decode(uint8_t *dest, int dest_len,

                              const uint8_t *src, int src_len)

{

    uint8_t byte = *src++;

    uint8_t ival = byte + 0x16;

    const uint8_t * ptr = src + byte*2;

    int ptr_len = src_len - 1 - byte*2;

    uint8_t val = ival;

    uint8_t *dest_end = dest + dest_len;

    uint8_t *dest_start = dest;

    int ret;

    GetBitContext gb;



    if ((ret = init_get_bits8(&gb, ptr, ptr_len)) < 0)

        return ret;



    while (val != 0x16) {

        unsigned idx = val - 0x17 + get_bits1(&gb) * byte;

        if (idx >= 2 * byte)

            return AVERROR_INVALIDDATA;

        val = src[idx];



        if (val < 0x16) {

            if (dest >= dest_end)

                return dest_len;

            *dest++ = val;

            val = ival;

        }

    }



    return dest - dest_start;

}

