static int vqf_read_header(AVFormatContext *s)

{

    VqfContext *c = s->priv_data;

    AVStream *st  = avformat_new_stream(s, NULL);

    int chunk_tag;

    int rate_flag = -1;

    int header_size;

    int read_bitrate = 0;

    int size;

    uint8_t comm_chunk[12];



    if (!st)

        return AVERROR(ENOMEM);



    avio_skip(s->pb, 12);



    header_size = avio_rb32(s->pb);



    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id   = AV_CODEC_ID_TWINVQ;

    st->start_time = 0;



    do {

        int len;

        chunk_tag = avio_rl32(s->pb);



        if (chunk_tag == MKTAG('D','A','T','A'))

            break;



        len = avio_rb32(s->pb);



        if ((unsigned) len > INT_MAX/2) {

            av_log(s, AV_LOG_ERROR, "Malformed header\n");





        header_size -= 8;



        switch(chunk_tag){

        case MKTAG('C','O','M','M'):

            avio_read(s->pb, comm_chunk, 12);

            st->codec->channels = AV_RB32(comm_chunk    ) + 1;

            read_bitrate        = AV_RB32(comm_chunk + 4);

            rate_flag           = AV_RB32(comm_chunk + 8);

            avio_skip(s->pb, len-12);



            st->codec->bit_rate              = read_bitrate*1000;

            break;

        case MKTAG('D','S','I','Z'): // size of compressed data

        {

            char buf[8] = {0};

            int size = avio_rb32(s->pb);



            snprintf(buf, sizeof(buf), "%d", size);

            av_dict_set(&s->metadata, "size", buf, 0);


            break;

        case MKTAG('Y','E','A','R'): // recording date

        case MKTAG('E','N','C','D'): // compression date

        case MKTAG('E','X','T','R'): // reserved

        case MKTAG('_','Y','M','H'): // reserved

        case MKTAG('_','N','T','T'): // reserved

        case MKTAG('_','I','D','3'): // reserved for ID3 tags

            avio_skip(s->pb, FFMIN(len, header_size));

            break;

        default:

            add_metadata(s, chunk_tag, len, header_size);

            break;




        header_size -= len;



    } while (header_size >= 0);



    switch (rate_flag) {

    case -1:

        av_log(s, AV_LOG_ERROR, "COMM tag not found!\n");


    case 44:

        st->codec->sample_rate = 44100;

        break;

    case 22:

        st->codec->sample_rate = 22050;

        break;

    case 11:

        st->codec->sample_rate = 11025;

        break;

    default:

        st->codec->sample_rate = rate_flag*1000;





        break;




    switch (((st->codec->sample_rate/1000) << 8) +

            read_bitrate/st->codec->channels) {

    case (11<<8) + 8 :

    case (8 <<8) + 8 :

    case (11<<8) + 10:

    case (22<<8) + 32:

        size = 512;

        break;

    case (16<<8) + 16:

    case (22<<8) + 20:

    case (22<<8) + 24:

        size = 1024;

        break;

    case (44<<8) + 40:

    case (44<<8) + 48:

        size = 2048;

        break;

    default:

        av_log(s, AV_LOG_ERROR, "Mode not suported: %d Hz, %d kb/s.\n",

               st->codec->sample_rate, st->codec->bit_rate);



    c->frame_bit_len = st->codec->bit_rate*size/st->codec->sample_rate;

    avpriv_set_pts_info(st, 64, size, st->codec->sample_rate);



    /* put first 12 bytes of COMM chunk in extradata */

    if (!(st->codec->extradata = av_malloc(12 + FF_INPUT_BUFFER_PADDING_SIZE)))

        return AVERROR(ENOMEM);

    st->codec->extradata_size = 12;

    memcpy(st->codec->extradata, comm_chunk, 12);



    ff_metadata_conv_ctx(s, NULL, vqf_metadata_conv);



    return 0;

static int tak_read_header(AVFormatContext *s)

{

    TAKDemuxContext *tc = s->priv_data;

    AVIOContext *pb     = s->pb;

    GetBitContext gb;

    AVStream *st;

    uint8_t *buffer = NULL;

    int ret;



    st = avformat_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id   = AV_CODEC_ID_TAK;

    st->need_parsing      = AVSTREAM_PARSE_FULL_RAW;



    tc->mlast_frame = 0;

    if (avio_rl32(pb) != MKTAG('t', 'B', 'a', 'K')) {

        avio_seek(pb, -4, SEEK_CUR);

        return 0;

    }



    while (!url_feof(pb)) {

        enum TAKMetaDataType type;

        int size;



        type = avio_r8(pb) & 0x7f;

        size = avio_rl24(pb);



        switch (type) {

        case TAK_METADATA_STREAMINFO:

        case TAK_METADATA_LAST_FRAME:

        case TAK_METADATA_ENCODER:

            if (size <= 3)

                return AVERROR_INVALIDDATA;



            buffer = av_malloc(size - 3 + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!buffer)

                return AVERROR(ENOMEM);




            ffio_init_checksum(pb, tak_check_crc, 0xCE04B7U);

            if (avio_read(pb, buffer, size - 3) != size - 3) {

                av_freep(&buffer);

                return AVERROR(EIO);

            }

            if (ffio_get_checksum(s->pb) != avio_rb24(pb)) {

                av_log(s, AV_LOG_ERROR, "%d metadata block CRC error.\n", type);

                if (s->error_recognition & AV_EF_EXPLODE) {

                    av_freep(&buffer);

                    return AVERROR_INVALIDDATA;

                }

            }



            init_get_bits8(&gb, buffer, size - 3);

            break;

        case TAK_METADATA_MD5: {

            uint8_t md5[16];

            int i;



            if (size != 19)

                return AVERROR_INVALIDDATA;

            ffio_init_checksum(pb, tak_check_crc, 0xCE04B7U);

            avio_read(pb, md5, 16);

            if (ffio_get_checksum(s->pb) != avio_rb24(pb)) {

                av_log(s, AV_LOG_ERROR, "MD5 metadata block CRC error.\n");

                if (s->error_recognition & AV_EF_EXPLODE)

                    return AVERROR_INVALIDDATA;

            }



            av_log(s, AV_LOG_VERBOSE, "MD5=");

            for (i = 0; i < 16; i++)

                av_log(s, AV_LOG_VERBOSE, "%02x", md5[i]);

            av_log(s, AV_LOG_VERBOSE, "\n");

            break;

        }

        case TAK_METADATA_END: {

            int64_t curpos = avio_tell(pb);



            if (pb->seekable) {

                ff_ape_parse_tag(s);

                avio_seek(pb, curpos, SEEK_SET);

            }



            tc->data_end += curpos;

            return 0;

        }

        default:

            ret = avio_skip(pb, size);

            if (ret < 0)

                return ret;

        }



        if (type == TAK_METADATA_STREAMINFO) {

            TAKStreamInfo ti;



            avpriv_tak_parse_streaminfo(&gb, &ti);

            if (ti.samples > 0)

                st->duration = ti.samples;

            st->codec->bits_per_coded_sample = ti.bps;

            if (ti.ch_layout)

                st->codec->channel_layout = ti.ch_layout;

            st->codec->sample_rate           = ti.sample_rate;

            st->codec->channels              = ti.channels;

            st->start_time                   = 0;

            avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);

            st->codec->extradata             = buffer;

            st->codec->extradata_size        = size - 3;

            buffer                           = NULL;

        } else if (type == TAK_METADATA_LAST_FRAME) {

            if (size != 11)

                return AVERROR_INVALIDDATA;

            tc->mlast_frame = 1;

            tc->data_end    = get_bits64(&gb, TAK_LAST_FRAME_POS_BITS) +

                              get_bits(&gb, TAK_LAST_FRAME_SIZE_BITS);

            av_freep(&buffer);

        } else if (type == TAK_METADATA_ENCODER) {

            av_log(s, AV_LOG_VERBOSE, "encoder version: %0X\n",

                   get_bits_long(&gb, TAK_ENCODER_VERSION_BITS));

            av_freep(&buffer);

        }

    }



    return AVERROR_EOF;

}

static int tak_read_header(AVFormatContext *s)

{

    TAKDemuxContext *tc = s->priv_data;

    AVIOContext *pb     = s->pb;

    GetBitContext gb;

    AVStream *st;

    uint8_t *buffer = NULL;

    int ret;



    st = avformat_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id   = AV_CODEC_ID_TAK;

    st->need_parsing      = AVSTREAM_PARSE_FULL_RAW;



    tc->mlast_frame = 0;

    if (avio_rl32(pb) != MKTAG('t', 'B', 'a', 'K')) {

        avio_seek(pb, -4, SEEK_CUR);

        return 0;

    }



    while (!url_feof(pb)) {

        enum TAKMetaDataType type;

        int size;



        type = avio_r8(pb) & 0x7f;

        size = avio_rl24(pb);



        switch (type) {

        case TAK_METADATA_STREAMINFO:

        case TAK_METADATA_LAST_FRAME:

        case TAK_METADATA_ENCODER:

            buffer = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!buffer)

                return AVERROR(ENOMEM);



            if (avio_read(pb, buffer, size) != size) {

                av_freep(&buffer);

                return AVERROR(EIO);

            }



            init_get_bits(&gb, buffer, size * 8);

            break;

        case TAK_METADATA_MD5: {

            uint8_t md5[16];

            int i;



            if (size != 19)

                return AVERROR_INVALIDDATA;

            avio_read(pb, md5, 16);

            avio_skip(pb, 3);

            av_log(s, AV_LOG_VERBOSE, "MD5=");

            for (i = 0; i < 16; i++)

                av_log(s, AV_LOG_VERBOSE, "%02x", md5[i]);

            av_log(s, AV_LOG_VERBOSE, "\n");

            break;

        }

        case TAK_METADATA_END: {

            int64_t curpos = avio_tell(pb);



            if (pb->seekable) {

                ff_ape_parse_tag(s);

                avio_seek(pb, curpos, SEEK_SET);

            }



            tc->data_end += curpos;

            return 0;

        }

        default:

            ret = avio_skip(pb, size);

            if (ret < 0)

                return ret;

        }



        if (type == TAK_METADATA_STREAMINFO) {

            TAKStreamInfo ti;



            avpriv_tak_parse_streaminfo(&gb, &ti);

            if (ti.samples > 0)

                st->duration = ti.samples;

            st->codec->bits_per_coded_sample = ti.bps;

            if (ti.ch_layout)

                st->codec->channel_layout = ti.ch_layout;

            st->codec->sample_rate           = ti.sample_rate;

            st->codec->channels              = ti.channels;

            st->start_time                   = 0;

            avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);

            st->codec->extradata             = buffer;

            st->codec->extradata_size        = size;

            buffer                           = NULL;

        } else if (type == TAK_METADATA_LAST_FRAME) {

            if (size != 11)

                return AVERROR_INVALIDDATA;

            tc->mlast_frame = 1;

            tc->data_end    = get_bits64(&gb, TAK_LAST_FRAME_POS_BITS) +

                              get_bits(&gb, TAK_LAST_FRAME_SIZE_BITS);

            av_freep(&buffer);

        } else if (type == TAK_METADATA_ENCODER) {

            av_log(s, AV_LOG_VERBOSE, "encoder version: %0X\n",

                   get_bits_long(&gb, TAK_ENCODER_VERSION_BITS));

            av_freep(&buffer);

        }

    }



    return AVERROR_EOF;

}

static int wsvqa_read_header(AVFormatContext *s)

{

    WsVqaDemuxContext *wsvqa = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    unsigned char *header;

    unsigned char scratch[VQA_PREAMBLE_SIZE];

    unsigned int chunk_tag;

    unsigned int chunk_size;

    int fps;



    /* initialize the video decoder stream */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->start_time = 0;

    wsvqa->video_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_WS_VQA;

    st->codec->codec_tag = 0;  /* no fourcc */



    /* skip to the start of the VQA header */

    avio_seek(pb, 20, SEEK_SET);



    /* the VQA header needs to go to the decoder */

    st->codec->extradata_size = VQA_HEADER_SIZE;

    st->codec->extradata = av_mallocz(VQA_HEADER_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

    header = (unsigned char *)st->codec->extradata;

    if (avio_read(pb, st->codec->extradata, VQA_HEADER_SIZE) !=

        VQA_HEADER_SIZE) {

        av_free(st->codec->extradata);

        return AVERROR(EIO);

    }

    st->codec->width = AV_RL16(&header[6]);

    st->codec->height = AV_RL16(&header[8]);

    fps = header[12];

    st->nb_frames =

    st->duration  = AV_RL16(&header[4]);

    if (fps < 1 || fps > 30) {

        av_log(s, AV_LOG_ERROR, "invalid fps: %d\n", fps);

        return AVERROR_INVALIDDATA;

    }

    avpriv_set_pts_info(st, 64, 1, fps);



    wsvqa->version      = AV_RL16(&header[ 0]);

    wsvqa->sample_rate  = AV_RL16(&header[24]);

    wsvqa->channels     = header[26];

    wsvqa->bps          = header[27];

    wsvqa->audio_stream_index = -1;



    s->ctx_flags |= AVFMTCTX_NOHEADER;



    /* there are 0 or more chunks before the FINF chunk; iterate until

     * FINF has been skipped and the file will be ready to be demuxed */

    do {

        if (avio_read(pb, scratch, VQA_PREAMBLE_SIZE) != VQA_PREAMBLE_SIZE)

            return AVERROR(EIO);

        chunk_tag = AV_RB32(&scratch[0]);

        chunk_size = AV_RB32(&scratch[4]);



        /* catch any unknown header tags, for curiousity */

        switch (chunk_tag) {

        case CINF_TAG:

        case CINH_TAG:

        case CIND_TAG:

        case PINF_TAG:

        case PINH_TAG:

        case PIND_TAG:

        case FINF_TAG:

        case CMDS_TAG:

            break;



        default:

            av_log (s, AV_LOG_ERROR, " note: unknown chunk seen (%c%c%c%c)\n",

                scratch[0], scratch[1],

                scratch[2], scratch[3]);

            break;

        }



        avio_skip(pb, chunk_size);

    } while (chunk_tag != FINF_TAG);



    return 0;

}

static int ftp_send_command(FTPContext *s, const char *command,
                            const int response_codes[], char **response)
{
    int err;
    ff_dlog(s, "%s", command);
    if (response)
        *response = NULL;
    if ((err = ffurl_write(s->conn_control, command, strlen(command))) < 0)
        return err;
    if (!err)
        return -1;
    /* return status */
    if (response_codes) {
        return ftp_status(s, response, response_codes);
    }
    return 0;
}

static int ftp_status(FTPContext *s, char **line, const int response_codes[])

{

    int err, i, result = 0, pref_code_found = 0, wait_count = 100;

    char buf[CONTROL_BUFFER_SIZE];



    /* Set blocking mode */

    s->conn_control_block_flag = 0;

    for (;;) {

        if ((err = ftp_get_line(s, buf, sizeof(buf))) < 0) {

            if (err == AVERROR_EXIT) {

                if (!pref_code_found && wait_count--) {

                    av_usleep(10000);

                    continue;

                }

            }

            return result;

        }



        av_log(s, AV_LOG_DEBUG, "%s\n", buf);



        if (!pref_code_found) {

            if (strlen(buf) < 3)

                continue;



            err = 0;

            for (i = 0; i < 3; ++i) {

                if (buf[i] < '0' || buf[i] > '9')

                    continue;

                err *= 10;

                err += buf[i] - '0';

            }



            for (i = 0; response_codes[i]; ++i) {

                if (err == response_codes[i]) {

                    /* first code received. Now get all lines in non blocking mode */

                    s->conn_control_block_flag = 1;

                    pref_code_found = 1;

                    result = err;

                    if (line)

                        *line = av_strdup(buf);

                    break;

                }

            }

        }

    }

    return result;

}

static int ftp_flush_control_input(FTPContext *s)

{

    char buf[CONTROL_BUFFER_SIZE];

    int err, ori_block_flag = s->conn_control_block_flag;



    s->conn_control_block_flag = 1;

    do {

        err = ftp_get_line(s, buf, sizeof(buf));

    } while (!err);



    s->conn_control_block_flag = ori_block_flag;



    if (err < 0 && err != AVERROR_EXIT)

        return err;



    return 0;

}

static int ftp_auth(FTPContext *s, char *auth)

{

    const char *user = NULL, *pass = NULL;

    char *end = NULL, buf[CONTROL_BUFFER_SIZE];

    int err;

    av_assert2(auth);



    user = av_strtok(auth, ":", &end);

    pass = av_strtok(end, ":", &end);



    if (user) {

        snprintf(buf, sizeof(buf), "USER %s\r\n", user);

        if ((err = ffurl_write(s->conn_control, buf, strlen(buf))) < 0)

            return err;

        ftp_status(s, &err, NULL, NULL, NULL, -1);

        if (err == 3) {

            if (pass) {

                snprintf(buf, sizeof(buf), "PASS %s\r\n", pass);

                if ((err = ffurl_write(s->conn_control, buf, strlen(buf))) < 0)

                    return err;

                ftp_status(s, &err, NULL, NULL, NULL, -1);

            } else

                return AVERROR(EACCES);

        }

        if (err != 2) {

            return AVERROR(EACCES);

        }

    } else {

        const char* command = "USER anonymous\r\n";

        if ((err = ffurl_write(s->conn_control, command, strlen(command))) < 0)

            return err;

        ftp_status(s, &err, NULL, NULL, NULL, -1);

        if (err == 3) {

            if (s->anonymous_password) {

                snprintf(buf, sizeof(buf), "PASS %s\r\n", s->anonymous_password);

            } else

                snprintf(buf, sizeof(buf), "PASS nopassword\r\n");

            if ((err = ffurl_write(s->conn_control, buf, strlen(buf))) < 0)

                return err;

            ftp_status(s, &err, NULL, NULL, NULL, -1);

        }

        if (err != 2) {

            return AVERROR(EACCES);

        }

    }



    return 0;

}

static uint64_t strongarm_gpio_read(void *opaque, hwaddr offset,

                                    unsigned size)

{

    StrongARMGPIOInfo *s = opaque;



    switch (offset) {

    case GPDR:        /* GPIO Pin-Direction registers */

        return s->dir;



    case GPSR:        /* GPIO Pin-Output Set registers */

        DPRINTF("%s: Read from a write-only register 0x" TARGET_FMT_plx "\n",

                        __func__, offset);

        return s->gpsr;    /* Return last written value.  */



    case GPCR:        /* GPIO Pin-Output Clear registers */

        DPRINTF("%s: Read from a write-only register 0x" TARGET_FMT_plx "\n",

                        __func__, offset);

        return 31337;        /* Specified as unpredictable in the docs.  */



    case GRER:        /* GPIO Rising-Edge Detect Enable registers */

        return s->rising;



    case GFER:        /* GPIO Falling-Edge Detect Enable registers */

        return s->falling;



    case GAFR:        /* GPIO Alternate Function registers */

        return s->gafr;



    case GPLR:        /* GPIO Pin-Level registers */

        return (s->olevel & s->dir) |

               (s->ilevel & ~s->dir);



    case GEDR:        /* GPIO Edge Detect Status registers */

        return s->status;



    default:

        printf("%s: Bad offset 0x" TARGET_FMT_plx "\n", __func__, offset);

    }



    return 0;

}

static uint64_t arm_sysctl_read(void *opaque, target_phys_addr_t offset,

                                unsigned size)

{

    arm_sysctl_state *s = (arm_sysctl_state *)opaque;



    switch (offset) {

    case 0x00: /* ID */

        return s->sys_id;

    case 0x04: /* SW */

        /* General purpose hardware switches.

           We don't have a useful way of exposing these to the user.  */

        return 0;

    case 0x08: /* LED */

        return s->leds;

    case 0x20: /* LOCK */

        return s->lockval;

    case 0x0c: /* OSC0 */

    case 0x10: /* OSC1 */

    case 0x14: /* OSC2 */

    case 0x18: /* OSC3 */

    case 0x1c: /* OSC4 */

    case 0x24: /* 100HZ */

        /* ??? Implement these.  */

        return 0;

    case 0x28: /* CFGDATA1 */

        return s->cfgdata1;

    case 0x2c: /* CFGDATA2 */

        return s->cfgdata2;

    case 0x30: /* FLAGS */

        return s->flags;

    case 0x38: /* NVFLAGS */

        return s->nvflags;

    case 0x40: /* RESETCTL */

        if (board_id(s) == BOARD_ID_VEXPRESS) {

            /* reserved: RAZ/WI */

            return 0;

        }

        return s->resetlevel;

    case 0x44: /* PCICTL */

        return 1;

    case 0x48: /* MCI */

        return s->sys_mci;

    case 0x4c: /* FLASH */

        return 0;

    case 0x50: /* CLCD */

        return s->sys_clcd;

    case 0x54: /* CLCDSER */

        return 0;

    case 0x58: /* BOOTCS */

        return 0;

    case 0x5c: /* 24MHz */

        return muldiv64(qemu_get_clock_ns(vm_clock), 24000000, get_ticks_per_sec());

    case 0x60: /* MISC */

        return 0;

    case 0x84: /* PROCID0 */

        return s->proc_id;

    case 0x88: /* PROCID1 */

        return 0xff000000;

    case 0x64: /* DMAPSR0 */

    case 0x68: /* DMAPSR1 */

    case 0x6c: /* DMAPSR2 */

    case 0x70: /* IOSEL */

    case 0x74: /* PLDCTL */

    case 0x80: /* BUSID */

    case 0x8c: /* OSCRESET0 */

    case 0x90: /* OSCRESET1 */

    case 0x94: /* OSCRESET2 */

    case 0x98: /* OSCRESET3 */

    case 0x9c: /* OSCRESET4 */

    case 0xc0: /* SYS_TEST_OSC0 */

    case 0xc4: /* SYS_TEST_OSC1 */

    case 0xc8: /* SYS_TEST_OSC2 */

    case 0xcc: /* SYS_TEST_OSC3 */

    case 0xd0: /* SYS_TEST_OSC4 */

        return 0;

    case 0xa0: /* SYS_CFGDATA */

        if (board_id(s) != BOARD_ID_VEXPRESS) {

            goto bad_reg;

        }

        return s->sys_cfgdata;

    case 0xa4: /* SYS_CFGCTRL */

        if (board_id(s) != BOARD_ID_VEXPRESS) {

            goto bad_reg;

        }

        return s->sys_cfgctrl;

    case 0xa8: /* SYS_CFGSTAT */

        if (board_id(s) != BOARD_ID_VEXPRESS) {

            goto bad_reg;

        }

        return s->sys_cfgstat;

    default:

    bad_reg:

        printf ("arm_sysctl_read: Bad register offset 0x%x\n", (int)offset);

        return 0;

    }

}

static uint32_t cadence_ttc_read_imp(void *opaque, target_phys_addr_t offset)

{

    CadenceTimerState *s = cadence_timer_from_addr(opaque, offset);

    uint32_t value;



    cadence_timer_sync(s);

    cadence_timer_run(s);



    switch (offset) {

    case 0x00: /* clock control */

    case 0x04:

    case 0x08:

        return s->reg_clock;



    case 0x0c: /* counter control */

    case 0x10:

    case 0x14:

        return s->reg_count;



    case 0x18: /* counter value */

    case 0x1c:

    case 0x20:

        return (uint16_t)(s->reg_value >> 16);



    case 0x24: /* reg_interval counter */

    case 0x28:

    case 0x2c:

        return s->reg_interval;



    case 0x30: /* match 1 counter */

    case 0x34:

    case 0x38:

        return s->reg_match[0];



    case 0x3c: /* match 2 counter */

    case 0x40:

    case 0x44:

        return s->reg_match[1];



    case 0x48: /* match 3 counter */

    case 0x4c:

    case 0x50:

        return s->reg_match[2];



    case 0x54: /* interrupt register */

    case 0x58:

    case 0x5c:

        /* cleared after read */

        value = s->reg_intr;

        s->reg_intr = 0;

        cadence_timer_update(s);

        return value;



    case 0x60: /* interrupt enable */

    case 0x64:

    case 0x68:

        return s->reg_intr_en;



    case 0x6c:

    case 0x70:

    case 0x74:

        return s->reg_event_ctrl;



    case 0x78:

    case 0x7c:

    case 0x80:

        return s->reg_event;



    default:

        return 0;

    }

}

static uint64_t omap_tcmi_read(void *opaque, target_phys_addr_t addr,

                               unsigned size)

{

    struct omap_mpu_state_s *s = (struct omap_mpu_state_s *) opaque;

    uint32_t ret;



    if (size != 4) {

        return omap_badwidth_read32(opaque, addr);

    }



    switch (addr) {

    case 0x00:	/* IMIF_PRIO */

    case 0x04:	/* EMIFS_PRIO */

    case 0x08:	/* EMIFF_PRIO */

    case 0x0c:	/* EMIFS_CONFIG */

    case 0x10:	/* EMIFS_CS0_CONFIG */

    case 0x14:	/* EMIFS_CS1_CONFIG */

    case 0x18:	/* EMIFS_CS2_CONFIG */

    case 0x1c:	/* EMIFS_CS3_CONFIG */

    case 0x24:	/* EMIFF_MRS */

    case 0x28:	/* TIMEOUT1 */

    case 0x2c:	/* TIMEOUT2 */

    case 0x30:	/* TIMEOUT3 */

    case 0x3c:	/* EMIFF_SDRAM_CONFIG_2 */

    case 0x40:	/* EMIFS_CFG_DYN_WAIT */

        return s->tcmi_regs[addr >> 2];



    case 0x20:	/* EMIFF_SDRAM_CONFIG */

        ret = s->tcmi_regs[addr >> 2];

        s->tcmi_regs[addr >> 2] &= ~1; /* XXX: Clear SLRF on SDRAM access */

        /* XXX: We can try using the VGA_DIRTY flag for this */

        return ret;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static void tcg_handle_interrupt(CPUState *cpu, int mask)

{

    int old_mask;



    old_mask = cpu->interrupt_request;

    cpu->interrupt_request |= mask;



    /*

     * If called from iothread context, wake the target cpu in

     * case its halted.

     */

    if (!qemu_cpu_is_self(cpu)) {

        qemu_cpu_kick(cpu);

        return;

    }



    if (use_icount) {

        cpu->icount_decr.u16.high = 0xffff;

        if (!cpu->can_do_io

            && (mask & ~old_mask) != 0) {

            cpu_abort(cpu, "Raised interrupt while not in I/O function");

        }

    } else {

        cpu->tcg_exit_req = 1;

    }

}

