static int encode_ext_header(Wmv2Context *w){

    MpegEncContext * const s= &w->s;

    PutBitContext pb;

    int code;



    init_put_bits(&pb, s->avctx->extradata, s->avctx->extradata_size);



    put_bits(&pb, 5, s->avctx->time_base.den / s->avctx->time_base.num); //yes 29.97 -> 29

    put_bits(&pb, 11, FFMIN(s->bit_rate/1024, 2047));



    put_bits(&pb, 1, w->mspel_bit=1);

    put_bits(&pb, 1, w->flag3=1);

    put_bits(&pb, 1, w->abt_flag=1);

    put_bits(&pb, 1, w->j_type_bit=1);

    put_bits(&pb, 1, w->top_left_mv_flag=0);

    put_bits(&pb, 1, w->per_mb_rl_bit=1);

    put_bits(&pb, 3, code=1);



    flush_put_bits(&pb);



    s->slice_height = s->mb_height / code;



    return 0;

}

int av_interleave_packet_per_dts(AVFormatContext *s, AVPacket *out, AVPacket *pkt, int flush){

    AVPacketList *pktl;

    int stream_count=0, noninterleaved_count=0;

    int64_t delta_dts_max = 0;

    int i;



    if(pkt){

        ff_interleave_add_packet(s, pkt, ff_interleave_compare_dts);

    }



    for(i=0; i < s->nb_streams; i++) {

        if (s->streams[i]->last_in_packet_buffer) {

            ++stream_count;

        } else if(s->streams[i]->codec->codec_type == AVMEDIA_TYPE_SUBTITLE) {

            ++noninterleaved_count;

        }

    }



    if (s->nb_streams == stream_count) {

        flush = 1;

    } else if (!flush){

        for(i=0; i < s->nb_streams; i++) {

            if (s->streams[i]->last_in_packet_buffer) {

                int64_t delta_dts =

                    av_rescale_q(s->streams[i]->last_in_packet_buffer->pkt.dts,

                                s->streams[i]->time_base,

                                AV_TIME_BASE_Q) -

                    av_rescale_q(s->packet_buffer->pkt.dts,

                                s->streams[s->packet_buffer->pkt.stream_index]->time_base,

                                AV_TIME_BASE_Q);

                delta_dts_max= FFMAX(delta_dts_max, delta_dts);

            }

        }

        if(s->nb_streams == stream_count+noninterleaved_count &&

           delta_dts_max > 20*AV_TIME_BASE) {

            av_log(s, AV_LOG_DEBUG, "flushing with %d noninterleaved\n", noninterleaved_count);

            flush = 1;

        }

    }

    if(stream_count && flush){

        pktl= s->packet_buffer;

        *out= pktl->pkt;



        s->packet_buffer= pktl->next;

        if(!s->packet_buffer)

            s->packet_buffer_end= NULL;



        if(s->streams[out->stream_index]->last_in_packet_buffer == pktl)

            s->streams[out->stream_index]->last_in_packet_buffer= NULL;

        av_freep(&pktl);

        return 1;

    }else{

        av_init_packet(out);

        return 0;

    }

}

static int decode_audio(InputStream *ist, AVPacket *pkt, int *got_output)

{

    AVFrame *decoded_frame, *f;

    AVCodecContext *avctx = ist->dec_ctx;

    int i, ret, err = 0;



    if (!ist->decoded_frame && !(ist->decoded_frame = av_frame_alloc()))

        return AVERROR(ENOMEM);

    if (!ist->filter_frame && !(ist->filter_frame = av_frame_alloc()))

        return AVERROR(ENOMEM);

    decoded_frame = ist->decoded_frame;



    ret = decode(avctx, decoded_frame, got_output, pkt);

    if (!*got_output || ret < 0)

        return ret;



    ist->samples_decoded += decoded_frame->nb_samples;

    ist->frames_decoded++;



    /* if the decoder provides a pts, use it instead of the last packet pts.

       the decoder could be delaying output by a packet or more. */

    if (decoded_frame->pts != AV_NOPTS_VALUE)

        ist->next_dts = decoded_frame->pts;

    else if (pkt && pkt->pts != AV_NOPTS_VALUE) {

        decoded_frame->pts = pkt->pts;

    }



    if (decoded_frame->pts != AV_NOPTS_VALUE)

        decoded_frame->pts = av_rescale_q(decoded_frame->pts,

                                          ist->st->time_base,

                                          (AVRational){1, avctx->sample_rate});

    ist->nb_samples = decoded_frame->nb_samples;

    for (i = 0; i < ist->nb_filters; i++) {

        if (i < ist->nb_filters - 1) {

            f = ist->filter_frame;

            err = av_frame_ref(f, decoded_frame);

            if (err < 0)

                break;

        } else

            f = decoded_frame;



        err = ifilter_send_frame(ist->filters[i], f);

        if (err < 0)

            break;

    }



    av_frame_unref(ist->filter_frame);

    av_frame_unref(decoded_frame);

    return err < 0 ? err : ret;

}

static int seek_frame_generic(AVFormatContext *s,

                                 int stream_index, int64_t timestamp, int flags)

{

    int index;

    int64_t ret;

    AVStream *st;

    AVIndexEntry *ie;



    st = s->streams[stream_index];



    index = av_index_search_timestamp(st, timestamp, flags);



    if(index < 0 && st->nb_index_entries && timestamp < st->index_entries[0].timestamp)

        return -1;



    if(index < 0 || index==st->nb_index_entries-1){

        AVPacket pkt;

        int nonkey=0;



        if(st->nb_index_entries){

            assert(st->index_entries);

            ie= &st->index_entries[st->nb_index_entries-1];

            if ((ret = avio_seek(s->pb, ie->pos, SEEK_SET)) < 0)

                return ret;

            ff_update_cur_dts(s, st, ie->timestamp);

        }else{

            if ((ret = avio_seek(s->pb, s->data_offset, SEEK_SET)) < 0)

                return ret;

        }

        for (;;) {

            int read_status;

            do{

                read_status = av_read_frame(s, &pkt);

            } while (read_status == AVERROR(EAGAIN));

            if (read_status < 0)

                break;

            av_free_packet(&pkt);

            if(stream_index == pkt.stream_index && pkt.dts > timestamp){

                if(pkt.flags & AV_PKT_FLAG_KEY)

                    break;

                if(nonkey++ > 1000){

                    av_log(s, AV_LOG_ERROR,"seek_frame_generic failed as this stream seems to contain no keyframes after the target timestamp, %d non keyframes found\n", nonkey);

                    break;

                }

            }

        }

        index = av_index_search_timestamp(st, timestamp, flags);

    }

    if (index < 0)

        return -1;



    ff_read_frame_flush(s);

    AV_NOWARN_DEPRECATED(

    if (s->iformat->read_seek){

        if(s->iformat->read_seek(s, stream_index, timestamp, flags) >= 0)

            return 0;

    }

    )

    ie = &st->index_entries[index];

    if ((ret = avio_seek(s->pb, ie->pos, SEEK_SET)) < 0)

        return ret;

    ff_update_cur_dts(s, st, ie->timestamp);



    return 0;

}

static void estimate_timings_from_pts(AVFormatContext *ic, int64_t old_offset)

{

    AVPacket pkt1, *pkt = &pkt1;

    AVStream *st;

    int read_size, i, ret;

    int64_t end_time;

    int64_t filesize, offset, duration;

    int retry = 0;



    /* flush packet queue */

    flush_packet_queue(ic);



    for (i = 0; i < ic->nb_streams; i++) {

        st = ic->streams[i];

        if (st->start_time == AV_NOPTS_VALUE &&

            st->first_dts == AV_NOPTS_VALUE &&

            st->codec->codec_type != AVMEDIA_TYPE_UNKNOWN)

            av_log(st->codec, AV_LOG_WARNING,

                   "start time for stream %d is not set in estimate_timings_from_pts\n", i);



        if (st->parser) {

            av_parser_close(st->parser);

            st->parser = NULL;

        }

    }



    /* estimate the end time (duration) */

    /* XXX: may need to support wrapping */

    filesize = ic->pb ? avio_size(ic->pb) : 0;

    end_time = AV_NOPTS_VALUE;

    do {

        offset = filesize - (DURATION_MAX_READ_SIZE << retry);

        if (offset < 0)

            offset = 0;



        avio_seek(ic->pb, offset, SEEK_SET);

        read_size = 0;

        for (;;) {

            if (read_size >= DURATION_MAX_READ_SIZE << (FFMAX(retry - 1, 0)))

                break;



            do {

                ret = ff_read_packet(ic, pkt);

            } while (ret == AVERROR(EAGAIN));

            if (ret != 0)

                break;

            read_size += pkt->size;

            st         = ic->streams[pkt->stream_index];

            if (pkt->pts != AV_NOPTS_VALUE &&

                (st->start_time != AV_NOPTS_VALUE ||

                 st->first_dts  != AV_NOPTS_VALUE)) {

                duration = end_time = pkt->pts + pkt->duration;

                if (st->start_time != AV_NOPTS_VALUE)

                    duration -= st->start_time;

                else

                    duration -= st->first_dts;

                if (duration > 0) {

                    if (st->duration == AV_NOPTS_VALUE || st->info->last_duration<= 0 ||

                        (st->duration < duration && FFABS(duration - st->info->last_duration) < 60LL*st->time_base.den / st->time_base.num))

                        st->duration = duration;

                    st->info->last_duration = duration;

                }

            }

            av_free_packet(pkt);

        }

    } while (end_time == AV_NOPTS_VALUE &&

             filesize > (DURATION_MAX_READ_SIZE << retry) &&

             ++retry <= DURATION_MAX_RETRY);



    /* warn about audio/video streams which duration could not be estimated */

    for (i = 0; i < ic->nb_streams; i++) {

        st = ic->streams[i];

        if (st->duration == AV_NOPTS_VALUE) {

            switch (st->codec->codec_type) {

            case AVMEDIA_TYPE_VIDEO:

            case AVMEDIA_TYPE_AUDIO:

                if (st->start_time != AV_NOPTS_VALUE || st->first_dts  != AV_NOPTS_VALUE) {

                    av_log(ic, AV_LOG_DEBUG, "stream %d : no PTS found at end of file, duration not set\n", i);

                } else

                    av_log(ic, AV_LOG_DEBUG, "stream %d : no TS found at start of file, duration not set\n", i);

            }

        }

    }

    fill_all_stream_timings(ic);



    avio_seek(ic->pb, old_offset, SEEK_SET);

    for (i = 0; i < ic->nb_streams; i++) {

        int j;



        st              = ic->streams[i];

        st->cur_dts     = st->first_dts;

        st->last_IP_pts = AV_NOPTS_VALUE;

        st->last_dts_for_order_check = AV_NOPTS_VALUE;

        for (j = 0; j < MAX_REORDER_DELAY + 1; j++)

            st->pts_buffer[j] = AV_NOPTS_VALUE;

    }

}

int attribute_align_arg avcodec_encode_audio(AVCodecContext *avctx,

                                             uint8_t *buf, int buf_size,

                                             const short *samples)

{

    AVPacket pkt;

    AVFrame *frame;

    int ret, samples_size, got_packet;



    av_init_packet(&pkt);

    pkt.data = buf;

    pkt.size = buf_size;



    if (samples) {

        frame = av_frame_alloc();





        if (avctx->frame_size) {

            frame->nb_samples = avctx->frame_size;

        } else {

            /* if frame_size is not set, the number of samples must be

             * calculated from the buffer size */

            int64_t nb_samples;

            if (!av_get_bits_per_sample(avctx->codec_id)) {

                av_log(avctx, AV_LOG_ERROR, "avcodec_encode_audio() does not "

                                            "support this codec\n");

                av_frame_free(&frame);

                return AVERROR(EINVAL);

            }

            nb_samples = (int64_t)buf_size * 8 /

                         (av_get_bits_per_sample(avctx->codec_id) *

                          avctx->channels);

            if (nb_samples >= INT_MAX) {

                av_frame_free(&frame);

                return AVERROR(EINVAL);

            }

            frame->nb_samples = nb_samples;

        }



        /* it is assumed that the samples buffer is large enough based on the

         * relevant parameters */

        samples_size = av_samples_get_buffer_size(NULL, avctx->channels,

                                                  frame->nb_samples,

                                                  avctx->sample_fmt, 1);

        if ((ret = avcodec_fill_audio_frame(frame, avctx->channels,

                                            avctx->sample_fmt,

                                            (const uint8_t *)samples,

                                            samples_size, 1)) < 0) {

            av_frame_free(&frame);

            return ret;

        }



        /* fabricate frame pts from sample count.

         * this is needed because the avcodec_encode_audio() API does not have

         * a way for the user to provide pts */

        if (avctx->sample_rate && avctx->time_base.num)

            frame->pts = ff_samples_to_time_base(avctx,

                                                 avctx->internal->sample_count);

        else

            frame->pts = AV_NOPTS_VALUE;

        avctx->internal->sample_count += frame->nb_samples;

    } else {

        frame = NULL;

    }



    got_packet = 0;

    ret = avcodec_encode_audio2(avctx, &pkt, frame, &got_packet);

    if (!ret && got_packet && avctx->coded_frame) {

        avctx->coded_frame->pts       = pkt.pts;

        avctx->coded_frame->key_frame = !!(pkt.flags & AV_PKT_FLAG_KEY);

    }

    /* free any side data since we cannot return it */

    av_packet_free_side_data(&pkt);



    if (frame && frame->extended_data != frame->data)

        av_freep(&frame->extended_data);



    av_frame_free(&frame);

    return ret ? ret : pkt.size;

}

int attribute_align_arg avcodec_encode_audio2(AVCodecContext *avctx,
                                              AVPacket *avpkt,
                                              const AVFrame *frame,
                                              int *got_packet_ptr)
{
    AVFrame *extended_frame = NULL;
    AVFrame *padded_frame = NULL;
    int ret;
    AVPacket user_pkt = *avpkt;
    int needs_realloc = !user_pkt.data;
    *got_packet_ptr = 0;
    if (!(avctx->codec->capabilities & AV_CODEC_CAP_DELAY) && !frame) {
        av_free_packet(avpkt);
        av_init_packet(avpkt);
        return 0;
    }
    /* ensure that extended_data is properly set */
    if (frame && !frame->extended_data) {
        if (av_sample_fmt_is_planar(avctx->sample_fmt) &&
            avctx->channels > AV_NUM_DATA_POINTERS) {
            av_log(avctx, AV_LOG_ERROR, "Encoding to a planar sample format, "
                                        "with more than %d channels, but extended_data is not set.\n",
                   AV_NUM_DATA_POINTERS);
            return AVERROR(EINVAL);
        }
        av_log(avctx, AV_LOG_WARNING, "extended_data is not set.\n");
        extended_frame = av_frame_alloc();
        if (!extended_frame)
            return AVERROR(ENOMEM);
        memcpy(extended_frame, frame, sizeof(AVFrame));
        extended_frame->extended_data = extended_frame->data;
        frame = extended_frame;
    }
    /* extract audio service type metadata */
    if (frame) {
        AVFrameSideData *sd = av_frame_get_side_data(frame, AV_FRAME_DATA_AUDIO_SERVICE_TYPE);
        if (sd && sd->size >= sizeof(enum AVAudioServiceType))
            avctx->audio_service_type = *(enum AVAudioServiceType*)sd->data;
    }
    /* check for valid frame size */
    if (frame) {
        if (avctx->codec->capabilities & AV_CODEC_CAP_SMALL_LAST_FRAME) {
            if (frame->nb_samples > avctx->frame_size) {
                av_log(avctx, AV_LOG_ERROR, "more samples than frame size (avcodec_encode_audio2)\n");
                ret = AVERROR(EINVAL);
                goto end;
            }
        } else if (!(avctx->codec->capabilities & AV_CODEC_CAP_VARIABLE_FRAME_SIZE)) {
            if (frame->nb_samples < avctx->frame_size &&
                !avctx->internal->last_audio_frame) {
                ret = pad_last_frame(avctx, &padded_frame, frame);
                if (ret < 0)
                    goto end;
                frame = padded_frame;
                avctx->internal->last_audio_frame = 1;
            }
            if (frame->nb_samples != avctx->frame_size) {
                av_log(avctx, AV_LOG_ERROR, "nb_samples (%d) != frame_size (%d) (avcodec_encode_audio2)\n", frame->nb_samples, avctx->frame_size);
                ret = AVERROR(EINVAL);
                goto end;
            }
        }
    }
    ret = avctx->codec->encode2(avctx, avpkt, frame, got_packet_ptr);
    if (!ret) {
        if (*got_packet_ptr) {
            if (!(avctx->codec->capabilities & AV_CODEC_CAP_DELAY)) {
                if (avpkt->pts == AV_NOPTS_VALUE)
                    avpkt->pts = frame->pts;
                if (!avpkt->duration)
                    avpkt->duration = ff_samples_to_time_base(avctx,
                                                              frame->nb_samples);
            }
            avpkt->dts = avpkt->pts;
        } else {
            avpkt->size = 0;
        }
    }
    if (avpkt->data && avpkt->data == avctx->internal->byte_buffer) {
        needs_realloc = 0;
        if (user_pkt.data) {
            if (user_pkt.size >= avpkt->size) {
                memcpy(user_pkt.data, avpkt->data, avpkt->size);
            } else {
                av_log(avctx, AV_LOG_ERROR, "Provided packet is too small, needs to be %d\n", avpkt->size);
                avpkt->size = user_pkt.size;
                ret = -1;
            }
            avpkt->buf      = user_pkt.buf;
            avpkt->data     = user_pkt.data;
#if FF_API_DESTRUCT_PACKET
FF_DISABLE_DEPRECATION_WARNINGS
            avpkt->destruct = user_pkt.destruct;
FF_ENABLE_DEPRECATION_WARNINGS
#endif
        } else {
            if (av_dup_packet(avpkt) < 0) {
                ret = AVERROR(ENOMEM);
            }
        }
    }
    if (!ret) {
        if (needs_realloc && avpkt->data) {
            ret = av_buffer_realloc(&avpkt->buf, avpkt->size + AV_INPUT_BUFFER_PADDING_SIZE);
            if (ret >= 0)
                avpkt->data = avpkt->buf->data;
        }
        avctx->frame_number++;
    }
    if (ret < 0 || !*got_packet_ptr) {
        av_free_packet(avpkt);
        av_init_packet(avpkt);
        goto end;
    }
    /* NOTE: if we add any audio encoders which output non-keyframe packets,
     *       this needs to be moved to the encoders, but for now we can do it
     *       here to simplify things */
    avpkt->flags |= AV_PKT_FLAG_KEY;
end:
    av_frame_free(&padded_frame);
    av_free(extended_frame);
#if FF_API_AUDIOENC_DELAY
    avctx->delay = avctx->initial_padding;
#endif
    return ret;
}

int attribute_align_arg avcodec_encode_audio(AVCodecContext *avctx,

                                             uint8_t *buf, int buf_size,

                                             const short *samples)

{

    AVPacket pkt;

    AVFrame frame0 = { 0 };

    AVFrame *frame;

    int ret, samples_size, got_packet;



    av_init_packet(&pkt);

    pkt.data = buf;

    pkt.size = buf_size;



    if (samples) {

        frame = &frame0;

        avcodec_get_frame_defaults(frame);



        if (avctx->frame_size) {

            frame->nb_samples = avctx->frame_size;

        } else {

            /* if frame_size is not set, the number of samples must be

             * calculated from the buffer size */

            int64_t nb_samples;

            if (!av_get_bits_per_sample(avctx->codec_id)) {

                av_log(avctx, AV_LOG_ERROR, "avcodec_encode_audio() does not "

                                            "support this codec\n");

                return AVERROR(EINVAL);

            }

            nb_samples = (int64_t)buf_size * 8 /

                         (av_get_bits_per_sample(avctx->codec_id) *

                          avctx->channels);

            if (nb_samples >= INT_MAX)

                return AVERROR(EINVAL);

            frame->nb_samples = nb_samples;

        }



        /* it is assumed that the samples buffer is large enough based on the

         * relevant parameters */

        samples_size = av_samples_get_buffer_size(NULL, avctx->channels,

                                                  frame->nb_samples,

                                                  avctx->sample_fmt, 1);

        if ((ret = avcodec_fill_audio_frame(frame, avctx->channels,

                                            avctx->sample_fmt,

                                            (const uint8_t *)samples,

                                            samples_size, 1)))

            return ret;



        /* fabricate frame pts from sample count.

         * this is needed because the avcodec_encode_audio() API does not have

         * a way for the user to provide pts */

        if (avctx->sample_rate && avctx->time_base.num)

            frame->pts = ff_samples_to_time_base(avctx,

                                                 avctx->internal->sample_count);

        else

            frame->pts = AV_NOPTS_VALUE;

        avctx->internal->sample_count += frame->nb_samples;

    } else {

        frame = NULL;

    }



    got_packet = 0;

    ret = avcodec_encode_audio2(avctx, &pkt, frame, &got_packet);

    if (!ret && got_packet && avctx->coded_frame) {

        avctx->coded_frame->pts       = pkt.pts;

        avctx->coded_frame->key_frame = !!(pkt.flags & AV_PKT_FLAG_KEY);

    }

    /* free any side data since we cannot return it */

    ff_packet_free_side_data(&pkt);



    if (frame && frame->extended_data != frame->data)

        av_freep(&frame->extended_data);



    return ret ? ret : pkt.size;

}

int attribute_align_arg avcodec_decode_audio3(AVCodecContext *avctx, int16_t *samples,

                         int *frame_size_ptr,

                         AVPacket *avpkt)

{

    AVFrame frame;

    int ret, got_frame = 0;



    if (avctx->get_buffer != avcodec_default_get_buffer) {

        av_log(avctx, AV_LOG_ERROR, "A custom get_buffer() cannot be used with "

               "avcodec_decode_audio3()\n");

        return AVERROR(EINVAL);

    }



    ret = avcodec_decode_audio4(avctx, &frame, &got_frame, avpkt);



    if (ret >= 0 && got_frame) {

        int ch, plane_size;

        int planar = av_sample_fmt_is_planar(avctx->sample_fmt);

        int data_size = av_samples_get_buffer_size(&plane_size, avctx->channels,

                                                   frame.nb_samples,

                                                   avctx->sample_fmt, 1);

        if (*frame_size_ptr < data_size) {

            av_log(avctx, AV_LOG_ERROR, "output buffer size is too small for "

                   "the current frame (%d < %d)\n", *frame_size_ptr, data_size);

            return AVERROR(EINVAL);

        }



        memcpy(samples, frame.extended_data[0], plane_size);



        if (planar && avctx->channels > 1) {

            uint8_t *out = ((uint8_t *)samples) + plane_size;

            for (ch = 1; ch < avctx->channels; ch++) {

                memcpy(out, frame.extended_data[ch], plane_size);

                out += plane_size;

            }

        }

        *frame_size_ptr = data_size;

    } else {

        *frame_size_ptr = 0;

    }

    return ret;

}

void host_cpuid(uint32_t function, uint32_t count,

                uint32_t *eax, uint32_t *ebx, uint32_t *ecx, uint32_t *edx)

{

#if defined(CONFIG_KVM)

    uint32_t vec[4];



#ifdef __x86_64__

    asm volatile("cpuid"

                 : "=a"(vec[0]), "=b"(vec[1]),

                   "=c"(vec[2]), "=d"(vec[3])

                 : "0"(function), "c"(count) : "cc");

#else

    asm volatile("pusha \n\t"

                 "cpuid \n\t"

                 "mov %%eax, 0(%2) \n\t"

                 "mov %%ebx, 4(%2) \n\t"

                 "mov %%ecx, 8(%2) \n\t"

                 "mov %%edx, 12(%2) \n\t"

                 "popa"

                 : : "a"(function), "c"(count), "S"(vec)

                 : "memory", "cc");

#endif



    if (eax)

        *eax = vec[0];

    if (ebx)

        *ebx = vec[1];

    if (ecx)

        *ecx = vec[2];

    if (edx)

        *edx = vec[3];

#endif

}

static int libx265_encode_frame(AVCodecContext *avctx, AVPacket *pkt,
                                const AVFrame *pic, int *got_packet)
{
    libx265Context *ctx = avctx->priv_data;
    x265_picture x265pic;
    x265_picture x265pic_out = { { 0 } };
    x265_nal *nal;
    uint8_t *dst;
    int payload = 0;
    int nnal;
    int ret;
    int i;
    if (pic) {
        for (i = 0; i < 3; i++) {
           x265pic.planes[i] = pic->data[i];
           x265pic.stride[i] = pic->linesize[i];
        }
        x265pic.pts = pic->pts;
    }
    ret = x265_encoder_encode(ctx->encoder, &nal, &nnal,
                              pic ? &x265pic : NULL, &x265pic_out);
    if (ret < 0)
        return AVERROR_UNKNOWN;
    if (!nnal)
        return 0;
    for (i = 0; i < nnal; i++)
        payload += nal[i].sizeBytes;
    payload += ctx->header_size;
    ret = ff_alloc_packet(pkt, payload);
    if (ret < 0) {
        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");
        return ret;
    }
    dst = pkt->data;
    if (ctx->header) {
        memcpy(dst, ctx->header, ctx->header_size);
        dst += ctx->header_size;
        av_freep(&ctx->header);
        ctx->header_size = 0;
    }
    for (i = 0; i < nnal; i++) {
        memcpy(dst, nal[i].payload, nal[i].sizeBytes);
        dst += nal[i].sizeBytes;
        if (is_keyframe(nal[i].type))
            pkt->flags |= AV_PKT_FLAG_KEY;
    }
    pkt->pts = x265pic_out.pts;
    pkt->dts = x265pic_out.dts;
    *got_packet = 1;
    return 0;
}

static int overlay_opencl_blend(FFFrameSync *fs)

{

    AVFilterContext    *avctx = fs->parent;

    AVFilterLink     *outlink = avctx->outputs[0];

    OverlayOpenCLContext *ctx = avctx->priv;

    AVFrame *input_main, *input_overlay;

    AVFrame *output;

    cl_mem mem;

    cl_int cle, x, y;

    size_t global_work[2];

    int kernel_arg = 0;

    int err, plane;



    err = ff_framesync_get_frame(fs, 0, &input_main, 0);

    if (err < 0)

        return err;

    err = ff_framesync_get_frame(fs, 1, &input_overlay, 0);

    if (err < 0)

        return err;



    if (!ctx->initialised) {

        AVHWFramesContext *main_fc =

            (AVHWFramesContext*)input_main->hw_frames_ctx->data;

        AVHWFramesContext *overlay_fc =

            (AVHWFramesContext*)input_overlay->hw_frames_ctx->data;



        err = overlay_opencl_load(avctx, main_fc->sw_format,

                                  overlay_fc->sw_format);

        if (err < 0)

            return err;

    }



    output = ff_get_video_buffer(outlink, outlink->w, outlink->h);

    if (!output) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    for (plane = 0; plane < ctx->nb_planes; plane++) {

        kernel_arg = 0;



        mem = (cl_mem)output->data[plane];

        cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_mem), &mem);

        if (cle != CL_SUCCESS)

            goto fail_kernel_arg;



        mem = (cl_mem)input_main->data[plane];

        cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_mem), &mem);

        if (cle != CL_SUCCESS)

            goto fail_kernel_arg;



        mem = (cl_mem)input_overlay->data[plane];

        cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_mem), &mem);

        if (cle != CL_SUCCESS)

            goto fail_kernel_arg;



        if (ctx->alpha_separate) {

            mem = (cl_mem)input_overlay->data[ctx->nb_planes];

            cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_mem), &mem);

            if (cle != CL_SUCCESS)

                goto fail_kernel_arg;

        }



        x = ctx->x_position / (plane == 0 ? 1 : ctx->x_subsample);

        y = ctx->y_position / (plane == 0 ? 1 : ctx->y_subsample);



        cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_int), &x);

        if (cle != CL_SUCCESS)

            goto fail_kernel_arg;

        cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_int), &y);

        if (cle != CL_SUCCESS)

            goto fail_kernel_arg;



        if (ctx->alpha_separate) {

            cl_int alpha_adj_x = plane == 0 ? 1 : ctx->x_subsample;

            cl_int alpha_adj_y = plane == 0 ? 1 : ctx->y_subsample;



            cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_int), &alpha_adj_x);

            if (cle != CL_SUCCESS)

                goto fail_kernel_arg;

            cle = clSetKernelArg(ctx->kernel, kernel_arg++, sizeof(cl_int), &alpha_adj_y);

            if (cle != CL_SUCCESS)

                goto fail_kernel_arg;

        }



        global_work[0] = output->width;

        global_work[1] = output->height;



        cle = clEnqueueNDRangeKernel(ctx->command_queue, ctx->kernel, 2, NULL,

                                     global_work, NULL, 0, NULL, NULL);

        if (cle != CL_SUCCESS) {

            av_log(avctx, AV_LOG_ERROR, "Failed to enqueue "

                   "overlay kernel for plane %d: %d.\n", cle, plane);

            err = AVERROR(EIO);

            goto fail;

        }

    }



    cle = clFinish(ctx->command_queue);

    if (cle != CL_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to finish "

               "command queue: %d.\n", cle);

        err = AVERROR(EIO);

        goto fail;

    }



    err = av_frame_copy_props(output, input_main);



    av_log(avctx, AV_LOG_DEBUG, "Filter output: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(output->format),

           output->width, output->height, output->pts);



    return ff_filter_frame(outlink, output);



fail_kernel_arg:

    av_log(avctx, AV_LOG_ERROR, "Failed to set kernel arg %d: %d.\n",

           kernel_arg, cle);

    err = AVERROR(EIO);

fail:


    return err;

}

static int dxva2_get_decoder_configuration(AVCodecContext *s, const GUID *device_guid,

                                           const DXVA2_VideoDesc *desc,

                                           DXVA2_ConfigPictureDecode *config)

{

    InputStream  *ist = s->opaque;

    int loglevel = (ist->hwaccel_id == HWACCEL_AUTO) ? AV_LOG_VERBOSE : AV_LOG_ERROR;

    DXVA2Context *ctx = ist->hwaccel_ctx;

    unsigned cfg_count = 0, best_score = 0;

    DXVA2_ConfigPictureDecode *cfg_list = NULL;

    DXVA2_ConfigPictureDecode best_cfg = {{0}};

    HRESULT hr;

    int i;



    hr = IDirectXVideoDecoderService_GetDecoderConfigurations(ctx->decoder_service, device_guid, desc, NULL, &cfg_count, &cfg_list);

    if (FAILED(hr)) {

        av_log(NULL, loglevel, "Unable to retrieve decoder configurations\n");

        return AVERROR(EINVAL);

    }



    for (i = 0; i < cfg_count; i++) {

        DXVA2_ConfigPictureDecode *cfg = &cfg_list[i];



        unsigned score;

        if (cfg->ConfigBitstreamRaw == 1)

            score = 1;

        else if (s->codec_id == AV_CODEC_ID_H264 && cfg->ConfigBitstreamRaw == 2)

            score = 2;

        else

            continue;

        if (IsEqualGUID(&cfg->guidConfigBitstreamEncryption, &DXVA2_NoEncrypt))

            score += 16;

        if (score > best_score) {

            best_score = score;

            best_cfg   = *cfg;

        }

    }

    CoTaskMemFree(cfg_list);



    if (!best_score) {

        av_log(NULL, loglevel, "No valid decoder configuration available\n");

        return AVERROR(EINVAL);

    }



    *config = best_cfg;

    return 0;

}

static int nppscale_resize(AVFilterContext *ctx, NPPScaleStageContext *stage,

                           AVFrame *out, AVFrame *in)

{

    NPPScaleContext *s = ctx->priv;

    NppStatus err;

    int i;



    for (i = 0; i < FF_ARRAY_ELEMS(in->data) && in->data[i]; i++) {

        int iw = stage->planes_in[i].width;

        int ih = stage->planes_in[i].height;

        int ow = stage->planes_out[i].width;

        int oh = stage->planes_out[i].height;



        err = nppiResizeSqrPixel_8u_C1R(in->data[i], (NppiSize){ iw, ih },

                                        in->linesize[i], (NppiRect){ 0, 0, iw, ih },

                                        out->data[i], out->linesize[i],

                                        (NppiRect){ 0, 0, ow, oh },

                                        (double)ow / iw, (double)oh / ih,

                                        0.0, 0.0, s->interp_algo);

        if (err != NPP_SUCCESS) {

            av_log(ctx, AV_LOG_ERROR, "NPP resize error: %d\n", err);

            return AVERROR_UNKNOWN;

        }

    }



    return 0;

}

static void print_track_chunks(FILE *out, struct Tracks *tracks, int main,

                               const char *type)

{

    int i, j;

    struct Track *track = tracks->tracks[main];

    for (i = 0; i < track->chunks; i++) {

        for (j = main + 1; j < tracks->nb_tracks; j++) {

            if (tracks->tracks[j]->is_audio == track->is_audio &&

                track->offsets[i].duration != tracks->tracks[j]->offsets[i].duration)

                fprintf(stderr, "Mismatched duration of %s chunk %d in %s and %s\n",

                        type, i, track->name, tracks->tracks[j]->name);

        }

        fprintf(out, "\t\t<c n=\"%d\" d=\"%d\" />\n",

                i, track->offsets[i].duration);

    }

}

void select_soundhw(const char *optarg)

{

    struct soundhw *c;



    if (*optarg == '?') {

    show_valid_cards:



        printf("Valid sound card names (comma separated):\n");

        for (c = soundhw; c->name; ++c) {

            printf ("%-11s %s\n", c->name, c->descr);

        }

        printf("\n-soundhw all will enable all of the above\n");

        exit(*optarg != '?');

    }

    else {

        size_t l;

        const char *p;

        char *e;

        int bad_card = 0;



        if (!strcmp(optarg, "all")) {

            for (c = soundhw; c->name; ++c) {

                c->enabled = 1;

            }

            return;

        }



        p = optarg;

        while (*p) {

            e = strchr(p, ',');

            l = !e ? strlen(p) : (size_t) (e - p);



            for (c = soundhw; c->name; ++c) {

                if (!strncmp(c->name, p, l) && !c->name[l]) {

                    c->enabled = 1;

                    break;

                }

            }



            if (!c->name) {

                if (l > 80) {

                    fprintf(stderr,

                            "Unknown sound card name (too big to show)\n");

                }

                else {

                    fprintf(stderr, "Unknown sound card name `%.*s'\n",

                            (int) l, p);

                }

                bad_card = 1;

            }

            p += l + (e != NULL);

        }



        if (bad_card) {

            goto show_valid_cards;

        }

    }

}

void show_help(void)

{

    const OptionDef *po;

    int i, expert;



    printf("ffmpeg version " FFMPEG_VERSION ", Copyright (c) 2000,2001 Gerard Lantau\n"

           "usage: ffmpeg [[options] -i input_file]... {[options] outfile}...\n"

           "Hyper fast MPEG1/MPEG4/H263/RV and AC3/MPEG audio encoder\n"

           "\n"

           "Main options are:\n");

    for(i=0;i<2;i++) {

        if (i == 1)

            printf("\nAdvanced options are:\n");

        for(po = options; po->name != NULL; po++) {

            char buf[64];

            expert = (po->flags & OPT_EXPERT) != 0;

            if (expert == i) {

                strcpy(buf, po->name);

                if (po->flags & HAS_ARG) {

                    strcat(buf, " ");

                    strcat(buf, po->argname);

                }

                printf("-%-17s  %s\n", buf, po->help);

            }

        }

    }



    exit(1);

}

static void usage(void)

{

    const struct qemu_argument *arginfo;

    int maxarglen;

    int maxenvlen;



    printf("usage: qemu-" TARGET_ARCH " [options] program [arguments...]\n"

           "Linux CPU emulator (compiled for " TARGET_ARCH " emulation)\n"

           "\n"

           "Options and associated environment variables:\n"

           "\n");



    maxarglen = maxenvlen = 0;



    for (arginfo = arg_table; arginfo->handle_opt != NULL; arginfo++) {

        if (strlen(arginfo->env) > maxenvlen) {

            maxenvlen = strlen(arginfo->env);

        }

        if (strlen(arginfo->argv) > maxarglen) {

            maxarglen = strlen(arginfo->argv);

        }

    }



    printf("%-*s%-*sDescription\n", maxarglen+3, "Argument",

            maxenvlen+1, "Env-variable");



    for (arginfo = arg_table; arginfo->handle_opt != NULL; arginfo++) {

        if (arginfo->has_arg) {

            printf("-%s %-*s %-*s %s\n", arginfo->argv,

                    (int)(maxarglen-strlen(arginfo->argv)), arginfo->example,

                    maxenvlen, arginfo->env, arginfo->help);

        } else {

            printf("-%-*s %-*s %s\n", maxarglen+1, arginfo->argv,

                    maxenvlen, arginfo->env,

                    arginfo->help);

        }

    }



    printf("\n"

           "Defaults:\n"

           "QEMU_LD_PREFIX  = %s\n"

           "QEMU_STACK_SIZE = %ld byte\n",

           interp_prefix,

           guest_stack_size);



    printf("\n"

           "You can use -E and -U options or the QEMU_SET_ENV and\n"

           "QEMU_UNSET_ENV environment variables to set and unset\n"

           "environment variables for the target process.\n"

           "It is possible to provide several variables by separating them\n"

           "by commas in getsubopt(3) style. Additionally it is possible to\n"

           "provide the -E and -U options multiple times.\n"

           "The following lines are equivalent:\n"

           "    -E var1=val2 -E var2=val2 -U LD_PRELOAD -U LD_DEBUG\n"

           "    -E var1=val2,var2=val2 -U LD_PRELOAD,LD_DEBUG\n"

           "    QEMU_SET_ENV=var1=val2,var2=val2 QEMU_UNSET_ENV=LD_PRELOAD,LD_DEBUG\n"

           "Note that if you provide several changes to a single variable\n"

           "the last change will stay in effect.\n");



    exit(1);

}

static av_cold int png_dec_init(AVCodecContext *avctx)

{

    PNGDecContext *s = avctx->priv_data;



    s->avctx = avctx;

    s->previous_picture.f = av_frame_alloc();

    s->last_picture.f = av_frame_alloc();

    s->picture.f = av_frame_alloc();

    if (!s->previous_picture.f || !s->last_picture.f || !s->picture.f)

        return AVERROR(ENOMEM);



    if (!avctx->internal->is_copy) {

        avctx->internal->allocate_progress = 1;

        ff_pngdsp_init(&s->dsp);

    }



    return 0;

}

static av_cold int dirac_decode_init(AVCodecContext *avctx)

{

    DiracContext *s = avctx->priv_data;

    int i;



    s->avctx = avctx;

    s->frame_number = -1;



    if (avctx->flags&CODEC_FLAG_EMU_EDGE) {

        av_log(avctx, AV_LOG_ERROR, "Edge emulation not supported!\n");

        return AVERROR_PATCHWELCOME;

    }



    ff_dsputil_init(&s->dsp, avctx);

    ff_diracdsp_init(&s->diracdsp);



    for (i = 0; i < MAX_FRAMES; i++)

        s->all_frames[i].avframe = av_frame_alloc();



    return 0;

}

static av_cold int ulti_decode_init(AVCodecContext *avctx)

{

    UltimotionDecodeContext *s = avctx->priv_data;



    s->avctx = avctx;

    s->width = avctx->width;

    s->height = avctx->height;

    s->blocks = (s->width / 8) * (s->height / 8);



    avctx->pix_fmt = AV_PIX_FMT_YUV410P;

    s->ulti_codebook = ulti_codebook;



    s->frame = av_frame_alloc();

    if (!s->frame)

        return AVERROR(ENOMEM);



    return 0;

}

static av_cold int mss1_decode_init(AVCodecContext *avctx)

{

    MSS1Context * const c = avctx->priv_data;

    int ret;



    c->ctx.avctx       = avctx;



    c->pic = av_frame_alloc();

    if (!c->pic)

        return AVERROR(ENOMEM);



    ret = ff_mss12_decode_init(&c->ctx, 0, &c->sc, NULL);





    avctx->pix_fmt = AV_PIX_FMT_PAL8;



    return ret;

}

static int vqa_decode_chunk(VqaContext *s)

{

    unsigned int chunk_type;

    unsigned int chunk_size;

    int byte_skip;

    unsigned int index = 0;

    int i;

    unsigned char r, g, b;

    int index_shift;

    int res;



    int cbf0_chunk = -1;

    int cbfz_chunk = -1;

    int cbp0_chunk = -1;

    int cbpz_chunk = -1;

    int cpl0_chunk = -1;

    int cplz_chunk = -1;

    int vptz_chunk = -1;



    int x, y;

    int lines = 0;

    int pixel_ptr;

    int vector_index = 0;

    int lobyte = 0;

    int hibyte = 0;

    int lobytes = 0;

    int hibytes = s->decode_buffer_size / 2;



    /* first, traverse through the frame and find the subchunks */

    while (bytestream2_get_bytes_left(&s->gb) >= 8) {



        chunk_type = bytestream2_get_be32u(&s->gb);

        index      = bytestream2_tell(&s->gb);

        chunk_size = bytestream2_get_be32u(&s->gb);



        switch (chunk_type) {



        case CBF0_TAG:

            cbf0_chunk = index;

            break;



        case CBFZ_TAG:

            cbfz_chunk = index;

            break;



        case CBP0_TAG:

            cbp0_chunk = index;

            break;



        case CBPZ_TAG:

            cbpz_chunk = index;

            break;



        case CPL0_TAG:

            cpl0_chunk = index;

            break;



        case CPLZ_TAG:

            cplz_chunk = index;

            break;



        case VPTZ_TAG:

            vptz_chunk = index;

            break;



        default:

            av_log(s->avctx, AV_LOG_ERROR, "Found unknown chunk type: %c%c%c%c (%08X)\n",

            (chunk_type >> 24) & 0xFF,

            (chunk_type >> 16) & 0xFF,

            (chunk_type >>  8) & 0xFF,

            (chunk_type >>  0) & 0xFF,

            chunk_type);

            break;

        }



        byte_skip = chunk_size & 0x01;

        bytestream2_skip(&s->gb, chunk_size + byte_skip);

    }



    /* next, deal with the palette */

    if ((cpl0_chunk != -1) && (cplz_chunk != -1)) {



        /* a chunk should not have both chunk types */

        av_log(s->avctx, AV_LOG_ERROR, "problem: found both CPL0 and CPLZ chunks\n");

        return AVERROR_INVALIDDATA;

    }



    /* decompress the palette chunk */

    if (cplz_chunk != -1) {



/* yet to be handled */



    }



    /* convert the RGB palette into the machine's endian format */

    if (cpl0_chunk != -1) {



        bytestream2_seek(&s->gb, cpl0_chunk, SEEK_SET);

        chunk_size = bytestream2_get_be32(&s->gb);

        /* sanity check the palette size */

        if (chunk_size / 3 > 256 || chunk_size > bytestream2_get_bytes_left(&s->gb)) {

            av_log(s->avctx, AV_LOG_ERROR, "problem: found a palette chunk with %d colors\n",

                chunk_size / 3);

            return AVERROR_INVALIDDATA;

        }

        for (i = 0; i < chunk_size / 3; i++) {

            /* scale by 4 to transform 6-bit palette -> 8-bit */

            r = bytestream2_get_byteu(&s->gb) * 4;

            g = bytestream2_get_byteu(&s->gb) * 4;

            b = bytestream2_get_byteu(&s->gb) * 4;

            s->palette[i] = 0xFF << 24 | r << 16 | g << 8 | b;

            s->palette[i] |= s->palette[i] >> 6 & 0x30303;

        }

    }



    /* next, look for a full codebook */

    if ((cbf0_chunk != -1) && (cbfz_chunk != -1)) {



        /* a chunk should not have both chunk types */

        av_log(s->avctx, AV_LOG_ERROR, "problem: found both CBF0 and CBFZ chunks\n");

        return AVERROR_INVALIDDATA;

    }



    /* decompress the full codebook chunk */

    if (cbfz_chunk != -1) {



        bytestream2_seek(&s->gb, cbfz_chunk, SEEK_SET);

        chunk_size = bytestream2_get_be32(&s->gb);

        if ((res = decode_format80(s, chunk_size, s->codebook,

                                   s->codebook_size, 0)) < 0)

            return res;

    }



    /* copy a full codebook */

    if (cbf0_chunk != -1) {



        bytestream2_seek(&s->gb, cbf0_chunk, SEEK_SET);

        chunk_size = bytestream2_get_be32(&s->gb);

        /* sanity check the full codebook size */

        if (chunk_size > MAX_CODEBOOK_SIZE) {

            av_log(s->avctx, AV_LOG_ERROR, "problem: CBF0 chunk too large (0x%X bytes)\n",

                chunk_size);

            return AVERROR_INVALIDDATA;

