static void get_attachment(AVFormatContext *s, AVIOContext *pb, int length)

{

    char mime[1024];

    char description[1024];

    unsigned int filesize;

    AVStream *st;

    int64_t pos = avio_tell(pb);



    avio_get_str16le(pb, INT_MAX, mime, sizeof(mime));

    if (strcmp(mime, "image/jpeg"))

        goto done;



    avio_r8(pb);

    avio_get_str16le(pb, INT_MAX, description, sizeof(description));

    filesize = avio_rl32(pb);

    if (!filesize)

        goto done;



    st = avformat_new_stream(s, NULL);

    if (!st)

        goto done;

    av_dict_set(&st->metadata, "title", description, 0);

    st->codec->codec_id   = AV_CODEC_ID_MJPEG;

    st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

    st->codec->extradata  = av_mallocz(filesize);


    if (!st->codec->extradata)

        goto done;

    st->codec->extradata_size = filesize;

    avio_read(pb, st->codec->extradata, filesize);

done:

    avio_seek(pb, pos + length, SEEK_SET);

}

static int mov_read_custom(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    int64_t end = avio_tell(pb) + atom.size;

    uint8_t *key = NULL, *val = NULL, *mean = NULL;

    int i;

    AVStream *st;

    MOVStreamContext *sc;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    for (i = 0; i < 3; i++) {

        uint8_t **p;

        uint32_t len, tag;

        int ret;



        if (end - avio_tell(pb) <= 12)

            break;



        len = avio_rb32(pb);

        tag = avio_rl32(pb);

        avio_skip(pb, 4); // flags



        if (len < 12 || len - 12 > end - avio_tell(pb))

            break;

        len -= 12;



        if (tag == MKTAG('m', 'e', 'a', 'n'))

            p = &mean;

        else if (tag == MKTAG('n', 'a', 'm', 'e'))

            p = &key;

        else if (tag == MKTAG('d', 'a', 't', 'a') && len > 4) {

            avio_skip(pb, 4);

            len -= 4;

            p = &val;

        } else

            break;



        *p = av_malloc(len + 1);

        if (!*p)

            break;

        ret = ffio_read_size(pb, *p, len);

        if (ret < 0) {

            av_freep(p);

            return ret;

        }

        (*p)[len] = 0;

    }



    if (mean && key && val) {

        if (strcmp(key, "iTunSMPB") == 0) {

            int priming, remainder, samples;

            if(sscanf(val, "%*X %X %X %X", &priming, &remainder, &samples) == 3){

                if(priming>0 && priming<16384)

                    sc->start_pad = priming;

            }

        }

        if (strcmp(key, "cdec") != 0) {

            av_dict_set(&c->fc->metadata, key, val,

                        AV_DICT_DONT_STRDUP_KEY | AV_DICT_DONT_STRDUP_VAL);

            key = val = NULL;

        }

    } else {

        av_log(c->fc, AV_LOG_VERBOSE,

               "Unhandled or malformed custom metadata of size %"PRId64"\n", atom.size);

    }



    avio_seek(pb, end, SEEK_SET);

    av_freep(&key);

    av_freep(&val);

    av_freep(&mean);

    return 0;

}

static int mov_read_custom_2plus(MOVContext *c, AVIOContext *pb, int size)

{

    int64_t end = avio_tell(pb) + size;

    uint8_t *key = NULL, *val = NULL;

    int i;

    AVStream *st;

    MOVStreamContext *sc;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    for (i = 0; i < 2; i++) {

        uint8_t **p;

        uint32_t len, tag;



        if (end - avio_tell(pb) <= 12)

            break;



        len = avio_rb32(pb);

        tag = avio_rl32(pb);

        avio_skip(pb, 4); // flags



        if (len < 12 || len - 12 > end - avio_tell(pb))

            break;

        len -= 12;



        if (tag == MKTAG('n', 'a', 'm', 'e'))

            p = &key;

        else if (tag == MKTAG('d', 'a', 't', 'a') && len > 4) {

            avio_skip(pb, 4);

            len -= 4;

            p = &val;

        } else

            break;



        *p = av_malloc(len + 1);

        if (!*p)

            break;

        avio_read(pb, *p, len);

        (*p)[len] = 0;

    }



    if (key && val) {

        if (strcmp(key, "iTunSMPB") == 0) {

            int priming, remainder, samples;

            if(sscanf(val, "%*X %X %X %X", &priming, &remainder, &samples) == 3){

                if(priming>0 && priming<16384)

                    sc->start_pad = priming;

            }

        }

        if (strcmp(key, "cdec") != 0) {

            av_dict_set(&c->fc->metadata, key, val,

                        AV_DICT_DONT_STRDUP_KEY | AV_DICT_DONT_STRDUP_VAL);

            key = val = NULL;

        }

    }



    avio_seek(pb, end, SEEK_SET);

    av_freep(&key);

    av_freep(&val);

    return 0;

}

static int ape_tag_read_field(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    uint8_t key[1024], *value;

    uint32_t size, flags;

    int i, c;



    size = avio_rl32(pb);  /* field size */

    flags = avio_rl32(pb); /* field flags */

    for (i = 0; i < sizeof(key) - 1; i++) {

        c = avio_r8(pb);

        if (c < 0x20 || c > 0x7E)

            break;

        else

            key[i] = c;

    }

    key[i] = 0;

    if (c != 0) {

        av_log(s, AV_LOG_WARNING, "Invalid APE tag key '%s'.\n", key);

        return -1;

    }

    if (size >= UINT_MAX)

        return -1;

    if (flags & APE_TAG_FLAG_IS_BINARY) {

        uint8_t filename[1024];

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        avio_get_str(pb, INT_MAX, filename, sizeof(filename));

        st->codec->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!st->codec->extradata)

            return AVERROR(ENOMEM);

        if (avio_read(pb, st->codec->extradata, size) != size) {

            av_freep(&st->codec->extradata);

            return AVERROR(EIO);

        }

        st->codec->extradata_size = size;

        av_dict_set(&st->metadata, key, filename, 0);

        st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

    } else {

        value = av_malloc(size+1);

        if (!value)

            return AVERROR(ENOMEM);

        c = avio_read(pb, value, size);

        if (c < 0)

            return c;

        value[c] = 0;

        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }

    return 0;

}

static int set_string_binary(void *obj, const AVOption *o, const char *val, uint8_t **dst)

{

    int *lendst = (int *)(dst + 1);

    uint8_t *bin, *ptr;

    int len = strlen(val);



    av_freep(dst);

    *lendst = 0;



    if (len & 1)

        return AVERROR(EINVAL);

    len /= 2;



    ptr = bin = av_malloc(len);

    while (*val) {

        int a = hexchar2int(*val++);

        int b = hexchar2int(*val++);

        if (a < 0 || b < 0) {

            av_free(bin);

            return AVERROR(EINVAL);

        }

        *ptr++ = (a << 4) | b;

    }

    *dst = bin;

    *lendst = len;



    return 0;

}

int av_dict_set(AVDictionary **pm, const char *key, const char *value,

                int flags)

{

    AVDictionary *m = *pm;

    AVDictionaryEntry *tag = av_dict_get(m, key, NULL, flags);

    char *oldval = NULL;



    if (!m)

        m = *pm = av_mallocz(sizeof(*m));



    if (tag) {

        if (flags & AV_DICT_DONT_OVERWRITE)

            return 0;

        if (flags & AV_DICT_APPEND)

            oldval = tag->value;

        else

            av_free(tag->value);

        av_free(tag->key);

        *tag = m->elems[--m->count];

    } else {

        AVDictionaryEntry *tmp = av_realloc(m->elems,

                                            (m->count + 1) * sizeof(*m->elems));

        if (tmp)

            m->elems = tmp;

        else

            return AVERROR(ENOMEM);

    }

    if (value) {

        if (flags & AV_DICT_DONT_STRDUP_KEY)

            m->elems[m->count].key = key;

        else

            m->elems[m->count].key = av_strdup(key);

        if (flags & AV_DICT_DONT_STRDUP_VAL) {

            m->elems[m->count].value = value;

        } else if (oldval && flags & AV_DICT_APPEND) {

            int len = strlen(oldval) + strlen(value) + 1;

            if (!(oldval = av_realloc(oldval, len)))

                return AVERROR(ENOMEM);

            av_strlcat(oldval, value, len);

            m->elems[m->count].value = oldval;

        } else

            m->elems[m->count].value = av_strdup(value);

        m->count++;

    }

    if (!m->count) {

        av_free(m->elems);

        av_freep(pm);

    }



    return 0;

}

static int set_string_number(void *obj, const AVOption *o, const char *val, void *dst)

{

    int ret = 0, notfirst = 0;

    for (;;) {

        int i, den = 1;

        char buf[256];

        int cmd = 0;

        double d, num = 1;

        int64_t intnum = 1;



        if (*val == '+' || *val == '-')

            cmd = *(val++);



        for (i = 0; i < sizeof(buf) - 1 && val[i] && val[i] != '+' && val[i] != '-'; i++)

            buf[i] = val[i];

        buf[i] = 0;



        {

            const AVOption *o_named = av_opt_find(obj, buf, o->unit, 0, 0);

            if (o_named && o_named->type == AV_OPT_TYPE_CONST)

                d = DEFAULT_NUMVAL(o_named);

            else if (!strcmp(buf, "default")) d = DEFAULT_NUMVAL(o);

            else if (!strcmp(buf, "max"    )) d = o->max;

            else if (!strcmp(buf, "min"    )) d = o->min;

            else if (!strcmp(buf, "none"   )) d = 0;

            else if (!strcmp(buf, "all"    )) d = ~0;

            else {

                int res = av_expr_parse_and_eval(&d, buf, const_names, const_values, NULL, NULL, NULL, NULL, NULL, 0, obj);

                if (res < 0) {

                    av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\"\n", val);

                    return res;

                }

            }

        }

        if (o->type == AV_OPT_TYPE_FLAGS) {

            read_number(o, dst, NULL, NULL, &intnum);

            if      (cmd == '+') d = intnum | (int64_t)d;

            else if (cmd == '-') d = intnum &~(int64_t)d;

        } else {

            read_number(o, dst, &num, &den, &intnum);

            if      (cmd == '+') d = notfirst*num*intnum/den + d;

            else if (cmd == '-') d = notfirst*num*intnum/den - d;

        }



        if ((ret = write_number(obj, o, dst, d, 1, 1)) < 0)

            return ret;

        val += i;

        if (!*val)

            return 0;

        notfirst = 1;

    }



    return 0;

}

int av_dict_set(AVDictionary **pm, const char *key, const char *value,

                int flags)

{

    AVDictionary *m = *pm;

    AVDictionaryEntry *tag = av_dict_get(m, key, NULL, flags);

    char *oldval = NULL, *copy_key = NULL, *copy_value = NULL;



    if (flags & AV_DICT_DONT_STRDUP_KEY)

        copy_key = (void *)key;

    else

        copy_key = av_strdup(key);

    if (flags & AV_DICT_DONT_STRDUP_VAL)

        copy_value = (void *)value;

    else if (copy_key)

        copy_value = av_strdup(value);

    if (!m)

        m = *pm = av_mallocz(sizeof(*m));

    if (!m || (key && !copy_key) || (value && !copy_value))

        goto err_out;



    if (tag) {

        if (flags & AV_DICT_DONT_OVERWRITE) {

            av_free(copy_key);

            av_free(copy_value);

            return 0;

        }

        if (flags & AV_DICT_APPEND)

            oldval = tag->value;

        else

            av_free(tag->value);

        av_free(tag->key);

        *tag = m->elems[--m->count];

    } else {

        AVDictionaryEntry *tmp = av_realloc(m->elems,

                                            (m->count + 1) * sizeof(*m->elems));

        if (!tmp)

            goto err_out;

        m->elems = tmp;

    }

    if (copy_value) {

        m->elems[m->count].key = copy_key;

        m->elems[m->count].value = copy_value;

        if (oldval && flags & AV_DICT_APPEND) {

            size_t len = strlen(oldval) + strlen(copy_value) + 1;

            char *newval = av_mallocz(len);

            if (!newval)

                goto err_out;

            av_strlcat(newval, oldval, len);

            av_freep(&oldval);

            av_strlcat(newval, copy_value, len);

            m->elems[m->count].value = newval;

            av_freep(&copy_value);

        }

        m->count++;

    } else {

        av_freep(&copy_key);

    }

    if (!m->count) {

        av_freep(&m->elems);

        av_freep(pm);

    }



    return 0;



err_out:

    if (m && !m->count) {

        av_freep(&m->elems);

        av_freep(pm);

    }

    av_free(copy_key);

    av_free(copy_value);

    return AVERROR(ENOMEM);

}

