static int decode_bdlt(uint8_t *frame, int width, int height,

                       const uint8_t *src, const uint8_t *src_end)

{

    const uint8_t *frame_end = frame + width * height;

    uint8_t *line_ptr;

    int count, lines, segments;



    count = bytestream_get_le16(&src);

    if (count >= height || width * count < 0)

        return -1;

    frame += width * count;

    lines = bytestream_get_le16(&src);

    if (frame + lines * width > frame_end || src >= src_end)

        return -1;



    while (lines--) {

        line_ptr = frame;

        frame += width;

        segments = *src++;

        while (segments--) {

            if (src_end - src < 3)

                return -1;

            line_ptr += *src++;

            if (line_ptr >= frame)

                return -1;

            count = (int8_t)*src++;

            if (count >= 0) {

                if (line_ptr + count > frame || src_end - src < count)

                    return -1;

                bytestream_get_buffer(&src, line_ptr, count);

            } else {

                count = -count;

                if (line_ptr + count > frame || src >= src_end)

                    return -1;

                memset(line_ptr, *src++, count);

            }

            line_ptr += count;

        }

    }



    return 0;

}

static const uint8_t *avc_mp4_find_startcode(const uint8_t *start, const uint8_t *end, int nal_length_size)

{

    int res = 0;



    if (end - start < nal_length_size)

        return NULL;

    while (nal_length_size--)

        res = (res << 8) | *start++;



    if (start + res > end || res < 0 || start + res < start)

        return NULL;



    return start + res;

}

static int decode_wdlt(uint8_t *frame, int width, int height,

                       const uint8_t *src, const uint8_t *src_end)

{

    const uint8_t *frame_end   = frame + width * height;

    uint8_t *line_ptr;

    int count, i, v, lines, segments;



    lines = bytestream_get_le16(&src);

    if (lines > height || src >= src_end)

        return -1;



    while (lines--) {

        segments = bytestream_get_le16(&src);

        while ((segments & 0xC000) == 0xC000) {

            unsigned delta = -((int16_t)segments * width);

            if (frame_end - frame <= delta)

                return -1;

            frame    += delta;

            segments = bytestream_get_le16(&src);

        }

        if (segments & 0x8000) {

            frame[width - 1] = segments & 0xFF;

            segments = bytestream_get_le16(&src);

        }

        line_ptr = frame;

        frame += width;

        while (segments--) {

            if (src_end - src < 2)

                return -1;

            if (frame - line_ptr <= *src)

                return -1;

            line_ptr += *src++;

            count = (int8_t)*src++;

            if (count >= 0) {

                if (frame - line_ptr < count*2 || src_end - src < count*2)

                    return -1;

                bytestream_get_buffer(&src, line_ptr, count*2);

                line_ptr += count * 2;

            } else {

                count = -count;

                if (frame - line_ptr < count*2 || src_end - src < 2)

                    return -1;

                v = bytestream_get_le16(&src);

                for (i = 0; i < count; i++)

                    bytestream_put_le16(&line_ptr, v);

            }

        }

    }



    return 0;

}

static int decode_dds1(uint8_t *frame, int width, int height,

                       const uint8_t *src, const uint8_t *src_end)

{

    const uint8_t *frame_start = frame;

    const uint8_t *frame_end   = frame + width * height;

    int mask = 0x10000, bitbuf = 0;

    int i, v, offset, count, segments;



    segments = bytestream_get_le16(&src);

    while (segments--) {

        if (mask == 0x10000) {

            if (src >= src_end)

                return -1;

            bitbuf = bytestream_get_le16(&src);

            mask = 1;

        }

        if (src_end - src < 2 || frame_end - frame < 2)

            return -1;

        if (bitbuf & mask) {

            v = bytestream_get_le16(&src);

            offset = (v & 0x1FFF) << 2;

            count = ((v >> 13) + 2) << 1;

            if (frame - frame_start < offset || frame_end - frame < count*2 + width)

                return -1;

            for (i = 0; i < count; i++) {

                frame[0] = frame[1] =

                frame[width] = frame[width + 1] = frame[-offset];



                frame += 2;

            }

        } else if (bitbuf & (mask << 1)) {

            frame += bytestream_get_le16(&src) * 2;

        } else {

            frame[0] = frame[1] =

            frame[width] = frame[width + 1] =  *src++;

            frame += 2;

            frame[0] = frame[1] =

            frame[width] = frame[width + 1] =  *src++;

            frame += 2;

        }

        mask <<= 2;

    }



    return 0;

}

static uint16_t nvme_identify_ns(NvmeCtrl *n, NvmeIdentify *c)

{

    NvmeNamespace *ns;

    uint32_t nsid = le32_to_cpu(c->nsid);

    uint64_t prp1 = le64_to_cpu(c->prp1);

    uint64_t prp2 = le64_to_cpu(c->prp2);



    if (nsid == 0 || nsid > n->num_namespaces) {

        return NVME_INVALID_NSID | NVME_DNR;

    }



    ns = &n->namespaces[nsid - 1];

    return nvme_dma_read_prp(n, (uint8_t *)&ns->id_ns, sizeof(ns->id_ns),

        prp1, prp2);

}

static uint16_t nvme_get_feature(NvmeCtrl *n, NvmeCmd *cmd, NvmeRequest *req)

{

    uint32_t dw10 = le32_to_cpu(cmd->cdw10);

    uint32_t result;



    switch (dw10) {

    case NVME_VOLATILE_WRITE_CACHE:

        result = blk_enable_write_cache(n->conf.blk);

        break;

    case NVME_NUMBER_OF_QUEUES:

        result = cpu_to_le32((n->num_queues - 1) | ((n->num_queues - 1) << 16));

        break;

    default:

        return NVME_INVALID_FIELD | NVME_DNR;

    }



    req->cqe.result = result;

    return NVME_SUCCESS;

}

static uint16_t nvme_rw(NvmeCtrl *n, NvmeNamespace *ns, NvmeCmd *cmd,

    NvmeRequest *req)

{

    NvmeRwCmd *rw = (NvmeRwCmd *)cmd;

    uint32_t nlb  = le32_to_cpu(rw->nlb) + 1;

    uint64_t slba = le64_to_cpu(rw->slba);

    uint64_t prp1 = le64_to_cpu(rw->prp1);

    uint64_t prp2 = le64_to_cpu(rw->prp2);



    uint8_t lba_index  = NVME_ID_NS_FLBAS_INDEX(ns->id_ns.flbas);

    uint8_t data_shift = ns->id_ns.lbaf[lba_index].ds;

    uint64_t data_size = nlb << data_shift;

    uint64_t aio_slba  = slba << (data_shift - BDRV_SECTOR_BITS);

    int is_write = rw->opcode == NVME_CMD_WRITE ? 1 : 0;



    if ((slba + nlb) > ns->id_ns.nsze) {

        return NVME_LBA_RANGE | NVME_DNR;

    }

    if (nvme_map_prp(&req->qsg, prp1, prp2, data_size, n)) {

        return NVME_INVALID_FIELD | NVME_DNR;

    }

    assert((nlb << data_shift) == req->qsg.size);



    dma_acct_start(n->conf.bs, &req->acct, &req->qsg, is_write ?

        BLOCK_ACCT_WRITE : BLOCK_ACCT_READ);

    req->aiocb = is_write ?

        dma_bdrv_write(n->conf.bs, &req->qsg, aio_slba, nvme_rw_cb, req) :

        dma_bdrv_read(n->conf.bs, &req->qsg, aio_slba, nvme_rw_cb, req);



    return NVME_NO_COMPLETE;

}

static uint16_t nvme_set_feature(NvmeCtrl *n, NvmeCmd *cmd, NvmeRequest *req)

{

    uint32_t dw10 = le32_to_cpu(cmd->cdw10);

    uint32_t dw11 = le32_to_cpu(cmd->cdw11);



    switch (dw10) {

    case NVME_VOLATILE_WRITE_CACHE:

        blk_set_enable_write_cache(n->conf.blk, dw11 & 1);

        break;

    case NVME_NUMBER_OF_QUEUES:

        req->cqe.result =

            cpu_to_le32((n->num_queues - 1) | ((n->num_queues - 1) << 16));

        break;

    default:

        return NVME_INVALID_FIELD | NVME_DNR;

    }

    return NVME_SUCCESS;

}

