static uint16_t eepro100_read2(EEPRO100State * s, uint32_t addr)

{

    uint16_t val;

    if (addr <= sizeof(s->mem) - sizeof(val)) {

        memcpy(&val, &s->mem[addr], sizeof(val));

    }



    switch (addr) {

    case SCBStatus:

    case SCBCmd:

        TRACE(OTHER, logout("addr=%s val=0x%04x\n", regname(addr), val));

        break;

    case SCBeeprom:

        val = eepro100_read_eeprom(s);

        TRACE(OTHER, logout("addr=%s val=0x%04x\n", regname(addr), val));

        break;

    default:

        logout("addr=%s val=0x%04x\n", regname(addr), val);

        missing("unknown word read");

    }

    return val;

}

static uint8_t eepro100_read1(EEPRO100State * s, uint32_t addr)

{

    uint8_t val;

    if (addr <= sizeof(s->mem) - sizeof(val)) {

        memcpy(&val, &s->mem[addr], sizeof(val));

    }



    switch (addr) {

    case SCBStatus:

    case SCBAck:

        TRACE(OTHER, logout("addr=%s val=0x%02x\n", regname(addr), val));

        break;

    case SCBCmd:

        TRACE(OTHER, logout("addr=%s val=0x%02x\n", regname(addr), val));

#if 0

        val = eepro100_read_command(s);

#endif

        break;

    case SCBIntmask:

        TRACE(OTHER, logout("addr=%s val=0x%02x\n", regname(addr), val));

        break;

    case SCBPort + 3:

        TRACE(OTHER, logout("addr=%s val=0x%02x\n", regname(addr), val));

        break;

    case SCBeeprom:

        val = eepro100_read_eeprom(s);

        break;

    case SCBpmdr:       /* Power Management Driver Register */

        val = 0;

        TRACE(OTHER, logout("addr=%s val=0x%02x\n", regname(addr), val));

        break;

    case SCBgstat:      /* General Status Register */

        /* 100 Mbps full duplex, valid link */

        val = 0x07;

        TRACE(OTHER, logout("addr=General Status val=%02x\n", val));

        break;

    default:

        logout("addr=%s val=0x%02x\n", regname(addr), val);

        missing("unknown byte read");

    }

    return val;

}

static void sbr_mapping(AACContext *ac, SpectralBandReplication *sbr,

                        SBRData *ch_data, int e_a[2])

{

    int e, i, m;



    memset(ch_data->s_indexmapped[1], 0, 7*sizeof(ch_data->s_indexmapped[1]));

    for (e = 0; e < ch_data->bs_num_env; e++) {

        const unsigned int ilim = sbr->n[ch_data->bs_freq_res[e + 1]];

        uint16_t *table = ch_data->bs_freq_res[e + 1] ? sbr->f_tablehigh : sbr->f_tablelow;

        int k;



        for (i = 0; i < ilim; i++)

            for (m = table[i]; m < table[i + 1]; m++)

                sbr->e_origmapped[e][m - sbr->kx[1]] = ch_data->env_facs[e+1][i];



        // ch_data->bs_num_noise > 1 => 2 noise floors

        k = (ch_data->bs_num_noise > 1) && (ch_data->t_env[e] >= ch_data->t_q[1]);

        for (i = 0; i < sbr->n_q; i++)

            for (m = sbr->f_tablenoise[i]; m < sbr->f_tablenoise[i + 1]; m++)

                sbr->q_mapped[e][m - sbr->kx[1]] = ch_data->noise_facs[k+1][i];



        for (i = 0; i < sbr->n[1]; i++) {

            if (ch_data->bs_add_harmonic_flag) {

                const unsigned int m_midpoint =

                    (sbr->f_tablehigh[i] + sbr->f_tablehigh[i + 1]) >> 1;



                ch_data->s_indexmapped[e + 1][m_midpoint - sbr->kx[1]] = ch_data->bs_add_harmonic[i] *

                    (e >= e_a[1] || (ch_data->s_indexmapped[0][m_midpoint - sbr->kx[1]] == 1));

            }

        }



        for (i = 0; i < ilim; i++) {

            int additional_sinusoid_present = 0;

            for (m = table[i]; m < table[i + 1]; m++) {

                if (ch_data->s_indexmapped[e + 1][m - sbr->kx[1]]) {

                    additional_sinusoid_present = 1;

                    break;

                }

            }

            memset(&sbr->s_mapped[e][table[i] - sbr->kx[1]], additional_sinusoid_present,

                   (table[i + 1] - table[i]) * sizeof(sbr->s_mapped[e][0]));

        }

    }



    memcpy(ch_data->s_indexmapped[0], ch_data->s_indexmapped[ch_data->bs_num_env], sizeof(ch_data->s_indexmapped[0]));

}

static int encode_rgb_frame(FFV1Context *s, uint8_t *src[3], int w, int h, int stride[3])

{

    int x, y, p, i;

    const int ring_size = s->avctx->context_model ? 3 : 2;

    int16_t *sample[4][3];

    int lbd    = s->bits_per_raw_sample <= 8;

    int bits   = s->bits_per_raw_sample > 0 ? s->bits_per_raw_sample : 8;

    int offset = 1 << bits;



    s->run_index = 0;



    memset(s->sample_buffer, 0, ring_size * MAX_PLANES *

                                (w + 6) * sizeof(*s->sample_buffer));



    for (y = 0; y < h; y++) {

        for (i = 0; i < ring_size; i++)

            for (p = 0; p < MAX_PLANES; p++)

                sample[p][i]= s->sample_buffer + p*ring_size*(w+6) + ((h+i-y)%ring_size)*(w+6) + 3;



        for (x = 0; x < w; x++) {

            int b, g, r, av_uninit(a);

            if (lbd) {

                unsigned v = *((uint32_t*)(src[0] + x*4 + stride[0]*y));

                b =  v        & 0xFF;

                g = (v >>  8) & 0xFF;

                r = (v >> 16) & 0xFF;

                a =  v >> 24;

            } else {

                b = *((uint16_t*)(src[0] + x*2 + stride[0]*y));

                g = *((uint16_t*)(src[1] + x*2 + stride[1]*y));

                r = *((uint16_t*)(src[2] + x*2 + stride[2]*y));

            }



            b -= g;

            r -= g;

            g += (b + r) >> 2;

            b += offset;

            r += offset;



            sample[0][0][x] = g;

            sample[1][0][x] = b;

            sample[2][0][x] = r;

            sample[3][0][x] = a;

        }

        for (p = 0; p < 3 + s->transparency; p++) {

            int ret;

            sample[p][0][-1] = sample[p][1][0  ];

            sample[p][1][ w] = sample[p][1][w-1];

            if (lbd)

                ret = encode_line(s, w, sample[p], (p + 1) / 2, 9);

            else

                ret = encode_line(s, w, sample[p], (p + 1) / 2, bits + 1);

            if (ret < 0)

                return ret;

        }

    }

    return 0;

}

int pcie_cap_init(PCIDevice *dev, uint8_t offset, uint8_t type, uint8_t port)

{

    /* PCIe cap v2 init */

    int pos;

    uint8_t *exp_cap;



    assert(pci_is_express(dev));



    pos = pci_add_capability(dev, PCI_CAP_ID_EXP, offset, PCI_EXP_VER2_SIZEOF);

    if (pos < 0) {

        return pos;

    }

    dev->exp.exp_cap = pos;

    exp_cap = dev->config + pos;



    /* Filling values common with v1 */

    pcie_cap_v1_fill(exp_cap, port, type, PCI_EXP_FLAGS_VER2);



    /* Filling v2 specific values */

    pci_set_long(exp_cap + PCI_EXP_DEVCAP2,

                 PCI_EXP_DEVCAP2_EFF | PCI_EXP_DEVCAP2_EETLPP);



    pci_set_word(dev->wmask + pos + PCI_EXP_DEVCTL2, PCI_EXP_DEVCTL2_EETLPPB);

    return pos;

}

static void pci_device_reset(PCIDevice *dev)

{

    int r;



    memset(dev->irq_state, 0, sizeof dev->irq_state);

    dev->config[PCI_COMMAND] &= ~(PCI_COMMAND_IO | PCI_COMMAND_MEMORY |

                                  PCI_COMMAND_MASTER);

    dev->config[PCI_CACHE_LINE_SIZE] = 0x0;

    dev->config[PCI_INTERRUPT_LINE] = 0x0;

    for (r = 0; r < PCI_NUM_REGIONS; ++r) {

        if (!dev->io_regions[r].size) {

            continue;

        }

        pci_set_long(dev->config + pci_bar(dev, r), dev->io_regions[r].type);

    }

    pci_update_mappings(dev);

}

static int vt82c686b_mc97_initfn(PCIDevice *dev)

{

    VT686MC97State *s = DO_UPCAST(VT686MC97State, dev, dev);

    uint8_t *pci_conf = s->dev.config;



    pci_config_set_vendor_id(pci_conf, PCI_VENDOR_ID_VIA);

    pci_config_set_device_id(pci_conf, PCI_DEVICE_ID_VIA_MC97);

    pci_config_set_class(pci_conf, PCI_CLASS_COMMUNICATION_OTHER);

    pci_config_set_revision(pci_conf, 0x30);



    pci_set_word(pci_conf + PCI_COMMAND, PCI_COMMAND_INVALIDATE |

                 PCI_COMMAND_VGA_PALETTE);

    pci_set_word(pci_conf + PCI_STATUS, PCI_STATUS_DEVSEL_MEDIUM);

    pci_set_long(pci_conf + PCI_INTERRUPT_PIN, 0x03);



    return 0;

}

static int vt82c686b_pm_initfn(PCIDevice *dev)

{

    VT686PMState *s = DO_UPCAST(VT686PMState, dev, dev);

    uint8_t *pci_conf;



    pci_conf = s->dev.config;

    pci_config_set_vendor_id(pci_conf, PCI_VENDOR_ID_VIA);

    pci_config_set_device_id(pci_conf, PCI_DEVICE_ID_VIA_ACPI);

    pci_config_set_class(pci_conf, PCI_CLASS_BRIDGE_OTHER);

    pci_config_set_revision(pci_conf, 0x40);



    pci_set_word(pci_conf + PCI_COMMAND, 0);

    pci_set_word(pci_conf + PCI_STATUS, PCI_STATUS_FAST_BACK |

                 PCI_STATUS_DEVSEL_MEDIUM);



    /* 0x48-0x4B is Power Management I/O Base */

    pci_set_long(pci_conf + 0x48, 0x00000001);



    /* SMB ports:0xeee0~0xeeef */

    s->smb_io_base =((s->smb_io_base & 0xfff0) + 0x0);

    pci_conf[0x90] = s->smb_io_base | 1;

    pci_conf[0x91] = s->smb_io_base >> 8;

    pci_conf[0xd2] = 0x90;

    register_ioport_write(s->smb_io_base, 0xf, 1, smb_ioport_writeb, &s->smb);

    register_ioport_read(s->smb_io_base, 0xf, 1, smb_ioport_readb, &s->smb);



    apm_init(&s->apm, NULL, s);



    acpi_pm_tmr_init(&s->tmr, pm_tmr_timer);

    acpi_pm1_cnt_init(&s->pm1_cnt, NULL);



    pm_smbus_init(&s->dev.qdev, &s->smb);



    return 0;

}

