static void fill_gv_table(int table[256 + 2*YUVRGB_TABLE_HEADROOM], const int elemsize, const int inc)

{

    int i;

    int off    = -(inc >> 9);



    for (i = 0; i < 256 + 2*YUVRGB_TABLE_HEADROOM; i++) {

        int64_t cb = av_clip(i-YUVRGB_TABLE_HEADROOM, 0, 255)*inc;

        table[i] = elemsize * (off + (cb >> 16));

    }

}

static void vc1_inv_trans_4x8_dc_c(uint8_t *dest, int linesize, DCTELEM *block)

{

    int i;

    int dc = block[0];

    const uint8_t *cm;

    dc = (17 * dc +  4) >> 3;

    dc = (12 * dc + 64) >> 7;

    cm = ff_cropTbl + MAX_NEG_CROP + dc;

    for(i = 0; i < 8; i++){

        dest[0] = cm[dest[0]];

        dest[1] = cm[dest[1]];

        dest[2] = cm[dest[2]];

        dest[3] = cm[dest[3]];

        dest += linesize;

    }

}

static void add_pixels_clamped2_c(const DCTELEM *block, uint8_t *restrict pixels,

                          int line_size)

{

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    /* read the pixels */

    for(i=0;i<2;i++) {

        pixels[0] = cm[pixels[0] + block[0]];

        pixels[1] = cm[pixels[1] + block[1]];

        pixels += line_size;

        block += 8;

    }

}

static void add_pixels_clamped4_c(const DCTELEM *block, uint8_t *restrict pixels,

                          int line_size)

{

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    /* read the pixels */

    for(i=0;i<4;i++) {

        pixels[0] = cm[pixels[0] + block[0]];

        pixels[1] = cm[pixels[1] + block[1]];

        pixels[2] = cm[pixels[2] + block[2]];

        pixels[3] = cm[pixels[3] + block[3]];

        pixels += line_size;

        block += 8;

    }

}

static int allocate_buffers(ShortenContext *s)

{

    int i, chan, err;



    for (chan = 0; chan < s->channels; chan++) {

        if (FFMAX(1, s->nmean) >= UINT_MAX / sizeof(int32_t)) {

            av_log(s->avctx, AV_LOG_ERROR, "nmean too large\n");

            return AVERROR_INVALIDDATA;

        }

        if (s->blocksize + s->nwrap >= UINT_MAX / sizeof(int32_t) ||

            s->blocksize + s->nwrap <= (unsigned)s->nwrap) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "s->blocksize + s->nwrap too large\n");

            return AVERROR_INVALIDDATA;

        }



        if ((err = av_reallocp_array(&s->offset[chan],

                               sizeof(int32_t),

                               FFMAX(1, s->nmean))) < 0)

            return err;



        if ((err = av_reallocp_array(&s->decoded_base[chan], (s->blocksize + s->nwrap),

                               sizeof(s->decoded_base[0][0]))) < 0)

            return err;

        for (i = 0; i < s->nwrap; i++)

            s->decoded_base[chan][i] = 0;

        s->decoded[chan] = s->decoded_base[chan] + s->nwrap;

    }



    if ((err = av_reallocp_array(&s->coeffs, s->nwrap, sizeof(*s->coeffs))) < 0)

        return err;



    return 0;

}

