static int libschroedinger_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                                        const AVFrame *frame, int *got_packet)

{

    int enc_size = 0;

    SchroEncoderParams *p_schro_params = avctx->priv_data;

    SchroEncoder *encoder = p_schro_params->encoder;

    struct FFSchroEncodedFrame *p_frame_output = NULL;

    int go = 1;

    SchroBuffer *enc_buf;

    int presentation_frame;

    int parse_code;

    int last_frame_in_sequence = 0;

    int pkt_size, ret;



    if (!frame) {

        /* Push end of sequence if not already signalled. */

        if (!p_schro_params->eos_signalled) {

            schro_encoder_end_of_stream(encoder);

            p_schro_params->eos_signalled = 1;

        }

    } else {

        /* Allocate frame data to schro input buffer. */

        SchroFrame *in_frame = libschroedinger_frame_from_data(avctx, frame);

        if (!in_frame)

            return AVERROR(ENOMEM);

        /* Load next frame. */

        schro_encoder_push_frame(encoder, in_frame);

    }



    if (p_schro_params->eos_pulled)

        go = 0;



    /* Now check to see if we have any output from the encoder. */

    while (go) {

        int err;

        SchroStateEnum state;

        state = schro_encoder_wait(encoder);

        switch (state) {

        case SCHRO_STATE_HAVE_BUFFER:

        case SCHRO_STATE_END_OF_STREAM:

            enc_buf = schro_encoder_pull(encoder, &presentation_frame);

            if (enc_buf->length <= 0)

                return AVERROR_BUG;

            parse_code = enc_buf->data[4];



            /* All non-frame data is prepended to actual frame data to

             * be able to set the pts correctly. So we don't write data

             * to the frame output queue until we actually have a frame

             */

            if ((err = av_reallocp(&p_schro_params->enc_buf,

                                   p_schro_params->enc_buf_size +

                                   enc_buf->length)) < 0) {

                p_schro_params->enc_buf_size = 0;

                return err;

            }



            memcpy(p_schro_params->enc_buf + p_schro_params->enc_buf_size,

                   enc_buf->data, enc_buf->length);

            p_schro_params->enc_buf_size += enc_buf->length;





            if (state == SCHRO_STATE_END_OF_STREAM) {

                p_schro_params->eos_pulled = 1;

                go = 0;

            }



            if (!SCHRO_PARSE_CODE_IS_PICTURE(parse_code)) {

                schro_buffer_unref(enc_buf);

                break;

            }



            /* Create output frame. */

            p_frame_output = av_mallocz(sizeof(FFSchroEncodedFrame));

            if (!p_frame_output)

                return AVERROR(ENOMEM);

            /* Set output data. */

            p_frame_output->size     = p_schro_params->enc_buf_size;

            p_frame_output->p_encbuf = p_schro_params->enc_buf;

            if (SCHRO_PARSE_CODE_IS_INTRA(parse_code) &&

                SCHRO_PARSE_CODE_IS_REFERENCE(parse_code))

                p_frame_output->key_frame = 1;



            /* Parse the coded frame number from the bitstream. Bytes 14

             * through 17 represent the frame number. */

            p_frame_output->frame_num = AV_RB32(enc_buf->data + 13);



            ff_schro_queue_push_back(&p_schro_params->enc_frame_queue,

                                     p_frame_output);

            p_schro_params->enc_buf_size = 0;

            p_schro_params->enc_buf      = NULL;



            schro_buffer_unref(enc_buf);



            break;



        case SCHRO_STATE_NEED_FRAME:

            go = 0;

            break;



        case SCHRO_STATE_AGAIN:

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unknown Schro Encoder state\n");

            return -1;

        }

    }



    /* Copy 'next' frame in queue. */



    if (p_schro_params->enc_frame_queue.size == 1 &&

        p_schro_params->eos_pulled)

        last_frame_in_sequence = 1;



    p_frame_output = ff_schro_queue_pop(&p_schro_params->enc_frame_queue);



    if (!p_frame_output)

        return 0;



    pkt_size = p_frame_output->size;

    if (last_frame_in_sequence && p_schro_params->enc_buf_size > 0)

        pkt_size += p_schro_params->enc_buf_size;

    if ((ret = ff_alloc_packet2(avctx, pkt, pkt_size, 0)) < 0)

        goto error;



    memcpy(pkt->data, p_frame_output->p_encbuf, p_frame_output->size);

#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->key_frame = p_frame_output->key_frame;

    avctx->coded_frame->pts = p_frame_output->frame_num;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

    /* Use the frame number of the encoded frame as the pts. It is OK to

     * do so since Dirac is a constant frame rate codec. It expects input

     * to be of constant frame rate. */

    pkt->pts = p_frame_output->frame_num;

    pkt->dts = p_schro_params->dts++;

    enc_size = p_frame_output->size;



    /* Append the end of sequence information to the last frame in the

     * sequence. */

    if (last_frame_in_sequence && p_schro_params->enc_buf_size > 0) {

        memcpy(pkt->data + enc_size, p_schro_params->enc_buf,

               p_schro_params->enc_buf_size);

        enc_size += p_schro_params->enc_buf_size;

        av_freep(&p_schro_params->enc_buf);

        p_schro_params->enc_buf_size = 0;

    }



    if (p_frame_output->key_frame)

        pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



error:

    /* free frame */

    libschroedinger_free_frame(p_frame_output);

    return ret;

}

static int libschroedinger_decode_frame(AVCodecContext *avctx,

                                        void *data, int *got_frame,

                                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    int64_t pts  = avpkt->pts;

    SchroTag *tag;



    SchroDecoderParams *p_schro_params = avctx->priv_data;

    SchroDecoder *decoder = p_schro_params->decoder;

    SchroBuffer *enc_buf;

    SchroFrame* frame;

    AVFrame *avframe = data;

    int state;

    int go = 1;

    int outer = 1;

    SchroParseUnitContext parse_ctx;

    LibSchroFrameContext *framewithpts = NULL;

    int ret;



    *got_frame = 0;



    parse_context_init(&parse_ctx, buf, buf_size);

    if (!buf_size) {

        if (!p_schro_params->eos_signalled) {

            state = schro_decoder_push_end_of_stream(decoder);

            p_schro_params->eos_signalled = 1;

        }

    }



    /* Loop through all the individual parse units in the input buffer */

    do {

        if ((enc_buf = find_next_parse_unit(&parse_ctx))) {

            /* Set Schrotag with the pts to be recovered after decoding*/

            enc_buf->tag = schro_tag_new(av_malloc(sizeof(int64_t)), av_free);

            if (!enc_buf->tag->value) {

                av_log(avctx, AV_LOG_ERROR, "Unable to allocate SchroTag\n");

                return AVERROR(ENOMEM);

            }

            AV_WN(64, enc_buf->tag->value, pts);

            /* Push buffer into decoder. */

            if (SCHRO_PARSE_CODE_IS_PICTURE(enc_buf->data[4]) &&

                SCHRO_PARSE_CODE_NUM_REFS(enc_buf->data[4]) > 0)

                avctx->has_b_frames = 1;

            state = schro_decoder_push(decoder, enc_buf);

            if (state == SCHRO_DECODER_FIRST_ACCESS_UNIT)

                libschroedinger_handle_first_access_unit(avctx);

            go = 1;

        } else

            outer = 0;



        while (go) {

            /* Parse data and process result. */

            state = schro_decoder_wait(decoder);

            switch (state) {

            case SCHRO_DECODER_FIRST_ACCESS_UNIT:

                libschroedinger_handle_first_access_unit(avctx);

                break;



            case SCHRO_DECODER_NEED_BITS:

                /* Need more input data - stop iterating over what we have. */

                go = 0;

                break;



            case SCHRO_DECODER_NEED_FRAME:

                /* Decoder needs a frame - create one and push it in. */

                frame = ff_create_schro_frame(avctx,

                                              p_schro_params->frame_format);

                if (!frame)

                    return AVERROR(ENOMEM);

                schro_decoder_add_output_picture(decoder, frame);

                break;



            case SCHRO_DECODER_OK:

                /* Pull a frame out of the decoder. */

                tag   = schro_decoder_get_picture_tag(decoder);

                frame = schro_decoder_pull(decoder);



                if (frame) {

                    /* Add relation between schroframe and pts. */

                    framewithpts = av_malloc(sizeof(LibSchroFrameContext));

                    if (!framewithpts) {

                        av_log(avctx, AV_LOG_ERROR, "Unable to allocate FrameWithPts\n");

                        return AVERROR(ENOMEM);

                    }

                    framewithpts->frame = frame;

                    framewithpts->pts   = AV_RN64(tag->value);

                    ff_schro_queue_push_back(&p_schro_params->dec_frame_queue,

                                             framewithpts);

                }

                break;

            case SCHRO_DECODER_EOS:

                go = 0;

                p_schro_params->eos_pulled = 1;

                schro_decoder_reset(decoder);

                outer = 0;

                break;



            case SCHRO_DECODER_ERROR:

                return -1;

                break;

            }

        }

    } while (outer);



    /* Grab next frame to be returned from the top of the queue. */

    framewithpts = ff_schro_queue_pop(&p_schro_params->dec_frame_queue);



    if (framewithpts && framewithpts->frame && framewithpts->frame->components[0].stride) {

        if ((ret = ff_get_buffer(avctx, avframe, 0)) < 0) {

            goto end;

        }



        memcpy(avframe->data[0],

               framewithpts->frame->components[0].data,

               framewithpts->frame->components[0].length);



        memcpy(avframe->data[1],

               framewithpts->frame->components[1].data,

               framewithpts->frame->components[1].length);



        memcpy(avframe->data[2],

               framewithpts->frame->components[2].data,

               framewithpts->frame->components[2].length);



        /* Fill frame with current buffer data from Schroedinger. */

        avframe->pts = framewithpts->pts;

#if FF_API_PKT_PTS

FF_DISABLE_DEPRECATION_WARNINGS

        avframe->pkt_pts = avframe->pts;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

        avframe->linesize[0] = framewithpts->frame->components[0].stride;

        avframe->linesize[1] = framewithpts->frame->components[1].stride;

        avframe->linesize[2] = framewithpts->frame->components[2].stride;



        *got_frame      = 1;

    } else {

        data       = NULL;

        *got_frame = 0;

    }

    ret = buf_size;

end:

    /* Now free the frame resources. */

    if (framewithpts && framewithpts->frame)

        libschroedinger_decode_frame_free(framewithpts->frame);

    av_freep(&framewithpts);

    return ret;

}

static int process_output_surface(AVCodecContext *avctx, AVPacket *pkt, NvencSurface *tmpoutsurf)

{

    NvencContext *ctx = avctx->priv_data;

    NvencDynLoadFunctions *dl_fn = &ctx->nvenc_dload_funcs;

    NV_ENCODE_API_FUNCTION_LIST *p_nvenc = &dl_fn->nvenc_funcs;



    uint32_t slice_mode_data;

    uint32_t *slice_offsets = NULL;

    NV_ENC_LOCK_BITSTREAM lock_params = { 0 };

    NVENCSTATUS nv_status;

    int res = 0;



    enum AVPictureType pict_type;



    switch (avctx->codec->id) {

    case AV_CODEC_ID_H264:

      slice_mode_data = ctx->encode_config.encodeCodecConfig.h264Config.sliceModeData;

      break;

    case AV_CODEC_ID_H265:

      slice_mode_data = ctx->encode_config.encodeCodecConfig.hevcConfig.sliceModeData;

      break;

    default:

      av_log(avctx, AV_LOG_ERROR, "Unknown codec name\n");

      res = AVERROR(EINVAL);

      goto error;

    }

    slice_offsets = av_mallocz(slice_mode_data * sizeof(*slice_offsets));



    if (!slice_offsets) {

        res = AVERROR(ENOMEM);

        goto error;

    }



    lock_params.version = NV_ENC_LOCK_BITSTREAM_VER;



    lock_params.doNotWait = 0;

    lock_params.outputBitstream = tmpoutsurf->output_surface;

    lock_params.sliceOffsets = slice_offsets;



    nv_status = p_nvenc->nvEncLockBitstream(ctx->nvencoder, &lock_params);

    if (nv_status != NV_ENC_SUCCESS) {

        res = nvenc_print_error(avctx, nv_status, "Failed locking bitstream buffer");

        goto error;

    }



    if (res = ff_alloc_packet2(avctx, pkt, lock_params.bitstreamSizeInBytes,0)) {

        p_nvenc->nvEncUnlockBitstream(ctx->nvencoder, tmpoutsurf->output_surface);

        goto error;

    }



    memcpy(pkt->data, lock_params.bitstreamBufferPtr, lock_params.bitstreamSizeInBytes);



    nv_status = p_nvenc->nvEncUnlockBitstream(ctx->nvencoder, tmpoutsurf->output_surface);

    if (nv_status != NV_ENC_SUCCESS)

        nvenc_print_error(avctx, nv_status, "Failed unlocking bitstream buffer, expect the gates of mordor to open");





    if (avctx->pix_fmt == AV_PIX_FMT_CUDA || avctx->pix_fmt == AV_PIX_FMT_D3D11) {

        ctx->registered_frames[tmpoutsurf->reg_idx].mapped -= 1;

        if (ctx->registered_frames[tmpoutsurf->reg_idx].mapped == 0) {

            p_nvenc->nvEncUnmapInputResource(ctx->nvencoder, ctx->registered_frames[tmpoutsurf->reg_idx].in_map.mappedResource);

            p_nvenc->nvEncUnregisterResource(ctx->nvencoder, ctx->registered_frames[tmpoutsurf->reg_idx].regptr);

            ctx->registered_frames[tmpoutsurf->reg_idx].regptr = NULL;

        } else if (ctx->registered_frames[tmpoutsurf->reg_idx].mapped < 0) {

            res = AVERROR_BUG;

            goto error;

        }



        av_frame_unref(tmpoutsurf->in_ref);



        tmpoutsurf->input_surface = NULL;

    }



    switch (lock_params.pictureType) {

    case NV_ENC_PIC_TYPE_IDR:

        pkt->flags |= AV_PKT_FLAG_KEY;

    case NV_ENC_PIC_TYPE_I:

        pict_type = AV_PICTURE_TYPE_I;

        break;

    case NV_ENC_PIC_TYPE_P:

        pict_type = AV_PICTURE_TYPE_P;

        break;

    case NV_ENC_PIC_TYPE_B:

        pict_type = AV_PICTURE_TYPE_B;

        break;

    case NV_ENC_PIC_TYPE_BI:

        pict_type = AV_PICTURE_TYPE_BI;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown picture type encountered, expect the output to be broken.\n");

        av_log(avctx, AV_LOG_ERROR, "Please report this error and include as much information on how to reproduce it as possible.\n");

        res = AVERROR_EXTERNAL;

        goto error;

    }



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->pict_type = pict_type;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    ff_side_data_set_encoder_stats(pkt,

        (lock_params.frameAvgQP - 1) * FF_QP2LAMBDA, NULL, 0, pict_type);



    res = nvenc_set_timestamp(avctx, &lock_params, pkt);

    if (res < 0)

        goto error2;



    av_free(slice_offsets);



    return 0;



error:

    timestamp_queue_dequeue(ctx->timestamp_list);



error2:

    av_free(slice_offsets);



    return res;

}

static int shorten_decode_frame(AVCodecContext *avctx,

        void *data, int *data_size,

        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    ShortenContext *s = avctx->priv_data;

    int i, input_buf_size = 0;

    int16_t *samples = data;

    int ret;



    /* allocate internal bitstream buffer */

    if(s->max_framesize == 0){

        void *tmp_ptr;

        s->max_framesize= 1024; // should hopefully be enough for the first header

        tmp_ptr = av_fast_realloc(s->bitstream, &s->allocated_bitstream_size,

                                  s->max_framesize);

        if (!tmp_ptr) {

            av_log(avctx, AV_LOG_ERROR, "error allocating bitstream buffer\n");

            return AVERROR(ENOMEM);

        }

        s->bitstream = tmp_ptr;

    }



    /* append current packet data to bitstream buffer */

    if(1 && s->max_framesize){//FIXME truncated

        buf_size= FFMIN(buf_size, s->max_framesize - s->bitstream_size);

        input_buf_size= buf_size;



        if(s->bitstream_index + s->bitstream_size + buf_size > s->allocated_bitstream_size){

            memmove(s->bitstream, &s->bitstream[s->bitstream_index], s->bitstream_size);

            s->bitstream_index=0;

        }

        memcpy(&s->bitstream[s->bitstream_index + s->bitstream_size], buf, buf_size);

        buf= &s->bitstream[s->bitstream_index];

        buf_size += s->bitstream_size;

        s->bitstream_size= buf_size;



        /* do not decode until buffer has at least max_framesize bytes */

        if(buf_size < s->max_framesize){

            *data_size = 0;

            return input_buf_size;

        }

    }

    /* init and position bitstream reader */

    init_get_bits(&s->gb, buf, buf_size*8);

    skip_bits(&s->gb, s->bitindex);



    /* process header or next subblock */

    if (!s->blocksize)

    {

        if ((ret = read_header(s)) < 0)

            return ret;

        *data_size = 0;

    }

    else

    {

        int cmd;

        int len;

        cmd = get_ur_golomb_shorten(&s->gb, FNSIZE);



        if (cmd > FN_VERBATIM) {

            av_log(avctx, AV_LOG_ERROR, "unknown shorten function %d\n", cmd);

            if (s->bitstream_size > 0) {

                s->bitstream_index++;

                s->bitstream_size--;

            }

            return -1;

        }



        if (!is_audio_command[cmd]) {

            /* process non-audio command */

            switch (cmd) {

                case FN_VERBATIM:

                    len = get_ur_golomb_shorten(&s->gb, VERBATIM_CKSIZE_SIZE);

                    while (len--) {

                        get_ur_golomb_shorten(&s->gb, VERBATIM_BYTE_SIZE);

                    }

                    break;

                case FN_BITSHIFT:

                    s->bitshift = get_ur_golomb_shorten(&s->gb, BITSHIFTSIZE);

                    break;

                case FN_BLOCKSIZE: {

                    int blocksize = get_uint(s, av_log2(s->blocksize));

                    if (blocksize > s->blocksize) {

                        av_log(avctx, AV_LOG_ERROR, "Increasing block size is not supported\n");

                        return AVERROR_PATCHWELCOME;

                    }

                    if (!blocksize || blocksize > MAX_BLOCKSIZE) {

                        av_log(avctx, AV_LOG_ERROR, "invalid or unsupported "

                               "block size: %d\n", blocksize);

                        return AVERROR(EINVAL);

                    }

                    s->blocksize = blocksize;

                    break;

                }

                case FN_QUIT:

                    break;

            }

            *data_size = 0;

        } else {

            /* process audio command */

            int residual_size = 0;

            int channel = s->cur_chan;

            int32_t coffset;



            /* get Rice code for residual decoding */

            if (cmd != FN_ZERO) {

                residual_size = get_ur_golomb_shorten(&s->gb, ENERGYSIZE);

                /* this is a hack as version 0 differed in defintion of get_sr_golomb_shorten */

                if (s->version == 0)

                    residual_size--;

            }



            /* calculate sample offset using means from previous blocks */

            if (s->nmean == 0)

                coffset = s->offset[channel][0];

            else {

                int32_t sum = (s->version < 2) ? 0 : s->nmean / 2;

                for (i=0; i<s->nmean; i++)

                    sum += s->offset[channel][i];

                coffset = sum / s->nmean;

                if (s->version >= 2)

                    coffset >>= FFMIN(1, s->bitshift);

            }



            /* decode samples for this channel */

            if (cmd == FN_ZERO) {

                for (i=0; i<s->blocksize; i++)

                    s->decoded[channel][i] = 0;

            } else {

                if ((ret = decode_subframe_lpc(s, cmd, channel, residual_size, coffset)) < 0)

                    return ret;

            }



            /* update means with info from the current block */

            if (s->nmean > 0) {

                int32_t sum = (s->version < 2) ? 0 : s->blocksize / 2;

                for (i=0; i<s->blocksize; i++)

                    sum += s->decoded[channel][i];



                for (i=1; i<s->nmean; i++)

                    s->offset[channel][i-1] = s->offset[channel][i];



                if (s->version < 2)

                    s->offset[channel][s->nmean - 1] = sum / s->blocksize;

                else

                    s->offset[channel][s->nmean - 1] = (sum / s->blocksize) << s->bitshift;

            }



            /* copy wrap samples for use with next block */

            for (i=-s->nwrap; i<0; i++)

                s->decoded[channel][i] = s->decoded[channel][i + s->blocksize];



            /* shift samples to add in unused zero bits which were removed

               during encoding */

            fix_bitshift(s, s->decoded[channel]);



            /* if this is the last channel in the block, output the samples */

            s->cur_chan++;

            if (s->cur_chan == s->channels) {

                samples = interleave_buffer(samples, s->channels, s->blocksize, s->decoded);

                s->cur_chan = 0;

                *data_size = (int8_t *)samples - (int8_t *)data;

            } else {

                *data_size = 0;

            }

        }

    }



    s->bitindex = get_bits_count(&s->gb) - 8*((get_bits_count(&s->gb))/8);

    i= (get_bits_count(&s->gb))/8;

    if (i > buf_size) {

        av_log(s->avctx, AV_LOG_ERROR, "overread: %d\n", i - buf_size);

        s->bitstream_size=0;

        s->bitstream_index=0;

        return -1;

    }

    if (s->bitstream_size) {

        s->bitstream_index += i;

        s->bitstream_size  -= i;

        return input_buf_size;

    } else

        return i;

}

static int fill_default_ref_list(H264Context *h){

    MpegEncContext * const s = &h->s;

    int i;

    int smallest_poc_greater_than_current = -1;

    Picture sorted_short_ref[32];



    if(h->slice_type==B_TYPE){

        int out_i;

        int limit= -1;



        /* sort frame according to poc in B slice */

        for(out_i=0; out_i<h->short_ref_count; out_i++){

            int best_i=-1;

            int best_poc=INT_MAX;



            for(i=0; i<h->short_ref_count; i++){

                const int poc= h->short_ref[i]->poc;

                if(poc > limit && poc < best_poc){

                    best_poc= poc;

                    best_i= i;

                }

            }



            assert(best_i != -1);



            limit= best_poc;

            sorted_short_ref[out_i]= *h->short_ref[best_i];

            tprintf("sorted poc: %d->%d poc:%d fn:%d\n", best_i, out_i, sorted_short_ref[out_i].poc, sorted_short_ref[out_i].frame_num);

            if (-1 == smallest_poc_greater_than_current) {

                if (h->short_ref[best_i]->poc >= s->current_picture_ptr->poc) {

                    smallest_poc_greater_than_current = out_i;

                }

            }

        }

    }



    if(s->picture_structure == PICT_FRAME){

        if(h->slice_type==B_TYPE){

            int list;

            tprintf("current poc: %d, smallest_poc_greater_than_current: %d\n", s->current_picture_ptr->poc, smallest_poc_greater_than_current);



            // find the largest poc

            for(list=0; list<2; list++){

                int index = 0;

                int j= -99;

                int step= list ? -1 : 1;



                for(i=0; i<h->short_ref_count && index < h->ref_count[list]; i++, j+=step) {

                    while(j<0 || j>= h->short_ref_count){

                        if(j != -99 && step == (list ? -1 : 1))

                            return -1;

                        step = -step;

                        j= smallest_poc_greater_than_current + (step>>1);

                    }

                    if(sorted_short_ref[j].reference != 3) continue;

                    h->default_ref_list[list][index  ]= sorted_short_ref[j];

                    h->default_ref_list[list][index++].pic_id= sorted_short_ref[j].frame_num;

                }



                for(i = 0; i < 16 && index < h->ref_count[ list ]; i++){

                    if(h->long_ref[i] == NULL) continue;

                    if(h->long_ref[i]->reference != 3) continue;



                    h->default_ref_list[ list ][index  ]= *h->long_ref[i];

                    h->default_ref_list[ list ][index++].pic_id= i;;

                }



                if(list && (smallest_poc_greater_than_current<=0 || smallest_poc_greater_than_current>=h->short_ref_count) && (1 < index)){

                    // swap the two first elements of L1 when

                    // L0 and L1 are identical

                    Picture temp= h->default_ref_list[1][0];

                    h->default_ref_list[1][0] = h->default_ref_list[1][1];

                    h->default_ref_list[1][1] = temp;

                }



                if(index < h->ref_count[ list ])

                    memset(&h->default_ref_list[list][index], 0, sizeof(Picture)*(h->ref_count[ list ] - index));

            }

        }else{

            int index=0;

            for(i=0; i<h->short_ref_count; i++){

                if(h->short_ref[i]->reference != 3) continue; //FIXME refernce field shit

                h->default_ref_list[0][index  ]= *h->short_ref[i];

                h->default_ref_list[0][index++].pic_id= h->short_ref[i]->frame_num;

            }

            for(i = 0; i < 16; i++){

                if(h->long_ref[i] == NULL) continue;

                if(h->long_ref[i]->reference != 3) continue;

                h->default_ref_list[0][index  ]= *h->long_ref[i];

                h->default_ref_list[0][index++].pic_id= i;;

            }

            if(index < h->ref_count[0])

                memset(&h->default_ref_list[0][index], 0, sizeof(Picture)*(h->ref_count[0] - index));

        }

    }else{ //FIELD

        if(h->slice_type==B_TYPE){

        }else{

            //FIXME second field balh

        }

    }

#ifdef TRACE

    for (i=0; i<h->ref_count[0]; i++) {

        tprintf("List0: %s fn:%d 0x%p\n", (h->default_ref_list[0][i].long_ref ? "LT" : "ST"), h->default_ref_list[0][i].pic_id, h->default_ref_list[0][i].data[0]);

    }

    if(h->slice_type==B_TYPE){

        for (i=0; i<h->ref_count[1]; i++) {

            tprintf("List1: %s fn:%d 0x%p\n", (h->default_ref_list[1][i].long_ref ? "LT" : "ST"), h->default_ref_list[1][i].pic_id, h->default_ref_list[0][i].data[0]);

        }

    }

#endif

    return 0;

}

static int decode_ref_pic_marking(H264Context *h){

    MpegEncContext * const s = &h->s;

    int i;



    if(h->nal_unit_type == NAL_IDR_SLICE){ //FIXME fields

        s->broken_link= get_bits1(&s->gb) -1;

        h->mmco[0].long_index= get_bits1(&s->gb) - 1; // current_long_term_idx

        if(h->mmco[0].long_index == -1)

            h->mmco_index= 0;

        else{

            h->mmco[0].opcode= MMCO_LONG;

            h->mmco_index= 1;

        }

    }else{

        if(get_bits1(&s->gb)){ // adaptive_ref_pic_marking_mode_flag

            for(i= 0; i<MAX_MMCO_COUNT; i++) {

                MMCOOpcode opcode= get_ue_golomb(&s->gb);;



                h->mmco[i].opcode= opcode;

                if(opcode==MMCO_SHORT2UNUSED || opcode==MMCO_SHORT2LONG){

                    h->mmco[i].short_frame_num= (h->frame_num - get_ue_golomb(&s->gb) - 1) & ((1<<h->sps.log2_max_frame_num)-1); //FIXME fields

/*                    if(h->mmco[i].short_frame_num >= h->short_ref_count || h->short_ref[ h->mmco[i].short_frame_num ] == NULL){

                        av_log(s->avctx, AV_LOG_ERROR, "illegal short ref in memory management control operation %d\n", mmco);

                        return -1;

                    }*/

                }

                if(opcode==MMCO_SHORT2LONG || opcode==MMCO_LONG2UNUSED || opcode==MMCO_LONG || opcode==MMCO_SET_MAX_LONG){

                    h->mmco[i].long_index= get_ue_golomb(&s->gb);

                    if(/*h->mmco[i].long_index >= h->long_ref_count || h->long_ref[ h->mmco[i].long_index ] == NULL*/ h->mmco[i].long_index >= 16){

                        av_log(h->s.avctx, AV_LOG_ERROR, "illegal long ref in memory management control operation %d\n", opcode);

                        return -1;

                    }

                }



                if(opcode > MMCO_LONG){

                    av_log(h->s.avctx, AV_LOG_ERROR, "illegal memory management control operation %d\n", opcode);

                    return -1;

                }

                if(opcode == MMCO_END)

                    break;

            }

            h->mmco_index= i;

        }else{

            assert(h->long_ref_count + h->short_ref_count <= h->sps.ref_frame_count);



            if(h->long_ref_count + h->short_ref_count == h->sps.ref_frame_count){ //FIXME fields

                h->mmco[0].opcode= MMCO_SHORT2UNUSED;

                h->mmco[0].short_frame_num= h->short_ref[ h->short_ref_count - 1 ]->frame_num;

                h->mmco_index= 1;

            }else

                h->mmco_index= 0;

        }

    }



    return 0;

}

static int decode_ref_pic_list_reordering(H264Context *h){

    MpegEncContext * const s = &h->s;

    int list, index, pic_structure;



    print_short_term(h);

    print_long_term(h);

    if(h->slice_type==FF_I_TYPE || h->slice_type==FF_SI_TYPE) return 0; //FIXME move before func



    for(list=0; list<h->list_count; list++){

        memcpy(h->ref_list[list], h->default_ref_list[list], sizeof(Picture)*h->ref_count[list]);



        if(get_bits1(&s->gb)){

            int pred= h->curr_pic_num;



            for(index=0; ; index++){

                unsigned int reordering_of_pic_nums_idc= get_ue_golomb(&s->gb);

                unsigned int pic_id;

                int i;

                Picture *ref = NULL;



                if(reordering_of_pic_nums_idc==3)

                    break;



                if(index >= h->ref_count[list]){

                    av_log(h->s.avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                if(reordering_of_pic_nums_idc<3){

                    if(reordering_of_pic_nums_idc<2){

                        const unsigned int abs_diff_pic_num= get_ue_golomb(&s->gb) + 1;

                        int frame_num;



                        if(abs_diff_pic_num > h->max_pic_num){

                            av_log(h->s.avctx, AV_LOG_ERROR, "abs_diff_pic_num overflow\n");

                            return -1;

                        }



                        if(reordering_of_pic_nums_idc == 0) pred-= abs_diff_pic_num;

                        else                                pred+= abs_diff_pic_num;

                        pred &= h->max_pic_num - 1;



                        frame_num = pic_num_extract(h, pred, &pic_structure);



                        for(i= h->short_ref_count-1; i>=0; i--){

                            ref = h->short_ref[i];

                            assert(ref->reference);

                            assert(!ref->long_ref);

                            if(ref->data[0] != NULL &&

                                   ref->frame_num == frame_num &&

                                   (ref->reference & pic_structure) &&

                                   ref->long_ref == 0) // ignore non existing pictures by testing data[0] pointer

                                break;

                        }

                        if(i>=0)

                            ref->pic_id= pred;

                    }else{

                        int long_idx;

                        pic_id= get_ue_golomb(&s->gb); //long_term_pic_idx



                        long_idx= pic_num_extract(h, pic_id, &pic_structure);



                        if(long_idx>31){

                            av_log(h->s.avctx, AV_LOG_ERROR, "long_term_pic_idx overflow\n");

                            return -1;

                        }

                        ref = h->long_ref[long_idx];

                        assert(!(ref && !ref->reference));

                        if(ref && (ref->reference & pic_structure)){

                            ref->pic_id= pic_id;

                            assert(ref->long_ref);

                            i=0;

                        }else{

                            i=-1;

                        }

                    }



                    if (i < 0) {

                        av_log(h->s.avctx, AV_LOG_ERROR, "reference picture missing during reorder\n");

                        memset(&h->ref_list[list][index], 0, sizeof(Picture)); //FIXME

                    } else {

                        for(i=index; i+1<h->ref_count[list]; i++){

                            if(ref->long_ref == h->ref_list[list][i].long_ref && ref->pic_id == h->ref_list[list][i].pic_id)

                                break;

                        }

                        for(; i > index; i--){

                            h->ref_list[list][i]= h->ref_list[list][i-1];

                        }

                        h->ref_list[list][index]= *ref;

                        if (FIELD_PICTURE){

                            pic_as_field(&h->ref_list[list][index], pic_structure);

                        }

                    }

                }else{

                    av_log(h->s.avctx, AV_LOG_ERROR, "illegal reordering_of_pic_nums_idc\n");

                    return -1;

                }

            }

        }

    }

    for(list=0; list<h->list_count; list++){

        for(index= 0; index < h->ref_count[list]; index++){

            if(!h->ref_list[list][index].data[0])

                h->ref_list[list][index]= s->current_picture;

        }

    }



    if(h->slice_type==FF_B_TYPE && !h->direct_spatial_mv_pred)

        direct_dist_scale_factor(h);

    direct_ref_list_init(h);

    return 0;

}

static inline void direct_ref_list_init(H264Context * const h){

    MpegEncContext * const s = &h->s;

    Picture * const ref1 = &h->ref_list[1][0];

    Picture * const cur = s->current_picture_ptr;

    int list, i, j;

    int sidx= s->picture_structure&1;

    int ref1sidx= ref1->reference&1;

    for(list=0; list<2; list++){

        cur->ref_count[sidx][list] = h->ref_count[list];

        for(j=0; j<h->ref_count[list]; j++)

            cur->ref_poc[sidx][list][j] = h->ref_list[list][j].poc;

    }

    if(s->picture_structure == PICT_FRAME){

        memcpy(cur->ref_count[0], cur->ref_count[1], sizeof(cur->ref_count[0]));

        memcpy(cur->ref_poc  [0], cur->ref_poc  [1], sizeof(cur->ref_poc  [0]));

    }

    if(cur->pict_type != FF_B_TYPE || h->direct_spatial_mv_pred)

        return;

    for(list=0; list<2; list++){

        for(i=0; i<ref1->ref_count[ref1sidx][list]; i++){

            const int poc = ref1->ref_poc[ref1sidx][list][i];

            h->map_col_to_list0[list][i] = 0; /* bogus; fills in for missing frames */

            for(j=0; j<h->ref_count[list]; j++)

                if(h->ref_list[list][j].poc == poc){

                    h->map_col_to_list0[list][i] = j;

                    break;

                }

        }

    }

    if(FRAME_MBAFF){

        for(list=0; list<2; list++){

            for(i=0; i<ref1->ref_count[ref1sidx][list]; i++){

                j = h->map_col_to_list0[list][i];

                h->map_col_to_list0_field[list][2*i] = 2*j;

                h->map_col_to_list0_field[list][2*i+1] = 2*j+1;

            }

        }

    }

}

static int qemu_save_device_state(QEMUFile *f)
{
    SaveStateEntry *se;
    qemu_put_be32(f, QEMU_VM_FILE_MAGIC);
    qemu_put_be32(f, QEMU_VM_FILE_VERSION);
    cpu_synchronize_all_states();
    QTAILQ_FOREACH(se, &savevm_state.handlers, entry) {
        if (se->is_ram) {
            continue;
        }
        if ((!se->ops || !se->ops->save_state) && !se->vmsd) {
            continue;
        }
        save_section_header(f, se, QEMU_VM_SECTION_FULL);
        vmstate_save(f, se, NULL);
    }
    qemu_put_byte(f, QEMU_VM_EOF);
    return qemu_file_get_error(f);
}

void qemu_savevm_state_begin(QEMUFile *f,

                             const MigrationParams *params)

{

    SaveStateEntry *se;

    int ret;



    trace_savevm_state_begin();

    QTAILQ_FOREACH(se, &savevm_state.handlers, entry) {

        if (!se->ops || !se->ops->set_params) {

            continue;

        }

        se->ops->set_params(params, se->opaque);

    }



    QTAILQ_FOREACH(se, &savevm_state.handlers, entry) {

        if (!se->ops || !se->ops->save_live_setup) {

            continue;

        }

        if (se->ops && se->ops->is_active) {

            if (!se->ops->is_active(se->opaque)) {

                continue;

            }

        }

        save_section_header(f, se, QEMU_VM_SECTION_START);



        ret = se->ops->save_live_setup(f, se->opaque);


        if (ret < 0) {

            qemu_file_set_error(f, ret);

            break;

        }

    }

}

int qemu_savevm_state_complete(Monitor *mon, QEMUFile *f)

{

    SaveStateEntry *se;



    cpu_synchronize_all_states();



    QTAILQ_FOREACH(se, &savevm_handlers, entry) {

        if (se->save_live_state == NULL)

            continue;



        /* Section type */

        qemu_put_byte(f, QEMU_VM_SECTION_END);

        qemu_put_be32(f, se->section_id);



        se->save_live_state(mon, f, QEMU_VM_SECTION_END, se->opaque);

    }



    QTAILQ_FOREACH(se, &savevm_handlers, entry) {

        int len;



	if (se->save_state == NULL && se->vmsd == NULL)

	    continue;



        /* Section type */

        qemu_put_byte(f, QEMU_VM_SECTION_FULL);

        qemu_put_be32(f, se->section_id);



        /* ID string */

        len = strlen(se->idstr);

        qemu_put_byte(f, len);

        qemu_put_buffer(f, (uint8_t *)se->idstr, len);



        qemu_put_be32(f, se->instance_id);

        qemu_put_be32(f, se->version_id);



        vmstate_save(f, se);

    }



    qemu_put_byte(f, QEMU_VM_EOF);



    return qemu_file_get_error(f);

}

static void qemu_fflush(QEMUFile *f)

{

    int ret = 0;



    if (!f->ops->put_buffer) {

        return;

    }

    if (f->is_write && f->buf_index > 0) {

        ret = f->ops->put_buffer(f->opaque, f->buf, f->buf_offset, f->buf_index);

        if (ret >= 0) {

            f->buf_offset += f->buf_index;

        }

        f->buf_index = 0;

    }

    if (ret < 0) {

        qemu_file_set_error(f, ret);

    }

}

