static int get_metadata(AVFormatContext *s,

                        const char *const tag,

                        const unsigned data_size)

{

    uint8_t *buf = ((data_size + 1) == 0) ? NULL : av_malloc(data_size + 1);



    if (!buf)

        return AVERROR(ENOMEM);



    if (avio_read(s->pb, buf, data_size) < 0) {

        av_free(buf);

        return AVERROR(EIO);

    }

    buf[data_size] = 0;

    av_dict_set(&s->metadata, tag, buf, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

int avio_close_dyn_buf(AVIOContext *s, uint8_t **pbuffer)

{

    DynBuffer *d;

    int size;

    static const char padbuf[AV_INPUT_BUFFER_PADDING_SIZE] = {0};

    int padding = 0;



    if (!s) {

        *pbuffer = NULL;

        return 0;

    }



    /* don't attempt to pad fixed-size packet buffers */

    if (!s->max_packet_size) {

        avio_write(s, padbuf, sizeof(padbuf));

        padding = AV_INPUT_BUFFER_PADDING_SIZE;

    }



    avio_flush(s);



    d = s->opaque;

    *pbuffer = d->buffer;

    size = d->size;

    av_free(d);

    av_free(s);

    return size - padding;

}

int avio_close(AVIOContext *s)

{

    AVIOInternal *internal;

    URLContext *h;



    if (!s)

        return 0;



    avio_flush(s);

    internal = s->opaque;

    h        = internal->h;



    av_opt_free(internal);



    av_freep(&internal->protocols);

    av_freep(&s->opaque);

    av_freep(&s->buffer);

    av_free(s);

    return ffurl_close(h);

}

