static int microdvd_probe(AVProbeData *p)

{

    unsigned char c;

    const uint8_t *ptr = p->buf;

    int i;



    if (AV_RB24(ptr) == 0xEFBBBF)

        ptr += 3;  /* skip UTF-8 BOM */



    for (i=0; i<3; i++) {

        if (sscanf(ptr, "{%*d}{}%c",     &c) != 1 &&

            sscanf(ptr, "{%*d}{%*d}%c",  &c) != 1 &&

            sscanf(ptr, "{DEFAULT}{}%c", &c) != 1)

            return 0;

        ptr += strcspn(ptr, "\n") + 1;

    }

    return AVPROBE_SCORE_MAX;

}

static int mpsub_probe(AVProbeData *p)

{

    const char *ptr     = p->buf;

    const char *ptr_end = p->buf + p->buf_size;



    while (ptr < ptr_end) {

        if (!memcmp(ptr, "FORMAT=TIME", 11))

            return AVPROBE_SCORE_EXTENSION;

        if (!memcmp(ptr, "FORMAT=", 7))

            return AVPROBE_SCORE_EXTENSION / 3;

        ptr += strcspn(ptr, "\n") + 1;

    }

    return 0;

}

static int mpc_probe(AVProbeData *p)

{

    const uint8_t *d = p->buf;

    if (p->buf_size < 32)

        return 0;

    if (d[0] == 'M' && d[1] == 'P' && d[2] == '+' && (d[3] == 0x17 || d[3] == 0x7))

        return AVPROBE_SCORE_MAX;

    if (d[0] == 'I' && d[1] == 'D' && d[2] == '3')

        return AVPROBE_SCORE_MAX / 2;

    return 0;

}

static int mpl2_probe(AVProbeData *p)

{

    int i;

    char c;

    int64_t start, end;

    const unsigned char *ptr = p->buf;

    const unsigned char *ptr_end = ptr + p->buf_size;



    for (i = 0; i < 2; i++) {

        if (sscanf(ptr, "[%"SCNd64"][%"SCNd64"]%c", &start, &end, &c) != 3 &&

            sscanf(ptr, "[%"SCNd64"][]%c",          &start,       &c) != 2)

            return 0;

        ptr += strcspn(ptr, "\n") + 1;

        if (ptr >= ptr_end)

            return 0;

    }

    return AVPROBE_SCORE_MAX;

}

static int piix4_device_hotplug(DeviceState *qdev, PCIDevice *dev,

				PCIHotplugState state)

{

    int slot = PCI_SLOT(dev->devfn);

    PIIX4PMState *s = DO_UPCAST(PIIX4PMState, dev,

                                PCI_DEVICE(qdev));



    /* Don't send event when device is enabled during qemu machine creation:

     * it is present on boot, no hotplug event is necessary. We do send an

     * event when the device is disabled later. */

    if (state == PCI_COLDPLUG_ENABLED) {

        return 0;

    }



    s->pci0_status.up = 0;

    s->pci0_status.down = 0;

    if (state == PCI_HOTPLUG_ENABLED) {

        enable_device(s, slot);

    } else {

        disable_device(s, slot);

    }



    pm_update_sci(s);



    return 0;

}

static void acpi_pcihp_update_hotplug_bus(AcpiPciHpState *s, int bsel)

{

    BusChild *kid, *next;

    PCIBus *bus = acpi_pcihp_find_hotplug_bus(s, bsel);



    /* Execute any pending removes during reset */

    while (s->acpi_pcihp_pci_status[bsel].down) {

        acpi_pcihp_eject_slot(s, bsel, s->acpi_pcihp_pci_status[bsel].down);

    }



    s->acpi_pcihp_pci_status[bsel].hotplug_enable = ~0;

    s->acpi_pcihp_pci_status[bsel].device_present = 0;



    if (!bus) {

        return;

    }

    QTAILQ_FOREACH_SAFE(kid, &bus->qbus.children, sibling, next) {

        DeviceState *qdev = kid->child;

        PCIDevice *pdev = PCI_DEVICE(qdev);

        int slot = PCI_SLOT(pdev->devfn);



        if (acpi_pcihp_pc_no_hotplug(s, pdev)) {

            s->acpi_pcihp_pci_status[bsel].hotplug_enable &= ~(1U << slot);

        }



        s->acpi_pcihp_pci_status[bsel].device_present |= (1U << slot);

    }

}

static void acpi_get_hotplug_info(AcpiMiscInfo *misc)

{

    int i;

    PCIBus *bus = find_i440fx();



    if (!bus) {

        /* Only PIIX supports ACPI hotplug */

        memset(misc->slot_hotplug_enable, 0, sizeof misc->slot_hotplug_enable);

        return;

    }



    memset(misc->slot_hotplug_enable, 0xff,

           DIV_ROUND_UP(PCI_SLOT_MAX, BITS_PER_BYTE));



    for (i = 0; i < ARRAY_SIZE(bus->devices); ++i) {

        PCIDeviceClass *pc;

        PCIDevice *pdev = bus->devices[i];



        if (!pdev) {

            continue;

        }



        pc = PCI_DEVICE_GET_CLASS(pdev);



        if (pc->no_hotplug) {

            int slot = PCI_SLOT(i);



            clear_bit(slot, misc->slot_hotplug_enable);

        }

    }

}

static int pci_qdev_init(DeviceState *qdev, DeviceInfo *base)

{

    PCIDevice *pci_dev = (PCIDevice *)qdev;

    PCIDeviceInfo *info = container_of(base, PCIDeviceInfo, qdev);

    PCIBus *bus;

    int devfn, rc;



    /* initialize cap_present for pci_is_express() and pci_config_size() */

    if (info->is_express) {

        pci_dev->cap_present |= QEMU_PCI_CAP_EXPRESS;

    }



    bus = FROM_QBUS(PCIBus, qdev_get_parent_bus(qdev));

    devfn = pci_dev->devfn;

    pci_dev = do_pci_register_device(pci_dev, bus, base->name, devfn,

                                     info->config_read, info->config_write);

    assert(pci_dev);

    rc = info->init(pci_dev);

    if (rc != 0)

        return rc;

    if (qdev->hotplugged)

        bus->hotplug(pci_dev, 1);

    return 0;

}

