}

void qemu_set_dfilter_ranges(const char *filter_spec, Error **errp)

{

    gchar **ranges = g_strsplit(filter_spec, ",", 0);

    int i;



    if (debug_regions) {

        g_array_unref(debug_regions);

        debug_regions = NULL;

    }



    debug_regions = g_array_sized_new(FALSE, FALSE,

                                      sizeof(Range), g_strv_length(ranges));

    for (i = 0; ranges[i]; i++) {

        const char *r = ranges[i];

        const char *range_op, *r2, *e;

        uint64_t r1val, r2val, lob, upb;

        struct Range range;



        range_op = strstr(r, "-");

        r2 = range_op ? range_op + 1 : NULL;

        if (!range_op) {

            range_op = strstr(r, "+");

            r2 = range_op ? range_op + 1 : NULL;

        }

        if (!range_op) {

            range_op = strstr(r, "..");

            r2 = range_op ? range_op + 2 : NULL;

        }

        if (!range_op) {

            error_setg(errp, "Bad range specifier");

            goto out;

        }



        if (qemu_strtoull(r, &e, 0, &r1val)

            || e != range_op) {

            error_setg(errp, "Invalid number to the left of %.*s",

                       (int)(r2 - range_op), range_op);

            goto out;

        }

        if (qemu_strtoull(r2, NULL, 0, &r2val)) {

            error_setg(errp, "Invalid number to the right of %.*s",

                       (int)(r2 - range_op), range_op);

            goto out;

        }



        switch (*range_op) {

        case '+':

            lob = r1val;

            upb = r1val + r2val - 1;

            break;

        case '-':

            upb = r1val;

            lob = r1val - (r2val - 1);

            break;

        case '.':

            lob = r1val;

            upb = r2val;

            break;

        default:

            g_assert_not_reached();

        }

        if (lob > upb || (lob == 0 && upb == UINT64_MAX)) {

            error_setg(errp, "Invalid range");

            goto out;

        }

        range.begin = lob;

        range.end = upb + 1;

        g_array_append_val(debug_regions, range);

    }

out:

    g_strfreev(ranges);

}

static int eval_refl(int *refl, const int16_t *coefs, RA144Context *ractx)

{

    int b, i, j;

    int buffer1[10];

    int buffer2[10];

    int *bp1 = buffer1;

    int *bp2 = buffer2;



    for (i=0; i < 10; i++)

        buffer2[i] = coefs[i];



    refl[9] = bp2[9];



    if ((unsigned) bp2[9] + 0x1000 > 0x1fff) {

        av_log(ractx, AV_LOG_ERROR, "Overflow. Broken sample?\n");

        return 1;

    }



    for (i=8; i >= 0; i--) {

        b = 0x1000-((bp2[i+1] * bp2[i+1]) >> 12);



        if (!b)

            b = -2;



        for (j=0; j <= i; j++)

            bp1[j] = ((bp2[j] - ((refl[i+1] * bp2[i-j]) >> 12)) * (0x1000000 / b)) >> 12;



        refl[i] = bp1[i];



        if ((unsigned) bp1[i] + 0x1000 > 0x1fff)

            return 1;



        FFSWAP(int *, bp1, bp2);

    }

    return 0;

}

int ff_eval_refl(int *refl, const int16_t *coefs, AVCodecContext *avctx)

{

    int b, i, j;

    int buffer1[LPC_ORDER];

    int buffer2[LPC_ORDER];

    int *bp1 = buffer1;

    int *bp2 = buffer2;



    for (i=0; i < LPC_ORDER; i++)

        buffer2[i] = coefs[i];



    refl[LPC_ORDER-1] = bp2[LPC_ORDER-1];



    if ((unsigned) bp2[LPC_ORDER-1] + 0x1000 > 0x1fff) {

        av_log(avctx, AV_LOG_ERROR, "Overflow. Broken sample?\n");

        return 1;

    }



    for (i = LPC_ORDER-2; i >= 0; i--) {

        b = 0x1000-((bp2[i+1] * bp2[i+1]) >> 12);



        if (!b)

            b = -2;



        b = 0x1000000 / b;

        for (j=0; j <= i; j++) {

#if CONFIG_FTRAPV

            int a = bp2[j] - ((refl[i+1] * bp2[i-j]) >> 12);

            if((int)(a*(unsigned)b) != a*(int64_t)b)

                return 1;

#endif

            bp1[j] = ((bp2[j] - ((refl[i+1] * bp2[i-j]) >> 12)) * b) >> 12;

        }



        if ((unsigned) bp1[i] + 0x1000 > 0x1fff)

            return 1;



        refl[i] = bp1[i];



        FFSWAP(int *, bp1, bp2);

    }

    return 0;

}

static void fft_test(AC3MDCTContext *mdct, AVLFG *lfg)

{

    IComplex in[FN], in1[FN];

    int k, n, i;

    float sum_re, sum_im, a;



    for (i = 0; i < FN; i++) {

        in[i].re = av_lfg_get(lfg) % 65535 - 32767;

        in[i].im = av_lfg_get(lfg) % 65535 - 32767;

        in1[i]   = in[i];

    }

    fft(mdct, in, 7);



    /* do it by hand */

    for (k = 0; k < FN; k++) {

        sum_re = 0;

        sum_im = 0;

        for (n = 0; n < FN; n++) {

            a = -2 * M_PI * (n * k) / FN;

            sum_re += in1[n].re * cos(a) - in1[n].im * sin(a);

            sum_im += in1[n].re * sin(a) + in1[n].im * cos(a);

        }

        av_log(NULL, AV_LOG_DEBUG, "%3d: %6d,%6d %6.0f,%6.0f\n",

               k, in[k].re, in[k].im, sum_re / FN, sum_im / FN);

    }

}

