static int decode_segment(TAKDecContext *s, int8_t mode, int32_t *decoded, int len)

{

    struct CParam code;

    GetBitContext *gb = &s->gb;

    int i;



    if (!mode) {

        memset(decoded, 0, len * sizeof(*decoded));

        return 0;

    }



    if (mode > FF_ARRAY_ELEMS(xcodes))

        return AVERROR_INVALIDDATA;

    code = xcodes[mode - 1];



    for (i = 0; i < len; i++) {

        int x = get_bits_long(gb, code.init);

        if (x >= code.escape && get_bits1(gb)) {

            x |= 1 << code.init;

            if (x >= code.aescape) {

                int scale = get_unary(gb, 1, 9);

                if (scale == 9) {

                    int scale_bits = get_bits(gb, 3);

                    if (scale_bits > 0) {

                        if (scale_bits == 7) {

                            scale_bits += get_bits(gb, 5);

                            if (scale_bits > 29)

                                return AVERROR_INVALIDDATA;

                        }

                        scale = get_bits_long(gb, scale_bits) + 1;

                        x    += code.scale * scale;

                    }

                    x += code.bias;

                } else

                    x += code.scale * scale - code.escape;

            } else

                x -= code.escape;

        }

        decoded[i] = (x >> 1) ^ -(x & 1);

    }



    return 0;

}

static int hq_decode_block(HQContext *c, GetBitContext *gb, int16_t block[64],

                           int qsel, int is_chroma, int is_hqa)

{

    const int32_t *q;

    int val, pos = 1;



    memset(block, 0, 64 * sizeof(*block));



    if (!is_hqa) {

        block[0] = get_sbits(gb, 9) * 64;

        q = ff_hq_quants[qsel][is_chroma][get_bits(gb, 2)];

    } else {

        q = ff_hq_quants[qsel][is_chroma][get_bits(gb, 2)];

        block[0] = get_sbits(gb, 9) * 64;

    }



    for (;;) {

        val = get_vlc2(gb, c->hq_ac_vlc.table, 9, 2);

        if (val < 0)

            return AVERROR_INVALIDDATA;



        pos += ff_hq_ac_skips[val];

        if (pos >= 64)

            break;

        block[ff_zigzag_direct[pos]] = (ff_hq_ac_syms[val] * q[pos]) >> 12;

        pos++;

    }



    return 0;

}

static void decode_block(BinkAudioContext *s, short *out, int use_dct)

{

    int ch, i, j, k;

    float q, quant[25];

    int width, coeff;

    GetBitContext *gb = &s->gb;



    if (use_dct)

        skip_bits(gb, 2);



    for (ch = 0; ch < s->channels; ch++) {

        FFTSample *coeffs = s->coeffs_ptr[ch];

        q = 0.0f;

        coeffs[0] = get_float(gb) * s->root;

        coeffs[1] = get_float(gb) * s->root;



        for (i = 0; i < s->num_bands; i++) {

            /* constant is result of 0.066399999/log10(M_E) */

            int value = get_bits(gb, 8);

            quant[i] = expf(FFMIN(value, 95) * 0.15289164787221953823f) * s->root;

        }



        // find band (k)

        for (k = 0; s->bands[k] < 1; k++) {

            q = quant[k];

        }



        // parse coefficients

        i = 2;

        while (i < s->frame_len) {

            if (get_bits1(gb)) {

                j = i + rle_length_tab[get_bits(gb, 4)] * 8;

            } else {

                j = i + 8;

            }



            j = FFMIN(j, s->frame_len);



            width = get_bits(gb, 4);

            if (width == 0) {

                memset(coeffs + i, 0, (j - i) * sizeof(*coeffs));

                i = j;

                while (s->bands[k] < i)

                    q = quant[k++];

            } else {

                while (i < j) {

                    if (s->bands[k] == i)

                        q = quant[k++];

                    coeff = get_bits(gb, width);

                    if (coeff) {

                        if (get_bits1(gb))

                            coeffs[i] = -q * coeff;

                        else

                            coeffs[i] =  q * coeff;

                    } else {

                        coeffs[i] = 0.0f;

                    }

                    i++;

                }

            }

        }



        if (CONFIG_BINKAUDIO_DCT_DECODER && use_dct) {

            coeffs[0] /= 0.5;

            ff_dct_calc (&s->trans.dct,  coeffs);

            s->dsp.vector_fmul_scalar(coeffs, coeffs, s->frame_len / 2, s->frame_len);

        }

        else if (CONFIG_BINKAUDIO_RDFT_DECODER)

            ff_rdft_calc(&s->trans.rdft, coeffs);

    }



    s->fmt_conv.float_to_int16_interleave(out, (const float **)s->coeffs_ptr,

                                          s->frame_len, s->channels);



    if (!s->first) {

        int count = s->overlap_len * s->channels;

        int shift = av_log2(count);

        for (i = 0; i < count; i++) {

            out[i] = (s->previous[i] * (count - i) + out[i] * i) >> shift;

        }

    }



    memcpy(s->previous, out + s->block_size,

           s->overlap_len * s->channels * sizeof(*out));



    s->first = 0;

}

