int ff_h263_decode_mb(MpegEncContext *s,

                      int16_t block[6][64])

{

    int cbpc, cbpy, i, cbp, pred_x, pred_y, mx, my, dquant;

    int16_t *mot_val;

    const int xy= s->mb_x + s->mb_y * s->mb_stride;

    int cbpb = 0, pb_mv_count = 0;



    assert(!s->h263_pred);



    if (s->pict_type == AV_PICTURE_TYPE_P) {

        do{

            if (get_bits1(&s->gb)) {

                /* skip mb */

                s->mb_intra = 0;

                for(i=0;i<6;i++)

                    s->block_last_index[i] = -1;

                s->mv_dir = MV_DIR_FORWARD;

                s->mv_type = MV_TYPE_16X16;

                s->current_picture.mb_type[xy] = MB_TYPE_SKIP | MB_TYPE_16x16 | MB_TYPE_L0;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->mb_skipped = !(s->obmc | s->loop_filter);

                goto end;

            }

            cbpc = get_vlc2(&s->gb, ff_h263_inter_MCBPC_vlc.table, INTER_MCBPC_VLC_BITS, 2);

            if (cbpc < 0){

                av_log(s->avctx, AV_LOG_ERROR, "cbpc damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }

        }while(cbpc == 20);



        s->dsp.clear_blocks(s->block[0]);



        dquant = cbpc & 8;

        s->mb_intra = ((cbpc & 4) != 0);

        if (s->mb_intra) goto intra;



        if(s->pb_frame && get_bits1(&s->gb))

            pb_mv_count = h263_get_modb(&s->gb, s->pb_frame, &cbpb);

        cbpy = get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);



        if(s->alt_inter_vlc==0 || (cbpc & 3)!=3)

            cbpy ^= 0xF;



        cbp = (cbpc & 3) | (cbpy << 2);

        if (dquant) {

            h263_decode_dquant(s);

        }



        s->mv_dir = MV_DIR_FORWARD;

        if ((cbpc & 16) == 0) {

            s->current_picture.mb_type[xy] = MB_TYPE_16x16 | MB_TYPE_L0;

            /* 16x16 motion prediction */

            s->mv_type = MV_TYPE_16X16;

            ff_h263_pred_motion(s, 0, 0, &pred_x, &pred_y);

            if (s->umvplus)

               mx = h263p_decode_umotion(s, pred_x);

            else

               mx = ff_h263_decode_motion(s, pred_x, 1);



            if (mx >= 0xffff)

                return -1;



            if (s->umvplus)

               my = h263p_decode_umotion(s, pred_y);

            else

               my = ff_h263_decode_motion(s, pred_y, 1);



            if (my >= 0xffff)

                return -1;

            s->mv[0][0][0] = mx;

            s->mv[0][0][1] = my;



            if (s->umvplus && (mx - pred_x) == 1 && (my - pred_y) == 1)

               skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */

        } else {

            s->current_picture.mb_type[xy] = MB_TYPE_8x8 | MB_TYPE_L0;

            s->mv_type = MV_TYPE_8X8;

            for(i=0;i<4;i++) {

                mot_val = ff_h263_pred_motion(s, i, 0, &pred_x, &pred_y);

                if (s->umvplus)

                  mx = h263p_decode_umotion(s, pred_x);

                else

                  mx = ff_h263_decode_motion(s, pred_x, 1);

                if (mx >= 0xffff)

                    return -1;



                if (s->umvplus)

                  my = h263p_decode_umotion(s, pred_y);

                else

                  my = ff_h263_decode_motion(s, pred_y, 1);

                if (my >= 0xffff)

                    return -1;

                s->mv[0][i][0] = mx;

                s->mv[0][i][1] = my;

                if (s->umvplus && (mx - pred_x) == 1 && (my - pred_y) == 1)

                  skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */

                mot_val[0] = mx;

                mot_val[1] = my;

            }

        }

    } else if(s->pict_type==AV_PICTURE_TYPE_B) {

        int mb_type;

        const int stride= s->b8_stride;

        int16_t *mot_val0 = s->current_picture.motion_val[0][2 * (s->mb_x + s->mb_y * stride)];

        int16_t *mot_val1 = s->current_picture.motion_val[1][2 * (s->mb_x + s->mb_y * stride)];

//        const int mv_xy= s->mb_x + 1 + s->mb_y * s->mb_stride;



        //FIXME ugly

        mot_val0[0       ]= mot_val0[2       ]= mot_val0[0+2*stride]= mot_val0[2+2*stride]=

        mot_val0[1       ]= mot_val0[3       ]= mot_val0[1+2*stride]= mot_val0[3+2*stride]=

        mot_val1[0       ]= mot_val1[2       ]= mot_val1[0+2*stride]= mot_val1[2+2*stride]=

        mot_val1[1       ]= mot_val1[3       ]= mot_val1[1+2*stride]= mot_val1[3+2*stride]= 0;



        do{

            mb_type= get_vlc2(&s->gb, h263_mbtype_b_vlc.table, H263_MBTYPE_B_VLC_BITS, 2);

            if (mb_type < 0){

                av_log(s->avctx, AV_LOG_ERROR, "b mb_type damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            mb_type= h263_mb_type_b_map[ mb_type ];

        }while(!mb_type);



        s->mb_intra = IS_INTRA(mb_type);

        if(HAS_CBP(mb_type)){

            s->dsp.clear_blocks(s->block[0]);

            cbpc = get_vlc2(&s->gb, cbpc_b_vlc.table, CBPC_B_VLC_BITS, 1);

            if(s->mb_intra){

                dquant = IS_QUANT(mb_type);

                goto intra;

            }



            cbpy = get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);



            if (cbpy < 0){

                av_log(s->avctx, AV_LOG_ERROR, "b cbpy damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            if(s->alt_inter_vlc==0 || (cbpc & 3)!=3)

                cbpy ^= 0xF;



            cbp = (cbpc & 3) | (cbpy << 2);

        }else

            cbp=0;



        assert(!s->mb_intra);



        if(IS_QUANT(mb_type)){

            h263_decode_dquant(s);

        }



        if(IS_DIRECT(mb_type)){



            s->mv_dir = MV_DIR_FORWARD | MV_DIR_BACKWARD | MV_DIRECT;

            mb_type |= ff_mpeg4_set_direct_mv(s, 0, 0);

        }else{

            s->mv_dir = 0;

            s->mv_type= MV_TYPE_16X16;

//FIXME UMV



            if(USES_LIST(mb_type, 0)){

                int16_t *mot_val= ff_h263_pred_motion(s, 0, 0, &mx, &my);

                s->mv_dir = MV_DIR_FORWARD;



                mx = ff_h263_decode_motion(s, mx, 1);

                my = ff_h263_decode_motion(s, my, 1);



                s->mv[0][0][0] = mx;

                s->mv[0][0][1] = my;

                mot_val[0       ]= mot_val[2       ]= mot_val[0+2*stride]= mot_val[2+2*stride]= mx;

                mot_val[1       ]= mot_val[3       ]= mot_val[1+2*stride]= mot_val[3+2*stride]= my;

            }



            if(USES_LIST(mb_type, 1)){

                int16_t *mot_val= ff_h263_pred_motion(s, 0, 1, &mx, &my);

                s->mv_dir |= MV_DIR_BACKWARD;



                mx = ff_h263_decode_motion(s, mx, 1);

                my = ff_h263_decode_motion(s, my, 1);



                s->mv[1][0][0] = mx;

                s->mv[1][0][1] = my;

                mot_val[0       ]= mot_val[2       ]= mot_val[0+2*stride]= mot_val[2+2*stride]= mx;

                mot_val[1       ]= mot_val[3       ]= mot_val[1+2*stride]= mot_val[3+2*stride]= my;

            }

        }



        s->current_picture.mb_type[xy] = mb_type;

    } else { /* I-Frame */

        do{

            cbpc = get_vlc2(&s->gb, ff_h263_intra_MCBPC_vlc.table, INTRA_MCBPC_VLC_BITS, 2);

            if (cbpc < 0){

                av_log(s->avctx, AV_LOG_ERROR, "I cbpc damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }

        }while(cbpc == 8);



        s->dsp.clear_blocks(s->block[0]);



        dquant = cbpc & 4;

        s->mb_intra = 1;

intra:

        s->current_picture.mb_type[xy] = MB_TYPE_INTRA;

        if (s->h263_aic) {

            s->ac_pred = get_bits1(&s->gb);

            if(s->ac_pred){

                s->current_picture.mb_type[xy] = MB_TYPE_INTRA | MB_TYPE_ACPRED;



                s->h263_aic_dir = get_bits1(&s->gb);

            }

        }else

            s->ac_pred = 0;



        if(s->pb_frame && get_bits1(&s->gb))

            pb_mv_count = h263_get_modb(&s->gb, s->pb_frame, &cbpb);

        cbpy = get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);

        if(cbpy<0){

            av_log(s->avctx, AV_LOG_ERROR, "I cbpy damaged at %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        cbp = (cbpc & 3) | (cbpy << 2);

        if (dquant) {

            h263_decode_dquant(s);

        }



        pb_mv_count += !!s->pb_frame;

    }



    while(pb_mv_count--){

        ff_h263_decode_motion(s, 0, 1);

        ff_h263_decode_motion(s, 0, 1);

    }



    /* decode each block */

    for (i = 0; i < 6; i++) {

        if (h263_decode_block(s, block[i], i, cbp&32) < 0)

            return -1;

        cbp+=cbp;

    }



    if(s->pb_frame && h263_skip_b_part(s, cbpb) < 0)

        return -1;

    if(s->obmc && !s->mb_intra){

        if(s->pict_type == AV_PICTURE_TYPE_P && s->mb_x+1<s->mb_width && s->mb_num_left != 1)

            preview_obmc(s);

    }

end:



        /* per-MB end of slice check */

    {

        int v= show_bits(&s->gb, 16);



        if (get_bits_left(&s->gb) < 16) {

            v >>= 16 - get_bits_left(&s->gb);

        }



        if(v==0)

            return SLICE_END;

    }



    return SLICE_OK;

}

static int mpeg_decode_mb(MpegEncContext *s, int16_t block[12][64])

{

    int i, j, k, cbp, val, mb_type, motion_type;

    const int mb_block_count = 4 + (1 << s->chroma_format);

    int ret;



    ff_tlog(s->avctx, "decode_mb: x=%d y=%d\n", s->mb_x, s->mb_y);



    av_assert2(s->mb_skipped == 0);



    if (s->mb_skip_run-- != 0) {

        if (s->pict_type == AV_PICTURE_TYPE_P) {

            s->mb_skipped = 1;

            s->current_picture.mb_type[s->mb_x + s->mb_y * s->mb_stride] =

                MB_TYPE_SKIP | MB_TYPE_L0 | MB_TYPE_16x16;

        } else {

            int mb_type;



            if (s->mb_x)

                mb_type = s->current_picture.mb_type[s->mb_x + s->mb_y * s->mb_stride - 1];

            else

                // FIXME not sure if this is allowed in MPEG at all

                mb_type = s->current_picture.mb_type[s->mb_width + (s->mb_y - 1) * s->mb_stride - 1];

            if (IS_INTRA(mb_type)) {

                av_log(s->avctx, AV_LOG_ERROR, "skip with previntra\n");

                return AVERROR_INVALIDDATA;

            }

            s->current_picture.mb_type[s->mb_x + s->mb_y * s->mb_stride] =

                mb_type | MB_TYPE_SKIP;



            if ((s->mv[0][0][0] | s->mv[0][0][1] | s->mv[1][0][0] | s->mv[1][0][1]) == 0)

                s->mb_skipped = 1;

        }



        return 0;

    }



    switch (s->pict_type) {

    default:

    case AV_PICTURE_TYPE_I:

        if (get_bits1(&s->gb) == 0) {

            if (get_bits1(&s->gb) == 0) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "Invalid mb type in I-frame at %d %d\n",

                       s->mb_x, s->mb_y);

                return AVERROR_INVALIDDATA;

            }

            mb_type = MB_TYPE_QUANT | MB_TYPE_INTRA;

        } else {

            mb_type = MB_TYPE_INTRA;

        }

        break;

    case AV_PICTURE_TYPE_P:

        mb_type = get_vlc2(&s->gb, ff_mb_ptype_vlc.table, MB_PTYPE_VLC_BITS, 1);

        if (mb_type < 0) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Invalid mb type in P-frame at %d %d\n", s->mb_x, s->mb_y);

            return AVERROR_INVALIDDATA;

        }

        mb_type = ptype2mb_type[mb_type];

        break;

    case AV_PICTURE_TYPE_B:

        mb_type = get_vlc2(&s->gb, ff_mb_btype_vlc.table, MB_BTYPE_VLC_BITS, 1);

        if (mb_type < 0) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Invalid mb type in B-frame at %d %d\n", s->mb_x, s->mb_y);

            return AVERROR_INVALIDDATA;

        }

        mb_type = btype2mb_type[mb_type];

        break;

    }

    ff_tlog(s->avctx, "mb_type=%x\n", mb_type);

//    motion_type = 0; /* avoid warning */

    if (IS_INTRA(mb_type)) {

        s->bdsp.clear_blocks(s->block[0]);



        if (!s->chroma_y_shift)

            s->bdsp.clear_blocks(s->block[6]);



        /* compute DCT type */

        // FIXME: add an interlaced_dct coded var?

        if (s->picture_structure == PICT_FRAME &&

            !s->frame_pred_frame_dct)

            s->interlaced_dct = get_bits1(&s->gb);



        if (IS_QUANT(mb_type))

            s->qscale = get_qscale(s);



        if (s->concealment_motion_vectors) {

            /* just parse them */

            if (s->picture_structure != PICT_FRAME)

                skip_bits1(&s->gb);  /* field select */



            s->mv[0][0][0]      =

            s->last_mv[0][0][0] =

            s->last_mv[0][1][0] = mpeg_decode_motion(s, s->mpeg_f_code[0][0],

                                                     s->last_mv[0][0][0]);

            s->mv[0][0][1]      =

            s->last_mv[0][0][1] =

            s->last_mv[0][1][1] = mpeg_decode_motion(s, s->mpeg_f_code[0][1],

                                                     s->last_mv[0][0][1]);



            check_marker(s->avctx, &s->gb, "after concealment_motion_vectors");

        } else {

            /* reset mv prediction */

            memset(s->last_mv, 0, sizeof(s->last_mv));

        }

        s->mb_intra = 1;

        // if 1, we memcpy blocks in xvmcvideo

        if ((CONFIG_MPEG1_XVMC_HWACCEL || CONFIG_MPEG2_XVMC_HWACCEL) && s->pack_pblocks)

            ff_xvmc_pack_pblocks(s, -1); // inter are always full blocks



        if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO) {

            if (s->avctx->flags2 & AV_CODEC_FLAG2_FAST) {

                for (i = 0; i < 6; i++)

                    mpeg2_fast_decode_block_intra(s, *s->pblocks[i], i);

            } else {

                for (i = 0; i < mb_block_count; i++)

                    if ((ret = mpeg2_decode_block_intra(s, *s->pblocks[i], i)) < 0)

                        return ret;

            }

        } else {

            for (i = 0; i < 6; i++) {

                ret = ff_mpeg1_decode_block_intra(&s->gb,

                                                  s->intra_matrix,

                                                  s->intra_scantable.permutated,

                                                  s->last_dc, *s->pblocks[i],

                                                  i, s->qscale);

                if (ret < 0) {

                    av_log(s->avctx, AV_LOG_ERROR, "ac-tex damaged at %d %d\n",

                           s->mb_x, s->mb_y);

                    return ret;

                }



                s->block_last_index[i] = ret;

            }

        }

    } else {

        if (mb_type & MB_TYPE_ZERO_MV) {

            av_assert2(mb_type & MB_TYPE_CBP);



            s->mv_dir = MV_DIR_FORWARD;

            if (s->picture_structure == PICT_FRAME) {

                if (s->picture_structure == PICT_FRAME

                    && !s->frame_pred_frame_dct)

                    s->interlaced_dct = get_bits1(&s->gb);

                s->mv_type = MV_TYPE_16X16;

            } else {

                s->mv_type            = MV_TYPE_FIELD;

                mb_type              |= MB_TYPE_INTERLACED;

                s->field_select[0][0] = s->picture_structure - 1;

            }



            if (IS_QUANT(mb_type))

                s->qscale = get_qscale(s);



            s->last_mv[0][0][0] = 0;

            s->last_mv[0][0][1] = 0;

            s->last_mv[0][1][0] = 0;

            s->last_mv[0][1][1] = 0;

            s->mv[0][0][0]      = 0;

            s->mv[0][0][1]      = 0;

        } else {

            av_assert2(mb_type & MB_TYPE_L0L1);

            // FIXME decide if MBs in field pictures are MB_TYPE_INTERLACED

            /* get additional motion vector type */

            if (s->picture_structure == PICT_FRAME && s->frame_pred_frame_dct) {

                motion_type = MT_FRAME;

            } else {

                motion_type = get_bits(&s->gb, 2);

                if (s->picture_structure == PICT_FRAME && HAS_CBP(mb_type))

                    s->interlaced_dct = get_bits1(&s->gb);

            }



            if (IS_QUANT(mb_type))

                s->qscale = get_qscale(s);



            /* motion vectors */

            s->mv_dir = (mb_type >> 13) & 3;

            ff_tlog(s->avctx, "motion_type=%d\n", motion_type);

            switch (motion_type) {

            case MT_FRAME: /* or MT_16X8 */

                if (s->picture_structure == PICT_FRAME) {

                    mb_type   |= MB_TYPE_16x16;

                    s->mv_type = MV_TYPE_16X16;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            /* MT_FRAME */

                            s->mv[i][0][0]      =

                            s->last_mv[i][0][0] =

                            s->last_mv[i][1][0] =

                                mpeg_decode_motion(s, s->mpeg_f_code[i][0],

                                                   s->last_mv[i][0][0]);

                            s->mv[i][0][1]      =

                            s->last_mv[i][0][1] =

                            s->last_mv[i][1][1] =

                                mpeg_decode_motion(s, s->mpeg_f_code[i][1],

                                                   s->last_mv[i][0][1]);

                            /* full_pel: only for MPEG-1 */

                            if (s->full_pel[i]) {

                                s->mv[i][0][0] *= 2;

                                s->mv[i][0][1] *= 2;

                            }

                        }

                    }

                } else {

                    mb_type   |= MB_TYPE_16x8 | MB_TYPE_INTERLACED;

                    s->mv_type = MV_TYPE_16X8;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            /* MT_16X8 */

                            for (j = 0; j < 2; j++) {

                                s->field_select[i][j] = get_bits1(&s->gb);

                                for (k = 0; k < 2; k++) {

                                    val = mpeg_decode_motion(s, s->mpeg_f_code[i][k],

                                                             s->last_mv[i][j][k]);

                                    s->last_mv[i][j][k] = val;

                                    s->mv[i][j][k]      = val;

                                }

                            }

                        }

                    }

                }

                break;

            case MT_FIELD:

                s->mv_type = MV_TYPE_FIELD;

                if (s->picture_structure == PICT_FRAME) {

                    mb_type |= MB_TYPE_16x8 | MB_TYPE_INTERLACED;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            for (j = 0; j < 2; j++) {

                                s->field_select[i][j] = get_bits1(&s->gb);

                                val = mpeg_decode_motion(s, s->mpeg_f_code[i][0],

                                                         s->last_mv[i][j][0]);

                                s->last_mv[i][j][0] = val;

                                s->mv[i][j][0]      = val;

                                ff_tlog(s->avctx, "fmx=%d\n", val);

                                val = mpeg_decode_motion(s, s->mpeg_f_code[i][1],

                                                         s->last_mv[i][j][1] >> 1);

                                s->last_mv[i][j][1] = 2 * val;

                                s->mv[i][j][1]      = val;

                                ff_tlog(s->avctx, "fmy=%d\n", val);

                            }

                        }

                    }

                } else {

                    av_assert0(!s->progressive_sequence);

                    mb_type |= MB_TYPE_16x16 | MB_TYPE_INTERLACED;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            s->field_select[i][0] = get_bits1(&s->gb);

                            for (k = 0; k < 2; k++) {

                                val = mpeg_decode_motion(s, s->mpeg_f_code[i][k],

                                                         s->last_mv[i][0][k]);

                                s->last_mv[i][0][k] = val;

                                s->last_mv[i][1][k] = val;

                                s->mv[i][0][k]      = val;

                            }

                        }

                    }

                }

                break;

            case MT_DMV:

                if (s->progressive_sequence){

                    av_log(s->avctx, AV_LOG_ERROR, "MT_DMV in progressive_sequence\n");

                    return AVERROR_INVALIDDATA;

                }

                s->mv_type = MV_TYPE_DMV;

                for (i = 0; i < 2; i++) {

                    if (USES_LIST(mb_type, i)) {

                        int dmx, dmy, mx, my, m;

                        const int my_shift = s->picture_structure == PICT_FRAME;



                        mx = mpeg_decode_motion(s, s->mpeg_f_code[i][0],

                                                s->last_mv[i][0][0]);

                        s->last_mv[i][0][0] = mx;

                        s->last_mv[i][1][0] = mx;

                        dmx = get_dmv(s);

                        my  = mpeg_decode_motion(s, s->mpeg_f_code[i][1],

                                                 s->last_mv[i][0][1] >> my_shift);

                        dmy = get_dmv(s);





                        s->last_mv[i][0][1] = my * (1 << my_shift);

                        s->last_mv[i][1][1] = my * (1 << my_shift);



                        s->mv[i][0][0] = mx;

                        s->mv[i][0][1] = my;

                        s->mv[i][1][0] = mx; // not used

                        s->mv[i][1][1] = my; // not used



                        if (s->picture_structure == PICT_FRAME) {

                            mb_type |= MB_TYPE_16x16 | MB_TYPE_INTERLACED;



                            // m = 1 + 2 * s->top_field_first;

                            m = s->top_field_first ? 1 : 3;



                            /* top -> top pred */

                            s->mv[i][2][0] = ((mx * m + (mx > 0)) >> 1) + dmx;

                            s->mv[i][2][1] = ((my * m + (my > 0)) >> 1) + dmy - 1;

                            m = 4 - m;

                            s->mv[i][3][0] = ((mx * m + (mx > 0)) >> 1) + dmx;

                            s->mv[i][3][1] = ((my * m + (my > 0)) >> 1) + dmy + 1;

                        } else {

                            mb_type |= MB_TYPE_16x16;



                            s->mv[i][2][0] = ((mx + (mx > 0)) >> 1) + dmx;

                            s->mv[i][2][1] = ((my + (my > 0)) >> 1) + dmy;

                            if (s->picture_structure == PICT_TOP_FIELD)

                                s->mv[i][2][1]--;

                            else

                                s->mv[i][2][1]++;

                        }

                    }

                }

                break;

            default:

                av_log(s->avctx, AV_LOG_ERROR,

                       "00 motion_type at %d %d\n", s->mb_x, s->mb_y);

                return AVERROR_INVALIDDATA;

            }

        }



        s->mb_intra = 0;

        if (HAS_CBP(mb_type)) {

            s->bdsp.clear_blocks(s->block[0]);



            cbp = get_vlc2(&s->gb, ff_mb_pat_vlc.table, MB_PAT_VLC_BITS, 1);

            if (mb_block_count > 6) {

                cbp <<= mb_block_count - 6;

                cbp  |= get_bits(&s->gb, mb_block_count - 6);

                s->bdsp.clear_blocks(s->block[6]);

            }

            if (cbp <= 0) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "invalid cbp %d at %d %d\n", cbp, s->mb_x, s->mb_y);

                return AVERROR_INVALIDDATA;

            }



            // if 1, we memcpy blocks in xvmcvideo

            if ((CONFIG_MPEG1_XVMC_HWACCEL || CONFIG_MPEG2_XVMC_HWACCEL) && s->pack_pblocks)

                ff_xvmc_pack_pblocks(s, cbp);



            if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO) {

                if (s->avctx->flags2 & AV_CODEC_FLAG2_FAST) {

                    for (i = 0; i < 6; i++) {

                        if (cbp & 32)

                            mpeg2_fast_decode_block_non_intra(s, *s->pblocks[i], i);

                        else

                            s->block_last_index[i] = -1;

                        cbp += cbp;

                    }

                } else {

                    cbp <<= 12 - mb_block_count;



                    for (i = 0; i < mb_block_count; i++) {

                        if (cbp & (1 << 11)) {

                            if ((ret = mpeg2_decode_block_non_intra(s, *s->pblocks[i], i)) < 0)

                                return ret;

                        } else {

                            s->block_last_index[i] = -1;

                        }

                        cbp += cbp;

                    }

                }

            } else {

                if (s->avctx->flags2 & AV_CODEC_FLAG2_FAST) {

                    for (i = 0; i < 6; i++) {

                        if (cbp & 32)

                            mpeg1_fast_decode_block_inter(s, *s->pblocks[i], i);

                        else

                            s->block_last_index[i] = -1;

                        cbp += cbp;

                    }

                } else {

                    for (i = 0; i < 6; i++) {

                        if (cbp & 32) {

                            if ((ret = mpeg1_decode_block_inter(s, *s->pblocks[i], i)) < 0)

                                return ret;

                        } else {

                            s->block_last_index[i] = -1;

                        }

                        cbp += cbp;

                    }

                }

            }

        } else {

            for (i = 0; i < 12; i++)

                s->block_last_index[i] = -1;

        }

    }



    s->current_picture.mb_type[s->mb_x + s->mb_y * s->mb_stride] = mb_type;



    return 0;

}

int ff_h263_decode_mb(MpegEncContext *s,

                      DCTELEM block[6][64])

{

    int cbpc, cbpy, i, cbp, pred_x, pred_y, mx, my, dquant;

    INT16 *mot_val;

    static INT8 quant_tab[4] = { -1, -2, 1, 2 };



    s->error_status_table[s->mb_x + s->mb_y*s->mb_width]= 0;



    if(s->mb_x==0) PRINT_MB_TYPE("\n");



    if (s->pict_type == P_TYPE || s->pict_type==S_TYPE) {

        if (get_bits1(&s->gb)) {

            /* skip mb */

            s->mb_intra = 0;

            for(i=0;i<6;i++)

                s->block_last_index[i] = -1;

            s->mv_dir = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

            if(s->pict_type==S_TYPE && s->vol_sprite_usage==GMC_SPRITE){

                PRINT_MB_TYPE("G");

                s->mcsel=1;

                s->mv[0][0][0]= get_amv(s, 0);

                s->mv[0][0][1]= get_amv(s, 1);



                s->mb_skiped = 0;

            }else{

                PRINT_MB_TYPE("S");

                s->mcsel=0;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->mb_skiped = 1;

            }

            goto end;

        }

        cbpc = get_vlc2(&s->gb, inter_MCBPC_vlc.table, INTER_MCBPC_VLC_BITS, 2);

        //fprintf(stderr, "\tCBPC: %d", cbpc);

        if (cbpc < 0)

            return -1;

        if (cbpc > 20)

            cbpc+=3;

        else if (cbpc == 20)

            fprintf(stderr, "Stuffing !");



        dquant = cbpc & 8;

        s->mb_intra = ((cbpc & 4) != 0);

        if (s->mb_intra) goto intra;



        if(s->pict_type==S_TYPE && s->vol_sprite_usage==GMC_SPRITE && (cbpc & 16) == 0)

            s->mcsel= get_bits1(&s->gb);

        else s->mcsel= 0;

        cbpy = get_vlc2(&s->gb, cbpy_vlc.table, CBPY_VLC_BITS, 1);

        cbp = (cbpc & 3) | ((cbpy ^ 0xf) << 2);

        if (dquant) {

            change_qscale(s, quant_tab[get_bits(&s->gb, 2)]);

        }

        if((!s->progressive_sequence) && (cbp || (s->workaround_bugs&FF_BUG_XVID_ILACE)))

            s->interlaced_dct= get_bits1(&s->gb);



        s->mv_dir = MV_DIR_FORWARD;

        if ((cbpc & 16) == 0) {

            if(s->mcsel){

                PRINT_MB_TYPE("G");

                /* 16x16 global motion prediction */

                s->mv_type = MV_TYPE_16X16;

                mx= get_amv(s, 0);

                my= get_amv(s, 1);

                s->mv[0][0][0] = mx;

                s->mv[0][0][1] = my;

            }else if((!s->progressive_sequence) && get_bits1(&s->gb)){

                PRINT_MB_TYPE("f");

                /* 16x8 field motion prediction */

                s->mv_type= MV_TYPE_FIELD;



                s->field_select[0][0]= get_bits1(&s->gb);

                s->field_select[0][1]= get_bits1(&s->gb);



                h263_pred_motion(s, 0, &pred_x, &pred_y);



                for(i=0; i<2; i++){

                    mx = h263_decode_motion(s, pred_x, s->f_code);

                    if (mx >= 0xffff)

                        return -1;



                    my = h263_decode_motion(s, pred_y/2, s->f_code);

                    if (my >= 0xffff)

                        return -1;



                    s->mv[0][i][0] = mx;

                    s->mv[0][i][1] = my;

                }

            }else{

                PRINT_MB_TYPE("P");

                /* 16x16 motion prediction */

                s->mv_type = MV_TYPE_16X16;

                h263_pred_motion(s, 0, &pred_x, &pred_y);

                if (s->umvplus_dec)

                   mx = h263p_decode_umotion(s, pred_x);

                else

                   mx = h263_decode_motion(s, pred_x, s->f_code);



                if (mx >= 0xffff)

                    return -1;



                if (s->umvplus_dec)

                   my = h263p_decode_umotion(s, pred_y);

                else

                   my = h263_decode_motion(s, pred_y, s->f_code);



                if (my >= 0xffff)

                    return -1;

                s->mv[0][0][0] = mx;

                s->mv[0][0][1] = my;



                if (s->umvplus_dec && (mx - pred_x) == 1 && (my - pred_y) == 1)

                   skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */                   

            }

        } else {

            PRINT_MB_TYPE("4");

            s->mv_type = MV_TYPE_8X8;

            for(i=0;i<4;i++) {

                mot_val = h263_pred_motion(s, i, &pred_x, &pred_y);

                if (s->umvplus_dec)

                  mx = h263p_decode_umotion(s, pred_x);

                else

                  mx = h263_decode_motion(s, pred_x, s->f_code);

                if (mx >= 0xffff)

                    return -1;



                if (s->umvplus_dec)

                  my = h263p_decode_umotion(s, pred_y);

                else    

                  my = h263_decode_motion(s, pred_y, s->f_code);

                if (my >= 0xffff)

                    return -1;

                s->mv[0][i][0] = mx;

                s->mv[0][i][1] = my;

                if (s->umvplus_dec && (mx - pred_x) == 1 && (my - pred_y) == 1)

                  skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */

                mot_val[0] = mx;

                mot_val[1] = my;

            }

        }

    } else if(s->pict_type==B_TYPE) {

        int modb1; // first bit of modb

        int modb2; // second bit of modb

        int mb_type;

        int xy;



        s->mb_intra = 0; //B-frames never contain intra blocks

        s->mcsel=0;      //     ...               true gmc blocks



        if(s->mb_x==0){

            for(i=0; i<2; i++){

                s->last_mv[i][0][0]= 

                s->last_mv[i][0][1]= 

                s->last_mv[i][1][0]= 

                s->last_mv[i][1][1]= 0;

            }

        }



        /* if we skipped it in the future P Frame than skip it now too */

        s->mb_skiped= s->next_picture.mbskip_table[s->mb_y * s->mb_width + s->mb_x]; // Note, skiptab=0 if last was GMC



        if(s->mb_skiped){

                /* skip mb */

            for(i=0;i<6;i++)

                s->block_last_index[i] = -1;



            s->mv_dir = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

            s->mv[0][0][0] = 0;

            s->mv[0][0][1] = 0;

            s->mv[1][0][0] = 0;

            s->mv[1][0][1] = 0;

            PRINT_MB_TYPE("s");

            goto end;

        }



        modb1= get_bits1(&s->gb); 

        if(modb1){

            mb_type=4; //like MB_TYPE_B_DIRECT but no vectors coded

            cbp=0;

        }else{

            int field_mv;



            modb2= get_bits1(&s->gb);

            mb_type= get_vlc2(&s->gb, mb_type_b_vlc.table, MB_TYPE_B_VLC_BITS, 1);

            if(modb2) cbp= 0;

            else      cbp= get_bits(&s->gb, 6);



            if (mb_type!=MB_TYPE_B_DIRECT && cbp) {

                if(get_bits1(&s->gb)){

                    change_qscale(s, get_bits1(&s->gb)*4 - 2);

                }

            }

            field_mv=0;



            if(!s->progressive_sequence){

                if(cbp)

                    s->interlaced_dct= get_bits1(&s->gb);



                if(mb_type!=MB_TYPE_B_DIRECT && get_bits1(&s->gb)){

                    field_mv=1;



                    if(mb_type!=MB_TYPE_B_BACKW){

                        s->field_select[0][0]= get_bits1(&s->gb);

                        s->field_select[0][1]= get_bits1(&s->gb);

                    }

                    if(mb_type!=MB_TYPE_B_FORW){

                        s->field_select[1][0]= get_bits1(&s->gb);

                        s->field_select[1][1]= get_bits1(&s->gb);

                    }

                }

            }



            s->mv_dir = 0;

            if(mb_type!=MB_TYPE_B_DIRECT && !field_mv){

                s->mv_type= MV_TYPE_16X16;

                if(mb_type!=MB_TYPE_B_BACKW){

                    s->mv_dir = MV_DIR_FORWARD;



                    mx = h263_decode_motion(s, s->last_mv[0][0][0], s->f_code);

                    my = h263_decode_motion(s, s->last_mv[0][0][1], s->f_code);

                    s->last_mv[0][1][0]= s->last_mv[0][0][0]= s->mv[0][0][0] = mx;

                    s->last_mv[0][1][1]= s->last_mv[0][0][1]= s->mv[0][0][1] = my;

                }



                if(mb_type!=MB_TYPE_B_FORW){

                    s->mv_dir |= MV_DIR_BACKWARD;



                    mx = h263_decode_motion(s, s->last_mv[1][0][0], s->b_code);

                    my = h263_decode_motion(s, s->last_mv[1][0][1], s->b_code);

                    s->last_mv[1][1][0]= s->last_mv[1][0][0]= s->mv[1][0][0] = mx;

                    s->last_mv[1][1][1]= s->last_mv[1][0][1]= s->mv[1][0][1] = my;

                }

                if(mb_type!=MB_TYPE_B_DIRECT)

                    PRINT_MB_TYPE(mb_type==MB_TYPE_B_FORW ? "F" : (mb_type==MB_TYPE_B_BACKW ? "B" : "T"));

            }else if(mb_type!=MB_TYPE_B_DIRECT){

                s->mv_type= MV_TYPE_FIELD;



                if(mb_type!=MB_TYPE_B_BACKW){

                    s->mv_dir = MV_DIR_FORWARD;



                    for(i=0; i<2; i++){

                        mx = h263_decode_motion(s, s->last_mv[0][i][0]  , s->f_code);

                        my = h263_decode_motion(s, s->last_mv[0][i][1]/2, s->f_code);

                        s->last_mv[0][i][0]=  s->mv[0][i][0] = mx;

                        s->last_mv[0][i][1]= (s->mv[0][i][1] = my)*2;

                    }

                }



                if(mb_type!=MB_TYPE_B_FORW){

                    s->mv_dir |= MV_DIR_BACKWARD;



                    for(i=0; i<2; i++){

                        mx = h263_decode_motion(s, s->last_mv[1][i][0]  , s->b_code);

                        my = h263_decode_motion(s, s->last_mv[1][i][1]/2, s->b_code);

                        s->last_mv[1][i][0]=  s->mv[1][i][0] = mx;

                        s->last_mv[1][i][1]= (s->mv[1][i][1] = my)*2;

                    }

                }

                if(mb_type!=MB_TYPE_B_DIRECT)

                    PRINT_MB_TYPE(mb_type==MB_TYPE_B_FORW ? "f" : (mb_type==MB_TYPE_B_BACKW ? "b" : "t"));

            }

        }



        if(mb_type==4 || mb_type==MB_TYPE_B_DIRECT){

            if(mb_type==4)

                mx=my=0;

            else{

                mx = h263_decode_motion(s, 0, 1);

                my = h263_decode_motion(s, 0, 1);

            }



            s->mv_dir = MV_DIR_FORWARD | MV_DIR_BACKWARD | MV_DIRECT;

            ff_mpeg4_set_direct_mv(s, mx, my);

        }



        if(mb_type<0 || mb_type>4){

            printf("illegal MB_type\n");

            return -1;

        }

    } else { /* I-Frame */

        cbpc = get_vlc2(&s->gb, intra_MCBPC_vlc.table, INTRA_MCBPC_VLC_BITS, 1);

        if (cbpc < 0)

            return -1;

        dquant = cbpc & 4;

        s->mb_intra = 1;

intra:

        s->ac_pred = 0;

        if (s->h263_pred || s->h263_aic) {

            s->ac_pred = get_bits1(&s->gb);

            if (s->ac_pred && s->h263_aic)

                s->h263_aic_dir = get_bits1(&s->gb);

        }

        PRINT_MB_TYPE(s->ac_pred ? "A" : "I");



        cbpy = get_vlc2(&s->gb, cbpy_vlc.table, CBPY_VLC_BITS, 1);

        if(cbpy<0) return -1;

        cbp = (cbpc & 3) | (cbpy << 2);

        if (dquant) {

            change_qscale(s, quant_tab[get_bits(&s->gb, 2)]);

        }



        if(!s->progressive_sequence)

            s->interlaced_dct= get_bits1(&s->gb);



        /* decode each block */

        if (s->h263_pred) {

            for (i = 0; i < 6; i++) {

                if (mpeg4_decode_block(s, block[i], i, cbp&32, 1) < 0)

                    return -1;

                cbp+=cbp;

            }

        } else {

            for (i = 0; i < 6; i++) {

                if (h263_decode_block(s, block[i], i, cbp&32) < 0)

                    return -1;

                cbp+=cbp;

            }

        }

        goto end;

    }



    /* decode each block */

    if (s->h263_pred) {

        for (i = 0; i < 6; i++) {

            if (mpeg4_decode_block(s, block[i], i, cbp&32, 0) < 0)

                return -1;

            cbp+=cbp;

        }

    } else {

        for (i = 0; i < 6; i++) {

            if (h263_decode_block(s, block[i], i, cbp&32) < 0)

                return -1;

            cbp+=cbp;

        }

    }

end:



        /* per-MB end of slice check */

    if(s->codec_id==CODEC_ID_MPEG4){

        if(mpeg4_is_resync(s)){

            if(s->pict_type==B_TYPE && s->next_picture.mbskip_table[s->mb_y * s->mb_width + s->mb_x+1])

                return SLICE_OK;

            return SLICE_END;

        }

    }else{

        int v= show_bits(&s->gb, 16);



        if(get_bits_count(&s->gb) + 16 > s->gb.size*8){

            v>>= get_bits_count(&s->gb) + 16 - s->gb.size*8;

        }



        if(v==0)

            return SLICE_END;

    }



    return SLICE_OK;     

}

static int mpeg_decode_mb(MpegEncContext *s, DCTELEM block[12][64])

{

    int i, j, k, cbp, val, mb_type, motion_type;

    const int mb_block_count = 4 + (1 << s->chroma_format);



    av_dlog(s->avctx, "decode_mb: x=%d y=%d\n", s->mb_x, s->mb_y);



    assert(s->mb_skipped == 0);



    if (s->mb_skip_run-- != 0) {

        if (s->pict_type == AV_PICTURE_TYPE_P) {

            s->mb_skipped = 1;

            s->current_picture.f.mb_type[s->mb_x + s->mb_y * s->mb_stride] = MB_TYPE_SKIP | MB_TYPE_L0 | MB_TYPE_16x16;

        } else {

            int mb_type;



            if (s->mb_x)

                mb_type = s->current_picture.f.mb_type[s->mb_x + s->mb_y * s->mb_stride - 1];

            else

                mb_type = s->current_picture.f.mb_type[s->mb_width + (s->mb_y - 1) * s->mb_stride - 1]; // FIXME not sure if this is allowed in MPEG at all

            if (IS_INTRA(mb_type))

                return -1;

            s->current_picture.f.mb_type[s->mb_x + s->mb_y*s->mb_stride] =

                mb_type | MB_TYPE_SKIP;

//            assert(s->current_picture.f.mb_type[s->mb_x + s->mb_y * s->mb_stride - 1] & (MB_TYPE_16x16 | MB_TYPE_16x8));



            if ((s->mv[0][0][0] | s->mv[0][0][1] | s->mv[1][0][0] | s->mv[1][0][1]) == 0)

                s->mb_skipped = 1;

        }



        return 0;

    }



    switch (s->pict_type) {

    default:

    case AV_PICTURE_TYPE_I:

        if (get_bits1(&s->gb) == 0) {

            if (get_bits1(&s->gb) == 0) {

                av_log(s->avctx, AV_LOG_ERROR, "invalid mb type in I Frame at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }

            mb_type = MB_TYPE_QUANT | MB_TYPE_INTRA;

        } else {

            mb_type = MB_TYPE_INTRA;

        }

        break;

    case AV_PICTURE_TYPE_P:

        mb_type = get_vlc2(&s->gb, mb_ptype_vlc.table, MB_PTYPE_VLC_BITS, 1);

        if (mb_type < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "invalid mb type in P Frame at %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        mb_type = ptype2mb_type[mb_type];

        break;

    case AV_PICTURE_TYPE_B:

        mb_type = get_vlc2(&s->gb, mb_btype_vlc.table, MB_BTYPE_VLC_BITS, 1);

        if (mb_type < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "invalid mb type in B Frame at %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        mb_type = btype2mb_type[mb_type];

        break;

    }

    av_dlog(s->avctx, "mb_type=%x\n", mb_type);

//    motion_type = 0; /* avoid warning */

    if (IS_INTRA(mb_type)) {

        s->dsp.clear_blocks(s->block[0]);



        if (!s->chroma_y_shift) {

            s->dsp.clear_blocks(s->block[6]);

        }



        /* compute DCT type */

        if (s->picture_structure == PICT_FRAME && // FIXME add an interlaced_dct coded var?

            !s->frame_pred_frame_dct) {

            s->interlaced_dct = get_bits1(&s->gb);

        }



        if (IS_QUANT(mb_type))

            s->qscale = get_qscale(s);



        if (s->concealment_motion_vectors) {

            /* just parse them */

            if (s->picture_structure != PICT_FRAME)

                skip_bits1(&s->gb); /* field select */



            s->mv[0][0][0]= s->last_mv[0][0][0]= s->last_mv[0][1][0] =

                mpeg_decode_motion(s, s->mpeg_f_code[0][0], s->last_mv[0][0][0]);

            s->mv[0][0][1]= s->last_mv[0][0][1]= s->last_mv[0][1][1] =

                mpeg_decode_motion(s, s->mpeg_f_code[0][1], s->last_mv[0][0][1]);



            skip_bits1(&s->gb); /* marker */

        } else

            memset(s->last_mv, 0, sizeof(s->last_mv)); /* reset mv prediction */

        s->mb_intra = 1;

        // if 1, we memcpy blocks in xvmcvideo

        if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration > 1) {

            ff_xvmc_pack_pblocks(s, -1); // inter are always full blocks

            if (s->swap_uv) {

                exchange_uv(s);

            }

        }



        if (s->codec_id == CODEC_ID_MPEG2VIDEO) {

            if (s->flags2 & CODEC_FLAG2_FAST) {

                for (i = 0; i < 6; i++) {

                    mpeg2_fast_decode_block_intra(s, *s->pblocks[i], i);

                }

            } else {

                for (i = 0; i < mb_block_count; i++) {

                    if (mpeg2_decode_block_intra(s, *s->pblocks[i], i) < 0)

                        return -1;

                }

            }

        } else {

            for (i = 0; i < 6; i++) {

                if (mpeg1_decode_block_intra(s, *s->pblocks[i], i) < 0)

                    return -1;

            }

        }

    } else {

        if (mb_type & MB_TYPE_ZERO_MV) {

            assert(mb_type & MB_TYPE_CBP);



            s->mv_dir = MV_DIR_FORWARD;

            if (s->picture_structure == PICT_FRAME) {

                if (!s->frame_pred_frame_dct)

                    s->interlaced_dct = get_bits1(&s->gb);

                s->mv_type = MV_TYPE_16X16;

            } else {

                s->mv_type = MV_TYPE_FIELD;

                mb_type |= MB_TYPE_INTERLACED;

                s->field_select[0][0] = s->picture_structure - 1;

            }



            if (IS_QUANT(mb_type))

                s->qscale = get_qscale(s);



            s->last_mv[0][0][0] = 0;

            s->last_mv[0][0][1] = 0;

            s->last_mv[0][1][0] = 0;

            s->last_mv[0][1][1] = 0;

            s->mv[0][0][0] = 0;

            s->mv[0][0][1] = 0;

        } else {

            assert(mb_type & MB_TYPE_L0L1);

            // FIXME decide if MBs in field pictures are MB_TYPE_INTERLACED

            /* get additional motion vector type */

            if (s->frame_pred_frame_dct)

                motion_type = MT_FRAME;

            else {

                motion_type = get_bits(&s->gb, 2);

                if (s->picture_structure == PICT_FRAME && HAS_CBP(mb_type))

                    s->interlaced_dct = get_bits1(&s->gb);

            }



            if (IS_QUANT(mb_type))

                s->qscale = get_qscale(s);



            /* motion vectors */

            s->mv_dir = (mb_type >> 13) & 3;

            av_dlog(s->avctx, "motion_type=%d\n", motion_type);

            switch (motion_type) {

            case MT_FRAME: /* or MT_16X8 */

                if (s->picture_structure == PICT_FRAME) {

                    mb_type |= MB_TYPE_16x16;

                    s->mv_type = MV_TYPE_16X16;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            /* MT_FRAME */

                            s->mv[i][0][0]= s->last_mv[i][0][0]= s->last_mv[i][1][0] =

                                mpeg_decode_motion(s, s->mpeg_f_code[i][0], s->last_mv[i][0][0]);

                            s->mv[i][0][1]= s->last_mv[i][0][1]= s->last_mv[i][1][1] =

                                mpeg_decode_motion(s, s->mpeg_f_code[i][1], s->last_mv[i][0][1]);

                            /* full_pel: only for MPEG-1 */

                            if (s->full_pel[i]) {

                                s->mv[i][0][0] <<= 1;

                                s->mv[i][0][1] <<= 1;

                            }

                        }

                    }

                } else {

                    mb_type |= MB_TYPE_16x8 | MB_TYPE_INTERLACED;

                    s->mv_type = MV_TYPE_16X8;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            /* MT_16X8 */

                            for (j = 0; j < 2; j++) {

                                s->field_select[i][j] = get_bits1(&s->gb);

                                for (k = 0; k < 2; k++) {

                                    val = mpeg_decode_motion(s, s->mpeg_f_code[i][k],

                                                             s->last_mv[i][j][k]);

                                    s->last_mv[i][j][k] = val;

                                    s->mv[i][j][k]      = val;

                                }

                            }

                        }

                    }

                }

                break;

            case MT_FIELD:

                if(s->progressive_sequence){

                    av_log(s->avctx, AV_LOG_ERROR, "MT_FIELD in progressive_sequence\n");

                    return -1;

                }

                s->mv_type = MV_TYPE_FIELD;

                if (s->picture_structure == PICT_FRAME) {

                    mb_type |= MB_TYPE_16x8 | MB_TYPE_INTERLACED;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            for (j = 0; j < 2; j++) {

                                s->field_select[i][j] = get_bits1(&s->gb);

                                val = mpeg_decode_motion(s, s->mpeg_f_code[i][0],

                                                         s->last_mv[i][j][0]);

                                s->last_mv[i][j][0] = val;

                                s->mv[i][j][0]      = val;

                                av_dlog(s->avctx, "fmx=%d\n", val);

                                val = mpeg_decode_motion(s, s->mpeg_f_code[i][1],

                                                         s->last_mv[i][j][1] >> 1);

                                s->last_mv[i][j][1] = val << 1;

                                s->mv[i][j][1]      = val;

                                av_dlog(s->avctx, "fmy=%d\n", val);

                            }

                        }

                    }

                } else {

                    av_assert0(!s->progressive_sequence);

                    mb_type |= MB_TYPE_16x16 | MB_TYPE_INTERLACED;

                    for (i = 0; i < 2; i++) {

                        if (USES_LIST(mb_type, i)) {

                            s->field_select[i][0] = get_bits1(&s->gb);

                            for (k = 0; k < 2; k++) {

                                val = mpeg_decode_motion(s, s->mpeg_f_code[i][k],

                                                         s->last_mv[i][0][k]);

                                s->last_mv[i][0][k] = val;

                                s->last_mv[i][1][k] = val;

                                s->mv[i][0][k]      = val;

                            }

                        }

                    }

                }

                break;

            case MT_DMV:

                if(s->progressive_sequence){

                    av_log(s->avctx, AV_LOG_ERROR, "MT_DMV in progressive_sequence\n");

                    return -1;

                }

                s->mv_type = MV_TYPE_DMV;

                for (i = 0; i < 2; i++) {

                    if (USES_LIST(mb_type, i)) {

                        int dmx, dmy, mx, my, m;

                        const int my_shift = s->picture_structure == PICT_FRAME;



                        mx = mpeg_decode_motion(s, s->mpeg_f_code[i][0],

                                                s->last_mv[i][0][0]);

                        s->last_mv[i][0][0] = mx;

                        s->last_mv[i][1][0] = mx;

                        dmx = get_dmv(s);

                        my  = mpeg_decode_motion(s, s->mpeg_f_code[i][1],

                                                 s->last_mv[i][0][1] >> my_shift);

                        dmy = get_dmv(s);





                        s->last_mv[i][0][1] = my << my_shift;

                        s->last_mv[i][1][1] = my << my_shift;



                        s->mv[i][0][0] = mx;

                        s->mv[i][0][1] = my;

                        s->mv[i][1][0] = mx; // not used

                        s->mv[i][1][1] = my; // not used



                        if (s->picture_structure == PICT_FRAME) {

                            mb_type |= MB_TYPE_16x16 | MB_TYPE_INTERLACED;



                            // m = 1 + 2 * s->top_field_first;

                            m = s->top_field_first ? 1 : 3;



                            /* top -> top pred */

                            s->mv[i][2][0] = ((mx * m + (mx > 0)) >> 1) + dmx;

                            s->mv[i][2][1] = ((my * m + (my > 0)) >> 1) + dmy - 1;

                            m = 4 - m;

                            s->mv[i][3][0] = ((mx * m + (mx > 0)) >> 1) + dmx;

                            s->mv[i][3][1] = ((my * m + (my > 0)) >> 1) + dmy + 1;

                        } else {

                            mb_type |= MB_TYPE_16x16;



                            s->mv[i][2][0] = ((mx + (mx > 0)) >> 1) + dmx;

                            s->mv[i][2][1] = ((my + (my > 0)) >> 1) + dmy;

                            if (s->picture_structure == PICT_TOP_FIELD)

                                s->mv[i][2][1]--;

                            else

                                s->mv[i][2][1]++;

                        }

                    }

                }

                break;

            default:

                av_log(s->avctx, AV_LOG_ERROR, "00 motion_type at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }

        }



        s->mb_intra = 0;

        if (HAS_CBP(mb_type)) {

            s->dsp.clear_blocks(s->block[0]);



            cbp = get_vlc2(&s->gb, mb_pat_vlc.table, MB_PAT_VLC_BITS, 1);

            if (mb_block_count > 6) {

                 cbp <<= mb_block_count - 6;

                 cbp  |= get_bits(&s->gb, mb_block_count - 6);

                 s->dsp.clear_blocks(s->block[6]);

            }

            if (cbp <= 0) {

                av_log(s->avctx, AV_LOG_ERROR, "invalid cbp at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            //if 1, we memcpy blocks in xvmcvideo

            if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration > 1) {

                ff_xvmc_pack_pblocks(s, cbp);

                if (s->swap_uv) {

                    exchange_uv(s);

                }

            }



            if (s->codec_id == CODEC_ID_MPEG2VIDEO) {

                if (s->flags2 & CODEC_FLAG2_FAST) {

                    for (i = 0; i < 6; i++) {

                        if (cbp & 32) {

                            mpeg2_fast_decode_block_non_intra(s, *s->pblocks[i], i);

                        } else {

                            s->block_last_index[i] = -1;

                        }

                        cbp += cbp;

                    }

                } else {

                    cbp <<= 12-mb_block_count;



                    for (i = 0; i < mb_block_count; i++) {

                        if (cbp & (1 << 11)) {

                            if (mpeg2_decode_block_non_intra(s, *s->pblocks[i], i) < 0)

                                return -1;

                        } else {

                            s->block_last_index[i] = -1;

                        }

                        cbp += cbp;

                    }

                }

            } else {

                if (s->flags2 & CODEC_FLAG2_FAST) {

                    for (i = 0; i < 6; i++) {

                        if (cbp & 32) {

                            mpeg1_fast_decode_block_inter(s, *s->pblocks[i], i);

                        } else {

                            s->block_last_index[i] = -1;

                        }

                        cbp += cbp;

                    }

                } else {

                    for (i = 0; i < 6; i++) {

                        if (cbp & 32) {

                            if (mpeg1_decode_block_inter(s, *s->pblocks[i], i) < 0)

                                return -1;

                        } else {

                            s->block_last_index[i] = -1;

                        }

                        cbp += cbp;

                    }

                }

            }

        } else {

            for (i = 0; i < 12; i++)

                s->block_last_index[i] = -1;

        }

    }



    s->current_picture.f.mb_type[s->mb_x + s->mb_y * s->mb_stride] = mb_type;



    return 0;

}

int register_savevm_live(DeviceState *dev,

                         const char *idstr,

                         int instance_id,

                         int version_id,

                         SaveVMHandlers *ops,

                         void *opaque)

{

    SaveStateEntry *se;



    se = g_malloc0(sizeof(SaveStateEntry));

    se->version_id = version_id;

    se->section_id = savevm_state.global_section_id++;

    se->ops = ops;

    se->opaque = opaque;

    se->vmsd = NULL;

    /* if this is a live_savem then set is_ram */

    if (ops->save_live_setup != NULL) {

        se->is_ram = 1;

    }



    if (dev) {

        char *id = qdev_get_dev_path(dev);

        if (id) {

            pstrcpy(se->idstr, sizeof(se->idstr), id);

            pstrcat(se->idstr, sizeof(se->idstr), "/");

            g_free(id);



            se->compat = g_malloc0(sizeof(CompatEntry));

            pstrcpy(se->compat->idstr, sizeof(se->compat->idstr), idstr);

            se->compat->instance_id = instance_id == -1 ?

                         calculate_compat_instance_id(idstr) : instance_id;

            instance_id = -1;

        }

    }

    pstrcat(se->idstr, sizeof(se->idstr), idstr);



    if (instance_id == -1) {

        se->instance_id = calculate_new_instance_id(se->idstr);

    } else {

        se->instance_id = instance_id;

    }

    assert(!se->compat || se->instance_id == 0);

    /* add at the end of list */

    QTAILQ_INSERT_TAIL(&savevm_state.handlers, se, entry);

    return 0;

}

int vmstate_register_with_alias_id(DeviceState *dev, int instance_id,

                                   const VMStateDescription *vmsd,

                                   void *opaque, int alias_id,

                                   int required_for_version)

{

    SaveStateEntry *se;



    /* If this triggers, alias support can be dropped for the vmsd. */

    assert(alias_id == -1 || required_for_version >= vmsd->minimum_version_id);



    se = g_malloc0(sizeof(SaveStateEntry));

    se->version_id = vmsd->version_id;

    se->section_id = savevm_state.global_section_id++;

    se->opaque = opaque;

    se->vmsd = vmsd;

    se->alias_id = alias_id;



    if (dev) {

        char *id = qdev_get_dev_path(dev);

        if (id) {

            pstrcpy(se->idstr, sizeof(se->idstr), id);

            pstrcat(se->idstr, sizeof(se->idstr), "/");

            g_free(id);



            se->compat = g_malloc0(sizeof(CompatEntry));

            pstrcpy(se->compat->idstr, sizeof(se->compat->idstr), vmsd->name);

            se->compat->instance_id = instance_id == -1 ?

                         calculate_compat_instance_id(vmsd->name) : instance_id;

            instance_id = -1;

        }

    }

    pstrcat(se->idstr, sizeof(se->idstr), vmsd->name);



    if (instance_id == -1) {

        se->instance_id = calculate_new_instance_id(se->idstr);

    } else {

        se->instance_id = instance_id;

    }

    assert(!se->compat || se->instance_id == 0);

    /* add at the end of list */

    QTAILQ_INSERT_TAIL(&savevm_state.handlers, se, entry);

    return 0;

}

int register_savevm_live(const char *idstr,

