static inline void downmix_3f_1r_to_stereo(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += (samples[i + 256] + samples[i + 768]);

        samples[i + 256] += (samples[i + 512] + samples[i + 768]);

        samples[i + 512] = samples[i + 768] = 0;

    }

}

static inline void downmix_2f_2r_to_stereo(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += samples[i + 512];

        samples[i + 256] = samples[i + 768];

        samples[i + 512] = samples[i + 768] = 0;

    }

}

static inline void downmix_2f_1r_to_mono(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += (samples[i + 256] + samples[i + 512]);

        samples[i + 256] = samples[i + 512] = 0;

    }

}

static inline void downmix_2f_2r_to_mono(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += (samples[i + 256] + samples[i + 512] + samples[i + 768]);

        samples[i + 256] = samples[i + 512] = samples[i + 768] = 0;

    }

}

static int qsv_decode_init(AVCodecContext *avctx, QSVContext *q)

{

    const AVPixFmtDescriptor *desc;

    mfxSession session = NULL;

    int iopattern = 0;

    mfxVideoParam param = { { 0 } };

    int frame_width  = avctx->coded_width;

    int frame_height = avctx->coded_height;

    int ret;



    desc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);

    if (!desc)

        return AVERROR_BUG;



    if (!q->async_fifo) {

        q->async_fifo = av_fifo_alloc((1 + q->async_depth) *

                                      (sizeof(mfxSyncPoint*) + sizeof(QSVFrame*)));

        if (!q->async_fifo)

            return AVERROR(ENOMEM);

    }



    if (avctx->pix_fmt == AV_PIX_FMT_QSV && avctx->hwaccel_context) {

        AVQSVContext *user_ctx = avctx->hwaccel_context;

        session           = user_ctx->session;

        iopattern         = user_ctx->iopattern;

        q->ext_buffers    = user_ctx->ext_buffers;

        q->nb_ext_buffers = user_ctx->nb_ext_buffers;

    }



    if (avctx->hw_frames_ctx) {

        AVHWFramesContext    *frames_ctx = (AVHWFramesContext*)avctx->hw_frames_ctx->data;

        AVQSVFramesContext *frames_hwctx = frames_ctx->hwctx;



        if (!iopattern) {

            if (frames_hwctx->frame_type & MFX_MEMTYPE_OPAQUE_FRAME)

                iopattern = MFX_IOPATTERN_OUT_OPAQUE_MEMORY;

            else if (frames_hwctx->frame_type & MFX_MEMTYPE_VIDEO_MEMORY_DECODER_TARGET)

                iopattern = MFX_IOPATTERN_OUT_VIDEO_MEMORY;

        }



        frame_width  = frames_hwctx->surfaces[0].Info.Width;

        frame_height = frames_hwctx->surfaces[0].Info.Height;

    }



    if (!iopattern)

        iopattern = MFX_IOPATTERN_OUT_SYSTEM_MEMORY;

    q->iopattern = iopattern;



    ret = qsv_init_session(avctx, q, session, avctx->hw_frames_ctx);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing an MFX session\n");

        return ret;

    }



    ret = ff_qsv_codec_id_to_mfx(avctx->codec_id);

    if (ret < 0)

        return ret;



    param.mfx.CodecId      = ret;

    param.mfx.CodecProfile = ff_qsv_profile_to_mfx(avctx->codec_id, avctx->profile);

    param.mfx.CodecLevel   = avctx->level == FF_LEVEL_UNKNOWN ? MFX_LEVEL_UNKNOWN : avctx->level;



    param.mfx.FrameInfo.BitDepthLuma   = desc->comp[0].depth;

    param.mfx.FrameInfo.BitDepthChroma = desc->comp[0].depth;

    param.mfx.FrameInfo.Shift          = desc->comp[0].depth > 8;

    param.mfx.FrameInfo.FourCC         = q->fourcc;

    param.mfx.FrameInfo.Width          = frame_width;

    param.mfx.FrameInfo.Height         = frame_height;

    param.mfx.FrameInfo.ChromaFormat   = MFX_CHROMAFORMAT_YUV420;



    switch (avctx->field_order) {

    case AV_FIELD_PROGRESSIVE:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_PROGRESSIVE;

        break;

    case AV_FIELD_TT:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_FIELD_TFF;

        break;

    case AV_FIELD_BB:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_FIELD_BFF;

        break;

    default:

        param.mfx.FrameInfo.PicStruct = MFX_PICSTRUCT_UNKNOWN;

        break;

    }



    param.IOPattern   = q->iopattern;

    param.AsyncDepth  = q->async_depth;

    param.ExtParam    = q->ext_buffers;

    param.NumExtParam = q->nb_ext_buffers;



    ret = MFXVideoDECODE_Init(q->session, &param);

    if (ret < 0)

        return ff_qsv_print_error(avctx, ret,

                                  "Error initializing the MFX video decoder");



    q->frame_info = param.mfx.FrameInfo;



    return 0;

}

static int qsv_decode_init(AVCodecContext *avctx, QSVContext *q, AVPacket *avpkt)

{

    mfxVideoParam param = { { 0 } };

    mfxBitstream bs   = { { { 0 } } };

    int ret;

    enum AVPixelFormat pix_fmts[3] = { AV_PIX_FMT_QSV,

                                       AV_PIX_FMT_NV12,

                                       AV_PIX_FMT_NONE };



    ret = ff_get_format(avctx, pix_fmts);

    if (ret < 0)

        return ret;



    avctx->pix_fmt      = ret;



    q->iopattern  = MFX_IOPATTERN_OUT_SYSTEM_MEMORY;

    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;



        q->session        = qsv->session;

        q->iopattern      = qsv->iopattern;

        q->ext_buffers    = qsv->ext_buffers;

        q->nb_ext_buffers = qsv->nb_ext_buffers;

    }

    if (!q->session) {

        if (!q->internal_qs.session) {

            ret = ff_qsv_init_internal_session(avctx, &q->internal_qs,

                                               q->load_plugins);

            if (ret < 0)

                return ret;

        }



        q->session = q->internal_qs.session;

    }



    if (avpkt->size) {

        bs.Data       = avpkt->data;

        bs.DataLength = avpkt->size;

        bs.MaxLength  = bs.DataLength;

        bs.TimeStamp  = avpkt->pts;

    } else

        return AVERROR_INVALIDDATA;



    ret = ff_qsv_codec_id_to_mfx(avctx->codec_id);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported codec_id %08x\n", avctx->codec_id);

        return ret;

    }



    param.mfx.CodecId = ret;



    ret = MFXVideoDECODE_DecodeHeader(q->session, &bs, &param);

    if (MFX_ERR_MORE_DATA==ret) {

        /* this code means that header not found so we return packet size to skip

           a current packet

         */

        return avpkt->size;

    } else if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Decode header error %d\n", ret);

        return ff_qsv_error(ret);

    }

    param.IOPattern   = q->iopattern;

    param.AsyncDepth  = q->async_depth;

    param.ExtParam    = q->ext_buffers;

    param.NumExtParam = q->nb_ext_buffers;

    param.mfx.FrameInfo.BitDepthLuma   = 8;

    param.mfx.FrameInfo.BitDepthChroma = 8;



    ret = MFXVideoDECODE_Init(q->session, &param);

    if (ret < 0) {

        if (MFX_ERR_INVALID_VIDEO_PARAM==ret) {

            av_log(avctx, AV_LOG_ERROR,

                   "Error initializing the MFX video decoder, unsupported video\n");

        } else {

            av_log(avctx, AV_LOG_ERROR,

                   "Error initializing the MFX video decoder %d\n", ret);

        }

        return ff_qsv_error(ret);

    }



    avctx->profile      = param.mfx.CodecProfile;

    avctx->level        = param.mfx.CodecLevel;

    avctx->coded_width  = param.mfx.FrameInfo.Width;

    avctx->coded_height = param.mfx.FrameInfo.Height;

    avctx->width        = param.mfx.FrameInfo.CropW - param.mfx.FrameInfo.CropX;

    avctx->height       = param.mfx.FrameInfo.CropH - param.mfx.FrameInfo.CropY;



    /* maximum decoder latency should be not exceed max DPB size for h.264 and

       HEVC which is 16 for both cases.

       So weare  pre-allocating fifo big enough for 17 elements:

     */

    if (!q->async_fifo) {

        q->async_fifo = av_fifo_alloc((1 + 16) *

                                      (sizeof(mfxSyncPoint*) + sizeof(QSVFrame*)));

        if (!q->async_fifo)

            return AVERROR(ENOMEM);

    }



    if (!q->input_fifo) {

        q->input_fifo = av_fifo_alloc(1024*16);

        if (!q->input_fifo)

            return AVERROR(ENOMEM);

    }



    if (!q->pkt_fifo) {

        q->pkt_fifo = av_fifo_alloc( sizeof(AVPacket) * (1 + 16) );

        if (!q->pkt_fifo)

            return AVERROR(ENOMEM);

    }

    q->engine_ready = 1;



    return 0;

}

int ff_qsv_enc_init(AVCodecContext *avctx, QSVEncContext *q)

{

    int opaque_alloc = 0;

    int ret;



    q->param.IOPattern  = MFX_IOPATTERN_IN_SYSTEM_MEMORY;

    q->param.AsyncDepth = q->async_depth;



    q->async_fifo = av_fifo_alloc((1 + q->async_depth) *

                                  (sizeof(AVPacket) + sizeof(mfxSyncPoint) + sizeof(mfxBitstream*)));

    if (!q->async_fifo)

        return AVERROR(ENOMEM);



    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;



        q->session         = qsv->session;

        q->param.IOPattern = qsv->iopattern;



        opaque_alloc = qsv->opaque_alloc;

    }



    if (!q->session) {

        ret = ff_qsv_init_internal_session(avctx, &q->internal_session,

                                           q->load_plugins);

        if (ret < 0)

            return ret;



        q->session = q->internal_session;

    }



    ret = init_video_param(avctx, q);

    if (ret < 0)

        return ret;



    ret = MFXVideoENCODE_QueryIOSurf(q->session, &q->param, &q->req);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error querying the encoding parameters\n");

        return ff_qsv_error(ret);

    }



    if (opaque_alloc) {

        ret = qsv_init_opaque_alloc(avctx, q);

        if (ret < 0)

            return ret;

    }



    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;

        int i, j;



        q->extparam = av_mallocz_array(qsv->nb_ext_buffers + q->nb_extparam_internal,

                                       sizeof(*q->extparam));

        if (!q->extparam)

            return AVERROR(ENOMEM);



        q->param.ExtParam = q->extparam;

        for (i = 0; i < qsv->nb_ext_buffers; i++)

            q->param.ExtParam[i] = qsv->ext_buffers[i];

        q->param.NumExtParam = qsv->nb_ext_buffers;



        for (i = 0; i < q->nb_extparam_internal; i++) {

            for (j = 0; j < qsv->nb_ext_buffers; j++) {

                if (qsv->ext_buffers[j]->BufferId == q->extparam_internal[i]->BufferId)

                    break;

            }

            if (j < qsv->nb_ext_buffers)

                continue;



            q->param.ExtParam[q->param.NumExtParam++] = q->extparam_internal[i];

        }

    } else {

        q->param.ExtParam    = q->extparam_internal;

        q->param.NumExtParam = q->nb_extparam_internal;

    }



    ret = MFXVideoENCODE_Init(q->session, &q->param);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing the encoder\n");

        return ff_qsv_error(ret);

    }



    ret = qsv_retrieve_enc_params(avctx, q);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error retrieving encoding parameters.\n");

        return ret;

    }



    q->avctx = avctx;



    return 0;

}

int qsv_init(AVCodecContext *s)

{

    InputStream *ist = s->opaque;

    QSVContext  *qsv = ist->hwaccel_ctx;

    AVQSVContext *hwctx_dec;

    int ret;



    if (!qsv) {

        av_log(NULL, AV_LOG_ERROR, "QSV transcoding is not initialized. "

               "-hwaccel qsv should only be used for one-to-one QSV transcoding "

               "with no filters.\n");

        return AVERROR_BUG;

    }



    ret = init_opaque_surf(qsv);

    if (ret < 0)

        return ret;



    hwctx_dec = av_qsv_alloc_context();

    if (!hwctx_dec)

        return AVERROR(ENOMEM);



    hwctx_dec->session        = qsv->session;

    hwctx_dec->iopattern      = MFX_IOPATTERN_OUT_OPAQUE_MEMORY;

    hwctx_dec->ext_buffers    = qsv->ext_buffers;

    hwctx_dec->nb_ext_buffers = FF_ARRAY_ELEMS(qsv->ext_buffers);



    av_freep(&s->hwaccel_context);

    s->hwaccel_context = hwctx_dec;



    ist->hwaccel_get_buffer = qsv_get_buffer;

    ist->hwaccel_uninit     = qsv_uninit;



    return 0;

}

