static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }




    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static void decode_plane_bitstream(HYuvContext *s, int count, int plane)

{

    int i;



    count /= 2;



    if (s->bps <= 8) {

        OPEN_READER(re, &s->gb);

        if (count >= (get_bits_left(&s->gb)) / (32 * 2)) {

            for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

                READ_2PIX_PLANE(s->temp[0][2 * i], s->temp[0][2 * i + 1], plane, OP8bits);

            }

        } else {

            for(i=0; i<count; i++){

                READ_2PIX_PLANE(s->temp[0][2 * i], s->temp[0][2 * i + 1], plane, OP8bits);

            }

        }

        CLOSE_READER(re, &s->gb);

    } else if (s->bps <= 14) {

        OPEN_READER(re, &s->gb);

        if (count >= (get_bits_left(&s->gb)) / (32 * 2)) {

            for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

                READ_2PIX_PLANE(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane, OP14bits);

            }

        } else {

            for(i=0; i<count; i++){

                READ_2PIX_PLANE(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane, OP14bits);

            }

        }

        CLOSE_READER(re, &s->gb);

    } else {

        if (count >= (get_bits_left(&s->gb)) / (32 * 2)) {

            for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

                READ_2PIX_PLANE16(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane);

            }

        } else {

            for(i=0; i<count; i++){

                READ_2PIX_PLANE16(s->temp16[0][2 * i], s->temp16[0][2 * i + 1], plane);

            }

        }

    }

}

static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

        for (; i < count; i++)

            s->temp[0][2 * i    ] = s->temp[1][i] =

            s->temp[0][2 * i + 1] = s->temp[2][i] = 128;

    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static void encode_422_bitstream(HYuvContext *s, int count){

    int i;



    count/=2;

    if(s->flags&CODEC_FLAG_PASS1){

        for(i=0; i<count; i++){

            s->stats[0][ s->temp[0][2*i  ] ]++;

            s->stats[1][ s->temp[1][  i  ] ]++;

            s->stats[0][ s->temp[0][2*i+1] ]++;

            s->stats[2][ s->temp[2][  i  ] ]++;

        }

    }else if(s->context){

        for(i=0; i<count; i++){

            s->stats[0][ s->temp[0][2*i  ] ]++;

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i  ] ], s->bits[0][ s->temp[0][2*i  ] ]);

            s->stats[1][ s->temp[1][  i  ] ]++;

            put_bits(&s->pb, s->len[1][ s->temp[1][  i  ] ], s->bits[1][ s->temp[1][  i  ] ]);

            s->stats[0][ s->temp[0][2*i+1] ]++;

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i+1] ], s->bits[0][ s->temp[0][2*i+1] ]);

            s->stats[2][ s->temp[2][  i  ] ]++;

            put_bits(&s->pb, s->len[2][ s->temp[2][  i  ] ], s->bits[2][ s->temp[2][  i  ] ]);

        }

    }else{

        for(i=0; i<count; i++){

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i  ] ], s->bits[0][ s->temp[0][2*i  ] ]);

            put_bits(&s->pb, s->len[1][ s->temp[1][  i  ] ], s->bits[1][ s->temp[1][  i  ] ]);

            put_bits(&s->pb, s->len[0][ s->temp[0][2*i+1] ], s->bits[0][ s->temp[0][2*i+1] ]);

            put_bits(&s->pb, s->len[2][ s->temp[2][  i  ] ], s->bits[2][ s->temp[2][  i  ] ]);

        }

    }

}

