static int jpeg2000_decode_frame(AVCodecContext *avctx, void *data,

                                 int *got_frame, AVPacket *avpkt)

{

    Jpeg2000DecoderContext *s = avctx->priv_data;

    ThreadFrame frame = { .f = data };

    AVFrame *picture = data;

    int tileno, ret;



    s->avctx     = avctx;

    s->buf       = s->buf_start = avpkt->data;

    s->buf_end   = s->buf_start + avpkt->size;

    s->curtileno = 0; // TODO: only one tile in DCI JP2K. to implement for more tiles



    // reduction factor, i.e number of resolution levels to skip

    s->reduction_factor = s->lowres;



    if (s->buf_end - s->buf < 2)

        return AVERROR_INVALIDDATA;



    // check if the image is in jp2 format

    if ((AV_RB32(s->buf) == 12) &&

        (AV_RB32(s->buf + 4) == JP2_SIG_TYPE) &&

        (AV_RB32(s->buf + 8) == JP2_SIG_VALUE)) {

        if (!jp2_find_codestream(s)) {

            av_log(avctx, AV_LOG_ERROR,

                   "Could not find Jpeg2000 codestream atom.\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (bytestream_get_be16(&s->buf) != JPEG2000_SOC) {

        av_log(avctx, AV_LOG_ERROR, "SOC marker not present\n");

        return AVERROR_INVALIDDATA;

    }

    if (ret = jpeg2000_read_main_headers(s))

        goto end;



    /* get picture buffer */

    if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "ff_thread_get_buffer() failed.\n");

        goto end;

    }

    picture->pict_type = AV_PICTURE_TYPE_I;

    picture->key_frame = 1;



    if (ret = jpeg2000_read_bitstream_packets(s))

        goto end;

    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++)

        if (ret = jpeg2000_decode_tile(s, s->tile + tileno, picture))

            goto end;



    *got_frame = 1;



end:

    jpeg2000_dec_cleanup(s);

    return ret ? ret : s->buf - s->buf_start;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    UtvideoContext *c = avctx->priv_data;

    int i, j;

    const uint8_t *plane_start[5];

    int plane_size, max_slice_size = 0, slice_start, slice_end, slice_size;

    int ret;

    GetByteContext gb;

    ThreadFrame frame = { .f = data };



    if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0)

        return ret;



    /* parse plane structure to get frame flags and validate slice offsets */

    bytestream2_init(&gb, buf, buf_size);

    for (i = 0; i < c->planes; i++) {

        plane_start[i] = gb.buffer;

        if (bytestream2_get_bytes_left(&gb) < 256 + 4 * c->slices) {

            av_log(avctx, AV_LOG_ERROR, "Insufficient data for a plane\n");

            return AVERROR_INVALIDDATA;

        }

        bytestream2_skipu(&gb, 256);

        slice_start = 0;

        slice_end   = 0;

        for (j = 0; j < c->slices; j++) {

            slice_end   = bytestream2_get_le32u(&gb);

            slice_size  = slice_end - slice_start;

            if (slice_end < 0 || slice_size < 0 ||

                bytestream2_get_bytes_left(&gb) < slice_end) {

                av_log(avctx, AV_LOG_ERROR, "Incorrect slice size\n");

                return AVERROR_INVALIDDATA;

            }

            slice_start = slice_end;

            max_slice_size = FFMAX(max_slice_size, slice_size);

        }

        plane_size = slice_end;

        bytestream2_skipu(&gb, plane_size);

    }

    plane_start[c->planes] = gb.buffer;

    if (bytestream2_get_bytes_left(&gb) < c->frame_info_size) {

        av_log(avctx, AV_LOG_ERROR, "Not enough data for frame information\n");

        return AVERROR_INVALIDDATA;

    }

    c->frame_info = bytestream2_get_le32u(&gb);

    av_log(avctx, AV_LOG_DEBUG, "frame information flags %"PRIX32"\n",

           c->frame_info);



    c->frame_pred = (c->frame_info >> 8) & 3;



    if (c->frame_pred == PRED_GRADIENT) {

        avpriv_request_sample(avctx, "Frame with gradient prediction");

        return AVERROR_PATCHWELCOME;

    }



    av_fast_malloc(&c->slice_bits, &c->slice_bits_size,

                   max_slice_size + AV_INPUT_BUFFER_PADDING_SIZE);



    if (!c->slice_bits) {

        av_log(avctx, AV_LOG_ERROR, "Cannot allocate temporary buffer\n");

        return AVERROR(ENOMEM);

    }



    switch (c->avctx->pix_fmt) {

    case AV_PIX_FMT_RGB24:

    case AV_PIX_FMT_RGBA:

        for (i = 0; i < c->planes; i++) {

            ret = decode_plane(c, i, frame.f->data[0] + ff_ut_rgb_order[i],

                               c->planes, frame.f->linesize[0], avctx->width,

                               avctx->height, plane_start[i],

                               c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[0] + ff_ut_rgb_order[i],

                                   c->planes, frame.f->linesize[0], avctx->width,

                                   avctx->height, c->slices, 0);

                } else {

                    restore_median_il(frame.f->data[0] + ff_ut_rgb_order[i],

                                      c->planes, frame.f->linesize[0],

                                      avctx->width, avctx->height, c->slices,

                                      0);

                }

            }

        }

        restore_rgb_planes(frame.f->data[0], c->planes, frame.f->linesize[0],

                           avctx->width, avctx->height);

        break;

    case AV_PIX_FMT_YUV420P:

        for (i = 0; i < 3; i++) {

            ret = decode_plane(c, i, frame.f->data[i], 1, frame.f->linesize[i],

                               avctx->width >> !!i, avctx->height >> !!i,

                               plane_start[i], c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[i], 1, frame.f->linesize[i],

                                   avctx->width >> !!i, avctx->height >> !!i,

                                   c->slices, !i);

                } else {

                    restore_median_il(frame.f->data[i], 1, frame.f->linesize[i],

                                      avctx->width  >> !!i,

                                      avctx->height >> !!i,

                                      c->slices, !i);

                }

            }

        }

        break;

    case AV_PIX_FMT_YUV422P:

        for (i = 0; i < 3; i++) {

            ret = decode_plane(c, i, frame.f->data[i], 1, frame.f->linesize[i],

                               avctx->width >> !!i, avctx->height,

                               plane_start[i], c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[i], 1, frame.f->linesize[i],

                                   avctx->width >> !!i, avctx->height,

                                   c->slices, 0);

                } else {

                    restore_median_il(frame.f->data[i], 1, frame.f->linesize[i],

                                      avctx->width >> !!i, avctx->height,

                                      c->slices, 0);

                }

            }

        }

        break;

    }



    frame.f->key_frame = 1;

    frame.f->pict_type = AV_PICTURE_TYPE_I;

    frame.f->interlaced_frame = !!c->interlaced;



    *got_frame = 1;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static int encode_frame(AVCodecContext *avctx,

                        uint8_t *buf, int buf_size,

                        void *data)

{

    int tileno, ret;

    J2kEncoderContext *s = avctx->priv_data;



    // init:

    s->buf = s->buf_start = buf;

    s->buf_end = buf + buf_size;



    s->picture = data;



    s->lambda = s->picture->quality * LAMBDA_SCALE;



    copy_frame(s);

    reinit(s);



    if (s->buf_end - s->buf < 2)

        return -1;

    bytestream_put_be16(&s->buf, J2K_SOC);

    if (ret = put_siz(s))

        return ret;

    if (ret = put_cod(s))

        return ret;

    if (ret = put_qcd(s, 0))

        return ret;



    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++){

        uint8_t *psotptr;

        if ((psotptr = put_sot(s, tileno)) < 0)

            return psotptr;

        if (s->buf_end - s->buf < 2)

            return -1;

        bytestream_put_be16(&s->buf, J2K_SOD);

        if (ret = encode_tile(s, s->tile + tileno, tileno))

            return ret;

        bytestream_put_be32(&psotptr, s->buf - psotptr + 6);

    }

    if (s->buf_end - s->buf < 2)

        return -1;

    bytestream_put_be16(&s->buf, J2K_EOC);



    av_log(s->avctx, AV_LOG_DEBUG, "end\n");

    return s->buf - s->buf_start;

}

static int smvjpeg_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                            AVPacket *avpkt)

{

    const AVPixFmtDescriptor *desc;

    SMVJpegDecodeContext *s = avctx->priv_data;

    AVFrame* mjpeg_data = s->picture[0];

    int i, cur_frame = 0, ret = 0;



    cur_frame = avpkt->pts % s->frames_per_jpeg;



    /* Are we at the start of a block? */

    if (!cur_frame) {

        av_frame_unref(mjpeg_data);

        ret = avcodec_decode_video2(s->avctx, mjpeg_data, &s->mjpeg_data_size, avpkt);

        if (ret < 0) {

            s->mjpeg_data_size = 0;

            return ret;

        }

    } else if (!s->mjpeg_data_size)

        return AVERROR(EINVAL);



    desc = av_pix_fmt_desc_get(s->avctx->pix_fmt);

    if (desc && mjpeg_data->height % (s->frames_per_jpeg << desc->log2_chroma_h)) {

        av_log(avctx, AV_LOG_ERROR, "Invalid height\n");

        return AVERROR_INVALIDDATA;

    }



    /*use the last lot... */

    *data_size = s->mjpeg_data_size;



    avctx->pix_fmt = s->avctx->pix_fmt;



    /* We shouldn't get here if frames_per_jpeg <= 0 because this was rejected

       in init */

    ret = ff_set_dimensions(avctx, mjpeg_data->width, mjpeg_data->height / s->frames_per_jpeg);

    if (ret < 0) {

        av_log(s, AV_LOG_ERROR, "Failed to set dimensions\n");

        return ret;

    }



    if (*data_size) {

        s->picture[1]->extended_data = NULL;

        s->picture[1]->width         = avctx->width;

        s->picture[1]->height        = avctx->height;

        s->picture[1]->format        = avctx->pix_fmt;

        /* ff_init_buffer_info(avctx, &s->picture[1]); */

        smv_img_pnt(s->picture[1]->data, mjpeg_data->data, mjpeg_data->linesize,

                    avctx->pix_fmt, avctx->width, avctx->height, cur_frame);

        for (i = 0; i < AV_NUM_DATA_POINTERS; i++)

            s->picture[1]->linesize[i] = mjpeg_data->linesize[i];



        ret = av_frame_ref(data, s->picture[1]);

    }



    return ret;

}

static void vfio_platform_eoi(VFIODevice *vbasedev)

{

    VFIOINTp *intp;

    VFIOPlatformDevice *vdev =

        container_of(vbasedev, VFIOPlatformDevice, vbasedev);



    qemu_mutex_lock(&vdev->intp_mutex);

    QLIST_FOREACH(intp, &vdev->intp_list, next) {

        if (intp->state == VFIO_IRQ_ACTIVE) {

            trace_vfio_platform_eoi(intp->pin,

                                event_notifier_get_fd(intp->interrupt));

            intp->state = VFIO_IRQ_INACTIVE;



            /* deassert the virtual IRQ */

            qemu_set_irq(intp->qemuirq, 0);



            if (intp->flags & VFIO_IRQ_INFO_AUTOMASKED) {

                /* unmasks the physical level-sensitive IRQ */

                vfio_unmask_single_irqindex(vbasedev, intp->pin);

            }



            /* a single IRQ can be active at a time */

            break;

        }

    }

    /* in case there are pending IRQs, handle the first one */

    if (!QSIMPLEQ_EMPTY(&vdev->pending_intp_queue)) {

        intp = QSIMPLEQ_FIRST(&vdev->pending_intp_queue);

        vfio_intp_inject_pending_lockheld(intp);

        QSIMPLEQ_REMOVE_HEAD(&vdev->pending_intp_queue, pqnext);

    }

    qemu_mutex_unlock(&vdev->intp_mutex);

}

static void vfio_platform_realize(DeviceState *dev, Error **errp)

{

    VFIOPlatformDevice *vdev = VFIO_PLATFORM_DEVICE(dev);

    SysBusDevice *sbdev = SYS_BUS_DEVICE(dev);

    VFIODevice *vbasedev = &vdev->vbasedev;

    VFIOINTp *intp;

    int i, ret;



    vbasedev->type = VFIO_DEVICE_TYPE_PLATFORM;

    vbasedev->ops = &vfio_platform_ops;



    trace_vfio_platform_realize(vbasedev->name, vdev->compat);



    ret = vfio_base_device_init(vbasedev);

    if (ret) {

        error_setg(errp, "vfio: vfio_base_device_init failed for %s",

                   vbasedev->name);

        return;

    }



    for (i = 0; i < vbasedev->num_regions; i++) {

        vfio_map_region(vdev, i);

        sysbus_init_mmio(sbdev, &vdev->regions[i]->mem);

    }



    QLIST_FOREACH(intp, &vdev->intp_list, next) {

        vfio_start_eventfd_injection(intp);

    }

}

static void vfio_intp_interrupt(VFIOINTp *intp)

{

    int ret;

    VFIOINTp *tmp;

    VFIOPlatformDevice *vdev = intp->vdev;

    bool delay_handling = false;



    qemu_mutex_lock(&vdev->intp_mutex);

    if (intp->state == VFIO_IRQ_INACTIVE) {

        QLIST_FOREACH(tmp, &vdev->intp_list, next) {

            if (tmp->state == VFIO_IRQ_ACTIVE ||

                tmp->state == VFIO_IRQ_PENDING) {

                delay_handling = true;

                break;

            }

        }

    }

    if (delay_handling) {

        /*

         * the new IRQ gets a pending status and is pushed in

         * the pending queue

         */

        intp->state = VFIO_IRQ_PENDING;

        trace_vfio_intp_interrupt_set_pending(intp->pin);

        QSIMPLEQ_INSERT_TAIL(&vdev->pending_intp_queue,

                             intp, pqnext);

        ret = event_notifier_test_and_clear(&intp->interrupt);

        qemu_mutex_unlock(&vdev->intp_mutex);

        return;

    }



    trace_vfio_platform_intp_interrupt(intp->pin,

                              event_notifier_get_fd(&intp->interrupt));



    ret = event_notifier_test_and_clear(&intp->interrupt);

    if (!ret) {

        error_report("Error when clearing fd=%d (ret = %d)",

                     event_notifier_get_fd(&intp->interrupt), ret);

    }



    intp->state = VFIO_IRQ_ACTIVE;



    /* sets slow path */

    vfio_mmap_set_enabled(vdev, false);



    /* trigger the virtual IRQ */

    qemu_set_irq(intp->qemuirq, 1);



    /*

     * Schedule the mmap timer which will restore fastpath when no IRQ

     * is active anymore

     */

    if (vdev->mmap_timeout) {

        timer_mod(vdev->mmap_timer,

                  qemu_clock_get_ms(QEMU_CLOCK_VIRTUAL) +

                      vdev->mmap_timeout);

    }

    qemu_mutex_unlock(&vdev->intp_mutex);

}

static int vfio_set_resample_eventfd(VFIOINTp *intp)

{

    VFIODevice *vbasedev = &intp->vdev->vbasedev;

    struct vfio_irq_set *irq_set;

    int argsz, ret;

    int32_t *pfd;



    argsz = sizeof(*irq_set) + sizeof(*pfd);

    irq_set = g_malloc0(argsz);

    irq_set->argsz = argsz;

    irq_set->flags = VFIO_IRQ_SET_DATA_EVENTFD | VFIO_IRQ_SET_ACTION_UNMASK;

    irq_set->index = intp->pin;

    irq_set->start = 0;

    irq_set->count = 1;

    pfd = (int32_t *)&irq_set->data;

    *pfd = event_notifier_get_fd(&intp->unmask);

    qemu_set_fd_handler(*pfd, NULL, NULL, NULL);

    ret = ioctl(vbasedev->fd, VFIO_DEVICE_SET_IRQS, irq_set);

    g_free(irq_set);

    if (ret < 0) {

        error_report("vfio: Failed to set resample eventfd: %m");

    }

    return ret;

}

static void gen_addq(DisasContext *s, TCGv_i64 val, int rlow, int rhigh)

{

    TCGv_i64 tmp;

    TCGv tmpl;

    TCGv tmph;



    /* Load 64-bit value rd:rn.  */

    tmpl = load_reg(s, rlow);

    tmph = load_reg(s, rhigh);

    tmp = tcg_temp_new_i64();

    tcg_gen_concat_i32_i64(tmp, tmpl, tmph);

    dead_tmp(tmpl);

    dead_tmp(tmph);

    tcg_gen_add_i64(val, val, tmp);

    tcg_temp_free_i64(tmp);

}

static void gen_add16(TCGv t0, TCGv t1)

{

    TCGv tmp = new_tmp();

    tcg_gen_xor_i32(tmp, t0, t1);

    tcg_gen_andi_i32(tmp, tmp, 0x8000);

    tcg_gen_andi_i32(t0, t0, ~0x8000);

    tcg_gen_andi_i32(t1, t1, ~0x8000);

    tcg_gen_add_i32(t0, t0, t1);

    tcg_gen_xor_i32(t0, t0, tmp);

    dead_tmp(tmp);

    dead_tmp(t1);

}

static void gen_addq(DisasContext *s, TCGv val, int rlow, int rhigh)

{

    TCGv tmp;

    TCGv tmpl;

    TCGv tmph;



    /* Load 64-bit value rd:rn.  */

    tmpl = load_reg(s, rlow);

    tmph = load_reg(s, rhigh);

    tmp = tcg_temp_new(TCG_TYPE_I64);

    tcg_gen_concat_i32_i64(tmp, tmpl, tmph);

    dead_tmp(tmpl);

    dead_tmp(tmph);

    tcg_gen_add_i64(val, val, tmp);

}

static void gen_neon_zip_u16(TCGv t0, TCGv t1)

{

    TCGv tmp, tmp2;



    tmp = new_tmp();

    tmp2 = new_tmp();



    tcg_gen_andi_i32(tmp, t0, 0xffff);

    tcg_gen_shli_i32(tmp2, t1, 16);

    tcg_gen_or_i32(tmp, tmp, tmp2);

    tcg_gen_andi_i32(t1, t1, 0xffff0000);

    tcg_gen_shri_i32(tmp2, t0, 16);

    tcg_gen_or_i32(t1, t1, tmp2);

    tcg_gen_mov_i32(t0, tmp);



    dead_tmp(tmp2);

    dead_tmp(tmp);

}

static void event_test_emit(test_QAPIEvent event, QDict *d, Error **errp)

{

    QObject *obj;

    QDict *t;

    int64_t s, ms;



    /* Verify that we have timestamp, then remove it to compare other fields */

    obj = qdict_get(d, "timestamp");

    g_assert(obj);

    t = qobject_to_qdict(obj);

    g_assert(t);

    obj = qdict_get(t, "seconds");

    g_assert(obj && qobject_type(obj) == QTYPE_QINT);

    s = qint_get_int(qobject_to_qint(obj));

    obj = qdict_get(t, "microseconds");

    g_assert(obj && qobject_type(obj) == QTYPE_QINT);

    ms = qint_get_int(qobject_to_qint(obj));

    if (s == -1) {

        g_assert(ms == -1);

    } else {

        g_assert(ms >= 0 && ms <= 999999);

    }

    g_assert(qdict_size(t) == 2);



    qdict_del(d, "timestamp");



    g_assert(qdict_cmp_simple(d, test_event_data->expect));



}

static void simple_varargs(void)

{

    QObject *embedded_obj;

    QObject *obj;

    LiteralQObject decoded = QLIT_QLIST(((LiteralQObject[]){

            QLIT_QINT(1),

            QLIT_QINT(2),

            QLIT_QLIST(((LiteralQObject[]){

                        QLIT_QINT(32),

                        QLIT_QINT(42),

                        {}})),

            {}}));



    embedded_obj = qobject_from_json("[32, 42]", NULL);

    g_assert(embedded_obj != NULL);



    obj = qobject_from_jsonf("[%d, 2, %p]", 1, embedded_obj);

