static av_cold int vorbis_encode_init(AVCodecContext *avccontext)

{

    vorbis_enc_context *venc = avccontext->priv_data;



    if (avccontext->channels != 2) {

        av_log(avccontext, AV_LOG_ERROR, "Current Libav Vorbis encoder only supports 2 channels.\n");

        return -1;

    }



    create_vorbis_context(venc, avccontext);



    if (avccontext->flags & CODEC_FLAG_QSCALE)

        venc->quality = avccontext->global_quality / (float)FF_QP2LAMBDA / 10.;

    else

        venc->quality = 0.03;

    venc->quality *= venc->quality;



    avccontext->extradata_size = put_main_header(venc, (uint8_t**)&avccontext->extradata);



    avccontext->frame_size     = 1 << (venc->log2_blocksize[0] - 1);



    avccontext->coded_frame            = avcodec_alloc_frame();

    avccontext->coded_frame->key_frame = 1;



    return 0;

}

static av_cold int cinepak_decode_init(AVCodecContext *avctx)

{

    CinepakContext *s = avctx->priv_data;



    s->avctx = avctx;

    s->width = (avctx->width + 3) & ~3;

    s->height = (avctx->height + 3) & ~3;

    s->sega_film_skip_bytes = -1;  /* uninitialized state */



    // check for paletted data

    if (avctx->bits_per_coded_sample != 8) {

        s->palette_video = 0;

        avctx->pix_fmt = AV_PIX_FMT_YUV420P;

    } else {

        s->palette_video = 1;

        avctx->pix_fmt = AV_PIX_FMT_PAL8;

    }



    s->frame.data[0] = NULL;



    return 0;

}

static av_cold int twolame_encode_init(AVCodecContext *avctx)

{

    TWOLAMEContext *s = avctx->priv_data;

    int ret;



    avctx->frame_size = TWOLAME_SAMPLES_PER_FRAME;

    avctx->delay      = 512 - 32 + 1;



    s->glopts = twolame_init();

    if (!s->glopts)

        return AVERROR(ENOMEM);



    twolame_set_verbosity(s->glopts, s->verbosity);

    twolame_set_mode(s->glopts, s->mode);

    twolame_set_psymodel(s->glopts, s->psymodel);

    twolame_set_energy_levels(s->glopts, s->energy);

    twolame_set_error_protection(s->glopts, s->error_protection);

    twolame_set_copyright(s->glopts, s->copyright);

    twolame_set_original(s->glopts, s->original);



    twolame_set_num_channels(s->glopts, avctx->channels);

    twolame_set_in_samplerate(s->glopts, avctx->sample_rate);

    twolame_set_out_samplerate(s->glopts, avctx->sample_rate);

    if (avctx->flags & CODEC_FLAG_QSCALE || !avctx->bit_rate) {

        twolame_set_VBR(s->glopts, TRUE);

        twolame_set_VBR_level(s->glopts,

                              avctx->global_quality / (float) FF_QP2LAMBDA);

        av_log(avctx, AV_LOG_WARNING,

               "VBR in MP2 is a hack, use another codec that supports it.\n");

    } else {

        twolame_set_bitrate(s->glopts, avctx->bit_rate / 1000);

    }



    ret = twolame_init_params(s->glopts);

    if (ret) {

        twolame_encode_close(avctx);

        return AVERROR_UNKNOWN;

    }



    return 0;

}

static av_cold int adx_encode_init(AVCodecContext *avctx)

{

    ADXContext *c = avctx->priv_data;



    if (avctx->channels > 2)

        return -1;

    avctx->frame_size = 32;



    avctx->coded_frame = avcodec_alloc_frame();

    avctx->coded_frame->key_frame = 1;



    /* the cutoff can be adjusted, but this seems to work pretty well */

    c->cutoff = 500;

    ff_adx_calculate_coeffs(c->cutoff, avctx->sample_rate, COEFF_BITS, c->coeff);



    return 0;

}

static int libshine_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                 const AVFrame *frame, int *got_packet_ptr)

{

    SHINEContext *s = avctx->priv_data;

    MPADecodeHeader hdr;

    unsigned char *data;

    long written;

    int ret, len;



    if (frame)

        data = shine_encode_buffer(s->shine, (int16_t **)frame->data, &written);

    else

        data = shine_flush(s->shine, &written);

    if (written < 0)

        return -1;

    if (written > 0) {

        if (s->buffer_index + written > BUFFER_SIZE) {

            av_log(avctx, AV_LOG_ERROR, "internal buffer too small\n");

            return AVERROR_BUG;

        }

        memcpy(s->buffer + s->buffer_index, data, written);

        s->buffer_index += written;

    }

    if (frame) {

        if ((ret = ff_af_queue_add(&s->afq, frame)) < 0)

            return ret;

    }



    if (s->buffer_index < 4 || !s->afq.frame_count)

        return 0;

    if (avpriv_mpegaudio_decode_header(&hdr, AV_RB32(s->buffer))) {

        av_log(avctx, AV_LOG_ERROR, "free format output not supported\n");

        return -1;

    }



    len = hdr.frame_size;

    if (len <= s->buffer_index) {

        if ((ret = ff_alloc_packet2(avctx, avpkt, len)))

            return ret;

        memcpy(avpkt->data, s->buffer, len);

        s->buffer_index -= len;

        memmove(s->buffer, s->buffer + len, s->buffer_index);



        ff_af_queue_remove(&s->afq, avctx->frame_size, &avpkt->pts,

                           &avpkt->duration);



        avpkt->size = len;

        *got_packet_ptr = 1;

    }

    return 0;

}

static int ra288_decode_frame(AVCodecContext * avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    float *out;

    int i, ret;

    RA288Context *ractx = avctx->priv_data;

    GetBitContext gb;



    if (buf_size < avctx->block_align) {

        av_log(avctx, AV_LOG_ERROR,

               "Error! Input buffer is too small [%d<%d]\n",

               buf_size, avctx->block_align);

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    frame->nb_samples = RA288_BLOCK_SIZE * RA288_BLOCKS_PER_FRAME;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;

    out = (float *)frame->data[0];



    init_get_bits8(&gb, buf, avctx->block_align);



    for (i=0; i < RA288_BLOCKS_PER_FRAME; i++) {

        float gain = amptable[get_bits(&gb, 3)];

        int cb_coef = get_bits(&gb, 6 + (i&1));



        decode(ractx, gain, cb_coef);



        memcpy(out, &ractx->sp_hist[70 + 36], RA288_BLOCK_SIZE * sizeof(*out));

        out += RA288_BLOCK_SIZE;



        if ((i & 7) == 3) {

            backward_filter(ractx, ractx->sp_hist, ractx->sp_rec, syn_window,

                            ractx->sp_lpc, syn_bw_tab, 36, 40, 35, 70);



            backward_filter(ractx, ractx->gain_hist, ractx->gain_rec, gain_window,

                            ractx->gain_lpc, gain_bw_tab, 10, 8, 20, 28);

        }

    }



    *got_frame_ptr = 1;



    return avctx->block_align;

}

static int Faac_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    FaacAudioContext *s = avctx->priv_data;

    int bytes_written, ret;

    int num_samples  = frame ? frame->nb_samples : 0;

    void *samples    = frame ? frame->data[0]    : NULL;



    if ((ret = ff_alloc_packet2(avctx, avpkt, (7 + 768) * avctx->channels))) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet\n");

        return ret;

    }



    bytes_written = faacEncEncode(s->faac_handle, samples,

                                  num_samples * avctx->channels,

                                  avpkt->data, avpkt->size);

    if (bytes_written < 0) {

        av_log(avctx, AV_LOG_ERROR, "faacEncEncode() error\n");

        return bytes_written;

    }



    /* add current frame to the queue */

    if (frame) {

        if ((ret = ff_af_queue_add(&s->afq, frame)) < 0)

            return ret;

    }



    if (!bytes_written)

        return 0;



    /* Get the next frame pts/duration */

    ff_af_queue_remove(&s->afq, avctx->frame_size, &avpkt->pts,

                       &avpkt->duration);



    avpkt->size = bytes_written;

    *got_packet_ptr = 1;

    return 0;

}

static int roq_dpcm_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                 const AVFrame *frame, int *got_packet_ptr)

{

    int i, stereo, data_size, ret;

    const int16_t *in = frame ? (const int16_t *)frame->data[0] : NULL;

    uint8_t *out;

    ROQDPCMContext *context = avctx->priv_data;



    stereo = (avctx->channels == 2);



    if (!in && context->input_frames >= 8)

        return 0;



    if (in && context->input_frames < 8) {

        memcpy(&context->frame_buffer[context->buffered_samples * avctx->channels],

               in, avctx->frame_size * avctx->channels * sizeof(*in));

        context->buffered_samples += avctx->frame_size;

        if (context->input_frames == 0)

            context->first_pts = frame->pts;

        if (context->input_frames < 7) {

            context->input_frames++;

            return 0;

        }

    }

    if (context->input_frames < 8) {

        in = context->frame_buffer;

    }



    if (stereo) {

        context->lastSample[0] &= 0xFF00;

        context->lastSample[1] &= 0xFF00;

    }



    if (context->input_frames == 7)

        data_size = avctx->channels * context->buffered_samples;

    else

        data_size = avctx->channels * avctx->frame_size;



    if ((ret = ff_alloc_packet2(avctx, avpkt, ROQ_HEADER_SIZE + data_size)))

        return ret;

    out = avpkt->data;



    bytestream_put_byte(&out, stereo ? 0x21 : 0x20);

    bytestream_put_byte(&out, 0x10);

    bytestream_put_le32(&out, data_size);



    if (stereo) {

        bytestream_put_byte(&out, (context->lastSample[1])>>8);

        bytestream_put_byte(&out, (context->lastSample[0])>>8);

    } else

        bytestream_put_le16(&out, context->lastSample[0]);



    /* Write the actual samples */

    for (i = 0; i < data_size; i++)

        *out++ = dpcm_predict(&context->lastSample[i & 1], *in++);



    avpkt->pts      = context->input_frames <= 7 ? context->first_pts : frame->pts;

    avpkt->duration = data_size / avctx->channels;



    context->input_frames++;

    if (!in)

        context->input_frames = FFMAX(context->input_frames, 8);



    *got_packet_ptr = 1;

    return 0;

}

static void apply_window_and_mdct(AACEncContext *s, SingleChannelElement *sce,

                                  float *audio)

{

    int i;

    float *output = sce->ret_buf;



    apply_window[sce->ics.window_sequence[0]](s->fdsp, sce, audio);



    if (sce->ics.window_sequence[0] != EIGHT_SHORT_SEQUENCE)

        s->mdct1024.mdct_calc(&s->mdct1024, sce->coeffs, output);

    else

        for (i = 0; i < 1024; i += 128)

            s->mdct128.mdct_calc(&s->mdct128, sce->coeffs + i, output + i*2);

    memcpy(audio, audio + 1024, sizeof(audio[0]) * 1024);

    memcpy(sce->pcoeffs, sce->coeffs, sizeof(sce->pcoeffs));

}

static void apply_dependent_coupling_fixed(AACContext *ac,

                                     SingleChannelElement *target,

                                     ChannelElement *cce, int index)

{

    IndividualChannelStream *ics = &cce->ch[0].ics;

    const uint16_t *offsets = ics->swb_offset;

    int *dest = target->coeffs;

    const int *src = cce->ch[0].coeffs;

    int g, i, group, k, idx = 0;

    if (ac->oc[1].m4ac.object_type == AOT_AAC_LTP) {

        av_log(ac->avctx, AV_LOG_ERROR,

               "Dependent coupling is not supported together with LTP\n");

        return;

    }

    for (g = 0; g < ics->num_window_groups; g++) {

        for (i = 0; i < ics->max_sfb; i++, idx++) {

            if (cce->ch[0].band_type[idx] != ZERO_BT) {

                const int gain = cce->coup.gain[index][idx];

                int shift, round, c, tmp;



                if (gain < 0) {

                    c = -cce_scale_fixed[-gain & 7];

                    shift = (-gain-1024) >> 3;

                }

                else {

                    c = cce_scale_fixed[gain & 7];

                    shift = (gain-1024) >> 3;

                }



                if (shift < -31) {

                    // Nothing to do

                } else if (shift < 0) {

                    shift = -shift;

                    round = 1 << (shift - 1);



                    for (group = 0; group < ics->group_len[g]; group++) {

                        for (k = offsets[i]; k < offsets[i + 1]; k++) {

                            tmp = (int)(((int64_t)src[group * 128 + k] * c + \

                                       (int64_t)0x1000000000) >> 37);

                            dest[group * 128 + k] += (tmp + round) >> shift;

                        }

                    }

                }

                else {

                    for (group = 0; group < ics->group_len[g]; group++) {

                        for (k = offsets[i]; k < offsets[i + 1]; k++) {

                            tmp = (int)(((int64_t)src[group * 128 + k] * c + \

                                        (int64_t)0x1000000000) >> 37);

                            dest[group * 128 + k] += tmp << shift;

                        }

                    }

                }

            }

        }

        dest += ics->group_len[g] * 128;

        src  += ics->group_len[g] * 128;

    }

}

static void apply_dependent_coupling(AACContext * ac, SingleChannelElement * target, ChannelElement * cce, int index) {

    IndividualChannelStream * ics = &cce->ch[0].ics;

    const uint16_t * offsets = ics->swb_offset;

    float * dest = target->coeffs;

    const float * src = cce->ch[0].coeffs;

    int g, i, group, k, idx = 0;

    if(ac->m4ac.object_type == AOT_AAC_LTP) {

        av_log(ac->avccontext, AV_LOG_ERROR,

               "Dependent coupling is not supported together with LTP\n");

        return;

    }

    for (g = 0; g < ics->num_window_groups; g++) {

        for (i = 0; i < ics->max_sfb; i++, idx++) {

            if (cce->ch[0].band_type[idx] != ZERO_BT) {

                for (group = 0; group < ics->group_len[g]; group++) {

                    for (k = offsets[i]; k < offsets[i+1]; k++) {

                        // XXX dsputil-ize

                        dest[group*128+k] += cce->coup.gain[index][idx] * src[group*128+k];

                    }

                }

            }

        }

        dest += ics->group_len[g]*128;

        src  += ics->group_len[g]*128;

    }

}

static void sbr_qmf_synthesis(DSPContext *dsp, FFTContext *mdct,

                              float *out, float X[2][38][64],

                              float mdct_buf[2][64],

                              float *v0, int *v_off, const unsigned int div)

{

    int i, n;

    const float *sbr_qmf_window = div ? sbr_qmf_window_ds : sbr_qmf_window_us;

    float *v;

    for (i = 0; i < 32; i++) {

        if (*v_off == 0) {

            int saved_samples = (1280 - 128) >> div;

            memcpy(&v0[SBR_SYNTHESIS_BUF_SIZE - saved_samples], v0, saved_samples * sizeof(float));

            *v_off = SBR_SYNTHESIS_BUF_SIZE - saved_samples - (128 >> div);

        } else {

            *v_off -= 128 >> div;

        }

        v = v0 + *v_off;

        if (div) {

            for (n = 0; n < 32; n++) {

                X[0][i][   n] = -X[0][i][n];

                X[0][i][32+n] =  X[1][i][31-n];

            }

            mdct->imdct_half(mdct, mdct_buf[0], X[0][i]);

            for (n = 0; n < 32; n++) {

                v[     n] =  mdct_buf[0][63 - 2*n];

                v[63 - n] = -mdct_buf[0][62 - 2*n];

            }

        } else {

            for (n = 1; n < 64; n+=2) {

                X[1][i][n] = -X[1][i][n];

            }

            mdct->imdct_half(mdct, mdct_buf[0], X[0][i]);

            mdct->imdct_half(mdct, mdct_buf[1], X[1][i]);

            for (n = 0; n < 64; n++) {

                v[      n] = -mdct_buf[0][63 -   n] + mdct_buf[1][  n    ];

                v[127 - n] =  mdct_buf[0][63 -   n] + mdct_buf[1][  n    ];

            }

        }

        dsp->vector_fmul_add(out, v                , sbr_qmf_window               , zero64, 64 >> div);

        dsp->vector_fmul_add(out, v + ( 192 >> div), sbr_qmf_window + ( 64 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + ( 256 >> div), sbr_qmf_window + (128 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + ( 448 >> div), sbr_qmf_window + (192 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + ( 512 >> div), sbr_qmf_window + (256 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + ( 704 >> div), sbr_qmf_window + (320 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + ( 768 >> div), sbr_qmf_window + (384 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + ( 960 >> div), sbr_qmf_window + (448 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + (1024 >> div), sbr_qmf_window + (512 >> div), out   , 64 >> div);

        dsp->vector_fmul_add(out, v + (1216 >> div), sbr_qmf_window + (576 >> div), out   , 64 >> div);

        out += 64 >> div;

    }

}

