static const uint8_t *parse_opus_ts_header(const uint8_t *start, int *payload_len, int buf_len)

{

    const uint8_t *buf = start + 1;

    int start_trim_flag, end_trim_flag, control_extension_flag, control_extension_length;

    uint8_t flags;



    GetByteContext gb;

    bytestream2_init(&gb, buf, buf_len);



    flags = bytestream2_get_byte(&gb);

    start_trim_flag        = (flags >> 4) & 1;

    end_trim_flag          = (flags >> 3) & 1;

    control_extension_flag = (flags >> 2) & 1;



    *payload_len = 0;

    while (bytestream2_peek_byte(&gb) == 0xff)

        *payload_len += bytestream2_get_byte(&gb);



    *payload_len += bytestream2_get_byte(&gb);



    if (start_trim_flag)

        bytestream2_skip(&gb, 2);

    if (end_trim_flag)

        bytestream2_skip(&gb, 2);

    if (control_extension_flag) {

        control_extension_length = bytestream2_get_byte(&gb);

        bytestream2_skip(&gb, control_extension_length);

    }



    return buf + bytestream2_tell(&gb);

}

static void decode_interframe_v4a(AVCodecContext *avctx, uint8_t *src,

                                  uint32_t size)

{

    Hnm4VideoContext *hnm = avctx->priv_data;

    GetByteContext gb;

    uint32_t writeoffset = 0, offset;

    uint8_t tag, count, previous, delta;



    bytestream2_init(&gb, src, size);



    while (bytestream2_tell(&gb) < size) {

        count = bytestream2_peek_byte(&gb) & 0x3F;

        if (count == 0) {

            tag = bytestream2_get_byte(&gb) & 0xC0;

            tag = tag >> 6;

            if (tag == 0) {

                writeoffset += bytestream2_get_byte(&gb);

            } else if (tag == 1) {

                if (writeoffset + hnm->width >= hnm->width * hnm->height) {

                    av_log(avctx, AV_LOG_ERROR, "writeoffset out of bounds\n");

                    break;

                }

                hnm->current[writeoffset]              = bytestream2_get_byte(&gb);

                hnm->current[writeoffset + hnm->width] = bytestream2_get_byte(&gb);

                writeoffset++;

            } else if (tag == 2) {

                writeoffset += hnm->width;

            } else if (tag == 3) {

                break;

            }

            if (writeoffset > hnm->width * hnm->height) {

                av_log(avctx, AV_LOG_ERROR, "writeoffset out of bounds\n");

                break;

            }

        } else {

            delta    = bytestream2_peek_byte(&gb) & 0x80;

            previous = bytestream2_peek_byte(&gb) & 0x40;

            bytestream2_skip(&gb, 1);



            offset  = writeoffset;

            offset += bytestream2_get_le16(&gb);



            if (delta)

                offset -= 0x10000;



            if (offset + hnm->width + count >= hnm->width * hnm->height) {

                av_log(avctx, AV_LOG_ERROR, "Attempting to read out of bounds\n");

                break;

            } else if (writeoffset + hnm->width + count >= hnm->width * hnm->height) {

                av_log(avctx, AV_LOG_ERROR, "Attempting to write out of bounds\n");

                break;

            }



            if (previous) {

                while (count > 0) {

                    hnm->current[writeoffset]              = hnm->previous[offset];

                    hnm->current[writeoffset + hnm->width] = hnm->previous[offset + hnm->width];

                    writeoffset++;

                    offset++;

                    count--;

                }

            } else {

                while (count > 0) {

                    hnm->current[writeoffset]              = hnm->current[offset];

                    hnm->current[writeoffset + hnm->width] = hnm->current[offset + hnm->width];

                    writeoffset++;

                    offset++;

                    count--;

                }

            }

        }

    }

}

static int decode_type2(GetByteContext *gb, PutByteContext *pb)

{

    unsigned repeat = 0, first = 1, opcode;

    int i, len, pos;



    while (bytestream2_get_bytes_left(gb) > 0) {

        GetByteContext gbc;



        while (bytestream2_get_bytes_left(gb) > 0) {

            if (first) {

                first = 0;

                if (bytestream2_peek_byte(gb) > 17) {

                    len = bytestream2_get_byte(gb) - 17;

                    if (len < 4) {

                        do {

                            bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                            --len;

                        } while (len);

                        opcode = bytestream2_peek_byte(gb);

                        continue;

                    } else {

                        do {

                            bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                            --len;

                        } while (len);

                        opcode = bytestream2_peek_byte(gb);

                        if (opcode < 0x10) {

                            bytestream2_skip(gb, 1);

                            pos = - (opcode >> 2) - 4 * bytestream2_get_byte(gb) - 2049;



                            bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

                            bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);



                            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                            len = opcode & 3;

                            if (!len) {

                                repeat = 1;

                            } else {

                                do {

                                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                                    --len;

                                } while (len);

                                opcode = bytestream2_peek_byte(gb);

                            }

                            continue;

                        }

                    }

                    repeat = 0;

                }

                repeat = 1;

            }

            if (repeat) {

                repeat = 0;

                opcode = bytestream2_peek_byte(gb);

                if (opcode < 0x10) {

                    bytestream2_skip(gb, 1);

                    if (!opcode) {

                        if (!bytestream2_peek_byte(gb)) {

                            do {

                                bytestream2_skip(gb, 1);

                                opcode += 255;

                            } while (!bytestream2_peek_byte(gb) && bytestream2_get_bytes_left(gb) > 0);

                        }

                        opcode += bytestream2_get_byte(gb) + 15;

                    }

                    bytestream2_put_le32(pb, bytestream2_get_le32(gb));

                    for (i = opcode - 1; i > 0; --i)

                        bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                    opcode = bytestream2_peek_byte(gb);

                    if (opcode < 0x10) {

                        bytestream2_skip(gb, 1);

                        pos = - (opcode >> 2) - 4 * bytestream2_get_byte(gb) - 2049;



                        bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

                        bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);



                        bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                        bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                        bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                        len = opcode & 3;

                        if (!len) {

                            repeat = 1;

                        } else {

                            do {

                                bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                                --len;

                            } while (len);

                            opcode = bytestream2_peek_byte(gb);

                        }

                        continue;

                    }

                }

            }



            if (opcode >= 0x40) {

                bytestream2_skip(gb, 1);

                pos = - ((opcode >> 2) & 7) - 1 - 8 * bytestream2_get_byte(gb);

                len = (opcode >> 5) - 1;



                bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

                bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);



                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                do {

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    --len;

                } while (len);



                len = opcode & 3;



                if (!len) {

                    repeat = 1;

                } else {

                    do {

                        bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                        --len;

                    } while (len);

                    opcode = bytestream2_peek_byte(gb);

                }

                continue;

            } else if (opcode < 0x20) {

                break;

            }

            len = opcode & 0x1F;

            bytestream2_skip(gb, 1);

            if (!len) {

                if (!bytestream2_peek_byte(gb)) {

                    do {

                        bytestream2_skip(gb, 1);

                        len += 255;

                    } while (!bytestream2_peek_byte(gb) && bytestream2_get_bytes_left(gb) > 0);

                }

                len += bytestream2_get_byte(gb) + 31;

            }

            i = bytestream2_get_le16(gb);

            pos = - (i >> 2) - 1;



            bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

            bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);



            if (len < 6 || bytestream2_tell_p(pb) - bytestream2_tell(&gbc) < 4) {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                do {

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                    --len;

                } while (len);

            } else {

                bytestream2_put_le32(pb, bytestream2_get_le32(&gbc));

                for (len = len - 2; len; --len)

                    bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            }

            len = i & 3;

            if (!len) {

                repeat = 1;

            } else {

                do {

                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                    --len;

                } while (len);

                opcode = bytestream2_peek_byte(gb);

            }

        }

        bytestream2_skip(gb, 1);

        if (opcode < 0x10) {

            pos = -(opcode >> 2) - 1 - 4 * bytestream2_get_byte(gb);



            bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

            bytestream2_seek(&gbc, bytestream2_tell_p(pb) + pos, SEEK_SET);



            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            len = opcode & 3;

            if (!len) {

                repeat = 1;

            } else {

                do {

                    bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                    --len;

                } while (len);

                opcode = bytestream2_peek_byte(gb);

            }

            continue;

        }

        len = opcode & 7;

        if (!len) {

            if (!bytestream2_peek_byte(gb)) {

                do {

                    bytestream2_skip(gb, 1);

                    len += 255;

                } while (!bytestream2_peek_byte(gb) && bytestream2_get_bytes_left(gb) > 0);

            }

            len += bytestream2_get_byte(gb) + 7;

        }

        i = bytestream2_get_le16(gb);

        pos = bytestream2_tell_p(pb) - 2048 * (opcode & 8);

        pos = pos - (i >> 2);

        if (pos == bytestream2_tell_p(pb))

            break;



        pos = pos - 0x4000;

        bytestream2_init(&gbc, pb->buffer_start, pb->buffer_end - pb->buffer_start);

        bytestream2_seek(&gbc, pos, SEEK_SET);



        if (len < 6 || bytestream2_tell_p(pb) - bytestream2_tell(&gbc) < 4) {

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

                --len;

            } while (len);

        } else {

            bytestream2_put_le32(pb, bytestream2_get_le32(&gbc));

            for (len = len - 2; len; --len)

                bytestream2_put_byte(pb, bytestream2_get_byte(&gbc));

        }



        len = i & 3;

        if (!len) {

            repeat = 1;

        } else {

            do {

                bytestream2_put_byte(pb, bytestream2_get_byte(gb));

                --len;

            } while (len);

            opcode = bytestream2_peek_byte(gb);

        }

    }



    return 0;

}

static int msrle_decode_pal4(AVCodecContext *avctx, AVFrame *pic,

                             GetByteContext *gb)

{

    unsigned char rle_code;

    unsigned char extra_byte, odd_pixel;

    unsigned char stream_byte;

    int pixel_ptr = 0;

    int line = avctx->height - 1;

    int i;



    while (line >= 0 && pixel_ptr <= avctx->width) {

        if (bytestream2_get_bytes_left(gb) <= 0) {

            av_log(avctx, AV_LOG_ERROR,

                   "MS RLE: bytestream overrun, %dx%d left\n",

                   avctx->width - pixel_ptr, line);

            return AVERROR_INVALIDDATA;

        }

        rle_code = stream_byte = bytestream2_get_byteu(gb);

        if (rle_code == 0) {

            /* fetch the next byte to see how to handle escape code */

            stream_byte = bytestream2_get_byte(gb);

            if (stream_byte == 0) {

                /* line is done, goto the next one */

                line--;

                pixel_ptr = 0;

            } else if (stream_byte == 1) {

                /* decode is done */

                return 0;

            } else if (stream_byte == 2) {

                /* reposition frame decode coordinates */

                stream_byte = bytestream2_get_byte(gb);

                pixel_ptr += stream_byte;

                stream_byte = bytestream2_get_byte(gb);

                avpriv_request_sample(avctx, "Unused stream byte %X", stream_byte);

            } else {

                // copy pixels from encoded stream

                odd_pixel =  stream_byte & 1;

                rle_code = (stream_byte + 1) / 2;

                extra_byte = rle_code & 0x01;

                if (pixel_ptr + 2*rle_code - odd_pixel > avctx->width ||

                    bytestream2_get_bytes_left(gb) < rle_code) {

                    av_log(avctx, AV_LOG_ERROR,

                           "MS RLE: frame/stream ptr just went out of bounds (copy)\n");

                    return AVERROR_INVALIDDATA;

                }



                for (i = 0; i < rle_code; i++) {

                    if (pixel_ptr >= avctx->width)

                        break;

                    stream_byte = bytestream2_get_byteu(gb);

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte >> 4;

                    pixel_ptr++;

                    if (i + 1 == rle_code && odd_pixel)

                        break;

                    if (pixel_ptr >= avctx->width)

                        break;

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte & 0x0F;

                    pixel_ptr++;

                }



                // if the RLE code is odd, skip a byte in the stream

                if (extra_byte)

                    bytestream2_skip(gb, 1);

            }

        } else {

            // decode a run of data

            if (pixel_ptr + rle_code > avctx->width + 1) {

                av_log(avctx, AV_LOG_ERROR,

                       "MS RLE: frame ptr just went out of bounds (run) %d %d %d\n", pixel_ptr, rle_code, avctx->width);

                return AVERROR_INVALIDDATA;

            }

            stream_byte = bytestream2_get_byte(gb);

            for (i = 0; i < rle_code; i++) {

                if (pixel_ptr >= avctx->width)

                    break;

                if ((i & 1) == 0)

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte >> 4;

                else

                    pic->data[0][line * pic->linesize[0] + pixel_ptr] = stream_byte & 0x0F;

                pixel_ptr++;

            }

        }

    }



    /* one last sanity check on the way out */

    if (bytestream2_get_bytes_left(gb)) {

        av_log(avctx, AV_LOG_ERROR,

               "MS RLE: ended frame decode with %d bytes left over\n",

               bytestream2_get_bytes_left(gb));

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static void setup_frame(int sig, struct target_sigaction *ka,

			target_sigset_t *set, CPUX86State *env)

{

	abi_ulong frame_addr;

	struct sigframe *frame;

	int i, err = 0;



	frame_addr = get_sigframe(ka, env, sizeof(*frame));



	if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0))

		goto give_sigsegv;



    __put_user(current_exec_domain_sig(sig),

               &frame->sig);

	if (err)

		goto give_sigsegv;



	setup_sigcontext(&frame->sc, &frame->fpstate, env, set->sig[0],

                         frame_addr + offsetof(struct sigframe, fpstate));

	if (err)

		goto give_sigsegv;



        for(i = 1; i < TARGET_NSIG_WORDS; i++) {

            if (__put_user(set->sig[i], &frame->extramask[i - 1]))

                goto give_sigsegv;

        }



	/* Set up to return from userspace.  If provided, use a stub

	   already in userspace.  */

	if (ka->sa_flags & TARGET_SA_RESTORER) {

        __put_user(ka->sa_restorer, &frame->pretcode);

	} else {

                uint16_t val16;

                abi_ulong retcode_addr;

                retcode_addr = frame_addr + offsetof(struct sigframe, retcode);

        __put_user(retcode_addr, &frame->pretcode);

		/* This is popl %eax ; movl $,%eax ; int $0x80 */

                val16 = 0xb858;

        __put_user(val16, (uint16_t *)(frame->retcode+0));

        __put_user(TARGET_NR_sigreturn, (int *)(frame->retcode+2));

                val16 = 0x80cd;

        __put_user(val16, (uint16_t *)(frame->retcode+6));

	}



	if (err)

		goto give_sigsegv;



	/* Set up registers for signal handler */

	env->regs[R_ESP] = frame_addr;

	env->eip = ka->_sa_handler;



        cpu_x86_load_seg(env, R_DS, __USER_DS);

        cpu_x86_load_seg(env, R_ES, __USER_DS);

        cpu_x86_load_seg(env, R_SS, __USER_DS);

        cpu_x86_load_seg(env, R_CS, __USER_CS);

	env->eflags &= ~TF_MASK;



	unlock_user_struct(frame, frame_addr, 1);



	return;



give_sigsegv:

	unlock_user_struct(frame, frame_addr, 1);

	if (sig == TARGET_SIGSEGV)

		ka->_sa_handler = TARGET_SIG_DFL;

	force_sig(TARGET_SIGSEGV /* , current */);

}

static void setup_frame(int sig, struct target_sigaction *ka,

                        target_sigset_t *set, CPUMBState *env)

{

    struct target_signal_frame *frame;

    abi_ulong frame_addr;

    int err = 0;

    int i;



    frame_addr = get_sigframe(ka, env, sizeof *frame);

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0))

        goto badframe;



    /* Save the mask.  */

    __put_user(set->sig[0], &frame->uc.tuc_mcontext.oldmask);

    if (err)

        goto badframe;



    for(i = 1; i < TARGET_NSIG_WORDS; i++) {

        if (__put_user(set->sig[i], &frame->extramask[i - 1]))

            goto badframe;

    }



    setup_sigcontext(&frame->uc.tuc_mcontext, env);



    /* Set up to return from userspace. If provided, use a stub

       already in userspace. */

    /* minus 8 is offset to cater for "rtsd r15,8" offset */

    if (ka->sa_flags & TARGET_SA_RESTORER) {

        env->regs[15] = ((unsigned long)ka->sa_restorer)-8;

    } else {

        uint32_t t;

        /* Note, these encodings are _big endian_! */

        /* addi r12, r0, __NR_sigreturn */

        t = 0x31800000UL | TARGET_NR_sigreturn;

        __put_user(t, frame->tramp + 0);

        /* brki r14, 0x8 */

        t = 0xb9cc0008UL;

        __put_user(t, frame->tramp + 1);



        /* Return from sighandler will jump to the tramp.

           Negative 8 offset because return is rtsd r15, 8 */

        env->regs[15] = ((unsigned long)frame->tramp) - 8;

    }



    if (err)

        goto badframe;



    /* Set up registers for signal handler */

    env->regs[1] = frame_addr;

    /* Signal handler args: */

    env->regs[5] = sig; /* Arg 0: signum */

    env->regs[6] = 0;

    /* arg 1: sigcontext */

    env->regs[7] = frame_addr += offsetof(typeof(*frame), uc);



    /* Offset of 4 to handle microblaze rtid r14, 0 */

    env->sregs[SR_PC] = (unsigned long)ka->_sa_handler;



    unlock_user_struct(frame, frame_addr, 1);

    return;

  badframe:

    unlock_user_struct(frame, frame_addr, 1);

    force_sig(TARGET_SIGSEGV);

}

static void setup_rt_frame(int sig, struct target_sigaction *ka,

                           target_siginfo_t *info,

                           target_sigset_t *set, CPUSH4State *regs)

{

    struct target_rt_sigframe *frame;

    abi_ulong frame_addr;

    int i;

    int err = 0;

    int signal;



    frame_addr = get_sigframe(ka, regs->gregs[15], sizeof(*frame));

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0))

	goto give_sigsegv;



    signal = current_exec_domain_sig(sig);



    err |= copy_siginfo_to_user(&frame->info, info);



    /* Create the ucontext.  */

    __put_user(0, &frame->uc.tuc_flags);

    __put_user(0, (unsigned long *)&frame->uc.tuc_link);

    __put_user((unsigned long)target_sigaltstack_used.ss_sp,

               &frame->uc.tuc_stack.ss_sp);

    __put_user(sas_ss_flags(regs->gregs[15]),

               &frame->uc.tuc_stack.ss_flags);

    __put_user(target_sigaltstack_used.ss_size,

               &frame->uc.tuc_stack.ss_size);

    setup_sigcontext(&frame->uc.tuc_mcontext,

			    regs, set->sig[0]);

    for(i = 0; i < TARGET_NSIG_WORDS; i++) {

        __put_user(set->sig[i], &frame->uc.tuc_sigmask.sig[i]);

    }



    /* Set up to return from userspace.  If provided, use a stub

       already in userspace.  */

    if (ka->sa_flags & TARGET_SA_RESTORER) {

        regs->pr = (unsigned long) ka->sa_restorer;

    } else {

        /* Generate return code (system call to sigreturn) */

        __put_user(MOVW(2), &frame->retcode[0]);

        __put_user(TRAP_NOARG, &frame->retcode[1]);

        __put_user((TARGET_NR_rt_sigreturn), &frame->retcode[2]);

        regs->pr = (unsigned long) frame->retcode;

    }



    if (err)

        goto give_sigsegv;



    /* Set up registers for signal handler */

    regs->gregs[15] = frame_addr;

    regs->gregs[4] = signal; /* Arg for signal handler */

    regs->gregs[5] = frame_addr + offsetof(typeof(*frame), info);

    regs->gregs[6] = frame_addr + offsetof(typeof(*frame), uc);

    regs->pc = (unsigned long) ka->_sa_handler;



    unlock_user_struct(frame, frame_addr, 1);

    return;



give_sigsegv:

    unlock_user_struct(frame, frame_addr, 1);

    force_sig(TARGET_SIGSEGV);

}

static void setup_frame(int sig, struct target_sigaction *ka,

                        target_sigset_t *set, CPUPPCState *env)

{

    struct target_sigframe *frame;

    struct target_sigcontext *sc;

    target_ulong frame_addr, newsp;

    int err = 0;

    int signal;



    frame_addr = get_sigframe(ka, env, sizeof(*frame));

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 1))

        goto sigsegv;

    sc = &frame->sctx;



    signal = current_exec_domain_sig(sig);



    __put_user(ka->_sa_handler, &sc->handler);

    __put_user(set->sig[0], &sc->oldmask);

#if defined(TARGET_PPC64)

    __put_user(set->sig[0] >> 32, &sc->_unused[3]);

#else

    __put_user(set->sig[1], &sc->_unused[3]);

#endif

    __put_user(h2g(&frame->mctx), &sc->regs);

    __put_user(sig, &sc->signal);



    /* Save user regs.  */

    err |= save_user_regs(env, &frame->mctx, TARGET_NR_sigreturn);



    /* The kernel checks for the presence of a VDSO here.  We don't

       emulate a vdso, so use a sigreturn system call.  */

    env->lr = (target_ulong) h2g(frame->mctx.tramp);



    /* Turn off all fp exceptions.  */

    env->fpscr = 0;



    /* Create a stack frame for the caller of the handler.  */

    newsp = frame_addr - SIGNAL_FRAMESIZE;

    err |= put_user(env->gpr[1], newsp, target_ulong);



    if (err)

        goto sigsegv;



    /* Set up registers for signal handler.  */

    env->gpr[1] = newsp;

    env->gpr[3] = signal;

    env->gpr[4] = frame_addr + offsetof(struct target_sigframe, sctx);

    env->nip = (target_ulong) ka->_sa_handler;

    /* Signal handlers are entered in big-endian mode.  */

    env->msr &= ~MSR_LE;



    unlock_user_struct(frame, frame_addr, 1);

    return;



sigsegv:

    unlock_user_struct(frame, frame_addr, 1);

    qemu_log("segfaulting from setup_frame\n");

    force_sig(TARGET_SIGSEGV);

}

