        }

    }

}

static int mkv_write_chapters(AVFormatContext *s)

{

    MatroskaMuxContext *mkv = s->priv_data;

    AVIOContext *pb = s->pb;

    ebml_master chapters, editionentry;

    AVRational scale = {1, 1E9};

    int i, ret;



    if (!s->nb_chapters || mkv->wrote_chapters)

        return 0;



    ret = mkv_add_seekhead_entry(mkv->main_seekhead, MATROSKA_ID_CHAPTERS, avio_tell(pb));

    if (ret < 0) return ret;



    chapters     = start_ebml_master(pb, MATROSKA_ID_CHAPTERS    , 0);

    editionentry = start_ebml_master(pb, MATROSKA_ID_EDITIONENTRY, 0);

    put_ebml_uint(pb, MATROSKA_ID_EDITIONFLAGDEFAULT, 1);

    put_ebml_uint(pb, MATROSKA_ID_EDITIONFLAGHIDDEN , 0);

    for (i = 0; i < s->nb_chapters; i++) {

        ebml_master chapteratom, chapterdisplay;

        AVChapter *c     = s->chapters[i];

        int chapterstart = av_rescale_q(c->start, c->time_base, scale);

        int chapterend   = av_rescale_q(c->end,   c->time_base, scale);

        AVDictionaryEntry *t = NULL;

        if (chapterstart < 0 || chapterstart > chapterend)

            return AVERROR_INVALIDDATA;



        chapteratom = start_ebml_master(pb, MATROSKA_ID_CHAPTERATOM, 0);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERUID, c->id + mkv->chapter_id_offset);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERTIMESTART, chapterstart);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERTIMEEND, chapterend);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERFLAGHIDDEN , 0);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERFLAGENABLED, 1);

        if ((t = av_dict_get(c->metadata, "title", NULL, 0))) {

            chapterdisplay = start_ebml_master(pb, MATROSKA_ID_CHAPTERDISPLAY, 0);

            put_ebml_string(pb, MATROSKA_ID_CHAPSTRING, t->value);

            put_ebml_string(pb, MATROSKA_ID_CHAPLANG  , "und");

            end_ebml_master(pb, chapterdisplay);

        }

        end_ebml_master(pb, chapteratom);

    }

    end_ebml_master(pb, editionentry);

    end_ebml_master(pb, chapters);



    mkv->wrote_chapters = 1;

    return 0;

}

static int write_packet(AVFormatContext *s, AVPacket *pkt)

{

    WVMuxContext *wc = s->priv_data;

    AVCodecContext *codec = s->streams[0]->codec;

    AVIOContext *pb = s->pb;

    uint64_t size;

    uint32_t flags;

    uint32_t left = pkt->size;

    uint8_t *ptr = pkt->data;

    int off = codec->channels > 2 ? 4 : 0;



    /* FIXME: Simplify decoder/demuxer so bellow code can support midstream

     *        change of stream parameters */

    wc->duration += pkt->duration;

    ffio_wfourcc(pb, "wvpk");

    if (off) {

        size = AV_RL32(pkt->data);

        if (size <= 12)

            return AVERROR_INVALIDDATA;

        size -= 12;

    } else {

        size = pkt->size;

    }



    if (size + off > left)

        return AVERROR_INVALIDDATA;



    avio_wl32(pb, size + 12);

    avio_wl16(pb, 0x410);

    avio_w8(pb, 0);

    avio_w8(pb, 0);

    avio_wl32(pb, -1);

    avio_wl32(pb, pkt->pts);

    ptr += off; left -= off;

    flags = AV_RL32(ptr + 4);

    avio_write(pb, ptr, size);

    ptr += size; left -= size;



    while (!(flags & WV_END_BLOCK) &&

            (left >= 4 + WV_EXTRA_SIZE)) {

        ffio_wfourcc(pb, "wvpk");

        size = AV_RL32(ptr);

        ptr += 4; left -= 4;

        if (size < 24 || size - 24 > left)

            return AVERROR_INVALIDDATA;

        avio_wl32(pb, size);

        avio_wl16(pb, 0x410);

        avio_w8(pb, 0);

        avio_w8(pb, 0);

        avio_wl32(pb, -1);

        avio_wl32(pb, pkt->pts);

        flags = AV_RL32(ptr + 4);

        avio_write(pb, ptr, WV_EXTRA_SIZE);

        ptr += WV_EXTRA_SIZE; left -= WV_EXTRA_SIZE;

        avio_write(pb, ptr, size - 24);

        ptr += size - 24; left -= size - 24;

    }



    return 0;

}

