static int dfa_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    DfaContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    const uint8_t *buf_end = avpkt->data + avpkt->size;

    const uint8_t *tmp_buf;

    uint32_t chunk_type, chunk_size;

    uint8_t *dst;

    int ret;

    int i, pal_elems;



    if (s->pic.data[0])

        avctx->release_buffer(avctx, &s->pic);



    if ((ret = avctx->get_buffer(avctx, &s->pic))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    while (buf < buf_end) {

        chunk_size = AV_RL32(buf + 4);

        chunk_type = AV_RL32(buf + 8);

        buf += 12;

        if (buf_end - buf < chunk_size) {

            av_log(avctx, AV_LOG_ERROR, "Chunk size is too big (%d bytes)\n", chunk_size);

            return -1;

        }

        if (!chunk_type)

            break;

        if (chunk_type == 1) {

            pal_elems = FFMIN(chunk_size / 3, 256);

            tmp_buf = buf;

            for (i = 0; i < pal_elems; i++) {

                s->pal[i] = bytestream_get_be24(&tmp_buf) << 2;

                s->pal[i] |= (s->pal[i] >> 6) & 0x333;

            }

            s->pic.palette_has_changed = 1;

        } else if (chunk_type <= 9) {

            if (decoder[chunk_type - 2](s->frame_buf, avctx->width, avctx->height,

                                        buf, buf + chunk_size)) {

                av_log(avctx, AV_LOG_ERROR, "Error decoding %s chunk\n",

                       chunk_name[chunk_type - 2]);

                return -1;

            }

        } else {

            av_log(avctx, AV_LOG_WARNING, "Ignoring unknown chunk type %d\n",

                   chunk_type);

        }

        buf += chunk_size;

    }



    buf = s->frame_buf;

    dst = s->pic.data[0];

    for (i = 0; i < avctx->height; i++) {

        memcpy(dst, buf, avctx->width);

        dst += s->pic.linesize[0];

        buf += avctx->width;

    }

    memcpy(s->pic.data[1], s->pal, sizeof(s->pal));



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->pic;



    return avpkt->size;

}

static int tgq_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt){

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_start = buf;

    const uint8_t *buf_end = buf + buf_size;

    TgqContext *s = avctx->priv_data;

    int x,y;



    int big_endian = AV_RL32(&buf[4]) > 0x000FFFFF;

    buf += 8;



    if(8>buf_end-buf) {

        av_log(avctx, AV_LOG_WARNING, "truncated header\n");

        return -1;

    }

    s->width  = big_endian ? AV_RB16(&buf[0]) : AV_RL16(&buf[0]);

    s->height = big_endian ? AV_RB16(&buf[2]) : AV_RL16(&buf[2]);



    if (s->avctx->width!=s->width || s->avctx->height!=s->height) {

        avcodec_set_dimensions(s->avctx, s->width, s->height);

        if (s->frame.data[0])

            avctx->release_buffer(avctx, &s->frame);

    }

    tgq_calculate_qtable(s, buf[4]);

    buf += 8;



    if (!s->frame.data[0]) {

        s->frame.key_frame = 1;

        s->frame.pict_type = AV_PICTURE_TYPE_I;

        s->frame.buffer_hints = FF_BUFFER_HINTS_VALID;

        if (avctx->get_buffer(avctx, &s->frame)) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }

    }



    for (y=0; y<(avctx->height+15)/16; y++)

    for (x=0; x<(avctx->width+15)/16; x++)

        tgq_decode_mb(s, y, x, &buf, buf_end);



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->frame;



    return buf-buf_start;

}

static int decode_frame_byterun1(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    IffContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    unsigned buf_size = avpkt->size;

    const uint8_t *buf_end = buf+buf_size;

    unsigned y, plane, x;



    if (avctx->reget_buffer(avctx, &s->frame) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    for(y = 0; y < avctx->height ; y++ ) {

        uint8_t *row = &s->frame.data[0][ y*s->frame.linesize[0] ];

        if (avctx->codec_tag == MKTAG('I','L','B','M')) { //interleaved

            memset(row, 0, avctx->pix_fmt == PIX_FMT_PAL8 ? avctx->width : (avctx->width * 4));

            for (plane = 0; plane < avctx->bits_per_coded_sample; plane++) {

                for(x = 0; x < s->planesize && buf < buf_end; ) {

                    int8_t value = *buf++;

                    unsigned length;

                    if (value >= 0) {

                        length = value + 1;

                        memcpy(s->planebuf + x, buf, FFMIN3(length, s->planesize - x, buf_end - buf));

                        buf += length;

                    } else if (value > -128) {

                        length = -value + 1;

                        memset(s->planebuf + x, *buf++, FFMIN(length, s->planesize - x));

                    } else { //noop

                        continue;

                    }

                    x += length;

                }

                if (avctx->pix_fmt == PIX_FMT_PAL8) {

                    decodeplane8(row, s->planebuf, s->planesize, avctx->bits_per_coded_sample, plane);

                } else { //PIX_FMT_BGR32

                    decodeplane32((uint32_t *) row, s->planebuf, s->planesize, avctx->bits_per_coded_sample, plane);

                }

            }

        } else {

            for(x = 0; x < avctx->width && buf < buf_end; ) {

                int8_t value = *buf++;

                unsigned length;

                if (value >= 0) {

                    length = value + 1;

                    memcpy(row + x, buf, FFMIN3(length, buf_end - buf, avctx->width - x));

                    buf += length;

                } else if (value > -128) {

                    length = -value + 1;

                    memset(row + x, *buf++, FFMIN(length, avctx->width - x));

                } else { //noop

                    continue;

                }

                x += length;

            }

        }

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->frame;

    return buf_size;

}

static int decode_frame_ilbm(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    IffContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_end = buf+buf_size;

    int y, plane;



    if (avctx->reget_buffer(avctx, &s->frame) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    for(y = 0; y < avctx->height; y++ ) {

        uint8_t *row = &s->frame.data[0][ y*s->frame.linesize[0] ];

        memset(row, 0, avctx->pix_fmt == PIX_FMT_PAL8 ? avctx->width : (avctx->width * 4));

        for (plane = 0; plane < avctx->bits_per_coded_sample && buf < buf_end; plane++) {

            if (avctx->pix_fmt == PIX_FMT_PAL8) {

                decodeplane8(row, buf, FFMIN(s->planesize, buf_end - buf), avctx->bits_per_coded_sample, plane);

            } else { // PIX_FMT_BGR32

                decodeplane32(row, buf, FFMIN(s->planesize, buf_end - buf), avctx->bits_per_coded_sample, plane);

            }

            buf += s->planesize;

        }

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->frame;

    return buf_size;

}

