static void virtio_serial_device_realize(DeviceState *dev, Error **errp)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(dev);

    VirtIOSerial *vser = VIRTIO_SERIAL(dev);

    uint32_t i, max_supported_ports;



    if (!vser->serial.max_virtserial_ports) {

        error_setg(errp, "Maximum number of serial ports not specified");

        return;

    }



    /* Each port takes 2 queues, and one pair is for the control queue */

    max_supported_ports = VIRTIO_QUEUE_MAX / 2 - 1;



    if (vser->serial.max_virtserial_ports > max_supported_ports) {

        error_setg(errp, "maximum ports supported: %u", max_supported_ports);

        return;

    }



    /* We don't support emergency write, skip it for now. */

    /* TODO: cleaner fix, depending on host features. */

    virtio_init(vdev, "virtio-serial", VIRTIO_ID_CONSOLE,

                offsetof(struct virtio_console_config, emerg_wr));



    /* Spawn a new virtio-serial bus on which the ports will ride as devices */

    qbus_create_inplace(&vser->bus, sizeof(vser->bus), TYPE_VIRTIO_SERIAL_BUS,

                        dev, vdev->bus_name);

    qbus_set_hotplug_handler(BUS(&vser->bus), DEVICE(vser), errp);

    vser->bus.vser = vser;

    QTAILQ_INIT(&vser->ports);



    vser->bus.max_nr_ports = vser->serial.max_virtserial_ports;

    vser->ivqs = g_malloc(vser->serial.max_virtserial_ports

                          * sizeof(VirtQueue *));

    vser->ovqs = g_malloc(vser->serial.max_virtserial_ports

                          * sizeof(VirtQueue *));



    /* Add a queue for host to guest transfers for port 0 (backward compat) */

    vser->ivqs[0] = virtio_add_queue(vdev, 128, handle_input);

    /* Add a queue for guest to host transfers for port 0 (backward compat) */

    vser->ovqs[0] = virtio_add_queue(vdev, 128, handle_output);



    /* TODO: host to guest notifications can get dropped

     * if the queue fills up. Implement queueing in host,

     * this might also make it possible to reduce the control

     * queue size: as guest preposts buffers there,

     * this will save 4Kbyte of guest memory per entry. */



    /* control queue: host to guest */

    vser->c_ivq = virtio_add_queue(vdev, 32, control_in);

    /* control queue: guest to host */

    vser->c_ovq = virtio_add_queue(vdev, 32, control_out);



    for (i = 1; i < vser->bus.max_nr_ports; i++) {

        /* Add a per-port queue for host to guest transfers */

        vser->ivqs[i] = virtio_add_queue(vdev, 128, handle_input);

        /* Add a per-per queue for guest to host transfers */

        vser->ovqs[i] = virtio_add_queue(vdev, 128, handle_output);

    }



    vser->ports_map = g_malloc0(((vser->serial.max_virtserial_ports + 31) / 32)

        * sizeof(vser->ports_map[0]));

    /*

     * Reserve location 0 for a console port for backward compat

     * (old kernel, new qemu)

     */

    mark_port_added(vser, 0);



    vser->post_load = NULL;



    QLIST_INSERT_HEAD(&vserdevices.devices, vser, next);

}

static size_t pdu_marshal(V9fsPDU *pdu, size_t offset, const char *fmt, ...)

{

    size_t old_offset = offset;

    va_list ap;

    int i;



    va_start(ap, fmt);

    for (i = 0; fmt[i]; i++) {

        switch (fmt[i]) {

        case 'b': {

            uint8_t val = va_arg(ap, int);

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'w': {

            uint16_t val;

            cpu_to_le16w(&val, va_arg(ap, int));

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'd': {

            uint32_t val;

            cpu_to_le32w(&val, va_arg(ap, uint32_t));

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'q': {

            uint64_t val;

            cpu_to_le64w(&val, va_arg(ap, uint64_t));

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'v': {

            struct iovec *iov = va_arg(ap, struct iovec *);

            int *iovcnt = va_arg(ap, int *);

            *iovcnt = pdu_copy_sg(pdu, offset, 1, iov);

            break;

        }

        case 's': {

            V9fsString *str = va_arg(ap, V9fsString *);

            offset += pdu_marshal(pdu, offset, "w", str->size);

            offset += pdu_pack(pdu, offset, str->data, str->size);

            break;

        }

        case 'Q': {

            V9fsQID *qidp = va_arg(ap, V9fsQID *);

            offset += pdu_marshal(pdu, offset, "bdq",

                        qidp->type, qidp->version, qidp->path);

            break;

        }

        case 'S': {

            V9fsStat *statp = va_arg(ap, V9fsStat *);

            offset += pdu_marshal(pdu, offset, "wwdQdddqsssssddd",

                        statp->size, statp->type, statp->dev,

                        &statp->qid, statp->mode, statp->atime,

                        statp->mtime, statp->length, &statp->name,

                        &statp->uid, &statp->gid, &statp->muid,

                        &statp->extension, statp->n_uid,

                        statp->n_gid, statp->n_muid);

            break;

        }

        case 'A': {

            V9fsStatDotl *statp = va_arg(ap, V9fsStatDotl *);

            offset += pdu_marshal(pdu, offset, "qQdddqqqqqqqqqqqqqqq",

                        statp->st_result_mask,

                        &statp->qid, statp->st_mode,

                        statp->st_uid, statp->st_gid,

                        statp->st_nlink, statp->st_rdev,

                        statp->st_size, statp->st_blksize, statp->st_blocks,

                        statp->st_atime_sec, statp->st_atime_nsec,

                        statp->st_mtime_sec, statp->st_mtime_nsec,

                        statp->st_ctime_sec, statp->st_ctime_nsec,

                        statp->st_btime_sec, statp->st_btime_nsec,

                        statp->st_gen, statp->st_data_version);

            break;

        }

        default:

            break;

        }

    }

    va_end(ap);



    return offset - old_offset;

}

int kvm_vcpu_ioctl(CPUState *env, int type, ...)

{

    int ret;

    void *arg;

    va_list ap;



    va_start(ap, type);

    arg = va_arg(ap, void *);

    va_end(ap);



    ret = ioctl(env->kvm_fd, type, arg);

    if (ret == -1)

        ret = -errno;



    return ret;

}

size_t v9fs_marshal(struct iovec *in_sg, int in_num, size_t offset,

                    int bswap, const char *fmt, ...)

{

    int i;

    va_list ap;

    size_t old_offset = offset;



    va_start(ap, fmt);

    for (i = 0; fmt[i]; i++) {

        switch (fmt[i]) {

        case 'b': {

            uint8_t val = va_arg(ap, int);

            offset += v9fs_pack(in_sg, in_num, offset, &val, sizeof(val));

            break;

        }

        case 'w': {

            uint16_t val;

            if (bswap) {

                cpu_to_le16w(&val, va_arg(ap, int));

            } else {

                val =  va_arg(ap, int);

            }

            offset += v9fs_pack(in_sg, in_num, offset, &val, sizeof(val));

            break;

        }

        case 'd': {

            uint32_t val;

            if (bswap) {

                cpu_to_le32w(&val, va_arg(ap, uint32_t));

            } else {

                val =  va_arg(ap, uint32_t);

            }

            offset += v9fs_pack(in_sg, in_num, offset, &val, sizeof(val));

            break;

        }

        case 'q': {

            uint64_t val;

            if (bswap) {

                cpu_to_le64w(&val, va_arg(ap, uint64_t));

            } else {

                val =  va_arg(ap, uint64_t);

            }

            offset += v9fs_pack(in_sg, in_num, offset, &val, sizeof(val));

            break;

        }

        case 's': {

            V9fsString *str = va_arg(ap, V9fsString *);

            offset += v9fs_marshal(in_sg, in_num, offset, bswap,

                            "w", str->size);

            offset += v9fs_pack(in_sg, in_num, offset, str->data, str->size);

            break;

        }

        case 'Q': {

            V9fsQID *qidp = va_arg(ap, V9fsQID *);

            offset += v9fs_marshal(in_sg, in_num, offset, bswap, "bdq",

                                   qidp->type, qidp->version, qidp->path);

            break;

        }

        case 'S': {

            V9fsStat *statp = va_arg(ap, V9fsStat *);

            offset += v9fs_marshal(in_sg, in_num, offset, bswap,

                                   "wwdQdddqsssssddd",

                                   statp->size, statp->type, statp->dev,

                                   &statp->qid, statp->mode, statp->atime,

                                   statp->mtime, statp->length, &statp->name,

                                   &statp->uid, &statp->gid, &statp->muid,

                                   &statp->extension, statp->n_uid,

                                   statp->n_gid, statp->n_muid);

            break;

        }

        case 'A': {

            V9fsStatDotl *statp = va_arg(ap, V9fsStatDotl *);

            offset += v9fs_marshal(in_sg, in_num, offset, bswap,

                                   "qQdddqqqqqqqqqqqqqqq",

                                   statp->st_result_mask,

                                   &statp->qid, statp->st_mode,

                                   statp->st_uid, statp->st_gid,

                                   statp->st_nlink, statp->st_rdev,

                                   statp->st_size, statp->st_blksize,

                                   statp->st_blocks, statp->st_atime_sec,

                                   statp->st_atime_nsec, statp->st_mtime_sec,

                                   statp->st_mtime_nsec, statp->st_ctime_sec,

                                   statp->st_ctime_nsec, statp->st_btime_sec,

                                   statp->st_btime_nsec, statp->st_gen,

                                   statp->st_data_version);

            break;

        }

        default:

            break;

        }

    }

    va_end(ap);



    return offset - old_offset;

}

size_t v9fs_unmarshal(struct iovec *out_sg, int out_num, size_t offset,

                      int bswap, const char *fmt, ...)

{

    int i;

    va_list ap;

    size_t old_offset = offset;



    va_start(ap, fmt);

    for (i = 0; fmt[i]; i++) {

        switch (fmt[i]) {

        case 'b': {

            uint8_t *valp = va_arg(ap, uint8_t *);

            offset += v9fs_unpack(valp, out_sg, out_num, offset, sizeof(*valp));

            break;

        }

        case 'w': {

            uint16_t val, *valp;

            valp = va_arg(ap, uint16_t *);

            offset += v9fs_unpack(&val, out_sg, out_num, offset, sizeof(val));

            if (bswap) {

                *valp = le16_to_cpu(val);

            } else {

                *valp = val;

            }

            break;

        }

        case 'd': {

            uint32_t val, *valp;

            valp = va_arg(ap, uint32_t *);

            offset += v9fs_unpack(&val, out_sg, out_num, offset, sizeof(val));

            if (bswap) {

                *valp = le32_to_cpu(val);

            } else {

                *valp = val;

            }

            break;

        }

        case 'q': {

            uint64_t val, *valp;

            valp = va_arg(ap, uint64_t *);

            offset += v9fs_unpack(&val, out_sg, out_num, offset, sizeof(val));

            if (bswap) {

                *valp = le64_to_cpu(val);

            } else {

                *valp = val;

            }

            break;

        }

        case 's': {

            V9fsString *str = va_arg(ap, V9fsString *);

            offset += v9fs_unmarshal(out_sg, out_num, offset, bswap,

                            "w", &str->size);

            /* FIXME: sanity check str->size */

            str->data = g_malloc(str->size + 1);

            offset += v9fs_unpack(str->data, out_sg, out_num, offset,

                            str->size);

            str->data[str->size] = 0;

            break;

        }

        case 'Q': {

            V9fsQID *qidp = va_arg(ap, V9fsQID *);

            offset += v9fs_unmarshal(out_sg, out_num, offset, bswap, "bdq",

                                     &qidp->type, &qidp->version, &qidp->path);

            break;

        }

        case 'S': {

            V9fsStat *statp = va_arg(ap, V9fsStat *);

            offset += v9fs_unmarshal(out_sg, out_num, offset, bswap,

                                    "wwdQdddqsssssddd",

                                     &statp->size, &statp->type, &statp->dev,

                                     &statp->qid, &statp->mode, &statp->atime,

                                     &statp->mtime, &statp->length,

                                     &statp->name, &statp->uid, &statp->gid,

                                     &statp->muid, &statp->extension,

                                     &statp->n_uid, &statp->n_gid,

                                     &statp->n_muid);

            break;

        }

        case 'I': {

            V9fsIattr *iattr = va_arg(ap, V9fsIattr *);

            offset += v9fs_unmarshal(out_sg, out_num, offset, bswap,

                                     "ddddqqqqq",

                                     &iattr->valid, &iattr->mode,

                                     &iattr->uid, &iattr->gid, &iattr->size,

                                     &iattr->atime_sec, &iattr->atime_nsec,

                                     &iattr->mtime_sec, &iattr->mtime_nsec);

            break;

        }

        default:

            break;

        }

    }



    va_end(ap);



    return offset - old_offset;

}

