void helper_divl_EAX_T0(void)

{

    unsigned int den, q, r;

    uint64_t num;



    num = ((uint32_t)EAX) | ((uint64_t)((uint32_t)EDX) << 32);

    den = T0;

    if (den == 0) {

        raise_exception(EXCP00_DIVZ);

    }

#ifdef BUGGY_GCC_DIV64

    r = div32(&q, num, den);

#else

    q = (num / den);

    r = (num % den);

#endif

    EAX = (uint32_t)q;

    EDX = (uint32_t)r;

}

void OPPROTO op_idivb_AL_T0(void)

{

    int num, den, q, r;



    num = (int16_t)EAX;

    den = (int8_t)T0;

    if (den == 0) {

        raise_exception(EXCP00_DIVZ);

    }

    q = (num / den) & 0xff;

    r = (num % den) & 0xff;

    EAX = (EAX & ~0xffff) | (r << 8) | q;

}

void OPPROTO op_idivw_AX_T0(void)

{

    int num, den, q, r;



    num = (EAX & 0xffff) | ((EDX & 0xffff) << 16);

    den = (int16_t)T0;

    if (den == 0) {

        raise_exception(EXCP00_DIVZ);

    }

    q = (num / den) & 0xffff;

    r = (num % den) & 0xffff;

    EAX = (EAX & ~0xffff) | q;

    EDX = (EDX & ~0xffff) | r;

}

void helper_idivq_EAX_T0(void)

{

    uint64_t r0, r1;

    if (T0 == 0) {

        raise_exception(EXCP00_DIVZ);

    }

    r0 = EAX;

    r1 = EDX;

    idiv64(&r0, &r1, T0);

    EAX = r0;

    EDX = r1;

}

static av_always_inline void fic_idct(int16_t *blk, int step, int shift, int rnd)

{

    const int t0 =  27246 * blk[3 * step] + 18405 * blk[5 * step];

    const int t1 =  27246 * blk[5 * step] - 18405 * blk[3 * step];

    const int t2 =   6393 * blk[7 * step] + 32139 * blk[1 * step];

    const int t3 =   6393 * blk[1 * step] - 32139 * blk[7 * step];

    const unsigned t4 = 5793U * (t2 + t0 + 0x800 >> 12);

    const unsigned t5 = 5793U * (t3 + t1 + 0x800 >> 12);

    const unsigned t6 = t2 - t0;

    const unsigned t7 = t3 - t1;

    const unsigned t8 =  17734 * blk[2 * step] - 42813 * blk[6 * step];

    const unsigned t9 =  17734 * blk[6 * step] + 42814 * blk[2 * step];

    const unsigned tA = (blk[0 * step] - blk[4 * step]) * 32768 + rnd;

    const unsigned tB = (blk[0 * step] + blk[4 * step]) * 32768 + rnd;

    blk[0 * step] = (int)(  t4       + t9 + tB) >> shift;

    blk[1 * step] = (int)(  t6 + t7  + t8 + tA) >> shift;

    blk[2 * step] = (int)(  t6 - t7  - t8 + tA) >> shift;

    blk[3 * step] = (int)(  t5       - t9 + tB) >> shift;

    blk[4 * step] = (int)( -t5       - t9 + tB) >> shift;

    blk[5 * step] = (int)(-(t6 - t7) - t8 + tA) >> shift;

    blk[6 * step] = (int)(-(t6 + t7) + t8 + tA) >> shift;

    blk[7 * step] = (int)( -t4       + t9 + tB) >> shift;

}

static inline void idct4col_put(uint8_t *dest, int line_size, const int16_t *col)

{

    int c0, c1, c2, c3, a0, a1, a2, a3;



    a0 = col[8*0];

    a1 = col[8*2];

    a2 = col[8*4];

    a3 = col[8*6];

    c0 = ((a0 + a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c2 = ((a0 - a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c1 = a1 * C1 + a3 * C2;

    c3 = a1 * C2 - a3 * C1;

    dest[0] = av_clip_uint8((c0 + c1) >> C_SHIFT);

    dest += line_size;

    dest[0] = av_clip_uint8((c2 + c3) >> C_SHIFT);

    dest += line_size;

    dest[0] = av_clip_uint8((c2 - c3) >> C_SHIFT);

    dest += line_size;

    dest[0] = av_clip_uint8((c0 - c1) >> C_SHIFT);

}

static void vc1_inv_trans_8x4_c(uint8_t *dest, int linesize, DCTELEM *block)

{

    int i;

    register int t1,t2,t3,t4,t5,t6,t7,t8;

    DCTELEM *src, *dst;

    const uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    src = block;

    dst = block;

    for(i = 0; i < 4; i++){

        t1 = 12 * (src[0] + src[4]) + 4;

        t2 = 12 * (src[0] - src[4]) + 4;

        t3 = 16 * src[2] +  6 * src[6];

        t4 =  6 * src[2] - 16 * src[6];



        t5 = t1 + t3;

        t6 = t2 + t4;

        t7 = t2 - t4;

        t8 = t1 - t3;



        t1 = 16 * src[1] + 15 * src[3] +  9 * src[5] +  4 * src[7];

        t2 = 15 * src[1] -  4 * src[3] - 16 * src[5] -  9 * src[7];

        t3 =  9 * src[1] - 16 * src[3] +  4 * src[5] + 15 * src[7];

        t4 =  4 * src[1] -  9 * src[3] + 15 * src[5] - 16 * src[7];



        dst[0] = (t5 + t1) >> 3;

        dst[1] = (t6 + t2) >> 3;

        dst[2] = (t7 + t3) >> 3;

        dst[3] = (t8 + t4) >> 3;

        dst[4] = (t8 - t4) >> 3;

        dst[5] = (t7 - t3) >> 3;

        dst[6] = (t6 - t2) >> 3;

        dst[7] = (t5 - t1) >> 3;



        src += 8;

        dst += 8;

    }



    src = block;

    for(i = 0; i < 8; i++){

        t1 = 17 * (src[ 0] + src[16]) + 64;

        t2 = 17 * (src[ 0] - src[16]) + 64;

        t3 = 22 * src[ 8] + 10 * src[24];

        t4 = 22 * src[24] - 10 * src[ 8];



        dest[0*linesize] = cm[dest[0*linesize] + ((t1 + t3) >> 7)];

        dest[1*linesize] = cm[dest[1*linesize] + ((t2 - t4) >> 7)];

        dest[2*linesize] = cm[dest[2*linesize] + ((t2 + t4) >> 7)];

        dest[3*linesize] = cm[dest[3*linesize] + ((t1 - t3) >> 7)];



        src ++;

        dest++;

    }

}

static int fourxm_probe(AVProbeData *p)

{

    if ((AV_RL32(&p->buf[0]) != RIFF_TAG) ||

        (AV_RL32(&p->buf[8]) != _4XMV_TAG))

        return 0;



    return AVPROBE_SCORE_MAX;

}

static int ea_probe(AVProbeData *p)

{

    switch (AV_RL32(&p->buf[0])) {

    case ISNh_TAG:

    case SCHl_TAG:

    case SEAD_TAG:

    case SHEN_TAG:

    case kVGT_TAG:

    case MADk_TAG:

    case MPCh_TAG:

    case MVhd_TAG:

    case MVIh_TAG:

        break;

    default:

        return 0;

    }

    if (AV_RL32(&p->buf[4]) > 0xfffff && AV_RB32(&p->buf[4]) > 0xfffff)

        return 0;



    return AVPROBE_SCORE_MAX;

}

static int roq_probe(AVProbeData *p)

{

    if (p->buf_size < 6)

        return 0;



    if ((AV_RL16(&p->buf[0]) != RoQ_MAGIC_NUMBER) ||

        (AV_RL32(&p->buf[2]) != 0xFFFFFFFF))

        return 0;



    return AVPROBE_SCORE_MAX;

}

static int vid_probe(AVProbeData *p)

{

    // little endian VID tag, file starts with "VID\0"

    if (p->buf_size < 4 || AV_RL32(p->buf) != MKTAG('V', 'I', 'D', 0))

        return 0;



    return AVPROBE_SCORE_MAX;

}

