static int hevc_decode_nal_units(const uint8_t *buf, int buf_size, HEVCParamSets *ps,

                                 int is_nalff, int nal_length_size, void *logctx)

{

    int i;

    int ret = 0;

    H2645Packet pkt = { 0 };



    ret = ff_h2645_packet_split(&pkt, buf, buf_size, logctx, is_nalff, nal_length_size, AV_CODEC_ID_HEVC, 1);

    if (ret < 0) {

        goto done;

    }



    for (i = 0; i < pkt.nb_nals; i++) {

        H2645NAL *nal = &pkt.nals[i];



        /* ignore everything except parameter sets and VCL NALUs */

        switch (nal->type) {

        case HEVC_NAL_VPS: ff_hevc_decode_nal_vps(&nal->gb, logctx, ps);    break;

        case HEVC_NAL_SPS: ff_hevc_decode_nal_sps(&nal->gb, logctx, ps, 1); break;

        case HEVC_NAL_PPS: ff_hevc_decode_nal_pps(&nal->gb, logctx, ps);    break;

        default:

            av_log(logctx, AV_LOG_VERBOSE, "Ignoring NAL type %d in extradata\n", nal->type);

            break;

        }

    }



done:

    ff_h2645_packet_uninit(&pkt);

    return ret;

}

static int select_reference_stream(AVFormatContext *s)

{

    SegmentContext *seg = s->priv_data;

    int ret, i;



    seg->reference_stream_index = -1;

    if (!strcmp(seg->reference_stream_specifier, "auto")) {

        /* select first index of type with highest priority */

        int type_index_map[AVMEDIA_TYPE_NB];

        static const enum AVMediaType type_priority_list[] = {

            AVMEDIA_TYPE_VIDEO,

            AVMEDIA_TYPE_AUDIO,

            AVMEDIA_TYPE_SUBTITLE,

            AVMEDIA_TYPE_DATA,

            AVMEDIA_TYPE_ATTACHMENT

        };

        enum AVMediaType type;



        for (i = 0; i < AVMEDIA_TYPE_NB; i++)

            type_index_map[i] = -1;



        /* select first index for each type */

        for (i = 0; i < s->nb_streams; i++) {

            type = s->streams[i]->codec->codec_type;

            if ((unsigned)type < AVMEDIA_TYPE_NB && type_index_map[type] == -1

                /* ignore attached pictures/cover art streams */

                && !(s->streams[i]->disposition & AV_DISPOSITION_ATTACHED_PIC))

                type_index_map[type] = i;

        }



        for (i = 0; i < FF_ARRAY_ELEMS(type_priority_list); i++) {

            type = type_priority_list[i];

            if ((seg->reference_stream_index = type_index_map[type]) >= 0)

                break;

        }

    } else {

        for (i = 0; i < s->nb_streams; i++) {

            ret = avformat_match_stream_specifier(s, s->streams[i],

                                                  seg->reference_stream_specifier);

            if (ret < 0)

                break;

            if (ret > 0) {

                seg->reference_stream_index = i;

                break;

            }

        }

    }



    if (seg->reference_stream_index < 0) {

        av_log(s, AV_LOG_ERROR, "Could not select stream matching identifier '%s'\n",

               seg->reference_stream_specifier);

        return AVERROR(EINVAL);

    }



    return 0;

}

static int parse_nal_units(AVCodecParserContext *s, const uint8_t *buf,

                           int buf_size, AVCodecContext *avctx)

{

    HEVCParserContext *ctx = s->priv_data;

    int ret, i;



    ret = ff_h2645_packet_split(&ctx->pkt, buf, buf_size, avctx, 0, 0,

                                AV_CODEC_ID_HEVC);

    if (ret < 0)

        return ret;



    for (i = 0; i < ctx->pkt.nb_nals; i++) {

        H2645NAL *nal = &ctx->pkt.nals[i];



        /* ignore everything except parameter sets and VCL NALUs */

        switch (nal->type) {

        case NAL_VPS: ff_hevc_decode_nal_vps(&nal->gb, avctx, &ctx->ps);    break;

        case NAL_SPS: ff_hevc_decode_nal_sps(&nal->gb, avctx, &ctx->ps, 1); break;

        case NAL_PPS: ff_hevc_decode_nal_pps(&nal->gb, avctx, &ctx->ps);    break;

        case NAL_TRAIL_R:

        case NAL_TRAIL_N:

        case NAL_TSA_N:

        case NAL_TSA_R:

        case NAL_STSA_N:

        case NAL_STSA_R:

        case NAL_BLA_W_LP:

        case NAL_BLA_W_RADL:

        case NAL_BLA_N_LP:

        case NAL_IDR_W_RADL:

        case NAL_IDR_N_LP:

        case NAL_CRA_NUT:

        case NAL_RADL_N:

        case NAL_RADL_R:

        case NAL_RASL_N:

        case NAL_RASL_R:

            if (buf == avctx->extradata) {

                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit: %d\n", nal->type);

                return AVERROR_INVALIDDATA;

            }

            hevc_parse_slice_header(s, nal, avctx);

            break;

        }

    }



    return 0;

}

static int hevc_decode_extradata(HEVCContext *s, uint8_t *buf, int length)

{

    int ret, i;



    ret = ff_hevc_decode_extradata(buf, length, &s->ps, &s->sei, &s->is_nalff,

                                   &s->nal_length_size, s->avctx->err_recognition,

                                   s->apply_defdispwin, s->avctx);

    if (ret < 0)

        return ret;



    /* export stream parameters from the first SPS */

    for (i = 0; i < FF_ARRAY_ELEMS(s->ps.sps_list); i++) {

        if (s->ps.sps_list[i]) {

            const HEVCSPS *sps = (const HEVCSPS*)s->ps.sps_list[i]->data;

            export_stream_params(s->avctx, &s->ps, sps);

            break;

        }

    }



    return 0;

}

static void FUNC(put_hevc_epel_bi_w_v)(uint8_t *_dst, ptrdiff_t _dststride, uint8_t *_src, ptrdiff_t _srcstride,

                                       int16_t *src2,

                                       int height, int denom, int wx0, int wx1,

                                       int ox0, int ox1, intptr_t mx, intptr_t my, int width)

{

    int x, y;

    pixel *src = (pixel *)_src;

    ptrdiff_t srcstride  = _srcstride / sizeof(pixel);

    const int8_t *filter = ff_hevc_epel_filters[my - 1];

    pixel *dst          = (pixel *)_dst;

    ptrdiff_t dststride = _dststride / sizeof(pixel);

    int shift = 14 + 1 - BIT_DEPTH;

    int log2Wd = denom + shift - 1;



    ox0     = ox0 * (1 << (BIT_DEPTH - 8));

    ox1     = ox1 * (1 << (BIT_DEPTH - 8));

    for (y = 0; y < height; y++) {

        for (x = 0; x < width; x++)

            dst[x] = av_clip_pixel(((EPEL_FILTER(src, srcstride) >> (BIT_DEPTH - 8)) * wx1 + src2[x] * wx0 +

                                    ((ox0 + ox1 + 1) << log2Wd)) >> (log2Wd + 1));

        src  += srcstride;

        dst  += dststride;

        src2 += MAX_PB_SIZE;

    }

}

static void FUNC(put_hevc_epel_bi_w_hv)(uint8_t *_dst, ptrdiff_t _dststride, uint8_t *_src, ptrdiff_t _srcstride,

                                        int16_t *src2,

                                        int height, int denom, int wx0, int wx1,

                                        int ox0, int ox1, intptr_t mx, intptr_t my, int width)

{

    int x, y;

    pixel *src = (pixel *)_src;

    ptrdiff_t srcstride = _srcstride / sizeof(pixel);

    pixel *dst          = (pixel *)_dst;

    ptrdiff_t dststride = _dststride / sizeof(pixel);

    const int8_t *filter = ff_hevc_epel_filters[mx - 1];

    int16_t tmp_array[(MAX_PB_SIZE + EPEL_EXTRA) * MAX_PB_SIZE];

    int16_t *tmp = tmp_array;

    int shift = 14 + 1 - BIT_DEPTH;

    int log2Wd = denom + shift - 1;



    src -= EPEL_EXTRA_BEFORE * srcstride;



    for (y = 0; y < height + EPEL_EXTRA; y++) {

        for (x = 0; x < width; x++)

            tmp[x] = EPEL_FILTER(src, 1) >> (BIT_DEPTH - 8);

        src += srcstride;

        tmp += MAX_PB_SIZE;

    }



    tmp      = tmp_array + EPEL_EXTRA_BEFORE * MAX_PB_SIZE;

    filter = ff_hevc_epel_filters[my - 1];



    ox0     = ox0 * (1 << (BIT_DEPTH - 8));

    ox1     = ox1 * (1 << (BIT_DEPTH - 8));

    for (y = 0; y < height; y++) {

        for (x = 0; x < width; x++)

            dst[x] = av_clip_pixel(((EPEL_FILTER(tmp, MAX_PB_SIZE) >> 6) * wx1 + src2[x] * wx0 +

                                    ((ox0 + ox1 + 1) << log2Wd)) >> (log2Wd + 1));

        tmp  += MAX_PB_SIZE;

        dst  += dststride;

        src2 += MAX_PB_SIZE;

    }

}

