static av_cold int fdk_aac_decode_init(AVCodecContext *avctx)

{

    FDKAACDecContext *s = avctx->priv_data;

    AAC_DECODER_ERROR err;

    int ret;



    s->handle = aacDecoder_Open(avctx->extradata_size ? TT_MP4_RAW : TT_MP4_ADTS, 1);

    if (!s->handle) {

        av_log(avctx, AV_LOG_ERROR, "Error opening decoder\n");

        return AVERROR_UNKNOWN;

    }



    if (avctx->extradata_size) {

        if ((err = aacDecoder_ConfigRaw(s->handle, &avctx->extradata,

                                        &avctx->extradata_size)) != AAC_DEC_OK) {

            av_log(avctx, AV_LOG_ERROR, "Unable to set extradata\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if ((err = aacDecoder_SetParam(s->handle, AAC_CONCEAL_METHOD,

                                   s->conceal_method)) != AAC_DEC_OK) {

        av_log(avctx, AV_LOG_ERROR, "Unable to set error concealment method\n");

        return AVERROR_UNKNOWN;

    }



    if (avctx->request_channel_layout > 0 &&

        avctx->request_channel_layout != AV_CH_LAYOUT_NATIVE) {

        int downmix_channels = -1;



        switch (avctx->request_channel_layout) {

        case AV_CH_LAYOUT_STEREO:

        case AV_CH_LAYOUT_STEREO_DOWNMIX:

            downmix_channels = 2;

            break;

        case AV_CH_LAYOUT_MONO:

            downmix_channels = 1;

            break;

        default:

            av_log(avctx, AV_LOG_WARNING, "Invalid request_channel_layout\n");

            break;

        }



        if (downmix_channels != -1) {

            if (aacDecoder_SetParam(s->handle, AAC_PCM_MAX_OUTPUT_CHANNELS,

                                    downmix_channels) != AAC_DEC_OK) {

               av_log(avctx, AV_LOG_WARNING, "Unable to set output channels in the decoder\n");

            } else {

               s->anc_buffer = av_malloc(DMX_ANC_BUFFSIZE);

               if (!s->anc_buffer) {

                   av_log(avctx, AV_LOG_ERROR, "Unable to allocate ancillary buffer for the decoder\n");

                   ret = AVERROR(ENOMEM);

                   goto fail;

               }

               if (aacDecoder_AncDataInit(s->handle, s->anc_buffer, DMX_ANC_BUFFSIZE)) {

                   av_log(avctx, AV_LOG_ERROR, "Unable to register downmix ancillary buffer in the decoder\n");

                   ret = AVERROR_UNKNOWN;

                   goto fail;

               }

            }

        }

    }



    if (s->drc_boost != -1) {

        if (aacDecoder_SetParam(s->handle, AAC_DRC_BOOST_FACTOR, s->drc_boost) != AAC_DEC_OK) {

            av_log(avctx, AV_LOG_ERROR, "Unable to set DRC boost factor in the decoder\n");

            return AVERROR_UNKNOWN;

        }

    }



    if (s->drc_cut != -1) {

        if (aacDecoder_SetParam(s->handle, AAC_DRC_ATTENUATION_FACTOR, s->drc_cut) != AAC_DEC_OK) {

            av_log(avctx, AV_LOG_ERROR, "Unable to set DRC attenuation factor in the decoder\n");

            return AVERROR_UNKNOWN;

        }

    }



    if (s->drc_level != -1) {

        if (aacDecoder_SetParam(s->handle, AAC_DRC_REFERENCE_LEVEL, s->drc_level) != AAC_DEC_OK) {

            av_log(avctx, AV_LOG_ERROR, "Unable to set DRC reference level in the decoder\n");

            return AVERROR_UNKNOWN;

        }

    }



    if (s->drc_heavy != -1) {

        if (aacDecoder_SetParam(s->handle, AAC_DRC_HEAVY_COMPRESSION, s->drc_heavy) != AAC_DEC_OK) {

            av_log(avctx, AV_LOG_ERROR, "Unable to set DRC heavy compression in the decoder\n");

            return AVERROR_UNKNOWN;

        }

    }



#ifdef AACDECODER_LIB_VL0

    if (aacDecoder_SetParam(s->handle, AAC_PCM_LIMITER_ENABLE, s->level_limit) != AAC_DEC_OK) {

        av_log(avctx, AV_LOG_ERROR, "Unable to set in signal level limiting in the decoder\n");

        return AVERROR_UNKNOWN;

    }

#endif



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;



    s->decoder_buffer_size = DECODER_BUFFSIZE * DECODER_MAX_CHANNELS;

    s->decoder_buffer = av_malloc(s->decoder_buffer_size);

    if (!s->decoder_buffer) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    return 0;

fail:

    fdk_aac_decode_close(avctx);

    return ret;

}

static int ffmal_update_format(AVCodecContext *avctx)

{

    MMALDecodeContext *ctx = avctx->priv_data;

    MMAL_STATUS_T status;

    int ret = 0;

    MMAL_COMPONENT_T *decoder = ctx->decoder;

    MMAL_ES_FORMAT_T *format_out = decoder->output[0]->format;



    ffmmal_poolref_unref(ctx->pool_out);

    if (!(ctx->pool_out = av_mallocz(sizeof(*ctx->pool_out)))) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }

    atomic_store(&ctx->pool_out->refcount, 1);



    if (!format_out)

        goto fail;



    if ((status = mmal_port_parameter_set_uint32(decoder->output[0], MMAL_PARAMETER_EXTRA_BUFFERS, ctx->extra_buffers)))

        goto fail;



    if ((status = mmal_port_parameter_set_boolean(decoder->output[0], MMAL_PARAMETER_VIDEO_INTERPOLATE_TIMESTAMPS, 0)))

        goto fail;



    if (avctx->pix_fmt == AV_PIX_FMT_MMAL) {

        format_out->encoding = MMAL_ENCODING_OPAQUE;

    } else {

        format_out->encoding_variant = format_out->encoding = MMAL_ENCODING_I420;

    }



    if ((status = mmal_port_format_commit(decoder->output[0])))

        goto fail;



    if ((ret = ff_set_dimensions(avctx, format_out->es->video.crop.x + format_out->es->video.crop.width,

                                        format_out->es->video.crop.y + format_out->es->video.crop.height)) < 0)

        goto fail;



    if (format_out->es->video.par.num && format_out->es->video.par.den) {

        avctx->sample_aspect_ratio.num = format_out->es->video.par.num;

        avctx->sample_aspect_ratio.den = format_out->es->video.par.den;

    }



    avctx->colorspace = ffmmal_csp_to_av_csp(format_out->es->video.color_space);



    decoder->output[0]->buffer_size =

        FFMAX(decoder->output[0]->buffer_size_min, decoder->output[0]->buffer_size_recommended);

    decoder->output[0]->buffer_num =

        FFMAX(decoder->output[0]->buffer_num_min, decoder->output[0]->buffer_num_recommended) + ctx->extra_buffers;

    ctx->pool_out->pool = mmal_pool_create(decoder->output[0]->buffer_num,

                                           decoder->output[0]->buffer_size);

    if (!ctx->pool_out->pool) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    return 0;



fail:

    return ret < 0 ? ret : AVERROR_UNKNOWN;

}

static av_cold int libopenjpeg_encode_init(AVCodecContext *avctx)

{

    LibOpenJPEGContext *ctx = avctx->priv_data;

    int err = 0;



    opj_set_default_encoder_parameters(&ctx->enc_params);



#if HAVE_OPENJPEG_2_1_OPENJPEG_H

    switch (ctx->cinema_mode) {

    case OPJ_CINEMA2K_24:

        ctx->enc_params.rsiz = OPJ_PROFILE_CINEMA_2K;

        ctx->enc_params.max_cs_size = OPJ_CINEMA_24_CS;

        ctx->enc_params.max_comp_size = OPJ_CINEMA_24_COMP;

        break;

    case OPJ_CINEMA2K_48:

        ctx->enc_params.rsiz = OPJ_PROFILE_CINEMA_2K;

        ctx->enc_params.max_cs_size = OPJ_CINEMA_48_CS;

        ctx->enc_params.max_comp_size = OPJ_CINEMA_48_COMP;

        break;

    case OPJ_CINEMA4K_24:

        ctx->enc_params.rsiz = OPJ_PROFILE_CINEMA_4K;

        ctx->enc_params.max_cs_size = OPJ_CINEMA_24_CS;

        ctx->enc_params.max_comp_size = OPJ_CINEMA_24_COMP;

        break;

    }



    switch (ctx->profile) {

    case OPJ_CINEMA2K:

        if (ctx->enc_params.rsiz == OPJ_PROFILE_CINEMA_4K) {

            err = AVERROR(EINVAL);

            break;

        }

        ctx->enc_params.rsiz = OPJ_PROFILE_CINEMA_2K;

        break;

    case OPJ_CINEMA4K:

        if (ctx->enc_params.rsiz == OPJ_PROFILE_CINEMA_2K) {

            err = AVERROR(EINVAL);

            break;

        }

        ctx->enc_params.rsiz = OPJ_PROFILE_CINEMA_4K;

        break;

    }



    if (err) {

        av_log(avctx, AV_LOG_ERROR,

               "Invalid parameter pairing: cinema_mode and profile conflict.\n");

        goto fail;

    }

#else

    ctx->enc_params.cp_rsiz = ctx->profile;

    ctx->enc_params.cp_cinema = ctx->cinema_mode;

#endif



    if (!ctx->numresolution) {

        ctx->numresolution = 6;

        while (FFMIN(avctx->width, avctx->height) >> ctx->numresolution < 1)

            ctx->numresolution --;

    }



    ctx->enc_params.mode = !!avctx->global_quality;

    ctx->enc_params.prog_order = ctx->prog_order;

    ctx->enc_params.numresolution = ctx->numresolution;

    ctx->enc_params.cp_disto_alloc = ctx->disto_alloc;

    ctx->enc_params.cp_fixed_alloc = ctx->fixed_alloc;

    ctx->enc_params.cp_fixed_quality = ctx->fixed_quality;

    ctx->enc_params.tcp_numlayers = ctx->numlayers;

    ctx->enc_params.tcp_rates[0] = FFMAX(avctx->compression_level, 0) * 2;



    if (ctx->cinema_mode > 0) {

        cinema_parameters(&ctx->enc_params);

    }



#if OPENJPEG_MAJOR_VERSION == 1

    ctx->image = mj2_create_image(avctx, &ctx->enc_params);

    if (!ctx->image) {

        av_log(avctx, AV_LOG_ERROR, "Error creating the mj2 image\n");

        err = AVERROR(EINVAL);

        goto fail;

    }

#endif // OPENJPEG_MAJOR_VERSION == 1



    return 0;



fail:

#if OPENJPEG_MAJOR_VERSION == 1

    opj_image_destroy(ctx->image);

    ctx->image = NULL;

#endif // OPENJPEG_MAJOR_VERSION == 1

    return err;

}

ogg_get_length (AVFormatContext * s)

{

    ogg_t *ogg = s->priv_data;

    int idx = -1, i;

    offset_t size, end;



    if(s->pb.is_streamed)

        return 0;



// already set

    if (s->duration != AV_NOPTS_VALUE)

        return 0;



    size = url_fsize(&s->pb);

    if(size < 0)

        return 0;

    end = size > MAX_PAGE_SIZE? size - MAX_PAGE_SIZE: size;



    ogg_save (s);

    url_fseek (&s->pb, end, SEEK_SET);



    while (!ogg_read_page (s, &i)){

        if (ogg->streams[i].granule != -1 && ogg->streams[i].granule != 0)

            idx = i;

    }



    if (idx != -1){

        s->streams[idx]->duration =

            ogg_gptopts (s, idx, ogg->streams[idx].granule);

    }



    ogg->size = size;

    ogg_restore (s, 0);

    ogg_save (s);

    while (!ogg_read_page (s, &i)) {

        if (i == idx && ogg->streams[i].granule != -1 && ogg->streams[i].granule != 0)

            break;

    }

    if (i == idx) {

        s->streams[idx]->start_time = ogg_gptopts (s, idx, ogg->streams[idx].granule);

        s->streams[idx]->duration -= s->streams[idx]->start_time;

    }

    ogg_restore (s, 0);



    return 0;

}

static int64_t ogg_read_timestamp(AVFormatContext *s, int stream_index,

                                  int64_t *pos_arg, int64_t pos_limit)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + stream_index;

    AVIOContext *bc = s->pb;

    int64_t pts = AV_NOPTS_VALUE;

    int i;

    avio_seek(bc, *pos_arg, SEEK_SET);

    ogg_reset(ogg);



    while (avio_tell(bc) < pos_limit && !ogg_packet(s, &i, NULL, NULL, pos_arg)) {

        if (i == stream_index) {

            pts = ogg_calc_pts(s, i, NULL);

            if (os->keyframe_seek && !(os->pflags & AV_PKT_FLAG_KEY))

                pts = AV_NOPTS_VALUE;

        }

        if (pts != AV_NOPTS_VALUE)

            break;

    }

    ogg_reset(ogg);

    return pts;

}

static int ogg_read_header(AVFormatContext *s)

{

    struct ogg *ogg = s->priv_data;

    int ret, i;



    ogg->curidx = -1;



    //linear headers seek from start

    do {

        ret = ogg_packet(s, NULL, NULL, NULL, NULL);

        if (ret < 0) {

            ogg_read_close(s);

            return ret;

        }

    } while (!ogg->headers);

    av_log(s, AV_LOG_TRACE, "found headers\n");



    for (i = 0; i < ogg->nstreams; i++) {

        struct ogg_stream *os = ogg->streams + i;



        if (ogg->streams[i].header < 0) {

            av_log(s, AV_LOG_ERROR, "Header parsing failed for stream %d\n", i);

            ogg->streams[i].codec = NULL;


        } else if (os->codec && os->nb_header < os->codec->nb_header) {

            av_log(s, AV_LOG_WARNING,

                   "Headers mismatch for stream %d: "

                   "expected %d received %d.\n",

                   i, os->codec->nb_header, os->nb_header);

            if (s->error_recognition & AV_EF_EXPLODE)

                return AVERROR_INVALIDDATA;

        }

        if (os->start_granule != OGG_NOGRANULE_VALUE)

            os->lastpts = s->streams[i]->start_time =

                ogg_gptopts(s, i, os->start_granule, NULL);

    }



    //linear granulepos seek from end

    ret = ogg_get_length(s);

    if (ret < 0) {

        ogg_read_close(s);

        return ret;

    }



    return 0;

}

static int ogg_restore(AVFormatContext *s)

{

    struct ogg *ogg = s->priv_data;

    AVIOContext *bc = s->pb;

    struct ogg_state *ost = ogg->state;

    int i, err;



    if (!ost)

        return 0;



    ogg->state = ost->next;



        for (i = 0; i < ogg->nstreams; i++)

            av_freep(&ogg->streams[i].buf);



        avio_seek(bc, ost->pos, SEEK_SET);

        ogg->page_pos = -1;

        ogg->curidx   = ost->curidx;

        ogg->nstreams = ost->nstreams;

        if ((err = av_reallocp_array(&ogg->streams, ogg->nstreams,

                                     sizeof(*ogg->streams))) < 0) {

            ogg->nstreams = 0;

            return err;

        } else

            memcpy(ogg->streams, ost->streams,

                   ost->nstreams * sizeof(*ogg->streams));



    av_free(ost);



    return 0;

}

static int mimic_decode_frame(AVCodecContext *avctx, void *data,

                              int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    int swap_buf_size  = buf_size - MIMIC_HEADER_SIZE;

    MimicContext *ctx  = avctx->priv_data;

    GetByteContext gb;

    int is_pframe;

    int width, height;

    int quality, num_coeffs;

    int res;



    if (buf_size <= MIMIC_HEADER_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "insufficient data\n");

        return AVERROR_INVALIDDATA;

    }



    bytestream2_init(&gb, buf, MIMIC_HEADER_SIZE);

    bytestream2_skip(&gb, 2); /* some constant (always 256) */

    quality    = bytestream2_get_le16u(&gb);

    width      = bytestream2_get_le16u(&gb);

    height     = bytestream2_get_le16u(&gb);

    bytestream2_skip(&gb, 4); /* some constant */

    is_pframe  = bytestream2_get_le32u(&gb);

    num_coeffs = bytestream2_get_byteu(&gb);

    bytestream2_skip(&gb, 3); /* some constant */



    if (!ctx->avctx) {

        int i;



        if (!(width == 160 && height == 120) &&

            !(width == 320 && height == 240)) {

            av_log(avctx, AV_LOG_ERROR, "invalid width/height!\n");

            return AVERROR_INVALIDDATA;

        }



        ctx->avctx     = avctx;

        avctx->width   = width;

        avctx->height  = height;

        avctx->pix_fmt = AV_PIX_FMT_YUV420P;

        for (i = 0; i < 3; i++) {

            ctx->num_vblocks[i] = AV_CEIL_RSHIFT(height,   3 + !!i);

            ctx->num_hblocks[i] =                width >> (3 + !!i);

        }

    } else if (width != ctx->avctx->width || height != ctx->avctx->height) {

        avpriv_request_sample(avctx, "Resolution changing");

        return AVERROR_PATCHWELCOME;

    }



    if (is_pframe && !ctx->frames[ctx->prev_index].f->data[0]) {

        av_log(avctx, AV_LOG_ERROR, "decoding must start with keyframe\n");

        return AVERROR_INVALIDDATA;

    }



    ff_thread_release_buffer(avctx, &ctx->frames[ctx->cur_index]);

    ctx->frames[ctx->cur_index].f->pict_type = is_pframe ? AV_PICTURE_TYPE_P :

                                                           AV_PICTURE_TYPE_I;

    if ((res = ff_thread_get_buffer(avctx, &ctx->frames[ctx->cur_index],

                                    AV_GET_BUFFER_FLAG_REF)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return res;

    }



    ctx->next_prev_index = ctx->cur_index;

    ctx->next_cur_index  = (ctx->cur_index - 1) & 15;



    ff_thread_finish_setup(avctx);



    av_fast_padded_malloc(&ctx->swap_buf, &ctx->swap_buf_size, swap_buf_size);

    if (!ctx->swap_buf)

        return AVERROR(ENOMEM);



    ctx->bbdsp.bswap_buf(ctx->swap_buf,

                         (const uint32_t *) (buf + MIMIC_HEADER_SIZE),

                         swap_buf_size >> 2);

    init_get_bits(&ctx->gb, ctx->swap_buf, swap_buf_size << 3);



    res = decode(ctx, quality, num_coeffs, !is_pframe);

    ff_thread_report_progress(&ctx->frames[ctx->cur_index], INT_MAX, 0);

    if (res < 0) {

        if (!(avctx->active_thread_type & FF_THREAD_FRAME))

            ff_thread_release_buffer(avctx, &ctx->frames[ctx->cur_index]);

        return res;

    }



    if ((res = av_frame_ref(data, ctx->frames[ctx->cur_index].f)) < 0)

        return res;

    *got_frame      = 1;



    flip_swap_frame(data);



    ctx->prev_index = ctx->next_prev_index;

    ctx->cur_index  = ctx->next_cur_index;



    /* Only release frames that aren't used for backreferences anymore */

    ff_thread_release_buffer(avctx, &ctx->frames[ctx->cur_index]);



    return buf_size;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    VBDecContext * const c = avctx->priv_data;

    uint8_t *outptr, *srcptr;

    int i, j;

    int flags;

    uint32_t size;

    int rest = buf_size;

    int offset = 0;



    if(c->pic.data[0])

        avctx->release_buffer(avctx, &c->pic);

    c->pic.reference = 3;

    if(avctx->get_buffer(avctx, &c->pic) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    c->stream = buf;

    flags = bytestream_get_le16(&c->stream);

    rest -= 2;



    if(flags & VB_HAS_GMC){

        i = (int16_t)bytestream_get_le16(&c->stream);

        j = (int16_t)bytestream_get_le16(&c->stream);

        offset = i + j * avctx->width;

        rest -= 4;

    }

    if(flags & VB_HAS_VIDEO){

        size = bytestream_get_le32(&c->stream);

        if(size > rest){

            av_log(avctx, AV_LOG_ERROR, "Frame size is too big\n");

            return -1;

        }

        vb_decode_framedata(c, c->stream, size, offset);

        c->stream += size - 4;

        rest -= size;

    }

    if(flags & VB_HAS_PALETTE){

        size = bytestream_get_le32(&c->stream);

        if(size > rest){

            av_log(avctx, AV_LOG_ERROR, "Palette size is too big\n");

            return -1;

        }

        vb_decode_palette(c, size);

        rest -= size;

    }



    memcpy(c->pic.data[1], c->pal, AVPALETTE_SIZE);

    c->pic.palette_has_changed = flags & VB_HAS_PALETTE;



    outptr = c->pic.data[0];

    srcptr = c->frame;



    for(i = 0; i < avctx->height; i++){

        memcpy(outptr, srcptr, avctx->width);

        srcptr += avctx->width;

        outptr += c->pic.linesize[0];

    }



    FFSWAP(uint8_t*, c->frame, c->prev_frame);



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = c->pic;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static int pcx_decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                            AVPacket *avpkt)

{

    PCXContext * const s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame * const p = &s->picture;

    GetByteContext gb;

    int compressed, xmin, ymin, xmax, ymax, ret;

    unsigned int w, h, bits_per_pixel, bytes_per_line, nplanes, stride, y, x,

                 bytes_per_scanline;

    uint8_t *ptr, *scanline;



    if (avpkt->size < 128)

        return AVERROR_INVALIDDATA;



    bytestream2_init(&gb, avpkt->data, avpkt->size);



    if (bytestream2_get_byteu(&gb) != 0x0a || bytestream2_get_byteu(&gb) > 5) {

        av_log(avctx, AV_LOG_ERROR, "this is not PCX encoded data\n");

        return AVERROR_INVALIDDATA;

    }



    compressed = bytestream2_get_byteu(&gb);

    bits_per_pixel = bytestream2_get_byteu(&gb);

    xmin = bytestream2_get_le16u(&gb);

    ymin = bytestream2_get_le16u(&gb);

    xmax = bytestream2_get_le16u(&gb);

    ymax = bytestream2_get_le16u(&gb);

    avctx->sample_aspect_ratio.num = bytestream2_get_le16u(&gb);

    avctx->sample_aspect_ratio.den = bytestream2_get_le16u(&gb);



    if (xmax < xmin || ymax < ymin) {

        av_log(avctx, AV_LOG_ERROR, "invalid image dimensions\n");

        return AVERROR_INVALIDDATA;

    }



    w = xmax - xmin + 1;

    h = ymax - ymin + 1;



    bytestream2_skipu(&gb, 49);

    nplanes            = bytestream2_get_byteu(&gb);

    bytes_per_line     = bytestream2_get_le16u(&gb);

    bytes_per_scanline = nplanes * bytes_per_line;



    if (bytes_per_scanline < (w * bits_per_pixel * nplanes + 7) / 8) {

        av_log(avctx, AV_LOG_ERROR, "PCX data is corrupted\n");

        return AVERROR_INVALIDDATA;

    }



    switch ((nplanes<<8) + bits_per_pixel) {

        case 0x0308:

            avctx->pix_fmt = AV_PIX_FMT_RGB24;

            break;

        case 0x0108:

        case 0x0104:

        case 0x0102:

        case 0x0101:

        case 0x0401:

        case 0x0301:

        case 0x0201:

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "invalid PCX file\n");

            return AVERROR_INVALIDDATA;

    }



    bytestream2_skipu(&gb, 60);



    if (p->data[0])

        avctx->release_buffer(avctx, p);



    if ((ret = av_image_check_size(w, h, 0, avctx)) < 0)

        return ret;

    if (w != avctx->width || h != avctx->height)

        avcodec_set_dimensions(avctx, w, h);

    if ((ret = ff_get_buffer(avctx, p)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    p->pict_type = AV_PICTURE_TYPE_I;



    ptr    = p->data[0];

    stride = p->linesize[0];



    scanline = av_malloc(bytes_per_scanline);

    if (!scanline)

        return AVERROR(ENOMEM);



    if (nplanes == 3 && bits_per_pixel == 8) {

        for (y=0; y<h; y++) {

            pcx_rle_decode(&gb, scanline, bytes_per_scanline, compressed);



            for (x=0; x<w; x++) {

                ptr[3*x  ] = scanline[x                    ];

                ptr[3*x+1] = scanline[x+ bytes_per_line    ];

                ptr[3*x+2] = scanline[x+(bytes_per_line<<1)];

            }



            ptr += stride;

        }



    } else if (nplanes == 1 && bits_per_pixel == 8) {

        int palstart = avpkt->size - 769;



        for (y=0; y<h; y++, ptr+=stride) {

            pcx_rle_decode(&gb, scanline, bytes_per_scanline, compressed);

            memcpy(ptr, scanline, w);

        }



        if (bytestream2_tell(&gb) != palstart) {

            av_log(avctx, AV_LOG_WARNING, "image data possibly corrupted\n");

            bytestream2_seek(&gb, palstart, SEEK_SET);

        }

        if (bytestream2_get_byte(&gb) != 12) {

            av_log(avctx, AV_LOG_ERROR, "expected palette after image data\n");

            ret = AVERROR_INVALIDDATA;

            goto end;

        }



    } else if (nplanes == 1) {   /* all packed formats, max. 16 colors */

        GetBitContext s;



        for (y=0; y<h; y++) {

            init_get_bits8(&s, scanline, bytes_per_scanline);



            pcx_rle_decode(&gb, scanline, bytes_per_scanline, compressed);



            for (x=0; x<w; x++)

                ptr[x] = get_bits(&s, bits_per_pixel);

            ptr += stride;

        }



    } else {    /* planar, 4, 8 or 16 colors */

        int i;



        for (y=0; y<h; y++) {

            pcx_rle_decode(&gb, scanline, bytes_per_scanline, compressed);



            for (x=0; x<w; x++) {

                int m = 0x80 >> (x&7), v = 0;

                for (i=nplanes - 1; i>=0; i--) {

                    v <<= 1;

                    v  += !!(scanline[i*bytes_per_line + (x>>3)] & m);

                }

                ptr[x] = v;

            }

            ptr += stride;

        }

    }



    ret = bytestream2_tell(&gb);

    if (nplanes == 1 && bits_per_pixel == 8) {

        pcx_palette(&gb, (uint32_t *) p->data[1], 256);

        ret += 256 * 3;

    } else if (bits_per_pixel * nplanes == 1) {

        AV_WN32A(p->data[1]  , 0xFF000000);

        AV_WN32A(p->data[1]+4, 0xFFFFFFFF);

    } else if (bits_per_pixel < 8) {

        bytestream2_seek(&gb, 16, SEEK_SET);

        pcx_palette(&gb, (uint32_t *) p->data[1], 16);

    }



    *picture = s->picture;

    *got_frame = 1;



end:

    av_free(scanline);

    return ret;

}

static int mss4_decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MSS4Context *c = avctx->priv_data;

    GetBitContext gb;

    GetByteContext bc;

    uint8_t *dst[3];

    int width, height, quality, frame_type;

    int x, y, i, mb_width, mb_height, blk_type;

    int ret;



    if (buf_size < HEADER_SIZE) {

        av_log(avctx, AV_LOG_ERROR,

               "Frame should have at least %d bytes, got %d instead\n",

               HEADER_SIZE, buf_size);

        return AVERROR_INVALIDDATA;

    }



    bytestream2_init(&bc, buf, buf_size);

    width      = bytestream2_get_be16(&bc);

    height     = bytestream2_get_be16(&bc);

    bytestream2_skip(&bc, 2);

    quality    = bytestream2_get_byte(&bc);

    frame_type = bytestream2_get_byte(&bc);



    if (width > avctx->width ||

        height != avctx->height) {

        av_log(avctx, AV_LOG_ERROR, "Invalid frame dimensions %dx%d\n",

               width, height);

        return AVERROR_INVALIDDATA;

    }

    if (quality < 1 || quality > 100) {

        av_log(avctx, AV_LOG_ERROR, "Invalid quality setting %d\n", quality);

        return AVERROR_INVALIDDATA;

    }

    if ((frame_type & ~3) || frame_type == 3) {

        av_log(avctx, AV_LOG_ERROR, "Invalid frame type %d\n", frame_type);

        return AVERROR_INVALIDDATA;

    }



    if (frame_type != SKIP_FRAME && !bytestream2_get_bytes_left(&bc)) {

        av_log(avctx, AV_LOG_ERROR,

               "Empty frame found but it is not a skip frame.\n");

        return AVERROR_INVALIDDATA;

    }



    if ((ret = ff_reget_buffer(avctx, c->pic)) < 0)

        return ret;

    c->pic->key_frame = (frame_type == INTRA_FRAME);

    c->pic->pict_type = (frame_type == INTRA_FRAME) ? AV_PICTURE_TYPE_I

                                                   : AV_PICTURE_TYPE_P;

    if (frame_type == SKIP_FRAME) {

        *got_frame      = 1;

        if ((ret = av_frame_ref(data, c->pic)) < 0)

            return ret;



        return buf_size;

    }



    if (c->quality != quality) {

        c->quality = quality;

        for (i = 0; i < 2; i++)

            ff_mss34_gen_quant_mat(c->quant_mat[i], quality, !i);

    }



    init_get_bits8(&gb, buf + HEADER_SIZE, (buf_size - HEADER_SIZE));



    mb_width  = FFALIGN(width,  16) >> 4;

    mb_height = FFALIGN(height, 16) >> 4;

    dst[0] = c->pic->data[0];

    dst[1] = c->pic->data[1];

    dst[2] = c->pic->data[2];



    memset(c->prev_vec, 0, sizeof(c->prev_vec));

    for (y = 0; y < mb_height; y++) {

        memset(c->dc_cache, 0, sizeof(c->dc_cache));

        for (x = 0; x < mb_width; x++) {

            blk_type = decode012(&gb);

            switch (blk_type) {

            case DCT_BLOCK:

                if (mss4_decode_dct_block(c, &gb, dst, x, y) < 0) {

                    av_log(avctx, AV_LOG_ERROR,

                           "Error decoding DCT block %d,%d\n",

                           x, y);

                    return AVERROR_INVALIDDATA;

                }

                break;

            case IMAGE_BLOCK:

                if (mss4_decode_image_block(c, &gb, dst, x, y) < 0) {

                    av_log(avctx, AV_LOG_ERROR,

                           "Error decoding VQ block %d,%d\n",

                           x, y);

                    return AVERROR_INVALIDDATA;

                }

                break;

            case SKIP_BLOCK:

                if (frame_type == INTRA_FRAME) {

                    av_log(avctx, AV_LOG_ERROR, "Skip block in intra frame\n");

                    return AVERROR_INVALIDDATA;

                }

                break;

            }

            if (blk_type != DCT_BLOCK)

                mss4_update_dc_cache(c, x);

        }

        dst[0] += c->pic->linesize[0] * 16;

        dst[1] += c->pic->linesize[1] * 16;

        dst[2] += c->pic->linesize[2] * 16;

    }



    if ((ret = av_frame_ref(data, c->pic)) < 0)

        return ret;



    *got_frame      = 1;



    return buf_size;

}

static int ipvideo_decode_block_opcode_0x8(IpvideoContext *s, AVFrame *frame)
{
    int x, y;
    unsigned char P[4];
    unsigned int flags = 0;
    /* 2-color encoding for each 4x4 quadrant, or 2-color encoding on
     * either top and bottom or left and right halves */
    P[0] = bytestream2_get_byte(&s->stream_ptr);
    P[1] = bytestream2_get_byte(&s->stream_ptr);
    if (P[0] <= P[1]) {
        for (y = 0; y < 16; y++) {
            // new values for each 4x4 block
            if (!(y & 3)) {
                if (y) {
                    P[0]  = bytestream2_get_byte(&s->stream_ptr);
                    P[1]  = bytestream2_get_byte(&s->stream_ptr);
                flags = bytestream2_get_le16(&s->stream_ptr);
            for (x = 0; x < 4; x++, flags >>= 1)
                *s->pixel_ptr++ = P[flags & 1];
            s->pixel_ptr += s->stride - 4;
            // switch to right half
            if (y == 7) s->pixel_ptr -= 8 * s->stride - 4;
    } else {
        flags = bytestream2_get_le32(&s->stream_ptr);
        P[2] = bytestream2_get_byte(&s->stream_ptr);
        P[3] = bytestream2_get_byte(&s->stream_ptr);
        if (P[2] <= P[3]) {
            /* vertical split; left & right halves are 2-color encoded */
            for (y = 0; y < 16; y++) {
                for (x = 0; x < 4; x++, flags >>= 1)
                    *s->pixel_ptr++ = P[flags & 1];
                s->pixel_ptr += s->stride - 4;
                // switch to right half
                if (y == 7) {
                    s->pixel_ptr -= 8 * s->stride - 4;
                    P[0]  = P[2];
                    P[1]  = P[3];
                    flags = bytestream2_get_le32(&s->stream_ptr);
        } else {
            /* horizontal split; top & bottom halves are 2-color encoded */
            for (y = 0; y < 8; y++) {
                if (y == 4) {
                    P[0]  = P[2];
                    P[1]  = P[3];
                    flags = bytestream2_get_le32(&s->stream_ptr);
                for (x = 0; x < 8; x++, flags >>= 1)
                    *s->pixel_ptr++ = P[flags & 1];
                s->pixel_ptr += s->line_inc;
    /* report success */
    return 0;

static int ipvideo_decode_block_opcode_0x7(IpvideoContext *s, AVFrame *frame)
{
    int x, y;
    unsigned char P[2];
    unsigned int flags;
    /* 2-color encoding */
    P[0] = bytestream2_get_byte(&s->stream_ptr);
    P[1] = bytestream2_get_byte(&s->stream_ptr);
    if (P[0] <= P[1]) {
        /* need 8 more bytes from the stream */
        for (y = 0; y < 8; y++) {
            flags = bytestream2_get_byte(&s->stream_ptr) | 0x100;
            for (; flags != 1; flags >>= 1)
                *s->pixel_ptr++ = P[flags & 1];
            s->pixel_ptr += s->line_inc;
    } else {
        /* need 2 more bytes from the stream */
        flags = bytestream2_get_le16(&s->stream_ptr);
        for (y = 0; y < 8; y += 2) {
            for (x = 0; x < 8; x += 2, flags >>= 1) {
                s->pixel_ptr[x                ] =
                s->pixel_ptr[x + 1            ] =
                s->pixel_ptr[x +     s->stride] =
                s->pixel_ptr[x + 1 + s->stride] = P[flags & 1];
            s->pixel_ptr += s->stride * 2;
    /* report success */
    return 0;

static int ipvideo_decode_block_opcode_0xD(IpvideoContext *s)

{

    int y;

    unsigned char P[2];



    /* 4-color block encoding: each 4x4 block is a different color */

    CHECK_STREAM_PTR(4);



    for (y = 0; y < 8; y++) {

        if (!(y & 3)) {

            P[0] = *s->stream_ptr++;

            P[1] = *s->stream_ptr++;

        }

        memset(s->pixel_ptr,     P[0], 4);

        memset(s->pixel_ptr + 4, P[1], 4);

        s->pixel_ptr += s->stride;

    }



    /* report success */

    return 0;

}

static int ipvideo_decode_block_opcode_0xE(IpvideoContext *s)

{

    int y;

    unsigned char pix;



    /* 1-color encoding: the whole block is 1 solid color */

    CHECK_STREAM_PTR(1);

    pix = *s->stream_ptr++;



    for (y = 0; y < 8; y++) {

        memset(s->pixel_ptr, pix, 8);

        s->pixel_ptr += s->stride;

    }



    /* report success */

    return 0;

}

static int gdb_get_avr_reg(CPUState *env, uint8_t *mem_buf, int n)

{

    if (n < 32) {

#ifdef WORDS_BIGENDIAN

        stq_p(mem_buf, env->avr[n].u64[0]);

        stq_p(mem_buf+8, env->avr[n].u64[1]);

#else

        stq_p(mem_buf, env->avr[n].u64[1]);

        stq_p(mem_buf+8, env->avr[n].u64[0]);

#endif

        return 16;

    }

    if (n == 33) {

        stl_p(mem_buf, env->vscr);

        return 4;

    }

    if (n == 34) {

        stl_p(mem_buf, (uint32_t)env->spr[SPR_VRSAVE]);

        return 4;

    }

    return 0;

}

static int gdb_set_spe_reg(CPUState *env, uint8_t *mem_buf, int n)

{

    if (n < 32) {

#if defined(TARGET_PPC64)

        target_ulong lo = (uint32_t)env->gpr[n];

        target_ulong hi = (target_ulong)ldl_p(mem_buf) << 32;

        env->gpr[n] = lo | hi;

#else

        env->gprh[n] = ldl_p(mem_buf);

#endif

        return 4;

    }

    if (n == 33) {

        env->spe_acc = ldq_p(mem_buf);

        return 8;

    }

    if (n == 34) {

        /* SPEFSCR not implemented */

        return 4;

    }

    return 0;

}

static int gdb_set_float_reg(CPUPPCState *env, uint8_t *mem_buf, int n)

{

    if (n < 32) {

        env->fpr[n] = ldfq_p(mem_buf);

        return 8;

    }

    if (n == 32) {

        /* FPSCR not implemented  */

        return 4;

    }

    return 0;

}

static int gdb_get_spe_reg(CPUState *env, uint8_t *mem_buf, int n)

{

    if (n < 32) {

#if defined(TARGET_PPC64)

        stl_p(mem_buf, env->gpr[n] >> 32);

#else

        stl_p(mem_buf, env->gprh[n]);

#endif

        return 4;

    }

    if (n == 33) {

        stq_p(mem_buf, env->spe_acc);

        return 8;

    }

    if (n == 34) {

        /* SPEFSCR not implemented */

        memset(mem_buf, 0, 4);

        return 4;

    }

    return 0;

}

static void vga_draw_text(VGAState *s, int full_update)

{

    int cx, cy, cheight, cw, ch, cattr, height, width, ch_attr;

    int cx_min, cx_max, linesize, x_incr;

    uint32_t offset, fgcol, bgcol, v, cursor_offset;

    uint8_t *d1, *d, *src, *s1, *dest, *cursor_ptr;

    const uint8_t *font_ptr, *font_base[2];

    int dup9, line_offset, depth_index;

    uint32_t *palette;

    uint32_t *ch_attr_ptr;

    vga_draw_glyph8_func *vga_draw_glyph8;

    vga_draw_glyph9_func *vga_draw_glyph9;



    vga_dirty_log_stop(s);



    /* compute font data address (in plane 2) */

    v = s->sr[3];

    offset = (((v >> 4) & 1) | ((v << 1) & 6)) * 8192 * 4 + 2;

    if (offset != s->font_offsets[0]) {

        s->font_offsets[0] = offset;

        full_update = 1;

    }

    font_base[0] = s->vram_ptr + offset;



    offset = (((v >> 5) & 1) | ((v >> 1) & 6)) * 8192 * 4 + 2;

    font_base[1] = s->vram_ptr + offset;

    if (offset != s->font_offsets[1]) {

        s->font_offsets[1] = offset;

        full_update = 1;

    }

    if (s->plane_updated & (1 << 2)) {

        /* if the plane 2 was modified since the last display, it

           indicates the font may have been modified */

        s->plane_updated = 0;

        full_update = 1;

    }

    full_update |= update_basic_params(s);



    line_offset = s->line_offset;

    s1 = s->vram_ptr + (s->start_addr * 4);



    vga_get_text_resolution(s, &width, &height, &cw, &cheight);

    x_incr = cw * ((ds_get_bits_per_pixel(s->ds) + 7) >> 3);

    if ((height * width) > CH_ATTR_SIZE) {

        /* better than nothing: exit if transient size is too big */

        return;

    }



    if (width != s->last_width || height != s->last_height ||

        cw != s->last_cw || cheight != s->last_ch || s->last_depth) {

        s->last_scr_width = width * cw;

        s->last_scr_height = height * cheight;

        qemu_console_resize(s->ds, s->last_scr_width, s->last_scr_height);

        s->last_depth = 0;

        s->last_width = width;

        s->last_height = height;

        s->last_ch = cheight;

        s->last_cw = cw;

        full_update = 1;

    }

    s->rgb_to_pixel =

        rgb_to_pixel_dup_table[get_depth_index(s->ds)];

    full_update |= update_palette16(s);

    palette = s->last_palette;

    x_incr = cw * ((ds_get_bits_per_pixel(s->ds) + 7) >> 3);



    cursor_offset = ((s->cr[0x0e] << 8) | s->cr[0x0f]) - s->start_addr;

    if (cursor_offset != s->cursor_offset ||

        s->cr[0xa] != s->cursor_start ||

        s->cr[0xb] != s->cursor_end) {

      /* if the cursor position changed, we update the old and new

         chars */

        if (s->cursor_offset < CH_ATTR_SIZE)

            s->last_ch_attr[s->cursor_offset] = -1;

        if (cursor_offset < CH_ATTR_SIZE)

            s->last_ch_attr[cursor_offset] = -1;

        s->cursor_offset = cursor_offset;

        s->cursor_start = s->cr[0xa];

        s->cursor_end = s->cr[0xb];

    }

    cursor_ptr = s->vram_ptr + (s->start_addr + cursor_offset) * 4;



    depth_index = get_depth_index(s->ds);

    if (cw == 16)

        vga_draw_glyph8 = vga_draw_glyph16_table[depth_index];

    else

        vga_draw_glyph8 = vga_draw_glyph8_table[depth_index];

    vga_draw_glyph9 = vga_draw_glyph9_table[depth_index];



    dest = ds_get_data(s->ds);

    linesize = ds_get_linesize(s->ds);

    ch_attr_ptr = s->last_ch_attr;

    for(cy = 0; cy < height; cy++) {

        d1 = dest;

        src = s1;

        cx_min = width;

        cx_max = -1;

        for(cx = 0; cx < width; cx++) {

            ch_attr = *(uint16_t *)src;

            if (full_update || ch_attr != *ch_attr_ptr) {

                if (cx < cx_min)

                    cx_min = cx;

                if (cx > cx_max)

                    cx_max = cx;

                *ch_attr_ptr = ch_attr;

#ifdef WORDS_BIGENDIAN

                ch = ch_attr >> 8;

                cattr = ch_attr & 0xff;

#else

                ch = ch_attr & 0xff;

                cattr = ch_attr >> 8;

#endif

                font_ptr = font_base[(cattr >> 3) & 1];

                font_ptr += 32 * 4 * ch;

                bgcol = palette[cattr >> 4];

                fgcol = palette[cattr & 0x0f];

                if (cw != 9) {

                    vga_draw_glyph8(d1, linesize,

                                    font_ptr, cheight, fgcol, bgcol);

                } else {

                    dup9 = 0;

                    if (ch >= 0xb0 && ch <= 0xdf && (s->ar[0x10] & 0x04))

                        dup9 = 1;

                    vga_draw_glyph9(d1, linesize,

                                    font_ptr, cheight, fgcol, bgcol, dup9);

                }

                if (src == cursor_ptr &&

                    !(s->cr[0x0a] & 0x20)) {

                    int line_start, line_last, h;

                    /* draw the cursor */

                    line_start = s->cr[0x0a] & 0x1f;

                    line_last = s->cr[0x0b] & 0x1f;

                    /* XXX: check that */

                    if (line_last > cheight - 1)

                        line_last = cheight - 1;

                    if (line_last >= line_start && line_start < cheight) {

                        h = line_last - line_start + 1;

                        d = d1 + linesize * line_start;

                        if (cw != 9) {

                            vga_draw_glyph8(d, linesize,

                                            cursor_glyph, h, fgcol, bgcol);

                        } else {

                            vga_draw_glyph9(d, linesize,

                                            cursor_glyph, h, fgcol, bgcol, 1);

                        }

                    }

                }

            }

            d1 += x_incr;

            src += 4;

            ch_attr_ptr++;

        }

        if (cx_max != -1) {

            dpy_update(s->ds, cx_min * cw, cy * cheight,

                       (cx_max - cx_min + 1) * cw, cheight);

        }

        dest += linesize * cheight;

        s1 += line_offset;

    }

}

static void vga_update_text(void *opaque, console_ch_t *chardata)
{
    VGACommonState *s =  opaque;
    int graphic_mode, i, cursor_offset, cursor_visible;
    int cw, cheight, width, height, size, c_min, c_max;
    uint32_t *src;
    console_ch_t *dst, val;
    char msg_buffer[80];
    int full_update = 0;
    if (!(s->ar_index & 0x20)) {
        graphic_mode = GMODE_BLANK;
    } else {
        graphic_mode = s->gr[6] & 1;
    }
    if (graphic_mode != s->graphic_mode) {
        s->graphic_mode = graphic_mode;
        full_update = 1;
    }
    if (s->last_width == -1) {
        s->last_width = 0;
        full_update = 1;
    }
    switch (graphic_mode) {
    case GMODE_TEXT:
        /* TODO: update palette */
        full_update |= update_basic_params(s);
        /* total width & height */
        cheight = (s->cr[9] & 0x1f) + 1;
        cw = 8;
        if (!(s->sr[1] & 0x01))
            cw = 9;
        if (s->sr[1] & 0x08)
            cw = 16; /* NOTE: no 18 pixel wide */
        width = (s->cr[0x01] + 1);
        if (s->cr[0x06] == 100) {
            /* ugly hack for CGA 160x100x16 - explain me the logic */
            height = 100;
        } else {
            height = s->cr[0x12] | 
                ((s->cr[0x07] & 0x02) << 7) | 
                ((s->cr[0x07] & 0x40) << 3);
            height = (height + 1) / cheight;
        }
        size = (height * width);
        if (size > CH_ATTR_SIZE) {
            if (!full_update)
                return;
            snprintf(msg_buffer, sizeof(msg_buffer), "%i x %i Text mode",
                     width, height);
            break;
        }
        if (width != s->last_width || height != s->last_height ||
            cw != s->last_cw || cheight != s->last_ch) {
            s->last_scr_width = width * cw;
            s->last_scr_height = height * cheight;
            s->ds->surface->width = width;
            s->ds->surface->height = height;
            dpy_resize(s->ds);
            s->last_width = width;
            s->last_height = height;
            s->last_ch = cheight;
            s->last_cw = cw;
            full_update = 1;
        }
        /* Update "hardware" cursor */
        cursor_offset = ((s->cr[0x0e] << 8) | s->cr[0x0f]) - s->start_addr;
        if (cursor_offset != s->cursor_offset ||
            s->cr[0xa] != s->cursor_start ||
            s->cr[0xb] != s->cursor_end || full_update) {
            cursor_visible = !(s->cr[0xa] & 0x20);
            if (cursor_visible && cursor_offset < size && cursor_offset >= 0)
                dpy_cursor(s->ds,
                           TEXTMODE_X(cursor_offset),
                           TEXTMODE_Y(cursor_offset));
            else
                dpy_cursor(s->ds, -1, -1);
            s->cursor_offset = cursor_offset;
            s->cursor_start = s->cr[0xa];
            s->cursor_end = s->cr[0xb];
        }
        src = (uint32_t *) s->vram_ptr + s->start_addr;
        dst = chardata;
        if (full_update) {
            for (i = 0; i < size; src ++, dst ++, i ++)
                console_write_ch(dst, VMEM2CHTYPE(le32_to_cpu(*src)));
            dpy_update(s->ds, 0, 0, width, height);
        } else {
            c_max = 0;
            for (i = 0; i < size; src ++, dst ++, i ++) {
                console_write_ch(&val, VMEM2CHTYPE(le32_to_cpu(*src)));
                if (*dst != val) {
                    *dst = val;
                    c_max = i;
                    break;
                }
            }
            c_min = i;
            for (; i < size; src ++, dst ++, i ++) {
                console_write_ch(&val, VMEM2CHTYPE(le32_to_cpu(*src)));
                if (*dst != val) {
                    *dst = val;
                    c_max = i;
                }
            }
            if (c_min <= c_max) {
                i = TEXTMODE_Y(c_min);
                dpy_update(s->ds, 0, i, width, TEXTMODE_Y(c_max) - i + 1);
            }
        }
        return;
    case GMODE_GRAPH:
        if (!full_update)
            return;
        s->get_resolution(s, &width, &height);
        snprintf(msg_buffer, sizeof(msg_buffer), "%i x %i Graphic mode",
                 width, height);
        break;
    case GMODE_BLANK:
    default:
        if (!full_update)
            return;
        snprintf(msg_buffer, sizeof(msg_buffer), "VGA Blank mode");
        break;
    }
    /* Display a message */
    s->last_width = 60;
    s->last_height = height = 3;
    dpy_cursor(s->ds, -1, -1);
    s->ds->surface->width = s->last_width;
    s->ds->surface->height = height;
    dpy_resize(s->ds);
    for (dst = chardata, i = 0; i < s->last_width * height; i ++)
        console_write_ch(dst ++, ' ');
    size = strlen(msg_buffer);
    width = (s->last_width - size) / 2;
    dst = chardata + s->last_width + width;
    for (i = 0; i < size; i ++)
        console_write_ch(dst ++, 0x00200100 | msg_buffer[i]);
    dpy_update(s->ds, 0, 0, s->last_width, height);
}

static void vga_update_text(void *opaque, console_ch_t *chardata)

{

    VGACommonState *s =  opaque;

    int graphic_mode, i, cursor_offset, cursor_visible;

    int cw, cheight, width, height, size, c_min, c_max;

    uint32_t *src;

    console_ch_t *dst, val;

    char msg_buffer[80];

    int full_update = 0;



    qemu_flush_coalesced_mmio_buffer();



    if (!(s->ar_index & 0x20)) {

        graphic_mode = GMODE_BLANK;

    } else {

        graphic_mode = s->gr[VGA_GFX_MISC] & VGA_GR06_GRAPHICS_MODE;

    }

    if (graphic_mode != s->graphic_mode) {

        s->graphic_mode = graphic_mode;

        full_update = 1;

    }

    if (s->last_width == -1) {

        s->last_width = 0;

        full_update = 1;

    }



    switch (graphic_mode) {

    case GMODE_TEXT:

        /* TODO: update palette */

        full_update |= update_basic_params(s);



        /* total width & height */

        cheight = (s->cr[VGA_CRTC_MAX_SCAN] & 0x1f) + 1;

        cw = 8;

        if (!(s->sr[VGA_SEQ_CLOCK_MODE] & VGA_SR01_CHAR_CLK_8DOTS)) {

            cw = 9;

        }

        if (s->sr[VGA_SEQ_CLOCK_MODE] & 0x08) {

            cw = 16; /* NOTE: no 18 pixel wide */

        }

        width = (s->cr[VGA_CRTC_H_DISP] + 1);

        if (s->cr[VGA_CRTC_V_TOTAL] == 100) {

            /* ugly hack for CGA 160x100x16 - explain me the logic */

            height = 100;

        } else {

            height = s->cr[VGA_CRTC_V_DISP_END] |

                ((s->cr[VGA_CRTC_OVERFLOW] & 0x02) << 7) |

                ((s->cr[VGA_CRTC_OVERFLOW] & 0x40) << 3);

            height = (height + 1) / cheight;

        }



        size = (height * width);

        if (size > CH_ATTR_SIZE) {

            if (!full_update)

                return;



            snprintf(msg_buffer, sizeof(msg_buffer), "%i x %i Text mode",

                     width, height);

            break;

        }



        if (width != s->last_width || height != s->last_height ||

            cw != s->last_cw || cheight != s->last_ch) {

            s->last_scr_width = width * cw;

            s->last_scr_height = height * cheight;

            qemu_console_resize(s->con, s->last_scr_width, s->last_scr_height);

            dpy_text_resize(s->con, width, height);

            s->last_depth = 0;

            s->last_width = width;

            s->last_height = height;

            s->last_ch = cheight;

            s->last_cw = cw;

            full_update = 1;

        }



        if (full_update) {

            s->full_update_gfx = 1;

        }

        if (s->full_update_text) {

            s->full_update_text = 0;

            full_update |= 1;

        }



        /* Update "hardware" cursor */

        cursor_offset = ((s->cr[VGA_CRTC_CURSOR_HI] << 8) |

                         s->cr[VGA_CRTC_CURSOR_LO]) - s->start_addr;

        if (cursor_offset != s->cursor_offset ||

            s->cr[VGA_CRTC_CURSOR_START] != s->cursor_start ||

            s->cr[VGA_CRTC_CURSOR_END] != s->cursor_end || full_update) {

            cursor_visible = !(s->cr[VGA_CRTC_CURSOR_START] & 0x20);

            if (cursor_visible && cursor_offset < size && cursor_offset >= 0)

                dpy_text_cursor(s->con,

                                TEXTMODE_X(cursor_offset),

                                TEXTMODE_Y(cursor_offset));

            else

                dpy_text_cursor(s->con, -1, -1);

            s->cursor_offset = cursor_offset;

            s->cursor_start = s->cr[VGA_CRTC_CURSOR_START];

            s->cursor_end = s->cr[VGA_CRTC_CURSOR_END];

        }



        src = (uint32_t *) s->vram_ptr + s->start_addr;

        dst = chardata;



        if (full_update) {

            for (i = 0; i < size; src ++, dst ++, i ++)

                console_write_ch(dst, VMEM2CHTYPE(le32_to_cpu(*src)));



            dpy_text_update(s->con, 0, 0, width, height);

        } else {

            c_max = 0;



            for (i = 0; i < size; src ++, dst ++, i ++) {

                console_write_ch(&val, VMEM2CHTYPE(le32_to_cpu(*src)));

                if (*dst != val) {

                    *dst = val;

                    c_max = i;

                    break;

                }

            }

            c_min = i;

            for (; i < size; src ++, dst ++, i ++) {

                console_write_ch(&val, VMEM2CHTYPE(le32_to_cpu(*src)));

                if (*dst != val) {

                    *dst = val;

                    c_max = i;

                }

            }



            if (c_min <= c_max) {

                i = TEXTMODE_Y(c_min);

                dpy_text_update(s->con, 0, i, width, TEXTMODE_Y(c_max) - i + 1);

            }

        }



        return;

    case GMODE_GRAPH:

        if (!full_update)

            return;



        s->get_resolution(s, &width, &height);

        snprintf(msg_buffer, sizeof(msg_buffer), "%i x %i Graphic mode",

                 width, height);

        break;

    case GMODE_BLANK:

    default:

        if (!full_update)

            return;



        snprintf(msg_buffer, sizeof(msg_buffer), "VGA Blank mode");

        break;

    }



    /* Display a message */

    s->last_width = 60;

    s->last_height = height = 3;

    dpy_text_cursor(s->con, -1, -1);

    dpy_text_resize(s->con, s->last_width, height);



    for (dst = chardata, i = 0; i < s->last_width * height; i ++)

        console_write_ch(dst ++, ' ');



    size = strlen(msg_buffer);

    width = (s->last_width - size) / 2;

    dst = chardata + s->last_width + width;

    for (i = 0; i < size; i ++)

        console_write_ch(dst ++, 0x00200100 | msg_buffer[i]);



    dpy_text_update(s->con, 0, 0, s->last_width, height);

}

static void vga_draw_graphic(VGACommonState *s, int full_update)

{

    int y1, y, update, linesize, y_start, double_scan, mask, depth;

    int width, height, shift_control, line_offset, bwidth, bits;

    ram_addr_t page0, page1, page_min, page_max;

    int disp_width, multi_scan, multi_run;

    uint8_t *d;

    uint32_t v, addr1, addr;

    vga_draw_line_func *vga_draw_line;



    full_update |= update_basic_params(s);



    if (!full_update)

        vga_sync_dirty_bitmap(s);



    s->get_resolution(s, &width, &height);

    disp_width = width;



    shift_control = (s->gr[VGA_GFX_MODE] >> 5) & 3;

    double_scan = (s->cr[VGA_CRTC_MAX_SCAN] >> 7);

    if (shift_control != 1) {

        multi_scan = (((s->cr[VGA_CRTC_MAX_SCAN] & 0x1f) + 1) << double_scan)

            - 1;

    } else {

        /* in CGA modes, multi_scan is ignored */

        /* XXX: is it correct ? */

        multi_scan = double_scan;

    }

    multi_run = multi_scan;

    if (shift_control != s->shift_control ||

        double_scan != s->double_scan) {

        full_update = 1;

        s->shift_control = shift_control;

        s->double_scan = double_scan;

    }



    if (shift_control == 0) {

        if (s->sr[VGA_SEQ_CLOCK_MODE] & 8) {

            disp_width <<= 1;

        }

    } else if (shift_control == 1) {

        if (s->sr[VGA_SEQ_CLOCK_MODE] & 8) {

            disp_width <<= 1;

        }

    }



    depth = s->get_bpp(s);

    if (s->line_offset != s->last_line_offset ||

        disp_width != s->last_width ||

        height != s->last_height ||

        s->last_depth != depth) {

#if defined(HOST_WORDS_BIGENDIAN) == defined(TARGET_WORDS_BIGENDIAN)

        if (depth == 16 || depth == 32) {

#else

        if (depth == 32) {

#endif

            qemu_free_displaysurface(s->ds);

            s->ds->surface = qemu_create_displaysurface_from(disp_width, height, depth,

                    s->line_offset,

                    s->vram_ptr + (s->start_addr * 4));

#if defined(HOST_WORDS_BIGENDIAN) != defined(TARGET_WORDS_BIGENDIAN)

            s->ds->surface->pf = qemu_different_endianness_pixelformat(depth);

#endif

            dpy_gfx_resize(s->ds);

        } else {

            qemu_console_resize(s->ds, disp_width, height);

        }

        s->last_scr_width = disp_width;

        s->last_scr_height = height;

        s->last_width = disp_width;

        s->last_height = height;

        s->last_line_offset = s->line_offset;

        s->last_depth = depth;

        full_update = 1;

    } else if (is_buffer_shared(s->ds->surface) &&

               (full_update || ds_get_data(s->ds) != s->vram_ptr

                + (s->start_addr * 4))) {

        qemu_free_displaysurface(s->ds);

        s->ds->surface = qemu_create_displaysurface_from(disp_width,

                height, depth,

                s->line_offset,

                s->vram_ptr + (s->start_addr * 4));

        dpy_gfx_setdata(s->ds);

    }



    s->rgb_to_pixel =

        rgb_to_pixel_dup_table[get_depth_index(s->ds)];



    if (shift_control == 0) {

        full_update |= update_palette16(s);

        if (s->sr[VGA_SEQ_CLOCK_MODE] & 8) {

            v = VGA_DRAW_LINE4D2;

        } else {

            v = VGA_DRAW_LINE4;

        }

        bits = 4;

    } else if (shift_control == 1) {

        full_update |= update_palette16(s);

        if (s->sr[VGA_SEQ_CLOCK_MODE] & 8) {

            v = VGA_DRAW_LINE2D2;

        } else {

            v = VGA_DRAW_LINE2;

        }

        bits = 4;

    } else {

        switch(s->get_bpp(s)) {

        default:

        case 0:

            full_update |= update_palette256(s);

            v = VGA_DRAW_LINE8D2;

            bits = 4;

            break;

        case 8:

            full_update |= update_palette256(s);

            v = VGA_DRAW_LINE8;

            bits = 8;

            break;

        case 15:

            v = VGA_DRAW_LINE15;

            bits = 16;

            break;

        case 16:

            v = VGA_DRAW_LINE16;

            bits = 16;

            break;

        case 24:

            v = VGA_DRAW_LINE24;

            bits = 24;

            break;

        case 32:

            v = VGA_DRAW_LINE32;

            bits = 32;

            break;

        }

    }

    vga_draw_line = vga_draw_line_table[v * NB_DEPTHS + get_depth_index(s->ds)];



    if (!is_buffer_shared(s->ds->surface) && s->cursor_invalidate)

        s->cursor_invalidate(s);



    line_offset = s->line_offset;

#if 0

    printf("w=%d h=%d v=%d line_offset=%d cr[0x09]=0x%02x cr[0x17]=0x%02x linecmp=%d sr[0x01]=0x%02x\n",

           width, height, v, line_offset, s->cr[9], s->cr[VGA_CRTC_MODE],

           s->line_compare, s->sr[VGA_SEQ_CLOCK_MODE]);

#endif

    addr1 = (s->start_addr * 4);

    bwidth = (width * bits + 7) / 8;

    y_start = -1;

    page_min = -1;

    page_max = 0;

    d = ds_get_data(s->ds);

    linesize = ds_get_linesize(s->ds);

    y1 = 0;

    for(y = 0; y < height; y++) {

        addr = addr1;

        if (!(s->cr[VGA_CRTC_MODE] & 1)) {

            int shift;

            /* CGA compatibility handling */

            shift = 14 + ((s->cr[VGA_CRTC_MODE] >> 6) & 1);

            addr = (addr & ~(1 << shift)) | ((y1 & 1) << shift);

        }

        if (!(s->cr[VGA_CRTC_MODE] & 2)) {

            addr = (addr & ~0x8000) | ((y1 & 2) << 14);

        }

        update = full_update;

        page0 = addr;

        page1 = addr + bwidth - 1;

        update |= memory_region_get_dirty(&s->vram, page0, page1 - page0,

                                          DIRTY_MEMORY_VGA);

        /* explicit invalidation for the hardware cursor */

        update |= (s->invalidated_y_table[y >> 5] >> (y & 0x1f)) & 1;

        if (update) {

            if (y_start < 0)

                y_start = y;

            if (page0 < page_min)

                page_min = page0;

            if (page1 > page_max)

                page_max = page1;

            if (!(is_buffer_shared(s->ds->surface))) {

                vga_draw_line(s, d, s->vram_ptr + addr, width);

                if (s->cursor_draw_line)

                    s->cursor_draw_line(s, d, y);

            }

        } else {

            if (y_start >= 0) {

                /* flush to display */

                dpy_gfx_update(s->ds, 0, y_start,

                               disp_width, y - y_start);

                y_start = -1;

            }

        }

        if (!multi_run) {

            mask = (s->cr[VGA_CRTC_MODE] & 3) ^ 3;

            if ((y1 & mask) == mask)

                addr1 += line_offset;

            y1++;

            multi_run = multi_scan;

        } else {

            multi_run--;

        }

        /* line compare acts on the displayed lines */

        if (y == s->line_compare)

            addr1 = 0;

        d += linesize;

    }

    if (y_start >= 0) {

        /* flush to display */

        dpy_gfx_update(s->ds, 0, y_start,

                       disp_width, y - y_start);

    }

    /* reset modified pages */

    if (page_max >= page_min) {

        memory_region_reset_dirty(&s->vram,

                                  page_min,

                                  page_max - page_min,

                                  DIRTY_MEMORY_VGA);

    }

    memset(s->invalidated_y_table, 0, ((height + 31) >> 5) * 4);

}

uint64_t qemu_get_be64(QEMUFile *f)

{

