static void decor_c(int32_t *dst, const int32_t *src, int coeff, ptrdiff_t len)

{

    int i;



    for (i = 0; i < len; i++)

        dst[i] += (int)(src[i] * (SUINT)coeff + (1 << 2)) >> 3;

}

static void conv411(uint8_t *dst, int dst_wrap, 
                    uint8_t *src, int src_wrap,
                    int width, int height)
{
    int w, c;
    uint8_t *s1, *s2, *d;
    for(;height > 0; height--) {
        s1 = src;
        s2 = src + src_wrap;
        d = dst;
        for(w = width;w > 0; w--) {
            c = (s1[0] + s2[0]) >> 1;
            d[0] = c;
            d[1] = c;
            s1++;
            s2++;
            d += 2;
        }
        src += src_wrap * 2;
        dst += dst_wrap;
    }
}

static void rgba32_to_rgb24(AVPicture *dst, AVPicture *src,

                            int width, int height)

{

    const uint8_t *s;

    uint8_t *d;

    int src_wrap, dst_wrap, j, y;

    unsigned int v;



    s = src->data[0];

    src_wrap = src->linesize[0] - width * 4;



    d = dst->data[0];

    dst_wrap = dst->linesize[0] - width * 3;



    for(y=0;y<height;y++) {

        for(j = 0;j < width; j++) {

            v = *(uint32_t *)s;

            s += 4;

            d[0] = v >> 16;

            d[1] = v >> 8;

            d[2] = v;

            d += 3;

        }

        s += src_wrap;

        d += dst_wrap;

    }

}

static void dmix_sub_c(int32_t *dst, const int32_t *src, int coeff, ptrdiff_t len)

{

    int i;



    for (i = 0; i < len; i++)

        dst[i] -= mul15(src[i], coeff);

}

qemu_irq *arm_gic_init(uint32_t base, qemu_irq parent_irq)

{

    gic_state *s;

    qemu_irq *qi;

