static int matroska_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    MatroskaDemuxContext *matroska = s->priv_data;

    EbmlList *attachements_list = &matroska->attachments;

    MatroskaAttachement *attachements;

    EbmlList *chapters_list = &matroska->chapters;

    MatroskaChapter *chapters;

    MatroskaTrack *tracks;

    EbmlList *index_list;

    MatroskaIndex *index;

    int index_scale = 1;

    Ebml ebml = { 0 };

    AVStream *st;

    int i, j;



    matroska->ctx = s;



    /* First read the EBML header. */

    if (ebml_parse(matroska, ebml_syntax, &ebml)

        || ebml.version > EBML_VERSION       || ebml.max_size > sizeof(uint64_t)

        || ebml.id_length > sizeof(uint32_t) || strcmp(ebml.doctype, "matroska")

        || ebml.doctype_version > 2) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "EBML header using unsupported features\n"

               "(EBML version %"PRIu64", doctype %s, doc version %"PRIu64")\n",

               ebml.version, ebml.doctype, ebml.doctype_version);

        return AVERROR_NOFMT;

    }

    ebml_free(ebml_syntax, &ebml);



    /* The next thing is a segment. */

    if (ebml_parse(matroska, matroska_segments, matroska) < 0)

        return -1;

    matroska_execute_seekhead(matroska);



    if (matroska->duration)

        matroska->ctx->duration = matroska->duration * matroska->time_scale

                                  * 1000 / AV_TIME_BASE;

    if (matroska->title)

        strncpy(matroska->ctx->title, matroska->title,

                sizeof(matroska->ctx->title)-1);

    matroska_convert_tags(s, &matroska->tags);



    tracks = matroska->tracks.elem;

    for (i=0; i < matroska->tracks.nb_elem; i++) {

        MatroskaTrack *track = &tracks[i];

        enum CodecID codec_id = CODEC_ID_NONE;

        EbmlList *encodings_list = &tracks->encodings;

        MatroskaTrackEncoding *encodings = encodings_list->elem;

        uint8_t *extradata = NULL;

        int extradata_size = 0;

        int extradata_offset = 0;



        /* Apply some sanity checks. */

        if (track->type != MATROSKA_TRACK_TYPE_VIDEO &&

            track->type != MATROSKA_TRACK_TYPE_AUDIO &&

            track->type != MATROSKA_TRACK_TYPE_SUBTITLE) {

            av_log(matroska->ctx, AV_LOG_INFO,

                   "Unknown or unsupported track type %"PRIu64"\n",

                   track->type);

            continue;

        }

        if (track->codec_id == NULL)

            continue;



        if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

            if (!track->default_duration)

                track->default_duration = 1000000000/track->video.frame_rate;

            if (!track->video.display_width)

                track->video.display_width = track->video.pixel_width;

            if (!track->video.display_height)

                track->video.display_height = track->video.pixel_height;

        } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

            if (!track->audio.out_samplerate)

                track->audio.out_samplerate = track->audio.samplerate;

        }

        if (encodings_list->nb_elem > 1) {

            av_log(matroska->ctx, AV_LOG_ERROR,

                   "Multiple combined encodings no supported");

        } else if (encodings_list->nb_elem == 1) {

            if (encodings[0].type ||

                (encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_HEADERSTRIP &&

#ifdef CONFIG_ZLIB

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_ZLIB &&

#endif

#ifdef CONFIG_BZLIB

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_BZLIB &&

#endif

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_LZO)) {

                encodings[0].scope = 0;

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Unsupported encoding type");

            } else if (track->codec_priv.size && encodings[0].scope&2) {

                uint8_t *codec_priv = track->codec_priv.data;

                int offset = matroska_decode_buffer(&track->codec_priv.data,

                                                    &track->codec_priv.size,

                                                    track);

                if (offset < 0) {

                    track->codec_priv.data = NULL;

                    track->codec_priv.size = 0;

                    av_log(matroska->ctx, AV_LOG_ERROR,

                           "Failed to decode codec private data\n");

                } else if (offset > 0) {

                    track->codec_priv.data = av_malloc(track->codec_priv.size + offset);

                    memcpy(track->codec_priv.data,

                           encodings[0].compression.settings.data, offset);

                    memcpy(track->codec_priv.data+offset, codec_priv,

                           track->codec_priv.size);

                    track->codec_priv.size += offset;

                }

                if (codec_priv != track->codec_priv.data)

                    av_free(codec_priv);

            }

        }



        for(j=0; ff_mkv_codec_tags[j].id != CODEC_ID_NONE; j++){

            if(!strncmp(ff_mkv_codec_tags[j].str, track->codec_id,

                        strlen(ff_mkv_codec_tags[j].str))){

                codec_id= ff_mkv_codec_tags[j].id;

                break;

            }

        }



        st = track->stream = av_new_stream(s, 0);

        if (st == NULL)

            return AVERROR(ENOMEM);



        if (!strcmp(track->codec_id, "V_MS/VFW/FOURCC")

            && track->codec_priv.size >= 40

            && track->codec_priv.data != NULL) {

            track->video.fourcc = AV_RL32(track->codec_priv.data + 16);

            codec_id = codec_get_id(codec_bmp_tags, track->video.fourcc);

        } else if (!strcmp(track->codec_id, "A_MS/ACM")

                   && track->codec_priv.size >= 18

                   && track->codec_priv.data != NULL) {

            uint16_t tag = AV_RL16(track->codec_priv.data);

            codec_id = codec_get_id(codec_wav_tags, tag);

        } else if (!strcmp(track->codec_id, "V_QUICKTIME")

                   && (track->codec_priv.size >= 86)

                   && (track->codec_priv.data != NULL)) {

            track->video.fourcc = AV_RL32(track->codec_priv.data);

            codec_id=codec_get_id(codec_movvideo_tags, track->video.fourcc);

        } else if (codec_id == CODEC_ID_PCM_S16BE) {

            switch (track->audio.bitdepth) {

            case  8:  codec_id = CODEC_ID_PCM_U8;     break;

            case 24:  codec_id = CODEC_ID_PCM_S24BE;  break;

            case 32:  codec_id = CODEC_ID_PCM_S32BE;  break;

            }

        } else if (codec_id == CODEC_ID_PCM_S16LE) {

            switch (track->audio.bitdepth) {

            case  8:  codec_id = CODEC_ID_PCM_U8;     break;

            case 24:  codec_id = CODEC_ID_PCM_S24LE;  break;

            case 32:  codec_id = CODEC_ID_PCM_S32LE;  break;

            }

        } else if (codec_id==CODEC_ID_PCM_F32LE && track->audio.bitdepth==64) {

            codec_id = CODEC_ID_PCM_F64LE;

        } else if (codec_id == CODEC_ID_AAC && !track->codec_priv.size) {

            int profile = matroska_aac_profile(track->codec_id);

            int sri = matroska_aac_sri(track->audio.samplerate);

            extradata = av_malloc(5);

            if (extradata == NULL)

                return AVERROR(ENOMEM);

            extradata[0] = (profile << 3) | ((sri&0x0E) >> 1);

            extradata[1] = ((sri&0x01) << 7) | (track->audio.channels<<3);

            if (strstr(track->codec_id, "SBR")) {

                sri = matroska_aac_sri(track->audio.out_samplerate);

                extradata[2] = 0x56;

                extradata[3] = 0xE5;

                extradata[4] = 0x80 | (sri<<3);

                extradata_size = 5;

            } else

                extradata_size = 2;

        } else if (codec_id == CODEC_ID_TTA) {

            ByteIOContext b;

            extradata_size = 30;

            extradata = av_mallocz(extradata_size);

            if (extradata == NULL)

                return AVERROR(ENOMEM);

            init_put_byte(&b, extradata, extradata_size, 1,

                          NULL, NULL, NULL, NULL);

            put_buffer(&b, "TTA1", 4);

            put_le16(&b, 1);

            put_le16(&b, track->audio.channels);

            put_le16(&b, track->audio.bitdepth);

            put_le32(&b, track->audio.out_samplerate);

            put_le32(&b, matroska->ctx->duration * track->audio.out_samplerate);

        } else if (codec_id == CODEC_ID_RV10 || codec_id == CODEC_ID_RV20 ||

                   codec_id == CODEC_ID_RV30 || codec_id == CODEC_ID_RV40) {

            extradata_offset = 26;

            track->codec_priv.size -= extradata_offset;

        } else if (codec_id == CODEC_ID_RA_144) {

            track->audio.out_samplerate = 8000;

            track->audio.channels = 1;

        } else if (codec_id == CODEC_ID_RA_288 || codec_id == CODEC_ID_COOK ||

                   codec_id == CODEC_ID_ATRAC3) {

            ByteIOContext b;



            init_put_byte(&b, track->codec_priv.data,track->codec_priv.size,

                          0, NULL, NULL, NULL, NULL);

            url_fskip(&b, 24);

            track->audio.coded_framesize = get_be32(&b);

            url_fskip(&b, 12);

            track->audio.sub_packet_h    = get_be16(&b);

            track->audio.frame_size      = get_be16(&b);

            track->audio.sub_packet_size = get_be16(&b);

            track->audio.buf = av_malloc(track->audio.frame_size * track->audio.sub_packet_h);

            if (codec_id == CODEC_ID_RA_288) {

                st->codec->block_align = track->audio.coded_framesize;

                track->codec_priv.size = 0;

            } else {

                st->codec->block_align = track->audio.sub_packet_size;

                extradata_offset = 78;

                track->codec_priv.size -= extradata_offset;

            }

        }



        if (codec_id == CODEC_ID_NONE)

            av_log(matroska->ctx, AV_LOG_INFO,

                   "Unknown/unsupported CodecID %s.\n", track->codec_id);



        if (track->time_scale < 0.01)

            track->time_scale = 1.0;

        av_set_pts_info(st, 64, matroska->time_scale*track->time_scale, 1000*1000*1000); /* 64 bit pts in ns */



        st->codec->codec_id = codec_id;

        st->start_time = 0;

        if (strcmp(track->language, "und"))

            av_strlcpy(st->language, track->language, 4);



        if (track->flag_default)

            st->disposition |= AV_DISPOSITION_DEFAULT;



        if (track->default_duration)

            av_reduce(&st->codec->time_base.num, &st->codec->time_base.den,

                      track->default_duration, 1000000000, 30000);



        if(extradata){

            st->codec->extradata = extradata;

            st->codec->extradata_size = extradata_size;

        } else if(track->codec_priv.data && track->codec_priv.size > 0){

            st->codec->extradata = av_malloc(track->codec_priv.size);

            if(st->codec->extradata == NULL)

                return AVERROR(ENOMEM);

            st->codec->extradata_size = track->codec_priv.size;

            memcpy(st->codec->extradata,

                   track->codec_priv.data + extradata_offset,

                   track->codec_priv.size);

        }



        if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

            st->codec->codec_type = CODEC_TYPE_VIDEO;

            st->codec->codec_tag  = track->video.fourcc;

            st->codec->width  = track->video.pixel_width;

            st->codec->height = track->video.pixel_height;

            av_reduce(&st->sample_aspect_ratio.num,

                      &st->sample_aspect_ratio.den,

                      st->codec->height * track->video.display_width,

                      st->codec-> width * track->video.display_height,

                      255);

            st->need_parsing = AVSTREAM_PARSE_HEADERS;

        } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

            st->codec->codec_type = CODEC_TYPE_AUDIO;

            st->codec->sample_rate = track->audio.out_samplerate;

            st->codec->channels = track->audio.channels;

        } else if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE) {

            st->codec->codec_type = CODEC_TYPE_SUBTITLE;

        }

    }



    attachements = attachements_list->elem;

    for (j=0; j<attachements_list->nb_elem; j++) {

        if (!(attachements[j].filename && attachements[j].mime &&

              attachements[j].bin.data && attachements[j].bin.size > 0)) {

            av_log(matroska->ctx, AV_LOG_ERROR, "incomplete attachment\n");

        } else {

            AVStream *st = av_new_stream(s, 0);

            if (st == NULL)

                break;

            st->filename          = av_strdup(attachements[j].filename);

            st->codec->codec_id = CODEC_ID_NONE;

            st->codec->codec_type = CODEC_TYPE_ATTACHMENT;

            st->codec->extradata  = av_malloc(attachements[j].bin.size);

            if(st->codec->extradata == NULL)

                break;

            st->codec->extradata_size = attachements[j].bin.size;

            memcpy(st->codec->extradata, attachements[j].bin.data, attachements[j].bin.size);



            for (i=0; ff_mkv_mime_tags[i].id != CODEC_ID_NONE; i++) {

                if (!strncmp(ff_mkv_mime_tags[i].str, attachements[j].mime,

                             strlen(ff_mkv_mime_tags[i].str))) {

                    st->codec->codec_id = ff_mkv_mime_tags[i].id;

                    break;

                }

            }

        }

    }



    chapters = chapters_list->elem;

    for (i=0; i<chapters_list->nb_elem; i++)

        if (chapters[i].start != AV_NOPTS_VALUE && chapters[i].uid)

            ff_new_chapter(s, chapters[i].uid, (AVRational){1, 1000000000},

                           chapters[i].start, chapters[i].end,

                           chapters[i].title);



    index_list = &matroska->index;

    index = index_list->elem;

    if (index_list->nb_elem

        && index[0].time > 100000000000000/matroska->time_scale) {

        av_log(matroska->ctx, AV_LOG_WARNING, "Working around broken index.\n");

        index_scale = matroska->time_scale;

    }

    for (i=0; i<index_list->nb_elem; i++) {

        EbmlList *pos_list = &index[i].pos;

        MatroskaIndexPos *pos = pos_list->elem;

        for (j=0; j<pos_list->nb_elem; j++) {

            MatroskaTrack *track = matroska_find_track_by_num(matroska,

                                                              pos[j].track);

            if (track && track->stream)

                av_add_index_entry(track->stream,

                                   pos[j].pos + matroska->segment_start,

                                   index[i].time/index_scale, 0, 0,

                                   AVINDEX_KEYFRAME);

        }

    }



    return 0;

}

static int matroska_parse_tracks(AVFormatContext *s)

{

    MatroskaDemuxContext *matroska = s->priv_data;

    MatroskaTrack *tracks = matroska->tracks.elem;

    AVStream *st;

    int i, j, ret;

    int k;



    for (i = 0; i < matroska->tracks.nb_elem; i++) {

        MatroskaTrack *track = &tracks[i];

        enum AVCodecID codec_id = AV_CODEC_ID_NONE;

        EbmlList *encodings_list = &track->encodings;

        MatroskaTrackEncoding *encodings = encodings_list->elem;

        uint8_t *extradata = NULL;

        int extradata_size = 0;

        int extradata_offset = 0;

        uint32_t fourcc = 0;

        AVIOContext b;

        char* key_id_base64 = NULL;

        int bit_depth = -1;



        /* Apply some sanity checks. */

        if (track->type != MATROSKA_TRACK_TYPE_VIDEO &&

            track->type != MATROSKA_TRACK_TYPE_AUDIO &&

            track->type != MATROSKA_TRACK_TYPE_SUBTITLE &&

            track->type != MATROSKA_TRACK_TYPE_METADATA) {

            av_log(matroska->ctx, AV_LOG_INFO,

                   "Unknown or unsupported track type %"PRIu64"\n",

                   track->type);

            continue;

        }

        if (!track->codec_id)

            continue;



        if (track->audio.samplerate < 0 || track->audio.samplerate > INT_MAX ||

            isnan(track->audio.samplerate)) {

            av_log(matroska->ctx, AV_LOG_WARNING,

                   "Invalid sample rate %f, defaulting to 8000 instead.\n",

                   track->audio.samplerate);

            track->audio.samplerate = 8000;

        }



        if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

            if (!track->default_duration && track->video.frame_rate > 0)

                track->default_duration = 1000000000 / track->video.frame_rate;

            if (track->video.display_width == -1)

                track->video.display_width = track->video.pixel_width;

            if (track->video.display_height == -1)

                track->video.display_height = track->video.pixel_height;

            if (track->video.color_space.size == 4)

                fourcc = AV_RL32(track->video.color_space.data);

        } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

            if (!track->audio.out_samplerate)

                track->audio.out_samplerate = track->audio.samplerate;

        }

        if (encodings_list->nb_elem > 1) {

            av_log(matroska->ctx, AV_LOG_ERROR,

                   "Multiple combined encodings not supported");

        } else if (encodings_list->nb_elem == 1) {

            if (encodings[0].type) {

                if (encodings[0].encryption.key_id.size > 0) {

                    /* Save the encryption key id to be stored later as a

                       metadata tag. */

                    const int b64_size = AV_BASE64_SIZE(encodings[0].encryption.key_id.size);

                    key_id_base64 = av_malloc(b64_size);

                    if (key_id_base64 == NULL)

                        return AVERROR(ENOMEM);



                    av_base64_encode(key_id_base64, b64_size,

                                     encodings[0].encryption.key_id.data,

                                     encodings[0].encryption.key_id.size);

                } else {

                    encodings[0].scope = 0;

                    av_log(matroska->ctx, AV_LOG_ERROR,

                           "Unsupported encoding type");

                }

            } else if (

#if CONFIG_ZLIB

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_ZLIB  &&

#endif

#if CONFIG_BZLIB

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_BZLIB &&

#endif

#if CONFIG_LZO

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_LZO   &&

#endif

                 encodings[0].compression.algo != MATROSKA_TRACK_ENCODING_COMP_HEADERSTRIP) {

                encodings[0].scope = 0;

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Unsupported encoding type");

            } else if (track->codec_priv.size && encodings[0].scope & 2) {

                uint8_t *codec_priv = track->codec_priv.data;

                int ret = matroska_decode_buffer(&track->codec_priv.data,

                                                 &track->codec_priv.size,

                                                 track);

                if (ret < 0) {

                    track->codec_priv.data = NULL;

                    track->codec_priv.size = 0;

                    av_log(matroska->ctx, AV_LOG_ERROR,

                           "Failed to decode codec private data\n");

                }



                if (codec_priv != track->codec_priv.data)

                    av_free(codec_priv);

            }

        }



        for (j = 0; ff_mkv_codec_tags[j].id != AV_CODEC_ID_NONE; j++) {

            if (!strncmp(ff_mkv_codec_tags[j].str, track->codec_id,

                         strlen(ff_mkv_codec_tags[j].str))) {

                codec_id = ff_mkv_codec_tags[j].id;

                break;

            }

        }



        st = track->stream = avformat_new_stream(s, NULL);

        if (!st) {

            av_free(key_id_base64);

            return AVERROR(ENOMEM);

        }



        if (key_id_base64) {

            /* export encryption key id as base64 metadata tag */

            av_dict_set(&st->metadata, "enc_key_id", key_id_base64, 0);

            av_freep(&key_id_base64);

        }



        if (!strcmp(track->codec_id, "V_MS/VFW/FOURCC") &&

             track->codec_priv.size >= 40               &&

            track->codec_priv.data) {

            track->ms_compat    = 1;

            bit_depth           = AV_RL16(track->codec_priv.data + 14);

            fourcc              = AV_RL32(track->codec_priv.data + 16);

            codec_id            = ff_codec_get_id(ff_codec_bmp_tags,

                                                  fourcc);

            if (!codec_id)

                codec_id        = ff_codec_get_id(ff_codec_movvideo_tags,

                                                  fourcc);

            extradata_offset    = 40;

        } else if (!strcmp(track->codec_id, "A_MS/ACM") &&

                   track->codec_priv.size >= 14         &&

                   track->codec_priv.data) {

            int ret;

            ffio_init_context(&b, track->codec_priv.data,

                              track->codec_priv.size,

                              0, NULL, NULL, NULL, NULL);

            ret = ff_get_wav_header(s, &b, st->codecpar, track->codec_priv.size, 0);

            if (ret < 0)

                return ret;

            codec_id         = st->codecpar->codec_id;

            fourcc           = st->codecpar->codec_tag;

            extradata_offset = FFMIN(track->codec_priv.size, 18);

        } else if (!strcmp(track->codec_id, "A_QUICKTIME")

                   /* Normally 36, but allow noncompliant private data */

                   && (track->codec_priv.size >= 32)

                   && (track->codec_priv.data)) {

            uint16_t sample_size;

            int ret = get_qt_codec(track, &fourcc, &codec_id);

            if (ret < 0)

                return ret;

            sample_size = AV_RB16(track->codec_priv.data + 26);

            if (fourcc == 0) {

                if (sample_size == 8) {

                    fourcc = MKTAG('r','a','w',' ');

                    codec_id = ff_codec_get_id(ff_codec_movaudio_tags, fourcc);

                } else if (sample_size == 16) {

                    fourcc = MKTAG('t','w','o','s');

                    codec_id = ff_codec_get_id(ff_codec_movaudio_tags, fourcc);

                }

            }

            if ((fourcc == MKTAG('t','w','o','s') ||

                    fourcc == MKTAG('s','o','w','t')) &&

                    sample_size == 8)

                codec_id = AV_CODEC_ID_PCM_S8;

        } else if (!strcmp(track->codec_id, "V_QUICKTIME") &&

                   (track->codec_priv.size >= 21)          &&

                   (track->codec_priv.data)) {

            int ret = get_qt_codec(track, &fourcc, &codec_id);

            if (ret < 0)

                return ret;

            if (codec_id == AV_CODEC_ID_NONE && AV_RL32(track->codec_priv.data+4) == AV_RL32("SMI ")) {

                fourcc = MKTAG('S','V','Q','3');

                codec_id = ff_codec_get_id(ff_codec_movvideo_tags, fourcc);

            }

            if (codec_id == AV_CODEC_ID_NONE)

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "mov FourCC not found %s.\n", av_fourcc2str(fourcc));

            if (track->codec_priv.size >= 86) {

                bit_depth = AV_RB16(track->codec_priv.data + 82);

                ffio_init_context(&b, track->codec_priv.data,

                                  track->codec_priv.size,

                                  0, NULL, NULL, NULL, NULL);

                if (ff_get_qtpalette(codec_id, &b, track->palette)) {

                    bit_depth &= 0x1F;

                    track->has_palette = 1;

                }

            }

        } else if (codec_id == AV_CODEC_ID_PCM_S16BE) {

            switch (track->audio.bitdepth) {

            case  8:

                codec_id = AV_CODEC_ID_PCM_U8;

                break;

            case 24:

                codec_id = AV_CODEC_ID_PCM_S24BE;

                break;

            case 32:

                codec_id = AV_CODEC_ID_PCM_S32BE;

                break;

            }

        } else if (codec_id == AV_CODEC_ID_PCM_S16LE) {

            switch (track->audio.bitdepth) {

            case  8:

                codec_id = AV_CODEC_ID_PCM_U8;

                break;

            case 24:

                codec_id = AV_CODEC_ID_PCM_S24LE;

                break;

            case 32:

                codec_id = AV_CODEC_ID_PCM_S32LE;

                break;

            }

        } else if (codec_id == AV_CODEC_ID_PCM_F32LE &&

                   track->audio.bitdepth == 64) {

            codec_id = AV_CODEC_ID_PCM_F64LE;

        } else if (codec_id == AV_CODEC_ID_AAC && !track->codec_priv.size) {

            int profile = matroska_aac_profile(track->codec_id);

            int sri     = matroska_aac_sri(track->audio.samplerate);

            extradata   = av_mallocz(5 + AV_INPUT_BUFFER_PADDING_SIZE);

            if (!extradata)

                return AVERROR(ENOMEM);

            extradata[0] = (profile << 3) | ((sri & 0x0E) >> 1);

            extradata[1] = ((sri & 0x01) << 7) | (track->audio.channels << 3);

            if (strstr(track->codec_id, "SBR")) {

                sri            = matroska_aac_sri(track->audio.out_samplerate);

                extradata[2]   = 0x56;

                extradata[3]   = 0xE5;

                extradata[4]   = 0x80 | (sri << 3);

                extradata_size = 5;

            } else

                extradata_size = 2;

        } else if (codec_id == AV_CODEC_ID_ALAC && track->codec_priv.size && track->codec_priv.size < INT_MAX - 12 - AV_INPUT_BUFFER_PADDING_SIZE) {

            /* Only ALAC's magic cookie is stored in Matroska's track headers.

             * Create the "atom size", "tag", and "tag version" fields the

             * decoder expects manually. */

            extradata_size = 12 + track->codec_priv.size;

            extradata      = av_mallocz(extradata_size +

                                        AV_INPUT_BUFFER_PADDING_SIZE);

            if (!extradata)

                return AVERROR(ENOMEM);

            AV_WB32(extradata, extradata_size);

            memcpy(&extradata[4], "alac", 4);

            AV_WB32(&extradata[8], 0);

            memcpy(&extradata[12], track->codec_priv.data,

                   track->codec_priv.size);

        } else if (codec_id == AV_CODEC_ID_TTA) {

            extradata_size = 30;

            extradata      = av_mallocz(extradata_size + AV_INPUT_BUFFER_PADDING_SIZE);

            if (!extradata)

                return AVERROR(ENOMEM);

            ffio_init_context(&b, extradata, extradata_size, 1,

                              NULL, NULL, NULL, NULL);

            avio_write(&b, "TTA1", 4);

            avio_wl16(&b, 1);

            if (track->audio.channels > UINT16_MAX ||

                track->audio.bitdepth > UINT16_MAX) {

                av_log(matroska->ctx, AV_LOG_WARNING,

                       "Too large audio channel number %"PRIu64

                       " or bitdepth %"PRIu64". Skipping track.\n",

                       track->audio.channels, track->audio.bitdepth);

                av_freep(&extradata);

                if (matroska->ctx->error_recognition & AV_EF_EXPLODE)

                    return AVERROR_INVALIDDATA;

                else

                    continue;

            }

            avio_wl16(&b, track->audio.channels);

            avio_wl16(&b, track->audio.bitdepth);

            if (track->audio.out_samplerate < 0 || track->audio.out_samplerate > INT_MAX)

                return AVERROR_INVALIDDATA;

            avio_wl32(&b, track->audio.out_samplerate);

            avio_wl32(&b, av_rescale((matroska->duration * matroska->time_scale),

                                     track->audio.out_samplerate,

                                     AV_TIME_BASE * 1000));

        } else if (codec_id == AV_CODEC_ID_RV10 ||

                   codec_id == AV_CODEC_ID_RV20 ||

                   codec_id == AV_CODEC_ID_RV30 ||

                   codec_id == AV_CODEC_ID_RV40) {

            extradata_offset = 26;

        } else if (codec_id == AV_CODEC_ID_RA_144) {

            track->audio.out_samplerate = 8000;

            track->audio.channels       = 1;

        } else if ((codec_id == AV_CODEC_ID_RA_288 ||

                    codec_id == AV_CODEC_ID_COOK   ||

                    codec_id == AV_CODEC_ID_ATRAC3 ||

                    codec_id == AV_CODEC_ID_SIPR)

                      && track->codec_priv.data) {

            int flavor;



            ffio_init_context(&b, track->codec_priv.data,

                              track->codec_priv.size,

                              0, NULL, NULL, NULL, NULL);

            avio_skip(&b, 22);

            flavor                       = avio_rb16(&b);

            track->audio.coded_framesize = avio_rb32(&b);

            avio_skip(&b, 12);

            track->audio.sub_packet_h    = avio_rb16(&b);

            track->audio.frame_size      = avio_rb16(&b);

            track->audio.sub_packet_size = avio_rb16(&b);

            if (flavor                        < 0 ||

                track->audio.coded_framesize <= 0 ||

                track->audio.sub_packet_h    <= 0 ||

                track->audio.frame_size      <= 0 ||

                track->audio.sub_packet_size <= 0 && codec_id != AV_CODEC_ID_SIPR)

                return AVERROR_INVALIDDATA;

            track->audio.buf = av_malloc_array(track->audio.sub_packet_h,

                                               track->audio.frame_size);

            if (!track->audio.buf)

                return AVERROR(ENOMEM);

            if (codec_id == AV_CODEC_ID_RA_288) {

                st->codecpar->block_align = track->audio.coded_framesize;

                track->codec_priv.size = 0;

            } else {

                if (codec_id == AV_CODEC_ID_SIPR && flavor < 4) {

                    static const int sipr_bit_rate[4] = { 6504, 8496, 5000, 16000 };

                    track->audio.sub_packet_size = ff_sipr_subpk_size[flavor];

                    st->codecpar->bit_rate          = sipr_bit_rate[flavor];

                }

                st->codecpar->block_align = track->audio.sub_packet_size;

                extradata_offset       = 78;

            }

        } else if (codec_id == AV_CODEC_ID_FLAC && track->codec_priv.size) {

            ret = matroska_parse_flac(s, track, &extradata_offset);

            if (ret < 0)

                return ret;

        } else if (codec_id == AV_CODEC_ID_PRORES && track->codec_priv.size == 4) {

            fourcc = AV_RL32(track->codec_priv.data);

        }

        track->codec_priv.size -= extradata_offset;



        if (codec_id == AV_CODEC_ID_NONE)

            av_log(matroska->ctx, AV_LOG_INFO,

                   "Unknown/unsupported AVCodecID %s.\n", track->codec_id);



        if (track->time_scale < 0.01)

            track->time_scale = 1.0;

        avpriv_set_pts_info(st, 64, matroska->time_scale * track->time_scale,

                            1000 * 1000 * 1000);    /* 64 bit pts in ns */



        /* convert the delay from ns to the track timebase */

        track->codec_delay_in_track_tb = av_rescale_q(track->codec_delay,

                                          (AVRational){ 1, 1000000000 },

                                          st->time_base);



        st->codecpar->codec_id = codec_id;



        if (strcmp(track->language, "und"))

            av_dict_set(&st->metadata, "language", track->language, 0);

        av_dict_set(&st->metadata, "title", track->name, 0);



        if (track->flag_default)

            st->disposition |= AV_DISPOSITION_DEFAULT;

        if (track->flag_forced)

            st->disposition |= AV_DISPOSITION_FORCED;



        if (!st->codecpar->extradata) {

            if (extradata) {

                st->codecpar->extradata      = extradata;

                st->codecpar->extradata_size = extradata_size;

            } else if (track->codec_priv.data && track->codec_priv.size > 0) {

                if (ff_alloc_extradata(st->codecpar, track->codec_priv.size))

                    return AVERROR(ENOMEM);

                memcpy(st->codecpar->extradata,

                       track->codec_priv.data + extradata_offset,

                       track->codec_priv.size);

            }

        }



        if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

            MatroskaTrackPlane *planes = track->operation.combine_planes.elem;

            int display_width_mul  = 1;

            int display_height_mul = 1;



            st->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;

            st->codecpar->codec_tag  = fourcc;

            if (bit_depth >= 0)

                st->codecpar->bits_per_coded_sample = bit_depth;

            st->codecpar->width      = track->video.pixel_width;

            st->codecpar->height     = track->video.pixel_height;



            if (track->video.interlaced == MATROSKA_VIDEO_INTERLACE_FLAG_INTERLACED)

                st->codecpar->field_order = mkv_field_order(matroska, track->video.field_order);

            else if (track->video.interlaced == MATROSKA_VIDEO_INTERLACE_FLAG_PROGRESSIVE)

                st->codecpar->field_order = AV_FIELD_PROGRESSIVE;



            if (track->video.stereo_mode && track->video.stereo_mode < MATROSKA_VIDEO_STEREOMODE_TYPE_NB)

                mkv_stereo_mode_display_mul(track->video.stereo_mode, &display_width_mul, &display_height_mul);



            if (track->video.display_unit < MATROSKA_VIDEO_DISPLAYUNIT_UNKNOWN) {

                av_reduce(&st->sample_aspect_ratio.num,

                          &st->sample_aspect_ratio.den,

                          st->codecpar->height * track->video.display_width  * display_width_mul,

                          st->codecpar->width  * track->video.display_height * display_height_mul,

                          255);

            }

            if (st->codecpar->codec_id != AV_CODEC_ID_HEVC)

                st->need_parsing = AVSTREAM_PARSE_HEADERS;



            if (track->default_duration) {

                av_reduce(&st->avg_frame_rate.num, &st->avg_frame_rate.den,

                          1000000000, track->default_duration, 30000);

#if FF_API_R_FRAME_RATE

                if (   st->avg_frame_rate.num < st->avg_frame_rate.den * 1000LL

                    && st->avg_frame_rate.num > st->avg_frame_rate.den * 5LL)

                    st->r_frame_rate = st->avg_frame_rate;

#endif

            }



            /* export stereo mode flag as metadata tag */

            if (track->video.stereo_mode && track->video.stereo_mode < MATROSKA_VIDEO_STEREOMODE_TYPE_NB)

                av_dict_set(&st->metadata, "stereo_mode", ff_matroska_video_stereo_mode[track->video.stereo_mode], 0);



            /* export alpha mode flag as metadata tag  */

            if (track->video.alpha_mode)

                av_dict_set(&st->metadata, "alpha_mode", "1", 0);



            /* if we have virtual track, mark the real tracks */

            for (j=0; j < track->operation.combine_planes.nb_elem; j++) {

                char buf[32];

                if (planes[j].type >= MATROSKA_VIDEO_STEREO_PLANE_COUNT)

                    continue;

                snprintf(buf, sizeof(buf), "%s_%d",

                         ff_matroska_video_stereo_plane[planes[j].type], i);

                for (k=0; k < matroska->tracks.nb_elem; k++)

                    if (planes[j].uid == tracks[k].uid && tracks[k].stream) {

                        av_dict_set(&tracks[k].stream->metadata,

                                    "stereo_mode", buf, 0);

                        break;

                    }

            }

            // add stream level stereo3d side data if it is a supported format

            if (track->video.stereo_mode < MATROSKA_VIDEO_STEREOMODE_TYPE_NB &&

                track->video.stereo_mode != 10 && track->video.stereo_mode != 12) {

                int ret = ff_mkv_stereo3d_conv(st, track->video.stereo_mode);

                if (ret < 0)

                    return ret;

            }



            ret = mkv_parse_video_color(st, track);

            if (ret < 0)

                return ret;

            ret = mkv_parse_video_projection(st, track);

            if (ret < 0)

                return ret;

        } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

            st->codecpar->codec_type  = AVMEDIA_TYPE_AUDIO;

            st->codecpar->codec_tag   = fourcc;

            st->codecpar->sample_rate = track->audio.out_samplerate;

            st->codecpar->channels    = track->audio.channels;

            if (!st->codecpar->bits_per_coded_sample)

                st->codecpar->bits_per_coded_sample = track->audio.bitdepth;

            if (st->codecpar->codec_id == AV_CODEC_ID_MP3)

                st->need_parsing = AVSTREAM_PARSE_FULL;

            else if (st->codecpar->codec_id != AV_CODEC_ID_AAC)

                st->need_parsing = AVSTREAM_PARSE_HEADERS;

            if (track->codec_delay > 0) {

                st->codecpar->initial_padding = av_rescale_q(track->codec_delay,

                                                             (AVRational){1, 1000000000},

                                                             (AVRational){1, st->codecpar->codec_id == AV_CODEC_ID_OPUS ?

                                                                             48000 : st->codecpar->sample_rate});

            }

            if (track->seek_preroll > 0) {

                st->codecpar->seek_preroll = av_rescale_q(track->seek_preroll,

                                                          (AVRational){1, 1000000000},

                                                          (AVRational){1, st->codecpar->sample_rate});

            }

        } else if (codec_id == AV_CODEC_ID_WEBVTT) {

            st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;



            if (!strcmp(track->codec_id, "D_WEBVTT/CAPTIONS")) {

                st->disposition |= AV_DISPOSITION_CAPTIONS;

            } else if (!strcmp(track->codec_id, "D_WEBVTT/DESCRIPTIONS")) {

                st->disposition |= AV_DISPOSITION_DESCRIPTIONS;

            } else if (!strcmp(track->codec_id, "D_WEBVTT/METADATA")) {

                st->disposition |= AV_DISPOSITION_METADATA;

            }

        } else if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE) {

            st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;

            if (st->codecpar->codec_id == AV_CODEC_ID_ASS)

                matroska->contains_ssa = 1;

        }

    }



    return 0;

}

matroska_read_header (AVFormatContext    *s,

                      AVFormatParameters *ap)

{

    MatroskaDemuxContext *matroska = s->priv_data;

    char *doctype;

    int version, last_level, res = 0;

    uint32_t id;



    matroska->ctx = s;



    /* First read the EBML header. */

    doctype = NULL;

    if ((res = ebml_read_header(matroska, &doctype, &version)) < 0)

        return res;

    if ((doctype == NULL) || strcmp(doctype, "matroska")) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "Wrong EBML doctype ('%s' != 'matroska').\n",

               doctype ? doctype : "(none)");

        if (doctype)

            av_free(doctype);

        return AVERROR_NOFMT;

    }

    av_free(doctype);

    if (version > 2) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "Matroska demuxer version 2 too old for file version %d\n",

               version);

        return AVERROR_NOFMT;

    }



    /* The next thing is a segment. */

    while (1) {

        if (!(id = ebml_peek_id(matroska, &last_level)))

            return AVERROR_IO;

        if (id == MATROSKA_ID_SEGMENT)

            break;



        /* oi! */

        av_log(matroska->ctx, AV_LOG_INFO,

               "Expected a Segment ID (0x%x), but received 0x%x!\n",

               MATROSKA_ID_SEGMENT, id);

        if ((res = ebml_read_skip(matroska)) < 0)

            return res;

    }



    /* We now have a Matroska segment.

     * Seeks are from the beginning of the segment,

     * after the segment ID/length. */

    if ((res = ebml_read_master(matroska, &id)) < 0)

        return res;

    matroska->segment_start = url_ftell(&s->pb);



    matroska->time_scale = 1000000;

    /* we've found our segment, start reading the different contents in here */

    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR_IO;

            break;

        } else if (matroska->level_up) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* stream info */

            case MATROSKA_ID_INFO: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_info(matroska);

                break;

            }



            /* track info headers */

            case MATROSKA_ID_TRACKS: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_tracks(matroska);

                break;

            }



            /* stream index */

            case MATROSKA_ID_CUES: {

                if (!matroska->index_parsed) {

                    if ((res = ebml_read_master(matroska, &id)) < 0)

                        break;

                    res = matroska_parse_index(matroska);

                } else

                    res = ebml_read_skip(matroska);

                break;

            }



            /* metadata */

            case MATROSKA_ID_TAGS: {

                if (!matroska->metadata_parsed) {

                    if ((res = ebml_read_master(matroska, &id)) < 0)

                        break;

                    res = matroska_parse_metadata(matroska);

                } else

                    res = ebml_read_skip(matroska);

                break;

            }



            /* file index (if seekable, seek to Cues/Tags to parse it) */

            case MATROSKA_ID_SEEKHEAD: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_seekhead(matroska);

                break;

            }



            case MATROSKA_ID_CLUSTER: {

                /* Do not read the master - this will be done in the next

                 * call to matroska_read_packet. */

                res = 1;

                break;

            }



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown matroska file header ID 0x%x\n", id);

            /* fall-through */



            case EBML_ID_VOID:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    /* Have we found a cluster? */

    if (ebml_peek_id(matroska, NULL) == MATROSKA_ID_CLUSTER) {

        int i, j;

        MatroskaTrack *track;

        AVStream *st;



        for (i = 0; i < matroska->num_tracks; i++) {

            enum CodecID codec_id = CODEC_ID_NONE;

            uint8_t *extradata = NULL;

            int extradata_size = 0;

            int extradata_offset = 0;

            track = matroska->tracks[i];



            /* libavformat does not really support subtitles.

             * Also apply some sanity checks. */

            if ((track->type == MATROSKA_TRACK_TYPE_SUBTITLE) ||

                (track->codec_id == NULL))

                continue;



            for(j=0; codec_tags[j].str; j++){

                if(!strncmp(codec_tags[j].str, track->codec_id,

                            strlen(codec_tags[j].str))){

                    codec_id= codec_tags[j].id;

                    break;

                }

            }



            /* Set the FourCC from the CodecID. */

            /* This is the MS compatibility mode which stores a

             * BITMAPINFOHEADER in the CodecPrivate. */

            if (!strcmp(track->codec_id,

                        MATROSKA_CODEC_ID_VIDEO_VFW_FOURCC) &&

                (track->codec_priv_size >= 40) &&

                (track->codec_priv != NULL)) {

                unsigned char *p;



                /* Offset of biCompression. Stored in LE. */

                p = (unsigned char *)track->codec_priv + 16;

                ((MatroskaVideoTrack *)track)->fourcc = (p[3] << 24) |

                                 (p[2] << 16) | (p[1] << 8) | p[0];

                codec_id = codec_get_id(codec_bmp_tags, ((MatroskaVideoTrack *)track)->fourcc);



            }



            /* This is the MS compatibility mode which stores a

             * WAVEFORMATEX in the CodecPrivate. */

            else if (!strcmp(track->codec_id,

                             MATROSKA_CODEC_ID_AUDIO_ACM) &&

                (track->codec_priv_size >= 18) &&

                (track->codec_priv != NULL)) {

                unsigned char *p;

                uint16_t tag;



                /* Offset of wFormatTag. Stored in LE. */

                p = (unsigned char *)track->codec_priv;

                tag = (p[1] << 8) | p[0];

                codec_id = codec_get_id(codec_wav_tags, tag);



            }



            else if (codec_id == CODEC_ID_MPEG1VIDEO ||

                     codec_id == CODEC_ID_MPEG2VIDEO ||

                     codec_id == CODEC_ID_MPEG4      ||

                     codec_id == CODEC_ID_MSMPEG4V3  ||

                     codec_id == CODEC_ID_H264) {

                track->flags |= MATROSKA_TRACK_REORDER;

            }



            else if (codec_id == CODEC_ID_AAC && !track->codec_priv_size) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *) track;

                int profile = matroska_aac_profile(track->codec_id);

                int sri = matroska_aac_sri(audiotrack->internal_samplerate);

                extradata = av_malloc(5);

                if (extradata == NULL)

                    return AVERROR_NOMEM;

                extradata[0] = (profile << 3) | ((sri&0x0E) >> 1);

                extradata[1] = ((sri&0x01) << 7) | (audiotrack->channels<<3);

                if (strstr(track->codec_id, "SBR")) {

                    sri = matroska_aac_sri(audiotrack->samplerate);

                    extradata[2] = 0x56;

                    extradata[3] = 0xE5;

                    extradata[4] = 0x80 | (sri<<3);

                    extradata_size = 5;

                } else {

                    extradata_size = 2;

                }

                track->default_duration = 1024*1000 / audiotrack->internal_samplerate;

            }



            else if (codec_id == CODEC_ID_TTA) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *) track;

                ByteIOContext b;

                extradata_size = 30;

                extradata = av_mallocz(extradata_size);

                if (extradata == NULL)

                    return AVERROR_NOMEM;

                init_put_byte(&b, extradata, extradata_size, 1,

                              NULL, NULL, NULL, NULL);

                put_buffer(&b, (uint8_t *) "TTA1", 4);

                put_le16(&b, 1);

                put_le16(&b, audiotrack->channels);

                put_le16(&b, audiotrack->bitdepth);

                put_le32(&b, audiotrack->samplerate);

                put_le32(&b, matroska->ctx->duration * audiotrack->samplerate);

            }



            else if (codec_id == CODEC_ID_RV10 || codec_id == CODEC_ID_RV20 ||

                     codec_id == CODEC_ID_RV30 || codec_id == CODEC_ID_RV40) {

                extradata_offset = 26;

                track->codec_priv_size -= extradata_offset;

                track->flags |= MATROSKA_TRACK_REAL_V;

            }



            if (codec_id == CODEC_ID_NONE) {

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown/unsupported CodecID %s.\n",

                       track->codec_id);

            }



            track->stream_index = matroska->num_streams;



            matroska->num_streams++;

            st = av_new_stream(s, track->stream_index);

            if (st == NULL)

                return AVERROR_NOMEM;

            av_set_pts_info(st, 64, matroska->time_scale, 1000*1000*1000); /* 64 bit pts in ns */



            st->codec->codec_id = codec_id;



            if (track->default_duration)

                av_reduce(&st->codec->time_base.num, &st->codec->time_base.den,

                          track->default_duration, 1000, 30000);



            if(extradata){

                st->codec->extradata = extradata;

                st->codec->extradata_size = extradata_size;

            } else if(track->codec_priv && track->codec_priv_size > 0){

                st->codec->extradata = av_malloc(track->codec_priv_size);

                if(st->codec->extradata == NULL)

                    return AVERROR_NOMEM;

                st->codec->extradata_size = track->codec_priv_size;

                memcpy(st->codec->extradata,track->codec_priv+extradata_offset,

                       track->codec_priv_size);

            }



            if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

                MatroskaVideoTrack *videotrack = (MatroskaVideoTrack *)track;



                st->codec->codec_type = CODEC_TYPE_VIDEO;

                st->codec->codec_tag = videotrack->fourcc;

                st->codec->width = videotrack->pixel_width;

                st->codec->height = videotrack->pixel_height;

                if (videotrack->display_width == 0)

                    videotrack->display_width= videotrack->pixel_width;

                if (videotrack->display_height == 0)

                    videotrack->display_height= videotrack->pixel_height;

                av_reduce(&st->codec->sample_aspect_ratio.num,

                          &st->codec->sample_aspect_ratio.den,

                          st->codec->height * videotrack->display_width,

                          st->codec-> width * videotrack->display_height,

                          255);

            } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *)track;



                st->codec->codec_type = CODEC_TYPE_AUDIO;

                st->codec->sample_rate = audiotrack->samplerate;

                st->codec->channels = audiotrack->channels;

            } else if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE) {

                st->codec->codec_type = CODEC_TYPE_SUBTITLE;

            }



            /* What do we do with private data? E.g. for Vorbis. */

        }

        res = 0;

    }



    return res;

}

matroska_add_stream (MatroskaDemuxContext *matroska)

{

    int res = 0;

    uint32_t id;

    MatroskaTrack *track;



    av_log(matroska->ctx, AV_LOG_DEBUG, "parsing track, adding stream..,\n");



    /* Allocate a generic track. As soon as we know its type we'll realloc. */

    track = av_mallocz(MAX_TRACK_SIZE);

    matroska->num_tracks++;

    strcpy(track->language, "eng");



    /* start with the master */

    if ((res = ebml_read_master(matroska, &id)) < 0)

        return res;



    /* try reading the trackentry headers */

    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR(EIO);

            break;

        } else if (matroska->level_up > 0) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* track number (unique stream ID) */

            case MATROSKA_ID_TRACKNUMBER: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                track->num = num;

                break;

            }



            /* track UID (unique identifier) */

            case MATROSKA_ID_TRACKUID: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                track->uid = num;

                break;

            }



            /* track type (video, audio, combined, subtitle, etc.) */

            case MATROSKA_ID_TRACKTYPE: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                if (track->type && track->type != num) {

                    av_log(matroska->ctx, AV_LOG_INFO,

                           "More than one tracktype in an entry - skip\n");

                    break;

                }

                track->type = num;



                switch (track->type) {

                    case MATROSKA_TRACK_TYPE_VIDEO:

                    case MATROSKA_TRACK_TYPE_AUDIO:

                    case MATROSKA_TRACK_TYPE_SUBTITLE:

                        break;

                    case MATROSKA_TRACK_TYPE_COMPLEX:

                    case MATROSKA_TRACK_TYPE_LOGO:

                    case MATROSKA_TRACK_TYPE_CONTROL:

                    default:

                        av_log(matroska->ctx, AV_LOG_INFO,

                               "Unknown or unsupported track type 0x%x\n",

                               track->type);

                        track->type = MATROSKA_TRACK_TYPE_NONE;

                        break;

                }

                matroska->tracks[matroska->num_tracks - 1] = track;

                break;

            }



            /* tracktype specific stuff for video */

            case MATROSKA_ID_TRACKVIDEO: {

                MatroskaVideoTrack *videotrack;

                if (!track->type)

                    track->type = MATROSKA_TRACK_TYPE_VIDEO;

                if (track->type != MATROSKA_TRACK_TYPE_VIDEO) {

                    av_log(matroska->ctx, AV_LOG_INFO,

                           "video data in non-video track - ignoring\n");

                    res = AVERROR_INVALIDDATA;

                    break;

                } else if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                videotrack = (MatroskaVideoTrack *)track;



                while (res == 0) {

                    if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

                        res = AVERROR(EIO);

                        break;

                    } else if (matroska->level_up > 0) {

                        matroska->level_up--;

                        break;

                    }



                    switch (id) {

                        /* fixme, this should be one-up, but I get it here */

                        case MATROSKA_ID_TRACKDEFAULTDURATION: {

                            uint64_t num;

                            if ((res = ebml_read_uint (matroska, &id,

                                                       &num)) < 0)

                                break;

                            track->default_duration = num;

                            break;

                        }



                        /* video framerate */

                        case MATROSKA_ID_VIDEOFRAMERATE: {

                            double num;

                            if ((res = ebml_read_float(matroska, &id,

                                                       &num)) < 0)

                                break;

                            if (!track->default_duration)

                                track->default_duration = 1000000000/num;

                            break;

                        }



                        /* width of the size to display the video at */

                        case MATROSKA_ID_VIDEODISPLAYWIDTH: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            videotrack->display_width = num;

                            break;

                        }



                        /* height of the size to display the video at */

                        case MATROSKA_ID_VIDEODISPLAYHEIGHT: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            videotrack->display_height = num;

                            break;

                        }



                        /* width of the video in the file */

                        case MATROSKA_ID_VIDEOPIXELWIDTH: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            videotrack->pixel_width = num;

                            break;

                        }



                        /* height of the video in the file */

                        case MATROSKA_ID_VIDEOPIXELHEIGHT: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            videotrack->pixel_height = num;

                            break;

                        }



                        /* whether the video is interlaced */

                        case MATROSKA_ID_VIDEOFLAGINTERLACED: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            if (num)

                                track->flags |=

                                    MATROSKA_VIDEOTRACK_INTERLACED;

                            else

                                track->flags &=

                                    ~MATROSKA_VIDEOTRACK_INTERLACED;

                            break;

                        }



                        /* stereo mode (whether the video has two streams,

                         * where one is for the left eye and the other for

                         * the right eye, which creates a 3D-like

                         * effect) */

                        case MATROSKA_ID_VIDEOSTEREOMODE: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            if (num != MATROSKA_EYE_MODE_MONO &&

                                num != MATROSKA_EYE_MODE_LEFT &&

                                num != MATROSKA_EYE_MODE_RIGHT &&

                                num != MATROSKA_EYE_MODE_BOTH) {

                                av_log(matroska->ctx, AV_LOG_INFO,

                                       "Ignoring unknown eye mode 0x%x\n",

                                       (uint32_t) num);

                                break;

                            }

                            videotrack->eye_mode = num;

                            break;

                        }



                        /* aspect ratio behaviour */

                        case MATROSKA_ID_VIDEOASPECTRATIO: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            if (num != MATROSKA_ASPECT_RATIO_MODE_FREE &&

                                num != MATROSKA_ASPECT_RATIO_MODE_KEEP &&

                                num != MATROSKA_ASPECT_RATIO_MODE_FIXED) {

                                av_log(matroska->ctx, AV_LOG_INFO,

                                       "Ignoring unknown aspect ratio 0x%x\n",

                                       (uint32_t) num);

                                break;

                            }

                            videotrack->ar_mode = num;

                            break;

                        }



                        /* colorspace (only matters for raw video)

                         * fourcc */

                        case MATROSKA_ID_VIDEOCOLORSPACE: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            videotrack->fourcc = num;

                            break;

                        }



                        default:

                            av_log(matroska->ctx, AV_LOG_INFO,

                                   "Unknown video track header entry "

                                   "0x%x - ignoring\n", id);

                            /* pass-through */



                        case EBML_ID_VOID:

                            res = ebml_read_skip(matroska);

                            break;

                    }



                    if (matroska->level_up) {

                        matroska->level_up--;

                        break;

                    }

                }

                break;

            }



            /* tracktype specific stuff for audio */

            case MATROSKA_ID_TRACKAUDIO: {

                MatroskaAudioTrack *audiotrack;

                if (!track->type)

                    track->type = MATROSKA_TRACK_TYPE_AUDIO;

                if (track->type != MATROSKA_TRACK_TYPE_AUDIO) {

                    av_log(matroska->ctx, AV_LOG_INFO,

                           "audio data in non-audio track - ignoring\n");

                    res = AVERROR_INVALIDDATA;

                    break;

                } else if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                audiotrack = (MatroskaAudioTrack *)track;

                audiotrack->channels = 1;

                audiotrack->samplerate = 8000;



                while (res == 0) {

                    if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

                        res = AVERROR(EIO);

                        break;

                    } else if (matroska->level_up > 0) {

                        matroska->level_up--;

                        break;

                    }



                    switch (id) {

                        /* samplerate */

                        case MATROSKA_ID_AUDIOSAMPLINGFREQ: {

                            double num;

                            if ((res = ebml_read_float(matroska, &id,

                                                       &num)) < 0)

                                break;

                            audiotrack->internal_samplerate =

                            audiotrack->samplerate = num;

                            break;

                        }



                        case MATROSKA_ID_AUDIOOUTSAMPLINGFREQ: {

                            double num;

                            if ((res = ebml_read_float(matroska, &id,

                                                       &num)) < 0)

                                break;

                            audiotrack->samplerate = num;

                            break;

                        }



                            /* bitdepth */

                        case MATROSKA_ID_AUDIOBITDEPTH: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            audiotrack->bitdepth = num;

                            break;

                        }



                            /* channels */

                        case MATROSKA_ID_AUDIOCHANNELS: {

                            uint64_t num;

                            if ((res = ebml_read_uint(matroska, &id,

                                                      &num)) < 0)

                                break;

                            audiotrack->channels = num;

                            break;

                        }



                        default:

                            av_log(matroska->ctx, AV_LOG_INFO,

                                   "Unknown audio track header entry "

                                   "0x%x - ignoring\n", id);

                            /* pass-through */



                        case EBML_ID_VOID:

                            res = ebml_read_skip(matroska);

                            break;

                    }



                    if (matroska->level_up) {

                        matroska->level_up--;

                        break;

                    }

                }

                break;

            }



                /* codec identifier */

            case MATROSKA_ID_CODECID: {

                char *text;

                if ((res = ebml_read_ascii(matroska, &id, &text)) < 0)

                    break;

                track->codec_id = text;

                break;

            }



                /* codec private data */

            case MATROSKA_ID_CODECPRIVATE: {

                uint8_t *data;

                int size;

                if ((res = ebml_read_binary(matroska, &id, &data, &size) < 0))

                    break;

                track->codec_priv = data;

                track->codec_priv_size = size;

                break;

            }



                /* name of the codec */

            case MATROSKA_ID_CODECNAME: {

                char *text;

                if ((res = ebml_read_utf8(matroska, &id, &text)) < 0)

                    break;

                track->codec_name = text;

                break;

            }



                /* name of this track */

            case MATROSKA_ID_TRACKNAME: {

                char *text;

                if ((res = ebml_read_utf8(matroska, &id, &text)) < 0)

                    break;

                track->name = text;

                break;

            }



                /* language (matters for audio/subtitles, mostly) */

            case MATROSKA_ID_TRACKLANGUAGE: {

                char *text, *end;

                if ((res = ebml_read_utf8(matroska, &id, &text)) < 0)

                    break;

                if ((end = strchr(text, '-')))

                    *end = '\0';

                if (strlen(text) == 3)

                    strcpy(track->language, text);

                av_free(text);

                break;

            }



                /* whether this is actually used */

            case MATROSKA_ID_TRACKFLAGENABLED: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                if (num)

                    track->flags |= MATROSKA_TRACK_ENABLED;

                else

                    track->flags &= ~MATROSKA_TRACK_ENABLED;

                break;

            }



                /* whether it's the default for this track type */

            case MATROSKA_ID_TRACKFLAGDEFAULT: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                if (num)

                    track->flags |= MATROSKA_TRACK_DEFAULT;

                else

                    track->flags &= ~MATROSKA_TRACK_DEFAULT;

                break;

            }



                /* lacing (like MPEG, where blocks don't end/start on frame

                 * boundaries) */

            case MATROSKA_ID_TRACKFLAGLACING: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                if (num)

                    track->flags |= MATROSKA_TRACK_LACING;

                else

                    track->flags &= ~MATROSKA_TRACK_LACING;

                break;

            }



                /* default length (in time) of one data block in this track */

            case MATROSKA_ID_TRACKDEFAULTDURATION: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                track->default_duration = num;

                break;

            }



            case MATROSKA_ID_TRACKCONTENTENCODINGS: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;



                while (res == 0) {

                    if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

                        res = AVERROR(EIO);

                        break;

                    } else if (matroska->level_up > 0) {

                        matroska->level_up--;

                        break;

                    }



                    switch (id) {

                        case MATROSKA_ID_TRACKCONTENTENCODING: {

                            int encoding_scope = 1;

                            if ((res = ebml_read_master(matroska, &id)) < 0)

                                break;



                            while (res == 0) {

                                if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

                                    res = AVERROR(EIO);

                                    break;

                                } else if (matroska->level_up > 0) {

                                    matroska->level_up--;

                                    break;

                                }



                                switch (id) {

                                    case MATROSKA_ID_ENCODINGSCOPE: {

                                        uint64_t num;

                                        if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                                            break;

                                        encoding_scope = num;

                                        break;

                                    }



                                    case MATROSKA_ID_ENCODINGTYPE: {

                                        uint64_t num;

                                        if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                                            break;

                                        if (num)

                                            av_log(matroska->ctx, AV_LOG_ERROR,

                                                   "Unsupported encoding type");

                                        break;

                                    }



                                    case MATROSKA_ID_ENCODINGCOMPRESSION: {

                                        if ((res = ebml_read_master(matroska, &id)) < 0)

                                            break;



                                        while (res == 0) {

                                            if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

                                                res = AVERROR(EIO);

                                                break;

                                            } else if (matroska->level_up > 0) {

                                                matroska->level_up--;

                                                break;

                                            }



                                            switch (id) {

                                                case MATROSKA_ID_ENCODINGCOMPALGO: {

                                                    uint64_t num;

                                                    if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                                                        break;

                                                    if (num != MATROSKA_TRACK_ENCODING_COMP_HEADERSTRIP &&

#ifdef CONFIG_ZLIB

                                                        num != MATROSKA_TRACK_ENCODING_COMP_ZLIB &&

#endif

#ifdef CONFIG_BZLIB

                                                        num != MATROSKA_TRACK_ENCODING_COMP_BZLIB &&

#endif

                                                        num != MATROSKA_TRACK_ENCODING_COMP_LZO)

                                                        av_log(matroska->ctx, AV_LOG_ERROR,

                                                               "Unsupported compression algo\n");

                                                    track->encoding_algo = num;

                                                    break;

                                                }



                                                case MATROSKA_ID_ENCODINGCOMPSETTINGS: {

                                                    uint8_t *data;

                                                    int size;

                                                    if ((res = ebml_read_binary(matroska, &id, &data, &size) < 0))

                                                        break;

                                                    track->encoding_settings = data;

                                                    track->encoding_settings_len = size;

                                                    break;

                                                }



                                                default:

                                                    av_log(matroska->ctx, AV_LOG_INFO,

                                                           "Unknown compression header entry "

                                                           "0x%x - ignoring\n", id);

                                                    /* pass-through */



                                                case EBML_ID_VOID:

                                                    res = ebml_read_skip(matroska);

                                                    break;

                                            }



                                            if (matroska->level_up) {

                                                matroska->level_up--;

                                                break;

                                            }

                                        }

                                        break;

                                    }



                                    default:

                                        av_log(matroska->ctx, AV_LOG_INFO,

                                               "Unknown content encoding header entry "

                                               "0x%x - ignoring\n", id);

                                        /* pass-through */



                                    case EBML_ID_VOID:

                                        res = ebml_read_skip(matroska);

                                        break;

                                }



                                if (matroska->level_up) {

                                    matroska->level_up--;

                                    break;

                                }

                            }



                            track->encoding_scope = encoding_scope;

                            break;

                        }



                        default:

                            av_log(matroska->ctx, AV_LOG_INFO,

                                   "Unknown content encodings header entry "

                                   "0x%x - ignoring\n", id);

                            /* pass-through */



                        case EBML_ID_VOID:

                            res = ebml_read_skip(matroska);

                            break;

                    }



                    if (matroska->level_up) {

                        matroska->level_up--;

                        break;

                    }

                }

                break;

            }



            case MATROSKA_ID_TRACKTIMECODESCALE: {

                double num;

                if ((res = ebml_read_float(matroska, &id, &num)) < 0)

                    break;

                track->time_scale = num;

                break;

            }



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown track header entry 0x%x - ignoring\n", id);

                /* pass-through */



            case EBML_ID_VOID:

            /* we ignore these because they're nothing useful. */

            case MATROSKA_ID_TRACKFLAGFORCED:

            case MATROSKA_ID_CODECDECODEALL:

            case MATROSKA_ID_CODECINFOURL:

            case MATROSKA_ID_CODECDOWNLOADURL:

            case MATROSKA_ID_TRACKMINCACHE:

            case MATROSKA_ID_TRACKMAXCACHE:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    return res;

}

static int filter_frame(AVFilterLink *inlink, AVFilterBufferRef *cur_buf)

{

    AlphaExtractContext *extract = inlink->dst->priv;

    AVFilterLink *outlink = inlink->dst->outputs[0];

    AVFilterBufferRef *out_buf =

        ff_get_video_buffer(outlink, AV_PERM_WRITE, outlink->w, outlink->h);

    int ret;



    if (!out_buf) {

        ret = AVERROR(ENOMEM);

        goto end;

    }

    avfilter_copy_buffer_ref_props(out_buf, cur_buf);



    if (extract->is_packed_rgb) {

        int x, y;

        uint8_t *pin, *pout;

        for (y = 0; y < out_buf->video->h; y++) {

            pin = cur_buf->data[0] + y * cur_buf->linesize[0] + extract->rgba_map[A];

            pout = out_buf->data[0] + y * out_buf->linesize[0];

            for (x = 0; x < out_buf->video->w; x++) {

                *pout = *pin;

                pout += 1;

                pin += 4;

            }

        }

    } else {

        const int linesize = FFMIN(out_buf->linesize[Y], cur_buf->linesize[A]);

        int y;

        for (y = 0; y < out_buf->video->h; y++) {

            memcpy(out_buf->data[Y] + y * out_buf->linesize[Y],

                   cur_buf->data[A] + y * cur_buf->linesize[A],

                   linesize);

        }

    }



    ret = ff_filter_frame(outlink, out_buf);



end:

    avfilter_unref_buffer(cur_buf);

    return ret;

}

static int load_data(AVFilterContext *ctx, int azim, int elev, float radius)

{

    struct SOFAlizerContext *s = ctx->priv;

    const int n_samples = s->sofa.n_samples;

    int n_conv = s->n_conv; /* no. channels to convolve */

    int n_fft = s->n_fft;

    int delay_l[16]; /* broadband delay for each IR */

    int delay_r[16];

    int nb_input_channels = ctx->inputs[0]->channels; /* no. input channels */

    float gain_lin = expf((s->gain - 3 * nb_input_channels) / 20 * M_LN10); /* gain - 3dB/channel */

    FFTComplex *data_hrtf_l = NULL;

    FFTComplex *data_hrtf_r = NULL;

    FFTComplex *fft_in_l = NULL;

    FFTComplex *fft_in_r = NULL;

    float *data_ir_l = NULL;

    float *data_ir_r = NULL;

    int offset = 0; /* used for faster pointer arithmetics in for-loop */

    int m[16]; /* measurement index m of IR closest to required source positions */

    int i, j, azim_orig = azim, elev_orig = elev;



    if (!s->sofa.ncid) { /* if an invalid SOFA file has been selected */

        av_log(ctx, AV_LOG_ERROR, "Selected SOFA file is invalid. Please select valid SOFA file.\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->type == TIME_DOMAIN) {

        s->temp_src[0] = av_calloc(FFALIGN(n_samples, 16), sizeof(float));

        s->temp_src[1] = av_calloc(FFALIGN(n_samples, 16), sizeof(float));



        /* get temporary IR for L and R channel */

        data_ir_l = av_malloc_array(n_conv * n_samples, sizeof(*data_ir_l));

        data_ir_r = av_malloc_array(n_conv * n_samples, sizeof(*data_ir_r));

        if (!data_ir_r || !data_ir_l || !s->temp_src[0] || !s->temp_src[1]) {

            av_free(data_ir_l);

            av_free(data_ir_r);

            return AVERROR(ENOMEM);

        }

    } else {

        /* get temporary HRTF memory for L and R channel */

        data_hrtf_l = av_malloc_array(n_fft, sizeof(*data_hrtf_l) * n_conv);

        data_hrtf_r = av_malloc_array(n_fft, sizeof(*data_hrtf_r) * n_conv);

        if (!data_hrtf_r || !data_hrtf_l) {

            av_free(data_hrtf_l);

            av_free(data_hrtf_r);

            return AVERROR(ENOMEM);

        }

    }



    for (i = 0; i < s->n_conv; i++) {

        /* load and store IRs and corresponding delays */

        azim = (int)(s->speaker_azim[i] + azim_orig) % 360;

        elev = (int)(s->speaker_elev[i] + elev_orig) % 90;

        /* get id of IR closest to desired position */

        m[i] = find_m(s, azim, elev, radius);



        /* load the delays associated with the current IRs */

        delay_l[i] = *(s->sofa.data_delay + 2 * m[i]);

        delay_r[i] = *(s->sofa.data_delay + 2 * m[i] + 1);



        if (s->type == TIME_DOMAIN) {

            offset = i * n_samples; /* no. samples already written */

            for (j = 0; j < n_samples; j++) {

                /* load reversed IRs of the specified source position

                 * sample-by-sample for left and right ear; and apply gain */

                *(data_ir_l + offset + j) = /* left channel */

                *(s->sofa.data_ir + 2 * m[i] * n_samples + n_samples - 1 - j) * gain_lin;

                *(data_ir_r + offset + j) = /* right channel */

                *(s->sofa.data_ir + 2 * m[i] * n_samples + n_samples - 1 - j  + n_samples) * gain_lin;

            }

        } else {

            fft_in_l = av_calloc(n_fft, sizeof(*fft_in_l));

            fft_in_r = av_calloc(n_fft, sizeof(*fft_in_r));

            if (!fft_in_l || !fft_in_r) {

                av_free(data_hrtf_l);

                av_free(data_hrtf_r);

                av_free(fft_in_l);

                av_free(fft_in_r);

                return AVERROR(ENOMEM);

            }



            offset = i * n_fft; /* no. samples already written */

            for (j = 0; j < n_samples; j++) {

                /* load non-reversed IRs of the specified source position

                 * sample-by-sample and apply gain,

                 * L channel is loaded to real part, R channel to imag part,

                 * IRs ared shifted by L and R delay */

                fft_in_l[delay_l[i] + j].re = /* left channel */

                *(s->sofa.data_ir + 2 * m[i] * n_samples + j) * gain_lin;

                fft_in_r[delay_r[i] + j].re = /* right channel */

                *(s->sofa.data_ir + (2 * m[i] + 1) * n_samples + j) * gain_lin;

            }



            /* actually transform to frequency domain (IRs -> HRTFs) */

            av_fft_permute(s->fft[0], fft_in_l);

            av_fft_calc(s->fft[0], fft_in_l);

            memcpy(data_hrtf_l + offset, fft_in_l, n_fft * sizeof(*fft_in_l));

            av_fft_permute(s->fft[0], fft_in_r);

            av_fft_calc(s->fft[0], fft_in_r);

            memcpy(data_hrtf_r + offset, fft_in_r, n_fft * sizeof(*fft_in_r));

        }



        av_log(ctx, AV_LOG_DEBUG, "Index: %d, Azimuth: %f, Elevation: %f, Radius: %f of SOFA file.\n",

               m[i], *(s->sofa.sp_a + m[i]), *(s->sofa.sp_e + m[i]), *(s->sofa.sp_r + m[i]));

    }



    if (s->type == TIME_DOMAIN) {

        /* copy IRs and delays to allocated memory in the SOFAlizerContext struct: */

        memcpy(s->data_ir[0], data_ir_l, sizeof(float) * n_conv * n_samples);

        memcpy(s->data_ir[1], data_ir_r, sizeof(float) * n_conv * n_samples);



        av_freep(&data_ir_l); /* free temporary IR memory */

        av_freep(&data_ir_r);

    } else {

        s->data_hrtf[0] = av_malloc_array(n_fft * s->n_conv, sizeof(FFTComplex));

        s->data_hrtf[1] = av_malloc_array(n_fft * s->n_conv, sizeof(FFTComplex));

        if (!s->data_hrtf[0] || !s->data_hrtf[1]) {

            av_freep(&data_hrtf_l);

            av_freep(&data_hrtf_r);

            av_freep(&fft_in_l);

            av_freep(&fft_in_r);

            return AVERROR(ENOMEM); /* memory allocation failed */

        }



        memcpy(s->data_hrtf[0], data_hrtf_l, /* copy HRTF data to */

            sizeof(FFTComplex) * n_conv * n_fft); /* filter struct */

        memcpy(s->data_hrtf[1], data_hrtf_r,

            sizeof(FFTComplex) * n_conv * n_fft);



        av_freep(&data_hrtf_l); /* free temporary HRTF memory */

        av_freep(&data_hrtf_r);



        av_freep(&fft_in_l); /* free temporary FFT memory */

        av_freep(&fft_in_r);

    }



    memcpy(s->delay[0], &delay_l[0], sizeof(int) * s->n_conv);

    memcpy(s->delay[1], &delay_r[0], sizeof(int) * s->n_conv);



    return 0;

}

static AVFrame *get_palette_frame(AVFilterContext *ctx)

{

    AVFrame *out;

    PaletteGenContext *s = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    double ratio;

    int box_id = 0;

    struct range_box *box;



    /* reference only the used colors from histogram */

    s->refs = load_color_refs(s->histogram, s->nb_refs);

    if (!s->refs) {

        av_log(ctx, AV_LOG_ERROR, "Unable to allocate references for %d different colors\n", s->nb_refs);

        return NULL;

    }



    /* create the palette frame */

    out = ff_get_video_buffer(outlink, outlink->w, outlink->h);

    if (!out)

        return NULL;

    out->pts = 0;



    /* set first box for 0..nb_refs */

    box = &s->boxes[box_id];

    box->len = s->nb_refs;

    box->sorted_by = -1;

    box->color = get_avg_color(s->refs, box);

    box->variance = -1;

    s->nb_boxes = 1;



    while (box && box->len > 1) {

        int i, rr, gr, br, longest;

        uint64_t median, box_weight = 0;



        /* compute the box weight (sum all the weights of the colors in the

         * range) and its boundings */

        uint8_t min[3] = {0xff, 0xff, 0xff};

        uint8_t max[3] = {0x00, 0x00, 0x00};

        for (i = box->start; i < box->start + box->len; i++) {

            const struct color_ref *ref = s->refs[i];

            const uint32_t rgb = ref->color;

            const uint8_t r = rgb >> 16 & 0xff, g = rgb >> 8 & 0xff, b = rgb & 0xff;

            min[0] = FFMIN(r, min[0]), max[0] = FFMAX(r, max[0]);

            min[1] = FFMIN(g, min[1]), max[1] = FFMAX(g, max[1]);

            min[2] = FFMIN(b, min[2]), max[2] = FFMAX(b, max[2]);

            box_weight += ref->count;

        }



        /* define the axis to sort by according to the widest range of colors */

        rr = max[0] - min[0];

        gr = max[1] - min[1];

        br = max[2] - min[2];

        longest = 1; // pick green by default (the color the eye is the most sensitive to)

        if (br >= rr && br >= gr) longest = 2;

        if (rr >= gr && rr >= br) longest = 0;

        if (gr >= rr && gr >= br) longest = 1; // prefer green again



        av_dlog(ctx, "box #%02X [%6d..%-6d] (%6d) w:%-6"PRIu64" ranges:[%2x %2x %2x] sort by %c (already sorted:%c) ",

                box_id, box->start, box->start + box->len - 1, box->len, box_weight,

                rr, gr, br, "rgb"[longest], box->sorted_by == longest ? 'y':'n');



        /* sort the range by its longest axis if it's not already sorted */

        if (box->sorted_by != longest) {

            cmp_func cmpf = cmp_funcs[longest];

            AV_QSORT(&s->refs[box->start], box->len, const struct color_ref *, cmpf);

            box->sorted_by = longest;

        }



        /* locate the median where to split */

        median = (box_weight + 1) >> 1;

        box_weight = 0;

        /* if you have 2 boxes, the maximum is actually #0: you must have at

         * least 1 color on each side of the split, hence the -2 */

        for (i = box->start; i < box->start + box->len - 2; i++) {

            box_weight += s->refs[i]->count;

            if (box_weight > median)

                break;

        }

        av_dlog(ctx, "split @ i=%-6d with w=%-6"PRIu64" (target=%6"PRIu64")\n", i, box_weight, median);

        split_box(s, box, i);



        box_id = get_next_box_id_to_split(s);

        box = box_id >= 0 ? &s->boxes[box_id] : NULL;

    }



    ratio = set_colorquant_ratio_meta(out, s->nb_boxes, s->nb_refs);

    av_log(ctx, AV_LOG_INFO, "%d%s colors generated out of %d colors; ratio=%f\n",

           s->nb_boxes, s->reserve_transparent ? "(+1)" : "", s->nb_refs, ratio);



    qsort(s->boxes, s->nb_boxes, sizeof(*s->boxes), cmp_color);



    write_palette(ctx, out);



    return out;

}

static int filter_frame(AVFilterLink *inlink, AVFrame *inpicref)

{

    AVFilterContext *ctx = inlink->dst;

    SeparateFieldsContext *sf = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    AVFrame *second;

    int i, ret;



    inpicref->height = outlink->h;

    inpicref->interlaced_frame = 0;



    second = av_frame_clone(inpicref);

    if (!second)

        return AVERROR(ENOMEM);



    for (i = 0; i < sf->nb_planes; i++) {

        if (!inpicref->top_field_first)

            inpicref->data[i] = inpicref->data[i] + inpicref->linesize[i];

        else

            second->data[i] = second->data[i] + second->linesize[i];

        inpicref->linesize[i] *= 2;

        second->linesize[i]   *= 2;

    }



    inpicref->pts = outlink->frame_count * sf->ts_unit;

    ret = ff_filter_frame(outlink, inpicref);

    if (ret < 0)

        return ret;



    second->pts = outlink->frame_count * sf->ts_unit;

    return ff_filter_frame(outlink, second);

}

static void ahci_test_identify(AHCIQState *ahci)
{
    uint16_t buff[256];
    unsigned px;
    int rc;
    uint16_t sect_size;
    const size_t buffsize = 512;
    g_assert(ahci != NULL);
    /**
     * This serves as a bit of a tutorial on AHCI device programming:
     *
     * (1) Create a data buffer for the IDENTIFY response to be sent to
     * (2) Create a Command Table buffer, where we will store the
     *     command and PRDT (Physical Region Descriptor Table)
     * (3) Construct an FIS host-to-device command structure, and write it to
     *     the top of the Command Table buffer.
     * (4) Create one or more Physical Region Descriptors (PRDs) that describe
     *     a location in memory where data may be stored/retrieved.
     * (5) Write these PRDTs to the bottom (offset 0x80) of the Command Table.
     * (6) Each AHCI port has up to 32 command slots. Each slot contains a
     *     header that points to a Command Table buffer. Pick an unused slot
     *     and update it to point to the Command Table we have built.
     * (7) Now: Command #n points to our Command Table, and our Command Table
     *     contains the FIS (that describes our command) and the PRDTL, which
     *     describes our buffer.
     * (8) We inform the HBA via PxCI (Command Issue) that the command in slot
     *     #n is ready for processing.
     */
    /* Pick the first implemented and running port */
    px = ahci_port_select(ahci);
    g_test_message("Selected port %u for test", px);
    /* Clear out the FIS Receive area and any pending interrupts. */
    ahci_port_clear(ahci, px);
    /* "Read" 512 bytes using CMD_IDENTIFY into the host buffer. */
    ahci_io(ahci, px, CMD_IDENTIFY, &buff, buffsize);
    /* Check serial number/version in the buffer */
    /* NB: IDENTIFY strings are packed in 16bit little endian chunks.
     * Since we copy byte-for-byte in ahci-test, on both LE and BE, we need to
     * unchunk this data. By contrast, ide-test copies 2 bytes at a time, and
     * as a consequence, only needs to unchunk the data on LE machines. */
    string_bswap16(&buff[10], 20);
    rc = memcmp(&buff[10], "testdisk            ", 20);
    g_assert_cmphex(rc, ==, 0);
    string_bswap16(&buff[23], 8);
    rc = memcmp(&buff[23], "version ", 8);
    g_assert_cmphex(rc, ==, 0);
}

static void test_dma_fragmented(void)

{

    AHCIQState *ahci;

    AHCICommand *cmd;

    uint8_t px;

    size_t bufsize = 4096;

    unsigned char *tx = g_malloc(bufsize);

    unsigned char *rx = g_malloc0(bufsize);

    uint64_t ptr;



    ahci = ahci_boot_and_enable();

    px = ahci_port_select(ahci);

    ahci_port_clear(ahci, px);



    /* create pattern */

    generate_pattern(tx, bufsize, AHCI_SECTOR_SIZE);



    /* Create a DMA buffer in guest memory, and write our pattern to it. */

    ptr = guest_alloc(ahci->parent->alloc, bufsize);

    g_assert(ptr);

    memwrite(ptr, tx, bufsize);



    cmd = ahci_command_create(CMD_WRITE_DMA);

    ahci_command_adjust(cmd, 0, ptr, bufsize, 32);

    ahci_command_commit(ahci, cmd, px);

    ahci_command_issue(ahci, cmd);

    ahci_command_verify(ahci, cmd);

    g_free(cmd);



    cmd = ahci_command_create(CMD_READ_DMA);

    ahci_command_adjust(cmd, 0, ptr, bufsize, 32);

    ahci_command_commit(ahci, cmd, px);

    ahci_command_issue(ahci, cmd);

    ahci_command_verify(ahci, cmd);

    g_free(cmd);



    /* Read back the guest's receive buffer into local memory */

    memread(ptr, rx, bufsize);

    guest_free(ahci->parent->alloc, ptr);



    g_assert_cmphex(memcmp(tx, rx, bufsize), ==, 0);



    ahci_shutdown(ahci);



    g_free(rx);

    g_free(tx);

}

static void ahci_test_identify(AHCIQState *ahci)

{

    RegD2HFIS *d2h = g_malloc0(0x20);

    RegD2HFIS *pio = g_malloc0(0x20);

    RegH2DFIS fis;

    AHCICommandHeader cmd;

    PRD prd;

    uint32_t reg, data_ptr;

    uint16_t buff[256];

    unsigned i;

    int rc;

    uint8_t cx;

    uint64_t table;



    g_assert(ahci != NULL);



    /* We need to:

     * (1) Create a Command Table Buffer and update the Command List Slot #0

     *     to point to this buffer.

     * (2) Construct an FIS host-to-device command structure, and write it to

     *     the top of the command table buffer.

     * (3) Create a data buffer for the IDENTIFY response to be sent to

     * (4) Create a Physical Region Descriptor that points to the data buffer,

     *     and write it to the bottom (offset 0x80) of the command table.

     * (5) Now, PxCLB points to the command list, command 0 points to

     *     our table, and our table contains an FIS instruction and a

     *     PRD that points to our rx buffer.

     * (6) We inform the HBA via PxCI that there is a command ready in slot #0.

     */



    /* Pick the first implemented and running port */

    i = ahci_port_select(ahci);

    g_test_message("Selected port %u for test", i);



    /* Clear out the FIS Receive area and any pending interrupts. */

    ahci_port_clear(ahci, i);



    /* Create a Command Table buffer. 0x80 is the smallest with a PRDTL of 0. */

    /* We need at least one PRD, so round up to the nearest 0x80 multiple.    */

    table = ahci_alloc(ahci, CMD_TBL_SIZ(1));

    g_assert(table);

    ASSERT_BIT_CLEAR(table, 0x7F);



    /* Create a data buffer ... where we will dump the IDENTIFY data to. */

    data_ptr = ahci_alloc(ahci, 512);

    g_assert(data_ptr);



    /* pick a command slot (should be 0!) */

    cx = ahci_pick_cmd(ahci, i);



    /* Construct our Command Header (set_command_header handles endianness.) */

    memset(&cmd, 0x00, sizeof(cmd));

    cmd.flags = 5;      /* reg_h2d_fis is 5 double-words long */

    cmd.flags |= 0x400; /* clear PxTFD.STS.BSY when done */

    cmd.prdtl = 1;      /* One PRD table entry. */

    cmd.prdbc = 0;

    cmd.ctba = table;



    /* Construct our PRD, noting that DBC is 0-indexed. */

    prd.dba = cpu_to_le64(data_ptr);

    prd.res = 0;

    /* 511+1 bytes, request DPS interrupt */

    prd.dbc = cpu_to_le32(511 | 0x80000000);



    /* Construct our Command FIS, Based on http://wiki.osdev.org/AHCI */

    memset(&fis, 0x00, sizeof(fis));

    fis.fis_type = 0x27; /* Register Host-to-Device FIS */

    fis.command = 0xEC;  /* IDENTIFY */

    fis.device = 0;

    fis.flags = 0x80;    /* Indicate this is a command FIS */



    /* We've committed nothing yet, no interrupts should be posted yet. */

    g_assert_cmphex(ahci_px_rreg(ahci, i, AHCI_PX_IS), ==, 0);



    /* Commit the Command FIS to the Command Table */

    memwrite(table, &fis, sizeof(fis));



    /* Commit the PRD entry to the Command Table */

    memwrite(table + 0x80, &prd, sizeof(prd));



    /* Commit Command #cx, pointing to the Table, to the Command List Buffer. */

    ahci_set_command_header(ahci, i, cx, &cmd);



    /* Everything is in place, but we haven't given the go-ahead yet,

     * so we should find that there are no pending interrupts yet. */

    g_assert_cmphex(ahci_px_rreg(ahci, i, AHCI_PX_IS), ==, 0);



    /* Issue Command #cx via PxCI */

    ahci_px_wreg(ahci, i, AHCI_PX_CI, (1 << cx));

    while (BITSET(ahci_px_rreg(ahci, i, AHCI_PX_TFD), AHCI_PX_TFD_STS_BSY)) {

        usleep(50);

    }



    /* Check for expected interrupts */

    reg = ahci_px_rreg(ahci, i, AHCI_PX_IS);

    ASSERT_BIT_SET(reg, AHCI_PX_IS_DHRS);

    ASSERT_BIT_SET(reg, AHCI_PX_IS_PSS);

    /* BUG: we expect AHCI_PX_IS_DPS to be set. */

    ASSERT_BIT_CLEAR(reg, AHCI_PX_IS_DPS);



    /* Clear expected interrupts and assert all interrupts now cleared. */

    ahci_px_wreg(ahci, i, AHCI_PX_IS,

                 AHCI_PX_IS_DHRS | AHCI_PX_IS_PSS | AHCI_PX_IS_DPS);

    g_assert_cmphex(ahci_px_rreg(ahci, i, AHCI_PX_IS), ==, 0);



    /* Check for errors. */

    reg = ahci_px_rreg(ahci, i, AHCI_PX_SERR);

    g_assert_cmphex(reg, ==, 0);

    reg = ahci_px_rreg(ahci, i, AHCI_PX_TFD);

    ASSERT_BIT_CLEAR(reg, AHCI_PX_TFD_STS_ERR);

    ASSERT_BIT_CLEAR(reg, AHCI_PX_TFD_ERR);



    /* Investigate the CMD, assert that we read 512 bytes */

    ahci_get_command_header(ahci, i, cx, &cmd);

    g_assert_cmphex(512, ==, cmd.prdbc);



    /* Investigate FIS responses */

    memread(ahci->port[i].fb + 0x20, pio, 0x20);

    memread(ahci->port[i].fb + 0x40, d2h, 0x20);

    g_assert_cmphex(pio->fis_type, ==, 0x5f);

    g_assert_cmphex(d2h->fis_type, ==, 0x34);

    g_assert_cmphex(pio->flags, ==, d2h->flags);

    g_assert_cmphex(pio->status, ==, d2h->status);

    g_assert_cmphex(pio->error, ==, d2h->error);



    reg = ahci_px_rreg(ahci, i, AHCI_PX_TFD);

    g_assert_cmphex((reg & AHCI_PX_TFD_ERR), ==, pio->error);

    g_assert_cmphex((reg & AHCI_PX_TFD_STS), ==, pio->status);

    /* The PIO Setup FIS contains a "bytes read" field, which is a

     * 16-bit value. The Physical Region Descriptor Byte Count is

     * 32-bit, but for small transfers using one PRD, it should match. */

    g_assert_cmphex(le16_to_cpu(pio->res4), ==, cmd.prdbc);



    /* Last, but not least: Investigate the IDENTIFY response data. */

    memread(data_ptr, &buff, 512);



    /* Check serial number/version in the buffer */

    /* NB: IDENTIFY strings are packed in 16bit little endian chunks.

     * Since we copy byte-for-byte in ahci-test, on both LE and BE, we need to

     * unchunk this data. By contrast, ide-test copies 2 bytes at a time, and

     * as a consequence, only needs to unchunk the data on LE machines. */

    string_bswap16(&buff[10], 20);

    rc = memcmp(&buff[10], "testdisk            ", 20);

    g_assert_cmphex(rc, ==, 0);



    string_bswap16(&buff[23], 8);

    rc = memcmp(&buff[23], "version ", 8);

    g_assert_cmphex(rc, ==, 0);



    g_free(d2h);

    g_free(pio);

}

static void test_to_from_buf_1(void)

{

     unsigned niov;

     struct iovec *iov;

     size_t sz;

     unsigned char *ibuf, *obuf;

     unsigned i, j, n;



     iov_random(&iov, &niov);



     sz = iov_size(iov, niov);



     ibuf = g_malloc(sz + 8) + 4;

     memcpy(ibuf-4, "aaaa", 4); memcpy(ibuf + sz, "bbbb", 4);

     obuf = g_malloc(sz + 8) + 4;

     memcpy(obuf-4, "xxxx", 4); memcpy(obuf + sz, "yyyy", 4);



     /* fill in ibuf with 0123456... */

     for (i = 0; i < sz; ++i) {

         ibuf[i] = i & 255;

     }



     for (i = 0; i <= sz; ++i) {



         /* Test from/to buf for offset(i) in [0..sz] up to the end of buffer.

          * For last iteration with offset == sz, the procedure should

          * skip whole vector and process exactly 0 bytes */



         /* first set bytes [i..sz) to some "random" value */

         n = iov_memset(iov, niov, 0, 0xff, -1);

         g_assert(n == sz);



         /* next copy bytes [i..sz) from ibuf to iovec */

         n = iov_from_buf(iov, niov, i, ibuf + i, -1);

         g_assert(n == sz - i);



         /* clear part of obuf */

         memset(obuf + i, 0, sz - i);

         /* and set this part of obuf to values from iovec */

         n = iov_to_buf(iov, niov, i, obuf + i, -1);

         g_assert(n == sz - i);



         /* now compare resulting buffers */

         g_assert(memcmp(ibuf, obuf, sz) == 0);



         /* test just one char */

         n = iov_to_buf(iov, niov, i, obuf + i, 1);

         g_assert(n == (i < sz));

         if (n) {

             g_assert(obuf[i] == (i & 255));

         }



         for (j = i; j <= sz; ++j) {

             /* now test num of bytes cap up to byte no. j,

              * with j in [i..sz]. */



             /* clear iovec */

             n = iov_memset(iov, niov, 0, 0xff, -1);

             g_assert(n == sz);



             /* copy bytes [i..j) from ibuf to iovec */

             n = iov_from_buf(iov, niov, i, ibuf + i, j - i);

             g_assert(n == j - i);



             /* clear part of obuf */

             memset(obuf + i, 0, j - i);



             /* copy bytes [i..j) from iovec to obuf */

             n = iov_to_buf(iov, niov, i, obuf + i, j - i);

             g_assert(n == j - i);



             /* verify result */

             g_assert(memcmp(ibuf, obuf, sz) == 0);



             /* now actually check if the iovec contains the right data */

             test_iov_bytes(iov, niov, i, j - i);

         }

    }

    g_assert(!memcmp(ibuf-4, "aaaa", 4) && !memcmp(ibuf+sz, "bbbb", 4));

    g_free(ibuf-4);

    g_assert(!memcmp(obuf-4, "xxxx", 4) && !memcmp(obuf+sz, "yyyy", 4));

    g_free(obuf-4);

    iov_free(iov, niov);

}

static uint32_t pm_ioport_readw(void *opaque, uint32_t addr)

{

    VT686PMState *s = opaque;

    uint32_t val;



    addr &= 0x0f;

    switch (addr) {

    case 0x00:

        val = acpi_pm1_evt_get_sts(&s->ar, s->ar.tmr.overflow_time);

        break;

    case 0x02:

        val = s->ar.pm1.evt.en;

        break;

    case 0x04:

        val = s->ar.pm1.cnt.cnt;

        break;

    default:

        val = 0;

        break;

    }

    DPRINTF("PM readw port=0x%04x val=0x%02x\n", addr, val);

    return val;

}

