static uint64_t pxa2xx_pm_read(void *opaque, hwaddr addr,

                               unsigned size)

{

    PXA2xxState *s = (PXA2xxState *) opaque;



    switch (addr) {

    case PMCR ... PCMD31:

        if (addr & 3)

            goto fail;



        return s->pm_regs[addr >> 2];

    default:

    fail:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

    return 0;

}

static uint64_t hpdmc_read(void *opaque, target_phys_addr_t addr,

                           unsigned size)

{

    MilkymistHpdmcState *s = opaque;

    uint32_t r = 0;



    addr >>= 2;

    switch (addr) {

    case R_SYSTEM:

    case R_BYPASS:

    case R_TIMING:

    case R_IODELAY:

        r = s->regs[addr];

        break;



    default:

        error_report("milkymist_hpdmc: read access to unknown register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    }



    trace_milkymist_hpdmc_memory_read(addr << 2, r);



    return r;

}

static int w64_read_header(AVFormatContext *s)

{

    int64_t size, data_ofs = 0;

    AVIOContext *pb      = s->pb;

    WAVDemuxContext *wav = s->priv_data;

    AVStream *st;

    uint8_t guid[16];

    int ret;



    avio_read(pb, guid, 16);

    if (memcmp(guid, ff_w64_guid_riff, 16))




    /* riff + wave + fmt + sizes */

    if (avio_rl64(pb) < 16 + 8 + 16 + 8 + 16 + 8)




    avio_read(pb, guid, 16);

    if (memcmp(guid, ff_w64_guid_wave, 16)) {

        av_log(s, AV_LOG_ERROR, "could not find wave guid\n");


    }



    wav->w64 = 1;



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    while (!avio_feof(pb)) {

        if (avio_read(pb, guid, 16) != 16)

            break;

        size = avio_rl64(pb);

        if (size <= 24 || INT64_MAX - size < avio_tell(pb))




        if (!memcmp(guid, ff_w64_guid_fmt, 16)) {

            /* subtract chunk header size - normal wav file doesn't count it */

            ret = ff_get_wav_header(s, pb, st->codecpar, size - 24, 0);

            if (ret < 0)

                return ret;

            avio_skip(pb, FFALIGN(size, INT64_C(8)) - size);



            avpriv_set_pts_info(st, 64, 1, st->codecpar->sample_rate);

        } else if (!memcmp(guid, ff_w64_guid_fact, 16)) {

            int64_t samples;



            samples = avio_rl64(pb);

            if (samples > 0)

                st->duration = samples;

        } else if (!memcmp(guid, ff_w64_guid_data, 16)) {

            wav->data_end = avio_tell(pb) + size - 24;



            data_ofs = avio_tell(pb);

            if (!(pb->seekable & AVIO_SEEKABLE_NORMAL))

                break;



            avio_skip(pb, size - 24);

        } else if (!memcmp(guid, ff_w64_guid_summarylist, 16)) {

            int64_t start, end, cur;

            uint32_t count, chunk_size, i;



            start = avio_tell(pb);

            end = start + FFALIGN(size, INT64_C(8)) - 24;

            count = avio_rl32(pb);



            for (i = 0; i < count; i++) {

                char chunk_key[5], *value;



                if (avio_feof(pb) || (cur = avio_tell(pb)) < 0 || cur > end - 8 /* = tag + size */)

                    break;



                chunk_key[4] = 0;

                avio_read(pb, chunk_key, 4);

                chunk_size = avio_rl32(pb);





                value = av_mallocz(chunk_size + 1);

                if (!value)

                    return AVERROR(ENOMEM);



                ret = avio_get_str16le(pb, chunk_size, value, chunk_size);

                avio_skip(pb, chunk_size - ret);



                av_dict_set(&s->metadata, chunk_key, value, AV_DICT_DONT_STRDUP_VAL);

            }



            avio_skip(pb, end - avio_tell(pb));

        } else {

            av_log(s, AV_LOG_DEBUG, "unknown guid: "FF_PRI_GUID"\n", FF_ARG_GUID(guid));

            avio_skip(pb, FFALIGN(size, INT64_C(8)) - 24);

        }

    }



    if (!data_ofs)

        return AVERROR_EOF;



    ff_metadata_conv_ctx(s, NULL, wav_metadata_conv);

    ff_metadata_conv_ctx(s, NULL, ff_riff_info_conv);



    handle_stream_probing(st);

    st->need_parsing = AVSTREAM_PARSE_FULL_RAW;



    avio_seek(pb, data_ofs, SEEK_SET);



    set_spdif(s, wav);



    return 0;

}

static int wav_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    int size;

    unsigned int tag;

    ByteIOContext *pb = s->pb;

    AVStream *st;

    WAVContext *wav = s->priv_data;



    /* check RIFF header */

    tag = get_le32(pb);



    if (tag != MKTAG('R', 'I', 'F', 'F'))

        return -1;

    get_le32(pb); /* file size */

    tag = get_le32(pb);

    if (tag != MKTAG('W', 'A', 'V', 'E'))

        return -1;



    /* parse fmt header */

    size = find_tag(pb, MKTAG('f', 'm', 't', ' '));

    if (size < 0)

        return -1;

    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    get_wav_header(pb, st->codec, size);

    st->need_parsing = AVSTREAM_PARSE_FULL;



    av_set_pts_info(st, 64, 1, st->codec->sample_rate);



    size = find_tag(pb, MKTAG('d', 'a', 't', 'a'));

    if (size < 0)

        return -1;

    wav->data_end= url_ftell(pb) + size;

    return 0;

}

static int audio_read_header(AVFormatContext *s1, AVFormatParameters *ap)

{

    AudioData *s = s1->priv_data;

    AVStream *st;

    int ret;



    if (!ap || ap->sample_rate <= 0 || ap->channels <= 0)

        return -1;



    st = av_new_stream(s1, 0);

    if (!st) {

        return -ENOMEM;

    }

    s->sample_rate = ap->sample_rate;

    s->channels = ap->channels;



    ret = audio_open(s, 0, ap->device);

    if (ret < 0) {

        av_free(st);

        return AVERROR_IO;

    }



    /* take real parameters */

    st->codec->codec_type = CODEC_TYPE_AUDIO;

    st->codec->codec_id = s->codec_id;

    st->codec->sample_rate = s->sample_rate;

    st->codec->channels = s->channels;



    av_set_pts_info(st, 64, 1, 1000000);  /* 64 bits pts in us */

    return 0;

}

static int mp3_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    AVStream *st;

    int64_t off;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type = CODEC_TYPE_AUDIO;

    st->codec->codec_id = CODEC_ID_MP3;

    st->need_parsing = AVSTREAM_PARSE_FULL;

    st->start_time = 0;



    ff_id3v1_read(s);

    ff_id3v2_read(s);



    off = url_ftell(s->pb);

    if (mp3_parse_vbr_tags(s, st, off) < 0)

        url_fseek(s->pb, off, SEEK_SET);



    /* the parameters will be extracted from the compressed bitstream */

    return 0;

}

void rgb15tobgr16(const uint8_t *src, uint8_t *dst, long src_size)

{

	long i;

	long num_pixels = src_size >> 1;



	for(i=0; i<num_pixels; i++)

	{

	    unsigned b,g,r;

	    register uint16_t rgb;

	    rgb = src[2*i];

	    r = rgb&0x1F;

	    g = (rgb&0x3E0)>>5;

	    b = (rgb&0x7C00)>>10;

	    dst[2*i] = (b&0x1F) | ((g&0x3F)<<5) | ((r&0x1F)<<11);

	}

}

