            av_log(NULL, AV_LOG_ERROR, "Directly using swscale dimensions/format options is not supported, please use the -s or -pix_fmt options\n");

            return AVERROR(EINVAL);

        }

        if (ret < 0) {

            av_log(NULL, AV_LOG_ERROR, "Error setting option %s.\n", opt);

            return ret;

        }



        av_dict_set(&sws_dict, opt, arg, FLAGS);



        consumed = 1;

    }

#else

    if (!consumed && !strcmp(opt, "sws_flags")) {

        av_log(NULL, AV_LOG_WARNING, "Ignoring %s %s, due to disabled swscale\n", opt, arg);

        consumed = 1;

    }

#endif

#if CONFIG_SWRESAMPLE

    swr_class = swr_get_class();

    if (!consumed && (o=opt_find(&swr_class, opt, NULL, 0,

                                    AV_OPT_SEARCH_CHILDREN | AV_OPT_SEARCH_FAKE_OBJ))) {

        struct SwrContext *swr = swr_alloc();

        int ret = av_opt_set(swr, opt, arg, 0);

        swr_free(&swr);

        if (ret < 0) {

            av_log(NULL, AV_LOG_ERROR, "Error setting option %s.\n", opt);

            return ret;

        }

        av_dict_set(&swr_opts, opt, arg, FLAGS);

        consumed = 1;

    }

#endif

#if CONFIG_AVRESAMPLE

    if ((o=opt_find(&rc, opt, NULL, 0,

                       AV_OPT_SEARCH_CHILDREN | AV_OPT_SEARCH_FAKE_OBJ))) {

        av_dict_set(&resample_opts, opt, arg, FLAGS);

        consumed = 1;

    }

#endif



    if (consumed)

        return 0;

    return AVERROR_OPTION_NOT_FOUND;

}

int opt_default(const char *opt, const char *arg){

    int type;

    const AVOption *o= NULL;

    int opt_types[]={AV_OPT_FLAG_VIDEO_PARAM, AV_OPT_FLAG_AUDIO_PARAM, 0, AV_OPT_FLAG_SUBTITLE_PARAM, 0};



    for(type=0; type<CODEC_TYPE_NB; type++){

        const AVOption *o2 = av_find_opt(avctx_opts[0], opt, NULL, opt_types[type], opt_types[type]);

        if(o2)

            o = av_set_string2(avctx_opts[type], opt, arg, 1);

    }

    if(!o)

        o = av_set_string2(avformat_opts, opt, arg, 1);

    if(!o)

        o = av_set_string2(sws_opts, opt, arg, 1);

    if(!o){

        if(opt[0] == 'a')

            o = av_set_string2(avctx_opts[CODEC_TYPE_AUDIO], opt+1, arg, 1);

        else if(opt[0] == 'v')

            o = av_set_string2(avctx_opts[CODEC_TYPE_VIDEO], opt+1, arg, 1);

        else if(opt[0] == 's')

            o = av_set_string2(avctx_opts[CODEC_TYPE_SUBTITLE], opt+1, arg, 1);

    }

    if(!o)

        return -1;



//    av_log(NULL, AV_LOG_ERROR, "%s:%s: %f 0x%0X\n", opt, arg, av_get_double(avctx_opts, opt, NULL), (int)av_get_int(avctx_opts, opt, NULL));



    //FIXME we should always use avctx_opts, ... for storing options so there will not be any need to keep track of what i set over this

    opt_names= av_realloc(opt_names, sizeof(void*)*(opt_name_count+1));

    opt_names[opt_name_count++]= o->name;



    if(avctx_opts[0]->debug || avformat_opts->debug)

        av_log_set_level(AV_LOG_DEBUG);

    return 0;

}

int split_commandline(OptionParseContext *octx, int argc, char *argv[],

                      const OptionDef *options,

                      const OptionGroupDef *groups)

{

    int optindex = 1;



    /* perform system-dependent conversions for arguments list */

    prepare_app_arguments(&argc, &argv);



    init_parse_context(octx, groups);

    av_log(NULL, AV_LOG_DEBUG, "Splitting the commandline.\n");



    while (optindex < argc) {

        const char *opt = argv[optindex++], *arg;

        const OptionDef *po;

        int ret;



        av_log(NULL, AV_LOG_DEBUG, "Reading option '%s' ...", opt);



        /* unnamed group separators, e.g. output filename */

        if (opt[0] != '-' || !opt[1]) {

            finish_group(octx, 0, opt);

            av_log(NULL, AV_LOG_DEBUG, " matched as %s.\n", groups[0].name);

            continue;

        }

        opt++;



#define GET_ARG(arg)                                                           \

do {                                                                           \

    arg = argv[optindex++];                                                    \

    if (!arg) {                                                                \

        av_log(NULL, AV_LOG_ERROR, "Missing argument for option '%s'.\n", opt);\

        return AVERROR(EINVAL);                                                \

    }                                                                          \

} while (0)



        /* named group separators, e.g. -i */

        if ((ret = match_group_separator(groups, opt)) >= 0) {

            GET_ARG(arg);

            finish_group(octx, ret, arg);

            av_log(NULL, AV_LOG_DEBUG, " matched as %s with argument '%s'.\n",

                   groups[ret].name, arg);

            continue;

        }



        /* normal options */

        po = find_option(options, opt);

        if (po->name) {

            if (po->flags & OPT_EXIT) {

                /* optional argument, e.g. -h */

                arg = argv[optindex++];

            } else if (po->flags & HAS_ARG) {

                GET_ARG(arg);

            } else {

                arg = "1";

            }



            add_opt(octx, po, opt, arg);

            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "

                   "argument '%s'.\n", po->name, po->help, arg);

            continue;

        }



        /* AVOptions */

        if (argv[optindex]) {

            ret = opt_default(NULL, opt, argv[optindex]);

            if (ret >= 0) {

                av_log(NULL, AV_LOG_DEBUG, " matched as AVOption '%s' with "

                       "argument '%s'.\n", opt, argv[optindex]);

                optindex++;

                continue;

            } else if (ret != AVERROR_OPTION_NOT_FOUND) {

                av_log(NULL, AV_LOG_ERROR, "Error parsing option '%s' "

                       "with argument '%s'.\n", opt, argv[optindex]);

                return ret;

            }

        }



        /* boolean -nofoo options */

        if (opt[0] == 'n' && opt[1] == 'o' &&

            (po = find_option(options, opt + 2)) &&

            po->name && po->flags & OPT_BOOL) {

            add_opt(octx, po, opt, "0");

            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "

                   "argument 0.\n", po->name, po->help);

            continue;

        }



        av_log(NULL, AV_LOG_ERROR, "Unrecognized option '%s'.\n", opt);

        return AVERROR_OPTION_NOT_FOUND;

    }



    if (octx->cur_group.nb_opts || codec_opts || format_opts)

        av_log(NULL, AV_LOG_WARNING, "Trailing options were found on the "

               "commandline.\n");



    av_log(NULL, AV_LOG_DEBUG, "Finished splitting the commandline.\n");



    return 0;

}

