static void syborg_init(ram_addr_t ram_size,

                        const char *boot_device,

                        const char *kernel_filename, const char *kernel_cmdline,

                        const char *initrd_filename, const char *cpu_model)

{

    CPUState *env;

    qemu_irq *cpu_pic;

    qemu_irq pic[64];

    ram_addr_t ram_addr;

    DeviceState *dev;

    int i;



    if (!cpu_model)

        cpu_model = "cortex-a8";

    env = cpu_init(cpu_model);

    if (!env) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }



    /* RAM at address zero. */

    ram_addr = qemu_ram_alloc(ram_size);

    cpu_register_physical_memory(0, ram_size, ram_addr | IO_MEM_RAM);



    cpu_pic = arm_pic_init_cpu(env);

    dev = sysbus_create_simple("syborg,interrupt", 0xC0000000,

                               cpu_pic[ARM_PIC_CPU_IRQ]);

    for (i = 0; i < 64; i++) {

        pic[i] = qdev_get_gpio_in(dev, i);

    }



    sysbus_create_simple("syborg,rtc", 0xC0001000, NULL);



    dev = qdev_create(NULL, "syborg,timer");

    qdev_prop_set_uint32(dev, "frequency", 1000000);

    qdev_init(dev);

    sysbus_mmio_map(sysbus_from_qdev(dev), 0, 0xC0002000);

    sysbus_connect_irq(sysbus_from_qdev(dev), 0, pic[1]);



    sysbus_create_simple("syborg,keyboard", 0xC0003000, pic[2]);

    sysbus_create_simple("syborg,pointer", 0xC0004000, pic[3]);

    sysbus_create_simple("syborg,framebuffer", 0xC0005000, pic[4]);

    sysbus_create_simple("syborg,serial", 0xC0006000, pic[5]);

    sysbus_create_simple("syborg,serial", 0xC0007000, pic[6]);

    sysbus_create_simple("syborg,serial", 0xC0008000, pic[7]);

    sysbus_create_simple("syborg,serial", 0xC0009000, pic[8]);



    if (nd_table[0].vlan) {

        DeviceState *dev;

        SysBusDevice *s;



        qemu_check_nic_model(&nd_table[0], "virtio");

        dev = qdev_create(NULL, "syborg,virtio-net");

        dev->nd = &nd_table[0];

        qdev_init(dev);

        s = sysbus_from_qdev(dev);

        sysbus_mmio_map(s, 0, 0xc000c000);

        sysbus_connect_irq(s, 0, pic[9]);

    }



    syborg_binfo.ram_size = ram_size;

    syborg_binfo.kernel_filename = kernel_filename;

    syborg_binfo.kernel_cmdline = kernel_cmdline;

    syborg_binfo.initrd_filename = initrd_filename;

    syborg_binfo.board_id = 0;

    arm_load_kernel(env, &syborg_binfo);

}

static void tcx_init(hwaddr addr, qemu_irq irq, int vram_size, int width,

                     int height, int depth)

{

    DeviceState *dev;

    SysBusDevice *s;



    dev = qdev_create(NULL, "SUNW,tcx");

    qdev_prop_set_uint32(dev, "vram_size", vram_size);

    qdev_prop_set_uint16(dev, "width", width);

    qdev_prop_set_uint16(dev, "height", height);

    qdev_prop_set_uint16(dev, "depth", depth);

    qdev_prop_set_uint64(dev, "prom_addr", addr);

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);



    /* 10/ROM : FCode ROM */

    sysbus_mmio_map(s, 0, addr);

    /* 2/STIP : Stipple */

    sysbus_mmio_map(s, 1, addr + 0x04000000ULL);

    /* 3/BLIT : Blitter */

    sysbus_mmio_map(s, 2, addr + 0x06000000ULL);

    /* 5/RSTIP : Raw Stipple */

    sysbus_mmio_map(s, 3, addr + 0x0c000000ULL);

    /* 6/RBLIT : Raw Blitter */

    sysbus_mmio_map(s, 4, addr + 0x0e000000ULL);

    /* 7/TEC : Transform Engine */

    sysbus_mmio_map(s, 5, addr + 0x00700000ULL);

    /* 8/CMAP  : DAC */

    sysbus_mmio_map(s, 6, addr + 0x00200000ULL);

    /* 9/THC : */

    if (depth == 8) {

        sysbus_mmio_map(s, 7, addr + 0x00300000ULL);

    } else {

        sysbus_mmio_map(s, 7, addr + 0x00301000ULL);

    }

    /* 11/DHC : */

    sysbus_mmio_map(s, 8, addr + 0x00240000ULL);

    /* 12/ALT : */

    sysbus_mmio_map(s, 9, addr + 0x00280000ULL);

    /* 0/DFB8 : 8-bit plane */

    sysbus_mmio_map(s, 10, addr + 0x00800000ULL);

    /* 1/DFB24 : 24bit plane */

    sysbus_mmio_map(s, 11, addr + 0x02000000ULL);

    /* 4/RDFB32: Raw framebuffer. Control plane */

    sysbus_mmio_map(s, 12, addr + 0x0a000000ULL);

    /* 9/THC24bits : NetBSD writes here even with 8-bit display: dummy */

    if (depth == 8) {

        sysbus_mmio_map(s, 13, addr + 0x00301000ULL);

    }



    sysbus_connect_irq(s, 0, irq);

}

