static ResampleContext *resample_init(ResampleContext *c, int out_rate, int in_rate, int filter_size, int phase_shift, int linear,

                                    double cutoff0, enum AVSampleFormat format, enum SwrFilterType filter_type, int kaiser_beta,

                                    double precision, int cheby){

    double cutoff = cutoff0? cutoff0 : 0.97;

    double factor= FFMIN(out_rate * cutoff / in_rate, 1.0);

    int phase_count= 1<<phase_shift;



    if (!c || c->phase_shift != phase_shift || c->linear!=linear || c->factor != factor

           || c->filter_length != FFMAX((int)ceil(filter_size/factor), 1) || c->format != format

           || c->filter_type != filter_type || c->kaiser_beta != kaiser_beta) {

        c = av_mallocz(sizeof(*c));

        if (!c)

            return NULL;



        c->format= format;



        c->felem_size= av_get_bytes_per_sample(c->format);



        switch(c->format){

        case AV_SAMPLE_FMT_S16P:

            c->filter_shift = 15;

            break;

        case AV_SAMPLE_FMT_S32P:

            c->filter_shift = 30;

            break;

        case AV_SAMPLE_FMT_FLTP:

        case AV_SAMPLE_FMT_DBLP:

            c->filter_shift = 0;

            break;

        default:

            av_log(NULL, AV_LOG_ERROR, "Unsupported sample format\n");

            av_assert0(0);

        }



        c->phase_shift   = phase_shift;

        c->phase_mask    = phase_count - 1;

        c->linear        = linear;

        c->factor        = factor;

        c->filter_length = FFMAX((int)ceil(filter_size/factor), 1);

        c->filter_alloc  = FFALIGN(c->filter_length, 8);

        c->filter_bank   = av_mallocz(c->filter_alloc*(phase_count+1)*c->felem_size);

        c->filter_type   = filter_type;

        c->kaiser_beta   = kaiser_beta;

        if (!c->filter_bank)

            goto error;

        if (build_filter(c, (void*)c->filter_bank, factor, c->filter_length, c->filter_alloc, phase_count, 1<<c->filter_shift, filter_type, kaiser_beta))

            goto error;

        memcpy(c->filter_bank + (c->filter_alloc*phase_count+1)*c->felem_size, c->filter_bank, (c->filter_alloc-1)*c->felem_size);

        memcpy(c->filter_bank + (c->filter_alloc*phase_count  )*c->felem_size, c->filter_bank + (c->filter_alloc - 1)*c->felem_size, c->felem_size);

    }



    c->compensation_distance= 0;

    if(!av_reduce(&c->src_incr, &c->dst_incr, out_rate, in_rate * (int64_t)phase_count, INT32_MAX/2))

        goto error;

    c->ideal_dst_incr= c->dst_incr;



    c->index= -phase_count*((c->filter_length-1)/2);

    c->frac= 0;



    return c;

error:

    av_free(c->filter_bank);

    av_free(c);

    return NULL;

}

static inline int hpel_motion_lowres(MpegEncContext *s,

                                     uint8_t *dest, uint8_t *src,

                                     int field_based, int field_select,

                                     int src_x, int src_y,

                                     int width, int height, int stride,

                                     int h_edge_pos, int v_edge_pos,

                                     int w, int h, h264_chroma_mc_func *pix_op,

                                     int motion_x, int motion_y)

{

    const int lowres   = s->avctx->lowres;

    const int op_index = FFMIN(lowres, 3);

    const int s_mask   = (2 << lowres) - 1;

    int emu = 0;

    int sx, sy;



    if (s->quarter_sample) {

        motion_x /= 2;

        motion_y /= 2;

    }



    sx = motion_x & s_mask;

    sy = motion_y & s_mask;

    src_x += motion_x >> lowres + 1;

    src_y += motion_y >> lowres + 1;



    src   += src_y * stride + src_x;



    if ((unsigned)src_x > FFMAX( h_edge_pos - (!!sx) - w,                 0) ||

        (unsigned)src_y > FFMAX((v_edge_pos >> field_based) - (!!sy) - h, 0)) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, src, s->linesize, w + 1,

                                (h + 1) << field_based, src_x,

                                src_y   << field_based,

                                h_edge_pos,

                                v_edge_pos);

        src = s->edge_emu_buffer;

        emu = 1;

    }



    sx = (sx << 2) >> lowres;

    sy = (sy << 2) >> lowres;

    if (field_select)

        src += s->linesize;

    pix_op[op_index](dest, src, stride, h, sx, sy);

    return emu;

}

static ResampleContext *resample_init(ResampleContext *c, int out_rate, int in_rate, int filter_size, int phase_shift, int linear,
                                    double cutoff0, enum AVSampleFormat format, enum SwrFilterType filter_type, int kaiser_beta,
                                    double precision, int cheby){
    double cutoff = cutoff0? cutoff0 : 0.97;
    double factor= FFMIN(out_rate * cutoff / in_rate, 1.0);
    int phase_count= 1<<phase_shift;
    if (!c || c->phase_shift != phase_shift || c->linear!=linear || c->factor != factor
           || c->filter_length != FFMAX((int)ceil(filter_size/factor), 1) || c->format != format
           || c->filter_type != filter_type || c->kaiser_beta != kaiser_beta) {
        c = av_mallocz(sizeof(*c));
        if (!c)
            return NULL;
        c->format= format;
        c->felem_size= av_get_bytes_per_sample(c->format);
        switch(c->format){
        case AV_SAMPLE_FMT_S16P:
            c->filter_shift = 15;
            break;
        case AV_SAMPLE_FMT_S32P:
            c->filter_shift = 30;
            break;
        case AV_SAMPLE_FMT_FLTP:
        case AV_SAMPLE_FMT_DBLP:
            c->filter_shift = 0;
            break;
        default:
            av_log(NULL, AV_LOG_ERROR, "Unsupported sample format\n");
            av_assert0(0);
        c->phase_shift   = phase_shift;
        c->phase_mask    = phase_count - 1;
        c->linear        = linear;
        c->factor        = factor;
        c->filter_length = FFMAX((int)ceil(filter_size/factor), 1);
        c->filter_alloc  = FFALIGN(c->filter_length, 8);
        c->filter_bank   = av_calloc(c->filter_alloc, (phase_count+1)*c->felem_size);
        c->filter_type   = filter_type;
        c->kaiser_beta   = kaiser_beta;
        if (!c->filter_bank)
        if (build_filter(c, (void*)c->filter_bank, factor, c->filter_length, c->filter_alloc, phase_count, 1<<c->filter_shift, filter_type, kaiser_beta))
        memcpy(c->filter_bank + (c->filter_alloc*phase_count+1)*c->felem_size, c->filter_bank, (c->filter_alloc-1)*c->felem_size);
        memcpy(c->filter_bank + (c->filter_alloc*phase_count  )*c->felem_size, c->filter_bank + (c->filter_alloc - 1)*c->felem_size, c->felem_size);
    c->compensation_distance= 0;
    if(!av_reduce(&c->src_incr, &c->dst_incr, out_rate, in_rate * (int64_t)phase_count, INT32_MAX/2))
    c->ideal_dst_incr= c->dst_incr;
    c->index= -phase_count*((c->filter_length-1)/2);
    c->frac= 0;
    return c;
error:
    av_freep(&c->filter_bank);
    av_free(c);
    return NULL;

AVResampleContext *swr_resample_init(AVResampleContext *c, int out_rate, int in_rate, int filter_size, int phase_shift, int linear, double cutoff){

    double factor= FFMIN(out_rate * cutoff / in_rate, 1.0);

    int phase_count= 1<<phase_shift;



    if (!c || c->phase_shift != phase_shift || c->linear!=linear || c->factor != factor

           || c->filter_length != FFMAX((int)ceil(filter_size/factor), 1)) {

        c = av_mallocz(sizeof(AVResampleContext));

        if (!c)

            return NULL;



        c->phase_shift   = phase_shift;

        c->phase_mask    = phase_count - 1;

        c->linear        = linear;

        c->factor        = factor;

        c->filter_length = FFMAX((int)ceil(filter_size/factor), 1);

        c->filter_bank   = av_mallocz(c->filter_length*(phase_count+1)*sizeof(FELEM));

        if (!c->filter_bank)

            goto error;

        if (build_filter(c->filter_bank, factor, c->filter_length, phase_count, 1<<FILTER_SHIFT, WINDOW_TYPE))

            goto error;

        memcpy(&c->filter_bank[c->filter_length*phase_count+1], c->filter_bank, (c->filter_length-1)*sizeof(FELEM));

        c->filter_bank[c->filter_length*phase_count]= c->filter_bank[c->filter_length - 1];

    }



    c->compensation_distance= 0;

    c->src_incr= out_rate;

    c->ideal_dst_incr= c->dst_incr= in_rate * phase_count;

    c->index= -phase_count*((c->filter_length-1)/2);

    c->frac= 0;



    return c;

error:

    av_free(c->filter_bank);

    av_free(c);

    return NULL;

}

