static int handle_sigp(S390CPU *cpu, struct kvm_run *run, uint8_t ipa1)

{

    CPUS390XState *env = &cpu->env;

    uint8_t order_code;

    uint16_t cpu_addr;

    int r = -1;

    S390CPU *target_cpu;



    cpu_synchronize_state(CPU(cpu));



    /* get order code */

    order_code = decode_basedisp_rs(env, run->s390_sieic.ipb) & SIGP_ORDER_MASK;



    cpu_addr = env->regs[ipa1 & 0x0f];

    target_cpu = s390_cpu_addr2state(cpu_addr);

    if (target_cpu == NULL) {

        goto out;

    }



    switch (order_code) {

    case SIGP_START:

        r = kvm_s390_cpu_start(target_cpu);

        break;

    case SIGP_RESTART:

        r = kvm_s390_cpu_restart(target_cpu);

        break;

    case SIGP_SET_ARCH:

        /* make the caller panic */

        return -1;

    case SIGP_INITIAL_CPU_RESET:

        r = s390_cpu_initial_reset(target_cpu);

        break;

    default:

        fprintf(stderr, "KVM: unknown SIGP: 0x%x\n", order_code);

        break;

    }



out:

    setcc(cpu, r ? 3 : 0);

    return 0;

}

uint32_t HELPER(xc)(CPUS390XState *env, uint32_t l, uint64_t dest,

                    uint64_t src)

{

    int i;

    unsigned char x;

    uint32_t cc = 0;



    HELPER_LOG("%s l %d dest %" PRIx64 " src %" PRIx64 "\n",

               __func__, l, dest, src);



#ifndef CONFIG_USER_ONLY

    /* xor with itself is the same as memset(0) */

    if ((l > 32) && (src == dest) &&

        (src & TARGET_PAGE_MASK) == ((src + l) & TARGET_PAGE_MASK)) {

        mvc_fast_memset(env, l + 1, dest, 0);

        return 0;

    }

#else

    if (src == dest) {

        memset(g2h(dest), 0, l + 1);

        return 0;

    }

#endif



    for (i = 0; i <= l; i++) {

        x = cpu_ldub_data(env, dest + i) ^ cpu_ldub_data(env, src + i);

        if (x) {

            cc = 1;

        }

        cpu_stb_data(env, dest + i, x);

    }

    return cc;

}

uint32_t HELPER(msa)(CPUS390XState *env, uint32_t r1, uint32_t r2, uint32_t r3,

                     uint32_t type)

{

    const uintptr_t ra = GETPC();

    const uint8_t mod = env->regs[0] & 0x80ULL;

    const uint8_t fc = env->regs[0] & 0x7fULL;

    CPUState *cs = CPU(s390_env_get_cpu(env));

    uint8_t subfunc[16] = { 0 };

    uint64_t param_addr;

    int i;



    switch (type) {

    case S390_FEAT_TYPE_KMAC:

    case S390_FEAT_TYPE_KIMD:

    case S390_FEAT_TYPE_KLMD:

    case S390_FEAT_TYPE_PCKMO:

    case S390_FEAT_TYPE_PCC:

        if (mod) {

            cpu_restore_state(cs, ra);

            program_interrupt(env, PGM_SPECIFICATION, 4);

            return 0;

        }

        break;

    }



    s390_get_feat_block(type, subfunc);

    if (!test_be_bit(fc, subfunc)) {

        cpu_restore_state(cs, ra);

        program_interrupt(env, PGM_SPECIFICATION, 4);

        return 0;

    }



    switch (fc) {

    case 0: /* query subfunction */

        for (i = 0; i < 16; i++) {

            param_addr = wrap_address(env, env->regs[1] + i);

            cpu_stb_data_ra(env, param_addr, subfunc[i], ra);

        }

        break;

    default:

        /* we don't implement any other subfunction yet */

        g_assert_not_reached();

    }



    return 0;

}

