                     const uint16_t *abuf0, uint8_t *dest, int dstW,

                     int uvalpha, enum PixelFormat dstFormat,

                     int flags, int y, enum PixelFormat target)

{

    int i;



    if (uvalpha < 2048) {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 = buf0[i * 2]     >> 7;

            int Y2 = buf0[i * 2 + 1] >> 7;

            int U  = ubuf1[i]        >> 7;

            int V  = vbuf1[i]        >> 7;



            output_pixels(i * 4, Y1, U, Y2, V);

        }

    } else {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 =  buf0[i * 2]          >> 7;

            int Y2 =  buf0[i * 2 + 1]      >> 7;

            int U  = (ubuf0[i] + ubuf1[i]) >> 8;

            int V  = (vbuf0[i] + vbuf1[i]) >> 8;



            output_pixels(i * 4, Y1, U, Y2, V);

        }

    }

}

yuv2rgb_2_c_template(SwsContext *c, const int16_t *buf[2],
                     const int16_t *ubuf[2], const int16_t *vbuf[2],
                     const int16_t *abuf[2], uint8_t *dest, int dstW,
                     int yalpha, int uvalpha, int y,
                     enum PixelFormat target, int hasAlpha)
{
    const int16_t *buf0  = buf[0],  *buf1  = buf[1],
                  *ubuf0 = ubuf[0], *ubuf1 = ubuf[1],
                  *vbuf0 = vbuf[0], *vbuf1 = vbuf[1],
                  *abuf0 = hasAlpha ? abuf[0] : NULL,
                  *abuf1 = hasAlpha ? abuf[1] : NULL;
    int  yalpha1 = 4095 - yalpha;
    int uvalpha1 = 4095 - uvalpha;
    int i;
    for (i = 0; i < (dstW >> 1); i++) {
        int Y1 = (buf0[i * 2]     * yalpha1  + buf1[i * 2]     * yalpha)  >> 19;
        int Y2 = (buf0[i * 2 + 1] * yalpha1  + buf1[i * 2 + 1] * yalpha)  >> 19;
        int U  = (ubuf0[i]        * uvalpha1 + ubuf1[i]        * uvalpha) >> 19;
        int V  = (vbuf0[i]        * uvalpha1 + vbuf1[i]        * uvalpha) >> 19;
        int A1, A2;
        const void *r =  c->table_rV[V],
                   *g = (c->table_gU[U] + c->table_gV[V]),
                   *b =  c->table_bU[U];
        if (hasAlpha) {
            A1 = (abuf0[i * 2    ] * yalpha1 + abuf1[i * 2    ] * yalpha) >> 19;
            A2 = (abuf0[i * 2 + 1] * yalpha1 + abuf1[i * 2 + 1] * yalpha) >> 19;
        }
        yuv2rgb_write(dest, i, Y1, Y2, hasAlpha ? A1 : 0, hasAlpha ? A2 : 0,
                      r, g, b, y, target, hasAlpha);
    }
}

static inline int onenand_prog_main(OneNANDState *s, int sec, int secn,

                void *src)

{

    int result = 0;



    if (secn > 0) {

        uint32_t size = (uint32_t)secn * 512;

        const uint8_t *sp = (const uint8_t *)src;

        uint8_t *dp = 0;

        if (s->blk_cur) {

            dp = g_malloc(size);

            if (!dp || blk_read(s->blk_cur, sec, dp, secn) < 0) {

                result = 1;

            }

        } else {

            if (sec + secn > s->secs_cur) {

                result = 1;

            } else {

                dp = (uint8_t *)s->current + (sec << 9);

            }

        }

        if (!result) {

            uint32_t i;

            for (i = 0; i < size; i++) {

                dp[i] &= sp[i];

            }

            if (s->blk_cur) {

                result = blk_write(s->blk_cur, sec, dp, secn) < 0;

            }

        }

        if (dp && s->blk_cur) {

            g_free(dp);

        }

    }



    return result;

}

static inline int onenand_prog_spare(OneNANDState *s, int sec, int secn,

                void *src)

{

    int result = 0;

    if (secn > 0) {

        const uint8_t *sp = (const uint8_t *)src;

        uint8_t *dp = 0, *dpp = 0;

        if (s->blk_cur) {

            dp = g_malloc(512);

            if (!dp

                || blk_read(s->blk_cur, s->secs_cur + (sec >> 5), dp, 1) < 0) {

                result = 1;

            } else {

                dpp = dp + ((sec & 31) << 4);

            }

        } else {

            if (sec + secn > s->secs_cur) {

                result = 1;

            } else {

                dpp = s->current + (s->secs_cur << 9) + (sec << 4);

            }

        }

        if (!result) {

            uint32_t i;

            for (i = 0; i < (secn << 4); i++) {

                dpp[i] &= sp[i];

            }

            if (s->blk_cur) {

                result = blk_write(s->blk_cur, s->secs_cur + (sec >> 5),

                                   dp, 1) < 0;

            }

        }

        g_free(dp);

    }

    return result;

}

static inline int onenand_prog_spare(OneNANDState *s, int sec, int secn,

                void *src)

{

    int result = 0;

    if (secn > 0) {

        const uint8_t *sp = (const uint8_t *)src;

        uint8_t *dp = 0, *dpp = 0;

        if (s->bdrv_cur) {

            dp = g_malloc(512);

            if (!dp || bdrv_read(s->bdrv_cur,

                                 s->secs_cur + (sec >> 5),

                                 dp, 1) < 0) {

                result = 1;

            } else {

                dpp = dp + ((sec & 31) << 4);

            }

        } else {

            if (sec + secn > s->secs_cur) {

                result = 1;

            } else {

                dpp = s->current + (s->secs_cur << 9) + (sec << 4);

            }

        }

        if (!result) {

            uint32_t i;

            for (i = 0; i < (secn << 4); i++) {

                dpp[i] &= sp[i];

            }

            if (s->bdrv_cur) {

                result = bdrv_write(s->bdrv_cur, s->secs_cur + (sec >> 5),

                                    dp, 1) < 0;

            }

        }

        g_free(dp);

    }

    return result;

}

static inline int onenand_erase(OneNANDState *s, int sec, int num)

{

    uint8_t *blankbuf, *tmpbuf;



    blankbuf = g_malloc(512);

    tmpbuf = g_malloc(512);

    memset(blankbuf, 0xff, 512);

    for (; num > 0; num--, sec++) {

        if (s->blk_cur) {

            int erasesec = s->secs_cur + (sec >> 5);

            if (blk_write(s->blk_cur, sec, blankbuf, 1) < 0) {

                goto fail;

            }

            if (blk_read(s->blk_cur, erasesec, tmpbuf, 1) < 0) {

                goto fail;

            }

            memcpy(tmpbuf + ((sec & 31) << 4), blankbuf, 1 << 4);

            if (blk_write(s->blk_cur, erasesec, tmpbuf, 1) < 0) {

                goto fail;

            }

        } else {

            if (sec + 1 > s->secs_cur) {

                goto fail;

            }

            memcpy(s->current + (sec << 9), blankbuf, 512);

            memcpy(s->current + (s->secs_cur << 9) + (sec << 4),

                   blankbuf, 1 << 4);

        }

    }



    g_free(tmpbuf);

    g_free(blankbuf);

    return 0;



fail:

    g_free(tmpbuf);

    g_free(blankbuf);

    return 1;

}

static int nbd_receive_list(QIOChannel *ioc, char **name, Error **errp)

{

    uint64_t magic;

    uint32_t opt;

    uint32_t type;

    uint32_t len;

    uint32_t namelen;



    *name = NULL;

    if (read_sync(ioc, &magic, sizeof(magic)) != sizeof(magic)) {

        error_setg(errp, "failed to read list option magic");

        return -1;

    }

    magic = be64_to_cpu(magic);

    if (magic != NBD_REP_MAGIC) {

        error_setg(errp, "Unexpected option list magic");

        return -1;

    }

    if (read_sync(ioc, &opt, sizeof(opt)) != sizeof(opt)) {

        error_setg(errp, "failed to read list option");

        return -1;

    }

    opt = be32_to_cpu(opt);

    if (opt != NBD_OPT_LIST) {

        error_setg(errp, "Unexpected option type %x expected %x",

                   opt, NBD_OPT_LIST);

        return -1;

    }



    if (read_sync(ioc, &type, sizeof(type)) != sizeof(type)) {

        error_setg(errp, "failed to read list option type");

        return -1;

    }

    type = be32_to_cpu(type);

    if (type == NBD_REP_ERR_UNSUP) {

        return 0;

    }

    if (nbd_handle_reply_err(opt, type, errp) < 0) {

        return -1;

    }



    if (read_sync(ioc, &len, sizeof(len)) != sizeof(len)) {

        error_setg(errp, "failed to read option length");

        return -1;

    }

    len = be32_to_cpu(len);



    if (type == NBD_REP_ACK) {

        if (len != 0) {

            error_setg(errp, "length too long for option end");

            return -1;

        }

    } else if (type == NBD_REP_SERVER) {

        if (read_sync(ioc, &namelen, sizeof(namelen)) != sizeof(namelen)) {

            error_setg(errp, "failed to read option name length");

            return -1;

        }

        namelen = be32_to_cpu(namelen);

        if (len != (namelen + sizeof(namelen))) {

            error_setg(errp, "incorrect option mame length");

            return -1;

        }

        if (namelen > 255) {

            error_setg(errp, "export name length too long %d", namelen);

            return -1;

        }



        *name = g_new0(char, namelen + 1);

        if (read_sync(ioc, *name, namelen) != namelen) {

            error_setg(errp, "failed to read export name");

            g_free(*name);

            *name = NULL;

            return -1;

        }

        (*name)[namelen] = '\0';

    } else {

        error_setg(errp, "Unexpected reply type %x expected %x",

                   type, NBD_REP_SERVER);

        return -1;

    }

    return 1;

}

static int nbd_receive_list(QIOChannel *ioc, const char *want, bool *match,

                            Error **errp)

{

    nbd_opt_reply reply;

    uint32_t len;

    uint32_t namelen;

    char name[NBD_MAX_NAME_SIZE + 1];

    int error;



    if (nbd_receive_option_reply(ioc, NBD_OPT_LIST, &reply, errp) < 0) {

        return -1;

    }

    error = nbd_handle_reply_err(ioc, &reply, errp);

    if (error <= 0) {

        /* The server did not support NBD_OPT_LIST, so set *match on

         * the assumption that any name will be accepted.  */

        *match = true;

        return error;

    }

    len = reply.length;



    if (reply.type == NBD_REP_ACK) {

        if (len != 0) {

            error_setg(errp, "length too long for option end");

            nbd_send_opt_abort(ioc);

            return -1;

        }

        return 0;

    } else if (reply.type != NBD_REP_SERVER) {

        error_setg(errp, "Unexpected reply type %" PRIx32 " expected %x",

                   reply.type, NBD_REP_SERVER);

        nbd_send_opt_abort(ioc);

        return -1;

    }



    if (len < sizeof(namelen) || len > NBD_MAX_BUFFER_SIZE) {

        error_setg(errp, "incorrect option length %" PRIu32, len);

        nbd_send_opt_abort(ioc);

        return -1;

    }

    if (read_sync(ioc, &namelen, sizeof(namelen), errp) < 0) {

        error_prepend(errp, "failed to read option name length");

        nbd_send_opt_abort(ioc);

        return -1;

    }

    namelen = be32_to_cpu(namelen);

    len -= sizeof(namelen);

    if (len < namelen) {

        error_setg(errp, "incorrect option name length");

        nbd_send_opt_abort(ioc);

        return -1;

    }

    if (namelen != strlen(want)) {

        if (drop_sync(ioc, len, errp) < 0) {

            error_prepend(errp, "failed to skip export name with wrong length");

            nbd_send_opt_abort(ioc);

            return -1;

        }

        return 1;

    }



    assert(namelen < sizeof(name));

    if (read_sync(ioc, name, namelen, errp) < 0) {

        error_prepend(errp, "failed to read export name");

        nbd_send_opt_abort(ioc);

        return -1;

    }

    name[namelen] = '\0';

    len -= namelen;

    if (drop_sync(ioc, len, errp) < 0) {

        error_prepend(errp, "failed to read export description");

        nbd_send_opt_abort(ioc);

        return -1;

    }

    if (!strcmp(name, want)) {

        *match = true;

    }

    return 1;

}

static int nbd_negotiate_send_rep_len(QIOChannel *ioc, uint32_t type,

                                      uint32_t opt, uint32_t len, Error **errp)

{

    uint64_t magic;



    trace_nbd_negotiate_send_rep_len(opt, type, len);



    magic = cpu_to_be64(NBD_REP_MAGIC);

    if (nbd_write(ioc, &magic, sizeof(magic), errp) < 0) {

        error_prepend(errp, "write failed (rep magic): ");

        return -EINVAL;

    }



    opt = cpu_to_be32(opt);

    if (nbd_write(ioc, &opt, sizeof(opt), errp) < 0) {

        error_prepend(errp, "write failed (rep opt): ");

        return -EINVAL;

    }



    type = cpu_to_be32(type);

    if (nbd_write(ioc, &type, sizeof(type), errp) < 0) {

        error_prepend(errp, "write failed (rep type): ");

        return -EINVAL;

    }



    len = cpu_to_be32(len);

    if (nbd_write(ioc, &len, sizeof(len), errp) < 0) {

        error_prepend(errp, "write failed (rep data length): ");

        return -EINVAL;

    }

    return 0;

}

static int nbd_receive_option_reply(QIOChannel *ioc, uint32_t opt,

                                    nbd_opt_reply *reply, Error **errp)

{

    QEMU_BUILD_BUG_ON(sizeof(*reply) != 20);

    if (nbd_read(ioc, reply, sizeof(*reply), errp) < 0) {

        error_prepend(errp, "failed to read option reply");

        nbd_send_opt_abort(ioc);

        return -1;

    }

    be64_to_cpus(&reply->magic);

    be32_to_cpus(&reply->option);

    be32_to_cpus(&reply->type);

    be32_to_cpus(&reply->length);



    trace_nbd_receive_option_reply(reply->option, reply->type, reply->length);



    if (reply->magic != NBD_REP_MAGIC) {

        error_setg(errp, "Unexpected option reply magic");

        nbd_send_opt_abort(ioc);

        return -1;

    }

    if (reply->option != opt) {

        error_setg(errp, "Unexpected option type %x expected %x",

                   reply->option, opt);

        nbd_send_opt_abort(ioc);

        return -1;

    }

    return 0;

}

static int hwmap_config_output(AVFilterLink *outlink)

{

    AVFilterContext *avctx = outlink->src;

    HWMapContext      *ctx = avctx->priv;

    AVFilterLink   *inlink = avctx->inputs[0];

    AVHWFramesContext *hwfc;

    AVBufferRef *device;

    const AVPixFmtDescriptor *desc;

    int err;



    av_log(avctx, AV_LOG_DEBUG, "Configure hwmap %s -> %s.\n",

           av_get_pix_fmt_name(inlink->format),

           av_get_pix_fmt_name(outlink->format));



    av_buffer_unref(&ctx->hwframes_ref);



    device = avctx->hw_device_ctx;



    if (inlink->hw_frames_ctx) {

        hwfc = (AVHWFramesContext*)inlink->hw_frames_ctx->data;



        if (ctx->derive_device_type) {

            enum AVHWDeviceType type;



            type = av_hwdevice_find_type_by_name(ctx->derive_device_type);

            if (type == AV_HWDEVICE_TYPE_NONE) {

                av_log(avctx, AV_LOG_ERROR, "Invalid device type.\n");

                goto fail;

            }



            err = av_hwdevice_ctx_create_derived(&device, type,

                                                 hwfc->device_ref, 0);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to created derived "

                       "device context: %d.\n", err);

                goto fail;

            }

        }



        desc = av_pix_fmt_desc_get(outlink->format);

        if (!desc) {

            err = AVERROR(EINVAL);

            goto fail;

        }



        if (inlink->format == hwfc->format &&

            (desc->flags & AV_PIX_FMT_FLAG_HWACCEL)) {

            // Map between two hardware formats (including the case of

            // undoing an existing mapping).



            if (!device) {

                av_log(avctx, AV_LOG_ERROR, "A device reference is "

                       "required to map to a hardware format.\n");

                err = AVERROR(EINVAL);

                goto fail;

            }



            err = av_hwframe_ctx_create_derived(&ctx->hwframes_ref,

                                                outlink->format,

                                                device,

                                                inlink->hw_frames_ctx, 0);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to create derived "

                       "frames context: %d.\n", err);

                goto fail;

            }



        } else if ((outlink->format == hwfc->format &&

                    inlink->format  == hwfc->sw_format) ||

                   inlink->format == hwfc->format) {

            // Map from a hardware format to a software format, or

            // undo an existing such mapping.



            ctx->hwframes_ref = av_buffer_ref(inlink->hw_frames_ctx);

            if (!ctx->hwframes_ref) {

                err = AVERROR(ENOMEM);

                goto fail;

            }



        } else {

            // Non-matching formats - not supported.



            av_log(avctx, AV_LOG_ERROR, "Unsupported formats for "

                   "hwmap: from %s (%s) to %s.\n",

                   av_get_pix_fmt_name(inlink->format),

                   av_get_pix_fmt_name(hwfc->format),

                   av_get_pix_fmt_name(outlink->format));

            err = AVERROR(EINVAL);

            goto fail;

        }

    } else if (avctx->hw_device_ctx) {

        // Map from a software format to a hardware format.  This

        // creates a new hwframe context like hwupload, but then

        // returns frames mapped from that to the previous link in

        // order to fill them without an additional copy.



        if (!device) {

            av_log(avctx, AV_LOG_ERROR, "A device reference is "

                   "required to create new frames with backwards "

                   "mapping.\n");

            err = AVERROR(EINVAL);

            goto fail;

        }



        ctx->map_backwards = 1;



        ctx->hwframes_ref = av_hwframe_ctx_alloc(device);

        if (!ctx->hwframes_ref) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        hwfc = (AVHWFramesContext*)ctx->hwframes_ref->data;



        hwfc->format    = outlink->format;

        hwfc->sw_format = inlink->format;

        hwfc->width     = inlink->w;

        hwfc->height    = inlink->h;



        err = av_hwframe_ctx_init(ctx->hwframes_ref);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Failed to create frame "

                   "context for backward mapping: %d.\n", err);

            goto fail;

        }



    } else {

        av_log(avctx, AV_LOG_ERROR, "Mapping requires a hardware "

               "context (a device, or frames on input).\n");

        return AVERROR(EINVAL);

    }



    outlink->hw_frames_ctx = av_buffer_ref(ctx->hwframes_ref);

    if (!outlink->hw_frames_ctx) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    outlink->w = inlink->w;

    outlink->h = inlink->h;



    return 0;



fail:

    av_buffer_unref(&ctx->hwframes_ref);

    return err;

}

static int config_input_ref(AVFilterLink *inlink)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(inlink->format);

    AVFilterContext *ctx  = inlink->dst;

    PSNRContext *s = ctx->priv;

    unsigned sum;

    int j;



    s->nb_components = desc->nb_components;

    if (ctx->inputs[0]->w != ctx->inputs[1]->w ||

        ctx->inputs[0]->h != ctx->inputs[1]->h) {

        av_log(ctx, AV_LOG_ERROR, "Width and height of input videos must be same.\n");

        return AVERROR(EINVAL);

    }

    if (ctx->inputs[0]->format != ctx->inputs[1]->format) {

        av_log(ctx, AV_LOG_ERROR, "Inputs must be of same pixel format.\n");

        return AVERROR(EINVAL);

    }



    s->max[0] = (1 << (desc->comp[0].depth_minus1 + 1)) - 1;

    s->max[1] = (1 << (desc->comp[1].depth_minus1 + 1)) - 1;

    s->max[2] = (1 << (desc->comp[2].depth_minus1 + 1)) - 1;

    s->max[3] = (1 << (desc->comp[3].depth_minus1 + 1)) - 1;



    s->is_rgb = ff_fill_rgba_map(s->rgba_map, inlink->format) >= 0;

    s->comps[0] = s->is_rgb ? 'r' : 'y' ;

    s->comps[1] = s->is_rgb ? 'g' : 'u' ;

    s->comps[2] = s->is_rgb ? 'b' : 'v' ;

    s->comps[3] = 'a';



    s->planeheight[1] = s->planeheight[2] = FF_CEIL_RSHIFT(inlink->h, desc->log2_chroma_h);

    s->planeheight[0] = s->planeheight[3] = inlink->h;

    s->planewidth[1]  = s->planewidth[2]  = FF_CEIL_RSHIFT(inlink->w, desc->log2_chroma_w);

    s->planewidth[0]  = s->planewidth[3]  = inlink->w;

    sum = 0;

    for (j = 0; j < s->nb_components; j++)

        sum += s->planeheight[j] * s->planewidth[j];

    for (j = 0; j < s->nb_components; j++) {

        s->planeweight[j] = (double) s->planeheight[j] * s->planewidth[j] / sum;

        s->average_max += s->max[j] * s->planeweight[j];

    }



    s->compute_mse = desc->comp[0].depth_minus1 > 7 ? compute_images_mse_16bit : compute_images_mse;



    return 0;

}

static int vsink_query_formats(AVFilterContext *ctx)

{

    BufferSinkContext *buf = ctx->priv;

    AVFilterFormats *formats = NULL;

    unsigned i;

    int ret;



    if (buf->pixel_fmts_size % sizeof(*buf->pixel_fmts)) {

        av_log(ctx, AV_LOG_ERROR, "Invalid size for format list\n");

        return AVERROR(EINVAL);

    }



    if (buf->pixel_fmts_size) {

        for (i = 0; i < NB_ITEMS(buf->pixel_fmts); i++)

            if ((ret = ff_add_format(&formats, buf->pixel_fmts[i])) < 0)

                return ret;

        ff_set_common_formats(ctx, formats);

    } else {

        ff_default_query_formats(ctx);

    }



    return 0;

}

av_cold int ff_vaapi_encode_init(AVCodecContext *avctx,

                                 const VAAPIEncodeType *type)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    AVVAAPIFramesContext *recon_hwctx = NULL;

    AVVAAPIHWConfig *hwconfig = NULL;

    AVHWFramesConstraints *constraints = NULL;

    enum AVPixelFormat recon_format;

    VAStatus vas;

    int err, i;



    if (!avctx->hw_frames_ctx) {

        av_log(avctx, AV_LOG_ERROR, "A hardware frames reference is "

               "required to associate the encoding device.\n");

        return AVERROR(EINVAL);

    }



    ctx->codec = type;

    ctx->codec_options = ctx->codec_options_data;



    ctx->va_config  = VA_INVALID_ID;

    ctx->va_context = VA_INVALID_ID;



    ctx->priv_data = av_mallocz(type->priv_data_size);

    if (!ctx->priv_data) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    ctx->input_frames_ref = av_buffer_ref(avctx->hw_frames_ctx);

    if (!ctx->input_frames_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->input_frames = (AVHWFramesContext*)ctx->input_frames_ref->data;



    ctx->device_ref = av_buffer_ref(ctx->input_frames->device_ref);

    if (!ctx->device_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->device = (AVHWDeviceContext*)ctx->device_ref->data;

    ctx->hwctx = ctx->device->hwctx;



    err = ctx->codec->init(avctx);

    if (err < 0)

        goto fail;



    err = vaapi_encode_check_config(avctx);

    if (err < 0)

        goto fail;



    vas = vaCreateConfig(ctx->hwctx->display,

                         ctx->va_profile, ctx->va_entrypoint,

                         ctx->config_attributes, ctx->nb_config_attributes,

                         &ctx->va_config);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create encode pipeline "

               "configuration: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    hwconfig = av_hwdevice_hwconfig_alloc(ctx->device_ref);

    if (!hwconfig) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    hwconfig->config_id = ctx->va_config;



    constraints = av_hwdevice_get_hwframe_constraints(ctx->device_ref,

                                                      hwconfig);

    if (!constraints) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    // Probably we can use the input surface format as the surface format

    // of the reconstructed frames.  If not, we just pick the first (only?)

    // format in the valid list and hope that it all works.

    recon_format = AV_PIX_FMT_NONE;

    if (constraints->valid_sw_formats) {

        for (i = 0; constraints->valid_sw_formats[i] != AV_PIX_FMT_NONE; i++) {

            if (ctx->input_frames->sw_format ==

                constraints->valid_sw_formats[i]) {

                recon_format = ctx->input_frames->sw_format;

                break;

            }

        }

        if (recon_format == AV_PIX_FMT_NONE) {

            // No match.  Just use the first in the supported list and

            // hope for the best.

            recon_format = constraints->valid_sw_formats[0];

        }

    } else {

        // No idea what to use; copy input format.

        recon_format = ctx->input_frames->sw_format;

    }

    av_log(avctx, AV_LOG_DEBUG, "Using %s as format of "

           "reconstructed frames.\n", av_get_pix_fmt_name(recon_format));



    if (ctx->aligned_width  < constraints->min_width  ||

        ctx->aligned_height < constraints->min_height ||

        ctx->aligned_width  > constraints->max_width ||

        ctx->aligned_height > constraints->max_height) {

        av_log(avctx, AV_LOG_ERROR, "Hardware does not support encoding at "

               "size %dx%d (constraints: width %d-%d height %d-%d).\n",

               ctx->aligned_width, ctx->aligned_height,

               constraints->min_width,  constraints->max_width,

               constraints->min_height, constraints->max_height);

        err = AVERROR(EINVAL);

        goto fail;

    }



    av_freep(&hwconfig);

    av_hwframe_constraints_free(&constraints);



    ctx->recon_frames_ref = av_hwframe_ctx_alloc(ctx->device_ref);

    if (!ctx->recon_frames_ref) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    ctx->recon_frames = (AVHWFramesContext*)ctx->recon_frames_ref->data;



    ctx->recon_frames->format    = AV_PIX_FMT_VAAPI;

    ctx->recon_frames->sw_format = recon_format;

    ctx->recon_frames->width     = ctx->aligned_width;

    ctx->recon_frames->height    = ctx->aligned_height;

    ctx->recon_frames->initial_pool_size = ctx->nb_recon_frames;



    err = av_hwframe_ctx_init(ctx->recon_frames_ref);

    if (err < 0) {

        av_log(avctx, AV_LOG_ERROR, "Failed to initialise reconstructed "

               "frame context: %d.\n", err);

        goto fail;

    }

    recon_hwctx = ctx->recon_frames->hwctx;



    vas = vaCreateContext(ctx->hwctx->display, ctx->va_config,

                          ctx->aligned_width, ctx->aligned_height,

                          VA_PROGRESSIVE,

                          recon_hwctx->surface_ids,

                          recon_hwctx->nb_surfaces,

                          &ctx->va_context);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "Failed to create encode pipeline "

               "context: %d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    ctx->input_order  = 0;

    ctx->output_delay = avctx->max_b_frames;

    ctx->decode_delay = 1;

    ctx->output_order = - ctx->output_delay - 1;



    if (ctx->codec->sequence_params_size > 0) {

        ctx->codec_sequence_params =

            av_mallocz(ctx->codec->sequence_params_size);

        if (!ctx->codec_sequence_params) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }

    if (ctx->codec->picture_params_size > 0) {

        ctx->codec_picture_params =

            av_mallocz(ctx->codec->picture_params_size);

        if (!ctx->codec_picture_params) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }



    if (ctx->codec->init_sequence_params) {

        err = ctx->codec->init_sequence_params(avctx);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Codec sequence initialisation "

                   "failed: %d.\n", err);

            goto fail;

        }

    }



    ctx->output_buffer_pool =

        av_buffer_pool_init2(sizeof(VABufferID), avctx,

                             &vaapi_encode_alloc_output_buffer, NULL);

    if (!ctx->output_buffer_pool) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    // All I are IDR for now.

    ctx->i_per_idr = 0;

    ctx->p_per_i = ((avctx->gop_size + avctx->max_b_frames) /

                    (avctx->max_b_frames + 1));

    ctx->b_per_p = avctx->max_b_frames;



    // This should be configurable somehow.  (Needs testing on a machine

    // where it actually overlaps properly, though.)

    ctx->issue_mode = ISSUE_MODE_MAXIMISE_THROUGHPUT;



    return 0;



fail:

    av_freep(&hwconfig);

    av_hwframe_constraints_free(&constraints);

    ff_vaapi_encode_close(avctx);

    return err;

}

void error_set_win32(Error **errp, int win32_err, ErrorClass err_class,

                     const char *fmt, ...)

{

    va_list ap;

    char *msg1, *msg2;



    if (errp == NULL) {

        return;

    }



    va_start(ap, fmt);

    error_setv(errp, err_class, fmt, ap);

    va_end(ap);



    if (win32_err != 0) {

        msg1 = (*errp)->msg;

        msg2 = g_win32_error_message(win32_err);

        (*errp)->msg = g_strdup_printf("%s: %s (error: %x)", msg1, msg2,

                                       (unsigned)win32_err);

        g_free(msg2);

        g_free(msg1);

    }

}

void error_setg_errno(Error **errp, int os_errno, const char *fmt, ...)

{

    va_list ap;

    char *msg;

    int saved_errno = errno;



    if (errp == NULL) {

        return;

    }



    va_start(ap, fmt);

    error_setv(errp, ERROR_CLASS_GENERIC_ERROR, fmt, ap);

    va_end(ap);



    if (os_errno != 0) {

        msg = (*errp)->msg;

        (*errp)->msg = g_strdup_printf("%s: %s", msg, strerror(os_errno));

        g_free(msg);

    }



    errno = saved_errno;

}

void error_set(Error **errp, const char *fmt, ...)

{

    Error *err;

    va_list ap;



    if (errp == NULL) {

        return;

    }

    assert(*errp == NULL);



    err = g_malloc0(sizeof(*err));



    va_start(ap, fmt);

    err->obj = qobject_to_qdict(qobject_from_jsonv(fmt, &ap));

    va_end(ap);

    err->msg = qerror_format(fmt, err->obj);



    *errp = err;

}

static int monitor_fprintf(FILE *stream, const char *fmt, ...)

{

    va_list ap;

    va_start(ap, fmt);

    monitor_vprintf((Monitor *)stream, fmt, ap);

    va_end(ap);

    return 0;

}

static void frame_end(MpegEncContext *s)

{

    if (s->unrestricted_mv &&

        s->current_picture.reference &&

        !s->intra_only) {

        const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(s->avctx->pix_fmt);

        int hshift = desc->log2_chroma_w;

        int vshift = desc->log2_chroma_h;

        s->mpvencdsp.draw_edges(s->current_picture.f->data[0],

                                s->current_picture.f->linesize[0],

                                s->h_edge_pos, s->v_edge_pos,

                                EDGE_WIDTH, EDGE_WIDTH,

                                EDGE_TOP | EDGE_BOTTOM);

        s->mpvencdsp.draw_edges(s->current_picture.f->data[1],

                                s->current_picture.f->linesize[1],

                                s->h_edge_pos >> hshift,

                                s->v_edge_pos >> vshift,

                                EDGE_WIDTH >> hshift,

                                EDGE_WIDTH >> vshift,

                                EDGE_TOP | EDGE_BOTTOM);

        s->mpvencdsp.draw_edges(s->current_picture.f->data[2],

                                s->current_picture.f->linesize[2],

                                s->h_edge_pos >> hshift,

                                s->v_edge_pos >> vshift,

                                EDGE_WIDTH >> hshift,

                                EDGE_WIDTH >> vshift,

                                EDGE_TOP | EDGE_BOTTOM);

    }



    emms_c();



    s->last_pict_type                 = s->pict_type;

    s->last_lambda_for [s->pict_type] = s->current_picture_ptr->f->quality;

    if (s->pict_type!= AV_PICTURE_TYPE_B)

        s->last_non_b_pict_type = s->pict_type;



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS


    av_frame_copy_props(s->avctx->coded_frame, s->current_picture.f);

FF_ENABLE_DEPRECATION_WARNINGS

#endif

#if FF_API_ERROR_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    memcpy(s->current_picture.f->error, s->current_picture.encoding_error,

           sizeof(s->current_picture.encoding_error));

FF_ENABLE_DEPRECATION_WARNINGS

#endif

}

void ff_xvmc_decode_mb(MpegEncContext *s)

{

    XvMCMacroBlock *mv_block;

    struct xvmc_pix_fmt *render;

    int i, cbp, blocks_per_mb;



    const int mb_xy = s->mb_y * s->mb_stride + s->mb_x;





    if (s->encoding) {

        av_log(s->avctx, AV_LOG_ERROR, "XVMC doesn't support encoding!!!\n");

        return;

    }



    // from ff_mpv_decode_mb(), update DC predictors for P macroblocks

    if (!s->mb_intra) {

        s->last_dc[0] =

        s->last_dc[1] =

        s->last_dc[2] =  128 << s->intra_dc_precision;

    }



    // MC doesn't skip blocks

    s->mb_skipped = 0;





    // Do I need to export quant when I could not perform postprocessing?

    // Anyway, it doesn't hurt.

    s->current_picture.qscale_table[mb_xy] = s->qscale;



    // start of XVMC-specific code

    render = (struct xvmc_pix_fmt*)s->current_picture.f->data[2];

    assert(render);

    assert(render->xvmc_id == AV_XVMC_ID);

    assert(render->mv_blocks);



    // take the next free macroblock

    mv_block = &render->mv_blocks[render->start_mv_blocks_num +

                                  render->filled_mv_blocks_num];



    mv_block->x        = s->mb_x;

    mv_block->y        = s->mb_y;

    mv_block->dct_type = s->interlaced_dct; // XVMC_DCT_TYPE_FRAME/FIELD;

    if (s->mb_intra) {

        mv_block->macroblock_type = XVMC_MB_TYPE_INTRA; // no MC, all done

    } else {

        mv_block->macroblock_type = XVMC_MB_TYPE_PATTERN;



        if (s->mv_dir & MV_DIR_FORWARD) {

            mv_block->macroblock_type |= XVMC_MB_TYPE_MOTION_FORWARD;

            // PMV[n][dir][xy] = mv[dir][n][xy]

            mv_block->PMV[0][0][0] = s->mv[0][0][0];

            mv_block->PMV[0][0][1] = s->mv[0][0][1];

            mv_block->PMV[1][0][0] = s->mv[0][1][0];

            mv_block->PMV[1][0][1] = s->mv[0][1][1];

        }

        if (s->mv_dir & MV_DIR_BACKWARD) {

            mv_block->macroblock_type |= XVMC_MB_TYPE_MOTION_BACKWARD;

            mv_block->PMV[0][1][0] = s->mv[1][0][0];

            mv_block->PMV[0][1][1] = s->mv[1][0][1];

            mv_block->PMV[1][1][0] = s->mv[1][1][0];

            mv_block->PMV[1][1][1] = s->mv[1][1][1];

        }



        switch(s->mv_type) {

            case  MV_TYPE_16X16:

                mv_block->motion_type = XVMC_PREDICTION_FRAME;

                break;

            case  MV_TYPE_16X8:

                mv_block->motion_type = XVMC_PREDICTION_16x8;

                break;

            case  MV_TYPE_FIELD:

                mv_block->motion_type = XVMC_PREDICTION_FIELD;

                if (s->picture_structure == PICT_FRAME) {

                    mv_block->PMV[0][0][1] <<= 1;

                    mv_block->PMV[1][0][1] <<= 1;

                    mv_block->PMV[0][1][1] <<= 1;

                    mv_block->PMV[1][1][1] <<= 1;

                }

                break;

            case  MV_TYPE_DMV:

                mv_block->motion_type = XVMC_PREDICTION_DUAL_PRIME;

                if (s->picture_structure == PICT_FRAME) {



                    mv_block->PMV[0][0][0] = s->mv[0][0][0];      // top from top

                    mv_block->PMV[0][0][1] = s->mv[0][0][1] << 1;



                    mv_block->PMV[0][1][0] = s->mv[0][0][0];      // bottom from bottom

                    mv_block->PMV[0][1][1] = s->mv[0][0][1] << 1;



                    mv_block->PMV[1][0][0] = s->mv[0][2][0];      // dmv00, top from bottom

                    mv_block->PMV[1][0][1] = s->mv[0][2][1] << 1; // dmv01



                    mv_block->PMV[1][1][0] = s->mv[0][3][0];      // dmv10, bottom from top

                    mv_block->PMV[1][1][1] = s->mv[0][3][1] << 1; // dmv11



                } else {

                    mv_block->PMV[0][1][0] = s->mv[0][2][0];      // dmv00

                    mv_block->PMV[0][1][1] = s->mv[0][2][1];      // dmv01

                }

                break;

            default:

                assert(0);

        }



        mv_block->motion_vertical_field_select = 0;



        // set correct field references

        if (s->mv_type == MV_TYPE_FIELD || s->mv_type == MV_TYPE_16X8) {

            mv_block->motion_vertical_field_select |= s->field_select[0][0];

            mv_block->motion_vertical_field_select |= s->field_select[1][0] << 1;

            mv_block->motion_vertical_field_select |= s->field_select[0][1] << 2;

            mv_block->motion_vertical_field_select |= s->field_select[1][1] << 3;

        }

    } // !intra

    // time to handle data blocks

    mv_block->index = render->next_free_data_block_num;



    blocks_per_mb = 6;

    if (s->chroma_format >= 2) {

        blocks_per_mb = 4 + (1 << s->chroma_format);

    }



    // calculate cbp

    cbp = 0;

    for (i = 0; i < blocks_per_mb; i++) {

        cbp += cbp;

        if (s->block_last_index[i] >= 0)

            cbp++;

    }



    if (s->avctx->flags & AV_CODEC_FLAG_GRAY) {

        if (s->mb_intra) {                                   // intra frames are always full chroma blocks

            for (i = 4; i < blocks_per_mb; i++) {

                memset(s->pblocks[i], 0, sizeof(*s->pblocks[i]));  // so we need to clear them

                if (!render->unsigned_intra)

                    *s->pblocks[i][0] = 1 << 10;

            }

        } else {

            cbp &= 0xf << (blocks_per_mb - 4);

            blocks_per_mb = 4;                               // luminance blocks only

        }

    }

    mv_block->coded_block_pattern = cbp;

    if (cbp == 0)

        mv_block->macroblock_type &= ~XVMC_MB_TYPE_PATTERN;



    for (i = 0; i < blocks_per_mb; i++) {

        if (s->block_last_index[i] >= 0) {

            // I do not have unsigned_intra MOCO to test, hope it is OK.

            if (s->mb_intra && (render->idct || !render->unsigned_intra))

                *s->pblocks[i][0] -= 1 << 10;

            if (!render->idct) {

                s->idsp.idct(*s->pblocks[i]);

                /* It is unclear if MC hardware requires pixel diff values to be

                 * in the range [-255;255]. TODO: Clipping if such hardware is

                 * ever found. As of now it would only be an unnecessary

                 * slowdown. */

            }

            // copy blocks only if the codec doesn't support pblocks reordering

            if (s->avctx->xvmc_acceleration == 1) {

                memcpy(&render->data_blocks[render->next_free_data_block_num*64],

                       s->pblocks[i], sizeof(*s->pblocks[i]));

            }

            render->next_free_data_block_num++;

        }

    }

    render->filled_mv_blocks_num++;



    assert(render->filled_mv_blocks_num     <= render->allocated_mv_blocks);

    assert(render->next_free_data_block_num <= render->allocated_data_blocks);

    /* The above conditions should not be able to fail as long as this function

     * is used and the following 'if ()' automatically calls a callback to free

     * blocks. */





    if (render->filled_mv_blocks_num == render->allocated_mv_blocks)

        ff_mpeg_draw_horiz_band(s, 0, 0);

}

static void frame_end(MpegEncContext *s)

{

    int i;



    if (s->unrestricted_mv &&

        s->current_picture.reference &&

        !s->intra_only) {

        const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(s->avctx->pix_fmt);

        int hshift = desc->log2_chroma_w;

        int vshift = desc->log2_chroma_h;

        s->mpvencdsp.draw_edges(s->current_picture.f->data[0], s->linesize,

                                s->h_edge_pos, s->v_edge_pos,

                                EDGE_WIDTH, EDGE_WIDTH,

                                EDGE_TOP | EDGE_BOTTOM);

        s->mpvencdsp.draw_edges(s->current_picture.f->data[1], s->uvlinesize,

                                s->h_edge_pos >> hshift,

                                s->v_edge_pos >> vshift,

                                EDGE_WIDTH >> hshift,

                                EDGE_WIDTH >> vshift,

                                EDGE_TOP | EDGE_BOTTOM);

        s->mpvencdsp.draw_edges(s->current_picture.f->data[2], s->uvlinesize,

                                s->h_edge_pos >> hshift,

                                s->v_edge_pos >> vshift,

                                EDGE_WIDTH >> hshift,

                                EDGE_WIDTH >> vshift,

                                EDGE_TOP | EDGE_BOTTOM);

    }



    emms_c();



    s->last_pict_type                 = s->pict_type;

    s->last_lambda_for [s->pict_type] = s->current_picture_ptr->f->quality;

    if (s->pict_type!= AV_PICTURE_TYPE_B)

        s->last_non_b_pict_type = s->pict_type;



    if (s->encoding) {

        /* release non-reference frames */

        for (i = 0; i < MAX_PICTURE_COUNT; i++) {

            if (!s->picture[i].reference)

                ff_mpeg_unref_picture(s->avctx, &s->picture[i]);

        }

    }



    s->avctx->coded_frame = s->current_picture_ptr->f;



}

static int estimate_best_b_count(MpegEncContext *s)

{

    AVCodec *codec    = avcodec_find_encoder(s->avctx->codec_id);

    AVCodecContext *c = avcodec_alloc_context3(NULL);

    AVFrame input[FF_MAX_B_FRAMES + 2];

    const int scale = s->avctx->brd_scale;

    int i, j, out_size, p_lambda, b_lambda, lambda2;

    int64_t best_rd  = INT64_MAX;

    int best_b_count = -1;



    assert(scale >= 0 && scale <= 3);



    //emms_c();

    //s->next_picture_ptr->quality;

    p_lambda = s->last_lambda_for[AV_PICTURE_TYPE_P];

    //p_lambda * FFABS(s->avctx->b_quant_factor) + s->avctx->b_quant_offset;

    b_lambda = s->last_lambda_for[AV_PICTURE_TYPE_B];

    if (!b_lambda) // FIXME we should do this somewhere else

        b_lambda = p_lambda;

    lambda2  = (b_lambda * b_lambda + (1 << FF_LAMBDA_SHIFT) / 2) >>

               FF_LAMBDA_SHIFT;



    c->width        = s->width  >> scale;

    c->height       = s->height >> scale;

    c->flags        = CODEC_FLAG_QSCALE | CODEC_FLAG_PSNR |

                      CODEC_FLAG_INPUT_PRESERVED /*| CODEC_FLAG_EMU_EDGE*/;

    c->flags       |= s->avctx->flags & CODEC_FLAG_QPEL;

    c->mb_decision  = s->avctx->mb_decision;

    c->me_cmp       = s->avctx->me_cmp;

    c->mb_cmp       = s->avctx->mb_cmp;

    c->me_sub_cmp   = s->avctx->me_sub_cmp;

    c->pix_fmt      = AV_PIX_FMT_YUV420P;

    c->time_base    = s->avctx->time_base;

    c->max_b_frames = s->max_b_frames;



    if (avcodec_open2(c, codec, NULL) < 0)

        return -1;



    for (i = 0; i < s->max_b_frames + 2; i++) {

        int ysize = c->width * c->height;

        int csize = (c->width / 2) * (c->height / 2);

        Picture pre_input, *pre_input_ptr = i ? s->input_picture[i - 1] :

                                                s->next_picture_ptr;



        avcodec_get_frame_defaults(&input[i]);

        input[i].data[0]     = av_malloc(ysize + 2 * csize);

        input[i].data[1]     = input[i].data[0] + ysize;

        input[i].data[2]     = input[i].data[1] + csize;

        input[i].linesize[0] = c->width;

        input[i].linesize[1] =

        input[i].linesize[2] = c->width / 2;



        if (pre_input_ptr && (!i || s->input_picture[i - 1])) {

            pre_input = *pre_input_ptr;



            if (!pre_input.shared && i) {

                pre_input.f.data[0] += INPLACE_OFFSET;

                pre_input.f.data[1] += INPLACE_OFFSET;

                pre_input.f.data[2] += INPLACE_OFFSET;

            }



            s->dsp.shrink[scale](input[i].data[0], input[i].linesize[0],

                                 pre_input.f.data[0], pre_input.f.linesize[0],

                                 c->width,      c->height);

            s->dsp.shrink[scale](input[i].data[1], input[i].linesize[1],

                                 pre_input.f.data[1], pre_input.f.linesize[1],

                                 c->width >> 1, c->height >> 1);

            s->dsp.shrink[scale](input[i].data[2], input[i].linesize[2],

                                 pre_input.f.data[2], pre_input.f.linesize[2],

                                 c->width >> 1, c->height >> 1);

        }

    }



    for (j = 0; j < s->max_b_frames + 1; j++) {

        int64_t rd = 0;



        if (!s->input_picture[j])

            break;



        c->error[0] = c->error[1] = c->error[2] = 0;



        input[0].pict_type = AV_PICTURE_TYPE_I;

        input[0].quality   = 1 * FF_QP2LAMBDA;



        out_size = encode_frame(c, &input[0]);



        //rd += (out_size * lambda2) >> FF_LAMBDA_SHIFT;



        for (i = 0; i < s->max_b_frames + 1; i++) {

            int is_p = i % (j + 1) == j || i == s->max_b_frames;



            input[i + 1].pict_type = is_p ?

                                     AV_PICTURE_TYPE_P : AV_PICTURE_TYPE_B;

            input[i + 1].quality   = is_p ? p_lambda : b_lambda;



            out_size = encode_frame(c, &input[i + 1]);



            rd += (out_size * lambda2) >> (FF_LAMBDA_SHIFT - 3);

        }



        /* get the delayed frames */

        while (out_size) {

            out_size = encode_frame(c, NULL);

            rd += (out_size * lambda2) >> (FF_LAMBDA_SHIFT - 3);

        }



        rd += c->error[0] + c->error[1] + c->error[2];



        if (rd < best_rd) {

            best_rd = rd;

            best_b_count = j;

        }

    }



    avcodec_close(c);

    av_freep(&c);



    for (i = 0; i < s->max_b_frames + 2; i++) {

        av_freep(&input[i].data[0]);

    }



    return best_b_count;

}

int qemu_get_buffer(QEMUFile *f, uint8_t *buf, int size1)

{

    int size, l;



    if (f->is_write) {

        abort();

    }



    size = size1;

    while (size > 0) {

        l = f->buf_size - f->buf_index;

        if (l == 0) {

            qemu_fill_buffer(f);

            l = f->buf_size - f->buf_index;

            if (l == 0) {

                break;

            }

        }

        if (l > size) {

            l = size;

        }

        memcpy(buf, f->buf + f->buf_index, l);

        f->buf_index += l;

        buf += l;

        size -= l;

    }

    return size1 - size;

}

int qemu_get_buffer(QEMUFile *f, uint8_t *buf, int size)

{

    int pending = size;

    int done = 0;



    while (pending > 0) {

        int res;



        res = qemu_peek_buffer(f, buf, pending, 0);

        if (res == 0) {

            return done;

        }

        qemu_file_skip(f, res);

        buf += res;

        pending -= res;

        done += res;

    }

    return done;

}

int qemu_get_byte(QEMUFile *f)

{

    if (f->is_write)

        abort();



    if (f->buf_index >= f->buf_size) {

        qemu_fill_buffer(f);

        if (f->buf_index >= f->buf_size)

            return 0;

    }

    return f->buf[f->buf_index++];

}

void qemu_put_buffer(QEMUFile *f, const uint8_t *buf, int size)

{

    int l;

    while (size > 0) {

        l = IO_BUF_SIZE - f->buf_index;

        if (l > size)

            l = size;

        memcpy(f->buf + f->buf_index, buf, l);

        f->buf_index += l;

        buf += l;

        size -= l;

        if (f->buf_index >= IO_BUF_SIZE)

            qemu_fflush(f);

    }

}

