static int sdp_parse_fmtp_config_h264(AVStream * stream,

                                      PayloadContext * h264_data,

                                      char *attr, char *value)

{

    AVCodecContext *codec = stream->codec;

    assert(codec->codec_id == CODEC_ID_H264);

    assert(h264_data != NULL);



    if (!strcmp(attr, "packetization-mode")) {

        av_log(codec, AV_LOG_DEBUG, "RTP Packetization Mode: %d\n", atoi(value));

        h264_data->packetization_mode = atoi(value);

        /*

           Packetization Mode:

           0 or not present: Single NAL mode (Only nals from 1-23 are allowed)

           1: Non-interleaved Mode: 1-23, 24 (STAP-A), 28 (FU-A) are allowed.

           2: Interleaved Mode: 25 (STAP-B), 26 (MTAP16), 27 (MTAP24), 28 (FU-A), and 29 (FU-B) are allowed.

         */

        if (h264_data->packetization_mode > 1)

            av_log(codec, AV_LOG_ERROR,

                   "Interleaved RTP mode is not supported yet.");

    } else if (!strcmp(attr, "profile-level-id")) {

        if (strlen(value) == 6) {

            char buffer[3];

            // 6 characters=3 bytes, in hex.

            uint8_t profile_idc;

            uint8_t profile_iop;

            uint8_t level_idc;



            buffer[0] = value[0]; buffer[1] = value[1]; buffer[2] = '\0';

            profile_idc = strtol(buffer, NULL, 16);

            buffer[0] = value[2]; buffer[1] = value[3];

            profile_iop = strtol(buffer, NULL, 16);

            buffer[0] = value[4]; buffer[1] = value[5];

            level_idc = strtol(buffer, NULL, 16);



            // set the parameters...

            av_log(codec, AV_LOG_DEBUG,

                   "RTP Profile IDC: %x Profile IOP: %x Level: %x\n",

                   profile_idc, profile_iop, level_idc);

            h264_data->profile_idc = profile_idc;

            h264_data->profile_iop = profile_iop;

            h264_data->level_idc = level_idc;

        }

    } else  if (!strcmp(attr, "sprop-parameter-sets")) {

        uint8_t start_sequence[]= { 0, 0, 1 };

        codec->extradata_size= 0;

        codec->extradata= NULL;



        while (*value) {

            char base64packet[1024];

            uint8_t decoded_packet[1024];

            uint32_t packet_size;

            char *dst = base64packet;



            while (*value && *value != ','

                   && (dst - base64packet) < sizeof(base64packet) - 1) {

                *dst++ = *value++;

            }

            *dst++ = '\0';



            if (*value == ',')

                value++;



            packet_size= av_base64_decode(decoded_packet, base64packet, sizeof(decoded_packet));

            if (packet_size) {

                uint8_t *dest = av_malloc(packet_size + sizeof(start_sequence) +

                                         codec->extradata_size +

                                         FF_INPUT_BUFFER_PADDING_SIZE);

                if(dest)

                {

                    if(codec->extradata_size)

                    {

                        // av_realloc?

                        memcpy(dest, codec->extradata, codec->extradata_size);

                        av_free(codec->extradata);

                    }



                    memcpy(dest+codec->extradata_size, start_sequence, sizeof(start_sequence));

                    memcpy(dest+codec->extradata_size+sizeof(start_sequence), decoded_packet, packet_size);

                    memset(dest+codec->extradata_size+sizeof(start_sequence)+

                           packet_size, 0, FF_INPUT_BUFFER_PADDING_SIZE);



                    codec->extradata= dest;

                    codec->extradata_size+= sizeof(start_sequence)+packet_size;

                } else {

                    av_log(codec, AV_LOG_ERROR, "Unable to allocate memory for extradata!");

                    return AVERROR(ENOMEM);

                }

            }

        }

        av_log(codec, AV_LOG_DEBUG, "Extradata set to %p (size: %d)!", codec->extradata, codec->extradata_size);

    }

    return 0;

}

static int sdp_parse_fmtp_config_h264(AVFormatContext *s,

                                      AVStream *stream,

                                      PayloadContext *h264_data,

                                      const char *attr, const char *value)

{

    AVCodecParameters *par = stream->codecpar;



    if (!strcmp(attr, "packetization-mode")) {

        av_log(s, AV_LOG_DEBUG, "RTP Packetization Mode: %d\n", atoi(value));

        h264_data->packetization_mode = atoi(value);

        /*

         * Packetization Mode:

         * 0 or not present: Single NAL mode (Only nals from 1-23 are allowed)

         * 1: Non-interleaved Mode: 1-23, 24 (STAP-A), 28 (FU-A) are allowed.

         * 2: Interleaved Mode: 25 (STAP-B), 26 (MTAP16), 27 (MTAP24), 28 (FU-A),

         *                      and 29 (FU-B) are allowed.

         */

        if (h264_data->packetization_mode > 1)

            av_log(s, AV_LOG_ERROR,

                   "Interleaved RTP mode is not supported yet.\n");

    } else if (!strcmp(attr, "profile-level-id")) {

        if (strlen(value) == 6)

            parse_profile_level_id(s, h264_data, value);

    } else if (!strcmp(attr, "sprop-parameter-sets")) {

        int ret;

        if (value[strlen(value) - 1] == ',') {

            av_log(s, AV_LOG_WARNING, "Missing PPS in sprop-parameter-sets, ignoring\n");

            return 0;

        }

        par->extradata_size = 0;

        av_freep(&par->extradata);

        ret = ff_h264_parse_sprop_parameter_sets(s, &par->extradata,

                                                 &par->extradata_size, value);

        av_log(s, AV_LOG_DEBUG, "Extradata set to %p (size: %d)\n",

               par->extradata, par->extradata_size);

        return ret;

    }

    return 0;

}

static int h264_handle_packet(AVFormatContext *ctx,
                              PayloadContext *data,
                              AVStream *st,
                              AVPacket * pkt,
                              uint32_t * timestamp,
                              const uint8_t * buf,
                              int len, int flags)
{
    uint8_t nal = buf[0];
    uint8_t type = (nal & 0x1f);
    int result= 0;
    uint8_t start_sequence[]= {0, 0, 1};
#ifdef DEBUG
    assert(data);
    assert(data->cookie == MAGIC_COOKIE);
#endif
    assert(buf);
    if (type >= 1 && type <= 23)
        type = 1;              // simplify the case. (these are all the nal types used internally by the h264 codec)
    switch (type) {
    case 0:                    // undefined;
        result= -1;
        break;
    case 1:
        av_new_packet(pkt, len+sizeof(start_sequence));
        memcpy(pkt->data, start_sequence, sizeof(start_sequence));
        memcpy(pkt->data+sizeof(start_sequence), buf, len);
#ifdef DEBUG
        data->packet_types_received[nal & 0x1f]++;
#endif
        break;
    case 24:                   // STAP-A (one packet, multiple nals)
        // consume the STAP-A NAL
        buf++;
        len--;
        // first we are going to figure out the total size....
        {
            int pass= 0;
            int total_length= 0;
            uint8_t *dst= NULL;
            for(pass= 0; pass<2; pass++) {
                const uint8_t *src= buf;
                int src_len= len;
                do {
                    uint16_t nal_size = AV_RB16(src); // this going to be a problem if unaligned (can it be?)
                    // consume the length of the aggregate...
                    src += 2;
                    src_len -= 2;
                    if (nal_size <= src_len) {
                        if(pass==0) {
                            // counting...
                            total_length+= sizeof(start_sequence)+nal_size;
                        } else {
                            // copying
                            assert(dst);
                            memcpy(dst, start_sequence, sizeof(start_sequence));
                            dst+= sizeof(start_sequence);
                            memcpy(dst, src, nal_size);
#ifdef DEBUG
                            data->packet_types_received[*src & 0x1f]++;
#endif
                            dst+= nal_size;
                        }
                    } else {
                        av_log(ctx, AV_LOG_ERROR,
                               "nal size exceeds length: %d %d\n", nal_size, src_len);
                    }
                    // eat what we handled...
                    src += nal_size;
                    src_len -= nal_size;
                    if (src_len < 0)
                        av_log(ctx, AV_LOG_ERROR,
                               "Consumed more bytes than we got! (%d)\n", src_len);
                } while (src_len > 2);      // because there could be rtp padding..
                if(pass==0) {
                    // now we know the total size of the packet (with the start sequences added)
                    av_new_packet(pkt, total_length);
                    dst= pkt->data;
                } else {
                    assert(dst-pkt->data==total_length);
                }
            }
        }
        break;
    case 25:                   // STAP-B
    case 26:                   // MTAP-16
    case 27:                   // MTAP-24
    case 29:                   // FU-B
        av_log(ctx, AV_LOG_ERROR,
               "Unhandled type (%d) (See RFC for implementation details\n",
               type);
        result= -1;
        break;
    case 28:                   // FU-A (fragmented nal)
        buf++;
        len--;                  // skip the fu_indicator
        {
            // these are the same as above, we just redo them here for clarity...
            uint8_t fu_indicator = nal;
            uint8_t fu_header = *buf;   // read the fu_header.
            uint8_t start_bit = fu_header >> 7;
//            uint8_t end_bit = (fu_header & 0x40) >> 6;
            uint8_t nal_type = (fu_header & 0x1f);
            uint8_t reconstructed_nal;
            // reconstruct this packet's true nal; only the data follows..
            reconstructed_nal = fu_indicator & (0xe0);  // the original nal forbidden bit and NRI are stored in this packet's nal;
            reconstructed_nal |= nal_type;
            // skip the fu_header...
            buf++;
            len--;
#ifdef DEBUG
            if (start_bit)
                data->packet_types_received[nal_type]++;
#endif
            if(start_bit) {
                // copy in the start sequence, and the reconstructed nal....
                av_new_packet(pkt, sizeof(start_sequence)+sizeof(nal)+len);
                memcpy(pkt->data, start_sequence, sizeof(start_sequence));
                pkt->data[sizeof(start_sequence)]= reconstructed_nal;
                memcpy(pkt->data+sizeof(start_sequence)+sizeof(nal), buf, len);
            } else {
                av_new_packet(pkt, len);
                memcpy(pkt->data, buf, len);
            }
        }
        break;
    case 30:                   // undefined
    case 31:                   // undefined
    default:
        av_log(ctx, AV_LOG_ERROR, "Undefined type (%d)", type);
        result= -1;
        break;
    }
    return result;
}

static int h264_handle_packet(AVFormatContext *ctx,

                              PayloadContext *data,

                              AVStream *st,

                              AVPacket * pkt,

                              uint32_t * timestamp,

                              const uint8_t * buf,

                              int len, int flags)

{

    uint8_t nal = buf[0];

    uint8_t type = (nal & 0x1f);

    int result= 0;

    uint8_t start_sequence[] = { 0, 0, 0, 1 };



#ifdef DEBUG

    assert(data);

    assert(data->cookie == MAGIC_COOKIE);

#endif

    assert(buf);



    if (type >= 1 && type <= 23)

        type = 1;              // simplify the case. (these are all the nal types used internally by the h264 codec)

    switch (type) {

    case 0:                    // undefined, but pass them through

    case 1:

        av_new_packet(pkt, len+sizeof(start_sequence));

        memcpy(pkt->data, start_sequence, sizeof(start_sequence));

        memcpy(pkt->data+sizeof(start_sequence), buf, len);

#ifdef DEBUG

        data->packet_types_received[nal & 0x1f]++;

#endif

        break;



    case 24:                   // STAP-A (one packet, multiple nals)

        // consume the STAP-A NAL

        buf++;

        len--;

        // first we are going to figure out the total size....

        {

            int pass= 0;

            int total_length= 0;

            uint8_t *dst= NULL;



            for(pass= 0; pass<2; pass++) {

                const uint8_t *src= buf;

                int src_len= len;



                do {

                    uint16_t nal_size = AV_RB16(src); // this going to be a problem if unaligned (can it be?)



                    // consume the length of the aggregate...

                    src += 2;

                    src_len -= 2;



                    if (nal_size <= src_len) {

                        if(pass==0) {

                            // counting...

                            total_length+= sizeof(start_sequence)+nal_size;

                        } else {

                            // copying

                            assert(dst);

                            memcpy(dst, start_sequence, sizeof(start_sequence));

                            dst+= sizeof(start_sequence);

                            memcpy(dst, src, nal_size);

#ifdef DEBUG

                            data->packet_types_received[*src & 0x1f]++;

#endif

                            dst+= nal_size;

                        }

                    } else {

                        av_log(ctx, AV_LOG_ERROR,

                               "nal size exceeds length: %d %d\n", nal_size, src_len);

                    }



                    // eat what we handled...

                    src += nal_size;

                    src_len -= nal_size;



                    if (src_len < 0)

                        av_log(ctx, AV_LOG_ERROR,

                               "Consumed more bytes than we got! (%d)\n", src_len);

                } while (src_len > 2);      // because there could be rtp padding..



                if(pass==0) {

                    // now we know the total size of the packet (with the start sequences added)

                    av_new_packet(pkt, total_length);

                    dst= pkt->data;

                } else {

                    assert(dst-pkt->data==total_length);

                }

            }

        }

        break;



    case 25:                   // STAP-B

    case 26:                   // MTAP-16

    case 27:                   // MTAP-24

    case 29:                   // FU-B

        av_log(ctx, AV_LOG_ERROR,

               "Unhandled type (%d) (See RFC for implementation details\n",

               type);

        result= -1;

        break;



    case 28:                   // FU-A (fragmented nal)

        buf++;

        len--;                  // skip the fu_indicator

        {

            // these are the same as above, we just redo them here for clarity...

            uint8_t fu_indicator = nal;

            uint8_t fu_header = *buf;   // read the fu_header.

            uint8_t start_bit = fu_header >> 7;

//            uint8_t end_bit = (fu_header & 0x40) >> 6;

            uint8_t nal_type = (fu_header & 0x1f);

            uint8_t reconstructed_nal;



            // reconstruct this packet's true nal; only the data follows..

            reconstructed_nal = fu_indicator & (0xe0);  // the original nal forbidden bit and NRI are stored in this packet's nal;

            reconstructed_nal |= nal_type;



            // skip the fu_header...

            buf++;

            len--;



#ifdef DEBUG

            if (start_bit)

                data->packet_types_received[nal_type]++;

#endif

            if(start_bit) {

                // copy in the start sequence, and the reconstructed nal....

                av_new_packet(pkt, sizeof(start_sequence)+sizeof(nal)+len);

                memcpy(pkt->data, start_sequence, sizeof(start_sequence));

                pkt->data[sizeof(start_sequence)]= reconstructed_nal;

                memcpy(pkt->data+sizeof(start_sequence)+sizeof(nal), buf, len);

            } else {

                av_new_packet(pkt, len);

                memcpy(pkt->data, buf, len);

            }

        }

        break;



    case 30:                   // undefined

    case 31:                   // undefined

    default:

        av_log(ctx, AV_LOG_ERROR, "Undefined type (%d)", type);

        result= -1;

        break;

    }



    pkt->stream_index = st->index;



    return result;

}

static int qcow2_create2(const char *filename, int64_t total_size,

                         const char *backing_file, const char *backing_format,

                         int flags, size_t cluster_size, int prealloc,

                         QEMUOptionParameter *options, int version,

                         Error **errp)

{

    /* Calculate cluster_bits */

    int cluster_bits;

    cluster_bits = ffs(cluster_size) - 1;

    if (cluster_bits < MIN_CLUSTER_BITS || cluster_bits > MAX_CLUSTER_BITS ||

        (1 << cluster_bits) != cluster_size)

    {

        error_setg(errp, "Cluster size must be a power of two between %d and "

                   "%dk", 1 << MIN_CLUSTER_BITS, 1 << (MAX_CLUSTER_BITS - 10));

        return -EINVAL;

    }



    /*

     * Open the image file and write a minimal qcow2 header.

     *

     * We keep things simple and start with a zero-sized image. We also

     * do without refcount blocks or a L1 table for now. We'll fix the

     * inconsistency later.

     *

     * We do need a refcount table because growing the refcount table means

     * allocating two new refcount blocks - the seconds of which would be at

     * 2 GB for 64k clusters, and we don't want to have a 2 GB initial file

     * size for any qcow2 image.

     */

    BlockDriverState* bs;

    QCowHeader *header;

    uint8_t* refcount_table;

    Error *local_err = NULL;

    int ret;



    ret = bdrv_create_file(filename, options, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        return ret;

    }



    bs = NULL;

    ret = bdrv_open(&bs, filename, NULL, NULL, BDRV_O_RDWR | BDRV_O_PROTOCOL,

                    NULL, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        return ret;

    }



    /* Write the header */

    QEMU_BUILD_BUG_ON((1 << MIN_CLUSTER_BITS) < sizeof(*header));

    header = g_malloc0(cluster_size);

    *header = (QCowHeader) {

        .magic                      = cpu_to_be32(QCOW_MAGIC),

        .version                    = cpu_to_be32(version),

        .cluster_bits               = cpu_to_be32(cluster_bits),

        .size                       = cpu_to_be64(0),

        .l1_table_offset            = cpu_to_be64(0),

        .l1_size                    = cpu_to_be32(0),

        .refcount_table_offset      = cpu_to_be64(cluster_size),

        .refcount_table_clusters    = cpu_to_be32(1),

        .refcount_order             = cpu_to_be32(3 + REFCOUNT_SHIFT),

        .header_length              = cpu_to_be32(sizeof(*header)),

    };



    if (flags & BLOCK_FLAG_ENCRYPT) {

        header->crypt_method = cpu_to_be32(QCOW_CRYPT_AES);

    } else {

        header->crypt_method = cpu_to_be32(QCOW_CRYPT_NONE);

    }



    if (flags & BLOCK_FLAG_LAZY_REFCOUNTS) {

        header->compatible_features |=

            cpu_to_be64(QCOW2_COMPAT_LAZY_REFCOUNTS);

    }



    ret = bdrv_pwrite(bs, 0, header, cluster_size);

    g_free(header);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not write qcow2 header");

        goto out;

    }



    /* Write an empty refcount table */

    refcount_table = g_malloc0(cluster_size);

    ret = bdrv_pwrite(bs, cluster_size, refcount_table, cluster_size);

    g_free(refcount_table);



    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not write refcount table");

        goto out;

    }



    bdrv_unref(bs);

    bs = NULL;



    /*

     * And now open the image and make it consistent first (i.e. increase the

     * refcount of the cluster that is occupied by the header and the refcount

     * table)

     */

    BlockDriver* drv = bdrv_find_format("qcow2");

    assert(drv != NULL);

    ret = bdrv_open(&bs, filename, NULL, NULL,

        BDRV_O_RDWR | BDRV_O_CACHE_WB | BDRV_O_NO_FLUSH, drv, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto out;

    }



    ret = qcow2_alloc_clusters(bs, 2 * cluster_size);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not allocate clusters for qcow2 "

                         "header and refcount table");

        goto out;



    } else if (ret != 0) {

        error_report("Huh, first cluster in empty image is already in use?");

        abort();

    }



    /* Okay, now that we have a valid image, let's give it the right size */

    ret = bdrv_truncate(bs, total_size * BDRV_SECTOR_SIZE);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not resize image");

        goto out;

    }



    /* Want a backing file? There you go.*/

    if (backing_file) {

        ret = bdrv_change_backing_file(bs, backing_file, backing_format);

        if (ret < 0) {

            error_setg_errno(errp, -ret, "Could not assign backing file '%s' "

                             "with format '%s'", backing_file, backing_format);

            goto out;

        }

    }



    /* And if we're supposed to preallocate metadata, do that now */

    if (prealloc) {

        BDRVQcowState *s = bs->opaque;

        qemu_co_mutex_lock(&s->lock);

        ret = preallocate(bs);

        qemu_co_mutex_unlock(&s->lock);

        if (ret < 0) {

            error_setg_errno(errp, -ret, "Could not preallocate metadata");

            goto out;

        }

    }



    bdrv_unref(bs);

    bs = NULL;



    /* Reopen the image without BDRV_O_NO_FLUSH to flush it before returning */

    ret = bdrv_open(&bs, filename, NULL, NULL,

                    BDRV_O_RDWR | BDRV_O_CACHE_WB | BDRV_O_NO_BACKING,

                    drv, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        goto out;

    }



    ret = 0;

out:

    if (bs) {

        bdrv_unref(bs);

    }

    return ret;

}

