dma_write(void *opaque, target_phys_addr_t addr,

	  uint64_t val64, unsigned int size)

{

        struct fs_dma_ctrl *ctrl = opaque;

	uint32_t value = val64;

	int c;



	if (size != 4) {

		dma_winvalid(opaque, addr, value);

	}



        /* Make addr relative to this channel and bounded to nr regs.  */

	c = fs_channel(addr);

        addr &= 0xff;

        addr >>= 2;

        switch (addr)

	{

		case RW_DATA:

			ctrl->channels[c].regs[addr] = value;

			break;



		case RW_CFG:

			ctrl->channels[c].regs[addr] = value;

			dma_update_state(ctrl, c);

			break;

		case RW_CMD:

			/* continue.  */

			if (value & ~1)

				printf("Invalid store to ch=%d RW_CMD %x\n",

				       c, value);

			ctrl->channels[c].regs[addr] = value;

			channel_continue(ctrl, c);

			break;



		case RW_SAVED_DATA:

		case RW_SAVED_DATA_BUF:

		case RW_GROUP:

		case RW_GROUP_DOWN:

			ctrl->channels[c].regs[addr] = value;

			break;



		case RW_ACK_INTR:

		case RW_INTR_MASK:

			ctrl->channels[c].regs[addr] = value;

			channel_update_irq(ctrl, c);

			if (addr == RW_ACK_INTR)

				ctrl->channels[c].regs[RW_ACK_INTR] = 0;

			break;



		case RW_STREAM_CMD:

			if (value & ~1023)

				printf("Invalid store to ch=%d "

				       "RW_STREAMCMD %x\n",

				       c, value);

			ctrl->channels[c].regs[addr] = value;

			D(printf("stream_cmd ch=%d\n", c));

			channel_stream_cmd(ctrl, c, value);

			break;



	        default:

			D(printf ("%s c=%d " TARGET_FMT_plx "\n",

				__func__, c, addr));

			break;

        }

}

static uint64_t pxa2xx_pm_read(void *opaque, hwaddr addr,

                               unsigned size)

{

    PXA2xxState *s = (PXA2xxState *) opaque;



    switch (addr) {

    case PMCR ... PCMD31:

        if (addr & 3)

            goto fail;



        return s->pm_regs[addr >> 2];

    default:

    fail:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

    return 0;

}

pic_read(void *opaque, target_phys_addr_t addr, unsigned int size)

{

    struct etrax_pic *fs = opaque;

    uint32_t rval;



    rval = fs->regs[addr >> 2];

    D(printf("%s %x=%x\n", __func__, addr, rval));

    return rval;

}

static inline uint16_t get_hwc_color(SM501State *state, int crt, int index)

{

    uint32_t color_reg = 0;

    uint16_t color_565 = 0;



    if (index == 0) {

        return 0;

    }



    switch (index) {

    case 1:

    case 2:

        color_reg = crt ? state->dc_crt_hwc_color_1_2

                        : state->dc_panel_hwc_color_1_2;

        break;

    case 3:

        color_reg = crt ? state->dc_crt_hwc_color_3

                        : state->dc_panel_hwc_color_3;

        break;

    default:

        printf("invalid hw cursor color.\n");

        abort();

    }



    switch (index) {

    case 1:

    case 3:

        color_565 = (uint16_t)(color_reg & 0xFFFF);

        break;

    case 2:

        color_565 = (uint16_t)((color_reg >> 16) & 0xFFFF);

        break;

    }

    return color_565;

}

static void pxa2xx_descriptor_load(PXA2xxLCDState *s)

{

    PXAFrameDescriptor desc;

    target_phys_addr_t descptr;

    int i;



    for (i = 0; i < PXA_LCDDMA_CHANS; i ++) {

        s->dma_ch[i].source = 0;



        if (!s->dma_ch[i].up)

            continue;



        if (s->dma_ch[i].branch & FBR_BRA) {

            descptr = s->dma_ch[i].branch & FBR_SRCADDR;

            if (s->dma_ch[i].branch & FBR_BINT)

                pxa2xx_dma_bs_set(s, i);

            s->dma_ch[i].branch &= ~FBR_BRA;

        } else

            descptr = s->dma_ch[i].descriptor;



        if (!(descptr >= PXA2XX_SDRAM_BASE && descptr +

                    sizeof(desc) <= PXA2XX_SDRAM_BASE + ram_size))

            continue;



        cpu_physical_memory_read(descptr, (void *)&desc, sizeof(desc));

        s->dma_ch[i].descriptor = tswap32(desc.fdaddr);

        s->dma_ch[i].source = tswap32(desc.fsaddr);

        s->dma_ch[i].id = tswap32(desc.fidr);

        s->dma_ch[i].command = tswap32(desc.ldcmd);

    }

}

static void pxa2xx_update_display(void *opaque)

{

    struct pxa2xx_lcdc_s *s = (struct pxa2xx_lcdc_s *) opaque;

    target_phys_addr_t fbptr;

    int miny, maxy;

    int ch;

    if (!(s->control[0] & LCCR0_ENB))

        return;



    pxa2xx_descriptor_load(s);



    pxa2xx_lcdc_resize(s);

    miny = s->yres;

    maxy = 0;

    s->transp = s->dma_ch[2].up || s->dma_ch[3].up;

    /* Note: With overlay planes the order depends on LCCR0 bit 25.  */

    for (ch = 0; ch < PXA_LCDDMA_CHANS; ch ++)

        if (s->dma_ch[ch].up) {

            if (!s->dma_ch[ch].source) {

                pxa2xx_dma_ber_set(s, ch);

                continue;

            }

            fbptr = s->dma_ch[ch].source;

            if (!(fbptr >= PXA2XX_SDRAM_BASE &&

                    fbptr <= PXA2XX_SDRAM_BASE + phys_ram_size)) {

                pxa2xx_dma_ber_set(s, ch);

                continue;

            }



            if (s->dma_ch[ch].command & LDCMD_PAL) {

                cpu_physical_memory_read(fbptr, s->dma_ch[ch].pbuffer,

                    MAX(LDCMD_LENGTH(s->dma_ch[ch].command),

                        sizeof(s->dma_ch[ch].pbuffer)));

                pxa2xx_palette_parse(s, ch, s->bpp);

            } else {

                /* Do we need to reparse palette */

                if (LCCR4_PALFOR(s->control[4]) != s->pal_for)

                    pxa2xx_palette_parse(s, ch, s->bpp);



                /* ACK frame start */

                pxa2xx_dma_sof_set(s, ch);



                s->dma_ch[ch].redraw(s, fbptr, &miny, &maxy);

                s->invalidated = 0;



                /* ACK frame completed */

                pxa2xx_dma_eof_set(s, ch);

            }

        }



    if (s->control[0] & LCCR0_DIS) {

        /* ACK last frame completed */

        s->control[0] &= ~LCCR0_ENB;

        s->status[0] |= LCSR0_LDD;

    }



    if (miny >= 0) {

        if (s->orientation)

            dpy_update(s->ds, miny, 0, maxy, s->xres);

        else

            dpy_update(s->ds, 0, miny, s->xres, maxy);

    }

    pxa2xx_lcdc_int_update(s);



    qemu_irq_raise(s->vsync_cb);

}

void omap_inth_reset(struct omap_intr_handler_s *s)

{

    int i;



    for (i = 0; i < s->nbanks; ++i){

        s->bank[i].irqs = 0x00000000;

        s->bank[i].mask = 0xffffffff;

        s->bank[i].sens_edge = 0x00000000;

        s->bank[i].fiq = 0x00000000;

        s->bank[i].inputs = 0x00000000;

        s->bank[i].swi = 0x00000000;

        memset(s->bank[i].priority, 0, sizeof(s->bank[i].priority));



        if (s->level_only)

            s->bank[i].sens_edge = 0xffffffff;

    }



    s->new_agr[0] = ~0;

    s->new_agr[1] = ~0;

    s->sir_intr[0] = 0;

    s->sir_intr[1] = 0;

    s->autoidle = 0;

    s->mask = ~0;



    qemu_set_irq(s->parent_intr[0], 0);

    qemu_set_irq(s->parent_intr[1], 0);

}

static int qsv_get_buffer(AVCodecContext *s, AVFrame *frame, int flags)

{

    InputStream *ist = s->opaque;

    QSVContext  *qsv = ist->hwaccel_ctx;

    int i;



    for (i = 0; i < qsv->nb_surfaces; i++) {

        if (qsv->surface_used[i])

            continue;



        frame->buf[0] = av_buffer_create((uint8_t*)qsv->surface_ptrs[i], sizeof(*qsv->surface_ptrs[i]),

                                         buffer_release, &qsv->surface_used[i], 0);

        if (!frame->buf[0])

            return AVERROR(ENOMEM);

        frame->data[3]       = (uint8_t*)qsv->surface_ptrs[i];

        qsv->surface_used[i] = 1;

        return 0;

    }



    return AVERROR(ENOMEM);

}

static int spapr_fixup_cpu_smt_dt(void *fdt, int offset, PowerPCCPU *cpu,

                                  int smt_threads)

{

    int i, ret = 0;

    uint32_t servers_prop[smt_threads];

    uint32_t gservers_prop[smt_threads * 2];

    int index = ppc_get_vcpu_dt_id(cpu);



    if (cpu->cpu_version) {

        ret = fdt_setprop(fdt, offset, "cpu-version",

                          &cpu->cpu_version, sizeof(cpu->cpu_version));

        if (ret < 0) {

            return ret;

        }

    }



    /* Build interrupt servers and gservers properties */

    for (i = 0; i < smt_threads; i++) {

        servers_prop[i] = cpu_to_be32(index + i);

        /* Hack, direct the group queues back to cpu 0 */

        gservers_prop[i*2] = cpu_to_be32(index + i);

        gservers_prop[i*2 + 1] = 0;

    }

    ret = fdt_setprop(fdt, offset, "ibm,ppc-interrupt-server#s",

                      servers_prop, sizeof(servers_prop));

    if (ret < 0) {

        return ret;

    }

    ret = fdt_setprop(fdt, offset, "ibm,ppc-interrupt-gserver#s",

                      gservers_prop, sizeof(gservers_prop));



    return ret;

}

int bdrv_aio_multiwrite(BlockDriverState *bs, BlockRequest *reqs, int num_reqs)

{

    BlockDriverAIOCB *acb;

    MultiwriteCB *mcb;

    int i;



    if (num_reqs == 0) {

        return 0;

    }



    // Create MultiwriteCB structure

    mcb = qemu_mallocz(sizeof(*mcb) + num_reqs * sizeof(*mcb->callbacks));

    mcb->num_requests = 0;

    mcb->num_callbacks = num_reqs;



    for (i = 0; i < num_reqs; i++) {

        mcb->callbacks[i].cb = reqs[i].cb;

        mcb->callbacks[i].opaque = reqs[i].opaque;

    }



    // Check for mergable requests

    num_reqs = multiwrite_merge(bs, reqs, num_reqs, mcb);



    // Run the aio requests

    for (i = 0; i < num_reqs; i++) {

        acb = bdrv_aio_writev(bs, reqs[i].sector, reqs[i].qiov,

            reqs[i].nb_sectors, multiwrite_cb, mcb);



        if (acb == NULL) {

            // We can only fail the whole thing if no request has been

            // submitted yet. Otherwise we'll wait for the submitted AIOs to

            // complete and report the error in the callback.

            if (mcb->num_requests == 0) {

                reqs[i].error = -EIO;

                goto fail;

            } else {

                mcb->error = -EIO;

                break;

            }

        } else {

            mcb->num_requests++;

        }

    }



    return 0;



fail:

    free(mcb);

    return -1;

}

static int vhdx_parse_log(BlockDriverState *bs, BDRVVHDXState *s)

{

    int ret = 0;

    int i;

    VHDXHeader *hdr;



    hdr = s->headers[s->curr_header];



    /* either the log guid, or log length is zero,

     * then a replay log is present */

    for (i = 0; i < sizeof(hdr->log_guid.data4); i++) {

        ret |= hdr->log_guid.data4[i];

    }

    if (hdr->log_guid.data1 == 0 &&

        hdr->log_guid.data2 == 0 &&

        hdr->log_guid.data3 == 0 &&

        ret == 0) {

        goto exit;

    }



    /* per spec, only log version of 0 is supported */

    if (hdr->log_version != 0) {

        ret = -EINVAL;

        goto exit;

    }



    if (hdr->log_length == 0) {

        goto exit;

    }



    /* We currently do not support images with logs to replay */

    ret = -ENOTSUP;



exit:

    return ret;

}

int vhdx_log_write_and_flush(BlockDriverState *bs, BDRVVHDXState *s,

                             void *data, uint32_t length, uint64_t offset)

{

    int ret = 0;

    VHDXLogSequence logs = { .valid = true,

                             .count = 1,

                             .hdr = { 0 } };





    /* Make sure data written (new and/or changed blocks) is stable

     * on disk, before creating log entry */

    bdrv_flush(bs);

    ret = vhdx_log_write(bs, s, data, length, offset);

    if (ret < 0) {

        goto exit;

    }

    logs.log = s->log;



    /* Make sure log is stable on disk */

    bdrv_flush(bs);

    ret = vhdx_log_flush(bs, s, &logs);

    if (ret < 0) {

        goto exit;

    }



    s->log = logs.log;



exit:

    return ret;

}

void ppc_tlb_invalidate_all (CPUPPCState *env)

{

    switch (env->mmu_model) {

    case POWERPC_MMU_SOFT_6xx:

    case POWERPC_MMU_SOFT_74xx:

        ppc6xx_tlb_invalidate_all(env);

        break;

    case POWERPC_MMU_SOFT_4xx:

    case POWERPC_MMU_SOFT_4xx_Z:

        ppc4xx_tlb_invalidate_all(env);

        break;

    case POWERPC_MMU_REAL_4xx:

        cpu_abort(env, "No TLB for PowerPC 4xx in real mode\n");

        break;

    case POWERPC_MMU_BOOKE:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_BOOKE_FSL:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_601:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_32B:

#if defined(TARGET_PPC64)

    case POWERPC_MMU_64B:

    case POWERPC_MMU_64BRIDGE:

#endif /* defined(TARGET_PPC64) */

        tlb_flush(env, 1);

        break;

    default:

        /* XXX: TODO */

        cpu_abort(env, "Unknown MMU model %d\n", env->mmu_model);

        break;

    }

}

void ppc_tlb_invalidate_one (CPUPPCState *env, target_ulong addr)

{

#if !defined(FLUSH_ALL_TLBS)

    addr &= TARGET_PAGE_MASK;

    switch (env->mmu_model) {

    case POWERPC_MMU_SOFT_6xx:

    case POWERPC_MMU_SOFT_74xx:

        ppc6xx_tlb_invalidate_virt(env, addr, 0);

        if (env->id_tlbs == 1)

            ppc6xx_tlb_invalidate_virt(env, addr, 1);

        break;

    case POWERPC_MMU_SOFT_4xx:

    case POWERPC_MMU_SOFT_4xx_Z:

        ppc4xx_tlb_invalidate_virt(env, addr, env->spr[SPR_40x_PID]);

        break;

    case POWERPC_MMU_REAL_4xx:

        cpu_abort(env, "No TLB for PowerPC 4xx in real mode\n");

        break;

    case POWERPC_MMU_BOOKE:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_BOOKE_FSL:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_32B:

    case POWERPC_MMU_601:

        /* tlbie invalidate TLBs for all segments */

        addr &= ~((target_ulong)-1 << 28);

        /* XXX: this case should be optimized,

         * giving a mask to tlb_flush_page

         */

        tlb_flush_page(env, addr | (0x0 << 28));

        tlb_flush_page(env, addr | (0x1 << 28));

        tlb_flush_page(env, addr | (0x2 << 28));

        tlb_flush_page(env, addr | (0x3 << 28));

        tlb_flush_page(env, addr | (0x4 << 28));

        tlb_flush_page(env, addr | (0x5 << 28));

        tlb_flush_page(env, addr | (0x6 << 28));

        tlb_flush_page(env, addr | (0x7 << 28));

        tlb_flush_page(env, addr | (0x8 << 28));

        tlb_flush_page(env, addr | (0x9 << 28));

        tlb_flush_page(env, addr | (0xA << 28));

        tlb_flush_page(env, addr | (0xB << 28));

        tlb_flush_page(env, addr | (0xC << 28));

        tlb_flush_page(env, addr | (0xD << 28));

        tlb_flush_page(env, addr | (0xE << 28));

        tlb_flush_page(env, addr | (0xF << 28));

        break;

#if defined(TARGET_PPC64)

    case POWERPC_MMU_64B:

        /* tlbie invalidate TLBs for all segments */

        /* XXX: given the fact that there are too many segments to invalidate,

         *      and we still don't have a tlb_flush_mask(env, n, mask) in Qemu,

         *      we just invalidate all TLBs

         */

        tlb_flush(env, 1);

        break;

#endif /* defined(TARGET_PPC64) */

    default:

        /* XXX: TODO */

        cpu_abort(env, "Unknown MMU model\n");

        break;

    }

#else

    ppc_tlb_invalidate_all(env);

#endif

}

void dump_mmu(FILE *f, fprintf_function cpu_fprintf, CPUPPCState *env)

{

    switch (env->mmu_model) {

    case POWERPC_MMU_BOOKE:

        mmubooke_dump_mmu(f, cpu_fprintf, env);

        break;

    case POWERPC_MMU_BOOKE206:

        mmubooke206_dump_mmu(f, cpu_fprintf, env);

        break;

    case POWERPC_MMU_SOFT_6xx:

    case POWERPC_MMU_SOFT_74xx:

        mmu6xx_dump_mmu(f, cpu_fprintf, env);

        break;

#if defined(TARGET_PPC64)

    case POWERPC_MMU_64B:

    case POWERPC_MMU_2_03:

    case POWERPC_MMU_2_06:


    case POWERPC_MMU_2_07:


        dump_slb(f, cpu_fprintf, env);

        break;

#endif

    default:

        qemu_log_mask(LOG_UNIMP, "%s: unimplemented\n", __func__);

    }

}

static void gen_tlbwe_40x(DisasContext *ctx)

{

#if defined(CONFIG_USER_ONLY)

    gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

#else

    if (unlikely(ctx->pr)) {

        gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

        return;

    }

    switch (rB(ctx->opcode)) {

    case 0:

        gen_helper_4xx_tlbwe_hi(cpu_env, cpu_gpr[rA(ctx->opcode)],

                                cpu_gpr[rS(ctx->opcode)]);

        break;

    case 1:

        gen_helper_4xx_tlbwe_lo(cpu_env, cpu_gpr[rA(ctx->opcode)],

                                cpu_gpr[rS(ctx->opcode)]);

        break;

    default:

        gen_inval_exception(ctx, POWERPC_EXCP_INVAL_INVAL);

        break;

    }

#endif

}

uint32_t HELPER(lpebr)(CPUS390XState *env, uint32_t f1, uint32_t f2)

{

    float32 v1;

    float32 v2 = env->fregs[f2].d;



    v1 = float32_abs(v2);

    env->fregs[f1].d = v1;

    return set_cc_nz_f32(v1);

}

uint32_t HELPER(lcdbr)(CPUS390XState *env, uint32_t f1, uint32_t f2)

{

    env->fregs[f1].d = float64_chs(env->fregs[f2].d);



    return set_cc_nz_f64(env->fregs[f1].d);

}

uint32_t HELPER(lcxbr)(CPUS390XState *env, uint32_t f1, uint32_t f2)

{

    CPU_QuadU x1, x2;



    x2.ll.upper = env->fregs[f2].ll;

    x2.ll.lower = env->fregs[f2 + 2].ll;

    x1.q = float128_chs(x2.q);

    env->fregs[f1].ll = x1.ll.upper;

    env->fregs[f1 + 2].ll = x1.ll.lower;

    return set_cc_nz_f128(x1.q);

}

