    rt->last_bytes_read = 0;

    rt->server_bw = 2500000;



    av_log(s, AV_LOG_DEBUG, "Proto = %s, path = %s, app = %s, fname = %s\n",

           proto, path, rt->app, rt->playpath);

    if (!rt->listen) {

        if ((ret = gen_connect(s, rt)) < 0)

            goto fail;

    } else {

        if (read_connect(s, s->priv_data) < 0)

            goto fail;

        rt->is_input = 1;

    }



    do {

        ret = get_packet(s, 1);

    } while (ret == EAGAIN);

    if (ret < 0)

        goto fail;



    if (rt->do_reconnect) {

        ffurl_close(rt->stream);

        rt->stream       = NULL;

        rt->do_reconnect = 0;

        rt->nb_invokes   = 0;

        memset(rt->prev_pkt, 0, sizeof(rt->prev_pkt));

        free_tracked_methods(rt);

        goto reconnect;

    }



    if (rt->is_input) {

        // generate FLV header for demuxer

        rt->flv_size = 13;

        rt->flv_data = av_realloc(rt->flv_data, rt->flv_size);

        rt->flv_off  = 0;

        memcpy(rt->flv_data, "FLV\1\5\0\0\0\011\0\0\0\0", rt->flv_size);

    } else {

        rt->flv_size = 0;

        rt->flv_data = NULL;

        rt->flv_off  = 0;

        rt->skip_bytes = 13;

    }



    s->max_packet_size = rt->stream->max_packet_size;

    s->is_streamed     = 1;

    return 0;



fail:

    av_dict_free(&opts);

    rtmp_close(s);

    return ret;

}

static int qemu_rdma_dest_init(RDMAContext *rdma, Error **errp)

{

    int ret = -EINVAL, idx;

    struct rdma_cm_id *listen_id;

    char ip[40] = "unknown";

    struct addrinfo *res;

    char port_str[16];



    for (idx = 0; idx < RDMA_WRID_MAX; idx++) {

        rdma->wr_data[idx].control_len = 0;

        rdma->wr_data[idx].control_curr = NULL;

    }



    if (rdma->host == NULL) {

        ERROR(errp, "RDMA host is not set!");

        rdma->error_state = -EINVAL;

        return -1;

    }

    /* create CM channel */

    rdma->channel = rdma_create_event_channel();

    if (!rdma->channel) {

        ERROR(errp, "could not create rdma event channel");

        rdma->error_state = -EINVAL;

        return -1;

    }



    /* create CM id */

    ret = rdma_create_id(rdma->channel, &listen_id, NULL, RDMA_PS_TCP);

    if (ret) {

        ERROR(errp, "could not create cm_id!");

        goto err_dest_init_create_listen_id;

    }



    snprintf(port_str, 16, "%d", rdma->port);

    port_str[15] = '\0';



    if (rdma->host && strcmp("", rdma->host)) {

        struct addrinfo *e;



        ret = getaddrinfo(rdma->host, port_str, NULL, &res);

        if (ret < 0) {

            ERROR(errp, "could not getaddrinfo address %s", rdma->host);

            goto err_dest_init_bind_addr;

        }



        for (e = res; e != NULL; e = e->ai_next) {

            inet_ntop(e->ai_family,

                &((struct sockaddr_in *) e->ai_addr)->sin_addr, ip, sizeof ip);

            DPRINTF("Trying %s => %s\n", rdma->host, ip);

            ret = rdma_bind_addr(listen_id, e->ai_addr);

            if (!ret) {

                goto listen;

            }

        }



        ERROR(errp, "Error: could not rdma_bind_addr!");

        goto err_dest_init_bind_addr;

    } else {

        ERROR(errp, "migration host and port not specified!");

        ret = -EINVAL;

        goto err_dest_init_bind_addr;

    }

listen:



    rdma->listen_id = listen_id;

    qemu_rdma_dump_gid("dest_init", listen_id);

    return 0;



err_dest_init_bind_addr:

    rdma_destroy_id(listen_id);

err_dest_init_create_listen_id:

    rdma_destroy_event_channel(rdma->channel);

    rdma->channel = NULL;

    rdma->error_state = ret;

    return ret;



}

static int qemu_rdma_resolve_host(RDMAContext *rdma, Error **errp)

{

    int ret;

    struct addrinfo *res;

    char port_str[16];

    struct rdma_cm_event *cm_event;

    char ip[40] = "unknown";

    struct addrinfo *e;



    if (rdma->host == NULL || !strcmp(rdma->host, "")) {

        ERROR(errp, "RDMA hostname has not been set");

        return -1;

    }



    /* create CM channel */

    rdma->channel = rdma_create_event_channel();

    if (!rdma->channel) {

        ERROR(errp, "could not create CM channel");

        return -1;

    }



    /* create CM id */

    ret = rdma_create_id(rdma->channel, &rdma->cm_id, NULL, RDMA_PS_TCP);

    if (ret) {

        ERROR(errp, "could not create channel id");

        goto err_resolve_create_id;

    }



    snprintf(port_str, 16, "%d", rdma->port);

    port_str[15] = '\0';



    ret = getaddrinfo(rdma->host, port_str, NULL, &res);

    if (ret < 0) {

        ERROR(errp, "could not getaddrinfo address %s", rdma->host);

        goto err_resolve_get_addr;

    }



    for (e = res; e != NULL; e = e->ai_next) {

        inet_ntop(e->ai_family,

            &((struct sockaddr_in *) e->ai_addr)->sin_addr, ip, sizeof ip);

        DPRINTF("Trying %s => %s\n", rdma->host, ip);



        /* resolve the first address */

        ret = rdma_resolve_addr(rdma->cm_id, NULL, e->ai_addr,

                RDMA_RESOLVE_TIMEOUT_MS);

        if (!ret) {

            goto route;

        }

    }



    ERROR(errp, "could not resolve address %s", rdma->host);

    goto err_resolve_get_addr;



route:

    qemu_rdma_dump_gid("source_resolve_addr", rdma->cm_id);



    ret = rdma_get_cm_event(rdma->channel, &cm_event);

    if (ret) {

        ERROR(errp, "could not perform event_addr_resolved");

        goto err_resolve_get_addr;

    }



    if (cm_event->event != RDMA_CM_EVENT_ADDR_RESOLVED) {

        ERROR(errp, "result not equal to event_addr_resolved %s",

                rdma_event_str(cm_event->event));

        perror("rdma_resolve_addr");

        goto err_resolve_get_addr;

    }

    rdma_ack_cm_event(cm_event);



    /* resolve route */

    ret = rdma_resolve_route(rdma->cm_id, RDMA_RESOLVE_TIMEOUT_MS);

    if (ret) {

        ERROR(errp, "could not resolve rdma route");

        goto err_resolve_get_addr;

    }



    ret = rdma_get_cm_event(rdma->channel, &cm_event);

    if (ret) {

        ERROR(errp, "could not perform event_route_resolved");

        goto err_resolve_get_addr;

    }

    if (cm_event->event != RDMA_CM_EVENT_ROUTE_RESOLVED) {

        ERROR(errp, "result not equal to event_route_resolved: %s",

                        rdma_event_str(cm_event->event));

        rdma_ack_cm_event(cm_event);

        goto err_resolve_get_addr;

    }

    rdma_ack_cm_event(cm_event);

    rdma->verbs = rdma->cm_id->verbs;

    qemu_rdma_dump_id("source_resolve_host", rdma->cm_id->verbs);

    qemu_rdma_dump_gid("source_resolve_host", rdma->cm_id);

    return 0;



err_resolve_get_addr:

    rdma_destroy_id(rdma->cm_id);

    rdma->cm_id = NULL;

err_resolve_create_id:

    rdma_destroy_event_channel(rdma->channel);

    rdma->channel = NULL;



    return -1;

}

static int qemu_rdma_source_init(RDMAContext *rdma, Error **errp, bool pin_all)

{

    int ret, idx;

    Error *local_err = NULL, **temp = &local_err;



    /*

     * Will be validated against destination's actual capabilities

     * after the connect() completes.

     */

    rdma->pin_all = pin_all;



    ret = qemu_rdma_resolve_host(rdma, temp);

    if (ret) {

        goto err_rdma_source_init;

    }



    ret = qemu_rdma_alloc_pd_cq(rdma);

    if (ret) {

        ERROR(temp, "rdma migration: error allocating pd and cq! Your mlock()"

                    " limits may be too low. Please check $ ulimit -a # and "

                    "search for 'ulimit -l' in the output");

        goto err_rdma_source_init;

    }



    ret = qemu_rdma_alloc_qp(rdma);

    if (ret) {

        ERROR(temp, "rdma migration: error allocating qp!");

        goto err_rdma_source_init;

    }



    ret = qemu_rdma_init_ram_blocks(rdma);

    if (ret) {

        ERROR(temp, "rdma migration: error initializing ram blocks!");

        goto err_rdma_source_init;

    }



    for (idx = 0; idx < RDMA_WRID_MAX; idx++) {

        ret = qemu_rdma_reg_control(rdma, idx);

        if (ret) {

            ERROR(temp, "rdma migration: error registering %d control!",

                                                            idx);

            goto err_rdma_source_init;

        }

    }



    return 0;



err_rdma_source_init:

    error_propagate(errp, local_err);

    qemu_rdma_cleanup(rdma);

    return -1;

}

static void qemu_rdma_cleanup(RDMAContext *rdma)

{

    struct rdma_cm_event *cm_event;

    int ret, idx;



    if (rdma->cm_id && rdma->connected) {

        if (rdma->error_state) {

            RDMAControlHeader head = { .len = 0,

                                       .type = RDMA_CONTROL_ERROR,

                                       .repeat = 1,

                                     };

            error_report("Early error. Sending error.");

            qemu_rdma_post_send_control(rdma, NULL, &head);

        }



        ret = rdma_disconnect(rdma->cm_id);

        if (!ret) {

            trace_qemu_rdma_cleanup_waiting_for_disconnect();

            ret = rdma_get_cm_event(rdma->channel, &cm_event);

            if (!ret) {

                rdma_ack_cm_event(cm_event);

            }

        }

        trace_qemu_rdma_cleanup_disconnect();

        rdma->connected = false;

    }



    g_free(rdma->block);

    rdma->block = NULL;



    for (idx = 0; idx < RDMA_WRID_MAX; idx++) {

        if (rdma->wr_data[idx].control_mr) {

            rdma->total_registrations--;

            ibv_dereg_mr(rdma->wr_data[idx].control_mr);

        }

        rdma->wr_data[idx].control_mr = NULL;

    }



    if (rdma->local_ram_blocks.block) {

        while (rdma->local_ram_blocks.nb_blocks) {

            rdma_delete_block(rdma, rdma->local_ram_blocks.block->offset);

        }

    }



    if (rdma->cq) {

        ibv_destroy_cq(rdma->cq);

        rdma->cq = NULL;

    }

    if (rdma->comp_channel) {

        ibv_destroy_comp_channel(rdma->comp_channel);

        rdma->comp_channel = NULL;

    }

    if (rdma->pd) {

        ibv_dealloc_pd(rdma->pd);

        rdma->pd = NULL;

    }

    if (rdma->listen_id) {

        rdma_destroy_id(rdma->listen_id);

        rdma->listen_id = NULL;

    }

    if (rdma->cm_id) {

        if (rdma->qp) {

            rdma_destroy_qp(rdma->cm_id);

            rdma->qp = NULL;

        }

        rdma_destroy_id(rdma->cm_id);

        rdma->cm_id = NULL;

    }

    if (rdma->channel) {

        rdma_destroy_event_channel(rdma->channel);

        rdma->channel = NULL;

    }

    g_free(rdma->host);

    rdma->host = NULL;

}

static inline void s_zero(int cur_diff, struct G722Band *band)

{

    int s_zero = 0;



    #define ACCUM(k, x, d) do { \

            int tmp = x; \

            band->zero_mem[k] = ((band->zero_mem[k] * 255) >> 8) + \

               d*((band->diff_mem[k]^cur_diff) < 0 ? -128 : 128); \

            band->diff_mem[k] = tmp; \

            s_zero += (tmp * band->zero_mem[k]) >> 15; \

        } while (0)

    if (cur_diff) {

        ACCUM(5, band->diff_mem[4], 1);

        ACCUM(4, band->diff_mem[3], 1);

        ACCUM(3, band->diff_mem[2], 1);

        ACCUM(2, band->diff_mem[1], 1);

        ACCUM(1, band->diff_mem[0], 1);

        ACCUM(0, cur_diff << 1, 1);

    } else {

        ACCUM(5, band->diff_mem[4], 0);

        ACCUM(4, band->diff_mem[3], 0);

        ACCUM(3, band->diff_mem[2], 0);

        ACCUM(2, band->diff_mem[1], 0);

        ACCUM(1, band->diff_mem[0], 0);

        ACCUM(0, cur_diff << 1, 0);

    }

    #undef ACCUM

    band->s_zero = s_zero;

}

int udp_output2(struct socket *so, struct mbuf *m,

                struct sockaddr_in *saddr, struct sockaddr_in *daddr,

                int iptos)

{

	register struct udpiphdr *ui;

	int error = 0;



	DEBUG_CALL("udp_output");

	DEBUG_ARG("so = %p", so);

	DEBUG_ARG("m = %p", m);

	DEBUG_ARG("saddr = %lx", (long)saddr->sin_addr.s_addr);

	DEBUG_ARG("daddr = %lx", (long)daddr->sin_addr.s_addr);



	/*

	 * Adjust for header

	 */

	m->m_data -= sizeof(struct udpiphdr);

	m->m_len += sizeof(struct udpiphdr);



	/*

	 * Fill in mbuf with extended UDP header

	 * and addresses and length put into network format.

	 */

	ui = mtod(m, struct udpiphdr *);

    memset(&ui->ui_i.ih_mbuf, 0 , sizeof(struct mbuf_ptr));

	ui->ui_x1 = 0;

	ui->ui_pr = IPPROTO_UDP;

	ui->ui_len = htons(m->m_len - sizeof(struct ip));

	/* XXXXX Check for from-one-location sockets, or from-any-location sockets */

        ui->ui_src = saddr->sin_addr;

	ui->ui_dst = daddr->sin_addr;

	ui->ui_sport = saddr->sin_port;

	ui->ui_dport = daddr->sin_port;

	ui->ui_ulen = ui->ui_len;



	/*

	 * Stuff checksum and output datagram.

	 */

	ui->ui_sum = 0;

	if ((ui->ui_sum = cksum(m, m->m_len)) == 0)

		ui->ui_sum = 0xffff;

	((struct ip *)ui)->ip_len = m->m_len;



	((struct ip *)ui)->ip_ttl = IPDEFTTL;

	((struct ip *)ui)->ip_tos = iptos;



	error = ip_output(so, m);



	return (error);

}

int AES_set_encrypt_key(const unsigned char *userKey, const int bits,

			AES_KEY *key) {



	u32 *rk;

   	int i = 0;

	u32 temp;



	if (!userKey || !key)

		return -1;

	if (bits != 128 && bits != 192 && bits != 256)

		return -2;



	rk = key->rd_key;



	if (bits==128)

		key->rounds = 10;

	else if (bits==192)

		key->rounds = 12;

	else

		key->rounds = 14;



	rk[0] = GETU32(userKey     );

	rk[1] = GETU32(userKey +  4);

	rk[2] = GETU32(userKey +  8);

	rk[3] = GETU32(userKey + 12);

	if (bits == 128) {

		while (1) {

			temp  = rk[3];

			rk[4] = rk[0] ^

                                (AES_Te4[(temp >> 16) & 0xff] & 0xff000000) ^

                                (AES_Te4[(temp >>  8) & 0xff] & 0x00ff0000) ^

                                (AES_Te4[(temp      ) & 0xff] & 0x0000ff00) ^

                                (AES_Te4[(temp >> 24)       ] & 0x000000ff) ^

				rcon[i];

			rk[5] = rk[1] ^ rk[4];

			rk[6] = rk[2] ^ rk[5];

			rk[7] = rk[3] ^ rk[6];

			if (++i == 10) {

				return 0;

			}

			rk += 4;

		}

	}

	rk[4] = GETU32(userKey + 16);

	rk[5] = GETU32(userKey + 20);

	if (bits == 192) {

		while (1) {

			temp = rk[ 5];

			rk[ 6] = rk[ 0] ^

                                (AES_Te4[(temp >> 16) & 0xff] & 0xff000000) ^

                                (AES_Te4[(temp >>  8) & 0xff] & 0x00ff0000) ^

                                (AES_Te4[(temp      ) & 0xff] & 0x0000ff00) ^

                                (AES_Te4[(temp >> 24)       ] & 0x000000ff) ^

				rcon[i];

			rk[ 7] = rk[ 1] ^ rk[ 6];

			rk[ 8] = rk[ 2] ^ rk[ 7];

			rk[ 9] = rk[ 3] ^ rk[ 8];

			if (++i == 8) {

				return 0;

			}

			rk[10] = rk[ 4] ^ rk[ 9];

			rk[11] = rk[ 5] ^ rk[10];

			rk += 6;

		}

	}

	rk[6] = GETU32(userKey + 24);

	rk[7] = GETU32(userKey + 28);

	if (bits == 256) {

		while (1) {

			temp = rk[ 7];

			rk[ 8] = rk[ 0] ^

                                (AES_Te4[(temp >> 16) & 0xff] & 0xff000000) ^

                                (AES_Te4[(temp >>  8) & 0xff] & 0x00ff0000) ^

                                (AES_Te4[(temp      ) & 0xff] & 0x0000ff00) ^

                                (AES_Te4[(temp >> 24)       ] & 0x000000ff) ^

				rcon[i];

			rk[ 9] = rk[ 1] ^ rk[ 8];

			rk[10] = rk[ 2] ^ rk[ 9];

			rk[11] = rk[ 3] ^ rk[10];

			if (++i == 7) {

				return 0;

			}

			temp = rk[11];

			rk[12] = rk[ 4] ^

                                (AES_Te4[(temp >> 24)       ] & 0xff000000) ^

                                (AES_Te4[(temp >> 16) & 0xff] & 0x00ff0000) ^

                                (AES_Te4[(temp >>  8) & 0xff] & 0x0000ff00) ^

                                (AES_Te4[(temp      ) & 0xff] & 0x000000ff);

			rk[13] = rk[ 5] ^ rk[12];

			rk[14] = rk[ 6] ^ rk[13];

			rk[15] = rk[ 7] ^ rk[14];



			rk += 8;

        	}

	}

	return 0;

}

get_field (const unsigned char *data, enum floatformat_byteorders order,

           unsigned int total_len, unsigned int start, unsigned int len)

{

  unsigned long result;

  unsigned int cur_byte;

  int cur_bitshift;



  /* Start at the least significant part of the field.  */

  cur_byte = (start + len) / FLOATFORMAT_CHAR_BIT;

  if (order == floatformat_little)

    cur_byte = (total_len / FLOATFORMAT_CHAR_BIT) - cur_byte - 1;

  cur_bitshift =

    ((start + len) % FLOATFORMAT_CHAR_BIT) - FLOATFORMAT_CHAR_BIT;

  result = *(data + cur_byte) >> (-cur_bitshift);

  cur_bitshift += FLOATFORMAT_CHAR_BIT;

  if (order == floatformat_little)

    ++cur_byte;

  else

    --cur_byte;



  /* Move towards the most significant part of the field.  */

  while ((unsigned int) cur_bitshift < len)

    {

      if (len - cur_bitshift < FLOATFORMAT_CHAR_BIT)

	/* This is the last byte; zero out the bits which are not part of

	   this field.  */

	result |=

	  (*(data + cur_byte) & ((1 << (len - cur_bitshift)) - 1))

	    << cur_bitshift;

      else

	result |= *(data + cur_byte) << cur_bitshift;

      cur_bitshift += FLOATFORMAT_CHAR_BIT;

      if (order == floatformat_little)

	++cur_byte;

      else

	--cur_byte;

    }

  return result;

}

void address_space_unmap(AddressSpace *as, void *buffer, hwaddr len,

                         int is_write, hwaddr access_len)

{

    if (buffer != bounce.buffer) {

        if (is_write) {

            ram_addr_t addr1 = qemu_ram_addr_from_host_nofail(buffer);

            while (access_len) {

                unsigned l;

                l = TARGET_PAGE_SIZE;

                if (l > access_len)

                    l = access_len;

                invalidate_and_set_dirty(addr1, l);

                addr1 += l;

                access_len -= l;

            }

        }

        if (xen_enabled()) {

            xen_invalidate_map_cache_entry(buffer);

        }

        return;

    }

    if (is_write) {

        address_space_write(as, bounce.addr, bounce.buffer, access_len);

    }

    qemu_vfree(bounce.buffer);

    bounce.buffer = NULL;

    cpu_notify_map_clients();

}

void cpu_physical_memory_unmap(void *buffer, target_phys_addr_t len,

                               int is_write, target_phys_addr_t access_len)

{

    if (buffer != bounce.buffer) {

        if (is_write) {

            unsigned long addr1 = (uint8_t *)buffer - phys_ram_base;

            while (access_len) {

                unsigned l;

                l = TARGET_PAGE_SIZE;

                if (l > access_len)

                    l = access_len;

                if (!cpu_physical_memory_is_dirty(addr1)) {

                    /* invalidate code */

                    tb_invalidate_phys_page_range(addr1, addr1 + l, 0);

                    /* set dirty bit */

                    phys_ram_dirty[addr1 >> TARGET_PAGE_BITS] |=

                        (0xff & ~CODE_DIRTY_FLAG);

                }

                addr1 += l;

                access_len -= l;

            }

        }

        return;

    }

    if (is_write) {

        cpu_physical_memory_write(bounce.addr, bounce.buffer, access_len);

    }

    qemu_free(bounce.buffer);

    bounce.buffer = NULL;


}

void address_space_unmap(AddressSpace *as, void *buffer, hwaddr len,

                         int is_write, hwaddr access_len)

{

    if (buffer != bounce.buffer) {

        MemoryRegion *mr;

        ram_addr_t addr1;



        mr = qemu_ram_addr_from_host(buffer, &addr1);

        assert(mr != NULL);

        if (is_write) {

            while (access_len) {

                unsigned l;

                l = TARGET_PAGE_SIZE;

                if (l > access_len)

                    l = access_len;

                invalidate_and_set_dirty(addr1, l);

                addr1 += l;

                access_len -= l;

            }

        }

        if (xen_enabled()) {

            xen_invalidate_map_cache_entry(buffer);

        }

        memory_region_unref(mr);

        return;

    }

    if (is_write) {

        address_space_write(as, bounce.addr, bounce.buffer, access_len);

    }

    qemu_vfree(bounce.buffer);

    bounce.buffer = NULL;

    memory_region_unref(bounce.mr);

    cpu_notify_map_clients();

}

void *address_space_map(AddressSpace *as,

                        target_phys_addr_t addr,

                        target_phys_addr_t *plen,

                        bool is_write)

{

    AddressSpaceDispatch *d = as->dispatch;

    target_phys_addr_t len = *plen;

    target_phys_addr_t todo = 0;

    int l;

    target_phys_addr_t page;

    MemoryRegionSection *section;

    ram_addr_t raddr = RAM_ADDR_MAX;

    ram_addr_t rlen;

    void *ret;



    while (len > 0) {

        page = addr & TARGET_PAGE_MASK;

        l = (page + TARGET_PAGE_SIZE) - addr;

        if (l > len)

            l = len;

        section = phys_page_find(d, page >> TARGET_PAGE_BITS);



        if (!(memory_region_is_ram(section->mr) && !section->readonly)) {

            if (todo || bounce.buffer) {

                break;

            }

            bounce.buffer = qemu_memalign(TARGET_PAGE_SIZE, TARGET_PAGE_SIZE);

            bounce.addr = addr;

            bounce.len = l;

            if (!is_write) {

                address_space_read(as, addr, bounce.buffer, l);

            }



            *plen = l;

            return bounce.buffer;

        }

        if (!todo) {

            raddr = memory_region_get_ram_addr(section->mr)

                + memory_region_section_addr(section, addr);

        }



        len -= l;

        addr += l;

        todo += l;

    }

    rlen = todo;

    ret = qemu_ram_ptr_length(raddr, &rlen);

    *plen = rlen;

    return ret;

}

static av_cold int cook_decode_init(AVCodecContext *avctx)

{

    COOKContext *q = avctx->priv_data;

    const uint8_t *edata_ptr = avctx->extradata;

    const uint8_t *edata_ptr_end = edata_ptr + avctx->extradata_size;

    int extradata_size = avctx->extradata_size;

    int s = 0;

    unsigned int channel_mask = 0;

    int samples_per_frame;

    int ret;

    q->avctx = avctx;



    /* Take care of the codec specific extradata. */

    if (extradata_size < 8) {

        av_log(avctx, AV_LOG_ERROR, "Necessary extradata missing!\n");

        return AVERROR_INVALIDDATA;

    }

    av_log(avctx, AV_LOG_DEBUG, "codecdata_length=%d\n", avctx->extradata_size);



    /* Take data from the AVCodecContext (RM container). */

    if (!avctx->channels) {

        av_log(avctx, AV_LOG_ERROR, "Invalid number of channels\n");

        return AVERROR_INVALIDDATA;

    }



    /* Initialize RNG. */

    av_lfg_init(&q->random_state, 0);



    ff_audiodsp_init(&q->adsp);



    while (edata_ptr < edata_ptr_end) {

        /* 8 for mono, 16 for stereo, ? for multichannel

           Swap to right endianness so we don't need to care later on. */

        if (extradata_size >= 8) {

            q->subpacket[s].cookversion = bytestream_get_be32(&edata_ptr);

            samples_per_frame           = bytestream_get_be16(&edata_ptr);

            q->subpacket[s].subbands = bytestream_get_be16(&edata_ptr);

            extradata_size -= 8;

        }

        if (extradata_size >= 8) {

            bytestream_get_be32(&edata_ptr);    // Unknown unused

            q->subpacket[s].js_subband_start = bytestream_get_be16(&edata_ptr);

            q->subpacket[s].js_vlc_bits = bytestream_get_be16(&edata_ptr);

            extradata_size -= 8;

        }



        /* Initialize extradata related variables. */

        q->subpacket[s].samples_per_channel = samples_per_frame / avctx->channels;

        q->subpacket[s].bits_per_subpacket = avctx->block_align * 8;



        /* Initialize default data states. */

        q->subpacket[s].log2_numvector_size = 5;

        q->subpacket[s].total_subbands = q->subpacket[s].subbands;

        q->subpacket[s].num_channels = 1;



        /* Initialize version-dependent variables */



        av_log(avctx, AV_LOG_DEBUG, "subpacket[%i].cookversion=%x\n", s,

               q->subpacket[s].cookversion);

        q->subpacket[s].joint_stereo = 0;

        switch (q->subpacket[s].cookversion) {

        case MONO:

            if (avctx->channels != 1) {

                avpriv_request_sample(avctx, "Container channels != 1");

                return AVERROR_PATCHWELCOME;

            }

            av_log(avctx, AV_LOG_DEBUG, "MONO\n");

            break;

        case STEREO:

            if (avctx->channels != 1) {

                q->subpacket[s].bits_per_subpdiv = 1;

                q->subpacket[s].num_channels = 2;

            }

            av_log(avctx, AV_LOG_DEBUG, "STEREO\n");

            break;

        case JOINT_STEREO:

            if (avctx->channels != 2) {

                avpriv_request_sample(avctx, "Container channels != 2");

                return AVERROR_PATCHWELCOME;

            }

            av_log(avctx, AV_LOG_DEBUG, "JOINT_STEREO\n");

            if (avctx->extradata_size >= 16) {

                q->subpacket[s].total_subbands = q->subpacket[s].subbands +

                                                 q->subpacket[s].js_subband_start;

                q->subpacket[s].joint_stereo = 1;

                q->subpacket[s].num_channels = 2;

            }

            if (q->subpacket[s].samples_per_channel > 256) {

                q->subpacket[s].log2_numvector_size = 6;

            }

            if (q->subpacket[s].samples_per_channel > 512) {

                q->subpacket[s].log2_numvector_size = 7;

            }

            break;

        case MC_COOK:

            av_log(avctx, AV_LOG_DEBUG, "MULTI_CHANNEL\n");

            if (extradata_size >= 4)

                channel_mask |= q->subpacket[s].channel_mask = bytestream_get_be32(&edata_ptr);



            if (av_get_channel_layout_nb_channels(q->subpacket[s].channel_mask) > 1) {

                q->subpacket[s].total_subbands = q->subpacket[s].subbands +

                                                 q->subpacket[s].js_subband_start;

                q->subpacket[s].joint_stereo = 1;

                q->subpacket[s].num_channels = 2;

                q->subpacket[s].samples_per_channel = samples_per_frame >> 1;



                if (q->subpacket[s].samples_per_channel > 256) {

                    q->subpacket[s].log2_numvector_size = 6;

                }

                if (q->subpacket[s].samples_per_channel > 512) {

                    q->subpacket[s].log2_numvector_size = 7;

                }

            } else

                q->subpacket[s].samples_per_channel = samples_per_frame;



            break;

        default:

            avpriv_request_sample(avctx, "Cook version %d",

                                  q->subpacket[s].cookversion);

            return AVERROR_PATCHWELCOME;

        }



        if (s > 1 && q->subpacket[s].samples_per_channel != q->samples_per_channel) {

            av_log(avctx, AV_LOG_ERROR, "different number of samples per channel!\n");

            return AVERROR_INVALIDDATA;

        } else

            q->samples_per_channel = q->subpacket[0].samples_per_channel;





        /* Initialize variable relations */

        q->subpacket[s].numvector_size = (1 << q->subpacket[s].log2_numvector_size);



        /* Try to catch some obviously faulty streams, otherwise it might be exploitable */

        if (q->subpacket[s].total_subbands > 53) {

            avpriv_request_sample(avctx, "total_subbands > 53");

            return AVERROR_PATCHWELCOME;

        }



        if ((q->subpacket[s].js_vlc_bits > 6) ||

            (q->subpacket[s].js_vlc_bits < 2 * q->subpacket[s].joint_stereo)) {

            av_log(avctx, AV_LOG_ERROR, "js_vlc_bits = %d, only >= %d and <= 6 allowed!\n",

                   q->subpacket[s].js_vlc_bits, 2 * q->subpacket[s].joint_stereo);

            return AVERROR_INVALIDDATA;

        }



        if (q->subpacket[s].subbands > 50) {

            avpriv_request_sample(avctx, "subbands > 50");

            return AVERROR_PATCHWELCOME;

        }

        q->subpacket[s].gains1.now      = q->subpacket[s].gain_1;

        q->subpacket[s].gains1.previous = q->subpacket[s].gain_2;

        q->subpacket[s].gains2.now      = q->subpacket[s].gain_3;

        q->subpacket[s].gains2.previous = q->subpacket[s].gain_4;



        q->num_subpackets++;

        s++;

        if (s > MAX_SUBPACKETS) {

            avpriv_request_sample(avctx, "subpackets > %d", MAX_SUBPACKETS);

            return AVERROR_PATCHWELCOME;

        }

    }

    /* Generate tables */

    init_pow2table();

    init_gain_table(q);

    init_cplscales_table(q);



    if ((ret = init_cook_vlc_tables(q)))

        return ret;





    if (avctx->block_align >= UINT_MAX / 2)

        return AVERROR(EINVAL);



    /* Pad the databuffer with:

       DECODE_BYTES_PAD1 or DECODE_BYTES_PAD2 for decode_bytes(),

       AV_INPUT_BUFFER_PADDING_SIZE, for the bitstreamreader. */

    q->decoded_bytes_buffer =

        av_mallocz(avctx->block_align

                   + DECODE_BYTES_PAD1(avctx->block_align)

                   + AV_INPUT_BUFFER_PADDING_SIZE);

    if (!q->decoded_bytes_buffer)

        return AVERROR(ENOMEM);



    /* Initialize transform. */

    if ((ret = init_cook_mlt(q)))

        return ret;



    /* Initialize COOK signal arithmetic handling */

    if (1) {

        q->scalar_dequant  = scalar_dequant_float;

        q->decouple        = decouple_float;

        q->imlt_window     = imlt_window_float;

        q->interpolate     = interpolate_float;

        q->saturate_output = saturate_output_float;

    }



    /* Try to catch some obviously faulty streams, otherwise it might be exploitable */

    if (q->samples_per_channel != 256 && q->samples_per_channel != 512 &&

        q->samples_per_channel != 1024) {

        avpriv_request_sample(avctx, "samples_per_channel = %d",

                              q->samples_per_channel);

        return AVERROR_PATCHWELCOME;

    }



    avctx->sample_fmt = AV_SAMPLE_FMT_FLTP;

    if (channel_mask)

        avctx->channel_layout = channel_mask;

    else

        avctx->channel_layout = (avctx->channels == 2) ? AV_CH_LAYOUT_STEREO : AV_CH_LAYOUT_MONO;



#ifdef DEBUG

    dump_cook_context(q);

#endif

    return 0;

}

static av_cold int ape_decode_init(AVCodecContext *avctx)

{

    APEContext *s = avctx->priv_data;

    int i;



    if (avctx->extradata_size != 6) {

        av_log(avctx, AV_LOG_ERROR, "Incorrect extradata\n");

        return AVERROR(EINVAL);

    }

    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Only mono and stereo is supported\n");

        return AVERROR(EINVAL);

    }

    s->bps = avctx->bits_per_coded_sample;

    switch (s->bps) {

    case 8:

        avctx->sample_fmt = AV_SAMPLE_FMT_U8;

        break;

    case 16:

        avctx->sample_fmt = AV_SAMPLE_FMT_S16;

        break;

    case 24:

        avctx->sample_fmt = AV_SAMPLE_FMT_S32;

        break;

    default:

        av_log_ask_for_sample(avctx, "Unsupported bits per coded sample %d\n",

                              s->bps);

        return AVERROR_PATCHWELCOME;

    }

    s->avctx             = avctx;

    s->channels          = avctx->channels;

    s->fileversion       = AV_RL16(avctx->extradata);

    s->compression_level = AV_RL16(avctx->extradata + 2);

    s->flags             = AV_RL16(avctx->extradata + 4);



    av_log(avctx, AV_LOG_DEBUG, "Compression Level: %d - Flags: %d\n",

           s->compression_level, s->flags);

    if (s->compression_level % 1000 || s->compression_level > COMPRESSION_LEVEL_INSANE) {

        av_log(avctx, AV_LOG_ERROR, "Incorrect compression level %d\n",

               s->compression_level);

        return AVERROR_INVALIDDATA;

    }

    s->fset = s->compression_level / 1000 - 1;

    for (i = 0; i < APE_FILTER_LEVELS; i++) {

        if (!ape_filter_orders[s->fset][i])

            break;

        FF_ALLOC_OR_GOTO(avctx, s->filterbuf[i],

                         (ape_filter_orders[s->fset][i] * 3 + HISTORY_SIZE) * 4,

                         filter_alloc_fail);

    }



    ff_dsputil_init(&s->dsp, avctx);

    avctx->channel_layout = (avctx->channels==2) ? AV_CH_LAYOUT_STEREO : AV_CH_LAYOUT_MONO;



    avcodec_get_frame_defaults(&s->frame);

    avctx->coded_frame = &s->frame;



    return 0;

filter_alloc_fail:

    ape_decode_close(avctx);

    return AVERROR(ENOMEM);

}

static av_cold int atrac3_decode_init(AVCodecContext *avctx)

{

    int i, ret;

    int version, delay, samples_per_frame, frame_factor;

    const uint8_t *edata_ptr = avctx->extradata;

    ATRAC3Context *q = avctx->priv_data;



    if (avctx->channels <= 0 || avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Channel configuration error!\n");

        return AVERROR(EINVAL);

    }



    /* Take care of the codec-specific extradata. */

    if (avctx->extradata_size == 14) {

        /* Parse the extradata, WAV format */

        av_log(avctx, AV_LOG_DEBUG, "[0-1] %d\n",

               bytestream_get_le16(&edata_ptr));  // Unknown value always 1

        edata_ptr += 4;                             // samples per channel

        q->coding_mode = bytestream_get_le16(&edata_ptr);

        av_log(avctx, AV_LOG_DEBUG,"[8-9] %d\n",

               bytestream_get_le16(&edata_ptr));  //Dupe of coding mode

        frame_factor = bytestream_get_le16(&edata_ptr);  // Unknown always 1

        av_log(avctx, AV_LOG_DEBUG,"[12-13] %d\n",

               bytestream_get_le16(&edata_ptr));  // Unknown always 0



        /* setup */

        samples_per_frame    = SAMPLES_PER_FRAME * avctx->channels;

        version              = 4;

        delay                = 0x88E;

        q->coding_mode       = q->coding_mode ? JOINT_STEREO : STEREO;

        q->scrambled_stream  = 0;



        if (avctx->block_align !=  96 * avctx->channels * frame_factor &&

            avctx->block_align != 152 * avctx->channels * frame_factor &&

            avctx->block_align != 192 * avctx->channels * frame_factor) {

            av_log(avctx, AV_LOG_ERROR, "Unknown frame/channel/frame_factor "

                   "configuration %d/%d/%d\n", avctx->block_align,

                   avctx->channels, frame_factor);

            return AVERROR_INVALIDDATA;

        }

    } else if (avctx->extradata_size == 10) {

        /* Parse the extradata, RM format. */

        version                = bytestream_get_be32(&edata_ptr);

        samples_per_frame      = bytestream_get_be16(&edata_ptr);

        delay                  = bytestream_get_be16(&edata_ptr);

        q->coding_mode         = bytestream_get_be16(&edata_ptr);

        q->scrambled_stream    = 1;



    } else {

        av_log(NULL, AV_LOG_ERROR, "Unknown extradata size %d.\n",

               avctx->extradata_size);

        return AVERROR(EINVAL);

    }



    /* Check the extradata */



    if (version != 4) {

        av_log(avctx, AV_LOG_ERROR, "Version %d != 4.\n", version);

        return AVERROR_INVALIDDATA;

    }



    if (samples_per_frame != SAMPLES_PER_FRAME &&

        samples_per_frame != SAMPLES_PER_FRAME * 2) {

        av_log(avctx, AV_LOG_ERROR, "Unknown amount of samples per frame %d.\n",

               samples_per_frame);

        return AVERROR_INVALIDDATA;

    }



    if (delay != 0x88E) {

        av_log(avctx, AV_LOG_ERROR, "Unknown amount of delay %x != 0x88E.\n",

               delay);

        return AVERROR_INVALIDDATA;

    }



    if (q->coding_mode == STEREO)

        av_log(avctx, AV_LOG_DEBUG, "Normal stereo detected.\n");

    else if (q->coding_mode == JOINT_STEREO) {

        if (avctx->channels != 2)

            return AVERROR_INVALIDDATA;

        av_log(avctx, AV_LOG_DEBUG, "Joint stereo detected.\n");

    } else {

        av_log(avctx, AV_LOG_ERROR, "Unknown channel coding mode %x!\n",

               q->coding_mode);

        return AVERROR_INVALIDDATA;

    }



    if (avctx->block_align >= UINT_MAX / 2)

        return AVERROR(EINVAL);



    q->decoded_bytes_buffer = av_mallocz(FFALIGN(avctx->block_align, 4) +

                                         FF_INPUT_BUFFER_PADDING_SIZE);

    if (q->decoded_bytes_buffer == NULL)

        return AVERROR(ENOMEM);



    avctx->sample_fmt = AV_SAMPLE_FMT_FLTP;



    /* initialize the MDCT transform */

    if ((ret = ff_mdct_init(&q->mdct_ctx, 9, 1, 1.0 / 32768)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing MDCT\n");

        av_freep(&q->decoded_bytes_buffer);

        return ret;

    }



    /* init the joint-stereo decoding data */

    q->weighting_delay[0] = 0;

    q->weighting_delay[1] = 7;

    q->weighting_delay[2] = 0;

    q->weighting_delay[3] = 7;

    q->weighting_delay[4] = 0;

    q->weighting_delay[5] = 7;



    for (i = 0; i < 4; i++) {

        q->matrix_coeff_index_prev[i] = 3;

        q->matrix_coeff_index_now[i]  = 3;

        q->matrix_coeff_index_next[i] = 3;

    }



    ff_atrac_init_gain_compensation(&q->gainc_ctx, 4, 3);

    avpriv_float_dsp_init(&q->fdsp, avctx->flags & CODEC_FLAG_BITEXACT);

    ff_fmt_convert_init(&q->fmt_conv, avctx);



    q->units = av_mallocz(sizeof(*q->units) * avctx->channels);

    if (!q->units) {

        atrac3_decode_close(avctx);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static av_cold int adpcm_encode_init(AVCodecContext *avctx)

{

    ADPCMEncodeContext *s = avctx->priv_data;

    uint8_t *extradata;

    int i;

    if (avctx->channels > 2)

        return -1; /* only stereo or mono =) */



    if (avctx->trellis && (unsigned)avctx->trellis > 16U) {

        av_log(avctx, AV_LOG_ERROR, "invalid trellis size\n");

        return -1;

    }



    if (avctx->trellis) {

        int frontier  = 1 << avctx->trellis;

        int max_paths =  frontier * FREEZE_INTERVAL;

        FF_ALLOC_OR_GOTO(avctx, s->paths,

                         max_paths * sizeof(*s->paths), error);

        FF_ALLOC_OR_GOTO(avctx, s->node_buf,

                         2 * frontier * sizeof(*s->node_buf),  error);

        FF_ALLOC_OR_GOTO(avctx, s->nodep_buf,

                         2 * frontier * sizeof(*s->nodep_buf), error);

        FF_ALLOC_OR_GOTO(avctx, s->trellis_hash,

                         65536 * sizeof(*s->trellis_hash), error);

    }



    avctx->bits_per_coded_sample = av_get_bits_per_sample(avctx->codec->id);



    switch (avctx->codec->id) {

    case CODEC_ID_ADPCM_IMA_WAV:

        /* each 16 bits sample gives one nibble

           and we have 4 bytes per channel overhead */

        avctx->frame_size = (BLKSIZE - 4 * avctx->channels) * 8 /

                            (4 * avctx->channels) + 1;

        /* seems frame_size isn't taken into account...

           have to buffer the samples :-( */

        avctx->block_align = BLKSIZE;

        avctx->bits_per_coded_sample = 4;

        break;

    case CODEC_ID_ADPCM_IMA_QT:

        avctx->frame_size  = 64;

        avctx->block_align = 34 * avctx->channels;

        break;

    case CODEC_ID_ADPCM_MS:

        /* each 16 bits sample gives one nibble

           and we have 7 bytes per channel overhead */

        avctx->frame_size = (BLKSIZE - 7 * avctx->channels) * 2 / avctx->channels + 2;

        avctx->block_align = BLKSIZE;

        avctx->bits_per_coded_sample = 4;

        avctx->extradata_size = 32;

        extradata = avctx->extradata = av_malloc(avctx->extradata_size);

        if (!extradata)

            return AVERROR(ENOMEM);

        bytestream_put_le16(&extradata, avctx->frame_size);

        bytestream_put_le16(&extradata, 7); /* wNumCoef */

        for (i = 0; i < 7; i++) {

            bytestream_put_le16(&extradata, ff_adpcm_AdaptCoeff1[i] * 4);

            bytestream_put_le16(&extradata, ff_adpcm_AdaptCoeff2[i] * 4);

        }

        break;

    case CODEC_ID_ADPCM_YAMAHA:

        avctx->frame_size  = BLKSIZE * avctx->channels;

        avctx->block_align = BLKSIZE;

        break;

    case CODEC_ID_ADPCM_SWF:

        if (avctx->sample_rate != 11025 &&

            avctx->sample_rate != 22050 &&

            avctx->sample_rate != 44100) {

            av_log(avctx, AV_LOG_ERROR, "Sample rate must be 11025, "

                   "22050 or 44100\n");

            goto error;

        }

        avctx->frame_size = 512 * (avctx->sample_rate / 11025);

        break;

    default:

        goto error;

    }



    avctx->coded_frame = avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;

error:

    av_freep(&s->paths);

    av_freep(&s->node_buf);

    av_freep(&s->nodep_buf);

    av_freep(&s->trellis_hash);

    return -1;

}

