static int mxf_read_seek(AVFormatContext *s, int stream_index, int64_t sample_time, int flags)

{

    AVStream *st = s->streams[stream_index];

    int64_t seconds;



    if (!s->bit_rate)

        return AVERROR_INVALIDDATA;

    if (sample_time < 0)

        sample_time = 0;

    seconds = av_rescale(sample_time, st->time_base.num, st->time_base.den);

    avio_seek(s->pb, (s->bit_rate * seconds) >> 3, SEEK_SET);

    ff_update_cur_dts(s, st, sample_time);

    return 0;

}

static int asf_read_seek(AVFormatContext *s, int stream_index,

                         int64_t pts, int flags)

{

    ASFContext *asf = s->priv_data;

    AVStream *st    = s->streams[stream_index];

    int64_t pos;

    int index;



    if (s->packet_size <= 0)

        return -1;



    /* Try using the protocol's read_seek if available */

    if (s->pb) {

        int ret = avio_seek_time(s->pb, stream_index, pts, flags);

        if (ret >= 0)

            asf_reset_header(s);

        if (ret != AVERROR(ENOSYS))

            return ret;

    }



    if (!asf->index_read)

        asf_build_simple_index(s, stream_index);



    if ((asf->index_read && st->index_entries)) {

        index = av_index_search_timestamp(st, pts, flags);

        if (index >= 0) {

            /* find the position */

            pos = st->index_entries[index].pos;



            /* do the seek */

            av_log(s, AV_LOG_DEBUG, "SEEKTO: %"PRId64"\n", pos);

            avio_seek(s->pb, pos, SEEK_SET);

            asf_reset_header(s);

            return 0;

        }

    }

    /* no index or seeking by index failed */

    if (ff_seek_frame_binary(s, stream_index, pts, flags) < 0)

        return -1;

    asf_reset_header(s);

    return 0;

}

static int mp3_seek(AVFormatContext *s, int stream_index, int64_t timestamp,

                    int flags)

{

    MP3DecContext *mp3 = s->priv_data;

    AVIndexEntry *ie, ie1;

    AVStream *st = s->streams[0];

    int64_t ret  = av_index_search_timestamp(st, timestamp, flags);

    int64_t best_pos;

    int fast_seek = (s->flags & AVFMT_FLAG_FAST_SEEK) ? 1 : 0;

    int64_t filesize = mp3->header_filesize;



    if (mp3->usetoc == 2)

        return -1; // generic index code



    if (filesize <= 0) {

        int64_t size = avio_size(s->pb);

        if (size > 0 && size > s->internal->data_offset)

            filesize = size - s->internal->data_offset;

    }



    if (   (mp3->is_cbr || fast_seek)

        && (mp3->usetoc == 0 || !mp3->xing_toc)

        && st->duration > 0

        && filesize > 0) {

        ie = &ie1;

        timestamp = av_clip64(timestamp, 0, st->duration);

        ie->timestamp = timestamp;

        ie->pos       = av_rescale(timestamp, filesize, st->duration) + s->internal->data_offset;

    } else if (mp3->xing_toc) {

        if (ret < 0)

            return ret;



        ie = &st->index_entries[ret];

    } else {

        return -1;

    }



    best_pos = mp3_sync(s, ie->pos, flags);

    if (best_pos < 0)

        return best_pos;



    if (mp3->is_cbr && ie == &ie1 && mp3->frames) {

        int frame_duration = av_rescale(st->duration, 1, mp3->frames);

        ie1.timestamp = frame_duration * av_rescale(best_pos - s->internal->data_offset, mp3->frames, mp3->header_filesize);

    }



    ff_update_cur_dts(s, st, ie->timestamp);

    return 0;

}

static int vqf_read_seek(AVFormatContext *s,

                         int stream_index, int64_t timestamp, int flags)

{

    VqfContext *c = s->priv_data;

    AVStream *st;

    int ret;

    int64_t pos;



    st = s->streams[stream_index];

    pos = av_rescale_rnd(timestamp * st->codec->bit_rate,

                         st->time_base.num,

                         st->time_base.den * (int64_t)c->frame_bit_len,

                         (flags & AVSEEK_FLAG_BACKWARD) ?

                                                   AV_ROUND_DOWN : AV_ROUND_UP);

    pos *= c->frame_bit_len;



    st->cur_dts = av_rescale(pos, st->time_base.den,

                             st->codec->bit_rate * (int64_t)st->time_base.num);



    if ((ret = avio_seek(s->pb, ((pos-7) >> 3) + s->internal->data_offset, SEEK_SET)) < 0)

        return ret;



    c->remaining_bits = -7 - ((pos-7)&7);

    return 0;

}

if_start(void)
{
	struct mbuf *ifm, *ifqt;
	DEBUG_CALL("if_start");
	if (if_queued == 0)
	   return; /* Nothing to do */
 again:
        /* check if we can really output */
        if (!slirp_can_output())
            return;
	/*
	 * See which queue to get next packet from
	 * If there's something in the fastq, select it immediately
	 */
	if (if_fastq.ifq_next != &if_fastq) {
		ifm = if_fastq.ifq_next;
	} else {
		/* Nothing on fastq, see if next_m is valid */
		if (next_m != &if_batchq)
		   ifm = next_m;
		else
		   ifm = if_batchq.ifq_next;
		/* Set which packet to send on next iteration */
		next_m = ifm->ifq_next;
	}
	/* Remove it from the queue */
	ifqt = ifm->ifq_prev;
	remque(ifm);
	--if_queued;
	/* If there are more packets for this session, re-queue them */
	if (ifm->ifs_next != /* ifm->ifs_prev != */ ifm) {
		insque(ifm->ifs_next, ifqt);
		ifs_remque(ifm);
	}
	/* Update so_queued */
	if (ifm->ifq_so) {
		if (--ifm->ifq_so->so_queued == 0)
		   /* If there's no more queued, reset nqueued */
		   ifm->ifq_so->so_nqueued = 0;
	}
	/* Encapsulate the packet for sending */
        if_encap(ifm->m_data, ifm->m_len);
	if (if_queued)
	   goto again;
}

static uint32_t sdhci_read_dataport(SDHCIState *s, unsigned size)

{

    uint32_t value = 0;

    int i;



    /* first check that a valid data exists in host controller input buffer */

    if ((s->prnsts & SDHC_DATA_AVAILABLE) == 0) {

        ERRPRINT("Trying to read from empty buffer\n");

        return 0;

    }



    for (i = 0; i < size; i++) {

        value |= s->fifo_buffer[s->data_count] << i * 8;

        s->data_count++;

        /* check if we've read all valid data (blksize bytes) from buffer */

        if ((s->data_count) >= (s->blksize & 0x0fff)) {

            DPRINT_L2("All %u bytes of data have been read from input buffer\n",

                    s->data_count);

            s->prnsts &= ~SDHC_DATA_AVAILABLE; /* no more data in a buffer */

            s->data_count = 0;  /* next buff read must start at position [0] */



            if (s->trnmod & SDHC_TRNS_BLK_CNT_EN) {

                s->blkcnt--;

            }



            /* if that was the last block of data */

            if ((s->trnmod & SDHC_TRNS_MULTI) == 0 ||

                ((s->trnmod & SDHC_TRNS_BLK_CNT_EN) && (s->blkcnt == 0)) ||

                 /* stop at gap request */

                (s->stopped_state == sdhc_gap_read &&

                 !(s->prnsts & SDHC_DAT_LINE_ACTIVE))) {

                sdhci_end_transfer(s);

            } else { /* if there are more data, read next block from card */

                sdhci_read_block_from_card(s);

            }

            break;

        }

    }



    return value;

}

if_start(Slirp *slirp)

{

    uint64_t now = qemu_get_clock_ns(rt_clock);

    int requeued = 0;

    bool from_batchq = false;

	struct mbuf *ifm, *ifqt;



	DEBUG_CALL("if_start");



	if (slirp->if_queued == 0)

	   return; /* Nothing to do */



 again:

        /* check if we can really output */

        if (!slirp_can_output(slirp->opaque))

            return;



	/*

	 * See which queue to get next packet from

	 * If there's something in the fastq, select it immediately

	 */

	if (slirp->if_fastq.ifq_next != &slirp->if_fastq) {

		ifm = slirp->if_fastq.ifq_next;

	} else {

		/* Nothing on fastq, see if next_m is valid */

		if (slirp->next_m != &slirp->if_batchq)

		   ifm = slirp->next_m;

		else

		   ifm = slirp->if_batchq.ifq_next;



                from_batchq = true;

	}



        slirp->if_queued--;



        /* Try to send packet unless it already expired */

        if (ifm->expiration_date >= now && !if_encap(slirp, ifm)) {

            /* Packet is delayed due to pending ARP resolution */

            requeued++;

            goto out;

        }



        if (from_batchq) {

            /* Set which packet to send on next iteration */

            slirp->next_m = ifm->ifq_next;

        }



	/* Remove it from the queue */

	ifqt = ifm->ifq_prev;

	remque(ifm);



	/* If there are more packets for this session, re-queue them */

	if (ifm->ifs_next != /* ifm->ifs_prev != */ ifm) {

		insque(ifm->ifs_next, ifqt);

		ifs_remque(ifm);

	}



	/* Update so_queued */

	if (ifm->ifq_so) {

		if (--ifm->ifq_so->so_queued == 0)

		   /* If there's no more queued, reset nqueued */

		   ifm->ifq_so->so_nqueued = 0;

	}



        m_free(ifm);



 out:

	if (slirp->if_queued)

	   goto again;



        slirp->if_queued = requeued;

}

