static int rice_count_exact(int32_t *res, int n, int k)

{

    int i;

    int count = 0;



    for (i = 0; i < n; i++) {

        int32_t v = -2 * res[i] - 1;

        v ^= v >> 31;

        count += (v >> k) + 1 + k;

    }

    return count;

}

static int color_distance(uint32_t a, uint32_t b)

{

    int r = 0, d, i;



    for (i = 0; i < 32; i += 8) {

        d = ((a >> i) & 0xFF) - ((b >> i) & 0xFF);

        r += d * d;

    }

    return r;

}

uint32_t net_checksum_add(int len, uint8_t *buf)

{

    uint32_t sum = 0;

    int i;



    for (i = 0; i < len; i++) {

	if (i & 1)

	    sum += (uint32_t)buf[i];

	else

	    sum += (uint32_t)buf[i] << 8;

    }

    return sum;

}

static int64_t truehd_layout(int chanmap)

{

    int layout = 0, i;



    for (i = 0; i < 13; i++)

