static void test_qga_fstrim(gconstpointer fix)

{

    const TestFixture *fixture = fix;

    QDict *ret;

    QList *list;

    const QListEntry *entry;



    ret = qmp_fd(fixture->fd, "{'execute': 'guest-fstrim',"

                 " arguments: { minimum: 4194304 } }");

