            if(s->vol_sprite_usage==STATIC_SPRITE) printf("Static Sprites not supported\n");

            if(s->vol_sprite_usage==STATIC_SPRITE || s->vol_sprite_usage==GMC_SPRITE){

                if(s->vol_sprite_usage==STATIC_SPRITE){

                    s->sprite_width = get_bits(&s->gb, 13);

                    skip_bits1(&s->gb); /* marker */

                    s->sprite_height= get_bits(&s->gb, 13);

                    skip_bits1(&s->gb); /* marker */

                    s->sprite_left  = get_bits(&s->gb, 13);

                    skip_bits1(&s->gb); /* marker */

                    s->sprite_top   = get_bits(&s->gb, 13);

                    skip_bits1(&s->gb); /* marker */

                }

                s->num_sprite_warping_points= get_bits(&s->gb, 6);

                s->sprite_warping_accuracy = get_bits(&s->gb, 2);

                s->sprite_brightness_change= get_bits1(&s->gb);

                if(s->vol_sprite_usage==STATIC_SPRITE)

                    s->low_latency_sprite= get_bits1(&s->gb);            

            }

            // FIXME sadct disable bit if verid!=1 && shape not rect



            if (get_bits1(&s->gb) == 1) {   /* not_8_bit */

                s->quant_precision = get_bits(&s->gb, 4); /* quant_precision */

                if(get_bits(&s->gb, 4)!=8) printf("N-bit not supported\n"); /* bits_per_pixel */

            } else {

                s->quant_precision = 5;

            }



            // FIXME a bunch of grayscale shape things

            if(get_bits1(&s->gb)) printf("Quant-Type not supported\n");  /* vol_quant_type */ //FIXME

            if(vo_ver_id != 1)

                 s->quarter_sample= get_bits1(&s->gb);

            else s->quarter_sample=0;



            if(!get_bits1(&s->gb)) printf("Complexity estimation not supported\n");

#if 0

            if(get_bits1(&s->gb)) printf("resync disable\n");

#else

            skip_bits1(&s->gb);   /* resync_marker_disabled */

#endif

            s->data_partioning= get_bits1(&s->gb);

            if(s->data_partioning){

                printf("data partitioning not supported\n");

                skip_bits1(&s->gb); // reversible vlc

            }



            if(vo_ver_id != 1) {

                s->new_pred= get_bits1(&s->gb);

                if(s->new_pred){

                    printf("new pred not supported\n");

                    skip_bits(&s->gb, 2); /* requested upstream message type */

                    skip_bits1(&s->gb); /* newpred segment type */

                }

                s->reduced_res_vop= get_bits1(&s->gb);

                if(s->reduced_res_vop) printf("reduced resolution VOP not supported\n");

            }

            else{

                s->new_pred=0;

                s->reduced_res_vop= 0;

            }



            s->scalability= get_bits1(&s->gb);

            if (s->scalability) {

                printf("bad scalability!!!\n");

                return -1;

            }

        }

//printf("end Data %X %d\n", show_bits(&s->gb, 32), get_bits_count(&s->gb)&0x7);

        goto redo;

    } else if (startcode == 0x1b2) { //userdata

        char buf[256];

        int i;

        int e;

        int ver, build;



//printf("user Data %X\n", show_bits(&s->gb, 32));

        buf[0]= show_bits(&s->gb, 8);

        for(i=1; i<256; i++){

            buf[i]= show_bits(&s->gb, 16)&0xFF;

            if(buf[i]==0) break;

            skip_bits(&s->gb, 8);

        }

        buf[255]=0;

        e=sscanf(buf, "DivX%dBuild%d", &ver, &build);

        if(e==2){

            s->divx_version= ver;

            s->divx_build= build;

            if(s->picture_number==0){

                printf("This file was encoded with DivX%d Build%d\n", ver, build);

                if(ver==500 && build==413){ //most likely all version are indeed totally buggy but i dunno for sure ...

                    printf("WARNING: this version of DivX is not MPEG4 compatible, trying to workaround these bugs...\n");

                }else{

                    printf("hmm, i havnt seen that version of divx yet, lets assume they fixed these bugs ...\n"

                           "using mpeg4 decoder, if it fails contact the developers (of ffmpeg)\n");

                }

            }

        }

//printf("User Data: %s\n", buf);

        goto redo;

    } else if (startcode != 0x1b6) { //VOP

        goto redo;

    }



    s->pict_type = get_bits(&s->gb, 2) + 1;	/* pict type: I = 0 , P = 1 */

//printf("pic: %d\n", s->pict_type); 

    time_incr=0;

    while (get_bits1(&s->gb) != 0) 

        time_incr++;



    check_marker(&s->gb, "before time_increment");

    s->time_increment= get_bits(&s->gb, s->time_increment_bits);

    if(s->pict_type!=B_TYPE){

        s->time_base+= time_incr;

        s->last_non_b_time[1]= s->last_non_b_time[0];

        s->last_non_b_time[0]= s->time_base*s->time_increment_resolution + s->time_increment;

    }else{

        s->time= (s->last_non_b_time[1]/s->time_increment_resolution + time_incr)*s->time_increment_resolution;

        s->time+= s->time_increment;

    }



    if(check_marker(&s->gb, "before vop_coded")==0 && s->picture_number==0){

        printf("hmm, seems the headers arnt complete, trying to guess time_increment_bits\n");

        for(s->time_increment_bits++ ;s->time_increment_bits<16; s->time_increment_bits++){

            if(get_bits1(&s->gb)) break;

        }

        printf("my guess is %d bits ;)\n",s->time_increment_bits);

    }

    /* vop coded */

    if (get_bits1(&s->gb) != 1)

        goto redo;

//printf("time %d %d %d || %d %d %d\n", s->time_increment_bits, s->time_increment, s->time_base,

//s->time, s->last_non_b_time[0], s->last_non_b_time[1]);  

    if (s->shape != BIN_ONLY_SHAPE && ( s->pict_type == P_TYPE

                          || (s->pict_type == S_TYPE && s->vol_sprite_usage==GMC_SPRITE))) {

        /* rounding type for motion estimation */

	s->no_rounding = get_bits1(&s->gb);

    } else {

	s->no_rounding = 0;

    }

//FIXME reduced res stuff



     if (s->shape != RECT_SHAPE) {

         if (s->vol_sprite_usage != 1 || s->pict_type != I_TYPE) {

             int width, height, hor_spat_ref, ver_spat_ref;



             width = get_bits(&s->gb, 13);

             skip_bits1(&s->gb);   /* marker */

             height = get_bits(&s->gb, 13);

             skip_bits1(&s->gb);   /* marker */

             hor_spat_ref = get_bits(&s->gb, 13); /* hor_spat_ref */

             skip_bits1(&s->gb);   /* marker */

             ver_spat_ref = get_bits(&s->gb, 13); /* ver_spat_ref */

         }

         skip_bits1(&s->gb); /* change_CR_disable */



         if (get_bits1(&s->gb) != 0) {

             skip_bits(&s->gb, 8); /* constant_alpha_value */

         }

     }

//FIXME complexity estimation stuff



     if (s->shape != BIN_ONLY_SHAPE) {

         skip_bits(&s->gb, 3); /* intra dc VLC threshold */

         //FIXME interlaced specific bits

     }



     if(s->pict_type == S_TYPE && (s->vol_sprite_usage==STATIC_SPRITE || s->vol_sprite_usage==GMC_SPRITE)){

         if(s->num_sprite_warping_points){

             mpeg4_decode_sprite_trajectory(s);

         }

         if(s->sprite_brightness_change) printf("sprite_brightness_change not supported\n");

         if(s->vol_sprite_usage==STATIC_SPRITE) printf("static sprite not supported\n");

     }



     if (s->shape != BIN_ONLY_SHAPE) {

         /* note: we do not use quant_precision to avoid problem if no

            MPEG4 vol header as it is found on some old opendivx

            movies */

         s->qscale = get_bits(&s->gb, 5);

         if(s->qscale==0){

             printf("Error, header damaged or not MPEG4 header (qscale=0)\n");

             return -1; // makes no sense to continue, as there is nothing left from the image then

         }



         if (s->pict_type != I_TYPE) {

             s->f_code = get_bits(&s->gb, 3);	/* fcode_for */

             if(s->f_code==0){

                 printf("Error, header damaged or not MPEG4 header (f_code=0)\n");

                 return -1; // makes no sense to continue, as the MV decoding will break very quickly

             }

         }

         if (s->pict_type == B_TYPE) {

             s->b_code = get_bits(&s->gb, 3);

//printf("b-code %d\n", s->b_code);

         }

//printf("quant:%d fcode:%d\n", s->qscale, s->f_code);



         if(!s->scalability){

             if (s->shape!=RECT_SHAPE && s->pict_type!=I_TYPE) {

                 skip_bits1(&s->gb); // vop shape coding type

             }

         }

     }

     s->picture_number++; // better than pic number==0 allways ;)

     return 0;

}

static int decode_vol_header(Mpeg4DecContext *ctx, GetBitContext *gb)

{

    MpegEncContext *s = &ctx->m;

    int width, height, vo_ver_id;



    /* vol header */

    skip_bits(gb, 1);                   /* random access */

    s->vo_type = get_bits(gb, 8);

    if (get_bits1(gb) != 0) {           /* is_ol_id */

        vo_ver_id = get_bits(gb, 4);    /* vo_ver_id */

        skip_bits(gb, 3);               /* vo_priority */

    } else {

        vo_ver_id = 1;

    }

    s->aspect_ratio_info = get_bits(gb, 4);

    if (s->aspect_ratio_info == FF_ASPECT_EXTENDED) {

        s->avctx->sample_aspect_ratio.num = get_bits(gb, 8);  // par_width

        s->avctx->sample_aspect_ratio.den = get_bits(gb, 8);  // par_height

    } else {

        s->avctx->sample_aspect_ratio = ff_h263_pixel_aspect[s->aspect_ratio_info];

    }



    if ((ctx->vol_control_parameters = get_bits1(gb))) { /* vol control parameter */

        int chroma_format = get_bits(gb, 2);

        if (chroma_format != CHROMA_420)

            av_log(s->avctx, AV_LOG_ERROR, "illegal chroma format\n");



        s->low_delay = get_bits1(gb);

        if (get_bits1(gb)) {    /* vbv parameters */

            get_bits(gb, 15);   /* first_half_bitrate */

            skip_bits1(gb);     /* marker */

            get_bits(gb, 15);   /* latter_half_bitrate */

            skip_bits1(gb);     /* marker */

            get_bits(gb, 15);   /* first_half_vbv_buffer_size */

            skip_bits1(gb);     /* marker */

            get_bits(gb, 3);    /* latter_half_vbv_buffer_size */

            get_bits(gb, 11);   /* first_half_vbv_occupancy */

            skip_bits1(gb);     /* marker */

            get_bits(gb, 15);   /* latter_half_vbv_occupancy */

            skip_bits1(gb);     /* marker */

        }

    } else {

        /* is setting low delay flag only once the smartest thing to do?

         * low delay detection won't be overridden. */

        if (s->picture_number == 0)

            s->low_delay = 0;

    }



    ctx->shape = get_bits(gb, 2); /* vol shape */

    if (ctx->shape != RECT_SHAPE)

        av_log(s->avctx, AV_LOG_ERROR, "only rectangular vol supported\n");

    if (ctx->shape == GRAY_SHAPE && vo_ver_id != 1) {

        av_log(s->avctx, AV_LOG_ERROR, "Gray shape not supported\n");

        skip_bits(gb, 4);  /* video_object_layer_shape_extension */

    }



    check_marker(gb, "before time_increment_resolution");



    s->avctx->framerate.num = get_bits(gb, 16);

    if (!s->avctx->framerate.num) {

        av_log(s->avctx, AV_LOG_ERROR, "framerate==0\n");

        return AVERROR_INVALIDDATA;

    }



    ctx->time_increment_bits = av_log2(s->avctx->framerate.num - 1) + 1;

    if (ctx->time_increment_bits < 1)

        ctx->time_increment_bits = 1;



    check_marker(gb, "before fixed_vop_rate");



    if (get_bits1(gb) != 0)     /* fixed_vop_rate  */

        s->avctx->framerate.den = get_bits(gb, ctx->time_increment_bits);

    else

        s->avctx->framerate.den = 1;



    s->avctx->time_base = av_inv_q(av_mul_q(s->avctx->framerate, (AVRational){s->avctx->ticks_per_frame, 1}));



    ctx->t_frame = 0;



    if (ctx->shape != BIN_ONLY_SHAPE) {

        if (ctx->shape == RECT_SHAPE) {

            check_marker(gb, "before width");

            width = get_bits(gb, 13);

            check_marker(gb, "before height");

            height = get_bits(gb, 13);

            check_marker(gb, "after height");

            if (width && height &&  /* they should be non zero but who knows */

                !(s->width && s->codec_tag == AV_RL32("MP4S"))) {

                if (s->width && s->height &&

                    (s->width != width || s->height != height))

                    s->context_reinit = 1;

                s->width  = width;

                s->height = height;

            }

        }



        s->progressive_sequence  =

        s->progressive_frame     = get_bits1(gb) ^ 1;

        s->interlaced_dct        = 0;

        if (!get_bits1(gb) && (s->avctx->debug & FF_DEBUG_PICT_INFO))

            av_log(s->avctx, AV_LOG_INFO,           /* OBMC Disable */

                   "MPEG4 OBMC not supported (very likely buggy encoder)\n");

        if (vo_ver_id == 1)

            ctx->vol_sprite_usage = get_bits1(gb);    /* vol_sprite_usage */

        else

            ctx->vol_sprite_usage = get_bits(gb, 2);  /* vol_sprite_usage */



        if (ctx->vol_sprite_usage == STATIC_SPRITE)

            av_log(s->avctx, AV_LOG_ERROR, "Static Sprites not supported\n");

        if (ctx->vol_sprite_usage == STATIC_SPRITE ||

            ctx->vol_sprite_usage == GMC_SPRITE) {

            if (ctx->vol_sprite_usage == STATIC_SPRITE) {

                skip_bits(gb, 13); // sprite_width

                skip_bits1(gb); /* marker */

                skip_bits(gb, 13); // sprite_height

                skip_bits1(gb); /* marker */

                skip_bits(gb, 13); // sprite_left

                skip_bits1(gb); /* marker */

                skip_bits(gb, 13); // sprite_top

                skip_bits1(gb); /* marker */

            }

            ctx->num_sprite_warping_points = get_bits(gb, 6);

            if (ctx->num_sprite_warping_points > 3) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "%d sprite_warping_points\n",

                       ctx->num_sprite_warping_points);

                ctx->num_sprite_warping_points = 0;

                return AVERROR_INVALIDDATA;

            }

            s->sprite_warping_accuracy  = get_bits(gb, 2);

            ctx->sprite_brightness_change = get_bits1(gb);

            if (ctx->vol_sprite_usage == STATIC_SPRITE)

                skip_bits1(gb); // low_latency_sprite

        }

        // FIXME sadct disable bit if verid!=1 && shape not rect



        if (get_bits1(gb) == 1) {                   /* not_8_bit */

            s->quant_precision = get_bits(gb, 4);   /* quant_precision */

            if (get_bits(gb, 4) != 8)               /* bits_per_pixel */

                av_log(s->avctx, AV_LOG_ERROR, "N-bit not supported\n");

            if (s->quant_precision != 5)

                av_log(s->avctx, AV_LOG_ERROR,

                       "quant precision %d\n", s->quant_precision);

            if (s->quant_precision<3 || s->quant_precision>9) {

                s->quant_precision = 5;

            }

        } else {

            s->quant_precision = 5;

        }



        // FIXME a bunch of grayscale shape things



        if ((s->mpeg_quant = get_bits1(gb))) { /* vol_quant_type */

            int i, v;



            /* load default matrixes */

            for (i = 0; i < 64; i++) {

                int j = s->idsp.idct_permutation[i];

                v = ff_mpeg4_default_intra_matrix[i];

                s->intra_matrix[j]        = v;

                s->chroma_intra_matrix[j] = v;



                v = ff_mpeg4_default_non_intra_matrix[i];

                s->inter_matrix[j]        = v;

                s->chroma_inter_matrix[j] = v;

            }



            /* load custom intra matrix */

            if (get_bits1(gb)) {

                int last = 0;

                for (i = 0; i < 64; i++) {

                    int j;

                    v = get_bits(gb, 8);

                    if (v == 0)

                        break;



                    last = v;

                    j = s->idsp.idct_permutation[ff_zigzag_direct[i]];

                    s->intra_matrix[j]        = last;

                    s->chroma_intra_matrix[j] = last;

                }



                /* replicate last value */

                for (; i < 64; i++) {

                    int j = s->idsp.idct_permutation[ff_zigzag_direct[i]];

                    s->intra_matrix[j]        = last;

                    s->chroma_intra_matrix[j] = last;

                }

            }



            /* load custom non intra matrix */

            if (get_bits1(gb)) {

                int last = 0;

                for (i = 0; i < 64; i++) {

                    int j;

                    v = get_bits(gb, 8);

                    if (v == 0)

                        break;



                    last = v;

                    j = s->idsp.idct_permutation[ff_zigzag_direct[i]];

                    s->inter_matrix[j]        = v;

                    s->chroma_inter_matrix[j] = v;

                }



                /* replicate last value */

                for (; i < 64; i++) {

                    int j = s->idsp.idct_permutation[ff_zigzag_direct[i]];

                    s->inter_matrix[j]        = last;

                    s->chroma_inter_matrix[j] = last;

                }

            }



            // FIXME a bunch of grayscale shape things

        }



        if (vo_ver_id != 1)

            s->quarter_sample = get_bits1(gb);

        else

            s->quarter_sample = 0;



        if (get_bits_left(gb) < 4) {

            av_log(s->avctx, AV_LOG_ERROR, "VOL Header truncated\n");

            return AVERROR_INVALIDDATA;

        }



        if (!get_bits1(gb)) {

            int pos               = get_bits_count(gb);

            int estimation_method = get_bits(gb, 2);

            if (estimation_method < 2) {

                if (!get_bits1(gb)) {

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* opaque */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* transparent */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* intra_cae */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* inter_cae */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* no_update */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* upampling */

                }

                if (!get_bits1(gb)) {

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* intra_blocks */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* inter_blocks */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* inter4v_blocks */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* not coded blocks */

                }

                if (!check_marker(gb, "in complexity estimation part 1")) {

                    skip_bits_long(gb, pos - get_bits_count(gb));

                    goto no_cplx_est;

                }

                if (!get_bits1(gb)) {

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* dct_coeffs */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* dct_lines */

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* vlc_syms */

                    ctx->cplx_estimation_trash_i += 4 * get_bits1(gb);  /* vlc_bits */

                }

                if (!get_bits1(gb)) {

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* apm */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* npm */

                    ctx->cplx_estimation_trash_b += 8 * get_bits1(gb);  /* interpolate_mc_q */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* forwback_mc_q */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* halfpel2 */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* halfpel4 */

                }

                if (!check_marker(gb, "in complexity estimation part 2")) {

                    skip_bits_long(gb, pos - get_bits_count(gb));

                    goto no_cplx_est;

                }

                if (estimation_method == 1) {

                    ctx->cplx_estimation_trash_i += 8 * get_bits1(gb);  /* sadct */

                    ctx->cplx_estimation_trash_p += 8 * get_bits1(gb);  /* qpel */

                }

            } else

                av_log(s->avctx, AV_LOG_ERROR,

                       "Invalid Complexity estimation method %d\n",

                       estimation_method);

        } else {



no_cplx_est:

            ctx->cplx_estimation_trash_i =

            ctx->cplx_estimation_trash_p =

            ctx->cplx_estimation_trash_b = 0;

        }



        ctx->resync_marker = !get_bits1(gb); /* resync_marker_disabled */



        s->data_partitioning = get_bits1(gb);

        if (s->data_partitioning)

            ctx->rvlc = get_bits1(gb);



        if (vo_ver_id != 1) {

            ctx->new_pred = get_bits1(gb);

            if (ctx->new_pred) {

                av_log(s->avctx, AV_LOG_ERROR, "new pred not supported\n");

                skip_bits(gb, 2); /* requested upstream message type */

                skip_bits1(gb);   /* newpred segment type */

            }

            if (get_bits1(gb)) // reduced_res_vop

                av_log(s->avctx, AV_LOG_ERROR,

                       "reduced resolution VOP not supported\n");

        } else {

            ctx->new_pred = 0;

        }



        ctx->scalability = get_bits1(gb);



        if (ctx->scalability) {

            GetBitContext bak = *gb;

            int h_sampling_factor_n;

            int h_sampling_factor_m;

            int v_sampling_factor_n;

            int v_sampling_factor_m;



            skip_bits1(gb);    // hierarchy_type

            skip_bits(gb, 4);  /* ref_layer_id */

            skip_bits1(gb);    /* ref_layer_sampling_dir */

            h_sampling_factor_n = get_bits(gb, 5);

            h_sampling_factor_m = get_bits(gb, 5);

            v_sampling_factor_n = get_bits(gb, 5);

            v_sampling_factor_m = get_bits(gb, 5);

            ctx->enhancement_type = get_bits1(gb);



            if (h_sampling_factor_n == 0 || h_sampling_factor_m == 0 ||

                v_sampling_factor_n == 0 || v_sampling_factor_m == 0) {

                /* illegal scalability header (VERY broken encoder),

                 * trying to workaround */

                ctx->scalability = 0;

                *gb            = bak;

            } else

                av_log(s->avctx, AV_LOG_ERROR, "scalability not supported\n");



            // bin shape stuff FIXME

        }

    }



    if (s->avctx->debug&FF_DEBUG_PICT_INFO) {

        av_log(s->avctx, AV_LOG_DEBUG, "tb %d/%d, tincrbits:%d, qp_prec:%d, ps:%d,  %s%s%s%s\n",

               s->avctx->framerate.den, s->avctx->framerate.num,

               ctx->time_increment_bits,

               s->quant_precision,

               s->progressive_sequence,

               ctx->scalability ? "scalability " :"" , s->quarter_sample ? "qpel " : "",

               s->data_partitioning ? "partition " : "", ctx->rvlc ? "rvlc " : ""

        );

    }



    return 0;

}

static void mpeg4_encode_vol_header(MpegEncContext * s, int vo_number, int vol_number)

{

    int vo_ver_id;



    if(s->max_b_frames || s->quarter_sample){

        vo_ver_id= 5;

        s->vo_type= ADV_SIMPLE_VO_TYPE;

    }else{

        vo_ver_id= 1;

        s->vo_type= SIMPLE_VO_TYPE;

    }



    put_bits(&s->pb, 16, 0);

    put_bits(&s->pb, 16, 0x100 + vo_number);        /* video obj */

    put_bits(&s->pb, 16, 0);

    put_bits(&s->pb, 16, 0x120 + vol_number);       /* video obj layer */



    put_bits(&s->pb, 1, 0);		/* random access vol */

    put_bits(&s->pb, 8, s->vo_type);	/* video obj type indication */

    put_bits(&s->pb, 1, 1);		/* is obj layer id= yes */

      put_bits(&s->pb, 4, vo_ver_id);	/* is obj layer ver id */

      put_bits(&s->pb, 3, 1);		/* is obj layer priority */



    aspect_to_info(s, s->avctx->sample_aspect_ratio);



    put_bits(&s->pb, 4, s->aspect_ratio_info);/* aspect ratio info */

    if (s->aspect_ratio_info == FF_ASPECT_EXTENDED){

        put_bits(&s->pb, 8, s->avctx->sample_aspect_ratio.num);

        put_bits(&s->pb, 8, s->avctx->sample_aspect_ratio.den);

    }



    if(s->low_delay){

        put_bits(&s->pb, 1, 1);		/* vol control parameters= yes */

        put_bits(&s->pb, 2, 1);		/* chroma format YUV 420/YV12 */

        put_bits(&s->pb, 1, s->low_delay);

        put_bits(&s->pb, 1, 0);		/* vbv parameters= no */

    }else{

        put_bits(&s->pb, 1, 0);		/* vol control parameters= no */

    }



    put_bits(&s->pb, 2, RECT_SHAPE);	/* vol shape= rectangle */

    put_bits(&s->pb, 1, 1);		/* marker bit */



    put_bits(&s->pb, 16, s->time_increment_resolution);

    if (s->time_increment_bits < 1)

        s->time_increment_bits = 1;

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 1, 0);		/* fixed vop rate=no */

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 13, s->width);	/* vol width */

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 13, s->height);	/* vol height */

    put_bits(&s->pb, 1, 1);		/* marker bit */

    put_bits(&s->pb, 1, s->progressive_sequence ? 0 : 1);

    put_bits(&s->pb, 1, 1);		/* obmc disable */

    if (vo_ver_id == 1) {

        put_bits(&s->pb, 1, s->vol_sprite_usage=0);		/* sprite enable */

    }else{

        put_bits(&s->pb, 2, s->vol_sprite_usage=0);		/* sprite enable */

    }



    s->quant_precision=5;

    put_bits(&s->pb, 1, 0);		/* not 8 bit == false */

    put_bits(&s->pb, 1, s->mpeg_quant);	/* quant type= (0=h263 style)*/



    if(s->mpeg_quant){

        ff_write_quant_matrix(&s->pb, s->avctx->intra_matrix);

        ff_write_quant_matrix(&s->pb, s->avctx->inter_matrix);

    }



    if (vo_ver_id != 1)

        put_bits(&s->pb, 1, s->quarter_sample);

    put_bits(&s->pb, 1, 1);		/* complexity estimation disable */

    s->resync_marker= s->rtp_mode;

    put_bits(&s->pb, 1, s->resync_marker ? 0 : 1);/* resync marker disable */

    put_bits(&s->pb, 1, s->data_partitioning ? 1 : 0);

    if(s->data_partitioning){

        put_bits(&s->pb, 1, 0);		/* no rvlc */

    }



    if (vo_ver_id != 1){

        put_bits(&s->pb, 1, 0);		/* newpred */

        put_bits(&s->pb, 1, 0);		/* reduced res vop */

    }

    put_bits(&s->pb, 1, 0);		/* scalability */



    ff_mpeg4_stuffing(&s->pb);



    /* user data */

    if(!(s->flags & CODEC_FLAG_BITEXACT)){

        put_bits(&s->pb, 16, 0);

        put_bits(&s->pb, 16, 0x1B2);	/* user_data */

	put_string(&s->pb, LIBAVCODEC_IDENT);

        ff_mpeg4_stuffing(&s->pb);

    }

}

void ff_init_block_index(MpegEncContext *s){ //FIXME maybe rename

    const int linesize   = s->current_picture.f.linesize[0]; //not s->linesize as this would be wrong for field pics

    const int uvlinesize = s->current_picture.f.linesize[1];

    const int mb_size= 4;



    s->block_index[0]= s->b8_stride*(s->mb_y*2    ) - 2 + s->mb_x*2;

    s->block_index[1]= s->b8_stride*(s->mb_y*2    ) - 1 + s->mb_x*2;

    s->block_index[2]= s->b8_stride*(s->mb_y*2 + 1) - 2 + s->mb_x*2;

    s->block_index[3]= s->b8_stride*(s->mb_y*2 + 1) - 1 + s->mb_x*2;

    s->block_index[4]= s->mb_stride*(s->mb_y + 1)                + s->b8_stride*s->mb_height*2 + s->mb_x - 1;

    s->block_index[5]= s->mb_stride*(s->mb_y + s->mb_height + 2) + s->b8_stride*s->mb_height*2 + s->mb_x - 1;

    //block_index is not used by mpeg2, so it is not affected by chroma_format



    s->dest[0] = s->current_picture.f.data[0] + ((s->mb_x - 1) <<  mb_size);

    s->dest[1] = s->current_picture.f.data[1] + ((s->mb_x - 1) << (mb_size - s->chroma_x_shift));

    s->dest[2] = s->current_picture.f.data[2] + ((s->mb_x - 1) << (mb_size - s->chroma_x_shift));



    if(!(s->pict_type==AV_PICTURE_TYPE_B && s->avctx->draw_horiz_band && s->picture_structure==PICT_FRAME))

    {

        if(s->picture_structure==PICT_FRAME){

        s->dest[0] += s->mb_y *   linesize << mb_size;

        s->dest[1] += s->mb_y * uvlinesize << (mb_size - s->chroma_y_shift);

        s->dest[2] += s->mb_y * uvlinesize << (mb_size - s->chroma_y_shift);

        }else{

            s->dest[0] += (s->mb_y>>1) *   linesize << mb_size;

            s->dest[1] += (s->mb_y>>1) * uvlinesize << (mb_size - s->chroma_y_shift);

            s->dest[2] += (s->mb_y>>1) * uvlinesize << (mb_size - s->chroma_y_shift);

            assert((s->mb_y&1) == (s->picture_structure == PICT_BOTTOM_FIELD));

        }

    }

}

static int sse_mb(MpegEncContext *s){

    int w= 16;

    int h= 16;



    if(s->mb_x*16 + 16 > s->width ) w= s->width - s->mb_x*16;

    if(s->mb_y*16 + 16 > s->height) h= s->height- s->mb_y*16;



    if(w==16 && h==16)

      if(s->avctx->mb_cmp == FF_CMP_NSSE){

        return  s->dsp.nsse[0](s, s->new_picture.f.data[0] + s->mb_x*16 + s->mb_y*s->linesize*16, s->dest[0], s->linesize, 16)

               +s->dsp.nsse[1](s, s->new_picture.f.data[1] + s->mb_x*8  + s->mb_y*s->uvlinesize*8,s->dest[1], s->uvlinesize, 8)

               +s->dsp.nsse[1](s, s->new_picture.f.data[2] + s->mb_x*8  + s->mb_y*s->uvlinesize*8,s->dest[2], s->uvlinesize, 8);

      }else{

        return  s->dsp.sse[0](NULL, s->new_picture.f.data[0] + s->mb_x*16 + s->mb_y*s->linesize*16, s->dest[0], s->linesize, 16)

               +s->dsp.sse[1](NULL, s->new_picture.f.data[1] + s->mb_x*8  + s->mb_y*s->uvlinesize*8,s->dest[1], s->uvlinesize, 8)

               +s->dsp.sse[1](NULL, s->new_picture.f.data[2] + s->mb_x*8  + s->mb_y*s->uvlinesize*8,s->dest[2], s->uvlinesize, 8);

      }

    else

        return  sse(s, s->new_picture.f.data[0] + s->mb_x*16 + s->mb_y*s->linesize*16, s->dest[0], w, h, s->linesize)

               +sse(s, s->new_picture.f.data[1] + s->mb_x*8  + s->mb_y*s->uvlinesize*8,s->dest[1], w>>1, h>>1, s->uvlinesize)

               +sse(s, s->new_picture.f.data[2] + s->mb_x*8  + s->mb_y*s->uvlinesize*8,s->dest[2], w>>1, h>>1, s->uvlinesize);

}

int ff_init_me(MpegEncContext *s){

    MotionEstContext * const c= &s->me;

    int cache_size= FFMIN(ME_MAP_SIZE>>ME_MAP_SHIFT, 1<<ME_MAP_SHIFT);

    int dia_size= FFMAX(FFABS(s->avctx->dia_size)&255, FFABS(s->avctx->pre_dia_size)&255);



    if(FFMIN(s->avctx->dia_size, s->avctx->pre_dia_size) < -ME_MAP_SIZE){

        av_log(s->avctx, AV_LOG_ERROR, "ME_MAP size is too small for SAB diamond\n");

        return -1;

    }

    //special case of snow is needed because snow uses its own iterative ME code

    if(s->me_method!=ME_ZERO && s->me_method!=ME_EPZS && s->me_method!=ME_X1 && s->avctx->codec_id != AV_CODEC_ID_SNOW){

        av_log(s->avctx, AV_LOG_ERROR, "me_method is only allowed to be set to zero and epzs; for hex,umh,full and others see dia_size\n");

        return -1;

    }



    c->avctx= s->avctx;



    if(cache_size < 2*dia_size && !c->stride){

        av_log(s->avctx, AV_LOG_INFO, "ME_MAP size may be a little small for the selected diamond size\n");

    }



    ff_set_cmp(&s->dsp, s->dsp.me_pre_cmp, c->avctx->me_pre_cmp);

    ff_set_cmp(&s->dsp, s->dsp.me_cmp, c->avctx->me_cmp);

    ff_set_cmp(&s->dsp, s->dsp.me_sub_cmp, c->avctx->me_sub_cmp);

    ff_set_cmp(&s->dsp, s->dsp.mb_cmp, c->avctx->mb_cmp);



    c->flags    = get_flags(c, 0, c->avctx->me_cmp    &FF_CMP_CHROMA);

    c->sub_flags= get_flags(c, 0, c->avctx->me_sub_cmp&FF_CMP_CHROMA);

    c->mb_flags = get_flags(c, 0, c->avctx->mb_cmp    &FF_CMP_CHROMA);



/*FIXME s->no_rounding b_type*/

    if(s->flags&CODEC_FLAG_QPEL){

        c->sub_motion_search= qpel_motion_search;

        c->qpel_avg= s->dsp.avg_qpel_pixels_tab;

        if(s->no_rounding) c->qpel_put= s->dsp.put_no_rnd_qpel_pixels_tab;

        else               c->qpel_put= s->dsp.put_qpel_pixels_tab;

    }else{

        if(c->avctx->me_sub_cmp&FF_CMP_CHROMA)

            c->sub_motion_search= hpel_motion_search;

        else if(   c->avctx->me_sub_cmp == FF_CMP_SAD

                && c->avctx->    me_cmp == FF_CMP_SAD

                && c->avctx->    mb_cmp == FF_CMP_SAD)

            c->sub_motion_search= sad_hpel_motion_search; // 2050 vs. 2450 cycles

        else

            c->sub_motion_search= hpel_motion_search;

    }

    c->hpel_avg= s->dsp.avg_pixels_tab;

    if(s->no_rounding) c->hpel_put= s->dsp.put_no_rnd_pixels_tab;

    else               c->hpel_put= s->dsp.put_pixels_tab;



    if(s->linesize){

        c->stride  = s->linesize;

        c->uvstride= s->uvlinesize;

    }else{

        c->stride  = 16*s->mb_width + 32;

        c->uvstride=  8*s->mb_width + 16;

    }



    /* 8x8 fullpel search would need a 4x4 chroma compare, which we do

     * not have yet, and even if we had, the motion estimation code

     * does not expect it. */

    if(s->codec_id != AV_CODEC_ID_SNOW){

        if((c->avctx->me_cmp&FF_CMP_CHROMA)/* && !s->dsp.me_cmp[2]*/){

            s->dsp.me_cmp[2]= zero_cmp;

        }

        if((c->avctx->me_sub_cmp&FF_CMP_CHROMA) && !s->dsp.me_sub_cmp[2]){

            s->dsp.me_sub_cmp[2]= zero_cmp;

        }

        c->hpel_put[2][0]= c->hpel_put[2][1]=

        c->hpel_put[2][2]= c->hpel_put[2][3]= zero_hpel;

    }



    if(s->codec_id == AV_CODEC_ID_H261){

        c->sub_motion_search= no_sub_motion_search;

    }



    return 0;

}

void ff_fix_long_p_mvs(MpegEncContext * s)

{

    const int f_code= s->f_code;

    int y;

    UINT8 * fcode_tab= s->fcode_tab;



    /* clip / convert to intra 16x16 type MVs */

    for(y=0; y<s->mb_height; y++){

        int x;

        int xy= (y+1)* (s->mb_width+2)+1;

        int i= y*s->mb_width;

        for(x=0; x<s->mb_width; x++){

            if(s->mb_type[i]&MB_TYPE_INTER){

                if(   fcode_tab[s->p_mv_table[xy][0] + MAX_MV] > f_code

                   || fcode_tab[s->p_mv_table[xy][0] + MAX_MV] == 0

                   || fcode_tab[s->p_mv_table[xy][1] + MAX_MV] > f_code

                   || fcode_tab[s->p_mv_table[xy][1] + MAX_MV] == 0 ){

                    s->mb_type[i] &= ~MB_TYPE_INTER;

                    s->mb_type[i] |= MB_TYPE_INTRA;

                    s->p_mv_table[xy][0] = 0;

                    s->p_mv_table[xy][1] = 0;

                }

            }

            xy++;

            i++;

        }

    }



    if(s->flags&CODEC_FLAG_4MV){

        const int wrap= 2+ s->mb_width*2;



        /* clip / convert to intra 8x8 type MVs */

        for(y=0; y<s->mb_height; y++){

            int xy= (y*2 + 1)*wrap + 1;

            int i= y*s->mb_width;

            int x;



            for(x=0; x<s->mb_width; x++){

                if(s->mb_type[i]&MB_TYPE_INTER4V){

                    int block;

                    for(block=0; block<4; block++){

                        int off= (block& 1) + (block>>1)*wrap;

                        int mx= s->motion_val[ xy + off ][0];

                        int my= s->motion_val[ xy + off ][1];



                        if(   fcode_tab[mx + MAX_MV] > f_code

                           || fcode_tab[mx + MAX_MV] == 0

                           || fcode_tab[my + MAX_MV] > f_code

                           || fcode_tab[my + MAX_MV] == 0 ){

                            s->mb_type[i] &= ~MB_TYPE_INTER4V;

                            s->mb_type[i] |= MB_TYPE_INTRA;

                        }

                    }

                    xy+=2;

                    i++;

                }

            }

        }

    }

}

static void filter_mb_edgev( H264Context *h, uint8_t *pix, int stride, int bS[4], int qp ) {

    int i, d;

    const int index_a = clip( qp + h->slice_alpha_c0_offset, 0, 51 );

    const int alpha = alpha_table[index_a];

    const int beta  = beta_table[clip( qp + h->slice_beta_offset, 0, 51 )];



    for( i = 0; i < 4; i++ ) {

        if( bS[i] == 0 ) {

            pix += 4 * stride;

            continue;

        }



        /* 4px edge length */

        for( d = 0; d < 4; d++ ) {

            const uint8_t p0 = pix[-1];

            const uint8_t p1 = pix[-2];

            const uint8_t p2 = pix[-3];



            const uint8_t q0 = pix[0];

            const uint8_t q1 = pix[1];

            const uint8_t q2 = pix[2];



            if( abs( p0 - q0 ) >= alpha ||

                abs( p1 - p0 ) >= beta ||

                abs( q1 - q0 ) >= beta ) {

                pix += stride;

                continue;

            }



            if( bS[i] < 4 ) {

                const int tc0 = tc0_table[index_a][bS[i] - 1];

                int tc = tc0;

                int i_delta;



                if( abs( p2 - p0 ) < beta ) {

                    pix[-2] = p1 + clip( ( p2 + ( ( p0 + q0 + 1 ) >> 1 ) - ( p1 << 1 ) ) >> 1, -tc0, tc0 );

                    tc++;

                }

                if( abs( q2 - q0 ) < beta ) {

                    pix[1] = q1 + clip( ( q2 + ( ( p0 + q0 + 1 ) >> 1 ) - ( q1 << 1 ) ) >> 1, -tc0, tc0 );

                    tc++;

                }



                i_delta = clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );

                pix[-1] = clip( p0 + i_delta, 0, 255 );    /* p0' */

                pix[0]  = clip( q0 - i_delta, 0, 255 );    /* q0' */

            }

            else

            {

                const int c  = abs( p0 - q0 ) < (( alpha >> 2 ) + 2 );



                if( abs( p2 - p0 ) < beta && c )

                {

                    const uint8_t p3 = pix[-4];

                    /* p0', p1', p2' */

                    pix[-1] = ( p2 + 2*p1 + 2*p0 + 2*q0 + q1 + 4 ) >> 3;

                    pix[-2] = ( p2 + p1 + p0 + q0 + 2 ) >> 2;

                    pix[-3] = ( 2*p3 + 3*p2 + p1 + p0 + q0 + 4 ) >> 3;

                } else {

                    /* p0' */

                    pix[-1] = ( 2*p1 + p0 + q1 + 2 ) >> 2;

                }

                if( abs( q2 - q0 ) < beta && c )

                {

                    const uint8_t q3 = pix[3];

                    /* q0', q1', q2' */

                    pix[0] = ( p1 + 2*p0 + 2*q0 + 2*q1 + q2 + 4 ) >> 3;

                    pix[1] = ( p0 + q0 + q1 + q2 + 2 ) >> 2;

                    pix[2] = ( 2*q3 + 3*q2 + q1 + q0 + p0 + 4 ) >> 3;

                } else {

                    /* q0' */

                    pix[0] = ( 2*q1 + q0 + p1 + 2 ) >> 2;

                }

            }

            pix += stride;

        }

    }

}

int kvm_arch_handle_exit(CPUPPCState *env, struct kvm_run *run)

{

    int ret;



    switch (run->exit_reason) {

    case KVM_EXIT_DCR:

        if (run->dcr.is_write) {

            dprintf("handle dcr write\n");

            ret = kvmppc_handle_dcr_write(env, run->dcr.dcrn, run->dcr.data);

        } else {

            dprintf("handle dcr read\n");

            ret = kvmppc_handle_dcr_read(env, run->dcr.dcrn, &run->dcr.data);

        }

        break;

    case KVM_EXIT_HLT:

        dprintf("handle halt\n");

        ret = kvmppc_handle_halt(env);

        break;

#ifdef CONFIG_PSERIES

    case KVM_EXIT_PAPR_HCALL:

        dprintf("handle PAPR hypercall\n");

        run->papr_hcall.ret = spapr_hypercall(env, run->papr_hcall.nr,

                                              run->papr_hcall.args);

        ret = 1;

        break;

#endif

    default:

        fprintf(stderr, "KVM: unknown exit reason %d\n", run->exit_reason);

        ret = -1;

        break;

    }



    return ret;

}

int kvm_cpu_exec(CPUState *cpu)

{

    struct kvm_run *run = cpu->kvm_run;

    int ret, run_ret;



    DPRINTF("kvm_cpu_exec()\n");



    if (kvm_arch_process_async_events(cpu)) {

        cpu->exit_request = 0;

        return EXCP_HLT;

    }



    qemu_mutex_unlock_iothread();



    do {

        MemTxAttrs attrs;



        if (cpu->kvm_vcpu_dirty) {

            kvm_arch_put_registers(cpu, KVM_PUT_RUNTIME_STATE);

            cpu->kvm_vcpu_dirty = false;

        }



        kvm_arch_pre_run(cpu, run);

        if (cpu->exit_request) {

            DPRINTF("interrupt exit requested\n");

            /*

             * KVM requires us to reenter the kernel after IO exits to complete

             * instruction emulation. This self-signal will ensure that we

             * leave ASAP again.

             */

            qemu_cpu_kick_self();

        }



        run_ret = kvm_vcpu_ioctl(cpu, KVM_RUN, 0);



        attrs = kvm_arch_post_run(cpu, run);



        if (run_ret < 0) {

            if (run_ret == -EINTR || run_ret == -EAGAIN) {

                DPRINTF("io window exit\n");

                ret = EXCP_INTERRUPT;

                break;

            }

            fprintf(stderr, "error: kvm run failed %s\n",

                    strerror(-run_ret));

#ifdef TARGET_PPC

            if (run_ret == -EBUSY) {

                fprintf(stderr,

                        "This is probably because your SMT is enabled.\n"

                        "VCPU can only run on primary threads with all "

                        "secondary threads offline.\n");

            }

#endif

            ret = -1;

            break;

        }



        trace_kvm_run_exit(cpu->cpu_index, run->exit_reason);

        switch (run->exit_reason) {

        case KVM_EXIT_IO:

            DPRINTF("handle_io\n");

            /* Called outside BQL */

            kvm_handle_io(run->io.port, attrs,

                          (uint8_t *)run + run->io.data_offset,

                          run->io.direction,

                          run->io.size,

                          run->io.count);

            ret = 0;

            break;

        case KVM_EXIT_MMIO:

            DPRINTF("handle_mmio\n");

            /* Called outside BQL */

            address_space_rw(&address_space_memory,

                             run->mmio.phys_addr, attrs,

                             run->mmio.data,

                             run->mmio.len,

                             run->mmio.is_write);

            ret = 0;

            break;

        case KVM_EXIT_IRQ_WINDOW_OPEN:

            DPRINTF("irq_window_open\n");

            ret = EXCP_INTERRUPT;

            break;

        case KVM_EXIT_SHUTDOWN:

            DPRINTF("shutdown\n");

            qemu_system_reset_request();

            ret = EXCP_INTERRUPT;

            break;

        case KVM_EXIT_UNKNOWN:

            fprintf(stderr, "KVM: unknown exit, hardware reason %" PRIx64 "\n",

                    (uint64_t)run->hw.hardware_exit_reason);

            ret = -1;

            break;

        case KVM_EXIT_INTERNAL_ERROR:

            ret = kvm_handle_internal_error(cpu, run);

            break;

        case KVM_EXIT_SYSTEM_EVENT:

            switch (run->system_event.type) {

            case KVM_SYSTEM_EVENT_SHUTDOWN:

                qemu_system_shutdown_request();

                ret = EXCP_INTERRUPT;

                break;

            case KVM_SYSTEM_EVENT_RESET:

                qemu_system_reset_request();

                ret = EXCP_INTERRUPT;

                break;

            case KVM_SYSTEM_EVENT_CRASH:


                qemu_mutex_lock_iothread();

                qemu_system_guest_panicked();

                qemu_mutex_unlock_iothread();

                ret = 0;

                break;

            default:

                DPRINTF("kvm_arch_handle_exit\n");

                ret = kvm_arch_handle_exit(cpu, run);

                break;

            }

            break;

        default:

            DPRINTF("kvm_arch_handle_exit\n");

            ret = kvm_arch_handle_exit(cpu, run);

            break;

        }

    } while (ret == 0);



    qemu_mutex_lock_iothread();



    if (ret < 0) {

        cpu_dump_state(cpu, stderr, fprintf, CPU_DUMP_CODE);

        vm_stop(RUN_STATE_INTERNAL_ERROR);

    }



    cpu->exit_request = 0;

    return ret;

}

int kvm_cpu_exec(CPUState *cpu)

{

    struct kvm_run *run = cpu->kvm_run;

    int ret, run_ret;



    DPRINTF("kvm_cpu_exec()\n");



    if (kvm_arch_process_async_events(cpu)) {

        cpu->exit_request = 0;

        return EXCP_HLT;

    }



    do {

        MemTxAttrs attrs;



        if (cpu->kvm_vcpu_dirty) {

            kvm_arch_put_registers(cpu, KVM_PUT_RUNTIME_STATE);

            cpu->kvm_vcpu_dirty = false;

        }



        kvm_arch_pre_run(cpu, run);

        if (cpu->exit_request) {

            DPRINTF("interrupt exit requested\n");

            /*

             * KVM requires us to reenter the kernel after IO exits to complete

             * instruction emulation. This self-signal will ensure that we

             * leave ASAP again.

             */

            qemu_cpu_kick_self();

        }

        qemu_mutex_unlock_iothread();



        run_ret = kvm_vcpu_ioctl(cpu, KVM_RUN, 0);



        qemu_mutex_lock_iothread();

        attrs = kvm_arch_post_run(cpu, run);



        if (run_ret < 0) {

            if (run_ret == -EINTR || run_ret == -EAGAIN) {

                DPRINTF("io window exit\n");

                ret = EXCP_INTERRUPT;

                break;

            }

            fprintf(stderr, "error: kvm run failed %s\n",

                    strerror(-run_ret));

#ifdef TARGET_PPC

            if (run_ret == -EBUSY) {

                fprintf(stderr,

                        "This is probably because your SMT is enabled.\n"

                        "VCPU can only run on primary threads with all "

                        "secondary threads offline.\n");

            }

#endif

            ret = -1;

            break;

        }



        trace_kvm_run_exit(cpu->cpu_index, run->exit_reason);

        switch (run->exit_reason) {

        case KVM_EXIT_IO:

            DPRINTF("handle_io\n");

            kvm_handle_io(run->io.port, attrs,

                          (uint8_t *)run + run->io.data_offset,

                          run->io.direction,

                          run->io.size,

                          run->io.count);

            ret = 0;

            break;

        case KVM_EXIT_MMIO:

            DPRINTF("handle_mmio\n");

            address_space_rw(&address_space_memory,

                             run->mmio.phys_addr, attrs,

                             run->mmio.data,

                             run->mmio.len,

                             run->mmio.is_write);

            ret = 0;

            break;

        case KVM_EXIT_IRQ_WINDOW_OPEN:

            DPRINTF("irq_window_open\n");

            ret = EXCP_INTERRUPT;

            break;

        case KVM_EXIT_SHUTDOWN:

            DPRINTF("shutdown\n");

            qemu_system_reset_request();

            ret = EXCP_INTERRUPT;

            break;

        case KVM_EXIT_UNKNOWN:

            fprintf(stderr, "KVM: unknown exit, hardware reason %" PRIx64 "\n",

                    (uint64_t)run->hw.hardware_exit_reason);

            ret = -1;

            break;

        case KVM_EXIT_INTERNAL_ERROR:

            ret = kvm_handle_internal_error(cpu, run);

            break;

        case KVM_EXIT_SYSTEM_EVENT:

            switch (run->system_event.type) {

            case KVM_SYSTEM_EVENT_SHUTDOWN:

                qemu_system_shutdown_request();

                ret = EXCP_INTERRUPT;

                break;

            case KVM_SYSTEM_EVENT_RESET:

                qemu_system_reset_request();

                ret = EXCP_INTERRUPT;

                break;

            default:

                DPRINTF("kvm_arch_handle_exit\n");

                ret = kvm_arch_handle_exit(cpu, run);

                break;

            }

            break;

        default:

            DPRINTF("kvm_arch_handle_exit\n");

            ret = kvm_arch_handle_exit(cpu, run);

            break;

        }

    } while (ret == 0);



    if (ret < 0) {

        cpu_dump_state(cpu, stderr, fprintf, CPU_DUMP_CODE);

        vm_stop(RUN_STATE_INTERNAL_ERROR);

    }



    cpu->exit_request = 0;

    return ret;

}

static int kvm_handle_internal_error(CPUState *env, struct kvm_run *run)

{

    fprintf(stderr, "KVM internal error.");

    if (kvm_check_extension(kvm_state, KVM_CAP_INTERNAL_ERROR_DATA)) {

        int i;



        fprintf(stderr, " Suberror: %d\n", run->internal.suberror);

        for (i = 0; i < run->internal.ndata; ++i) {

            fprintf(stderr, "extra data[%d]: %"PRIx64"\n",

                    i, (uint64_t)run->internal.data[i]);

        }

    } else {

        fprintf(stderr, "\n");

    }

    if (run->internal.suberror == KVM_INTERNAL_ERROR_EMULATION) {

        fprintf(stderr, "emulation failure\n");

        if (!kvm_arch_stop_on_emulation_error(env)) {

            cpu_dump_state(env, stderr, fprintf, CPU_DUMP_CODE);

            return 0;

        }

    }

    /* FIXME: Should trigger a qmp message to let management know

     * something went wrong.

     */

    return -1;

}

AddressSpace *pci_device_iommu_address_space(PCIDevice *dev)

{

    PCIBus *bus = PCI_BUS(dev->bus);



    if (bus->iommu_fn) {

        return bus->iommu_fn(bus, bus->iommu_opaque, dev->devfn);

    }



    if (bus->parent_dev) {

        /** We are ignoring the bus master DMA bit of the bridge

         *  as it would complicate things such as VFIO for no good reason */

        return pci_device_iommu_address_space(bus->parent_dev);

    }



    return &address_space_memory;

}

PCIDevice *pci_create_simple(PCIBus *bus, int devfn, const char *name)

{

    PCIDevice *dev = pci_create(bus, devfn, name);

    qdev_init(&dev->qdev);

    return dev;

}

PCIBus *pci_device_root_bus(const PCIDevice *d)

{

    PCIBus *bus = d->bus;



    while (!pci_bus_is_root(bus)) {

        d = bus->parent_dev;

        assert(d != NULL);



        bus = d->bus;

    }



    return bus;

}

bool bdrv_debug_is_suspended(BlockDriverState *bs, const char *tag)

{

    while (bs && bs->drv && !bs->drv->bdrv_debug_is_suspended) {

        bs = bs->file;

    }



    if (bs && bs->drv && bs->drv->bdrv_debug_is_suspended) {

        return bs->drv->bdrv_debug_is_suspended(bs, tag);

    }



    return false;

}

static inline void gen_op_eval_fbl(TCGv dst, TCGv src,

                                    unsigned int fcc_offset)

{

    gen_mov_reg_FCC0(dst, src, fcc_offset);

    gen_mov_reg_FCC1(cpu_tmp0, src, fcc_offset);

    tcg_gen_xori_tl(cpu_tmp0, cpu_tmp0, 0x1);

    tcg_gen_and_tl(dst, dst, cpu_tmp0);

}

static inline void gen_op_eval_fbe(TCGv dst, TCGv src,

                                    unsigned int fcc_offset)

{

    gen_mov_reg_FCC0(dst, src, fcc_offset);

    gen_mov_reg_FCC1(cpu_tmp0, src, fcc_offset);

    tcg_gen_or_tl(dst, dst, cpu_tmp0);

    tcg_gen_xori_tl(dst, dst, 0x1);

}

static inline void gen_op_eval_fbu(TCGv dst, TCGv src,

                                    unsigned int fcc_offset)

{

    gen_mov_reg_FCC0(dst, src, fcc_offset);

    gen_mov_reg_FCC1(cpu_tmp0, src, fcc_offset);

    tcg_gen_and_tl(dst, dst, cpu_tmp0);

}

static inline void gen_op_eval_fbue(TCGv dst, TCGv src,

                                    unsigned int fcc_offset)

{

    gen_mov_reg_FCC0(dst, src, fcc_offset);

    gen_mov_reg_FCC1(cpu_tmp0, src, fcc_offset);

    tcg_gen_xor_tl(dst, dst, cpu_tmp0);

    tcg_gen_xori_tl(dst, dst, 0x1);

}

static int dvbsub_decode(AVCodecContext *avctx,

                         void *data, int *data_size,

                         AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    DVBSubContext *ctx = avctx->priv_data;

    AVSubtitle *sub = data;

    const uint8_t *p, *p_end;

    int segment_type;

    int page_id;

    int segment_length;



#ifdef DEBUG_PACKET_CONTENTS

    int i;



    av_log(avctx, AV_LOG_INFO, "DVB sub packet:\n");



    for (i=0; i < buf_size; i++) {

        av_log(avctx, AV_LOG_INFO, "%02x ", buf[i]);

        if (i % 16 == 15)

            av_log(avctx, AV_LOG_INFO, "\n");

    }



    if (i % 16)

        av_log(avctx, AV_LOG_INFO, "\n");



#endif



    if (buf_size <= 2 || *buf != 0x0f)

        return -1;



    p = buf;

    p_end = buf + buf_size;



    while (p < p_end && *p == 0x0f) {

        p += 1;

        segment_type = *p++;

        page_id = AV_RB16(p);

        p += 2;

        segment_length = AV_RB16(p);

        p += 2;



        if (page_id == ctx->composition_id || page_id == ctx->ancillary_id ||

            ctx->composition_id == -1 || ctx->ancillary_id == -1) {

            switch (segment_type) {

            case DVBSUB_PAGE_SEGMENT:

                dvbsub_parse_page_segment(avctx, p, segment_length);

                break;

            case DVBSUB_REGION_SEGMENT:

                dvbsub_parse_region_segment(avctx, p, segment_length);

                break;

            case DVBSUB_CLUT_SEGMENT:

                dvbsub_parse_clut_segment(avctx, p, segment_length);

                break;

            case DVBSUB_OBJECT_SEGMENT:

                dvbsub_parse_object_segment(avctx, p, segment_length);

                break;

            case DVBSUB_DISPLAYDEFINITION_SEGMENT:

                dvbsub_parse_display_definition_segment(avctx, p, segment_length);

            case DVBSUB_DISPLAY_SEGMENT:

                *data_size = dvbsub_display_end_segment(avctx, p, segment_length, sub);

                break;

            default:

                av_dlog(avctx, "Subtitling segment type 0x%x, page id %d, length %d\n",

                        segment_type, page_id, segment_length);

                break;

            }

        }



        p += segment_length;

    }



    return p - buf;

}

static int dvbsub_parse(AVCodecParserContext *s,

                        AVCodecContext *avctx,

                        const uint8_t **poutbuf, int *poutbuf_size,

                        const uint8_t *buf, int buf_size)

{

    DVBSubParseContext *pc = s->priv_data;

    uint8_t *p, *p_end;

    int i, len, buf_pos = 0;



    av_dlog(avctx, "DVB parse packet pts=%"PRIx64", lpts=%"PRIx64", cpts=%"PRIx64":\n",

            s->pts, s->last_pts, s->cur_frame_pts[s->cur_frame_start_index]);



    for (i=0; i < buf_size; i++)

    {

        av_dlog(avctx, "%02x ", buf[i]);

        if (i % 16 == 15)

            av_dlog(avctx, "\n");

    }



    if (i % 16 != 0)

        av_dlog(avctx, "\n");



    *poutbuf = NULL;

    *poutbuf_size = 0;



    s->fetch_timestamp = 1;



    if (s->last_pts != s->pts && s->pts != AV_NOPTS_VALUE) /* Start of a new packet */

    {

        if (pc->packet_index != pc->packet_start)

        {

            av_dlog(avctx, "Discarding %d bytes\n",

                    pc->packet_index - pc->packet_start);

        }



        pc->packet_start = 0;

        pc->packet_index = 0;



        if (buf_size < 2 || buf[0] != 0x20 || buf[1] != 0x00) {

            av_dlog(avctx, "Bad packet header\n");

            return -1;

        }



        buf_pos = 2;



        pc->in_packet = 1;

    } else {

        if (pc->packet_start != 0)

        {

            if (pc->packet_index != pc->packet_start)

            {

                memmove(pc->packet_buf, pc->packet_buf + pc->packet_start,

                            pc->packet_index - pc->packet_start);



                pc->packet_index -= pc->packet_start;

                pc->packet_start = 0;

            } else {

                pc->packet_start = 0;

                pc->packet_index = 0;

            }

        }

    }



    if (buf_size - buf_pos + pc->packet_index > PARSE_BUF_SIZE)

        return -1;



/* if not currently in a packet, discard data */

    if (pc->in_packet == 0)

        return buf_size;



    memcpy(pc->packet_buf + pc->packet_index, buf + buf_pos, buf_size - buf_pos);

    pc->packet_index += buf_size - buf_pos;



    p = pc->packet_buf;

    p_end = pc->packet_buf + pc->packet_index;



    while (p < p_end)

    {

        if (*p == 0x0f)

        {

            if (p + 6 <= p_end)

            {

                len = AV_RB16(p + 4);



                if (p + len + 6 <= p_end)

                {

                    *poutbuf_size += len + 6;



                    p += len + 6;

                } else

                    break;

            } else

                break;

        } else if (*p == 0xff) {

            if (p + 1 < p_end)

            {

                av_dlog(avctx, "Junk at end of packet\n");

            }

            pc->packet_index = p - pc->packet_buf;

            pc->in_packet = 0;

            break;

        } else {

            av_log(avctx, AV_LOG_ERROR, "Junk in packet\n");



            pc->packet_index = p - pc->packet_buf;

            pc->in_packet = 0;

            break;

        }

    }



    if (*poutbuf_size > 0)

    {

        *poutbuf = pc->packet_buf;

        pc->packet_start = *poutbuf_size;

    }



    if (s->pts == AV_NOPTS_VALUE)

        s->pts = s->last_pts;



    return buf_size;

}

static int decode(AVCodecContext *avctx, void *data, int *data_size,

                  AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;



    const uint8_t *buf_end;

    uint8_t       segment_type;

    int           segment_length;

    int i, ret;



    av_dlog(avctx, "PGS sub packet:\n");



    for (i = 0; i < buf_size; i++) {

        av_dlog(avctx, "%02x ", buf[i]);

        if (i % 16 == 15)

            av_dlog(avctx, "\n");

    }



    if (i & 15)

        av_dlog(avctx, "\n");



    *data_size = 0;



    /* Ensure that we have received at a least a segment code and segment length */

    if (buf_size < 3)

        return -1;



    buf_end = buf + buf_size;



    /* Step through buffer to identify segments */

    while (buf < buf_end) {

        segment_type   = bytestream_get_byte(&buf);

        segment_length = bytestream_get_be16(&buf);



        av_dlog(avctx, "Segment Length %d, Segment Type %x\n", segment_length, segment_type);



        if (segment_type != DISPLAY_SEGMENT && segment_length > buf_end - buf)

            break;



        switch (segment_type) {

        case PALETTE_SEGMENT:

            parse_palette_segment(avctx, buf, segment_length);

            break;

        case PICTURE_SEGMENT:

            parse_picture_segment(avctx, buf, segment_length);

            break;

        case PRESENTATION_SEGMENT:

            ret = parse_presentation_segment(avctx, buf, segment_length, avpkt->pts);

            if (ret < 0)

                return ret;

            break;

        case WINDOW_SEGMENT:

            /*

             * Window Segment Structure (No new information provided):

             *     2 bytes: Unknown,

             *     2 bytes: X position of subtitle,

             *     2 bytes: Y position of subtitle,

             *     2 bytes: Width of subtitle,

             *     2 bytes: Height of subtitle.

             */

            break;

        case DISPLAY_SEGMENT:

            *data_size = display_end_segment(avctx, data, buf, segment_length);

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unknown subtitle segment type 0x%x, length %d\n",

                   segment_type, segment_length);

            break;

        }



        buf += segment_length;

    }



    return buf_size;

}

static void dvbsub_parse_page_segment(AVCodecContext *avctx,

                                        const uint8_t *buf, int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubRegionDisplay *display;

    DVBSubRegionDisplay *tmp_display_list, **tmp_ptr;



    const uint8_t *buf_end = buf + buf_size;

    int region_id;

    int page_state;



    if (buf_size < 1)

        return;



    ctx->time_out = *buf++;

    page_state = ((*buf++) >> 2) & 3;



    av_dlog(avctx, "Page time out %ds, state %d\n", ctx->time_out, page_state);



    if (page_state == 2) {

        delete_state(ctx);

    }



    tmp_display_list = ctx->display_list;

    ctx->display_list = NULL;

    ctx->display_list_size = 0;



    while (buf + 5 < buf_end) {

        region_id = *buf++;

        buf += 1;



        display = tmp_display_list;

        tmp_ptr = &tmp_display_list;



        while (display && display->region_id != region_id) {

            tmp_ptr = &display->next;

            display = display->next;

        }



        if (!display)

            display = av_mallocz(sizeof(DVBSubRegionDisplay));



        display->region_id = region_id;



        display->x_pos = AV_RB16(buf);

        buf += 2;

        display->y_pos = AV_RB16(buf);

        buf += 2;



        *tmp_ptr = display->next;



        display->next = ctx->display_list;

        ctx->display_list = display;

        ctx->display_list_size++;



        av_dlog(avctx, "Region %d, (%d,%d)\n", region_id, display->x_pos, display->y_pos);

    }



    while (tmp_display_list) {

        display = tmp_display_list;



        tmp_display_list = display->next;



        av_free(display);

    }



}

static int bamboo_load_device_tree(hwaddr addr,

                                     uint32_t ramsize,

                                     hwaddr initrd_base,

                                     hwaddr initrd_size,

                                     const char *kernel_cmdline)

{

    int ret = -1;

    uint32_t mem_reg_property[] = { 0, 0, cpu_to_be32(ramsize) };

    char *filename;

    int fdt_size;

    void *fdt;

    uint32_t tb_freq = 400000000;

    uint32_t clock_freq = 400000000;



    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, BINARY_DEVICE_TREE_FILE);

    if (!filename) {

        goto out;

    }

    fdt = load_device_tree(filename, &fdt_size);

    g_free(filename);

    if (fdt == NULL) {

        goto out;

    }



    /* Manipulate device tree in memory. */



    ret = qemu_devtree_setprop(fdt, "/memory", "reg", mem_reg_property,

                               sizeof(mem_reg_property));

    if (ret < 0)

        fprintf(stderr, "couldn't set /memory/reg\n");



    ret = qemu_devtree_setprop_cell(fdt, "/chosen", "linux,initrd-start",

                                    initrd_base);

    if (ret < 0)

        fprintf(stderr, "couldn't set /chosen/linux,initrd-start\n");



    ret = qemu_devtree_setprop_cell(fdt, "/chosen", "linux,initrd-end",

                                    (initrd_base + initrd_size));

    if (ret < 0)

        fprintf(stderr, "couldn't set /chosen/linux,initrd-end\n");



    ret = qemu_devtree_setprop_string(fdt, "/chosen", "bootargs",

                                      kernel_cmdline);

    if (ret < 0)

        fprintf(stderr, "couldn't set /chosen/bootargs\n");



    /* Copy data from the host device tree into the guest. Since the guest can

     * directly access the timebase without host involvement, we must expose

     * the correct frequencies. */

    if (kvm_enabled()) {

        tb_freq = kvmppc_get_tbfreq();

        clock_freq = kvmppc_get_clockfreq();

    }



    qemu_devtree_setprop_cell(fdt, "/cpus/cpu@0", "clock-frequency",

                              clock_freq);

    qemu_devtree_setprop_cell(fdt, "/cpus/cpu@0", "timebase-frequency",

                              tb_freq);



    ret = rom_add_blob_fixed(BINARY_DEVICE_TREE_FILE, fdt, fdt_size, addr);

    g_free(fdt);



out:



    return ret;

}

static int load_dtb(hwaddr addr, const struct arm_boot_info *binfo,

                    hwaddr addr_limit)

{

    void *fdt = NULL;

    int size, rc;

    uint32_t acells, scells;



    if (binfo->dtb_filename) {

        char *filename;

        filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, binfo->dtb_filename);

        if (!filename) {

            fprintf(stderr, "Couldn't open dtb file %s\n", binfo->dtb_filename);

            goto fail;

        }



        fdt = load_device_tree(filename, &size);

        if (!fdt) {

            fprintf(stderr, "Couldn't open dtb file %s\n", filename);

            g_free(filename);

            goto fail;

        }

        g_free(filename);

    } else if (binfo->get_dtb) {

        fdt = binfo->get_dtb(binfo, &size);

        if (!fdt) {

            fprintf(stderr, "Board was unable to create a dtb blob\n");

            goto fail;

        }

    }



    if (addr_limit > addr && size > (addr_limit - addr)) {

        /* Installing the device tree blob at addr would exceed addr_limit.

         * Whether this constitutes failure is up to the caller to decide,

         * so just return 0 as size, i.e., no error.

         */

        g_free(fdt);

        return 0;

    }



    acells = qemu_fdt_getprop_cell(fdt, "/", "#address-cells");

    scells = qemu_fdt_getprop_cell(fdt, "/", "#size-cells");

    if (acells == 0 || scells == 0) {

        fprintf(stderr, "dtb file invalid (#address-cells or #size-cells 0)\n");

        goto fail;

    }



    if (scells < 2 && binfo->ram_size >= (1ULL << 32)) {

        /* This is user error so deserves a friendlier error message

         * than the failure of setprop_sized_cells would provide

         */

        fprintf(stderr, "qemu: dtb file not compatible with "

                "RAM size > 4GB\n");

        goto fail;

    }



    rc = qemu_fdt_setprop_sized_cells(fdt, "/memory", "reg",

                                      acells, binfo->loader_start,

                                      scells, binfo->ram_size);

    if (rc < 0) {

        fprintf(stderr, "couldn't set /memory/reg\n");

        goto fail;

    }



    if (binfo->kernel_cmdline && *binfo->kernel_cmdline) {

        rc = qemu_fdt_setprop_string(fdt, "/chosen", "bootargs",

                                     binfo->kernel_cmdline);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/bootargs\n");

            goto fail;

        }

    }



    if (binfo->initrd_size) {

        rc = qemu_fdt_setprop_cell(fdt, "/chosen", "linux,initrd-start",

                                   binfo->initrd_start);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/linux,initrd-start\n");

            goto fail;

        }



        rc = qemu_fdt_setprop_cell(fdt, "/chosen", "linux,initrd-end",

                                   binfo->initrd_start + binfo->initrd_size);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/linux,initrd-end\n");

            goto fail;

        }

    }



    if (binfo->modify_dtb) {

        binfo->modify_dtb(binfo, fdt);

    }



    qemu_fdt_dumpdtb(fdt, size);



    /* Put the DTB into the memory map as a ROM image: this will ensure

     * the DTB is copied again upon reset, even if addr points into RAM.

     */

    rom_add_blob_fixed("dtb", fdt, size, addr);



    g_free(fdt);



    return size;



fail:

    g_free(fdt);

    return -1;

}

